## 2. `Models.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var colorHex: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = completions
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previous
        }

        return streak
    }

    var completedToday: Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completions.contains {
            calendar.isDate($0.date, inSameDayAs: today)
        }
    }

    func hasCompletion(on date: Date) -> Bool {
        let calendar = Calendar.current
        return completions.contains {
            calendar.isDate($0.date, inSameDayAs: date)
        }
    }
}

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date

    init(id: UUID = UUID(), date: Date = Date()) {
        self.id = id
        self.date = date
    }
}
```

