## 3. `ContentView.swift`

```swift
import SwiftUI
import SwiftData

struct ContentView: View {
    @Environment(\.modelContext) private var modelContext
    @Query(sort: \Habit.createdAt, order: .forward) private var habits: [Habit]

    @State private var showingAddHabit = false

    var body: some View {
        NavigationStack {
            Group {
                if habits.isEmpty {
                    ContentUnavailableView(
                        "No Habits Yet",
                        systemImage: "checklist",
                        description: Text("Tap the + button to create your first habit.")
                    )
                } else {
                    List {
                        ForEach(habits) { habit in
                            NavigationLink(destination: HabitDetailView(habit: habit)) {
                                HabitRowView(habit: habit)
                            }
                            .swipeActions(edge: .trailing) {
                                Button(role: .destructive) {
                                    deleteHabit(habit)
                                } label: {
                                    Label("Delete", systemImage: "trash")
                                }
                            }
                            .swipeActions(edge: .leading) {
                                Button {
                                    toggleToday(for: habit)
                                } label: {
                                    Label(
                                        habit.completedToday ? "Undo Today" : "Complete Today",
                                        systemImage: habit.completedToday ? "arrow.uturn.backward" : "checkmark"
                                    )
                                }
                                .tint(habit.completedToday ? .orange : .green)
                            }
                        }
                    }
                    .listStyle(.insetGrouped)
                }
            }
            .navigationTitle("Habits")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        showingAddHabit = true
                    } label: {
                        Image(systemName: "plus")
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView()
            }
        }
    }

    private func deleteHabit(_ habit: Habit) {
        modelContext.delete(habit)
        try? modelContext.save()
    }

    private func toggleToday(for habit: Habit) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            calendar.isDate($0.date, inSameDayAs: today)
        }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: today)
            habit.completions.append(completion)
            modelContext.insert(completion)
        }

        try? modelContext.save()
    }
}
```

