import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var sortedCompletions: [HabitCompletion] {
        habit.completions.sorted { $0.date > $1.date }
    }

    var body: some View {
        List {
            Section("Overview") {
                HStack {
                    Text("Name")
                    Spacer()
                    Text(habit.name)
                        .foregroundStyle(.secondary)
                }

                if !habit.habitDescription.isEmpty {
                    HStack {
                        Text("Description")
                        Spacer()
                        Text(habit.habitDescription)
                            .foregroundStyle(.secondary)
                            .multilineTextAlignment(.trailing)
                    }
                }

                HStack {
                    Text("Current Streak")
                    Spacer()
                    Text("\(habit.currentStreak)")
                        .bold()
                }

                HStack {
                    Text("Completed Today")
                    Spacer()
                    Image(systemName: habit.completedToday ? "checkmark.circle.fill" : "xmark.circle")
                        .foregroundStyle(habit.completedToday ? .green : .red)
                }
            }

            Section("Actions") {
                Button(habit.completedToday ? "Undo Today" : "Mark Today Complete") {
                    toggleToday()
                }
            }

            Section("History") {
                if sortedCompletions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(sortedCompletions) { completion in
                        HStack {
                            Image(systemName: "checkmark.circle.fill")
                                .foregroundStyle(.green)
                            Text(completion.date.formatted(date: .abbreviated, time: .omitted))
                        }
                    }
                    .onDelete(perform: deleteCompletions)
                }
            }
        }
        .navigationTitle(habit.name)
        .navigationBarTitleDisplayMode(.inline)
    }

    private func toggleToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            calendar.isDate($0.date, inSameDayAs: today)
        }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: today)
            habit.completions.append(completion)
            modelContext.insert(completion)
        }

        try? modelContext.save()
    }

    private func deleteCompletions(at offsets: IndexSet) {
        let items = sortedCompletions
        for index in offsets {
            let completion = items[index]
            modelContext.delete(completion)
        }
        try? modelContext.save()
    }
}
