# 2. `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var colorHex: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        colorHex: String = "#4CAF50",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains {
            calendar.isDate($0.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: calendar.startOfDay(for: date))
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let sortedDays = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDays.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        if !sortedDays.contains(where: { calendar.isDate($0, inSameDayAs: expectedDate) }) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: expectedDate),
                  sortedDays.contains(where: { calendar.isDate($0, inSameDayAs: yesterday) }) else {
                return 0
            }
            expectedDate = yesterday
        }

        var remaining = Set(sortedDays.map { $0.timeIntervalSince1970 })

        while remaining.contains(expectedDate.timeIntervalSince1970) {
            streak += 1
            remaining.remove(expectedDate.timeIntervalSince1970)

            guard let previous = calendar.date(byAdding: .day, value: -1, to: expectedDate) else {
                break
            }
            expectedDate = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        completions.count
    }
}
```

