# Quick improvement: cascade delete relationship

For better data integrity, you may want to explicitly define the relationship between `Habit` and `HabitCompletion`.

Replace `Habit.swift` and `HabitCompletion.swift` with this improved version:

## `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    @Attribute(.unique) var id: UUID
    var name: String
    var detail: String
    var colorHex: String
    var createdAt: Date

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        colorHex: String = "#4CAF50",
        createdAt: Date = Date()
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = []
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains {
            calendar.isDate($0.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: calendar.startOfDay(for: date), habit: self)
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Array(Set(completions.map { calendar.startOfDay(for: $0.date) }))
            .sorted(by: >)

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(where: { calendar.isDate($0, inSameDayAs: expectedDate) }) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: expectedDate),
                  uniqueDays.contains(where: { calendar.isDate($0, inSameDayAs: yesterday) }) else {
                return 0
            }
            expectedDate = yesterday
        }

        let remaining = Set(uniqueDays.map { calendar.startOfDay(for: $0) })

        while remaining.contains(expectedDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: expectedDate) else {
                break
            }
            expectedDate = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        Array(Set(completions.map { Calendar.current.startOfDay(for: $0.date) })).count
    }
}
```

