## `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var completions: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = Date(),
        completions: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completions.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completions.firstIndex(where: { calendar.isDateInToday($0) }) {
            completions.remove(at: index)
        } else {
            completions.append(Date())
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(
            completions.map { calendar.startOfDay(for: $0) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while uniqueDays.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    func totalCompletions(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(completions.map { calendar.startOfDay(for: $0) })
        return uniqueDays.count
    }
}
```

