                        .font(.caption)
                        .foregroundStyle(.green)
                }
            }

            Spacer()

            Button {
                toggleTodayCompletion()
            } label: {
                Image(systemName: isCompletedToday ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 28))
                    .foregroundStyle(isCompletedToday ? .green : .gray)
            }
            .buttonStyle(.plain)
        }
        .padding(.vertical, 6)
    }

    private var isCompletedToday: Bool {
        let calendar = Calendar.current
        return habit.completions.contains { calendar.isDateInToday($0) }
    }

    private var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(habit.completions.map { calendar.startOfDay(for: $0) })

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !normalizedDates.contains(currentDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
                  normalizedDates.contains(yesterday) else {
                return 0
            }
            currentDate = yesterday
        }

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previous
        }

        return streak
    }

    private func toggleTodayCompletion() {
        let calendar = Calendar.current

        if let existingIndex = habit.completions.firstIndex(where: { calendar.isDateInToday($0) }) {
            habit.completions.remove(at: existingIndex)
        } else {
            habit.completions.append(Date())
        }

        do {
            try modelContext.save()
        } catch {
            print("Failed to update completion: \(error)")
        }
    }
}
