```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var colorHex: String
    @Relationship(deleteRule: .cascade) var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        colorHex: String = "#4F46E5",
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completions = completions
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: calendar.startOfDay(for: date))
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let completedDays = Set(completions.map { calendar.startOfDay(for: $0.date) })
        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while completedDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        completions.count
    }
}

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date

    init(id: UUID = UUID(), date: Date) {
        self.id = id
        self.date = date
    }
}
