# 4. `Utilities/HabitStats.swift`

```swift
import Foundation

enum HabitStats {
    static func isCompletedToday(_ habit: Habit, calendar: Calendar = .current) -> Bool {
        habit.completions.contains { completion in
            calendar.isDateInToday(completion.date)
        }
    }

    static func toggleToday(for habit: Habit, calendar: Calendar = .current) {
        if let existing = habit.completions.first(where: { calendar.isDateInToday($0.date) }) {
            if let index = habit.completions.firstIndex(where: { $0.id == existing.id }) {
                habit.completions.remove(at: index)
            }
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            habit.completions.append(completion)
        }
    }

    static func currentStreak(for habit: Habit, calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(
            habit.completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    static func totalCompletions(for habit: Habit) -> Int {
        let uniqueDays = Set(habit.completions.map { Calendar.current.startOfDay(for: $0.date) })
        return uniqueDays.count
    }
}
