## Models/Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
        )

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(currentDay) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDay),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            currentDay = yesterday
        }

        while uniqueDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }

    func completedCount() -> Int {
        let uniqueDays = Set(completionDates.map { Calendar.current.startOfDay(for: $0) })
        return uniqueDays.count
    }
}
```

