# 6. Optional improved model

If you want a more scalable design, instead of storing `[Date]` directly, create a separate `HabitCompletion` model.

This is better for:
- querying
- filtering
- reporting
- avoiding duplicate same-day entries

Example:

```swift
import Foundation
import SwiftData

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date
    var habit: Habit?

    init(id: UUID = UUID(), date: Date = Date(), habit: Habit? = nil) {
        self.id = id
        self.date = date
        self.habit = habit
    }
}

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completions = completions
    }
}
```

That version is more production-friendly.

