# 2. `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completionDates = completionDates
    }
}

extension Habit {
    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        let today = calendar.startOfDay(for: Date())
        return completionDates.contains { calendar.isDate($0, inSameDayAs: today) }
    }

    func toggleToday(calendar: Calendar = .current) {
        let today = calendar.startOfDay(for: Date())

        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(completionDates.map { calendar.startOfDay(for: $0) })
        let sortedDates = normalizedDates.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        let today = calendar.startOfDay(for: Date())
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!

        var streak = 0
        var currentDate: Date

        if normalizedDates.contains(today) {
            currentDate = today
        } else if normalizedDates.contains(yesterday) {
            currentDate = yesterday
        } else {
            return 0
        }

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
            currentDate = previous
        }

        return streak
    }

    func totalCompletions(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(completionDates.map { calendar.startOfDay(for: $0) })
        return normalizedDates.count
    }
}
```

