            .tint(habit.isCompletedToday() ? .green : .accentColor)
        }
        .padding()
        .background(.thinMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 16))
    }

    private var statsCard: some View {
        HStack {
            statItem(title: "Current Streak", value: "\(habit.currentStreak())", color: .orange, icon: "flame.fill")
            Spacer()
            statItem(title: "Total Done", value: "\(habit.totalCompletions())", color: .blue, icon: "checkmark.circle.fill")
        }
        .padding()
        .background(.thinMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 16))
    }

    private func statItem(title: String, value: String, color: Color, icon: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Label(title, systemImage: icon)
                .foregroundStyle(color)
                .font(.subheadline)

            Text(value)
                .font(.largeTitle.bold())
        }
    }

    private var historyCard: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("Recent History")
                .font(.headline)

            LazyVGrid(columns: columns, spacing: 12) {
                ForEach(last30Days(), id: \.self) { date in
                    let completed = habit.completionDates.contains {
                        Calendar.current.isDate($0, inSameDayAs: date)
                    }

                    VStack(spacing: 6) {
                        Text(dayLetter(for: date))
                            .font(.caption)
                            .foregroundStyle(.secondary)

                        Circle()
                            .fill(completed ? Color.green : Color.gray.opacity(0.25))
                            .frame(width: 28, height: 28)

                        Text(dayNumber(for: date))
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .padding()
        .background(.thinMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 16))
    }

    private func last30Days() -> [Date] {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        return (0..<30).compactMap {
            calendar.date(byAdding: .day, value: -$0, to: today)
        }
        .reversed()
    }

    private func dayLetter(for date: Date) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "E"
        return String(formatter.string(from: date).prefix(1))
    }

    private func dayNumber(for date: Date) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "d"
        return formatter.string(from: date)
    }
}
