## C) Add longest streak

Update `Habit.swift`:

```swift
var longestStreak: Int {
    let calendar = Calendar.current
    let sortedDays = Array(Set(completionDates.map { calendar.startOfDay(for: $0) })).sorted()

    guard !sortedDays.isEmpty else { return 0 }

    var longest = 1
    var current = 1

    for i in 1..<sortedDays.count {
        let previous = sortedDays[i - 1]
        let currentDay = sortedDays[i]

        if let expected = calendar.date(byAdding: .day, value: 1, to: previous),
           calendar.isDate(expected, inSameDayAs: currentDay) {
            current += 1
        } else {
            current = 1
        }

        longest = max(longest, current)
    }

    return longest
}
```

