```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        let today = calendar.startOfDay(for: Date())
        return completions.contains {
            calendar.isDate($0.date, inSameDayAs: today)
        }
    }

    func toggleToday(calendar: Calendar = .current) {
        let today = calendar.startOfDay(for: Date())

        if let existing = completions.first(where: {
            calendar.isDate($0.date, inSameDayAs: today)
        }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            let completion = HabitCompletion(date: today)
            completions.append(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let days = Set(completions.map { calendar.startOfDay(for: $0.date) })
        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        while days.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }

    func totalCompletions(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(completions.map { calendar.startOfDay(for: $0.date) })
        return uniqueDays.count
    }
}
```

