import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var colorHex: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade) var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completions = completions
    }

    var sortedCompletions: [HabitCompletion] {
        completions.sorted { $0.date < $1.date }
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func markCompleted(on date: Date, calendar: Calendar = .current) {
        guard !isCompleted(on: date, calendar: calendar) else { return }
        completions.append(HabitCompletion(date: calendar.startOfDay(for: date)))
    }

    func unmarkCompleted(on date: Date, calendar: Calendar = .current) {
        completions.removeAll { completion in
            calendar.isDate(completion.date, inSameDayAs: date)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let completionDates = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while completionDates.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    func totalCompletions() -> Int {
        completions.count
    }
}
