    @ViewBuilder
    private func statRow(title: String, value: String) -> some View {
        HStack {
            Text(title)
            Spacer()
            Text(value)
                .foregroundStyle(.secondary)
        }
    }

    private func deleteCompletion(at offsets: IndexSet) {
        let reversed = habit.sortedCompletions.reversed()
        let items = Array(reversed)

        for index in offsets {
            let completion = items[index]
            modelContext.delete(completion)
        }

        try? modelContext.save()
    }

    private func colorFromHex(_ hex: String) -> Color {
        switch hex {
        case "#EF4444": return .red
        case "#F59E0B": return .orange
        case "#10B981": return .green
        case "#3B82F6": return .blue
        case "#8B5CF6": return .purple
        default: return .indigo
        }
    }
