# 3. Streak utility

## `Utils/StreakCalculator.swift`

```swift
import Foundation

enum StreakCalculator {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let grouped = Dictionary(grouping: habit.completions) {
            calendar.startOfDay(for: $0.date)
        }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        while true {
            let totalCount = grouped[currentDate]?.reduce(0, { $0 + $1.count }) ?? 0
            if totalCount >= habit.targetPerDay {
                streak += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                    break
                }
                currentDate = previousDay
            } else {
                break
            }
        }

        return streak
    }

    static func completedToday(for habit: Habit) -> Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let total = habit.completions
            .filter { calendar.isDate($0.date, inSameDayAs: today) }
            .reduce(0) { $0 + $1.count }

        return total >= habit.targetPerDay
    }

    static func countToday(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return habit.completions
            .filter { calendar.isDate($0.date, inSameDayAs: today) }
            .reduce(0) { $0 + $1.count }
    }
}
```

