                        Text(isCompleted ? "Completed Today" : "Mark Progress")
                    }
                    .frame(maxWidth: .infinity)
                    .padding()
                    .background(isCompleted ? Color.green : colorFromHex(habit.colorHex))
                    .foregroundStyle(.white)
                    .clipShape(RoundedRectangle(cornerRadius: 14))
