                        }
                    }
                }
            }
            .padding()
        }
        .navigationTitle("Habit Details")
        .navigationBarTitleDisplayMode(.inline)
    }

    private func incrementToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let existing = habit.completions.first(where: { calendar.isDate($0.date, inSameDayAs: today) }) {
            existing.count += 1
        } else {
            let completion = HabitCompletion(date: today, count: 1, habit: habit)
            habit.completions.append(completion)
            modelContext.insert(completion)
        }

        do {
            try modelContext.save()
        } catch {
            print("Failed to save completion: \(error)")
        }
    }

    private func sortedCompletions() -> [HabitCompletion] {
        habit.completions.sorted { $0.date > $1.date }
    }

    private func colorFromHex(_ hex: String) -> Color {
        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
