import SwiftUI
import SwiftData

struct AddEditHabitView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext

    var habitToEdit: Habit?

    @State private var name: String = ""
    @State private var habitDescription: String = ""
    @State private var colorHex: String = "#4F46E5"
    @State private var targetPerDay: Int = 1

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit Info") {
                    TextField("Name", text: $name)
                    TextField("Description", text: $habitDescription)
                    TextField("Color Hex", text: $colorHex)
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                    Stepper("Target Per Day: \(targetPerDay)", value: $targetPerDay, in: 1...20)
                }
            }
            .navigationTitle(habitToEdit == nil ? "New Habit" : "Edit Habit")
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    Button("Cancel") {
                        dismiss()
                    }
                }

                ToolbarItem(placement: .topBarTrailing) {
                    Button("Save") {
                        saveHabit()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            .onAppear {
                if let habit = habitToEdit {
                    name = habit.name
                    habitDescription = habit.habitDescription
                    colorHex = habit.colorHex
                    targetPerDay = habit.targetPerDay
                }
            }
        }
    }

    private func saveHabit() {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)

        if let habit = habitToEdit {
            habit.name = trimmedName
            habit.habitDescription = habitDescription
            habit.colorHex = colorHex
            habit.targetPerDay = max(1, targetPerDay)
        } else {
            let newHabit = Habit(
                name: trimmedName,
                habitDescription: habitDescription,
                colorHex: colorHex,
                targetPerDay: targetPerDay
            )
            modelContext.insert(newHabit)
        }

        do {
            try modelContext.save()
            dismiss()
        } catch {
            print("Failed to save habit: \(error)")
        }
    }
}
