# 5. Habit Row View

## `Views/HabitRowView.swift`

```swift
import SwiftUI
import SwiftData

struct HabitRowView: View {
    @Environment(\.modelContext) private var modelContext
    let habit: Habit

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                VStack(alignment: .leading, spacing: 4) {
                    Text(habit.name)
                        .font(.headline)

                    if !habit.habitDescription.isEmpty {
                        Text(habit.habitDescription)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                }

                Spacer()

                Button {
                    toggleTodayCompletion()
                } label: {
                    Image(systemName: isCompletedToday ? "checkmark.circle.fill" : "circle")
                        .font(.title2)
                        .foregroundStyle(isCompletedToday ? .green : .gray)
                }
                .buttonStyle(.plain)
            }

            HStack {
                Label("Streak: \(currentStreak)", systemImage: "flame.fill")
                    .foregroundStyle(.orange)

                Spacer()

                Label("\(weeklyCompletionCount)/\(habit.targetPerWeek) this week", systemImage: "chart.bar.fill")
                    .foregroundStyle(.blue)
            }
            .font(.caption)
        }
        .padding(.vertical, 6)
    }

    private var isCompletedToday: Bool {
        habit.completions.contains { $0.date.isSameDay(as: .now) }
    }

    private var weeklyCompletionCount: Int {
        let start = Date().weekStart
        return habit.completions.filter { $0.date >= start }.count
    }

    private var currentStreak: Int {
        let calendar = Calendar.current
        let completionDays = Set(habit.completions.map { $0.date.startOfDay })

        var streak = 0
        var currentDate = Date().startOfDay

        while completionDays.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    private func toggleTodayCompletion() {
        let today = Date().startOfDay

        if let existing = habit.completions.first(where: { $0.date == today }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: today, habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }

        do {
            try modelContext.save()
        } catch {
            print("Failed to toggle completion: \(error)")
        }
    }
}
```

