import Foundation
import SwiftData

@MainActor
final class HabitStore: ObservableObject {
    func addHabit(name: String, description: String, context: ModelContext) {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedDescription = description.trimmingCharacters(in: .whitespacesAndNewlines)

        guard !trimmedName.isEmpty else { return }

        let habit = Habit(
            name: trimmedName,
            habitDescription: trimmedDescription
        )

        context.insert(habit)
        try? context.save()
    }

    func deleteHabits(at offsets: IndexSet, from habits: [Habit], context: ModelContext) {
        for index in offsets {
            context.delete(habits[index])
        }
        try? context.save()
    }

    func toggleToday(for habit: Habit, context: ModelContext) {
        if habit.isCompletedToday() {
            habit.unmarkCompletedToday()
        } else {
            habit.markCompletedToday()
        }

        try? context.save()
    }
}
