# 2. Models/Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var isCompletedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completionDates.map { calendar.startOfDay(for: $0) })
        let sortedDays = uniqueDays.sorted(by: >)

        guard !sortedDays.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        if !calendar.isDate(sortedDays[0], inSameDayAs: expectedDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: expectedDate),
                  calendar.isDate(sortedDays[0], inSameDayAs: yesterday) else {
                return 0
            }
            expectedDate = yesterday
        }

        for day in sortedDays {
            if calendar.isDate(day, inSameDayAs: expectedDate) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previous
            } else {
                break
            }
        }

        return streak
    }

    func toggleTodayCompletion() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
```

