# 2. `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completedDates: [Date]
    var colorHex: String

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = [],
        colorHex: String = "#4F46E5"
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completedDates = completedDates
        self.colorHex = colorHex
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completedDates.contains { calendar.isDateInToday($0) }
    }

    func markCompletedToday(calendar: Calendar = .current) {
        guard !isCompletedToday(calendar: calendar) else { return }
        completedDates.append(Date())
    }

    func unmarkCompletedToday(calendar: Calendar = .current) {
        completedDates.removeAll { calendar.isDateInToday($0) }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let normalized = Set(completedDates.map { calendar.startOfDay(for: $0) })
        guard !normalized.isEmpty else { return 0 }

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        if !normalized.contains(day) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: day),
                  normalized.contains(yesterday) else {
                return 0
            }
            day = yesterday
        }

        while normalized.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        let calendar = Calendar.current
        let normalized = Set(completedDates.map { calendar.startOfDay(for: $0) })
        return normalized.count
    }
}
```

