# 3. `Utils/HabitLogic.swift`

```swift
import Foundation

enum HabitLogic {
    static let calendar = Calendar.current

    static func normalized(_ date: Date) -> Date {
        calendar.startOfDay(for: date)
    }

    static func isCompletedToday(_ habit: Habit) -> Bool {
        let today = normalized(Date())
        return habit.completionDates.contains { calendar.isDate($0, inSameDayAs: today) }
    }

    static func toggleToday(for habit: Habit) {
        let today = normalized(Date())

        if let index = habit.completionDates.firstIndex(where: {
            calendar.isDate($0, inSameDayAs: today)
        }) {
            habit.completionDates.remove(at: index)
        } else {
            habit.completionDates.append(today)
        }
    }

    static func currentStreak(for habit: Habit) -> Int {
        let uniqueDays = Set(habit.completionDates.map { normalized($0) })
        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var day = normalized(Date())

        while uniqueDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else {
                break
            }
            day = previous
        }

        return streak
    }

    static func totalCompletions(for habit: Habit) -> Int {
        Set(habit.completionDates.map { normalized($0) }).count
    }
}
