## 2. `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completedDates: [Date]
    var colorHex: String

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = [],
        colorHex: String = "#4F46E5"
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completedDates = completedDates
        self.colorHex = colorHex
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    func toggleCompletion(for date: Date = Date()) {
        let calendar = Calendar.current

        if let index = completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: date) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(date)
        }
    }

    func currentStreak(referenceDate: Date = Date()) -> Int {
        let calendar = Calendar.current
        let normalizedDates = Set(completedDates.map { calendar.startOfDay(for: $0) })

        var streak = 0
        var date = calendar.startOfDay(for: referenceDate)

        if !normalizedDates.contains(date) {
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: date),
                  normalizedDates.contains(previousDay) else {
                return 0
            }
            date = previousDay
        }

        while normalizedDates.contains(date) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else { break }
            date = previous
        }

        return streak
    }
}
```

