# 2. Models/Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func markCompletedToday(calendar: Calendar = .current) {
        guard !isCompletedToday(calendar: calendar) else { return }
        completionDates.append(Date())
    }

    func unmarkCompletedToday(calendar: Calendar = .current) {
        completionDates.removeAll { calendar.isDateInToday($0) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completionDates.map { calendar.startOfDay(for: $0) })
        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(day) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: day),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            day = yesterday
        }

        while uniqueDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }

        return streak
    }

    var totalCompletions: Int {
        let calendar = Calendar.current
        return Set(completionDates.map { calendar.startOfDay(for: $0) }).count
    }
}
```

