# 3. ViewModels/HabitStats.swift

```swift
import Foundation

struct HabitStats {
    static func completionRate(for habit: Habit, inLast days: Int) -> Double {
        guard days > 0 else { return 0 }
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        let validDays = Set(habit.completionDates.map { calendar.startOfDay(for: $0) })
        var completed = 0

        for offset in 0..<days {
            if let date = calendar.date(byAdding: .day, value: -offset, to: today),
               validDays.contains(date) {
                completed += 1
            }
        }

        return Double(completed) / Double(days)
    }
}
