# 3. SwiftData models

## `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetFrequencyRaw: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        colorHex: String = "#4F46E5",
        targetFrequencyRaw: String = HabitFrequency.daily.rawValue
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.targetFrequencyRaw = targetFrequencyRaw
    }

    var targetFrequency: HabitFrequency {
        HabitFrequency(rawValue: targetFrequencyRaw) ?? .daily
    }

    var isCompletedToday: Bool {
        completions.contains { Calendar.current.isDateInToday($0.date) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let completionDays = Set(
            completions.map { calendar.startOfDay(for: $0.date) }
        )

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !completionDays.contains(currentDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
                  completionDays.contains(yesterday) else {
                return 0
            }
            currentDate = yesterday
        }

        while completionDays.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    var totalCompletions: Int {
        completions.count
    }
}

enum HabitFrequency: String, CaseIterable, Identifiable, Codable {
    case daily = "Daily"
    case weekly = "Weekly"

    var id: String { rawValue }
}
```

