        VStack(alignment: .leading, spacing: 8) {
            Text("Today")
                .font(.headline)

            Text("\(completedTodayCount) of \(habits.count) completed")
                .font(.title2.bold())

            ProgressView(
                value: habits.isEmpty ? 0 : Double(completedTodayCount),
                total: habits.isEmpty ? 1 : Double(habits.count)
            )
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding()
        .background(.indigo.opacity(0.1))
        .clipShape(RoundedRectangle(cornerRadius: 16))
    }

    private func deleteHabit(_ habit: Habit) {
        modelContext.delete(habit)
        try? modelContext.save()
    }

    private func toggleTodayCompletion(for habit: Habit) {
        let calendar = Calendar.current

        if let existing = habit.completions.first(where: { calendar.isDateInToday($0.date) }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: .now, habit: habit)
            modelContext.insert(completion)
            habit.completions.append(completion)
        }

        try? modelContext.save()
    }
}
