# 2. `Models/Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completedDates.contains { calendar.isDateInToday($0) }
    }

    func streak(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(
            completedDates.map { calendar.startOfDay(for: $0) }
        )

        var streakCount = 0
        var currentDate = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDate) {
            streakCount += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streakCount
    }
}
```

