# 2. Data Model

## `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    var completedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    func toggleCompletionForToday() {
        let calendar = Calendar.current

        if let index = completedDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let normalizedDates = Set(completedDates.map { calendar.startOfDay(for: $0) })

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        if !normalizedDates.contains(currentDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
                  normalizedDates.contains(yesterday) else {
                return 0
            }
            currentDate = yesterday
        }

        while normalizedDates.contains(currentDate) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDay
        }

        return streak
    }

    var totalCompletions: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completedDates.map { calendar.startOfDay(for: $0) })
        return uniqueDays.count
    }
}
```

