# 9. Streak calculation helper

Create a helper file.

## `HabitStats.swift`

```swift
import Foundation

enum HabitStats {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current

        let uniqueDays = Set(
            habit.completions.map { calendar.startOfDay(for: $0) }
        )

        guard !uniqueDays.isEmpty else { return 0 }

        let sortedDays = uniqueDays.sorted(by: >)
        let today = calendar.startOfDay(for: Date())
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!

        guard sortedDays[0] == today || sortedDays[0] == yesterday else {
            return 0
        }

        var streak = 0
        var currentDay = sortedDays[0]

        while uniqueDays.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }
}
```

