# 8. Streak Utility

You referenced `HabitStats.currentStreak(for:)`, so here is that helper.

## `HabitStats.swift`

```swift
import Foundation

enum HabitStats {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current

        let uniqueDays = Set(
            habit.completions.map { calendar.startOfDay(for: $0.date) }
        )

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var date = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(date) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: date),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            date = yesterday
        }

        while uniqueDays.contains(date) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else {
                break
            }
            date = previous
        }

        return streak
    }
}
```

