```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completedDates.contains { calendar.isDateInToday($0) }
    }

    func streak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(completedDates.map { calendar.startOfDay(for: $0) })
        guard !uniqueDays.isEmpty else { return 0 }

        var streakCount = 0
        var currentDay = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(currentDay) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDay),
                  uniqueDays.contains(yesterday) else {
                return 0
            }
            currentDay = yesterday
        }

        while uniqueDays.contains(currentDay) {
            streakCount += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streakCount
    }
}
