# 2. Models/Habit.swift

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var normalizedCompletionDates: [Date] {
        let calendar = Calendar.current
        let normalized = completionDates.map { calendar.startOfDay(for: $0) }
        return Array(Set(normalized)).sorted()
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return normalizedCompletionDates.contains(today)
    }

    func toggleToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if isCompletedToday() {
            completionDates.removeAll {
                calendar.isDate($0, inSameDayAs: today)
            }
        } else {
            completionDates.append(today)
        }
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        let dates = normalizedCompletionDates.sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        if !calendar.isDate(dates[0], inSameDayAs: expectedDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: expectedDate),
                  calendar.isDate(dates[0], inSameDayAs: yesterday) else {
                return 0
            }
            expectedDate = yesterday
        }

        for date in dates {
            if calendar.isDate(date, inSameDayAs: expectedDate) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previous
            } else if date < expectedDate {
                break
            }
        }

        return streak
    }

    func totalCompletions() -> Int {
        normalizedCompletionDates.count
    }
}
```

