# Optional Improved Model

If you want a more scalable data model, use a separate completion record instead of `[Date]` on the habit. For example:

```swift
@Model
final class HabitCompletion {
    var date: Date
    var habit: Habit?

    init(date: Date = Date(), habit: Habit? = nil) {
        self.date = date
        self.habit = habit
    }
}
```

Then relate it to `Habit`:

```swift
@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(id: UUID = UUID(), name: String, details: String = "", createdAt: Date = Date()) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.completions = []
    }
}
```

This is better if you plan to support:

- notes per completion
- partial completion
