## 3. `HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            save()
        }
    }

    private let habitsKey = "habits_storage_key"

    init() {
        load()
    }

    func addHabit(name: String) {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }

        let habit = Habit(name: trimmed)
        habits.append(habit)
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleTodayCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let calendar = Calendar.current

        if habits[index].isCompletedToday(calendar: calendar) {
            habits[index].completedDates.removeAll { calendar.isDateInToday($0) }
        } else {
            habits[index].completedDates.append(Date())
        }
    }

    private func save() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: habitsKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func load() {
        guard let data = UserDefaults.standard.data(forKey: habitsKey) else { return }

        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
        }
    }
}
```

