import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, createdAt: Date = Date(), completedDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday() {
        let calendar = Calendar.current

        if let index = completedDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let normalizedDates = completedDates.map { calendar.startOfDay(for: $0) }
        let uniqueDates = Array(Set(normalizedDates)).sorted(by: >)

        guard !uniqueDates.isEmpty else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        for date in uniqueDates {
            if calendar.isDate(date, inSameDayAs: currentDate) {
                streak += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previousDay
            } else if date < currentDate {
                break
            }
        }

        return streak
    }
}
