import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completionDates: [Date]

    init(name: String, createdAt: Date = Date(), completionDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
