        var streak = 0
        var date = calendar.startOfDay(for: Date())

        while uniqueDays.contains(date) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else {
                break
            }
            date = previous
        }

        return streak
    }
}
