import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var createdAt: Date
    var completionDates: [Date]

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.createdAt = Date()
        self.completionDates = []
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func streak(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(
            completionDates.map { calendar.startOfDay(for: $0) }
        )

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previousDay
        }

        return streak
    }
}
