# 9. Repository

`data/repository/BankingRepository.kt`

```kotlin
package com.example.securebank.data.repository

import com.example.securebank.data.api.BankingApi
import com.example.securebank.data.model.Account
import com.example.securebank.data.model.LoginRequest
import com.example.securebank.data.model.Transaction
import com.example.securebank.data.security.SecureTokenStorage
import javax.inject.Inject

class BankingRepository @Inject constructor(
    private val api: BankingApi,
    private val tokenStorage: SecureTokenStorage
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return try {
            val response = api.login(LoginRequest(username, password))
            tokenStorage.saveAccessToken(response.accessToken)
            tokenStorage.saveRefreshToken(response.refreshToken)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return try {
            Result.success(api.getAccounts())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(accountId: String): Result<List<Transaction>> {
        return try {
            Result.success(api.getTransactions(accountId))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        tokenStorage.clear()
    }
}
