package com.example.securebank.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.securebank.data.model.AccountSummary
import com.example.securebank.data.model.Transaction
import com.example.securebank.data.repository.AccountRepository
import com.example.securebank.data.repository.AuthRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

data class DashboardUiState(
    val isLoading: Boolean = false,
    val accountSummary: AccountSummary? = null,
    val transactions: List<Transaction> = emptyList(),
    val error: String? = null
)

@HiltViewModel
class DashboardViewModel @Inject constructor(
    private val authRepository: AuthRepository,
    private val accountRepository: AccountRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(DashboardUiState())
    val uiState: StateFlow<DashboardUiState> = _uiState

    fun loadDashboard() {
        val token = authRepository.getToken()
        if (token == null) {
            _uiState.value = _uiState.value.copy(error = "User not authenticated")
            return
        }

        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)

            val summaryResult = accountRepository.getAccountSummary(token)
            val txResult = accountRepository.getTransactions(token)

            _uiState.value = if (summaryResult.isSuccess && txResult.isSuccess) {
                _uiState.value.copy(
                    isLoading = false,
                    accountSummary = summaryResult.getOrNull(),
                    transactions = txResult.getOrDefault(emptyList())
                )
            } else {
                _uiState.value.copy(
                    isLoading = false,
                    error = summaryResult.exceptionOrNull()?.message
                        ?: txResult.exceptionOrNull()?.message
                        ?: "Failed to load dashboard"
                )
            }
        }
    }
}
