import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

sealed class AccountsUiState {
    data object Loading : AccountsUiState()
    data class Success(val accounts: List<Account>) : AccountsUiState()
    data class Error(val message: String) : AccountsUiState()
}

class AccountsViewModel(
    private val api: BankingApi,
    private val tokenStore: AuthTokenStore
) : ViewModel() {

    private val _uiState = MutableStateFlow<AccountsUiState>(AccountsUiState.Loading)
    val uiState: StateFlow<AccountsUiState> = _uiState

    fun loadAccounts() {
        viewModelScope.launch {
            _uiState.value = AccountsUiState.Loading
            try {
                val token = tokenStore.getToken()
                if (token.isNullOrBlank()) {
                    _uiState.value = AccountsUiState.Error("Not authenticated")
                    return@launch
                }

                val accounts = api.getAccounts("Bearer $token")
                _uiState.value = AccountsUiState.Success(accounts)
            } catch (e: Exception) {
                _uiState.value = AccountsUiState.Error("Failed to load accounts")
            }
        }
    }
}
