package com.example.securebank.data.repository

import com.example.securebank.data.local.SecurePrefs
import com.example.securebank.data.model.Account
import com.example.securebank.data.model.Transaction
import com.example.securebank.data.model.User
import com.example.securebank.data.remote.ApiService
import com.example.securebank.data.remote.LoginRequest
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankingRepository @Inject constructor(
    private val apiService: ApiService,
    private val securePrefs: SecurePrefs
) {
    suspend fun login(username: String, password: String): Result<User> {
        return try {
            val user = apiService.login(LoginRequest(username, password))
            securePrefs.saveToken(user.token)
            Result.success(user)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return try {
            Result.success(apiService.getAccounts())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(): Result<List<Transaction>> {
        return try {
            Result.success(apiService.getTransactions())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun isLoggedIn(): Boolean = !securePrefs.getToken().isNullOrBlank()

    fun logout() = securePrefs.clearSession()
}
