@Composable
fun NavGraph() {
    val navController = rememberNavController()
    val authViewModel: AuthViewModel = hiltViewModel()
    val dashboardViewModel: DashboardViewModel = hiltViewModel()

    val authState by authViewModel.authState.collectAsState()
    val accounts by dashboardViewModel.accounts.collectAsState()
    val transactions by dashboardViewModel.transactions.collectAsState()

    NavHost(navController = navController, startDestination = "login") {
        composable("login") {
            LoginScreen(
                authState = authState,
                onLogin = { username, password ->
                    authViewModel.login(username, password)
                }
            )

            if (authState is AuthState.Authenticated) {
                dashboardViewModel.loadData()
                navController.navigate("dashboard") {
                    popUpTo("login") { inclusive = true }
                }
            }
        }

        composable("dashboard") {
            DashboardScreen(accounts = accounts)
        }

        composable("transactions") {
            TransactionsScreen(transactions = transactions)
        }
    }
