# 8) Repository

## `data/repository/BankRepository.kt`

```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.remote.BankingApi
import com.example.bankapp.data.remote.LoginRequest
import com.example.bankapp.domain.model.Account
import com.example.bankapp.domain.model.Transaction
import com.example.bankapp.security.SecurePrefs
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor(
    private val api: BankingApi,
    private val securePrefs: SecurePrefs
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return runCatching {
            val response = api.login(LoginRequest(username, password))
            securePrefs.saveTokens(response.accessToken, response.refreshToken)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return runCatching {
            api.getAccounts().map {
                Account(
                    id = it.id,
                    name = it.name,
                    accountNumberMasked = it.accountNumberMasked,
                    balance = it.balance,
                    currency = it.currency
                )
            }
        }
    }

    suspend fun getTransactions(accountId: String): Result<List<Transaction>> {
        return runCatching {
            api.getTransactions(accountId).map {
                Transaction(
                    id = it.id,
                    description = it.description,
                    amount = it.amount,
                    date = it.date,
                    type = it.type
                )
            }
        }
    }

    fun logout() {
        securePrefs.clear()
    }
}
