```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.local.SecurePrefs
import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.remote.ApiService
import com.example.bankapp.data.remote.LoginRequest
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor(
    private val apiService: ApiService,
    private val securePrefs: SecurePrefs
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return try {
            val user = apiService.login(LoginRequest(username, password))
            securePrefs.saveToken(user.token)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return try {
            Result.success(apiService.getAccounts())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(): Result<List<Transaction>> {
        return try {
            Result.success(apiService.getTransactions())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        securePrefs.clear()
    }
}
