data class DashboardUiState(
    val accounts: List<Account> = emptyList(),
    val transactions: List<Transaction> = emptyList(),
    val isLoading: Boolean = false,
    val error: String? = null
)

@HiltViewModel
class DashboardViewModel @Inject constructor(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(DashboardUiState())
    val uiState: StateFlow<DashboardUiState> = _uiState

    fun loadData() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)

            val accountsResult = repository.getAccounts()
            val transactionsResult = repository.getTransactions()

            _uiState.value = if (accountsResult.isSuccess && transactionsResult.isSuccess) {
                DashboardUiState(
                    accounts = accountsResult.getOrDefault(emptyList()),
                    transactions = transactionsResult.getOrDefault(emptyList()),
                    isLoading = false
                )
            } else {
                DashboardUiState(
                    isLoading = false,
                    error = "Failed to load dashboard data"
                )
            }
        }
    }
