## `data/remote/BankApi.kt`

```kotlin
package com.example.bankapp.data.remote

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.LoginRequest
import com.example.bankapp.data.model.LoginResponse
import com.example.bankapp.data.model.Transaction
import retrofit2.http.Body
import retrofit2.http.GET
import retrofit2.http.Header
import retrofit2.http.POST

interface BankApi {

    @POST("login")
    suspend fun login(
        @Body request: LoginRequest
    ): LoginResponse

    @GET("accounts")
    suspend fun getAccounts(
        @Header("Authorization") token: String
    ): List<Account>

    @GET("transactions")
    suspend fun getTransactions(
        @Header("Authorization") token: String
    ): List<Transaction>
}
