# 8. Repository

## `data/repository/BankRepository.kt`

```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.LoginRequest
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.remote.BankApi
import com.example.bankapp.util.SessionManager
import javax.inject.Inject

class BankRepository @Inject constructor(
    private val api: BankApi,
    private val sessionManager: SessionManager
) {
    suspend fun login(username: String, password: String): Result<String> {
        return try {
            val response = api.login(LoginRequest(username, password))
            sessionManager.saveToken(response.token)
            Result.success(response.customerName)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<List<Account>> {
        return try {
            val token = sessionManager.getToken().orEmpty()
            val accounts = api.getAccounts("Bearer $token")
            Result.success(accounts)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(): Result<List<Transaction>> {
        return try {
            val token = sessionManager.getToken().orEmpty()
            val transactions = api.getTransactions("Bearer $token")
            Result.success(transactions)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        sessionManager.clearSession()
    }
}
```

