package com.example.bankapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.compose.*
import com.example.bankapp.ui.screen.DashboardScreen
import com.example.bankapp.ui.screen.LoginScreen
import com.example.bankapp.ui.screen.TransactionsScreen
import com.example.bankapp.ui.viewmodel.DashboardViewModel
import com.example.bankapp.ui.viewmodel.LoginViewModel
import com.example.bankapp.ui.viewmodel.TransactionsViewModel

@Composable
fun AppNavGraph() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = "login"
    ) {
        composable("login") {
            val viewModel: LoginViewModel = hiltViewModel()
            LoginScreen(
                viewModel = viewModel,
                onLoginSuccess = {
                    navController.navigate("dashboard") {
                        popUpTo("login") { inclusive = true }
                    }
                }
            )
        }

        composable("dashboard") {
            val viewModel: DashboardViewModel = hiltViewModel()
            DashboardScreen(
                viewModel = viewModel,
                onTransactionsClick = {
                    navController.navigate("transactions")
                },
                onLogout = {
                    viewModel.logout()
                    navController.navigate("login") {
                        popUpTo("dashboard") { inclusive = true }
                    }
                }
            )
        }

        composable("transactions") {
            val viewModel: TransactionsViewModel = hiltViewModel()
            TransactionsScreen(viewModel = viewModel)
        }
    }
}
