```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.local.SecurePrefs
import com.example.bankapp.data.remote.ApiService
import com.example.bankapp.data.remote.models.LoginRequest
import com.example.bankapp.util.Resource
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class AuthRepository @Inject constructor(
    private val apiService: ApiService,
    private val securePrefs: SecurePrefs
) {
    suspend fun login(username: String, password: String): Resource<Unit> {
        return try {
            val response = apiService.login(LoginRequest(username, password))
            if (response.isSuccessful) {
                val body = response.body()
                if (body != null) {
                    securePrefs.saveAccessToken(body.accessToken)
                    securePrefs.saveRefreshToken(body.refreshToken)
                    Resource.Success(Unit)
                } else {
                    Resource.Error("Empty server response")
                }
            } else {
                Resource.Error("Login failed: ${response.code()}")
            }
        } catch (e: Exception) {
            Resource.Error("Network error: ${e.message}")
        }
    }

    fun logout() {
        securePrefs.clearAll()
    }

    fun isLoggedIn(): Boolean = !securePrefs.getAccessToken().isNullOrBlank()
}
