package com.example.bankapp.ui.navigation

import androidx.biometric.BiometricPrompt
import androidx.compose.runtime.Composable
import androidx.compose.ui.platform.LocalContext
import androidx.fragment.app.FragmentActivity
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavType
import androidx.navigation.compose.*
import androidx.navigation.navArgument
import com.example.bankapp.ui.screens.dashboard.DashboardScreen
import com.example.bankapp.ui.screens.dashboard.DashboardViewModel
import com.example.bankapp.ui.screens.login.LoginScreen
import com.example.bankapp.ui.screens.login.LoginViewModel
import com.example.bankapp.ui.screens.transactions.TransactionsScreen
import com.example.bankapp.ui.screens.transactions.TransactionsViewModel
import java.util.concurrent.Executor
import androidx.core.content.ContextCompat

@Composable
fun BankNavGraph(
    startDestination: String = "login"
) {
    val navController = rememberNavController()

    NavHost(navController = navController, startDestination = startDestination) {
        composable("login") {
            val vm: LoginViewModel = hiltViewModel()
            val context = LocalContext.current
            val activity = context as FragmentActivity

            LoginScreen(
                viewModel = vm,
                onLoginSuccess = {
                    navController.navigate("dashboard") {
                        popUpTo("login") { inclusive = true }
                    }
                },
                onBiometricLogin = {
                    showBiometricPrompt(
                        activity = activity,
                        onSuccess = {
                            navController.navigate("dashboard") {
                                popUpTo("login") { inclusive = true }
                            }
                        }
                    )
                }
            )
        }

        composable("dashboard") {
            val vm: DashboardViewModel = hiltViewModel()
            DashboardScreen(
                viewModel = vm,
                onAccountClick = { accountId ->
                    navController.navigate("transactions/$accountId")
                }
            )
        }

        composable(
            route = "transactions/{accountId}",
            arguments = listOf(navArgument("accountId") { type = NavType.StringType })
        ) {
            val vm: TransactionsViewModel = hiltViewModel()
            TransactionsScreen(viewModel = vm)
        }
    }
}

private fun showBiometricPrompt(
    activity: FragmentActivity,
    onSuccess: () -> Unit
) {
    val executor: Executor = ContextCompat.getMainExecutor(activity)

    val promptInfo = BiometricPrompt.PromptInfo.Builder()
        .setTitle("Biometric Login")
        .setSubtitle("Authenticate to access your banking app")
        .setNegativeButtonText("Cancel")
        .build()

    val biometricPrompt = BiometricPrompt(
        activity,
        executor,
        object : BiometricPrompt.AuthenticationCallback() {
            override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {
                super.onAuthenticationSucceeded(result)
                onSuccess()
            }
        }
    )

    biometricPrompt.authenticate(promptInfo)
}
