# 5. Repository

## `data/repository/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.data.model.User
import kotlinx.coroutines.delay

class BankingRepository {

    private var loggedIn = false

    private val fakeUser = User(
        id = "u1",
        fullName = "Alex Johnson",
        email = "alex@example.com"
    )

    private var fakeAccount = Account(
        id = "a1",
        accountName = "Primary Checking",
        accountNumberMasked = "**** 4821",
        balance = 5240.75,
        currency = "USD"
    )

    private val fakeTransactions = mutableListOf(
        Transaction("t1", "Coffee Shop", "2026-09-10", -5.75, TransactionType.DEBIT),
        Transaction("t2", "Salary", "2026-09-09", 2500.00, TransactionType.CREDIT),
        Transaction("t3", "Grocery Store", "2026-09-08", -82.14, TransactionType.DEBIT),
        Transaction("t4", "Electric Bill", "2026-09-07", -120.00, TransactionType.DEBIT),
        Transaction("t5", "Transfer In", "2026-09-06", 300.00, TransactionType.CREDIT)
    )

    suspend fun login(username: String, password: String): Result<User> {
        delay(800)
        return if (username == "demo" && password == "password") {
            loggedIn = true
            Result.success(fakeUser)
        } else {
            Result.failure(Exception("Invalid username or password"))
        }
    }

    fun isLoggedIn(): Boolean = loggedIn

    fun getUser(): User = fakeUser

    fun getAccount(): Account = fakeAccount

    fun getTransactions(): List<Transaction> = fakeTransactions.toList()

    suspend fun transfer(toAccount: String, amount: Double): Result<Unit> {
        delay(1000)

        if (toAccount.isBlank()) {
            return Result.failure(Exception("Destination account is required"))
        }

        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        if (amount > fakeAccount.balance) {
            return Result.failure(Exception("Insufficient funds"))
        }

        fakeAccount = fakeAccount.copy(balance = fakeAccount.balance - amount)

        fakeTransactions.add(
            0,
            Transaction(
                id = "t${fakeTransactions.size + 1}",
                title = "Transfer to $toAccount",
                date = "2026-09-16",
                amount = -amount,
                type = TransactionType.DEBIT
            )
        )

        return Result.success(Unit)
    }
}
```

