# 3) Repository

## `data/repository/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import kotlinx.coroutines.delay

class BankingRepository {

    private val accounts = mutableListOf(
        Account(
            id = "1",
            name = "Checking Account",
            numberMasked = "**** 1234",
            balance = 2450.75,
            currency = "USD"
        ),
        Account(
            id = "2",
            name = "Savings Account",
            numberMasked = "**** 5678",
            balance = 10420.10,
            currency = "USD"
        )
    )

    private val transactions = mutableListOf(
        Transaction("t1", "1", "Coffee Shop", -5.75, "2026-09-10", TransactionType.DEBIT),
        Transaction("t2", "1", "Payroll", 1800.00, "2026-09-09", TransactionType.CREDIT),
        Transaction("t3", "1", "Grocery Store", -82.40, "2026-09-08", TransactionType.DEBIT),
        Transaction("t4", "2", "Interest Payment", 12.50, "2026-09-01", TransactionType.CREDIT)
    )

    suspend fun login(username: String, password: String): Boolean {
        delay(800)
        return username == "user" && password == "password"
    }

    suspend fun getAccounts(): List<Account> {
        delay(300)
        return accounts.toList()
    }

    suspend fun getTransactions(accountId: String): List<Transaction> {
        delay(300)
        return transactions.filter { it.accountId == accountId }
    }

    suspend fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        delay(500)

        if (amount <= 0) return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        if (fromAccountId == toAccountId) return Result.failure(IllegalArgumentException("Accounts must be different"))

        val from = accounts.find { it.id == fromAccountId }
        val to = accounts.find { it.id == toAccountId }

        if (from == null || to == null) {
            return Result.failure(IllegalArgumentException("Account not found"))
        }

        if (from.balance < amount) {
            return Result.failure(IllegalStateException("Insufficient funds"))
        }

        val fromIndex = accounts.indexOf(from)
        val toIndex = accounts.indexOf(to)

        accounts[fromIndex] = from.copy(balance = from.balance - amount)
        accounts[toIndex] = to.copy(balance = to.balance + amount)

        transactions.add(
            0,
            Transaction(
                id = "t${transactions.size + 1}",
                accountId = from.id,
                title = "Transfer to ${to.name}",
                amount = -amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )

        transactions.add(
            0,
            Transaction(
                id = "t${transactions.size + 1}",
                accountId = to.id,
                title = "Transfer from ${from.name}",
                amount = amount,
                date = "2026-09-16",
                type = TransactionType.CREDIT
            )
        )

        return Result.success(Unit)
    }
}
