package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.repository.BankingRepository
import kotlinx.coroutines.launch

class TransferViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    var accounts by mutableStateOf<List<Account>>(emptyList())
    var fromAccountId by mutableStateOf("")
    var toAccountId by mutableStateOf("")
    var amount by mutableStateOf("")
    var isLoading by mutableStateOf(false)
    var message by mutableStateOf<String?>(null)

    fun loadAccounts() {
        viewModelScope.launch {
            accounts = repository.getAccounts()
            if (accounts.isNotEmpty() && fromAccountId.isBlank()) {
                fromAccountId = accounts.first().id
            }
            if (accounts.size > 1 && toAccountId.isBlank()) {
                toAccountId = accounts[1].id
            }
        }
    }

    fun submitTransfer(onSuccess: () -> Unit) {
        val parsedAmount = amount.toDoubleOrNull()
        if (parsedAmount == null) {
            message = "Enter a valid amount"
            return
        }

        isLoading = true
        message = null

        viewModelScope.launch {
            val result = repository.transfer(fromAccountId, toAccountId, parsedAmount)
            isLoading = false
            result.onSuccess {
                message = "Transfer successful"
                onSuccess()
            }.onFailure {
                message = it.message
            }
        }
    }
}
