package com.example.bankingapp

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.bankingapp.data.repository.BankingRepository
import com.example.bankingapp.ui.navigation.NavRoutes
import com.example.bankingapp.ui.screens.AccountsScreen
import com.example.bankingapp.ui.screens.LoginScreen
import com.example.bankingapp.ui.screens.TransactionsScreen
import com.example.bankingapp.ui.screens.TransferScreen
import com.example.bankingapp.ui.theme.BankingAppTheme
import com.example.bankingapp.ui.viewmodel.AccountsViewModel
import com.example.bankingapp.ui.viewmodel.LoginViewModel
import com.example.bankingapp.ui.viewmodel.TransactionsViewModel
import com.example.bankingapp.ui.viewmodel.TransferViewModel

@Composable
fun BankingApp() {
    BankingAppTheme {
        val navController = rememberNavController()
        val repository = remember { BankingRepository() }

        NavHost(
            navController = navController,
            startDestination = NavRoutes.LOGIN
        ) {
            composable(NavRoutes.LOGIN) {
                val vm = viewModel<LoginViewModel>(
                    factory = simpleViewModelFactory { LoginViewModel(repository) }
                )
                LoginScreen(
                    viewModel = vm,
                    onLoginSuccess = {
                        navController.navigate(NavRoutes.ACCOUNTS) {
                            popUpTo(NavRoutes.LOGIN) { inclusive = true }
                        }
                    }
                )
            }

            composable(NavRoutes.ACCOUNTS) {
                val vm = viewModel<AccountsViewModel>(
                    factory = simpleViewModelFactory { AccountsViewModel(repository) }
                )
                AccountsScreen(
                    viewModel = vm,
                    onAccountClick = { accountId ->
                        navController.navigate("${NavRoutes.TRANSACTIONS}/$accountId")
                    },
                    onTransferClick = {
                        navController.navigate(NavRoutes.TRANSFER)
                    }
                )
            }

            composable(
                route = "${NavRoutes.TRANSACTIONS}/{accountId}",
                arguments = listOf(navArgument("accountId") { type = NavType.StringType })
            ) { backStackEntry ->
                val accountId = backStackEntry.arguments?.getString("accountId").orEmpty()
                val vm = viewModel<TransactionsViewModel>(
                    factory = simpleViewModelFactory { TransactionsViewModel(repository) }
                )
                TransactionsScreen(
                    accountId = accountId,
                    viewModel = vm
                )
            }

            composable(NavRoutes.TRANSFER) {
                val vm = viewModel<TransferViewModel>(
                    factory = simpleViewModelFactory { TransferViewModel(repository) }
                )
                TransferScreen(
                    viewModel = vm,
                    onTransferSuccess = {
                        navController.popBackStack()
                    }
                )
            }
        }
    }
}
