                onLoginSuccess = {
                    navController.navigate(Routes.DASHBOARD) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.DASHBOARD) {
            DashboardScreen(
                onAccountsClick = { navController.navigate(Routes.ACCOUNTS) },
                onTransactionsClick = { navController.navigate(Routes.TRANSACTIONS) },
                onTransferClick = { navController.navigate(Routes.TRANSFER) }
            )
        }

        composable(Routes.ACCOUNTS) {
            val vm: AccountsViewModel = viewModel(factory = AccountsViewModel.factory(repository))
            AccountsScreen(viewModel = vm)
        }

        composable(Routes.TRANSACTIONS) {
            val vm: TransactionsViewModel = viewModel(factory = TransactionsViewModel.factory(repository))
            TransactionsScreen(viewModel = vm)
        }

        composable(Routes.TRANSFER) {
            val vm: TransferViewModel = viewModel(factory = TransferViewModel.factory(repository))
            TransferScreen(
                viewModel = vm,
                onTransferComplete = { navController.popBackStack() }
            )
        }
    }
