## `data/repository/FakeBankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.User
import kotlin.random.Random

class FakeBankingRepository : BankingRepository {

    private val accounts = mutableListOf(
        Account("1", "Primary Checking", "Checking", 2450.75, "USD"),
        Account("2", "Savings Plus", "Savings", 10200.00, "USD"),
        Account("3", "Travel Card", "Card", 340.20, "USD")
    )

    private val transactions = mutableListOf(
        Transaction("t1", "1", "Payroll Deposit", 3200.00, "2026-09-01", true),
        Transaction("t2", "1", "Coffee Shop", 6.50, "2026-09-02", false),
        Transaction("t3", "2", "Interest Payment", 12.35, "2026-09-03", true),
        Transaction("t4", "3", "Airline Ticket", 220.00, "2026-09-04", false)
    )

    override fun login(username: String, password: String): Result<User> {
        return if (username == "user" && password == "password") {
            Result.success(User("u1", "Alex Johnson", "alex@example.com"))
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    override fun getAccounts(): List<Account> = accounts

    override fun getTransactions(): List<Transaction> = transactions.sortedByDescending { it.date }

    override fun transfer(
        fromAccountId: String,
        toAccountNumber: String,
        amount: Double
    ): Result<String> {
        val accountIndex = accounts.indexOfFirst { it.id == fromAccountId }
        if (accountIndex == -1) return Result.failure(Exception("Source account not found"))
        if (amount <= 0) return Result.failure(Exception("Amount must be greater than zero"))

        val source = accounts[accountIndex]
        if (source.balance < amount) {
            return Result.failure(Exception("Insufficient funds"))
        }

        accounts[accountIndex] = source.copy(balance = source.balance - amount)

        transactions.add(
            Transaction(
                id = "t${Random.nextInt(1000, 9999)}",
                accountId = fromAccountId,
                title = "Transfer to $toAccountNumber",
                amount = amount,
                date = "2026-09-16",
                isCredit = false
            )
        )

        return Result.success("Transfer completed successfully")
    }
}
