```kotlin
package com.example.bankingapp.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.repository.BankingRepository
import com.example.bankingapp.domain.usecase.GetAccountsUseCase
import com.example.bankingapp.domain.usecase.TransferUseCase

class TransferViewModel(
    private val getAccountsUseCase: GetAccountsUseCase,
    private val transferUseCase: TransferUseCase
) : ViewModel() {

    var accounts by mutableStateOf<List<Account>>(emptyList())
        private set

    var selectedAccountId by mutableStateOf("")
    var recipientAccountNumber by mutableStateOf("")
    var amount by mutableStateOf("")
    var message by mutableStateOf<String?>(null)

    init {
        accounts = getAccountsUseCase()
        selectedAccountId = accounts.firstOrNull()?.id.orEmpty()
    }

    fun submitTransfer() {
        val parsedAmount = amount.toDoubleOrNull()
        if (selectedAccountId.isBlank() || recipientAccountNumber.isBlank() || parsedAmount == null) {
            message = "Please fill in all fields correctly"
            return
        }

        val result = transferUseCase(selectedAccountId, recipientAccountNumber, parsedAmount)
        result.onSuccess {
            message = it
            amount = ""
            recipientAccountNumber = ""
        }.onFailure {
            message = it.message
        }
    }

    companion object {
        fun factory(repository: BankingRepository): ViewModelProvider.Factory =
            object : ViewModelProvider.Factory {
                @Suppress("UNCHECKED_CAST")
                override fun <T : ViewModel> create(modelClass: Class<T>): T {
                    return TransferViewModel(
                        GetAccountsUseCase(repository),
                        TransferUseCase(repository)
                    ) as T
                }
            }
    }
}
