## 4. Repository

### `data/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransactionType
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.UUID

class BankingRepository {

    private val _account = MutableStateFlow(
        Account(
            accountNumber = "1234567890",
            accountHolder = "Alex Johnson",
            balance = 2450.75
        )
    )
    val account: StateFlow<Account> = _account.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction(
                id = UUID.randomUUID().toString(),
                title = "Salary",
                amount = 3200.00,
                type = TransactionType.CREDIT,
                timestamp = "2026-09-01 09:00"
            ),
            Transaction(
                id = UUID.randomUUID().toString(),
                title = "Groceries",
                amount = 86.45,
                type = TransactionType.DEBIT,
                timestamp = "2026-09-03 18:20"
            ),
            Transaction(
                id = UUID.randomUUID().toString(),
                title = "Electric Bill",
                amount = 120.00,
                type = TransactionType.DEBIT,
                timestamp = "2026-09-05 10:15"
            )
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    fun transfer(recipient: String, amount: Double): Result<Unit> {
        val currentAccount = _account.value

        if (recipient.isBlank()) {
            return Result.failure(IllegalArgumentException("Recipient is required"))
        }

        if (amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }

        if (amount > currentAccount.balance) {
            return Result.failure(IllegalArgumentException("Insufficient balance"))
        }

        _account.value = currentAccount.copy(balance = currentAccount.balance - amount)

        val formatter = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault())
        val newTransaction = Transaction(
            id = UUID.randomUUID().toString(),
            title = "Transfer to $recipient",
            amount = amount,
            type = TransactionType.DEBIT,
            timestamp = formatter.format(Date())
        )

        _transactions.value = listOf(newTransaction) + _transactions.value

        return Result.success(Unit)
    }
}
```

