## `data/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data

import androidx.compose.runtime.mutableStateListOf
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransactionType
import kotlin.math.absoluteValue

class BankingRepository {

    private val accounts = mutableStateListOf(
        Account(
            id = "1",
            name = "Checking Account",
            numberMasked = "**** 1234",
            balance = 2450.75,
            currency = "USD"
        ),
        Account(
            id = "2",
            name = "Savings Account",
            numberMasked = "**** 5678",
            balance = 10200.00,
            currency = "USD"
        )
    )

    private val transactions = mutableStateListOf(
        Transaction("t1", "1", "Coffee Shop", -5.75, "2026-09-10", TransactionType.DEBIT),
        Transaction("t2", "1", "Salary", 2500.00, "2026-09-09", TransactionType.CREDIT),
        Transaction("t3", "1", "Groceries", -82.40, "2026-09-08", TransactionType.DEBIT),
        Transaction("t4", "2", "Interest", 12.25, "2026-09-01", TransactionType.CREDIT)
    )

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    fun getAccounts(): List<Account> = accounts

    fun getTransactionsForAccount(accountId: String): List<Transaction> {
        return transactions.filter { it.accountId == accountId }
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        if (fromAccountId == toAccountId) {
            return Result.failure(IllegalArgumentException("Cannot transfer to the same account"))
        }

        if (amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }

        val fromIndex = accounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = accounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1) {
            return Result.failure(IllegalArgumentException("Invalid account"))
        }

        val from = accounts[fromIndex]
        val to = accounts[toIndex]

        if (from.balance < amount) {
            return Result.failure(IllegalStateException("Insufficient funds"))
        }

        accounts[fromIndex] = from.copy(balance = from.balance - amount)
        accounts[toIndex] = to.copy(balance = to.balance + amount)

        val timestamp = System.currentTimeMillis().toString()

        transactions.add(
            Transaction(
                id = "out_$timestamp",
                accountId = fromAccountId,
                title = "Transfer to ${to.name}",
                amount = -amount.absoluteValue,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )

        transactions.add(
            Transaction(
                id = "in_$timestamp",
                accountId = toAccountId,
                title = "Transfer from ${from.name}",
                amount = amount.absoluteValue,
                date = "2026-09-16",
                type = TransactionType.CREDIT
            )
        )

        return Result.success(Unit)
    }
}
