```kotlin
package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.navArgument
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.data.BankingRepository
import com.example.bankingapp.ui.screens.AccountsScreen
import com.example.bankingapp.ui.screens.LoginScreen
import com.example.bankingapp.ui.screens.TransactionScreen
import com.example.bankingapp.ui.screens.TransferScreen
import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.BankingViewModel

@Composable
fun AppNavHost(
    modifier: Modifier = Modifier
) {
    val navController = rememberNavController()
    val repository = BankingRepository()

    val authViewModel: AuthViewModel = viewModel(
        factory = SimpleViewModelFactory { AuthViewModel(repository) }
    )

    val bankingViewModel: BankingViewModel = viewModel(
        factory = SimpleViewModelFactory { BankingViewModel(repository) }
    )

    NavHost(
        navController = navController,
        startDestination = NavRoutes.LOGIN,
        modifier = modifier
    ) {
        composable(NavRoutes.LOGIN) {
            LoginScreen(
                authViewModel = authViewModel,
                onLoginSuccess = {
                    navController.navigate(NavRoutes.ACCOUNTS) {
                        popUpTo(NavRoutes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(NavRoutes.ACCOUNTS) {
            AccountsScreen(
                bankingViewModel = bankingViewModel,
                onAccountClick = { accountId ->
                    navController.navigate(NavRoutes.transactionsRoute(accountId))
                },
                onTransferClick = {
                    navController.navigate(NavRoutes.TRANSFER)
                }
            )
        }

        composable(
            route = NavRoutes.TRANSACTIONS_ROUTE,
            arguments = listOf(navArgument(NavRoutes.ACCOUNT_ID_ARG) {
                type = NavType.StringType
            })
        ) { backStackEntry ->
            val accountId = backStackEntry.arguments?.getString(NavRoutes.ACCOUNT_ID_ARG).orEmpty()
            TransactionScreen(
                accountId = accountId,
                bankingViewModel = bankingViewModel,
                onBack = { navController.popBackStack() }
            )
        }

        composable(NavRoutes.TRANSFER) {
            TransferScreen(
                bankingViewModel = bankingViewModel,
                onBack = { navController.popBackStack() },
                onTransferSuccess = { navController.popBackStack() }
            )
        }
    }
}
```

