            label = { Text("From Account ID") }
        )

        OutlinedTextField(
            value = toAccountId,
            onValueChange = { toAccountId = it },
            modifier = Modifier.fillMaxWidth(),
            label = { Text("To Account ID") }
        )

        OutlinedTextField(
            value = amountText,
            onValueChange = { amountText = it },
            modifier = Modifier.fillMaxWidth(),
            label = { Text("Amount") }
        )

        if (message != null) {
            Text(
                text = message!!,
                color = MaterialTheme.colorScheme.error
            )
        }

        Button(
            onClick = {
                val amount = amountText.toDoubleOrNull()
                if (amount == null) {
                    message = "Enter a valid amount"
                } else {
                    val result = bankingViewModel.transfer(fromAccountId, toAccountId, amount)
                    if (result.isSuccess) {
                        onTransferSuccess()
                    } else {
                        message = result.exceptionOrNull()?.message
                    }
                }
            },
            modifier = Modifier.fillMaxWidth()
        ) {
            Text("Submit Transfer")
        }

        Button(
            onClick = onBack,
            modifier = Modifier.fillMaxWidth()
        ) {
            Text("Cancel")
        }
    }
