# 4. Repository

## `BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.data.model.User
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

class BankingRepository {

    private val demoUser = User(
        id = "u1",
        username = "demo",
        fullName = "Alex Johnson"
    )

    private val _accounts = MutableStateFlow(
        listOf(
            Account("a1", "Checking Account", "****1234", 2450.75),
            Account("a2", "Savings Account", "****5678", 10200.00)
        )
    )
    val accounts: StateFlow<List<Account>> = _accounts.asStateFlow()

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction("t1", "a1", "Grocery Store", -54.23, "2026-09-10", TransactionType.DEBIT),
            Transaction("t2", "a1", "Salary", 2500.00, "2026-09-09", TransactionType.CREDIT),
            Transaction("t3", "a2", "Interest", 12.50, "2026-09-08", TransactionType.CREDIT)
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions.asStateFlow()

    fun login(username: String, password: String): User? {
        return if (username == "demo" && password == "password") {
            demoUser
        } else {
            null
        }
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Boolean {
        if (amount <= 0 || fromAccountId == toAccountId) return false

        val currentAccounts = _accounts.value.toMutableList()
        val fromIndex = currentAccounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = currentAccounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1) return false

        val fromAccount = currentAccounts[fromIndex]
        val toAccount = currentAccounts[toIndex]

        if (fromAccount.balance < amount) return false

        currentAccounts[fromIndex] = fromAccount.copy(balance = fromAccount.balance - amount)
        currentAccounts[toIndex] = toAccount.copy(balance = toAccount.balance + amount)

        _accounts.value = currentAccounts

        val updatedTransactions = _transactions.value.toMutableList()
        updatedTransactions.add(
            Transaction(
                id = UUID.randomUUID().toString(),
                accountId = fromAccountId,
                title = "Transfer to ${toAccount.name}",
                amount = -amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )
        updatedTransactions.add(
            Transaction(
                id = UUID.randomUUID().toString(),
                accountId = toAccountId,
                title = "Transfer from ${fromAccount.name}",
                amount = amount,
                date = "2026-09-16",
                type = TransactionType.CREDIT
            )
        )

        _transactions.value = updatedTransactions
        return true
    }

    fun getTransactionsForAccount(accountId: String): List<Transaction> {
        return _transactions.value.filter { it.accountId == accountId }
    }
}
