package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.ui.screen.HomeScreen
import com.example.bankingapp.ui.screen.LoginScreen
import com.example.bankingapp.ui.screen.TransferScreen
import com.example.bankingapp.ui.screen.TransactionsScreen
import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.BankingViewModel

object Routes {
    const val LOGIN = "login"
    const val HOME = "home"
    const val TRANSACTIONS = "transactions/{accountId}"
    const val TRANSFER = "transfer"
}

@Composable
fun AppNavGraph(
    authViewModel: AuthViewModel,
    bankingViewModel: BankingViewModel
) {
    val navController = rememberNavController()
    val currentUser = authViewModel.currentUser.value
    val accounts by bankingViewModel.accounts.collectAsState()

    NavHost(
        navController = navController,
        startDestination = if (currentUser == null) Routes.LOGIN else Routes.HOME
    ) {
        composable(Routes.LOGIN) {
            LoginScreen(
                authViewModel = authViewModel,
                onLoginSuccess = {
                    navController.navigate(Routes.HOME) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.HOME) {
            HomeScreen(
                userName = currentUser?.fullName ?: "User",
                accounts = accounts,
                onAccountClick = { accountId ->
                    navController.navigate("transactions/$accountId")
                },
                onTransferClick = {
                    navController.navigate(Routes.TRANSFER)
                },
                onLogout = {
                    authViewModel.logout()
                    navController.navigate(Routes.LOGIN) {
                        popUpTo(0)
                    }
                }
            )
        }

        composable(Routes.TRANSACTIONS) { backStackEntry ->
            val accountId = backStackEntry.arguments?.getString("accountId").orEmpty()
            TransactionsScreen(
                accountId = accountId,
                transactions = bankingViewModel.getTransactionsForAccount(accountId),
                onBack = { navController.popBackStack() }
            )
        }

        composable(Routes.TRANSFER) {
            TransferScreen(
                accounts = accounts,
                onTransfer = { fromId, toId, amount ->
                    bankingViewModel.transfer(fromId, toId, amount)
                },
                onBack = { navController.popBackStack() }
            )
        }
    }
}
