```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import kotlin.math.roundToInt

class FakeBankingRepository : BankingRepository {

    private val accounts = mutableListOf(
        Account(
            id = "1",
            name = "Checking Account",
            numberMasked = "****1234",
            balance = 2450.75,
            currency = "USD"
        ),
        Account(
            id = "2",
            name = "Savings Account",
            numberMasked = "****5678",
            balance = 10200.00,
            currency = "USD"
        )
    )

    private val transactions = mutableListOf(
        Transaction("t1", "1", "Coffee Shop", -5.75, "2026-09-10", TransactionType.DEBIT),
        Transaction("t2", "1", "Payroll", 2500.00, "2026-09-09", TransactionType.CREDIT),
        Transaction("t3", "1", "Groceries", -82.14, "2026-09-08", TransactionType.DEBIT),
        Transaction("t4", "2", "Interest", 15.22, "2026-09-01", TransactionType.CREDIT)
    )

    override fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    override fun getAccounts(): List<Account> = accounts.toList()

    override fun getTransactions(accountId: String): List<Transaction> {
        return transactions.filter { it.accountId == accountId }
    }

    override fun transfer(fromAccountId: String, toAccountNumber: String, amount: Double): Result<Unit> {
        val index = accounts.indexOfFirst { it.id == fromAccountId }
        if (index == -1) return Result.failure(Exception("Account not found"))
        if (amount <= 0) return Result.failure(Exception("Amount must be greater than zero"))

        val account = accounts[index]
        if (account.balance < amount) return Result.failure(Exception("Insufficient funds"))

        val updated = account.copy(balance = ((account.balance - amount) * 100).roundToInt() / 100.0)
        accounts[index] = updated

        transactions.add(
            0,
            Transaction(
                id = "t${transactions.size + 1}",
                accountId = fromAccountId,
                title = "Transfer to $toAccountNumber",
                amount = -amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )

        return Result.success(Unit)
    }
}
