```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.repository.BankingRepository

class TransferViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    var toAccountNumber by mutableStateOf("")
        private set

    var amount by mutableStateOf("")
        private set

    var message by mutableStateOf<String?>(null)
        private set

    fun onToAccountChange(value: String) {
        toAccountNumber = value
    }

    fun onAmountChange(value: String) {
        amount = value
    }

    fun submitTransfer(fromAccountId: String, onSuccess: () -> Unit) {
        val parsedAmount = amount.toDoubleOrNull()
        if (toAccountNumber.isBlank()) {
            message = "Destination account is required"
            return
        }
        if (parsedAmount == null) {
            message = "Enter a valid amount"
            return
        }

        val result = repository.transfer(fromAccountId, toAccountNumber, parsedAmount)
        if (result.isSuccess) {
            message = "Transfer successful"
            toAccountNumber = ""
            amount = ""
            onSuccess()
        } else {
            message = result.exceptionOrNull()?.message ?: "Transfer failed"
        }
    }
}
