import com.example.bankingapp.LocalAppContainer
import com.example.bankingapp.ui.screens.AccountsScreen
import com.example.bankingapp.ui.screens.LoginScreen
import com.example.bankingapp.ui.screens.TransferScreen
import com.example.bankingapp.ui.viewmodel.AccountsViewModel
import com.example.bankingapp.ui.viewmodel.LoginViewModel
import com.example.bankingapp.ui.viewmodel.TransferViewModel

@Composable
fun AppNavGraph(
    navController: NavHostController,
    appContainer: AppContainer
) {
    CompositionLocalProvider(LocalAppContainer provides appContainer) {
        NavHost(
            navController = navController,
            startDestination = Destinations.LOGIN
        ) {
            composable(Destinations.LOGIN) {
                val vm = LoginViewModel(appContainer.repository)
                LoginScreen(
                    viewModel = vm,
                    onLoginSuccess = {
                        navController.navigate(Destinations.ACCOUNTS) {
                            popUpTo(Destinations.LOGIN) { inclusive = true }
                        }
                    }
                )
            }

            composable(Destinations.ACCOUNTS) {
                val vm = AccountsViewModel(appContainer.repository)
                AccountsScreen(
                    viewModel = vm,
                    onTransferClick = {
                        navController.navigate(Destinations.TRANSFER)
                    }
                )
            }

            composable(Destinations.TRANSFER) {
                val accountsVm = AccountsViewModel(appContainer.repository)
                val transferVm = TransferViewModel(appContainer.repository)
                TransferScreen(
                    accountsViewModel = accountsVm,
                    transferViewModel = transferVm,
                    onBack = { navController.popBackStack() },
                    onTransferSuccess = {
                        navController.popBackStack()
                    }
                )
            }
        }
    }
}
