```kotlin
package com.example.bankapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankapp.data.repository.BankRepository

class TransferViewModel(
    private val repository: BankRepository = BankRepository()
) : ViewModel() {

    var recipientAccount by mutableStateOf("")
    var amount by mutableStateOf("")
    var transferMessage by mutableStateOf<String?>(null)
    var transferError by mutableStateOf<String?>(null)

    fun submitTransfer() {
        transferMessage = null
        transferError = null

        val parsedAmount = amount.toDoubleOrNull()
        if (parsedAmount == null) {
            transferError = "Enter a valid amount"
            return
        }

        val result = repository.transfer(recipientAccount, parsedAmount)
        result
            .onSuccess {
                transferMessage = it
                recipientAccount = ""
                amount = ""
            }
            .onFailure {
                transferError = it.message
            }
    }
}
