package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction

class BankingRepository {

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "password"
    }

    fun getAccounts(): List<Account> {
        return listOf(
            Account(
                id = "1",
                name = "Primary Checking",
                type = "Checking",
                balance = 2450.75,
                accountNumberMasked = "****1234"
            ),
            Account(
                id = "2",
                name = "Savings",
                type = "Savings",
                balance = 10500.00,
                accountNumberMasked = "****5678"
            )
        )
    }

    fun getRecentTransactions(): List<Transaction> {
        return listOf(
            Transaction("t1", "Coffee Shop", -5.75, "2026-09-14", "debit"),
            Transaction("t2", "Payroll Deposit", 2500.00, "2026-09-13", "credit"),
            Transaction("t3", "Electric Bill", -120.45, "2026-09-12", "debit")
        )
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<String> {
        return when {
            fromAccountId == toAccountId -> Result.failure(Exception("Accounts must be different"))
            amount <= 0 -> Result.failure(Exception("Amount must be greater than zero"))
            else -> Result.success("Transfer submitted successfully")
        }
    }
}
