package com.example.bankingapp.viewmodel

import androidx.compose.runtime.mutableStateListOf
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.repository.BankingRepository

class AccountsViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    val accounts = mutableStateListOf<Account>()
    val transactions = mutableStateListOf<Transaction>()

    init {
        loadData()
    }

    private fun loadData() {
        accounts.clear()
        accounts.addAll(repository.getAccounts())

        transactions.clear()
        transactions.addAll(repository.getRecentTransactions())
    }
}
