# 5. Repository

## `data/repository/BankingRepository.kt`

```kotlin
package com.example.mobilebanking.data.repository

import com.example.mobilebanking.data.model.Account
import com.example.mobilebanking.data.model.Transaction
import com.example.mobilebanking.data.model.TransactionType
import com.example.mobilebanking.data.model.UserSession
import kotlinx.coroutines.delay

class BankingRepository {

    private var session: UserSession? = null

    private val accounts = mutableListOf(
        Account(
            id = "1",
            name = "Main Checking",
            type = "Checking",
            balance = 2450.75,
            currency = "USD",
            accountNumberMasked = "****1234"
        ),
        Account(
            id = "2",
            name = "Savings Account",
            type = "Savings",
            balance = 10420.10,
            currency = "USD",
            accountNumberMasked = "****5678"
        )
    )

    private val transactions = listOf(
        Transaction("t1", "Coffee Shop", -5.75, "2026-09-10", TransactionType.DEBIT),
        Transaction("t2", "Salary", 2500.00, "2026-09-09", TransactionType.CREDIT),
        Transaction("t3", "Electric Bill", -120.30, "2026-09-08", TransactionType.DEBIT)
    )

    suspend fun login(username: String, password: String): Result<UserSession> {
        delay(1000)
        return if (username == "demo" && password == "password") {
            val newSession = UserSession(
                userId = "user_001",
                fullName = "Alex Johnson",
                authToken = "fake_jwt_token"
            )
            session = newSession
            Result.success(newSession)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    fun logout() {
        session = null
    }

    fun getSession(): UserSession? = session

    suspend fun getAccounts(): List<Account> {
        delay(500)
        return accounts.toList()
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(500)
        return transactions
    }

    suspend fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        delay(1000)

        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        val fromIndex = accounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = accounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1) {
            return Result.failure(Exception("Invalid account selection"))
        }

        if (fromAccountId == toAccountId) {
            return Result.failure(Exception("Cannot transfer to the same account"))
        }

        val fromAccount = accounts[fromIndex]
        val toAccount = accounts[toIndex]

        if (fromAccount.balance < amount) {
            return Result.failure(Exception("Insufficient funds"))
        }

        accounts[fromIndex] = fromAccount.copy(balance = fromAccount.balance - amount)
        accounts[toIndex] = toAccount.copy(balance = toAccount.balance + amount)

        return Result.success(Unit)
    }
}
```

