# 9. Navigation

## `ui/navigation/AppNavGraph.kt`

```kotlin
package com.example.mobilebanking.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.example.mobilebanking.data.repository.BankingRepository
import com.example.mobilebanking.ui.screen.AccountsScreen
import com.example.mobilebanking.ui.screen.DashboardScreen
import com.example.mobilebanking.ui.screen.LoginScreen
import com.example.mobilebanking.ui.screen.TransferScreen
import com.example.mobilebanking.viewmodel.AuthViewModel
import com.example.mobilebanking.viewmodel.DashboardViewModel
import com.example.mobilebanking.viewmodel.TransferViewModel

sealed class AppRoute(val route: String) {
    data object Login : AppRoute("login")
    data object Dashboard : AppRoute("dashboard")
    data object Accounts : AppRoute("accounts")
    data object Transfer : AppRoute("transfer")
}

@Composable
fun AppNavGraph(repository: BankingRepository) {
    val navController = rememberNavController()

    val authViewModel: AuthViewModel = viewModel(
        factory = simpleFactory { AuthViewModel(repository) }
    )
    val authState by authViewModel.uiState.collectAsState()

    NavHost(
        navController = navController,
        startDestination = if (authState.session == null) AppRoute.Login.route else AppRoute.Dashboard.route
    ) {
        composable(AppRoute.Login.route) {
            LoginScreen(
                uiState = authState,
                onLogin = { username, password ->
                    authViewModel.login(username, password)
                },
                onLoginSuccess = {
                    navController.navigate(AppRoute.Dashboard.route) {
                        popUpTo(AppRoute.Login.route) { inclusive = true }
                    }
                }
            )
        }

        composable(AppRoute.Dashboard.route) {
            val dashboardViewModel: DashboardViewModel = viewModel(
                factory = simpleFactory { DashboardViewModel(repository) }
            )
            DashboardScreen(
                viewModel = dashboardViewModel,
                onAccountsClick = { navController.navigate(AppRoute.Accounts.route) },
                onTransferClick = { navController.navigate(AppRoute.Transfer.route) },
                onLogout = {
                    authViewModel.logout()
                    navController.navigate(AppRoute.Login.route) {
                        popUpTo(0)
                    }
                }
            )
        }

        composable(AppRoute.Accounts.route) {
            val dashboardViewModel: DashboardViewModel = viewModel(
                factory = simpleFactory { DashboardViewModel(repository) }
            )
            AccountsScreen(
                viewModel = dashboardViewModel,
                onBack = { navController.popBackStack() }
            )
        }

        composable(AppRoute.Transfer.route) {
            val transferViewModel: TransferViewModel = viewModel(
                factory = simpleFactory { TransferViewModel(repository) }
            )
            TransferScreen(
                viewModel = transferViewModel,
                onBack = { navController.popBackStack() }
            )
        }
    }
}

fun <T : ViewModel> simpleFactory(create: () -> T): ViewModelProvider.Factory {
    return object : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <VM : ViewModel> create(modelClass: Class<VM>): VM = create() as VM
    }
}
