package com.example.mobilebanking.ui.screen

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import com.example.mobilebanking.viewmodel.TransferViewModel

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TransferScreen(
    viewModel: TransferViewModel,
    onBack: () -> Unit
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()

    var fromAccountId by remember { mutableStateOf("") }
    var toAccountId by remember { mutableStateOf("") }
    var amount by remember { mutableStateOf("") }

    LaunchedEffect(Unit) {
        viewModel.loadAccounts()
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Transfer Funds") },
                navigationIcon = {
                    TextButton(onClick = onBack) {
                        Text("Back")
                    }
                }
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            val accounts = uiState.accounts

            if (accounts.isNotEmpty() && fromAccountId.isEmpty()) {
                fromAccountId = accounts.first().id
            }
            if (accounts.size > 1 && toAccountId.isEmpty()) {
                toAccountId = accounts[1].id
            }

            Text("From Account")
            accounts.forEach { account ->
                RowSelector(
                    text = "${account.name} (${account.accountNumberMasked})",
                    selected = fromAccountId == account.id,
                    onClick = { fromAccountId = account.id }
                )
            }

            Text("To Account")
            accounts.forEach { account ->
                RowSelector(
                    text = "${account.name} (${account.accountNumberMasked})",
                    selected = toAccountId == account.id,
                    onClick = { toAccountId = account.id }
                )
            }

            OutlinedTextField(
                value = amount,
                onValueChange = { amount = it },
                label = { Text("Amount") },
                modifier = Modifier.fillMaxWidth()
            )

            uiState.error?.let {
                Text(it, color = MaterialTheme.colorScheme.error)
            }

            uiState.successMessage?.let {
                Text(it, color = MaterialTheme.colorScheme.primary)
            }

            Button(
                onClick = {
                    val parsedAmount = amount.toDoubleOrNull() ?: 0.0
                    viewModel.transfer(fromAccountId, toAccountId, parsedAmount)
                },
                modifier = Modifier.fillMaxWidth(),
                enabled = !uiState.isLoading
            ) {
                Text(if (uiState.isLoading) "Processing..." else "Submit Transfer")
            }
        }
    }
}

@Composable
private fun RowSelector(
    text: String,
    selected: Boolean,
    onClick: () -> Unit
) {
    AssistChip(
        onClick = onClick,
        label = { Text(text) }
    )
}
