## `data/repository/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.data.model.User

class BankingRepository {

    private val fakeUser = User(
        id = "u1",
        fullName = "Alex Johnson"
    )

    private val fakeAccounts = listOf(
        Account(
            id = "a1",
            name = "Checking Account",
            numberMasked = "****1234",
            balance = 2450.75,
            currency = "USD"
        ),
        Account(
            id = "a2",
            name = "Savings Account",
            numberMasked = "****5678",
            balance = 10250.00,
            currency = "USD"
        )
    )

    private val fakeTransactions = listOf(
        Transaction("t1", "Grocery Store", -54.20, "2026-09-10", TransactionType.DEBIT),
        Transaction("t2", "Salary", 2500.00, "2026-09-09", TransactionType.CREDIT),
        Transaction("t3", "Electric Bill", -120.00, "2026-09-08", TransactionType.DEBIT)
    )

    fun login(username: String, password: String): Result<User> {
        return if (username == "demo" && password == "password") {
            Result.success(fakeUser)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    fun getAccounts(): List<Account> = fakeAccounts

    fun getRecentTransactions(): List<Transaction> = fakeTransactions

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<String> {
        if (fromAccountId == toAccountId) {
            return Result.failure(Exception("Cannot transfer to the same account"))
        }
        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }
        return Result.success("Transfer submitted successfully")
    }
}
