import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.DashboardViewModel
import com.example.bankingapp.ui.viewmodel.TransferViewModel

object Routes {
    const val LOGIN = "login"
    const val DASHBOARD = "dashboard"
    const val ACCOUNTS = "accounts"
    const val TRANSFER = "transfer"
}

@Composable
fun AppNavGraph(
    navController: NavHostController,
    modifier: Modifier = Modifier
) {
    NavHost(
        navController = navController,
        startDestination = Routes.LOGIN,
        modifier = modifier
    ) {
        composable(Routes.LOGIN) {
            val viewModel: AuthViewModel = viewModel()
            LoginScreen(
                viewModel = viewModel,
                onLoginSuccess = {
                    navController.navigate(Routes.DASHBOARD) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.DASHBOARD) {
            val viewModel: DashboardViewModel = viewModel()
            DashboardScreen(
                viewModel = viewModel,
                onAccountsClick = { navController.navigate(Routes.ACCOUNTS) },
                onTransferClick = { navController.navigate(Routes.TRANSFER) }
            )
        }

        composable(Routes.ACCOUNTS) {
            val viewModel: AccountsViewModel = viewModel()
            AccountsScreen(viewModel = viewModel)
        }

        composable(Routes.TRANSFER) {
            val viewModel: TransferViewModel = viewModel()
            TransferScreen(viewModel = viewModel)
        }
    }
}
