# 7. Mock repository

## `data/repository/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.data.model.User
import kotlinx.coroutines.delay

class BankingRepository {

    private var loggedInUser: User? = null
    private var account = Account(
        id = "acc_001",
        accountName = "Primary Checking",
        accountNumberMasked = "****1234",
        balance = 5420.75,
        currency = "USD"
    )

    private val transactions = mutableListOf(
        Transaction("txn_001", "Salary", 3200.00, "2026-09-01", TransactionType.CREDIT),
        Transaction("txn_002", "Coffee Shop", 6.50, "2026-09-03", TransactionType.DEBIT),
        Transaction("txn_003", "Electric Bill", 120.00, "2026-09-05", TransactionType.DEBIT),
        Transaction("txn_004", "Refund", 45.00, "2026-09-07", TransactionType.CREDIT)
    )

    suspend fun login(email: String, password: String): Result<User> {
        delay(1000)
        return if (email.isNotBlank() && password.length >= 4) {
            val user = User(
                id = "user_001",
                fullName = "Alex Johnson",
                email = email
            )
            loggedInUser = user
            Result.success(user)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    suspend fun getCurrentUser(): User? {
        delay(200)
        return loggedInUser
    }

    suspend fun getAccount(): Account {
        delay(400)
        return account
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(500)
        return transactions.toList()
    }

    suspend fun transfer(toAccount: String, amount: Double): Result<Unit> {
        delay(1000)

        if (toAccount.isBlank()) {
            return Result.failure(Exception("Recipient account is required"))
        }

        if (amount <= 0.0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        if (amount > account.balance) {
            return Result.failure(Exception("Insufficient funds"))
        }

        account = account.copy(balance = account.balance - amount)
        transactions.add(
            0,
            Transaction(
                id = "txn_${System.currentTimeMillis()}",
                title = "Transfer to $toAccount",
                amount = amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )

        return Result.success(Unit)
    }
}
