            try {
                val account = repository.getAccount()
                val transactions = repository.getTransactions()
                _uiState.value = DashboardUiState(
                    account = account,
                    transactions = transactions
                )
            } catch (e: Exception) {
                _uiState.value = DashboardUiState(
                    error = e.message ?: "Failed to load dashboard"
                )
            }
        }
    }
