package com.example.bankingapp.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.repository.BankingRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

data class TransferUiState(
    val isLoading: Boolean = false,
    val success: Boolean = false,
    val error: String? = null
)

class TransferViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(TransferUiState())
    val uiState: StateFlow<TransferUiState> = _uiState.asStateFlow()

    fun transfer(toAccount: String, amountText: String) {
        val amount = amountText.toDoubleOrNull()
        if (amount == null) {
            _uiState.value = TransferUiState(error = "Invalid amount")
            return
        }

        _uiState.value = TransferUiState(isLoading = true)

        viewModelScope.launch {
            val result = repository.transfer(toAccount, amount)
            _uiState.value = result.fold(
                onSuccess = {
                    TransferUiState(success = true)
                },
                onFailure = { error ->
                    TransferUiState(error = error.message ?: "Transfer failed")
                }
            )
        }
    }

    fun resetState() {
        _uiState.value = TransferUiState()
    }
}
