package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.ui.screen.DashboardScreen
import com.example.bankingapp.ui.screen.LoginScreen
import com.example.bankingapp.ui.screen.TransferScreen
import com.example.bankingapp.ui.viewmodel.AppViewModelFactory
import com.example.bankingapp.ui.viewmodel.AuthViewModel
import com.example.bankingapp.ui.viewmodel.DashboardViewModel
import com.example.bankingapp.ui.viewmodel.TransferViewModel

object Routes {
    const val LOGIN = "login"
    const val DASHBOARD = "dashboard"
    const val TRANSFER = "transfer"
}

@Composable
fun BankingNavGraph(
    factory: AppViewModelFactory,
    navController: NavHostController = rememberNavController()
) {
    NavHost(
        navController = navController,
        startDestination = Routes.LOGIN
    ) {
        composable(Routes.LOGIN) {
            val viewModel: AuthViewModel = viewModel(factory = factory)
            val state = viewModel.uiState.collectAsStateWithLifecycle()

            LaunchedEffect(state.value.user) {
                if (state.value.user != null) {
                    navController.navigate(Routes.DASHBOARD) {
                        popUpTo(Routes.LOGIN) { inclusive = true }
                    }
                }
            }

            LoginScreen(
                uiState = state.value,
                onLogin = viewModel::login
            )
        }

        composable(Routes.DASHBOARD) {
            val viewModel: DashboardViewModel = viewModel(factory = factory)
            val state = viewModel.uiState.collectAsStateWithLifecycle()

            LaunchedEffect(Unit) {
                viewModel.loadDashboard()
            }

            DashboardScreen(
                uiState = state.value,
                onTransferClick = {
                    navController.navigate(Routes.TRANSFER)
                }
            )
        }

        composable(Routes.TRANSFER) {
            val viewModel: TransferViewModel = viewModel(factory = factory)
            val state = viewModel.uiState.collectAsStateWithLifecycle()

            LaunchedEffect(state.value.success) {
                if (state.value.success) {
                    navController.popBackStack()
                }
            }

            TransferScreen(
                uiState = state.value,
                onTransfer = viewModel::transfer,
                onBack = { navController.popBackStack() }
            )
        }
    }
}
