# 4. Fake repository

## `data/BankingRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransactionType
import com.example.bankingapp.model.TransferRequest
import kotlinx.coroutines.delay

class BankingRepository {

    private var account = Account(
        accountNumber = "1234567890",
        accountName = "Alex Johnson",
        balance = 2450.75,
        currency = "USD"
    )

    private val transactions = mutableListOf(
        Transaction("1", "Salary", 3200.00, "2026-09-01", TransactionType.CREDIT),
        Transaction("2", "Groceries", 120.45, "2026-09-03", TransactionType.DEBIT),
        Transaction("3", "Electric Bill", 89.99, "2026-09-05", TransactionType.DEBIT),
        Transaction("4", "Coffee Shop", 8.50, "2026-09-06", TransactionType.DEBIT)
    )

    suspend fun login(username: String, password: String): Boolean {
        delay(800)
        return username == "user" && password == "password"
    }

    suspend fun getAccount(): Account {
        delay(300)
        return account
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(300)
        return transactions.toList()
    }

    suspend fun transfer(request: TransferRequest): Result<Unit> {
        delay(700)

        if (request.amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }

        if (request.amount > account.balance) {
            return Result.failure(IllegalStateException("Insufficient funds"))
        }

        account = account.copy(balance = account.balance - request.amount)

        transactions.add(
            0,
            Transaction(
                id = System.currentTimeMillis().toString(),
                title = "Transfer to ${request.recipientName}",
                amount = request.amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )

        return Result.success(Unit)
    }
}
