```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.BankingRepository
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransferRequest
import kotlinx.coroutines.launch

class BankingViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    var account by mutableStateOf<Account?>(null)
    var transactions by mutableStateOf<List<Transaction>>(emptyList())
    var isLoading by mutableStateOf(false)
    var message by mutableStateOf<String?>(null)

    fun loadDashboard() {
        isLoading = true
        viewModelScope.launch {
            account = repository.getAccount()
            transactions = repository.getTransactions()
            isLoading = false
        }
    }

    fun transfer(recipientName: String, recipientAccount: String, amount: String) {
        val amountValue = amount.toDoubleOrNull()
        if (amountValue == null) {
            message = "Enter a valid amount"
            return
        }

        viewModelScope.launch {
            isLoading = true
            val result = repository.transfer(
                TransferRequest(
                    recipientName = recipientName,
                    recipientAccount = recipientAccount,
                    amount = amountValue
                )
            )
            isLoading = false

            result.onSuccess {
                message = "Transfer successful"
                loadDashboard()
            }.onFailure {
                message = it.message
            }
        }
    }
}
