package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.repository.BankingRepository
import kotlinx.coroutines.launch

class TransferViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    var toAccount by mutableStateOf("")
    var amount by mutableStateOf("")
    var isLoading by mutableStateOf(false)
    var successMessage by mutableStateOf<String?>(null)
    var errorMessage by mutableStateOf<String?>(null)

    fun submitTransfer() {
        val amountValue = amount.toDoubleOrNull()
        if (amountValue == null) {
            errorMessage = "Enter a valid amount"
            return
        }

        viewModelScope.launch {
            isLoading = true
            successMessage = null
            errorMessage = null

            val result = repository.transfer(toAccount, amountValue)
            isLoading = false

            result.onSuccess {
                successMessage = "Transfer completed successfully"
                toAccount = ""
                amount = ""
            }.onFailure {
                errorMessage = it.message
            }
        }
    }
}
