@Composable
private fun AccountCard(account: Account) {
    Card(modifier = Modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(16.dp)) {
            Text(
                text = account.accountType,
                style = MaterialTheme.typography.titleMedium
            )
            Text(text = account.accountNumberMasked)
            Text(
                text = formatCurrency(account.balance, account.currency),
                style = MaterialTheme.typography.headlineSmall,
                modifier = Modifier.padding(top = 8.dp)
            )
        }
    }
}

@Composable
private fun TransactionRow(transaction: Transaction) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Column {
            Text(text = transaction.title, style = MaterialTheme.typography.bodyLarge)
            Text(text = transaction.date, style = MaterialTheme.typography.bodySmall)
        }

        val prefix = if (transaction.isCredit) "+" else "-"
        Text(
            text = "$prefix${formatCurrency(transaction.amount, "USD")}",
            color = if (transaction.isCredit) MaterialTheme.colorScheme.primary
            else MaterialTheme.colorScheme.error
        )
    }
}

private fun formatCurrency(amount: Double, currencyCode: String): String {
    val format = NumberFormat.getCurrencyInstance(Locale.US)
    format.currency = Currency.getInstance(currencyCode)
    return format.format(amount)
}
