## `data/repository/FakeBankRepository.kt`

```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.model.TransactionType
import com.example.bankapp.data.model.TransferRequest
import kotlinx.coroutines.delay

class FakeBankRepository : BankRepository {

    private var currentBalance = 5240.75

    override suspend fun login(username: String, password: String): Result<Unit> {
        delay(800)
        return if (username == "demo" && password == "password") {
            Result.success(Unit)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    override suspend fun getAccount(): Account {
        delay(500)
        return Account(
            id = "acc_001",
            name = "Primary Checking",
            accountNumberMasked = "****1234",
            balance = currentBalance,
            currency = "USD"
        )
    }

    override suspend fun getTransactions(): List<Transaction> {
        delay(500)
        return listOf(
            Transaction("txn_001", "Coffee Shop", "2026-09-10", -5.75, "USD", TransactionType.DEBIT),
            Transaction("txn_002", "Payroll", "2026-09-09", 2500.00, "USD", TransactionType.CREDIT),
            Transaction("txn_003", "Electric Bill", "2026-09-08", -120.30, "USD", TransactionType.DEBIT),
            Transaction("txn_004", "Grocery Store", "2026-09-07", -84.12, "USD", TransactionType.DEBIT)
        )
    }

    override suspend fun transfer(request: TransferRequest): Result<Unit> {
        delay(1000)
        return if (request.amount <= 0) {
            Result.failure(Exception("Amount must be greater than zero"))
        } else if (request.amount > currentBalance) {
            Result.failure(Exception("Insufficient funds"))
        } else {
            currentBalance -= request.amount
            Result.success(Unit)
        }
    }
}
```

