import com.example.bankapp.ui.screen.login.LoginScreen
import com.example.bankapp.ui.screen.login.LoginViewModel
import com.example.bankapp.ui.screen.transfer.TransferScreen
import com.example.bankapp.ui.screen.transfer.TransferViewModel

object Routes {
    const val LOGIN = "login"
    const val DASHBOARD = "dashboard"
    const val TRANSFER = "transfer"
}

@Composable
fun BankNavGraph(repository: BankRepository) {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = Routes.LOGIN
    ) {
        composable(Routes.LOGIN) {
            val vm: LoginViewModel = viewModel(
                factory = LoginViewModel.factory(repository)
            )
            LoginScreen(
                state = vm.uiState,
                onUsernameChange = vm::onUsernameChange,
                onPasswordChange = vm::onPasswordChange,
                onLoginClick = {
                    vm.login(
                        onSuccess = {
                            navController.navigate(Routes.DASHBOARD) {
                                popUpTo(Routes.LOGIN) { inclusive = true }
                            }
                        }
                    )
                }
            )
        }

        composable(Routes.DASHBOARD) {
            val vm: DashboardViewModel = viewModel(
                factory = DashboardViewModel.factory(repository)
            )
            DashboardScreen(
                state = vm.uiState,
                onRefresh = vm::loadData,
                onTransferClick = { navController.navigate(Routes.TRANSFER) }
            )
        }

        composable(Routes.TRANSFER) {
            val vm: TransferViewModel = viewModel(
                factory = TransferViewModel.factory(repository)
            )
            TransferScreen(
                state = vm.uiState,
                onRecipientNameChange = vm::onRecipientNameChange,
                onRecipientAccountChange = vm::onRecipientAccountChange,
                onAmountChange = vm::onAmountChange,
                onNoteChange = vm::onNoteChange,
                onSubmit = {
                    vm.submitTransfer(
                        onSuccess = {
                            navController.popBackStack()
                        }
                    )
                },
                onBack = { navController.popBackStack() }
            )
        }
    }
}
