package com.example.bankapp.ui.screen.transfer

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.model.TransferRequest
import com.example.bankapp.data.repository.BankRepository
import kotlinx.coroutines.launch

data class TransferUiState(
    val recipientName: String = "",
    val recipientAccount: String = "",
    val amount: String = "",
    val note: String = "",
    val isSubmitting: Boolean = false,
    val error: String? = null
)

class TransferViewModel(
    private val repository: BankRepository
) : ViewModel() {

    var uiState by mutableStateOf(TransferUiState())
        private set

    fun onRecipientNameChange(value: String) {
        uiState = uiState.copy(recipientName = value, error = null)
    }

    fun onRecipientAccountChange(value: String) {
        uiState = uiState.copy(recipientAccount = value, error = null)
    }

    fun onAmountChange(value: String) {
        uiState = uiState.copy(amount = value, error = null)
    }

    fun onNoteChange(value: String) {
        uiState = uiState.copy(note = value, error = null)
    }

    fun submitTransfer(onSuccess: () -> Unit) {
        val amountValue = uiState.amount.toDoubleOrNull()
        if (amountValue == null) {
            uiState = uiState.copy(error = "Enter a valid amount")
            return
        }

        viewModelScope.launch {
            uiState = uiState.copy(isSubmitting = true, error = null)
            val result = repository.transfer(
                TransferRequest(
                    recipientName = uiState.recipientName,
                    recipientAccount = uiState.recipientAccount,
                    amount = amountValue,
                    note = uiState.note
                )
            )
            uiState = uiState.copy(isSubmitting = false)

            result.onSuccess { onSuccess() }
                .onFailure { uiState = uiState.copy(error = it.message) }
        }
    }

    companion object {
        fun factory(repository: BankRepository): ViewModelProvider.Factory =
            object : ViewModelProvider.Factory {
                @Suppress("UNCHECKED_CAST")
                override fun <T : ViewModel> create(modelClass: Class<T>): T {
                    return TransferViewModel(repository) as T
                }
            }
    }
}
