## `BankingApp.kt`

```kotlin
package com.example.bankingdemo.ui

import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.*
import com.example.bankingdemo.data.FakeRepository
import com.example.bankingdemo.ui.screens.DashboardScreen
import com.example.bankingdemo.ui.screens.LoginScreen
import com.example.bankingdemo.ui.screens.TransferScreen

sealed class AppScreen {
    object Login : AppScreen()
    object Dashboard : AppScreen()
    object Transfer : AppScreen()
}

@Composable
fun BankingApp() {
    var currentScreen by remember { mutableStateOf<AppScreen>(AppScreen.Login) }
    var isLoggedIn by remember { mutableStateOf(false) }
    var transferMessage by remember { mutableStateOf<String?>(null) }

    val account = FakeRepository.getAccount()
    val transactions = FakeRepository.getTransactions()

    MaterialTheme {
        Surface {
            when (currentScreen) {
                AppScreen.Login -> {
                    LoginScreen(
                        onLogin = { username, password ->
                            if (username.isNotBlank() && password.isNotBlank()) {
                                isLoggedIn = true
                                currentScreen = AppScreen.Dashboard
                            }
                        }
                    )
                }

                AppScreen.Dashboard -> {
                    if (isLoggedIn) {
                        DashboardScreen(
                            accountName = account.accountName,
                            accountNumber = account.accountNumber,
                            balance = account.balance,
                            transactions = transactions,
                            transferMessage = transferMessage,
                            onTransferClick = {
                                currentScreen = AppScreen.Transfer
                            },
                            onLogout = {
                                isLoggedIn = false
                                transferMessage = null
                                currentScreen = AppScreen.Login
                            }
                        )
                    } else {
                        currentScreen = AppScreen.Login
                    }
                }

                AppScreen.Transfer -> {
                    TransferScreen(
                        onBack = { currentScreen = AppScreen.Dashboard },
                        onSubmitTransfer = { recipient, amount ->
                            transferMessage = "Transferred $%.2f to %s".format(amount, recipient)
                            currentScreen = AppScreen.Dashboard
                        }
                    )
                }
            }
        }
    }
}
