# 9) Transfer screen

## `ui/TransferScreen.kt`

```kotlin
package com.example.bankingapp.ui

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.example.bankingapp.data.FakeBankRepository

@Composable
fun TransferScreen(
    onBack: () -> Unit,
    onTransferSuccess: () -> Unit
) {
    var toAccount by remember { mutableStateOf("") }
    var amountText by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Transfer Money") }
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            OutlinedTextField(
                value = toAccount,
                onValueChange = {
                    toAccount = it
                    message = ""
                },
                label = { Text("Recipient Account") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = amountText,
                onValueChange = {
                    amountText = it
                    message = ""
                },
                label = { Text("Amount") },
                modifier = Modifier.fillMaxWidth()
            )

            Button(
                onClick = {
                    val amount = amountText.toDoubleOrNull()
                    if (amount == null) {
                        message = "Enter a valid amount"
                    } else {
                        val success = FakeBankRepository.transfer(toAccount, amount)
                        if (success) {
                            onTransferSuccess()
                        } else {
                            message = "Transfer failed"
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth()
            ) {
                Text("Send")
            }

            OutlinedButton(
                onClick = onBack,
                modifier = Modifier.fillMaxWidth()
            ) {
                Text("Back")
            }

            if (message.isNotEmpty()) {
                Text(message, color = MaterialTheme.colorScheme.error)
            }
        }
    }
}
