# 5) Repository

## `data/BankRepository.kt`
```kotlin
package com.example.bankingapp.data

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction

object BankRepository {
    private val _account = mutableStateOf(
        Account(
            accountNumber = "1234567890",
            accountHolder = "John Doe",
            balance = 2500.00
        )
    )

    private val _transactions = mutableStateListOf(
        Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
        Transaction(2, "Salary", 1500.00, "2026-09-09"),
        Transaction(3, "Groceries", -76.20, "2026-09-08")
    )

    val account get() = _account
    val transactions: List<Transaction> get() = _transactions

    fun login(username: String, password: String): Boolean {
        return username == "user" && password == "pass123"
    }

    fun transfer(to: String, amount: Double): Boolean {
        val current = _account.value
        if (to.isBlank() || amount <= 0 || amount > current.balance) return false

        _account.value = current.copy(balance = current.balance - amount)
        _transactions.add(
            0,
            Transaction(
                id = _transactions.size + 1,
                title = "Transfer to $to",
                amount = -amount,
                date = "2026-09-16"
            )
        )
        return true
    }
}
```

