# 8) `data/FakeBankRepository.kt`

```kotlin
package com.example.bankingapp.data

class FakeBankRepository {

    private var currentUser = User(
        username = "demo",
        fullName = "Demo User",
        balance = 1250.75
    )

    private val transactions = mutableListOf(
        Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
        Transaction(2, "Salary", 2500.00, "2026-09-09"),
        Transaction(3, "Electric Bill", -120.30, "2026-09-08")
    )

    fun login(username: String, password: String): Boolean {
        return username == "demo" && password == "password"
    }

    fun getUser(): User = currentUser

    fun getTransactions(): List<Transaction> = transactions.reversed()

    fun transfer(recipient: String, amount: Double): Boolean {
        if (recipient.isBlank() || amount <= 0 || amount > currentUser.balance) return false

        currentUser = currentUser.copy(balance = currentUser.balance - amount)
        transactions.add(
            Transaction(
                id = transactions.size + 1,
                title = "Transfer to $recipient",
                amount = -amount,
                date = "2026-09-16"
            )
        )
        return true
    }
}
