            TransferScreen(
                message = bankViewModel.transferMessage,
                onTransfer = { recipient, amount ->
                    bankViewModel.transfer(recipient, amount)
                },
                onBack = {
                    bankViewModel.clearTransferMessage()
                    navController.popBackStack()
                }
            )
        }
    }
}
