```kotlin
package com.example.bankingapp.viewmodel

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction

class BankingViewModel : ViewModel() {

    var isLoggedIn = mutableStateOf(false)
        private set

    var accountState = mutableStateOf(
        Account(
            accountNumber = "1234567890",
            accountName = "John Doe",
            balance = 2500.00
        )
    )
        private set

    val transactions = mutableStateListOf(
        Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
        Transaction(2, "Salary", 1500.00, "2026-09-09"),
        Transaction(3, "Groceries", -82.30, "2026-09-08")
    )

    fun login(username: String, password: String): Boolean {
        val success = username == "user" && password == "pass"
        isLoggedIn.value = success
        return success
    }

    fun logout() {
        isLoggedIn.value = false
    }

    fun transfer(recipient: String, amountText: String): String {
        val amount = amountText.toDoubleOrNull()
            ?: return "Invalid amount"

        if (recipient.isBlank()) return "Recipient required"
        if (amount <= 0) return "Amount must be greater than zero"
        if (amount > accountState.value.balance) return "Insufficient funds"

        val updated = accountState.value.copy(
            balance = accountState.value.balance - amount
        )
        accountState.value = updated

        transactions.add(
            0,
            Transaction(
                id = transactions.size + 1,
                title = "Transfer to $recipient",
                amount = -amount,
                date = "2026-09-16"
            )
        )

        return "Transfer successful"
    }
}
