# 8. `data/BankViewModel.kt`

```kotlin
package com.example.bankingapp.data

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel

class BankViewModel : ViewModel() {

    var isLoggedIn by mutableStateOf(false)
        private set

    var username by mutableStateOf("")
        private set

    var balance by mutableStateOf(1250.0)
        private set

    var transactions by mutableStateOf(
        listOf(
            TransactionItem("Salary", 2000.0, TransactionType.CREDIT),
            TransactionItem("Groceries", 120.5, TransactionType.DEBIT),
            TransactionItem("Electric Bill", 75.0, TransactionType.DEBIT)
        )
    )
        private set

    fun login(user: String, password: String): Boolean {
        return if (user.isNotBlank() && password == "1234") {
            username = user
            isLoggedIn = true
            true
        } else {
            false
        }
    }

    fun logout() {
        isLoggedIn = false
        username = ""
    }

    fun transfer(recipient: String, amount: Double): Boolean {
        if (recipient.isBlank() || amount <= 0 || amount > balance) return false

        balance -= amount
        transactions = listOf(
            TransactionItem("Transfer to $recipient", amount, TransactionType.DEBIT)
        ) + transactions
        return true
    }
}
```

