# 9. `ui/BankingApp.kt`

```kotlin
package com.example.bankingapp.ui

import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.bankingapp.data.BankViewModel

enum class AppScreen {
    LOGIN, DASHBOARD, TRANSFER
}

@Composable
fun BankingApp(viewModel: BankViewModel = viewModel()) {
    MaterialTheme {
        Surface {
            when {
                !viewModel.isLoggedIn -> {
                    LoginScreen(
                        onLogin = { user, pass -> viewModel.login(user, pass) }
                    )
                }
                else -> {
                    AppContent(viewModel)
                }
            }
        }
    }
}

@Composable
private fun AppContent(viewModel: BankViewModel) {
    val currentScreen = androidx.compose.runtime.remember {
        androidx.compose.runtime.mutableStateOf(AppScreen.DASHBOARD)
    }

    when (currentScreen.value) {
        AppScreen.DASHBOARD -> DashboardScreen(
            username = viewModel.username,
            balance = viewModel.balance,
            transactions = viewModel.transactions,
            onTransferClick = { currentScreen.value = AppScreen.TRANSFER },
            onLogoutClick = { viewModel.logout() }
        )

        AppScreen.TRANSFER -> TransferScreen(
            balance = viewModel.balance,
            onBack = { currentScreen.value = AppScreen.DASHBOARD },
            onSubmit = { recipient, amount ->
                val success = viewModel.transfer(recipient, amount)
                if (success) currentScreen.value = AppScreen.DASHBOARD
                success
            }
        )

        AppScreen.LOGIN -> Unit
    }
}
```

