## `data/AppDatabase.kt`

```kotlin
package com.example.bankapp.data

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

@Database(entities = [User::class, Transaction::class], version = 1, exportSchema = false)
abstract class AppDatabase : RoomDatabase() {
    abstract fun userDao(): UserDao
    abstract fun transactionDao(): TransactionDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getDatabase(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "bank_db"
                ).build()
                INSTANCE = instance
                instance
            }
        }
    }
}
```

## `data/BankRepository.kt`

```kotlin
package com.example.bankapp.data

class BankRepository(
    private val userDao: UserDao,
    private val transactionDao: TransactionDao
) {
    suspend fun signup(username: String, password: String): Result<User> {
        val existing = userDao.getByUsername(username)
        if (existing != null) return Result.failure(Exception("User already exists"))

        val id = userDao.insert(User(username = username, password = password)).toInt()
        val user = userDao.getById(id) ?: return Result.failure(Exception("Signup failed"))
        return Result.success(user)
    }

    suspend fun login(username: String, password: String): Result<User> {
        val user = userDao.getByUsername(username)
            ?: return Result.failure(Exception("User not found"))
        return if (user.password == password) {
            Result.success(user)
        } else {
            Result.failure(Exception("Invalid password"))
        }
    }

    suspend fun getUser(userId: Int): User? = userDao.getById(userId)

    suspend fun getTransactions(userId: Int): List<Transaction> =
        transactionDao.getForUser(userId)

    suspend fun deposit(userId: Int, amount: Double): Result<User> {
        if (amount <= 0) return Result.failure(Exception("Invalid amount"))
        val user = userDao.getById(userId) ?: return Result.failure(Exception("User not found"))
        val updated = user.copy(balance = user.balance + amount)
        userDao.update(updated)
        transactionDao.insert(
            Transaction(userId = userId, type = "DEPOSIT", amount = amount, description = "Cash deposit")
        )
        return Result.success(updated)
    }

    suspend fun withdraw(userId: Int, amount: Double): Result<User> {
        if (amount <= 0) return Result.failure(Exception("Invalid amount"))
        val user = userDao.getById(userId) ?: return Result.failure(Exception("User not found"))
        if (user.balance < amount) return Result.failure(Exception("Insufficient funds"))

        val updated = user.copy(balance = user.balance - amount)
        userDao.update(updated)
        transactionDao.insert(
            Transaction(userId = userId, type = "WITHDRAW", amount = amount, description = "Cash withdrawal")
        )
        return Result.success(updated)
    }

    suspend fun transfer(fromUserId: Int, toUsername: String, amount: Double): Result<User> {
        if (amount <= 0) return Result.failure(Exception("Invalid amount"))

        val sender = userDao.getById(fromUserId) ?: return Result.failure(Exception("Sender not found"))
        val receiver = userDao.getByUsername(toUsername) ?: return Result.failure(Exception("Recipient not found"))

        if (sender.id == receiver.id) return Result.failure(Exception("Cannot transfer to self"))
        if (sender.balance < amount) return Result.failure(Exception("Insufficient funds"))

        val updatedSender = sender.copy(balance = sender.balance - amount)
        val updatedReceiver = receiver.copy(balance = receiver.balance + amount)

        userDao.update(updatedSender)
        userDao.update(updatedReceiver)

        transactionDao.insert(
            Transaction(
                userId = sender.id,
                type = "TRANSFER_OUT",
                amount = amount,
                description = "Transfer to ${receiver.username}"
            )
        )
        transactionDao.insert(
            Transaction(
                userId = receiver.id,
                type = "TRANSFER_IN",
                amount = amount,
                description = "Transfer from ${sender.username}"
            )
        )

        return Result.success(updatedSender)
    }
}
