```kotlin
package com.example.bankapp.ui

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.BankRepository
import com.example.bankapp.data.Transaction
import com.example.bankapp.data.User
import kotlinx.coroutines.launch

class AppViewModel(private val repository: BankRepository) : ViewModel() {
    var currentUser by mutableStateOf<User?>(null)
        private set

    var transactions by mutableStateOf<List<Transaction>>(emptyList())
        private set

    var message by mutableStateOf("")
        private set

    fun signup(username: String, password: String) {
        viewModelScope.launch {
            val result = repository.signup(username, password)
            result.onSuccess {
                currentUser = it
                loadTransactions()
                message = "Signup successful"
            }.onFailure {
                message = it.message ?: "Signup failed"
            }
        }
    }

    fun login(username: String, password: String) {
        viewModelScope.launch {
            val result = repository.login(username, password)
            result.onSuccess {
                currentUser = it
                loadTransactions()
                message = "Login successful"
            }.onFailure {
                message = it.message ?: "Login failed"
            }
        }
    }

    fun logout() {
        currentUser = null
        transactions = emptyList()
        message = "Logged out"
    }

    fun deposit(amount: Double) {
        val user = currentUser ?: return
        viewModelScope.launch {
            val result = repository.deposit(user.id, amount)
            result.onSuccess {
                currentUser = it
                loadTransactions()
                message = "Deposit successful"
            }.onFailure {
                message = it.message ?: "Deposit failed"
            }
        }
    }

    fun withdraw(amount: Double) {
        val user = currentUser ?: return
        viewModelScope.launch {
            val result = repository.withdraw(user.id, amount)
            result.onSuccess {
                currentUser = it
                loadTransactions()
                message = "Withdrawal successful"
            }.onFailure {
                message = it.message ?: "Withdrawal failed"
            }
        }
    }

    fun transfer(toUsername: String, amount: Double) {
        val user = currentUser ?: return
        viewModelScope.launch {
            val result = repository.transfer(user.id, toUsername, amount)
            result.onSuccess {
                currentUser = it
                loadTransactions()
                message = "Transfer successful"
            }.onFailure {
                message = it.message ?: "Transfer failed"
            }
        }
    }

    fun loadTransactions() {
        val user = currentUser ?: return
        viewModelScope.launch {
            transactions = repository.getTransactions(user.id)
        }
    }
}
