# 6) `BankingApp.kt`

```kotlin
package com.example.bankingapp

import androidx.compose.runtime.*
import androidx.navigation.NavType
import androidx.navigation.compose.*
import com.example.bankingapp.ui.DashboardScreen
import com.example.bankingapp.ui.LoginScreen
import com.example.bankingapp.ui.TransferScreen

data class Transaction(
    val id: Int,
    val title: String,
    val amount: Double,
    val date: String
)

@Composable
fun BankingApp() {
    val navController = rememberNavController()

    var balance by remember { mutableStateOf(2450.75) }
    var transactions by remember {
        mutableStateOf(
            listOf(
                Transaction(1, "Coffee Shop", -4.50, "2026-09-10"),
                Transaction(2, "Salary", 3200.00, "2026-09-01"),
                Transaction(3, "Electric Bill", -120.25, "2026-09-03")
            )
        )
    }

    NavHost(
        navController = navController,
        startDestination = "login"
    ) {
        composable("login") {
            LoginScreen(
                onLogin = { username, password ->
                    if (username.isNotBlank() && password.isNotBlank()) {
                        navController.navigate("dashboard") {
                            popUpTo("login") { inclusive = true }
                        }
                    }
                }
            )
        }

        composable("dashboard") {
            DashboardScreen(
                balance = balance,
                transactions = transactions,
                onTransferClick = {
                    navController.navigate("transfer")
                }
            )
        }

        composable("transfer") {
            TransferScreen(
                onBack = { navController.popBackStack() },
                onSubmitTransfer = { recipient, amount ->
                    if (recipient.isNotBlank() && amount > 0 && amount <= balance) {
                        balance -= amount
                        transactions = listOf(
                            Transaction(
                                id = transactions.size + 1,
                                title = "Transfer to $recipient",
                                amount = -amount,
                                date = "2026-09-16"
                            )
                        ) + transactions
                        navController.popBackStack()
                    }
                }
            )
        }
    }
}
