```kotlin
package com.example.bankapp

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.UUID

object BankRepository {
    private val demoUser = User(
        username = "user",
        password = "pass123",
        fullName = "Alex Johnson"
    )

    var isLoggedIn = mutableStateOf(false)
        private set

    var currentUser = mutableStateOf<User?>(null)
        private set

    private val _accounts = mutableStateListOf(
        Account(id = "1", name = "Checking", balance = 2500.00),
        Account(id = "2", name = "Savings", balance = 5000.00)
    )
    val accounts: List<Account> get() = _accounts

    private val _transactions = mutableStateListOf<TransactionItem>()
    val transactions: List<TransactionItem> get() = _transactions.reversed()

    fun login(username: String, password: String): Boolean {
        val success = username == demoUser.username && password == demoUser.password
        if (success) {
            isLoggedIn.value = true
            currentUser.value = demoUser
        }
        return success
    }

    fun logout() {
        isLoggedIn.value = false
        currentUser.value = null
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        if (fromAccountId == toAccountId) {
            return Result.failure(Exception("Accounts must be different"))
        }
        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        val fromIndex = _accounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = _accounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1) {
            return Result.failure(Exception("Invalid account selection"))
        }

        val from = _accounts[fromIndex]
        val to = _accounts[toIndex]

        if (from.balance < amount) {
            return Result.failure(Exception("Insufficient funds"))
        }

        _accounts[fromIndex] = from.copy(balance = from.balance - amount)
        _accounts[toIndex] = to.copy(balance = to.balance + amount)

        val formatter = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault())
        _transactions.add(
            TransactionItem(
                id = UUID.randomUUID().toString(),
                fromAccount = from.name,
                toAccount = to.name,
                amount = amount,
                timestamp = formatter.format(Date())
            )
        )

        return Result.success(Unit)
    }
}
