# 3. `BankViewModel.kt`

```kotlin
package com.example.bankingapp

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import kotlin.math.roundToInt

class BankViewModel : ViewModel() {

    var isLoggedIn by mutableStateOf(false)
        private set

    var accounts by mutableStateOf(
        listOf(
            Account(id = 1, name = "Checking", balance = 1200.00),
            Account(id = 2, name = "Savings", balance = 5000.00)
        )
    )
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction(
                id = 1,
                description = "Initial deposit",
                amount = 1200.00,
                timestamp = currentTime()
            ),
            Transaction(
                id = 2,
                description = "Savings deposit",
                amount = 5000.00,
                timestamp = currentTime()
            )
        )
    )
        private set

    fun login(username: String, password: String): Boolean {
        isLoggedIn = username == "user" && password == "pass"
        return isLoggedIn
    }

    fun logout() {
        isLoggedIn = false
    }

    fun transfer(fromId: Int, toId: Int, amount: Double): Boolean {
        if (fromId == toId || amount <= 0) return false

        val from = accounts.find { it.id == fromId } ?: return false
        val to = accounts.find { it.id == toId } ?: return false
        if (from.balance < amount) return false

        accounts = accounts.map {
            when (it.id) {
                fromId -> it.copy(balance = round2(it.balance - amount))
                toId -> it.copy(balance = round2(it.balance + amount))
                else -> it
            }
        }

        transactions = listOf(
            Transaction(
                id = transactions.size + 1,
                description = "Transfer from ${from.name} to ${to.name}",
                amount = amount,
                timestamp = currentTime()
            )
        ) + transactions

        return true
    }

    private fun currentTime(): String {
        return SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date())
    }

    private fun round2(value: Double): Double {
        return (value * 100.0).roundToInt() / 100.0
    }
}
