# 5. `data/BankRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransactionType
import com.example.bankingapp.model.User

class BankRepository {
    private val demoUser = User(
        username = "user",
        password = "pass123",
        fullName = "Alex Johnson"
    )

    private val account = Account(
        accountNumber = "1234567890",
        balance = 2500.00
    )

    private val transactions = mutableListOf(
        Transaction(1, "Salary", 3000.00, TransactionType.CREDIT),
        Transaction(2, "Groceries", 120.50, TransactionType.DEBIT),
        Transaction(3, "Electric Bill", 75.20, TransactionType.DEBIT)
    )

    fun login(username: String, password: String): User? {
        return if (username == demoUser.username && password == demoUser.password) {
            demoUser
        } else {
            null
        }
    }

    fun getAccount(): Account = account

    fun getTransactions(): List<Transaction> = transactions.reversed()

    fun transfer(toAccount: String, amount: Double): Boolean {
        if (toAccount.isBlank() || amount <= 0 || amount > account.balance) {
            return false
        }

        account.balance -= amount
        transactions.add(
            Transaction(
                id = transactions.size + 1,
                title = "Transfer to $toAccount",
                amount = amount,
                type = TransactionType.DEBIT
            )
        )
        return true
    }
}
