# 5) Fake repository

## `data/FakeBankRepository.kt`

```kotlin
package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.TransactionItem
import com.example.bankingapp.model.User
import kotlin.math.absoluteValue

class FakeBankRepository {
    private var currentUser: User? = null
    private var currentAccount = Account(
        accountNumber = "1234567890",
        balance = 2450.75,
        transactions = listOf(
            TransactionItem("1", "Coffee Shop", -4.50, "2026-09-10"),
            TransactionItem("2", "Salary", 3000.00, "2026-09-09"),
            TransactionItem("3", "Electric Bill", -120.25, "2026-09-08")
        )
    )

    fun login(username: String, password: String): Boolean {
        return if (username.isNotBlank() && password == "password") {
            currentUser = User(username)
            true
        } else {
            false
        }
    }

    fun getCurrentUser(): User? = currentUser

    fun getAccount(): Account = currentAccount

    fun transfer(recipient: String, amount: Double): Result<Account> {
        if (recipient.isBlank()) {
            return Result.failure(IllegalArgumentException("Recipient is required"))
        }
        if (amount <= 0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than 0"))
        }
        if (amount > currentAccount.balance) {
            return Result.failure(IllegalArgumentException("Insufficient funds"))
        }

        val newBalance = currentAccount.balance - amount
        val newTransaction = TransactionItem(
            id = System.currentTimeMillis().toString(),
            title = "Transfer to $recipient",
            amount = -amount.absoluteValue,
            date = "2026-09-16"
        )

        currentAccount = currentAccount.copy(
            balance = newBalance,
            transactions = listOf(newTransaction) + currentAccount.transactions
        )

        return Result.success(currentAccount)
    }
}
