```kotlin
package com.example.bankingapp

import androidx.compose.runtime.*
import androidx.navigation.compose.*
import com.example.bankingapp.data.FakeBankRepository
import com.example.bankingapp.ui.DashboardScreen
import com.example.bankingapp.ui.LoginScreen
import com.example.bankingapp.ui.TransferScreen

@Composable
fun BankApp() {
    val navController = rememberNavController()
    val repository = remember { FakeBankRepository() }

    NavHost(
        navController = navController,
        startDestination = "login"
    ) {
        composable("login") {
            LoginScreen(
                onLogin = { username, password ->
                    val success = repository.login(username, password)
                    success
                },
                onLoginSuccess = {
                    navController.navigate("dashboard") {
                        popUpTo("login") { inclusive = true }
                    }
                }
            )
        }

        composable("dashboard") {
            DashboardScreen(
                username = repository.getCurrentUser()?.username ?: "User",
                account = repository.getAccount(),
                onTransferClick = {
                    navController.navigate("transfer")
                }
            )
        }

        composable("transfer") {
            TransferScreen(
                onSubmit = { recipient, amount ->
                    repository.transfer(recipient, amount)
                },
                onBack = {
                    navController.popBackStack()
                },
                onTransferSuccess = {
                    navController.popBackStack()
                }
            )
        }
    }
}
