# 5. `BankApp.kt`

This handles simple app state and screen switching.

```kotlin
package com.example.bankdemo

import androidx.compose.runtime.*
import com.example.bankdemo.data.FakeBankRepository
import com.example.bankdemo.model.Account
import com.example.bankdemo.model.Transaction
import com.example.bankdemo.model.User
import com.example.bankdemo.ui.DashboardScreen
import com.example.bankdemo.ui.LoginScreen
import com.example.bankdemo.ui.TransferScreen

private enum class Screen {
    LOGIN, DASHBOARD, TRANSFER
}

@Composable
fun BankApp() {
    val repository = remember { FakeBankRepository() }

    var currentScreen by remember { mutableStateOf(Screen.LOGIN) }
    var user by remember { mutableStateOf<User?>(null) }
    var loginError by remember { mutableStateOf<String?>(null) }
    var transferMessage by remember { mutableStateOf<String?>(null) }

    fun account(): Account = repository.getAccount()
    fun transactions(): List<Transaction> = repository.getTransactions()

    when (currentScreen) {
        Screen.LOGIN -> {
            LoginScreen(
                errorMessage = loginError,
                onLogin = { username, password ->
                    val loggedInUser = repository.login(username, password)
                    if (loggedInUser != null) {
                        user = loggedInUser
                        loginError = null
                        currentScreen = Screen.DASHBOARD
                    } else {
                        loginError = "Invalid username or password"
                    }
                }
            )
        }

        Screen.DASHBOARD -> {
            DashboardScreen(
                user = user!!,
                account = account(),
                transactions = transactions(),
                transferMessage = transferMessage,
                onTransferClick = {
                    transferMessage = null
                    currentScreen = Screen.TRANSFER
                },
                onLogout = {
                    user = null
                    loginError = null
                    transferMessage = null
                    currentScreen = Screen.LOGIN
                }
            )
        }

        Screen.TRANSFER -> {
            TransferScreen(
                onSubmit = { recipient, amount ->
                    val result = repository.transfer(recipient, amount)
                    if (result.isSuccess) {
                        transferMessage = "Transfer successful"
                        currentScreen = Screen.DASHBOARD
                    } else {
                        transferMessage = result.exceptionOrNull()?.message
                        currentScreen = Screen.DASHBOARD
                    }
                },
                onCancel = {
                    currentScreen = Screen.DASHBOARD
                }
            )
        }
    }
}
```

