# 5. Fake repository

## `data/FakeBankRepository.kt`

```kotlin
package com.example.bankingapp.data

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import java.util.UUID

class FakeBankRepository {
    var loggedIn = mutableStateOf(false)
        private set

    private val _accounts = mutableStateListOf(
        Account(
            id = "1",
            name = "Checking Account",
            number = "****1234",
            balance = 2450.75
        ),
        Account(
            id = "2",
            name = "Savings Account",
            number = "****5678",
            balance = 10200.00
        )
    )

    private val _transactions = mutableStateListOf(
        Transaction(UUID.randomUUID().toString(), "Coffee Shop", -4.50, "2026-09-12"),
        Transaction(UUID.randomUUID().toString(), "Salary", 3200.00, "2026-09-10"),
        Transaction(UUID.randomUUID().toString(), "Electric Bill", -89.99, "2026-09-08")
    )

    fun login(username: String, password: String): Boolean {
        val success = username == "user" && password == "pass123"
        loggedIn.value = success
        return success
    }

    fun logout() {
        loggedIn.value = false
    }

    fun getAccounts(): List<Account> = _accounts

    fun getTransactions(): List<Transaction> = _transactions

    fun transfer(fromId: String, toId: String, amount: Double): Boolean {
        if (amount <= 0) return false
        if (fromId == toId) return false

        val fromIndex = _accounts.indexOfFirst { it.id == fromId }
        val toIndex = _accounts.indexOfFirst { it.id == toId }

        if (fromIndex == -1 || toIndex == -1) return false

        val from = _accounts[fromIndex]
        val to = _accounts[toIndex]

        if (from.balance < amount) return false

        _accounts[fromIndex] = from.copy(balance = from.balance - amount)
        _accounts[toIndex] = to.copy(balance = to.balance + amount)

        _transactions.add(
            0,
            Transaction(
                id = UUID.randomUUID().toString(),
                title = "Transfer: ${from.name} → ${to.name}",
                amount = -amount,
                date = "2026-09-16"
            )
        )

        return true
    }
}
```

