package com.example.bankingdemo

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import com.example.bankingdemo.ui.model.Transaction
import com.example.bankingdemo.ui.screens.DashboardScreen
import com.example.bankingdemo.ui.screens.LoginScreen
import com.example.bankingdemo.ui.screens.TransferScreen

sealed class Screen {
    data object Login : Screen()
    data object Dashboard : Screen()
    data object Transfer : Screen()
}

@Composable
fun BankingDemoApp() {
    var currentScreen by remember { mutableStateOf<Screen>(Screen.Login) }
    var balance by remember { mutableStateOf(2450.75) }

    var transactions by remember {
        mutableStateOf(
            listOf(
                Transaction(1, "Coffee Shop", "-$4.50", "2026-09-10"),
                Transaction(2, "Salary", "+$2,500.00", "2026-09-09"),
                Transaction(3, "Groceries", "-$67.20", "2026-09-08")
            )
        )
    }

    MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
            when (currentScreen) {
                Screen.Login -> LoginScreen(
                    onLogin = { _, _ ->
                        currentScreen = Screen.Dashboard
                    }
                )

                Screen.Dashboard -> DashboardScreen(
                    balance = balance,
                    transactions = transactions,
                    onTransferClick = {
                        currentScreen = Screen.Transfer
                    },
                    onLogout = {
                        currentScreen = Screen.Login
                    }
                )

                Screen.Transfer -> TransferScreen(
                    onBack = {
                        currentScreen = Screen.Dashboard
                    },
                    onTransfer = { recipient, amount ->
                        val value = amount.toDoubleOrNull()
                        if (value != null && value > 0 && value <= balance) {
                            balance -= value
                            transactions = listOf(
                                Transaction(
                                    id = transactions.size + 1,
                                    title = "Transfer to $recipient",
                                    amount = "-$${"%.2f".format(value)}",
                                    date = "2026-09-16"
                                )
                            ) + transactions
                        }
                        currentScreen = Screen.Dashboard
                    }
                )
            }
        }
    }
}
