## `sync.js` — sync engine

```javascript
// sync.js
import * as Network from 'expo-network';
import { getPendingSurveys, markSurveySynced } from './db';

const API_URL = 'http://YOUR_SERVER_IP:3000';

export async function isOnline() {
  const state = await Network.getNetworkStateAsync();
  return state.isConnected && state.isInternetReachable !== false;
}

export async function syncPendingSurveys() {
  const online = await isOnline();
  if (!online) {
    console.log('Offline, skipping sync');
    return;
  }

  const pending = getPendingSurveys();
  if (!pending.length) {
    console.log('No pending surveys to sync');
    return;
  }

  for (const survey of pending) {
    try {
      const response = await fetch(`${API_URL}/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(survey),
      });

      if (!response.ok) {
        throw new Error(`Sync failed: ${response.status}`);
      }

      markSurveySynced(survey.id);
      console.log(`Survey ${survey.id} synced`);
    } catch (error) {
      console.error(`Failed to sync survey ${survey.id}:`, error.message);
    }
  }
}
