## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

// Upsert endpoint for sync
app.post('/surveys', (req, res) => {
  const survey = req.body;

  if (!survey.id || !survey.title || !survey.updatedAt) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const existing = surveys.get(survey.id);

  // Last-write-wins conflict strategy
  if (!existing || new Date(survey.updatedAt) >= new Date(existing.updatedAt)) {
    surveys.set(survey.id, survey);
  }

  return res.status(200).json({
    success: true,
    survey: surveys.get(survey.id),
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Survey server running on port ${PORT}`);
});
```

