# 6. Example: Add pull sync

Here’s a simple extension.

## Backend

```javascript
app.get('/surveys/changes', (req, res) => {
  const since = req.query.since;
  const sinceDate = since ? new Date(since) : new Date(0);

  const changed = Array.from(surveys.values()).filter(
    (s) => new Date(s.updatedAt) > sinceDate
  );

  res.json(changed);
});
```

## Frontend DB helper

```javascript
export function getLastSyncTime() {
  const stmt = db.prepareSync(`
    SELECT MAX(updatedAt) as lastSync FROM surveys
  `);
  try {
    const result = stmt.executeSync();
    const row = result.getFirstSync();
    return row?.lastSync || null;
  } finally {
    stmt.finalizeSync();
  }
}
```

## Frontend pull sync

```javascript
import { getLastSyncTime, saveSurvey } from './db';

export async function pullServerChanges() {
  const online = await isOnline();
  if (!online) return;

  const since = getLastSyncTime();
  const url = since
    ? `${API_URL}/surveys/changes?since=${encodeURIComponent(since)}`
    : `${API_URL}/surveys/changes`;

  const response = await fetch(url);
  if (!response.ok) throw new Error('Failed to pull changes');

  const changes = await response.json();

  for (const survey of changes) {
    saveSurvey({
      ...survey,
      syncStatus: 'synced',
    });
  }
}
```

Then call:

```javascript
await syncPendingSurveys();
await pullServerChanges();
```

