```javascript
import React, { useEffect, useState, useCallback } from 'react';
import {
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
  SafeAreaView,
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';

const db = SQLite.openDatabase('surveys.db');
const API_URL = 'http://YOUR_SERVER_IP:3000';

export default function App() {
  const [surveyorName, setSurveyorName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);
      if (online) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  const initDb = () => {
    db.transaction((tx) => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          local_id TEXT NOT NULL,
          server_id TEXT,
          surveyor_name TEXT,
          location TEXT,
          notes TEXT,
          status TEXT NOT NULL,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );`
      );
    });
  };

  const loadSurveys = () => {
    db.transaction((tx) => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY id DESC;',
        [],
        (_, result) => {
          setSurveys(result.rows._array);
        },
        (_, error) => {
          console.error('Load surveys error:', error);
          return false;
        }
      );
    });
  };

  const createSurvey = () => {
    if (!surveyorName || !location) {
      Alert.alert('Validation', 'Surveyor name and location are required.');
      return;
    }

    const now = new Date().toISOString();
    const localId = `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    db.transaction((tx) => {
      tx.executeSql(
        `INSERT INTO surveys
          (local_id, server_id, surveyor_name, location, notes, status, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?);`,
        [localId, null, surveyorName, location, notes, 'pending', now, now],
        () => {
          setSurveyorName('');
          setLocation('');
          setNotes('');
          loadSurveys();

          if (isOnline) {
            syncPendingSurveys();
          }
        },
        (_, error) => {
          console.error('Insert survey error:', error);
          return false;
        }
      );
    });
  };

  const syncPendingSurveys = useCallback(() => {
    if (syncing) return;

    setSyncing(true);

    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE status = 'pending' ORDER BY created_at ASC;`,
        [],
        async (_, result) => {
          const pending = result.rows._array;

          if (pending.length === 0) {
            setSyncing(false);
            return;
          }

          for (const survey of pending) {
            try {
              const response = await fetch(`${API_URL}/surveys/sync`, {
                method: 'POST',
                headers: {
                  'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                  local_id: survey.local_id,
                  surveyor_name: survey.surveyor_name,
                  location: survey.location,
                  notes: survey.notes,
                  created_at: survey.created_at,
                  updated_at: survey.updated_at,
                }),
              });

              if (!response.ok) {
                throw new Error(`Sync failed with status ${response.status}`);
              }

              const data = await response.json();

              db.transaction((innerTx) => {
                innerTx.executeSql(
                  `UPDATE surveys
                   SET status = 'synced', server_id = ?, updated_at = ?
                   WHERE local_id = ?;`,
                  [String(data.server_id), new Date().toISOString(), survey.local_id]
                );
              });
            } catch (error) {
              console.error(`Failed to sync survey ${survey.local_id}:`, error);
            }
          }

          setTimeout(() => {
            loadSurveys();
            setSyncing(false);
          }, 500);
        },
        (_, error) => {
          console.error('Select pending surveys error:', error);
          setSyncing(false);
          return false;
        }
      );
    });
  }, [syncing]);

  const renderItem = ({ item }) => (
    <View style={styles.card}>
      <Text style={styles.title}>{item.surveyor_name}</Text>
      <Text>Location: {item.location}</Text>
      <Text>Notes: {item.notes || '-'}</Text>
      <Text>Status: {item.status}</Text>
      <Text>Local ID: {item.local_id}</Text>
      {item.server_id ? <Text>Server ID: {item.server_id}</Text> : null}
    </View>
  );

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        {isOnline ? 'Online' : 'Offline'} {syncing ? ' • Syncing...' : ''}
      </Text>

      <TextInput
        style={styles.input}
        placeholder="Surveyor Name"
        value={surveyorName}
        onChangeText={setSurveyorName}
      />
      <TextInput
        style={styles.input}
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
      />
      <TextInput
        style={styles.input}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
      />

      <Button title="Save Survey" onPress={createSurvey} />
      <View style={{ height: 16 }} />
      <Button title="Manual Sync" onPress={syncPendingSurveys} disabled={!isOnline || syncing} />

      <Text style={styles.subheader}>Saved Surveys</Text>
      <FlatList
        data={surveys}
        keyExtractor={(item) => item.local_id}
        renderItem={renderItem}
        contentContainerStyle={{ paddingBottom: 40 }}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
    marginTop: 30,
  },
  header: {
    fontSize: 26,
    fontWeight: 'bold',
    marginBottom: 8,
  },
  status: {
    marginBottom: 16,
    color: '#666',
  },
  subheader: {
    marginTop: 24,
    marginBottom: 12,
    fontSize: 20,
    fontWeight: '600',
  },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    padding: 12,
    borderRadius: 8,
    marginBottom: 12,
  },
  card: {
    padding: 12,
    borderRadius: 8,
    backgroundColor: '#f3f3f3',
    marginBottom: 10,
  },
  title: {
    fontWeight: 'bold',
    fontSize: 16,
    marginBottom: 4,
  },
});
