## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

let surveys = [];
let nextId = 1;

// Idempotent sync endpoint using local_id
app.post('/surveys/sync', (req, res) => {
  const {
    local_id,
    surveyor_name,
    location,
    notes,
    created_at,
    updated_at,
  } = req.body;

  if (!local_id || !surveyor_name || !location) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const existing = surveys.find((s) => s.local_id === local_id);

  if (existing) {
    existing.surveyor_name = surveyor_name;
    existing.location = location;
    existing.notes = notes;
    existing.updated_at = updated_at;

    return res.json({
      success: true,
      server_id: existing.id,
      message: 'Survey already existed, updated instead',
    });
  }

  const survey = {
    id: nextId++,
    local_id,
    surveyor_name,
    location,
    notes,
    created_at,
    updated_at,
    received_at: new Date().toISOString(),
  };

  surveys.push(survey);

  return res.json({
    success: true,
    server_id: survey.id,
    message: 'Survey synced successfully',
  });
});

app.get('/surveys', (req, res) => {
  res.json(surveys);
});

app.listen(3000, () => {
  console.log('Survey sync server running on port 3000');
});
```

