# 4. Survey repository

## `src/repositories/surveyRepository.ts`

```ts
import db from '../db/database';
import { Survey } from '../types/survey';

export const surveyRepository = {
  getAll(): Survey[] {
    const rows = db.getAllSync<Survey>(
      `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
    );
    return rows;
  },

  getById(id: string): Survey | null {
    const row = db.getFirstSync<Survey>(
      `SELECT * FROM surveys WHERE id = ? LIMIT 1`,
      [id]
    );
    return row ?? null;
  },

  upsert(survey: Survey) {
    db.runSync(
      `INSERT INTO surveys (id, title, location, notes, updatedAt, deletedAt, syncStatus)
       VALUES (?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         title = excluded.title,
         location = excluded.location,
         notes = excluded.notes,
         updatedAt = excluded.updatedAt,
         deletedAt = excluded.deletedAt,
         syncStatus = excluded.syncStatus`,
      [
        survey.id,
        survey.title,
        survey.location,
        survey.notes,
        survey.updatedAt,
        survey.deletedAt ?? null,
        survey.syncStatus,
      ]
    );
  },

  markDeleted(id: string, deletedAt: string, syncStatus: Survey['syncStatus']) {
    db.runSync(
      `UPDATE surveys
       SET deletedAt = ?, updatedAt = ?, syncStatus = ?
       WHERE id = ?`,
      [deletedAt, deletedAt, syncStatus, id]
    );
  },

  markSynced(id: string, updatedAt?: string) {
    if (updatedAt) {
      db.runSync(
        `UPDATE surveys SET syncStatus = 'synced', updatedAt = ? WHERE id = ?`,
        [updatedAt, id]
      );
    } else {
      db.runSync(
        `UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`,
        [id]
      );
    }
  },

  setSyncStatus(id: string, status: Survey['syncStatus']) {
    db.runSync(
      `UPDATE surveys SET syncStatus = ? WHERE id = ?`,
      [status, id]
    );
  },

  replaceAllFromServer(surveys: Survey[]) {
    db.withTransactionSync(() => {
      for (const survey of surveys) {
        this.upsert({
          ...survey,
          syncStatus: 'synced',
        });
      }
    });
  },

  getPending(): Survey[] {
    return db.getAllSync<Survey>(
      `SELECT * FROM surveys WHERE syncStatus IN ('pending', 'failed')`
    );
  },
};
```

