import db from '../db/database';
import { SyncQueueItem } from '../types/survey';

export const syncQueueRepository = {
  add(item: SyncQueueItem) {
    db.runSync(
      `INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt, retries)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        item.id,
        item.entityType,
        item.entityId,
        item.action,
        item.payload,
        item.createdAt,
        item.retries,
      ]
    );
  },

  getAll(): SyncQueueItem[] {
    return db.getAllSync<SyncQueueItem>(
      `SELECT * FROM sync_queue ORDER BY createdAt ASC`
    );
  },

  remove(id: string) {
    db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
  },

  incrementRetries(id: string) {
    db.runSync(
      `UPDATE sync_queue SET retries = retries + 1 WHERE id = ?`,
      [id]
    );
  },

  clearForEntity(entityId: string) {
    db.runSync(`DELETE FROM sync_queue WHERE entityId = ?`, [entityId]);
  },
};
