# 8. Sync service

This is the heart of the offline-first behavior.

## `src/services/sync.ts`

```ts
import AsyncStorage from '@react-native-async-storage/async-storage';
import { surveyRepository } from '../repositories/surveyRepository';
import { syncQueueRepository } from '../repositories/syncQueueRepository';
import { pullSurveys, pushSurveyChange } from './api';
import { Survey, SyncQueueItem } from '../types/survey';

const LAST_SYNC_KEY = 'LAST_SYNC_AT';

export async function syncAll() {
  await pushPendingChanges();
  await pullLatestChanges();
}

async function pushPendingChanges() {
  const queue = syncQueueRepository.getAll();

  for (const item of queue) {
    try {
      const survey: Survey = JSON.parse(item.payload);

      await pushSurveyChange(item.action, survey);

      surveyRepository.markSynced(item.entityId);
      syncQueueRepository.remove(item.id);
    } catch (error) {
      console.error('Failed to sync queue item', item.id, error);
      surveyRepository.setSyncStatus(item.entityId, 'failed');
      syncQueueRepository.incrementRetries(item.id);
    }
  }
}

async function pullLatestChanges() {
  const lastSyncAt = await AsyncStorage.getItem(LAST_SYNC_KEY);
  const serverSurveys = await pullSurveys(lastSyncAt || undefined);

  for (const serverSurvey of serverSurveys) {
    const local = surveyRepository.getById(serverSurvey.id);

    // Simple conflict strategy: latest updatedAt wins
    if (!local) {
      surveyRepository.upsert({
        ...serverSurvey,
        syncStatus: 'synced',
      });
      continue;
    }

    const localTime = new Date(local.updatedAt).getTime();
    const serverTime = new Date(serverSurvey.updatedAt).getTime();

    if (serverTime >= localTime && local.syncStatus === 'synced') {
      surveyRepository.upsert({
        ...serverSurvey,
        syncStatus: 'synced',
      });
    }
  }

  await AsyncStorage.setItem(LAST_SYNC_KEY, new Date().toISOString());
}
```

