# 9. Survey data operations

These functions write locally first and queue sync actions.

## `src/hooks/useSurveys.ts`

```ts
import { useCallback, useEffect, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Survey, SyncQueueItem } from '../types/survey';
import { surveyRepository } from '../repositories/surveyRepository';
import { syncQueueRepository } from '../repositories/syncQueueRepository';
import { syncAll } from '../services/sync';

export function useSurveys() {
  const [surveys, setSurveys] = useState<Survey[]>([]);

  const refresh = useCallback(() => {
    setSurveys(surveyRepository.getAll());
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const createSurvey = useCallback(
    async (input: Omit<Survey, 'id' | 'updatedAt' | 'syncStatus'>) => {
      const now = new Date().toISOString();

      const survey: Survey = {
        id: uuidv4(),
        title: input.title,
        location: input.location,
        notes: input.notes,
        deletedAt: null,
        updatedAt: now,
        syncStatus: 'pending',
      };

      const queueItem: SyncQueueItem = {
        id: uuidv4(),
        entityType: 'survey',
        entityId: survey.id,
        action: 'create',
        payload: JSON.stringify(survey),
        createdAt: now,
        retries: 0,
      };

      surveyRepository.upsert(survey);
      syncQueueRepository.add(queueItem);
      refresh();

      try {
        await syncAll();
        refresh();
      } catch {
        // stay offline-safe
      }
    },
    [refresh]
  );

  const updateSurvey = useCallback(
    async (id: string, updates: Partial<Pick<Survey, 'title' | 'location' | 'notes'>>) => {
      const existing = surveyRepository.getById(id);
      if (!existing) return;

      const updated: Survey = {
        ...existing,
        ...updates,
        updatedAt: new Date().toISOString(),
        syncStatus: 'pending',
      };

      const queueItem: SyncQueueItem = {
        id: uuidv4(),
        entityType: 'survey',
        entityId: updated.id,
        action: 'update',
        payload: JSON.stringify(updated),
        createdAt: updated.updatedAt,
        retries: 0,
      };

      surveyRepository.upsert(updated);
      syncQueueRepository.add(queueItem);
      refresh();

      try {
        await syncAll();
        refresh();
      } catch {
        // offline-safe
      }
    },
    [refresh]
  );

  const deleteSurvey = useCallback(
    async (id: string) => {
      const existing = surveyRepository.getById(id);
      if (!existing) return;

      const now = new Date().toISOString();

      const deletedSurvey: Survey = {
        ...existing,
        deletedAt: now,
        updatedAt: now,
        syncStatus: 'pending',
      };

      const queueItem: SyncQueueItem = {
        id: uuidv4(),
        entityType: 'survey',
        entityId: id,
        action: 'delete',
        payload: JSON.stringify(deletedSurvey),
        createdAt: now,
        retries: 0,
      };

      surveyRepository.markDeleted(id, now, 'pending');
      syncQueueRepository.add(queueItem);
      refresh();

      try {
        await syncAll();
        refresh();
      } catch {
        // offline-safe
      }
    },
    [refresh]
  );

  return {
    surveys,
    refresh,
    createSurvey,
    updateSurvey,
    deleteSurvey,
  };
}
```

