# Optional: improved queue deduplication example

Here’s a more production-friendly queue enqueue helper.

## `src/repositories/enqueueSurveyChange.ts`

```ts
import { v4 as uuidv4 } from 'uuid';
import db from '../db/database';
import { Survey, SyncQueueItem } from '../types/survey';

export function enqueueSurveyChange(
  action: 'create' | 'update' | 'delete',
  survey: Survey
) {
  const existing = db.getAllSync<SyncQueueItem>(
    `SELECT * FROM sync_queue
     WHERE entityType = 'survey' AND entityId = ?
     ORDER BY createdAt ASC`,
    [survey.id]
  );

  db.withTransactionSync(() => {
    for (const item of existing) {
      db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);
    }

    let finalAction: 'create' | 'update' | 'delete' = action;

    if (existing.some((i) => i.action === 'create') && action === 'update') {
      finalAction = 'create';
    }

    const queueItem: SyncQueueItem = {
      id: uuidv4(),
      entityType: 'survey',
      entityId: survey.id,
      action: finalAction,
      payload: JSON.stringify(survey),
      createdAt: new Date().toISOString(),
      retries: 0,
    };

    db.runSync(
      `INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt, retries)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        queueItem.id,
        queueItem.entityType,
        queueItem.entityId,
        queueItem.action,
        queueItem.payload,
        queueItem.createdAt,
        queueItem.retries,
      ]
    );
  });
}
```

Then replace direct `syncQueueRepository.add(...)` calls with `enqueueSurveyChange(...)`.

