const express = require('express');
const app = express();
app.use(express.json());

let surveys = [];

app.post('/surveys', (req, res) => {
  const survey = req.body;
  surveys = surveys.filter((s) => s.id !== survey.id);
  surveys.push({ ...survey, updatedAt: new Date().toISOString() });
  res.status(201).json({ ok: true });
});

app.put('/surveys/:id', (req, res) => {
  const survey = req.body;
  surveys = surveys.filter((s) => s.id !== req.params.id);
  surveys.push({ ...survey, updatedAt: new Date().toISOString() });
  res.json({ ok: true });
});

app.delete('/surveys/:id', (req, res) => {
  surveys = surveys.map((s) =>
    s.id === req.params.id
      ? { ...s, deletedAt: new Date().toISOString(), updatedAt: new Date().toISOString() }
      : s
  );
  res.json({ ok: true });
});

app.get('/surveys', (req, res) => {
  const since = req.query.since;
  if (!since) return res.json(surveys);

  const sinceTime = new Date(since).getTime();
  const filtered = surveys.filter(
    (s) => new Date(s.updatedAt).getTime() > sinceTime
  );
  res.json(filtered);
});

