## `surveyRepository.ts`

```ts
import { getDB } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  title: string;
  locationLat: number | null;
  locationLng: number | null;
  notes: string;
  updatedAt: number;
  deleted: number;
  version: number;
};

export async function getAllSurveys(): Promise<Survey[]> {
  const db = getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  const surveys: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    surveys.push(result.rows.item(i));
  }
  return surveys;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = getDB();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (result.rows.length === 0) return null;
  return result.rows.item(0);
}

export async function upsertLocalSurvey(
  survey: Partial<Survey> & { id?: string; title: string }
): Promise<Survey> {
  const db = getDB();
  const now = Date.now();
  const id = survey.id ?? uuidv4();

  const existing = await getSurveyById(id);
  const next: Survey = {
    id,
    title: survey.title,
    locationLat: survey.locationLat ?? null,
    locationLng: survey.locationLng ?? null,
    notes: survey.notes ?? '',
    updatedAt: now,
    deleted: 0,
    version: existing ? existing.version + 1 : 1,
  };

  await db.executeSql(
    `
    INSERT OR REPLACE INTO surveys
    (id, title, locationLat, locationLng, notes, updatedAt, deleted, version)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `,
    [
      next.id,
      next.title,
      next.locationLat,
      next.locationLng,
      next.notes,
      next.updatedAt,
      next.deleted,
      next.version,
    ]
  );

  return next;
}

export async function markSurveyDeleted(id: string): Promise<void> {
  const db = getDB();
  const existing = await getSurveyById(id);
  if (!existing) return;

  await db.executeSql(
    `
    UPDATE surveys
    SET deleted = 1, updatedAt = ?, version = ?
    WHERE id = ?
    `,
    [Date.now(), existing.version + 1, id]
  );
}

export async function applyRemoteSurvey(survey: Survey): Promise<void> {
  const db = getDB();
  const local = await getSurveyById(survey.id);

  if (!local || survey.version >= local.version || survey.updatedAt > local.updatedAt) {
    await db.executeSql(
      `
      INSERT OR REPLACE INTO surveys
      (id, title, locationLat, locationLng, notes, updatedAt, deleted, version)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `,
      [
        survey.id,
        survey.title,
        survey.locationLat,
        survey.locationLng,
        survey.notes,
        survey.updatedAt,
        survey.deleted,
        survey.version,
      ]
    );
  }
}
