## `syncQueueRepository.ts`

```ts
import { getDB } from './db';
import { v4 as uuidv4 } from 'uuid';

export type QueueOperation = 'create' | 'update' | 'delete';

export type SyncQueueItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: QueueOperation;
  payload: string;
  createdAt: number;
  synced: number;
};

export async function enqueueChange(
  entityId: string,
  operation: QueueOperation,
  payload: object
) {
  const db = getDB();
  const item: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId,
    operation,
    payload: JSON.stringify(payload),
    createdAt: Date.now(),
    synced: 0,
  };

  await db.executeSql(
    `
    INSERT INTO sync_queue
    (id, entityType, entityId, operation, payload, createdAt, synced)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    `,
    [
      item.id,
      item.entityType,
      item.entityId,
      item.operation,
      item.payload,
      item.createdAt,
      item.synced,
    ]
  );
}

export async function getPendingQueueItems(): Promise<SyncQueueItem[]> {
  const db = getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue WHERE synced = 0 ORDER BY createdAt ASC`
  );

  const items: SyncQueueItem[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function markQueueItemsSynced(ids: string[]) {
  if (ids.length === 0) return;
  const db = getDB();
  const placeholders = ids.map(() => '?').join(',');
  await db.executeSql(
    `UPDATE sync_queue SET synced = 1 WHERE id IN (${placeholders})`,
    ids
  );
}
```

