## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import { getPendingQueueItems, markQueueItemsSynced } from './syncQueueRepository';
import { applyRemoteSurvey } from './surveyRepository';
import { getMetadata, setMetadata } from './metadataRepository';

const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

let syncInProgress = false;

export async function syncNow() {
  if (syncInProgress) return;
  syncInProgress = true;

  try {
    const net = await NetInfo.fetch();
    if (!net.isConnected) return;

    const pending = await getPendingQueueItems();
    const lastSync = await getMetadata('lastSyncAt');
    const lastSyncAt = lastSync ? Number(lastSync) : 0;

    const pushPayload = pending.map(item => ({
      queueId: item.id,
      entityType: item.entityType,
      entityId: item.entityId,
      operation: item.operation,
      payload: JSON.parse(item.payload),
      createdAt: item.createdAt,
    }));

    const response = await axios.post(`${API_BASE_URL}/sync`, {
      lastSyncAt,
      changes: pushPayload,
    });

    const { acknowledgedQueueIds, remoteChanges, serverTime } = response.data;

    await markQueueItemsSynced(acknowledgedQueueIds);

    for (const change of remoteChanges) {
      if (change.entityType === 'survey') {
        await applyRemoteSurvey(change.payload);
      }
    }

    await setMetadata('lastSyncAt', String(serverTime));
  } catch (err) {
    console.error('Sync failed', err);
  } finally {
    syncInProgress = false;
  }
}

export function startSyncListener() {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncNow();
    }
  });
}
```

