## `server.js`

```js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

/**
 * In production use PostgreSQL, MySQL, MongoDB, etc.
 * This in-memory store is just for demonstration.
 */
const surveys = new Map();
/**
 * changeLog entries:
 * {
 *   entityType: 'survey',
 *   entityId: string,
 *   payload: surveyObject,
 *   updatedAt: number
 * }
 */
const changeLog = [];

app.post('/sync', (req, res) => {
  const { lastSyncAt = 0, changes = [] } = req.body;
  const acknowledgedQueueIds = [];
  const conflicts = [];

  for (const change of changes) {
    const { queueId, entityId, operation, payload } = change;

    const existing = surveys.get(entityId);

    if (!existing) {
      if (operation === 'delete') {
        acknowledgedQueueIds.push(queueId);
        continue;
      }

      surveys.set(entityId, payload);
      changeLog.push({
        entityType: 'survey',
        entityId,
        payload,
        updatedAt: payload.updatedAt,
      });
      acknowledgedQueueIds.push(queueId);
      continue;
    }

    // Simple conflict resolution:
    // accept newer version or newer updatedAt
    const isNewer =
      payload.version > existing.version ||
      payload.updatedAt > existing.updatedAt;

    if (isNewer) {
      surveys.set(entityId, payload);
      changeLog.push({
        entityType: 'survey',
        entityId,
        payload,
        updatedAt: payload.updatedAt,
      });
      acknowledgedQueueIds.push(queueId);
    } else {
      conflicts.push({
        queueId,
        entityId,
        serverRecord: existing,
        clientRecord: payload,
      });
    }
  }

  const remoteChanges = changeLog.filter(change => change.updatedAt > lastSyncAt);

  res.json({
    acknowledgedQueueIds,
    conflicts,
    remoteChanges,
    serverTime: Date.now(),
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

