# 9. Optional queue compaction example

Here’s a simple compaction helper:

```ts
type QueuedChange = {
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
};

export function compactChanges(changes: QueuedChange[]): QueuedChange[] {
  const map = new Map<string, QueuedChange>();

  for (const change of changes) {
    const existing = map.get(change.entityId);

    if (!existing) {
      map.set(change.entityId, change);
      continue;
    }

    if (existing.operation === 'create' && change.operation === 'update') {
      map.set(change.entityId, {
        ...change,
        operation: 'create',
      });
      continue;
    }

    if (
      (existing.operation === 'create' || existing.operation === 'update') &&
      change.operation === 'delete'
    ) {
      if (existing.operation === 'create') {
        map.delete(change.entityId);
      } else {
        map.set(change.entityId, change);
      }
      continue;
    }

    if (existing.operation === 'update' && change.operation === 'update') {
      map.set(change.entityId, change);
      continue;
    }

    map.set(change.entityId, change);
  }

  return Array.from(map.values());
}
```

