  useEffect(() => {
    initDatabase();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener(state => {
      const online = !!state.isConnected;
      setIsConnected(online);

      if (online) {
        syncAndReload();
      }
    });

    return () => unsubscribe();
