## `db.js`

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('surveys.db');

export const initDB = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          local_id TEXT UNIQUE,
          server_id TEXT,
          name TEXT,
          location TEXT,
          notes TEXT,
          created_at TEXT,
          updated_at TEXT,
          sync_status TEXT
        );`,
        [],
        () => resolve(),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const insertSurvey = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys 
          (local_id, server_id, name, location, notes, created_at, updated_at, sync_status)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.local_id,
          survey.server_id || null,
          survey.name,
          survey.location,
          survey.notes,
          survey.created_at,
          survey.updated_at,
          survey.sync_status,
        ],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY created_at DESC`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const getPendingSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE sync_status = 'pending'`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};

export const markAsSynced = (local_id, server_id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET sync_status = 'synced', server_id = ?, updated_at = ?
         WHERE local_id = ?`,
        [server_id, new Date().toISOString(), local_id],
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
};
```

