import { getPendingSurveys, markAsSynced } from './db';
import { uploadSurvey } from './api';

let syncing = false;

export const syncPendingSurveys = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const pending = await getPendingSurveys();

    for (const survey of pending) {
      try {
        const result = await uploadSurvey(survey);
        await markAsSynced(survey.local_id, result.server_id);
      } catch (err) {
        console.error(`Failed to sync survey ${survey.local_id}:`, err.message);
      }
    }
  } finally {
    syncing = false;
