const express = require('express');
const cors = require('cors');
const { randomUUID } = require('crypto');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/surveys', (req, res) => {
  const survey = req.body;

  if (!survey.local_id || !survey.name || !survey.location) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Idempotency: if same local_id already synced, return existing server_id
  for (const [serverId, existing] of surveys.entries()) {
    if (existing.local_id === survey.local_id) {
      return res.json({ server_id: serverId, status: 'already_synced' });
    }
  }

  const server_id = randomUUID();

  surveys.set(server_id, {
    ...survey,
    server_id,
    received_at: new Date().toISOString(),
  });

  res.json({ server_id, status: 'synced' });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

