## Queue-based `sync.js`

```javascript
import {
  getQueueItems,
  removeQueueItem,
  incrementQueueRetry,
  markAsSynced,
} from './db';
import { uploadSurvey } from './api';

let syncing = false;

export const syncPendingSurveys = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const queue = await getQueueItems();

    for (const item of queue) {
      try {
        const payload = JSON.parse(item.payload);

        if (item.entity_type === 'survey' && item.operation_type === 'create') {
          const result = await uploadSurvey(payload);
          await markAsSynced(payload.local_id, result.server_id);
          await removeQueueItem(item.id);
        }
      } catch (err) {
        await incrementQueueRetry(item.id, err.message);
      }
    }
  } finally {
    syncing = false;
  }
};
```

