# `sync.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import { getPendingSurveys, markSurveySynced } from './db';
import { uploadSurvey } from './api';

let syncing = false;

export const syncPendingSurveys = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const netState = await NetInfo.fetch();
    if (!netState.isConnected) {
      syncing = false;
      return;
    }

    const pending = await getPendingSurveys();

    for (const survey of pending) {
      try {
        await uploadSurvey(survey);
        await markSurveySynced(survey.id);
      } catch (err) {
        console.log(`Failed to sync survey ${survey.id}:`, err.message);
      }
    }
  } finally {
    syncing = false;
  }
};

export const startSyncListener = () => {
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncPendingSurveys();
    }
  });

  return unsubscribe;
};
```

