  useEffect(() => {
    initDB();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener(state => {
      const online = !!state.isConnected;
      setIsOnline(online);

      if (online) {
        syncPendingSurveys().then(loadSurveys);
      }
    });

    syncPendingSurveys().then(loadSurveys);

    return () => unsubscribe();
  }, []);

