## `surveyRepository.ts` — local CRUD + queueing

```ts
import { getDB } from './db';
import { Survey } from './types';
import { v4 as uuidv4 } from 'uuid';

function now() {
  return new Date().toISOString();
}

async function enqueue(entityId: string, operation: 'create' | 'update' | 'delete', payload: object) {
  const db = getDB();
  const queueId = uuidv4();

  await db.executeSql(
    `INSERT INTO sync_queue (id, entity_type, entity_id, operation, payload, created_at, retry_count)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [queueId, 'survey', entityId, operation, JSON.stringify(payload), now()]
  );
}

export async function createSurvey(data: Omit<Survey, 'id' | 'created_at' | 'updated_at' | 'sync_status'>) {
  const db = getDB();
  const id = uuidv4();
  const timestamp = now();

  const survey: Survey = {
    id,
    server_id: null,
    title: data.title,
    location_lat: data.location_lat ?? null,
    location_lng: data.location_lng ?? null,
    notes: data.notes ?? null,
    status: 'active',
    created_at: timestamp,
    updated_at: timestamp,
    sync_status: 'pending',
  };

  await db.executeSql(
    `INSERT INTO surveys
      (id, server_id, title, location_lat, location_lng, notes, status, created_at, updated_at, sync_status)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.server_id,
      survey.title,
      survey.location_lat,
      survey.location_lng,
      survey.notes,
      survey.status,
      survey.created_at,
      survey.updated_at,
      survey.sync_status,
    ]
  );

  await enqueue(id, 'create', survey);
  return survey;
}

export async function updateSurvey(id: string, updates: Partial<Survey>) {
  const db = getDB();
  const timestamp = now();

  const result = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  const row = result[0].rows.item(0);
  if (!row) throw new Error('Survey not found');

  const merged: Survey = {
    ...row,
    ...updates,
    updated_at: timestamp,
    sync_status: 'pending',
  };

  await db.executeSql(
    `UPDATE surveys
     SET title = ?, location_lat = ?, location_lng = ?, notes = ?, status = ?, updated_at = ?, sync_status = ?
     WHERE id = ?`,
    [
      merged.title,
      merged.location_lat,
      merged.location_lng,
      merged.notes,
      merged.status,
      merged.updated_at,
      merged.sync_status,
      id,
    ]
  );

  await enqueue(id, row.server_id ? 'update' : 'create', merged);
  return merged;
}

export async function deleteSurvey(id: string) {
  const db = getDB();

  const result = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  const row = result[0].rows.item(0);
  if (!row) throw new Error('Survey not found');

  if (!row.server_id) {
    await db.executeSql(`DELETE FROM surveys WHERE id = ?`, [id]);
    await db.executeSql(`DELETE FROM sync_queue WHERE entity_id = ?`, [id]);
    return;
  }

  const timestamp = now();
  await db.executeSql(
    `UPDATE surveys SET status = ?, updated_at = ?, sync_status = ? WHERE id = ?`,
    ['deleted', timestamp, 'pending', id]
  );

  await enqueue(id, 'delete', { id, server_id: row.server_id, updated_at: timestamp });
}

export async function listSurveys(): Promise<Survey[]> {
  const db = getDB();
  const result = await db.executeSql(
    `SELECT * FROM surveys WHERE status != 'deleted' ORDER BY updated_at DESC`
  );

  const rows = result[0].rows;
  const items: Survey[] = [];
  for (let i = 0; i < rows.length; i++) {
    items.push(rows.item(i));
  }
  return items;
}
```

