## `syncService.ts` — sync queue processing

```ts
import NetInfo from '@react-native-community/netinfo';
import { getDB } from './db';

const API_BASE = 'http://YOUR_SERVER_IP:3000';

async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return !!state.isConnected;
}

export async function processSyncQueue() {
  const online = await isOnline();
  if (!online) return;

  const db = getDB();
  const result = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY created_at ASC`
  );

  const rows = result[0].rows;

  for (let i = 0; i < rows.length; i++) {
    const item = rows.item(i);

    try {
      const payload = JSON.parse(item.payload);

      let response;
      if (item.operation === 'create') {
        response = await fetch(`${API_BASE}/surveys`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.operation === 'update') {
        response = await fetch(`${API_BASE}/surveys/${payload.server_id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.operation === 'delete') {
        response = await fetch(`${API_BASE}/surveys/${payload.server_id}`, {
          method: 'DELETE',
        });
      }

      if (!response || !response.ok) {
        throw new Error(`Sync failed with status ${response?.status}`);
      }

      const responseData = item.operation !== 'delete' ? await response.json() : null;

      if (item.operation === 'create') {
        await db.executeSql(
          `UPDATE surveys SET server_id = ?, sync_status = 'synced' WHERE id = ?`,
          [responseData.server_id, item.entity_id]
        );
      } else if (item.operation === 'update') {
        await db.executeSql(
          `UPDATE surveys SET sync_status = 'synced' WHERE id = ?`,
          [item.entity_id]
        );
      } else if (item.operation === 'delete') {
        await db.executeSql(`DELETE FROM surveys WHERE id = ?`, [item.entity_id]);
      }

      await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);
    } catch (error) {
      await db.executeSql(
        `UPDATE sync_queue SET retry_count = retry_count + 1 WHERE id = ?`,
        [item.id]
      );
      await db.executeSql(
        `UPDATE surveys SET sync_status = 'failed' WHERE id = ?`,
        [item.entity_id]
      );
      console.error('Sync error:', error);
    }
  }
}

export function startSyncListener() {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      processSyncQueue().catch(console.error);
    }
  });
}
```

