## `server.js`

```js
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Create survey
 */
app.post('/surveys', (req, res) => {
  const body = req.body;
  const serverId = uuidv4();

  const survey = {
    server_id: serverId,
    client_id: body.id,
    title: body.title,
    location_lat: body.location_lat ?? null,
    location_lng: body.location_lng ?? null,
    notes: body.notes ?? null,
    status: body.status || 'active',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  surveys.set(serverId, survey);

  res.status(201).json({
    message: 'Created',
    server_id: serverId,
    survey,
  });
});

/**
 * Update survey
 */
app.put('/surveys/:serverId', (req, res) => {
  const { serverId } = req.params;
  if (!surveys.has(serverId)) {
    return res.status(404).json({ error: 'Survey not found' });
  }

  const existing = surveys.get(serverId);
  const updated = {
    ...existing,
    ...req.body,
    server_id: serverId,
    updated_at: new Date().toISOString(),
  };

  surveys.set(serverId, updated);
  res.json(updated);
});

/**
 * Delete survey
 */
app.delete('/surveys/:serverId', (req, res) => {
  const { serverId } = req.params;
  if (!surveys.has(serverId)) {
    return res.status(404).json({ error: 'Survey not found' });
  }

  surveys.delete(serverId);
  res.status(204).send();
});

/**
 * Optional: fetch all surveys
 */
app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

