# 7. Example pull-sync endpoint

A more realistic backend should support incremental sync:

```js
app.get('/sync', (req, res) => {
  const since = req.query.since;
  const all = Array.from(surveys.values());

  const changed = since
    ? all.filter(item => new Date(item.updated_at) > new Date(since))
    : all;

  res.json({
    server_time: new Date().toISOString(),
    surveys: changed,
  });
});
```

And client-side:

```ts
export async function pullRemoteChanges(lastSyncTime: string | null) {
  const db = getDB();
  const url = lastSyncTime
    ? `${API_BASE}/sync?since=${encodeURIComponent(lastSyncTime)}`
    : `${API_BASE}/sync`;

  const response = await fetch(url);
  if (!response.ok) throw new Error('Failed to pull remote changes');

  const data = await response.json();

  for (const survey of data.surveys) {
    const result = await db.executeSql(
      `SELECT * FROM surveys WHERE server_id = ?`,
      [survey.server_id]
    );

    if (result[0].rows.length === 0) {
      await db.executeSql(
        `INSERT INTO surveys
        (id, server_id, title, location_lat, location_lng, notes, status, created_at, updated_at, sync_status)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.client_id || survey.server_id,
          survey.server_id,
          survey.title,
          survey.location_lat,
          survey.location_lng,
          survey.notes,
          survey.status,
          survey.created_at,
          survey.updated_at,
          'synced',
        ]
      );
    } else {
      await db.executeSql(
        `UPDATE surveys
         SET title = ?, location_lat = ?, location_lng = ?, notes = ?, status = ?, updated_at = ?, sync_status = 'synced'
         WHERE server_id = ?`,
        [
          survey.title,
          survey.location_lat,
          survey.location_lng,
          survey.notes,
          survey.status,
          survey.updated_at,
          survey.server_id,
        ]
      );
    }
  }

  return data.server_time;
}
```

