## `surveyRepository.js`

Handles local CRUD and queueing sync operations.

```javascript
// surveyRepository.js
import db from './db';
import { v4 as uuidv4 } from 'uuid';

export const createSurvey = (title, location, notes) => {
  return new Promise((resolve, reject) => {
    const id = uuidv4();
    const updatedAt = Date.now();

    const survey = {
      id,
      server_id: null,
      title,
      location,
      notes,
      updated_at: updatedAt,
      sync_status: 'pending'
    };

    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, server_id, title, location, notes, updated_at, sync_status)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.server_id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updated_at,
          survey.sync_status
        ]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (entity_type, entity_id, operation, payload, created_at, status)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [
          'survey',
          survey.id,
          'upsert',
          JSON.stringify(survey),
          updatedAt,
          'pending'
        ]
      );
    }, reject, () => resolve(survey));
  });
};

export const updateSurvey = (id, fields) => {
  return new Promise((resolve, reject) => {
    const updatedAt = Date.now();

    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE id = ?`,
        [id],
        (_, result) => {
          if (result.rows.length === 0) {
            reject(new Error('Survey not found'));
            return;
          }

          const existing = result.rows.item(0);
          const updated = {
            ...existing,
            ...fields,
            updated_at: updatedAt,
            sync_status: 'pending'
          };

          tx.executeSql(
            `UPDATE surveys
             SET title = ?, location = ?, notes = ?, updated_at = ?, sync_status = ?
             WHERE id = ?`,
            [
              updated.title,
              updated.location,
              updated.notes,
              updated.updated_at,
              updated.sync_status,
              id
            ]
          );

          tx.executeSql(
            `INSERT INTO sync_queue (entity_type, entity_id, operation, payload, created_at, status)
             VALUES (?, ?, ?, ?, ?, ?)`,
            [
              'survey',
              id,
              'upsert',
              JSON.stringify(updated),
              updatedAt,
              'pending'
            ]
          );
        }
      );
    }, reject, () => resolve(true));
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updated_at DESC`,
        [],
        (_, result) => {
          const items = [];
          for (let i = 0; i < result.rows.length; i++) {
            items.push(result.rows.item(i));
          }
          resolve(items);
        }
      );
    }, reject);
  });
};

export const markSurveySynced = (localId, serverId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET server_id = ?, sync_status = ? WHERE id = ?`,
        [serverId, 'synced', localId]
      );
    }, reject, resolve);
  });
};
```

