## `syncService.js`

Pushes queued changes to backend when online.

```javascript
// syncService.js
import db from './db';
import { markSurveySynced } from './surveyRepository';

const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

export const getPendingQueueItems = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue WHERE status = 'pending' ORDER BY created_at ASC`,
        [],
        (_, result) => {
          const items = [];
          for (let i = 0; i < result.rows.length; i++) {
            items.push(result.rows.item(i));
          }
          resolve(items);
        }
      );
    }, reject);
  });
};

export const markQueueItemDone = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE sync_queue SET status = 'done' WHERE id = ?`,
        [id]
      );
    }, reject, resolve);
  });
};

export const incrementRetryCount = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE sync_queue SET retry_count = retry_count + 1 WHERE id = ?`,
        [id]
      );
    }, reject, resolve);
  });
};

export const syncPendingData = async () => {
  const items = await getPendingQueueItems();

  for (const item of items) {
    try {
      const payload = JSON.parse(item.payload);

      const response = await fetch(`${API_BASE_URL}/sync/survey`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          operation: item.operation,
          data: payload
        })
      });

      if (!response.ok) {
        throw new Error(`Sync failed with status ${response.status}`);
      }

      const result = await response.json();

      await markSurveySynced(payload.id, result.serverId || payload.server_id || payload.id);
      await markQueueItemDone(item.id);
    } catch (err) {
      console.error('Sync error for queue item', item.id, err);
      await incrementRetryCount(item.id);
    }
  }
};
```

