const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/sync/survey', (req, res) => {
  const { operation, data } = req.body;

  if (operation !== 'upsert') {
    return res.status(400).json({ error: 'Unsupported operation' });
  }

  let serverId = data.server_id;

  if (!serverId) {
    serverId = uuidv4();
  }

  const serverRecord = {
    server_id: serverId,
    client_id: data.id,
    title: data.title,
    location: data.location,
    notes: data.notes,
    updated_at: data.updated_at
  };

  surveys.set(serverId, serverRecord);

  res.json({
    success: true,
    serverId,
    record: serverRecord
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

