```javascript
import React, { useEffect, useState, useCallback } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';

const db = SQLite.openDatabase('survey.db');
const API_BASE = 'http://YOUR_SERVER_IP:3000';

function nowIso() {
  return new Date().toISOString();
}

function uuid() {
  return 'xxxxxxxxyxxx4xxxyxxxxxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

function executeSql(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => resolve(result),
        (_, error) => {
          reject(error);
          return false;
        }
      );
    });
  });
}

async function initDb() {
  await executeSql(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      title TEXT NOT NULL,
      location TEXT,
      notes TEXT,
      updatedAt TEXT NOT NULL,
      synced INTEGER NOT NULL DEFAULT 0,
      deleted INTEGER NOT NULL DEFAULT 0
    );
  `);

  await executeSql(`
    CREATE TABLE IF NOT EXISTS sync_queue (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      entityType TEXT NOT NULL,
      entityId TEXT NOT NULL,
      operation TEXT NOT NULL,
      payload TEXT NOT NULL,
      createdAt TEXT NOT NULL
    );
  `);

  await executeSql(`
    CREATE TABLE IF NOT EXISTS sync_meta (
      key TEXT PRIMARY KEY NOT NULL,
      value TEXT
    );
  `);

  const result = await executeSql(
    `SELECT value FROM sync_meta WHERE key = ?`,
    ['lastPulledAt']
  );

  if (result.rows.length === 0) {
    await executeSql(
      `INSERT INTO sync_meta (key, value) VALUES (?, ?)`,
      ['lastPulledAt', '1970-01-01T00:00:00.000Z']
    );
  }
}

async function getLastPulledAt() {
  const result = await executeSql(
    `SELECT value FROM sync_meta WHERE key = ?`,
    ['lastPulledAt']
  );
  return result.rows.item(0)?.value || '1970-01-01T00:00:00.000Z';
}

async function setLastPulledAt(value) {
  await executeSql(
    `UPDATE sync_meta SET value = ? WHERE key = ?`,
    [value, 'lastPulledAt']
  );
}

async function getAllSurveys() {
  const result = await executeSql(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );
  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

async function createSurvey({ title, location, notes }) {
  const survey = {
    id: uuid(),
    title,
    location: location || '',
    notes: notes || '',
    updatedAt: nowIso(),
    synced: 0,
    deleted: 0,
  };

  await executeSql(
    `INSERT INTO surveys (id, title, location, notes, updatedAt, synced, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.location,
      survey.notes,
      survey.updatedAt,
      survey.synced,
      survey.deleted,
    ]
  );

  await enqueueChange('survey', survey.id, 'upsert', survey);
  return survey;
}

async function updateSurvey(id, updates) {
  const existingResult = await executeSql(
    `SELECT * FROM surveys WHERE id = ?`,
    [id]
  );
  if (existingResult.rows.length === 0) return null;

  const existing = existingResult.rows.item(0);
  const updated = {
    ...existing,
    ...updates,
    updatedAt: nowIso(),
    synced: 0,
  };

  await executeSql(
    `UPDATE surveys
     SET title = ?, location = ?, notes = ?, updatedAt = ?, synced = ?
     WHERE id = ?`,
    [
      updated.title,
      updated.location,
      updated.notes,
      updated.updatedAt,
      updated.synced,
      id,
    ]
  );

  await enqueueChange('survey', id, 'upsert', updated);
  return updated;
}

async function deleteSurvey(id) {
  const existingResult = await executeSql(
    `SELECT * FROM surveys WHERE id = ?`,
    [id]
  );
  if (existingResult.rows.length === 0) return;

  const existing = existingResult.rows.item(0);
  const deletedRecord = {
    ...existing,
    deleted: 1,
    updatedAt: nowIso(),
    synced: 0,
  };

  await executeSql(
    `UPDATE surveys
     SET deleted = 1, updatedAt = ?, synced = 0
     WHERE id = ?`,
    [deletedRecord.updatedAt, id]
  );

  await enqueueChange('survey', id, 'delete', deletedRecord);
}

async function enqueueChange(entityType, entityId, operation, payload) {
  await executeSql(
    `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [entityType, entityId, operation, JSON.stringify(payload), nowIso()]
  );
}

async function getPendingQueue() {
  const result = await executeSql(
    `SELECT * FROM sync_queue ORDER BY id ASC`
  );
  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

async function clearQueueIds(ids) {
  if (!ids.length) return;
  const placeholders = ids.map(() => '?').join(',');
  await executeSql(
    `DELETE FROM sync_queue WHERE id IN (${placeholders})`,
    ids
  );
}

async function markSurveySynced(id) {
  await executeSql(
    `UPDATE surveys SET synced = 1 WHERE id = ?`,
    [id]
  );
}

async function applyRemoteSurvey(remote) {
  const localResult = await executeSql(
    `SELECT * FROM surveys WHERE id = ?`,
    [remote.id]
  );

  if (localResult.rows.length === 0) {
    await executeSql(
      `INSERT INTO surveys (id, title, location, notes, updatedAt, synced, deleted)
       VALUES (?, ?, ?, ?, ?, 1, ?)`,
      [
        remote.id,
        remote.title,
        remote.location || '',
        remote.notes || '',
        remote.updatedAt,
        remote.deleted ? 1 : 0,
      ]
    );
    return;
  }

  const local = localResult.rows.item(0);

  // If local is unsynced and newer, keep local for now.
  if (!local.synced && new Date(local.updatedAt) > new Date(remote.updatedAt)) {
    return;
  }

  // Otherwise apply remote
  await executeSql(
    `UPDATE surveys
     SET title = ?, location = ?, notes = ?, updatedAt = ?, synced = 1, deleted = ?
     WHERE id = ?`,
    [
      remote.title,
      remote.location || '',
      remote.notes || '',
      remote.updatedAt,
      remote.deleted ? 1 : 0,
      remote.id,
    ]
  );
}

async function pushLocalChanges() {
  const queue = await getPendingQueue();
  if (queue.length === 0) return;

  const changes = queue.map(item => ({
    queueId: item.id,
    entityType: item.entityType,
    entityId: item.entityId,
    operation: item.operation,
    payload: JSON.parse(item.payload),
    createdAt: item.createdAt,
  }));

  const res = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ changes }),
  });

  if (!res.ok) {
    throw new Error('Push sync failed');
  }

  const data = await res.json();

  const ackedQueueIds = data.ackedQueueIds || [];
  const syncedEntityIds = data.syncedEntityIds || [];

  await clearQueueIds(ackedQueueIds);

  for (const id of syncedEntityIds) {
    await markSurveySynced(id);
  }
}

async function pullRemoteChanges() {
  const lastPulledAt = await getLastPulledAt();

  const res = await fetch(
    `${API_BASE}/sync/pull?since=${encodeURIComponent(lastPulledAt)}`
  );

  if (!res.ok) {
    throw new Error('Pull sync failed');
  }

  const data = await res.json();
  const surveys = data.surveys || [];
  const serverTime = data.serverTime || nowIso();

  for (const survey of surveys) {
    await applyRemoteSurvey(survey);
  }

  await setLastPulledAt(serverTime);
}

async function syncAll() {
  await pushLocalChanges();
  await pullRemoteChanges();
}

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  const loadSurveys = useCallback(async () => {
    const items = await getAllSurveys();
    setSurveys(items);
  }, []);

  const doSync = useCallback(async () => {
    try {
      setSyncing(true);
      await syncAll();
      await loadSurveys();
    } catch (err) {
      console.log('Sync error:', err);
    } finally {
      setSyncing(false);
    }
  }, [loadSurveys]);

  useEffect(() => {
    (async () => {
      await initDb();
      await loadSurveys();
    })();

    const unsubscribe = NetInfo.addEventListener(state => {
      const online = !!state.isConnected;
      setIsOnline(online);
      if (online) {
        doSync();
      }
    });

    return () => unsubscribe();
  }, [doSync, loadSurveys]);

  const onAddSurvey = async () => {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    await createSurvey({ title, location, notes });
    setTitle('');
    setLocation('');
    setNotes('');
    await loadSurveys();

    if (isOnline) {
      await doSync();
    }
  };

  const onDeleteSurvey = async id => {
    await deleteSurvey(id);
    await loadSurveys();
    if (isOnline) {
      await doSync();
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        Status: {isOnline ? 'Online' : 'Offline'} | Sync: {syncing ? 'Running' : 'Idle'}
      </Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Survey title"
          value={title}
          onChangeText={setTitle}
        />
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={location}
          onChangeText={setLocation}
        />
        <TextInput
          style={[styles.input, styles.notes]}
          placeholder="Notes"
          multiline
          value={notes}
          onChangeText={setNotes}
        />
        <Button title="Add Survey" onPress={onAddSurvey} />
        <View style={{ height: 8 }} />
        <Button title="Manual Sync" onPress={doSync} />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.cardTitle}>{item.title}</Text>
            <Text>Location: {item.location}</Text>
            <Text>Notes: {item.notes}</Text>
            <Text>Updated: {item.updatedAt}</Text>
            <Text>{item.synced ? 'Synced' : 'Pending Sync'}</Text>
            <Button title="Delete" onPress={() => onDeleteSurvey(item.id)} />
          </View>
        )}
      />
    </SafeAreaView>
  );
}

