---

## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

// Example survey structure:
// {
//   id,
//   title,
//   location,
//   notes,
//   updatedAt,
//   deleted
// }

function nowIso() {
  return new Date().toISOString();
}

app.post('/sync/push', (req, res) => {
  const changes = req.body.changes || [];
  const ackedQueueIds = [];
  const syncedEntityIds = [];

  for (const change of changes) {
    const { queueId, operation, payload } = change;
    if (!payload || !payload.id) continue;

    const existing = surveys.get(payload.id);

    if (!existing) {
      surveys.set(payload.id, {
        ...payload,
        deleted: payload.deleted ? 1 : 0,
      });
      ackedQueueIds.push(queueId);
      syncedEntityIds.push(payload.id);
      continue;
    }

    const incomingTime = new Date(payload.updatedAt).getTime();
    const existingTime = new Date(existing.updatedAt).getTime();

    // Last-write-wins
    if (incomingTime >= existingTime) {
      if (operation === 'delete') {
        surveys.set(payload.id, {
          ...existing,
          ...payload,
          deleted: 1,
        });
      } else {
        surveys.set(payload.id, {
          ...existing,
          ...payload,
          deleted: payload.deleted ? 1 : 0,
        });
      }

      ackedQueueIds.push(queueId);
      syncedEntityIds.push(payload.id);
    } else {
      // Older local change loses conflict but still ack queue item
      ackedQueueIds.push(queueId);
    }
  }

  res.json({
    ackedQueueIds,
    syncedEntityIds,
    serverTime: nowIso(),
  });
});

app.get('/sync/pull', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';
  const sinceTime = new Date(since).getTime();

  const changedSurveys = [];

  for (const survey of surveys.values()) {
    const updatedTime = new Date(survey.updatedAt).getTime();
    if (updatedTime > sinceTime) {
      changedSurveys.push(survey);
    }
  }

  res.json({
    surveys: changedSurveys,
    serverTime: nowIso(),
  });
});

app.get('/surveys', (_, res) => {
  res.json(Array.from(surveys.values()));
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Sync server listening on port ${PORT}`);
});
```

