# 7. Example `syncService.js`

```javascript
export async function runSync({
  pushLocalChanges,
  pullRemoteChanges,
  onStart,
  onFinish,
  onError,
}) {
  try {
    onStart?.();
    await pushLocalChanges();
    await pullRemoteChanges();
    onFinish?.();
  } catch (error) {
    onError?.(error);
    throw error;
  }
}
