## 3. `surveyRepository.js`

Handles local persistence and queueing.

```javascript
// surveyRepository.js
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';

const db = getDb();

export function listSurveys() {
  const result = db.getAllSync(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updated_at DESC`
  );
  return result;
}

export function getPendingQueue() {
  return db.getAllSync(
    `SELECT * FROM sync_queue ORDER BY created_at ASC`
  );
}

export function createSurvey({ title, notes, latitude, longitude }) {
  const id = uuidv4();
  const now = Date.now();

  const survey = {
    id,
    remote_id: null,
    title,
    notes: notes || '',
    latitude: latitude ?? null,
    longitude: longitude ?? null,
    updated_at: now,
    sync_status: 'pending',
    deleted: 0,
  };

  db.runSync(
    `INSERT INTO surveys
      (id, remote_id, title, notes, latitude, longitude, updated_at, sync_status, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.remote_id,
      survey.title,
      survey.notes,
      survey.latitude,
      survey.longitude,
      survey.updated_at,
      survey.sync_status,
      survey.deleted,
    ]
  );

  enqueue('survey', id, 'create', survey);
  return survey;
}

export function updateSurvey(id, updates) {
  const existing = db.getFirstSync(
    `SELECT * FROM surveys WHERE id = ?`,
    [id]
  );

  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...updates,
    updated_at: Date.now(),
    sync_status: 'pending',
  };

  db.runSync(
    `UPDATE surveys
     SET title = ?, notes = ?, latitude = ?, longitude = ?, updated_at = ?, sync_status = ?
     WHERE id = ?`,
    [
      updated.title,
      updated.notes,
      updated.latitude,
      updated.longitude,
      updated.updated_at,
      updated.sync_status,
      id,
    ]
  );

  enqueue('survey', id, 'update', updated);
  return updated;
}

export function deleteSurvey(id) {
  const existing = db.getFirstSync(
    `SELECT * FROM surveys WHERE id = ?`,
    [id]
  );

  if (!existing) return;

  const updated = {
    ...existing,
    deleted: 1,
    updated_at: Date.now(),
    sync_status: 'pending',
  };

  db.runSync(
    `UPDATE surveys
     SET deleted = 1, updated_at = ?, sync_status = ?
     WHERE id = ?`,
    [updated.updated_at, updated.sync_status, id]
  );

  enqueue('survey', id, 'delete', updated);
}

function enqueue(entityType, entityId, operation, payload) {
  db.runSync(
    `INSERT INTO sync_queue (entity_type, entity_id, operation, payload, created_at)
     VALUES (?, ?, ?, ?, ?)`,
    [entityType, entityId, operation, JSON.stringify(payload), Date.now()]
  );
}

export function markSurveySynced(localId, remoteId, updatedAt) {
  db.runSync(
    `UPDATE surveys
     SET remote_id = ?, sync_status = 'synced', updated_at = ?
     WHERE id = ?`,
    [remoteId, updatedAt, localId]
  );
}

export function removeQueueItem(queueId) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [queueId]);
}

export function upsertRemoteSurvey(remoteSurvey) {
  const existing = db.getFirstSync(
    `SELECT * FROM surveys WHERE remote_id = ? OR id = ?`,
    [remoteSurvey.id, remoteSurvey.local_id || '']
  );

  if (existing) {
    // naive conflict strategy: latest updated_at wins if local is not pending
    if (existing.sync_status === 'pending' && existing.updated_at > remoteSurvey.updated_at) {
      return;
    }

    db.runSync(
      `UPDATE surveys
       SET remote_id = ?, title = ?, notes = ?, latitude = ?, longitude = ?, updated_at = ?, sync_status = 'synced', deleted = ?
       WHERE id = ?`,
      [
        remoteSurvey.id,
        remoteSurvey.title,
        remoteSurvey.notes,
        remoteSurvey.latitude,
        remoteSurvey.longitude,
        remoteSurvey.updated_at,
        remoteSurvey.deleted ? 1 : 0,
        existing.id,
      ]
    );
  } else {
    db.runSync(
      `INSERT INTO surveys
       (id, remote_id, title, notes, latitude, longitude, updated_at, sync_status, deleted)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'synced', ?)`,
      [
        uuidv4(),
        remoteSurvey.id,
        remoteSurvey.title,
        remoteSurvey.notes,
        remoteSurvey.latitude,
        remoteSurvey.longitude,
        remoteSurvey.updated_at,
        remoteSurvey.deleted ? 1 : 0,
      ]
    );
  }
}
```

