## 4. `syncService.js`

Pushes queue to server and pulls latest remote records.

```javascript
// syncService.js
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingQueue,
  markSurveySynced,
  removeQueueItem,
  upsertRemoteSurvey,
} from './surveyRepository';

const API_BASE = 'http://YOUR_SERVER_IP:3000';

export async function isOnline() {
  const state = await NetInfo.fetch();
  return !!state.isConnected;
}

export async function syncAll() {
  const online = await isOnline();
  if (!online) return { synced: false, reason: 'offline' };

  const queue = getPendingQueue();

  for (const item of queue) {
    const payload = JSON.parse(item.payload);

    try {
      let response;

      if (item.operation === 'create') {
        response = await fetch(`${API_BASE}/surveys`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.operation === 'update') {
        const remoteId = payload.remote_id || payload.id;
        response = await fetch(`${API_BASE}/surveys/${remoteId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.operation === 'delete') {
        const remoteId = payload.remote_id || payload.id;
        response = await fetch(`${API_BASE}/surveys/${remoteId}`, {
          method: 'DELETE',
        });
      }

      if (!response?.ok) {
        continue;
      }

      let serverRecord = null;
      if (item.operation !== 'delete') {
        serverRecord = await response.json();
        markSurveySynced(payload.id, serverRecord.id, serverRecord.updated_at);
      }

      removeQueueItem(item.id);
    } catch (err) {
      console.log('Sync item failed:', err.message);
    }
  }

  // Pull latest server state
  try {
    const res = await fetch(`${API_BASE}/surveys`);
    if (res.ok) {
      const surveys = await res.json();
      surveys.forEach(upsertRemoteSurvey);
    }
  } catch (err) {
    console.log('Pull sync failed:', err.message);
  }

  return { synced: true };
}
