# Backend Code

## 6. `server.js`

Simple Express backend for sync.

```javascript
// server.js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/surveys', (req, res) => {
  const body = req.body;
  const id = body.remote_id || body.id || cryptoRandomId();

  const survey = {
    id,
    title: body.title,
    notes: body.notes || '',
    latitude: body.latitude ?? null,
    longitude: body.longitude ?? null,
    updated_at: Date.now(),
    deleted: 0,
  };

  surveys.set(id, survey);
  res.status(201).json(survey);
});

app.put('/surveys/:id', (req, res) => {
  const id = req.params.id;
  const existing = surveys.get(id);

  if (!existing) {
    const created = {
      id,
      title: req.body.title,
      notes: req.body.notes || '',
      latitude: req.body.latitude ?? null,
      longitude: req.body.longitude ?? null,
      updated_at: Date.now(),
      deleted: 0,
    };
    surveys.set(id, created);
    return res.json(created);
  }

  const updated = {
    ...existing,
    ...req.body,
    id,
    updated_at: Date.now(),
  };

  surveys.set(id, updated);
  res.json(updated);
});

app.delete('/surveys/:id', (req, res) => {
  const id = req.params.id;
  const existing = surveys.get(id);

  if (existing) {
    surveys.set(id, {
      ...existing,
      deleted: 1,
      updated_at: Date.now(),
    });
  }

  res.status(204).send();
});

function cryptoRandomId() {
  return Math.random().toString(36).slice(2, 12);
}

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

