# Better transactional local write example

Here is how you might improve `createSurvey` with a transaction:

```javascript
export function createSurveyTransactional({ title, notes, latitude, longitude }) {
  const id = uuidv4();
  const now = Date.now();

  const survey = {
    id,
    remote_id: null,
    title,
    notes: notes || '',
    latitude: latitude ?? null,
    longitude: longitude ?? null,
    updated_at: now,
    sync_status: 'pending',
    deleted: 0,
  };

  db.execSync('BEGIN');
  try {
    db.runSync(
      `INSERT INTO surveys
       (id, remote_id, title, notes, latitude, longitude, updated_at, sync_status, deleted)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        survey.id,
        survey.remote_id,
        survey.title,
        survey.notes,
        survey.latitude,
        survey.longitude,
        survey.updated_at,
        survey.sync_status,
        survey.deleted,
      ]
    );

    db.runSync(
      `INSERT INTO sync_queue (entity_type, entity_id, operation, payload, created_at)
       VALUES (?, ?, ?, ?, ?)`,
      ['survey', id, 'create', JSON.stringify(survey), now]
    );

    db.execSync('COMMIT');
  } catch (e) {
    db.execSync('ROLLBACK');
    throw e;
  }

  return survey;
}
```

