## `App.js`

```javascript
import React, { useEffect, useState } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';

const db = SQLite.openDatabase('survey.db');
const API_BASE = 'http://YOUR_SERVER_IP:3000';

export default function App() {
  const [siteName, setSiteName] = useState('');
  const [observer, setObserver] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener(state => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);
      if (online) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  const initDb = () => {
    db.transaction(tx => {
      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          siteName TEXT,
          observer TEXT,
          notes TEXT,
          updatedAt TEXT,
          synced INTEGER DEFAULT 0
        );
      `);
    });
  };

  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY updatedAt DESC;',
        [],
        (_, result) => {
          setSurveys(result.rows._array);
        },
        (_, error) => {
          console.error('Load surveys error:', error);
          return false;
        }
      );
    });
  };

  const saveSurvey = () => {
    if (!siteName.trim()) {
      Alert.alert('Validation', 'Site name is required.');
      return;
    }

    const id = generateId();
    const updatedAt = new Date().toISOString();

    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, siteName, observer, notes, updatedAt, synced)
         VALUES (?, ?, ?, ?, ?, 0);`,
        [id, siteName, observer, notes, updatedAt],
        () => {
          setSiteName('');
          setObserver('');
          setNotes('');
          loadSurveys();
          if (isOnline) {
            syncPendingSurveys();
          }
        },
        (_, error) => {
          console.error('Save survey error:', error);
          return false;
        }
      );
    });
  };

  const syncPendingSurveys = async () => {
    if (syncing) return;
    setSyncing(true);

    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE synced = 0;',
        [],
        async (_, result) => {
          const pending = result.rows._array;

          for (const survey of pending) {
            try {
              await axios.post(`${API_BASE}/surveys/sync`, survey);

              db.transaction(tx2 => {
                tx2.executeSql(
                  'UPDATE surveys SET synced = 1 WHERE id = ?;',
                  [survey.id]
                );
              });
            } catch (err) {
              console.error('Sync failed for survey:', survey.id, err.message);
            }
          }

          loadSurveys();
          setSyncing(false);
        },
        (_, error) => {
          console.error('Fetch pending surveys error:', error);
          setSyncing(false);
          return false;
        }
      );
    });
  };

  const pullLatest = async () => {
    if (!isOnline) {
      Alert.alert('Offline', 'Cannot pull latest data while offline.');
      return;
    }

    try {
      const response = await axios.get(`${API_BASE}/surveys`);
      const remoteSurveys = response.data;

      db.transaction(tx => {
        remoteSurveys.forEach(item => {
          tx.executeSql(
            `
            INSERT INTO surveys (id, siteName, observer, notes, updatedAt, synced)
            VALUES (?, ?, ?, ?, ?, 1)
            ON CONFLICT(id) DO UPDATE SET
              siteName = excluded.siteName,
              observer = excluded.observer,
              notes = excluded.notes,
              updatedAt = excluded.updatedAt,
              synced = 1
            WHERE excluded.updatedAt > surveys.updatedAt;
            `,
            [
              item.id,
              item.siteName,
              item.observer,
              item.notes,
              item.updatedAt,
            ]
          );
        });
      }, null, loadSurveys);
    } catch (err) {
      console.error('Pull latest error:', err.message);
    }
  };

  const generateId = () => {
    return 'survey-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9);
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text style={styles.status}>
        Status: {isOnline ? 'Online' : 'Offline'} {syncing ? '(Syncing...)' : ''}
      </Text>

      <TextInput
        style={styles.input}
        placeholder="Site Name"
        value={siteName}
        onChangeText={setSiteName}
      />
      <TextInput
        style={styles.input}
        placeholder="Observer"
        value={observer}
        onChangeText={setObserver}
      />
      <TextInput
        style={[styles.input, styles.notes]}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        multiline
      />

      <Button title="Save Survey" onPress={saveSurvey} />
      <View style={{ height: 10 }} />
      <Button title="Pull Latest From Server" onPress={pullLatest} />

      <Text style={styles.subHeader}>Saved Surveys</Text>
      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.item}>
            <Text style={styles.itemTitle}>{item.siteName}</Text>
            <Text>Observer: {item.observer || '-'}</Text>
            <Text>Notes: {item.notes || '-'}</Text>
            <Text>Updated: {item.updatedAt}</Text>
            <Text style={{ color: item.synced ? 'green' : 'orange' }}>
              {item.synced ? 'Synced' : 'Pending Sync'}
            </Text>
          </View>
        )}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16, marginTop: 30 },
  header: { fontSize: 24, fontWeight: 'bold', marginBottom: 8 },
  status: { marginBottom: 12, color: '#444' },
  subHeader: { fontSize: 20, marginTop: 20, marginBottom: 10 },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    padding: 10,
    borderRadius: 8,
    marginBottom: 10,
  },
  notes: { height: 80, textAlignVertical: 'top' },
  item: {
    padding: 12,
    borderWidth: 1,
    borderColor: '#ddd',
    borderRadius: 8,
    marginBottom: 10,
  },
  itemTitle: { fontSize: 16, fontWeight: 'bold' },
});
