const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id: string,
 *   siteName: string,
 *   observer: string,
 *   notes: string,
 *   updatedAt: string
 * }
 */

app.get('/surveys', (req, res) => {
  const all = Array.from(surveys.values()).sort(
    (a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)
  );
  res.json(all);
});

app.post('/surveys/sync', (req, res) => {
  const incoming = req.body;

  if (!incoming.id || !incoming.siteName || !incoming.updatedAt) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const existing = surveys.get(incoming.id);

  if (!existing) {
    surveys.set(incoming.id, {
      id: incoming.id,
      siteName: incoming.siteName,
      observer: incoming.observer || '',
      notes: incoming.notes || '',
      updatedAt: incoming.updatedAt,
    });
    return res.json({ status: 'created', survey: surveys.get(incoming.id) });
  }

  if (new Date(incoming.updatedAt) > new Date(existing.updatedAt)) {
    surveys.set(incoming.id, {
      id: incoming.id,
      siteName: incoming.siteName,
      observer: incoming.observer || '',
      notes: incoming.notes || '',
      updatedAt: incoming.updatedAt,
    });
    return res.json({ status: 'updated', survey: surveys.get(incoming.id) });
  }

  return res.json({ status: 'ignored', survey: existing });
});

app.listen(3000, () => {
  console.log('Survey server running on http://localhost:3000');
});
```

