```javascript
import { getDB } from './db';
import { v4 as uuidv4 } from 'uuid';

function nowISO() {
  return new Date().toISOString();
}

export async function createSurvey({ title, notes, latitude, longitude }) {
  const db = await getDB();
  const id = uuidv4();
  const localUpdatedAt = nowISO();

  await db.executeSql(
    `
    INSERT INTO surveys (
      id, title, notes, latitude, longitude,
      deleted, sync_status, local_updated_at, server_updated_at
    )
    VALUES (?, ?, ?, ?, ?, 0, 'pending', ?, NULL)
    `,
    [id, title, notes, latitude, longitude, localUpdatedAt]
  );

  return { id, title, notes, latitude, longitude, deleted: 0, sync_status: 'pending', local_updated_at: localUpdatedAt };
}

export async function updateSurvey(id, updates) {
  const db = await getDB();
  const localUpdatedAt = nowISO();

  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const merged = {
    title: updates.title ?? existing.title,
    notes: updates.notes ?? existing.notes,
    latitude: updates.latitude ?? existing.latitude,
    longitude: updates.longitude ?? existing.longitude,
  };

  await db.executeSql(
    `
    UPDATE surveys
    SET title = ?, notes = ?, latitude = ?, longitude = ?,
        sync_status = 'pending',
        local_updated_at = ?
    WHERE id = ?
    `,
    [
      merged.title,
      merged.notes,
      merged.latitude,
      merged.longitude,
      localUpdatedAt,
      id,
    ]
  );

  return { ...existing, ...merged, sync_status: 'pending', local_updated_at: localUpdatedAt };
}

export async function deleteSurvey(id) {
  const db = await getDB();
  const localUpdatedAt = nowISO();

  await db.executeSql(
    `
    UPDATE surveys
    SET deleted = 1,
        sync_status = 'pending',
        local_updated_at = ?
    WHERE id = ?
    `,
    [localUpdatedAt, id]
  );
}

export async function getSurveyById(id) {
  const db = await getDB();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (result.rows.length === 0) return null;
  return result.rows.item(0);
}

export async function listSurveys() {
  const db = await getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY local_updated_at DESC`
  );

  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function getPendingSurveys() {
  const db = await getDB();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE sync_status IN ('pending', 'failed')`
  );

  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function markSurveySynced(id, serverUpdatedAt) {
  const db = await getDB();
  await db.executeSql(
    `
    UPDATE surveys
    SET sync_status = 'synced',
        server_updated_at = ?
    WHERE id = ?
    `,
    [serverUpdatedAt, id]
  );
}

export async function markSurveyFailed(id) {
  const db = await getDB();
  await db.executeSql(
    `
    UPDATE surveys
    SET sync_status = 'failed'
    WHERE id = ?
    `,
    [id]
  );
}

export async function upsertServerSurvey(survey) {
  const db = await getDB();

  const existing = await getSurveyById(survey.id);

  if (!existing) {
    await db.executeSql(
      `
      INSERT INTO surveys (
        id, title, notes, latitude, longitude, deleted,
        sync_status, local_updated_at, server_updated_at
      )
      VALUES (?, ?, ?, ?, ?, ?, 'synced', ?, ?)
      `,
      [
        survey.id,
        survey.title,
        survey.notes,
        survey.latitude,
        survey.longitude,
        survey.deleted ? 1 : 0,
        survey.server_updated_at,
        survey.server_updated_at,
      ]
    );
    return;
  }

  const localTime = new Date(existing.local_updated_at).getTime();
  const serverTime = new Date(survey.server_updated_at).getTime();

  // Only overwrite if server version is newer and local record is not pending
  if (existing.sync_status === 'pending' || existing.sync_status === 'failed') {
    return;
  }

  if (!existing.server_updated_at || serverTime >= localTime) {
    await db.executeSql(
      `
      UPDATE surveys
      SET title = ?, notes = ?, latitude = ?, longitude = ?,
          deleted = ?, sync_status = 'synced',
          local_updated_at = ?, server_updated_at = ?
      WHERE id = ?
      `,
      [
        survey.title,
        survey.notes,
        survey.latitude,
        survey.longitude,
        survey.deleted ? 1 : 0,
        survey.server_updated_at,
        survey.server_updated_at,
        survey.id,
      ]
    );
  }
}

export async function getLastSyncTime() {
  const db = await getDB();
  const [result] = await db.executeSql(
    `SELECT value FROM sync_meta WHERE key = 'last_sync_time'`
  );
  if (result.rows.length === 0) return null;
  return result.rows.item(0).value;
}

export async function setLastSyncTime(value) {
  const db = await getDB();
  await db.executeSql(
    `
    INSERT INTO sync_meta (key, value)
    VALUES ('last_sync_time', ?)
    ON CONFLICT(key) DO UPDATE SET value = excluded.value
    `,
    [value]
  );
}
