## `syncService.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import {
  getPendingSurveys,
  markSurveySynced,
  markSurveyFailed,
  upsertServerSurvey,
  getLastSyncTime,
  setLastSyncTime,
} from './surveyRepository';

const API_BASE = 'http://YOUR_SERVER_IP:3000';

export async function isOnline() {
  const state = await NetInfo.fetch();
  return !!state.isConnected;
}

export async function syncSurveys() {
  const online = await isOnline();
  if (!online) {
    return { success: false, message: 'Offline' };
  }

  try {
    // 1. Push local pending changes
    const pending = await getPendingSurveys();

    if (pending.length > 0) {
      const pushResponse = await fetch(`${API_BASE}/surveys/sync`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ surveys: pending }),
      });

      if (!pushResponse.ok) {
        throw new Error(`Push failed: ${pushResponse.status}`);
      }

      const pushResult = await pushResponse.json();

      for (const item of pushResult.results) {
        if (item.success) {
          await markSurveySynced(item.id, item.server_updated_at);
        } else {
          await markSurveyFailed(item.id);
        }
      }
    }

    // 2. Pull remote changes
    const lastSync = await getLastSyncTime();
    const pullUrl = lastSync
      ? `${API_BASE}/surveys/changes?since=${encodeURIComponent(lastSync)}`
      : `${API_BASE}/surveys/changes`;

    const pullResponse = await fetch(pullUrl);
    if (!pullResponse.ok) {
      throw new Error(`Pull failed: ${pullResponse.status}`);
    }

    const pullResult = await pullResponse.json();

    for (const survey of pullResult.surveys) {
      await upsertServerSurvey(survey);
    }

    await setLastSyncTime(pullResult.server_time);

    return { success: true, pushed: pending.length, pulled: pullResult.surveys.length };
  } catch (error) {
    return { success: false, message: error.message };
  }
}
```

