## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
app.use(cors());
app.use(bodyParser.json());

const surveys = new Map();

function nowISO() {
  return new Date().toISOString();
}

// Push local changes from client
app.post('/surveys/sync', (req, res) => {
  const incoming = req.body.surveys || [];
  const results = [];

  for (const survey of incoming) {
    const existing = surveys.get(survey.id);

    if (!existing) {
      const serverUpdatedAt = nowISO();
      const record = {
        id: survey.id,
        title: survey.title,
        notes: survey.notes,
        latitude: survey.latitude,
        longitude: survey.longitude,
        deleted: !!survey.deleted,
        server_updated_at: serverUpdatedAt,
      };
      surveys.set(survey.id, record);

      results.push({
        id: survey.id,
        success: true,
        server_updated_at: serverUpdatedAt,
      });
      continue;
    }

    const incomingTime = new Date(survey.local_updated_at).getTime();
    const existingTime = new Date(existing.server_updated_at).getTime();

    // Last-write-wins conflict resolution
    if (incomingTime >= existingTime) {
      const serverUpdatedAt = nowISO();
      const updated = {
        ...existing,
        title: survey.title,
        notes: survey.notes,
        latitude: survey.latitude,
        longitude: survey.longitude,
        deleted: !!survey.deleted,
        server_updated_at: serverUpdatedAt,
      };
      surveys.set(survey.id, updated);

      results.push({
        id: survey.id,
        success: true,
        server_updated_at: serverUpdatedAt,
      });
    } else {
      results.push({
        id: survey.id,
        success: false,
        error: 'Conflict: server has newer version',
      });
    }
  }

  res.json({ results });
});

// Pull changes since last sync
app.get('/surveys/changes', (req, res) => {
  const since = req.query.since ? new Date(req.query.since).getTime() : 0;
  const changed = [];

  for (const survey of surveys.values()) {
    const updatedAt = new Date(survey.server_updated_at).getTime();
    if (updatedAt > since) {
      changed.push(survey);
    }
  }

  res.json({
    surveys: changed,
    server_time: nowISO(),
  });
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

