# 2) Local database

## `db.ts`

This uses Expo SQLite.

```ts
import * as SQLite from 'expo-sqlite';
import { SurveyRecord } from './types';

const db = SQLite.openDatabaseSync('survey.db');

export function initDb() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      siteName TEXT NOT NULL,
      latitude REAL NOT NULL,
      longitude REAL NOT NULL,
      notes TEXT,
      photoUri TEXT,
      deleted INTEGER NOT NULL DEFAULT 0,
      updatedAt TEXT NOT NULL,
      syncStatus TEXT NOT NULL
    );
  `);
}

export function saveSurvey(record: SurveyRecord) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys
      (id, siteName, latitude, longitude, notes, photoUri, deleted, updatedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.siteName,
      record.latitude,
      record.longitude,
      record.notes,
      record.photoUri ?? null,
      record.deleted,
      record.updatedAt,
      record.syncStatus,
    ]
  );
}

export function getAllSurveys(): SurveyRecord[] {
  return db.getAllSync<SurveyRecord>(`SELECT * FROM surveys ORDER BY updatedAt DESC`);
}

export function getPendingSurveys(): SurveyRecord[] {
  return db.getAllSync<SurveyRecord>(
    `SELECT * FROM surveys WHERE syncStatus IN ('pending', 'error') ORDER BY updatedAt ASC`
  );
}

export function markSurveySynced(id: string) {
  db.runSync(`UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`, [id]);
}

export function markSurveyError(id: string) {
  db.runSync(`UPDATE surveys SET syncStatus = 'error' WHERE id = ?`, [id]);
}

export function softDeleteSurvey(id: string) {
  db.runSync(
    `UPDATE surveys
     SET deleted = 1, updatedAt = ?, syncStatus = 'pending'
     WHERE id = ?`,
    [new Date().toISOString(), id]
  );
}
```

