# 3) API layer

## `api.ts`

This is the remote sync API. Replace URL with your backend.

```ts
import { SurveyRecord } from './types';

const API_BASE = 'https://your-api.example.com';

export async function pushSurvey(record: SurveyRecord): Promise<void> {
  const response = await fetch(`${API_BASE}/surveys/${record.id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(record),
  });

  if (!response.ok) {
    throw new Error(`Failed to push survey ${record.id}`);
  }
}

export async function pullSurveys(lastSyncAt?: string): Promise<SurveyRecord[]> {
  const url = lastSyncAt
    ? `${API_BASE}/surveys?updatedSince=${encodeURIComponent(lastSyncAt)}`
    : `${API_BASE}/surveys`;

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error('Failed to pull surveys');
  }

  return response.json();
}
```

