# 4) Sync engine

## `sync.ts`

This handles push and pull.

```ts
import { getPendingSurveys, markSurveyError, markSurveySynced, saveSurvey } from './db';
import { pullSurveys, pushSurvey } from './api';
import { SurveyRecord } from './types';
import * as SQLite from 'expo-sqlite';

const metaDb = SQLite.openDatabaseSync('survey.db');

function getLastSyncAt(): string | null {
  metaDb.execSync(`
    CREATE TABLE IF NOT EXISTS app_meta (
      key TEXT PRIMARY KEY NOT NULL,
      value TEXT
    );
  `);

  const row = metaDb.getFirstSync<{ value: string }>(
    `SELECT value FROM app_meta WHERE key = 'lastSyncAt'`
  );
  return row?.value ?? null;
}

function setLastSyncAt(value: string) {
  metaDb.runSync(
    `INSERT OR REPLACE INTO app_meta (key, value) VALUES ('lastSyncAt', ?)`,
    [value]
  );
}

function shouldReplaceLocal(local: SurveyRecord | undefined, remote: SurveyRecord): boolean {
  if (!local) return true;
  return new Date(remote.updatedAt).getTime() > new Date(local.updatedAt).getTime();
}

export async function syncAll(localRecords: SurveyRecord[]): Promise<void> {
  const pending = getPendingSurveys();

  // Push local pending changes
  for (const record of pending) {
    try {
      await pushSurvey(record);
      markSurveySynced(record.id);
    } catch (err) {
      console.error('Push failed', record.id, err);
      markSurveyError(record.id);
    }
  }

  // Pull remote changes
  try {
    const lastSyncAt = getLastSyncAt() ?? undefined;
    const remoteRecords = await pullSurveys(lastSyncAt);

    const localMap = new Map(localRecords.map(r => [r.id, r]));

    for (const remote of remoteRecords) {
      const local = localMap.get(remote.id);
      if (shouldReplaceLocal(local, remote)) {
        saveSurvey(remote);
      }
    }

    setLastSyncAt(new Date().toISOString());
  } catch (err) {
    console.error('Pull failed', err);
  }
}
```

