```javascript
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
      surveyStore.createIndex('updatedAt', 'updatedAt');
      surveyStore.createIndex('syncStatus', 'syncStatus');
    }

    if (!db.objectStoreNames.contains('syncQueue')) {
      const queueStore = db.createObjectStore('syncQueue', {
        keyPath: 'queueId',
        autoIncrement: true,
      });
      queueStore.createIndex('status', 'status');
      queueStore.createIndex('createdAt', 'createdAt');
    }

    if (!db.objectStoreNames.contains('meta')) {
      db.createObjectStore('meta', { keyPath: 'key' });
    }
  },
});

export async function saveSurveyLocally(survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function getSurvey(id) {
  const db = await dbPromise;
  return db.get('surveys', id);
}

export async function deleteSurveyLocal(id) {
  const db = await dbPromise;
  await db.delete('surveys', id);
}

export async function addToSyncQueue(operation) {
  const db = await dbPromise;
  return db.add('syncQueue', {
    ...operation,
    status: 'pending',
    createdAt: new Date().toISOString(),
  });
}

export async function getPendingQueueItems() {
  const db = await dbPromise;
  return db.getAllFromIndex('syncQueue', 'status', 'pending');
}

export async function markQueueItemDone(queueId) {
  const db = await dbPromise;
  const item = await db.get('syncQueue', queueId);
  if (!item) return;
  item.status = 'done';
  item.syncedAt = new Date().toISOString();
  await db.put('syncQueue', item);
}

export async function markQueueItemFailed(queueId, error) {
  const db = await dbPromise;
  const item = await db.get('syncQueue', queueId);
  if (!item) return;
  item.status = 'failed';
  item.error = error;
  await db.put('syncQueue', item);
}

export async function setMeta(key, value) {
  const db = await dbPromise;
  await db.put('meta', { key, value });
}

export async function getMeta(key) {
  const db = await dbPromise;
  const result = await db.get('meta', key);
  return result?.value;
}
```

