## `src/api.js`

Server communication.

```javascript
const API_BASE = 'http://localhost:4000/api';

export async function pushOperation(operation) {
  const response = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(operation),
  });

  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Push failed: ${text}`);
  }

  return response.json();
}

export async function pullChanges(lastSyncAt) {
  const url = new URL(`${API_BASE}/sync/pull`);
  if (lastSyncAt) {
    url.searchParams.set('since', lastSyncAt);
  }

  const response = await fetch(url.toString());
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Pull failed: ${text}`);
  }

  return response.json();
}
```

