## `src/sync.js`

This is the sync engine.

```javascript
import {
  addToSyncQueue,
  getPendingQueueItems,
  markQueueItemDone,
  markQueueItemFailed,
  saveSurveyLocally,
  getMeta,
  setMeta,
  getSurvey,
} from './db';
import { pushOperation, pullChanges } from './api';

let syncInProgress = false;

export async function queueSurveyCreateOrUpdate(survey) {
  const now = new Date().toISOString();

  const localSurvey = {
    ...survey,
    updatedAt: now,
    syncStatus: 'pending',
  };

  await saveSurveyLocally(localSurvey);

  await addToSyncQueue({
    type: 'upsert',
    entity: 'survey',
    recordId: survey.id,
    payload: localSurvey,
  });

  if (navigator.onLine) {
    syncNow();
  }
}

export async function queueSurveyDelete(id) {
  const now = new Date().toISOString();

  const existing = await getSurvey(id);
  if (existing) {
    await saveSurveyLocally({
      ...existing,
      deleted: true,
      updatedAt: now,
      syncStatus: 'pending',
    });
  }

  await addToSyncQueue({
    type: 'delete',
    entity: 'survey',
    recordId: id,
    payload: { id, deleted: true, updatedAt: now },
  });

  if (navigator.onLine) {
    syncNow();
  }
}

export async function syncNow() {
  if (syncInProgress || !navigator.onLine) return;
  syncInProgress = true;

  try {
    // 1. Push local pending operations
    const pending = await getPendingQueueItems();

    for (const op of pending) {
      try {
        const result = await pushOperation(op);

        if (op.entity === 'survey' && op.type === 'upsert') {
          await saveSurveyLocally({
            ...op.payload,
            ...result.record,
            syncStatus: 'synced',
          });
        }

        if (op.entity === 'survey' && op.type === 'delete') {
          // Keep tombstone or remove locally depending on your strategy
        }

        await markQueueItemDone(op.queueId);
      } catch (err) {
        await markQueueItemFailed(op.queueId, err.message);
      }
    }

    // 2. Pull remote changes
    const lastSyncAt = await getMeta('lastSyncAt');
    const pullResult = await pullChanges(lastSyncAt);

    for (const remoteSurvey of pullResult.changes.surveys) {
      const local = await getSurvey(remoteSurvey.id);

      // Simple last-write-wins conflict strategy
      if (!local || new Date(remoteSurvey.updatedAt) >= new Date(local.updatedAt)) {
        await saveSurveyLocally({
          ...remoteSurvey,
          syncStatus: 'synced',
        });
      }
    }

    await setMeta('lastSyncAt', pullResult.serverTime);
  } finally {
    syncInProgress = false;
  }
}

export function registerSyncListeners() {
  window.addEventListener('online', () => {
    syncNow();
  });
}
```

