## `server.js`

This example uses in-memory storage for simplicity. In production, use PostgreSQL, MongoDB, or another persistent database.

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

function nowIso() {
  return new Date().toISOString();
}

app.post('/api/sync/push', (req, res) => {
  const op = req.body;

  if (op.entity !== 'survey') {
    return res.status(400).send('Unsupported entity');
  }

  if (op.type === 'upsert') {
    const incoming = op.payload;
    const existing = surveys.get(incoming.id);

    // Simple last-write-wins
    if (!existing || new Date(incoming.updatedAt) >= new Date(existing.updatedAt)) {
      const saved = {
        ...existing,
        ...incoming,
        syncedAt: nowIso(),
      };
      surveys.set(incoming.id, saved);
      return res.json({ ok: true, record: saved });
    }

    return res.json({ ok: true, record: existing, conflict: true });
  }

  if (op.type === 'delete') {
    const incoming = op.payload;
    const existing = surveys.get(incoming.id);

    if (!existing || new Date(incoming.updatedAt) >= new Date(existing.updatedAt)) {
      const deletedRecord = {
        ...existing,
        id: incoming.id,
        deleted: true,
        updatedAt: incoming.updatedAt,
        syncedAt: nowIso(),
      };
      surveys.set(incoming.id, deletedRecord);
      return res.json({ ok: true, record: deletedRecord });
    }

    return res.json({ ok: true, record: existing, conflict: true });
  }

  return res.status(400).send('Unsupported operation type');
});

app.get('/api/sync/pull', (req, res) => {
  const since = req.query.since ? new Date(req.query.since) : null;

  const changes = Array.from(surveys.values()).filter(record => {
    if (!since) return true;
    return new Date(record.updatedAt) > since;
  });

  res.json({
    serverTime: nowIso(),
    changes: {
      surveys: changes,
    },
  });
});

app.get('/api/surveys', (req, res) => {
  res.json(Array.from(surveys.values()).filter(s => !s.deleted));
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Sync server running on http://localhost:${PORT}`);
});
```

