import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
} from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import * as SQLite from 'expo-sqlite';
import axios from 'axios';
import { v4 as uuidv4 } from 'uuid';

const db = SQLite.openDatabase('survey.db');
const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);
      if (online) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  const initDb = () => {
    db.transaction((tx) => {
      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          title TEXT NOT NULL,
          location TEXT,
          notes TEXT,
          createdAt TEXT NOT NULL,
          updatedAt TEXT NOT NULL,
          version INTEGER NOT NULL,
          syncStatus TEXT NOT NULL
        );
      `);

      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS sync_queue (
          queueId INTEGER PRIMARY KEY AUTOINCREMENT,
          entityId TEXT NOT NULL,
          action TEXT NOT NULL,
          payload TEXT NOT NULL,
          createdAt TEXT NOT NULL
        );
      `);
    });
  };

  const loadSurveys = () => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY datetime(updatedAt) DESC;`,
        [],
        (_, result) => {
          setSurveys(result.rows._array);
        },
        (_, error) => {
          console.error('Load surveys error:', error);
          return false;
        }
      );
    });
  };

  const addSurvey = () => {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    const now = new Date().toISOString();
    const survey = {
      id: uuidv4(),
      title: title.trim(),
      location: location.trim(),
      notes: notes.trim(),
      createdAt: now,
      updatedAt: now,
      version: 1,
      syncStatus: 'pending',
    };

    db.transaction((tx) => {
      tx.executeSql(
        `INSERT INTO surveys (id, title, location, notes, createdAt, updatedAt, version, syncStatus)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.createdAt,
          survey.updatedAt,
          survey.version,
          survey.syncStatus,
        ]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (entityId, action, payload, createdAt)
         VALUES (?, ?, ?, ?);`,
        [survey.id, 'create', JSON.stringify(survey), now]
      );
    },
    (error) => {
      console.error('Transaction error:', error);
    },
    () => {
      setTitle('');
      setLocation('');
      setNotes('');
      loadSurveys();
      if (isOnline) syncPendingSurveys();
    });
  };

  const syncPendingSurveys = async () => {
    if (syncing) return;
    setSyncing(true);

    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY queueId ASC;`,
        [],
        async (_, result) => {
          const queueItems = result.rows._array;

          for (const item of queueItems) {
            try {
              const payload = JSON.parse(item.payload);

              if (item.action === 'create') {
                await axios.post(`${API_BASE_URL}/surveys`, payload);

                db.transaction((tx2) => {
                  tx2.executeSql(
                    `UPDATE surveys SET syncStatus = 'synced' WHERE id = ?;`,
                    [item.entityId]
                  );
                  tx2.executeSql(
                    `DELETE FROM sync_queue WHERE queueId = ?;`,
                    [item.queueId]
                  );
                });
              }

              if (item.action === 'update') {
                await axios.put(`${API_BASE_URL}/surveys/${item.entityId}`, payload);

                db.transaction((tx2) => {
                  tx2.executeSql(
                    `UPDATE surveys SET syncStatus = 'synced' WHERE id = ?;`,
                    [item.entityId]
                  );
                  tx2.executeSql(
                    `DELETE FROM sync_queue WHERE queueId = ?;`,
                    [item.queueId]
                  );
                });
              }
            } catch (err) {
              console.error('Sync failed for item:', item.queueId, err.message);
              break;
            }
          }

          loadSurveys();
          setSyncing(false);
        },
        (_, error) => {
          console.error('Queue fetch error:', error);
          setSyncing(false);
          return false;
        }
      );
    });
  };

  const updateSurvey = (survey) => {
    const now = new Date().toISOString();
    const updatedSurvey = {
      ...survey,
      notes: survey.notes + ' (edited)',
      updatedAt: now,
      version: survey.version + 1,
      syncStatus: 'pending',
    };

    db.transaction((tx) => {
      tx.executeSql(
        `UPDATE surveys
         SET title = ?, location = ?, notes = ?, updatedAt = ?, version = ?, syncStatus = ?
         WHERE id = ?;`,
        [
          updatedSurvey.title,
          updatedSurvey.location,
          updatedSurvey.notes,
          updatedSurvey.updatedAt,
          updatedSurvey.version,
          updatedSurvey.syncStatus,
          updatedSurvey.id,
        ]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (entityId, action, payload, createdAt)
         VALUES (?, ?, ?, ?);`,
        [updatedSurvey.id, 'update', JSON.stringify(updatedSurvey), now]
      );
    },
    (error) => {
      console.error('Update transaction error:', error);
    },
    () => {
      loadSurveys();
      if (isOnline) syncPendingSurveys();
    });
  };

  const renderItem = ({ item }) => (
    <View style={styles.card}>
      <Text style={styles.title}>{item.title}</Text>
      <Text>Location: {item.location || '-'}</Text>
      <Text>Notes: {item.notes || '-'}</Text>
      <Text>Status: {item.syncStatus}</Text>
      <Text>Version: {item.version}</Text>
      <Button title="Quick Edit" onPress={() => updateSurvey(item)} />
    </View>
  );

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text>Online: {isOnline ? 'Yes' : 'No'}</Text>
      <Text>Syncing: {syncing ? 'Yes' : 'No'}</Text>

      <TextInput
        style={styles.input}
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
      />
      <TextInput
        style={styles.input}
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
      />
      <TextInput
        style={styles.input}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
      />

      <Button title="Add Survey" onPress={addSurvey} />
      <View style={{ height: 16 }} />
      <Button title="Manual Sync" onPress={syncPendingSurveys} />

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={renderItem}
        contentContainerStyle={{ paddingBottom: 40, paddingTop: 20 }}
      />
    </SafeAreaView>
  );
}

