```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/surveys', (req, res) => {
  const survey = req.body;

  if (!survey.id || !survey.title) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const existing = surveys.get(survey.id);
  if (existing) {
    return res.status(409).json({ error: 'Survey already exists' });
  }

  surveys.set(survey.id, {
    ...survey,
    serverReceivedAt: new Date().toISOString(),
  });

  res.status(201).json({ success: true, survey: surveys.get(survey.id) });
});

app.put('/surveys/:id', (req, res) => {
  const { id } = req.params;
  const incoming = req.body;
  const existing = surveys.get(id);

  if (!existing) {
    return res.status(404).json({ error: 'Survey not found' });
  }

  if ((incoming.version || 0) < (existing.version || 0)) {
    return res.status(409).json({
      error: 'Version conflict',
      serverRecord: existing,
    });
  }

  const updated = {
    ...existing,
    ...incoming,
    serverReceivedAt: new Date().toISOString(),
  };

  surveys.set(id, updated);
  res.json({ success: true, survey: updated });
});

app.listen(3000, () => {
  console.log('Survey sync server running on port 3000');
});
```

