# 2. IndexedDB setup

## `src/db.js`

```javascript
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;
const SURVEY_STORE = 'surveys';
const OUTBOX_STORE = 'outbox';

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains(SURVEY_STORE)) {
      const surveyStore = db.createObjectStore(SURVEY_STORE, {
        keyPath: 'localId',
      });
      surveyStore.createIndex('synced', 'synced');
      surveyStore.createIndex('updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains(OUTBOX_STORE)) {
      const outboxStore = db.createObjectStore(OUTBOX_STORE, {
        keyPath: 'id',
        autoIncrement: true,
      });
      outboxStore.createIndex('status', 'status');
      outboxStore.createIndex('createdAt', 'createdAt');
    }
  },
});

export async function saveSurveyOffline(survey) {
  const db = await dbPromise;
  await db.put(SURVEY_STORE, survey);
}

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll(SURVEY_STORE);
}

export async function getUnsyncedSurveys() {
  const db = await dbPromise;
  const tx = db.transaction(SURVEY_STORE, 'readonly');
  const index = tx.store.index('synced');
  return index.getAll(false);
}

export async function markSurveySynced(localId, serverId) {
  const db = await dbPromise;
  const survey = await db.get(SURVEY_STORE, localId);
  if (!survey) return;

  survey.synced = true;
  survey.serverId = serverId;
  survey.lastSyncedAt = new Date().toISOString();

  await db.put(SURVEY_STORE, survey);
}

export async function addToOutbox(action) {
  const db = await dbPromise;
  return db.add(OUTBOX_STORE, {
    ...action,
    status: 'pending',
    createdAt: new Date().toISOString(),
  });
}

export async function getPendingOutboxItems() {
  const db = await dbPromise;
  const tx = db.transaction(OUTBOX_STORE, 'readonly');
  const index = tx.store.index('status');
  return index.getAll('pending');
}

export async function markOutboxItemDone(id) {
  const db = await dbPromise;
  const item = await db.get(OUTBOX_STORE, id);
  if (!item) return;
  item.status = 'done';
  item.completedAt = new Date().toISOString();
  await db.put(OUTBOX_STORE, item);
}

export async function markOutboxItemFailed(id, error) {
  const db = await dbPromise;
  const item = await db.get(OUTBOX_STORE, id);
  if (!item) return;
  item.status = 'failed';
  item.error = error;
  item.failedAt = new Date().toISOString();
  await db.put(OUTBOX_STORE, item);
}
```

