# 4. Sync engine

## `src/sync.js`

```javascript
import {
  getPendingOutboxItems,
  markOutboxItemDone,
  markOutboxItemFailed,
  markSurveySynced,
} from './db';
import { uploadSurvey } from './api';

let syncInProgress = false;

export async function syncOutbox() {
  if (syncInProgress) return;
  if (!navigator.onLine) return;

  syncInProgress = true;

  try {
    const items = await getPendingOutboxItems();

    for (const item of items) {
      try {
        if (item.type === 'CREATE_SURVEY') {
          const result = await uploadSurvey(item.payload);
          await markSurveySynced(item.payload.localId, result.id);
          await markOutboxItemDone(item.id);
        } else {
          await markOutboxItemFailed(item.id, 'Unknown action type');
        }
      } catch (err) {
        console.error('Sync failed for outbox item', item.id, err);
        await markOutboxItemFailed(item.id, err.message);
      }
    }
  } finally {
    syncInProgress = false;
  }
}

export function setupAutoSync() {
  window.addEventListener('online', () => {
    syncOutbox();
  });
}
