import { useState } from 'react';
import { saveSurveyOffline, addToOutbox } from './db';
import { syncOutbox } from './sync';

function generateLocalId() {
  return `local_${crypto.randomUUID()}`;
}

export default function SurveyForm({ onSaved }) {
  const [surveyorName, setSurveyorName] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setSaving(true);

    const now = new Date().toISOString();

    const survey = {
      localId: generateLocalId(),
      surveyorName,
      location,
      notes,
      createdAt: now,
      updatedAt: now,
      synced: false,
    };

    try {
      await saveSurveyOffline(survey);

      await addToOutbox({
        type: 'CREATE_SURVEY',
        payload: survey,
      });

      if (navigator.onLine) {
        await syncOutbox();
      }

      setSurveyorName('');
      setLocation('');
      setNotes('');
      onSaved?.();
    } catch (err) {
      console.error('Failed to save survey', err);
      alert('Failed to save survey locally.');
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} style={{ padding: 16, border: '1px solid #ccc' }}>
      <h2>New Survey</h2>

      <div>
        <label>Surveyor Name</label>
        <br />
        <input
          value={surveyorName}
          onChange={(e) => setSurveyorName(e.target.value)}
          required
