      <div>
        <label>Location</label>
        <br />
        <input
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
      </div>

      <div>
        <label>Notes</label>
        <br />
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={4}
        />
      </div>

      <button type="submit" disabled={saving}>
        {saving ? 'Saving...' : 'Save Survey'}
      </button>

      <p>{navigator.onLine ? 'Online' : 'Offline'}</p>
    </form>
  );
}
