## `surveyRepository.js` — Save locally first

```javascript
import { getDB } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function saveSurveyLocally({
  id,
  title,
  latitude,
  longitude,
  notes,
}) {
  const db = await getDB();
  const surveyId = id || uuidv4();
  const updatedAt = new Date().toISOString();

  const payload = {
    id: surveyId,
    title,
    latitude,
    longitude,
    notes,
    updated_at: updatedAt,
  };

  await db.executeSql(
    `
    INSERT OR REPLACE INTO surveys
    (id, title, latitude, longitude, notes, updated_at, sync_status)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    `,
    [
      surveyId,
      title,
      latitude,
      longitude,
      notes,
      updatedAt,
      'pending_sync',
    ]
  );

  await db.executeSql(
    `
    INSERT INTO outbox (record_id, operation, payload, created_at)
    VALUES (?, ?, ?, ?)
    `,
    [surveyId, 'UPSERT', JSON.stringify(payload), updatedAt]
  );

  return payload;
}

export async function getAllSurveys() {
  const db = await getDB();
  const [result] = await db.executeSql(`SELECT * FROM surveys ORDER BY updated_at DESC`);
  const rows = [];

  for (let i = 0; i < result.rows.length; i++) {
    rows.push(result.rows.item(i));
  }

  return rows;
}
```

