## `syncService.js` — Sync queued changes when online

```javascript
import axios from 'axios';
import NetInfo from '@react-native-community/netinfo';
import { getDB } from './db';

const API_BASE_URL = 'http://YOUR_SERVER_IP:3000';

export async function syncOutbox() {
  const netState = await NetInfo.fetch();
  if (!netState.isConnected) {
    console.log('Offline, skipping sync');
    return;
  }

  const db = await getDB();
  const [result] = await db.executeSql(`
    SELECT * FROM outbox ORDER BY created_at ASC
  `);

  for (let i = 0; i < result.rows.length; i++) {
    const item = result.rows.item(i);

    try {
      const payload = JSON.parse(item.payload);

      const response = await axios.post(`${API_BASE_URL}/sync/survey`, payload);

      if (response.status === 200) {
        await db.executeSql(`DELETE FROM outbox WHERE id = ?`, [item.id]);
        await db.executeSql(
          `UPDATE surveys SET sync_status = ? WHERE id = ?`,
          ['synced', item.record_id]
        );
      }
    } catch (error) {
      console.log('Sync failed for outbox item', item.id, error.message);
      break;
    }
  }
}
```

