## `server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Basic last-write-wins sync
 */
app.post('/sync/survey', (req, res) => {
  const incoming = req.body;

  if (!incoming.id) {
    return res.status(400).json({ error: 'Missing survey id' });
  }

  const existing = surveys.get(incoming.id);

  if (!existing) {
    surveys.set(incoming.id, incoming);
    return res.status(200).json({
      status: 'created',
      record: incoming,
    });
  }

  const existingTime = new Date(existing.updated_at).getTime();
  const incomingTime = new Date(incoming.updated_at).getTime();

  if (incomingTime >= existingTime) {
    surveys.set(incoming.id, incoming);
    return res.status(200).json({
      status: 'updated',
      record: incoming,
    });
  }

  return res.status(200).json({
    status: 'ignored_older_update',
    record: existing,
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

