# 3. Local database setup

## `db/database.js`

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('surveys.db');

export const initDB = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          title TEXT NOT NULL,
          location TEXT,
          notes TEXT,
          status TEXT NOT NULL,
          lastModified INTEGER NOT NULL,
          synced INTEGER NOT NULL
        );`
      );

      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS sync_queue (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          surveyId TEXT NOT NULL,
          action TEXT NOT NULL,
          payload TEXT NOT NULL,
          createdAt INTEGER NOT NULL
        );`,
        [],
        () => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY lastModified DESC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const getSurveyById = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE id = ?;`,
        [id],
        (_, result) => resolve(result.rows._array[0]),
        (_, error) => reject(error)
      );
    });
  });
};

export const saveSurveyLocally = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys
          (id, title, location, notes, status, lastModified, synced)
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location || '',
          survey.notes || '',
          survey.status || 'draft',
          survey.lastModified,
          survey.synced ? 1 : 0
        ],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const addToSyncQueue = ({ surveyId, action, payload }) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (surveyId, action, payload, createdAt)
         VALUES (?, ?, ?, ?);`,
        [surveyId, action, JSON.stringify(payload), Date.now()],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const getSyncQueue = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY createdAt ASC;`,
        [],
        (_, result) => {
          const rows = result.rows._array.map(item => ({
            ...item,
            payload: JSON.parse(item.payload)
          }));
          resolve(rows);
        },
        (_, error) => reject(error)
      );
    });
  });
};

export const removeSyncQueueItem = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?;`,
        [id],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const markSurveySynced = (surveyId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id = ?;`,
        [surveyId],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export default db;
```

