const API_BASE_URL = 'https://your-api.example.com';

export const pushSurveyToServer = async (survey) => {
  const response = await fetch(`${API_BASE_URL}/surveys/${survey.id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(survey)
  });

  if (!response.ok) {
    throw new Error(`Push failed: ${response.status}`);
  }

  return response.json();
};

export const fetchUpdatedSurveysFromServer = async (lastSyncTime = 0) => {
  const response = await fetch(
    `${API_BASE_URL}/surveys?updatedSince=${lastSyncTime}`
  );

  if (!response.ok) {
    throw new Error(`Fetch failed: ${response.status}`);
  }

  return response.json();
};
```

