# 5. Sync engine

This service:

- reads queued local changes
- pushes them to the server
- marks them synced
- pulls newer server records
- merges them into local DB

## `services/syncService.js`

```javascript
import {
  getSyncQueue,
  removeSyncQueueItem,
  markSurveySynced,
  saveSurveyLocally,
  getAllSurveys
} from '../db/database';
import {
  pushSurveyToServer,
  fetchUpdatedSurveysFromServer
} from './api';

let lastSyncTime = 0;
let syncInProgress = false;

export const syncData = async () => {
  if (syncInProgress) return;
  syncInProgress = true;

  try {
    const queue = await getSyncQueue();

    for (const item of queue) {
      try {
        await pushSurveyToServer(item.payload);
        await markSurveySynced(item.surveyId);
        await removeSyncQueueItem(item.id);
      } catch (err) {
        console.log('Failed to sync queue item:', item.id, err.message);
      }
    }

    const serverUpdates = await fetchUpdatedSurveysFromServer(lastSyncTime);
    const localSurveys = await getAllSurveys();
    const localMap = new Map(localSurveys.map(s => [s.id, s]));

    for (const remote of serverUpdates) {
      const local = localMap.get(remote.id);

      if (!local || remote.lastModified > local.lastModified) {
        await saveSurveyLocally({
          ...remote,
          synced: true
        });
      }
    }

    lastSyncTime = Date.now();
  } catch (err) {
    console.log('Sync failed:', err.message);
  } finally {
    syncInProgress = false;
  }
};
```

