## `surveyRepository.js` — local CRUD

```javascript
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';

function nowIso() {
  return new Date().toISOString();
}

export function createSurvey({ title, locationLat, locationLng, notes }) {
  const db = getDb();
  const id = uuidv4();
  const updatedAt = nowIso();

  db.runSync(
    `INSERT INTO surveys
      (id, title, locationLat, locationLng, notes, updatedAt, deleted, isDirty)
     VALUES (?, ?, ?, ?, ?, ?, 0, 1)`,
    [id, title, locationLat, locationLng, notes, updatedAt]
  );

  return id;
}

export function updateSurvey(id, updates) {
  const db = getDb();
  const existing = db.getFirstSync(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (!existing) return false;

  const title = updates.title ?? existing.title;
  const locationLat = updates.locationLat ?? existing.locationLat;
  const locationLng = updates.locationLng ?? existing.locationLng;
  const notes = updates.notes ?? existing.notes;
  const updatedAt = nowIso();

  db.runSync(
    `UPDATE surveys
     SET title = ?, locationLat = ?, locationLng = ?, notes = ?, updatedAt = ?, isDirty = 1
     WHERE id = ?`,
    [title, locationLat, locationLng, notes, updatedAt, id]
  );

  return true;
}

export function softDeleteSurvey(id) {
  const db = getDb();
  db.runSync(
    `UPDATE surveys
     SET deleted = 1, updatedAt = ?, isDirty = 1
     WHERE id = ?`,
    [nowIso(), id]
  );
}

export function getAllSurveys() {
  const db = getDb();
  return db.getAllSync(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );
}

export function getDirtySurveys() {
  const db = getDb();
  return db.getAllSync(`SELECT * FROM surveys WHERE isDirty = 1`);
}

export function markSurveyClean(id, updatedAt) {
  const db = getDb();
  db.runSync(
    `UPDATE surveys SET isDirty = 0, updatedAt = ? WHERE id = ?`,
    [updatedAt, id]
  );
}

export function upsertSurveyFromServer(record) {
  const db = getDb();
  const local = db.getFirstSync(`SELECT * FROM surveys WHERE id = ?`, [record.id]);

  if (!local) {
    db.runSync(
      `INSERT INTO surveys
       (id, title, locationLat, locationLng, notes, updatedAt, deleted, isDirty)
       VALUES (?, ?, ?, ?, ?, ?, ?, 0)`,
      [
        record.id,
        record.title,
        record.locationLat,
        record.locationLng,
        record.notes,
        record.updatedAt,
        record.deleted ? 1 : 0,
      ]
    );
    return;
  }

  // Preserve local dirty edits; only overwrite if local is clean
  if (local.isDirty === 1) return;

  db.runSync(
    `UPDATE surveys
     SET title = ?, locationLat = ?, locationLng = ?, notes = ?, updatedAt = ?, deleted = ?, isDirty = 0
     WHERE id = ?`,
    [
      record.title,
      record.locationLat,
      record.locationLng,
      record.notes,
      record.updatedAt,
      record.deleted ? 1 : 0,
      record.id,
    ]
  );
}

export function getLastSyncTime() {
  const db = getDb();
  const row = db.getFirstSync(`SELECT value FROM sync_meta WHERE key = 'lastSyncTime'`);
  return row?.value || '1970-01-01T00:00:00.000Z';
}

export function setLastSyncTime(value) {
  const db = getDb();
  const existing = db.getFirstSync(`SELECT key FROM sync_meta WHERE key = 'lastSyncTime'`);

  if (existing) {
    db.runSync(`UPDATE sync_meta SET value = ? WHERE key = 'lastSyncTime'`, [value]);
  } else {
    db.runSync(`INSERT INTO sync_meta (key, value) VALUES ('lastSyncTime', ?)`, [value]);
  }
}
```

