## `syncService.js` — push/pull sync

```javascript
import * as Network from 'expo-network';
import {
  getDirtySurveys,
  markSurveyClean,
  upsertSurveyFromServer,
  getLastSyncTime,
  setLastSyncTime,
} from './surveyRepository';

const API_BASE = 'http://YOUR_SERVER_IP:3000';

export async function isOnline() {
  const state = await Network.getNetworkStateAsync();
  return state.isConnected && state.isInternetReachable;
}

export async function syncSurveys() {
  const online = await isOnline();
  if (!online) {
    return { success: false, message: 'Offline' };
  }

  try {
    // 1. Push local dirty records
    const dirty = getDirtySurveys();

    if (dirty.length > 0) {
      const pushResponse = await fetch(`${API_BASE}/sync/push`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ records: dirty }),
      });

      if (!pushResponse.ok) {
        throw new Error('Push sync failed');
      }

      const pushResult = await pushResponse.json();

      for (const item of pushResult.synced) {
        markSurveyClean(item.id, item.updatedAt);
      }
    }

    // 2. Pull server updates since last sync
    const lastSyncTime = getLastSyncTime();
    const pullResponse = await fetch(
      `${API_BASE}/sync/pull?since=${encodeURIComponent(lastSyncTime)}`
    );

    if (!pullResponse.ok) {
      throw new Error('Pull sync failed');
    }

    const pullResult = await pullResponse.json();

    for (const record of pullResult.records) {
      upsertSurveyFromServer(record);
    }

    setLastSyncTime(new Date().toISOString());

    return { success: true, message: 'Sync complete' };
  } catch (err) {
    return { success: false, message: err.message };
  }
}
```

