const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map(); // Replace with PostgreSQL/MongoDB in production

function nowIso() {
  return new Date().toISOString();
}

// Push endpoint: client sends dirty records
app.post('/sync/push', (req, res) => {
  const { records } = req.body;

  if (!Array.isArray(records)) {
    return res.status(400).json({ error: 'records must be an array' });
  }

  const synced = [];

  for (const record of records) {
    const existing = surveys.get(record.id);

    // Last-write-wins strategy
    if (!existing || new Date(record.updatedAt) >= new Date(existing.updatedAt)) {
      const serverRecord = {
        id: record.id,
        title: record.title,
        locationLat: record.locationLat,
        locationLng: record.locationLng,
        notes: record.notes,
        deleted: !!record.deleted,
        updatedAt: nowIso(),
      };

      surveys.set(record.id, serverRecord);
      synced.push({ id: record.id, updatedAt: serverRecord.updatedAt });
    } else {
      // If server version is newer, client should later pull it
      synced.push({ id: record.id, updatedAt: existing.updatedAt });
    }
  }

  res.json({ synced });
});

// Pull endpoint: client asks for records changed since timestamp
app.get('/sync/pull', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';
  const sinceDate = new Date(since);

  const records = Array.from(surveys.values()).filter(
    (record) => new Date(record.updatedAt) > sinceDate
  );

  res.json({ records });
});

app.get('/health', (req, res) => {
  res.json({ ok: true });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Sync server running on port ${PORT}`);
});
```

