# 3. Mobile App Code

## `db.js`
Creates local SQLite tables for surveys and sync queue.

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDb = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          title TEXT,
          location TEXT,
          notes TEXT,
          updatedAt INTEGER,
          synced INTEGER DEFAULT 0
        );
      `);

      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS sync_queue (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          entityType TEXT NOT NULL,
          entityId TEXT NOT NULL,
          action TEXT NOT NULL,
          payload TEXT NOT NULL,
          createdAt INTEGER NOT NULL
        );
      `);
    }, reject, resolve);
  });
};

export const saveSurveyLocally = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys (id, title, location, notes, updatedAt, synced)
         VALUES (?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updatedAt,
          0
        ]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (entityType, entityId, action, payload, createdAt)
         VALUES (?, ?, ?, ?, ?);`,
        [
          'survey',
          survey.id,
          'upsert',
          JSON.stringify(survey),
          Date.now()
        ]
      );
    }, reject, resolve);
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY updatedAt DESC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
};

export const getPendingQueueItems = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY createdAt ASC;`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
};

export const removeQueueItem = (queueId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?;`,
        [queueId],
        () => resolve(),
        (_, err) => reject(err)
      );
    });
  });
};

export const markSurveySynced = (surveyId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id = ?;`,
        [surveyId],
        () => resolve(),
        (_, err) => reject(err)
      );
    });
  });
};

export default db;
```

