## `sync.js`
Processes queued operations when online.

```javascript
import NetInfo from '@react-native-community/netinfo';
import { getPendingQueueItems, removeQueueItem, markSurveySynced } from './db';
import { uploadSurvey } from './api';

let syncing = false;

export const syncPendingData = async () => {
  if (syncing) return;
  syncing = true;

  try {
    const queue = await getPendingQueueItems();

    for (const item of queue) {
      const payload = JSON.parse(item.payload);

      if (item.entityType === 'survey' && item.action === 'upsert') {
        await uploadSurvey(payload);
        await markSurveySynced(item.entityId);
        await removeQueueItem(item.id);
      }
    }
  } catch (err) {
    console.log('Sync error:', err.message);
  } finally {
    syncing = false;
  }
};

export const startNetworkListener = () => {
  return NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncPendingData();
    }
  });
};
```

