## `client/src/sync.js`

This handles sync when online.

```javascript
import { getUnsyncedSurveys, markSurveySynced } from './db';
import { sendSurveyToServer } from './api';

let syncInProgress = false;

export async function syncSurveys() {
  if (syncInProgress || !navigator.onLine) return;

  syncInProgress = true;

  try {
    const unsynced = await getUnsyncedSurveys();

    for (const survey of unsynced) {
      try {
        const result = await sendSurveyToServer(survey);
        await markSurveySynced(survey.localId, result.id);
      } catch (err) {
        console.error('Failed syncing survey', survey.localId, err);
      }
    }
  } finally {
    syncInProgress = false;
  }
}

export function setupAutoSync() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncSurveys();
  });
}
```

