## `client/src/db.js`

```js
import { openDB } from 'idb';

const DB_NAME = 'fieldSurveyDB';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      db.createObjectStore('surveys', { keyPath: 'id' });
    }

    if (!db.objectStoreNames.contains('responses')) {
      const store = db.createObjectStore('responses', { keyPath: 'localId' });
      store.createIndex('by_synced', 'synced');
      store.createIndex('by_surveyId', 'surveyId');
    }

    if (!db.objectStoreNames.contains('syncQueue')) {
      const store = db.createObjectStore('syncQueue', { keyPath: 'id', autoIncrement: true });
      store.createIndex('by_status', 'status');
    }
  }
});

export async function saveSurveys(surveys) {
  const db = await dbPromise;
  const tx = db.transaction('surveys', 'readwrite');
  for (const survey of surveys) {
    await tx.store.put(survey);
  }
  await tx.done;
}

export async function getSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function saveResponse(response) {
  const db = await dbPromise;
  const tx = db.transaction(['responses', 'syncQueue'], 'readwrite');

  const responseRecord = {
    ...response,
    localId: crypto.randomUUID(),
    synced: false,
    updatedAt: new Date().toISOString()
  };

  await tx.objectStore('responses').put(responseRecord);
  await tx.objectStore('syncQueue').put({
    type: 'CREATE_RESPONSE',
    payload: responseRecord,
    status: 'pending',
    createdAt: new Date().toISOString()
  });

  await tx.done;
  return responseRecord;
}

export async function getResponsesBySurvey(surveyId) {
  const db = await dbPromise;
  return db.getAllFromIndex('responses', 'by_surveyId', surveyId);
}

export async function getPendingQueueItems() {
  const db = await dbPromise;
  return db.getAllFromIndex('syncQueue', 'by_status', 'pending');
}

export async function markQueueItemSynced(id) {
  const db = await dbPromise;
  const item = await db.get('syncQueue', id);
  if (!item) return;
  item.status = 'synced';
  item.syncedAt = new Date().toISOString();
  await db.put('syncQueue', item);
}

export async function markResponseSynced(localId, serverId) {
  const db = await dbPromise;
  const response = await db.get('responses', localId);
  if (!response) return;
  response.synced = true;
  response.serverId = serverId;
  response.syncedAt = new Date().toISOString();
  await db.put('responses', response);
}
```

