## `client/src/sync.js`

```js
import {
  getPendingQueueItems,
  markQueueItemSynced,
  markResponseSynced
} from './db';
import { syncResponseToServer } from './api';

let syncing = false;

export async function syncPendingData() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const items = await getPendingQueueItems();

    for (const item of items) {
      try {
        if (item.type === 'CREATE_RESPONSE') {
          const result = await syncResponseToServer(item.payload);
          await markResponseSynced(item.payload.localId, result.serverId);
          await markQueueItemSynced(item.id);
        }
      } catch (err) {
        console.error('Failed to sync item', item.id, err);
      }
    }
  } finally {
    syncing = false;
  }
}

export function setupAutoSync() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncPendingData();
  });
}
```

