## `client/src/App.jsx`

```jsx
import { useEffect, useState } from 'react';
import { fetchSurveysFromServer } from './api';
import { getSurveys, saveSurveys } from './db';
import { setupAutoSync, syncPendingData } from './sync';
import { useOnlineStatus } from './useOnlineStatus';
import SurveyList from './components/SurveyList';
import SurveyForm from './components/SurveyForm';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [selectedSurvey, setSelectedSurvey] = useState(null);
  const [status, setStatus] = useState('');
  const isOnline = useOnlineStatus();

  useEffect(() => {
    setupAutoSync();

    async function loadSurveys() {
      const localSurveys = await getSurveys();
      if (localSurveys.length > 0) {
        setSurveys(localSurveys);
      }

      if (navigator.onLine) {
        try {
          const remoteSurveys = await fetchSurveysFromServer();
          await saveSurveys(remoteSurveys);
          setSurveys(remoteSurveys);
          setStatus('Surveys updated from server.');
          await syncPendingData();
        } catch (err) {
          console.error(err);
          setStatus('Using offline survey cache.');
        }
      } else {
        setStatus('Offline mode: using local data.');
      }
    }

    loadSurveys();
  }, []);

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>Status: {isOnline ? 'Online' : 'Offline'}</p>
      <p>{status}</p>

      {!selectedSurvey ? (
        <SurveyList surveys={surveys} onSelect={setSelectedSurvey} />
      ) : (
        <div>
          <button onClick={() => setSelectedSurvey(null)}>Back</button>
          <SurveyForm survey={selectedSurvey} />
        </div>
      )}
    </div>
  );
}
