# 8. Optional: Better Sync Queue Logic

Here’s a more robust replacement for queue processing:

```js
export async function markQueueItemFailed(id, errorMessage) {
  const db = await dbPromise;
  const item = await db.get('syncQueue', id);
  if (!item) return;

  const retryCount = (item.retryCount || 0) + 1;
  const delayMs = Math.min(60000, 1000 * 2 ** retryCount);

  item.status = 'pending';
  item.retryCount = retryCount;
  item.lastError = errorMessage;
  item.nextRetryAt = new Date(Date.now() + delayMs).toISOString();
  item.updatedAt = new Date().toISOString();

  await db.put('syncQueue', item);
}
```

And in sync logic:

```js
const now = Date.now();
for (const item of items) {
  if (item.nextRetryAt && new Date(item.nextRetryAt).getTime() > now) {
    continue;
  }

  try {
    // sync item
  } catch (err) {
    await markQueueItemFailed(item.id, err.message);
  }
}
```

