## `backend/server.js`

```js
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const PORT = 4000;

/**
 * Simple in-memory store.
 * Replace with a real DB in production.
 */
const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id,
 *   localId,
 *   title,
 *   location,
 *   notes,
 *   updatedAt,
 *   deleted
 * }
 */

app.get('/surveys', (req, res) => {
  const all = Array.from(surveys.values()).filter(s => !s.deleted);
  res.json(all);
});

app.post('/sync', (req, res) => {
  const { operations = [] } = req.body;

  const results = [];

  for (const op of operations) {
    const { type, record } = op;

    if (type === 'create') {
      const id = record.id && !record.id.startsWith('local-') ? record.id : uuidv4();
      const saved = {
        ...record,
        id,
        updatedAt: new Date().toISOString(),
        deleted: false
      };
      surveys.set(id, saved);

      results.push({
        success: true,
        type,
        localId: record.localId || record.id,
        serverRecord: saved
      });
    }

    if (type === 'update') {
      const existing = surveys.get(record.id);
      if (existing) {
        const updated = {
          ...existing,
          ...record,
          updatedAt: new Date().toISOString()
        };
        surveys.set(record.id, updated);

        results.push({
          success: true,
          type,
          localId: record.localId || record.id,
          serverRecord: updated
        });
      } else {
        results.push({
          success: false,
          type,
          localId: record.localId || record.id,
          error: 'Record not found'
        });
      }
    }

    if (type === 'delete') {
      const existing = surveys.get(record.id);
      if (existing) {
        const deleted = {
          ...existing,
          deleted: true,
          updatedAt: new Date().toISOString()
        };
        surveys.set(record.id, deleted);

        results.push({
          success: true,
          type,
          localId: record.localId || record.id,
          serverRecord: deleted
        });
      } else {
        results.push({
          success: false,
          type,
          localId: record.localId || record.id,
          error: 'Record not found'
        });
      }
    }
  }

  const serverState = Array.from(surveys.values());

  res.json({
    results,
    serverState
  });
});

app.listen(PORT, () => {
  console.log(`Backend running on http://localhost:${PORT}`);
});
