```js
import { openDB } from 'idb';

const DB_NAME = 'survey-offline-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
      surveyStore.createIndex('updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains('syncQueue')) {
      const queueStore = db.createObjectStore('syncQueue', {
        keyPath: 'queueId',
        autoIncrement: true
      });
      queueStore.createIndex('status', 'status');
    }

    if (!db.objectStoreNames.contains('meta')) {
      db.createObjectStore('meta', { keyPath: 'key' });
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  const all = await db.getAll('surveys');
  return all.filter(s => !s.deleted);
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function deleteSurveyLocal(id) {
  const db = await dbPromise;
  const survey = await db.get('surveys', id);
  if (survey) {
    await db.put('surveys', {
      ...survey,
      deleted: true,
      updatedAt: new Date().toISOString()
    });
  }
}

export async function enqueueOperation(operation) {
  const db = await dbPromise;
  await db.add('syncQueue', {
    ...operation,
    status: 'pending',
    createdAt: new Date().toISOString()
  });
}

export async function getPendingOperations() {
  const db = await dbPromise;
  return db.getAllFromIndex('syncQueue', 'status', 'pending');
}

export async function removeQueueItem(queueId) {
  const db = await dbPromise;
  await db.delete('syncQueue', queueId);
}

export async function replaceAllSurveys(serverState) {
  const db = await dbPromise;
  const tx = db.transaction('surveys', 'readwrite');
  await tx.store.clear();

  for (const survey of serverState) {
    await tx.store.put(survey);
  }

  await tx.done;
}
```

