## `frontend/src/sync.js`

```js
import {
  getPendingOperations,
  removeQueueItem,
  replaceAllSurveys
} from './db';
import { syncOperations } from './api';

let syncing = false;

export async function runSync() {
  if (syncing || !navigator.onLine) return { skipped: true };

  syncing = true;

  try {
    const pending = await getPendingOperations();

    if (pending.length === 0) {
      syncing = false;
      return { success: true, synced: 0 };
    }

    const payload = pending.map(item => ({
      type: item.type,
      record: item.record
    }));

    const result = await syncOperations(payload);

    for (const item of pending) {
      await removeQueueItem(item.queueId);
    }

    await replaceAllSurveys(result.serverState);

    syncing = false;
    return { success: true, synced: pending.length };
  } catch (err) {
    syncing = false;
    return { success: false, error: err.message };
  }
}
```

