## `frontend/src/App.js`

```js
import React, { useEffect, useState } from 'react';
import SurveyForm from './SurveyForm';
import SurveyList from './SurveyList';
import {
  getAllSurveys,
  saveSurvey,
  deleteSurveyLocal,
  enqueueOperation
} from './db';
import { runSync } from './sync';

function App() {
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState(navigator.onLine ? 'Online' : 'Offline');

  async function loadLocalSurveys() {
    const local = await getAllSurveys();
    setSurveys(local.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)));
  }

  useEffect(() => {
    loadLocalSurveys();

    const onOnline = async () => {
      setStatus('Online');
      await runSync();
      await loadLocalSurveys();
    };

    const onOffline = () => {
      setStatus('Offline');
    };

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    runSync().then(loadLocalSurveys);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function handleSave(data) {
    const localId = `local-${crypto.randomUUID()}`;
    const survey = {
      id: localId,
      localId,
      ...data,
      updatedAt: new Date().toISOString(),
      deleted: false
    };

    await saveSurvey(survey);
    await enqueueOperation({
      type: 'create',
      record: survey
    });

    await loadLocalSurveys();
    await runSync();
    await loadLocalSurveys();
  }

  async function handleDelete(id) {
    await deleteSurveyLocal(id);
    await enqueueOperation({
      type: 'delete',
      record: { id }
    });

    await loadLocalSurveys();
    await runSync();
    await loadLocalSurveys();
  }

  return (
    <div style={{ padding: 20, maxWidth: 700 }}>
      <h1>Offline Field Survey App</h1>
      <p>Status: {status}</p>
      <button onClick={async () => {
        const result = await runSync();
        console.log(result);
        await loadLocalSurveys();
      }}>
        Sync Now
      </button>

      <SurveyForm onSave={handleSave} />
      <SurveyList surveys={surveys} onDelete={handleDelete} />
    </div>
  );
}

export default App;
```

