## `client/src/sync.js`
Sync engine.

```javascript
import {
  getSyncQueue,
  clearSyncQueueItem,
  updateSurveySyncStatus,
  saveSurveyLocally
} from './db';
import { syncBatch, fetchRemoteSurveys } from './api';

let syncing = false;

export async function runSync() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const queue = await getSyncQueue();
    if (queue.length > 0) {
      const result = await syncBatch(queue);

      for (const synced of result.synced) {
        if (synced.localId) {
          await updateSurveySyncStatus(synced.localId, {
            synced: true,
            serverId: synced.serverId,
            updatedAt: synced.updatedAt
          });
        }
      }

      for (const item of queue) {
        await clearSyncQueueItem(item.id);
      }
    }

    const remoteSurveys = await fetchRemoteSurveys();
    for (const survey of remoteSurveys) {
      await saveSurveyLocally({
        ...survey,
        localId: survey.localId || survey.serverId,
        synced: true
      });
    }
  } catch (err) {
    console.error('Sync error:', err);
  } finally {
    syncing = false;
  }
}

export function setupSyncListeners() {
  window.addEventListener('online', runSync);
}
```

