## `server/index.js`
Simple backend with batch sync.

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/sync', (req, res) => {
  const { actions } = req.body;

  if (!Array.isArray(actions)) {
    return res.status(400).json({ error: 'actions must be an array' });
  }

  const synced = [];

  for (const action of actions) {
    if (action.type === 'UPSERT_SURVEY') {
      const payload = action.payload;

      const serverId = payload.serverId || `srv-${crypto.randomUUID()}`;
      const record = {
        ...payload,
        serverId,
        synced: true,
        updatedAt: new Date().toISOString()
      };

      surveys.set(serverId, record);

      synced.push({
        localId: payload.localId,
        serverId,
        updatedAt: record.updatedAt
      });
    }
  }

  res.json({ synced });
});

app.listen(4000, () => {
  console.log('Server running on http://localhost:4000');
});
```

> If your Node version does not expose `crypto.randomUUID()` globally, add:
```javascript
const crypto = require('crypto');
```

