## `frontend/src/sync.js`

```javascript
import { fetchChanges, pushChanges } from './api';
import {
  getPendingSurveys,
  saveSurveys,
  setMeta,
  getMeta
} from './db';

export async function syncData() {
  if (!navigator.onLine) return { synced: false, reason: 'offline' };

  const pending = await getPendingSurveys();

  if (pending.length > 0) {
    const payload = pending.map(({ syncStatus, ...rest }) => rest);
    await pushChanges(payload);

    const syncedRecords = pending.map(item => ({
      ...item,
      syncStatus: 'synced'
    }));
    await saveSurveys(syncedRecords);
  }

  const lastSync = await getMeta('lastSync');
  const remote = await fetchChanges(lastSync || 0);

  const remoteRecords = remote.surveys.map(item => ({
    ...item,
    syncStatus: 'synced'
  }));

  await saveSurveys(remoteRecords);
  await setMeta('lastSync', remote.serverTime);

  return { synced: true };
}
```

