## `frontend/src/App.jsx`

```javascript
import React, { useEffect, useState } from 'react';
import { getAllSurveys, saveSurvey } from './db';
import { syncData } from './sync';

function generateId() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [online, setOnline] = useState(navigator.onLine);
  const [syncMessage, setSyncMessage] = useState('');

  async function loadSurveys() {
    const all = await getAllSurveys();
    setSurveys(all.filter(s => !s.deleted).sort((a, b) => b.updatedAt - a.updatedAt));
  }

  useEffect(() => {
    loadSurveys();

    const goOnline = async () => {
      setOnline(true);
      setSyncMessage('Online. Syncing...');
      try {
        await syncData();
        await loadSurveys();
        setSyncMessage('Sync complete');
      } catch (e) {
        setSyncMessage(`Sync failed: ${e.message}`);
      }
    };

    const goOffline = () => {
      setOnline(false);
      setSyncMessage('Offline mode');
    };

    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);

    if (navigator.onLine) {
      goOnline();
    }

    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  async function addSurvey(e) {
    e.preventDefault();

    const survey = {
      id: generateId(),
      title,
      location,
      notes,
      deleted: false,
      updatedAt: Date.now(),
      syncStatus: 'pending'
    };

    await saveSurvey(survey);
    setTitle('');
    setLocation('');
    setNotes('');
    await loadSurveys();

    if (navigator.onLine) {
      try {
        await syncData();
        await loadSurveys();
        setSyncMessage('Saved and synced');
      } catch (e) {
        setSyncMessage('Saved locally; sync failed');
      }
    } else {
      setSyncMessage('Saved locally');
    }
  }

  async function deleteSurvey(id) {
    const survey = surveys.find(s => s.id === id);
    if (!survey) return;

    await saveSurvey({
      ...survey,
      deleted: true,
      updatedAt: Date.now(),
      syncStatus: 'pending'
    });

    await loadSurveys();

    if (navigator.onLine) {
      try {
        await syncData();
        await loadSurveys();
        setSyncMessage('Deleted and synced');
      } catch {
        setSyncMessage('Deleted locally; sync failed');
      }
    }
  }

  return (
    <div className="container">
      <h1>Field Survey App</h1>
      <div className={`status ${online ? 'online' : 'offline'}`}>
        {online ? 'Online' : 'Offline'}
      </div>
      <p>{syncMessage}</p>

      <form onSubmit={addSurvey} className="survey-form">
        <input
          value={title}
          onChange={e => setTitle(e.target.value)}
          placeholder="Survey title"
          required
        />
        <input
          value={location}
          onChange={e => setLocation(e.target.value)}
          placeholder="Location"
          required
        />
        <textarea
          value={notes}
          onChange={e => setNotes(e.target.value)}
          placeholder="Notes"
        />
        <button type="submit">Save Survey</button>
      </form>

      <ul className="survey-list">
        {surveys.map(survey => (
          <li key={survey.id} className="survey-item">
            <h3>{survey.title}</h3>
            <p><strong>Location:</strong> {survey.location}</p>
            <p>{survey.notes}</p>
            <small>
              {new Date(survey.updatedAt).toLocaleString()} · {survey.syncStatus}
            </small>
            <br />
            <button onClick={() => deleteSurvey(survey.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
