```ts
type Survey = {
  id: string;
  title: string;
  location: string;
  notes: string;
  updatedAt: number;
  synced: boolean;
  deleted?: boolean;
};
```

### Sync queue item

```ts
type SyncQueueItem = {
  id?: number;
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
  createdAt: number;
};
```

