## `src/sync.js`

Sync engine.

```js
import { db } from './db';
import { pushQueueItems, pullSurveys } from './api';

const SYNC_META_KEY = 'lastSuccessfulSync';

export async function enqueueOperation(entityId, operation, payload) {
  await db.syncQueue.add({
    entityId,
    operation,
    payload,
    createdAt: Date.now()
  });
}

export async function getLastSyncTime() {
  return Number(localStorage.getItem(SYNC_META_KEY) || 0);
}

export async function setLastSyncTime(ts) {
  localStorage.setItem(SYNC_META_KEY, String(ts));
}

export async function syncAll() {
  if (!navigator.onLine) return { synced: false, reason: 'offline' };

  const queueItems = await db.syncQueue.orderBy('createdAt').toArray();

  if (queueItems.length > 0) {
    await pushQueueItems(queueItems);

    const ids = queueItems.map(item => item.id);
    await db.syncQueue.bulkDelete(ids);

    for (const item of queueItems) {
      if (item.operation === 'delete') {
        await db.surveys.delete(item.entityId);
      } else {
        await db.surveys.update(item.entityId, { synced: true });
      }
    }
  }

  const lastSync = await getLastSyncTime();
  const serverData = await pullSurveys(lastSync);

  if (serverData.surveys?.length) {
    await db.transaction('rw', db.surveys, async () => {
      for (const survey of serverData.surveys) {
        if (survey.deleted) {
          await db.surveys.delete(survey.id);
        } else {
          await db.surveys.put({
            ...survey,
            synced: true
          });
        }
      }
    });
  }

  await setLastSyncTime(Date.now());

  return { synced: true };
}
```

