## `src/surveyService.js`

Local-first CRUD.

```js
import { db } from './db';
import { enqueueOperation } from './sync';
import { v4 as uuidv4 } from 'uuid';

export async function createSurvey(data) {
  const survey = {
    id: uuidv4(),
    title: data.title || '',
    location: data.location || '',
    notes: data.notes || '',
    updatedAt: Date.now(),
    synced: false,
    deleted: false
  };

  await db.surveys.put(survey);
  await enqueueOperation(survey.id, 'create', survey);

  return survey;
}

export async function updateSurvey(id, updates) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...updates,
    updatedAt: Date.now(),
    synced: false
  };

  await db.surveys.put(updated);
  await enqueueOperation(id, 'update', updated);

  return updated;
}

export async function deleteSurvey(id) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const deletedRecord = {
    ...existing,
    deleted: true,
    updatedAt: Date.now(),
    synced: false
  };

  await db.surveys.put(deletedRecord);
  await enqueueOperation(id, 'delete', {
    id,
    updatedAt: deletedRecord.updatedAt,
    deleted: true
  });
}

export async function listSurveys() {
  return db.surveys
    .filter(s => !s.deleted)
    .sortBy('updatedAt');
}
```

