import React, { useEffect, useState } from 'react';
import { createSurvey, updateSurvey, deleteSurvey, listSurveys } from './surveyService';
import { syncAll } from './sync';
import { useOnlineStatus } from './useOnlineStatus';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [form, setForm] = useState({ title: '', location: '', notes: '' });
  const [editingId, setEditingId] = useState(null);
  const [syncStatus, setSyncStatus] = useState('idle');
  const online = useOnlineStatus();

  async function refresh() {
    const data = await listSurveys();
    setSurveys(data.reverse());
  }

  useEffect(() => {
    refresh();
  }, []);

  useEffect(() => {
    if (online) {
      setSyncStatus('syncing');
      syncAll()
        .then(() => {
          setSyncStatus('synced');
          refresh();
        })
        .catch(() => setSyncStatus('error'));
    } else {
      setSyncStatus('offline');
    }
  }, [online]);

  async function handleSubmit(e) {
    e.preventDefault();

    if (editingId) {
      await updateSurvey(editingId, form);
      setEditingId(null);
    } else {
      await createSurvey(form);
    }

    setForm({ title: '', location: '', notes: '' });
    await refresh();

    if (online) {
      try {
        setSyncStatus('syncing');
        await syncAll();
        setSyncStatus('synced');
        await refresh();
      } catch {
        setSyncStatus('error');
      }
    }
  }

  async function handleEdit(survey) {
    setEditingId(survey.id);
    setForm({
      title: survey.title,
      location: survey.location,
      notes: survey.notes
    });
  }

  async function handleDelete(id) {
    await deleteSurvey(id);
    await refresh();

    if (online) {
      try {
        setSyncStatus('syncing');
        await syncAll();
        setSyncStatus('synced');
        await refresh();
      } catch {
        setSyncStatus('error');
      }
    }
  }

  return (
    <div style={{ maxWidth: 700, margin: '0 auto', padding: 20 }}>
      <h1>Field Survey App</h1>
      <p>
        Status: <strong>{online ? 'Online' : 'Offline'}</strong> | Sync:{' '}
        <strong>{syncStatus}</strong>
      </p>

      <form onSubmit={handleSubmit} style={{ marginBottom: 20 }}>
        <input
          placeholder="Survey title"
          value={form.title}
          onChange={e => setForm({ ...form, title: e.target.value })}
          required
          style={{ display: 'block', width: '100%', marginBottom: 10 }}
        />
        <input
          placeholder="Location"
          value={form.location}
          onChange={e => setForm({ ...form, location: e.target.value })}
          style={{ display: 'block', width: '100%', marginBottom: 10 }}
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={e => setForm({ ...form, notes: e.target.value })}
          style={{ display: 'block', width: '100%', marginBottom: 10 }}
        />
        <button type="submit">
          {editingId ? 'Update Survey' : 'Create Survey'}
        </button>
      </form>

      <ul>
        {surveys.map(survey => (
          <li key={survey.id} style={{ marginBottom: 12, borderBottom: '1px solid #ccc' }}>
            <h3>
              {survey.title} {!survey.synced && <em>(pending sync)</em>}
            </h3>
            <div>Location: {survey.location}</div>
            <div>Notes: {survey.notes}</div>
            <button onClick={() => handleEdit(survey)}>Edit</button>
            <button onClick={() => handleDelete(survey.id)} style={{ marginLeft: 8 }}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

