## `server.js`

```js
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/sync', (req, res) => {
  const { items } = req.body;

  if (!Array.isArray(items)) {
    return res.status(400).json({ error: 'items must be an array' });
  }

  for (const item of items) {
    const { entityId, operation, payload } = item;

    if (operation === 'create' || operation === 'update') {
      const existing = surveys.get(entityId);
      if (!existing || payload.updatedAt >= existing.updatedAt) {
        surveys.set(entityId, {
          ...payload,
          id: entityId
        });
      }
    }

    if (operation === 'delete') {
      const existing = surveys.get(entityId);
      if (!existing || payload.updatedAt >= existing.updatedAt) {
        surveys.set(entityId, {
          id: entityId,
          deleted: true,
          updatedAt: payload.updatedAt
        });
      }
    }
  }

  res.json({ success: true });
});

app.get('/surveys', (req, res) => {
  const since = Number(req.query.since || 0);

  const changed = Array.from(surveys.values()).filter(
    survey => survey.updatedAt >= since
  );

  res.json({ surveys: changed });
});

app.listen(4000, () => {
  console.log('API listening on http://localhost:4000');
});
```

