# 6. Optional improved queue compaction example

Here’s a simple enhancement to reduce duplicate queue entries.

## Replace `enqueueOperation` with:

```js
import { db } from './db';

export async function enqueueOperation(entityId, operation, payload) {
  const existingItems = await db.syncQueue.where('entityId').equals(entityId).toArray();
  const lastItem = existingItems.sort((a, b) => b.createdAt - a.createdAt)[0];

  if (!lastItem) {
    await db.syncQueue.add({
      entityId,
      operation,
      payload,
      createdAt: Date.now()
    });
    return;
  }

  if (lastItem.operation === 'create' && operation === 'update') {
    await db.syncQueue.update(lastItem.id, {
      payload,
      createdAt: Date.now()
    });
    return;
  }

  if ((lastItem.operation === 'create' || lastItem.operation === 'update') && operation === 'delete') {
    if (lastItem.operation === 'create') {
      await db.syncQueue.delete(lastItem.id);
    } else {
      await db.syncQueue.add({
        entityId,
        operation,
        payload,
        createdAt: Date.now()
      });
    }
    return;
  }

  await db.syncQueue.add({
    entityId,
    operation,
    payload,
    createdAt: Date.now()
  });
}
```

