## `backend/server.js`
```js
const express = require("express");
const cors = require("cors");
const db = require("./db");

const app = express();
app.use(cors());
app.use(express.json());

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

app.get("/surveys", (req, res) => {
  const rows = db.prepare(`
    SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC
  `).all();

  res.json(rows.map(normalizeSurvey));
});

app.post("/sync", (req, res) => {
  const { operations } = req.body;

  if (!Array.isArray(operations)) {
    return res.status(400).json({ error: "operations must be an array" });
  }

  const affectedIds = new Set();

  const getSurveyStmt = db.prepare(`SELECT * FROM surveys WHERE id = ?`);
  const insertStmt = db.prepare(`
    INSERT INTO surveys (
      id, siteName, inspectorName, latitude, longitude, notes, status, createdAt, updatedAt, deleted
    ) VALUES (
      @id, @siteName, @inspectorName, @latitude, @longitude, @notes, @status, @createdAt, @updatedAt, @deleted
    )
  `);
  const updateStmt = db.prepare(`
    UPDATE surveys SET
      siteName = @siteName,
      inspectorName = @inspectorName,
      latitude = @latitude,
      longitude = @longitude,
      notes = @notes,
      status = @status,
      createdAt = @createdAt,
      updatedAt = @updatedAt,
      deleted = @deleted
    WHERE id = @id
  `);

  const tx = db.transaction((ops) => {
    for (const op of ops) {
      if (op.type === "upsert" && op.payload) {
        const incoming = { ...op.payload, deleted: op.payload.deleted ? 1 : 0 };
        const existing = getSurveyStmt.get(incoming.id);

        if (!existing) {
          insertStmt.run(incoming);
        } else if (new Date(incoming.updatedAt).getTime() >= new Date(existing.updatedAt).getTime()) {
          updateStmt.run(incoming);
        }

        affectedIds.add(incoming.id);
      }

      if (op.type === "delete") {
        const existing = getSurveyStmt.get(op.surveyId);
        const opTime = new Date(op.timestamp).getTime();

        if (!existing) {
          insertStmt.run({
            id: op.surveyId,
            siteName: "",
            inspectorName: "",
            latitude: 0,
            longitude: 0,
            notes: "",
            status: "draft",
            createdAt: op.timestamp,
            updatedAt: op.timestamp,
            deleted: 1
          });
        } else if (opTime >= new Date(existing.updatedAt).getTime()) {
          updateStmt.run({
            ...existing,
            deleted: 1,
            updatedAt: op.timestamp
          });
        }

        affectedIds.add(op.surveyId);
      }
    }
  });

  tx(operations);

  const ids = Array.from(affectedIds);
  const result = ids.length
    ? db.prepare(
        `SELECT * FROM surveys WHERE id IN (${ids.map(() => "?").join(",")})`
      ).all(...ids).map(normalizeSurvey)
    : [];

  res.json({ success: true, surveys: result });
});

function normalizeSurvey(row) {
  return {
    ...row,
    deleted: !!row.deleted
  };
}

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Backend listening on http://localhost:${PORT}`);
});
```

