## `frontend/src/db.ts`
```ts
import { openDB } from "idb";
import type { Survey, SyncOperation } from "./types";

const DB_NAME = "offline-survey-db";
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("surveys")) {
      db.createObjectStore("surveys", { keyPath: "id" });
    }
    if (!db.objectStoreNames.contains("syncQueue")) {
      db.createObjectStore("syncQueue", { keyPath: "opId" });
    }
  }
});

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await dbPromise;
  const all = await db.getAll("surveys");
  return all.filter((s) => !s.deleted).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

export async function saveSurvey(survey: Survey) {
  const db = await dbPromise;
  await db.put("surveys", survey);
}

export async function deleteSurveyLocal(id: string) {
  const db = await dbPromise;
  const survey = await db.get("surveys", id);
  if (!survey) return;
  survey.deleted = true;
  survey.updatedAt = new Date().toISOString();
  await db.put("surveys", survey);
}

export async function enqueueOperation(op: SyncOperation) {
  const db = await dbPromise;
  await db.put("syncQueue", op);
}

export async function getQueuedOperations(): Promise<SyncOperation[]> {
  const db = await dbPromise;
  return await db.getAll("syncQueue");
}

export async function clearQueuedOperation(opId: string) {
  const db = await dbPromise;
  await db.delete("syncQueue", opId);
}

export async function applyServerSurveys(surveys: Survey[]) {
  const db = await dbPromise;
  const tx = db.transaction("surveys", "readwrite");
  for (const survey of surveys) {
    await tx.store.put(survey);
  }
  await tx.done;
}
```

