## `frontend/src/sync.ts`
```ts
import { getQueuedOperations, clearQueuedOperation, applyServerSurveys } from "./db";
import { syncOperations } from "./api";

let syncing = false;

export async function syncPendingOperations() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const ops = await getQueuedOperations();
    if (ops.length === 0) return;

    ops.sort((a, b) => a.timestamp.localeCompare(b.timestamp));

    const serverSurveys = await syncOperations(ops);
    await applyServerSurveys(serverSurveys);

    for (const op of ops) {
      await clearQueuedOperation(op.opId);
    }
  } catch (err) {
    console.error("Sync failed:", err);
  } finally {
    syncing = false;
  }
}
```

## `frontend/src/hooks.ts`
```ts
import { useEffect, useState } from "react";
import { syncPendingOperations } from "./sync";

export function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const onOnline = () => {
      setIsOnline(true);
      syncPendingOperations();
    };
    const onOffline = () => setIsOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return isOnline;
}
```

