    e.preventDefault();

    const now = new Date().toISOString();
    const survey: Survey = {
      id: uuid(),
      ...form,
      createdAt: now,
      updatedAt: now,
      deleted: false
    };

    await saveSurvey(survey);

    const op: SyncOperation = {
      opId: uuid(),
      type: "upsert",
      surveyId: survey.id,
      payload: survey,
      timestamp: now
    };

    await enqueueOperation(op);
    await loadLocal();
    await syncPendingOperations();

    setForm(emptyForm);
  }

