## `backend/server.js`

This uses in-memory storage for simplicity. You can replace it with PostgreSQL later.

```js
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id: string,
 *   title: string,
 *   location: string,
 *   notes: string,
 *   updatedAt: string
 * }
 */

// Health check
app.get("/health", (req, res) => {
  res.json({ ok: true });
});

// Get all surveys
app.get("/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

// Bulk sync endpoint
app.post("/sync", (req, res) => {
  const { changes } = req.body;

  if (!Array.isArray(changes)) {
    return res.status(400).json({ error: "changes must be an array" });
  }

  const results = [];

  for (const incoming of changes) {
    const existing = surveys.get(incoming.id);

    if (!existing) {
      surveys.set(incoming.id, incoming);
      results.push({
        id: incoming.id,
        status: "synced",
        serverRecord: incoming
      });
      continue;
    }

    // Simple last-write-wins conflict strategy
    const incomingTime = new Date(incoming.updatedAt).getTime();
    const existingTime = new Date(existing.updatedAt).getTime();

    if (incomingTime >= existingTime) {
      surveys.set(incoming.id, incoming);
      results.push({
        id: incoming.id,
        status: "synced",
        serverRecord: incoming
      });
    } else {
      results.push({
        id: incoming.id,
        status: "conflict",
        serverRecord: existing
      });
    }
  }

  res.json({
    success: true,
    results,
    serverTime: new Date().toISOString()
  });
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Backend listening on http://localhost:${PORT}`);
});
```

