## `frontend/src/sync.ts`

This is the core offline sync engine.

```ts
import { db } from "./db";
import { syncSurveys } from "./api";
import { Survey } from "./types";

export async function pushPendingSurveys() {
  const pending = await db.surveys
    .where("syncStatus")
    .anyOf("pending", "failed", "conflict")
    .toArray();

  if (pending.length === 0) return { pushed: 0 };

  const response = await syncSurveys(
    pending.map((s) => ({
      ...s,
      syncStatus: "pending"
    }))
  );

  for (const result of response.results) {
    const local = await db.surveys.get(result.id);
    if (!local) continue;

    if (result.status === "synced") {
      await db.surveys.put({
        ...local,
        ...result.serverRecord,
        syncStatus: "synced"
      });
    } else if (result.status === "conflict") {
      await db.surveys.put({
        ...result.serverRecord,
        syncStatus: "conflict"
      });
    }
  }

  return { pushed: pending.length };
}

export async function syncIfOnline() {
  if (!navigator.onLine) {
    return { pushed: 0, skipped: true };
  }

  try {
    return await pushPendingSurveys();
  } catch (err) {
    const pending = await db.surveys
      .where("syncStatus")
      .anyOf("pending", "failed")
      .toArray();

    for (const survey of pending) {
      await db.surveys.put({
        ...survey,
        syncStatus: "failed"
      });
    }

    throw err;
  }
}
```

