## `frontend/src/App.tsx`

```tsx
import { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import SurveyForm from "./components/SurveyForm";
import SurveyList from "./components/SurveyList";
import { db } from "./db";
import { Survey } from "./types";
import { syncIfOnline } from "./sync";

export default function App() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [syncMessage, setSyncMessage] = useState("");

  async function loadSurveys() {
    const all = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(all);
  }

  useEffect(() => {
    loadSurveys();

    const onOnline = async () => {
      setIsOnline(true);
      setSyncMessage("Back online. Syncing...");
      try {
        await syncIfOnline();
        await loadSurveys();
        setSyncMessage("Sync complete.");
      } catch {
        setSyncMessage("Sync failed.");
      }
    };

    const onOffline = () => {
      setIsOnline(false);
      setSyncMessage("Offline mode.");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSave(data: {
    title: string;
    location: string;
    notes: string;
  }) {
    const survey: Survey = {
      id: uuidv4(),
      title: data.title,
      location: data.location,
      notes: data.notes,
      updatedAt: new Date().toISOString(),
      syncStatus: "pending"
    };

    await db.surveys.put(survey);
    await loadSurveys();

    if (navigator.onLine) {
      try {
        await syncIfOnline();
        await loadSurveys();
        setSyncMessage("Saved and synced.");
      } catch {
        setSyncMessage("Saved offline. Sync failed.");
      }
    } else {
      setSyncMessage("Saved offline.");
    }
  }

  async function handleManualSync() {
    setSyncMessage("Manual sync started...");
    try {
      await syncIfOnline();
      await loadSurveys();
      setSyncMessage("Manual sync complete.");
    } catch {
      setSyncMessage("Manual sync failed.");
    }
  }

  return (
    <div style={{ maxWidth: 700, margin: "0 auto", padding: 20 }}>
      <h1>Field Survey App</h1>
      <p>
        Network:{" "}
        <strong style={{ color: isOnline ? "green" : "red" }}>
          {isOnline ? "Online" : "Offline"}
        </strong>
      </p>
      <p>{syncMessage}</p>

      <button onClick={handleManualSync} disabled={!isOnline}>
        Sync Now
      </button>

      <SurveyForm onSave={handleSave} />
      <SurveyList surveys={surveys} />
    </div>
  );
}
```

