## client/src/db.js

This handles IndexedDB storage.

```javascript
import { openDB } from 'idb';

const DB_NAME = 'survey-offline-db';
const DB_VERSION = 1;
const SURVEY_STORE = 'surveys';
const META_STORE = 'meta';

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains(SURVEY_STORE)) {
      const store = db.createObjectStore(SURVEY_STORE, { keyPath: 'id' });
      store.createIndex('by_synced', 'synced');
      store.createIndex('by_updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains(META_STORE)) {
      db.createObjectStore(META_STORE, { keyPath: 'key' });
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll(SURVEY_STORE);
}

export async function getSurvey(id) {
  const db = await dbPromise;
  return db.get(SURVEY_STORE, id);
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  await db.put(SURVEY_STORE, survey);
  return survey;
}

export async function getUnsyncedSurveys() {
  const db = await dbPromise;
  return db.getAllFromIndex(SURVEY_STORE, 'by_synced', false);
}

export async function markSurveySynced(id, serverUpdatedAt = null) {
  const db = await dbPromise;
  const survey = await db.get(SURVEY_STORE, id);
  if (!survey) return;

  survey.synced = true;
  if (serverUpdatedAt) {
    survey.serverUpdatedAt = serverUpdatedAt;
  }
  await db.put(SURVEY_STORE, survey);
}

export async function bulkUpsertSurveys(surveys) {
  const db = await dbPromise;
  const tx = db.transaction(SURVEY_STORE, 'readwrite');
  for (const survey of surveys) {
    await tx.store.put(survey);
  }
  await tx.done;
}

export async function setMeta(key, value) {
  const db = await dbPromise;
  await db.put(META_STORE, { key, value });
}

export async function getMeta(key) {
  const db = await dbPromise;
  const result = await db.get(META_STORE, key);
  return result?.value;
}
