## client/src/sync.js

This is the offline sync engine.

```javascript
import {
  getUnsyncedSurveys,
  markSurveySynced,
  bulkUpsertSurveys
} from './db';
import { pushSurveys, fetchAllSurveys } from './api';

let syncing = false;

export async function syncNow() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const unsynced = await getUnsyncedSurveys();

    if (unsynced.length > 0) {
      const result = await pushSurveys(unsynced);

      for (const syncedRecord of result.synced) {
        await markSurveySynced(syncedRecord.id, syncedRecord.serverUpdatedAt);
      }
    }

    const serverData = await fetchAllSurveys();

    const normalized = serverData.surveys.map((s) => ({
      ...s,
      synced: true
    }));

    await bulkUpsertSurveys(normalized);
  } catch (err) {
    console.error('Sync failed:', err);
  } finally {
    syncing = false;
  }
}

export function setupAutoSync() {
  window.addEventListener('online', () => {
    syncNow();
  });
}
```

