## client/src/App.jsx

```javascript
import React, { useEffect, useState } from 'react';
import SurveyForm from './components/SurveyForm';
import SurveyList from './components/SurveyList';
import { getAllSurveys, saveSurvey } from './db';
import { setupAutoSync, syncNow } from './sync';

function generateId() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  async function loadSurveys() {
    const all = await getAllSurveys();
    all.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
    setSurveys(all);
  }

  async function handleSave(form) {
    const now = new Date().toISOString();

    const survey = {
      id: generateId(),
      title: form.title,
      observer: form.observer,
      notes: form.notes,
      latitude: form.latitude ? Number(form.latitude) : null,
      longitude: form.longitude ? Number(form.longitude) : null,
      createdAt: now,
      updatedAt: now,
      synced: false
    };

    await saveSurvey(survey);
    await loadSurveys();

    if (navigator.onLine) {
      await syncNow();
      await loadSurveys();
    }
  }

  useEffect(() => {
    loadSurveys();
    setupAutoSync();

    function onOnline() {
      setIsOnline(true);
      syncNow().then(loadSurveys);
    }

    function onOffline() {
      setIsOnline(false);
    }

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    if (navigator.onLine) {
      syncNow().then(loadSurveys);
    }

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  return (
    <div style={{ padding: 20, fontFamily: 'sans-serif' }}>
      <h1>Offline Field Surveying App</h1>
      <p>
        Network status: <strong>{isOnline ? 'Online' : 'Offline'}</strong>
      </p>
      <button onClick={() => syncNow().then(loadSurveys)} disabled={!isOnline}>
        Sync Now
      </button>
      <SurveyForm onSave={handleSave} />
      <SurveyList surveys={surveys} />
    </div>
  );
}
