## server/index.js

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id,
 *   title,
 *   observer,
 *   notes,
 *   latitude,
 *   longitude,
 *   createdAt,
 *   updatedAt
 * }
 */

app.get('/surveys', (req, res) => {
  const all = Array.from(surveys.values());
  all.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json({ surveys: all });
});

app.post('/sync', (req, res) => {
  const incoming = req.body.surveys || [];
  const synced = [];
  const conflicts = [];

  for (const clientSurvey of incoming) {
    const existing = surveys.get(clientSurvey.id);

    if (!existing) {
      const serverRecord = {
        ...clientSurvey,
        serverUpdatedAt: new Date().toISOString()
      };
      delete serverRecord.synced;
      surveys.set(clientSurvey.id, serverRecord);

      synced.push({
        id: clientSurvey.id,
        serverUpdatedAt: serverRecord.serverUpdatedAt
      });
      continue;
    }

    const clientUpdated = new Date(clientSurvey.updatedAt).getTime();
    const serverUpdated = new Date(existing.updatedAt).getTime();

    if (clientUpdated >= serverUpdated) {
      const updatedRecord = {
        ...existing,
        ...clientSurvey,
        serverUpdatedAt: new Date().toISOString()
      };
      delete updatedRecord.synced;
      surveys.set(clientSurvey.id, updatedRecord);

      synced.push({
        id: clientSurvey.id,
        serverUpdatedAt: updatedRecord.serverUpdatedAt
      });
    } else {
      conflicts.push({
        id: clientSurvey.id,
        serverRecord: existing
      });
    }
  }

  res.json({
    synced,
    conflicts
  });
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

