# 5. Sync engine

This is the core offline-first behavior.

## `src/sync.js`

```javascript
import { db } from "./db";
import { pushSurvey, updateSurvey, deleteSurvey, fetchSurveys } from "./api";

let syncing = false;

export async function enqueueSync(entityId, operation) {
  await db.syncQueue.add({
    entityId,
    operation,
    createdAt: new Date().toISOString()
  });
}

export async function syncPending() {
  if (syncing || !navigator.onLine) return;

  syncing = true;

  try {
    const queue = await db.syncQueue.orderBy("queueId").toArray();

    for (const item of queue) {
      const survey = await db.surveys.get(item.entityId);

      try {
        if (item.operation === "create") {
          if (survey && !survey.deleted) {
            await pushSurvey(survey);
            await db.surveys.update(item.entityId, { synced: true });
          }
        } else if (item.operation === "update") {
          if (survey && !survey.deleted) {
            await updateSurvey(survey);
            await db.surveys.update(item.entityId, { synced: true });
          }
        } else if (item.operation === "delete") {
          await deleteSurvey(item.entityId);
          await db.surveys.delete(item.entityId);
        }

        await db.syncQueue.delete(item.queueId);
      } catch (err) {
        console.error("Sync item failed:", item, err);
        break;
      }
    }

    // Optional pull latest server data after push
    const remoteSurveys = await fetchSurveys();

    for (const remote of remoteSurveys) {
      const local = await db.surveys.get(remote.id);

      if (!local || new Date(remote.updatedAt) > new Date(local.updatedAt)) {
        await db.surveys.put({
          ...remote,
          synced: true
        });
      }
    }
  } finally {
    syncing = false;
  }
}
```

