import { useEffect, useState } from "react";
import { db } from "../db";
import { enqueueSync, syncPending } from "../sync";

export default function SurveyList() {
  const [surveys, setSurveys] = useState([]);

  useEffect(() => {
    const load = async () => {
      const items = await db.surveys
        .filter((s) => !s.deleted)
        .reverse()
        .sortBy("createdAt");
      setSurveys(items.reverse());
    };

    load();

    const interval = setInterval(load, 1000);
    return () => clearInterval(interval);
  }, []);

  async function handleDelete(id) {
    const survey = await db.surveys.get(id);
    if (!survey) return;

    await db.surveys.update(id, {
      deleted: true,
      synced: false,
      updatedAt: new Date().toISOString()
    });

    await enqueueSync(id, "delete");
    await syncPending();
  }

  return (
    <div className="card">
      <h2>Survey Records</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet.</p>
      ) : (
        <ul className="survey-list">
          {surveys.map((survey) => (
            <li key={survey.id} className="survey-item">
              <div>
                <strong>{survey.siteName}</strong>
                <div>Observer: {survey.observer}</div>
                <div>Notes: {survey.notes || "—"}</div>
                <div>
                  Location: {survey.latitude ?? "—"}, {survey.longitude ?? "—"}
                </div>
                <div>Updated: {new Date(survey.updatedAt).toLocaleString()}</div>
              </div>
              <div className="status-actions">
                <span className={survey.synced ? "synced" : "pending"}>
                  {survey.synced ? "Synced" : "Pending"}
                </span>
                <button onClick={() => handleDelete(survey.id)}>Delete</button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
