## `server/index.js`

```js
const express = require('express');
const cors = require('cors');
const db = require('./db');

const app = express();
const PORT = 4000;

app.use(cors());
app.use(express.json());

app.get('/surveys', (req, res) => {
  db.all(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`,
    [],
    (err, rows) => {
      if (err) return res.status(500).json({ error: err.message });
      res.json(rows);
    }
  );
});

app.get('/surveys/:id', (req, res) => {
  db.get(
    `SELECT * FROM surveys WHERE id = ?`,
    [req.params.id],
    (err, row) => {
      if (err) return res.status(500).json({ error: err.message });
      if (!row || row.deleted) return res.status(404).json({ error: 'Not found' });
      res.json(row);
    }
  );
});

app.post('/surveys', (req, res) => {
  const { id, title, location, notes, status, updatedAt } = req.body;

  db.run(
    `INSERT INTO surveys (id, title, location, notes, status, updatedAt, deleted)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [id, title, location, notes, status || 'draft', updatedAt],
    function (err) {
      if (err) return res.status(500).json({ error: err.message });
      res.status(201).json({ success: true });
    }
  );
});

app.put('/surveys/:id', (req, res) => {
  const { title, location, notes, status, updatedAt } = req.body;
  const id = req.params.id;

  db.get(`SELECT * FROM surveys WHERE id = ?`, [id], (err, existing) => {
    if (err) return res.status(500).json({ error: err.message });
    if (!existing) return res.status(404).json({ error: 'Not found' });

    // last-write-wins
    if (updatedAt < existing.updatedAt) {
      return res.status(409).json({
        error: 'Conflict',
        serverRecord: existing
      });
    }

    db.run(
      `UPDATE surveys
       SET title = ?, location = ?, notes = ?, status = ?, updatedAt = ?, deleted = 0
       WHERE id = ?`,
      [title, location, notes, status, updatedAt, id],
      function (updateErr) {
        if (updateErr) return res.status(500).json({ error: updateErr.message });
        res.json({ success: true });
      }
    );
  });
});

app.delete('/surveys/:id', (req, res) => {
  const id = req.params.id;
  const updatedAt = Date.now();

  db.run(
    `UPDATE surveys SET deleted = 1, updatedAt = ? WHERE id = ?`,
    [updatedAt, id],
    function (err) {
      if (err) return res.status(500).json({ error: err.message });
      res.json({ success: true });
    }
  );
});

app.post('/sync', (req, res) => {
  const { operations } = req.body;
  const results = [];

  if (!Array.isArray(operations)) {
    return res.status(400).json({ error: 'operations must be an array' });
  }

  let remaining = operations.length;
  if (remaining === 0) return res.json({ results: [] });

  const finish = () => {
    remaining -= 1;
    if (remaining === 0) {
      res.json({ results });
    }
  };

  operations.forEach((op) => {
    const { type, record } = op;

    if (type === 'create') {
      db.get(`SELECT * FROM surveys WHERE id = ?`, [record.id], (err, existing) => {
        if (err) {
          results.push({ id: record.id, success: false, error: err.message });
          return finish();
        }

        if (existing) {
          results.push({ id: record.id, success: true, skipped: true });
          return finish();
        }

        db.run(
          `INSERT INTO surveys (id, title, location, notes, status, updatedAt, deleted)
           VALUES (?, ?, ?, ?, ?, ?, 0)`,
          [
            record.id,
            record.title,
            record.location,
            record.notes,
            record.status || 'draft',
            record.updatedAt
          ],
          (insertErr) => {
            if (insertErr) {
              results.push({ id: record.id, success: false, error: insertErr.message });
            } else {
              results.push({ id: record.id, success: true });
            }
            finish();
          }
        );
      });
    } else if (type === 'update') {
      db.get(`SELECT * FROM surveys WHERE id = ?`, [record.id], (err, existing) => {
        if (err) {
          results.push({ id: record.id, success: false, error: err.message });
          return finish();
        }

        if (!existing) {
          db.run(
            `INSERT INTO surveys (id, title, location, notes, status, updatedAt, deleted)
             VALUES (?, ?, ?, ?, ?, ?, 0)`,
            [
              record.id,
              record.title,
              record.location,
              record.notes,
              record.status || 'draft',
              record.updatedAt
            ],
            (insertErr) => {
              if (insertErr) {
                results.push({ id: record.id, success: false, error: insertErr.message });
              } else {
                results.push({ id: record.id, success: true, createdOnServer: true });
              }
              finish();
            }
          );
          return;
        }

        if (record.updatedAt < existing.updatedAt) {
          results.push({
            id: record.id,
            success: false,
            conflict: true,
            serverRecord: existing
          });
          return finish();
        }

        db.run(
          `UPDATE surveys
           SET title = ?, location = ?, notes = ?, status = ?, updatedAt = ?, deleted = 0
           WHERE id = ?`,
          [
            record.title,
            record.location,
            record.notes,
            record.status,
            record.updatedAt,
            record.id
          ],
          (updateErr) => {
            if (updateErr) {
              results.push({ id: record.id, success: false, error: updateErr.message });
            } else {
              results.push({ id: record.id, success: true });
            }
            finish();
          }
        );
      });
    } else if (type === 'delete') {
      db.get(`SELECT * FROM surveys WHERE id = ?`, [record.id], (err, existing) => {
        if (err) {
          results.push({ id: record.id, success: false, error: err.message });
          return finish();
        }

        if (!existing) {
          results.push({ id: record.id, success: true, skipped: true });
          return finish();
        }

        db.run(
          `UPDATE surveys SET deleted = 1, updatedAt = ? WHERE id = ?`,
          [record.updatedAt || Date.now(), record.id],
          (deleteErr) => {
            if (deleteErr) {
              results.push({ id: record.id, success: false, error: deleteErr.message });
            } else {
              results.push({ id: record.id, success: true });
            }
            finish();
          }
        );
      });
    } else {
      results.push({ id: record?.id, success: false, error: 'Unknown operation type' });
      finish();
    }
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

