## `client/src/db.js`

```js
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
      surveyStore.createIndex('updatedAt', 'updatedAt');
    }

    if (!db.objectStoreNames.contains('syncQueue')) {
      const queueStore = db.createObjectStore('syncQueue', {
        keyPath: 'queueId',
        autoIncrement: true
      });
      queueStore.createIndex('synced', 'synced');
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  const all = await db.getAll('surveys');
  return all.filter((s) => !s.deleted).sort((a, b) => b.updatedAt - a.updatedAt);
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function deleteSurveyLocal(id) {
  const db = await dbPromise;
  const existing = await db.get('surveys', id);
  if (!existing) return;
  await db.put('surveys', {
    ...existing,
    deleted: true,
    updatedAt: Date.now()
  });
}

export async function enqueueOperation(operation) {
  const db = await dbPromise;
  await db.add('syncQueue', {
    ...operation,
    synced: false,
    createdAt: Date.now()
  });
}

export async function getPendingOperations() {
  const db = await dbPromise;
  const all = await db.getAll('syncQueue');
  return all.filter((item) => !item.synced).sort((a, b) => a.createdAt - b.createdAt);
}

export async function markOperationSynced(queueId) {
  const db = await dbPromise;
  const op = await db.get('syncQueue', queueId);
  if (!op) return;
  await db.put('syncQueue', { ...op, synced: true });
}

export async function replaceSurvey(record) {
  const db = await dbPromise;
  await db.put('surveys', record);
}
