## `client/src/sync.js`

```js
import {
  getPendingOperations,
  markOperationSynced,
  replaceSurvey,
  saveSurvey
} from './db';
import { syncOperations, fetchSurveys } from './api';

let syncing = false;

export async function runSync() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const pending = await getPendingOperations();

    if (pending.length > 0) {
      const payload = pending.map((item) => ({
        type: item.type,
        record: item.record
      }));

      const result = await syncOperations(payload);

      for (let i = 0; i < result.results.length; i++) {
        const syncResult = result.results[i];
        const queueItem = pending[i];

        if (syncResult.success) {
          await markOperationSynced(queueItem.queueId);
        } else if (syncResult.conflict && syncResult.serverRecord) {
          await replaceSurvey(syncResult.serverRecord);
        }
      }
    }

    // Refresh local cache from server after sync
    const serverSurveys = await fetchSurveys();
    for (const survey of serverSurveys) {
      await saveSurvey(survey);
    }
  } catch (err) {
    console.error('Sync error:', err);
  } finally {
    syncing = false;
  }
}
```

