## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import {
  getAllSurveys,
  saveSurvey,
  enqueueOperation,
  deleteSurveyLocal
} from './db';
import { runSync } from './sync';
import './styles.css';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [status, setStatus] = useState('draft');
  const [editingId, setEditingId] = useState(null);
  const [online, setOnline] = useState(navigator.onLine);

  async function loadSurveys() {
    const data = await getAllSurveys();
    setSurveys(data);
  }

  useEffect(() => {
    loadSurveys();

    const handleOnline = async () => {
      setOnline(true);
      await runSync();
      await loadSurveys();
    };

    const handleOffline = () => setOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    runSync().then(loadSurveys);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const now = Date.now();

    if (editingId) {
      const updated = {
        id: editingId,
        title,
        location,
        notes,
        status,
        updatedAt: now,
        deleted: false
      };

      await saveSurvey(updated);
      await enqueueOperation({ type: 'update', record: updated });
    } else {
      const newSurvey = {
        id: uuidv4(),
        title,
        location,
        notes,
        status,
        updatedAt: now,
        deleted: false
      };

      await saveSurvey(newSurvey);
      await enqueueOperation({ type: 'create', record: newSurvey });
    }

    setTitle('');
    setLocation('');
    setNotes('');
    setStatus('draft');
    setEditingId(null);

    await loadSurveys();
    if (navigator.onLine) {
      await runSync();
      await loadSurveys();
    }
  }

  function startEdit(survey) {
    setEditingId(survey.id);
    setTitle(survey.title);
    setLocation(survey.location || '');
    setNotes(survey.notes || '');
    setStatus(survey.status || 'draft');
  }

  async function handleDelete(id) {
    const record = {
      id,
      updatedAt: Date.now()
    };

    await deleteSurveyLocal(id);
    await enqueueOperation({ type: 'delete', record });
    await loadSurveys();

    if (navigator.onLine) {
      await runSync();
      await loadSurveys();
    }
  }

  return (
    <div className="container">
      <header>
        <h1>Field Survey App</h1>
        <div className={`status ${online ? 'online' : 'offline'}`}>
          {online ? 'Online' : 'Offline'}
        </div>
      </header>

      <form onSubmit={handleSubmit} className="survey-form">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Survey title"
          required
        />
        <input
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          placeholder="Location"
        />
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Notes"
        />
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="draft">Draft</option>
          <option value="completed">Completed</option>
          <option value="submitted">Submitted</option>
        </select>

        <button type="submit">{editingId ? 'Update Survey' : 'Add Survey'}</button>
      </form>

      <section className="survey-list">
        {surveys.length === 0 ? (
          <p>No surveys yet.</p>
        ) : (
          surveys.map((survey) => (
            <div key={survey.id} className="survey-card">
              <h3>{survey.title}</h3>
              <p><strong>Location:</strong> {survey.location || '-'}</p>
              <p><strong>Notes:</strong> {survey.notes || '-'}</p>
              <p><strong>Status:</strong> {survey.status}</p>
              <small>Updated: {new Date(survey.updatedAt).toLocaleString()}</small>
              <div className="actions">
                <button onClick={() => startEdit(survey)}>Edit</button>
                <button onClick={() => handleDelete(survey.id)}>Delete</button>
              </div>
            </div>
          ))
        )}
      </section>
    </div>
  );
}
