# 3. Frontend code

## `App.js`

```javascript
import React, { useEffect, useState } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  Button,
  FlatList,
  StyleSheet,
  Alert,
} from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import * as SQLite from 'expo-sqlite';
import { v4 as uuidv4 } from 'uuid';

const db = SQLite.openDatabase('survey.db');
const API_URL = 'http://YOUR_SERVER_IP:3000';

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected;
      setIsOnline(online);
      if (online) {
        syncPendingChanges();
      }
    });

    return () => unsubscribe();
  }, []);

  const initDb = () => {
    db.transaction((tx) => {
      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS surveys (
          local_id TEXT PRIMARY KEY NOT NULL,
          server_id TEXT,
          title TEXT,
          location TEXT,
          notes TEXT,
          updated_at TEXT,
          sync_status TEXT
        );
      `);

      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS sync_queue (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          entity_type TEXT NOT NULL,
          entity_local_id TEXT NOT NULL,
          operation TEXT NOT NULL,
          payload TEXT NOT NULL,
          created_at TEXT NOT NULL,
          status TEXT NOT NULL
        );
      `);
    });
  };

  const loadSurveys = () => {
    db.transaction((tx) => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY updated_at DESC;',
        [],
        (_, result) => {
          setSurveys(result.rows._array);
        }
      );
    });
  };

  const addSurvey = () => {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    const localId = uuidv4();
    const now = new Date().toISOString();

    const survey = {
      local_id: localId,
      server_id: null,
      title,
      location,
      notes,
      updated_at: now,
      sync_status: 'pending',
    };

    db.transaction((tx) => {
      tx.executeSql(
        `INSERT INTO surveys (local_id, server_id, title, location, notes, updated_at, sync_status)
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [
          survey.local_id,
          survey.server_id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updated_at,
          survey.sync_status,
        ]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (entity_type, entity_local_id, operation, payload, created_at, status)
         VALUES (?, ?, ?, ?, ?, ?);`,
        [
          'survey',
          survey.local_id,
          'upsert',
          JSON.stringify(survey),
          now,
          'pending',
        ]
      );
    }, null, () => {
      setTitle('');
      setLocation('');
      setNotes('');
      loadSurveys();
      if (isOnline) syncPendingChanges();
    });
  };

  const syncPendingChanges = async () => {
    if (syncing) return;
    setSyncing(true);

    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM sync_queue WHERE status = 'pending' ORDER BY created_at ASC;`,
        [],
        async (_, result) => {
          const queueItems = result.rows._array;

          if (queueItems.length === 0) {
            setSyncing(false);
            return;
          }

          try {
            const response = await fetch(`${API_URL}/sync`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ changes: queueItems }),
            });

            if (!response.ok) {
              throw new Error('Sync failed');
            }

            const data = await response.json();

            db.transaction((tx2) => {
              data.results.forEach((item) => {
                tx2.executeSql(
                  `UPDATE surveys
                   SET server_id = ?, sync_status = 'synced'
                   WHERE local_id = ?;`,
                  [item.serverId, item.localId]
                );

                tx2.executeSql(
                  `UPDATE sync_queue
                   SET status = 'synced'
                   WHERE id = ?;`,
                  [item.queueId]
                );
              });
            }, null, () => {
              loadSurveys();
              setSyncing(false);
            });
          } catch (err) {
            console.log('Sync error:', err.message);
            setSyncing(false);
          }
        }
      );
    });
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text>Status: {isOnline ? 'Online' : 'Offline'}</Text>
      <Text>Sync: {syncing ? 'Syncing...' : 'Idle'}</Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Survey title"
          value={title}
          onChangeText={setTitle}
        />
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={location}
          onChangeText={setLocation}
        />
        <TextInput
          style={[styles.input, styles.textArea]}
          placeholder="Notes"
          value={notes}
          onChangeText={setNotes}
          multiline
        />
        <Button title="Save Survey" onPress={addSurvey} />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.local_id}
        renderItem={({ item }) => (
          <View style={styles.item}>
            <Text style={styles.itemTitle}>{item.title}</Text>
            <Text>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text style={styles.meta}>
              {item.sync_status} | {item.updated_at}
            </Text>
          </View>
        )}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
    marginTop: 40,
  },
  header: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 8,
  },
  form: {
    marginVertical: 16,
  },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    padding: 10,
    marginBottom: 10,
    borderRadius: 6,
  },
  textArea: {
    minHeight: 80,
  },
  item: {
    padding: 12,
    borderWidth: 1,
    borderColor: '#ddd',
    borderRadius: 6,
    marginBottom: 10,
  },
  itemTitle: {
    fontWeight: 'bold',
    fontSize: 16,
  },
  meta: {
    marginTop: 6,
    color: '#666',
    fontSize: 12,
  },
});
```

