## `server.js`

```javascript
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/sync', (req, res) => {
  const { changes } = req.body;

  if (!Array.isArray(changes)) {
    return res.status(400).json({ error: 'Invalid changes payload' });
  }

  const results = [];

  for (const queueItem of changes) {
    try {
      const payload = JSON.parse(queueItem.payload);

      if (queueItem.entity_type === 'survey' && queueItem.operation === 'upsert') {
        let serverId = payload.server_id;

        if (!serverId) {
          serverId = uuidv4();
        }

        surveys.set(serverId, {
          server_id: serverId,
          local_id: payload.local_id,
          title: payload.title,
          location: payload.location,
          notes: payload.notes,
          updated_at: payload.updated_at,
        });

        results.push({
          queueId: queueItem.id,
          localId: payload.local_id,
          serverId,
          status: 'synced',
        });
      }
    } catch (err) {
      results.push({
        queueId: queueItem.id,
        status: 'failed',
        error: err.message,
      });
    }
  }

  res.json({ results });
});

app.get('/surveys', (req, res) => {
  res.json([...surveys.values()]);
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

