## `mobile/db.js`

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('surveys.db');

export function initDb() {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          title TEXT,
          location TEXT,
          notes TEXT,
          updatedAt INTEGER,
          deleted INTEGER DEFAULT 0
        );
      `);

      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS sync_queue (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          surveyId TEXT NOT NULL,
          operation TEXT NOT NULL,
          payload TEXT NOT NULL,
          createdAt INTEGER NOT NULL
        );
      `);

      tx.executeSql(`
        CREATE TABLE IF NOT EXISTS metadata (
          key TEXT PRIMARY KEY NOT NULL,
          value TEXT
        );
      `);
    }, reject, resolve);
  });
}

export function saveSurveyLocally(survey) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys (id, title, location, notes, updatedAt, deleted)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updatedAt,
          survey.deleted ? 1 : 0
        ]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (surveyId, operation, payload, createdAt)
         VALUES (?, ?, ?, ?)`,
        [
          survey.id,
          survey.deleted ? 'delete' : 'upsert',
          JSON.stringify(survey),
          Date.now()
        ]
      );
    }, reject, resolve);
  });
}

export function getAllSurveys() {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
}

export function getSyncQueue() {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY createdAt ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => reject(err)
      );
    });
  });
}

export function clearSyncQueueItem(id) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => reject(err)
      );
    });
  });
}

export function upsertRemoteSurvey(survey) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys (id, title, location, notes, updatedAt, deleted)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updatedAt,
          survey.deleted ? 1 : 0
        ]
      );
    }, reject, resolve);
  });
}

export function getMetadata(key) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT value FROM metadata WHERE key = ?`,
        [key],
        (_, result) => {
          if (result.rows.length > 0) resolve(result.rows.item(0).value);
          else resolve(null);
        },
        (_, err) => reject(err)
      );
    });
  });
}

export function setMetadata(key, value) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO metadata (key, value) VALUES (?, ?)`,
        [key, value]
      );
    }, reject, resolve);
  });
}
```

