## `mobile/sync.js`

```javascript
import {
  getSyncQueue,
  clearSyncQueueItem,
  upsertRemoteSurvey,
  getMetadata,
  setMetadata
} from './db';
import { pushChanges, pullChanges } from './api';

export async function syncAll() {
  const queue = await getSyncQueue();

  if (queue.length > 0) {
    const changes = queue.map(item => ({
      queueId: item.id,
      surveyId: item.surveyId,
      operation: item.operation,
      payload: JSON.parse(item.payload),
      createdAt: item.createdAt
    }));

    const pushResult = await pushChanges(changes);

    for (const ack of pushResult.acknowledged) {
      await clearSyncQueueItem(ack.queueId);
    }
  }

  const lastSync = await getMetadata('lastSync');
  const pullResult = await pullChanges(lastSync);

  for (const survey of pullResult.changes) {
    await upsertRemoteSurvey(survey);
  }

  await setMetadata('lastSync', String(pullResult.serverTime));
}
```

