    setLocation('');
    setNotes('');
    await loadSurveys();
  }

  async function runSync() {
    try {
      await syncAll();
      await loadSurveys();
    } catch (e) {
      console.log('Sync failed:', e.message);
    }
  }

  useEffect(() => {
    async function setup() {
      await initDb();
      await loadSurveys();
    }
    setup();
  }, []);

  useEffect(() => {
    if (isOnline) {
      runSync();
    }
  }, [isOnline]);

  return (
    <View style={styles.container}>
      <Text style={styles.header}>Field Survey App</Text>
      <Text>Status: {isOnline ? 'Online' : 'Offline'}</Text>

      <TextInput
        style={styles.input}
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
      />
      <TextInput
        style={styles.input}
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
      />
      <TextInput
        style={styles.input}
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
      />

      <Button title="Save Survey" onPress={addSurvey} />
      <View style={{ height: 12 }} />
      <Button title="Sync Now" onPress={runSync} disabled={!isOnline} />

      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.title}>{item.title}</Text>
            <Text>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text style={styles.time}>
              Updated: {new Date(item.updatedAt).toLocaleString()}
            </Text>
          </View>
        )}
      />
    </View>
  );
}

