## `server/index.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/sync/push', (req, res) => {
  const { changes } = req.body;
  const acknowledged = [];

  for (const change of changes) {
    const incoming = change.payload;
    const existing = surveys.get(incoming.id);

    if (!existing || incoming.updatedAt >= existing.updatedAt) {
      surveys.set(incoming.id, {
        ...incoming,
        updatedAt: incoming.updatedAt || Date.now()
      });
    }

    acknowledged.push({ queueId: change.queueId });
  }

  res.json({
    acknowledged,
    serverTime: Date.now()
  });
});

app.get('/sync/pull', (req, res) => {
  const since = Number(req.query.since || 0);

  const changes = Array.from(surveys.values()).filter(
    survey => survey.updatedAt > since
  );

  res.json({
    changes,
    serverTime: Date.now()
  });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

