# 6. Example: Better Queue Deduplication

If you want, replace `saveSurveyLocally()` with this improved version:

```javascript
export function saveSurveyLocally(survey) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT OR REPLACE INTO surveys (id, title, location, notes, updatedAt, deleted)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [
          survey.id,
          survey.title,
          survey.location,
          survey.notes,
          survey.updatedAt,
          survey.deleted ? 1 : 0
        ]
      );

      tx.executeSql(
        `DELETE FROM sync_queue WHERE surveyId = ?`,
        [survey.id]
      );

      tx.executeSql(
        `INSERT INTO sync_queue (surveyId, operation, payload, createdAt)
         VALUES (?, ?, ?, ?)`,
        [
          survey.id,
          survey.deleted ? 'delete' : 'upsert',
          JSON.stringify(survey),
          Date.now()
        ]
      );
    }, reject, resolve);
  });
}
```

