## `client/src/db.js`

Uses IndexedDB for local persistence.

```javascript
import { openDB } from 'idb';

const DB_NAME = 'fieldSurveyDB';
const DB_VERSION = 1;
const SURVEY_STORE = 'surveys';
const SYNC_STORE = 'syncQueue';

export async function initDB() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(SURVEY_STORE)) {
        db.createObjectStore(SURVEY_STORE, { keyPath: 'localId' });
      }

      if (!db.objectStoreNames.contains(SYNC_STORE)) {
        db.createObjectStore(SYNC_STORE, { keyPath: 'localId' });
      }
    }
  });
}

export async function saveSurveyLocally(survey) {
  const db = await initDB();
  await db.put(SURVEY_STORE, survey);
  await db.put(SYNC_STORE, survey);
}

export async function getAllSurveys() {
  const db = await initDB();
  return db.getAll(SURVEY_STORE);
}

export async function getPendingSyncItems() {
  const db = await initDB();
  return db.getAll(SYNC_STORE);
}

export async function removePendingSyncItem(localId) {
  const db = await initDB();
  await db.delete(SYNC_STORE, localId);
}

export async function markSurveySynced(localId, serverId) {
  const db = await initDB();
  const survey = await db.get(SURVEY_STORE, localId);
  if (survey) {
    survey.synced = true;
    survey.serverId = serverId;
    await db.put(SURVEY_STORE, survey);
  }
}
```

