## `client/src/sync.js`

Handles syncing pending records to the server.

```javascript
import {
  getPendingSyncItems,
  removePendingSyncItem,
  markSurveySynced
} from './db';

const API_URL = 'http://localhost:4000/api/surveys';

export async function syncPendingSurveys() {
  if (!navigator.onLine) {
    console.log('Offline, skipping sync');
    return;
  }

  const pendingItems = await getPendingSyncItems();

  for (const item of pendingItems) {
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(item)
      });

      if (!response.ok) {
        throw new Error(`Sync failed for ${item.localId}`);
      }

      const result = await response.json();
      await markSurveySynced(item.localId, result.serverId);
      await removePendingSyncItem(item.localId);

      console.log(`Synced survey ${item.localId}`);
    } catch (error) {
      console.error('Sync error:', error);
    }
  }
}

export function setupOnlineSync() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncPendingSurveys();
  });
}
```

