## `client/src/sync.js`

```js
import { db } from "./db";
import { pushChanges, pullChanges } from "./api";

let syncInProgress = false;

export async function getLastSyncTime() {
  const row = await db.meta.get("lastSyncTime");
  return row?.value || 0;
}

export async function setLastSyncTime(timestamp) {
  await db.meta.put({ key: "lastSyncTime", value: timestamp });
}

export async function enqueueSurveyChange(survey) {
  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(survey);
    await db.outbox.put({
      id: crypto.randomUUID(),
      entityId: survey.id,
      type: "upsert",
      payload: survey,
      createdAt: Date.now(),
      retries: 0
    });
  });
}

export async function syncNow() {
  if (syncInProgress || !navigator.onLine) return;
  syncInProgress = true;

  try {
    const outboxItems = await db.outbox.orderBy("createdAt").toArray();

    if (outboxItems.length > 0) {
      const pushResult = await pushChanges(outboxItems);

      await db.transaction("rw", db.outbox, db.surveys, async () => {
        for (const accepted of pushResult.accepted || []) {
          await db.outbox
            .where("entityId")
            .equals(accepted.id)
            .delete();

          const local = await db.surveys.get(accepted.id);
          if (local) {
            await db.surveys.put({
              ...local,
              version: accepted.version,
              dirty: false,
              lastSyncedAt: Date.now()
            });
          }
        }

        for (const conflict of pushResult.conflicts || []) {
          const local = await db.surveys.get(conflict.local.id);
          if (local) {
            await db.surveys.put({
              ...conflict.server,
              dirty: false,
              lastSyncedAt: Date.now(),
              conflict: true
            });
          }

          await db.outbox
            .where("entityId")
            .equals(conflict.local.id)
            .delete();
        }
      });
    }

    const lastSyncTime = await getLastSyncTime();
    const pullResult = await pullChanges(lastSyncTime);

    await db.transaction("rw", db.surveys, db.meta, async () => {
      for (const survey of pullResult.changes || []) {
        const local = await db.surveys.get(survey.id);

        if (!local || !local.dirty || survey.updatedAt > local.updatedAt) {
          await db.surveys.put({
            ...survey,
            dirty: false,
            lastSyncedAt: Date.now()
          });
        }
      }

      await setLastSyncTime(pullResult.serverTime || Date.now());
    });
  } catch (err) {
    console.error("Sync failed:", err);

    const items = await db.outbox.toArray();
    for (const item of items) {
      await db.outbox.update(item.id, { retries: item.retries + 1 });
    }
  } finally {
    syncInProgress = false;
  }
}

export function startSyncLoop() {
  window.addEventListener("online", syncNow);
  const interval = setInterval(syncNow, 10000);

  return () => {
    window.removeEventListener("online", syncNow);
    clearInterval(interval);
  };
}
