## `server/index.js`

```js
import express from "express";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post("/sync/push", (req, res) => {
  const changes = req.body.changes || [];
  const accepted = [];
  const conflicts = [];

  for (const op of changes) {
    if (op.type !== "upsert") continue;

    const incoming = op.payload;
    const existing = surveys.get(incoming.id);

    if (!existing) {
      const created = {
        ...incoming,
        version: 1,
        updatedAt: Date.now()
      };
      surveys.set(created.id, created);
      accepted.push(created);
      continue;
    }

    if ((incoming.version || 0) < (existing.version || 0)) {
      conflicts.push({
        local: incoming,
        server: existing
      });
      continue;
    }

    const updated = {
      ...existing,
      ...incoming,
      version: (existing.version || 0) + 1,
      updatedAt: Date.now()
    };

    surveys.set(updated.id, updated);
    accepted.push(updated);
  }

  res.json({
    accepted,
    conflicts
  });
});

app.get("/sync/pull", (req, res) => {
  const since = Number(req.query.since || 0);

  const changes = Array.from(surveys.values()).filter(
    (s) => s.updatedAt > since
  );

  res.json({
    changes,
    serverTime: Date.now()
  });
});

app.get("/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3001, () => {
  console.log("Server listening on http://localhost:3001");
});
```

