## `server/index.js`

```js
import express from 'express';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Survey shape:
 * {
 *   id: string,
 *   title: string,
 *   location: string,
 *   notes: string,
 *   updatedAt: string,
 *   clientUpdatedAt: string
 * }
 */

app.get('/health', (req, res) => {
  res.json({ ok: true });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/sync', (req, res) => {
  const { changes } = req.body;

  if (!Array.isArray(changes)) {
    return res.status(400).json({ error: 'changes must be an array' });
  }

  const results = [];

  for (const change of changes) {
    const { type, record } = change;

    if (!record?.id) {
      results.push({
        id: record?.id ?? null,
        status: 'error',
        message: 'Missing record id'
      });
      continue;
    }

    if (type === 'upsert') {
      const existing = surveys.get(record.id);

      if (!existing || new Date(record.clientUpdatedAt) >= new Date(existing.clientUpdatedAt || 0)) {
        const saved = {
          ...existing,
          ...record,
          updatedAt: new Date().toISOString()
        };
        surveys.set(record.id, saved);

        results.push({
          id: record.id,
          status: 'synced',
          serverRecord: saved
        });
      } else {
        results.push({
          id: record.id,
          status: 'conflict',
          serverRecord: existing
        });
      }
    } else if (type === 'delete') {
      surveys.delete(record.id);
      results.push({
        id: record.id,
        status: 'synced'
      });
    } else {
      results.push({
        id: record.id,
        status: 'error',
        message: `Unknown change type: ${type}`
      });
    }
  }

  res.json({ results });
});

const PORT = process.env.PORT || 4000;
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```

