# 5. IndexedDB Layer

## `client/src/db.js`

```js
import { openDB } from 'idb';

const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
      surveyStore.createIndex('by_updatedAt', 'clientUpdatedAt');
    }

    if (!db.objectStoreNames.contains('outbox')) {
      const outboxStore = db.createObjectStore('outbox', {
        keyPath: 'queueId',
        autoIncrement: true
      });
      outboxStore.createIndex('by_status', 'status');
      outboxStore.createIndex('by_createdAt', 'createdAt');
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function saveSurveyLocally(survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function deleteSurveyLocally(id) {
  const db = await dbPromise;
  await db.delete('surveys', id);
}

export async function enqueueChange(change) {
  const db = await dbPromise;
  await db.add('outbox', {
    ...change,
    status: 'pending',
    createdAt: new Date().toISOString()
  });
}

export async function getPendingChanges() {
  const db = await dbPromise;
  return db.getAllFromIndex('outbox', 'by_status', 'pending');
}

export async function markQueueItemSynced(queueId) {
  const db = await dbPromise;
  const item = await db.get('outbox', queueId);
  if (!item) return;
  item.status = 'synced';
  await db.put('outbox', item);
}

export async function markQueueItemError(queueId, error) {
  const db = await dbPromise;
  const item = await db.get('outbox', queueId);
  if (!item) return;
  item.status = 'error';
  item.error = error;
  await db.put('outbox', item);
}

export async function replaceSurvey(serverRecord) {
  const db = await dbPromise;
  await db.put('surveys', {
    ...serverRecord,
    pendingSync: false
  });
}
```

