# 6. Sync Engine

## `client/src/sync.js`

```js
import {
  getPendingChanges,
  markQueueItemSynced,
  markQueueItemError,
  replaceSurvey,
  deleteSurveyLocally
} from './db';

const API_BASE = 'http://localhost:4000';

let syncing = false;

export async function syncPendingChanges() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const pending = await getPendingChanges();
    if (pending.length === 0) return;

    const payload = {
      changes: pending.map((item) => ({
        type: item.type,
        record: item.record
      }))
    };

    const response = await fetch(`${API_BASE}/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      throw new Error(`Sync failed with status ${response.status}`);
    }

    const data = await response.json();

    for (let i = 0; i < pending.length; i++) {
      const queueItem = pending[i];
      const result = data.results[i];

      if (!result) {
        await markQueueItemError(queueItem.queueId, 'Missing sync result');
        continue;
      }

      if (result.status === 'synced') {
        await markQueueItemSynced(queueItem.queueId);

        if (queueItem.type === 'upsert' && result.serverRecord) {
          await replaceSurvey(result.serverRecord);
        }

        if (queueItem.type === 'delete') {
          await deleteSurveyLocally(queueItem.record.id);
        }
      } else if (result.status === 'conflict') {
        await markQueueItemError(queueItem.queueId, 'Conflict detected');
      } else {
        await markQueueItemError(queueItem.queueId, result.message || 'Unknown sync error');
      }
    }
  } catch (err) {
    console.error('Sync error:', err);
  } finally {
    syncing = false;
  }
}

export function setupAutoSync() {
  window.addEventListener('online', () => {
    syncPendingChanges();
  });

  setInterval(() => {
    syncPendingChanges();
  }, 10000);
}
```

