# 9. Main App

## `client/src/App.jsx`

```jsx
import { useEffect, useState } from 'react';
import SurveyForm from './SurveyForm';
import SurveyList from './SurveyList';
import { getAllSurveys } from './db';
import { setupAutoSync, syncPendingChanges } from './sync';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);

  async function loadSurveys() {
    const data = await getAllSurveys();
    data.sort((a, b) => new Date(b.clientUpdatedAt) - new Date(a.clientUpdatedAt));
    setSurveys(data);
  }

  useEffect(() => {
    loadSurveys();
    setupAutoSync();
    syncPendingChanges();

    const onOnline = () => {
      setOnline(true);
      syncPendingChanges().then(loadSurveys);
    };

    const onOffline = () => {
      setOnline(false);
    };

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>
        Connection status:{' '}
        <strong style={{ color: online ? 'green' : 'red' }}>
          {online ? 'Online' : 'Offline'}
        </strong>
      </p>

      <SurveyForm onSaved={loadSurveys} />
      <button onClick={() => syncPendingChanges().then(loadSurveys)}>
        Sync Now
      </button>

      <hr />
      <SurveyList surveys={surveys} />
    </div>
  );
}
