export async function pushSurveyToServer(survey) {
  const response = await fetch('http://localhost:4000/api/surveys', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(survey)
  });

  if (!response.ok) {
    throw new Error(`Push failed: ${response.status}`);
  }

  return response.json();
}

export async function fetchServerUpdates(lastSyncAt) {
  const url = new URL('http://localhost:4000/api/surveys');
  if (lastSyncAt) {
    url.searchParams.set('since', lastSyncAt);
  }

  const response = await fetch(url.toString());
  if (!response.ok) {
    throw new Error(`Pull failed: ${response.status}`);
  }

  return response.json();
}
