## `src/sync.js`

```javascript
import {
  getPendingOperations,
  markOperationDone,
  markOperationFailed,
  saveSurveyLocally,
  setMeta,
  getMeta
} from './db';
import { pushSurveyToServer, fetchServerUpdates } from './api';

let syncing = false;

export async function syncAll() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const pending = await getPendingOperations();

    for (const op of pending) {
      try {
        if (op.type === 'UPSERT_SURVEY') {
          const serverSurvey = await pushSurveyToServer(op.payload);
          await saveSurveyLocally({
            ...serverSurvey,
            synced: true
          });
        }
        await markOperationDone(op.opId);
      } catch (err) {
        await markOperationFailed(op.opId, err.message);
      }
    }

    const lastSyncAt = await getMeta('lastSyncAt');
    const updates = await fetchServerUpdates(lastSyncAt);

    for (const survey of updates.surveys) {
      await saveSurveyLocally({
        ...survey,
        synced: true
      });
    }

    await setMeta('lastSyncAt', updates.serverTime);
  } finally {
    syncing = false;
  }
}
```

