## `src/App.jsx`

```javascript
import React, { useEffect, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import {
  getAllSurveys,
  saveSurveyLocally,
  addOutboxOperation
} from './db';
import { syncAll } from './sync';

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [form, setForm] = useState({
    title: '',
    location: '',
    notes: ''
  });
  const [online, setOnline] = useState(navigator.onLine);

  async function loadSurveys() {
    const data = await getAllSurveys();
    data.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
    setSurveys(data);
  }

  useEffect(() => {
    loadSurveys();

    const onOnline = async () => {
      setOnline(true);
      await syncAll();
      await loadSurveys();
    };

    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    if (navigator.onLine) {
      syncAll().then(loadSurveys);
    }

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const survey = {
      id: uuidv4(),
      title: form.title,
      location: form.location,
      notes: form.notes,
      updatedAt: now,
      createdAt: now,
      synced: false
    };

    await saveSurveyLocally(survey);

    await addOutboxOperation({
      type: 'UPSERT_SURVEY',
      payload: survey,
      status: 'pending',
      createdAt: now,
      retryCount: 0
    });

    setForm({ title: '', location: '', notes: '' });
    await loadSurveys();

    if (navigator.onLine) {
      await syncAll();
      await loadSurveys();
    }
  }

  return (
    <div style={{ padding: 20, fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? 'Online' : 'Offline'}</p>

      <form onSubmit={handleSubmit} style={{ marginBottom: 24 }}>
        <div>
          <input
            placeholder="Survey title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
        </div>
        <div>
          <input
            placeholder="Location"
            value={form.location}
            onChange={(e) => setForm({ ...form, location: e.target.value })}
            required
          />
        </div>
        <div>
          <textarea
            placeholder="Notes"
            value={form.notes}
            onChange={(e) => setForm({ ...form, notes: e.target.value })}
          />
        </div>
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((survey) => (
          <li key={survey.id} style={{ marginBottom: 12 }}>
            <strong>{survey.title}</strong> - {survey.location}
            <br />
            {survey.notes}
            <br />
            <small>
              Updated: {survey.updatedAt} | {survey.synced ? 'Synced' : 'Pending Sync'}
            </small>
          </li>
        ))}
      </ul>
    </div>
  );
}
