## `server/index.js`

This is a simple in-memory backend. Replace with PostgreSQL or MongoDB later.

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

app.post('/api/surveys', (req, res) => {
  const incoming = req.body;
  const existing = surveys.get(incoming.id);

  if (!existing || new Date(incoming.updatedAt) >= new Date(existing.updatedAt)) {
    surveys.set(incoming.id, {
      ...incoming,
      synced: true,
      serverUpdatedAt: new Date().toISOString()
    });
  }

  return res.json(surveys.get(incoming.id));
});

app.get('/api/surveys', (req, res) => {
  const since = req.query.since;
  let results = Array.from(surveys.values());

  if (since) {
    results = results.filter(
      (s) =>
        new Date(s.serverUpdatedAt || s.updatedAt) > new Date(since)
    );
  }

  res.json({
    surveys: results,
    serverTime: new Date().toISOString()
  });
});

app.listen(4000, () => {
  console.log('Server listening on http://localhost:4000');
});
```

