# 2. Frontend Implementation

## `src/db.js`
A lightweight IndexedDB wrapper.

```javascript
const DB_NAME = 'field-survey-db';
const DB_VERSION = 1;
const SURVEYS_STORE = 'surveys';
const QUEUE_STORE = 'syncQueue';

export function openDb() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains(SURVEYS_STORE)) {
        const surveyStore = db.createObjectStore(SURVEYS_STORE, { keyPath: 'id' });
        surveyStore.createIndex('updatedAt', 'updatedAt');
      }

      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        const queueStore = db.createObjectStore(QUEUE_STORE, { keyPath: 'queueId', autoIncrement: true });
        queueStore.createIndex('status', 'status');
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function putSurvey(survey) {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(SURVEYS_STORE, 'readwrite');
    tx.objectStore(SURVEYS_STORE).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function getAllSurveys() {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(SURVEYS_STORE, 'readonly');
    const req = tx.objectStore(SURVEYS_STORE).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function addToQueue(item) {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readwrite');
    tx.objectStore(QUEUE_STORE).add(item);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function getQueuedItems() {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readonly');
    const req = tx.objectStore(QUEUE_STORE).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function removeQueueItem(queueId) {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readwrite');
    tx.objectStore(QUEUE_STORE).delete(queueId);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}
```

