## `src/sync.js`

```javascript
import { getQueuedItems, removeQueueItem, putSurvey } from './db';
import { syncSurveyToServer } from './api';

let syncing = false;

export async function syncPendingData() {
  if (syncing || !navigator.onLine) return;
  syncing = true;

  try {
    const queuedItems = await getQueuedItems();

    for (const item of queuedItems) {
      try {
        const serverSurvey = await syncSurveyToServer(item.payload);
        await putSurvey({ ...serverSurvey, synced: true });
        await removeQueueItem(item.queueId);
      } catch (err) {
        console.error('Sync failed for item', item, err);
      }
    }
  } finally {
    syncing = false;
  }
}

export function initSyncListeners() {
  window.addEventListener('online', () => {
    console.log('Back online. Syncing...');
    syncPendingData();
  });
}
```

