import React, { useEffect, useState } from 'react';
import { addToQueue, getAllSurveys, putSurvey } from './db';
import { initSyncListeners, syncPendingData } from './sync';

function App() {
  const [surveys, setSurveys] = useState([]);
  const [form, setForm] = useState({
    id: '',
    location: '',
    observer: '',
    notes: '',
  });

  async function loadSurveys() {
    const all = await getAllSurveys();
    setSurveys(all.sort((a, b) => b.updatedAt - a.updatedAt));
  }

  useEffect(() => {
    loadSurveys();
    initSyncListeners();
    syncPendingData();
  }, []);

  function updateField(e) {
    setForm({ ...form, [e.target.name]: e.target.value });
  }

  async function saveSurvey(e) {
    e.preventDefault();

    const survey = {
      ...form,
      id: form.id || crypto.randomUUID(),
      updatedAt: Date.now(),
      synced: false,
    };

    await putSurvey(survey);
    await addToQueue({
      type: 'UPSERT_SURVEY',
      payload: survey,
      createdAt: Date.now(),
    });

    await loadSurveys();
    setForm({ id: '', location: '', observer: '', notes: '' });

    if (navigator.onLine) {
      await syncPendingData();
      await loadSurveys();
    }
  }

  return (
    <div style={{ padding: 20, maxWidth: 700, margin: '0 auto' }}>
      <h1>Field Survey App</h1>
      <p>Status: {navigator.onLine ? 'Online' : 'Offline'}</p>

      <form onSubmit={saveSurvey} style={{ display: 'grid', gap: 10, marginBottom: 20 }}>
        <input
          name="location"
          placeholder="Location"
          value={form.location}
          onChange={updateField}
          required
        />
        <input
          name="observer"
          placeholder="Observer"
          value={form.observer}
          onChange={updateField}
          required
        />
        <textarea
          name="notes"
          placeholder="Notes"
          value={form.notes}
          onChange={updateField}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((survey) => (
          <li key={survey.id} style={{ marginBottom: 12 }}>
            <strong>{survey.location}</strong> by {survey.observer}
            <br />
            {survey.notes}
            <br />
            <small>
              {new Date(survey.updatedAt).toLocaleString()} —{' '}
              {survey.synced ? 'Synced' : 'Pending Sync'}
            </small>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
