## `frontend/src/sync.js`

```javascript
import { getUnsyncedSurveys, markSurveySynced } from './db';

const API_URL = 'http://localhost:4000';

export async function syncSurveys() {
  if (!navigator.onLine) {
    console.log('Offline, skipping sync');
    return;
  }

  const unsynced = await getUnsyncedSurveys();
  if (unsynced.length === 0) return;

  for (const survey of unsynced) {
    try {
      const response = await fetch(`${API_URL}/api/surveys/sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey),
      });

      if (!response.ok) {
        throw new Error(`Sync failed for ${survey.id}`);
      }

      await markSurveySynced(survey.id);
    } catch (err) {
      console.error('Sync error:', err);
    }
  }
}

export function setupSyncListeners() {
  window.addEventListener('online', () => {
    console.log('Back online, syncing...');
    syncSurveys();
  });
}
```

