## `frontend/src/App.jsx`

```javascript
import React, { useEffect, useState } from 'react';
import {
  getAllSurveys,
  saveSurvey,
  deleteSurveyLocal,
} from './db';
import { syncSurveys, setupSyncListeners } from './sync';

function generateId() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [status, setStatus] = useState(navigator.onLine ? 'Online' : 'Offline');

  async function loadSurveys() {
    const all = await getAllSurveys();
    setSurveys(all.filter(s => !s.deleted).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
  }

  useEffect(() => {
    loadSurveys();
    setupSyncListeners();

    const onOnline = () => setStatus('Online');
    const onOffline = () => setStatus('Offline');

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    syncSurveys();

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function getLocation() {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve({ latitude: null, longitude: null });
        return;
      }

      navigator.geolocation.getCurrentPosition(
        (pos) => {
          resolve({
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude,
          });
        },
        () => resolve({ latitude: null, longitude: null }),
        { enableHighAccuracy: true, timeout: 5000 }
      );
    });
  }

  async function handleAddSurvey(e) {
    e.preventDefault();
    const coords = await getLocation();

    const survey = {
      id: generateId(),
      title,
      notes,
      latitude: coords.latitude,
      longitude: coords.longitude,
      updatedAt: new Date().toISOString(),
      synced: false,
      deleted: false,
    };

    await saveSurvey(survey);
    setTitle('');
    setNotes('');
    await loadSurveys();
    syncSurveys();
  }

  async function handleDelete(id) {
    await deleteSurveyLocal(id);
    await loadSurveys();
    syncSurveys();
  }

  return (
    <div style={{ maxWidth: 700, margin: '0 auto', padding: 20, fontFamily: 'Arial' }}>
      <h1>Field Survey App</h1>
      <p>Status: <strong>{status}</strong></p>

      <form onSubmit={handleAddSurvey} style={{ marginBottom: 24 }}>
        <div style={{ marginBottom: 12 }}>
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Survey title"
            required
            style={{ width: '100%', padding: 8 }}
          />
        </div>
        <div style={{ marginBottom: 12 }}>
          <textarea
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            placeholder="Notes"
            rows={4}
            style={{ width: '100%', padding: 8 }}
          />
        </div>
        <button type="submit">Save Survey</button>
      </form>

      <h2>Saved Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet.</p>
      ) : (
        <ul style={{ listStyle: 'none', padding: 0 }}>
          {surveys.map((survey) => (
            <li
              key={survey.id}
              style={{
                border: '1px solid #ccc',
                padding: 12,
                marginBottom: 12,
                borderRadius: 8,
              }}
            >
              <h3>{survey.title}</h3>
              <p>{survey.notes}</p>
              <p>
                Location: {survey.latitude ?? 'N/A'}, {survey.longitude ?? 'N/A'}
              </p>
              <p>
                Updated: {new Date(survey.updatedAt).toLocaleString()}
              </p>
              <p>
                Sync: {survey.synced ? 'Synced' : 'Pending'}
              </p>
              <button onClick={() => handleDelete(survey.id)}>Delete</button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
