## `backend/server.js`

```javascript
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map();

/**
 * Upsert survey from client.
 * Simple last-write-wins using updatedAt.
 */
app.post('/api/surveys/sync', (req, res) => {
  const incoming = req.body;

  if (!incoming.id || !incoming.updatedAt) {
    return res.status(400).json({ error: 'Missing id or updatedAt' });
  }

  const existing = surveys.get(incoming.id);

  if (!existing) {
    if (!incoming.deleted) {
      surveys.set(incoming.id, incoming);
    }
    return res.json({ ok: true, action: incoming.deleted ? 'ignored-delete' : 'created' });
  }

  const incomingTime = new Date(incoming.updatedAt).getTime();
  const existingTime = new Date(existing.updatedAt).getTime();

  if (incomingTime >= existingTime) {
    if (incoming.deleted) {
      surveys.delete(incoming.id);
      return res.json({ ok: true, action: 'deleted' });
    } else {
      surveys.set(incoming.id, incoming);
      return res.json({ ok: true, action: 'updated' });
    }
  }

  return res.json({ ok: true, action: 'ignored-older-update' });
});

app.get('/api/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

const PORT = 4000;
app.listen(PORT, () => {
  console.log(`Backend listening on http://localhost:${PORT}`);
});
```

