const express = require('express');
const path = require('path');

const app = express();
const PORT = 3000;

// In-memory storage for demo purposes
const surveys = [];

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Receive synced surveys
app.post('/api/surveys', (req, res) => {
  const survey = req.body;

  if (!survey || !survey.localId || !survey.name || !survey.location) {
    return res.status(400).json({ error: 'Invalid survey payload' });
  }

  const exists = surveys.find(s => s.localId === survey.localId);
  if (!exists) {
    surveys.push({
      ...survey,
      serverReceivedAt: new Date().toISOString()
    });
  }

  res.json({ success: true, localId: survey.localId });
});

// View all synced surveys
app.get('/api/surveys', (req, res) => {
  res.json(surveys);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
