# 4) `public/app.js`

```js
const DB_NAME = 'survey-db';
const STORE_NAME = 'surveys';
const DB_VERSION = 1;

const form = document.getElementById('surveyForm');
const surveyList = document.getElementById('surveyList');
const networkStatus = document.getElementById('networkStatus');
const syncBtn = document.getElementById('syncBtn');

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
  networkStatus.style.background = navigator.onLine ? '#d4edda' : '#f8d7da';
}

window.addEventListener('online', async () => {
  updateNetworkStatus();
  await syncSurveys();
});

window.addEventListener('offline', updateNetworkStatus);

updateNetworkStatus();

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = event => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'localId' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveSurvey(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = '';

  surveys.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const survey of surveys) {
    const div = document.createElement('div');
    div.className = 'survey';
    div.innerHTML = `
      <strong>${escapeHtml(survey.name)}</strong><br/>
      Location: ${escapeHtml(survey.location)}<br/>
      Notes: ${escapeHtml(survey.notes || '')}<br/>
      Created: ${new Date(survey.createdAt).toLocaleString()}<br/>
      Status: <span class="${survey.synced ? 'synced' : 'pending'}">
        ${survey.synced ? 'Synced' : 'Pending Sync'}
      </span>
    `;
    surveyList.appendChild(div);
  }
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[c]));
}

form.addEventListener('submit', async e => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    name: document.getElementById('name').value.trim(),
    location: document.getElementById('location').value.trim(),
    notes: document.getElementById('notes').value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurvey(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter(s => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch('/api/surveys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error('Sync failed');

      survey.synced = true;
      await saveSurvey(survey);
    } catch (err) {
      console.error('Failed to sync survey', survey.localId, err);
    }
  }

  await renderSurveys();
}

syncBtn.addEventListener('click', syncSurveys);

if ('serviceWorker' in navigator) {
  window.addEventListener('load', async () => {
    try {
      await navigator.serviceWorker.register('/sw.js');
      console.log('Service worker registered');
    } catch (err) {
      console.error('Service worker registration failed', err);
    }
  });
}

renderSurveys();
```

