## `client/app.js`

```js
const API_BASE = "http://localhost:3000";

const form = document.getElementById("surveyForm");
const recordsList = document.getElementById("recordsList");
const networkStatus = document.getElementById("networkStatus");
const syncBtn = document.getElementById("syncBtn");

const STORAGE_KEY = "offlineSurveyRecords";

function loadRecords() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
}

function saveRecords(records) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
}

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? "Online" : "Offline";
}

function renderRecords() {
  const records = loadRecords();
  recordsList.innerHTML = "";

  if (records.length === 0) {
    recordsList.innerHTML = "<li>No records yet.</li>";
    return;
  }

  records.forEach((record) => {
    const li = document.createElement("li");
    li.className = "record";
    li.innerHTML = `
      <strong>${escapeHtml(record.surveyor)}</strong> - ${escapeHtml(record.location)}<br>
      <small>${new Date(record.createdAt).toLocaleString()}</small><br>
      <span>${escapeHtml(record.notes || "")}</span><br>
      <span class="badge ${record.synced ? "synced" : "pending"}">
        ${record.synced ? "Synced" : "Pending Sync"}
      </span>
    `;
    recordsList.appendChild(li);
  });
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (m) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  }[m]));
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const surveyor = document.getElementById("surveyor").value.trim();
  const location = document.getElementById("location").value.trim();
  const notes = document.getElementById("notes").value.trim();

  const record = {
    clientId: crypto.randomUUID(),
    surveyor,
    location,
    notes,
    createdAt: new Date().toISOString(),
    synced: false
  };

  const records = loadRecords();
  records.push(record);
  saveRecords(records);
  renderRecords();
  form.reset();

  if (navigator.onLine) {
    await syncPendingRecords();
  }
});

async function syncPendingRecords() {
  const records = loadRecords();
  const pending = records.filter((r) => !r.synced);

  if (pending.length === 0) return;

  try {
    const response = await fetch(`${API_BASE}/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ records: pending })
    });

    if (!response.ok) {
      throw new Error("Sync failed");
    }

    const result = await response.json();
    const acceptedIds = new Set(result.accepted.map((r) => r.clientId));

    const updated = records.map((r) =>
      acceptedIds.has(r.clientId) ? { ...r, synced: true } : r
    );

    saveRecords(updated);
    renderRecords();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

syncBtn.addEventListener("click", syncPendingRecords);

window.addEventListener("online", async () => {
  updateNetworkStatus();
  await syncPendingRecords();
});

window.addEventListener("offline", updateNetworkStatus);

updateNetworkStatus();
renderRecords();
```

