## `client/app.js`

```js
const API_BASE = "http://localhost:3000";

const dbName = "offlineSurveyDB";
const storeName = "surveys";
let db;

const networkStatusEl = document.getElementById("networkStatus");
const syncStatusEl = document.getElementById("syncStatus");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const syncBtn = document.getElementById("syncBtn");

function updateNetworkStatus() {
  if (navigator.onLine) {
    networkStatusEl.textContent = "Online";
    networkStatusEl.className = "online";
  } else {
    networkStatusEl.textContent = "Offline";
    networkStatusEl.className = "offline";
  }
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(dbName, 1);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      const store = db.createObjectStore(storeName, { keyPath: "localId" });
      store.createIndex("synced", "synced", { unique: false });
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function addSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, "readwrite");
    const store = tx.objectStore(storeName);
    store.put(survey);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, "readonly");
    const store = tx.objectStore(storeName);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function getUnsyncedSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, "readonly");
    const store = tx.objectStore(storeName);
    const request = store.getAll();

    request.onsuccess = () => {
      const unsynced = request.result.filter(item => !item.synced);
      resolve(unsynced);
    };
    request.onerror = () => reject(request.error);
  });
}

function markAsSynced(localId, serverId, syncedAt) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, "readwrite");
    const store = tx.objectStore(storeName);
    const getReq = store.get(localId);

    getReq.onsuccess = () => {
      const item = getReq.result;
      if (!item) return resolve();

      item.synced = true;
      item.serverId = serverId;
      item.syncedAt = syncedAt;

      store.put(item);
    };

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((survey) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <div><strong>${escapeHtml(survey.name)}</strong></div>
        <div>${escapeHtml(survey.location)}</div>
        <div>${escapeHtml(survey.notes || "")}</div>
        <div class="meta">Created: ${new Date(survey.createdAt).toLocaleString()}</div>
        <div class="${survey.synced ? "synced" : "pending"}">
          ${survey.synced ? "Synced" : "Pending sync"}
        </div>
      `;
      surveyList.appendChild(li);
    });
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (m) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "\"": "&quot;",
    "'": "&#039;"
  }[m]));
}

async function syncSurveys() {
  if (!navigator.onLine) {
    syncStatusEl.textContent = "Offline - waiting to reconnect";
    return;
  }

  const unsynced = await getUnsyncedSurveys();

  if (unsynced.length === 0) {
    syncStatusEl.textContent = "Nothing to sync";
    return;
  }

  syncStatusEl.textContent = `Syncing ${unsynced.length} item(s)...`;

  try {
    const response = await fetch(`${API_BASE}/surveys/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ items: unsynced })
    });

    if (!response.ok) {
      throw new Error(`Sync failed with status ${response.status}`);
    }

    const result = await response.json();

    for (const accepted of result.accepted) {
      await markAsSynced(accepted.localId, accepted.serverId, accepted.syncedAt);
    }

    syncStatusEl.textContent = `Synced ${result.accepted.length} item(s)`;
    await renderSurveys();
  } catch (err) {
    console.error(err);
    syncStatusEl.textContent = "Sync failed - will retry when online";
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addSurvey(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    syncSurveys();
  }
});

syncBtn.addEventListener("click", syncSurveys);

window.addEventListener("online", () => {
  updateNetworkStatus();
  syncSurveys();
});

window.addEventListener("offline", updateNetworkStatus);

async function registerServiceWorker() {
  if ("serviceWorker" in navigator) {
    try {
      await navigator.serviceWorker.register("./sw.js");
      console.log("Service worker registered");
    } catch (err) {
      console.error("Service worker registration failed", err);
    }
  }
}

async function init() {
  updateNetworkStatus();
  await openDB();
  await renderSurveys();
  await registerServiceWorker();

  if (navigator.onLine) {
    syncSurveys();
  }
}

init();
