import express from "express";
import cors from "cors";

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

let surveys = [];
let nextId = 1;

// Health check
app.get("/api/health", (req, res) => {
  res.json({ ok: true });
});

// Get all synced surveys
app.get("/api/surveys", (req, res) => {
  res.json(surveys);
});

// Create a survey
app.post("/api/surveys", (req, res) => {
  const { localId, name, location, notes, createdAt } = req.body;

  const survey = {
    id: nextId++,
    localId,
    name,
    location,
    notes,
    createdAt,
    syncedAt: new Date().toISOString()
  };

  surveys.push(survey);
  res.status(201).json(survey);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
