## `client/app.js`

```js
const API_URL = "http://localhost:3000/api/surveys";
const DB_NAME = "survey-db";
const STORE_NAME = "surveys";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const listEl = document.getElementById("surveyList");

function updateOnlineStatus() {
  statusEl.textContent = navigator.onLine ? "Online" : "Offline";
  statusEl.style.color = navigator.onLine ? "green" : "red";
}

window.addEventListener("online", async () => {
  updateOnlineStatus();
  await syncPendingSurveys();
  await renderSurveys();
});

window.addEventListener("offline", updateOnlineStatus);

updateOnlineStatus();

if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("./sw.js");
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "localId" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveSurveyLocally(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllLocalSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function markSurveySynced(localId, serverData) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const getReq = store.get(localId);

    getReq.onsuccess = () => {
      const survey = getReq.result;
      if (survey) {
        survey.synced = true;
        survey.serverId = serverData.id;
        survey.syncedAt = serverData.syncedAt;
        store.put(survey);
      }
    };

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllLocalSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error("Sync failed");

      const serverData = await res.json();
      await markSurveySynced(survey.localId, serverData);
    } catch (err) {
      console.error("Failed to sync survey:", survey.localId, err);
    }
  }
}

async function renderSurveys() {
  const surveys = await getAllLocalSurveys();
  listEl.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((survey) => {
      const div = document.createElement("div");
      div.className = `card ${survey.synced ? "synced" : "pending"}`;
      div.innerHTML = `
        <strong>${survey.name}</strong><br/>
        <em>${survey.location}</em><br/>
        <p>${survey.notes}</p>
        <small>
          ${survey.synced ? "Synced" : "Pending sync"} |
          Created: ${new Date(survey.createdAt).toLocaleString()}
        </small>
      `;
      listEl.appendChild(div);
    });
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    name: document.getElementById("name").value,
    location: document.getElementById("location").value,
    notes: document.getElementById("notes").value,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncPendingSurveys();
    await renderSurveys();
  }
});

(async function init() {
  await renderSurveys();
  await syncPendingSurveys();
  await renderSurveys();
})();
```

