# 5. `public/app.js`

```js
const STORAGE_KEY = 'offline-survey-queue';

const form = document.getElementById('survey-form');
const connectionStatus = document.getElementById('connection-status');
const queueCount = document.getElementById('queue-count');
const localEntriesEl = document.getElementById('local-entries');
const serverEntriesEl = document.getElementById('server-entries');
const refreshServerBtn = document.getElementById('refresh-server');

function getQueue() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveQueue(queue) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(queue));
}

function updateConnectionStatus() {
  connectionStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
  connectionStatus.style.color = navigator.onLine ? 'green' : 'red';
}

function renderQueue() {
  const queue = getQueue();
  queueCount.textContent = queue.length;
  localEntriesEl.innerHTML = '';

  if (queue.length === 0) {
    localEntriesEl.innerHTML = '<li>No local queued entries.</li>';
    return;
  }

  queue.forEach(entry => {
    const li = document.createElement('li');
    li.textContent = `${entry.siteName} (${entry.latitude}, ${entry.longitude}) - ${entry.notes || 'No notes'}`;
    localEntriesEl.appendChild(li);
  });
}

async function renderServerEntries() {
  if (!navigator.onLine) {
    serverEntriesEl.innerHTML = '<li>Offline - cannot load server data.</li>';
    return;
  }

  try {
    const res = await fetch('/api/surveys');
    const data = await res.json();

    serverEntriesEl.innerHTML = '';

    if (!data.surveys.length) {
      serverEntriesEl.innerHTML = '<li>No synced server entries.</li>';
      return;
    }

    data.surveys.forEach(entry => {
      const li = document.createElement('li');
      li.textContent = `${entry.siteName} (${entry.latitude}, ${entry.longitude}) - Synced at ${entry.syncedAt}`;
      serverEntriesEl.appendChild(li);
    });
  } catch (err) {
    serverEntriesEl.innerHTML = '<li>Failed to fetch server data.</li>';
  }
}

async function syncQueue() {
  const queue = getQueue();
  if (!navigator.onLine || queue.length === 0) return;

  try {
    const res = await fetch('/api/surveys', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(queue)
    });

    if (!res.ok) throw new Error('Sync failed');

    saveQueue([]);
    renderQueue();
    renderServerEntries();
  } catch (err) {
    console.error('Sync error:', err);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const entry = {
    id: crypto.randomUUID(),
    siteName: document.getElementById('siteName').value.trim(),
    latitude: parseFloat(document.getElementById('latitude').value),
    longitude: parseFloat(document.getElementById('longitude').value),
    notes: document.getElementById('notes').value.trim(),
    createdAt: new Date().toISOString()
  };

  const queue = getQueue();
  queue.push(entry);
  saveQueue(queue);

  form.reset();
  renderQueue();

  if (navigator.onLine) {
    await syncQueue();
  }
});

window.addEventListener('online', async () => {
  updateConnectionStatus();
  await syncQueue();
  await renderServerEntries();
});

window.addEventListener('offline', () => {
  updateConnectionStatus();
});

refreshServerBtn.addEventListener('click', renderServerEntries);

if ('serviceWorker' in navigator) {
  window.addEventListener('load', async () => {
    try {
      await navigator.serviceWorker.register('/sw.js');
      console.log('Service worker registered');
    } catch (err) {
      console.error('Service worker registration failed:', err);
    }
  });
}

updateConnectionStatus();
renderQueue();
renderServerEntries();
syncQueue();
```

