## `client/app.js`

```js
const DB_NAME = 'survey-db';
const STORE_NAME = 'surveys';
const API_URL = 'http://localhost:3000/surveys';

const form = document.getElementById('surveyForm');
const surveyList = document.getElementById('surveyList');
const networkStatus = document.getElementById('networkStatus');
const syncBtn = document.getElementById('syncBtn');
const gpsBtn = document.getElementById('gpsBtn');

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = event => {
      const db = event.target.result;
      const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      store.createIndex('synced', 'synced', { unique: false });
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveSurveyLocally(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function getPendingSurveys() {
  const all = await getAllSurveys();
  return all.filter(s => !s.synced);
}

async function markSurveySynced(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const getReq = store.get(id);

    getReq.onsuccess = () => {
      const survey = getReq.result;
      survey.synced = true;
      store.put(survey);
    };

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = '';

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach(survey => {
      const li = document.createElement('li');
      li.className = survey.synced ? 'synced' : 'pending';
      li.innerHTML = `
        <strong>${survey.siteName}</strong><br>
        Surveyor: ${survey.surveyor}<br>
        Lat/Lng: ${survey.latitude}, ${survey.longitude}<br>
        Notes: ${survey.notes || '-'}<br>
        Created: ${survey.createdAt}<br>
        Status: ${survey.synced ? 'Synced' : 'Pending'}
      `;
      surveyList.appendChild(li);
    });
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const pending = await getPendingSurveys();
  if (!pending.length) return;

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await markSurveySynced(survey.id);
      }
    } catch (err) {
      console.error('Sync failed for survey', survey.id, err);
      break;
    }
  }

  await renderSurveys();
}

form.addEventListener('submit', async event => {
  event.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    surveyor: document.getElementById('surveyor').value,
    siteName: document.getElementById('siteName').value,
    latitude: parseFloat(document.getElementById('latitude').value),
    longitude: parseFloat(document.getElementById('longitude').value),
    notes: document.getElementById('notes').value,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  form.reset();
  await renderSurveys();
  await syncPendingSurveys();
});

syncBtn.addEventListener('click', syncPendingSurveys);

gpsBtn.addEventListener('click', () => {
  if (!navigator.geolocation) {
    alert('Geolocation is not supported in this browser.');
    return;
  }

  navigator.geolocation.getCurrentPosition(
    position => {
      document.getElementById('latitude').value = position.coords.latitude;
      document.getElementById('longitude').value = position.coords.longitude;
    },
    err => {
      alert('Unable to retrieve location: ' + err.message);
    }
  );
});

window.addEventListener('online', async () => {
  updateNetworkStatus();
  await syncPendingSurveys();
});

window.addEventListener('offline', updateNetworkStatus);

window.addEventListener('load', async () => {
  updateNetworkStatus();
  await renderSurveys();

  if ('serviceWorker' in navigator) {
    try {
      await navigator.serviceWorker.register('./sw.js');
      console.log('Service worker registered');
    } catch (err) {
      console.error('Service worker registration failed', err);
    }
  }

  await syncPendingSurveys();
});
```

