import express from "express";
import cors from "cors";

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

let surveys = [];

// health check
app.get("/health", (req, res) => {
  res.json({ ok: true });
});

// receive synced surveys
app.post("/surveys", (req, res) => {
  const survey = req.body;

  if (!survey || !survey.id || !survey.name || !survey.location) {
    return res.status(400).json({ error: "Invalid survey payload" });
  }

  const exists = surveys.find((s) => s.id === survey.id);
  if (!exists) {
    surveys.push({
      ...survey,
      receivedAt: new Date().toISOString()
    });
  }

  res.json({ success: true, id: survey.id });
});

// list all surveys
