# 4. IndexedDB helper

## `client/src/db.js`

```js
const DB_NAME = 'offlineSurveyDB';
const DB_VERSION = 1;
const SURVEY_STORE = 'surveys';
const PENDING_STORE = 'pending';

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains(SURVEY_STORE)) {
        db.createObjectStore(SURVEY_STORE, { keyPath: 'clientId' });
      }

      if (!db.objectStoreNames.contains(PENDING_STORE)) {
        db.createObjectStore(PENDING_STORE, { keyPath: 'clientId' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function tx(storeName, mode, action) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(storeName, mode);
    const store = transaction.objectStore(storeName);
    const result = action(store);

    transaction.oncomplete = () => resolve(result);
    transaction.onerror = () => reject(transaction.error);
  });
}

export async function saveSurvey(survey) {
  return tx(SURVEY_STORE, 'readwrite', store => store.put(survey));
}

export async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(SURVEY_STORE, 'readonly');
    const store = transaction.objectStore(SURVEY_STORE);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function savePending(survey) {
  return tx(PENDING_STORE, 'readwrite', store => store.put(survey));
}

export async function getAllPending() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(PENDING_STORE, 'readonly');
    const store = transaction.objectStore(PENDING_STORE);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function clearPending(clientId) {
  return tx(PENDING_STORE, 'readwrite', store => store.delete(clientId));
}

export async function replaceAllSurveys(surveys) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(SURVEY_STORE, 'readwrite');
    const store = transaction.objectStore(SURVEY_STORE);

    store.clear();
    surveys.forEach(s => store.put(s));

    transaction.oncomplete = () => resolve(true);
    transaction.onerror = () => reject(transaction.error);
  });
}
```

