# 5. Sync logic

## `client/src/sync.js`

```js
import { getAllPending, clearPending, replaceAllSurveys } from './db';

const API_URL = 'http://localhost:4000';

export async function syncData() {
  if (!navigator.onLine) return { synced: false, reason: 'offline' };

  const pending = await getAllPending();

  const response = await fetch(`${API_URL}/sync`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ changes: pending })
  });

  if (!response.ok) {
    throw new Error('Sync failed');
  }

  const result = await response.json();

  for (const item of pending) {
    await clearPending(item.clientId);
  }

  await replaceAllSurveys(result.serverData);

  return { synced: true, count: pending.length };
}

export async function fetchServerData() {
  if (!navigator.onLine) return;

  const response = await fetch(`${API_URL}/surveys`);
  const data = await response.json();
  await replaceAllSurveys(data);
}
```

