```jsx
import React, { useEffect, useState } from 'react';
import { getAllSurveys, saveSurvey, savePending } from './db';
import { syncData, fetchServerData } from './sync';

function makeId() {
  return crypto.randomUUID();
}

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState(navigator.onLine ? 'Online' : 'Offline');

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)));
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      clientId: makeId(),
      title,
      location,
      notes,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    await saveSurvey(survey);
    await savePending(survey);
    await loadLocal();

    setTitle('');
    setLocation('');
    setNotes('');

    if (navigator.onLine) {
      try {
        await syncData();
        await loadLocal();
      } catch (err) {
        console.error(err);
      }
    }
  }

  async function handleSync() {
    try {
      setStatus('Syncing...');
      await syncData();
      await loadLocal();
      setStatus(navigator.onLine ? 'Online' : 'Offline');
    } catch (err) {
      console.error(err);
      setStatus('Sync failed');
    }
  }

  useEffect(() => {
    loadLocal();

    if (navigator.onLine) {
      fetchServerData().then(loadLocal).catch(console.error);
    }

    const goOnline = async () => {
      setStatus('Online');
      try {
        await syncData();
        await loadLocal();
      } catch (err) {
        console.error(err);
      }
    };

    const goOffline = () => setStatus('Offline');

    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);

    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  return (
    <div style={{ maxWidth: 700, margin: '40px auto', fontFamily: 'Arial, sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>Status: <strong>{status}</strong></p>

      <form onSubmit={handleSubmit} style={{ display: 'grid', gap: 10, marginBottom: 20 }}>
        <input
          placeholder="Survey title"
          value={title}
          onChange={e => setTitle(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={e => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={e => setNotes(e.target.value)}
          rows={4}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={handleSync} disabled={!navigator.onLine}>
        Sync Now
      </button>

      <h2 style={{ marginTop: 30 }}>Saved Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet.</p>
      ) : (
        <ul style={{ padding: 0, listStyle: 'none' }}>
          {surveys.map(s => (
            <li
              key={s.clientId}
              style={{
                border: '1px solid #ccc',
                padding: 12,
                borderRadius: 8,
                marginBottom: 10
              }}
            >
              <strong>{s.title}</strong>
              <div>{s.location}</div>
              <div>{s.notes}</div>
              <small>{new Date(s.createdAt).toLocaleString()}</small>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
