## `client/app.js`

```js
const API_URL = "http://localhost:3000/submissions";
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function tx(storeName, mode = "readonly") {
  return db.transaction(storeName, mode).objectStore(storeName);
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const request = tx(STORE_NAME).getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function saveSurveyLocally(survey) {
  return new Promise((resolve, reject) => {
    const request = tx(STORE_NAME, "readwrite").put(survey);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function updateNetworkStatus() {
  const el = document.getElementById("networkStatus");
  el.textContent = navigator.onLine ? "Online" : "Offline";
  el.style.color = navigator.onLine ? "green" : "red";
}

function renderSurveys(surveys) {
  const list = document.getElementById("surveyList");
  list.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((survey) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <strong>${escapeHtml(survey.surveyor)}</strong> - ${escapeHtml(survey.location)}<br/>
        <small>${new Date(survey.createdAt).toLocaleString()}</small><br/>
        <div>${escapeHtml(survey.notes || "")}</div>
        <div class="${survey.synced ? "synced" : "pending"}">
          ${survey.synced ? "Synced" : "Pending sync"}
        </div>
      `;
      list.appendChild(li);
    });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function refreshUI() {
  const surveys = await getAllSurveys();
  renderSurveys(surveys);
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (!res.ok) throw new Error("Sync failed");

      survey.synced = true;
      await saveSurveyLocally(survey);
    } catch (err) {
      console.error("Could not sync survey:", survey.id, err);
    }
  }

  await refreshUI();
}

function generateId() {
  return crypto.randomUUID
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

async function handleSubmit(event) {
  event.preventDefault();

  const survey = {
    id: generateId(),
    surveyor: document.getElementById("surveyor").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurveyLocally(survey);
  event.target.reset();
  await refreshUI();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
}

async function init() {
  await openDB();
  updateNetworkStatus();
  await refreshUI();

  document.getElementById("surveyForm").addEventListener("submit", handleSubmit);
  document.getElementById("syncBtn").addEventListener("click", syncPendingSurveys);

  window.addEventListener("online", async () => {
    updateNetworkStatus();
    await syncPendingSurveys();
  });

  window.addEventListener("offline", updateNetworkStatus);
}

init().catch(console.error);
```

