## `client/app.js`

```js
const API_URL = 'http://localhost:3000';
const DB_NAME = 'offlineSurveyDB';
const STORE_NAME = 'pendingSurveys';

const statusEl = document.getElementById('status');
const form = document.getElementById('survey-form');
const pendingList = document.getElementById('pending-list');
const serverList = document.getElementById('server-list');
const refreshServerBtn = document.getElementById('refresh-server');

function updateOnlineStatus() {
  if (navigator.onLine) {
    statusEl.textContent = 'Online';
    statusEl.className = 'online';
  } else {
    statusEl.textContent = 'Offline';
    statusEl.className = 'offline';
  }
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function savePendingSurvey(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getPendingSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function deletePendingSurvey(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderPendingSurveys() {
  const surveys = await getPendingSurveys();
  pendingList.innerHTML = '';

  if (surveys.length === 0) {
    pendingList.innerHTML = '<li>No pending surveys</li>';
    return;
  }

  surveys.forEach(s => {
    const li = document.createElement('li');
    li.textContent = `${s.name} @ ${s.location} - ${s.notes}`;
    pendingList.appendChild(li);
  });
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const pending = await getPendingSurveys();
  if (pending.length === 0) return;

  try {
    const response = await fetch(`${API_URL}/surveys`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(pending)
    });

    if (!response.ok) throw new Error('Sync failed');

    for (const survey of pending) {
      await deletePendingSurvey(survey.id);
    }

    await renderPendingSurveys();
    await fetchServerSurveys();
  } catch (err) {
    console.error('Sync error:', err);
  }
}

async function fetchServerSurveys() {
  if (!navigator.onLine) return;

  try {
    const res = await fetch(`${API_URL}/surveys`);
    const data = await res.json();

    serverList.innerHTML = '';
    data.forEach(s => {
      const li = document.createElement('li');
      li.textContent = `${s.name} @ ${s.location} - ${s.notes}`;
      serverList.appendChild(li);
    });

    if (data.length === 0) {
      serverList.innerHTML = '<li>No server surveys yet</li>';
    }
  } catch (err) {
    console.error('Failed to load server surveys:', err);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById('name').value,
    location: document.getElementById('location').value,
    notes: document.getElementById('notes').value,
    createdAt: new Date().toISOString()
  };

  await savePendingSurvey(survey);
  form.reset();
  await renderPendingSurveys();
  await syncSurveys();
});

refreshServerBtn.addEventListener('click', fetchServerSurveys);

window.addEventListener('online', async () => {
  updateOnlineStatus();
  await syncSurveys();
});

window.addEventListener('offline', updateOnlineStatus);

async function registerServiceWorker() {
  if ('serviceWorker' in navigator) {
    try {
      await navigator.serviceWorker.register('./sw.js');
      console.log('Service worker registered');
    } catch (err) {
      console.error('SW registration failed:', err);
    }
  }
}

(async function init() {
  updateOnlineStatus();
  await renderPendingSurveys();
  await fetchServerSurveys();
  await syncSurveys();
  await registerServiceWorker();
})();
```

## `client/sw.js`

```js
const CACHE_NAME = 'offline-survey-cache-v1';
const ASSETS = [
  './',
  './index.html',
  './app.js',
  './styles.css',
  './manifest.json'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => cache.addAll(ASSETS))
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request).then(cached => {
      return cached || fetch(event.request);
    })
  );
});
