## `client/src/db.js`

```js
import { openDB } from "idb";

const DB_NAME = "survey-db";
const STORE_NAME = "surveys";

export async function getDb() {
  return openDB(DB_NAME, 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, {
          keyPath: "localId"
        });
        store.createIndex("synced", "synced");
      }
    }
  });
}

export async function addSurvey(survey) {
  const db = await getDb();
  await db.put(STORE_NAME, survey);
}

export async function getAllSurveys() {
  const db = await getDb();
  return db.getAll(STORE_NAME);
}

export async function getUnsyncedSurveys() {
  const db = await getDb();
  return db.getAllFromIndex(STORE_NAME, "synced", false);
}

export async function markSurveySynced(localId) {
  const db = await getDb();
  const survey = await db.get(STORE_NAME, localId);
  if (!survey) return;
  survey.synced = true;
  await db.put(STORE_NAME, survey);
}
```

