## `client/src/App.js`

```js
import React, { useEffect, useState } from "react";
import {
  addSurvey,
  getAllSurveys,
  getUnsyncedSurveys,
  markSurveySynced
} from "./db";

const API_URL = "http://localhost:4000";

function App() {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState(navigator.onLine ? "Online" : "Offline");
  const [syncing, setSyncing] = useState(false);

  async function refreshSurveys() {
    const all = await getAllSurveys();
    all.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    setSurveys(all);
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      localId: crypto.randomUUID(),
      name,
      location,
      notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await addSurvey(survey);
    setName("");
    setLocation("");
    setNotes("");
    await refreshSurveys();

    if (navigator.onLine) {
      await syncSurveys();
    }
  }

  async function syncSurveys() {
    if (syncing) return;
    setSyncing(true);

    try {
      const unsynced = await getUnsyncedSurveys();
      if (unsynced.length === 0) {
        setSyncing(false);
        return;
      }

      const response = await fetch(`${API_URL}/surveys/sync`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ surveys: unsynced })
      });

      if (!response.ok) {
        throw new Error("Sync failed");
      }

      for (const survey of unsynced) {
        await markSurveySynced(survey.localId);
      }

      await refreshSurveys();
    } catch (err) {
      console.error("Sync error:", err);
    } finally {
      setSyncing(false);
    }
  }

  useEffect(() => {
    refreshSurveys();

    function handleOnline() {
      setStatus("Online");
      syncSurveys();
    }

    function handleOffline() {
      setStatus("Offline");
    }

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    if (navigator.onLine) {
      syncSurveys();
    }

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", fontFamily: "Arial" }}>
      <h1>Field Survey App</h1>
      <p>
        Status: <strong>{status}</strong>{" "}
        {syncing ? <span>(syncing...)</span> : null}
      </p>

      <form onSubmit={handleSubmit} style={{ marginBottom: 24 }}>
        <div style={{ marginBottom: 12 }}>
          <label>Surveyor Name</label>
          <br />
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            style={{ width: "100%", padding: 8 }}
          />
        </div>

        <div style={{ marginBottom: 12 }}>
          <label>Location</label>
          <br />
          <input
            value={location}
            onChange={(e) => setLocation(e.target.value)}
            required
            style={{ width: "100%", padding: 8 }}
          />
        </div>

        <div style={{ marginBottom: 12 }}>
          <label>Notes</label>
          <br />
          <textarea
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            rows="4"
            style={{ width: "100%", padding: 8 }}
          />
        </div>

        <button type="submit">Save Survey</button>
      </form>

      <h2>Local Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet.</p>
      ) : (
        <ul style={{ listStyle: "none", padding: 0 }}>
          {surveys.map((s) => (
            <li
              key={s.localId}
              style={{
                border: "1px solid #ccc",
                padding: 12,
                marginBottom: 12,
                borderRadius: 6
              }}
            >
              <div><strong>{s.name}</strong></div>
              <div>Location: {s.location}</div>
              <div>Notes: {s.notes || "-"}</div>
              <div>Created: {new Date(s.createdAt).toLocaleString()}</div>
              <div>
                Sync:{" "}
                <strong style={{ color: s.synced ? "green" : "orange" }}>
                  {s.synced ? "Synced" : "Pending"}
                </strong>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default App;
```

