const API_URL = "http://localhost:3000/sync";

const form = document.getElementById("surveyForm");
const recordsEl = document.getElementById("records");
const connectionStatusEl = document.getElementById("connectionStatus");
const pendingCountEl = document.getElementById("pendingCount");
const syncNowBtn = document.getElementById("syncNowBtn");

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("synced", "synced", { unique: false });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function addSurvey(record) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function getPendingSurveys() {
  const all = await getAllSurveys();
  return all.filter((r) => !r.synced);
}

async function markSynced(ids) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);

    ids.forEach((id) => {
      const getReq = store.get(id);
      getReq.onsuccess = () => {
        const record = getReq.result;
        if (record) {
          record.synced = true;
          record.syncedAt = new Date().toISOString();
          store.put(record);
        }
      };
    });

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function updateConnectionStatus() {
  if (navigator.onLine) {
    connectionStatusEl.textContent = "Online";
    connectionStatusEl.className = "online";
  } else {
    connectionStatusEl.textContent = "Offline";
    connectionStatusEl.className = "offline";
  }
}

async function renderRecords() {
  const records = await getAllSurveys();
  const pending = records.filter((r) => !r.synced).length;
  pendingCountEl.textContent = pending;

  recordsEl.innerHTML = "";

  records
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((r) => {
      const div = document.createElement("div");
      div.className = "record";
      div.innerHTML = `
        <strong>${escapeHtml(r.siteName)}</strong><br />
        Observer: ${escapeHtml(r.observer)}<br />
        Notes: ${escapeHtml(r.notes || "")}<br />
        Created: ${new Date(r.createdAt).toLocaleString()}<br />
        Synced: ${r.synced ? "Yes" : "No"}
      `;
      recordsEl.appendChild(div);
    });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function syncPending() {
  if (!navigator.onLine) return;

  const pending = await getPendingSurveys();
  if (pending.length === 0) {
    await renderRecords();
    return;
  }

  try {
    const response = await fetch(API_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ records: pending })
    });

    if (!response.ok) {
      throw new Error("Sync failed");
    }

    await markSynced(pending.map((r) => r.id));
    await renderRecords();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    id: crypto.randomUUID(),
    siteName: document.getElementById("siteName").value.trim(),
    observer: document.getElementById("observer").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addSurvey(record);
  form.reset();
  await renderRecords();
  await syncPending();
});

syncNowBtn.addEventListener("click", syncPending);

window.addEventListener("online", async () => {
  updateConnectionStatus();
  await syncPending();
});

window.addEventListener("offline", updateConnectionStatus);

async function registerServiceWorker() {
  if ("serviceWorker" in navigator) {
    try {
      await navigator.serviceWorker.register("./sw.js");
      console.log("Service worker registered");
    } catch (err) {
      console.error("SW registration failed:", err);
    }
  }
}

async function init() {
  updateConnectionStatus();
  await renderRecords();
  await registerServiceWorker();
  await syncPending();
}

init();
```

