```js
const API_BASE = 'http://localhost:3000';
const DB_NAME = 'survey-db';
const STORE_NAME = 'surveys';

const form = document.getElementById('surveyForm');
const recordsList = document.getElementById('recordsList');
const networkStatus = document.getElementById('networkStatus');
const syncBtn = document.getElementById('syncBtn');

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
  networkStatus.style.color = navigator.onLine ? 'green' : 'red';
}

window.addEventListener('online', async () => {
  updateNetworkStatus();
  await syncPendingRecords();
});

window.addEventListener('offline', updateNetworkStatus);

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function addRecord(record) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllRecords() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const req = tx.objectStore(STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function markAsSynced(ids) {
  const db = await openDB();
  return new Promise(async (resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);

    for (const id of ids) {
      const getReq = store.get(id);
      getReq.onsuccess = () => {
        const record = getReq.result;
        if (record) {
          record.synced = true;
          record.syncedAt = new Date().toISOString();
          store.put(record);
        }
      };
    }

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function renderRecords(records) {
  recordsList.innerHTML = '';

  if (!records.length) {
    recordsList.innerHTML = '<li>No local records yet.</li>';
    return;
  }

  records
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((record) => {
      const li = document.createElement('li');
      li.innerHTML = `
        <strong>${record.surveyor}</strong> @ ${record.location}<br/>
        <div>${record.observation}</div>
        <small>Created: ${record.createdAt}</small><br/>
        <small class="${record.synced ? 'synced' : 'pending'}">
          ${record.synced ? 'Synced' : 'Pending sync'}
        </small>
      `;
      recordsList.appendChild(li);
    });
}

async function refreshUI() {
  const records = await getAllRecords();
  renderRecords(records);
}

async function syncPendingRecords() {
  if (!navigator.onLine) return;

  const records = await getAllRecords();
  const pending = records.filter((r) => !r.synced);

  if (!pending.length) return;

  try {
    const res = await fetch(`${API_BASE}/surveys/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ records: pending })
    });

    if (!res.ok) throw new Error('Sync failed');

    const data = await res.json();
    await markAsSynced(data.acceptedIds);
    await refreshUI();
  } catch (err) {
    console.error('Sync error:', err);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const record = {
    id: crypto.randomUUID(),
    surveyor: document.getElementById('surveyor').value.trim(),
    location: document.getElementById('location').value.trim(),
    observation: document.getElementById('observation').value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addRecord(record);
  form.reset();
  await refreshUI();

  if (navigator.onLine) {
    await syncPendingRecords();
  }
});

syncBtn.addEventListener('click', async () => {
  await syncPendingRecords();
});

(async function init() {
  updateNetworkStatus();
  await refreshUI();
  if (navigator.onLine) {
    await syncPendingRecords();
  }
})();
