```js
const form = document.getElementById('surveyForm');
const statusEl = document.getElementById('status');
const queueCountEl = document.getElementById('queueCount');
const surveyListEl = document.getElementById('surveyList');
const syncBtn = document.getElementById('syncBtn');
const refreshBtn = document.getElementById('refreshBtn');

const QUEUE_KEY = 'offlineSurveyQueue';

function getQueue() {
  return JSON.parse(localStorage.getItem(QUEUE_KEY) || '[]');
}

function saveQueue(queue) {
  localStorage.setItem(QUEUE_KEY, JSON.stringify(queue));
  renderQueueCount();
}

function renderQueueCount() {
  queueCountEl.textContent = getQueue().length;
}

function updateOnlineStatus() {
  if (navigator.onLine) {
    statusEl.textContent = 'Online';
    statusEl.className = 'online';
  } else {
    statusEl.textContent = 'Offline';
    statusEl.className = 'offline';
  }
}

function createSurveyPayload() {
  return {
    id: crypto.randomUUID(),
    name: document.getElementById('name').value.trim(),
    location: document.getElementById('location').value.trim(),
    notes: document.getElementById('notes').value.trim(),
    createdAt: new Date().toISOString()
  };
}

async function syncQueue() {
  const queue = getQueue();
  if (!navigator.onLine) {
    alert('You are offline. Sync will happen when reconnected.');
    return;
  }

  if (queue.length === 0) {
    return;
  }

  try {
    const res = await fetch('/api/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(queue)
    });

    if (!res.ok) {
      throw new Error('Sync failed');
    }

    saveQueue([]);
    await fetchSurveys();
  } catch (err) {
    console.error('Sync error:', err);
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();

  const survey = createSurveyPayload();
  const queue = getQueue();
  queue.push(survey);
  saveQueue(queue);

  form.reset();

  if (navigator.onLine) {
    await syncQueue();
  } else {
    alert('Saved offline. Will sync when online.');
  }
});

async function fetchSurveys() {
  if (!navigator.onLine) return;

  try {
    const res = await fetch('/api/surveys');
    const surveys = await res.json();

    surveyListEl.innerHTML = '';
    surveys.forEach(s => {
      const li = document.createElement('li');
      li.textContent = `${s.name} - ${s.location} (${s.notes})`;
      surveyListEl.appendChild(li);
    });
  } catch (err) {
    console.error('Fetch surveys error:', err);
  }
}

window.addEventListener('online', async () => {
  updateOnlineStatus();
  await syncQueue();
});

window.addEventListener('offline', updateOnlineStatus);

