# 6. `public/app.js`

```js
const form = document.getElementById('surveyForm');
const locationInput = document.getElementById('location');
const observationInput = document.getElementById('observation');
const pendingList = document.getElementById('pendingList');
const syncBtn = document.getElementById('syncBtn');
const statusEl = document.getElementById('status');

const STORAGE_KEY = 'offlineSurveyQueue';

function getQueue() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}

function saveQueue(queue) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(queue));
}

function renderQueue() {
  const queue = getQueue();
  pendingList.innerHTML = '';

  if (queue.length === 0) {
    const li = document.createElement('li');
    li.textContent = 'No pending records';
    pendingList.appendChild(li);
    return;
  }

  queue.forEach(item => {
    const li = document.createElement('li');
    li.textContent = `${item.location} - ${item.observation} (${item.createdAt})`;
    pendingList.appendChild(li);
  });
}

function updateOnlineStatus() {
  if (navigator.onLine) {
    statusEl.textContent = 'Online';
    statusEl.className = 'status online';
  } else {
    statusEl.textContent = 'Offline';
    statusEl.className = 'status offline';
  }
}

async function syncQueue() {
  if (!navigator.onLine) {
    alert('You are offline. Cannot sync now.');
    return;
  }

  let queue = getQueue();
  if (queue.length === 0) {
    alert('No pending records to sync.');
    return;
  }

  const remaining = [];

  for (const record of queue) {
    try {
      const res = await fetch('/api/surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(record)
      });

      if (!res.ok) {
        throw new Error('Sync failed');
      }
    } catch (err) {
      remaining.push(record);
    }
  }

  saveQueue(remaining);
  renderQueue();

  if (remaining.length === 0) {
    alert('All records synced successfully.');
  } else {
    alert(`${remaining.length} record(s) still pending.`);
  }
}

form.addEventListener('submit', (e) => {
  e.preventDefault();

  const record = {
    id: crypto.randomUUID(),
    location: locationInput.value.trim(),
    observation: observationInput.value.trim(),
    createdAt: new Date().toISOString()
  };

  if (!record.location || !record.observation) {
    alert('Please fill in all fields.');
    return;
  }

  const queue = getQueue();
  queue.push(record);
  saveQueue(queue);
  renderQueue();

  form.reset();

  if (navigator.onLine) {
    syncQueue();
  } else {
    alert('Saved offline. Will sync when reconnected.');
  }
});

syncBtn.addEventListener('click', syncQueue);

window.addEventListener('online', () => {
  updateOnlineStatus();
  syncQueue();
});

window.addEventListener('offline', updateOnlineStatus);

updateOnlineStatus();
renderQueue();
```

