## `client/app.js`

```js
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";
const API_URL = "http://localhost:3000/sync";

const form = document.getElementById("survey-form");
const recordsList = document.getElementById("records");
const statusEl = document.getElementById("status");
const syncBtn = document.getElementById("sync-btn");

function updateOnlineStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online" : "Offline";
  statusEl.className = online ? "online" : "offline";
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function addRecord(record) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllRecords() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const request = tx.objectStore(STORE_NAME).getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function deleteRecord(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function renderRecords() {
  const records = await getAllRecords();
  recordsList.innerHTML = "";

  if (records.length === 0) {
    recordsList.innerHTML = "<li>No local records</li>";
    return;
  }

  for (const record of records) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${record.surveyor}</strong> @ ${record.location}<br/>
      ${record.notes || ""}<br/>
      <small>${record.createdAt}</small><br/>
      <em>${record.synced ? "Synced" : "Pending sync"}</em>
    `;
    recordsList.appendChild(li);
  }
}

async function markRecordSynced(id) {
  const records = await getAllRecords();
  const record = records.find((r) => r.id === id);
  if (!record) return;
  record.synced = true;
  await addRecord(record);
}

async function syncRecords() {
  if (!navigator.onLine) return;

  const records = await getAllRecords();
  const pending = records.filter((r) => !r.synced);

  if (pending.length === 0) return;

  try {
    const response = await fetch(API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ records: pending })
    });

    if (!response.ok) throw new Error("Sync failed");

    const result = await response.json();

    for (const id of result.accepted) {
      await markRecordSynced(id);
    }

    await renderRecords();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    id: crypto.randomUUID(),
    surveyor: document.getElementById("surveyor").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addRecord(record);
  form.reset();
  await renderRecords();

  if (navigator.onLine) {
    await syncRecords();
  }
});

syncBtn.addEventListener("click", syncRecords);

window.addEventListener("online", async () => {
  updateOnlineStatus();
  await syncRecords();
});

window.addEventListener("offline", updateOnlineStatus);

async function registerServiceWorker() {
  if ("serviceWorker" in navigator) {
    try {
      await navigator.serviceWorker.register("./sw.js");
      console.log("Service worker registered");
    } catch (err) {
      console.error("SW registration failed", err);
    }
  }
}

(async function init() {
  updateOnlineStatus();
  await renderRecords();
  await registerServiceWorker();

  if (navigator.onLine) {
    await syncRecords();
  }
})();
```

