## `client/app.js`

```js
const DB_NAME = "offlineSurveyDB";
const STORE_NAME = "surveys";
const API_URL = "http://localhost:3000/sync";

const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const networkStatus = document.getElementById("networkStatus");
const syncBtn = document.getElementById("syncBtn");

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
      store.createIndex("synced", "synced", { unique: false });
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function tx(storeName, mode = "readonly") {
  return db.transaction(storeName, mode).objectStore(storeName);
}

function addSurvey(record) {
  return new Promise((resolve, reject) => {
    const request = tx(STORE_NAME, "readwrite").put(record);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

function getAllSurveys() {
  return new Promise((resolve, reject) => {
    const request = tx(STORE_NAME).getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function getPendingSurveys() {
  return new Promise((resolve, reject) => {
    const index = tx(STORE_NAME).index("synced");
    const request = index.getAll(false);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function markAsSynced(ids) {
  return Promise.all(
    ids.map(id => new Promise((resolve, reject) => {
      const store = tx(STORE_NAME, "readwrite");
      const getReq = store.get(id);

      getReq.onsuccess = () => {
        const record = getReq.result;
        if (!record) return resolve();

        record.synced = true;
        record.syncedAt = new Date().toISOString();

        const putReq = store.put(record);
        putReq.onsuccess = () => resolve();
        putReq.onerror = () => reject(putReq.error);
      };

      getReq.onerror = () => reject(getReq.error);
    }))
  );
}

function renderSurveys(records) {
  surveyList.innerHTML = "";

  records.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  for (const record of records) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${record.surveyor}</strong> @ ${record.location}<br/>
      ${record.notes || ""}<br/>
      <small>${record.createdAt}</small><br/>
      <small class="${record.synced ? "synced" : "pending"}">
        ${record.synced ? "Synced" : "Pending sync"}
      </small>
    `;
    surveyList.appendChild(li);
  }
}

async function refreshUI() {
  const records = await getAllSurveys();
  renderSurveys(records);
}

function updateNetworkStatus() {
  networkStatus.textContent = navigator.onLine ? "Online" : "Offline";
}

async function syncPending() {
  if (!navigator.onLine) return;

  const pending = await getPendingSurveys();
  if (!pending.length) return;

  try {
    const response = await fetch(API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ records: pending })
    });

    if (!response.ok) throw new Error("Sync failed");

    const result = await response.json();
    await markAsSynced(result.accepted);
    await refreshUI();
  } catch (err) {
    console.error("Sync error:", err);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    id: crypto.randomUUID(),
    surveyor: document.getElementById("surveyor").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await addSurvey(record);
  form.reset();
  await refreshUI();
  await syncPending();
});

syncBtn.addEventListener("click", syncPending);

window.addEventListener("online", async () => {
  updateNetworkStatus();
  await syncPending();
});

window.addEventListener("offline", updateNetworkStatus);

async function init() {
  db = await openDB();
  updateNetworkStatus();
  await refreshUI();
  await syncPending();
}

init();
```

