import express from "express";
import cors from "cors";

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

let surveys = [];

/*
Survey shape:
{
  id: string,
  name: string,
  location: string,
  notes: string,
  createdAt: number,
  syncedAt?: number
}
*/

app.get("/api/surveys", (req, res) => {
  res.json(surveys);
});

app.post("/api/sync", (req, res) => {
  const { items } = req.body;

  if (!Array.isArray(items)) {
    return res.status(400).json({ error: "items must be an array" });
  }

  const acceptedIds = [];

  for (const item of items) {
    const exists = surveys.some(s => s.id === item.id);
    if (!exists) {
      surveys.push({
        ...item,
        syncedAt: Date.now()
      });
    }
    acceptedIds.push(item.id);
  }

  res.json({
    success: true,
    acceptedIds,
    serverCount: surveys.length
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
