```js
import express from "express";
import http from "http";
import { Server } from "socket.io";
import Stripe from "stripe";
import cors from "cors";
import jwt from "jsonwebtoken";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const users = new Map();
const messages = [];

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "No token" });

  try {
    const token = auth.split(" ")[1];
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/api/messages", authMiddleware, (req, res) => {
  const { toUserId, text } = req.body;
  const message = {
    id: Date.now().toString(),
    fromUserId: req.user.id,
    toUserId,
    text,
    createdAt: new Date().toISOString()
  };

  messages.push(message);
  io.to(toUserId).emit("message:new", message);
  res.json(message);
});

app.get("/api/messages", authMiddleware, (req, res) => {
  const userMessages = messages.filter(
    m => m.fromUserId === req.user.id || m.toUserId === req.user.id
  );
  res.json(userMessages);
});

app.post("/api/create-subscription", authMiddleware, async (req, res) => {
  try {
    const customer = await stripe.customers.create({
      metadata: { userId: req.user.id }
    });

    const subscription = await stripe.subscriptions.create({
      customer: customer.id,
      items: [{ price: process.env.STRIPE_PRICE_ID }],
      payment_behavior: "default_incomplete",
      expand: ["latest_invoice.payment_intent"]
    });

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

io.use((socket, next) => {
  try {
    const token = socket.handshake.auth.token;
    const user = jwt.verify(token, process.env.JWT_SECRET);
    socket.user = user;
    next();
  } catch {
    next(new Error("Unauthorized"));
  }
});

io.on("connection", socket => {
  const userId = socket.user.id;
  socket.join(userId);
  users.set(userId, socket.id);

  socket.on("message:send", ({ toUserId, text }) => {
    const message = {
      id: Date.now().toString(),
      fromUserId: userId,
      toUserId,
      text,
      createdAt: new Date().toISOString()
    };

    messages.push(message);
    io.to(toUserId).emit("message:new", message);
    io.to(userId).emit("message:new", message);
  });

  socket.on("disconnect", () => {
    users.delete(userId);
  });
});

server.listen(4000, () => {
  console.log("Server running on port 4000");
});
```

