```js
const express = require("express");
const auth = require("../middleware/auth");
const Conversation = require("../models/Conversation");
const Message = require("../models/Message");

const router = express.Router();

router.post("/send", auth, async (req, res) => {
  try {
    const {
      recipientId,
      text,
      mediaUrl,
      isPaidContent = false,
      unlockPrice = 0
    } = req.body;

    let conversation = await Conversation.findOne({
      participants: { $all: [req.user.id, recipientId] }
    });

    if (!conversation) {
      conversation = await Conversation.create({
        participants: [req.user.id, recipientId]
      });
    }

    const message = await Message.create({
      conversationId: conversation._id,
      sender: req.user.id,
      text,
      mediaUrl,
      isPaidContent,
      unlockPrice
    });

    conversation.lastMessage = text || "[media]";
    await conversation.save();

    const io = req.app.get("io");
    io.to(recipientId).emit("new_message", message);
    io.to(recipientId).emit("notification", {
      type: "message",
      message: "You received a new message"
    });

    res.json(message);
  } catch (err) {
    res.status(500).json({ message: "Send failed", error: err.message });
  }
});

router.get("/conversation/:userId", auth, async (req, res) => {
  try {
    const otherUserId = req.params.userId;

    const conversation = await Conversation.findOne({
      participants: { $all: [req.user.id, otherUserId] }
    });

    if (!conversation) return res.json([]);

    const messages = await Message.find({
      conversationId: conversation._id
    }).sort({ createdAt: 1 });

    res.json(messages);
  } catch (err) {
    res.status(500).json({ message: "Fetch messages failed", error: err.message });
  }
});

module.exports = router;
```

