```js
const express = require("express");
const Stripe = require("stripe");
const auth = require("../middleware/auth");
const User = require("../models/User");
const Purchase = require("../models/Purchase");
const Message = require("../models/Message");

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-checkout-session", auth, async (req, res) => {
  try {
    const { type, amount } = req.body;

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [{
        price_data: {
          currency: "usd",
          product_data: {
            name: type === "coins" ? "Coin Pack" : "Premium Upgrade"
          },
          unit_amount: amount * 100
        },
        quantity: 1
      }],
      success_url: `${process.env.CLIENT_URL}/chat?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/chat?canceled=true`,
      metadata: {
        userId: req.user.id,
        type,
        amount: String(amount)
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: "Stripe session failed", error: err.message });
  }
});

router.post("/mock-confirm", auth, async (req, res) => {
  try {
    const { type, amount, messageId } = req.body;

    const user = await User.findById(req.user.id);

    if (type === "subscription") {
      user.isPremium = true;
    }

    if (type === "coins") {
      user.coins += amount;
    }

    if (type === "unlock") {
      const message = await Message.findById(messageId);
      if (!message) return res.status(404).json({ message: "Message not found" });

      if (user.coins < message.unlockPrice) {
        return res.status(400).json({ message: "Not enough coins" });
      }

      user.coins -= message.unlockPrice;

      if (!message.unlockedBy.includes(user._id)) {
        message.unlockedBy.push(user._id);
        await message.save();
      }
    }

    await user.save();

    await Purchase.create({
      userId: user._id,
      type,
      amount,
      metadata: { messageId: messageId || null }
    });

    res.json({ message: "Purchase processed", user });
  } catch (err) {
    res.status(500).json({ message: "Purchase failed", error: err.message });
  }
});

module.exports = router;
