          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>
          Chat {selectedUser ? `with ${selectedUser.username}` : ""}
        </h3>
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10 }}>
          {messages.map((m, i) => (
            <div key={m._id || i} style={{ marginBottom: 8 }}>
              <strong>{m.sender?.username || m.sender}</strong>:{" "}
              {m.isPaidContent ? `🔒 Locked content (${m.unlockPrice} coins)` : m.text}
            </div>
          ))}
        </div>

        <input
