# 8. Message controller with real-time events

```js
// server/src/controllers/messageController.js
import prisma from '../lib/prisma.js';
import { getIO, getOnlineUsers } from '../socket.js';

export async function sendMessage(req, res) {
  try {
    const senderId = req.user.id;
    const { receiverId, content } = req.body;

    const message = await prisma.message.create({
      data: {
        senderId,
        receiverId,
        content
      }
    });

    const notification = await prisma.notification.create({
      data: {
        userId: receiverId,
        type: 'message',
        title: 'New Message',
        body: content.slice(0, 100)
      }
    });

    const io = getIO();
    const onlineUsers = getOnlineUsers();

    const receiverSocketId = onlineUsers.get(receiverId);
    if (receiverSocketId) {
      io.to(receiverSocketId).emit('message:new', message);
      io.to(receiverSocketId).emit('notification:new', notification);
    }

    res.json({ message });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}

export async function getConversation(req, res) {
  try {
    const userId = req.user.id;
    const { otherUserId } = req.params;

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: userId, receiverId: otherUserId },
          { senderId: otherUserId, receiverId: userId }
        ]
      },
      orderBy: { createdAt: 'asc' }
    });

    res.json({ messages });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}
```

