# 20. Chat page

```jsx
// client/src/pages/ChatPage.jsx
import { useEffect, useState } from 'react';
import { apiFetch } from '../api';
import socket from '../socket';

export default function ChatPage({ user }) {
  const [otherUserId, setOtherUserId] = useState('');
  const [content, setContent] = useState('');
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    socket.emit('user:online', user.id);

    socket.on('message:new', (message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on('notification:new', (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    return () => {
      socket.off('message:new');
      socket.off('notification:new');
    };
  }, [user.id]);

  async function loadConversation() {
    const data = await apiFetch(`/messages/${otherUserId}`);
    setMessages(data.messages || []);
  }

  async function sendMessage() {
    const data = await apiFetch('/messages', {
      method: 'POST',
      body: JSON.stringify({
        receiverId: otherUserId,
        content
      })
    });

    if (data.message) {
      setMessages((prev) => [...prev, data.message]);
      setContent('');
    }
  }

  async function loadNotifications() {
    const data = await apiFetch('/notifications');
    setNotifications(data.notifications || []);
  }

  return (
    <div style={{ display: 'flex', gap: 24 }}>
      <div>
        <h2>Chat</h2>
        <input
          placeholder="Recipient User ID"
          value={otherUserId}
          onChange={(e) => setOtherUserId(e.target.value)}
        />
        <button onClick={loadConversation}>Load Conversation</button>

        <div style={{ border: '1px solid #ccc', minHeight: 200, padding: 8 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <strong>{m.senderId === user.id ? 'You' : 'Them'}:</strong> {m.content}
            </div>
          ))}
        </div>

        <input
          placeholder="Type message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </div>

      <div>
        <h2>Notifications</h2>
        <button onClick={loadNotifications}>Refresh</button>
        {notifications.map((n) => (
          <div key={n.id} style={{ borderBottom: '1px solid #ddd', marginBottom: 8 }}>
            <div>{n.title}</div>
            <small>{n.body}</small>
          </div>
        ))}
      </div>
    </div>
  );
}
