# 7. Message routes with real-time notification support

## `routes/messages.js`

```js
const express = require("express");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const auth = require("../middleware/auth");

module.exports = function (io, onlineUsers) {
  const router = express.Router();

  // Send message
  router.post("/", auth, async (req, res) => {
    try {
      const { recipientId, text, mediaUrl, isPaidMessage, unlockCost } = req.body;

      const message = await Message.create({
        sender: req.user.id,
        recipient: recipientId,
        text,
        mediaUrl: mediaUrl || "",
        isPaidMessage: !!isPaidMessage,
        unlockCost: unlockCost || 0
      });

      const populated = await message.populate("sender", "username avatarUrl");

      const notification = await Notification.create({
        user: recipientId,
        type: "message",
        content: `New message from ${populated.sender.username}`,
        meta: { messageId: message._id, senderId: req.user.id }
      });

      const recipientSocketId = onlineUsers.get(recipientId);
      if (recipientSocketId) {
        io.to(recipientSocketId).emit("new_message", populated);
        io.to(recipientSocketId).emit("new_notification", notification);
      }

      res.json(populated);
    } catch (err) {
      res.status(500).json({ message: "Failed to send message", error: err.message });
    }
  });

  // Get conversation
  router.get("/:userId", auth, async (req, res) => {
    try {
      const currentUserId = req.user.id;
      const otherUserId = req.params.userId;

      const messages = await Message.find({
        $or: [
          { sender: currentUserId, recipient: otherUserId },
          { sender: otherUserId, recipient: currentUserId }
        ]
      })
        .sort({ createdAt: 1 })
        .populate("sender", "username avatarUrl")
        .populate("recipient", "username avatarUrl");

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch conversation", error: err.message });
    }
  });

  return router;
};
```

