# 9. Billing routes with Stripe

## `routes/billing.js`

```js
const express = require("express");
const Stripe = require("stripe");
const auth = require("../middleware/auth");
const User = require("../models/User");
const Purchase = require("../models/Purchase");
const Notification = require("../models/Notification");

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

// Buy coins
router.post("/create-payment-intent", auth, async (req, res) => {
  try {
    const { amount, type } = req.body;

    const paymentIntent = await stripe.paymentIntents.create({
      amount,
      currency: "usd",
      metadata: {
        userId: req.user.id,
        type
      }
    });

    const purchase = await Purchase.create({
      user: req.user.id,
      type: type || "coins",
      amount,
      stripePaymentIntentId: paymentIntent.id,
      status: "pending"
    });

    res.json({
      clientSecret: paymentIntent.client_secret,
      purchaseId: purchase._id
    });
  } catch (err) {
    res.status(500).json({ message: "Payment intent creation failed", error: err.message });
  }
});

// Confirm purchase manually for demo purposes
router.post("/confirm", auth, async (req, res) => {
  try {
    const { purchaseId } = req.body;

    const purchase = await Purchase.findOne({ _id: purchaseId, user: req.user.id });
    if (!purchase) return res.status(404).json({ message: "Purchase not found" });

    if (purchase.status === "completed") {
      return res.json({ message: "Already completed" });
    }

    purchase.status = "completed";
    await purchase.save();

    const user = await User.findById(req.user.id);

    if (purchase.type === "coins") {
      user.coins += Math.floor(purchase.amount / 100);
    } else if (purchase.type === "subscription") {
      user.isPremium = true;
    }

    await user.save();

    await Notification.create({
      user: req.user.id,
      type: "purchase",
      content: `Your ${purchase.type} purchase was successful.`,
      meta: { purchaseId: purchase._id }
    });

    res.json({
      message: "Purchase completed",
      user: {
        id: user._id,
        isPremium: user.isPremium,
        coins: user.coins
      }
    });
  } catch (err) {
    res.status(500).json({ message: "Purchase confirmation failed", error: err.message });
  }
});

module.exports = router;
