// src/services/paymentService.js
const Stripe = require('stripe');
const prisma = require('../db');

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

async function createCheckoutSession(userId, customerEmail, priceId) {
  const session = await stripe.checkout.sessions.create({
    mode: 'subscription',
    payment_method_types: ['card'],
    customer_email: customerEmail,
    line_items: [
      {
        price: priceId,
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/billing/success?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: { userId },
  });

  return session;
}

async function handleWebhook(event) {
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.metadata.userId;

    await prisma.subscription.create({
      data: {
        userId,
        provider: 'stripe',
        providerCustomerId: session.customer ? String(session.customer) : null,
        providerSubId: session.subscription ? String(session.subscription) : null,
        status: 'active',
        tier: 'premium',
      },
    });
  }
}

module.exports = {
  createCheckoutSession,
  handleWebhook,
};
