# 10. Messaging routes

```js
// src/routes/messages.js
const express = require('express');
const prisma = require('../db');
const requireAuth = require('../middleware/requireAuth');
const { createNotification } = require('../services/notificationService');

function buildMessageRouter(io, onlineUsers) {
  const router = express.Router();

  router.use(requireAuth);

  router.get('/inbox', async (req, res) => {
    const userId = req.user.sub;

    const messages = await prisma.message.findMany({
      where: {
        OR: [{ senderId: userId }, { receiverId: userId }],
      },
      orderBy: { createdAt: 'desc' },
      take: 100,
    });

    res.json(messages);
  });

  router.post('/', async (req, res) => {
    try {
      const senderId = req.user.sub;
      const { receiverId, content } = req.body;

      if (!receiverId || !content) {
        return res.status(400).json({ error: 'receiverId and content required' });
      }

      const message = await prisma.message.create({
        data: {
          senderId,
          receiverId,
          content,
        },
      });

      const notification = await createNotification(receiverId, 'new_message', {
        messageId: message.id,
        senderId,
        preview: content.slice(0, 100),
      });

      const receiverSocketId = onlineUsers.get(receiverId);
      if (receiverSocketId) {
        io.to(receiverSocketId).emit('message:new', message);
        io.to(receiverSocketId).emit('notification:new', notification);
      }

      res.json(message);
    } catch (err) {
      res.status(500).json({ error: 'Failed to send message', details: err.message });
    }
  });

  return router;
}

module.exports = buildMessageRouter;
```

