## `server/routes/messages.js`

```js
const express = require("express");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const auth = require("../middleware/auth");

const router = express.Router();

module.exports = (io, onlineUsers) => {
  router.post("/", auth, async (req, res) => {
    try {
      const { recipient, content } = req.body;

      const message = await Message.create({
        sender: req.user.id,
        recipient,
        content
      });

      const populatedMessage = await message.populate("sender recipient", "username email");

      const notification = await Notification.create({
        user: recipient,
        type: "message",
        message: `New message from ${populatedMessage.sender.username}`
      });

      const recipientSocketId = onlineUsers.get(recipient);
      if (recipientSocketId) {
        io.to(recipientSocketId).emit("new_message", populatedMessage);
        io.to(recipientSocketId).emit("new_notification", notification);
      }

      res.json(populatedMessage);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  router.get("/:userId", auth, async (req, res) => {
    try {
      const currentUserId = req.user.id;
      const otherUserId = req.params.userId;

      const messages = await Message.find({
        $or: [
          { sender: currentUserId, recipient: otherUserId },
          { sender: otherUserId, recipient: currentUserId }
        ]
      })
        .sort({ createdAt: 1 })
        .populate("sender recipient", "username email");

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  return router;
};
```

