# 7. Messaging Routes

## `server/routes/messages.js`

```js
import express from "express";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import auth from "../middleware/auth.js";

const router = express.Router();

export default function messageRoutes(io, onlineUsers) {
  router.post("/", auth, async (req, res) => {
    try {
      const { receiver, text, paidContent = false, unlockPrice = 0 } = req.body;

      const message = await Message.create({
        sender: req.user.id,
        receiver,
        text,
        paidContent,
        unlockPrice
      });

      const populatedMessage = await message.populate("sender receiver", "username email");

      const notification = await Notification.create({
        user: receiver,
        type: "message",
        content: `New message from ${req.user.username}`
      });

      const receiverSocketId = onlineUsers.get(receiver);
      if (receiverSocketId) {
        io.to(receiverSocketId).emit("newMessage", populatedMessage);
        io.to(receiverSocketId).emit("newNotification", notification);
      }

      res.json(populatedMessage);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  router.get("/:userId", auth, async (req, res) => {
    try {
      const myId = req.user.id;
      const otherId = req.params.userId;

      const messages = await Message.find({
        $or: [
          { sender: myId, receiver: otherId },
          { sender: otherId, receiver: myId }
        ]
      })
        .populate("sender receiver", "username email")
        .sort({ createdAt: 1 });

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  return router;
}
```

