# 9. Payments / Monetization Routes

## `server/routes/payments.js`

```js
import express from "express";
import Stripe from "stripe";
import auth from "../middleware/auth.js";
import User from "../models/User.js";
import Purchase from "../models/Purchase.js";
import Message from "../models/Message.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-payment-intent", auth, async (req, res) => {
  try {
    const { type, amount, messageId } = req.body;

    const paymentIntent = await stripe.paymentIntents.create({
      amount: amount * 100,
      currency: "usd",
      metadata: {
        userId: req.user.id,
        type,
        messageId: messageId || ""
      }
    });

    await Purchase.create({
      user: req.user.id,
      type,
      amount,
      stripePaymentIntentId: paymentIntent.id,
      metadata: { messageId }
    });

    res.json({ clientSecret: paymentIntent.client_secret });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/confirm-premium", auth, async (req, res) => {
  try {
    await User.findByIdAndUpdate(req.user.id, { isPremium: true });
    res.json({ message: "Premium activated" });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/buy-coins", auth, async (req, res) => {
  try {
    const { coins } = req.body;
    const user = await User.findById(req.user.id);
    user.coins += coins;
    await user.save();
    res.json({ message: "Coins added", coins: user.coins });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/unlock-message/:messageId", auth, async (req, res) => {
  try {
    const message = await Message.findById(req.params.messageId);
    const user = await User.findById(req.user.id);

    if (!message) return res.status(404).json({ message: "Message not found" });
    if (!message.paidContent) return res.status(400).json({ message: "Message is not locked" });

    if (user.coins < message.unlockPrice) {
      return res.status(400).json({ message: "Not enough coins" });
    }

    user.coins -= message.unlockPrice;
    await user.save();

    await Purchase.create({
      user: req.user.id,
      type: "unlock",
      amount: message.unlockPrice,
      metadata: { messageId: message._id }
    });

    res.json({ message: "Unlocked", content: message.text, remainingCoins: user.coins });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

export default router;
```

