import { useEffect } from "react";
import { apiRequest } from "../api";

export default function Notifications({ token, notifications, setNotifications }) {
  useEffect(() => {
    apiRequest("/notifications", "GET", null, token).then((data) => {
      if (Array.isArray(data)) setNotifications(data);
    });
  }, [token, setNotifications]);

  const markRead = async (id) => {
    const updated = await apiRequest(`/notifications/${id}/read`, "PATCH", {}, token);
    setNotifications((prev) =>
      prev.map((n) => (n._id === id ? updated : n))
    );
  };

  return (
    <div>
      <h2>Notifications</h2>
      {notifications.map((n) => (
        <div key={n._id} style={{ border: "1px solid #ccc", margin: 4, padding: 8 }}>
          <p>{n.content}</p>
          <p>Status: {n.read ? "Read" : "Unread"}</p>
          {!n.read && <button onClick={() => markRead(n._id)}>Mark as read</button>}
        </div>
      ))}
    </div>
  );
}
