    const data = await apiRequest(
      "/messages",
      "POST",
      {
        receiver: receiverId,
        text
      },
      token
    );

    if (data._id) {
      setMessages((prev) => [...prev, data]);
      setText("");
    } else {
      alert(data.message || "Failed to send");
    }
  };

  return (
    <div>
      <h2>Chat</h2>
      <input
        placeholder="Receiver User ID"
        value={receiverId}
        onChange={(e) => setReceiverId(e.target.value)}
      />
