            <strong>{m.sender?.username || m.senderId}:</strong>{" "}
            {m.paidContent ? `Locked message ($${m.unlockPrice})` : m.text}
          </div>
        ))}
      </div>

      <input
        placeholder="Type message"
        value={text}
        onChange={(e) => setText(e.target.value)}
