const express = require("express");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const auth = require("../middleware/auth");

const router = express.Router();

module.exports = (io, onlineUsers) => {
  router.post("/", auth, async (req, res) => {
    try {
      const { receiverId, text } = req.body;

      const message = await Message.create({
        sender: req.user.id,
        receiver: receiverId,
        text
      });

      const populatedMessage = await Message.findById(message._id)
        .populate("sender", "username email")
        .populate("receiver", "username email");

      const notification = await Notification.create({
        user: receiverId,
        type: "message",
        content: `New message from ${req.user.username}`,
        meta: { senderId: req.user.id, messageId: message._id }
      });

      const receiverSocketId = onlineUsers.get(receiverId);
      if (receiverSocketId) {
        io.to(receiverSocketId).emit("new_message", populatedMessage);
        io.to(receiverSocketId).emit("new_notification", notification);
      }

      res.status(201).json(populatedMessage);
    } catch (err) {
      res.status(500).json({ message: "Failed to send message", error: err.message });
    }
  });

  router.get("/:userId", auth, async (req, res) => {
    try {
      const otherUserId = req.params.userId;

      const messages = await Message.find({
        $or: [
          { sender: req.user.id, receiver: otherUserId },
          { sender: otherUserId, receiver: req.user.id }
        ]
      })
        .sort({ createdAt: 1 })
        .populate("sender", "username email")
        .populate("receiver", "username email");

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch messages", error: err.message });
    }
  });

  return router;
};
