## `server/routes/payments.js`

```js
const express = require("express");
const Stripe = require("stripe");
const auth = require("../middleware/auth");
const Purchase = require("../models/Purchase");
const User = require("../models/User");
const Notification = require("../models/Notification");

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

module.exports = (io, onlineUsers) => {
  router.post("/create-payment-intent", auth, async (req, res) => {
    try {
      const { amount, itemType } = req.body;

      const paymentIntent = await stripe.paymentIntents.create({
        amount,
        currency: "usd",
        metadata: {
          userId: req.user.id,
          itemType
        }
      });

      const purchase = await Purchase.create({
        user: req.user.id,
        stripePaymentIntentId: paymentIntent.id,
        amount,
        itemType,
        status: "pending"
      });

      res.json({
        clientSecret: paymentIntent.client_secret,
        purchaseId: purchase._id
      });
    } catch (err) {
      res.status(500).json({ message: "Payment creation failed", error: err.message });
    }
  });

  router.post("/confirm", auth, async (req, res) => {
    try {
      const { paymentIntentId } = req.body;

      const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId);

      if (paymentIntent.status !== "succeeded") {
        return res.status(400).json({ message: "Payment not completed" });
      }

      const purchase = await Purchase.findOneAndUpdate(
        { stripePaymentIntentId: paymentIntentId },
        { status: "completed" },
        { new: true }
      );

      if (!purchase) {
        return res.status(404).json({ message: "Purchase not found" });
      }

      const user = await User.findById(req.user.id);

      if (purchase.itemType === "premium") {
        user.isPremium = true;
      } else if (purchase.itemType === "coins") {
        user.balance += purchase.amount / 100;
      }

      await user.save();

      const notification = await Notification.create({
        user: req.user.id,
        type: "payment",
        content: `Payment successful for ${purchase.itemType}`,
        meta: { purchaseId: purchase._id }
      });

      const socketId = onlineUsers.get(req.user.id);
      if (socketId) {
        io.to(socketId).emit("new_notification", notification);
      }

      res.json({
        message: "Payment confirmed",
        purchase,
        user: {
          id: user._id,
          isPremium: user.isPremium,
          balance: user.balance
        }
      });
    } catch (err) {
      res.status(500).json({ message: "Payment confirmation failed", error: err.message });
    }
  });

  return router;
};
```

