import React, { useEffect, useRef, useState } from "react";
import API from "../api";
import { createSocket } from "../socket";

export default function Chat({ user }) {
  const [receiverId, setReceiverId] = useState("");
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [typing, setTyping] = useState("");
  const socketRef = useRef(null);

  useEffect(() => {
    const socket = createSocket();
    socketRef.current = socket;

    socket.on("connected", () => {
      console.log("Socket connected");
    });

    socket.on("new_message", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on("new_notification", (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    socket.on("typing", ({ username }) => {
      setTyping(`${username} is typing...`);
      setTimeout(() => setTyping(""), 1500);
    });

    fetchNotifications();

    return () => {
      socket.disconnect();
    };
  }, []);

  const fetchMessages = async () => {
    if (!receiverId) return;
    const res = await API.get(`/messages/${receiverId}`);
    setMessages(res.data);
  };

  const fetchNotifications = async () => {
    const res = await API.get("/notifications");
    setNotifications(res.data);
  };

  const sendMessage = async () => {
    if (!receiverId || !text.trim()) return;
    const res = await API.post("/messages", { receiverId, text });
    setMessages((prev) => [...prev, res.data]);
    setText("");
  };

  const handleTyping = (e) => {
    setText(e.target.value);
    if (receiverId && socketRef.current) {
      socketRef.current.emit("typing", { toUserId: receiverId });
    }
  };

  return (
    <div>
      <h2>Chat</h2>

      <input
        placeholder="Receiver User ID"
        value={receiverId}
        onChange={(e) => setReceiverId(e.target.value)}
        style={{ width: 300, marginBottom: 8 }}
      />
      <button onClick={fetchMessages} style={{ marginLeft: 8 }}>
        Load Chat
      </button>

      <div style={{ border: "1px solid #ccc", padding: 12, marginTop: 12, minHeight: 200 }}>
        {messages.map((msg) => (
          <div key={msg._id} style={{ marginBottom: 8 }}>
            <strong>{msg.sender.username}:</strong> {msg.text}
          </div>
        ))}
      </div>

      <p>{typing}</p>

      <input
        placeholder="Type a message"
        value={text}
        onChange={handleTyping}
        style={{ width: 300, marginTop: 8 }}
      />
      <button onClick={sendMessage} style={{ marginLeft: 8 }}>
        Send
      </button>

      <h3 style={{ marginTop: 24 }}>Notifications</h3>
      <ul>
        {notifications.map((n) => (
          <li key={n._id}>
            {n.content} {n.read ? "" : "(new)"}
          </li>
        ))}
      </ul>
    </div>
  );
}
