# 12) Payments routes

`server/src/routes/payments.js`

```js
import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import { prisma } from "../db.js";
import { stripe } from "../services/stripe.js";

export default function paymentRoutes(io) {
  const router = express.Router();

  router.post("/create-checkout-session", authMiddleware, async (req, res) => {
    try {
      const user = await prisma.user.findUnique({
        where: { id: req.user.id }
      });

      let customerId = user.stripeCustomerId;

      if (!customerId) {
        const customer = await stripe.customers.create({
          email: user.email,
          metadata: { userId: user.id }
        });

        customerId = customer.id;

        await prisma.user.update({
          where: { id: user.id },
          data: { stripeCustomerId: customerId }
        });
      }

      const session = await stripe.checkout.sessions.create({
        customer: customerId,
        payment_method_types: ["card"],
        mode: "subscription",
        line_items: [
          {
            price: process.env.STRIPE_PRICE_ID,
            quantity: 1
          }
        ],
        success_url: `${process.env.CLIENT_URL}/premium-success`,
        cancel_url: `${process.env.CLIENT_URL}/premium-cancel`
      });

      res.json({ url: session.url });
    } catch (err) {
      res.status(500).json({ error: "Failed to create checkout session", details: err.message });
    }
  });

  router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers["stripe-signature"],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const customerId = session.customer;

      const user = await prisma.user.findFirst({
        where: { stripeCustomerId: customerId }
      });

      if (user) {
        await prisma.user.update({
          where: { id: user.id },
          data: { isPremium: true }
        });

        await prisma.purchase.create({
          data: {
            userId: user.id,
            stripePaymentId: session.payment_intent || session.id,
            amount: session.amount_total || 0,
            currency: session.currency || "usd",
            status: "completed"
          }
        });

        io.to(`user:${user.id}`).emit("premium:activated", {
          isPremium: true
        });

        io.to(`user:${user.id}`).emit("notification:new", {
          type: "payment",
          title: "Premium activated",
          body: "Your premium subscription is now active."
        });
      }
    }

    res.json({ received: true });
  });

  return router;
}
```

