# 13) Socket handling

`server/src/sockets/chat.js`

```js
import jwt from "jsonwebtoken";

export function registerChatHandlers(io) {
  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error("Unauthorized"));

      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.user.id;

    socket.join(`user:${userId}`);

    socket.on("message:send", ({ receiverId, content }) => {
      const message = {
        id: crypto.randomUUID(),
        senderId: userId,
        receiverId,
        content,
        createdAt: new Date().toISOString()
      };

      io.to(`user:${receiverId}`).emit("message:new", message);
      io.to(`user:${userId}`).emit("message:sent", message);
    });

    socket.on("notification:read", (notificationId) => {
      io.to(`user:${userId}`).emit("notification:read:ack", { notificationId });
    });

    socket.on("disconnect", () => {
      console.log(`User ${userId} disconnected`);
    });
  });
}
```

