import { useEffect, useState } from "react";
import { apiRequest } from "../api";
import { getSocket } from "../socket";

export default function Chat({ selectedUser }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!selectedUser) return;

    apiRequest(`/messages/conversation/${selectedUser.id}`).then(setMessages);
  }, [selectedUser]);

  useEffect(() => {
    const socket = getSocket();
    if (!socket) return;

    const onNewMessage = (msg) => {
      if (
        msg.senderId === selectedUser?.id ||
        msg.receiverId === selectedUser?.id
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    socket.on("message:new", onNewMessage);
    socket.on("message:sent", onNewMessage);

    return () => {
      socket.off("message:new", onNewMessage);
      socket.off("message:sent", onNewMessage);
    };
  }, [selectedUser]);

  const sendMessage = async () => {
    if (!content.trim() || !selectedUser) return;

    const msg = await apiRequest("/messages", "POST", {
      receiverId: selectedUser.id,
      content
    });

    setMessages((prev) => [...prev, msg]);
    setContent("");
  };

  return (
    <div>
      <h3>Chat with {selectedUser?.username}</h3>
      <div style={{ border: "1px solid #ccc", height: 300, overflowY: "auto", padding: 8 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.senderId === selectedUser?.id ? selectedUser.username : "You"}:</strong>{" "}
            {m.content}
          </div>
        ))}
      </div>
      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message"
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
