# 22) A better real-time message persistence version

If you want the socket itself to save messages in DB, replace the socket send handler with this:

```js
import jwt from "jsonwebtoken";
import { prisma } from "../db.js";

export function registerChatHandlers(io) {
  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error("Unauthorized"));
      socket.user = jwt.verify(token, process.env.JWT_SECRET);
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.user.id;
    socket.join(`user:${userId}`);

    socket.on("message:send", async ({ receiverId, content }) => {
      try {
        const message = await prisma.message.create({
          data: {
            senderId: userId,
            receiverId,
            content
          }
        });

        io.to(`user:${receiverId}`).emit("message:new", message);
        io.to(`user:${userId}`).emit("message:sent", message);
      } catch (err) {
        socket.emit("error:message", { error: "Failed to send message" });
      }
    });
  });
}
