```js
import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import Conversation from "../models/Conversation.js";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";

const router = express.Router();

router.post("/send", authMiddleware, async (req, res) => {
  try {
    const { receiverId, text } = req.body;
    const senderId = req.user._id;

    let conversation = await Conversation.findOne({
      participants: { $all: [senderId, receiverId] }
    });

    if (!conversation) {
      conversation = await Conversation.create({
        participants: [senderId, receiverId]
      });
    }

    const message = await Message.create({
      conversation: conversation._id,
      sender: senderId,
      receiver: receiverId,
      text
    });

    conversation.lastMessage = message._id;
    await conversation.save();

    const notification = await Notification.create({
      user: receiverId,
      type: "message",
      title: "New Message",
      body: `${req.user.username} sent you a message`,
      meta: {
        senderId,
        conversationId: conversation._id,
        messageId: message._id
      }
    });

    const io = req.app.get("io");
    io.to(receiverId.toString()).emit("new_message", message);
    io.to(receiverId.toString()).emit("new_notification", notification);
    io.to(senderId.toString()).emit("message_sent", message);

    res.status(201).json({ conversation, message });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.get("/conversation/:userId", authMiddleware, async (req, res) => {
  try {
    const otherUserId = req.params.userId;
    const myId = req.user._id;

    const conversation = await Conversation.findOne({
      participants: { $all: [myId, otherUserId] }
    });

    if (!conversation) return res.json([]);

    const messages = await Message.find({
      conversation: conversation._id
    }).sort({ createdAt: 1 });

    res.json(messages);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

export default router;
