import express from "express";
import Stripe from "stripe";
import { authMiddleware } from "../middleware/auth.js";
import User from "../models/User.js";
import Purchase from "../models/Purchase.js";
import Notification from "../models/Notification.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      customer_email: req.user.email,
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Upgrade"
            },
            unit_amount: 999
          },
          quantity: 1
        }
      ],
      metadata: {
        userId: req.user._id.toString(),
        productType: "premium_upgrade"
      },
      success_url: `${process.env.CLIENT_URL}/premium?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/premium?canceled=true`
    });

    res.json({ url: session.url });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.post(
  "/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers["stripe-signature"],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      const user = await User.findByIdAndUpdate(
        userId,
        { isPremium: true, stripeCustomerId: session.customer || null },
        { new: true }
      );

      await Purchase.findOneAndUpdate(
        { stripeSessionId: session.id },
        {
          user: userId,
          stripeSessionId: session.id,
          amountTotal: session.amount_total || 0,
          currency: session.currency || "usd",
          status: session.payment_status,
          productType: session.metadata.productType
        },
        { upsert: true, new: true }
      );

      const notification = await Notification.create({
        user: userId,
        type: "payment",
        title: "Premium Activated",
        body: "Your premium upgrade is now active.",
        meta: { sessionId: session.id }
      });

      const io = req.app.get("io");
      io.to(userId.toString()).emit("premium_activated", {
        isPremium: true
      });
      io.to(userId.toString()).emit("new_notification", notification);
    }

    res.json({ received: true });
  }
);

export default router;
