```jsx
import React, { useEffect, useState } from "react";
import API from "../api";
import { connectSocket, getSocket } from "../socket";
import ConversationList from "../components/ConversationList";
import MessageList from "../components/MessageList";
import MessageInput from "../components/MessageInput";
import NotificationBell from "../components/NotificationBell";

export default function Chat() {
  const currentUser = JSON.parse(localStorage.getItem("user"));
  const token = localStorage.getItem("token");

  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [typingUser, setTypingUser] = useState("");

  useEffect(() => {
    const init = async () => {
      const usersRes = await API.get("/users");
      const notifRes = await API.get("/notifications");
      setUsers(usersRes.data);
      setNotifications(notifRes.data);
    };

    init();

    const socket = connectSocket(token);

    socket.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.sender === selectedUser._id || message.receiver === selectedUser._id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("message_sent", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on("new_notification", (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    socket.on("typing", ({ from }) => {
      const user = users.find((u) => u._id === from);
      setTypingUser(user?.username || "Someone");
    });

    socket.on("stop_typing", () => {
      setTypingUser("");
    });

    socket.on("premium_activated", () => {
      const updated = { ...currentUser, isPremium: true };
      localStorage.setItem("user", JSON.stringify(updated));
      alert("Premium activated!");
    });

    return () => socket.disconnect();
  }, []);

  const loadConversation = async (user) => {
    setSelectedUser(user);
    const { data } = await API.get(`/messages/conversation/${user._id}`);
    setMessages(data);
  };

  const sendMessage = async (text) => {
    if (!selectedUser) return;
    await API.post("/messages/send", {
      receiverId: selectedUser._id,
      text
    });
  };

  const handleTyping = () => {
    if (!selectedUser) return;
    getSocket()?.emit("typing", { to: selectedUser._id });
  };

  const handleStopTyping = () => {
    if (!selectedUser) return;
    getSocket()?.emit("stop_typing", { to: selectedUser._id });
  };

  return (
    <div>
      <NotificationBell notifications={notifications} />
      <div style={{ display: "flex" }}>
        <ConversationList
          users={users}
          selectedUser={selectedUser}
          onSelect={loadConversation}
        />
        <div style={{ flex: 1 }}>
          <h3 style={{ padding: 12 }}>
            {selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}
          </h3>
          <MessageList messages={messages} currentUser={currentUser} />
          {typingUser && <div style={{ paddingLeft: 12 }}>{typingUser} is typing...</div>}
          <MessageInput
            onSend={sendMessage}
            onTyping={handleTyping}
            onStopTyping={handleStopTyping}
          />
        </div>
      </div>
    </div>
  );
}
