# 14. React Chat Component

## `client/src/components/Chat.jsx`

```jsx
import React, { useEffect, useState } from 'react';
import { io } from 'socket.io-client';
import { getMessages, sendMessage } from '../api';

const socket = io('http://localhost:5000');

export default function Chat({ token, currentUser, otherUserId }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState('');

  useEffect(() => {
    socket.emit('join', currentUser.id);

    getMessages(token, otherUserId).then((data) => {
      setMessages(data.messages || []);
    });

    socket.on('new_message', (message) => {
      if (
        message.senderId === otherUserId ||
        message.receiverId === otherUserId
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.off('new_message');
    };
  }, [token, currentUser.id, otherUserId]);

  const handleSend = async () => {
    if (!content.trim()) return;

    const data = await sendMessage(token, {
      receiverId: otherUserId,
      content
    });

    if (data.message) {
      setMessages((prev) => [...prev, data.message]);
      setContent('');
    }
  };

  return (
    <div>
      <h2>Chat</h2>
      <div style={{ border: '1px solid #ccc', height: 300, overflowY: 'auto' }}>
        {messages.map((msg) => (
          <div key={msg.id}>
            <strong>{msg.senderId === currentUser.id ? 'Me' : 'Them'}:</strong> {msg.content}
          </div>
        ))}
      </div>
      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message"
      />
      <button onClick={handleSend}>Send</button>
    </div>
  );
}
```

