## `client/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";
import API from "../api";
import NotificationBell from "../components/NotificationBell";

const socket = io("http://localhost:5000");

export default function Chat() {
  const user = JSON.parse(localStorage.getItem("user"));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [conversation, setConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [liveNotification, setLiveNotification] = useState(null);

  useEffect(() => {
    socket.emit("join", user._id);
    fetchUsers();

    socket.on("newMessage", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("newNotification", (notification) => {
      setLiveNotification(notification);
    });

    return () => {
      socket.off("newMessage");
      socket.off("newNotification");
    };
  }, []);

  const fetchUsers = async () => {
    const res = await API.get("/users");
    setUsers(res.data.filter((u) => u._id !== user._id));
  };

  const openConversation = async (otherUser) => {
    setSelectedUser(otherUser);
    const convoRes = await API.post("/messages/conversation", {
      participantId: otherUser._id
    });
    setConversation(convoRes.data);

    const msgRes = await API.get(`/messages/${convoRes.data._id}`);
    setMessages(msgRes.data);
  };

  const sendMessage = async () => {
    if (!text || !conversation || !selectedUser) return;

    const res = await API.post("/messages", {
      conversationId: conversation._id,
      text,
      recipientId: selectedUser._id
    });

    setMessages((prev) => [...prev, res.data]);
    setText("");
  };

  const upgradeToPremium = async () => {
    const res = await API.post("/payments/create-checkout-session");
    window.location.href = res.data.url;
  };

  const confirmPremium = async () => {
    await API.post("/payments/confirm-premium");
    alert("Premium activated");
  };

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Users</h3>
        {users.map((u) => (
          <div key={u._id}>
            <button onClick={() => openConversation(u)}>
              {u.username} {u.isPremium ? "⭐" : ""}
            </button>
          </div>
        ))}

        <hr />
        <NotificationBell liveNotification={liveNotification} />
        <hr />
        <button onClick={upgradeToPremium}>Buy Premium</button>
        <button onClick={confirmPremium}>Confirm Premium</button>
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat with {selectedUser?.username || "..."}</h3>
        <div
          style={{
            border: "1px solid #ccc",
            minHeight: 300,
            padding: 10,
            marginBottom: 10
          }}
        >
          {messages.map((m) => (
            <div key={m._id}>
              <b>{m.sender === user._id ? "Me" : selectedUser?.username}:</b>{" "}
              {m.text}
            </div>
          ))}
        </div>

        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Type message..."
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
