import { Router } from "express";
import express from "express";
import Stripe from "stripe";
import { requireAuth, AuthedRequest } from "../middleware/auth";
import { createCheckoutSession } from "../services/billing";
import { prisma } from "../prisma";

const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

router.post("/checkout", requireAuth, async (req: AuthedRequest, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user!.id }
  });

  if (!user) return res.status(404).json({ error: "User not found" });

  const url = await createCheckoutSession(user.id, user.email);
  return res.json({ url });
});

export const stripeWebhookHandler = [
  express.raw({ type: "application/json" }),
  async (req: any, res: any) => {
    const sig = req.headers["stripe-signature"];

    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET!
      );
    } catch (err: any) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object as Stripe.Checkout.Session;

      if (session.customer && session.subscription) {
        await prisma.subscription.updateMany({
          where: {
            provider: "stripe",
            providerCustomerId: String(session.customer)
          },
          data: {
            providerSubId: String(session.subscription),
            status: "active"
          }
        });
      }
    }

    if (event.type === "customer.subscription.deleted") {
      const subscription = event.data.object as Stripe.Subscription;
      await prisma.subscription.updateMany({
        where: { providerSubId: subscription.id },
        data: { status: "canceled" }
      });
    }

    res.json({ received: true });
  }
];

export default router;
