```ts
import { Router } from "express";
import { z } from "zod";
import { prisma } from "../prisma";
import { requireAuth, AuthedRequest } from "../middleware/auth";

const router = Router();

const sendSchema = z.object({
  receiverId: z.string().min(1),
  body: z.string().min(1).max(2000)
});

router.get("/thread/:userId", requireAuth, async (req: AuthedRequest, res) => {
  const otherUserId = req.params.userId;
  const me = req.user!.id;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: otherUserId },
        { senderId: otherUserId, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  return res.json(messages);
});

router.post("/", requireAuth, async (req: AuthedRequest, res) => {
  try {
    const data = sendSchema.parse(req.body);

    const message = await prisma.message.create({
      data: {
        senderId: req.user!.id,
        receiverId: data.receiverId,
        body: data.body,
        deliveredAt: new Date()
      }
    });

    return res.json(message);
  } catch (err: any) {
    return res.status(400).json({ error: err.message || "Invalid request" });
  }
});

router.post("/read/:messageId", requireAuth, async (req: AuthedRequest, res) => {
  const message = await prisma.message.findUnique({
    where: { id: req.params.messageId }
  });

  if (!message || message.receiverId !== req.user!.id) {
    return res.status(404).json({ error: "Message not found" });
  }

  const updated = await prisma.message.update({
    where: { id: message.id },
    data: { readAt: new Date() }
  });

  return res.json(updated);
});

export default router;
```

