# 12. Socket.IO chat

`server/src/sockets/chat.ts`

```ts
import { Server, Socket } from "socket.io";
import jwt from "jsonwebtoken";
import { prisma } from "../prisma";
import { sendPushNotification } from "../services/notifications";

type JwtPayload = {
  id: string;
  email: string;
};

export function registerChatHandlers(io: Server) {
  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET!) as JwtPayload;
      (socket as any).user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket: Socket) => {
    const user = (socket as any).user as JwtPayload;
    socket.join(`user:${user.id}`);

    socket.on("message:send", async (payload, ack) => {
      try {
        const { receiverId, body } = payload || {};

        if (!receiverId || !body || typeof body !== "string" || body.length > 2000) {
          return ack?.({ error: "Invalid payload" });
        }

        const message = await prisma.message.create({
          data: {
            senderId: user.id,
            receiverId,
            body,
            deliveredAt: new Date()
          }
        });

        io.to(`user:${receiverId}`).emit("message:new", message);
        io.to(`user:${user.id}`).emit("message:new", message);

        await sendPushNotification({
          userId: receiverId,
          title: "New message",
          body: "You received a new message",
          data: { messageId: message.id }
        });

        ack?.({ ok: true, message });
      } catch {
        ack?.({ error: "Failed to send message" });
      }
    });

    socket.on("message:read", async ({ messageId }, ack) => {
      try {
        const message = await prisma.message.findUnique({ where: { id: messageId } });
        if (!message || message.receiverId !== user.id) {
          return ack?.({ error: "Not found" });
        }

        const updated = await prisma.message.update({
          where: { id: messageId },
          data: { readAt: new Date() }
        });

        io.to(`user:${message.senderId}`).emit("message:read", updated);
        io.to(`user:${message.receiverId}`).emit("message:read", updated);

        ack?.({ ok: true, message: updated });
      } catch {
        ack?.({ error: "Failed to update read status" });
      }
    });
  });
}
```

