# 16. Chat component

`client/src/Chat.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import { API_URL, api, getToken } from "./api";

type Message = {
  id: string;
  senderId: string;
  receiverId: string;
  body: string;
  createdAt: string;
  readAt?: string | null;
};

export default function Chat() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUserId, setOtherUserId] = useState("");
  const [body, setBody] = useState("");

  const socket: Socket | null = useMemo(() => {
    const token = getToken();
    if (!token) return null;
    return io(API_URL, { auth: { token } });
  }, []);

  useEffect(() => {
    if (!socket) return;

    socket.on("message:new", (msg: Message) => {
      setMessages(prev => [...prev, msg]);
    });

    socket.on("message:read", (updated: Message) => {
      setMessages(prev => prev.map(m => (m.id === updated.id ? updated : m)));
    });

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  async function loadThread() {
    const data = await api(`/messages/thread/${otherUserId}`);
    setMessages(data);
  }

  function sendMessage() {
    if (!socket) return;

    socket.emit("message:send", { receiverId: otherUserId, body }, (resp: any) => {
      if (!resp?.error) setBody("");
    });
  }

  return (
    <div>
      <h2>Chat</h2>
      <input
        placeholder="Other user ID"
        value={otherUserId}
        onChange={e => setOtherUserId(e.target.value)}
      />
      <button onClick={loadThread}>Load Thread</button>

      <div style={{ border: "1px solid #ccc", padding: 12, margin: "12px 0" }}>
        {messages.map(m => (
          <div key={m.id}>
            <strong>{m.senderId}</strong>: {m.body} {m.readAt ? "✓✓" : "✓"}
          </div>
        ))}
      </div>

      <input
        placeholder="Type a message"
        value={body}
        onChange={e => setBody(e.target.value)}
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
```

