import React, { useEffect, useState } from "react";
import { apiRequest } from "../api";
import { socket } from "../socket";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ token, user }) {
  const [recipientId, setRecipientId] = useState("");
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    socket.emit("register_user", user.id);

    socket.on("new_message", (message) => {
      if (
        message.sender === recipientId ||
        message.recipient === recipientId
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.off("new_message");
    };
  }, [recipientId, user.id]);

  const loadMessages = async () => {
    if (!recipientId) return;
    const data = await apiRequest(`/messages/${recipientId}`, "GET", null, token);
    setMessages(data);
  };

  const sendMessage = async () => {
    const message = await apiRequest(
      "/messages",
      "POST",
      { recipientId, text },
      token
    );
    setMessages((prev) => [...prev, message]);
    setText("");
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Welcome, {user.username}</h1>
      <a href="/premium">Go Premium</a>
      <NotificationBell token={token} />

      <div style={{ marginTop: 20 }}>
        <input
          placeholder="Recipient user ID"
          value={recipientId}
          onChange={(e) => setRecipientId(e.target.value)}
        />
        <button onClick={loadMessages}>Load Chat</button>
      </div>

      <div style={{ border: "1px solid #ccc", padding: 10, marginTop: 20 }}>
        {messages.map((m) => (
          <div key={m._id}>
            <strong>{m.sender === user.id ? "Me" : "Them"}:</strong> {m.text}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 20 }}>
        <input
          placeholder="Type a message"
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
