const express = require("express");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const auth = require("../middleware/auth");

module.exports = function(io, onlineUsers) {
  const router = express.Router();

  router.post("/", auth, async (req, res) => {
    try {
      const { recipientId, text } = req.body;

      const message = await Message.create({
        sender: req.user.id,
        recipient: recipientId,
        text
      });

      const notification = await Notification.create({
        user: recipientId,
        type: "message",
        content: `New message from ${req.user.username}`,
        meta: { senderId: req.user.id, messageId: message._id }
      });

      const recipientSocketId = onlineUsers.get(recipientId);
      if (recipientSocketId) {
        io.to(recipientSocketId).emit("message:new", message);
        io.to(recipientSocketId).emit("notification:new", notification);
      }

      res.json(message);
    } catch (err) {
      res.status(500).json({ message: "Failed to send message", error: err.message });
    }
  });

  router.get("/:userId", auth, async (req, res) => {
    try {
      const otherUserId = req.params.userId;

      const messages = await Message.find({
        $or: [
          { sender: req.user.id, recipient: otherUserId },
          { sender: otherUserId, recipient: req.user.id }
        ]
      }).sort({ createdAt: 1 });

      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch messages", error: err.message });
    }
  });

  return router;
};
```

