```js
import React, { useEffect, useState } from "react";
import API from "./api";
import socket from "./socket";

function App() {
  const [user, setUser] = useState(null);
  const [recipientId, setRecipientId] = useState("");
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const savedUser = localStorage.getItem("user");
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setUser(parsed);
      socket.emit("user:online", parsed._id);
      loadNotifications();
    }

    socket.on("message:new", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on("notification:new", (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    socket.on("premium:updated", ({ isPremium }) => {
      setUser((prev) => {
        const updated = { ...prev, isPremium };
        localStorage.setItem("user", JSON.stringify(updated));
        return updated;
      });
    });

    return () => {
      socket.off("message:new");
      socket.off("notification:new");
      socket.off("premium:updated");
    };
  }, []);

  const register = async () => {
    const username = prompt("Username");
    const email = prompt("Email");
    const password = prompt("Password");
    const res = await API.post("/auth/register", { username, email, password });
    localStorage.setItem("token", res.data.token);
    localStorage.setItem("user", JSON.stringify(res.data.user));
    setUser(res.data.user);
    socket.emit("user:online", res.data.user._id);
  };

  const login = async () => {
    const email = prompt("Email");
    const password = prompt("Password");
    const res = await API.post("/auth/login", { email, password });
    localStorage.setItem("token", res.data.token);
    localStorage.setItem("user", JSON.stringify(res.data.user));
    setUser(res.data.user);
    socket.emit("user:online", res.data.user._id);
    loadNotifications();
  };

  const loadMessages = async () => {
    if (!recipientId) return;
    const res = await API.get(`/messages/${recipientId}`);
    setMessages(res.data);
  };

  const sendMessage = async () => {
    const res = await API.post("/messages", { recipientId, text });
    setMessages((prev) => [...prev, res.data]);
    setText("");
  };

  const loadNotifications = async () => {
    const res = await API.get("/notifications");
    setNotifications(res.data);
  };

  const upgradePremium = async () => {
    const res = await API.post("/payments/create-checkout-session");
    window.location.href = res.data.url;
  };

  return (
    <div style={{ padding: 20, fontFamily: "Arial" }}>
      <h1>Social Messaging App</h1>

      {!user ? (
        <div>
          <button onClick={register}>Register</button>
          <button onClick={login}>Login</button>
        </div>
      ) : (
        <>
          <p>
            Logged in as <b>{user.username}</b> {user.isPremium ? "⭐ Premium" : ""}
          </p>

          {!user.isPremium && (
            <button onClick={upgradePremium}>Upgrade to Premium ($9.99)</button>
          )}

          <hr />

          <h2>Messages</h2>
          <input
            placeholder="Recipient User ID"
            value={recipientId}
            onChange={(e) => setRecipientId(e.target.value)}
          />
          <button onClick={loadMessages}>Load Chat</button>

          <div style={{ border: "1px solid #ccc", padding: 10, marginTop: 10, minHeight: 200 }}>
            {messages.map((m) => (
              <div key={m._id}>
                <b>{m.sender === user._id ? "Me" : "Them"}:</b> {m.text}
              </div>
            ))}
          </div>

          <input
            placeholder="Type message..."
            value={text}
            onChange={(e) => setText(e.target.value)}
            style={{ width: 300 }}
          />
          <button onClick={sendMessage}>Send</button>

          <hr />

          <h2>Notifications</h2>
          <button onClick={loadNotifications}>Refresh Notifications</button>
          <ul>
            {notifications.map((n) => (
              <li key={n._id}>
                {n.content} {n.read ? "" : "• unread"}
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

export default App;
