```tsx
"use client";

import { useEffect, useState } from "react";
import { apiFetch } from "../lib/api";
import { getSocket } from "../lib/socket";

export default function ChatWindow({ selectedUser }: { selectedUser: any }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!selectedUser) return;

    apiFetch(`/messages/${selectedUser.id}`).then(setMessages);

    const socket = getSocket();

    socket.on("message:new", (message) => {
      if (
        message.senderId === selectedUser.id ||
        message.receiverId === selectedUser.id
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.off("message:new");
    };
  }, [selectedUser]);

  const sendMessage = async () => {
    if (!content.trim()) return;

    const message = await apiFetch("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content
      })
    });

    const socket = getSocket();
    socket.emit("message:send", message);

    setMessages((prev) => [...prev, message]);
    setContent("");
  };

  if (!selectedUser) {
    return <div>Select a user to start chatting.</div>;
  }

  return (
    <div style={{ border: "1px solid #ccc", padding: 12, flex: 1 }}>
      <h3>Chat with {selectedUser.username}</h3>
      <div style={{ minHeight: 300, marginBottom: 12 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.senderId === selectedUser.id ? selectedUser.username : "You"}:</strong> {m.content}
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <input
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message"
          style={{ flex: 1 }}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
