router.post("/create-checkout-session", authMiddleware, async (req: AuthRequest, res) => {
  const userId = req.user!.userId;
  const { priceType } = req.body;

  let unitAmount = 999;
  let name = "Premium Subscription";

  if (priceType === "message_unlock") {
    unitAmount = 299;
    name = "Paid Message Unlock";
  }

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ["card"],
    mode: "payment",
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name },
          unit_amount: unitAmount,
        },
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/premium?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/premium?canceled=1`,
    metadata: {
      userId,
      priceType,
    },
  });

  res.json({ url: session.url });
});

router.post("/webhook", async (req, res) => {
  // Initial simplified webhook example.
  // In production use raw body verification with stripe.webhooks.constructEvent.
  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const priceType = session.metadata.priceType;

    if (priceType === "subscription") {
      await prisma.user.update({
        where: { id: userId },
        data: { subscriptionStatus: "PREMIUM" },
      });

      await prisma.purchase.create({
        data: {
          userId,
          type: "SUBSCRIPTION",
          amount: session.amount_total || 0,
          stripePaymentId: session.payment_intent,
        },
      });

      await createNotification({
        userId,
        type: "PAYMENT",
        title: "Premium activated",
        body: "Your premium subscription is now active.",
      });
    } else {
      await prisma.purchase.create({
        data: {
          userId,
          type: "MESSAGE_UNLOCK",
          amount: session.amount_total || 0,
          stripePaymentId: session.payment_intent,
        },
      });

      await createNotification({
        userId,
        type: "PAYMENT",
        title: "Purchase successful",
        body: "Your message unlock purchase was successful.",
      });
    }
  }

  res.json({ received: true });
