"use client";

import { useEffect, useState } from "react";
import { apiFetch } from "../lib/api";
import { getSocket } from "../lib/socket";

export default function ChatWindow({ selectedUser }: { selectedUser: any }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!selectedUser) return;

    apiFetch(`/messages/${selectedUser.id}`)
      .then(setMessages)
      .catch(console.error);
  }, [selectedUser]);

  useEffect(() => {
    const socket = getSocket();

    const onMessage = (message: any) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on("message:new", onMessage);

    return () => {
      socket.off("message:new", onMessage);
    };
  }, [selectedUser]);

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;

    const message = await apiFetch("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content,
      }),
    });

    setMessages((prev) => [...prev, message]);
    setContent("");
  }

  if (!selectedUser) return <div>Select a user to chat</div>;

  return (
    <div>
      <h3>Chat with {selectedUser.username}</h3>
      <div style={{ height: 300, overflowY: "auto", border: "1px solid #ddd", padding: 8 }}>
        {messages.map((m) => (
          <div key={m.id} style={{ marginBottom: 8 }}>
            <strong>{m.senderId === selectedUser.id ? selectedUser.username : "You"}:</strong>{" "}
            {m.content}
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
        <input
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message"
          style={{ flex: 1 }}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
