## `server/routes/monetization.js`

```js
const express = require('express');
const Stripe = require('stripe');
const User = require('../models/User');
const Purchase = require('../models/Purchase');
const Notification = require('../models/Notification');

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

router.post('/create-payment-intent', async (req, res) => {
  try {
    const { itemType } = req.body;

    let amount = 0;
    let creditsAdded = 0;

    if (itemType === 'premium') {
      amount = 999;
    } else if (itemType === 'credits') {
      amount = 499;
      creditsAdded = 50;
    } else {
      return res.status(400).json({ message: 'Invalid item type' });
    }

    const paymentIntent = await stripe.paymentIntents.create({
      amount,
      currency: 'usd',
      metadata: {
        userId: req.user.id,
        itemType,
        creditsAdded: creditsAdded.toString()
      }
    });

    res.json({ clientSecret: paymentIntent.client_secret });
  } catch (err) {
    res.status(500).json({ message: 'Stripe error', error: err.message });
  }
});

router.post('/confirm', async (req, res) => {
  try {
    const { paymentIntentId } = req.body;

    const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId);

    if (paymentIntent.status !== 'succeeded') {
      return res.status(400).json({ message: 'Payment not completed' });
    }

    const userId = paymentIntent.metadata.userId;
    const itemType = paymentIntent.metadata.itemType;
    const creditsAdded = parseInt(paymentIntent.metadata.creditsAdded || '0', 10);

    const existingPurchase = await Purchase.findOne({
      stripePaymentIntentId: paymentIntent.id
    });

    if (existingPurchase) {
      return res.json({ message: 'Purchase already processed' });
    }

    let user;
    if (itemType === 'premium') {
      user = await User.findByIdAndUpdate(
        userId,
        { isPremium: true },
        { new: true }
      );
    } else if (itemType === 'credits') {
      user = await User.findByIdAndUpdate(
        userId,
        { $inc: { credits: creditsAdded } },
        { new: true }
      );
    }

    await Purchase.create({
      user: userId,
      stripePaymentIntentId: paymentIntent.id,
      amount: paymentIntent.amount,
      currency: paymentIntent.currency,
      itemType,
      creditsAdded,
      status: paymentIntent.status
    });

    await Notification.create({
      user: userId,
      type: 'purchase',
      message:
        itemType === 'premium'
          ? 'Your premium subscription is now active.'
          : `${creditsAdded} credits added to your account.`
    });

    res.json({
      message: 'Purchase confirmed',
      user: {
        id: user._id,
        username: user.username,
        email: user.email,
        isPremium: user.isPremium,
        credits: user.credits
      }
    });
  } catch (err) {
    res.status(500).json({ message: 'Confirmation error', error: err.message });
  }
});

module.exports = router;
```

