import React, { useEffect, useState } from 'react';
import Login from './pages/Login';
import Register from './pages/Register';
import Chat from './pages/Chat';
import Premium from './pages/Premium';

function App() {
  const [page, setPage] = useState('login');
  const [user, setUser] = useState(() => {
    const saved = localStorage.getItem('user');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    if (user) {
      setPage('chat');
    }
  }, [user]);

  const handleAuth = (data) => {
    localStorage.setItem('token', data.token);
    localStorage.setItem('user', JSON.stringify(data.user));
    setUser(data.user);
    setPage('chat');
  };

  const logout = () => {
    localStorage.clear();
    setUser(null);
    setPage('login');
  };

  if (!user && page === 'register') {
    return <Register onAuth={handleAuth} goLogin={() => setPage('login')} />;
  }

  if (!user) {
    return <Login onAuth={handleAuth} goRegister={() => setPage('register')} />;
  }

  if (page === 'premium') {
    return <Premium user={user} setUser={setUser} goBack={() => setPage('chat')} />;
  }

  return <Chat user={user} logout={logout} goPremium={() => setPage('premium')} />;
}

export default App;
