import React, { useEffect, useState } from 'react';
import API from '../api';
import socket from '../socket';
import NotificationBell from '../components/NotificationBell';

export default function Chat({ user, logout, goPremium }) {
  const [recipientId, setRecipientId] = useState('');
  const [content, setContent] = useState('');
  const [chatUserId, setChatUserId] = useState('');
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    socket.emit('register_user', user.id);

    socket.on('new_message', (message) => {
      setMessages((prev) => [...prev, message]);
    });

    return () => {
      socket.off('new_message');
    };
  }, [user.id]);

  const loadMessages = async () => {
    if (!chatUserId) return;
    const res = await API.get(`/messages/${chatUserId}`);
    setMessages(res.data);
  };

  const sendMessage = async () => {
    if (!recipientId || !content) return;
    const res = await API.post('/messages', { recipientId, content });
    setMessages((prev) => [...prev, res.data]);
    setContent('');
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>Welcome, {user.username}</h2>
      <p>
        Premium: {user.isPremium ? 'Yes' : 'No'} | Credits: {user.credits}
      </p>
      <button onClick={logout}>Logout</button>
      <button onClick={goPremium}>Monetization</button>

      <NotificationBell />

      <hr />

      <div>
        <h3>Open Conversation</h3>
        <input
          placeholder="User ID to open chat"
          value={chatUserId}
          onChange={(e) => setChatUserId(e.target.value)}
        />
        <button onClick={loadMessages}>Load Messages</button>
      </div>

      <div>
        <h3>Send Message</h3>
        <input
          placeholder="Recipient User ID"
          value={recipientId}
          onChange={(e) => setRecipientId(e.target.value)}
        />
        <br />
        <textarea
          placeholder="Type message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <br />
        <button onClick={sendMessage}>Send</button>
      </div>

      <hr />

      <h3>Messages</h3>
      {messages.map((m) => (
        <div key={m._id}>
          <strong>{m.sender.username}</strong>: {m.content}
        </div>
      ))}
    </div>
  );
}
