## Messages route

### `backend/src/routes/messages.ts`

```ts
import { Router } from "express";
import { prisma } from "../prisma";
import { requireAuth } from "../middleware/auth";
import { emitToUser } from "../services/socket";

const router = Router();

router.get("/:conversationId", requireAuth, async (req, res) => {
  const { conversationId } = req.params;

  const messages = await prisma.message.findMany({
    where: { conversationId },
    include: {
      sender: {
        select: {
          id: true,
          username: true
        }
      }
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

router.post("/", requireAuth, async (req, res) => {
  const { conversationId, content } = req.body;
  const senderId = req.user!.userId;

  if (!conversationId || !content) {
    return res.status(400).json({ error: "conversationId and content required" });
  }

  const conversation = await prisma.conversation.findUnique({
    where: { id: conversationId },
    include: {
      participants: true
    }
  });

  if (!conversation) {
    return res.status(404).json({ error: "Conversation not found" });
  }

  const isParticipant = conversation.participants.some((p) => p.userId === senderId);
  if (!isParticipant) {
    return res.status(403).json({ error: "Forbidden" });
  }

  const message = await prisma.message.create({
    data: {
      conversationId,
      senderId,
      content
    },
    include: {
      sender: {
        select: {
          id: true,
          username: true
        }
      }
    }
  });

  const recipients = conversation.participants.filter((p) => p.userId !== senderId);

  for (const recipient of recipients) {
    await prisma.notification.create({
      data: {
        userId: recipient.userId,
        type: "MESSAGE",
        title: "New message",
        body: content.slice(0, 120)
      }
    });

    emitToUser(recipient.userId, "message:new", message);
    emitToUser(recipient.userId, "notification:new", {
      type: "MESSAGE",
      title: "New message",
      body: content.slice(0, 120)
    });
  }

  res.json(message);
});

export default router;
```

