```js
import express from "express";
import { prisma } from "../db.js";
import { authMiddleware } from "../middleware/auth.js";
import { createNotification } from "../services/notificationService.js";

export default function messagesRouter(io) {
  const router = express.Router();

  router.get("/conversations/:userId", authMiddleware, async (req, res) => {
    const currentUserId = req.user.id;
    const otherUserId = req.params.userId;

    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { senderId: currentUserId, receiverId: otherUserId },
          { senderId: otherUserId, receiverId: currentUserId }
        ]
      },
      orderBy: { createdAt: "asc" },
      take: 100
    });

    res.json(messages);
  });

  router.post("/", authMiddleware, async (req, res) => {
    try {
      const { receiverId, content } = req.body;

      if (!receiverId || !content?.trim()) {
        return res.status(400).json({ error: "receiverId and content are required" });
      }

      const message = await prisma.message.create({
        data: {
          senderId: req.user.id,
          receiverId,
          content: content.trim()
        }
      });

      io.to(`user:${receiverId}`).emit("message:new", message);
      io.to(`user:${req.user.id}`).emit("message:new", message);

      await createNotification(
        io,
        receiverId,
        "message",
        "New message",
        `${req.user.username} sent you a message`,
        { messageId: message.id, senderId: req.user.id }
      );

      res.json(message);
    } catch {
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  return router;
}
```

