## `backend/src/routes/payments.js`

```js
import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import { createCheckoutSession, stripe } from "../services/paymentService.js";
import { prisma } from "../db.js";

export default function paymentsRouter(io) {
  const router = express.Router();

  router.post("/checkout", authMiddleware, async (req, res) => {
    try {
      const { amount, itemType, itemRef } = req.body;

      const session = await createCheckoutSession({
        userId: req.user.id,
        amount,
        itemType,
        itemRef,
        successUrl: `${process.env.CLIENT_URL}/wallet?success=1`,
        cancelUrl: `${process.env.CLIENT_URL}/wallet?canceled=1`
      });

      await prisma.purchase.create({
        data: {
          userId: req.user.id,
          stripeSessionId: session.id,
          amount,
          currency: "usd",
          status: "pending",
          itemType,
          itemRef
        }
      });

      res.json({ url: session.url });
    } catch (err) {
      res.status(500).json({ error: "Failed to create checkout session" });
    }
  });

  router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
    const sig = req.headers["stripe-signature"];

    try {
      const event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );

      if (event.type === "checkout.session.completed") {
        const session = event.data.object;

        const purchase = await prisma.purchase.updateMany({
          where: { stripeSessionId: session.id },
          data: {
            status: "paid",
            stripePaymentId: session.payment_intent
          }
        });

        const existing = await prisma.purchase.findFirst({
          where: { stripeSessionId: session.id }
        });

        if (existing) {
          io.to(`user:${existing.userId}`).emit("purchase:updated", {
            status: "paid",
            itemType: existing.itemType
          });
        }
      }

      res.json({ received: true });
    } catch (err) {
      res.status(400).send(`Webhook Error: ${err.message}`);
    }
  });

  router.get("/me/purchases", authMiddleware, async (req, res) => {
    const purchases = await prisma.purchase.findMany({
      where: { userId: req.user.id },
      orderBy: { createdAt: "desc" }
    });

    res.json(purchases);
  });

  return router;
}
```

