```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { connectSocket, getSocket } from "./socket";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Chat from "./pages/Chat";
import Wallet from "./pages/Wallet";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token"));
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [view, setView] = useState(user ? "chat" : "login");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;

    const socket = connectSocket(token);

    socket.on("notification:new", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    socket.on("purchase:updated", (purchase) => {
      alert(`Purchase updated: ${purchase.status}`);
    });

    return () => socket.disconnect();
  }, [token]);

  useEffect(() => {
    if (!token) return;
    api("/users/me/notifications", { token })
      .then(setNotifications)
      .catch(console.error);
  }, [token]);

  function handleAuth(data) {
    localStorage.setItem("token", data.token);
    localStorage.setItem("user", JSON.stringify(data.user));
    setToken(data.token);
    setUser(data.user);
    setView("chat");
  }

  function logout() {
    localStorage.clear();
    const socket = getSocket();
    if (socket) socket.disconnect();
    setToken(null);
    setUser(null);
    setNotifications([]);
    setView("login");
  }

  if (!token) {
    return view === "register"
      ? <Register onAuth={handleAuth} onSwitch={() => setView("login")} />
      : <Login onAuth={handleAuth} onSwitch={() => setView("register")} />;
  }

  return (
    <div style={{ padding: 20 }}>
      <div style={{ display: "flex", gap: 12, marginBottom: 20 }}>
        <button onClick={() => setView("chat")}>Chat</button>
        <button onClick={() => setView("wallet")}>Wallet</button>
        <button onClick={logout}>Logout</button>
        <div>Notifications: {notifications.filter(n => !n.read).length}</div>
      </div>

      {view === "chat" && <Chat token={token} user={user} notifications={notifications} />}
      {view === "wallet" && <Wallet token={token} />}
    </div>
  );
}
```

