```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";
import { getSocket } from "../socket";

export default function Chat({ token, user }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const socket = getSocket();

  useEffect(() => {
    api("/users", { token }).then(setUsers);
  }, [token]);

  useEffect(() => {
    if (!selectedUser) return;
    api(`/messages/conversations/${selectedUser.id}`, { token }).then(setMessages);
  }, [selectedUser, token]);

  useEffect(() => {
    if (!socket) return;

    const onMessage = (msg) => {
      if (
        selectedUser &&
        (
          (msg.senderId === selectedUser.id && msg.receiverId === user.id) ||
          (msg.senderId === user.id && msg.receiverId === selectedUser.id)
        )
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    socket.on("message:new", onMessage);
    return () => socket.off("message:new", onMessage);
  }, [socket, selectedUser, user.id]);

  async function sendMessage(content) {
    if (!selectedUser) return;
    await api("/messages", {
      method: "POST",
      token,
      body: {
        receiverId: selectedUser.id,
        content
      }
    });
  }

  return (
    <div style={{ display: "flex", gap: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Users</h3>
        {users.map(u => (
          <div key={u.id}>
            <button onClick={() => setSelectedUser(u)}>{u.username}</button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h3>
        <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 10 }}>
          {messages.map(m => (
            <div key={m.id} style={{ textAlign: m.senderId === user.id ? "right" : "left" }}>
              <p>{m.content}</p>
            </div>
          ))}
        </div>
        {selectedUser && <MessageComposer onSend={sendMessage} />}
      </div>
    </div>
  );
}

function MessageComposer({ onSend }) {
  const [content, setContent] = useState("");

  function submit(e) {
    e.preventDefault();
    if (!content.trim()) return;
    onSend(content);
    setContent("");
  }

  return (
    <form onSubmit={submit} style={{ marginTop: 10 }}>
      <input value={content} onChange={e => setContent(e.target.value)} placeholder="Type a message..." />
      <button type="submit">Send</button>
    </form>
  );
}
