      data: {
        senderId: req.user.id,
        receiverId,
        content
      }
    });

    emitToUser(receiverId, "message:new", message);
    await createNotification(receiverId, "message", `New message from ${req.user.username}`);

    res.json(message);
  } catch (err) {
