## `backend/src/routes/payments.js`

```js
import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import { stripe } from "../services/paymentService.js";
import { prisma } from "../db.js";
import { createNotification } from "../services/notificationService.js";

const router = express.Router();

router.post("/checkout-session", authMiddleware, async (req, res) => {
  try {
    const { amount = 499, currency = "usd" } = req.body;

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price_data: {
            currency,
            product_data: {
              name: "Premium Feature"
            },
            unit_amount: amount
          },
          quantity: 1
        }
      ],
      success_url: "http://localhost:5173/monetization?success=true",
      cancel_url: "http://localhost:5173/monetization?canceled=true",
      metadata: {
        userId: req.user.id,
        amount: String(amount)
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: "Failed to create checkout session", details: err.message });
  }
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"];

  let event;
  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;

    const userId = session.metadata.userId;
    const amount = Number(session.metadata.amount);

    await prisma.purchase.create({
      data: {
        userId,
        stripePaymentId: session.payment_intent,
        amount,
        currency: session.currency || "usd",
        status: "completed"
      }
    });

    await createNotification(userId, "purchase", "Your premium purchase was successful.");
  }

  res.json({ received: true });
});

export default router;
```

