  const [user, setUser] = useState(() => {
    const saved = localStorage.getItem("user");
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    if (user) setPage("chat");
  }, [user]);

  const logout = () => {
    localStorage.clear();
    setUser(null);
    setPage("login");
  };

  if (!user && page === "register") {
    return <Register setUser={setUser} setPage={setPage} />;
  }

  if (!user) {
    return <Login setUser={setUser} setPage={setPage} />;
  }

  if (page === "monetization") {
    return <Monetization setPage={setPage} />;
  }

  return <Chat user={user} logout={logout} setPage={setPage} />;
}
