import React, { useEffect, useState } from "react";
import { apiFetch } from "../api";

export default function ChatWindow({ selectedUser, socket, currentUser }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    if (!selectedUser) return;
    apiFetch(`/messages/${selectedUser.id}`).then(setMessages);
  }, [selectedUser]);

  useEffect(() => {
    if (!socket) return;

    socket.on("message:new", (message) => {
      if (
        message.senderId === selectedUser?.id ||
        message.receiverId === selectedUser?.id
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => socket.off("message:new");
  }, [socket, selectedUser]);

  async function sendMessage() {
    if (!content.trim() || !selectedUser) return;

    const message = await apiFetch("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content
      })
    });

    setMessages((prev) => [...prev, message]);
    setContent("");
  }

  if (!selectedUser) return <div>Select a user to chat</div>;

  return (
    <div>
      <h3>Chat with {selectedUser.username}</h3>
      <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 8 }}>
        {messages.map((m) => (
          <div key={m.id} style={{ textAlign: m.senderId === currentUser.id ? "right" : "left" }}>
            <span>{m.content}</span>
          </div>
        ))}
      </div>
      <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Type a message" />
      <button onClick={sendMessage}>Send</button>
