import { prisma } from "../lib/prisma.js";

export async function createConversation(req, res) {
  try {
    const { memberIds = [], title } = req.body;
    const creatorId = req.user.userId;

    const uniqueMembers = Array.from(new Set([creatorId, ...memberIds]));

    const conversation = await prisma.conversation.create({
      data: {
        title,
        members: {
          create: uniqueMembers.map((userId) => ({ userId }))
        }
      },
      include: {
        members: {
          include: {
            user: {
              select: { id: true, username: true, email: true }
            }
          }
        }
      }
    });

    res.json(conversation);
  } catch (err) {
    res.status(500).json({ message: "Failed to create conversation", error: err.message });
  }
}

export async function getConversations(req, res) {
  try {
    const userId = req.user.userId;

    const conversations = await prisma.conversation.findMany({
      where: {
        members: {
          some: { userId }
        }
      },
      include: {
        members: {
          include: {
            user: {
              select: { id: true, username: true }
            }
          }
        },
        messages: {
          orderBy: { createdAt: "desc" },
          take: 1
        }
      },
      orderBy: { updatedAt: "desc" }
    });

    res.json(conversations);
  } catch (err) {
    res.status(500).json({ message: "Failed to fetch conversations", error: err.message });
  }
}
