import Stripe from "stripe";
import { prisma } from "../lib/prisma.js";
import { emitToUser } from "../services/socket.service.js";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

export async function createCheckoutSession(req, res) {
  try {
    const userId = req.user.userId;

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "subscription",
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Messaging"
            },
            recurring: {
              interval: "month"
            },
            unit_amount: 999
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/premium?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/premium?canceled=true`,
      metadata: {
        userId
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: "Failed to create checkout session", error: err.message });
  }
}

export async function stripeWebhook(req, res) {
  const sig = req.headers["stripe-signature"];

  let event;
  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  try {
    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      await prisma.purchase.create({
        data: {
          userId,
          type: "SUBSCRIPTION",
          amount: session.amount_total || 0,
          currency: session.currency || "usd",
          stripePaymentId: session.payment_intent || session.id
        }
      });

      await prisma.subscription.create({
        data: {
          userId,
          stripeCustomerId: session.customer?.toString(),
          stripeSubscriptionId: session.subscription?.toString(),
          status: "active"
        }
      });

      emitToUser(userId, "payment:success", {
        message: "Premium subscription activated"
      });
    }

    res.json({ received: true });
  } catch (err) {
    res.status(500).json({ message: "Webhook handling failed", error: err.message });
  }
}
