import React, { useEffect, useState } from "react";
import { api } from "../api";

export default function ChatPage({ socket }) {
  const [conversations, setConversations] = useState([]);
  const [selected, setSelected] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    loadConversations();
  }, []);

  useEffect(() => {
    if (!socket) return;

    socket.on("message:new", (message) => {
      if (message.conversationId === selected?.id) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.off("message:new");
    };
  }, [socket, selected]);

  async function loadConversations() {
    const { data } = await api.get("/conversations");
    setConversations(data);
  }

  async function openConversation(conversation) {
    setSelected(conversation);
    socket?.emit("conversation:join", conversation.id);
    const { data } = await api.get(`/messages/${conversation.id}`);
    setMessages(data);
  }

  async function sendMessage() {
    if (!selected || !content.trim()) return;
    const { data } = await api.post("/messages", {
      conversationId: selected.id,
      content
    });
    setMessages((prev) => [...prev, data]);
    setContent("");
  }

  return (
    <div style={{ display: "flex", gap: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Conversations</h3>
        {conversations.map((c) => (
          <div
            key={c.id}
            onClick={() => openConversation(c)}
            style={{
              border: "1px solid #ccc",
              padding: 8,
              marginBottom: 8,
              cursor: "pointer"
            }}
          >
            <div>{c.title || "Untitled Conversation"}</div>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>{selected?.title || "Select a conversation"}</h3>
        <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 12 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <strong>{m.sender.username}:</strong> {m.content}
            </div>
          ))}
        </div>
        <div style={{ marginTop: 12 }}>
          <input
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message"
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
}
