# 3. Database schema with Prisma

Create `apps/api/prisma/schema.prisma`:

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum SubscriptionTier {
  FREE
  PREMIUM
}

enum NotificationType {
  MESSAGE
  TIP
  SUBSCRIPTION
  SYSTEM
}

model User {
  id                String           @id @default(cuid())
  email             String           @unique
  username          String           @unique
  passwordHash      String
  bio               String?
  avatarUrl         String?
  subscriptionTier  SubscriptionTier @default(FREE)
  stripeCustomerId  String?
  createdAt         DateTime         @default(now())
  updatedAt         DateTime         @updatedAt

  sentMessages      Message[]        @relation("SentMessages")
  receivedMessages  Message[]        @relation("ReceivedMessages")
  notifications     Notification[]
  sentTips          Tip[]            @relation("SentTips")
  receivedTips      Tip[]            @relation("ReceivedTips")
}

model Conversation {
  id           String                @id @default(cuid())
  createdAt    DateTime              @default(now())
  updatedAt    DateTime              @updatedAt
  participants ConversationParticipant[]
  messages     Message[]
}

model ConversationParticipant {
  id             String        @id @default(cuid())
  conversationId String
  userId         String
  joinedAt       DateTime      @default(now())

  conversation   Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  user           User          @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([conversationId, userId])
}

model Message {
  id             String        @id @default(cuid())
  conversationId String
  senderId       String
  receiverId     String
  content        String
  createdAt      DateTime      @default(now())
  readAt         DateTime?

  conversation   Conversation  @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender         User          @relation("SentMessages", fields: [senderId], references: [id], onDelete: Cascade)
  receiver       User          @relation("ReceivedMessages", fields: [receiverId], references: [id], onDelete: Cascade)
}

model Notification {
  id         String           @id @default(cuid())
  userId     String
  type       NotificationType
  title      String
  body       String
  read       Boolean          @default(false)
  metadata   Json?
  createdAt  DateTime         @default(now())

  user       User             @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model Tip {
  id          String    @id @default(cuid())
  senderId    String
  receiverId  String
  amount      Int
  currency    String    @default("usd")
  stripePaymentIntentId String?
  createdAt   DateTime  @default(now())

  sender      User      @relation("SentTips", fields: [senderId], references: [id], onDelete: Cascade)
  receiver    User      @relation("ReceivedTips", fields: [receiverId], references: [id], onDelete: Cascade)
}
