# 6. Messaging routes

## `apps/api/src/routes/messages.ts`

```ts
import { Router } from "express";
import { z } from "zod";
import { prisma } from "../lib/prisma";
import { requireAuth, AuthedRequest } from "../middleware/auth";

export function createMessageRouter(io: any, onlineUsers: Map<string, string>) {
  const router = Router();

  router.post("/", requireAuth, async (req: AuthedRequest, res) => {
    const schema = z.object({
      receiverId: z.string(),
      content: z.string().min(1).max(2000)
    });

    const parsed = schema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json(parsed.error.flatten());
    }

    const senderId = req.user!.userId;
    const { receiverId, content } = parsed.data;

    let conversation = await prisma.conversation.findFirst({
      where: {
        participants: {
          every: {
            userId: { in: [senderId, receiverId] }
          }
        }
      },
      include: {
        participants: true
      }
    });

    if (!conversation || conversation.participants.length !== 2) {
      conversation = await prisma.conversation.create({
        data: {
          participants: {
            create: [{ userId: senderId }, { userId: receiverId }]
          }
        },
        include: { participants: true }
      });
    }

    const message = await prisma.message.create({
      data: {
        conversationId: conversation.id,
        senderId,
        receiverId,
        content
      }
    });

    const notification = await prisma.notification.create({
      data: {
        userId: receiverId,
        type: "MESSAGE",
        title: "New message",
        body: content.slice(0, 120),
        metadata: {
          conversationId: conversation.id,
          senderId
        }
      }
    });

    const receiverSocketId = onlineUsers.get(receiverId);
    if (receiverSocketId) {
      io.to(receiverSocketId).emit("message:new", message);
      io.to(receiverSocketId).emit("notification:new", notification);
    }

    return res.json({ message, conversationId: conversation.id });
  });

  router.get("/conversations", requireAuth, async (req: AuthedRequest, res) => {
    const userId = req.user!.userId;

    const conversations = await prisma.conversation.findMany({
      where: {
        participants: {
          some: { userId }
        }
      },
      include: {
        participants: {
          include: {
            user: {
              select: {
                id: true,
                username: true,
                avatarUrl: true
              }
            }
          }
        },
        messages: {
          orderBy: { createdAt: "desc" },
          take: 1
        }
      },
      orderBy: { updatedAt: "desc" }
    });

    res.json(conversations);
  });

  router.get("/:conversationId", requireAuth, async (req: AuthedRequest, res) => {
    const { conversationId } = req.params;
    const userId = req.user!.userId;

    const isParticipant = await prisma.conversationParticipant.findFirst({
      where: { conversationId, userId }
    });

    if (!isParticipant) {
      return res.status(403).json({ error: "Forbidden" });
    }

    const messages = await prisma.message.findMany({
      where: { conversationId },
      orderBy: { createdAt: "asc" }
    });

    res.json(messages);
  });

  return router;
}
```

