const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "");

router.post("/create-subscription-checkout", requireAuth, async (req: AuthedRequest, res) => {
  const userId = req.user!.userId;

  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user) return res.status(404).json({ error: "User not found" });

  let customerId = user.stripeCustomerId;

  if (!customerId) {
    const customer = await stripe.customers.create({
      email: user.email,
      metadata: { userId: user.id }
    });

    customerId = customer.id;

    await prisma.user.update({
      where: { id: userId },
      data: { stripeCustomerId: customerId }
    });
  }

  const session = await stripe.checkout.sessions.create({
    customer: customerId,
    mode: "subscription",
    payment_method_types: ["card"],
    line_items: [
      {
        price: process.env.STRIPE_PREMIUM_PRICE_ID!,
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`
  });

  res.json({ url: session.url });
});

router.post("/create-tip-payment", requireAuth, async (req: AuthedRequest, res) => {
  const { receiverId, amount } = req.body;
  const senderId = req.user!.userId;

  const paymentIntent = await stripe.paymentIntents.create({
    amount,
    currency: "usd",
    automatic_payment_methods: { enabled: true },
    metadata: {
      senderId,
      receiverId,
      type: "tip"
    }
  });

  res.json({ clientSecret: paymentIntent.client_secret });
});

export default router;
