"use client";

import { useEffect, useState } from "react";
import { api } from "../../lib/api";
import { getSocket } from "../../lib/socket";

export default function MessagesPage() {
  const [conversations, setConversations] = useState<any[]>([]);
  const [selectedConversationId, setSelectedConversationId] = useState("");
  const [messages, setMessages] = useState<any[]>([]);
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState<any[]>([]);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      api.defaults.headers.common.Authorization = `Bearer ${token}`;
    }

    loadConversations();
    loadNotifications();

    const socket = getSocket();
    if (socket) {
      socket.on("message:new", (message) => {
        if (message.conversationId === selectedConversationId) {
          setMessages((prev) => [...prev, message]);
        }
        loadConversations();
      });

      socket.on("notification:new", (notification) => {
        setNotifications((prev) => [notification, ...prev]);
      });
    }

    return () => {
      socket?.off("message:new");
      socket?.off("notification:new");
    };
  }, [selectedConversationId]);

  async function loadConversations() {
    const res = await api.get("/messages/conversations");
    setConversations(res.data);
  }

  async function loadMessages(conversationId: string) {
    setSelectedConversationId(conversationId);
    const res = await api.get(`/messages/${conversationId}`);
    setMessages(res.data);
  }

  async function loadNotifications() {
    const res = await api.get("/notifications");
    setNotifications(res.data);
  }

  async function sendMessage() {
    const res = await api.post("/messages", { receiverId, content });
    if (res.data.conversationId === selectedConversationId) {
      setMessages((prev) => [...prev, res.data.message]);
    }
    setContent("");
    loadConversations();
  }

  return (
    <main style={{ display: "flex", gap: 24, padding: 24 }}>
      <section style={{ width: 300 }}>
        <h2>Conversations</h2>
        {conversations.map((conv) => (
          <div key={conv.id}>
            <button onClick={() => loadMessages(conv.id)}>
              {conv.participants.map((p: any) => p.user.username).join(", ")}
            </button>
          </div>
        ))}
      </section>

      <section style={{ flex: 1 }}>
        <h2>Messages</h2>
        <div>
          <input
            placeholder="Receiver user ID"
            value={receiverId}
            onChange={(e) => setReceiverId(e.target.value)}
          />
        </div>
        <div style={{ minHeight: 300, border: "1px solid #ccc", margin: "12px 0" }}>
          {messages.map((m) => (
            <div key={m.id}>
              <strong>{m.senderId}</strong>: {m.content}
            </div>
          ))}
        </div>
        <input
          placeholder="Type a message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </section>

      <section style={{ width: 300 }}>
        <h2>Notifications</h2>
        {notifications.map((n) => (
          <div key={n.id}>
            <strong>{n.title}</strong>
            <p>{n.body}</p>
          </div>
        ))}
      </section>
    </main>
  );
}
