import Stripe from "stripe";
import { prisma } from "../prisma";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "");

export async function createTopUpPaymentIntent(userId: string, amount: number) {
  const paymentIntent = await stripe.paymentIntents.create({
    amount,
    currency: "usd",
    metadata: { userId, type: "wallet_topup" }
  });

  await prisma.purchase.create({
    data: {
      userId,
      stripePaymentIntentId: paymentIntent.id,
      amount,
      currency: "usd",
      status: "pending"
    }
  });

  return paymentIntent;
}

export async function handlePaymentSucceeded(paymentIntentId: string) {
  const purchase = await prisma.purchase.findUnique({
    where: { stripePaymentIntentId: paymentIntentId }
  });

  if (!purchase) return;

  if (purchase.status === "succeeded") return;

  await prisma.purchase.update({
    where: { id: purchase.id },
    data: { status: "succeeded" }
  });

  await prisma.user.update({
    where: { id: purchase.userId },
    data: {
      walletBalance: {
        increment: purchase.amount
      }
    }
  });
}
