import { Router } from "express";
import express from "express";
import Stripe from "stripe";
import { authMiddleware, AuthRequest } from "../middleware/auth";
import { createTopUpPaymentIntent, handlePaymentSucceeded } from "../services/paymentService";

const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "");

router.post("/create-payment-intent", authMiddleware, async (req: AuthRequest, res) => {
  const userId = req.user!.userId;
  const { amount } = req.body;

  const paymentIntent = await createTopUpPaymentIntent(userId, amount);

  res.json({ clientSecret: paymentIntent.client_secret });
});

router.post(
  "/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"] as string;

    try {
      const event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET || ""
      );

      if (event.type === "payment_intent.succeeded") {
        const paymentIntent = event.data.object as Stripe.PaymentIntent;
        await handlePaymentSucceeded(paymentIntent.id);
      }

      res.json({ received: true });
    } catch (err) {
      res.status(400).send(`Webhook Error`);
    }
  }
);

export default router;
