import { useEffect, useState } from "react";
import { api, setAuthToken } from "./api";
import { createSocket } from "./socket";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Chat from "./pages/Chat";
import Wallet from "./pages/Wallet";

export default function App() {
  const [token, setToken] = useState<string | null>(localStorage.getItem("token"));
  const [page, setPage] = useState<"login" | "register" | "chat" | "wallet">("login");
  const [socket, setSocket] = useState<any>(null);
  const [notifications, setNotifications] = useState<any[]>([]);

  useEffect(() => {
    if (token) {
      setAuthToken(token);
      const s = createSocket(token);
      setSocket(s);

      api.get("/notifications").then((res) => setNotifications(res.data));

      s.on("notification:new", (notification: any) => {
        setNotifications((prev) => [notification, ...prev]);
      });

      return () => {
        s.disconnect();
      };
    }
  }, [token]);

  if (!token) {
    return page === "register" ? (
      <Register
        onSuccess={(newToken) => {
          localStorage.setItem("token", newToken);
          setToken(newToken);
          setPage("chat");
        }}
        onSwitch={() => setPage("login")}
      />
    ) : (
      <Login
        onSuccess={(newToken) => {
          localStorage.setItem("token", newToken);
          setToken(newToken);
          setPage("chat");
        }}
        onSwitch={() => setPage("register")}
      />
    );
  }

  return (
    <div style={{ padding: 20 }}>
      <div style={{ display: "flex", gap: 12, marginBottom: 20 }}>
        <button onClick={() => setPage("chat")}>Chat</button>
        <button onClick={() => setPage("wallet")}>Wallet</button>
        <button
          onClick={() => {
            localStorage.removeItem("token");
            setAuthToken(null);
            setToken(null);
            setPage("login");
          }}
        >
          Logout
        </button>
        <span>Notifications: {notifications.filter((n) => !n.isRead).length}</span>
      </div>

      {page === "chat" && <Chat socket={socket} />}
      {page === "wallet" && <Wallet />}
    </div>
  );
}
