## frontend/src/pages/Chat.tsx

```tsx
import { useEffect, useState } from "react";
import { api } from "../api";

export default function Chat({ socket }: { socket: any }) {
  const [conversations, setConversations] = useState<any[]>([]);
  const [selectedConversation, setSelectedConversation] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api.get("/conversations").then((res) => setConversations(res.data));
  }, []);

  useEffect(() => {
    if (!socket || !selectedConversation) return;

    socket.emit("conversation:join", selectedConversation);

    api.get(`/messages/${selectedConversation}`).then((res) => setMessages(res.data));

    const handler = (message: any) => {
      if (message.conversationId === selectedConversation) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on("message:new", handler);

    return () => {
      socket.emit("conversation:leave", selectedConversation);
      socket.off("message:new", handler);
    };
  }, [socket, selectedConversation]);

  async function sendMessage() {
    if (!selectedConversation || !content.trim()) return;

    await api.post("/messages", {
      conversationId: selectedConversation,
      content
    });

    setContent("");
  }

  return (
    <div style={{ display: "flex", gap: 20 }}>
      <div style={{ width: 250 }}>
        <h3>Conversations</h3>
        {conversations.map((conv) => (
          <div
            key={conv.id}
            onClick={() => setSelectedConversation(conv.id)}
            style={{
              padding: 10,
              border: "1px solid #ccc",
              marginBottom: 8,
              cursor: "pointer"
            }}
          >
            {conv.participants.map((p: any) => p.user.username).join(", ")}
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>Messages</h3>
        <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 10 }}>
          {messages.map((msg) => (
            <div key={msg.id}>
              <strong>{msg.sender.username}: </strong>
              {msg.content}
            </div>
          ))}
        </div>

        <div style={{ marginTop: 10 }}>
          <input
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message"
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
}
