## `backend/src/routes/payments.ts`

```ts
import { Router } from "express";
import express from "express";
import { stripe } from "../services/stripe";
import { env } from "../config/env";
import { prisma } from "../lib/prisma";
import { authMiddleware, AuthRequest } from "../middleware/auth";

const router = Router();

router.post("/create-checkout-session", authMiddleware, async (req: AuthRequest, res) => {
  const { amount } = req.body;

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ["card"],
    mode: "payment",
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: "Wallet Top-up"
          },
          unit_amount: amount
        },
        quantity: 1
      }
    ],
    success_url: `${env.CLIENT_URL}/wallet?success=true`,
    cancel_url: `${env.CLIENT_URL}/wallet?canceled=true`,
    metadata: {
      userId: req.user!.userId,
      amount: String(amount)
    }
  });

  res.json({ url: session.url });
});

router.post(
  "/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"] as string;

    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err: any) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object as any;
      const userId = session.metadata.userId;
      const amount = parseInt(session.metadata.amount, 10);

      await prisma.purchase.create({
        data: {
          userId,
          amount,
          stripePaymentId: session.payment_intent,
          currency: "usd"
        }
      });

      await prisma.wallet.upsert({
        where: { userId },
        update: { balance: { increment: amount } },
        create: { userId, balance: amount }
      });
    }

    res.json({ received: true });
  }
);

export default router;
```

