## `frontend/src/components/MessageThread.tsx`

```tsx
import { useEffect, useState } from "react";
import { api } from "../api";
import { socket } from "../socket";

export default function MessageThread({ currentUser, selectedUser }: any) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  const loadMessages = async () => {
    const res = await api.get(`/messages/${selectedUser.id}`);
    setMessages(res.data);
  };

  useEffect(() => {
    loadMessages();

    const onMessage = (message: any) => {
      const relevant =
        (message.senderId === selectedUser.id && message.receiverId === currentUser.id) ||
        (message.senderId === currentUser.id && message.receiverId === selectedUser.id);

      if (relevant) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on("message", onMessage);

    return () => {
      socket.off("message", onMessage);
    };
  }, [selectedUser.id]);

  const send = async () => {
    const res = await api.post("/messages", {
      receiverId: selectedUser.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
    setContent("");
  };

  return (
    <div style={{ flex: 1, border: "1px solid #ccc", padding: 10 }}>
      <h3>Chat with {selectedUser.username}</h3>
      <div style={{ height: 300, overflowY: "auto", marginBottom: 10 }}>
        {messages.map((msg) => (
          <div key={msg.id} style={{ margin: "8px 0" }}>
            <strong>{msg.senderId === currentUser.id ? "You" : selectedUser.username}:</strong>{" "}
            {msg.content}
          </div>
        ))}
      </div>
      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message"
      />
      <button onClick={send}>Send</button>
    </div>
  );
}
```

