# 7. Messaging API

## `server/src/routes/message.routes.js`

```js
const express = require("express");
const prisma = require("../config/prisma");
const auth = require("../middleware/auth");

const router = express.Router();

router.post("/send", auth, async (req, res) => {
  try {
    const { receiverId, body } = req.body;
    const senderId = req.user.userId;

    let conversation = await prisma.conversation.findFirst({
      where: {
        participants: {
          every: {
            userId: { in: [senderId, receiverId] }
          }
        }
      },
      include: { participants: true }
    });

    if (!conversation || conversation.participants.length !== 2) {
      conversation = await prisma.conversation.create({
        data: {
          participants: {
            create: [
              { userId: senderId },
              { userId: receiverId }
            ]
          }
        },
        include: { participants: true }
      });
    }

    const message = await prisma.message.create({
      data: {
        conversationId: conversation.id,
        senderId,
        receiverId,
        body
      }
    });

    await prisma.notification.create({
      data: {
        userId: receiverId,
        type: "NEW_MESSAGE",
        title: "New message",
        body: "You received a new message",
        metadata: { senderId, conversationId: conversation.id, messageId: message.id }
      }
    });

    const io = req.app.get("io");
    if (io) {
      io.to(receiverId).emit("message:new", message);
      io.to(receiverId).emit("notification:new", {
        type: "NEW_MESSAGE",
        title: "New message",
        body: "You received a new message"
      });
    }

    res.json(message);
  } catch (error) {
    res.status(500).json({ message: "Failed to send message", error: error.message });
  }
});

router.get("/conversation/:conversationId", auth, async (req, res) => {
  try {
    const messages = await prisma.message.findMany({
      where: { conversationId: req.params.conversationId },
      orderBy: { createdAt: "asc" }
    });

    res.json(messages);
  } catch (error) {
    res.status(500).json({ message: "Failed to fetch messages", error: error.message });
  }
});

module.exports = router;
```

