# 8. Socket.IO Real-Time Layer

## `server/src/sockets/index.js`

```js
const jwt = require("jsonwebtoken");

function registerSocketHandlers(io) {
  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth.token;
      const decoded = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = decoded;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.user.userId;
    socket.join(userId);

    socket.on("typing:start", ({ conversationId, toUserId }) => {
      io.to(toUserId).emit("typing:start", {
        conversationId,
        fromUserId: userId
      });
    });

    socket.on("typing:stop", ({ conversationId, toUserId }) => {
      io.to(toUserId).emit("typing:stop", {
        conversationId,
        fromUserId: userId
      });
    });

    socket.on("message:read", ({ messageId, toUserId }) => {
      io.to(toUserId).emit("message:read", {
        messageId,
        byUserId: userId
      });
    });
  });
}

module.exports = { registerSocketHandlers };
```

