# 15. Messaging UI Component

## `client/src/components/ChatWindow.jsx`

```jsx
import { useEffect, useState } from "react";
import api from "../api/client";
import { getSocket } from "../socket/socket";

export default function ChatWindow({ conversationId, receiverId }) {
  const [messages, setMessages] = useState([]);
  const [body, setBody] = useState("");
  const socket = getSocket();

  useEffect(() => {
    if (!conversationId) return;

    api.get(`/messages/conversation/${conversationId}`).then((res) => {
      setMessages(res.data);
    });
  }, [conversationId]);

  useEffect(() => {
    if (!socket) return;

    const onMessage = (message) => {
      if (message.conversationId === conversationId) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on("message:new", onMessage);

    return () => {
      socket.off("message:new", onMessage);
    };
  }, [socket, conversationId]);

  const sendMessage = async () => {
    if (!body.trim()) return;

    const res = await api.post("/messages/send", { receiverId, body });
    setMessages((prev) => [...prev, res.data]);
    setBody("");
  };

  return (
    <div>
      <div style={{ height: 300, overflowY: "auto", border: "1px solid #ccc" }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.senderId}</strong>: {m.body}
          </div>
        ))}
      </div>

      <div style={{ display: "flex", marginTop: 8 }}>
        <input
          value={body}
          onChange={(e) => setBody(e.target.value)}
          placeholder="Type a message..."
          style={{ flex: 1 }}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
}
```

