`backend/src/routes/payments.ts`

```ts
import { Router } from 'express';
import { authMiddleware, AuthRequest } from '../middleware/auth';
import { stripe } from '../lib/stripe';
import { prisma } from '../lib/prisma';
import { createNotification } from '../services/notificationService';
import { NotificationType, SubscriptionStatus } from '@prisma/client';

const router = Router();

router.post('/create-checkout-session', authMiddleware, async (req: AuthRequest, res) => {
  const userId = req.user!.userId;

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    mode: 'subscription',
    line_items: [
      {
        price: process.env.STRIPE_PREMIUM_PRICE_ID!,
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/premium?success=true`,
    cancel_url: `${process.env.CLIENT_URL}/premium?canceled=true`,
    metadata: { userId },
  });

  res.json({ url: session.url });
});

router.post('/webhook', async (req, res) => {
  const sig = req.headers['stripe-signature'] as string;

  let event;
  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object as any;
    const userId = session.metadata.userId;

    await prisma.purchase.create({
      data: {
        userId,
        stripeSessionId: session.id,
        amount: session.amount_total || 0,
        currency: session.currency || 'usd',
        status: 'completed',
      },
    });

    await prisma.user.update({
      where: { id: userId },
      data: { subscriptionStatus: SubscriptionStatus.PREMIUM },
    });

    await createNotification({
      type: NotificationType.PAYMENT,
      content: 'Your premium subscription is now active',
      recipientId: userId,
    });
  }

  res.json({ received: true });
});

export default router;
```

