## 4.5 Chat Page

`frontend/app/chat/page.tsx`

```tsx
'use client';

import { useEffect, useState } from 'react';
import { socket } from '../../lib/socket';
import { getUser } from '../../lib/auth';
import { apiFetch } from '../../lib/api';

export default function ChatPage() {
  const user = getUser();
  const [receiverId, setReceiverId] = useState('');
  const [content, setContent] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);

  useEffect(() => {
    if (!user) return;

    socket.connect();
    socket.emit('register', user.id);

    socket.on('message:new', (message) => {
      setMessages(prev => [...prev, message]);
    });

    socket.on('notification:new', (notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    return () => {
      socket.off('message:new');
      socket.off('notification:new');
      socket.disconnect();
    };
  }, [user]);

  async function loadMessages() {
    const data = await apiFetch(`/messages/${receiverId}`);
    setMessages(data);
  }

  async function sendMessage() {
    const message = await apiFetch('/messages', {
      method: 'POST',
      body: JSON.stringify({ receiverId, content }),
    });
    setMessages(prev => [...prev, message]);
    setContent('');
  }

  return (
    <div className="p-6">
      <h1 className="text-2xl mb-4">Chat</h1>

      <div className="mb-4">
        <input
          className="border p-2 mr-2"
          placeholder="Receiver User ID"
          value={receiverId}
          onChange={(e) => setReceiverId(e.target.value)}
        />
        <button className="bg-gray-700 text-white px-4 py-2" onClick={loadMessages}>
          Load Chat
        </button>
      </div>

      <div className="border p-4 h-80 overflow-y-auto mb-4">
        {messages.map((m) => (
          <div key={m.id} className="mb-2">
            <strong>{m.senderId === user?.id ? 'Me' : m.senderId}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <input
          className="border p-2 flex-1"
          placeholder="Type message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <button className="bg-blue-600 text-white px-4 py-2" onClick={sendMessage}>
          Send
        </button>
      </div>

      <div className="mt-8">
        <h2 className="text-xl mb-2">Notifications</h2>
        {notifications.map((n) => (
          <div key={n.id} className="border-b py-2">
            {n.content}
          </div>
        ))}
      </div>
    </div>
  );
}
```

