### `server/src/routes/messages.js`

```js
import express from "express";
import { authMiddleware } from "../middleware/auth.js";
import Conversation from "../models/Conversation.js";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import { getIO } from "../sockets/socket.js";

const router = express.Router();

router.post("/conversation/:userId", authMiddleware, async (req, res) => {
  try {
    const otherUserId = req.params.userId;

    let conversation = await Conversation.findOne({
      participants: { $all: [req.user._id, otherUserId] }
    });

    if (!conversation) {
      conversation = await Conversation.create({
        participants: [req.user._id, otherUserId]
      });
    }

    res.json(conversation);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

router.get("/conversations", authMiddleware, async (req, res) => {
  const conversations = await Conversation.find({
    participants: req.user._id
  })
    .populate("participants", "_id username avatarUrl isPremium")
    .populate("lastMessage")
    .sort({ updatedAt: -1 });

  res.json(conversations);
});

router.get("/:conversationId", authMiddleware, async (req, res) => {
  const messages = await Message.find({
    conversation: req.params.conversationId
  })
    .populate("sender", "_id username")
    .sort({ createdAt: 1 });

  res.json(messages);
});

router.post("/:conversationId", authMiddleware, async (req, res) => {
  try {
    const { text } = req.body;
    const conversationId = req.params.conversationId;

    const message = await Message.create({
      conversation: conversationId,
      sender: req.user._id,
      text,
      readBy: [req.user._id]
    });

    await Conversation.findByIdAndUpdate(conversationId, {
      lastMessage: message._id,
      updatedAt: new Date()
    });

    const populatedMessage = await Message.findById(message._id).populate(
      "sender",
      "_id username"
    );

    const conversation = await Conversation.findById(conversationId);
    const recipientIds = conversation.participants
      .map((id) => id.toString())
      .filter((id) => id !== req.user._id.toString());

    const io = getIO();
    io.to(`conversation:${conversationId}`).emit("new_message", populatedMessage);

    for (const recipientId of recipientIds) {
      const notification = await Notification.create({
        user: recipientId,
        type: "message",
        content: `${req.user.username} sent you a message`,
        meta: { conversationId, messageId: message._id }
      });

      io.to(`user:${recipientId}`).emit("notification:new", notification);
    }

    res.status(201).json(populatedMessage);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

export default router;
```

