## `client/src/pages/Chat.jsx`

```js
import React, { useEffect, useState } from "react";
import api from "../api";
import { createSocket } from "../socket";
import ConversationList from "../components/ConversationList";
import MessageList from "../components/MessageList";
import MessageInput from "../components/MessageInput";
import NotificationBell from "../components/NotificationBell";

export default function Chat() {
  const currentUser = JSON.parse(localStorage.getItem("user"));
  const [users, setUsers] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    loadInitial();

    const s = createSocket();
    setSocket(s);

    s.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    s.on("notification:new", (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    });

    return () => s.disconnect();
  }, []);

  const loadInitial = async () => {
    const [usersRes, convRes, notifRes] = await Promise.all([
      api.get("/users"),
      api.get("/messages/conversations"),
      api.get("/notifications")
    ]);
    setUsers(usersRes.data);
    setConversations(convRes.data);
    setNotifications(notifRes.data);
  };

  const startConversation = async (userId) => {
    const res = await api.post(`/messages/conversation/${userId}`);
    setSelectedConversation(res.data);
    socket?.emit("join_conversation", res.data._id);

    const msgRes = await api.get(`/messages/${res.data._id}`);
    setMessages(msgRes.data);
  };

  const sendMessage = async (text) => {
    if (!selectedConversation) return;
    await api.post(`/messages/${selectedConversation._id}`, { text });
  };

  const upgradeToPremium = async () => {
    const res = await api.post("/monetization/create-checkout-session");
    window.location.href = res.data.url;
  };

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 250 }}>
        <NotificationBell notifications={notifications} />
        <button onClick={upgradeToPremium}>Upgrade to Premium</button>
        <ConversationList
          users={users}
          conversations={conversations}
          selectedConversation={selectedConversation}
          onStartConversation={startConversation}
        />
      </div>

      <div style={{ flex: 1 }}>
        <h2>Chat</h2>
        {selectedConversation ? (
          <>
            <MessageList
              messages={messages}
              currentUserId={currentUser.id}
            />
            <MessageInput onSend={sendMessage} />
          </>
        ) : (
          <p>Select a user to start chatting.</p>
        )}
      </div>
    </div>
  );
}
```

