import React, { useEffect, useState } from 'react';
import { io } from 'socket.io-client';
import API from '../api';
import NotificationBell from '../components/NotificationBell';
import MessageList from '../components/MessageList';
import MessageInput from '../components/MessageInput';

const socket = io('http://localhost:5000');

export default function Chat({ onLogout }) {
  const currentUser = JSON.parse(localStorage.getItem('user'));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    socket.emit('join', currentUser.id);

    socket.on('receive_message', (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages(prev => [...prev, message]);
      }
    });

    socket.on('new_notification', (notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    return () => {
      socket.off('receive_message');
      socket.off('new_notification');
    };
  }, [selectedUser]);

  useEffect(() => {
    API.get('/users').then(res => setUsers(res.data));
    API.get('/users/notifications').then(res => setNotifications(res.data));
  }, []);

  const loadMessages = async (userId) => {
    setSelectedUser(users.find(u => u.id === userId));
    const res = await API.get(`/messages/${userId}`);
    setMessages(res.data);
  };

  const sendMessage = async (content, isPaid) => {
    if (!selectedUser) return;

    socket.emit('send_message', {
      senderId: currentUser.id,
      receiverId: selectedUser.id,
      content,
      isPaid
    });

    setMessages(prev => [
      ...prev,
      {
        id: Date.now().toString(),
        senderId: currentUser.id,
        receiverId: selectedUser.id,
        content,
        isPaid
      }
    ]);
  };

  return (
    <div style={{ display: 'flex', gap: '20px' }}>
      <div>
        <h3>Users</h3>
        <NotificationBell notifications={notifications} />
        <button onClick={onLogout}>Logout</button>
        {users.map(user => (
          <div key={user.id}>
            <button onClick={() => loadMessages(user.id)}>{user.username}</button>
          </div>
        ))}
      </div>

      <div>
        <h3>{selectedUser ? `Chat with ${selectedUser.username}` : 'Select a user'}</h3>
        <MessageList messages={messages} currentUser={currentUser} />
        {selectedUser && <MessageInput onSend={sendMessage} />}
      </div>
    </div>
  );
}
```

