'use client';

import { useEffect, useState } from 'react';
import { api } from '../lib/api';

interface Message {
  id: string;
  content: string;
  senderId: string;
  receiverId: string;
  isPremium: boolean;
}

export default function ChatWindow({ selectedUser, currentUser }: any) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [content, setContent] = useState('');
  const [isPremium, setIsPremium] = useState(false);

  useEffect(() => {
    if (!selectedUser) return;
    api(`/messages/${selectedUser.id}`).then(setMessages);
  }, [selectedUser]);

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;

    const message = await api('/messages', {
      method: 'POST',
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content,
        isPremium,
      }),
    });

    if (!message.error) {
      setMessages((prev) => [...prev, message]);
      setContent('');
    } else {
      alert(message.error);
    }
  }

  return (
    <div className="border rounded p-4 flex flex-col h-[500px]">
      <h2 className="font-bold mb-3">
        Chat with {selectedUser?.username || '...'}
      </h2>

      <div className="flex-1 overflow-y-auto space-y-2 mb-4">
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`p-2 rounded max-w-[70%] ${
              msg.senderId === currentUser.id
                ? 'ml-auto bg-blue-500 text-white'
                : 'bg-gray-200'
            }`}
          >
            {msg.content}
            {msg.isPremium && <span className="ml-2 text-xs">💎</span>}
          </div>
        ))}
      </div>

      <div className="space-y-2">
        <textarea
          className="w-full border rounded p-2"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message..."
        />
        <div className="flex items-center justify-between">
          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={isPremium}
              onChange={(e) => setIsPremium(e.target.checked)}
            />
            Premium message
          </label>
          <button
            onClick={sendMessage}
            className="bg-blue-600 text-white px-4 py-2 rounded"
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
}
