## Chat page: `src/pages/ChatPage.jsx`
```jsx
import React, { useEffect, useState } from 'react';
import { api } from '../api';
import { socket } from '../socket';
import { useAuth } from '../context/AuthContext';

export default function ChatPage() {
  const { user } = useAuth();
  const [users, setUsers] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    api.get('/users').then((res) => {
      setUsers(res.data.filter((u) => u.id !== user.id));
    });

    api.get('/conversations').then((res) => setConversations(res.data));
  }, [user.id]);

  useEffect(() => {
    socket.on('message:new', ({ conversationId, message }) => {
      if (selectedConversation?.id === conversationId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => socket.off('message:new');
  }, [selectedConversation]);

  const startConversation = async (otherUserId) => {
    const res = await api.post('/conversations', { otherUserId });
    setSelectedConversation(res.data);
    const msgRes = await api.get(`/messages/${res.data.id}`);
    setMessages(msgRes.data);
  };

  const openConversation = async (conversation) => {
    setSelectedConversation(conversation);
    const res = await api.get(`/messages/${conversation.id}`);
    setMessages(res.data);
  };

  const sendMessage = async (content) => {
    if (!selectedConversation) return;
    const res = await api.post('/messages', {
      conversationId: selectedConversation.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
  };

  return (
    <div style={{ display: 'flex', gap: 20 }}>
      <div style={{ width: 220 }}>
        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => startConversation(u.id)}>
              {u.username}
            </button>
          </div>
        ))}

        <h3>Conversations</h3>
        {conversations.map((c) => (
          <div key={c.id}>
            <button onClick={() => openConversation(c)}>
              {c.participants
                .map((p) => p.user.username)
                .filter((name) => name !== user.username)
                .join(', ') || 'Conversation'}
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>Messages</h3>
        <div style={{ minHeight: 300, border: '1px solid #ccc', padding: 12 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <strong>{m.sender.username}: </strong>
              {m.content}
            </div>
          ))}
        </div>

        <MessageComposer onSend={sendMessage} />
      </div>
    </div>
  );
}

function MessageComposer({ onSend }) {
  const [content, setContent] = useState('');

  const submit = async (e) => {
    e.preventDefault();
    if (!content.trim()) return;
    await onSend(content);
    setContent('');
  };

  return (
    <form onSubmit={submit} style={{ marginTop: 12 }}>
      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message"
        style={{ width: '80%' }}
      />
      <button type="submit">Send</button>
    </form>
  );
}
```

