## `frontend/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import api from "../api";
import socket from "../socket";
import UserList from "../components/UserList";
import ChatWindow from "../components/ChatWindow";
import NotificationBell from "../components/NotificationBell";

export default function Chat() {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const currentUser = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    loadUsers();
    loadNotifications();

    socket.connect();
    socket.emit("join", currentUser.id);

    socket.on("new_message", (message) => {
      if (
        selectedUser &&
        (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
      ) {
        setMessages(prev => [...prev, message]);
      }
    });

    socket.on("new_notification", (notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    return () => {
      socket.off("new_message");
      socket.off("new_notification");
      socket.disconnect();
    };
  }, [selectedUser]);

  const loadUsers = async () => {
    const res = await api.get("/users");
    setUsers(res.data);
  };

  const loadNotifications = async () => {
    const res = await api.get("/notifications");
    setNotifications(res.data);
  };

  const selectUser = async (user) => {
    setSelectedUser(user);
    const res = await api.get(`/messages/${user.id}`);
    setMessages(res.data);
  };

  const sendMessage = async (content) => {
    if (!selectedUser) return;
    const res = await api.post("/messages", {
      receiverId: selectedUser.id,
      content
    });
    setMessages(prev => [...prev, res.data]);
  };

  return (
    <div>
      <NotificationBell notifications={notifications} />
      <div style={{ display: "flex" }}>
        <UserList users={users} onSelect={selectUser} selectedUser={selectedUser} />
        <ChatWindow messages={messages} onSend={sendMessage} selectedUser={selectedUser} />
      </div>
    </div>
  );
}
```

