## backend/src/controllers/payment.controller.ts

```ts
import { Request, Response } from "express";
import { z } from "zod";
import { stripe } from "../lib/stripe";
import { config } from "../config";
import { createTipPaymentIntent, recordSuccessfulTip } from "../services/payment.service";

const tipSchema = z.object({
  receiverId: z.string(),
  amount: z.number().int().min(50)
});

export async function createTipIntent(req: Request, res: Response) {
  const senderId = req.user!.userId;
  const parsed = tipSchema.parse(req.body);

  const paymentIntent = await createTipPaymentIntent(
    senderId,
    parsed.receiverId,
    parsed.amount
  );

  res.json({
    clientSecret: paymentIntent.client_secret
  });
}

export async function stripeWebhook(req: Request, res: Response) {
  const sig = req.headers["stripe-signature"] as string;

  let event;
  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      config.stripeWebhookSecret
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "payment_intent.succeeded") {
    const pi = event.data.object as any;
    const senderId = pi.metadata.senderId;
    const receiverId = pi.metadata.receiverId;
    const amount = pi.amount;
    const paymentIntentId = pi.id;

    await recordSuccessfulTip(senderId, receiverId, amount, paymentIntentId);
  }

  res.json({ received: true });
}
