import { useEffect, useState } from "react";
import { api } from "../api";
import { UserList } from "../components/UserList";
import { ChatWindow } from "../components/ChatWindow";
import { NotificationBell } from "../components/NotificationBell";
import { useSocket } from "../hooks/useSocket";

export function ChatPage() {
  const [users, setUsers] = useState<any[]>([]);
  const [selectedUser, setSelectedUser] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);

  async function loadUsers() {
    const res = await api.get("/users");
    const currentUser = JSON.parse(localStorage.getItem("user") || "{}");
    setUsers(res.data.filter((u: any) => u.id !== currentUser.id));
  }

  async function loadNotifications() {
    const res = await api.get("/notifications");
    setNotifications(res.data);
  }

  async function loadConversation(userId: string) {
    const res = await api.get(`/messages/${userId}`);
    setMessages(res.data);
  }

  useSocket(
    (msg) => {
      if (
        selectedUser &&
        (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    },
    (notification) => {
      setNotifications((prev) => [notification, ...prev]);
    }
  );

  useEffect(() => {
    loadUsers();
    loadNotifications();
  }, []);

  async function handleSend(content: string) {
    if (!selectedUser) return;
    const res = await api.post("/messages", {
      receiverId: selectedUser.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
  }

  async function handleTip(amount: number) {
    if (!selectedUser) return;
    const res = await api.post("/payments/tip-intent", {
      receiverId: selectedUser.id,
      amount
    });

    alert(`Stripe client secret created: ${res.data.clientSecret}`);
  }

  return (
    <div style={{ padding: 16 }}>
      <NotificationBell notifications={notifications} />
      <div style={{ display: "flex" }}>
        <UserList
          users={users}
          selectedUserId={selectedUser?.id}
          onSelect={(user) => {
            setSelectedUser(user);
            loadConversation(user.id);
          }}
        />
        <ChatWindow
          messages={messages}
          selectedUser={selectedUser}
          onSend={handleSend}
          onTip={handleTip}
        />
      </div>
    </div>
  );
}
