# 5. Important Fix for Stripe Webhook Raw Body

There is one subtle issue in many Express apps: Stripe webhooks require the **raw request body**, not parsed JSON.

A safer approach is to register the webhook route before `express.json()`.

### Better `app.ts`

```ts
import express from "express";
import cors from "cors";
import authRoutes from "./routes/auth.routes";
import userRoutes from "./routes/user.routes";
import messageRoutes from "./routes/message.routes";
import notificationRoutes from "./routes/notification.routes";
import paymentRoutes from "./routes/payment.routes";
import { errorHandler } from "./middleware/errorHandler";
import { config } from "./config";
import { stripeWebhook } from "./controllers/payment.controller";

export const app = express();

app.use(cors({ origin: config.clientUrl }));

app.post(
  "/api/payments/webhook",
  express.raw({ type: "application/json" }),
  stripeWebhook
);

app.use(express.json());

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.use("/api/auth", authRoutes);
app.use("/api/users", userRoutes);
app.use("/api/messages", messageRoutes);
app.use("/api/notifications", notificationRoutes);
app.use("/api/payments", paymentRoutes);

app.use(errorHandler);
```

And then remove `/webhook` from `payment.routes.ts` to avoid duplicate registration.

