## `backend/routes/messages.js`

```js
const express = require("express");
const auth = require("../middleware/auth");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const { emitToUser } = require("../utils/socket");

const router = express.Router();

router.get("/:userId", auth, async (req, res) => {
  try {
    const myId = req.user.id;
    const otherId = req.params.userId;

    const messages = await Message.find({
      $or: [
        { sender: myId, recipient: otherId },
        { sender: otherId, recipient: myId }
      ]
    }).sort({ createdAt: 1 });

    res.json(messages);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/", auth, async (req, res) => {
  try {
    const { recipient, text, mediaUrl, isPaid, price } = req.body;

    const message = await Message.create({
      sender: req.user.id,
      recipient,
      text,
      mediaUrl: mediaUrl || "",
      isPaid: !!isPaid,
      price: isPaid ? price || 0 : 0
    });

    const populated = await message.populate("sender recipient", "username");

    const notification = await Notification.create({
      user: recipient,
      type: "message",
      message: `New message from ${populated.sender.username}`,
      meta: { senderId: req.user.id, messageId: message._id }
    });

    emitToUser(recipient, "new_message", populated);
    emitToUser(recipient, "new_notification", notification);

    res.json(populated);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

module.exports = router;
```

