## `backend/routes/payments.js`

```js
const express = require("express");
const Stripe = require("stripe");
const auth = require("../middleware/auth");
const User = require("../models/User");
const Purchase = require("../models/Purchase");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const { emitToUser } = require("../utils/socket");

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

router.post("/create-payment-intent", auth, async (req, res) => {
  try {
    const { amount, type, targetUserId, messageId } = req.body;

    const paymentIntent = await stripe.paymentIntents.create({
      amount: Math.round(amount * 100),
      currency: "usd",
      metadata: {
        userId: req.user.id,
        type,
        targetUserId: targetUserId || "",
        messageId: messageId || ""
      }
    });

    res.json({ clientSecret: paymentIntent.client_secret });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

router.post("/confirm", auth, async (req, res) => {
  try {
    const { amount, type, targetUserId, messageId, stripePaymentIntentId } = req.body;

    const me = await User.findById(req.user.id);

    if (type === "wallet_topup") {
      me.balance += amount;
      await me.save();

      await Purchase.create({
        buyer: me._id,
        amount,
        stripePaymentIntentId,
        type
      });

      return res.json({ success: true, balance: me.balance });
    }

    if (type === "premium") {
      me.premium = true;
      await me.save();

      await Purchase.create({
        buyer: me._id,
        amount,
        stripePaymentIntentId,
        type
      });

      return res.json({ success: true, premium: true });
    }

    if (type === "paid_message") {
      const message = await Message.findById(messageId);
      if (!message) return res.status(404).json({ message: "Message not found" });

      const seller = await User.findById(targetUserId);
      if (!seller) return res.status(404).json({ message: "Seller not found" });

      await Purchase.create({
        buyer: me._id,
        seller: seller._id,
        message: message._id,
        amount,
        stripePaymentIntentId,
        type
      });

      seller.balance += amount;
      await seller.save();

      const notification = await Notification.create({
        user: seller._id,
        type: "purchase",
        message: `${me.username} purchased your paid message`,
        meta: { buyerId: me._id, messageId: message._id }
      });

      emitToUser(seller._id, "new_notification", notification);

      return res.json({ success: true });
    }

    res.status(400).json({ message: "Invalid payment type" });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

module.exports = router;
```

