## `frontend/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import api from "./api";
import socket from "./socket";
import LoginPage from "./pages/LoginPage";
import RegisterPage from "./pages/RegisterPage";
import ChatPage from "./pages/ChatPage";

export default function App() {
  const [view, setView] = useState("login");
  const [user, setUser] = useState(null);

  useEffect(() => {
    const bootstrap = async () => {
      const token = localStorage.getItem("token");
      if (!token) return;
      try {
        const res = await api.get("/users/me");
        setUser(res.data);
        setView("chat");
        socket.emit("register", res.data._id);
      } catch {
        localStorage.removeItem("token");
      }
    };
    bootstrap();
  }, []);

  const onAuthSuccess = (data) => {
    localStorage.setItem("token", data.token);
    setUser(data.user);
    setView("chat");
    socket.emit("register", data.user.id);
  };

  if (user) {
    return <ChatPage user={user} onLogout={() => {
      localStorage.removeItem("token");
      setUser(null);
      setView("login");
    }} />;
  }

  return (
    <div style={{ padding: 20 }}>
      {view === "login" ? (
        <>
          <LoginPage onSuccess={onAuthSuccess} />
          <p>
            No account? <button onClick={() => setView("register")}>Register</button>
          </p>
        </>
      ) : (
        <>
          <RegisterPage onSuccess={onAuthSuccess} />
          <p>
            Have an account? <button onClick={() => setView("login")}>Login</button>
          </p>
        </>
      )}
    </div>
  );
}
```

