import React, { useState } from "react";
import api from "../api";

export default function ChatWindow({ messages, selectedUser, refreshMessages }) {
  const [text, setText] = useState("");
  const [isPaid, setIsPaid] = useState(false);
  const [price, setPrice] = useState(0);

  const sendMessage = async () => {
    if (!selectedUser || !text) return;

    await api.post("/messages", {
      recipient: selectedUser._id,
      text,
      isPaid,
      price
    });

    setText("");
    setIsPaid(false);
    setPrice(0);
    refreshMessages();
  };

  return (
    <div style={{ flex: 1, padding: 10 }}>
      <h3>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h3>

      <div style={{ minHeight: 300, border: "1px solid #ccc", marginBottom: 10, padding: 10 }}>
        {messages.map((m) => (
          <div key={m._id} style={{ marginBottom: 8 }}>
            <strong>{m.sender.username || "User"}:</strong>{" "}
            {m.isPaid ? `Paid message ($${m.price})` : m.text}
          </div>
        ))}
      </div>

      {selectedUser && (
        <>
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Type a message"
          />
          <br />
          <label>
            <input
              type="checkbox"
              checked={isPaid}
              onChange={(e) => setIsPaid(e.target.checked)}
            />
            Paid message
          </label>
          {isPaid && (
            <input
              type="number"
              value={price}
              onChange={(e) => setPrice(Number(e.target.value))}
              placeholder="Price"
            />
          )}
          <br />
          <button onClick={sendMessage}>Send</button>
        </>
      )}
    </div>
  );
}
