# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcrypt");
const { v4: uuidv4 } = require("uuid");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const db = new sqlite3.Database("./app.db");

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      token TEXT,
      premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER NOT NULL,
      recipient_id INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      type TEXT NOT NULL,
      message TEXT NOT NULL,
      read INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function auth(req, res, next) {
  const token = req.headers.authorization;
  if (!token) return res.status(401).json({ error: "Missing token" });

  db.get("SELECT * FROM users WHERE token = ?", [token], (err, user) => {
    if (err || !user) return res.status(401).json({ error: "Invalid token" });
    req.user = user;
    next();
  });
}

const onlineUsers = new Map(); // userId -> socket.id

io.on("connection", (socket) => {
  socket.on("authenticate", (token) => {
    db.get("SELECT * FROM users WHERE token = ?", [token], (err, user) => {
      if (!err && user) {
        onlineUsers.set(user.id, socket.id);
        socket.userId = user.id;
        socket.emit("authenticated", { success: true });
      }
    });
  });

  socket.on("disconnect", () => {
    if (socket.userId) {
      onlineUsers.delete(socket.userId);
    }
  });
});

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  const hash = await bcrypt.hash(password, 10);
  db.run(
    "INSERT INTO users (username, password_hash) VALUES (?, ?)",
    [username, hash],
    function (err) {
      if (err) return res.status(400).json({ error: "Username already exists" });
      res.json({ success: true });
    }
  );
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  db.get("SELECT * FROM users WHERE username = ?", [username], async (err, user) => {
    if (err || !user) return res.status(400).json({ error: "Invalid credentials" });

    const ok = await bcrypt.compare(password, user.password_hash);
    if (!ok) return res.status(400).json({ error: "Invalid credentials" });

    const token = uuidv4();
    db.run("UPDATE users SET token = ? WHERE id = ?", [token, user.id], (err2) => {
      if (err2) return res.status(500).json({ error: "Login failed" });
      res.json({
        token,
        user: {
          id: user.id,
          username: user.username,
          premium: user.premium
        }
      });
    });
  });
});

app.get("/api/users", auth, (req, res) => {
  db.all(
    "SELECT id, username, premium FROM users WHERE id != ? ORDER BY username",
    [req.user.id],
    (err, users) => {
      if (err) return res.status(500).json({ error: "Failed to fetch users" });
      res.json(users);
    }
  );
});

app.get("/api/messages/:userId", auth, (req, res) => {
  const otherUserId = parseInt(req.params.userId, 10);
  db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND recipient_id = ?)
       OR (sender_id = ? AND recipient_id = ?)
    ORDER BY created_at ASC, id ASC
    `,
    [req.user.id, otherUserId, otherUserId, req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "Failed to fetch messages" });
      res.json(rows);
    }
  );
});

app.post("/api/messages", auth, (req, res) => {
  const { recipientId, content } = req.body;
  if (!recipientId || !content) {
    return res.status(400).json({ error: "recipientId and content required" });
  }

  // Monetization rule:
  // free users can only send messages up to 100 chars
  if (!req.user.premium && content.length > 100) {
    return res.status(402).json({
      error: "Upgrade to premium to send messages longer than 100 characters"
    });
  }

  db.run(
    "INSERT INTO messages (sender_id, recipient_id, content) VALUES (?, ?, ?)",
    [req.user.id, recipientId, content],
    function (err) {
      if (err) return res.status(500).json({ error: "Failed to send message" });

      const messageId = this.lastID;

      db.run(
        "INSERT INTO notifications (user_id, type, message) VALUES (?, ?, ?)",
        [recipientId, "message", `New message from ${req.user.username}`],
        function () {
          db.get("SELECT * FROM messages WHERE id = ?", [messageId], (err2, msg) => {
            if (err2 || !msg) return res.status(500).json({ error: "Message saved but fetch failed" });

            const recipientSocketId = onlineUsers.get(Number(recipientId));
            if (recipientSocketId) {
              io.to(recipientSocketId).emit("new_message", msg);
              io.to(recipientSocketId).emit("notification", {
                type: "message",
                message: `New message from ${req.user.username}`
              });
            }

            res.json(msg);
          });
        }
      );
    }
  );
});

app.get("/api/notifications", auth, (req, res) => {
  db.all(
    "SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC, id DESC",
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "Failed to fetch notifications" });
      res.json(rows);
    }
  );
});

app.post("/api/upgrade", auth, (req, res) => {
  // Simulated in-app purchase
  db.run("UPDATE users SET premium = 1 WHERE id = ?", [req.user.id], (err) => {
    if (err) return res.status(500).json({ error: "Upgrade failed" });
    res.json({ success: true, premium: 1 });
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

