# 6. `public/app.js`

```js
const token = localStorage.getItem("token");
const me = JSON.parse(localStorage.getItem("user") || "null");

if (!token || !me) {
  window.location.href = "/";
}

const socket = io();
socket.emit("authenticate", token);

const headers = {
  "Content-Type": "application/json",
  "Authorization": token
};

let selectedUser = null;

document.getElementById("me").innerText =
  `Logged in as ${me.username} ${me.premium ? "(Premium)" : "(Free)"}`;

document.getElementById("upgradeBtn").onclick = upgrade;
document.getElementById("sendBtn").onclick = sendMessage;

socket.on("notification", (notif) => {
  const div = document.createElement("div");
  div.className = "notification";
  div.innerText = notif.message;
  document.getElementById("notifications").prepend(div);
});

socket.on("new_message", (msg) => {
  if (
    selectedUser &&
    (msg.sender_id === selectedUser.id || msg.recipient_id === selectedUser.id)
  ) {
    renderMessage(msg);
  } else {
    const div = document.createElement("div");
    div.className = "notification";
    div.innerText = "New message received";
    document.getElementById("notifications").prepend(div);
  }
});

async function loadUsers() {
  const res = await fetch("/api/users", { headers });
  const users = await res.json();
  const container = document.getElementById("users");
  container.innerHTML = "";

  users.forEach((user) => {
    const div = document.createElement("div");
    div.className = "user-item";
    div.innerText = `${user.username} ${user.premium ? "⭐" : ""}`;
    div.onclick = () => selectUser(user);
    container.appendChild(div);
  });
}

async function selectUser(user) {
  selectedUser = user;
  document.getElementById("chatTitle").innerText = `Chat with ${user.username}`;
  document.getElementById("messages").innerHTML = "";

  const res = await fetch(`/api/messages/${user.id}`, { headers });
  const messages = await res.json();
  messages.forEach(renderMessage);
}

function renderMessage(msg) {
  const div = document.createElement("div");
  div.className = "message " + (msg.sender_id === me.id ? "mine" : "theirs");
  div.innerText = msg.content;
  document.getElementById("messages").appendChild(div);
}

async function sendMessage() {
  if (!selectedUser) {
    document.getElementById("messageStatus").innerText = "Select a user first";
    return;
  }

  const content = document.getElementById("messageInput").value;

  const res = await fetch("/api/messages", {
    method: "POST",
    headers,
    body: JSON.stringify({
      recipientId: selectedUser.id,
      content
    })
  });

  const data = await res.json();

  if (!res.ok) {
    document.getElementById("messageStatus").innerText = data.error;
    return;
  }

  renderMessage(data);
  document.getElementById("messageInput").value = "";
  document.getElementById("messageStatus").innerText = "";
}

async function loadNotifications() {
  const res = await fetch("/api/notifications", { headers });
  const notifications = await res.json();
  const container = document.getElementById("notifications");
  container.innerHTML = "";

  notifications.forEach((n) => {
    const div = document.createElement("div");
    div.className = "notification";
    div.innerText = n.message;
    container.appendChild(div);
  });
}

async function upgrade() {
  const res = await fetch("/api/upgrade", {
    method: "POST",
    headers
  });

  const data = await res.json();
  if (data.success) {
    me.premium = 1;
    localStorage.setItem("user", JSON.stringify(me));
    document.getElementById("me").innerText =
      `Logged in as ${me.username} (Premium)`;
    document.getElementById("messageStatus").innerText =
      "Upgraded successfully";
    loadUsers();
  }
}

loadUsers();
loadNotifications();
```

