## Option A: single-file ultra-minimal demo
Here’s a very small backend you can run immediately.

### `server.js`
```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const sqlite3 = require("sqlite3").verbose();
const cors = require("cors");
const bcrypt = require("bcryptjs");
const jwt = require("jsonwebtoken");

const app = express();
const server = http.createServer(app);
const io = new Server(server, { cors: { origin: "*" } });

const SECRET = "dev_secret_key";
const db = new sqlite3.Database("./app.db");

app.use(cors());
app.use(express.json());

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE,
      password TEXT,
      premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      username TEXT,
      text TEXT,
      highlighted INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function auth(req, res, next) {
  const header = req.headers.authorization;
  if (!header) return res.status(401).json({ error: "Missing token" });
  const token = header.split(" ")[1];
  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/signup", async (req, res) => {
  const { username, password } = req.body;
  const hash = await bcrypt.hash(password, 10);
  db.run(
    `INSERT INTO users(username, password) VALUES(?, ?)`,
    [username, hash],
    function (err) {
      if (err) return res.status(400).json({ error: "Username taken" });
      const token = jwt.sign({ id: this.lastID, username }, SECRET);
      res.json({ token });
    }
  );
});

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  db.get(`SELECT * FROM users WHERE username = ?`, [username], async (err, user) => {
    if (!user) return res.status(400).json({ error: "Invalid credentials" });
    const ok = await bcrypt.compare(password, user.password);
    if (!ok) return res.status(400).json({ error: "Invalid credentials" });
    const token = jwt.sign({ id: user.id, username: user.username }, SECRET);
    res.json({ token, premium: !!user.premium });
  });
});

app.get("/messages", (req, res) => {
  db.all(`SELECT * FROM messages ORDER BY id DESC LIMIT 50`, [], (err, rows) => {
    res.json(rows || []);
  });
});

app.post("/messages", auth, (req, res) => {
  const { text } = req.body;
  db.get(`SELECT premium FROM users WHERE id = ?`, [req.user.id], (err, user) => {
    const highlighted = user?.premium ? 1 : 0;
    db.run(
      `INSERT INTO messages(user_id, username, text, highlighted) VALUES(?, ?, ?, ?)`,
      [req.user.id, req.user.username, text, highlighted],
      function () {
        const msg = {
          id: this.lastID,
          user_id: req.user.id,
          username: req.user.username,
          text,
          highlighted,
        };
        io.emit("new_message", msg);
        io.emit("notification", {
          type: "message",
          text: `New message from ${req.user.username}`,
        });
        res.json(msg);
      }
    );
  });
});

app.post("/purchase/mock-premium", auth, (req, res) => {
  db.run(`UPDATE users SET premium = 1 WHERE id = ?`, [req.user.id], function () {
    res.json({ success: true, premium: true });
  });
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);
  socket.on("disconnect", () => console.log("User disconnected:", socket.id));
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

