## Option B: minimal React frontend
### `App.jsx`
```jsx
import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";
const socket = io(API);

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [messages, setMessages] = useState([]);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState(0);
  const [premium, setPremium] = useState(false);

  useEffect(() => {
    fetch(`${API}/messages`)
      .then((r) => r.json())
      .then(setMessages);

    socket.on("new_message", (msg) => {
      setMessages((prev) => [msg, ...prev]);
    });

    socket.on("notification", () => {
      setNotifications((n) => n + 1);
    });

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, []);

  async function auth() {
    const res = await fetch(`${API}/${authMode}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, password }),
    });
    const data = await res.json();
    if (data.token) {
      setToken(data.token);
      setPremium(!!data.premium);
      localStorage.setItem("token", data.token);
    } else {
      alert(data.error || "Auth failed");
    }
  }

  async function sendMessage() {
    const res = await fetch(`${API}/messages`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ text }),
    });
    const data = await res.json();
    if (!data.error) setText("");
  }

  async function buyPremium() {
    const res = await fetch(`${API}/purchase/mock-premium`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });
    const data = await res.json();
    if (data.success) setPremium(true);
  }

  return (
    <div style={{ maxWidth: 600, margin: "40px auto", fontFamily: "Arial" }}>
      <h1>Mini Social App</h1>
      <div>Notifications: {notifications}</div>

      {!token ? (
        <div>
          <h3>{authMode === "login" ? "Login" : "Sign Up"}</h3>
          <input
            placeholder="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <input
            placeholder="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button onClick={auth}>{authMode}</button>
          <button onClick={() => setAuthMode(authMode === "login" ? "signup" : "login")}>
            switch to {authMode === "login" ? "signup" : "login"}
          </button>
        </div>
      ) : (
        <div>
          <div>
            Premium: {premium ? "Yes" : "No"}{" "}
            {!premium && <button onClick={buyPremium}>Unlock Premium</button>}
          </div>
          <textarea
            placeholder="Write a message..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          <br />
          <button onClick={sendMessage}>Post</button>
        </div>
      )}

      <hr />

      {messages.map((m) => (
        <div
          key={m.id}
          style={{
            padding: 10,
            marginBottom: 8,
            border: "1px solid #ddd",
            background: m.highlighted ? "#fff7cc" : "#fff",
          }}
        >
          <strong>@{m.username}</strong>: {m.text}
          {m.highlighted ? " ⭐" : ""}
        </div>
      ))}
    </div>
  );
}
```

