`pages/chat.js`

```js
import { useEffect, useState } from "react";
import axios from "axios";
import { io } from "socket.io-client";

let socket;

export default function Chat() {
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [receiverId, setReceiverId] = useState("");
  const [message, setMessage] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("user"));
    if (!stored) {
      location.href = "/login";
      return;
    }
    setUser(stored);

    socket = io();
    socket.emit("register-user", stored.id);

    socket.on("new-message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    });

    loadUsers(stored.id);

    return () => {
      socket.disconnect();
    };
  }, []);

  const loadUsers = async (myId) => {
    const res = await axios.get("/api/users", { params: { myId } });
    setUsers(res.data);
  };

  const loadMessages = async (targetId) => {
    const res = await axios.get("/api/messages", {
      params: { userId: user.id, otherUserId: targetId }
    });
    setMessages(res.data);
  };

  const sendMessage = async () => {
    if (!receiverId || !message.trim()) return;

    const res = await axios.post("/api/messages", {
      senderId: user.id,
      receiverId: Number(receiverId),
      content: message
    });

    setMessages((prev) => [...prev, res.data]);

    socket.emit("send-message", {
      ...res.data,
      senderUsername: user.username
    });

    setMessage("");
  };

  const buyPremium = async () => {
    const res = await axios.post("/api/purchase", { userId: user.id });
    window.location.href = res.data.url;
  };

  return (
    <div className="chat-layout">
      <div className="sidebar">
        <h3>Users</h3>
        {users.map((u) => (
          <div
            key={u.id}
            className={`user ${String(receiverId) === String(u.id) ? "active" : ""}`}
            onClick={() => {
              setReceiverId(u.id);
              loadMessages(u.id);
            }}
          >
            {u.username} {u.isPremium ? "⭐" : ""}
          </div>
        ))}

        <button onClick={buyPremium}>
          {user?.isPremium ? "Premium Active" : "Buy Premium"}
        </button>

        <h3>Notifications</h3>
        {notifications.map((n, i) => (
          <div key={i} className="notif">{n.content}</div>
        ))}
      </div>

      <div className="chat-panel">
        <h2>Logged in as: {user?.username}</h2>
        <div className="messages">
          {messages.map((m) => (
            <div
              key={m.id || `${m.senderId}-${m.receiverId}-${m.createdAt}`}
              className={m.senderId === user?.id ? "mine" : "theirs"}
            >
              {m.content}
            </div>
          ))}
        </div>

        <div className="composer">
          <input
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="Type message..."
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
}
