## 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

/**
 * In-memory demo storage
 */
const users = new Map(); 
// username -> { username, balance, socketId }

const messages = []; 
// { id, from, to, text, timestamp }

const purchases = []; 
// { id, from, to, amount, timestamp }

/**
 * Demo auth/login
 */
app.post("/api/login", (req, res) => {
  const { username } = req.body;
  if (!username || !username.trim()) {
    return res.status(400).json({ error: "Username required" });
  }

  const clean = username.trim().toLowerCase();
  if (!users.has(clean)) {
    users.set(clean, {
      username: clean,
      balance: 100,
      socketId: null
    });
  }

  res.json({
    user: users.get(clean)
  });
});

/**
 * List users
 */
app.get("/api/users", (req, res) => {
  res.json({
    users: Array.from(users.values()).map(u => ({
      username: u.username,
      balance: u.balance,
      online: !!u.socketId
    }))
  });
});

/**
 * Get conversation
 */
app.get("/api/messages/:userA/:userB", (req, res) => {
  const { userA, userB } = req.params;
  const convo = messages.filter(
    m =>
      (m.from === userA && m.to === userB) ||
      (m.from === userB && m.to === userA)
  );
  res.json({ messages: convo });
});

/**
 * Send message
 */
app.post("/api/messages", (req, res) => {
  const { from, to, text } = req.body;

  if (!from || !to || !text) {
    return res.status(400).json({ error: "from, to, text required" });
  }

  if (!users.has(from) || !users.has(to)) {
    return res.status(404).json({ error: "User not found" });
  }

  const message = {
    id: Date.now().toString(),
    from,
    to,
    text,
    timestamp: new Date().toISOString()
  };

  messages.push(message);

  const recipient = users.get(to);
  if (recipient?.socketId) {
    io.to(recipient.socketId).emit("new_message", message);
    io.to(recipient.socketId).emit("notification", {
      type: "message",
      text: `New message from ${from}`
    });
  }

  const sender = users.get(from);
  if (sender?.socketId) {
    io.to(sender.socketId).emit("message_sent", message);
  }

  res.json({ message });
});

/**
 * Mock monetization: tip another user
 */
app.post("/api/tip", (req, res) => {
  const { from, to, amount } = req.body;

  if (!from || !to || typeof amount !== "number") {
    return res.status(400).json({ error: "from, to, amount required" });
  }

  if (amount <= 0) {
    return res.status(400).json({ error: "amount must be > 0" });
  }

  const sender = users.get(from);
  const recipient = users.get(to);

  if (!sender || !recipient) {
    return res.status(404).json({ error: "User not found" });
  }

  if (sender.balance < amount) {
    return res.status(400).json({ error: "Insufficient balance" });
  }

  sender.balance -= amount;
  recipient.balance += amount;

  const purchase = {
    id: Date.now().toString(),
    from,
    to,
    amount,
    timestamp: new Date().toISOString()
  };

  purchases.push(purchase);

  if (recipient.socketId) {
    io.to(recipient.socketId).emit("notification", {
      type: "tip",
      text: `${from} tipped you ${amount} coins`
    });
    io.to(recipient.socketId).emit("balance_update", {
      username: recipient.username,
      balance: recipient.balance
    });
  }

  if (sender.socketId) {
    io.to(sender.socketId).emit("balance_update", {
      username: sender.username,
      balance: sender.balance
    });
  }

  res.json({
    success: true,
    purchase,
    senderBalance: sender.balance,
    recipientBalance: recipient.balance
  });
});

io.on("connection", socket => {
  socket.on("register", username => {
    if (!username || !users.has(username)) return;
    const user = users.get(username);
    user.socketId = socket.id;

    socket.emit("notification", {
      type: "system",
      text: `Connected as ${username}`
    });

    io.emit("presence_update", {
      username,
      online: true
    });
  });

  socket.on("disconnect", () => {
    for (const [username, user] of users.entries()) {
      if (user.socketId === socket.id) {
        user.socketId = null;
        io.emit("presence_update", {
          username,
          online: false
        });
        break;
      }
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

