## 5. `public/app.js`

```js
const socket = io();

let currentUser = null;
let selectedUser = null;

const loginSection = document.getElementById("loginSection");
const appSection = document.getElementById("appSection");
const usernameInput = document.getElementById("usernameInput");
const loginBtn = document.getElementById("loginBtn");
const meEl = document.getElementById("me");
const balanceEl = document.getElementById("balance");
const usersList = document.getElementById("usersList");
const chatWith = document.getElementById("chatWith");
const messagesEl = document.getElementById("messages");
const messageInput = document.getElementById("messageInput");
const sendBtn = document.getElementById("sendBtn");
const notificationsEl = document.getElementById("notifications");
const tipAmount = document.getElementById("tipAmount");
const tipBtn = document.getElementById("tipBtn");

function addNotification(text) {
  const li = document.createElement("li");
  li.textContent = `${new Date().toLocaleTimeString()} - ${text}`;
  notificationsEl.prepend(li);
}

async function api(url, method = "GET", body) {
  const res = await fetch(url, {
    method,
    headers: { "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined
  });
  return res.json();
}

async function login() {
  const username = usernameInput.value.trim().toLowerCase();
  if (!username) return alert("Enter username");

  const data = await api("/api/login", "POST", { username });
  if (data.error) return alert(data.error);

  currentUser = data.user;
  meEl.textContent = currentUser.username;
  balanceEl.textContent = currentUser.balance;

  loginSection.classList.add("hidden");
  appSection.classList.remove("hidden");

  socket.emit("register", currentUser.username);
  await loadUsers();
}

async function loadUsers() {
  const data = await api("/api/users");
  usersList.innerHTML = "";

  data.users
    .filter(u => u.username !== currentUser.username)
    .forEach(user => {
      const li = document.createElement("li");
      li.className = "user-item";
      li.innerHTML = `
        <button>
          ${user.username} ${user.online ? "🟢" : "⚪"}
        </button>
      `;
      li.querySelector("button").onclick = async () => {
        selectedUser = user.username;
        chatWith.textContent = `Chatting with ${selectedUser}`;
        await loadMessages();
      };
      usersList.appendChild(li);
    });
}

async function loadMessages() {
  if (!selectedUser) return;
  const data = await api(`/api/messages/${currentUser.username}/${selectedUser}`);
  messagesEl.innerHTML = "";

  data.messages.forEach(renderMessage);
}

function renderMessage(msg) {
  const div = document.createElement("div");
  div.className = `message ${msg.from === currentUser.username ? "mine" : "theirs"}`;
  div.textContent = `${msg.from}: ${msg.text}`;
  messagesEl.appendChild(div);
  messagesEl.scrollTop = messagesEl.scrollHeight;
}

async function sendMessage() {
  const text = messageInput.value.trim();
  if (!selectedUser) return alert("Select a user");
  if (!text) return;

  const data = await api("/api/messages", "POST", {
    from: currentUser.username,
    to: selectedUser,
    text
  });

  if (data.error) return alert(data.error);

  messageInput.value = "";
}

async function sendTip() {
  if (!selectedUser) return alert("Select a user");
  const amount = Number(tipAmount.value);

  const data = await api("/api/tip", "POST", {
    from: currentUser.username,
    to: selectedUser,
    amount
  });

  if (data.error) return alert(data.error);

  balanceEl.textContent = data.senderBalance;
  addNotification(`You tipped ${selectedUser} ${amount} coins`);
}

socket.on("new_message", msg => {
  if (
    selectedUser &&
    (msg.from === selectedUser || msg.to === selectedUser)
  ) {
    renderMessage(msg);
  }
});

socket.on("message_sent", msg => {
  if (
    selectedUser &&
    (msg.from === selectedUser || msg.to === selectedUser)
  ) {
    renderMessage(msg);
  }
});

socket.on("notification", payload => {
  addNotification(payload.text);
});

socket.on("balance_update", payload => {
  if (currentUser && payload.username === currentUser.username) {
    balanceEl.textContent = payload.balance;
  }
});

socket.on("presence_update", () => {
  if (currentUser) loadUsers();
});

loginBtn.onclick = login;
sendBtn.onclick = sendMessage;
tipBtn.onclick = sendTip;
```

