```js
import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { prisma } from "./db.js";
import { signToken, authMiddleware } from "./auth.js";

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: { origin: "http://localhost:5173", methods: ["GET", "POST"] }
});

app.use(cors());
app.use(express.json());

const onlineUsers = new Map();

io.on("connection", (socket) => {
  socket.on("identify", (userId) => {
    onlineUsers.set(userId, socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

app.post("/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  const hashed = await bcrypt.hash(password, 10);

  try {
    const user = await prisma.user.create({
      data: { username, password: hashed }
    });
    res.json({ token: signToken(user), user: { id: user.id, username: user.username } });
  } catch {
    res.status(400).json({ error: "username already exists" });
  }
});

app.post("/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) return res.status(401).json({ error: "invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(401).json({ error: "invalid credentials" });

  res.json({ token: signToken(user), user: { id: user.id, username: user.username } });
});

app.get("/users", authMiddleware, async (req, res) => {
  const users = await prisma.user.findMany({
    select: { id: true, username: true }
  });
  res.json(users);
});

app.post("/follow/:id", authMiddleware, async (req, res) => {
  const followingId = Number(req.params.id);
  const followerId = req.user.id;

  if (followingId === followerId) {
    return res.status(400).json({ error: "cannot follow yourself" });
  }

  try {
    await prisma.follow.create({
      data: { followerId, followingId }
    });

    const socketId = onlineUsers.get(followingId);
    if (socketId) {
      io.to(socketId).emit("notification", {
        type: "follow",
        message: `${req.user.username} followed you`
      });
    }

    res.json({ ok: true });
  } catch {
    res.status(400).json({ error: "already following or invalid user" });
  }
});

app.post("/posts", authMiddleware, async (req, res) => {
  const { content } = req.body;
  if (!content) return res.status(400).json({ error: "content required" });

  const post = await prisma.post.create({
    data: {
      content,
      authorId: req.user.id
    },
    include: {
      author: { select: { id: true, username: true } }
    }
  });

  const followers = await prisma.follow.findMany({
    where: { followingId: req.user.id }
  });

  for (const f of followers) {
    const socketId = onlineUsers.get(f.followerId);
    if (socketId) {
      io.to(socketId).emit("notification", {
        type: "post",
        message: `${req.user.username} made a new post`,
        post
      });
    }
  }

  res.json(post);
});

app.get("/feed", authMiddleware, async (req, res) => {
  const follows = await prisma.follow.findMany({
    where: { followerId: req.user.id },
    select: { followingId: true }
  });

  const ids = follows.map((f) => f.followingId).concat(req.user.id);

  const posts = await prisma.post.findMany({
    where: { authorId: { in: ids } },
    include: { author: { select: { id: true, username: true } } },
    orderBy: { createdAt: "desc" },
    take: 50
  });

  res.json(posts);
});

// mock monetization endpoint
app.post("/purchase/boost", authMiddleware, async (req, res) => {
  res.json({
    ok: true,
    message: "Mock purchase successful. Integrate Stripe/Apple/Google in production."
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
