import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:3001";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [feed, setFeed] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(API), []);

  useEffect(() => {
    if (user) socket.emit("identify", user.id);
  }, [user, socket]);

  useEffect(() => {
    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
      if (n.post) setFeed((prev) => [n.post, ...prev]);
    });
    return () => socket.off("notification");
  }, [socket]);

  async function auth(path) {
    const res = await fetch(`${API}/${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, password })
    });
    const data = await res.json();
    if (data.token) {
      setToken(data.token);
      setUser(data.user);
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
      loadData(data.token);
    } else {
      alert(data.error || "Auth failed");
    }
  }

  async function loadData(t = token) {
    const headers = { Authorization: `Bearer ${t}` };
    const [uRes, fRes] = await Promise.all([
      fetch(`${API}/users`, { headers }),
      fetch(`${API}/feed`, { headers })
    ]);
    setUsers(await uRes.json());
    setFeed(await fRes.json());
  }

  async function follow(id) {
    await fetch(`${API}/follow/${id}`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` }
    });
    loadData();
  }

  async function createPost() {
    const res = await fetch(`${API}/posts`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ content })
    });
    const data = await res.json();
    if (data.id) {
      setFeed((prev) => [data, ...prev]);
      setContent("");
    }
  }

  async function purchaseBoost() {
    const res = await fetch(`${API}/purchase/boost`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    alert(data.message);
  }

  function logout() {
    localStorage.clear();
    setToken("");
    setUser(null);
    setFeed([]);
    setUsers([]);
    setNotifications([]);
  }

  useEffect(() => {
    if (token) loadData();
  }, []);

  if (!token) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h1>Social MVP</h1>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input
          placeholder="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <br />
        <button onClick={() => auth("register")}>Register</button>
        <button onClick={() => auth("login")}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif", display: "grid", gridTemplateColumns: "1fr 2fr 1fr", gap: 20 }}>
      <div>
        <h3>Users</h3>
        <p>Logged in as <b>{user?.username}</b></p>
        <button onClick={logout}>Logout</button>
        <ul>
          {users.filter((u) => u.id !== user.id).map((u) => (
            <li key={u.id}>
              {u.username} <button onClick={() => follow(u.id)}>Follow</button>
            </li>
          ))}
        </ul>
      </div>

      <div>
        <h3>Feed</h3>
        <textarea
          rows="3"
          cols="40"
          placeholder="What's happening?"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <br />
        <button onClick={createPost}>Post</button>
        <button onClick={purchaseBoost}>Mock Boost Purchase</button>

        <ul>
          {feed.map((p) => (
            <li key={p.id}>
              <b>{p.author.username}</b>: {p.content}
            </li>
          ))}
        </ul>
      </div>

      <div>
        <h3>Notifications</h3>
        <ul>
          {notifications.map((n, i) => (
            <li key={i}>{n.message}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
