# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcrypt");
const jwt = require("jsonwebtoken");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const PORT = 3000;
const JWT_SECRET = "super-secret-key"; // replace in production

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const db = new sqlite3.Database("./app.db");

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER NOT NULL,
      receiver_id INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS purchases (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      item TEXT NOT NULL,
      amount_cents INTEGER NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization || "";
  const token = authHeader.replace("Bearer ", "");
  if (!token) return res.status(401).json({ error: "Missing token" });

  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload;
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

// In-memory socket tracking: userId -> socket.id
const onlineUsers = new Map();

io.use((socket, next) => {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error("Missing token"));
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    socket.user = payload;
    next();
  } catch {
    next(new Error("Invalid token"));
  }
});

io.on("connection", (socket) => {
  const userId = socket.user.id;
  onlineUsers.set(userId, socket.id);
  console.log(`User ${userId} connected`);

  socket.emit("notification", {
    type: "system",
    message: "Connected to realtime server"
  });

  socket.on("disconnect", () => {
    onlineUsers.delete(userId);
    console.log(`User ${userId} disconnected`);
  });
});

// Auth
app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  try {
    const hash = await bcrypt.hash(password, 10);
    db.run(
      `INSERT INTO users (username, password_hash) VALUES (?, ?)`,
      [username, hash],
      function (err) {
        if (err) return res.status(400).json({ error: "Username already exists" });
        return res.json({ success: true, userId: this.lastID });
      }
    );
  } catch {
    res.status(500).json({ error: "Server error" });
  }
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  db.get(`SELECT * FROM users WHERE username = ?`, [username], async (err, user) => {
    if (err || !user) return res.status(400).json({ error: "Invalid credentials" });

    const ok = await bcrypt.compare(password, user.password_hash);
    if (!ok) return res.status(400).json({ error: "Invalid credentials" });

    const token = jwt.sign(
      { id: user.id, username: user.username, premium: user.premium },
      JWT_SECRET
    );

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        premium: !!user.premium
      }
    });
  });
});

// List users
app.get("/api/users", authMiddleware, (req, res) => {
  db.all(
    `SELECT id, username, premium FROM users WHERE id != ? ORDER BY username`,
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows.map(u => ({ ...u, premium: !!u.premium })));
    }
  );
});

// Get conversation
app.get("/api/messages/:otherUserId", authMiddleware, (req, res) => {
  const myId = req.user.id;
  const otherId = Number(req.params.otherUserId);

  db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC, id ASC
    `,
    [myId, otherId, otherId, myId],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

// Send message
app.post("/api/messages", authMiddleware, (req, res) => {
  const senderId = req.user.id;
  const { receiverId, content } = req.body;

  if (!receiverId || !content) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  // Monetization rule:
  // Non-premium users can only send messages up to 100 chars.
  if (!req.user.premium && content.length > 100) {
    return res.status(402).json({
      error: "Upgrade to premium to send messages longer than 100 characters"
    });
  }

  db.run(
    `INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)`,
    [senderId, receiverId, content],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      const message = {
        id: this.lastID,
        sender_id: senderId,
        receiver_id: receiverId,
        content,
        created_at: new Date().toISOString()
      };

      const receiverSocketId = onlineUsers.get(Number(receiverId));
      if (receiverSocketId) {
        io.to(receiverSocketId).emit("new_message", message);
        io.to(receiverSocketId).emit("notification", {
          type: "message",
          message: `New message from user ${senderId}`
        });
      }

      res.json({ success: true, message });
    }
  );
});

// Fake purchase endpoint
app.post("/api/purchase", authMiddleware, (req, res) => {
  const userId = req.user.id;
  const { item } = req.body;

  if (item !== "premium_unlock") {
    return res.status(400).json({ error: "Unknown item" });
  }

  // Simulate successful payment
  db.run(
    `INSERT INTO purchases (user_id, item, amount_cents) VALUES (?, ?, ?)`,
    [userId, item, 499],
    function (err) {
      if (err) return res.status(500).json({ error: "DB error" });

      db.run(
        `UPDATE users SET premium = 1 WHERE id = ?`,
        [userId],
        function (err2) {
          if (err2) return res.status(500).json({ error: "DB error" });

          const newToken = jwt.sign(
            { id: req.user.id, username: req.user.username, premium: 1 },
            JWT_SECRET
          );

          const socketId = onlineUsers.get(userId);
          if (socketId) {
            io.to(socketId).emit("notification", {
              type: "purchase",
              message: "Premium unlocked successfully"
            });
          }

          res.json({
            success: true,
            premium: true,
            token: newToken
          });
        }
      );
    }
  );
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
