# 5. `public/app.js`

```js
let token = localStorage.getItem("token") || "";
let currentUser = JSON.parse(localStorage.getItem("user") || "null");
let socket = null;
let selectedUser = null;

const authSection = document.getElementById("authSection");
const appSection = document.getElementById("appSection");
const meEl = document.getElementById("me");
const premiumBadge = document.getElementById("premiumBadge");
const usersList = document.getElementById("usersList");
const messagesEl = document.getElementById("messages");
const notificationsList = document.getElementById("notificationsList");
const chatTitle = document.getElementById("chatTitle");
const messageInput = document.getElementById("messageInput");

function setAuth(user, jwt) {
  currentUser = user;
  token = jwt;
  localStorage.setItem("token", jwt);
  localStorage.setItem("user", JSON.stringify(user));
}

function clearAuth() {
  currentUser = null;
  token = "";
  localStorage.removeItem("token");
  localStorage.removeItem("user");
}

function addNotification(text) {
  const li = document.createElement("li");
  li.textContent = `${new Date().toLocaleTimeString()} - ${text}`;
  notificationsList.prepend(li);
}

function renderSession() {
  if (!currentUser || !token) {
    authSection.classList.remove("hidden");
    appSection.classList.add("hidden");
    return;
  }

  authSection.classList.add("hidden");
  appSection.classList.remove("hidden");
  meEl.textContent = currentUser.username;
  premiumBadge.textContent = currentUser.premium ? "Premium" : "Free";
  premiumBadge.className = `badge ${currentUser.premium ? "premium" : ""}`;
}

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    ...options
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || "Request failed");
  return data;
}

async function loadUsers() {
  const users = await api("/api/users");
  usersList.innerHTML = "";
  users.forEach(user => {
    const li = document.createElement("li");
    li.innerHTML = `
      <button class="userBtn">
        ${user.username} ${user.premium ? "⭐" : ""}
      </button>
    `;
    li.querySelector("button").onclick = async () => {
      selectedUser = user;
      chatTitle.textContent = `Chat with ${user.username}`;
      await loadMessages();
    };
    usersList.appendChild(li);
  });
}

async function loadMessages() {
  if (!selectedUser) return;
  const msgs = await api(`/api/messages/${selectedUser.id}`);
  messagesEl.innerHTML = "";
  msgs.forEach(renderMessage);
  messagesEl.scrollTop = messagesEl.scrollHeight;
}

function renderMessage(msg) {
  const div = document.createElement("div");
  div.className = "message " + (msg.sender_id === currentUser.id ? "mine" : "theirs");
  div.textContent = msg.content;
  messagesEl.appendChild(div);
}

function connectSocket() {
  if (socket) socket.disconnect();

  socket = io({
    auth: { token }
  });

  socket.on("connect", () => {
    addNotification("Realtime connected");
  });

  socket.on("notification", (payload) => {
    addNotification(payload.message);
  });

  socket.on("new_message", (msg) => {
    if (selectedUser && (
      msg.sender_id === selectedUser.id || msg.receiver_id === selectedUser.id
    )) {
      renderMessage(msg);
      messagesEl.scrollTop = messagesEl.scrollHeight;
    }
    addNotification("You received a new message");
  });
}

document.getElementById("registerBtn").onclick = async () => {
  try {
    const username = document.getElementById("regUsername").value.trim();
    const password = document.getElementById("regPassword").value.trim();
    await api("/api/register", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    alert("Registered successfully. Please log in.");
  } catch (e) {
    alert(e.message);
  }
};

document.getElementById("loginBtn").onclick = async () => {
  try {
    const username = document.getElementById("loginUsername").value.trim();
    const password = document.getElementById("loginPassword").value.trim();
    const data = await api("/api/login", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    setAuth(data.user, data.token);
    renderSession();
    connectSocket();
    await loadUsers();
  } catch (e) {
    alert(e.message);
  }
};

document.getElementById("sendBtn").onclick = async () => {
  try {
    if (!selectedUser) return alert("Select a user first");
    const content = messageInput.value.trim();
    if (!content) return;

    const data = await api("/api/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content
      })
    });

    renderMessage(data.message);
    messageInput.value = "";
    messagesEl.scrollTop = messagesEl.scrollHeight;
  } catch (e) {
    alert(e.message);
  }
};

document.getElementById("buyPremiumBtn").onclick = async () => {
  try {
    const data = await api("/api/purchase", {
      method: "POST",
      body: JSON.stringify({ item: "premium_unlock" })
    });

    token = data.token;
    currentUser.premium = true;
    localStorage.setItem("token", token);
    localStorage.setItem("user", JSON.stringify(currentUser));
    renderSession();
    connectSocket();
    alert("Premium unlocked!");
  } catch (e) {
    alert(e.message);
  }
};

renderSession();
if (currentUser && token) {
  connectSocket();
  loadUsers().catch(console.error);
}
