## `server/src/routes/auth.js`

```js
import express from "express";
import bcrypt from "bcryptjs";
import { prisma } from "../db.js";
import { signToken, authMiddleware } from "../auth.js";

const router = express.Router();

router.post("/register", async (req, res) => {
  const { email, password, name } = req.body;

  if (!email || !password || !name) {
    return res.status(400).json({ error: "Missing fields" });
  }

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) {
    return res.status(400).json({ error: "Email already in use" });
  }

  const passwordHash = await bcrypt.hash(password, 10);
  const user = await prisma.user.create({
    data: { email, passwordHash, name }
  });

  const token = signToken(user);
  res.json({ token, user: { id: user.id, email: user.email, name: user.name, isPremium: user.isPremium } });
});

router.post("/login", async (req, res) => {
  const { email, password } = req.body;

  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = signToken(user);
  res.json({ token, user: { id: user.id, email: user.email, name: user.name, isPremium: user.isPremium } });
});

router.get("/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });
  res.json({ user: { id: user.id, email: user.email, name: user.name, isPremium: user.isPremium } });
});

router.get("/users", authMiddleware, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.id } },
    select: { id: true, name: true, email: true, isPremium: true }
  });
  res.json({ users });
});

export default router;
```

