export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [mode, setMode] = useState("login");

  const socket = useMemo(() => io(API, { autoConnect: false }), []);

  useEffect(() => {
    if (token && user) {
      socket.connect();
      socket.emit("register", user.id);

      socket.on("new_message", (message) => {
        if (
          selectedUser &&
          (message.senderId === selectedUser.id || message.receiverId === selectedUser.id)
        ) {
          setMessages((prev) => [...prev, message]);
        } else {
          alert(`New message from user ${message.senderId}`);
        }
      });

      loadUsers();

      return () => {
        socket.off("new_message");
        socket.disconnect();
      };
    }
  }, [token, user, selectedUser]);

  async function api(path, options = {}) {
    const res = await fetch(`${API}${path}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...(options.headers || {})
      }
    });
    return res.json();
  }

  async function handleAuth() {
    const path = mode === "login" ? "/auth/login" : "/auth/register";
    const body = mode === "login" ? { email, password } : { email, password, name };
    const data = await api(path, {
      method: "POST",
      body: JSON.stringify(body)
    });

    if (data.token) {
      setToken(data.token);
      setUser(data.user);
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
    } else {
      alert(data.error || "Auth failed");
    }
  }

  async function loadUsers() {
    const data = await api("/auth/users");
    setUsers(data.users || []);
  }

  async function loadMessages(otherUser) {
    setSelectedUser(otherUser);
    const data = await api(`/messages/${otherUser.id}`);
    setMessages(data.messages || []);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    const data = await api("/messages", {
      method: "POST",
      body: JSON.stringify({
        receiverId: selectedUser.id,
        content
      })
    });

    if (data.message) {
      setMessages((prev) => [...prev, data.message]);
      setContent("");
    }
  }

  async function upgradeToPremium() {
    const data = await api("/payments/create-checkout-session", {
      method: "POST"
    });
    if (data.url) {
      window.location.href = data.url;
    }
  }

  function logout() {
    localStorage.clear();
    setToken("");
    setUser(null);
    setUsers([]);
    setSelectedUser(null);
    setMessages([]);
  }

  if (!token || !user) {
    return (
      <div style={{ padding: 20, fontFamily: "Arial" }}>
        <h1>Social Messaging App</h1>
        <h2>{mode === "login" ? "Login" : "Register"}</h2>
        {mode === "register" && (
          <input
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{ display: "block", marginBottom: 10 }}
          />
        )}
        <input
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          style={{ display: "block", marginBottom: 10 }}
        />
        <input
          placeholder="Password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          style={{ display: "block", marginBottom: 10 }}
        />
        <button onClick={handleAuth}>
          {mode === "login" ? "Login" : "Register"}
        </button>
        <button onClick={() => setMode(mode === "login" ? "register" : "login")} style={{ marginLeft: 10 }}>
          Switch to {mode === "login" ? "Register" : "Login"}
        </button>
      </div>
    );
  }

  return (
    <div style={{ padding: 20, fontFamily: "Arial" }}>
      <h1>Social Messaging App</h1>
      <p>
        Logged in as <strong>{user.name}</strong> ({user.email}){" "}
        {user.isPremium ? "🌟 Premium" : ""}
      </p>

      {!user.isPremium && (
        <button onClick={upgradeToPremium}>Upgrade to Premium ($4.99)</button>
      )}

      <button onClick={logout} style={{ marginLeft: 10 }}>
        Logout
      </button>

      <div style={{ display: "flex", gap: 20, marginTop: 20 }}>
        <div style={{ width: 250 }}>
          <h3>Users</h3>
          {users.map((u) => (
            <div
              key={u.id}
              onClick={() => loadMessages(u)}
              style={{
                padding: 10,
                border: "1px solid #ccc",
                marginBottom: 8,
                cursor: "pointer",
                background: selectedUser?.id === u.id ? "#eee" : "#fff"
              }}
            >
              {u.name} {u.isPremium ? "🌟" : ""}
            </div>
          ))}
        </div>

        <div style={{ flex: 1 }}>
          <h3>
            Chat {selectedUser ? `with ${selectedUser.name}` : ""}
          </h3>

          <div
            style={{
              border: "1px solid #ccc",
              minHeight: 300,
              padding: 10,
              marginBottom: 10
            }}
          >
            {messages.map((m) => (
              <div key={m.id} style={{ marginBottom: 8 }}>
                <strong>{m.senderId === user.id ? "You" : selectedUser?.name}:</strong>{" "}
                {m.content}
              </div>
            ))}
          </div>

          {selectedUser && (
            <>
              <input
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Type a message"
                style={{ width: "80%", marginRight: 10 }}
              />
              <button onClick={sendMessage}>Send</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
