# 10. One more important webhook note

Because Stripe webhooks require the **raw body**, the current middleware ordering can be tricky. A safer `server/src/index.js` is:

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import authRoutes from "./routes/auth.js";
import messageRoutes from "./routes/messages.js";
import paymentRoutes from "./routes/payments.js";
import { initSocket } from "./socket.js";

dotenv.config();

const app = express();
const server = http.createServer(app);

app.use(cors({ origin: "http://localhost:5173" }));

app.use("/payments/webhook", express.raw({ type: "application/json" }));
app.use((req, res, next) => {
  if (req.originalUrl === "/payments/webhook") return next();
  express.json()(req, res, next);
});

app.use("/auth", authRoutes);
app.use("/messages", messageRoutes);
app.use("/payments", paymentRoutes);

initSocket(server);

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

