import express from 'express';
import cors from 'cors';
import dotenv from 'dotenv';
import { createServer } from 'http';
import { Server } from 'socket.io';
import Stripe from 'stripe';
import { v4 as uuidv4 } from 'uuid';
import db from './db.js';

dotenv.config();

const app = express();
const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ['GET', 'POST']
  }
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.use(cors({ origin: process.env.CLIENT_URL }));
app.use(express.json());

const onlineUsers = new Map();

io.on('connection', (socket) => {
  socket.on('register', (userId) => {
    onlineUsers.set(userId, socket.id);
    socket.data.userId = userId;
    console.log(`User connected: ${userId}`);
  });

  socket.on('disconnect', () => {
    if (socket.data.userId) {
      onlineUsers.delete(socket.data.userId);
      console.log(`User disconnected: ${socket.data.userId}`);
    }
  });
});

app.get('/users', (req, res) => {
  const users = db.prepare('SELECT id, username, coins FROM users').all();
  res.json(users);
});

app.post('/register', (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: 'Username required' });

  const id = uuidv4();
  try {
    db.prepare('INSERT INTO users (id, username) VALUES (?, ?)').run(id, username);
    const user = db.prepare('SELECT id, username, coins FROM users WHERE id = ?').get(id);
    res.json(user);
  } catch (e) {
    res.status(400).json({ error: 'Username already exists' });
  }
});

app.get('/messages/:userA/:userB', (req, res) => {
  const { userA, userB } = req.params;
  const messages = db.prepare(`
    SELECT * FROM messages
    WHERE (senderId = ? AND receiverId = ?)
       OR (senderId = ? AND receiverId = ?)
    ORDER BY createdAt ASC
  `).all(userA, userB, userB, userA);

  res.json(messages);
});

app.post('/messages', (req, res) => {
  const { senderId, receiverId, content } = req.body;
  if (!senderId || !receiverId || !content) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const message = {
    id: uuidv4(),
    senderId,
    receiverId,
    content,
    createdAt: new Date().toISOString()
  };

  db.prepare(`
    INSERT INTO messages (id, senderId, receiverId, content, createdAt)
    VALUES (?, ?, ?, ?, ?)
  `).run(message.id, message.senderId, message.receiverId, message.content, message.createdAt);

  const receiverSocketId = onlineUsers.get(receiverId);
  if (receiverSocketId) {
    io.to(receiverSocketId).emit('new_message', message);
    io.to(receiverSocketId).emit('notification', {
      type: 'message',
      text: `New message from ${senderId}`
    });
  }

  res.json(message);
});

app.post('/create-checkout-session', async (req, res) => {
  const { userId } = req.body;
  const user = db.prepare('SELECT * FROM users WHERE id = ?').get(userId);

  if (!user) return res.status(404).json({ error: 'User not found' });

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: 'usd',
          product_data: {
            name: '100 Coins'
          },
          unit_amount: 500
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}?success=1&userId=${userId}`,
    cancel_url: `${process.env.CLIENT_URL}?canceled=1`
  });

  res.json({ url: session.url });
});

app.post('/payment-success', (req, res) => {
  const { userId } = req.body;
  db.prepare('UPDATE users SET coins = coins + 100 WHERE id = ?').run(userId);
  const updated = db.prepare('SELECT id, username, coins FROM users WHERE id = ?').get(userId);
  res.json(updated);
});

httpServer.listen(process.env.PORT, () => {
  console.log(`Server running on http://localhost:${process.env.PORT}`);
});
```

