```jsx
import React, { useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import {
  register,
  getUsers,
  getMessages,
  sendMessage,
  createCheckoutSession,
  paymentSuccess
} from './api';

const socket = io('http://localhost:4000');

export default function App() {
  const [username, setUsername] = useState('');
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState('');
  const [notification, setNotification] = useState('');

  const query = useMemo(() => new URLSearchParams(window.location.search), []);

  useEffect(() => {
    const success = query.get('success');
    const userId = query.get('userId');
    if (success && userId) {
      paymentSuccess(userId).then((updatedUser) => {
        setMe(updatedUser);
        window.history.replaceState({}, '', '/');
      });
    }
  }, [query]);

  useEffect(() => {
    if (!me) return;
    socket.emit('register', me.id);
    loadUsers();

    socket.on('new_message', (msg) => {
      if (
        selectedUser &&
        (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on('notification', (n) => {
      setNotification(n.text);
      setTimeout(() => setNotification(''), 3000);
    });

    return () => {
      socket.off('new_message');
      socket.off('notification');
    };
  }, [me, selectedUser]);

  async function loadUsers() {
    const all = await getUsers();
    setUsers(all.filter((u) => u.id !== me?.id));
  }

  async function handleRegister() {
    const user = await register(username);
    if (user.error) {
      alert(user.error);
      return;
    }
    setMe(user);
  }

  async function openChat(user) {
    setSelectedUser(user);
    const msgs = await getMessages(me.id, user.id);
    setMessages(msgs);
  }

  async function handleSend() {
    if (!text.trim() || !selectedUser) return;
    const msg = await sendMessage(me.id, selectedUser.id, text);
    setMessages((prev) => [...prev, msg]);
    setText('');
  }

  async function handleBuyCoins() {
    const session = await createCheckoutSession(me.id);
    window.location.href = session.url;
  }

  if (!me) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Register</h2>
        <input
          placeholder="username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={handleRegister}>Join</button>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', height: '100vh', fontFamily: 'Arial' }}>
      <div style={{ width: 250, borderRight: '1px solid #ccc', padding: 12 }}>
        <h3>{me.username}</h3>
        <p>Coins: {me.coins}</p>
        <button onClick={handleBuyCoins}>Buy 100 Coins ($5)</button>
        <hr />
        <h4>Users</h4>
        {users.map((u) => (
          <div
            key={u.id}
            style={{ padding: 8, cursor: 'pointer', background: selectedUser?.id === u.id ? '#eee' : 'transparent' }}
            onClick={() => openChat(u)}
          >
            {u.username}
          </div>
        ))}
      </div>

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: 12, borderBottom: '1px solid #ccc' }}>
          {selectedUser ? `Chat with ${selectedUser.username}` : 'Select a user'}
          {notification && (
            <div style={{ color: 'green', marginTop: 8 }}>{notification}</div>
          )}
        </div>

        <div style={{ flex: 1, overflowY: 'auto', padding: 12 }}>
          {messages.map((m) => (
            <div
              key={m.id}
              style={{
                textAlign: m.senderId === me.id ? 'right' : 'left',
                marginBottom: 8
              }}
            >
              <span
                style={{
                  display: 'inline-block',
                  padding: '8px 12px',
                  borderRadius: 12,
                  background: m.senderId === me.id ? '#d1e7dd' : '#f8d7da'
                }}
              >
                {m.content}
              </span>
            </div>
          ))}
        </div>

        {selectedUser && (
          <div style={{ display: 'flex', padding: 12, borderTop: '1px solid #ccc' }}>
            <input
              style={{ flex: 1, marginRight: 8 }}
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type a message"
            />
            <button onClick={handleSend}>Send</button>
          </div>
        )}
      </div>
    </div>
  );
}
