# 12. Stripe webhook

You’ll usually want a service-role Supabase client here, but for a minimal example:

## `app/api/stripe/webhook/route.ts`

```ts
import { headers } from 'next/headers';
import { NextResponse } from 'next/server';
import { stripe } from '@/lib/stripe';
import { createClient } from '@supabase/supabase-js';

export async function POST(req: Request) {
  const body = await req.text();
  const sig = headers().get('stripe-signature')!;
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!
    );
  } catch (err: any) {
    return new NextResponse(`Webhook Error: ${err.message}`, { status: 400 });
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object as any;

    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    );

    // In production, attach user ID in metadata and use service role key.
    const userId = session.metadata?.userId;

    if (userId) {
      await supabase.from('profiles').update({ is_pro: true }).eq('id', userId);
    }
  }

  return NextResponse.json({ received: true });
}
```

