## `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory data
const users = [
  { id: "u1", username: "alice", password: "1234", premium: false },
  { id: "u2", username: "bob", password: "1234", premium: false }
];

const messages = [];
const notifications = [];
const onlineUsers = new Map(); // userId -> socketId

function auth(req, res, next) {
  const userId = req.headers["x-user-id"];
  const user = users.find((u) => u.id === userId);
  if (!user) return res.status(401).json({ error: "Unauthorized" });
  req.user = user;
  next();
}

// Auth routes
app.post("/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }
  if (users.find((u) => u.username === username)) {
    return res.status(400).json({ error: "username already exists" });
  }

  const user = { id: uuidv4(), username, password, premium: false };
  users.push(user);
  res.json({ user: { id: user.id, username: user.username, premium: user.premium } });
});

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = users.find((u) => u.username === username && u.password === password);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  res.json({
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

// User listing
app.get("/users", auth, (req, res) => {
  res.json(
    users
      .filter((u) => u.id !== req.user.id)
      .map((u) => ({ id: u.id, username: u.username, premium: u.premium }))
  );
});

// Messages
app.get("/messages/:otherUserId", auth, (req, res) => {
  const { otherUserId } = req.params;
  const convo = messages.filter(
    (m) =>
      (m.from === req.user.id && m.to === otherUserId) ||
      (m.from === otherUserId && m.to === req.user.id)
  );
  res.json(convo);
});

app.post("/messages", auth, (req, res) => {
  const { to, text } = req.body;
  if (!to || !text) return res.status(400).json({ error: "to and text required" });

  const msg = {
    id: uuidv4(),
    from: req.user.id,
    to,
    text,
    createdAt: Date.now()
  };
  messages.push(msg);

  const notification = {
    id: uuidv4(),
    userId: to,
    type: "message",
    text: `${req.user.username} sent you a message`,
    createdAt: Date.now(),
    read: false
  };
  notifications.push(notification);

  const recipientSocketId = onlineUsers.get(to);
  if (recipientSocketId) {
    io.to(recipientSocketId).emit("message:new", msg);
    io.to(recipientSocketId).emit("notification:new", notification);
  }

  res.json(msg);
});

// Notifications
app.get("/notifications", auth, (req, res) => {
  const userNotifications = notifications.filter((n) => n.userId === req.user.id);
  res.json(userNotifications);
});

app.post("/notifications/:id/read", auth, (req, res) => {
  const n = notifications.find((x) => x.id === req.params.id && x.userId === req.user.id);
  if (!n) return res.status(404).json({ error: "Notification not found" });
  n.read = true;
  res.json(n);
});

// Monetization: fake premium purchase
app.post("/purchase/premium", auth, (req, res) => {
  req.user.premium = true;

  const notification = {
    id: uuidv4(),
    userId: req.user.id,
    type: "purchase",
    text: "Premium unlocked successfully",
    createdAt: Date.now(),
    read: false
  };
  notifications.push(notification);

  const socketId = onlineUsers.get(req.user.id);
  if (socketId) {
    io.to(socketId).emit("notification:new", notification);
    io.to(socketId).emit("premium:updated", { premium: true });
  }

  res.json({
    success: true,
    premium: true
  });
});

// Socket.IO
io.on("connection", (socket) => {
  socket.on("auth", ({ userId }) => {
    onlineUsers.set(userId, socket.id);
    socket.data.userId = userId;
    socket.emit("connected", { ok: true });
  });

  socket.on("disconnect", () => {
    if (socket.data.userId) {
      onlineUsers.delete(socket.data.userId);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

