```jsx
import React, { useEffect, useMemo, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";

export default function App() {
  const [mode, setMode] = useState("login");
  const [authForm, setAuthForm] = useState({ username: "", password: "" });
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [error, setError] = useState("");

  const unreadCount = useMemo(
    () => notifications.filter((n) => !n.read).length,
    [notifications]
  );

  useEffect(() => {
    if (!user) return;

    socket.emit("auth", { userId: user.id });

    socket.on("message:new", (msg) => {
      if (
        selectedUser &&
        (msg.from === selectedUser.id || msg.to === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification:new", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    socket.on("premium:updated", ({ premium }) => {
      setUser((prev) => ({ ...prev, premium }));
    });

    return () => {
      socket.off("message:new");
      socket.off("notification:new");
      socket.off("premium:updated");
    };
  }, [user, selectedUser]);

  async function handleAuth() {
    try {
      setError("");
      const path = mode === "login" ? "/login" : "/register";
      const res = await api(path, "POST", authForm);
      setUser(res.user);
      const [usersRes, notificationsRes] = await Promise.all([
        api("/users", "GET", undefined, res.user.id),
        api("/notifications", "GET", undefined, res.user.id)
      ]);
      setUsers(usersRes);
      setNotifications(notificationsRes.reverse());
    } catch (e) {
      setError(e.message);
    }
  }

  async function openChat(other) {
    setSelectedUser(other);
    const convo = await api(`/messages/${other.id}`, "GET", undefined, user.id);
    setMessages(convo);
  }

  async function sendMessage() {
    if (!text.trim() || !selectedUser) return;
    const msg = await api(
      "/messages",
      "POST",
      { to: selectedUser.id, text },
      user.id
    );
    setMessages((prev) => [...prev, msg]);
    setText("");
  }

  async function markRead(id) {
    const updated = await api(`/notifications/${id}/read`, "POST", {}, user.id);
    setNotifications((prev) => prev.map((n) => (n.id === id ? updated : n)));
  }

  async function buyPremium() {
    const res = await api("/purchase/premium", "POST", {}, user.id);
    setUser((prev) => ({ ...prev, premium: res.premium }));
  }

  if (!user) {
    return (
      <div style={{ padding: 20, fontFamily: "Arial" }}>
        <h1>Social Messaging App</h1>
        <div style={{ marginBottom: 12 }}>
          <button onClick={() => setMode("login")}>Login</button>
          <button onClick={() => setMode("register")} style={{ marginLeft: 8 }}>
            Register
          </button>
        </div>

        <input
          placeholder="username"
          value={authForm.username}
          onChange={(e) => setAuthForm({ ...authForm, username: e.target.value })}
        />
        <br />
        <br />
        <input
          placeholder="password"
          type="password"
          value={authForm.password}
          onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })}
        />
        <br />
        <br />
        <button onClick={handleAuth}>
          {mode === "login" ? "Login" : "Register"}
        </button>

        {error && <p style={{ color: "red" }}>{error}</p>}
        <p>Demo users: alice / 1234, bob / 1234</p>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", fontFamily: "Arial", height: "100vh" }}>
      <div style={{ width: 250, borderRight: "1px solid #ccc", padding: 12 }}>
        <h3>{user.username}</h3>
        <p>
          Plan: <strong>{user.premium ? "Premium" : "Free"}</strong>
        </p>
        {!user.premium && <button onClick={buyPremium}>Unlock Premium</button>}

        <hr />
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id} style={{ marginBottom: 8 }}>
            <button onClick={() => openChat(u)}>
              {u.username} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}

        <hr />
        <h4>Notifications ({unreadCount})</h4>
        <div style={{ maxHeight: 250, overflow: "auto" }}>
          {notifications.map((n) => (
            <div
              key={n.id}
              style={{
                padding: 8,
                marginBottom: 6,
                background: n.read ? "#f3f3f3" : "#dff0ff",
                borderRadius: 6
              }}
            >
              <div>{n.text}</div>
              <small>{new Date(n.createdAt).toLocaleTimeString()}</small>
              {!n.read && (
                <div>
                  <button onClick={() => markRead(n.id)}>Mark read</button>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      <div style={{ flex: 1, padding: 12 }}>
        {selectedUser ? (
          <>
            <h3>Chat with {selectedUser.username}</h3>
            <div
              style={{
                border: "1px solid #ccc",
                height: "70vh",
                overflow: "auto",
                padding: 12,
                marginBottom: 12
              }}
            >
              {messages.map((m) => (
                <div
                  key={m.id}
                  style={{
                    textAlign: m.from === user.id ? "right" : "left",
                    marginBottom: 10
                  }}
                >
                  <span
                    style={{
                      display: "inline-block",
                      padding: 8,
                      borderRadius: 8,
                      background: m.from === user.id ? "#cfe9ff" : "#eee"
                    }}
                  >
                    {m.text}
                  </span>
                </div>
              ))}
            </div>

            <input
              style={{ width: "80%" }}
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type a message"
            />
            <button onClick={sendMessage} style={{ marginLeft: 8 }}>
              Send
            </button>
          </>
        ) : (
          <h3>Select a user to start chatting</h3>
        )}
      </div>
    </div>
  );
}
