```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory store
const users = [];
const messages = [];
const sessions = new Map(); // token -> userId
const onlineUsers = new Map(); // userId -> socketId

function auth(req, res, next) {
  const token = req.headers.authorization?.replace("Bearer ", "");
  if (!token || !sessions.has(token)) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  req.userId = sessions.get(token);
  next();
}

// Register/Login
app.post("/auth/register", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "Username required" });

  let user = users.find((u) => u.username === username);
  if (!user) {
    user = {
      id: uuidv4(),
      username,
      premium: false
    };
    users.push(user);
  }

  const token = uuidv4();
  sessions.set(token, user.id);

  res.json({ token, user });
});

// Get all users
app.get("/users", auth, (req, res) => {
  res.json(users.filter((u) => u.id !== req.userId));
});

// Get conversation
app.get("/messages/:withUserId", auth, (req, res) => {
  const { withUserId } = req.params;
  const convo = messages.filter(
    (m) =>
      (m.from === req.userId && m.to === withUserId) ||
      (m.from === withUserId && m.to === req.userId)
  );
  res.json(convo);
});

// Send message
app.post("/messages", auth, (req, res) => {
  const { to, text } = req.body;
  if (!to || !text) return res.status(400).json({ error: "to and text required" });

  const msg = {
    id: uuidv4(),
    from: req.userId,
    to,
    text,
    createdAt: new Date().toISOString()
  };

  messages.push(msg);

  const targetSocket = onlineUsers.get(to);
  if (targetSocket) {
    io.to(targetSocket).emit("new_message", msg);
    io.to(targetSocket).emit("notification", {
      type: "message",
      text: "You received a new message"
    });
  }

  res.json(msg);
});

// Mock premium purchase
app.post("/purchase/premium", auth, (req, res) => {
  const user = users.find((u) => u.id === req.userId);
  if (!user) return res.status(404).json({ error: "User not found" });

  user.premium = true;
  res.json({ success: true, premium: true });
});

// Premium-only feature
app.get("/premium/stickers", auth, (req, res) => {
  const user = users.find((u) => u.id === req.userId);
  if (!user?.premium) {
    return res.status(403).json({ error: "Premium required" });
  }

  res.json([
    "🔥",
    "🚀",
    "💎",
    "🎉"
  ]);
});

// Socket auth
io.on("connection", (socket) => {
  socket.on("identify", ({ token }) => {
    const userId = sessions.get(token);
    if (!userId) return;
    onlineUsers.set(userId, socket.id);
    socket.data.userId = userId;
  });

  socket.on("disconnect", () => {
    if (socket.data.userId) {
      onlineUsers.delete(socket.data.userId);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

