import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(
    JSON.parse(localStorage.getItem("user") || "null")
  );
  const [username, setUsername] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [stickers, setStickers] = useState([]);

  const socket = useMemo(() => io(API, { autoConnect: false }), []);

  useEffect(() => {
    if (!token) return;
    socket.connect();
    socket.emit("identify", { token });

    socket.on("new_message", (msg) => {
      if (
        selectedUser &&
        (msg.from === selectedUser.id || msg.to === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    });

    return () => {
      socket.off("new_message");
      socket.off("notification");
      socket.disconnect();
    };
  }, [token, selectedUser, socket]);

  async function login() {
    const res = await fetch(`${API}/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const data = await res.json();
    setToken(data.token);
    setUser(data.user);
    localStorage.setItem("token", data.token);
    localStorage.setItem("user", JSON.stringify(data.user));
    loadUsers(data.token);
  }

  async function loadUsers(currentToken = token) {
    const res = await fetch(`${API}/users`, {
      headers: { Authorization: `Bearer ${currentToken}` }
    });
    const data = await res.json();
    setUsers(data);
  }

  async function loadMessages(otherUser) {
    setSelectedUser(otherUser);
    const res = await fetch(`${API}/messages/${otherUser.id}`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    setMessages(data);
  }

  async function sendMessage() {
    if (!selectedUser || !text.trim()) return;
    const res = await fetch(`${API}/messages`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ to: selectedUser.id, text })
    });
    const msg = await res.json();
    setMessages((prev) => [...prev, msg]);
    setText("");
  }

  async function buyPremium() {
    const res = await fetch(`${API}/purchase/premium`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    const updatedUser = { ...user, premium: data.premium };
    setUser(updatedUser);
    localStorage.setItem("user", JSON.stringify(updatedUser));
  }

  async function loadStickers() {
    const res = await fetch(`${API}/premium/stickers`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    if (Array.isArray(data)) setStickers(data);
    else alert(data.error || "Could not load stickers");
  }

  useEffect(() => {
    if (token) loadUsers();
  }, [token]);

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Login / Register</h1>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Username"
        />
        <button onClick={login}>Continue</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "Arial" }}>
      <div style={{ width: 250, borderRight: "1px solid #ccc", padding: 10 }}>
        <h3>{user?.username}</h3>
        <p>{user?.premium ? "Premium User" : "Free User"}</p>
        {!user?.premium && <button onClick={buyPremium}>Buy Premium</button>}
        <button onClick={loadStickers} style={{ marginLeft: 8 }}>
          Load Stickers
        </button>

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => loadMessages(u)}>
              {u.username}
            </button>
          </div>
        ))}

        <h4>Notifications</h4>
        {notifications.map((n, i) => (
          <div key={i} style={{ fontSize: 12, marginBottom: 6 }}>
            {n.text}
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 10 }}>
        <h2>
          Chat {selectedUser ? `with ${selectedUser.username}` : ""}
        </h2>

        <div
          style={{
            border: "1px solid #ccc",
            height: "70vh",
            overflowY: "auto",
            padding: 10,
            marginBottom: 10
          }}
        >
          {messages.map((m) => (
            <div key={m.id} style={{ marginBottom: 8 }}>
              <b>{m.from === user.id ? "Me" : selectedUser?.username}:</b> {m.text}
            </div>
          ))}
        </div>

        {selectedUser && (
          <>
            <input
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type a message"
            />
            <button onClick={sendMessage}>Send</button>
          </>
        )}

        {stickers.length > 0 && (
          <div style={{ marginTop: 20 }}>
            <h4>Premium Stickers</h4>
            {stickers.map((s, i) => (
              <button
                key={i}
                onClick={() => setText((prev) => prev + s)}
                style={{ fontSize: 24, marginRight: 8 }}
              >
                {s}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
