  cors: {
    origin: "*"
  }
});

// In-memory data store
const users = new Map(); // userId -> { id, username, premium }
const messages = []; // { id, from, to, text, createdAt }
const socketsByUser = new Map(); // userId -> socket.id

// Simple auth/register
app.post("/auth/login", (req, res) => {
  const { username } = req.body;
  if (!username?.trim()) {
    return res.status(400).json({ error: "Username required" });
  }

  let existing = [...users.values()].find(
    (u) => u.username.toLowerCase() === username.toLowerCase()
  );

  if (!existing) {
    existing = {
      id: uuid(),
      username,
      premium: false
    };
    users.set(existing.id, existing);
  }

  res.json(existing);
});

// List users
app.get("/users", (req, res) => {
  res.json([...users.values()]);
});

// Get messages between two users
app.get("/messages", (req, res) => {
  const { userId, peerId } = req.query;
  const convo = messages.filter(
    (m) =>
      (m.from === userId && m.to === peerId) ||
      (m.from === peerId && m.to === userId)
  );
  res.json(convo);
});

// Send message
app.post("/messages", (req, res) => {
  const { from, to, text } = req.body;

  if (!from || !to || !text?.trim()) {
    return res.status(400).json({ error: "Invalid payload" });
  }

  const sender = users.get(from);
  const recipient = users.get(to);

  if (!sender || !recipient) {
    return res.status(404).json({ error: "User not found" });
  }

  // Monetization rule:
  // free users can only send first 5 messages total
  const sentCount = messages.filter((m) => m.from === from).length;
  if (!sender.premium && sentCount >= 5) {
    return res.status(402).json({
      error: "Free message limit reached. Upgrade to premium."
    });
  }

  const msg = {
    id: uuid(),
    from,
    to,
    text,
    createdAt: new Date().toISOString()
  };

  messages.push(msg);

  // Real-time delivery
  const targetSocketId = socketsByUser.get(to);
  if (targetSocketId) {
    io.to(targetSocketId).emit("message:new", msg);
    io.to(targetSocketId).emit("notification", {
      type: "NEW_MESSAGE",
      from,
      text: text.slice(0, 80)
    });
  }

  // Echo to sender too
  const senderSocketId = socketsByUser.get(from);
  if (senderSocketId) {
    io.to(senderSocketId).emit("message:new", msg);
  }

  res.json(msg);
});

// Mock purchase endpoint
app.post("/billing/upgrade", (req, res) => {
  const { userId } = req.body;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  user.premium = true;
  users.set(user.id, user);

  const socketId = socketsByUser.get(user.id);
  if (socketId) {
    io.to(socketId).emit("notification", {
      type: "PREMIUM_UPGRADED",
      message: "You are now premium!"
    });
  }

  res.json({ success: true, user });
});

io.on("connection", (socket) => {
  socket.on("identify", (userId) => {
    socketsByUser.set(userId, socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of socketsByUser.entries()) {
      if (socketId === socket.id) {
        socketsByUser.delete(userId);
        break;
      }
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
