```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";
const socket = io(API, { autoConnect: true });

export default function App() {
  const [username, setUsername] = useState("");
  const [me, setMe] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);

  async function login() {
    const res = await fetch(`${API}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const user = await res.json();
    setMe(user);
    socket.emit("identify", user.id);
  }

  async function loadUsers() {
    const res = await fetch(`${API}/users`);
    const data = await res.json();
    setUsers(data);
  }

  async function loadMessages(peerId) {
    if (!me || !peerId) return;
    const res = await fetch(
      `${API}/messages?userId=${me.id}&peerId=${peerId}`
    );
    const data = await res.json();
    setMessages(data);
  }

  async function sendMessage() {
    if (!selectedUser || !text.trim()) return;

    const res = await fetch(`${API}/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        from: me.id,
        to: selectedUser.id,
        text
      })
    });

    const data = await res.json();

    if (!res.ok) {
      alert(data.error || "Failed to send");
      return;
    }

    setText("");
  }

  async function upgrade() {
    const res = await fetch(`${API}/billing/upgrade`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: me.id })
    });
    const data = await res.json();
    if (data.user) setMe(data.user);
  }

  useEffect(() => {
    loadUsers();
    const interval = setInterval(loadUsers, 3000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (selectedUser) loadMessages(selectedUser.id);
  }, [selectedUser, me]);

  useEffect(() => {
    socket.on("message:new", (msg) => {
      if (
        me &&
        selectedUser &&
        ((msg.from === me.id && msg.to === selectedUser.id) ||
          (msg.from === selectedUser.id && msg.to === me.id))
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev].slice(0, 5));
    });

    return () => {
      socket.off("message:new");
      socket.off("notification");
    };
  }, [me, selectedUser]);

  const visibleUsers = useMemo(() => {
    if (!me) return [];
    return users.filter((u) => u.id !== me.id);
  }, [users, me]);

  if (!me) {
    return (
      <div className="container auth">
        <h1>Mini Social Messenger</h1>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Enter username"
        />
        <button onClick={login}>Login / Register</button>
      </div>
    );
  }

  return (
    <div className="container app">
      <aside className="sidebar">
        <h2>{me.username}</h2>
        <div className="badge">{me.premium ? "Premium" : "Free"}</div>
        {!me.premium && <button onClick={upgrade}>Upgrade</button>}

        <h3>Users</h3>
        {visibleUsers.map((u) => (
          <button
            key={u.id}
            className={`userBtn ${selectedUser?.id === u.id ? "active" : ""}`}
            onClick={() => setSelectedUser(u)}
          >
            {u.username}
          </button>
        ))}

        <h3>Notifications</h3>
        <div className="notifications">
          {notifications.map((n, i) => (
            <div key={i} className="notif">
              {n.type === "NEW_MESSAGE"
                ? `New message: ${n.text}`
                : n.message || n.type}
            </div>
          ))}
        </div>
      </aside>

      <main className="chat">
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.username}</h2>
            <div className="messages">
              {messages.map((m) => (
                <div
                  key={m.id}
                  className={`message ${m.from === me.id ? "mine" : "theirs"}`}
                >
                  <div>{m.text}</div>
                  <small>{new Date(m.createdAt).toLocaleTimeString()}</small>
                </div>
              ))}
            </div>
            <div className="composer">
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Type a message"
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <div className="empty">Select a user to start chatting</div>
        )}
      </main>
    </div>
  );
}
```

