```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"]
  }
});

// In-memory data
const users = new Map(); // userId -> { id, username, premium }
const messages = []; // { id, from, to, text, ts }
const onlineUsers = new Map(); // userId -> socketId

// Simple auth/register
app.post("/auth/login", (req, res) => {
  const { username } = req.body;
  if (!username?.trim()) {
    return res.status(400).json({ error: "Username required" });
  }

  let existing = [...users.values()].find((u) => u.username === username);
  if (!existing) {
    existing = { id: uuidv4(), username, premium: false };
    users.set(existing.id, existing);
  }

  res.json(existing);
});

// List users
app.get("/users", (req, res) => {
  res.json([...users.values()]);
});

// Get messages between two users
app.get("/messages", (req, res) => {
  const { user1, user2 } = req.query;
  const convo = messages.filter(
    (m) =>
      (m.from === user1 && m.to === user2) ||
      (m.from === user2 && m.to === user1)
  );
  res.json(convo);
});

// Mock monetization endpoint
app.post("/purchase/premium", (req, res) => {
  const { userId } = req.body;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  user.premium = true;
  users.set(userId, user);

  io.to(userId).emit("premium-updated", { premium: true });

  res.json({
    success: true,
    message: "Premium unlocked",
    user
  });
});

io.on("connection", (socket) => {
  socket.on("join", ({ userId }) => {
    onlineUsers.set(userId, socket.id);
    socket.join(userId);
    io.emit("presence", [...onlineUsers.keys()]);
  });

  socket.on("send-message", ({ from, to, text }) => {
    const msg = {
      id: uuidv4(),
      from,
      to,
      text,
      ts: Date.now()
    };

    messages.push(msg);

    io.to(to).emit("new-message", msg);
    io.to(from).emit("new-message", msg);

    io.to(to).emit("notification", {
      type: "message",
      title: "New message",
      body: text
    });
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) {
        onlineUsers.delete(userId);
        break;
      }
    }
    io.emit("presence", [...onlineUsers.keys()]);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

