```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:4000";
const socket = io(API, { autoConnect: false });

export default function App() {
  const [me, setMe] = useState(null);
  const [username, setUsername] = useState("");
  const [users, setUsers] = useState([]);
  const [online, setOnline] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);

  const otherUsers = useMemo(
    () => users.filter((u) => u.id !== me?.id),
    [users, me]
  );

  async function login() {
    const res = await fetch(`${API}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const user = await res.json();
    setMe(user);
  }

  async function loadUsers() {
    const res = await fetch(`${API}/users`);
    const data = await res.json();
    setUsers(data);
  }

  async function loadMessages(userId) {
    if (!me || !userId) return;
    const res = await fetch(
      `${API}/messages?user1=${me.id}&user2=${userId}`
    );
    const data = await res.json();
    setMessages(data);
  }

  async function buyPremium() {
    const res = await fetch(`${API}/purchase/premium`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: me.id })
    });
    const data = await res.json();
    setMe(data.user);
  }

  function sendMessage() {
    if (!text.trim() || !selectedUser || !me) return;
    socket.emit("send-message", {
      from: me.id,
      to: selectedUser.id,
      text
    });
    setText("");
  }

  useEffect(() => {
    loadUsers();
  }, []);

  useEffect(() => {
    if (!me) return;

    socket.connect();
    socket.emit("join", { userId: me.id });

    socket.on("new-message", (msg) => {
      const isCurrentChat =
        selectedUser &&
        ((msg.from === me.id && msg.to === selectedUser.id) ||
          (msg.from === selectedUser.id && msg.to === me.id));

      if (isCurrentChat) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev.slice(0, 4)]);
    });

    socket.on("presence", (onlineIds) => {
      setOnline(onlineIds);
    });

    socket.on("premium-updated", ({ premium }) => {
      setMe((prev) => ({ ...prev, premium }));
    });

    loadUsers();

    return () => {
      socket.off("new-message");
      socket.off("notification");
      socket.off("presence");
      socket.off("premium-updated");
    };
  }, [me, selectedUser]);

  useEffect(() => {
    if (selectedUser) loadMessages(selectedUser.id);
  }, [selectedUser, me]);

  if (!me) {
    return (
      <div className="container auth">
        <h1>Mini Social Messenger</h1>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Enter username"
        />
        <button onClick={login}>Login / Register</button>
      </div>
    );
  }

  return (
    <div className="container app">
      <aside className="sidebar">
        <h2>{me.username}</h2>
        <p>Status: {me.premium ? "Premium" : "Free"}</p>
        {!me.premium && <button onClick={buyPremium}>Unlock Premium</button>}

        <h3>Users</h3>
        {otherUsers.map((u) => (
          <div
            key={u.id}
            className={`user ${selectedUser?.id === u.id ? "active" : ""}`}
            onClick={() => setSelectedUser(u)}
          >
            <span>{u.username}</span>
            <span className={online.includes(u.id) ? "online" : "offline"}>
              {online.includes(u.id) ? "●" : "○"}
            </span>
          </div>
        ))}

        <h3>Notifications</h3>
        <div className="notifications">
          {notifications.map((n, i) => (
            <div key={i} className="notif">
              <strong>{n.title}</strong>
              <p>{n.body}</p>
            </div>
          ))}
        </div>
      </aside>

      <main className="chat">
        {selectedUser ? (
          <>
            <div className="chat-header">
              Chat with {selectedUser.username}
            </div>

            <div className="messages">
              {messages.map((m) => (
                <div
                  key={m.id}
                  className={`message ${m.from === me.id ? "mine" : "theirs"}`}
                >
                  {m.text}
                </div>
              ))}
            </div>

            <div className="composer">
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Type a message"
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <div className="empty">Select a user to start chatting</div>
        )}
      </main>
    </div>
  );
}
