import { useEffect, useState } from 'react'
import io from 'socket.io-client'

let socket

export default function Home() {
  const [user, setUser] = useState(null)
  const [messages, setMessages] = useState([])
  const [form, setForm] = useState({ email: '', password: '', name: '' })
  const [isLogin, setIsLogin] = useState(true)
  const [content, setContent] = useState('')

  async function loadMe() {
    const res = await fetch('/api/me')
    const data = await res.json()
    setUser(data.user)
  }

  async function loadMessages() {
    const res = await fetch('/api/messages')
    const data = await res.json()
    setMessages(data.reverse())
  }

  useEffect(() => {
    loadMe()
    loadMessages()

    fetch('/api/socket').then(() => {
      socket = io()

      socket.on('new-message', (message) => {
        setMessages((prev) => [...prev, message])
      })
    })

    return () => {
      if (socket) socket.disconnect()
    }
  }, [])

  async function handleAuth(e) {
    e.preventDefault()
    const endpoint = isLogin ? '/api/login' : '/api/signup'
    const payload = isLogin
      ? { email: form.email, password: form.password }
      : form

    const res = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })

    const data = await res.json()
    if (data.user) {
      setUser(data.user)
      setForm({ email: '', password: '', name: '' })
    } else {
      alert(data.error || 'Error')
    }
  }

  async function sendMessage(e) {
    e.preventDefault()
    if (!content.trim()) return

    const res = await fetch('/api/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content })
    })

    const data = await res.json()
    if (data.error) {
      alert(data.error)
    } else {
      setContent('')
    }
  }

  async function upgrade() {
    const res = await fetch('/api/upgrade', { method: 'POST' })
    const data = await res.json()
    if (data.user) setUser(data.user)
  }

  async function logout() {
    await fetch('/api/logout')
    setUser(null)
  }

  return (
    <main style={{ maxWidth: 700, margin: '40px auto', fontFamily: 'Arial' }}>
      <h1>Mini Social Messaging App</h1>

      {!user ? (
        <div style={{ border: '1px solid #ccc', padding: 20, marginBottom: 20 }}>
          <h2>{isLogin ? 'Login' : 'Sign Up'}</h2>
          <form onSubmit={handleAuth}>
            {!isLogin && (
              <input
                placeholder="Name"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                style={{ display: 'block', marginBottom: 10, width: '100%', padding: 8 }}
              />
            )}
            <input
              placeholder="Email"
              value={form.email}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
              style={{ display: 'block', marginBottom: 10, width: '100%', padding: 8 }}
            />
            <input
              type="password"
              placeholder="Password"
              value={form.password}
              onChange={(e) => setForm({ ...form, password: e.target.value })}
              style={{ display: 'block', marginBottom: 10, width: '100%', padding: 8 }}
            />
            <button type="submit">{isLogin ? 'Login' : 'Create account'}</button>
          </form>
          <button onClick={() => setIsLogin(!isLogin)} style={{ marginTop: 10 }}>
            Switch to {isLogin ? 'Sign Up' : 'Login'}
          </button>
        </div>
      ) : (
        <div style={{ border: '1px solid #ccc', padding: 20, marginBottom: 20 }}>
          <p>
            Logged in as <strong>{user.name}</strong> {user.premium ? '⭐ Premium' : ''}
          </p>
          {!user.premium && (
