# 4. server.js

```js
const express = require("express");
const http = require("http");
const path = require("path");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcryptjs");
const jwt = require("jsonwebtoken");
const dotenv = require("dotenv");
const Stripe = require("stripe");
const { Server } = require("socket.io");

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server);
const db = new sqlite3.Database("./app.db");
const stripe = Stripe(process.env.STRIPE_SECRET_KEY);

const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET || "secret";

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      is_premium INTEGER DEFAULT 0
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER NOT NULL,
      receiver_id INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.run(`
    CREATE TABLE IF NOT EXISTS notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      type TEXT NOT NULL,
      message TEXT NOT NULL,
      is_read INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: "Missing token" });

  const token = authHeader.split(" ")[1];
  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function createNotification(userId, type, message) {
  db.run(
    `INSERT INTO notifications (user_id, type, message) VALUES (?, ?, ?)`,
    [userId, type, message],
    function (err) {
      if (!err) {
        io.to(`user_${userId}`).emit("notification", {
          id: this.lastID,
          user_id: userId,
          type,
          message
        });
      }
    }
  );
}

// Auth
app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  const hash = await bcrypt.hash(password, 10);
  db.run(
    `INSERT INTO users (username, password_hash) VALUES (?, ?)`,
    [username, hash],
    function (err) {
      if (err) return res.status(400).json({ error: "Username already exists" });
      res.json({ success: true, userId: this.lastID });
    }
  );
});

app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  db.get(`SELECT * FROM users WHERE username = ?`, [username], async (err, user) => {
    if (err || !user) return res.status(400).json({ error: "Invalid credentials" });

    const ok = await bcrypt.compare(password, user.password_hash);
    if (!ok) return res.status(400).json({ error: "Invalid credentials" });

    const token = jwt.sign(
      { id: user.id, username: user.username, is_premium: user.is_premium },
      JWT_SECRET
    );

    res.json({
      token,
      user: { id: user.id, username: user.username, is_premium: user.is_premium }
    });
  });
});

// List users
app.get("/api/users", authMiddleware, (req, res) => {
  db.all(
    `SELECT id, username, is_premium FROM users WHERE id != ?`,
    [req.user.id],
    (err, rows) => {
      if (err) return res.status(500).json({ error: "DB error" });
      res.json(rows);
    }
  );
});

// Send message
app.post("/api/messages", authMiddleware, (req, res) => {
  const { receiverId, content } = req.body;
  if (!receiverId || !content) {
    return res.status(400).json({ error: "receiverId and content required" });
  }

  db.run(
    `INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)`,
    [req.user.id, receiverId, content],
    function (err) {
      if (err) return res.status(500).json({ error: "Failed to send message" });

      const msg = {
        id: this.lastID,
        sender_id: req.user.id,
        receiver_id: receiverId,
        content,
        created_at: new Date().toISOString()
      };

      io.to(`user_${receiverId}`).emit("message", msg);
      createNotification(receiverId, "message", `New message from ${req.user.username}`);

      res.json({ success: true, message: msg });
    }
  );
});

