# 6. public/app.js

```js
let token = localStorage.getItem("token") || null;
let currentUser = JSON.parse(localStorage.getItem("user") || "null");
let selectedUserId = null;
let socket = null;

function api(path, options = {}) {
  return fetch(path, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {})
    }
  }).then(async (res) => {
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || "Request failed");
    return data;
  });
}

function showApp() {
  document.getElementById("auth").classList.add("hidden");
  document.getElementById("app").classList.remove("hidden");
  document.getElementById("me").textContent = currentUser.username;
  document.getElementById("premiumBadge").textContent = currentUser.is_premium ? "⭐ Premium" : "";
}

function showAuth() {
  document.getElementById("auth").classList.remove("hidden");
  document.getElementById("app").classList.add("hidden");
}

async function register() {
  const username = document.getElementById("regUsername").value;
  const password = document.getElementById("regPassword").value;
  try {
    await api("/api/register", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    alert("Registered successfully. Now log in.");
  } catch (e) {
    alert(e.message);
  }
}

async function login() {
  const username = document.getElementById("loginUsername").value;
  const password = document.getElementById("loginPassword").value;

  try {
    const data = await api("/api/login", {
      method: "POST",
      body: JSON.stringify({ username, password })
    });
    token = data.token;
    currentUser = data.user;
    localStorage.setItem("token", token);
    localStorage.setItem("user", JSON.stringify(currentUser));
    initSocket();
    showApp();
    loadUsers();
    loadNotifications();
  } catch (e) {
    alert(e.message);
  }
}

function initSocket() {
  if (socket) socket.disconnect();

  socket = io({
    auth: { token }
  });

  socket.on("message", (msg) => {
    if (selectedUserId && (msg.sender_id === selectedUserId || msg.receiver_id === selectedUserId)) {
      appendMessage(msg);
    }
    loadNotifications();
  });

  socket.on("notification", (n) => {
    prependNotification(n);
  });
}

async function loadUsers() {
  try {
    const users = await api("/api/users");
    const ul = document.getElementById("users");
    ul.innerHTML = "";
    users.forEach((u) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <button onclick="selectUser(${u.id}, '${u.username}')">
          ${u.username} ${u.is_premium ? "⭐" : ""}
        </button>
      `;
      ul.appendChild(li);
    });
  } catch (e) {
    alert(e.message);
  }
}

async function selectUser(id, username) {
  selectedUserId = id;
  document.getElementById("conversation").innerHTML = `<p><em>Chatting with ${username}</em></p>`;
  const msgs = await api(`/api/messages/${id}`);
  msgs.forEach(appendMessage);
}

function appendMessage(msg) {
  const div = document.getElementById("conversation");
  const p = document.createElement("p");
  const who = msg.sender_id === currentUser.id ? "Me" : "Them";
  p.textContent = `${who}: ${msg.content}`;
  div.appendChild(p);
  div.scrollTop = div.scrollHeight;
}

async function sendMessage() {
  const content = document.getElementById("messageInput").value;
  if (!selectedUserId) return alert("Select a user first");
  if (!content) return;

  try {
    const data = await api("/api/messages", {
      method: "POST",
      body: JSON.stringify({ receiverId: selectedUserId, content })
    });
    appendMessage(data.message);
    document.getElementById("messageInput").value = "";
  } catch (e) {
    alert(e.message);
  }
}

async function loadNotifications() {
  try {
    const notifications = await api("/api/notifications");
    const ul = document.getElementById("notifications");
    ul.innerHTML = "";
    notifications.forEach((n) => {
      const li = document.createElement("li");
      li.textContent = `${n.is_read ? "✓" : "•"} ${n.message}`;
      ul.appendChild(li);
    });
  } catch (e) {
    console.error(e);
  }
}

function prependNotification(n) {
  const ul = document.getElementById("notifications");
  const li = document.createElement("li");
  li.textContent = `• ${n.message}`;
  ul.prepend(li);
}

async function startPremiumCheckout() {
  try {
    const data = await api("/api/create-checkout-session", {
      method: "POST"
    });
    window.location.href = data.url;
  } catch (e) {
    alert(e.message);
  }
}

async function demoUpgradePremium() {
  try {
    await api("/api/upgrade-premium-demo", { method: "POST" });
    currentUser.is_premium = 1;
    localStorage.setItem("user", JSON.stringify(currentUser));
    showApp();
    loadNotifications();
    alert("Premium unlocked for demo");
  } catch (e) {
    alert(e.message);
  }
}

if (token && currentUser) {
  showApp();
  initSocket();
  loadUsers();
  loadNotifications();
} else {
  showAuth();
}
```

