  <script>
    const chartCanvas = document.getElementById("chart");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const currentDeltaEl = document.getElementById("currentDelta");
    const avgValueEl = document.getElementById("avgValue");
    const peakValueEl = document.getElementById("peakValue");
    const recordCountEl = document.getElementById("recordCount");
    const streamStatusEl = document.getElementById("streamStatus");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const recordForm = document.getElementById("recordForm");
    const recordsTableBody = document.getElementById("recordsTableBody");
    const formSuccess = document.getElementById("formSuccess");

    const maxPoints = 60;
    let data = [];
    let timer = null;
    let peak = 0;
    let records = [];

    function generateValue() {
      const base = 50;
      const noise = (Math.random() - 0.5) * 20;
      const trend = Math.sin(Date.now() / 1000) * 10;
      return Math.max(0, +(base + noise + trend).toFixed(2));
    }

    function updateData() {
      const newValue = generateValue();
      const prevValue = data.length ? data[data.length - 1] : newValue;
      data.push(newValue);

      if (data.length > maxPoints) {
        data.shift();
      }

      peak = Math.max(peak, newValue);
      updateKPIs(newValue, prevValue);
      drawChart();
    }

    function updateKPIs(current, previous) {
      const avg = data.reduce((sum, v) => sum + v, 0) / (data.length || 1);
      const delta = previous === 0 ? 0 : ((current - previous) / previous) * 100;

      currentValueEl.textContent = current.toFixed(2);
      currentDeltaEl.textContent = `${delta >= 0 ? "+" : ""}${delta.toFixed(2)}%`;
      currentDeltaEl.style.color = delta >= 0 ? "#86efac" : "#fca5a5";
      avgValueEl.textContent = avg.toFixed(2);
      peakValueEl.textContent = peak.toFixed(2);
      recordCountEl.textContent = records.length;
    }

    function drawChart() {
      const w = chartCanvas.width;
      const h = chartCanvas.height;
      ctx.clearRect(0, 0, w, h);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const min = Math.min(...data) - 5;
      const max = Math.max(...data) + 5;
      const xStep = w / (maxPoints - 1);

      // Area fill
      ctx.beginPath();
      data.forEach((value, index) => {
        const x = index * xStep;
        const y = h - ((value - min) / (max - min)) * h;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo((data.length - 1) * xStep, h);
      ctx.lineTo(0, h);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, "rgba(59,130,246,0.35)");
      gradient.addColorStop(1, "rgba(59,130,246,0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((value, index) => {
        const x = index * xStep;
        const y = h - ((value - min) / (max - min)) * h;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Last point
      const lastIndex = data.length - 1;
      const lastX = lastIndex * xStep;
      const lastY = h - ((data[lastIndex] - min) / (max - min)) * h;
      ctx.beginPath();
      ctx.arc(lastX, lastY, 5, 0, Math.PI * 2);
      ctx.fillStyle = "#22c55e";
      ctx.fill();

      // Labels
      ctx.fillStyle = "rgba(229, 231, 235, 0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText(`Max: ${max.toFixed(1)}`, 10, 16);
      ctx.fillText(`Min: ${min.toFixed(1)}`, 10, h - 10);
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(updateData, 1000);
      streamStatusEl.textContent = "Stream: Running";
      streamStatusEl.style.background = "rgba(34, 197, 94, 0.15)";
      streamStatusEl.style.color = "#86efac";
      streamStatusEl.style.borderColor = "rgba(34, 197, 94, 0.35)";
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
      streamStatusEl.textContent = "Stream: Stopped";
      streamStatusEl.style.background = "rgba(239, 68, 68, 0.15)";
      streamStatusEl.style.color = "#fca5a5";
      streamStatusEl.style.borderColor = "rgba(239, 68, 68, 0.35)";
    }

    function resetDashboard() {
      data = [];
      peak = 0;
      updateKPIs(0, 0);
      drawChart();
    }

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      setError("nameError", "");
      setError("categoryError", "");
      setError("priorityError", "");
      setError("notesError", "");
      formSuccess.textContent = "";
    }

    function validateForm(values) {
      let valid = true;
      clearErrors();

      if (!values.name.trim()) {
        setError("nameError", "Name is required.");
        valid = false;
      } else if (values.name.trim().length < 2) {
        setError("nameError", "Name must be at least 2 characters.");
        valid = false;
      }

      if (!values.category) {
        setError("categoryError", "Please select a category.");
        valid = false;
      }

      if (!values.priority) {
        setError("priorityError", "Please select a priority.");
        valid = false;
      }

      if (values.notes.length > 200) {
        setError("notesError", "Notes must be 200 characters or fewer.");
        valid = false;
      }

      return valid;
    }

    function renderRecords() {
      recordCountEl.textContent = records.length;

      if (records.length === 0) {
        recordsTableBody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted); text-align: center;">No records yet</td>
          </tr>
        `;
        return;
      }

      recordsTableBody.innerHTML = records
        .slice()
        .reverse()
        .map(record => `
          <tr>
            <td>${record.time}</td>
            <td>${escapeHtml(record.name)}</td>
            <td>${escapeHtml(record.category)}</td>
            <td><span class="pill ${record.priority}">${record.priority}</span></td>
            <td>${escapeHtml(record.notes || "-")}</td>
          </tr>
        `)
        .join("");
    }

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    recordForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const values = {
        name: document.getElementById("name").value,
        category: document.getElementById("category").value,
        priority: document.getElementById("priority").value,
        notes: document.getElementById("notes").value.trim()
      };

      if (!validateForm(values)) return;

      const record = {
        ...values,
        time: new Date().toLocaleTimeString()
      };

      records.push(record);
      renderRecords();
      recordForm.reset();
      formSuccess.textContent = "Record submitted successfully.";
    });

    // Initial state
    for (let i = 0; i < 20; i++) {
      data.push(generateValue());
    }
    peak = Math.max(...data, 0);
    updateKPIs(data[data.length - 1] || 0, data[data.length - 2] || 0);
    drawChart();
    renderRecords();
    startStream();
  </script>
</body>
</html>
```

