    .card h2 {
      margin-top: 0;
      margin-bottom: 14px;
      font-size: 1.1rem;
    }

    .chart-wrap {
      position: relative;
      width: 100%;
      height: 340px;
      background: linear-gradient(180deg, rgba(30,41,59,0.35), rgba(15,23,42,0.2));
      border-radius: 12px;
      padding: 10px;
    }

    canvas {
      width: 100%;
      height: 100%;
      display: block;
    }

    form {
      display: grid;
      gap: 14px;
    }

    .field {
      display: grid;
      gap: 6px;
    }

    label {
      font-size: 0.92rem;
      color: var(--muted);
    }

    input, select, textarea {
      width: 100%;
      border: 1px solid var(--border);
      background: #0b1220;
      color: var(--text);
      padding: 12px;
      border-radius: 12px;
      outline: none;
      transition: border-color 0.2s ease;
    }

    input:focus, select:focus, textarea:focus {
      border-color: var(--accent-2);
    }

    .error {
      color: #fca5a5;
      font-size: 0.85rem;
      min-height: 1em;
    }

    .success-message {
      margin-top: 10px;
      color: #86efac;
      font-size: 0.92rem;
    }

    .feed-list {
      list-style: none;
      padding: 0;
      margin: 0;
      display: grid;
      gap: 10px;
      max-height: 280px;
      overflow: auto;
    }

    .feed-item {
      padding: 12px 14px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: rgba(15, 23, 42, 0.65);
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: flex-start;
    }

    .feed-item strong {
      display: block;
      margin-bottom: 4px;
    }

    .timestamp {
      color: var(--muted);
      white-space: nowrap;
      font-size: 0.85rem;
    }

    .badge {
      display: inline-block;
      padding: 4px 8px;
      border-radius: 999px;
      font-size: 0.78rem;
      font-weight: 700;
      margin-left: 8px;
    }

    .badge.info {
      background: rgba(56, 189, 248, 0.15);
      color: #7dd3fc;
    }

    .badge.alert {
      background: rgba(239, 68, 68, 0.15);
      color: #fca5a5;
    }

    .badge.user {
      background: rgba(34, 197, 94, 0.15);
      color: #86efac;
    }

    @media (max-width: 980px) {
      .stat-card { grid-column: span 6; }
      .chart-card, .form-card { grid-column: span 12; }
    }

    @media (max-width: 640px) {
      .stat-card { grid-column: span 12; }
      .container { padding: 16px; }
      .chart-wrap { height: 260px; }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Real-Time Operations Dashboard</h1>
        <p>Live metrics, event stream, and interactive form handling</p>
      </div>
      <div class="controls">
        <button id="startBtn" class="primary">Start Stream</button>
        <button id="stopBtn">Stop Stream</button>
        <button id="resetBtn" class="danger">Reset Data</button>
      </div>
    </div>

    <div class="grid">
      <div class="card stat-card">
        <div class="stat-label">Current Value</div>
        <div id="currentValue" class="stat-value">0</div>
        <div id="currentTrend" class="stat-trend neutral">Waiting for data...</div>
      </div>

      <div class="card stat-card">
        <div class="stat-label">Average</div>
        <div id="avgValue" class="stat-value">0</div>
        <div class="stat-trend">Rolling average of visible points</div>
      </div>

      <div class="card stat-card">
        <div class="stat-label">Peak</div>
        <div id="peakValue" class="stat-value">0</div>
        <div class="stat-trend">Highest value observed</div>
      </div>

      <div class="card stat-card">
        <div class="stat-label">Events Logged</div>
        <div id="eventCount" class="stat-value">0</div>
        <div class="stat-trend">System + user activity feed</div>
      </div>

      <div class="card chart-card">
        <h2>Live Throughput</h2>
        <div class="chart-wrap">
          <canvas id="chart"></canvas>
        </div>
      </div>

      <div class="card form-card">
        <h2>Create Alert</h2>
        <form id="alertForm" novalidate>
          <div class="field">
            <label for="name">Operator Name</label>
            <input id="name" name="name" type="text" placeholder="e.g. Alex" />
            <div class="error" id="nameError"></div>
          </div>

          <div class="field">
            <label for="type">Alert Type</label>
            <select id="type" name="type">
              <option value="">Select alert type</option>
              <option value="Performance">Performance</option>
              <option value="Incident">Incident</option>
              <option value="Maintenance">Maintenance</option>
            </select>
            <div class="error" id="typeError"></div>
          </div>

          <div class="field">
            <label for="threshold">Threshold</label>
            <input id="threshold" name="threshold" type="number" min="0" max="1000" placeholder="e.g. 120" />
            <div class="error" id="thresholdError"></div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional notes..."></textarea>
            <div class="error" id="notesError"></div>
          </div>

          <button type="submit" class="primary">Submit Alert</button>
          <div id="formSuccess" class="success-message"></div>
        </form>
      </div>

      <div class="card feed-card">
        <h2>Activity Feed</h2>
        <ul id="feedList" class="feed-list"></ul>
      </div>
    </div>
  </div>

  <script>
    const MAX_POINTS = 40;
    const dataPoints = [];
    let streamInterval = null;
    let eventCounter = 0;

    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const currentTrendEl = document.getElementById('currentTrend');
    const eventCountEl = document.getElementById('eventCount');
    const feedList = document.getElementById('feedList');

    function resizeCanvas() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    window.addEventListener('resize', resizeCanvas);

    function randomWalkValue() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1].value : 80;
      const delta = (Math.random() - 0.5) * 24;
      const next = Math.max(10, Math.min(180, last + delta));
      return Number(next.toFixed(1));
    }

    function addDataPoint(value = randomWalkValue()) {
      const point = {
        time: new Date(),
        value
      };
      dataPoints.push(point);
      if (dataPoints.length > MAX_POINTS) dataPoints.shift();

      updateStats();
      drawChart();

      if (value > 150) {
        addFeedItem(
          'High throughput detected',
          `System measured elevated value: ${value}`,
          'alert'
        );
      } else {
        addFeedItem(
          'Metric updated',
          `New live value recorded: ${value}`,
          'info'
        );
      }
    }

    function updateStats() {
      if (!dataPoints.length) {
        currentValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        currentTrendEl.textContent = 'Waiting for data...';
        currentTrendEl.className = 'stat-trend neutral';
        return;
      }

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);

      if (values.length > 1) {
        const prev = values[values.length - 2];
        const diff = current - prev;
        if (diff > 0.5) {
          currentTrendEl.textContent = `▲ Rising by ${diff.toFixed(1)}`;
          currentTrendEl.className = 'stat-trend up';
        } else if (diff < -0.5) {
          currentTrendEl.textContent = `▼ Falling by ${Math.abs(diff).toFixed(1)}`;
          currentTrendEl.className = 'stat-trend down';
        } else {
          currentTrendEl.textContent = '■ Stable';
          currentTrendEl.className = 'stat-trend neutral';
        }
      }
    }

    function drawChart() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const padding = 30;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + (chartH / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 6; i++) {
        const x = padding + (chartW / 6) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      if (!dataPoints.length) {
        ctx.fillStyle = '#94a3b8';
        ctx.font = '14px sans-serif';
        ctx.fillText('No data yet. Start the stream to begin.', padding, height / 2);
        return;
      }

      const values = dataPoints.map(p => p.value);
      const min = Math.min(...values, 0);
      const max = Math.max(...values, 200);
      const range = max - min || 1;

      const points = dataPoints.map((point, i) => {
        const x = padding + (i / Math.max(dataPoints.length - 1, 1)) * chartW;
        const y = padding + chartH - ((point.value - min) / range) * chartH;
        return { x, y, value: point.value };
      });

      // Area fill
      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');

      ctx.beginPath();
      ctx.moveTo(points[0].x, height - padding);
      points.forEach(p => ctx.lineTo(p.x, p.y));
      ctx.lineTo(points[points.length - 1].x, height - padding);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      points.forEach((p, i) => {
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      points.forEach((p, i) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, i === points.length - 1 ? 5 : 3, 0, Math.PI * 2);
        ctx.fillStyle = i === points.length - 1 ? '#22c55e' : '#e5e7eb';
        ctx.fill();
      });

      // Y-axis labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.fillText(max.toFixed(0), 6, padding + 4);
      ctx.fillText(((max + min) / 2).toFixed(0), 6, padding + chartH / 2);
      ctx.fillText(min.toFixed(0), 6, height - padding);

      // Last value label
      const last = points[points.length - 1];
      ctx.fillStyle = '#e5e7eb';
      ctx.fillText(`Latest: ${dataPoints[dataPoints.length - 1].value}`, Math.max(padding, last.x - 30), Math.max(18, last.y - 10));
    }

    function addFeedItem(title, message, type = 'info') {
      eventCounter++;
      eventCountEl.textContent = eventCounter;

      const li = document.createElement('li');
      li.className = 'feed-item';

      const left = document.createElement('div');
      const right = document.createElement('div');

      const strong = document.createElement('strong');
      strong.textContent = title;

      const badge = document.createElement('span');
      badge.className = `badge ${type}`;
      badge.textContent = type.toUpperCase();

      strong.appendChild(badge);

      const p = document.createElement('div');
      p.textContent = message;

      left.appendChild(strong);
      left.appendChild(p);

      right.className = 'timestamp';
      right.textContent = new Date().toLocaleTimeString();

      li.appendChild(left);
      li.appendChild(right);

      feedList.prepend(li);

      while (feedList.children.length > 20) {
        feedList.removeChild(feedList.lastChild);
      }
    }

    function startStream() {
      if (streamInterval) return;
      addFeedItem('Stream started', 'Real-time data generation has started.', 'info');
      streamInterval = setInterval(() => addDataPoint(), 1000);
    }

    function stopStream() {
      if (!streamInterval) return;
      clearInterval(streamInterval);
      streamInterval = null;
      addFeedItem('Stream stopped', 'Real-time data generation has been paused.', 'info');
    }

    function resetDashboard() {
      stopStream();
      dataPoints.length = 0;
      eventCounter = 0;
      eventCountEl.textContent = '0';
      feedList.innerHTML = '';
      updateStats();
      drawChart();
      addFeedItem('Dashboard reset', 'All chart data and feed items were cleared.', 'alert');
    }

    document.getElementById('startBtn').addEventListener('click', startStream);
    document.getElementById('stopBtn').addEventListener('click', stopStream);
    document.getElementById('resetBtn').addEventListener('click', resetDashboard);

    // Form handling
    const alertForm = document.getElementById('alertForm');
    const formSuccess = document.getElementById('formSuccess');

    function clearErrors() {
      ['name', 'type', 'threshold', 'notes'].forEach(field => {
        const errorEl = document.getElementById(field + 'Error');
        if (errorEl) errorEl.textContent = '';
      });
      formSuccess.textContent = '';
    }

    function validateForm(formData) {
      const errors = {};

      if (!formData.name.trim()) {
        errors.name = 'Operator name is required.';
      } else if (formData.name.trim().length < 2) {
        errors.name = 'Name must be at least 2 characters.';
      }

      if (!formData.type) {
        errors.type = 'Please select an alert type.';
      }

      if (!formData.threshold.trim()) {
        errors.threshold = 'Threshold is required.';
      } else {
        const value = Number(formData.threshold);
        if (Number.isNaN(value)) {
          errors.threshold = 'Threshold must be a number.';
        } else if (value < 0 || value > 1000) {
          errors.threshold = 'Threshold must be between 0 and 1000.';
        }
      }

      if (formData.notes.length > 200) {
        errors.notes = 'Notes must be 200 characters or fewer.';
      }

      return errors;
    }

    alertForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const formData = {
        name: document.getElementById('name').value,
        type: document.getElementById('type').value,
        threshold: document.getElementById('threshold').value,
        notes: document.getElementById('notes').value.trim()
      };

      const errors = validateForm(formData);

      if (Object.keys(errors).length > 0) {
        for (const key in errors) {
          const errorEl = document.getElementById(key + 'Error');
          if (errorEl) errorEl.textContent = errors[key];
        }
        return;
      }

      formSuccess.textContent = 'Alert submitted successfully.';
      addFeedItem(
        'User alert created',
        `${formData.name} created a ${formData.type} alert with threshold ${formData.threshold}${formData.notes ? ` — "${formData.notes}"` : ''}`,
        'user'
      );

      alertForm.reset();
    });

    // Initial render
    resizeCanvas();
    updateStats();
    drawChart();
    addFeedItem('Dashboard ready', 'Interface loaded and awaiting interaction.', 'info');
  </script>
</body>
</html>
```

## Features included

- **Real-time visualization**
  - Simulated live data updates every second
  - Canvas-based line chart with area fill
  - Dynamic stats for current, average, and peak values

- **Interactive controls**
  - Start stream
  - Stop stream
  - Reset dashboard

- **Form handling**
  - Input validation
  - Error messages
  - Success feedback
  - Adds submitted form data into the activity feed

- **Activity feed**
  - Logs system and user events
  - Shows timestamps
  - Uses badges for event types

