        <h2>Data Generator Settings</h2>
        <form id="settingsForm" novalidate>
          <div class="field">
            <label for="sourceName">Source Name</label>
            <input type="text" id="sourceName" name="sourceName" placeholder="e.g. Sensor A" />
            <div class="error" id="sourceNameError"></div>
          </div>

          <div class="field">
            <label for="minValue">Minimum Value</label>
            <input type="number" id="minValue" name="minValue" value="20" />
            <div class="error" id="minValueError"></div>
          </div>

          <div class="field">
            <label for="maxValue">Maximum Value</label>
            <input type="number" id="maxValue" name="maxValue" value="100" />
            <div class="error" id="maxValueError"></div>
          </div>

          <div class="field">
            <label for="intervalMs">Update Interval (ms)</label>
            <select id="intervalMs" name="intervalMs">
              <option value="500">500</option>
              <option value="1000" selected>1000</option>
              <option value="1500">1500</option>
              <option value="2000">2000</option>
            </select>
            <div class="error" id="intervalMsError"></div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="3" placeholder="Optional notes"></textarea>
            <div class="error" id="notesError"></div>
          </div>

          <button type="submit" class="btn-success">Apply Settings</button>
          <div class="success-message" id="formSuccess"></div>
        </form>

        <h2 style="margin-top: 24px;">Event Log</h2>
        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('chartCanvas');
    const ctx = canvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const sampleCountEl = document.getElementById('sampleCount');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const settingsForm = document.getElementById('settingsForm');
    const eventLog = document.getElementById('eventLog');
    const formSuccess = document.getElementById('formSuccess');

    let data = [];
    let timer = null;
    let config = {
      sourceName: 'Sensor A',
      minValue: 20,
      maxValue: 100,
      intervalMs: 1000,
      notes: ''
    };

    const maxPoints = 30;

    function addLog(message, type = 'INFO') {
      const item = document.createElement('div');
      item.className = 'log-item';
      const time = new Date().toLocaleTimeString();
      item.innerHTML = `<span class="tag">${type}</span>${time} — ${message}`;
      eventLog.prepend(item);
    }

    function randomValue(min, max) {
      return +(Math.random() * (max - min) + min).toFixed(2);
    }

    function generatePoint() {
      const value = randomValue(config.minValue, config.maxValue);
      const point = {
        time: new Date(),
        value
      };
      data.push(point);
      if (data.length > maxPoints) data.shift();
      updateStats();
      drawChart();
      addLog(`${config.sourceName} produced value ${value}`, 'DATA');
    }

    function updateStats() {
      if (data.length === 0) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        sampleCountEl.textContent = '0';
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(2);
      averageValueEl.textContent = avg.toFixed(2);
      peakValueEl.textContent = peak.toFixed(2);
      sampleCountEl.textContent = String(data.length);
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, w, h);

      // Grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values, config.minValue);
      const max = Math.max(...values, config.maxValue);
      const range = max - min || 1;

      const padding = 30;
      const chartW = w - padding * 2;
      const chartH = h - padding * 2;

      // Axis labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.fillText(max.toFixed(1), 6, padding);
      ctx.fillText(min.toFixed(1), 6, h - padding);

      // Line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartW;
        const y = h - padding - ((point.value - min) / range) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Area fill
      ctx.lineTo(padding + ((data.length - 1) / (maxPoints - 1)) * chartW, h - padding);
      ctx.lineTo(padding, h - padding);
      ctx.closePath();
      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, 'rgba(59,130,246,0.35)');
      gradient.addColorStop(1, 'rgba(59,130,246,0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Points
      data.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartW;
        const y = h - padding - ((point.value - min) / range) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(generatePoint, config.intervalMs);
      addLog(`Stream started at ${config.intervalMs}ms interval`, 'SYSTEM');
    }

    function stopStream() {
      if (!timer) return;
      clearInterval(timer);
      timer = null;
      addLog('Stream stopped', 'SYSTEM');
    }

    function restartStreamIfRunning() {
      const wasRunning = !!timer;
      if (wasRunning) {
        stopStream();
        startStream();
      }
    }

    function resetDashboard() {
      stopStream();
      data = [];
      updateStats();
      drawChart();
      addLog('Dashboard reset', 'SYSTEM');
    }

    function clearErrors() {
      document.querySelectorAll('.error').forEach(el => el.textContent = '');
      formSuccess.textContent = '';
    }

    function validateForm(formData) {
      let valid = true;

      if (!formData.sourceName.trim()) {
        document.getElementById('sourceNameError').textContent = 'Source name is required.';
        valid = false;
      }

      if (formData.minValue === '' || isNaN(formData.minValue)) {
        document.getElementById('minValueError').textContent = 'Minimum value must be a number.';
        valid = false;
      }

      if (formData.maxValue === '' || isNaN(formData.maxValue)) {
        document.getElementById('maxValueError').textContent = 'Maximum value must be a number.';
        valid = false;
      }

      if (!isNaN(formData.minValue) && !isNaN(formData.maxValue) && Number(formData.minValue) >= Number(formData.maxValue)) {
        document.getElementById('maxValueError').textContent = 'Maximum must be greater than minimum.';
        valid = false;
      }

      if (!formData.intervalMs) {
        document.getElementById('intervalMsError').textContent = 'Please select an interval.';
        valid = false;
      }

      if (formData.notes.length > 200) {
        document.getElementById('notesError').textContent = 'Notes must be 200 characters or fewer.';
        valid = false;
      }

      return valid;
    }

    settingsForm.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const formData = {
        sourceName: document.getElementById('sourceName').value,
        minValue: document.getElementById('minValue').value,
        maxValue: document.getElementById('maxValue').value,
        intervalMs: document.getElementById('intervalMs').value,
        notes: document.getElementById('notes').value
      };

      if (!validateForm(formData)) return;

      config = {
        sourceName: formData.sourceName.trim(),
        minValue: Number(formData.minValue),
        maxValue: Number(formData.maxValue),
        intervalMs: Number(formData.intervalMs),
        notes: formData.notes.trim()
      };

      formSuccess.textContent = 'Settings applied successfully.';
      addLog(`Settings updated for ${config.sourceName}`, 'FORM');
      restartStreamIfRunning();
      drawChart();
    });

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetDashboard);

    // Initial state
    document.getElementById('sourceName').value = config.sourceName;
    document.getElementById('minValue').value = config.minValue;
    document.getElementById('maxValue').value = config.maxValue;
    document.getElementById('intervalMs').value = String(config.intervalMs);
    document.getElementById('notes').value = config.notes;

    drawChart();
    addLog('Dashboard initialized', 'SYSTEM');
  </script>
</body>
</html>
