  <script>
    const canvas = document.getElementById('chartCanvas');
    const ctx = canvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const sampleCountEl = document.getElementById('sampleCount');
    const streamStatusEl = document.getElementById('streamStatus');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const form = document.getElementById('recordForm');
    const recordsTableBody = document.getElementById('recordsTableBody');

    const state = {
      data: [],
      maxPoints: 60,
      timer: null,
      running: true,
      records: []
    };

    function resizeCanvas() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function generateDataPoint() {
      const last = state.data.length ? state.data[state.data.length - 1] : 50;
      const noise = (Math.random() - 0.5) * 14;
      const trend = Math.sin(Date.now() / 1200) * 4;
      let next = last + noise * 0.35 + trend * 0.15;
      next = Math.max(5, Math.min(100, next));
      return Number(next.toFixed(1));
    }

    function updateMetrics() {
      const data = state.data;
      const current = data[data.length - 1] || 0;
      const avg = data.length
        ? data.reduce((sum, v) => sum + v, 0) / data.length
        : 0;
      const peak = data.length ? Math.max(...data) : 0;

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      sampleCountEl.textContent = data.length;
    }

    function drawGrid(width, height, padding) {
      ctx.save();
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 6;

      for (let i = 0; i <= rows; i++) {
        const y = padding + ((height - padding * 2) / rows) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = padding + ((width - padding * 2) / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawChart() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      const padding = 24;

      ctx.clearRect(0, 0, width, height);
      drawGrid(width, height, padding);

      const data = state.data;
      if (!data.length) return;

      const min = 0;
      const max = 100;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      const xStep = data.length > 1 ? chartWidth / (state.maxPoints - 1) : 0;

      ctx.beginPath();
      data.forEach((value, i) => {
        const x = padding + i * xStep;
        const y = padding + chartHeight - ((value - min) / (max - min)) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      ctx.lineTo(padding + (data.length - 1) * xStep, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      ctx.beginPath();
      data.forEach((value, i) => {
        const x = padding + i * xStep;
        const y = padding + chartHeight - ((value - min) / (max - min)) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.stroke();

      const lastValue = data[data.length - 1];
      const lastX = padding + (data.length - 1) * xStep;
      const lastY = padding + chartHeight - ((lastValue - min) / (max - min)) * chartHeight;

      ctx.beginPath();
      ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
      ctx.fillStyle = '#22c55e';
      ctx.fill();

      ctx.fillStyle = '#cbd5e1';
      ctx.font = '12px sans-serif';
      ctx.fillText('100', 4, padding + 4);
      ctx.fillText('0', 12, height - padding);
    }

    function tick() {
      const point = generateDataPoint();
      state.data.push(point);
      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }
      updateMetrics();
      drawChart();
    }

    function startStream() {
      if (state.timer) return;
      state.running = true;
      streamStatusEl.innerHTML = '<span class="status-dot"></span><span>Streaming live</span>';
      state.timer = setInterval(tick, 900);
    }

    function stopStream() {
      state.running = false;
      clearInterval(state.timer);
      state.timer = null;
      streamStatusEl.innerHTML = '<span class="status-dot" style="background:#f59e0b; box-shadow:0 0 0 6px rgba(245,158,11,0.15); animation:none;"></span><span>Paused</span>';
    }

    function resetStream() {
      state.data = [];
      updateMetrics();
      drawChart();
    }

    function validateForm(values) {
      const errors = {};

      if (!values.name.trim()) {
        errors.name = 'Name is required.';
      } else if (values.name.trim().length < 2) {
        errors.name = 'Name must be at least 2 characters.';
      }

      if (!values.category) {
        errors.category = 'Category is required.';
      }

      if (!values.priority) {
        errors.priority = 'Priority is required.';
      }

      if (values.notes.length > 200) {
        errors.notes = 'Notes must be 200 characters or fewer.';
      }

      return errors;
    }

    function setFieldError(field, message = '') {
      document.getElementById(field + 'Error').textContent = message;
    }

    function clearErrors() {
      ['name', 'category', 'priority', 'notes'].forEach(field => setFieldError(field, ''));
      document.getElementById('formSuccess').textContent = '';
    }

    function priorityBadge(priority) {
      const cls = priority.toLowerCase();
      return `<span class="badge ${cls}">${priority}</span>`;
    }

    function addRecord(record) {
      state.records.unshift(record);

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${record.timestamp}</td>
        <td>${escapeHtml(record.name)}</td>
        <td>${escapeHtml(record.category)}</td>
        <td>${priorityBadge(record.priority)}</td>
        <td>${escapeHtml(record.notes || '-')}</td>
      `;

      if (recordsTableBody.firstChild) {
        recordsTableBody.insertBefore(row, recordsTableBody.firstChild);
      } else {
        recordsTableBody.appendChild(row);
      }
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const values = {
        name: form.name.value,
        category: form.category.value,
        priority: form.priority.value,
        notes: form.notes.value.trim()
      };

      const errors = validateForm(values);

      if (Object.keys(errors).length > 0) {
        Object.entries(errors).forEach(([field, message]) => setFieldError(field, message));
        return;
      }

      const record = {
        ...values,
        timestamp: new Date().toLocaleString()
      };

      addRecord(record);
      form.reset();
      document.getElementById('formSuccess').textContent = 'Record submitted successfully.';
    });

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetStream);

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();

    for (let i = 0; i < 20; i++) {
      tick();
    }
    startStream();
  </script>
</body>
</html>
```

## What this does

- Simulates a live data stream with `setInterval`
- Draws a real-time line/area chart on `<canvas>`
- Updates summary metrics:
  - current value
  - average
  - peak
  - sample count
- Handles form submission with validation
- Safely renders submitted records into a table
- Supports responsive layout for desktop and mobile

