<body>
  <div class="app">
    <div class="header">
      <div>
        <h1>Operations Dashboard</h1>
        <p>Interactive real-time metrics, controls, and form submissions</p>
      </div>
      <div class="header-actions">
        <button id="toggleStreamBtn">Pause Stream</button>
