            </div>
            <div class="kpi">
              <div class="kpi-label">Requests/sec</div>
              <div class="kpi-value" id="requestsValue">0</div>
              <div class="kpi-trend" id="requestsTrend">--</div>
            </div>
            <div class="kpi">
              <div class="kpi-label">Active Users</div>
              <div class="kpi-value" id="usersValue">0</div>
