        <div class="panel">
          <h2>Real-Time Metrics</h2>
          <div class="chart-wrap">
            <canvas id="chartCanvas"></canvas>
          </div>
          <div class="legend">
            <div class="legend-item"><span class="dot cpu"></span> CPU</div>
            <div class="legend-item"><span class="dot memory"></span> Memory</div>
            <div class="legend-item"><span class="dot requests"></span> Requests/sec</div>
          </div>
          <div class="status-bar">
            <div>Last update: <span id="lastUpdate">--</span></div>
            <div class="badge live" id="streamStatus">LIVE</div>
          </div>
        </div>
      </div>

      <div class="right-col">
        <div class="panel">
          <h2>Manual Event Form</h2>
          <form id="eventForm" novalidate>
            <div class="field">
              <label for="title">Event Title</label>
              <input id="title" name="title" type="text" placeholder="e.g. API latency incident" />
              <div class="error" id="titleError"></div>
            </div>

            <div class="form-row">
              <div class="field">
                <label for="severity">Severity</label>
                <select id="severity" name="severity">
                  <option value="">Select severity</option>
                  <option value="Low">Low</option>
                  <option value="Medium">Medium</option>
                  <option value="High">High</option>
                  <option value="Critical">Critical</option>
                </select>
                <div class="error" id="severityError"></div>
              </div>

              <div class="field">
                <label for="owner">Owner</label>
                <input id="owner" name="owner" type="text" placeholder="e.g. Ops Team" />
                <div class="error" id="ownerError"></div>
              </div>
            </div>

            <div class="field">
              <label for="notes">Notes</label>
              <textarea id="notes" name="notes" rows="4" placeholder="Describe the event..."></textarea>
              <div class="error" id="notesError"></div>
            </div>

            <div class="form-row">
              <button type="submit">Submit Event</button>
              <button type="button" id="simulateAlertBtn" class="secondary">Simulate Alert</button>
            </div>

            <div class="success" id="formSuccess"></div>
          </form>
