  </div>

  <script>
    const state = {
      live: true,
      maxPoints: 60,
      data: [],
      metrics: {
        cpu: 42,
        memory: 58,
        requests: 220,
        users: 1200
      }
    };

    const els = {
      canvas: document.getElementById('chartCanvas'),
      cpuValue: document.getElementById('cpuValue'),
      memoryValue: document.getElementById('memoryValue'),
      requestsValue: document.getElementById('requestsValue'),
      usersValue: document.getElementById('usersValue'),
      cpuTrend: document.getElementById('cpuTrend'),
      memoryTrend: document.getElementById('memoryTrend'),
      requestsTrend: document.getElementById('requestsTrend'),
      usersTrend: document.getElementById('usersTrend'),
      lastUpdate: document.getElementById('lastUpdate'),
      streamStatus: document.getElementById('streamStatus'),
      toggleStreamBtn: document.getElementById('toggleStreamBtn'),
      injectSpikeBtn: document.getElementById('injectSpikeBtn'),
      clearLogsBtn: document.getElementById('clearLogsBtn'),
      logList: document.getElementById('logList'),
      eventForm: document.getElementById('eventForm'),
      formSuccess: document.getElementById('formSuccess'),
      simulateAlertBtn: document.getElementById('simulateAlertBtn'),
      title: document.getElementById('title'),
      severity: document.getElementById('severity'),
      owner: document.getElementById('owner'),
      notes: document.getElementById('notes'),
      titleError: document.getElementById('titleError'),
      severityError: document.getElementById('severityError'),
      ownerError: document.getElementById('ownerError'),
      notesError: document.getElementById('notesError')
    };

    const ctx = els.canvas.getContext('2d');

    function resizeCanvas() {
      const rect = els.canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      els.canvas.width = rect.width * dpr;
      els.canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function randomDelta(range) {
      return (Math.random() * range * 2) - range;
    }

    function generateNextMetrics() {
      const prev = { ...state.metrics };

      state.metrics.cpu = clamp(prev.cpu + randomDelta(6), 5, 100);
      state.metrics.memory = clamp(prev.memory + randomDelta(4), 15, 100);
      state.metrics.requests = clamp(prev.requests + randomDelta(35), 20, 500);
      state.metrics.users = clamp(prev.users + randomDelta(50), 100, 5000);

      return {
        timestamp: new Date(),
        cpu: state.metrics.cpu,
        memory: state.metrics.memory,
        requests: state.metrics.requests,
        users: state.metrics.users,
        prev
      };
    }

    function pushDataPoint(point) {
      state.data.push(point);
      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }
    }

    function formatTime(date) {
      return date.toLocaleTimeString();
    }

    function trendText(current, previous, suffix = '', decimals = 1) {
      const diff = current - previous;
      const sign = diff >= 0 ? '+' : '';
      const cls = diff >= 0 ? 'up' : 'down';
      return `<span class="${cls}">${sign}${diff.toFixed(decimals)}${suffix}</span>`;
    }

    function updateKPIs(point) {
      const { cpu, memory, requests, users, prev } = point;

      els.cpuValue.textContent = `${cpu.toFixed(1)}%`;
      els.memoryValue.textContent = `${memory.toFixed(1)}%`;
      els.requestsValue.textContent = `${Math.round(requests)}`;
      els.usersValue.textContent = `${Math.round(users).toLocaleString()}`;

      els.cpuTrend.innerHTML = trendText(cpu, prev.cpu, '%');
      els.memoryTrend.innerHTML = trendText(memory, prev.memory, '%');
      els.requestsTrend.innerHTML = trendText(requests, prev.requests, '', 0);
      els.usersTrend.innerHTML = trendText(users, prev.users, '', 0);

      els.lastUpdate.textContent = formatTime(point.timestamp);
    }

    function drawGrid(width, height, padding) {
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 6;

      for (let i = 0; i <= rows; i++) {
        const y = padding + ((height - padding * 2) / rows) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = padding + ((width - padding * 2) / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }
    }

    function drawLine(points, color, valueKey, maxValue) {
      if (points.length < 2) return;

      const width = els.canvas.clientWidth;
      const height = els.canvas.clientHeight;
      const padding = 28;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      ctx.beginPath();
      ctx.lineWidth = 2.5;
      ctx.strokeStyle = color;

      points.forEach((point, index) => {
        const x = padding + (index / (points.length - 1)) * chartWidth;
        const y = padding + (1 - point[valueKey] / maxValue) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();
    }

    function drawChart() {
      const width = els.canvas.clientWidth;
      const height = els.canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      drawGrid(width, height, 28);

      drawLine(state.data, '#38bdf8', 'cpu', 100);
      drawLine(state.data, '#22c55e', 'memory', 100);
      drawLine(state.data.map(d => ({ ...d, requestsScaled: d.requests / 5 })), '#f59e0b', 'requestsScaled', 100);

      if (state.data.length) {
        const latest = state.data[state.data.length - 1];
        drawLatestLabel(latest);
      }
    }

    function drawLatestLabel(point) {
      const width = els.canvas.clientWidth;
      const height = els.canvas.clientHeight;
      const padding = 28;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;
      const lastIndex = state.data.length - 1;
      const x = padding + (lastIndex / Math.max(1, state.data.length - 1)) * chartWidth;
      const y = padding + (1 - point.cpu / 100) * chartHeight;

      ctx.fillStyle = '#38bdf8';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#e5e7eb';
      ctx.font = '12px sans-serif';
      ctx.fillText(`CPU ${point.cpu.toFixed(1)}%`, Math.max(10, x - 20), Math.max(16, y - 10));
    }

    function addLog(message, severity = 'Info') {
      const li = document.createElement('li');
      li.className = 'log-item';

      const time = document.createElement('div');
      time.className = 'log-time';
      time.textContent = `${new Date().toLocaleString()} • ${severity}`;

      const text = document.createElement('div');
      text.textContent = message;

      li.appendChild(time);
      li.appendChild(text);

      els.logList.prepend(li);

      while (els.logList.children.length > 25) {
        els.logList.removeChild(els.logList.lastChild);
      }
    }

    function tick() {
      if (!state.live) return;
      const point = generateNextMetrics();
      pushDataPoint(point);
      updateKPIs(point);
      drawChart();

      if (point.cpu > 90) addLog(`CPU usage is high at ${point.cpu.toFixed(1)}%`, 'Warning');
      if (point.memory > 92) addLog(`Memory usage is critical at ${point.memory.toFixed(1)}%`, 'Critical');
    }

    function setLiveStatus(isLive) {
      state.live = isLive;
      els.streamStatus.textContent = isLive ? 'LIVE' : 'PAUSED';
      els.streamStatus.className = `badge ${isLive ? 'live' : 'paused'}`;
      els.toggleStreamBtn.textContent = isLive ? 'Pause Stream' : 'Resume Stream';
      addLog(`Data stream ${isLive ? 'resumed' : 'paused'}`, 'System');
    }

    function injectSpike() {
      state.metrics.cpu = clamp(state.metrics.cpu + 25, 0, 100);
      state.metrics.memory = clamp(state.metrics.memory + 12, 0, 100);
      state.metrics.requests = clamp(state.metrics.requests + 140, 0, 500);
      state.metrics.users = clamp(state.metrics.users + 300, 0, 5000);

      addLog('Manual traffic spike injected', 'Action');
    }

    function clearErrors() {
      els.titleError.textContent = '';
      els.severityError.textContent = '';
      els.ownerError.textContent = '';
      els.notesError.textContent = '';
      els.formSuccess.textContent = '';
    }

    function validateForm(values) {
      clearErrors();
      let valid = true;

      if (!values.title.trim()) {
        els.titleError.textContent = 'Title is required.';
        valid = false;
      } else if (values.title.trim().length < 4) {
        els.titleError.textContent = 'Title must be at least 4 characters.';
        valid = false;
      }

      if (!values.severity) {
        els.severityError.textContent = 'Severity is required.';
        valid = false;
      }

      if (!values.owner.trim()) {
        els.ownerError.textContent = 'Owner is required.';
        valid = false;
      }

      if (!values.notes.trim()) {
        els.notesError.textContent = 'Notes are required.';
        valid = false;
      } else if (values.notes.trim().length < 10) {
        els.notesError.textContent = 'Notes must be at least 10 characters.';
        valid = false;
      }

      return valid;
    }

    function handleFormSubmit(event) {
      event.preventDefault();

      const values = {
        title: els.title.value,
        severity: els.severity.value,
        owner: els.owner.value,
        notes: els.notes.value
      };

      if (!validateForm(values)) return;

      addLog(
        `Event submitted: "${values.title}" assigned to ${values.owner}. Notes: ${values.notes}`,
        values.severity
      );

      els.formSuccess.textContent = 'Event submitted successfully.';
      els.eventForm.reset();
    }

    function simulateAlert() {
      const alerts = [
        { title: 'API latency elevated', severity: 'High' },
        { title: 'Database connection retries detected', severity: 'Medium' },
        { title: 'Cache miss ratio spike', severity: 'Low' },
        { title: 'Node unavailable in cluster', severity: 'Critical' }
      ];

      const alert = alerts[Math.floor(Math.random() * alerts.length)];
      addLog(`Simulated alert: ${alert.title}`, alert.severity);
    }

    els.toggleStreamBtn.addEventListener('click', () => {
      setLiveStatus(!state.live);
    });

    els.injectSpikeBtn.addEventListener('click', injectSpike);
    els.clearLogsBtn.addEventListener('click', () => {
      els.logList.innerHTML = '';
      addLog('Logs cleared', 'System');
    });

    els.eventForm.addEventListener('submit', handleFormSubmit);
    els.simulateAlertBtn.addEventListener('click', simulateAlert);
    window.addEventListener('resize', resizeCanvas);

    for (let i = 0; i < state.maxPoints; i++) {
      const point = generateNextMetrics();
      pushDataPoint(point);
    }

    updateKPIs(state.data[state.data.length - 1]);
    resizeCanvas();
    drawChart();
    addLog('Dashboard initialized', 'System');

    setInterval(tick, 1000);
  </script>
</body>
</html>
