  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const entryCountEl = document.getElementById('entryCount');

    const form = document.getElementById('recordForm');
    const toast = document.getElementById('toast');
    const tableBody = document.getElementById('recordsTableBody');

    const fields = {
      name: document.getElementById('name'),
      category: document.getElementById('category'),
      priority: document.getElementById('priority'),
      notes: document.getElementById('notes')
    };

    const errors = {
      name: document.getElementById('nameError'),
      category: document.getElementById('categoryError'),
      priority: document.getElementById('priorityError'),
      notes: document.getElementById('notesError')
    };

    const state = {
      data: [],
      maxPoints: 40,
      records: [],
      peak: 0
    };

    function randomValue() {
      const base = 50 + Math.sin(Date.now() / 1000) * 20;
      const noise = Math.random() * 18 - 9;
      return Math.max(5, Math.round(base + noise));
    }

    function addDataPoint() {
      const value = randomValue();
      state.data.push(value);
      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }
      state.peak = Math.max(state.peak, value);
      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      const latest = state.data[state.data.length - 1] ?? 0;
      const avg = state.data.length
        ? state.data.reduce((sum, n) => sum + n, 0) / state.data.length
        : 0;

      currentValueEl.textContent = latest.toFixed(0);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = state.peak.toFixed(0);
      entryCountEl.textContent = state.records.length.toString();
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      const padding = 32;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      // Grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = padding + (chartH / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      if (state.data.length < 2) return;

      const maxVal = Math.max(...state.data, 100);
      const minVal = Math.min(...state.data, 0);
      const range = maxVal - minVal || 1;

      // Area fill
      ctx.beginPath();
      state.data.forEach((value, index) => {
        const x = padding + (index / (state.maxPoints - 1)) * chartW;
        const y = padding + chartH - ((value - minVal) / range) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding + chartW, padding + chartH);
      ctx.lineTo(padding, padding + chartH);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, padding + chartH);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(34, 197, 94, 0.05)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      state.data.forEach((value, index) => {
        const x = padding + (index / (state.maxPoints - 1)) * chartW;
        const y = padding + chartH - ((value - minVal) / range) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#60a5fa';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      state.data.forEach((value, index) => {
        const x = padding + (index / (state.maxPoints - 1)) * chartW;
        const y = padding + chartH - ((value - minVal) / range) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = 'rgba(229, 231, 235, 0.8)';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Max: ${maxVal}`, padding, padding - 10);
      ctx.fillText(`Min: ${minVal}`, width - padding - 60, padding - 10);
    }

    function validateForm() {
      let valid = true;

      Object.values(errors).forEach(el => el.textContent = '');

      if (!fields.name.value.trim()) {
        errors.name.textContent = 'Name is required.';
        valid = false;
      } else if (fields.name.value.trim().length < 2) {
        errors.name.textContent = 'Name must be at least 2 characters.';
        valid = false;
      }

      if (!fields.category.value) {
        errors.category.textContent = 'Category is required.';
        valid = false;
      }

      if (!fields.priority.value) {
        errors.priority.textContent = 'Priority is required.';
        valid = false;
      }

      if (fields.notes.value.length > 200) {
        errors.notes.textContent = 'Notes must be 200 characters or fewer.';
        valid = false;
      }

      return valid;
    }

    function showToast(message, type = 'success') {
      toast.textContent = message;
      toast.className = `toast ${type}`;
      setTimeout(() => {
        toast.className = 'toast';
        toast.textContent = '';
      }, 2500);
    }

    function addRecord(record) {
      state.records.unshift(record);
      renderRecords();
      updateMetrics();
    }

    function renderRecords() {
      tableBody.innerHTML = '';
      state.records.forEach(record => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${record.time}</td>
          <td>${escapeHtml(record.name)}</td>
          <td>${escapeHtml(record.category)}</td>
          <td><span class="badge ${record.priority}">${capitalize(record.priority)}</span></td>
          <td>${escapeHtml(record.notes || '-')}</td>
        `;
        tableBody.appendChild(tr);
      });
    }

    function capitalize(str) {
      return str.charAt(0).toUpperCase() + str.slice(1);
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      if (!validateForm()) {
        showToast('Please fix the form errors.', 'error');
        return;
      }

      const record = {
        time: new Date().toLocaleTimeString(),
        name: fields.name.value.trim(),
        category: fields.category.value,
        priority: fields.priority.value,
        notes: fields.notes.value.trim()
      };

      addRecord(record);
      form.reset();
      showToast('Record submitted successfully.', 'success');
    });

    form.addEventListener('reset', () => {
      setTimeout(() => {
        Object.values(errors).forEach(el => el.textContent = '');
        toast.className = 'toast';
        toast.textContent = '';
      }, 0);
    });

    // Seed initial data
    for (let i = 0; i < 20; i++) {
      state.data.push(randomValue());
    }
    state.peak = Math.max(...state.data);
    updateMetrics();
    drawChart();

    // Real-time updates
    setInterval(addDataPoint, 1000);
  </script>
</body>
</html>
