<body>
  <div class="container">
    <div class="header">
      <div class="title">
        <h1>Interactive Real-Time Dashboard</h1>
        <p>Live metrics, chart updates, and manual event submission</p>
      </div>
      <div class="status">
        <span class="status-dot"></span>
        <span id="liveStatus">Streaming live data</span>
      </div>
    </div>

    <div class="stats">
      <div class="stat-card">
        <div class="stat-label">Current Value</div>
        <div class="stat-value" id="currentValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>
      <div class="stat-card">
