            The chart updates every second with simulated values. You can also inject manual values using the form.
          </div>
        </div>

        <div class="panel" style="margin-top: 20px;">
          <h2>Recent Events</h2>
          <div class="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Time</th>
                  <th>Label</th>
                  <th>Value</th>
                  <th>Source</th>
                </tr>
              </thead>
              <tbody id="eventsTableBody"></tbody>
            </table>
          </div>
        </div>
      </div>

      <div>
        <div class="panel">
          <h2>Add Data Point</h2>
          <form id="dataForm">
            <div class="form-group">
              <label for="labelInput">Label</label>
              <input id="labelInput" type="text" placeholder="e.g. Sensor A" required />
            </div>

            <div class="form-row">
              <div class="form-group">
                <label for="valueInput">Value</label>
                <input id="valueInput" type="number" step="0.1" min="0" placeholder="e.g. 72.5" required />
              </div>
              <div class="form-group">
                <label for="categoryInput">Category</label>
                <select id="categoryInput">
                  <option value="manual">Manual</option>
                  <option value="alert">Alert</option>
                  <option value="system">System</option>
