                <input id="speedRange" type="range" min="250" max="3000" step="250" value="1000" />
              </div>
              <div class="small">Adjust how often simulated real-time data arrives.</div>
            </div>

            <button type="submit" class="btn-primary">Submit Data Point</button>
            <div id="formMessage" class="message"></div>
          </form>
        </div>
      </div>
    </div>
  </div>

  <script>
    const chartCanvas = document.getElementById("chartCanvas");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const eventCountEl = document.getElementById("eventCount");
    const eventsTableBody = document.getElementById("eventsTableBody");
    const liveStatusEl = document.getElementById("liveStatus");

    const dataForm = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");
    const categoryInput = document.getElementById("categoryInput");
    const notesInput = document.getElementById("notesInput");
    const formMessage = document.getElementById("formMessage");
    const speedRange = document.getElementById("speedRange");
    const speedValue = document.getElementById("speedValue");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const MAX_POINTS = 40;
    let dataPoints = [];
    let events = [];
    let timer = null;
    let intervalMs = Number(speedRange.value);

    function resizeCanvasForDisplay() {
      const ratio = window.devicePixelRatio || 1;
      const rect = chartCanvas.getBoundingClientRect();
      chartCanvas.width = rect.width * ratio;
      chartCanvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function randomValue() {
      const base = 50;
      const variance = 30;
      return +(base + Math.random() * variance + Math.sin(Date.now() / 2000) * 10).toFixed(1);
    }

    function timestamp() {
      return new Date().toLocaleTimeString();
    }

    function addDataPoint(value, label = "Auto Stream", source = "auto", notes = "") {
      const point = {
        time: timestamp(),
        value: Number(value),
        label,
        source,
        notes
      };

      dataPoints.push(point);
      events.unshift(point);

      if (dataPoints.length > MAX_POINTS) dataPoints.shift();
      if (events.length > 12) events.pop();

      updateStats();
      renderEvents();
      drawChart();
    }

    function updateStats() {
      if (!dataPoints.length) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        eventCountEl.textContent = "0";
        return;
      }

      const values = dataPoints.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      eventCountEl.textContent = String(events.length);
    }

    function renderEvents() {
      eventsTableBody.innerHTML = "";

      events.forEach(event => {
        const tr = document.createElement("tr");
        tr.innerHTML = `
          <td>${event.time}</td>
          <td>${escapeHtml(event.label)}</td>
          <td>${event.value.toFixed(1)}</td>
          <td>
            <span class="badge ${event.source === "auto" ? "auto" : "manual"}">
              ${escapeHtml(event.source)}
            </span>
          </td>
        `;
        eventsTableBody.appendChild(tr);
      });
    }

    function drawChart() {
      const rect = chartCanvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.clearRect(0, 0, width, height);

      const padding = 36;
      const innerWidth = width - padding * 2;
      const innerHeight = height - padding * 2;

      // Background grid
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + (innerHeight / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 6; i++) {
        const x = padding + (innerWidth / 6) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = "rgba(229,231,235,0.7)";
      ctx.font = "12px sans-serif";
      ctx.fillText("Value", 8, 16);
      ctx.fillText("Time →", width - 70, height - 10);

      if (dataPoints.length < 2) {
        ctx.fillStyle = "rgba(148,163,184,0.9)";
        ctx.font = "16px sans-serif";
        ctx.fillText("Waiting for data...", padding + 10, padding + 24);
        return;
      }

      const values = dataPoints.map(p => p.value);
      const min = Math.min(...values);
      const max = Math.max(...values);
      const range = Math.max(max - min, 10);

      const points = dataPoints.map((point, index) => {
        const x = padding + (index / (MAX_POINTS - 1)) * innerWidth;
        const y = padding + innerHeight - ((point.value - min) / range) * innerHeight;
        return { x, y, ...point };
      });

      // Area fill
      ctx.beginPath();
      ctx.moveTo(points[0].x, height - padding);
      points.forEach(p => ctx.lineTo(p.x, p.y));
      ctx.lineTo(points[points.length - 1].x, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, "rgba(59,130,246,0.35)");
      gradient.addColorStop(1, "rgba(59,130,246,0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      ctx.moveTo(points[0].x, points[0].y);
      points.forEach(p => ctx.lineTo(p.x, p.y));
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      points.forEach((p, i) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, i === points.length - 1 ? 5 : 3, 0, Math.PI * 2);
        ctx.fillStyle = i === points.length - 1 ? "#22c55e" : "#dbeafe";
        ctx.fill();
      });

      // Min/Max labels
      ctx.fillStyle = "rgba(229,231,235,0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText(max.toFixed(1), 6, padding + 4);
      ctx.fillText(min.toFixed(1), 6, height - padding + 4);
    }

    function startStreaming() {
      stopStreaming();
      timer = setInterval(() => {
        addDataPoint(randomValue(), "Auto Stream", "auto");
      }, intervalMs);
      liveStatusEl.textContent = `Streaming live data (${intervalMs} ms)`;
    }

    function stopStreaming() {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
      liveStatusEl.textContent = "Stream paused";
    }

    function resetDashboard() {
      dataPoints = [];
      events = [];
      updateStats();
      renderEvents();
      drawChart();
      showMessage("Dashboard reset.", "success");
    }

    function showMessage(text, type = "success") {
      formMessage.textContent = text;
      formMessage.className = `message ${type}`;
      setTimeout(() => {
        formMessage.className = "message";
        formMessage.textContent = "";
      }, 2500);
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);
      const category = categoryInput.value;
      const notes = notesInput.value.trim();

      if (!label) {
        showMessage("Label is required.", "error");
        return;
      }

      if (Number.isNaN(value) || value < 0) {
        showMessage("Please enter a valid non-negative value.", "error");
        return;
      }

      addDataPoint(value, `${label} (${category})`, "manual", notes);
      showMessage("Manual data point added.", "success");
      dataForm.reset();
      speedRange.value = intervalMs;
      speedValue.textContent = intervalMs;
    });

    speedRange.addEventListener("input", () => {
      intervalMs = Number(speedRange.value);
      speedValue.textContent = intervalMs;

      if (timer) {
        startStreaming();
      }
    });

    startBtn.addEventListener("click", startStreaming);
    stopBtn.addEventListener("click", stopStreaming);
    resetBtn.addEventListener("click", resetDashboard);

    window.addEventListener("resize", resizeCanvasForDisplay);

    // Seed initial data
    for (let i = 0; i < 12; i++) {
      addDataPoint(randomValue(), "Auto Stream", "auto");
    }

    resizeCanvasForDisplay();
    startStreaming();
  </script>
</body>
</html>
