    .pill-high {
      background: rgba(239, 68, 68, 0.15);
      color: #fca5a5;
    }

    @media (max-width: 1000px) {
      .metrics {
        grid-template-columns: repeat(2, 1fr);
      }

      .chart-panel,
      .form-panel {
        grid-column: span 12;
      }
    }

    @media (max-width: 640px) {
      .metrics {
        grid-template-columns: 1fr;
      }

      .container {
        padding: 16px;
      }

      .metric-value {
        font-size: 1.6rem;
      }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Interactive Real-Time Dashboard</h1>
        <p>Live metrics, streaming chart, and form submissions in one browser-based UI.</p>
      </div>
      <div class="status-badge" id="statusBadge">
        <span class="status-dot"></span>
        <span id="statusText">Streaming Active</span>
      </div>
    </div>

    <div class="grid">
      <section class="metrics">
        <div class="card metric-card">
          <h3>Current Value</h3>
          <div class="metric-value" id="currentValue">0</div>
          <div class="metric-sub">Latest data point</div>
        </div>
        <div class="card metric-card">
          <h3>Average</h3>
          <div class="metric-value" id="averageValue">0</div>
          <div class="metric-sub">Rolling average</div>
        </div>
        <div class="card metric-card">
          <h3>Peak</h3>
