          <h2>Submitted Events</h2>
        </div>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Name</th>
              <th>Email</th>
              <th>Priority</th>
              <th>Message</th>
            </tr>
          </thead>
          <tbody id="eventsTableBody">
            <tr>
              <td colspan="5" style="color: var(--muted); text-align: center;">No submissions yet</td>
            </tr>
          </tbody>
        </table>
      </section>
    </div>
  </div>

  <script>
    const chartCanvas = document.getElementById("chartCanvas");
    const ctx = chartCanvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const sampleCountEl = document.getElementById("sampleCount");
    const statusTextEl = document.getElementById("statusText");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const eventForm = document.getElementById("eventForm");
    const eventsTableBody = document.getElementById("eventsTableBody");

    const maxPoints = 60;
    let dataPoints = [];
    let timer = null;
    let streaming = true;

    function generateDataPoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1].value : 50;
      const noise = (Math.random() - 0.5) * 12;
      const trend = Math.sin(Date.now() / 1500) * 2;
      let next = last + noise + trend;
      next = Math.max(10, Math.min(100, next));
      return {
        time: new Date(),
        value: Number(next.toFixed(1))
      };
    }

    function addDataPoint() {
      dataPoints.push(generateDataPoint());
      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
      }
      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (!dataPoints.length) {
        currentValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        sampleCountEl.textContent = "0";
        return;
      }

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const average = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = average.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      sampleCountEl.textContent = String(dataPoints.length);
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      drawGrid(width, height);

      if (dataPoints.length < 2) return;

      const padding = 30;
      const minY = 0;
      const maxY = 100;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = height - padding - ((point.value - minY) / (maxY - minY)) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.stroke();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.35)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");

      ctx.lineTo(padding + ((dataPoints.length - 1) / (maxPoints - 1)) * chartWidth, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      dataPoints.forEach((point, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = height - padding - ((point.value - minY) / (maxY - minY)) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });

      drawAxesLabels(width, height, padding);
    }

    function drawGrid(width, height) {
      ctx.save();
      ctx.strokeStyle = "rgba(148, 163, 184, 0.12)";
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 6;

      for (let i = 1; i < rows; i++) {
        const y = (height / rows) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 1; i < cols; i++) {
        const x = (width / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawAxesLabels(width, height, padding) {
      ctx.save();
      ctx.fillStyle = "rgba(229, 231, 235, 0.7)";
      ctx.font = "12px sans-serif";

      [0, 25, 50, 75, 100].forEach(value => {
        const y = height - padding - (value / 100) * (height - padding * 2);
        ctx.fillText(String(value), 4, y + 4);
      });

      ctx.fillText("Live Value", width - 70, 18);
      ctx.restore();
    }

    function startStreaming() {
      if (timer) return;
      streaming = true;
      statusTextEl.textContent = "Streaming Active";
      timer = setInterval(addDataPoint, 1000);
    }

    function stopStreaming() {
      streaming = false;
      statusTextEl.textContent = "Streaming Paused";
      clearInterval(timer);
      timer = null;
    }

    function resetStreaming() {
      dataPoints = [];
      updateMetrics();
      drawChart();
    }

    startBtn.addEventListener("click", startStreaming);
    stopBtn.addEventListener("click", stopStreaming);
    resetBtn.addEventListener("click", resetStreaming);

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      setError("nameError", "");
      setError("emailError", "");
      setError("priorityError", "");
      setError("messageError", "");
      document.getElementById("formSuccess").textContent = "";
    }

    function validateForm(data) {
      let valid = true;
      clearErrors();

      if (!data.name.trim()) {
        setError("nameError", "Name is required.");
        valid = false;
      }

      if (!data.email.trim()) {
        setError("emailError", "Email is required.");
        valid = false;
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) {
        setError("emailError", "Enter a valid email address.");
        valid = false;
      }

      if (!data.priority) {
        setError("priorityError", "Please select a priority.");
        valid = false;
      }

      if (!data.message.trim()) {
        setError("messageError", "Message is required.");
        valid = false;
      } else if (data.message.trim().length < 10) {
        setError("messageError", "Message must be at least 10 characters.");
        valid = false;
      }

      return valid;
    }

    function priorityClass(priority) {
      if (priority === "Low") return "pill pill-low";
      if (priority === "Medium") return "pill pill-medium";
      return "pill pill-high";
    }

    function addSubmissionToTable(data) {
      const emptyRow = eventsTableBody.querySelector("td[colspan='5']");
      if (emptyRow) {
        eventsTableBody.innerHTML = "";
      }

      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${new Date().toLocaleTimeString()}</td>
        <td>${escapeHtml(data.name)}</td>
        <td>${escapeHtml(data.email)}</td>
        <td><span class="${priorityClass(data.priority)}">${escapeHtml(data.priority)}</span></td>
        <td>${escapeHtml(data.message)}</td>
      `;

      eventsTableBody.prepend(row);
    }

    function escapeHtml(str) {
      return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = {
        name: document.getElementById("name").value,
        email: document.getElementById("email").value,
        priority: document.getElementById("priority").value,
        message: document.getElementById("message").value
      };

      if (!validateForm(formData)) return;

      addSubmissionToTable(formData);
      document.getElementById("formSuccess").textContent = "Event submitted successfully.";
      eventForm.reset();
    });

    for (let i = 0; i < 20; i++) {
      addDataPoint();
    }
    startStreaming();
  </script>
</body>
</html>
```

## Features included
- **Real-time chart** using the HTML5 `<canvas>`
- **Live metrics**:
  - current value
  - average
  - peak
  - sample count
- **Interactive controls**:
  - start
  - stop
  - reset
- **Form handling** with:
  - required field checks
  - email validation
  - minimum message length
- **Submission table** that updates instantly
- **Basic XSS protection** via HTML escaping before rendering user input

