    const statusDot = document.getElementById("statusDot");
    const statusText = document.getElementById("statusText");

    const form = document.getElementById("recordForm");
    const tableBody = document.getElementById("recordsTableBody");
    const formSuccess = document.getElementById("formSuccess");

    const maxPoints = 50;
    let data = [];
    let timer = null;
    let peak = 0;
    let submissionCount = 0;

    function generateValue() {
      const base = 50;
      const variance = Math.random() * 40 - 20;
      const trend = Math.sin(Date.now() / 2000) * 15;
      return Math.max(5, Math.round(base + variance + trend));
    }

    function updateMetrics() {
      const current = data.length ? data[data.length - 1] : 0;
      const avg = data.length
        ? (data.reduce((sum, value) => sum + value, 0) / data.length).toFixed(1)
        : 0;

      peak = data.length ? Math.max(...data, peak) : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      peakValueEl.textContent = peak;
      submissionCountEl.textContent = submissionCount;
    }

    function drawChart() {
      const { width, height } = chartCanvas;
      ctx.clearRect(0, 0, width, height);

      drawGrid(width, height);
      drawAxes(width, height);

      if (data.length < 2) return;

      const padding = 40;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;
      const maxVal = Math.max(...data, 100);
      const minVal = Math.min(...data, 0);
      const range = maxVal - minVal || 1;

      ctx.beginPath();
      ctx.lineWidth = 3;
      ctx.strokeStyle = "#3b82f6";

      data.forEach((value, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = height - padding - ((value - minVal) / range) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.lineTo(padding + chartWidth, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = "rgba(59, 130, 246, 0.12)";
      ctx.fill();

      data.forEach((value, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = height - padding - ((value - minVal) / range) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });

      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      ctx.fillText(`Max: ${maxVal}`, 8, 18);
      ctx.fillText(`Min: ${minVal}`, 8, height - 10);
    }

    function drawGrid(width, height) {
      ctx.strokeStyle = "rgba(148, 163, 184, 0.12)";
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 6;

      for (let i = 0; i <= rows; i++) {
        const y = (height / rows) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = (width / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
    }

    function drawAxes(width, height) {
      ctx.strokeStyle = "rgba(226, 232, 240, 0.3)";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(40, 10);
      ctx.lineTo(40, height - 40);
      ctx.lineTo(width - 10, height - 40);
      ctx.stroke();
    }

    function tick() {
      const nextValue = generateValue();
      data.push(nextValue);
      if (data.length > maxPoints) data.shift();
      updateMetrics();
      drawChart();
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(tick, 500);
      statusDot.classList.remove("paused");
      statusText.textContent = "Streaming live data";
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
      statusDot.classList.add("paused");
      statusText.textContent = "Stream paused";
    }

    function resetDashboard() {
      stopStream();
      data = [];
      peak = 0;
      drawChart();
      updateMetrics();
      statusText.textContent = "Dashboard reset";
    }

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    function clearErrors() {
      ["name", "category", "priority", "notes"].forEach(field => {
        document.getElementById(field + "Error").textContent = "";
      });
      formSuccess.textContent = "";
    }

    function validateForm(values) {
      const errors = {};

      if (!values.name.trim()) {
        errors.name = "Name is required.";
      } else if (values.name.trim().length < 2) {
        errors.name = "Name must be at least 2 characters.";
      }

      if (!values.category) {
        errors.category = "Please select a category.";
      }

      if (!values.priority) {
        errors.priority = "Please select a priority.";
      }

      if (!values.notes.trim()) {
        errors.notes = "Notes are required.";
      } else if (values.notes.trim().length < 5) {
        errors.notes = "Notes must be at least 5 characters.";
      }

      return errors;
    }

    function priorityBadge(priority) {
      const cls = priority.toLowerCase();
      return `<span class="badge ${cls}">${priority}</span>`;
    }

    function addTableRow(record) {
      const emptyRow = tableBody.querySelector("td[colspan='5']");
      if (emptyRow) {
        tableBody.innerHTML = "";
      }

      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${record.time}</td>
        <td>${escapeHtml(record.name)}</td>
        <td>${escapeHtml(record.category)}</td>
        <td>${priorityBadge(record.priority)}</td>
        <td>${escapeHtml(record.notes)}</td>
      `;
      tableBody.prepend(row);
    }

    function escapeHtml(str) {
      const div = document.createElement("div");
      div.textContent = str;
      return div.innerHTML;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const values = {
        name: form.name.value,
        category: form.category.value,
        priority: form.priority.value,
        notes: form.notes.value
      };

      const errors = validateForm(values);

      if (Object.keys(errors).length > 0) {
        Object.entries(errors).forEach(([field, message]) => {
          document.getElementById(field + "Error").textContent = message;
        });
        return;
      }

      const now = new Date();
      const record = {
        ...values,
        time: now.toLocaleTimeString()
      };

      addTableRow(record);
      submissionCount++;
      updateMetrics();

      form.reset();
      formSuccess.textContent = "Record submitted successfully.";
    });

    function resizeCanvasForDisplay() {
      const rect = chartCanvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      chartCanvas.width = rect.width * dpr;
      chartCanvas.height = 320 * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    window.addEventListener("resize", resizeCanvasForDisplay);

    resizeCanvasForDisplay();
    for (let i = 0; i < 12; i++) {
      data.push(generateValue());
    }
    updateMetrics();
    drawChart();
    startStream();
  </script>
</body>
</html>
```

## Features included
- Live updating chart using `<canvas>`
- Real-time metrics:
  - current value
  - average
  - peak
  - submission count
- Form validation
- Safe rendering of submitted text
- Dynamic table updates
- Responsive layout
- Start, stop, and reset controls

