  </div>

  <script>
    const MAX_POINTS = 60;
    const dataPoints = [];
    let intervalId = null;
    let peak = 0;
    let running = false;
    let eventCounter = 0;

    const canvas = document.getElementById("chartCanvas");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const eventCountEl = document.getElementById("eventCount");
    const statusBadge = document.getElementById("statusBadge");

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    const form = document.getElementById("eventForm");
    const eventsTableBody = document.getElementById("eventsTableBody");
    const formSuccess = document.getElementById("formSuccess");

    function resizeCanvasForDisplay() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = 320 * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function generateDataPoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1] : 50;
      const next = Math.max(5, Math.min(100, last + (Math.random() * 20 - 10)));
      dataPoints.push(Number(next.toFixed(1)));
      if (dataPoints.length > MAX_POINTS) dataPoints.shift();

      peak = Math.max(peak, next);
      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      const current = dataPoints.length ? dataPoints[dataPoints.length - 1] : 0;
      const avg = dataPoints.length
        ? dataPoints.reduce((sum, v) => sum + v, 0) / dataPoints.length
        : 0;

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      eventCountEl.textContent = eventCounter;
    }

    function drawChart() {
      const width = canvas.getBoundingClientRect().width;
      const height = 320;
      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 6; i++) {
        const x = (width / 6) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      if (dataPoints.length < 2) return;

      // Area fill
      const stepX = width / (MAX_POINTS - 1);

      ctx.beginPath();
      dataPoints.forEach((value, index) => {
        const x = index * stepX;
        const y = height - (value / 100) * (height - 20) - 10;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo((dataPoints.length - 1) * stepX, height);
      ctx.lineTo(0, height);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.35)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((value, index) => {
        const x = index * stepX;
        const y = height - (value / 100) * (height - 20) - 10;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((value, index) => {
        const x = index * stepX;
        const y = height - (value / 100) * (height - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });
    }

    function startStream() {
      if (running) return;
      running = true;
      statusBadge.textContent = "Live Stream: Running";
      statusBadge.style.background = "rgba(34, 197, 94, 0.15)";
      statusBadge.style.color = "#86efac";
      intervalId = setInterval(generateDataPoint, 1000);
    }

    function stopStream() {
      running = false;
      clearInterval(intervalId);
      statusBadge.textContent = "Live Stream: Stopped";
      statusBadge.style.background = "rgba(239, 68, 68, 0.15)";
      statusBadge.style.color = "#fca5a5";
    }

    function resetDashboard() {
      stopStream();
      dataPoints.length = 0;
      peak = 0;
      updateMetrics();
      drawChart();
    }

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetDashboard);

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      ["nameError", "emailError", "categoryError", "messageError"].forEach(id => {
        setError(id, "");
      });
      formSuccess.textContent = "";
    }

    function validateEmail(email) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function categoryTagClass(category) {
      if (category === "Info") return "info";
      if (category === "Warning") return "warn";
      return "ok";
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const name = document.getElementById("name").value.trim();
      const email = document.getElementById("email").value.trim();
      const category = document.getElementById("category").value;
      const message = document.getElementById("message").value.trim();

      let valid = true;

      if (!name || name.length < 2) {
        setError("nameError", "Please enter a valid name.");
        valid = false;
      }

      if (!email || !validateEmail(email)) {
        setError("emailError", "Please enter a valid email address.");
        valid = false;
      }

      if (!category) {
        setError("categoryError", "Please select a category.");
        valid = false;
      }

      if (!message || message.length < 5) {
        setError("messageError", "Message must be at least 5 characters.");
        valid = false;
      }

      if (!valid) return;

      const now = new Date().toLocaleTimeString();
      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${now}</td>
        <td>${escapeHtml(name)}</td>
        <td>${escapeHtml(email)}</td>
        <td><span class="tag ${categoryTagClass(category)}">${escapeHtml(category)}</span></td>
        <td>${escapeHtml(message)}</td>
      `;

      if (eventsTableBody.children.length === 1 &&
          eventsTableBody.children[0].textContent.includes("No events submitted yet")) {
        eventsTableBody.innerHTML = "";
      }

      eventsTableBody.prepend(row);
      eventCounter++;
      updateMetrics();
      formSuccess.textContent = "Event submitted successfully.";
      form.reset();
    });

    function escapeHtml(str) {
      const div = document.createElement("div");
      div.textContent = str;
      return div.innerHTML;
    }

    window.addEventListener("resize", resizeCanvasForDisplay);

    // Init
    resizeCanvasForDisplay();
    for (let i = 0; i < 20; i++) generateDataPoint();
    startStream();
  </script>
</body>
</html>
```

