  <script>
    const chartCanvas = document.getElementById('chartCanvas');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const recordCountEl = document.getElementById('recordCount');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const statusText = document.getElementById('statusText');
    const statusBadge = document.getElementById('statusBadge');

    const form = document.getElementById('recordForm');
    const successMessage = document.getElementById('successMessage');
    const recordsTableBody = document.getElementById('recordsTableBody');

    const MAX_POINTS = 40;
    let dataPoints = [];
    let labels = [];
    let streamInterval = null;
    let submittedRecords = [];

    function randomValue() {
      return Math.floor(30 + Math.random() * 70);
    }

    function addDataPoint() {
      const value = randomValue();
      const time = new Date().toLocaleTimeString();

      dataPoints.push(value);
      labels.push(time);

      if (dataPoints.length > MAX_POINTS) {
        dataPoints.shift();
        labels.shift();
      }

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (dataPoints.length === 0) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const current = dataPoints[dataPoints.length - 1];
      const avg = dataPoints.reduce((sum, v) => sum + v, 0) / dataPoints.length;
      const peak = Math.max(...dataPoints);

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak;
      recordCountEl.textContent = submittedRecords.length;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      const padding = 40;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + ((height - padding * 2) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= 6; i++) {
        const x = padding + ((width - padding * 2) / 6) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }

      // Axes
      ctx.strokeStyle = 'rgba(226, 232, 240, 0.35)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, height - padding);
      ctx.lineTo(width - padding, height - padding);
      ctx.stroke();

      if (dataPoints.length < 2) return;

      const minVal = 0;
      const maxVal = 120;
      const plotWidth = width - padding * 2;
      const plotHeight = height - padding * 2;
      const stepX = plotWidth / (MAX_POINTS - 1);

      // Area fill
      ctx.beginPath();
      dataPoints.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = padding + plotHeight - ((value - minVal) / (maxVal - minVal)) * plotHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + (dataPoints.length - 1) * stepX;
      ctx.lineTo(lastX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = padding + plotHeight - ((value - minVal) / (maxVal - minVal)) * plotHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = padding + plotHeight - ((value - minVal) / (maxVal - minVal)) * plotHeight;

        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });

      // Y-axis labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      for (let i = 0; i <= 5; i++) {
        const value = maxVal - (maxVal / 5) * i;
        const y = padding + ((height - padding * 2) / 5) * i + 4;
        ctx.fillText(value.toFixed(0), padding - 8, y);
      }

      // X-axis labels
      ctx.textAlign = 'center';
      const labelStep = Math.max(1, Math.floor(dataPoints.length / 6));
      for (let i = 0; i < dataPoints.length; i += labelStep) {
        const x = padding + i * stepX;
        ctx.fillText(labels[i].split(' ')[0], x, height - padding + 18);
      }
    }

    function startStream() {
      if (streamInterval) return;
      streamInterval = setInterval(addDataPoint, 1000);
      statusText.textContent = 'Streaming live';
      statusBadge.style.background = 'rgba(34, 197, 94, 0.12)';
      statusBadge.style.color = '#86efac';
      statusBadge.style.borderColor = 'rgba(34, 197, 94, 0.3)';
    }

    function stopStream() {
      clearInterval(streamInterval);
      streamInterval = null;
      statusText.textContent = 'Paused';
      statusBadge.style.background = 'rgba(245, 158, 11, 0.12)';
      statusBadge.style.color = '#fcd34d';
      statusBadge.style.borderColor = 'rgba(245, 158, 11, 0.3)';
    }

    function resetStream() {
      stopStream();
      dataPoints = [];
      labels = [];
      updateMetrics();
      drawChart();
    }

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetStream);

    function setError(id, message) {
      document.getElementById(id).textContent = message;
    }

    function clearErrors() {
      setError('nameError', '');
      setError('categoryError', '');
      setError('priorityError', '');
      setError('notesError', '');
      successMessage.textContent = '';
    }

    function priorityClass(priority) {
      if (priority === 'Low') return 'pill pill-low';
      if (priority === 'Medium') return 'pill pill-medium';
      return 'pill pill-high';
    }

    function renderRecords() {
      recordCountEl.textContent = submittedRecords.length;

      if (submittedRecords.length === 0) {
        recordsTableBody.innerHTML = `
          <tr>
            <td colspan="5" style="text-align:center; color: var(--muted);">No records submitted yet.</td>
          </tr>
        `;
        return;
      }

      recordsTableBody.innerHTML = submittedRecords
        .map(record => `
          <tr>
            <td>${record.time}</td>
            <td>${escapeHtml(record.name)}</td>
            <td>${escapeHtml(record.category)}</td>
            <td><span class="${priorityClass(record.priority)}">${escapeHtml(record.priority)}</span></td>
            <td>${escapeHtml(record.notes || '-')}</td>
          </tr>
        `)
        .join('');
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const name = form.name.value.trim();
      const category = form.category.value;
      const priority = form.priority.value;
      const notes = form.notes.value.trim();

      let valid = true;

      if (!name) {
        setError('nameError', 'Name is required.');
        valid = false;
      } else if (name.length < 2) {
        setError('nameError', 'Name must be at least 2 characters.');
        valid = false;
      }

      if (!category) {
        setError('categoryError', 'Please select a category.');
        valid = false;
      }

      if (!priority) {
        setError('priorityError', 'Please select a priority.');
        valid = false;
      }

      if (notes.length > 200) {
        setError('notesError', 'Notes must be 200 characters or fewer.');
        valid = false;
      }

      if (!valid) return;

      const record = {
        time: new Date().toLocaleString(),
        name,
        category,
        priority,
        notes
      };

      submittedRecords.unshift(record);
      renderRecords();

      successMessage.textContent = 'Record submitted successfully.';
      form.reset();
    });

    // Initial state
    for (let i = 0; i < 10; i++) addDataPoint();
    renderRecords();
    startStream();

    // Redraw on resize for sharper layout if desired
    window.addEventListener('resize', drawChart);
  </script>
</body>
</html>
```

