<body>
  <div class="container">
    <h1>Interactive Real-Time Dashboard</h1>
    <div class="subtitle">Live metrics, chart updates, and form-driven event handling.</div>

    <div class="grid">
      <div class="card stat-card">
        <div class="stat-title">Current Value</div>
        <div class="stat-value" id="currentValue">0</div>
      </div>

      <div class="card stat-card">
        <div class="stat-title">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>

      <div class="card stat-card">
        <div class="stat-title">Peak</div>
        <div class="stat-value" id="peakValue">0</div>
      </div>

      <div class="card stat-card">
        <div class="stat-title">Events Submitted</div>
        <div class="stat-value" id="eventCount">0</div>
      </div>

      <div class="card chart-card">
        <h2>Live Data Stream</h2>
        <div class="status-row">
          <span id="streamStatus">Stream: Running</span>
          <span id="lastUpdated">Last updated: --</span>
        </div>
        <div class="chart-wrap">
          <canvas id="liveChart"></canvas>
        </div>
        <div class="controls">
          <button id="toggleStreamBtn" type="button">Pause Stream</button>
          <button id="resetDataBtn" type="button" class="secondary-btn">Reset Data</button>
        </div>
      </div>

      <div class="card form-card">
        <h2>Submit Event</h2>
        <form id="eventForm">
          <div>
            <label for="eventName">Event Name</label>
            <input id="eventName" name="eventName" type="text" placeholder="e.g. Sensor Alert" required />
          </div>

          <div>
            <label for="eventType">Event Type</label>
            <select id="eventType" name="eventType" required>
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="critical">Critical</option>
            </select>
          </div>

          <div>
            <label for="eventValue">Value</label>
            <input id="eventValue" name="eventValue" type="number" placeholder="Enter numeric value" required />
          </div>

          <div>
            <label for="eventNote">Note</label>
            <textarea id="eventNote" name="eventNote" placeholder="Optional notes..."></textarea>
          </div>

          <button type="submit">Add Event</button>
        </form>
      </div>

      <div class="card log-card">
        <h2>Activity Log</h2>
        <ul id="logList" class="log-list"></ul>
      </div>
    </div>
  </div>

  <script>
    const maxPoints = 20;
    let streamRunning = true;
    let submittedEvents = 0;
    let dataPoints = [];
    let labels = [];

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const streamStatusEl = document.getElementById('streamStatus');
    const lastUpdatedEl = document.getElementById('lastUpdated');
    const logListEl = document.getElementById('logList');
    const toggleStreamBtn = document.getElementById('toggleStreamBtn');
    const resetDataBtn = document.getElementById('resetDataBtn');
    const eventForm = document.getElementById('eventForm');

    const ctx = document.getElementById('liveChart').getContext('2d');

    const liveChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Metric Value',
          data: dataPoints,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: '#93c5fd'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        }
      }
    });

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function addLog(message, type = 'info') {
      const li = document.createElement('li');
      li.className = 'log-item';

      let badgeClass = 'badge-ok';
      let badgeText = 'INFO';

      if (type === 'warning') {
        badgeClass = 'badge-warn';
        badgeText = 'WARN';
      } else if (type === 'critical') {
        badgeClass = 'badge-danger';
        badgeText = 'CRITICAL';
      }

      li.innerHTML = `
        <span class="log-time">[${formatTime()}]</span>
        <span>${message}</span>
        <span class="badge ${badgeClass}">${badgeText}</span>
      `;

      logListEl.prepend(li);

      while (logListEl.children.length > 30) {
        logListEl.removeChild(logListEl.lastChild);
      }
    }

    function updateStats() {
      const current = dataPoints.length ? dataPoints[dataPoints.length - 1] : 0;
      const avg = dataPoints.length
        ? (dataPoints.reduce((sum, v) => sum + v, 0) / dataPoints.length).toFixed(1)
        : 0;
      const peak = dataPoints.length ? Math.max(...dataPoints) : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      peakValueEl.textContent = peak;
      eventCountEl.textContent = submittedEvents;
    }

    function pushDataPoint(value) {
      const now = formatTime();
      labels.push(now);
      dataPoints.push(value);

      if (labels.length > maxPoints) labels.shift();
      if (dataPoints.length > maxPoints) dataPoints.shift();

      liveChart.update();
      updateStats();
      lastUpdatedEl.textContent = `Last updated: ${now}`;
    }

    function generateRandomValue() {
      return Math.floor(Math.random() * 100) + 1;
    }

    function tick() {
      if (!streamRunning) return;
      const value = generateRandomValue();
      pushDataPoint(value);

      if (value > 85) {
        addLog(`High metric detected: ${value}`, 'warning');
      }
    }

    toggleStreamBtn.addEventListener('click', () => {
      streamRunning = !streamRunning;
      streamStatusEl.textContent = `Stream: ${streamRunning ? 'Running' : 'Paused'}`;
      toggleStreamBtn.textContent = streamRunning ? 'Pause Stream' : 'Resume Stream';
      addLog(`Data stream ${streamRunning ? 'resumed' : 'paused'}`, 'info');
    });

    resetDataBtn.addEventListener('click', () => {
      labels.length = 0;
      dataPoints.length = 0;
      liveChart.update();
      updateStats();
      lastUpdatedEl.textContent = 'Last updated: --';
      addLog('Dashboard data reset', 'warning');
    });

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(eventForm);
      const eventName = formData.get('eventName').trim();
      const eventType = formData.get('eventType');
      const eventValue = Number(formData.get('eventValue'));
      const eventNote = formData.get('eventNote').trim();

      if (!eventName || Number.isNaN(eventValue)) {
        addLog('Invalid form submission', 'critical');
        return;
      }

      submittedEvents++;
      eventCountEl.textContent = submittedEvents;

      pushDataPoint(eventValue);

      let message = `Event "${eventName}" submitted with value ${eventValue}`;
      if (eventNote) {
        message += ` — Note: ${eventNote}`;
      }

      addLog(message, eventType === 'critical' ? 'critical' : eventType === 'warning' ? 'warning' : 'info');

      eventForm.reset();
    });

    // Seed initial data
    for (let i = 0; i < 8; i++) {
      pushDataPoint(generateRandomValue());
    }

    addLog('Dashboard initialized', 'info');

    // Real-time update interval
    setInterval(tick, 1500);
  </script>
</body>
</html>
```

## Features included

- `Chart.js` line chart for live visualization
- Automatic simulated real-time updates every 1.5 seconds
- Pause/resume stream control
- Reset chart data
- Form submission that injects new values into the chart
- Event log with severity badges
- Summary metrics:
  - Current value
  - Average
  - Peak
  - Submitted event count

