      data.push({
        time,
        label: time.toLocaleTimeString(),
        value
      });

      if (data.length > MAX_POINTS) {
        data.shift();
      }

      updateKPIs();
      drawChart();
    }

    function updateKPIs() {
      if (!data.length) {
        currentValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        currentDeltaEl.textContent = 'Waiting for data...';
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const prev = values.length > 1 ? values[values.length - 2] : current;
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);
      const delta = current - prev;

      currentValueEl.textContent = current.toString();
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toString();

      const sign = delta > 0 ? '+' : '';
      currentDeltaEl.textContent = `Change from last point: ${sign}${delta}`;
      currentDeltaEl.style.color = delta >= 0 ? '#86efac' : '#fca5a5';
    }

    function drawChart() {
      const { width, height } = canvas;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      const padding = { top: 20, right: 20, bottom: 30, left: 45 };
      const chartW = width - padding.left - padding.right;
      const chartH = height - padding.top - padding.bottom;

      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding.top + (chartH / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding.left, y);
        ctx.lineTo(width - padding.right, y);
        ctx.stroke();
      }

      if (!data.length) return;

      const values = data.map(d => d.value);
      const min = 0;
      const max = 100;

      const xStep = data.length > 1 ? chartW / (data.length - 1) : chartW;

      // Area fill
      ctx.beginPath();
      data.forEach((point, i) => {
        const x = padding.left + i * xStep;
        const y = padding.top + chartH - ((point.value - min) / (max - min)) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(padding.left + (data.length - 1) * xStep, padding.top + chartH);
      ctx.lineTo(padding.left, padding.top + chartH);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.03)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((point, i) => {
        const x = padding.left + i * xStep;
        const y = padding.top + chartH - ((point.value - min) / (max - min)) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#60a5fa';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((point, i) => {
        const x = padding.left + i * xStep;
        const y = padding.top + chartH - ((point.value - min) / (max - min)) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#93c5fd';
        ctx.fill();
      });

      // Y-axis labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      for (let i = 0; i <= 5; i++) {
        const value = max - (max / 5) * i;
        const y = padding.top + (chartH / 5) * i + 4;
        ctx.fillText(value.toString(), padding.left - 8, y);
      }

      // X-axis labels
      ctx.textAlign = 'center';
      const labelCount = Math.min(6, data.length);
      for (let i = 0; i < labelCount; i++) {
        const idx = Math.floor((data.length - 1) * (i / Math.max(1, labelCount - 1)));
        const x = padding.left + idx * xStep;
        const y = height - 10;
        ctx.fillText(data[idx].label, x, y);
      }
    }

    function startStream() {
      if (timer) return;
      addDataPoint();
      timer = setInterval(addDataPoint, 1000);
      streamStatusEl.innerHTML = '<span class="status-dot"></span><span>Streaming live</span>';
      streamStatusEl.style.background = 'rgba(34, 197, 94, 0.12)';
      streamStatusEl.style.color = '#bbf7d0';
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
      streamStatusEl.innerHTML = '<span class="status-dot" style="background:#f59e0b; box-shadow:0 0 12px #f59e0b;"></span><span>Stream paused</span>';
      streamStatusEl.style.background = 'rgba(245, 158, 11, 0.12)';
      streamStatusEl.style.color = '#fde68a';
    }

    function resetDashboard() {
      stopStream();
      data = [];
      updateKPIs();
      drawChart();
    }

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetDashboard);

    function clearErrors() {
      document.querySelectorAll('.error').forEach(el => el.textContent = '');
      formSuccess.textContent = '';
    }

    function setError(field, message) {
      const errorEl = document.querySelector(`[data-error-for="${field}"]`);
      if (errorEl) errorEl.textContent = message;
    }

    function validateForm(values) {
      let valid = true;

      if (!values.name.trim()) {
        setError('name', 'Name is required.');
        valid = false;
      } else if (values.name.trim().length < 3) {
        setError('name', 'Name must be at least 3 characters.');
        valid = false;
      }

      if (!values.category) {
        setError('category', 'Please select a category.');
        valid = false;
      }

      if (!values.severity) {
        setError('severity', 'Please select a severity.');
        valid = false;
      }

      if (values.notes.length > 200) {
        setError('notes', 'Notes must be 200 characters or fewer.');
        valid = false;
      }

      return valid;
    }

    function severityBadge(severity) {
      const cls =
        severity === 'High' ? 'badge-high' :
        severity === 'Medium' ? 'badge-medium' :
        'badge-low';

      return `<span class="badge ${cls}">${severity}</span>`;
    }

    function renderTable() {
      submissionCountEl.textContent = submissions.length.toString();

      if (!submissions.length) {
        tableBody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted); text-align:center;">No records submitted yet.</td>
          </tr>
        `;
        return;
      }

      tableBody.innerHTML = submissions
        .slice()
        .reverse()
        .map(item => `
          <tr>
            <td>${item.time}</td>
            <td>${escapeHtml(item.name)}</td>
            <td>${escapeHtml(item.category)}</td>
            <td>${severityBadge(item.severity)}</td>
            <td>${escapeHtml(item.notes || '-')}</td>
          </tr>
        `)
        .join('');
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#39;');
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const values = {
        name: form.name.value,
        category: form.category.value,
        severity: form.severity.value,
        notes: form.notes.value.trim()
      };

      if (!validateForm(values)) return;

      submissions.push({
        ...values,
        time: new Date().toLocaleString()
      });

      renderTable();
      form.reset();
      formSuccess.textContent = 'Record submitted successfully.';
    });

    // Initialize
    updateKPIs();
    drawChart();
    renderTable();
    startStream();

    // Redraw chart if window resizes and CSS scaling changes layout feel
    window.addEventListener('resize', drawChart);
  </script>
</body>
</html>
```

## How it works

### Real-time visualization
- A simulated data stream adds one data point every second.
- The chart is drawn on an HTML5 `<canvas>`.
- KPI cards update automatically:
  - current value
  - average
  - peak
  - submission count

### Form handling
- The form validates:
  - required name
  - required category
  - required severity
  - notes length
- On successful submit:
  - the record is stored in memory
  - the table updates immediately
  - a success message is shown

### Controls
- Start: resumes live updates
- Stop: pauses the stream
- Reset: clears chart data and pauses the stream

