            <button type="submit" class="primary">Submit Event</button>
            <div class="success-message" id="formSuccess"></div>
          </form>
        </div>

        <div class="card">
          <h2>Current Health</h2>
          <div id="healthBadge" class="status ok">Normal</div>
          <p class="footer-note" id="healthDescription">
            System operating within expected range.
          </p>
        </div>
