  </div>

  <script>
    const chartCanvas = document.getElementById('chartCanvas');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const statusTextEl = document.getElementById('statusText');
    const healthBadgeEl = document.getElementById('healthBadge');
    const healthDescriptionEl = document.getElementById('healthDescription');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const form = document.getElementById('eventForm');
    const recordsTableBody = document.getElementById('recordsTableBody');
    const formSuccess = document.getElementById('formSuccess');

    const MAX_POINTS = 40;
    let dataPoints = [];
    let intervalId = null;

    function generateDataPoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1].value : 50;
      const next = Math.max(0, Math.min(100, last + (Math.random() * 20 - 10)));
      return {
        time: new Date(),
        value: Number(next.toFixed(1))
      };
    }

    function addDataPoint() {
      const point = generateDataPoint();
      dataPoints.push(point);
      if (dataPoints.length > MAX_POINTS) dataPoints.shift();
      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (!dataPoints.length) {
        currentValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        statusTextEl.textContent = 'Idle';
        setHealthState('ok', 'Normal', 'System operating within expected range.');
        return;
      }

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);

      if (current < 60) {
        statusTextEl.textContent = 'Stable';
        setHealthState('ok', 'Normal', 'System operating within expected range.');
      } else if (current < 80) {
        statusTextEl.textContent = 'Warning';
        setHealthState('warn', 'Elevated', 'Values are above baseline. Monitoring recommended.');
      } else {
        statusTextEl.textContent = 'Critical';
        setHealthState('alert', 'Critical', 'Threshold exceeded. Immediate attention may be required.');
      }
    }

    function setHealthState(type, label, description) {
      healthBadgeEl.className = `status ${type}`;
      healthBadgeEl.textContent = label;
      healthDescriptionEl.textContent = description;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      drawGrid(width, height);

      if (dataPoints.length < 2) return;

      const padding = 30;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      ctx.beginPath();
      ctx.lineWidth = 3;
      ctx.strokeStyle = '#3b82f6';

      dataPoints.forEach((point, index) => {
        const x = padding + (index / (MAX_POINTS - 1)) * chartWidth;
        const y = padding + ((100 - point.value) / 100) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.lineTo(padding + chartWidth, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = 'rgba(59,130,246,0.15)';
      ctx.fill();

      dataPoints.forEach((point, index) => {
        const x = padding + (index / (MAX_POINTS - 1)) * chartWidth;
        const y = padding + ((100 - point.value) / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });

      drawYAxisLabels(padding, chartHeight);
    }

    function drawGrid(width, height) {
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 8;
      const padding = 30;

      for (let i = 0; i <= rows; i++) {
        const y = padding + ((height - padding * 2) / rows) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = padding + ((width - padding * 2) / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }
    }

    function drawYAxisLabels(padding, chartHeight) {
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';

      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 20;
        const y = padding + (chartHeight / 5) * i + 4;
        ctx.fillText(String(value), 6, y);
      }
    }

    function startStream() {
      if (intervalId) return;
      addDataPoint();
      intervalId = setInterval(addDataPoint, 1000);
    }

    function stopStream() {
      clearInterval(intervalId);
      intervalId = null;
    }

    function resetData() {
      stopStream();
      dataPoints = [];
      updateMetrics();
      drawChart();
    }

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetData);

    function clearErrors() {
      ['name', 'category', 'priority', 'notes'].forEach(field => {
        document.getElementById(field + 'Error').textContent = '';
      });
      formSuccess.textContent = '';
    }

    function validateForm(data) {
      let isValid = true;
      clearErrors();

      if (!data.name.trim()) {
        document.getElementById('nameError').textContent = 'Name is required.';
        isValid = false;
      } else if (data.name.trim().length < 3) {
        document.getElementById('nameError').textContent = 'Name must be at least 3 characters.';
        isValid = false;
      }

      if (!data.category) {
        document.getElementById('categoryError').textContent = 'Please select a category.';
        isValid = false;
      }

      if (!data.priority) {
        document.getElementById('priorityError').textContent = 'Please select a priority.';
        isValid = false;
      }

      if (data.notes.trim().length > 0 && data.notes.trim().length < 5) {
        document.getElementById('notesError').textContent = 'Notes must be at least 5 characters if provided.';
        isValid = false;
      }

      return isValid;
    }

    function addRecordToTable(data) {
      const emptyRow = recordsTableBody.querySelector('td[colspan="5"]');
      if (emptyRow) {
        recordsTableBody.innerHTML = '';
      }

      const tr = document.createElement('tr');
      const time = new Date().toLocaleTimeString();

      tr.innerHTML = `
        <td>${time}</td>
        <td>${escapeHtml(data.name)}</td>
        <td>${escapeHtml(data.category)}</td>
        <td>${escapeHtml(data.priority)}</td>
        <td>${escapeHtml(data.notes || '-')}</td>
      `;

      recordsTableBody.prepend(tr);
    }

    function escapeHtml(str) {
      return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    form.addEventListener('submit', function (e) {
      e.preventDefault();

      const formData = {
        name: document.getElementById('name').value,
        category: document.getElementById('category').value,
        priority: document.getElementById('priority').value,
        notes: document.getElementById('notes').value
      };

      if (!validateForm(formData)) return;

      addRecordToTable(formData);
      form.reset();
      formSuccess.textContent = 'Event submitted successfully.';
    });

    updateMetrics();
    drawChart();
  </script>
</body>
</html>
```

