  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const currentDeltaEl = document.getElementById("currentDelta");
    const avgValueEl = document.getElementById("avgValue");
    const peakValueEl = document.getElementById("peakValue");
    const entryCountEl = document.getElementById("entryCount");
    const recordsTableBody = document.getElementById("recordsTableBody");

    const form = document.getElementById("dataForm");
    const formSuccess = document.getElementById("formSuccess");

    const fields = {
      name: document.getElementById("name"),
      category: document.getElementById("category"),
      value: document.getElementById("value"),
      priority: document.getElementById("priority"),
      owner: document.getElementById("owner"),
      notes: document.getElementById("notes")
    };

    const errors = {
      name: document.getElementById("nameError"),
      category: document.getElementById("categoryError"),
      value: document.getElementById("valueError"),
      priority: document.getElementById("priorityError"),
      owner: document.getElementById("ownerError"),
      notes: document.getElementById("notesError")
    };

    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");

    let dataPoints = [];
    let labels = [];
    let records = [];
    let timer = null;
    const maxPoints = 40;

    function resizeCanvas() {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    }

    function generateValue() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1] : 50;
      const noise = (Math.random() - 0.5) * 14;
      const trend = Math.sin(Date.now() / 4000) * 3;
      let next = last + noise + trend;
      next = Math.max(10, Math.min(100, next));
      return Number(next.toFixed(1));
    }

    function addDataPoint() {
      const value = generateValue();
      const now = new Date();
      const label = now.toLocaleTimeString();

      dataPoints.push(value);
      labels.push(label);

      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
        labels.shift();
      }

      updateStats();
      drawChart();
    }

    function updateStats() {
      if (!dataPoints.length) {
        currentValueEl.textContent = "0";
        avgValueEl.textContent = "0";
        peakValueEl.textContent = "0";
        currentDeltaEl.textContent = "Waiting for data...";
        return;
      }

      const current = dataPoints[dataPoints.length - 1];
      const prev = dataPoints[dataPoints.length - 2] ?? current;
      const avg = dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length;
      const peak = Math.max(...dataPoints);
      const delta = (current - prev).toFixed(1);

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      currentDeltaEl.textContent =
        delta >= 0 ? `▲ +${delta} from previous` : `▼ ${delta} from previous`;
    }

    function drawChart() {
      const width = canvas.getBoundingClientRect().width;
      const height = canvas.getBoundingClientRect().height;
      ctx.clearRect(0, 0, width, height);

      const padding = { top: 20, right: 20, bottom: 30, left: 40 };
      const chartW = width - padding.left - padding.right;
      const chartH = height - padding.top - padding.bottom;

      // Grid
      ctx.strokeStyle = "rgba(148,163,184,0.15)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let i = 0; i <= 5; i++) {
        const y = padding.top + (chartH / 5) * i;
        ctx.moveTo(padding.left, y);
        ctx.lineTo(padding.left + chartW, y);
      }
      ctx.stroke();

      // Axes labels
      ctx.fillStyle = "rgba(148,163,184,0.8)";
      ctx.font = "12px sans-serif";
      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 18;
        const y = padding.top + (chartH / 5) * i;
        ctx.fillText(String(Math.round(value)), 8, y + 4);
      }

      if (dataPoints.length < 2) return;

      const minY = 0;
      const maxY = 100;
      const xStep = chartW / (maxPoints - 1);

      const getX = (index) => padding.left + index * xStep;
      const getY = (value) =>
        padding.top + chartH - ((value - minY) / (maxY - minY)) * chartH;

      // Average line
      const avg = dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length;
      const avgY = getY(avg);
      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 1.5;
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(padding.left, avgY);
      ctx.lineTo(padding.left + chartW, avgY);
      ctx.stroke();
      ctx.setLineDash([]);

      // Gradient line
      const gradient = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
      gradient.addColorStop(0, "rgba(59,130,246,1)");
      gradient.addColorStop(1, "rgba(59,130,246,0.2)");

      // Area fill
      ctx.beginPath();
      ctx.moveTo(getX(0), getY(dataPoints[0]));
      dataPoints.forEach((point, i) => {
        ctx.lineTo(getX(i), getY(point));
      });
      ctx.lineTo(getX(dataPoints.length - 1), padding.top + chartH);
      ctx.lineTo(getX(0), padding.top + chartH);
      ctx.closePath();

      const fillGradient = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
      fillGradient.addColorStop(0, "rgba(59,130,246,0.25)");
      fillGradient.addColorStop(1, "rgba(59,130,246,0.02)");
      ctx.fillStyle = fillGradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((point, i) => {
        const x = getX(i);
        const y = getY(point);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = gradient;
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((point, i) => {
        const x = getX(i);
        const y = getY(point);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#93c5fd";
        ctx.fill();
      });

      // Last label
      const lastIndex = dataPoints.length - 1;
      const lx = getX(lastIndex);
      const ly = getY(dataPoints[lastIndex]);

      ctx.fillStyle = "#e5e7eb";
      ctx.font = "12px sans-serif";
      ctx.fillText(dataPoints[lastIndex].toFixed(1), lx - 10, ly - 10);
    }

    function startStream() {
      if (timer) return;
      addDataPoint();
      timer = setInterval(addDataPoint, 1000);
    }

    function stopStream() {
      clearInterval(timer);
      timer = null;
    }

    function resetData() {
      stopStream();
      dataPoints = [];
      labels = [];
      updateStats();
      drawChart();
    }

    function clearErrors() {
      Object.values(errors).forEach(el => el.textContent = "");
      formSuccess.textContent = "";
    }

    function validateForm() {
      clearErrors();
      let valid = true;

      if (!fields.name.value.trim()) {
        errors.name.textContent = "Name is required.";
        valid = false;
      } else if (fields.name.value.trim().length < 2) {
        errors.name.textContent = "Name must be at least 2 characters.";
        valid = false;
      }

      if (!fields.category.value) {
        errors.category.textContent = "Please select a category.";
        valid = false;
      }

      const numericValue = Number(fields.value.value);
      if (fields.value.value === "") {
        errors.value.textContent = "Value is required.";
        valid = false;
      } else if (Number.isNaN(numericValue) || numericValue < 0 || numericValue > 1000) {
        errors.value.textContent = "Value must be between 0 and 1000.";
        valid = false;
      }

      if (!fields.priority.value) {
        errors.priority.textContent = "Please select a priority.";
        valid = false;
      }

      if (!fields.owner.value.trim()) {
        errors.owner.textContent = "Owner is required.";
        valid = false;
      }

      if (fields.notes.value.length > 300) {
        errors.notes.textContent = "Notes must be 300 characters or fewer.";
        valid = false;
      }

      return valid;
    }

    function renderRecords() {
      entryCountEl.textContent = records.length;

      if (!records.length) {
        recordsTableBody.innerHTML = `
          <tr>
            <td colspan="5" style="color: var(--muted);">No records submitted yet.</td>
          </tr>
        `;
        return;
      }

      recordsTableBody.innerHTML = records
        .slice()
        .reverse()
        .map(record => `
          <tr>
            <td>${record.time}</td>
            <td>${escapeHtml(record.name)}</td>
            <td>${escapeHtml(record.category)}</td>
            <td>${record.value}</td>
            <td><span class="badge ${record.priority}">${record.priority}</span></td>
          </tr>
        `)
        .join("");
    }

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      const record = {
        name: fields.name.value.trim(),
        category: fields.category.value,
        value: Number(fields.value.value),
        priority: fields.priority.value,
        owner: fields.owner.value.trim(),
        notes: fields.notes.value.trim(),
        time: new Date().toLocaleTimeString()
      };

      records.push(record);
      renderRecords();
      form.reset();
      clearErrors();
      formSuccess.textContent = "Record submitted successfully.";

      // Optional: push submitted value into live chart if within range
      const chartValue = Math.max(10, Math.min(100, record.value / 10));
      dataPoints.push(Number(chartValue.toFixed(1)));
      labels.push(record.time);
      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
        labels.shift();
      }
      updateStats();
      drawChart();
    });

    startBtn.addEventListener("click", startStream);
    stopBtn.addEventListener("click", stopStream);
    resetBtn.addEventListener("click", resetData);
    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    renderRecords();
    startStream();
  </script>
</body>
</html>
