  <script>
    const maxPoints = 20;
    let dataPoints = [];
    let labels = [];
    let timer = null;
    let eventCounter = 0;
    let activeThreshold = 75;

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const logEl = document.getElementById('log');
    const statusDot = document.getElementById('statusDot');
    const statusText = document.getElementById('statusText');

    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Sensor Value',
          data: dataPoints,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 2,
          pointHoverRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          },
          y: {
            min: 0,
            max: 100,
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          }
        }
      }
    });

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function addLog(message, type = 'info') {
      eventCounter++;
      eventCountEl.textContent = eventCounter;

      const item = document.createElement('div');
      item.className = 'log-item';

      let borderColor = 'var(--border)';
      if (type === 'alert') borderColor = 'rgba(239, 68, 68, 0.45)';
      if (type === 'success') borderColor = 'rgba(34, 197, 94, 0.45)';
      if (type === 'action') borderColor = 'rgba(59, 130, 246, 0.45)';
      item.style.borderColor = borderColor;

      item.innerHTML = `
        <div class="log-time">${formatTime()}</div>
        <div>${message}</div>
      `;

      logEl.prepend(item);
    }

    function generateDataPoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1] : 50;
      const next = Math.max(5, Math.min(100, last + (Math.random() * 20 - 10)));
      return Number(next.toFixed(1));
    }

    function updateMetrics() {
      if (!dataPoints.length) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const current = dataPoints[dataPoints.length - 1];
      const avg = dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length;
      const peak = Math.max(...dataPoints);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
    }

    function pushData() {
      const value = generateDataPoint();
      const time = formatTime();

      dataPoints.push(value);
      labels.push(time);

      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
        labels.shift();
      }

      realtimeChart.update();
      updateMetrics();

      if (value > activeThreshold) {
        addLog(`Alert: live value ${value.toFixed(1)} exceeded threshold ${activeThreshold}.`, 'alert');
      }
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(pushData, 1000);
      statusDot.classList.add('live');
      statusText.textContent = 'Live stream active';
      addLog('Data stream started.', 'success');
    }

    function stopStream() {
      if (!timer) return;
      clearInterval(timer);
      timer = null;
      statusDot.classList.remove('live');
      statusText.textContent = 'Live stream paused';
      addLog('Data stream stopped.', 'info');
    }

    function resetDashboard() {
      stopStream();
      dataPoints.length = 0;
      labels.length = 0;
      realtimeChart.update();
      updateMetrics();
      addLog('Dashboard reset.', 'action');
    }

    document.getElementById('startBtn').addEventListener('click', startStream);
    document.getElementById('stopBtn').addEventListener('click', stopStream);
    document.getElementById('resetBtn').addEventListener('click', resetDashboard);

    const form = document.getElementById('actionForm');
    const successMessage = document.getElementById('successMessage');

    function clearErrors() {
      ['name', 'category', 'threshold', 'priority', 'notes'].forEach(field => {
        document.getElementById(field + 'Error').textContent = '';
      });
      successMessage.style.display = 'none';
    }

    function validateForm(formData) {
      let valid = true;

      if (!formData.name.trim()) {
        document.getElementById('nameError').textContent = 'Name is required.';
        valid = false;
      }

      if (!formData.category) {
        document.getElementById('categoryError').textContent = 'Please select a category.';
        valid = false;
      }

      const thresholdNum = Number(formData.threshold);
      if (formData.threshold === '' || Number.isNaN(thresholdNum) || thresholdNum < 0 || thresholdNum > 200) {
        document.getElementById('thresholdError').textContent = 'Threshold must be between 0 and 200.';
        valid = false;
      }

      if (!formData.priority) {
        document.getElementById('priorityError').textContent = 'Please select a priority.';
        valid = false;
      }

      if (!formData.notes.trim() || formData.notes.trim().length < 5) {
        document.getElementById('notesError').textContent = 'Notes must be at least 5 characters.';
        valid = false;
      }

      return valid;
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      clearErrors();

      const formData = {
        name: document.getElementById('name').value,
        category: document.getElementById('category').value,
        threshold: document.getElementById('threshold').value,
        priority: document.getElementById('priority').value,
        notes: document.getElementById('notes').value
      };

      if (!validateForm(formData)) return;

      activeThreshold = Number(formData.threshold);

      addLog(
        `Event submitted by ${formData.name}: ${formData.category} | Priority: ${formData.priority} | Threshold set to ${activeThreshold}. Notes: ${formData.notes}`,
        'action'
      );

      successMessage.style.display = 'block';
      form.reset();
      document.getElementById('threshold').value = activeThreshold;
    });

    // Seed initial data
    for (let i = 0; i < 8; i++) {
      dataPoints.push(generateDataPoint());
      labels.push(formatTime(new Date(Date.now() - (8000 - i * 1000))));
    }
    realtimeChart.update();
    updateMetrics();
    addLog('Dashboard initialized.', 'success');
    startStream();
  </script>
</body>
</html>
