      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Live Data Chart</h2>
        <div class="chart-wrap">
          <canvas id="chartCanvas" width="800" height="340"></canvas>
        </div>

        <div class="table-wrap">
          <h2>Logged Events</h2>
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Name</th>
                <th>Category</th>
                <th>Severity</th>
                <th>Notes</th>
              </tr>
            </thead>
            <tbody id="eventTableBody"></tbody>
          </table>
        </div>
      </div>

      <div class="panel">
        <h2>Log New Event</h2>
        <form id="eventForm" novalidate>
          <div class="field">
            <label for="name">Event Name</label>
            <input id="name" name="name" type="text" placeholder="e.g. Sensor Alert" />
            <div class="error" id="nameError"></div>
          </div>

          <div class="field">
            <label for="category">Category</label>
            <select id="category" name="category">
              <option value="">Select category</option>
              <option value="System">System</option>
              <option value="Network">Network</option>
              <option value="Sensor">Sensor</option>
              <option value="User">User</option>
            </select>
            <div class="error" id="categoryError"></div>
          </div>

          <div class="field">
            <label for="severity">Severity</label>
            <select id="severity" name="severity">
              <option value="">Select severity</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
            <div class="error" id="severityError"></div>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional details..."></textarea>
            <div class="error" id="notesError"></div>
