  <script>
    const chartCanvas = document.getElementById('chartCanvas');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');

    const eventForm = document.getElementById('eventForm');
    const eventTableBody = document.getElementById('eventTableBody');
    const formSuccess = document.getElementById('formSuccess');

    const dataPoints = [];
    const maxPoints = 50;
    let intervalId = null;
    let events = [];

    function randomValue() {
      const base = 50;
      const variance = Math.random() * 40 - 20;
      const wave = Math.sin(Date.now() / 1000) * 10;
      return Math.max(0, Math.round(base + variance + wave));
    }

    function addDataPoint() {
      const value = randomValue();
      const time = new Date().toLocaleTimeString();

      dataPoints.push({ value, time });
      if (dataPoints.length > maxPoints) dataPoints.shift();

      updateMetrics();
      drawChart();
    }

    function updateMetrics() {
      if (dataPoints.length === 0) {
        currentValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const avg = (values.reduce((a, b) => a + b, 0) / values.length).toFixed(1);
      const peak = Math.max(...values);

      currentValueEl.textContent = current;
      avgValueEl.textContent = avg;
      peakValueEl.textContent = peak;
      eventCountEl.textContent = events.length;
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      if (dataPoints.length < 2) return;

      const values = dataPoints.map(p => p.value);
      const max = Math.max(...values, 100);
      const min = Math.min(...values, 0);
      const range = max - min || 1;

      const padding = 30;
      const chartW = width - padding * 2;
      const chartH = height - padding * 2;

      // Area fill
      ctx.beginPath();
      dataPoints.forEach((point, i) => {
        const x = padding + (i / (maxPoints - 1)) * chartW;
        const y = padding + chartH - ((point.value - min) / range) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = padding + ((dataPoints.length - 1) / (maxPoints - 1)) * chartW;
      ctx.lineTo(lastX, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(59,130,246,0.35)');
      gradient.addColorStop(1, 'rgba(59,130,246,0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((point, i) => {
        const x = padding + (i / (maxPoints - 1)) * chartW;
        const y = padding + chartH - ((point.value - min) / range) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#60a5fa';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((point, i) => {
        const x = padding + (i / (maxPoints - 1)) * chartW;
        const y = padding + chartH - ((point.value - min) / range) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#22c55e';
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = 'rgba(229, 231, 235, 0.85)';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Max: ${max}`, 10, 16);
      ctx.fillText(`Min: ${min}`, 10, height - 10);
    }

    function startStream() {
      if (intervalId) return;
      addDataPoint();
      intervalId = setInterval(addDataPoint, 1000);
    }

    function stopStream() {
      clearInterval(intervalId);
      intervalId = null;
    }

    function resetDashboard() {
      stopStream();
      dataPoints.length = 0;
      events = [];
      eventTableBody.innerHTML = '';
      formSuccess.textContent = '';
      updateMetrics();
      drawChart();
    }

    function validateForm(data) {
      let valid = true;

      const errors = {
        name: '',
        category: '',
        severity: '',
        notes: ''
      };

      if (!data.name.trim()) {
        errors.name = 'Event name is required.';
        valid = false;
      } else if (data.name.trim().length < 3) {
        errors.name = 'Event name must be at least 3 characters.';
        valid = false;
      }

      if (!data.category) {
        errors.category = 'Please select a category.';
        valid = false;
      }

      if (!data.severity) {
        errors.severity = 'Please select a severity.';
        valid = false;
      }

      if (data.notes.length > 200) {
        errors.notes = 'Notes must be 200 characters or fewer.';
        valid = false;
      }

      document.getElementById('nameError').textContent = errors.name;
      document.getElementById('categoryError').textContent = errors.category;
      document.getElementById('severityError').textContent = errors.severity;
      document.getElementById('notesError').textContent = errors.notes;

      return valid;
    }

    function renderEvents() {
      eventTableBody.innerHTML = '';

      events.slice().reverse().forEach(event => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${event.time}</td>
          <td>${escapeHtml(event.name)}</td>
          <td>${escapeHtml(event.category)}</td>
          <td><span class="badge ${event.severity}">${event.severity}</span></td>
          <td>${escapeHtml(event.notes || '-')}</td>
        `;
        eventTableBody.appendChild(row);
      });

      eventCountEl.textContent = events.length;
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();
      formSuccess.textContent = '';

      const formData = {
        name: document.getElementById('name').value,
        category: document.getElementById('category').value,
        severity: document.getElementById('severity').value,
        notes: document.getElementById('notes').value.trim()
      };

      if (!validateForm(formData)) return;

      const newEvent = {
        ...formData,
        time: new Date().toLocaleTimeString()
      };

      events.push(newEvent);
      renderEvents();
      updateMetrics();

      eventForm.reset();
      document.getElementById('nameError').textContent = '';
      document.getElementById('categoryError').textContent = '';
      document.getElementById('severityError').textContent = '';
      document.getElementById('notesError').textContent = '';
      formSuccess.textContent = 'Event submitted successfully.';
    });

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetDashboard);

    drawChart();
    updateMetrics();
  </script>
</body>
</html>
```

## What this does
- Simulates real-time incoming data every second
- Draws a live-updating line/area chart on a `<canvas>`
- Shows summary stats:
  - current value
  - average
  - peak
  - events logged
- Lets users submit events through a form
- Validates required fields and note length
- Adds submitted events to a table

