      ].forEach(id => {
        document.getElementById(id).textContent = "";
      });
      els.formMessage.textContent = "";
    }

    function validateForm(values) {
      const errors = {};
      if (!values.streamName.trim()) {
        errors.streamName = "Stream name is required.";
      }
      if (isNaN(values.minValue)) {
        errors.minValue = "Minimum value must be a number.";
      }
      if (isNaN(values.maxValue)) {
        errors.maxValue = "Maximum value must be a number.";
      }
      if (!isNaN(values.minValue) && !isNaN(values.maxValue) && values.minValue >= values.maxValue) {
        errors.maxValue = "Maximum must be greater than minimum.";
      }
      if (isNaN(values.interval) || values.interval < 100) {
        errors.interval = "Interval must be at least 100 ms.";
      }
      return errors;
    }

    function showErrors(errors) {
      if (errors.streamName) document.getElementById("streamNameError").textContent = errors.streamName;
      if (errors.minValue) document.getElementById("minValueError").textContent = errors.minValue;
      if (errors.maxValue) document.getElementById("maxValueError").textContent = errors.maxValue;
      if (errors.interval) document.getElementById("intervalError").textContent = errors.interval;
    }

    function logEvent(type, message) {
      const item = document.createElement("div");
      item.className = "log-item";
      const time = new Date().toLocaleTimeString();
      item.innerHTML = `<span class="tag ${type}">${type.toUpperCase()}</span>${message} <span style="color:#94a3b8">(${time})</span>`;
      els.eventLog.prepend(item);

      while (els.eventLog.children.length > 50) {
        els.eventLog.removeChild(els.eventLog.lastChild);
      }
    }

    function generateValue() {
      const range = state.maxValue - state.minValue;
      const base = state.minValue + Math.random() * range;
      const noise = (Math.random() - 0.5) * (range * 0.15);
      return Math.max(state.minValue, Math.min(state.maxValue, base + noise));
    }

    function addDataPoint() {
      const value = Number(generateValue().toFixed(2));
      const point = {
        time: new Date(),
        value
      };
      state.data.push(point);
      if (state.data.length > state.maxPoints) {
        state.data.shift();
      }
      updateStats();
      drawChart();
    }

    function updateStats() {
      if (state.data.length === 0) {
        els.currentValue.textContent = "0";
        els.avgValue.textContent = "0";
        els.peakValue.textContent = "0";
        els.sampleCount.textContent = "0";
        return;
      }

      const values = state.data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      els.currentValue.textContent = current.toFixed(2);
      els.avgValue.textContent = avg.toFixed(2);
      els.peakValue.textContent = peak.toFixed(2);
      els.sampleCount.textContent = String(state.data.length);
    }

    function drawChart() {
      const canvas = els.chart;
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = "rgba(148,163,184,0.15)";
      ctx.lineWidth = 1;
      const gridRows = 5;
      const gridCols = 6;

      for (let i = 0; i <= gridRows; i++) {
        const y = (height / gridRows) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= gridCols; i++) {
        const x = (width / gridCols) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      if (state.data.length < 2) {
        ctx.fillStyle = "#94a3b8";
        ctx.font = "16px sans-serif";
        ctx.fillText("Waiting for data...", 20, 30);
        return;
      }

      const values = state.data.map(d => d.value);
      const min = Math.min(...values, state.minValue);
      const max = Math.max(...values, state.maxValue);
      const padding = 24;

      const xStep = (width - padding * 2) / (state.maxPoints - 1 || 1);

      function getX(index) {
        return padding + index * xStep;
      }

      function getY(value) {
        const normalized = (value - min) / (max - min || 1);
        return height - padding - normalized * (height - padding * 2);
      }

      // Area
      ctx.beginPath();
      state.data.forEach((point, i) => {
        const x = getX(i);
        const y = getY(point.value);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      const lastX = getX(state.data.length - 1);
      const firstX = getX(0);
      ctx.lineTo(lastX, height - padding);
      ctx.lineTo(firstX, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, hexToRgba(state.color, 0.35));
      gradient.addColorStop(1, hexToRgba(state.color, 0.02));
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      state.data.forEach((point, i) => {
        const x = getX(i);
        const y = getY(point.value);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = state.color;
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      state.data.forEach((point, i) => {
        const x = getX(i);
        const y = getY(point.value);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#e5e7eb";
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      ctx.fillText(`${state.streamName}`, 20, 20);
      ctx.fillText(`Min: ${min.toFixed(1)}`, 20, height - 8);
      ctx.fillText(`Max: ${max.toFixed(1)}`, width - 80, 20);
    }

    function hexToRgba(hex, alpha) {
      const clean = hex.replace("#", "");
      const bigint = parseInt(clean, 16);
      const r = (bigint >> 16) & 255;
      const g = (bigint >> 8) & 255;
      const b = bigint & 255;
      return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }

    function startStream() {
      stopStream();
      state.timerId = setInterval(() => {
        if (!state.paused) {
          addDataPoint();
        }
      }, state.interval);
    }

    function stopStream() {
      if (state.timerId) {
        clearInterval(state.timerId);
        state.timerId = null;
      }
    }

    function resetDashboard() {
      state.data = [];
      updateStats();
      drawChart();
      logEvent("warn", "Dashboard data reset.");
    }

    els.settingsForm.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const values = {
        streamName: els.streamName.value,
        minValue: Number(els.minValue.value),
        maxValue: Number(els.maxValue.value),
        interval: Number(els.interval.value),
        color: els.theme.value,
        notes: els.notes.value.trim()
      };

      const errors = validateForm(values);
      if (Object.keys(errors).length > 0) {
        showErrors(errors);
        logEvent("warn", "Form validation failed.");
        return;
      }

      state.streamName = values.streamName.trim();
      state.minValue = values.minValue;
      state.maxValue = values.maxValue;
      state.interval = values.interval;
      state.color = values.color;
      state.notes = values.notes;

      startStream();
      drawChart();

      els.formMessage.textContent = "Settings applied successfully.";
      logEvent("ok", `Updated stream "${state.streamName}" with interval ${state.interval}ms.`);
    });

    els.generateNowBtn.addEventListener("click", () => {
      addDataPoint();
      logEvent("info", "Manual data point generated.");
    });

    els.pauseBtn.addEventListener("click", () => {
      state.paused = true;
      logEvent("warn", "Stream paused.");
    });

    els.resumeBtn.addEventListener("click", () => {
      state.paused = false;
      logEvent("ok", "Stream resumed.");
    });

    els.resetBtn.addEventListener("click", () => {
      resetDashboard();
    });

    window.addEventListener("resize", () => {
      // Keep canvas crisp on resize
      const rect = els.chart.getBoundingClientRect();
      const ratio = window.devicePixelRatio || 1;
      els.chart.width = Math.floor(rect.width * ratio);
      els.chart.height = Math.floor(320 * ratio);
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      drawChart();
    });

    function setupCanvas() {
      const rect = els.chart.getBoundingClientRect();
      const ratio = window.devicePixelRatio || 1;
      els.chart.width = Math.floor(rect.width * ratio);
      els.chart.height = Math.floor(320 * ratio);
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    }

    function seedInitialData(points = 8) {
      for (let i = 0; i < points; i++) {
        addDataPoint();
      }
    }

    function init() {
      initForm();
      setupCanvas();
      seedInitialData();
      startStream();
      logEvent("info", "Dashboard initialized.");
    }

    init();
  </script>
</body>
</html>
```

## Features included

- Real-time simulated data stream using `setInterval`
- Live chart drawn with the HTML5 Canvas API
- KPI/stat cards:
  - current value
  - average
  - peak
  - sample count
- Form validation:
  - required stream name
  - numeric min/max
  - min must be less than max
  - interval minimum enforced
- Interactive controls:
  - pause
  - resume
  - reset
  - generate a data point immediately
- Event log with timestamps

