  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const eventLogEl = document.getElementById('eventLog');
    const toggleStreamBtn = document.getElementById('toggleStreamBtn');
    const addSpikeBtn = document.getElementById('addSpikeBtn');
    const resetBtn = document.getElementById('resetBtn');
    const streamStatusEl = document.getElementById('streamStatus');
    const streamDotEl = document.getElementById('streamDot');

    const form = document.getElementById('configForm');
    const metricNameInput = document.getElementById('metricName');
    const thresholdInput = document.getElementById('threshold');
    const intervalInput = document.getElementById('interval');
    const notesInput = document.getElementById('notes');
    const formSuccess = document.getElementById('formSuccess');

    const metricNameError = document.getElementById('metricNameError');
    const thresholdError = document.getElementById('thresholdError');

    let data = [];
    let maxPoints = 50;
    let timer = null;
    let isStreaming = true;
    let threshold = 80;
    let updateInterval = 1000;
    let metricName = 'System Load';
    let eventCount = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    function randomValue(prev = 50) {
      const drift = (Math.random() - 0.5) * 14;
      let next = prev + drift;
      next = Math.max(5, Math.min(100, next));
      return Number(next.toFixed(1));
    }

    function addDataPoint(value = null) {
      const last = data.length ? data[data.length - 1].value : 50;
      const nextValue = value !== null ? value : randomValue(last);
      data.push({
        time: new Date(),
        value: nextValue
      });

      if (data.length > maxPoints) data.shift();

      updateKPIs();
      drawChart();

      if (nextValue >= threshold) {
        addLog(`Threshold exceeded: ${nextValue} >= ${threshold}`, 'warn');
      }
    }

    function updateKPIs() {
      if (!data.length) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      eventCountEl.textContent = eventCount;
    }

    function drawGrid(width, height, padding) {
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;

      const rows = 5;
      const cols = 6;

      for (let i = 0; i <= rows; i++) {
        const y = padding + ((height - padding * 2) / rows) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = padding + ((width - padding * 2) / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, padding);
        ctx.lineTo(x, height - padding);
        ctx.stroke();
      }
    }

    function drawChart() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      const padding = 28;

      ctx.clearRect(0, 0, width, height);
      drawGrid(width, height, padding);

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = 0;
      const max = 100;

      const xStep = (width - padding * 2) / (maxPoints - 1);

      function getX(i) {
        return padding + i * xStep;
      }

      function getY(v) {
        const normalized = (v - min) / (max - min);
        return height - padding - normalized * (height - padding * 2);
      }

      // Area fill
      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, 'rgba(56, 189, 248, 0.35)');
      gradient.addColorStop(1, 'rgba(56, 189, 248, 0.02)');

      ctx.beginPath();
      ctx.moveTo(getX(0), getY(values[0]));
      values.forEach((v, i) => ctx.lineTo(getX(i), getY(v)));
      ctx.lineTo(getX(values.length - 1), height - padding);
      ctx.lineTo(getX(0), height - padding);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      values.forEach((v, i) => {
        const x = getX(i);
        const y = getY(v);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 2.5;
      ctx.stroke();

      // Threshold line
      const thresholdY = getY(threshold);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(width - padding, thresholdY);
      ctx.strokeStyle = 'rgba(245, 158, 11, 0.9)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([6, 6]);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = '#fbbf24';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Threshold: ${threshold}`, padding + 8, thresholdY - 8);

      // Last point marker
      const lastIndex = values.length - 1;
      const lx = getX(lastIndex);
      const ly = getY(values[lastIndex]);

      ctx.beginPath();
      ctx.arc(lx, ly, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = '#22c55e';
      ctx.fill();
      ctx.strokeStyle = '#d1fae5';
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    function addLog(message, type = 'info') {
      eventCount++;
      eventCountEl.textContent = eventCount;

      const item = document.createElement('div');
      item.className = 'log-item';

      const time = new Date().toLocaleTimeString();
      item.innerHTML = `
        <div class="time">${time} <span class="badge ${type}">${type.toUpperCase()}</span></div>
        <div>${message}</div>
      `;

      eventLogEl.prepend(item);

      while (eventLogEl.children.length > 20) {
        eventLogEl.removeChild(eventLogEl.lastChild);
      }
    }

    function startStream() {
      clearInterval(timer);
      timer = setInterval(() => {
        if (isStreaming) addDataPoint();
      }, updateInterval);
    }

    function setStreamingState(streaming) {
      isStreaming = streaming;
      streamStatusEl.textContent = streaming ? 'Streaming live' : 'Paused';
      streamDotEl.style.background = streaming ? 'var(--accent)' : 'var(--danger)';
      streamDotEl.style.boxShadow = streaming
        ? '0 0 12px var(--accent)'
        : '0 0 12px var(--danger)';
      toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
    }

    function validateForm() {
      let valid = true;
      metricNameError.textContent = '';
      thresholdError.textContent = '';
      formSuccess.textContent = '';

      if (!metricNameInput.value.trim()) {
        metricNameError.textContent = 'Metric name is required.';
        valid = false;
      }

      const thresholdValue = Number(thresholdInput.value);
      if (thresholdInput.value.trim() === '') {
        thresholdError.textContent = 'Threshold is required.';
        valid = false;
      } else if (Number.isNaN(thresholdValue) || thresholdValue < 0 || thresholdValue > 1000) {
        thresholdError.textContent = 'Threshold must be between 0 and 1000.';
        valid = false;
      }

      return valid;
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      metricName = metricNameInput.value.trim();
      threshold = Number(thresholdInput.value);
      updateInterval = Number(intervalInput.value);

      startStream();
      drawChart();

      const notes = notesInput.value.trim();
      formSuccess.textContent = 'Settings saved successfully.';
      addLog(
        `Updated config for "${metricName}" with threshold ${threshold} and interval ${updateInterval}ms${notes ? ` | Notes: ${notes}` : ''}`,
        'info'
      );
    });

    toggleStreamBtn.addEventListener('click', () => {
      setStreamingState(!isStreaming);
      addLog(isStreaming ? 'Stream resumed' : 'Stream paused', 'info');
    });

    addSpikeBtn.addEventListener('click', () => {
      const spike = Math.min(100, threshold + 10 + Math.random() * 15);
      addDataPoint(Number(spike.toFixed(1)));
      addLog(`Manual spike injected: ${spike.toFixed(1)}`, 'warn');
    });

    resetBtn.addEventListener('click', () => {
      data = [];
      updateKPIs();
      drawChart();
      addLog('Data reset', 'error');
    });

    window.addEventListener('resize', resizeCanvas);

    function init() {
      thresholdInput.value = threshold;
      metricNameInput.value = metricName;

      for (let i = 0; i < 20; i++) {
        addDataPoint(i === 0 ? 50 : null);
      }

      setStreamingState(true);
      startStream();
      resizeCanvas();
      addLog('Dashboard initialized', 'info');
    }

    init();
  </script>
</body>
</html>
```

## What this does

- Simulates incoming real-time data every second
- Draws the data on a live canvas chart
- Tracks:
  - current value
  - average
  - peak
  - event count
- Lets the user:
  - pause/resume the stream
  - inject a spike
  - reset the data
  - submit configuration via a form
- Validates form fields before applying changes
- Writes actions to an event log

