<body>
  <div class="container">
    <h1>Interactive Real-Time Dashboard</h1>

    <div class="stats">
      <div class="stat-card">
        <div class="stat-label">Current Value</div>
        <div class="stat-value" id="currentValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Peak</div>
        <div class="stat-value" id="peakValue">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Status</div>
        <div class="stat-value" id="streamStatus">Stopped</div>
      </div>
    </div>

    <div class="grid">
      <div class="panel">
        <h2>Live Data Visualisation</h2>
        <div class="charts">
          <div class="chart-wrap">
            <canvas id="lineChart"></canvas>
          </div>
          <div class="chart-wrap">
            <canvas id="barChart"></canvas>
          </div>
        </div>
        <div class="button-row">
          <button class="btn-success" id="startBtn">Start Stream</button>
          <button class="btn-warning" id="stopBtn">Stop Stream</button>
          <button class="btn-danger" id="resetBtn">Reset Data</button>
        </div>
        <div class="footer-note">Data updates every second using a simulated stream.</div>
      </div>

      <div class="panel">
        <h2>Configuration Form</h2>
        <form id="configForm">
          <div class="form-row">
            <label for="sensorName">Sensor Name</label>
            <input type="text" id="sensorName" name="sensorName" placeholder="e.g. Temperature Sensor A" required />
          </div>

          <div class="form-row">
            <label for="updateInterval">Update Interval (ms)</label>
            <input type="number" id="updateInterval" name="updateInterval" min="200" step="100" value="1000" required />
          </div>

          <div class="form-row">
            <label for="dataType">Data Type</label>
            <select id="dataType" name="dataType">
              <option value="temperature">Temperature</option>
              <option value="humidity">Humidity</option>
              <option value="pressure">Pressure</option>
              <option value="traffic">Traffic</option>
            </select>
          </div>

          <div class="form-row">
            <label for="threshold">Alert Threshold</label>
            <input type="number" id="threshold" name="threshold" value="75" required />
          </div>

          <div class="form-row">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" placeholder="Optional notes..."></textarea>
          </div>

          <div class="button-row">
            <button type="submit" class="btn-primary">Save Configuration</button>
          </div>
        </form>

        <div id="formMessage" class="message"></div>

        <h2 style="margin-top:20px;">Recent Data</h2>
        <div class="table-container">
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Sensor</th>
                <th>Type</th>
                <th>Value</th>
                <th>Alert</th>
              </tr>
            </thead>
            <tbody id="dataTableBody"></tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

  <script>
    const state = {
      sensorName: "Temperature Sensor A",
      updateInterval: 1000,
      dataType: "temperature",
      threshold: 75,
      notes: "",
      timer: null,
      labels: [],
      values: [],
      maxPoints: 20,
      peak: 0
    };

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const peakValueEl = document.getElementById("peakValue");
    const streamStatusEl = document.getElementById("streamStatus");
    const dataTableBody = document.getElementById("dataTableBody");
    const formMessage = document.getElementById("formMessage");

    const lineCtx = document.getElementById("lineChart").getContext("2d");
    const barCtx = document.getElementById("barChart").getContext("2d");

    const lineChart = new Chart(lineCtx, {
      type: "line",
      data: {
        labels: [],
        datasets: [{
          label: "Live Value",
          data: [],
          borderColor: "#3b82f6",
          backgroundColor: "rgba(59, 130, 246, 0.2)",
          fill: true,
          tension: 0.35,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    const barChart = new Chart(barCtx, {
      type: "bar",
      data: {
        labels: ["Min", "Current", "Average", "Peak"],
        datasets: [{
          label: "Summary",
          data: [0, 0, 0, 0],
          backgroundColor: ["#f59e0b", "#3b82f6", "#22c55e", "#ef4444"]
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function generateValue(type) {
      switch (type) {
        case "temperature":
          return +(20 + Math.random() * 70).toFixed(2);
        case "humidity":
          return +(30 + Math.random() * 60).toFixed(2);
        case "pressure":
          return +(950 + Math.random() * 100).toFixed(2);
        case "traffic":
          return +(100 + Math.random() * 900).toFixed(2);
        default:
          return +(Math.random() * 100).toFixed(2);
      }
    }

    function getTimeLabel() {
      return new Date().toLocaleTimeString();
    }

    function updateStats() {
      const values = state.values;
      const current = values.length ? values[values.length - 1] : 0;
      const avg = values.length
        ? values.reduce((sum, v) => sum + v, 0) / values.length
        : 0;
      const min = values.length ? Math.min(...values) : 0;
      const peak = values.length ? Math.max(...values) : 0;

      state.peak = peak;

      currentValueEl.textContent = current.toFixed(2);
      averageValueEl.textContent = avg.toFixed(2);
      peakValueEl.textContent = peak.toFixed(2);

      barChart.data.datasets[0].data = [
        +min.toFixed(2),
        +current.toFixed(2),
        +avg.toFixed(2),
        +peak.toFixed(2)
      ];
      barChart.update();
    }

    function updateCharts() {
      lineChart.data.labels = [...state.labels];
      lineChart.data.datasets[0].data = [...state.values];
      lineChart.data.datasets[0].label = `${state.sensorName} (${state.dataType})`;
      lineChart.update();
    }

    function prependTableRow(time, value, alert) {
      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${time}</td>
        <td>${state.sensorName}</td>
        <td>${state.dataType}</td>
        <td>${value.toFixed(2)}</td>
        <td>${alert ? "Yes" : "No"}</td>
      `;
      dataTableBody.prepend(row);

      while (dataTableBody.children.length > 15) {
        dataTableBody.removeChild(dataTableBody.lastChild);
      }
    }

    function tick() {
      const time = getTimeLabel();
      const value = generateValue(state.dataType);
      const isAlert = value > state.threshold;

      state.labels.push(time);
      state.values.push(value);

      if (state.labels.length > state.maxPoints) state.labels.shift();
      if (state.values.length > state.maxPoints) state.values.shift();

      updateCharts();
      updateStats();
      prependTableRow(time, value, isAlert);
    }

    function startStream() {
      stopStream();
      state.timer = setInterval(tick, state.updateInterval);
      streamStatusEl.textContent = "Running";
    }

    function stopStream() {
      if (state.timer) {
        clearInterval(state.timer);
        state.timer = null;
      }
      streamStatusEl.textContent = "Stopped";
    }

    function resetData() {
      state.labels = [];
      state.values = [];
      state.peak = 0;
      lineChart.data.labels = [];
      lineChart.data.datasets[0].data = [];
      lineChart.update();
      barChart.data.datasets[0].data = [0, 0, 0, 0];
      barChart.update();
      currentValueEl.textContent = "0";
      averageValueEl.textContent = "0";
      peakValueEl.textContent = "0";
      dataTableBody.innerHTML = "";
    }

    document.getElementById("startBtn").addEventListener("click", startStream);
    document.getElementById("stopBtn").addEventListener("click", stopStream);
    document.getElementById("resetBtn").addEventListener("click", resetData);

    document.getElementById("configForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const sensorName = document.getElementById("sensorName").value.trim();
      const updateInterval = parseInt(document.getElementById("updateInterval").value, 10);
      const dataType = document.getElementById("dataType").value;
      const threshold = parseFloat(document.getElementById("threshold").value);
      const notes = document.getElementById("notes").value.trim();

      if (!sensorName) {
        showMessage("Sensor name is required.", "error");
        return;
      }

      if (isNaN(updateInterval) || updateInterval < 200) {
        showMessage("Update interval must be at least 200 ms.", "error");
        return;
      }

      if (isNaN(threshold)) {
        showMessage("Threshold must be a valid number.", "error");
        return;
      }

      state.sensorName = sensorName;
      state.updateInterval = updateInterval;
      state.dataType = dataType;
      state.threshold = threshold;
      state.notes = notes;

      showMessage("Configuration saved successfully.", "success");

      if (state.timer) {
        startStream();
      }

      updateCharts();
    });

    function showMessage(text, type) {
      formMessage.textContent = text;
      formMessage.className = `message ${type}`;
      setTimeout(() => {
        formMessage.className = "message";
        formMessage.textContent = "";
      }, 3000);
    }

    document.getElementById("sensorName").value = state.sensorName;
    tick();
  </script>
</body>
</html>
