## `app.js`

```javascript
const records = [];
const maxDataPoints = 20;
let streamRunning = true;
let streamInterval = null;

const categoryCounts = {
  Sales: 0,
  Marketing: 0,
  Support: 0,
  Engineering: 0
};

const totalRecordsEl = document.getElementById("totalRecords");
const avgValueEl = document.getElementById("avgValue");
const latestCategoryEl = document.getElementById("latestCategory");
const streamStatusEl = document.getElementById("streamStatus");
const recordsTableBody = document.getElementById("recordsTableBody");
const recordForm = document.getElementById("recordForm");
const formMessage = document.getElementById("formMessage");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");

const lineCtx = document.getElementById("lineChart").getContext("2d");
const barCtx = document.getElementById("barChart").getContext("2d");

const lineChart = new Chart(lineCtx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Value",
        data: [],
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59, 130, 246, 0.2)",
        fill: true,
        tension: 0.35,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      }
    }
  }
});

const barChart = new Chart(barCtx, {
  type: "bar",
  data: {
    labels: Object.keys(categoryCounts),
    datasets: [
      {
        label: "Records by Category",
        data: Object.values(categoryCounts),
        backgroundColor: ["#3b82f6", "#10b981", "#f59e0b", "#8b5cf6"]
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      },
      y: {
        beginAtZero: true,
        ticks: { color: "#94a3b8", precision: 0 },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      }
    }
  }
});

function formatTime(date = new Date()) {
  return date.toLocaleTimeString();
}

function updateStats() {
  totalRecordsEl.textContent = records.length;

  const totalValue = records.reduce((sum, record) => sum + record.value, 0);
  const avg = records.length ? (totalValue / records.length).toFixed(2) : "0";
  avgValueEl.textContent = avg;

  latestCategoryEl.textContent = records.length
    ? records[records.length - 1].category
    : "-";

  streamStatusEl.textContent = streamRunning ? "Running" : "Paused";
}

function updateTable() {
  recordsTableBody.innerHTML = "";

  const recentRecords = [...records].slice(-10).reverse();

  recentRecords.forEach((record) => {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${record.time}</td>
      <td>${record.name}</td>
      <td>${record.value.toFixed(2)}</td>
      <td>${record.category}</td>
      <td>${record.notes || "-"}</td>
    `;
    recordsTableBody.appendChild(row);
  });
}

function updateCharts() {
  const recentRecords = records.slice(-maxDataPoints);

  lineChart.data.labels = recentRecords.map((record) => record.time);
  lineChart.data.datasets[0].data = recentRecords.map((record) => record.value);
  lineChart.update();

  barChart.data.datasets[0].data = Object.values(categoryCounts);
  barChart.update();
}

function addRecord(record) {
  records.push(record);
  categoryCounts[record.category] = (categoryCounts[record.category] || 0) + 1;

  updateStats();
  updateTable();
  updateCharts();
}

function validateForm(data) {
  if (!data.name.trim()) {
    return "Name is required.";
  }

  if (Number.isNaN(data.value) || data.value < 0) {
    return "Value must be a valid non-negative number.";
  }

  if (!data.category) {
    return "Category is required.";
  }

  return null;
}

recordForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const formData = new FormData(recordForm);
  const data = {
    name: formData.get("name").toString(),
    value: parseFloat(formData.get("value")),
    category: formData.get("category").toString(),
    notes: formData.get("notes").toString().trim(),
    time: formatTime()
  };

  const error = validateForm(data);

  if (error) {
    formMessage.textContent = error;
    formMessage.style.color = "#ef4444";
    return;
  }

  addRecord(data);
  formMessage.textContent = "Record submitted successfully.";
  formMessage.style.color = "#10b981";
  recordForm.reset();
});

function generateRandomRecord() {
  const categories = Object.keys(categoryCounts);
  const category = categories[Math.floor(Math.random() * categories.length)];
  const value = +(Math.random() * 100).toFixed(2);

  return {
    name: `Auto-${records.length + 1}`,
    value,
    category,
    notes: "Generated from live stream",
    time: formatTime()
  };
}

function startStream() {
  streamInterval = setInterval(() => {
    if (!streamRunning) return;
    addRecord(generateRandomRecord());
  }, 2000);
}

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;
  toggleStreamBtn.textContent = streamRunning ? "Pause Stream" : "Resume Stream";
  updateStats();
});

for (let i = 0; i < 5; i++) {
  addRecord(generateRandomRecord());
}

startStream();
updateStats();
updateTable();
updateCharts();
```

