## `app.js`

```javascript
const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const submissionCountEl = document.getElementById("submissionCount");
const dataForm = document.getElementById("dataForm");
const labelInput = document.getElementById("labelInput");
const valueInput = document.getElementById("valueInput");
const submissionList = document.getElementById("submissionList");
const startBtn = document.getElementById("startBtn");
const stopBtn = document.getElementById("stopBtn");

let chart;
let liveData = [];
let liveLabels = [];
let submissions = [];
let intervalId = null;
const maxPoints = 20;

function initChart() {
  const ctx = document.getElementById("liveChart").getContext("2d");

  chart = new Chart(ctx, {
    type: "line",
    data: {
      labels: liveLabels,
      datasets: [
        {
          label: "Sensor Value",
          data: liveData,
          borderColor: "#2563eb",
          backgroundColor: "rgba(37, 99, 235, 0.2)",
          tension: 0.3,
          fill: true
        }
      ]
    },
    options: {
      responsive: true,
      animation: false,
      scales: {
        y: {
          beginAtZero: true
        }
      }
    }
  });
}

function updateMetrics() {
  const current = liveData.length ? liveData[liveData.length - 1] : 0;
  const average = liveData.length
    ? (liveData.reduce((sum, val) => sum + val, 0) / liveData.length).toFixed(2)
    : 0;

  currentValueEl.textContent = current;
  averageValueEl.textContent = average;
  submissionCountEl.textContent = submissions.length;
}

function addDataPoint(label, value, isSubmission = false) {
  liveLabels.push(label);
  liveData.push(value);

  if (liveData.length > maxPoints) {
    liveData.shift();
    liveLabels.shift();
  }

  if (isSubmission) {
    submissions.unshift({ label, value, time: new Date().toLocaleTimeString() });
    renderSubmissions();
  }

  chart.update();
  updateMetrics();
}

function renderSubmissions() {
  submissionList.innerHTML = "";

  submissions.slice(0, 10).forEach((item) => {
    const li = document.createElement("li");
    li.textContent = `${item.time} — ${item.label}: ${item.value}`;
    submissionList.appendChild(li);
  });
}

function generateRandomData() {
  const value = Math.floor(Math.random() * 100);
  const label = new Date().toLocaleTimeString();
  addDataPoint(label, value);
}

function startSimulation() {
  if (intervalId) return;
  intervalId = setInterval(generateRandomData, 1000);
}

function stopSimulation() {
  clearInterval(intervalId);
  intervalId = null;
}

dataForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const label = labelInput.value.trim();
  const value = Number(valueInput.value);

  if (!label || Number.isNaN(value)) {
    return;
  }

  addDataPoint(label, value, true);

  dataForm.reset();
});

startBtn.addEventListener("click", startSimulation);
stopBtn.addEventListener("click", stopSimulation);

initChart();
startSimulation();
```

