    }

    @media (max-width: 900px) {
      .main-grid {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Operations Dashboard</h1>
        <p>Interactive real-time monitoring and form-driven event capture.</p>
      </div>
      <div class="toolbar">
        <button id="toggleLiveBtn" class="btn-primary">Pause Live Feed</button>
        <button id="clearLogBtn" class="btn-danger">Clear Log</button>
      </div>
    </div>

    <div class="grid stats">
      <div class="card stat-card">
        <div class="stat-label">Current Value</div>
        <div class="stat-value" id="currentValue">0</div>
      </div>
      <div class="card stat-card">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>
      <div class="card stat-card">
        <div class="stat-label">Peak</div>
        <div class="stat-value" id="peakValue">0</div>
      </div>
      <div class="card stat-card">
        <div class="stat-label">Events Logged</div>
        <div class="stat-value" id="eventCount">0</div>
      </div>
    </div>

    <div class="grid main-grid">
      <div class="card panel">
        <div class="status-row">
          <h2 style="margin: 0;">Real-Time Data Stream</h2>
          <div class="status-text">
            <span class="live-dot" id="liveDot"></span>
            <span id="liveStatus">Live updates active</span>
          </div>
        </div>

        <div class="chart-wrap">
          <canvas id="lineChart" width="800" height="300"></canvas>
        </div>

        <p class="footer-note">
          Simulated data updates every second. Replace the generator with a WebSocket, SSE, or polling API source.
        </p>
      </div>

      <div class="card panel">
        <h2>Add Event</h2>
        <form id="eventForm">
          <div class="field">
            <label for="eventName">Event Name</label>
            <input id="eventName" name="eventName" type="text" placeholder="e.g. Sensor Alert" required />
          </div>

          <div class="field">
            <label for="eventType">Type</label>
            <select id="eventType" name="eventType" required>
              <option value="info">Info</option>
              <option value="success">Success</option>
              <option value="warning">Warning</option>
            </select>
          </div>

          <div class="field">
            <label for="eventValue">Value</label>
            <input id="eventValue" name="eventValue" type="number" placeholder="e.g. 42" required />
          </div>

          <div class="field">
            <label for="eventNotes">Notes</label>
            <textarea id="eventNotes" name="eventNotes" rows="4" placeholder="Optional details..."></textarea>
          </div>

          <div class="form-actions">
            <button type="submit" class="btn-primary">Submit Event</button>
            <button type="reset" class="btn-secondary">Reset</button>
          </div>
        </form>
      </div>
    </div>

    <div class="card panel" style="margin-top: 20px;">
      <h2>Event Log</h2>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Name</th>
              <th>Type</th>
              <th>Value</th>
              <th>Notes</th>
            </tr>
          </thead>
          <tbody id="eventTableBody"></tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const MAX_POINTS = 30;
    const dataPoints = [];
    const events = [];
    let live = true;
    let intervalId = null;

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const toggleLiveBtn = document.getElementById('toggleLiveBtn');
    const clearLogBtn = document.getElementById('clearLogBtn');
    const liveStatusEl = document.getElementById('liveStatus');
    const liveDotEl = document.getElementById('liveDot');
    const eventForm = document.getElementById('eventForm');
    const eventTableBody = document.getElementById('eventTableBody');
    const canvas = document.getElementById('lineChart');
    const ctx = canvas.getContext('2d');

    function generatePoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1].value : 50;
      const next = Math.max(0, Math.min(100, last + (Math.random() * 20 - 10)));
      return {
        time: new Date(),
        value: Number(next.toFixed(1))
      };
    }

    function addDataPoint(point) {
      dataPoints.push(point);
      if (dataPoints.length > MAX_POINTS) {
        dataPoints.shift();
      }
      updateStats();
      drawChart();
    }

    function updateStats() {
      if (!dataPoints.length) return;

      const values = dataPoints.map(p => p.value);
      const current = values[values.length - 1];
      const avg = values.reduce((sum, v) => sum + v, 0) / values.length;
      const peak = Math.max(...values);

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(1);
      eventCountEl.textContent = events.length;
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      const padding = 32;

      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      for (let i = 0; i <= 4; i++) {
        const value = 100 - i * 25;
        const y = padding + ((height - padding * 2) / 4) * i;
        ctx.fillText(String(value), 6, y + 4);
      }

      if (dataPoints.length < 2) return;

      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      // Line
      ctx.beginPath();
      dataPoints.forEach((point, index) => {
        const x = padding + (index / (MAX_POINTS - 1)) * chartWidth;
        const y = padding + ((100 - point.value) / 100) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Fill area
      ctx.lineTo(padding + chartWidth, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();
      ctx.fillStyle = 'rgba(59, 130, 246, 0.15)';
      ctx.fill();

      // Points
      dataPoints.forEach((point, index) => {
        const x = padding + (index / (MAX_POINTS - 1)) * chartWidth;
        const y = padding + ((100 - point.value) / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = '#93c5fd';
        ctx.fill();
      });
    }

    function getBadgeClass(type) {
      switch (type) {
        case 'success': return 'badge badge-success';
        case 'warning': return 'badge badge-warning';
        default: return 'badge badge-info';
      }
    }

    function renderEvents() {
      eventTableBody.innerHTML = '';

      [...events].reverse().forEach(event => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${event.time}</td>
          <td>${escapeHtml(event.name)}</td>
          <td><span class="${getBadgeClass(event.type)}">${event.type}</span></td>
          <td>${event.value}</td>
          <td>${escapeHtml(event.notes || '-')}</td>
        `;
        eventTableBody.appendChild(tr);
      });

      eventCountEl.textContent = events.length;
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    function addEvent({ name, type, value, notes }) {
      events.push({
        time: new Date().toLocaleTimeString(),
        name,
        type,
        value,
        notes
      });
      renderEvents();
    }

    function startLiveFeed() {
      intervalId = setInterval(() => {
        if (!live) return;
        addDataPoint(generatePoint());
      }, 1000);
    }

    toggleLiveBtn.addEventListener('click', () => {
      live = !live;
      toggleLiveBtn.textContent = live ? 'Pause Live Feed' : 'Resume Live Feed';
      liveStatusEl.textContent = live ? 'Live updates active' : 'Live updates paused';
      liveDotEl.style.background = live ? '#22c55e' : '#ef4444';
      liveDotEl.style.boxShadow = live
        ? '0 0 12px rgba(34, 197, 94, 0.8)'
        : '0 0 12px rgba(239, 68, 68, 0.8)';
    });

    clearLogBtn.addEventListener('click', () => {
      events.length = 0;
      renderEvents();
    });

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(eventForm);
      const name = formData.get('eventName').trim();
      const type = formData.get('eventType');
      const value = Number(formData.get('eventValue'));
      const notes = formData.get('eventNotes').trim();

      if (!name || Number.isNaN(value)) {
        alert('Please provide a valid event name and numeric value.');
        return;
      }

      addEvent({ name, type, value, notes });
      eventForm.reset();
    });

    // Seed initial chart data
    for (let i = 0; i < 12; i++) {
      addDataPoint(generatePoint());
    }

    renderEvents();
    startLiveFeed();

    // Redraw on resize for sharper canvas rendering if desired
    window.addEventListener('resize', () => {
      drawChart();
    });
  </script>
</body>
</html>
```

