          <button id="resetBtn" class="secondary">Reset Data</button>
        </div>
        <canvas id="realtimeChart"></canvas>
      </div>

      <div class="card form-card">
        <h3>Submit Event</h3>
        <form id="eventForm" novalidate>
          <div class="field">
            <label for="eventName">Event Name</label>
            <input type="text" id="eventName" name="eventName" placeholder="e.g. Payment Failure" />
            <div class="error" id="eventNameError"></div>
          </div>

          <div class="field">
            <label for="eventType">Event Type</label>
            <select id="eventType" name="eventType">
              <option value="">Select type</option>
              <option value="Info">Info</option>
              <option value="Warning">Warning</option>
              <option value="Success">Success</option>
            </select>
            <div class="error" id="eventTypeError"></div>
          </div>

          <div class="field">
            <label for="eventValue">Numeric Value</label>
            <input type="number" id="eventValue" name="eventValue" placeholder="e.g. 42" />
            <div class="error" id="eventValueError"></div>
          </div>

          <div class="field">
            <label for="eventNotes">Notes</label>
            <textarea id="eventNotes" name="eventNotes" rows="4" placeholder="Optional details..."></textarea>
            <div class="error" id="eventNotesError"></div>
          </div>

          <button type="submit">Submit Event</button>
          <div class="success-message" id="formSuccess"></div>
        </form>
      </div>

      <div class="card table-card">
        <h3>Recent Events</h3>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Name</th>
              <th>Type</th>
              <th>Value</th>
              <th>Notes</th>
            </tr>
          </thead>
          <tbody id="eventsTableBody"></tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const state = {
      isStreaming: true,
      maxPoints: 20,
      chartLabels: [],
      activeUsersData: [],
      transactionsData: [],
      errorRateData: [],
      systemLoadData: [],
      metrics: {
        activeUsers: 120,
        transactions: 75,
        errorRate: 1.8,
        systemLoad: 48
      },
      previousMetrics: {
        activeUsers: 115,
        transactions: 72,
        errorRate: 2.1,
        systemLoad: 45
      },
      events: []
    };

    const els = {
      activeUsers: document.getElementById("activeUsers"),
      transactions: document.getElementById("transactions"),
      errorRate: document.getElementById("errorRate"),
      systemLoad: document.getElementById("systemLoad"),
      activeUsersTrend: document.getElementById("activeUsersTrend"),
      transactionsTrend: document.getElementById("transactionsTrend"),
      errorRateTrend: document.getElementById("errorRateTrend"),
      systemLoadTrend: document.getElementById("systemLoadTrend"),
      pauseBtn: document.getElementById("pauseBtn"),
      addSpikeBtn: document.getElementById("addSpikeBtn"),
      resetBtn: document.getElementById("resetBtn"),
      eventForm: document.getElementById("eventForm"),
      formSuccess: document.getElementById("formSuccess"),
      eventsTableBody: document.getElementById("eventsTableBody")
    };

    const ctx = document.getElementById("realtimeChart").getContext("2d");

    const realtimeChart = new Chart(ctx, {
      type: "line",
      data: {
        labels: state.chartLabels,
        datasets: [
          {
            label: "Active Users",
            data: state.activeUsersData,
            borderColor: "#38bdf8",
            backgroundColor: "rgba(56, 189, 248, 0.15)",
            tension: 0.35,
            fill: false
          },
          {
            label: "Transactions / Min",
            data: state.transactionsData,
            borderColor: "#22c55e",
            backgroundColor: "rgba(34, 197, 94, 0.15)",
            tension: 0.35,
            fill: false
          },
          {
            label: "Error Rate (%)",
            data: state.errorRateData,
            borderColor: "#ef4444",
            backgroundColor: "rgba(239, 68, 68, 0.15)",
            tension: 0.35,
            fill: false
          },
          {
            label: "System Load (%)",
            data: state.systemLoadData,
            borderColor: "#f59e0b",
            backgroundColor: "rgba(245, 158, 11, 0.15)",
            tension: 0.35,
            fill: false
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: "#e5e7eb"
            }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.1)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.1)" }
          }
        }
      }
    });

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function randomDelta(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function updateMetrics() {
      state.previousMetrics = { ...state.metrics };

      state.metrics.activeUsers = Math.round(clamp(
        state.metrics.activeUsers + randomDelta(-8, 12),
        50,
        300
      ));

      state.metrics.transactions = Math.round(clamp(
        state.metrics.transactions + randomDelta(-6, 10),
        20,
        180
      ));

      state.metrics.errorRate = Number(clamp(
        state.metrics.errorRate + randomDelta(-0.3, 0.25),
        0.1,
        8
      ).toFixed(2));

      state.metrics.systemLoad = Math.round(clamp(
        state.metrics.systemLoad + randomDelta(-5, 6),
        10,
        100
      ));
    }

    function calculateTrend(current, previous) {
      if (previous === 0) return "0.0";
      return (((current - previous) / previous) * 100).toFixed(1);
    }

    function renderMetrics() {
      els.activeUsers.textContent = state.metrics.activeUsers;
      els.transactions.textContent = state.metrics.transactions;
      els.errorRate.textContent = `${state.metrics.errorRate}%`;
      els.systemLoad.textContent = `${state.metrics.systemLoad}%`;

      renderTrend(els.activeUsersTrend, calculateTrend(state.metrics.activeUsers, state.previousMetrics.activeUsers));
      renderTrend(els.transactionsTrend, calculateTrend(state.metrics.transactions, state.previousMetrics.transactions));
      renderTrend(els.errorRateTrend, calculateTrend(state.metrics.errorRate, state.previousMetrics.errorRate), true);
      renderTrend(els.systemLoadTrend, calculateTrend(state.metrics.systemLoad, state.previousMetrics.systemLoad));
    }

    function renderTrend(el, value, invertGood = false) {
      const numeric = Number(value);
      const positive = numeric >= 0;
      const isGood = invertGood ? !positive : positive;
      el.textContent = `${positive ? "+" : ""}${value}%`;
      el.className = `metric-trend ${isGood ? "up" : "down"}`;
    }

    function pushChartData() {
      const label = formatTime();

      state.chartLabels.push(label);
      state.activeUsersData.push(state.metrics.activeUsers);
      state.transactionsData.push(state.metrics.transactions);
      state.errorRateData.push(state.metrics.errorRate);
      state.systemLoadData.push(state.metrics.systemLoad);

      if (state.chartLabels.length > state.maxPoints) {
        state.chartLabels.shift();
        state.activeUsersData.shift();
        state.transactionsData.shift();
        state.errorRateData.shift();
        state.systemLoadData.shift();
      }

      realtimeChart.update();
    }

    function tick() {
      if (!state.isStreaming) return;
      updateMetrics();
      renderMetrics();
      pushChartData();
    }

    function simulateSpike() {
      state.previousMetrics = { ...state.metrics };
      state.metrics.activeUsers = clamp(state.metrics.activeUsers + 60, 50, 300);
      state.metrics.transactions = clamp(state.metrics.transactions + 40, 20, 180);
      state.metrics.errorRate = Number(clamp(state.metrics.errorRate + 1.2, 0.1, 8).toFixed(2));
      state.metrics.systemLoad = clamp(state.metrics.systemLoad + 18, 10, 100);
      renderMetrics();
      pushChartData();
      prependEvent({
        time: formatTime(),
        name: "Traffic Spike Simulation",
        type: "Warning",
        value: state.metrics.transactions,
        notes: "Manual spike generated from dashboard controls."
      });
    }

    function resetDashboard() {
      state.chartLabels.length = 0;
      state.activeUsersData.length = 0;
      state.transactionsData.length = 0;
      state.errorRateData.length = 0;
      state.systemLoadData.length = 0;
      state.events = [];
      els.eventsTableBody.innerHTML = "";

      state.metrics = {
        activeUsers: 120,
        transactions: 75,
        errorRate: 1.8,
        systemLoad: 48
      };

      state.previousMetrics = {
        activeUsers: 115,
        transactions: 72,
        errorRate: 2.1,
        systemLoad: 45
      };

      renderMetrics();
      realtimeChart.update();
    }

    function prependEvent(event) {
      state.events.unshift(event);
      if (state.events.length > 12) {
        state.events.pop();
      }
      renderEvents();
    }

    function renderEvents() {
      els.eventsTableBody.innerHTML = state.events.map(event => `
        <tr>
          <td>${event.time}</td>
          <td>${escapeHtml(event.name)}</td>
          <td>${renderTypePill(event.type)}</td>
          <td>${escapeHtml(String(event.value))}</td>
          <td>${escapeHtml(event.notes || "-")}</td>
        </tr>
      `).join("");
    }

    function renderTypePill(type) {
      const map = {
        Info: "pill pill-info",
        Warning: "pill pill-warning",
        Success: "pill pill-success"
      };
      return `<span class="${map[type] || "pill pill-info"}">${escapeHtml(type)}</span>`;
    }

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function clearErrors() {
      document.querySelectorAll(".error").forEach(el => el.textContent = "");
      els.formSuccess.textContent = "";
    }

    function validateForm(data) {
      const errors = {};

      if (!data.eventName.trim()) {
        errors.eventName = "Event name is required.";
      } else if (data.eventName.trim().length < 3) {
        errors.eventName = "Event name must be at least 3 characters.";
      }

      if (!data.eventType) {
        errors.eventType = "Please select an event type.";
      }

      if (data.eventValue === "") {
        errors.eventValue = "Numeric value is required.";
      } else if (isNaN(Number(data.eventValue))) {
        errors.eventValue = "Numeric value must be a number.";
      }

      if (data.eventNotes.length > 200) {
        errors.eventNotes = "Notes must be 200 characters or fewer.";
      }

      return errors;
    }

    function showErrors(errors) {
      document.getElementById("eventNameError").textContent = errors.eventName || "";
      document.getElementById("eventTypeError").textContent = errors.eventType || "";
      document.getElementById("eventValueError").textContent = errors.eventValue || "";
      document.getElementById("eventNotesError").textContent = errors.eventNotes || "";
    }

    els.eventForm.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const formData = {
        eventName: document.getElementById("eventName").value,
        eventType: document.getElementById("eventType").value,
        eventValue: document.getElementById("eventValue").value,
        eventNotes: document.getElementById("eventNotes").value
      };

      const errors = validateForm(formData);
      if (Object.keys(errors).length > 0) {
        showErrors(errors);
        return;
      }

      const event = {
        time: formatTime(),
        name: formData.eventName.trim(),
        type: formData.eventType,
        value: Number(formData.eventValue),
        notes: formData.eventNotes.trim()
      };

      prependEvent(event);
      els.formSuccess.textContent = "Event submitted successfully.";
      els.eventForm.reset();

      state.previousMetrics = { ...state.metrics };
      state.metrics.transactions = clamp(state.metrics.transactions + 5, 20, 180);
      state.metrics.activeUsers = clamp(state.metrics.activeUsers + 2, 50, 300);
      renderMetrics();
      pushChartData();
    });

    els.pauseBtn.addEventListener("click", () => {
      state.isStreaming = !state.isStreaming;
      els.pauseBtn.textContent = state.isStreaming ? "Pause Stream" : "Resume Stream";
    });

    els.addSpikeBtn.addEventListener("click", simulateSpike);
    els.resetBtn.addEventListener("click", resetDashboard);

    renderMetrics();
    for (let i = 0; i < 8; i++) {
      updateMetrics();
      pushChartData();
    }

    prependEvent({
      time: formatTime(),
      name: "Dashboard Initialized",
      type: "Success",
      value: 1,
      notes: "Initial dashboard state loaded."
    });

    setInterval(tick, 2000);
  </script>
</body>
</html>
```

