# 2. `server.js`

This backend:

- Serves static frontend files
- Hosts a WebSocket server
- Simulates real-time metric updates
- Accepts form submissions from the frontend
- Broadcasts updates to all connected clients

```js
const express = require('express');
const http = require('http');
const path = require('path');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

let dashboardState = {
  metrics: {
    temperature: 22,
    humidity: 55,
    pressure: 1012
  },
  submissions: []
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

function generateMetricDrift() {
  dashboardState.metrics.temperature = +(dashboardState.metrics.temperature + (Math.random() * 2 - 1)).toFixed(2);
  dashboardState.metrics.humidity = +(dashboardState.metrics.humidity + (Math.random() * 4 - 2)).toFixed(2);
  dashboardState.metrics.pressure = +(dashboardState.metrics.pressure + (Math.random() * 2 - 1)).toFixed(2);

  broadcast({
    type: 'metrics:update',
    payload: {
      timestamp: Date.now(),
      metrics: dashboardState.metrics
    }
  });
}

setInterval(generateMetricDrift, 2000);

app.get('/api/state', (req, res) => {
  res.json(dashboardState);
});

app.post('/api/submit', (req, res) => {
  const { name, threshold, note } = req.body;

  if (!name || threshold === undefined) {
    return res.status(400).json({
      error: 'Name and threshold are required'
    });
  }

  const submission = {
    id: Date.now(),
    name,
    threshold: Number(threshold),
    note: note || '',
    createdAt: new Date().toISOString()
  };

  dashboardState.submissions.unshift(submission);

  broadcast({
    type: 'submission:new',
    payload: submission
  });

  res.status(201).json({
    success: true,
    submission
  });
});

wss.on('connection', ws => {
  ws.send(JSON.stringify({
    type: 'init',
    payload: dashboardState
  }));
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

