```js
const temperatureValue = document.getElementById('temperatureValue');
const humidityValue = document.getElementById('humidityValue');
const pressureValue = document.getElementById('pressureValue');
const submissionList = document.getElementById('submissionList');
const alertForm = document.getElementById('alertForm');
const formStatus = document.getElementById('formStatus');

const labels = [];
const temperatureData = [];
const humidityData = [];
const pressureData = [];
const MAX_POINTS = 20;

const ctx = document.getElementById('metricsChart').getContext('2d');
const metricsChart = new Chart(ctx, {
  type: 'line',
  data: {
    labels,
    datasets: [
      {
        label: 'Temperature',
        data: temperatureData,
        borderColor: '#f97316',
        backgroundColor: 'rgba(249, 115, 22, 0.2)',
        tension: 0.3
      },
      {
        label: 'Humidity',
        data: humidityData,
        borderColor: '#22c55e',
        backgroundColor: 'rgba(34, 197, 94, 0.2)',
        tension: 0.3
      },
      {
        label: 'Pressure',
        data: pressureData,
        borderColor: '#38bdf8',
        backgroundColor: 'rgba(56, 189, 248, 0.2)',
        tension: 0.3
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      x: {
        ticks: { color: '#cbd5e1' },
        grid: { color: '#334155' }
      },
      y: {
        ticks: { color: '#cbd5e1' },
        grid: { color: '#334155' }
      }
    },
    plugins: {
      legend: {
        labels: {
          color: '#e2e8f0'
        }
      }
    }
  }
});

function updateStats(metrics) {
  temperatureValue.textContent = `${metrics.temperature} °C`;
  humidityValue.textContent = `${metrics.humidity} %`;
  pressureValue.textContent = `${metrics.pressure} hPa`;
}

function addChartPoint(timestamp, metrics) {
  const timeLabel = new Date(timestamp).toLocaleTimeString();

  labels.push(timeLabel);
  temperatureData.push(metrics.temperature);
  humidityData.push(metrics.humidity);
  pressureData.push(metrics.pressure);

  if (labels.length > MAX_POINTS) {
    labels.shift();
    temperatureData.shift();
    humidityData.shift();
    pressureData.shift();
  }

  metricsChart.update();
}

function renderSubmission(submission) {
  const li = document.createElement('li');
  li.className = 'submission-item';
  li.innerHTML = `
    <strong>${submission.name}</strong>
    <div>Threshold: ${submission.threshold}</div>
    <div>${submission.note || ''}</div>
    <small>${new Date(submission.createdAt).toLocaleString()}</small>
  `;
  submissionList.prepend(li);
}

async function loadInitialState() {
  const res = await fetch('/api/state');
  const state = await res.json();

  updateStats(state.metrics);
  addChartPoint(Date.now(), state.metrics);

  submissionList.innerHTML = '';
  state.submissions.forEach(renderSubmission);
}

function connectWebSocket() {
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  const ws = new WebSocket(`${protocol}//${window.location.host}`);

  ws.addEventListener('message', event => {
    const message = JSON.parse(event.data);

    switch (message.type) {
      case 'init':
        updateStats(message.payload.metrics);
        submissionList.innerHTML = '';
        message.payload.submissions.forEach(renderSubmission);
        break;

      case 'metrics:update':
        updateStats(message.payload.metrics);
        addChartPoint(message.payload.timestamp, message.payload.metrics);
        break;

      case 'submission:new':
        renderSubmission(message.payload);
        break;
    }
  });

  ws.addEventListener('close', () => {
    formStatus.textContent = 'Connection lost. Reconnecting...';
    setTimeout(connectWebSocket, 2000);
  });

  ws.addEventListener('open', () => {
    formStatus.textContent = 'Connected';
    setTimeout(() => {
      if (formStatus.textContent === 'Connected') {
        formStatus.textContent = '';
      }
    }, 1500);
  });
}

alertForm.addEventListener('submit', async event => {
  event.preventDefault();
  formStatus.textContent = 'Submitting...';

  const formData = new FormData(alertForm);
  const payload = {
    name: formData.get('name'),
    threshold: formData.get('threshold'),
    note: formData.get('note')
  };

  try {
    const res = await fetch('/api/submit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    const result = await res.json();

    if (!res.ok) {
      throw new Error(result.error || 'Submission failed');
    }

    formStatus.textContent = 'Submitted successfully';
    alertForm.reset();

    setTimeout(() => {
      if (formStatus.textContent === 'Submitted successfully') {
        formStatus.textContent = '';
      }
    }, 2000);
  } catch (error) {
    formStatus.textContent = error.message;
  }
});

loadInitialState();
connectWebSocket();
