## `app.js`

```javascript
const state = {
  events: [],
  maxPoints: 20,
  chart: null
};

const elements = {
  totalEvents: document.getElementById("totalEvents"),
  averageValue: document.getElementById("averageValue"),
  latestCategory: document.getElementById("latestCategory"),
  lastUpdated: document.getElementById("lastUpdated"),
  eventsTableBody: document.getElementById("eventsTableBody"),
  eventForm: document.getElementById("eventForm"),
  formMessage: document.getElementById("formMessage"),
  connectionStatus: document.getElementById("connectionStatus")
};

function formatTime(date) {
  return new Intl.DateTimeFormat([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
  }).format(date);
}

function createEvent({ category, value, note = "" }) {
  return {
    id: crypto.randomUUID(),
    timestamp: new Date(),
    category,
    value: Number(value),
    note
  };
}

function seedInitialData() {
  const categories = ["Sales", "Support", "System", "Marketing"];
  for (let i = 0; i < 8; i++) {
    const event = createEvent({
      category: categories[Math.floor(Math.random() * categories.length)],
      value: (Math.random() * 100 + 10).toFixed(2),
      note: "Auto-generated seed event"
    });
    state.events.unshift(event);
  }
}

function initChart() {
  const ctx = document.getElementById("liveChart").getContext("2d");

  state.chart = new Chart(ctx, {
    type: "line",
    data: {
      labels: [],
      datasets: [
        {
          label: "Value",
          data: [],
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.2)",
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      plugins: {
        legend: {
          labels: {
            color: "#e5e7eb"
          }
        }
      },
      scales: {
        x: {
          ticks: { color: "#94a3b8" },
          grid: { color: "rgba(148, 163, 184, 0.15)" }
        },
        y: {
          ticks: { color: "#94a3b8" },
          grid: { color: "rgba(148, 163, 184, 0.15)" }
        }
      }
    }
  });
}

function refreshChart() {
  const recent = [...state.events]
    .slice(0, state.maxPoints)
    .reverse();

  state.chart.data.labels = recent.map(event => formatTime(event.timestamp));
  state.chart.data.datasets[0].data = recent.map(event => event.value);
  state.chart.update();
}

function renderMetrics() {
  const total = state.events.length;
  const avg =
    total === 0
      ? 0
      : state.events.reduce((sum, event) => sum + event.value, 0) / total;

  const latest = state.events[0];

  elements.totalEvents.textContent = String(total);
  elements.averageValue.textContent = avg.toFixed(2);
  elements.latestCategory.textContent = latest ? latest.category : "—";
  elements.lastUpdated.textContent = latest
    ? formatTime(latest.timestamp)
    : "—";
}

function renderTable() {
  elements.eventsTableBody.innerHTML = "";

  state.events.slice(0, 10).forEach(event => {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${formatTime(event.timestamp)}</td>
      <td>${event.category}</td>
      <td>${event.value.toFixed(2)}</td>
      <td>${event.note || "—"}</td>
    `;
    elements.eventsTableBody.appendChild(row);
  });
}

function renderAll() {
  renderMetrics();
  renderTable();
  refreshChart();
}

function addEvent(event) {
  state.events.unshift(event);
  renderAll();
}

function handleFormSubmit(e) {
  e.preventDefault();

  const formData = new FormData(elements.eventForm);
  const category = formData.get("category")?.toString().trim();
  const value = formData.get("value")?.toString().trim();
  const note = formData.get("note")?.toString().trim();

  if (!category || !value || Number(value) < 0) {
    elements.formMessage.textContent = "Please enter a valid category and value.";
    elements.formMessage.style.color = "#f87171";
    return;
  }

  const newEvent = createEvent({
    category,
    value,
    note
  });

  addEvent(newEvent);

  elements.formMessage.textContent = "Event submitted successfully.";
  elements.formMessage.style.color = "#22c55e";
  elements.eventForm.reset();
}

function simulateRealtimeData() {
  const categories = ["Sales", "Support", "System", "Marketing"];

  setInterval(() => {
    const randomEvent = createEvent({
      category: categories[Math.floor(Math.random() * categories.length)],
      value: (Math.random() * 120 + 5).toFixed(2),
      note: "Simulated real-time event"
    });

    addEvent(randomEvent);
  }, 3000);
}

function init() {
  seedInitialData();
  initChart();
  renderAll();
  simulateRealtimeData();

  elements.eventForm.addEventListener("submit", handleFormSubmit);
  elements.connectionStatus.textContent = "Live";
}

init();
```

