      data: {
        labels: chartLabels,
        datasets: [{
          label: 'Live Value',
          data: chartData,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function updateStats() {
      totalEventsEl.textContent = events.length;

      const total = events.reduce((sum, event) => sum + event.value, 0);
      const average = events.length ? (total / events.length).toFixed(2) : 0;
      averageValueEl.textContent = average;

      latestCategoryEl.textContent = events.length
        ? events[events.length - 1].category
        : '-';
    }

    function addLogItem(event) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.innerHTML = `
        <strong>${event.name}</strong><br />
        Value: ${event.value} | Category: ${event.category}<br />
        <small>${event.time}</small>
      `;
      eventLogEl.prepend(item);
    }

    function addEvent(name, value, category) {
      const time = new Date().toLocaleTimeString();
      const event = {
        name,
        value: Number(value),
        category,
        time
      };

      events.push(event);

      chartLabels.push(time);
      chartData.push(event.value);

      if (chartLabels.length > 20) {
        chartLabels.shift();
        chartData.shift();
      }

      liveChart.update();
      updateStats();
      addLogItem(event);
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('eventName').value.trim();
      const value = document.getElementById('eventValue').value;
      const category = document.getElementById('eventCategory').value;

      if (!name || !value || !category) {
        alert('Please fill in all fields.');
        return;
      }

      addEvent(name, value, category);
      eventForm.reset();
    });

    function simulateRealTimeData() {
      const categories = ['Sales', 'Marketing', 'Operations'];
      const randomName = `Auto Event ${events.length + 1}`;
      const randomValue = Math.floor(Math.random() * 100) + 1;
      const randomCategory = categories[Math.floor(Math.random() * categories.length)];

      addEvent(randomName, randomValue, randomCategory);
    }

    setInterval(simulateRealTimeData, 3000);
  </script>
</body>
</html>
```

