## `app.js`

```javascript
const maxDataPoints = 20;
let streamActive = true;

const labels = [];
const data = [];

const latestValueEl = document.getElementById("latestValue");
const averageValueEl = document.getElementById("averageValue");
const totalPointsEl = document.getElementById("totalPoints");
const eventLogEl = document.getElementById("eventLog");
const formMessageEl = document.getElementById("formMessage");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const connectionStatusEl = document.getElementById("connectionStatus");

const ctx = document.getElementById("liveChart").getContext("2d");

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Sensor Value",
        data,
        borderColor: "#60a5fa",
        backgroundColor: "rgba(96, 165, 250, 0.2)",
        fill: true,
        tension: 0.3,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(203, 213, 225, 0.1)" }
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(203, 213, 225, 0.1)" }
      }
    },
    plugins: {
      legend: {
        labels: {
          color: "#e2e8f0"
        }
      }
    }
  }
});

function getCurrentTimeLabel() {
  return new Date().toLocaleTimeString();
}

function addLog(message) {
  const li = document.createElement("li");
  li.textContent = `[${getCurrentTimeLabel()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 10) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const total = data.length;
  const latest = total ? data[data.length - 1] : "--";
  const average = total
    ? (data.reduce((sum, val) => sum + val, 0) / total).toFixed(2)
    : "--";

  latestValueEl.textContent = latest;
  averageValueEl.textContent = average;
  totalPointsEl.textContent = total;
}

function addDataPoint(label, value, source = "manual") {
  labels.push(label);
  data.push(value);

  if (labels.length > maxDataPoints) labels.shift();
  if (data.length > maxDataPoints) data.shift();

  liveChart.update();
  updateMetrics();
  addLog(`Added ${source} data point: ${value}`);
}

function generateRandomValue() {
  return Number((Math.random() * 100).toFixed(2));
}

setInterval(() => {
  if (!streamActive) return;
  addDataPoint(getCurrentTimeLabel(), generateRandomValue(), "stream");
}, 1000);

toggleStreamBtn.addEventListener("click", () => {
  streamActive = !streamActive;
  toggleStreamBtn.textContent = streamActive ? "Pause Stream" : "Resume Stream";
  connectionStatusEl.textContent = streamActive ? "Live" : "Paused";
  addLog(streamActive ? "Stream resumed" : "Stream paused");
});

document.getElementById("dataForm").addEventListener("submit", (e) => {
  e.preventDefault();

  const labelInput = document.getElementById("labelInput");
  const valueInput = document.getElementById("valueInput");

  const label = labelInput.value.trim() || getCurrentTimeLabel();
  const value = parseFloat(valueInput.value);

  if (Number.isNaN(value)) {
    formMessageEl.textContent = "Please enter a valid numeric value.";
    return;
  }

  addDataPoint(label, value, "manual");
  formMessageEl.textContent = "Data point added successfully.";

  labelInput.value = "";
  valueInput.value = "";
});
```

