<body>
  <div class="container">
    <h1>Interactive Real-Time Dashboard</h1>

    <div class="grid">
      <div class="card span-12">
        <h2>Overview</h2>
        <div class="stats">
          <div class="stat">
            <div class="stat-label">Current Value</div>
            <div class="stat-value" id="currentValue">0</div>
          </div>
          <div class="stat">
            <div class="stat-label">Average</div>
            <div class="stat-value" id="averageValue">0</div>
          </div>
          <div class="stat">
            <div class="stat-label">Status</div>
            <div class="stat-value" id="systemStatus">OK</div>
          </div>
        </div>
      </div>

      <div class="card span-8">
        <h2>Live Data Chart</h2>
        <canvas id="liveChart"></canvas>
      </div>

      <div class="card span-4">
        <h2>Controls</h2>
        <div class="controls">
          <button id="startBtn">Start Stream</button>
          <button id="stopBtn" class="secondary-btn">Stop Stream</button>
          <button id="resetBtn" class="secondary-btn">Reset Data</button>
        </div>
        <div style="margin-top: 16px;">
          <label for="thresholdInput">Alert Threshold</label>
          <input type="number" id="thresholdInput" value="75" min="0" max="1000" />
        </div>
      </div>

      <div class="card span-4">
        <h2>Submit Event</h2>
        <form id="eventForm">
          <div class="form-row">
            <label for="eventName">Event Name</label>
            <input type="text" id="eventName" name="eventName" placeholder="e.g. Sensor Check" required />
          </div>

          <div class="form-row">
            <label for="eventType">Event Type</label>
            <select id="eventType" name="eventType" required>
              <option value="">Select type</option>
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="critical">Critical</option>
            </select>
          </div>

          <div class="form-row">
            <label for="eventNotes">Notes</label>
            <textarea id="eventNotes" name="eventNotes" rows="4" placeholder="Optional notes"></textarea>
          </div>

          <button type="submit">Submit Event</button>
          <div id="formMessage" class="message"></div>
        </form>
      </div>

      <div class="card span-8">
        <h2>Recent Activity</h2>
        <table class="log-table">
          <thead>
            <tr>
              <th>Time</th>
              <th>Type</th>
              <th>Description</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody id="activityLog"></tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const MAX_POINTS = 20;
    let streamInterval = null;
    let dataPoints = [];
    let labels = [];
    let threshold = 75;

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const systemStatusEl = document.getElementById('systemStatus');
    const thresholdInput = document.getElementById('thresholdInput');
    const activityLog = document.getElementById('activityLog');
    const formMessage = document.getElementById('formMessage');

    const ctx = document.getElementById('liveChart').getContext('2d');
    const liveChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: 'Live Metric',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.2)',
          fill: true,
          tension: 0.3,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#cbd5e1' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#cbd5e1' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    function getTimeLabel() {
      return new Date().toLocaleTimeString();
    }

    function generateValue() {
      return Math.floor(Math.random() * 100);
    }

    function updateStats(value) {
      currentValueEl.textContent = value;

      const avg = dataPoints.length
        ? (dataPoints.reduce((sum, v) => sum + v, 0) / dataPoints.length).toFixed(1)
        : 0;

      averageValueEl.textContent = avg;

      const isAlert = value > threshold;
      systemStatusEl.textContent = isAlert ? 'ALERT' : 'OK';
      systemStatusEl.style.color = isAlert ? '#ef4444' : '#22c55e';
    }

    function addLog(type, description, isAlert = false) {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${getTimeLabel()}</td>
        <td>${type}</td>
        <td>${description}</td>
        <td>
          <span class="badge ${isAlert ? 'badge-alert' : 'badge-ok'}">
            ${isAlert ? 'Alert' : 'Normal'}
          </span>
        </td>
      `;
      activityLog.prepend(row);

      while (activityLog.children.length > 10) {
        activityLog.removeChild(activityLog.lastChild);
      }
    }

    function pushDataPoint() {
      const value = generateValue();
      const label = getTimeLabel();

      dataPoints.push(value);
      labels.push(label);

      if (dataPoints.length > MAX_POINTS) {
        dataPoints.shift();
        labels.shift();
      }

      liveChart.update();
      updateStats(value);

      if (value > threshold) {
        addLog('System', `Metric exceeded threshold with value ${value}`, true);
      } else {
        addLog('System', `Metric updated to ${value}`, false);
      }
    }

    function startStream() {
      if (streamInterval) return;
      pushDataPoint();
      streamInterval = setInterval(pushDataPoint, 1000);
      addLog('Control', 'Data stream started');
    }

    function stopStream() {
      if (!streamInterval) return;
      clearInterval(streamInterval);
      streamInterval = null;
      addLog('Control', 'Data stream stopped');
    }

    function resetData() {
      dataPoints.length = 0;
      labels.length = 0;
      liveChart.update();
      currentValueEl.textContent = '0';
      averageValueEl.textContent = '0';
      systemStatusEl.textContent = 'OK';
      systemStatusEl.style.color = '#22c55e';
      addLog('Control', 'Dashboard data reset');
    }

    document.getElementById('startBtn').addEventListener('click', startStream);
    document.getElementById('stopBtn').addEventListener('click', stopStream);
    document.getElementById('resetBtn').addEventListener('click', resetData);

    thresholdInput.addEventListener('input', (e) => {
      threshold = Number(e.target.value) || 0;
      addLog('Config', `Alert threshold set to ${threshold}`);
    });

    document.getElementById('eventForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const eventName = document.getElementById('eventName').value.trim();
      const eventType = document.getElementById('eventType').value;
      const eventNotes = document.getElementById('eventNotes').value.trim();

      if (!eventName || !eventType) {
        formMessage.textContent = 'Please complete all required fields.';
        formMessage.className = 'message error';
        return;
      }

      addLog(
        eventType.toUpperCase(),
        `${eventName}${eventNotes ? ' - ' + eventNotes : ''}`,
        eventType === 'critical'
      );

      formMessage.textContent = 'Event submitted successfully.';
      formMessage.className = 'message success';

      e.target.reset();
    });

    // Optional initial seed
    for (let i = 0; i < 5; i++) {
      dataPoints.push(generateValue());
      labels.push(getTimeLabel());
    }
    liveChart.update();
    updateStats(dataPoints[dataPoints.length - 1] || 0);
  </script>
</body>
</html>
```

