## 3. `app.js`

```javascript
const maxPoints = 20;
let isStreaming = true;
let dataPoints = [];
let labels = [];
let rules = [];

const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const maxValueEl = document.getElementById("maxValue");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const alertForm = document.getElementById("alertForm");
const formMessage = document.getElementById("formMessage");
const rulesTableBody = document.getElementById("rulesTableBody");

const ctx = document.getElementById("liveChart").getContext("2d");

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Sensor Value",
        data: dataPoints,
        borderColor: "#22c55e",
        backgroundColor: "rgba(34, 197, 94, 0.2)",
        tension: 0.3,
        fill: true
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#334155" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#334155" },
        beginAtZero: true
      }
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    }
  }
});

function generateDataPoint() {
  return Math.floor(Math.random() * 100);
}

function updateDashboard(value) {
  const timeLabel = new Date().toLocaleTimeString();

  labels.push(timeLabel);
  dataPoints.push(value);

  if (labels.length > maxPoints) labels.shift();
  if (dataPoints.length > maxPoints) dataPoints.shift();

  liveChart.update();

  const current = dataPoints[dataPoints.length - 1] || 0;
  const average =
    dataPoints.reduce((sum, point) => sum + point, 0) / (dataPoints.length || 1);
  const max = Math.max(...dataPoints, 0);

  currentValueEl.textContent = current.toFixed(0);
  averageValueEl.textContent = average.toFixed(1);
  maxValueEl.textContent = max.toFixed(0);
}

const streamInterval = setInterval(() => {
  if (!isStreaming) return;
  const newValue = generateDataPoint();
  updateDashboard(newValue);
}, 1000);

toggleStreamBtn.addEventListener("click", () => {
  isStreaming = !isStreaming;
  toggleStreamBtn.textContent = isStreaming ? "Pause" : "Resume";
});

alertForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const ruleName = document.getElementById("ruleName").value.trim();
  const threshold = document.getElementById("threshold").value.trim();
  const severity = document.getElementById("severity").value;

  if (!ruleName || !threshold || !severity) {
    formMessage.textContent = "Please fill in all fields.";
    formMessage.style.color = "#ef4444";
    return;
  }

  const newRule = {
    ruleName,
    threshold,
    severity,
    createdAt: new Date().toLocaleString()
  };

  rules.unshift(newRule);
  renderRules();

  formMessage.textContent = "Alert rule created successfully.";
  formMessage.style.color = "#22c55e";
  alertForm.reset();
});

function renderRules() {
  rulesTableBody.innerHTML = "";

  rules.forEach((rule) => {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${rule.ruleName}</td>
      <td>${rule.threshold}</td>
      <td>${rule.severity}</td>
      <td>${rule.createdAt}</td>
    `;
    rulesTableBody.appendChild(row);
  });
}

// Seed initial data
for (let i = 0; i < 8; i++) {
  updateDashboard(generateDataPoint());
}
