<body>
  <div class="app">
    <aside class="sidebar">
      <div class="brand">LiveDash</div>
      <nav class="nav">
        <a href="#" class="active">Overview</a>
        <a href="#">Analytics</a>
        <a href="#">Events</a>
        <a href="#">Settings</a>
      </nav>
    </aside>

    <main class="main">
      <div class="topbar">
        <div>
          <h1>Operations Dashboard</h1>
          <p style="margin: 6px 0 0; color: var(--muted);">Monitor live metrics and submit updates.</p>
        </div>
        <div class="status">
          <span class="pulse"></span>
          <span>Live stream active</span>
        </div>
      </div>

      <section class="grid">
        <div class="card metric">
          <div class="metric-title">Current Throughput</div>
          <div class="metric-value" id="throughputValue">0</div>
          <div class="metric-sub">units/min</div>
        </div>

        <div class="card metric">
          <div class="metric-title">System Load</div>
          <div class="metric-value" id="loadValue">0%</div>
          <div class="metric-sub">active utilization</div>
        </div>

        <div class="card metric">
          <div class="metric-title">Error Rate</div>
          <div class="metric-value" id="errorValue">0.0%</div>
          <div class="metric-sub">last 60 seconds</div>
        </div>

        <div class="card metric">
          <div class="metric-title">Events Processed</div>
          <div class="metric-value" id="eventsValue">0</div>
          <div class="metric-sub">session total</div>
        </div>

        <div class="card chart-card">
          <h2>Real-Time Throughput</h2>
          <canvas id="chart" width="900" height="320"></canvas>
        </div>

        <div class="card feed-card">
          <h2>Activity Feed</h2>
          <ul class="feed" id="activityFeed"></ul>
        </div>

        <div class="card form-card">
          <h2>Submit Configuration Update</h2>
          <form id="configForm" novalidate>
            <div class="field">
              <label for="operator">Operator Name</label>
              <input id="operator" name="operator" type="text" placeholder="Jane Doe" />
              <div class="error-text" id="operatorError"></div>
            </div>

            <div class="field">
              <label for="threshold">Alert Threshold</label>
              <input id="threshold" name="threshold" type="number" min="1" max="100" placeholder="75" />
              <div class="error-text" id="thresholdError"></div>
            </div>

            <div class="field">
              <label for="mode">Mode</label>
              <select id="mode" name="mode">
                <option value="">Select mode</option>
                <option value="normal">Normal</option>
                <option value="safe">Safe</option>
                <option value="performance">Performance</option>
              </select>
              <div class="error-text" id="modeError"></div>
            </div>

            <div class="field full">
              <label for="notes">Notes</label>
              <textarea id="notes" name="notes" placeholder="Add context for this update..."></textarea>
              <div class="error-text" id="notesError"></div>
            </div>

            <div class="actions">
              <button type="submit">Submit Update</button>
              <button type="button" class="secondary" id="resetBtn">Reset</button>
              <div id="formMessage" class="message"></div>
            </div>
          </form>
        </div>
      </section>
    </main>
  </div>

  <script>
    const state = {
      throughputData: [],
      maxPoints: 40,
      eventsProcessed: 0,
      threshold: 75,
      mode: "normal"
    };

    const throughputValue = document.getElementById("throughputValue");
    const loadValue = document.getElementById("loadValue");
    const errorValue = document.getElementById("errorValue");
    const eventsValue = document.getElementById("eventsValue");
    const activityFeed = document.getElementById("activityFeed");
    const chart = document.getElementById("chart");
    const ctx = chart.getContext("2d");

    const form = document.getElementById("configForm");
    const resetBtn = document.getElementById("resetBtn");
    const formMessage = document.getElementById("formMessage");

    const fields = {
      operator: document.getElementById("operator"),
      threshold: document.getElementById("threshold"),
      mode: document.getElementById("mode"),
      notes: document.getElementById("notes")
    };

    const errors = {
      operator: document.getElementById("operatorError"),
      threshold: document.getElementById("thresholdError"),
      mode: document.getElementById("modeError"),
      notes: document.getElementById("notesError")
    };

    function addFeedItem(message) {
      const li = document.createElement("li");
      li.innerHTML = `
        <div>${message}</div>
        <span class="feed-time">${new Date().toLocaleTimeString()}</span>
      `;
      activityFeed.prepend(li);

      while (activityFeed.children.length > 12) {
        activityFeed.removeChild(activityFeed.lastChild);
      }
    }

    function generateDataPoint() {
      const last = state.throughputData.length
        ? state.throughputData[state.throughputData.length - 1]
        : 55;

      let next = last + (Math.random() * 16 - 8);

      if (state.mode === "safe") next -= 4;
      if (state.mode === "performance") next += 6;

      next = Math.max(10, Math.min(100, Math.round(next)));

      const load = Math.max(20, Math.min(100, Math.round(next + (Math.random() * 10 - 5))));
      const errorRate = Math.max(0, Math.min(12, +(Math.random() * (next > state.threshold ? 4 : 2)).toFixed(1)));

      state.throughputData.push(next);
      if (state.throughputData.length > state.maxPoints) {
        state.throughputData.shift();
      }

      state.eventsProcessed += Math.floor(Math.random() * 8) + 1;

      throughputValue.textContent = next;
      loadValue.textContent = load + "%";
      errorValue.textContent = errorRate.toFixed(1) + "%";
      eventsValue.textContent = state.eventsProcessed;

      if (next > state.threshold) {
        addFeedItem(`⚠️ Throughput exceeded threshold (${next} > ${state.threshold})`);
      } else if (Math.random() > 0.7) {
        addFeedItem(`✅ Stable update received: throughput ${next}, load ${load}%`);
      }

      drawChart();
    }

    function drawChart() {
      const width = chart.width;
      const height = chart.height;
      ctx.clearRect(0, 0, width, height);

      const padding = 30;
      const innerWidth = width - padding * 2;
      const innerHeight = height - padding * 2;

      ctx.strokeStyle = "rgba(148, 163, 184, 0.25)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + (innerHeight / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 3;
      ctx.beginPath();

      state.throughputData.forEach((value, index) => {
        const x = padding + (index / Math.max(state.maxPoints - 1, 1)) * innerWidth;
        const y = padding + innerHeight - (value / 100) * innerHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.lineTo(width - padding, height - padding);
      ctx.lineTo(padding, height - padding);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, padding, 0, height - padding);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      ctx.fillStyle = "rgba(148, 163, 184, 0.8)";
      ctx.font = "12px sans-serif";
      ctx.fillText("100", 6, padding + 4);
      ctx.fillText("50", 12, padding + innerHeight / 2 + 4);
      ctx.fillText("0", 18, height - padding + 4);
    }

    function clearErrors() {
      Object.values(errors).forEach(el => el.textContent = "");
      formMessage.textContent = "";
      formMessage.className = "message";
    }

    function validateForm() {
      clearErrors();
      let valid = true;

      const operator = fields.operator.value.trim();
      const threshold = fields.threshold.value.trim();
      const mode = fields.mode.value;
      const notes = fields.notes.value.trim();

      if (!operator || operator.length < 2) {
        errors.operator.textContent = "Please enter an operator name with at least 2 characters.";
        valid = false;
      }

      const thresholdNum = Number(threshold);
      if (!threshold || Number.isNaN(thresholdNum) || thresholdNum < 1 || thresholdNum > 100) {
        errors.threshold.textContent = "Threshold must be a number between 1 and 100.";
        valid = false;
      }

      if (!mode) {
        errors.mode.textContent = "Please select a mode.";
        valid = false;
      }

      if (notes.length > 0 && notes.length < 5) {
        errors.notes.textContent = "Notes must be at least 5 characters if provided.";
        valid = false;
      }

      return valid;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) {
        formMessage.textContent = "Please fix the highlighted errors.";
        formMessage.className = "message error";
        return;
      }

      const payload = {
        operator: fields.operator.value.trim(),
        threshold: Number(fields.threshold.value),
        mode: fields.mode.value,
        notes: fields.notes.value.trim(),
        submittedAt: new Date().toISOString()
      };

      state.threshold = payload.threshold;
      state.mode = payload.mode;

      addFeedItem(`🛠️ Config updated by ${payload.operator}: mode=${payload.mode}, threshold=${payload.threshold}`);
      formMessage.textContent = "Configuration submitted successfully.";
      formMessage.className = "message success";

      console.log("Submitted payload:", payload);
    });

    resetBtn.addEventListener("click", () => {
      form.reset();
      clearErrors();
      formMessage.textContent = "Form reset.";
      formMessage.className = "message";
    });

    function seedInitialData() {
      for (let i = 0; i < state.maxPoints; i++) {
        const value = 45 + Math.round(Math.random() * 20);
        state.throughputData.push(value);
      }
      drawChart();
      throughputValue.textContent = state.throughputData[state.throughputData.length - 1];
      loadValue.textContent = "58%";
      errorValue.textContent = "1.2%";
      eventsValue.textContent = state.eventsProcessed;
      addFeedItem("🚀 Dashboard initialized");
      addFeedItem("📡 Awaiting live updates");
    }

    seedInitialData();
    setInterval(generateDataPoint, 1200);
  </script>
</body>
</html>
```

---

## Features included

### 1. Real-time visualization
- Simulated live metric updates every `1.2s`
- Canvas-based line chart
- Live metric cards for:
  - Throughput
  - System load
  - Error rate
  - Events processed

### 2. Activity feed
- New events are added automatically
- Threshold exceedance generates alerts
- Configuration submissions appear in the feed

### 3. Form handling
- Operator name validation
- Threshold numeric validation
- Mode selection validation
- Optional notes validation
- Success/error messaging
- Reset support

### 4. Responsive UI
- Sidebar + main content on desktop
- Stacked layout on mobile/tablet

