    </aside>

    <main class="main">
      <div class="topbar">
        <h1>Real-Time Operations Dashboard</h1>
        <div class="controls">
          <button class="btn-success" id="startBtn">Start</button>
          <button class="btn-warning" id="stopBtn">Stop</button>
          <button class="btn-danger" id="resetBtn">Reset</button>
        </div>
      </div>

      <section class="grid">
        <div class="kpis">
          <div class="card kpi">
            <h3>Current Value</h3>
            <div class="value" id="currentValue">0</div>
            <div class="sub">Latest incoming metric</div>
          </div>
          <div class="card kpi">
            <h3>Average</h3>
            <div class="value" id="averageValue">0</div>
            <div class="sub">Rolling average</div>
          </div>
          <div class="card kpi">
            <h3>Peak</h3>
            <div class="value" id="peakValue">0</div>
            <div class="sub">Highest observed value</div>
          </div>
          <div class="card kpi">
            <h3>Events</h3>
            <div class="value" id="eventCount">0</div>
            <div class="sub">Logged dashboard actions</div>
          </div>
        </div>

        <div class="card chart-card">
          <div class="card-header">
            <h2>Live Metric Stream</h2>
            <span id="statusLabel">Status: Running</span>
          </div>
          <canvas id="chart" width="900" height="320"></canvas>
        </div>

        <div class="card form-card">
          <div class="card-header">
            <h2>Submit Configuration</h2>
          </div>
          <form id="configForm">
            <div class="field">
              <label for="operatorName">Operator Name</label>
              <input type="text" id="operatorName" name="operatorName" placeholder="Enter your name" required />
            </div>

            <div class="field">
              <label for="threshold">Alert Threshold</label>
              <input type="number" id="threshold" name="threshold" min="0" max="100" value="75" required />
            </div>

            <div class="field">
              <label for="mode">Mode</label>
              <select id="mode" name="mode">
                <option value="normal">Normal</option>
                <option value="sensitive">Sensitive</option>
                <option value="performance">Performance</option>
              </select>
            </div>

            <div class="field">
              <label for="notes">Notes</label>
              <textarea id="notes" name="notes" rows="4" placeholder="Optional notes"></textarea>
            </div>

            <div class="form-actions">
              <button type="submit" class="btn-primary">Save Settings</button>
              <button type="button" class="btn-warning" id="fillDemoBtn">Fill Demo</button>
            </div>
          </form>
          <div id="formMessage" class="message"></div>
        </div>

        <div class="card log-card">
          <div class="card-header">
            <h2>Event Log</h2>
          </div>
