  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const statusLabel = document.getElementById('statusLabel');
    const logList = document.getElementById('logList');
    const formMessage = document.getElementById('formMessage');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const resetBtn = document.getElementById('resetBtn');
    const fillDemoBtn = document.getElementById('fillDemoBtn');
    const configForm = document.getElementById('configForm');

    let data = [];
    let maxPoints = 50;
    let timer = null;
    let eventCount = 0;
    let threshold = 75;

    function randomMetric() {
      const base = 40 + Math.random() * 40;
      const spike = Math.random() > 0.9 ? Math.random() * 25 : 0;
      return Math.min(100, Math.round(base + spike));
    }

    function addLog(message) {
      eventCount++;
      eventCountEl.textContent = eventCount;

      const li = document.createElement('li');
      li.className = 'log-item';
      li.innerHTML = `<span class="log-time">${new Date().toLocaleTimeString()}</span>${message}`;
      logList.prepend(li);

      while (logList.children.length > 20) {
        logList.removeChild(logList.lastChild);
      }
    }

    function updateKPIs() {
      if (data.length === 0) {
        currentValueEl.textContent = '0';
        averageValueEl.textContent = '0';
        peakValueEl.textContent = '0';
        return;
      }

      const current = data[data.length - 1];
      const avg = data.reduce((sum, v) => sum + v, 0) / data.length;
      const peak = Math.max(...data);

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak.toFixed(0);
    }

    function drawChart() {
      const width = chartCanvas.width;
      const height = chartCanvas.height;

      ctx.clearRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.15)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // Threshold line
      const thresholdY = height - (threshold / 100) * height;
      ctx.strokeStyle = 'rgba(245, 158, 11, 0.8)';
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(0, thresholdY);
      ctx.lineTo(width, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      if (data.length < 2) return;

      // Area fill
      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(59, 130, 246, 0.35)');
      gradient.addColorStop(1, 'rgba(59, 130, 246, 0.02)');

      ctx.beginPath();
      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * width;
        const y = height - (value / 100) * height;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(width, height);
      ctx.lineTo(0, height);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * width;
        const y = height - (value / 100) * height;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * width;
        const y = height - (value / 100) * height;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = value >= threshold ? '#f59e0b' : '#22c55e';
        ctx.fill();
      });
    }

    function tick() {
      const value = randomMetric();
      data.push(value);

      if (data.length > maxPoints) {
        data.shift();
      }

      updateKPIs();
      drawChart();

      if (value >= threshold) {
        addLog(`Alert: metric exceeded threshold with value <strong>${value}</strong>.`);
      }
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(tick, 1000);
      statusLabel.textContent = 'Status: Running';
      addLog('Data stream started.');
    }

    function stopStream() {
      if (!timer) return;
      clearInterval(timer);
      timer = null;
      statusLabel.textContent = 'Status: Stopped';
      addLog('Data stream stopped.');
    }

    function resetDashboard() {
      stopStream();
      data = [];
      updateKPIs();
      drawChart();
      addLog('Dashboard reset.');
    }

    configForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(configForm);
      const operatorName = formData.get('operatorName').trim();
      const newThreshold = Number(formData.get('threshold'));
      const mode = formData.get('mode');
      const notes = formData.get('notes').trim();

      if (!operatorName) {
        formMessage.className = 'message error';
        formMessage.textContent = 'Operator name is required.';
        return;
      }

      if (Number.isNaN(newThreshold) || newThreshold < 0 || newThreshold > 100) {
        formMessage.className = 'message error';
        formMessage.textContent = 'Threshold must be between 0 and 100.';
        return;
      }

      threshold = newThreshold;
      drawChart();

      formMessage.className = 'message success';
      formMessage.textContent = 'Configuration saved successfully.';

      addLog(
        `Configuration updated by <strong>${operatorName}</strong> — threshold: <strong>${threshold}</strong>, mode: <strong>${mode}</strong>${notes ? `, notes: "${notes}"` : ''}.`
      );
    });

    fillDemoBtn.addEventListener('click', () => {
      document.getElementById('operatorName').value = 'Alex Morgan';
      document.getElementById('threshold').value = '68';
      document.getElementById('mode').value = 'sensitive';
      document.getElementById('notes').value = 'Monitoring elevated activity during test run.';
      formMessage.className = 'message';
      formMessage.textContent = '';
      addLog('Demo form values inserted.');
    });

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);
    resetBtn.addEventListener('click', resetDashboard);

    // Initial seed data
    for (let i = 0; i < 20; i++) {
      data.push(randomMetric());
    }
    updateKPIs();
    drawChart();
    startStream();
  </script>
</body>
</html>
```

