# 3) `app.js`

```javascript
const MAX_POINTS = 20;

const labels = [];
const dataPoints = [];

const currentValueEl = document.getElementById('currentValue');
const averageValueEl = document.getElementById('averageValue');
const entryCountEl = document.getElementById('entryCount');
const form = document.getElementById('dataForm');
const labelInput = document.getElementById('labelInput');
const valueInput = document.getElementById('valueInput');
const resetBtn = document.getElementById('resetBtn');
const formMessage = document.getElementById('formMessage');

const ctx = document.getElementById('lineChart').getContext('2d');

const lineChart = new Chart(ctx, {
  type: 'line',
  data: {
    labels,
    datasets: [
      {
        label: 'Metric Value',
        data: dataPoints,
        borderColor: '#3b82f6',
        backgroundColor: 'rgba(59, 130, 246, 0.2)',
        fill: true,
        tension: 0.3,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: '#e5e7eb'
        }
      }
    },
    scales: {
      x: {
        ticks: {
          color: '#94a3b8'
        },
        grid: {
          color: '#334155'
        }
      },
      y: {
        ticks: {
          color: '#94a3b8'
        },
        grid: {
          color: '#334155'
        },
        beginAtZero: true
      }
    }
  }
});

function updateStats() {
  const count = dataPoints.length;
  const current = count ? dataPoints[count - 1] : 0;
  const average = count
    ? (dataPoints.reduce((sum, value) => sum + value, 0) / count).toFixed(2)
    : 0;

  currentValueEl.textContent = current;
  averageValueEl.textContent = average;
  entryCountEl.textContent = count;
}

function addDataPoint(label, value) {
  labels.push(label);
  dataPoints.push(value);

  if (labels.length > MAX_POINTS) {
    labels.shift();
    dataPoints.shift();
  }

  lineChart.update();
  updateStats();
}

function getCurrentTimeLabel() {
  return new Date().toLocaleTimeString();
}

function generateRandomValue() {
  return Math.floor(Math.random() * 100);
}

function simulateLiveData() {
  const label = getCurrentTimeLabel();
  const value = generateRandomValue();
  addDataPoint(label, value);
}

form.addEventListener('submit', (event) => {
  event.preventDefault();

  const label = labelInput.value.trim();
  const value = Number(valueInput.value);

  if (!label) {
    formMessage.textContent = 'Label is required.';
    formMessage.style.color = '#ef4444';
    return;
  }

  if (Number.isNaN(value)) {
    formMessage.textContent = 'Value must be a valid number.';
    formMessage.style.color = '#ef4444';
    return;
  }

  addDataPoint(label, value);
  formMessage.textContent = `Added data point: ${label} → ${value}`;
  formMessage.style.color = '#22c55e';
  form.reset();
});

resetBtn.addEventListener('click', () => {
  labels.length = 0;
  dataPoints.length = 0;
  lineChart.update();
  updateStats();
  formMessage.textContent = 'Dashboard data reset.';
  formMessage.style.color = '#94a3b8';
});

for (let i = 0; i < 5; i++) {
  simulateLiveData();
}

setInterval(simulateLiveData, 2000);
```

