## `app.js`

```javascript
const MAX_POINTS = 20;
const FEED_INTERVAL_MS = 1500;

const chartLabels = [];
const chartData = [];
const records = [];

let feedRunning = true;
let feedIntervalId = null;

const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const entryCountEl = document.getElementById("entryCount");
const recordsTableBody = document.getElementById("recordsTableBody");
const form = document.getElementById("recordForm");
const formMessage = document.getElementById("formMessage");
const toggleFeedBtn = document.getElementById("toggleFeedBtn");
const clearTableBtn = document.getElementById("clearTableBtn");
const connectionStatus = document.getElementById("connectionStatus");

const ctx = document.getElementById("liveChart").getContext("2d");

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels: chartLabels,
    datasets: [
      {
        label: "Throughput",
        data: chartData,
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59, 130, 246, 0.2)",
        fill: true,
        tension: 0.3,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      },
      y: {
        beginAtZero: true,
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      }
    }
  }
});

function getTimeLabel() {
  return new Date().toLocaleTimeString();
}

function generateMetric() {
  return Math.floor(Math.random() * 100) + 1;
}

function pushChartPoint(value) {
  chartLabels.push(getTimeLabel());
  chartData.push(value);

  if (chartLabels.length > MAX_POINTS) {
    chartLabels.shift();
    chartData.shift();
  }

  liveChart.update();
  updateSummary();
}

function updateSummary() {
  const count = chartData.length;
  const current = count ? chartData[count - 1] : 0;
  const average = count
    ? (chartData.reduce((sum, value) => sum + value, 0) / count).toFixed(1)
    : 0;

  currentValueEl.textContent = current;
  averageValueEl.textContent = average;
  entryCountEl.textContent = records.length;
}

function addRecordToTable(record) {
  const row = document.createElement("tr");

  row.innerHTML = `
    <td>${record.time}</td>
    <td>${record.name}</td>
    <td>${record.category}</td>
    <td>${record.value}</td>
  `;

  recordsTableBody.prepend(row);

  while (recordsTableBody.children.length > 10) {
    recordsTableBody.removeChild(recordsTableBody.lastChild);
  }
}

function addRecord(record) {
  records.push(record);
  addRecordToTable(record);
  updateSummary();
}

function startFeed() {
  if (feedIntervalId) return;

  feedIntervalId = setInterval(() => {
    const value = generateMetric();
    pushChartPoint(value);
  }, FEED_INTERVAL_MS);

  connectionStatus.textContent = "Live";
  toggleFeedBtn.textContent = "Pause Feed";
}

function stopFeed() {
  clearInterval(feedIntervalId);
  feedIntervalId = null;
  connectionStatus.textContent = "Paused";
  toggleFeedBtn.textContent = "Resume Feed";
}

toggleFeedBtn.addEventListener("click", () => {
  feedRunning = !feedRunning;

  if (feedRunning) {
    startFeed();
  } else {
    stopFeed();
  }
});

clearTableBtn.addEventListener("click", () => {
  records.length = 0;
  recordsTableBody.innerHTML = "";
  updateSummary();
  formMessage.textContent = "Records cleared.";
});

form.addEventListener("submit", (event) => {
  event.preventDefault();

  const formData = new FormData(form);
  const name = formData.get("name").trim();
  const category = formData.get("category");
  const value = Number(formData.get("value"));

  if (!name || !category || Number.isNaN(value) || value < 0) {
    formMessage.textContent = "Please enter valid form values.";
    return;
  }

  const record = {
    time: getTimeLabel(),
    name,
    category,
    value
  };

  addRecord(record);
  form.reset();
  formMessage.textContent = `Record "${name}" added successfully.`;
});

function seedInitialData() {
  for (let i = 0; i < 8; i++) {
    pushChartPoint(generateMetric());
  }

  [
    { name: "API Node A", category: "System", value: 42 },
    { name: "Q2 Pipeline", category: "Sales", value: 67 },
    { name: "Ticket Batch", category: "Support", value: 18 }
  ].forEach((item) => {
    addRecord({
      time: getTimeLabel(),
      ...item
    });
  });
}

seedInitialData();
startFeed();
