  <script>
    const maxPoints = 20;
    let feedRunning = true;

    const state = {
      metrics: {
        activeUsers: 128,
        transactions: 842,
        errorRate: 1.2,
        systemHealth: 98
      },
      chartMode: 'throughput',
      throughputData: [],
      latencyData: [],
      labels: [],
      events: []
    };

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function randomInt(min, max) {
      return Math.floor(randomBetween(min, max + 1));
    }

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function seedChartData() {
      for (let i = maxPoints; i > 0; i--) {
        const date = new Date(Date.now() - i * 2000);
        state.labels.push(date.toLocaleTimeString());
        state.throughputData.push(randomInt(40, 100));
        state.latencyData.push(randomInt(120, 300));
      }
    }

    seedChartData();

    const ctx = document.getElementById('realtimeChart').getContext('2d');

    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: state.labels,
        datasets: [{
          label: 'Throughput',
          data: state.throughputData,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 2,
          pointHoverRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.08)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.08)' }
          }
        }
      }
    });

    function updateChart() {
      const mode = state.chartMode;
      realtimeChart.data.labels = state.labels;
      realtimeChart.data.datasets[0].label = mode === 'throughput' ? 'Throughput' : 'Latency';
      realtimeChart.data.datasets[0].data = mode === 'throughput' ? state.throughputData : state.latencyData;
      realtimeChart.data.datasets[0].borderColor = mode === 'throughput' ? '#38bdf8' : '#22c55e';
      realtimeChart.data.datasets[0].backgroundColor = mode === 'throughput'
        ? 'rgba(56, 189, 248, 0.2)'
        : 'rgba(34, 197, 94, 0.2)';
      realtimeChart.update();
    }

    function updateStats() {
      document.getElementById('activeUsers').textContent = state.metrics.activeUsers;
      document.getElementById('transactions').textContent = state.metrics.transactions;
      document.getElementById('errorRate').textContent = state.metrics.errorRate.toFixed(1) + '%';
      document.getElementById('systemHealth').textContent = Math.round(state.metrics.systemHealth) + '%';

      document.getElementById('usersTrend').textContent =
        `${state.metrics.activeUsers > 120 ? '+' : '-'}${randomBetween(1, 5).toFixed(1)}% this hour`;

      document.getElementById('transactionsTrend').textContent =
        `+${randomBetween(1, 4).toFixed(1)}% today`;

      document.getElementById('errorTrend').textContent =
        `${state.metrics.errorRate < 2 ? '-' : '+'}${randomBetween(0.1, 0.6).toFixed(1)}% from baseline`;

      document.getElementById('healthTrend').textContent =
        state.metrics.systemHealth > 95 ? 'Stable' : 'Attention needed';
    }

    function addEvent(event) {
      state.events.unshift(event);
      state.events = state.events.slice(0, 10);
      renderEvents();
    }

    function renderEvents() {
      const tbody = document.getElementById('eventsTableBody');
      tbody.innerHTML = '';

      state.events.forEach(evt => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${evt.time}</td>
          <td>${evt.name}</td>
          <td><span class="badge ${evt.type}">${evt.type}</span></td>
          <td>${evt.value}</td>
          <td>${evt.notes || '-'}</td>
        `;
        tbody.appendChild(tr);
      });
    }

    function simulateTick() {
      if (!feedRunning) return;

      state.labels.push(nowTime());
      state.throughputData.push(randomInt(50, 110));
      state.latencyData.push(randomInt(100, 320));

      if (state.labels.length > maxPoints) {
        state.labels.shift();
        state.throughputData.shift();
        state.latencyData.shift();
      }

      state.metrics.activeUsers = Math.max(80, state.metrics.activeUsers + randomInt(-5, 7));
      state.metrics.transactions += randomInt(1, 12);
      state.metrics.errorRate = Math.max(0.2, Math.min(4.5, state.metrics.errorRate + randomBetween(-0.2, 0.2)));
      state.metrics.systemHealth = Math.max(85, Math.min(100, state.metrics.systemHealth + randomBetween(-1, 1)));

      updateStats();
      updateChart();
    }

    function showFormMessage(text, type) {
      const msg = document.getElementById('formMessage');
      msg.className = `message ${type}`;
      msg.textContent = text;
    }

    document.getElementById('chartMode').addEventListener('change', (e) => {
      state.chartMode = e.target.value;
      updateChart();
    });

    document.getElementById('toggleFeedBtn').addEventListener('click', () => {
      feedRunning = !feedRunning;
      document.getElementById('toggleFeedBtn').textContent = feedRunning ? 'Pause Feed' : 'Resume Feed';
    });

    document.getElementById('addRandomBtn').addEventListener('click', () => {
      const types = ['info', 'success', 'warn'];
      const names = ['Order Received', 'Payment Processed', 'API Warning', 'User Login', 'Sync Completed'];

      const event = {
        time: nowTime(),
        name: names[randomInt(0, names.length - 1)],
        type: types[randomInt(0, types.length - 1)],
        value: randomInt(10, 500),
        notes: 'Generated automatically'
      };

      addEvent(event);
      state.metrics.transactions += randomInt(2, 8);
      updateStats();
    });

    document.getElementById('eventForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('eventName').value.trim();
      const type = document.getElementById('eventType').value;
      const value = document.getElementById('eventValue').value;
      const notes = document.getElementById('eventNotes').value.trim();

      if (!name || !type || value === '') {
        showFormMessage('Please fill in all required fields.', 'error');
        return;
      }

      const event = {
        time: nowTime(),
        name,
        type,
        value: Number(value),
        notes
      };

      addEvent(event);

      state.metrics.transactions += Number(value) > 0 ? 1 : 0;
      state.metrics.activeUsers += type === 'success' ? 1 : 0;
      state.metrics.errorRate = type === 'warn'
        ? Math.min(5, state.metrics.errorRate + 0.1)
        : Math.max(0.1, state.metrics.errorRate - 0.05);

      updateStats();
      showFormMessage('Event submitted successfully.', 'success');
      e.target.reset();
    });

    addEvent({
      time: nowTime(),
      name: 'System Boot',
      type: 'info',
      value: 1,
      notes: 'Dashboard initialized'
    });

    addEvent({
      time: nowTime(),
      name: 'Initial Sync',
      type: 'success',
      value: 24,
      notes: 'Connected to mock stream'
    });

    updateStats();
    updateChart();

    setInterval(simulateTick, 2000);
  </script>
</body>
</html>
```

