<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Operations Dashboard</h1>
        <p>Interactive browser dashboard with live metrics, charting, and form submission.</p>
      </div>
      <div class="controls">
        <button id="toggleFeedBtn" class="primary">Pause Feed</button>
