        <div id="errorTrend" class="metric-trend down">0%</div>
      </div>

      <div class="card metric-card">
        <div class="metric-label">Submissions</div>
        <div id="submissionCount" class="metric-value">0</div>
        <div class="metric-trend">Manual entries logged</div>
      </div>

