        <h2>Submit Incident</h2>
        <form id="incidentForm" novalidate>
          <div class="field">
            <label for="title">Title</label>
            <input id="title" name="title" type="text" placeholder="Enter incident title" />
            <div class="error" id="titleError"></div>
          </div>

          <div class="field">
            <label for="severity">Severity</label>
            <select id="severity" name="severity">
              <option value="">Select severity</option>
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
            </select>
            <div class="error" id="severityError"></div>
          </div>

          <div class="field">
            <label for="owner">Owner</label>
            <input id="owner" name="owner" type="text" placeholder="Assigned owner" />
            <div class="error" id="ownerError"></div>
          </div>

          <div class="field">
            <label for="description">Description</label>
            <textarea id="description" name="description" rows="4" placeholder="Describe the issue"></textarea>
            <div class="error" id="descriptionError"></div>
          </div>

          <button type="submit" class="primary">Submit Record</button>
          <div id="formStatus" class="success"></div>
        </form>
      </div>

      <div class="card table-card">
        <h2>Submitted Records</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Title</th>
              <th>Severity</th>
              <th>Owner</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody id="recordsTableBody"></tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const state = {
      feedRunning: true,
      throughputHistory: [],
      labels: [],
      records: [],
      metrics: {
        throughput: 120,
        sessions: 42,
        errorRate: 1.2
      }
    };

    const maxPoints = 20;

    const els = {
      throughputValue: document.getElementById('throughputValue'),
      throughputTrend: document.getElementById('throughputTrend'),
      sessionsValue: document.getElementById('sessionsValue'),
      sessionsTrend: document.getElementById('sessionsTrend'),
      errorValue: document.getElementById('errorValue'),
      errorTrend: document.getElementById('errorTrend'),
      submissionCount: document.getElementById('submissionCount'),
      logList: document.getElementById('logList'),
      toggleFeedBtn: document.getElementById('toggleFeedBtn'),
      addRandomBtn: document.getElementById('addRandomBtn'),
      incidentForm: document.getElementById('incidentForm'),
      formStatus: document.getElementById('formStatus'),
      recordsTableBody: document.getElementById('recordsTableBody')
    };

    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [
          {
            label: 'Throughput',
            data: [],
            borderColor: '#3b82f6',
            backgroundColor: 'rgba(59,130,246,0.15)',
            fill: true,
            tension: 0.35,
            pointRadius: 2
          },
          {
            label: 'Sessions',
            data: [],
            borderColor: '#22c55e',
            backgroundColor: 'rgba(34,197,94,0.15)',
            fill: false,
            tension: 0.35,
            pointRadius: 2
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          }
        }
      }
    });

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function clamp(num, min, max) {
      return Math.min(Math.max(num, min), max);
    }

    function randomDelta(range) {
      return (Math.random() * range * 2) - range;
    }

    function addLog(message) {
      const li = document.createElement('li');
      li.className = 'log-item';
      li.innerHTML = `<span class="log-time">${formatTime()}</span>${message}`;
      els.logList.prepend(li);

      while (els.logList.children.length > 12) {
        els.logList.removeChild(els.logList.lastChild);
      }
    }

    function updateMetrics() {
      const prevThroughput = state.metrics.throughput;
      const prevSessions = state.metrics.sessions;
      const prevError = state.metrics.errorRate;

      state.metrics.throughput = Math.round(clamp(prevThroughput + randomDelta(12), 80, 220));
      state.metrics.sessions = Math.round(clamp(prevSessions + randomDelta(5), 20, 100));
      state.metrics.errorRate = Number(clamp(prevError + randomDelta(0.4), 0.1, 8).toFixed(1));

      const throughputTrend = (((state.metrics.throughput - prevThroughput) / prevThroughput) * 100).toFixed(1);
      const sessionsTrend = (((state.metrics.sessions - prevSessions) / prevSessions) * 100).toFixed(1);
      const errorTrend = (state.metrics.errorRate - prevError).toFixed(1);

      els.throughputValue.textContent = state.metrics.throughput;
      els.sessionsValue.textContent = state.metrics.sessions;
      els.errorValue.textContent = `${state.metrics.errorRate}%`;

      els.throughputTrend.textContent = `${throughputTrend > 0 ? '+' : ''}${throughputTrend}%`;
      els.throughputTrend.className = `metric-trend ${throughputTrend >= 0 ? 'up' : 'down'}`;

      els.sessionsTrend.textContent = `${sessionsTrend > 0 ? '+' : ''}${sessionsTrend}%`;
      els.sessionsTrend.className = `metric-trend ${sessionsTrend >= 0 ? 'up' : 'down'}`;

      els.errorTrend.textContent = `${errorTrend > 0 ? '+' : ''}${errorTrend}%`;
      els.errorTrend.className = `metric-trend ${errorTrend <= 0 ? 'up' : 'down'}`;
    }

    function updateChart() {
      const label = formatTime();
      realtimeChart.data.labels.push(label);
      realtimeChart.data.datasets[0].data.push(state.metrics.throughput);
      realtimeChart.data.datasets[1].data.push(state.metrics.sessions);

      if (realtimeChart.data.labels.length > maxPoints) {
        realtimeChart.data.labels.shift();
        realtimeChart.data.datasets[0].data.shift();
        realtimeChart.data.datasets[1].data.shift();
      }

      realtimeChart.update();
    }

    function tick() {
      if (!state.feedRunning) return;
      updateMetrics();
      updateChart();

      if (Math.random() > 0.7) {
        addLog(`System heartbeat: throughput ${state.metrics.throughput}, sessions ${state.metrics.sessions}, error ${state.metrics.errorRate}%`);
      }
    }

    function severityBadge(severity) {
      const map = {
        Low: 'badge badge-low',
        Medium: 'badge badge-medium',
        High: 'badge badge-high'
      };
      return `<span class="${map[severity] || 'badge'}">${severity}</span>`;
    }

    function renderRecords() {
      els.recordsTableBody.innerHTML = '';

      state.records.slice().reverse().forEach(record => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${record.time}</td>
          <td>${record.title}</td>
          <td>${severityBadge(record.severity)}</td>
          <td>${record.owner}</td>
          <td>${record.description}</td>
        `;
        els.recordsTableBody.appendChild(tr);
      });

      els.submissionCount.textContent = state.records.length;
    }

    function clearErrors() {
      ['title', 'severity', 'owner', 'description'].forEach(field => {
        document.getElementById(field + 'Error').textContent = '';
      });
      els.formStatus.textContent = '';
    }

    function validateForm(data) {
      const errors = {};

      if (!data.title.trim()) errors.title = 'Title is required.';
      if (!data.severity.trim()) errors.severity = 'Severity is required.';
      if (!data.owner.trim()) errors.owner = 'Owner is required.';
      if (!data.description.trim()) errors.description = 'Description is required.';
      if (data.description.trim().length > 0 && data.description.trim().length < 10) {
        errors.description = 'Description must be at least 10 characters.';
      }

      return errors;
    }

    function showErrors(errors) {
      Object.entries(errors).forEach(([key, value]) => {
        document.getElementById(key + 'Error').textContent = value;
      });
    }

    function handleFormSubmit(event) {
      event.preventDefault();
      clearErrors();

      const formData = new FormData(els.incidentForm);
      const data = {
        title: formData.get('title') || '',
        severity: formData.get('severity') || '',
        owner: formData.get('owner') || '',
        description: formData.get('description') || ''
      };

      const errors = validateForm(data);
      if (Object.keys(errors).length > 0) {
        showErrors(errors);
        addLog('Form validation failed for incident submission.');
        return;
      }

      const record = {
        ...data,
        time: formatTime()
      };

      state.records.push(record);
      renderRecords();
      els.incidentForm.reset();
      els.formStatus.textContent = 'Record submitted successfully.';
      addLog(`New ${record.severity.toLowerCase()} severity incident submitted by ${record.owner}.`);
    }

    function addRandomRecord() {
      const severities = ['Low', 'Medium', 'High'];
      const titles = ['Latency spike', 'API timeout', 'Database warning', 'Queue backlog', 'Memory pressure'];
      const owners = ['Alex', 'Jordan', 'Sam', 'Taylor', 'Morgan'];
      const descriptions = [
        'Observed elevated latency in the service layer.',
        'Intermittent timeout errors detected on public API routes.',
        'Background jobs are accumulating faster than expected.',
        'Memory utilization increased above normal operating threshold.',
        'A downstream dependency is responding slower than baseline.'
      ];

      const record = {
        time: formatTime(),
        title: titles[Math.floor(Math.random() * titles.length)],
        severity: severities[Math.floor(Math.random() * severities.length)],
        owner: owners[Math.floor(Math.random() * owners.length)],
        description: descriptions[Math.floor(Math.random() * descriptions.length)]
      };

      state.records.push(record);
      renderRecords();
      addLog(`Random record added: ${record.title} (${record.severity}).`);
    }

    els.toggleFeedBtn.addEventListener('click', () => {
      state.feedRunning = !state.feedRunning;
      els.toggleFeedBtn.textContent = state.feedRunning ? 'Pause Feed' : 'Resume Feed';
      addLog(state.feedRunning ? 'Real-time feed resumed.' : 'Real-time feed paused.');
    });

    els.addRandomBtn.addEventListener('click', addRandomRecord);
    els.incidentForm.addEventListener('submit', handleFormSubmit);

    updateMetrics();
    updateChart();
    renderRecords();
    addLog('Dashboard initialized.');

    setInterval(tick, 1000);
  </script>
</body>
</html>
