  <script>
    const MAX_POINTS = 20;
    const UPDATE_INTERVAL_MS = 1500;

    const state = {
      points: [],
      labels: [],
      submittedEvents: [],
      currentValue: 0,
      peakValue: 0
    };

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const eventCountEl = document.getElementById('eventCount');
    const currentTrendEl = document.getElementById('currentTrend');
    const activityLogEl = document.getElementById('activityLog');
    const formMessageEl = document.getElementById('formMessage');
    const eventForm = document.getElementById('eventForm');

    const ctx = document.getElementById('liveChart').getContext('2d');

    const liveChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Metric Value',
          data: [],
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.2)',
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: '#7dd3fc',
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: {
          duration: 400
        },
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: {
              color: '#94a3b8'
            },
            grid: {
              color: 'rgba(148, 163, 184, 0.12)'
            }
          },
          y: {
            ticks: {
              color: '#94a3b8'
            },
            grid: {
              color: 'rgba(148, 163, 184, 0.12)'
            },
            beginAtZero: true
          }
        }
      }
    });

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
    }

    function randomValue() {
      const base = 50;
      const variance = Math.random() * 30 - 15;
      const wave = Math.sin(Date.now() / 5000) * 10;
      return Math.max(0, +(base + variance + wave).toFixed(1));
    }

    function updateMetrics() {
      const points = state.points;
      const current = points[points.length - 1] || 0;
      const previous = points[points.length - 2] || current;
      const avg = points.length
        ? (points.reduce((sum, val) => sum + val, 0) / points.length).toFixed(1)
        : '0.0';

      state.currentValue = current;
      state.peakValue = Math.max(state.peakValue, current);

      const trend = previous === 0 ? 0 : (((current - previous) / previous) * 100);
      const trendText = `${trend >= 0 ? '+' : ''}${trend.toFixed(1)}%`;

      currentValueEl.textContent = current.toFixed(1);
      avgValueEl.textContent = avg;
      peakValueEl.textContent = state.peakValue.toFixed(1);
      eventCountEl.textContent = state.submittedEvents.length;
      currentTrendEl.textContent = trendText;
      currentTrendEl.style.color = trend >= 0 ? '#86efac' : '#fca5a5';
    }

    function addActivityLogItem(text, meta = '') {
      const item = document.createElement('li');
      item.className = 'log-item';
      item.innerHTML = `
        <div>${text}</div>
        <div class="log-meta">${meta}</div>
      `;
      activityLogEl.prepend(item);

      while (activityLogEl.children.length > 12) {
        activityLogEl.removeChild(activityLogEl.lastChild);
      }
    }

    function pushDataPoint(value) {
      const label = formatTime();

      state.labels.push(label);
      state.points.push(value);

      if (state.points.length > MAX_POINTS) {
        state.points.shift();
        state.labels.shift();
      }

      liveChart.data.labels = [...state.labels];
      liveChart.data.datasets[0].data = [...state.points];
      liveChart.update();

      updateMetrics();
    }

    function simulateRealtimeData() {
      const value = randomValue();
      pushDataPoint(value);
    }

    function validateForm(data) {
      if (!data.eventName.trim()) {
        return 'Event name is required.';
      }
      if (!data.eventType) {
        return 'Event type is required.';
      }
      if (Number.isNaN(data.eventValue) || data.eventValue === null) {
        return 'Associated value must be a valid number.';
      }
      return null;
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(eventForm);
      const payload = {
        eventName: formData.get('eventName')?.toString() || '',
        eventType: formData.get('eventType')?.toString() || '',
        eventValue: Number(formData.get('eventValue')),
        notes: formData.get('notes')?.toString() || '',
        createdAt: new Date().toISOString()
      };

      const error = validateForm(payload);

      if (error) {
        formMessageEl.textContent = error;
        formMessageEl.className = 'message error';
        return;
      }

      state.submittedEvents.push(payload);

      addActivityLogItem(
        `${payload.eventName} (${payload.eventType}) submitted with value ${payload.eventValue}`,
        formatTime(new Date(payload.createdAt))
      );

      if (!Number.isNaN(payload.eventValue)) {
        pushDataPoint(payload.eventValue);
      }

      formMessageEl.textContent = 'Event submitted successfully.';
      formMessageEl.className = 'message success';

      eventForm.reset();
      updateMetrics();
    });

    eventForm.addEventListener('reset', () => {
      formMessageEl.textContent = '';
      formMessageEl.className = 'message';
    });

    function bootstrap() {
      for (let i = 0; i < 8; i++) {
        pushDataPoint(randomValue());
      }

      addActivityLogItem('Dashboard initialized', formatTime());
      setInterval(simulateRealtimeData, UPDATE_INTERVAL_MS);
    }

    bootstrap();
  </script>
</body>
</html>
