</head>
<body>
  <div class="container">
    <div class="header">
      <div>
        <h1>Operations Dashboard</h1>
        <div style="color: var(--muted); margin-top: 6px;">Live monitoring and input management</div>
      </div>
      <div class="status">
        <span class="status-dot"></span>
        Real-time feed active
      </div>
    </div>

    <div class="metrics">
      <div class="metric-card">
        <div class="metric-label">Current Throughput</div>
        <div class="metric-value" id="throughputValue">0</div>
        <div class="metric-trend" id="throughputTrend">+0.0%</div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Average Load</div>
        <div class="metric-value" id="avgLoadValue">0%</div>
        <div class="metric-trend" id="avgLoadTrend">Stable</div>
      </div>
      <div class="metric-card">
        <div class="metric-label">Alerts Today</div>
        <div class="metric-value" id="alertsValue">0</div>
        <div class="metric-trend" id="alertsTrend">No change</div>
      </div>
    </div>

    <div class="grid" style="margin-top: 20px;">
      <div class="left-column">
        <div class="panel">
          <h2>Real-Time Data Stream</h2>
          <div class="chart-wrapper">
            <canvas id="liveChart" width="800" height="320"></canvas>
          </div>
        </div>

        <div class="panel">
          <h2>Recent Submissions</h2>
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Name</th>
                <th>Priority</th>
                <th>Description</th>
              </tr>
            </thead>
            <tbody id="submissionTableBody">
              <tr>
                <td colspan="4" style="color: var(--muted);">No submissions yet.</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <div class="right-column">
        <div class="panel">
          <h2>Create Entry</h2>
          <form id="entryForm" novalidate>
            <div class="form-group">
              <label for="name">Name</label>
              <input id="name" name="name" type="text" placeholder="Enter a name" />
              <div class="error" id="nameError"></div>
            </div>

            <div class="form-group">
              <label for="priority">Priority</label>
              <select id="priority" name="priority">
                <option value="">Select priority</option>
                <option value="Low">Low</option>
                <option value="Medium">Medium</option>
                <option value="High">High</option>
              </select>
              <div class="error" id="priorityError"></div>
            </div>

            <div class="form-group">
              <label for="description">Description</label>
              <textarea id="description" name="description" placeholder="Describe the issue or request"></textarea>
              <div class="error" id="descriptionError"></div>
            </div>

            <div class="button-row">
              <button type="submit">Submit</button>
              <button type="button" class="secondary-btn" id="resetBtn">Reset</button>
            </div>
            <div class="message" id="formMessage"></div>
          </form>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("liveChart");
    const ctx = canvas.getContext("2d");

    const throughputValue = document.getElementById("throughputValue");
    const throughputTrend = document.getElementById("throughputTrend");
    const avgLoadValue = document.getElementById("avgLoadValue");
    const avgLoadTrend = document.getElementById("avgLoadTrend");
    const alertsValue = document.getElementById("alertsValue");
    const alertsTrend = document.getElementById("alertsTrend");

    const entryForm = document.getElementById("entryForm");
    const resetBtn = document.getElementById("resetBtn");
    const formMessage = document.getElementById("formMessage");
    const submissionTableBody = document.getElementById("submissionTableBody");

    const nameInput = document.getElementById("name");
    const priorityInput = document.getElementById("priority");
    const descriptionInput = document.getElementById("description");

    const nameError = document.getElementById("nameError");
    const priorityError = document.getElementById("priorityError");
    const descriptionError = document.getElementById("descriptionError");

    const maxPoints = 40;
    const dataPoints = [];
    let alertsCount = 0;

    function generatePoint() {
      const last = dataPoints.length ? dataPoints[dataPoints.length - 1] : 50;
      let next = last + (Math.random() * 16 - 8);
      next = Math.max(10, Math.min(100, next));
      return Math.round(next);
    }

    function seedData() {
      for (let i = 0; i < maxPoints; i++) {
        dataPoints.push(generatePoint());
      }
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = (height / 4) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      if (!dataPoints.length) return;

      // Area fill
      ctx.beginPath();
      const stepX = width / (maxPoints - 1);

      dataPoints.forEach((value, index) => {
        const x = index * stepX;
        const y = height - (value / 100) * (height - 20) - 10;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.lineTo(width, height);
      ctx.lineTo(0, height);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.35)");
      gradient.addColorStop(1, "rgba(59, 130, 246, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fill();

      // Line
      ctx.beginPath();
      dataPoints.forEach((value, index) => {
        const x = index * stepX;
        const y = height - (value / 100) * (height - 20) - 10;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#60a5fa";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      dataPoints.forEach((value, index) => {
        const x = index * stepX;
        const y = height - (value / 100) * (height - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#93c5fd";
        ctx.fill();
      });
    }

    function updateMetrics() {
      const current = dataPoints[dataPoints.length - 1] || 0;
      const previous = dataPoints[dataPoints.length - 2] || current;
      const average = dataPoints.reduce((sum, val) => sum + val, 0) / dataPoints.length;
      const change = previous === 0 ? 0 : ((current - previous) / previous) * 100;

      throughputValue.textContent = current;
      throughputTrend.textContent = `${change >= 0 ? "+" : ""}${change.toFixed(1)}%`;

      avgLoadValue.textContent = `${average.toFixed(0)}%`;
      avgLoadTrend.textContent =
        average > 75 ? "High load" :
        average > 45 ? "Moderate load" :
        "Stable";

      alertsValue.textContent = alertsCount;
      alertsTrend.textContent =
        current > 85 ? "Spike detected" :
        current < 20 ? "Low activity" :
        "Normal range";
    }

    function tick() {
      const newPoint = generatePoint();
      dataPoints.push(newPoint);
      if (dataPoints.length > maxPoints) {
        dataPoints.shift();
      }

      if (newPoint > 90 && Math.random() > 0.6) {
        alertsCount++;
      }

      drawChart();
      updateMetrics();
    }

    function clearErrors() {
      nameError.textContent = "";
      priorityError.textContent = "";
      descriptionError.textContent = "";
      formMessage.textContent = "";
    }

    function validateForm() {
      clearErrors();
      let isValid = true;

      if (!nameInput.value.trim()) {
        nameError.textContent = "Name is required.";
        isValid = false;
      }

      if (!priorityInput.value) {
        priorityError.textContent = "Priority is required.";
        isValid = false;
      }

      if (!descriptionInput.value.trim()) {
        descriptionError.textContent = "Description is required.";
        isValid = false;
      } else if (descriptionInput.value.trim().length < 10) {
        descriptionError.textContent = "Description must be at least 10 characters.";
        isValid = false;
      }

      return isValid;
    }

    function priorityBadge(priority) {
      const cls =
        priority === "High" ? "badge-high" :
        priority === "Medium" ? "badge-medium" :
        "badge-low";
      return `<span class="badge ${cls}">${priority}</span>`;
    }

    function addSubmissionRow({ name, priority, description, time }) {
      const emptyRow = submissionTableBody.querySelector("td[colspan='4']");
      if (emptyRow) {
        submissionTableBody.innerHTML = "";
      }

      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td>${time}</td>
        <td>${escapeHtml(name)}</td>
        <td>${priorityBadge(priority)}</td>
        <td>${escapeHtml(description)}</td>
      `;
      submissionTableBody.prepend(tr);
    }

    function escapeHtml(str) {
      return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    }

    entryForm.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) {
        formMessage.textContent = "Please fix the errors above.";
        return;
      }

      const submission = {
        name: nameInput.value.trim(),
        priority: priorityInput.value,
        description: descriptionInput.value.trim(),
        time: new Date().toLocaleTimeString()
      };

      addSubmissionRow(submission);
      formMessage.textContent = "Entry submitted successfully.";

      entryForm.reset();
    });

    resetBtn.addEventListener("click", () => {
      entryForm.reset();
      clearErrors();
      formMessage.textContent = "Form reset.";
    });

    seedData();
    drawChart();
    updateMetrics();

    setInterval(tick, 1000);
  </script>
</body>
</html>
