      formMessage: document.getElementById('formMessage'),
      toggleLiveBtn: document.getElementById('toggleLiveBtn'),
      liveStatus: document.getElementById('liveStatus'),
      lastRefresh: document.getElementById('lastRefresh')
    };

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function clamp(num, min, max) {
      return Math.min(Math.max(num, min), max);
    }

    function updateSummaryCards() {
      els.throughputValue.textContent = Math.round(state.throughput);
      els.sessionsValue.textContent = Math.round(state.sessions);
      els.errorRateValue.textContent = `${state.errorRate.toFixed(1)}%`;

      if (state.errorRate < 2) {
        state.health = 'Healthy';
        els.healthValue.textContent = state.health;
        els.healthValue.className = 'stat-value positive';
      } else if (state.errorRate < 5) {
        state.health = 'Warning';
        els.healthValue.textContent = state.health;
        els.healthValue.className = 'stat-value warning';
      } else {
        state.health = 'Critical';
        els.healthValue.textContent = state.health;
        els.healthValue.className = 'stat-value negative';
      }
    }

    function addFeedItem(title, tag, description) {
      const item = {
        time: formatTime(),
        title,
        tag,
        description
      };

      state.events.unshift(item);
      state.events = state.events.slice(0, 12);

      renderFeed();
    }

    function renderFeed() {
      els.eventFeed.innerHTML = '';

      if (state.events.length === 0) {
        els.eventFeed.innerHTML = '<div class="small">No events yet.</div>';
        return;
      }

      state.events.forEach(event => {
        const div = document.createElement('div');
        div.className = 'feed-item';
        div.innerHTML = `
          <div class="feed-item-top">
            <strong>${escapeHtml(event.title)}</strong>
            <span class="feed-tag">${escapeHtml(event.tag)}</span>
          </div>
          <div>${escapeHtml(event.description)}</div>
          <div class="small" style="margin-top:8px;">${escapeHtml(event.time)}</div>
        `;
        els.eventFeed.appendChild(div);
      });
    }

    function renderRecords() {
      els.recordsTableBody.innerHTML = '';

      if (state.records.length === 0) {
        els.recordsTableBody.innerHTML = `
          <tr>
            <td colspan="5" class="small">No submitted records yet.</td>
          </tr>
        `;
        return;
      }

      state.records.forEach(record => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${escapeHtml(record.time)}</td>
          <td>${escapeHtml(record.eventName)}</td>
          <td>${escapeHtml(record.priority)}</td>
          <td>${escapeHtml(String(record.value))}</td>
          <td>${escapeHtml(record.notes)}</td>
        `;
        els.recordsTableBody.appendChild(tr);
      });
    }

    function showMessage(text, type = 'success') {
      els.formMessage.textContent = text;
      els.formMessage.className = `message ${type}`;
      setTimeout(() => {
        els.formMessage.className = 'message';
        els.formMessage.textContent = '';
      }, 3000);
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: state.chartLabels,
        datasets: [
          {
            label: 'Throughput',
            data: state.throughputSeries,
            borderColor: '#38bdf8',
            backgroundColor: 'rgba(56, 189, 248, 0.2)',
            tension: 0.35,
            fill: true
          },
          {
            label: 'Sessions',
            data: state.sessionSeries,
            borderColor: '#22c55e',
            backgroundColor: 'rgba(34, 197, 94, 0.15)',
            tension: 0.35,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          }
        }
      }
    });

    function pushChartData() {
      const label = formatTime();
      state.chartLabels.push(label);
      state.throughputSeries.push(Math.round(state.throughput));
      state.sessionSeries.push(Math.round(state.sessions));

      if (state.chartLabels.length > MAX_POINTS) {
        state.chartLabels.shift();
        state.throughputSeries.shift();
        state.sessionSeries.shift();
      }

      realtimeChart.update();
    }

    function simulateRealtimeUpdate() {
      if (!liveUpdatesEnabled) return;

      state.throughput = clamp(state.throughput + (Math.random() * 20 - 10), 60, 220);
      state.sessions = clamp(state.sessions + (Math.random() * 10 - 5), 10, 100);
      state.errorRate = clamp(state.errorRate + (Math.random() * 1.2 - 0.6), 0.1, 8.5);

      updateSummaryCards();
      pushChartData();

      if (Math.random() > 0.7) {
        const eventTypes = [
          ['Auto Scale Triggered', 'System', 'Capacity adjusted automatically'],
          ['Latency Spike', 'Alert', 'Response times increased briefly'],
          ['Worker Rebalanced', 'System', 'Load redistributed across nodes'],
          ['New Session Burst', 'Traffic', 'User sessions increased rapidly']
        ];
        const randomEvent = eventTypes[Math.floor(Math.random() * eventTypes.length)];
        addFeedItem(randomEvent[0], randomEvent[1], randomEvent[2]);
      }

      els.lastRefresh.textContent = formatTime();
    }

    els.form.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(els.form);
      const eventName = String(formData.get('eventName') || '').trim();
      const priority = String(formData.get('priority') || '').trim();
      const value = Number(formData.get('value'));
      const notes = String(formData.get('notes') || '').trim();

      if (!eventName || !priority || Number.isNaN(value)) {
        showMessage('Please complete all required fields.', 'error');
        return;
      }

      const record = {
        time: formatTime(),
        eventName,
        priority,
        value,
        notes
      };

      state.records.unshift(record);
      state.records = state.records.slice(0, 20);

      renderRecords();
      addFeedItem(eventName, priority, notes || `Manual entry recorded with value ${value}`);
      showMessage('Event submitted successfully.', 'success');

      state.throughput = clamp(state.throughput + value * 0.1, 60, 220);
      state.errorRate = clamp(
        priority === 'High' ? state.errorRate + 0.8 :
        priority === 'Medium' ? state.errorRate + 0.3 :
        state.errorRate + 0.1,
        0.1,
        8.5
      );

      updateSummaryCards();
      pushChartData();
      els.form.reset();
    });

    els.toggleLiveBtn.addEventListener('click', () => {
      liveUpdatesEnabled = !liveUpdatesEnabled;
      els.liveStatus.textContent = liveUpdatesEnabled ? 'ON' : 'OFF';
      els.toggleLiveBtn.textContent = liveUpdatesEnabled ? 'Pause Live Feed' : 'Resume Live Feed';
      addFeedItem(
        liveUpdatesEnabled ? 'Live Feed Resumed' : 'Live Feed Paused',
        'Control',
        liveUpdatesEnabled
          ? 'Automatic updates have resumed.'
          : 'Automatic updates have been paused.'
      );
    });

    function seedInitialData() {
      for (let i = 0; i < 8; i++) {
        state.throughput = clamp(state.throughput + (Math.random() * 20 - 10), 60, 220);
        state.sessions = clamp(state.sessions + (Math.random() * 10 - 5), 10, 100);
        state.errorRate = clamp(state.errorRate + (Math.random() * 0.6 - 0.3), 0.1, 8.5);
        pushChartData();
      }

      addFeedItem('Dashboard Started', 'System', 'Live monitoring initialized.');
      addFeedItem('Baseline Metrics Loaded', 'System', 'Initial chart data seeded.');
      updateSummaryCards();
      renderRecords();
      els.lastRefresh.textContent = formatTime();
    }

    seedInitialData();
    setInterval(simulateRealtimeUpdate, 2000);
  </script>
</body>
</html>
