<body>
  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <div class="label">Latest Value</div>
        <div class="value" id="latestValue">-</div>
      </div>
      <div class="stat">
        <div class="label">Average</div>
        <div class="value" id="averageValue">-</div>
      </div>
      <div class="stat">
        <div class="label">Total Points</div>
        <div class="value" id="totalPoints">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Chart</h2>
        <canvas id="chart" width="700" height="320"></canvas>
        <div class="buttons" style="margin-top:12px;">
          <button class="success" id="startBtn">Start Stream</button>
          <button class="danger" id="stopBtn">Stop Stream</button>
        </div>
      </div>

      <div class="card">
        <h2>Add Data Point</h2>
        <form id="dataForm">
          <label>
            Label
            <input type="text" id="labelInput" placeholder="e.g. Manual Entry" required />
          </label>
          <label>
            Value
            <input type="number" id="valueInput" placeholder="e.g. 42" step="any" required />
          </label>
          <div class="buttons">
            <button type="submit" class="primary">Add Point</button>
            <button type="button" class="danger" id="clearBtn">Clear Data</button>
          </div>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const averageValueEl = document.getElementById('averageValue');
    const totalPointsEl = document.getElementById('totalPoints');
    const eventLog = document.getElementById('eventLog');

    const dataForm = document.getElementById('dataForm');
    const labelInput = document.getElementById('labelInput');
    const valueInput = document.getElementById('valueInput');

    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');
    const clearBtn = document.getElementById('clearBtn');

    let data = [];
    let timer = null;
    const maxPoints = 30;

    function logEvent(message) {
      const row = document.createElement('div');
      row.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(row);

      while (eventLog.children.length > 20) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function addPoint(label, value) {
      data.push({
        label,
        value: Number(value),
        time: new Date()
      });

      if (data.length > maxPoints) data.shift();

      updateStats();
      drawChart();
    }

    function updateStats() {
      if (data.length === 0) {
        latestValueEl.textContent = '-';
        averageValueEl.textContent = '-';
        totalPointsEl.textContent = '0';
        return;
      }

      const latest = data[data.length - 1].value;
      const avg = data.reduce((sum, p) => sum + p.value, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(2);
      averageValueEl.textContent = avg.toFixed(2);
      totalPointsEl.textContent = data.length;
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      const pad = 40;

      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, w, h);

      // Axes
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad, 10);
      ctx.lineTo(pad, h - pad);
      ctx.lineTo(w - 10, h - pad);
      ctx.stroke();

      if (data.length === 0) return;

      const values = data.map(d => d.value);
      let min = Math.min(...values);
      let max = Math.max(...values);

      if (min === max) {
        min -= 1;
        max += 1;
      }

      // Y-axis labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px Arial';
      ctx.fillText(max.toFixed(1), 5, 20);
      ctx.fillText(min.toFixed(1), 5, h - pad);

      const chartW = w - pad - 20;
      const chartH = h - pad - 20;

      // Line
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = pad + (i / Math.max(data.length - 1, 1)) * chartW;
        const y = 20 + ((max - point.value) / (max - min)) * chartH;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = '#3b82f6';
      data.forEach((point, i) => {
        const x = pad + (i / Math.max(data.length - 1, 1)) * chartW;
        const y = 20 + ((max - point.value) / (max - min)) * chartH;

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function startStream() {
      if (timer) return;
      timer = setInterval(() => {
        const value = 20 + Math.random() * 80;
        addPoint('Auto', value);
        logEvent(`Auto data added: ${value.toFixed(2)}`);
      }, 1000);
      logEvent('Stream started');
    }

    function stopStream() {
      if (!timer) return;
      clearInterval(timer);
      timer = null;
      logEvent('Stream stopped');
    }

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const label = labelInput.value.trim();
      const value = parseFloat(valueInput.value);

      if (!label || Number.isNaN(value)) {
        alert('Please enter a valid label and value.');
        return;
      }

      addPoint(label, value);
      logEvent(`Manual data added: ${label} = ${value.toFixed(2)}`);
      dataForm.reset();
    });

    clearBtn.addEventListener('click', () => {
      data = [];
      updateStats();
      drawChart();
      logEvent('Data cleared');
    });

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);

    drawChart();
    updateStats();
  </script>
</body>
</html>
