    const values = [];

    const ctx = document.getElementById('liveChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Value',
          data: values,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function updateMetrics(category, value) {
      totalEvents++;
      totalValue += value;
      totalEventsEl.textContent = totalEvents;
      avgValueEl.textContent = (totalValue / totalEvents).toFixed(1);
      lastCategoryEl.textContent = category;
    }

    function addChartPoint(value) {
      const time = new Date().toLocaleTimeString();
      labels.push(time);
      values.push(value);

      if (labels.length > 20) {
        labels.shift();
        values.shift();
      }

      chart.update();
    }

    function addLog(category, value, source) {
      const li = document.createElement('li');
      li.textContent = `${new Date().toLocaleTimeString()} - ${category}: ${value} (${source})`;
      eventLogEl.prepend(li);

      while (eventLogEl.children.length > 10) {
        eventLogEl.removeChild(eventLogEl.lastChild);
      }
    }

    function addEvent(category, value, source) {
      updateMetrics(category, value);
      addChartPoint(value);
      addLog(category, value, source);
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const category = document.getElementById('category').value;
      const value = Number(document.getElementById('value').value);
      const source = document.getElementById('source').value.trim();

      if (!source || Number.isNaN(value)) return;

      addEvent(category, value, source);
      eventForm.reset();
    });

    toggleFeedBtn.addEventListener('click', () => {
      feedRunning = !feedRunning;
      toggleFeedBtn.textContent = feedRunning ? 'Pause Feed' : 'Resume Feed';
    });

    clearDataBtn.addEventListener('click', () => {
      totalEvents = 0;
      totalValue = 0;
      totalEventsEl.textContent = '0';
      avgValueEl.textContent = '0';
      lastCategoryEl.textContent = '-';

      labels.length = 0;
      values.length = 0;
      chart.update();

      eventLogEl.innerHTML = '';
    });

    setInterval(() => {
      if (!feedRunning) return;

      const categories = ['Sales', 'Traffic', 'Errors'];
      const category = categories[Math.floor(Math.random() * categories.length)];
      const value = Math.floor(Math.random() * 100);
      addEvent(category, value, 'Simulated Feed');
    }, 1500);
  </script>
</body>
</html>
```

