        <div class="stat-value" id="countValue">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Chart</h2>
        <canvas id="chart" width="700" height="300"></canvas>
      </div>

      <div class="card">
        <h2>Add Event</h2>
        <form id="eventForm">
          <label>
            Name
            <input type="text" id="name" placeholder="Enter event name" required />
          </label>

          <label>
            Type
            <select id="type" required>
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="success">Success</option>
            </select>
          </label>

