  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const countValueEl = document.getElementById('countValue');

    const form = document.getElementById('eventForm');
    const nameInput = document.getElementById('name');
    const typeInput = document.getElementById('type');
    const valueInput = document.getElementById('value');
    const formError = document.getElementById('formError');
    const eventLog = document.getElementById('eventLog');

    const data = [];
    const maxPoints = 40;

    function addDataPoint(value) {
      data.push(value);
      if (data.length > maxPoints) data.shift();
      updateStats();
      drawChart();
    }

    function updateStats() {
      const latest = data[data.length - 1] ?? 0;
      const avg = data.length
        ? data.reduce((sum, v) => sum + v, 0) / data.length
        : 0;

      latestValueEl.textContent = latest.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      countValueEl.textContent = data.length;
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const min = Math.min(...data);
      const max = Math.max(...data);
      const range = max - min || 1;

      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * w;
        const y = h - ((value - min) / range) * (h - 20) - 10;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Draw points
      ctx.fillStyle = '#86efac';
      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * w;
        const y = h - ((value - min) / range) * (h - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function addLogItem({ name, type, value, time }) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${time}] ${type.toUpperCase()} - ${name}: ${value}`;
      eventLog.prepend(item);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      formError.textContent = '';

      const name = nameInput.value.trim();
      const type = typeInput.value;
      const value = Number(valueInput.value);

      if (!name) {
        formError.textContent = 'Name is required.';
        return;
      }

      if (Number.isNaN(value)) {
        formError.textContent = 'Value must be a number.';
        return;
      }

      addDataPoint(value);
      addLogItem({
        name,
        type,
        value,
        time: new Date().toLocaleTimeString()
      });

      form.reset();
      nameInput.focus();
    });

    // Simulated realtime data feed
    setInterval(() => {
      const randomValue = 20 + Math.random() * 80;
      addDataPoint(randomValue);
    }, 1000);

    // Initial render
    drawChart();
    updateStats();
  </script>
</body>
</html>
