            Update Interval (ms)
            <input type="number" id="intervalInput" value="1000" min="100" step="100" />
          </label>

          <label>
            Data Mode
            <select id="modeInput">
              <option value="random">Random</option>
              <option value="steady">Steady Rise</option>
              <option value="spiky">Spiky</option>
            </select>
          </label>

