  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const thresholdValueEl = document.getElementById('thresholdValue');

    const settingsForm = document.getElementById('settingsForm');
    const thresholdInput = document.getElementById('thresholdInput');
    const intervalInput = document.getElementById('intervalInput');
    const modeInput = document.getElementById('modeInput');

    const toggleFeedBtn = document.getElementById('toggleFeed');
    const clearDataBtn = document.getElementById('clearData');
    const eventLog = document.getElementById('eventLog');

    let data = [];
    let maxPoints = 40;
    let threshold = 50;
    let interval = 1000;
    let mode = 'random';
    let timer = null;
    let running = true;
    let steadyValue = 10;

    function logEvent(message) {
      const empty = eventLog.querySelector('.muted');
      if (empty) empty.remove();

      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);

      while (eventLog.children.length > 12) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function generateValue() {
      if (mode === 'random') {
        return Math.floor(Math.random() * 100);
      }

      if (mode === 'steady') {
        steadyValue += 5;
        if (steadyValue > 100) steadyValue = 0;
        return steadyValue;
      }

      if (mode === 'spiky') {
        const spike = Math.random() > 0.8 ? 80 : 20;
        return Math.min(100, Math.max(0, spike + Math.floor(Math.random() * 20)));
      }

      return 0;
    }

    function updateStats() {
      const current = data.length ? data[data.length - 1] : 0;
      const avg = data.length
        ? (data.reduce((sum, v) => sum + v, 0) / data.length).toFixed(1)
        : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      thresholdValueEl.textContent = threshold;
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      // Threshold line
      const thresholdY = h - (threshold / 100) * h;
      ctx.strokeStyle = '#ef4444';
      ctx.setLineDash([6, 4]);
      ctx.beginPath();
      ctx.moveTo(0, thresholdY);
      ctx.lineTo(w, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      if (data.length < 2) return;

      // Line
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * w;
        const y = h - (value / 100) * h;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = '#86efac';
      data.forEach((value, index) => {
        const x = (index / (maxPoints - 1)) * w;
        const y = h - (value / 100) * h;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function pushDataPoint() {
      const value = generateValue();
      data.push(value);

      if (data.length > maxPoints) {
        data.shift();
      }

      updateStats();
      drawChart();

      if (value > threshold) {
        logEvent(`Alert: value ${value} exceeded threshold ${threshold}`);
      }
    }

    function startFeed() {
      stopFeed();
      timer = setInterval(() => {
        if (running) pushDataPoint();
      }, interval);
    }

    function stopFeed() {
      if (timer) clearInterval(timer);
    }

    settingsForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const newThreshold = Number(thresholdInput.value);
      const newInterval = Number(intervalInput.value);
      const newMode = modeInput.value;

      if (Number.isNaN(newThreshold) || Number.isNaN(newInterval) || newInterval < 100) {
        logEvent('Invalid form input.');
        return;
      }

      threshold = newThreshold;
      interval = newInterval;
      mode = newMode;

      logEvent(`Settings updated: threshold=${threshold}, interval=${interval}ms, mode=${mode}`);
      updateStats();
      startFeed();
    });

    toggleFeedBtn.addEventListener('click', () => {
      running = !running;
      toggleFeedBtn.textContent = running ? 'Pause Feed' : 'Resume Feed';
      logEvent(running ? 'Feed resumed.' : 'Feed paused.');
    });

    clearDataBtn.addEventListener('click', () => {
      data = [];
      steadyValue = 10;
      updateStats();
      drawChart();
      logEvent('Data cleared.');
    });

    // Initial render
    updateStats();
    drawChart();
    startFeed();
    logEvent('Dashboard started.');
  </script>
</body>
</html>
