<body>
  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="grid">
      <div class="card">
        <h2>Live Data</h2>
        <canvas id="liveChart"></canvas>
        <div class="status" id="chartStatus">Streaming simulated data...</div>
      </div>

      <div class="card">
        <h2>Add Entry</h2>
        <form id="entryForm">
          <input type="text" id="name" placeholder="Name" required />
          <input type="number" id="value" placeholder="Value" required />
          <button type="submit">Submit</button>
        </form>
        <div class="status" id="formStatus"></div>
      </div>
    </div>

    <div class="card" style="margin-top: 20px;">
      <h2>Submitted Entries</h2>
      <table>
        <thead>
          <tr>
            <th>Time</th>
            <th>Name</th>
            <th>Value</th>
          </tr>
        </thead>
        <tbody id="entriesTable"></tbody>
      </table>
    </div>
  </div>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = [];
    const dataPoints = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Sensor Value',
          data: dataPoints,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.2)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function addLiveDataPoint() {
      const now = new Date().toLocaleTimeString();
      const value = Math.floor(Math.random() * 100);

      labels.push(now);
      dataPoints.push(value);

      if (labels.length > 10) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
    }

    setInterval(addLiveDataPoint, 1000);
    addLiveDataPoint();

    const form = document.getElementById('entryForm');
    const table = document.getElementById('entriesTable');
    const formStatus = document.getElementById('formStatus');

    form.addEventListener('submit', function (e) {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const value = document.getElementById('value').value.trim();

      if (!name || !value) {
        formStatus.textContent = 'Please fill in all fields.';
        return;
      }

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${new Date().toLocaleTimeString()}</td>
        <td>${escapeHtml(name)}</td>
        <td>${escapeHtml(value)}</td>
      `;

      table.prepend(row);

      form.reset();
      formStatus.textContent = 'Entry submitted successfully.';
    });

    function escapeHtml(str) {
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }
  </script>
</body>
</html>
```

