<body>
  <div class="container">
    <h1>Realtime Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <div class="stat-label">Latest Value</div>
        <div class="stat-value" id="latestValue">0</div>
      </div>
      <div class="stat">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="averageValue">0</div>
      </div>
      <div class="stat">
        <div class="stat-label">Status</div>
        <div class="stat-value" id="statusValue">Running</div>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Chart</h2>
        <p class="small">Simulated realtime data stream.</p>
        <canvas id="chart" width="700" height="320"></canvas>
      </div>

      <div class="card">
        <h2>Controls & Form</h2>
        <form id="dataForm">
          <label>
            Label
            <input type="text" id="labelInput" placeholder="e.g. Sensor A" required />
          </label>

          <label>
            Base Value
            <input type="number" id="baseInput" value="50" min="0" max="1000" required />
          </label>

          <label>
            Update Interval (ms)
            <select id="intervalInput">
              <option value="250">250</option>
              <option value="500" selected>500</option>
              <option value="1000">1000</option>
              <option value="2000">2000</option>
            </select>
          </label>

          <button type="submit">Apply Settings</button>
        </form>

        <div class="controls">
          <button class="secondary" id="toggleBtn" type="button">Pause</button>
          <button class="danger" id="resetBtn" type="button">Reset</button>
        </div>

        <div class="log" id="log"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const latestValueEl = document.getElementById("latestValue");
    const averageValueEl = document.getElementById("averageValue");
    const statusValueEl = document.getElementById("statusValue");

    const form = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const baseInput = document.getElementById("baseInput");
    const intervalInput = document.getElementById("intervalInput");

    const toggleBtn = document.getElementById("toggleBtn");
    const resetBtn = document.getElementById("resetBtn");
    const logEl = document.getElementById("log");

    let config = {
      label: "Sensor A",
      base: 50,
      interval: 500
    };

    let data = [];
    let maxPoints = 40;
    let timer = null;
    let running = true;

    function log(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      logEl.prepend(item);

      while (logEl.children.length > 12) {
        logEl.removeChild(logEl.lastChild);
      }
    }

    function generateValue() {
      const noise = (Math.random() - 0.5) * 20;
      const wave = Math.sin(Date.now() / 1000) * 10;
      return Math.max(0, config.base + noise + wave);
    }

    function updateData() {
      const value = generateValue();
      data.push({
        time: new Date(),
        value
      });

      if (data.length > maxPoints) data.shift();

      updateStats();
      drawChart();
    }

    function updateStats() {
      if (!data.length) {
        latestValueEl.textContent = "0";
        averageValueEl.textContent = "0";
        return;
      }

      const latest = data[data.length - 1].value;
      const avg = data.reduce((sum, d) => sum + d.value, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      statusValueEl.textContent = running ? "Running" : "Paused";
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;

      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = "rgba(148,163,184,0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values) - 5;
      const max = Math.max(...values) + 5;
      const range = max - min || 1;

      // Line
      ctx.beginPath();
      ctx.lineWidth = 2;
      ctx.strokeStyle = "#38bdf8";

      data.forEach((point, index) => {
        const x = (index / (maxPoints - 1)) * w;
        const y = h - ((point.value - min) / range) * h;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Fill
      ctx.lineTo(w, h);
      ctx.lineTo(0, h);
      ctx.closePath();
      ctx.fillStyle = "rgba(56, 189, 248, 0.15)";
      ctx.fill();

      // Latest point
      const lastIndex = data.length - 1;
      const lastX = (lastIndex / (maxPoints - 1)) * w;
      const lastY = h - ((data[lastIndex].value - min) / range) * h;

      ctx.beginPath();
      ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
      ctx.fillStyle = "#22c55e";
      ctx.fill();

      // Label
      ctx.fillStyle = "#e5e7eb";
      ctx.font = "14px Arial";
      ctx.fillText(config.label, 12, 20);
    }

    function startTimer() {
      stopTimer();
      timer = setInterval(() => {
        if (running) updateData();
      }, Number(config.interval));
    }

    function stopTimer() {
      if (timer) clearInterval(timer);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      config.label = labelInput.value.trim() || "Sensor A";
      config.base = Number(baseInput.value) || 50;
      config.interval = Number(intervalInput.value) || 500;

      startTimer();
      log(`Updated settings: label=${config.label}, base=${config.base}, interval=${config.interval}ms`);
      drawChart();
    });

    toggleBtn.addEventListener("click", () => {
      running = !running;
      toggleBtn.textContent = running ? "Pause" : "Resume";
      statusValueEl.textContent = running ? "Running" : "Paused";
      log(running ? "Stream resumed" : "Stream paused");
    });

    resetBtn.addEventListener("click", () => {
      data = [];
      updateStats();
      drawChart();
      log("Data reset");
    });

    // Initial form values
    labelInput.value = config.label;
    baseInput.value = config.base;
    intervalInput.value = config.interval;

    // Seed initial data
    for (let i = 0; i < 10; i++) {
      data.push({
        time: new Date(),
        value: generateValue()
      });
    }

    updateStats();
    drawChart();
    startTimer();
    log("Dashboard started");
  </script>
</body>
</html>
