      main {
        grid-template-columns: 1fr;
      }

      .kpis {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Real-Time Dashboard</h1>
  </header>

  <main>
    <section>
      <div class="kpis">
        <div class="kpi">
          <h2 id="kpiValue">0</h2>
          <p>Latest Value</p>
        </div>
        <div class="kpi">
          <h2 id="kpiAvg">0</h2>
          <p>Average</p>
        </div>
        <div class="kpi">
          <h2 id="kpiCount">0</h2>
          <p>Data Points</p>
        </div>
      </div>

      <div class="card">
        <h3>Live Data</h3>
        <canvas id="liveChart"></canvas>
      </div>
    </section>

    <aside>
      <div class="card" style="margin-bottom: 1rem;">
        <h3>Add Manual Entry</h3>
        <form id="dataForm">
          <input type="text" id="labelInput" placeholder="Label" required />
          <input type="number" id="valueInput" placeholder="Value" required />
          <button type="submit">Add Data Point</button>
        </form>
      </div>

      <div class="card">
        <h3>Event Log</h3>
        <ul id="eventLog"></ul>
      </div>
    </aside>
  </main>

  <script>
    const labels = [];
    const values = [];

    const ctx = document.getElementById('liveChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Metric',
          data: values,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.2)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    const kpiValue = document.getElementById('kpiValue');
    const kpiAvg = document.getElementById('kpiAvg');
    const kpiCount = document.getElementById('kpiCount');
    const eventLog = document.getElementById('eventLog');
    const form = document.getElementById('dataForm');
    const labelInput = document.getElementById('labelInput');
    const valueInput = document.getElementById('valueInput');

    function updateKPIs() {
      const count = values.length;
      const latest = count ? values[count - 1] : 0;
      const avg = count ? (values.reduce((a, b) => a + b, 0) / count).toFixed(2) : 0;

      kpiValue.textContent = latest;
      kpiAvg.textContent = avg;
      kpiCount.textContent = count;
    }

    function addLog(message) {
      const li = document.createElement('li');
      li.textContent = `${new Date().toLocaleTimeString()} — ${message}`;
      eventLog.prepend(li);

      while (eventLog.children.length > 10) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function addDataPoint(label, value, source = 'manual') {
      labels.push(label);
      values.push(value);

      if (labels.length > 20) {
        labels.shift();
        values.shift();
      }

      chart.update();
      updateKPIs();
      addLog(`Added ${value} (${source})`);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = parseFloat(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      addDataPoint(label, value, 'form');
      form.reset();
    });

    // Simulated real-time data feed
    setInterval(() => {
      const now = new Date().toLocaleTimeString();
      const randomValue = Math.floor(Math.random() * 100);
      addDataPoint(now, randomValue, 'auto');
    }, 2000);

    updateKPIs();
  </script>
</body>
</html>
```

### Features included
- `setInterval()` simulates real-time incoming data
- Form submission adds custom data points
- Chart updates instantly
- KPI summary updates automatically
- Event log shows recent actions

