<body>
  <div class="container">
    <h1>Realtime Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <h3>Current Value</h3>
        <p id="currentValue">0</p>
      </div>
      <div class="stat">
        <h3>Submitted Threshold</h3>
        <p id="thresholdValue">50</p>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Data</h2>
        <canvas id="liveChart"></canvas>
      </div>

      <div class="card">
        <h2>Settings Form</h2>
        <form id="settingsForm">
          <label>
            Threshold
            <input type="number" id="thresholdInput" min="0" max="100" value="50" required />
          </label>

          <label>
            Label
            <input type="text" id="labelInput" maxlength="20" placeholder="e.g. Sensor A" required />
          </label>

          <button type="submit">Save Settings</button>
          <div id="formMessage" class="message"></div>
        </form>

        <ul id="eventLog" class="log"></ul>
      </div>
    </div>
  </div>

  <script>
    const currentValueEl = document.getElementById('currentValue');
    const thresholdValueEl = document.getElementById('thresholdValue');
    const settingsForm = document.getElementById('settingsForm');
    const thresholdInput = document.getElementById('thresholdInput');
    const labelInput = document.getElementById('labelInput');
    const formMessage = document.getElementById('formMessage');
    const eventLog = document.getElementById('eventLog');

    let threshold = 50;
    let currentLabel = 'Live Metric';

    const labels = [];
    const dataPoints = [];

    const ctx = document.getElementById('liveChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: currentLabel,
          data: dataPoints,
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.2)',
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            min: 0,
            max: 100
          }
        }
      }
    });

    function addLog(message) {
      const li = document.createElement('li');
      li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(li);

      while (eventLog.children.length > 8) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function getRandomValue() {
      return Math.floor(Math.random() * 101);
    }

    function updateRealtimeData() {
      const value = getRandomValue();
      const time = new Date().toLocaleTimeString();

      currentValueEl.textContent = value;

      labels.push(time);
      dataPoints.push(value);

      if (labels.length > 12) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();

      if (value > threshold) {
        addLog(`Alert: value ${value} exceeded threshold ${threshold}`);
      }
    }

    settingsForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const newThreshold = Number(thresholdInput.value);
      const newLabel = labelInput.value.trim();

      if (Number.isNaN(newThreshold) || newThreshold < 0 || newThreshold > 100) {
        formMessage.textContent = 'Threshold must be between 0 and 100.';
        formMessage.className = 'message error';
        return;
      }

      if (!newLabel) {
        formMessage.textContent = 'Label is required.';
        formMessage.className = 'message error';
        return;
      }

      threshold = newThreshold;
      currentLabel = newLabel;

      thresholdValueEl.textContent = threshold;
      chart.data.datasets[0].label = currentLabel;
      chart.update();

      formMessage.textContent = 'Settings saved successfully.';
      formMessage.className = 'message success';

      addLog(`Settings updated: threshold=${threshold}, label="${currentLabel}"`);
    });

    // Seed initial data
    for (let i = 0; i < 6; i++) {
      labels.push(new Date(Date.now() - (6 - i) * 1000).toLocaleTimeString());
      dataPoints.push(getRandomValue());
    }
    chart.update();
    currentValueEl.textContent = dataPoints[dataPoints.length - 1];

    // Realtime updates every second
    setInterval(updateRealtimeData, 1000);
  </script>
</body>
</html>
```

## What this includes

- **Real-time visualization**: chart updates every second
- **Dashboard stats**: current value and threshold
- **Form handling**:
  - validates threshold
  - validates label
  - updates dashboard state
- **Event log**: shows alerts and form submissions

## How to run

1. Save as `index.html`
2. Open in a browser
3. Interact with the form and watch the chart update live

