</head>
<body>
  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <div class="stat-label">Latest Value</div>
        <div class="stat-value" id="latestValue">0</div>
      </div>
      <div class="stat">
        <div class="stat-label">Average</div>
        <div class="stat-value" id="avgValue">0</div>
      </div>
      <div class="stat">
        <div class="stat-label">Updates</div>
        <div class="stat-value" id="updateCount">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Chart</h2>
        <canvas id="chart" width="700" height="320"></canvas>
      </div>

      <div class="card">
        <h2>Add Manual Data</h2>
        <form id="dataForm">
          <label>
            Label
            <input type="text" id="labelInput" placeholder="e.g. Sensor A" required />
          </label>

          <label>
            Value
            <input type="number" id="valueInput" placeholder="e.g. 42" required />
          </label>

          <label>
            Type
            <select id="typeInput">
              <option value="manual">Manual</option>
              <option value="alert">Alert</option>
              <option value="system">System</option>
            </select>
          </label>

          <button type="submit">Submit</button>
          <div id="formError" class="error"></div>
        </form>

        <div class="log" id="log"></div>
      </div>
    </div>
  </div>

  <script>
    const chart = document.getElementById("chart");
    const ctx = chart.getContext("2d");

    const latestValueEl = document.getElementById("latestValue");
    const avgValueEl = document.getElementById("avgValue");
    const updateCountEl = document.getElementById("updateCount");
    const logEl = document.getElementById("log");
    const form = document.getElementById("dataForm");
    const formError = document.getElementById("formError");

    const data = [];
    const maxPoints = 30;
    let updates = 0;

    function addDataPoint(label, value, type = "auto") {
      const point = {
        time: new Date().toLocaleTimeString(),
        label,
        value: Number(value),
        type
      };

      data.push(point);
      if (data.length > maxPoints) data.shift();

      updates++;
      updateStats();
      drawChart();
      addLogEntry(point);
    }

    function updateStats() {
      if (data.length === 0) return;

      const latest = data[data.length - 1].value;
      const avg = data.reduce((sum, p) => sum + p.value, 0) / data.length;

      latestValueEl.textContent = latest.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      updateCountEl.textContent = updates;
    }

    function drawChart() {
      const w = chart.width;
      const h = chart.height;
      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, w, h);

      // Grid
      ctx.strokeStyle = "rgba(148,163,184,0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values, 0);
      const max = Math.max(...values, 100);
      const range = max - min || 1;

      // Line
      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = (i / (maxPoints - 1)) * (w - 40) + 20;
        const y = h - ((point.value - min) / range) * (h - 40) - 20;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#86efac";
      data.forEach((point, i) => {
        const x = (i / (maxPoints - 1)) * (w - 40) + 20;
        const y = h - ((point.value - min) / range) * (h - 40) - 20;

        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px Arial";
      ctx.fillText(`Min: ${min.toFixed(1)}`, 10, h - 8);
      ctx.fillText(`Max: ${max.toFixed(1)}`, w - 80, h - 8);
    }

    function addLogEntry(point) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${point.time}] ${point.label}: ${point.value} (${point.type})`;
      logEl.prepend(item);

      while (logEl.children.length > 20) {
        logEl.removeChild(logEl.lastChild);
      }
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      formError.textContent = "";

      const label = document.getElementById("labelInput").value.trim();
      const value = document.getElementById("valueInput").value;
      const type = document.getElementById("typeInput").value;

      if (!label) {
        formError.textContent = "Label is required.";
        return;
      }

      if (value === "" || isNaN(value)) {
        formError.textContent = "Value must be a number.";
        return;
      }

      addDataPoint(label, Number(value), type);
      form.reset();
    });

    // Simulated real-time stream
    setInterval(() => {
      const randomValue = 20 + Math.random() * 80;
      addDataPoint("Live Feed", randomValue, "auto");
    }, 1000);

    // Seed initial data
    for (let i = 0; i < 8; i++) {
      addDataPoint("Initial", 20 + Math.random() * 80, "seed");
    }
  </script>
</body>
</html>
```

