      labels.push(timeLabel);
      dataPoints.push(value);

      if (labels.length > maxPoints) {
        labels.shift();
        dataPoints.shift();
      }

      eventLog.push(`[${source}] ${timeLabel}: ${value}`);
      if (eventLog.length > 50) eventLog.shift();

      chart.update();
      updateStats();
      renderLog();
    }

