  <script>
    const data = [];
    const maxPoints = 20;

    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const latestValueEl = document.getElementById("latestValue");
    const avgValueEl = document.getElementById("avgValue");
    const totalPointsEl = document.getElementById("totalPoints");
    const tableBody = document.getElementById("dataTableBody");
    const form = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");

    function addDataPoint(label, value) {
      data.push({ label, value: Number(value) });
      if (data.length > maxPoints) data.shift();
      updateDashboard();
    }

    function updateDashboard() {
      drawChart();
      updateStats();
      updateTable();
    }

    function updateStats() {
      const values = data.map(d => d.value);
      const latest = values.length ? values[values.length - 1] : 0;
      const avg = values.length
        ? (values.reduce((a, b) => a + b, 0) / values.length).toFixed(2)
        : 0;

      latestValueEl.textContent = latest;
      avgValueEl.textContent = avg;
      totalPointsEl.textContent = data.length;
    }

    function updateTable() {
      tableBody.innerHTML = "";
      [...data].reverse().forEach(point => {
        const row = document.createElement("tr");
        row.innerHTML = `<td>${point.label}</td><td>${point.value}</td>`;
        tableBody.appendChild(row);
      });
    }

    function drawChart() {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      // Axes
      ctx.strokeStyle = "#ccc";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(40, 10);
      ctx.lineTo(40, height - 30);
      ctx.lineTo(width - 10, height - 30);
      ctx.stroke();

      if (data.length === 0) return;

      const values = data.map(d => d.value);
      const max = Math.max(...values, 10);
      const min = Math.min(...values, 0);
      const range = max - min || 1;

      const plotWidth = width - 60;
      const plotHeight = height - 50;

      // Line
      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = 40 + (i / Math.max(data.length - 1, 1)) * plotWidth;
        const y = 10 + (1 - (point.value - min) / range) * plotHeight;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#ef4444";
      data.forEach((point, i) => {
        const x = 40 + (i / Math.max(data.length - 1, 1)) * plotWidth;
        const y = 10 + (1 - (point.value - min) / range) * plotHeight;

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const label = labelInput.value.trim() || new Date().toLocaleTimeString();
      const value = valueInput.value;

      if (value === "") return;

      addDataPoint(label, value);
      form.reset();
    });

    // Simulated real-time updates every 2 seconds
    setInterval(() => {
      const label = new Date().toLocaleTimeString();
      const value = Math.floor(Math.random() * 100);
      addDataPoint(label, value);
    }, 2000);

    // Initial seed data
    for (let i = 0; i < 5; i++) {
      addDataPoint(`T-${5 - i}`, Math.floor(Math.random() * 100));
    }
  </script>
</body>
