<body>
  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="stats">
      <div class="stat">
        <h2 id="currentValue">0</h2>
        <p>Current Value</p>
      </div>
      <div class="stat">
        <h2 id="averageValue">0</h2>
        <p>Average</p>
      </div>
      <div class="stat">
        <h2 id="entryCount">0</h2>
        <p>Form Entries</p>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h3>Live Data Chart</h3>
        <canvas id="liveChart"></canvas>
      </div>

