  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');
    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const entryCountEl = document.getElementById('entryCount');
    const entryForm = document.getElementById('entryForm');
    const entryList = document.getElementById('entryList');

    const labels = [];
    const dataPoints = [];
    const entries = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Sensor Value',
          data: dataPoints,
          borderColor: '#0077ff',
          backgroundColor: 'rgba(0, 119, 255, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function updateStats() {
      const current = dataPoints[dataPoints.length - 1] || 0;
      const average = dataPoints.length
        ? (dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length).toFixed(1)
        : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = average;
      entryCountEl.textContent = entries.length;
    }

    function addLiveDataPoint() {
      const now = new Date().toLocaleTimeString();
      const value = Math.floor(Math.random() * 100);

      labels.push(now);
      dataPoints.push(value);

      if (labels.length > 10) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
      updateStats();
    }

    entryForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const amount = document.getElementById('amount').value.trim();

      if (!name || !amount) return;

      const entry = { name, amount };
      entries.push(entry);

      const li = document.createElement('li');
      li.textContent = `${name} — $${amount}`;
      entryList.prepend(li);

      entryForm.reset();
      updateStats();
    });

    setInterval(addLiveDataPoint, 1000);
    addLiveDataPoint();
  </script>
</body>
