            <button type="button" class="secondary" id="toggleBtn">Pause</button>
            <button type="button" class="danger" id="resetBtn">Reset</button>
          </div>
        </form>

        <div class="log" id="log"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const latestValueEl = document.getElementById("latestValue");
    const avgValueEl = document.getElementById("avgValue");
    const totalPointsEl = document.getElementById("totalPoints");
    const logEl = document.getElementById("log");
    const statusEl = document.getElementById("status");

    const form = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");
    const modeSelect = document.getElementById("modeSelect");
    const toggleBtn = document.getElementById("toggleBtn");
    const resetBtn = document.getElementById("resetBtn");

    let data = [];
    let running = true;
    const maxPoints = 30;

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      logEl.prepend(item);

      while (logEl.children.length > 8) {
        logEl.removeChild(logEl.lastChild);
      }
    }

    function addDataPoint(label, value) {
      data.push({ label, value: Number(value), time: new Date() });
      if (data.length > maxPoints) data.shift();
      updateMetrics();
      drawChart();
      addLog(`${label}: ${value}`);
    }

    function updateMetrics() {
      if (data.length === 0) {
        latestValueEl.textContent = "0";
        avgValueEl.textContent = "0";
        totalPointsEl.textContent = "0";
        return;
      }

      const values = data.map(d => d.value);
      const latest = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;

      latestValueEl.textContent = latest.toFixed(1);
      avgValueEl.textContent = avg.toFixed(1);
      totalPointsEl.textContent = data.length;
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background grid
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values, 0);
      const max = Math.max(...values, 10);
      const range = max - min || 1;

      const padding = 30;
      const chartW = w - padding * 2;
      const chartH = h - padding * 2;

      // Line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = padding + (i / (data.length - 1)) * chartW;
        const y = h - padding - ((point.value - min) / range) * chartH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#22c55e";
      data.forEach((point, i) => {
        const x = padding + (i / (data.length - 1)) * chartW;
        const y = h - padding - ((point.value - min) / range) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      ctx.font = "12px Arial";
      ctx.fillText(`Min: ${min.toFixed(1)}`, 10, h - 10);
      ctx.fillText(`Max: ${max.toFixed(1)}`, 10, 20);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const label = labelInput.value.trim();
      const value = parseFloat(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      addDataPoint(label, value);
      form.reset();
    });

    toggleBtn.addEventListener("click", () => {
      running = !running;
      toggleBtn.textContent = running ? "Pause" : "Resume";
      statusEl.textContent = running ? "Running" : "Paused";
      statusEl.style.color = running ? "#22c55e" : "#f59e0b";
      addLog(running ? "Auto generation resumed" : "Auto generation paused");
    });

    resetBtn.addEventListener("click", () => {
      data = [];
      updateMetrics();
      drawChart();
      logEl.innerHTML = "";
      addLog("Dashboard reset");
    });

    function autoGenerate() {
      if (running && modeSelect.value === "auto") {
        const value = (Math.random() * 100).toFixed(1);
        addDataPoint("Auto", value);
      }
    }

    setInterval(autoGenerate, 1000);

    // Seed initial data
    for (let i = 0; i < 8; i++) {
      addDataPoint("Seed", (20 + Math.random() * 60).toFixed(1));
    }
  </script>
</body>
</html>
