      currentValue = Math.max(0, Math.min(100, currentValue));
      currentValue = Number(currentValue.toFixed(2));

      tick++;
      labels.push(`T${tick}`);
      data.push(currentValue);

      if (labels.length > 20) {
        labels.shift();
        data.shift();
      }

      currentValueEl.textContent = currentValue;
      chart.update();
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const newTarget = Number(targetInput.value);
      const label = labelInput.value.trim();

      targetValue = newTarget;
      targetValueEl.textContent = newTarget;

      addLog(`Target set to ${newTarget}${label ? ` (${label})` : ''}`);

      form.reset();
    });

    setInterval(updateLiveData, 1000);
    updateLiveData();
