### `background.js`

```js
const DYNAMIC_RULE_ID_START = 1000;

async function setCustomBlockedDomains(domains) {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existingRules.map(rule => rule.id);

  const newRules = domains.map((domain, index) => ({
    id: DYNAMIC_RULE_ID_START + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: ["script", "xmlhttprequest", "image", "ping", "sub_frame"]
    }
  }));

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds,
    addRules: newRules
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  const defaultCustomDomains = [
    "segment.com",
    "hotjar.com"
  ];

  await chrome.storage.local.set({ customBlockedDomains: defaultCustomDomains });
  await setCustomBlockedDomains(defaultCustomDomains);
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "local" && changes.customBlockedDomains) {
    await setCustomBlockedDomains(changes.customBlockedDomains.newValue || []);
  }
});
```

