const textarea = document.getElementById("domains");
const saveButton = document.getElementById("save");
const status = document.getElementById("status");

async function loadDomains() {
  const result = await chrome.storage.local.get("customBlockedDomains");
  const domains = result.customBlockedDomains || [];
  textarea.value = domains.join("\n");
}

saveButton.addEventListener("click", async () => {
  const domains = textarea.value
    .split("\n")
    .map(d => d.trim())
    .filter(Boolean);

  await chrome.storage.local.set({ customBlockedDomains: domains });
  status.textContent = "Saved.";
  setTimeout(() => {
    status.textContent = "";
  }, 1500);
});

loadDomains();
```

