This is optional for static blocking, but useful for logging blocked requests locally and updating the badge count.

```js
let blockedCount = 0;

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener((info) => {
  blockedCount++;
  chrome.action.setBadgeText({ text: String(blockedCount) });
  chrome.action.setBadgeBackgroundColor({ color: "#b00020" });

  console.log("Blocked tracker:", {
    ruleId: info.rule.ruleId,
    request: info.request.url,
    type: info.request.type
  });
});

chrome.runtime.onInstalled.addListener(() => {
  chrome.action.setBadgeText({ text: "" });
});
