## `service_worker.js`

This handles:

- badge updates
- dynamic user rules
- stripping tracking query parameters from the current tab URL when requested

```javascript
const TRACKING_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "fbclid",
  "gclid",
  "mc_cid",
  "mc_eid"
];

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.sync.get(["customDomains", "blockedCount"]);
  if (!data.customDomains) {
    await chrome.storage.sync.set({ customDomains: [] });
  }
  if (!data.blockedCount) {
    await chrome.storage.local.set({ blockedCount: 0 });
  }
  await rebuildDynamicRules();
  updateBadge();
});

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener(async () => {
  const { blockedCount = 0 } = await chrome.storage.local.get("blockedCount");
  await chrome.storage.local.set({ blockedCount: blockedCount + 1 });
  updateBadge();
});

async function updateBadge() {
  const { blockedCount = 0 } = await chrome.storage.local.get("blockedCount");
  chrome.action.setBadgeBackgroundColor({ color: "#1f2937" });
  chrome.action.setBadgeText({
    text: blockedCount > 0 ? String(blockedCount) : ""
  });
}

async function rebuildDynamicRules() {
  const { customDomains = [] } = await chrome.storage.sync.get("customDomains");
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const removeRuleIds = existing.map(r => r.id);

  const dynamicRules = customDomains.map((domain, index) => ({
    id: 1000 + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  }));

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds,
    addRules: dynamicRules
  });
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "rebuildRules") {
    rebuildDynamicRules()
      .then(() => sendResponse({ ok: true }))
      .catch(err => sendResponse({ ok: false, error: err.message }));
    return true;
  }

  if (message.type === "resetCount") {
    chrome.storage.local.set({ blockedCount: 0 }).then(updateBadge);
    sendResponse({ ok: true });
    return;
  }

  if (message.type === "stripTrackingFromActiveTab") {
    chrome.tabs.query({ active: true, currentWindow: true }, tabs => {
      const tab = tabs[0];
      if (!tab?.url) {
        sendResponse({ ok: false });
        return;
      }

      try {
        const url = new URL(tab.url);
        let changed = false;

        for (const param of TRACKING_PARAMS) {
          if (url.searchParams.has(param)) {
            url.searchParams.delete(param);
            changed = true;
          }
        }

        if (changed) {
          chrome.tabs.update(tab.id, { url: url.toString() }, () => {
            sendResponse({ ok: true, changed: true, url: url.toString() });
          });
        } else {
          sendResponse({ ok: true, changed: false, url: tab.url });
        }
      } catch (e) {
        sendResponse({ ok: false, error: e.message });
      }
    });

    return true;
  }
});
```

