```javascript
async function loadDomains() {
  const { customDomains = [] } = await chrome.storage.sync.get("customDomains");
  document.getElementById("domains").value = customDomains.join("\n");
}

document.getElementById("save").addEventListener("click", async () => {
  const raw = document.getElementById("domains").value;
  const domains = raw
    .split("\n")
    .map(s => s.trim())
    .filter(Boolean)
    .filter(d => /^[a-z0-9.-]+$/i.test(d));

  await chrome.storage.sync.set({ customDomains: domains });

  chrome.runtime.sendMessage({ type: "rebuildRules" }, response => {
    const status = document.getElementById("status");
    if (response?.ok) {
      status.textContent = "Saved successfully.";
    } else {
      status.textContent = "Failed to save rules.";
    }
  });
});

loadDomains();
