### `background.js`

```javascript
const RULES = [
  {
    id: 1001,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||google-analytics.com^",
      resourceTypes: ["script", "image", "xmlhttprequest", "ping"],
      domainType: "thirdParty"
    }
  },
  {
    id: 1002,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||googletagmanager.com^",
      resourceTypes: ["script", "xmlhttprequest", "image", "ping"],
      domainType: "thirdParty"
    }
  },
  {
    id: 1003,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||doubleclick.net^",
      resourceTypes: ["script", "image", "xmlhttprequest", "sub_frame", "ping"],
      domainType: "thirdParty"
    }
  }
];

async function enableBlocking() {
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existing.map(rule => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds,
    addRules: RULES
  });

  await chrome.storage.local.set({ enabled: true });
}

async function disableBlocking() {
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existing.map(rule => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds
  });

  await chrome.storage.local.set({ enabled: false });
}

chrome.runtime.onInstalled.addListener(async () => {
  await enableBlocking();
});

chrome.action.onClicked.addListener(async () => {
  const { enabled } = await chrome.storage.local.get("enabled");

  if (enabled) {
    await disableBlocking();
    chrome.action.setBadgeText({ text: "OFF" });
  } else {
    await enableBlocking();
    chrome.action.setBadgeText({ text: "ON" });
  }
});

chrome.runtime.onStartup.addListener(async () => {
  const { enabled } = await chrome.storage.local.get("enabled");
  chrome.action.setBadgeText({ text: enabled ? "ON" : "OFF" });
});
```

