## `content.js`

This removes common tracking script tags that may already be present in the DOM and watches for newly added ones.

```js
const trackerPatterns = [
  /google-analytics\.com/i,
  /googletagmanager\.com/i,
  /connect\.facebook\.net/i,
  /doubleclick\.net/i,
  /analytics/i,
  /gtag\/js/i
];

function isTrackerScript(src) {
  if (!src) return false;
  return trackerPatterns.some((pattern) => pattern.test(src));
}

function removeTrackerScripts(root = document) {
  const scripts = root.querySelectorAll ? root.querySelectorAll("script[src]") : [];
  for (const script of scripts) {
    const src = script.getAttribute("src") || "";
    if (isTrackerScript(src)) {
      console.debug("Removing tracker script:", src);
      script.remove();
    }
  }
}

removeTrackerScripts();

const observer = new MutationObserver((mutations) => {
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes) {
      if (node.nodeType !== Node.ELEMENT_NODE) continue;

      if (node.tagName === "SCRIPT") {
        const src = node.getAttribute("src") || "";
        if (isTrackerScript(src)) {
          console.debug("Blocking dynamically added tracker script:", src);
          node.remove();
        }
      } else {
        removeTrackerScripts(node);
      }
    }
  }
});

observer.observe(document.documentElement || document, {
  childList: true,
  subtree: true
});
```

