## `content.js`

This reduces some common client-side tracking/fingerprinting signals. It does **not** make the browser anonymous, but it can reduce passive tracking.

```js
(() => {
  // Prevent some common analytics globals from being used if page code expects them.
  const noop = () => {};
  const noopObj = new Proxy(noop, {
    get: () => noop,
    apply: () => undefined
  });

  // Stub common tracker globals
  const defineSafeGlobal = (name, value) => {
    try {
      Object.defineProperty(window, name, {
        configurable: false,
        enumerable: false,
        writable: false,
        value
      });
    } catch (_) {}
  };

  defineSafeGlobal("ga", noop);
  defineSafeGlobal("gtag", noop);
  defineSafeGlobal("fbq", noop);
  defineSafeGlobal("hj", noop);
  defineSafeGlobal("mixpanel", noopObj);
  defineSafeGlobal("analytics", noopObj);

  // Reduce basic canvas fingerprinting by returning empty data for toDataURL in some cases.
  try {
    const originalToDataURL = HTMLCanvasElement.prototype.toDataURL;
    HTMLCanvasElement.prototype.toDataURL = function (...args) {
      try {
        if (document.visibilityState === "hidden") {
          return "data:,";
        }
      } catch (_) {}
      return originalToDataURL.apply(this, args);
    };
  } catch (_) {}

  // Reduce WebGL renderer leakage
  try {
    const getParameter = WebGLRenderingContext.prototype.getParameter;
    WebGLRenderingContext.prototype.getParameter = function (param) {
      const UNMASKED_VENDOR_WEBGL = 0x9245;
      const UNMASKED_RENDERER_WEBGL = 0x9246;

      if (param === UNMASKED_VENDOR_WEBGL) return "Blocked";
      if (param === UNMASKED_RENDERER_WEBGL) return "Blocked";

      return getParameter.apply(this, arguments);
    };
  } catch (_) {}

  // Reduce AudioContext fingerprint timing precision slightly
  try {
    const originalGetChannelData = AudioBuffer.prototype.getChannelData;
    AudioBuffer.prototype.getChannelData = function (...args) {
      const data = originalGetChannelData.apply(this, args);
      for (let i = 0; i < data.length; i += 100) {
        data[i] = Math.round(data[i] * 1000) / 1000;
      }
      return data;
    };
  } catch (_) {}
})();
```

