## Example: add per-site allowlisting

If you want, here is a simple `background.js` that supports toggling protection for the current site using dynamic rules and storage:

```js
const DISABLED_SITES_KEY = "disabledSites";

async function getDisabledSites() {
  const data = await chrome.storage.local.get(DISABLED_SITES_KEY);
  return data[DISABLED_SITES_KEY] || [];
}

async function setDisabledSites(sites) {
  await chrome.storage.local.set({ [DISABLED_SITES_KEY]: sites });
}

chrome.runtime.onInstalled.addListener(() => {
  console.log("Privacy Tracker Blocker installed.");
});

chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.url) return;

  const url = new URL(tab.url);
  const hostname = url.hostname;

  let disabledSites = await getDisabledSites();

  if (disabledSites.includes(hostname)) {
    disabledSites = disabledSites.filter((site) => site !== hostname);
    await setDisabledSites(disabledSites);

    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: [1000 + hostname.length]
    });

    console.log(`Protection re-enabled for ${hostname}`);
  } else {
    disabledSites.push(hostname);
    await setDisabledSites(disabledSites);

    await chrome.declarativeNetRequest.updateDynamicRules({
      addRules: [
        {
          id: 1000 + hostname.length,
          priority: 100,
          action: { "type": "allowAllRequests" },
          condition: {
            "requestDomains": [hostname],
            "resourceTypes": [
              "main_frame",
              "sub_frame",
              "script",
              "image",
              "xmlhttprequest",
              "stylesheet",
              "font",
              "media",
              "ping",
              "other"
            ]
          }
        }
      ],
      removeRuleIds: []
    });

    console.log(`Protection disabled for ${hostname}`);
  }
});
```

That example is only a prototype: using `1000 + hostname.length` for rule IDs can collide. A production version should use a proper deterministic ID mapping.

