## `background.js`

This handles enabling/disabling the static ruleset.

```javascript
const RULESET_ID = "tracker_rules";
const STORAGE_KEY = "blockingEnabled";

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get(STORAGE_KEY);
  if (data[STORAGE_KEY] === undefined) {
    await chrome.storage.local.set({ [STORAGE_KEY]: true });
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  }
});

chrome.runtime.onStartup.addListener(async () => {
  syncRulesetState();
});

chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "local" && changes[STORAGE_KEY]) {
    syncRulesetState();
  }
});

async function syncRulesetState() {
  const data = await chrome.storage.local.get(STORAGE_KEY);
  const enabled = data[STORAGE_KEY] !== false;

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });
}
```

