## `background.js`

Tracks how many requests were blocked and updates the badge.

```javascript
let blockedCount = 0;

async function updateBadge() {
  const text = blockedCount > 0 ? String(blockedCount) : "";
  await chrome.action.setBadgeBackgroundColor({ color: "#b91c1c" });
  await chrome.action.setBadgeText({ text });
}

chrome.runtime.onInstalled.addListener(async () => {
  await chrome.storage.local.set({ blockedCount: 0 });
  blockedCount = 0;
  await updateBadge();
});

chrome.runtime.onStartup.addListener(async () => {
  const data = await chrome.storage.local.get("blockedCount");
  blockedCount = data.blockedCount || 0;
  await updateBadge();
});

chrome.declarativeNetRequest.onRuleMatchedDebug.addListener(async () => {
  blockedCount += 1;
  await chrome.storage.local.set({ blockedCount });
  await updateBadge();
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getBlockedCount") {
    sendResponse({ blockedCount });
    return true;
  }

  if (message.type === "resetBlockedCount") {
    blockedCount = 0;
    chrome.storage.local.set({ blockedCount }).then(updateBadge);
    sendResponse({ blockedCount });
    return true;
  }
});
```

