## `background.js`

This script intercepts outgoing requests and blocks ones matching the tracker list.

```js
importScripts("blocklist.js");

let blockedCount = 0;
let extensionEnabled = true;

function isTrackerUrl(url) {
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname.toLowerCase();

    return TRACKER_DOMAINS.some(domain =>
      hostname === domain || hostname.endsWith(`.${domain}`)
    );
  } catch (e) {
    return false;
  }
}

chrome.storage.local.get(["blockedCount", "extensionEnabled"], (result) => {
  blockedCount = result.blockedCount || 0;
  extensionEnabled = result.extensionEnabled !== false;
});

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!extensionEnabled) {
      return { cancel: false };
    }

    if (isTrackerUrl(details.url)) {
      blockedCount += 1;
      chrome.storage.local.set({ blockedCount });
      console.log("Blocked tracker:", details.url);
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStats") {
    sendResponse({
      blockedCount,
      extensionEnabled
    });
  }

  if (message.type === "toggleExtension") {
    extensionEnabled = !!message.enabled;
    chrome.storage.local.set({ extensionEnabled }, () => {
      sendResponse({ success: true, extensionEnabled });
    });
    return true;
  }
});
```

