## 4. `background.js`

This service worker installs the dynamic rules on startup.

```js
importScripts("rules.js");

async function installRules() {
  try {
    const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
    const existingRuleIds = existingRules.map(rule => rule.id);

    if (existingRuleIds.length > 0) {
      await chrome.declarativeNetRequest.updateDynamicRules({
        removeRuleIds: existingRuleIds
      });
    }

    await chrome.declarativeNetRequest.updateDynamicRules({
      addRules: TRACKER_RULES
    });

    await chrome.storage.local.set({
      enabled: true,
      blockedCount: 0
    });

    console.log("Tracker blocking rules installed.");
  } catch (err) {
    console.error("Failed to install rules:", err);
  }
}

chrome.runtime.onInstalled.addListener(() => {
  installRules();
});

chrome.runtime.onStartup.addListener(() => {
  installRules();
});

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener(async (info) => {
  const result = await chrome.storage.local.get(["blockedCount", "enabled"]);
  const blockedCount = result.blockedCount || 0;
  if (result.enabled) {
    await chrome.storage.local.set({ blockedCount: blockedCount + 1 });
  }
});
```

