## 6. `popup.js`

```js
async function refreshUI() {
  const data = await chrome.storage.local.get(["enabled", "blockedCount"]);
  const enabled = data.enabled ?? true;
  const blockedCount = data.blockedCount ?? 0;

  document.getElementById("status").textContent = enabled ? "Enabled" : "Disabled";
  document.getElementById("count").textContent = blockedCount;
  document.getElementById("toggleBtn").textContent = enabled ? "Disable" : "Enable";
}

async function setBlocking(enabled) {
  const dynamicRules = await chrome.declarativeNetRequest.getDynamicRules();
  const ruleIds = dynamicRules.map(rule => rule.id);

  if (enabled) {
    const rulesModule = await fetch(chrome.runtime.getURL("rules.js")).then(r => r.text());

    // Eval avoided in production; this is just a simple starter approach.
    // Better approach: store rules in JSON.
    const sandbox = {};
    new Function(`${rulesModule}; this.TRACKER_RULES = TRACKER_RULES;`).call(sandbox);

    await chrome.declarativeNetRequest.updateDynamicRules({
      addRules: sandbox.TRACKER_RULES
    });
  } else {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: ruleIds
    });
  }

  await chrome.storage.local.set({ enabled });
  await refreshUI();
}

document.getElementById("toggleBtn").addEventListener("click", async () => {
  const data = await chrome.storage.local.get("enabled");
  const enabled = !(data.enabled ?? true);
  await setBlocking(enabled);
});

refreshUI();
```

