## 10. Safer improved toggle approach

Instead of loading rules in the popup, move all rule management to the background script and message it.

### Updated `background.js`

```js
importScripts("rules.js");

async function enableBlocking() {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingRuleIds = existingRules.map(rule => rule.id);

  if (existingRuleIds.length) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingRuleIds
    });
  }

  await chrome.declarativeNetRequest.updateDynamicRules({
    addRules: TRACKER_RULES
  });

  await chrome.storage.local.set({ enabled: true });
}

async function disableBlocking() {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingRuleIds = existingRules.map(rule => rule.id);

  if (existingRuleIds.length) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingRuleIds
    });
  }

  await chrome.storage.local.set({ enabled: false });
}

async function initialize() {
  const { enabled } = await chrome.storage.local.get("enabled");
  if (enabled === false) {
    await disableBlocking();
  } else {
    await enableBlocking();
    const { blockedCount } = await chrome.storage.local.get("blockedCount");
    if (blockedCount === undefined) {
      await chrome.storage.local.set({ blockedCount: 0 });
    }
  }
}

chrome.runtime.onInstalled.addListener(initialize);
chrome.runtime.onStartup.addListener(initialize);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "GET_STATE") {
    chrome.storage.local.get(["enabled", "blockedCount"]).then(data => {
      sendResponse({
        enabled: data.enabled ?? true,
        blockedCount: data.blockedCount ?? 0
      });
    });
    return true;
  }

  if (message.type === "TOGGLE_BLOCKING") {
    chrome.storage.local.get("enabled").then(async ({ enabled }) => {
      const nextState = !(enabled ?? true);
      if (nextState) {
        await enableBlocking();
      } else {
        await disableBlocking();
      }

      const data = await chrome.storage.local.get(["enabled", "blockedCount"]);
      sendResponse({
        enabled: data.enabled ?? true,
        blockedCount: data.blockedCount ?? 0
      });
    });
    return true;
  }
});

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener(async () => {
  const { enabled = true, blockedCount = 0 } = await chrome.storage.local.get([
    "enabled",
    "blockedCount"
  ]);

  if (!enabled) return;

  await chrome.storage.local.set({ blockedCount: blockedCount + 1 });
});
```

