## 5. `popup.js`

```javascript
const toggleBtn = document.getElementById("toggleBtn");
const statusText = document.getElementById("statusText");

function render(enabled) {
  toggleBtn.textContent = enabled ? "Disable" : "Enable";
  statusText.textContent = enabled
    ? "Tracking protection is ON."
    : "Tracking protection is OFF.";
}

async function getStatus() {
  return chrome.runtime.sendMessage({ type: "GET_STATUS" });
}

async function setStatus(enabled) {
  return chrome.runtime.sendMessage({ type: "SET_STATUS", enabled });
}

async function init() {
  try {
    const response = await getStatus();
    const enabled = response?.enabled !== false;
    render(enabled);

    toggleBtn.addEventListener("click", async () => {
      toggleBtn.disabled = true;
      try {
        const current = (await getStatus())?.enabled !== false;
        const next = !current;
        const result = await setStatus(next);

        if (result?.success) {
          render(next);
        } else {
          statusText.textContent = "Failed to update setting.";
        }
      } finally {
        toggleBtn.disabled = false;
      }
    });
  } catch (error) {
    statusText.textContent = "Error loading extension state.";
    console.error(error);
  }
