## 2. `background.js`

This initializes default settings and tracks blocked request counts in memory.

```js
const DEFAULT_SETTINGS = {
  blockingEnabled: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  await chrome.storage.sync.set({
    blockingEnabled: existing.blockingEnabled
  });
  await updateRulesetState(existing.blockingEnabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const settings = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  await updateRulesetState(settings.blockingEnabled);
});

async function updateRulesetState(enabled) {
  const rulesetId = "tracker_rules";

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [rulesetId],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [rulesetId]
    });
  }
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "getBlockingStatus") {
    chrome.storage.sync.get(DEFAULT_SETTINGS).then((settings) => {
      sendResponse({ blockingEnabled: settings.blockingEnabled });
    });
    return true;
  }

  if (message?.type === "setBlockingStatus") {
    const enabled = Boolean(message.enabled);

    chrome.storage.sync.set({ blockingEnabled: enabled }).then(async () => {
      await updateRulesetState(enabled);
      sendResponse({ success: true, blockingEnabled: enabled });
    });

    return true;
  }
});
```

