This lets the user enable or disable the static ruleset.

```javascript
const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");
const RULESET_ID = "tracker-rules";

async function getEnabledState() {
  const result = await chrome.storage.local.get(["blockingEnabled"]);
  return result.blockingEnabled !== false;
}

async function setEnabledState(enabled) {
  await chrome.storage.local.set({ blockingEnabled: enabled });

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });

  render(enabled);
}

function render(enabled) {
  statusEl.textContent = enabled ? "Protection is ON" : "Protection is OFF";
  toggleBtn.textContent = enabled ? "Disable Blocking" : "Enable Blocking";
  toggleBtn.classList.toggle("off", enabled);
}

toggleBtn.addEventListener("click", async () => {
  const enabled = await getEnabledState();
  await setEnabledState(!enabled);
});

(async function init() {
  const enabled = await getEnabledState();
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });
  render(enabled);
})();
```

