async function updateUI() {
  const { blockingEnabled = true, blockedCount = 0 } =
    await chrome.storage.local.get(["blockingEnabled", "blockedCount"]);

  document.getElementById("status").textContent = blockingEnabled ? "Enabled" : "Disabled";
  document.getElementById("blockedCount").textContent = blockedCount;
  document.getElementById("toggleButton").textContent = blockingEnabled
    ? "Disable Blocking"
    : "Enable Blocking";
}

async function setRulesEnabled(enabled) {
  const rulesetId = "tracker_rules";

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [rulesetId]
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: [rulesetId]
    });
  }

  await chrome.storage.local.set({ blockingEnabled: enabled });
  await updateUI();
}

document.getElementById("toggleButton").addEventListener("click", async () => {
  const { blockingEnabled = true } = await chrome.storage.local.get("blockingEnabled");
  await setRulesEnabled(!blockingEnabled);
});

document.getElementById("resetButton").addEventListener("click", async () => {
  await chrome.storage.local.set({ blockedCount: 0 });
  await updateUI();
});

document.addEventListener("DOMContentLoaded", updateUI);
