# 3. `background.js`

This service worker:

- Initializes default settings
- Tracks blocked request counts
- Updates the extension badge
- Supports enable/disable toggle

```js
const DEFAULT_SETTINGS = {
  enabled: true,
  totalBlocked: 0,
  perTabBlocked: {}
};

chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.local.get([
    "enabled",
    "totalBlocked",
    "perTabBlocked"
  ]);

  const updates = {};

  if (existing.enabled === undefined) updates.enabled = DEFAULT_SETTINGS.enabled;
  if (existing.totalBlocked === undefined) updates.totalBlocked = DEFAULT_SETTINGS.totalBlocked;
  if (existing.perTabBlocked === undefined) updates.perTabBlocked = DEFAULT_SETTINGS.perTabBlocked;

  if (Object.keys(updates).length > 0) {
    await chrome.storage.local.set(updates);
  }

  await syncRulesetState();
});

chrome.runtime.onStartup?.addListener(async () => {
  await syncRulesetState();
});

async function syncRulesetState() {
  const { enabled = true } = await chrome.storage.local.get("enabled");

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }

  await updateBadgeForAllTabs();
}

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "local" && changes.enabled) {
    await syncRulesetState();
  }
});

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener(async (info) => {
  const { enabled = true, totalBlocked = 0, perTabBlocked = {} } =
    await chrome.storage.local.get(["enabled", "totalBlocked", "perTabBlocked"]);

  if (!enabled) return;

  const tabId = info.request.tabId;

  const nextTotal = totalBlocked + 1;
  const nextPerTabBlocked = { ...perTabBlocked };

  if (tabId >= 0) {
    nextPerTabBlocked[tabId] = (nextPerTabBlocked[tabId] || 0) + 1;
    await updateBadge(tabId, nextPerTabBlocked[tabId]);
  }

  await chrome.storage.local.set({
    totalBlocked: nextTotal,
    perTabBlocked: nextPerTabBlocked
  });
});

chrome.tabs.onRemoved.addListener(async (tabId) => {
  const { perTabBlocked = {} } = await chrome.storage.local.get("perTabBlocked");
  if (perTabBlocked[tabId] !== undefined) {
    delete perTabBlocked[tabId];
    await chrome.storage.local.set({ perTabBlocked });
  }
});

chrome.tabs.onActivated.addListener(async ({ tabId }) => {
  const { perTabBlocked = {} } = await chrome.storage.local.get("perTabBlocked");
  await updateBadge(tabId, perTabBlocked[tabId] || 0);
});

chrome.tabs.onUpdated.addListener(async (tabId, changeInfo) => {
  if (changeInfo.status === "loading") {
    const { perTabBlocked = {} } = await chrome.storage.local.get("perTabBlocked");
    perTabBlocked[tabId] = 0;
    await chrome.storage.local.set({ perTabBlocked });
    await updateBadge(tabId, 0);
  }
});

async function updateBadge(tabId, count) {
  const text = count > 0 ? String(count) : "";
  await chrome.action.setBadgeBackgroundColor({ color: "#1f8b4c", tabId });
  await chrome.action.setBadgeText({ text, tabId });
}

async function updateBadgeForAllTabs() {
  const { perTabBlocked = {} } = await chrome.storage.local.get("perTabBlocked");
  const tabs = await chrome.tabs.query({});

  await Promise.all(
    tabs.map((tab) => {
      if (tab.id === undefined) return Promise.resolve();
      return updateBadge(tab.id, perTabBlocked[tab.id] || 0);
    })
  );
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "getStats") {
    chrome.storage.local
      .get(["enabled", "totalBlocked", "perTabBlocked"])
      .then(async (data) => {
        let activeTabCount = 0;
        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
        if (tab?.id !== undefined) {
          activeTabCount = data.perTabBlocked?.[tab.id] || 0;
        }

        sendResponse({
          enabled: data.enabled ?? true,
          totalBlocked: data.totalBlocked ?? 0,
          currentTabBlocked: activeTabCount
        });
      });

    return true;
  }

  if (message?.type === "setEnabled") {
    chrome.storage.local.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });

    return true;
  }

  if (message?.type === "resetStats") {
    chrome.storage.local.set({
      totalBlocked: 0,
      perTabBlocked: {}
    }).then(async () => {
      await updateBadgeForAllTabs();
      sendResponse({ ok: true });
    });

    return true;
  }
});
```

