## 3. `background.js`

This initializes extension state and toggles the ruleset on/off.

```js
const RULESET_ID = "trackers";
const STORAGE_KEY = "blockingEnabled";

chrome.runtime.onInstalled.addListener(async () => {
  const result = await chrome.storage.sync.get(STORAGE_KEY);

  if (result[STORAGE_KEY] === undefined) {
    await chrome.storage.sync.set({ [STORAGE_KEY]: true });
  }

  await syncRulesetState();
});

chrome.runtime.onStartup.addListener(async () => {
  await syncRulesetState();
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "sync" && changes[STORAGE_KEY]) {
    await syncRulesetState();
  }
});

async function syncRulesetState() {
  const result = await chrome.storage.sync.get(STORAGE_KEY);
  const enabled = result[STORAGE_KEY] !== false;

  const current = await chrome.declarativeNetRequest.getEnabledRulesets();
  const isEnabled = current.includes(RULESET_ID);

  if (enabled && !isEnabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID]
    });
  } else if (!enabled && isEnabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: [RULESET_ID]
    });
  }
}
```

