## `background.js`

This script listens for outgoing requests and cancels ones matching tracker patterns.

```js
importScripts("rules.js");

let blockingEnabled = true;
let blockedCount = 0;

chrome.storage.local.get(["blockingEnabled", "blockedCount"], (result) => {
  if (typeof result.blockingEnabled === "boolean") {
    blockingEnabled = result.blockingEnabled;
  }
  if (typeof result.blockedCount === "number") {
    blockedCount = result.blockedCount;
  }
});

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!blockingEnabled) {
      return { cancel: false };
    }

    blockedCount += 1;
    chrome.storage.local.set({ blockedCount });

    console.log("Blocked tracker:", details.url);
    return { cancel: true };
  },
  {
    urls: TRACKER_PATTERNS,
    types: ["script", "xmlhttprequest", "image", "sub_frame"]
  },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "GET_STATUS") {
    sendResponse({
      blockingEnabled,
      blockedCount
    });
  }

  if (message.type === "SET_BLOCKING") {
    blockingEnabled = !!message.enabled;
    chrome.storage.local.set({ blockingEnabled }, () => {
      sendResponse({ success: true, blockingEnabled });
    });
    return true;
  }

  if (message.type === "RESET_COUNT") {
    blockedCount = 0;
    chrome.storage.local.set({ blockedCount }, () => {
      sendResponse({ success: true, blockedCount });
    });
    return true;
  }
});
```

