  chrome.runtime.sendMessage({ type: "GET_STATUS" }, (response) => {
    if (!response) return;

    statusEl.textContent = response.blockingEnabled ? "Enabled" : "Disabled";
    countEl.textContent = response.blockedCount;
    toggleBtn.textContent = response.blockingEnabled ? "Disable" : "Enable";
