## `background.js`

```js
const TRACKER_RULES = [
  {
    id: 1,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "google-analytics.com",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  },
  {
    id: 2,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "googletagmanager.com",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  },
  {
    id: 3,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "doubleclick.net",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  },
  {
    id: 4,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "connect.facebook.net",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  },
  {
    id: 5,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "hotjar.com",
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame"]
    }
  }
];

async function enableBlocking() {
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existing.map((rule) => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds,
    addRules: TRACKER_RULES
  });

  await chrome.storage.local.set({ blockingEnabled: true });
}

async function disableBlocking() {
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existing.map((rule) => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds
  });

  await chrome.storage.local.set({ blockingEnabled: false });
}

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get(["blockingEnabled", "blockedCount"]);
  const blockingEnabled = data.blockingEnabled ?? true;
  const blockedCount = data.blockedCount ?? 0;

  await chrome.storage.local.set({ blockedCount });

  if (blockingEnabled) {
    await enableBlocking();
  } else {
    await disableBlocking();
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "GET_STATUS") {
    chrome.storage.local.get(["blockingEnabled", "blockedCount"], (data) => {
      sendResponse({
        blockingEnabled: data.blockingEnabled ?? true,
        blockedCount: data.blockedCount ?? 0
      });
    });
    return true;
  }

  if (message.type === "SET_BLOCKING") {
    (async () => {
      if (message.enabled) {
        await enableBlocking();
      } else {
        await disableBlocking();
      }

      sendResponse({ success: true });
    })();
    return true;
  }

  if (message.type === "RESET_COUNT") {
    chrome.storage.local.set({ blockedCount: 0 }, () => {
      sendResponse({ success: true, blockedCount: 0 });
    });
    return true;
  }
});

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener(async () => {
  const data = await chrome.storage.local.get("blockedCount");
  const blockedCount = (data.blockedCount ?? 0) + 1;
  await chrome.storage.local.set({ blockedCount });
});
```

