```js
importScripts("rules.js");

let blockedCount = 0;
let enabled = true;

chrome.storage.local.get(["enabled", "blockedCount"], (result) => {
  if (typeof result.enabled === "boolean") {
    enabled = result.enabled;
  }
  if (typeof result.blockedCount === "number") {
    blockedCount = result.blockedCount;
  }
});

function shouldBlock(url) {
  try {
    const parsed = new URL(url);
    return BLOCKED_PATTERNS.some(pattern => parsed.hostname.includes(pattern));
  } catch (e) {
    return false;
  }
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!enabled) {
      return { cancel: false };
    }

    const isScriptLike =
      details.type === "script" ||
      details.type === "xmlhttprequest" ||
      details.type === "ping" ||
      details.type === "image";

    if (isScriptLike && shouldBlock(details.url)) {
      blockedCount += 1;
      chrome.storage.local.set({ blockedCount });
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({ enabled, blockedCount });
    return;
