## `background.js`

```js
importScripts("rules.js");

let blockedCount = 0;
let enabled = true;

chrome.storage.local.get(["enabled", "blockedCount"], (result) => {
  enabled = result.enabled ?? true;
  blockedCount = result.blockedCount ?? 0;
  updateBadge();
});

function updateBadge() {
  chrome.action.setBadgeText({
    text: enabled ? String(blockedCount) : ""
  });
  chrome.action.setBadgeBackgroundColor({ color: "#d32f2f" });
}

function persistState() {
  chrome.storage.local.set({ enabled, blockedCount });
}

chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    if (!enabled) return;

    if (isTrackerUrl(details.url)) {
      blockedCount += 1;
      persistState();
      updateBadge();

      return { cancel: true };
    }
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    sendResponse({ enabled, blockedCount });
  }

  if (message.type === "toggleEnabled") {
    enabled = !enabled;
    persistState();
    updateBadge();
    sendResponse({ enabled, blockedCount });
  }
});
```

