## `background.js`

This initializes default settings and keeps a simple enabled/disabled state.

```js
chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.sync.get(["enabled"]);
  if (typeof data.enabled === "undefined") {
    await chrome.storage.sync.set({ enabled: true });
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getStatus") {
    chrome.storage.sync.get(["enabled"]).then((data) => {
      sendResponse({ enabled: data.enabled !== false });
    });
    return true;
  }

  if (message.type === "setStatus") {
    const enabled = Boolean(message.enabled);

    chrome.storage.sync.set({ enabled }).then(async () => {
      const rulesetId = "tracker-rules";

      if (enabled) {
        await chrome.declarativeNetRequest.updateEnabledRulesets({
          enableRulesetIds: [rulesetId],
          disableRulesetIds: []
        });
      } else {
        await chrome.declarativeNetRequest.updateEnabledRulesets({
          enableRulesetIds: [],
          disableRulesetIds: [rulesetId]
        });
      }

      sendResponse({ success: true, enabled });
    });

    return true;
  }
});
```

