# 3. `background.js`

This service worker installs the dynamic rules and tracks blocked counts locally.

```js
importScripts("rules.js");

const STORAGE_KEYS = {
  ENABLED: "enabled",
  BLOCKED_TOTAL: "blockedTotal"
};

async function getFromStorage(keys) {
  return chrome.storage.local.get(keys);
}

async function setInStorage(data) {
  return chrome.storage.local.set(data);
}

async function initializeState() {
  const data = await getFromStorage([STORAGE_KEYS.ENABLED, STORAGE_KEYS.BLOCKED_TOTAL]);

  if (typeof data[STORAGE_KEYS.ENABLED] !== "boolean") {
    await setInStorage({ [STORAGE_KEYS.ENABLED]: true });
  }

  if (typeof data[STORAGE_KEYS.BLOCKED_TOTAL] !== "number") {
    await setInStorage({ [STORAGE_KEYS.BLOCKED_TOTAL]: 0 });
  }
}

async function applyRules(enabled) {
  const existingDynamicRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existingDynamicRules.map(rule => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds,
    addRules: enabled ? TRACKER_RULES : []
  });
}

async function refreshRulesFromState() {
  const data = await getFromStorage([STORAGE_KEYS.ENABLED]);
  const enabled = data[STORAGE_KEYS.ENABLED] !== false;
  await applyRules(enabled);
}

chrome.runtime.onInstalled.addListener(async () => {
  await initializeState();
  await refreshRulesFromState();
});

chrome.runtime.onStartup.addListener(async () => {
  await initializeState();
  await refreshRulesFromState();
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName !== "local") return;

  if (changes[STORAGE_KEYS.ENABLED]) {
    const enabled = changes[STORAGE_KEYS.ENABLED].newValue !== false;
    await applyRules(enabled);
  }
});

chrome.declarativeNetRequest.onRuleMatchedDebug.addListener(async (info) => {
  const data = await getFromStorage([STORAGE_KEYS.BLOCKED_TOTAL]);
  const current = typeof data[STORAGE_KEYS.BLOCKED_TOTAL] === "number"
    ? data[STORAGE_KEYS.BLOCKED_TOTAL]
    : 0;

  await setInStorage({
    [STORAGE_KEYS.BLOCKED_TOTAL]: current + 1
  });
});
```

