## 2. `rules.js`

This file defines an initial static set of tracker patterns.

```js
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "googletagmanager.com",
  "doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "analytics.twitter.com",
  "ads-twitter.com",
  "hotjar.com",
  "segment.io",
  "cdn.segment.com",
  "mixpanel.com",
  "api.mixpanel.com"
];

function buildRules(enabled) {
  if (!enabled) return [];

  return TRACKER_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "image",
        "sub_frame"
      ]
    }
  }));
}
```

