## 3. `background.js`

This service worker installs and updates the blocking rules.

```js
importScripts("rules.js");

const RULESET_KEY = "blockingEnabled";

async function getBlockingEnabled() {
  return new Promise((resolve) => {
    chrome.storage.sync.get([RULESET_KEY], (result) => {
      resolve(result[RULESET_KEY] !== false);
    });
  });
}

async function updateRules() {
  const enabled = await getBlockingEnabled();
  const newRules = buildRules(enabled);

  chrome.declarativeNetRequest.getDynamicRules((existingRules) => {
    const existingRuleIds = existingRules.map(rule => rule.id);

    chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingRuleIds,
      addRules: newRules
    }, () => {
      if (chrome.runtime.lastError) {
        console.error("Failed to update dynamic rules:", chrome.runtime.lastError.message);
      } else {
        console.log(`Tracker blocking ${enabled ? "enabled" : "disabled"}. Rules updated.`);
      }
    });
  });
}

chrome.runtime.onInstalled.addListener(() => {
  updateRules();
});

chrome.runtime.onStartup.addListener(() => {
  updateRules();
});

chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "sync" && changes[RULESET_KEY]) {
    updateRules();
  }
});
```

