## 3. `background.js`

This background service worker tracks whether blocking is enabled and updates the extension badge.

```js
const RULESET_ID = "tracker_rules";
const BADGE_ON = "ON";
const BADGE_OFF = "OFF";

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled } = await chrome.storage.local.get("enabled");

  if (enabled === undefined) {
    await chrome.storage.local.set({ enabled: true });
  }

  await syncRulesetState();
  await updateBadge();
});

chrome.runtime.onStartup.addListener(async () => {
  await syncRulesetState();
  await updateBadge();
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "local" && changes.enabled) {
    await syncRulesetState();
    await updateBadge();
  }
});

async function syncRulesetState() {
  const { enabled } = await chrome.storage.local.get("enabled");
  const isEnabled = enabled !== false;

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: isEnabled ? [RULESET_ID] : [],
    disableRulesetIds: isEnabled ? [] : [RULESET_ID]
  });
}

async function updateBadge() {
  const { enabled } = await chrome.storage.local.get("enabled");
  const isEnabled = enabled !== false;

  await chrome.action.setBadgeText({
    text: isEnabled ? BADGE_ON : BADGE_OFF
  });

  await chrome.action.setBadgeBackgroundColor({
