## Optional improvement: block only third-party trackers

If you want to avoid breaking first-party site functionality, you can block only when the request is third-party relative to the page:

```javascript
const blockedDomains = [
  "google-analytics.com",
  "doubleclick.net",
  "googletagmanager.com",
  "facebook.net",
  "connect.facebook.net",
  "analytics.twitter.com",
  "ads-twitter.com"
];

function getHostname(url) {
  try {
    return new URL(url).hostname;
  } catch {
    return null;
  }
}

function matchesBlockedDomain(hostname) {
  return blockedDomains.some(domain =>
    hostname === domain || hostname.endsWith("." + domain)
  );
}

function isThirdParty(requestUrl, originUrl) {
  const requestHost = getHostname(requestUrl);
  const originHost = getHostname(originUrl);
  if (!requestHost || !originHost) return false;
  return requestHost !== originHost && !requestHost.endsWith("." + originHost);
}

browser.webRequest.onBeforeRequest.addListener(
  (details) => {
    const requestHost = getHostname(details.url);
    if (!requestHost || !matchesBlockedDomain(requestHost)) {
      return {};
    }

    const origin = details.originUrl || details.documentUrl || "";
    if (origin && isThirdParty(details.url, origin)) {
      console.log("Blocked third-party tracker:", details.url);
      return { cancel: true };
    }

    return {};
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);
```

