  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "CRM", "UBER", "SHOP"
    ];

    const maxTimeSteps = 80;
    const updateIntervalMs = 1000;

    let paused = false;
    let timeIndex = 0;
    let zoomTransform = d3.zoomIdentity;

    const basePrices = new Map();
    const latestPrices = new Map();
    const seriesData = [];

    symbols.forEach(symbol => {
      const base = 80 + Math.random() * 220;
      basePrices.set(symbol, base);
      latestPrices.set(symbol, base);
    });

    function generateNextDataPoint() {
      const timestamp = new Date();

      symbols.forEach(symbol => {
        const prev = latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 2.4;
        const next = Math.max(5, prev * (1 + drift / 100));
        latestPrices.set(symbol, next);

        const base = basePrices.get(symbol);
        const pctChange = ((next - base) / base) * 100;

        seriesData.push({
          symbol,
          timeIndex,
          timestamp,
          price: next,
          pctChange
        });
      });

      timeIndex++;

      const minAllowedTime = Math.max(0, timeIndex - maxTimeSteps);
      while (seriesData.length && seriesData[0].timeIndex < minAllowedTime) {
        seriesData.shift();
      }
    }

    for (let i = 0; i < maxTimeSteps; i++) {
      generateNextDataPoint();
    }

    const svg = d3.select("#chart");
    const tooltip = d3.select("#tooltip");
    const chartWrap = document.getElementById("chartWrap");

    const margin = { top: 20, right: 20, bottom: 50, left: 80 };

    const root = svg.append("g");
    const plot = root.append("g");
    const cellsGroup = plot.append("g");
    const xAxisGroup = root.append("g").attr("class", "axis");
    const yAxisGroup = root.append("g").attr("class", "axis");
    const gridGroup = plot.append("g").attr("class", "grid");

    const clipId = "plot-clip";
    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect");

    plot.attr("clip-path", `url(#${clipId})`);

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    const xScaleBase = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);
    const yScale = d3.scaleBand().domain(symbols).paddingInner(0.06).paddingOuter(0.02);

    const colorScale = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#7f1d1d", "#ef4444", "#f8fafc", "#22c55e", "#14532d"])
      .clamp(true);

    function getVisibleTimeDomain() {
      const minTime = Math.max(0, timeIndex - maxTimeSteps);
      const maxTime = timeIndex - 1;
      return d3.range(minTime, maxTime + 1);
    }

    function resize() {
      const rect = chartWrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      svg.attr("width", width).attr("height", height);

      root.attr("transform", `translate(${margin.left},${margin.top})`);

      svg.select(`#${clipId} rect`)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      xScaleBase
        .domain(getVisibleTimeDomain())
        .range([0, innerWidth]);

      yScale.range([0, innerHeight]);

      xAxisGroup.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisGroup.attr("transform", `translate(${margin.left},${margin.top})`);

      render();
    }

    function formatTimeLabel(tIndex) {
      const item = seriesData.find(d => d.timeIndex === tIndex);
      if (!item) return `${tIndex}`;
      return d3.timeFormat("%H:%M:%S")(item.timestamp);
    }

    function render() {
      const visibleDomain = getVisibleTimeDomain();
      xScaleBase.domain(visibleDomain);

      const zx = zoomTransform.rescaleX(
        d3.scaleLinear()
          .domain([0, visibleDomain.length])
          .range([0, innerWidth])
      );

      const visibleIndices = visibleDomain.map((d, i) => {
        const x0 = zx(i);
        const x1 = zx(i + 1);
        return {
          timeIndex: d,
          x: x0,
          width: Math.max(0, x1 - x0)
        };
      });

      const xPositionMap = new Map(visibleIndices.map(d => [d.timeIndex, d]));

      const filteredData = seriesData.filter(d => xPositionMap.has(d.timeIndex));

      const cells = cellsGroup.selectAll("rect.cell")
        .data(filteredData, d => `${d.symbol}-${d.timeIndex}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 1)
          .attr("ry", 1)
          .attr("x", d => xPositionMap.get(d.timeIndex).x)
          .attr("y", d => yScale(d.symbol))
          .attr("width", d => xPositionMap.get(d.timeIndex).width)
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.pctChange))
          .on("mousemove", function(event, d) {
            const [mx, my] = d3.pointer(event, chartWrap);
            tooltip
              .style("opacity", 1)
              .style("left", `${mx}px`)
              .style("top", `${my}px`)
              .html(`
                <div><strong>${d.symbol}</strong></div>
                <div>Time: ${d3.timeFormat("%H:%M:%S")(d.timestamp)}</div>
                <div>Price: $${d.price.toFixed(2)}</div>
                <div>Change: ${d.pctChange.toFixed(2)}%</div>
              `);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
          }),
        update => update
          .attr("x", d => xPositionMap.get(d.timeIndex).x)
          .attr("y", d => yScale(d.symbol))
          .attr("width", d => xPositionMap.get(d.timeIndex).width)
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.pctChange)),
        exit => exit.remove()
      );

      const xTicks = visibleIndices
        .filter((d, i) => i % Math.max(1, Math.floor(visibleIndices.length / 8)) === 0);

      const xAxis = d3.axisBottom(
        d3.scaleLinear()
          .domain([0, innerWidth])
          .range([0, innerWidth])
      )
      .tickValues(xTicks.map(d => d.x + d.width / 2))
      .tickFormat((value, i) => formatTimeLabel(xTicks[i].timeIndex));

      xAxisGroup.call(xAxis);

      const yAxis = d3.axisLeft(yScale);
      yAxisGroup.call(yAxis);

      const gridLines = gridGroup.selectAll("line.row-grid")
        .data(symbols);

      gridLines.join(
        enter => enter.append("line")
          .attr("class", "row-grid")
          .attr("x1", 0)
          .attr("x2", innerWidth)
          .attr("y1", d => yScale(d) + yScale.bandwidth())
          .attr("y2", d => yScale(d) + yScale.bandwidth())
          .attr("stroke", "#1e293b"),
        update => update
          .attr("x2", innerWidth)
          .attr("y1", d => yScale(d) + yScale.bandwidth())
          .attr("y2", d => yScale(d) + yScale.bandwidth()),
        exit => exit.remove()
      );
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        zoomTransform = event.transform;
        render();
      });

    svg.call(zoom).on("dblclick.zoom", null);

    document.getElementById("pauseBtn").addEventListener("click", () => {
      paused = !paused;
      document.getElementById("pauseBtn").textContent = paused ? "Resume" : "Pause";
      document.getElementById("status").textContent = `Live updates: ${paused ? "OFF" : "ON"}`;
    });

    document.getElementById("resetZoomBtn").addEventListener("click", () => {
      zoomTransform = d3.zoomIdentity;
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    function tick() {
      if (!paused) {
        generateNextDataPoint();
        render();
      }
    }

    window.addEventListener("resize", resize);

    resize();
    render();
    setInterval(tick, updateIntervalMs);
  </script>
</body>
</html>
```

