</head>
<body>
  <div class="container">
    <div class="title">Real-Time Stock Price Heatmap</div>
    <div class="subtitle">
      Simulated live stock percent changes across recent time windows. Use mouse wheel to zoom and drag to pan.
    </div>

    <div class="controls">
      <button id="toggleUpdates">Pause Updates</button>
      <button id="resetZoom">Reset Zoom</button>
      <div class="status" id="status">Live updates running</div>
    </div>

    <div class="panel">
      <div id="chart">
        <div class="tooltip" id="tooltip"></div>
      </div>
    </div>
  </div>

  <script>
    const tickers = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "NFLX",
      "AMD", "INTC", "CRM", "ORCL", "IBM", "UBER", "SHOP", "SQ",
      "BABA", "PYPL", "ADBE", "QCOM"
    ];

    const timeWindowSize = 60; // number of columns shown
    const updateIntervalMs = 1000;

    let isRunning = true;
    let intervalId = null;

    const chartEl = document.getElementById("chart");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 40, right: 30, bottom: 80, left: 90 };
    const width = chartEl.clientWidth;
    const height = chartEl.clientHeight;
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height)
      .style("display", "block");

    const defs = svg.append("defs");

    const root = svg.append("g");
    const zoomLayer = root.append("g");
    const plotLayer = zoomLayer.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const xAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);

    const yAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const legendG = svg.append("g")
      .attr("class", "legend")
      .attr("transform", `translate(${width - 220}, 12)`);

    // Generate initial time labels
    function generateTimeLabels(count) {
      const now = new Date();
      const labels = [];
      for (let i = count - 1; i >= 0; i--) {
        const d = new Date(now.getTime() - i * 1000);
        labels.push(d.toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit'
        }));
      }
      return labels;
    }

    let timeLabels = generateTimeLabels(timeWindowSize);

    // Simulated stock state
    const stockState = tickers.map(ticker => ({
      ticker,
      basePrice: 50 + Math.random() * 450,
      currentPrice: 50 + Math.random() * 450,
      history: []
    }));

    // Seed initial history
    for (let t = 0; t < timeWindowSize; t++) {
      stockState.forEach(stock => {
        const drift = (Math.random() - 0.5) * 0.02;
        stock.currentPrice = Math.max(5, stock.currentPrice * (1 + drift));
        const pctChange = ((stock.currentPrice - stock.basePrice) / stock.basePrice) * 100;
        stock.history.push({
          ticker: stock.ticker,
          timeIndex: t,
          timeLabel: timeLabels[t],
          price: stock.currentPrice,
          pctChange
        });
      });
    }

    function buildData() {
      return stockState.flatMap(stock => stock.history);
    }

    let data = buildData();

    const xDomain = d3.range(timeWindowSize);
    const yDomain = tickers;

    let xScale = d3.scaleBand()
      .domain(xDomain)
      .range([0, innerWidth])
      .paddingInner(0.02)
      .paddingOuter(0.01);

    let yScale = d3.scaleBand()
      .domain(yDomain)
      .range([0, innerHeight])
      .paddingInner(0.02)
      .paddingOuter(0.01);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#1f2937", "#16a34a"])
      .clamp(true);

    function renderLegend() {
      legendG.selectAll("*").remove();

      const legendWidth = 160;
      const legendHeight = 12;

      const gradientId = "heatmap-gradient";
      const gradient = defs.append("linearGradient")
        .attr("id", gradientId)
        .attr("x1", "0%")
        .attr("x2", "100%")
        .attr("y1", "0%")
        .attr("y2", "0%");

      gradient.append("stop").attr("offset", "0%").attr("stop-color", "#b91c1c");
      gradient.append("stop").attr("offset", "50%").attr("stop-color", "#1f2937");
      gradient.append("stop").attr("offset", "100%").attr("stop-color", "#16a34a");

      legendG.append("text")
        .attr("x", 0)
        .attr("y", 0)
        .attr("dy", "0.9em")
        .text("% Change");

      legendG.append("rect")
        .attr("x", 0)
        .attr("y", 20)
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", `url(#${gradientId})`)
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-5, 5])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .tickValues([-5, -2.5, 0, 2.5, 5])
        .tickFormat(d => `${d}%`);

      legendG.append("g")
        .attr("transform", `translate(0, ${20 + legendHeight})`)
        .call(legendAxis)
        .call(g => g.selectAll("text").attr("fill", "#e5e7eb"))
        .call(g => g.selectAll("line,path").attr("stroke", "#475569"));
    }

    function renderAxes(currentXScale) {
      const xAxis = d3.axisBottom(currentXScale)
        .tickValues(
          currentXScale.domain().filter((d, i) => {
            const step = Math.max(1, Math.floor(timeWindowSize / 8));
            return i % step === 0;
          })
        )
        .tickFormat(d => timeLabels[d] || "");

      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisG.call(yAxis);
    }

    function renderCells(currentXScale) {
      const cells = plotLayer.selectAll("rect.cell")
        .data(data, d => `${d.ticker}-${d.timeIndex}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => currentXScale(d.timeIndex))
          .attr("y", d => yScale(d.ticker))
          .attr("width", currentXScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.pctChange))
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 12}px`)
              .style("top", `${event.offsetY + 12}px`)
              .html(`
                <strong>${d.ticker}</strong><br/>
                Time: ${d.timeLabel}<br/>
                Price: $${d.price.toFixed(2)}<br/>
                Change: ${d.pctChange.toFixed(2)}%
              `);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
          }),
        update => update
          .transition()
          .duration(300)
          .attr("x", d => currentXScale(d.timeIndex))
          .attr("y", d => yScale(d.ticker))
          .attr("width", currentXScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.pctChange)),
        exit => exit.remove()
      );
    }

    function render(currentXScale = xScale) {
      renderAxes(currentXScale);
      renderCells(currentXScale);
      renderLegend();
    }

    function updateData() {
      timeLabels.shift();
      const now = new Date();
      timeLabels.push(
        now.toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit'
        })
      );

      stockState.forEach(stock => {
        stock.history.shift();

        const volatility = 0.008 + Math.random() * 0.01;
        const drift = (Math.random() - 0.5) * volatility * 2;
        stock.currentPrice = Math.max(5, stock.currentPrice * (1 + drift));

        const pctChange = ((stock.currentPrice - stock.basePrice) / stock.basePrice) * 100;

        stock.history.push({
          ticker: stock.ticker,
          timeIndex: timeWindowSize - 1,
          timeLabel: timeLabels[timeWindowSize - 1],
          price: stock.currentPrice,
          pctChange
        });

        stock.history = stock.history.map((point, i) => ({
          ...point,
          timeIndex: i,
          timeLabel: timeLabels[i]
        }));
      });

      data = buildData();
      render(rescaledX || xScale);
    }

    let rescaledX = null;

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
      .on("zoom", (event) => {
        const zx = event.transform.rescaleX(
          d3.scaleLinear()
            .domain([0, timeWindowSize])
            .range([0, innerWidth])
        );

        const domain = xDomain;
        const scaledBand = d3.scaleBand()
          .domain(domain)
          .range([zx(0), zx(timeWindowSize)])
          .paddingInner(0.02)
          .paddingOuter(0.01);

        rescaledX = scaledBand;
        render(rescaledX);
      });

    svg.call(zoom);

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
      rescaledX = null;
      render(xScale);
    });

    document.getElementById("toggleUpdates").addEventListener("click", (e) => {
      isRunning = !isRunning;
      e.target.textContent = isRunning ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = isRunning ? "Live updates running" : "Live updates paused";

      if (isRunning) {
        startUpdates();
      } else {
        stopUpdates();
      }
    });

    function startUpdates() {
      stopUpdates();
      intervalId = setInterval(updateData, updateIntervalMs);
    }

    function stopUpdates() {
      if (intervalId) {
        clearInterval(intervalId);
        intervalId = null;
      }
    }

    // Initial render
    render();
    startUpdates();

    // Optional: make responsive
    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
