  </style>
</head>
<body>
  <div class="container">
    <h1>Real-Time Stock Price Heatmap</h1>

    <div class="controls">
      <button id="resetZoom">Reset Zoom</button>
      <button id="pauseBtn">Pause Updates</button>
      <span class="status" id="status">Streaming simulated price changes...</span>
    </div>

    <div id="chart" class="chart-wrap">
      <canvas id="heatmap"></canvas>
      <svg class="overlay"></svg>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <div class="legend">
      <span>Negative</span>
      <div class="legend-bar"></div>
      <span>Positive</span>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "NVDA", "META", "NFLX",
      "AMD", "INTC", "ORCL", "IBM", "CRM", "UBER", "SHOP", "SQ",
      "BABA", "PYPL", "ADBE", "QCOM"
    ];

    const chartEl = document.getElementById("chart");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("svg.overlay");
    const tooltip = document.getElementById("tooltip");
    const resetZoomBtn = document.getElementById("resetZoom");
    const pauseBtn = document.getElementById("pauseBtn");
    const statusEl = document.getElementById("status");

    let width = 0;
    let height = 0;
    let margin = { top: 30, right: 20, bottom: 40, left: 70 };
    let innerWidth = 0;
    let innerHeight = 0;

    const numTimeSteps = 120; // columns visible in base view
    const timeStepMs = 1000;  // one second per column in simulation
    const rowCount = symbols.length;

    let isPaused = false;
    let transform = d3.zoomIdentity;

    // Data structure:
    // each row is a symbol, each column is a time bucket
    // value is simulated % price change in range roughly [-5, 5]
    let startTime = Date.now() - (numTimeSteps - 1) * timeStepMs;
    let times = d3.range(numTimeSteps).map(i => startTime + i * timeStepMs);

    let data = symbols.map(symbol =>
      times.map(t => ({
        symbol,
        time: t,
        value: (Math.random() - 0.5) * 2
      }))
    );

    const colorScale = d3.scaleLinear()
      .domain([-5, -2, 0, 2, 5])
      .range(["#7f1d1d", "#ef4444", "#f8fafc", "#22c55e", "#14532d"])
      .clamp(true);

    let xScale, yScale, xAxis, yAxis, xAxisG, yAxisG, zoomBehavior;

    function resize() {
      width = chartEl.clientWidth;
      height = chartEl.clientHeight;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      canvas.width = width;
      canvas.height = height;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";

      svg
        .attr("width", width)
        .attr("height", height);

      setupScales();
      setupAxes();
      draw();
    }

    function setupScales() {
      xScale = d3.scaleBand()
        .domain(times)
        .range([margin.left, margin.left + innerWidth])
        .paddingInner(0.02)
        .paddingOuter(0);

      yScale = d3.scaleBand()
        .domain(symbols)
        .range([margin.top, margin.top + innerHeight])
        .paddingInner(0.04)
        .paddingOuter(0);
    }

    function setupAxes() {
      svg.selectAll("*").remove();

      xAxis = d3.axisBottom(xScale)
        .tickValues(times.filter((d, i) => i % 10 === 0))
        .tickFormat(d => {
          const dt = new Date(d);
          return d3.timeFormat("%H:%M:%S")(dt);
        });

      yAxis = d3.axisLeft(yScale);

      xAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(0, ${margin.top + innerHeight})`)
        .call(xAxis);

      yAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(${margin.left}, 0)`)
        .call(yAxis);

      svg.append("rect")
        .attr("class", "zoom-capture")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight)
        .attr("fill", "transparent")
        .style("cursor", "grab");

      zoomBehavior = d3.zoom()
        .scaleExtent([1, 12])
        .translateExtent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .on("zoom", (event) => {
          transform = event.transform;
          draw();
          updateAxesForTransform();
        });

      svg.call(zoomBehavior);

      svg.on("mousemove", handleMouseMove);
      svg.on("mouseleave", hideTooltip);
    }

    function updateAxesForTransform() {
      // For scaleBand, zooming is approximated by transforming positions.
      // We rebuild a derived x scale using transformed coordinates.
      const transformedPositions = times.map(t => transform.applyX(xScale(t)));
      const tempScale = d3.scaleBand()
        .domain(times)
        .range([
          transformedPositions[0],
          transformedPositions[transformedPositions.length - 1] + xScale.bandwidth() * transform.k
        ])
        .paddingInner(0.02);

      const tickTimes = times.filter((d, i) => i % Math.max(1, Math.floor(10 / transform.k)) === 0);

      const updatedXAxis = d3.axisBottom(tempScale)
        .tickValues(tickTimes)
        .tickFormat(d => d3.timeFormat("%H:%M:%S")(new Date(d)));

      xAxisG.call(updatedXAxis);
      yAxisG.call(d3.axisLeft(yScale));
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      // clip drawing area
      ctx.save();
      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      const baseCellWidth = xScale.bandwidth();
      const baseCellHeight = yScale.bandwidth();

      for (let row = 0; row < data.length; row++) {
        for (let col = 0; col < data[row].length; col++) {
          const d = data[row][col];
          const x = transform.applyX(xScale(d.time));
          const y = yScale(d.symbol);
          const w = baseCellWidth * transform.k;
          const h = baseCellHeight;

          // skip offscreen cells
          if (x + w < margin.left || x > margin.left + innerWidth) continue;

          ctx.fillStyle = colorScale(d.value);
          ctx.fillRect(x, y, Math.max(1, w), h);
        }
      }

      // grid lines
      ctx.strokeStyle = "rgba(148, 163, 184, 0.08)";
      ctx.lineWidth = 1;

      for (const symbol of symbols) {
        const y = yScale(symbol);
        ctx.beginPath();
        ctx.moveTo(margin.left, y);
        ctx.lineTo(margin.left + innerWidth, y);
        ctx.stroke();
      }

      ctx.restore();
    }

    function handleMouseMove(event) {
      const [mx, my] = d3.pointer(event, svg.node());

      if (
        mx < margin.left || mx > margin.left + innerWidth ||
        my < margin.top || my > margin.top + innerHeight
      ) {
        hideTooltip();
        return;
      }

      const rowIndex = symbols.findIndex(symbol => {
        const y = yScale(symbol);
        return my >= y && my <= y + yScale.bandwidth();
      });

      if (rowIndex === -1) {
        hideTooltip();
        return;
      }

      const cellWidth = xScale.bandwidth() * transform.k;
      let colIndex = -1;

      for (let i = 0; i < times.length; i++) {
        const x = transform.applyX(xScale(times[i]));
        if (mx >= x && mx <= x + cellWidth) {
          colIndex = i;
          break;
        }
      }

      if (colIndex === -1) {
        hideTooltip();
        return;
      }

      const d = data[rowIndex][colIndex];
      tooltip.style.display = "block";
      tooltip.style.left = `${mx + 12}px`;
      tooltip.style.top = `${my + 12}px`;
      tooltip.innerHTML = `
        <div><strong>${d.symbol}</strong></div>
        <div>Time: ${d3.timeFormat("%H:%M:%S")(new Date(d.time))}</div>
        <div>Change: ${d.value.toFixed(2)}%</div>
      `;
    }

    function hideTooltip() {
      tooltip.style.display = "none";
    }

    function pushNewTimeColumn() {
      const lastTime = times[times.length - 1];
      const nextTime = lastTime + timeStepMs;

      times.push(nextTime);
      times.shift();

      for (let r = 0; r < data.length; r++) {
        const prev = data[r][data[r].length - 1].value;
        const drift = (Math.random() - 0.5) * 1.2;
        const nextValue = Math.max(-5, Math.min(5, prev + drift));

        data[r].push({
          symbol: symbols[r],
          time: nextTime,
          value: nextValue
        });
        data[r].shift();
      }

      setupScales();
      updateAxesForTransform();
      draw();
    }

    let streamTimer = setInterval(() => {
      if (!isPaused) {
        pushNewTimeColumn();
      }
    }, 1000);

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoomBehavior.transform, d3.zoomIdentity);
    });

    pauseBtn.addEventListener("click", () => {
      isPaused = !isPaused;
      pauseBtn.textContent = isPaused ? "Resume Updates" : "Pause Updates";
      statusEl.textContent = isPaused
        ? "Updates paused."
        : "Streaming simulated price changes...";
    });

    window.addEventListener("resize", resize);

    resize();
  </script>
</body>
</html>
