      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: #444;
    }

    .title {
      font-size: 18px;
      font-weight: bold;
      fill: #fff;
    }

    .subtitle {
      font-size: 12px;
      fill: #aaa;
    }
  </style>
</head>
<body>
  <div id="container">
    <div class="tooltip" id="tooltip"></div>
  </div>

  <script>
    const container = document.getElementById("container");
    const tooltip = document.getElementById("tooltip");

    const margin = { top: 70, right: 30, bottom: 60, left: 90 };
    let width = container.clientWidth - margin.left - margin.right;
    let height = container.clientHeight - margin.top - margin.bottom;

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "IBM", "CRM", "UBER"
    ];

    const timeWindow = 60; // number of columns (last 60 updates)
    const updateIntervalMs = 1000;

    // Initial synthetic prices
    const basePrices = new Map(
      symbols.map(s => [s, 100 + Math.random() * 300])
    );

    // Heatmap data: one row per symbol, each with rolling time-series cells
    let data = symbols.map(symbol => ({
      symbol,
      values: d3.range(timeWindow).map(i => ({
        t: i,
        price: basePrices.get(symbol),
        changePct: 0
      }))
    }));

    const svg = d3.select("#container")
      .append("svg");

    const root = svg.append("g");
    const chart = root.append("g");
    const xAxisGroup = root.append("g").attr("class", "axis");
    const yAxisGroup = root.append("g").attr("class", "axis");

    svg.append("text")
      .attr("class", "title")
      .attr("x", 20)
      .attr("y", 28)
      .text("Real-Time Stock Price Heatmap");

    svg.append("text")
      .attr("class", "subtitle")
      .attr("x", 20)
      .attr("y", 48)
      .text("Color shows % change from previous tick. Scroll to zoom, drag to pan.");

    let xScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    let yScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);

    // Diverging color scale: red -> neutral -> green
    const colorScale = d3.scaleSequential()
      .domain([5, -5]) // invert so green is positive if using interpolateRdYlGn
      .interpolator(d3.interpolateRdYlGn);

    let currentTransform = d3.zoomIdentity;

    function flattenData() {
      const cells = [];
      data.forEach(row => {
        row.values.forEach((d, i) => {
          cells.push({
            symbol: row.symbol,
            xIndex: i,
            price: d.price,
            changePct: d.changePct
          });
        });
      });
      return cells;
    }

    function updateDimensions() {
      width = container.clientWidth - margin.left - margin.right;
      height = container.clientHeight - margin.top - margin.bottom;

      svg.attr("width", container.clientWidth)
         .attr("height", container.clientHeight);

      root.attr("transform", `translate(${margin.left},${margin.top})`);

      xScale.domain(d3.range(timeWindow)).range([0, width]);
      yScale.domain(symbols).range([0, height]);

      xAxisGroup.attr("transform", `translate(${margin.left},${margin.top + height})`);
      yAxisGroup.attr("transform", `translate(${margin.left},${margin.top})`);

      render();
    }

    function render() {
      const cells = flattenData();

      const zx = currentTransform.rescaleX(
        d3.scaleLinear().domain([0, timeWindow]).range([0, width])
      );

      const visibleBandWidth = Math.max(1, (zx(1) - zx(0)) - 1);

      const rects = chart
        .attr("transform", `translate(${margin.left},${margin.top})`)
        .selectAll("rect.cell")
        .data(cells, d => `${d.symbol}-${d.xIndex}`);

      rects.enter()
        .append("rect")
        .attr("class", "cell")
        .merge(rects)
        .attr("x", d => zx(d.xIndex))
        .attr("y", d => yScale(d.symbol))
        .attr("width", visibleBandWidth)
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(Math.max(-5, Math.min(5, d.changePct))))
        .on("mousemove", function(event, d) {
          tooltip.style.visibility = "visible";
          tooltip.style.left = `${event.pageX + 12}px`;
          tooltip.style.top = `${event.pageY + 12}px`;
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br/>
            Time Slot: ${d.xIndex}<br/>
            Price: $${d.price.toFixed(2)}<br/>
            Change: ${d.changePct.toFixed(2)}%
          `;
          d3.select(this).attr("stroke", "#fff").attr("stroke-width", 1);
        })
        .on("mouseleave", function() {
          tooltip.style.visibility = "hidden";
          d3.select(this).attr("stroke", "none");
        });

      rects.exit().remove();

      const xAxisScale = d3.scaleLinear()
        .domain([0, timeWindow - 1])
        .range([0, width]);

      const transformedXAxis = currentTransform.rescaleX(xAxisScale);

      const xAxis = d3.axisBottom(transformedXAxis)
        .ticks(Math.min(12, timeWindow))
        .tickFormat(d => {
          const v = Math.round(d);
          return v >= 0 && v < timeWindow ? `-${timeWindow - 1 - v}s` : "";
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisGroup.call(xAxis);
      yAxisGroup.call(yAxis);
    }

    function nextPrice(prev) {
      // Simulate random walk
      const drift = (Math.random() - 0.5) * 2.5;
      return Math.max(1, prev * (1 + drift / 100));
    }

    function pushRealtimeData() {
      data = data.map(row => {
        const prev = row.values[row.values.length - 1].price;
        const price = nextPrice(prev);
        const changePct = ((price - prev) / prev) * 100;

        const nextValues = row.values.slice(1);
        nextValues.push({
          t: Date.now(),
          price,
          changePct
        });

        return {
          ...row,
          values: nextValues
        };
      });

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom)
       .on("dblclick.zoom", null);

    window.addEventListener("resize", () => {
      updateDimensions();
    });

    updateDimensions();
    render();

    // Start simulated real-time updates
    setInterval(pushRealtimeData, updateIntervalMs);
  </script>
</body>
</html>
