        </div>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "NVDA", "META", "NFLX",
      "AMD", "INTC", "BABA", "ORCL", "CRM", "UBER", "SHOP", "PYPL",
      "ADBE", "QCOM", "SNOW", "SQ"
    ];

    const timeSteps = 120; // number of visible columns
    const rowHeight = 24;
    const colWidth = 14;
    const margin = { top: 30, right: 20, bottom: 30, left: 80 };

    let isStreaming = true;
    let currentTransform = d3.zoomIdentity;

    const chartWrap = document.getElementById("chartWrap");
    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    // Simulated data: each row contains rolling price-change percentages
    let data = symbols.map(symbol => ({
      symbol,
      values: Array.from({ length: timeSteps }, () => randomChange())
    }));

    function randomChange() {
      return +(Math.random() * 10 - 5).toFixed(2); // -5% to +5%
    }

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#8b0000", "#222222", "#006400"])
      .clamp(true);

    let xScale, yScale, xAxisG, yAxisG, zoomBehavior;

    function resize() {
      width = chartWrap.clientWidth;
      height = chartWrap.clientHeight;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      canvas.width = width * devicePixelRatio;
      canvas.height = height * devicePixelRatio;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);

      svg
        .attr("width", width)
        .attr("height", height);

      xScale = d3.scaleLinear()
        .domain([0, timeSteps])
        .range([margin.left, margin.left + innerWidth]);

      yScale = d3.scaleBand()
        .domain(symbols)
        .range([margin.top, margin.top + innerHeight])
        .paddingInner(0.05);

      svg.selectAll("*").remove();

      xAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(0, ${margin.top + innerHeight})`);

      yAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(${margin.left}, 0)`);

      svg.append("clipPath")
        .attr("id", "plot-clip")
        .append("rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      zoomBehavior = d3.zoom()
        .scaleExtent([1, 12])
        .translateExtent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .extent([[margin.left, margin.top], [margin.left + innerWidth, margin.top + innerHeight]])
        .on("zoom", (event) => {
          currentTransform = event.transform;
          draw();
        });

      svg.call(zoomBehavior);

      draw();
    }

    function drawAxes(rescaledX) {
      const x = rescaledX || xScale;

      const ticks = d3.range(0, timeSteps + 1, 10);
      const xAxis = d3.axisBottom(x)
        .tickValues(ticks)
        .tickFormat(d => `T-${timeSteps - d}`);

      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      const zx = currentTransform.rescaleX(xScale);

      drawAxes(zx);

      ctx.save();

      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      for (let row = 0; row < data.length; row++) {
        const stock = data[row];
        const y = yScale(stock.symbol);

        for (let col = 0; col < stock.values.length; col++) {
          const value = stock.values[col];
          const x0 = zx(col);
          const x1 = zx(col + 1);
          const w = x1 - x0;
          const h = yScale.bandwidth();

          if (x1 < margin.left || x0 > margin.left + innerWidth) continue;

          ctx.fillStyle = colorScale(value);
          ctx.fillRect(x0, y, Math.max(1, w), h);
        }
      }

      ctx.restore();
    }

    function updateData() {
      data.forEach(stock => {
        const last = stock.values[stock.values.length - 1];
        const next = +(Math.max(-5, Math.min(5, last + (Math.random() * 1.4 - 0.7)))).toFixed(2);
        stock.values.push(next);
        if (stock.values.length > timeSteps) stock.values.shift();
      });

      draw();
    }

    function getCellFromMouse(mx, my) {
      const zx = currentTransform.rescaleX(xScale);

      const symbol = symbols.find(s => {
        const y = yScale(s);
        return my >= y && my <= y + yScale.bandwidth();
      });

      if (!symbol) return null;

      let colIndex = null;
      for (let i = 0; i < timeSteps; i++) {
        const x0 = zx(i);
        const x1 = zx(i + 1);
        if (mx >= x0 && mx <= x1) {
          colIndex = i;
          break;
        }
      }

      if (colIndex == null) return null;

      const row = data.find(d => d.symbol === symbol);
      const value = row.values[colIndex];

      return {
        symbol,
        colIndex,
        value
      };
    }

    svg.on("mousemove", function(event) {
      const [mx, my] = d3.pointer(event, this);

      if (
        mx < margin.left ||
        mx > margin.left + innerWidth ||
        my < margin.top ||
        my > margin.top + innerHeight
      ) {
        tooltip.style.display = "none";
        return;
      }

      const cell = getCellFromMouse(mx, my);
      if (!cell) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = `${mx + 14}px`;
      tooltip.style.top = `${my + 14}px`;
      tooltip.innerHTML = `
        <strong>${cell.symbol}</strong><br/>
        Time Index: ${cell.colIndex}<br/>
        Change: <span style="color:${colorScale(cell.value)}">${cell.value.toFixed(2)}%</span>
      `;
    });

    svg.on("mouseleave", () => {
      tooltip.style.display = "none";
    });

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(400).call(zoomBehavior.transform, d3.zoomIdentity);
    });

    document.getElementById("toggleStream").addEventListener("click", (e) => {
      isStreaming = !isStreaming;
      e.target.textContent = isStreaming ? "Pause" : "Resume";
      status.textContent = isStreaming
        ? "Streaming real-time updates..."
        : "Updates paused";
    });

    setInterval(() => {
      if (isStreaming) updateData();
    }, 700);

    window.addEventListener("resize", resize);

    resize();
  </script>
</body>
</html>
