socket.onmessage = (event) => {
  const updates = JSON.parse(event.data);
  // updates example:
  // [{ symbol: "AAPL", change: 1.23 }, ...]

  updates.forEach(update => {
    const stock = data.find(d => d.symbol === update.symbol);
    if (!stock) return;
    stock.values.push(update.change);
    if (stock.values.length > timeSteps) stock.values.shift();
  });

  draw();
};
