        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <div class="status" id="status">Initializing...</div>
    </div>
    <div class="chart-container" id="chart-container">
      <div class="tooltip" id="tooltip"></div>
      <svg id="heatmap"></svg>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "CRM", "ORCL", "UBER", "SHOP", "BABA"
    ];

    const timeWindow = 60; // number of columns visible in data
    const updateIntervalMs = 1000;

    const initialPrices = {
      AAPL: 190, MSFT: 420, GOOGL: 175, AMZN: 182, TSLA: 245,
      NVDA: 118, META: 505, NFLX: 640, AMD: 162, INTC: 34,
      CRM: 268, ORCL: 141, UBER: 78, SHOP: 71, BABA: 82
    };

    const data = [];
    const latestPrices = { ...initialPrices };

    function formatTime(date) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function generateNextPrice(symbol, prev) {
      const drift = (Math.random() - 0.5) * 0.012;
      const next = prev * (1 + drift);
      return Math.max(1, +next.toFixed(2));
    }

    function seedData() {
      const now = new Date();
      for (let t = timeWindow - 1; t >= 0; t--) {
        const timestamp = new Date(now.getTime() - t * updateIntervalMs);
        symbols.forEach(symbol => {
          if (t === timeWindow - 1) {
            latestPrices[symbol] = initialPrices[symbol];
          } else {
            latestPrices[symbol] = generateNextPrice(symbol, latestPrices[symbol]);
          }
          const base = initialPrices[symbol];
          const price = latestPrices[symbol];
          const pctChange = ((price - base) / base) * 100;

          data.push({
            symbol,
            timestamp,
            timeKey: timestamp.toISOString(),
            price,
            pctChange
          });
        });
      }
    }

    seedData();

    const svg = d3.select("#heatmap");
    const container = document.getElementById("chart-container");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    const margin = { top: 30, right: 20, bottom: 60, left: 80 };
    let width = container.clientWidth - margin.left - margin.right;
    let height = container.clientHeight - margin.top - margin.bottom;

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const zoomLayer = root.append("g");
    const cellsLayer = zoomLayer.append("g").attr("class", "cells");
    const labelsLayer = zoomLayer.append("g").attr("class", "labels");

    const xAxisG = root.append("g")
      .attr("class", "axis x-axis")
      .attr("transform", `translate(0,${height})`);

    const yAxisG = root.append("g")
      .attr("class", "axis y-axis");

    const gridLayer = root.append("g").attr("class", "grid");

    function getUniqueTimes() {
      return [...new Set(data.map(d => d.timeKey))]
        .sort()
        .map(k => new Date(k));
    }

    function buildScales() {
      const times = getUniqueTimes();

      const x = d3.scaleBand()
        .domain(times.map(d => d.toISOString()))
        .range([0, width])
        .paddingInner(0.02)
        .paddingOuter(0.01);

      const y = d3.scaleBand()
        .domain(symbols)
        .range([0, height])
        .paddingInner(0.03)
        .paddingOuter(0.01);

      const extent = d3.extent(data, d => d.pctChange);
      const maxAbs = Math.max(Math.abs(extent[0] || 0), Math.abs(extent[1] || 0), 0.5);

      const color = d3.scaleSequential()
        .domain([maxAbs, -maxAbs])
        .interpolator(d3.interpolateRdYlGn);

      return { x, y, color, times };
    }

    let xScale, yScale, colorScale, times;
    let currentTransform = d3.zoomIdentity;

    function render() {
      width = container.clientWidth - margin.left - margin.right;
      height = container.clientHeight - margin.top - margin.bottom;

      svg
        .attr("width", container.clientWidth)
        .attr("height", container.clientHeight);

      xAxisG.attr("transform", `translate(0,${height})`);

      ({ x: xScale, y: yScale, color: colorScale, times } = buildScales());

      const zx = currentTransform.rescaleX(
        d3.scaleLinear().domain([0, width]).range([0, width])
      );

      const transformedX = key => zx(xScale(key));
      const transformedBandwidth = xScale.bandwidth() * currentTransform.k;

      const cells = cellsLayer.selectAll("rect.cell")
        .data(data, d => `${d.symbol}-${d.timeKey}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 2)
          .attr("ry", 2)
          .attr("x", d => transformedX(d.timeKey))
          .attr("y", d => yScale(d.symbol))
          .attr("width", transformedBandwidth)
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.pctChange))
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 12}px`)
              .style("top", `${event.offsetY - 8}px`)
              .html(`
                <strong>${d.symbol}</strong><br/>
                Time: ${formatTime(new Date(d.timeKey))}<br/>
                Price: $${d.price.toFixed(2)}<br/>
                Change: ${d.pctChange.toFixed(2)}%
              `);
          })
          .on("mouseleave", () => {
            tooltip.style("opacity", 0);
          }),
        update => update,
        exit => exit.remove()
      )
      .attr("x", d => transformedX(d.timeKey))
      .attr("y", d => yScale(d.symbol))
      .attr("width", transformedBandwidth)
      .attr("height", yScale.bandwidth())
      .attr("fill", d => colorScale(d.pctChange));

      const showLabels = transformedBandwidth > 38 && yScale.bandwidth() > 18;

      const labels = labelsLayer.selectAll("text.price-label")
        .data(showLabels ? data : [], d => `${d.symbol}-${d.timeKey}`);

      labels.join(
        enter => enter.append("text")
          .attr("class", "price-label"),
        update => update,
        exit => exit.remove()
      )
      .attr("x", d => transformedX(d.timeKey) + transformedBandwidth / 2)
      .attr("y", d => yScale(d.symbol) + yScale.bandwidth() / 2)
      .text(d => d.price.toFixed(0));

      const visibleTickKeys = times
        .map(t => t.toISOString())
        .filter(key => {
          const x = transformedX(key);
          return x + transformedBandwidth >= 0 && x <= width;
        });

      const tickStep = Math.max(1, Math.ceil(visibleTickKeys.length / 8));
      const tickValues = visibleTickKeys.filter((_, i) => i % tickStep === 0);

      const xAxisScale = d3.scaleBand()
        .domain(times.map(t => t.toISOString()))
        .range([0, width]);

      xAxisG.call(
        d3.axisBottom(xAxisScale)
          .tickValues(tickValues)
          .tickFormat(d => formatTime(new Date(d)))
      );

      xAxisG.selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisG.call(d3.axisLeft(yScale));

      const rowLines = gridLayer.selectAll("line.row-grid")
        .data(symbols, d => d);

      rowLines.join(
        enter => enter.append("line").attr("class", "row-grid"),
        update => update,
        exit => exit.remove()
      )
      .attr("x1", 0)
      .attr("x2", width)
      .attr("y1", d => yScale(d) + yScale.bandwidth())
      .attr("y2", d => yScale(d) + yScale.bandwidth())
      .attr("stroke", "#1e293b");

      statusEl.textContent =
        `Symbols: ${symbols.length} | Time Window: ${timeWindow}s | Zoom: ${currentTransform.k.toFixed(2)}x`;
    }

    function pushRealtimeData() {
      const timestamp = new Date();

      // remove oldest column
      const uniqueKeys = [...new Set(data.map(d => d.timeKey))].sort();
      if (uniqueKeys.length >= timeWindow) {
        const oldest = uniqueKeys[0];
        for (let i = data.length - 1; i >= 0; i--) {
          if (data[i].timeKey === oldest) data.splice(i, 1);
        }
      }

      symbols.forEach(symbol => {
        latestPrices[symbol] = generateNextPrice(symbol, latestPrices[symbol]);
        const base = initialPrices[symbol];
        const price = latestPrices[symbol];
        const pctChange = ((price - base) / base) * 100;

        data.push({
          symbol,
          timestamp,
          timeKey: timestamp.toISOString(),
          price,
          pctChange
        });
      });

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    window.addEventListener("resize", () => {
      render();
    });

    render();
    setInterval(pushRealtimeData, updateIntervalMs);
  </script>
</body>
</html>
```

