      <div class="status" id="status">Streaming live simulated prices</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <svg id="heatmap"></svg>
      <div class="tooltip" id="tooltip"></div>
      <div class="footer-note">Mouse wheel to zoom, drag to pan</div>
    </div>
  </div>

  <script>
    const svg = d3.select("#heatmap");
    const chartWrap = document.getElementById("chartWrap");
    const tooltip = d3.select("#tooltip");

    const rowsInput = document.getElementById("rows");
    const colsInput = document.getElementById("cols");
    const speedInput = document.getElementById("speed");
    const rowsValue = document.getElementById("rowsValue");
    const colsValue = document.getElementById("colsValue");
    const speedValue = document.getElementById("speedValue");
    const toggleBtn = document.getElementById("toggleUpdates");
    const resetZoomBtn = document.getElementById("resetZoom");
    const statusEl = document.getElementById("status");

    const margin = { top: 40, right: 30, bottom: 60, left: 80 };
    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    let numRows = +rowsInput.value;
    let numCols = +colsInput.value;
    let updateSpeed = +speedInput.value;
    let updatesRunning = true;
    let updateTimer = null;

    let data = [];
    let symbols = [];

    const root = svg.append("g").attr("class", "root");
    const plotArea = root.append("g").attr("class", "plot-area");
    const cellsGroup = plotArea.append("g").attr("class", "cells");
    const xAxisGroup = root.append("g").attr("class", "axis x-axis");
    const yAxisGroup = root.append("g").attr("class", "axis y-axis");
    const legendGroup = svg.append("g").attr("class", "legend");

    let xScale = d3.scaleBand();
    let yScale = d3.scaleBand();

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#1f2937", "#16a34a"])
      .clamp(true);

    const zoom = d3.zoom()
      .scaleExtent([0.7, 12])
      .translateExtent([[-500, -500], [5000, 5000]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function generateSymbol(index) {
      const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const a = letters[index % 26];
      const b = letters[Math.floor(index / 26) % 26];
      const c = letters[Math.floor(index / (26 * 26)) % 26];
      return `${a}${b}${c}`.replace(/A/g, "").slice(0, 4) || `STK${index}`;
    }

    function createData(rows, cols) {
      const sectors = Array.from({ length: rows }, (_, i) => `Sector ${i + 1}`);
      symbols = Array.from({ length: cols }, (_, i) => generateSymbol(i + 1));

      const arr = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const basePrice = +(50 + Math.random() * 450).toFixed(2);
          const change = +(Math.random() * 6 - 3).toFixed(2);
          arr.push({
            row: r,
            col: c,
            sector: sectors[r],
            symbol: symbols[c],
            price: basePrice,
            open: basePrice - change,
            changePct: change,
            volume: Math.floor(100000 + Math.random() * 5000000)
          });
        }
      }
      return arr;
    }

    function resize() {
      const rect = chartWrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      root.attr("transform", `translate(${margin.left},${margin.top})`);

      xScale.range([0, innerWidth]).paddingInner(0.04).paddingOuter(0.02);
      yScale.range([0, innerHeight]).paddingInner(0.04).paddingOuter(0.02);

      xAxisGroup.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisGroup.attr("transform", `translate(${margin.left},${margin.top})`);

      drawLegend();
      render();
    }

    function render() {
      const rows = Array.from(new Set(data.map(d => d.sector)));
      const cols = Array.from(new Set(data.map(d => d.symbol)));

      xScale.domain(cols);
      yScale.domain(rows);

      const xAxis = d3.axisBottom(xScale)
        .tickValues(cols.filter((_, i) => i % Math.ceil(cols.length / 12) === 0));

      const yAxis = d3.axisLeft(yScale);

      xAxisGroup.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisGroup.call(yAxis);

      const cells = cellsGroup.selectAll(".cell")
        .data(data, d => `${d.row}-${d.col}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => xScale(d.symbol))
          .attr("y", d => yScale(d.sector))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.changePct))
          .on("mousemove", (event, d) => showTooltip(event, d))
          .on("mouseenter", (event, d) => showTooltip(event, d))
          .on("mouseleave", hideTooltip)
          .call(enter => enter.append("title").text(d => d.symbol)),
        update => update
          .transition()
          .duration(250)
          .attr("x", d => xScale(d.symbol))
          .attr("y", d => yScale(d.sector))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.changePct)),
        exit => exit.remove()
      );

      plotArea.attr("clip-path", null);

      const defs = svg.selectAll("defs").data([null]).join("defs");
      defs.selectAll("#clip").data([null]).join("clipPath")
        .attr("id", "clip")
        .selectAll("rect")
        .data([null])
        .join("rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      plotArea.attr("clip-path", "url(#clip)");
    }

    function drawLegend() {
      const legendWidth = 220;
      const legendHeight = 12;
      const x = width - legendWidth - 30;
      const y = 16;

      const gradientId = "legend-gradient";
      const defs = svg.selectAll("defs").data([null]).join("defs");

      const gradient = defs.selectAll(`#${gradientId}`)
        .data([null])
        .join("linearGradient")
        .attr("id", gradientId)
        .attr("x1", "0%")
        .attr("x2", "100%");

      gradient.selectAll("stop")
        .data([
          { offset: "0%", color: "#b91c1c" },
          { offset: "50%", color: "#1f2937" },
          { offset: "100%", color: "#16a34a" }
        ])
        .join("stop")
        .attr("offset", d => d.offset)
        .attr("stop-color", d => d.color);

      legendGroup.attr("transform", `translate(${x},${y})`);

      legendGroup.selectAll("text.legend-title")
        .data([null])
        .join("text")
        .attr("class", "legend-title")
        .attr("x", 0)
        .attr("y", -4)
        .text("Price Change %");

      legendGroup.selectAll("rect.legend-bar")
        .data([null])
        .join("rect")
        .attr("class", "legend-bar")
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", `url(#${gradientId})`)
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-5, 5])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .tickValues([-5, -2.5, 0, 2.5, 5])
        .tickFormat(d => `${d}%`);

      legendGroup.selectAll("g.legend-axis")
        .data([null])
        .join("g")
        .attr("class", "legend-axis")
        .attr("transform", `translate(0, ${legendHeight})`)
        .call(legendAxis);
    }

    function showTooltip(event, d) {
      const changeClass = d.changePct >= 0 ? "positive" : "negative";
      tooltip
        .style("opacity", 1)
        .html(`
          <div class="symbol">${d.symbol}</div>
          <div class="row"><span>Sector</span><span>${d.sector}</span></div>
          <div class="row"><span>Price</span><span>$${d.price.toFixed(2)}</span></div>
          <div class="row"><span>Open</span><span>$${d.open.toFixed(2)}</span></div>
          <div class="row"><span>Change</span><span class="${changeClass}">${d.changePct.toFixed(2)}%</span></div>
          <div class="row"><span>Volume</span><span>${d.volume.toLocaleString()}</span></div>
        `);

      const [mx, my] = d3.pointer(event, chartWrap);
      tooltip
        .style("left", `${mx + 12}px`)
        .style("top", `${my + 12}px`);
    }

    function hideTooltip() {
      tooltip.style("opacity", 0);
    }

    function updateRandomCells() {
      if (!updatesRunning) return;

      const count = Math.max(1, Math.floor(data.length * 0.08));
      for (let i = 0; i < count; i++) {
        const idx = Math.floor(Math.random() * data.length);
        const d = data[idx];

        const drift = (Math.random() - 0.5) * 1.2;
        d.changePct = Math.max(-5, Math.min(5, +(d.changePct + drift).toFixed(2)));

        const newPrice = d.open * (1 + d.changePct / 100);
        d.price = +newPrice.toFixed(2);

        const volumeJump = Math.floor(Math.random() * 50000);
        d.volume += volumeJump;
      }

      cellsGroup.selectAll(".cell")
        .data(data, d => `${d.row}-${d.col}`)
        .transition()
        .duration(Math.min(300, updateSpeed - 20))
        .attr("fill", d => colorScale(d.changePct));
    }

    function startUpdates() {
      stopUpdates();
      updateTimer = setInterval(updateRandomCells, updateSpeed);
    }

    function stopUpdates() {
      if (updateTimer) {
        clearInterval(updateTimer);
        updateTimer = null;
      }
    }

    function rebuildData() {
      numRows = +rowsInput.value;
      numCols = +colsInput.value;

      rowsValue.textContent = numRows;
      colsValue.textContent = numCols;

      data = createData(numRows, numCols);
      render();
    }

    function zoomed(event) {
      const t = event.transform;
      plotArea.attr("transform", `translate(${t.x},${t.y}) scale(${t.k})`);
      xAxisGroup.attr(
        "transform",
        `translate(${margin.left + t.x},${margin.top + innerHeight + t.y}) scale(${t.k},1)`
      );
      yAxisGroup.attr(
        "transform",
        `translate(${margin.left + t.x},${margin.top + t.y}) scale(1,${t.k})`
      );
    }

    rowsInput.addEventListener("input", () => {
      rebuildData();
    });

    colsInput.addEventListener("input", () => {
      rebuildData();
    });

    speedInput.addEventListener("input", () => {
      updateSpeed = +speedInput.value;
      speedValue.textContent = `${updateSpeed}ms`;
      if (updatesRunning) startUpdates();
    });

    toggleBtn.addEventListener("click", () => {
      updatesRunning = !updatesRunning;
      toggleBtn.textContent = updatesRunning ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = updatesRunning
        ? "Streaming live simulated prices"
        : "Updates paused";

      if (updatesRunning) {
        startUpdates();
      } else {
        stopUpdates();
      }
    });

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(350).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", resize);

    speedValue.textContent = `${updateSpeed}ms`;
    rowsValue.textContent = numRows;
    colsValue.textContent = numCols;

    data = createData(numRows, numCols);
    resize();
    startUpdates();
  </script>
</body>
</html>
