      color: #e2e8f0;
      border: 1px solid #334155;
      padding: 6px 10px;
      border-radius: 6px;
      cursor: pointer;
    }

    #toolbar button:hover {
      background: #334155;
    }

    #canvasWrap {
      position: relative;
      flex: 1;
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    #tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      color: #f8fafc;
      border: 1px solid #334155;
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      white-space: nowrap;
      transform: translate(12px, 12px);
      display: none;
      z-index: 10;
    }

    #legend {
      margin-left: auto;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    #legendBar {
      width: 180px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(to right, #7f1d1d, #111827, #14532d);
      border: 1px solid #334155;
    }

    .muted {
      color: #94a3b8;
    }
  </style>
</head>
<body>
  <div id="app">
    <div id="toolbar">
      <button id="resetViewBtn">Reset View</button>
      <button id="pauseBtn">Pause</button>
      <span class="muted">Wheel = Zoom, Drag = Pan, Hover = Details</span>

      <div id="legend">
        <span class="muted">Down</span>
        <div id="legendBar"></div>
        <span class="muted">Up</span>
      </div>
    </div>

    <div id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div id="tooltip"></div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, options = {}) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;

        this.dpr = Math.max(1, window.devicePixelRatio || 1);

        this.symbols = options.symbols || [];
        this.timeSteps = options.timeSteps || 200;

        // Data matrix: rows = symbols, cols = time
        this.data = [];
        this.prices = new Map();

        // View transform
        this.offsetX = 0;
        this.offsetY = 0;
        this.scaleX = 1;
        this.scaleY = 1;

        // Base cell sizes
        this.baseCellWidth = 12;
        this.baseCellHeight = 22;

        // Interaction
        this.isDragging = false;
        this.lastMouseX = 0;
        this.lastMouseY = 0;
        this.hoverCell = null;
        this.paused = false;

        this.initData();
        this.bindEvents();
        this.resize();
        this.render();
      }

      initData() {
        for (const symbol of this.symbols) {
          const startPrice = 50 + Math.random() * 250;
          this.prices.set(symbol, startPrice);

          const row = [];
          for (let i = 0; i < this.timeSteps; i++) {
            row.push(0);
          }
          this.data.push(row);
        }
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.lastMouseX = e.clientX;
          this.lastMouseY = e.clientY;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.isDragging) {
            const dx = e.clientX - this.lastMouseX;
            const dy = e.clientY - this.lastMouseY;
            this.offsetX += dx;
            this.offsetY += dy;
            this.lastMouseX = e.clientX;
            this.lastMouseY = e.clientY;
            this.render();
          } else {
            this.updateHover(x, y, e.clientX - rect.left, e.clientY - rect.top);
          }
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

          const worldX = (mouseX - this.offsetX) / this.scaleX;
          const worldY = (mouseY - this.offsetY) / this.scaleY;

          this.scaleX *= zoomFactor;
          this.scaleY *= zoomFactor;

          this.scaleX = Math.max(0.4, Math.min(6, this.scaleX));
          this.scaleY = Math.max(0.4, Math.min(4, this.scaleY));

          this.offsetX = mouseX - worldX * this.scaleX;
          this.offsetY = mouseY - worldY * this.scaleY;

          this.render();
        }, { passive: false });
      }

      resize() {
        const rect = this.canvas.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      resetView() {
        this.offsetX = 80;
        this.offsetY = 20;
        this.scaleX = 1;
        this.scaleY = 1;
        this.render();
      }

      updateData() {
        if (this.paused) return;

        for (let r = 0; r < this.symbols.length; r++) {
          const symbol = this.symbols[r];
          const prevPrice = this.prices.get(symbol);

          const drift = (Math.random() - 0.5) * 2.5;
          const nextPrice = Math.max(1, prevPrice + drift);

          const pctChange = ((nextPrice - prevPrice) / prevPrice) * 100;
          this.prices.set(symbol, nextPrice);

          this.data[r].shift();
          this.data[r].push(pctChange);
        }

        this.render();
      }

      valueToColor(value) {
        // Clamp around a useful range
        const min = -3;
        const max = 3;
        const v = Math.max(min, Math.min(max, value));

        if (v < 0) {
          const t = (v - min) / (0 - min);
          return this.lerpColor([127, 29, 29], [17, 24, 39], t);
        } else {
          const t = v / max;
          return this.lerpColor([17, 24, 39], [22, 163, 74], t);
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      updateHover(mouseX, mouseY, tooltipX, tooltipY) {
        const cellW = this.baseCellWidth * this.scaleX;
        const cellH = this.baseCellHeight * this.scaleY;

        const labelWidth = 80;
        const topPad = 20;

        const localX = mouseX - this.offsetX - labelWidth;
        const localY = mouseY - this.offsetY - topPad;

        if (localX < 0 || localY < 0) {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
          return;
        }

        const col = Math.floor(localX / cellW);
        const row = Math.floor(localY / cellH);

        if (
          row >= 0 &&
          row < this.symbols.length &&
          col >= 0 &&
          col < this.timeSteps
        ) {
          this.hoverCell = { row, col };

          const symbol = this.symbols[row];
          const value = this.data[row][col];

          this.tooltip.innerHTML = `
            <strong>${symbol}</strong><br/>
            Time: ${col}<br/>
            Change: ${value.toFixed(2)}%
          `;
          this.tooltip.style.left = `${tooltipX}px`;
          this.tooltip.style.top = `${tooltipY}px`;
          this.tooltip.style.display = 'block';
        } else {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
        }

        this.render();
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = '#0b1220';
        ctx.fillRect(0, 0, width, height);

        const cellW = this.baseCellWidth * this.scaleX;
        const cellH = this.baseCellHeight * this.scaleY;
        const labelWidth = 80;
        const topPad = 20;

        ctx.save();
        ctx.translate(this.offsetX, this.offsetY);

        // Draw labels
        ctx.font = '12px Arial';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = '#cbd5e1';

        for (let r = 0; r < this.symbols.length; r++) {
          const y = topPad + r * cellH + cellH / 2;
          if (y < -cellH || y > height + cellH) continue;
          ctx.fillText(this.symbols[r], 4, y);
        }

        // Draw time axis markers
        ctx.textBaseline = 'alphabetic';
        ctx.fillStyle = '#94a3b8';
        for (let c = 0; c < this.timeSteps; c += 10) {
          const x = labelWidth + c * cellW;
          if (x < -cellW || x > width + cellW) continue;
          ctx.fillText(String(c), x + 2, 12);
        }

        // Draw cells
        for (let r = 0; r < this.symbols.length; r++) {
          for (let c = 0; c < this.timeSteps; c++) {
            const x = labelWidth + c * cellW;
            const y = topPad + r * cellH;

            if (x + cellW < 0 || x > width) continue;
            if (y + cellH < 0 || y > height) continue;

            const value = this.data[r][c];
            ctx.fillStyle = this.valueToColor(value);
            ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));

            // Cell border
            ctx.strokeStyle = 'rgba(15, 23, 42, 0.35)';
            ctx.strokeRect(x, y, Math.ceil(cellW), Math.ceil(cellH));
          }
        }

        // Highlight hover cell
        if (this.hoverCell) {
          const { row, col } = this.hoverCell;
          const x = labelWidth + col * cellW;
          const y = topPad + row * cellH;

          ctx.lineWidth = 2;
          ctx.strokeStyle = '#f8fafc';
          ctx.strokeRect(x + 1, y + 1, Math.max(1, cellW - 2), Math.max(1, cellH - 2));
        }

        ctx.restore();

        // Overlay info
        ctx.fillStyle = '#cbd5e1';
        ctx.font = '12px Arial';
        ctx.fillText(
          `ZoomX: ${this.scaleX.toFixed(2)}  ZoomY: ${this.scaleY.toFixed(2)}  Offset: (${Math.round(this.offsetX)}, ${Math.round(this.offsetY)})`,
          12,
          height - 12
        );
      }
    }

    // Example symbols
    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA',
      'NVDA', 'META', 'NFLX', 'AMD', 'INTC',
      'BABA', 'ORCL', 'CRM', 'UBER', 'SHOP',
      'PYPL', 'QCOM', 'IBM', 'ADBE', 'SNOW'
    ];

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const heatmap = new StockHeatmap(canvas, tooltip, {
      symbols,
      timeSteps: 240
    });

    heatmap.resetView();

    // Simulated real-time updates
    const interval = setInterval(() => {
      heatmap.updateData();
    }, 500);

    document.getElementById('resetViewBtn').addEventListener('click', () => {
      heatmap.resetView();
    });

    document.getElementById('pauseBtn').addEventListener('click', (e) => {
      heatmap.paused = !heatmap.paused;
      e.target.textContent = heatmap.paused ? 'Resume' : 'Pause';
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `data[row][col]` stores percent change for a stock at a time slice.
- Every update:
  - old leftmost value is removed with `shift()`
  - new change is appended with `push()`

### Rendering
- Canvas draws:
  - stock labels
  - time markers
  - heatmap cells
  - hover highlight

### Color mapping
- Negative changes: red → dark neutral
- Positive changes: dark neutral → green

### Zoom and pan
- `scaleX`, `scaleY` control zoom
- `offsetX`, `offsetY` control pan
- Mouse wheel zooms around cursor position

---

## Replacing simulated data with real WebSocket data

If you have a real-time feed, replace the `setInterval` update logic with a WebSocket:

```js
const socket = new WebSocket('wss://your-stock-feed.example');

socket.onmessage = (event) => {
  const tick = JSON.parse(event.data);
  // Example tick: { symbol: "AAPL", price: 189.42 }

  const row = heatmap.symbols.indexOf(tick.symbol);
  if (row === -1) return;

  const prevPrice = heatmap.prices.get(tick.symbol) ?? tick.price;
  const pctChange = ((tick.price - prevPrice) / prevPrice) * 100;

  heatmap.prices.set(tick.symbol, tick.price);
  heatmap.data[row].shift();
  heatmap.data[row].push(pctChange);

  heatmap.render();
};
```

If you want synchronized time columns across all symbols, buffer incoming ticks and flush them on a timer.

