  </style>
</head>
<body>
  <div class="container">
    <div class="header">Real-Time Stock Price Heatmap</div>
    <div class="chart-wrapper" id="chart-wrapper">
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div><strong>Price Change (%)</strong></div>
        <div class="legend-bar"></div>
        <div style="display:flex; justify-content:space-between;">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC"
    ];

    const timeWindow = 60; // number of time columns visible
    const updateInterval = 1000; // ms

    const basePrices = {};
    const latestPrices = {};
    symbols.forEach(symbol => {
      const start = 100 + Math.random() * 900;
      basePrices[symbol] = start;
      latestPrices[symbol] = start;
    });

    let heatmapData = [];
    let timestamps = [];

    const wrapper = document.getElementById("chart-wrapper");
    const tooltip = d3.select("#tooltip");

    const margin = { top: 40, right: 20, bottom: 50, left: 80 };

    let width = wrapper.clientWidth - margin.left - margin.right;
    let height = wrapper.clientHeight - margin.top - margin.bottom;

    const svg = d3.select("#chart-wrapper")
      .append("svg");

    const rootG = svg.append("g");
    const chartG = rootG.append("g");
    const cellsG = chartG.append("g");
    const xAxisG = rootG.append("g").attr("class", "axis");
    const yAxisG = rootG.append("g").attr("class", "axis");
    const xGridG = chartG.append("g").attr("class", "grid");
    const yGridG = chartG.append("g").attr("class", "grid");

    const clipId = "clip-heatmap";
    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect");

    chartG.attr("clip-path", `url(#${clipId})`);

    let xScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    let yScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleLinear()
      .domain([-5, -2, 0, 2, 5])
      .range(["#7f1d1d", "#dc2626", "#f8fafc", "#16a34a", "#14532d"])
      .clamp(true);

    let zoomTransform = d3.zoomIdentity;

    function formatTime(ts) {
      const d = new Date(ts);
      return d3.timeFormat("%H:%M:%S")(d);
    }

    function generateNextTick() {
      const ts = Date.now();
      timestamps.push(ts);

      if (timestamps.length > timeWindow) {
        timestamps.shift();
      }

      symbols.forEach(symbol => {
        const drift = (Math.random() - 0.5) * 0.02;
        latestPrices[symbol] *= (1 + drift);

        const pctChange = ((latestPrices[symbol] - basePrices[symbol]) / basePrices[symbol]) * 100;

        heatmapData.push({
          symbol,
          timestamp: ts,
          price: latestPrices[symbol],
          pctChange
        });
      });

      const minTimestamp = timestamps[0];
      heatmapData = heatmapData.filter(d => d.timestamp >= minTimestamp);
    }

    function resize() {
      width = wrapper.clientWidth - margin.left - margin.right;
      height = wrapper.clientHeight - margin.top - margin.bottom;

      svg
        .attr("width", wrapper.clientWidth)
        .attr("height", wrapper.clientHeight);

      rootG.attr("transform", `translate(${margin.left},${margin.top})`);

      svg.select(`#${clipId} rect`)
        .attr("width", width)
        .attr("height", height);

      xAxisG.attr("transform", `translate(${margin.left},${margin.top + height})`);
      yAxisG.attr("transform", `translate(${margin.left},${margin.top})`);

      chartG.attr("transform", `translate(${margin.left},${margin.top})`);

      updateScales();
      render();
    }

    function updateScales() {
      xScale.domain(timestamps.map(String)).range([0, width]);
      yScale.domain(symbols).range([0, height]);
    }

    function getZoomedXScale() {
      const base = d3.scaleBand()
        .domain(timestamps.map(String))
        .range([0, width])
        .paddingInner(0.02)
        .paddingOuter(0.01);

      const domain = base.domain();
      const positions = domain.map(d => zoomTransform.applyX(base(d)));
      const bandwidth = base.bandwidth() * zoomTransform.k;

      return { base, positions, bandwidth };
    }

    function renderAxes() {
      const { base, positions, bandwidth } = getZoomedXScale();

      const tickValues = [];
      const tickLabels = [];

      base.domain().forEach((d, i) => {
        const x = positions[i];
        if (x + bandwidth >= 0 && x <= width) {
          if (i % Math.max(1, Math.floor(timestamps.length / 8)) === 0) {
            tickValues.push(d);
            tickLabels.push({
              value: d,
              x: x + bandwidth / 2
            });
          }
        }
      });

      xAxisG.selectAll("*").remove();
      yAxisG.selectAll("*").remove();
      xGridG.selectAll("*").remove();
      yGridG.selectAll("*").remove();

      xAxisG.append("line")
        .attr("x1", 0)
        .attr("x2", width)
        .attr("y1", 0)
        .attr("y2", 0)
        .attr("stroke", "#475569");

      tickLabels.forEach(t => {
        xAxisG.append("line")
          .attr("x1", t.x)
          .attr("x2", t.x)
          .attr("y1", 0)
          .attr("y2", 6)
          .attr("stroke", "#475569");

        xAxisG.append("text")
          .attr("x", t.x)
          .attr("y", 20)
          .attr("text-anchor", "middle")
          .attr("fill", "#cbd5e1")
          .style("font-size", "11px")
          .text(formatTime(+t.value));

        xGridG.append("line")
          .attr("x1", t.x)
          .attr("x2", t.x)
          .attr("y1", 0)
          .attr("y2", height)
          .attr("stroke", "rgba(148, 163, 184, 0.15)");
      });

      const yAxis = d3.axisLeft(yScale);
      yAxisG.call(yAxis);

      yScale.domain().forEach(symbol => {
        const y = yScale(symbol) + yScale.bandwidth() / 2;
        yGridG.append("line")
          .attr("x1", 0)
          .attr("x2", width)
          .attr("y1", y)
          .attr("y2", y)
          .attr("stroke", "rgba(148, 163, 184, 0.12)");
      });
    }

    function render() {
      updateScales();
      renderAxes();

      const { base, positions, bandwidth } = getZoomedXScale();

      const xPosMap = new Map();
      base.domain().forEach((d, i) => {
        xPosMap.set(d, positions[i]);
      });

      const cells = cellsG.selectAll("rect.cell")
        .data(heatmapData, d => `${d.symbol}-${d.timestamp}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("rx", 2)
        .attr("ry", 2)
        .merge(cells)
        .attr("x", d => xPosMap.get(String(d.timestamp)) ?? -9999)
        .attr("y", d => yScale(d.symbol))
        .attr("width", Math.max(1, bandwidth))
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.pctChange))
        .attr("stroke", "#0f172a")
        .attr("stroke-width", 0.5)
        .style("opacity", d => {
          const x = xPosMap.get(String(d.timestamp));
          return x + bandwidth < 0 || x > width ? 0 : 1;
        });

      cells
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .html(`
              <div><strong>${d.symbol}</strong></div>
              <div>Time: ${formatTime(d.timestamp)}</div>
              <div>Price: $${d.price.toFixed(2)}</div>
              <div>Change: ${d.pctChange.toFixed(2)}%</div>
            `)
            .style("left", `${event.offsetX + 16}px`)
            .style("top", `${event.offsetY + 16}px`);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        });

      cells.exit().remove();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        zoomTransform = event.transform;
        render();
      });

    svg.call(zoom);

    function initData() {
      for (let i = timeWindow - 1; i >= 0; i--) {
        const ts = Date.now() - i * updateInterval;
        timestamps.push(ts);

        symbols.forEach(symbol => {
          const drift = (Math.random() - 0.5) * 0.02;
          latestPrices[symbol] *= (1 + drift);

          const pctChange = ((latestPrices[symbol] - basePrices[symbol]) / basePrices[symbol]) * 100;

          heatmapData.push({
            symbol,
            timestamp: ts,
            price: latestPrices[symbol],
            pctChange
          });
        });
      }
    }

    initData();
    resize();
    render();

    setInterval(() => {
      generateNextTick();
      render();
    }, updateInterval);

    window.addEventListener("resize", resize);
  </script>
</body>
</html>
```

