<body>
  <div class="container">
    <div class="header">
      <h1>Real-Time Stock Price Heatmap</h1>
      <div class="controls">
        <span class="status" id="status">Streaming: ON</span>
        <button id="toggleStream">Pause</button>
        <button id="resetZoom">Reset Zoom</button>
      </div>
    </div>
    <div class="chart-wrapper" id="chart"></div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "CRM", "ORCL", "IBM", "UBER", "SHOP"
    ];

    const timeWindow = 60; // number of time columns visible
    const updateIntervalMs = 1000;

    const state = {
      streaming: true,
      data: [],
      latestPrices: new Map(),
      basePrices: new Map(),
      currentTransform: d3.zoomIdentity
    };

    // Initialize price state
    symbols.forEach(symbol => {
      const base = 100 + Math.random() * 900;
      state.basePrices.set(symbol, base);
      state.latestPrices.set(symbol, base);
    });

    // Seed initial data
    function generateInitialData() {
      const now = Date.now();
      for (let t = timeWindow - 1; t >= 0; t--) {
        const ts = now - t * updateIntervalMs;
        symbols.forEach(symbol => {
          let prev = state.latestPrices.get(symbol);
          const next = simulatePrice(prev);
          state.latestPrices.set(symbol, next);
          state.data.push({
            symbol,
            timestamp: ts,
            price: next,
            changePct: ((next - state.basePrices.get(symbol)) / state.basePrices.get(symbol)) * 100
          });
        });
      }
    }

    function simulatePrice(prev) {
      const drift = (Math.random() - 0.5) * 2.5;
      const volatility = prev * 0.0025;
      return Math.max(5, prev + drift + (Math.random() - 0.5) * volatility);
    }

    generateInitialData();

    const container = document.getElementById("chart");
    const tooltip = d3.select(container)
      .append("div")
      .attr("class", "tooltip");

    const margin = { top: 30, right: 30, bottom: 50, left: 80 };
    let width = container.clientWidth - margin.left - margin.right;
    let height = container.clientHeight - margin.top - margin.bottom;

    const svg = d3.select(container)
      .append("svg");

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const clipId = "clip-heatmap";

    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect");

    const plotArea = root.append("g")
      .attr("clip-path", `url(#${clipId})`);

    const heatmapLayer = plotArea.append("g");
    const gridLayer = root.append("g").attr("class", "grid");
    const xAxisG = root.append("g").attr("class", "axis x-axis");
    const yAxisG = root.append("g").attr("class", "axis y-axis");

    const legendG = svg.append("g").attr("class", "legend");

    const xScale = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    const yScale = d3.scaleBand().domain(symbols).paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleSequential()
      .interpolator(d3.interpolateRdYlGn);

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [container.clientWidth, container.clientHeight]])
      .extent([[0, 0], [container.clientWidth, container.clientHeight]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function getVisibleTimestamps() {
      const timestamps = [...new Set(state.data.map(d => d.timestamp))].sort((a, b) => a - b);
      return timestamps.slice(-timeWindow);
    }

    function updateScales() {
      width = container.clientWidth - margin.left - margin.right;
      height = container.clientHeight - margin.top - margin.bottom;

      svg
        .attr("width", container.clientWidth)
        .attr("height", container.clientHeight);

      svg.select(`#${clipId} rect`)
        .attr("width", width)
        .attr("height", height);

      xAxisG.attr("transform", `translate(0,${height})`);

      const timestamps = getVisibleTimestamps();

      xScale
        .domain(timestamps)
        .range([0, width]);

      yScale
        .range([0, height]);

      const visibleData = state.data.filter(d => timestamps.includes(d.timestamp));
      const maxAbs = d3.max(visibleData, d => Math.abs(d.changePct)) || 1;
      colorScale.domain([-maxAbs, maxAbs]);

      legendG.attr("transform", `translate(${margin.left}, 8)`);
    }

    function renderAxes(transform = d3.zoomIdentity) {
      const zx = transform.rescaleX(d3.scaleLinear()
        .domain([0, width])
        .range([0, width]));

      const timestamps = xScale.domain();
      const positions = timestamps.map(ts => xScale(ts) + xScale.bandwidth() / 2);

      const transformedPositions = positions.map(p => zx(p));

      const tickData = timestamps.map((ts, i) => ({
        ts,
        x: transformedPositions[i]
      })).filter(d => d.x >= -80 && d.x <= width + 80);

      const xAxis = g => {
        g.selectAll("*").remove();
        g.append("line")
          .attr("x1", 0)
          .attr("x2", width)
          .attr("y1", 0)
          .attr("y2", 0)
          .attr("stroke", "#475569");

        g.selectAll("g.tick")
          .data(tickData.filter((_, i) => i % Math.ceil(tickData.length / 8 || 1) === 0))
          .join("g")
          .attr("class", "tick")
          .attr("transform", d => `translate(${d.x},0)`)
          .call(gTick => {
            gTick.append("line")
              .attr("y2", 6)
              .attr("stroke", "#475569");

            gTick.append("text")
              .attr("fill", "#cbd5e1")
              .attr("y", 20)
              .attr("text-anchor", "middle")
              .text(d => d3.timeFormat("%H:%M:%S")(new Date(d.ts)));
          });
      };

      const yAxis = d3.axisLeft(yScale).tickSize(0);

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);
      yAxisG.selectAll("text").attr("dx", "-0.5em");
      yAxisG.select(".domain").remove();
    }

    function renderGrid(transform = d3.zoomIdentity) {
      gridLayer.selectAll("*").remove();

      const zx = transform.rescaleX(d3.scaleLinear()
        .domain([0, width])
        .range([0, width]));

      const timestamps = xScale.domain();

      timestamps.forEach(ts => {
        const x = xScale(ts);
        const xCenter = x + xScale.bandwidth() / 2;
        const tx = zx(xCenter);
        gridLayer.append("line")
          .attr("x1", tx)
          .attr("x2", tx)
          .attr("y1", 0)
          .attr("y2", height)
          .attr("stroke", "#1e293b");
      });

      symbols.forEach(sym => {
        const y = yScale(sym) + yScale.bandwidth() / 2;
        gridLayer.append("line")
          .attr("x1", 0)
          .attr("x2", width)
          .attr("y1", y)
          .attr("y2", y)
          .attr("stroke", "#1e293b");
      });
    }

    function renderLegend() {
      legendG.selectAll("*").remove();

      const legendWidth = 220;
      const legendHeight = 10;

      const defs = svg.select("defs");
      defs.select("#legend-gradient").remove();

      const gradient = defs.append("linearGradient")
        .attr("id", "legend-gradient")
        .attr("x1", "0%")
        .attr("x2", "100%")
        .attr("y1", "0%")
        .attr("y2", "0%");

      const stops = d3.range(0, 1.01, 0.1);
      stops.forEach(s => {
        gradient.append("stop")
          .attr("offset", `${s * 100}%`)
          .attr("stop-color", colorScale(
            colorScale.domain()[0] + s * (colorScale.domain()[1] - colorScale.domain()[0])
          ));
      });

      legendG.append("text")
        .attr("x", 0)
        .attr("y", 0)
        .attr("dominant-baseline", "hanging")
        .text("Price Change %");

      legendG.append("rect")
        .attr("x", 110)
        .attr("y", 2)
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", "url(#legend-gradient)")
        .attr("stroke", "#475569");

      legendG.append("text")
        .attr("x", 105)
        .attr("y", 22)
        .attr("text-anchor", "end")
        .text(`${colorScale.domain()[0].toFixed(2)}%`);

      legendG.append("text")
        .attr("x", 110 + legendWidth / 2)
        .attr("y", 22)
        .attr("text-anchor", "middle")
        .text("0%");

      legendG.append("text")
        .attr("x", 110 + legendWidth + 5)
        .attr("y", 22)
        .attr("text-anchor", "start")
        .text(`${colorScale.domain()[1].toFixed(2)}%`);
    }

    function renderHeatmap(transform = d3.zoomIdentity) {
      const timestamps = getVisibleTimestamps();
      const visibleData = state.data.filter(d => timestamps.includes(d.timestamp));

      const zx = transform.rescaleX(d3.scaleLinear()
        .domain([0, width])
        .range([0, width]));

      const cells = heatmapLayer.selectAll("rect.cell")
        .data(visibleData, d => `${d.symbol}-${d.timestamp}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("rx", 1)
        .attr("ry", 1)
        .merge(cells)
        .attr("x", d => {
          const baseX = xScale(d.timestamp);
          return zx(baseX);
        })
        .attr("y", d => yScale(d.symbol))
        .attr("width", Math.max(1, zx(xScale(d.timestamp) + xScale.bandwidth()) - zx(xScale(d.timestamp))))
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.changePct))
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Time: ${d3.timeFormat("%H:%M:%S")(new Date(d.timestamp))}<br/>
              Price: $${d.price.toFixed(2)}<br/>
              Change: ${d.changePct.toFixed(2)}%
            `)
            .style("left", `${event.offsetX + 16}px`)
            .style("top", `${event.offsetY + 16}px`);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        });

      cells.exit().remove();
    }

    function zoomed(event) {
      state.currentTransform = event.transform;
      renderAxes(state.currentTransform);
      renderGrid(state.currentTransform);
      renderHeatmap(state.currentTransform);
    }

    function render() {
      updateScales();
      renderAxes(state.currentTransform);
      renderGrid(state.currentTransform);
      renderHeatmap(state.currentTransform);
      renderLegend();
    }

    function pushNewDataPoint() {
      const ts = Date.now();

      symbols.forEach(symbol => {
        const prev = state.latestPrices.get(symbol);
        const next = simulatePrice(prev);
        state.latestPrices.set(symbol, next);

        state.data.push({
          symbol,
          timestamp: ts,
          price: next,
          changePct: ((next - state.basePrices.get(symbol)) / state.basePrices.get(symbol)) * 100
        });
      });

      const timestamps = getVisibleTimestamps();
      const minVisibleTs = timestamps[0];

      state.data = state.data.filter(d => d.timestamp >= minVisibleTs);
    }

    let streamTimer = setInterval(() => {
      if (!state.streaming) return;
      pushNewDataPoint();
      render();
    }, updateIntervalMs);

    document.getElementById("toggleStream").addEventListener("click", () => {
      state.streaming = !state.streaming;
      document.getElementById("status").textContent = `Streaming: ${state.streaming ? "ON" : "OFF"}`;
      document.getElementById("toggleStream").textContent = state.streaming ? "Pause" : "Resume";
    });

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", () => {
      render();
    });

    render();
  </script>
</body>
</html>
```

