      min-width: 160px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(10px, 10px);
      transition: opacity 0.08s linear;
    }

    .legend {
      position: absolute;
      right: 16px;
      bottom: 16px;
      background: rgba(18, 25, 51, 0.92);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px;
      color: var(--text);
      font-size: 12px;
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      border-radius: 999px;
      margin-bottom: 6px;
      background: linear-gradient(
        to right,
        #7f0000 0%,
        #d73027 20%,
        #f46d43 35%,
        #f7f7f7 50%,
        #74add1 65%,
        #4575b4 80%,
        #313695 100%
      );
      border: 1px solid rgba(255,255,255,0.12);
    }

    .legend-labels {
      display: flex;
      justify-content: space-between;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>

      <div class="group">
        <button id="toggleStream">Pause</button>
        <button id="resetZoom">Reset Zoom</button>
      </div>

      <div class="group">
        <label for="speed">Update speed</label>
        <select id="speed">
          <option value="250">250ms</option>
          <option value="500" selected>500ms</option>
          <option value="1000">1000ms</option>
        </select>
      </div>

      <div class="group">
        <label for="windowSize">Time window</label>
        <select id="windowSize">
          <option value="60">60 points</option>
          <option value="120" selected>120 points</option>
          <option value="240">240 points</option>
        </select>
      </div>

      <div class="status" id="status">Streaming</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor({ canvas, container, tooltip }) {
        this.canvas = canvas;
        this.ctx = canvas.getContext("2d");
        this.container = container;
        this.tooltip = tooltip;

        this.margin = { top: 20, right: 20, bottom: 40, left: 80 };
        this.dpr = window.devicePixelRatio || 1;

        this.symbols = [
          "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
          "META", "TSLA", "NFLX", "AMD", "INTC",
          "CRM", "ORCL", "IBM", "UBER", "SHOP",
          "BABA", "PYPL", "ADBE", "QCOM", "SNOW"
        ];

        this.windowSize = 120;
        this.timestamps = [];
        this.data = []; // rows = symbols, cols = time
        this.basePrices = {};
        this.currentPrices = {};

        this.isStreaming = true;
        this.updateIntervalMs = 500;
        this.timer = null;

        // zoom/pan transform in data-space for x only
        this.zoomTransform = d3.zoomIdentity;
        this.hoveredCell = null;

        this.initData();
        this.setupCanvas();
        this.setupInteraction();
        this.start();
        this.render();
      }

      initData() {
        const now = Date.now();

        this.symbols.forEach(symbol => {
          const base = 50 + Math.random() * 250;
          this.basePrices[symbol] = base;
          this.currentPrices[symbol] = base;
        });

        this.timestamps = [];
        for (let i = this.windowSize - 1; i >= 0; i--) {
          this.timestamps.push(now - i * this.updateIntervalMs);
        }

        this.data = this.symbols.map(symbol => {
          const row = [];
          let price = this.basePrices[symbol];
          for (let i = 0; i < this.windowSize; i++) {
            price = this.nextPrice(price);
            const pct = ((price - this.basePrices[symbol]) / this.basePrices[symbol]) * 100;
            row.push({
              symbol,
              timestamp: this.timestamps[i],
              price,
              pctChange: pct
            });
          }
          this.currentPrices[symbol] = row[row.length - 1].price;
          return row;
        });
      }

      nextPrice(prev) {
        const drift = (Math.random() - 0.5) * 0.8;
        const volatility = prev * 0.0025;
        return Math.max(1, prev + drift + (Math.random() - 0.5) * volatility * 2);
      }

      setupCanvas() {
        this.resize();
        window.addEventListener("resize", () => {
          this.resize();
          this.render();
        });
      }

      resize() {
        const rect = this.container.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;

        this.canvas.width = Math.floor(this.width * this.dpr);
        this.canvas.height = Math.floor(this.height * this.dpr);
        this.canvas.style.width = `${this.width}px`;
        this.canvas.style.height = `${this.height}px`;

        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);

        this.innerWidth = this.width - this.margin.left - this.margin.right;
        this.innerHeight = this.height - this.margin.top - this.margin.bottom;
      }

      setupInteraction() {
        const zoom = d3.zoom()
          .scaleExtent([1, 20])
          .translateExtent([[0, 0], [this.width, this.height]])
          .on("zoom", (event) => {
            this.zoomTransform = event.transform;
            this.render();
          });

        d3.select(this.canvas).call(zoom);

        this.zoomBehavior = zoom;

        this.canvas.addEventListener("mousemove", (e) => this.onMouseMove(e));
        this.canvas.addEventListener("mouseleave", () => {
          this.hoveredCell = null;
          this.tooltip.style.opacity = 0;
          this.render();
        });
      }

      start() {
        this.stop();
        this.timer = setInterval(() => {
          if (this.isStreaming) {
            this.pushUpdate();
            this.render();
          }
        }, this.updateIntervalMs);
      }

      stop() {
        if (this.timer) clearInterval(this.timer);
      }

      setSpeed(ms) {
        this.updateIntervalMs = ms;
        this.rebuildTimestamps();
        this.start();
      }

      setWindowSize(size) {
        this.windowSize = size;
        this.initData();
        this.render();
      }

      rebuildTimestamps() {
        // preserve existing data spacing visually by reassigning timestamps
        const now = Date.now();
        this.timestamps = [];
        for (let i = this.windowSize - 1; i >= 0; i--) {
          this.timestamps.push(now - i * this.updateIntervalMs);
        }
        this.data.forEach((row) => {
          row.forEach((cell, i) => {
            cell.timestamp = this.timestamps[i];
          });
        });
      }

      pushUpdate() {
        const ts = Date.now();
        this.timestamps.push(ts);
        if (this.timestamps.length > this.windowSize) {
          this.timestamps.shift();
        }

        this.data.forEach((row, rowIndex) => {
          const symbol = this.symbols[rowIndex];
          const newPrice = this.nextPrice(this.currentPrices[symbol]);
          this.currentPrices[symbol] = newPrice;

          const pct = ((newPrice - this.basePrices[symbol]) / this.basePrices[symbol]) * 100;
          row.push({
            symbol,
            timestamp: ts,
            price: newPrice,
            pctChange: pct
          });

          if (row.length > this.windowSize) row.shift();
        });
      }

      getXScale() {
        const base = d3.scaleLinear()
          .domain([0, this.timestamps.length])
          .range([this.margin.left, this.margin.left + this.innerWidth]);

        return this.zoomTransform.rescaleX(base);
      }

      getYScale() {
        return d3.scaleBand()
          .domain(this.symbols)
          .range([this.margin.top, this.margin.top + this.innerHeight])
          .paddingInner(0.08)
          .paddingOuter(0.02);
      }

      getColorScale() {
        return d3.scaleLinear()
          .domain([-5, -2, -0.5, 0, 0.5, 2, 5])
          .range(["#7f0000", "#d73027", "#f46d43", "#f7f7f7", "#74add1", "#4575b4", "#313695"])
          .clamp(true);
      }

      clear() {
        this.ctx.clearRect(0, 0, this.width, this.height);
        this.ctx.fillStyle = "#0b1020";
        this.ctx.fillRect(0, 0, this.width, this.height);
      }

      render() {
        this.clear();

        const ctx = this.ctx;
        const x = this.getXScale();
        const y = this.getYScale();
        const color = this.getColorScale();

        this.drawGrid(x, y);
        this.drawCells(x, y, color);
        this.drawAxes(x, y);

        if (this.hoveredCell) {
          this.drawHoverOutline(x, y);
        }
      }

      drawGrid(x, y) {
        const ctx = this.ctx;
        ctx.save();
        ctx.strokeStyle = "rgba(255,255,255,0.08)";
        ctx.lineWidth = 1;

        // Horizontal lines
        this.symbols.forEach(symbol => {
          const yy = y(symbol);
          if (yy == null) return;
          ctx.beginPath();
          ctx.moveTo(this.margin.left, yy);
          ctx.lineTo(this.margin.left + this.innerWidth, yy);
          ctx.stroke();
        });

        // Vertical lines
        for (let i = 0; i <= this.timestamps.length; i += Math.max(1, Math.floor(this.timestamps.length / 10))) {
          const xx = x(i);
          ctx.beginPath();
          ctx.moveTo(xx, this.margin.top);
          ctx.lineTo(xx, this.margin.top + this.innerHeight);
          ctx.stroke();
        }

        ctx.restore();
      }

      drawCells(x, y, color) {
        const ctx = this.ctx;
        const bandH = y.bandwidth();

        ctx.save();

        for (let rowIndex = 0; rowIndex < this.symbols.length; rowIndex++) {
          const symbol = this.symbols[rowIndex];
          const yy = y(symbol);
          const row = this.data[rowIndex];

          for (let col = 0; col < row.length; col++) {
            const x0 = x(col);
            const x1 = x(col + 1);
            const w = x1 - x0;

            if (x1 < this.margin.left || x0 > this.margin.left + this.innerWidth) continue;

            const cell = row[col];
            ctx.fillStyle = color(cell.pctChange);
            ctx.fillRect(x0, yy, Math.max(1, w), bandH);
          }
        }

        ctx.restore();
      }

      drawAxes(x, y) {
        const ctx = this.ctx;
        ctx.save();

        ctx.fillStyle = "#dbe4ff";
        ctx.strokeStyle = "rgba(255,255,255,0.2)";
        ctx.lineWidth = 1;
        ctx.font = "12px Inter, system-ui, sans-serif";

        // Y labels
        ctx.textAlign = "right";
        ctx.textBaseline = "middle";
        this.symbols.forEach(symbol => {
          const yy = y(symbol);
          if (yy == null) return;
          ctx.fillStyle = "#dbe4ff";
          ctx.fillText(symbol, this.margin.left - 10, yy + y.bandwidth() / 2);
        });

        // X axis line
        const axisY = this.margin.top + this.innerHeight;
        ctx.beginPath();
        ctx.moveTo(this.margin.left, axisY);
        ctx.lineTo(this.margin.left + this.innerWidth, axisY);
        ctx.stroke();

        // X ticks
        ctx.textAlign = "center";
        ctx.textBaseline = "top";
        const tickCount = 8;

        const visibleDomain = x.domain();
        const start = Math.max(0, Math.floor(visibleDomain[0]));
        const end = Math.min(this.timestamps.length - 1, Math.ceil(visibleDomain[1]));
        const step = Math.max(1, Math.floor((end - start) / tickCount));

        for (let i = start; i <= end; i += step) {
          const xx = x(i);
          if (xx < this.margin.left || xx > this.margin.left + this.innerWidth) continue;

          const ts = this.timestamps[Math.min(i, this.timestamps.length - 1)];
          const label = d3.timeFormat("%H:%M:%S")(new Date(ts));

          ctx.strokeStyle = "rgba(255,255,255,0.15)";
          ctx.beginPath();
          ctx.moveTo(xx, axisY);
          ctx.lineTo(xx, axisY + 6);
          ctx.stroke();

          ctx.fillStyle = "#8fa3d1";
          ctx.fillText(label, xx, axisY + 8);
        }

        ctx.restore();
      }

      drawHoverOutline(x, y) {
        const ctx = this.ctx;
        const { rowIndex, colIndex } = this.hoveredCell;
        const symbol = this.symbols[rowIndex];
        const yy = y(symbol);
        const x0 = x(colIndex);
        const x1 = x(colIndex + 1);

        ctx.save();
        ctx.strokeStyle = "rgba(255,255,255,0.95)";
        ctx.lineWidth = 2;
        ctx.strokeRect(x0 + 0.5, yy + 0.5, Math.max(1, x1 - x0 - 1), y.bandwidth() - 1);
        ctx.restore();
      }

      onMouseMove(event) {
        const rect = this.canvas.getBoundingClientRect();
        const mx = event.clientX - rect.left;
        const my = event.clientY - rect.top;

        const y = this.getYScale();
        const x = this.getXScale();

        let rowIndex = -1;
        for (let i = 0; i < this.symbols.length; i++) {
          const yy = y(this.symbols[i]);
          if (my >= yy && my <= yy + y.bandwidth()) {
            rowIndex = i;
            break;
          }
        }

        const xDomain = x.domain();
        const approxCol = Math.floor(
          ((mx - this.margin.left) / this.innerWidth) * (xDomain[1] - xDomain[0]) + xDomain[0]
        );

        if (
          rowIndex >= 0 &&
          approxCol >= 0 &&
          approxCol < this.timestamps.length &&
          mx >= this.margin.left &&
          mx <= this.margin.left + this.innerWidth &&
          my >= this.margin.top &&
          my <= this.margin.top + this.innerHeight
        ) {
          this.hoveredCell = { rowIndex, colIndex: approxCol };
          const cell = this.data[rowIndex][approxCol];
          this.showTooltip(event.clientX, event.clientY, cell);
        } else {
          this.hoveredCell = null;
          this.tooltip.style.opacity = 0;
        }

        this.render();
      }

      showTooltip(clientX, clientY, cell) {
        const pctColor = cell.pctChange >= 0 ? "#8ee28e" : "#ff8f8f";
        this.tooltip.innerHTML = `
          <div><strong>${cell.symbol}</strong></div>
          <div>Price: $${cell.price.toFixed(2)}</div>
          <div>Change: <span style="color:${pctColor}">${cell.pctChange.toFixed(2)}%</span></div>
          <div>Time: ${d3.timeFormat("%Y-%m-%d %H:%M:%S")(new Date(cell.timestamp))}</div>
        `;

        const wrapRect = this.container.getBoundingClientRect();
        const left = clientX - wrapRect.left + 12;
        const top = clientY - wrapRect.top + 12;

        this.tooltip.style.left = `${left}px`;
        this.tooltip.style.top = `${top}px`;
        this.tooltip.style.opacity = 1;
      }

      resetZoom() {
        d3.select(this.canvas)
          .transition()
          .duration(250)
          .call(this.zoomBehavior.transform, d3.zoomIdentity);
      }
    }

    const heatmap = new StockHeatmap({
      canvas: document.getElementById("heatmap"),
      container: document.getElementById("chartWrap"),
      tooltip: document.getElementById("tooltip")
    });

    const toggleBtn = document.getElementById("toggleStream");
    const resetZoomBtn = document.getElementById("resetZoom");
    const speedSelect = document.getElementById("speed");
    const windowSizeSelect = document.getElementById("windowSize");
    const status = document.getElementById("status");

    toggleBtn.addEventListener("click", () => {
      heatmap.isStreaming = !heatmap.isStreaming;
      toggleBtn.textContent = heatmap.isStreaming ? "Pause" : "Resume";
      status.textContent = heatmap.isStreaming ? "Streaming" : "Paused";
    });

    resetZoomBtn.addEventListener("click", () => {
      heatmap.resetZoom();
    });

    speedSelect.addEventListener("change", (e) => {
      heatmap.setSpeed(Number(e.target.value));
    });

    windowSizeSelect.addEventListener("change", (e) => {
      heatmap.setWindowSize(Number(e.target.value));
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each row is a stock symbol, and each column is a time step.

Each cell stores:
```js
{
  symbol,
  timestamp,
  price,
  pctChange
}
```

### Rendering
- Uses `canvas` for fast drawing
- Uses D3 scales and zoom behavior
- Redraws on:
  - new data
  - mouse movement
  - zoom/pan
  - resize

### Zoom and pan
`d3.zoom()` is attached to the canvas.  
The x-scale is rescaled with:

```js
this.zoomTransform.rescaleX(baseScale)
```

This gives smooth horizontal zooming and panning across time.

---

## Using real stock data instead of simulation

Replace `pushUpdate()` with WebSocket or polling logic.

Example WebSocket sketch:

```js
const socket = new WebSocket("wss://your-stock-feed.example.com");

socket.onmessage = (event) => {
  const update = JSON.parse(event.data);
  // update = { symbol: "AAPL", price: 192.31, timestamp: Date.now() }

  const ts = update.timestamp;

  // You may batch updates by timestamp, then append one new column
  // across all symbols once a full frame is assembled.
};
```

If using a real feed, you’ll usually want to:
- batch updates into time buckets, e.g. 1 second
- normalize missing symbol updates
- cap the visible time window
- debounce rendering if event volume is high

