<body>
  <div class="toolbar">
    <button id="resetZoom">Reset Zoom</button>
    <button id="pauseBtn">Pause Updates</button>
    <div class="status" id="status">Live updates: ON</div>
  </div>

  <div id="chart">
    <div class="tooltip" id="tooltip"></div>
    <div class="legend">
      <div><strong>Price Change %</strong></div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between;">
        <span>-5%</span>
        <span>0%</span>
        <span>+5%</span>
      </div>
    </div>
  </div>

  <script>
    const container = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const pauseBtn = document.getElementById("pauseBtn");

    let width = container.clientWidth;
    let height = container.clientHeight;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("viewBox", [0, 0, width, height]);

    const root = svg.append("g");
    const heatmapLayer = root.append("g");

    const sectors = [
      "Technology", "Finance", "Healthcare", "Energy",
      "Consumer", "Industrial", "Utilities", "Materials"
    ];

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","JPM","BAC","WFC",
      "XOM","CVX","PFE","JNJ","MRK","UNH","HD","MCD","NKE","DIS",
      "CAT","BA","GE","HON","NEE","DUK","SO","LIN","FCX","DOW",
      "AMD","INTC","ORCL","CRM","GS","MS","C","SCHW","SLB","COP"
    ];

    function randomSector() {
      return sectors[Math.floor(Math.random() * sectors.length)];
    }

    function createStocks() {
      return symbols.map((symbol, i) => {
        const basePrice = +(50 + Math.random() * 450).toFixed(2);
        return {
          id: i,
          symbol,
          sector: randomSector(),
          price: basePrice,
          prevClose: basePrice,
          changePct: 0,
          volume: Math.floor(100000 + Math.random() * 5000000)
        };
      });
    }

    let data = createStocks();
    let live = true;

    const cols = 5;
    const cellWidth = 180;
    const cellHeight = 110;
    const gap = 16;
    const rows = Math.ceil(data.length / cols);

    function layoutData(data) {
      return data.map((d, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        return {
          ...d,
          x: col * (cellWidth + gap),
          y: row * (cellHeight + gap)
        };
      });
    }

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatPct(v) {
      return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
    }

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#dc2626", "#334155", "#16a34a"])
      .clamp(true);

    const zoom = d3.zoom()
      .scaleExtent([0.5, 6])
      .translateExtent([[-500, -500], [cols * (cellWidth + gap) + 500, rows * (cellHeight + gap) + 500]])
      .on("zoom", (event) => {
        root.attr("transform", event.transform);
      });

    svg.call(zoom);

    function render() {
      const laidOut = layoutData(data);

      const cards = heatmapLayer.selectAll(".stock")
        .data(laidOut, d => d.symbol);

      const enter = cards.enter()
        .append("g")
        .attr("class", "stock")
        .attr("transform", d => `translate(${d.x}, ${d.y})`);

      enter.append("rect")
        .attr("class", "cell")
        .attr("width", cellWidth)
        .attr("height", cellHeight)
        .attr("fill", d => colorScale(d.changePct));

      enter.append("text")
        .attr("class", "label")
        .attr("x", 12)
        .attr("y", 24)
        .text(d => d.symbol);

      enter.append("text")
        .attr("class", "sub-label price")
        .attr("x", 12)
        .attr("y", 48)
        .text(d => formatPrice(d.price));

      enter.append("text")
        .attr("class", "sub-label change")
        .attr("x", 12)
        .attr("y", 68)
        .text(d => formatPct(d.changePct));

      enter.append("text")
        .attr("class", "sub-label sector")
        .attr("x", 12)
        .attr("y", 88)
        .text(d => d.sector);

      const merged = enter.merge(cards);

      merged.transition()
        .duration(500)
        .attr("transform", d => `translate(${d.x}, ${d.y})`);

      merged.select(".cell")
        .transition()
        .duration(500)
        .attr("fill", d => colorScale(d.changePct));

      merged.select(".price")
        .text(d => formatPrice(d.price));

      merged.select(".change")
        .text(d => formatPct(d.changePct))
        .attr("fill", d => d.changePct >= 0 ? "#86efac" : "#fca5a5");

      merged.select(".sector")
        .text(d => d.sector);

      merged
        .on("mousemove", function(event, d) {
          tooltip.style.opacity = 1;
          tooltip.style.left = `${event.offsetX}px`;
          tooltip.style.top = `${event.offsetY}px`;
          tooltip.innerHTML = `
            <div><strong>${d.symbol}</strong></div>
            <div>Sector: ${d.sector}</div>
            <div>Price: ${formatPrice(d.price)}</div>
            <div>Change: ${formatPct(d.changePct)}</div>
            <div>Prev Close: ${formatPrice(d.prevClose)}</div>
            <div>Volume: ${d.volume.toLocaleString()}</div>
          `;
        })
        .on("mouseleave", function() {
          tooltip.style.opacity = 0;
        });

      cards.exit().remove();
    }

    function updatePrices() {
      data = data.map(stock => {
        const drift = (Math.random() - 0.5) * 0.02;
        const volatility = (Math.random() - 0.5) * 0.03;
        const delta = stock.price * (drift + volatility);
        const newPrice = Math.max(1, stock.price + delta);
        const changePct = ((newPrice - stock.prevClose) / stock.prevClose) * 100;
        const volumeBump = Math.floor(Math.random() * 50000);

        return {
          ...stock,
          price: +newPrice.toFixed(2),
          changePct: +changePct.toFixed(2),
          volume: stock.volume + volumeBump
        };
      });

      render();
    }

    render();

    let interval = setInterval(() => {
      if (live) updatePrices();
    }, 1000);

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(500).call(
        zoom.transform,
        d3.zoomIdentity.translate(20, 20).scale(1)
      );
    });

    pauseBtn.addEventListener("click", () => {
      live = !live;
      pauseBtn.textContent = live ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = `Live updates: ${live ? "ON" : "OFF"}`;
    });

    window.addEventListener("resize", () => {
      width = container.clientWidth;
      height = container.clientHeight;
      svg.attr("viewBox", [0, 0, width, height]);
    });

    svg.call(
      zoom.transform,
      d3.zoomIdentity.translate(20, 20).scale(1)
    );
  </script>
</body>
</html>
```

