<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #0f172a;
      color: #e2e8f0;
      overflow: hidden;
    }

    .container {
      width: 100vw;
      height: 100vh;
      display: flex;
      flex-direction: column;
    }

    .header {
      padding: 12px 16px;
      background: #111827;
      border-bottom: 1px solid #1f2937;
      font-size: 18px;
      font-weight: 600;
    }

    .chart-wrapper {
      flex: 1;
      position: relative;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background: #020617;
      cursor: grab;
    }

    svg:active {
      cursor: grabbing;
    }

    .axis text {
      fill: #cbd5e1;
      font-size: 12px;
    }

    .axis path,
    .axis line {
      stroke: #475569;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      color: #f8fafc;
      border: 1px solid #334155;
      border-radius: 6px;
      padding: 8px 10px;
      font-size: 12px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.3);
      opacity: 0;
      transition: opacity 0.15s ease;
      white-space: nowrap;
    }

    .legend text {
      fill: #cbd5e1;
      font-size: 11px;
    }

    .grid line {
      stroke: rgba(255,255,255,0.06);
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">Real-Time Stock Price Heatmap</div>
    <div class="chart-wrapper">
      <svg id="heatmap"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const tickers = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "CRM", "ORCL", "IBM", "UBER", "SHOP"
    ];

    const maxTimePoints = 60;
    const updateInterval = 1000;

    const basePrices = {};
    const latestPrices = {};
    tickers.forEach(t => {
      const base = 50 + Math.random() * 250;
      basePrices[t] = base;
      latestPrices[t] = base;
    });

    let timeIndex = 0;
    let data = [];

    function generateNextDataPoint() {
      const timestamp = new Date();

      tickers.forEach(ticker => {
        const drift = (Math.random() - 0.5) * 2.5;
        latestPrices[ticker] = Math.max(5, latestPrices[ticker] + drift);

        const pctChange = ((latestPrices[ticker] - basePrices[ticker]) / basePrices[ticker]) * 100;

        data.push({
          ticker,
          timeIndex,
          timeLabel: timestamp.toLocaleTimeString(),
          price: latestPrices[ticker],
          pctChange
        });
      });

      timeIndex++;

      const minTime = Math.max(0, timeIndex - maxTimePoints);
      data = data.filter(d => d.timeIndex >= minTime);
    }

    for (let i = 0; i < maxTimePoints; i++) {
      generateNextDataPoint();
    }

    const svg = d3.select("#heatmap");
    const tooltip = d3.select("#tooltip");

    const margin = { top: 30, right: 30, bottom: 60, left: 80 };
    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    const root = svg.append("g");
    const zoomLayer = root.append("g");
    const cellsLayer = zoomLayer.append("g");
    const xAxisLayer = root.append("g").attr("class", "axis");
    const yAxisLayer = root.append("g").attr("class", "axis");
    const gridLayer = zoomLayer.append("g").attr("class", "grid");
    const legendLayer = root.append("g").attr("class", "legend");

    const xScaleBase = d3.scaleBand().paddingInner(0.02).paddingOuter(0.01);
    const yScaleBase = d3.scaleBand().domain(tickers).paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleSequential()
      .domain([8, -8])
      .interpolator(d3.interpolateRdYlGn);

    let currentTransform = d3.zoomIdentity;

    function getVisibleTimeIndices() {
      const start = Math.max(0, timeIndex - maxTimePoints);
      return d3.range(start, timeIndex);
    }

    function formatTimeLabel(index) {
      const found = data.find(d => d.timeIndex === index);
      return found ? found.timeLabel : "";
    }

    function resize() {
      const rect = svg.node().getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      xScaleBase.range([0, innerWidth]).domain(getVisibleTimeIndices());
      yScaleBase.range([0, innerHeight]);

      root.attr("transform", `translate(${margin.left},${margin.top})`);

      xAxisLayer.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisLayer.attr("transform", `translate(${margin.left},${margin.top})`);

      drawLegend();
      render();
    }

    function transformedXScale() {
      return currentTransform.rescaleX(
        d3.scaleLinear()
          .domain([0, getVisibleTimeIndices().length])
          .range([0, innerWidth])
      );
    }

    function renderGrid(xBandWidth, xPosFn) {
      const yTicks = tickers;

      const hLines = gridLayer.selectAll(".h-line")
        .data(yTicks, d => d);

      hLines.join(
        enter => enter.append("line")
          .attr("class", "h-line")
          .attr("x1", 0)
          .attr("x2", innerWidth)
          .attr("y1", d => yScaleBase(d) + yScaleBase.bandwidth())
          .attr("y2", d => yScaleBase(d) + yScaleBase.bandwidth()),
        update => update
          .attr("x2", innerWidth)
          .attr("y1", d => yScaleBase(d) + yScaleBase.bandwidth())
          .attr("y2", d => yScaleBase(d) + yScaleBase.bandwidth()),
        exit => exit.remove()
      );

      const times = getVisibleTimeIndices();
      const vLines = gridLayer.selectAll(".v-line")
        .data(times, d => d);

      vLines.join(
        enter => enter.append("line")
          .attr("class", "v-line")
          .attr("y1", 0)
          .attr("y2", innerHeight)
          .attr("x1", d => xPosFn(d))
          .attr("x2", d => xPosFn(d)),
        update => update
          .attr("y2", innerHeight)
          .attr("x1", d => xPosFn(d))
          .attr("x2", d => xPosFn(d)),
        exit => exit.remove()
      );
    }

    function render() {
      xScaleBase.domain(getVisibleTimeIndices());

      const visibleTimes = getVisibleTimeIndices();

      const linearIndexScale = d3.scaleLinear()
        .domain([0, visibleTimes.length])
        .range([0, innerWidth]);

      const zx = currentTransform.rescaleX(linearIndexScale);

      const xPos = (timeVal) => {
        const idx = visibleTimes.indexOf(timeVal);
        return zx(idx);
      };

      const xBandWidth = Math.max(2, (zx(1) - zx(0)) * 0.96);

      const filteredData = data.filter(d => visibleTimes.includes(d.timeIndex));

      const cells = cellsLayer.selectAll("rect.cell")
        .data(filteredData, d => `${d.ticker}-${d.timeIndex}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("rx", 1)
          .attr("ry", 1)
          .attr("x", d => xPos(d.timeIndex))
          .attr("y", d => yScaleBase(d.ticker))
          .attr("width", xBandWidth)
          .attr("height", yScaleBase.bandwidth())
          .attr("fill", d => colorScale(d.pctChange))
          .on("mousemove", (event, d) => {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 14}px`)
              .style("top", `${event.offsetY + 14}px`)
              .html(`
                <strong>${d.ticker}</strong><br/>
                Time: ${d.timeLabel}<br/>
                Price: $${d.price.toFixed(2)}<br/>
                Change: ${d.pctChange.toFixed(2)}%
              `);
          })
          .on("mouseleave", () => {
            tooltip.style("opacity", 0);
          }),
        update => update
          .transition()
          .duration(300)
          .attr("x", d => xPos(d.timeIndex))
          .attr("y", d => yScaleBase(d.ticker))
          .attr("width", xBandWidth)
          .attr("height", yScaleBase.bandwidth())
          .attr("fill", d => colorScale(d.pctChange)),
        exit => exit.remove()
      );

      const tickCount = Math.max(4, Math.floor(innerWidth / 100));
      const tickIndices = d3.range(visibleTimes.length).filter((_, i) => i % Math.ceil(visibleTimes.length / tickCount) === 0);

      const xAxisScale = d3.scaleLinear()
        .domain([0, visibleTimes.length - 1])
        .range([0, innerWidth]);

      const zxAxis = currentTransform.rescaleX(xAxisScale);

      const xAxis = d3.axisBottom(zxAxis)
        .tickValues(tickIndices)
        .tickFormat(i => {
          const timeVal = visibleTimes[Math.round(i)];
          return timeVal !== undefined ? formatTimeLabel(timeVal) : "";
        });

      const yAxis = d3.axisLeft(yScaleBase);

      xAxisLayer.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisLayer.call(yAxis);

      zoomLayer.attr("transform", `translate(${margin.left},${margin.top})`);
      renderGrid(xBandWidth, xPos);
    }

    function drawLegend() {
      legendLayer.selectAll("*").remove();

      const legendWidth = 220;
      const legendHeight = 12;
      const x = width - margin.right - legendWidth;
      const y = 8;

      const defs = svg.select("defs").empty() ? svg.append("defs") : svg.select("defs");
      defs.select("#legend-gradient").remove();

      const gradient = defs.append("linearGradient")
        .attr("id", "legend-gradient")
        .attr("x1", "0%")
        .attr("x2", "100%")
        .attr("y1", "0%")
        .attr("y2", "0%");

      const stops = d3.range(0, 1.01, 0.1);
      stops.forEach(s => {
        gradient.append("stop")
          .attr("offset", `${s * 100}%`)
          .attr("stop-color", colorScale(8 - s * 16));
      });

      legendLayer.append("text")
        .attr("x", x)
        .attr("y", y - 2)
        .text("% Change");

      legendLayer.append("rect")
        .attr("x", x)
        .attr("y", y + 6)
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", "url(#legend-gradient)")
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-8, 8])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .ticks(5)
        .tickFormat(d => `${d}%`);

      legendLayer.append("g")
        .attr("transform", `translate(${x},${y + 18})`)
        .call(legendAxis)
        .selectAll("text")
        .style("fill", "#cbd5e1");

      legendLayer.selectAll(".domain, .tick line")
        .attr("stroke", "#475569");
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    function tick() {
      generateNextDataPoint();
      xScaleBase.domain(getVisibleTimeIndices());
      render();
    }

    window.addEventListener("resize", resize);
    resize();

    setInterval(tick, updateInterval);
  </script>
</body>
</html>
