      <div class="meta" id="statusText">Live updates: ON</div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div><strong>Price Change Heatmap</strong></div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>Loss</span>
          <span>Flat</span>
          <span>Gain</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("canvasWrap");
    const tooltip = document.getElementById("tooltip");
    const resetViewBtn = document.getElementById("resetViewBtn");
    const pauseBtn = document.getElementById("pauseBtn");
    const statusText = document.getElementById("statusText");

    const DPR = Math.max(1, window.devicePixelRatio || 1);

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "CRM", "UBER", "SHOP",
      "PYPL", "ADBE", "SNOW", "SQ", "COIN"
    ];

    const maxColumns = 240;
    const data = [];

    const basePrices = {};
    symbols.forEach(sym => {
      basePrices[sym] = 50 + Math.random() * 250;
    });

    for (let r = 0; r < symbols.length; r++) {
      data.push([]);
    }

    let tickIndex = 0;
    let paused = false;

    const state = {
      offsetX: 120,
      offsetY: 30,
      scaleX: 22,
      scaleY: 28,
      minScaleX: 6,
      maxScaleX: 100,
      minScaleY: 14,
      maxScaleY: 80,
      isDragging: false,
      dragStartX: 0,
      dragStartY: 0,
      dragOriginOffsetX: 0,
      dragOriginOffsetY: 0,
      hovered: null
    };

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * DPR;
      canvas.height = rect.height * DPR;
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function randomWalk(prev) {
      const drift = (Math.random() - 0.5) * 2.2;
      return Math.max(1, prev + drift);
    }

    function pushNewTick() {
      for (let r = 0; r < symbols.length; r++) {
        const sym = symbols[r];
        const row = data[r];
        const prev = row.length ? row[row.length - 1].price : basePrices[sym];
        const next = randomWalk(prev);
        const pct = ((next - basePrices[sym]) / basePrices[sym]) * 100;

        row.push({
          tick: tickIndex,
          price: next,
          pctChange: pct,
          time: new Date()
        });

        if (row.length > maxColumns) row.shift();
      }
      tickIndex++;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(pct) {
      const capped = clamp(pct, -5, 5);
      const t = (capped + 5) / 10;

      if (t < 0.5) {
        const k = t / 0.5;
        const r = Math.round(180 + (255 - 180) * k);
        const g = Math.round(0 + (245 - 0) * k);
        const b = Math.round(0 + (245 - 0) * k);
        return `rgb(${r},${g},${b})`;
      } else {
        const k = (t - 0.5) / 0.5;
        const r = Math.round(255 + (0 - 255) * k);
        const g = Math.round(245 + (160 - 245) * k);
        const b = Math.round(245 + (80 - 245) * k);
        return `rgb(${r},${g},${b})`;
      }
    }

    function drawAxes(width, height) {
      ctx.save();

      ctx.fillStyle = "#020617";
      ctx.fillRect(0, 0, width, height);

      ctx.fillStyle = "#cbd5e1";
      ctx.font = "12px Arial";
      ctx.textBaseline = "middle";

      for (let r = 0; r < symbols.length; r++) {
        const y = state.offsetY + r * state.scaleY;
        if (y + state.scaleY < 0 || y > height) continue;
        ctx.fillStyle = "#94a3b8";
        ctx.fillText(symbols[r], 8, y + state.scaleY / 2);
      }

      const visibleCols = getVisibleColumnRange(width);
      for (let c = visibleCols.start; c <= visibleCols.end; c++) {
        const x = state.offsetX + c * state.scaleX;
        if (x + state.scaleX < 0 || x > width) continue;
        ctx.fillStyle = "#64748b";
        ctx.fillText(String(c), x + 2, 14);
      }

      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1;

      for (let r = 0; r <= symbols.length; r++) {
        const y = state.offsetY + r * state.scaleY;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      const maxVisibleCols = Math.ceil(width / state.scaleX) + 2;
      for (let c = 0; c <= maxVisibleCols; c++) {
        const x = state.offsetX + c * state.scaleX;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      ctx.restore();
    }

    function getVisibleColumnRange(width) {
      const start = Math.max(0, Math.floor((-state.offsetX) / state.scaleX) - 1);
      const end = Math.min(
        maxColumns - 1,
        Math.ceil((width - state.offsetX) / state.scaleX) + 1
      );
      return { start, end };
    }

    function drawHeatmap() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;

      drawAxes(width, height);

      const visibleCols = getVisibleColumnRange(width);

      for (let r = 0; r < data.length; r++) {
        const row = data[r];
        const rowY = state.offsetY + r * state.scaleY;

        if (rowY + state.scaleY < 0 || rowY > height) continue;

        const rowStartIndex = Math.max(0, row.length - maxColumns);

        for (let c = visibleCols.start; c <= visibleCols.end; c++) {
          const item = row[c];
          if (!item) continue;

          const x = state.offsetX + c * state.scaleX;
          const y = rowY;

          ctx.fillStyle = colorForValue(item.pctChange);
          ctx.fillRect(
            x + 0.5,
            y + 0.5,
            Math.max(0, state.scaleX - 1),
            Math.max(0, state.scaleY - 1)
          );
        }
      }

      if (state.hovered) {
        const { row, col } = state.hovered;
        const x = state.offsetX + col * state.scaleX;
        const y = state.offsetY + row * state.scaleY;

        ctx.save();
        ctx.strokeStyle = "#f8fafc";
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, state.scaleX - 2, state.scaleY - 2);
        ctx.restore();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width / DPR, canvas.height / DPR);
      drawHeatmap();
    }

    function screenToCell(mx, my) {
      const col = Math.floor((mx - state.offsetX) / state.scaleX);
      const row = Math.floor((my - state.offsetY) / state.scaleY);

      if (row < 0 || row >= symbols.length) return null;
      if (col < 0 || col >= maxColumns) return null;
      if (!data[row][col]) return null;

      return { row, col };
    }

    function formatTime(date) {
      return date.toLocaleTimeString();
    }

    canvas.addEventListener("mousemove", (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (state.isDragging) {
        state.offsetX = state.dragOriginOffsetX + (mx - state.dragStartX);
        state.offsetY = state.dragOriginOffsetY + (my - state.dragStartY);
        draw();
        tooltip.style.display = "none";
        return;
      }

      const hit = screenToCell(mx, my);
      state.hovered = hit;

      if (hit) {
        const item = data[hit.row][hit.col];
        tooltip.style.display = "block";
        tooltip.style.left = `${mx}px`;
        tooltip.style.top = `${my}px`;
        tooltip.innerHTML = `
          <div><strong>${symbols[hit.row]}</strong></div>
          <div>Tick: ${item.tick}</div>
          <div>Price: $${item.price.toFixed(2)}</div>
          <div>Change: ${item.pctChange.toFixed(2)}%</div>
          <div>Time: ${formatTime(item.time)}</div>
        `;
      } else {
        tooltip.style.display = "none";
      }

      draw();
    });

    canvas.addEventListener("mouseleave", () => {
      state.hovered = null;
      tooltip.style.display = "none";
      draw();
    });

    canvas.addEventListener("mousedown", (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      state.isDragging = true;
      state.dragStartX = mx;
      state.dragStartY = my;
      state.dragOriginOffsetX = state.offsetX;
      state.dragOriginOffsetY = state.offsetY;
      canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      state.isDragging = false;
      canvas.classList.remove("dragging");
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoom = e.deltaY < 0 ? 1.1 : 0.9;

      const worldXBefore = (mx - state.offsetX) / state.scaleX;
      const worldYBefore = (my - state.offsetY) / state.scaleY;

      if (e.shiftKey) {
        state.scaleY = clamp(state.scaleY * zoom, state.minScaleY, state.maxScaleY);
      } else if (e.ctrlKey || e.metaKey) {
        state.scaleX = clamp(state.scaleX * zoom, state.minScaleX, state.maxScaleX);
      } else {
        state.scaleX = clamp(state.scaleX * zoom, state.minScaleX, state.maxScaleX);
        state.scaleY = clamp(state.scaleY * zoom, state.minScaleY, state.maxScaleY);
      }

      state.offsetX = mx - worldXBefore * state.scaleX;
      state.offsetY = my - worldYBefore * state.scaleY;

      draw();
    }, { passive: false });

    resetViewBtn.addEventListener("click", () => {
      state.offsetX = 120;
      state.offsetY = 30;
      state.scaleX = 22;
      state.scaleY = 28;
      draw();
    });

    pauseBtn.addEventListener("click", () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume" : "Pause";
      statusText.textContent = `Live updates: ${paused ? "OFF" : "ON"}`;
    });

    function tick() {
      if (!paused) {
        pushNewTick();
        draw();
      }
    }

    for (let i = 0; i < 80; i++) {
      pushNewTick();
    }

    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);
    setInterval(tick, 1000);
  </script>
</body>
</html>
```

---

## How interaction works

### Pan
- Click and drag on the canvas

### Zoom
- Mouse wheel:
  - wheel only: zoom both axes
  - `Ctrl/Cmd + wheel`: zoom horizontally
  - `Shift + wheel`: zoom vertically

### Hover
- Move mouse over a cell to see:
  - symbol
  - tick index
  - price
  - percent change
  - timestamp

---

## Notes

This example uses:
- `canvas` for rendering speed
- simulated random-walk stock prices
- a fixed rolling window of `maxColumns`

---

## If you want real market data

You can replace the simulated update logic in `pushNewTick()` with:
- WebSocket feed
- polling from an API like:
  - Alpha Vantage
  - Twelve Data
  - Finnhub
  - Polygon
  - IEX Cloud

For example, instead of generating `next = randomWalk(prev)`, you'd insert actual live prices.

---

## Possible improvements

You may want to add:

- row/column labels that stay pinned while panning
- smooth animation transitions
- color scaling based on current visible range
- mini-map overview
- touch support for pinch zoom
- WebGL rendering for very large datasets
- D3 scales/axes
- clustering/grouping by sector
- click-to-select a stock row
- live sparkline per row

