<body>
  <div class="app">
    <div class="toolbar">
      <label>
        Symbols
        <input id="symbolCount" type="number" min="5" max="200" value="40" />
      </label>

      <label>
        Time buckets
        <input id="timeBuckets" type="number" min="10" max="500" value="120" />
      </label>

      <label>
        Update interval
        <select id="updateInterval">
          <option value="250">250ms</option>
          <option value="500" selected>500ms</option>
          <option value="1000">1000ms</option>
        </select>
      </label>

      <button id="resetView">Reset View</button>
      <button id="pauseBtn">Pause</button>
      <button id="regenBtn">Regenerate</button>

      <div class="status" id="status">Running</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-title">Price change %</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, wrap, tooltip) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.wrap = wrap;
        this.tooltip = tooltip;

        this.dpr = window.devicePixelRatio || 1;
        this.width = 0;
        this.height = 0;

        this.symbols = [];
        this.times = [];
        this.data = [];

        this.baseCellWidth = 18;
        this.baseCellHeight = 22;
        this.scaleX = 1;
        this.scaleY = 1;
        this.offsetX = 80;
        this.offsetY = 30;

        this.minScaleX = 0.4;
        this.maxScaleX = 8;
        this.minScaleY = 0.5;
        this.maxScaleY = 4;

        this.axisLeft = 80;
        this.axisTop = 30;
        this.axisBottom = 40;
        this.axisRight = 20;

        this.dragging = false;
        this.lastPointer = null;
        this.hoverCell = null;

        this.paused = false;
        this.timer = null;
        this.updateInterval = 500;

        this.bindEvents();
        this.resize();
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('pointerdown', (e) => {
          this.dragging = true;
          this.lastPointer = { x: e.clientX, y: e.clientY };
          this.canvas.classList.add('dragging');
          this.canvas.setPointerCapture(e.pointerId);
        });

        this.canvas.addEventListener('pointermove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.dragging && this.lastPointer) {
            const dx = e.clientX - this.lastPointer.x;
            const dy = e.clientY - this.lastPointer.y;
            this.offsetX += dx;
            this.offsetY += dy;
            this.lastPointer = { x: e.clientX, y: e.clientY };
            this.draw();
          }

          this.updateHover(x, y);
        });

        this.canvas.addEventListener('pointerup', (e) => {
          this.dragging = false;
          this.lastPointer = null;
          this.canvas.classList.remove('dragging');
          this.canvas.releasePointerCapture?.(e.pointerId);
        });

        this.canvas.addEventListener('pointerleave', () => {
          if (!this.dragging) {
            this.hoverCell = null;
            this.tooltip.style.display = 'none';
            this.draw();
          }
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
          const zoomY = e.shiftKey;

          if (zoomY) {
            this.zoomAtY(my, zoomFactor);
          } else {
            this.zoomAtX(mx, zoomFactor);
          }

          this.draw();
        }, { passive: false });
      }

      resize() {
        const rect = this.wrap.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;

        this.canvas.width = Math.floor(this.width * this.dpr);
        this.canvas.height = Math.floor(this.height * this.dpr);
        this.canvas.style.width = this.width + 'px';
        this.canvas.style.height = this.height + 'px';

        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.draw();
      }

      generate(symbolCount = 40, timeBuckets = 120) {
        this.symbols = Array.from({ length: symbolCount }, (_, i) => {
          const prefixes = ['A', 'MS', 'NV', 'GO', 'AM', 'TS', 'ME', 'IN', 'OR', 'PL'];
          const suffixes = ['PL', 'TA', 'DA', 'FT', 'GL', 'ZN', 'LA', 'TA', 'TC', 'AI'];
          return prefixes[i % prefixes.length] + suffixes[(i * 3) % suffixes.length] + (i < 10 ? i : '');
        });

        this.times = Array.from({ length: timeBuckets }, (_, i) => i);

        this.data = this.symbols.map(() => {
          let price = 100 + Math.random() * 200;
          return this.times.map(() => {
            const drift = (Math.random() - 0.5) * 1.8;
            price = Math.max(5, price + drift);
            const pct = ((Math.random() - 0.5) * 6);
            return {
              price,
              changePct: pct
            };
          });
        });

        this.resetView();
        this.draw();
      }

      resetView() {
        this.scaleX = 1;
        this.scaleY = 1;
        this.offsetX = this.axisLeft;
        this.offsetY = this.axisTop;
        this.draw();
      }

      start(interval = 500) {
        this.stop();
        this.updateInterval = interval;
        this.timer = setInterval(() => {
          if (!this.paused) this.tick();
        }, interval);
      }

      stop() {
        if (this.timer) clearInterval(this.timer);
        this.timer = null;
      }

      tick() {
        if (!this.data.length) return;

        for (let row = 0; row < this.data.length; row++) {
          const series = this.data[row];
          const last = series[series.length - 1];
          const newPrice = Math.max(5, last.price + (Math.random() - 0.5) * 2.2);
          const changePct = Math.max(-5, Math.min(5, last.changePct + (Math.random() - 0.5) * 1.2));

          series.shift();
          series.push({
            price: newPrice,
            changePct
          });
        }

        this.draw();
      }

      zoomAtX(mouseX, factor) {
        const prev = this.scaleX;
        const next = Math.max(this.minScaleX, Math.min(this.maxScaleX, prev * factor));
        const contentX = (mouseX - this.offsetX) / prev;
        this.scaleX = next;
        this.offsetX = mouseX - contentX * next;
      }

      zoomAtY(mouseY, factor) {
        const prev = this.scaleY;
        const next = Math.max(this.minScaleY, Math.min(this.maxScaleY, prev * factor));
        const contentY = (mouseY - this.offsetY) / prev;
        this.scaleY = next;
        this.offsetY = mouseY - contentY * next;
      }

      get cellWidth() {
        return this.baseCellWidth * this.scaleX;
      }

      get cellHeight() {
        return this.baseCellHeight * this.scaleY;
      }

      valueToColor(v) {
        const clamped = Math.max(-5, Math.min(5, v));
        if (clamped < 0) {
          const t = (clamped + 5) / 5;
          return this.lerpColor([127, 29, 29], [239, 68, 68], t);
        } else {
          const t = clamped / 5;
          return this.lerpColor([34, 197, 94], [20, 83, 45], t);
        }
      }

      lerpColor(a, b, t) {
        const mix = a.map((v, i) => Math.round(v + (b[i] - v) * t));
        return `rgb(${mix[0]}, ${mix[1]}, ${mix[2]})`;
      }

      updateHover(x, y) {
        const col = Math.floor((x - this.offsetX) / this.cellWidth);
        const row = Math.floor((y - this.offsetY) / this.cellHeight);

        if (
          row >= 0 && row < this.symbols.length &&
          col >= 0 && col < this.times.length
        ) {
          this.hoverCell = { row, col, x, y };
          const point = this.data[row][col];
          this.tooltip.innerHTML = `
            <div><strong>${this.symbols[row]}</strong></div>
            <div class="muted">Bucket: ${col}</div>
            <div>Price: $${point.price.toFixed(2)}</div>
            <div>Change: ${point.changePct.toFixed(2)}%</div>
          `;
          this.tooltip.style.left = `${x}px`;
          this.tooltip.style.top = `${y}px`;
          this.tooltip.style.display = 'block';
        } else {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
        }

        this.draw();
      }

      draw() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.width, this.height);

        this.drawBackground();
        this.drawHeatmap();
        this.drawAxes();
        this.drawHover();
      }

      drawBackground() {
        const ctx = this.ctx;
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, this.width, this.height);
      }

      drawHeatmap() {
        const ctx = this.ctx;
        const cw = this.cellWidth;
        const ch = this.cellHeight;

        const startCol = Math.max(0, Math.floor((0 - this.offsetX) / cw));
        const endCol = Math.min(this.times.length, Math.ceil((this.width - this.offsetX) / cw));
        const startRow = Math.max(0, Math.floor((0 - this.offsetY) / ch));
        const endRow = Math.min(this.symbols.length, Math.ceil((this.height - this.offsetY) / ch));

        for (let row = startRow; row < endRow; row++) {
          for (let col = startCol; col < endCol; col++) {
            const x = this.offsetX + col * cw;
            const y = this.offsetY + row * ch;
            const point = this.data[row][col];

            ctx.fillStyle = this.valueToColor(point.changePct);
            ctx.fillRect(x, y, cw, ch);

            ctx.strokeStyle = 'rgba(15, 23, 42, 0.45)';
            ctx.strokeRect(x, y, cw, ch);

            if (cw > 40 && ch > 18) {
              ctx.fillStyle = 'rgba(255,255,255,0.9)';
              ctx.font = '11px sans-serif';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              ctx.fillText(point.changePct.toFixed(1) + '%', x + cw / 2, y + ch / 2);
            }
          }
        }
      }

      drawAxes() {
        const ctx = this.ctx;
        const cw = this.cellWidth;
        const ch = this.cellHeight;

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, this.axisLeft, this.height);
        ctx.fillRect(0, 0, this.width, this.axisTop);

        ctx.strokeStyle = '#334155';
        ctx.beginPath();
        ctx.moveTo(this.axisLeft - 0.5, 0);
        ctx.lineTo(this.axisLeft - 0.5, this.height);
        ctx.moveTo(0, this.axisTop - 0.5);
        ctx.lineTo(this.width, this.axisTop - 0.5);
        ctx.stroke();

        const startRow = Math.max(0, Math.floor((0 - this.offsetY) / ch));
        const endRow = Math.min(this.symbols.length, Math.ceil((this.height - this.offsetY) / ch));

        ctx.fillStyle = '#cbd5e1';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';

        for (let row = startRow; row < endRow; row++) {
          const y = this.offsetY + row * ch + ch / 2;
          if (y >= this.axisTop && y <= this.height) {
            ctx.fillText(this.symbols[row], this.axisLeft - 8, y);
          }
        }

        const startCol = Math.max(0, Math.floor((0 - this.offsetX) / cw));
        const endCol = Math.min(this.times.length, Math.ceil((this.width - this.offsetX) / cw));

        ctx.save();
        ctx.fillStyle = '#cbd5e1';
        ctx.font = '11px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        for (let col = startCol; col < endCol; col++) {
          const x = this.offsetX + col * cw + cw / 2;
          if (x >= this.axisLeft && x <= this.width) {
            ctx.fillText(`T-${this.times.length - col}`, x, 8);
          }
        }
        ctx.restore();
      }

      drawHover() {
        if (!this.hoverCell) return;

        const { row, col } = this.hoverCell;
        const x = this.offsetX + col * this.cellWidth;
        const y = this.offsetY + row * this.cellHeight;

        const ctx = this.ctx;
        ctx.save();
        ctx.strokeStyle = '#f8fafc';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, this.cellWidth - 2, this.cellHeight - 2);
        ctx.restore();
      }
    }

    const canvas = document.getElementById('heatmap');
    const wrap = document.getElementById('chartWrap');
    const tooltip = document.getElementById('tooltip');

    const symbolCountInput = document.getElementById('symbolCount');
    const timeBucketsInput = document.getElementById('timeBuckets');
    const updateIntervalInput = document.getElementById('updateInterval');
    const resetViewBtn = document.getElementById('resetView');
    const pauseBtn = document.getElementById('pauseBtn');
    const regenBtn = document.getElementById('regenBtn');
    const statusEl = document.getElementById('status');

    const heatmap = new StockHeatmap(canvas, wrap, tooltip);

    function regenerate() {
      const symbolCount = parseInt(symbolCountInput.value, 10);
      const timeBuckets = parseInt(timeBucketsInput.value, 10);
      heatmap.generate(symbolCount, timeBuckets);
    }

    regenerate();
    heatmap.start(parseInt(updateIntervalInput.value, 10));

    resetViewBtn.addEventListener('click', () => heatmap.resetView());

    pauseBtn.addEventListener('click', () => {
      heatmap.paused = !heatmap.paused;
      pauseBtn.textContent = heatmap.paused ? 'Resume' : 'Pause';
      statusEl.textContent = heatmap.paused ? 'Paused' : 'Running';
    });

    regenBtn.addEventListener('click', regenerate);

    updateIntervalInput.addEventListener('change', () => {
      heatmap.start(parseInt(updateIntervalInput.value, 10));
    });

    symbolCountInput.addEventListener('change', regenerate);
    timeBucketsInput.addEventListener('change', regenerate);
  </script>
</body>
</html>
```

