  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <div class="title">Real-Time Stock Heatmap</div>

      <button id="playPauseBtn">Pause</button>
      <button id="resetZoomBtn">Reset Zoom</button>

      <span class="label">Update speed:</span>
      <select id="speedSelect">
        <option value="1000">1s</option>
        <option value="500" selected>500ms</option>
        <option value="250">250ms</option>
        <option value="100">100ms</option>
      </select>

      <span class="label">Window size:</span>
      <select id="windowSelect">
        <option value="30">30</option>
        <option value="60" selected>60</option>
        <option value="120">120</option>
      </select>

      <div class="status" id="statusText">Streaming</div>
    </div>

    <div id="chart">
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC",
      "ORCL", "IBM", "CRM", "UBER", "SHOP"
    ];

    const margin = { top: 30, right: 30, bottom: 60, left: 90 };
    const chartEl = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const playPauseBtn = document.getElementById("playPauseBtn");
    const resetZoomBtn = document.getElementById("resetZoomBtn");
    const speedSelect = document.getElementById("speedSelect");
    const windowSelect = document.getElementById("windowSelect");
    const statusText = document.getElementById("statusText");

    let width = chartEl.clientWidth;
    let height = chartEl.clientHeight;

    let isRunning = true;
    let updateInterval = +speedSelect.value;
    let timeWindow = +windowSelect.value;
    let timer = null;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("preserveAspectRatio", "xMidYMid meet");

    const defs = svg.append("defs");

    const chartGroup = svg.append("g");
    const plotGroup = chartGroup.append("g");
    const cellsGroup = plotGroup.append("g");
    const xAxisGroup = chartGroup.append("g").attr("class", "axis");
    const yAxisGroup = chartGroup.append("g").attr("class", "axis");
    const gridGroup = plotGroup.append("g").attr("class", "grid");
    const legendGroup = svg.append("g").attr("class", "legend");

    let innerWidth = width - margin.left - margin.right;
    let innerHeight = height - margin.top - margin.bottom;

    chartGroup.attr("transform", `translate(${margin.left},${margin.top})`);

    const basePrices = new Map();
    const latestPrices = new Map();

    symbols.forEach(symbol => {
      const base = 80 + Math.random() * 220;
      basePrices.set(symbol, base);
      latestPrices.set(symbol, base);
    });

    let timestamps = [];
    let data = [];

    function nowLabel(date = new Date()) {
      return d3.timeFormat("%H:%M:%S")(date);
    }

    function generateTick() {
      const ts = new Date();
      const label = nowLabel(ts);
      timestamps.push(label);

      if (timestamps.length > timeWindow) {
        timestamps.shift();
      }

      symbols.forEach(symbol => {
        const prev = latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 0.02;
        const next = Math.max(1, prev * (1 + drift));
        latestPrices.set(symbol, next);

        data.push({
          symbol,
          time: label,
          timestamp: ts,
          price: next,
          changePct: ((next - basePrices.get(symbol)) / basePrices.get(symbol)) * 100
        });
      });

      const minTimeSet = new Set(timestamps);
      data = data.filter(d => minTimeSet.has(d.time));
    }

    for (let i = 0; i < timeWindow; i++) {
      generateTick();
    }

    let xScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);
    let yScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#1e293b", "#16a34a"])
      .clamp(true);

    let currentTransform = d3.zoomIdentity;

    function updateDimensions() {
      width = chartEl.clientWidth;
      height = chartEl.clientHeight;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      svg.attr("viewBox", `0 0 ${width} ${height}`);
      chartGroup.attr("transform", `translate(${margin.left},${margin.top})`);

      xAxisGroup.attr("transform", `translate(${margin.left},${margin.top + innerHeight})`);
      yAxisGroup.attr("transform", `translate(${margin.left},${margin.top})`);

      drawLegend();
      render();
    }

    function drawLegend() {
      legendGroup.selectAll("*").remove();

      const legendWidth = 180;
      const legendHeight = 12;
      const x = width - legendWidth - 40;
      const y = 12;

      const gradientId = "heat-gradient";
      defs.select(`#${gradientId}`).remove();

      const gradient = defs.append("linearGradient")
        .attr("id", gradientId)
        .attr("x1", "0%")
        .attr("x2", "100%")
        .attr("y1", "0%")
        .attr("y2", "0%");

      gradient.append("stop").attr("offset", "0%").attr("stop-color", "#b91c1c");
      gradient.append("stop").attr("offset", "50%").attr("stop-color", "#1e293b");
      gradient.append("stop").attr("offset", "100%").attr("stop-color", "#16a34a");

      legendGroup.append("text")
        .attr("x", x)
        .attr("y", y - 2)
        .text("% Change");

      legendGroup.append("rect")
        .attr("x", x)
        .attr("y", y + 6)
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", `url(#${gradientId})`)
        .attr("stroke", "#475569");

      const legendScale = d3.scaleLinear()
        .domain([-5, 5])
        .range([0, legendWidth]);

      const legendAxis = d3.axisBottom(legendScale)
        .tickValues([-5, -2.5, 0, 2.5, 5])
        .tickFormat(d => `${d}%`);

      legendGroup.append("g")
        .attr("transform", `translate(${x},${y + 18})`)
        .call(legendAxis)
        .call(g => g.selectAll("text").attr("fill", "#cbd5e1"))
        .call(g => g.selectAll("line,path").attr("stroke", "#475569"));
    }

    function render() {
      xScale.domain(timestamps).range([0, innerWidth]);
      yScale.domain(symbols).range([0, innerHeight]);

      const zx = currentTransform.rescaleX(
        d3.scaleLinear().domain([0, innerWidth]).range([0, innerWidth])
      );

      const visibleX = t => zx(xScale(t) + xScale.bandwidth() / 2);
      const scaledBandwidthX = xScale.bandwidth() * currentTransform.k;
      const scaledBandwidthY = yScale.bandwidth() * currentTransform.k;

      plotGroup.attr("transform", `translate(${currentTransform.x},${currentTransform.y}) scale(${currentTransform.k})`);

      const xAxisScale = d3.scalePoint()
        .domain(timestamps)
        .range([0, innerWidth]);

      const xAxis = d3.axisBottom(xAxisScale)
        .tickValues(
          timestamps.filter((d, i) => {
            const approx = Math.ceil(timestamps.length / Math.max(1, innerWidth / 80));
            return i % approx === 0;
          })
        );

      const yAxis = d3.axisLeft(yScale);

      xAxisGroup.call(xAxis)
        .call(g => g.selectAll("text")
          .attr("transform", "rotate(-35)")
          .style("text-anchor", "end"));

      yAxisGroup.call(yAxis);

      const gridRows = gridGroup.selectAll(".row-line")
        .data(symbols, d => d);

      gridRows.join(
        enter => enter.append("line")
          .attr("class", "row-line")
          .attr("x1", 0)
          .attr("x2", innerWidth)
          .attr("y1", d => yScale(d))
          .attr("y2", d => yScale(d))
          .attr("stroke", "#1e293b"),
        update => update
          .attr("x2", innerWidth)
          .attr("y1", d => yScale(d))
          .attr("y2", d => yScale(d)),
        exit => exit.remove()
      );

      const cells = cellsGroup.selectAll("rect")
        .data(data, d => `${d.symbol}-${d.time}`);

      cells.join(
        enter => enter.append("rect")
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("rx", 2)
          .attr("ry", 2)
          .attr("fill", d => colorScale(d.changePct))
          .on("mousemove", function(event, d) {
            tooltip.style.opacity = 1;
            tooltip.innerHTML = `
              <div><strong>${d.symbol}</strong></div>
              <div>Time: ${d.time}</div>
              <div>Price: $${d.price.toFixed(2)}</div>
              <div>Change: ${d.changePct.toFixed(2)}%</div>
            `;
            const bounds = chartEl.getBoundingClientRect();
            tooltip.style.left = `${event.clientX - bounds.left + 12}px`;
            tooltip.style.top = `${event.clientY - bounds.top + 12}px`;
          })
          .on("mouseleave", function() {
            tooltip.style.opacity = 0;
          }),
        update => update
          .transition()
          .duration(Math.min(updateInterval * 0.8, 300))
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.symbol))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.changePct)),
        exit => exit.remove()
      );
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        plotGroup.attr(
          "transform",
          `translate(${currentTransform.x},${currentTransform.y}) scale(${currentTransform.k})`
        );
      });

    svg.call(zoom);

    function tickAndRender() {
      if (!isRunning) return;
      generateTick();
      render();
    }

    function startTimer() {
      if (timer) clearInterval(timer);
      timer = setInterval(tickAndRender, updateInterval);
    }

    playPauseBtn.addEventListener("click", () => {
      isRunning = !isRunning;
      playPauseBtn.textContent = isRunning ? "Pause" : "Resume";
      statusText.textContent = isRunning ? "Streaming" : "Paused";
    });

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    speedSelect.addEventListener("change", () => {
      updateInterval = +speedSelect.value;
      startTimer();
    });

    windowSelect.addEventListener("change", () => {
      timeWindow = +windowSelect.value;
      timestamps = [];
      data = [];
      symbols.forEach(symbol => {
        latestPrices.set(symbol, basePrices.get(symbol));
      });
      for (let i = 0; i < timeWindow; i++) {
        generateTick();
      }
      render();
    });

    window.addEventListener("resize", updateDimensions);

    drawLegend();
    render();
    startTimer();
  </script>
</body>
