      line-height: 1.4;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(10px, 10px);
      white-space: nowrap;
    }

    .status {
      color: #94a3b8;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetZoom">Reset Zoom</button>
      <button id="toggleStream">Pause Stream</button>
      <div class="status" id="status">Streaming live updates...</div>
      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>
    </div>
    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const resetZoomBtn = document.getElementById("resetZoom");
    const toggleStreamBtn = document.getElementById("toggleStream");
    const statusEl = document.getElementById("status");

    const DPR = window.devicePixelRatio || 1;

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","META","NVDA","TSLA","AMD","NFLX","INTC",
      "ORCL","IBM","CRM","ADBE","PYPL","UBER","SHOP","SQ","BABA","SONY"
    ];

    const timeSteps = 120; // columns shown
    const data = [];
    const basePrices = new Map();

    symbols.forEach(symbol => {
      const start = 80 + Math.random() * 220;
      basePrices.set(symbol, start);
      const row = [];
      let price = start;
      for (let i = 0; i < timeSteps; i++) {
        price *= 1 + (Math.random() - 0.5) * 0.01;
        row.push({
          symbol,
          time: Date.now() - (timeSteps - i) * 1000,
          price,
          pctChange: ((price - start) / start) * 100
        });
      }
      data.push(row);
    });

    let isStreaming = true;

    const state = {
      width: 0,
      height: 0,
      transform: d3.zoomIdentity,
      cellWidth: 18,
      cellHeight: 26,
      paddingLeft: 90,
      paddingTop: 30,
      paddingRight: 20,
      paddingBottom: 30
    };

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#7f1d1d", "#111827", "#14532d"])
      .clamp(true);

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      state.width = rect.width;
      state.height = rect.height;

      canvas.width = rect.width * DPR;
      canvas.height = rect.height * DPR;
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";

      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      render();
    }

    function getPlotWidth() {
      return state.width - state.paddingLeft - state.paddingRight;
    }

    function getPlotHeight() {
      return state.height - state.paddingTop - state.paddingBottom;
    }

    function drawAxes() {
      const plotW = getPlotWidth();
      const plotH = getPlotHeight();

      ctx.save();
      ctx.translate(state.paddingLeft, state.paddingTop);

      ctx.strokeStyle = "#334155";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(0, plotH);
      ctx.lineTo(plotW, plotH);
      ctx.stroke();

      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px Arial";
      ctx.textBaseline = "middle";

      // Y labels
      symbols.forEach((symbol, rowIndex) => {
        const y = rowIndex * state.cellHeight + state.cellHeight / 2;
        const transformed = applyTransform(0, y);
        if (transformed.y < -state.cellHeight || transformed.y > plotH + state.cellHeight) return;
        ctx.fillText(symbol, -80, transformed.y);
      });

      // X labels
      ctx.textAlign = "center";
      const firstRow = data[0];
      for (let col = 0; col < firstRow.length; col += 10) {
        const x = col * state.cellWidth + state.cellWidth / 2;
        const transformed = applyTransform(x, 0);
        if (transformed.x < -50 || transformed.x > plotW + 50) continue;
        const t = new Date(firstRow[col].time);
        const label = t.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
        ctx.fillText(label, transformed.x, plotH + 16);
      }

      ctx.restore();
    }

    function applyTransform(x, y) {
      return {
        x: state.transform.applyX(x),
        y: state.transform.applyY(y)
      };
    }

    function invertTransform(x, y) {
      return {
        x: state.transform.invertX(x),
        y: state.transform.invertY(y)
      };
    }

    function drawHeatmap() {
      const plotW = getPlotWidth();
      const plotH = getPlotHeight();

      ctx.save();
      ctx.translate(state.paddingLeft, state.paddingTop);

      // Clip plotting area
      ctx.beginPath();
      ctx.rect(0, 0, plotW, plotH);
      ctx.clip();

      for (let row = 0; row < data.length; row++) {
        for (let col = 0; col < data[row].length; col++) {
          const cell = data[row][col];
          const x = col * state.cellWidth;
          const y = row * state.cellHeight;

          const p = applyTransform(x, y);
          const w = state.cellWidth * state.transform.k;
          const h = state.cellHeight * state.transform.k;

          if (p.x + w < 0 || p.x > plotW || p.y + h < 0 || p.y > plotH) continue;

          ctx.fillStyle = colorScale(cell.pctChange);
          ctx.fillRect(p.x, p.y, w, h);

          if (state.transform.k > 1.8) {
            ctx.strokeStyle = "rgba(255,255,255,0.06)";
            ctx.strokeRect(p.x, p.y, w, h);
          }
        }
      }

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, state.width, state.height);
      drawAxes();
      drawHeatmap();
    }

    function pickCell(mouseX, mouseY) {
      const localX = mouseX - state.paddingLeft;
      const localY = mouseY - state.paddingTop;
      const plotW = getPlotWidth();
      const plotH = getPlotHeight();

      if (localX < 0 || localY < 0 || localX > plotW || localY > plotH) return null;

      const inv = invertTransform(localX, localY);
      const col = Math.floor(inv.x / state.cellWidth);
      const row = Math.floor(inv.y / state.cellHeight);

      if (row < 0 || row >= data.length || col < 0 || col >= data[row].length) return null;
      return data[row][col];
    }

    canvas.addEventListener("mousemove", (e) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const cell = pickCell(x, y);

      if (!cell) {
        tooltip.style.opacity = 0;
        return;
      }

      tooltip.style.opacity = 1;
      tooltip.style.left = `${x + 12}px`;
      tooltip.style.top = `${y + 12}px`;
      tooltip.innerHTML = `
        <strong>${cell.symbol}</strong><br/>
        Price: $${cell.price.toFixed(2)}<br/>
        Change: ${cell.pctChange.toFixed(2)}%<br/>
        Time: ${new Date(cell.time).toLocaleTimeString()}
      `;
    });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.opacity = 0;
    });

    const zoom = d3.zoom()
      .scaleExtent([0.5, 8])
      .translateExtent([[-500, -500], [5000, 5000]])
      .on("zoom", (event) => {
        state.transform = event.transform;
        render();
      });

    d3.select(canvas).call(zoom);

    resetZoomBtn.addEventListener("click", () => {
      d3.select(canvas)
        .transition()
        .duration(300)
        .call(zoom.transform, d3.zoomIdentity);
    });

    toggleStreamBtn.addEventListener("click", () => {
      isStreaming = !isStreaming;
      toggleStreamBtn.textContent = isStreaming ? "Pause Stream" : "Resume Stream";
      statusEl.textContent = isStreaming ? "Streaming live updates..." : "Stream paused";
    });

    function streamUpdate() {
      if (!isStreaming) return;

      const now = Date.now();

      for (let row = 0; row < data.length; row++) {
        const symbol = symbols[row];
        const start = basePrices.get(symbol);
        const prev = data[row][data[row].length - 1].price;
        const nextPrice = prev * (1 + (Math.random() - 0.5) * 0.008);

        data[row].push({
          symbol,
          time: now,
          price: nextPrice,
          pctChange: ((nextPrice - start) / start) * 100
        });

        if (data[row].length > timeSteps) {
          data[row].shift();
        }
      }

      render();
    }

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    render();

    setInterval(streamUpdate, 1000);
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each row is an array of time-series points:

```js
{
  symbol,
  time,
  price,
  pctChange
}
```

### Rendering
- The heatmap is drawn on a `<canvas>` for speed.
- D3 zoom manages pan/scale transforms.
- Each cell is colored based on percent change.

### Real-time updates
Every second:
- a new price is generated
- appended to each stock row
- oldest value is removed
- canvas rerenders

### Hover interaction
Mouse position is converted back through the zoom transform to identify the hovered cell.

