    }

    .subtitle {
      font-size: 13px;
      color: #94a3b8;
      margin-bottom: 14px;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="title">Real-Time Stock Price Heatmap</div>
    <div class="subtitle">
      X = time, Y = stock symbol, color = % change from baseline. Zoom/pan with mouse wheel + drag.
    </div>

    <div class="toolbar">
      <button id="toggleLiveBtn">Pause Live Updates</button>
      <button id="resetZoomBtn">Reset Zoom</button>
      <span class="status" id="statusText">Live updates running</span>
    </div>

    <div class="chart-wrapper" id="chartWrapper">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="legend" id="legend"></div>
  </div>

  <script>
    (() => {
      const symbols = [
        "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
        "NVDA", "META", "NFLX", "AMD", "INTC",
        "BABA", "ORCL", "CRM", "UBER", "SHOP"
      ];

      const timeSteps = 60; // columns visible in rolling window
      const updateIntervalMs = 1000;

      const margin = { top: 20, right: 20, bottom: 50, left: 80 };
      const outerWidth = 1200;
      const outerHeight = 650;
      const width = outerWidth - margin.left - margin.right;
      const height = outerHeight - margin.top - margin.bottom;

      const svg = d3.select("#chart")
        .attr("width", outerWidth)
        .attr("height", outerHeight);

      const root = svg.append("g")
        .attr("transform", `translate(${margin.left},${margin.top})`);

      const clipId = "heatmap-clip";

      svg.append("defs")
        .append("clipPath")
        .attr("id", clipId)
        .append("rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", width)
        .attr("height", height);

      const plot = root.append("g")
        .attr("clip-path", `url(#${clipId})`);

      const heatmapLayer = plot.append("g");
      const xGridLayer = root.append("g").attr("class", "grid");
      const yGridLayer = root.append("g").attr("class", "grid");

      const xAxisG = root.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(0,${height})`);

      const yAxisG = root.append("g")
        .attr("class", "axis");

      const tooltip = d3.select("#tooltip");

      const basePrices = new Map();
      const currentPrices = new Map();

      symbols.forEach(symbol => {
        const base = 100 + Math.random() * 400;
        basePrices.set(symbol, base);
        currentPrices.set(symbol, base);
      });

      let currentStep = 0;
      let live = true;

      const timeLabels = [];
      const data = [];

      function formatTimeLabel(date) {
        return d3.timeFormat("%H:%M:%S")(date);
      }

      function seedInitialData() {
        const now = new Date();
        for (let t = timeSteps - 1; t >= 0; t--) {
          const timestamp = new Date(now.getTime() - t * updateIntervalMs);
          timeLabels.push(timestamp);

          symbols.forEach(symbol => {
            const prev = currentPrices.get(symbol);
            const drift = (Math.random() - 0.5) * 1.8;
            const next = Math.max(5, prev + drift);
            currentPrices.set(symbol, next);

            const pctChange = ((next - basePrices.get(symbol)) / basePrices.get(symbol)) * 100;

            data.push({
              symbol,
              timestamp,
              step: currentStep,
              price: next,
              pctChange
            });
          });

          currentStep++;
        }
      }

      seedInitialData();

      const xScaleBase = d3.scaleBand()
        .domain(d3.range(timeSteps))
        .range([0, width])
        .paddingInner(0.02)
        .paddingOuter(0);

      const yScaleBase = d3.scaleBand()
        .domain(symbols)
        .range([0, height])
        .paddingInner(0.04)
        .paddingOuter(0);

      const colorScale = d3.scaleSequential()
        .domain([5, -5]) // reversed so red = negative, green = positive via interpolator below
        .interpolator(d3.interpolateRdYlGn);

      let currentXScale = xScaleBase.copy();
      let currentYScale = yScaleBase.copy();

      function getVisibleColumnDomain() {
        return d3.range(timeLabels.length);
      }

      function buildXTickValues(scale) {
        const domain = scale.domain();
        const maxTicks = Math.max(2, Math.floor(width / 100));
        const step = Math.max(1, Math.ceil(domain.length / maxTicks));
        return domain.filter((_, i) => i % step === 0);
      }

      function drawLegend() {
        const legendWidth = 320;
        const legendHeight = 14;

        const legend = d3.select("#legend");
        legend.html("");

        legend.append("span")
          .attr("class", "legend-label")
          .text("Price Change %");

        const legendSvg = legend.append("svg")
          .attr("width", legendWidth)
          .attr("height", 40);

        const defs = legendSvg.append("defs");
        const gradient = defs.append("linearGradient")
          .attr("id", "legend-gradient")
          .attr("x1", "0%")
          .attr("x2", "100%")
          .attr("y1", "0%")
          .attr("y2", "0%");

        const stops = d3.range(0, 1.01, 0.1);
        stops.forEach(s => {
          const value = -5 + s * 10;
          gradient.append("stop")
            .attr("offset", `${s * 100}%`)
            .attr("stop-color", colorScale(value));
        });

        legendSvg.append("rect")
          .attr("x", 0)
          .attr("y", 8)
          .attr("width", legendWidth)
          .attr("height", legendHeight)
          .attr("fill", "url(#legend-gradient)")
          .attr("stroke", "#475569");

        const legendScale = d3.scaleLinear()
          .domain([-5, 5])
          .range([0, legendWidth]);

        const legendAxis = d3.axisBottom(legendScale)
          .ticks(5)
          .tickFormat(d => `${d}%`);

        legendSvg.append("g")
          .attr("transform", `translate(0,${8 + legendHeight})`)
          .attr("class", "axis")
          .call(legendAxis);
      }

      drawLegend();

      function updateAxes() {
        const xTicks = buildXTickValues(currentXScale);

        const xAxis = d3.axisBottom(currentXScale)
          .tickValues(xTicks)
          .tickFormat(d => {
            const ts = timeLabels[d];
            return ts ? formatTimeLabel(ts) : "";
          });

        const yAxis = d3.axisLeft(currentYScale);

        xAxisG.call(xAxis);
        yAxisG.call(yAxis);

        const xGrid = d3.axisBottom(currentXScale)
          .tickValues(xTicks)
          .tickSize(-height)
          .tickFormat("");

        const yGrid = d3.axisLeft(currentYScale)
          .tickSize(-width)
          .tickFormat("");

        xGridLayer
          .attr("transform", `translate(0,${height})`)
          .call(xGrid);

        yGridLayer.call(yGrid);
      }

      function render() {
        const visibleDomain = getVisibleColumnDomain();
        currentXScale.domain(visibleDomain);
        currentYScale.domain(symbols);

        const cells = heatmapLayer.selectAll("rect.cell")
          .data(data, d => `${d.symbol}-${d.timestamp.getTime()}`);

        cells.join(
          enter => enter.append("rect")
            .attr("class", "cell")
            .attr("x", d => currentXScale(dataColumnIndex(d)))
            .attr("y", d => currentYScale(d.symbol))
            .attr("width", currentXScale.bandwidth())
            .attr("height", currentYScale.bandwidth())
            .attr("fill", d => colorScale(clamp(d.pctChange, -5, 5)))
            .on("mousemove", function(event, d) {
              const [mx, my] = d3.pointer(event, document.getElementById("chartWrapper"));
              tooltip
                .style("left", `${mx}px`)
                .style("top", `${my}px`)
                .style("opacity", 1)
                .html(`
                  <strong>${d.symbol}</strong><br/>
                  Time: ${formatTimeLabel(d.timestamp)}<br/>
                  Price: $${d.price.toFixed(2)}<br/>
                  Change: ${d.pctChange.toFixed(2)}%
                `);
            })
            .on("mouseleave", function() {
              tooltip.style("opacity", 0);
            }),
          update => update,
          exit => exit.remove()
        )
        .attr("x", d => currentXScale(dataColumnIndex(d)))
        .attr("y", d => currentYScale(d.symbol))
        .attr("width", currentXScale.bandwidth())
        .attr("height", currentYScale.bandwidth())
        .attr("fill", d => colorScale(clamp(d.pctChange, -5, 5)));

        updateAxes();
      }

      function dataColumnIndex(d) {
        const idx = timeLabels.findIndex(t => t.getTime() === d.timestamp.getTime());
        return idx;
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function pushNewTimeStep() {
        const timestamp = new Date();
        timeLabels.push(timestamp);

        symbols.forEach(symbol => {
          const prev = currentPrices.get(symbol);
          const volatility = symbol === "TSLA" || symbol === "NVDA" ? 3.2 : 1.5;
          const drift = (Math.random() - 0.5) * volatility;
          const next = Math.max(5, prev + drift);
          currentPrices.set(symbol, next);

          const pctChange = ((next - basePrices.get(symbol)) / basePrices.get(symbol)) * 100;

          data.push({
            symbol,
            timestamp,
            step: currentStep,
            price: next,
            pctChange
          });
        });

        currentStep++;

        while (timeLabels.length > timeSteps) {
          const removed = timeLabels.shift();
          const removedTime = removed.getTime();
          for (let i = data.length - 1; i >= 0; i--) {
            if (data[i].timestamp.getTime() === removedTime) {
              data.splice(i, 1);
            }
          }
        }
      }

      render();

      const zoom = d3.zoom()
        .scaleExtent([1, 8])
        .translateExtent([[0, 0], [width, height]])
        .extent([[0, 0], [width, height]])
        .on("zoom", zoomed);

      svg.append("rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", width)
        .attr("height", height)
        .attr("fill", "transparent")
        .style("cursor", "grab")
        .call(zoom);

      let currentTransform = d3.zoomIdentity;

      function zoomed(event) {
        currentTransform = event.transform;

        const zx = event.transform.rescaleX(
          d3.scaleLinear()
            .domain([0, timeLabels.length])
            .range([0, width])
        );

        const zy = event.transform.rescaleY(
          d3.scaleLinear()
            .domain([0, symbols.length])
            .range([0, height])
        );

        const xDomainContinuous = zx.domain();
        const yDomainContinuous = zy.domain();

        const xIndices = d3.range(timeLabels.length).filter(i =>
          i >= Math.floor(xDomainContinuous[0]) && i <= Math.ceil(xDomainContinuous[1])
        );

        const yIndices = d3.range(symbols.length).filter(i =>
          i >= Math.floor(yDomainContinuous[0]) && i <= Math.ceil(yDomainContinuous[1])
        );

        currentXScale = d3.scaleBand()
          .domain(xIndices)
          .range([
            zx(Math.max(0, xIndices[0] ?? 0)),
            zx(Math.min(timeLabels.length, (xIndices[xIndices.length - 1] ?? timeLabels.length - 1) + 1))
          ])
          .paddingInner(0.02);

        currentYScale = d3.scaleBand()
          .domain(yIndices.map(i => symbols[i]))
          .range([
            zy(Math.max(0, yIndices[0] ?? 0)),
            zy(Math.min(symbols.length, (yIndices[yIndices.length - 1] ?? symbols.length - 1) + 1))
          ])
          .paddingInner(0.04);

        heatmapLayer.selectAll("rect.cell")
          .attr("x", d => currentXScale(dataColumnIndex(d)))
          .attr("y", d => currentYScale(d.symbol))
          .attr("width", currentXScale.bandwidth())
          .attr("height", currentYScale.bandwidth())
          .attr("display", d => {
            const xOk = currentXScale.domain().includes(dataColumnIndex(d));
            const yOk = currentYScale.domain().includes(d.symbol);
            return xOk && yOk ? null : "none";
          });

        updateAxes();
      }

      let timer = setInterval(() => {
        if (!live) return;

        pushNewTimeStep();

        currentXScale = xScaleBase.copy().domain(d3.range(timeLabels.length));
        currentYScale = yScaleBase.copy().domain(symbols);

        svg.selectAll(".zoom-overlay-reset-helper").remove();
        svg.call(zoom.transform, d3.zoomIdentity);
        render();
      }, updateIntervalMs);

      document.getElementById("toggleLiveBtn").addEventListener("click", () => {
        live = !live;
        document.getElementById("toggleLiveBtn").textContent = live
          ? "Pause Live Updates"
          : "Resume Live Updates";
        document.getElementById("statusText").textContent = live
          ? "Live updates running"
          : "Live updates paused";
      });

      document.getElementById("resetZoomBtn").addEventListener("click", () => {
        currentXScale = xScaleBase.copy().domain(d3.range(timeLabels.length));
        currentYScale = yScaleBase.copy().domain(symbols);
        svg.call(zoom.transform, d3.zoomIdentity);
        render();
      });

      window.addEventListener("resize", () => {
        // This example uses fixed dimensions for simplicity.
        // If needed, I can provide a fully responsive version.
      });
    })();
  </script>
</body>
</html>
```

