      stroke: #1e293b;
      stroke-opacity: 0.8;
      shape-rendering: crispEdges;
    }

    .grid path {
      stroke-width: 0;
    }

    .legend text {
      fill: #cbd5e1;
      font-size: 11px;
    }

    .status {
      font-size: 13px;
      color: #94a3b8;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Real-Time Stock Price Heatmap</h1>
      <div class="controls">
        <button id="toggleStream">Pause Stream</button>
        <button id="resetZoom">Reset Zoom</button>
        <span class="status" id="status">Streaming live updates...</span>
      </div>
    </div>
    <div class="chart-wrapper" id="chartWrapper">
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "IBM", "CRM", "ADBE"
    ];

    const timeSteps = 60; // columns
    const updateInterval = 1000; // 1 sec
    let streaming = true;

    const margin = { top: 30, right: 30, bottom: 60, left: 80 };
    const wrapper = document.getElementById("chartWrapper");
    const tooltip = d3.select("#tooltip");
    const statusEl = document.getElementById("status");

    let width = wrapper.clientWidth - margin.left - margin.right;
    let height = wrapper.clientHeight - margin.top - margin.bottom;

    const svg = d3.select("#chartWrapper")
      .append("svg");

    const rootG = svg.append("g");
    const zoomLayer = rootG.append("g");
    const gridLayer = zoomLayer.append("g").attr("class", "grid");
    const heatmapLayer = zoomLayer.append("g").attr("class", "heatmap");
    const xAxisG = rootG.append("g").attr("class", "axis x-axis");
    const yAxisG = rootG.append("g").attr("class", "axis y-axis");
    const legendG = rootG.append("g").attr("class", "legend");

    const now = new Date();
    let timestamps = d3.range(timeSteps).map(i => new Date(now.getTime() - (timeSteps - 1 - i) * 1000));

    let data = [];
    const basePrices = {};

    stocks.forEach(stock => {
      basePrices[stock] = 100 + Math.random() * 300;
      timestamps.forEach(ts => {
        data.push({
          stock,
          time: ts,
          price: +(basePrices[stock] + (Math.random() - 0.5) * 10).toFixed(2)
        });
      });
    });

    let xScale = d3.scaleBand().padding(0.03);
    let yScale = d3.scaleBand().padding(0.03);
    let colorScale = d3.scaleSequential(d3.interpolateRdYlGn);
    let xAxisScale = d3.scaleBand();

    let zoomBehavior;

    function getPriceExtent() {
      return d3.extent(data, d => d.price);
    }

    function updateDimensions() {
      width = wrapper.clientWidth - margin.left - margin.right;
      height = wrapper.clientHeight - margin.top - margin.bottom;

      svg
        .attr("width", wrapper.clientWidth)
        .attr("height", wrapper.clientHeight);

      rootG.attr("transform", `translate(${margin.left},${margin.top})`);

      xScale.range([0, width]).domain(timestamps.map(d => d.toISOString()));
      xAxisScale.range([0, width]).domain(timestamps.map(d => d.toISOString()));
      yScale.range([0, height]).domain(stocks);

      xAxisG.attr("transform", `translate(${margin.left},${margin.top + height})`);
      yAxisG.attr("transform", `translate(${margin.left},${margin.top})`);

      legendG.attr("transform", `translate(${margin.left + width - 220},${margin.top - 22})`);
    }

    function renderAxes(rescaledX = null) {
      const scaleForAxis = rescaledX || xAxisScale;

      const xAxis = d3.axisBottom(scaleForAxis)
        .tickValues(scaleForAxis.domain().filter((d, i) => i % Math.ceil(timeSteps / 10) === 0))
        .tickFormat(d => {
          const date = new Date(d);
          return d3.timeFormat("%H:%M:%S")(date);
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end");

      yAxisG.call(yAxis);
    }

    function renderGrid() {
      const xLines = gridLayer.selectAll(".vline")
        .data(timestamps.map(d => d.toISOString()), d => d);

      xLines.join(
        enter => enter.append("line")
          .attr("class", "vline")
          .attr("y1", 0)
          .attr("y2", height)
          .attr("x1", d => xScale(d))
          .attr("x2", d => xScale(d))
          .attr("stroke", "#1e293b"),
        update => update
          .attr("y2", height)
          .attr("x1", d => xScale(d))
          .attr("x2", d => xScale(d)),
        exit => exit.remove()
      );

      const yLines = gridLayer.selectAll(".hline")
        .data(stocks, d => d);

      yLines.join(
        enter => enter.append("line")
          .attr("class", "hline")
          .attr("x1", 0)
          .attr("x2", width)
          .attr("y1", d => yScale(d))
          .attr("y2", d => yScale(d))
          .attr("stroke", "#1e293b"),
        update => update
          .attr("x2", width)
          .attr("y1", d => yScale(d))
          .attr("y2", d => yScale(d)),
        exit => exit.remove()
      );
    }

    function renderLegend() {
      legendG.selectAll("*").remove();

      const legendWidth = 180;
      const legendHeight = 10;
      const [minPrice, maxPrice] = getPriceExtent();

      const defs = svg.select("defs").empty() ? svg.append("defs") : svg.select("defs");
      defs.select("#legend-gradient").remove();

      const gradient = defs.append("linearGradient")
        .attr("id", "legend-gradient")
        .attr("x1", "0%")
        .attr("x2", "100%")
        .attr("y1", "0%")
        .attr("y2", "0%");

      d3.range(0, 1.01, 0.1).forEach(t => {
        gradient.append("stop")
          .attr("offset", `${t * 100}%`)
          .attr("stop-color", colorScale(minPrice + t * (maxPrice - minPrice)));
      });

      legendG.append("text")
        .attr("x", 0)
        .attr("y", 0)
        .text("Price");

      legendG.append("rect")
        .attr("x", 0)
        .attr("y", 6)
        .attr("width", legendWidth)
        .attr("height", legendHeight)
        .attr("fill", "url(#legend-gradient)")
        .attr("stroke", "#475569");

      legendG.append("text")
        .attr("x", 0)
        .attr("y", 30)
        .text(minPrice.toFixed(2));

      legendG.append("text")
        .attr("x", legendWidth)
        .attr("y", 30)
        .attr("text-anchor", "end")
        .text(maxPrice.toFixed(2));
    }

    function renderHeatmap() {
      const [minPrice, maxPrice] = getPriceExtent();
      colorScale.domain([minPrice, maxPrice]);

      const cells = heatmapLayer.selectAll("rect.cell")
        .data(data, d => `${d.stock}-${d.time.toISOString()}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => xScale(d.time.toISOString()))
          .attr("y", d => yScale(d.stock))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.price))
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .style("left", `${event.offsetX + 14}px`)
              .style("top", `${event.offsetY + 14}px`)
              .html(`
                <strong>${d.stock}</strong><br/>
                Time: ${d3.timeFormat("%H:%M:%S")(d.time)}<br/>
                Price: $${d.price.toFixed(2)}
              `);
            d3.select(this).attr("stroke", "#fff").attr("stroke-width", 1);
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
            d3.select(this).attr("stroke", "none");
          }),
        update => update
          .transition()
          .duration(400)
          .attr("x", d => xScale(d.time.toISOString()))
          .attr("y", d => yScale(d.stock))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.price)),
        exit => exit.remove()
      );

      renderLegend();
    }

    function render() {
      updateDimensions();
      renderAxes();
      renderGrid();
      renderHeatmap();
    }

    function streamUpdate() {
      if (!streaming) return;

      const nextTime = new Date(timestamps[timestamps.length - 1].getTime() + 1000);
      timestamps.shift();
      timestamps.push(nextTime);

      const latestByStock = new Map();
      data.forEach(d => {
        latestByStock.set(d.stock, d);
      });

      data = data.filter(d => d.time > timestamps[0]);

      stocks.forEach(stock => {
        const prev = data
          .filter(d => d.stock === stock)
          .sort((a, b) => a.time - b.time)
          .slice(-1)[0];

        const lastPrice = prev ? prev.price : basePrices[stock];
        const drift = (Math.random() - 0.5) * 4;
        const newPrice = Math.max(10, +(lastPrice + drift).toFixed(2));

        data.push({
          stock,
          time: nextTime,
          price: newPrice
        });
      });

      xScale.domain(timestamps.map(d => d.toISOString()));
      xAxisScale.domain(timestamps.map(d => d.toISOString()));

      render();
    }

    function setupZoom() {
      zoomBehavior = d3.zoom()
        .scaleExtent([1, 8])
        .translateExtent([[0, 0], [width, height]])
        .extent([[0, 0], [width, height]])
        .on("zoom", (event) => {
          const transform = event.transform;
          zoomLayer.attr("transform", transform);

          const zx = transform.rescaleX(
            d3.scaleLinear()
              .domain([0, timestamps.length])
              .range([0, width])
          );

          const domain = timestamps.map(d => d.toISOString());
          const visible = domain.map((d, i) => ({
            key: d,
            pos: zx(i)
          }));

          const tempScale = d3.scaleBand()
            .domain(visible.map(d => d.key))
            .range([d3.min(visible, d => d.pos), d3.max(visible, d => d.pos)])
            .padding(0.03);

          renderAxes(tempScale);
        });

      svg.call(zoomBehavior);
    }

    document.getElementById("toggleStream").addEventListener("click", () => {
      streaming = !streaming;
      document.getElementById("toggleStream").textContent = streaming ? "Pause Stream" : "Resume Stream";
      statusEl.textContent = streaming ? "Streaming live updates..." : "Stream paused";
    });

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(500).call(zoomBehavior.transform, d3.zoomIdentity);
    });

    window.addEventListener("resize", () => {
      render();
      setupZoom();
    });

    render();
    setupZoom();
    setInterval(streamUpdate, updateInterval);
  </script>
</body>
</html>
