<body>
  <div id="container">
    <div class="title">Real-Time Stock Price Heatmap</div>
    <div class="legend">
      <div>Price Change (%)</div>
      <div class="legend-bar"></div>
      <div class="legend-labels">
        <span>-5%</span>
        <span>0%</span>
        <span>+5%</span>
      </div>
    </div>
    <div class="tooltip" id="tooltip"></div>
  </div>

  <script>
    const container = document.getElementById("container");
    const tooltip = d3.select("#tooltip");

    const margin = { top: 60, right: 30, bottom: 40, left: 80 };
    const outerWidth = window.innerWidth;
    const outerHeight = window.innerHeight;
    const width = outerWidth - margin.left - margin.right;
    const height = outerHeight - margin.top - margin.bottom;

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "CRM", "UBER", "SHOP"
    ];

    const maxTimePoints = 60;
    let timeIndex = 0;

    // Initial base prices
    const basePrices = {};
    symbols.forEach(sym => {
      basePrices[sym] = 100 + Math.random() * 900;
    });

    // Data structure: one entry per symbol/time cell
    let data = [];

    // Track current prices
    const currentPrices = {};
    symbols.forEach(sym => currentPrices[sym] = basePrices[sym]);

    // Seed initial timeline
    for (let t = 0; t < maxTimePoints; t++) {
      symbols.forEach(sym => {
        const drift = (Math.random() - 0.5) * 0.01;
        currentPrices[sym] *= (1 + drift);
        const pctChange = ((currentPrices[sym] - basePrices[sym]) / basePrices[sym]) * 100;
        data.push({
          symbol: sym,
          time: t,
          price: currentPrices[sym],
          change: pctChange
        });
      });
      timeIndex++;
    }

    const svg = d3.select("#container")
      .append("svg")
      .attr("viewBox", `0 0 ${outerWidth} ${outerHeight}`);

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const heatmapLayer = root.append("g").attr("class", "heatmap-layer");
    const xAxisLayer = root.append("g")
      .attr("class", "axis x-axis")
      .attr("transform", `translate(0,${height})`);
    const yAxisLayer = root.append("g")
      .attr("class", "axis y-axis");

    const xScale = d3.scaleBand()
      .domain(d3.range(maxTimePoints))
      .range([0, width])
      .padding(0.02);

    const yScale = d3.scaleBand()
      .domain(symbols)
      .range([0, height])
      .padding(0.02);

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b30000", "#222222", "#00b300"])
      .clamp(true);

    const xAxis = d3.axisBottom(xScale)
      .tickValues(xScale.domain().filter(d => d % 5 === 0))
      .tickFormat(d => `T-${maxTimePoints - d}`);

    const yAxis = d3.axisLeft(yScale);

    xAxisLayer.call(xAxis);
    yAxisLayer.call(yAxis);

    function render() {
      const cells = heatmapLayer.selectAll("rect")
        .data(data, d => `${d.symbol}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change))
        .on("mousemove", function(event, d) {
          tooltip
            .style("opacity", 1)
            .style("left", `${event.pageX + 12}px`)
            .style("top", `${event.pageY + 12}px`)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Time: ${d.time}<br/>
              Price: $${d.price.toFixed(2)}<br/>
              Change: ${d.change.toFixed(2)}%
            `);
        })
        .on("mouseleave", function() {
          tooltip.style("opacity", 0);
        })
        .merge(cells)
        .transition()
        .duration(300)
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change));

      cells.exit().remove();

      xAxisLayer.call(
        d3.axisBottom(xScale)
          .tickValues(xScale.domain().filter(d => d % 5 === 0))
          .tickFormat(d => `${d}`)
      );
      yAxisLayer.call(yAxis);
    }

    function pushRealtimeUpdate() {
      // Shift timeline left by 1
      data = data
        .map(d => ({ ...d, time: d.time - 1 }))
        .filter(d => d.time >= 0);

      // Add newest column on right
      symbols.forEach(sym => {
        const drift = (Math.random() - 0.5) * 0.02;
        currentPrices[sym] *= (1 + drift);
        const pctChange = ((currentPrices[sym] - basePrices[sym]) / basePrices[sym]) * 100;

        data.push({
          symbol: sym,
          time: maxTimePoints - 1,
          price: currentPrices[sym],
          change: pctChange
        });
      });

      render();
    }

    render();

    // Zoom/pan
    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [outerWidth, outerHeight]])
      .extent([[0, 0], [outerWidth, outerHeight]])
      .on("zoom", (event) => {
        heatmapLayer.attr("transform", event.transform);
        xAxisLayer.attr(
          "transform",
          `translate(${event.transform.x},${height * event.transform.k + event.transform.y}) scale(${event.transform.k},${event.transform.k})`
        );
        yAxisLayer.attr(
          "transform",
          `translate(${event.transform.x},${event.transform.y}) scale(${event.transform.k},${event.transform.k})`
        );
      });

    svg.call(zoom);

    // Real-time updates every second
    setInterval(pushRealtimeUpdate, 1000);

    // Resize handling
    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
```

