    }

    .legend {
      position: absolute;
      right: 16px;
      bottom: 16px;
      background: rgba(18, 26, 48, 0.9);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px;
      font-size: 12px;
      color: var(--muted);
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      border-radius: 999px;
      margin-bottom: 6px;
      background: linear-gradient(
        to right,
        rgb(180, 35, 35),
        rgb(90, 90, 90),
        rgb(30, 170, 70)
      );
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <div class="stat" id="symbolsStat"></div>
      <div class="stat" id="windowStat"></div>
      <button id="resetViewBtn">Reset View</button>
      <button id="pauseBtn">Pause</button>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-bar"></div>
        <div>-5% &nbsp;&nbsp; change &nbsp;&nbsp; +5%</div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('chartWrap');
    const tooltip = document.getElementById('tooltip');
    const symbolsStat = document.getElementById('symbolsStat');
    const windowStat = document.getElementById('windowStat');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    const DPR = window.devicePixelRatio || 1;

    const symbols = [
      'AAPL','MSFT','GOOG','AMZN','META','NVDA','TSLA','NFLX',
      'AMD','INTC','ORCL','CRM','UBER','SHOP','BABA','PYPL'
    ];

    const state = {
      running: true,
      maxColumns: 180,
      timestamps: [],
      data: new Map(),
      basePrices: new Map(),
      latestPrices: new Map(),

      viewStartCol: 0,
      viewColCount: 60,

      rowHeight: 28,
      leftAxisWidth: 80,
      topAxisHeight: 30,

      isDragging: false,
      dragStartX: 0,
      dragStartViewStart: 0,

      hover: null
    };

    function initData() {
      const now = Date.now();
      symbols.forEach(symbol => {
        const base = 100 + Math.random() * 400;
        state.basePrices.set(symbol, base);
        state.latestPrices.set(symbol, base);
        state.data.set(symbol, []);
      });

      for (let i = 0; i < state.viewColCount; i++) {
        const ts = now - (state.viewColCount - i) * 1000;
        appendTick(ts, false);
      }

      state.viewStartCol = Math.max(0, state.timestamps.length - state.viewColCount);
    }

    function appendTick(timestamp = Date.now(), trim = true) {
      state.timestamps.push(timestamp);

      symbols.forEach(symbol => {
        const prev = state.latestPrices.get(symbol);
        const drift = (Math.random() - 0.5) * 1.8;
        const next = Math.max(1, prev + drift);
        state.latestPrices.set(symbol, next);

        const base = state.basePrices.get(symbol);
        const pct = ((next - base) / base) * 100;
        state.data.get(symbol).push({
          timestamp,
          price: next,
          pctChange: pct
        });

        if (trim && state.data.get(symbol).length > state.maxColumns) {
          state.data.get(symbol).shift();
        }
      });

      if (trim && state.timestamps.length > state.maxColumns) {
        state.timestamps.shift();
      }

      const maxStart = Math.max(0, state.timestamps.length - state.viewColCount);
      if (state.viewStartCol >= maxStart - 2) {
        state.viewStartCol = maxStart;
      }
    }

    function resize() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * DPR;
      canvas.height = rect.height * DPR;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function colorForValue(pct) {
      const clamped = clamp(pct, -5, 5);
      if (clamped < 0) {
        const t = (clamped + 5) / 5;
        const r = Math.round(180 * (1 - t) + 90 * t);
        const g = Math.round(35 * (1 - t) + 90 * t);
        const b = Math.round(35 * (1 - t) + 90 * t);
        return `rgb(${r},${g},${b})`;
      } else {
        const t = clamped / 5;
        const r = Math.round(90 * (1 - t) + 30 * t);
        const g = Math.round(90 * (1 - t) + 170 * t);
        const b = Math.round(90 * (1 - t) + 70 * t);
        return `rgb(${r},${g},${b})`;
      }
    }

    function formatTime(ts) {
      const d = new Date(ts);
      return d.toLocaleTimeString();
    }

    function getLayout() {
      const width = canvas.width / DPR;
      const height = canvas.height / DPR;
      const plotX = state.leftAxisWidth;
      const plotY = state.topAxisHeight;
      const plotW = width - state.leftAxisWidth;
      const plotH = height - state.topAxisHeight;
      const visibleRows = symbols.length;
      const rowH = plotH / visibleRows;
      const colW = plotW / state.viewColCount;

      return { width, height, plotX, plotY, plotW, plotH, rowH, colW };
    }

    function drawAxes(layout) {
      const { width, height, plotX, plotY, plotW, plotH, rowH, colW } = layout;

      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;

      for (let r = 0; r <= symbols.length; r++) {
        const y = plotY + r * rowH;
        ctx.beginPath();
        ctx.moveTo(plotX, y);
        ctx.lineTo(plotX + plotW, y);
        ctx.stroke();
      }

      for (let c = 0; c <= state.viewColCount; c++) {
        const x = plotX + c * colW;
        ctx.beginPath();
        ctx.moveTo(x, plotY);
        ctx.lineTo(x, plotY + plotH);
        ctx.stroke();
      }

      ctx.fillStyle = '#91a0c6';
      ctx.font = '12px sans-serif';
      ctx.textBaseline = 'middle';

      symbols.forEach((symbol, i) => {
        const y = plotY + i * rowH + rowH / 2;
        ctx.fillText(symbol, 10, y);
      });

      ctx.textBaseline = 'alphabetic';
      ctx.textAlign = 'center';

      const step = Math.max(1, Math.floor(state.viewColCount / 8));
      for (let c = 0; c < state.viewColCount; c += step) {
        const idx = state.viewStartCol + c;
        const ts = state.timestamps[idx];
        if (!ts) continue;
        const x = plotX + c * colW + colW / 2;
        ctx.fillText(formatTime(ts), x, 20);
      }

      ctx.textAlign = 'start';
    }

    function drawHeatmap(layout) {
      const { plotX, plotY, rowH, colW } = layout;

      symbols.forEach((symbol, row) => {
        const series = state.data.get(symbol);
        for (let c = 0; c < state.viewColCount; c++) {
          const idx = state.viewStartCol + c;
          const point = series[idx];
          if (!point) continue;

          const x = plotX + c * colW;
          const y = plotY + row * rowH;

          ctx.fillStyle = colorForValue(point.pctChange);
          ctx.fillRect(x + 0.5, y + 0.5, Math.ceil(colW), Math.ceil(rowH));

          if (
            state.hover &&
            state.hover.row === row &&
            state.hover.col === c
          ) {
            ctx.strokeStyle = 'rgba(255,255,255,0.9)';
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, colW - 2, rowH - 2);
          }
        }
      });
    }

    function draw() {
      const layout = getLayout();
      drawAxes(layout);
      drawHeatmap(layout);

      symbolsStat.textContent = `Symbols: ${symbols.length}`;
      windowStat.textContent = `Visible window: ${state.viewColCount}s`;
    }

    function getCellFromMouse(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const layout = getLayout();

      if (
        x < layout.plotX ||
        y < layout.plotY ||
        x > layout.plotX + layout.plotW ||
        y > layout.plotY + layout.plotH
      ) {
        return null;
      }

      const col = Math.floor((x - layout.plotX) / layout.colW);
      const row = Math.floor((y - layout.plotY) / layout.rowH);
      const dataIndex = state.viewStartCol + col;

      if (row < 0 || row >= symbols.length) return null;
      if (col < 0 || col >= state.viewColCount) return null;

      const symbol = symbols[row];
      const point = state.data.get(symbol)[dataIndex];
      if (!point) return null;

      return { row, col, symbol, point, x, y };
    }

    function showTooltip(cell, clientX, clientY) {
      tooltip.style.display = 'block';
      tooltip.style.left = `${clientX - wrap.getBoundingClientRect().left}px`;
      tooltip.style.top = `${clientY - wrap.getBoundingClientRect().top}px`;
      tooltip.innerHTML = `
        <strong>${cell.symbol}</strong><br>
        Time: ${formatTime(cell.point.timestamp)}<br>
        Price: $${cell.point.price.toFixed(2)}<br>
        Change: ${cell.point.pctChange.toFixed(2)}%
      `;
    }

    canvas.addEventListener('mousemove', (e) => {
      if (state.isDragging) {
        const dx = e.clientX - state.dragStartX;
        const layout = getLayout();
        const deltaCols = Math.round(dx / layout.colW);
        const maxStart = Math.max(0, state.timestamps.length - state.viewColCount);
        state.viewStartCol = clamp(
          state.dragStartViewStart - deltaCols,
          0,
          maxStart
        );
        draw();
        return;
      }

      const cell = getCellFromMouse(e.clientX, e.clientY);
      if (cell) {
        state.hover = { row: cell.row, col: cell.col };
        showTooltip(cell, e.clientX, e.clientY);
      } else {
        state.hover = null;
        tooltip.style.display = 'none';
      }
      draw();
    });

    canvas.addEventListener('mouseleave', () => {
      state.hover = null;
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('mousedown', (e) => {
      state.isDragging = true;
      state.dragStartX = e.clientX;
      state.dragStartViewStart = state.viewStartCol;
      canvas.style.cursor = 'grabbing';
    });

    window.addEventListener('mouseup', () => {
      state.isDragging = false;
      canvas.style.cursor = 'default';
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const delta = Math.sign(e.deltaY);
      const nextCount = clamp(state.viewColCount + delta * 5, 10, 120);

      if (nextCount === state.viewColCount) return;

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const layout = getLayout();
      const relativeX = clamp(mouseX - layout.plotX, 0, layout.plotW);
      const ratio = layout.plotW > 0 ? relativeX / layout.plotW : 0.5;
      const anchorCol = state.viewStartCol + Math.floor(ratio * state.viewColCount);

      state.viewColCount = nextCount;
      const nextStart = anchorCol - Math.floor(ratio * state.viewColCount);
      const maxStart = Math.max(0, state.timestamps.length - state.viewColCount);
      state.viewStartCol = clamp(nextStart, 0, maxStart);

      draw();
    }, { passive: false });

    resetViewBtn.addEventListener('click', () => {
      state.viewColCount = 60;
      state.viewStartCol = Math.max(0, state.timestamps.length - state.viewColCount);
      draw();
    });

    pauseBtn.addEventListener('click', () => {
      state.running = !state.running;
      pauseBtn.textContent = state.running ? 'Pause' : 'Resume';
    });

    initData();
    resize();
    window.addEventListener('resize', resize);

    setInterval(() => {
      if (!state.running) return;
      appendTick(Date.now(), true);
      draw();
    }, 1000);
  </script>
</body>
</html>
