      font-size: 13px;
    }

    .toolbar button {
      cursor: pointer;
    }

    .toolbar .spacer {
      flex: 1;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--muted);
    }

    .legend-bar {
      width: 180px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(
        90deg,
        #b42318 0%,
        #f97066 25%,
        #2b3048 50%,
        #5eead4 75%,
        #0ea5a4 100%
      );
      border: 1px solid #313856;
    }

    .canvas-wrap {
      position: relative;
      flex: 1;
      overflow: hidden;
      background:
        linear-gradient(to right, rgba(255,255,255,0.02) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(255,255,255,0.02) 1px, transparent 1px);
      background-size: 40px 40px;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(18, 21, 35, 0.96);
      border: 1px solid #323a5a;
      color: var(--text);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      min-width: 160px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      transform: translate(12px, 12px);
      display: none;
      z-index: 10;
    }

    .tooltip .muted {
      color: var(--muted);
    }

    .status {
      font-size: 12px;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Heatmap</h1>

      <button id="resetViewBtn">Reset View</button>

      <label>
        Update Speed
        <select id="speedSelect">
          <option value="1000">1s</option>
          <option value="500" selected>500ms</option>
          <option value="200">200ms</option>
          <option value="100">100ms</option>
        </select>
      </label>

      <label>
        Symbols
        <select id="symbolCountSelect">
          <option value="10">10</option>
          <option value="20" selected>20</option>
          <option value="40">40</option>
        </select>
      </label>

      <div class="spacer"></div>

      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>

      <div class="status" id="statusText"></div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmapCanvas"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;
        this.dpr = Math.max(1, window.devicePixelRatio || 1);

        this.symbols = [];
        this.timeBuckets = 120; // columns
        this.data = []; // rows x columns
        this.timestamps = [];

        this.baseCellWidth = 18;
        this.baseCellHeight = 22;
        this.scaleX = 1;
        this.scaleY = 1;
        this.offsetX = 80; // leave room for row labels
        this.offsetY = 30; // leave room for column labels

        this.minScaleX = 0.4;
        this.maxScaleX = 4;
        this.minScaleY = 0.5;
        this.maxScaleY = 3;

        this.isDragging = false;
        this.lastMouseX = 0;
        this.lastMouseY = 0;
        this.hoverCell = null;

        this.priceBounds = { min: -5, max: 5 }; // percent change color scale

        this.resizeObserver = new ResizeObserver(() => this.resize());
        this.resizeObserver.observe(this.canvas.parentElement);

        this.attachEvents();
        this.resize();
      }

      init(symbolCount = 20) {
        this.symbols = this.generateSymbols(symbolCount);
        this.timestamps = Array.from({ length: this.timeBuckets }, (_, i) => {
          const d = new Date(Date.now() - (this.timeBuckets - 1 - i) * 1000);
          return d;
        });

        this.data = this.symbols.map(symbol => {
          const basePrice = 50 + Math.random() * 250;
          let price = basePrice;
          const row = [];

          for (let i = 0; i < this.timeBuckets; i++) {
            price = this.nextPrice(price);
            row.push({
              symbol,
              time: this.timestamps[i],
              price,
              basePrice,
              changePct: ((price - basePrice) / basePrice) * 100
            });
          }
          return row;
        });

        this.render();
      }

      generateSymbols(count) {
        const preset = [
          'AAPL', 'MSFT', 'GOOG', 'AMZN', 'NVDA', 'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
          'ORCL', 'CRM', 'ADBE', 'UBER', 'SHOP', 'SNOW', 'PLTR', 'BABA', 'SONY', 'QCOM',
          'AVGO', 'SAP', 'IBM', 'PYPL', 'SQ', 'ZM', 'DOCU', 'CSCO', 'ASML', 'TXN',
          'MU', 'PANW', 'TEAM', 'MELI', 'SE', 'ROKU', 'COIN', 'DDOG', 'NET', 'OKTA'
        ];
        return preset.slice(0, count);
      }

      nextPrice(current) {
        const volatility = 0.008;
        const drift = (Math.random() - 0.5) * 2 * volatility;
        return Math.max(1, current * (1 + drift));
      }

      updateStream() {
        const now = new Date();
        this.timestamps.shift();
        this.timestamps.push(now);

        for (let r = 0; r < this.data.length; r++) {
          const row = this.data[r];
          const prev = row[row.length - 1];
          const price = this.nextPrice(prev.price);
          const cell = {
            symbol: prev.symbol,
            time: now,
            price,
            basePrice: prev.basePrice,
            changePct: ((price - prev.basePrice) / prev.basePrice) * 100
          };
          row.shift();
          row.push(cell);
        }

        this.render();
      }

      attachEvents() {
        this.canvas.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.lastMouseX = e.clientX;
          this.lastMouseY = e.clientY;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.isDragging) {
            const dx = e.clientX - this.lastMouseX;
            const dy = e.clientY - this.lastMouseY;
            this.offsetX += dx;
            this.offsetY += dy;
            this.lastMouseX = e.clientX;
            this.lastMouseY = e.clientY;
            this.render();
          } else {
            this.updateHover(x, y, e.clientX - rect.left, e.clientY - rect.top);
          }
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

          const prevScaleX = this.scaleX;
          const prevScaleY = this.scaleY;

          this.scaleX = this.clamp(this.scaleX * zoomFactor, this.minScaleX, this.maxScaleX);
          this.scaleY = this.clamp(this.scaleY * zoomFactor, this.minScaleY, this.maxScaleY);

          const worldX = (mouseX - this.offsetX) / (this.baseCellWidth * prevScaleX);
          const worldY = (mouseY - this.offsetY) / (this.baseCellHeight * prevScaleY);

          this.offsetX = mouseX - worldX * this.baseCellWidth * this.scaleX;
          this.offsetY = mouseY - worldY * this.baseCellHeight * this.scaleY;

          this.render();
        }, { passive: false });
      }

      updateHover(x, y, tooltipX, tooltipY) {
        const cellWidth = this.baseCellWidth * this.scaleX;
        const cellHeight = this.baseCellHeight * this.scaleY;

        const col = Math.floor((x - this.offsetX) / cellWidth);
        const row = Math.floor((y - this.offsetY) / cellHeight);

        if (
          row >= 0 && row < this.data.length &&
          col >= 0 && col < this.timeBuckets
        ) {
          this.hoverCell = { row, col };
          const cell = this.data[row][col];
          this.tooltip.innerHTML = `
            <div><strong>${cell.symbol}</strong></div>
            <div class="muted">${cell.time.toLocaleTimeString()}</div>
            <div>Price: $${cell.price.toFixed(2)}</div>
            <div>Change: <strong style="color:${this.getTextColor(cell.changePct)}">${cell.changePct.toFixed(2)}%</strong></div>
          `;
          this.tooltip.style.left = `${tooltipX}px`;
          this.tooltip.style.top = `${tooltipY}px`;
          this.tooltip.style.display = 'block';
          this.render();
        } else {
          this.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        }
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.canvas.width = Math.floor(rect.width * this.dpr);
        this.canvas.height = Math.floor(rect.height * this.dpr);
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      resetView() {
        this.scaleX = 1;
        this.scaleY = 1;
        this.offsetX = 80;
        this.offsetY = 30;
        this.render();
      }

      clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      getCellColor(changePct) {
        const min = this.priceBounds.min;
        const max = this.priceBounds.max;
        const v = this.clamp(changePct, min, max);

        if (v < 0) {
          const t = (v - min) / (0 - min);
          return this.lerpColor([180, 35, 24], [43, 48, 72], t);
        } else {
          const t = v / max;
          return this.lerpColor([43, 48, 72], [14, 165, 164], t);
        }
      }

      getTextColor(changePct) {
        return changePct >= 0 ? '#5eead4' : '#f97066';
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const bch = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${bch})`;
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);

        const cellWidth = this.baseCellWidth * this.scaleX;
        const cellHeight = this.baseCellHeight * this.scaleY;

        // Draw cells
        for (let r = 0; r < this.data.length; r++) {
          for (let c = 0; c < this.timeBuckets; c++) {
            const x = this.offsetX + c * cellWidth;
            const y = this.offsetY + r * cellHeight;

            if (x + cellWidth < 0 || y + cellHeight < 0 || x > width || y > height) {
              continue;
            }

            const cell = this.data[r][c];
            ctx.fillStyle = this.getCellColor(cell.changePct);
            ctx.fillRect(x, y, cellWidth - 1, cellHeight - 1);

            if (this.hoverCell && this.hoverCell.row === r && this.hoverCell.col === c) {
              ctx.strokeStyle = '#ffffff';
              ctx.lineWidth = 2;
              ctx.strokeRect(x + 1, y + 1, cellWidth - 3, cellHeight - 3);
            }
          }
        }

        // Row labels
        ctx.fillStyle = '#cfd6f6';
        ctx.font = '12px sans-serif';
        ctx.textBaseline = 'middle';
        for (let r = 0; r < this.symbols.length; r++) {
          const y = this.offsetY + r * cellHeight + cellHeight / 2;
          if (y < -20 || y > height + 20) continue;
          ctx.fillText(this.symbols[r], 8, y);
        }

        // Column labels
        ctx.fillStyle = '#8d95b8';
        ctx.textBaseline = 'top';
        const labelEvery = Math.max(1, Math.floor(60 / this.scaleX));
        for (let c = 0; c < this.timestamps.length; c += labelEvery) {
          const x = this.offsetX + c * cellWidth;
          if (x < -50 || x > width + 50) continue;
          const label = this.timestamps[c].toLocaleTimeString([], {
            minute: '2-digit',
            second: '2-digit'
          });
          ctx.save();
          ctx.translate(x + 2, 8);
          ctx.rotate(-Math.PI / 4);
          ctx.fillText(label, 0, 0);
          ctx.restore();
        }

        // Border guides
        ctx.strokeStyle = '#2a3150';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(this.offsetX - 1, 0);
        ctx.lineTo(this.offsetX - 1, height);
        ctx.moveTo(0, this.offsetY - 1);
        ctx.lineTo(width, this.offsetY - 1);
        ctx.stroke();

        this.statusEl.textContent =
          `Zoom: ${this.scaleX.toFixed(2)}x, ${this.scaleY.toFixed(2)}x · ` +
          `Symbols: ${this.symbols.length} · Buckets: ${this.timeBuckets}`;
      }
    }

    const canvas = document.getElementById('heatmapCanvas');
    const tooltip = document.getElementById('tooltip');
    const statusText = document.getElementById('statusText');

    const heatmap = new StockHeatmap(canvas, tooltip, statusText);
    heatmap.init(20);

    let intervalMs = Number(document.getElementById('speedSelect').value);
    let timer = setInterval(() => heatmap.updateStream(), intervalMs);

    function restartTimer() {
      clearInterval(timer);
      timer = setInterval(() => heatmap.updateStream(), intervalMs);
    }

    document.getElementById('speedSelect').addEventListener('change', (e) => {
      intervalMs = Number(e.target.value);
      restartTimer();
    });

    document.getElementById('symbolCountSelect').addEventListener('change', (e) => {
      const count = Number(e.target.value);
      heatmap.init(count);
    });

    document.getElementById('resetViewBtn').addEventListener('click', () => {
      heatmap.resetView();
    });
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each heatmap cell stores:

```js
{
  symbol,
  time,
  price,
  basePrice,
  changePct
}
```

### Real-time updates
A timer shifts the heatmap left and appends a new price point for each stock:

```js
row.shift();
row.push(newCell);
```

### Zoom/pan
- **Mouse wheel** adjusts `scaleX` and `scaleY`
- **Drag** changes `offsetX` and `offsetY`

### Rendering
Canvas redraws the visible grid on each update or interaction.

