<body>
  <div id="app">
    <div class="toolbar">
      <button id="toggle-stream">Pause Stream</button>
      <button id="reset-zoom">Reset Zoom</button>
      <div class="status" id="status">Streaming updates...</div>
    </div>
    <div id="chart-container">
      <canvas id="heatmap"></canvas>
      <svg id="overlay"></svg>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div>Price Change</div>
        <div class="legend-gradient"></div>
        <div class="legend-labels">
          <span>-3%</span>
          <span>0%</span>
          <span>+3%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "AMD", "NFLX", "INTC",
      "CRM", "ORCL", "IBM", "UBER", "SHOP",
      "BABA", "PYPL", "ADBE", "QCOM", "SNOW"
    ];

    const maxTimeSteps = 120;
    const updateIntervalMs = 1000;

    const margin = { top: 20, right: 24, bottom: 40, left: 80 };

    const container = document.getElementById("chart-container");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const toggleBtn = document.getElementById("toggle-stream");
    const resetZoomBtn = document.getElementById("reset-zoom");

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    const now = Date.now();
    let timestamps = d3.range(maxTimeSteps).map(i => new Date(now - (maxTimeSteps - 1 - i) * updateIntervalMs));

    let data = symbols.map(symbol => ({
      symbol,
      values: timestamps.map((ts, i) => ({
        time: ts,
        value: randomChange(symbol, i)
      }))
    }));

    function randomChange(symbol, i) {
      const base = (Math.sin(i / 8 + symbol.length) + Math.cos(i / 13)) * 0.8;
      const noise = (Math.random() - 0.5) * 1.2;
      return clamp(base + noise, -3, 3);
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    const baseXScale = d3.scaleTime();
    const baseYScale = d3.scaleBand().domain(symbols).paddingInner(0.05).paddingOuter(0.02);

    let currentTransform = d3.zoomIdentity;

    const colorScale = d3.scaleLinear()
      .domain([-3, 0, 3])
      .range(["#ef4444", "#1f2937", "#22c55e"])
      .clamp(true);

    const xAxisG = svg.append("g").attr("class", "axis x-axis");
    const yAxisG = svg.append("g").attr("class", "axis y-axis");

    const clipId = "plot-clip";

    svg.append("defs")
      .append("clipPath")
      .attr("id", clipId)
      .append("rect");

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([[0, 0], [100000, 100000]])
      .extent([[0, 0], [100000, 100000]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    function resize() {
      const rect = container.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      svg.attr("width", width).attr("height", height);

      svg.select(`#${clipId} rect`)
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      baseXScale
        .domain(d3.extent(timestamps))
        .range([margin.left, margin.left + innerWidth]);

      baseYScale
        .range([margin.top, margin.top + innerHeight]);

      render();
    }

    function getScaledX() {
      return currentTransform.rescaleX(baseXScale);
    }

    function getScaledY() {
      const k = currentTransform.k;
      const ty = currentTransform.y;
      return (symbol) => {
        const y = baseYScale(symbol);
        return y * k + ty;
      };
    }

    function getScaledBandHeight() {
      return baseYScale.bandwidth() * currentTransform.k;
    }

    function renderAxes(xScale) {
      const xAxis = d3.axisBottom(xScale)
        .ticks(Math.max(2, Math.floor(innerWidth / 100)))
        .tickFormat(d3.timeFormat("%H:%M:%S"));

      xAxisG
        .attr("transform", `translate(0, ${margin.top + innerHeight})`)
        .call(xAxis);

      const scaledY = getScaledY();
      const visibleSymbols = symbols.filter(symbol => {
        const y = scaledY(symbol);
        const h = getScaledBandHeight();
        return y + h >= margin.top && y <= margin.top + innerHeight;
      });

      const yScaleAxis = d3.scaleBand()
        .domain(visibleSymbols)
        .range([
          scaledY(visibleSymbols[0] || symbols[0]),
          scaledY(visibleSymbols[visibleSymbols.length - 1] || symbols[symbols.length - 1]) + getScaledBandHeight()
        ]);

      const yAxis = d3.axisLeft(yScaleAxis);

      yAxisG
        .attr("transform", `translate(${margin.left}, 0)`)
        .call(yAxis);

      yAxisG.selectAll("text")
        .style("font-size", `${Math.max(10, Math.min(14, getScaledBandHeight() * 0.45))}px`);
    }

    function render() {
      ctx.clearRect(0, 0, width, height);

      const xScale = getScaledX();
      const scaledY = getScaledY();
      const bandHeight = getScaledBandHeight();

      renderAxes(xScale);

      ctx.save();

      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      ctx.fillStyle = "#020617";
      ctx.fillRect(margin.left, margin.top, innerWidth, innerHeight);

      const timeCount = timestamps.length;
      const cellWidth = timeCount > 1
        ? Math.max(1, (xScale(timestamps[1]) - xScale(timestamps[0])))
        : innerWidth;

      for (let row = 0; row < data.length; row++) {
        const rowData = data[row];
        const y = scaledY(rowData.symbol);

        if (y > margin.top + innerHeight || y + bandHeight < margin.top) continue;

        for (let col = 0; col < rowData.values.length; col++) {
          const point = rowData.values[col];
          const x = xScale(point.time);

          if (x + cellWidth < margin.left || x > margin.left + innerWidth) continue;

          ctx.fillStyle = colorScale(point.value);
          ctx.fillRect(
            x,
            y,
            Math.ceil(cellWidth) + 1,
            Math.max(1, Math.ceil(bandHeight))
          );
        }
      }

      drawGridLines(xScale, scaledY, bandHeight);

      ctx.restore();
    }

    function drawGridLines(xScale, scaledY, bandHeight) {
      ctx.save();
      ctx.strokeStyle = "rgba(148, 163, 184, 0.12)";
      ctx.lineWidth = 1;

      for (const symbol of symbols) {
        const y = scaledY(symbol);
        if (y >= margin.top && y <= margin.top + innerHeight) {
          ctx.beginPath();
          ctx.moveTo(margin.left, y);
          ctx.lineTo(margin.left + innerWidth, y);
          ctx.stroke();
        }
      }

      const ticks = xScale.ticks(Math.max(2, Math.floor(innerWidth / 100)));
      for (const tick of ticks) {
        const x = xScale(tick);
        if (x >= margin.left && x <= margin.left + innerWidth) {
          ctx.beginPath();
          ctx.moveTo(x, margin.top);
          ctx.lineTo(x, margin.top + innerHeight);
          ctx.stroke();
        }
      }

      ctx.restore();
    }

    function appendNewColumn() {
      const nextTime = new Date(timestamps[timestamps.length - 1].getTime() + updateIntervalMs);
      timestamps.push(nextTime);
      if (timestamps.length > maxTimeSteps) timestamps.shift();

      data.forEach((row, rowIndex) => {
        const prev = row.values[row.values.length - 1]?.value ?? 0;
        const drift = (Math.random() - 0.5) * 0.9 + Math.sin((Date.now() / 1000 + rowIndex) / 4) * 0.15;
        const next = clamp(prev + drift, -3, 3);

        row.values.push({
          time: nextTime,
          value: next
        });

        if (row.values.length > maxTimeSteps) row.values.shift();
      });

      baseXScale.domain(d3.extent(timestamps));
      render();
    }

    let streaming = true;
    let timer = setInterval(() => {
      if (streaming) appendNewColumn();
    }, updateIntervalMs);

    toggleBtn.addEventListener("click", () => {
      streaming = !streaming;
      toggleBtn.textContent = streaming ? "Pause Stream" : "Resume Stream";
      statusEl.textContent = streaming ? "Streaming updates..." : "Stream paused";
    });

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    function getHoveredCell(mouseX, mouseY) {
      if (
        mouseX < margin.left || mouseX > margin.left + innerWidth ||
        mouseY < margin.top || mouseY > margin.top + innerHeight
      ) {
        return null;
      }

      const xScale = getScaledX();
      const scaledY = getScaledY();
      const bandHeight = getScaledBandHeight();

      let hoveredSymbol = null;
      for (const symbol of symbols) {
        const y = scaledY(symbol);
        if (mouseY >= y && mouseY <= y + bandHeight) {
          hoveredSymbol = symbol;
          break;
        }
      }
      if (!hoveredSymbol) return null;

      let nearestIndex = 0;
      let nearestDist = Infinity;
      for (let i = 0; i < timestamps.length; i++) {
        const x = xScale(timestamps[i]);
        const d = Math.abs(mouseX - x);
        if (d < nearestDist) {
          nearestDist = d;
          nearestIndex = i;
        }
      }

      const row = data.find(d => d.symbol === hoveredSymbol);
      if (!row) return null;

      return {
        symbol: hoveredSymbol,
        point: row.values[nearestIndex],
        x: xScale(row.values[nearestIndex].time),
        y: scaledY(hoveredSymbol)
      };
    }

    container.addEventListener("mousemove", (event) => {
      const rect = container.getBoundingClientRect();
      const mouseX = event.clientX - rect.left;
      const mouseY = event.clientY - rect.top;

      const cell = getHoveredCell(mouseX, mouseY);
      if (!cell) {
        tooltip.style.opacity = 0;
        return;
      }

      const pct = cell.point.value.toFixed(2);
      const timeStr = d3.timeFormat("%H:%M:%S")(cell.point.time);

      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Time: ${timeStr}</div>
        <div>Change: <span style="color:${colorScale(cell.point.value)}">${pct}%</span></div>
      `;
      tooltip.style.left = `${mouseX + 12}px`;
      tooltip.style.top = `${mouseY + 12}px`;
      tooltip.style.opacity = 1;
    });

    container.addEventListener("mouseleave", () => {
      tooltip.style.opacity = 0;
    });

    window.addEventListener("resize", resize);

    resize();
  </script>
</body>
</html>
```

