      heatmapData = symbols.flatMap(symbol => {
        let price = latestPrices.get(symbol);
        return timestamps.map(ts => {
          price = price * (1 + (Math.random() - 0.5) * 0.01);
          latestPrices.set(symbol, price);
          const base = basePrices.get(symbol);
          return {
            symbol,
            time: ts,
            price,
            changePct: ((price - base) / base) * 100
          };
        });
      });
