      .duration(300)
      .attr("x", d => xScale(d.time.getTime()))
      .attr("y", d => yScale(d.symbol))
      .attr("width", xScale.bandwidth())
      .attr("height", yScale.bandwidth())
      .attr("fill", d => colorScale(d.changePct));
    }

    function pushNextDataPoint() {
      const nextTime = new Date(timestamps[timestamps.length - 1].getTime() + updateIntervalMs);
      timestamps = timestamps.slice(1).concat(nextTime);

      const newData = [];

      symbols.forEach(symbol => {
        let currentPrice = latestPrices.get(symbol);
        currentPrice = currentPrice * (1 + (Math.random() - 0.5) * 0.02);
        latestPrices.set(symbol, currentPrice);

        const base = basePrices.get(symbol);

        newData.push({
          symbol,
          time: nextTime,
          price: currentPrice,
          changePct: ((currentPrice - base) / base) * 100
        });
      });

      const cutoff = timestamps[0].getTime();
      heatmapData = heatmapData
        .filter(d => d.time.getTime() >= cutoff)
        .concat(newData);

      const avgChange = d3.mean(newData, d => d.changePct) || 0;
      status.textContent = `Streaming simulated market data... Last update: ${d3.timeFormat("%H:%M:%S")(nextTime)} | Avg change: ${avgChange.toFixed(2)}%`;

      render();
