    button:hover {
      background: #31406f;
    }

    .chart-wrap {
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 12px;
      position: relative;
      overflow: hidden;
    }

    .chart-container {
      position: relative;
      width: 100%;
      height: 700px;
    }

    canvas, svg {
      position: absolute;
      inset: 0;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(10, 12, 20, 0.95);
      color: white;
      border: 1px solid #3a4268;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      line-height: 1.4;
      white-space: nowrap;
      transform: translate(10px, 10px);
      display: none;
      z-index: 10;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 12px;
      color: var(--muted);
      font-size: 12px;
    }

    .legend-bar {
      width: 220px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(
        to right,
        #8b0000 0%,
        #d73027 25%,
        #2a2a2a 50%,
        #1a9850 75%,
        #006400 100%
      );
      border: 1px solid #3a4268;
    }

    .status {
      color: var(--muted);
      font-size: 13px;
    }

    .axis text {
      fill: var(--muted);
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: #44507b;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Price Heatmap</h1>
      <div class="controls">
        <button id="resetZoomBtn">Reset Zoom</button>
        <button id="pauseBtn">Pause</button>
        <div class="status" id="statusText">Streaming...</div>
      </div>
    </div>

    <div class="chart-wrap">
      <div id="chart" class="chart-container">
        <canvas id="heatmapCanvas"></canvas>
        <svg id="overlaySvg"></svg>
        <div id="tooltip" class="tooltip"></div>
      </div>

      <div class="legend">
        <span>Negative</span>
        <div class="legend-bar"></div>
        <span>Positive</span>
      </div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA", "META", "TSLA", "AMD",
      "NFLX", "INTC", "CRM", "ORCL", "IBM", "UBER", "SHOP", "SNOW",
      "BABA", "ADBE", "PYPL", "QCOM", "AVGO", "MU", "PLTR", "SQ"
    ];

    const state = {
      margin: { top: 20, right: 20, bottom: 40, left: 80 },
      width: 0,
      height: 0,
      innerWidth: 0,
      innerHeight: 0,
      rows: symbols.length,
      cols: 120,
      data: [],
      timestamps: [],
      zoomTransform: d3.zoomIdentity,
      paused: false
    };

    const chartEl = document.getElementById("chart");
    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlaySvg");
    const tooltip = document.getElementById("tooltip");
    const statusText = document.getElementById("statusText");
    const pauseBtn = document.getElementById("pauseBtn");
    const resetZoomBtn = document.getElementById("resetZoomBtn");

    const xAxisG = svg.append("g").attr("class", "axis x-axis");
    const yAxisG = svg.append("g").attr("class", "axis y-axis");
    const hoverG = svg.append("g");
    const hoverRect = hoverG.append("rect")
      .attr("fill", "none")
      .attr("stroke", "#ffffff")
      .attr("stroke-width", 1)
      .style("display", "none");

    let xScale = d3.scaleLinear();
    let yScale = d3.scaleBand().paddingInner(0.04).paddingOuter(0.02);

    const colorScale = d3.scaleLinear()
      .domain([-3, -1, 0, 1, 3])
      .range(["#8b0000", "#d73027", "#2a2a2a", "#1a9850", "#006400"])
      .clamp(true);

    function generateInitialData() {
      const now = Date.now();
      state.timestamps = d3.range(state.cols).map(i => now - (state.cols - 1 - i) * 1000);

      const basePrices = new Map(symbols.map(s => [s, 100 + Math.random() * 300]));
      state.data = symbols.map(symbol => {
        let price = basePrices.get(symbol);
        return state.timestamps.map(ts => {
          price += (Math.random() - 0.5) * 2;
          const changePct = ((Math.random() - 0.5) * 4);
          return {
            symbol,
            timestamp: ts,
            price: +price.toFixed(2),
            changePct: +changePct.toFixed(2)
          };
        });
      });
    }

    function appendRealtimeColumn() {
      const ts = Date.now();
      state.timestamps.push(ts);
      if (state.timestamps.length > state.cols) state.timestamps.shift();

      state.data.forEach((row, rowIndex) => {
        const prev = row[row.length - 1];
        const drift = (Math.random() - 0.5) * 2.5;
        const nextPrice = Math.max(1, prev.price + drift);
        const changePct = Math.max(-3, Math.min(3, prev.changePct * 0.4 + (Math.random() - 0.5) * 2.2));

        row.push({
          symbol: symbols[rowIndex],
          timestamp: ts,
          price: +nextPrice.toFixed(2),
          changePct: +changePct.toFixed(2)
        });

        if (row.length > state.cols) row.shift();
      });
    }

    function resize() {
      state.width = chartEl.clientWidth;
      state.height = chartEl.clientHeight;
      state.innerWidth = state.width - state.margin.left - state.margin.right;
      state.innerHeight = state.height - state.margin.top - state.margin.bottom;

      canvas.width = state.width * devicePixelRatio;
      canvas.height = state.height * devicePixelRatio;
      canvas.style.width = state.width + "px";
      canvas.style.height = state.height + "px";
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);

      svg
        .attr("width", state.width)
        .attr("height", state.height);

      xAxisG.attr("transform", `translate(0, ${state.margin.top + state.innerHeight})`);
      yAxisG.attr("transform", `translate(${state.margin.left}, 0)`);

      xScale = d3.scaleLinear()
        .domain([0, state.timestamps.length])
        .range([state.margin.left, state.margin.left + state.innerWidth]);

      yScale = d3.scaleBand()
        .domain(symbols)
        .range([state.margin.top, state.margin.top + state.innerHeight])
        .paddingInner(0.04)
        .paddingOuter(0.02);

      render();
    }

    function getRescaledX() {
      return state.zoomTransform.rescaleX(xScale);
    }

    function renderAxes() {
      const zx = getRescaledX();

      const tickCount = Math.max(4, Math.floor(state.innerWidth / 120));
      const tickValues = d3.range(0, state.timestamps.length, Math.max(1, Math.floor(state.timestamps.length / tickCount)));

      const xAxis = d3.axisBottom(zx)
        .tickValues(tickValues)
        .tickFormat(i => {
          const idx = Math.max(0, Math.min(state.timestamps.length - 1, Math.round(i)));
          return d3.timeFormat("%H:%M:%S")(new Date(state.timestamps[idx]));
        });

      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);
    }

    function renderHeatmap() {
      ctx.clearRect(0, 0, state.width, state.height);

      const zx = getRescaledX();
      const colWidthBase = state.innerWidth / state.timestamps.length;

      for (let rowIndex = 0; rowIndex < state.data.length; rowIndex++) {
        const row = state.data[rowIndex];
        const y = yScale(symbols[rowIndex]);
        const h = yScale.bandwidth();

        for (let colIndex = 0; colIndex < row.length; colIndex++) {
          const cell = row[colIndex];
          const x0 = zx(colIndex);
          const x1 = zx(colIndex + 1);
          const w = Math.max(1, x1 - x0);

          if (x0 > state.width || x1 < state.margin.left) continue;

          ctx.fillStyle = colorScale(cell.changePct);
          ctx.fillRect(x0, y, w, h);
        }
      }

      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= symbols.length; i++) {
        const y = state.margin.top + i * (state.innerHeight / symbols.length);
        ctx.beginPath();
        ctx.moveTo(state.margin.left, y);
        ctx.lineTo(state.margin.left + state.innerWidth, y);
        ctx.stroke();
      }
    }

    function render() {
      renderHeatmap();
      renderAxes();
    }

    function getCellFromPointer(event) {
      const [mx, my] = d3.pointer(event, chartEl);

      if (
        mx < state.margin.left ||
        mx > state.margin.left + state.innerWidth ||
        my < state.margin.top ||
        my > state.margin.top + state.innerHeight
      ) {
        return null;
      }

      const zx = getRescaledX();
      const xIndex = Math.floor(zx.invert(mx));
      const ySymbol = yScale.domain().find(symbol => {
        const y = yScale(symbol);
        return my >= y && my <= y + yScale.bandwidth();
      });

      if (xIndex < 0 || xIndex >= state.timestamps.length || !ySymbol) return null;

      const rowIndex = symbols.indexOf(ySymbol);
      const cell = state.data[rowIndex][xIndex];
      if (!cell) return null;

      return { cell, rowIndex, colIndex: xIndex };
    }

    function showTooltip(event, hit) {
      const { cell, rowIndex, colIndex } = hit;
      const zx = getRescaledX();

      const x = zx(colIndex);
      const w = Math.max(1, zx(colIndex + 1) - zx(colIndex));
      const y = yScale(symbols[rowIndex]);
      const h = yScale.bandwidth();

      hoverRect
        .attr("x", x)
        .attr("y", y)
        .attr("width", w)
        .attr("height", h)
        .style("display", null);

      tooltip.style.display = "block";
      tooltip.style.left = event.offsetX + "px";
      tooltip.style.top = event.offsetY + "px";
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Time: ${d3.timeFormat("%H:%M:%S")(new Date(cell.timestamp))}</div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: <span style="color:${colorScale(cell.changePct)}">${cell.changePct.toFixed(2)}%</span></div>
      `;
    }

    function hideTooltip() {
      tooltip.style.display = "none";
      hoverRect.style("display", "none");
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([
        [state.margin.left, state.margin.top],
        [state.margin.left + 100000, state.margin.top + state.innerHeight]
      ])
      .extent([
        [state.margin.left, state.margin.top],
        [state.margin.left + state.innerWidth, state.margin.top + state.innerHeight]
      ])
      .on("zoom", (event) => {
        state.zoomTransform = event.transform;
        render();
      });

    svg.call(zoom);

    svg
      .on("mousemove", (event) => {
        const hit = getCellFromPointer(event);
        if (!hit) {
          hideTooltip();
          return;
        }
        showTooltip(event, hit);
      })
      .on("mouseleave", hideTooltip);

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    pauseBtn.addEventListener("click", () => {
      state.paused = !state.paused;
      pauseBtn.textContent = state.paused ? "Resume" : "Pause";
      statusText.textContent = state.paused ? "Paused" : "Streaming...";
    });

    generateInitialData();
    resize();
    window.addEventListener("resize", resize);

    setInterval(() => {
      if (state.paused) return;
      appendRealtimeColumn();
      render();
    }, 1000);
  </script>
</body>
</html>
```

---

## How it works

### Data model
The heatmap stores:

- `symbols`: rows
- `timestamps`: columns
- `data[row][col]`: cell object containing:
  - `symbol`
  - `timestamp`
  - `price`
  - `changePct`

### Rendering
- heatmap cells are drawn on a `canvas`
- axes and interaction overlays are drawn with `svg`
- this hybrid approach keeps rendering fast while preserving easy zoom/tooltip behavior

### Zoom/pan
`d3.zoom()` updates a transform:
- zoom rescales the x-axis
- panning shifts visible time columns
- y-axis remains fixed in this initial version

### Real-time updates
Every second:
- a new timestamp is appended
- each symbol gets a new simulated price/change cell
- oldest column is removed when the rolling window exceeds `cols`

