</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <button id="resetViewBtn">Reset View</button>
      <button id="toggleFeedBtn">Pause Feed</button>
      <div class="meta" id="statusText">Loading…</div>
      <div class="legend">
        <span>- loss</span>
        <div class="legend-bar"></div>
        <span>gain +</span>
      </div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('canvasWrap');
    const tooltip = document.getElementById('tooltip');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const toggleFeedBtn = document.getElementById('toggleFeedBtn');
    const statusText = document.getElementById('statusText');

    const DPR = Math.max(1, window.devicePixelRatio || 1);

    const stocks = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA',
      'NVDA', 'META', 'NFLX', 'AMD', 'INTC',
      'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA',
      'JPM', 'BAC', 'GS', 'V', 'MA'
    ];

    const state = {
      running: true,
      maxColumns: 300,
      timestamps: [],
      data: [], // rows: stocks, cols: time points, values = % change
      basePrices: {},
      latestPrices: {},
      view: {
        scaleX: 1,
        scaleY: 1,
        offsetX: 0,
        offsetY: 0
      },
      layout: {
        leftPad: 90,
        topPad: 30,
        rightPad: 20,
        bottomPad: 40
      },
      hover: null,
      drag: {
        active: false,
        startX: 0,
        startY: 0,
        originOffsetX: 0,
        originOffsetY: 0
      }
    };

    function initData() {
      state.timestamps = [];
      state.data = stocks.map(() => []);
      for (const symbol of stocks) {
        const base = 50 + Math.random() * 450;
        state.basePrices[symbol] = base;
        state.latestPrices[symbol] = base;
      }

      const now = Date.now();
      for (let i = 0; i < 60; i++) {
        const ts = now - (59 - i) * 1000;
        appendTick(ts, false);
      }
      autoFitView();
    }

    function appendTick(timestamp = Date.now(), trim = true) {
      state.timestamps.push(timestamp);

      for (let row = 0; row < stocks.length; row++) {
        const symbol = stocks[row];
        const prev = state.latestPrices[symbol];
        const drift = (Math.random() - 0.5) * 0.012;
        const next = Math.max(1, prev * (1 + drift));
        state.latestPrices[symbol] = next;

        const pctChange = ((next - state.basePrices[symbol]) / state.basePrices[symbol]) * 100;
        state.data[row].push(pctChange);
      }

      if (trim && state.timestamps.length > state.maxColumns) {
        state.timestamps.shift();
        for (const row of state.data) row.shift();
      }

      updateStatus();
      draw();
    }

    function updateStatus() {
      const cols = state.timestamps.length;
      statusText.textContent = `${stocks.length} stocks • ${cols} time slices • wheel=zoom • drag=pan`;
    }

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * DPR);
      canvas.height = Math.floor(rect.height * DPR);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function autoFitView() {
      state.view.scaleX = 1;
      state.view.scaleY = 1;
      state.view.offsetX = 0;
      state.view.offsetY = 0;
      draw();
    }

    function getPlotRect() {
      const w = canvas.width / DPR;
      const h = canvas.height / DPR;
      const { leftPad, topPad, rightPad, bottomPad } = state.layout;
      return {
        x: leftPad,
        y: topPad,
        w: Math.max(10, w - leftPad - rightPad),
        h: Math.max(10, h - topPad - bottomPad)
      };
    }

    function getCellMetrics() {
      const plot = getPlotRect();
      const cols = Math.max(1, state.timestamps.length);
      const rows = Math.max(1, stocks.length);

      const baseCellW = plot.w / cols;
      const baseCellH = plot.h / rows;

      return {
        plot,
        cols,
        rows,
        cellW: baseCellW * state.view.scaleX,
        cellH: baseCellH * state.view.scaleY
      };
    }

    function valueToColor(v) {
      const clamped = Math.max(-5, Math.min(5, v));
      const t = (clamped + 5) / 10;

      let r, g, b;
      if (t < 0.5) {
        const k = t / 0.5;
        r = 180 * (1 - k) + 80 * k;
        g = 30 * (1 - k) + 80 * k;
        b = 30 * (1 - k) + 80 * k;
      } else {
        const k = (t - 0.5) / 0.5;
        r = 80 * (1 - k) + 30 * k;
        g = 80 * (1 - k) + 180 * k;
        b = 80 * (1 - k) + 80 * k;
      }
      return `rgb(${r|0}, ${g|0}, ${b|0})`;
    }

    function clear() {
      const w = canvas.width / DPR;
      const h = canvas.height / DPR;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, w, h);
    }

    function drawAxes(plot, metrics) {
      ctx.save();
      ctx.strokeStyle = '#2a3866';
      ctx.lineWidth = 1;
      ctx.strokeRect(plot.x, plot.y, plot.w, plot.h);

      ctx.fillStyle = '#8ea0d0';
      ctx.font = '12px sans-serif';
      ctx.textBaseline = 'middle';

      for (let row = 0; row < stocks.length; row++) {
        const y = plot.y + state.view.offsetY + row * metrics.cellH + metrics.cellH / 2;
        if (y < plot.y - metrics.cellH || y > plot.y + plot.h + metrics.cellH) continue;
        ctx.fillText(stocks[row], 10, y);
      }

      ctx.textBaseline = 'top';
      const timeStep = Math.max(1, Math.ceil(50 / Math.max(1, metrics.cellW)));
      for (let col = 0; col < state.timestamps.length; col += timeStep) {
        const x = plot.x + state.view.offsetX + col * metrics.cellW;
        if (x < plot.x - metrics.cellW || x > plot.x + plot.w + metrics.cellW) continue;

        ctx.strokeStyle = '#1f2a4d';
        ctx.beginPath();
        ctx.moveTo(x, plot.y);
        ctx.lineTo(x, plot.y + plot.h);
        ctx.stroke();

        const d = new Date(state.timestamps[col]);
        const label = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
        ctx.save();
        ctx.translate(x + 2, plot.y + plot.h + 6);
        ctx.rotate(-Math.PI / 4);
        ctx.fillStyle = '#8ea0d0';
        ctx.fillText(label, 0, 0);
        ctx.restore();
      }

      for (let row = 0; row <= stocks.length; row++) {
        const y = plot.y + state.view.offsetY + row * metrics.cellH;
        if (y < plot.y || y > plot.y + plot.h) continue;
        ctx.strokeStyle = '#1f2a4d';
        ctx.beginPath();
        ctx.moveTo(plot.x, y);
        ctx.lineTo(plot.x + plot.w, y);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawHeatmap() {
      clear();
      const metrics = getCellMetrics();
      const { plot, cellW, cellH } = metrics;

      drawAxes(plot, metrics);

      ctx.save();
      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.w, plot.h);
      ctx.clip();

      for (let row = 0; row < stocks.length; row++) {
        const y = plot.y + state.view.offsetY + row * cellH;
        if (y + cellH < plot.y || y > plot.y + plot.h) continue;

        for (let col = 0; col < state.timestamps.length; col++) {
          const x = plot.x + state.view.offsetX + col * cellW;
          if (x + cellW < plot.x || x > plot.x + plot.w) continue;

          const value = state.data[row][col];
          ctx.fillStyle = valueToColor(value);
          ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));
        }
      }

      if (state.hover) {
        const { row, col } = state.hover;
        if (row >= 0 && row < stocks.length && col >= 0 && col < state.timestamps.length) {
          const x = plot.x + state.view.offsetX + col * cellW;
          const y = plot.y + state.view.offsetY + row * cellH;
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, Math.max(0, cellW - 2), Math.max(0, cellH - 2));
        }
      }

      ctx.restore();
    }

    function draw() {
      drawHeatmap();
    }

    function screenToCell(mx, my) {
      const metrics = getCellMetrics();
      const { plot, cellW, cellH } = metrics;

      if (mx < plot.x || mx > plot.x + plot.w || my < plot.y || my > plot.y + plot.h) {
        return null;
      }

      const localX = mx - plot.x - state.view.offsetX;
      const localY = my - plot.y - state.view.offsetY;

      const col = Math.floor(localX / cellW);
      const row = Math.floor(localY / cellH);

      if (row < 0 || row >= stocks.length || col < 0 || col >= state.timestamps.length) {
        return null;
      }

      return { row, col };
    }

    function updateTooltip(mx, my) {
      const hit = screenToCell(mx, my);
      state.hover = hit;

      if (!hit) {
        tooltip.style.display = 'none';
        draw();
        return;
      }

      const { row, col } = hit;
      const symbol = stocks[row];
      const value = state.data[row][col];
      const ts = new Date(state.timestamps[col]).toLocaleTimeString();
      const price = state.basePrices[symbol] * (1 + value / 100);

      tooltip.innerHTML = `
        <div><strong>${symbol}</strong></div>
        <div>Time: ${ts}</div>
        <div>Change: ${value.toFixed(2)}%</div>
        <div>Price: $${price.toFixed(2)}</div>
      `;
      tooltip.style.display = 'block';
      tooltip.style.left = mx + 'px';
      tooltip.style.top = my + 'px';

      draw();
    }

    function clampPan() {
      const metrics = getCellMetrics();
      const { plot, cellW, cellH } = metrics;
      const totalW = state.timestamps.length * cellW;
      const totalH = stocks.length * cellH;

      const minOffsetX = Math.min(0, plot.w - totalW);
      const maxOffsetX = 0;
      const minOffsetY = Math.min(0, plot.h - totalH);
      const maxOffsetY = 0;

      state.view.offsetX = Math.max(minOffsetX, Math.min(maxOffsetX, state.view.offsetX));
      state.view.offsetY = Math.max(minOffsetY, Math.min(maxOffsetY, state.view.offsetY));
    }

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (state.drag.active) {
        state.view.offsetX = state.drag.originOffsetX + (mx - state.drag.startX);
        state.view.offsetY = state.drag.originOffsetY + (my - state.drag.startY);
        clampPan();
        draw();
        return;
      }

      updateTooltip(mx, my);
    });

    canvas.addEventListener('mouseleave', () => {
      state.hover = null;
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('mousedown', (e) => {
      state.drag.active = true;
      canvas.classList.add('dragging');
      const rect = canvas.getBoundingClientRect();
      state.drag.startX = e.clientX - rect.left;
      state.drag.startY = e.clientY - rect.top;
      state.drag.originOffsetX = state.view.offsetX;
      state.drag.originOffsetY = state.view.offsetY;
    });

    window.addEventListener('mouseup', () => {
      state.drag.active = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const before = screenToWorld(mx, my);

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      if (e.shiftKey) {
        state.view.scaleY = Math.max(0.5, Math.min(8, state.view.scaleY * zoomFactor));
      } else {
        state.view.scaleX = Math.max(0.5, Math.min(12, state.view.scaleX * zoomFactor));
      }

      const afterMetrics = getCellMetrics();
      if (before) {
        const { plot, cellW, cellH } = afterMetrics;
        state.view.offsetX = mx - plot.x - before.colFloat * cellW;
        state.view.offsetY = my - plot.y - before.rowFloat * cellH;
      }

      clampPan();
      draw();
    }, { passive: false });

    function screenToWorld(mx, my) {
      const metrics = getCellMetrics();
      const { plot, cellW, cellH } = metrics;
      if (mx < plot.x || mx > plot.x + plot.w || my < plot.y || my > plot.y + plot.h) {
        return null;
      }
      return {
        colFloat: (mx - plot.x - state.view.offsetX) / cellW,
        rowFloat: (my - plot.y - state.view.offsetY) / cellH
      };
    }

    resetViewBtn.addEventListener('click', () => {
      autoFitView();
    });

    toggleFeedBtn.addEventListener('click', () => {
      state.running = !state.running;
      toggleFeedBtn.textContent = state.running ? 'Pause Feed' : 'Resume Feed';
    });

    let timer = null;
    function startFeed() {
      if (timer) clearInterval(timer);
      timer = setInterval(() => {
        if (state.running) appendTick(Date.now(), true);
      }, 1000);
    }

    window.addEventListener('resize', resizeCanvas);

    initData();
    resizeCanvas();
    startFeed();
    updateStatus();
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `stocks`: list of ticker symbols
- `timestamps`: x-axis columns
- `data[row][col]`: percent change from each stock’s base price

### Rendering
- Uses `<canvas>` for efficient redraws
- Each heatmap cell is drawn as a colored rectangle
- Color scale:
  - red = negative performance
  - gray = neutral
  - green = positive

### Real-time updates
- `appendTick()` simulates a new price every second
- New values are pushed onto the right
- Old columns are trimmed after `maxColumns`

### Zoom/pan
- Mouse wheel:
  - normal wheel = horizontal zoom
  - `Shift + wheel` = vertical zoom
- Drag = pan across the heatmap
- Zoom is anchored around cursor position

