  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>

      <div class="control">
        <label for="speed">Update Speed</label>
        <input id="speed" type="range" min="100" max="2000" step="100" value="500" />
        <span id="speedLabel">500ms</span>
      </div>

      <div class="control">
        <label for="volatility">Volatility</label>
        <input id="volatility" type="range" min="0.1" max="5" step="0.1" value="1.2" />
        <span id="volatilityLabel">1.2</span>
      </div>

      <button id="pauseBtn">Pause</button>
      <button id="resetViewBtn">Reset View</button>

      <div class="status" id="status">Running</div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('canvasWrap');
    const tooltip = document.getElementById('tooltip');

    const speedInput = document.getElementById('speed');
    const speedLabel = document.getElementById('speedLabel');
    const volatilityInput = document.getElementById('volatility');
    const volatilityLabel = document.getElementById('volatilityLabel');
    const pauseBtn = document.getElementById('pauseBtn');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const statusEl = document.getElementById('status');

    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'META', 'NVDA', 'TSLA', 'AMD',
      'NFLX', 'INTC', 'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA', 'PYPL',
      'ADBE', 'QCOM', 'AVGO', 'IBM'
    ];

    const ROWS = symbols.length;
    const COLS = 240; // historical time buckets

    // Heatmap stores percentage changes for each symbol over time
    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => 0)
    );

    let prices = symbols.map(() => 100 + Math.random() * 200);

    let running = true;
    let updateInterval = Number(speedInput.value);
    let volatility = Number(volatilityInput.value);

    // View state for zoom/pan
    const view = {
      offsetX: 0,
      scaleX: 1,
      minScaleX: 0.5,
      maxScaleX: 8
    };

    // Layout
    const layout = {
      leftPad: 80,
      topPad: 30,
      rightPad: 20,
      bottomPad: 30
    };

    // Mouse state
    const mouse = {
      x: 0,
      y: 0,
      down: false,
      lastX: 0
    };

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function generateNextTick() {
      for (let r = 0; r < ROWS; r++) {
        const drift = (Math.random() - 0.5) * 0.15;
        const shock = (Math.random() - 0.5) * volatility;
        const prev = prices[r];
        const next = Math.max(1, prev * (1 + (drift + shock) / 100));
        const pctChange = ((next - prev) / prev) * 100;
        prices[r] = next;

        data[r].shift();
        data[r].push(pctChange);
      }
    }

    function valueToColor(v) {
      // clamp around +/- 5%
      const min = -5;
      const max = 5;
      const x = clamp((v - min) / (max - min), 0, 1);

      // Diverging interpolation:
      // red -> neutral dark -> blue
      if (x < 0.5) {
        const t = x / 0.5;
        return lerpColor([139, 0, 0], [42, 53, 85], t);
      } else {
        const t = (x - 0.5) / 0.5;
        return lerpColor([42, 53, 85], [8, 48, 107], t);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r}, ${g}, ${b2})`;
    }

    function getPlotRect() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      return {
        x: layout.leftPad,
        y: layout.topPad,
        w: width - layout.leftPad - layout.rightPad,
        h: height - layout.topPad - layout.bottomPad
      };
    }

    function drawAxes(plot) {
      ctx.strokeStyle = '#2a3555';
      ctx.lineWidth = 1;

      ctx.beginPath();
      ctx.moveTo(plot.x, plot.y);
      ctx.lineTo(plot.x, plot.y + plot.h);
      ctx.lineTo(plot.x + plot.w, plot.y + plot.h);
      ctx.stroke();

      ctx.fillStyle = '#8ea0c9';
      ctx.font = '12px sans-serif';
      ctx.textBaseline = 'middle';

      const rowHeight = plot.h / ROWS;
      for (let r = 0; r < ROWS; r++) {
        const y = plot.y + r * rowHeight + rowHeight / 2;
        ctx.fillText(symbols[r], 10, y);
      }
    }

    function drawHeatmap(plot) {
      const rowHeight = plot.h / ROWS;
      const baseColWidth = plot.w / COLS;
      const colWidth = baseColWidth * view.scaleX;
      const totalWidth = COLS * colWidth;

      const maxOffset = Math.max(0, totalWidth - plot.w);
      view.offsetX = clamp(view.offsetX, 0, maxOffset);

      const startCol = Math.floor(view.offsetX / colWidth);
      const endCol = Math.min(
        COLS - 1,
        Math.ceil((view.offsetX + plot.w) / colWidth)
      );

      for (let r = 0; r < ROWS; r++) {
        const y = plot.y + r * rowHeight;

        for (let c = startCol; c <= endCol; c++) {
          const x = plot.x + c * colWidth - view.offsetX;
          const value = data[r][c];

          ctx.fillStyle = valueToColor(value);
          ctx.fillRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));

          // optional subtle grid
          ctx.strokeStyle = 'rgba(255,255,255,0.04)';
          ctx.strokeRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));
        }
      }

      // time labels
      ctx.fillStyle = '#8ea0c9';
      ctx.font = '11px sans-serif';
      ctx.textBaseline = 'top';

      const labelEvery = Math.max(1, Math.floor(20 / view.scaleX));
      for (let c = startCol; c <= endCol; c += labelEvery) {
        const x = plot.x + c * colWidth - view.offsetX;
        ctx.fillText(String(c), x + 2, plot.y + plot.h + 6);
      }
    }

    function drawCrosshair(plot) {
      const hit = getCellAt(mouse.x, mouse.y, plot);
      if (!hit) return;

      const { row, col, cellX, cellY, cellW, cellH } = hit;

      ctx.strokeStyle = 'rgba(255,255,255,0.8)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(cellX + 0.5, cellY + 0.5, cellW - 1, cellH - 1);

      const value = data[row][col];
      tooltip.style.display = 'block';
      tooltip.style.left = mouse.x + 'px';
      tooltip.style.top = mouse.y + 'px';
      tooltip.innerHTML = `
        <div><strong>${symbols[row]}</strong></div>
        <div>Time: ${col}</div>
        <div>Change: ${value.toFixed(3)}%</div>
        <div>Price: $${prices[row].toFixed(2)}</div>
      `;
    }

    function getCellAt(mx, my, plot = getPlotRect()) {
      if (
        mx < plot.x || mx > plot.x + plot.w ||
        my < plot.y || my > plot.y + plot.h
      ) {
        tooltip.style.display = 'none';
        return null;
      }

      const rowHeight = plot.h / ROWS;
      const baseColWidth = plot.w / COLS;
      const colWidth = baseColWidth * view.scaleX;

      const row = Math.floor((my - plot.y) / rowHeight);
      const virtualX = mx - plot.x + view.offsetX;
      const col = Math.floor(virtualX / colWidth);

      if (row < 0 || row >= ROWS || col < 0 || col >= COLS) {
        tooltip.style.display = 'none';
        return null;
      }

      const cellX = plot.x + col * colWidth - view.offsetX;
      const cellY = plot.y + row * rowHeight;

      return {
        row,
        col,
        cellX,
        cellY,
        cellW: colWidth,
        cellH: rowHeight
      };
    }

    function clear() {
      ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, canvas.clientWidth, canvas.clientHeight);
    }

    function draw() {
      clear();
      const plot = getPlotRect();
      drawAxes(plot);
      drawHeatmap(plot);
      drawCrosshair(plot);
    }

    let timer = null;

    function startLoop() {
      stopLoop();
      timer = setInterval(() => {
        if (!running) return;
        generateNextTick();
        draw();
      }, updateInterval);
    }

    function stopLoop() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    speedInput.addEventListener('input', () => {
      updateInterval = Number(speedInput.value);
      speedLabel.textContent = `${updateInterval}ms`;
      startLoop();
    });

    volatilityInput.addEventListener('input', () => {
      volatility = Number(volatilityInput.value);
      volatilityLabel.textContent = volatility.toFixed(1);
    });

    pauseBtn.addEventListener('click', () => {
      running = !running;
      pauseBtn.textContent = running ? 'Pause' : 'Resume';
      statusEl.textContent = running ? 'Running' : 'Paused';
    });

    resetViewBtn.addEventListener('click', () => {
      view.offsetX = 0;
      view.scaleX = 1;
      draw();
    });

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;

      if (mouse.down) {
        const plot = getPlotRect();
        const baseColWidth = plot.w / COLS;
        const colWidth = baseColWidth * view.scaleX;
        const totalWidth = COLS * colWidth;
        const maxOffset = Math.max(0, totalWidth - plot.w);

        const dx = e.clientX - mouse.lastX;
        view.offsetX = clamp(view.offsetX - dx, 0, maxOffset);
        mouse.lastX = e.clientX;
      }

      draw();
    });

    canvas.addEventListener('mousedown', (e) => {
      mouse.down = true;
      mouse.lastX = e.clientX;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      mouse.down = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const plot = getPlotRect();
      const mx = e.offsetX;

      const oldScale = view.scaleX;
      const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
      const newScale = clamp(
        view.scaleX * zoomFactor,
        view.minScaleX,
        view.maxScaleX
      );

      if (newScale === oldScale) return;

      const baseColWidth = plot.w / COLS;
      const oldColWidth = baseColWidth * oldScale;
      const newColWidth = baseColWidth * newScale;

      const worldX = view.offsetX + (mx - plot.x);
      const colAtMouse = worldX / oldColWidth;

      view.scaleX = newScale;
      view.offsetX = colAtMouse * newColWidth - (mx - plot.x);

      const totalWidth = COLS * newColWidth;
      const maxOffset = Math.max(0, totalWidth - plot.w);
      view.offsetX = clamp(view.offsetX, 0, maxOffset);

      draw();
    }, { passive: false });

    window.addEventListener('resize', resizeCanvas);

    // Seed initial data
    for (let i = 0; i < 100; i++) {
      generateNextTick();
    }

    resizeCanvas();
    startLoop();
  </script>
</body>
</html>
```

---

## How it works

### Data model
- `data[row][col]` stores the recent percentage change for a stock symbol.
- Each update:
  - a new simulated price is generated
  - percentage change is computed
  - oldest column is removed with `shift()`
  - newest value is appended with `push()`

### Rendering
- The heatmap is drawn onto a `<canvas>`.
- Each cell gets a color based on its value:
  - negative = red-ish
  - neutral = dark
  - positive = blue-ish

### Zoom/pan
- `view.scaleX` controls horizontal zoom
- `view.offsetX` controls horizontal pan
- Mouse wheel zooms around the cursor position
- Mouse drag pans left/right

### Tooltip
- On hover, the app calculates which cell is under the cursor and shows its metadata.

---

## Notes / limitations of this initial version

This is a good prototype, but for production you’d likely want:

1. **Real market data**
   - Replace simulated updates with WebSocket or SSE feeds
   - Example sources: Polygon, IEX Cloud, Alpha Vantage, Finnhub, Twelve Data

2. **Better time axis**
   - Use actual timestamps instead of numeric column indices

3. **Improved color scale**
   - Use a perceptually balanced diverging scale
   - Maybe green/red if that matches your UX expectations

4. **Performance improvements**
   - Avoid redrawing everything on every mouse move
   - Use offscreen canvas
   - Use `requestAnimationFrame`
   - Use typed arrays or ring buffers instead of `shift()`

5. **Vertical scrolling / row virtualization**
   - Important if you have hundreds or thousands of symbols

6. **Touch support**
   - Pinch zoom
   - Drag pan on mobile/tablet

7. **Selection/filtering**
   - Search symbols
   - Sector grouping
   - Sort by volatility, gainers, losers

