</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Price Heatmap</h1>

      <div class="group">
        <label for="symbolsCount">Symbols</label>
        <input id="symbolsCount" type="range" min="10" max="100" value="30" />
        <span id="symbolsCountValue" class="stat">30</span>
      </div>

      <div class="group">
        <label for="updateRate">Update ms</label>
        <input id="updateRate" type="range" min="100" max="2000" step="50" value="400" />
        <span id="updateRateValue" class="stat">400</span>
      </div>

      <div class="group">
        <button id="resetViewBtn">Reset View</button>
        <button id="pauseBtn">Pause</button>
      </div>

      <div class="group stat" id="status">Running</div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-bar"></div>
        <div class="legend-scale">
          <span>-strong</span>
          <span>flat</span>
          <span>+strong</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;

        this.dpr = window.devicePixelRatio || 1;

        this.symbols = [];
        this.timeBuckets = [];
        this.data = []; // data[row][col] => { price, changePct, ts }

        this.maxColumns = 240;
        this.bucketMs = 1000;
        this.running = true;
        this.timer = null;
        this.updateRate = 400;

        this.basePrices = new Map();
        this.lastPrices = new Map();

        this.margin = {
          top: 30,
          right: 20,
          bottom: 40,
          left: 90
        };

        this.view = {
          offsetX: 0,
          offsetY: 0,
          scaleX: 1,
          scaleY: 1
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          lastY: 0,
          hoverCell: null
        };

        this.initSymbols(30);
        this.initTimeAxis();
        this.initData();

        this.bindEvents();
        this.resize();
        this.start();
        this.render();
      }

      initSymbols(count) {
        const generated = [];
        for (let i = 0; i < count; i++) {
          generated.push(`STK${String(i + 1).padStart(3, '0')}`);
        }
        this.symbols = generated;

        this.basePrices.clear();
        this.lastPrices.clear();

        for (const symbol of this.symbols) {
          const base = 50 + Math.random() * 250;
          this.basePrices.set(symbol, base);
          this.lastPrices.set(symbol, base);
        }
      }

      initTimeAxis() {
        const now = Date.now();
        this.timeBuckets = [];
        for (let i = this.maxColumns - 1; i >= 0; i--) {
          this.timeBuckets.push(now - i * this.bucketMs);
        }
      }

      initData() {
        this.data = this.symbols.map(symbol => {
          const base = this.basePrices.get(symbol);
          return this.timeBuckets.map(ts => ({
            price: base,
            changePct: 0,
            ts
          }));
        });
      }

      setSymbolCount(count) {
        this.initSymbols(count);
        this.initTimeAxis();
        this.initData();
        this.resetView();
        this.render();
      }

      setUpdateRate(ms) {
        this.updateRate = ms;
        if (this.running) {
          this.stop();
          this.start();
        }
      }

      start() {
        this.running = true;
        this.statusEl.textContent = 'Running';
        this.timer = setInterval(() => {
          this.pushTick();
          this.render();
        }, this.updateRate);
      }

      stop() {
        this.running = false;
        this.statusEl.textContent = 'Paused';
        clearInterval(this.timer);
      }

      toggle() {
        if (this.running) this.stop();
        else this.start();
      }

      resetView() {
        this.view.offsetX = 0;
        this.view.offsetY = 0;
        this.view.scaleX = 1;
        this.view.scaleY = 1;
      }

      pushTick() {
        const ts = Date.now();

        this.timeBuckets.push(ts);
        if (this.timeBuckets.length > this.maxColumns) {
          this.timeBuckets.shift();
        }

        for (let row = 0; row < this.symbols.length; row++) {
          const symbol = this.symbols[row];
          const prev = this.lastPrices.get(symbol);
          const drift = (Math.random() - 0.5) * 0.012;
          const next = Math.max(1, prev * (1 + drift));
          const changePct = ((next - prev) / prev) * 100;

          this.lastPrices.set(symbol, next);

          this.data[row].push({
            price: next,
            changePct,
            ts
          });

          if (this.data[row].length > this.maxColumns) {
            this.data[row].shift();
          }
        }
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('mousedown', e => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
          this.interaction.lastY = e.clientY;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', e => {
          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            const dy = e.clientY - this.interaction.lastY;
            this.interaction.lastX = e.clientX;
            this.interaction.lastY = e.clientY;

            this.view.offsetX += dx;
            this.view.offsetY += dy;
            this.render();
          } else {
            this.handleHover(e);
          }
        });

        this.canvas.addEventListener('wheel', e => {
          e.preventDefault();

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
          const rect = this.canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;

          const oldScaleX = this.view.scaleX;
          const oldScaleY = this.view.scaleY;

          if (e.shiftKey) {
            this.view.scaleY = Math.max(0.5, Math.min(8, this.view.scaleY * zoomFactor));
          } else {
            this.view.scaleX = Math.max(0.5, Math.min(8, this.view.scaleX * zoomFactor));
          }

          this.view.offsetX = mx - ((mx - this.view.offsetX) * (this.view.scaleX / oldScaleX));
          this.view.offsetY = my - ((my - this.view.offsetY) * (this.view.scaleY / oldScaleY));

          this.render();
        }, { passive: false });

        this.canvas.addEventListener('mouseleave', () => {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
        });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.canvas.width = Math.floor(rect.width * this.dpr);
        this.canvas.height = Math.floor(rect.height * this.dpr);
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      getPlotArea() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        return {
          x: this.margin.left,
          y: this.margin.top,
          width: width - this.margin.left - this.margin.right,
          height: height - this.margin.top - this.margin.bottom
        };
      }

      handleHover(e) {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        const cell = this.pickCell(x, y);
        if (!cell) {
          this.tooltip.style.display = 'none';
          this.interaction.hoverCell = null;
          return;
        }

        this.interaction.hoverCell = cell;
        const point = this.data[cell.row][cell.col];
        const symbol = this.symbols[cell.row];

        this.tooltip.innerHTML = `
          <div><strong>${symbol}</strong></div>
          <div>Time: ${new Date(point.ts).toLocaleTimeString()}</div>
          <div>Price: $${point.price.toFixed(2)}</div>
          <div>Δ: ${point.changePct >= 0 ? '+' : ''}${point.changePct.toFixed(2)}%</div>
        `;
        this.tooltip.style.left = `${x}px`;
        this.tooltip.style.top = `${y}px`;
        this.tooltip.style.display = 'block';
      }

      pickCell(px, py) {
        const plot = this.getPlotArea();

        const cols = this.timeBuckets.length;
        const rows = this.symbols.length;
        const cellW = (plot.width / cols) * this.view.scaleX;
        const cellH = (plot.height / rows) * this.view.scaleY;

        const startX = plot.x + this.view.offsetX;
        const startY = plot.y + this.view.offsetY;

        if (px < plot.x || py < plot.y || px > plot.x + plot.width || py > plot.y + plot.height) {
          return null;
        }

        const col = Math.floor((px - startX) / cellW);
        const row = Math.floor((py - startY) / cellH);

        if (col < 0 || col >= cols || row < 0 || row >= rows) return null;
        return { row, col };
      }

      colorForValue(v) {
        const clamped = Math.max(-2, Math.min(2, v));
        const t = (clamped + 2) / 4;

        let r, g, b;
        if (t < 0.5) {
          const k = t / 0.5;
          r = Math.round(180 + (80 - 180) * k);
          g = Math.round(30 + (80 - 30) * k);
          b = Math.round(50 + (80 - 50) * k);
        } else {
          const k = (t - 0.5) / 0.5;
          r = Math.round(80 + (20 - 80) * k);
          g = Math.round(80 + (160 - 80) * k);
          b = Math.round(80 + (90 - 80) * k);
        }
        return `rgb(${r},${g},${b})`;
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        const plot = this.getPlotArea();

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, width, height);

        this.drawAxes(plot);
        this.drawHeatmap(plot);
        this.drawHover(plot);
      }

      drawAxes(plot) {
        const ctx = this.ctx;
        const rows = this.symbols.length;
        const cols = this.timeBuckets.length;
        const cellW = (plot.width / cols) * this.view.scaleX;
        const cellH = (plot.height / rows) * this.view.scaleY;
        const startX = plot.x + this.view.offsetX;
        const startY = plot.y + this.view.offsetY;

        ctx.save();

        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = 1;

        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.stroke();

        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        ctx.font = '11px sans-serif';
        ctx.fillStyle = '#8ea0d0';

        for (let r = 0; r < rows; r++) {
          const y = startY + r * cellH;
          if (y + cellH < plot.y || y > plot.y + plot.height) continue;

          ctx.strokeStyle = 'rgba(255,255,255,0.05)';
          ctx.beginPath();
          ctx.moveTo(plot.x, y);
          ctx.lineTo(plot.x + plot.width, y);
          ctx.stroke();

          ctx.restore();
          ctx.save();
          ctx.fillStyle = '#8ea0d0';
          ctx.textAlign = 'right';
          ctx.textBaseline = 'middle';
          ctx.fillText(this.symbols[r], plot.x - 8, y + cellH / 2);
          ctx.beginPath();
          ctx.rect(plot.x, plot.y, plot.width, plot.height);
          ctx.clip();
        }

        const labelEvery = Math.max(1, Math.floor(cols / 8));
        for (let c = 0; c < cols; c += labelEvery) {
          const x = startX + c * cellW;
          if (x + cellW < plot.x || x > plot.x + plot.width) continue;

          ctx.strokeStyle = 'rgba(255,255,255,0.05)';
          ctx.beginPath();
          ctx.moveTo(x, plot.y);
          ctx.lineTo(x, plot.y + plot.height);
          ctx.stroke();

          ctx.restore();
          ctx.save();
          ctx.fillStyle = '#8ea0d0';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'top';
          ctx.fillText(
            new Date(this.timeBuckets[c]).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            x + cellW / 2,
            plot.y + plot.height + 8
          );
          ctx.beginPath();
          ctx.rect(plot.x, plot.y, plot.width, plot.height);
          ctx.clip();
        }

        ctx.restore();
      }

      drawHeatmap(plot) {
        const ctx = this.ctx;
        const rows = this.symbols.length;
        const cols = this.timeBuckets.length;
        const cellW = (plot.width / cols) * this.view.scaleX;
        const cellH = (plot.height / rows) * this.view.scaleY;
        const startX = plot.x + this.view.offsetX;
        const startY = plot.y + this.view.offsetY;

        ctx.save();
        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        for (let r = 0; r < rows; r++) {
          const y = startY + r * cellH;
          if (y > plot.y + plot.height || y + cellH < plot.y) continue;

          for (let c = 0; c < cols; c++) {
            const x = startX + c * cellW;
            if (x > plot.x + plot.width || x + cellW < plot.x) continue;

            const point = this.data[r][c];
            ctx.fillStyle = this.colorForValue(point.changePct);
            ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));

            if (cellW > 8 && cellH > 8) {
              ctx.strokeStyle = 'rgba(255,255,255,0.04)';
              ctx.strokeRect(x, y, cellW, cellH);
            }
          }
        }

        ctx.restore();
      }

      drawHover(plot) {
        const hover = this.interaction.hoverCell;
        if (!hover) return;

        const rows = this.symbols.length;
        const cols = this.timeBuckets.length;
        const cellW = (plot.width / cols) * this.view.scaleX;
        const cellH = (plot.height / rows) * this.view.scaleY;
        const startX = plot.x + this.view.offsetX;
        const startY = plot.y + this.view.offsetY;

        const x = startX + hover.col * cellW;
        const y = startY + hover.row * cellH;

        const ctx = this.ctx;
        ctx.save();
        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);

        ctx.restore();
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    const heatmap = new StockHeatmap(canvas, tooltip, statusEl);

    const symbolsCount = document.getElementById('symbolsCount');
    const symbolsCountValue = document.getElementById('symbolsCountValue');
    const updateRate = document.getElementById('updateRate');
    const updateRateValue = document.getElementById('updateRateValue');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    symbolsCount.addEventListener('input', () => {
      const value = Number(symbolsCount.value);
      symbolsCountValue.textContent = value;
      heatmap.setSymbolCount(value);
    });

    updateRate.addEventListener('input', () => {
      const value = Number(updateRate.value);
      updateRateValue.textContent = value;
      heatmap.setUpdateRate(value);
    });

    resetViewBtn.addEventListener('click', () => {
      heatmap.resetView();
      heatmap.render();
    });

    pauseBtn.addEventListener('click', () => {
      heatmap.toggle();
      pauseBtn.textContent = heatmap.running ? 'Pause' : 'Resume';
    });
  </script>
</body>
</html>
```

