        #1e293b 50%,
        #16a34a 75%,
        #14532d 100%
      );
      border: 1px solid #334155;
    }

    .meta {
      color: #94a3b8;
      font-size: 13px;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetZoom">Reset Zoom</button>
      <div class="legend">
        <span class="meta">Price Change</span>
        <div class="legend-bar"></div>
        <span class="meta">-5% to +5%</span>
      </div>
    </div>

    <div id="chart" class="chart-wrap">
      <canvas id="heatmap"></canvas>
      <svg id="overlay" class="overlay"></svg>
      <div id="tooltip" class="tooltip"></div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "BABA",
      "JPM", "BAC", "GS", "V", "MA"
    ];

    const timeSteps = 120; // columns
    const data = [];
    const now = Date.now();
    const stepMs = 60 * 1000; // 1 minute buckets

    for (let row = 0; row < symbols.length; row++) {
      for (let col = 0; col < timeSteps; col++) {
        data.push({
          symbol: symbols[row],
          row,
          col,
          time: new Date(now - (timeSteps - 1 - col) * stepMs),
          change: (Math.random() - 0.5) * 6
        });
      }
    }

    const chartEl = document.getElementById("chart");
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const svg = d3.select("#overlay");
    const tooltip = document.getElementById("tooltip");
    const resetZoomBtn = document.getElementById("resetZoom");

    const margin = { top: 20, right: 20, bottom: 40, left: 80 };

    let width = 0;
    let height = 0;
    let innerWidth = 0;
    let innerHeight = 0;

    let xScale, yScale, xAxisG, yAxisG;
    let baseXScale, baseYScale;
    let currentTransform = d3.zoomIdentity;

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#dc2626", "#1e293b", "#16a34a"])
      .clamp(true);

    function resize() {
      const rect = chartEl.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      svg.attr("width", width).attr("height", height);

      const times = data.map(d => d.time);
      const minTime = d3.min(times);
      const maxTime = d3.max(times);

      baseXScale = d3.scaleTime()
        .domain([minTime, maxTime])
        .range([margin.left, width - margin.right]);

      baseYScale = d3.scaleBand()
        .domain(symbols)
        .range([margin.top, height - margin.bottom])
        .paddingInner(0.05)
        .paddingOuter(0.02);

      xScale = currentTransform.rescaleX(baseXScale);
      yScale = baseYScale.copy();

      svg.selectAll("*").remove();

      xAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(0, ${height - margin.bottom})`);

      yAxisG = svg.append("g")
        .attr("class", "axis")
        .attr("transform", `translate(${margin.left}, 0)`);

      svg.append("clipPath")
        .attr("id", "plot-clip")
        .append("rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      const interactionRect = svg.append("rect")
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight)
        .attr("fill", "transparent")
        .style("cursor", "grab");

      const zoom = d3.zoom()
        .scaleExtent([1, 20])
        .translateExtent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
        .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
        .on("zoom", (event) => {
          currentTransform = event.transform;
          xScale = currentTransform.rescaleX(baseXScale);
          draw();
        });

      interactionRect.call(zoom)
        .on("mousemove", handleMouseMove)
        .on("mouseleave", handleMouseLeave);

      resetZoomBtn.onclick = () => {
        interactionRect.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
      };

      draw();
    }

    function drawAxes() {
      const xAxis = d3.axisBottom(xScale).ticks(Math.max(4, width / 120));
      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      drawAxes();

      ctx.save();
      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      const bandHeight = yScale.bandwidth();

      for (const d of data) {
        const x0 = xScale(d.time);
        const x1 = xScale(new Date(d.time.getTime() + stepMs));
        const y = yScale(d.symbol);

        if (y == null) continue;

        const cellWidth = Math.max(1, x1 - x0);
        if (x1 < margin.left || x0 > width - margin.right) continue;

        ctx.fillStyle = colorScale(d.change);
        ctx.fillRect(x0, y, cellWidth, bandHeight);
      }

      ctx.restore();
    }

    function findDatum(mx, my) {
      if (
        mx < margin.left || mx > width - margin.right ||
        my < margin.top || my > height - margin.bottom
      ) {
        return null;
      }

      const symbol = symbols.find(sym => {
        const y = yScale(sym);
        return my >= y && my <= y + yScale.bandwidth();
      });

      if (!symbol) return null;

      const time = xScale.invert(mx);
      const col = Math.floor((time - data[0].time) / stepMs);

      if (col < 0 || col >= timeSteps) return null;

      const row = symbols.indexOf(symbol);
      return data[row * timeSteps + col] || null;
    }

    function handleMouseMove(event) {
      const [mx, my] = d3.pointer(event);
      const d = findDatum(mx, my);

      if (!d) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = (mx + 14) + "px";
      tooltip.style.top = (my + 14) + "px";
      tooltip.innerHTML = `
        <div><strong>${d.symbol}</strong></div>
        <div>${d.time.toLocaleTimeString()}</div>
        <div>Change: <strong style="color:${colorScale(d.change)}">${d.change.toFixed(2)}%</strong></div>
      `;
    }

    function handleMouseLeave() {
      tooltip.style.display = "none";
    }

    function tickUpdate() {
      const latestTime = d3.max(data, d => d.time);
      const nextTime = new Date(latestTime.getTime() + stepMs);

      for (let row = 0; row < symbols.length; row++) {
        data.shift();
      }

      for (let row = 0; row < symbols.length; row++) {
        data.push({
          symbol: symbols[row],
          row,
          col: timeSteps - 1,
          time: nextTime,
          change: Math.max(-5, Math.min(5, ((Math.random() - 0.5) * 2) + (Math.random() - 0.5) * 4))
        });
      }

      // Rebuild row/col consistency
      for (let row = 0; row < symbols.length; row++) {
        for (let col = 0; col < timeSteps; col++) {
          const idx = row * timeSteps + col;
          if (data[idx]) {
            data[idx].row = row;
            data[idx].col = col;
          }
        }
      }

      const times = data.map(d => d.time);
      baseXScale.domain([d3.min(times), d3.max(times)]);
      xScale = currentTransform.rescaleX(baseXScale);

      draw();
    }

    window.addEventListener("resize", resize);
    resize();
    setInterval(tickUpdate, 1000);
  </script>
</body>
</html>
```

