<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetViewBtn">Reset View</button>
      <button id="pauseBtn">Pause</button>
      <span id="status">Streaming: ON</span>
    </div>
    <div class="container" id="container">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div>Price Change Heat</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const container = document.getElementById('container');
    const tooltip = document.getElementById('tooltip');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const pauseBtn = document.getElementById('pauseBtn');
    const statusEl = document.getElementById('status');

    const STOCKS = [
      'AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA',
      'META', 'NVDA', 'NFLX', 'AMD', 'INTC',
      'ORCL', 'IBM', 'CRM', 'UBER', 'SHOP'
    ];

    const MAX_POINTS = 300;
    const UPDATE_INTERVAL = 400;
    const PRICE_CHANGE_LIMIT = 5; // +/- 5%

    let isStreaming = true;
    let timeIndex = 0;

    // Heatmap data: rows = stocks, cols = time
    const data = STOCKS.map(() => []);

    // Track current absolute prices for tooltip realism
    const currentPrices = STOCKS.map(() => 100 + Math.random() * 200);

    // View state
    const view = {
      offsetX: 0,
      scaleX: 1,
      minScaleX: 0.5,
      maxScaleX: 8
    };

    // Layout
    const layout = {
      leftPad: 70,
      rightPad: 20,
      topPad: 20,
      bottomPad: 30
    };

    let dragging = false;
    let lastMouseX = 0;
    let hoverCell = null;

    function resizeCanvas() {
      const rect = container.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function generateNextDataPoint() {
      for (let i = 0; i < STOCKS.length; i++) {
        // Simulate a price move
        const change = (Math.random() - 0.5) * 1.2; // small random drift in %
        currentPrices[i] *= (1 + change / 100);

        const boundedChange = clamp(change, -PRICE_CHANGE_LIMIT, PRICE_CHANGE_LIMIT);
        data[i].push({
          t: timeIndex,
          change: boundedChange,
          price: currentPrices[i]
        });

        if (data[i].length > MAX_POINTS) {
          data[i].shift();
        }
      }
      timeIndex++;
    }

    function getColor(change) {
      const normalized = clamp(change / PRICE_CHANGE_LIMIT, -1, 1);

      if (normalized < 0) {
        const t = normalized + 1; // [-1,0] => [0,1]
        return lerpColor([127, 29, 29], [31, 41, 55], t);
      } else {
        const t = normalized; // [0,1]
        return lerpColor([31, 41, 55], [22, 163, 74], t);
      }
    }

    function lerpColor(c1, c2, t) {
      const r = Math.round(c1[0] + (c2[0] - c1[0]) * t);
      const g = Math.round(c1[1] + (c2[1] - c1[1]) * t);
      const b = Math.round(c1[2] + (c2[2] - c1[2]) * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function drawAxes(width, height, plotWidth, plotHeight, rowHeight, colWidth, visibleCols) {
      ctx.strokeStyle = '#475569';
      ctx.fillStyle = '#cbd5e1';
      ctx.lineWidth = 1;

      // Border
      ctx.strokeRect(layout.leftPad, layout.topPad, plotWidth, plotHeight);

      // Y labels
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      ctx.font = '12px Arial';

      for (let i = 0; i < STOCKS.length; i++) {
        const y = layout.topPad + i * rowHeight + rowHeight / 2;
        ctx.fillText(STOCKS[i], layout.leftPad - 8, y);
      }

      // X labels
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';

      const step = Math.max(1, Math.floor(visibleCols / 8));
      for (let c = 0; c < visibleCols; c += step) {
        const x = layout.leftPad + c * colWidth + colWidth / 2;
        const t = Math.floor(view.offsetX + c / view.scaleX);
        ctx.fillText(`T${t}`, x, layout.topPad + plotHeight + 6);
      }
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      const plotWidth = width - layout.leftPad - layout.rightPad;
      const plotHeight = height - layout.topPad - layout.bottomPad;
      const rows = STOCKS.length;
      const rowHeight = plotHeight / rows;

      const visibleDataCols = Math.max(10, Math.floor(MAX_POINTS / view.scaleX));
      const colWidth = plotWidth / visibleDataCols;

      const maxOffset = Math.max(0, MAX_POINTS - visibleDataCols);
      view.offsetX = clamp(view.offsetX, 0, maxOffset);

      // Draw cells
      for (let r = 0; r < rows; r++) {
        const row = data[r];
        for (let c = 0; c < visibleDataCols; c++) {
          const dataIndex = Math.floor(view.offsetX + c);
          const point = row[dataIndex];
          if (!point) continue;

          const x = layout.leftPad + c * colWidth;
          const y = layout.topPad + r * rowHeight;

          ctx.fillStyle = getColor(point.change);
          ctx.fillRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));

          // subtle grid
          ctx.strokeStyle = 'rgba(15, 23, 42, 0.35)';
          ctx.strokeRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));
        }
      }

      drawAxes(width, height, plotWidth, plotHeight, rowHeight, colWidth, visibleDataCols);

      // Highlight hovered cell
      if (hoverCell) {
        ctx.strokeStyle = '#f8fafc';
        ctx.lineWidth = 2;
        ctx.strokeRect(hoverCell.x, hoverCell.y, hoverCell.w, hoverCell.h);
      }
    }

    function getMousePos(evt) {
      const rect = canvas.getBoundingClientRect();
      return {
        x: evt.clientX - rect.left,
        y: evt.clientY - rect.top
      };
    }

    function updateHover(evt) {
      const { x, y } = getMousePos(evt);

      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      const plotWidth = width - layout.leftPad - layout.rightPad;
      const plotHeight = height - layout.topPad - layout.bottomPad;
      const rowHeight = plotHeight / STOCKS.length;
      const visibleDataCols = Math.max(10, Math.floor(MAX_POINTS / view.scaleX));
      const colWidth = plotWidth / visibleDataCols;

      const insidePlot =
        x >= layout.leftPad &&
        x <= layout.leftPad + plotWidth &&
        y >= layout.topPad &&
        y <= layout.topPad + plotHeight;

      if (!insidePlot) {
        hoverCell = null;
        tooltip.style.display = 'none';
        draw();
        return;
      }

      const col = Math.floor((x - layout.leftPad) / colWidth);
      const row = Math.floor((y - layout.topPad) / rowHeight);
      const dataIndex = Math.floor(view.offsetX + col);

      const point = data[row]?.[dataIndex];
      if (!point) {
        hoverCell = null;
        tooltip.style.display = 'none';
        draw();
        return;
      }

      hoverCell = {
        x: layout.leftPad + col * colWidth,
        y: layout.topPad + row * rowHeight,
        w: Math.ceil(colWidth),
        h: Math.ceil(rowHeight)
      };

      tooltip.style.display = 'block';
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
      tooltip.innerHTML = `
        <div><strong>${STOCKS[row]}</strong></div>
        <div>Time: T${point.t}</div>
        <div>Price: $${point.price.toFixed(2)}</div>
        <div>Change: ${point.change.toFixed(2)}%</div>
      `;

      draw();
    }

    canvas.addEventListener('mousemove', (evt) => {
      if (dragging) {
        const dx = evt.clientX - lastMouseX;
        lastMouseX = evt.clientX;

        const plotWidth = canvas.clientWidth - layout.leftPad - layout.rightPad;
        const visibleDataCols = Math.max(10, Math.floor(MAX_POINTS / view.scaleX));
        const colWidth = plotWidth / visibleDataCols;

        view.offsetX -= dx / colWidth;
        draw();
      } else {
        updateHover(evt);
      }
    });

    canvas.addEventListener('mousedown', (evt) => {
      dragging = true;
      lastMouseX = evt.clientX;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('mouseleave', () => {
      hoverCell = null;
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('wheel', (evt) => {
      evt.preventDefault();

      const mouse = getMousePos(evt);
      const plotWidth = canvas.clientWidth - layout.leftPad - layout.rightPad;
      const visibleBefore = Math.max(10, Math.floor(MAX_POINTS / view.scaleX));
      const colWidthBefore = plotWidth / visibleBefore;

      const mouseCol = (mouse.x - layout.leftPad) / colWidthBefore;
      const anchorDataX = view.offsetX + mouseCol;

      const zoomFactor = evt.deltaY > 0 ? 0.9 : 1.1;
      const nextScale = clamp(view.scaleX * zoomFactor, view.minScaleX, view.maxScaleX);
      view.scaleX = nextScale;

      const visibleAfter = Math.max(10, Math.floor(MAX_POINTS / view.scaleX));
      const colWidthAfter = plotWidth / visibleAfter;
      const newMouseCol = (mouse.x - layout.leftPad) / colWidthAfter;

      view.offsetX = anchorDataX - newMouseCol;
      draw();
    }, { passive: false });

    resetViewBtn.addEventListener('click', () => {
      view.offsetX = Math.max(0, MAX_POINTS - Math.floor(MAX_POINTS / view.scaleX));
      view.scaleX = 1;
      draw();
    });

    pauseBtn.addEventListener('click', () => {
      isStreaming = !isStreaming;
      pauseBtn.textContent = isStreaming ? 'Pause' : 'Resume';
      statusEl.textContent = `Streaming: ${isStreaming ? 'ON' : 'OFF'}`;
    });

    function tick() {
      if (isStreaming) {
        generateNextDataPoint();

        // Auto-follow latest data if near the right edge
        const visibleCols = Math.max(10, Math.floor(MAX_POINTS / view.scaleX));
        const maxOffset = Math.max(0, MAX_POINTS - visibleCols);
        if (view.offsetX > maxOffset - 5 || timeIndex < MAX_POINTS) {
          view.offsetX = maxOffset;
        }

        draw();
      }
    }

    // Seed initial data
    for (let i = 0; i < MAX_POINTS; i++) {
      generateNextDataPoint();
    }
    view.offsetX = 0;

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    setInterval(tick, UPDATE_INTERVAL);
  </script>
</body>
</html>
```

---

## How it works

### Data model
Each stock has a row of time-series points:

```js
{
  t: timeIndex,
  change: boundedChange,
  price: currentPrices[i]
}
```

### Rendering
- The heatmap is painted onto a canvas.
- Each stock/time pair becomes one colored rectangle.
- Red = negative movement
- Gray = neutral
- Green = positive movement

### Zoom and pan
- **Pan** changes `view.offsetX`
- **Zoom** changes `view.scaleX`
- Mouse wheel zooms around the cursor anchor point

### Real-time updates
A timer appends new data points and removes old ones beyond `MAX_POINTS`.

