</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Heatmap</h1>

      <div class="group">
        <button id="toggleStreamBtn">Pause Stream</button>
        <button id="resetViewBtn">Reset View</button>
      </div>

      <div class="group">
        <label for="windowSize">Time Window</label>
        <select id="windowSize">
          <option value="60">60 points</option>
          <option value="120" selected>120 points</option>
          <option value="240">240 points</option>
        </select>
      </div>

      <div class="status" id="statusText">Streaming...</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmapCanvas"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div class="legend-title">Price Change %</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>

      <div class="help">
        Wheel = zoom<br />
        Drag = pan<br />
        Hover = inspect
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, statusEl) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;
        this.statusEl = statusEl;
        this.dpr = window.devicePixelRatio || 1;

        this.margin = {
          top: 30,
          right: 20,
          bottom: 30,
          left: 90
        };

        this.symbols = [
          'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
          'META', 'TSLA', 'NFLX', 'AMD', 'INTC',
          'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA'
        ];

        this.windowSize = 120;
        this.maxChangeAbs = 5; // +/- 5%
        this.streaming = true;

        this.basePrices = {};
        this.latestPrices = {};
        this.data = []; // columns of time slices: [{timestamp, values: {SYM: pctChange}}]

        this.view = {
          scaleX: 1,
          scaleY: 1,
          offsetX: 0,
          offsetY: 0
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          lastY: 0,
          hoverCell: null
        };

        this.initPrices();
        this.seedInitialData();
        this.resize();
        this.bindEvents();
        this.startStream();
        this.render();
      }

      initPrices() {
        for (const sym of this.symbols) {
          const base = 50 + Math.random() * 450;
          this.basePrices[sym] = base;
          this.latestPrices[sym] = base;
        }
      }

      seedInitialData() {
        const now = Date.now();
        for (let i = this.windowSize - 1; i >= 0; i--) {
          const timestamp = now - i * 1000;
          this.stepSimulation(timestamp, false);
        }
      }

      stepSimulation(timestamp = Date.now(), render = true) {
        const values = {};

        for (const sym of this.symbols) {
          const current = this.latestPrices[sym];
          const drift = (Math.random() - 0.5) * 0.012;
          const next = Math.max(1, current * (1 + drift));
          this.latestPrices[sym] = next;

          const pctChange = ((next - this.basePrices[sym]) / this.basePrices[sym]) * 100;
          values[sym] = pctChange;
        }

        this.data.push({ timestamp, values });

        if (this.data.length > this.windowSize) {
          this.data.shift();
        }

        if (render) this.render();
      }

      startStream() {
        this.streamTimer = setInterval(() => {
          if (!this.streaming) return;
          this.stepSimulation();
          this.statusEl.textContent = `Streaming... ${new Date().toLocaleTimeString()}`;
        }, 500);
      }

      stopStream() {
        clearInterval(this.streamTimer);
      }

      setWindowSize(size) {
        this.windowSize = size;
        while (this.data.length > size) this.data.shift();

        if (this.data.length < size) {
          const missing = size - this.data.length;
          const firstTs = this.data[0]?.timestamp || Date.now();
          const prepend = [];
          for (let i = missing; i > 0; i--) {
            const timestamp = firstTs - i * 1000;
            const values = {};
            for (const sym of this.symbols) {
              values[sym] = ((this.latestPrices[sym] - this.basePrices[sym]) / this.basePrices[sym]) * 100;
            }
            prepend.push({ timestamp, values });
          }
          this.data = [...prepend, ...this.data];
        }

        this.render();
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('mousedown', (e) => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
          this.interaction.lastY = e.clientY;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();

          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            const dy = e.clientY - this.interaction.lastY;
            this.interaction.lastX = e.clientX;
            this.interaction.lastY = e.clientY;

            this.view.offsetX += dx;
            this.view.offsetY += dy;
            this.clampView();
            this.render();
            return;
          }

          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          const cell = this.getCellAt(x, y);

          if (cell) {
            this.interaction.hoverCell = cell;
            this.showTooltip(e.clientX - rect.left, e.clientY - rect.top, cell);
          } else {
            this.interaction.hoverCell = null;
            this.hideTooltip();
          }

          this.render();
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.interaction.hoverCell = null;
          this.hideTooltip();
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
          const prevScaleX = this.view.scaleX;
          const prevScaleY = this.view.scaleY;

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const plot = this.getPlotArea();

          const localX = mouseX - plot.x;
          const localY = mouseY - plot.y;

          this.view.scaleX = this.clamp(this.view.scaleX * zoomFactor, 1, 8);
          this.view.scaleY = this.clamp(this.view.scaleY * zoomFactor, 1, 6);

          const scaleRatioX = this.view.scaleX / prevScaleX;
          const scaleRatioY = this.view.scaleY / prevScaleY;

          this.view.offsetX = localX - (localX - this.view.offsetX) * scaleRatioX;
          this.view.offsetY = localY - (localY - this.view.offsetY) * scaleRatioY;

          this.clampView();
          this.render();
        }, { passive: false });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      getPlotArea() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        return {
          x: this.margin.left,
          y: this.margin.top,
          w: width - this.margin.left - this.margin.right,
          h: height - this.margin.top - this.margin.bottom
        };
      }

      clamp(value, min, max) {
        return Math.max(min, Math.min(max, value));
      }

      clampView() {
        const plot = this.getPlotArea();
        const scaledW = plot.w * this.view.scaleX;
        const scaledH = plot.h * this.view.scaleY;

        const minOffsetX = Math.min(0, plot.w - scaledW);
        const minOffsetY = Math.min(0, plot.h - scaledH);

        this.view.offsetX = this.clamp(this.view.offsetX, minOffsetX, 0);
        this.view.offsetY = this.clamp(this.view.offsetY, minOffsetY, 0);
      }

      valueToColor(value) {
        const v = this.clamp(value, -this.maxChangeAbs, this.maxChangeAbs);
        const t = (v + this.maxChangeAbs) / (2 * this.maxChangeAbs);

        const red = { r: 180, g: 35, b: 35 };
        const mid = { r: 80, g: 80, b: 80 };
        const green = { r: 30, g: 170, b: 70 };

        let c1, c2, p;
        if (t < 0.5) {
          c1 = red;
          c2 = mid;
          p = t / 0.5;
        } else {
          c1 = mid;
          c2 = green;
          p = (t - 0.5) / 0.5;
        }

        const r = Math.round(c1.r + (c2.r - c1.r) * p);
        const g = Math.round(c1.g + (c2.g - c1.g) * p);
        const b = Math.round(c1.b + (c2.b - c1.b) * p);

        return `rgb(${r}, ${g}, ${b})`;
      }

      getCellGeometry() {
        const plot = this.getPlotArea();
        const cols = Math.max(1, this.data.length);
        const rows = Math.max(1, this.symbols.length);

        const cellW = (plot.w / cols) * this.view.scaleX;
        const cellH = (plot.h / rows) * this.view.scaleY;

        return { plot, cols, rows, cellW, cellH };
      }

      getCellAt(mouseX, mouseY) {
        const { plot, cols, rows, cellW, cellH } = this.getCellGeometry();

        if (
          mouseX < plot.x || mouseX > plot.x + plot.w ||
          mouseY < plot.y || mouseY > plot.y + plot.h
        ) {
          return null;
        }

        const localX = mouseX - plot.x - this.view.offsetX;
        const localY = mouseY - plot.y - this.view.offsetY;

        if (localX < 0 || localY < 0) return null;

        const col = Math.floor(localX / cellW);
        const row = Math.floor(localY / cellH);

        if (col < 0 || col >= cols || row < 0 || row >= rows) return null;

        const point = this.data[col];
        const symbol = this.symbols[row];
        if (!point) return null;

        return {
          col,
          row,
          x: plot.x + this.view.offsetX + col * cellW,
          y: plot.y + this.view.offsetY + row * cellH,
          w: cellW,
          h: cellH,
          symbol,
          timestamp: point.timestamp,
          value: point.values[symbol]
        };
      }

      showTooltip(x, y, cell) {
        this.tooltip.style.display = 'block';
        this.tooltip.style.left = `${x}px`;
        this.tooltip.style.top = `${y}px`;
        this.tooltip.innerHTML = `
          <strong>${cell.symbol}</strong><br />
          Change: ${cell.value.toFixed(2)}%<br />
          Time: ${new Date(cell.timestamp).toLocaleTimeString()}
        `;
      }

      hideTooltip() {
        this.tooltip.style.display = 'none';
      }

      drawAxes() {
        const ctx = this.ctx;
        const plot = this.getPlotArea();

        ctx.save();

        ctx.strokeStyle = '#33457f';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(plot.x, plot.y);
        ctx.lineTo(plot.x, plot.y + plot.h);
        ctx.lineTo(plot.x + plot.w, plot.y + plot.h);
        ctx.stroke();

        ctx.fillStyle = '#8da2d9';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';

        const { cellH } = this.getCellGeometry();
        for (let i = 0; i < this.symbols.length; i++) {
          const y = plot.y + this.view.offsetY + i * cellH + cellH / 2;
          if (y < plot.y - cellH || y > plot.y + plot.h + cellH) continue;
          ctx.fillText(this.symbols[i], plot.x - 8, y);
        }

        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        const step = Math.max(1, Math.floor(this.data.length / 8));
        const { cellW } = this.getCellGeometry();

        for (let i = 0; i < this.data.length; i += step) {
          const x = plot.x + this.view.offsetX + i * cellW + cellW / 2;
          if (x < plot.x || x > plot.x + plot.w) continue;

          const ts = this.data[i]?.timestamp;
          if (!ts) continue;

          ctx.fillText(
            new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            x,
            plot.y + plot.h + 6
          );
        }

        ctx.restore();
      }

      drawHeatmap() {
        const ctx = this.ctx;
        const { plot, cellW, cellH } = this.getCellGeometry();

        ctx.save();

        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.w, plot.h);
        ctx.clip();

        for (let col = 0; col < this.data.length; col++) {
          const point = this.data[col];
          const x = plot.x + this.view.offsetX + col * cellW;

          if (x + cellW < plot.x || x > plot.x + plot.w) continue;

          for (let row = 0; row < this.symbols.length; row++) {
            const symbol = this.symbols[row];
            const y = plot.y + this.view.offsetY + row * cellH;

            if (y + cellH < plot.y || y > plot.y + plot.h) continue;

            const value = point.values[symbol];
            ctx.fillStyle = this.valueToColor(value);
            ctx.fillRect(x, y, cellW, cellH);

            ctx.strokeStyle = 'rgba(10, 20, 40, 0.35)';
            ctx.strokeRect(x, y, cellW, cellH);
          }
        }

        if (this.interaction.hoverCell) {
          const c = this.interaction.hoverCell;
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2;
          ctx.strokeRect(c.x + 1, c.y + 1, c.w - 2, c.h - 2);
        }

        ctx.restore();
      }

      drawGridOverlay() {
        const ctx = this.ctx;
        const { plot, cellW, cellH } = this.getCellGeometry();

        ctx.save();
        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.w, plot.h);
        ctx.clip();

        ctx.strokeStyle = 'rgba(120, 150, 220, 0.08)';
        ctx.lineWidth = 1;

        for (let i = 0; i <= this.data.length; i++) {
          const x = plot.x + this.view.offsetX + i * cellW;
          ctx.beginPath();
          ctx.moveTo(x, plot.y);
          ctx.lineTo(x, plot.y + plot.h);
          ctx.stroke();
        }

        for (let i = 0; i <= this.symbols.length; i++) {
          const y = plot.y + this.view.offsetY + i * cellH;
          ctx.beginPath();
          ctx.moveTo(plot.x, y);
          ctx.lineTo(plot.x + plot.w, y);
          ctx.stroke();
        }

        ctx.restore();
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);

        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, width, height);

        this.drawHeatmap();
        this.drawGridOverlay();
        this.drawAxes();
      }
    }

    const canvas = document.getElementById('heatmapCanvas');
    const tooltip = document.getElementById('tooltip');
    const statusText = document.getElementById('statusText');
    const chart = new StockHeatmap(canvas, tooltip, statusText);

    document.getElementById('toggleStreamBtn').addEventListener('click', (e) => {
      chart.streaming = !chart.streaming;
      e.target.textContent = chart.streaming ? 'Pause Stream' : 'Resume Stream';
      statusText.textContent = chart.streaming ? 'Streaming...' : 'Paused';
    });

    document.getElementById('resetViewBtn').addEventListener('click', () => {
      chart.view.scaleX = 1;
      chart.view.scaleY = 1;
      chart.view.offsetX = 0;
      chart.view.offsetY = 0;
      chart.render();
    });

    document.getElementById('windowSize').addEventListener('change', (e) => {
      chart.setWindowSize(Number(e.target.value));
    });
  </script>
</body>
</html>
```

