  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Price Heatmap</h1>
      <div class="legend">
        <span>Negative</span>
        <div class="gradient"></div>
        <span>Positive</span>
      </div>
      <div class="pill">Wheel: Zoom</div>
      <div class="pill">Drag: Pan</div>
      <div class="pill">Hover: Inspect</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="footer">
      Simulated realtime updates. Colors represent normalized price change percentages.
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, options = {}) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;

        this.symbols = options.symbols || [
          'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA',
          'NVDA', 'META', 'NFLX', 'AMD', 'INTC',
          'BABA', 'ORCL', 'CRM', 'UBER', 'SHOP'
        ];

        this.totalCols = options.totalCols || 240;
        this.visibleCols = options.visibleCols || 80;
        this.minVisibleCols = 20;
        this.maxVisibleCols = this.totalCols;

        this.data = [];
        this.timestamps = [];
        this.prices = new Map();

        this.offsetX = this.totalCols - this.visibleCols;
        this.isDragging = false;
        this.dragStartX = 0;
        this.dragStartOffsetX = 0;

        this.padding = {
          top: 20,
          right: 20,
          bottom: 30,
          left: 70
        };

        this.dpr = window.devicePixelRatio || 1;

        this.initData();
        this.bindEvents();
        this.resize();
        this.startRealtime();
        this.render();
      }

      initData() {
        const now = Date.now();

        for (const symbol of this.symbols) {
          this.prices.set(symbol, 100 + Math.random() * 200);
        }

        for (let col = 0; col < this.totalCols; col++) {
          const row = [];
          const ts = now - (this.totalCols - col) * 1000;
          this.timestamps.push(ts);

          for (const symbol of this.symbols) {
            const prev = this.prices.get(symbol);
            const next = prev * (1 + (Math.random() - 0.5) * 0.01);
            this.prices.set(symbol, next);

            const pctChange = ((next - prev) / prev) * 100;
            row.push({
              symbol,
              price: next,
              pctChange,
              timestamp: ts
            });
          }

          this.data.push(row);
        }
      }

      startRealtime() {
        setInterval(() => {
          this.pushNextColumn();
          const nearRightEdge = this.offsetX + this.visibleCols >= this.totalCols - 2;
          if (nearRightEdge) {
            this.offsetX = this.totalCols - this.visibleCols;
          }
          this.render();
        }, 1000);
      }

      pushNextColumn() {
        const ts = Date.now();
        const row = [];

        for (const symbol of this.symbols) {
          const prev = this.prices.get(symbol);
          const volatility = symbol === 'TSLA' || symbol === 'NVDA' ? 0.02 : 0.01;
          const next = prev * (1 + (Math.random() - 0.5) * volatility);
          this.prices.set(symbol, next);

          const pctChange = ((next - prev) / prev) * 100;
          row.push({
            symbol,
            price: next,
            pctChange,
            timestamp: ts
          });
        }

        this.data.push(row);
        this.timestamps.push(ts);

        if (this.data.length > this.totalCols) {
          this.data.shift();
          this.timestamps.shift();
        }
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const zoomFactor = e.deltaY > 0 ? 1.1 : 0.9;
          const mouse = this.getMousePos(e);
          const plot = this.getPlotArea();

          if (mouse.x < plot.x || mouse.x > plot.x + plot.width) return;

          const relativeX = (mouse.x - plot.x) / plot.width;
          const anchorCol = this.offsetX + relativeX * this.visibleCols;

          let nextVisible = Math.round(this.visibleCols * zoomFactor);
          nextVisible = Math.max(this.minVisibleCols, Math.min(this.maxVisibleCols, nextVisible));

          const newOffset = anchorCol - relativeX * nextVisible;
          this.visibleCols = nextVisible;
          this.offsetX = Math.max(0, Math.min(this.totalCols - this.visibleCols, newOffset));

          this.render();
        }, { passive: false });

        this.canvas.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.dragStartX = e.clientX;
          this.dragStartOffsetX = this.offsetX;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const mouse = this.getMousePos(e);
          this.updateTooltip(mouse.x, mouse.y);

          if (!this.isDragging) return;

          const plot = this.getPlotArea();
          const dx = e.clientX - this.dragStartX;
          const colsPerPixel = this.visibleCols / plot.width;
          const deltaCols = dx * colsPerPixel;

          this.offsetX = this.dragStartOffsetX - deltaCols;
          this.offsetX = Math.max(0, Math.min(this.totalCols - this.visibleCols, this.offsetX));
          this.render();
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.canvas.classList.remove('dragging');
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.tooltip.style.display = 'none';
        });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      getPlotArea() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        return {
          x: this.padding.left,
          y: this.padding.top,
          width: width - this.padding.left - this.padding.right,
          height: height - this.padding.top - this.padding.bottom
        };
      }

      getMousePos(e) {
        const rect = this.canvas.getBoundingClientRect();
        return {
          x: e.clientX - rect.left,
          y: e.clientY - rect.top
        };
      }

      formatTime(ts) {
        return new Date(ts).toLocaleTimeString([], {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit'
        });
      }

      colorForChange(pct) {
        const clamped = Math.max(-2, Math.min(2, pct));
        const t = (clamped + 2) / 4;

        if (t < 0.5) {
          const local = t / 0.5;
          return this.lerpColor([139, 0, 0], [43, 43, 43], local);
        } else {
          const local = (t - 0.5) / 0.5;
          return this.lerpColor([43, 43, 43], [0, 230, 118], local);
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      renderAxes(plot) {
        const ctx = this.ctx;
        const rows = this.symbols.length;
        const rowHeight = plot.height / rows;

        ctx.strokeStyle = '#2b3957';
        ctx.fillStyle = '#8ea0c9';
        ctx.lineWidth = 1;
        ctx.font = '12px Inter, system-ui, sans-serif';

        for (let r = 0; r < rows; r++) {
          const y = plot.y + r * rowHeight;
          ctx.beginPath();
          ctx.moveTo(plot.x, y);
          ctx.lineTo(plot.x + plot.width, y);
          ctx.stroke();

          ctx.fillText(this.symbols[r], 12, y + rowHeight * 0.65);
        }

        ctx.beginPath();
        ctx.moveTo(plot.x, plot.y + plot.height);
        ctx.lineTo(plot.x + plot.width, plot.y + plot.height);
        ctx.stroke();

        const tickCount = 6;
        for (let i = 0; i <= tickCount; i++) {
          const x = plot.x + (i / tickCount) * plot.width;
          const col = Math.floor(this.offsetX + (i / tickCount) * (this.visibleCols - 1));
          const ts = this.timestamps[Math.max(0, Math.min(this.timestamps.length - 1, col))];

          ctx.beginPath();
          ctx.moveTo(x, plot.y + plot.height);
          ctx.lineTo(x, plot.y + plot.height + 5);
          ctx.stroke();

          if (ts) {
            ctx.fillText(this.formatTime(ts), x - 22, plot.y + plot.height + 18);
          }
        }
      }

      renderCells(plot) {
        const ctx = this.ctx;
        const rows = this.symbols.length;
        const rowHeight = plot.height / rows;
        const colWidth = plot.width / this.visibleCols;

        const startCol = Math.floor(this.offsetX);
        const endCol = Math.min(this.totalCols, Math.ceil(this.offsetX + this.visibleCols));
        const fracOffset = this.offsetX - startCol;

        for (let c = startCol; c < endCol; c++) {
          const screenX = plot.x + (c - startCol - fracOffset) * colWidth;
          const colData = this.data[c];
          if (!colData) continue;

          for (let r = 0; r < rows; r++) {
            const cell = colData[r];
            const y = plot.y + r * rowHeight;

            ctx.fillStyle = this.colorForChange(cell.pctChange);
            ctx.fillRect(
              screenX,
              y,
              Math.ceil(colWidth) + 1,
              Math.ceil(rowHeight) + 1
            );
          }
        }
      }

      updateTooltip(mouseX, mouseY) {
        const plot = this.getPlotArea();

        if (
          mouseX < plot.x || mouseX > plot.x + plot.width ||
          mouseY < plot.y || mouseY > plot.y + plot.height
        ) {
          this.tooltip.style.display = 'none';
          return;
        }

        const rowHeight = plot.height / this.symbols.length;
        const colWidth = plot.width / this.visibleCols;

        const row = Math.floor((mouseY - plot.y) / rowHeight);
        const col = Math.floor(this.offsetX + (mouseX - plot.x) / colWidth);

        const cell = this.data[col]?.[row];
        if (!cell) {
          this.tooltip.style.display = 'none';
          return;
        }

        this.tooltip.innerHTML = `
          <strong>${cell.symbol}</strong><br/>
          Price: $${cell.price.toFixed(2)}<br/>
          Change: ${cell.pctChange >= 0 ? '+' : ''}${cell.pctChange.toFixed(2)}%<br/>
          Time: ${this.formatTime(cell.timestamp)}
        `;

        this.tooltip.style.display = 'block';
        this.tooltip.style.left = `${mouseX}px`;
        this.tooltip.style.top = `${mouseY}px`;
      }

      clear() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        this.ctx.clearRect(0, 0, width, height);
      }

      render() {
        this.clear();

        const plot = this.getPlotArea();

        this.ctx.fillStyle = '#121a2b';
        this.ctx.fillRect(0, 0, this.canvas.width / this.dpr, this.canvas.height / this.dpr);

        this.renderCells(plot);
        this.renderAxes(plot);
      }
    }

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');

    new StockHeatmap(canvas, tooltip, {
      totalCols: 240,
      visibleCols: 80
    });
  </script>
</body>
</html>
