    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(20, 24, 38, 0.95);
      color: #fff;
      border: 1px solid #3a4470;
      border-radius: 6px;
      padding: 8px 10px;
      font-size: 12px;
      line-height: 1.4;
      white-space: nowrap;
      transform: translate(12px, 12px);
      display: none;
      z-index: 10;
      box-shadow: 0 4px 18px rgba(0,0,0,0.35);
    }

    .legend {
      position: absolute;
      right: 12px;
      bottom: 12px;
      background: rgba(20, 24, 38, 0.92);
      border: 1px solid #2a3152;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      border-radius: 6px;
      margin: 6px 0 4px;
      background: linear-gradient(to right, #8b0000, #d73027, #2b2b2b, #1a9850, #006400);
    }

    .legend-labels {
      display: flex;
      justify-content: space-between;
      color: #b8c0d9;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetZoom">Reset Zoom</button>
      <span id="status">Streaming simulated stock updates...</span>
    </div>
    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div>Price Change %</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const resetZoomBtn = document.getElementById("resetZoom");

    const DPR = window.devicePixelRatio || 1;

    const margin = {
      top: 20,
      right: 20,
      bottom: 40,
      left: 90
    };

    const symbols = [
      "AAPL", "MSFT", "GOOG", "AMZN", "NVDA",
      "META", "TSLA", "AMD", "NFLX", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "SNOW",
      "BABA", "PYPL", "ADBE", "QCOM", "AVGO"
    ];

    const maxTimeSteps = 240;
    const updateIntervalMs = 1000;
    const visibleWindowDefault = 60;

    let data = [];
    let timestamps = [];
    let prices = {};
    let transform = d3.zoomIdentity;

    symbols.forEach(symbol => {
      prices[symbol] = 100 + Math.random() * 200;
    });

    function nowLabel(date = new Date()) {
      return date.toLocaleTimeString();
    }

    function generateNextColumn() {
      const ts = new Date();
      timestamps.push(ts);

      const col = symbols.map(symbol => {
        const prev = prices[symbol];
        const drift = (Math.random() - 0.5) * 2.5;
        const next = Math.max(10, prev + drift);
        const pct = ((next - prev) / prev) * 100;
        prices[symbol] = next;

        return {
          symbol,
          timestamp: ts,
          price: next,
          changePct: pct
        };
      });

      data.push(col);

      if (data.length > maxTimeSteps) {
        data.shift();
        timestamps.shift();
      }
    }

    for (let i = 0; i < visibleWindowDefault; i++) {
      generateNextColumn();
    }

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = rect.width * DPR;
      canvas.height = rect.height * DPR;
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function getChartSize() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      return {
        width,
        height,
        innerWidth: width - margin.left - margin.right,
        innerHeight: height - margin.top - margin.bottom
      };
    }

    function colorForChange(v) {
      const clamped = Math.max(-5, Math.min(5, v));
      return d3.interpolateRdYlGn((clamped + 5) / 10);
    }

    function getBaseScales() {
      const { innerWidth, innerHeight } = getChartSize();

      const x = d3.scaleLinear()
        .domain([0, Math.max(0, data.length)])
        .range([margin.left, margin.left + innerWidth]);

      const y = d3.scaleBand()
        .domain(symbols)
        .range([margin.top, margin.top + innerHeight])
        .paddingInner(0.05)
        .paddingOuter(0.02);

      return { x, y };
    }

    function drawAxes(xScale, yScale) {
      const { width, height, innerHeight } = getChartSize();

      ctx.save();
      ctx.strokeStyle = "#506080";
      ctx.fillStyle = "#b8c0d9";
      ctx.lineWidth = 1;

      // Y axis labels
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      ctx.font = "12px Arial";

      symbols.forEach(symbol => {
        const y = yScale(symbol) + yScale.bandwidth() / 2;
        ctx.fillText(symbol, margin.left - 8, y);
      });

      // X axis line
      ctx.beginPath();
      ctx.moveTo(margin.left, margin.top + innerHeight);
      ctx.lineTo(width - margin.right, margin.top + innerHeight);
      ctx.stroke();

      // Y axis line
      ctx.beginPath();
      ctx.moveTo(margin.left, margin.top);
      ctx.lineTo(margin.left, margin.top + innerHeight);
      ctx.stroke();

      // X ticks
      ctx.textAlign = "center";
      ctx.textBaseline = "top";

      const tickCount = Math.min(8, data.length);
      for (let i = 0; i < tickCount; i++) {
        const idx = Math.floor((i / Math.max(1, tickCount - 1)) * Math.max(0, data.length - 1));
        const x = xScale(idx + 0.5);
        const ts = timestamps[idx];
        if (!ts) continue;

        ctx.beginPath();
        ctx.moveTo(x, margin.top + innerHeight);
        ctx.lineTo(x, margin.top + innerHeight + 6);
        ctx.stroke();

        ctx.fillText(nowLabel(ts), x, margin.top + innerHeight + 8);
      }

      ctx.restore();
    }

    function drawHeatmap() {
      const { width, height, innerWidth, innerHeight } = getChartSize();
      ctx.clearRect(0, 0, width, height);

      ctx.fillStyle = "#0f1220";
      ctx.fillRect(0, 0, width, height);

      const { x: baseX, y } = getBaseScales();
      const x = transform.rescaleX(baseX);

      // Clip chart area
      ctx.save();
      ctx.beginPath();
      ctx.rect(margin.left, margin.top, innerWidth, innerHeight);
      ctx.clip();

      const bandwidthY = y.bandwidth();

      for (let colIndex = 0; colIndex < data.length; colIndex++) {
        const x0 = x(colIndex);
        const x1 = x(colIndex + 1);
        const cellWidth = x1 - x0;

        if (x1 < margin.left || x0 > margin.left + innerWidth) continue;
        if (cellWidth < 0.25) continue;

        const col = data[colIndex];

        for (let rowIndex = 0; rowIndex < col.length; rowIndex++) {
          const d = col[rowIndex];
          const y0 = y(d.symbol);

          ctx.fillStyle = colorForChange(d.changePct);
          ctx.fillRect(x0, y0, Math.max(1, cellWidth), bandwidthY);
        }
      }

      ctx.restore();

      drawAxes(x, y);
    }

    function draw() {
      drawHeatmap();
    }

    function getDatumAt(mx, my) {
      const { innerWidth, innerHeight } = getChartSize();
      if (
        mx < margin.left ||
        mx > margin.left + innerWidth ||
        my < margin.top ||
        my > margin.top + innerHeight
      ) {
        return null;
      }

      const { x: baseX, y } = getBaseScales();
      const x = transform.rescaleX(baseX);

      const symbol = symbols.find(s => {
        const y0 = y(s);
        return my >= y0 && my <= y0 + y.bandwidth();
      });

      if (!symbol) return null;

      let colIndex = null;
      for (let i = 0; i < data.length; i++) {
        const x0 = x(i);
        const x1 = x(i + 1);
        if (mx >= x0 && mx <= x1) {
          colIndex = i;
          break;
        }
      }

      if (colIndex == null || !data[colIndex]) return null;

      const datum = data[colIndex].find(d => d.symbol === symbol);
      return datum || null;
    }

    canvas.addEventListener("mousemove", (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const datum = getDatumAt(mx, my);
      if (!datum) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = `${mx}px`;
      tooltip.style.top = `${my}px`;
      tooltip.innerHTML = `
        <div><strong>${datum.symbol}</strong></div>
        <div>Time: ${nowLabel(datum.timestamp)}</div>
        <div>Price: $${datum.price.toFixed(2)}</div>
        <div>Change: <span style="color:${colorForChange(datum.changePct)}">${datum.changePct.toFixed(2)}%</span></div>
      `;
    });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    const zoom = d3.zoom()
      .scaleExtent([1, 20])
      .translateExtent([[margin.left, 0], [100000, 100000]])
      .extent([[margin.left, margin.top], [window.innerWidth - margin.right, window.innerHeight - margin.bottom]])
      .on("zoom", (event) => {
        transform = event.transform;
        draw();
      });

    d3.select(canvas).call(zoom);

    resetZoomBtn.addEventListener("click", () => {
      d3.select(canvas)
        .transition()
        .duration(250)
        .call(zoom.transform, d3.zoomIdentity);
    });

    function tick() {
      generateNextColumn();

      // Auto-scroll effect while at identity zoom:
      if (transform.k === 1) {
        draw();
      } else {
        draw();
      }
    }

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    setInterval(tick, updateIntervalMs);
  </script>
</body>
</html>
```

---

## How it works

### Data model
`data` is an array of time columns:

```js
data = [
  [
    { symbol: "AAPL", timestamp, price, changePct },
    { symbol: "MSFT", timestamp, price, changePct },
    ...
  ],
  ...
]
```

Each column is one time step across all stocks.

### Rendering
- Uses a single `<canvas>`
- Each cell is drawn as a colored rectangle
- Color maps percentage change to red/yellow/green

### Zoom/pan
- `d3.zoom()` manages transform state
- x positions are rescaled with `transform.rescaleX(baseX)`
- y is currently fixed-band layout, though panning visually affects the whole transform interaction model only through x rescaling in this version

### Real-time updates
- Every second a new column is generated
- Old columns are dropped after `maxTimeSteps`

---

## Limitations of this initial version

This is a good starting point, but a production implementation would improve:

1. **True 2D zoom/pan**
   - current implementation effectively rescales x only
   - y-axis is fixed
   - if you want, I can provide full 2D pan/zoom

2. **Axis rendering**
   - axes are manually drawn on canvas
   - SVG overlay for axes can make labels cleaner

3. **Data source**
   - currently simulated
   - replace with WebSocket stream for real market data

4. **Performance**
   - for thousands of symbols/time buckets, consider:
     - offscreen canvas
     - WebGL
     - dirty-rect redraws

5. **Auto-follow latest data**
   - currently updates append, but viewport behavior is basic
   - can add “stick to latest” mode

