</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <button id="resetViewBtn">Reset View</button>
      <button id="pauseBtn">Pause Stream</button>
      <div class="meta" id="status"></div>
    </div>

    <div class="container" id="container">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        Price Change
        <div class="legend-bar"></div>
        <div style="display:flex; justify-content:space-between; margin-top:4px;">
          <span>-2%</span>
          <span>0%</span>
          <span>+2%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const container = document.getElementById('container');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetViewBtn = document.getElementById('resetViewBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    const DPR = () => window.devicePixelRatio || 1;

    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'META', 'TSLA', 'AMD', 'NFLX', 'INTC',
      'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA'
    ];

    const state = {
      rows: symbols.length,
      cols: 180,
      data: [],
      timestamps: [],
      basePrices: {},
      latestPrices: {},
      paused: false,

      // viewport in column space
      viewStartCol: 0,
      viewColCount: 60,

      // interaction
      isDragging: false,
      dragStartX: 0,
      dragStartViewStart: 0,

      hover: null,

      layout: {
        leftPad: 80,
        rightPad: 20,
        topPad: 20,
        bottomPad: 30
      }
    };

    function initData() {
      const now = Date.now();
      state.data = Array.from({ length: state.rows }, () => Array(state.cols).fill(0));
      state.timestamps = Array.from({ length: state.cols }, (_, i) => now - (state.cols - 1 - i) * 1000);

      symbols.forEach(symbol => {
        const base = 50 + Math.random() * 250;
        state.basePrices[symbol] = base;
        state.latestPrices[symbol] = base;

        for (let c = 0; c < state.cols; c++) {
          const drift = (Math.random() - 0.5) * 0.02;
          state.latestPrices[symbol] *= (1 + drift * 0.2);
          const pct = ((state.latestPrices[symbol] - base) / base) * 100;
          state.data[symbols.indexOf(symbol)][c] = pct;
        }
      });

      state.viewStartCol = Math.max(0, state.cols - state.viewColCount);
    }

    function resize() {
      const rect = container.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * DPR());
      canvas.height = Math.floor(rect.height * DPR());
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(DPR(), 0, 0, DPR(), 0, 0);
      render();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function valueToColor(v) {
      const min = -2;
      const max = 2;
      const t = clamp((v - min) / (max - min), 0, 1);

      // red -> yellow -> green
      let r, g, b;
      if (t < 0.5) {
        const k = t / 0.5;
        r = 180 + (230 - 180) * k;
        g = 30 + (200 - 30) * k;
        b = 30 + (60 - 30) * k;
      } else {
        const k = (t - 0.5) / 0.5;
        r = 230 + (20 - 230) * k;
        g = 200 + (180 - 200) * k;
        b = 60 + (90 - 60) * k;
      }
      return `rgb(${r|0}, ${g|0}, ${b|0})`;
    }

    function formatTime(ts) {
      const d = new Date(ts);
      return d.toLocaleTimeString();
    }

    function getPlotRect() {
      const { leftPad, rightPad, topPad, bottomPad } = state.layout;
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      return {
        x: leftPad,
        y: topPad,
        w: width - leftPad - rightPad,
        h: height - topPad - bottomPad
      };
    }

    function render() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const plot = getPlotRect();
      const visibleCols = Math.floor(state.viewColCount);
      const startCol = Math.floor(state.viewStartCol);
      const endCol = clamp(startCol + visibleCols, 0, state.cols);

      const rowHeight = plot.h / state.rows;
      const colWidth = plot.w / Math.max(1, (endCol - startCol));

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      // Plot bg
      ctx.fillStyle = '#0f1728';
      ctx.fillRect(plot.x, plot.y, plot.w, plot.h);

      // Cells
      for (let r = 0; r < state.rows; r++) {
        for (let c = startCol; c < endCol; c++) {
          const x = plot.x + (c - startCol) * colWidth;
          const y = plot.y + r * rowHeight;
          ctx.fillStyle = valueToColor(state.data[r][c]);
          ctx.fillRect(x, y, Math.ceil(colWidth), Math.ceil(rowHeight));
        }
      }

      // Grid lines
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;

      for (let r = 0; r <= state.rows; r++) {
        const y = plot.y + r * rowHeight;
        ctx.beginPath();
        ctx.moveTo(plot.x, y);
        ctx.lineTo(plot.x + plot.w, y);
        ctx.stroke();
      }

      const timeTicks = 6;
      for (let i = 0; i <= timeTicks; i++) {
        const x = plot.x + (i / timeTicks) * plot.w;
        ctx.beginPath();
        ctx.moveTo(x, plot.y);
        ctx.lineTo(x, plot.y + plot.h);
        ctx.stroke();
      }

      // Y labels
      ctx.fillStyle = '#d7e0ff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let r = 0; r < state.rows; r++) {
        const y = plot.y + r * rowHeight + rowHeight / 2;
        ctx.fillText(symbols[r], plot.x - 8, y);
      }

      // X labels
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillStyle = '#8fa3c7';
      for (let i = 0; i <= timeTicks; i++) {
        const ratio = i / timeTicks;
        const col = Math.floor(startCol + ratio * Math.max(0, (endCol - startCol - 1)));
        const x = plot.x + ratio * plot.w;
        const ts = state.timestamps[col];
        if (ts) ctx.fillText(formatTime(ts), x, plot.y + plot.h + 6);
      }

      // Hover outline
      if (state.hover) {
        const { row, col } = state.hover;
        if (col >= startCol && col < endCol) {
          const x = plot.x + (col - startCol) * colWidth;
          const y = plot.y + row * rowHeight;
          ctx.strokeStyle = 'rgba(255,255,255,0.95)';
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, Math.max(0, colWidth - 2), Math.max(0, rowHeight - 2));
        }
      }

      statusEl.textContent =
        `${state.paused ? 'Paused' : 'Streaming'} · ` +
        `Visible: ${endCol - startCol}/${state.cols} time slices`;
    }

    function pushDataPoint() {
      const ts = Date.now();
      state.timestamps.push(ts);
      if (state.timestamps.length > state.cols) state.timestamps.shift();

      for (let r = 0; r < state.rows; r++) {
        const symbol = symbols[r];
        const base = state.basePrices[symbol];
        const prev = state.latestPrices[symbol];

        const volatility = 0.003 + Math.random() * 0.004;
        const next = prev * (1 + (Math.random() - 0.5) * volatility * 2);
        state.latestPrices[symbol] = next;

        const pct = ((next - base) / base) * 100;
        state.data[r].push(pct);
        if (state.data[r].length > state.cols) state.data[r].shift();
      }

      // auto-follow when near right edge
      const maxStart = Math.max(0, state.cols - state.viewColCount);
      if (state.viewStartCol >= maxStart - 2) {
        state.viewStartCol = maxStart;
      }

      render();
    }

    function getCellFromMouse(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const plot = getPlotRect();

      if (x < plot.x || x > plot.x + plot.w || y < plot.y || y > plot.y + plot.h) {
        return null;
      }

      const startCol = Math.floor(state.viewStartCol);
      const endCol = clamp(startCol + Math.floor(state.viewColCount), 0, state.cols);
      const rowHeight = plot.h / state.rows;
      const colWidth = plot.w / Math.max(1, (endCol - startCol));

      const row = clamp(Math.floor((y - plot.y) / rowHeight), 0, state.rows - 1);
      const col = clamp(startCol + Math.floor((x - plot.x) / colWidth), startCol, endCol - 1);

      return { row, col, x, y };
    }

    canvas.addEventListener('mousemove', (e) => {
      if (state.isDragging) {
        const plot = getPlotRect();
        const dx = e.clientX - state.dragStartX;
        const colsMoved = -dx / (plot.w / state.viewColCount);
        const maxStart = Math.max(0, state.cols - state.viewColCount);
        state.viewStartCol = clamp(state.dragStartViewStart + colsMoved, 0, maxStart);
        render();
        tooltip.style.display = 'none';
        return;
      }

      const cell = getCellFromMouse(e.clientX, e.clientY);
      if (!cell) {
        state.hover = null;
        tooltip.style.display = 'none';
        render();
        return;
      }

      state.hover = { row: cell.row, col: cell.col };
      const symbol = symbols[cell.row];
      const value = state.data[cell.row][cell.col];
      const ts = state.timestamps[cell.col];

      tooltip.innerHTML = `
        <div><strong>${symbol}</strong></div>
        <div>Time: ${formatTime(ts)}</div>
        <div>Change: ${value.toFixed(2)}%</div>
      `;
      tooltip.style.display = 'block';
      tooltip.style.left = `${cell.x}px`;
      tooltip.style.top = `${cell.y}px`;

      render();
    });

    canvas.addEventListener('mouseleave', () => {
      state.hover = null;
      tooltip.style.display = 'none';
      render();
    });

    canvas.addEventListener('mousedown', (e) => {
      state.isDragging = true;
      state.dragStartX = e.clientX;
      state.dragStartViewStart = state.viewStartCol;
    });

    window.addEventListener('mouseup', () => {
      state.isDragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const plot = getPlotRect();
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const rel = clamp((mouseX - plot.x) / plot.w, 0, 1);

      const oldCount = state.viewColCount;
      const zoomFactor = e.deltaY > 0 ? 1.15 : 0.85;
      const newCount = clamp(oldCount * zoomFactor, 10, state.cols);

      const anchorCol = state.viewStartCol + rel * oldCount;
      let newStart = anchorCol - rel * newCount;
      const maxStart = Math.max(0, state.cols - newCount);
      newStart = clamp(newStart, 0, maxStart);

      state.viewColCount = newCount;
      state.viewStartCol = newStart;
      render();
    }, { passive: false });

    resetViewBtn.addEventListener('click', () => {
      state.viewColCount = 60;
      state.viewStartCol = Math.max(0, state.cols - state.viewColCount);
      render();
    });

    pauseBtn.addEventListener('click', () => {
      state.paused = !state.paused;
      pauseBtn.textContent = state.paused ? 'Resume Stream' : 'Pause Stream';
      render();
    });

    initData();
    resize();
    window.addEventListener('resize', resize);

    setInterval(() => {
      if (!state.paused) pushDataPoint();
    }, 1000);
  </script>
</body>
</html>
