      white-space: nowrap;
      transform: translate(10px, 10px);
      display: none;
      z-index: 10;
      box-shadow: 0 4px 16px rgba(0,0,0,0.25);
    }

    .legend {
      margin-left: auto;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .legend-bar {
      width: 140px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(
        to right,
        #7f1d1d 0%,
        #ef4444 25%,
        #1f2937 50%,
        #22c55e 75%,
        #14532d 100%
      );
      border: 1px solid #334155;
    }

    .status {
      color: #94a3b8;
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetViewBtn">Reset View</button>
      <button id="toggleStreamBtn">Pause Stream</button>
      <div class="status" id="statusText">Streaming live updates...</div>
      <div class="legend">
        <span>-</span>
        <div class="legend-bar"></div>
        <span>+</span>
      </div>
    </div>
    <div class="container" id="container">
      <canvas id="heatmapCanvas"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL", "MSFT", "GOOG", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "BABA", "ORCL", "CRM", "UBER", "SHOP"
    ];

    const state = {
      data: [],
      maxColumns: 240,
      basePrices: new Map(),
      streamActive: true,
      hoveredCell: null,

      // View transform
      offsetX: 0,
      scaleX: 1,
      minScaleX: 0.5,
      maxScaleX: 8,

      // Layout
      leftAxisWidth: 80,
      topAxisHeight: 30,
      rowHeight: 28,
      baseColWidth: 18,

      // Interaction
      dragging: false,
      lastMouseX: 0,
      lastMouseY: 0
    };

    const canvas = document.getElementById("heatmapCanvas");
    const ctx = canvas.getContext("2d");
    const container = document.getElementById("container");
    const tooltip = document.getElementById("tooltip");
    const resetViewBtn = document.getElementById("resetViewBtn");
    const toggleStreamBtn = document.getElementById("toggleStreamBtn");
    const statusText = document.getElementById("statusText");

    function initBasePrices() {
      symbols.forEach(symbol => {
        state.basePrices.set(symbol, 80 + Math.random() * 220);
      });
    }

    function generateSnapshot() {
      const timestamp = Date.now();
      const snapshot = {
        timestamp,
        values: symbols.map(symbol => {
          const prev = state.data.length
            ? state.data[state.data.length - 1].values.find(v => v.symbol === symbol)?.price ?? state.basePrices.get(symbol)
            : state.basePrices.get(symbol);

          const drift = (Math.random() - 0.5) * 2.5;
          const next = Math.max(1, prev + drift);

          return {
            symbol,
            price: next,
            changePct: ((next - state.basePrices.get(symbol)) / state.basePrices.get(symbol]) * 100
          };
        })
      };

      state.data.push(snapshot);
      if (state.data.length > state.maxColumns) {
        state.data.shift();
      }
    }

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = container.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function formatTime(ts) {
      const d = new Date(ts);
      return d.toLocaleTimeString();
    }

    function getColor(changePct) {
      // Clamp around [-5%, 5%]
      const normalized = clamp(changePct / 5, -1, 1);

      if (normalized < 0) {
        const t = Math.abs(normalized);
        return lerpColor([31, 41, 55], [239, 68, 68], t);
      } else {
        const t = normalized;
        return lerpColor([31, 41, 55], [34, 197, 94], t);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const bch = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r}, ${g}, ${bch})`;
    }

    function getColumnWidth() {
      return state.baseColWidth * state.scaleX;
    }

    function getGridWidth() {
      return canvas.clientWidth - state.leftAxisWidth;
    }

    function getGridHeight() {
      return canvas.clientHeight - state.topAxisHeight;
    }

    function getMaxOffsetX() {
      const totalWidth = state.data.length * getColumnWidth();
      return Math.max(0, totalWidth - getGridWidth());
    }

    function resetView() {
      state.scaleX = 1;
      state.offsetX = Math.max(0, state.data.length * getColumnWidth() - getGridWidth());
      draw();
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, width, height);

      drawAxes(width, height);
      drawHeatmap(width, height);
      drawHover();
    }

    function drawAxes(width, height) {
      ctx.fillStyle = "#111827";
      ctx.fillRect(0, 0, width, state.topAxisHeight);
      ctx.fillRect(0, 0, state.leftAxisWidth, height);

      ctx.strokeStyle = "#334155";
      ctx.beginPath();
      ctx.moveTo(state.leftAxisWidth, 0);
      ctx.lineTo(state.leftAxisWidth, height);
      ctx.moveTo(0, state.topAxisHeight);
      ctx.lineTo(width, state.topAxisHeight);
      ctx.stroke();

      ctx.fillStyle = "#cbd5e1";
      ctx.font = "12px Arial";
      ctx.textBaseline = "middle";

      // Row labels
      symbols.forEach((symbol, row) => {
        const y = state.topAxisHeight + row * state.rowHeight + state.rowHeight / 2;
        if (y < state.topAxisHeight || y > height) return;
        ctx.fillText(symbol, 10, y);
      });

      // Time labels
      const colWidth = getColumnWidth();
      const startCol = Math.floor(state.offsetX / colWidth);
      const endCol = Math.min(
        state.data.length,
        Math.ceil((state.offsetX + getGridWidth()) / colWidth)
      );

      for (let col = startCol; col < endCol; col++) {
        const x = state.leftAxisWidth + col * colWidth - state.offsetX;
        if (col % Math.max(1, Math.floor(80 / colWidth)) === 0 && state.data[col]) {
          ctx.save();
          ctx.translate(x + 2, state.topAxisHeight - 4);
          ctx.rotate(-Math.PI / 4);
          ctx.fillStyle = "#94a3b8";
          ctx.textBaseline = "bottom";
          ctx.fillText(formatTime(state.data[col].timestamp), 0, 0);
          ctx.restore();
        }
      }
    }

    function drawHeatmap(width, height) {
      const colWidth = getColumnWidth();
      const startCol = Math.floor(state.offsetX / colWidth);
      const endCol = Math.min(
        state.data.length,
        Math.ceil((state.offsetX + getGridWidth()) / colWidth)
      );

      for (let row = 0; row < symbols.length; row++) {
        const y = state.topAxisHeight + row * state.rowHeight;
        if (y > height) continue;

        for (let col = startCol; col < endCol; col++) {
          const snapshot = state.data[col];
          if (!snapshot) continue;

          const point = snapshot.values[row];
          const x = state.leftAxisWidth + col * colWidth - state.offsetX;

          ctx.fillStyle = getColor(point.changePct);
          ctx.fillRect(x, y, Math.ceil(colWidth), state.rowHeight - 1);

          if (colWidth > 32) {
            ctx.fillStyle = "#e5e7eb";
            ctx.font = "11px Arial";
            ctx.textBaseline = "middle";
            ctx.fillText(point.price.toFixed(1), x + 4, y + state.rowHeight / 2);
          }
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.beginPath();

      for (let row = 0; row <= symbols.length; row++) {
        const y = state.topAxisHeight + row * state.rowHeight;
        ctx.moveTo(state.leftAxisWidth, y);
        ctx.lineTo(width, y);
      }

      for (let col = startCol; col <= endCol; col++) {
        const x = state.leftAxisWidth + col * colWidth - state.offsetX;
        ctx.moveTo(x, state.topAxisHeight);
        ctx.lineTo(x, state.topAxisHeight + symbols.length * state.rowHeight);
      }

      ctx.stroke();
    }

    function getCellAt(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      if (x < state.leftAxisWidth || y < state.topAxisHeight) return null;

      const colWidth = getColumnWidth();
      const col = Math.floor((x - state.leftAxisWidth + state.offsetX) / colWidth);
      const row = Math.floor((y - state.topAxisHeight) / state.rowHeight);

      if (
        row < 0 || row >= symbols.length ||
        col < 0 || col >= state.data.length
      ) {
        return null;
      }

      const snapshot = state.data[col];
      const point = snapshot.values[row];

      return {
        row,
        col,
        x: state.leftAxisWidth + col * colWidth - state.offsetX,
        y: state.topAxisHeight + row * state.rowHeight,
        width: colWidth,
        height: state.rowHeight,
        symbol: point.symbol,
        price: point.price,
        changePct: point.changePct,
        timestamp: snapshot.timestamp
      };
    }

    function drawHover() {
      if (!state.hoveredCell) return;

      const c = state.hoveredCell;
      ctx.strokeStyle = "#f8fafc";
      ctx.lineWidth = 2;
      ctx.strokeRect(c.x + 1, c.y + 1, c.width - 2, c.height - 2);
      ctx.lineWidth = 1;
    }

    function updateTooltip(cell, clientX, clientY) {
      if (!cell) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = `${clientX}px`;
      tooltip.style.top = `${clientY}px`;
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong></div>
        <div>Price: ${cell.price.toFixed(2)}</div>
        <div>Change: ${cell.changePct.toFixed(2)}%</div>
        <div>Time: ${formatTime(cell.timestamp)}</div>
      `;
    }

    canvas.addEventListener("mousemove", (e) => {
      if (state.dragging) {
        const dx = e.clientX - state.lastMouseX;
        state.lastMouseX = e.clientX;
        state.offsetX = clamp(state.offsetX - dx, 0, getMaxOffsetX());
        draw();
        return;
      }

      const cell = getCellAt(e.clientX, e.clientY);
      state.hoveredCell = cell;
      updateTooltip(cell, e.clientX, e.clientY);
      draw();
    });

    canvas.addEventListener("mouseleave", () => {
      state.hoveredCell = null;
      tooltip.style.display = "none";
      draw();
    });

    canvas.addEventListener("mousedown", (e) => {
      state.dragging = true;
      state.lastMouseX = e.clientX;
      state.lastMouseY = e.clientY;
      canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      canvas.classList.remove("dragging");
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const gridX = mouseX - state.leftAxisWidth;
      if (gridX < 0) return;

      const oldColWidth = getColumnWidth();
      const worldX = state.offsetX + gridX;

      const zoomFactor = e.deltaY < 0 ? 1.15 : 0.87;
      state.scaleX = clamp(state.scaleX * zoomFactor, state.minScaleX, state.maxScaleX);

      const newColWidth = getColumnWidth();
      state.offsetX = (worldX * newColWidth / oldColWidth) - gridX;
      state.offsetX = clamp(state.offsetX, 0, getMaxOffsetX());

      draw();
    }, { passive: false });

    resetViewBtn.addEventListener("click", resetView);

    toggleStreamBtn.addEventListener("click", () => {
      state.streamActive = !state.streamActive;
      toggleStreamBtn.textContent = state.streamActive ? "Pause Stream" : "Resume Stream";
      statusText.textContent = state.streamActive
        ? "Streaming live updates..."
        : "Stream paused";
    });

    function tick() {
      if (state.streamActive) {
        const wasNearRightEdge = Math.abs(state.offsetX - getMaxOffsetX()) < 24;

        generateSnapshot();

        if (wasNearRightEdge) {
          state.offsetX = getMaxOffsetX();
        } else {
          state.offsetX = clamp(state.offsetX, 0, getMaxOffsetX());
        }

        draw();
      }
    }

    initBasePrices();

    for (let i = 0; i < 60; i++) {
      generateSnapshot();
    }

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    resetView();
    setInterval(tick, 1000);
  </script>
</body>
</html>
```

