      display: none;
      z-index: 10;
      box-shadow: 0 4px 14px rgba(0,0,0,0.35);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <div><strong>Stock Price Heatmap</strong></div>
      <div>Wheel: zoom</div>
      <div>Drag: pan</div>
      <div class="legend">
        <span>-5%</span>
        <div class="legend-bar"></div>
        <span>+5%</span>
      </div>
    </div>

    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('canvasWrap');
    const tooltip = document.getElementById('tooltip');

    const state = {
      symbols: [],
      times: [],
      data: [],
      cellWidth: 60,
      cellHeight: 28,
      minCellWidth: 20,
      maxCellWidth: 180,
      minCellHeight: 16,
      maxCellHeight: 60,
      offsetX: 120,
      offsetY: 40,
      dragging: false,
      lastX: 0,
      lastY: 0,
      hoverCell: null
    };

    function generateSymbols(count) {
      const base = ['AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA', 'NVDA', 'META', 'NFLX', 'AMD', 'INTC'];
      const result = [];
      for (let i = 0; i < count; i++) {
        result.push(base[i % base.length] + (i >= base.length ? i : ''));
      }
      return result;
    }

    function generateTimes(count) {
      const result = [];
      const now = new Date();
      for (let i = count - 1; i >= 0; i--) {
        const d = new Date(now.getTime() - i * 60000);
        result.push(
          d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        );
      }
      return result;
    }

    function initData(rows, cols) {
      state.symbols = generateSymbols(rows);
      state.times = generateTimes(cols);
      state.data = Array.from({ length: rows }, () =>
        Array.from({ length: cols }, () => ({
          price: 100 + Math.random() * 200,
          changePct: (Math.random() - 0.5) * 6
        }))
      );
    }

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function colorForChange(change) {
      const clamped = clamp(change, -5, 5);

      if (clamped < 0) {
        const t = (clamped + 5) / 5;
        return lerpColor([127, 29, 29], [239, 68, 68], t);
      } else {
        const t = clamped / 5;
        return lerpColor([34, 197, 94], [20, 83, 45], t);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r}, ${g}, ${b2})`;
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      drawGrid(width, height);
      drawLabels(width, height);
    }

    function drawGrid(width, height) {
      const rows = state.symbols.length;
      const cols = state.times.length;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = state.offsetX + c * state.cellWidth;
          const y = state.offsetY + r * state.cellHeight;

          if (
            x + state.cellWidth < 0 ||
            y + state.cellHeight < 0 ||
            x > width ||
            y > height
          ) continue;

          const cell = state.data[r][c];
          ctx.fillStyle = colorForChange(cell.changePct);
          ctx.fillRect(x, y, state.cellWidth - 1, state.cellHeight - 1);

          if (
            state.hoverCell &&
            state.hoverCell.row === r &&
            state.hoverCell.col === c
          ) {
            ctx.strokeStyle = '#f8fafc';
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, state.cellWidth - 3, state.cellHeight - 3);
          }

          if (state.cellWidth > 45 && state.cellHeight > 20) {
            ctx.fillStyle = 'rgba(255,255,255,0.9)';
            ctx.font = '12px Arial';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(
              cell.changePct.toFixed(2) + '%',
              x + state.cellWidth / 2,
              y + state.cellHeight / 2
            );
          }
        }
      }
    }

    function drawLabels(width, height) {
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px Arial';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';

      for (let r = 0; r < state.symbols.length; r++) {
        const y = state.offsetY + r * state.cellHeight + state.cellHeight / 2;
        if (y < 0 || y > height) continue;
        ctx.fillText(state.symbols[r], 10, y);
      }

      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      for (let c = 0; c < state.times.length; c++) {
        const x = state.offsetX + c * state.cellWidth + state.cellWidth / 2;
        if (x < 0 || x > width) continue;
        ctx.fillText(state.times[c], x, 8);
      }
    }

    function getCellAt(px, py) {
      const col = Math.floor((px - state.offsetX) / state.cellWidth);
      const row = Math.floor((py - state.offsetY) / state.cellHeight);

      if (
        row >= 0 &&
        row < state.symbols.length &&
        col >= 0 &&
        col < state.times.length
      ) {
        return { row, col };
      }
      return null;
    }

    function updateTooltip(cell, clientX, clientY) {
      if (!cell) {
        tooltip.style.display = 'none';
        return;
      }

      const item = state.data[cell.row][cell.col];
      tooltip.style.display = 'block';
      tooltip.style.left = clientX + 'px';
      tooltip.style.top = clientY + 'px';
      tooltip.innerHTML = `
        <div><strong>${state.symbols[cell.row]}</strong></div>
        <div>Time: ${state.times[cell.col]}</div>
        <div>Price: $${item.price.toFixed(2)}</div>
        <div>Change: ${item.changePct.toFixed(2)}%</div>
      `;
    }

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      canvas.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      if (state.dragging) {
        state.offsetX += e.clientX - state.lastX;
        state.offsetY += e.clientY - state.lastY;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
        draw();
        return;
      }

      const cell = getCellAt(x, y);
      state.hoverCell = cell;
      updateTooltip(cell, x, y);
      draw();
    });

    canvas.addEventListener('mouseleave', () => {
      state.hoverCell = null;
      tooltip.style.display = 'none';
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldCellWidth = state.cellWidth;
      const oldCellHeight = state.cellHeight;

      const newCellWidth = clamp(state.cellWidth * zoomFactor, state.minCellWidth, state.maxCellWidth);
      const newCellHeight = clamp(state.cellHeight * zoomFactor, state.minCellHeight, state.maxCellHeight);

      const scaleX = newCellWidth / oldCellWidth;
      const scaleY = newCellHeight / oldCellHeight;

      state.offsetX = mouseX - (mouseX - state.offsetX) * scaleX;
      state.offsetY = mouseY - (mouseY - state.offsetY) * scaleY;
      state.cellWidth = newCellWidth;
      state.cellHeight = newCellHeight;

      draw();
    }, { passive: false });

    function tickData() {
      for (let r = 0; r < state.data.length; r++) {
        for (let c = 0; c < state.data[r].length; c++) {
          const drift = (Math.random() - 0.5) * 0.6;
          state.data[r][c].changePct = clamp(state.data[r][c].changePct + drift, -5, 5);
          state.data[r][c].price = Math.max(1, state.data[r][c].price * (1 + drift / 100));
        }
      }

      const latestTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      state.times.shift();
      state.times.push(latestTime);

      for (let r = 0; r < state.data.length; r++) {
        state.data[r].shift();
        const prev = state.data[r][state.data[r].length - 1];
        const drift = (Math.random() - 0.5) * 2;
        const newPrice = Math.max(1, prev.price * (1 + drift / 100));
        state.data[r].push({
          price: newPrice,
          changePct: clamp(prev.changePct + drift, -5, 5)
        });
      }

      draw();
    }

    initData(25, 40);
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    setInterval(tickData, 1000);
  </script>
</body>
</html>
