<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetViewBtn">Reset View</button>
      <button id="pauseBtn">Pause</button>
      <span id="status">Streaming: ON</span>
    </div>

    <div class="container" id="container">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div>Price Intensity</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>Low</span>
          <span>Mid</span>
          <span>High</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, container, tooltip) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.container = container;
        this.tooltip = tooltip;

        this.dpr = window.devicePixelRatio || 1;

        this.symbols = [
          'AAPL', 'MSFT', 'GOOG', 'AMZN', 'TSLA',
          'NVDA', 'META', 'NFLX', 'AMD', 'INTC',
          'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA'
        ];

        this.timeSteps = 120;
        this.data = [];
        this.timestamps = [];

        this.margin = {
          top: 30,
          right: 20,
          bottom: 40,
          left: 80
        };

        this.view = {
          scaleX: 1,
          scaleY: 1,
          offsetX: 0,
          offsetY: 0
        };

        this.isDragging = false;
        this.lastMouse = { x: 0, y: 0 };
        this.hoveredCell = null;
        this.streaming = true;

        this.initData();
        this.resize();
        this.bindEvents();
        this.startStream();
        this.render();
      }

      initData() {
        const now = Date.now();
        for (let t = 0; t < this.timeSteps; t++) {
          this.timestamps.push(now - (this.timeSteps - t) * 1000);
        }

        for (let row = 0; row < this.symbols.length; row++) {
          const series = [];
          let base = 100 + Math.random() * 200;
          for (let col = 0; col < this.timeSteps; col++) {
            base += (Math.random() - 0.5) * 4;
            series.push({
              price: Math.max(1, base),
              change: 0
            });
          }
          this.data.push(series);
        }

        this.computeChanges();
      }

      computeChanges() {
        for (let row = 0; row < this.data.length; row++) {
          for (let col = 0; col < this.data[row].length; col++) {
            if (col === 0) {
              this.data[row][col].change = 0;
            } else {
              const prev = this.data[row][col - 1].price;
              const curr = this.data[row][col].price;
              this.data[row][col].change = ((curr - prev) / prev) * 100;
            }
          }
        }
      }

      startStream() {
        this.interval = setInterval(() => {
          if (!this.streaming) return;
          this.pushTick();
          this.render();
        }, 1000);
      }

      pushTick() {
        this.timestamps.push(Date.now());
        this.timestamps.shift();

        for (let row = 0; row < this.data.length; row++) {
          const series = this.data[row];
          const last = series[series.length - 1].price;
          const next = Math.max(1, last + (Math.random() - 0.5) * 6);
          series.push({
            price: next,
            change: ((next - last) / last) * 100
          });
          series.shift();
        }
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const rect = this.canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

          const prevScaleX = this.view.scaleX;
          const prevScaleY = this.view.scaleY;

          this.view.scaleX = Math.max(1, Math.min(8, this.view.scaleX * zoomFactor));
          this.view.scaleY = Math.max(1, Math.min(6, this.view.scaleY * zoomFactor));

          this.view.offsetX = mouseX - ((mouseX - this.view.offsetX) / prevScaleX) * this.view.scaleX;
          this.view.offsetY = mouseY - ((mouseY - this.view.offsetY) / prevScaleY) * this.view.scaleY;

          this.clampView();
          this.render();
        }, { passive: false });

        this.canvas.addEventListener('mousedown', (e) => {
          this.isDragging = true;
          this.lastMouse = { x: e.clientX, y: e.clientY };
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.isDragging) {
            const dx = e.clientX - this.lastMouse.x;
            const dy = e.clientY - this.lastMouse.y;
            this.lastMouse = { x: e.clientX, y: e.clientY };

            this.view.offsetX += dx;
            this.view.offsetY += dy;
            this.clampView();
            this.render();
          } else {
            this.updateHover(x, y);
          }
        });

        window.addEventListener('mouseup', () => {
          this.isDragging = false;
          this.canvas.classList.remove('dragging');
        });

        document.getElementById('resetViewBtn').addEventListener('click', () => {
          this.view = { scaleX: 1, scaleY: 1, offsetX: 0, offsetY: 0 };
          this.render();
        });

        document.getElementById('pauseBtn').addEventListener('click', (e) => {
          this.streaming = !this.streaming;
          e.target.textContent = this.streaming ? 'Pause' : 'Resume';
          document.getElementById('status').textContent = this.streaming ? 'Streaming: ON' : 'Streaming: OFF';
        });
      }

      resize() {
        const rect = this.container.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      clampView() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        const plotWidth = width - this.margin.left - this.margin.right;
        const plotHeight = height - this.margin.top - this.margin.bottom;

        const scaledWidth = plotWidth * this.view.scaleX;
        const scaledHeight = plotHeight * this.view.scaleY;

        const minOffsetX = width - this.margin.right - scaledWidth;
        const maxOffsetX = this.margin.left;

        const minOffsetY = height - this.margin.bottom - scaledHeight;
        const maxOffsetY = this.margin.top;

        this.view.offsetX = Math.min(maxOffsetX, Math.max(minOffsetX, this.view.offsetX));
        this.view.offsetY = Math.min(maxOffsetY, Math.max(minOffsetY, this.view.offsetY));
      }

      getColor(change) {
        const normalized = Math.max(-2, Math.min(2, change));
        const t = (normalized + 2) / 4;

        if (t < 0.5) {
          return this.lerpColor([59, 130, 246], [34, 197, 94], t / 0.5);
        } else if (t < 0.75) {
          return this.lerpColor([34, 197, 94], [245, 158, 11], (t - 0.5) / 0.25);
        } else {
          return this.lerpColor([245, 158, 11], [239, 68, 68], (t - 0.75) / 0.25);
        }
      }

      lerpColor(a, b, t) {
        const r = Math.round(a[0] + (b[0] - a[0]) * t);
        const g = Math.round(a[1] + (b[1] - a[1]) * t);
        const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
        return `rgb(${r}, ${g}, ${b2})`;
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, width, height);

        const plotX = this.margin.left;
        const plotY = this.margin.top;
        const plotWidth = width - this.margin.left - this.margin.right;
        const plotHeight = height - this.margin.top - this.margin.bottom;

        ctx.save();
        ctx.beginPath();
        ctx.rect(plotX, plotY, plotWidth, plotHeight);
        ctx.clip();

        const scaledWidth = plotWidth * this.view.scaleX;
        const scaledHeight = plotHeight * this.view.scaleY;

        const cellWidth = scaledWidth / this.timeSteps;
        const cellHeight = scaledHeight / this.symbols.length;

        const startX = this.view.offsetX || plotX;
        const startY = this.view.offsetY || plotY;

        for (let row = 0; row < this.symbols.length; row++) {
          for (let col = 0; col < this.timeSteps; col++) {
            const x = startX + col * cellWidth;
            const y = startY + row * cellHeight;

            if (
              x + cellWidth < plotX || x > plotX + plotWidth ||
              y + cellHeight < plotY || y > plotY + plotHeight
            ) {
              continue;
            }

            const point = this.data[row][col];
            ctx.fillStyle = this.getColor(point.change);
            ctx.fillRect(x, y, Math.ceil(cellWidth), Math.ceil(cellHeight));
          }
        }

        ctx.restore();

        this.drawAxes(width, height, plotX, plotY, plotWidth, plotHeight, startX, startY, cellWidth, cellHeight);
      }

      drawAxes(width, height, plotX, plotY, plotWidth, plotHeight, startX, startY, cellWidth, cellHeight) {
        const ctx = this.ctx;

        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(plotX, plotY);
        ctx.lineTo(plotX, plotY + plotHeight);
        ctx.lineTo(plotX + plotWidth, plotY + plotHeight);
        ctx.stroke();

        ctx.fillStyle = '#cbd5e1';
        ctx.font = '12px Arial';

        for (let row = 0; row < this.symbols.length; row++) {
          const y = startY + row * cellHeight + cellHeight / 2;
          if (y < plotY || y > plotY + plotHeight) continue;
          ctx.fillText(this.symbols[row], 10, y + 4);
        }

        const step = Math.max(1, Math.floor(this.timeSteps / 8));
        for (let col = 0; col < this.timeSteps; col += step) {
          const x = startX + col * cellWidth;
          if (x < plotX || x > plotX + plotWidth) continue;

          const ts = new Date(this.timestamps[col]);
          const label = ts.toLocaleTimeString([], {
            minute: '2-digit',
            second: '2-digit'
          });

          ctx.save();
          ctx.translate(x + 4, plotY + plotHeight + 14);
          ctx.rotate(-0.4);
          ctx.fillText(label, 0, 0);
          ctx.restore();
        }
      }

      updateHover(mouseX, mouseY) {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        const plotX = this.margin.left;
        const plotY = this.margin.top;
        const plotWidth = width - this.margin.left - this.margin.right;
        const plotHeight = height - this.margin.top - this.margin.bottom;

        const scaledWidth = plotWidth * this.view.scaleX;
        const scaledHeight = plotHeight * this.view.scaleY;

        const cellWidth = scaledWidth / this.timeSteps;
        const cellHeight = scaledHeight / this.symbols.length;

        const startX = this.view.offsetX || plotX;
        const startY = this.view.offsetY || plotY;

        if (
          mouseX < plotX || mouseX > plotX + plotWidth ||
          mouseY < plotY || mouseY > plotY + plotHeight
        ) {
          this.tooltip.style.display = 'none';
          return;
        }

        const col = Math.floor((mouseX - startX) / cellWidth);
        const row = Math.floor((mouseY - startY) / cellHeight);

        if (
          row >= 0 && row < this.symbols.length &&
          col >= 0 && col < this.timeSteps
        ) {
          const point = this.data[row][col];
          const ts = new Date(this.timestamps[col]);

          this.tooltip.style.display = 'block';
          this.tooltip.style.left = mouseX + 'px';
          this.tooltip.style.top = mouseY + 'px';
          this.tooltip.innerHTML = `
            <div><strong>${this.symbols[row]}</strong></div>
            <div>Price: $${point.price.toFixed(2)}</div>
            <div>Change: ${point.change.toFixed(2)}%</div>
            <div>Time: ${ts.toLocaleTimeString()}</div>
          `;
        } else {
          this.tooltip.style.display = 'none';
        }
      }
    }

    const canvas = document.getElementById('heatmap');
    const container = document.getElementById('container');
    const tooltip = document.getElementById('tooltip');

    new StockHeatmap(canvas, container, tooltip);
  </script>
</body>
</html>
```

