<body>
  <div class="app">
    <div class="toolbar">
      <h1>Real-Time Stock Heatmap</h1>
      <div class="stat" id="status">Streaming: simulated</div>
      <div class="stat" id="zoomStat">Zoom: 1.00x</div>
      <div class="stat" id="panStat">Pan: 0, 0</div>
      <button id="resetViewBtn">Reset View</button>
      <button id="toggleStreamBtn">Pause Stream</button>
    </div>

    <div class="container" id="container">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>

      <div class="legend">
        <div>Price Change (%)</div>
        <div class="legend-bar"></div>
        <div class="legend-labels">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, container, tooltip) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.container = container;
        this.tooltip = tooltip;

        this.dpr = window.devicePixelRatio || 1;

        this.symbols = [
          'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA',
          'META', 'NVDA', 'NFLX', 'AMD', 'INTC',
          'ORCL', 'CRM', 'UBER', 'SHOP', 'BABA',
          'JPM', 'GS', 'V', 'MA', 'PYPL'
        ];

        this.timeSteps = 120;
        this.data = [];
        this.basePrices = {};

        this.layout = {
          leftAxisWidth: 90,
          bottomAxisHeight: 36,
          topPadding: 10,
          rightPadding: 10
        };

        this.view = {
          scaleX: 1,
          scaleY: 1,
          offsetX: 0,
          offsetY: 0,
          minScale: 0.5,
          maxScale: 8
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          lastY: 0,
          hoverCell: null
        };

        this.streaming = true;
        this.frameRequest = null;

        this.initData();
        this.attachEvents();
        this.resize();
        this.startStream();
        this.render();
      }

      initData() {
        const now = Date.now();

        for (const symbol of this.symbols) {
          this.basePrices[symbol] = 100 + Math.random() * 300;
        }

        this.data = Array.from({ length: this.symbols.length }, (_, row) => {
          let current = this.basePrices[this.symbols[row]];
          return Array.from({ length: this.timeSteps }, (_, col) => {
            current *= 1 + (Math.random() - 0.5) * 0.01;
            return {
              timestamp: now - (this.timeSteps - col) * 1000,
              price: current,
              changePct: ((current - this.basePrices[this.symbols[row]]) / this.basePrices[this.symbols[row]]) * 100
            };
          });
        });
      }

      attachEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('wheel', (e) => this.onWheel(e), { passive: false });
        this.canvas.addEventListener('mousedown', (e) => this.onMouseDown(e));
        window.addEventListener('mousemove', (e) => this.onMouseMove(e));
        window.addEventListener('mouseup', () => this.onMouseUp());
        this.canvas.addEventListener('mouseleave', () => this.hideTooltip());

        document.getElementById('resetViewBtn').addEventListener('click', () => {
          this.view.scaleX = 1;
          this.view.scaleY = 1;
          this.view.offsetX = 0;
          this.view.offsetY = 0;
          this.updateStats();
          this.render();
        });

        document.getElementById('toggleStreamBtn').addEventListener('click', (e) => {
          this.streaming = !this.streaming;
          e.target.textContent = this.streaming ? 'Pause Stream' : 'Resume Stream';
          document.getElementById('status').textContent =
            `Streaming: ${this.streaming ? 'simulated' : 'paused'}`;
          if (this.streaming) this.startStream();
        });
      }

      resize() {
        const rect = this.container.getBoundingClientRect();
        this.canvas.width = rect.width * this.dpr;
        this.canvas.height = rect.height * this.dpr;
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      startStream() {
        if (this.streamInterval) clearInterval(this.streamInterval);

        this.streamInterval = setInterval(() => {
          if (!this.streaming) return;
          this.pushTick();
          this.render();
        }, 1000);
      }

      pushTick() {
        const now = Date.now();

        for (let row = 0; row < this.symbols.length; row++) {
          const symbol = this.symbols[row];
          const series = this.data[row];
          const last = series[series.length - 1];
          const drift = (Math.random() - 0.5) * 0.02;
          const nextPrice = Math.max(1, last.price * (1 + drift));
          const changePct = ((nextPrice - this.basePrices[symbol]) / this.basePrices[symbol]) * 100;

          series.push({
            timestamp: now,
            price: nextPrice,
            changePct
          });

          if (series.length > this.timeSteps) {
            series.shift();
          }
        }
      }

      onWheel(e) {
        e.preventDefault();

        const rect = this.canvas.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
        const prevScaleX = this.view.scaleX;
        const prevScaleY = this.view.scaleY;

        this.view.scaleX = this.clamp(
          this.view.scaleX * zoomFactor,
          this.view.minScale,
          this.view.maxScale
        );
        this.view.scaleY = this.clamp(
          this.view.scaleY * zoomFactor,
          this.view.minScale,
          this.view.maxScale
        );

        const scaleRatioX = this.view.scaleX / prevScaleX;
        const scaleRatioY = this.view.scaleY / prevScaleY;

        this.view.offsetX = mouseX - (mouseX - this.view.offsetX) * scaleRatioX;
        this.view.offsetY = mouseY - (mouseY - this.view.offsetY) * scaleRatioY;

        this.updateStats();
        this.render();
      }

      onMouseDown(e) {
        this.interaction.dragging = true;
        this.interaction.lastX = e.clientX;
        this.interaction.lastY = e.clientY;
        this.canvas.classList.add('dragging');
      }

      onMouseMove(e) {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        if (this.interaction.dragging) {
          const dx = e.clientX - this.interaction.lastX;
          const dy = e.clientY - this.interaction.lastY;
          this.view.offsetX += dx;
          this.view.offsetY += dy;
          this.interaction.lastX = e.clientX;
          this.interaction.lastY = e.clientY;
          this.updateStats();
          this.render();
          return;
        }

        const cell = this.getCellAt(x, y);
        if (cell) {
          this.showTooltip(x, y, cell);
        } else {
          this.hideTooltip();
        }
      }

      onMouseUp() {
        this.interaction.dragging = false;
        this.canvas.classList.remove('dragging');
      }

      getPlotArea() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        return {
          x: this.layout.leftAxisWidth,
          y: this.layout.topPadding,
          width: width - this.layout.leftAxisWidth - this.layout.rightPadding,
          height: height - this.layout.bottomAxisHeight - this.layout.topPadding
        };
      }

      getCellMetrics() {
        const plot = this.getPlotArea();
        return {
          cellWidth: (plot.width / this.timeSteps) * this.view.scaleX,
          cellHeight: (plot.height / this.symbols.length) * this.view.scaleY
        };
      }

      getCellAt(px, py) {
        const plot = this.getPlotArea();
        const { cellWidth, cellHeight } = this.getCellMetrics();

        const localX = px - plot.x - this.view.offsetX;
        const localY = py - plot.y - this.view.offsetY;

        if (localX < 0 || localY < 0) return null;

        const col = Math.floor(localX / cellWidth);
        const row = Math.floor(localY / cellHeight);

        if (
          row >= 0 && row < this.symbols.length &&
          col >= 0 && col < this.timeSteps
        ) {
          const point = this.data[row][col];
          return {
            row,
            col,
            symbol: this.symbols[row],
            ...point
          };
        }

        return null;
      }

      showTooltip(x, y, cell) {
        const date = new Date(cell.timestamp);
        this.tooltip.style.display = 'block';
        this.tooltip.style.left = x + 'px';
        this.tooltip.style.top = y + 'px';
        this.tooltip.innerHTML = `
          <div><strong>${cell.symbol}</strong></div>
          <div>Price: $${cell.price.toFixed(2)}</div>
          <div>Change: ${cell.changePct.toFixed(2)}%</div>
          <div>Time: ${date.toLocaleTimeString()}</div>
        `;
      }

      hideTooltip() {
        this.tooltip.style.display = 'none';
      }

      clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      getColor(changePct) {
        const clamped = this.clamp(changePct, -5, 5);
        const t = (clamped + 5) / 10;

        if (t < 0.5) {
          const k = t / 0.5;
          return this.rgb(
            Math.round(180 + (80 - 180) * k),
            Math.round(35 + (80 - 35) * k),
            Math.round(24 + (80 - 24) * k)
          );
        } else {
          const k = (t - 0.5) / 0.5;
          return this.rgb(
            Math.round(80 + (22 - 80) * k),
            Math.round(80 + (163 - 80) * k),
            Math.round(80 + (74 - 80) * k)
          );
        }
      }

      rgb(r, g, b) {
        return `rgb(${r}, ${g}, ${b})`;
      }

      updateStats() {
        document.getElementById('zoomStat').textContent =
          `Zoom: ${this.view.scaleX.toFixed(2)}x`;
        document.getElementById('panStat').textContent =
          `Pan: ${Math.round(this.view.offsetX)}, ${Math.round(this.view.offsetY)}`;
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        const plot = this.getPlotArea();
        const { cellWidth, cellHeight } = this.getCellMetrics();

        ctx.clearRect(0, 0, width, height);

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, width, height);

        ctx.save();

        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        for (let row = 0; row < this.symbols.length; row++) {
          for (let col = 0; col < this.timeSteps; col++) {
            const point = this.data[row][col];
            const x = plot.x + this.view.offsetX + col * cellWidth;
            const y = plot.y + this.view.offsetY + row * cellHeight;

            if (
              x + cellWidth < plot.x || x > plot.x + plot.width ||
              y + cellHeight < plot.y || y > plot.y + plot.height
            ) {
              continue;
            }

            ctx.fillStyle = this.getColor(point.changePct);
            ctx.fillRect(x, y, Math.ceil(cellWidth), Math.ceil(cellHeight));

            ctx.strokeStyle = 'rgba(15, 23, 42, 0.35)';
            ctx.strokeRect(x, y, Math.ceil(cellWidth), Math.ceil(cellHeight));
          }
        }

        ctx.restore();

        this.drawAxes(plot, cellWidth, cellHeight);
      }

      drawAxes(plot, cellWidth, cellHeight) {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.strokeStyle = '#334155';
        ctx.fillStyle = '#94a3b8';
        ctx.lineWidth = 1;
        ctx.font = '12px sans-serif';

        ctx.beginPath();
        ctx.moveTo(plot.x, plot.y);
        ctx.lineTo(plot.x, plot.y + plot.height);
        ctx.lineTo(plot.x + plot.width, plot.y + plot.height);
        ctx.stroke();

        for (let row = 0; row < this.symbols.length; row++) {
          const y = plot.y + this.view.offsetY + row * cellHeight + cellHeight / 2;
          if (y < plot.y || y > plot.y + plot.height) continue;

          ctx.fillStyle = '#cbd5e1';
          ctx.textAlign = 'right';
          ctx.textBaseline = 'middle';
          ctx.fillText(this.symbols[row], plot.x - 8, y);
        }

        const tickCount = 8;
        for (let i = 0; i <= tickCount; i++) {
          const col = Math.floor((i / tickCount) * (this.timeSteps - 1));
          const x = plot.x + this.view.offsetX + col * cellWidth;

          if (x < plot.x || x > plot.x + plot.width) continue;

          const point = this.data[0][col];
          const date = new Date(point.timestamp);

          ctx.strokeStyle = '#1f2937';
          ctx.beginPath();
          ctx.moveTo(x, plot.y);
          ctx.lineTo(x, plot.y + plot.height);
          ctx.stroke();

          ctx.fillStyle = '#94a3b8';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'top';
          ctx.fillText(date.toLocaleTimeString(), x, plot.y + plot.height + 8);
        }

        for (let row = 0; row <= this.symbols.length; row++) {
          const y = plot.y + this.view.offsetY + row * cellHeight;
          if (y < plot.y || y > plot.y + plot.height) continue;

          ctx.strokeStyle = '#1f2937';
          ctx.beginPath();
          ctx.moveTo(plot.x, y);
          ctx.lineTo(plot.x + plot.width, y);
          ctx.stroke();
        }
      }
    }

    const canvas = document.getElementById('heatmap');
    const container = document.getElementById('container');
    const tooltip = document.getElementById('tooltip');

    const heatmap = new StockHeatmap(canvas, container, tooltip);
  </script>
</body>
</html>
```

