  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <style>
    :root {
      --bg: #0b1020;
      --panel: #121933;
      --grid: #1f2a4d;
      --text: #dbe4ff;
      --muted: #8ea0d0;
      --border: #2b3763;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, system-ui, sans-serif;
    }

    .app {
      display: grid;
      grid-template-rows: auto 1fr;
      height: 100vh;
    }

    .toolbar {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 16px;
      background: var(--panel);
      border-bottom: 1px solid var(--border);
      flex-wrap: wrap;
    }

    .toolbar h1 {
      font-size: 16px;
      margin: 0 16px 0 0;
    }

    .toolbar .group {
      display: flex;
      align-items: center;
      gap: 8px;
      color: var(--muted);
      font-size: 13px;
    }

    .toolbar button, .toolbar select {
      background: #1a2345;
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 10px;
      cursor: pointer;
    }

    .toolbar button:hover, .toolbar select:hover {
      border-color: #4c5f9f;
    }

    .chart-wrap {
      position: relative;
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(8, 12, 24, 0.95);
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      min-width: 160px;
      transform: translate(10px, 10px);
      white-space: nowrap;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      display: none;
      z-index: 10;
    }

    .legend {
      position: absolute;
      right: 12px;
      bottom: 12px;
      background: rgba(18, 25, 51, 0.9);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px;
      width: 180px;
      font-size: 12px;
    }

    .legend-bar {
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(
        to right,
        rgb(180, 40, 40),
        rgb(80, 80, 80),
        rgb(40, 180, 90)
      );
      margin: 6px 0 4px;
    }

    .legend-scale {
      display: flex;
      justify-content: space-between;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Realtime Stock Price Heatmap</h1>

      <div class="group">
        <label for="speed">Update speed</label>
        <select id="speed">
          <option value="1000">1s</option>
          <option value="500" selected>500ms</option>
          <option value="200">200ms</option>
        </select>
      </div>

      <div class="group">
        <label for="windowSize">Time window</label>
        <select id="windowSize">
          <option value="60">60</option>
          <option value="120" selected>120</option>
          <option value="240">240</option>
        </select>
      </div>

      <button id="resetView">Reset View</button>
      <button id="pauseBtn">Pause</button>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div><strong>Price Change %</strong></div>
        <div class="legend-bar"></div>
        <div class="legend-scale">
          <span>-5%</span>
          <span>0%</span>
          <span>+5%</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    class StockHeatmap {
      constructor(canvas, tooltip, options = {}) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.tooltip = tooltip;

        this.stocks = options.stocks || [];
        this.maxPoints = options.maxPoints || 120;

        this.margin = { top: 30, right: 20, bottom: 40, left: 90 };

        this.data = [];
        this.timestamps = [];

        this.view = {
          scaleX: 1,
          scaleY: 1,
          offsetX: 0,
          offsetY: 0
        };

        this.interaction = {
          dragging: false,
          lastX: 0,
          lastY: 0,
          hoverCell: null
        };

        this.colorRange = {
          min: -5,
          max: 5
        };

        this.dpr = Math.max(1, window.devicePixelRatio || 1);

        this.initData();
        this.bindEvents();
        this.resize();
        this.render();
      }

      initData() {
        const now = Date.now();
        this.timestamps = [];
        this.data = this.stocks.map((stock, rowIndex) => {
          const series = [];
          let price = stock.basePrice;
          for (let i = 0; i < this.maxPoints; i++) {
            const ts = now - (this.maxPoints - 1 - i) * 1000;
            if (rowIndex === 0) this.timestamps.push(ts);

            const drift = (Math.random() - 0.5) * 0.8;
            price = Math.max(1, price + drift);
            const changePct = ((price - stock.basePrice) / stock.basePrice) * 100;

            series.push({
              ts,
              price,
              changePct
            });
          }
          return series;
        });
      }

      setMaxPoints(next) {
        this.maxPoints = next;
        this.initData();
        this.resetView();
        this.render();
      }

      addDataPoint() {
        const ts = Date.now();
        this.timestamps.push(ts);
        if (this.timestamps.length > this.maxPoints) {
          this.timestamps.shift();
        }

        this.data.forEach((series, rowIndex) => {
          const prev = series[series.length - 1];
          const stock = this.stocks[rowIndex];

          const volatility = stock.volatility ?? 0.6;
          const drift = (Math.random() - 0.5) * volatility;
          const price = Math.max(1, prev.price + drift);
          const changePct = ((price - stock.basePrice) / stock.basePrice) * 100;

          series.push({ ts, price, changePct });
          if (series.length > this.maxPoints) {
            series.shift();
          }
        });

        this.render();
      }

      bindEvents() {
        window.addEventListener('resize', () => this.resize());

        this.canvas.addEventListener('mousedown', (e) => {
          this.interaction.dragging = true;
          this.interaction.lastX = e.clientX;
          this.interaction.lastY = e.clientY;
          this.canvas.classList.add('dragging');
        });

        window.addEventListener('mouseup', () => {
          this.interaction.dragging = false;
          this.canvas.classList.remove('dragging');
        });

        window.addEventListener('mousemove', (e) => {
          const rect = this.canvas.getBoundingClientRect();

          if (this.interaction.dragging) {
            const dx = e.clientX - this.interaction.lastX;
            const dy = e.clientY - this.interaction.lastY;
            this.interaction.lastX = e.clientX;
            this.interaction.lastY = e.clientY;

            this.view.offsetX += dx;
            this.view.offsetY += dy;
            this.clampView();
            this.render();
          }

          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          this.handleHover(x, y, e.clientX - rect.left, e.clientY - rect.top);
        });

        this.canvas.addEventListener('mouseleave', () => {
          this.interaction.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
        });

        this.canvas.addEventListener('wheel', (e) => {
          e.preventDefault();

          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
          const rect = this.canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;

          if (e.shiftKey) {
            this.zoomY(zoomFactor, my);
          } else {
            this.zoomX(zoomFactor, mx);
          }

          this.clampView();
          this.render();
        }, { passive: false });
      }

      resize() {
        const rect = this.canvas.parentElement.getBoundingClientRect();
        this.dpr = Math.max(1, window.devicePixelRatio || 1);
        this.canvas.width = Math.floor(rect.width * this.dpr);
        this.canvas.height = Math.floor(rect.height * this.dpr);
        this.canvas.style.width = rect.width + 'px';
        this.canvas.style.height = rect.height + 'px';
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      resetView() {
        this.view.scaleX = 1;
        this.view.scaleY = 1;
        this.view.offsetX = 0;
        this.view.offsetY = 0;
      }

      zoomX(factor, mouseX) {
        const plot = this.getPlotRect();
        const prevScale = this.view.scaleX;
        const nextScale = Math.min(8, Math.max(1, prevScale * factor));

        const rel = (mouseX - plot.x - this.view.offsetX) / prevScale;
        this.view.scaleX = nextScale;
        this.view.offsetX = mouseX - plot.x - rel * nextScale;
      }

      zoomY(factor, mouseY) {
        const plot = this.getPlotRect();
        const prevScale = this.view.scaleY;
        const nextScale = Math.min(6, Math.max(1, prevScale * factor));

        const rel = (mouseY - plot.y - this.view.offsetY) / prevScale;
        this.view.scaleY = nextScale;
        this.view.offsetY = mouseY - plot.y - rel * nextScale;
      }

      clampView() {
        const plot = this.getPlotRect();

        const contentWidth = plot.width * this.view.scaleX;
        const contentHeight = plot.height * this.view.scaleY;

        const minOffsetX = Math.min(0, plot.width - contentWidth);
        const maxOffsetX = 0;

        const minOffsetY = Math.min(0, plot.height - contentHeight);
        const maxOffsetY = 0;

        this.view.offsetX = Math.max(minOffsetX, Math.min(maxOffsetX, this.view.offsetX));
        this.view.offsetY = Math.max(minOffsetY, Math.min(maxOffsetY, this.view.offsetY));
      }

      getPlotRect() {
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;
        return {
          x: this.margin.left,
          y: this.margin.top,
          width: Math.max(10, width - this.margin.left - this.margin.right),
          height: Math.max(10, height - this.margin.top - this.margin.bottom)
        };
      }

      valueToColor(changePct) {
        const clamped = Math.max(this.colorRange.min, Math.min(this.colorRange.max, changePct));
        const t = (clamped - this.colorRange.min) / (this.colorRange.max - this.colorRange.min);

        let r, g, b;
        if (t < 0.5) {
          const k = t / 0.5;
          r = Math.round(180 + (80 - 180) * k);
          g = Math.round(40 + (80 - 40) * k);
          b = Math.round(40 + (80 - 40) * k);
        } else {
          const k = (t - 0.5) / 0.5;
          r = Math.round(80 + (40 - 80) * k);
          g = Math.round(80 + (180 - 80) * k);
          b = Math.round(80 + (90 - 80) * k);
        }
        return `rgb(${r},${g},${b})`;
      }

      formatTime(ts) {
        const d = new Date(ts);
        return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      }

      handleHover(x, y, clientX, clientY) {
        const plot = this.getPlotRect();

        if (
          x < plot.x || x > plot.x + plot.width ||
          y < plot.y || y > plot.y + plot.height
        ) {
          this.interaction.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
          return;
        }

        const cols = this.timestamps.length;
        const rows = this.stocks.length;

        const cellW = (plot.width / cols) * this.view.scaleX;
        const cellH = (plot.height / rows) * this.view.scaleY;

        const localX = x - plot.x - this.view.offsetX;
        const localY = y - plot.y - this.view.offsetY;

        const col = Math.floor(localX / cellW);
        const row = Math.floor(localY / cellH);

        if (col < 0 || col >= cols || row < 0 || row >= rows) {
          this.interaction.hoverCell = null;
          this.tooltip.style.display = 'none';
          this.render();
          return;
        }

        const point = this.data[row][col];
        const stock = this.stocks[row];

        this.interaction.hoverCell = { row, col };

        this.tooltip.innerHTML = `
          <div><strong>${stock.symbol}</strong></div>
          <div>Time: ${this.formatTime(point.ts)}</div>
          <div>Price: $${point.price.toFixed(2)}</div>
          <div>Change: ${point.changePct.toFixed(2)}%</div>
        `;
        this.tooltip.style.left = `${clientX}px`;
        this.tooltip.style.top = `${clientY}px`;
        this.tooltip.style.display = 'block';

        this.render();
      }

      drawAxes(plot) {
        const ctx = this.ctx;
        ctx.save();

        ctx.strokeStyle = '#3a4a7a';
        ctx.lineWidth = 1;

        ctx.beginPath();
        ctx.moveTo(plot.x, plot.y);
        ctx.lineTo(plot.x, plot.y + plot.height);
        ctx.lineTo(plot.x + plot.width, plot.y + plot.height);
        ctx.stroke();

        ctx.fillStyle = '#8ea0d0';
        ctx.font = '12px sans-serif';
        ctx.textBaseline = 'middle';

        const rows = this.stocks.length;
        const rowH = (plot.height / rows) * this.view.scaleY;

        for (let i = 0; i < rows; i++) {
          const y = plot.y + this.view.offsetY + i * rowH + rowH / 2;
          if (y < plot.y - rowH || y > plot.y + plot.height + rowH) continue;
          ctx.fillText(this.stocks[i].symbol, 10, y);
        }

        const cols = this.timestamps.length;
        const colW = (plot.width / cols) * this.view.scaleX;
        const tickEvery = Math.max(1, Math.ceil(cols / 8));

        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        for (let i = 0; i < cols; i += tickEvery) {
          const x = plot.x + this.view.offsetX + i * colW + colW / 2;
          if (x < plot.x || x > plot.x + plot.width) continue;
          ctx.fillText(this.formatTime(this.timestamps[i]), x, plot.y + plot.height + 8);
        }

        ctx.restore();
      }

      drawGrid(plot) {
        const ctx = this.ctx;
        const rows = this.stocks.length;
        const cols = this.timestamps.length;
        const cellW = (plot.width / cols) * this.view.scaleX;
        const cellH = (plot.height / rows) * this.view.scaleY;

        ctx.save();
        ctx.beginPath();
        ctx.rect(plot.x, plot.y, plot.width, plot.height);
        ctx.clip();

        for (let row = 0; row < rows; row++) {
          for (let col = 0; col < cols; col++) {
            const x = plot.x + this.view.offsetX + col * cellW;
            const y = plot.y + this.view.offsetY + row * cellH;

            if (
              x + cellW < plot.x || x > plot.x + plot.width ||
              y + cellH < plot.y || y > plot.y + plot.height
            ) continue;

            const point = this.data[row][col];
            ctx.fillStyle = this.valueToColor(point.changePct);
            ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));

            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.strokeRect(x, y, Math.ceil(cellW), Math.ceil(cellH));
          }
        }

        if (this.interaction.hoverCell) {
          const { row, col } = this.interaction.hoverCell;
          const x = plot.x + this.view.offsetX + col * cellW;
          const y = plot.y + this.view.offsetY + row * cellH;
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 1, y + 1, Math.max(0, cellW - 2), Math.max(0, cellH - 2));
        }

        ctx.restore();
      }

      render() {
        const ctx = this.ctx;
        const width = this.canvas.width / this.dpr;
        const height = this.canvas.height / this.dpr;

        ctx.clearRect(0, 0, width, height);

        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, width, height);

        const plot = this.getPlotRect();

        ctx.fillStyle = '#121933';
        ctx.fillRect(plot.x, plot.y, plot.width, plot.height);

        this.drawGrid(plot);
        this.drawAxes(plot);

        ctx.fillStyle = '#dbe4ff';
        ctx.font = '13px sans-serif';
        ctx.fillText('Stocks', 10, 16);
        ctx.fillText('Time', plot.x + plot.width - 30, height - 10);
      }
    }

    const stocks = [
      { symbol: 'AAPL', basePrice: 192, volatility: 0.8 },
      { symbol: 'MSFT', basePrice: 415, volatility: 1.0 },
      { symbol: 'GOOGL', basePrice: 176, volatility: 0.7 },
      { symbol: 'AMZN', basePrice: 182, volatility: 0.9 },
      { symbol: 'NVDA', basePrice: 118, volatility: 1.3 },
      { symbol: 'META', basePrice: 505, volatility: 1.1 },
      { symbol: 'TSLA', basePrice: 170, volatility: 1.5 },
      { symbol: 'AMD', basePrice: 156, volatility: 1.2 },
      { symbol: 'NFLX', basePrice: 640, volatility: 1.0 },
      { symbol: 'INTC', basePrice: 34, volatility: 0.5 }
    ];

    const canvas = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const heatmap = new StockHeatmap(canvas, tooltip, {
      stocks,
      maxPoints: parseInt(document.getElementById('windowSize').value, 10)
    });

    let paused = false;
    let timer = null;

    function startTimer(interval) {
      if (timer) clearInterval(timer);
      timer = setInterval(() => {
        if (!paused) heatmap.addDataPoint();
      }, interval);
    }

    startTimer(parseInt(document.getElementById('speed').value, 10));

    document.getElementById('speed').addEventListener('change', (e) => {
      startTimer(parseInt(e.target.value, 10));
    });

    document.getElementById('windowSize').addEventListener('change', (e) => {
      heatmap.setMaxPoints(parseInt(e.target.value, 10));
    });

    document.getElementById('resetView').addEventListener('click', () => {
      heatmap.resetView();
      heatmap.render();
    });

    document.getElementById('pauseBtn').addEventListener('click', (e) => {
      paused = !paused;
      e.target.textContent = paused ? 'Resume' : 'Pause';
    });
  </script>
</body>
</html>
```

---

## How to use

- **Hover** over cells to inspect values
- **Drag** to pan
- **Mouse wheel** to zoom horizontally
- **Shift + mouse wheel** to zoom vertically
- Use toolbar controls to:
  - change update speed
  - change time window
  - pause/resume stream
  - reset view

---

## Notes on architecture

This initial version is intentionally simple:

- **Rendering**: HTML canvas for efficient drawing
- **Data model**:
  - `stocks[]` defines rows
  - each stock has a time series of points
- **Realtime updates**:
  - simulated random walk
  - can be replaced with WebSocket/SSE/API stream
- **Viewport transform**:
  - `scaleX`, `scaleY`, `offsetX`, `offsetY`

---

## Replacing simulated data with real data

You can replace `addDataPoint()` input generation with a live stream.

Example sketch:

```js
const ws = new WebSocket('wss://your-feed.example.com/stocks');

ws.onmessage = (event) => {
  const updates = JSON.parse(event.data);
  // updates example:
  // [{ symbol: 'AAPL', price: 194.12, ts: Date.now() }, ...]

  const ts = Date.now();
  heatmap.timestamps.push(ts);
  if (heatmap.timestamps.length > heatmap.maxPoints) {
    heatmap.timestamps.shift();
  }

  heatmap.data.forEach((series, rowIndex) => {
    const stock = heatmap.stocks[rowIndex];
    const match = updates.find(u => u.symbol === stock.symbol);
    const prev = series[series.length - 1];
    const price = match ? match.price : prev.price;
    const changePct = ((price - stock.basePrice) / stock.basePrice) * 100;

    series.push({ ts, price, changePct });
    if (series.length > heatmap.maxPoints) {
      series.shift();
    }
  });

  heatmap.render();
};
```

