    }

    .chart-wrap {
      position: relative;
      flex: 1;
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(10, 14, 24, 0.95);
      border: 1px solid var(--border);
      color: var(--text);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      min-width: 160px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      display: none;
      z-index: 10;
      white-space: nowrap;
    }

    .legend {
      position: absolute;
      right: 14px;
      bottom: 14px;
      background: rgba(18, 26, 43, 0.9);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px;
      font-size: 12px;
      color: var(--muted);
    }

    .legend-bar {
      width: 180px;
      height: 12px;
      border-radius: 999px;
      margin-bottom: 6px;
      background: linear-gradient(
        90deg,
        rgb(180, 40, 40) 0%,
        rgb(230, 190, 70) 50%,
        rgb(40, 180, 90) 100%
      );
      border: 1px solid rgba(255,255,255,0.08);
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>

      <div class="group">
        <label for="symbolsCount">Symbols</label>
        <select id="symbolsCount">
          <option value="10">10</option>
          <option value="20" selected>20</option>
          <option value="40">40</option>
        </select>
      </div>

      <div class="group">
        <label for="timeSteps">Columns</label>
        <select id="timeSteps">
          <option value="60">60</option>
          <option value="120" selected>120</option>
          <option value="240">240</option>
        </select>
      </div>

      <div class="group">
        <label for="speed">Update ms</label>
        <input id="speed" type="number" min="50" step="50" value="250" />
      </div>

      <div class="group">
        <button id="toggleStream">Pause</button>
        <button id="resetView">Reset View</button>
        <button id="regen">Regenerate</button>
      </div>

      <div class="status" id="status">Running</div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="legend">
        <div class="legend-bar"></div>
        <div>- strong loss &nbsp;&nbsp; | &nbsp;&nbsp; neutral &nbsp;&nbsp; | &nbsp;&nbsp; strong gain +</div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const symbolsCountEl = document.getElementById("symbolsCount");
    const timeStepsEl = document.getElementById("timeSteps");
    const speedEl = document.getElementById("speed");
    const toggleStreamBtn = document.getElementById("toggleStream");
    const resetViewBtn = document.getElementById("resetView");
    const regenBtn = document.getElementById("regen");

    const DPR = Math.max(1, window.devicePixelRatio || 1);

    const state = {
      width: 0,
      height: 0,
      padding: { top: 30, right: 20, bottom: 40, left: 90 },

      symbols: [],
      timeLabels: [],
      prices: [],      // [row][col]
      changes: [],     // normalized price deltas [row][col]

      rows: 20,
      cols: 120,

      streamTimer: null,
      streaming: true,
      updateMs: 250,

      view: {
        offsetX: 0,
        offsetY: 0,
        scaleX: 1,
        scaleY: 1
      },

      drag: {
        active: false,
        startX: 0,
        startY: 0,
        originOffsetX: 0,
        originOffsetY: 0
      },

      hover: {
        row: -1,
        col: -1,
        x: 0,
        y: 0
      }
    };

    function generateSymbols(n) {
      const base = [
        "AAPL","MSFT","GOOG","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
        "ORCL","CRM","UBER","SHOP","BABA","PYPL","ADBE","QCOM","AVGO","IBM",
        "SONY","SAP","CSCO","SQ","PLTR","SNOW","ZM","COIN","DOCU","ROKU",
        "PANW","NOW","ASML","ARM","DELL","HPQ","MU","TXN","AMAT","MRVL"
      ];
      return base.slice(0, n);
    }

    function nowLabel() {
      const d = new Date();
      return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    }

    function initData(rows, cols) {
      state.rows = rows;
      state.cols = cols;
      state.symbols = generateSymbols(rows);
      state.timeLabels = [];
      state.prices = [];
      state.changes = [];

      for (let c = 0; c < cols; c++) {
        state.timeLabels.push(`T-${cols - c}`);
      }

      for (let r = 0; r < rows; r++) {
        const basePrice = 50 + Math.random() * 250;
        const rowPrices = [];
        const rowChanges = [];
        let p = basePrice;

        for (let c = 0; c < cols; c++) {
          const drift = (Math.random() - 0.5) * 2.5;
          p = Math.max(5, p + drift);
          rowPrices.push(+p.toFixed(2));
          rowChanges.push(0);
        }

        for (let c = 1; c < cols; c++) {
          const prev = rowPrices[c - 1];
          const curr = rowPrices[c];
          rowChanges[c] = ((curr - prev) / prev) * 100;
        }

        state.prices.push(rowPrices);
        state.changes.push(rowChanges);
      }

      state.timeLabels[state.timeLabels.length - 1] = nowLabel();
      normalizeChanges();
      resetView();
    }

    function normalizeChanges() {
      let maxAbs = 0.01;
      for (let r = 0; r < state.rows; r++) {
        for (let c = 0; c < state.cols; c++) {
          maxAbs = Math.max(maxAbs, Math.abs(state.changes[r][c]));
        }
      }
      state.maxAbsChange = maxAbs;
    }

    function resize() {
      const rect = wrap.getBoundingClientRect();
      state.width = rect.width;
      state.height = rect.height;

      canvas.width = Math.floor(rect.width * DPR);
      canvas.height = Math.floor(rect.height * DPR);
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";

      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
      draw();
    }

    function getPlotRect() {
      const { top, right, bottom, left } = state.padding;
      return {
        x: left,
        y: top,
        w: state.width - left - right,
        h: state.height - top - bottom
      };
    }

    function resetView() {
      state.view.offsetX = 0;
      state.view.offsetY = 0;
      state.view.scaleX = 1;
      state.view.scaleY = 1;
      draw();
    }

    function clampView() {
      const plot = getPlotRect();
      const maxPanX = Math.max(0, plot.w * (state.view.scaleX - 1));
      const maxPanY = Math.max(0, plot.h * (state.view.scaleY - 1));

      state.view.offsetX = Math.min(0, Math.max(-maxPanX, state.view.offsetX));
      state.view.offsetY = Math.min(0, Math.max(-maxPanY, state.view.offsetY));
    }

    function colorForChange(change) {
      const t = Math.max(-1, Math.min(1, change / state.maxAbsChange));
      if (t < 0) {
        const k = t + 1;
        const r = Math.round(180 + (230 - 180) * k);
        const g = Math.round(40 + (190 - 40) * k);
        const b = Math.round(40 + (70 - 40) * k);
        return `rgb(${r},${g},${b})`;
      } else {
        const k = t;
        const r = Math.round(230 + (40 - 230) * k);
        const g = Math.round(190 + (180 - 190) * k);
        const b = Math.round(70 + (90 - 70) * k);
        return `rgb(${r},${g},${b})`;
      }
    }

    function clear() {
      ctx.clearRect(0, 0, state.width, state.height);
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, state.width, state.height);
    }

    function drawAxes(plot, cellW, cellH, scaledCellW, scaledCellH) {
      ctx.save();
      ctx.strokeStyle = "#2b395c";
      ctx.lineWidth = 1;

      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.w, plot.h);
      ctx.stroke();

      ctx.fillStyle = "#8fa3c7";
      ctx.font = "12px Inter, sans-serif";
      ctx.textBaseline = "middle";

      for (let r = 0; r < state.rows; r++) {
        const y = plot.y + state.view.offsetY + r * scaledCellH + scaledCellH / 2;
        if (y < plot.y - scaledCellH || y > plot.y + plot.h + scaledCellH) continue;
        ctx.textAlign = "right";
        ctx.fillText(state.symbols[r], plot.x - 10, y);
      }

      const labelStep = Math.max(1, Math.floor(state.cols / 8));
      ctx.textAlign = "center";
      ctx.textBaseline = "top";

      for (let c = 0; c < state.cols; c += labelStep) {
        const x = plot.x + state.view.offsetX + c * scaledCellW + scaledCellW / 2;
        if (x < plot.x || x > plot.x + plot.w) continue;
        ctx.fillText(state.timeLabels[c], x, plot.y + plot.h + 8);
      }

      ctx.restore();
    }

    function drawHeatmap() {
      clear();

      const plot = getPlotRect();
      const baseCellW = plot.w / state.cols;
      const baseCellH = plot.h / state.rows;
      const cellW = baseCellW * state.view.scaleX;
      const cellH = baseCellH * state.view.scaleY;

      clampView();

      ctx.save();
      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.w, plot.h);
      ctx.clip();

      for (let r = 0; r < state.rows; r++) {
        const y = plot.y + state.view.offsetY + r * cellH;
        if (y + cellH < plot.y || y > plot.y + plot.h) continue;

        for (let c = 0; c < state.cols; c++) {
          const x = plot.x + state.view.offsetX + c * cellW;
          if (x + cellW < plot.x || x > plot.x + plot.w) continue;

          ctx.fillStyle = colorForChange(state.changes[r][c]);
          ctx.fillRect(x, y, cellW, cellH);

          if (cellW > 8 && cellH > 8) {
            ctx.strokeStyle = "rgba(11,16,32,0.35)";
            ctx.strokeRect(x, y, cellW, cellH);
          }

          if (state.hover.row === r && state.hover.col === c) {
            ctx.strokeStyle = "#ffffff";
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, Math.max(0, cellW - 2), Math.max(0, cellH - 2));
          }
        }
      }

      ctx.restore();
      drawAxes(plot, baseCellW, baseCellH, cellW, cellH);
    }

    function draw() {
      drawHeatmap();
    }

    function screenToCell(mx, my) {
      const plot = getPlotRect();
      if (mx < plot.x || mx > plot.x + plot.w || my < plot.y || my > plot.y + plot.h) {
        return { row: -1, col: -1 };
      }

      const baseCellW = plot.w / state.cols;
      const baseCellH = plot.h / state.rows;
      const cellW = baseCellW * state.view.scaleX;
      const cellH = baseCellH * state.view.scaleY;

      const localX = mx - plot.x - state.view.offsetX;
      const localY = my - plot.y - state.view.offsetY;

      const col = Math.floor(localX / cellW);
      const row = Math.floor(localY / cellH);

      if (row < 0 || row >= state.rows || col < 0 || col >= state.cols) {
        return { row: -1, col: -1 };
      }

      return { row, col };
    }

    function updateTooltip(mx, my) {
      const hit = screenToCell(mx, my);
      state.hover.row = hit.row;
      state.hover.col = hit.col;
      state.hover.x = mx;
      state.hover.y = my;

      if (hit.row === -1 || hit.col === -1) {
        tooltip.style.display = "none";
        draw();
        return;
      }

      const symbol = state.symbols[hit.row];
      const time = state.timeLabels[hit.col];
      const price = state.prices[hit.row][hit.col];
      const change = state.changes[hit.row][hit.col];

      tooltip.innerHTML = `
        <div><strong>${symbol}</strong></div>
        <div>Time: ${time}</div>
        <div>Price: $${price.toFixed(2)}</div>
        <div>Change: <span style="color:${change >= 0 ? '#5ee28a' : '#ff7b7b'}">${change.toFixed(2)}%</span></div>
      `;
      tooltip.style.display = "block";
      tooltip.style.left = Math.min(state.width - 180, mx + 12) + "px";
      tooltip.style.top = Math.min(state.height - 80, my + 12) + "px";

      draw();
    }

    function pushRealtimeUpdate() {
      state.timeLabels.shift();
      state.timeLabels.push(nowLabel());

      for (let r = 0; r < state.rows; r++) {
        const rowPrices = state.prices[r];
        const rowChanges = state.changes[r];

        const prev = rowPrices[rowPrices.length - 1];
        const volatility = prev * 0.0025;
        const next = Math.max(5, prev + (Math.random() - 0.5) * volatility * 2);

        rowPrices.shift();
        rowPrices.push(+next.toFixed(2));

        rowChanges.shift();
        rowChanges.push(((next - prev) / prev) * 100);
      }

      normalizeChanges();
      draw();
    }

    function startStreaming() {
      stopStreaming();
      state.streaming = true;
      statusEl.textContent = `Running • ${state.updateMs}ms`;
      toggleStreamBtn.textContent = "Pause";

      state.streamTimer = setInterval(() => {
        pushRealtimeUpdate();
      }, state.updateMs);
    }

    function stopStreaming() {
      state.streaming = false;
      statusEl.textContent = "Paused";
      toggleStreamBtn.textContent = "Resume";
      if (state.streamTimer) {
        clearInterval(state.streamTimer);
        state.streamTimer = null;
      }
    }

    canvas.addEventListener("mousemove", (e) => {
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (state.drag.active) {
        const dx = mx - state.drag.startX;
        const dy = my - state.drag.startY;
        state.view.offsetX = state.drag.originOffsetX + dx;
        state.view.offsetY = state.drag.originOffsetY + dy;
        clampView();
        draw();
        return;
      }

      updateTooltip(mx, my);
    });

    canvas.addEventListener("mouseleave", () => {
      state.hover.row = -1;
      state.hover.col = -1;
      tooltip.style.display = "none";
      draw();
    });

    canvas.addEventListener("mousedown", (e) => {
      state.drag.active = true;
      canvas.classList.add("dragging");

      const rect = canvas.getBoundingClientRect();
      state.drag.startX = e.clientX - rect.left;
      state.drag.startY = e.clientY - rect.top;
      state.drag.originOffsetX = state.view.offsetX;
      state.drag.originOffsetY = state.view.offsetY;
    });

    window.addEventListener("mouseup", () => {
      state.drag.active = false;
      canvas.classList.remove("dragging");
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      if (e.shiftKey) {
        state.view.scaleY = Math.max(0.5, Math.min(8, state.view.scaleY * zoomFactor));
      } else {
        state.view.scaleX = Math.max(0.5, Math.min(12, state.view.scaleX * zoomFactor));
      }

      clampView();
      draw();
    }, { passive: false });

    toggleStreamBtn.addEventListener("click", () => {
      if (state.streaming) stopStreaming();
      else startStreaming();
    });

    resetViewBtn.addEventListener("click", () => {
      resetView();
    });

    regenBtn.addEventListener("click", () => {
      initData(+symbolsCountEl.value, +timeStepsEl.value);
      if (state.streaming) startStreaming();
      else draw();
    });

    symbolsCountEl.addEventListener("change", () => {
      initData(+symbolsCountEl.value, +timeStepsEl.value);
      if (state.streaming) startStreaming();
    });

    timeStepsEl.addEventListener("change", () => {
      initData(+symbolsCountEl.value, +timeStepsEl.value);
      if (state.streaming) startStreaming();
    });

    speedEl.addEventListener("change", () => {
      state.updateMs = Math.max(50, +speedEl.value || 250);
      if (state.streaming) startStreaming();
    });

    window.addEventListener("resize", resize);

    initData(20, 120);
    state.updateMs = 250;
    resize();
    startStreaming();
  </script>
</body>
</html>
```

---

## How to use

- **Hover** over cells to inspect values
- **Drag** to pan
- **Mouse wheel** to zoom horizontally
- **Shift + mouse wheel** to zoom vertically
- Use toolbar controls to:
  - change number of symbols
  - change number of time columns
  - adjust update speed
  - pause/resume streaming

---

## Notes on architecture

This initial version is intentionally simple:

- **Rendering:** HTML5 canvas
- **Data model:** 2D arrays for `prices` and `changes`
- **Streaming:** `setInterval()` simulates real-time ticks
- **Interaction:** manual zoom/pan math

---

## Suggested next improvements

If you want to evolve this into a production-quality component, I’d recommend:

1. **Use real market data**
   - WebSocket feed
   - REST bootstrap + incremental updates

2. **Improve zoom behavior**
   - zoom around mouse cursor rather than global scaling
   - add touch pinch support

3. **Virtualization / larger datasets**
   - offscreen canvas
   - WebGL rendering for thousands of rows/columns

4. **Better color scaling**
   - configurable palette
   - percentile clipping
   - log or z-score normalization

5. **Axes and labels**
   - sticky row labels
   - smarter time tick formatting

6. **Framework integration**
   - wrap into React/Vue/Svelte component
   - expose props/events

7. **Performance**
   - render only visible cells
   - use `requestAnimationFrame`
   - partial redraws for streaming updates

8. **Accessibility**
   - keyboard navigation
   - screen-reader summaries
   - high-contrast mode

