      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      line-height: 1.4;
      border: 1px solid #333;
    }

    .legend-bar {
      width: 140px;
      height: 10px;
      margin-top: 6px;
      background: linear-gradient(to right, #1e88e5, #222, #e53935);
      border: 1px solid #444;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <span>Wheel = zoom</span>
    <span>Drag = pan</span>
    <span id="status"></span>
  </div>

  <div id="container">
    <canvas id="heatmap"></canvas>
    <div class="legend">
      Price Change
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between;">
        <span>-</span><span>0</span><span>+</span>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const statusEl = document.getElementById('status');

    const ROWS = 30;   // stocks
    const COLS = 120;  // time slices
    const stocks = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);

    // Heatmap data: rows x cols, values are price changes in [-1, 1]
    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => (Math.random() - 0.5) * 0.4)
    );

    let view = {
      scaleX: 1,
      scaleY: 1,
      offsetX: 0,
      offsetY: 0
    };

    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v in [-1, 1]
      v = clamp(v, -1, 1);

      if (v < 0) {
        // blue -> dark
        const t = 1 + v; // -1..0 => 0..1
        const r = Math.round(30 * t + 10 * (1 - t));
        const g = Math.round(136 * t + 40 * (1 - t));
        const b = Math.round(229 * t + 120 * (1 - t));
        return `rgb(${r},${g},${b})`;
      } else {
        // dark -> red
        const t = v; // 0..1
        const r = Math.round(34 * (1 - t) + 229 * t);
        const g = Math.round(34 * (1 - t) + 57 * t);
        const b = Math.round(34 * (1 - t) + 53 * t);
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const baseCellW = width / COLS;
      const baseCellH = height / ROWS;
      const cellW = baseCellW * view.scaleX;
      const cellH = baseCellH * view.scaleY;

      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);

      // Draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = c * cellW;
          const y = r * cellH;

          // Skip offscreen cells
          if (x + cellW < -view.offsetX || x > width - view.offsetX) continue;
          if (y + cellH < -view.offsetY || y > height - view.offsetY) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW, cellH);
        }
      }

      // Grid lines when zoomed in enough
      if (cellW > 8 && cellH > 8) {
        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = 1;

        for (let c = 0; c <= COLS; c++) {
          const x = c * cellW;
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, ROWS * cellH);
          ctx.stroke();
        }

        for (let r = 0; r <= ROWS; r++) {
          const y = r * cellH;
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(COLS * cellW, y);
          ctx.stroke();
        }
      }

      ctx.restore();

      // Labels for rows when zoom allows
      if (cellH > 14) {
        ctx.fillStyle = '#ddd';
        ctx.font = '12px sans-serif';
        for (let r = 0; r < ROWS; r++) {
          const y = view.offsetY + r * cellH + cellH * 0.65;
          if (y < 0 || y > height) continue;
          ctx.fillText(stocks[r], 6, y);
        }
      }

      statusEl.textContent =
        `Zoom: ${view.scaleX.toFixed(2)}x, ${view.scaleY.toFixed(2)}x | Offset: ${Math.round(view.offsetX)}, ${Math.round(view.offsetY)}`;
    }

    function pushRealtimeData() {
      // Shift left and append new simulated price changes
      for (let r = 0; r < ROWS; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        const next = clamp(prev + (Math.random() - 0.5) * 0.25, -1, 1);
        data[r].push(next);
      }
      draw();
    }

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      canvas.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      view.offsetX += dx;
      view.offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      // Zoom around mouse position
      const prevScaleX = view.scaleX;
      const prevScaleY = view.scaleY;

      view.scaleX = clamp(view.scaleX * zoomFactor, 0.5, 8);
      view.scaleY = clamp(view.scaleY * zoomFactor, 0.5, 8);

      const scaleRatioX = view.scaleX / prevScaleX;
      const scaleRatioY = view.scaleY / prevScaleY;

      view.offsetX = mouseX - (mouseX - view.offsetX) * scaleRatioX;
      view.offsetY = mouseY - (mouseY - view.offsetY) * scaleRatioY;

      draw();
    }, { passive: false });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    draw();

    // Simulated realtime updates every 300ms
    setInterval(pushRealtimeData, 300);
  </script>
</body>
</html>
```

