<body>
  <div class="toolbar">
    <button id="resetBtn">Reset View</button>
    <div>Realtime Stock Heatmap</div>
    <div class="legend">Red = down, Gray = flat, Green = up</div>
  </div>

  <div id="container">
    <canvas id="heatmap"></canvas>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const resetBtn = document.getElementById("resetBtn");
    const container = document.getElementById("container");

    const symbols = [
      "AAPL", "MSFT", "GOOG", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC"
    ];

    const maxCols = 200;
    const data = symbols.map(() => []);

    // View transform
    let offsetX = 80;
    let offsetY = 20;
    let scaleX = 18;
    let scaleY = 28;

    let isDragging = false;
    let lastMouseX = 0;
    let lastMouseY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = container.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(val, min, max) {
      return Math.max(min, Math.min(max, val));
    }

    function colorForChange(change) {
      // Clamp between -3% and +3%
      const c = clamp(change, -3, 3);
      if (c < 0) {
        const t = Math.abs(c) / 3;
        const r = 80 + Math.floor(175 * t);
        const g = 40;
        const b = 40;
        return `rgb(${r},${g},${b})`;
      } else {
        const t = c / 3;
        const r = 40;
        const g = 80 + Math.floor(175 * t);
        const b = 40;
        return `rgb(${r},${g},${b})`;
      }
    }

    function seedData() {
      for (let row = 0; row < symbols.length; row++) {
        let price = 100 + Math.random() * 200;
        for (let col = 0; col < 50; col++) {
          const delta = (Math.random() - 0.5) * 2;
          price *= 1 + delta / 100;
          data[row].push(delta);
        }
      }
    }

    function pushRealtimeData() {
      for (let row = 0; row < symbols.length; row++) {
        const delta = (Math.random() - 0.5) * 1.5;
        data[row].push(delta);
        if (data[row].length > maxCols) data[row].shift();
      }
      draw();
    }

    function drawAxes() {
      ctx.fillStyle = "#aaa";
      ctx.font = "12px sans-serif";
      ctx.textBaseline = "middle";

      // Row labels
      for (let row = 0; row < symbols.length; row++) {
        const y = offsetY + row * scaleY + scaleY / 2;
        if (y < -20 || y > canvas.clientHeight + 20) continue;
        ctx.fillText(symbols[row], 10, y);
      }

      // Border line separating labels from heatmap
      ctx.strokeStyle = "#333";
      ctx.beginPath();
      ctx.moveTo(offsetX - 5, 0);
      ctx.lineTo(offsetX - 5, canvas.clientHeight);
      ctx.stroke();
    }

    function drawHeatmap() {
      for (let row = 0; row < data.length; row++) {
        const rowData = data[row];
        for (let col = 0; col < rowData.length; col++) {
          const x = offsetX + col * scaleX;
          const y = offsetY + row * scaleY;

          if (
            x + scaleX < 0 || x > canvas.clientWidth ||
            y + scaleY < 0 || y > canvas.clientHeight
          ) continue;

          ctx.fillStyle = colorForChange(rowData[col]);
          ctx.fillRect(x, y, scaleX - 1, scaleY - 1);
        }
      }
    }

    function drawGrid() {
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1;

      for (let row = 0; row <= symbols.length; row++) {
        const y = offsetY + row * scaleY;
        ctx.beginPath();
        ctx.moveTo(offsetX, y);
        ctx.lineTo(canvas.clientWidth, y);
        ctx.stroke();
      }

      const visibleCols = Math.ceil(canvas.clientWidth / scaleX);
      for (let col = 0; col <= visibleCols + 2; col++) {
        const x = offsetX + col * scaleX;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.clientHeight);
        ctx.stroke();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.clientWidth, canvas.clientHeight);
      drawHeatmap();
      drawGrid();
      drawAxes();
    }

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
      canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      canvas.classList.remove("dragging");
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      const dx = e.clientX - lastMouseX;
      const dy = e.clientY - lastMouseY;
      offsetX += dx;
      offsetY += dy;
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const mouseX = e.offsetX;
      const mouseY = e.offsetY;
      const zoom = e.deltaY < 0 ? 1.1 : 0.9;

      const prevScaleX = scaleX;
      const prevScaleY = scaleY;

      scaleX = clamp(scaleX * zoom, 4, 80);
      scaleY = clamp(scaleY * zoom, 10, 80);

      // Zoom around cursor
      offsetX = mouseX - ((mouseX - offsetX) / prevScaleX) * scaleX;
      offsetY = mouseY - ((mouseY - offsetY) / prevScaleY) * scaleY;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      offsetX = 80;
      offsetY = 20;
      scaleX = 18;
      scaleY = 28;
      draw();
    });

    window.addEventListener("resize", resizeCanvas);

    seedData();
    resizeCanvas();
    setInterval(pushRealtimeData, 1000);
  </script>
</body>
</html>
