  <div class="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <span>Wheel = zoom</span>
    <span>Drag = pan</span>
    <span id="status"></span>
  </div>

  <div id="container">
    <canvas id="heatmap"></canvas>
    <div class="hint">Green = gain, Red = loss</div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const container = document.getElementById('container');
    const statusEl = document.getElementById('status');

    const ROWS = 20;   // stocks
    const COLS = 120;  // time buckets
    const stocks = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);

    // Heatmap data: rows = stocks, cols = time
    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => 0)
    );

    // Simulated current prices
    let prices = Array.from({ length: ROWS }, () => 100 + Math.random() * 50);

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    const minScale = 0.5;
    const maxScale = 6;

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = container.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v expected roughly in [-2, 2]
      const t = clamp((v + 2) / 4, 0, 1);

      // red -> dark -> green
      const r = Math.round((1 - t) * 220);
      const g = Math.round(t * 220);
      const b = 60;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function draw() {
      const width = container.clientWidth;
      const height = container.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const baseCellW = 14;
      const baseCellH = 24;
      const cellW = baseCellW * scale;
      const cellH = baseCellH * scale;

      // background
      ctx.fillStyle = '#0d0d0d';
      ctx.fillRect(0, 0, width, height);

      // draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = offsetX + c * cellW;
          const y = offsetY + r * cellH;

          if (x + cellW < 0 || x > width || y + cellH < 0 || y > height) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);
        }
      }

      // labels if zoomed enough
      if (scale > 1.2) {
        ctx.fillStyle = '#ddd';
        ctx.font = `${Math.max(10, 10 * scale)}px sans-serif`;
        ctx.textBaseline = 'middle';

        for (let r = 0; r < ROWS; r++) {
          const y = offsetY + r * cellH + cellH / 2;
          if (y < 0 || y > height) continue;
          ctx.fillText(stocks[r], 6, y);
        }
      }

      statusEl.textContent = `scale=${scale.toFixed(2)} offset=(${Math.round(offsetX)}, ${Math.round(offsetY)})`;
    }

    function tick() {
      // shift left and append new simulated % changes
      for (let r = 0; r < ROWS; r++) {
        const prev = prices[r];
        const next = prev + (Math.random() - 0.5) * 1.8;
        prices[r] = next;

        const pctChange = ((next - prev) / prev) * 100;
        data[r].shift();
        data[r].push(pctChange);
      }

      draw();
    }

    container.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = container.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const oldScale = scale;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      scale = clamp(scale * zoomFactor, minScale, maxScale);

      // zoom around mouse position
      const worldX = (mx - offsetX) / oldScale;
      const worldY = (my - offsetY) / oldScale;
      offsetX = mx - worldX * scale;
      offsetY = my - worldY * scale;

      draw();
    }, { passive: false });

    container.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      container.classList.add('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      offsetX += dx;
      offsetY += dy;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      container.classList.remove('dragging');
    });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    draw();
    setInterval(tick, 500);
  </script>
