      background: #1a1a1a;
      border: 1px solid #333;
      display: block;
    }

    .axis text {
      fill: #ccc;
      font-size: 11px;
    }

    .axis path,
    .axis line {
      stroke: #555;
    }

    .cell {
      stroke: #222;
      stroke-width: 1px;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(0, 0, 0, 0.85);
      color: white;
      padding: 6px 8px;
      border-radius: 4px;
      font-size: 12px;
      border: 1px solid #444;
      opacity: 0;
      transition: opacity 0.1s;
    }

    .hint {
      margin-top: 8px;
      color: #aaa;
      font-size: 13px;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>Realtime Stock Price Heatmap</h1>
    <svg id="chart" width="1100" height="600"></svg>
    <div class="hint">Scroll to zoom, drag to pan. Data updates every second.</div>
  </div>
  <div class="tooltip" id="tooltip"></div>

  <script>
    const svg = d3.select("#chart");
    const tooltip = d3.select("#tooltip");

    const width = +svg.attr("width");
    const height = +svg.attr("height");

    const margin = { top: 40, right: 20, bottom: 80, left: 100 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const root = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);
    const zoomLayer = root.append("g");
    const cellsLayer = zoomLayer.append("g");

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC",
      "ORCL", "IBM"
    ];

    const timeSteps = 30;
    let times = Array.from({ length: timeSteps }, (_, i) => `T-${timeSteps - 1 - i}`);

    // Initialize fake prices and changes
    let latestPrices = Object.fromEntries(
      symbols.map(s => [s, 100 + Math.random() * 200])
    );

    let data = [];

    function generateInitialData() {
      data = [];
      for (let t = 0; t < timeSteps; t++) {
        symbols.forEach(symbol => {
          const prev = latestPrices[symbol];
          const next = prev + (Math.random() - 0.5) * 4;
          const change = ((next - prev) / prev) * 100;
          latestPrices[symbol] = next;

          data.push({
            symbol,
            time: times[t],
            price: +next.toFixed(2),
            change: +change.toFixed(2)
          });
        });
      }
    }

    generateInitialData();

    let xScale = d3.scaleBand()
      .domain(times)
      .range([0, innerWidth])
      .padding(0.04);

    let yScale = d3.scaleBand()
      .domain(symbols)
      .range([0, innerHeight])
      .padding(0.04);

    const colorScale = d3.scaleSequential()
      .domain([3, -3]) // green positive, red negative
      .interpolator(d3.interpolateRdYlGn);

    const xAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${innerHeight})`);

    const yAxisG = root.append("g")
      .attr("class", "axis");

    function renderAxes() {
      xAxisG.call(d3.axisBottom(xScale));
      yAxisG.call(d3.axisLeft(yScale));

      xAxisG.selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");
    }

    function renderCells() {
      const cells = cellsLayer.selectAll("rect")
        .data(data, d => `${d.symbol}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change))
        .on("mousemove", (event, d) => {
          tooltip
            .style("opacity", 1)
            .html(`
              <strong>${d.symbol}</strong><br>
              Time: ${d.time}<br>
              Price: $${d.price}<br>
              Change: ${d.change}%
            `)
            .style("left", `${event.pageX + 10}px`)
            .style("top", `${event.pageY + 10}px`);
        })
        .on("mouseleave", () => {
          tooltip.style("opacity", 0);
        })
        .merge(cells)
        .transition()
        .duration(300)
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change));

      cells.exit().remove();
    }

    function updateData() {
      // shift time labels
      times.shift();
      times.push(`T+${Date.now() % 100000}`);

      // remove oldest column
      data = data.filter(d => d.time !== xScale.domain()[0]);

      // add new values for latest time
      const newTime = times[times.length - 1];
      symbols.forEach(symbol => {
        const prev = latestPrices[symbol];
        const next = prev + (Math.random() - 0.5) * 4;
        const change = ((next - prev) / prev) * 100;
        latestPrices[symbol] = next;

        data.push({
          symbol,
          time: newTime,
          price: +next.toFixed(2),
          change: +change.toFixed(2)
        });
      });

      xScale.domain(times);
      renderAxes();
      renderCells();
    }

    renderAxes();
    renderCells();

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        zoomLayer.attr("transform", event.transform);
      });

    svg.call(zoom);

    setInterval(updateData, 1000);
  </script>
</body>
</html>
```

