    }
  </style>
</head>
<body>
  <div id="toolbar">
    <strong>Real-Time Stock Price Heatmap</strong>
    <span id="status">Updating...</span>
    <div class="legend">
      <span>Low</span>
      <div class="gradient"></div>
      <span>High</span>
    </div>
  </div>

  <canvas id="heatmap"></canvas>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");

    const rows = 20;   // stocks
    const cols = 60;   // time slices
    const cellBaseSize = 20;

    let data = Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => 80 + Math.random() * 40)
    );

    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight - document.getElementById("toolbar").offsetHeight;
      draw();
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function colorForValue(v, min, max) {
      const t = Math.max(0, Math.min(1, (v - min) / (max - min || 1)));

      let r, g, b;
      if (t < 0.5) {
        const tt = t / 0.5;
        r = lerp(44, 255, tt);
        g = lerp(123, 255, tt);
        b = lerp(182, 191, tt);
      } else {
        const tt = (t - 0.5) / 0.5;
        r = lerp(255, 215, tt);
        g = lerp(255, 25, tt);
        b = lerp(191, 28, tt);
      }

      return `rgb(${r|0},${g|0},${b|0})`;
    }

    function getMinMax() {
      let min = Infinity, max = -Infinity;
      for (const row of data) {
        for (const v of row) {
          if (v < min) min = v;
          if (v > max) max = v;
        }
      }
      return { min, max };
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      const { min, max } = getMinMax();
      const cellSize = cellBaseSize;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = c * cellSize;
          const y = r * cellSize;
          const value = data[r][c];

          ctx.fillStyle = colorForValue(value, min, max);
          ctx.fillRect(x, y, cellSize - 1, cellSize - 1);
        }
      }

      ctx.restore();
    }

    function updateData() {
      for (let r = 0; r < rows; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1];
        const next = Math.max(10, prev + (Math.random() - 0.5) * 4);
        data[r].push(next);
      }
      statusEl.textContent = "Last update: " + new Date().toLocaleTimeString();
      draw();
    }

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = 1.1;
      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      if (e.deltaY < 0) {
        scale *= zoomFactor;
      } else {
        scale /= zoomFactor;
      }

      scale = Math.max(0.5, Math.min(5, scale));

      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      draw();
    }, { passive: false });

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    window.addEventListener("resize", resize);

    resize();
    draw();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
