```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <style>
    body {
      margin: 0;
      font-family: sans-serif;
      background: #111;
      color: #eee;
    }

    .toolbar {
      padding: 10px 14px;
      background: #1b1b1b;
      border-bottom: 1px solid #333;
      display: flex;
      gap: 16px;
      align-items: center;
      flex-wrap: wrap;
    }

    .toolbar span {
      font-size: 14px;
      color: #bbb;
    }

    #container {
      padding: 12px;
    }

    canvas {
      display: block;
      background: #000;
      border: 1px solid #333;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <span>Wheel = zoom horizontally</span>
    <span>Drag = pan</span>
    <span id="status"></span>
  </div>

  <div id="container">
    <canvas id="heatmap" width="1200" height="500"></canvas>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const statusEl = document.getElementById('status');

    const symbols = [
      'AAPL', 'MSFT', 'GOOG', 'AMZN', 'META',
      'TSLA', 'NVDA', 'NFLX', 'AMD', 'INTC',
      'ORCL', 'IBM', 'CRM', 'UBER', 'SHOP'
    ];

    const rows = symbols.length;
    const maxCols = 500; // total time history retained
    const data = symbols.map(() => []);

    // Seed with initial values
    for (let r = 0; r < rows; r++) {
      let price = 80 + Math.random() * 200;
      for (let c = 0; c < 80; c++) {
        price += (Math.random() - 0.5) * 4;
        data[r].push(price);
      }
    }

    // View state
    let viewStart = 0;
    let viewCols = 80; // visible columns
    const minViewCols = 10;
    const maxViewCols = maxCols;

    // Interaction state
    let isDragging = false;
    let dragStartX = 0;
    let dragStartViewStart = 0;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function getGlobalMinMax() {
      let min = Infinity;
      let max = -Infinity;
      for (const row of data) {
        for (const v of row) {
          if (v < min) min = v;
          if (v > max) max = v;
        }
      }
      return { min, max };
    }

    function colorForValue(value, min, max) {
      const t = (value - min) / ((max - min) || 1);
      // blue -> yellow -> red
      const r = Math.floor(255 * Math.min(1, Math.max(0, (t - 0.5) * 2)));
      const g = Math.floor(255 * (1 - Math.abs(t - 0.5) * 2));
      const b = Math.floor(255 * Math.min(1, Math.max(0, (0.5 - t) * 2)));
      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      const leftPad = 70;
      const bottomPad = 30;
      const topPad = 10;
      const plotWidth = width - leftPad;
      const plotHeight = height - bottomPad - topPad;

      const cellW = plotWidth / viewCols;
      const cellH = plotHeight / rows;

      const { min, max } = getGlobalMinMax();

      // Background
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, width, height);

      // Draw cells
      for (let r = 0; r < rows; r++) {
        for (let i = 0; i < viewCols; i++) {
          const colIndex = Math.floor(viewStart + i);
          const value = data[r][colIndex];
          if (value == null) continue;

          const x = leftPad + i * cellW;
          const y = topPad + r * cellH;

          ctx.fillStyle = colorForValue(value, min, max);
          ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));
        }
      }

      // Row labels
      ctx.fillStyle = '#ddd';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let r = 0; r < rows; r++) {
        const y = topPad + r * cellH + cellH / 2;
        ctx.fillText(symbols[r], leftPad - 8, y);
      }

      // Grid lines
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      for (let r = 0; r <= rows; r++) {
        const y = topPad + r * cellH;
        ctx.beginPath();
        ctx.moveTo(leftPad, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // Border
      ctx.strokeStyle = '#444';
      ctx.strokeRect(leftPad, topPad, plotWidth, plotHeight);

      statusEl.textContent = `viewStart=${viewStart.toFixed(1)} visible=${viewCols}`;
    }

    function pushTick() {
      for (let r = 0; r < rows; r++) {
        const row = data[r];
        const last = row[row.length - 1] ?? (100 + Math.random() * 50);
        const next = last + (Math.random() - 0.5) * 3;
        row.push(next);
        if (row.length > maxCols) row.shift();
      }

      // Keep viewport pinned to right edge if already near it
      const currentLen = data[0].length;
      const maxStart = Math.max(0, currentLen - viewCols);
      if (viewStart >= maxStart - 2) {
        viewStart = maxStart;
      } else {
        viewStart = clamp(viewStart, 0, maxStart);
      }

      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY > 0 ? 1.15 : 0.85;
      const oldViewCols = viewCols;
      viewCols = clamp(Math.round(viewCols * zoomFactor), minViewCols, maxViewCols);

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const leftPad = 70;
      const plotWidth = canvas.width - leftPad;
      const rel = clamp((mouseX - leftPad) / plotWidth, 0, 1);

      const anchorCol = viewStart + rel * oldViewCols;
      viewStart = anchorCol - rel * viewCols;

      const currentLen = data[0].length;
      const maxStart = Math.max(0, currentLen - viewCols);
      viewStart = clamp(viewStart, 0, maxStart);

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      dragStartX = e.clientX;
      dragStartViewStart = viewStart;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      canvas.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;

      const leftPad = 70;
      const plotWidth = canvas.width - leftPad;
      const dx = e.clientX - dragStartX;
      const colsPerPixel = viewCols / plotWidth;

      viewStart = dragStartViewStart - dx * colsPerPixel;

      const currentLen = data[0].length;
      const maxStart = Math.max(0, currentLen - viewCols);
      viewStart = clamp(viewStart, 0, maxStart);

      draw();
    });

    // Initial draw
    draw();

    // Simulated realtime updates
    setInterval(pushTick, 500);
  </script>
</body>
</html>
