  </style>
</head>
<body>
  <div class="toolbar">
    <button id="resetView">Reset View</button>
    <span>Interactive Realtime Stock Heatmap</span>
  </div>

  <div class="container">
    <canvas id="heatmap" width="1000" height="500"></canvas>
    <div class="hint">
      Wheel = zoom horizontally, drag = pan, realtime updates every 300ms
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const resetBtn = document.getElementById("resetView");

    const width = canvas.width;
    const height = canvas.height;

    // Heatmap dimensions:
    // rows = stocks, cols = time slices
    const stocks = [
      "AAPL", "MSFT", "GOOG", "AMZN", "TSLA",
      "NVDA", "META", "NFLX", "AMD", "INTC"
    ];
    const rows = stocks.length;
    const totalCols = 300;

    // Data grid: each row has a rolling series of % changes
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: totalCols }, () => 0)
    );

    // Seed with random walk data
    for (let r = 0; r < rows; r++) {
      let v = (Math.random() - 0.5) * 2;
      for (let c = 0; c < totalCols; c++) {
        v += (Math.random() - 0.5) * 0.6;
        v = Math.max(-5, Math.min(5, v));
        data[r][c] = v;
      }
    }

    // View state for horizontal zoom/pan
    let viewStart = 0;
    let viewCols = 80;

    const leftPad = 70;
    const rightPad = 20;
    const topPad = 20;
    const bottomPad = 30;

    let isDragging = false;
    let dragStartX = 0;
    let dragStartViewStart = 0;

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function colorForValue(v) {
      // v in roughly [-5, 5]
      const t = clamp((v + 5) / 10, 0, 1);

      // interpolate red -> black -> green
      let r, g, b;
      if (t < 0.5) {
        const k = t / 0.5;
        r = 255 * (1 - k);
        g = 0;
        b = 0;
      } else {
        const k = (t - 0.5) / 0.5;
        r = 0;
        g = 255 * k;
        b = 0;
      }
      return `rgb(${r|0},${g|0},${b|0})`;
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#000";
      ctx.fillRect(0, 0, width, height);

      const plotW = width - leftPad - rightPad;
      const plotH = height - topPad - bottomPad;

      const cellW = plotW / viewCols;
      const cellH = plotH / rows;

      // Draw heatmap cells
      for (let r = 0; r < rows; r++) {
        for (let i = 0; i < viewCols; i++) {
          const c = Math.floor(viewStart + i);
          if (c < 0 || c >= totalCols) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(
            leftPad + i * cellW,
            topPad + r * cellH,
            Math.ceil(cellW),
            Math.ceil(cellH)
          );
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let r = 0; r <= rows; r++) {
        const y = topPad + r * cellH;
        ctx.beginPath();
        ctx.moveTo(leftPad, y);
        ctx.lineTo(leftPad + plotW, y);
        ctx.stroke();
      }

      for (let i = 0; i <= viewCols; i += Math.max(1, Math.floor(viewCols / 10))) {
        const x = leftPad + i * cellW;
        ctx.beginPath();
        ctx.moveTo(x, topPad);
        ctx.lineTo(x, topPad + plotH);
        ctx.stroke();
      }

      // Stock labels
      ctx.fillStyle = "#ddd";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";

      for (let r = 0; r < rows; r++) {
        const y = topPad + r * cellH + cellH / 2;
        ctx.fillText(stocks[r], leftPad - 8, y);
      }

      // Time labels
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      const tickCount = 10;
      for (let t = 0; t <= tickCount; t++) {
        const frac = t / tickCount;
        const col = Math.floor(viewStart + frac * viewCols);
        const x = leftPad + frac * plotW;
        ctx.fillText(String(col), x, topPad + plotH + 6);
      }

      // Border
      ctx.strokeStyle = "#666";
      ctx.strokeRect(leftPad, topPad, plotW, plotH);
    }

    function updateData() {
      for (let r = 0; r < rows; r++) {
        const prev = data[r][data[r].length - 1];
        let next = prev + (Math.random() - 0.5) * 0.8;
        next = clamp(next, -5, 5);
        data[r].push(next);
        data[r].shift();
      }

      // Follow newest data if currently near the end
      const maxStart = totalCols - viewCols;
      if (viewStart > maxStart - 3) {
        viewStart = maxStart;
      }

      draw();
    }

    // Mouse wheel zoom
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const plotW = width - leftPad - rightPad;
      const mouseX = clamp(e.offsetX - leftPad, 0, plotW);
      const mouseFrac = plotW === 0 ? 0 : mouseX / plotW;
      const anchorCol = viewStart + mouseFrac * viewCols;

      const zoomFactor = e.deltaY > 0 ? 1.15 : 0.85;
      let newViewCols = Math.round(viewCols * zoomFactor);
      newViewCols = clamp(newViewCols, 10, totalCols);

      let newViewStart = anchorCol - mouseFrac * newViewCols;
      newViewStart = clamp(newViewStart, 0, totalCols - newViewCols);

      viewCols = newViewCols;
      viewStart = newViewStart;
      draw();
    }, { passive: false });

    // Drag pan
    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      dragStartX = e.clientX;
      dragStartViewStart = viewStart;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;

      const plotW = width - leftPad - rightPad;
      const dx = e.clientX - dragStartX;
      const colsPerPixel = viewCols / plotW;
      viewStart = clamp(
        dragStartViewStart - dx * colsPerPixel,
        0,
        totalCols - viewCols
      );
      draw();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    resetBtn.addEventListener("click", () => {
      viewStart = totalCols - 80;
      viewCols = 80;
      draw();
    });

    // Initial view near latest data
    viewStart = totalCols - viewCols;
    draw();

    // Simulated realtime stream
    setInterval(updateData, 300);
  </script>
</body>
</html>
```

