      border: 1px solid #444;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      Realtime Stock Price Heatmap —
      Mouse wheel: zoom |
      Drag: pan
    </div>
    <div class="container">
      <canvas id="heatmap"></canvas>
      <div class="legend">
        <div><strong>Color:</strong> price change</div>
        <div class="legend-bar"></div>
        <div style="display:flex; justify-content:space-between;">
          <span>Down</span>
          <span>Flat</span>
          <span>Up</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");

    const ROWS = 20;   // stocks
    const COLS = 120;  // time slices
    const stocks = [];
    const symbols = [];

    for (let i = 0; i < ROWS; i++) {
      symbols.push("STK" + String(i + 1).padStart(2, "0"));
      const row = [];
      let price = 100 + Math.random() * 50;
      for (let j = 0; j < COLS; j++) {
        price += (Math.random() - 0.5) * 2;
        row.push(price);
      }
      stocks.push(row);
    }

    let view = {
      scaleX: 1,
      scaleY: 1,
      offsetX: 0,
      offsetY: 0
    };

    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function priceToColor(change) {
      // clamp roughly to [-2, 2]
      const c = Math.max(-2, Math.min(2, change));
      if (c >= 0) {
        const t = c / 2;
        const r = Math.round(34 * (1 - t));
        const g = Math.round(34 + (180 - 34) * t);
        const b = Math.round(34 * (1 - t));
        return `rgb(${r},${g},${b})`;
      } else {
        const t = Math.abs(c) / 2;
        const r = Math.round(34 + (180 - 34) * t);
        const g = Math.round(34 * (1 - t));
        const b = Math.round(34 * (1 - t));
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      ctx.clearRect(0, 0, w, h);

      const baseCellW = 60;
      const baseCellH = 28;
      const cellW = baseCellW * view.scaleX;
      const cellH = baseCellH * view.scaleY;

      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);

      for (let r = 0; r < ROWS; r++) {
        for (let c = 1; c < COLS; c++) {
          const x = c * cellW;
          const y = r * cellH;

          if (x + cellW < -view.offsetX || x > w - view.offsetX) continue;
          if (y + cellH < -view.offsetY || y > h - view.offsetY) continue;

          const prev = stocks[r][c - 1];
          const curr = stocks[r][c];
          const change = curr - prev;

          ctx.fillStyle = priceToColor(change);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          if (view.scaleX > 0.8 && view.scaleY > 0.8) {
            ctx.fillStyle = "rgba(255,255,255,0.85)";
            ctx.font = "12px sans-serif";
            ctx.fillText(curr.toFixed(1), x + 4, y + 17);
          }
        }
      }

      // Row labels
      ctx.fillStyle = "#ddd";
      ctx.font = "12px sans-serif";
      for (let r = 0; r < ROWS; r++) {
        const y = r * cellH + cellH * 0.65;
        if (y < -view.offsetY || y > h - view.offsetY) continue;
        ctx.fillText(symbols[r], 4 - view.offsetX, y);
      }

      ctx.restore();
    }

    function tickData() {
      for (let r = 0; r < ROWS; r++) {
        const row = stocks[r];
        const last = row[row.length - 1];
        const next = last + (Math.random() - 0.5) * 3;
        row.push(next);
        row.shift();
      }
      draw();
    }

    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      canvas.classList.remove("dragging");
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      view.offsetX += dx;
      view.offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      const prevScaleX = view.scaleX;
      const prevScaleY = view.scaleY;

      view.scaleX = Math.max(0.3, Math.min(4, view.scaleX * zoomFactor));
      view.scaleY = Math.max(0.3, Math.min(4, view.scaleY * zoomFactor));

      // zoom around cursor
      view.offsetX = mouseX - ((mouseX - view.offsetX) * view.scaleX / prevScaleX);
      view.offsetY = mouseY - ((mouseY - view.offsetY) * view.scaleY / prevScaleY);

      draw();
    }, { passive: false });

    window.addEventListener("resize", resizeCanvas);

    resizeCanvas();
    draw();
    setInterval(tickData, 1000);
  </script>
</body>
</html>
