<body>
  <div class="container">
    <h1>Realtime Stock Price Heatmap</h1>
    <div class="controls">
      <button id="resetZoom">Reset Zoom</button>
      <span>Mouse wheel to zoom, drag to pan</span>
    </div>
    <svg id="chart" width="1100" height="520"></svg>
  </div>

  <div id="tooltip" class="tooltip"></div>

  <script>
    const svg = d3.select("#chart");
    const tooltip = d3.select("#tooltip");

    const width = +svg.attr("width");
    const height = +svg.attr("height");

    const margin = { top: 20, right: 20, bottom: 80, left: 90 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const g = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const heatmapLayer = g.append("g");
    const xAxisG = g.append("g").attr("class", "axis").attr("transform", `translate(0,${innerHeight})`);
    const yAxisG = g.append("g").attr("class", "axis");

    g.append("text")
      .attr("class", "label")
      .attr("x", innerWidth / 2)
      .attr("y", innerHeight + 55)
      .attr("text-anchor", "middle")
      .text("Time");

    g.append("text")
      .attr("class", "label")
      .attr("transform", "rotate(-90)")
      .attr("x", -innerHeight / 2)
      .attr("y", -60)
      .attr("text-anchor", "middle")
      .text("Stock");

    const stocks = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 40;

    let currentTime = 0;
    let data = [];

    const basePrices = new Map(
      stocks.map(s => [s, 100 + Math.random() * 200])
    );

    function formatTime(t) {
      return `T${t}`;
    }

    function generateInitialData() {
      for (let t = 0; t < timeSteps; t++) {
        stocks.forEach(stock => {
          const prev = basePrices.get(stock);
          const next = Math.max(10, prev + (Math.random() - 0.5) * 8);
          basePrices.set(stock, next);
          data.push({
            stock,
            time: t,
            price: +next.toFixed(2)
          });
        });
      }
      currentTime = timeSteps - 1;
    }

    generateInitialData();

    const x0 = d3.scaleBand()
      .domain(d3.range(timeSteps))
      .range([0, innerWidth])
      .padding(0.03);

    const y = d3.scaleBand()
      .domain(stocks)
      .range([0, innerHeight])
      .padding(0.03);

    function getPriceExtent() {
      return d3.extent(data, d => d.price);
    }

    const color = d3.scaleSequential()
      .interpolator(d3.interpolateRdYlGn);

    let xScale = x0.copy();

    function updateColorDomain() {
      const [min, max] = getPriceExtent();
      color.domain([min, max]);
    }

    function visibleData() {
      const [rx0, rx1] = xScale.range();
      return data.filter(d => {
        const x = xScale(d.time);
        return x !== undefined && x + xScale.bandwidth() >= 0 && x <= innerWidth;
      });
    }

    function render() {
      updateColorDomain();

      const cells = heatmapLayer.selectAll("rect.cell")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("rx", 2)
        .attr("ry", 2)
        .merge(cells)
        .attr("x", d => xScale(d.time))
        .attr("y", d => y(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", y.bandwidth())
        .attr("fill", d => color(d.price))
        .attr("stroke", "#111")
        .on("mousemove", (event, d) => {
          tooltip
            .style("display", "block")
            .style("left", (event.clientX + 12) + "px")
            .style("top", (event.clientY + 12) + "px")
            .html(
              `<strong>${d.stock}</strong><br>` +
              `Time: ${formatTime(d.time)}<br>` +
              `Price: $${d.price}`
            );
        })
        .on("mouseleave", () => {
          tooltip.style("display", "none");
        });

      cells.exit().remove();

      const xTicks = xScale.domain().filter((d, i) => {
        const bw = xScale.bandwidth();
        return bw > 18 ? true : i % Math.ceil(18 / Math.max(bw, 1)) === 0;
      });

      xAxisG.call(
        d3.axisBottom(xScale)
          .tickValues(xTicks)
          .tickFormat(formatTime)
      )
      .selectAll("text")
      .attr("transform", "rotate(-45)")
      .style("text-anchor", "end");

      yAxisG.call(d3.axisLeft(y));
    }

    render();

    function pushRealtimeData() {
      currentTime += 1;

      stocks.forEach(stock => {
        const prev = basePrices.get(stock);
        const next = Math.max(10, prev + (Math.random() - 0.5) * 10);
        basePrices.set(stock, next);
        data.push({
          stock,
          time: currentTime,
          price: +next.toFixed(2)
        });
      });

      const minVisibleTime = currentTime - timeSteps + 1;

      data = data.filter(d => d.time >= minVisibleTime);

      const newDomain = d3.range(minVisibleTime, currentTime + 1);
      x0.domain(newDomain);
      xScale.domain(newDomain);

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [innerWidth, innerHeight]])
      .extent([[0, 0], [innerWidth, innerHeight]])
      .on("zoom", (event) => {
        const t = event.transform;

        const domain = x0.domain();
        const step = x0.step();

        const zx = d3.scaleBand()
          .domain(domain)
          .range([t.applyX(0), t.applyX(innerWidth)])
          .padding(0.03);

        xScale = zx;
        render();
      });

    svg.call(zoom);

    d3.select("#resetZoom").on("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    setInterval(pushRealtimeData, 1000);
  </script>
</body>
