  <script>
    const stocks = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 40;
    const cellSize = 24;
    const margin = { top: 30, right: 20, bottom: 60, left: 70 };

