    function render() {
      updateColorDomain();

      const cells = heatmapGroup.selectAll("rect")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price))
        .on("mousemove", function(event, d) {
          tooltip
            .style("display", "block")
            .style("left", (event.offsetX + 12) + "px")
            .style("top", (event.offsetY + 12) + "px")
            .html(
              `<strong>${d.stock}</strong><br>` +
              `Time: ${d.time}<br>` +
              `Price: $${d.price}`
            );
        })
        .on("mouseleave", function() {
          tooltip.style("display", "none");
        })
        .merge(cells)
        .transition()
        .duration(400)
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price));

      cells.exit().remove();

      xAxisGroup.call(
        d3.axisBottom(xScale)
          .tickValues(xScale.domain().filter((d, i) => i % 4 === 0))
      );

