    function tick() {
      timestamps = timestamps.map(t => t + 1);

      const latestTime = d3.max(timestamps);

      let newData = [];
      stocks.forEach(stock => {
        const prev = data
          .filter(d => d.stock === stock)
          .sort((a, b) => a.time - b.time);

        const lastPrice = prev[prev.length - 1].price;
        const nextPrice = +(lastPrice + (Math.random() - 0.5) * 6).toFixed(2);

        const shifted = prev.slice(1).map(d => ({
          stock: d.stock,
          time: d.time + 1,
          price: d.price
        }));

        shifted.push({
          stock,
          time: latestTime,
          price: nextPrice
        });

        newData.push(...shifted);
      });

      data = newData;
      timestamps = d3.range(d3.min(data, d => d.time), d3.max(data, d => d.time) + 1);

      xScale.domain(timestamps);
      render();
    }

    setInterval(tick, 1000);

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function zoomed(event) {
      const transform = event.transform;
      heatmapGroup.attr("transform", transform);

      const zx = transform.rescaleX(
        d3.scaleLinear()
          .domain([0, timestamps.length])
          .range([0, innerWidth])
      );

      const visibleTicks = timestamps.filter((d, i) => {
        const px = zx(i);
        return px >= 0 && px <= innerWidth;
      });

      const zoomedXScale = d3.scaleBand()
        .domain(timestamps)
        .range([transform.applyX(0), transform.applyX(innerWidth)])
        .padding(0.04);

      heatmapGroup.selectAll("rect")
        .attr("x", d => zoomedXScale(d.time))
        .attr("width", zoomedXScale.bandwidth() * transform.k)
        .attr("y", d => yScale(d.stock))
        .attr("height", yScale.bandwidth());

      xAxisGroup.call(
        d3.axisBottom(zoomedXScale)
          .tickValues(visibleTicks.filter((d, i) => i % 2 === 0))
      );
    }
  </script>
</body>
</html>
```

