  </style>
</head>
<body>
  <div class="container">
    <h1>Realtime Stock Price Heatmap</h1>
    <div id="chart"></div>
  </div>
  <div class="tooltip" id="tooltip"></div>

  <script>
    const symbols = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const maxColumns = 60;
    const cellWidth = 18;
    const cellHeight = 28;
    const margin = { top: 30, right: 20, bottom: 40, left: 70 };

    const width = margin.left + margin.right + maxColumns * cellWidth;
    const height = margin.top + margin.bottom + symbols.length * cellHeight;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height);

    const root = svg.append("g");
    const plot = root.append("g").attr("class", "plot");

    const tooltip = d3.select("#tooltip");

    let timeIndex = 0;
    let data = [];
    let prices = Object.fromEntries(
      symbols.map(s => [s, 100 + Math.random() * 200])
    );

    const color = d3.scaleLinear()
      .domain([-3, 0, 3])
      .range(["#b30000", "#222", "#00c853"])
      .clamp(true);

    const xScale = d3.scaleBand()
      .domain(d3.range(maxColumns))
      .range([margin.left, margin.left + maxColumns * cellWidth])
      .paddingInner(0.05);

    const yScale = d3.scaleBand()
      .domain(symbols)
      .range([margin.top, margin.top + symbols.length * cellHeight])
      .paddingInner(0.05);

    const xAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${margin.top + symbols.length * cellHeight})`);

    const yAxisG = root.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(${margin.left},0)`);

    function renderAxes() {
      const visibleTicks = xScale.domain().filter(d => d % 5 === 0);
      xAxisG.call(d3.axisBottom(xScale).tickValues(visibleTicks).tickFormat(d => `T-${maxColumns - 1 - d}`));
      yAxisG.call(d3.axisLeft(yScale));
    }

    function generateNextColumn() {
      const col = [];

      symbols.forEach(symbol => {
        const oldPrice = prices[symbol];
        const changePct = (Math.random() - 0.5) * 2.5; // about -1.25% to +1.25%
        const newPrice = oldPrice * (1 + changePct / 100);
        prices[symbol] = newPrice;

        col.push({
          symbol,
          time: timeIndex,
          displayTime: new Date().toLocaleTimeString(),
          price: newPrice,
          changePct
        });
      });

      timeIndex++;
      return col;
    }

    function pushData() {
      const next = generateNextColumn();
      data.push(next);

      if (data.length > maxColumns) {
        data.shift();
      }

      update();
    }

    function flattenData() {
      return data.flatMap((column, colIdx) =>
        column.map(d => ({
          ...d,
          colIdx
        }))
      );
    }

    function update() {
      const flat = flattenData();

      xScale.domain(d3.range(data.length));

      const cells = plot.selectAll("rect.cell")
        .data(flat, d => `${d.symbol}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.colIdx))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => color(d.changePct))
        .on("mousemove", (event, d) => {
          tooltip
            .style("opacity", 1)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY + 10) + "px")
            .html(`
              <strong>${d.symbol}</strong><br>
              Time: ${d.displayTime}<br>
              Price: $${d.price.toFixed(2)}<br>
              Change: ${d.changePct.toFixed(2)}%
            `);
        })
        .on("mouseleave", () => {
          tooltip.style("opacity", 0);
        })
        .merge(cells)
        .transition()
        .duration(300)
        .attr("x", d => xScale(d.colIdx))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => color(d.changePct));

      cells.exit().remove();

      renderAxes();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        plot.attr("transform", event.transform);
        xAxisG.attr(
          "transform",
          `translate(${event.transform.x},${margin.top + symbols.length * cellHeight + event.transform.y}) scale(${event.transform.k},1)`
        );
        yAxisG.attr(
          "transform",
          `translate(${margin.left + event.transform.x},${event.transform.y}) scale(1,${event.transform.k})`
        );
      });

    svg.call(zoom);

    // Seed initial data
    for (let i = 0; i < 20; i++) {
      pushData();
    }

    // Realtime updates
    setInterval(pushData, 1000);
  </script>
</body>
</html>
