</head>
<body>
  <div class="container">
    <h1>Realtime Stock Price Heatmap</h1>
    <div class="controls">
      <button id="resetZoom">Reset Zoom</button>
      <span>Pan: drag | Zoom: mouse wheel</span>
    </div>
    <svg id="chart" width="1100" height="520"></svg>
    <div class="legend">Color shows % change from previous value (red = down, green = up)</div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    const svg = d3.select("#chart");
    const tooltip = d3.select("#tooltip");

    const margin = { top: 20, right: 20, bottom: 80, left: 80 };
    const width = +svg.attr("width") - margin.left - margin.right;
    const height = +svg.attr("height") - margin.top - margin.bottom;

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const plot = root.append("g");
    const xAxisG = root.append("g").attr("class", "axis").attr("transform", `translate(0,${height})`);
    const yAxisG = root.append("g").attr("class", "axis");

    const stocks = ["AAPL", "MSFT", "GOOG", "AMZN", "TSLA", "NVDA", "META", "NFLX"];
    const timeSteps = 60;

    let timeLabels = d3.range(timeSteps).map(i => i);
    let prices = {};
    let data = [];

    stocks.forEach(symbol => {
      prices[symbol] = 100 + Math.random() * 200;
    });

    function generateInitialData() {
      const rows = [];
      const localPrices = { ...prices };

      for (let t = 0; t < timeSteps; t++) {
        stocks.forEach(symbol => {
          const prev = localPrices[symbol];
          const next = prev * (1 + (Math.random() - 0.5) * 0.03);
          const changePct = ((next - prev) / prev) * 100;
          localPrices[symbol] = next;

          rows.push({
            stock: symbol,
            time: t,
            price: next,
            changePct
          });
        });
      }

      stocks.forEach(symbol => {
        const latest = rows.filter(d => d.stock === symbol).at(-1);
        prices[symbol] = latest.price;
      });

      return rows;
    }

    data = generateInitialData();

    const xBase = d3.scaleBand()
      .domain(timeLabels)
      .range([0, width])
      .padding(0.03);

    const yScale = d3.scaleBand()
      .domain(stocks)
      .range([0, height])
      .padding(0.03);

    const colorScale = d3.scaleLinear()
      .domain([-3, 0, 3])
      .range(["#b22222", "#222", "#00c853"])
      .clamp(true);

    let currentTransform = d3.zoomIdentity;

    function getScaledX(transform) {
      const [r0, r1] = [0, width].map(transform.applyX, transform);
      return d3.scaleBand()
        .domain(timeLabels)
        .range([r0, r1])
        .padding(0.03);
    }

    function render() {
      const xScale = getScaledX(currentTransform);

      const cells = plot.selectAll("rect.cell")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.join(
        enter => enter.append("rect")
          .attr("class", "cell")
          .attr("x", d => xScale(d.time))
          .attr("y", d => yScale(d.stock))
          .attr("width", xScale.bandwidth())
          .attr("height", yScale.bandwidth())
          .attr("fill", d => colorScale(d.changePct))
          .on("mousemove", function(event, d) {
            tooltip
              .style("opacity", 1)
              .html(
                `<strong>${d.stock}</strong><br>` +
                `Time: ${d.time}<br>` +
                `Price: ${d.price.toFixed(2)}<br>` +
                `Change: ${d.changePct.toFixed(2)}%`
              )
              .style("left", (event.pageX + 12) + "px")
              .style("top", (event.pageY + 12) + "px");
          })
          .on("mouseleave", function() {
            tooltip.style("opacity", 0);
          }),
        update => update,
        exit => exit.remove()
      )
      .transition()
      .duration(250)
      .attr("x", d => xScale(d.time))
      .attr("y", d => yScale(d.stock))
      .attr("width", xScale.bandwidth())
      .attr("height", yScale.bandwidth())
      .attr("fill", d => colorScale(d.changePct));

      const xTicks = timeLabels.filter((d, i) => i % 5 === 0);
      const xAxis = d3.axisBottom(xScale).tickValues(xTicks);
      const yAxis = d3.axisLeft(yScale);

      xAxisG.call(xAxis);
      yAxisG.call(yAxis);
    }

    function updateData() {
      timeLabels = timeLabels.map(t => t + 1);

      const nextTime = timeLabels[timeLabels.length - 1];
      const newRows = [];

      stocks.forEach(symbol => {
        const prev = prices[symbol];
        const next = prev * (1 + (Math.random() - 0.5) * 0.03);
        const changePct = ((next - prev) / prev) * 100;
        prices[symbol] = next;

        newRows.push({
          stock: symbol,
          time: nextTime,
          price: next,
          changePct
        });
      });

      data = data
        .filter(d => d.time !== Math.min(...data.map(x => x.time)))
        .map(d => ({ ...d, time: d.time }))
        .concat(newRows);

      const minTime = d3.min(data, d => d.time);
      data = data.filter(d => d.time >= minTime);

      timeLabels = d3.range(nextTime - timeSteps + 1, nextTime + 1);
      xBase.domain(timeLabels);

      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        render();
      });

    svg.call(zoom);

    d3.select("#resetZoom").on("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    render();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
