```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #111;
      color: #eee;
      overflow: hidden;
    }

    #toolbar {
      height: 44px;
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 0 12px;
      background: #1b1b1b;
      border-bottom: 1px solid #333;
      font-size: 14px;
    }

    #container {
      width: 100vw;
      height: calc(100vh - 45px);
      position: relative;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      background: #0b0f14;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .legend {
      position: absolute;
      right: 12px;
      top: 12px;
      background: rgba(0,0,0,0.6);
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      border: 1px solid #333;
    }

    .legend-bar {
      width: 140px;
      height: 12px;
      margin: 6px 0 4px;
      background: linear-gradient(to right, #b00020, #333, #00c853);
      border: 1px solid #555;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <strong>Realtime Stock Heatmap</strong>
    <span>Wheel: zoom</span>
    <span>Drag: pan</span>
    <button id="resetBtn">Reset View</button>
  </div>

  <div id="container">
    <canvas id="heatmap"></canvas>
    <div class="legend">
      <div>Price Change</div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between;">
        <span>-5%</span>
        <span>0%</span>
        <span>+5%</span>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const container = document.getElementById('container');
    const resetBtn = document.getElementById('resetBtn');

    const ROWS = 30;   // stocks
    const COLS = 120;  // time buckets
    const stockNames = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);

    // Heatmap data: each row is a stock, each column is a time slice
    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => (Math.random() - 0.5) * 2)
    );

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = container.clientWidth * dpr;
      canvas.height = container.clientHeight * dpr;
      canvas.style.width = container.clientWidth + 'px';
      canvas.style.height = container.clientHeight + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function colorForValue(v) {
      // Clamp to [-5, 5]
      const x = Math.max(-5, Math.min(5, v));
      if (x < 0) {
        const t = (x + 5) / 5; // 0..1
        const r = 176 + (51 - 176) * t;
        const g = 0 + (51 - 0) * t;
        const b = 32 + (51 - 32) * t;
        return `rgb(${r|0},${g|0},${b|0})`;
      } else {
        const t = x / 5; // 0..1
        const r = 51 + (0 - 51) * t;
        const g = 51 + (200 - 51) * t;
        const b = 51 + (83 - 51) * t;
        return `rgb(${r|0},${g|0},${b|0})`;
      }
    }

    function draw() {
      const width = container.clientWidth;
      const height = container.clientHeight;

      ctx.clearRect(0, 0, width, height);

      const labelWidth = 70;
      const topPad = 20;

      const gridX = labelWidth + offsetX;
      const gridY = topPad + offsetY;
      const cellW = (width - labelWidth) / COLS * scale;
      const cellH = (height - topPad) / ROWS * scale;

      // Background
      ctx.fillStyle = '#0b0f14';
      ctx.fillRect(0, 0, width, height);

      // Draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = gridX + c * cellW;
          const y = gridY + r * cellH;

          if (x + cellW < labelWidth || x > width || y + cellH < 0 || y > height) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW, cellH);

          // Optional grid line
          if (cellW > 6 && cellH > 6) {
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.strokeRect(x, y, cellW, cellH);
          }
        }
      }

      // Row labels
      ctx.fillStyle = '#ccc';
      ctx.font = '12px Arial';
      ctx.textBaseline = 'middle';
      for (let r = 0; r < ROWS; r++) {
        const y = gridY + r * cellH + cellH / 2;
        if (y < 0 || y > height) continue;
        ctx.fillText(stockNames[r], 8, y);
      }

      // Time axis markers
      ctx.fillStyle = '#aaa';
      ctx.textBaseline = 'top';
      const step = Math.max(1, Math.floor(12 / scale));
      for (let c = 0; c < COLS; c += step) {
        const x = gridX + c * cellW;
        if (x < labelWidth || x > width) continue;
        ctx.fillText(String(c), x + 2, 2);
      }

      // Divider
      ctx.strokeStyle = '#444';
      ctx.beginPath();
      ctx.moveTo(labelWidth, 0);
      ctx.lineTo(labelWidth, height);
      ctx.stroke();
    }

    function tickData() {
      // Shift left and append new realtime values
      for (let r = 0; r < ROWS; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        const next = prev + (Math.random() - 0.5) * 1.2;
        data[r].push(Math.max(-5, Math.min(5, next)));
      }
      draw();
    }

    // Zoom
    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;

      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      const oldScale = scale;
      scale = Math.max(0.5, Math.min(8, scale * zoomFactor));

      // Zoom around cursor
      offsetX = mouseX - ((mouseX - offsetX) / oldScale) * scale;
      offsetY = mouseY - ((mouseY - offsetY) / oldScale) * scale;

      draw();
    }, { passive: false });

    // Pan
    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      offsetX += dx;
      offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      canvas.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    window.addEventListener('resize', resize);

    resize();
    setInterval(tickData, 500);
  </script>
</body>
</html>
```

