    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      canvas.width = container.clientWidth;
      canvas.height = container.clientHeight;
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // map roughly -5..+5 to red..neutral..green
      const min = -5;
      const max = 5;
      const x = clamp((v - min) / (max - min), 0, 1);

      if (x < 0.5) {
        // red -> dark neutral
        const t = x / 0.5;
        const r = Math.round(139 + (34 - 139) * t);
        const g = Math.round(0 + (34 - 0) * t);
        const b = Math.round(0 + (34 - 0) * t);
        return `rgb(${r},${g},${b})`;
      } else {
        // dark neutral -> green
        const t = (x - 0.5) / 0.5;
        const r = Math.round(34 + (0 - 34) * t);
        const g = Math.round(34 + (100 - 34) * t);
        const b = Math.round(34 + (0 - 34) * t);
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const labelWidth = 70;
      const topPad = 20;

      const heatmapX = labelWidth + offsetX;
      const heatmapY = topPad + offsetY;
      const cellW = (canvas.width - labelWidth) / COLS * scale;
      const cellH = (canvas.height - topPad) / ROWS * scale;

      // background
      ctx.fillStyle = '#0b0b0b';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = heatmapX + c * cellW;
          const y = heatmapY + r * cellH;

          if (x + cellW < labelWidth || x > canvas.width || y + cellH < topPad || y > canvas.height) {
            continue;
          }

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, Math.ceil(cellW), Math.ceil(cellH));
        }
      }

      // grid lines
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      for (let r = 0; r <= ROWS; r++) {
        const y = heatmapY + r * cellH;
        ctx.beginPath();
        ctx.moveTo(labelWidth, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }
      for (let c = 0; c <= COLS; c++) {
        const x = heatmapX + c * cellW;
        ctx.beginPath();
        ctx.moveTo(x, topPad);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }

      // row labels
      ctx.fillStyle = '#ccc';
      ctx.font = '12px Arial';
      ctx.textBaseline = 'middle';
      for (let r = 0; r < ROWS; r++) {
        const y = heatmapY + r * cellH + cellH / 2;
        if (y < topPad || y > canvas.height) continue;
        ctx.fillText(stockLabels[r], 8, y);
      }

      // border separating labels
      ctx.strokeStyle = '#444';
      ctx.beginPath();
      ctx.moveTo(labelWidth, 0);
      ctx.lineTo(labelWidth, canvas.height);
      ctx.stroke();
    }

    function updateData() {
      // shift left, append new values to simulate realtime stream
      for (let r = 0; r < ROWS; r++) {
        data[r].shift();
        const prev = data[r][data[r].length - 1] || 0;
        const next = clamp(prev + (Math.random() - 0.5) * 1.2, -5, 5);
        data[r].push(next);
      }
    }

    function tick() {
      if (streaming) {
        updateData();
        draw();
      }
    }

    // Zoom around mouse pointer
    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const prevScale = scale;
      scale = clamp(scale * zoomFactor, 0.5, 8);

      const mx = e.offsetX;
      const my = e.offsetY;

      offsetX = mx - ((mx - offsetX) * (scale / prevScale));
      offsetY = my - ((my - offsetY) * (scale / prevScale));

      draw();
    }, { passive: false });

