      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      offsetX += dx;
      offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    resetViewBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    toggleStreamBtn.addEventListener('click', () => {
