  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const resetBtn = document.getElementById('resetBtn');

    const stocks = [
      "AAPL","MSFT","GOOG","AMZN","TSLA","NVDA","META","NFLX","AMD","INTC",
      "ORCL","IBM","CRM","UBER","SHOP","BABA","SONY","SQ","PYPL","ADBE"
    ];

    const timeSteps = 120;
    let data = stocks.map(() =>
      Array.from({ length: timeSteps }, () => (Math.random() - 0.5) * 2)
    );

    let view = {
      scaleX: 1,
      scaleY: 1,
      offsetX: 0,
      offsetY: 0
    };

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function colorForValue(v) {
      // Clamp to [-5, 5]
      v = Math.max(-5, Math.min(5, v));
      const t = (v + 5) / 10; // 0..1

      // simple blue -> yellow -> red interpolation
      let r, g, b;
      if (t < 0.5) {
        const k = t / 0.5;
        r = Math.round(44 + k * (255 - 44));
        g = Math.round(123 + k * (255 - 123));
        b = Math.round(182 + k * (191 - 182));
      } else {
        const k = (t - 0.5) / 0.5;
        r = Math.round(255 + k * (215 - 255));
        g = Math.round(255 + k * (25 - 255));
        b = Math.round(191 + k * (28 - 191));
      }
      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const baseCellW = width / timeSteps;
      const baseCellH = height / stocks.length;

      const cellW = baseCellW * view.scaleX;
      const cellH = baseCellH * view.scaleY;

      for (let row = 0; row < stocks.length; row++) {
        for (let col = 0; col < timeSteps; col++) {
          const x = col * cellW + view.offsetX;
          const y = row * cellH + view.offsetY;

          if (x + cellW < 0 || x > width || y + cellH < 0 || y > height) continue;

          ctx.fillStyle = colorForValue(data[row][col]);
          ctx.fillRect(x, y, cellW, cellH);
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let row = 0; row <= stocks.length; row++) {
        const y = row * cellH + view.offsetY;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let col = 0; col <= timeSteps; col += 10) {
        const x = col * cellW + view.offsetX;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      // Labels
      ctx.fillStyle = "#ddd";
      ctx.font = "12px sans-serif";
      for (let row = 0; row < stocks.length; row++) {
        const y = row * cellH + view.offsetY + 14;
        if (y > 0 && y < height) {
          ctx.fillText(stocks[row], 6, y);
        }
      }
    }

    function tickData() {
      for (let i = 0; i < stocks.length; i++) {
        const prev = data[i][data[i].length - 1];
        const next = prev + (Math.random() - 0.5) * 0.8;
        data[i].push(next);
        if (data[i].length > timeSteps) data[i].shift();
      }
      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoom = e.deltaY < 0 ? 1.1 : 0.9;

      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      view.offsetX = mouseX - (mouseX - view.offsetX) * zoom;
      view.offsetY = mouseY - (mouseY - view.offsetY) * zoom;
      view.scaleX *= zoom;
      view.scaleY *= zoom;

      view.scaleX = Math.max(0.5, Math.min(8, view.scaleX));
      view.scaleY = Math.max(0.5, Math.min(8, view.scaleY));

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      view.offsetX += dx;
      view.offsetY += dy;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    resetBtn.addEventListener('click', () => {
      view = { scaleX: 1, scaleY: 1, offsetX: 0, offsetY: 0 };
      draw();
    });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    draw();
    setInterval(tickData, 500);
  </script>
