      if (clamped >= 0) {
        const light = 20 + clamped * 6;
        return `hsl(145, 70%, ${light}%)`;
      } else {
        const light = 20 + Math.abs(clamped) * 6;
        return `hsl(0, 75%, ${light}%)`;
      }
    }

    function renderCells() {
      world.innerHTML = "";
      for (const s of stocks) {
        const el = document.createElement("div");
        el.className = "cell";
        el.style.left = s.x + "px";
        el.style.top = s.y + "px";
        el.style.width = s.w + "px";
        el.style.height = s.h + "px";

        el.innerHTML = `
          <div class="symbol">${s.symbol}</div>
          <div class="price">$${s.price.toFixed(2)}</div>
          <div class="change">${s.changePct >= 0 ? "+" : ""}${s.changePct.toFixed(2)}%</div>
        `;
        world.appendChild(el);
        s.el = el;
        updateCell(s);
      }
    }

    function updateCell(s) {
      s.el.style.background = colorForChange(s.changePct);
      s.el.querySelector(".price").textContent = `$${s.price.toFixed(2)}`;
      s.el.querySelector(".change").textContent =
        `${s.changePct >= 0 ? "+" : ""}${s.changePct.toFixed(2)}%`;
    }

    // Simulated realtime updates
    function tick() {
      const updates = 1 + Math.floor(Math.random() * 4);
      for (let i = 0; i < updates; i++) {
        const s = stocks[Math.floor(Math.random() * stocks.length)];
        const deltaPct = (Math.random() - 0.5) * 1.2; // -0.6% to +0.6%
        s.changePct += deltaPct;
        s.changePct = Math.max(-9.99, Math.min(9.99, s.changePct));
        s.price = +(s.price * (1 + deltaPct / 100)).toFixed(2);
        updateCell(s);
      }
    }
    setInterval(tick, 500);

    // Zoom / pan state
    const view = {
      scale: 1,
      minScale: 0.5,
      maxScale: 3,
      x: 40,
      y: 60
    };

    function applyTransform() {
      world.style.transform = `translate(${view.x}px, ${view.y}px) scale(${view.scale})`;
    }

    resetBtn.addEventListener("click", () => {
      view.scale = 1;
      view.x = 40;
      view.y = 60;
      applyTransform();
    });

    // Pan
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let originX = 0;
    let originY = 0;

    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      originX = view.x;
      originY = view.y;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      view.x = originX + (e.clientX - startX);
      view.y = originY + (e.clientY - startY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    // Zoom centered on cursor
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(view.minScale, Math.min(view.maxScale, view.scale * zoomFactor));

      // Keep cursor point stable during zoom
      const worldX = (mouseX - view.x) / view.scale;
      const worldY = (mouseY - view.y) / view.scale;

      view.scale = newScale;
      view.x = mouseX - worldX * view.scale;
      view.y = mouseY - worldY * view.scale;

      applyTransform();
    }, { passive: false });

    layout();
    renderCells();
    applyTransform();
  </script>
</body>
</html>
