      font-size: 14px;
      color: #bbb;
    }

    .wrap {
      position: relative;
      padding: 12px;
    }

    canvas {
      display: block;
      background: #0b0b0b;
      border: 1px solid #333;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(20, 20, 20, 0.95);
      color: white;
      border: 1px solid #555;
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      white-space: nowrap;
      display: none;
      z-index: 20;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="resetBtn">Reset View</button>
    <div class="info">
      Wheel = zoom horizontally/vertically, Drag = pan, Shift+Wheel = vertical zoom
    </div>
  </div>

  <div class="wrap">
    <canvas id="heatmap" width="1200" height="600"></canvas>
    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");

    const W = canvas.width;
    const H = canvas.height;

    // Heatmap dimensions
    const stocks = [
      "AAPL", "MSFT", "GOOG", "AMZN", "TSLA",
      "META", "NVDA", "NFLX", "AMD", "INTC"
    ];
    const rows = stocks.length;
    const cols = 120; // time buckets

    // Data grid: rows x cols, values are % change
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => 0)
    );

    // Seed base values
    for (let r = 0; r < rows; r++) {
      let v = (Math.random() - 0.5) * 2;
      for (let c = 0; c < cols; c++) {
        v += (Math.random() - 0.5) * 0.4;
        v = Math.max(-5, Math.min(5, v));
        data[r][c] = v;
      }
    }

    // View transform
    let view = {
      offsetX: 0,
      offsetY: 0,
      scaleX: 1,
      scaleY: 1
    };

    const baseCellW = W / cols;
    const baseCellH = H / rows;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // Map -5..0..+5 to red..dark..green
      const maxAbs = 5;
      const t = clamp(v / maxAbs, -1, 1);

      if (t >= 0) {
        const g = Math.floor(80 + 175 * t);
        const r = Math.floor(20 * (1 - t));
        return `rgb(${r},${g},40)`;
      } else {
        const a = Math.abs(t);
        const r = Math.floor(80 + 175 * a);
        const g = Math.floor(20 * (1 - a));
        return `rgb(${r},${g},40)`;
      }
    }

    function screenToWorld(sx, sy) {
      return {
        x: (sx - view.offsetX) / view.scaleX,
        y: (sy - view.offsetY) / view.scaleY
      };
    }

    function worldToCell(wx, wy) {
      const c = Math.floor(wx / baseCellW);
      const r = Math.floor(wy / baseCellH);
      return { r, c };
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);

      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);
      ctx.scale(view.scaleX, view.scaleY);

      // Draw cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = c * baseCellW;
          const y = r * baseCellH;
          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, baseCellW, baseCellH);
        }
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1 / Math.max(view.scaleX, view.scaleY);

      for (let c = 0; c <= cols; c++) {
        const x = c * baseCellW;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, H);
        ctx.stroke();
      }

      for (let r = 0; r <= rows; r++) {
        const y = r * baseCellH;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(W, y);
        ctx.stroke();
      }

      // Row labels
      ctx.fillStyle = "white";
      ctx.font = `${12 / view.scaleY}px sans-serif`;
      for (let r = 0; r < rows; r++) {
        const y = r * baseCellH + baseCellH * 0.65;
        ctx.fillText(stocks[r], 4 / view.scaleX, y);
      }

      ctx.restore();
    }

    function updateData() {
      // Shift left and append new values to simulate real-time updates
      for (let r = 0; r < rows; r++) {
        const last = data[r][cols - 1];
        let next = last + (Math.random() - 0.5) * 0.8;
        next = clamp(next, -5, 5);
        data[r].shift();
        data[r].push(next);
      }
      draw();
    }

    // Mouse interactions: pan
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      lastX = e.offsetX;
      lastY = e.offsetY;
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
    });

    canvas.addEventListener("mousemove", (e) => {
      const mx = e.offsetX;
      const my = e.offsetY;

      if (dragging) {
        view.offsetX += mx - lastX;
        view.offsetY += my - lastY;
        lastX = mx;
        lastY = my;
        draw();
      }

      // Tooltip
      const world = screenToWorld(mx, my);
      const cell = worldToCell(world.x, world.y);

      if (
        cell.r >= 0 && cell.r < rows &&
        cell.c >= 0 && cell.c < cols
      ) {
        tooltip.style.display = "block";
        tooltip.style.left = `${mx + 18}px`;
        tooltip.style.top = `${my + 18}px`;
        tooltip.innerHTML = `
          <strong>${stocks[cell.r]}</strong><br>
          Time: ${cell.c}<br>
          Change: ${data[cell.r][cell.c].toFixed(2)}%
        `;
      } else {
        tooltip.style.display = "none";
      }
    });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    // Wheel zoom around cursor
    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.offsetX;
      const mouseY = e.offsetY;

      const before = screenToWorld(mouseX, mouseY);

      if (e.shiftKey) {
        view.scaleY = clamp(view.scaleY * zoomFactor, 0.5, 8);
      } else {
        view.scaleX = clamp(view.scaleX * zoomFactor, 0.5, 8);
      }

      const afterScreenX = before.x * view.scaleX + view.offsetX;
      const afterScreenY = before.y * view.scaleY + view.offsetY;

      view.offsetX += mouseX - afterScreenX;
      view.offsetY += mouseY - afterScreenY;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      view = {
        offsetX: 0,
        offsetY: 0,
        scaleX: 1,
        scaleY: 1
      };
      draw();
    });

    draw();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
