    .toolbar button:hover {
      background: #3a3a3a;
    }

    .toolbar span {
      font-size: 14px;
      color: #aaa;
    }

    #wrap {
      position: relative;
      width: 100vw;
      height: calc(100vh - 52px);
      overflow: hidden;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      background: #0d0d0d;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .legend {
      position: absolute;
      right: 12px;
