      border-radius: 6px;
    }

    .legend-bar {
      width: 140px;
      height: 12px;
      margin: 6px 0;
      background: linear-gradient(to right, #b00020, #333, #00c853);
      border: 1px solid #444;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="resetBtn">Reset View</button>
    <button id="pauseBtn">Pause</button>
    <span>Wheel = zoom, drag = pan, live simulated stock changes</span>
  </div>

  <div id="wrap">
    <canvas id="heatmap"></canvas>
    <div class="legend">
      <div><strong>Price Change</strong></div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between;">
        <span>Down</span>
        <span>Flat</span>
        <span>Up</span>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('wrap');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    const ROWS = 20;   // stocks
    const COLS = 60;   // time buckets
    const stocks = Array.from({ length: ROWS }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);

    let data = Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => (Math.random() - 0.5) * 2)
    );

    let paused = false;

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = wrap.clientWidth * dpr;
      canvas.height = wrap.clientHeight * dpr;
      canvas.style.width = wrap.clientWidth + 'px';
      canvas.style.height = wrap.clientHeight + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v expected roughly in [-5, 5]
      const t = clamp((v + 5) / 10, 0, 1);

      if (t < 0.5) {
        // red -> gray
        const k = t / 0.5;
        const r = Math.round(176 + (51 - 176) * k);
        const g = Math.round(0 + (51 - 0) * k);
        const b = Math.round(32 + (51 - 32) * k);
        return `rgb(${r},${g},${b})`;
      } else {
        // gray -> green
        const k = (t - 0.5) / 0.5;
        const r = Math.round(51 + (0 - 51) * k);
        const g = Math.round(51 + (200 - 51) * k);
        const b = Math.round(51 + (83 - 51) * k);
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const width = wrap.clientWidth;
      const height = wrap.clientHeight;

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = '#0d0d0d';
      ctx.fillRect(0, 0, width, height);

      const labelW = 70;
      const topPad = 20;

      const gridX = labelW + offsetX;
      const gridY = topPad + offsetY;
      const cellW = (width - labelW - 20) / COLS * scale;
      const cellH = (height - topPad - 20) / ROWS * scale;

      // Draw cells
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = gridX + c * cellW;
          const y = gridY + r * cellH;

          // simple viewport culling
          if (x + cellW < labelW || x > width || y + cellH < 0 || y > height) continue;

          ctx.fillStyle = colorForValue(data[r][c]);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);
        }
      }

      // Row labels
      ctx.fillStyle = '#bbb';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let r = 0; r < ROWS; r++) {
        const y = gridY + r * cellH + cellH / 2;
        if (y < 0 || y > height) continue;
        ctx.fillText(stocks[r], labelW - 8, y);
      }

      // Column labels
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillStyle = '#888';
      for (let c = 0; c < COLS; c += 5) {
        const x = gridX + c * cellW + cellW / 2;
        if (x < labelW || x > width) continue;
        ctx.fillText(`T-${COLS - c}`, x, 2);
      }

      // Border around grid area
      ctx.strokeStyle = '#333';
      ctx.strokeRect(gridX, gridY, COLS * cellW, ROWS * cellH);
    }

    function tickData() {
      if (paused) return;

      for (let r = 0; r < ROWS; r++) {
        // shift left
        data[r].shift();

        // new simulated price change with momentum
        const prev = data[r][data[r].length - 1] || 0;
        const next = clamp(prev * 0.7 + (Math.random() - 0.5) * 2.2, -5, 5);
        data[r].push(next);
      }

      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 4);

      // zoom towards mouse point
      const wx = (mx - offsetX) / scale;
      const wy = (my - offsetY) / scale;

      offsetX = mx - wx * newScale;
      offsetY = my - wy * newScale;
      scale = newScale;

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      offsetX += dx;
      offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    pauseBtn.addEventListener('click', () => {
      paused = !paused;
      pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    setInterval(tickData, 500);
  </script>
</body>
</html>
```

## What this does

- Creates a grid where:
  - rows = stocks
  - columns = recent time slices
- Colors represent simulated price movement:
  - **red** = down
  - **gray** = neutral
  - **green** = up
- Every 500ms, new data is pushed in and old data shifts out
- Mouse interactions:
  - **scroll wheel** to zoom
  - **drag** to pan

