      text-anchor: middle;
      dominant-baseline: middle;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    Interactive Stock Heatmap — scroll to zoom, drag to pan
  </div>
  <div id="chart"></div>

  <script>
    const stocks = [
      "AAPL", "MSFT", "GOOG", "AMZN", "META",
      "TSLA", "NVDA", "NFLX", "AMD", "INTC",
      "ORCL", "IBM", "CRM", "ADBE", "UBER",
      "SHOP", "SQ", "PYPL", "BABA", "SONY"
    ].map(symbol => ({
      symbol,
      price: 100 + Math.random() * 200,
      change: (Math.random() - 0.5) * 4
    }));

    const container = document.getElementById("chart");
    const width = container.clientWidth;
    const height = container.clientHeight;

    const cols = 5;
    const rows = Math.ceil(stocks.length / cols);
    const cellWidth = 160;
    const cellHeight = 100;
    const contentWidth = cols * cellWidth;
    const contentHeight = rows * cellHeight;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height);

    const root = svg.append("g");

    const colorScale = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#333333", "#16a34a"]);

    function render() {
      const cells = root.selectAll(".stock")
        .data(stocks, d => d.symbol);

      const enter = cells.enter()
        .append("g")
        .attr("class", "stock");

      enter.append("rect").attr("class", "cell");
      enter.append("text").attr("class", "label");
      enter.append("text").attr("class", "price");

      const merged = enter.merge(cells);

      merged.attr("transform", (d, i) => {
        const x = (i % cols) * cellWidth;
        const y = Math.floor(i / cols) * cellHeight;
        return `translate(${x},${y})`;
      });

      merged.select(".cell")
        .attr("width", cellWidth - 6)
        .attr("height", cellHeight - 6)
        .attr("x", 3)
        .attr("y", 3)
        .attr("rx", 8)
        .attr("fill", d => colorScale(d.change));

      merged.select(".label")
        .attr("x", cellWidth / 2)
        .attr("y", cellHeight / 2 - 12)
        .text(d => d.symbol);

      merged.select(".price")
        .attr("x", cellWidth / 2)
        .attr("y", cellHeight / 2 + 12)
        .text(d => `$${d.price.toFixed(2)} (${d.change.toFixed(2)}%)`);

      cells.exit().remove();
    }

    render();

    function updatePrices() {
      stocks.forEach(stock => {
        const delta = (Math.random() - 0.5) * 1.5;
        stock.change = Math.max(-5, Math.min(5, stock.change + delta));
        stock.price = Math.max(1, stock.price * (1 + delta / 100));
      });
      render();
    }

    setInterval(updatePrices, 1000);

    const zoom = d3.zoom()
      .scaleExtent([0.5, 4])
      .translateExtent([[0, 0], [contentWidth, contentHeight]])
      .on("zoom", (event) => {
        root.attr("transform", event.transform);
      });

    svg.call(zoom);

    const initialScale = Math.min(width / contentWidth, height / contentHeight);
    const initialTransform = d3.zoomIdentity
      .translate(
        (width - contentWidth * initialScale) / 2,
        (height - contentHeight * initialScale) / 2
      )
      .scale(initialScale);

    svg.call(zoom.transform, initialTransform);

    window.addEventListener("resize", () => location.reload());
  </script>
</body>
</html>
```

