Below is a minimal working example of a client-side stock price heatmap with:

- real-time updates
- zoom with mouse wheel
- pan by dragging
- pure HTML/CSS/JS
- no backend required

It uses a canvas and simulates live stock price changes.

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Realtime Stock Heatmap</title>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #111;
      color: #eee;
      overflow: hidden;
    }

    #toolbar {
      position: fixed;
      top: 10px;
      left: 10px;
      z-index: 10;
      background: rgba(0,0,0,0.7);
      padding: 10px 12px;
      border-radius: 8px;
      font-size: 14px;
    }

    #heatmap {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }

    #heatmap:active {
      cursor: grabbing;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Stock Price Heatmap</strong></div>
    <div>Wheel: zoom</div>
    <div>Drag: pan</div>
    <div id="status"></div>
  </div>

  <canvas id="heatmap"></canvas>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const statusEl = document.getElementById('status');

    const rows = 20;
    const cols = 40;
    const stocks = [];
    const labels = [];

    for (let r = 0; r < rows; r++) {
      const row = [];
      for (let c = 0; c < cols; c++) {
        row.push(80 + Math.random() * 40);
        labels.push(`STK${r * cols + c + 1}`);
      }
      stocks.push(row);
    }

    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resizeCanvas() {
      canvas.width = window.innerWidth * devicePixelRatio;
      canvas.height = window.innerHeight * devicePixelRatio;
      canvas.style.width = window.innerWidth + 'px';
      canvas.style.height = window.innerHeight + 'px';
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      draw();
    }

    function getColor(value) {
      // Map price delta-ish range to red/yellow/green
      const min = 70;
      const max = 130;
      const t = Math.max(0, Math.min(1, (value - min) / (max - min)));

      const r = t < 0.5 ? 255 : Math.round(255 * (1 - (t - 0.5) * 2));
      const g = t > 0.5 ? 255 : Math.round(255 * (t * 2));
      const b = 60;

      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const cellW = 80 * scale;
      const cellH = 40 * scale;

      ctx.save();
      ctx.translate(offsetX, offsetY);

      let labelIndex = 0;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = c * cellW;
          const y = r * cellH;
          const price = stocks[r][c];

          ctx.fillStyle = getColor(price);
          ctx.fillRect(x, y, cellW - 2, cellH - 2);

          if (scale > 0.6) {
            ctx.fillStyle = '#000';
            ctx.font = `${Math.max(10, 12 * scale)}px Arial`;
            ctx.fillText(labels[labelIndex], x + 6, y + 14 * scale);
            ctx.fillText(price.toFixed(2), x + 6, y + 30 * scale);
          }

          labelIndex++;
        }
      }

      ctx.restore();

      statusEl.textContent = `Zoom: ${scale.toFixed(2)} | Pan: (${Math.round(offsetX)}, ${Math.round(offsetY)})`;
    }

    function updatePrices() {
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          stocks[r][c] += (Math.random() - 0.5) * 2;
          stocks[r][c] = Math.max(70, Math.min(130, stocks[r][c]));
        }
      }
      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = 1.1;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const prevScale = scale;
      if (e.deltaY < 0) {
        scale *= zoomFactor;
      } else {
        scale /= zoomFactor;
      }
      scale = Math.max(0.3, Math.min(4, scale));

      const wx = (mouseX - offsetX) / prevScale;
      const wy = (mouseY - offsetY) / prevScale;

      offsetX = mouseX - wx * scale;
      offsetY = mouseY - wy * scale;

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    window.addEventListener('resize', resizeCanvas);

    resizeCanvas();
    setInterval(updatePrices, 500);
  </script>
</body>
</html>
```

