# 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const PORT = process.env.PORT || 3000;

app.use(express.static("public"));
app.use(express.json());

const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

function createTask({ title, description = "", assignee = "", dueDate = "" }) {
  const id = uuidv4();
  return {
    id,
    title,
    description,
    assignee,
    dueDate,
    createdAt: new Date().toISOString()
  };
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, assignee, dueDate, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = boardState.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = createTask({ title, description, assignee, dueDate });
  boardState.tasks[task.id] = task;
  column.taskIds.push(task.id);

  io.emit("board:update", boardState);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const task = boardState.tasks[req.params.id];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, assignee, dueDate } = req.body;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (assignee !== undefined) task.assignee = assignee;
  if (dueDate !== undefined) task.dueDate = dueDate;

  io.emit("board:update", boardState);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const taskId = req.params.id;
  const task = boardState.tasks[taskId];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete boardState.tasks[taskId];
  boardState.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  });

  io.emit("board:update", boardState);
  res.json({ success: true });
});

app.post("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  const taskExists = boardState.tasks[taskId];
  if (!taskExists) {
    return res.status(404).json({ error: "Task not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const safeIndex =
    typeof destinationIndex === "number" &&
    destinationIndex >= 0 &&
    destinationIndex <= destinationColumn.taskIds.length
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(safeIndex, 0, taskId);

  io.emit("board:update", boardState);
  res.json({ success: true, board: boardState });
});

io.on("connection", socket => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", payload => {
    const { title, description = "", assignee = "", dueDate = "", columnId } = payload;
    if (!title || !columnId) return;

    const column = boardState.columns.find(c => c.id === columnId);
    if (!column) return;

    const task = createTask({ title, description, assignee, dueDate });
    boardState.tasks[task.id] = task;
    column.taskIds.push(task.id);

    io.emit("board:update", boardState);
  });

  socket.on("task:update", payload => {
    const { id, title, description, assignee, dueDate } = payload;
    const task = boardState.tasks[id];
    if (!task) return;

    if (title !== undefined) task.title = title;
    if (description !== undefined) task.description = description;
    if (assignee !== undefined) task.assignee = assignee;
    if (dueDate !== undefined) task.dueDate = dueDate;

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ id }) => {
    if (!boardState.tasks[id]) return;

    delete boardState.tasks[id];
    boardState.columns.forEach(column => {
      column.taskIds = column.taskIds.filter(taskId => taskId !== id);
    });

    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);
    const task = boardState.tasks[taskId];

    if (!sourceColumn || !destinationColumn || !task) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

    const safeIndex =
      typeof destinationIndex === "number" &&
      destinationIndex >= 0 &&
      destinationIndex <= destinationColumn.taskIds.length
        ? destinationIndex
        : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(safeIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
