import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory data store
const db = {
  projects: {
    "default-project": {
      id: "default-project",
      name: "Website Redesign",
      columns: [
        {
          id: "col-todo",
          title: "To Do",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "col-inprogress",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "col-done",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes",
          assignee: "Alice"
        },
        "task-2": {
          id: "task-2",
          title: "Define color palette",
          description: "Pick brand colors for the redesign",
          assignee: "Bob"
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page hero",
          description: "Implement hero section in React",
          assignee: "Charlie"
        }
      }
    }
  }
};

function getProject(projectId) {
  return db.projects[projectId];
}

app.get("/api/projects/:projectId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const { columnId, title, description = "", assignee = "" } = req.body;
  const column = project.columns.find((c) => c.id === columnId);

  if (!column) {
    return res.status(400).json({ error: "Column not found" });
  }

  const taskId = uuidv4();
  const task = {
    id: taskId,
    title,
    description,
    assignee
  };

  project.tasks[taskId] = task;
  column.taskIds.push(taskId);

  io.to(project.id).emit("project:update", project);
  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const task = project.tasks[req.params.taskId];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, assignee } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (assignee !== undefined) task.assignee = assignee;

  io.to(project.id).emit("project:update", project);
  res.json(task);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const taskId = req.params.taskId;
  if (!project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  io.to(project.id).emit("project:update", project);
  res.status(204).send();
});

app.put("/api/projects/:projectId/reorder", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const { columns } = req.body;
  project.columns = columns;

  io.to(project.id).emit("project:update", project);
  res.json(project);
});

io.on("connection", (socket) => {
  socket.on("project:join", (projectId) => {
    socket.join(projectId);
    const project = getProject(projectId);
    if (project) {
      socket.emit("project:update", project);
    }
  });

  socket.on("task:create", ({ projectId, columnId, title, description, assignee }) => {
    const project = getProject(projectId);
    if (!project) return;

    const column = project.columns.find((c) => c.id === columnId);
    if (!column) return;

    const taskId = uuidv4();
    const task = { id: taskId, title, description, assignee };
    project.tasks[taskId] = task;
    column.taskIds.push(taskId);

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:update", ({ projectId, taskId, updates }) => {
    const project = getProject(projectId);
    if (!project || !project.tasks[taskId]) return;

    project.tasks[taskId] = {
      ...project.tasks[taskId],
      ...updates
    };

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:delete", ({ projectId, taskId }) => {
    const project = getProject(projectId);
    if (!project || !project.tasks[taskId]) return;

    delete project.tasks[taskId];
    project.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });

    io.to(projectId).emit("project:update", project);
  });

  socket.on("board:reorder", ({ projectId, columns }) => {
    const project = getProject(projectId);
    if (!project) return;

    project.columns = columns;
    io.to(projectId).emit("project:update", project);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
