## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const SERVER_URL = "http://localhost:4000";
const PROJECT_ID = "default-project";

const socket = io(SERVER_URL, {
  autoConnect: true
});

function App() {
  const [project, setProject] = useState(null);
  const [newTask, setNewTask] = useState({
    title: "",
    description: "",
    assignee: "",
    columnId: "col-todo"
  });

  useEffect(() => {
    socket.emit("project:join", PROJECT_ID);

    socket.on("project:update", (updatedProject) => {
      setProject(updatedProject);
    });

    return () => {
      socket.off("project:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columnsById = useMemo(() => {
    if (!project) return {};
    return Object.fromEntries(project.columns.map((col) => [col.id, col]));
  }, [project]);

  function findTaskLocation(taskId) {
    for (const column of project.columns) {
      const index = column.taskIds.indexOf(taskId);
      if (index !== -1) {
        return { columnId: column.id, index };
      }
    }
    return null;
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !project) return;

    const activeTaskId = active.id;
    const overId = over.id;

    const source = findTaskLocation(activeTaskId);
    if (!source) return;

    let destination = findTaskLocation(overId);

    if (!destination) {
      const overColumn = project.columns.find((col) => col.id === overId);
      if (overColumn) {
        destination = {
          columnId: overColumn.id,
          index: overColumn.taskIds.length
        };
      }
    }

    if (!destination) return;

    const updatedColumns = project.columns.map((col) => ({
      ...col,
      taskIds: [...col.taskIds]
    }));

    const sourceColumn = updatedColumns.find((c) => c.id === source.columnId);
    const destColumn = updatedColumns.find((c) => c.id === destination.columnId);

    sourceColumn.taskIds.splice(source.index, 1);

    let insertIndex = destination.index;
    if (
      source.columnId === destination.columnId &&
      source.index < destination.index
    ) {
      insertIndex -= 1;
    }

    destColumn.taskIds.splice(insertIndex, 0, activeTaskId);

    socket.emit("board:reorder", {
      projectId: PROJECT_ID,
      columns: updatedColumns
    });
  }

  function createTask(e) {
    e.preventDefault();
    if (!newTask.title.trim()) return;

    socket.emit("task:create", {
      projectId: PROJECT_ID,
      columnId: newTask.columnId,
      title: newTask.title,
      description: newTask.description,
      assignee: newTask.assignee
    });

    setNewTask({
      title: "",
      description: "",
      assignee: "",
      columnId: "col-todo"
    });
  }

  function updateTask(taskId, updates) {
    socket.emit("task:update", {
      projectId: PROJECT_ID,
      taskId,
      updates
    });
  }

  function deleteTask(taskId) {
    socket.emit("task:delete", {
      projectId: PROJECT_ID,
      taskId
    });
  }

  if (!project) {
    return <div className="loading">Loading project...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>{project.name}</h1>
        <p>Real-time collaborative task board</p>
      </header>

      <section className="task-form-section">
        <form className="task-form" onSubmit={createTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTask.title}
            onChange={(e) => setNewTask((prev) => ({ ...prev, title: e.target.value }))}
            required
          />
          <input
            type="text"
            placeholder="Description"
            value={newTask.description}
            onChange={(e) =>
              setNewTask((prev) => ({ ...prev, description: e.target.value }))
            }
          />
          <input
            type="text"
            placeholder="Assignee"
            value={newTask.assignee}
            onChange={(e) =>
              setNewTask((prev) => ({ ...prev, assignee: e.target.value }))
            }
          />
          <select
            value={newTask.columnId}
            onChange={(e) =>
              setNewTask((prev) => ({ ...prev, columnId: e.target.value }))
            }
          >
            {project.columns.map((column) => (
              <option key={column.id} value={column.id}>
                {column.title}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </section>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {project.columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={column.taskIds.map((taskId) => project.tasks[taskId]).filter(Boolean)}
              onUpdateTask={updateTask}
              onDeleteTask={deleteTask}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, onUpdateTask, onDeleteTask }) {
  return (
    <div className="column" id={column.id}>
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onUpdateTask={onUpdateTask}
              onDeleteTask={onDeleteTask}
            />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, onUpdateTask, onDeleteTask }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(task);

  useEffect(() => {
    setDraft(task);
  }, [task]);

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  function save() {
    onUpdateTask(task.id, draft);
    setEditing(false);
  }

  return (
    <div ref={setNodeRef} style={style} className="task-card">
      <div className="drag-handle" {...attributes} {...listeners}>
        ⋮⋮
      </div>

      {editing ? (
        <div className="task-edit">
          <input
            value={draft.title}
            onChange={(e) => setDraft((prev) => ({ ...prev, title: e.target.value }))}
          />
          <textarea
            value={draft.description}
            onChange={(e) => setDraft((prev) => ({ ...prev, description: e.target.value }))}
          />
          <input
            value={draft.assignee}
            onChange={(e) => setDraft((prev) => ({ ...prev, assignee: e.target.value }))}
          />
          <div className="task-actions">
            <button onClick={save}>Save</button>
            <button onClick={() => setEditing(false)} className="secondary">
              Cancel
            </button>
          </div>
        </div>
      ) : (
        <div className="task-content">
          <h3>{task.title}</h3>
          <p>{task.description}</p>
          <span className="assignee">{task.assignee}</span>
          <div className="task-actions">
            <button onClick={() => setEditing(true)}>Edit</button>
            <button onClick={() => onDeleteTask(task.id)} className="danger">
              Delete
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
```

