const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

const PORT = 4000;

// In-memory board state
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        {
          id: "task-1",
          title: "Set up project repository",
          description: "Initialize repo and add README",
          assignee: "Alice"
        },
        {
          id: "task-2",
          title: "Create wireframes",
          description: "Prepare UI wireframes for dashboard",
          assignee: "Bob"
        }
      ]
    },
    {
      id: "in-progress",
      title: "In Progress",
      tasks: [
        {
          id: "task-3",
          title: "Build drag-and-drop UI",
          description: "Implement board interactions",
          assignee: "Charlie"
        }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/task", (req, res) => {
  const { columnId, task } = req.body;

  const column = boardState.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const newTask = {
    id: `task-${Date.now()}`,
    title: task.title || "Untitled Task",
    description: task.description || "",
    assignee: task.assignee || ""
  };

  column.tasks.push(newTask);

  broadcast({
    type: "BOARD_UPDATE",
    payload: boardState
  });

  res.json(newTask);
});

app.put("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;
  const updates = req.body;

  for (const column of boardState.columns) {
    const task = column.tasks.find(t => t.id === taskId);
    if (task) {
      Object.assign(task, updates);

      broadcast({
        type: "BOARD_UPDATE",
        payload: boardState
      });

      return res.json(task);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const column of boardState.columns) {
    const index = column.tasks.findIndex(t => t.id === taskId);
    if (index !== -1) {
      const [deleted] = column.tasks.splice(index, 1);

      broadcast({
        type: "BOARD_UPDATE",
        payload: boardState
      });

      return res.json(deleted);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.post("/api/move-task", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  if (
    sourceIndex < 0 ||
    sourceIndex >= sourceColumn.tasks.length ||
    destinationIndex < 0
  ) {
    return res.status(400).json({ error: "Invalid indexes" });
  }

  const [movedTask] = sourceColumn.tasks.splice(sourceIndex, 1);
  destinationColumn.tasks.splice(destinationIndex, 0, movedTask);

  broadcast({
    type: "BOARD_UPDATE",
    payload: boardState
  });

  res.json(boardState);
});

wss.on("connection", ws => {
  ws.send(
    JSON.stringify({
      type: "BOARD_UPDATE",
      payload: boardState
    })
  );

  ws.on("message", message => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

