# 5. `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let boardState = { columns: [] };
let draggedTaskId = null;
let draggedFromColumnId = null;
let draggedFromIndex = null;
let socket = null;

const boardEl = document.getElementById("board");
const connectionStatusEl = document.getElementById("connectionStatus");
const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const taskAssignee = document.getElementById("taskAssignee");
const taskColumn = document.getElementById("taskColumn");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

function connectWebSocket() {
  socket = new WebSocket(WS_URL);

  socket.addEventListener("open", () => {
    connectionStatusEl.textContent = "Connected";
    connectionStatusEl.style.color = "lightgreen";
  });

  socket.addEventListener("close", () => {
    connectionStatusEl.textContent = "Disconnected - retrying...";
    connectionStatusEl.style.color = "orange";
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener("message", event => {
    const message = JSON.parse(event.data);

    if (message.type === "BOARD_UPDATE") {
      boardState = message.payload;
      renderBoard();
    }
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.tasks.length})`;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      taskListEl.classList.add("drop-zone-active");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drop-zone-active");
    });

    taskListEl.addEventListener("drop", async e => {
      e.preventDefault();
      taskListEl.classList.remove("drop-zone-active");

      const destinationColumnId = column.id;
      const destinationIndex = column.tasks.length;

      if (draggedTaskId == null || draggedFromColumnId == null || draggedFromIndex == null) {
        return;
      }

      await fetch(`${API_URL}/move-task`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          sourceIndex: draggedFromIndex,
          destinationIndex
        })
      });

      resetDragState();
    });

    column.tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        draggedFromIndex = index;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description)}</p>
        <p><strong>Assignee:</strong> ${escapeHtml(task.assignee)}</p>
        <div class="actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.querySelector(".edit-btn").addEventListener("click", async () => {
        const newTitle = prompt("Edit title:", task.title);
        if (newTitle === null) return;

        const newDescription = prompt("Edit description:", task.description);
        if (newDescription === null) return;

        const newAssignee = prompt("Edit assignee:", task.assignee);
        if (newAssignee === null) return;

        await fetch(`${API_URL}/task/${task.id}`, {
          method: "PUT",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            title: newTitle,
            description: newDescription,
            assignee: newAssignee
          })
        });
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", async () => {
        const confirmed = confirm(`Delete "${task.title}"?`);
        if (!confirmed) return;

        await fetch(`${API_URL}/task/${task.id}`, {
          method: "DELETE"
        });
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

taskForm.addEventListener("submit", async e => {
  e.preventDefault();

  const title = taskTitle.value.trim();
  const description = taskDescription.value.trim();
  const assignee = taskAssignee.value.trim();
  const columnId = taskColumn.value;

  if (!title) return;

  await fetch(`${API_URL}/task`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      columnId,
      task: {
        title,
        description,
        assignee
      }
    })
  });

  taskForm.reset();
});

function resetDragState() {
  draggedTaskId = null;
  draggedFromColumnId = null;
  draggedFromIndex = null;
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

fetchBoard();
connectWebSocket();
```

