const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

/**
 * In-memory data store
 * Replace with a DB in production
 */
const store = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        { id: "todo", title: "To Do", taskIds: [] },
        { id: "inprogress", title: "In Progress", taskIds: [] },
        { id: "done", title: "Done", taskIds: [] }
      ],
      tasks: {}
    }
  ]
};

// Seed sample tasks
const sampleTasks = [
  {
    id: uuidv4(),
    title: "Create landing page wireframe",
    description: "Design initial wireframe for homepage",
    assignee: "Alice",
    priority: "High"
  },
  {
    id: uuidv4(),
    title: "Set up analytics",
    description: "Integrate Google Analytics",
    assignee: "Bob",
    priority: "Medium"
  },
  {
    id: uuidv4(),
    title: "Write hero section copy",
    description: "Draft marketing copy for hero section",
    assignee: "Carol",
    priority: "Low"
  }
];

store.projects[0].tasks[sampleTasks[0].id] = sampleTasks[0];
store.projects[0].tasks[sampleTasks[1].id] = sampleTasks[1];
store.projects[0].tasks[sampleTasks[2].id] = sampleTasks[2];

store.projects[0].columns[0].taskIds.push(sampleTasks[0].id, sampleTasks[1].id);
store.projects[0].columns[1].taskIds.push(sampleTasks[2].id);

function getProject(projectId) {
  return store.projects.find((p) => p.id === projectId);
}

app.get("/api/projects", (req, res) => {
  res.json(store.projects);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const project = {
    id: uuidv4(),
    name: name || "Untitled Project",
    columns: [
      { id: "todo", title: "To Do", taskIds: [] },
      { id: "inprogress", title: "In Progress", taskIds: [] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {}
  };
  store.projects.push(project);
  io.emit("projects:update", store.projects);
  res.status(201).json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const { projectId } = req.params;
  const { title, description, assignee, priority, columnId } = req.body;

  const project = getProject(projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const task = {
    id: uuidv4(),
    title,
    description: description || "",
    assignee: assignee || "",
    priority: priority || "Medium"
  };

  project.tasks[task.id] = task;

  const column = project.columns.find((c) => c.id === (columnId || "todo"));
  if (!column) {
    return res.status(400).json({ error: "Invalid column" });
  }

  column.taskIds.push(task.id);

  io.emit("project:update", project);
  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const project = getProject(projectId);
  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  project.tasks[taskId] = {
    ...project.tasks[taskId],
    ...req.body
  };

  io.emit("project:update", project);
  res.json(project.tasks[taskId]);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const project = getProject(projectId);
  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  io.emit("project:update", project);
  res.json({ success: true });
});

app.post("/api/projects/:projectId/reorder", (req, res) => {
  const { projectId } = req.params;
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const project = getProject(projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid columns" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("project:update", project);
  res.json(project);
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("projects:init", store.projects);

  socket.on("join:project", (projectId) => {
    socket.join(projectId);
    const project = getProject(projectId);
    if (project) {
      socket.emit("project:update", project);
    }
  });

  socket.on("task:create", ({ projectId, task }) => {
    const project = getProject(projectId);
    if (!project) return;

    const newTask = {
      id: uuidv4(),
      title: task.title,
      description: task.description || "",
      assignee: task.assignee || "",
      priority: task.priority || "Medium"
    };

    project.tasks[newTask.id] = newTask;
    const column = project.columns.find((c) => c.id === (task.columnId || "todo"));
    if (column) column.taskIds.push(newTask.id);

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:update", ({ projectId, taskId, updates }) => {
    const project = getProject(projectId);
    if (!project || !project.tasks[taskId]) return;

    project.tasks[taskId] = {
      ...project.tasks[taskId],
      ...updates
    };

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:delete", ({ projectId, taskId }) => {
    const project = getProject(projectId);
    if (!project || !project.tasks[taskId]) return;

    delete project.tasks[taskId];
    project.columns.forEach((col) => {
      col.taskIds = col.taskIds.filter((id) => id !== taskId);
    });

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:move", ({ projectId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId }) => {
    const project = getProject(projectId);
    if (!project) return;

    const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);
    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds.splice(sourceIndex, 1);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.to(projectId).emit("project:update", project);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
