# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let projects = [];
let currentProjectId = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const projectSelect = document.getElementById("projectSelect");
const board = document.getElementById("board");
const newTaskBtn = document.getElementById("newTaskBtn");
const newProjectBtn = document.getElementById("newProjectBtn");

const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");

const projectDialog = document.getElementById("projectDialog");
const projectForm = document.getElementById("projectForm");
const cancelProjectBtn = document.getElementById("cancelProjectBtn");

async function fetchProjects() {
  const res = await fetch(`${API_URL}/projects`);
  projects = await res.json();
  renderProjectOptions();

  if (!currentProjectId && projects.length) {
    currentProjectId = projects[0].id;
    socket.emit("join:project", currentProjectId);
  }

  renderBoard();
}

function getCurrentProject() {
  return projects.find((p) => p.id === currentProjectId);
}

function renderProjectOptions() {
  projectSelect.innerHTML = "";
  projects.forEach((project) => {
    const option = document.createElement("option");
    option.value = project.id;
    option.textContent = project.name;
    if (project.id === currentProjectId) option.selected = true;
    projectSelect.appendChild(option);
  });
}

function renderBoard() {
  const project = getCurrentProject();
  board.innerHTML = "";

  if (!project) return;

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h3");
    title.textContent = column.title;
    columnEl.appendChild(title);

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drop-target");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-target");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskList.dataset.columnId;
      const sourceColumn = project.columns.find(c => c.id === draggedFromColumnId);
      const destinationColumn = project.columns.find(c => c.id === destinationColumnId);

      const sourceIndex = sourceColumn.taskIds.indexOf(draggedTaskId);
      const destinationIndex = destinationColumn.taskIds.length;

      socket.emit("task:move", {
        projectId: currentProjectId,
        sourceColumnId: draggedFromColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex,
        taskId: draggedTaskId
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      const title = document.createElement("div");
      title.className = "task-title";
      title.textContent = task.title;

      const desc = document.createElement("div");
      desc.className = "task-meta";
      desc.textContent = task.description || "";

      const meta = document.createElement("div");
      meta.className = "task-meta";
      meta.textContent = `Assignee: ${task.assignee || "Unassigned"} • Priority: ${task.priority}`;

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditTask(task, column.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.style.background = "#dc2626";
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", {
          projectId: currentProjectId,
          taskId: task.id
        });
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      card.appendChild(title);
      card.appendChild(desc);
      card.appendChild(meta);
      card.appendChild(actions);

      taskList.appendChild(card);
    });

    columnEl.appendChild(taskList);
    board.appendChild(columnEl);
  });
}

function openEditTask(task, columnId) {
  document.getElementById("taskId").value = task.id;
  document.getElementById("title").value = task.title;
  document.getElementById("description").value = task.description || "";
  document.getElementById("assignee").value = task.assignee || "";
  document.getElementById("priority").value = task.priority || "Medium";
  document.getElementById("columnId").value = columnId;
  taskDialog.showModal();
}

function openNewTaskDialog() {
  taskForm.reset();
  document.getElementById("taskId").value = "";
  document.getElementById("columnId").value = "todo";
  taskDialog.showModal();
}

newTaskBtn.addEventListener("click", openNewTaskDialog);
newProjectBtn.addEventListener("click", () => projectDialog.showModal());

cancelTaskBtn.addEventListener("click", () => taskDialog.close());
cancelProjectBtn.addEventListener("click", () => projectDialog.close());

projectSelect.addEventListener("change", () => {
  currentProjectId = projectSelect.value;
  socket.emit("join:project", currentProjectId);
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const taskId = document.getElementById("taskId").value;
  const title = document.getElementById("title").value.trim();
  const description = document.getElementById("description").value.trim();
  const assignee = document.getElementById("assignee").value.trim();
  const priority = document.getElementById("priority").value;
  const columnId = document.getElementById("columnId").value;

  if (!title) return;

  if (taskId) {
    socket.emit("task:update", {
      projectId: currentProjectId,
      taskId,
      updates: { title, description, assignee, priority }
    });
  } else {
    socket.emit("task:create", {
      projectId: currentProjectId,
      task: { title, description, assignee, priority, columnId }
    });
  }

  taskDialog.close();
});

projectForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  const name = document.getElementById("projectName").value.trim();
  if (!name) return;

  const res = await fetch(`${API_URL}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  currentProjectId = project.id;
  await fetchProjects();
  socket.emit("join:project", currentProjectId);
  projectDialog.close();
  projectForm.reset();
});

socket.on("projects:init", (serverProjects) => {
  projects = serverProjects;
  if (!currentProjectId && projects.length) {
    currentProjectId = projects[0].id;
    socket.emit("join:project", currentProjectId);
  }
  renderProjectOptions();
  renderBoard();
});

socket.on("projects:update", (serverProjects) => {
  projects = serverProjects;
  renderProjectOptions();
  renderBoard();
});

socket.on("project:update", (updatedProject) => {
  const index = projects.findIndex((p) => p.id === updatedProject.id);
  if (index >= 0) {
    projects[index] = updatedProject;
  } else {
    projects.push(updatedProject);
  }
  renderProjectOptions();
  renderBoard();
});

fetchProjects();
```

