# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const state = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Set up project repo", description: "Initialize GitHub repository" },
        { id: "task-2", title: "Design homepage", description: "Create wireframe for dashboard" }
      ]
    },
    {
      id: "inprogress",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build drag-and-drop", description: "Implement task movement across columns" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Create project plan", description: "Define MVP scope" }
      ]
    }
  ]
};

function findColumn(columnId) {
  return state.columns.find(col => col.id === columnId);
}

function removeTask(taskId) {
  for (const column of state.columns) {
    const index = column.tasks.findIndex(task => task.id === taskId);
    if (index !== -1) {
      return column.tasks.splice(index, 1)[0];
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", state);

  socket.on("task:create", ({ columnId, task }) => {
    const column = findColumn(columnId);
    if (!column) return;

    column.tasks.push(task);
    io.emit("board:update", state);
  });

  socket.on("task:update", ({ taskId, title, description }) => {
    for (const column of state.columns) {
      const task = column.tasks.find(t => t.id === taskId);
      if (task) {
        task.title = title;
        task.description = description;
        io.emit("board:update", state);
        return;
      }
    }
  });

  socket.on("task:delete", ({ taskId }) => {
    const removed = removeTask(taskId);
    if (removed) {
      io.emit("board:update", state);
    }
  });

  socket.on("task:move", ({ taskId, targetColumnId, targetIndex }) => {
    const task = removeTask(taskId);
    const targetColumn = findColumn(targetColumnId);

    if (!task || !targetColumn) return;

    const safeIndex = Math.max(0, Math.min(targetIndex, targetColumn.tasks.length));
    targetColumn.tasks.splice(safeIndex, 0, task);

    io.emit("board:update", state);
  });

  socket.on("column:create", ({ title }) => {
    const id = `column-${Date.now()}`;
    state.columns.push({
      id,
      title,
      tasks: []
    });
    io.emit("board:update", state);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

