```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory datastore for demo purposes
let board = {
  id: "board-1",
  name: "Team Project Board",
  columns: [
    {
      id: "col-1",
      title: "Backlog",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "col-2",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "col-3",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Design landing page",
      description: "Create wireframes and mockups",
      assignee: "Alice"
    },
    "task-2": {
      id: "task-2",
      title: "Set up database",
      description: "Initialize PostgreSQL schema",
      assignee: "Bob"
    },
    "task-3": {
      id: "task-3",
      title: "Build auth flow",
      description: "Login, signup, password reset",
      assignee: "Charlie"
    }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, title, description, assignee } = req.body;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const id = uuidv4();
  board.tasks[id] = {
    id,
    title,
    description: description || "",
    assignee: assignee || ""
  };
  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(board.tasks[id]);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const task = board.tasks[taskId];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, assignee } = req.body;
  task.title = title ?? task.title;
  task.description = description ?? task.description;
  task.assignee = assignee ?? task.assignee;

  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];
  board.columns.forEach((col) => {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  });

  io.emit("board:update", board);
  res.json({ success: true });
});

app.put("/api/board/reorder", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ success: true, board });
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);
  socket.emit("board:update", board);

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

