## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function App() {
  const [board, setBoard] = useState(null);
  const [newTask, setNewTask] = useState({
    columnId: "col-1",
    title: "",
    description: "",
    assignee: ""
  });

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const taskLocation = useMemo(() => {
    if (!board) return {};
    const map = {};
    board.columns.forEach((col) => {
      col.taskIds.forEach((taskId, index) => {
        map[taskId] = { columnId: col.id, index };
      });
    });
    return map;
  }, [board]);

  const findColumnByTaskId = (taskId) => {
    return board.columns.find((col) => col.taskIds.includes(taskId));
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over || !board) return;

    const activeTaskId = active.id;
    const overId = over.id;

    const sourceInfo = taskLocation[activeTaskId];
    if (!sourceInfo) return;

    let destinationColumnId;
    let destinationIndex;

    const overTaskLocation = taskLocation[overId];
    if (overTaskLocation) {
      destinationColumnId = overTaskLocation.columnId;
      destinationIndex = overTaskLocation.index;
    } else {
      const overColumn = board.columns.find((col) => col.id === overId);
      if (!overColumn) return;
      destinationColumnId = overColumn.id;
      destinationIndex = overColumn.taskIds.length;
    }

    if (
      sourceInfo.columnId === destinationColumnId &&
      sourceInfo.index === destinationIndex
    ) {
      return;
    }

    await fetch(`${API_URL}/api/board/reorder`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sourceColumnId: sourceInfo.columnId,
        destinationColumnId,
        sourceIndex: sourceInfo.index,
        destinationIndex,
        taskId: activeTaskId
      })
    });
  };

  const addTask = async (e) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newTask)
    });

    setNewTask({
      columnId: board.columns[0]?.id || "",
      title: "",
      description: "",
      assignee: ""
    });
  };

  const updateTask = async (taskId, updates) => {
    await fetch(`${API_URL}/api/tasks/${taskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updates)
    });
  };

  const deleteTask = async (taskId) => {
    await fetch(`${API_URL}/api/tasks/${taskId}`, {
      method: "DELETE"
    });
  };

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>{board.name}</h1>
        <p>Real-time collaborative task board</p>
      </header>

      <form className="task-form" onSubmit={addTask}>
        <select
          value={newTask.columnId}
          onChange={(e) => setNewTask({ ...newTask, columnId: e.target.value })}
        >
          {board.columns.map((col) => (
            <option key={col.id} value={col.id}>
              {col.title}
            </option>
          ))}
        </select>
        <input
          placeholder="Task title"
          value={newTask.title}
          onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
        />
        <input
          placeholder="Description"
          value={newTask.description}
          onChange={(e) =>
            setNewTask({ ...newTask, description: e.target.value })
          }
        />
        <input
          placeholder="Assignee"
          value={newTask.assignee}
          onChange={(e) => setNewTask({ ...newTask, assignee: e.target.value })}
        />
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {board.columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={column.taskIds.map((id) => board.tasks[id])}
              onUpdateTask={updateTask}
              onDeleteTask={deleteTask}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, onUpdateTask, onDeleteTask }) {
  return (
    <div className="column" id={column.id}>
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onUpdateTask={onUpdateTask}
              onDeleteTask={onDeleteTask}
            />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, onUpdateTask, onDeleteTask }) {
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState(task);

  useEffect(() => {
    setForm(task);
  }, [task]);

  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  const save = () => {
    onUpdateTask(task.id, form);
    setEditing(false);
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      {editing ? (
        <>
          <input
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
          />
          <textarea
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <input
            value={form.assignee}
            onChange={(e) => setForm({ ...form, assignee: e.target.value })}
          />
          <div className="task-actions">
            <button onClick={save}>Save</button>
            <button onClick={() => setEditing(false)}>Cancel</button>
          </div>
        </>
      ) : (
        <>
          <h3>{task.title}</h3>
          <p>{task.description}</p>
          <small>Assignee: {task.assignee || "Unassigned"}</small>
          <div className="task-actions">
            <button onClick={() => setEditing(true)}>Edit</button>
            <button onClick={() => onDeleteTask(task.id)}>Delete</button>
          </div>
        </>
      )}
    </div>
  );
}

export default App;
```

