# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

/**
 * In-memory project data
 * Replace with DB in production
 */
const board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

// Seed sample tasks
const t1 = uuidv4();
const t2 = uuidv4();
const t3 = uuidv4();

board.tasks[t1] = {
  id: t1,
  title: "Design landing page",
  description: "Create wireframes and final mockups",
  assignee: "Alex",
  updatedAt: Date.now()
};
board.tasks[t2] = {
  id: t2,
  title: "Set up API server",
  description: "Initialize Express and Socket.IO",
  assignee: "Sam",
  updatedAt: Date.now()
};
board.tasks[t3] = {
  id: t3,
  title: "Write documentation",
  description: "Prepare onboarding docs",
  assignee: "Taylor",
  updatedAt: Date.now()
};

board.columns[0].taskIds.push(t1, t3);
board.columns[1].taskIds.push(t2);

// REST API
app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "" } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const taskId = uuidv4();
  const newTask = {
    id: taskId,
    title: title.trim(),
    description,
    assignee,
    updatedAt: Date.now()
  };

  board.tasks[taskId] = newTask;
  board.columns[0].taskIds.push(taskId);

  io.emit("taskCreated", {
    task: newTask,
    columnId: "todo"
  });

  res.status(201).json(newTask);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const existing = board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updated = {
    ...existing,
    ...req.body,
    id,
    updatedAt: Date.now()
  };

  board.tasks[id] = updated;

  io.emit("taskUpdated", updated);

  res.json(updated);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];
  board.columns.forEach(col => {
    col.taskIds = col.taskIds.filter(taskId => taskId !== id);
  });

  io.emit("taskDeleted", { taskId: id });

  res.json({ success: true });
});

app.put("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceCol = board.columns.find(c => c.id === sourceColumnId);
  const destCol = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceCol || !destCol) {
    return res.status(400).json({ error: "Invalid column" });
  }

  const sourceIndex = sourceCol.taskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(400).json({ error: "Task not found in source column" });
  }

  sourceCol.taskIds.splice(sourceIndex, 1);
  destCol.taskIds.splice(destinationIndex, 0, taskId);

  const payload = {
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex
  };

  io.emit("taskMoved", payload);

  res.json({ success: true });
});

// Socket.IO events
io.on("connection", socket => {
  console.log(`Client connected: ${socket.id}`);

  socket.emit("boardState", board);

  socket.on("joinBoard", user => {
    socket.broadcast.emit("userJoined", {
      id: socket.id,
      name: user?.name || "Anonymous"
    });
  });

  socket.on("cursorMove", data => {
    socket.broadcast.emit("cursorMove", {
      socketId: socket.id,
      ...data
    });
  });

  socket.on("disconnect", () => {
    console.log(`Client disconnected: ${socket.id}`);
    socket.broadcast.emit("userLeft", { id: socket.id });
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```

