# 5) Frontend: `client/app.js`

```js
const API_BASE = "http://localhost:4000/api";
const socket = io("http://localhost:4000");

let boardState = {
  columns: [],
  tasks: {}
};

let currentUser = null;
let onlineUsers = {};

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("taskForm");
const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const taskAssigneeEl = document.getElementById("taskAssignee");
const joinBtn = document.getElementById("joinBtn");
const usernameInput = document.getElementById("usernameInput");
const presenceBar = document.getElementById("presenceBar");

async function fetchBoard() {
  const res = await fetch(`${API_BASE}/board`);
  boardState = await res.json();
  renderBoard();
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h3");
    title.textContent = `${column.title} (${column.taskIds.length})`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", e => {
      e.preventDefault();
      taskList.classList.add("drop-zone-active");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-zone-active");
    });

    taskList.addEventListener("drop", async e => {
      e.preventDefault();
      taskList.classList.remove("drop-zone-active");

      const taskId = e.dataTransfer.getData("text/plain");
      const sourceColumnId = e.dataTransfer.getData("sourceColumnId");
      const destinationColumnId = column.id;

      const destinationIndex = boardState.columns
        .find(c => c.id === destinationColumnId)
        .taskIds.length;

      if (!taskId || !sourceColumnId) return;
      if (sourceColumnId === destinationColumnId) return;

      await fetch(`${API_BASE}/board/move`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId,
          sourceColumnId,
          destinationColumnId,
          destinationIndex
        })
      });
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.columnId = column.id;

      card.addEventListener("dragstart", e => {
        card.classList.add("dragging");
        e.dataTransfer.setData("text/plain", task.id);
        e.dataTransfer.setData("sourceColumnId", column.id);
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      const titleEl = document.createElement("h4");
      titleEl.textContent = task.title;

      const descEl = document.createElement("p");
      descEl.textContent = task.description || "No description";

      const assigneeEl = document.createElement("p");
      assigneeEl.innerHTML = `<strong>Assignee:</strong> ${task.assignee || "Unassigned"}`;

      const metaEl = document.createElement("div");
      metaEl.className = "task-meta";
      metaEl.textContent = `Updated: ${new Date(task.updatedAt).toLocaleString()}`;

      const actionsEl = document.createElement("div");
      actionsEl.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => editTask(task.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => deleteTask(task.id));

      actionsEl.appendChild(editBtn);
      actionsEl.appendChild(deleteBtn);

      card.appendChild(titleEl);
      card.appendChild(descEl);
      card.appendChild(assigneeEl);
      card.appendChild(metaEl);
      card.appendChild(actionsEl);

      taskList.appendChild(card);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

async function createTask(e) {
  e.preventDefault();

  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const assignee = taskAssigneeEl.value.trim();

  if (!title) return;

  await fetch(`${API_BASE}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, assignee })
  });

  taskForm.reset();
}

async function editTask(taskId) {
  const task = boardState.tasks[taskId];
  if (!task) return;

  const title = prompt("Edit title:", task.title);
  if (title === null) return;

  const description = prompt("Edit description:", task.description || "");
  if (description === null) return;

  const assignee = prompt("Edit assignee:", task.assignee || "");
  if (assignee === null) return;

  await fetch(`${API_BASE}/tasks/${taskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title: title.trim(),
      description: description.trim(),
      assignee: assignee.trim()
    })
  });
}

async function deleteTask(taskId) {
  const confirmed = confirm("Delete this task?");
  if (!confirmed) return;

  await fetch(`${API_BASE}/tasks/${taskId}`, {
    method: "DELETE"
  });
}

function updatePresenceBar() {
  const names = Object.values(onlineUsers).map(u => u.name);
  presenceBar.textContent = names.length
    ? `Online: ${names.join(", ")}`
    : "No collaborators online";
}

joinBtn.addEventListener("click", () => {
  const name = usernameInput.value.trim() || "Anonymous";
  currentUser = { name };
  onlineUsers[socket.id] = currentUser;
  socket.emit("joinBoard", currentUser);
  updatePresenceBar();
});

taskForm.addEventListener("submit", createTask);

socket.on("boardState", state => {
  boardState = state;
  renderBoard();
});

socket.on("taskCreated", ({ task, columnId }) => {
  boardState.tasks[task.id] = task;
  const col = boardState.columns.find(c => c.id === columnId);
  if (col && !col.taskIds.includes(task.id)) {
    col.taskIds.push(task.id);
  }
  renderBoard();
});

socket.on("taskUpdated", task => {
  boardState.tasks[task.id] = task;
  renderBoard();
});

socket.on("taskDeleted", ({ taskId }) => {
  delete boardState.tasks[taskId];
  boardState.columns.forEach(col => {
    col.taskIds = col.taskIds.filter(id => id !== taskId);
  });
  renderBoard();
});

socket.on("taskMoved", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
  const sourceCol = boardState.columns.find(c => c.id === sourceColumnId);
  const destCol = boardState.columns.find(c => c.id === destinationColumnId);
  if (!sourceCol || !destCol) return;

  sourceCol.taskIds = sourceCol.taskIds.filter(id => id !== taskId);
  destCol.taskIds.splice(destinationIndex, 0, taskId);

  renderBoard();
});

socket.on("userJoined", user => {
  onlineUsers[user.id] = user;
  updatePresenceBar();
});

socket.on("userLeft", ({ id }) => {
  delete onlineUsers[id];
  updatePresenceBar();
});

// Optional: lightweight cursor sharing
document.addEventListener("mousemove", e => {
  if (!currentUser) return;
  socket.emit("cursorMove", {
    x: e.clientX,
    y: e.clientY,
    name: currentUser.name
  });
});

const remoteCursors = {};

socket.on("cursorMove", ({ socketId, x, y, name }) => {
  let cursor = remoteCursors[socketId];

  if (!cursor) {
    cursor = document.createElement("div");
    cursor.style.position = "fixed";
    cursor.style.pointerEvents = "none";
    cursor.style.background = "#2563eb";
    cursor.style.color = "white";
    cursor.style.padding = "2px 6px";
    cursor.style.borderRadius = "999px";
    cursor.style.fontSize = "12px";
    cursor.style.zIndex = "9999";
    document.body.appendChild(cursor);
    remoteCursors[socketId] = cursor;
  }

  cursor.textContent = name;
  cursor.style.left = `${x + 10}px`;
  cursor.style.top = `${y + 10}px`;
});
```

