# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory state
 * In production, replace with a database.
 */
let board = {
  id: "board-1",
  name: "Team Project Board",
  columns: [
    {
      id: "col-todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "col-inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "col-done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

// Seed data
const seedTasks = [
  {
    id: uuidv4(),
    title: "Set up project repo",
    description: "Initialize Git repository and README",
    assignee: "Alice",
    priority: "High"
  },
  {
    id: uuidv4(),
    title: "Design landing page",
    description: "Create wireframes for dashboard",
    assignee: "Bob",
    priority: "Medium"
  },
  {
    id: uuidv4(),
    title: "Implement API",
    description: "Build task endpoints and socket events",
    assignee: "Charlie",
    priority: "High"
  }
];

board.tasks[seedTasks[0].id] = seedTasks[0];
board.tasks[seedTasks[1].id] = seedTasks[1];
board.tasks[seedTasks[2].id] = seedTasks[2];
board.columns[0].taskIds.push(seedTasks[0].id, seedTasks[1].id);
board.columns[1].taskIds.push(seedTasks[2].id);

// REST API
app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "", priority = "Low", columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = board.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = {
    id: uuidv4(),
    title,
    description,
    assignee,
    priority
  };

  board.tasks[task.id] = task;
  column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const existing = board.tasks[taskId];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updated = {
    ...existing,
    ...req.body,
    id: taskId
  };

  board.tasks[taskId] = updated;
  io.emit("board:update", board);
  res.json(updated);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];
  board.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  });

  io.emit("board:update", board);
  res.json({ success: true });
});

app.post("/api/board/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!taskId || !sourceColumn || !destinationColumn || destinationIndex === undefined) {
    return res.status(400).json({ error: "Invalid move payload" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ success: true, board });
});

io.on("connection", socket => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:create", payload => {
    const { title, description = "", assignee = "", priority = "Low", columnId } = payload;
    const column = board.columns.find(c => c.id === columnId);
    if (!title || !column) return;

    const task = {
      id: uuidv4(),
      title,
      description,
      assignee,
      priority
    };

    board.tasks[task.id] = task;
    column.taskIds.push(task.id);

    io.emit("board:update", board);
  });

  socket.on("task:update", payload => {
    const { id } = payload;
    if (!id || !board.tasks[id]) return;

    board.tasks[id] = {
      ...board.tasks[id],
      ...payload,
      id
    };

    io.emit("board:update", board);
  });

  socket.on("task:delete", taskId => {
    if (!board.tasks[taskId]) return;

    delete board.tasks[taskId];
    board.columns.forEach(column => {
      column.taskIds = column.taskIds.filter(id => id !== taskId);
    });

    io.emit("board:update", board);
  });

  socket.on("task:move", payload => {
    const {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    } = payload;

    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!taskId || !sourceColumn || !destinationColumn || destinationIndex === undefined) {
      return;
    }

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

    const alreadyExists = destinationColumn.taskIds.includes(taskId);
    if (alreadyExists) {
      destinationColumn.taskIds = destinationColumn.taskIds.filter(id => id !== taskId);
    }

    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

