# 5) Frontend: `client/app.js`

```js
const socket = io("http://localhost:4000");

const boardEl = document.getElementById("board");
const taskModal = document.getElementById("taskModal");
const openTaskModalBtn = document.getElementById("openTaskModalBtn");
const closeTaskModalBtn = document.getElementById("closeTaskModalBtn");
const taskForm = document.getElementById("taskForm");

const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const assigneeInput = document.getElementById("assignee");
const priorityInput = document.getElementById("priority");
const columnIdInput = document.getElementById("columnId");
const modalTitle = document.getElementById("modalTitle");

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

function openModal() {
  taskModal.classList.remove("hidden");
}

function closeModal() {
  taskModal.classList.add("hidden");
  taskForm.reset();
  taskIdInput.value = "";
  modalTitle.textContent = "Add Task";
}

openTaskModalBtn.addEventListener("click", () => {
  taskForm.reset();
  taskIdInput.value = "";
  modalTitle.textContent = "Add Task";
  columnIdInput.value = "col-todo";
  openModal();
});

closeTaskModalBtn.addEventListener("click", closeModal);

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const payload = {
    title: titleInput.value.trim(),
    description: descriptionInput.value.trim(),
    assignee: assigneeInput.value.trim(),
    priority: priorityInput.value,
    columnId: columnIdInput.value
  };

  const existingTaskId = taskIdInput.value;

  if (existingTaskId) {
    socket.emit("task:update", {
      id: existingTaskId,
      title: payload.title,
      description: payload.description,
      assignee: payload.assignee,
      priority: payload.priority
    });
  } else {
    socket.emit("task:create", payload);
  }

  closeModal();
});

function renderBoard(board) {
  boardState = board;
  boardEl.innerHTML = "";

  board.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const destinationIndex = getDropIndex(taskListEl, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        destinationColumnId,
        destinationIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = board.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="meta">
          <div><strong>Assignee:</strong> ${escapeHtml(task.assignee || "Unassigned")}</div>
          <div><strong>Priority:</strong> ${escapeHtml(task.priority || "Low")}</div>
        </div>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".edit-btn").addEventListener("click", () => {
        taskIdInput.value = task.id;
        titleInput.value = task.title || "";
        descriptionInput.value = task.description || "";
        assigneeInput.value = task.assignee || "";
        priorityInput.value = task.priority || "Low";
        columnIdInput.value = column.id;
        modalTitle.textContent = "Edit Task";
        openModal();
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", task.id);
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(container, mouseY) {
  const draggableElements = [
    ...container.querySelectorAll(".task:not(.dragging)")
  ];

  let closest = {
    offset: Number.NEGATIVE_INFINITY,
    index: draggableElements.length
  };

  draggableElements.forEach((child, index) => {
    const box = child.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

socket.on("board:init", (board) => {
  renderBoard(board);
});

socket.on("board:update", (board) => {
  renderBoard(board);
});
```

