const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory data store
 * Replace with a real database in production
 */
let state = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        {
          id: "todo",
          title: "To Do",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "inprogress",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "done",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes",
          assignee: "Alice"
        },
        "task-2": {
          id: "task-2",
          title: "Define color palette",
          description: "Choose brand colors for the redesign",
          assignee: "Bob"
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page",
          description: "Implement responsive landing page",
          assignee: "Charlie"
        }
      }
    }
  ]
};

function findProject(projectId) {
  return state.projects.find((p) => p.id === projectId);
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const newProject = {
    id: `project-${Date.now()}`,
    name,
    columns: [
      { id: "todo", title: "To Do", taskIds: [] },
      { id: "inprogress", title: "In Progress", taskIds: [] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {}
  };
  state.projects.push(newProject);
  io.emit("projectCreated", newProject);
  res.status(201).json(newProject);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const { projectId } = req.params;
  const { title, description, assignee, columnId } = req.body;

  const project = findProject(projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const taskId = `task-${Date.now()}`;
  const task = {
    id: taskId,
    title,
    description,
    assignee
  };

  project.tasks[taskId] = task;
  const column = project.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Column not found" });
  }

  column.taskIds.push(taskId);

  io.emit("taskCreated", { projectId, task, columnId });
  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const updates = req.body;

  const project = findProject(projectId);
  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  project.tasks[taskId] = {
    ...project.tasks[taskId],
    ...updates
  };

  io.emit("taskUpdated", { projectId, task: project.tasks[taskId] });
  res.json(project.tasks[taskId]);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;

  const project = findProject(projectId);
  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  io.emit("taskDeleted", { projectId, taskId });
  res.json({ success: true });
});

app.put("/api/projects/:projectId/reorder", (req, res) => {
  const { projectId } = req.params;
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const project = findProject(projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("taskMoved", {
    projectId,
    sourceColumnId,
    destinationColumnId,
    sourceIndex,
    destinationIndex,
    taskId
  });

  res.json({ success: true, project });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state", state);

  socket.on("joinProject", (projectId) => {
    socket.join(projectId);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
