# 5. Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let projects = [];
let selectedProjectId = null;
let draggedTaskId = null;
let draggedFromColumnId = null;
let draggedFromIndex = null;

const projectListEl = document.getElementById("project-list");
const projectTitleEl = document.getElementById("project-title");
const boardEl = document.getElementById("board");

const projectForm = document.getElementById("project-form");
const projectNameInput = document.getElementById("project-name");

const taskForm = document.getElementById("task-form");
const taskTitleInput = document.getElementById("task-title");
const taskAssigneeInput = document.getElementById("task-assignee");
const taskDescriptionInput = document.getElementById("task-description");
const taskColumnInput = document.getElementById("task-column");

async function fetchProjects() {
  const res = await fetch(`${API_URL}/projects`);
  projects = await res.json();

  if (!selectedProjectId && projects.length > 0) {
    selectedProjectId = projects[0].id;
  }

  renderProjects();
  renderBoard();
}

function getSelectedProject() {
  return projects.find((p) => p.id === selectedProjectId);
}

function renderProjects() {
  projectListEl.innerHTML = "";

  projects.forEach((project) => {
    const div = document.createElement("div");
    div.className = `project-item ${project.id === selectedProjectId ? "active" : ""}`;
    div.textContent = project.name;
    div.onclick = () => {
      selectedProjectId = project.id;
      renderProjects();
      renderBoard();
      socket.emit("joinProject", project.id);
    };
    projectListEl.appendChild(div);
  });
}

function renderBoard() {
  const project = getSelectedProject();

  if (!project) {
    projectTitleEl.textContent = "Select a Project";
    boardEl.innerHTML = "";
    return;
  }

  projectTitleEl.textContent = project.name;
  boardEl.innerHTML = "";

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h3");
    titleEl.textContent = column.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();

      if (!draggedTaskId) return;

      const destinationColumnId = column.id;
      const destinationIndex = getDropIndex(taskListEl, e.clientY);

      await fetch(`${API_URL}/projects/${project.id}/reorder`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          sourceIndex: draggedFromIndex,
          destinationIndex,
          taskId: draggedTaskId
        })
      });
    });

    column.taskIds.forEach((taskId, index) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        draggedFromIndex = index;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.querySelector(".edit-btn").addEventListener("click", async () => {
        const newTitle = prompt("Edit title", task.title);
        if (newTitle === null) return;

        const newDescription = prompt("Edit description", task.description || "");
        if (newDescription === null) return;

        const newAssignee = prompt("Edit assignee", task.assignee || "");
        if (newAssignee === null) return;

        await fetch(`${API_URL}/projects/${project.id}/tasks/${task.id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            title: newTitle,
            description: newDescription,
            assignee: newAssignee
          })
        });
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", async () => {
        const confirmed = confirm(`Delete "${task.title}"?`);
        if (!confirmed) return;

        await fetch(`${API_URL}/projects/${project.id}/tasks/${task.id}`, {
          method: "DELETE"
        });
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(container, mouseY) {
  const cards = [...container.querySelectorAll(".task-card:not(.dragging)")];

  let closest = { offset: Number.NEGATIVE_INFINITY, index: cards.length };

  cards.forEach((card, index) => {
    const box = card.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

projectForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const name = projectNameInput.value.trim();
  if (!name) return;

  await fetch(`${API_URL}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  projectNameInput.value = "";
});

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const project = getSelectedProject();
  if (!project) {
    alert("Please select a project first.");
    return;
  }

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();
  const columnId = taskColumnInput.value;

  if (!title) return;

  await fetch(`${API_URL}/projects/${project.id}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title,
      description,
      assignee,
      columnId
    })
  });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskAssigneeInput.value = "";
  taskColumnInput.value = "todo";
});

socket.on("state", (serverState) => {
  projects = serverState.projects;
  if (!selectedProjectId && projects.length > 0) {
    selectedProjectId = projects[0].id;
  }
  renderProjects();
  renderBoard();
});

socket.on("projectCreated", (project) => {
  projects.push(project);
  if (!selectedProjectId) selectedProjectId = project.id;
  renderProjects();
  renderBoard();
});

socket.on("taskCreated", ({ projectId, task, columnId }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  project.tasks[task.id] = task;
  const column = project.columns.find((c) => c.id === columnId);
  if (column) {
    column.taskIds.push(task.id);
  }

  renderBoard();
});

socket.on("taskUpdated", ({ projectId, task }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  project.tasks[task.id] = task;
  renderBoard();
});

socket.on("taskDeleted", ({ projectId, taskId }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  delete project.tasks[taskId];
  project.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  renderBoard();
});

socket.on("taskMoved", ({ projectId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId }) => {
  const project = projects.find((p) => p.id === projectId);
  if (!project) return;

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);
  if (!sourceColumn || !destinationColumn) return;

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  renderBoard();
});

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

fetchProjects();
```

