# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = 4000;

/**
 * In-memory data store
 * Replace with a database in production.
 */
const store = {
  board: {
    id: "board-1",
    name: "Team Project Board",
    columns: [
      {
        id: "col-todo",
        title: "To Do",
        taskIds: []
      },
      {
        id: "col-inprogress",
        title: "In Progress",
        taskIds: []
      },
      {
        id: "col-done",
        title: "Done",
        taskIds: []
      }
    ],
    tasks: {}
  }
};

// Seed demo tasks
(function seed() {
  const task1 = {
    id: uuidv4(),
    title: "Define project scope",
    description: "Clarify deliverables and stakeholders",
    assignee: "Alice",
    createdAt: Date.now()
  };
  const task2 = {
    id: uuidv4(),
    title: "Design homepage wireframe",
    description: "Create initial mockup for homepage",
    assignee: "Bob",
    createdAt: Date.now()
  };
  const task3 = {
    id: uuidv4(),
    title: "Set up backend API",
    description: "Initialize Express server and routes",
    assignee: "Charlie",
    createdAt: Date.now()
  };

  store.board.tasks[task1.id] = task1;
  store.board.tasks[task2.id] = task2;
  store.board.tasks[task3.id] = task3;

  store.board.columns[0].taskIds.push(task1.id, task2.id);
  store.board.columns[1].taskIds.push(task3.id);
})();

/**
 * Helpers
 */
function getBoard() {
  return store.board;
}

function findColumnById(columnId) {
  return store.board.columns.find((c) => c.id === columnId);
}

function removeTaskFromAllColumns(taskId) {
  for (const col of store.board.columns) {
    col.taskIds = col.taskIds.filter((id) => id !== taskId);
  }
}

/**
 * REST API
 */
app.get("/api/board", (req, res) => {
  res.json(getBoard());
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "", columnId = "col-todo" } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const column = findColumnById(columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = {
    id: uuidv4(),
    title: title.trim(),
    description: description.trim(),
    assignee: assignee.trim(),
    createdAt: Date.now()
  };

  store.board.tasks[task.id] = task;
  column.taskIds.push(task.id);

  io.emit("board:update", getBoard());

  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const existing = store.board.tasks[taskId];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, assignee } = req.body;

  if (typeof title === "string") existing.title = title.trim();
  if (typeof description === "string") existing.description = description.trim();
  if (typeof assignee === "string") existing.assignee = assignee.trim();

  io.emit("board:update", getBoard());

  res.json(existing);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const existing = store.board.tasks[taskId];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete store.board.tasks[taskId];
  removeTaskFromAllColumns(taskId);

  io.emit("board:update", getBoard());

  res.json({ success: true });
});

app.put("/api/tasks/:taskId/move", (req, res) => {
  const { taskId } = req.params;
  const { sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const task = store.board.tasks[taskId];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const sourceColumn = findColumnById(sourceColumnId);
  const destinationColumn = findColumnById(destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Source or destination column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const safeIndex =
    typeof destinationIndex === "number" && destinationIndex >= 0
      ? Math.min(destinationIndex, destinationColumn.taskIds.length)
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(safeIndex, 0, taskId);

  io.emit("board:update", getBoard());

  res.json(getBoard());
});

app.put("/api/columns/reorder", (req, res) => {
  const { sourceColumnId, destinationColumnId, taskId, destinationIndex } = req.body;

  const sourceColumn = findColumnById(sourceColumnId);
  const destinationColumn = findColumnById(destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const safeIndex =
    typeof destinationIndex === "number" && destinationIndex >= 0
      ? Math.min(destinationIndex, destinationColumn.taskIds.length)
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(safeIndex, 0, taskId);

  io.emit("board:update", getBoard());

  res.json(getBoard());
});

/**
 * Socket.IO
 */
io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", getBoard());

  socket.on("task:create", (payload) => {
    const { title, description = "", assignee = "", columnId = "col-todo" } = payload || {};
    if (!title || !title.trim()) return;

    const column = findColumnById(columnId);
    if (!column) return;

    const task = {
      id: uuidv4(),
      title: title.trim(),
      description: description.trim(),
      assignee: assignee.trim(),
      createdAt: Date.now()
    };

    store.board.tasks[task.id] = task;
    column.taskIds.push(task.id);

    io.emit("board:update", getBoard());
  });

  socket.on("task:update", ({ taskId, updates }) => {
    const task = store.board.tasks[taskId];
    if (!task) return;

    if (typeof updates.title === "string") task.title = updates.title.trim();
    if (typeof updates.description === "string") task.description = updates.description.trim();
    if (typeof updates.assignee === "string") task.assignee = updates.assignee.trim();

    io.emit("board:update", getBoard());
  });

  socket.on("task:delete", ({ taskId }) => {
    if (!store.board.tasks[taskId]) return;

    delete store.board.tasks[taskId];
    removeTaskFromAllColumns(taskId);

    io.emit("board:update", getBoard());
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const task = store.board.tasks[taskId];
    const sourceColumn = findColumnById(sourceColumnId);
    const destinationColumn = findColumnById(destinationColumnId);

    if (!task || !sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex =
      typeof destinationIndex === "number" && destinationIndex >= 0
        ? Math.min(destinationIndex, destinationColumn.taskIds.length)
        : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(safeIndex, 0, taskId);

    io.emit("board:update", getBoard());
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
