# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const taskModal = document.getElementById("taskModal");
const openTaskModalBtn = document.getElementById("openTaskModalBtn");
const closeTaskModalBtn = document.getElementById("closeTaskModalBtn");
const taskForm = document.getElementById("taskForm");
const modalTitle = document.getElementById("modalTitle");
const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskAssigneeInput = document.getElementById("taskAssignee");
const taskColumnInput = document.getElementById("taskColumn");
const connectionStatus = document.getElementById("connectionStatus");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

function openModal(task = null, columnId = "col-todo") {
  taskModal.classList.remove("hidden");

  if (task) {
    modalTitle.textContent = "Edit Task";
    taskIdInput.value = task.id;
    taskTitleInput.value = task.title || "";
    taskDescriptionInput.value = task.description || "";
    taskAssigneeInput.value = task.assignee || "";
    taskColumnInput.value = findTaskColumnId(task.id) || "col-todo";
  } else {
    modalTitle.textContent = "Create Task";
    taskForm.reset();
    taskIdInput.value = "";
    taskColumnInput.value = columnId;
  }
}

function closeModal() {
  taskModal.classList.add("hidden");
}

function findTaskColumnId(taskId) {
  for (const col of boardState.columns) {
    if (col.taskIds.includes(taskId)) return col.id;
  }
  return null;
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const header = document.createElement("div");
    header.className = "column-header";
    header.textContent = `${column.title} (${column.taskIds.length})`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskList.dataset.columnId;
      const destinationIndex = getDropIndex(taskList, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        destinationColumnId,
        destinationIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      const title = document.createElement("h3");
      title.textContent = task.title;

      const desc = document.createElement("p");
      desc.textContent = task.description || "No description";

      const meta = document.createElement("div");
      meta.className = "task-meta";
      meta.textContent = `Assignee: ${task.assignee || "Unassigned"}`;

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.className = "edit-btn";
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openModal(task));

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => {
        if (confirm(`Delete task "${task.title}"?`)) {
          socket.emit("task:delete", { taskId: task.id });
        }
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      card.appendChild(title);
      card.appendChild(desc);
      card.appendChild(meta);
      card.appendChild(actions);

      taskList.appendChild(card);
    });

    columnEl.appendChild(header);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

function getDropIndex(taskList, mouseY) {
  const cards = [...taskList.querySelectorAll(".task-card:not(.dragging)")];

  for (let i = 0; i < cards.length; i++) {
    const rect = cards[i].getBoundingClientRect();
    const midpoint = rect.top + rect.height / 2;
    if (mouseY < midpoint) {
      return i;
    }
  }

  return cards.length;
}

openTaskModalBtn.addEventListener("click", () => openModal());
closeTaskModalBtn.addEventListener("click", closeModal);

taskModal.addEventListener("click", (e) => {
  if (e.target === taskModal) closeModal();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const id = taskIdInput.value.trim();
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();
  const selectedColumnId = taskColumnInput.value;

  if (!title) {
    alert("Title is required");
    return;
  }

  if (id) {
    const oldColumnId = findTaskColumnId(id);

    socket.emit("task:update", {
      taskId: id,
      updates: { title, description, assignee }
    });

    if (oldColumnId && oldColumnId !== selectedColumnId) {
      socket.emit("task:move", {
        taskId: id,
        sourceColumnId: oldColumnId,
        destinationColumnId: selectedColumnId,
        destinationIndex: boardState.columns.find(c => c.id === selectedColumnId)?.taskIds.length || 0
      });
    }
  } else {
    socket.emit("task:create", {
      title,
      description,
      assignee,
      columnId: selectedColumnId
    });
  }

  closeModal();
});

socket.on("connect", () => {
  connectionStatus.textContent = "Connected";
  connectionStatus.style.color = "#86efac";
});

socket.on("disconnect", () => {
  connectionStatus.textContent = "Disconnected";
  connectionStatus.style.color = "#fca5a5";
});

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

fetchBoard();
```

