# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let boardState = null;
let socket = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const dialogTitle = document.getElementById("dialogTitle");
const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const assigneeInput = document.getElementById("assignee");
const columnIdInput = document.getElementById("columnId");
const cancelBtn = document.getElementById("cancelBtn");
const statusEl = document.getElementById("status");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

function connectWebSocket() {
  socket = new WebSocket(WS_URL);

  socket.addEventListener("open", () => {
    statusEl.textContent = "Connected";
  });

  socket.addEventListener("close", () => {
    statusEl.textContent = "Disconnected - retrying...";
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener("message", (event) => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATED") {
      boardState = data.payload;
      renderBoard();
    }
  });
}

function populateColumnOptions() {
  columnIdInput.innerHTML = "";
  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    columnIdInput.appendChild(option);
  });
}

function openAddTaskDialog(defaultColumnId = "todo") {
  dialogTitle.textContent = "Add Task";
  taskIdInput.value = "";
  titleInput.value = "";
  descriptionInput.value = "";
  assigneeInput.value = "";
  populateColumnOptions();
  columnIdInput.value = defaultColumnId;
  taskDialog.showModal();
}

function openEditTaskDialog(task, columnId) {
  dialogTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  titleInput.value = task.title;
  descriptionInput.value = task.description;
  assigneeInput.value = task.assignee;
  populateColumnOptions();
  columnIdInput.value = columnId;
  taskDialog.showModal();
}

async function createTask(taskData) {
  await fetch(`${API_URL}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(taskData)
  });
}

async function updateTask(id, taskData) {
  await fetch(`${API_URL}/tasks/${id}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(taskData)
  });
}

async function deleteTask(id) {
  await fetch(`${API_URL}/tasks/${id}`, {
    method: "DELETE"
  });
}

async function moveTask(taskId, sourceColumnId, destinationColumnId, destinationIndex) {
  await fetch(`${API_URL}/move-task`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    })
  });
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const addBtn = document.createElement("button");
    addBtn.textContent = "+";
    addBtn.addEventListener("click", () => openAddTaskDialog(column.id));

    headerEl.appendChild(titleEl);
    headerEl.appendChild(addBtn);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drop-target");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drop-target");
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = column.id;
      const destinationIndex = column.taskIds.length;

      await moveTask(
        draggedTaskId,
        draggedFromColumnId,
        destinationColumnId,
        destinationIndex
      );

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const cardEl = document.createElement("div");
      cardEl.className = "task-card";
      cardEl.draggable = true;
      cardEl.dataset.taskId = task.id;

      cardEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        cardEl.classList.add("dragging");
      });

      cardEl.addEventListener("dragend", () => {
        cardEl.classList.remove("dragging");
      });

      const titleNode = document.createElement("div");
      titleNode.className = "task-title";
      titleNode.textContent = task.title;

      const descNode = document.createElement("div");
      descNode.className = "task-desc";
      descNode.textContent = task.description || "No description";

      const metaNode = document.createElement("div");
      metaNode.className = "task-meta";
      metaNode.textContent = `Assignee: ${task.assignee || "Unassigned"}`;

      const actionsNode = document.createElement("div");
      actionsNode.className = "task-actions";

      const editBtn = document.createElement("button");
      editBtn.textContent = "Edit";
      editBtn.addEventListener("click", () => openEditTaskDialog(task, column.id));

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.className = "delete";
      deleteBtn.addEventListener("click", () => deleteTask(task.id));

      actionsNode.appendChild(editBtn);
      actionsNode.appendChild(deleteBtn);

      cardEl.appendChild(titleNode);
      cardEl.appendChild(descNode);
      cardEl.appendChild(metaNode);
      cardEl.appendChild(actionsNode);

      taskListEl.appendChild(cardEl);
    });

    columnEl.appendChild(headerEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

addTaskBtn.addEventListener("click", () => openAddTaskDialog());

cancelBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const id = taskIdInput.value.trim();
  const title = titleInput.value.trim();
  const description = descriptionInput.value.trim();
  const assignee = assigneeInput.value.trim();
  const columnId = columnIdInput.value;

  if (!title) return;

  if (id) {
    await updateTask(id, { title, description, assignee });
  } else {
    await createTask({ title, description, assignee, columnId });
  }

  taskDialog.close();
});

fetchBoard();
connectWebSocket();
```

