# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const boardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["1", "2"] },
    { id: "inprogress", title: "In Progress", taskIds: ["3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "1": {
      id: "1",
      title: "Set up project repository",
      description: "Initialize GitHub repo and README"
    },
    "2": {
      id: "2",
      title: "Design homepage",
      description: "Create wireframe for landing page"
    },
    "3": {
      id: "3",
      title: "Build auth flow",
      description: "Implement login and registration UI"
    }
  }
};

function broadcastBoard() {
  io.emit("board:update", boardState);
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", boardState);

  socket.on("task:create", ({ columnId, title, description }) => {
    const id = Date.now().toString();
    boardState.tasks[id] = {
      id,
      title: title?.trim() || "Untitled Task",
      description: description?.trim() || ""
    };

    const column = boardState.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(id);
      broadcastBoard();
    }
  });

  socket.on("task:update", ({ taskId, title, description }) => {
    if (!boardState.tasks[taskId]) return;
    boardState.tasks[taskId].title = title?.trim() || boardState.tasks[taskId].title;
    boardState.tasks[taskId].description = description?.trim() || "";
    broadcastBoard();
  });

  socket.on("task:delete", ({ taskId }) => {
    delete boardState.tasks[taskId];
    boardState.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });
    broadcastBoard();
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = boardState.columns.find((c) => c.id === fromColumnId);
    const toColumn = boardState.columns.find((c) => c.id === toColumnId);

    if (!fromColumn || !toColumn) return;

    fromColumn.taskIds = fromColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex = Math.max(0, Math.min(toIndex, toColumn.taskIds.length));
    toColumn.taskIds.splice(safeIndex, 0, taskId);

    broadcastBoard();
  });

  socket.on("column:create", ({ title }) => {
    const id = `col_${Date.now()}`;
    boardState.columns.push({
      id,
      title: title?.trim() || "New Column",
      taskIds: []
    });
    broadcastBoard();
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

