# 5. `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const modalEl = document.getElementById("task-modal");
const modalTaskIdEl = document.getElementById("modal-task-id");
const modalTitleEl = document.getElementById("modal-title");
const modalDescriptionEl = document.getElementById("modal-description");
const saveTaskBtn = document.getElementById("save-task-btn");
const deleteTaskBtn = document.getElementById("delete-task-btn");
const closeModalBtn = document.getElementById("close-modal-btn");
const addColumnBtn = document.getElementById("add-column-btn");

socket.on("board:init", (state) => {
  boardState = state;
  renderBoard();
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = column.title;

    headerEl.appendChild(titleEl);
    columnEl.appendChild(headerEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      let toIndex = column.taskIds.length;

      if (afterElement) {
        toIndex = [...taskListEl.children].indexOf(afterElement);
      }

      socket.emit("task:move", {
        taskId: draggedTaskId,
        fromColumnId: draggedFromColumnId,
        toColumnId: column.id,
        toIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description)}</p>
      `;

      taskEl.addEventListener("click", () => openTaskModal(task));

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);

    const addTaskBtn = document.createElement("button");
    addTaskBtn.className = "add-task-btn";
    addTaskBtn.textContent = "+ Add Task";
    addTaskBtn.addEventListener("click", () => {
      const title = prompt("Task title:");
      if (!title) return;
      const description = prompt("Task description:") || "";
      socket.emit("task:create", {
        columnId: column.id,
        title,
        description
      });
    });

    columnEl.appendChild(addTaskBtn);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [
    ...container.querySelectorAll(".task:not(.dragging)")
  ];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}

function openTaskModal(task) {
  modalTaskIdEl.value = task.id;
  modalTitleEl.value = task.title;
  modalDescriptionEl.value = task.description;
  modalEl.classList.remove("hidden");
}

function closeTaskModal() {
  modalEl.classList.add("hidden");
  modalTaskIdEl.value = "";
  modalTitleEl.value = "";
  modalDescriptionEl.value = "";
}

saveTaskBtn.addEventListener("click", () => {
  const taskId = modalTaskIdEl.value;
  socket.emit("task:update", {
    taskId,
    title: modalTitleEl.value,
    description: modalDescriptionEl.value
  });
  closeTaskModal();
});

deleteTaskBtn.addEventListener("click", () => {
  const taskId = modalTaskIdEl.value;
  if (!taskId) return;
  socket.emit("task:delete", { taskId });
  closeTaskModal();
});

closeModalBtn.addEventListener("click", closeTaskModal);

modalEl.addEventListener("click", (e) => {
  if (e.target === modalEl) closeTaskModal();
});

addColumnBtn.addEventListener("click", () => {
  const title = prompt("Column name:");
  if (!title) return;
  socket.emit("column:create", { title });
});

function escapeHtml(str = "") {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
