const express = require("express");
const http = require("http");
const path = require("path");
const WebSocket = require("ws");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        {
          id: "task-1",
          title: "Set up project repo",
          description: "Initialize repository and add README",
          assignee: "Alex"
        },
        {
          id: "task-2",
          title: "Design homepage",
          description: "Create first mockup for dashboard",
          assignee: "Sam"
        }
      ]
    },
    {
      id: "inprogress",
      title: "In Progress",
      tasks: [
        {
          id: "task-3",
          title: "Build API server",
          description: "Create Express and WebSocket backend",
          assignee: "Jordan"
        }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        {
          id: "task-4",
          title: "Requirements gathering",
          description: "Collect application requirements",
          assignee: "Taylor"
        }
      ]
    }
  ]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  broadcast({ type: "BOARD_UPDATE", payload: boardState });
  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "BOARD_INIT", payload: boardState }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message);

      if (data.type === "BOARD_UPDATE") {
        boardState = data.payload;
        broadcast({ type: "BOARD_UPDATE", payload: boardState });
      }
    } catch (err) {
      console.error("Invalid WebSocket message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
