## 5. `public/app.js`

```js
const boardEl = document.getElementById("board");
const addColumnBtn = document.getElementById("add-column-btn");
const taskTemplate = document.getElementById("task-template");
const columnTemplate = document.getElementById("column-template");

let boardState = { columns: [] };
let draggedTaskId = null;
let draggedFromColumnId = null;

const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
const socket = new WebSocket(`${protocol}//${window.location.host}`);

socket.addEventListener("message", (event) => {
  const data = JSON.parse(event.data);

  if (data.type === "BOARD_INIT" || data.type === "BOARD_UPDATE") {
    boardState = data.payload;
    renderBoard();
  }
});

async function fetchBoard() {
  const res = await fetch("/api/board");
  boardState = await res.json();
  renderBoard();
}

function saveBoard() {
  socket.send(JSON.stringify({
    type: "BOARD_UPDATE",
    payload: boardState
  }));
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    columnNode.dataset.columnId = column.id;

    const titleEl = columnNode.querySelector(".column-title");
    const addTaskBtn = columnNode.querySelector(".add-task-btn");
    const taskList = columnNode.querySelector(".task-list");

    titleEl.textContent = column.title;

    addTaskBtn.addEventListener("click", () => addTask(column.id));

    columnNode.addEventListener("dragover", (e) => {
      e.preventDefault();
      columnNode.classList.add("drag-over");
    });

    columnNode.addEventListener("dragleave", () => {
      columnNode.classList.remove("drag-over");
    });

    columnNode.addEventListener("drop", (e) => {
      e.preventDefault();
      columnNode.classList.remove("drag-over");
      moveTask(draggedTaskId, draggedFromColumnId, column.id);
    });

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      taskNode.dataset.taskId = task.id;

      taskNode.querySelector(".task-title").textContent = task.title;
      taskNode.querySelector(".task-description").textContent = task.description;
      taskNode.querySelector(".task-assignee").textContent = task.assignee || "Unassigned";

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        taskNode.classList.remove("dragging");
      });

      taskNode.querySelector(".edit-task-btn").addEventListener("click", () => {
        editTask(column.id, task.id);
      });

      taskNode.querySelector(".delete-task-btn").addEventListener("click", () => {
        deleteTask(column.id, task.id);
      });

      taskList.appendChild(taskNode);
    });

    boardEl.appendChild(columnNode);
  });
}

function addTask(columnId) {
  const title = prompt("Task title:");
  if (!title) return;

  const description = prompt("Task description:") || "";
  const assignee = prompt("Assignee:") || "";

  const column = boardState.columns.find((c) => c.id === columnId);
  column.tasks.push({
    id: `task-${Date.now()}`,
    title,
    description,
    assignee
  });

  renderBoard();
  saveBoard();
}

function editTask(columnId, taskId) {
  const column = boardState.columns.find((c) => c.id === columnId);
  const task = column.tasks.find((t) => t.id === taskId);
  if (!task) return;

  const title = prompt("Edit title:", task.title);
  if (title === null) return;

  const description = prompt("Edit description:", task.description);
  if (description === null) return;

  const assignee = prompt("Edit assignee:", task.assignee);
  if (assignee === null) return;

  task.title = title;
  task.description = description;
  task.assignee = assignee;

  renderBoard();
  saveBoard();
}

function deleteTask(columnId, taskId) {
  const column = boardState.columns.find((c) => c.id === columnId);
  column.tasks = column.tasks.filter((t) => t.id !== taskId);

  renderBoard();
  saveBoard();
}

function moveTask(taskId, fromColumnId, toColumnId) {
  if (!taskId || !fromColumnId || !toColumnId) return;

  const fromColumn = boardState.columns.find((c) => c.id === fromColumnId);
  const toColumn = boardState.columns.find((c) => c.id === toColumnId);
  if (!fromColumn || !toColumn) return;

  const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = fromColumn.tasks.splice(taskIndex, 1);
  toColumn.tasks.push(task);

  draggedTaskId = null;
  draggedFromColumnId = null;

  renderBoard();
  saveBoard();
}

addColumnBtn.addEventListener("click", () => {
  const title = prompt("Column title:");
  if (!title) return;

  boardState.columns.push({
    id: `column-${Date.now()}`,
    title,
    tasks: []
  });

  renderBoard();
  saveBoard();
});

fetchBoard();
```

