# 2) Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory board state
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

// Seed sample tasks
const task1 = {
  id: uuidv4(),
  title: "Design landing page",
  description: "Create wireframes and visual mockups",
  assignee: "Alice",
  priority: "High",
  createdAt: Date.now()
};

const task2 = {
  id: uuidv4(),
  title: "Set up API server",
  description: "Initialize Express app and routes",
  assignee: "Bob",
  priority: "Medium",
  createdAt: Date.now()
};

board.tasks[task1.id] = task1;
board.tasks[task2.id] = task2;
board.columns[0].taskIds.push(task1.id, task2.id);

// REST API
app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "", priority = "Low", columnId = "todo" } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const newTask = {
    id: uuidv4(),
    title: title.trim(),
    description,
    assignee,
    priority,
    createdAt: Date.now()
  };

  board.tasks[newTask.id] = newTask;

  const column = board.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Invalid columnId" });
  }

  column.taskIds.push(newTask.id);

  io.emit("board:update", board);
  res.status(201).json(newTask);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const existing = board.tasks[taskId];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updatedTask = {
    ...existing,
    ...req.body,
    id: taskId
  };

  board.tasks[taskId] = updatedTask;

  io.emit("board:update", board);
  res.json(updatedTask);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];

  board.columns = board.columns.map(col => ({
    ...col,
    taskIds: col.taskIds.filter(id => id !== taskId)
  }));

  io.emit("board:update", board);
  res.json({ success: true });
});

app.post("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid source or destination column" });
  }

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const insertIndex =
    typeof destinationIndex === "number" &&
    destinationIndex >= 0 &&
    destinationIndex <= destinationColumn.taskIds.length
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  io.emit("board:update", board);
  res.json(board);
});

// Socket.IO
io.on("connection", socket => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:create", payload => {
    const { title, description = "", assignee = "", priority = "Low", columnId = "todo" } = payload;

    if (!title || !title.trim()) return;

    const newTask = {
      id: uuidv4(),
      title: title.trim(),
      description,
      assignee,
      priority,
      createdAt: Date.now()
    };

    board.tasks[newTask.id] = newTask;

    const column = board.columns.find(c => c.id === columnId);
    if (column) {
      column.taskIds.push(newTask.id);
      io.emit("board:update", board);
    }
  });

  socket.on("task:update", payload => {
    const { taskId, updates } = payload;
    if (!board.tasks[taskId]) return;

    board.tasks[taskId] = {
      ...board.tasks[taskId],
      ...updates,
      id: taskId
    };

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId }) => {
    if (!board.tasks[taskId]) return;

    delete board.tasks[taskId];
    board.columns.forEach(col => {
      col.taskIds = col.taskIds.filter(id => id !== taskId);
    });

    io.emit("board:update", board);
  });

  socket.on("task:move", payload => {
    const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = payload;

    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn || !board.tasks[taskId]) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

    const insertIndex =
      typeof destinationIndex === "number" &&
      destinationIndex >= 0 &&
      destinationIndex <= destinationColumn.taskIds.length
        ? destinationIndex
        : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

