# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:4000/api";
const SOCKET_URL = "http://localhost:4000";

const socket = io(SOCKET_URL);

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const taskModal = document.getElementById("taskModal");
const openTaskModalBtn = document.getElementById("openTaskModalBtn");
const cancelModalBtn = document.getElementById("cancelModalBtn");
const taskForm = document.getElementById("taskForm");
const modalTitle = document.getElementById("modalTitle");

const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const assigneeInput = document.getElementById("assignee");
const priorityInput = document.getElementById("priority");
const columnIdInput = document.getElementById("columnId");

function openModal(task = null, columnId = "todo") {
  taskModal.classList.remove("hidden");

  if (task) {
    modalTitle.textContent = "Edit Task";
    taskIdInput.value = task.id;
    titleInput.value = task.title || "";
    descriptionInput.value = task.description || "";
    assigneeInput.value = task.assignee || "";
    priorityInput.value = task.priority || "Low";
    columnIdInput.value = findTaskColumnId(task.id) || "todo";
  } else {
    modalTitle.textContent = "Create Task";
    taskForm.reset();
    taskIdInput.value = "";
    columnIdInput.value = columnId;
  }
}

function closeModal() {
  taskModal.classList.add("hidden");
  taskForm.reset();
  taskIdInput.value = "";
}

function findTaskColumnId(taskId) {
  for (const column of boardState.columns) {
    if (column.taskIds.includes(taskId)) return column.id;
  }
  return null;
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const headerEl = document.createElement("div");
    headerEl.className = "column-header";

    const titleEl = document.createElement("div");
    titleEl.className = "column-title";
    titleEl.textContent = `${column.title} (${column.taskIds.length})`;

    const addBtn = document.createElement("button");
    addBtn.textContent = "+";
    addBtn.addEventListener("click", () => openModal(null, column.id));

    headerEl.appendChild(titleEl);
    headerEl.appendChild(addBtn);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      const draggingEl = document.querySelector(".dragging");
      if (!draggingEl) return;

      if (afterElement == null) {
        taskListEl.appendChild(draggingEl);
      } else {
        taskListEl.insertBefore(draggingEl, afterElement);
      }
    });

    taskListEl.addEventListener("drop", e => {
      e.preventDefault();

      const destinationColumnId = taskListEl.dataset.columnId;
      const taskElements = [...taskListEl.querySelectorAll(".task-card")];
      const destinationIndex = taskElements.findIndex(el => el.dataset.taskId === draggedTaskId);

      if (draggedTaskId && draggedFromColumnId && destinationColumnId) {
        socket.emit("task:move", {
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex: destinationIndex === -1 ? taskElements.length : destinationIndex
        });
      }

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
        <div class="task-meta">Priority: ${escapeHtml(task.priority || "Low")}</div>
        <div class="task-meta">${escapeHtml(task.description || "")}</div>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.querySelector(".edit-btn").addEventListener("click", () => {
        openModal(task);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        if (confirm(`Delete "${task.title}"?`)) {
          socket.emit("task:delete", { taskId: task.id });
        }
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(headerEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task-card:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

openTaskModalBtn.addEventListener("click", () => openModal());
cancelModalBtn.addEventListener("click", closeModal);

taskModal.addEventListener("click", e => {
  if (e.target === taskModal) closeModal();
});

taskForm.addEventListener("submit", e => {
  e.preventDefault();

  const taskId = taskIdInput.value.trim();
  const payload = {
    title: titleInput.value.trim(),
    description: descriptionInput.value.trim(),
    assignee: assigneeInput.value.trim(),
    priority: priorityInput.value,
    columnId: columnIdInput.value
  };

  if (!payload.title) {
    alert("Title is required");
    return;
  }

  if (taskId) {
    const currentColumnId = findTaskColumnId(taskId);

    socket.emit("task:update", {
      taskId,
      updates: {
        title: payload.title,
        description: payload.description,
        assignee: payload.assignee,
        priority: payload.priority
      }
    });

    if (currentColumnId && currentColumnId !== payload.columnId) {
      socket.emit("task:move", {
        taskId,
        sourceColumnId: currentColumnId,
        destinationColumnId: payload.columnId,
        destinationIndex: boardState.columns.find(c => c.id === payload.columnId)?.taskIds.length || 0
      });
    }
  } else {
    socket.emit("task:create", payload);
  }

  closeModal();
});

socket.on("board:init", board => {
  boardState = board;
  renderBoard();
});

socket.on("board:update", board => {
  boardState = board;
  renderBoard();
});

async function loadBoardFallback() {
  try {
    const res = await fetch(`${API_URL}/board`);
    const data = await res.json();
    boardState = data;
    renderBoard();
  } catch (err) {
    console.error("Failed to load board:", err);
  }
}

loadBoardFallback();
```

