# 3. Backend: `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

const PORT = 4000;

/**
 * In-memory board state
 * Replace with a database in production.
 */
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const taskId = uuidv4();
  const task = {
    id: taskId,
    title: title.trim(),
    description,
    createdAt: new Date().toISOString()
  };

  board.tasks[taskId] = task;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Invalid columnId" });
  }

  column.taskIds.push(taskId);

  io.emit("board:update", board);

  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const taskId = req.params.id;
  const { title, description } = req.body;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  if (title !== undefined) board.tasks[taskId].title = title;
  if (description !== undefined) board.tasks[taskId].description = description;

  io.emit("board:update", board);

  res.json(board.tasks[taskId]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const taskId = req.params.id;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];

  board.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  io.emit("board:update", board);

  res.json({ success: true });
});

app.post("/api/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column id" });
  }

  const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(404).json({ error: "Task not found in source column" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);

  const insertIndex =
    typeof destinationIndex === "number"
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  io.emit("board:update", board);

  res.json(board);
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", ({ title, description, columnId = "todo" }) => {
    if (!title || !title.trim()) return;

    const taskId = uuidv4();
    const task = {
      id: taskId,
      title: title.trim(),
      description: description || "",
      createdAt: new Date().toISOString()
    };

    board.tasks[taskId] = task;

    const column = board.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(taskId);
      io.emit("board:update", board);
    }
  });

  socket.on("task:update", ({ id, title, description }) => {
    if (!board.tasks[id]) return;

    if (title !== undefined) board.tasks[id].title = title;
    if (description !== undefined) board.tasks[id].description = description;

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ id }) => {
    if (!board.tasks[id]) return;

    delete board.tasks[id];
    board.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((taskId) => taskId !== id);
    });

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceColumn.taskIds.splice(sourceIndex, 1);

    const insertIndex =
      typeof destinationIndex === "number"
        ? destinationIndex
        : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
