# 2) Backend: `server/server.js`

```js
const express = require("express");
const cors = require("cors");
const http = require("http");
const WebSocket = require("ws");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

const PORT = 3000;

/**
 * In-memory demo data
 * Replace with a database in production.
 */
let board = {
  id: "board-1",
  name: "Team Project Board",
  columns: [
    {
      id: "col-1",
      title: "Backlog",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "col-2",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "col-3",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up repository",
      description: "Initialize GitHub repo and branch rules",
      assignee: "Alice"
    },
    "task-2": {
      id: "task-2",
      title: "Design homepage",
      description: "Create initial wireframes",
      assignee: "Bob"
    },
    "task-3": {
      id: "task-3",
      title: "Build login page",
      description: "Implement login UI and validation",
      assignee: "Charlie"
    }
  }
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/task", (req, res) => {
  const { columnId, title, description, assignee } = req.body;
  if (!columnId || !title) {
    return res.status(400).json({ error: "columnId and title are required" });
  }

  const taskId = `task-${Date.now()}`;
  const task = {
    id: taskId,
    title,
    description: description || "",
    assignee: assignee || ""
  };

  board.tasks[taskId] = task;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(taskId);

  broadcast({ type: "BOARD_UPDATED", payload: board });
  res.json(task);
});

app.put("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description, assignee } = req.body;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[taskId] = {
    ...board.tasks[taskId],
    title: title ?? board.tasks[taskId].title,
    description: description ?? board.tasks[taskId].description,
    assignee: assignee ?? board.tasks[taskId].assignee
  };

  broadcast({ type: "BOARD_UPDATED", payload: board });
  res.json(board.tasks[taskId]);
});

app.delete("/api/task/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];
  board.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  broadcast({ type: "BOARD_UPDATED", payload: board });
  res.json({ success: true });
});

app.put("/api/board/reorder", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  broadcast({ type: "BOARD_UPDATED", payload: board });
  res.json(board);
});

app.post("/api/column", (req, res) => {
  const { title } = req.body;
  if (!title) {
    return res.status(400).json({ error: "title is required" });
  }

  const column = {
    id: `col-${Date.now()}`,
    title,
    taskIds: []
  };

  board.columns.push(column);
  broadcast({ type: "BOARD_UPDATED", payload: board });
  res.json(column);
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "BOARD_UPDATED", payload: board }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

