# 5) Frontend: `client/app.js`

```js
const API_URL = "http://localhost:3000/api";
const WS_URL = "ws://localhost:3000";

let boardState = null;
let editingTaskId = null;

const boardEl = document.getElementById("board");
const taskColumnSelect = document.getElementById("task-column-select");
const addTaskBtn = document.getElementById("add-task-btn");
const addColumnBtn = document.getElementById("add-column-btn");

const taskTitleInput = document.getElementById("task-title");
const taskAssigneeInput = document.getElementById("task-assignee");
const taskDescriptionInput = document.getElementById("task-description");
const newColumnTitleInput = document.getElementById("new-column-title");

const modal = document.getElementById("task-modal");
const editTitleInput = document.getElementById("edit-title");
const editAssigneeInput = document.getElementById("edit-assignee");
const editDescriptionInput = document.getElementById("edit-description");
const saveTaskBtn = document.getElementById("save-task-btn");
const deleteTaskBtn = document.getElementById("delete-task-btn");
const closeModalBtn = document.getElementById("close-modal-btn");

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";
  taskColumnSelect.innerHTML = "";

  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnSelect.appendChild(option);

    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h3");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();

      const taskId = e.dataTransfer.getData("taskId");
      const sourceColumnId = e.dataTransfer.getData("sourceColumnId");
      const sourceIndex = Number(e.dataTransfer.getData("sourceIndex"));
      const destinationColumnId = column.id;

      const destinationTaskEl = e.target.closest(".task-card");
      let destinationIndex = column.taskIds.length;

      if (destinationTaskEl) {
        destinationIndex = Number(destinationTaskEl.dataset.index);
      }

      await fetch(`${API_URL}/board/reorder`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId,
          sourceColumnId,
          destinationColumnId,
          sourceIndex,
          destinationIndex
        })
      });
    });

    column.taskIds.forEach((taskId, index) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div>${escapeHtml(task.description || "")}</div>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        taskEl.classList.add("dragging");
        e.dataTransfer.setData("taskId", task.id);
        e.dataTransfer.setData("sourceColumnId", column.id);
        e.dataTransfer.setData("sourceIndex", index.toString());
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.addEventListener("click", () => openEditModal(task.id));

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

async function addTask() {
  const columnId = taskColumnSelect.value;
  const title = taskTitleInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();
  const description = taskDescriptionInput.value.trim();

  if (!title) {
    alert("Task title is required");
    return;
  }

  await fetch(`${API_URL}/task`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ columnId, title, assignee, description })
  });

  taskTitleInput.value = "";
  taskAssigneeInput.value = "";
  taskDescriptionInput.value = "";
}

async function addColumn() {
  const title = newColumnTitleInput.value.trim();
  if (!title) {
    alert("Column title is required");
    return;
  }

  await fetch(`${API_URL}/column`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title })
  });

  newColumnTitleInput.value = "";
}

function openEditModal(taskId) {
  editingTaskId = taskId;
  const task = boardState.tasks[taskId];
  if (!task) return;

  editTitleInput.value = task.title;
  editAssigneeInput.value = task.assignee || "";
  editDescriptionInput.value = task.description || "";
  modal.classList.remove("hidden");
}

function closeModal() {
  modal.classList.add("hidden");
  editingTaskId = null;
}

async function saveTask() {
  if (!editingTaskId) return;

  await fetch(`${API_URL}/task/${editingTaskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title: editTitleInput.value.trim(),
      assignee: editAssigneeInput.value.trim(),
      description: editDescriptionInput.value.trim()
    })
  });

  closeModal();
}

async function deleteTask() {
  if (!editingTaskId) return;

  await fetch(`${API_URL}/task/${editingTaskId}`, {
    method: "DELETE"
  });

  closeModal();
}

function connectWebSocket() {
  const ws = new WebSocket(WS_URL);

  ws.onopen = () => {
    console.log("Connected to WebSocket server");
  };

  ws.onmessage = (event) => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATED") {
      boardState = data.payload;
      renderBoard();
    }
  };

  ws.onclose = () => {
    console.log("WebSocket disconnected. Reconnecting...");
    setTimeout(connectWebSocket, 2000);
  };
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

addTaskBtn.addEventListener("click", addTask);
addColumnBtn.addEventListener("click", addColumn);
saveTaskBtn.addEventListener("click", saveTask);
deleteTaskBtn.addEventListener("click", deleteTask);
closeModalBtn.addEventListener("click", closeModal);

window.addEventListener("click", (e) => {
  if (e.target === modal) {
    closeModal();
  }
});

fetchBoard();
connectWebSocket();
