# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static("public"));

const board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "inprogress", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

// Seed data
const seedTasks = [
  { title: "Design landing page", description: "Create the initial UI mockups", columnId: "todo" },
  { title: "Set up API", description: "Build REST endpoints for tasks", columnId: "inprogress" },
  { title: "Deploy prototype", description: "Deploy first version to staging", columnId: "done" }
];

seedTasks.forEach(task => {
  const id = uuidv4();
  board.tasks[id] = {
    id,
    title: task.title,
    description: task.description
  };
  const column = board.columns.find(c => c.id === task.columnId);
  column.taskIds.push(id);
});

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;
  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const column = board.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Invalid columnId" });
  }

  const id = uuidv4();
  const task = { id, title, description };
  board.tasks[id] = task;
  column.taskIds.push(id);

  broadcast({ type: "TASK_CREATED", payload: { task, columnId } });
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...board.tasks[id],
    title: title ?? board.tasks[id].title,
    description: description ?? board.tasks[id].description
  };

  broadcast({ type: "TASK_UPDATED", payload: board.tasks[id] });
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];
  board.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  });

  broadcast({ type: "TASK_DELETED", payload: { id } });
  res.status(204).send();
});

app.post("/api/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column IDs" });
  }

  const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(400).json({ error: "Task not found in source column" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  broadcast({
    type: "TASK_MOVED",
    payload: {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    }
  });

  res.json({ success: true });
});

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "BOARD_STATE", payload: board }));
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

