# 5. `public/app.js`

```js
let boardState = { columns: [], tasks: {} };
let draggedTaskId = null;
let sourceColumnId = null;

const boardEl = document.getElementById("board");
const newTaskBtn = document.getElementById("newTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const cancelBtn = document.getElementById("cancelBtn");

const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");
const dialogTitle = document.getElementById("dialogTitle");

async function fetchBoard() {
  const res = await fetch("/api/board");
  boardState = await res.json();
  renderBoard();
  populateColumnOptions();
}

function populateColumnOptions() {
  taskColumnSelect.innerHTML = "";
  boardState.columns.forEach(column => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnSelect.appendChild(option);
  });
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      const afterElement = getDragAfterElement(taskListEl, e.clientY);
      const draggingEl = document.querySelector(".dragging");
      if (!draggingEl) return;

      if (afterElement == null) {
        taskListEl.appendChild(draggingEl);
      } else {
        taskListEl.insertBefore(draggingEl, afterElement);
      }
    });

    taskListEl.addEventListener("drop", async e => {
      e.preventDefault();
      if (!draggedTaskId || !sourceColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const taskElements = [...taskListEl.querySelectorAll(".task")];
      const destinationIndex = taskElements.findIndex(el => el.dataset.taskId === draggedTaskId);

      await fetch("/api/move", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId,
          destinationColumnId,
          destinationIndex: destinationIndex === -1 ? taskElements.length : destinationIndex
        })
      });

      draggedTaskId = null;
      sourceColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        sourceColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".edit-btn").addEventListener("click", () => {
        openEditDialog(task.id, column.id);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", async () => {
        await fetch(`/api/tasks/${task.id}`, { method: "DELETE" });
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      return { offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

function openNewDialog() {
  dialogTitle.textContent = "New Task";
  taskIdInput.value = "";
  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskColumnSelect.value = boardState.columns[0]?.id || "todo";
  taskDialog.showModal();
}

function openEditDialog(taskId, columnId) {
  const task = boardState.tasks[taskId];
  if (!task) return;

  dialogTitle.textContent = "Edit Task";
  taskIdInput.value = task.id;
  taskTitleInput.value = task.title;
  taskDescriptionInput.value = task.description || "";
  taskColumnSelect.value = columnId;
  taskDialog.showModal();
}

taskForm.addEventListener("submit", async e => {
  e.preventDefault();

  const id = taskIdInput.value.trim();
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  if (id) {
    await fetch(`/api/tasks/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description })
    });

    const currentColumn = boardState.columns.find(c => c.taskIds.includes(id));
    if (currentColumn && currentColumn.id !== columnId) {
      await fetch("/api/move", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: id,
          sourceColumnId: currentColumn.id,
          destinationColumnId: columnId,
          destinationIndex: boardState.columns.find(c => c.id === columnId)?.taskIds.length || 0
        })
      });
    }
  } else {
    await fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, columnId })
    });
  }

  taskDialog.close();
});

cancelBtn.addEventListener("click", () => {
  taskDialog.close();
});

newTaskBtn.addEventListener("click", openNewDialog);

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

const protocol = location.protocol === "https:" ? "wss" : "ws";
const socket = new WebSocket(`${protocol}://${location.host}`);

socket.addEventListener("message", event => {
  const message = JSON.parse(event.data);

  switch (message.type) {
    case "BOARD_STATE":
      boardState = message.payload;
      renderBoard();
      populateColumnOptions();
      break;

    case "TASK_CREATED": {
      const { task, columnId } = message.payload;
      boardState.tasks[task.id] = task;
      const column = boardState.columns.find(c => c.id === columnId);
      if (column && !column.taskIds.includes(task.id)) {
        column.taskIds.push(task.id);
      }
      renderBoard();
      break;
    }

    case "TASK_UPDATED":
      boardState.tasks[message.payload.id] = message.payload;
      renderBoard();
      break;

    case "TASK_DELETED": {
      const { id } = message.payload;
      delete boardState.tasks[id];
      boardState.columns.forEach(column => {
        column.taskIds = column.taskIds.filter(taskId => taskId !== id);
      });
      renderBoard();
      break;
    }

    case "TASK_MOVED": {
      const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = message.payload;
      const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
      const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

      if (sourceColumn) {
        sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
      }

      if (destinationColumn) {
        destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
      }

      renderBoard();
      break;
    }
  }
});

fetchBoard();
```

