const express = require('express');
const http = require('http');
const path = require('path');
const WebSocket = require('ws');
const { v4: uuidv4 } = require('uuid');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// In-memory board state
let board = {
  columns: [
    { id: 'todo', title: 'To Do', taskIds: [] },
    { id: 'inprogress', title: 'In Progress', taskIds: [] },
    { id: 'done', title: 'Done', taskIds: [] }
  ],
  tasks: {}
};

// Seed data
const seedTasks = [
  { title: 'Set up project repo', description: 'Initialize Git repository and README', status: 'todo' },
  { title: 'Design task board UI', description: 'Create responsive board layout', status: 'inprogress' },
  { title: 'Implement WebSocket sync', description: 'Broadcast board changes to all clients', status: 'done' }
];

seedTasks.forEach(task => {
  const id = uuidv4();
  board.tasks[id] = {
    id,
    title: task.title,
    description: task.description,
    assignee: '',
    dueDate: '',
    status: task.status,
    updatedAt: Date.now()
  };
  const column = board.columns.find(c => c.id === task.status);
  if (column) column.taskIds.push(id);
});

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

function sendBoard(ws) {
  ws.send(JSON.stringify({ type: 'board_state', payload: board }));
}

app.get('/api/board', (req, res) => {
  res.json(board);
});

app.post('/api/tasks', (req, res) => {
  const { title, description = '', assignee = '', dueDate = '', status = 'todo' } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: 'Title is required' });
  }

  const id = uuidv4();
  const task = {
    id,
    title: title.trim(),
    description,
    assignee,
    dueDate,
    status,
    updatedAt: Date.now()
  };

  board.tasks[id] = task;

  const column = board.columns.find(c => c.id === status);
  if (column) {
    column.taskIds.push(id);
  } else {
    board.columns[0].taskIds.push(id);
    task.status = board.columns[0].id;
  }

  broadcast({ type: 'task_created', payload: task });
  broadcast({ type: 'board_state', payload: board });

  res.status(201).json(task);
});

app.put('/api/tasks/:id', (req, res) => {
  const { id } = req.params;
  const existing = board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const prevStatus = existing.status;
  const {
    title = existing.title,
    description = existing.description,
    assignee = existing.assignee,
    dueDate = existing.dueDate,
    status = existing.status
  } = req.body;

  existing.title = title;
  existing.description = description;
  existing.assignee = assignee;
  existing.dueDate = dueDate;
  existing.status = status;
  existing.updatedAt = Date.now();

  if (prevStatus !== status) {
    const prevColumn = board.columns.find(c => c.id === prevStatus);
    const nextColumn = board.columns.find(c => c.id === status);

    if (prevColumn) {
      prevColumn.taskIds = prevColumn.taskIds.filter(taskId => taskId !== id);
    }
    if (nextColumn) {
      nextColumn.taskIds.push(id);
    }
  }

  broadcast({ type: 'task_updated', payload: existing });
  broadcast({ type: 'board_state', payload: board });

  res.json(existing);
});

app.delete('/api/tasks/:id', (req, res) => {
  const { id } = req.params;
  const existing = board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const column = board.columns.find(c => c.id === existing.status);
  if (column) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  delete board.tasks[id];

  broadcast({ type: 'task_deleted', payload: { id } });
  broadcast({ type: 'board_state', payload: board });

  res.json({ success: true });
});

app.post('/api/board/move', (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);
  const task = board.tasks[taskId];

  if (!sourceColumn || !destinationColumn || !task) {
    return res.status(400).json({ error: 'Invalid move request' });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const insertIndex =
    typeof destinationIndex === 'number' &&
    destinationIndex >= 0 &&
    destinationIndex <= destinationColumn.taskIds.length
      ? destinationIndex
      : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);
  task.status = destinationColumnId;
  task.updatedAt = Date.now();

  broadcast({
    type: 'task_moved',
    payload: { taskId, sourceColumnId, destinationColumnId, destinationIndex: insertIndex }
  });
  broadcast({ type: 'board_state', payload: board });

  res.json({ success: true, board });
});

wss.on('connection', ws => {
  sendBoard(ws);

  ws.on('message', raw => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === 'ping') {
        ws.send(JSON.stringify({ type: 'pong' }));
      }
    } catch (err) {
      console.error('Invalid WS message:', err.message);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
