# 5. `public/app.js`

```js
const boardEl = document.getElementById('board');
const taskForm = document.getElementById('taskForm');
const editModal = document.getElementById('editModal');
const editTaskForm = document.getElementById('editTaskForm');
const cancelEditBtn = document.getElementById('cancelEdit');
const statusDot = document.getElementById('statusDot');
const statusText = document.getElementById('statusText');

let boardState = { columns: [], tasks: {} };
let draggedTaskId = null;
let socket = null;

function setConnectionStatus(online) {
  statusDot.classList.toggle('online', online);
  statusDot.classList.toggle('offline', !online);
  statusText.textContent = online ? 'Online' : 'Offline';
}

async function fetchBoard() {
  const res = await fetch('/api/board');
  boardState = await res.json();
  renderBoard();
}

function connectWebSocket() {
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  socket = new WebSocket(`${protocol}//${window.location.host}`);

  socket.addEventListener('open', () => {
    setConnectionStatus(true);
  });

  socket.addEventListener('close', () => {
    setConnectionStatus(false);
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener('message', event => {
    const message = JSON.parse(event.data);

    if (message.type === 'board_state') {
      boardState = message.payload;
      renderBoard();
    }
  });
}

function renderBoard() {
  boardEl.innerHTML = '';

  boardState.columns.forEach(column => {
    const columnEl = document.createElement('div');
    columnEl.className = 'column';
    columnEl.dataset.columnId = column.id;

    const title = document.createElement('h2');
    title.textContent = `${column.title} (${column.taskIds.length})`;

    const taskList = document.createElement('div');
    taskList.className = 'task-list';
    taskList.dataset.columnId = column.id;

    taskList.addEventListener('dragover', e => {
      e.preventDefault();
      taskList.classList.add('drop-zone-active');
    });

    taskList.addEventListener('dragleave', () => {
      taskList.classList.remove('drop-zone-active');
    });

    taskList.addEventListener('drop', async e => {
      e.preventDefault();
      taskList.classList.remove('drop-zone-active');

      if (!draggedTaskId) return;

      const sourceColumnId = findTaskColumnId(draggedTaskId);
      const destinationColumnId = column.id;

      if (!sourceColumnId || !destinationColumnId) return;

      await fetch('/api/board/move', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId,
          destinationColumnId,
          destinationIndex: boardState.columns.find(c => c.id === destinationColumnId).taskIds.length
        })
      });

      draggedTaskId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const card = document.createElement('div');
      card.className = 'task-card';
      card.draggable = true;
      card.dataset.taskId = task.id;

      card.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        card.classList.add('dragging');
      });

      card.addEventListener('dragend', () => {
        card.classList.remove('dragging');
      });

      const titleEl = document.createElement('h3');
      titleEl.textContent = task.title;

      const descEl = document.createElement('p');
      descEl.textContent = task.description || 'No description';

      const metaEl = document.createElement('div');
      metaEl.className = 'task-meta';
      metaEl.innerHTML = `
        <div><strong>Assignee:</strong> ${task.assignee || 'Unassigned'}</div>
        <div><strong>Due:</strong> ${task.dueDate || 'None'}</div>
        <div><strong>Updated:</strong> ${new Date(task.updatedAt).toLocaleString()}</div>
      `;

      const actions = document.createElement('div');
      actions.className = 'task-actions';

      const editBtn = document.createElement('button');
      editBtn.className = 'edit-btn';
      editBtn.textContent = 'Edit';
      editBtn.addEventListener('click', () => openEditModal(task));

      const deleteBtn = document.createElement('button');
      deleteBtn.className = 'delete-btn';
      deleteBtn.textContent = 'Delete';
      deleteBtn.addEventListener('click', async () => {
        await fetch(`/api/tasks/${task.id}`, { method: 'DELETE' });
      });

      actions.appendChild(editBtn);
      actions.appendChild(deleteBtn);

      card.appendChild(titleEl);
      card.appendChild(descEl);
      card.appendChild(metaEl);
      card.appendChild(actions);

      taskList.appendChild(card);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

function findTaskColumnId(taskId) {
  const column = boardState.columns.find(c => c.taskIds.includes(taskId));
  return column ? column.id : null;
}

taskForm.addEventListener('submit', async e => {
  e.preventDefault();

  const payload = {
    title: document.getElementById('title').value,
    description: document.getElementById('description').value,
    assignee: document.getElementById('assignee').value,
    dueDate: document.getElementById('dueDate').value,
    status: document.getElementById('status').value
  };

  await fetch('/api/tasks', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  taskForm.reset();
});

function openEditModal(task) {
  document.getElementById('editTaskId').value = task.id;
  document.getElementById('editTitle').value = task.title;
  document.getElementById('editDescription').value = task.description;
  document.getElementById('editAssignee').value = task.assignee;
  document.getElementById('editDueDate').value = task.dueDate;
  document.getElementById('editStatus').value = task.status;
  editModal.classList.remove('hidden');
}

function closeEditModal() {
  editModal.classList.add('hidden');
}

cancelEditBtn.addEventListener('click', closeEditModal);

editTaskForm.addEventListener('submit', async e => {
  e.preventDefault();

  const id = document.getElementById('editTaskId').value;

  const payload = {
    title: document.getElementById('editTitle').value,
    description: document.getElementById('editDescription').value,
    assignee: document.getElementById('editAssignee').value,
    dueDate: document.getElementById('editDueDate').value,
    status: document.getElementById('editStatus').value
  };

  await fetch(`/api/tasks/${id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  closeEditModal();
});

window.addEventListener('load', async () => {
  await fetchBoard();
  connectWebSocket();
});
```

