# 2) `server.js`

```js
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const { v4: uuidv4 } = require('uuid');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// In-memory board state
let board = {
  columns: [
    {
      id: 'todo',
      title: 'To Do',
      taskIds: []
    },
    {
      id: 'inprogress',
      title: 'In Progress',
      taskIds: []
    },
    {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  ],
  tasks: {}
};

// Seed data
function seedBoard() {
  const tasks = [
    { title: 'Set up project repo', description: 'Initialize repository and README', columnId: 'todo' },
    { title: 'Design UI wireframes', description: 'Create board layout mockups', columnId: 'todo' },
    { title: 'Implement drag-and-drop', description: 'Enable moving tasks across columns', columnId: 'inprogress' },
    { title: 'Deploy MVP', description: 'Deploy to staging environment', columnId: 'done' }
  ];

  tasks.forEach((task) => {
    const id = uuidv4();
    board.tasks[id] = {
      id,
      title: task.title,
      description: task.description
    };
    const column = board.columns.find(c => c.id === task.columnId);
    column.taskIds.push(id);
  });
}

seedBoard();

app.get('/api/board', (req, res) => {
  res.json(board);
});

app.post('/api/tasks', (req, res) => {
  const { title, description, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: 'title and columnId are required' });
  }

  const column = board.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: 'Column not found' });
  }

  const id = uuidv4();
  const task = {
    id,
    title,
    description: description || ''
  };

  board.tasks[id] = task;
  column.taskIds.push(id);

  io.emit('taskCreated', { task, columnId });
  res.status(201).json({ task, columnId });
});

app.put('/api/tasks/:id', (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  const task = board.tasks[id];
  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  task.title = title ?? task.title;
  task.description = description ?? task.description;

  io.emit('taskUpdated', task);
  res.json(task);
});

app.delete('/api/tasks/:id', (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  delete board.tasks[id];
  board.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  });

  io.emit('taskDeleted', { taskId: id });
  res.json({ success: true });
});

app.put('/api/board/move', (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: 'Source or destination column not found' });
  }

  const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(404).json({ error: 'Task not found in source column' });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);

  const safeIndex = Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length));
  destinationColumn.taskIds.splice(safeIndex, 0, taskId);

  io.emit('taskMoved', {
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex: safeIndex
  });

  res.json({ success: true });
});

io.on('connection', (socket) => {
  console.log(`Client connected: ${socket.id}`);

  socket.emit('boardState', board);

  socket.on('disconnect', () => {
    console.log(`Client disconnected: ${socket.id}`);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
