# 5) `public/app.js`

```js
const socket = io();

let boardState = {
  columns: [],
  tasks: {}
};

const boardEl = document.getElementById('board');
const taskForm = document.getElementById('task-form');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskColumnInput = document.getElementById('task-column');

const editModal = document.getElementById('edit-modal');
const editForm = document.getElementById('edit-form');
const editTaskIdInput = document.getElementById('edit-task-id');
const editTaskTitleInput = document.getElementById('edit-task-title');
const editTaskDescriptionInput = document.getElementById('edit-task-description');
const cancelEditBtn = document.getElementById('cancel-edit');

let draggedTaskId = null;
let draggedFromColumnId = null;

async function fetchBoard() {
  const res = await fetch('/api/board');
  boardState = await res.json();
  renderBoard();
}

function renderBoard() {
  boardEl.innerHTML = '';

  boardState.columns.forEach(column => {
    const columnEl = document.createElement('div');
    columnEl.className = 'column';
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement('h2');
    titleEl.textContent = column.title;

    const taskListEl = document.createElement('div');
    taskListEl.className = 'task-list drop-zone';
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener('dragover', (e) => {
      e.preventDefault();
      taskListEl.classList.add('over');
    });

    taskListEl.addEventListener('dragleave', () => {
      taskListEl.classList.remove('over');
    });

    taskListEl.addEventListener('drop', async (e) => {
      e.preventDefault();
      taskListEl.classList.remove('over');

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const destinationIndex = getDropIndex(taskListEl, e.clientY);

      moveTaskLocally(draggedTaskId, draggedFromColumnId, destinationColumnId, destinationIndex);
      renderBoard();

      await fetch('/api/board/move', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = createTaskElement(task, column.id);
      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function createTaskElement(task, columnId) {
  const taskEl = document.createElement('div');
  taskEl.className = 'task';
  taskEl.draggable = true;
  taskEl.dataset.taskId = task.id;
  taskEl.dataset.columnId = columnId;

  taskEl.addEventListener('dragstart', () => {
    draggedTaskId = task.id;
    draggedFromColumnId = columnId;
    taskEl.classList.add('dragging');
  });

  taskEl.addEventListener('dragend', () => {
    taskEl.classList.remove('dragging');
  });

  const titleEl = document.createElement('h3');
  titleEl.textContent = task.title;

  const descEl = document.createElement('p');
  descEl.textContent = task.description || '';

  const actionsEl = document.createElement('div');
  actionsEl.className = 'task-actions';

  const editBtn = document.createElement('button');
  editBtn.className = 'edit-btn';
  editBtn.textContent = 'Edit';
  editBtn.addEventListener('click', () => openEditModal(task));

  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'delete-btn';
  deleteBtn.textContent = 'Delete';
  deleteBtn.addEventListener('click', () => deleteTask(task.id));

  actionsEl.appendChild(editBtn);
  actionsEl.appendChild(deleteBtn);

  taskEl.appendChild(titleEl);
  taskEl.appendChild(descEl);
  taskEl.appendChild(actionsEl);

  return taskEl;
}

function getDropIndex(container, mouseY) {
  const taskElements = [...container.querySelectorAll('.task:not(.dragging)')];

  let closest = {
    offset: Number.NEGATIVE_INFINITY,
    index: taskElements.length
  };

  taskElements.forEach((taskEl, index) => {
    const box = taskEl.getBoundingClientRect();
    const offset = mouseY - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

function moveTaskLocally(taskId, sourceColumnId, destinationColumnId, destinationIndex) {
  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = boardState.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) return;

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const safeIndex = Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length));
  destinationColumn.taskIds.splice(safeIndex, 0, taskId);
}

async function createTask(title, description, columnId) {
  const res = await fetch('/api/tasks', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ title, description, columnId })
  });

  if (!res.ok) {
    alert('Failed to create task');
  }
}

async function updateTask(id, title, description) {
  const res = await fetch(`/api/tasks/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ title, description })
  });

  if (!res.ok) {
    alert('Failed to update task');
  }
}

async function deleteTask(id) {
  const res = await fetch(`/api/tasks/${id}`, {
    method: 'DELETE'
  });

  if (!res.ok) {
    alert('Failed to delete task');
  }
}

function openEditModal(task) {
  editTaskIdInput.value = task.id;
  editTaskTitleInput.value = task.title;
  editTaskDescriptionInput.value = task.description || '';
  editModal.classList.remove('hidden');
}

function closeEditModal() {
  editModal.classList.add('hidden');
}

taskForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnInput.value;

  if (!title) return;

  await createTask(title, description, columnId);
  taskTitleInput.value = '';
  taskDescriptionInput.value = '';
});

editForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  const id = editTaskIdInput.value;
  const title = editTaskTitleInput.value.trim();
  const description = editTaskDescriptionInput.value.trim();

  if (!title) return;

  await updateTask(id, title, description);
  closeEditModal();
});

cancelEditBtn.addEventListener('click', closeEditModal);

socket.on('boardState', (serverBoard) => {
  boardState = serverBoard;
  renderBoard();
});

socket.on('taskCreated', ({ task, columnId }) => {
  boardState.tasks[task.id] = task;
  const column = boardState.columns.find(c => c.id === columnId);
  if (column && !column.taskIds.includes(task.id)) {
    column.taskIds.push(task.id);
  }
  renderBoard();
});

socket.on('taskUpdated', (task) => {
  boardState.tasks[task.id] = task;
  renderBoard();
});

socket.on('taskDeleted', ({ taskId }) => {
  delete boardState.tasks[taskId];
  boardState.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  });
  renderBoard();
});

socket.on('taskMoved', ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
  moveTaskLocally(taskId, sourceColumnId, destinationColumnId, destinationIndex);
  renderBoard();
});

fetchBoard();
```

