## `server/server.js`

```javascript
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

const PORT = 3000;

// In-memory board state
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Design homepage",
      description: "Create wireframes and mockups",
      assignee: "Alice"
    },
    "task-2": {
      id: "task-2",
      title: "Set up authentication",
      description: "Implement login/logout flow",
      assignee: "Bob"
    },
    "task-3": {
      id: "task-3",
      title: "Build API",
      description: "Create REST endpoints for tasks",
      assignee: "Charlie"
    }
  }
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get("/board", (req, res) => {
  res.json(board);
});

app.post("/task", (req, res) => {
  const { columnId, title, description, assignee } = req.body;
  const id = `task-${Date.now()}`;

  board.tasks[id] = {
    id,
    title,
    description,
    assignee
  };

  const column = board.columns.find((c) => c.id === columnId);
  if (column) {
    column.taskIds.push(id);
  }

  broadcast({ type: "BOARD_UPDATE", payload: board });
  res.json({ success: true, task: board.tasks[id] });
});

app.put("/task/:id", (req, res) => {
  const { id } = req.params;
  const { title, description, assignee } = req.body;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...board.tasks[id],
    title,
    description,
    assignee
  };

  broadcast({ type: "BOARD_UPDATE", payload: board });
  res.json({ success: true, task: board.tasks[id] });
});

app.delete("/task/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];
  board.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((taskId) => taskId !== id);
  });

  broadcast({ type: "BOARD_UPDATE", payload: board });
  res.json({ success: true });
});

app.post("/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  if (destinationIndex >= 0 && destinationIndex <= destinationColumn.taskIds.length) {
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
  } else {
    destinationColumn.taskIds.push(taskId);
  }

  broadcast({ type: "BOARD_UPDATE", payload: board });
  res.json({ success: true });
});

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "BOARD_UPDATE", payload: board }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err);
    }
  });

  ws.on("close", () => {
    console.log("Client disconnected");
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

