## `client/app.js`

```javascript
const API_URL = "http://localhost:3000";
const WS_URL = "ws://localhost:3000";

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskModal = document.getElementById("taskModal");
const taskForm = document.getElementById("taskForm");
const cancelBtn = document.getElementById("cancelBtn");
const modalTitle = document.getElementById("modalTitle");
const connectionStatus = document.getElementById("connectionStatus");

const taskIdInput = document.getElementById("taskId");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskAssigneeInput = document.getElementById("taskAssignee");
const taskColumnSelect = document.getElementById("taskColumn");

function openModal(edit = false, task = null, columnId = null) {
  taskModal.classList.remove("hidden");
  modalTitle.textContent = edit ? "Edit Task" : "Add Task";

  taskColumnSelect.innerHTML = "";
  boardState.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumnSelect.appendChild(option);
  });

  if (edit && task) {
    taskIdInput.value = task.id;
    taskTitleInput.value = task.title;
    taskDescriptionInput.value = task.description;
    taskAssigneeInput.value = task.assignee;

    const currentColumn = boardState.columns.find((column) =>
      column.taskIds.includes(task.id)
    );
    if (currentColumn) {
      taskColumnSelect.value = currentColumn.id;
    }
  } else {
    taskForm.reset();
    taskIdInput.value = "";
    if (columnId) taskColumnSelect.value = columnId;
  }
}

function closeModal() {
  taskModal.classList.add("hidden");
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const addBtn = document.createElement("button");
    addBtn.textContent = "+ Add";
    addBtn.addEventListener("click", () => openModal(false, null, column.id));

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", async (e) => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = column.id;
      const destinationIndex = taskList.children.length;

      await fetch(`${API_URL}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.innerHTML = `
        <h3>${task.title}</h3>
        <p>${task.description}</p>
        <p><strong>Assignee:</strong> ${task.assignee}</p>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.querySelector(".edit-btn").addEventListener("click", () => {
        openModal(true, task);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", async () => {
        await fetch(`${API_URL}/task/${task.id}`, {
          method: "DELETE"
        });
      });

      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(addBtn);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

async function loadBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const id = taskIdInput.value;
  const title = taskTitleInput.value;
  const description = taskDescriptionInput.value;
  const assignee = taskAssigneeInput.value;
  const columnId = taskColumnSelect.value;

  if (id) {
    const currentColumn = boardState.columns.find((column) =>
      column.taskIds.includes(id)
    );

    await fetch(`${API_URL}/task/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, assignee })
    });

    if (currentColumn && currentColumn.id !== columnId) {
      await fetch(`${API_URL}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: id,
          sourceColumnId: currentColumn.id,
          destinationColumnId: columnId,
          destinationIndex: boardState.columns.find(c => c.id === columnId).taskIds.length
        })
      });
    }
  } else {
    await fetch(`${API_URL}/task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, assignee, columnId })
    });
  }

  closeModal();
});

addTaskBtn.addEventListener("click", () => openModal());
cancelBtn.addEventListener("click", closeModal);

function connectWebSocket() {
  const socket = new WebSocket(WS_URL);

  socket.addEventListener("open", () => {
    connectionStatus.textContent = "Connected";
  });

  socket.addEventListener("message", (event) => {
    const data = JSON.parse(event.data);
    if (data.type === "BOARD_UPDATE") {
      boardState = data.payload;
      renderBoard();
    }
  });

  socket.addEventListener("close", () => {
    connectionStatus.textContent = "Disconnected - retrying...";
    setTimeout(connectWebSocket, 2000);
  });

  socket.addEventListener("error", () => {
    connectionStatus.textContent = "Connection error";
    socket.close();
  });
}

loadBoard();
connectWebSocket();
```

