## `server/index.js`

```js
import express from 'express';
import cors from 'cors';
import { WebSocketServer } from 'ws';
import { v4 as uuidv4 } from 'uuid';
import http from 'http';

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const boards = {
  default: {
    id: 'default',
    name: 'Team Roadmap',
    columns: [
      {
        id: 'todo',
        title: 'To Do',
        taskIds: ['t1', 't2']
      },
      {
        id: 'inprogress',
        title: 'In Progress',
        taskIds: ['t3']
      },
      {
        id: 'done',
        title: 'Done',
        taskIds: []
      }
    ],
    tasks: {
      t1: { id: 't1', title: 'Set up repo', description: 'Initialize monorepo and CI' },
      t2: { id: 't2', title: 'Design homepage', description: 'Create wireframes' },
      t3: { id: 't3', title: 'Build auth flow', description: 'Login and registration pages' }
    }
  }
};

app.get('/api/boards/:boardId', (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: 'Board not found' });
  res.json(board);
});

app.post('/api/boards/:boardId/tasks', (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: 'Board not found' });

  const { title, description = '', columnId } = req.body;
  if (!title || !columnId) {
    return res.status(400).json({ error: 'title and columnId are required' });
  }

  const taskId = uuidv4();
  board.tasks[taskId] = { id: taskId, title, description };

  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(400).json({ error: 'Invalid columnId' });

  column.taskIds.push(taskId);

  broadcast({
    type: 'TASK_CREATED',
    payload: { boardId: board.id, task: board.tasks[taskId], columnId }
  });

  res.status(201).json(board.tasks[taskId]);
});

app.put('/api/boards/:boardId/reorder', (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: 'Board not found' });

  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const sourceCol = board.columns.find(c => c.id === sourceColumnId);
  const destCol = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceCol || !destCol) {
    return res.status(400).json({ error: 'Invalid column ids' });
  }

  sourceCol.taskIds.splice(sourceIndex, 1);
  destCol.taskIds.splice(destinationIndex, 0, taskId);

  broadcast({
    type: 'TASK_MOVED',
    payload: {
      boardId: board.id,
      sourceColumnId,
      destinationColumnId,
      sourceIndex,
      destinationIndex,
      taskId
    }
  });

  res.json({ success: true });
});

const wss = new WebSocketServer({ server });

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach(client => {
    if (client.readyState === 1) {
      client.send(data);
    }
  });
}

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'CONNECTED', payload: { message: 'Realtime connected' } }));

  ws.on('message', raw => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === 'PING') {
        ws.send(JSON.stringify({ type: 'PONG' }));
      }
    } catch (err) {
      console.error('Invalid WS message', err);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

