## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from 'react';
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors
} from '@dnd-kit/core';
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

const API_URL = 'http://localhost:4000/api';
const WS_URL = 'ws://localhost:4000';

function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [selectedColumn, setSelectedColumn] = useState('todo');

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetch(`${API_URL}/boards/default`)
      .then(res => res.json())
      .then(setBoard);

    const ws = new WebSocket(WS_URL);

    ws.onmessage = event => {
      const message = JSON.parse(event.data);

      if (message.type === 'TASK_CREATED') {
        const { task, columnId } = message.payload;
        setBoard(prev => {
          if (!prev) return prev;
          const updatedColumn = prev.columns.find(c => c.id === columnId);
          return {
            ...prev,
            tasks: { ...prev.tasks, [task.id]: task },
            columns: prev.columns.map(c =>
              c.id === columnId
                ? { ...c, taskIds: [...c.taskIds, task.id] }
                : c
            )
          };
        });
      }

      if (message.type === 'TASK_MOVED') {
        const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = message.payload;
        setBoard(prev => {
          if (!prev) return prev;

          const columns = prev.columns.map(col => ({
            ...col,
            taskIds: [...col.taskIds]
          }));

          const source = columns.find(c => c.id === sourceColumnId);
          const destination = columns.find(c => c.id === destinationColumnId);

          source.taskIds.splice(sourceIndex, 1);
          destination.taskIds.splice(destinationIndex, 0, taskId);

          return { ...prev, columns };
        });
      }
    };

    return () => ws.close();
  }, []);

  const handleAddTask = async () => {
    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/boards/default/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: newTaskTitle,
        columnId: selectedColumn
      })
    });

    setNewTaskTitle('');
  };

  const handleDragEnd = async event => {
    const { active, over } = event;
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    let sourceColumn = null;
    let destinationColumn = null;
    let sourceIndex = -1;
    let destinationIndex = -1;

    for (const col of board.columns) {
      const activeIndex = col.taskIds.indexOf(activeId);
      const overIndex = col.taskIds.indexOf(overId);

      if (activeIndex !== -1) {
        sourceColumn = col;
        sourceIndex = activeIndex;
      }

      if (overIndex !== -1) {
        destinationColumn = col;
        destinationIndex = overIndex;
      }
    }

    if (!sourceColumn || !destinationColumn) return;

    await fetch(`${API_URL}/boards/default/reorder`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        sourceColumnId: sourceColumn.id,
        destinationColumnId: destinationColumn.id,
        sourceIndex,
        destinationIndex,
        taskId: activeId
      })
    });
  };

  const columns = useMemo(() => board?.columns ?? [], [board]);

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>{board.name}</h1>
        <div className="task-form">
          <input
            value={newTaskTitle}
            onChange={e => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <select value={selectedColumn} onChange={e => setSelectedColumn(e.target.value)}>
            {board.columns.map(col => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>
          <button onClick={handleAddTask}>Add Task</button>
        </div>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map(column => (
            <Column key={column.id} column={column} tasks={column.taskIds.map(id => board.tasks[id])} />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map(task => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="task-card">
      <h3>{task.title}</h3>
      <p>{task.description}</p>
    </div>
  );
}

export default App;
```

