```ts
export type Task = {
  id: string;
  title: string;
  description?: string;
};

export type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

export type Board = {
  id: string;
  title: string;
  columns: Record<string, Column>;
  columnOrder: string[];
  tasks: Record<string, Task>;
};

export type ClientMessage =
  | {
      type: "MOVE_TASK";
      payload: {
        taskId: string;
