## backend/src/ws.ts

```ts
import { WebSocketServer, WebSocket } from "ws";
import { board } from "./store";
import { ClientMessage, ServerMessage } from "./types";

function broadcast(wss: WebSocketServer, message: ServerMessage) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

export function setupWebSocket(wss: WebSocketServer) {
  wss.on("connection", (ws) => {
    ws.send(
      JSON.stringify({
        type: "BOARD_STATE",
        payload: board
      } satisfies ServerMessage)
    );

    ws.on("message", (raw) => {
      try {
        const message: ClientMessage = JSON.parse(raw.toString());

        switch (message.type) {
          case "MOVE_TASK": {
            const {
              taskId,
              sourceColumnId,
              destinationColumnId,
              sourceIndex,
              destinationIndex
            } = message.payload;

            const source = board.columns[sourceColumnId];
            const destination = board.columns[destinationColumnId];

            if (!source || !destination) break;

            source.taskIds.splice(sourceIndex, 1);
            destination.taskIds.splice(destinationIndex, 0, taskId);

            broadcast(wss, {
              type: "BOARD_STATE",
              payload: board
            });
            break;
          }

          case "CREATE_TASK": {
            const { columnId, task } = message.payload;
            board.tasks[task.id] = task;
            board.columns[columnId].taskIds.push(task.id);

            broadcast(wss, {
              type: "BOARD_STATE",
              payload: board
            });
            break;
          }

          case "UPDATE_TASK": {
            const { task } = message.payload;
            if (board.tasks[task.id]) {
              board.tasks[task.id] = task;
            }

            broadcast(wss, {
              type: "BOARD_STATE",
              payload: board
            });
            break;
          }

          case "DELETE_TASK": {
            const { taskId, columnId } = message.payload;
            delete board.tasks[taskId];
            board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
              (id) => id !== taskId
            );

            broadcast(wss, {
              type: "BOARD_STATE",
              payload: board
            });
            break;
          }
        }
      } catch {
        ws.send(
          JSON.stringify({
            type: "ERROR",
            payload: { message: "Invalid message format" }
          } satisfies ServerMessage)
        );
      }
    });
  });
}
```

