## frontend/src/App.tsx

```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { arrayMove, SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { fetchBoard } from "./api";
import { createBoardSocket, sendMessage } from "./socket";
import { Board, Task, ServerMessage } from "./types";
import BoardView from "./components/Board";

function App() {
  const [board, setBoard] = useState<Board | null>(null);
  const [socket, setSocket] = useState<WebSocket | null>(null);

  useEffect(() => {
    fetchBoard().then(setBoard);

    const ws = createBoardSocket((message: ServerMessage) => {
      if (message.type === "BOARD_STATE") {
        setBoard(message.payload);
      }
    });

    setSocket(ws);
    return () => ws.close();
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columnTasks = useMemo(() => {
    if (!board) return {};
    return Object.fromEntries(
      board.columnOrder.map((columnId) => [
        columnId,
        board.columns[columnId].taskIds.map((taskId) => board.tasks[taskId])
      ])
    );
  }, [board]);

  const handleAddTask = (columnId: string) => {
    if (!socket) return;
    const title = prompt("Task title?");
    if (!title) return;

    const task: Task = {
      id: `task-${Date.now()}`,
      title
    };

    sendMessage(socket, {
      type: "CREATE_TASK",
      payload: { columnId, task }
    });
  };

  const handleEditTask = (task: Task) => {
    if (!socket) return;
    const title = prompt("Edit task title", task.title);
    if (!title) return;

    sendMessage(socket, {
      type: "UPDATE_TASK",
      payload: {
        task: { ...task, title }
      }
    });
  };

  const handleDeleteTask = (taskId: string, columnId: string) => {
    if (!socket) return;
    sendMessage(socket, {
      type: "DELETE_TASK",
      payload: { taskId, columnId }
    });
  };

  const findTaskLocation = (taskId: string) => {
    if (!board) return null;
    for (const columnId of board.columnOrder) {
      const index = board.columns[columnId].taskIds.indexOf(taskId);
      if (index !== -1) return { columnId, index };
    }
    return null;
  };

  const handleDragEnd = (event: DragEndEvent) => {
    if (!board || !socket) return;
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const taskId = String(active.id);
    const overTaskId = String(over.id);

    const source = findTaskLocation(taskId);
    const destination = findTaskLocation(overTaskId);

    if (!source || !destination) return;

    sendMessage(socket, {
      type: "MOVE_TASK",
      payload: {
        taskId,
        sourceColumnId: source.columnId,
        destinationColumnId: destination.columnId,
        sourceIndex: source.index,
        destinationIndex: destination.index
      }
    });
  };

  if (!board) return <div>Loading...</div>;

  return (
    <div style={{ padding: 24 }}>
      <h1>{board.title}</h1>
      <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
        <BoardView
          board={board}
          columnTasks={columnTasks}
          onAddTask={handleAddTask}
          onEditTask={handleEditTask}
          onDeleteTask={handleDeleteTask}
        />
      </DndContext>
    </div>
  );
}

export default App;
```

