```js
import express from 'express';
import cors from 'cors';
import { WebSocketServer } from 'ws';
import { createServer } from 'http';
import crypto from 'crypto';

const app = express();
app.use(cors());
app.use(express.json());

const server = createServer(app);
const wss = new WebSocketServer({ server });

const boardState = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: ['task-1', 'task-2']
    },
    inprogress: {
      id: 'inprogress',
      title: 'In Progress',
      taskIds: []
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {
    'task-1': {
      id: 'task-1',
      title: 'Set up project repo',
      description: 'Initialize frontend and backend folders'
    },
    'task-2': {
      id: 'task-2',
      title: 'Design board layout',
      description: 'Create Kanban columns and task cards'
    }
  },
  columnOrder: ['todo', 'inprogress', 'done']
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === 1) {
      client.send(message);
    }
  });
}

app.get('/api/board', (req, res) => {
  res.json(boardState);
});

app.post('/api/tasks', (req, res) => {
  const { title, description = '', columnId = 'todo' } = req.body;

  if (!title) {
    return res.status(400).json({ error: 'Title is required' });
  }

  const id = crypto.randomUUID();
  boardState.tasks[id] = { id, title, description };
  boardState.columns[columnId].taskIds.push(id);

  broadcast({ type: 'BOARD_UPDATED', payload: boardState });
  res.status(201).json(boardState.tasks[id]);
});

app.put('/api/tasks/:id', (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks[id];

  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const { title, description } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;

  broadcast({ type: 'BOARD_UPDATED', payload: boardState });
  res.json(task);
});

app.delete('/api/tasks/:id', (req, res) => {
  const { id } = req.params;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  delete boardState.tasks[id];

  Object.values(boardState.columns).forEach(column => {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  });

  broadcast({ type: 'BOARD_UPDATED', payload: boardState });
  res.json({ success: true });
});

app.post('/api/move-task', (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = boardState.columns[sourceColumnId];
  const destinationColumn = boardState.columns[destinationColumnId];

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: 'Invalid column' });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  broadcast({ type: 'BOARD_UPDATED', payload: boardState });
  res.json({ success: true });
});

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'BOARD_UPDATED', payload: boardState }));

  ws.on('message', message => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === 'PING') {
        ws.send(JSON.stringify({ type: 'PONG' }));
      }
    } catch (err) {
      console.error('Invalid WS message:', err);
    }
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

