## `client/app.js`

```js
const API_URL = 'http://localhost:4000/api';
const WS_URL = 'ws://localhost:4000';

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById('board');
const taskForm = document.getElementById('task-form');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskColumnInput = document.getElementById('task-column');

async function fetchBoard() {
  const res = await fetch(`${API_URL}/board`);
  boardState = await res.json();
  renderBoard();
}

function connectWebSocket() {
  const socket = new WebSocket(WS_URL);

  socket.onopen = () => {
    console.log('WebSocket connected');
  };

  socket.onmessage = event => {
    const message = JSON.parse(event.data);
    if (message.type === 'BOARD_UPDATED') {
      boardState = message.payload;
      renderBoard();
    }
  };

  socket.onclose = () => {
    console.log('WebSocket disconnected, retrying...');
    setTimeout(connectWebSocket, 1000);
  };
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = '';

  boardState.columnOrder.forEach(columnId => {
    const column = boardState.columns[columnId];
    const columnEl = document.createElement('section');
    columnEl.className = 'column';
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const taskListEl = columnEl.querySelector('.task-list');

    taskListEl.addEventListener('dragover', e => {
      e.preventDefault();
    });

    taskListEl.addEventListener('drop', async e => {
      e.preventDefault();
      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const destinationIndex = boardState.columns[destinationColumnId].taskIds.length;

      await fetch(`${API_URL}/move-task`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destinationColumnId,
          destinationIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      const taskEl = document.createElement('article');
      taskEl.className = 'task-card';
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || '')}</p>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add('dragging');
      });

      taskEl.addEventListener('dragend', () => {
        taskEl.classList.remove('dragging');
      });

      taskEl.querySelector('.edit-btn').addEventListener('click', async () => {
        const newTitle = prompt('Edit task title', task.title);
        if (newTitle === null) return;

        const newDescription = prompt('Edit task description', task.description || '');
        if (newDescription === null) return;

        await fetch(`${API_URL}/tasks/${task.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            title: newTitle,
            description: newDescription
          })
        });
      });

      taskEl.querySelector('.delete-btn').addEventListener('click', async () => {
        await fetch(`${API_URL}/tasks/${task.id}`, {
          method: 'DELETE'
        });
      });

      taskListEl.appendChild(taskEl);
    });

    boardEl.appendChild(columnEl);
  });
}

taskForm.addEventListener('submit', async e => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnInput.value;

  if (!title) return;

  await fetch(`${API_URL}/tasks`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, description, columnId })
  });

  taskForm.reset();
});

function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

fetchBoard();
connectWebSocket();
```

