## `server/index.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT"]
  }
});

// In-memory board state
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

app.get("/board", (req, res) => {
  res.json(board);
});

app.post("/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  const id = uuidv4();
  const task = {
    id,
    title,
    description,
    createdAt: Date.now()
  };

  board.tasks[id] = task;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Invalid columnId" });
  }

  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...board.tasks[id],
    title: title ?? board.tasks[id].title,
    description: description ?? board.tasks[id].description
  };

  io.emit("board:update", board);
  res.json(board.tasks[id]);
});

app.put("/board/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  if (destinationIndex >= 0 && destinationIndex <= destinationColumn.taskIds.length) {
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
  } else {
    destinationColumn.taskIds.push(taskId);
  }

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", ({ title, description, columnId = "todo" }) => {
    if (!title) return;

    const id = uuidv4();
    const task = {
      id,
      title,
      description: description || "",
      createdAt: Date.now()
    };

    board.tasks[id] = task;

    const column = board.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(id);
      io.emit("board:update", board);
    }
  });

  socket.on("task:update", ({ id, title, description }) => {
    if (!board.tasks[id]) return;

    board.tasks[id] = {
      ...board.tasks[id],
      title: title ?? board.tasks[id].title,
      description: description ?? board.tasks[id].description
    };

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    if (destinationIndex >= 0 && destinationIndex <= destinationColumn.taskIds.length) {
      destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
    } else {
      destinationColumn.taskIds.push(taskId);
    }

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
