const { v4: uuidv4 } = require("uuid");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const state = {
  projects: [
    {
      id: "project-1",
      name: "Demo Project",
      columns: [
        {
          id: "todo",
          title: "To Do",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "in-progress",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "done",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Set up project",
          description: "Initialize repo and tooling"
        },
        "task-2": {
          id: "task-2",
          title: "Design board UI",
          description: "Create initial Kanban layout"
        },
        "task-3": {
          id: "task-3",
          title: "Implement drag and drop",
          description: "Allow moving tasks between columns"
        }
      }
    }
  ]
};

function getProject(projectId) {
  return state.projects.find((p) => p.id === projectId);
}

function broadcast(message, except = null) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN && client !== except) {
      client.send(data);
    }
  });
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.post("/api/projects", (req, res) => {
  const { name } = req.body;
  const project = {
    id: uuidv4(),
    name: name || "Untitled Project",
    columns: [
      { id: uuidv4(), title: "To Do", taskIds: [] },
      { id: uuidv4(), title: "In Progress", taskIds: [] },
      { id: uuidv4(), title: "Done", taskIds: [] }
    ],
    tasks: {}
  };
  state.projects.push(project);
  broadcast({ type: "PROJECT_CREATED", payload: project });
  res.status(201).json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const { projectId } = req.params;
  const { title, description, columnId } = req.body;
  const project = getProject(projectId);

  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const taskId = uuidv4();
  const task = {
    id: taskId,
    title: title || "Untitled Task",
    description: description || ""
  };

  project.tasks[taskId] = task;

  const column = project.columns.find((c) => c.id === columnId) || project.columns[0];
  column.taskIds.push(taskId);

  broadcast({
    type: "TASK_CREATED",
    payload: { projectId, task, columnId: column.id }
  });

  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId/move", (req, res) => {
  const { projectId, taskId } = req.params;
  const { sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const project = getProject(projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column IDs" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const insertIndex =
    typeof destinationIndex === "number" ? destinationIndex : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  const payload = {
    projectId,
    taskId,
    sourceColumnId,
    destinationColumnId,
    destinationIndex: insertIndex
  };

  broadcast({ type: "TASK_MOVED", payload });
  res.json({ success: true });
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const { projectId, taskId } = req.params;
  const { title, description } = req.body;

  const project = getProject(projectId);
  if (!project || !project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  project.tasks[taskId] = {
    ...project.tasks[taskId],
    title: title ?? project.tasks[taskId].title,
    description: description ?? project.tasks[taskId].description
  };

  broadcast({
    type: "TASK_UPDATED",
    payload: {
      projectId,
      task: project.tasks[taskId]
    }
  });

  res.json(project.tasks[taskId]);
});

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "INIT",
      payload: state
    })
  );

  ws.on("message", (message) => {
    try {
      const parsed = JSON.parse(message.toString());

      if (parsed.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message:", err.message);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
