# 5. `public/app.js`

```js
const appState = {
  projects: [],
  selectedProjectId: null
};

let socket = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

async function fetchProjects() {
  const res = await fetch("/api/projects");
  const projects = await res.json();
  appState.projects = projects;
  if (!appState.selectedProjectId && projects.length > 0) {
    appState.selectedProjectId = projects[0].id;
  }
  render();
}

function connectWebSocket() {
  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  socket = new WebSocket(`${protocol}//${window.location.host}`);

  socket.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);

    switch (message.type) {
      case "INIT":
        appState.projects = message.payload.projects;
        if (!appState.selectedProjectId && appState.projects.length > 0) {
          appState.selectedProjectId = appState.projects[0].id;
        }
        render();
        break;

      case "PROJECT_CREATED":
        appState.projects.push(message.payload);
        render();
        break;

      case "TASK_CREATED": {
        const { projectId, task, columnId } = message.payload;
        const project = appState.projects.find((p) => p.id === projectId);
        if (!project) break;
        project.tasks[task.id] = task;
        const column = project.columns.find((c) => c.id === columnId);
        if (column && !column.taskIds.includes(task.id)) {
          column.taskIds.push(task.id);
        }
        render();
        break;
      }

      case "TASK_MOVED": {
        const { projectId, taskId, sourceColumnId, destinationColumnId, destinationIndex } = message.payload;
        const project = appState.projects.find((p) => p.id === projectId);
        if (!project) break;

        const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
        const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);
        if (!sourceColumn || !destinationColumn) break;

        sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
        destinationColumn.taskIds = destinationColumn.taskIds.filter((id) => id !== taskId);
        destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

        render();
        break;
      }

      case "TASK_UPDATED": {
        const { projectId, task } = message.payload;
        const project = appState.projects.find((p) => p.id === projectId);
        if (!project) break;
        project.tasks[task.id] = task;
        render();
        break;
      }
    }
  });

  socket.addEventListener("close", () => {
    setTimeout(connectWebSocket, 1000);
  });
}

function getSelectedProject() {
  return appState.projects.find((p) => p.id === appState.selectedProjectId);
}

function render() {
  renderProjectList();
  renderBoard();
}

function renderProjectList() {
  const list = document.getElementById("project-list");
  list.innerHTML = "";

  appState.projects.forEach((project) => {
    const li = document.createElement("li");
    li.textContent = project.name;
    if (project.id === appState.selectedProjectId) {
      li.classList.add("active");
    }
    li.addEventListener("click", () => {
      appState.selectedProjectId = project.id;
      render();
    });
    list.appendChild(li);
  });
}

function renderBoard() {
  const board = document.getElementById("board");
  const boardTitle = document.getElementById("board-title");
  board.innerHTML = "";

  const project = getSelectedProject();
  if (!project) {
    boardTitle.textContent = "Select a project";
    return;
  }

  boardTitle.textContent = project.name;

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h3");
    titleEl.textContent = column.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drop-target");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drop-target");
    });

    taskListEl.addEventListener("drop", async (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drop-target");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destinationColumnId = taskListEl.dataset.columnId;
      const destinationIndex = project.columns.find((c) => c.id === destinationColumnId).taskIds.length;

      await moveTask(project.id, draggedTaskId, draggedFromColumnId, destinationColumnId, destinationIndex);

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description)}</p>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.addEventListener("dblclick", async () => {
        const newTitle = prompt("Edit task title", task.title);
        if (newTitle === null) return;
        const newDescription = prompt("Edit task description", task.description);
        if (newDescription === null) return;
        await updateTask(project.id, task.id, newTitle, newDescription);
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);
    board.appendChild(columnEl);
  });
}

async function createProject() {
  const input = document.getElementById("project-name-input");
  const name = input.value.trim();
  if (!name) return;

  const res = await fetch("/api/projects", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })
  });

  const project = await res.json();
  appState.selectedProjectId = project.id;
  input.value = "";
  render();
}

async function addTask() {
  const project = getSelectedProject();
  if (!project) return;

  const titleInput = document.getElementById("task-title-input");
  const descInput = document.getElementById("task-desc-input");

  const title = titleInput.value.trim();
  const description = descInput.value.trim();
  if (!title) return;

  const defaultColumnId = project.columns[0].id;

  await fetch(`/api/projects/${project.id}/tasks`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      title,
      description,
      columnId: defaultColumnId
    })
  });

  titleInput.value = "";
  descInput.value = "";
}

async function moveTask(projectId, taskId, sourceColumnId, destinationColumnId, destinationIndex) {
  await fetch(`/api/projects/${projectId}/tasks/${taskId}/move`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    })
  });
}

async function updateTask(projectId, taskId, title, description) {
  await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description })
  });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

document.getElementById("create-project-btn").addEventListener("click", createProject);
document.getElementById("add-task-btn").addEventListener("click", addTask);

fetchProjects();
connectWebSocket();
```

