import express from "express";
import http from "http";
import { Server } from "socket.io";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Design homepage", description: "Create landing page wireframe" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow" },
    "task-3": { id: "task-3", title: "Create API", description: "Build initial REST endpoints" }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/board", (req, res) => {
  res.json(board);
});

app.post("/task", (req, res) => {
  const { title, description, columnId } = req.body;
  const id = `task-${Date.now()}`;
  board.tasks[id] = { id, title, description };
  board.columns[columnId].taskIds.push(id);

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("board:moveTask", ({ taskId, sourceColumnId, destColumnId, destIndex }) => {
    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    const destTaskIds =
      sourceColumnId === destColumnId
        ? sourceTaskIds
        : [...board.columns[destColumnId].taskIds];

    const sourceIndex = sourceTaskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceTaskIds.splice(sourceIndex, 1);
    destTaskIds.splice(destIndex, 0, taskId);

    board.columns[sourceColumnId].taskIds =
      sourceColumnId === destColumnId ? destTaskIds : sourceTaskIds;
    board.columns[destColumnId].taskIds = destTaskIds;

    io.emit("board:update", board);
  });

  socket.on("task:create", ({ title, description, columnId }) => {
    const id = `task-${Date.now()}`;
    board.tasks[id] = { id, title, description };
    board.columns[columnId].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:update", ({ taskId, updates }) => {
    if (!board.tasks[taskId]) return;
    board.tasks[taskId] = {
      ...board.tasks[taskId],
      ...updates
    };
    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    delete board.tasks[taskId];
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );
    io.emit("board:update", board);
  });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

