import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task, onEdit, onDelete }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
      <div className="task-actions">
        <button onClick={() => onEdit(task)}>Edit</button>
        <button onClick={() => onDelete(task.id)}>Delete</button>
      </div>
    </div>
  );
}

function Column({ column, tasks, onEditTask, onDeleteTask }) {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onEdit={onEditTask}
              onDelete={onDeleteTask}
            />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTask, setNewTask] = useState({
    title: "",
    description: "",
    columnId: "todo"
  });

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    socket.on("board:init", setBoard);
    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:init", setBoard);
      socket.off("board:update", setBoard);
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);
      return { ...column, tasks };
    });
  }, [board]);

  function findColumnByTaskId(taskId) {
    for (const columnId of board.columnOrder) {
      if (board.columns[columnId].taskIds.includes(taskId)) {
        return columnId;
      }
    }
    return null;
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const taskId = active.id;
    const overId = over.id;

    const sourceColumnId = findColumnByTaskId(taskId);
    let destColumnId = findColumnByTaskId(overId);

    if (!destColumnId && board.columns[overId]) {
      destColumnId = overId;
    }

    if (!sourceColumnId || !destColumnId) return;

    const destTaskIds = board.columns[destColumnId].taskIds;
    const destIndex = destTaskIds.includes(overId)
      ? destTaskIds.indexOf(overId)
      : destTaskIds.length;

    socket.emit("board:moveTask", {
      taskId,
      sourceColumnId,
      destColumnId,
      destIndex
    });
  }

  function handleCreateTask(e) {
    e.preventDefault();
    if (!newTask.title.trim()) return;

    socket.emit("task:create", newTask);
    setNewTask({
      title: "",
      description: "",
      columnId: "todo"
    });
  }

  function handleEditTask(task) {
    const title = prompt("Edit title", task.title);
    const description = prompt("Edit description", task.description);
    if (title == null || description == null) return;

    socket.emit("task:update", {
      taskId: task.id,
      updates: { title, description }
    });
  }

  function handleDeleteTask(taskId) {
    const columnId = findColumnByTaskId(taskId);
    if (!columnId) return;
    socket.emit("task:delete", { taskId, columnId });
  }

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header>
        <h1>Project Management Board</h1>
      </header>

      <form className="task-form" onSubmit={handleCreateTask}>
        <input
          type="text"
          placeholder="Task title"
          value={newTask.title}
          onChange={(e) => setNewTask((prev) => ({ ...prev, title: e.target.value }))}
        />
        <input
          type="text"
          placeholder="Description"
          value={newTask.description}
          onChange={(e) => setNewTask((prev) => ({ ...prev, description: e.target.value }))}
        />
        <select
          value={newTask.columnId}
          onChange={(e) => setNewTask((prev) => ({ ...prev, columnId: e.target.value }))}
        >
          {board.columnOrder.map((columnId) => (
            <option key={columnId} value={columnId}>
              {board.columns[columnId].title}
            </option>
          ))}
        </select>
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={column.tasks}
              onEditTask={handleEditTask}
              onDeleteTask={handleDeleteTask}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

