## `server/index.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project repo", description: "Initialize frontend and backend" },
    "task-2": { id: "task-2", title: "Design board UI", description: "Create kanban layout" },
    "task-3": { id: "task-3", title: "Implement sockets", description: "Enable realtime sync" }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  const id = `task-${Date.now()}`;
  board.tasks[id] = { id, title, description };

  board.columns[columnId].taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(board.tasks[id]);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...board.tasks[id],
    title: title ?? board.tasks[id].title,
    description: description ?? board.tasks[id].description
  };

  io.emit("board:update", board);
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];

  for (const column of Object.values(board.columns)) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns[sourceColumnId];
    const destinationColumn = board.columns[destinationColumnId];

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

