import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import Board from "./components/Board";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then(res => res.json())
      .then(data => setBoard(data));

    socket.on("board:init", data => setBoard(data));
    socket.on("board:update", data => setBoard(data));

    return () => {
      socket.off("board:init");
      socket.off("board:update");
    };
  }, []);

  const createTask = async (e) => {
    e.preventDefault();

    if (!title.trim()) return;

    await fetch("http://localhost:4000/api/tasks", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        title,
        description,
        columnId: "todo"
      })
    });

    setTitle("");
    setDescription("");
  };

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="app-header">
        <h1>Project Management Board</h1>
      </header>

      <form className="task-form" onSubmit={createTask}>
        <input
          type="text"
          placeholder="Task title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Task description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <button type="submit">Add Task</button>
      </form>

      <Board board={board} socket={socket} />
    </div>
  );
}
