# 5. Drag-and-Drop Board Components

## `client/src/components/Board.jsx`

```jsx
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import Column from "./Column";

export default function Board({ board, socket }) {
  const sensors = useSensors(useSensor(PointerSensor));

  const findColumnByTaskId = (taskId) => {
    return Object.values(board.columns).find((column) =>
      column.taskIds.includes(taskId)
    );
  };

  const handleDragEnd = (event) => {
    const { active, over } = event;

    if (!over) return;

    const taskId = active.id;
    const overId = over.id;

    const sourceColumn = findColumnByTaskId(taskId);
    if (!sourceColumn) return;

    let destinationColumn = board.columns[overId];

    if (!destinationColumn) {
      destinationColumn = findColumnByTaskId(overId);
    }

    if (!destinationColumn) return;

    const sourceColumnId = sourceColumn.id;
    const destinationColumnId = destinationColumn.id;

    let destinationIndex = destinationColumn.taskIds.length;

    if (board.tasks[overId]) {
      destinationIndex = destinationColumn.taskIds.indexOf(overId);
    }

    socket.emit("task:move", {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    });
  };

  return (
    <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
      <div className="board">
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

          return <Column key={column.id} column={column} tasks={tasks} />;
        })}
      </div>
    </DndContext>
  );
}
```

