```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["todo", "inprogress", "done"],
  tasks: {}
};

app.get("/board", (req, res) => {
  res.json(board);
});

app.post("/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  const id = uuidv4();
  const task = {
    id,
    title,
    description,
    createdAt: Date.now()
  };

  board.tasks[id] = task;
  board.columns[columnId].taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/board", (req, res) => {
  const nextBoard = req.body;
  board = nextBoard;
  io.emit("board:update", board);
  res.json(board);
});

app.put("/tasks/:id", (req, res) => {
  const { id } = req.params;
  const existing = board.tasks[id];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[id] = {
    ...existing,
    ...req.body,
    id
  };

  io.emit("board:update", board);
  res.json(board.tasks[id]);
});

app.delete("/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[id];

  Object.values(board.columns).forEach((column) => {
    column.taskIds = column.taskIds.filter((taskId) => taskId !== id);
  });

  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("disconnect", () => {
    console.log("Client disconnected");
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
