## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    fetch(`${API_URL}/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => board.columns[columnId]);
  }, [board]);

  const createTask = async () => {
    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/tasks`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        title: newTaskTitle
      })
    });

    setNewTaskTitle("");
  };

  const findColumnByTaskId = (taskId) => {
    return columns.find((column) => column.taskIds.includes(taskId));
  };

  const handleDragEnd = async ({ active, over }) => {
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const sourceColumn = findColumnByTaskId(activeId);
    const targetColumn =
      board.columns[overId] ||
      findColumnByTaskId(overId);

    if (!sourceColumn || !targetColumn) return;

    const nextBoard = structuredClone(board);

    if (sourceColumn.id === targetColumn.id) {
      const ids = [...nextBoard.columns[sourceColumn.id].taskIds];
      const oldIndex = ids.indexOf(activeId);
      const newIndex = ids.indexOf(overId);

      if (oldIndex !== -1 && newIndex !== -1) {
        ids.splice(oldIndex, 1);
        ids.splice(newIndex, 0, activeId);
        nextBoard.columns[sourceColumn.id].taskIds = ids;
      }
    } else {
      nextBoard.columns[sourceColumn.id].taskIds =
        nextBoard.columns[sourceColumn.id].taskIds.filter((id) => id !== activeId);

      const targetIds = [...nextBoard.columns[targetColumn.id].taskIds];
      const insertIndex = board.columns[overId]
        ? targetIds.length
        : targetIds.indexOf(overId);

      if (insertIndex >= 0) {
        targetIds.splice(insertIndex, 0, activeId);
      } else {
        targetIds.push(activeId);
      }

      nextBoard.columns[targetColumn.id].taskIds = targetIds;
    }

    setBoard(nextBoard);

    await fetch(`${API_URL}/board`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(nextBoard)
    });
  };

  if (!board) return <div className="loading">Loading...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Board</h1>
        <div className="new-task">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={createTask}>Add Task</button>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={column.taskIds.map((taskId) => board.tasks[taskId])}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column" id={column.id}>
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map((task) => task.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h3>{task.title}</h3>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

export default App;
```

