# 2. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "in-progress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project repo",
      description: "Initialize repository and project structure"
    },
    "task-2": {
      id: "task-2",
      title: "Design task board UI",
      description: "Create initial Kanban layout"
    }
  }
};

function createTaskId() {
  return "task-" + Math.random().toString(36).slice(2, 9);
}

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const column = boardState.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(400).json({ error: "Invalid columnId" });
  }

  const id = createTaskId();
  const task = {
    id,
    title: title.trim(),
    description: description.trim()
  };

  boardState.tasks[id] = task;
  column.taskIds.push(id);

  io.emit("board:update", boardState);

  res.status(201).json(task);
});

app.put("/api/tasks/:id/move", (req, res) => {
  const { id } = req.params;
  const { sourceColumnId, targetColumnId, targetIndex } = req.body;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  const sourceColumn = boardState.columns.find(c => c.id === sourceColumnId);
  const targetColumn = boardState.columns.find(c => c.id === targetColumnId);

  if (!sourceColumn || !targetColumn) {
    return res.status(400).json({ error: "Invalid column ids" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(taskId => taskId !== id);

  const insertIndex =
    typeof targetIndex === "number" && targetIndex >= 0
      ? targetIndex
      : targetColumn.taskIds.length;

  targetColumn.taskIds.splice(insertIndex, 0, id);

  io.emit("board:update", boardState);

  res.json({ success: true, board: boardState });
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks[id];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description } = req.body;

  if (typeof title === "string") task.title = title.trim();
  if (typeof description === "string") task.description = description.trim();

  io.emit("board:update", boardState);

  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!boardState.tasks[id]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete boardState.tasks[id];
  boardState.columns.forEach(column => {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  });

  io.emit("board:update", boardState);

  res.json({ success: true });
});

io.on("connection", socket => {
  console.log("Client connected:", socket.id);
  socket.emit("board:update", boardState);

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

