# 5. `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("task-form");
const taskTitleInput = document.getElementById("task-title");
const taskDescriptionInput = document.getElementById("task-description");
const taskColumnInput = document.getElementById("task-column");

async function fetchBoard() {
  const res = await fetch("/api/board");
  boardState = await res.json();
  renderBoard();
}

function renderBoard() {
  if (!boardState) return;
  boardEl.innerHTML = "";

  boardState.columns.forEach(column => {
    const columnEl = document
      .getElementById("column-template")
      .content.firstElementChild
      .cloneNode(true);

    columnEl.dataset.columnId = column.id;
    columnEl.querySelector("h2").textContent = column.title;

    const taskListEl = columnEl.querySelector(".task-list");
    taskListEl.dataset.columnId = column.id;

    addColumnDnDHandlers(taskListEl, column.id);

    column.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document
        .getElementById("task-template")
        .content.firstElementChild
        .cloneNode(true);

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskEl.querySelector(".task-title").textContent = task.title;
      taskEl.querySelector(".task-description").textContent = task.description;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".edit-btn").addEventListener("click", async () => {
        const newTitle = prompt("Edit task title:", task.title);
        if (newTitle === null) return;

        const newDescription = prompt("Edit task description:", task.description);
        if (newDescription === null) return;

        await fetch(`/api/tasks/${task.id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            title: newTitle,
            description: newDescription
          })
        });
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", async () => {
        const confirmed = confirm(`Delete "${task.title}"?`);
        if (!confirmed) return;

        await fetch(`/api/tasks/${task.id}`, {
          method: "DELETE"
        });
      });

      taskListEl.appendChild(taskEl);
    });

    boardEl.appendChild(columnEl);
  });
}

function addColumnDnDHandlers(taskListEl, targetColumnId) {
  taskListEl.addEventListener("dragover", e => {
    e.preventDefault();
    taskListEl.classList.add("drag-over");
  });

  taskListEl.addEventListener("dragleave", () => {
    taskListEl.classList.remove("drag-over");
  });

  taskListEl.addEventListener("drop", async e => {
    e.preventDefault();
    taskListEl.classList.remove("drag-over");

    if (!draggedTaskId || !draggedFromColumnId) return;

    const targetIndex = getDropIndex(taskListEl, e.clientY);

    await fetch(`/api/tasks/${draggedTaskId}/move`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sourceColumnId: draggedFromColumnId,
        targetColumnId,
        targetIndex
      })
    });

    draggedTaskId = null;
    draggedFromColumnId = null;
  });
}

function getDropIndex(taskListEl, mouseY) {
  const taskElements = [
    ...taskListEl.querySelectorAll(".task:not(.dragging)")
  ];

  for (let i = 0; i < taskElements.length; i++) {
    const rect = taskElements[i].getBoundingClientRect();
    if (mouseY < rect.top + rect.height / 2) {
      return i;
    }
  }

  return taskElements.length;
}

taskForm.addEventListener("submit", async e => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnInput.value;

  if (!title) return;

  await fetch("/api/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, columnId })
  });

  taskForm.reset();
});

socket.on("board:update", newBoardState => {
  boardState = newBoardState;
  renderBoard();
});

fetchBoard();
```

