```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory project store
const projects = {
  "demo-project": {
    id: "demo-project",
    name: "Demo Project",
    columns: [
      { id: "col-todo", title: "To Do", taskIds: [] },
      { id: "col-inprogress", title: "In Progress", taskIds: [] },
      { id: "col-done", title: "Done", taskIds: [] }
    ],
    tasks: {}
  }
};

// Seed sample tasks
const task1 = { id: uuidv4(), title: "Set up project", description: "Initialize repo and tooling" };
const task2 = { id: uuidv4(), title: "Build board UI", description: "Create kanban layout" };
projects["demo-project"].tasks[task1.id] = task1;
projects["demo-project"].tasks[task2.id] = task2;
projects["demo-project"].columns[0].taskIds.push(task1.id, task2.id);

app.get("/projects/:projectId", (req, res) => {
  const project = projects[req.params.projectId];
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.json(project);
});

app.post("/projects", (req, res) => {
  const id = uuidv4();
  const project = {
    id,
    name: req.body.name || "Untitled Project",
    columns: [
      { id: uuidv4(), title: "To Do", taskIds: [] },
      { id: uuidv4(), title: "In Progress", taskIds: [] },
      { id: uuidv4(), title: "Done", taskIds: [] }
    ],
    tasks: {}
  };
  projects[id] = project;
  res.status(201).json(project);
});

function moveTask(project, taskId, sourceColumnId, targetColumnId, targetIndex) {
  const sourceColumn = project.columns.find(c => c.id === sourceColumnId);
  const targetColumn = project.columns.find(c => c.id === targetColumnId);

  if (!sourceColumn || !targetColumn) return false;

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const insertIndex = Math.max(0, Math.min(targetIndex, targetColumn.taskIds.length));
  targetColumn.taskIds.splice(insertIndex, 0, taskId);

  return true;
}

io.on("connection", (socket) => {
  socket.on("join_project", ({ projectId }) => {
    const project = projects[projectId];
    if (!project) {
      socket.emit("error_message", { message: "Project not found" });
      return;
    }
    socket.join(projectId);
    socket.emit("project_state", project);
  });

  socket.on("create_task", ({ projectId, columnId, title, description }) => {
    const project = projects[projectId];
    if (!project) return;

    const column = project.columns.find(c => c.id === columnId);
    if (!column) return;

    const task = {
      id: uuidv4(),
      title: title || "Untitled Task",
      description: description || ""
    };

    project.tasks[task.id] = task;
    column.taskIds.push(task.id);

    io.to(projectId).emit("task_created", {
      projectId,
      task,
      columnId
    });
  });

  socket.on("update_task", ({ projectId, taskId, updates }) => {
    const project = projects[projectId];
    if (!project || !project.tasks[taskId]) return;

    project.tasks[taskId] = {
      ...project.tasks[taskId],
      ...updates
    };

    io.to(projectId).emit("task_updated", {
      projectId,
      task: project.tasks[taskId]
    });
  });

  socket.on("move_task", ({ projectId, taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const project = projects[projectId];
    if (!project) return;

    const ok = moveTask(project, taskId, sourceColumnId, targetColumnId, targetIndex);
    if (!ok) return;

    io.to(projectId).emit("task_moved", {
      projectId,
      taskId,
      sourceColumnId,
      targetColumnId,
      targetIndex
    });
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```

