```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");
const PROJECT_ID = "demo-project";

function App() {
  const [project, setProject] = useState(null);
  const [newTaskTitles, setNewTaskTitles] = useState({});

  useEffect(() => {
    fetch(`http://localhost:4000/projects/${PROJECT_ID}`)
      .then(res => res.json())
      .then(data => setProject(data));

    socket.emit("join_project", { projectId: PROJECT_ID });

    socket.on("project_state", (data) => {
      setProject(data);
    });

    socket.on("task_created", ({ task, columnId }) => {
      setProject(prev => {
        if (!prev) return prev;
        return {
          ...prev,
          tasks: {
            ...prev.tasks,
            [task.id]: task
          },
          columns: prev.columns.map(col =>
            col.id === columnId
              ? { ...col, taskIds: [...col.taskIds, task.id] }
              : col
          )
        };
      });
    });

    socket.on("task_updated", ({ task }) => {
      setProject(prev => {
        if (!prev) return prev;
        return {
          ...prev,
          tasks: {
            ...prev.tasks,
            [task.id]: task
          }
        };
      });
    });

    socket.on("task_moved", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
      setProject(prev => {
        if (!prev) return prev;

        const columns = prev.columns.map(col => ({
          ...col,
          taskIds: [...col.taskIds]
        }));

        const source = columns.find(c => c.id === sourceColumnId);
        const target = columns.find(c => c.id === targetColumnId);

        if (!source || !target) return prev;

        source.taskIds = source.taskIds.filter(id => id !== taskId);
        target.taskIds.splice(targetIndex, 0, taskId);

        return { ...prev, columns };
      });
    });

    return () => {
      socket.off("project_state");
      socket.off("task_created");
      socket.off("task_updated");
      socket.off("task_moved");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columnTaskMap = useMemo(() => {
    if (!project) return {};
    const map = {};
    for (const col of project.columns) {
      map[col.id] = col.taskIds.map(taskId => project.tasks[taskId]).filter(Boolean);
    }
    return map;
  }, [project]);

  function handleAddTask(columnId) {
    const title = newTaskTitles[columnId]?.trim();
    if (!title) return;

    socket.emit("create_task", {
      projectId: PROJECT_ID,
      columnId,
      title,
      description: ""
    });

    setNewTaskTitles(prev => ({ ...prev, [columnId]: "" }));
  }

  function findColumnByTaskId(taskId) {
    return project.columns.find(col => col.taskIds.includes(taskId));
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !project) return;

    const taskId = active.id;
    const overId = over.id;

    const sourceColumn = findColumnByTaskId(taskId);
    if (!sourceColumn) return;

    let targetColumn = project.columns.find(col => col.id === overId);
    let targetIndex = 0;

    if (targetColumn) {
      targetIndex = targetColumn.taskIds.length;
    } else {
      targetColumn = findColumnByTaskId(overId);
      if (!targetColumn) return;
      targetIndex = targetColumn.taskIds.indexOf(overId);
    }

    socket.emit("move_task", {
      projectId: PROJECT_ID,
      taskId,
      sourceColumnId: sourceColumn.id,
      targetColumnId: targetColumn.id,
      targetIndex
    });
  }

  if (!project) {
    return <div className="app-shell">Loading project...</div>;
  }

  return (
    <div className="app-shell">
      <header className="app-header">
        <h1>{project.name}</h1>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {project.columns.map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={columnTaskMap[column.id] || []}
              newTaskTitle={newTaskTitles[column.id] || ""}
              onNewTaskTitleChange={(value) =>
                setNewTaskTitles(prev => ({ ...prev, [column.id]: value }))
              }
              onAddTask={() => handleAddTask(column.id)}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({ column, tasks, newTaskTitle, onNewTaskTitleChange, onAddTask }) {
  return (
    <div className="column" id={column.id}>
      <h2>{column.title}</h2>

      <div className="new-task">
        <input
          value={newTaskTitle}
          onChange={(e) => onNewTaskTitleChange(e.target.value)}
          placeholder="New task title"
        />
        <button onClick={onAddTask}>Add</button>
      </div>

      <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <div className="task-title">{task.title}</div>
      <div className="task-desc">{task.description}</div>
    </div>
  );
}

export default App;
```

