import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board data
let board = {
  id: "board-1",
  title: "Team Project Board",
  columns: [
    {
      id: "col-1",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "col-2",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "col-3",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project repo",
      description: "Initialize GitHub repository and README"
    },
    "task-2": {
      id: "task-2",
      title: "Design board layout",
      description: "Create initial UI wireframes"
    },
    "task-3": {
      id: "task-3",
      title: "Implement backend",
      description: "Set up Express and Socket.IO"
    }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, title, description } = req.body;
  const id = uuidv4();

  const task = { id, title, description };
  board.tasks[id] = task;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  board.tasks[taskId] = {
    ...board.tasks[taskId],
    title,
    description
  };

  io.emit("board:update", board);
  res.json(board.tasks[taskId]);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!board.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete board.tasks[taskId];
  board.columns = board.columns.map((column) => ({
    ...column,
    taskIds: column.taskIds.filter((id) => id !== taskId)
  }));

  io.emit("board:update", board);
  res.status(204).send();
});

app.put("/api/board/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);
  socket.emit("board:update", board);

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
