import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const API_URL = "http://localhost:4000/api";
const socket = io("http://localhost:4000");

function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    fetch(`${API_URL}/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const handleAddTask = async (columnId) => {
    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/tasks`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        columnId,
        title: newTaskTitle,
        description: newTaskDescription
      })
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  const findColumnByTaskId = (taskId) => {
    return board.columns.find((col) => col.taskIds.includes(taskId));
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over || !board) return;
    if (active.id === over.id) return;

    const sourceColumn = findColumnByTaskId(active.id);
    const destinationColumn =
      board.columns.find((col) => col.id === over.id) || findColumnByTaskId(over.id);

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(active.id);
    let destinationIndex = destinationColumn.taskIds.indexOf(over.id);

    if (destinationIndex === -1) {
      destinationIndex = destinationColumn.taskIds.length;
    }

    const updatedBoard = structuredClone(board);

    const source = updatedBoard.columns.find((c) => c.id === sourceColumn.id);
    const dest = updatedBoard.columns.find((c) => c.id === destinationColumn.id);

    if (source.id === dest.id) {
      dest.taskIds = arrayMove(dest.taskIds, sourceIndex, destinationIndex);
      setBoard(updatedBoard);

      await fetch(`${API_URL}/board/move-task`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: active.id,
          sourceColumnId: source.id,
          destinationColumnId: dest.id,
          destinationIndex
        })
      });
    } else {
      source.taskIds = source.taskIds.filter((id) => id !== active.id);
      dest.taskIds.splice(destinationIndex, 0, active.id);
      setBoard(updatedBoard);

      await fetch(`${API_URL}/board/move-task`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: active.id,
          sourceColumnId: source.id,
          destinationColumnId: dest.id,
          destinationIndex
        })
      });
    }
  };

  if (!board) return <div className="loading">Loading...</div>;

  return (
    <div className="app">
      <h1>{board.title}</h1>
      <div className="board">
        {board.columns.map((column) => (
          <Column
            key={column.id}
            column={column}
            tasks={column.taskIds.map((taskId) => board.tasks[taskId])}
            onAddTask={handleAddTask}
            newTaskTitle={newTaskTitle}
            setNewTaskTitle={setNewTaskTitle}
            newTaskDescription={newTaskDescription}
            setNewTaskDescription={setNewTaskDescription}
          />
        ))}
      </div>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div style={{ display: "none" }} />
      </DndContext>
    </div>
  );
}

function Column({
  column,
  tasks,
  onAddTask,
  newTaskTitle,
  setNewTaskTitle,
  newTaskDescription,
  setNewTaskDescription
}) {
  return (
    <div className="column">
      <h2>{column.title}</h2>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" id={column.id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>

      <div className="task-form">
        <input
          placeholder="Task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
        />
        <textarea
          placeholder="Task description"
          value={newTaskDescription}
          onChange={(e) => setNewTaskDescription(e.target.value)}
        />
        <button onClick={() => onAddTask(column.id)}>Add Task</button>
      </div>
    </div>
  );
}

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h3>{task.title}</h3>
      <p>{task.description}</p>
    </div>
  );
}

export default App;
```

