## 2. Backend: `server/server.js`

```js
import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";
import http from "http";
import crypto from "crypto";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const PORT = 4000;

// In-memory state
const state = {
  project: {
    id: "project-1",
    name: "Demo Project",
    columns: [
      { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
      { id: "in-progress", title: "In Progress", taskIds: ["task-3"] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {
      "task-1": {
        id: "task-1",
        title: "Set up project repo",
        description: "Initialize repository and README",
        assignee: "Alex",
        priority: "High"
      },
      "task-2": {
        id: "task-2",
        title: "Design board layout",
        description: "Create initial kanban UI",
        assignee: "Sam",
        priority: "Medium"
      },
      "task-3": {
        id: "task-3",
        title: "Implement WebSocket sync",
        description: "Broadcast board updates to all clients",
        assignee: "Jordan",
        priority: "High"
      }
    }
  }
};

function broadcast(wss, message) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client.readyState === 1) {
      client.send(data);
    }
  }
}

function getProject() {
  return state.project;
}

app.get("/api/project", (req, res) => {
  res.json(getProject());
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "", priority = "Low", columnId = "todo" } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const taskId = crypto.randomUUID();
  const task = {
    id: taskId,
    title,
    description,
    assignee,
    priority
  };

  state.project.tasks[taskId] = task;

  const column = state.project.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(taskId);

  const payload = { type: "TASK_CREATED", project: getProject() };
  broadcast(wss, payload);

  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const existing = state.project.tasks[taskId];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updated = {
    ...existing,
    ...req.body,
    id: taskId
  };

  state.project.tasks[taskId] = updated;

  const payload = { type: "TASK_UPDATED", project: getProject() };
  broadcast(wss, payload);

  res.json(updated);
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  if (!state.project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete state.project.tasks[taskId];

  for (const column of state.project.columns) {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  }

  const payload = { type: "TASK_DELETED", project: getProject() };
  broadcast(wss, payload);

  res.json({ success: true });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = state.project.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = state.project.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
  if (sourceIndex === -1) {
    return res.status(404).json({ error: "Task not found in source column" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  const payload = { type: "TASK_MOVED", project: getProject() };
  broadcast(wss, payload);

  res.json({ success: true, project: getProject() });
});

const wss = new WebSocketServer({ server });

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "INIT", project: getProject() }));

  ws.on("message", raw => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === "PING") {
        ws.send(JSON.stringify({ type: "PONG" }));
      }
    } catch (err) {
      console.error("Invalid WS message", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

