## 5. Frontend: `client/app.js`

```js
const API_BASE = "http://localhost:4000/api";
const WS_URL = "ws://localhost:4000";

let project = null;
let editingTaskId = null;

const boardEl = document.getElementById("board");
const projectNameEl = document.getElementById("project-name");
const dialogEl = document.getElementById("task-dialog");
const formEl = document.getElementById("task-form");
const openCreateTaskBtn = document.getElementById("open-create-task");
const cancelTaskBtn = document.getElementById("cancel-task");
const taskColumnEl = document.getElementById("task-column");
const taskTitleEl = document.getElementById("task-title");
const taskDescriptionEl = document.getElementById("task-description");
const taskAssigneeEl = document.getElementById("task-assignee");
const taskPriorityEl = document.getElementById("task-priority");

async function fetchProject() {
  const res = await fetch(`${API_BASE}/project`);
  project = await res.json();
  render();
}

function connectWebSocket() {
  const ws = new WebSocket(WS_URL);

  ws.onopen = () => {
    console.log("WebSocket connected");
  };

  ws.onmessage = event => {
    const message = JSON.parse(event.data);

    if (message.project) {
      project = message.project;
      render();
    }
  };

  ws.onclose = () => {
    console.log("WebSocket disconnected. Reconnecting...");
    setTimeout(connectWebSocket, 1000);
  };
}

function render() {
  if (!project) return;

  projectNameEl.textContent = project.name;
  boardEl.innerHTML = "";

  taskColumnEl.innerHTML = project.columns
    .map(col => `<option value="${col.id}">${col.title}</option>`)
    .join("");

  for (const column of project.columns) {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <div class="column-header">
        <div class="column-title">${column.title}</div>
        <div>${column.taskIds.length}</div>
      </div>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
    });

    taskListEl.addEventListener("drop", async e => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData("text/task-id");
      const sourceColumnId = e.dataTransfer.getData("text/source-column-id");
      const destinationColumnId = column.id;
      const destinationIndex = project.columns
        .find(c => c.id === destinationColumnId)
        .taskIds.length;

      await fetch(`${API_BASE}/move-task`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId,
          sourceColumnId,
          destinationColumnId,
          destinationIndex
        })
      });
    });

    for (const taskId of column.taskIds) {
      const task = project.tasks[taskId];
      if (!task) continue;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div class="task-meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
        <div class="task-meta">Priority: ${escapeHtml(task.priority)}</div>
        <div class="task-description">${escapeHtml(task.description || "")}</div>
        <div class="task-actions">
          <button class="edit-btn" data-task-id="${task.id}">Edit</button>
          <button class="delete-btn" data-task-id="${task.id}">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", e => {
        taskEl.classList.add("dragging");
        e.dataTransfer.setData("text/task-id", task.id);
        e.dataTransfer.setData("text/source-column-id", column.id);
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".edit-btn").addEventListener("click", () => {
        openEditDialog(task, column.id);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", async () => {
        await fetch(`${API_BASE}/tasks/${task.id}`, { method: "DELETE" });
      });

      taskListEl.appendChild(taskEl);
    }

    boardEl.appendChild(columnEl);
  }
}

function openCreateDialog() {
  editingTaskId = null;
  formEl.reset();
  taskPriorityEl.value = "Low";
  if (project?.columns?.[0]) {
    taskColumnEl.value = project.columns[0].id;
  }
  formEl.querySelector("h2").textContent = "Create Task";
  formEl.querySelector('button[type="submit"]').textContent = "Create";
  dialogEl.showModal();
}

function openEditDialog(task, columnId) {
  editingTaskId = task.id;
  taskTitleEl.value = task.title;
  taskDescriptionEl.value = task.description || "";
  taskAssigneeEl.value = task.assignee || "";
  taskPriorityEl.value = task.priority || "Low";
  taskColumnEl.value = columnId;
  formEl.querySelector("h2").textContent = "Edit Task";
  formEl.querySelector('button[type="submit"]').textContent = "Save";
  dialogEl.showModal();
}

formEl.addEventListener("submit", async e => {
  e.preventDefault();

  const payload = {
    title: taskTitleEl.value.trim(),
    description: taskDescriptionEl.value.trim(),
    assignee: taskAssigneeEl.value.trim(),
    priority: taskPriorityEl.value,
    columnId: taskColumnEl.value
  };

  if (!payload.title) return;

  if (editingTaskId) {
    await fetch(`${API_BASE}/tasks/${editingTaskId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  } else {
    await fetch(`${API_BASE}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
  }

  dialogEl.close();
});

openCreateTaskBtn.addEventListener("click", openCreateDialog);
cancelTaskBtn.addEventListener("click", () => dialogEl.close());

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

fetchProject();
connectWebSocket();
