import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory store
const db = {
  projects: [
    {
      id: "project-1",
      name: "Demo Project",
      columns: [
        { id: "col-1", title: "Todo" },
        { id: "col-2", title: "In Progress" },
        { id: "col-3", title: "Done" }
      ],
      tasks: [
        {
          id: "task-1",
          title: "Set up project",
          description: "Initialize frontend and backend",
          columnId: "col-1"
        },
        {
          id: "task-2",
          title: "Build drag and drop",
          description: "Implement board interactions",
          columnId: "col-2"
        }
      ]
    }
  ]
};

// REST API
app.get("/projects", (req, res) => {
  res.json(db.projects);
});

app.get("/projects/:projectId", (req, res) => {
  const project = db.projects.find(p => p.id === req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });
  res.json(project);
});

app.post("/projects", (req, res) => {
  const project = {
    id: uuidv4(),
    name: req.body.name || "Untitled Project",
    columns: [
      { id: uuidv4(), title: "Todo" },
      { id: uuidv4(), title: "In Progress" },
      { id: uuidv4(), title: "Done" }
    ],
    tasks: []
  };
  db.projects.push(project);
  io.emit("project:created", project);
  res.status(201).json(project);
});

app.post("/projects/:projectId/tasks", (req, res) => {
  const project = db.projects.find(p => p.id === req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const task = {
    id: uuidv4(),
    title: req.body.title || "Untitled Task",
    description: req.body.description || "",
    columnId: req.body.columnId || project.columns[0].id
  };

  project.tasks.push(task);
  io.to(project.id).emit("task:created", { projectId: project.id, task });
  res.status(201).json(task);
});

app.put("/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = db.projects.find(p => p.id === req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const task = project.tasks.find(t => t.id === req.params.taskId);
  if (!task) return res.status(404).json({ error: "Task not found" });

  task.title = req.body.title ?? task.title;
  task.description = req.body.description ?? task.description;
  task.columnId = req.body.columnId ?? task.columnId;

  io.to(project.id).emit("task:updated", { projectId: project.id, task });
  res.json(task);
});

app.delete("/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = db.projects.find(p => p.id === req.params.projectId);
  if (!project) return res.status(404).json({ error: "Project not found" });

  const index = project.tasks.findIndex(t => t.id === req.params.taskId);
  if (index === -1) return res.status(404).json({ error: "Task not found" });

  const [deleted] = project.tasks.splice(index, 1);
  io.to(project.id).emit("task:deleted", {
    projectId: project.id,
    taskId: deleted.id
  });

  res.json({ success: true });
});

// Socket.IO
io.on("connection", socket => {
  console.log("Client connected:", socket.id);

  socket.on("project:join", projectId => {
    socket.join(projectId);
  });

  socket.on("task:move", ({ projectId, taskId, toColumnId }) => {
    const project = db.projects.find(p => p.id === projectId);
    if (!project) return;

    const task = project.tasks.find(t => t.id === taskId);
    if (!task) return;

    task.columnId = toColumnId;

    io.to(projectId).emit("task:moved", {
      projectId,
      taskId,
      toColumnId
    });
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

