```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter
} from "@dnd-kit/core";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function App() {
  const [projects, setProjects] = useState([]);
  const [activeProjectId, setActiveProjectId] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  const activeProject = useMemo(
    () => projects.find(p => p.id === activeProjectId) || null,
    [projects, activeProjectId]
  );

  useEffect(() => {
    fetch(`${API_URL}/projects`)
      .then(res => res.json())
      .then(data => {
        setProjects(data);
        if (data.length > 0) {
          setActiveProjectId(data[0].id);
          socket.emit("project:join", data[0].id);
        }
      });
  }, []);

  useEffect(() => {
    socket.on("project:created", project => {
      setProjects(prev => [...prev, project]);
    });

    socket.on("task:created", ({ projectId, task }) => {
      setProjects(prev =>
        prev.map(project =>
          project.id === projectId
            ? { ...project, tasks: [...project.tasks, task] }
            : project
        )
      );
    });

    socket.on("task:updated", ({ projectId, task }) => {
      setProjects(prev =>
        prev.map(project =>
          project.id === projectId
            ? {
                ...project,
                tasks: project.tasks.map(t => (t.id === task.id ? task : t))
              }
            : project
        )
      );
    });

    socket.on("task:deleted", ({ projectId, taskId }) => {
      setProjects(prev =>
        prev.map(project =>
          project.id === projectId
            ? {
                ...project,
                tasks: project.tasks.filter(t => t.id !== taskId)
              }
            : project
        )
      );
    });

    socket.on("task:moved", ({ projectId, taskId, toColumnId }) => {
      setProjects(prev =>
        prev.map(project =>
          project.id === projectId
            ? {
                ...project,
                tasks: project.tasks.map(task =>
                  task.id === taskId ? { ...task, columnId: toColumnId } : task
                )
              }
            : project
        )
      );
    });

    return () => {
      socket.off("project:created");
      socket.off("task:created");
      socket.off("task:updated");
      socket.off("task:deleted");
      socket.off("task:moved");
    };
  }, []);

  const createTask = async () => {
    if (!activeProject || !newTaskTitle.trim()) return;

    await fetch(`${API_URL}/projects/${activeProject.id}/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTaskTitle,
        columnId: activeProject.columns[0].id
      })
    });

    setNewTaskTitle("");
  };

  const handleDragEnd = event => {
    const { active, over } = event;
    if (!over || !activeProject) return;

    const taskId = active.id;
    const toColumnId = over.id;

    socket.emit("task:move", {
      projectId: activeProject.id,
      taskId,
      toColumnId
    });
  };

  return (
    <div className="app">
      <aside className="sidebar">
        <h2>Projects</h2>
        {projects.map(project => (
          <button
            key={project.id}
            className={project.id === activeProjectId ? "active" : ""}
            onClick={() => {
              setActiveProjectId(project.id);
              socket.emit("project:join", project.id);
            }}
          >
            {project.name}
          </button>
        ))}
      </aside>

      <main className="board-page">
        <header className="board-header">
          <h1>{activeProject?.name || "Loading..."}</h1>
          <div className="task-creator">
            <input
              value={newTaskTitle}
              onChange={e => setNewTaskTitle(e.target.value)}
              placeholder="New task title"
            />
            <button onClick={createTask}>Add Task</button>
          </div>
        </header>

        {activeProject && (
          <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
            <div className="board">
              {activeProject.columns.map(column => (
                <Column
                  key={column.id}
                  column={column}
                  tasks={activeProject.tasks.filter(t => t.columnId === column.id)}
                />
              ))}
            </div>
          </DndContext>
        )}
      </main>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column" id={column.id}>
      <h3>{column.title}</h3>
      <div className="task-list">
        {tasks.map(task => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>
    </div>
  );
}

function TaskCard({ task }) {
  return (
    <div className="task-card" data-task-id={task.id}>
      <strong>{task.title}</strong>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

export default App;
```

