# 6. Important note: drag-and-drop improvement

The code above gives the initial structure, but `@dnd-kit` requires proper `useDroppable` and `useDraggable` or sortable hooks. Here is the improved version for the draggable/droppable pieces.

Replace `Column` and `TaskCard` with this:

```jsx
import { useDraggable, useDroppable } from "@dnd-kit/core";

function Column({ column, tasks }) {
  const { setNodeRef, isOver } = useDroppable({
    id: column.id
  });

  return (
    <div
      ref={setNodeRef}
      className="column"
      style={{ background: isOver ? "#e9f5ff" : "#f4f5f7" }}
    >
      <h3>{column.title}</h3>
      <div className="task-list">
        {tasks.map(task => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>
    </div>
  );
}

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform } = useDraggable({
    id: task.id
  });

  const style = transform
    ? {
        transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`
      }
    : undefined;

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="task-card"
      {...listeners}
      {...attributes}
    >
      <strong>{task.title}</strong>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}
```

And update the imports at the top of `App.jsx`:

```jsx
import {
  DndContext,
  closestCenter,
  useDraggable,
  useDroppable
} from "@dnd-kit/core";
```

