```js
import express from 'express';
import http from 'http';
import cors from 'cors';
import { Server } from 'socket.io';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: '*'
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: []
    },
    inprogress: {
      id: 'inprogress',
      title: 'In Progress',
      taskIds: []
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  columnOrder: ['todo', 'inprogress', 'done'],
  tasks: {}
};

// Seed sample tasks
function seedBoard() {
  const t1 = { id: uuidv4(), title: 'Set up project repo', description: 'Initialize frontend and backend' };
  const t2 = { id: uuidv4(), title: 'Design board UI', description: 'Create kanban layout' };
  const t3 = { id: uuidv4(), title: 'Implement sockets', description: 'Real-time sync between users' };

  board.tasks[t1.id] = t1;
  board.tasks[t2.id] = t2;
  board.tasks[t3.id] = t3;

  board.columns.todo.taskIds.push(t1.id, t2.id);
  board.columns.inprogress.taskIds.push(t3.id);
}

seedBoard();

app.get('/api/board', (req, res) => {
  res.json(board);
});

app.post('/api/tasks', (req, res) => {
  const { title, description = '', columnId = 'todo' } = req.body;

  if (!title) {
    return res.status(400).json({ error: 'Title is required' });
  }

  const task = {
    id: uuidv4(),
    title,
    description
  };

  board.tasks[task.id] = task;
  board.columns[columnId].taskIds.push(task.id);

  io.emit('board:update', board);
  res.status(201).json(task);
});

app.put('/api/board/move', (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  if (!board.columns[sourceColumnId] || !board.columns[destinationColumnId]) {
    return res.status(400).json({ error: 'Invalid column' });
  }

  const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
  sourceTaskIds.splice(sourceIndex, 1);

  if (sourceColumnId === destinationColumnId) {
    sourceTaskIds.splice(destinationIndex, 0, taskId);
    board.columns[sourceColumnId].taskIds = sourceTaskIds;
  } else {
    const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
    destinationTaskIds.splice(destinationIndex, 0, taskId);

    board.columns[sourceColumnId].taskIds = sourceTaskIds;
    board.columns[destinationColumnId].taskIds = destinationTaskIds;
  }

  io.emit('board:update', board);
  res.json(board);
});

io.on('connection', (socket) => {
  console.log(`Client connected: ${socket.id}`);
  socket.emit('board:init', board);

  socket.on('task:create', ({ title, description, columnId }) => {
    const task = {
      id: uuidv4(),
      title,
      description: description || ''
    };

    board.tasks[task.id] = task;
    board.columns[columnId || 'todo'].taskIds.push(task.id);

    io.emit('board:update', board);
  });

  socket.on('task:move', ({ taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex }) => {
    if (!board.columns[sourceColumnId] || !board.columns[destinationColumnId]) return;

    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    sourceTaskIds.splice(sourceIndex, 1);

    if (sourceColumnId === destinationColumnId) {
      sourceTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
    } else {
      const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
      destinationTaskIds.splice(destinationIndex, 0, taskId);

      board.columns[sourceColumnId].taskIds = sourceTaskIds;
      board.columns[destinationColumnId].taskIds = destinationTaskIds;
    }

    io.emit('board:update', board);
  });

  socket.on('disconnect', () => {
    console.log(`Client disconnected: ${socket.id}`);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
