```jsx
import React, { useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

const socket = io('http://localhost:4000');

function TaskCard({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    socket.on('board:init', (initialBoard) => {
      setBoard(initialBoard);
    });

    socket.on('board:update', (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off('board:init');
      socket.off('board:update');
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);
      return { ...column, tasks };
    });
  }, [board]);

  function findColumnByTaskId(taskId) {
    if (!board) return null;
    return Object.values(board.columns).find((column) => column.taskIds.includes(taskId));
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;
    if (active.id === over.id) return;

    const sourceColumn = findColumnByTaskId(active.id);
    const destinationColumn = findColumnByTaskId(over.id) || board.columns[over.id];

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(active.id);
    let destinationIndex = destinationColumn.taskIds.indexOf(over.id);

    if (destinationIndex === -1) {
      destinationIndex = destinationColumn.taskIds.length;
    }

    socket.emit('task:move', {
      taskId: active.id,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      sourceIndex,
      destinationIndex
    });
  }

  function createTask(e) {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit('task:create', {
      title: newTaskTitle,
      description: newTaskDescription,
      columnId: 'todo'
    });

    setNewTaskTitle('');
    setNewTaskDescription('');
  }

  if (!board) {
    return <div className="loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header>
        <h1>Project Management Board</h1>
      </header>

      <form className="task-form" onSubmit={createTask}>
        <input
          type="text"
          placeholder="Task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Task description"
          value={newTaskDescription}
          onChange={(e) => setNewTaskDescription(e.target.value)}
        />
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <div key={column.id} id={column.id}>
              <Column column={column} tasks={column.tasks} />
            </div>
          ))}
        </div>
      </DndContext>
    </div>
  );
}
