import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let board = {
  id: "board-1",
  name: "Team Project Board",
  columns: [
    {
      id: "col-1",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "col-2",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "col-3",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up repository",
      description: "Initialize GitHub repo and branch rules"
    },
    "task-2": {
      id: "task-2",
      title: "Create wireframes",
      description: "Draft UI wireframes for dashboard"
    },
    "task-3": {
      id: "task-3",
      title: "Build auth page",
      description: "Implement login screen UI"
    }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, title, description } = req.body;

  if (!columnId || !title) {
    return res.status(400).json({ error: "columnId and title are required" });
  }

  const taskId = uuidv4();
  const newTask = {
    id: taskId,
    title,
    description: description || ""
  };

  board.tasks[taskId] = newTask;

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(taskId);

  io.emit("board:update", board);

  res.status(201).json(newTask);
});

app.put("/api/board/reorder", (req, res) => {
  const { columns } = req.body;

  if (!columns) {
    return res.status(400).json({ error: "columns are required" });
  }

  board.columns = columns;
  io.emit("board:update", board);

  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("board:update", (updatedBoard) => {
    board = updatedBoard;
    socket.broadcast.emit("board:update", board);
  });

  socket.on("task:create", ({ columnId, title, description }) => {
    const taskId = uuidv4();
    const newTask = {
      id: taskId,
      title,
      description: description || ""
    };

    board.tasks[taskId] = newTask;
    const column = board.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.push(taskId);
      io.emit("board:update", board);
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

