```jsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  arrayMove,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, transition } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks, onAddTask }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>

      <TaskComposer columnId={column.id} onAddTask={onAddTask} />
    </div>
  );
}

function TaskComposer({ columnId, onAddTask }) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  const submit = (e) => {
    e.preventDefault();
    if (!title.trim()) return;
    onAddTask(columnId, title.trim(), description.trim());
    setTitle("");
    setDescription("");
  };

  return (
    <form className="task-composer" onSubmit={submit}>
      <input
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        placeholder="Task title"
      />
      <textarea
        value={description}
        onChange={(e) => setDescription(e.target.value)}
        placeholder="Description"
      />
      <button type="submit">Add Task</button>
    </form>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:init", setBoard);
    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:init", setBoard);
      socket.off("board:update", setBoard);
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const taskColumnMap = useMemo(() => {
    if (!board) return {};
    const map = {};
    for (const column of board.columns) {
      for (const taskId of column.taskIds) {
        map[taskId] = column.id;
      }
    }
    return map;
  }, [board]);

  const findColumnByTaskId = (taskId) => taskColumnMap[taskId];

  const handleDragEnd = ({ active, over }) => {
    if (!over || !board) return;

    const activeTaskId = active.id;
    const overTaskId = over.id;

    const sourceColumnId = findColumnByTaskId(activeTaskId);
    const targetColumnId = findColumnByTaskId(overTaskId);

    if (!sourceColumnId || !targetColumnId) return;

    const nextBoard = structuredClone(board);
    const sourceColumn = nextBoard.columns.find((c) => c.id === sourceColumnId);
    const targetColumn = nextBoard.columns.find((c) => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(activeTaskId);
    const targetIndex = targetColumn.taskIds.indexOf(overTaskId);

    if (sourceColumnId === targetColumnId) {
      sourceColumn.taskIds = arrayMove(sourceColumn.taskIds, sourceIndex, targetIndex);
    } else {
      sourceColumn.taskIds.splice(sourceIndex, 1);
      targetColumn.taskIds.splice(targetIndex, 0, activeTaskId);
    }

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  };

  const handleAddTask = (columnId, title, description) => {
    socket.emit("task:create", { columnId, title, description });
  };

  if (!board) {
    return <div className="app-loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>{board.name}</h1>
        <span className="status">Realtime Connected</span>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {board.columns.map((column) => {
            const tasks = column.taskIds
              .map((taskId) => board.tasks[taskId])
              .filter(Boolean);

            return (
              <Column
                key={column.id}
                column={column}
                tasks={tasks}
                onAddTask={handleAddTask}
              />
            );
          })}
        </div>
      </DndContext>
    </div>
  );
}
```

