## `server/server.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

/**
 * In-memory store for initial implementation.
 * Replace with a database later.
 */
const state = {
  projects: [
    {
      id: "project-1",
      name: "Website Redesign",
      columns: [
        {
          id: "col-1",
          title: "Backlog",
          taskIds: ["task-1", "task-2"]
        },
        {
          id: "col-2",
          title: "In Progress",
          taskIds: ["task-3"]
        },
        {
          id: "col-3",
          title: "Done",
          taskIds: []
        }
      ],
      tasks: {
        "task-1": {
          id: "task-1",
          title: "Create wireframes",
          description: "Design homepage and dashboard wireframes"
        },
        "task-2": {
          id: "task-2",
          title: "Collect stakeholder feedback",
          description: "Review requirements with product team"
        },
        "task-3": {
          id: "task-3",
          title: "Build landing page",
          description: "Implement responsive hero section"
        }
      }
    }
  ]
};

function getProject(projectId) {
  return state.projects.find((p) => p.id === projectId);
}

app.get("/api/projects", (req, res) => {
  res.json(state.projects);
});

app.get("/api/projects/:projectId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.json(project);
});

app.post("/api/projects/:projectId/tasks", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const { columnId, title, description } = req.body;
  const column = project.columns.find((c) => c.id === columnId);

  if (!column) {
    return res.status(400).json({ error: "Column not found" });
  }

  const id = uuidv4();
  const task = {
    id,
    title: title || "Untitled Task",
    description: description || ""
  };

  project.tasks[id] = task;
  column.taskIds.push(id);

  io.to(project.id).emit("project:update", project);

  res.status(201).json(task);
});

app.put("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const task = project.tasks[req.params.taskId];
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description } = req.body;
  if (typeof title === "string") task.title = title;
  if (typeof description === "string") task.description = description;

  io.to(project.id).emit("project:update", project);

  res.json(task);
});

app.delete("/api/projects/:projectId/tasks/:taskId", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const taskId = req.params.taskId;
  if (!project.tasks[taskId]) {
    return res.status(404).json({ error: "Task not found" });
  }

  delete project.tasks[taskId];
  project.columns.forEach((column) => {
    column.taskIds = column.taskIds.filter((id) => id !== taskId);
  });

  io.to(project.id).emit("project:update", project);

  res.status(204).send();
});

app.post("/api/projects/:projectId/reorder", (req, res) => {
  const project = getProject(req.params.projectId);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }

  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column id" });
  }

  if (
    sourceIndex < 0 ||
    sourceIndex >= sourceColumn.taskIds.length ||
    destinationIndex < 0 ||
    destinationIndex > destinationColumn.taskIds.length
  ) {
    return res.status(400).json({ error: "Invalid index" });
  }

  const [movedTaskId] = sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, movedTaskId);

  io.to(project.id).emit("project:update", project);

  res.json(project);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("project:join", (projectId) => {
    socket.join(projectId);
    const project = getProject(projectId);
    if (project) {
      socket.emit("project:update", project);
    }
  });

  socket.on("task:create", ({ projectId, columnId, title, description }) => {
    const project = getProject(projectId);
    if (!project) return;

    const column = project.columns.find((c) => c.id === columnId);
    if (!column) return;

    const id = uuidv4();
    const task = {
      id,
      title: title || "Untitled Task",
      description: description || ""
    };

    project.tasks[id] = task;
    column.taskIds.push(id);

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:update", ({ projectId, taskId, title, description }) => {
    const project = getProject(projectId);
    if (!project) return;

    const task = project.tasks[taskId];
    if (!task) return;

    if (typeof title === "string") task.title = title;
    if (typeof description === "string") task.description = description;

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:delete", ({ projectId, taskId }) => {
    const project = getProject(projectId);
    if (!project || !project.tasks[taskId]) return;

    delete project.tasks[taskId];
    project.columns.forEach((column) => {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    });

    io.to(projectId).emit("project:update", project);
  });

  socket.on("task:move", ({ projectId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex }) => {
    const project = getProject(projectId);
    if (!project) return;

    const sourceColumn = project.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = project.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;
    if (sourceIndex < 0 || sourceIndex >= sourceColumn.taskIds.length) return;
    if (destinationIndex < 0 || destinationIndex > destinationColumn.taskIds.length) return;

    const [movedTaskId] = sourceColumn.taskIds.splice(sourceIndex, 1);
    destinationColumn.taskIds.splice(destinationIndex, 0, movedTaskId);

    io.to(projectId).emit("project:update", project);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

