## `client/app.js`

```js
const API_BASE = "http://localhost:4000/api";
const socket = io("http://localhost:4000");

const projectId = "project-1";
let project = null;
let draggedTaskId = null;
let draggedFromColumnId = null;
let editingTaskId = null;

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");

const taskModal = document.getElementById("taskModal");
const taskForm = document.getElementById("taskForm");
const taskColumn = document.getElementById("taskColumn");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const cancelModalBtn = document.getElementById("cancelModalBtn");

const editModal = document.getElementById("editModal");
const editTaskForm = document.getElementById("editTaskForm");
const editTaskTitle = document.getElementById("editTaskTitle");
const editTaskDescription = document.getElementById("editTaskDescription");
const cancelEditModalBtn = document.getElementById("cancelEditModalBtn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");

async function fetchProject() {
  const res = await fetch(`${API_BASE}/projects/${projectId}`);
  project = await res.json();
  renderBoard();
}

function openTaskModal() {
  taskColumn.innerHTML = "";
  project.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumn.appendChild(option);
  });

  taskTitle.value = "";
  taskDescription.value = "";
  taskModal.classList.remove("hidden");
}

function closeTaskModal() {
  taskModal.classList.add("hidden");
}

function openEditModal(taskId) {
  editingTaskId = taskId;
  const task = project.tasks[taskId];
  if (!task) return;

  editTaskTitle.value = task.title;
  editTaskDescription.value = task.description || "";
  editModal.classList.remove("hidden");
}

function closeEditModal() {
  editingTaskId = null;
  editModal.classList.add("hidden");
}

function renderBoard() {
  if (!project) return;
  boardEl.innerHTML = "";

  project.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h3");
    titleEl.textContent = column.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const sourceColumn = project.columns.find((c) => c.id === draggedFromColumnId);
      const destinationColumn = project.columns.find((c) => c.id === column.id);

      const sourceIndex = sourceColumn.taskIds.indexOf(draggedTaskId);
      const destinationIndex = destinationColumn.taskIds.length;

      socket.emit("task:move", {
        projectId,
        sourceColumnId: draggedFromColumnId,
        destinationColumnId: column.id,
        sourceIndex,
        destinationIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = project.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task-card";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.innerHTML = `
        <h4>${escapeHtml(task.title)}</h4>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
      });

      taskEl.addEventListener("click", () => {
        openEditModal(task.id);
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

addTaskBtn.addEventListener("click", openTaskModal);
cancelModalBtn.addEventListener("click", closeTaskModal);
cancelEditModalBtn.addEventListener("click", closeEditModal);

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("task:create", {
    projectId,
    columnId: taskColumn.value,
    title: taskTitle.value.trim(),
    description: taskDescription.value.trim()
  });

  closeTaskModal();
});

editTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  if (!editingTaskId) return;

  socket.emit("task:update", {
    projectId,
    taskId: editingTaskId,
    title: editTaskTitle.value.trim(),
    description: editTaskDescription.value.trim()
  });

  closeEditModal();
});

deleteTaskBtn.addEventListener("click", () => {
  if (!editingTaskId) return;

  socket.emit("task:delete", {
    projectId,
    taskId: editingTaskId
  });

  closeEditModal();
});

socket.on("connect", () => {
  socket.emit("project:join", projectId);
});

socket.on("project:update", (updatedProject) => {
  project = updatedProject;
  renderBoard();
});

fetchProject();
```

