## `client/app.js`

```js
const boardEl = document.getElementById("board");
const connectionStatusEl = document.getElementById("connectionStatus");
const taskTemplate = document.getElementById("taskTemplate");

let boardState = null;
let draggedTaskId = null;

const ws = new WebSocket("ws://localhost:4000");

ws.addEventListener("open", () => {
  connectionStatusEl.textContent = "Connected";
});

ws.addEventListener("close", () => {
  connectionStatusEl.textContent = "Disconnected";
});

ws.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);

  if (message.type === "board:init" || message.type === "board:update") {
    boardState = message.payload;
    renderBoard();
  }
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", handleDragOver);
    taskListEl.addEventListener("drop", handleDrop);

    column.tasks.forEach((task) => {
      const taskEl = createTaskElement(task, column.id);
      taskListEl.appendChild(taskEl);
    });

    const formEl = document.createElement("form");
    formEl.className = "add-task-form";
    formEl.innerHTML = `
      <input type="text" name="title" placeholder="Task title" required />
      <textarea name="description" placeholder="Task description"></textarea>
      <button type="submit">Add Task</button>
    `;

    formEl.addEventListener("submit", (e) => {
      e.preventDefault();
      const formData = new FormData(formEl);
      const title = formData.get("title").toString().trim();
      const description = formData.get("description").toString().trim();

      if (!title) return;

      const task = {
        id: `task-${Date.now()}`,
        title,
        description
      };

      ws.send(
        JSON.stringify({
          type: "task:add",
          payload: {
            columnId: column.id,
            task
          }
        })
      );

      formEl.reset();
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    columnEl.appendChild(formEl);
    boardEl.appendChild(columnEl);
  });
}

function createTaskElement(task, columnId) {
  const taskEl = taskTemplate.content.firstElementChild.cloneNode(true);
  taskEl.dataset.taskId = task.id;
  taskEl.dataset.columnId = columnId;

  taskEl.querySelector(".task-title").textContent = task.title;
  taskEl.querySelector(".task-desc").textContent = task.description || "";

  taskEl.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    taskEl.classList.add("dragging");
  });

  taskEl.addEventListener("dragend", () => {
    draggedTaskId = null;
    taskEl.classList.remove("dragging");
  });

  return taskEl;
}

function handleDragOver(e) {
  e.preventDefault();
}

function handleDrop(e) {
  e.preventDefault();

  const targetColumnId = e.currentTarget.dataset.columnId;
  if (!draggedTaskId) return;

  let movedTask = null;

  for (const column of boardState.columns) {
    const taskIndex = column.tasks.findIndex((t) => t.id === draggedTaskId);
    if (taskIndex !== -1) {
      movedTask = column.tasks.splice(taskIndex, 1)[0];
      break;
    }
  }

  if (!movedTask) return;

  const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);
  if (!targetColumn) return;

  targetColumn.tasks.push(movedTask);

  ws.send(
    JSON.stringify({
      type: "board:update",
      payload: boardState
    })
  );
}
```

