## `server/index.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

// In-memory board state
let board = {
  columns: {
    backlog: {
      id: "backlog",
      title: "Backlog",
      taskIds: ["task-1", "task-2"]
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    review: {
      id: "review",
      title: "Review",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  columnOrder: ["backlog", "inprogress", "review", "done"],
  tasks: {
    "task-1": {
      id: "task-1",
      title: "Set up project repository",
      description: "Initialize frontend and backend folders"
    },
    "task-2": {
      id: "task-2",
      title: "Design board layout",
      description: "Create Kanban board UI"
    }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "backlog" } = req.body;

  if (!title || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task payload" });
  }

  const id = uuidv4();
  const task = { id, title, description };

  board.tasks[id] = task;
  board.columns[columnId].taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:create", ({ title, description = "", columnId = "backlog" }) => {
    if (!title || !board.columns[columnId]) return;

    const id = uuidv4();
    const task = { id, title, description };

    board.tasks[id] = task;
    board.columns[columnId].taskIds.push(id);

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    if (
      !board.tasks[taskId] ||
      !board.columns[sourceColumnId] ||
      !board.columns[destinationColumnId]
    ) {
      return;
    }

    const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
    const destTaskIds =
      sourceColumnId === destinationColumnId
        ? sourceTaskIds
        : [...board.columns[destinationColumnId].taskIds];

    const sourceIndex = sourceTaskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceTaskIds.splice(sourceIndex, 1);

    if (sourceColumnId === destinationColumnId) {
      sourceTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
    } else {
      destTaskIds.splice(destinationIndex, 0, taskId);
      board.columns[sourceColumnId].taskIds = sourceTaskIds;
      board.columns[destinationColumnId].taskIds = destTaskIds;
    }

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```

