```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" data-column-id={column.id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    socket.on("board:init", (initialBoard) => setBoard(initialBoard));
    socket.on("board:update", (updatedBoard) => setBoard(updatedBoard));

    return () => {
      socket.off("board:init");
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);
      return { ...column, tasks };
    });
  }, [board]);

  function findColumnByTaskId(taskId) {
    if (!board) return null;
    return Object.values(board.columns).find((column) => column.taskIds.includes(taskId));
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || !board) return;

    const taskId = active.id;
    const overId = over.id;

    const sourceColumn = findColumnByTaskId(taskId);
    if (!sourceColumn) return;

    let destinationColumn = findColumnByTaskId(overId);
    let destinationIndex = 0;

    if (destinationColumn) {
      destinationIndex = destinationColumn.taskIds.indexOf(overId);
    } else {
      destinationColumn = columns.find((c) => c.id === overId);
      if (!destinationColumn) return;
      destinationIndex = destinationColumn.taskIds.length;
    }

    socket.emit("task:move", {
      taskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      destinationIndex
    });
  }

  function handleCreateTask(e) {
    e.preventDefault();
    if (!title.trim()) return;

    socket.emit("task:create", {
      title: title.trim(),
      description: description.trim(),
      columnId: "backlog"
    });

    setTitle("");
    setDescription("");
  }

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
      </header>

      <form className="task-form" onSubmit={handleCreateTask}>
        <input
          type="text"
          placeholder="Task title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <DroppableColumn key={column.id} column={column} tasks={column.tasks} />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function DroppableColumn({ column, tasks }) {
  const { setNodeRef } = require("@dnd-kit/core").useDroppable({
    id: column.id
  });

  return (
    <div ref={setNodeRef}>
      <Column column={column} tasks={tasks} />
    </div>
  );
}
```

