```ts
import { v4 as uuid } from "uuid";
import { Board, Task } from "./types";

const defaultBoard: Board = {
  id: "board-1",
  title: "Project Board",
  columnOrder: ["todo", "in-progress", "done"],
  columns: {
    todo: {
      id: "todo",
      title: "Todo",
      taskIds: []
    },
    "in-progress": {
      id: "in-progress",
      title: "In Progress",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {}
};

let board: Board = defaultBoard;

export function getBoard() {
  return board;
}

export function addTask(columnId: string, title: string, description?: string): Task {
  const id = uuid();
  const task: Task = { id, title, description };
  board.tasks[id] = task;
  board.columns[columnId].taskIds.push(id);
  return task;
}

export function moveTask(
  taskId: string,
  sourceColumnId: string,
  destinationColumnId: string,
  sourceIndex: number,
  destinationIndex: number
) {
  if (sourceColumnId === destinationColumnId) {
    const taskIds = [...board.columns[sourceColumnId].taskIds];
    taskIds.splice(sourceIndex, 1);
    taskIds.splice(destinationIndex, 0, taskId);
    board.columns[sourceColumnId].taskIds = taskIds;
    return;
  }

  const sourceTaskIds = [...board.columns[sourceColumnId].taskIds];
  sourceTaskIds.splice(sourceIndex, 1);

  const destinationTaskIds = [...board.columns[destinationColumnId].taskIds];
  destinationTaskIds.splice(destinationIndex, 0, taskId);

  board.columns[sourceColumnId].taskIds = sourceTaskIds;
  board.columns[destinationColumnId].taskIds = destinationTaskIds;
}
```

## `server/src/index.ts`

```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { addTask, getBoard, moveTask } from "./store";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/board", (_req, res) => {
  res.json(getBoard());
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:init", getBoard());

  socket.on("task:add", ({ columnId, title, description }) => {
    addTask(columnId, title, description);
    io.emit("board:update", getBoard());
  });

  socket.on(
    "task:move",
    ({
      taskId,
      sourceColumnId,
      destinationColumnId,
      sourceIndex,
      destinationIndex
    }) => {
      moveTask(
        taskId,
        sourceColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex
      );
      io.emit("board:update", getBoard());
    }
  );
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

