## `client/src/components/Board.tsx`

```tsx
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter
} from "@dnd-kit/core";
import { Board as BoardType } from "../types";
import Column from "./Column";
import { socket } from "../socket";

type Props = {
  board: BoardType;
};

function findTaskLocation(board: BoardType, taskId: string) {
  for (const columnId of board.columnOrder) {
    const index = board.columns[columnId].taskIds.indexOf(taskId);
    if (index !== -1) {
      return { columnId, index };
    }
  }
  return null;
}

export default function Board({ board }: Props) {
  const sensors = useSensors(useSensor(PointerSensor));

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const source = findTaskLocation(board, String(active.id));
    const destination = findTaskLocation(board, String(over.id));

    if (!source || !destination) return;

    socket.emit("task:move", {
      taskId: String(active.id),
      sourceColumnId: source.columnId,
      destinationColumnId: destination.columnId,
      sourceIndex: source.index,
      destinationIndex: destination.index
    });
  };

  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

          return <Column key={column.id} column={column} tasks={tasks} />;
        })}
      </div>
    </DndContext>
  );
}
```

