```ts
import { Board, Task } from "./types";
import { randomUUID } from "crypto";

const defaultBoardId = "board-1";

const initialTasks: Record<string, Task> = {
  "task-1": {
    id: "task-1",
    title: "Design landing page",
    description: "Create wireframes and mockups",
    columnId: "todo",
    order: 0,
  },
  "task-2": {
    id: "task-2",
    title: "Set up backend API",
    description: "Initialize Express and Socket.IO",
    columnId: "in-progress",
    order: 0,
  },
};

const boards: Record<string, Board> = {
  [defaultBoardId]: {
    id: defaultBoardId,
    title: "Demo Project",
    columns: [
      { id: "todo", title: "Todo", taskIds: ["task-1"] },
      { id: "in-progress", title: "In Progress", taskIds: ["task-2"] },
      { id: "done", title: "Done", taskIds: [] },
    ],
    tasks: initialTasks,
  },
};

export function getBoard(boardId: string) {
  return boards[boardId];
}

export function createTask(boardId: string, title: string, description = "") {
  const board = boards[boardId];
  if (!board) return null;

  const todoColumn = board.columns[0];
  const id = randomUUID();

  const task: Task = {
    id,
    title,
    description,
    columnId: todoColumn.id,
    order: todoColumn.taskIds.length,
  };

  board.tasks[id] = task;
  todoColumn.taskIds.push(id);

  return task;
}

export function moveTask(
  boardId: string,
  taskId: string,
  sourceColumnId: string,
  destinationColumnId: string,
  sourceIndex: number,
  destinationIndex: number
) {
  const board = boards[boardId];
  if (!board) return null;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) return null;

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  board.tasks[taskId].columnId = destinationColumnId;

  destinationColumn.taskIds.forEach((id, index) => {
    board.tasks[id].order = index;
  });

  if (sourceColumnId !== destinationColumnId) {
    sourceColumn.taskIds.forEach((id, index) => {
      board.tasks[id].order = index;
    });
  }

  return board;
}

export function updateTask(boardId: string, taskId: string, updates: Partial<Task>) {
  const board = boards[boardId];
  if (!board || !board.tasks[taskId]) return null;

  board.tasks[taskId] = {
    ...board.tasks[taskId],
    ...updates,
  };

  return board.tasks[taskId];
}
```

## `server/src/index.ts`

```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { createTask, getBoard, moveTask, updateTask } from "./boardStore";
import { MoveTaskPayload, UserPresence } from "./types";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"],
  },
});

const presenceByBoard: Record<string, UserPresence[]> = {};

app.get("/boards/:boardId", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/boards/:boardId/tasks", (req, res) => {
  const { title, description } = req.body;
  const task = createTask(req.params.boardId, title, description);
  if (!task) return res.status(404).json({ error: "Board not found" });

  const board = getBoard(req.params.boardId);
  io.to(req.params.boardId).emit("board:update", board);

  res.status(201).json(task);
});

io.on("connection", (socket) => {
  socket.on("board:join", ({ boardId, name }: { boardId: string; name: string }) => {
    socket.join(boardId);

    if (!presenceByBoard[boardId]) presenceByBoard[boardId] = [];
    presenceByBoard[boardId].push({ socketId: socket.id, name });

    socket.to(boardId).emit("presence:update", presenceByBoard[boardId]);
    socket.emit("presence:update", presenceByBoard[boardId]);

    const board = getBoard(boardId);
    socket.emit("board:update", board);
  });

  socket.on("task:move", (payload: MoveTaskPayload) => {
    const board = moveTask(
      payload.boardId,
      payload.taskId,
      payload.sourceColumnId,
      payload.destinationColumnId,
      payload.sourceIndex,
      payload.destinationIndex
    );

    if (board) {
      io.to(payload.boardId).emit("board:update", board);
    }
  });

  socket.on("task:update", ({ boardId, taskId, updates }) => {
    const task = updateTask(boardId, taskId, updates);
    if (task) {
      io.to(boardId).emit("task:updated", { taskId, task });
      io.to(boardId).emit("board:update", getBoard(boardId));
    }
  });

  socket.on("disconnecting", () => {
    for (const boardId of socket.rooms) {
      if (presenceByBoard[boardId]) {
        presenceByBoard[boardId] = presenceByBoard[boardId].filter(
          (u) => u.socketId !== socket.id
        );
        socket.to(boardId).emit("presence:update", presenceByBoard[boardId]);
      }
    }
  });
});

server.listen(4000, () => {
  console.log("Server listening on http://localhost:4000");
});
