## `client/src/hooks/useBoardSocket.ts`

```ts
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import { Board, UserPresence } from "../types";

const SERVER_URL = "http://localhost:4000";

export function useBoardSocket(boardId: string, name: string) {
  const [board, setBoard] = useState<Board | null>(null);
  const [presence, setPresence] = useState<UserPresence[]>([]);

  const socket: Socket = useMemo(() => io(SERVER_URL), []);

  useEffect(() => {
    socket.emit("board:join", { boardId, name });

    socket.on("board:update", (nextBoard: Board) => {
      setBoard(nextBoard);
    });

    socket.on("presence:update", (users: UserPresence[]) => {
      setPresence(users);
    });

    socket.on("task:updated", ({ task }) => {
      setBoard((prev) => {
        if (!prev) return prev;
        return {
          ...prev,
          tasks: {
            ...prev.tasks,
            [task.id]: task,
          },
        };
      });
    });

    return () => {
      socket.off("board:update");
      socket.off("presence:update");
      socket.off("task:updated");
      socket.disconnect();
    };
  }, [socket, boardId, name]);

  return { socket, board, setBoard, presence };
}
