## `client/src/components/Board.tsx`

```tsx
import { DndContext, DragEndEvent } from "@dnd-kit/core";
import { Board as BoardType } from "../types";
import Column from "./Column";

type Props = {
  board: BoardType;
  onMoveTask: (args: {
    taskId: string;
    sourceColumnId: string;
    destinationColumnId: string;
    sourceIndex: number;
    destinationIndex: number;
  }) => void;
};

export default function Board({ board, onMoveTask }: Props) {
  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const destinationColumnId = String(over.id);

    const task = board.tasks[taskId];
    if (!task) return;

    const sourceColumnId = task.columnId;
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    const destinationIndex = destinationColumn.taskIds.length;

    onMoveTask({
      taskId,
      sourceColumnId,
      destinationColumnId,
      sourceIndex,
      destinationIndex,
    });
  }

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div className="flex gap-4 overflow-x-auto">
        {board.columns.map((column) => (
          <Column key={column.id} column={column} board={board} />
        ))}
      </div>
    </DndContext>
  );
}
