import { useState } from "react";
import { useBoardSocket } from "./hooks/useBoardSocket";
import Board from "./components/Board";
import PresenceBar from "./components/PresenceBar";

const BOARD_ID = "board-1";

export default function App() {
  const [name] = useState(() => `User-${Math.floor(Math.random() * 1000)}`);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const { socket, board, presence } = useBoardSocket(BOARD_ID, name);

  async function createTask() {
    if (!newTaskTitle.trim()) return;

    await fetch(`http://localhost:4000/boards/${BOARD_ID}/tasks`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ title: newTaskTitle }),
    });

    setNewTaskTitle("");
  }

  if (!board) {
    return <div className="p-6">Loading board...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <header className="mb-6">
        <h1 className="text-2xl font-bold">{board.title}</h1>
        <p className="text-sm text-gray-500">Connected as {name}</p>
      </header>

      <PresenceBar users={presence} />

      <div className="mb-6 flex gap-2">
        <input
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="New task title"
          className="border rounded-lg px-3 py-2 w-80"
        />
        <button
          onClick={createTask}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg"
        >
          Add Task
        </button>
      </div>

      <Board
        board={board}
        onMoveTask={({ taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex }) => {
          socket.emit("task:move", {
            boardId: BOARD_ID,
            taskId,
            sourceColumnId,
            destinationColumnId,
            sourceIndex,
            destinationIndex,
          });
        }}
      />
    </div>
  );
}
