# 3. `server.js`

```js
const express = require('express');
const http = require('http');
const path = require('path');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, 'public')));
app.use(express.json());

// In-memory board state
let board = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: ['task-1', 'task-2']
    },
    doing: {
      id: 'doing',
      title: 'Doing',
      taskIds: []
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {
    'task-1': { id: 'task-1', title: 'Set up project' },
    'task-2': { id: 'task-2', title: 'Build drag-and-drop board' }
  },
  columnOrder: ['todo', 'doing', 'done']
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'init', board }));

  ws.on('message', message => {
    try {
      const data = JSON.parse(message);

      if (data.type === 'move-task') {
        const { taskId, sourceColId, destColId, destIndex } = data;

        const sourceCol = board.columns[sourceColId];
        const destCol = board.columns[destColId];
        if (!sourceCol || !destCol) return;

        sourceCol.taskIds = sourceCol.taskIds.filter(id => id !== taskId);
        destCol.taskIds.splice(destIndex, 0, taskId);

        broadcast({ type: 'update-board', board });
      }

      if (data.type === 'create-task') {
        const taskId = `task-${Date.now()}`;
        const title = (data.title || '').trim();
        const colId = data.colId;

        if (!title || !board.columns[colId]) return;

        board.tasks[taskId] = { id: taskId, title };
        board.columns[colId].taskIds.push(taskId);

        broadcast({ type: 'update-board', board });
      }

      if (data.type === 'delete-task') {
        const { taskId, colId } = data;
        if (!board.tasks[taskId] || !board.columns[colId]) return;

        delete board.tasks[taskId];
        board.columns[colId].taskIds = board.columns[colId].taskIds.filter(id => id !== taskId);

        broadcast({ type: 'update-board', board });
      }
    } catch (err) {
      console.error('Invalid message:', err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

