# 6. `public/app.js`

```js
const boardEl = document.getElementById('board');
const columnTemplate = document.getElementById('column-template');
const taskTemplate = document.getElementById('task-template');

const socket = new WebSocket(`ws://${location.host}`);

let board = null;
let draggedTaskId = null;
let draggedSourceColId = null;

socket.addEventListener('message', event => {
  const data = JSON.parse(event.data);

  if (data.type === 'init' || data.type === 'update-board') {
    board = data.board;
    renderBoard();
  }
});

function send(data) {
  if (socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify(data));
  }
}

function renderBoard() {
  boardEl.innerHTML = '';

  board.columnOrder.forEach(colId => {
    const col = board.columns[colId];
    const colNode = columnTemplate.content.firstElementChild.cloneNode(true);
    const titleEl = colNode.querySelector('h2');
    const taskListEl = colNode.querySelector('.task-list');
    const inputEl = colNode.querySelector('input');
    const addBtn = colNode.querySelector('button');

    titleEl.textContent = col.title;

    taskListEl.dataset.colId = col.id;

    taskListEl.addEventListener('dragover', e => {
      e.preventDefault();
      taskListEl.classList.add('drag-over');
    });

    taskListEl.addEventListener('dragleave', () => {
      taskListEl.classList.remove('drag-over');
    });

    taskListEl.addEventListener('drop', e => {
      e.preventDefault();
      taskListEl.classList.remove('drag-over');

      if (!draggedTaskId || !draggedSourceColId) return;

      send({
        type: 'move-task',
        taskId: draggedTaskId,
        sourceColId: draggedSourceColId,
        destColId: col.id,
        destIndex: col.taskIds.length
      });

      draggedTaskId = null;
      draggedSourceColId = null;
    });

    col.taskIds.forEach(taskId => {
      const task = board.tasks[taskId];
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      const titleSpan = taskNode.querySelector('.task-title');
      const deleteBtn = taskNode.querySelector('.delete-btn');

      titleSpan.textContent = task.title;
      taskNode.dataset.taskId = task.id;

      taskNode.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        draggedSourceColId = col.id;
        taskNode.classList.add('dragging');
      });

      taskNode.addEventListener('dragend', () => {
        taskNode.classList.remove('dragging');
      });

      deleteBtn.addEventListener('click', () => {
        send({
          type: 'delete-task',
          taskId: task.id,
          colId: col.id
        });
      });

      taskListEl.appendChild(taskNode);
    });

    addBtn.addEventListener('click', () => {
      const title = inputEl.value.trim();
      if (!title) return;

      send({
        type: 'create-task',
        title,
        colId: col.id
      });

      inputEl.value = '';
    });

    inputEl.addEventListener('keydown', e => {
      if (e.key === 'Enter') {
        addBtn.click();
      }
    });

    colNode.querySelector('.add-task').appendChild(addBtn);
    boardEl.appendChild(colNode);
  });
}
