# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));
app.use(express.json());

// In-memory board state
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", text: "Set up project" },
        { id: "task-2", text: "Design board UI" }
      ]
    },
    {
      id: "doing",
      title: "Doing",
      tasks: [
        { id: "task-3", text: "Implement drag and drop" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", text: "Create initial idea" }
      ]
    }
  ]
};

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("board:set", (newBoard) => {
    board = newBoard;
    socket.broadcast.emit("board:update", board);
  });

  socket.on("task:add", ({ columnId, text }) => {
    const column = board.columns.find((c) => c.id === columnId);
    if (!column || !text?.trim()) return;

    column.tasks.push({
      id: `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      text: text.trim()
    });

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId }) => {
    for (const column of board.columns) {
      const index = column.tasks.findIndex((t) => t.id === taskId);
      if (index !== -1) {
        column.tasks.splice(index, 1);
        io.emit("board:update", board);
        return;
      }
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

