# 6. `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTaskId = null;

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

function renderBoard() {
  const boardEl = document.getElementById("board");
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = column.title;
    columnEl.appendChild(title);

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");

      if (!draggedTaskId) return;
      moveTask(draggedTaskId, column.id);
      draggedTaskId = null;
    });

    column.tasks.forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      const text = document.createElement("span");
      text.textContent = task.text;

      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskEl.appendChild(text);
      taskEl.appendChild(deleteBtn);
      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(taskList);

    const addTaskWrap = document.createElement("div");
    addTaskWrap.className = "add-task";

    const input = document.createElement("input");
    input.type = "text";
    input.placeholder = "New task...";

    const addBtn = document.createElement("button");
    addBtn.textContent = "Add";
    addBtn.addEventListener("click", () => {
      const text = input.value.trim();
      if (!text) return;
      socket.emit("task:add", { columnId: column.id, text });
      input.value = "";
    });

    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") addBtn.click();
    });

    addTaskWrap.appendChild(input);
    addTaskWrap.appendChild(addBtn);
    columnEl.appendChild(addTaskWrap);

    boardEl.appendChild(columnEl);
  });
}

function moveTask(taskId, targetColumnId) {
  let taskToMove = null;

  for (const column of boardState.columns) {
    const index = column.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      taskToMove = column.tasks.splice(index, 1)[0];
      break;
    }
  }

  if (!taskToMove) return;

  const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);
  if (!targetColumn) return;

  targetColumn.tasks.push(taskToMove);

  socket.emit("board:set", boardState);
  renderBoard();
}
