const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

const board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["1", "2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "1": { id: "1", title: "Set up project" },
    "2": { id: "2", title: "Create first tasks" }
  },
  columnOrder: ["todo", "doing", "done"]
};

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:add", ({ columnId, title }) => {
    const id = Date.now().toString();
    board.tasks[id] = { id, title };
    board.columns[columnId].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const sourceIds = board.columns[sourceColumnId].taskIds;
    const targetIds = board.columns[targetColumnId].taskIds;

    const sourceIndex = sourceIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceIds.splice(sourceIndex, 1);
    targetIds.splice(targetIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:reorder", ({ columnId, taskId, targetIndex }) => {
    const ids = board.columns[columnId].taskIds;
    const currentIndex = ids.indexOf(taskId);
    if (currentIndex === -1) return;

    ids.splice(currentIndex, 1);
    ids.splice(targetIndex, 0, taskId);

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
