const io = new Server(server);

app.use(express.static("public"));

const board = {
  columns: {
    todo: [
      { id: "1", text: "Set up project" },
      { id: "2", text: "Design UI" }
    ],
    doing: [
      { id: "3", text: "Build drag-and-drop" }
    ],
