    io.emit("task:added", { columnId, task });
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromTasks = board.columns[fromColumnId];
    const toTasks = board.columns[toColumnId];

    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);
    toTasks.splice(toIndex, 0, task);

    io.emit("task:moved", {
      taskId,
      fromColumnId,
      toColumnId,
      toIndex
    });
  });

  socket.on("task:reorder", ({ columnId, taskId, toIndex }) => {
    const tasks = board.columns[columnId];
    const fromIndex = tasks.findIndex((t) => t.id === taskId);
    if (fromIndex === -1) return;

    const [task] = tasks.splice(fromIndex, 1);
    tasks.splice(toIndex, 0, task);

    io.emit("task:reordered", { columnId, taskId, toIndex });
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
