## 5) `public/app.js`

```js
const socket = io();

let boardState = {
  columns: {
    todo: [],
    doing: [],
    done: []
  }
};

function createTaskElement(task) {
  const el = document.createElement("div");
  el.className = "task";
  el.draggable = true;
  el.dataset.taskId = task.id;
  el.textContent = task.text;

  el.addEventListener("dragstart", (e) => {
    el.classList.add("dragging");
    const parentColumnId = el.parentElement.id;
    e.dataTransfer.setData(
      "text/plain",
      JSON.stringify({
        taskId: task.id,
        fromColumnId: parentColumnId
      })
    );
  });

  el.addEventListener("dragend", () => {
    el.classList.remove("dragging");
  });

  return el;
}

function renderBoard() {
  Object.keys(boardState.columns).forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";
    boardState.columns[columnId].forEach((task) => {
      list.appendChild(createTaskElement(task));
    });
  });
}

function getDropIndex(container, clientY) {
  const items = [...container.querySelectorAll(".task:not(.dragging)")];
  let closest = { offset: Number.NEGATIVE_INFINITY, index: items.length };

  items.forEach((item, index) => {
    const rect = item.getBoundingClientRect();
    const offset = clientY - rect.top - rect.height / 2;
    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

document.querySelectorAll(".task-list").forEach((list) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    const data = JSON.parse(e.dataTransfer.getData("text/plain"));
    const toColumnId = list.id;
    const toIndex = getDropIndex(list, e.clientY);

    if (data.fromColumnId === toColumnId) {
      socket.emit("task:reorder", {
        columnId: toColumnId,
        taskId: data.taskId,
        toIndex
      });
    } else {
      socket.emit("task:move", {
        taskId: data.taskId,
        fromColumnId: data.fromColumnId,
        toColumnId,
        toIndex
      });
    }
  });
});

document.querySelectorAll(".add-task-form").forEach((form) => {
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const columnId = form.dataset.columnId;
    const input = form.querySelector("input");
    const text = input.value.trim();
    if (!text) return;

    socket.emit("task:add", { columnId, text });
    input.value = "";
  });
});

socket.on("board:init", (board) => {
  boardState = board;
  renderBoard();
});

socket.on("task:added", ({ columnId, task }) => {
  boardState.columns[columnId].push(task);
  renderBoard();
});

socket.on("task:moved", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
  const fromTasks = boardState.columns[fromColumnId];
  const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = fromTasks.splice(taskIndex, 1);
  boardState.columns[toColumnId].splice(toIndex, 0, task);
  renderBoard();
});

socket.on("task:reordered", ({ columnId, taskId, toIndex }) => {
  const tasks = boardState.columns[columnId];
  const fromIndex = tasks.findIndex((t) => t.id === taskId);
  if (fromIndex === -1) return;

  const [task] = tasks.splice(fromIndex, 1);
  tasks.splice(toIndex, 0, task);
  renderBoard();
});
```

