## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {},
  columnOrder: ["todo", "doing", "done"]
};

function createTaskId() {
  return "task_" + Math.random().toString(36).slice(2, 9);
}

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:create", ({ columnId, content }) => {
    if (!columnId || !content) return;

    const taskId = createTaskId();
    board.tasks[taskId] = {
      id: taskId,
      content
    };
    board.columns[columnId].taskIds.push(taskId);

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    if (!taskId || !columnId) return;

    delete board.tasks[taskId];
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destColumnId, destIndex }) => {
    if (!taskId || !sourceColumnId || !destColumnId || destIndex == null) return;

    const sourceTasks = board.columns[sourceColumnId].taskIds;
    const destTasks = board.columns[destColumnId].taskIds;

    board.columns[sourceColumnId].taskIds = sourceTasks.filter((id) => id !== taskId);

    const insertAt = Math.max(0, Math.min(destIndex, destTasks.length));
    destTasks.splice(insertAt, 0, taskId);

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

