          taskEl.dataset.taskId = task.id;
          taskEl.dataset.columnId = columnId;

          taskEl.addEventListener("dragstart", () => {
            draggedTaskId = task.id;
            draggedFromColumnId = columnId;
            taskEl.classList.add("dragging");
          });

          taskEl.addEventListener("dragend", () => {
            draggedTaskId = null;
            draggedFromColumnId = null;
            taskEl.classList.remove("dragging");
            document.querySelectorAll(".drop-zone").forEach(z => z.classList.remove("active"));
          });

          const text = document.createElement("span");
          text.textContent = task.content;

          const delBtn = document.createElement("button");
          delBtn.textContent = "Delete";
          delBtn.addEventListener("click", () => {
            socket.emit("task:delete", {
              taskId: task.id,
              columnId
            });
          });

          taskEl.appendChild(text);
          taskEl.appendChild(delBtn);
          taskList.appendChild(taskEl);
        });

        taskList.appendChild(createDropZone(columnId, column.taskIds.length));
        columnEl.appendChild(taskList);

        const addTask = document.createElement("div");
        addTask.className = "add-task";

        const input = document.createElement("input");
        input.placeholder = "New task...";

        const button = document.createElement("button");
        button.textContent = "Add";
        button.addEventListener("click", () => {
          const content = input.value.trim();
          if (!content) return;
          socket.emit("task:create", {
            columnId,
            content
          });
          input.value = "";
        });

        input.addEventListener("keypress", (e) => {
          if (e.key === "Enter") button.click();
        });

        addTask.appendChild(input);
        addTask.appendChild(button);
        columnEl.appendChild(addTask);

        boardEl.appendChild(columnEl);
      });
    }

    function createDropZone(columnId, index) {
      const zone = document.createElement("div");
      zone.className = "drop-zone";

      zone.addEventListener("dragover", (e) => {
        e.preventDefault();
        zone.classList.add("active");
      });

      zone.addEventListener("dragleave", () => {
        zone.classList.remove("active");
      });

      zone.addEventListener("drop", (e) => {
        e.preventDefault();
        zone.classList.remove("active");

        if (!draggedTaskId || !draggedFromColumnId) return;

        socket.emit("task:move", {
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destColumnId: columnId,
          destIndex: index
        });
      });

      return zone;
    }
  </script>
</body>
