## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project" },
    "task-2": { id: "task-2", title: "Create first tasks" }
  },
  columnOrder: ["todo", "doing", "done"]
};

let nextTaskId = 3;

app.get("/api/board", (req, res) => {
  res.json(board);
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", ({ title, columnId }) => {
    if (!title || !columnId || !board.columns[columnId]) return;

    const id = `task-${nextTaskId++}`;
    board.tasks[id] = { id, title };
    board.columns[columnId].taskIds.push(id);

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = board.columns[fromColumnId];
    const toColumn = board.columns[toColumnId];

    if (!taskId || !fromColumn || !toColumn) return;

    const fromIndex = fromColumn.taskIds.indexOf(taskId);
    if (fromIndex === -1) return;

    fromColumn.taskIds.splice(fromIndex, 1);

    const safeIndex =
      typeof toIndex === "number" && toIndex >= 0
        ? Math.min(toIndex, toColumn.taskIds.length)
        : toColumn.taskIds.length;

    toColumn.taskIds.splice(safeIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    if (!taskId || !columnId || !board.columns[columnId]) return;

    delete board.tasks[taskId];
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

