## 2) `server.js`

```js
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// In-memory app state
let state = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: ['task-1', 'task-2']
    },
    doing: {
      id: 'doing',
      title: 'Doing',
      taskIds: ['task-3']
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {
    'task-1': { id: 'task-1', content: 'Set up project' },
    'task-2': { id: 'task-2', content: 'Design UI' },
    'task-3': { id: 'task-3', content: 'Build drag-and-drop' }
  },
  columnOrder: ['todo', 'doing', 'done']
};

function broadcastState() {
  io.emit('state:update', state);
}

app.get('/api/state', (req, res) => {
  res.json(state);
});

app.post('/api/tasks', (req, res) => {
  const { content, columnId } = req.body;
  if (!content || !columnId || !state.columns[columnId]) {
    return res.status(400).json({ error: 'Invalid task data' });
  }

  const id = `task-${Date.now()}`;
  state.tasks[id] = { id, content };
  state.columns[columnId].taskIds.push(id);

  broadcastState();
  res.json({ success: true, state });
});

app.delete('/api/tasks/:taskId', (req, res) => {
  const { taskId } = req.params;

  if (!state.tasks[taskId]) {
    return res.status(404).json({ error: 'Task not found' });
  }

  delete state.tasks[taskId];

  for (const column of Object.values(state.columns)) {
    column.taskIds = column.taskIds.filter(id => id !== taskId);
  }

  broadcastState();
  res.json({ success: true, state });
});

io.on('connection', (socket) => {
  socket.emit('state:update', state);

  socket.on('task:move', ({ taskId, sourceColumnId, targetColumnId, targetIndex }) => {
    const source = state.columns[sourceColumnId];
    const target = state.columns[targetColumnId];

    if (!source || !target || !state.tasks[taskId]) return;

    source.taskIds = source.taskIds.filter(id => id !== taskId);

    const safeIndex = Math.max(0, Math.min(targetIndex, target.taskIds.length));
    target.taskIds.splice(safeIndex, 0, taskId);

    broadcastState();
  });

  socket.on('task:update', ({ taskId, content }) => {
    if (!state.tasks[taskId] || typeof content !== 'string') return;
    state.tasks[taskId].content = content.trim() || state.tasks[taskId].content;
    broadcastState();
  });

  socket.on('disconnect', () => {
    console.log('User disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
