      if (!draggedTaskId || !draggedFromColumnId) return;

      const targetColumnId = taskList.dataset.columnId;
      const afterElement = getDragAfterElement(taskList, e.clientY);
      let targetIndex = appState.columns[targetColumnId].taskIds.length;

      if (afterElement) {
        const afterTaskId = afterElement.dataset.taskId;
        targetIndex = appState.columns[targetColumnId].taskIds.indexOf(afterTaskId);
      }

      socket.emit('task:move', {
        taskId: draggedTaskId,
        sourceColumnId: draggedFromColumnId,
        targetColumnId,
        targetIndex
      });
    });

    board.appendChild(columnEl);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      return { offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

function escapeHtml(str) {
  return str
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

addTaskForm.addEventListener('submit', async (e) => {
  e.preventDefault();

  const content = taskInput.value.trim();
  const columnId = columnSelect.value;

  if (!content) return;

  await fetch('/api/tasks', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ content, columnId })
  });

  taskInput.value = '';
});

socket.on('state:update', (state) => {
  render(state);
});

fetch('/api/state')
  .then(res => res.json())
  .then(render);
```

