# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["1", "2"] },
    { id: "doing", title: "Doing", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "1": { id: "1", title: "Set up project", description: "Initialize app structure" },
    "2": { id: "2", title: "Build board UI", description: "Create drag-and-drop columns" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body;
  const id = Date.now().toString();

  const task = {
    id,
    title: title || "Untitled Task",
    description: description || ""
  };

  board.tasks[id] = task;

  const column = board.columns.find(c => c.id === columnId) || board.columns[0];
  column.taskIds.push(id);

  io.emit("board:update", board);
  res.json(task);
});

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromCol = board.columns.find(c => c.id === fromColumnId);
    const toCol = board.columns.find(c => c.id === toColumnId);

    if (!fromCol || !toCol) return;

    fromCol.taskIds = fromCol.taskIds.filter(id => id !== taskId);

    if (typeof toIndex === "number" && toIndex >= 0 && toIndex <= toCol.taskIds.length) {
      toCol.taskIds.splice(toIndex, 0, taskId);
    } else {
      toCol.taskIds.push(taskId);
    }

    io.emit("board:update", board);
  });

  socket.on("task:create", ({ title, description, columnId }) => {
    const id = Date.now().toString();
    const task = {
      id,
      title: title || "Untitled Task",
      description: description || ""
    };

    board.tasks[id] = task;
    const column = board.columns.find(c => c.id === columnId) || board.columns[0];
    column.taskIds.push(id);

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

