# 6. `public/app.js`

```js
const socket = io();

let boardData = null;
let draggedTaskId = null;

const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

socket.on("board:init", (data) => {
  boardData = data;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardData.columnOrder.forEach((columnId) => {
    const column = boardData.columns[columnId];
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);

    columnNode.dataset.columnId = column.id;
    columnNode.querySelector("h2").textContent = column.title;

    const taskList = columnNode.querySelector(".task-list");
    taskList.dataset.columnId = column.id;

    column.taskIds.forEach((taskId) => {
      const task = boardData.tasks[taskId];
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);

      taskNode.textContent = task.content;
      taskNode.dataset.taskId = task.id;

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        draggedTaskId = null;
        taskNode.classList.remove("dragging");
      });

      taskList.appendChild(taskNode);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", () => {
      taskList.classList.remove("drag-over");
      if (!draggedTaskId) return;

      moveTask(draggedTaskId, column.id);
    });

    const form = columnNode.querySelector(".add-task-form");
    const input = form.querySelector("input");

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const content = input.value.trim();
      if (!content) return;

      socket.emit("task:add", {
        columnId: column.id,
        content
      });

      input.value = "";
    });

    boardEl.appendChild(columnNode);
  });
}

function moveTask(taskId, targetColumnId) {
  let sourceColumnId = null;

  for (const columnId of boardData.columnOrder) {
    const idx = boardData.columns[columnId].taskIds.indexOf(taskId);
    if (idx !== -1) {
      sourceColumnId = columnId;
      boardData.columns[columnId].taskIds.splice(idx, 1);
      break;
    }
  }

  if (!sourceColumnId) return;

  boardData.columns[targetColumnId].taskIds.push(taskId);

  renderBoard();
  socket.emit("board:update", boardData);
}
