## `public/app.js`

```js
const boardEl = document.getElementById("board");
const taskForm = document.getElementById("task-form");
const taskTitleInput = document.getElementById("task-title");
const taskColumnSelect = document.getElementById("task-column");

let boardData = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

async function fetchBoard() {
  const res = await fetch("/api/board");
  boardData = await res.json();
  renderBoard();
}

function renderBoard() {
  boardEl.innerHTML = "";

  boardData.columnOrder.forEach(columnId => {
    const column = boardData.columns[columnId];

    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      columnEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      columnEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", async e => {
      e.preventDefault();
      columnEl.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const destColumnId = column.id;
      const destIndex = column.taskIds.length;

      await fetch("/api/move", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          taskId: draggedTaskId,
          sourceColumnId: draggedFromColumnId,
          destColumnId,
          destIndex
        })
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    column.taskIds.forEach(taskId => {
      const task = boardData.tasks[taskId];
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

taskForm.addEventListener("submit", async e => {
  e.preventDefault();
  const title = taskTitleInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  await fetch("/api/task", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, columnId })
  });

  taskTitleInput.value = "";
});

const protocol = location.protocol === "https:" ? "wss" : "ws";
const socket = new WebSocket(`${protocol}://${location.host}`);

socket.addEventListener("message", event => {
  const message = JSON.parse(event.data);
  if (message.type === "BOARD_UPDATE") {
    boardData = message.board;
    renderBoard();
  }
});

fetchBoard();
