# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

const board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project" },
    "task-2": { id: "task-2", title: "Create first tasks" }
  },
  columnOrder: ["todo", "doing", "done"]
};

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", board);

  socket.on("task:add", ({ columnId, title }) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    board.tasks[id] = { id, title };
    board.columns[columnId].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceTaskIds = board.columns[sourceColumnId].taskIds;
    const destTaskIds = board.columns[destinationColumnId].taskIds;

    const sourceIndex = sourceTaskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    sourceTaskIds.splice(sourceIndex, 1);
    destTaskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:reorder", ({ columnId, taskId, destinationIndex }) => {
    const taskIds = board.columns[columnId].taskIds;
    const sourceIndex = taskIds.indexOf(taskId);
    if (sourceIndex === -1) return;

    taskIds.splice(sourceIndex, 1);
    taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

