  <script>
    const socket = io();
    let boardData = null;
    let draggedTaskId = null;
    let draggedFromColumnId = null;

    socket.on("board:init", (data) => {
      boardData = data;
      render();
    });

    socket.on("board:update", (data) => {
      boardData = data;
      render();
    });

    function render() {
      const board = document.getElementById("board");
      board.innerHTML = "";

      boardData.columnOrder.forEach((columnId) => {
        const column = boardData.columns[columnId];
        const columnEl = document.createElement("div");
        columnEl.className = "column";

        const title = document.createElement("h2");
        title.textContent = column.title;
        columnEl.appendChild(title);

        const taskList = document.createElement("div");
        taskList.className = "task-list";

        column.taskIds.forEach((taskId, index) => {
          const beforeDropZone = createDropZone(columnId, index);
          taskList.appendChild(beforeDropZone);

          const task = boardData.tasks[taskId];
          const taskEl = document.createElement("div");
          taskEl.className = "task";
          taskEl.draggable = true;
          taskEl.textContent = task.title;
          taskEl.dataset.taskId = task.id;
          taskEl.dataset.columnId = columnId;

          taskEl.addEventListener("dragstart", () => {
            draggedTaskId = task.id;
            draggedFromColumnId = columnId;
            taskEl.classList.add("dragging");
          });

          taskEl.addEventListener("dragend", () => {
            draggedTaskId = null;
            draggedFromColumnId = null;
            document.querySelectorAll(".drop-zone").forEach(z => z.classList.remove("active"));
            taskEl.classList.remove("dragging");
          });

          taskList.appendChild(taskEl);
        });

        taskList.appendChild(createDropZone(columnId, column.taskIds.length));
        columnEl.appendChild(taskList);

        const addTask = document.createElement("div");
        addTask.className = "add-task";

        const input = document.createElement("input");
        input.placeholder = "New task";

        const button = document.createElement("button");
        button.textContent = "Add";

        button.addEventListener("click", () => {
          const title = input.value.trim();
          if (!title) return;
          socket.emit("task:add", { columnId, title });
          input.value = "";
        });

        input.addEventListener("keydown", (e) => {
          if (e.key === "Enter") button.click();
        });

        addTask.appendChild(input);
        addTask.appendChild(button);
        columnEl.appendChild(addTask);

        board.appendChild(columnEl);
      });
    }

    function createDropZone(columnId, index) {
      const zone = document.createElement("div");
      zone.className = "drop-zone";

      zone.addEventListener("dragover", (e) => {
        e.preventDefault();
        zone.classList.add("active");
      });

      zone.addEventListener("dragleave", () => {
        zone.classList.remove("active");
      });

      zone.addEventListener("drop", (e) => {
        e.preventDefault();
        zone.classList.remove("active");

        if (!draggedTaskId || !draggedFromColumnId) return;

        if (draggedFromColumnId === columnId) {
          socket.emit("task:reorder", {
            columnId,
            taskId: draggedTaskId,
            destinationIndex: index
          });
        } else {
          socket.emit("task:move", {
            taskId: draggedTaskId,
            sourceColumnId: draggedFromColumnId,
            destinationColumnId: columnId,
            destinationIndex: index
          });
        }
      });

      return zone;
    }
  </script>
