## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

const state = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Set up project" },
    "task-2": { id: "task-2", content: "Build drag-and-drop board" }
  },
  columnOrder: ["todo", "doing", "done"]
};

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", ({ columnId, content }) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    state.tasks[id] = { id, content };
    state.columns[columnId].taskIds.push(id);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromTaskIds = state.columns[fromColumnId].taskIds;
    const toTaskIds = state.columns[toColumnId].taskIds;

    const fromIndex = fromTaskIds.indexOf(taskId);
    if (fromIndex === -1) return;

    fromTaskIds.splice(fromIndex, 1);
    toTaskIds.splice(toIndex, 0, taskId);

    io.emit("state:update", state);
  });

  socket.on("task:reorder", ({ columnId, taskId, toIndex }) => {
    const taskIds = state.columns[columnId].taskIds;
    const fromIndex = taskIds.indexOf(taskId);
    if (fromIndex === -1) return;

    taskIds.splice(fromIndex, 1);
    taskIds.splice(toIndex, 0, taskId);

    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    state.columns[columnId].taskIds = state.columns[columnId].taskIds.filter(
      (id) => id !== taskId
    );
    delete state.tasks[taskId];
    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

