## 5) `public/app.js`

```js
const socket = io();
const board = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

let appState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.on("state:init", (state) => {
  appState = state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

function render() {
  board.innerHTML = "";

  appState.columnOrder.forEach((columnId) => {
    const column = appState.columns[columnId];
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    const titleNode = columnNode.querySelector("h2");
    const taskListNode = columnNode.querySelector(".task-list");
    const formNode = columnNode.querySelector(".add-task-form");
    const inputNode = formNode.querySelector("input");

    titleNode.textContent = column.title;
    columnNode.dataset.columnId = column.id;
    taskListNode.dataset.columnId = column.id;

    column.taskIds.forEach((taskId) => {
      const task = appState.tasks[taskId];
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      const contentNode = taskNode.querySelector(".task-content");
      const deleteBtn = taskNode.querySelector(".delete-btn");

      contentNode.textContent = task.content;
      taskNode.dataset.taskId = task.id;
      taskNode.dataset.columnId = column.id;

      taskNode.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskNode.classList.add("dragging");
      });

      taskNode.addEventListener("dragend", () => {
        taskNode.classList.remove("dragging");
        draggedTaskId = null;
        draggedFromColumnId = null;
      });

      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId: column.id });
      });

      taskListNode.appendChild(taskNode);
    });

    taskListNode.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListNode.classList.add("drag-over");
    });

    taskListNode.addEventListener("dragleave", () => {
      taskListNode.classList.remove("drag-over");
    });

    taskListNode.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListNode.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const afterElement = getDragAfterElement(taskListNode, e.clientY);
      const toColumnId = taskListNode.dataset.columnId;
      const taskNodes = [...taskListNode.querySelectorAll(".task:not(.dragging)")];

      let toIndex = taskNodes.length;
      if (afterElement) {
        toIndex = taskNodes.indexOf(afterElement);
      }

      if (draggedFromColumnId === toColumnId) {
        socket.emit("task:reorder", {
          columnId: toColumnId,
          taskId: draggedTaskId,
          toIndex
        });
      } else {
        socket.emit("task:move", {
          taskId: draggedTaskId,
          fromColumnId: draggedFromColumnId,
          toColumnId,
          toIndex
        });
      }
    });

    formNode.addEventListener("submit", (e) => {
      e.preventDefault();
      const content = inputNode.value.trim();
      if (!content) return;
      socket.emit("task:add", { columnId: column.id, content });
      inputNode.value = "";
    });

    board.appendChild(columnNode);
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [
    ...container.querySelectorAll(".task:not(.dragging)")
  ];

  let closest = { offset: Number.NEGATIVE_INFINITY, element: null };

  draggableElements.forEach((child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, element: child };
    }
  });

  return closest.element;
}
```

