## 1) `server.js`

```js
const http = require("http");
const fs = require("fs");
const path = require("path");
const WebSocket = require("ws");

const PORT = 3000;

const publicDir = path.join(__dirname, "public");

const state = {
  tasks: [
    { id: "1", title: "Set up project", status: "todo" },
    { id: "2", title: "Build drag and drop", status: "doing" },
    { id: "3", title: "Test collaboration", status: "done" }
  ]
};

const server = http.createServer((req, res) => {
  let filePath = req.url === "/" ? "/index.html" : req.url;
  filePath = path.join(publicDir, filePath);

  fs.readFile(filePath, (err, content) => {
    if (err) {
      res.writeHead(404);
      res.end("Not found");
      return;
    }

    const ext = path.extname(filePath);
    const typeMap = {
      ".html": "text/html",
      ".js": "application/javascript",
      ".css": "text/css",
      ".json": "application/json"
    };

    res.writeHead(200, {
      "Content-Type": typeMap[ext] || "text/plain"
    });
    res.end(content);
  });
});

const wss = new WebSocket.Server({ server });

function broadcast(data) {
  const msg = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(msg);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", (message) => {
    let data;
    try {
      data = JSON.parse(message);
    } catch {
      return;
    }

    if (data.type === "add_task") {
      const task = {
        id: String(Date.now()),
        title: data.title || "Untitled Task",
        status: "todo"
      };
      state.tasks.push(task);
      broadcast({ type: "state", state });
    }

    if (data.type === "move_task") {
      const task = state.tasks.find((t) => t.id === data.id);
      if (task && ["todo", "doing", "done"].includes(data.status)) {
        task.status = data.status;
        broadcast({ type: "state", state });
      }
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

