# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));
app.use(express.json());

// In-memory state
let state = {
  projects: [
    {
      id: "project-1",
      name: "Demo Project",
      columns: [
        { id: "todo", title: "To Do" },
        { id: "doing", title: "Doing" },
        { id: "done", title: "Done" }
      ],
      tasks: [
        { id: "task-1", title: "Set up project", columnId: "todo" },
        { id: "task-2", title: "Build drag and drop", columnId: "doing" },
        { id: "task-3", title: "Ship MVP", columnId: "done" }
      ]
    }
  ]
};

function broadcast(data) {
  const msg = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(msg);
    }
  });
}

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", raw => {
    try {
      const msg = JSON.parse(raw);

      if (msg.type === "addTask") {
        const project = state.projects.find(p => p.id === msg.projectId);
        if (!project) return;

        project.tasks.push({
          id: `task-${Date.now()}`,
          title: msg.title || "Untitled Task",
          columnId: msg.columnId || "todo"
        });

        broadcast({ type: "state", state });
      }

      if (msg.type === "moveTask") {
        const project = state.projects.find(p => p.id === msg.projectId);
        if (!project) return;

        const task = project.tasks.find(t => t.id === msg.taskId);
        if (!task) return;

        task.columnId = msg.columnId;
        broadcast({ type: "state", state });
      }

      if (msg.type === "renameTask") {
        const project = state.projects.find(p => p.id === msg.projectId);
        if (!project) return;

        const task = project.tasks.find(t => t.id === msg.taskId);
        if (!task) return;

        task.title = msg.title;
        broadcast({ type: "state", state });
      }

      if (msg.type === "addProject") {
        const id = `project-${Date.now()}`;
        state.projects.push({
          id,
          name: msg.name || "New Project",
          columns: [
            { id: "todo", title: "To Do" },
            { id: "doing", title: "Doing" },
            { id: "done", title: "Done" }
          ],
          tasks: []
        });

        broadcast({ type: "state", state });
      }
    } catch (err) {
      console.error("Bad message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

