    <button id="addProjectBtn">Add Project</button>
    <div class="status" id="status">Connecting...</div>
  </header>

  <div id="app">
    <div id="projectList"></div>
    <div id="boardContainer"></div>
  </div>

  <script>
    let appState = null;
    let currentProjectId = null;
    let draggedTaskId = null;

    const statusEl = document.getElementById("status");
    const projectListEl = document.getElementById("projectList");
    const boardContainerEl = document.getElementById("boardContainer");
    const newProjectNameEl = document.getElementById("newProjectName");
    const addProjectBtn = document.getElementById("addProjectBtn");

    const protocol = location.protocol === "https:" ? "wss" : "ws";
    const ws = new WebSocket(`${protocol}://${location.host}`);

    ws.onopen = () => {
      statusEl.textContent = "Connected";
    };

    ws.onclose = () => {
      statusEl.textContent = "Disconnected";
    };

    ws.onmessage = event => {
      const msg = JSON.parse(event.data);

      if (msg.type === "init" || msg.type === "state") {
        appState = msg.state;
        if (!currentProjectId && appState.projects.length) {
          currentProjectId = appState.projects[0].id;
        }
        render();
      }
    };

    addProjectBtn.onclick = () => {
      const name = newProjectNameEl.value.trim();
      if (!name) return;
      ws.send(JSON.stringify({ type: "addProject", name }));
      newProjectNameEl.value = "";
    };

    function send(data) {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(data));
      }
    }

    function render() {
      renderProjects();
      renderBoard();
    }

    function renderProjects() {
      projectListEl.innerHTML = "";
      appState.projects.forEach(project => {
        const btn = document.createElement("button");
        btn.className = "project-btn" + (project.id === currentProjectId ? " active" : "");
        btn.textContent = project.name;
        btn.onclick = () => {
          currentProjectId = project.id;
          render();
        };
        projectListEl.appendChild(btn);
      });
    }

    function renderBoard() {
      const project = appState.projects.find(p => p.id === currentProjectId);
      if (!project) {
        boardContainerEl.innerHTML = "<p>No project selected.</p>";
        return;
      }

      const board = document.createElement("div");
      board.className = "board";

      project.columns.forEach(column => {
        const colEl = document.createElement("div");
        colEl.className = "column";
        colEl.dataset.columnId = column.id;

        const title = document.createElement("h2");
        title.textContent = column.title;
        colEl.appendChild(title);

        const taskList = document.createElement("div");
        taskList.className = "task-list";

        taskList.ondragover = e => {
          e.preventDefault();
          taskList.classList.add("drop-hover");
        };

        taskList.ondragleave = () => {
          taskList.classList.remove("drop-hover");
        };

        taskList.ondrop = e => {
          e.preventDefault();
          taskList.classList.remove("drop-hover");
          if (draggedTaskId) {
            send({
              type: "moveTask",
              projectId: project.id,
              taskId: draggedTaskId,
              columnId: column.id
            });
          }
        };

        project.tasks
          .filter(task => task.columnId === column.id)
          .forEach(task => {
            const taskEl = document.createElement("div");
            taskEl.className = "task";
            taskEl.draggable = true;
            taskEl.textContent = task.title;
            taskEl.contentEditable = true;

            taskEl.ondragstart = () => {
              draggedTaskId = task.id;
            };

            taskEl.ondragend = () => {
              draggedTaskId = null;
            };

            taskEl.onblur = () => {
              const newTitle = taskEl.textContent.trim();
              if (newTitle && newTitle !== task.title) {
                send({
                  type: "renameTask",
                  projectId: project.id,
                  taskId: task.id,
                  title: newTitle
                });
              } else {
                taskEl.textContent = task.title;
              }
            };

            taskList.appendChild(taskEl);
          });

        colEl.appendChild(taskList);

        const addTaskWrap = document.createElement("div");
        addTaskWrap.className = "add-task";

        const input = document.createElement("input");
        input.placeholder = "New task";

        const btn = document.createElement("button");
        btn.textContent = "+";
        btn.onclick = () => {
          const title = input.value.trim();
          if (!title) return;
          send({
            type: "addTask",
            projectId: project.id,
            title,
            columnId: column.id
          });
          input.value = "";
        };

        addTaskWrap.appendChild(input);
        addTaskWrap.appendChild(btn);
        colEl.appendChild(addTaskWrap);

        board.appendChild(colEl);
      });

      boardContainerEl.innerHTML = "";
      boardContainerEl.appendChild(board);
    }
  </script>
