## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "1", text: "Set up project" },
      { id: "2", text: "Create task board" }
    ],
    doing: [
      { id: "3", text: "Implement drag and drop" }
    ],
    done: []
  }
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message);

      if (data.type === "add_task") {
        const { columnId, text } = data;
        if (!state.columns[columnId]) return;

        const task = {
          id: Date.now().toString() + Math.random().toString(16).slice(2),
          text
        };

        state.columns[columnId].push(task);
        broadcast({ type: "state_update", state });
      }

      if (data.type === "move_task") {
        const { taskId, fromColumn, toColumn, toIndex } = data;
        if (!state.columns[fromColumn] || !state.columns[toColumn]) return;

        const fromTasks = state.columns[fromColumn];
        const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromTasks.splice(taskIndex, 1);
        state.columns[toColumn].splice(toIndex, 0, task);

        broadcast({ type: "state_update", state });
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

