## 5) `public/app.js`

```js
const socket = new WebSocket(`ws://${location.host}`);

let appState = null;
let draggedTaskId = null;
let draggedFromColumn = null;

const taskInput = document.getElementById("taskInput");
const columnSelect = document.getElementById("columnSelect");
const addTaskBtn = document.getElementById("addTaskBtn");

socket.addEventListener("message", (event) => {
  const data = JSON.parse(event.data);

  if (data.type === "init" || data.type === "state_update") {
    appState = data.state;
    render();
  }
});

addTaskBtn.addEventListener("click", () => {
  const text = taskInput.value.trim();
  const columnId = columnSelect.value;

  if (!text) return;

  socket.send(JSON.stringify({
    type: "add_task",
    columnId,
    text
  }));

  taskInput.value = "";
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

function render() {
  ["todo", "doing", "done"].forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    appState.columns[columnId].forEach((task, index) => {
      const card = document.createElement("div");
      card.className = "task";
      card.draggable = true;
      card.textContent = task.text;
      card.dataset.taskId = task.id;
      card.dataset.columnId = columnId;
      card.dataset.index = index;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumn = columnId;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      list.appendChild(card);
    });
  });

  document.querySelectorAll(".task-list").forEach((list) => {
    list.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();

      const toColumn = list.id;
      const tasks = [...list.querySelectorAll(".task")];
      let toIndex = tasks.length;

      for (let i = 0; i < tasks.length; i++) {
        const rect = tasks[i].getBoundingClientRect();
        if (e.clientY < rect.top + rect.height / 2) {
          toIndex = i;
          break;
        }
      }

      if (!draggedTaskId || !draggedFromColumn) return;

      socket.send(JSON.stringify({
        type: "move_task",
        taskId: draggedTaskId,
        fromColumn: draggedFromColumn,
        toColumn,
        toIndex
      }));

      draggedTaskId = null;
      draggedFromColumn = null;
    });
  });
}
```

