## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "Doing",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Set up project" },
    "task-2": { id: "task-2", content: "Build drag-and-drop board" }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.use(express.static(path.join(__dirname, "public")));

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  // Send current board state to new client
  socket.emit("board:init", board);

  socket.on("task:add", ({ columnId, content }) => {
    const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    board.tasks[id] = { id, content };
    board.columns[columnId].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destColumnId, destIndex }) => {
    const sourceIds = board.columns[sourceColumnId].taskIds;
    const destIds = board.columns[destColumnId].taskIds;

    // Remove from source
    const sourceIndex = sourceIds.indexOf(taskId);
    if (sourceIndex !== -1) {
      sourceIds.splice(sourceIndex, 1);
    }

    // Insert into destination
    const insertIndex = Math.max(0, Math.min(destIndex, destIds.length));
    destIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    board.columns[columnId].taskIds = board.columns[columnId].taskIds.filter(id => id !== taskId);
    delete board.tasks[taskId];
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

