      title: 'To Do',
      taskIds: ['1', '2']
    },
    doing: {
      id: 'doing',
      title: 'Doing',
      taskIds: ['3']
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {
    '1': { id: '1', title: 'Set up project repo' },
    '2': { id: '2', title: 'Design board layout' },
    '3': { id: '3', title: 'Implement drag and drop' }
  },
  columnOrder: ['todo', 'doing', 'done']
};

app.get('/api/board', (req, res) => {
  res.json(board);
});

app.post('/api/task', (req, res) => {
  const { title, columnId } = req.body;
  if (!title || !columnId || !board.columns[columnId]) {
    return res.status(400).json({ error: 'Invalid task data' });
  }

  const id = Date.now().toString();
  board.tasks[id] = { id, title };
  board.columns[columnId].taskIds.push(id);

  io.emit('board:update', board);
  res.json(board);
});

io.on('connection', (socket) => {
  socket.emit('board:init', board);

  socket.on('task:move', ({ taskId, sourceColumnId, destColumnId, destIndex }) => {
    const sourceCol = board.columns[sourceColumnId];
    const destCol = board.columns[destColumnId];

    if (!sourceCol || !destCol || !board.tasks[taskId]) return;

    sourceCol.taskIds = sourceCol.taskIds.filter(id => id !== taskId);
    destCol.taskIds.splice(destIndex, 0, taskId);

    io.emit('board:update', board);
  });

  socket.on('task:create', ({ title, columnId }) => {
    if (!title || !columnId || !board.columns[columnId]) return;

    const id = Date.now().toString();
    board.tasks[id] = { id, title };
    board.columns[columnId].taskIds.push(id);

    io.emit('board:update', board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
