# 3. `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

const state = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", text: "Create wireframes" },
        { id: "t2", text: "Define MVP scope" }
      ]
    },
    doing: {
      id: "doing",
      title: "Doing",
      tasks: [
        { id: "t3", text: "Build drag-and-drop board" }
      ]
    },
    done: {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", text: "Set up project" }
      ]
    }
  },
  columnOrder: ["todo", "doing", "done"]
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

function findAndRemoveTask(taskId) {
  for (const colId of state.columnOrder) {
    const column = state.columns[colId];
    const index = column.tasks.findIndex(t => t.id === taskId);
    if (index !== -1) {
      return column.tasks.splice(index, 1)[0];
    }
  }
  return null;
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", (raw) => {
    let msg;
    try {
      msg = JSON.parse(raw);
    } catch {
      return;
    }

    if (msg.type === "add_task") {
      const { columnId, text } = msg;
      if (!state.columns[columnId] || !text?.trim()) return;

      state.columns[columnId].tasks.push({
        id: "t" + Date.now() + Math.random().toString(16).slice(2),
        text: text.trim()
      });

      broadcast({ type: "state", state });
    }

    if (msg.type === "move_task") {
      const { taskId, toColumnId, toIndex } = msg;
      if (!state.columns[toColumnId]) return;

      const task = findAndRemoveTask(taskId);
      if (!task) return;

      const tasks = state.columns[toColumnId].tasks;
      const safeIndex = Math.max(0, Math.min(toIndex, tasks.length));
      tasks.splice(safeIndex, 0, task);

      broadcast({ type: "state", state });
    }

    if (msg.type === "delete_task") {
      const { taskId } = msg;
      const removed = findAndRemoveTask(taskId);
      if (!removed) return;

      broadcast({ type: "state", state });
    }

    if (msg.type === "edit_task") {
      const { taskId, text } = msg;
      if (!text?.trim()) return;

      for (const colId of state.columnOrder) {
        const task = state.columns[colId].tasks.find(t => t.id === taskId);
        if (task) {
          task.text = text.trim();
          broadcast({ type: "state", state });
          return;
        }
      }
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

