  <header>Project Management Board</header>
  <div class="board" id="board"></div>

  <script>
    const board = document.getElementById("board");
    const socket = new WebSocket(`ws://${location.host}`);

    let appState = null;
    let draggedTaskId = null;

    socket.addEventListener("message", (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === "init" || msg.type === "state") {
        appState = msg.state;
        render();
      }
    });

    function send(data) {
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(JSON.stringify(data));
      }
    }

    function render() {
      if (!appState) return;
      board.innerHTML = "";

      appState.columnOrder.forEach(columnId => {
        const column = appState.columns[columnId];

        const colEl = document.createElement("div");
        colEl.className = "column";

        const title = document.createElement("h2");
        title.textContent = column.title;
        colEl.appendChild(title);

        const taskList = document.createElement("div");
        taskList.className = "task-list";

        column.tasks.forEach((task, index) => {
          const dropZone = createDropZone(column.id, index);
          taskList.appendChild(dropZone);

          const taskEl = document.createElement("div");
          taskEl.className = "task";
          taskEl.draggable = true;
          taskEl.dataset.taskId = task.id;

          taskEl.addEventListener("dragstart", () => {
            draggedTaskId = task.id;
            taskEl.classList.add("dragging");
          });

          taskEl.addEventListener("dragend", () => {
            draggedTaskId = null;
            taskEl.classList.remove("dragging");
            document.querySelectorAll(".drop-zone").forEach(z => z.classList.remove("active"));
          });

          const text = document.createElement("div");
          text.textContent = task.text;
          taskEl.appendChild(text);

          const actions = document.createElement("div");
          actions.className = "task-actions";

          const editBtn = document.createElement("button");
          editBtn.className = "small-btn";
          editBtn.textContent = "Edit";
          editBtn.onclick = () => {
            const newText = prompt("Edit task", task.text);
            if (newText !== null) {
              send({ type: "edit_task", taskId: task.id, text: newText });
            }
          };

          const deleteBtn = document.createElement("button");
          deleteBtn.className = "delete-btn";
          deleteBtn.textContent = "Delete";
          deleteBtn.onclick = () => {
            send({ type: "delete_task", taskId: task.id });
          };

          actions.appendChild(editBtn);
          actions.appendChild(deleteBtn);
          taskEl.appendChild(actions);

          taskList.appendChild(taskEl);
        });

        taskList.appendChild(createDropZone(column.id, column.tasks.length));
        colEl.appendChild(taskList);

        const addBtn = document.createElement("button");
        addBtn.className = "add-btn";
        addBtn.textContent = "+ Add Task";
        addBtn.onclick = () => {
          const text = prompt("Task title");
          if (text !== null) {
            send({ type: "add_task", columnId: column.id, text });
          }
        };

        colEl.appendChild(addBtn);
        board.appendChild(colEl);
      });
    }

    function createDropZone(columnId, index) {
      const zone = document.createElement("div");
      zone.className = "drop-zone";

      zone.addEventListener("dragover", (e) => {
        e.preventDefault();
        zone.classList.add("active");
      });

      zone.addEventListener("dragleave", () => {
        zone.classList.remove("active");
      });

      zone.addEventListener("drop", (e) => {
        e.preventDefault();
        zone.classList.remove("active");
        if (!draggedTaskId) return;
        send({
          type: "move_task",
          taskId: draggedTaskId,
          toColumnId: columnId,
          toIndex: index
        });
      });

      return zone;
    }
  </script>
</body>
