const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let state = {
  project: {
    id: "project-1",
    name: "Demo Project",
    columns: [
      { id: "todo", title: "To Do" },
      { id: "doing", title: "Doing" },
      { id: "done", title: "Done" }
    ],
    tasks: [
      { id: "task-1", title: "Set up project", columnId: "todo" },
      { id: "task-2", title: "Build UI", columnId: "doing" },
      { id: "task-3", title: "Deploy app", columnId: "done" }
    ]
  }
};

function broadcast(data) {
  const msg = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(msg);
    }
  });
}

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { title, columnId } = req.body;
  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const task = {
    id: "task-" + Date.now(),
    title,
    columnId
  };

  state.project.tasks.push(task);
  broadcast({ type: "task_created", task });
  res.json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const task = state.project.tasks.find(t => t.id === req.params.id);
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, columnId } = req.body;
  if (typeof title === "string") task.title = title;
  if (typeof columnId === "string") task.columnId = columnId;

  broadcast({ type: "task_updated", task });
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const index = state.project.tasks.findIndex(t => t.id === req.params.id);
  if (index === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [deleted] = state.project.tasks.splice(index, 1);
  broadcast({ type: "task_deleted", taskId: deleted.id });
  res.json({ ok: true });
});

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", raw => {
    try {
      const msg = JSON.parse(raw);

      if (msg.type === "move_task") {
        const task = state.project.tasks.find(t => t.id === msg.taskId);
        if (task) {
          task.columnId = msg.columnId;
          broadcast({ type: "task_updated", task });
        }
      }

      if (msg.type === "create_task") {
        const task = {
          id: "task-" + Date.now(),
          title: msg.title || "New Task",
          columnId: msg.columnId || "todo"
        };
        state.project.tasks.push(task);
        broadcast({ type: "task_created", task });
      }

      if (msg.type === "delete_task") {
        const index = state.project.tasks.findIndex(t => t.id === msg.taskId);
        if (index !== -1) {
          state.project.tasks.splice(index, 1);
          broadcast({ type: "task_deleted", taskId: msg.taskId });
        }
      }

      if (msg.type === "rename_task") {
        const task = state.project.tasks.find(t => t.id === msg.taskId);
        if (task) {
          task.title = msg.title;
          broadcast({ type: "task_updated", task });
        }
      }
    } catch (err) {
      console.error("Invalid WS message", err);
    }
  });
