## 5) `public/app.js`

```js
const board = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const newTaskTitle = document.getElementById("newTaskTitle");
const newTaskColumn = document.getElementById("newTaskColumn");
const taskTemplate = document.getElementById("taskTemplate");

let appState = null;
let ws = null;

function connectWebSocket() {
  const protocol = location.protocol === "https:" ? "wss:" : "ws:";
  ws = new WebSocket(`${protocol}//${location.host}`);

  ws.onmessage = event => {
    const msg = JSON.parse(event.data);

    if (msg.type === "init") {
      appState = msg.state;
      render();
    }

    if (msg.type === "task_created") {
      appState.project.tasks.push(msg.task);
      render();
    }

    if (msg.type === "task_updated") {
      const index = appState.project.tasks.findIndex(t => t.id === msg.task.id);
      if (index !== -1) {
        appState.project.tasks[index] = msg.task;
      } else {
        appState.project.tasks.push(msg.task);
      }
      render();
    }

    if (msg.type === "task_deleted") {
      appState.project.tasks = appState.project.tasks.filter(t => t.id !== msg.taskId);
      render();
    }
  };

  ws.onclose = () => {
    setTimeout(connectWebSocket, 1000);
  };
}

function render() {
  if (!appState) return;
  board.innerHTML = "";

  const { columns, tasks } = appState.project;

  columns.forEach(column => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = column.title;

    const taskList = document.createElement("div");
    taskList.className = "task-list";

    taskList.addEventListener("dragover", e => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", e => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData("text/plain");
      moveTask(taskId, column.id);
    });

    tasks
      .filter(task => task.columnId === column.id)
      .forEach(task => {
        const taskEl = taskTemplate.content.firstElementChild.cloneNode(true);
        taskEl.dataset.taskId = task.id;

        const titleEl = taskEl.querySelector(".task-title");
        titleEl.textContent = task.title;

        taskEl.addEventListener("dragstart", e => {
          taskEl.classList.add("dragging");
          e.dataTransfer.setData("text/plain", task.id);
        });

        taskEl.addEventListener("dragend", () => {
          taskEl.classList.remove("dragging");
        });

        taskEl.querySelector(".edit-btn").addEventListener("click", () => {
          const updatedTitle = prompt("Edit task title:", task.title);
          if (updatedTitle && updatedTitle.trim()) {
            ws.send(JSON.stringify({
              type: "rename_task",
              taskId: task.id,
              title: updatedTitle.trim()
            }));
          }
        });

        taskEl.querySelector(".delete-btn").addEventListener("click", () => {
          ws.send(JSON.stringify({
            type: "delete_task",
            taskId: task.id
          }));
        });

        taskList.appendChild(taskEl);
      });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    board.appendChild(columnEl);
  });
}

function moveTask(taskId, columnId) {
  ws.send(JSON.stringify({
    type: "move_task",
    taskId,
    columnId
  }));
}

addTaskBtn.addEventListener("click", () => {
  const title = newTaskTitle.value.trim();
  const columnId = newTaskColumn.value;

  if (!title) return;

  ws.send(JSON.stringify({
    type: "create_task",
    title,
    columnId
  }));

  newTaskTitle.value = "";
});

connectWebSocket();
```

