## `src/main.rs`

```rust
use chrono::{DateTime, Utc};
use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::sync::mpsc;
use tokio::time::{sleep, Duration};
use tracing::{error, info, warn};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub struct Instrument(pub String);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum OrderType {
    Market,
    Limit,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MarketTick {
    pub instrument: Instrument,
    pub bid: Decimal,
    pub ask: Decimal,
    pub ts: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderRequest {
    pub order_id: Uuid,
    pub instrument: Instrument,
    pub side: Side,
    pub qty: Decimal,
    pub order_type: OrderType,
    pub limit_price: Option<Decimal>,
    pub ts: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum OrderStatus {
    New,
    Accepted,
    Rejected(String),
    Filled,
    PartiallyFilled,
    Cancelled,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderUpdate {
    pub order_id: Uuid,
    pub status: OrderStatus,
    pub filled_qty: Decimal,
    pub remaining_qty: Decimal,
    pub ts: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Position {
    pub instrument: Instrument,
    pub net_qty: Decimal,
}

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Decimal,
    pub max_position_abs: Decimal,
}

#[derive(Debug, Default)]
pub struct PositionBook {
    positions: HashMap<Instrument, Decimal>,
}

impl PositionBook {
    pub fn get(&self, instrument: &Instrument) -> Decimal {
        self.positions.get(instrument).cloned().unwrap_or(Decimal::ZERO)
    }

    pub fn apply_fill(&mut self, instrument: &Instrument, side: &Side, qty: Decimal) {
        let current = self.get(instrument);
        let updated = match side {
            Side::Buy => current + qty,
            Side::Sell => current - qty,
        };
        self.positions.insert(instrument.clone(), updated);
    }
}

#[derive(Debug)]
pub enum InternalEvent {
    Market(MarketTick),
    StrategyOrder(OrderRequest),
    RiskApproved(OrderRequest),
    RiskRejected(OrderRequest, String),
    OrderUpdate(OrderUpdate),
}

pub struct MarketDataGateway {
    tx_strategy: mpsc::Sender<InternalEvent>,
}

impl MarketDataGateway {
    pub fn new(tx_strategy: mpsc::Sender<InternalEvent>) -> Self {
        Self { tx_strategy }
    }

    pub async fn run(self) {
        let instrument = Instrument("BTC-USD".to_string());

        loop {
            let tick = MarketTick {
                instrument: instrument.clone(),
                bid: Decimal::new(30000, 0),
                ask: Decimal::new(30010, 0),
                ts: Utc::now(),
            };

            if let Err(e) = self.tx_strategy.send(InternalEvent::Market(tick)).await {
                error!("market data send failed: {}", e);
                break;
            }

            sleep(Duration::from_millis(100)).await;
        }
    }
}

pub struct StrategyEngine {
    rx: mpsc::Receiver<InternalEvent>,
    tx_risk: mpsc::Sender<InternalEvent>,
}

impl StrategyEngine {
    pub fn new(
        rx: mpsc::Receiver<InternalEvent>,
        tx_risk: mpsc::Sender<InternalEvent>,
    ) -> Self {
        Self { rx, tx_risk }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                InternalEvent::Market(tick) => {
                    let spread = tick.ask - tick.bid;

                    if spread >= Decimal::new(5, 0) {
                        let order = OrderRequest {
                            order_id: Uuid::new_v4(),
                            instrument: tick.instrument,
                            side: Side::Buy,
                            qty: Decimal::new(1, 0),
                            order_type: OrderType::Limit,
                            limit_price: Some(tick.bid),
                            ts: Utc::now(),
                        };

                        if let Err(e) = self.tx_risk.send(InternalEvent::StrategyOrder(order)).await {
                            error!("strategy -> risk send failed: {}", e);
                            break;
                        }
                    }
                }
                _ => {}
            }
        }
    }
}

pub struct RiskEngine {
    rx: mpsc::Receiver<InternalEvent>,
    tx_oms: mpsc::Sender<InternalEvent>,
    limits: RiskLimits,
    positions: PositionBook,
}

impl RiskEngine {
    pub fn new(
        rx: mpsc::Receiver<InternalEvent>,
        tx_oms: mpsc::Sender<InternalEvent>,
        limits: RiskLimits,
    ) -> Self {
        Self {
            rx,
            tx_oms,
            limits,
            positions: PositionBook::default(),
        }
    }

    fn check_order(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty > self.limits.max_order_qty {
            return Err("max order qty exceeded".to_string());
        }

        let current_pos = self.positions.get(&order.instrument);
        let projected = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected.abs() > self.limits.max_position_abs {
            return Err("max position exceeded".to_string());
        }

        Ok(())
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                InternalEvent::StrategyOrder(order) => {
                    match self.check_order(&order) {
                        Ok(_) => {
                            if let Err(e) = self.tx_oms.send(InternalEvent::RiskApproved(order)).await {
                                error!("risk -> oms send failed: {}", e);
                                break;
                            }
                        }
                        Err(reason) => {
                            warn!("order rejected by risk: {}", reason);
                            if let Err(e) = self.tx_oms.send(InternalEvent::RiskRejected(order, reason)).await {
                                error!("risk rejection send failed: {}", e);
                                break;
                            }
                        }
                    }
                }
                InternalEvent::OrderUpdate(update) => {
                    info!("risk received order update: {:?}", update);
                    // In a real system, correlate order_id -> original order and apply fills.
                }
                _ => {}
            }
        }
    }
}

pub struct Oms {
    rx: mpsc::Receiver<InternalEvent>,
    tx_exec: mpsc::Sender<InternalEvent>,
    orders: HashMap<Uuid, OrderStatus>,
}

impl Oms {
    pub fn new(
        rx: mpsc::Receiver<InternalEvent>,
        tx_exec: mpsc::Sender<InternalEvent>,
    ) -> Self {
        Self {
            rx,
            tx_exec,
            orders: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                InternalEvent::RiskApproved(order) => {
                    self.orders.insert(order.order_id, OrderStatus::New);

                    if let Err(e) = self.tx_exec.send(InternalEvent::RiskApproved(order)).await {
                        error!("oms -> exec send failed: {}", e);
                        break;
                    }
                }
                InternalEvent::RiskRejected(order, reason) => {
                    self.orders
                        .insert(order.order_id, OrderStatus::Rejected(reason.clone()));
                    warn!("OMS marked order {} as rejected: {}", order.order_id, reason);
                }
                InternalEvent::OrderUpdate(update) => {
                    self.orders.insert(update.order_id, update.status.clone());
                    info!("OMS updated order {} -> {:?}", update.order_id, update.status);
                }
                _ => {}
            }
        }
    }
}

pub struct ExecutionGateway {
    rx: mpsc::Receiver<InternalEvent>,
    tx_oms: mpsc::Sender<InternalEvent>,
}

impl ExecutionGateway {
    pub fn new(
        rx: mpsc::Receiver<InternalEvent>,
        tx_oms: mpsc::Sender<InternalEvent>,
    ) -> Self {
        Self { rx, tx_oms }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                InternalEvent::RiskApproved(order) => {
                    let accepted = OrderUpdate {
                        order_id: order.order_id,
                        status: OrderStatus::Accepted,
                        filled_qty: Decimal::ZERO,
                        remaining_qty: order.qty,
                        ts: Utc::now(),
                    };

                    if let Err(e) = self.tx_oms.send(InternalEvent::OrderUpdate(accepted)).await {
                        error!("exec -> oms accepted send failed: {}", e);
                        break;
                    }

                    let filled = OrderUpdate {
                        order_id: order.order_id,
                        status: OrderStatus::Filled,
                        filled_qty: order.qty,
                        remaining_qty: Decimal::ZERO,
                        ts: Utc::now(),
                    };

                    if let Err(e) = self.tx_oms.send(InternalEvent::OrderUpdate(filled)).await {
                        error!("exec -> oms filled send failed: {}", e);
                        break;
                    }
                }
                _ => {}
            }
        }
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (tx_strategy, rx_strategy) = mpsc::channel(1024);
    let (tx_risk, rx_risk) = mpsc::channel(1024);
    let (tx_oms, rx_oms) = mpsc::channel(1024);
    let (tx_exec, rx_exec) = mpsc::channel(1024);

    let md = MarketDataGateway::new(tx_strategy);
    let strategy = StrategyEngine::new(rx_strategy, tx_risk);
    let risk = RiskEngine::new(
        rx_risk,
        tx_oms.clone(),
        RiskLimits {
            max_order_qty: Decimal::new(10, 0),
            max_position_abs: Decimal::new(100, 0),
        },
    );
    let oms = Oms::new(rx_oms, tx_exec);
    let exec = ExecutionGateway::new(rx_exec, tx_oms);

    tokio::spawn(md.run());
    tokio::spawn(strategy.run());
    tokio::spawn(risk.run());
    tokio::spawn(oms.run());
    tokio::spawn(exec.run());

    loop {
        sleep(Duration::from_secs(60)).await;
    }
}
```

