# 6. Internal event bus

For an initial version, use channels.  
Later, you can replace this with:

- lock-free ring buffers
- shared memory queues
- Aeron / NATS / Kafka for distributed scale
- custom binary transport

## `src/bus.rs`

```rust
use tokio::sync::mpsc;

use crate::types::{ExecutionReport, MarketTick, OrderRequest, Signal};

#[derive(Clone)]
pub struct Bus {
    pub market_tx: mpsc::Sender<MarketTick>,
    pub signal_tx: mpsc::Sender<Signal>,
    pub order_tx: mpsc::Sender<OrderRequest>,
    pub exec_tx: mpsc::Sender<ExecutionReport>,
}

pub struct BusReceivers {
    pub market_rx: mpsc::Receiver<MarketTick>,
    pub signal_rx: mpsc::Receiver<Signal>,
    pub order_rx: mpsc::Receiver<OrderRequest>,
    pub exec_rx: mpsc::Receiver<ExecutionReport>,
}

pub fn create_bus(buffer: usize) -> (Bus, BusReceivers) {
    let (market_tx, market_rx) = mpsc::channel(buffer);
    let (signal_tx, signal_rx) = mpsc::channel(buffer);
    let (order_tx, order_rx) = mpsc::channel(buffer);
    let (exec_tx, exec_rx) = mpsc::channel(buffer);

    (
        Bus {
            market_tx,
            signal_tx,
            order_tx,
            exec_tx,
        },
        BusReceivers {
            market_rx,
            signal_rx,
            order_rx,
            exec_rx,
        },
    )
}
```

