# 7. Market data component

This simulates market data. In production, this would connect to exchange feeds.

## `src/market_data.rs`

```rust
use rust_decimal::Decimal;
use tokio::time::{sleep, Duration};
use tracing::info;

use crate::types::MarketTick;

pub async fn run_market_data_simulator(
    market_tx: tokio::sync::mpsc::Sender<MarketTick>,
) {
    let mut px = Decimal::new(10000, 2); // 100.00

    loop {
        let tick = MarketTick {
            symbol: "AAPL".to_string(),
            bid: px - Decimal::new(1, 2),
            ask: px + Decimal::new(1, 2),
            last: px,
            ts_nanos: now_nanos(),
        };

        if market_tx.send(tick).await.is_err() {
            info!("market data receiver dropped");
            break;
        }

        px += Decimal::new(1, 2);
        sleep(Duration::from_millis(50)).await;
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

