# 8. Strategy engine

This example strategy buys when price is below a threshold and sells above a threshold.

## `src/strategy.rs`

```rust
use rust_decimal::Decimal;
use tokio::sync::mpsc::{Receiver, Sender};
use tracing::info;

use crate::types::{MarketTick, Side, Signal};

pub async fn run_strategy(
    mut market_rx: Receiver<MarketTick>,
    signal_tx: Sender<Signal>,
) {
    let buy_threshold = Decimal::new(10050, 2);  // 100.50
    let sell_threshold = Decimal::new(10100, 2); // 101.00

    while let Some(tick) = market_rx.recv().await {
        let signal = if tick.last < buy_threshold {
            Some(Signal {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: Decimal::new(10, 0),
                price: Some(tick.ask),
                strategy_id: "mean_reversion_v1".to_string(),
                ts_nanos: now_nanos(),
            })
        } else if tick.last > sell_threshold {
            Some(Signal {
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: Decimal::new(10, 0),
                price: Some(tick.bid),
                strategy_id: "mean_reversion_v1".to_string(),
                ts_nanos: now_nanos(),
            })
        } else {
            None
        };

        if let Some(signal) = signal {
            if signal_tx.send(signal).await.is_err() {
                info!("signal receiver dropped");
                break;
            }
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

