# 9. Risk engine

This is where you enforce:

- max order size
- max position
- fat-finger checks
- notional limits
- symbol restrictions
- account restrictions

## `src/risk.rs`

```rust
use rust_decimal::Decimal;
use tokio::sync::mpsc::{Receiver, Sender};
use tracing::{info, warn};
use uuid::Uuid;

use crate::types::{OrderRequest, OrderType, Signal, TimeInForce};

pub async fn run_risk_engine(
    mut signal_rx: Receiver<Signal>,
    order_tx: Sender<OrderRequest>,
) {
    let max_order_qty = Decimal::new(1000, 0);

    while let Some(signal) = signal_rx.recv().await {
        if signal.qty > max_order_qty {
            warn!("risk reject: qty too large {:?}", signal);
            continue;
        }

        let order = OrderRequest {
            order_id: Uuid::new_v4(),
            symbol: signal.symbol,
            side: signal.side,
            qty: signal.qty,
            order_type: if signal.price.is_some() {
                OrderType::Limit
            } else {
                OrderType::Market
            },
            price: signal.price,
            tif: TimeInForce::IOC,
            strategy_id: signal.strategy_id,
            ts_nanos: now_nanos(),
        };

        if order_tx.send(order).await.is_err() {
            info!("order receiver dropped");
            break;
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

