# 10. OMS

The OMS tracks orders and execution reports.

## `src/oms.rs`

```rust
use std::collections::HashMap;

use tokio::sync::mpsc::{Receiver, Sender};
use tracing::{info, warn};

use crate::types::{ExecutionReport, OrderId, OrderRequest, OrderStatus};

pub async fn run_oms(
    mut order_rx: Receiver<OrderRequest>,
    mut exec_rx: Receiver<ExecutionReport>,
    exec_forward_tx: Sender<OrderRequest>,
) {
    let mut orders: HashMap<OrderId, OrderStatus> = HashMap::new();

    loop {
        tokio::select! {
            maybe_order = order_rx.recv() => {
                match maybe_order {
                    Some(order) => {
                        orders.insert(order.order_id, OrderStatus::PendingNew);
                        if exec_forward_tx.send(order).await.is_err() {
                            warn!("execution gateway unavailable");
                            break;
                        }
                    }
                    None => {
                        info!("order_rx closed");
                        break;
                    }
                }
            }
            maybe_exec = exec_rx.recv() => {
                match maybe_exec {
                    Some(report) => {
                        orders.insert(report.order_id, report.status.clone());
                        info!("execution update: {:?}", report);
                    }
                    None => {
                        info!("exec_rx closed");
                        break;
                    }
                }
            }
        }
    }
}
```

