# 11. Execution gateway

This simulates exchange execution. In production, this is where FIX/OUCH/ITCH/native APIs go.

## `src/execution.rs`

```rust
use rust_decimal::Decimal;
use tokio::sync::mpsc::{Receiver, Sender};
use tokio::time::{sleep, Duration};
use tracing::info;

use crate::types::{ExecutionReport, OrderRequest, OrderStatus};

pub async fn run_execution_gateway(
    mut order_rx: Receiver<OrderRequest>,
    exec_tx: Sender<ExecutionReport>,
) {
    while let Some(order) = order_rx.recv().await {
        sleep(Duration::from_millis(5)).await;

        let report = ExecutionReport {
            order_id: order.order_id,
            symbol: order.symbol,
            status: OrderStatus::Filled,
            filled_qty: order.qty,
            remaining_qty: Decimal::ZERO,
            avg_price: order.price,
            reason: None,
            ts_nanos: now_nanos(),
        };

        if exec_tx.send(report).await.is_err() {
            info!("exec report receiver dropped");
            break;
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

