# 13. Main application wiring

There’s one subtle issue: a single Tokio mpsc receiver cannot be consumed by multiple components.  
So for clean fan-out, we’ll wire separate channels explicitly.

## `src/main.rs`

```rust
mod bus;
mod execution;
mod market_data;
mod oms;
mod risk;
mod strategy;
mod telemetry;
mod types;

use tokio::sync::mpsc;

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() {
    telemetry::init_tracing();

    let (market_tx, market_rx_strategy) = mpsc::channel(1024);
    let (signal_tx, signal_rx_risk) = mpsc::channel(1024);
    let (order_tx_oms, order_rx_oms) = mpsc::channel(1024);
    let (order_tx_exec, order_rx_exec) = mpsc::channel(1024);
    let (exec_tx_oms, exec_rx_oms) = mpsc::channel(1024);

    let md_handle = tokio::spawn(market_data::run_market_data_simulator(market_tx));
    let strategy_handle = tokio::spawn(strategy::run_strategy(market_rx_strategy, signal_tx));
    let risk_handle = tokio::spawn(risk::run_risk_engine(signal_rx_risk, order_tx_oms));
    let oms_handle = tokio::spawn(oms::run_oms(order_rx_oms, exec_rx_oms, order_tx_exec));
    let exec_handle = tokio::spawn(execution::run_execution_gateway(order_rx_exec, exec_tx_oms));

    let _ = tokio::join!(md_handle, strategy_handle, risk_handle, oms_handle, exec_handle);
}
```

