use crate::types::MarketTick;
use crossbeam::channel::Sender;
use rand::Rng;
use std::thread;
use std::time::{Duration, SystemTime};

pub struct MockMarketDataFeed {
    pub symbol: String,
    pub tx: Sender<MarketTick>,
}

impl MockMarketDataFeed {
    pub fn start(self) {
        thread::spawn(move || {
            let mut rng = rand::thread_rng();
            let mut mid = 100.0;

            loop {
                let delta: f64 = rng.gen_range(-0.05..0.05);
                mid += delta;

                let spread = 0.02;
                let tick = MarketTick {
                    symbol: self.symbol.clone(),
                    bid: mid - spread / 2.0,
                    ask: mid + spread / 2.0,
                    ts: SystemTime::now(),
                };

                if self.tx.send(tick).is_err() {
                    break;
                }

                thread::sleep(Duration::from_millis(10));
            }
        });
    }
}
