pub trait Strategy: Send {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest>;
    fn id(&self) -> &str;
}

pub struct MeanReversionStrategy {
    id: String,
    last_mid: Option<f64>,
    threshold: f64,
    next_order_id: u64,
    order_qty: u64,
}

impl MeanReversionStrategy {
    pub fn new(id: impl Into<String>, threshold: f64, order_qty: u64) -> Self {
        Self {
            id: id.into(),
            last_mid: None,
            threshold,
            next_order_id: 1,
            order_qty,
        }
    }
}

impl Strategy for MeanReversionStrategy {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest> {
        let mid = (tick.bid + tick.ask) / 2.0;

        let order = if let Some(last_mid) = self.last_mid {
            let diff = mid - last_mid;

            if diff < -self.threshold {
                Some(OrderRequest {
                    id: self.next_order_id,
                    symbol: tick.symbol.clone(),
                    side: Side::Buy,
                    qty: self.order_qty,
                    order_type: OrderType::Market,
                    ts: SystemTime::now(),
                    strategy_id: self.id.clone(),
                })
            } else if diff > self.threshold {
                Some(OrderRequest {
                    id: self.next_order_id,
                    symbol: tick.symbol.clone(),
                    side: Side::Sell,
                    qty: self.order_qty,
                    order_type: OrderType::Market,
                    ts: SystemTime::now(),
                    strategy_id: self.id.clone(),
                })
            } else {
                None
            }
        } else {
            None
        };

        self.last_mid = Some(mid);

        if order.is_some() {
            self.next_order_id += 1;
        }

        order
    }

    fn id(&self) -> &str {
        &self.id
    }
}
