use crate::types::{OrderRequest, Side};
use std::collections::HashMap;

pub struct RiskEngine {
    max_order_qty: u64,
    max_abs_position: i64,
    positions: HashMap<String, i64>,
}

impl RiskEngine {
    pub fn new(max_order_qty: u64, max_abs_position: i64) -> Self {
        Self {
            max_order_qty,
            max_abs_position,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty == 0 {
            return Err("order qty cannot be zero".into());
        }

        if order.qty > self.max_order_qty {
            return Err(format!(
                "order qty {} exceeds max {}",
                order.qty, self.max_order_qty
            ));
        }

        let current = *self.positions.get(&order.symbol).unwrap_or(&0);
        let projected = match order.side {
            Side::Buy => current + order.qty as i64,
            Side::Sell => current - order.qty as i64,
        };

        if projected.abs() > self.max_abs_position {
            return Err(format!(
                "projected position {} exceeds max abs position {}",
                projected, self.max_abs_position
            ));
        }

        Ok(())
    }

    pub fn apply_fill(&mut self, symbol: &str, side: &Side, qty: u64) {
        let pos = self.positions.entry(symbol.to_string()).or_insert(0);
        match side {
            Side::Buy => *pos += qty as i64,
            Side::Sell => *pos -= qty as i64,
        }
    }
}
