# src/engine.rs

```rust
use crate::execution::ExecutionVenue;
use crate::risk::RiskEngine;
use crate::strategy::Strategy;
use crate::types::{ExecutionReport, MarketTick, OrderRequest, OrderStatus};
use crossbeam::channel::{Receiver, Sender};
use tracing::{error, info};

pub struct TradingEngine<S: Strategy, E: ExecutionVenue> {
    pub strategy: S,
    pub risk: RiskEngine,
    pub venue: E,
    pub market_data_rx: Receiver<MarketTick>,
    pub exec_report_tx: Sender<ExecutionReport>,
}

impl<S: Strategy, E: ExecutionVenue> TradingEngine<S, E> {
    pub fn run(&mut self) {
        while let Ok(tick) = self.market_data_rx.recv() {
            if let Some(order) = self.strategy.on_tick(&tick) {
                self.handle_order(order);
            }
        }
    }

    fn handle_order(&mut self, order: OrderRequest) {
        match self.risk.check_order(&order) {
            Ok(()) => {
                info!("order accepted: {:?}", order);
                let report = self.venue.send_order(&order);

                if let OrderStatus::Filled { fill_qty, .. } = &report.status {
                    self.risk.apply_fill(&order.symbol, &order.side, *fill_qty);
                }

                let _ = self.exec_report_tx.send(report);
            }
            Err(reason) => {
                error!("order rejected: {} {:?}", reason, order);
                let report = ExecutionReport {
                    order_id: order.id,
                    symbol: order.symbol.clone(),
                    status: OrderStatus::Rejected(reason),
                    ts: std::time::SystemTime::now(),
                };
                let _ = self.exec_report_tx.send(report);
            }
        }
    }
}
