use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;
use thiserror::Error;
use tokio::sync::{mpsc, RwLock};
use tokio::time::{sleep, Duration};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MarketTick {
    pub symbol: String,
    pub bid: f64,
    pub ask: f64,
    pub last: f64,
    pub ts_nanos: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum OrderType {
    Market,
    Limit,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderRequest {
    pub id: u64,
    pub symbol: String,
    pub side: Side,
    pub qty: f64,
    pub order_type: OrderType,
    pub price: Option<f64>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FillEvent {
    pub order_id: u64,
    pub symbol: String,
    pub filled_qty: f64,
    pub fill_price: f64,
    pub ts_nanos: u64,
}

#[derive(Debug, Clone)]
pub struct Position {
    pub symbol: String,
    pub qty: f64,
    pub avg_price: f64,
}

#[derive(Debug, Error)]
pub enum TradingError {
    #[error("risk rejected order: {0}")]
    RiskRejected(String),

    #[error("execution error: {0}")]
    ExecutionError(String),
}

#[async_trait]
pub trait MarketDataFeed: Send + Sync {
    async fn run(&self, tx: mpsc::Sender<MarketTick>);
}

#[async_trait]
pub trait Strategy: Send + Sync {
    async fn on_tick(&self, tick: MarketTick) -> Option<OrderRequest>;
}

#[async_trait]
pub trait RiskManager: Send + Sync {
    async fn check_order(&self, order: &OrderRequest) -> Result<(), TradingError>;
    async fn on_fill(&self, fill: &FillEvent);
}

#[async_trait]
pub trait ExecutionGateway: Send + Sync {
    async fn send_order(&self, order: OrderRequest) -> Result<FillEvent, TradingError>;
}

pub struct SimulatedMarketDataFeed {
    pub symbol: String,
}

#[async_trait]
impl MarketDataFeed for SimulatedMarketDataFeed {
    async fn run(&self, tx: mpsc::Sender<MarketTick>) {
        let mut px = 100.0;
        loop {
            px += 0.01;
            let tick = MarketTick {
                symbol: self.symbol.clone(),
                bid: px - 0.01,
                ask: px + 0.01,
                last: px,
                ts_nanos: now_nanos(),
            };

            if tx.send(tick).await.is_err() {
                break;
            }

            sleep(Duration::from_millis(10)).await;
        }
    }
}

pub struct MeanReversionStrategy {
    pub threshold: f64,
    pub order_size: f64,
    pub last_price: Arc<RwLock<HashMap<String, f64>>>,
    pub next_order_id: Arc<RwLock<u64>>,
}

impl MeanReversionStrategy {
    pub fn new(threshold: f64, order_size: f64) -> Self {
        Self {
            threshold,
            order_size,
            last_price: Arc::new(RwLock::new(HashMap::new())),
            next_order_id: Arc::new(RwLock::new(1)),
        }
    }

    async fn gen_order_id(&self) -> u64 {
        let mut guard = self.next_order_id.write().await;
        let id = *guard;
        *guard += 1;
        id
    }
}

#[async_trait]
impl Strategy for MeanReversionStrategy {
    async fn on_tick(&self, tick: MarketTick) -> Option<OrderRequest> {
        let mut prices = self.last_price.write().await;
        let prev = prices.insert(tick.symbol.clone(), tick.last);

        if let Some(prev_px) = prev {
            let diff = tick.last - prev_px;
            if diff.abs() >= self.threshold {
                let side = if diff < 0.0 { Side::Buy } else { Side::Sell };
                let order_id = self.gen_order_id().await;
                return Some(OrderRequest {
                    id: order_id,
                    symbol: tick.symbol,
                    side,
                    qty: self.order_size,
                    order_type: OrderType::Market,
                    price: None,
                });
            }
        }

        None
    }
}

pub struct BasicRiskManager {
    pub max_order_qty: f64,
    pub max_position_abs: f64,
    pub positions: Arc<RwLock<HashMap<String, Position>>>,
}

impl BasicRiskManager {
    pub fn new(max_order_qty: f64, max_position_abs: f64) -> Self {
        Self {
            max_order_qty,
            max_position_abs,
            positions: Arc::new(RwLock::new(HashMap::new())),
        }
    }
}

#[async_trait]
impl RiskManager for BasicRiskManager {
    async fn check_order(&self, order: &OrderRequest) -> Result<(), TradingError> {
        if order.qty > self.max_order_qty {
            return Err(TradingError::RiskRejected(format!(
                "order qty {} exceeds max {}",
                order.qty, self.max_order_qty
            )));
        }

        let positions = self.positions.read().await;
        let current_qty = positions
            .get(&order.symbol)
            .map(|p| p.qty)
            .unwrap_or(0.0);

        let projected = match order.side {
            Side::Buy => current_qty + order.qty,
            Side::Sell => current_qty - order.qty,
        };

        if projected.abs() > self.max_position_abs {
            return Err(TradingError::RiskRejected(format!(
                "projected position {} exceeds max {}",
                projected, self.max_position_abs
            )));
        }

        Ok(())
    }

    async fn on_fill(&self, fill: &FillEvent) {
        let mut positions = self.positions.write().await;
        let pos = positions.entry(fill.symbol.clone()).or_insert(Position {
            symbol: fill.symbol.clone(),
            qty: 0.0,
            avg_price: 0.0,
        });

        let old_qty = pos.qty;
        let new_qty = old_qty + fill.filled_qty;
        if new_qty.abs() > f64::EPSILON {
            pos.avg_price = ((pos.avg_price * old_qty) + (fill.fill_price * fill.filled_qty))
                / new_qty;
        } else {
            pos.avg_price = 0.0;
        }
        pos.qty = new_qty;
    }
}

pub struct SimulatedExecutionGateway;

#[async_trait]
impl ExecutionGateway for SimulatedExecutionGateway {
    async fn send_order(&self, order: OrderRequest) -> Result<FillEvent, TradingError> {
        let fill_price = order.price.unwrap_or(100.0);
        let signed_qty = match order.side {
            Side::Buy => order.qty,
            Side::Sell => -order.qty,
        };

        Ok(FillEvent {
            order_id: order.id,
            symbol: order.symbol,
            filled_qty: signed_qty,
            fill_price,
            ts_nanos: now_nanos(),
        })
    }
}

pub struct TradingEngine<S, R, E>
where
    S: Strategy + 'static,
    R: RiskManager + 'static,
    E: ExecutionGateway + 'static,
{
    pub strategy: Arc<S>,
    pub risk: Arc<R>,
    pub execution: Arc<E>,
}

impl<S, R, E> TradingEngine<S, R, E>
where
    S: Strategy + 'static,
    R: RiskManager + 'static,
    E: ExecutionGateway + 'static,
{
    pub fn new(strategy: Arc<S>, risk: Arc<R>, execution: Arc<E>) -> Self {
        Self {
            strategy,
            risk,
            execution,
        }
    }

    pub async fn run(&self, mut market_rx: mpsc::Receiver<MarketTick>) {
        while let Some(tick) = market_rx.recv().await {
            if let Some(order) = self.strategy.on_tick(tick).await {
                match self.risk.check_order(&order).await {
                    Ok(()) => match self.execution.send_order(order).await {
                        Ok(fill) => {
                            self.risk.on_fill(&fill).await;
                            println!("FILL: {:?}", fill);
                        }
                        Err(e) => {
                            eprintln!("Execution failed: {}", e);
                        }
                    },
                    Err(e) => {
                        eprintln!("Risk rejected order: {}", e);
                    }
                }
            }
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    dur.as_nanos() as u64
}

#[tokio::main]
async fn main() {
    let (market_tx, market_rx) = mpsc::channel(1024);

    let feed = Arc::new(SimulatedMarketDataFeed {
        symbol: "AAPL".to_string(),
    });

    let strategy = Arc::new(MeanReversionStrategy::new(0.05, 10.0));
    let risk = Arc::new(BasicRiskManager::new(100.0, 1000.0));
    let execution = Arc::new(SimulatedExecutionGateway);

    let engine = TradingEngine::new(strategy, risk, execution);

    let feed_task = {
        let tx = market_tx.clone();
        let feed = feed.clone();
        tokio::spawn(async move {
            feed.run(tx).await;
        })
    };

    let engine_task = tokio::spawn(async move {
        engine.run(market_rx).await;
    });

    let _ = tokio::join!(feed_task, engine_task);
}
