use crate::types::{MarketEvent, Quote};
use crossbeam::channel::Sender;
use rust_decimal::Decimal;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tracing::info;

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

pub struct MarketDataGateway {
    tx: Sender<MarketEvent>,
}

impl MarketDataGateway {
    pub fn new(tx: Sender<MarketEvent>) -> Self {
        Self { tx }
    }

    pub fn start(self) {
        thread::spawn(move || {
            info!("market data gateway started");

            let mut px = Decimal::new(10000, 2); // 100.00

            loop {
                let quote = Quote {
                    instrument_id: 1,
                    bid: px,
                    ask: px + Decimal::new(1, 1), // +0.1
                    bid_size: Decimal::new(10, 0),
                    ask_size: Decimal::new(12, 0),
                    ts_nanos: now_nanos(),
                };

                if self.tx.send(MarketEvent::Quote(quote)).is_err() {
                    break;
                }

                px += Decimal::new(1, 2); // +0.01
                thread::sleep(Duration::from_millis(10));
            }
        });
    }
}
```

