# 8. Strategy engine

This sample strategy:
- buys when spread is small
- sells when spread is wide

## `src/strategy.rs`

```rust
use crate::types::{
    MarketEvent, NewOrderRequest, OrderType, Side, TimeInForce,
};
use crossbeam::channel::{Receiver, Sender};
use rust_decimal::Decimal;
use tracing::{debug, info};

pub struct StrategyEngine {
    market_rx: Receiver<MarketEvent>,
    order_tx: Sender<NewOrderRequest>,
    strategy_id: u64,
}

impl StrategyEngine {
    pub fn new(
        market_rx: Receiver<MarketEvent>,
        order_tx: Sender<NewOrderRequest>,
        strategy_id: u64,
    ) -> Self {
        Self {
            market_rx,
            order_tx,
            strategy_id,
        }
    }

    pub fn start(self) {
        std::thread::spawn(move || {
            info!("strategy engine started");

            while let Ok(event) = self.market_rx.recv() {
                if let MarketEvent::Quote(q) = event {
                    let spread = q.ask - q.bid;

                    let side = if spread <= Decimal::new(1, 1) {
                        Some(Side::Buy)
                    } else if spread >= Decimal::new(5, 1) {
                        Some(Side::Sell)
                    } else {
                        None
                    };

                    if let Some(side) = side {
                        let req = NewOrderRequest {
                            strategy_id: self.strategy_id,
                            instrument_id: q.instrument_id,
                            side,
                            qty: Decimal::new(1, 0),
                            order_type: OrderType::Limit,
                            limit_price: Some(match side {
                                Side::Buy => q.bid,
                                Side::Sell => q.ask,
                            }),
                            tif: TimeInForce::IOC,
                        };

                        debug!("strategy generated order: {:?}", req);

                        if self.order_tx.send(req).is_err() {
                            break;
                        }
                    }
                }
            }
        });
    }
}
```

