# 9. Risk engine

The risk engine checks:
- max order quantity
- max position by instrument

## `src/risk.rs`

```rust
use crate::types::{NewOrderRequest, Side};
use crossbeam::channel::{Receiver, Sender};
use dashmap::DashMap;
use rust_decimal::Decimal;
use tracing::{info, warn};

pub struct RiskEngine {
    order_rx: Receiver<NewOrderRequest>,
    approved_tx: Sender<NewOrderRequest>,
    positions: DashMap<u64, Decimal>,
    max_order_qty: Decimal,
    max_abs_position: Decimal,
}

impl RiskEngine {
    pub fn new(
        order_rx: Receiver<NewOrderRequest>,
        approved_tx: Sender<NewOrderRequest>,
        max_order_qty: Decimal,
        max_abs_position: Decimal,
    ) -> Self {
        Self {
            order_rx,
            approved_tx,
            positions: DashMap::new(),
            max_order_qty,
            max_abs_position,
        }
    }

    fn would_breach_position(&self, req: &NewOrderRequest) -> bool {
        let current = self
            .positions
            .get(&req.instrument_id)
            .map(|v| *v)
            .unwrap_or(Decimal::ZERO);

        let delta = match req.side {
            Side::Buy => req.qty,
            Side::Sell => -req.qty,
        };

        let projected = current + delta;
        projected.abs() > self.max_abs_position
    }

    pub fn start(self) {
        std::thread::spawn(move || {
            info!("risk engine started");

            while let Ok(req) = self.order_rx.recv() {
                if req.qty > self.max_order_qty {
                    warn!("risk rejected order: qty too large {:?}", req);
                    continue;
                }

                if self.would_breach_position(&req) {
                    warn!("risk rejected order: position breach {:?}", req);
                    continue;
                }

                if self.approved_tx.send(req).is_err() {
                    break;
                }
            }
        });
    }
}
```

Note: in production, risk should update based on:
- fills
- cancels
- open order exposure
- per-strategy limits
- kill switch
- notional limits
- fat-finger checks
- price collars

