use crate::types::{NewOrderRequest, Order, OrderStatus};
use crossbeam::channel::{Receiver, Sender};
use dashmap::DashMap;
use tracing::info;
use uuid::Uuid;

pub struct Oms {
    approved_rx: Receiver<NewOrderRequest>,
    exec_tx: Sender<Order>,
    orders: DashMap<Uuid, OrderStatus>,
}

impl Oms {
    pub fn new(
        approved_rx: Receiver<NewOrderRequest>,
        exec_tx: Sender<Order>,
    ) -> Self {
        Self {
            approved_rx,
            exec_tx,
            orders: DashMap::new(),
        }
    }

    pub fn start(self) {
        std::thread::spawn(move || {
            info!("OMS started");

            while let Ok(req) = self.approved_rx.recv() {
                let order = Order {
                    order_id: Uuid::new_v4(),
                    strategy_id: req.strategy_id,
                    instrument_id: req.instrument_id,
                    side: req.side,
                    qty: req.qty,
                    order_type: req.order_type,
                    limit_price: req.limit_price,
                    tif: req.tif,
                };

                self.orders.insert(order.order_id, OrderStatus::PendingNew);

                if self.exec_tx.send(order).is_err() {
                    break;
                }
            }
        });
    }
}
