# 11. Execution gateway

This simulates an exchange:
- immediately acknowledges
- immediately fills

## `src/execution.rs`

```rust
use crate::types::{ExecutionReport, Order, OrderStatus};
use crossbeam::channel::{Receiver, Sender};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH};
use tracing::info;

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

pub struct ExecutionGateway {
    order_rx: Receiver<Order>,
    report_tx: Sender<ExecutionReport>,
}

impl ExecutionGateway {
    pub fn new(order_rx: Receiver<Order>, report_tx: Sender<ExecutionReport>) -> Self {
        Self { order_rx, report_tx }
    }

    pub fn start(self) {
        thread::spawn(move || {
            info!("execution gateway started");

            while let Ok(order) = self.order_rx.recv() {
                let ack = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::New,
                    filled_qty: Default::default(),
                    avg_price: None,
                    ts_nanos: now_nanos(),
                };

                if self.report_tx.send(ack).is_err() {
                    break;
                }

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Filled,
                    filled_qty: order.qty,
                    avg_price: order.limit_price,
                    ts_nanos: now_nanos(),
                };

                if self.report_tx.send(fill).is_err() {
                    break;
                }
            }
        });
    }
}
```

