    pub fn new(report_rx: Receiver<ExecutionReport>) -> Self {
        Self {
            report_rx,
            orders: DashMap::new(),
        }
    }

    pub fn start(self) {
        std::thread::spawn(move || {
            info!("state store started");

            while let Ok(report) = self.report_rx.recv() {
                if let OrderStatus::Rejected(reason) = &report.status {
                    warn!("order rejected {}: {}", report.order_id, reason);
                }

                self.orders.insert(report.order_id, report);
            }
        });
    }
}
