use bus::bounded_bus;
use config::Config;
use execution::ExecutionGateway;
use market_data::MarketDataGateway;
use metrics::init_metrics;
use oms::Oms;
use risk::RiskEngine;
use rust_decimal::Decimal;
use state::StateStore;
use strategy::StrategyEngine;
use tracing_subscriber;

fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    init_metrics();

    let cfg = Config::default();

    let (market_tx, market_rx) = bounded_bus(cfg.market_data_buffer);
    let (order_tx, order_rx) = bounded_bus(cfg.strategy_order_buffer);
    let (approved_tx, approved_rx) = bounded_bus(cfg.risk_order_buffer);
    let (exec_tx, exec_rx) = bounded_bus(cfg.exec_order_buffer);
    let (report_tx, report_rx) = bounded_bus(cfg.exec_report_buffer);

    let md = MarketDataGateway::new(market_tx);
    let strategy = StrategyEngine::new(market_rx, order_tx, 1);
    let risk = RiskEngine::new(
