    let oms = Oms::new(approved_rx, exec_tx);
    let exec = ExecutionGateway::new(exec_rx, report_tx);
    let state = StateStore::new(report_rx);

    md.start();
    strategy.start();
    risk.start();
    oms.start();
    exec.start();
    state.start();

    loop {
