use crate::types::{Instrument, MarketEvent, Quote};
use chrono::Utc;
use crossbeam_channel::Sender;
use rust_decimal::Decimal;
use std::{thread, time::Duration};
use tracing::info;

pub struct MarketDataGateway {
    tx: Sender<MarketEvent>,
}

impl MarketDataGateway {
    pub fn new(tx: Sender<MarketEvent>) -> Self {
        Self { tx }
    }

    pub fn run(self) {
        thread::spawn(move || {
            let instrument = Instrument {
                venue: "SIM".to_string(),
                symbol: "BTC-USD".to_string(),
            };

            let mut px = Decimal::new(50000, 0);

            loop {
                let quote = Quote {
                    instrument: instrument.clone(),
                    bid: px - Decimal::new(5, 0),
                    ask: px + Decimal::new(5, 0),
                    bid_size: Decimal::new(10, 0),
                    ask_size: Decimal::new(12, 0),
                    ts: Utc::now(),
                };

                if self.tx.send(MarketEvent::Quote(quote)).is_err() {
                    break;
                }

                px += Decimal::new(1, 0);
                thread::sleep(Duration::from_millis(10));
            }

            info!("MarketDataGateway stopped");
        });
    }
}
```

