## src/strategy.rs

A simple strategy: buy if ask is below threshold, sell if bid is above threshold.

```rust
use crate::types::{MarketEvent, OrderRequest, OrderType, Side};
use chrono::Utc;
use crossbeam_channel::{Receiver, Sender};
use rust_decimal::Decimal;
use tracing::{debug, info};
use uuid::Uuid;

pub struct StrategyEngine {
    market_rx: Receiver<MarketEvent>,
    order_tx: Sender<OrderRequest>,
    buy_below: Decimal,
    sell_above: Decimal,
}

impl StrategyEngine {
    pub fn new(
        market_rx: Receiver<MarketEvent>,
        order_tx: Sender<OrderRequest>,
        buy_below: Decimal,
        sell_above: Decimal,
    ) -> Self {
        Self {
            market_rx,
            order_tx,
            buy_below,
            sell_above,
        }
    }

    pub fn run(self) {
        std::thread::spawn(move || {
            while let Ok(event) = self.market_rx.recv() {
                if let MarketEvent::Quote(q) = event {
                    debug!("Strategy received quote: {:?}", q);

                    if q.ask < self.buy_below {
                        let order = OrderRequest {
                            order_id: Uuid::new_v4(),
                            instrument: q.instrument.clone(),
                            side: Side::Buy,
                            qty: Decimal::new(1, 0),
                            order_type: OrderType::Limit,
                            limit_price: Some(q.ask),
                            ts: Utc::now(),
                        };

                        let _ = self.order_tx.send(order);
                    } else if q.bid > self.sell_above {
                        let order = OrderRequest {
                            order_id: Uuid::new_v4(),
                            instrument: q.instrument.clone(),
                            side: Side::Sell,
                            qty: Decimal::new(1, 0),
                            order_type: OrderType::Limit,
                            limit_price: Some(q.bid),
                            ts: Utc::now(),
                        };

                        let _ = self.order_tx.send(order);
                    }
                }
            }

            info!("StrategyEngine stopped");
        });
    }
}
