## src/risk.rs

Pre-trade risk checks. This is mandatory in real systems.

```rust
use crate::types::{OrderRequest, Side};
use crossbeam_channel::{Receiver, Sender};
use rust_decimal::Decimal;
use std::collections::HashMap;
use tracing::{info, warn};

pub struct RiskEngine {
    order_rx: Receiver<OrderRequest>,
    approved_tx: Sender<OrderRequest>,
    max_order_qty: Decimal,
    max_position_abs: Decimal,
}

impl RiskEngine {
    pub fn new(
        order_rx: Receiver<OrderRequest>,
        approved_tx: Sender<OrderRequest>,
        max_order_qty: Decimal,
        max_position_abs: Decimal,
    ) -> Self {
        Self {
            order_rx,
            approved_tx,
            max_order_qty,
            max_position_abs,
        }
    }

    pub fn run(self) {
        std::thread::spawn(move || {
            let mut positions: HashMap<String, Decimal> = HashMap::new();

            while let Ok(order) = self.order_rx.recv() {
                if order.qty > self.max_order_qty {
                    warn!("Risk rejected order {}: qty too large", order.order_id);
                    continue;
                }

                let key = format!("{}:{}", order.instrument.venue, order.instrument.symbol);
                let current_pos = positions.get(&key).cloned().unwrap_or(Decimal::ZERO);

                let projected = match order.side {
                    Side::Buy => current_pos + order.qty,
                    Side::Sell => current_pos - order.qty,
                };

                if projected.abs() > self.max_position_abs {
                    warn!(
                        "Risk rejected order {}: projected position {} exceeds limit",
                        order.order_id, projected
                    );
                    continue;
                }

                positions.insert(key, projected);

                if self.approved_tx.send(order).is_err() {
                    break;
                }
            }

            info!("RiskEngine stopped");
        });
    }
}
```

Note: In a real platform, positions should usually be updated from fills, not assumed at order submission. This example is intentionally simplified.

