## src/oms.rs

Tracks order state.

```rust
use crate::types::{ExecutionReport, OrderRequest, OrderStatus};
use crossbeam_channel::{Receiver, Sender};
use rust_decimal::Decimal;
use std::collections::HashMap;
use tracing::{info, warn};
use uuid::Uuid;

pub struct Oms {
    approved_rx: Receiver<OrderRequest>,
    exec_tx: Sender<OrderRequest>,
    report_rx: Receiver<ExecutionReport>,
}

impl Oms {
    pub fn new(
        approved_rx: Receiver<OrderRequest>,
        exec_tx: Sender<OrderRequest>,
        report_rx: Receiver<ExecutionReport>,
    ) -> Self {
        Self {
            approved_rx,
            exec_tx,
            report_rx,
        }
    }

    pub fn run(self) {
        std::thread::spawn(move || {
            let mut orders: HashMap<Uuid, (OrderRequest, OrderStatus, Decimal)> = HashMap::new();

            loop {
                crossbeam_channel::select! {
                    recv(self.approved_rx) -> msg => {
                        match msg {
                            Ok(order) => {
                                orders.insert(order.order_id, (order.clone(), OrderStatus::New, Decimal::ZERO));
                                if self.exec_tx.send(order).is_err() {
                                    break;
                                }
                            }
                            Err(_) => break,
                        }
                    }
                    recv(self.report_rx) -> msg => {
                        match msg {
                            Ok(report) => {
                                if let Some((_, status, filled_qty)) = orders.get_mut(&report.order_id) {
                                    *status = report.status.clone();
                                    *filled_qty = report.filled_qty;
                                } else {
                                    warn!("OMS received report for unknown order {}", report.order_id);
                                }
                            }
                            Err(_) => break,
                        }
                    }
                }
            }

            info!("OMS stopped");
        });
    }
}
```

