```rust
use crate::types::{ExecutionReport, OrderRequest, OrderStatus};
use chrono::Utc;
use crossbeam_channel::{Receiver, Sender};
use tracing::info;

pub struct ExecutionGateway {
    order_rx: Receiver<OrderRequest>,
    report_tx: Sender<ExecutionReport>,
}

impl ExecutionGateway {
    pub fn new(order_rx: Receiver<OrderRequest>, report_tx: Sender<ExecutionReport>) -> Self {
        Self { order_rx, report_tx }
    }

    pub fn run(self) {
        std::thread::spawn(move || {
            while let Ok(order) = self.order_rx.recv() {
                let ack = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Acked,
                    filled_qty: rust_decimal::Decimal::ZERO,
                    remaining_qty: order.qty,
                    avg_price: None,
                    ts: Utc::now(),
                };

                let _ = self.report_tx.send(ack);

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Filled,
                    filled_qty: order.qty,
                    remaining_qty: rust_decimal::Decimal::ZERO,
                    avg_price: order.limit_price,
                    ts: Utc::now(),
                };

                let _ = self.report_tx.send(fill);
            }

            info!("ExecutionGateway stopped");
        });
    }
}
