```rust
mod bus;
mod config;
mod execution;
mod market_data;
mod oms;
mod risk;
mod strategy;
mod types;

use bus::channel;
use config::Config;
use execution::ExecutionGateway;
use market_data::MarketDataGateway;
use oms::Oms;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tracing::Level;

fn main() {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .init();

    let cfg = Config::default();

    let (market_tx, market_rx) = channel(1024);
    let (order_tx, order_rx) = channel(1024);
    let (approved_tx, approved_rx) = channel(1024);
    let (exec_tx, exec_rx) = channel(1024);
    let (report_tx, report_rx) = channel(1024);

    let md = MarketDataGateway::new(market_tx);
    let strategy = StrategyEngine::new(market_rx, order_tx, cfg.buy_below, cfg.sell_above);
    let risk = RiskEngine::new(order_rx, approved_tx, cfg.max_order_qty, cfg.max_position_abs);
    let oms = Oms::new(approved_rx, exec_tx, report_rx);
    let exec = ExecutionGateway::new(exec_rx, report_tx);

    md.run();
    strategy.run();
    risk.run();
    oms.run();
    exec.run();

    loop {
        std::thread::park();
    }
}
