use dashmap::DashMap;
use std::sync::Arc;
use uuid::Uuid;

use crate::types::{ExecutionReport, OrderStatus};

#[derive(Debug, Clone, Default)]
pub struct Position {
    pub net_qty: i64,
    pub avg_price: f64,
}

#[derive(Clone, Default)]
pub struct StateStore {
    pub positions: Arc<DashMap<String, Position>>,
    pub orders: Arc<DashMap<Uuid, ExecutionReport>>,
}

impl StateStore {
    pub fn update_execution(&self, report: &ExecutionReport) {
        self.orders.insert(report.order_id, report.clone());

        if let OrderStatus::Filled | OrderStatus::PartiallyFilled = report.status {
            let mut entry = self.positions.entry(report.symbol.clone()).or_default();
            let pos = entry.value_mut();

            // Simplified position update logic.
            // In production, use side-aware fill events, realized PnL, etc.
            pos.net_qty += report.filled_qty as i64;
            if let Some(px) = report.avg_fill_price {
                pos.avg_price = px;
            }
        }
    }

    pub fn get_position(&self, symbol: &str) -> i64 {
        self.positions.get(symbol).map(|p| p.net_qty).unwrap_or(0)
    }
}
