use crate::config::AppConfig;
use crate::state::StateStore;
use crate::types::{OrderRequest, Side};

#[derive(Clone)]
pub struct RiskEngine {
    config: AppConfig,
    state: StateStore,
}

impl RiskEngine {
    pub fn new(config: AppConfig, state: StateStore) -> Self {
        Self { config, state }
    }

    pub fn check_order(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty > self.config.max_order_qty {
            return Err(format!(
                "order qty {} exceeds max {}",
                order.qty, self.config.max_order_qty
            ));
        }

        let current_pos = self.state.get_position(&order.symbol);
        let projected = match order.side {
            Side::Buy => current_pos + order.qty as i64,
            Side::Sell => current_pos - order.qty as i64,
        };

        if projected.abs() > self.config.max_position_per_symbol {
            return Err(format!(
                "projected position {} exceeds max {}",
                projected, self.config.max_position_per_symbol
            ));
        }

        Ok(())
    }
}
