# src/strategy.rs

Simple example strategy: buy if spread is tight and price below threshold.

```rust
use chrono::Utc;
use uuid::Uuid;

use crate::types::{MarketTick, OrderRequest, OrderType, Side};

#[derive(Clone)]
pub struct SimpleStrategy {
    pub symbol: String,
    pub max_buy_price: f64,
    pub order_qty: u64,
}

impl SimpleStrategy {
    pub fn on_tick(&self, tick: &MarketTick) -> Option<OrderRequest> {
        if tick.symbol != self.symbol {
            return None;
        }

        let spread = tick.ask - tick.bid;

        if tick.ask <= self.max_buy_price && spread <= 0.05 {
            return Some(OrderRequest {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                order_type: OrderType::Limit,
                limit_price: Some(tick.ask),
                ts: Utc::now(),
            });
        }

        None
    }
}
