```rust
mod bus;
mod config;
mod execution;
mod market_data;
mod metrics;
mod risk;
mod state;
mod strategy;
mod types;

use std::sync::atomic::Ordering;

use tracing::{error, info};
use tracing_subscriber::EnvFilter;

use bus::EventBus;
use config::AppConfig;
use execution::ExecutionEngine;
use market_data::run_market_data;
use metrics::Metrics;
use risk::RiskEngine;
use state::StateStore;
use strategy::SimpleStrategy;
use types::Event;

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let config = AppConfig::default();
    let bus = EventBus::new(16_384);
    let state = StateStore::default();
    let risk = RiskEngine::new(config, state.clone());
    let exec = ExecutionEngine::new(bus.clone());
    let metrics = Metrics::default();

    let strategy = SimpleStrategy {
        symbol: "FOO".to_string(),
        max_buy_price: 100.20,
        order_qty: 100,
    };

    let md_bus = bus.clone();
    tokio::spawn(async move {
        run_market_data(md_bus).await;
    });

    let mut strategy_rx = bus.subscribe();
    let strategy_exec = exec.clone();
    let strategy_risk = risk.clone();
    let strategy_metrics = metrics.clone();

    tokio::spawn(async move {
        loop {
            match strategy_rx.recv().await {
                Ok(Event::MarketTick(tick)) => {
                    if let Some(order) = strategy.on_tick(&tick) {
                        match strategy_risk.check_order(&order) {
                            Ok(_) => {
                                strategy_metrics
                                    .orders_sent
                                    .fetch_add(1, Ordering::Relaxed);
                                strategy_exec.send_order(order).await;
                            }
                            Err(reason) => {
                                error!("risk rejected order: {}", reason);
                            }
                        }
                    }
                }
                Ok(_) => {}
                Err(e) => {
                    error!("strategy receiver error: {}", e);
                }
            }
        }
    });

    let mut state_rx = bus.subscribe();
    let state_store = state.clone();
    let fill_metrics = metrics.clone();

    tokio::spawn(async move {
        loop {
            match state_rx.recv().await {
                Ok(Event::ExecutionReport(report)) => {
                    state_store.update_execution(&report);
                    fill_metrics
                        .fills_received
                        .fetch_add(1, Ordering::Relaxed);
                    info!("updated state for order {}", report.order_id);
                }
                Ok(_) => {}
                Err(e) => {
                    error!("state receiver error: {}", e);
                }
            }
        }
    });

    info!("trading platform started");

    loop {
        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
        let sent = metrics.orders_sent.load(Ordering::Relaxed);
        let fills = metrics.fills_received.load(Ordering::Relaxed);
        info!("metrics: orders_sent={}, fills_received={}", sent, fills);
    }
}
```

