```rust
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::thread;

use crate::types::{MarketTick, OrderRequest, OrderType, Side, TimeInForce};

pub struct StrategyEngine {
    market_rx: Receiver<MarketTick>,
    order_tx: Sender<OrderRequest>,
}

impl StrategyEngine {
    pub fn new(market_rx: Receiver<MarketTick>, order_tx: Sender<OrderRequest>) -> Self {
        Self { market_rx, order_tx }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut last_mid = None::<i64>;

            while let Ok(tick) = self.market_rx.recv() {
                let mid = (tick.bid + tick.ask) / 2;

                if let Some(prev_mid) = last_mid {
                    if mid < prev_mid - 3 {
                        let order = OrderRequest {
                            strategy_id: 1,
                            instrument_id: tick.instrument_id,
                            side: Side::Buy,
                            qty: 10,
                            order_type: OrderType::Limit,
                            price: Some(tick.bid),
                            tif: TimeInForce::IOC,
                        };
                        let _ = self.order_tx.send(order);
                    } else if mid > prev_mid + 3 {
                        let order = OrderRequest {
                            strategy_id: 1,
                            instrument_id: tick.instrument_id,
                            side: Side::Sell,
                            qty: 10,
                            order_type: OrderType::Limit,
                            price: Some(tick.ask),
                            tif: TimeInForce::IOC,
                        };
                        let _ = self.order_tx.send(order);
                    }
                }

                last_mid = Some(mid);
                let _ = Utc::now(); // placeholder for timing instrumentation
            }
        });
    }
}
