```rust
use chrono::Utc;
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;
use std::thread;

use crate::types::{ApprovedOrder, OrderRequest, Side};

pub struct RiskEngine {
    order_rx: Receiver<OrderRequest>,
    approved_tx: Sender<ApprovedOrder>,
    max_abs_position: i64,
}

impl RiskEngine {
    pub fn new(
        order_rx: Receiver<OrderRequest>,
        approved_tx: Sender<ApprovedOrder>,
        max_abs_position: i64,
    ) -> Self {
        Self {
            order_rx,
            approved_tx,
            max_abs_position,
        }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut next_order_id = 1u64;
            let mut positions: HashMap<u64, i64> = HashMap::new();

            while let Ok(req) = self.order_rx.recv() {
                let pos = *positions.get(&req.instrument_id).unwrap_or(&0);
                let new_pos = match req.side {
                    Side::Buy => pos + req.qty,
                    Side::Sell => pos - req.qty,
                };

                if new_pos.abs() <= self.max_abs_position {
                    positions.insert(req.instrument_id, new_pos);

                    let approved = ApprovedOrder {
                        order_id: next_order_id,
                        request: req,
                        ts: Utc::now(),
                    };
                    next_order_id += 1;

                    let _ = self.approved_tx.send(approved);
                } else {
                    // In production, emit reject event/metric here.
                }
            }
        });
    }
}
