# src/oms.rs

```rust
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;
use std::thread;

use crate::types::{ApprovedOrder, ExecutionReport, ExecutionReportStatus};

pub struct Oms {
    approved_rx: Receiver<ApprovedOrder>,
    exec_tx: Sender<ApprovedOrder>,
    report_rx: Receiver<ExecutionReport>,
}

impl Oms {
    pub fn new(
        approved_rx: Receiver<ApprovedOrder>,
        exec_tx: Sender<ApprovedOrder>,
        report_rx: Receiver<ExecutionReport>,
    ) -> Self {
        Self {
            approved_rx,
            exec_tx,
            report_rx,
        }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut live_orders: HashMap<u64, ApprovedOrder> = HashMap::new();

            loop {
                crossbeam::select! {
                    recv(self.approved_rx) -> msg => {
                        match msg {
                            Ok(order) => {
                                live_orders.insert(order.order_id, order.clone());
                                let _ = self.exec_tx.send(order);
                            }
                            Err(_) => break,
                        }
                    }
                    recv(self.report_rx) -> msg => {
                        match msg {
                            Ok(report) => {
                                match report.status {
                                    ExecutionReportStatus::Filled
                                    | ExecutionReportStatus::Rejected
                                    | ExecutionReportStatus::Cancelled => {
                                        live_orders.remove(&report.order_id);
                                    }
                                    _ => {}
                                }
                            }
                            Err(_) => break,
                        }
                    }
                }
            }
        });
    }
}
