use crossbeam::channel::{bounded, Receiver, Sender};
use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::thread;
use std::time::{Duration, SystemTime};
use thiserror::Error;
use tracing::{error, info};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MarketData {
    pub symbol: String,
    pub bid: Decimal,
    pub ask: Decimal,
    pub ts: SystemTime,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Signal {
    pub symbol: String,
    pub side: Side,
    pub qty: u64,
    pub price: Decimal,
    pub ts: SystemTime,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderRequest {
    pub id: Uuid,
    pub symbol: String,
    pub side: Side,
    pub qty: u64,
    pub price: Decimal,
    pub ts: SystemTime,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum OrderStatus {
    New,
    Acked,
    Rejected(String),
    Filled { filled_qty: u64, avg_price: Decimal },
    PartiallyFilled { filled_qty: u64, avg_price: Decimal },
    Cancelled,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderEvent {
    pub order_id: Uuid,
    pub status: OrderStatus,
    pub ts: SystemTime,
}

#[derive(Debug, Default)]
pub struct Position {
    pub net_qty: i64,
}

#[derive(Debug, Error)]
pub enum RiskError {
    #[error("position limit exceeded for symbol {0}")]
    PositionLimitExceeded(String),
}

pub struct StrategyEngine {
    last_mid: HashMap<String, Decimal>,
}

impl StrategyEngine {
    pub fn new() -> Self {
        Self {
            last_mid: HashMap::new(),
        }
    }

    pub fn on_market_data(&mut self, md: &MarketData) -> Option<Signal> {
        let mid = (md.bid + md.ask) / Decimal::from(2u64);

        let signal = if let Some(prev_mid) = self.last_mid.get(&md.symbol) {
            if mid > *prev_mid {
                Some(Signal {
                    symbol: md.symbol.clone(),
                    side: Side::Buy,
                    qty: 10,
                    price: md.ask,
                    ts: SystemTime::now(),
                })
            } else if mid < *prev_mid {
                Some(Signal {
                    symbol: md.symbol.clone(),
                    side: Side::Sell,
                    qty: 10,
                    price: md.bid,
                    ts: SystemTime::now(),
                })
            } else {
                None
            }
        } else {
            None
        };

        self.last_mid.insert(md.symbol.clone(), mid);
        signal
    }
}

pub struct RiskEngine {
    max_abs_position: i64,
    positions: HashMap<String, Position>,
}

impl RiskEngine {
    pub fn new(max_abs_position: i64) -> Self {
        Self {
            max_abs_position,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &OrderRequest) -> Result<(), RiskError> {
        let current = self.positions.get(&order.symbol).map(|p| p.net_qty).unwrap_or(0);

        let delta = match order.side {
            Side::Buy => order.qty as i64,
            Side::Sell => -(order.qty as i64),
        };

        let projected = current + delta;
        if projected.abs() > self.max_abs_position {
            return Err(RiskError::PositionLimitExceeded(order.symbol.clone()));
        }

        Ok(())
    }

    pub fn on_fill(&mut self, order: &OrderRequest, filled_qty: u64) {
        let pos = self.positions.entry(order.symbol.clone()).or_default();
        match order.side {
            Side::Buy => pos.net_qty += filled_qty as i64,
            Side::Sell => pos.net_qty -= filled_qty as i64,
        }
    }
}

pub struct OrderManager {
    live_orders: HashMap<Uuid, OrderRequest>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            live_orders: HashMap::new(),
        }
    }

    pub fn register(&mut self, order: OrderRequest) {
        self.live_orders.insert(order.id, order);
    }

    pub fn get(&self, id: &Uuid) -> Option<&OrderRequest> {
        self.live_orders.get(id)
    }

    pub fn remove(&mut self, id: &Uuid) {
        self.live_orders.remove(id);
    }
}

fn market_data_producer(tx: Sender<MarketData>) {
    let symbols = vec!["AAPL", "MSFT", "BTC-USD"];
    let mut px = Decimal::from(100u64);

    loop {
        for sym in &symbols {
            let md = MarketData {
                symbol: sym.to_string(),
                bid: px,
                ask: px + Decimal::new(1, 1),
                ts: SystemTime::now(),
            };

            if tx.send(md).is_err() {
                return;
            }
            px += Decimal::new(1, 2);
        }
        thread::sleep(Duration::from_millis(10));
    }
}

fn strategy_loop(
    md_rx: Receiver<MarketData>,
    signal_tx: Sender<Signal>,
) {
    let mut strategy = StrategyEngine::new();

    while let Ok(md) = md_rx.recv() {
        if let Some(signal) = strategy.on_market_data(&md) {
            let _ = signal_tx.send(signal);
        }
    }
}

fn risk_and_order_loop(
    signal_rx: Receiver<Signal>,
    order_tx: Sender<OrderRequest>,
    order_event_rx: Receiver<OrderEvent>,
) {
    let mut risk = RiskEngine::new(100);
    let mut oms = OrderManager::new();

    loop {
        crossbeam::select! {
            recv(signal_rx) -> msg => {
                match msg {
                    Ok(signal) => {
                        let order = OrderRequest {
                            id: Uuid::new_v4(),
                            symbol: signal.symbol,
                            side: signal.side,
                            qty: signal.qty,
                            price: signal.price,
                            ts: signal.ts,
                        };

                        match risk.check_order(&order) {
                            Ok(_) => {
                                oms.register(order.clone());
                                let _ = order_tx.send(order);
                            }
                            Err(e) => {
                                error!("risk reject: {}", e);
                            }
                        }
                    }
                    Err(_) => break,
                }
            }
            recv(order_event_rx) -> msg => {
                match msg {
                    Ok(event) => {
                        if let Some(order) = oms.get(&event.order_id).cloned() {
                            match event.status {
                                OrderStatus::Filled { filled_qty, .. } |
                                OrderStatus::PartiallyFilled { filled_qty, .. } => {
                                    risk.on_fill(&order, filled_qty);
                                }
                                OrderStatus::Cancelled | OrderStatus::Rejected(_) => {
                                    oms.remove(&event.order_id);
                                }
                                OrderStatus::Acked | OrderStatus::New => {}
                            }
                        }
                    }
                    Err(_) => break,
                }
            }
        }
    }
}

fn execution_loop(
    order_rx: Receiver<OrderRequest>,
    order_event_tx: Sender<OrderEvent>,
) {
    while let Ok(order) = order_rx.recv() {
        let ack = OrderEvent {
            order_id: order.id,
            status: OrderStatus::Acked,
            ts: SystemTime::now(),
        };
        let _ = order_event_tx.send(ack);

        let fill = OrderEvent {
            order_id: order.id,
            status: OrderStatus::Filled {
                filled_qty: order.qty,
                avg_price: order.price,
            },
            ts: SystemTime::now(),
        };
        let _ = order_event_tx.send(fill);
    }
}

fn persistence_loop(order_event_rx: Receiver<OrderEvent>) {
    while let Ok(event) = order_event_rx.recv() {
        info!("persisting order event: {:?}", event);
        // Replace with async DB/Kafka write
    }
}

fn main() {
    tracing_subscriber::fmt::init();

    let (md_tx, md_rx) = bounded::<MarketData>(1024);
    let (signal_tx, signal_rx) = bounded::<Signal>(1024);
    let (order_tx, order_rx) = bounded::<OrderRequest>(1024);
    let (order_event_tx_core, order_event_rx_core) = bounded::<OrderEvent>(1024);
    let (order_event_tx_persist, order_event_rx_persist) = bounded::<OrderEvent>(1024);

    let tee_order_event_tx = {
        let tx1 = order_event_tx_core.clone();
        let tx2 = order_event_tx_persist.clone();
        move |event: OrderEvent| {
            let _ = tx1.send(event.clone());
            let _ = tx2.send(event);
        }
    };

    let exec_order_event_tx = {
        let tx = order_event_tx_core.clone();
        let tx_persist = order_event_tx_persist.clone();
        move |event: OrderEvent| {
            let _ = tx.send(event.clone());
            let _ = tx_persist.send(event);
        }
    };

    let md_handle = thread::spawn(move || market_data_producer(md_tx));
    let strat_handle = thread::spawn(move || strategy_loop(md_rx, signal_tx));
    let risk_handle = thread::spawn(move || risk_and_order_loop(signal_rx, order_tx, order_event_rx_core));

    let exec_handle = thread::spawn(move || {
        while let Ok(order) = order_rx.recv() {
            let ack = OrderEvent {
                order_id: order.id,
                status: OrderStatus::Acked,
                ts: SystemTime::now(),
            };
            exec_order_event_tx(ack);

            let fill = OrderEvent {
                order_id: order.id,
                status: OrderStatus::Filled {
                    filled_qty: order.qty,
                    avg_price: order.price,
                },
                ts: SystemTime::now(),
            };
            exec_order_event_tx(fill);
        }
    });

    let persist_handle = thread::spawn(move || persistence_loop(order_event_rx_persist));

    let _ = md_handle.join();
    let _ = strat_handle.join();
    let _ = risk_handle.join();
    let _ = exec_handle.join();
    let _ = persist_handle.join();

    let _ = tee_order_event_tx;
}
