# Position manager: `src/position.rs`

```rust
use std::collections::HashMap;
use crate::types::{ExecutionReport, OrderStatus, Qty, Symbol, Side};

#[derive(Debug, Default)]
pub struct PositionManager {
    positions: HashMap<Symbol, i64>,
}

impl PositionManager {
    pub fn new() -> Self {
        Self {
            positions: HashMap::new(),
        }
    }

    pub fn on_fill(&mut self, report: &ExecutionReport, side: Side) {
        if report.status != OrderStatus::Filled && report.status != OrderStatus::PartiallyFilled {
            return;
        }

        let pos = self.positions.entry(report.symbol.clone()).or_insert(0);
        let signed_qty = report.filled_qty as i64;

        match side {
            Side::Buy => *pos += signed_qty,
            Side::Sell => *pos -= signed_qty,
        }
    }

    pub fn get_position(&self, symbol: &str) -> i64 {
        *self.positions.get(symbol).unwrap_or(&0)
    }

    pub fn snapshot(&self) -> HashMap<Symbol, i64> {
        self.positions.clone()
    }
}
```

