use crate::types::{OrderRequest, Side};

#[derive(Debug)]
pub struct RiskEngine {
    max_order_qty: u64,
    max_position_abs: i64,
    positions: HashMap<String, i64>,
}

impl RiskEngine {
    pub fn new(max_order_qty: u64, max_position_abs: i64) -> Self {
        Self {
            max_order_qty,
            max_position_abs,
            positions: HashMap::new(),
        }
    }

    pub fn check(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty == 0 {
            return Err("order qty cannot be zero".to_string());
        }

        if order.qty > self.max_order_qty {
            return Err(format!(
                "order qty {} exceeds max {}",
                order.qty, self.max_order_qty
            ));
        }

        let current_pos = *self.positions.get(&order.symbol).unwrap_or(&0);
        let projected = match order.side {
            Side::Buy => current_pos + order.qty as i64,
            Side::Sell => current_pos - order.qty as i64,
        };

        if projected.abs() > self.max_position_abs {
            return Err(format!(
                "projected position {} exceeds max abs {}",
                projected, self.max_position_abs
            ));
        }

        Ok(())
    }

    pub fn on_fill(&mut self, symbol: &str, side: Side, filled_qty: u64) {
        let pos = self.positions.entry(symbol.to_string()).or_insert(0);
        match side {
            Side::Buy => *pos += filled_qty as i64,
            Side::Sell => *pos -= filled_qty as i64,
        }
    }

    pub fn get_position(&self, symbol: &str) -> i64 {
        *self.positions.get(symbol).unwrap_or(&0)
    }
}
