This example strategy buys if spread is tight and last trades near ask; sells if near bid. Just a placeholder.

```rust
use crate::types::{MarketTick, OrderType, Signal, Side};

pub struct SimpleStrategy {
    pub strategy_id: u64,
    pub trade_qty: u64,
}

impl SimpleStrategy {
    pub fn new(strategy_id: u64, trade_qty: u64) -> Self {
        Self {
            strategy_id,
            trade_qty,
        }
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<Signal> {
        let spread = tick.ask - tick.bid;
        if spread <= 2 {
            if tick.last >= tick.ask - 1 {
                return Some(Signal {
                    strategy_id: self.strategy_id,
                    symbol: tick.symbol.clone(),
                    side: Side::Buy,
                    qty: self.trade_qty,
                    limit_price: Some(tick.ask),
                    ts_nanos: tick.ts_nanos,
                });
            } else if tick.last <= tick.bid + 1 {
                return Some(Signal {
                    strategy_id: self.strategy_id,
                    symbol: tick.symbol.clone(),
                    side: Side::Sell,
                    qty: self.trade_qty,
                    limit_price: Some(tick.bid),
                    ts_nanos: tick.ts_nanos,
                });
            }
        }
        None
    }
}
