use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};

use crate::types::{OrderId, OrderRequest, OrderStatus, OrderType, Signal};

#[derive(Debug, Clone)]
pub struct ManagedOrder {
    pub request: OrderRequest,
    pub status: OrderStatus,
}

pub struct OrderManager {
    next_id: AtomicU64,
    orders: HashMap<OrderId, ManagedOrder>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            next_id: AtomicU64::new(1),
            orders: HashMap::new(),
        }
    }

    pub fn create_order(&mut self, signal: Signal) -> OrderRequest {
        let order_id = self.next_id.fetch_add(1, Ordering::Relaxed);
        let order = OrderRequest {
            strategy_id: signal.strategy_id,
            order_id,
            symbol: signal.symbol,
            side: signal.side,
            qty: signal.qty,
            order_type: OrderType::Limit,
            limit_price: signal.limit_price,
            ts_nanos: signal.ts_nanos,
        };

        self.orders.insert(order_id, ManagedOrder {
            request: order.clone(),
            status: OrderStatus::New,
        });

        order
    }

    pub fn mark_status(&mut self, order_id: OrderId, status: OrderStatus) {
        if let Some(order) = self.orders.get_mut(&order_id) {
            order.status = status;
        }
    }

    pub fn get(&self, order_id: OrderId) -> Option<&ManagedOrder> {
        self.orders.get(&order_id)
    }
}
