```rust
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use crossbeam::channel::{Receiver, Sender};

use crate::types::{ExecutionReport, OrderRequest, OrderStatus};

pub struct MockGateway;

impl MockGateway {
    pub fn start(order_rx: Receiver<OrderRequest>, exec_tx: Sender<ExecutionReport>) {
        thread::spawn(move || {
            while let Ok(order) = order_rx.recv() {
                let accepted = ExecutionReport {
                    order_id: order.order_id,
                    symbol: order.symbol.clone(),
                    status: OrderStatus::Accepted,
                    filled_qty: 0,
                    remaining_qty: order.qty,
                    avg_price: None,
                    reason: None,
                    ts_nanos: now_nanos(),
                };

                if exec_tx.send(accepted).is_err() {
                    break;
                }

                thread::sleep(Duration::from_micros(50));

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    symbol: order.symbol.clone(),
                    status: OrderStatus::Filled,
                    filled_qty: order.qty,
                    remaining_qty: 0,
                    avg_price: order.limit_price,
                    reason: None,
                    ts_nanos: now_nanos(),
                };

                if exec_tx.send(fill).is_err() {
                    break;
                }
            }
        });
    }
}

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
