use crate::bus::EventBus;
use crate::events::{Event, NewOrder, Side, Signal};
use uuid::Uuid;

pub struct StrategyEngine {
    bus: EventBus,
}

impl StrategyEngine {
    pub fn new(bus: EventBus) -> Self {
        Self { bus }
    }

    pub fn run(&mut self) {
        let rx = self.bus.subscribe();

        while let Ok(event) = rx.recv() {
            if let Event::MarketTick(tick) = event {
                let mid = (tick.bid + tick.ask) / 2.0;

                let signal = if tick.bid_size > tick.ask_size * 2 {
                    Some(Signal {
                        symbol: tick.symbol.clone(),
                        side: Side::Buy,
                        qty: 10,
                        price: tick.ask,
                        ts_nanos: tick.ts_nanos,
                    })
                } else if tick.ask_size > tick.bid_size * 2 {
                    Some(Signal {
                        symbol: tick.symbol.clone(),
                        side: Side::Sell,
                        qty: 10,
                        price: tick.bid,
                        ts_nanos: tick.ts_nanos,
                    })
                } else {
                    None
                };

                if let Some(sig) = signal {
                    let order = NewOrder {
                        order_id: Uuid::new_v4(),
                        symbol: sig.symbol,
                        side: sig.side,
                        qty: sig.qty,
                        price: sig.price.max(mid * 0.5),
                        ts_nanos: sig.ts_nanos,
                    };
                    self.bus.publish(Event::NewOrder(order));
                }
            }
        }
    }
}
