use crate::bus::EventBus;
use crate::events::{Event, NewOrder};

pub struct RiskEngine {
    bus: EventBus,
    max_notional: f64,
    max_qty: u64,
}

impl RiskEngine {
    pub fn new(bus: EventBus, max_notional: f64, max_qty: u64) -> Self {
        Self {
            bus,
            max_notional,
            max_qty,
        }
    }

    pub fn run(&mut self) {
        let rx = self.bus.subscribe();

        while let Ok(event) = rx.recv() {
            if let Event::NewOrder(order) = event {
                self.handle_order(order);
            }
        }
    }

    fn handle_order(&self, order: NewOrder) {
        let notional = order.price * order.qty as f64;

        if order.qty > self.max_qty {
            self.bus.publish(Event::RiskRejected {
                order_id: order.order_id,
                reason: "max qty exceeded".to_string(),
            });
            return;
        }

        if notional > self.max_notional {
            self.bus.publish(Event::RiskRejected {
                order_id: order.order_id,
                reason: "max notional exceeded".to_string(),
            });
            return;
        }

        self.bus.publish(Event::RiskApproved(order));
    }
}
