use crate::bus::EventBus;
use crate::events::{Event, NewOrder, OrderAck};
use std::collections::HashMap;
use uuid::Uuid;

#[derive(Debug, Clone)]
enum OrderState {
    PendingRisk,
    Approved,
    Acked(String),
    Rejected(String),
    Filled,
}

pub struct Oms {
    bus: EventBus,
    orders: HashMap<Uuid, OrderState>,
}

impl Oms {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            orders: HashMap::new(),
        }
    }

    pub fn run(&mut self) {
        let rx = self.bus.subscribe();

        while let Ok(event) = rx.recv() {
            match event {
                Event::NewOrder(order) => {
                    self.orders.insert(order.order_id, OrderState::PendingRisk);
                }
                Event::RiskApproved(order) => {
                    self.orders.insert(order.order_id, OrderState::Approved);
                    self.bus.publish(Event::RiskApproved(order));
                }
                Event::RiskRejected { order_id, reason } => {
                    self.orders.insert(order_id, OrderState::Rejected(reason));
                }
                Event::OrderAck(OrderAck { order_id, venue_order_id, .. }) => {
                    self.orders.insert(order_id, OrderState::Acked(venue_order_id));
                }
                Event::Fill(fill) => {
                    self.orders.insert(fill.order_id, OrderState::Filled);
                }
                _ => {}
            }
        }
    }
}
