```rust
use crate::bus::EventBus;
use crate::events::{Event, Fill, OrderAck};

pub struct ExecutionGateway {
    bus: EventBus,
}

impl ExecutionGateway {
    pub fn new(bus: EventBus) -> Self {
        Self { bus }
    }

    pub fn run(&mut self) {
        let rx = self.bus.subscribe();

        while let Ok(event) = rx.recv() {
            if let Event::RiskApproved(order) = event {
                let ack = OrderAck {
                    order_id: order.order_id,
                    venue_order_id: format!("VENUE-{}", order.order_id),
                    ts_nanos: now_nanos(),
                };
                self.bus.publish(Event::OrderAck(ack));

                let fill = Fill {
                    order_id: order.order_id,
                    symbol: order.symbol,
                    side: order.side,
                    qty: order.qty,
                    price: order.price,
                    ts_nanos: now_nanos(),
                };
                self.bus.publish(Event::Fill(fill));
            }
        }
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

