## `src/position.rs`
```rust
use crate::bus::EventBus;
use crate::events::{Event, Fill, PositionUpdate, Side};
use std::collections::HashMap;

#[derive(Debug, Clone, Default)]
struct Position {
    net_qty: i64,
    avg_price: f64,
    realized_pnl: f64,
}

pub struct PositionService {
    bus: EventBus,
    positions: HashMap<String, Position>,
}

impl PositionService {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            positions: HashMap::new(),
        }
    }

    pub fn run(&mut self) {
        let rx = self.bus.subscribe();

        while let Ok(event) = rx.recv() {
            if let Event::Fill(fill) = event {
                self.apply_fill(fill);
            }
        }
    }

    fn apply_fill(&mut self, fill: Fill) {
        let pos = self.positions.entry(fill.symbol.clone()).or_default();

        match fill.side {
            Side::Buy => {
                let new_qty = pos.net_qty + fill.qty as i64;
                if new_qty != 0 {
                    pos.avg_price = ((pos.avg_price * pos.net_qty as f64)
                        + (fill.price * fill.qty as f64))
                        / new_qty as f64;
                }
                pos.net_qty = new_qty;
            }
            Side::Sell => {
                pos.net_qty -= fill.qty as i64;
                pos.realized_pnl += fill.qty as f64 * (fill.price - pos.avg_price);
            }
        }

        self.bus.publish(Event::PositionUpdate(PositionUpdate {
            symbol: fill.symbol,
            net_qty: pos.net_qty,
            avg_price: pos.avg_price,
            realized_pnl: pos.realized_pnl,
            ts_nanos: fill.ts_nanos,
        }));
    }
}
```

