```java
package strategy;

import core.MarketDataTick;
import core.Order;
import core.Side;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

public class MeanReversionStrategy implements Strategy {
    private final Map<String, Double> lastPriceBySymbol = new HashMap<>();
    private final AtomicLong tempOrderIds = new AtomicLong(1);

    @Override
    public Optional<Order> onMarketData(MarketDataTick tick) {
        Double prev = lastPriceBySymbol.put(tick.symbol(), tick.last());
        if (prev == null) {
            return Optional.empty();
        }

        double change = (tick.last() - prev) / prev;
        if (change < -0.002) {
            return Optional.of(new Order(
                    tempOrderIds.getAndIncrement(),
                    tick.symbol(),
                    Side.BUY,
                    100,
                    tick.ask(),
                    System.nanoTime()
            ));
        } else if (change > 0.002) {
            return Optional.of(new Order(
                    tempOrderIds.getAndIncrement(),
                    tick.symbol(),
                    Side.SELL,
                    100,
                    tick.bid(),
                    System.nanoTime()
            ));
        }

        return Optional.empty();
    }
}
