package risk;

import core.ExecutionReport;
import core.Side;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class PositionTracker {
    private final Map<String, Integer> positions = new ConcurrentHashMap<>();

    public void onFill(ExecutionReport fill) {
        int signedQty = fill.side() == Side.BUY ? fill.filledQty() : -fill.filledQty();
        positions.merge(fill.symbol(), signedQty, Integer::sum);
    }

    public int getPosition(String symbol) {
        return positions.getOrDefault(symbol, 0);
    }
}
