## `RiskEngine.java`

```java
package risk;

import core.Order;
import core.RiskResult;
import core.Side;

public class RiskEngine {
    private final PositionTracker positionTracker;
    private final int maxOrderQty;
    private final int maxPositionAbs;

    public RiskEngine(PositionTracker positionTracker, int maxOrderQty, int maxPositionAbs) {
        this.positionTracker = positionTracker;
        this.maxOrderQty = maxOrderQty;
        this.maxPositionAbs = maxPositionAbs;
    }

    public RiskResult check(Order order) {
        if (order.quantity() <= 0) {
            return new RiskResult(false, "Invalid quantity");
        }

        if (order.quantity() > maxOrderQty) {
            return new RiskResult(false, "Order quantity exceeds limit");
        }

        int currentPos = positionTracker.getPosition(order.symbol());
        int projectedPos = order.side() == Side.BUY
                ? currentPos + order.quantity()
                : currentPos - order.quantity();

        if (Math.abs(projectedPos) > maxPositionAbs) {
            return new RiskResult(false, "Projected position exceeds limit");
        }

        return new RiskResult(true, "OK");
    }
}
```

