package oms;

import bus.RingBufferBus;
import core.ExecutionReport;
import core.Order;
import core.RiskResult;
import gateway.ExchangeGateway;
import risk.RiskEngine;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class OrderManager {
    private final RiskEngine riskEngine;
    private final ExchangeGateway gateway;
    private final RingBufferBus bus;
    private final IdGenerator idGenerator;
    private final Map<Long, Order> liveOrders = new ConcurrentHashMap<>();

    public OrderManager(RiskEngine riskEngine, ExchangeGateway gateway, RingBufferBus bus, IdGenerator idGenerator) {
        this.riskEngine = riskEngine;
        this.gateway = gateway;
        this.bus = bus;
        this.idGenerator = idGenerator;
    }

    public void submit(Order draftOrder) {
        Order order = new Order(
                idGenerator.next(),
                draftOrder.symbol(),
                draftOrder.side(),
                draftOrder.quantity(),
                draftOrder.price(),
                System.nanoTime()
        );

        RiskResult result = riskEngine.check(order);
        if (!result.approved()) {
            bus.publish(new ExecutionReport(
                    order.orderId(),
                    order.symbol(),
                    order.side(),
                    0,
                    0.0,
                    "REJECT",
                    System.nanoTime()
            ));
            return;
        }

        liveOrders.put(order.orderId(), order);
        gateway.send(order);
    }

    public void onExecutionReport(ExecutionReport report) {
        if ("FILL".equals(report.status()) || "REJECT".equals(report.status())) {
            liveOrders.remove(report.orderId());
        }
    }
}
```

