package app;

import bus.RingBufferBus;
import core.Event;
import core.EventType;
import core.ExecutionReport;
import core.MarketDataTick;
import gateway.ExchangeGateway;
import gateway.SimulatedExchangeGateway;
import marketdata.MarketDataHandler;
import oms.IdGenerator;
import oms.OrderManager;
import risk.PositionTracker;
import risk.RiskEngine;
import strategy.MeanReversionStrategy;
import strategy.Strategy;

public class TradingEngine {
    private final RingBufferBus bus;
    private final MarketDataHandler marketDataHandler;
    private final Strategy strategy;
    private final PositionTracker positionTracker;
    private final RiskEngine riskEngine;
    private final ExchangeGateway gateway;
    private final OrderManager orderManager;

    public TradingEngine() {
        this.bus = new RingBufferBus(1024);
        this.marketDataHandler = new MarketDataHandler(bus);
        this.strategy = new MeanReversionStrategy();
        this.positionTracker = new PositionTracker();
        this.riskEngine = new RiskEngine(positionTracker, 1000, 5000);
        this.gateway = new SimulatedExchangeGateway(bus);
        this.orderManager = new OrderManager(riskEngine, gateway, bus, new IdGenerator());

        bus.register(this::handleEvent);
        bus.start();
    }

    private void handleEvent(Event event) {
        switch (event.type()) {
            case MARKET_DATA -> {
                MarketDataTick tick = (MarketDataTick) event;
                strategy.onMarketData(tick).ifPresent(orderManager::submit);
            }
            case ORDER_ACK, ORDER_REJECT, FILL -> {
                ExecutionReport report = (ExecutionReport) event;
                orderManager.onExecutionReport(report);
                if (event.type() == EventType.FILL) {
                    positionTracker.onFill(report);
                }
            }
            default -> {
                // no-op
            }
        }
    }

    public MarketDataHandler marketDataHandler() {
        return marketDataHandler;
    }
}
