# src/risk.rs

```rust
use parking_lot::RwLock;
use std::collections::HashMap;
use std::sync::Arc;

use crate::types::{NewOrder, Qty, Side, Symbol};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Qty,
    pub max_abs_position_per_symbol: Qty,
    pub trading_enabled: bool,
}

#[derive(Default)]
pub struct PositionState {
    positions: HashMap<Symbol, Qty>,
}

#[derive(Clone)]
pub struct RiskEngine {
    limits: Arc<RwLock<RiskLimits>>,
    positions: Arc<RwLock<PositionState>>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits: Arc::new(RwLock::new(limits)),
            positions: Arc::new(RwLock::new(PositionState::default())),
        }
    }

    pub fn check_order(&self, order: &NewOrder) -> Result<(), String> {
        let limits = self.limits.read();

        if !limits.trading_enabled {
            return Err("trading disabled".into());
        }

        if order.qty <= 0 || order.qty > limits.max_order_qty {
            return Err(format!("order qty {} exceeds max {}", order.qty, limits.max_order_qty));
        }

        let positions = self.positions.read();
        let current = *positions.positions.get(&order.symbol).unwrap_or(&0);

        let projected = match order.side {
            Side::Buy => current + order.qty,
            Side::Sell => current - order.qty,
        };

        if projected.abs() > limits.max_abs_position_per_symbol {
            return Err(format!(
                "projected position {} exceeds max abs position {} for {}",
                projected, limits.max_abs_position_per_symbol, order.symbol
            ));
        }

        Ok(())
    }

    pub fn apply_fill(&self, symbol: &str, side: &Side, fill_qty: Qty) {
        let mut positions = self.positions.write();
        let entry = positions.positions.entry(symbol.to_string()).or_insert(0);
        match side {
            Side::Buy => *entry += fill_qty,
            Side::Sell => *entry -= fill_qty,
        }
    }
}
