# src/oms.rs

```rust
use parking_lot::RwLock;
use std::collections::HashMap;
use std::sync::Arc;
use uuid::Uuid;

use crate::types::{ExecutionReport, NewOrder, OrderStatus, Side, Symbol, Qty};

#[derive(Debug, Clone)]
pub struct OrderRecord {
    pub order: NewOrder,
    pub status: OrderStatus,
    pub filled_qty: Qty,
}

#[derive(Clone, Default)]
pub struct Oms {
    orders: Arc<RwLock<HashMap<Uuid, OrderRecord>>>,
}

impl Oms {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn register_new(&self, order: NewOrder) {
        let mut orders = self.orders.write();
        orders.insert(
            order.order_id,
            OrderRecord {
                order,
                status: OrderStatus::PendingNew,
                filled_qty: 0,
            },
        );
    }

    pub fn on_execution_report(&self, report: &ExecutionReport) {
        let mut orders = self.orders.write();
        if let Some(record) = orders.get_mut(&report.order_id) {
            record.status = report.status.clone();
            record.filled_qty = report.filled_qty;
        }
    }

    pub fn get_order_side_symbol(&self, order_id: &Uuid) -> Option<(Side, Symbol)> {
        let orders = self.orders.read();
        orders.get(order_id).map(|r| (r.order.side.clone(), r.order.symbol.clone()))
    }
}
