# src/portfolio.rs

```rust
use parking_lot::RwLock;
use std::collections::HashMap;
use std::sync::Arc;

use crate::types::{Price, Qty, Symbol};

#[derive(Clone, Default)]
pub struct Portfolio {
    positions: Arc<RwLock<HashMap<Symbol, Qty>>>,
    last_prices: Arc<RwLock<HashMap<Symbol, Price>>>,
}

impl Portfolio {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn update_position(&self, symbol: &str, delta: Qty) {
        let mut positions = self.positions.write();
        *positions.entry(symbol.to_string()).or_insert(0) += delta;
    }

    pub fn update_last_price(&self, symbol: &str, px: Price) {
        let mut prices = self.last_prices.write();
        prices.insert(symbol.to_string(), px);
    }

    pub fn snapshot_pnl(&self) -> i64 {
        let positions = self.positions.read();
        let prices = self.last_prices.read();

        positions
            .iter()
            .map(|(sym, qty)| prices.get(sym).copied().unwrap_or(0) * qty)
            .sum()
    }
}
