# src/strategy.rs

This example strategy is intentionally simple: buy if spread is narrow and last trades at ask; sell if last trades at bid.

```rust
use std::sync::Arc;
use uuid::Uuid;

use crate::types::{
    MarketTick, NewOrder, OrderRequest, OrderType, Side, TimestampNanos,
};

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderRequest>;
}

pub struct SimpleMakerTakerStrategy {
    pub order_qty: i64,
    pub max_spread: i64,
}

impl Strategy for SimpleMakerTakerStrategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderRequest> {
        let spread = tick.ask - tick.bid;
        if spread < 0 {
            return None;
        }

        if spread <= self.max_spread && tick.last >= tick.ask {
            return Some(OrderRequest::New(NewOrder {
                order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                order_type: OrderType::Market,
                ts_nanos: tick.ts_nanos,
            }));
        }

        if spread <= self.max_spread && tick.last <= tick.bid {
            return Some(OrderRequest::New(NewOrder {
                order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: self.order_qty,
                order_type: OrderType::Market,
                ts_nanos: tick.ts_nanos,
            }));
        }

        None
    }
}

pub type SharedStrategy = Arc<dyn Strategy>;
