# src/exchange/sim.rs

A simulated exchange adapter for testing.

```rust
use async_trait::async_trait;
use tokio::sync::mpsc;
use tokio::time::{sleep, Duration};

use crate::exchange::ExchangeAdapter;
use crate::types::{
    ExecutionReport, NewOrder, OrderRequest, OrderStatus, Side,
};

pub struct SimExchange {
    report_tx: mpsc::Sender<ExecutionReport>,
    report_rx: tokio::sync::Mutex<mpsc::Receiver<ExecutionReport>>,
}

impl SimExchange {
    pub fn new(buffer: usize) -> Self {
        let (tx, rx) = mpsc::channel(buffer);
        Self {
            report_tx: tx,
            report_rx: tokio::sync::Mutex::new(rx),
        }
    }

    async fn simulate_new_order(&self, order: NewOrder) {
        let ack = ExecutionReport {
            order_id: order.order_id,
            symbol: order.symbol.clone(),
            status: OrderStatus::Acked,
            filled_qty: 0,
            remaining_qty: order.qty,
            avg_price: None,
            ts_nanos: order.ts_nanos + 1,
        };

        let fill = ExecutionReport {
            order_id: order.order_id,
            symbol: order.symbol.clone(),
            status: OrderStatus::Filled,
            filled_qty: order.qty,
            remaining_qty: 0,
            avg_price: match order.order_type {
                crate::types::OrderType::Market => Some(100),
                crate::types::OrderType::Limit { price } => Some(price),
            },
            ts_nanos: order.ts_nanos + 2,
        };

        let tx = self.report_tx.clone();
        tokio::spawn(async move {
            let _ = tx.send(ack).await;
            sleep(Duration::from_millis(1)).await;
            let _ = tx.send(fill).await;
        });
    }
}

#[async_trait]
impl ExchangeAdapter for SimExchange {
    async fn send_order(&self, req: OrderRequest) -> Result<(), String> {
        match req {
            OrderRequest::New(order) => {
                self.simulate_new_order(order).await;
                Ok(())
            }
            OrderRequest::Cancel(_) => Ok(()),
        }
    }

    async fn next_execution_report(&self) -> Option<ExecutionReport> {
        let mut rx = self.report_rx.lock().await;
        rx.recv().await
    }
}
