use tokio::time::{sleep, Duration};

use crate::bus::EventBus;
use crate::types::{Event, MarketTick};

pub async fn run_market_data(bus: EventBus) {
    let mut px = 100_i64;

    loop {
        let tick = MarketTick {
            symbol: "FOO".to_string(),
            bid: px - 1,
            ask: px + 1,
            last: px,
            ts_nanos: now_nanos(),
        };

        if bus.publish(Event::Market(tick)).is_err() {
            break;
        }

        px = if px % 2 == 0 { px + 1 } else { px - 1 };
        sleep(Duration::from_millis(10)).await;
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
