# src/main.rs

```rust
mod bus;
mod config;
mod exchange;
mod execution;
mod market_data;
mod oms;
mod persistence;
mod portfolio;
mod risk;
mod strategy;
mod types;

use std::sync::Arc;
use std::thread;

use tracing::{error, info};

use bus::EventBus;
use config::Config;
use exchange::sim::SimExchange;
use execution::ExecutionEngine;
use oms::Oms;
use persistence::{run_persistence, PersistenceWriter};
use portfolio::Portfolio;
use risk::{RiskEngine, RiskLimits};
use strategy::{SharedStrategy, SimpleMakerTakerStrategy};
use types::{Event, OrderRequest, OrderStatus, Side};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = Config::default();

    let (bus, rx) = EventBus::new(config.event_bus_capacity);
    let (persistence, persistence_rx) = PersistenceWriter::new(config.persistence_buffer);

    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 100,
        max_abs_position_per_symbol: 1000,
        trading_enabled: true,
    });

    let oms = Oms::new();
    let portfolio = Portfolio::new();

    let strategy: SharedStrategy = Arc::new(SimpleMakerTakerStrategy {
        order_qty: 10,
        max_spread: 2,
    });

    let exchange = Arc::new(SimExchange::new(1024));
    let execution = ExecutionEngine::new(exchange.clone());

    tokio::spawn(run_persistence(persistence_rx));
    tokio::spawn(market_data::run_market_data(bus.clone()));

    {
        let adapter = execution.adapter();
        let bus_clone = bus.clone();
        tokio::spawn(async move {
            while let Some(report) = adapter.next_execution_report().await {
                let _ = bus_clone.publish(Event::ExecutionReport(report));
            }
        });
    }

    let event_loop = {
        let persistence = persistence.clone();
        let risk = risk.clone();
        let oms = oms.clone();
        let portfolio = portfolio.clone();
        let strategy = strategy.clone();
        let execution = execution.clone();

        thread::spawn(move || {
            while let Ok(event) = rx.recv() {
                match event.clone() {
                    Event::Market(tick) => {
                        portfolio.update_last_price(&tick.symbol, tick.last);

                        if let Some(req) = strategy.on_tick(&tick) {
                            if let OrderRequest::New(order) = &req {
                                match risk.check_order(order) {
                                    Ok(_) => {
                                        oms.register_new(order.clone());
                                        let exec = execution.clone();
                                        tokio::runtime::Handle::current().block_on(async move {
                                            exec.send(req).await;
                                        });
                                    }
                                    Err(e) => {
                                        error!("risk rejected order {}: {}", order.order_id, e);
                                    }
                                }
                            }
                        }
                    }
                    Event::ExecutionReport(report) => {
                        oms.on_execution_report(&report);

                        if matches!(report.status, OrderStatus::Filled | OrderStatus::PartiallyFilled)
                        {
                            if let Some((side, symbol)) = oms.get_order_side_symbol(&report.order_id) {
                                let signed_qty = report.filled_qty;
                                match side {
                                    Side::Buy => {
                                        risk.apply_fill(&symbol, &Side::Buy, signed_qty);
                                        portfolio.update_position(&symbol, signed_qty);
                                    }
                                    Side::Sell => {
                                        risk.apply_fill(&symbol, &Side::Sell, signed_qty);
                                        portfolio.update_position(&symbol, -signed_qty);
                                    }
                                }
                            }
                        }

                        let pnl = portfolio.snapshot_pnl();
                        info!("portfolio mtm pnl: {}", pnl);
                    }
                    Event::OrderRequest(_) => {}
                    Event::Shutdown => break,
                }

                tokio::runtime::Handle::current().block_on(async {
                    persistence.write(event).await;
                });
            }
        })
    };

    let _ = tokio::signal::ctrl_c().await;
    let _ = bus.publish(Event::Shutdown);
    let _ = event_loop.join();
    info!("shutdown complete");
}
```

