pub struct EventBus {
    pub market_tx: broadcast::Sender<MarketTick>,
    pub order_tx: broadcast::Sender<OrderRequest>,
    pub exec_tx: broadcast::Sender<ExecutionReport>,
    pub pos_tx: broadcast::Sender<PositionUpdate>,
}

impl EventBus {
    pub fn new(buffer: usize) -> Self {
        let (market_tx, _) = broadcast::channel(buffer);
        let (order_tx, _) = broadcast::channel(buffer);
        let (exec_tx, _) = broadcast::channel(buffer);
        let (pos_tx, _) = broadcast::channel(buffer);

        Self {
            market_tx,
            order_tx,
            exec_tx,
            pos_tx,
        }
    }
}
