# src/strategy.rs

Simple example strategy: buy if spread is small and price is below threshold.

```rust
use rust_decimal::Decimal;
use std::str::FromStr;
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};
use uuid::Uuid;

use crate::bus::EventBus;
use crate::types::{OrderRequest, OrderType, Side};

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

pub async fn run_strategy(bus: EventBus) {
    let mut market_rx = bus.market_tx.subscribe();

    loop {
        match market_rx.recv().await {
            Ok(tick) => {
                let spread = tick.ask - tick.bid;
                let threshold = Decimal::from_str("100.50").unwrap();

                if spread <= Decimal::from_str("0.03").unwrap() && tick.ask < threshold {
                    let order = OrderRequest {
                        order_id: Uuid::new_v4(),
                        symbol: tick.symbol.clone(),
                        side: Side::Buy,
                        qty: Decimal::from_str("10").unwrap(),
                        order_type: OrderType::Limit,
                        limit_price: Some(tick.ask),
                        ts_nanos: now_nanos(),
                    };

                    let _ = bus.order_tx.send(order.clone());
                    info!("strategy emitted order: {:?}", order);
                }
            }
            Err(RecvError::Lagged(n)) => {
                warn!("strategy lagged by {} messages", n);
            }
            Err(RecvError::Closed) => break,
        }
    }
}
```

