# src/risk.rs

Risk checks should be fast and deterministic.

```rust
use rust_decimal::Decimal;
use std::collections::HashMap;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::types::{OrderRequest, Side};

pub async fn run_risk(bus: EventBus) {
    let mut order_rx = bus.order_tx.subscribe();
    let mut approved_orders: HashMap<String, Decimal> = HashMap::new();
    let max_position = Decimal::new(1000, 0);

    loop {
        match order_rx.recv().await {
            Ok(order) => {
                let current = approved_orders
                    .get(&order.symbol)
                    .cloned()
                    .unwrap_or(Decimal::ZERO);

                let proposed = match order.side {
                    Side::Buy => current + order.qty,
                    Side::Sell => current - order.qty,
                };

                if proposed.abs() <= max_position {
                    approved_orders.insert(order.symbol.clone(), proposed);
                    let _ = bus.exec_tx.send(crate::types::ExecutionReport {
                        order_id: order.order_id,
                        symbol: order.symbol.clone(),
                        status: crate::types::OrderStatus::Accepted,
                        filled_qty: Decimal::ZERO,
                        avg_price: None,
                        ts_nanos: order.ts_nanos,
                    });
                    info!("risk approved order {:?}", order.order_id);
                } else {
                    let _ = bus.exec_tx.send(crate::types::ExecutionReport {
                        order_id: order.order_id,
                        symbol: order.symbol.clone(),
                        status: crate::types::OrderStatus::Rejected(
                            "max position exceeded".to_string(),
                        ),
                        filled_qty: Decimal::ZERO,
                        avg_price: None,
                        ts_nanos: order.ts_nanos,
                    });
                    warn!("risk rejected order {:?}", order.order_id);
                }
            }
            Err(RecvError::Lagged(n)) => warn!("risk lagged by {}", n),
            Err(RecvError::Closed) => break,
        }
    }
}
```

