# src/oms.rs

The OMS tracks orders and forwards accepted ones to execution.

```rust
use std::collections::HashMap;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};
use uuid::Uuid;

use crate::bus::EventBus;
use crate::types::{ExecutionReport, OrderRequest, OrderStatus};

pub async fn run_oms(bus: EventBus) {
    let mut order_rx = bus.order_tx.subscribe();
    let mut exec_rx = bus.exec_tx.subscribe();

    let mut orders: HashMap<Uuid, OrderRequest> = HashMap::new();

    loop {
        tokio::select! {
            msg = order_rx.recv() => {
                match msg {
                    Ok(order) => {
                        orders.insert(order.order_id, order.clone());
                        info!("oms registered order {:?}", order.order_id);
                    }
                    Err(RecvError::Lagged(n)) => warn!("oms order lagged by {}", n),
                    Err(RecvError::Closed) => break,
                }
            }
            msg = exec_rx.recv() => {
                match msg {
                    Ok(report) => {
                        match &report.status {
                            OrderStatus::Accepted => {
                                if let Some(order) = orders.get(&report.order_id) {
                                    let _ = bus.order_tx.send(order.clone());
                                    info!("oms forwarded order {:?} to execution path", order.order_id);
                                }
                            }
                            _ => {
                                info!("oms received execution report {:?}", report);
                            }
                        }
                    }
                    Err(RecvError::Lagged(n)) => warn!("oms exec lagged by {}", n),
                    Err(RecvError::Closed) => break,
                }
            }
        }
    }
}
```

