# src/execution.rs

In real life this would speak FIX, OUCH, ITCH, WebSocket, REST, or native exchange APIs.

```rust
use rust_decimal::Decimal;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::types::{ExecutionReport, OrderStatus};

pub async fn run_execution(bus: EventBus) {
    let mut order_rx = bus.order_tx.subscribe();

    loop {
        match order_rx.recv().await {
            Ok(order) => {
                if order.limit_price.is_some() {
                    let fill = ExecutionReport {
                        order_id: order.order_id,
                        symbol: order.symbol.clone(),
                        status: OrderStatus::Filled,
                        filled_qty: order.qty,
                        avg_price: order.limit_price,
                        ts_nanos: order.ts_nanos,
                    };

                    let _ = bus.exec_tx.send(fill.clone());
                    info!("execution filled order: {:?}", fill);
                } else {
                    let reject = ExecutionReport {
                        order_id: order.order_id,
                        symbol: order.symbol.clone(),
                        status: OrderStatus::Rejected("missing price".to_string()),
                        filled_qty: Decimal::ZERO,
                        avg_price: None,
                        ts_nanos: order.ts_nanos,
                    };

                    let _ = bus.exec_tx.send(reject.clone());
                    warn!("execution rejected order: {:?}", reject);
                }
            }
            Err(RecvError::Lagged(n)) => warn!("execution lagged by {}", n),
            Err(RecvError::Closed) => break,
        }
    }
}
