# src/position.rs

Tracks positions from fills.

```rust
use rust_decimal::Decimal;
use std::collections::HashMap;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::types::{OrderStatus, PositionUpdate};

#[derive(Debug, Clone)]
struct Position {
    net_qty: Decimal,
    avg_price: Decimal,
    realized_pnl: Decimal,
}

pub async fn run_position_manager(bus: EventBus) {
    let mut exec_rx = bus.exec_tx.subscribe();
    let mut positions: HashMap<String, Position> = HashMap::new();

    loop {
        match exec_rx.recv().await {
            Ok(report) => {
                if let OrderStatus::Filled = report.status {
                    let pos = positions.entry(report.symbol.clone()).or_insert(Position {
                        net_qty: Decimal::ZERO,
                        avg_price: Decimal::ZERO,
                        realized_pnl: Decimal::ZERO,
                    });

                    let fill_qty = report.filled_qty;
                    let fill_px = report.avg_price.unwrap_or(Decimal::ZERO);

                    let new_qty = pos.net_qty + fill_qty;
                    if new_qty != Decimal::ZERO {
                        pos.avg_price = ((pos.avg_price * pos.net_qty) + (fill_px * fill_qty)) / new_qty;
                    }
                    pos.net_qty = new_qty;

                    let update = PositionUpdate {
                        symbol: report.symbol.clone(),
                        net_qty: pos.net_qty,
                        avg_price: pos.avg_price,
                        realized_pnl: pos.realized_pnl,
                        unrealized_pnl: Decimal::ZERO,
                    };

                    let _ = bus.pos_tx.send(update.clone());
                    info!("position updated: {:?}", update);
                }
            }
            Err(RecvError::Lagged(n)) => warn!("position lagged by {}", n),
            Err(RecvError::Closed) => break,
        }
    }
}
```

