# 8. Strategy engine

This example strategy buys if spread is small and price is rising. It is intentionally simple.

## `src/strategy.rs`

```rust
use chrono::Utc;
use std::collections::HashMap;
use uuid::Uuid;

use crate::bus::EventBus;
use crate::types::{Event, MarketTick, OrderRequest, OrderType, Side};

pub struct StrategyEngine {
    last_mid: HashMap<String, f64>,
}

impl StrategyEngine {
    pub fn new() -> Self {
        Self {
            last_mid: HashMap::new(),
        }
    }

    pub fn on_tick(&mut self, tick: MarketTick, bus: &EventBus) {
        let mid = (tick.bid + tick.ask) * 0.5;
        let prev = self.last_mid.get(&tick.symbol).copied();

        if let Some(prev_mid) = prev {
            if mid > prev_mid && (tick.ask - tick.bid) <= 0.05 {
                let order = OrderRequest {
                    id: Uuid::new_v4(),
                    symbol: tick.symbol.clone(),
                    side: Side::Buy,
                    qty: 10.0,
                    order_type: OrderType::Limit { price: tick.ask },
                    ts: Utc::now(),
                };
                bus.publish(Event::NewOrder(order));
            }
        }

        self.last_mid.insert(tick.symbol, mid);
    }
}
```

