# 9. Risk engine

This is where you enforce max order size, notional, positions, kill switch, etc.

## `src/risk.rs`

```rust
use crate::types::{OrderRequest, OrderType};

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
        }
    }

    pub fn validate(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("quantity must be positive".to_string());
        }

        if order.qty > self.max_order_qty {
            return Err(format!(
                "order qty {} exceeds max {}",
                order.qty, self.max_order_qty
            ));
        }

        let price = match order.order_type {
            OrderType::Market => 0.0,
            OrderType::Limit { price } => price,
        };

        if price * order.qty > self.max_notional {
            return Err(format!(
                "notional {} exceeds max {}",
                price * order.qty,
                self.max_notional
            ));
        }

        Ok(())
    }
}
```

