use dashmap::DashMap;
use uuid::Uuid;

use crate::types::{ExecutionReport, OrderRequest, OrderStatus};

pub struct Oms {
    pub orders: DashMap<Uuid, OrderStatus>,
    pub requests: DashMap<Uuid, OrderRequest>,
}

impl Oms {
    pub fn new() -> Self {
        Self {
            orders: DashMap::new(),
            requests: DashMap::new(),
        }
    }

    pub fn on_new_order(&self, order: OrderRequest) {
        self.orders.insert(order.id, OrderStatus::PendingNew);
        self.requests.insert(order.id, order);
    }

    pub fn on_execution(&self, exec: &ExecutionReport) {
        self.orders.insert(exec.order_id, exec.status.clone());
    }
}
