# 11. Execution gateway

This simulates exchange acceptance/fill. Real implementation would speak FIX, REST, WebSocket, OUCH, etc.

## `src/execution.rs`

```rust
use chrono::Utc;
use tokio::time::{sleep, Duration};

use crate::bus::EventBus;
use crate::types::{Event, ExecutionReport, OrderRequest, OrderStatus};

pub async fn send_order(order: OrderRequest, bus: EventBus) {
    let accepted = ExecutionReport {
        order_id: order.id,
        status: OrderStatus::Accepted,
        filled_qty: 0.0,
        remaining_qty: order.qty,
        avg_price: None,
        ts: Utc::now(),
    };

    bus.publish(Event::Execution(accepted));

    sleep(Duration::from_millis(5)).await;

    let fill_price = match order.order_type {
        crate::types::OrderType::Market => 100.0,
        crate::types::OrderType::Limit { price } => price,
    };

    let filled = ExecutionReport {
        order_id: order.id,
        status: OrderStatus::Filled,
        filled_qty: order.qty,
        remaining_qty: 0.0,
        avg_price: Some(fill_price),
        ts: Utc::now(),
    };

    bus.publish(Event::Execution(filled));
}
```

