# 12. Position service

## `src/position.rs`

```rust
use dashmap::DashMap;
use crate::types::{ExecutionReport, OrderStatus, Side};
use crate::oms::Oms;

pub struct PositionService {
    pub positions: DashMap<String, f64>,
}

impl PositionService {
    pub fn new() -> Self {
        Self {
            positions: DashMap::new(),
        }
    }

    pub fn on_execution(&self, exec: &ExecutionReport, oms: &Oms) {
        if !matches!(exec.status, OrderStatus::Filled | OrderStatus::PartiallyFilled) {
            return;
        }

        if let Some(order) = oms.requests.get(&exec.order_id) {
            let signed_qty = match order.side {
                Side::Buy => exec.filled_qty,
                Side::Sell => -exec.filled_qty,
            };

            self.positions
                .entry(order.symbol.clone())
                .and_modify(|p| *p += signed_qty)
                .or_insert(signed_qty);
        }
    }
}
```

