# 13. Main event loop

This wires the components together.

## `src/main.rs`

```rust
mod bus;
mod execution;
mod market_data;
mod oms;
mod position;
mod risk;
mod strategy;
mod types;

use bus::EventBus;
use crossbeam::channel::Receiver;
use oms::Oms;
use position::PositionService;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tokio::task;
use tracing::{error, info};
use types::Event;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt::init();

    let (bus, rx): (EventBus, Receiver<Event>) = EventBus::new();

    let risk = RiskEngine::new(1000.0, 1_000_000.0);
    let oms = Oms::new();
    let positions = PositionService::new();
    let mut strategy = StrategyEngine::new();

    let md_bus = bus.clone();
    task::spawn(async move {
        market_data::run_market_data(md_bus).await;
    });

    event_loop(rx, bus, risk, oms, positions, &mut strategy).await;
}

async fn event_loop(
    rx: Receiver<Event>,
    bus: EventBus,
    risk: RiskEngine,
    oms: Oms,
    positions: PositionService,
    strategy: &mut StrategyEngine,
) {
    loop {
        match rx.recv() {
            Ok(event) => match event {
                Event::Market(tick) => {
                    strategy.on_tick(tick, &bus);
                }
                Event::NewOrder(order) => {
                    match risk.validate(&order) {
                        Ok(()) => {
                            info!("order accepted by risk: {:?}", order.id);
                            oms.on_new_order(order.clone());

                            let exec_bus = bus.clone();
                            tokio::spawn(async move {
                                execution::send_order(order, exec_bus).await;
                            });
                        }
                        Err(reason) => {
                            error!("risk rejected order {}: {}", order.id, reason);
                        }
                    }
                }
                Event::Execution(exec) => {
                    oms.on_execution(&exec);
                    positions.on_execution(&exec, &oms);
                    info!("execution report: {:?}", exec);
                }
            },
            Err(_) => break,
        }
    }
}
```

