## Example strategy: simple spread-crossing strategy

```java
package com.yourorg.trading.strategy;

import com.yourorg.trading.common.model.*;

import java.util.concurrent.atomic.AtomicLong;

public final class SimpleAggressiveStrategy implements TradingStrategy {
    private final AtomicLong orderIdGenerator = new AtomicLong(1);
    private final Instrument instrument;
    private final long buyThresholdPrice;
    private final long orderQty;

    public SimpleAggressiveStrategy(Instrument instrument, long buyThresholdPrice, long orderQty) {
        this.instrument = instrument;
        this.buyThresholdPrice = buyThresholdPrice;
        this.orderQty = orderQty;
    }

    @Override
    public OrderRequest onMarketData(MarketDataTick tick) {
        if (!instrument.equals(tick.instrument())) {
            return null;
        }

        if (tick.askPrice() <= buyThresholdPrice) {
            return new OrderRequest(
                    orderIdGenerator.getAndIncrement(),
                    instrument,
                    Side.BUY,
                    OrderType.LIMIT,
                    orderQty,
                    tick.askPrice(),
                    System.nanoTime()
            );
        }

        return null;
    }
}
```

