package com.yourorg.trading.risk;

import com.yourorg.trading.common.model.OrderRequest;

public final class BasicRiskEngine implements RiskEngine {
    private final long maxOrderQty;
    private final long maxNotional;
    private volatile boolean tradingEnabled = true;

    public BasicRiskEngine(long maxOrderQty, long maxNotional) {
        this.maxOrderQty = maxOrderQty;
        this.maxNotional = maxNotional;
    }

    @Override
    public RiskCheckResult check(OrderRequest order) {
        if (!tradingEnabled) {
            return RiskCheckResult.reject("Trading disabled");
        }
        if (order.quantity() <= 0) {
            return RiskCheckResult.reject("Invalid quantity");
        }
        if (order.quantity() > maxOrderQty) {
            return RiskCheckResult.reject("Quantity exceeds limit");
        }
        long notional = order.quantity() * order.price();
        if (notional > maxNotional) {
            return RiskCheckResult.reject("Notional exceeds limit");
        }
        return RiskCheckResult.accept();
    }

    public void disableTrading() {
        tradingEnabled = false;
    }

    public void enableTrading() {
        tradingEnabled = true;
    }
}
