# 12. Core trading engine

This is the single-threaded hot-path orchestrator.  
That is intentional: **single-threaded core often beats heavily locked multi-threaded designs in latency-sensitive systems**.

## `TradingEngine.java`

```java
package com.yourorg.trading.app;

import com.yourorg.trading.common.event.EventType;
import com.yourorg.trading.common.model.*;
import com.yourorg.trading.execution.ExecutionGateway;
import com.yourorg.trading.oms.OrderManager;
import com.yourorg.trading.persistence.EventStore;
import com.yourorg.trading.risk.RiskCheckResult;
import com.yourorg.trading.risk.RiskEngine;
import com.yourorg.trading.strategy.TradingStrategy;

public final class TradingEngine {
    private final TradingStrategy strategy;
    private final RiskEngine riskEngine;
    private final OrderManager orderManager;
    private final ExecutionGateway executionGateway;
    private final EventStore eventStore;

    public TradingEngine(
            TradingStrategy strategy,
            RiskEngine riskEngine,
            OrderManager orderManager,
            ExecutionGateway executionGateway,
            EventStore eventStore) {
        this.strategy = strategy;
        this.riskEngine = riskEngine;
        this.orderManager = orderManager;
        this.executionGateway = executionGateway;
        this.eventStore = eventStore;
    }

    public void onMarketData(MarketDataTick tick) {
        eventStore.append("MD|" + tick.instrument() + "|" + tick.bidPrice() + "|" + tick.askPrice());

        OrderRequest order = strategy.onMarketData(tick);
        if (order == null) {
            return;
        }

        RiskCheckResult risk = riskEngine.check(order);
        if (!risk.accepted()) {
            ExecutionReport reject = new ExecutionReport(
                    order.orderId(),
                    OrderStatus.REJECTED,
                    0,
                    order.quantity(),
                    0,
                    risk.reason(),
                    System.nanoTime()
            );
            orderManager.onNewOrder(order);
            orderManager.onExecutionReport(reject);
            eventStore.append("REJECT|" + order.orderId() + "|" + risk.reason());
            return;
        }

        orderManager.onNewOrder(order);
        eventStore.append("ORDER|" + order.orderId() + "|" + order.instrument() + "|" + order.side());

        ExecutionReport report = executionGateway.send(order);
        orderManager.onExecutionReport(report);
        eventStore.append("EXEC|" + report.orderId() + "|" + report.status());
    }
}
```

