# 2. Risk engine

This is a synchronous in-memory pre-trade risk check.

## `crates/risk/src/lib.rs`

```rust
use common::{AccountId, InstrumentId, NewOrderRequest, Qty, Side};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Qty,
    pub max_position_abs: Qty,
    pub max_notional: i64,
}

#[derive(Debug, Default, Clone)]
pub struct PositionState {
    pub net_qty: Qty,
}

#[derive(Debug, Default)]
pub struct RiskEngine {
    account_limits: HashMap<AccountId, RiskLimits>,
    positions: HashMap<(AccountId, InstrumentId), PositionState>,
}

#[derive(Debug)]
pub enum RiskRejectReason {
    MissingLimitConfig,
    OrderQtyTooLarge,
    PriceRequiredForNotionalCheck,
    NotionalTooLarge,
    PositionLimitExceeded,
}

impl RiskEngine {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_limit(&mut self, account_id: AccountId, limits: RiskLimits) {
        self.account_limits.insert(account_id, limits);
    }

    pub fn apply_fill(
        &mut self,
        account_id: AccountId,
        instrument_id: InstrumentId,
        side: Side,
        fill_qty: Qty,
    ) {
        let pos = self.positions.entry((account_id, instrument_id)).or_default();
        match side {
            Side::Buy => pos.net_qty += fill_qty,
            Side::Sell => pos.net_qty -= fill_qty,
        }
    }

    pub fn check_order(&self, order: &NewOrderRequest) -> Result<(), RiskRejectReason> {
        let limits = self
            .account_limits
            .get(&order.account_id)
            .ok_or(RiskRejectReason::MissingLimitConfig)?;

        if order.qty.abs() > limits.max_order_qty.abs() {
            return Err(RiskRejectReason::OrderQtyTooLarge);
        }

        let px = order.price.ok_or(RiskRejectReason::PriceRequiredForNotionalCheck)?;
        let notional = px.saturating_mul(order.qty.abs());
        if notional > limits.max_notional {
            return Err(RiskRejectReason::NotionalTooLarge);
        }

        let current = self
            .positions
            .get(&(order.account_id, order.instrument_id))
            .map(|p| p.net_qty)
            .unwrap_or(0);

        let projected = match order.side {
            Side::Buy => current + order.qty,
            Side::Sell => current - order.qty,
        };

        if projected.abs() > limits.max_position_abs {
            return Err(RiskRejectReason::PositionLimitExceeded);
        }

        Ok(())
    }
}
```

