# 3. Order manager

The OMS receives orders, runs risk checks, tracks state, and forwards accepted orders to the execution gateway.

## `crates/oms/src/lib.rs`

```rust
use common::{
    now_nanos, Event, NewOrderRequest, OrderAck, OrderId, OrderStatus,
};
use risk::RiskEngine;
use std::collections::HashMap;
use tokio::sync::mpsc;

#[derive(Debug, Clone)]
pub struct ManagedOrder {
    pub req: NewOrderRequest,
    pub status: OrderStatus,
}

pub struct OrderManager {
    risk: RiskEngine,
    orders: HashMap<OrderId, ManagedOrder>,
    exec_tx: mpsc::Sender<NewOrderRequest>,
    event_tx: mpsc::Sender<Event>,
}

impl OrderManager {
    pub fn new(
        risk: RiskEngine,
        exec_tx: mpsc::Sender<NewOrderRequest>,
        event_tx: mpsc::Sender<Event>,
    ) -> Self {
        Self {
            risk,
            orders: HashMap::new(),
            exec_tx,
            event_tx,
        }
    }

    pub async fn on_new_order(&mut self, order: NewOrderRequest) {
        let ack = match self.risk.check_order(&order) {
            Ok(()) => {
                self.orders.insert(
                    order.order_id,
                    ManagedOrder {
                        req: order.clone(),
                        status: OrderStatus::Accepted,
                    },
                );

                if self.exec_tx.send(order.clone()).await.is_err() {
                    OrderAck {
                        order_id: order.order_id,
                        status: OrderStatus::Rejected,
                        reason: Some("Execution gateway unavailable".to_string()),
                        ts: now_nanos(),
                    }
                } else {
                    OrderAck {
                        order_id: order.order_id,
                        status: OrderStatus::Accepted,
                        reason: None,
                        ts: now_nanos(),
                    }
                }
            }
            Err(reason) => OrderAck {
                order_id: order.order_id,
                status: OrderStatus::Rejected,
                reason: Some(format!("{reason:?}")),
                ts: now_nanos(),
            },
        };

        let _ = self.event_tx.send(Event::OrderAck(ack)).await;
    }
}
```

