# 4. Execution gateway

This is where exchange connectivity would go. For now, we simulate exchange acknowledgments/fills.

## `crates/gateway/src/lib.rs`

```rust
use common::{now_nanos, Event, FillEvent, NewOrderRequest};
use tokio::sync::mpsc;
use tokio::time::{sleep, Duration};

pub struct ExecutionGateway {
    rx: mpsc::Receiver<NewOrderRequest>,
    event_tx: mpsc::Sender<Event>,
}

impl ExecutionGateway {
    pub fn new(
        rx: mpsc::Receiver<NewOrderRequest>,
        event_tx: mpsc::Sender<Event>,
    ) -> Self {
        Self { rx, event_tx }
    }

    pub async fn run(mut self) {
        while let Some(order) = self.rx.recv().await {
            sleep(Duration::from_millis(1)).await;

            let fill = FillEvent {
                order_id: order.order_id,
                instrument_id: order.instrument_id,
                fill_qty: order.qty,
                fill_price: order.price.unwrap_or(0),
                leaves_qty: 0,
                ts: now_nanos(),
            };

            let _ = self.event_tx.send(Event::Fill(fill)).await;
        }
    }
}
```

