# 5. Strategy engine

A simple example market-making or threshold strategy.

## `crates/strategy/src/lib.rs`

```rust
use common::{
    now_nanos, MarketTick, NewOrderRequest, OrderType, Side, StrategyId, TimeInForce,
};
use std::sync::atomic::{AtomicU64, Ordering};

pub struct SimpleStrategy {
    strategy_id: StrategyId,
    account_id: u64,
    next_order_id: AtomicU64,
    instrument_id: u32,
    threshold: i64,
    order_qty: i64,
}

impl SimpleStrategy {
    pub fn new(
        strategy_id: StrategyId,
        account_id: u64,
        instrument_id: u32,
        threshold: i64,
        order_qty: i64,
    ) -> Self {
        Self {
            strategy_id,
            account_id,
            next_order_id: AtomicU64::new(1),
            instrument_id,
            threshold,
            order_qty,
        }
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<NewOrderRequest> {
        if tick.instrument_id != self.instrument_id {
            return None;
        }

        let mid = (tick.bid + tick.ask) / 2;

        if tick.last < mid - self.threshold {
            Some(NewOrderRequest {
                order_id: self.next_order_id.fetch_add(1, Ordering::Relaxed),
                strategy_id: self.strategy_id,
                account_id: self.account_id,
                instrument_id: tick.instrument_id,
                side: Side::Buy,
                order_type: OrderType::Limit,
                tif: TimeInForce::IOC,
                price: Some(tick.ask),
                qty: self.order_qty,
                ts_created: now_nanos(),
            })
        } else if tick.last > mid + self.threshold {
            Some(NewOrderRequest {
                order_id: self.next_order_id.fetch_add(1, Ordering::Relaxed),
                strategy_id: self.strategy_id,
                account_id: self.account_id,
                instrument_id: tick.instrument_id,
                side: Side::Sell,
                order_type: OrderType::Limit,
                tif: TimeInForce::IOC,
                price: Some(tick.bid),
                qty: self.order_qty,
                ts_created: now_nanos(),
            })
        } else {
            None
        }
    }
}
