use tokio::sync::mpsc;

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() {
    let (md_tx, mut md_rx) = mpsc::channel::<MarketTick>(1024);
    let (exec_tx, exec_rx) = mpsc::channel(1024);
    let (event_tx, mut event_rx) = mpsc::channel::<Event>(4096);

    let mut risk = RiskEngine::new();
    risk.set_limit(
        1,
        RiskLimits {
            max_order_qty: 1_000,
            max_position_abs: 10_000,
            max_notional: 1_000_000_000,
        },
    );

    let mut oms = OrderManager::new(risk, exec_tx, event_tx.clone());
    let strategy = SimpleStrategy::new(1, 1, 1001, 5, 100);

    tokio::spawn(async move {
        MarketDataFeed::new(md_tx, 1001).run().await;
    });

    tokio::spawn(async move {
        ExecutionGateway::new(exec_rx, event_tx).run().await;
    });

    let event_task = tokio::spawn(async move {
        while let Some(event) = event_rx.recv().await {
            println!("EVENT: {:?}", event);
