# 9. Strategy engine

## `src/strategy.rs`

This is intentionally simple: buy if spread is tight and price moved down, sell if moved up.

```rust
use crate::types::{now_ns, MarketTick, Side, Signal, StrategyId};
use crossbeam::channel::{Receiver, Sender};

pub struct StrategyEngine {
    pub strategy_id: StrategyId,
    pub md_in: Receiver<MarketTick>,
    pub signal_out: Sender<Signal>,
}

impl StrategyEngine {
    pub fn run(self) {
        let mut last_mid: Option<i64> = None;

        while let Ok(tick) = self.md_in.recv() {
            let mid = (tick.bid + tick.ask) / 2;
            let spread = tick.ask - tick.bid;

            let signal = if let Some(prev) = last_mid {
                if spread <= 10 && mid < prev - 3 {
                    Some(Signal {
                        strategy_id: self.strategy_id,
                        symbol: tick.symbol,
                        side: Side::Buy,
                        price: tick.ask,
                        qty: 10,
                        ts_ns: now_ns(),
                    })
                } else if spread <= 10 && mid > prev + 3 {
                    Some(Signal {
                        strategy_id: self.strategy_id,
                        symbol: tick.symbol,
                        side: Side::Sell,
                        price: tick.bid,
                        qty: 10,
                        ts_ns: now_ns(),
                    })
                } else {
                    None
                }
            } else {
                None
            };

            last_mid = Some(mid);

            if let Some(sig) = signal {
                if self.signal_out.send(sig).is_err() {
                    break;
                }
            }
        }
    }
}
```

