# 10. Risk engine

## `src/risk.rs`

This does simple position limit checks. In production, this must be much more comprehensive.

```rust
use crate::types::{OrderRequest, Qty, Side, Signal, SymbolId};
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;

pub struct RiskEngine {
    pub signal_in: Receiver<Signal>,
    pub order_out: Sender<OrderRequest>,
    pub max_abs_position: i64,
}

impl RiskEngine {
    pub fn run(self) {
        let mut next_order_id: u64 = 1;
        let mut positions: HashMap<SymbolId, i64> = HashMap::new();

        while let Ok(sig) = self.signal_in.recv() {
            let pos = *positions.get(&sig.symbol).unwrap_or(&0);
            let delta = match sig.side {
                Side::Buy => sig.qty as i64,
                Side::Sell => -(sig.qty as i64),
            };

            let new_pos = pos + delta;
            if new_pos.abs() > self.max_abs_position {
                continue;
            }

            positions.insert(sig.symbol, new_pos);

            let req = OrderRequest {
                strategy_id: sig.strategy_id,
                order_id: next_order_id,
                symbol: sig.symbol,
                side: sig.side,
                price: sig.price,
                qty: sig.qty as Qty,
                ts_ns: sig.ts_ns,
            };

            next_order_id += 1;

            if self.order_out.send(req).is_err() {
                break;
            }
        }
    }
}
```

