# 11. OMS

## `src/oms.rs`

Tracks order state transitions.

```rust
use crate::types::{ExecutionReport, OrderId, OrderRequest, OrderStatus};
use crossbeam::channel::{Receiver, Sender};
use std::collections::HashMap;

#[derive(Debug, Clone, Copy)]
pub struct OrderState {
    pub req: OrderRequest,
    pub status: OrderStatus,
    pub filled_qty: u64,
}

pub struct Oms {
    pub order_in: Receiver<OrderRequest>,
    pub exec_in: Receiver<ExecutionReport>,
    pub order_out: Sender<OrderRequest>,
}

impl Oms {
    pub fn run(self) {
        let mut orders: HashMap<OrderId, OrderState> = HashMap::new();

        loop {
            crossbeam::select! {
                recv(self.order_in) -> msg => {
                    match msg {
                        Ok(req) => {
                            orders.insert(req.order_id, OrderState {
                                req,
                                status: OrderStatus::New,
                                filled_qty: 0,
                            });

                            if self.order_out.send(req).is_err() {
                                break;
                            }
                        }
                        Err(_) => break,
                    }
                }
                recv(self.exec_in) -> msg => {
                    match msg {
                        Ok(exec) => {
                            if let Some(state) = orders.get_mut(&exec.order_id) {
                                state.status = exec.status;
                                state.filled_qty = exec.filled_qty;
                            }
                            println!("OMS EXEC: {:?}", exec);
                        }
                        Err(_) => break,
                    }
                }
            }
        }
    }
}
```

