# 12. Execution gateway

## `src/execution.rs`

This simulates exchange acknowledgements/fills.

```rust
use crate::types::{now_ns, ExecutionReport, OrderRequest, OrderStatus};
use crossbeam::channel::{Receiver, Sender};
use std::{thread, time::Duration};

pub struct ExecutionGateway {
    pub order_in: Receiver<OrderRequest>,
    pub exec_out: Sender<ExecutionReport>,
}

impl ExecutionGateway {
    pub fn run(self) {
        while let Ok(req) = self.order_in.recv() {
            let ack = ExecutionReport {
                order_id: req.order_id,
                symbol: req.symbol,
                status: OrderStatus::Acked,
                filled_qty: 0,
                remaining_qty: req.qty,
                last_px: req.price,
                ts_ns: now_ns(),
            };

            if self.exec_out.send(ack).is_err() {
                break;
            }

            thread::sleep(Duration::from_micros(50));

            let fill = ExecutionReport {
                order_id: req.order_id,
                symbol: req.symbol,
                status: OrderStatus::Filled,
                filled_qty: req.qty,
                remaining_qty: 0,
                last_px: req.price,
                ts_ns: now_ns(),
            };

            if self.exec_out.send(fill).is_err() {
                break;
            }
        }
    }
}
```

