use crate::types::Event;
use std::fs::OpenOptions;
use std::io::Write;

pub struct Journal {
    file: std::fs::File,
}

impl Journal {
    pub fn new(path: &str) -> std::io::Result<Self> {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        Ok(Self { file })
    }

    pub fn append(&mut self, event: &Event) -> std::io::Result<()> {
        writeln!(self.file, "{:?}", event)
    }
}
