# 8. Strategy engine

Simple example strategy:
- buy if price crosses above threshold
- sell if price crosses below threshold

## `src/strategy.rs`

```rust
use crate::types::{Event, OrderRequest, OrderType, Side};
use chrono::Utc;
use crossbeam_channel::{Receiver, Sender};
use uuid::Uuid;

pub struct ThresholdStrategy {
    pub strategy_id: String,
    pub symbol: String,
    pub buy_above: f64,
    pub sell_below: f64,
    pub qty: u64,
    rx_market: Receiver<Event>,
    tx_risk: Sender<Event>,
}

impl ThresholdStrategy {
    pub fn new(
        strategy_id: String,
        symbol: String,
        buy_above: f64,
        sell_below: f64,
        qty: u64,
        rx_market: Receiver<Event>,
        tx_risk: Sender<Event>,
    ) -> Self {
        Self {
            strategy_id,
            symbol,
            buy_above,
            sell_below,
            qty,
            rx_market,
            tx_risk,
        }
    }

    pub fn start(self) {
        std::thread::spawn(move || {
            while let Ok(event) = self.rx_market.recv() {
                if let Event::MarketTick(tick) = event {
                    if tick.symbol != self.symbol {
                        continue;
                    }

                    let maybe_order = if tick.last > self.buy_above {
                        Some(OrderRequest {
                            id: Uuid::new_v4(),
                            symbol: tick.symbol.clone(),
                            side: Side::Buy,
                            qty: self.qty,
                            order_type: OrderType::Market,
                            price: None,
                            ts_created: Utc::now(),
                            strategy_id: self.strategy_id.clone(),
                        })
                    } else if tick.last < self.sell_below {
                        Some(OrderRequest {
                            id: Uuid::new_v4(),
                            symbol: tick.symbol.clone(),
                            side: Side::Sell,
                            qty: self.qty,
                            order_type: OrderType::Market,
                            price: None,
                            ts_created: Utc::now(),
                            strategy_id: self.strategy_id.clone(),
                        })
                    } else {
                        None
                    };

                    if let Some(order) = maybe_order {
                        let _ = self.tx_risk.send(Event::OrderRequest(order));
                    }
                }
            }
        });
    }
}
```

