# 9. Risk engine

This is critical. Even a simple version should:
- enforce max order size
- enforce max net position
- reject invalid orders

## `src/risk.rs`

```rust
use crate::types::{Event, OrderRequest, OrderStatus, OrderUpdate, Position, Side};
use chrono::Utc;
use crossbeam_channel::{Receiver, Sender};
use std::collections::HashMap;

pub struct RiskLimits {
    pub max_order_qty: u64,
    pub max_abs_position: i64,
}

pub struct RiskEngine {
    limits: RiskLimits,
    positions: HashMap<String, Position>,
    rx_orders: Receiver<Event>,
    tx_gateway: Sender<Event>,
    tx_updates: Sender<Event>,
}

impl RiskEngine {
    pub fn new(
        limits: RiskLimits,
        rx_orders: Receiver<Event>,
        tx_gateway: Sender<Event>,
        tx_updates: Sender<Event>,
    ) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
            rx_orders,
            tx_gateway,
            tx_updates,
        }
    }

    fn check_order(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty == 0 {
            return Err("quantity must be > 0".to_string());
        }
        if order.qty > self.limits.max_order_qty {
            return Err(format!("order qty {} exceeds max {}", order.qty, self.limits.max_order_qty));
        }

        let current = self.positions.get(&order.symbol).map(|p| p.net_qty).unwrap_or(0);
        let projected = match order.side {
            Side::Buy => current + order.qty as i64,
            Side::Sell => current - order.qty as i64,
        };

        if projected.abs() > self.limits.max_abs_position {
            return Err(format!(
                "projected position {} exceeds max abs position {}",
                projected, self.limits.max_abs_position
            ));
        }

        Ok(())
    }

    pub fn start(mut self) {
        std::thread::spawn(move || {
            while let Ok(event) = self.rx_orders.recv() {
                if let Event::OrderRequest(order) = event {
                    match self.check_order(&order) {
                        Ok(_) => {
                            let _ = self.tx_gateway.send(Event::OrderRequest(order));
                        }
                        Err(reason) => {
                            let update = OrderUpdate {
                                id: order.id,
                                status: OrderStatus::Rejected(reason),
                                filled_qty: 0,
                                remaining_qty: order.qty,
                                avg_fill_price: None,
                                ts_exchange: None,
                                ts_received: Utc::now(),
                            };
                            let _ = self.tx_updates.send(Event::OrderUpdate(update));
                        }
                    }
                }
            }
        });
    }
}
```

