# 10. Order gateway

This simulates exchange execution. In production this is where FIX/OUCH/ITCH/native protocols live.

## `src/order_gateway.rs`

```rust
use crate::types::{Event, OrderStatus, OrderUpdate};
use chrono::Utc;
use crossbeam_channel::{Receiver, Sender};
use std::{thread, time::Duration};

pub struct OrderGateway {
    rx_orders: Receiver<Event>,
    tx_updates: Sender<Event>,
}

impl OrderGateway {
    pub fn new(rx_orders: Receiver<Event>, tx_updates: Sender<Event>) -> Self {
        Self {
            rx_orders,
            tx_updates,
        }
    }

    pub fn start(self) {
        thread::spawn(move || {
            while let Ok(event) = self.rx_orders.recv() {
                if let Event::OrderRequest(order) = event {
                    let accepted = OrderUpdate {
                        id: order.id,
                        status: OrderStatus::Accepted,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_fill_price: None,
                        ts_exchange: Some(Utc::now()),
                        ts_received: Utc::now(),
                    };
                    let _ = self.tx_updates.send(Event::OrderUpdate(accepted));

                    thread::sleep(Duration::from_millis(2));

                    let filled = OrderUpdate {
                        id: order.id,
                        status: OrderStatus::Filled,
                        filled_qty: order.qty,
                        remaining_qty: 0,
                        avg_fill_price: order.price.or(Some(100.0)),
                        ts_exchange: Some(Utc::now()),
                        ts_received: Utc::now(),
                    };
                    let _ = self.tx_updates.send(Event::OrderUpdate(filled));
                }
            }
        });
    }
}
