use crate::types::Event;
use crossbeam_channel::Receiver;
use std::fs::OpenOptions;
use std::io::Write;
use std::thread;

pub struct Journal {
    rx_events: Receiver<Event>,
    path: String,
}

impl Journal {
    pub fn new(rx_events: Receiver<Event>, path: String) -> Self {
        Self { rx_events, path }
    }

    pub fn start(self) {
        thread::spawn(move || {
            let mut file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(&self.path)
                .expect("failed to open journal");

            while let Ok(event) = self.rx_events.recv() {
                if let Ok(line) = serde_json::to_string(&event) {
                    let _ = writeln!(file, "{line}");
                }
            }
        });
    }
}
