# 7. State management

## `src/state.rs`

```rust
use std::collections::HashMap;
use std::sync::Arc;

use tokio::sync::RwLock;
use uuid::Uuid;

use crate::types::{ExecutionReport, OrderRequest, OrderStatus, Position, Side};

#[derive(Clone, Default)]
pub struct SharedState {
    pub positions: Arc<RwLock<HashMap<String, Position>>>,
    pub orders: Arc<RwLock<HashMap<Uuid, OrderStatus>>>,
}

impl SharedState {
    pub async fn record_order_new(&self, order: &OrderRequest) {
        let mut orders = self.orders.write().await;
        orders.insert(order.id, OrderStatus::New);
    }

    pub async fn record_order_status(&self, order_id: Uuid, status: OrderStatus) {
        let mut orders = self.orders.write().await;
        orders.insert(order_id, status);
    }

    pub async fn apply_execution(&self, report: &ExecutionReport) {
        let mut positions = self.positions.write().await;
        let pos = positions.entry(report.symbol.clone()).or_insert(Position {
            symbol: report.symbol.clone(),
            net_qty: 0,
            avg_price: 0.0,
            realized_pnl: 0.0,
        });

        let signed_qty = match report.side {
            Side::Buy => report.qty as i64,
            Side::Sell => -(report.qty as i64),
        };

        let old_qty = pos.net_qty;
        let new_qty = old_qty + signed_qty;

        if old_qty == 0 || old_qty.signum() == signed_qty.signum() {
            let total_notional =
                pos.avg_price * (old_qty.abs() as f64) + report.fill_price * (report.qty as f64);
            let total_qty = old_qty.abs() + report.qty as i64;
            pos.avg_price = if total_qty > 0 {
                total_notional / (total_qty as f64)
            } else {
                0.0
            };
            pos.net_qty = new_qty;
        } else {
            let closing_qty = old_qty.abs().min(report.qty as i64) as f64;
            let pnl_per_unit = if old_qty > 0 {
                report.fill_price - pos.avg_price
            } else {
                pos.avg_price - report.fill_price
            };
            pos.realized_pnl += pnl_per_unit * closing_qty;
            pos.net_qty = new_qty;

            if pos.net_qty == 0 {
                pos.avg_price = 0.0;
            } else if old_qty.abs() < report.qty as i64 {
                pos.avg_price = report.fill_price;
            }
        }
    }
}
```

