# 9. Strategy engine

## `src/strategy.rs`

This is a toy mean-reversion strategy.

```rust
use std::collections::VecDeque;

use chrono::Utc;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};
use uuid::Uuid;

use crate::bus::EventBus;
use crate::types::{OrderRequest, OrderType, Side};

pub async fn run_strategy(bus: EventBus, strategy_id: String, symbol: String) {
    let mut rx = bus.market_tx.subscribe();
    let mut window: VecDeque<f64> = VecDeque::new();
    let max_window = 20usize;

    loop {
        match rx.recv().await {
            Ok(tick) => {
                if tick.symbol != symbol {
                    continue;
                }

                window.push_back(tick.last);
                if window.len() > max_window {
                    window.pop_front();
                }

                if window.len() < max_window {
                    continue;
                }

                let mean = window.iter().sum::<f64>() / window.len() as f64;
                let threshold = 0.15;

                let maybe_order = if tick.last < mean - threshold {
                    Some(OrderRequest {
                        id: Uuid::new_v4(),
                        symbol: symbol.clone(),
                        side: Side::Buy,
                        qty: 10,
                        order_type: OrderType::Market,
                        ts: Utc::now(),
                        strategy_id: strategy_id.clone(),
                    })
                } else if tick.last > mean + threshold {
                    Some(OrderRequest {
                        id: Uuid::new_v4(),
                        symbol: symbol.clone(),
                        side: Side::Sell,
                        qty: 10,
                        order_type: OrderType::Market,
                        ts: Utc::now(),
                        strategy_id: strategy_id.clone(),
                    })
                } else {
                    None
                };

                if let Some(order) = maybe_order {
                    let _ = bus.order_tx.send(order.clone());
                    info!("strategy emitted order: {:?}", order);
                }
            }
            Err(RecvError::Lagged(n)) => {
                warn!("strategy lagged by {} messages", n);
            }
            Err(RecvError::Closed) => break,
        }
    }
}
```

