# 10. Risk engine

## `src/risk.rs`

```rust
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::state::SharedState;
use crate::types::{RiskCheckedOrder, RiskDecision, Side};

const MAX_ORDER_QTY: u64 = 100;
const MAX_ABS_POSITION: i64 = 1000;

pub async fn run_risk(bus: EventBus, state: SharedState) {
    let mut rx = bus.order_tx.subscribe();

    loop {
        match rx.recv().await {
            Ok(order) => {
                state.record_order_new(&order).await;

                let positions = state.positions.read().await;
                let current_pos = positions
                    .get(&order.symbol)
                    .map(|p| p.net_qty)
                    .unwrap_or(0);

                let projected = match order.side {
                    Side::Buy => current_pos + order.qty as i64,
                    Side::Sell => current_pos - order.qty as i64,
                };

                let decision = if order.qty > MAX_ORDER_QTY {
                    RiskDecision::Rejected(format!(
                        "order qty {} exceeds max {}",
                        order.qty, MAX_ORDER_QTY
                    ))
                } else if projected.abs() > MAX_ABS_POSITION {
                    RiskDecision::Rejected(format!(
                        "projected position {} exceeds limit {}",
                        projected, MAX_ABS_POSITION
                    ))
                } else {
                    RiskDecision::Approved
                };

                let checked = RiskCheckedOrder { order, decision };
                let _ = bus.risk_tx.send(checked.clone());
                info!("risk decision: {:?}", checked);
            }
            Err(RecvError::Lagged(n)) => warn!("risk lagged by {} messages", n),
            Err(RecvError::Closed) => break,
        }
    }
}
```

