# 11. OMS

## `src/oms.rs`

```rust
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::state::SharedState;
use crate::types::{OrderStatus, RiskDecision};

pub async fn run_oms(bus: EventBus, state: SharedState) {
    let mut rx = bus.risk_tx.subscribe();

    loop {
        match rx.recv().await {
            Ok(checked) => match checked.decision {
                RiskDecision::Approved => {
                    state
                        .record_order_status(checked.order.id, OrderStatus::SentToVenue)
                        .await;
                    let _ = bus.exec_tx.send(crate::types::ExecutionReport {
                        order_id: checked.order.id,
                        symbol: checked.order.symbol.clone(),
                        side: checked.order.side.clone(),
                        qty: checked.order.qty,
                        fill_price: 0.0,
                        status: OrderStatus::SentToVenue,
                        ts: chrono::Utc::now(),
                    });
                    info!("oms approved order {}", checked.order.id);
                }
                RiskDecision::Rejected(reason) => {
                    state
                        .record_order_status(
                            checked.order.id,
                            OrderStatus::Rejected(reason.clone()),
                        )
                        .await;
                    info!("oms rejected order {}: {}", checked.order.id, reason);
                }
            },
            Err(RecvError::Lagged(n)) => warn!("oms lagged by {} messages", n),
            Err(RecvError::Closed) => break,
        }
    }
}
