# 12. Execution simulator

## `src/execution.rs`

This listens for `SentToVenue` reports and produces fills.

```rust
use chrono::Utc;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

use crate::bus::EventBus;
use crate::state::SharedState;
use crate::types::{ExecutionReport, OrderStatus};

pub async fn run_execution(bus: EventBus, state: SharedState) {
    let mut rx = bus.exec_tx.subscribe();
    let mut market_rx = bus.market_tx.subscribe();

    let mut last_price = 100.0;

    tokio::spawn(async move {
        loop {
            match market_rx.recv().await {
                Ok(tick) => last_price = tick.last,
                Err(_) => break,
            }
        }
    });

    loop {
        match rx.recv().await {
            Ok(report) => {
                if !matches!(report.status, OrderStatus::SentToVenue) {
                    continue;
                }

                let fill = ExecutionReport {
                    order_id: report.order_id,
                    symbol: report.symbol.clone(),
                    side: report.side.clone(),
                    qty: report.qty,
                    fill_price: last_price,
                    status: OrderStatus::Filled,
                    ts: Utc::now(),
                };

                state
                    .record_order_status(fill.order_id, OrderStatus::Filled)
                    .await;
                state.apply_execution(&fill).await;

                info!("execution fill: {:?}", fill);
            }
            Err(RecvError::Lagged(n)) => warn!("execution lagged by {} messages", n),
            Err(RecvError::Closed) => break,
        }
    }
}
```

