## `src/state.rs`

```rust
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Debug, Default)]
pub struct PositionState {
    positions: DashMap<String, i64>,
}

impl PositionState {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            positions: DashMap::new(),
        })
    }

    pub fn get_position(&self, symbol: &str) -> i64 {
        self.positions.get(symbol).map(|v| *v).unwrap_or(0)
    }

    pub fn apply_fill(&self, symbol: &str, signed_qty: i64) {
        self.positions
            .entry(symbol.to_string())
            .and_modify(|p| *p += signed_qty)
            .or_insert(signed_qty);
    }
}
