use crate::bus::EventBus;
use crate::types::{Event, MarketTick, OrderRequest, OrderType, Side};
use chrono::Utc;
use tokio::sync::broadcast::error::RecvError;
use tracing::info;
use uuid::Uuid;

pub async fn run_strategy(bus: EventBus) {
    let mut rx = bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(Event::Market(MarketTick { symbol, last, .. })) => {
                if (last as u64) % 2 == 0 {
                    let order = OrderRequest {
                        id: Uuid::new_v4(),
                        symbol,
                        side: Side::Buy,
                        qty: 10,
                        order_type: OrderType::Limit,
                        price: Some(last),
                        ts: Utc::now(),
                    };
                    bus.publish(Event::OrderNew(order));
                    info!("strategy generated order");
                }
            }
            Ok(_) => {}
            Err(RecvError::Lagged(_)) => continue,
            Err(RecvError::Closed) => break,
        }
    }
}
