## `src/risk.rs`

```rust
use crate::bus::EventBus;
use crate::config::RiskConfig;
use crate::state::PositionState;
use crate::types::{Event, OrderRequest, OrderStatus, OrderUpdate, Side};
use chrono::Utc;
use std::sync::Arc;
use tokio::sync::broadcast::error::RecvError;
use tracing::{info, warn};

pub async fn run_risk(bus: EventBus, positions: Arc<PositionState>, cfg: RiskConfig) {
    let mut rx = bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(Event::OrderNew(order)) => {
                if let Some(reject_reason) = validate_order(&order, &positions, &cfg) {
                    let update = OrderUpdate {
                        id: order.id,
                        status: OrderStatus::Rejected,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_fill_price: None,
                        reason: Some(reject_reason),
                        ts: Utc::now(),
                    };
                    bus.publish(Event::OrderUpdate(update));
                    warn!("risk rejected order");
                } else {
                    // Forward approved order by republishing.
                    // In a more advanced design, use separate topics/channels.
                    bus.publish(Event::OrderNew(order));
                    info!("risk approved order");
                }
            }
            Ok(_) => {}
            Err(RecvError::Lagged(_)) => continue,
            Err(RecvError::Closed) => break,
        }
    }
}

fn validate_order(
    order: &OrderRequest,
    positions: &PositionState,
    cfg: &RiskConfig,
) -> Option<String> {
    if order.qty > cfg.max_order_qty {
        return Some("max_order_qty_exceeded".to_string());
    }

    let px = order.price.unwrap_or(0.0);
    let notional = px * order.qty as f64;
    if notional > cfg.max_notional {
        return Some("max_notional_exceeded".to_string());
    }

    let current_pos = positions.get_position(&order.symbol);
    let signed = match order.side {
        Side::Buy => order.qty as i64,
        Side::Sell => -(order.qty as i64),
    };
    let projected = current_pos + signed;

    if projected.abs() > cfg.max_position_abs {
        return Some("max_position_abs_exceeded".to_string());
    }

    None
}
```

