use crate::bus::EventBus;
use crate::types::{Event, OrderRequest, OrderStatus, OrderUpdate};
use chrono::Utc;
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::broadcast::error::RecvError;
use tracing::info;
use uuid::Uuid;

#[derive(Default)]
pub struct OrderStore {
    pub orders: DashMap<Uuid, OrderRequest>,
}

impl OrderStore {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            orders: DashMap::new(),
        })
    }
}

pub async fn run_oms(bus: EventBus, store: Arc<OrderStore>) {
    let mut rx = bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(Event::OrderNew(order)) => {
                store.orders.insert(order.id, order.clone());

                let accepted = OrderUpdate {
                    id: order.id,
                    status: OrderStatus::Accepted,
                    filled_qty: 0,
                    remaining_qty: order.qty,
                    avg_fill_price: None,
                    reason: None,
                    ts: Utc::now(),
                };

                bus.publish(Event::OrderUpdate(accepted));
                bus.publish(Event::OrderNew(order));
                info!("oms accepted order");
            }
            Ok(_) => {}
            Err(RecvError::Lagged(_)) => continue,
            Err(RecvError::Closed) => break,
        }
    }
}
