## `src/execution.rs`

```rust
use crate::bus::EventBus;
use crate::state::PositionState;
use crate::types::{Event, OrderStatus, OrderUpdate, Side};
use chrono::Utc;
use std::sync::Arc;
use tokio::sync::broadcast::error::RecvError;
use tracing::info;

pub async fn run_execution(bus: EventBus, positions: Arc<PositionState>) {
    let mut rx = bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(Event::OrderNew(order)) => {
                let fill_px = order.price.unwrap_or(100.0);

                let update = OrderUpdate {
                    id: order.id,
                    status: OrderStatus::Filled,
                    filled_qty: order.qty,
                    remaining_qty: 0,
                    avg_fill_price: Some(fill_px),
                    reason: None,
                    ts: Utc::now(),
                };

                let signed_qty = match order.side {
                    Side::Buy => order.qty as i64,
                    Side::Sell => -(order.qty as i64),
                };

                positions.apply_fill(&order.symbol, signed_qty);
                bus.publish(Event::OrderUpdate(update));
                info!("execution filled order");
            }
            Ok(_) => {}
            Err(RecvError::Lagged(_)) => continue,
            Err(RecvError::Closed) => break,
        }
    }
}
