# 11. Strategy Engine

Simple example strategy:
- buy if spread is tight and ask below threshold
- sell if bid above threshold

## `crates/engine/src/strategy.rs`
```rust
use std::time::{SystemTime, UNIX_EPOCH};

use common::{
    events::Event,
    types::{OrderRequest, OrderType, Side, StrategyId},
};

use crate::bus::EventBus;

pub struct StrategyEngine {
    bus: EventBus,
    strategy_id: StrategyId,
}

impl StrategyEngine {
    pub fn new(bus: EventBus, strategy_id: StrategyId) -> Self {
        Self { bus, strategy_id }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::MarketData(tick)) => {
                    let spread = tick.ask - tick.bid;

                    if spread <= 1 && tick.ask <= 1001 {
                        let ts_ns = SystemTime::now()
                            .duration_since(UNIX_EPOCH)
                            .unwrap()
                            .as_nanos() as u64;

                        let order = OrderRequest {
                            strategy_id: self.strategy_id,
                            instrument_id: tick.instrument_id,
                            side: Side::Buy,
                            order_type: OrderType::Limit,
                            price: Some(tick.ask),
                            qty: 1,
                            ts_ns,
                        };

                        self.bus.publish(Event::OrderRequest(order));
                    }
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}
