# 12. Risk Engine

## `crates/engine/src/risk_engine.rs`
```rust
use std::collections::HashMap;

use common::{
    events::Event,
    risk::{RiskLimits, StrategyRiskConfig},
    types::{ApprovedOrder, OrderId, OrderRequest, Side, StrategyId},
};

use crate::bus::EventBus;

pub struct RiskEngine {
    bus: EventBus,
    configs: HashMap<StrategyId, RiskLimits>,
    next_order_id: OrderId,
    positions: HashMap<(StrategyId, u64), i64>,
}

impl RiskEngine {
    pub fn new(bus: EventBus, strategy_configs: Vec<StrategyRiskConfig>) -> Self {
        let configs = strategy_configs
            .into_iter()
            .map(|cfg| (cfg.strategy_id, cfg.limits))
            .collect();

        Self {
            bus,
            configs,
            next_order_id: 1,
            positions: HashMap::new(),
        }
    }

    fn check_order(&self, req: &OrderRequest) -> Result<(), String> {
        let limits = self
            .configs
            .get(&req.strategy_id)
            .ok_or_else(|| "missing risk config".to_string())?;

        if req.qty.abs() > limits.max_order_qty {
            return Err("order qty exceeds limit".to_string());
        }

        let px = req.price.unwrap_or(0);
        let notional = px.abs() * req.qty.abs();
        if notional > limits.max_notional_per_order {
            return Err("order notional exceeds limit".to_string());
        }

        let current_pos = *self
            .positions
            .get(&(req.strategy_id, req.instrument_id))
            .unwrap_or(&0);

        let delta = match req.side {
            Side::Buy => req.qty,
            Side::Sell => -req.qty,
        };

        let projected = current_pos + delta;
        if projected.abs() > limits.max_position_abs {
            return Err("projected position exceeds limit".to_string());
        }

        Ok(())
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::OrderRequest(req)) => match self.check_order(&req) {
                    Ok(()) => {
                        let approved = ApprovedOrder {
                            order_id: self.next_order_id,
                            request: req,
                        };
                        self.next_order_id += 1;
                        self.bus.publish(Event::ApprovedOrder(approved));
                    }
                    Err(reason) => {
                        self.bus.publish(Event::RiskReject {
                            reason,
                            request: req,
                        });
                    }
                },
                Ok(Event::ExecutionReport(report)) => {
                    if let common::types::OrderStatus::Filled
                    | common::types::OrderStatus::PartiallyFilled = report.status
                    {
                        // In a real implementation, track order side/instrument by order_id.
                        // This MVP omits that mapping for brevity.
                    }
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}
```

