# 13. Order Manager

## `crates/engine/src/order_manager.rs`
```rust
use std::collections::HashMap;

use common::{
    events::Event,
    types::{ApprovedOrder, OrderId},
};

use crate::bus::EventBus;

pub struct OrderManager {
    bus: EventBus,
    live_orders: HashMap<OrderId, ApprovedOrder>,
}

impl OrderManager {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            live_orders: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::ApprovedOrder(order)) => {
                    self.live_orders.insert(order.order_id, order.clone());
                    self.bus.publish(Event::ApprovedOrder(order));
                }
                Ok(Event::ExecutionReport(report)) => {
                    if matches!(
                        report.status,
                        common::types::OrderStatus::Filled
                            | common::types::OrderStatus::Cancelled
                            | common::types::OrderStatus::Rejected(_)
                    ) {
                        self.live_orders.remove(&report.order_id);
                    }
                }
                Ok(_) => {}
                Err(_) => {}
            }
        }
    }
}
```

> Note: In production, do **not** republish the same `ApprovedOrder` from multiple consumers like this. This is just illustrating flow. Better is direct stage ownership or separate command/event topics.

