```rust
use common::{
    CancelOrder, ExecutionReport, MarketDataEvent, NewOrder, OrderId, Price, Quantity,
    RejectReason, Side, Timestamp, Trade,
};
use std::cmp::min;
use std::collections::{BTreeMap, HashMap, VecDeque};

#[derive(Debug, Clone)]
struct RestingOrder {
    client_id: u64,
    order_id: OrderId,
    instrument_id: u32,
    side: Side,
    price: Price,
    remaining_qty: Quantity,
    timestamp: Timestamp,
}

#[derive(Debug, Default)]
struct OrderBookSide {
    // price -> fifo queue of resting orders
    levels: BTreeMap<Price, VecDeque<RestingOrder>>,
}

#[derive(Debug, Default)]
pub struct OrderBook {
    bids: OrderBookSide,
    asks: OrderBookSide,
    order_index: HashMap<OrderId, (Side, Price)>,
}

#[derive(Debug, Default)]
pub struct MatchResult {
    pub execution_reports: Vec<ExecutionReport>,
    pub market_data: Vec<MarketDataEvent>,
}

impl OrderBook {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn process_new(&mut self, order: NewOrder) -> MatchResult {
        let mut result = MatchResult::default();

        if order.quantity == 0 {
            result.execution_reports.push(ExecutionReport::Rejected {
                client_id: order.client_id,
                order_id: order.order_id,
                instrument_id: order.instrument_id,
                reason: RejectReason::InvalidQuantity,
            });
            return result;
        }

        if order.price == 0 {
            result.execution_reports.push(ExecutionReport::Rejected {
                client_id: order.client_id,
                order_id: order.order_id,
                instrument_id: order.instrument_id,
                reason: RejectReason::InvalidPrice,
            });
            return result;
        }

        if self.order_index.contains_key(&order.order_id) {
            result.execution_reports.push(ExecutionReport::Rejected {
                client_id: order.client_id,
                order_id: order.order_id,
                instrument_id: order.instrument_id,
                reason: RejectReason::DuplicateOrderId,
            });
            return result;
        }

        result.execution_reports.push(ExecutionReport::Accepted {
            client_id: order.client_id,
            order_id: order.order_id,
            instrument_id: order.instrument_id,
        });

        let mut incoming = RestingOrder {
            client_id: order.client_id,
            order_id: order.order_id,
            instrument_id: order.instrument_id,
            side: order.side,
            price: order.price,
            remaining_qty: order.quantity,
            timestamp: order.timestamp,
        };

        match incoming.side {
            Side::Buy => self.match_buy(&mut incoming, &mut result),
            Side::Sell => self.match_sell(&mut incoming, &mut result),
        }

        if incoming.remaining_qty > 0 {
            self.add_resting(incoming);
        }

        self.publish_top_of_book(order.instrument_id, order.timestamp, &mut result);
        result
    }

    pub fn process_cancel(&mut self, cancel: CancelOrder) -> MatchResult {
        let mut result = MatchResult::default();

        let Some((side, price)) = self.order_index.remove(&cancel.order_id) else {
            result.execution_reports.push(ExecutionReport::Rejected {
                client_id: cancel.client_id,
                order_id: cancel.order_id,
                instrument_id: cancel.instrument_id,
                reason: RejectReason::OrderNotFound,
            });
            return result;
        };

        let levels = match side {
            Side::Buy => &mut self.bids.levels,
            Side::Sell => &mut self.asks.levels,
        };

        if let Some(queue) = levels.get_mut(&price) {
            if let Some(pos) = queue.iter().position(|o| o.order_id == cancel.order_id) {
                queue.remove(pos);
                result.execution_reports.push(ExecutionReport::Cancelled {
                    client_id: cancel.client_id,
                    order_id: cancel.order_id,
                    instrument_id: cancel.instrument_id,
                });
            }

            if queue.is_empty() {
                levels.remove(&price);
            }
        }

        self.publish_top_of_book(cancel.instrument_id, cancel.timestamp, &mut result);
        result
    }

    fn add_resting(&mut self, order: RestingOrder) {
        let levels = match order.side {
            Side::Buy => &mut self.bids.levels,
            Side::Sell => &mut self.asks.levels,
        };

        levels
            .entry(order.price)
            .or_default()
            .push_back(order.clone());

        self.order_index
            .insert(order.order_id, (order.side, order.price));
    }

    fn match_buy(&mut self, incoming: &mut RestingOrder, result: &mut MatchResult) {
        loop {
            let best_ask_price = match self.asks.levels.keys().next().copied() {
                Some(p) => p,
                None => break,
            };

            if best_ask_price > incoming.price || incoming.remaining_qty == 0 {
                break;
            }

            let mut remove_level = false;

            if let Some(queue) = self.asks.levels.get_mut(&best_ask_price) {
                while let Some(resting) = queue.front_mut() {
                    if incoming.remaining_qty == 0 {
                        break;
                    }

                    let traded = min(incoming.remaining_qty, resting.remaining_qty);
                    incoming.remaining_qty -= traded;
                    resting.remaining_qty -= traded;

                    result.market_data.push(MarketDataEvent::Trade(Trade {
                        instrument_id: incoming.instrument_id,
                        buy_order_id: incoming.order_id,
                        sell_order_id: resting.order_id,
                        price: resting.price,
                        quantity: traded,
                        timestamp: incoming.timestamp,
                    }));

                    emit_fill_reports(incoming, resting, traded, resting.price, result);

                    if resting.remaining_qty == 0 {
                        let filled = queue.pop_front().unwrap();
                        self.order_index.remove(&filled.order_id);
                    } else {
                        break;
                    }
                }

                remove_level = queue.is_empty();
            }

            if remove_level {
                self.asks.levels.remove(&best_ask_price);
            }
        }
    }

    fn match_sell(&mut self, incoming: &mut RestingOrder, result: &mut MatchResult) {
        loop {
            let best_bid_price = match self.bids.levels.keys().next_back().copied() {
                Some(p) => p,
                None => break,
            };

            if best_bid_price < incoming.price || incoming.remaining_qty == 0 {
                break;
            }

            let mut remove_level = false;

            if let Some(queue) = self.bids.levels.get_mut(&best_bid_price) {
                while let Some(resting) = queue.front_mut() {
                    if incoming.remaining_qty == 0 {
                        break;
                    }

                    let traded = min(incoming.remaining_qty, resting.remaining_qty);
                    incoming.remaining_qty -= traded;
                    resting.remaining_qty -= traded;

                    result.market_data.push(MarketDataEvent::Trade(Trade {
                        instrument_id: incoming.instrument_id,
                        buy_order_id: resting.order_id,
                        sell_order_id: incoming.order_id,
                        price: resting.price,
                        quantity: traded,
                        timestamp: incoming.timestamp,
                    }));

                    emit_fill_reports(resting, incoming, traded, resting.price, result);

                    if resting.remaining_qty == 0 {
                        let filled = queue.pop_front().unwrap();
                        self.order_index.remove(&filled.order_id);
                    } else {
                        break;
                    }
                }

                remove_level = queue.is_empty();
            }

            if remove_level {
                self.bids.levels.remove(&best_bid_price);
            }
        }
    }

    fn publish_top_of_book(
        &self,
        instrument_id: u32,
        timestamp: Timestamp,
        result: &mut MatchResult,
    ) {
        let best_bid = self.bids.levels.iter().next_back().map(|(price, queue)| {
            let qty = queue.iter().map(|o| o.remaining_qty).sum();
            (*price, qty)
        });

        let best_ask = self.asks.levels.iter().next().map(|(price, queue)| {
            let qty = queue.iter().map(|o| o.remaining_qty).sum();
            (*price, qty)
        });

        result.market_data.push(MarketDataEvent::BookTop {
            instrument_id,
            best_bid,
            best_ask,
            timestamp,
        });
    }
}

fn emit_fill_reports(
    buy_side: &RestingOrder,
    sell_side: &RestingOrder,
    traded: Quantity,
    price: Price,
    result: &mut MatchResult,
) {
    let buy_remaining = buy_side.remaining_qty;
    let sell_remaining = sell_side.remaining_qty;

    let buy_report = if buy_remaining == 0 {
        ExecutionReport::Filled {
            client_id: buy_side.client_id,
            order_id: buy_side.order_id,
            instrument_id: buy_side.instrument_id,
            filled_qty: traded,
            price,
        }
    } else {
        ExecutionReport::PartiallyFilled {
            client_id: buy_side.client_id,
            order_id: buy_side.order_id,
            instrument_id: buy_side.instrument_id,
            filled_qty: traded,
            remaining_qty: buy_remaining,
            price,
        }
    };

    let sell_report = if sell_remaining == 0 {
        ExecutionReport::Filled {
            client_id: sell_side.client_id,
            order_id: sell_side.order_id,
            instrument_id: sell_side.instrument_id,
            filled_qty: traded,
            price,
        }
    } else {
        ExecutionReport::PartiallyFilled {
            client_id: sell_side.client_id,
            order_id: sell_side.order_id,
            instrument_id: sell_side.instrument_id,
            filled_qty: traded,
            remaining_qty: sell_remaining,
            price,
        }
    };

    result.execution_reports.push(buy_report);
    result.execution_reports.push(sell_report);
}
