```rust
use common::{ClientRequest, ExecutionReport, InstrumentId, MarketDataEvent};
use matching_engine::OrderBook;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{broadcast, mpsc, Mutex};

#[derive(Clone)]
struct ClientSession {
    client_id: u64,
    tx: mpsc::Sender<ExecutionReport>,
}

#[derive(Clone)]
struct AppState {
    sessions: Arc<Mutex<HashMap<u64, mpsc::Sender<ExecutionReport>>>>,
    md_tx: broadcast::Sender<MarketDataEvent>,
}

enum EngineCommand {
    Request(ClientRequest),
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let (engine_tx, engine_rx) = mpsc::channel::<EngineCommand>(1024);
    let (md_tx, _) = broadcast::channel::<MarketDataEvent>(1024);

    let state = AppState {
        sessions: Arc::new(Mutex::new(HashMap::new())),
        md_tx: md_tx.clone(),
    };

    tokio::spawn(run_matching_engine(engine_rx, state.clone()));

    let listener = TcpListener::bind("0.0.0.0:7000").await?;
    println!("gateway listening on 0.0.0.0:7000");

    loop {
        let (socket, _) = listener.accept().await?;
        let engine_tx = engine_tx.clone();
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(socket, engine_tx, state).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

async fn handle_client(
    socket: TcpStream,
    engine_tx: mpsc::Sender<EngineCommand>,
    state: AppState,
) -> Result<(), Box<dyn std::error::Error>> {
    let (reader, mut writer) = socket.into_split();
    let mut lines = BufReader::new(reader).lines();

    let first = match lines.next_line().await? {
        Some(line) => line,
        None => return Ok(()),
    };

    let hello: serde_json::Value = serde_json::from_str(&first)?;
    let client_id = hello["client_id"]
        .as_u64()
        .ok_or("missing client_id in first message")?;

    let (tx, mut rx) = mpsc::channel::<ExecutionReport>(1024);
    state.sessions.lock().await.insert(client_id, tx.clone());

    let mut md_rx = state.md_tx.subscribe();

    let mut writer_clone = writer;
    let write_task = tokio::spawn(async move {
        loop {
            tokio::select! {
                Some(report) = rx.recv() => {
                    let line = serde_json::to_string(&report).unwrap();
                    if writer_clone.write_all(line.as_bytes()).await.is_err() { break; }
                    if writer_clone.write_all(b"\n").await.is_err() { break; }
                }
                Ok(md) = md_rx.recv() => {
                    let line = serde_json::to_string(&md).unwrap();
                    if writer_clone.write_all(line.as_bytes()).await.is_err() { break; }
                    if writer_clone.write_all(b"\n").await.is_err() { break; }
                }
            }
        }
    });

    while let Some(line) = lines.next_line().await? {
        let req: ClientRequest = serde_json::from_str(&line)?;
        engine_tx.send(EngineCommand::Request(req)).await?;
    }

    state.sessions.lock().await.remove(&client_id);
    write_task.abort();
    Ok(())
}

async fn run_matching_engine(
    mut rx: mpsc::Receiver<EngineCommand>,
    state: AppState,
) {
    let mut books: HashMap<InstrumentId, OrderBook> = HashMap::new();

    while let Some(cmd) = rx.recv().await {
        match cmd {
            EngineCommand::Request(req) => {
                let (client_id, instrument_id, result) = match req {
                    ClientRequest::New(order) => {
                        let client_id = order.client_id;
                        let instrument_id = order.instrument_id;
                        let book = books.entry(instrument_id).or_insert_with(OrderBook::new);
                        let result = book.process_new(order);
                        (client_id, instrument_id, result)
                    }
                    ClientRequest::Cancel(cancel) => {
                        let client_id = cancel.client_id;
                        let instrument_id = cancel.instrument_id;
                        let book = books.entry(instrument_id).or_insert_with(OrderBook::new);
                        let result = book.process_cancel(cancel);
                        (client_id, instrument_id, result)
                    }
                };

                for report in result.execution_reports {
                    route_execution_report(&state, &report).await;
                }

                for md in result.market_data {
                    let _ = state.md_tx.send(md);
                }

                let _ = (client_id, instrument_id);
            }
        }
    }
}

async fn route_execution_report(state: &AppState, report: &ExecutionReport) {
    let target_client = match report {
        ExecutionReport::Accepted { client_id, .. } => *client_id,
        ExecutionReport::Rejected { client_id, .. } => *client_id,
        ExecutionReport::PartiallyFilled { client_id, .. } => *client_id,
        ExecutionReport::Filled { client_id, .. } => *client_id,
        ExecutionReport::Cancelled { client_id, .. } => *client_id,
    };

    let sessions = state.sessions.lock().await;
    if let Some(tx) = sessions.get(&target_client) {
        let _ = tx.send(report.clone()).await;
    }
}
