use crate::types::{Order, RiskDecision};

#[derive(Clone)]
pub struct RiskEngine {
    pub max_order_qty: u64,
}

impl RiskEngine {
    pub fn new(max_order_qty: u64) -> Self {
        Self { max_order_qty }
    }

    pub fn check(&self, order: &Order) -> RiskDecision {
        if order.qty == 0 {
            return RiskDecision::Reject("quantity must be > 0".into());
        }

        if order.qty > self.max_order_qty {
            return RiskDecision::Reject(format!(
                "order quantity {} exceeds max {}",
                order.qty, self.max_order_qty
            ));
        }

        RiskDecision::Pass
    }
}
