```rust
use crate::types::{Event, Order, OrderStatus, Side};
use std::collections::{BTreeMap, VecDeque};
use uuid::Uuid;

#[derive(Default)]
pub struct OrderBook {
    pub bids: BTreeMap<u64, VecDeque<Order>>,
    pub asks: BTreeMap<u64, VecDeque<Order>>,
}

pub struct MatchingEngine {
    books: std::collections::HashMap<String, OrderBook>,
}

impl MatchingEngine {
    pub fn new() -> Self {
        Self {
            books: std::collections::HashMap::new(),
        }
    }

    pub fn process_order(&mut self, mut incoming: Order) -> Vec<Event> {
        let mut events = Vec::new();
        let book = self.books.entry(incoming.instrument.clone()).or_default();

        match incoming.side {
            Side::Buy => {
                while incoming.remaining_qty > 0 {
                    let best_ask_price = match book.asks.keys().next().copied() {
                        Some(p) => p,
                        None => break,
                    };

                    if let Some(limit) = incoming.price {
                        if best_ask_price > limit {
                            break;
                        }
                    }

                    let queue = book.asks.get_mut(&best_ask_price).unwrap();
                    while incoming.remaining_qty > 0 && !queue.is_empty() {
                        let mut resting = queue.pop_front().unwrap();
                        let fill_qty = incoming.remaining_qty.min(resting.remaining_qty);

                        incoming.remaining_qty -= fill_qty;
                        resting.remaining_qty -= fill_qty;

                        events.push(Event::OrderFilled {
                            order_id: incoming.order_id,
                            fill_qty,
                            remaining_qty: incoming.remaining_qty,
                            price: best_ask_price,
                        });

                        events.push(Event::OrderFilled {
                            order_id: resting.order_id,
                            fill_qty,
                            remaining_qty: resting.remaining_qty,
                            price: best_ask_price,
                        });

                        if resting.remaining_qty > 0 {
                            queue.push_front(resting);
                            break;
                        }
                    }

                    if queue.is_empty() {
                        book.asks.remove(&best_ask_price);
                    }
                }

                if incoming.remaining_qty > 0 {
                    if let Some(price) = incoming.price {
                        incoming.status = OrderStatus::Accepted;
                        book.bids.entry(price).or_default().push_back(incoming.clone());
                        events.push(Event::OrderAccepted(incoming));
                    }
                }
            }
            Side::Sell => {
                while incoming.remaining_qty > 0 {
                    let best_bid_price = match book.bids.keys().next_back().copied() {
                        Some(p) => p,
                        None => break,
                    };

                    if let Some(limit) = incoming.price {
                        if best_bid_price < limit {
                            break;
                        }
                    }

                    let queue = book.bids.get_mut(&best_bid_price).unwrap();
                    while incoming.remaining_qty > 0 && !queue.is_empty() {
                        let mut resting = queue.pop_front().unwrap();
                        let fill_qty = incoming.remaining_qty.min(resting.remaining_qty);

                        incoming.remaining_qty -= fill_qty;
                        resting.remaining_qty -= fill_qty;

                        events.push(Event::OrderFilled {
                            order_id: incoming.order_id,
                            fill_qty,
                            remaining_qty: incoming.remaining_qty,
                            price: best_bid_price,
                        });

                        events.push(Event::OrderFilled {
                            order_id: resting.order_id,
                            fill_qty,
                            remaining_qty: resting.remaining_qty,
                            price: best_bid_price,
                        });

                        if resting.remaining_qty > 0 {
                            queue.push_front(resting);
                            break;
                        }
                    }

                    if queue.is_empty() {
                        book.bids.remove(&best_bid_price);
                    }
                }

                if incoming.remaining_qty > 0 {
                    if let Some(price) = incoming.price {
                        incoming.status = OrderStatus::Accepted;
                        book.asks.entry(price).or_default().push_back(incoming.clone());
                        events.push(Event::OrderAccepted(incoming));
                    }
                }
            }
        }

        events
    }

    pub fn cancel_order(&mut self, _order_id: Uuid) -> Option<Event> {
        None
    }
}
