    matching: Arc<Mutex<MatchingEngine>>,
    event_bus: EventBus,
    orders: Arc<DashMap<Uuid, Order>>,
}

impl OrderManager {
    pub fn new(risk: RiskEngine, matching: MatchingEngine, event_bus: EventBus) -> Self {
        Self {
            risk,
            matching: Arc::new(Mutex::new(matching)),
            event_bus,
            orders: Arc::new(DashMap::new()),
        }
    }

    pub async fn submit(&self, req: OrderRequest) -> ExecutionReport {
        let order = Order {
            order_id: Uuid::new_v4(),
            client_id: req.client_id,
            account: req.account,
            instrument: req.instrument,
            side: req.side,
            qty: req.qty,
            remaining_qty: req.qty,
            price: req.price,
            order_type: req.order_type,
            status: OrderStatus::New,
            created_at: Utc::now(),
        };

        self.event_bus.publish(Event::OrderReceived(order.clone()));

        match self.risk.check(&order) {
            RiskDecision::Reject(reason) => {
                self.event_bus.publish(Event::OrderRejected {
                    order_id: order.order_id,
                    reason: reason.clone(),
                });

                ExecutionReport {
                    order_id: order.order_id,
                    status: OrderStatus::Rejected,
                    filled_qty: 0,
                    remaining_qty: order.qty,
                    message: reason,
                    ts: Utc::now(),
                }
            }
            RiskDecision::Pass => {
                self.orders.insert(order.order_id, order.clone());

                let mut matching = self.matching.lock().await;
                let events = matching.process_order(order.clone());

                for event in &events {
                    self.event_bus.publish(event.clone());
                }

                let mut final_status = OrderStatus::Accepted;
                let mut remaining_qty = order.qty;
                let mut filled_qty = 0;

                for event in events {
                    if let Event::OrderFilled {
                        order_id,
                        fill_qty,
                        remaining_qty: rq,
                        ..
                    } = event
                    {
                        if order_id == order.order_id {
                            filled_qty += fill_qty;
                            remaining_qty = rq;
                        }
                    }
                }

                if remaining_qty == 0 {
                    final_status = OrderStatus::Filled;
                } else if filled_qty > 0 {
                    final_status = OrderStatus::PartiallyFilled;
                }

                let report = ExecutionReport {
                    order_id: order.order_id,
                    status: final_status,
                    filled_qty,
                    remaining_qty,
                    message: "processed".into(),
                    ts: Utc::now(),
                };

                self.event_bus.publish(Event::ExecutionReport(report.clone()));
                report
            }
        }
    }
}
