use crate::event_bus::EventBus;
use crate::types::Event;
use tokio::task;
use tracing::{error, info};

pub fn start_persistence_worker(event_bus: EventBus) {
    let mut rx = event_bus.subscribe();

    task::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(event) => {
                    persist_event(event).await;
                }
                Err(err) => {
                    error!("persistence worker recv error: {:?}", err);
                }
            }
        }
    });
}

async fn persist_event(event: Event) {
    info!("persisting event: {:?}", event);
}
