pub struct StrategyEngine<S: Strategy> {
    strategy: S,
    md_rx: Receiver<MarketDataTick>,
    order_tx: Sender<OrderRequest>,
}

impl<S: Strategy> StrategyEngine<S> {
    pub fn new(strategy: S, md_rx: Receiver<MarketDataTick>, order_tx: Sender<OrderRequest>) -> Self {
        Self { strategy, md_rx, order_tx }
    }

    pub fn run(mut self) {
        thread::spawn(move || {
            while let Ok(tick) = self.md_rx.recv() {
                if let Some(order) = self.strategy.on_market_data(tick) {
                    let _ = self.order_tx.send(order);
                }
            }
        });
    }
