## `risk` crate

### `risk/src/lib.rs`

```rust
use common::types::*;
use std::collections::HashMap;

pub struct RiskLimits {
    pub max_order_qty: u64,
    pub max_position_abs: i64,
    pub max_notional: u64,
    pub kill_switch: bool,
}

pub struct RiskEngine {
    pub limits: RiskLimits,
    pub positions: HashMap<InstrumentId, i64>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
        }
    }

    pub fn check(&self, req: &OrderRequest) -> RiskDecision {
        if self.limits.kill_switch {
            return RiskDecision::Rejected(RiskRejectReason::KillSwitch);
        }

        if req.qty > self.limits.max_order_qty {
            return RiskDecision::Rejected(RiskRejectReason::MaxOrderQty);
        }

        let current_pos = *self.positions.get(&req.instrument_id).unwrap_or(&0);
        let delta = match req.side {
            Side::Buy => req.qty as i64,
            Side::Sell => -(req.qty as i64),
        };

        if (current_pos + delta).abs() > self.limits.max_position_abs {
            return RiskDecision::Rejected(RiskRejectReason::PositionLimit);
        }

        let notional = (req.qty as i128) * (req.px as i128);
        if notional > self.limits.max_notional as i128 {
            return RiskDecision::Rejected(RiskRejectReason::NotionalLimit);
        }

        RiskDecision::Approved
    }

    pub fn apply_fill(&mut self, req: &OrderRequest, fill_qty: u64) {
        let pos = self.positions.entry(req.instrument_id).or_insert(0);
        match req.side {
            Side::Buy => *pos += fill_qty as i64,
            Side::Sell => *pos -= fill_qty as i64,
        }
    }
}
```

