```rust
use common::types::*;
use crossbeam_channel::{Receiver, Sender};
use risk::RiskEngine;
use std::collections::HashMap;
use std::thread;

pub struct Oms {
    next_order_id: u64,
    orders: HashMap<OrderId, Order>,
    risk: RiskEngine,
    order_req_rx: Receiver<OrderRequest>,
    exec_tx: Sender<Order>,
    exec_report_rx: Receiver<ExecutionReport>,
}

impl Oms {
    pub fn new(
        risk: RiskEngine,
        order_req_rx: Receiver<OrderRequest>,
        exec_tx: Sender<Order>,
        exec_report_rx: Receiver<ExecutionReport>,
    ) -> Self {
        Self {
            next_order_id: 1,
            orders: HashMap::new(),
            risk,
            order_req_rx,
            exec_tx,
            exec_report_rx,
        }
    }

    fn handle_order_request(&mut self, req: OrderRequest) {
        match self.risk.check(&req) {
            RiskDecision::Approved => {
                let order_id = OrderId(self.next_order_id);
                self.next_order_id += 1;

                let order = Order {
                    order_id,
                    request: req,
                    status: OrderStatus::PendingNew,
                    filled_qty: 0,
                };

                self.orders.insert(order_id, order);
                let _ = self.exec_tx.send(order);
            }
            RiskDecision::Rejected(reason) => {
                eprintln!("risk rejected order: {:?}", reason);
            }
        }
    }

    fn handle_exec_report(&mut self, report: ExecutionReport) {
        if let Some(order) = self.orders.get_mut(&report.order_id) {
            match report.exec_type {
                ExecutionType::Ack => {
                    order.status = OrderStatus::New;
                }
                ExecutionType::Fill => {
                    order.filled_qty += report.last_fill_qty;
                    self.risk.apply_fill(&order.request, report.last_fill_qty);

                    if order.filled_qty >= order.request.qty {
                        order.status = OrderStatus::Filled;
                    } else {
                        order.status = OrderStatus::PartiallyFilled;
                    }
                }
                ExecutionType::CancelAck => {
                    order.status = OrderStatus::Cancelled;
                }
                ExecutionType::Reject => {
                    order.status = OrderStatus::Rejected;
                }
            }
        }
    }

    pub fn run(mut self) {
        thread::spawn(move || loop {
            crossbeam_channel::select! {
                recv(self.order_req_rx) -> msg => {
                    match msg {
                        Ok(req) => self.handle_order_request(req),
                        Err(_) => break,
                    }
                }
                recv(self.exec_report_rx) -> msg => {
                    match msg {
                        Ok(report) => self.handle_exec_report(report),
                        Err(_) => break,
                    }
                }
            }
        });
    }
}
```

