```rust
use common::types::*;
use crossbeam_channel::{Receiver, Sender};
use std::{thread, time::Duration};

pub struct ExecutionGateway {
    order_rx: Receiver<Order>,
    report_tx: Sender<ExecutionReport>,
}

impl ExecutionGateway {
    pub fn new(order_rx: Receiver<Order>, report_tx: Sender<ExecutionReport>) -> Self {
        Self { order_rx, report_tx }
    }

    pub fn run(self) {
        thread::spawn(move || {
            while let Ok(order) = self.order_rx.recv() {
                let ack = ExecutionReport {
                    order_id: order.order_id,
                    exec_type: ExecutionType::Ack,
                    last_fill_qty: 0,
                    last_fill_px: 0,
                };
                let _ = self.report_tx.send(ack);

                thread::sleep(Duration::from_millis(1));

                let fill = ExecutionReport {
                    order_id: order.order_id,
                    exec_type: ExecutionType::Fill,
                    last_fill_qty: order.request.qty,
                    last_fill_px: order.request.px,
                };
                let _ = self.report_tx.send(fill);
            }
        });
    }
}
