This simulates a market data feed. In production, this would connect to exchange multicast, broker websocket, FIX/ITCH/OUCH, etc.

```rust
use crate::bus::EventBus;
use crate::types::{Event, MarketTick};
use rand::Rng;
use std::time::{Duration, Instant};
use tokio::time::sleep;

pub struct MarketDataEngine {
    bus: EventBus,
    symbols: Vec<String>,
}

impl MarketDataEngine {
    pub fn new(bus: EventBus, symbols: Vec<String>) -> Self {
        Self { bus, symbols }
    }

    pub async fn run(self) {
        let mut rng = rand::thread_rng();
        let mut prices: Vec<f64> = self.symbols.iter().map(|_| 100.0).collect();

        loop {
            for (i, symbol) in self.symbols.iter().enumerate() {
                let delta = rng.gen_range(-0.25..0.25);
                prices[i] = (prices[i] + delta).max(1.0);

                let tick = MarketTick {
                    symbol: symbol.clone(),
                    bid: prices[i] - 0.01,
                    ask: prices[i] + 0.01,
                    last: prices[i],
                    ts: Instant::now(),
                };

                self.bus.publish(Event::MarketTick(tick));
            }

            sleep(Duration::from_millis(10)).await;
        }
    }
}
