# src/strategy.rs

A simple example strategy: buy if price dips, sell if price rises relative to previous tick.

```rust
use crate::bus::EventBus;
use crate::types::{Event, MarketTick, Signal, Side};
use std::collections::HashMap;
use std::time::Instant;
use tracing::{info, warn};

pub struct StrategyEngine {
    bus: EventBus,
    last_prices: HashMap<String, f64>,
}

impl StrategyEngine {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            last_prices: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::MarketTick(MarketTick { symbol, last, .. })) => {
                    let maybe_prev = self.last_prices.insert(symbol.clone(), last);

                    if let Some(prev) = maybe_prev {
                        let change = (last - prev) / prev;

                        let signal = if change < -0.002 {
                            Some(Signal {
                                symbol,
                                side: Side::Buy,
                                qty: 10,
                                price: Some(last),
                                ts: Instant::now(),
                            })
                        } else if change > 0.002 {
                            Some(Signal {
                                symbol,
                                side: Side::Sell,
                                qty: 10,
                                price: Some(last),
                                ts: Instant::now(),
                            })
                        } else {
                            None
                        };

                        if let Some(signal) = signal {
                            info!("strategy signal: {:?}", signal);
                            self.bus.publish(Event::Signal(signal));
                        }
                    }
                }
                Ok(_) => {}
                Err(e) => {
                    warn!("strategy recv error: {}", e);
                }
            }
        }
    }
}
