# src/risk.rs

Basic pre-trade risk checks.

```rust
use crate::bus::EventBus;
use crate::config::Config;
use crate::types::{Event, OrderRequest, OrderStatus, OrderUpdate, Side, Signal};
use std::collections::HashMap;
use std::time::Instant;
use tracing::{info, warn};

pub struct RiskEngine {
    bus: EventBus,
    cfg: Config,
    positions: HashMap<String, i64>,
    next_order_id: u64,
}

impl RiskEngine {
    pub fn new(bus: EventBus, cfg: Config) -> Self {
        Self {
            bus,
            cfg,
            positions: HashMap::new(),
            next_order_id: 1,
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::Signal(signal)) => {
                    self.handle_signal(signal);
                }
                Ok(Event::OrderUpdate(update)) => {
                    if matches!(update.status, OrderStatus::Filled | OrderStatus::PartiallyFilled) {
                        // In a real system we'd map order_id -> order details.
                        // This initial version leaves position updates to a future enhancement.
                    }
                }
                Ok(_) => {}
                Err(e) => warn!("risk recv error: {}", e),
            }
        }
    }

    fn handle_signal(&mut self, signal: Signal) {
        if signal.qty > self.cfg.max_order_qty {
            let reject = OrderUpdate {
                order_id: 0,
                status: OrderStatus::Rejected,
                filled_qty: 0,
                remaining_qty: signal.qty,
                avg_fill_price: None,
                reason: Some("max_order_qty exceeded".to_string()),
                ts: Instant::now(),
            };
            self.bus.publish(Event::OrderUpdate(reject));
            return;
        }

        let pos = *self.positions.get(&signal.symbol).unwrap_or(&0);
        let projected = match signal.side {
            Side::Buy => pos + signal.qty as i64,
            Side::Sell => pos - signal.qty as i64,
        };

        if projected.abs() > self.cfg.max_position_abs {
            let reject = OrderUpdate {
                order_id: 0,
                status: OrderStatus::Rejected,
                filled_qty: 0,
                remaining_qty: signal.qty,
                avg_fill_price: None,
                reason: Some("max_position_abs exceeded".to_string()),
                ts: Instant::now(),
            };
            self.bus.publish(Event::OrderUpdate(reject));
            return;
        }

        let order = OrderRequest {
            order_id: self.next_order_id,
            symbol: signal.symbol,
            side: signal.side,
            qty: signal.qty,
            order_type: crate::types::OrderType::Limit,
            price: signal.price,
            ts: Instant::now(),
        };
        self.next_order_id += 1;

        info!("risk approved order: {:?}", order);
        self.bus.publish(Event::OrderRequest(order));
    }
}
```

