# src/order_manager.rs

Tracks order state and forwards to execution.

```rust
use crate::bus::EventBus;
use crate::types::{Event, OrderRequest, OrderStatus, OrderUpdate};
use std::collections::HashMap;
use std::time::Instant;
use tracing::{info, warn};

pub struct OrderManager {
    bus: EventBus,
    live_orders: HashMap<u64, OrderRequest>,
}

impl OrderManager {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            live_orders: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::OrderRequest(order)) => {
                    self.live_orders.insert(order.order_id, order.clone());

                    let accepted = OrderUpdate {
                        order_id: order.order_id,
                        status: OrderStatus::Accepted,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_fill_price: None,
                        reason: None,
                        ts: Instant::now(),
                    };

                    self.bus.publish(Event::OrderUpdate(accepted));
                    self.bus.publish(Event::OrderRequest(order));
                }
                Ok(Event::OrderUpdate(update)) => {
                    match update.status {
                        OrderStatus::Filled | OrderStatus::Cancelled | OrderStatus::Rejected => {
                            self.live_orders.remove(&update.order_id);
                        }
                        _ => {}
                    }
                }
                Ok(_) => {}
                Err(e) => warn!("order manager recv error: {}", e),
            }
        }
    }
}
