Simulated execution gateway.

```rust
use crate::bus::EventBus;
use crate::types::{Event, OrderRequest, OrderStatus, OrderUpdate};
use std::time::{Duration, Instant};
use tokio::time::sleep;
use tracing::{info, warn};

pub struct ExecutionGateway {
    bus: EventBus,
}

impl ExecutionGateway {
    pub fn new(bus: EventBus) -> Self {
        Self { bus }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::OrderRequest(order)) => {
                    self.execute(order).await;
                }
                Ok(_) => {}
                Err(e) => warn!("execution recv error: {}", e),
            }
        }
    }

    async fn execute(&self, order: OrderRequest) {
        info!("sending order to venue: {:?}", order);

        sleep(Duration::from_millis(2)).await;

        let fill = OrderUpdate {
            order_id: order.order_id,
            status: OrderStatus::Filled,
            filled_qty: order.qty,
            remaining_qty: 0,
            avg_fill_price: order.price,
            reason: None,
            ts: Instant::now(),
        };

        self.bus.publish(Event::OrderUpdate(fill));
    }
}
```

