use bus::EventBus;
use config::Config;
use execution::ExecutionGateway;
use market_data::MarketDataEngine;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tokio::task;
use tracing::info;
use types::{Event, OrderStatus};

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = Config::default();
    let bus = EventBus::new(1024);

    let md = MarketDataEngine::new(bus.clone(), cfg.symbols.clone());
    let strategy = StrategyEngine::new(bus.clone());
    let risk = RiskEngine::new(bus.clone(), cfg.clone());
    let exec = ExecutionGateway::new(bus.clone());

    task::spawn(md.run());
    task::spawn(strategy.run());
    task::spawn(risk.run());
    task::spawn(exec.run());

    let mut rx = bus.subscribe();
    while let Ok(event) = rx.recv().await {
        match event {
            Event::RiskRejected(update) => {
                info!("risk rejected order: {:?}", update);
            }
            Event::OrderAccepted(update) => {
                info!("order accepted: {:?}", update);
            }
            Event::ExecutionReport(update) => {
                match update.status {
                    OrderStatus::Filled => info!("fill: {:?}", update),
                    _ => info!("execution report: {:?}", update),
                }
            }
            _ => {}
        }
    }
}
