use crate::bus::EventBus;
use crate::types::{Event, MarketTick, Side, Signal};
use std::collections::HashMap;
use std::time::Instant;
use tracing::warn;

pub struct StrategyEngine {
    bus: EventBus,
    last_prices: HashMap<String, f64>,
}

impl StrategyEngine {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            last_prices: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::MarketTick(MarketTick { symbol, last, .. })) => {
                    let prev = self.last_prices.insert(symbol.clone(), last);
                    if let Some(prev) = prev {
                        let change = (last - prev) / prev;

                        if change < -0.002 {
                            self.bus.publish(Event::Signal(Signal {
                                symbol,
                                side: Side::Buy,
                                qty: 10,
                                price: Some(last),
                                ts: Instant::now(),
                            }));
                        } else if change > 0.002 {
                            self.bus.publish(Event::Signal(Signal {
                                symbol,
                                side: Side::Sell,
                                qty: 10,
                                price: Some(last),
                                ts: Instant::now(),
                            }));
                        }
                    }
                }
                Ok(_) => {}
                Err(e) => warn!("strategy recv error: {}", e),
            }
        }
    }
}
