use crate::bus::EventBus;
use crate::types::{Event, OrderStatus, OrderUpdate};
use std::time::{Duration, Instant};
use tokio::time::sleep;
use tracing::warn;

pub struct ExecutionGateway {
    bus: EventBus,
}

impl ExecutionGateway {
    pub fn new(bus: EventBus) -> Self {
        Self { bus }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe();

        loop {
            match rx.recv().await {
                Ok(Event::RiskApprovedOrder(order)) => {
                    self.bus.publish(Event::OrderAccepted(OrderUpdate {
                        order_id: order.order_id,
                        status: OrderStatus::Accepted,
                        filled_qty: 0,
                        remaining_qty: order.qty,
                        avg_fill_price: None,
                        reason: None,
                        ts: Instant::now(),
                    }));

                    sleep(Duration::from_millis(2)).await;

                    self.bus.publish(Event::ExecutionReport(OrderUpdate {
                        order_id: order.order_id,
                        status: OrderStatus::Filled,
                        filled_qty: order.qty,
                        remaining_qty: 0,
                        avg_fill_price: order.price,
                        reason: None,
                        ts: Instant::now(),
                    }));
                }
                Ok(_) => {}
                Err(e) => warn!("execution recv error: {}", e),
            }
        }
    }
}
