package com.example.trading.strategy;

import com.example.trading.bus.EventBus;
import com.example.trading.common.Side;
import com.example.trading.event.MarketDataEvent;
import com.example.trading.event.SignalEvent;

public class MeanReversionStrategy implements Strategy {

    private final EventBus eventBus;
    private final String strategyId;
    private final String symbol;
    private final double fairValue;
    private final double threshold;
    private final int quantity;

    public MeanReversionStrategy(EventBus eventBus, String strategyId, String symbol,
                                 double fairValue, double threshold, int quantity) {
        this.eventBus = eventBus;
        this.strategyId = strategyId;
        this.symbol = symbol;
        this.fairValue = fairValue;
        this.threshold = threshold;
        this.quantity = quantity;
    }

    @Override
    public void onMarketData(MarketDataEvent event) {
        if (!event.symbol().equals(symbol)) return;

        if (event.ask() < fairValue - threshold) {
            eventBus.publish(new SignalEvent(
                    System.nanoTime(), symbol, Side.BUY, quantity, strategyId
            ));
        } else if (event.bid() > fairValue + threshold) {
            eventBus.publish(new SignalEvent(
                    System.nanoTime(), symbol, Side.SELL, quantity, strategyId
            ));
        }
    }
}
