package com.example.trading.position;

import com.example.trading.common.Side;
import com.example.trading.event.FillEvent;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class PositionService {

    private final Map<String, Integer> netPositions = new ConcurrentHashMap<>();

    public void onFill(FillEvent fill) {
        int delta = fill.side() == Side.BUY ? fill.quantity() : -fill.quantity();
        netPositions.merge(fill.symbol(), delta, Integer::sum);
    }

    public int getNetPosition(String symbol) {
        return netPositions.getOrDefault(symbol, 0);
    }
