package com.example.trading.risk;

import com.example.trading.bus.EventBus;
import com.example.trading.common.Side;
import com.example.trading.event.OrderAcceptedEvent;
import com.example.trading.event.OrderRequestEvent;
import com.example.trading.event.RiskRejectedEvent;
import com.example.trading.position.PositionService;

public class RiskEngine {

    private final EventBus eventBus;
    private final RiskLimits limits;
    private final PositionService positionService;

    public RiskEngine(EventBus eventBus, RiskLimits limits, PositionService positionService) {
        this.eventBus = eventBus;
        this.limits = limits;
        this.positionService = positionService;
    }

    public void start() {
        eventBus.subscribe(OrderRequestEvent.class, order -> {
            if (order.quantity() > limits.maxOrderQuantity()) {
                eventBus.publish(new RiskRejectedEvent(
                        System.nanoTime(),
                        order.orderId(),
                        "Order quantity exceeds maxOrderQuantity"
                ));
                return;
            }

            int currentPos = positionService.getNetPosition(order.symbol());
            int projectedPos = currentPos + (order.side() == Side.BUY ? order.quantity() : -order.quantity());

            if (Math.abs(projectedPos) > limits.maxNetPosition()) {
                eventBus.publish(new RiskRejectedEvent(
                        System.nanoTime(),
                        order.orderId(),
                        "Projected position exceeds maxNetPosition"
                ));
                return;
            }

            eventBus.publish(new OrderAcceptedEvent(
                    System.nanoTime(),
                    order.orderId(),
                    order.symbol()
            ));
        });
    }
}
