package com.example.trading.execution;

import com.example.trading.bus.EventBus;
import com.example.trading.event.FillEvent;
import com.example.trading.event.OrderRequestEvent;

public class SimulatedExecutionGateway implements ExecutionGateway {

    private final EventBus eventBus;

    public SimulatedExecutionGateway(EventBus eventBus) {
        this.eventBus = eventBus;
    }

    @Override
    public void send(OrderRequestEvent order) {
        double fillPrice = order.price() > 0 ? order.price() : 100.0;
        eventBus.publish(new FillEvent(
                System.nanoTime(),
                order.orderId(),
                order.symbol(),
                order.side(),
                order.quantity(),
                fillPrice
        ));
    }
}
