import com.example.trading.event.OrderAcceptedEvent;
import com.example.trading.event.OrderRequestEvent;
import com.example.trading.execution.ExecutionGateway;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class OrderManager {

    private final EventBus eventBus;
    private final ExecutionGateway executionGateway;
    private final Map<String, OrderRequestEvent> pendingOrders = new ConcurrentHashMap<>();

    public OrderManager(EventBus eventBus, ExecutionGateway executionGateway) {
        this.eventBus = eventBus;
        this.executionGateway = executionGateway;
    }

    public void start() {
        eventBus.subscribe(OrderRequestEvent.class, order -> {
            pendingOrders.put(order.orderId(), order);
        });

        eventBus.subscribe(OrderAcceptedEvent.class, accepted -> {
            OrderRequestEvent order = pendingOrders.get(accepted.orderId());
            if (order != null) {
                executionGateway.send(order);
            }
        });
    }
}
