## `src/orderbook.rs`

```rust
use std::collections::{BTreeMap, VecDeque};

use crate::model::{Order, Side, Trade};

pub struct OrderBook {
    pub symbol: u32,
    bids: BTreeMap<u64, VecDeque<Order>>,
    asks: BTreeMap<u64, VecDeque<Order>>,
}

impl OrderBook {
    pub fn new(symbol: u32) -> Self {
        Self {
            symbol,
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    pub fn add_order(&mut self, order: Order) {
        let book_side = match order.side {
            Side::Buy => &mut self.bids,
            Side::Sell => &mut self.asks,
        };
        book_side.entry(order.price).or_default().push_back(order);
    }

    pub fn match_order(&mut self, incoming: &mut Order, ts_ns: u64) -> Vec<Trade> {
        let mut trades = Vec::new();

        match incoming.side {
            Side::Buy => {
                while incoming.remaining_qty > 0 {
                    let best_ask_price = match self.asks.keys().next().cloned() {
                        Some(p) => p,
                        None => break,
                    };

                    if incoming.price < best_ask_price {
                        break;
                    }

                    let level_empty;
                    {
                        let level = self.asks.get_mut(&best_ask_price).unwrap();
                        while incoming.remaining_qty > 0 && !level.is_empty() {
                            let resting = level.front_mut().unwrap();
                            let fill_qty = incoming.remaining_qty.min(resting.remaining_qty);
                            incoming.remaining_qty -= fill_qty;
                            resting.remaining_qty -= fill_qty;

                            trades.push(Trade {
                                symbol: incoming.symbol,
                                buy_order_id: incoming.order_id,
                                sell_order_id: resting.order_id,
                                price: resting.price,
                                qty: fill_qty,
                                ts_ns,
                            });

                            if resting.remaining_qty == 0 {
                                level.pop_front();
                            }
                        }
                        level_empty = level.is_empty();
                    }
                    if level_empty {
                        self.asks.remove(&best_ask_price);
                    }
                }
            }
            Side::Sell => {
                while incoming.remaining_qty > 0 {
                    let best_bid_price = match self.bids.keys().next_back().cloned() {
                        Some(p) => p,
                        None => break,
                    };

                    if incoming.price > best_bid_price {
                        break;
                    }

                    let level_empty;
                    {
                        let level = self.bids.get_mut(&best_bid_price).unwrap();
                        while incoming.remaining_qty > 0 && !level.is_empty() {
                            let resting = level.front_mut().unwrap();
                            let fill_qty = incoming.remaining_qty.min(resting.remaining_qty);
                            incoming.remaining_qty -= fill_qty;
                            resting.remaining_qty -= fill_qty;

                            trades.push(Trade {
                                symbol: incoming.symbol,
                                buy_order_id: resting.order_id,
                                sell_order_id: incoming.order_id,
                                price: resting.price,
                                qty: fill_qty,
                                ts_ns,
                            });

                            if resting.remaining_qty == 0 {
                                level.pop_front();
                            }
                        }
                        level_empty = level.is_empty();
                    }
                    if level_empty {
                        self.bids.remove(&best_bid_price);
                    }
                }
            }
        }

        trades
    }
}
