## `src/engine.rs`

```rust
use std::collections::HashMap;

use crate::eventlog::EventLog;
use crate::model::{Event, NewOrderRequest, Order, OrderType};
use crate::orderbook::OrderBook;
use crate::risk;

pub struct Exchange {
    next_order_id: u64,
    books: HashMap<u32, OrderBook>,
    event_log: EventLog,
}

impl Exchange {
    pub fn new(event_log: EventLog) -> Self {
        Self {
            next_order_id: 1,
            books: HashMap::new(),
            event_log,
        }
    }

    pub fn submit_order(&mut self, req: NewOrderRequest) -> Vec<Event> {
        let mut out = Vec::new();

        if let Err(reason) = risk::check_order(&req) {
            let ev = Event::OrderRejected {
                client_id: req.client_id,
                reason,
            };
            self.event_log.append(ev.clone());
            out.push(ev);
            return out;
        }

        let order_id = self.next_order_id;
        self.next_order_id += 1;

        let mut order = Order {
            order_id,
            client_id: req.client_id,
            symbol: req.symbol,
            side: req.side,
            price: req.price,
            qty: req.qty,
            remaining_qty: req.qty,
            timestamp_ns: req.timestamp_ns,
        };

        let accepted = Event::OrderAccepted {
            order_id,
            client_id: req.client_id,
            symbol: req.symbol,
        };
        self.event_log.append(accepted.clone());
        out.push(accepted);

        let book = self.books.entry(req.symbol).or_insert_with(|| OrderBook::new(req.symbol));

        let trades = book.match_order(&mut order, req.timestamp_ns);
        for trade in trades {
            let ev = Event::Trade(trade);
            self.event_log.append(ev.clone());
            out.push(ev);
        }

        if order.remaining_qty > 0 && matches!(req.order_type, OrderType::Limit) {
            book.add_order(order.clone());
            let placed = Event::OrderPlaced {
                order_id: order.order_id,
                symbol: order.symbol,
                side: order.side,
                price: order.price,
                qty: order.remaining_qty,
            };
            self.event_log.append(placed.clone());
            out.push(placed);
        }

        out
    }

    pub fn events(&self) -> &[Event] {
        self.event_log.all()
    }
}
