use std::sync::Arc;

use axum::{
    extract::State,
    routing::{get, post},
    Json, Router,
};
use tokio::sync::Mutex;

use crate::engine::Exchange;
use crate::model::{Event, NewOrderRequest};

#[derive(Clone)]
pub struct AppState {
    pub exchange: Arc<Mutex<Exchange>>,
}

pub async fn serve(exchange: Arc<Mutex<Exchange>>) {
    let state = AppState { exchange };

    let app = Router::new()
        .route("/order", post(submit_order))
        .route("/events", get(get_events))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

async fn submit_order(
    State(state): State<AppState>,
    Json(req): Json<NewOrderRequest>,
) -> Json<Vec<Event>> {
    let mut exchange = state.exchange.lock().await;
    let events = exchange.submit_order(req);
    Json(events)
}

async fn get_events(State(state): State<AppState>) -> Json<Vec<Event>> {
    let exchange = state.exchange.lock().await;
    Json(exchange.events().to_vec())
}
