# Main implementation

```rust
use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

type Topic = u64;
type SubscriberId = u64;

#[derive(Clone)]
struct Message {
    topic: Topic,
    payload: Arc<[u8]>,
    created_at: Instant,
    sequence: u64,
}

struct Subscriber {
    id: SubscriberId,
    tx: Sender<Message>,
}

struct Metrics {
    ingress: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    subscriber_dropped: AtomicU64,
    processed: AtomicU64,
    latency_ns_total: AtomicU64,
    latency_ns_max: AtomicU64,
    histogram: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            ingress: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            subscriber_dropped: AtomicU64::new(0),
            processed: AtomicU64::new(0),
            latency_ns_total: AtomicU64::new(0),
            latency_ns_max: AtomicU64::new(0),
            histogram: Mutex::new(Histogram::<u64>::new(3).unwrap()),
        }
    }

    fn record_latency(&self, latency: Duration) {
        let ns = latency.as_nanos() as u64;
        self.latency_ns_total.fetch_add(ns, Ordering::Relaxed);

        let mut current = self.latency_ns_max.load(Ordering::Relaxed);
        while ns > current {
            match self.latency_ns_max.compare_exchange_weak(
                current,
                ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }

        if let Ok(mut hist) = self.histogram.lock() {
            let _ = hist.record(ns);
        }
    }
}

struct Router {
    ingress_tx: Sender<Message>,
    subscriptions: Arc<DashMap<Topic, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
}

impl Router {
    fn new(ingress_capacity: usize, worker_count: usize) -> Self {
        let (ingress_tx, ingress_rx) = bounded::<Message>(ingress_capacity);
        let subscriptions = Arc::new(DashMap::<Topic, Vec<Subscriber>>::new());
        let metrics = Arc::new(Metrics::new());
        let running = Arc::new(AtomicBool::new(true));

        for worker_id in 0..worker_count {
            let rx = ingress_rx.clone();
            let subs = Arc::clone(&subscriptions);
            let metrics_clone = Arc::clone(&metrics);
            let running_clone = Arc::clone(&running);

            thread::Builder::new()
                .name(format!("router-worker-{worker_id}"))
                .spawn(move || {
                    router_worker(rx, subs, metrics_clone, running_clone);
                })
                .expect("failed to spawn router worker");
        }

        Self {
            ingress_tx,
            subscriptions,
            metrics,
            running,
        }
    }

    fn publish(&self, msg: Message) -> Result<(), &'static str> {
        self.metrics.ingress.fetch_add(1, Ordering::Relaxed);
        match self.ingress_tx.try_send(msg) {
            Ok(_) => Ok(()),
            Err(TrySendError::Full(_)) => {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                Err("ingress queue full")
            }
            Err(TrySendError::Disconnected(_)) => Err("router stopped"),
        }
    }

    fn subscribe(&self, topic: Topic, subscriber_id: SubscriberId, queue_capacity: usize) -> Receiver<Message> {
        let (tx, rx) = bounded(queue_capacity);
        let subscriber = Subscriber {
            id: subscriber_id,
            tx,
        };

        self.subscriptions
            .entry(topic)
            .and_modify(|subs| subs.push(subscriber.clone()))
            .or_insert_with(|| vec![subscriber]);

        rx
    }

    fn metrics(&self) -> Arc<Metrics> {
        Arc::clone(&self.metrics)
    }

    fn shutdown(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

impl Clone for Subscriber {
    fn clone(&self) -> Self {
        Self {
            id: self.id,
            tx: self.tx.clone(),
        }
    }
}

fn router_worker(
    ingress_rx: Receiver<Message>,
    subscriptions: Arc<DashMap<Topic, Vec<Subscriber>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match ingress_rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                if let Some(subs_ref) = subscriptions.get(&msg.topic) {
                    for sub in subs_ref.iter() {
                        match sub.tx.try_send(msg.clone()) {
                            Ok(_) => {
                                metrics.routed.fetch_add(1, Ordering::Relaxed);
                            }
                            Err(TrySendError::Full(_)) => {
                                metrics.subscriber_dropped.fetch_add(1, Ordering::Relaxed);
                            }
                            Err(TrySendError::Disconnected(_)) => {
                                metrics.subscriber_dropped.fetch_add(1, Ordering::Relaxed);
                            }
                        }
                    }
                }
            }
            Err(_) => {}
        }
    }
}

fn start_consumer(
    consumer_name: String,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::Builder::new()
        .name(consumer_name.clone())
        .spawn(move || {
            while running.load(Ordering::Relaxed) {
                match rx.recv_timeout(Duration::from_millis(10)) {
                    Ok(msg) => {
                        let latency = msg.created_at.elapsed();
                        metrics.processed.fetch_add(1, Ordering::Relaxed);
                        metrics.record_latency(latency);

                        // Simulated processing
                        std::hint::black_box(&msg.payload);
                    }
                    Err(_) => {}
                }
            }
        })
        .expect("failed to spawn consumer")
}

fn start_metrics_reporter(metrics: Arc<Metrics>, running: Arc<AtomicBool>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_ingress = 0;
        let mut last_routed = 0;
        let mut last_processed = 0;
        let mut last_dropped = 0;
        let mut last_sub_dropped = 0;

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let ingress = metrics.ingress.load(Ordering::Relaxed);
            let routed = metrics.routed.load(Ordering::Relaxed);
            let processed = metrics.processed.load(Ordering::Relaxed);
            let dropped = metrics.dropped.load(Ordering::Relaxed);
            let sub_dropped = metrics.subscriber_dropped.load(Ordering::Relaxed);

            let ingress_rate = ingress - last_ingress;
            let routed_rate = routed - last_routed;
            let processed_rate = processed - last_processed;
            let dropped_rate = dropped - last_dropped;
            let sub_dropped_rate = sub_dropped - last_sub_dropped;

            last_ingress = ingress;
            last_routed = routed;
            last_processed = processed;
            last_dropped = dropped;
            last_sub_dropped = sub_dropped;

            let hist_snapshot = {
                let hist = metrics.histogram.lock().unwrap();
                hist.clone()
            };

            let p50 = if hist_snapshot.len() > 0 {
                hist_snapshot.value_at_quantile(0.50)
            } else {
                0
            };
            let p95 = if hist_snapshot.len() > 0 {
                hist_snapshot.value_at_quantile(0.95)
            } else {
                0
            };
            let p99 = if hist_snapshot.len() > 0 {
                hist_snapshot.value_at_quantile(0.99)
            } else {
                0
            };
            let max = metrics.latency_ns_max.load(Ordering::Relaxed);

            println!(
                "ingress/s={} routed/s={} processed/s={} dropped/s={} sub_dropped/s={} latency_ns p50={} p95={} p99={} max={}",
                ingress_rate,
                routed_rate,
                processed_rate,
                dropped_rate,
                sub_dropped_rate,
                p50,
                p95,
                p99,
                max
            );
        }
    })
}

fn main() {
    let router = Router::new(
        1_000_000, // ingress queue capacity
        4,         // router workers
    );

    let running = Arc::clone(&router.running);
    let metrics = router.metrics();

    let topic_count = 8;
    let subscribers_per_topic = 2;

    let mut consumer_handles = Vec::new();

    for topic in 0..topic_count {
        for sid in 0..subscribers_per_topic {
            let rx = router.subscribe(topic, sid as u64, 100_000);
            let handle = start_consumer(
                format!("consumer-topic-{topic}-sub-{sid}"),
                rx,
                Arc::clone(&metrics),
                Arc::clone(&running),
            );
            consumer_handles.push(handle);
        }
    }

    let metrics_handle = start_metrics_reporter(Arc::clone(&metrics), Arc::clone(&running));

    let producer_threads = 4;
    let messages_per_thread = 5_000_000usize;

    let mut producers = Vec::new();

    for producer_id in 0..producer_threads {
        let router_ref = Router {
            ingress_tx: router.ingress_tx.clone(),
            subscriptions: Arc::clone(&router.subscriptions),
            metrics: Arc::clone(&router.metrics),
            running: Arc::clone(&router.running),
        };

        let handle = thread::Builder::new()
            .name(format!("producer-{producer_id}"))
            .spawn(move || {
                let mut rng = rand::thread_rng();
                let payload: Arc<[u8]> = Arc::from(vec![0u8; 128].into_boxed_slice());

                for seq in 0..messages_per_thread {
                    let topic = rng.gen_range(0..topic_count as u64);
                    let msg = Message {
                        topic,
                        payload: payload.clone(),
                        created_at: Instant::now(),
                        sequence: seq as u64,
                    };

                    let _ = router_ref.publish(msg);
                }
            })
            .expect("failed to spawn producer");

        producers.push(handle);
    }

    for handle in producers {
        handle.join().unwrap();
    }

    thread::sleep(Duration::from_secs(5));
    router.shutdown();

    for handle in consumer_handles {
        let _ = handle.join();
    }

    let _ = metrics_handle.join();
}
```

