use bytes::Bytes;
use dashmap::DashMap;
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use rand::Rng;
use std::{
    collections::HashMap,
    fmt,
    sync::{
        atomic::{AtomicU64, AtomicUsize, Ordering},
        Arc,
    },
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use thiserror::Error;
use tokio::{
    sync::mpsc,
    task,
    time::{interval, Instant},
};

type Topic = String;
type SubscriberId = usize;

#[derive(Clone)]
pub struct Message {
    pub id: u64,
    pub topic: Arc<str>,
    pub payload: Bytes,
    pub created_at_nanos: u128,
}

impl Message {
    pub fn new(id: u64, topic: Arc<str>, payload: Bytes) -> Self {
        Self {
            id,
            topic,
            payload,
            created_at_nanos: now_nanos(),
        }
    }

    pub fn latency_nanos(&self) -> u128 {
        now_nanos().saturating_sub(self.created_at_nanos)
    }
}

fn now_nanos() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos()
}

#[derive(Default)]
pub struct Metrics {
    published: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    subscriber_send_failures: AtomicU64,
    active_subscribers: AtomicUsize,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    pub fn new() -> Self {
        let hist = Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3)
            .expect("failed to create histogram");
        Self {
            published: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            subscriber_send_failures: AtomicU64::new(0),
            active_subscribers: AtomicUsize::new(0),
            latency_hist: Mutex::new(hist),
        }
    }

    pub fn record_publish(&self) {
        self.published.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_routed(&self) {
        self.routed.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_drop(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_send_failure(&self) {
        self.subscriber_send_failures
            .fetch_add(1, Ordering::Relaxed);
    }

    pub fn set_active_subscribers(&self, count: usize) {
        self.active_subscribers.store(count, Ordering::Relaxed);
    }

    pub fn record_latency_ns(&self, latency_ns: u64) {
        let mut hist = self.latency_hist.lock();
        let _ = hist.record(latency_ns.max(1));
    }

    pub fn snapshot(&self) -> MetricsSnapshot {
        let hist = self.latency_hist.lock();
        MetricsSnapshot {
            published: self.published.load(Ordering::Relaxed),
            routed: self.routed.load(Ordering::Relaxed),
            dropped: self.dropped.load(Ordering::Relaxed),
            subscriber_send_failures: self
                .subscriber_send_failures
                .load(Ordering::Relaxed),
            active_subscribers: self.active_subscribers.load(Ordering::Relaxed),
            p50_ns: hist.value_at_quantile(0.50),
            p95_ns: hist.value_at_quantile(0.95),
            p99_ns: hist.value_at_quantile(0.99),
            max_ns: hist.max(),
        }
    }
}

pub struct MetricsSnapshot {
    pub published: u64,
    pub routed: u64,
    pub dropped: u64,
    pub subscriber_send_failures: u64,
    pub active_subscribers: usize,
    pub p50_ns: u64,
    pub p95_ns: u64,
    pub p99_ns: u64,
    pub max_ns: u64,
}

impl fmt::Display for MetricsSnapshot {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "published={} routed={} dropped={} send_failures={} active_subscribers={} latency_ns[p50={}, p95={}, p99={}, max={}]",
            self.published,
            self.routed,
            self.dropped,
            self.subscriber_send_failures,
            self.active_subscribers,
            self.p50_ns,
            self.p95_ns,
            self.p99_ns,
            self.max_ns
        )
    }
}

#[derive(Error, Debug)]
pub enum RouterError {
    #[error("subscriber channel full")]
    SubscriberChannelFull,
    #[error("subscriber channel closed")]
    SubscriberChannelClosed,
}

#[derive(Clone)]
pub struct SubscriberHandle {
    pub id: SubscriberId,
    pub topic: Arc<str>,
}

#[derive(Clone)]
struct Subscriber {
    id: SubscriberId,
    tx: mpsc::Sender<Message>,
}

pub struct Router {
    subscriptions: DashMap<Topic, Vec<Subscriber>>,
    metrics: Arc<Metrics>,
    next_subscriber_id: AtomicUsize,
}

impl Router {
    pub fn new(metrics: Arc<Metrics>) -> Self {
        Self {
            subscriptions: DashMap::new(),
            metrics,
            next_subscriber_id: AtomicUsize::new(1),
        }
    }

    pub fn subscribe(
        &self,
        topic: impl Into<String>,
        buffer: usize,
    ) -> (SubscriberHandle, mpsc::Receiver<Message>) {
        let topic = topic.into();
        let subscriber_id = self.next_subscriber_id.fetch_add(1, Ordering::Relaxed);
        let (tx, rx) = mpsc::channel(buffer);

        let subscriber = Subscriber {
            id: subscriber_id,
            tx,
        };

        self.subscriptions
            .entry(topic.clone())
            .or_insert_with(Vec::new)
            .push(subscriber);

        let total = self
            .subscriptions
            .iter()
            .map(|entry| entry.value().len())
            .sum::<usize>();
        self.metrics.set_active_subscribers(total);

        (
            SubscriberHandle {
                id: subscriber_id,
                topic: Arc::from(topic),
            },
            rx,
        )
    }

    pub fn unsubscribe(&self, handle: &SubscriberHandle) {
        if let Some(mut subs) = self.subscriptions.get_mut(handle.topic.as_ref()) {
            subs.retain(|s| s.id != handle.id);
        }

        let total = self
            .subscriptions
            .iter()
            .map(|entry| entry.value().len())
            .sum::<usize>();
        self.metrics.set_active_subscribers(total);
    }

    pub fn publish(&self, msg: Message) {
        self.metrics.record_publish();

        if let Some(subscribers) = self.subscriptions.get(msg.topic.as_ref()) {
            for sub in subscribers.iter() {
                match sub.tx.try_send(msg.clone()) {
                    Ok(_) => {
                        self.metrics.record_routed();
                    }
                    Err(tokio::sync::mpsc::error::TrySendError::Full(_)) => {
                        self.metrics.record_drop();
                    }
                    Err(tokio::sync::mpsc::error::TrySendError::Closed(_)) => {
                        self.metrics.record_send_failure();
                    }
                }
            }
        }
    }

    pub fn metrics(&self) -> Arc<Metrics> {
        self.metrics.clone()
    }
}

async fn subscriber_worker(
    worker_name: String,
    mut rx: mpsc::Receiver<Message>,
    metrics: Arc<Metrics>,
) {
    while let Some(msg) = rx.recv().await {
        let latency_ns = msg.latency_nanos() as u64;
        metrics.record_latency_ns(latency_ns);

        // Simulate message handling work.
        // Replace with real business logic.
        black_box_process(&worker_name, &msg).await;
    }
}

