async fn metrics_reporter(metrics: Arc<Metrics>) {
    let mut ticker = interval(Duration::from_secs(1));
    loop {
        ticker.tick().await;
        let snapshot = metrics.snapshot();
        println!("[METRICS] {}", snapshot);
