async fn producer_task(router: Arc<Router>, producer_id: usize, topic: Arc<str>, rate_hint: usize) {
    let mut seq: u64 = 0;
    let payload = Bytes::from(vec![42u8; 256]);

    loop {
        for _ in 0..rate_hint {
            seq += 1;
            let id = ((producer_id as u64) << 48) | seq;
            let msg = Message::new(id, topic.clone(), payload.clone());
            router.publish(msg);
        }

        task::yield_now().await;
    }
}

