```rust
use bytes::Bytes;
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const INGRESS_CAPACITY: usize = 1_000_000;
const DEST_CAPACITY: usize = 1_000_000;
const ROUTER_THREADS: usize = 4;
const DEST_SHARDS: usize = 8;
const PAYLOAD_SIZE: usize = 128;

#[inline(always)]
fn now_nanos() -> u64 {
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap();
    dur.as_nanos() as u64
}

#[derive(Clone)]
struct Message {
    id: u64,
    topic: u64,
    created_at_ns: u64,
    ingress_at_ns: u64,
    routed_at_ns: u64,
    payload: Bytes,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    consumed: AtomicU64,
    end_to_end_ns: Mutex<Histogram<u64>>,
    ingress_to_route_ns: Mutex<Histogram<u64>>,
    route_to_consume_ns: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            consumed: AtomicU64::new(0),
            end_to_end_ns: Mutex::new(Histogram::new_with_bounds(1, 60_000_000_000, 3).unwrap()),
            ingress_to_route_ns: Mutex::new(Histogram::new_with_bounds(1, 60_000_000_000, 3).unwrap()),
            route_to_consume_ns: Mutex::new(Histogram::new_with_bounds(1, 60_000_000_000, 3).unwrap()),
        }
    }

    fn record_ingress_to_route(&self, v: u64) {
        if let Ok(mut h) = self.ingress_to_route_ns.lock() {
            let _ = h.record(v.max(1));
        }
    }

    fn record_route_to_consume(&self, v: u64) {
        if let Ok(mut h) = self.route_to_consume_ns.lock() {
            let _ = h.record(v.max(1));
        }
    }

    fn record_end_to_end(&self, v: u64) {
        if let Ok(mut h) = self.end_to_end_ns.lock() {
            let _ = h.record(v.max(1));
        }
    }

    fn report(&self) {
        let received = self.received.load(Ordering::Relaxed);
        let routed = self.routed.load(Ordering::Relaxed);
        let dropped = self.dropped.load(Ordering::Relaxed);
        let consumed = self.consumed.load(Ordering::Relaxed);

        println!("==== metrics ====");
        println!("received={received} routed={routed} consumed={consumed} dropped={dropped}");

        if let Ok(h) = self.ingress_to_route_ns.lock() {
            if h.len() > 0 {
                println!(
                    "ingress->route ns: p50={} p95={} p99={} max={}",
                    h.value_at_quantile(0.50),
                    h.value_at_quantile(0.95),
                    h.value_at_quantile(0.99),
                    h.max()
                );
            }
        }

        if let Ok(h) = self.route_to_consume_ns.lock() {
            if h.len() > 0 {
                println!(
                    "route->consume ns: p50={} p95={} p99={} max={}",
                    h.value_at_quantile(0.50),
                    h.value_at_quantile(0.95),
                    h.value_at_quantile(0.99),
                    h.max()
                );
            }
        }

        if let Ok(h) = self.end_to_end_ns.lock() {
            if h.len() > 0 {
                println!(
                    "end-to-end ns: p50={} p95={} p99={} max={}",
                    h.value_at_quantile(0.50),
                    h.value_at_quantile(0.95),
                    h.value_at_quantile(0.99),
                    h.max()
                );
            }
        }
    }
}

#[inline(always)]
fn route_shard(topic: u64, shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % shards
}

fn producer_thread(tx: Sender<Message>, metrics: Arc<Metrics>, running: Arc<AtomicBool>, producer_id: u64) {
    let mut seq: u64 = 0;
    let payload = vec![0u8; PAYLOAD_SIZE];

    while running.load(Ordering::Relaxed) {
        let now = now_nanos();
        let msg = Message {
            id: (producer_id << 48) | seq,
            topic: rand::thread_rng().gen_range(0..10_000),
            created_at_ns: now,
            ingress_at_ns: now,
            routed_at_ns: 0,
            payload: Bytes::copy_from_slice(&payload),
        };

        match tx.try_send(msg) {
            Ok(_) => {
                metrics.received.fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {
                metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }

        seq = seq.wrapping_add(1);
    }
}

fn router_thread(
    rx: Receiver<Message>,
    dest_txs: Arc<Vec<Sender<Message>>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
    core_id: Option<core_affinity::CoreId>,
) {
    if let Some(core) = core_id {
        core_affinity::set_for_current(core);
    }

    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_micros(100)) {
            Ok(mut msg) => {
                let routed_at = now_nanos();
                msg.routed_at_ns = routed_at;
                metrics.record_ingress_to_route(routed_at.saturating_sub(msg.ingress_at_ns));

                let shard = route_shard(msg.topic, dest_txs.len());
                match dest_txs[shard].try_send(msg) {
                    Ok(_) => {
                        metrics.routed.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(_) => {
                        metrics.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Err(_) => {}
        }
    }
}

fn consumer_thread(
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
    core_id: Option<core_affinity::CoreId>,
) {
    if let Some(core) = core_id {
        core_affinity::set_for_current(core);
    }

    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_micros(100)) {
            Ok(msg) => {
                let now = now_nanos();

                metrics.record_route_to_consume(now.saturating_sub(msg.routed_at_ns));
                metrics.record_end_to_end(now.saturating_sub(msg.created_at_ns));
                metrics.consumed.fetch_add(1, Ordering::Relaxed);

                // Simulate very lightweight downstream handling
                std::hint::black_box(&msg.payload);
            }
            Err(_) => {}
        }
    }
}

fn metrics_thread(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(2));
        metrics.report();
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let running = Arc::new(AtomicBool::new(true));

    let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_CAPACITY);

    let mut dest_txs = Vec::with_capacity(DEST_SHARDS);
    let mut dest_rxs = Vec::with_capacity(DEST_SHARDS);

    for _ in 0..DEST_SHARDS {
        let (tx, rx) = bounded::<Message>(DEST_CAPACITY);
        dest_txs.push(tx);
        dest_rxs.push(rx);
    }

    let dest_txs = Arc::new(dest_txs);

    let cores = core_affinity::get_core_ids().unwrap_or_default();

    let mut handles = Vec::new();

    // Producers
    for producer_id in 0..4u64 {
        let tx = ingress_tx.clone();
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || {
            producer_thread(tx, metrics, running, producer_id);
        }));
    }

    // Routers
    for i in 0..ROUTER_THREADS {
        let rx = ingress_rx.clone();
        let dest_txs = dest_txs.clone();
        let metrics = metrics.clone();
        let running = running.clone();
        let core = cores.get(i).cloned();

        handles.push(thread::spawn(move || {
            router_thread(rx, dest_txs, metrics, running, core);
        }));
    }

    // Consumers
    for (i, rx) in dest_rxs.into_iter().enumerate() {
        let metrics = metrics.clone();
        let running = running.clone();
        let core = cores.get(ROUTER_THREADS + i).cloned();

        handles.push(thread::spawn(move || {
            consumer_thread(rx, metrics, running, core);
        }));
    }

    // Metrics reporter
    {
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || {
            metrics_thread(metrics, running);
        }));
    }

    thread::sleep(Duration::from_secs(15));
    running.store(false, Ordering::Relaxed);

    for h in handles {
        let _ = h.join();
    }

    metrics.report();
}
```

