}

impl LocalMetrics {
    pub fn new() -> Self {
        Self {
            routed: 0,
            consumed: 0,
            dropped: 0,
            ingress_to_route: Histogram::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            route_to_consume: Histogram::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
