use crossbeam_channel::{bounded, Receiver, Sender};
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_ROUTER_THREADS: usize = 8;
const NUM_DESTINATIONS: usize = 4;
const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const DEST_QUEUE_SIZE: usize = 1_000_000;
const METRICS_QUEUE_SIZE: usize = 1_000_000;

#[inline(always)]
fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    route_key: u64,
    created_at_ns: u64,
    payload: Vec<u8>,
}

#[derive(Clone, Debug)]
struct LatencyEvent {
    message_id: u64,
    ingress_to_route_ns: u64,
    route_to_egress_ns: u64,
    end_to_end_ns: u64,
}

struct Metrics {
    total_messages: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            total_messages: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record(&self, latency_ns: u64) {
        self.total_messages.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current_max = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current_max {
            match self.max_latency_ns.compare_exchange_weak(
                current_max,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current_max = v,
            }
        }
    }

    fn snapshot(&self) -> (u64, u64, u64) {
        (
            self.total_messages.load(Ordering::Relaxed),
            self.total_latency_ns.load(Ordering::Relaxed),
            self.max_latency_ns.load(Ordering::Relaxed),
        )
    }
}

fn router_worker(
    worker_id: usize,
    ingress_rx: Receiver<Message>,
    destination_txs: Arc<Vec<Sender<Message>>>,
    metrics_tx: Sender<LatencyEvent>,
) {
    while let Ok(msg) = ingress_rx.recv() {
        let route_start_ns = now_ns();

        let destination_index = (msg.route_key as usize) % destination_txs.len();
        let tx = &destination_txs[destination_index];

        if tx.send(msg.clone()).is_err() {
            eprintln!("Router worker {} failed to send to destination", worker_id);
            continue;
        }

        let egress_ns = now_ns();

        let event = LatencyEvent {
            message_id: msg.id,
            ingress_to_route_ns: route_start_ns.saturating_sub(msg.created_at_ns),
            route_to_egress_ns: egress_ns.saturating_sub(route_start_ns),
            end_to_end_ns: egress_ns.saturating_sub(msg.created_at_ns),
        };

        let _ = metrics_tx.send(event);
    }
}

fn destination_worker(destination_id: usize, rx: Receiver<Message>) {
    let mut processed = 0u64;
    while let Ok(_msg) = rx.recv() {
        processed += 1;
        if processed % 1_000_000 == 0 {
            println!(
                "Destination {} processed {} messages",
                destination_id, processed
            );
        }
    }
}

fn metrics_worker(metrics_rx: Receiver<LatencyEvent>, metrics: Arc<Metrics>) {
    let mut last_report = now_ns();
    let mut interval_count = 0u64;
    let mut interval_latency_sum = 0u64;
    let mut interval_max = 0u64;

    while let Ok(event) = metrics_rx.recv() {
        metrics.record(event.end_to_end_ns);

        interval_count += 1;
        interval_latency_sum += event.end_to_end_ns;
        interval_max = interval_max.max(event.end_to_end_ns);

        let now = now_ns();
        if now - last_report >= 1_000_000_000 {
            let avg = if interval_count > 0 {
                interval_latency_sum / interval_count
            } else {
                0
            };

            let (total_msgs, total_latency, global_max) = metrics.snapshot();
            let global_avg = if total_msgs > 0 {
                total_latency / total_msgs
            } else {
                0
            };

            println!(
                "[METRICS] interval_msgs={} avg_latency_ns={} max_latency_ns={} total_msgs={} global_avg_ns={} global_max_ns={}",
                interval_count, avg, interval_max, total_msgs, global_avg, global_max
            );

            interval_count = 0;
            interval_latency_sum = 0;
            interval_max = 0;
            last_report = now;
        }
    }
}

fn producer(ingress_tx: Sender<Message>, producer_id: usize, num_messages: u64) {
    for i in 0..num_messages {
        let msg = Message {
            id: ((producer_id as u64) << 48) | i,
            route_key: i,
            created_at_ns: now_ns(),
            payload: vec![0u8; 128],
        };

        if ingress_tx.send(msg).is_err() {
            break;
        }
    }
}

fn main() {
    let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);
    let (metrics_tx, metrics_rx) = bounded::<LatencyEvent>(METRICS_QUEUE_SIZE);

    let metrics = Arc::new(Metrics::new());

    let mut destination_txs = Vec::with_capacity(NUM_DESTINATIONS);
    let mut destination_rxs = Vec::with_capacity(NUM_DESTINATIONS);

    for _ in 0..NUM_DESTINATIONS {
        let (tx, rx) = bounded::<Message>(DEST_QUEUE_SIZE);
        destination_txs.push(tx);
        destination_rxs.push(rx);
    }

    let destination_txs = Arc::new(destination_txs);

    for (destination_id, rx) in destination_rxs.into_iter().enumerate() {
        thread::spawn(move || destination_worker(destination_id, rx));
    }

    {
        let metrics = Arc::clone(&metrics);
        thread::spawn(move || metrics_worker(metrics_rx, metrics));
    }

    for worker_id in 0..NUM_ROUTER_THREADS {
        let rx = ingress_rx.clone();
        let txs = Arc::clone(&destination_txs);
        let metrics_tx = metrics_tx.clone();

        thread::spawn(move || router_worker(worker_id, rx, txs, metrics_tx));
    }

    let producer_threads = 4;
    let messages_per_producer = 5_000_000u64;

    let mut handles = Vec::new();
    for producer_id in 0..producer_threads {
        let tx = ingress_tx.clone();
        handles.push(thread::spawn(move || {
            producer(tx, producer_id, messages_per_producer)
        }));
    }

    drop(ingress_tx);

    for h in handles {
        let _ = h.join();
    }

    thread::sleep(Duration::from_secs(10));

    let (total_msgs, total_latency, max_latency) = metrics.snapshot();
    let avg_latency = if total_msgs > 0 {
        total_latency / total_msgs
    } else {
        0
    };

    println!(
        "FINAL METRICS: total_msgs={} avg_latency_ns={} max_latency_ns={}",
        total_msgs, avg_latency, max_latency
    );
}
```

