use anyhow::Result;
use bytes::{Buf, BufMut, BytesMut};
use crossbeam::channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use serde::{Deserialize, Serialize};
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::net::SocketAddr;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc, Mutex,
};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};

const WORKER_QUEUE_SIZE: usize = 1_000_000;
const MAX_FRAME_SIZE: usize = 64 * 1024;
const METRICS_INTERVAL_SECS: u64 = 1;

#[derive(Serialize, Deserialize, Debug, Clone)]
struct Message {
    topic: u64,
    key: u64,
    payload: Vec<u8>,
    ingress_ts_nanos: u64,
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
}

struct LatencyMetrics {
    hist: Mutex<Histogram<u64>>,
}

impl LatencyMetrics {
    fn new() -> Self {
        let hist = Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap();
        Self {
            hist: Mutex::new(hist),
        }
    }

    fn record(&self, value_ns: u64) {
        if let Ok(mut h) = self.hist.lock() {
            let _ = h.record(value_ns);
        }
    }

    fn snapshot_and_reset(&self) -> Option<(u64, u64, u64, u64, u64)> {
        if let Ok(mut h) = self.hist.lock() {
            if h.len() == 0 {
                return Some((0, 0, 0, 0, 0));
            }
            let p50 = h.value_at_quantile(0.50);
            let p95 = h.value_at_quantile(0.95);
            let p99 = h.value_at_quantile(0.99);
            let p999 = h.value_at_quantile(0.999);
            let max = h.max();
            h.reset();
            Some((p50, p95, p99, p999, max))
        } else {
            None
        }
    }
}

type RouteTable = DashMap<u64, Vec<usize>>;

struct Router {
    routes: Arc<RouteTable>,
    worker_senders: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(
        routes: Arc<RouteTable>,
        worker_senders: Vec<Sender<Message>>,
        metrics: Arc<Metrics>,
    ) -> Self {
        Self {
            routes,
            worker_senders,
            metrics,
        }
    }

    fn route(&self, msg: Message) {
        self.metrics.received.fetch_add(1, Ordering::Relaxed);

        if let Some(destinations) = self.routes.get(&msg.topic) {
            for &worker_id in destinations.iter() {
                if let Some(sender) = self.worker_senders.get(worker_id) {
                    if sender.try_send(msg.clone()).is_ok() {
                        self.metrics.routed.fetch_add(1, Ordering::Relaxed);
                    } else {
                        self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
        } else {
            // Fallback shard by key if no explicit route exists
            let shard = shard_for_key(msg.key, self.worker_senders.len());
            if self.worker_senders[shard].try_send(msg).is_ok() {
                self.metrics.routed.fetch_add(1, Ordering::Relaxed);
            } else {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    }
}

fn shard_for_key(key: u64, shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    key.hash(&mut hasher);
    (hasher.finish() as usize) % shards
}

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::ZERO)
        .as_nanos() as u64
}

async fn handle_connection(mut socket: TcpStream, router: Arc<Router>) -> Result<()> {
    let mut read_buf = BytesMut::with_capacity(64 * 1024);

    loop {
        let mut len_buf = [0u8; 4];
        if socket.read_exact(&mut len_buf).await.is_err() {
            break;
        }

        let frame_len = u32::from_be_bytes(len_buf) as usize;
        if frame_len == 0 || frame_len > MAX_FRAME_SIZE {
            break;
        }

        read_buf.resize(frame_len, 0);
        socket.read_exact(&mut read_buf).await?;

        let mut msg: Message = bincode::deserialize(&read_buf)?;
        msg.ingress_ts_nanos = now_nanos();

        router.route(msg);
    }

    Ok(())
}

fn worker_loop(
    worker_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    latency: Arc<LatencyMetrics>,
) {
    let mut batch = Vec::with_capacity(1024);

    loop {
        batch.clear();

        match rx.recv() {
            Ok(msg) => batch.push(msg),
            Err(_) => break,
        }

        while batch.len() < 1024 {
            match rx.try_recv() {
                Ok(msg) => batch.push(msg),
                Err(_) => break,
            }
        }

        for msg in batch.drain(..) {
            // Simulated processing / egress
            let latency_ns = now_nanos().saturating_sub(msg.ingress_ts_nanos);
            latency.record(latency_ns);
            metrics.processed.fetch_add(1, Ordering::Relaxed);

            // Replace this with actual egress logic:
            // - send to another TCP socket
            // - write to Kafka/NATS/custom transport
            // - invoke strategy engine / downstream consumer
            let _ = worker_id;
        }
    }
}

async fn metrics_task(metrics: Arc<Metrics>, latency: Arc<LatencyMetrics>) {
    let mut prev_received = 0;
    let mut prev_routed = 0;
    let mut prev_dropped = 0;
    let mut prev_processed = 0;

    loop {
        tokio::time::sleep(Duration::from_secs(METRICS_INTERVAL_SECS)).await;

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let processed = metrics.processed.load(Ordering::Relaxed);

        let rps_in = received - prev_received;
        let rps_routed = routed - prev_routed;
        let rps_dropped = dropped - prev_dropped;
        let rps_processed = processed - prev_processed;

        prev_received = received;
        prev_routed = routed;
        prev_dropped = dropped;
        prev_processed = processed;

        if let Some((p50, p95, p99, p999, max)) = latency.snapshot_and_reset() {
            println!(
                "[metrics] in/s={} routed/s={} dropped/s={} processed/s={} latency_ns p50={} p95={} p99={} p999={} max={}",
                rps_in, rps_routed, rps_dropped, rps_processed, p50, p95, p99, p999, max
            );
        }
    }
}

async fn start_server(addr: SocketAddr, router: Arc<Router>) -> Result<()> {
    let listener = TcpListener::bind(addr).await?;
    println!("listening on {}", addr);

    loop {
        let (socket, peer) = listener.accept().await?;
        let router_clone = router.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_connection(socket, router_clone).await {
                eprintln!("connection {} error: {:?}", peer, e);
            }
        });
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    let metrics = Arc::new(Metrics::default());
    let latency = Arc::new(LatencyMetrics::new());
    let routes = Arc::new(RouteTable::new());

    let worker_count = num_cpus::get().max(4);
    let mut worker_senders = Vec::with_capacity(worker_count);

    for worker_id in 0..worker_count {
        let (tx, rx) = bounded::<Message>(WORKER_QUEUE_SIZE);
        worker_senders.push(tx);

        let metrics_clone = metrics.clone();
        let latency_clone = latency.clone();

        std::thread::Builder::new()
            .name(format!("worker-{}", worker_id))
            .spawn(move || worker_loop(worker_id, rx, metrics_clone, latency_clone))
            .expect("failed to spawn worker");
    }

    // Example static routes:
    // topic 100 -> workers 0,1
    // topic 200 -> worker 2
    routes.insert(100, vec![0, 1]);
    routes.insert(200, vec![2]);

    let router = Arc::new(Router::new(
        routes.clone(),
        worker_senders,
        metrics.clone(),
    ));

    tokio::spawn(metrics_task(metrics.clone(), latency.clone()));

    let addr: SocketAddr = "0.0.0.0:9000".parse()?;
    start_server(addr, router).await
}
```

