```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const PAYLOAD_SIZE: usize = 128;
const NUM_TOPICS: usize = 1024;
const CHANNEL_CAPACITY: usize = 1_000_000;
const PRODUCER_THREADS: usize = 4;
const CONSUMER_THREADS_PER_ROUTE: usize = 1;

#[derive(Clone)]
struct Message {
    topic: u64,
    created_at: Instant,
    payload: [u8; PAYLOAD_SIZE],
}

struct Metrics {
    routed_count: AtomicU64,
    dropped_count: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
    histogram: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed_count: AtomicU64::new(0),
            dropped_count: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
            histogram: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.routed_count.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current_max = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current_max {
            match self.max_latency_ns.compare_exchange_weak(
                current_max,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current_max = v,
            }
        }

        if let Ok(mut hist) = self.histogram.lock() {
            let _ = hist.record(latency_ns);
        }
    }

    fn record_drop(&self) {
        self.dropped_count.fetch_add(1, Ordering::Relaxed);
    }
}

fn hash_topic(topic: u64, num_routes: usize) -> usize {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % num_routes
}

fn start_router(
    ingress_rx: Receiver<Message>,
    route_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) {
            match ingress_rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    let route = hash_topic(msg.topic, route_txs.len());
                    if route_txs[route].try_send(msg).is_err() {
                        metrics.record_drop();
                    }
                }
                Err(_) => continue,
            }
        }
    })
}

fn start_consumer(
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) {
            match rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    let latency = msg.created_at.elapsed().as_nanos() as u64;
                    metrics.record_latency(latency);

                    // Simulate lightweight processing
                    std::hint::black_box(msg.payload);
                }
                Err(_) => continue,
            }
        }
    })
}

fn start_producer(
    tx: Sender<Message>,
    running: Arc<AtomicBool>,
    producer_id: usize,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut counter = producer_id as u64;
        while running.load(Ordering::Relaxed) {
            let msg = Message {
                topic: counter % NUM_TOPICS as u64,
                created_at: Instant::now(),
                payload: [42u8; PAYLOAD_SIZE],
            };

            let _ = tx.try_send(msg);
            counter = counter.wrapping_add(PRODUCER_THREADS as u64);
        }
    })
}

fn start_metrics_reporter(
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_count = 0u64;
        let mut last_dropped = 0u64;

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let count = metrics.routed_count.load(Ordering::Relaxed);
            let dropped = metrics.dropped_count.load(Ordering::Relaxed);
            let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
            let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

            let delta = count - last_count;
            let delta_dropped = dropped - last_dropped;

            last_count = count;
            last_dropped = dropped;

            let avg_latency = if count > 0 {
                total_latency / count
            } else {
                0
            };

            let (p50, p95, p99) = if let Ok(hist) = metrics.histogram.lock() {
                (
                    hist.value_at_quantile(0.50),
                    hist.value_at_quantile(0.95),
                    hist.value_at_quantile(0.99),
                )
            } else {
                (0, 0, 0)
            };

            println!(
                "throughput={} msg/s dropped={} avg={}ns p50={}ns p95={}ns p99={}ns max={}ns total={}",
                delta, delta_dropped, avg_latency, p50, p95, p99, max_latency, count
            );
        }
    })
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());

    let num_routes = num_cpus::get().max(2);

    let (ingress_tx, ingress_rx) = bounded::<Message>(CHANNEL_CAPACITY);

    let mut route_txs = Vec::with_capacity(num_routes);
    let mut consumer_handles = Vec::new();

    for _ in 0..num_routes {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY / num_routes.max(1));
        route_txs.push(tx);

        for _ in 0..CONSUMER_THREADS_PER_ROUTE {
            consumer_handles.push(start_consumer(
                rx.clone(),
                metrics.clone(),
                running.clone(),
            ));
        }
    }

    let router_handle = start_router(
        ingress_rx,
        route_txs,
        metrics.clone(),
        running.clone(),
    );

    let mut producer_handles = Vec::new();
    for i in 0..PRODUCER_THREADS {
        producer_handles.push(start_producer(
            ingress_tx.clone(),
            running.clone(),
            i,
        ));
    }

    let metrics_handle = start_metrics_reporter(metrics.clone(), running.clone());

    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for h in producer_handles {
        let _ = h.join();
    }
    let _ = router_handle.join();
    for h in consumer_handles {
        let _ = h.join();
    }
    let _ = metrics_handle.join();
}
```

