```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone, Debug)]
struct Message {
    topic: u64,
    payload: Vec<u8>,
    created_ns: u64,
}

impl Message {
    #[inline]
    fn new(topic: u64, payload: Vec<u8>) -> Self {
        Self {
            topic,
            payload,
            created_ns: now_ns(),
        }
    }
}

#[derive(Default)]
struct Metrics {
    total_received: AtomicU64,
    total_routed: AtomicU64,
    total_dropped: AtomicU64,
    latency_sum_ns: AtomicU64,
    latency_count: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    #[inline]
    fn record_received(&self) {
        self.total_received.fetch_add(1, Ordering::Relaxed);
    }

    #[inline]
    fn record_routed(&self, latency_ns: u64) {
        self.total_routed.fetch_add(1, Ordering::Relaxed);
        self.latency_sum_ns.fetch_add(latency_ns, Ordering::Relaxed);
        self.latency_count.fetch_add(1, Ordering::Relaxed);
        update_max(&self.max_latency_ns, latency_ns);
    }

    #[inline]
    fn record_dropped(&self) {
        self.total_dropped.fetch_add(1, Ordering::Relaxed);
    }
}

fn update_max(atom: &AtomicU64, value: u64) {
    let mut prev = atom.load(Ordering::Relaxed);
    while value > prev {
        match atom.compare_exchange_weak(prev, value, Ordering::Relaxed, Ordering::Relaxed) {
            Ok(_) => break,
            Err(next) => prev = next,
        }
    }
}

type Subscriber = Sender<Message>;

struct Router {
    routes: DashMap<u64, Vec<Subscriber>>,
    ingress_tx: Sender<Message>,
    ingress_rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
}

impl Router {
    fn new(queue_size: usize, metrics: Arc<Metrics>) -> Self {
        let (tx, rx) = bounded(queue_size);
        Self {
            routes: DashMap::new(),
            ingress_tx: tx,
            ingress_rx: rx,
            metrics,
            running: Arc::new(AtomicBool::new(true)),
        }
    }

    fn publisher(&self) -> Sender<Message> {
        self.ingress_tx.clone()
    }

    fn subscribe(&self, topic: u64, subscriber: Subscriber) {
        self.routes
            .entry(topic)
            .and_modify(|subs| subs.push(subscriber.clone()))
            .or_insert_with(|| vec![subscriber]);
    }

    fn start_workers(&self, worker_count: usize) -> Vec<thread::JoinHandle<()>> {
        let mut handles = Vec::with_capacity(worker_count);

        for _ in 0..worker_count {
            let rx = self.ingress_rx.clone();
            let routes = self.routes.clone();
            let metrics = self.metrics.clone();
            let running = self.running.clone();

            let handle = thread::spawn(move || {
                while running.load(Ordering::Relaxed) {
                    match rx.recv_timeout(Duration::from_millis(10)) {
                        Ok(msg) => {
                            metrics.record_received();

                            if let Some(subs) = routes.get(&msg.topic) {
                                let latency_ns = now_ns().saturating_sub(msg.created_ns);

                                for sub in subs.iter() {
                                    if sub.try_send(msg.clone()).is_err() {
                                        metrics.record_dropped();
                                    }
                                }

                                metrics.record_routed(latency_ns);
                            } else {
                                metrics.record_dropped();
                            }
                        }
                        Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
                        Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
                    }
                }
            });

            handles.push(handle);
        }

        handles
    }

    fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn start_metrics_reporter(metrics: Arc<Metrics>, running: Arc<AtomicBool>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_received = 0;
        let mut last_routed = 0;
        let mut last_dropped = 0;

        let mut hist = Histogram::<u64>::new(3).unwrap();

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let received = metrics.total_received.load(Ordering::Relaxed);
            let routed = metrics.total_routed.load(Ordering::Relaxed);
            let dropped = metrics.total_dropped.load(Ordering::Relaxed);
            let latency_sum = metrics.latency_sum_ns.load(Ordering::Relaxed);
            let latency_count = metrics.latency_count.load(Ordering::Relaxed);
            let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

            let delta_received = received - last_received;
            let delta_routed = routed - last_routed;
            let delta_dropped = dropped - last_dropped;

            last_received = received;
            last_routed = routed;
            last_dropped = dropped;

            let avg_latency = if latency_count > 0 {
                latency_sum / latency_count
            } else {
                0
            };

            hist.reset();
            if max_latency > 0 {
                let _ = hist.record(max_latency);
            }

            println!(
                "recv/s={} routed/s={} dropped/s={} total_recv={} total_routed={} avg_latency_ns={} max_latency_ns={} p99_est_ns={}",
                delta_received,
                delta_routed,
                delta_dropped,
                received,
                routed,
                avg_latency,
                max_latency,
                hist.value_at_quantile(0.99)
            );
        }
    })
}

fn start_subscriber(name: &'static str, queue: usize) -> Sender<Message> {
    let (tx, rx) = bounded::<Message>(queue);

    thread::spawn(move || {
        while let Ok(msg) = rx.recv() {
            let _ = black_box_process(&msg);
            if msg.payload.is_empty() {
                eprintln!("{} got empty payload", name);
            }
        }
    });

    tx
}

#[inline(never)]
fn black_box_process(msg: &Message) -> usize {
    msg.payload.iter().fold(0usize, |acc, b| acc.wrapping_add(*b as usize))
}

fn start_publishers(
    publisher_count: usize,
    tx: Sender<Message>,
    topics: Vec<u64>,
    running: Arc<AtomicBool>,
) -> Vec<thread::JoinHandle<()>> {
    let mut handles = Vec::with_capacity(publisher_count);

    for _ in 0..publisher_count {
        let tx = tx.clone();
        let topics = topics.clone();
        let running = running.clone();

        let handle = thread::spawn(move || {
            let mut rng = rand::thread_rng();

            while running.load(Ordering::Relaxed) {
                let topic = topics[rng.gen_range(0..topics.len())];
                let payload = vec![42u8; 128];
                let msg = Message::new(topic, payload);

                if tx.try_send(msg).is_err() {
                    // ingress queue full, drop
                }
            }
        });

        handles.push(handle);
    }

    handles
}

fn main() {
    let metrics = Arc::new(Metrics::default());
    let router = Router::new(1_000_000, metrics.clone());

    let worker_count = num_cpus::get().max(2);
    let workers = router.start_workers(worker_count);

    let sub_a = start_subscriber("sub-A", 100_000);
    let sub_b = start_subscriber("sub-B", 100_000);
    let sub_c = start_subscriber("sub-C", 100_000);

    router.subscribe(1, sub_a.clone());
    router.subscribe(1, sub_b.clone());
    router.subscribe(2, sub_c.clone());
    router.subscribe(3, sub_a.clone());

    let reporter = start_metrics_reporter(metrics.clone(), router.running.clone());

    let publishers = start_publishers(
        worker_count,
        router.publisher(),
        vec![1, 2, 3],
        router.running.clone(),
    );

    thread::sleep(Duration::from_secs(10));

    router.stop();

    for h in publishers {
        let _ = h.join();
    }

    for h in workers {
        let _ = h.join();
    }

    let _ = reporter.join();
}
```

