use bytes::Bytes;
use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone)]
struct Message {
    id: u64,
    topic: String,
    payload: Bytes,
    created_at_ns: u64,
}

struct Metrics {
    ingress_count: AtomicU64,
    routed_count: AtomicU64,
    processed_count: AtomicU64,
    dropped_count: AtomicU64,
    total_route_latency_ns: AtomicU64,
    total_end_to_end_latency_ns: AtomicU64,
    route_hist: Mutex<Histogram<u64>>,
    e2e_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            ingress_count: AtomicU64::new(0),
            routed_count: AtomicU64::new(0),
            processed_count: AtomicU64::new(0),
            dropped_count: AtomicU64::new(0),
            total_route_latency_ns: AtomicU64::new(0),
            total_end_to_end_latency_ns: AtomicU64::new(0),
            route_hist: Mutex::new(Histogram::new(3).unwrap()),
            e2e_hist: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record_route_latency(&self, ns: u64) {
        self.total_route_latency_ns.fetch_add(ns, Ordering::Relaxed);
        let _ = self.route_hist.lock().record(ns);
    }

    fn record_e2e_latency(&self, ns: u64) {
        self.total_end_to_end_latency_ns.fetch_add(ns, Ordering::Relaxed);
        let _ = self.e2e_hist.lock().record(ns);
    }
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn topic_shard(topic: &str, num_shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % num_shards
}

fn start_router(
    ingress_rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) {
            match ingress_rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    let route_start = now_ns();
                    let shard = topic_shard(&msg.topic, worker_txs.len());

                    match worker_txs[shard].try_send(msg) {
                        Ok(_) => {
                            metrics.routed_count.fetch_add(1, Ordering::Relaxed);
                            let route_latency = now_ns() - route_start;
                            metrics.record_route_latency(route_latency);
                        }
                        Err(_) => {
                            metrics.dropped_count.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                }
                Err(crossbeam::channel::RecvTimeoutError::Timeout) => continue,
                Err(crossbeam::channel::RecvTimeoutError::Disconnected) => break,
            }
        }
    })
}

fn start_worker(
    worker_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) {
            match rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    // Simulated processing
                    let _ = worker_id;
                    let _payload_len = msg.payload.len();

                    metrics.processed_count.fetch_add(1, Ordering::Relaxed);

                    let e2e = now_ns() - msg.created_at_ns;
                    metrics.record_e2e_latency(e2e);
                }
                Err(crossbeam::channel::RecvTimeoutError::Timeout) => continue,
                Err(crossbeam::channel::RecvTimeoutError::Disconnected) => break,
            }
        }
    })
}

fn start_metrics_reporter(
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_ingress = 0;
        let mut last_processed = 0;
        let mut last_routed = 0;
        let mut last_dropped = 0;

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let ingress = metrics.ingress_count.load(Ordering::Relaxed);
            let routed = metrics.routed_count.load(Ordering::Relaxed);
            let processed = metrics.processed_count.load(Ordering::Relaxed);
            let dropped = metrics.dropped_count.load(Ordering::Relaxed);

            let ingress_rate = ingress - last_ingress;
            let routed_rate = routed - last_routed;
            let processed_rate = processed - last_processed;
            let dropped_rate = dropped - last_dropped;

            last_ingress = ingress;
            last_routed = routed;
            last_processed = processed;
            last_dropped = dropped;

            let route_hist = metrics.route_hist.lock();
            let e2e_hist = metrics.e2e_hist.lock();

            println!("--- metrics ---");
            println!("ingress/s   : {}", ingress_rate);
            println!("routed/s    : {}", routed_rate);
            println!("processed/s : {}", processed_rate);
            println!("dropped/s   : {}", dropped_rate);

            if route_hist.len() > 0 {
                println!(
                    "route latency (ns): p50={} p95={} p99={} max={}",
                    route_hist.value_at_quantile(0.50),
                    route_hist.value_at_quantile(0.95),
                    route_hist.value_at_quantile(0.99),
                    route_hist.max()
                );
            }

            if e2e_hist.len() > 0 {
                println!(
                    "e2e latency (ns):   p50={} p95={} p99={} max={}",
                    e2e_hist.value_at_quantile(0.50),
                    e2e_hist.value_at_quantile(0.95),
                    e2e_hist.value_at_quantile(0.99),
                    e2e_hist.max()
                );
            }
        }
    })
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());

    let ingress_queue_size = 1_000_000;
    let worker_queue_size = 100_000;
    let num_workers = num_cpus::get().max(2);

    let (ingress_tx, ingress_rx) = bounded::<Message>(ingress_queue_size);

    let mut worker_txs = Vec::with_capacity(num_workers);
    let mut worker_handles = Vec::with_capacity(num_workers);

    for worker_id in 0..num_workers {
        let (tx, rx) = bounded::<Message>(worker_queue_size);
        worker_txs.push(tx);

        let handle = start_worker(worker_id, rx, metrics.clone(), running.clone());
        worker_handles.push(handle);
    }

    let router_handle = start_router(
        ingress_rx,
        worker_txs,
        metrics.clone(),
        running.clone(),
    );

    let metrics_handle = start_metrics_reporter(metrics.clone(), running.clone());

    // Simulated producers
    let producer_count = num_cpus::get();
    let mut producer_handles = Vec::with_capacity(producer_count);

    for producer_id in 0..producer_count {
        let tx = ingress_tx.clone();
        let metrics = metrics.clone();
        let running = running.clone();

        let handle = thread::spawn(move || {
            let mut rng = rand::thread_rng();
            let topics = [
                "orders",
                "trades",
                "quotes",
                "risk",
                "positions",
                "market_data",
            ];

            let mut local_id = producer_id as u64 * 1_000_000_000;

            while running.load(Ordering::Relaxed) {
                let topic = topics[rng.gen_range(0..topics.len())].to_string();
                let payload = Bytes::from_static(b"abcdefghijklmnopqrstuvwxyz012345");

                let msg = Message {
                    id: local_id,
                    topic,
                    payload,
                    created_at_ns: now_ns(),
                };

                local_id += 1;
                metrics.ingress_count.fetch_add(1, Ordering::Relaxed);

                if tx.try_send(msg).is_err() {
                    metrics.dropped_count.fetch_add(1, Ordering::Relaxed);
                }
            }
        });

        producer_handles.push(handle);
    }

    // Run benchmark interval
    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    drop(ingress_tx);

    for handle in producer_handles {
        let _ = handle.join();
    }

    let _ = router_handle.join();

    for handle in worker_handles {
        let _ = handle.join();
    }

    let _ = metrics_handle.join();

    println!("Shutdown complete.");
}
