use crossbeam_channel::{bounded, unbounded, Receiver, Sender};
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_PRODUCERS: usize = 4;
const NUM_WORKERS: usize = 8;
const MESSAGES_PER_PRODUCER: usize = 2_000_000;
const ROUTER_QUEUE_SIZE: usize = 262_144;
const WORKER_QUEUE_SIZE: usize = 262_144;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    route_key: u32,
    payload: [u8; 64],
    created_at: Instant,
}

#[derive(Debug)]
struct LatencyEvent {
    route_key: u32,
    total_latency_ns: u64,
    routing_latency_ns: u64,
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    processed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    routing_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn record_received(&self) {
        self.received.fetch_add(1, Ordering::Relaxed);
    }

    fn record_routed(&self) {
        self.routed.fetch_add(1, Ordering::Relaxed);
    }

    fn record_processed(&self, total_latency_ns: u64, routing_latency_ns: u64) {
        self.processed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns
            .fetch_add(total_latency_ns, Ordering::Relaxed);
        self.routing_latency_ns
            .fetch_add(routing_latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while total_latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                total_latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn record_dropped(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

fn route_to_worker(route_key: u32, num_workers: usize) -> usize {
    (route_key as usize) % num_workers
}

fn producer_thread(
    producer_id: usize,
    tx: Sender<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let start_id = (producer_id as u64) << 48;

        for i in 0..MESSAGES_PER_PRODUCER {
            if !running.load(Ordering::Relaxed) {
                break;
            }

            let msg = Message {
                id: start_id | i as u64,
                route_key: (i % 1024) as u32,
                payload: [producer_id as u8; 64],
                created_at: Instant::now(),
            };

            metrics.record_received();

            if tx.try_send(msg).is_err() {
                metrics.record_dropped();
            }
        }
    })
}

fn router_thread(
    rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) || !rx.is_empty() {
            match rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    let idx = route_to_worker(msg.route_key, worker_txs.len());
                    if worker_txs[idx].try_send(msg).is_ok() {
                        metrics.record_routed();
                    } else {
                        metrics.record_dropped();
                    }
                }
                Err(_) => {}
            }
        }
    })
}

fn worker_thread(
    worker_id: usize,
    rx: Receiver<Message>,
    latency_tx: Sender<LatencyEvent>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) || !rx.is_empty() {
            match rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    let now = Instant::now();
                    let total_latency_ns = now.duration_since(msg.created_at).as_nanos() as u64;

                    // Approximation: routing latency is measured as time until worker receives it.
                    let routing_latency_ns = total_latency_ns;

                    // Simulate very lightweight processing
                    std::hint::black_box(msg.id);
                    std::hint::black_box(msg.route_key);
                    std::hint::black_box(msg.payload[0]);
                    std::hint::black_box(worker_id);

                    let evt = LatencyEvent {
                        route_key: msg.route_key,
                        total_latency_ns,
                        routing_latency_ns,
                    };

                    let _ = latency_tx.try_send(evt);
                }
                Err(_) => {}
            }
        }
    })
}

fn metrics_thread(
    latency_rx: Receiver<LatencyEvent>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut per_route_counts: HashMap<u32, u64> = HashMap::new();
        let mut last_report = Instant::now();
        let mut last_processed = 0u64;

        while running.load(Ordering::Relaxed) || !latency_rx.is_empty() {
            match latency_rx.recv_timeout(Duration::from_millis(100)) {
                Ok(evt) => {
                    *per_route_counts.entry(evt.route_key).or_insert(0) += 1;
                    metrics.record_processed(evt.total_latency_ns, evt.routing_latency_ns);
                }
                Err(_) => {}
            }

            if last_report.elapsed() >= Duration::from_secs(1) {
                let processed = metrics.processed.load(Ordering::Relaxed);
                let received = metrics.received.load(Ordering::Relaxed);
                let routed = metrics.routed.load(Ordering::Relaxed);
                let dropped = metrics.dropped.load(Ordering::Relaxed);
                let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
                let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

                let delta = processed - last_processed;
                last_processed = processed;

                let avg_latency_ns = if processed > 0 {
                    total_latency / processed
                } else {
                    0
                };

                println!(
                    "recv={} routed={} processed={} dropped={} throughput={} msg/s avg_latency={} ns max_latency={} ns active_routes={}",
                    received,
                    routed,
                    processed,
                    dropped,
                    delta,
                    avg_latency_ns,
                    max_latency,
                    per_route_counts.len()
                );

                last_report = Instant::now();
            }
        }
    })
}

fn main() {
    let metrics = Arc::new(Metrics::default());
    let running = Arc::new(AtomicBool::new(true));

    let (ingress_tx, ingress_rx) = bounded::<Message>(ROUTER_QUEUE_SIZE);

    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_rxs = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(WORKER_QUEUE_SIZE);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    let (latency_tx, latency_rx) = unbounded::<LatencyEvent>();

    let metrics_handle = metrics_thread(latency_rx, metrics.clone(), running.clone());

    let mut worker_handles = Vec::with_capacity(NUM_WORKERS);
    for (i, rx) in worker_rxs.into_iter().enumerate() {
        worker_handles.push(worker_thread(
            i,
            rx,
            latency_tx.clone(),
            running.clone(),
        ));
    }

    let router_handle = router_thread(ingress_rx, worker_txs, metrics.clone(), running.clone());

    let mut producer_handles = Vec::with_capacity(NUM_PRODUCERS);
    for i in 0..NUM_PRODUCERS {
        producer_handles.push(producer_thread(
            i,
            ingress_tx.clone(),
            metrics.clone(),
            running.clone(),
        ));
    }

    for h in producer_handles {
        h.join().unwrap();
    }

    // Give the router/workers a moment to drain
    thread::sleep(Duration::from_secs(2));
    running.store(false, Ordering::Relaxed);

    router_handle.join().unwrap();
    for h in worker_handles {
        h.join().unwrap();
    }
    metrics_handle.join().unwrap();

    let received = metrics.received.load(Ordering::Relaxed);
    let routed = metrics.routed.load(Ordering::Relaxed);
    let processed = metrics.processed.load(Ordering::Relaxed);
    let dropped = metrics.dropped.load(Ordering::Relaxed);
    let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
    let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

    let avg_latency_ns = if processed > 0 {
        total_latency / processed
    } else {
        0
    };

    println!("\n=== FINAL METRICS ===");
    println!("received   : {}", received);
    println!("routed     : {}", routed);
    println!("processed  : {}", processed);
    println!("dropped    : {}", dropped);
    println!("avg latency: {} ns", avg_latency_ns);
    println!("max latency: {} ns", max_latency);
}
```

