## `src/main.rs`

```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 8;
const QUEUE_CAPACITY: usize = 1_000_000;
const REPORT_INTERVAL_SECS: u64 = 1;

#[derive(Clone, Debug)]
struct Message {
    key: u64,
    payload: [u8; 64],
    created_at: Instant,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
    // Histogram protected by mutex for simplicity.
    // For extreme performance, use per-thread histograms and merge periodically.
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            processed: AtomicU64::new(0),
            latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000, 3)
                    .expect("failed to create histogram"),
            ),
        }
    }

    fn record_latency_micros(&self, us: u64) {
        if let Ok(mut hist) = self.latency_hist.lock() {
            let _ = hist.record(us);
        }
    }
}

fn shard_for_key(key: u64, num_shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    key.hash(&mut hasher);
    (hasher.finish() as usize) % num_shards
}

fn worker_loop(shard_id: usize, rx: Receiver<Message>, metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                // Simulate processing
                let latency = msg.created_at.elapsed();
                metrics.processed.fetch_add(1, Ordering::Relaxed);
                metrics.record_latency_micros(latency.as_micros() as u64);

                // In real systems:
                // - forward to downstream
                // - dispatch to handler
                // - write to socket/shared memory
                let _ = shard_id;
            }
            Err(_) => {}
        }
    }
}

fn router_loop(
    ingress_rx: Receiver<Message>,
    shard_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !ingress_rx.is_empty() {
        match ingress_rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                metrics.received.fetch_add(1, Ordering::Relaxed);

                let shard = shard_for_key(msg.key, shard_txs.len());

                match shard_txs[shard].try_send(msg) {
                    Ok(_) => {
                        metrics.routed.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(_) => {
                        metrics.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Err(_) => {}
        }
    }
}

fn metrics_reporter(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    let mut last_received = 0;
    let mut last_routed = 0;
    let mut last_processed = 0;
    let mut last_dropped = 0;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(REPORT_INTERVAL_SECS));

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let processed = metrics.processed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);

        let rps_in = received - last_received;
        let rps_routed = routed - last_routed;
        let rps_processed = processed - last_processed;
        let rps_dropped = dropped - last_dropped;

        last_received = received;
        last_routed = routed;
        last_processed = processed;
        last_dropped = dropped;

        let (p50, p95, p99, max) = {
            let hist = metrics.latency_hist.lock().unwrap();
            (
                hist.value_at_quantile(0.50),
                hist.value_at_quantile(0.95),
                hist.value_at_quantile(0.99),
                hist.max(),
            )
        };

        println!(
            "in/s={} routed/s={} processed/s={} dropped/s={} latency_us p50={} p95={} p99={} max={}",
            rps_in, rps_routed, rps_processed, rps_dropped, p50, p95, p99, max
        );
    }
}

fn pin_thread_to_core(core_id: usize) {
    if let Some(core_ids) = core_affinity::get_core_ids() {
        if core_id < core_ids.len() {
            core_affinity::set_for_current(core_ids[core_id]);
        }
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());

    let (ingress_tx, ingress_rx) = bounded::<Message>(QUEUE_CAPACITY);

    let mut shard_txs = Vec::with_capacity(NUM_SHARDS);
    let mut worker_handles = Vec::with_capacity(NUM_SHARDS);

    for shard_id in 0..NUM_SHARDS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        shard_txs.push(tx);

        let metrics_clone = Arc::clone(&metrics);
        let running_clone = Arc::clone(&running);

        let handle = thread::spawn(move || {
            pin_thread_to_core(shard_id + 1);
            worker_loop(shard_id, rx, metrics_clone, running_clone);
        });

        worker_handles.push(handle);
    }

    let router_metrics = Arc::clone(&metrics);
    let router_running = Arc::clone(&running);
    let router_shards = shard_txs.clone();

    let router_handle = thread::spawn(move || {
        pin_thread_to_core(0);
        router_loop(ingress_rx, router_shards, router_metrics, router_running);
    });

    let reporter_metrics = Arc::clone(&metrics);
    let reporter_running = Arc::clone(&running);
    let reporter_handle = thread::spawn(move || {
        metrics_reporter(reporter_metrics, reporter_running);
    });

    // Simulated producers
    let mut producer_handles = Vec::new();
    let num_producers = 4;

    for producer_id in 0..num_producers {
        let tx = ingress_tx.clone();
        let running_clone = Arc::clone(&running);

        let handle = thread::spawn(move || {
            pin_thread_to_core(NUM_SHARDS + 2 + producer_id);

            let mut key: u64 = producer_id as u64;
            while running_clone.load(Ordering::Relaxed) {
                let msg = Message {
                    key,
                    payload: [0u8; 64],
                    created_at: Instant::now(),
                };

                // Backpressure-aware send
                if tx.try_send(msg).is_err() {
                    // In production:
                    // - count drops
                    // - apply backpressure
                    // - batch/retry
                }

                key = key.wrapping_add(1);
            }
        });

        producer_handles.push(handle);
    }

    // Run benchmark for 10 seconds
    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for handle in producer_handles {
        let _ = handle.join();
    }

    let _ = router_handle.join();

    for handle in worker_handles {
        let _ = handle.join();
    }

    let _ = reporter_handle.join();

    println!("Final totals:");
    println!(
        "received={} routed={} processed={} dropped={}",
        metrics.received.load(Ordering::Relaxed),
        metrics.routed.load(Ordering::Relaxed),
        metrics.processed.load(Ordering::Relaxed),
        metrics.dropped.load(Ordering::Relaxed),
    );
}
```

