```rust
use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use rand::Rng;
use serde::{Deserialize, Serialize};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const WORKER_QUEUE_SIZE: usize = 250_000;
const NUM_WORKERS: usize = 8;
const NUM_PRODUCERS: usize = 4;
const RUN_SECONDS: u64 = 10;

#[derive(Clone, Debug, Serialize, Deserialize)]
struct Message {
    id: u64,
    route_key: u64,
    payload: [u8; 64],
    created_at: Instant,
}

#[derive(Default)]
struct Metrics {
    ingress_received: AtomicU64,
    ingress_dropped: AtomicU64,
    routed: AtomicU64,
    worker_processed: AtomicU64,
    worker_dropped: AtomicU64,
    route_counts: DashMap<u64, u64>,
    end_to_end_ns_sum: AtomicU64,
    queue_delay_ns_sum: AtomicU64,
    latency_histogram: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            ingress_received: AtomicU64::new(0),
            ingress_dropped: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            worker_processed: AtomicU64::new(0),
            worker_dropped: AtomicU64::new(0),
            route_counts: DashMap::new(),
            end_to_end_ns_sum: AtomicU64::new(0),
            queue_delay_ns_sum: AtomicU64::new(0),
            latency_histogram: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap()
            ),
        }
    }

    fn record_route(&self, route: u64) {
        self.route_counts
            .entry(route)
            .and_modify(|v| *v += 1)
            .or_insert(1);
    }

    fn record_latency(&self, queue_delay_ns: u64, end_to_end_ns: u64) {
        self.queue_delay_ns_sum
            .fetch_add(queue_delay_ns, Ordering::Relaxed);
        self.end_to_end_ns_sum
            .fetch_add(end_to_end_ns, Ordering::Relaxed);
        if let Ok(mut hist) = self.latency_histogram.lock() {
            let _ = hist.record(end_to_end_ns);
        }
    }
}

fn pin_thread_to_core(core_id: usize) {
    if let Some(core_ids) = core_affinity::get_core_ids() {
        if core_id < core_ids.len() {
            core_affinity::set_for_current(core_ids[core_id]);
        }
    }
}

fn producer_thread(
    producer_id: usize,
    tx: Sender<Message>,
    running: Arc<AtomicBool>,
    metrics: Arc<Metrics>,
) {
    pin_thread_to_core(producer_id);
    let mut rng = rand::thread_rng();
    let mut msg_id = producer_id as u64 * 1_000_000_000;

    while running.load(Ordering::Relaxed) {
        let msg = Message {
            id: msg_id,
            route_key: rng.gen_range(0..NUM_WORKERS as u64),
            payload: [producer_id as u8; 64],
            created_at: Instant::now(),
        };
        msg_id += 1;

        metrics.ingress_received.fetch_add(1, Ordering::Relaxed);

        match tx.try_send(msg) {
            Ok(_) => {}
            Err(TrySendError::Full(_)) => {
                metrics.ingress_dropped.fetch_add(1, Ordering::Relaxed);
            }
            Err(TrySendError::Disconnected(_)) => break,
        }
    }
}

fn router_thread(
    rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    running: Arc<AtomicBool>,
    metrics: Arc<Metrics>,
) {
    pin_thread_to_core(NUM_PRODUCERS);

    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_micros(50)) {
            Ok(msg) => {
                let route = (msg.route_key as usize) % worker_txs.len();
                metrics.record_route(route as u64);

                match worker_txs[route].try_send(msg) {
                    Ok(_) => {
                        metrics.routed.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(TrySendError::Full(_)) => {
                        metrics.worker_dropped.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(TrySendError::Disconnected(_)) => {}
                }
            }
            Err(_) => {}
        }
    }
}

fn worker_thread(
    worker_id: usize,
    rx: Receiver<Message>,
    running: Arc<AtomicBool>,
    metrics: Arc<Metrics>,
) {
    pin_thread_to_core(NUM_PRODUCERS + 1 + worker_id);

    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_micros(50)) {
            Ok(msg) => {
                let now = Instant::now();
                let total_latency = now.duration_since(msg.created_at).as_nanos() as u64;

                // Simplified queue delay approximation:
                let queue_delay = total_latency;

                metrics.worker_processed.fetch_add(1, Ordering::Relaxed);
                metrics.record_latency(queue_delay, total_latency);

                // Simulate tiny processing cost if desired:
                // std::hint::spin_loop();
            }
            Err(_) => {}
        }
    }
}

fn metrics_thread(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let ingress_received = metrics.ingress_received.load(Ordering::Relaxed);
        let ingress_dropped = metrics.ingress_dropped.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let worker_processed = metrics.worker_processed.load(Ordering::Relaxed);
        let worker_dropped = metrics.worker_dropped.load(Ordering::Relaxed);

        let avg_e2e = if worker_processed > 0 {
            metrics.end_to_end_ns_sum.load(Ordering::Relaxed) / worker_processed
        } else {
            0
        };

        let avg_queue = if worker_processed > 0 {
            metrics.queue_delay_ns_sum.load(Ordering::Relaxed) / worker_processed
        } else {
            0
        };

        let (p50, p95, p99, p999) = if let Ok(hist) = metrics.latency_histogram.lock() {
            (
                hist.value_at_quantile(0.50),
                hist.value_at_quantile(0.95),
                hist.value_at_quantile(0.99),
                hist.value_at_quantile(0.999),
            )
        } else {
            (0, 0, 0, 0)
        };

        println!("=== METRICS ===");
        println!("Ingress received : {}", ingress_received);
        println!("Ingress dropped  : {}", ingress_dropped);
        println!("Routed           : {}", routed);
        println!("Worker processed : {}", worker_processed);
        println!("Worker dropped   : {}", worker_dropped);
        println!("Avg queue ns     : {}", avg_queue);
        println!("Avg e2e ns       : {}", avg_e2e);
        println!("p50 latency ns   : {}", p50);
        println!("p95 latency ns   : {}", p95);
        println!("p99 latency ns   : {}", p99);
        println!("p99.9 latency ns : {}", p999);
        println!("Routes tracked   : {}", metrics.route_counts.len());
        println!();
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let running = Arc::new(AtomicBool::new(true));

    let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);

    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_rxs = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(WORKER_QUEUE_SIZE);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    let mut handles = Vec::new();

    for producer_id in 0..NUM_PRODUCERS {
        let tx = ingress_tx.clone();
        let running_clone = running.clone();
        let metrics_clone = metrics.clone();
        handles.push(thread::spawn(move || {
            producer_thread(producer_id, tx, running_clone, metrics_clone)
        }));
    }

    {
        let rx = ingress_rx.clone();
        let txs = worker_txs.clone();
        let running_clone = running.clone();
        let metrics_clone = metrics.clone();
        handles.push(thread::spawn(move || {
            router_thread(rx, txs, running_clone, metrics_clone)
        }));
    }

    for (worker_id, rx) in worker_rxs.into_iter().enumerate() {
        let running_clone = running.clone();
        let metrics_clone = metrics.clone();
        handles.push(thread::spawn(move || {
            worker_thread(worker_id, rx, running_clone, metrics_clone)
        }));
    }

    {
        let metrics_clone = metrics.clone();
        let running_clone = running.clone();
        handles.push(thread::spawn(move || {
            metrics_thread(metrics_clone, running_clone)
        }));
    }

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    drop(ingress_tx);

    for handle in handles {
        let _ = handle.join();
    }

    println!("System shutdown complete.");
}
