use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const WORKER_COUNT: usize = 8;
const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const WORKER_QUEUE_SIZE: usize = 250_000;
const METRICS_INTERVAL_SECS: u64 = 1;

#[inline(always)]
fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

#[derive(Clone)]
pub struct Message {
    pub topic: Arc<str>,
    pub payload: Arc<[u8]>,
    pub created_at_ns: u64,
}

impl Message {
    #[inline(always)]
    pub fn new(topic: Arc<str>, payload: Arc<[u8]>) -> Self {
        Self {
            topic,
            payload,
            created_at_ns: now_nanos(),
        }
    }
}

#[derive(Default)]
pub struct LatencyStats {
    pub messages_in: AtomicU64,
    pub messages_routed: AtomicU64,
    pub messages_processed: AtomicU64,
    pub dropped: AtomicU64,

    pub total_route_latency_ns: AtomicU64,
    pub total_end_to_end_latency_ns: AtomicU64,

    pub max_route_latency_ns: AtomicU64,
    pub max_end_to_end_latency_ns: AtomicU64,
}

impl LatencyStats {
    #[inline(always)]
    pub fn record_ingress(&self) {
        self.messages_in.fetch_add(1, Ordering::Relaxed);
    }

    #[inline(always)]
    pub fn record_drop(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }

    #[inline(always)]
    pub fn record_routed(&self, route_latency_ns: u64) {
        self.messages_routed.fetch_add(1, Ordering::Relaxed);
        self.total_route_latency_ns
            .fetch_add(route_latency_ns, Ordering::Relaxed);
        update_max(&self.max_route_latency_ns, route_latency_ns);
    }

    #[inline(always)]
    pub fn record_processed(&self, end_to_end_ns: u64) {
        self.messages_processed.fetch_add(1, Ordering::Relaxed);
        self.total_end_to_end_latency_ns
            .fetch_add(end_to_end_ns, Ordering::Relaxed);
        update_max(&self.max_end_to_end_latency_ns, end_to_end_ns);
    }

    pub fn snapshot(&self) -> MetricsSnapshot {
        let messages_in = self.messages_in.load(Ordering::Relaxed);
        let messages_routed = self.messages_routed.load(Ordering::Relaxed);
        let messages_processed = self.messages_processed.load(Ordering::Relaxed);
        let dropped = self.dropped.load(Ordering::Relaxed);

        let total_route_latency_ns = self.total_route_latency_ns.load(Ordering::Relaxed);
        let total_end_to_end_latency_ns = self.total_end_to_end_latency_ns.load(Ordering::Relaxed);

        let avg_route_latency_ns = if messages_routed > 0 {
            total_route_latency_ns / messages_routed
        } else {
            0
        };

        let avg_end_to_end_latency_ns = if messages_processed > 0 {
            total_end_to_end_latency_ns / messages_processed
        } else {
            0
        };

        MetricsSnapshot {
            messages_in,
            messages_routed,
            messages_processed,
            dropped,
            avg_route_latency_ns,
            avg_end_to_end_latency_ns,
            max_route_latency_ns: self.max_route_latency_ns.load(Ordering::Relaxed),
            max_end_to_end_latency_ns: self.max_end_to_end_latency_ns.load(Ordering::Relaxed),
        }
    }
}

pub struct MetricsSnapshot {
    pub messages_in: u64,
    pub messages_routed: u64,
    pub messages_processed: u64,
    pub dropped: u64,
    pub avg_route_latency_ns: u64,
    pub avg_end_to_end_latency_ns: u64,
    pub max_route_latency_ns: u64,
    pub max_end_to_end_latency_ns: u64,
}

#[inline(always)]
fn update_max(target: &AtomicU64, value: u64) {
    let mut current = target.load(Ordering::Relaxed);
    while value > current {
        match target.compare_exchange_weak(
            current,
            value,
            Ordering::Relaxed,
            Ordering::Relaxed,
        ) {
            Ok(_) => break,
            Err(actual) => current = actual,
        }
    }
}

pub struct Router {
    ingress_tx: Sender<Message>,
    stats: Arc<LatencyStats>,
}

impl Router {
    pub fn new(workers: usize) -> Self {
        let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);
        let stats = Arc::new(LatencyStats::default());
        let topic_registry = Arc::new(DashMap::<Arc<str>, usize>::new());

        let mut worker_txs = Vec::with_capacity(workers);

        for worker_id in 0..workers {
            let (tx, rx) = bounded::<Message>(WORKER_QUEUE_SIZE);
            worker_txs.push(tx);

            let stats_clone = Arc::clone(&stats);
            thread::Builder::new()
                .name(format!("worker-{worker_id}"))
                .spawn(move || worker_loop(worker_id, rx, stats_clone))
                .expect("failed to spawn worker");
        }

        {
            let stats_clone = Arc::clone(&stats);
            let registry_clone = Arc::clone(&topic_registry);
            thread::Builder::new()
                .name("router-core".to_string())
                .spawn(move || router_loop(ingress_rx, worker_txs, registry_clone, stats_clone))
                .expect("failed to spawn router thread");
        }

        {
            let stats_clone = Arc::clone(&stats);
            thread::Builder::new()
                .name("metrics".to_string())
                .spawn(move || metrics_loop(stats_clone))
                .expect("failed to spawn metrics thread");
        }

        Self { ingress_tx, stats }
    }

    #[inline(always)]
    pub fn publish(&self, topic: Arc<str>, payload: Arc<[u8]>) -> Result<(), &'static str> {
        self.stats.record_ingress();
        let msg = Message::new(topic, payload);
        self.ingress_tx.try_send(msg).map_err(|_| {
            self.stats.record_drop();
            "ingress queue full"
        })
    }

    pub fn stats_snapshot(&self) -> MetricsSnapshot {
        self.stats.snapshot()
    }
}

fn router_loop(
    ingress_rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    topic_registry: Arc<DashMap<Arc<str>, usize>>,
    stats: Arc<LatencyStats>,
) {
    let worker_count = worker_txs.len();

    while let Ok(msg) = ingress_rx.recv() {
        let route_start_ns = now_nanos();

        let worker_idx = if let Some(entry) = topic_registry.get(&msg.topic) {
            *entry
        } else {
            let idx = hash_topic(&msg.topic) % worker_count;
            topic_registry.insert(Arc::clone(&msg.topic), idx);
            idx
        };

        if worker_txs[worker_idx].try_send(msg).is_ok() {
            let route_latency_ns = now_nanos().saturating_sub(route_start_ns);
            stats.record_routed(route_latency_ns);
        } else {
            stats.record_drop();
        }
    }
}

fn worker_loop(worker_id: usize, rx: Receiver<Message>, stats: Arc<LatencyStats>) {
    while let Ok(msg) = rx.recv() {
        process_message(worker_id, &msg);

        let e2e_ns = now_nanos().saturating_sub(msg.created_at_ns);
        stats.record_processed(e2e_ns);
    }
}

#[inline(always)]
fn process_message(_worker_id: usize, _msg: &Message) {
    std::hint::spin_loop();
}

fn metrics_loop(stats: Arc<LatencyStats>) {
    let mut last_in = 0;
    let mut last_processed = 0;
    let mut last_dropped = 0;

    loop {
        thread::sleep(Duration::from_secs(METRICS_INTERVAL_SECS));
        let snap = stats.snapshot();

        let in_rate = snap.messages_in.saturating_sub(last_in);
        let proc_rate = snap.messages_processed.saturating_sub(last_processed);
        let drop_rate = snap.dropped.saturating_sub(last_dropped);

        last_in = snap.messages_in;
        last_processed = snap.messages_processed;
        last_dropped = snap.dropped;

        println!(
            "[metrics] in={} msg/s processed={} msg/s dropped={} msg/s avg_route={} ns max_route={} ns avg_e2e={} ns max_e2e={} ns total_in={} total_processed={} total_dropped={}",
            in_rate,
            proc_rate,
            drop_rate,
            snap.avg_route_latency_ns,
            snap.max_route_latency_ns,
            snap.avg_end_to_end_latency_ns,
            snap.max_end_to_end_latency_ns,
            snap.messages_in,
            snap.messages_processed,
            snap.dropped
        );
    }
}

#[inline(always)]
fn hash_topic(topic: &str) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    hasher.finish() as usize
}

fn main() {
    let router = Arc::new(Router::new(WORKER_COUNT));
    let running = Arc::new(AtomicBool::new(true));

    let producer_threads = 4;
    let mut handles = Vec::new();

    for producer_id in 0..producer_threads {
        let router_clone = Arc::clone(&router);
        let running_clone = Arc::clone(&running);

        let handle = thread::Builder::new()
            .name(format!("producer-{producer_id}"))
            .spawn(move || {
                let mut rng = rand::thread_rng();
                let topics: Vec<Arc<str>> = vec![
                    Arc::from("orders"),
                    Arc::from("trades"),
                    Arc::from("quotes"),
                    Arc::from("risk"),
                    Arc::from("positions"),
                ];

                while running_clone.load(Ordering::Relaxed) {
                    let topic = Arc::clone(&topics[rng.gen_range(0..topics.len())]);

                    let payload_vec = vec![42u8; 128];
                    let payload: Arc<[u8]> = Arc::from(payload_vec.into_boxed_slice());

                    let _ = router_clone.publish(topic, payload);
                }
            })
            .expect("failed to spawn producer");

        handles.push(handle);
    }

    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for h in handles {
        let _ = h.join();
    }

    let final_stats = router.stats_snapshot();
    println!(
        "Final stats: in={} routed={} processed={} dropped={}",
        final_stats.messages_in,
        final_stats.messages_routed,
        final_stats.messages_processed,
        final_stats.dropped
    );
}
