use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::distributions::Alphanumeric;
use rand::{thread_rng, Rng};
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

const NUM_TOPICS: usize = 1024;
const MESSAGE_SIZE: usize = 128;
const CHANNEL_CAPACITY: usize = 1_000_000;
const PRODUCER_THREADS: usize = 4;
const RUN_DURATION_SECS: u64 = 15;

#[derive(Clone)]
struct Message {
    topic: String,
    payload: [u8; MESSAGE_SIZE],
    ingress_time: Instant,
    sequence: u64,
}

struct WorkerStats {
    processed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
}

impl WorkerStats {
    fn new() -> Self {
        Self {
            processed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
        }
    }
}

struct SharedMetrics {
    total_ingress: AtomicU64,
    total_routed: AtomicU64,
    hist: Mutex<Histogram<u64>>,
}

impl SharedMetrics {
    fn new() -> Self {
        Self {
            total_ingress: AtomicU64::new(0),
            total_routed: AtomicU64::new(0),
            hist: Mutex::new(Histogram::<u64>::new(3).unwrap()),
        }
    }
}

fn topic_hash(topic: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    hasher.finish()
}

fn worker_loop(
    id: usize,
    rx: Receiver<Message>,
    stats: Arc<WorkerStats>,
    metrics: Arc<SharedMetrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let latency = msg.ingress_time.elapsed();
                let latency_ns = latency.as_nanos() as u64;

                stats.processed.fetch_add(1, Ordering::Relaxed);
                stats
                    .total_latency_ns
                    .fetch_add(latency_ns, Ordering::Relaxed);

                metrics.total_routed.fetch_add(1, Ordering::Relaxed);

                if let Ok(mut hist) = metrics.hist.lock() {
                    let _ = hist.record(latency_ns);
                }

                let _ = black_box_process(&msg);
            }
            Err(_) => {}
        }
    }

    println!("worker {} exiting", id);
}

#[inline(always)]
fn black_box_process(msg: &Message) -> u64 {
    let mut acc = msg.sequence;
    for b in msg.payload.iter() {
        acc = acc.wrapping_mul(31).wrapping_add(*b as u64);
    }
    acc
}

fn router_loop(
    ingress_rx: Receiver<Message>,
    worker_txs: Vec<Sender<Message>>,
    worker_stats: Vec<Arc<WorkerStats>>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !ingress_rx.is_empty() {
        match ingress_rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let idx = (topic_hash(&msg.topic) as usize) % worker_txs.len();
                if worker_txs[idx].try_send(msg).is_err() {
                    worker_stats[idx].dropped.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {}
        }
    }

    println!("router exiting");
}

fn producer_loop(
    id: usize,
    ingress_tx: Sender<Message>,
    metrics: Arc<SharedMetrics>,
    running: Arc<AtomicBool>,
) {
    let mut rng = thread_rng();
    let mut seq = 0u64;
    let topics: Vec<String> = (0..NUM_TOPICS)
        .map(|i| format!("topic-{}", i))
        .collect();

    while running.load(Ordering::Relaxed) {
        let topic = &topics[rng.gen_range(0..topics.len())];
        let mut payload = [0u8; MESSAGE_SIZE];
        rng.fill(&mut payload);

        let msg = Message {
            topic: topic.clone(),
            payload,
            ingress_time: Instant::now(),
            sequence: ((id as u64) << 56) | seq,
        };

        if ingress_tx.try_send(msg).is_ok() {
            metrics.total_ingress.fetch_add(1, Ordering::Relaxed);
        }

        seq = seq.wrapping_add(1);
    }

    println!("producer {} exiting", id);
}

fn monitor_loop(
    worker_stats: Vec<Arc<WorkerStats>>,
    metrics: Arc<SharedMetrics>,
    running: Arc<AtomicBool>,
) {
    let mut last_ingress = 0u64;
    let mut last_routed = 0u64;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let ingress = metrics.total_ingress.load(Ordering::Relaxed);
        let routed = metrics.total_routed.load(Ordering::Relaxed);

        let ingress_rate = ingress - last_ingress;
        let routed_rate = routed - last_routed;

        last_ingress = ingress;
        last_routed = routed;

        let mut total_processed = 0u64;
        let mut total_dropped = 0u64;
        let mut total_latency = 0u64;

        for ws in &worker_stats {
            total_processed += ws.processed.load(Ordering::Relaxed);
            total_dropped += ws.dropped.load(Ordering::Relaxed);
            total_latency += ws.total_latency_ns.load(Ordering::Relaxed);
        }

        let avg_latency_ns = if total_processed > 0 {
            total_latency / total_processed
        } else {
            0
        };

        let (p50, p95, p99, max) = if let Ok(hist) = metrics.hist.lock() {
            if hist.len() > 0 {
                (
                    hist.value_at_quantile(0.50),
                    hist.value_at_quantile(0.95),
                    hist.value_at_quantile(0.99),
                    hist.max(),
                )
            } else {
                (0, 0, 0, 0)
            }
        } else {
            (0, 0, 0, 0)
        };

        println!(
            "ingress/s={} routed/s={} total_processed={} dropped={} avg_latency_ns={} p50={} p95={} p99={} max={}",
            ingress_rate,
            routed_rate,
            total_processed,
            total_dropped,
            avg_latency_ns,
            p50,
            p95,
            p99,
            max
        );
    }

    println!("monitor exiting");
}

#[tokio::main(flavor = "multi_thread")]
async fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(SharedMetrics::new());

    let worker_count = num_cpus::get().max(2);
    let (ingress_tx, ingress_rx) = bounded::<Message>(CHANNEL_CAPACITY);

    let mut worker_txs = Vec::with_capacity(worker_count);
    let mut worker_rxs = Vec::with_capacity(worker_count);
    let mut worker_stats = Vec::with_capacity(worker_count);

    for _ in 0..worker_count {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY / worker_count.max(1));
        worker_txs.push(tx);
        worker_rxs.push(rx);
        worker_stats.push(Arc::new(WorkerStats::new()));
    }

    let router_running = running.clone();
    let router_worker_txs = worker_txs.clone();
    let router_worker_stats = worker_stats.clone();
    let router_handle = thread::spawn(move || {
        router_loop(ingress_rx, router_worker_txs, router_worker_stats, router_running)
    });

    let mut worker_handles = Vec::new();
    for (i, rx) in worker_rxs.into_iter().enumerate() {
        let stats = worker_stats[i].clone();
        let metrics_clone = metrics.clone();
        let worker_running = running.clone();
        worker_handles.push(thread::spawn(move || {
            worker_loop(i, rx, stats, metrics_clone, worker_running)
        }));
    }

    let mut producer_handles = Vec::new();
    for i in 0..PRODUCER_THREADS {
        let tx = ingress_tx.clone();
        let metrics_clone = metrics.clone();
        let producer_running = running.clone();
        producer_handles.push(thread::spawn(move || {
            producer_loop(i, tx, metrics_clone, producer_running)
        }));
    }

    let monitor_running = running.clone();
    let monitor_stats = worker_stats.clone();
    let monitor_metrics = metrics.clone();
    let monitor_handle = thread::spawn(move || {
        monitor_loop(monitor_stats, monitor_metrics, monitor_running)
    });

    tokio::time::sleep(Duration::from_secs(RUN_DURATION_SECS)).await;
    running.store(false, Ordering::Relaxed);

    for handle in producer_handles {
        let _ = handle.join();
    }

    let _ = router_handle.join();

    for handle in worker_handles {
        let _ = handle.join();
    }

    let _ = monitor_handle.join();

    println!("system shutdown complete");
}
```

