# Main implementation

```rust
use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use dashmap::DashMap;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone, Debug)]
pub struct Message {
    pub topic: String,
    pub payload: Vec<u8>,
    pub created_at_ns: u64,
}

impl Message {
    pub fn new(topic: impl Into<String>, payload: Vec<u8>) -> Self {
        Self {
            topic: topic.into(),
            payload,
            created_at_ns: now_ns(),
        }
    }
}

#[inline]
fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

pub struct RouteMetrics {
    pub routed: AtomicU64,
    pub dropped: AtomicU64,
    pub total_latency_ns: AtomicU64,
    pub max_latency_ns: AtomicU64,
}

impl RouteMetrics {
    pub fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    #[inline]
    pub fn record_success(&self, latency_ns: u64) {
        self.routed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    #[inline]
    pub fn record_drop(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

pub struct Subscriber {
    pub id: u64,
    pub tx: Sender<Message>,
}

pub struct TopicEntry {
    pub subscribers: Vec<Subscriber>,
    pub metrics: Arc<RouteMetrics>,
}

pub struct Router {
    topics: DashMap<String, Arc<TopicEntry>>,
    ingress_tx: Sender<Message>,
    ingress_rx: Receiver<Message>,
    running: AtomicBool,
}

impl Router {
    pub fn new(queue_capacity: usize) -> Arc<Self> {
        let (tx, rx) = bounded(queue_capacity);
        Arc::new(Self {
            topics: DashMap::new(),
            ingress_tx: tx,
            ingress_rx: rx,
            running: AtomicBool::new(true),
        })
    }

    pub fn publisher(&self) -> Sender<Message> {
        self.ingress_tx.clone()
    }

    pub fn subscribe(
        &self,
        topic: impl Into<String>,
        subscriber_id: u64,
        queue_capacity: usize,
    ) -> Receiver<Message> {
        let topic = topic.into();
        let (tx, rx) = bounded(queue_capacity);

        let subscriber = Subscriber {
            id: subscriber_id,
            tx,
        };

        self.topics
            .entry(topic)
            .and_modify(|entry| {
                let mut subs = entry.subscribers.clone();
                subs.push(subscriber.clone());
                *entry = Arc::new(TopicEntry {
                    subscribers: subs,
                    metrics: entry.metrics.clone(),
                });
            })
            .or_insert_with(|| {
                Arc::new(TopicEntry {
                    subscribers: vec![subscriber],
                    metrics: Arc::new(RouteMetrics::new()),
                })
            });

        rx
    }

    pub fn start(self: Arc<Self>, worker_threads: usize) -> Vec<thread::JoinHandle<()>> {
        let mut handles = Vec::with_capacity(worker_threads);

        for _ in 0..worker_threads {
            let router = self.clone();
            let rx = router.ingress_rx.clone();

            let handle = thread::spawn(move || {
                while router.running.load(Ordering::Relaxed) {
                    match rx.recv() {
                        Ok(msg) => {
                            if let Some(entry) = router.topics.get(&msg.topic) {
                                let latency_ns = now_ns().saturating_sub(msg.created_at_ns);

                                for sub in &entry.subscribers {
                                    match sub.tx.try_send(msg.clone()) {
                                        Ok(_) => {
                                            entry.metrics.record_success(latency_ns);
                                        }
                                        Err(TrySendError::Full(_)) | Err(TrySendError::Disconnected(_)) => {
                                            entry.metrics.record_drop();
                                        }
                                    }
                                }
                            }
                        }
                        Err(_) => break,
                    }
                }
            });

            handles.push(handle);
        }

        handles
    }

    pub fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }

    pub fn metrics_snapshot(&self) -> Vec<(String, u64, u64, u64, u64)> {
        self.topics
            .iter()
            .map(|entry| {
                let topic = entry.key().clone();
                let metrics = entry.value().metrics.clone();

                let routed = metrics.routed.load(Ordering::Relaxed);
                let dropped = metrics.dropped.load(Ordering::Relaxed);
                let total_latency_ns = metrics.total_latency_ns.load(Ordering::Relaxed);
                let max_latency_ns = metrics.max_latency_ns.load(Ordering::Relaxed);
                let avg_latency_ns = if routed > 0 {
                    total_latency_ns / routed
                } else {
                    0
                };

                (topic, routed, dropped, avg_latency_ns, max_latency_ns)
            })
            .collect()
    }
}

impl Clone for Subscriber {
    fn clone(&self) -> Self {
        Self {
            id: self.id,
            tx: self.tx.clone(),
        }
    }
}

fn topic_for(i: u64) -> &'static str {
    match i % 4 {
        0 => "orders",
        1 => "trades",
        2 => "quotes",
        _ => "risk",
    }
}

fn main() {
    let router = Router::new(1_000_000);

    let worker_handles = router.clone().start(4);

    let orders_rx = router.subscribe("orders", 1, 100_000);
    let trades_rx = router.subscribe("trades", 2, 100_000);
    let quotes_rx = router.subscribe("quotes", 3, 100_000);
    let risk_rx = router.subscribe("risk", 4, 100_000);

    let consumer_handles: Vec<_> = vec![orders_rx, trades_rx, quotes_rx, risk_rx]
        .into_iter()
        .map(|rx| {
            thread::spawn(move || {
                while let Ok(_msg) = rx.recv() {
                    // Simulate ultra-fast consumer
                    std::hint::spin_loop();
                }
            })
        })
        .collect();

    let metrics_router = router.clone();
    let metrics_handle = thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(1));
        let snapshot = metrics_router.metrics_snapshot();
        println!("==== metrics ====");
        for (topic, routed, dropped, avg_ns, max_ns) in snapshot {
            println!(
                "topic={topic} routed={routed} dropped={dropped} avg_latency_ns={avg_ns} max_latency_ns={max_ns}"
            );
        }
    });

    let publisher = router.publisher();
    let producer_threads = 4;
    let messages_per_thread = 1_000_000;

    let mut producers = Vec::new();

    for t in 0..producer_threads {
        let tx = publisher.clone();
        let handle = thread::spawn(move || {
            for i in 0..messages_per_thread {
                let global_i = (t * messages_per_thread + i) as u64;
                let topic = topic_for(global_i);
                let payload = vec![0u8; 128];

                let msg = Message::new(topic, payload);
                if tx.send(msg).is_err() {
                    break;
                }
            }
        });
        producers.push(handle);
    }

    for h in producers {
        h.join().unwrap();
    }

    thread::sleep(Duration::from_secs(3));
    router.stop();

    drop(router.publisher());

    for h in worker_handles {
        let _ = h.join();
    }

    for h in consumer_handles {
        let _ = h.join();
    }

    let _ = metrics_handle.join();
}
