# Main implementation

```rust
use bytes::Bytes;
use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone)]
struct Message {
    topic: u64,
    created_ns: u64,
    payload: Bytes,
}

impl Message {
    #[inline]
    fn new(topic: u64, payload: Bytes) -> Self {
        Self {
            topic,
            created_ns: now_ns(),
            payload,
        }
    }
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
}

struct LatencyMetrics {
    route_latency_ns: Mutex<Histogram<u64>>,
    end_to_end_latency_ns: Mutex<Histogram<u64>>,
}

impl LatencyMetrics {
    fn new() -> Self {
        Self {
            route_latency_ns: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ),
            end_to_end_latency_ns: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
            ),
        }
    }

    fn record_route_latency(&self, value: u64) {
        if let Ok(mut h) = self.route_latency_ns.lock() {
            let _ = h.record(value.max(1));
        }
    }

    fn record_end_to_end_latency(&self, value: u64) {
        if let Ok(mut h) = self.end_to_end_latency_ns.lock() {
            let _ = h.record(value.max(1));
        }
    }

    fn snapshot(&self) -> (Histogram<u64>, Histogram<u64>) {
        let route = self.route_latency_ns.lock().unwrap().clone();
        let e2e = self.end_to_end_latency_ns.lock().unwrap().clone();
        (route, e2e)
    }
}

struct Router {
    shard_senders: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    latency: Arc<LatencyMetrics>,
}

impl Router {
    fn new(
        shard_senders: Vec<Sender<Message>>,
        metrics: Arc<Metrics>,
        latency: Arc<LatencyMetrics>,
    ) -> Self {
        Self {
            shard_senders,
            metrics,
            latency,
        }
    }

    #[inline]
    fn route(&self, msg: Message) {
        self.metrics.received.fetch_add(1, Ordering::Relaxed);

        let route_start = now_ns();
        let idx = shard_for_topic(msg.topic, self.shard_senders.len());

        match self.shard_senders[idx].try_send(msg) {
            Ok(()) => {
                self.metrics.routed.fetch_add(1, Ordering::Relaxed);
                let route_end = now_ns();
                self.latency
                    .record_route_latency(route_end.saturating_sub(route_start));
            }
            Err(TrySendError::Full(_)) | Err(TrySendError::Disconnected(_)) => {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    }
}

fn shard_for_topic(topic: u64, num_shards: usize) -> usize {
    let mut hasher = DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % num_shards
}

fn worker_loop(
    shard_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    latency: Arc<LatencyMetrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                // Simulated processing
                black_box_process(&msg);

                metrics.processed.fetch_add(1, Ordering::Relaxed);

                let now = now_ns();
                latency.record_end_to_end_latency(now.saturating_sub(msg.created_ns));
            }
            Err(_) => {
                // timeout/disconnect; continue
            }
        }
    }

    // Drain remaining messages on shutdown
    while let Ok(msg) = rx.try_recv() {
        black_box_process(&msg);
        metrics.processed.fetch_add(1, Ordering::Relaxed);
        let now = now_ns();
        latency.record_end_to_end_latency(now.saturating_sub(msg.created_ns));
    }

    println!("worker {} stopped", shard_id);
}

#[inline(never)]
fn black_box_process(msg: &Message) {
    let mut acc = 0u64;
    for b in msg.payload.iter().take(8) {
        acc = acc.wrapping_add(*b as u64);
    }
    std::hint::black_box(acc);
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn metrics_reporter(
    metrics: Arc<Metrics>,
    latency: Arc<LatencyMetrics>,
    running: Arc<AtomicBool>,
) {
    let mut last_received = 0;
    let mut last_routed = 0;
    let mut last_processed = 0;
    let mut last_dropped = 0;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let processed = metrics.processed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);

        let d_received = received - last_received;
        let d_routed = routed - last_routed;
        let d_processed = processed - last_processed;
        let d_dropped = dropped - last_dropped;

        last_received = received;
        last_routed = routed;
        last_processed = processed;
        last_dropped = dropped;

        let (route_hist, e2e_hist) = latency.snapshot();

        println!("=== metrics ===");
        println!(
            "recv/s={} routed/s={} processed/s={} dropped/s={}",
            d_received, d_routed, d_processed, d_dropped
        );

        if route_hist.len() > 0 {
            println!(
                "route latency ns: p50={} p99={} p99.9={} max={}",
                route_hist.value_at_quantile(0.50),
                route_hist.value_at_quantile(0.99),
                route_hist.value_at_quantile(0.999),
                route_hist.max()
            );
        }

        if e2e_hist.len() > 0 {
            println!(
                "e2e latency ns: p50={} p99={} p99.9={} max={}",
                e2e_hist.value_at_quantile(0.50),
                e2e_hist.value_at_quantile(0.99),
                e2e_hist.value_at_quantile(0.999),
                e2e_hist.max()
            );
        }
    }
}

fn producer_loop(router: Arc<Router>, running: Arc<AtomicBool>, producer_id: usize) {
    let mut rng = rand::thread_rng();

    while running.load(Ordering::Relaxed) {
        let topic = rng.gen_range(0..10_000) as u64;

        // Small payload to keep throughput high
        let payload = Bytes::from(vec![producer_id as u8; 32]);
        let msg = Message::new(topic, payload);

        router.route(msg);
    }
}

fn main() {
    let num_shards = num_cpus::get().max(2);
    let queue_capacity = 1_000_000usize;
    let num_producers = num_cpus::get();

    let metrics = Arc::new(Metrics::default());
    let latency = Arc::new(LatencyMetrics::new());
    let running = Arc::new(AtomicBool::new(true));

    let mut shard_senders = Vec::with_capacity(num_shards);
    let mut worker_handles = Vec::with_capacity(num_shards);

    for shard_id in 0..num_shards {
        let (tx, rx) = bounded::<Message>(queue_capacity);
        shard_senders.push(tx);

        let metrics_clone = Arc::clone(&metrics);
        let latency_clone = Arc::clone(&latency);
        let running_clone = Arc::clone(&running);

        let handle = thread::spawn(move || {
            worker_loop(shard_id, rx, metrics_clone, latency_clone, running_clone)
        });

        worker_handles.push(handle);
    }

    let router = Arc::new(Router::new(
        shard_senders,
        Arc::clone(&metrics),
        Arc::clone(&latency),
    ));

    let reporter_handle = {
        let metrics_clone = Arc::clone(&metrics);
        let latency_clone = Arc::clone(&latency);
        let running_clone = Arc::clone(&running);
        thread::spawn(move || metrics_reporter(metrics_clone, latency_clone, running_clone))
    };

    let mut producer_handles = Vec::with_capacity(num_producers);
    for i in 0..num_producers {
        let router_clone = Arc::clone(&router);
        let running_clone = Arc::clone(&running);
        let handle = thread::spawn(move || producer_loop(router_clone, running_clone, i));
        producer_handles.push(handle);
    }

    thread::sleep(Duration::from_secs(15));
    running.store(false, Ordering::Relaxed);

    for h in producer_handles {
        let _ = h.join();
    }

    for h in worker_handles {
        let _ = h.join();
    }

    let _ = reporter_handle.join();

    println!("shutdown complete");
}
```

