# If you want Go instead

Here is a simpler **Go** version skeleton. It is easier to read, but Rust will usually give better control over latency and allocation.

```go
package main

import (
	"fmt"
	"hash/fnv"
	"math/rand"
	"runtime"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     uint64
	CreatedNs int64
	Payload   []byte
}

type Metrics struct {
	Received  uint64
	Routed    uint64
	Dropped   uint64
	Processed uint64
}

func shardForTopic(topic uint64, shards int) int {
	h := fnv.New64a()
	var b [8]byte
	for i := 0; i < 8; i++ {
		b[i] = byte(topic >> (8 * i))
	}
	h.Write(b[:])
	return int(h.Sum64() % uint64(shards))
}

func worker(id int, ch <-chan Message, metrics *Metrics) {
	for msg := range ch {
		_ = msg.Payload
		atomic.AddUint64(&metrics.Processed, 1)
	}
}

func producer(shards []chan Message, metrics *Metrics, stop <-chan struct{}) {
	r := rand.New(rand.NewSource(time.Now().UnixNano()))
	for {
		select {
		case <-stop:
			return
		default:
			msg := Message{
				Topic:     uint64(r.Intn(10000)),
				CreatedNs: time.Now().UnixNano(),
				Payload:   make([]byte, 32),
			}
			atomic.AddUint64(&metrics.Received, 1)
			idx := shardForTopic(msg.Topic, len(shards))
			select {
			case shards[idx] <- msg:
				atomic.AddUint64(&metrics.Routed, 1)
			default:
				atomic.AddUint64(&metrics.Dropped, 1)
			}
		}
	}
}

func main() {
	numShards := runtime.NumCPU()
	shards := make([]chan Message, numShards)
	metrics := &Metrics{}
	stop := make(chan struct{})

	for i := 0; i < numShards; i++ {
		shards[i] = make(chan Message, 100000)
		go worker(i, shards[i], metrics)
	}

	for i := 0; i < runtime.NumCPU(); i++ {
		go producer(shards, metrics, stop)
	}

	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	go func() {
		var lastR, lastRt, lastP, lastD uint64
		for range ticker.C {
			r := atomic.LoadUint64(&metrics.Received)
			rt := atomic.LoadUint64(&metrics.Routed)
			p := atomic.LoadUint64(&metrics.Processed)
			d := atomic.LoadUint64(&metrics.Dropped)

			fmt.Printf("recv/s=%d routed/s=%d processed/s=%d dropped/s=%d\n",
				r-lastR, rt-lastRt, p-lastP, d-lastD)

			lastR, lastRt, lastP, lastD = r, rt, p, d
		}
	}()

	time.Sleep(15 * time.Second)
	close(stop)
	time.Sleep(1 * time.Second)
}
