```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_TOPICS: usize = 8;
const NUM_PRODUCERS: usize = 4;
const NUM_WORKERS_PER_TOPIC: usize = 2;
const INGRESS_QUEUE_SIZE: usize = 1_000_000;
const PAYLOAD_SIZE: usize = 128;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: usize,
    ingress_ns: u128,
    payload: [u8; PAYLOAD_SIZE],
}

#[derive(Default)]
struct Metrics {
    total_received: AtomicU64,
    total_routed: AtomicU64,
    total_processed: AtomicU64,
    total_dropped: AtomicU64,
    latency_histogram: Mutex<Histogram<u64>>,
}

fn now_ns() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn producer_thread(
    producer_id: usize,
    tx: Sender<Message>,
    metrics: Arc<Metrics>,
    id_gen: Arc<AtomicU64>,
) {
    let mut rng = rand::thread_rng();

    loop {
        let id = id_gen.fetch_add(1, Ordering::Relaxed);
        let topic = rng.gen_range(0..NUM_TOPICS);

        let mut payload = [0u8; PAYLOAD_SIZE];
        for b in payload.iter_mut() {
            *b = rng.gen();
        }

        let msg = Message {
            id,
            topic,
            ingress_ns: now_ns(),
            payload,
        };

        match tx.try_send(msg) {
            Ok(_) => {
                metrics.total_received.fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {
                metrics.total_dropped.fetch_add(1, Ordering::Relaxed);
                // Drop on backpressure to preserve low latency
            }
        }

        if producer_id == usize::MAX {
            break;
        }
    }
}

fn router_thread(
    ingress_rx: Receiver<Message>,
    topic_senders: Vec<Vec<Sender<Message>>>,
    metrics: Arc<Metrics>,
) {
    let mut rr_counters = vec![0usize; NUM_TOPICS];

    while let Ok(msg) = ingress_rx.recv() {
        let topic = msg.topic;
        let workers = &topic_senders[topic];
        let idx = rr_counters[topic] % workers.len();
        rr_counters[topic] += 1;

        if workers[idx].try_send(msg).is_ok() {
            metrics.total_routed.fetch_add(1, Ordering::Relaxed);
        } else {
            metrics.total_dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn worker_thread(
    topic: usize,
    worker_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
) {
    let _ = (topic, worker_id);

    while let Ok(msg) = rx.recv() {
        // Simulate processing
        std::hint::black_box(&msg.payload);

        let latency_ns = (now_ns() - msg.ingress_ns) as u64;

        {
            let mut hist = metrics.latency_histogram.lock().unwrap();
            let _ = hist.record(latency_ns);
        }

        metrics.total_processed.fetch_add(1, Ordering::Relaxed);
    }
}

fn metrics_thread(metrics: Arc<Metrics>) {
    let mut last_processed = 0u64;

    loop {
        thread::sleep(Duration::from_secs(1));

        let received = metrics.total_received.load(Ordering::Relaxed);
        let routed = metrics.total_routed.load(Ordering::Relaxed);
        let processed = metrics.total_processed.load(Ordering::Relaxed);
        let dropped = metrics.total_dropped.load(Ordering::Relaxed);

        let delta = processed - last_processed;
        last_processed = processed;

        let (p50, p95, p99, max) = {
            let hist = metrics.latency_histogram.lock().unwrap();
            if hist.len() > 0 {
                (
                    hist.value_at_quantile(0.50),
                    hist.value_at_quantile(0.95),
                    hist.value_at_quantile(0.99),
                    hist.max(),
                )
            } else {
                (0, 0, 0, 0)
            }
        };

        println!(
            "recv={} routed={} processed={} dropped={} throughput={} msg/s latency(ns): p50={} p95={} p99={} max={}",
            received, routed, processed, dropped, delta, p50, p95, p99, max
        );
    }
}

fn main() {
    let metrics = Arc::new(Metrics {
        total_received: AtomicU64::new(0),
        total_routed: AtomicU64::new(0),
        total_processed: AtomicU64::new(0),
        total_dropped: AtomicU64::new(0),
        latency_histogram: Mutex::new(Histogram::<u64>::new(3).unwrap()),
    });

    let id_gen = Arc::new(AtomicU64::new(1));

    let (ingress_tx, ingress_rx) = bounded::<Message>(INGRESS_QUEUE_SIZE);

    let mut topic_senders: Vec<Vec<Sender<Message>>> = Vec::with_capacity(NUM_TOPICS);

    for topic in 0..NUM_TOPICS {
        let mut workers = Vec::with_capacity(NUM_WORKERS_PER_TOPIC);

        for worker_id in 0..NUM_WORKERS_PER_TOPIC {
            let (tx, rx) = bounded::<Message>(INGRESS_QUEUE_SIZE / NUM_TOPICS);
            workers.push(tx);

            let metrics_clone = Arc::clone(&metrics);
            thread::spawn(move || worker_thread(topic, worker_id, rx, metrics_clone));
        }

        topic_senders.push(workers);
    }

    {
        let metrics_clone = Arc::clone(&metrics);
        let router_senders = topic_senders.clone();
        thread::spawn(move || router_thread(ingress_rx, router_senders, metrics_clone));
    }

    for producer_id in 0..NUM_PRODUCERS {
        let tx = ingress_tx.clone();
        let metrics_clone = Arc::clone(&metrics);
        let id_clone = Arc::clone(&id_gen);

        thread::spawn(move || producer_thread(producer_id, tx, metrics_clone, id_clone));
    }

    {
        let metrics_clone = Arc::clone(&metrics);
        thread::spawn(move || metrics_thread(metrics_clone));
    }

    loop {
        thread::park();
    }
}
```

