# `src/main.rs`

```rust
use ahash::AHasher;
use bytes::Bytes;
use dashmap::DashMap;
use flume::{Receiver, Sender};
use hdrhistogram::Histogram;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tokio::task;
use tokio::time::sleep;

type Topic = String;
type SubscriberId = u64;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Message {
    pub topic: Topic,
    pub payload: Bytes,
    pub created_at_ns: u64,
    pub sequence: u64,
}

impl Message {
    pub fn new(topic: impl Into<String>, payload: Bytes, sequence: u64) -> Self {
        Self {
            topic: topic.into(),
            payload,
            created_at_ns: now_ns(),
            sequence,
        }
    }
}

#[derive(Default)]
pub struct RouteMetrics {
    pub routed: AtomicU64,
    pub dropped: AtomicU64,
    pub total_latency_ns: AtomicU64,
}

pub struct Subscriber {
    pub id: SubscriberId,
    pub tx: Sender<Message>,
}

pub struct Router {
    routes: DashMap<Topic, Vec<Subscriber>>,
    route_metrics: DashMap<Topic, Arc<RouteMetrics>>,
    ingress_tx: Vec<Sender<Message>>,
    running: AtomicBool,
}

impl Router {
    pub fn new(worker_count: usize, queue_size: usize) -> Arc<Self> {
        let mut ingress_tx = Vec::with_capacity(worker_count);
        let mut ingress_rx = Vec::with_capacity(worker_count);

        for _ in 0..worker_count {
            let (tx, rx) = flume::bounded::<Message>(queue_size);
            ingress_tx.push(tx);
            ingress_rx.push(rx);
        }

        let router = Arc::new(Self {
            routes: DashMap::new(),
            route_metrics: DashMap::new(),
            ingress_tx,
            running: AtomicBool::new(true),
        });

        for (worker_id, rx) in ingress_rx.into_iter().enumerate() {
            let router_clone = Arc::clone(&router);
            task::spawn(async move {
                router_clone.worker_loop(worker_id, rx).await;
            });
        }

        router
    }

    pub fn subscribe(&self, topic: impl Into<String>, subscriber_id: SubscriberId) -> Receiver<Message> {
        let topic = topic.into();
        let (tx, rx) = flume::bounded::<Message>(65_536);

        self.routes
            .entry(topic.clone())
            .or_insert_with(Vec::new)
            .push(Subscriber {
                id: subscriber_id,
                tx,
            });

        self.route_metrics
            .entry(topic)
            .or_insert_with(|| Arc::new(RouteMetrics::default()));

        rx
    }

    pub fn publish(&self, msg: Message) -> Result<(), flume::SendError<Message>> {
        let shard = self.shard_for(&msg.topic);
        self.ingress_tx[shard].send(msg)
    }

    fn shard_for(&self, topic: &str) -> usize {
        let mut hasher = AHasher::default();
        topic.hash(&mut hasher);
        (hasher.finish() as usize) % self.ingress_tx.len()
    }

    async fn worker_loop(self: Arc<Self>, worker_id: usize, rx: Receiver<Message>) {
        while self.running.load(Ordering::Relaxed) {
            match rx.recv_async().await {
                Ok(msg) => {
                    self.route_message(msg);
                }
                Err(_) => {
                    eprintln!("worker {} exiting: ingress closed", worker_id);
                    break;
                }
            }
        }
    }

    fn route_message(&self, msg: Message) {
        let now = now_ns();
        let latency = now.saturating_sub(msg.created_at_ns);

        if let Some(subscribers_ref) = self.routes.get(&msg.topic) {
            let subscribers = subscribers_ref.value();

            let metrics = self
                .route_metrics
                .entry(msg.topic.clone())
                .or_insert_with(|| Arc::new(RouteMetrics::default()))
                .clone();

            let mut delivered = 0u64;
            let mut dropped = 0u64;

            for sub in subscribers.iter() {
                match sub.tx.try_send(msg.clone()) {
                    Ok(_) => {
                        delivered += 1;
                    }
                    Err(_) => {
                        dropped += 1;
                    }
                }
            }

            metrics.routed.fetch_add(delivered, Ordering::Relaxed);
            metrics.dropped.fetch_add(dropped, Ordering::Relaxed);
            metrics
                .total_latency_ns
                .fetch_add(latency, Ordering::Relaxed);
        }
    }

    pub fn snapshot_metrics(&self) -> HashMap<String, RouteSnapshot> {
        let mut out = HashMap::new();

        for entry in self.route_metrics.iter() {
            let topic = entry.key().clone();
            let metrics = entry.value();

            let routed = metrics.routed.load(Ordering::Relaxed);
            let dropped = metrics.dropped.load(Ordering::Relaxed);
            let total_latency_ns = metrics.total_latency_ns.load(Ordering::Relaxed);

            let avg_latency_ns = if routed > 0 {
                total_latency_ns / routed
            } else {
                0
            };

            out.insert(
                topic,
                RouteSnapshot {
                    routed,
                    dropped,
                    avg_latency_ns,
                },
            );
        }

        out
    }

    pub fn shutdown(&self) {
        self.running.store(false, Ordering::Relaxed);
    }
}

#[derive(Debug, Serialize)]
pub struct RouteSnapshot {
    pub routed: u64,
    pub dropped: u64,
    pub avg_latency_ns: u64,
}

pub struct LatencyMonitor {
    histogram: Mutex<Histogram<u64>>,
    samples: AtomicU64,
}

impl LatencyMonitor {
    pub fn new() -> Self {
        Self {
            histogram: Mutex::new(Histogram::new(3).unwrap()),
            samples: AtomicU64::new(0),
        }
    }

    pub fn record(&self, latency_ns: u64) {
        if let Ok(mut h) = self.histogram.lock() {
            let _ = h.record(latency_ns);
            self.samples.fetch_add(1, Ordering::Relaxed);
        }
    }

    pub fn snapshot(&self) -> LatencySnapshot {
        let h = self.histogram.lock().unwrap();
        LatencySnapshot {
            count: self.samples.load(Ordering::Relaxed),
            p50_ns: h.value_at_quantile(0.50),
            p95_ns: h.value_at_quantile(0.95),
            p99_ns: h.value_at_quantile(0.99),
            max_ns: h.max(),
        }
    }
}

#[derive(Debug, Serialize)]
pub struct LatencySnapshot {
    pub count: u64,
    pub p50_ns: u64,
    pub p95_ns: u64,
    pub p99_ns: u64,
    pub max_ns: u64,
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::ZERO)
        .as_nanos() as u64
}

#[tokio::main(flavor = "multi_thread")]
async fn main() {
    let worker_count = num_cpus::get().max(4);
    let router = Router::new(worker_count, 262_144);
    let latency_monitor = Arc::new(LatencyMonitor::new());

    // Create subscribers
    let mut subscriber_handles = Vec::new();
    for i in 0..8u64 {
        let rx = router.subscribe("orders", i);
        let lm = Arc::clone(&latency_monitor);

        let handle = task::spawn(async move {
            while let Ok(msg) = rx.recv_async().await {
                let latency = now_ns().saturating_sub(msg.created_at_ns);
                lm.record(latency);

                // Simulate lightweight processing
                let _ = msg.sequence;
            }
        });

        subscriber_handles.push(handle);
    }

    // Metrics reporter
    let router_metrics = Arc::clone(&router);
    let lm = Arc::clone(&latency_monitor);
    task::spawn(async move {
        loop {
            sleep(Duration::from_secs(2)).await;

            let route_stats = router_metrics.snapshot_metrics();
            let latency_stats = lm.snapshot();

            println!("=== ROUTE METRICS ===");
            println!("{}", serde_json::to_string_pretty(&route_stats).unwrap());

            println!("=== LATENCY METRICS ===");
            println!("{}", serde_json::to_string_pretty(&latency_stats).unwrap());
        }
    });

    // Publishers
    let publisher_count = 4;
    let messages_per_publisher = 500_000u64;

    let mut publishers = Vec::new();
    for p in 0..publisher_count {
        let r = Arc::clone(&router);

        let handle = task::spawn(async move {
            for i in 0..messages_per_publisher {
                let payload = Bytes::from_static(b"{\"symbol\":\"AAPL\",\"price\":189.42}");
                let msg = Message::new("orders", payload, p as u64 * messages_per_publisher + i);

                if let Err(_e) = r.publish(msg) {
                    // backpressure / ingress closed
                }
            }
        });

        publishers.push(handle);
    }

    for p in publishers {
        let _ = p.await;
    }

    sleep(Duration::from_secs(5)).await;
    router.shutdown();

    for h in subscriber_handles {
        h.abort();
    }
}
```

