## 3. Latency monitor

This tracks:

- total messages processed
- average latency
- max latency

For production, replace with HDR Histogram or Micrometer/Prometheus.

```java
package hfmessaging;

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public final class LatencyMonitor {
    private final LongAdder processed = new LongAdder();
    private final LongAdder totalLatencyNanos = new LongAdder();
    private final AtomicLong maxLatencyNanos = new AtomicLong();

    public void record(long latencyNanos) {
        processed.increment();
        totalLatencyNanos.add(latencyNanos);

        long prev;
        do {
            prev = maxLatencyNanos.get();
            if (latencyNanos <= prev) {
                break;
            }
        } while (!maxLatencyNanos.compareAndSet(prev, latencyNanos));
    }

    public long getProcessed() {
        return processed.sum();
    }

    public long getAverageLatencyNanos() {
        long count = processed.sum();
        return count == 0 ? 0 : totalLatencyNanos.sum() / count;
    }

    public long getMaxLatencyNanos() {
        return maxLatencyNanos.get();
    }

    public String snapshot() {
        return "processed=" + getProcessed()
                + ", avgLatencyMicros=" + (getAverageLatencyNanos() / 1_000.0)
                + ", maxLatencyMicros=" + (getMaxLatencyNanos() / 1_000.0);
    }
}
```

