## 5. Partition worker

Each partition has:

- a bounded queue
- a dedicated worker thread
- fanout to topic subscribers
- latency measurement

```java
package hfmessaging;

import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.AtomicBoolean;

public final class PartitionWorker implements Runnable {
    private final int partitionId;
    private final BlockingQueue<Message> queue;
    private final TopicRegistry topicRegistry;
    private final LatencyMonitor latencyMonitor;
    private final AtomicBoolean running = new AtomicBoolean(true);
    private final Thread thread;

    public PartitionWorker(
            int partitionId,
            int queueCapacity,
            TopicRegistry topicRegistry,
            LatencyMonitor latencyMonitor) {
        this.partitionId = partitionId;
        this.queue = new ArrayBlockingQueue<>(queueCapacity);
        this.topicRegistry = topicRegistry;
        this.latencyMonitor = latencyMonitor;
        this.thread = new Thread(this, "partition-worker-" + partitionId);
    }

    public void start() {
        thread.start();
    }

    public boolean publish(Message message) {
        return queue.offer(message);
    }

    public void shutdown() {
        running.set(false);
        thread.interrupt();
    }

    @Override
    public void run() {
        while (running.get()) {
            try {
                Message message = queue.take();
                long now = System.nanoTime();
                latencyMonitor.record(now - message.getCreatedAtNanos());

                List<Subscriber> subscribers = topicRegistry.getSubscribers(message.getTopic());
                for (Subscriber subscriber : subscribers) {
                    try {
                        subscriber.onMessage(message);
                    } catch (Exception e) {
                        System.err.println("Subscriber error on partition " + partitionId + ": " + e.getMessage());
                    }
                }
            } catch (InterruptedException e) {
                if (!running.get()) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }
    }
}
```

