## 6. Router

Routes by key hash to preserve ordering per key.

```java
package hfmessaging;

import java.util.ArrayList;
import java.util.List;

public final class MessageRouter {
    private final List<PartitionWorker> partitions;
    private final int partitionCount;

    public MessageRouter(int partitionCount, int queueCapacityPerPartition,
                         TopicRegistry topicRegistry, LatencyMonitor latencyMonitor) {
        this.partitionCount = partitionCount;
        this.partitions = new ArrayList<>(partitionCount);

        for (int i = 0; i < partitionCount; i++) {
            partitions.add(new PartitionWorker(i, queueCapacityPerPartition, topicRegistry, latencyMonitor));
        }
    }

    public void start() {
        for (PartitionWorker partition : partitions) {
            partition.start();
        }
    }

    public boolean publish(Message message) {
        int partition = partitionFor(message.getKey());
        return partitions.get(partition).publish(message);
    }

    private int partitionFor(String key) {
        int h = key == null ? 0 : key.hashCode();
        return (h & Integer.MAX_VALUE) % partitionCount;
    }

    public void shutdown() {
        for (PartitionWorker partition : partitions) {
            partition.shutdown();
        }
    }
}
```

