## 7. Messaging system facade

```java
package hfmessaging;

import java.util.concurrent.atomic.AtomicLong;

public final class MessagingSystem {
    private final TopicRegistry topicRegistry = new TopicRegistry();
    private final LatencyMonitor latencyMonitor = new LatencyMonitor();
    private final MessageRouter router;
    private final AtomicLong messageIdGenerator = new AtomicLong();

    public MessagingSystem(int partitions, int queueCapacityPerPartition) {
        this.router = new MessageRouter(
                partitions,
                queueCapacityPerPartition,
                topicRegistry,
                latencyMonitor
        );
    }

    public void start() {
        router.start();
    }

    public void subscribe(String topic, Subscriber subscriber) {
        topicRegistry.subscribe(topic, subscriber);
    }

    public boolean publish(String topic, String key, byte[] payload) {
        long id = messageIdGenerator.incrementAndGet();
        Message message = new Message(id, topic, key, payload);
        return router.publish(message);
    }

    public String metrics() {
        return latencyMonitor.snapshot();
    }

    public void shutdown() {
        router.shutdown();
    }
}
```

