## 8. Example usage

```java
package hfmessaging;

import java.nio.charset.StandardCharsets;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class Main {
    public static void main(String[] args) throws Exception {
        MessagingSystem system = new MessagingSystem(
                Runtime.getRuntime().availableProcessors(),
                100_000
        );

        system.subscribe("orders", message -> {
            // Simulate fast processing
            byte[] payload = message.getPayload();
            if (payload.length == 0) {
                throw new IllegalStateException("empty payload");
            }
        });

        system.subscribe("orders", message -> {
            // Another subscriber
            String body = new String(message.getPayload(), StandardCharsets.UTF_8);
            if (body.startsWith("bad")) {
                // no-op
            }
        });

        system.start();

        ScheduledExecutorService metricsPrinter = Executors.newSingleThreadScheduledExecutor();
        metricsPrinter.scheduleAtFixedRate(() -> {
            System.out.println(system.metrics());
        }, 1, 1, TimeUnit.SECONDS);

        int producerThreads = 4;
        var producerPool = Executors.newFixedThreadPool(producerThreads);

        for (int t = 0; t < producerThreads; t++) {
            final int threadNum = t;
            producerPool.submit(() -> {
                long i = 0;
                while (true) {
                    String key = "account-" + (i % 10_000);
                    String payload = "order-" + threadNum + "-" + i;
                    boolean accepted = system.publish(
                            "orders",
                            key,
                            payload.getBytes(StandardCharsets.UTF_8)
                    );

                    if (!accepted) {
                        // Backpressure signal: queue full
                        Thread.yield();
                    }

                    i++;
                }
            });
        }

        Thread.sleep(30_000);

        producerPool.shutdownNow();
        metricsPrinter.shutdownNow();
        system.shutdown();
    }
}
```

