# `broker/metrics.go`

```go
package broker

import (
	"encoding/json"
	"net/http"
	"sync/atomic"
	"time"
)

type LatencyStats struct {
	Count uint64        `json:"count"`
	MinNs uint64        `json:"min_ns"`
	MaxNs uint64        `json:"max_ns"`
	AvgNs uint64        `json:"avg_ns"`
	P50Ns uint64        `json:"p50_ns,omitempty"`
	P95Ns uint64        `json:"p95_ns,omitempty"`
	P99Ns uint64        `json:"p99_ns,omitempty"`
	Last  time.Duration `json:"last"`
}

type Metrics struct {
	Received uint64 `json:"received"`
	Routed   uint64 `json:"routed"`
	Dropped  uint64 `json:"dropped"`

	ProcessingNsTotal uint64 `json:"processing_ns_total"`
	EndToEndNsTotal   uint64 `json:"end_to_end_ns_total"`

	ProcessingCount uint64 `json:"processing_count"`
	EndToEndCount   uint64 `json:"end_to_end_count"`

	ProcessingMinNs uint64 `json:"processing_min_ns"`
	ProcessingMaxNs uint64 `json:"processing_max_ns"`
	EndToEndMinNs   uint64 `json:"end_to_end_min_ns"`
	EndToEndMaxNs   uint64 `json:"end_to_end_max_ns"`

	LastProcessingNs uint64 `json:"last_processing_ns"`
	LastEndToEndNs   uint64 `json:"last_end_to_end_ns"`
}

func NewMetrics() *Metrics {
	return &Metrics{
		ProcessingMinNs: ^uint64(0),
		EndToEndMinNs:   ^uint64(0),
	}
}

func (m *Metrics) RecordReceived() {
	atomic.AddUint64(&m.Received, 1)
}

func (m *Metrics) RecordRouted() {
	atomic.AddUint64(&m.Routed, 1)
}

func (m *Metrics) RecordDropped() {
	atomic.AddUint64(&m.Dropped, 1)
}

func (m *Metrics) RecordProcessingLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.ProcessingNsTotal, ns)
	atomic.AddUint64(&m.ProcessingCount, 1)
	atomic.StoreUint64(&m.LastProcessingNs, ns)
	updateMin(&m.ProcessingMinNs, ns)
	updateMax(&m.ProcessingMaxNs, ns)
}

func (m *Metrics) RecordEndToEndLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.EndToEndNsTotal, ns)
	atomic.AddUint64(&m.EndToEndCount, 1)
	atomic.StoreUint64(&m.LastEndToEndNs, ns)
	updateMin(&m.EndToEndMinNs, ns)
	updateMax(&m.EndToEndMaxNs, ns)
}

func updateMin(addr *uint64, value uint64) {
	for {
		current := atomic.LoadUint64(addr)
		if value >= current {
			return
		}
		if atomic.CompareAndSwapUint64(addr, current, value) {
			return
		}
	}
}

func updateMax(addr *uint64, value uint64) {
	for {
		current := atomic.LoadUint64(addr)
		if value <= current {
			return
		}
		if atomic.CompareAndSwapUint64(addr, current, value) {
			return
		}
	}
}

type MetricsSnapshot struct {
	Received          uint64 `json:"received"`
	Routed            uint64 `json:"routed"`
	Dropped           uint64 `json:"dropped"`
	ProcessingCount   uint64 `json:"processing_count"`
	EndToEndCount     uint64 `json:"end_to_end_count"`
	ProcessingMinNs   uint64 `json:"processing_min_ns"`
	ProcessingMaxNs   uint64 `json:"processing_max_ns"`
	ProcessingAvgNs   uint64 `json:"processing_avg_ns"`
	EndToEndMinNs     uint64 `json:"end_to_end_min_ns"`
	EndToEndMaxNs     uint64 `json:"end_to_end_max_ns"`
	EndToEndAvgNs     uint64 `json:"end_to_end_avg_ns"`
	LastProcessingNs  uint64 `json:"last_processing_ns"`
	LastEndToEndNs    uint64 `json:"last_end_to_end_ns"`
	TimestampUnixNano int64  `json:"timestamp_unix_nano"`
}

func (m *Metrics) Snapshot() MetricsSnapshot {
	pc := atomic.LoadUint64(&m.ProcessingCount)
	ec := atomic.LoadUint64(&m.EndToEndCount)

	var pAvg uint64
	var eAvg uint64
	if pc > 0 {
		pAvg = atomic.LoadUint64(&m.ProcessingNsTotal) / pc
	}
	if ec > 0 {
		eAvg = atomic.LoadUint64(&m.EndToEndNsTotal) / ec
	}

	pMin := atomic.LoadUint64(&m.ProcessingMinNs)
	eMin := atomic.LoadUint64(&m.EndToEndMinNs)
	if pMin == ^uint64(0) {
		pMin = 0
	}
	if eMin == ^uint64(0) {
		eMin = 0
	}

	return MetricsSnapshot{
		Received:          atomic.LoadUint64(&m.Received),
		Routed:            atomic.LoadUint64(&m.Routed),
		Dropped:           atomic.LoadUint64(&m.Dropped),
		ProcessingCount:   pc,
		EndToEndCount:     ec,
		ProcessingMinNs:   pMin,
		ProcessingMaxNs:   atomic.LoadUint64(&m.ProcessingMaxNs),
		ProcessingAvgNs:   pAvg,
		EndToEndMinNs:     eMin,
		EndToEndMaxNs:     atomic.LoadUint64(&m.EndToEndMaxNs),
		EndToEndAvgNs:     eAvg,
		LastProcessingNs:  atomic.LoadUint64(&m.LastProcessingNs),
		LastEndToEndNs:    atomic.LoadUint64(&m.LastEndToEndNs),
		TimestampUnixNano: time.Now().UnixNano(),
	}
}

func (m *Metrics) Handler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(m.Snapshot())
	}
}
