# `broker/broker.go`

```go
package broker

import (
	"errors"
	"hash/fnv"
	"runtime"
	"sync"
	"time"
)

var ErrBrokerClosed = errors.New("broker closed")
var ErrBackpressure = errors.New("broker backpressure")

type shard struct {
	queue chan Message
}

type Broker struct {
	shards      []shard
	subscribers map[string][]Subscriber
	subMu       sync.RWMutex

	ingress chan Message
	quit    chan struct{}
	wg      sync.WaitGroup

	metrics *Metrics
}

type Config struct {
	ShardCount     int
	IngressSize    int
	ShardQueueSize int
}

func DefaultConfig() Config {
	cpus := runtime.NumCPU()
	return Config{
		ShardCount:     cpus * 2,
		IngressSize:    1 << 16,
		ShardQueueSize: 1 << 14,
	}
}

func NewBroker(cfg Config) *Broker {
	if cfg.ShardCount <= 0 {
		cfg.ShardCount = 1
	}
	if cfg.IngressSize <= 0 {
		cfg.IngressSize = 1024
	}
	if cfg.ShardQueueSize <= 0 {
		cfg.ShardQueueSize = 1024
	}

	b := &Broker{
		shards:      make([]shard, cfg.ShardCount),
		subscribers: make(map[string][]Subscriber),
		ingress:     make(chan Message, cfg.IngressSize),
		quit:        make(chan struct{}),
		metrics:     NewMetrics(),
	}

	for i := range b.shards {
		b.shards[i] = shard{
			queue: make(chan Message, cfg.ShardQueueSize),
		}
	}

	b.wg.Add(1)
	go b.runIngress()

	for i := range b.shards {
		b.wg.Add(1)
		go b.runShard(i)
	}

	return b
}

func (b *Broker) Metrics() *Metrics {
	return b.metrics
}

func (b *Broker) Publish(msg Message) error {
	select {
	case <-b.quit:
		return ErrBrokerClosed
	default:
	}

	b.metrics.RecordReceived()

	select {
	case b.ingress <- msg:
		return nil
	default:
		b.metrics.RecordDropped()
		return ErrBackpressure
	}
}

func (b *Broker) Subscribe(topic string, buffer int) Subscriber {
	if buffer <= 0 {
		buffer = 1024
	}
	sub := make(Subscriber, buffer)

	b.subMu.Lock()
	b.subscribers[topic] = append(b.subscribers[topic], sub)
	b.subMu.Unlock()

	return sub
}

func (b *Broker) Close() {
	select {
	case <-b.quit:
		return
	default:
		close(b.quit)
	}

	b.wg.Wait()

	b.subMu.Lock()
	for _, subs := range b.subscribers {
		for _, sub := range subs {
			close(sub)
		}
	}
	b.subscribers = map[string][]Subscriber{}
	b.subMu.Unlock()
}

func (b *Broker) runIngress() {
	defer b.wg.Done()

	for {
		select {
		case <-b.quit:
			return
		case msg := <-b.ingress:
			idx := b.shardFor(msg.Topic)
			select {
			case b.shards[idx].queue <- msg:
			default:
				b.metrics.RecordDropped()
			}
		}
	}
}

func (b *Broker) runShard(i int) {
	defer b.wg.Done()

	for {
		select {
		case <-b.quit:
			return
		case msg := <-b.shards[i].queue:
			start := time.Now()
			b.dispatch(msg)
			b.metrics.RecordProcessingLatency(time.Since(start))
		}
	}
}

func (b *Broker) dispatch(msg Message) {
	b.subMu.RLock()
	subs := b.subscribers[msg.Topic]
	b.subMu.RUnlock()

	if len(subs) == 0 {
		return
	}

	now := time.Now()
	for _, sub := range subs {
		select {
		case sub <- msg:
			b.metrics.RecordRouted()
			if !msg.CreatedAt.IsZero() {
				b.metrics.RecordEndToEndLatency(now.Sub(msg.CreatedAt))
			}
		default:
			b.metrics.RecordDropped()
		}
	}
}

func (b *Broker) shardFor(topic string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return int(h.Sum32()) % len(b.shards)
}
