# `main.go`

```go
package main

import (
	"fmt"
	"log"
	"net/http"
	"sync/atomic"
	"time"

	"hfmsg/broker"
)

func main() {
	cfg := broker.Config{
		ShardCount:     16,
		IngressSize:    1 << 18,
		ShardQueueSize: 1 << 16,
	}

	b := broker.NewBroker(cfg)
	defer b.Close()

	subOrders := b.Subscribe("orders", 1<<14)
	subTrades := b.Subscribe("trades", 1<<14)

	go consume("orders", subOrders)
	go consume("trades", subTrades)

	http.Handle("/metrics", b.Metrics().Handler())
	go func() {
		log.Println("metrics server listening on :8080")
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()

	var id uint64

	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	go func() {
		for range ticker.C {
			s := b.Metrics().Snapshot()
			fmt.Printf(
				"received=%d routed=%d dropped=%d proc_avg=%dns e2e_avg=%dns\n",
				s.Received, s.Routed, s.Dropped, s.ProcessingAvgNs, s.EndToEndAvgNs,
			)
		}
	}()

	topics := []string{"orders", "trades"}
	payload := make([]byte, 256)

	for {
		for _, topic := range topics {
			msg := broker.Message{
				ID:        atomic.AddUint64(&id, 1),
				Topic:     topic,
				Payload:   payload,
				CreatedAt: time.Now(),
			}
			_ = b.Publish(msg)
		}
	}
}

func consume(name string, sub broker.Subscriber) {
	var count uint64
	start := time.Now()

	for range sub {
		n := atomic.AddUint64(&count, 1)
		if n%1_000_000 == 0 {
			elapsed := time.Since(start).Seconds()
			fmt.Printf("%s consumed=%d rate=%.2f msg/sec\n", name, n, float64(n)/elapsed)
		}
	}
}
