```go
package router

import (
	"errors"
	"hash/fnv"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Handler func(Message)

type shard struct {
	ch chan Message
}

type Router struct {
	shards      []shard
	handler     Handler
	dropped     atomic.Uint64
	processed   atomic.Uint64
	enqueued    atomic.Uint64
	inflight    atomic.Int64
	latencyHist *LatencyCollector
}

type Config struct {
	ShardCount      int
	BufferPerShard  int
	Handler         Handler
	LatencyBuckets  []time.Duration
}

func NewRouter(cfg Config) (*Router, error) {
	if cfg.ShardCount <= 0 {
		return nil, errors.New("ShardCount must be > 0")
	}
	if cfg.BufferPerShard <= 0 {
		return nil, errors.New("BufferPerShard must be > 0")
	}
	if cfg.Handler == nil {
		return nil, errors.New("Handler is required")
	}
	if len(cfg.LatencyBuckets) == 0 {
		cfg.LatencyBuckets = DefaultLatencyBuckets()
	}

	r := &Router{
		shards:      make([]shard, cfg.ShardCount),
		handler:     cfg.Handler,
		latencyHist: NewLatencyCollector(cfg.LatencyBuckets),
	}

	for i := 0; i < cfg.ShardCount; i++ {
		r.shards[i] = shard{
			ch: make(chan Message, cfg.BufferPerShard),
		}
		go r.runShard(r.shards[i])
	}

	return r, nil
}

func (r *Router) runShard(s shard) {
	for msg := range s.ch {
		start := time.Now()

		r.handler(msg)

		r.processed.Add(1)
		r.inflight.Add(-1)

		created := time.Unix(0, msg.CreatedAt)
		e2e := time.Since(created)
		proc := time.Since(start)

		r.latencyHist.ObserveE2E(e2e)
		r.latencyHist.ObserveProc(proc)
	}
}

func (r *Router) Route(msg Message) bool {
	if msg.CreatedAt == 0 {
		msg.CreatedAt = time.Now().UnixNano()
	}

	idx := int(hash(msg.Key) % uint32(len(r.shards)))
	r.inflight.Add(1)

	select {
	case r.shards[idx].ch <- msg:
		r.enqueued.Add(1)
		return true
	default:
		r.inflight.Add(-1)
		r.dropped.Add(1)
		return false
	}
}

func (r *Router) Stats() StatsSnapshot {
	return StatsSnapshot{
		Enqueued:  r.enqueued.Load(),
		Processed: r.processed.Load(),
		Dropped:   r.dropped.Load(),
		Inflight:  r.inflight.Load(),
		Latency:   r.latencyHist.Snapshot(),
	}
}

func hash(s string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(s))
	return h.Sum32()
}
