```go
package router

import (
	"sort"
	"sync"
	"time"
)

type LatencySnapshot struct {
	E2E  Percentiles `json:"e2e"`
	Proc Percentiles `json:"proc"`
}

type Percentiles struct {
	Count int64         `json:"count"`
	P50   time.Duration `json:"p50"`
	P90   time.Duration `json:"p90"`
	P95   time.Duration `json:"p95"`
	P99   time.Duration `json:"p99"`
	Max   time.Duration `json:"max"`
}

type LatencyCollector struct {
	mu      sync.Mutex
	e2eVals []int64
	procVals []int64
}

func NewLatencyCollector(_ []time.Duration) *LatencyCollector {
	return &LatencyCollector{
		e2eVals:  make([]int64, 0, 4096),
		procVals: make([]int64, 0, 4096),
	}
}

func DefaultLatencyBuckets() []time.Duration {
	return []time.Duration{
		10 * time.Microsecond,
		50 * time.Microsecond,
		100 * time.Microsecond,
		250 * time.Microsecond,
		500 * time.Microsecond,
		1 * time.Millisecond,
		2 * time.Millisecond,
		5 * time.Millisecond,
		10 * time.Millisecond,
		25 * time.Millisecond,
		50 * time.Millisecond,
		100 * time.Millisecond,
		250 * time.Millisecond,
		500 * time.Millisecond,
		1 * time.Second,
	}
}

func (l *LatencyCollector) ObserveE2E(d time.Duration) {
	l.mu.Lock()
	l.e2eVals = append(l.e2eVals, int64(d))
	l.mu.Unlock()
}

func (l *LatencyCollector) ObserveProc(d time.Duration) {
	l.mu.Lock()
	l.procVals = append(l.procVals, int64(d))
	l.mu.Unlock()
}

func (l *LatencyCollector) Snapshot() LatencySnapshot {
	l.mu.Lock()
	defer l.mu.Unlock()

	e2e := computePercentiles(l.e2eVals)
	proc := computePercentiles(l.procVals)

	// reset after snapshot for rolling window behavior
	l.e2eVals = l.e2eVals[:0]
	l.procVals = l.procVals[:0]

	return LatencySnapshot{
		E2E:  e2e,
		Proc: proc,
	}
}

func computePercentiles(vals []int64) Percentiles {
	if len(vals) == 0 {
		return Percentiles{}
	}

	cp := make([]int64, len(vals))
	copy(cp, vals)
	sort.Slice(cp, func(i, j int) bool { return cp[i] < cp[j] })

	return Percentiles{
		Count: int64(len(cp)),
		P50:   time.Duration(percentile(cp, 0.50)),
		P90:   time.Duration(percentile(cp, 0.90)),
		P95:   time.Duration(percentile(cp, 0.95)),
		P99:   time.Duration(percentile(cp, 0.99)),
		Max:   time.Duration(cp[len(cp)-1]),
	}
}

func percentile(sorted []int64, p float64) int64 {
	if len(sorted) == 0 {
		return 0
	}
	idx := int(float64(len(sorted)-1) * p)
	return sorted[idx]
}
