package router

import (
	"encoding/json"
	"net/http"
	"sync/atomic"
	"time"
)

type latencyStats struct {
	count uint64
	total uint64 // nanoseconds
	max   uint64 // nanoseconds
}

func (l *latencyStats) record(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&l.count, 1)
	atomic.AddUint64(&l.total, ns)

	for {
		cur := atomic.LoadUint64(&l.max)
		if ns <= cur {
			return
		}
		if atomic.CompareAndSwapUint64(&l.max, cur, ns) {
			return
		}
	}
}

func (l *latencyStats) snapshot() map[string]interface{} {
	count := atomic.LoadUint64(&l.count)
	total := atomic.LoadUint64(&l.total)
	max := atomic.LoadUint64(&l.max)

	avg := uint64(0)
	if count > 0 {
		avg = total / count
	}

	return map[string]interface{}{
		"count":  count,
		"avg_ns": avg,
		"max_ns": max,
	}
}

type Metrics struct {
	Published         uint64
	Routed            uint64
	Dropped           uint64
	SubscriberCalls   uint64
	QueueLatency      latencyStats
	ProcessingLatency latencyStats
}

func (m *Metrics) IncPublished() {
	atomic.AddUint64(&m.Published, 1)
}

func (m *Metrics) IncRouted() {
	atomic.AddUint64(&m.Routed, 1)
}

func (m *Metrics) IncDropped() {
	atomic.AddUint64(&m.Dropped, 1)
}

func (m *Metrics) IncSubscriberCalls() {
	atomic.AddUint64(&m.SubscriberCalls, 1)
}

func (m *Metrics) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	resp := map[string]interface{}{
		"published":          atomic.LoadUint64(&m.Published),
		"routed":             atomic.LoadUint64(&m.Routed),
		"dropped":            atomic.LoadUint64(&m.Dropped),
		"subscriber_calls":   atomic.LoadUint64(&m.SubscriberCalls),
		"queue_latency":      m.QueueLatency.snapshot(),
		"processing_latency": m.ProcessingLatency.snapshot(),
		"timestamp":          time.Now().UTC(),
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}
