# `router/router.go`

```go
package router

import (
	"errors"
	"hash/fnv"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

var ErrRouterClosed = errors.New("router is closed")
var ErrQueueFull = errors.New("router queue full")

type subscriber struct {
	handler Handler
}

type shard struct {
	queue chan Message
}

type Router struct {
	shards      []shard
	subscribers map[string][]subscriber
	subMu       sync.RWMutex

	metrics *Metrics

	closed uint32
	wg     sync.WaitGroup
	nextID uint64
}

type Config struct {
	ShardCount int
	QueueSize  int
}

func DefaultConfig() Config {
	return Config{
		ShardCount: runtime.NumCPU() * 2,
		QueueSize:  65536,
	}
}

func NewRouter(cfg Config) *Router {
	if cfg.ShardCount <= 0 {
		cfg.ShardCount = runtime.NumCPU() * 2
	}
	if cfg.QueueSize <= 0 {
		cfg.QueueSize = 65536
	}

	r := &Router{
		shards:      make([]shard, cfg.ShardCount),
		subscribers: make(map[string][]subscriber),
		metrics:     &Metrics{},
	}

	for i := range r.shards {
		r.shards[i] = shard{
			queue: make(chan Message, cfg.QueueSize),
		}
		r.wg.Add(1)
		go r.runShard(i)
	}

	return r
}

func (r *Router) Metrics() *Metrics {
	return r.metrics
}

func (r *Router) Subscribe(topic string, h Handler) {
	r.subMu.Lock()
	defer r.subMu.Unlock()
	r.subscribers[topic] = append(r.subscribers[topic], subscriber{handler: h})
}

func (r *Router) Publish(topic, key string, payload []byte) error {
	if atomic.LoadUint32(&r.closed) == 1 {
		return ErrRouterClosed
	}

	msg := Message{
		ID:        atomic.AddUint64(&r.nextID, 1),
		Topic:     topic,
		Key:       key,
		Payload:   payload,
		CreatedAt: time.Now(),
	}

	r.metrics.IncPublished()

	idx := r.shardIndex(topic, key)
	select {
	case r.shards[idx].queue <- msg:
		return nil
	default:
		r.metrics.IncDropped()
		return ErrQueueFull
	}
}

func (r *Router) shardIndex(topic, key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	_, _ = h.Write([]byte{':'})
	_, _ = h.Write([]byte(key))
	return int(h.Sum32() % uint32(len(r.shards)))
}

func (r *Router) runShard(i int) {
	defer r.wg.Done()

	for msg := range r.shards[i].queue {
		queueDelay := time.Since(msg.CreatedAt)
		r.metrics.QueueLatency.record(queueDelay)

		r.subMu.RLock()
		subs := r.subscribers[msg.Topic]
		r.subMu.RUnlock()

		start := time.Now()
		for _, sub := range subs {
			sub.handler(msg)
			r.metrics.IncSubscriberCalls()
		}
		r.metrics.ProcessingLatency.record(time.Since(start))
		r.metrics.IncRouted()
	}
}

func (r *Router) Close() {
	if !atomic.CompareAndSwapUint32(&r.closed, 0, 1) {
		return
	}

	for i := range r.shards {
		close(r.shards[i].queue)
	}
	r.wg.Wait()
}
