		ShardCount: 16,
		QueueSize:  131072,
	})
	defer r.Close()

	r.Subscribe("bench", func(m Message) {})

	payload := []byte("payload")

	b.ResetTimer()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			_ = r.Publish("bench", "key", payload)
		}
	})
}
