package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"runtime"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID          uint64
	Topic       string
	Payload     []byte
	CreatedAtNs int64 // producer timestamp
}

type DeliveredMessage struct {
	Message
	RoutedAtNs    int64
	DeliveredAtNs int64
}

type Subscriber struct {
	ID      string
	Topic   string
	Ch      chan DeliveredMessage
	Dropped atomic.Uint64
}

type TopicStats struct {
	Published atomic.Uint64
	Routed    atomic.Uint64
	Dropped   atomic.Uint64
}

type LatencyStats struct {
	count        atomic.Uint64
	totalNs      atomic.Uint64
	maxNs        atomic.Uint64
	lastNs       atomic.Uint64
	routingCount atomic.Uint64
	routingTotal atomic.Uint64
	routingMax   atomic.Uint64
}

func (l *LatencyStats) RecordEndToEnd(ns uint64) {
	l.count.Add(1)
	l.totalNs.Add(ns)
	l.lastNs.Store(ns)
	for {
		cur := l.maxNs.Load()
		if ns <= cur {
			break
		}
		if l.maxNs.CompareAndSwap(cur, ns) {
			break
		}
	}
}

func (l *LatencyStats) RecordRouting(ns uint64) {
	l.routingCount.Add(1)
	l.routingTotal.Add(ns)
	for {
		cur := l.routingMax.Load()
		if ns <= cur {
			break
		}
		if l.routingMax.CompareAndSwap(cur, ns) {
			break
		}
	}
}

type Broker struct {
	topics sync.Map // map[string]*topicSubscribers

	publishCh chan Message
	workers   int

	totalPublished atomic.Uint64
	totalRouted    atomic.Uint64
	totalDropped   atomic.Uint64

	latency LatencyStats
	perTopic sync.Map // map[string]*TopicStats
}

type topicSubscribers struct {
	mu   sync.RWMutex
	subs map[string]*Subscriber
}

func newTopicSubscribers() *topicSubscribers {
	return &topicSubscribers{
		subs: make(map[string]*Subscriber),
	}
}

func NewBroker(workers int, queueSize int) *Broker {
	if workers <= 0 {
		workers = runtime.NumCPU()
	}
	if queueSize <= 0 {
		queueSize = 1 << 16
	}

	b := &Broker{
		publishCh: make(chan Message, queueSize),
		workers:   workers,
	}

	for i := 0; i < workers; i++ {
		go b.worker(i)
	}

	return b
}

func (b *Broker) getTopicStats(topic string) *TopicStats {
	if v, ok := b.perTopic.Load(topic); ok {
		return v.(*TopicStats)
	}
	stats := &TopicStats{}
	actual, _ := b.perTopic.LoadOrStore(topic, stats)
	return actual.(*TopicStats)
}

func (b *Broker) Subscribe(topic, subscriberID string, buffer int) *Subscriber {
	if buffer <= 0 {
		buffer = 1024
	}

	sub := &Subscriber{
		ID:    subscriberID,
		Topic: topic,
		Ch:    make(chan DeliveredMessage, buffer),
	}

	v, _ := b.topics.LoadOrStore(topic, newTopicSubscribers())
	ts := v.(*topicSubscribers)

	ts.mu.Lock()
	ts.subs[subscriberID] = sub
	ts.mu.Unlock()

	return sub
}

func (b *Broker) Unsubscribe(topic, subscriberID string) {
	v, ok := b.topics.Load(topic)
	if !ok {
		return
	}
	ts := v.(*topicSubscribers)

	ts.mu.Lock()
	sub, exists := ts.subs[subscriberID]
	if exists {
		delete(ts.subs, subscriberID)
		close(sub.Ch)
	}
	ts.mu.Unlock()
}

func (b *Broker) Publish(msg Message) bool {
	if msg.CreatedAtNs == 0 {
		msg.CreatedAtNs = time.Now().UnixNano()
	}

	select {
	case b.publishCh <- msg:
		b.totalPublished.Add(1)
		b.getTopicStats(msg.Topic).Published.Add(1)
		return true
	default:
		b.totalDropped.Add(1)
		b.getTopicStats(msg.Topic).Dropped.Add(1)
		return false
	}
}

func (b *Broker) worker(workerID int) {
	for msg := range b.publishCh {
		start := time.Now().UnixNano()

		v, ok := b.topics.Load(msg.Topic)
		if !ok {
			b.latency.RecordRouting(uint64(time.Now().UnixNano() - start))
			continue
		}

		ts := v.(*topicSubscribers)

		ts.mu.RLock()
		for _, sub := range ts.subs {
			delivered := DeliveredMessage{
				Message:       msg,
				RoutedAtNs:    time.Now().UnixNano(),
				DeliveredAtNs: 0,
			}

			select {
			case sub.Ch <- delivered:
				b.totalRouted.Add(1)
				b.getTopicStats(msg.Topic).Routed.Add(1)
			default:
				sub.Dropped.Add(1)
				b.totalDropped.Add(1)
				b.getTopicStats(msg.Topic).Dropped.Add(1)
			}
		}
		ts.mu.RUnlock()

		b.latency.RecordRouting(uint64(time.Now().UnixNano() - start))
	}
}

type MetricsSnapshot struct {
	TotalPublished uint64                  `json:"total_published"`
	TotalRouted    uint64                  `json:"total_routed"`
	TotalDropped   uint64                  `json:"total_dropped"`
	EndToEnd       LatencySnapshot         `json:"end_to_end_latency"`
	Routing        RoutingLatencySnapshot  `json:"routing_latency"`
	Topics         map[string]TopicMetrics `json:"topics"`
}

type LatencySnapshot struct {
	Count   uint64  `json:"count"`
	AvgMs   float64 `json:"avg_ms"`
	MaxMs   float64 `json:"max_ms"`
	LastMs  float64 `json:"last_ms"`
}

type RoutingLatencySnapshot struct {
	Count uint64  `json:"count"`
	AvgMs float64 `json:"avg_ms"`
	MaxMs float64 `json:"max_ms"`
}

type TopicMetrics struct {
	Published uint64 `json:"published"`
	Routed    uint64 `json:"routed"`
	Dropped   uint64 `json:"dropped"`
}

func (b *Broker) SnapshotMetrics() MetricsSnapshot {
	topics := make(map[string]TopicMetrics)

	b.perTopic.Range(func(key, value any) bool {
		topic := key.(string)
		stats := value.(*TopicStats)
		topics[topic] = TopicMetrics{
			Published: stats.Published.Load(),
			Routed:    stats.Routed.Load(),
			Dropped:   stats.Dropped.Load(),
		}
		return true
	})

	count := b.latency.count.Load()
	total := b.latency.totalNs.Load()
	last := b.latency.lastNs.Load()
	max := b.latency.maxNs.Load()

	rcount := b.latency.routingCount.Load()
	rtotal := b.latency.routingTotal.Load()
	rmax := b.latency.routingMax.Load()

	var avgMs float64
	if count > 0 {
		avgMs = float64(total) / float64(count) / 1e6
	}

	var routingAvgMs float64
	if rcount > 0 {
		routingAvgMs = float64(rtotal) / float64(rcount) / 1e6
	}

	return MetricsSnapshot{
		TotalPublished: b.totalPublished.Load(),
		TotalRouted:    b.totalRouted.Load(),
		TotalDropped:   b.totalDropped.Load(),
		EndToEnd: LatencySnapshot{
			Count:  count,
			AvgMs:  avgMs,
			MaxMs:  float64(max) / 1e6,
			LastMs: float64(last) / 1e6,
		},
		Routing: RoutingLatencySnapshot{
			Count: rcount,
			AvgMs: routingAvgMs,
			MaxMs: float64(rmax) / 1e6,
		},
		Topics: topics,
	}
}

func (b *Broker) StartMetricsServer(addr string) {
	http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
		snapshot := b.SnapshotMetrics()

		// stable ordering for readability if needed externally
		orderedTopics := make([]string, 0, len(snapshot.Topics))
		for t := range snapshot.Topics {
			orderedTopics = append(orderedTopics, t)
		}
		sort.Strings(orderedTopics)

		type orderedResponse struct {
			TotalPublished uint64                  `json:"total_published"`
			TotalRouted    uint64                  `json:"total_routed"`
			TotalDropped   uint64                  `json:"total_dropped"`
			EndToEnd       LatencySnapshot         `json:"end_to_end_latency"`
			Routing        RoutingLatencySnapshot  `json:"routing_latency"`
			Topics         map[string]TopicMetrics `json:"topics"`
		}

		resp := orderedResponse{
			TotalPublished: snapshot.TotalPublished,
			TotalRouted:    snapshot.TotalRouted,
			TotalDropped:   snapshot.TotalDropped,
			EndToEnd:       snapshot.EndToEnd,
			Routing:        snapshot.Routing,
			Topics:         snapshot.Topics,
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	})

	go func() {
		log.Printf("metrics server listening on %s", addr)
		if err := http.ListenAndServe(addr, nil); err != nil {
			log.Fatalf("metrics server failed: %v", err)
		}
	}()
}

func consumeSubscriber(sub *Subscriber, broker *Broker) {
	for msg := range sub.Ch {
		now := time.Now().UnixNano()
		msg.DeliveredAtNs = now
		e2e := uint64(now - msg.CreatedAtNs)
		broker.latency.RecordEndToEnd(e2e)
	}
}

func main() {
	broker := NewBroker(runtime.NumCPU(), 1<<20)
	broker.StartMetricsServer(":8080")

	sub1 := broker.Subscribe("orders", "risk-engine", 1<<14)
	sub2 := broker.Subscribe("orders", "matching-engine", 1<<14)
	sub3 := broker.Subscribe("prices", "analytics", 1<<14)

	go consumeSubscriber(sub1, broker)
	go consumeSubscriber(sub2, broker)
	go consumeSubscriber(sub3, broker)

	go func() {
		var id uint64
		ticker := time.NewTicker(time.Microsecond)
		defer ticker.Stop()

		for range ticker.C {
			id++
			ok := broker.Publish(Message{
				ID:      id,
				Topic:   "orders",
				Payload: []byte(fmt.Sprintf(`{"order_id":%d,"side":"buy","qty":100}`, id)),
			})
			if !ok {
				// backpressure/drop occurred
			}
