use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    created_at: Instant,
    payload: u64,
}

struct Metrics {
    processed: AtomicU64,
    histogram: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            processed: AtomicU64::new(0),
            histogram: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record(&self, latency_micros: u64) {
        self.processed.fetch_add(1, Ordering::Relaxed);
        if let Ok(mut hist) = self.histogram.lock() {
            let _ = hist.record(latency_micros);
        }
    }

    fn snapshot(&self) -> (u64, u64, u64, u64) {
        let hist = self.histogram.lock().unwrap();
        (
            hist.value_at_quantile(0.50),
            hist.value_at_quantile(0.95),
            hist.value_at_quantile(0.99),
            hist.mean() as u64,
        )
    }
}

fn producer(tx: Sender<Message>, producer_id: u64, count: u64) {
    for i in 0..count {
        let msg = Message {
            id: producer_id * 1_000_000_000 + i,
            created_at: Instant::now(),
            payload: i,
        };

        if tx.send(msg).is_err() {
            break;
        }
    }
}

fn worker(rx: Receiver<Message>, metrics: Arc<Metrics>) {
    while let Ok(msg) = rx.recv() {
        let _routed = msg.payload.wrapping_mul(2);

        let latency = msg.created_at.elapsed().as_micros() as u64;
        metrics.record(latency);
    }
}

fn main() {
    let producer_threads = 4;
    let worker_threads = 4;
    let messages_per_producer = 1_000_000;
    let queue_size = 1_000_000;

    let (tx, rx) = bounded::<Message>(queue_size);
    let metrics = Arc::new(Metrics::new());

    let start = Instant::now();

    let mut workers = Vec::new();
    for _ in 0..worker_threads {
        let rx_clone = rx.clone();
        let metrics_clone = Arc::clone(&metrics);
        workers.push(thread::spawn(move || {
            worker(rx_clone, metrics_clone);
        }));
    }

    let reporter_metrics = Arc::clone(&metrics);
    let reporter_start = start;
    let reporter = thread::spawn(move || {
        let mut last_count = 0;
        loop {
            thread::sleep(Duration::from_secs(1));
            let total = reporter_metrics.processed.load(Ordering::Relaxed);
            let delta = total - last_count;
            last_count = total;

            let (p50, p95, p99, avg) = reporter_metrics.snapshot();
            println!(
                "elapsed={:?} total={} rate={}/s latency_us: avg={} p50={} p95={} p99={}",
                reporter_start.elapsed(),
                total,
                delta,
                avg,
                p50,
                p95,
                p99
            );

            if total >= (producer_threads * messages_per_producer) as u64 {
                break;
            }
        }
    });

    let mut producers = Vec::new();
    for p in 0..producer_threads {
        let tx_clone = tx.clone();
        producers.push(thread::spawn(move || {
            producer(tx_clone, p as u64, messages_per_producer);
        }));
    }

    drop(tx);

    for p in producers {
        p.join().unwrap();
    }

    for w in workers {
        w.join().unwrap();
    }

    reporter.join().unwrap();

    let elapsed = start.elapsed().as_secs_f64();
    let total = metrics.processed.load(Ordering::Relaxed);
    let (p50, p95, p99, avg) = metrics.snapshot();

    println!("\nFinal Results");
    println!("Total messages: {}", total);
    println!("Elapsed: {:.3}s", elapsed);
    println!("Throughput: {:.0} msg/s", total as f64 / elapsed);
    println!(
        "Latency (us): avg={} p50={} p95={} p99={}",
        avg, p50, p95, p99
    );
}
