```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"runtime"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Subscriber chan Message

type Broker struct {
	topics sync.Map // map[string]*topicSubs

	published uint64
	delivered uint64
	dropped   uint64

	latencyRecorder *LatencyRecorder
}

type topicSubs struct {
	subs atomic.Value // stores []Subscriber
}

func newTopicSubs() *topicSubs {
	t := &topicSubs{}
	t.subs.Store([]Subscriber{})
	return t
}

func (t *topicSubs) add(sub Subscriber) {
	current := t.subs.Load().([]Subscriber)
	next := make([]Subscriber, 0, len(current)+1)
	next = append(next, current...)
	next = append(next, sub)
	t.subs.Store(next)
}

func (t *topicSubs) list() []Subscriber {
	return t.subs.Load().([]Subscriber)
}

func NewBroker() *Broker {
	return &Broker{
		latencyRecorder: NewLatencyRecorder(100000),
	}
}

func (b *Broker) getOrCreateTopic(topic string) *topicSubs {
	if v, ok := b.topics.Load(topic); ok {
		return v.(*topicSubs)
	}
	t := newTopicSubs()
	actual, _ := b.topics.LoadOrStore(topic, t)
	return actual.(*topicSubs)
}

func (b *Broker) Subscribe(topic string, buffer int) Subscriber {
	sub := make(Subscriber, buffer)
	b.getOrCreateTopic(topic).add(sub)
	return sub
}

func (b *Broker) Publish(msg Message) {
	atomic.AddUint64(&b.published, 1)

	v, ok := b.topics.Load(msg.Topic)
	if !ok {
		return
	}

	subs := v.(*topicSubs).list()
	now := time.Now().UnixNano()

	for _, sub := range subs {
		select {
		case sub <- msg:
			atomic.AddUint64(&b.delivered, 1)
			latencyMicros := (now - msg.CreatedAt) / 1000
			b.latencyRecorder.Record(latencyMicros)
		default:
			atomic.AddUint64(&b.dropped, 1)
		}
	}
}

type LatencyRecorder struct {
	mu      sync.Mutex
	samples []int64
	maxSize int
	index   int
	full    bool
}

func NewLatencyRecorder(maxSize int) *LatencyRecorder {
	return &LatencyRecorder{
		samples: make([]int64, maxSize),
		maxSize: maxSize,
	}
}

func (lr *LatencyRecorder) Record(v int64) {
	lr.mu.Lock()
	lr.samples[lr.index] = v
	lr.index++
	if lr.index >= lr.maxSize {
		lr.index = 0
		lr.full = true
	}
	lr.mu.Unlock()
}

func (lr *LatencyRecorder) Snapshot() map[string]int64 {
	lr.mu.Lock()
	var data []int64
	if lr.full {
		data = append([]int64(nil), lr.samples...)
	} else {
		data = append([]int64(nil), lr.samples[:lr.index]...)
	}
	lr.mu.Unlock()

	if len(data) == 0 {
		return map[string]int64{}
	}

	sort.Slice(data, func(i, j int) bool { return data[i] < data[j] })

	p50 := percentile(data, 0.50)
	p95 := percentile(data, 0.95)
	p99 := percentile(data, 0.99)
	return map[string]int64{
		"p50_us": p50,
		"p95_us": p95,
		"p99_us": p99,
		"min_us": data[0],
		"max_us": data[len(data)-1],
	}
}

func percentile(data []int64, p float64) int64 {
	if len(data) == 0 {
		return 0
	}
	idx := int(float64(len(data)-1) * p)
	return data[idx]
}

type Metrics struct {
	Published uint64           `json:"published"`
	Delivered uint64           `json:"delivered"`
	Dropped   uint64           `json:"dropped"`
	Latency   map[string]int64 `json:"latency"`
}

func (b *Broker) Metrics() Metrics {
	return Metrics{
		Published: atomic.LoadUint64(&b.published),
		Delivered: atomic.LoadUint64(&b.delivered),
		Dropped:   atomic.LoadUint64(&b.dropped),
		Latency:   b.latencyRecorder.Snapshot(),
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	broker := NewBroker()

	topics := []string{"orders", "trades", "quotes"}

	// Create subscribers
	for _, topic := range topics {
		for i := 0; i < 4; i++ {
			sub := broker.Subscribe(topic, 65536)
			go func(topic string, id int, ch Subscriber) {
				for msg := range ch {
					_ = msg // simulate processing
				}
			}(topic, i, sub)
		}
	}

	// Metrics endpoint
	http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
		m := broker.Metrics()
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(m)
	})

	go func() {
		log.Println("metrics server listening on :8080")
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()

	// Throughput reporter
	go func() {
		var prev uint64
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			curr := atomic.LoadUint64(&broker.published)
			fmt.Printf("publish rate: %d msg/sec\n", curr-prev)
			prev = curr
		}
	}()

	// Publishers
	publisherCount := runtime.NumCPU() * 2
	for i := 0; i < publisherCount; i++ {
		go func(id int) {
			r := rand.New(rand.NewSource(time.Now().UnixNano() + int64(id)))
			payload := make([]byte, 128)
			for {
				msg := Message{
					Topic:     topics[r.Intn(len(topics))],
					Payload:   payload,
					CreatedAt: time.Now().UnixNano(),
				}
				broker.Publish(msg)
			}
		}(i)
	}

	select {}
}
