package main

import (
	"fmt"
	"hash/fnv"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Subscriber chan Message

type Router struct {
	shards      []chan Message
	subscribers sync.Map // map[string][]Subscriber

	published uint64
	delivered uint64
	dropped   uint64

	latencyBuckets [7]uint64 // <1us, <10us, <100us, <1ms, <10ms, <100ms, >=100ms
}

func NewRouter(numShards, shardBuffer int) *Router {
	r := &Router{
		shards: make([]chan Message, numShards),
	}
	for i := range r.shards {
		ch := make(chan Message, shardBuffer)
		r.shards[i] = ch
		go r.runShard(ch)
	}
	return r
}

func (r *Router) Subscribe(topic string, buffer int) Subscriber {
	sub := make(Subscriber, buffer)
	val, _ := r.subscribers.LoadOrStore(topic, &[]Subscriber{})
	ptr := val.(*[]Subscriber)

	// minimal locking by replacing slice under topic
	// safe enough for demo with external sync assumptions
	newSubs := append(append([]Subscriber{}, (*ptr)...), sub)
	r.subscribers.Store(topic, &newSubs)
	return sub
}

func (r *Router) Publish(topic string, payload []byte) {
	msg := Message{
		Topic:     topic,
		Payload:   payload,
		CreatedAt: time.Now().UnixNano(),
	}
	atomic.AddUint64(&r.published, 1)
	shard := r.pickShard(topic)
	select {
	case r.shards[shard] <- msg:
	default:
		atomic.AddUint64(&r.dropped, 1)
	}
}

func (r *Router) pickShard(topic string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return h.Sum32() % uint32(len(r.shards))
}

func (r *Router) runShard(ch <-chan Message) {
	for msg := range ch {
		val, ok := r.subscribers.Load(msg.Topic)
		if !ok {
			continue
		}
		subs := *(val.(*[]Subscriber))
		for _, sub := range subs {
			select {
			case sub <- msg:
				atomic.AddUint64(&r.delivered, 1)
				r.observeLatency(time.Now().UnixNano() - msg.CreatedAt)
			default:
				atomic.AddUint64(&r.dropped, 1)
			}
		}
	}
}

func (r *Router) observeLatency(ns int64) {
	switch {
	case ns < 1_000:
		atomic.AddUint64(&r.latencyBuckets[0], 1)
	case ns < 10_000:
		atomic.AddUint64(&r.latencyBuckets[1], 1)
	case ns < 100_000:
		atomic.AddUint64(&r.latencyBuckets[2], 1)
	case ns < 1_000_000:
		atomic.AddUint64(&r.latencyBuckets[3], 1)
	case ns < 10_000_000:
		atomic.AddUint64(&r.latencyBuckets[4], 1)
	case ns < 100_000_000:
		atomic.AddUint64(&r.latencyBuckets[5], 1)
	default:
		atomic.AddUint64(&r.latencyBuckets[6], 1)
	}
}

func (r *Router) PrintStats(interval time.Duration, stop <-chan struct{}) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	var lastPublished uint64
	var lastDelivered uint64
	var lastDropped uint64

	for {
		select {
		case <-ticker.C:
			pub := atomic.LoadUint64(&r.published)
			del := atomic.LoadUint64(&r.delivered)
			drop := atomic.LoadUint64(&r.dropped)

			pubRate := float64(pub-lastPublished) / interval.Seconds()
			delRate := float64(del-lastDelivered) / interval.Seconds()
			dropRate := float64(drop-lastDropped) / interval.Seconds()

			lastPublished = pub
			lastDelivered = del
			lastDropped = drop

			buckets := make([]uint64, len(r.latencyBuckets))
			for i := range r.latencyBuckets {
				buckets[i] = atomic.LoadUint64(&r.latencyBuckets[i])
			}

			fmt.Printf(
				"pub=%d (%.0f/s) del=%d (%.0f/s) drop=%d (%.0f/s) latency=%v\n",
				pub, pubRate, del, delRate, drop, dropRate, formatBuckets(buckets),
			)

		case <-stop:
			return
		}
	}
}

func formatBuckets(b []uint64) string {
	labels := []string{
		"<1us", "<10us", "<100us", "<1ms", "<10ms", "<100ms", ">=100ms",
	}
	out := ""
	for i := range b {
		if i > 0 {
			out += ", "
		}
		out += fmt.Sprintf("%s:%d", labels[i], b[i])
	}
	return out
}

func main() {
	numShards := 32
	router := NewRouter(numShards, 65536)

	topics := []string{"orders", "trades", "quotes", "risk"}

	// subscribers
	for _, topic := range topics {
		for i := 0; i < 4; i++ {
			sub := router.Subscribe(topic, 65536)
			go func(s Subscriber) {
				for range s {
					// simulate very light processing
				}
			}(sub)
		}
	}

	stop := make(chan struct{})
	go router.PrintStats(1*time.Second, stop)

	// publishers
	var wg sync.WaitGroup
	publisherCount := 2 * numShards
	payload := make([]byte, 128)

	for i := 0; i < publisherCount; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			localTopics := append([]string{}, topics...)
			sort.Strings(localTopics)

			for {
				select {
				case <-stop:
					return
				default:
					topic := localTopics[id%len(localTopics)]
					router.Publish(topic, payload)
				}
			}
		}(i)
	}

	time.Sleep(10 * time.Second)
	close(stop)
	wg.Wait()

	fmt.Println("done")
}
