```go
package main

import (
	"fmt"
	"math/rand"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     uint8
	Timestamp int64 // UnixNano
	Payload   [32]byte
}

type Consumer struct {
	id    int
	inbox chan Message
}

type Router struct {
	// One channel per topic for minimal contention.
	topics []chan Message

	// Subscribers per topic.
	subs [][]*Consumer

	// Metrics
	routedCount   atomic.Uint64
	consumedCount atomic.Uint64
	latencySumNs  atomic.Uint64
	latencyMaxNs  atomic.Uint64
}

func NewRouter(numTopics int, topicBuffer int) *Router {
	r := &Router{
		topics: make([]chan Message, numTopics),
		subs:   make([][]*Consumer, numTopics),
	}
	for i := 0; i < numTopics; i++ {
		r.topics[i] = make(chan Message, topicBuffer)
	}
	return r
}

func (r *Router) AddConsumer(topic int, c *Consumer) {
	r.subs[topic] = append(r.subs[topic], c)
}

func (r *Router) Start() {
	for topic := range r.topics {
		topicCh := r.topics[topic]
		subs := r.subs[topic]

		go func(ch <-chan Message, consumers []*Consumer) {
			for msg := range ch {
				for _, c := range consumers {
					// Non-blocking drop-on-backpressure for minimal HFT-style behavior.
					select {
					case c.inbox <- msg:
					default:
						// Drop if consumer is slow.
					}
				}
				r.routedCount.Add(1)
			}
		}(topicCh, subs)
	}
}

func (r *Router) Publish(msg Message) {
	r.topics[msg.Topic] <- msg
}

func (r *Router) RecordLatency(ns uint64) {
	r.latencySumNs.Add(ns)

	for {
		current := r.latencyMaxNs.Load()
		if ns <= current {
			return
		}
		if r.latencyMaxNs.CompareAndSwap(current, ns) {
			return
		}
	}
}

func producer(id int, r *Router, stop <-chan struct{}, numTopics int) {
	var payload [32]byte
	rng := rand.New(rand.NewSource(time.Now().UnixNano() + int64(id)))

	for {
		select {
		case <-stop:
			return
		default:
			msg := Message{
				Topic:     uint8(rng.Intn(numTopics)),
				Timestamp: time.Now().UnixNano(),
				Payload:   payload,
			}
			r.Publish(msg)
		}
	}
}

func consumer(c *Consumer, r *Router, stop <-chan struct{}) {
	for {
		select {
		case <-stop:
			return
		case msg := <-c.inbox:
			latency := uint64(time.Now().UnixNano() - msg.Timestamp)
			r.RecordLatency(latency)
			r.consumedCount.Add(1)
		}
	}
}

func monitor(r *Router, stop <-chan struct{}) {
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	var lastRouted uint64
	var lastConsumed uint64

	for {
		select {
		case <-stop:
			return
		case <-ticker.C:
			routed := r.routedCount.Load()
			consumed := r.consumedCount.Load()
			latSum := r.latencySumNs.Swap(0)
			latMax := r.latencyMaxNs.Swap(0)

			routedDelta := routed - lastRouted
			consumedDelta := consumed - lastConsumed

			lastRouted = routed
			lastConsumed = consumed

			var avgLatencyUs float64
			if consumedDelta > 0 {
				avgLatencyUs = float64(latSum) / float64(consumedDelta) / 1000.0
			}

			fmt.Printf(
				"routed/s=%d consumed/s=%d avg_latency_us=%.2f max_latency_us=%.2f total_routed=%d total_consumed=%d\n",
				routedDelta,
				consumedDelta,
				avgLatencyUs,
				float64(latMax)/1000.0,
				routed,
				consumed,
			)
		}
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	const (
		numTopics      = 8
		numProducers   = 8
		numConsumers   = 16
		topicBuffer    = 65536
		consumerBuffer = 65536
		runDuration    = 10 * time.Second
	)

	router := NewRouter(numTopics, topicBuffer)

	consumers := make([]*Consumer, 0, numConsumers)
	for i := 0; i < numConsumers; i++ {
		c := &Consumer{
			id:    i,
			inbox: make(chan Message, consumerBuffer),
		}
		consumers = append(consumers, c)

		// Simple subscription pattern: each consumer subscribes to one topic.
		topic := i % numTopics
		router.AddConsumer(topic, c)
	}

	router.Start()

	stop := make(chan struct{})
	var wg sync.WaitGroup

	for _, c := range consumers {
		wg.Add(1)
		go func(c *Consumer) {
			defer wg.Done()
			consumer(c, router, stop)
		}(c)
	}

	for i := 0; i < numProducers; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			producer(id, router, stop, numTopics)
		}(i)
	}

	wg.Add(1)
	go func() {
		defer wg.Done()
		monitor(router, stop)
	}()

	time.Sleep(runDuration)
	close(stop)

	// Give goroutines a moment to exit cleanly.
	time.Sleep(500 * time.Millisecond)
}
