package main

import (
	"fmt"
	"hash/fnv"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Consumer func(Message)

type shard struct {
	inbox chan Message
	subs  map[string][]Consumer
}

type Router struct {
	shards    []shard
	numShards uint32

	received uint64
	routed   uint64
	dropped  uint64

	latencyCount uint64
	latencySumNs uint64
	latencyMaxNs uint64

	stopCh chan struct{}
	wg     sync.WaitGroup
}

func NewRouter(numShards int, queueSize int) *Router {
	r := &Router{
		shards:    make([]shard, numShards),
		numShards: uint32(numShards),
		stopCh:    make(chan struct{}),
	}

	for i := 0; i < numShards; i++ {
		r.shards[i] = shard{
			inbox: make(chan Message, queueSize),
			subs:  make(map[string][]Consumer),
		}
	}

	return r
}

func (r *Router) shardFor(topic string) *shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	idx := h.Sum32() % r.numShards
	return &r.shards[idx]
}

func (r *Router) Subscribe(topic string, c Consumer) {
	s := r.shardFor(topic)
	s.subs[topic] = append(s.subs[topic], c)
}

func (r *Router) Publish(msg Message) bool {
	atomic.AddUint64(&r.received, 1)
	s := r.shardFor(msg.Topic)

	select {
	case s.inbox <- msg:
		return true
	default:
		atomic.AddUint64(&r.dropped, 1)
		return false
	}
}

func (r *Router) Start() {
	for i := range r.shards {
		r.wg.Add(1)
		go func(s *shard) {
			defer r.wg.Done()
			for {
				select {
				case msg := <-s.inbox:
					now := time.Now().UnixNano()
					lat := uint64(now - msg.CreatedAt)

					atomic.AddUint64(&r.routed, 1)
					atomic.AddUint64(&r.latencyCount, 1)
					atomic.AddUint64(&r.latencySumNs, lat)

					for {
						oldMax := atomic.LoadUint64(&r.latencyMaxNs)
						if lat <= oldMax || atomic.CompareAndSwapUint64(&r.latencyMaxNs, oldMax, lat) {
							break
						}
					}

					if consumers, ok := s.subs[msg.Topic]; ok {
						for _, c := range consumers {
							c(msg)
						}
					}
				case <-r.stopCh:
					return
				}
			}
		}(&r.shards[i])
	}
}

func (r *Router) Stop() {
	close(r.stopCh)
	r.wg.Wait()
}

func (r *Router) Metrics() string {
	received := atomic.LoadUint64(&r.received)
	routed := atomic.LoadUint64(&r.routed)
	dropped := atomic.LoadUint64(&r.dropped)
	count := atomic.LoadUint64(&r.latencyCount)
	sum := atomic.LoadUint64(&r.latencySumNs)
	max := atomic.LoadUint64(&r.latencyMaxNs)

	var avg uint64
	if count > 0 {
		avg = sum / count
	}

	return fmt.Sprintf(
		"received=%d routed=%d dropped=%d avg_latency_us=%.2f max_latency_us=%.2f",
		received,
		routed,
		dropped,
		float64(avg)/1000.0,
		float64(max)/1000.0,
	)
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	router := NewRouter(runtime.NumCPU()*2, 65536)

	// Example subscriber
	router.Subscribe("orders", func(msg Message) {
		// In a real system, avoid allocations / logging in hot path.
	})

	router.Start()
	defer router.Stop()

	// Metrics reporter
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			fmt.Println(router.Metrics())
		}
	}()

	// Producers
	producerCount := runtime.NumCPU()
	var prodWG sync.WaitGroup
	stop := make(chan struct{})

	for i := 0; i < producerCount; i++ {
		prodWG.Add(1)
		go func(id int) {
			defer prodWG.Done()
			payload := []byte("x")
			for {
				select {
				case <-stop:
					return
				default:
					router.Publish(Message{
						Topic:     "orders",
						Payload:   payload,
						CreatedAt: time.Now().UnixNano(),
					})
				}
			}
		}(i)
	}

	time.Sleep(10 * time.Second)
	close(stop)
	prodWG.Wait()

	fmt.Println("final:", router.Metrics())
}
