use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_TOPICS: usize = 4;
const NUM_PRODUCERS: usize = 4;
const NUM_CONSUMERS_PER_TOPIC: usize = 2;
const CHANNEL_CAPACITY: usize = 1024 * 64;
const RUN_SECONDS: u64 = 10;

#[derive(Clone, Copy, Debug)]
struct Message {
    id: u64,
    topic: usize,
    created_at_ns: u64,
    payload: [u8; 32],
}

struct Stats {
    routed: AtomicU64,
    consumed: AtomicU64,
    dropped: AtomicU64,
    lat_hist: Mutex<Histogram<u64>>,
}

impl Stats {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            consumed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            lat_hist: Mutex::new(Histogram::new_with_bounds(1, 60_000_000_000, 3).unwrap()),
        }
    }
}

fn now_ns(start: Instant) -> u64 {
    start.elapsed().as_nanos() as u64
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let stats = Arc::new(Stats::new());
    let start = Instant::now();

    // Ingress channel: producers -> router
    let (ingress_tx, ingress_rx): (Sender<Message>, Receiver<Message>) = bounded(CHANNEL_CAPACITY);

    // Per-topic egress channels: router -> consumers
    let mut topic_txs = Vec::with_capacity(NUM_TOPICS);
    let mut topic_rxs = Vec::with_capacity(NUM_TOPICS);

    for _ in 0..NUM_TOPICS {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY);
        topic_txs.push(tx);
        topic_rxs.push(rx);
    }

    // Producers
    let mut handles = Vec::new();
    for producer_id in 0..NUM_PRODUCERS {
        let tx = ingress_tx.clone();
        let running = Arc::clone(&running);
        let start = start;

        handles.push(thread::spawn(move || {
            let mut seq = producer_id as u64 * 1_000_000_000;
            let mut rng = rand::thread_rng();

            while running.load(Ordering::Relaxed) {
                let topic = rng.gen_range(0..NUM_TOPICS);
                let msg = Message {
                    id: seq,
                    topic,
                    created_at_ns: now_ns(start),
                    payload: [producer_id as u8; 32],
                };
                seq += 1;

                if tx.send(msg).is_err() {
                    break;
                }
            }
        }));
    }

    // Router
    {
        let running = Arc::clone(&running);
        let stats = Arc::clone(&stats);
        let txs = topic_txs.clone();

        handles.push(thread::spawn(move || {
            while running.load(Ordering::Relaxed) {
                match ingress_rx.recv_timeout(Duration::from_millis(10)) {
                    Ok(msg) => {
                        let tx = &txs[msg.topic];
                        if tx.try_send(msg).is_ok() {
                            stats.routed.fetch_add(1, Ordering::Relaxed);
                        } else {
                            stats.dropped.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                    Err(_) => {}
                }
            }
        }));
    }

    // Consumers
    for topic in 0..NUM_TOPICS {
        for _ in 0..NUM_CONSUMERS_PER_TOPIC {
            let rx = topic_rxs[topic].clone();
            let running = Arc::clone(&running);
            let stats = Arc::clone(&stats);
            let start = start;

            handles.push(thread::spawn(move || {
                while running.load(Ordering::Relaxed) {
                    match rx.recv_timeout(Duration::from_millis(10)) {
                        Ok(msg) => {
                            let latency = now_ns(start).saturating_sub(msg.created_at_ns);
                            stats.consumed.fetch_add(1, Ordering::Relaxed);
                            if let Ok(mut hist) = stats.lat_hist.lock() {
                                let _ = hist.record(latency);
                            }
                        }
                        Err(_) => {}
                    }
                }
            }));
        }
    }

    // Reporter
    {
        let running = Arc::clone(&running);
        let stats = Arc::clone(&stats);

        handles.push(thread::spawn(move || {
            let mut last_routed = 0;
            let mut last_consumed = 0;

            while running.load(Ordering::Relaxed) {
                thread::sleep(Duration::from_secs(1));

                let routed = stats.routed.load(Ordering::Relaxed);
                let consumed = stats.consumed.load(Ordering::Relaxed);
                let dropped = stats.dropped.load(Ordering::Relaxed);

                let routed_delta = routed - last_routed;
                let consumed_delta = consumed - last_consumed;

                last_routed = routed;
                last_consumed = consumed;

                let (p50, p99, p999, max) = if let Ok(hist) = stats.lat_hist.lock() {
                    (
                        hist.value_at_quantile(0.50),
                        hist.value_at_quantile(0.99),
                        hist.value_at_quantile(0.999),
                        hist.max(),
                    )
                } else {
                    (0, 0, 0, 0)
                };

                println!(
                    "routed/s={} consumed/s={} dropped={} latency_ns p50={} p99={} p999={} max={}",
                    routed_delta, consumed_delta, dropped, p50, p99, p999, max
                );
            }
        }));
    }

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    drop(ingress_tx);
    drop(topic_txs);

    for h in handles {
        let _ = h.join();
    }

    let routed = stats.routed.load(Ordering::Relaxed);
    let consumed = stats.consumed.load(Ordering::Relaxed);
    let dropped = stats.dropped.load(Ordering::Relaxed);

    let hist = stats.lat_hist.lock().unwrap();
    println!("\nFinal:");
    println!("routed   = {}", routed);
    println!("consumed = {}", consumed);
    println!("dropped  = {}", dropped);
    println!("latency_ns p50  = {}", hist.value_at_quantile(0.50));
    println!("latency_ns p99  = {}", hist.value_at_quantile(0.99));
    println!("latency_ns p999 = {}", hist.value_at_quantile(0.999));
    println!("latency_ns max  = {}", hist.max());
}
```

