```go
package main

import (
	"fmt"
	"hash/fnv"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt int64 // unix nano
}

type Subscriber chan Message

type shard struct {
	input chan Message

	mu   sync.RWMutex
	subs map[string][]Subscriber
}

type Metrics struct {
	Published uint64
	Routed    uint64
	Dropped   uint64

	LatencyCount uint64
	LatencyTotal uint64
	LatencyMax   uint64
}

type Broker struct {
	shards  []shard
	metrics Metrics
}

func NewBroker(numShards, bufferSize int) *Broker {
	b := &Broker{
		shards: make([]shard, numShards),
	}
	for i := range b.shards {
		b.shards[i] = shard{
			input: make(chan Message, bufferSize),
			subs:  make(map[string][]Subscriber),
		}
		go b.shards[i].run(&b.metrics)
	}
	return b
}

func (s *shard) run(metrics *Metrics) {
	for msg := range s.input {
		s.mu.RLock()
		subs := s.subs[msg.Topic]
		for _, sub := range subs {
			select {
			case sub <- msg:
				atomic.AddUint64(&metrics.Routed, 1)
			default:
				atomic.AddUint64(&metrics.Dropped, 1)
			}
		}
		s.mu.RUnlock()

		latency := uint64(time.Now().UnixNano() - msg.CreatedAt)
		atomic.AddUint64(&metrics.LatencyCount, 1)
		atomic.AddUint64(&metrics.LatencyTotal, latency)

		for {
			oldMax := atomic.LoadUint64(&metrics.LatencyMax)
			if latency <= oldMax || atomic.CompareAndSwapUint64(&metrics.LatencyMax, oldMax, latency) {
				break
			}
		}
	}
}

func (b *Broker) shardFor(topic string) *shard {
	h := fnv.New32a()
	h.Write([]byte(topic))
	idx := int(h.Sum32()) % len(b.shards)
	return &b.shards[idx]
}

func (b *Broker) Publish(topic string, payload []byte) {
	msg := Message{
		Topic:     topic,
		Payload:   payload,
		CreatedAt: time.Now().UnixNano(),
	}
	atomic.AddUint64(&b.metrics.Published, 1)

	s := b.shardFor(topic)
	select {
	case s.input <- msg:
	default:
		atomic.AddUint64(&b.metrics.Dropped, 1)
	}
}

func (b *Broker) Subscribe(topic string, buffer int) Subscriber {
	sub := make(Subscriber, buffer)
	s := b.shardFor(topic)

	s.mu.Lock()
	s.subs[topic] = append(s.subs[topic], sub)
	s.mu.Unlock()

	return sub
}

func (b *Broker) PrintMetrics(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	var lastPublished uint64
	var lastRouted uint64

	for range ticker.C {
		published := atomic.LoadUint64(&b.metrics.Published)
		routed := atomic.LoadUint64(&b.metrics.Routed)
		dropped := atomic.LoadUint64(&b.metrics.Dropped)
		latCount := atomic.LoadUint64(&b.metrics.LatencyCount)
		latTotal := atomic.LoadUint64(&b.metrics.LatencyTotal)
		latMax := atomic.LoadUint64(&b.metrics.LatencyMax)

		pubRate := (published - lastPublished) / uint64(interval.Seconds())
		routeRate := (routed - lastRouted) / uint64(interval.Seconds())

		var avgLatency uint64
		if latCount > 0 {
			avgLatency = latTotal / latCount
		}

		fmt.Printf(
			"[metrics] pub=%d routed=%d dropped=%d pub_rate=%d/s route_rate=%d/s avg_lat=%dus max_lat=%dus\n",
			published,
			routed,
			dropped,
			pubRate,
			routeRate,
			avgLatency/1000,
			latMax/1000,
		)

		lastPublished = published
		lastRouted = routed
	}
}

func main() {
	broker := NewBroker(16, 65536)

	// subscribers
	for i := 0; i < 4; i++ {
		sub := broker.Subscribe("orders", 65536)
		go func(id int, ch Subscriber) {
			for range ch {
				// simulate ultra-light processing
			}
		}(i, sub)
	}

	go broker.PrintMetrics(1 * time.Second)

	// publishers
	publishers := 8
	for i := 0; i < publishers; i++ {
		go func(id int) {
			payload := []byte("test-message")
			for {
				broker.Publish("orders", payload)
			}
		}(i)
	}

	select {}
}
```

