# Improved minimal version

Here is the corrected full code:

```go
package main

import (
	"fmt"
	"hash/fnv"
	"runtime"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	CreatedAt int64
	Payload   []byte
}

type Router struct {
	workers []chan Message
}

func NewRouter(workerCount, queueSize int) *Router {
	r := &Router{
		workers: make([]chan Message, workerCount),
	}
	for i := 0; i < workerCount; i++ {
		r.workers[i] = make(chan Message, queueSize)
	}
	return r
}

func (r *Router) Route(msg Message) {
	idx := hashTopic(msg.Topic) % uint32(len(r.workers))
	r.workers[idx] <- msg
}

func hashTopic(s string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(s))
	return h.Sum32()
}

type Metrics struct {
	received       uint64
	processed      uint64
	totalLatencyNs uint64
	maxLatencyNs   uint64
}

func (m *Metrics) RecordReceived() {
	atomic.AddUint64(&m.received, 1)
}

func (m *Metrics) RecordProcessed(latency time.Duration) {
	atomic.AddUint64(&m.processed, 1)
	atomic.AddUint64(&m.totalLatencyNs, uint64(latency.Nanoseconds()))

	latNs := uint64(latency.Nanoseconds())
	for {
		old := atomic.LoadUint64(&m.maxLatencyNs)
		if latNs <= old {
			return
		}
		if atomic.CompareAndSwapUint64(&m.maxLatencyNs, old, latNs) {
			return
		}
	}
}

func worker(id int, ch <-chan Message, metrics *Metrics) {
	for msg := range ch {
		_ = msg.Payload
		latency := time.Since(time.Unix(0, msg.CreatedAt))
		metrics.RecordProcessed(latency)
	}
}

func printMetrics(metrics *Metrics, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	var lastProcessed uint64
	for range ticker.C {
		received := atomic.LoadUint64(&metrics.received)
		processed := atomic.LoadUint64(&metrics.processed)
		totalLatency := atomic.LoadUint64(&metrics.totalLatencyNs)
		maxLatency := atomic.LoadUint64(&metrics.maxLatencyNs)

		delta := processed - lastProcessed
		lastProcessed = processed

		var avgLatency time.Duration
		if processed > 0 {
			avgLatency = time.Duration(totalLatency / processed)
		}

		rate := uint64(float64(delta) / interval.Seconds())

		fmt.Printf(
			"recv=%d processed=%d rate=%d msg/s avg_latency=%s max_latency=%s goroutines=%d\n",
			received,
			processed,
			rate,
			avgLatency,
			time.Duration(maxLatency),
			runtime.NumGoroutine(),
		)
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	workerCount := runtime.NumCPU() * 2
	queueSize := 65536

	router := NewRouter(workerCount, queueSize)
	metrics := &Metrics{}

	for i := 0; i < workerCount; i++ {
		go worker(i, router.workers[i], metrics)
	}

	go printMetrics(metrics, 1*time.Second)

	var id uint64
	topics := []string{"orders", "trades", "quotes", "risk"}

	for {
		for _, topic := range topics {
			msg := Message{
				ID:        atomic.AddUint64(&id, 1),
				Topic:     topic,
				CreatedAt: time.Now().UnixNano(),
				Payload:   []byte("x"),
			}
			metrics.RecordReceived()
			router.Route(msg)
		}
	}
}
