## Example C code

This is a **DPDK-style skeleton**. It demonstrates the architecture and core packet loop. You would adapt the device init calls to your NIC and environment.

```c
// ultra_low_latency_forwarder.c
// Safe, authorized packet filtering + forwarding skeleton.
//
// Build target: DPDK-style environment
// This is a compact example showing the packet fast path design.

#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_PKT_BURST  32
#define MAX_PORTS      16
#define MAX_LCORES     32
#define MAX_RULES      1024
#define ETHER_ADDR_LEN 6

// -----------------------------------------------------------------------------
// Minimal packet header definitions
// -----------------------------------------------------------------------------
struct eth_hdr {
    uint8_t  dst[6];
    uint8_t  src[6];
    uint16_t ether_type;
} __attribute__((packed));

struct ipv4_hdr {
    uint8_t  version_ihl;
    uint8_t  tos;
    uint16_t total_length;
    uint16_t packet_id;
    uint16_t fragment_offset;
    uint8_t  ttl;
    uint8_t  next_proto_id;
    uint16_t hdr_checksum;
    uint32_t src_addr;
    uint32_t dst_addr;
} __attribute__((packed));

// -----------------------------------------------------------------------------
// Abstract packet buffer type
// Replace with rte_mbuf in a real DPDK implementation
// -----------------------------------------------------------------------------
struct packet {
    uint8_t *data;
    uint16_t data_len;
    uint16_t port;
};

// -----------------------------------------------------------------------------
// Filter rule
// -----------------------------------------------------------------------------
typedef struct {
    uint32_t src_ip;
    uint32_t src_mask;
    uint32_t dst_ip;
    uint32_t dst_mask;
    uint8_t  proto;      // 0 = any
    uint16_t dst_port;   // 0 = any (not parsed in this minimal example)
    bool     allow;
} filter_rule_t;

// -----------------------------------------------------------------------------
// Forwarding entry
// -----------------------------------------------------------------------------
typedef struct {
    uint16_t out_port;
    uint8_t  dst_mac[6];
    uint8_t  src_mac[6];
    bool     valid;
} fwd_entry_t;

// -----------------------------------------------------------------------------
// Global config
// -----------------------------------------------------------------------------
static filter_rule_t g_rules[MAX_RULES];
static size_t g_rule_count = 0;

static fwd_entry_t g_fwd_table[MAX_PORTS];

// -----------------------------------------------------------------------------
// Utility
// -----------------------------------------------------------------------------
static inline bool ip_match(uint32_t ip, uint32_t rule_ip, uint32_t mask) {
    return (ip & mask) == (rule_ip & mask);
}

static inline struct eth_hdr *get_eth_hdr(struct packet *pkt) {
    if (pkt->data_len < sizeof(struct eth_hdr)) return NULL;
    return (struct eth_hdr *)pkt->data;
}

static inline struct ipv4_hdr *get_ipv4_hdr(struct packet *pkt) {
    if (pkt->data_len < sizeof(struct eth_hdr) + sizeof(struct ipv4_hdr)) return NULL;
    struct eth_hdr *eth = (struct eth_hdr *)pkt->data;
    if (ntohs(eth->ether_type) != 0x0800) return NULL; // IPv4
    return (struct ipv4_hdr *)(pkt->data + sizeof(struct eth_hdr));
}

// -----------------------------------------------------------------------------
// Filtering
// Default policy: drop unless explicitly allowed
// -----------------------------------------------------------------------------
static inline bool packet_allowed(struct packet *pkt) {
    struct ipv4_hdr *ip = get_ipv4_hdr(pkt);
    if (!ip) return false;

    uint32_t src = ntohl(ip->src_addr);
    uint32_t dst = ntohl(ip->dst_addr);
    uint8_t proto = ip->next_proto_id;

    for (size_t i = 0; i < g_rule_count; i++) {
        filter_rule_t *r = &g_rules[i];
        if (!ip_match(src, r->src_ip, r->src_mask)) continue;
        if (!ip_match(dst, r->dst_ip, r->dst_mask)) continue;
        if (r->proto != 0 && r->proto != proto) continue;
        return r->allow;
    }

    return false;
}

// -----------------------------------------------------------------------------
// L2 rewrite for forwarding
// -----------------------------------------------------------------------------
static inline bool rewrite_l2_and_select_egress(struct packet *pkt, uint16_t *out_port) {
    if (pkt->port >= MAX_PORTS) return false;
    fwd_entry_t *fe = &g_fwd_table[pkt->port];
    if (!fe->valid) return false;

    struct eth_hdr *eth = get_eth_hdr(pkt);
    if (!eth) return false;

    memcpy(eth->dst, fe->dst_mac, 6);
    memcpy(eth->src, fe->src_mac, 6);
    *out_port = fe->out_port;
    return true;
}

// -----------------------------------------------------------------------------
// Abstract RX/TX/free interfaces
// Replace with rte_eth_rx_burst / rte_eth_tx_burst / rte_pktmbuf_free
// -----------------------------------------------------------------------------
static uint16_t rx_burst(uint16_t port, struct packet **pkts, uint16_t max_burst) {
    (void)port;
    (void)pkts;
    (void)max_burst;
    return 0;
}

static uint16_t tx_burst(uint16_t port, struct packet **pkts, uint16_t count) {
    (void)port;
    (void)pkts;
    return count;
}

static void free_packet(struct packet *pkt) {
    if (!pkt) return;
    free(pkt->data);
    free(pkt);
}

// -----------------------------------------------------------------------------
// Fast path loop
// -----------------------------------------------------------------------------
static void process_port_loop(uint16_t in_port) {
    struct packet *rx_pkts[MAX_PKT_BURST];
    struct packet *tx_pkts[MAX_PKT_BURST];
    uint16_t tx_count = 0;

    for (;;) {
        uint16_t nb_rx = rx_burst(in_port, rx_pkts, MAX_PKT_BURST);
        if (nb_rx == 0) {
            continue;
        }

        tx_count = 0;

        for (uint16_t i = 0; i < nb_rx; i++) {
            struct packet *pkt = rx_pkts[i];

            if (!packet_allowed(pkt)) {
                free_packet(pkt);
                continue;
            }

            uint16_t out_port;
            if (!rewrite_l2_and_select_egress(pkt, &out_port)) {
                free_packet(pkt);
                continue;
            }

            pkt->port = out_port;
            tx_pkts[tx_count++] = pkt;
        }

        if (tx_count > 0) {
            uint16_t sent = tx_burst(tx_pkts[0]->port, tx_pkts, tx_count);

            for (uint16_t i = sent; i < tx_count; i++) {
                free_packet(tx_pkts[i]);
            }
        }
    }
}

// -----------------------------------------------------------------------------
// Config helpers
// -----------------------------------------------------------------------------
static void add_rule(uint32_t src_ip, uint32_t src_mask,
                     uint32_t dst_ip, uint32_t dst_mask,
                     uint8_t proto, bool allow) {
    if (g_rule_count >= MAX_RULES) {
        fprintf(stderr, "rule table full\n");
        exit(1);
    }

    g_rules[g_rule_count++] = (filter_rule_t){
        .src_ip = src_ip,
        .src_mask = src_mask,
        .dst_ip = dst_ip,
        .dst_mask = dst_mask,
        .proto = proto,
        .dst_port = 0,
        .allow = allow
    };
}

static void set_fwd_entry(uint16_t in_port, uint16_t out_port,
                          const uint8_t src_mac[6],
                          const uint8_t dst_mac[6]) {
    if (in_port >= MAX_PORTS) {
        fprintf(stderr, "invalid in_port\n");
        exit(1);
    }

    g_fwd_table[in_port].out_port = out_port;
    memcpy(g_fwd_table[in_port].src_mac, src_mac, 6);
    memcpy(g_fwd_table[in_port].dst_mac, dst_mac, 6);
    g_fwd_table[in_port].valid = true;
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(void) {
    // Example policy:
    // Allow TCP from 10.0.0.0/24 to 10.0.1.0/24
    add_rule(
        0x0A000000, 0xFFFFFF00,
        0x0A000100, 0xFFFFFF00,
        6, true
    );

    // Example forwarding: port 0 -> port 1
    uint8_t src_mac[6] = {0x02, 0x00, 0x00, 0x00, 0x00, 0x01};
    uint8_t dst_mac[6] = {0x02, 0x00, 0x00, 0x00, 0x00, 0x02};
    set_fwd_entry(0, 1, src_mac, dst_mac);

    printf("Starting ultra-low-latency forwarding loop on port 0...\n");
    process_port_loop(0);

    return 0;
}
```

