## Example XDP filter/forward skeleton

If you want kernel-level low-latency filtering, here is a minimal **XDP** example that:
- parses Ethernet and IPv4
- allows only TCP
- redirects to another interface

```c
// xdp_forward_kern.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 16);
    __type(key, __u32);
    __type(value, __u32);
} tx_port_map SEC(".maps");

SEC("xdp")
int xdp_filter_fwd(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_DROP;

    if (eth->h_proto != __constant_htons(ETH_P_IP))
        return XDP_DROP;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_DROP;

    if (ip->protocol != IPPROTO_TCP)
        return XDP_DROP;

    __u32 out_ifindex = 1;
    return bpf_redirect_map(&tx_port_map, out_ifindex, 0);
}

char _license[] SEC("license") = "GPL";
