```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>

#ifndef MSG_WAITFORONE
#define MSG_WAITFORONE 0x10000
#endif

#define MAX_BATCH 32
#define MAX_PKT   2048
#define MAX_EVENTS 16
#define ALLOWLIST_MAX 16

static volatile sig_atomic_t g_stop = 0;

static void on_sigint(int signo) {
    (void)signo;
    g_stop = 1;
}

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

typedef struct {
    uint32_t ips[ALLOWLIST_MAX];
    size_t count;
    size_t min_len;
    size_t max_len;
    int first_byte_match; // -1 disabled, else 0..255
} filter_cfg_t;

typedef struct {
    uint64_t rx_packets;
    uint64_t rx_bytes;
    uint64_t passed_packets;
    uint64_t passed_bytes;
    uint64_t dropped_packets;
    uint64_t tx_packets;
    uint64_t tx_bytes;
    uint64_t tx_errors;
} stats_t;

static bool ip_allowed(const filter_cfg_t *cfg, uint32_t ip_be) {
    if (cfg->count == 0) return true;
    for (size_t i = 0; i < cfg->count; i++) {
        if (cfg->ips[i] == ip_be) return true;
    }
    return false;
}

static bool packet_allowed(
    const filter_cfg_t *cfg,
    const struct sockaddr_in *src,
    const uint8_t *buf,
    size_t len
) {
    if (!ip_allowed(cfg, src->sin_addr.s_addr)) return false;
    if (len < cfg->min_len || len > cfg->max_len) return false;
    if (cfg->first_byte_match >= 0) {
        if (len == 0 || buf[0] != (uint8_t)cfg->first_byte_match) return false;
    }
    return true;
}

static int make_udp_listener(const char *bind_ip, uint16_t bind_port) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int one = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
#ifdef SO_REUSEPORT
    setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one));
#endif

    int rcvbuf = 4 * 1024 * 1024;
    setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(bind_port);
    if (inet_pton(AF_INET, bind_ip, &addr.sin_addr) != 1) {
        fprintf(stderr, "invalid bind ip: %s\n", bind_ip);
        close(fd);
        return -1;
    }

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    if (set_nonblocking(fd) < 0) {
        perror("set_nonblocking(listener)");
        close(fd);
        return -1;
    }

    return fd;
}

static int make_udp_sender(const char *dst_ip, uint16_t dst_port, struct sockaddr_in *dst_out) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket sender");
        return -1;
    }

    int sndbuf = 4 * 1024 * 1024;
    setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf));

    if (set_nonblocking(fd) < 0) {
        perror("set_nonblocking(sender)");
        close(fd);
        return -1;
    }

    memset(dst_out, 0, sizeof(*dst_out));
    dst_out->sin_family = AF_INET;
    dst_out->sin_port = htons(dst_port);
    if (inet_pton(AF_INET, dst_ip, &dst_out->sin_addr) != 1) {
        fprintf(stderr, "invalid dst ip: %s\n", dst_ip);
        close(fd);
        return -1;
    }

    return fd;
}

static void print_stats(const stats_t *s, time_t start_time) {
    time_t now = time(NULL);
    double sec = difftime(now, start_time);
    if (sec < 1.0) sec = 1.0;

    fprintf(stderr,
        "[%.0fs] rx=%llu pkts %.2f pps, pass=%llu, drop=%llu, tx=%llu, txerr=%llu\n",
        sec,
        (unsigned long long)s->rx_packets, s->rx_packets / sec,
        (unsigned long long)s->passed_packets,
        (unsigned long long)s->dropped_packets,
        (unsigned long long)s->tx_packets,
        (unsigned long long)s->tx_errors
    );
}

int main(int argc, char **argv) {
    if (argc < 5) {
        fprintf(stderr,
            "usage: %s <bind_ip> <bind_port> <dst_ip> <dst_port>\n",
            argv[0]);
        return 1;
    }

    const char *bind_ip = argv[1];
    uint16_t bind_port = (uint16_t)atoi(argv[2]);
    const char *dst_ip = argv[3];
    uint16_t dst_port = (uint16_t)atoi(argv[4]);

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    filter_cfg_t filter = {0};
    filter.min_len = 1;
    filter.max_len = MAX_PKT;
    filter.first_byte_match = -1;

    // Example allowlist: empty means allow all.
    // To restrict, uncomment and set:
    // inet_pton(AF_INET, "127.0.0.1", &filter.ips[filter.count++]);

    stats_t stats = {0};

    int rx_fd = make_udp_listener(bind_ip, bind_port);
    if (rx_fd < 0) return 1;

    struct sockaddr_in dst_addr;
    int tx_fd = make_udp_sender(dst_ip, dst_port, &dst_addr);
    if (tx_fd < 0) {
        close(rx_fd);
        return 1;
    }

    int ep = epoll_create1(0);
    if (ep < 0) {
        perror("epoll_create1");
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev));
    ev.events = EPOLLIN;
    ev.data.fd = rx_fd;
    if (epoll_ctl(ep, EPOLL_CTL_ADD, rx_fd, &ev) < 0) {
        perror("epoll_ctl");
        close(ep);
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    struct mmsghdr msgs[MAX_BATCH];
    struct iovec iovecs[MAX_BATCH];
    struct sockaddr_in src_addrs[MAX_BATCH];
    uint8_t bufs[MAX_BATCH][MAX_PKT];
    char ctrl[MAX_BATCH][64];

    struct mmsghdr out_msgs[MAX_BATCH];
    struct iovec out_iovecs[MAX_BATCH];

    time_t start_time = time(NULL);
    time_t last_stat = start_time;

    while (!g_stop) {
        struct epoll_event events[MAX_EVENTS];
        int n = epoll_wait(ep, events, MAX_EVENTS, 1000);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }
        if (n == 0) {
            time_t now = time(NULL);
            if (now != last_stat) {
                print_stats(&stats, start_time);
                last_stat = now;
            }
            continue;
        }

        for (int ei = 0; ei < n; ei++) {
            if (events[ei].data.fd != rx_fd) continue;

            while (1) {
                memset(msgs, 0, sizeof(msgs));
                for (int i = 0; i < MAX_BATCH; i++) {
                    iovecs[i].iov_base = bufs[i];
                    iovecs[i].iov_len = sizeof(bufs[i]);

                    msgs[i].msg_hdr.msg_iov = &iovecs[i];
                    msgs[i].msg_hdr.msg_iovlen = 1;
                    msgs[i].msg_hdr.msg_name = &src_addrs[i];
                    msgs[i].msg_hdr.msg_namelen = sizeof(src_addrs[i]);
                    msgs[i].msg_hdr.msg_control = ctrl[i];
                    msgs[i].msg_hdr.msg_controllen = sizeof(ctrl[i]);
                }

                int r = recvmmsg(rx_fd, msgs, MAX_BATCH, MSG_DONTWAIT | MSG_WAITFORONE, NULL);
                if (r < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) break;
                    perror("recvmmsg");
                    break;
                }

                int out_count = 0;
                for (int i = 0; i < r; i++) {
                    size_t len = msgs[i].msg_len;
                    stats.rx_packets++;
                    stats.rx_bytes += len;

                    if (!packet_allowed(&filter, &src_addrs[i], bufs[i], len)) {
                        stats.dropped_packets++;
                        continue;
                    }

                    stats.passed_packets++;
                    stats.passed_bytes += len;

                    memset(&out_msgs[out_count], 0, sizeof(out_msgs[out_count]));
                    out_iovecs[out_count].iov_base = bufs[i];
                    out_iovecs[out_count].iov_len = len;

                    out_msgs[out_count].msg_hdr.msg_iov = &out_iovecs[out_count];
                    out_msgs[out_count].msg_hdr.msg_iovlen = 1;
                    out_msgs[out_count].msg_hdr.msg_name = &dst_addr;
                    out_msgs[out_count].msg_hdr.msg_namelen = sizeof(dst_addr);

                    out_count++;
                }

                if (out_count > 0) {
                    int s = sendmmsg(tx_fd, out_msgs, out_count, MSG_DONTWAIT);
                    if (s < 0) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            perror("sendmmsg");
                        }
                        stats.tx_errors += out_count;
                    } else {
                        for (int i = 0; i < s; i++) {
                            stats.tx_packets++;
                            stats.tx_bytes += out_iovecs[i].iov_len;
                        }
                        if (s < out_count) {
                            stats.tx_errors += (uint64_t)(out_count - s);
                        }
                    }
                }
            }
        }

        time_t now = time(NULL);
        if (now != last_stat) {
            print_stats(&stats, start_time);
            last_stat = now;
        }
    }

    print_stats(&stats, start_time);
    close(ep);
    close(rx_fd);
    close(tx_fd);
    return 0;
}
