```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_link.h>
#include <linux/ip.h>
#include <linux/if_xdp.h>
#include <net/if.h>
#include <poll.h>
#include <sched.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>
#include <bpf/xsk.h>

#define NUM_FRAMES              4096
#define FRAME_SIZE              XSK_UMEM__DEFAULT_FRAME_SIZE
#define UMEM_SIZE               (NUM_FRAMES * FRAME_SIZE)

#define RX_BATCH_SIZE           64
#define TX_BATCH_SIZE           64
#define FQ_SIZE                 2048
#define CQ_SIZE                 2048
#define RX_SIZE                 2048
#define TX_SIZE                 2048

#define INVALID_UMEM_ADDR       UINT64_MAX

static volatile sig_atomic_t running = 1;

struct xsk_port {
    int ifindex;
    int queue_id;
    int xsk_fd;

    struct xsk_ring_cons rx;
    struct xsk_ring_prod tx;
    struct xsk_ring_prod fq;
    struct xsk_ring_cons cq;

    struct xsk_umem *umem;
    struct xsk_socket *xsk;

    void *umem_area;

    uint64_t free_frames[NUM_FRAMES];
    uint32_t free_head;
    uint32_t free_count;
};

struct stats {
    uint64_t rx_pkts;
    uint64_t tx_pkts;
    uint64_t dropped;
    uint64_t filtered;
};

static void on_signal(int signo) {
    (void)signo;
    running = 0;
}

static void bump_memlock_rlimit(void) {
    struct rlimit r = {RLIM_INFINITY, RLIM_INFINITY};
    if (setrlimit(RLIMIT_MEMLOCK, &r)) {
        perror("setrlimit(RLIMIT_MEMLOCK)");
        exit(EXIT_FAILURE);
    }
}

static void pin_to_cpu(int cpu) {
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu, &set);
    if (sched_setaffinity(0, sizeof(set), &set) != 0) {
        perror("sched_setaffinity");
    }
}

static uint64_t alloc_frame(struct xsk_port *p) {
    if (p->free_count == 0)
        return INVALID_UMEM_ADDR;
    uint64_t addr = p->free_frames[p->free_head];
    p->free_head = (p->free_head + 1) % NUM_FRAMES;
    p->free_count--;
    return addr;
}

static void free_frame(struct xsk_port *p, uint64_t addr) {
    uint32_t idx = (p->free_head + p->free_count) % NUM_FRAMES;
    p->free_frames[idx] = addr;
    p->free_count++;
}

static void recycle_completions(struct xsk_port *p) {
    uint32_t idx_cq;
    unsigned int rcvd = xsk_ring_cons__peek(&p->cq, RX_BATCH_SIZE, &idx_cq);
    for (unsigned int i = 0; i < rcvd; i++) {
        uint64_t addr = *xsk_ring_cons__comp_addr(&p->cq, idx_cq + i);
        free_frame(p, addr);
    }
    if (rcvd)
        xsk_ring_cons__release(&p->cq, rcvd);
}

static void fill_rx_ring(struct xsk_port *p) {
    uint32_t idx_fq;
    unsigned int can_fill = xsk_prod_nb_free(&p->fq, RX_BATCH_SIZE);
    if (!can_fill)
        return;

    unsigned int n = can_fill > RX_BATCH_SIZE ? RX_BATCH_SIZE : can_fill;
    if (xsk_ring_prod__reserve(&p->fq, n, &idx_fq) != n)
        return;

    for (unsigned int i = 0; i < n; i++) {
        uint64_t addr = alloc_frame(p);
        if (addr == INVALID_UMEM_ADDR) {
            xsk_ring_prod__submit(&p->fq, i);
            return;
        }
        *xsk_ring_prod__fill_addr(&p->fq, idx_fq + i) = addr;
    }
    xsk_ring_prod__submit(&p->fq, n);
}

static int create_xsk_port(struct xsk_port *p, const char *ifname, int queue_id) {
    struct xsk_umem_config ucfg;
    struct xsk_socket_config cfg;
    struct xsk_umem *umem = NULL;
    struct xsk_socket *xsk = NULL;
    int ret;

    memset(p, 0, sizeof(*p));
    p->ifindex = if_nametoindex(ifname);
    if (!p->ifindex) {
        perror("if_nametoindex");
        return -1;
    }
    p->queue_id = queue_id;

    p->umem_area = mmap(NULL, UMEM_SIZE, PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS | MAP_POPULATE, -1, 0);
    if (p->umem_area == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    for (uint32_t i = 0; i < NUM_FRAMES; i++)
        p->free_frames[i] = i * FRAME_SIZE;
    p->free_head = 0;
    p->free_count = NUM_FRAMES;

    memset(&ucfg, 0, sizeof(ucfg));
    ucfg.fill_size = FQ_SIZE;
    ucfg.comp_size = CQ_SIZE;
    ucfg.frame_size = FRAME_SIZE;
    ucfg.frame_headroom = 0;
    ucfg.flags = 0;

    ret = xsk_umem__create(&umem, p->umem_area, UMEM_SIZE,
                           &p->fq, &p->cq, &ucfg);
    if (ret) {
        fprintf(stderr, "xsk_umem__create failed: %d\n", ret);
        return -1;
    }

    memset(&cfg, 0, sizeof(cfg));
    cfg.rx_size = RX_SIZE;
    cfg.tx_size = TX_SIZE;
    cfg.libbpf_flags = 0;
    cfg.xdp_flags = XDP_FLAGS_UPDATE_IF_NOEXIST;
    cfg.bind_flags = XDP_COPY; /* safer portability; use XDP_ZEROCOPY where supported */

    ret = xsk_socket__create(&xsk, ifname, queue_id, umem,
                             &p->rx, &p->tx, &cfg);
    if (ret) {
        fprintf(stderr, "xsk_socket__create(%s) failed: %d\n", ifname, ret);
        return -1;
    }

    p->umem = umem;
    p->xsk = xsk;
    p->xsk_fd = xsk_socket__fd(xsk);

    fill_rx_ring(p);
    fill_rx_ring(p);
    fill_rx_ring(p);

    return 0;
}

static void destroy_xsk_port(struct xsk_port *p) {
    if (p->xsk)
        xsk_socket__delete(p->xsk);
    if (p->umem)
        xsk_umem__delete(p->umem);
    if (p->umem_area && p->umem_area != MAP_FAILED)
        munmap(p->umem_area, UMEM_SIZE);
}

static bool should_drop(const uint8_t *pkt, uint32_t len, uint32_t blocked_src_be) {
    if (len < sizeof(struct ethhdr))
        return true;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return false;

    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return true;

    const struct iphdr *iph = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
    if (iph->version != 4)
        return true;

    if (iph->saddr == blocked_src_be)
        return true;

    return false;
}

static int submit_tx(struct xsk_port *txp, uint64_t addr, uint32_t len) {
    uint32_t idx;
    if (xsk_ring_prod__reserve(&txp->tx, 1, &idx) != 1)
        return -1;

    struct xdp_desc *tx_desc = xsk_ring_prod__tx_desc(&txp->tx, idx);
    tx_desc->addr = addr;
    tx_desc->len = len;
    xsk_ring_prod__submit(&txp->tx, 1);
    sendto(txp->xsk_fd, NULL, 0, MSG_DONTWAIT, NULL, 0);
    return 0;
}

static void process_loop(struct xsk_port *rxp, struct xsk_port *txp, uint32_t blocked_src_be) {
    struct pollfd fds[1];
    struct stats st = {0};

    fds[0].fd = rxp->xsk_fd;
    fds[0].events = POLLIN;

    while (running) {
        recycle_completions(txp);
        fill_rx_ring(rxp);

        uint32_t idx_rx = 0;
        unsigned int rcvd = xsk_ring_cons__peek(&rxp->rx, RX_BATCH_SIZE, &idx_rx);
        if (!rcvd) {
            poll(fds, 1, 50);
            continue;
        }

        for (unsigned int i = 0; i < rcvd; i++) {
            const struct xdp_desc *desc = xsk_ring_cons__rx_desc(&rxp->rx, idx_rx + i);
            uint64_t addr = desc->addr;
            uint32_t len = desc->len;
            uint8_t *pkt = xsk_umem__get_data(rxp->umem_area, addr);

            st.rx_pkts++;

            if (should_drop(pkt, len, blocked_src_be)) {
                st.filtered++;
                free_frame(rxp, addr);
                continue;
            }

            uint64_t tx_addr = alloc_frame(txp);
            if (tx_addr == INVALID_UMEM_ADDR) {
                st.dropped++;
                free_frame(rxp, addr);
                continue;
            }

            void *dst = xsk_umem__get_data(txp->umem_area, tx_addr);
            memcpy(dst, pkt, len);

            if (submit_tx(txp, tx_addr, len) != 0) {
                st.dropped++;
                free_frame(txp, tx_addr);
            } else {
                st.tx_pkts++;
            }

            free_frame(rxp, addr);
        }

        xsk_ring_cons__release(&rxp->rx, rcvd);
    }

    fprintf(stderr,
            "rx=%llu tx=%llu filtered=%llu dropped=%llu\n",
            (unsigned long long)st.rx_pkts,
            (unsigned long long)st.tx_pkts,
            (unsigned long long)st.filtered,
            (unsigned long long)st.dropped);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <rx_if> <tx_if> <blocked_src_ipv4> [cpu]\n"
        "Example: %s eth0 eth1 10.0.0.1 2\n",
        prog, prog);
}

int main(int argc, char **argv) {
    struct xsk_port rxp, txp;
    uint32_t blocked_src_be;
    int cpu = 0;

    if (argc < 4) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    if (argc >= 5)
        cpu = atoi(argv[4]);

    bump_memlock_rlimit();
    pin_to_cpu(cpu);

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (inet_pton(AF_INET, argv[3], &blocked_src_be) != 1) {
        fprintf(stderr, "Invalid IPv4 address: %s\n", argv[3]);
        return EXIT_FAILURE;
    }

    if (create_xsk_port(&rxp, argv[1], 0) != 0) {
        fprintf(stderr, "Failed to create RX port\n");
        return EXIT_FAILURE;
    }

    if (create_xsk_port(&txp, argv[2], 0) != 0) {
        fprintf(stderr, "Failed to create TX port\n");
        destroy_xsk_port(&rxp);
        return EXIT_FAILURE;
    }

    process_loop(&rxp, &txp, blocked_src_be);

    destroy_xsk_port(&txp);
    destroy_xsk_port(&rxp);
    return EXIT_SUCCESS;
}
