## Rust example

```rust
use std::io;
use std::mem::{size_of, zeroed};
use std::net::Ipv4Addr;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::ptr;

const ETH_P_ALL: u16 = 0x0003;
const ETH_HDR_LEN: usize = 14;
const IPV4_PROTO_OFFSET: usize = ETH_HDR_LEN + 9;
const IPV4_SRC_OFFSET: usize = ETH_HDR_LEN + 12;
const IPV4_DST_OFFSET: usize = ETH_HDR_LEN + 16;

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn set_cpu_affinity(cpu: usize) -> io::Result<()> {
    #[cfg(target_os = "linux")]
    unsafe {
        let mut set: libc::cpu_set_t = zeroed();
        libc::CPU_ZERO(&mut set);
        libc::CPU_SET(cpu, &mut set);
        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    Ok(())
}

fn if_nametoindex(name: &str) -> io::Result<u32> {
    let c = std::ffi::CString::new(name).unwrap();
    let idx = unsafe { libc::if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(idx)
    }
}

fn open_raw_socket(iface: &str) -> io::Result<OwnedFd> {
    unsafe {
        let fd = libc::socket(libc::AF_PACKET, libc::SOCK_RAW, htons(ETH_P_ALL) as i32);
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let fd = OwnedFd::from_raw_fd(fd);

        let ifindex = if_nametoindex(iface)?;

        let mut sll: libc::sockaddr_ll = zeroed();
        sll.sll_family = libc::AF_PACKET as u16;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifindex as i32;

        let rc = libc::bind(
            fd.as_raw_fd(),
            &sll as *const _ as *const libc::sockaddr,
            size_of::<libc::sockaddr_ll>() as u32,
        );
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }

        let rcvbuf: i32 = 4 * 1024 * 1024;
        let sndbuf: i32 = 4 * 1024 * 1024;

        let rc = libc::setsockopt(
            fd.as_raw_fd(),
            libc::SOL_SOCKET,
            libc::SO_RCVBUF,
            &rcvbuf as *const _ as *const _,
            size_of::<i32>() as u32,
        );
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }

        let rc = libc::setsockopt(
            fd.as_raw_fd(),
            libc::SOL_SOCKET,
            libc::SO_SNDBUF,
            &sndbuf as *const _ as *const _,
            size_of::<i32>() as u32,
        );
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(fd)
    }
}

fn parse_ipv4_addrs(frame: &[u8]) -> Option<(Ipv4Addr, Ipv4Addr, u8)> {
    if frame.len() < ETH_HDR_LEN + 20 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ihl = (frame[ETH_HDR_LEN] & 0x0f) as usize * 4;
    if frame.len() < ETH_HDR_LEN + ihl || ihl < 20 {
        return None;
    }

    let proto = frame[IPV4_PROTO_OFFSET];
    let src = Ipv4Addr::new(
        frame[IPV4_SRC_OFFSET],
        frame[IPV4_SRC_OFFSET + 1],
        frame[IPV4_SRC_OFFSET + 2],
        frame[IPV4_SRC_OFFSET + 3],
    );
    let dst = Ipv4Addr::new(
        frame[IPV4_DST_OFFSET],
        frame[IPV4_DST_OFFSET + 1],
        frame[IPV4_DST_OFFSET + 2],
        frame[IPV4_DST_OFFSET + 3],
    );

    Some((src, dst, proto))
}

fn should_forward(frame: &[u8]) -> bool {
    if let Some((src, dst, proto)) = parse_ipv4_addrs(frame) {
        if proto == 17 && src == Ipv4Addr::new(10, 0, 0, 10) && dst == Ipv4Addr::new(10, 0, 1, 10) {
            return true;
        }
    }
    false
}

fn forward_frame(tx_fd: &OwnedFd, out_ifindex: i32, frame: &[u8]) -> io::Result<usize> {
    unsafe {
        let mut addr: libc::sockaddr_ll = zeroed();
        addr.sll_family = libc::AF_PACKET as u16;
        addr.sll_protocol = htons(ETH_P_ALL);
        addr.sll_ifindex = out_ifindex;

        let n = libc::sendto(
            tx_fd.as_raw_fd(),
            frame.as_ptr() as *const _,
            frame.len(),
            0,
            &addr as *const _ as *const libc::sockaddr,
            size_of::<libc::sockaddr_ll>() as u32,
        );
        if n < 0 {
            Err(io::Error::last_os_error())
        } else {
            Ok(n as usize)
        }
    }
}

fn main() -> io::Result<()> {
    let in_iface = "eth0";
    let out_iface = "eth1";

    let _ = set_cpu_affinity(2);

    let rx = open_raw_socket(in_iface)?;
    let tx = open_raw_socket(out_iface)?;
    let out_ifindex = if_nametoindex(out_iface)? as i32;

    let mut buf = vec![0u8; 2048];

    loop {
        let n = unsafe {
            libc::recv(
                rx.as_raw_fd(),
                buf.as_mut_ptr() as *mut _,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if let Some(libc::EINTR) = err.raw_os_error() {
                continue;
            }
            eprintln!("recv error: {err}");
            continue;
        }

        let frame = &buf[..n as usize];

        if should_forward(frame) {
            if let Err(e) = forward_frame(&tx, out_ifindex, frame) {
                eprintln!("forward error: {e}");
            }
        }
    }
}
