## 1) eBPF/XDP redirect program

Save as `xdp_redirect_kern.c`:

```c
// clang -O2 -g -target bpf -c xdp_redirect_kern.c -o xdp_redirect_kern.o
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

struct {
    __uint(type, BPF_MAP_TYPE_XSKMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} xsks_map SEC(".maps");

SEC("xdp")
int xdp_sock_prog(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    // Minimal sanity check; you can add VLAN parsing if needed.
    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    __u32 index = ctx->rx_queue_index;

    // Redirect to AF_XDP socket bound to this queue if present.
    if (bpf_map_lookup_elem(&xsks_map, &index))
        return bpf_redirect_map(&xsks_map, index, XDP_PASS);

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
