fn parse_mac(s: &str) -> Result<[u8; 6]> {
    let parts: Vec<_> = s.split(':').collect();
    if parts.len() != 6 {
        return Err(anyhow!("invalid MAC"));
    }
    let mut out = [0u8; 6];
    for (i, p) in parts.iter().enumerate() {
        out[i] = u8::from_str_radix(p, 16)?;
    }
    Ok(out)
}

fn ifindex_from_name(name: &str) -> Result<u32> {
