    let idx = unsafe { libc::if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(anyhow!("if_nametoindex failed for {}", name))
    } else {
        Ok(idx)
    }
}

fn htons(v: u16) -> u16 {
