/*
 NOTE:
 The AF_XDP setup below uses libbpf-sys directly. It is intentionally compact and focused
 on the service logic. In production, split this into modules and add robust error handling.
*/

#[repr(C)]
struct XdpDesc {
    addr: u64,
    len: u32,
    options: u32,
}

#[allow(non_camel_case_types)]
type xsk_umem = c_void;
#[allow(non_camel_case_types)]
type xsk_socket = c_void;
#[allow(non_camel_case_types)]
type xsk_ring_prod = c_void;
#[allow(non_camel_case_types)]
type xsk_ring_cons = c_void;

unsafe extern "C" {
    fn xsk_umem__create(
        umem_ptr: *mut *mut xsk_umem,
        buffer: *mut c_void,
        size: u64,
        fill: *mut xsk_ring_prod,
        comp: *mut xsk_ring_cons,
        config: *const c_void,
    ) -> i32;

    fn xsk_socket__create(
        xsk_ptr: *mut *mut xsk_socket,
        ifname: *const i8,
        queue_id: u32,
        umem: *mut xsk_umem,
        rx: *mut xsk_ring_cons,
        tx: *mut xsk_ring_prod,
        config: *const c_void,
    ) -> i32;

    fn xsk_socket__fd(xsk: *const xsk_socket) -> i32;

    fn xsk_umem__delete(umem: *mut xsk_umem);
    fn xsk_socket__delete(xsk: *mut xsk_socket);

    fn xsk_ring_cons__peek(r: *mut xsk_ring_cons, nb: u32, idx: *mut u32) -> u32;
    fn xsk_ring_cons__release(r: *mut xsk_ring_cons, nb: u32);

    fn xsk_ring_prod__reserve(r: *mut xsk_ring_prod, nb: u32, idx: *mut u32) -> i32;
    fn xsk_ring_prod__submit(r: *mut xsk_ring_prod, nb: u32);

    fn xsk_ring_prod__fill_addr(r: *mut xsk_ring_prod, idx: u32) -> *mut u64;
    fn xsk_ring_cons__comp_addr(r: *mut xsk_ring_cons, idx: u32) -> *const u64;

    fn xsk_ring_cons__rx_desc(r: *mut xsk_ring_cons, idx: u32) -> *const XdpDesc;
    fn xsk_ring_prod__tx_desc(r: *mut xsk_ring_prod, idx: u32) -> *mut XdpDesc;
}

struct AfXdp {
    umem_area: *mut u8,
    umem_size: usize,
    frame_size: usize,
    frame_count: usize,

    umem: *mut xsk_umem,
    xsk: *mut xsk_socket,

    fill: Box<[u8; 4096]>,
    comp: Box<[u8; 4096]>,
    rx: Box<[u8; 4096]>,
    tx: Box<[u8; 4096]>,
}

impl Drop for AfXdp {
    fn drop(&mut self) {
        unsafe {
            if !self.xsk.is_null() {
                xsk_socket__delete(self.xsk);
            }
            if !self.umem.is_null() {
                xsk_umem__delete(self.umem);
            }
            if !self.umem_area.is_null() {
                let _ = munmap(self.umem_area as *mut c_void, self.umem_size);
            }
        }
    }
}

impl AfXdp {
    fn new(ifname: &str, queue_id: u32, frame_size: usize, frame_count: usize) -> Result<Self> {
        let umem_size = frame_size * frame_count;
        let umem_area = unsafe {
            mmap(
                null_mut(),
                umem_size,
                PROT_READ | PROT_WRITE,
                MAP_PRIVATE | MAP_ANONYMOUS,
                -1,
                0,
            )
        };
        if umem_area == MAP_FAILED {
            return Err(anyhow!("mmap failed"));
        }

        let mut s = Self {
            umem_area: umem_area as *mut u8,
            umem_size,
            frame_size,
            frame_count,
            umem: null_mut(),
            xsk: null_mut(),
            fill: Box::new([0u8; 4096]),
            comp: Box::new([0u8; 4096]),
            rx: Box::new([0u8; 4096]),
            tx: Box::new([0u8; 4096]),
        };

        let ret = unsafe {
            xsk_umem__create(
                &mut s.umem,
                s.umem_area as *mut c_void,
                umem_size as u64,
                s.fill.as_mut_ptr() as *mut xsk_ring_prod,
                s.comp.as_mut_ptr() as *mut xsk_ring_cons,
                null(),
            )
        };
        if ret != 0 {
            return Err(anyhow!("xsk_umem__create failed: {}", ret));
        }

        let cif = CString::new(ifname)?;
        let ret = unsafe {
            xsk_socket__create(
                &mut s.xsk,
                cif.as_ptr(),
                queue_id,
                s.umem,
                s.rx.as_mut_ptr() as *mut xsk_ring_cons,
                s.tx.as_mut_ptr() as *mut xsk_ring_prod,
                null(),
            )
        };
        if ret != 0 {
            return Err(anyhow!("xsk_socket__create failed: {}", ret));
        }

        // Pre-populate fill ring with all frames.
        let mut idx = 0u32;
        let reserved = unsafe { xsk_ring_prod__reserve(s.fill.as_mut_ptr() as *mut xsk_ring_prod, frame_count as u32, &mut idx) };
        if reserved < 0 || reserved as usize != frame_count {
            return Err(anyhow!("failed to reserve fill ring"));
        }
        for i in 0..frame_count {
            unsafe {
                *xsk_ring_prod__fill_addr(s.fill.as_mut_ptr() as *mut xsk_ring_prod, idx + i as u32) =
                    (i * frame_size) as u64;
            }
        }
        unsafe {
            xsk_ring_prod__submit(s.fill.as_mut_ptr() as *mut xsk_ring_prod, frame_count as u32);
        }

        Ok(s)
    }

    fn fd(&self) -> RawFd {
        unsafe { xsk_socket__fd(self.xsk) }
    }

    fn frame_ptr(&self, addr: u64) -> *mut u8 {
        unsafe { self.umem_area.add(addr as usize) }
    }
}

fn packet_allowed(pkt: &mut [u8], opts: &Opts, rewrite_dst_mac: Option<[u8; 6]>) -> bool {
    if pkt.len() < size_of::<EthHdr>() {
        return false;
    }

    let eth = unsafe { &mut *(pkt.as_mut_ptr() as *mut EthHdr) };
    let ethertype = ntohs(eth.ethertype);
    if ethertype != 0x0800 {
        return true;
    }

    let ip_off = size_of::<EthHdr>();
    if pkt.len() < ip_off + size_of::<Ipv4Hdr>() {
        return false;
    }

    let ip = unsafe { &mut *(pkt[ip_off..].as_mut_ptr() as *mut Ipv4Hdr) };
    let ihl = ((ip.version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || pkt.len() < ip_off + ihl {
        return false;
    }

    let l4_off = ip_off + ihl;

    match ip.protocol {
        17 => {
            if opts.drop_udp {
                return false;
            }
            if let Some(port) = opts.allow_dst_port {
                if pkt.len() < l4_off + size_of::<UdpHdr>() {
                    return false;
                }
                let udp = unsafe { &*(pkt[l4_off..].as_ptr() as *const UdpHdr) };
                if ntohs(udp.dst_port) != port {
                    return false;
                }
            }
        }
        6 => {
            if opts.drop_tcp {
                return false;
            }
            if let Some(port) = opts.allow_dst_port {
                if pkt.len() < l4_off + size_of::<TcpHdr>() {
                    return false;
                }
                let tcp = unsafe { &*(pkt[l4_off..].as_ptr() as *const TcpHdr) };
                if ntohs(tcp.dst_port) != port {
                    return false;
                }
            }
        }
        _ => {}
    }

    if let Some(mac) = rewrite_dst_mac {
        eth.dst = mac;
    }

    true
}

fn load_xdp_and_bind_xsk(ifname: &str, queue_id: u32, xdp_obj_path: &str, xsk_fd: i32) -> Result<()> {
    let builder = ObjectBuilder::default();
    let open_obj = builder.open_file(xdp_obj_path).context("open BPF object")?;
    let mut obj = open_obj.load().context("load BPF object")?;

    let prog = obj
        .prog_mut("xdp_sock_prog")
        .ok_or_else(|| anyhow!("program xdp_sock_prog not found"))?;

    let ifindex = ifindex_from_name(ifname)?;
    prog.attach_xdp(ifindex).context("attach xdp")?;

    let map = obj
        .map_mut("xsks_map")
        .ok_or_else(|| anyhow!("xsks_map not found"))?;

    let key = queue_id.to_ne_bytes();
    let val = (xsk_fd as u32).to_ne_bytes();
    map.update(&key, &val, libbpf_rs::MapFlags::ANY)
        .context("update xsks_map")?;

    std::mem::forget(obj); // keep attached for process lifetime in this example
    Ok(())
}

fn main() -> Result<()> {
    let opts = Opts::parse();

    if let Some(core_id) = core_affinity::get_core_ids().and_then(|v| v.get(opts.cpu).cloned()) {
        core_affinity::set_for_current(core_id);
    }

    let rewrite_dst_mac = match &opts.forward_dst_mac {
        Some(m) => Some(parse_mac(m)?),
        None => None,
    };

    let afxdp = AfXdp::new(&opts.ifname, opts.queue_id, opts.frame_size, opts.umem_frames)?;
    load_xdp_and_bind_xsk(&opts.ifname, opts.queue_id, &opts.xdp_obj, afxdp.fd())?;

    let running = Arc::new(AtomicBool::new(true));
    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    let mut stats = Stats::new();
    let mut last = Instant::now();

    while running.load(Ordering::Relaxed) {
        // Recycle completed TX frames back to fill ring.
        let mut comp_idx = 0u32;
        let completed = unsafe {
            xsk_ring_cons__peek(
                afxdp.comp.as_ptr() as *mut xsk_ring_cons,
                256,
                &mut comp_idx,
            )
        };
        if completed > 0 {
            let mut fill_idx = 0u32;
            let reserved = unsafe {
                xsk_ring_prod__reserve(
                    afxdp.fill.as_ptr() as *mut xsk_ring_prod,
                    completed,
                    &mut fill_idx,
                )
            };
            if reserved == completed as i32 {
                for i in 0..completed {
                    let addr = unsafe {
                        *xsk_ring_cons__comp_addr(
                            afxdp.comp.as_ptr() as *mut xsk_ring_cons,
                            comp_idx + i,
                        )
                    };
                    unsafe {
                        *xsk_ring_prod__fill_addr(
                            afxdp.fill.as_ptr() as *mut xsk_ring_prod,
                            fill_idx + i,
                        ) = addr;
                    }
                }
                unsafe {
                    xsk_ring_prod__submit(afxdp.fill.as_ptr() as *mut xsk_ring_prod, completed);
                    xsk_ring_cons__release(afxdp.comp.as_ptr() as *mut xsk_ring_cons, completed);
                }
            }
        }

        let mut rx_idx = 0u32;
        let received = unsafe {
            xsk_ring_cons__peek(
                afxdp.rx.as_ptr() as *mut xsk_ring_cons,
                64,
                &mut rx_idx,
            )
        };
        if received == 0 {
            std::hint::spin_loop();
            continue;
        }

        let mut tx_idx = 0u32;
        let tx_reserved = unsafe {
            xsk_ring_prod__reserve(
                afxdp.tx.as_ptr() as *mut xsk_ring_prod,
                received,
                &mut tx_idx,
            )
        };

        let tx_budget = if tx_reserved < 0 { 0 } else { tx_reserved as u32 };

        for i in 0..received {
            let desc = unsafe {
                *xsk_ring_cons__rx_desc(afxdp.rx.as_ptr() as *mut xsk_ring_cons, rx_idx + i)
            };
            stats.rx += 1;

            let ptr = afxdp.frame_ptr(desc.addr);
            let pkt = unsafe { std::slice::from_raw_parts_mut(ptr, desc.len as usize) };

            let allowed = packet_allowed(pkt, &opts, rewrite_dst_mac);
            if !allowed {
                stats.filtered += 1;

                // Recycle dropped frame directly to fill ring later via tx completion path is not possible,
                // so put it back immediately if fill ring has space.
                let mut fill_idx = 0u32;
                let res = unsafe {
                    xsk_ring_prod__reserve(
                        afxdp.fill.as_ptr() as *mut xsk_ring_prod,
                        1,
                        &mut fill_idx,
                    )
                };
                if res == 1 {
                    unsafe {
                        *xsk_ring_prod__fill_addr(
                            afxdp.fill.as_ptr() as *mut xsk_ring_prod,
                            fill_idx,
                        ) = desc.addr;
                        xsk_ring_prod__submit(afxdp.fill.as_ptr() as *mut xsk_ring_prod, 1);
                    }
                } else {
                    stats.dropped += 1;
                }
                continue;
            }

            if i < tx_budget {
                unsafe {
                    let txd = xsk_ring_prod__tx_desc(afxdp.tx.as_ptr() as *mut xsk_ring_prod, tx_idx + i);
                    (*txd).addr = desc.addr;
                    (*txd).len = desc.len;
                    (*txd).options = 0;
                }
                stats.tx += 1;
            } else {
                stats.dropped += 1;
                let mut fill_idx = 0u32;
                let res = unsafe {
                    xsk_ring_prod__reserve(
                        afxdp.fill.as_ptr() as *mut xsk_ring_prod,
                        1,
                        &mut fill_idx,
                    )
                };
                if res == 1 {
                    unsafe {
                        *xsk_ring_prod__fill_addr(
                            afxdp.fill.as_ptr() as *mut xsk_ring_prod,
                            fill_idx,
                        ) = desc.addr;
                        xsk_ring_prod__submit(afxdp.fill.as_ptr() as *mut xsk_ring_prod, 1);
                    }
                }
            }
        }

        unsafe {
            xsk_ring_cons__release(afxdp.rx.as_ptr() as *mut xsk_ring_cons, received);
        }

        if tx_budget > 0 {
            unsafe {
                xsk_ring_prod__submit(afxdp.tx.as_ptr() as *mut xsk_ring_prod, tx_budget);
            }

            // Kick TX path
            let _ = unsafe {
                libc::sendto(
                    afxdp.fd(),
                    null(),
                    0,
                    libc::MSG_DONTWAIT,
                    null(),
                    0,
                )
            };
        }

        if last.elapsed() >= Duration::from_secs(1) {
            eprintln!(
                "rx={} tx={} filtered={} dropped={}",
                stats.rx, stats.tx, stats.filtered, stats.dropped
            );
            last = Instant::now();
        }
    }

    Ok(())
}
