# 2) Userspace loader/control plane in C

This:
- Loads the XDP program
- Attaches it to an interface
- Inserts blocked IPs into the map
- Prints counters

Save as `xdp_filter_user.c`:

```c
// xdp_filter_user.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static volatile sig_atomic_t stop = 0;

static void on_sigint(int signo) {
    (void)signo;
    stop = 1;
}

static int add_block_ip(int map_fd, const char *ip_str) {
    struct in_addr addr;
    if (inet_pton(AF_INET, ip_str, &addr) != 1) {
        fprintf(stderr, "Invalid IP: %s\n", ip_str);
        return -1;
    }

    __u32 key = addr.s_addr; // network byte order
    __u8 value = 1;

    if (bpf_map_update_elem(map_fd, &key, &value, BPF_ANY) != 0) {
        perror("bpf_map_update_elem");
        return -1;
    }

    return 0;
}

static void print_counters(int map_fd) {
    for (__u32 i = 0; i < 3; i++) {
        __u64 values[128] = {0};
        __u32 cpu_cnt = 128;
        __u64 total = 0;

        if (bpf_map_lookup_elem(map_fd, &i, values) == 0) {
            for (__u32 c = 0; c < cpu_cnt; c++)
                total += values[c];

            const char *name =
                (i == 0) ? "drop" :
                (i == 1) ? "pass" : "malformed";

            printf("%s: %llu\n", name, (unsigned long long)total);
        }
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <ifname> <xdp_kern.o> [block_ip...]\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    const char *obj_path = argv[2];
    int ifindex = if_nametoindex(ifname);
    if (!ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    struct bpf_object *obj = NULL;
    int prog_fd = -1, err;
    int blocklist_fd = -1, counters_fd = -1;

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    obj = bpf_object__open_file(obj_path, NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_filter");
    if (!prog) {
        fprintf(stderr, "Program 'xdp_filter' not found\n");
        bpf_object__close(obj);
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0) {
        fprintf(stderr, "Invalid program fd\n");
        bpf_object__close(obj);
        return 1;
    }

    err = bpf_xdp_attach(ifindex, prog_fd, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
    if (err) {
        fprintf(stderr, "Failed to attach XDP program: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    blocklist_fd = bpf_object__find_map_fd_by_name(obj, "blocklist");
    counters_fd = bpf_object__find_map_fd_by_name(obj, "counters");

    if (blocklist_fd < 0 || counters_fd < 0) {
        fprintf(stderr, "Failed to find map fds\n");
        bpf_xdp_detach(ifindex, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
        bpf_object__close(obj);
        return 1;
    }

    for (int i = 3; i < argc; i++) {
        if (add_block_ip(blocklist_fd, argv[i]) != 0) {
            fprintf(stderr, "Failed to add block IP: %s\n", argv[i]);
        }
    }

    printf("XDP filter attached to %s. Press Ctrl+C to exit.\n", ifname);

    while (!stop) {
        sleep(2);
        print_counters(counters_fd);
        printf("----\n");
    }

    bpf_xdp_detach(ifindex, XDP_FLAGS_UPDATE_IF_NOEXIST, NULL);
    bpf_object__close(obj);
    return 0;
}
```

