## `udp_forwarder.cpp`

```cpp
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <linux/if_packet.h>
#include <netinet/in.h>
#include <sched.h>
#include <signal.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#include <array>
#include <atomic>
#include <cstring>
#include <iostream>
#include <optional>
#include <string>
#include <unordered_set>
#include <vector>

static std::atomic<bool> g_running{true};

static void on_signal(int) {
    g_running = false;
}

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

static bool set_socket_buf(int fd, int rcvbuf, int sndbuf) {
    bool ok = true;
    if (setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)) < 0) ok = false;
    if (setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf)) < 0) ok = false;
    return ok;
}

static bool set_reuseaddr(int fd) {
    int one = 1;
    return setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one)) == 0;
}

static bool set_reuseport(int fd) {
#ifdef SO_REUSEPORT
    int one = 1;
    return setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one)) == 0;
#else
    return false;
#endif
}

static bool pin_to_cpu(int cpu_id) {
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu_id, &set);
    return sched_setaffinity(0, sizeof(set), &set) == 0;
}

struct Config {
    std::string listen_ip = "0.0.0.0";
    uint16_t listen_port = 9000;

    std::string forward_ip = "127.0.0.1";
    uint16_t forward_port = 9001;

    int epoll_timeout_ms = 10;
    int batch_size = 32;
    int max_packet_size = 2048;

    int rcvbuf = 4 * 1024 * 1024;
    int sndbuf = 4 * 1024 * 1024;

    bool reuseport = false;
    std::optional<int> cpu_affinity;

    size_t min_payload = 1;
    size_t max_payload = 1500;

    std::optional<uint8_t> first_byte_must_equal;
    std::unordered_set<uint32_t> allowed_src_ipv4; // network byte order
};

static bool parse_ipv4(const std::string& s, uint32_t& out_nbo) {
    in_addr addr{};
    if (inet_pton(AF_INET, s.c_str(), &addr) != 1) return false;
    out_nbo = addr.s_addr;
    return true;
}

static sockaddr_in make_sockaddr(const std::string& ip, uint16_t port) {
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    inet_pton(AF_INET, ip.c_str(), &addr.sin_addr);
    return addr;
}

static bool packet_allowed(
    const Config& cfg,
    const sockaddr_in& src,
    const uint8_t* data,
    size_t len)
{
    if (len < cfg.min_payload || len > cfg.max_payload) {
        return false;
    }

    if (!cfg.allowed_src_ipv4.empty()) {
        if (cfg.allowed_src_ipv4.find(src.sin_addr.s_addr) == cfg.allowed_src_ipv4.end()) {
            return false;
        }
    }

    if (cfg.first_byte_must_equal.has_value()) {
        if (len == 0 || data[0] != *cfg.first_byte_must_equal) {
            return false;
        }
    }

    return true;
}

int main(int argc, char** argv) {
    Config cfg;

    // Minimal CLI parsing for demo purposes.
    // Usage:
    //   ./udp_forwarder <listen_ip> <listen_port> <forward_ip> <forward_port>
    if (argc >= 5) {
        cfg.listen_ip = argv[1];
        cfg.listen_port = static_cast<uint16_t>(std::stoi(argv[2]));
        cfg.forward_ip = argv[3];
        cfg.forward_port = static_cast<uint16_t>(std::stoi(argv[4]));
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (cfg.cpu_affinity.has_value()) {
        if (!pin_to_cpu(*cfg.cpu_affinity)) {
            std::cerr << "warning: failed to pin to CPU " << *cfg.cpu_affinity << "\n";
        }
    }

    int rx_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (rx_fd < 0) {
        std::cerr << "socket(rx) failed: " << strerror(errno) << "\n";
        return 1;
    }

    int tx_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (tx_fd < 0) {
        std::cerr << "socket(tx) failed: " << strerror(errno) << "\n";
        close(rx_fd);
        return 1;
    }

    set_reuseaddr(rx_fd);
    if (cfg.reuseport) set_reuseport(rx_fd);
    set_socket_buf(rx_fd, cfg.rcvbuf, cfg.sndbuf);
    set_socket_buf(tx_fd, cfg.rcvbuf, cfg.sndbuf);

    if (set_nonblocking(rx_fd) < 0 || set_nonblocking(tx_fd) < 0) {
        std::cerr << "set_nonblocking failed: " << strerror(errno) << "\n";
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    sockaddr_in listen_addr = make_sockaddr(cfg.listen_ip, cfg.listen_port);
    if (bind(rx_fd, reinterpret_cast<sockaddr*>(&listen_addr), sizeof(listen_addr)) < 0) {
        std::cerr << "bind failed: " << strerror(errno) << "\n";
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    sockaddr_in forward_addr = make_sockaddr(cfg.forward_ip, cfg.forward_port);

    int epfd = epoll_create1(0);
    if (epfd < 0) {
        std::cerr << "epoll_create1 failed: " << strerror(errno) << "\n";
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    epoll_event ev{};
    ev.events = EPOLLIN | EPOLLET;
    ev.data.fd = rx_fd;
    if (epoll_ctl(epfd, EPOLL_CTL_ADD, rx_fd, &ev) < 0) {
        std::cerr << "epoll_ctl failed: " << strerror(errno) << "\n";
        close(epfd);
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    const int BATCH = cfg.batch_size;
    const int MAXSZ = cfg.max_packet_size;

    std::vector<std::array<uint8_t, 65536>> buffers(BATCH);
    std::vector<mmsghdr> rx_msgs(BATCH);
    std::vector<iovec> rx_iov(BATCH);
    std::vector<sockaddr_in> src_addrs(BATCH);

    std::vector<mmsghdr> tx_msgs(BATCH);
    std::vector<iovec> tx_iov(BATCH);

    for (int i = 0; i < BATCH; ++i) {
        std::memset(&rx_msgs[i], 0, sizeof(mmsghdr));
        std::memset(&tx_msgs[i], 0, sizeof(mmsghdr));

        rx_iov[i].iov_base = buffers[i].data();
        rx_iov[i].iov_len = MAXSZ;

        rx_msgs[i].msg_hdr.msg_iov = &rx_iov[i];
        rx_msgs[i].msg_hdr.msg_iovlen = 1;
        rx_msgs[i].msg_hdr.msg_name = &src_addrs[i];
        rx_msgs[i].msg_hdr.msg_namelen = sizeof(sockaddr_in);
    }

    std::cout << "listening on " << cfg.listen_ip << ":" << cfg.listen_port
              << ", forwarding to " << cfg.forward_ip << ":" << cfg.forward_port << "\n";

    uint64_t pkts_rx = 0, pkts_fwd = 0, pkts_drop = 0;

    std::array<epoll_event, 16> events{};

    while (g_running.load(std::memory_order_relaxed)) {
        int n = epoll_wait(epfd, events.data(), static_cast<int>(events.size()), cfg.epoll_timeout_ms);
        if (n < 0) {
            if (errno == EINTR) continue;
            std::cerr << "epoll_wait failed: " << strerror(errno) << "\n";
            break;
        }

        if (n == 0) continue;

        for (int ei = 0; ei < n; ++ei) {
            if (events[ei].data.fd != rx_fd) continue;

            while (true) {
                for (int i = 0; i < BATCH; ++i) {
                    rx_msgs[i].msg_len = 0;
                    rx_msgs[i].msg_hdr.msg_namelen = sizeof(sockaddr_in);
                }

                int recvd = recvmmsg(rx_fd, rx_msgs.data(), BATCH, 0, nullptr);
                if (recvd < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) break;
                    if (errno == EINTR) continue;
                    std::cerr << "recvmmsg failed: " << strerror(errno) << "\n";
                    break;
                }

                if (recvd == 0) break;

                pkts_rx += recvd;

                int tx_count = 0;
                for (int i = 0; i < recvd; ++i) {
                    size_t len = rx_msgs[i].msg_len;
                    uint8_t* data = buffers[i].data();
                    const sockaddr_in& src = src_addrs[i];

                    if (!packet_allowed(cfg, src, data, len)) {
                        ++pkts_drop;
                        continue;
                    }

                    std::memset(&tx_msgs[tx_count], 0, sizeof(mmsghdr));
                    tx_iov[tx_count].iov_base = data;
                    tx_iov[tx_count].iov_len = len;

                    tx_msgs[tx_count].msg_hdr.msg_iov = &tx_iov[tx_count];
                    tx_msgs[tx_count].msg_hdr.msg_iovlen = 1;
                    tx_msgs[tx_count].msg_hdr.msg_name = &forward_addr;
                    tx_msgs[tx_count].msg_hdr.msg_namelen = sizeof(forward_addr);
                    ++tx_count;
                }

                if (tx_count > 0) {
                    int sent_total = 0;
                    while (sent_total < tx_count) {
                        int sent = sendmmsg(tx_fd, tx_msgs.data() + sent_total, tx_count - sent_total, 0);
                        if (sent < 0) {
                            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                                break;
                            }
                            if (errno == EINTR) continue;
                            std::cerr << "sendmmsg failed: " << strerror(errno) << "\n";
                            break;
                        }
                        sent_total += sent;
                    }
                    pkts_fwd += sent_total;
                    pkts_drop += (tx_count - sent_total);
                }
            }
        }
    }

    std::cout << "stats: rx=" << pkts_rx
              << " fwd=" << pkts_fwd
              << " drop=" << pkts_drop << "\n";

    close(epfd);
    close(rx_fd);
    close(tx_fd);
    return 0;
}
