```rust
use anyhow::{anyhow, Context, Result};
use libc::{
    c_void, setsockopt, sock_filter, sock_fprog, sockaddr_ll, AF_PACKET, ETH_P_ALL, IFNAMSIZ,
    PACKET_OUTGOING, SOCK_RAW, SOL_SOCKET, SO_ATTACH_FILTER,
};
use nix::sched::{sched_setaffinity, CpuSet};
use nix::sys::socket::{bind, recv, send, socket, AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType};
use nix::unistd::close;
use std::env;
use std::ffi::CString;
use std::mem::{size_of, zeroed};
use std::os::fd::{AsRawFd, OwnedFd};
use std::sync::Arc;
use std::thread;

const MAX_FRAME: usize = 2048;

/// Example classic BPF:
/// Accept only IPv4 Ethernet frames (ethertype 0x0800).
fn ipv4_eth_bpf() -> Vec<sock_filter> {
    vec![
        // Load half-word at Ethernet type offset 12
        sock_filter { code: 0x28, jt: 0, jf: 0, k: 12 },
        // Jump if == 0x0800
        sock_filter { code: 0x15, jt: 0, jf: 1, k: 0x0800 },
        // Accept packet
        sock_filter { code: 0x06, jt: 0, jf: 0, k: 0xFFFF },
        // Reject packet
        sock_filter { code: 0x06, jt: 0, jf: 0, k: 0 },
    ]
}

fn attach_bpf(fd: i32, prog: &[sock_filter]) -> Result<()> {
    let mut fprog = sock_fprog {
        len: prog.len() as u16,
        filter: prog.as_ptr() as *mut sock_filter,
    };

    let rc = unsafe {
        setsockopt(
            fd,
            SOL_SOCKET,
            SO_ATTACH_FILTER,
            &mut fprog as *mut _ as *const c_void,
            size_of::<sock_fprog>() as u32,
        )
    };

    if rc != 0 {
        return Err(anyhow!("SO_ATTACH_FILTER failed: {}", std::io::Error::last_os_error()));
    }
    Ok(())
}

fn if_nametoindex(name: &str) -> Result<u32> {
    let cstr = CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(cstr.as_ptr()) };
    if idx == 0 {
        Err(anyhow!("if_nametoindex({name}) failed: {}", std::io::Error::last_os_error()))
    } else {
        Ok(idx)
    }
}

fn bind_packet_socket(fd: i32, ifindex: u32) -> Result<()> {
    let mut addr: sockaddr_ll = unsafe { zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_protocol = (ETH_P_ALL as u16).to_be();
    addr.sll_ifindex = ifindex as i32;

    let sockaddr = nix::sys::socket::SockaddrStorage::from_raw(
        &addr as *const _ as *const libc::sockaddr,
        Some(size_of::<sockaddr_ll>() as libc::socklen_t),
    )
    .ok_or_else(|| anyhow!("failed to create sockaddr"))?;

    bind(fd, &sockaddr).context("bind packet socket failed")?;
    Ok(())
}

fn set_cpu_affinity(cpu: usize) -> Result<()> {
    let mut cpuset = CpuSet::new();
    cpuset.set(cpu)?;
    sched_setaffinity(nix::unistd::Pid::from_raw(0), &cpuset)?;
    Ok(())
}

/// Very small userspace filter:
/// - Ethernet II
/// - IPv4
/// - UDP dst port == 9000
fn should_forward(frame: &[u8]) -> bool {
    if frame.len() < 14 {
        return false;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return false;
    }

    if frame.len() < 14 + 20 {
        return false;
    }

    let ip_start = 14;
    let version_ihl = frame[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0F) as usize * 4;

    if version != 4 || frame.len() < ip_start + ihl + 8 {
        return false;
    }

    let proto = frame[ip_start + 9];
    if proto != 17 {
        return false;
    }

    let udp_start = ip_start + ihl;
    let dst_port = u16::from_be_bytes([frame[udp_start + 2], frame[udp_start + 3]]);
    dst_port == 9000
}

fn make_packet_socket() -> Result<OwnedFd> {
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::empty(),
        Some(SockProtocol::EthAll),
    )
    .context("socket(AF_PACKET, SOCK_RAW) failed")?;
    Ok(fd)
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("usage: {} <rx_if> <tx_if> <cpu>", args[0]);
        std::process::exit(1);
    }

    let rx_if = &args[1];
    let tx_if = &args[2];
    let cpu: usize = args[3].parse().context("invalid cpu")?;

    set_cpu_affinity(cpu).context("failed to set CPU affinity")?;

    let rx_ifindex = if_nametoindex(rx_if)?;
    let tx_ifindex = if_nametoindex(tx_if)?;

    let rx_fd = make_packet_socket()?;
    let tx_fd = make_packet_socket()?;

    bind_packet_socket(rx_fd.as_raw_fd(), rx_ifindex)?;
    bind_packet_socket(tx_fd.as_raw_fd(), tx_ifindex)?;

    let bpf = ipv4_eth_bpf();
    attach_bpf(rx_fd.as_raw_fd(), &bpf)?;

    let rx_fd = Arc::new(rx_fd);
    let tx_fd = Arc::new(tx_fd);

    let rx_thread = {
        let rx_fd = Arc::clone(&rx_fd);
        let tx_fd = Arc::clone(&tx_fd);

        thread::spawn(move || -> Result<()> {
            let mut buf = [0u8; MAX_FRAME];

            loop {
                let n = recv(rx_fd.as_raw_fd(), &mut buf, MsgFlags::empty())
                    .context("recv failed")?;

                if n == 0 || n > buf.len() {
                    continue;
                }

                let frame = &buf[..n];

                // Ignore outgoing looped packets if visible
                if frame.len() >= 14 {
                    // This is just a placeholder note; PACKET_OUTGOING is metadata-based,
                    // not directly available from plain recv() payload here.
                }

                if !should_forward(frame) {
                    continue;
                }

                // Forward as-is
                let sent = send(tx_fd.as_raw_fd(), frame, MsgFlags::empty())
                    .context("send failed")?;

                if sent != frame.len() {
                    return Err(anyhow!("short send: {} != {}", sent, frame.len()));
                }
            }
        })
    };

    match rx_thread.join() {
        Ok(r) => r,
        Err(_) => Err(anyhow!("worker thread panicked")),
    }?;

    let _ = close(rx_fd.as_raw_fd());
    let _ = close(tx_fd.as_raw_fd());

    Ok(())
}
```

