# 1. Rust service skeleton

```rust
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::time::Duration;
use std::{io, thread};

#[repr(C, packed)]
#[derive(Clone, Copy, Debug)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy, Debug)]
struct Ipv4Hdr {
    version_ihl: u8,
    dscp_ecn: u8,
    total_length: u16,
    identification: u16,
    flags_fragment: u16,
    ttl: u8,
    protocol: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

#[derive(Clone, Debug)]
struct FilterRule {
    drop_src: Option<Ipv4Addr>,
    drop_dst: Option<Ipv4Addr>,
    allow_proto: Option<u8>,
}

impl FilterRule {
    #[inline(always)]
    fn matches(&self, src: Ipv4Addr, dst: Ipv4Addr, proto: u8) -> bool {
        if let Some(s) = self.drop_src {
            if s == src {
                return true;
            }
        }
        if let Some(d) = self.drop_dst {
            if d == dst {
                return true;
            }
        }
        if let Some(p) = self.allow_proto {
            if p != proto {
                return true;
            }
        }
        false
    }
}

#[derive(Clone)]
struct Config {
    ifname_in: String,
    ifname_out: String,
    queue_id: u32,
    batch_size: usize,
    rules: Arc<Vec<FilterRule>>,
}

fn parse_ethhdr(buf: &[u8]) -> Option<EthHdr> {
    if buf.len() < 14 {
        return None;
    }
    let mut dst = [0u8; 6];
    let mut src = [0u8; 6];
    dst.copy_from_slice(&buf[0..6]);
    src.copy_from_slice(&buf[6..12]);
    let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    Some(EthHdr { dst, src, ethertype })
}

fn parse_ipv4hdr(buf: &[u8]) -> Option<Ipv4Hdr> {
    if buf.len() < 20 {
        return None;
    }
    Some(Ipv4Hdr {
        version_ihl: buf[0],
        dscp_ecn: buf[1],
        total_length: u16::from_be_bytes([buf[2], buf[3]]),
        identification: u16::from_be_bytes([buf[4], buf[5]]),
        flags_fragment: u16::from_be_bytes([buf[6], buf[7]]),
        ttl: buf[8],
        protocol: buf[9],
        checksum: u16::from_be_bytes([buf[10], buf[11]]),
        src: u32::from_be_bytes([buf[12], buf[13], buf[14], buf[15]]),
        dst: u32::from_be_bytes([buf[16], buf[17], buf[18], buf[19]]),
    })
}

#[inline(always)]
fn ipv4_from_u32_be(v: u32) -> Ipv4Addr {
    Ipv4Addr::from(v)
}

/// Decide whether to drop packet.
/// Returns true => drop, false => forward.
#[inline(always)]
fn should_drop(packet: &[u8], rules: &[FilterRule]) -> bool {
    let eth = match parse_ethhdr(packet) {
        Some(h) => h,
        None => return true,
    };

    // IPv4 only in this minimal example
    if eth.ethertype != 0x0800 {
        return true;
    }

    let ip_off = 14;
    let ip = match parse_ipv4hdr(&packet[ip_off..]) {
        Some(h) => h,
        None => return true,
    };

    let ihl = (ip.version_ihl & 0x0f) as usize * 4;
    if ihl < 20 || packet.len() < ip_off + ihl {
        return true;
    }

    let src = ipv4_from_u32_be(ip.src);
    let dst = ipv4_from_u32_be(ip.dst);
    let proto = ip.protocol;

    for rule in rules {
        if rule.matches(src, dst, proto) {
            return true;
        }
    }

    false
}

// -----------------------------------------------------------------------------
// AF_XDP abstraction placeholder
// In a real implementation, use a crate or FFI bindings to libbpf / xsk.
// -----------------------------------------------------------------------------

struct PacketBuf<'a> {
    data: &'a mut [u8],
}

struct RxTxSocket {
    _ifname: String,
    _queue_id: u32,
}

impl RxTxSocket {
    fn open(ifname: &str, queue_id: u32) -> io::Result<Self> {
        Ok(Self {
            _ifname: ifname.to_string(),
            _queue_id: queue_id,
        })
    }

    /// Receive a batch of packets.
    /// Real AF_XDP would return descriptors into UMEM.
    fn recv_batch<'a>(&'a mut self, _max: usize) -> io::Result<Vec<PacketBuf<'a>>> {
        Ok(Vec::new())
    }

    /// Transmit a batch of packets.
    fn send_batch<'a>(&'a mut self, _pkts: Vec<PacketBuf<'a>>) -> io::Result<usize> {
        Ok(0)
    }

    fn recycle_completions(&mut self) -> io::Result<()> {
        Ok(())
    }
}

fn worker(cfg: Config) -> io::Result<()> {
    let mut rx = RxTxSocket::open(&cfg.ifname_in, cfg.queue_id)?;
    let mut tx = RxTxSocket::open(&cfg.ifname_out, cfg.queue_id)?;

    loop {
        let batch = rx.recv_batch(cfg.batch_size)?;
        if batch.is_empty() {
            std::hint::spin_loop();
            continue;
        }

        let mut forward = Vec::with_capacity(batch.len());

        for mut pkt in batch {
            let data: &mut [u8] = pkt.data;

            if should_drop(data, &cfg.rules) {
                // drop: just let buffer be recycled by UMEM completion logic in real impl
                continue;
            }

            // Example forwarding tweak:
            // decrement TTL for IPv4 packets and update checksum incrementally
            if data.len() >= 14 + 20 {
                let ethertype = u16::from_be_bytes([data[12], data[13]]);
                if ethertype == 0x0800 {
                    let ip_off = 14;
                    let ttl_off = ip_off + 8;
                    let csum_off = ip_off + 10;

                    if data[ttl_off] > 1 {
                        data[ttl_off] -= 1;

                        // incremental checksum update for TTL decrement
                        let old_csum = u16::from_be_bytes([data[csum_off], data[csum_off + 1]]);
                        let new_csum = old_csum.wrapping_add(0x0100);
                        data[csum_off..csum_off + 2].copy_from_slice(&new_csum.to_be_bytes());
                    } else {
                        continue;
                    }
                }
            }

            forward.push(pkt);
        }

        if !forward.is_empty() {
            let _sent = tx.send_batch(forward)?;
        }

        tx.recycle_completions()?;
    }
}

fn main() -> io::Result<()> {
    let cfg = Config {
        ifname_in: "eth0".to_string(),
        ifname_out: "eth1".to_string(),
        queue_id: 0,
        batch_size: 64,
        rules: Arc::new(vec![
            FilterRule {
                drop_src: Some("10.0.0.1".parse().unwrap()),
                drop_dst: None,
                allow_proto: None,
            },
            FilterRule {
                drop_src: None,
                drop_dst: Some("192.168.1.10".parse().unwrap()),
                allow_proto: None,
            },
            FilterRule {
                drop_src: None,
                drop_dst: None,
                allow_proto: Some(17), // allow only UDP, drop others
            },
        ]),
    };

    let worker_cfg = cfg.clone();
    let handle = thread::spawn(move || worker(worker_cfg));

    loop {
        thread::sleep(Duration::from_secs(5));
        // stats/reporting hook
        if handle.is_finished() {
            break;
        }
    }

    handle.join().unwrap()
}
```

