```rust
use anyhow::{anyhow, Context, Result};
use mio::unix::SourceFd;
use mio::{Events, Interest, Poll, Token};
use std::env;
use std::ffi::CString;
use std::mem::{size_of, zeroed};
use std::os::fd::RawFd;

const TOKEN_A: Token = Token(0);
const TOKEN_B: Token = Token(1);
const ETH_P_ALL: u16 = 0x0003;

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn if_nametoindex(name: &str) -> Result<u32> {
    let c = CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(anyhow!("if_nametoindex failed for {}", name))
    } else {
        Ok(idx)
    }
}

fn make_raw_socket(iface: &str) -> Result<RawFd> {
    let fd = unsafe {
        libc::socket(
            libc::AF_PACKET,
            libc::SOCK_RAW | libc::SOCK_NONBLOCK | libc::SOCK_CLOEXEC,
            htons(ETH_P_ALL) as i32,
        )
    };
    if fd < 0 {
        return Err(anyhow!("socket(AF_PACKET) failed"));
    }

    let ifindex = if_nametoindex(iface)?;
    let mut sll: libc::sockaddr_ll = unsafe { zeroed() };
    sll.sll_family = libc::AF_PACKET as u16;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex as i32;

    let rc = unsafe {
        libc::bind(
            fd,
            &sll as *const _ as *const libc::sockaddr,
            size_of::<libc::sockaddr_ll>() as libc::socklen_t,
        )
    };
    if rc < 0 {
        unsafe { libc::close(fd) };
        return Err(anyhow!("bind() failed on {}", iface));
    }

    Ok(fd)
}

fn recv_frame(fd: RawFd, buf: &mut [u8]) -> Result<usize> {
    let n = unsafe { libc::recv(fd, buf.as_mut_ptr() as *mut _, buf.len(), 0) };
    if n < 0 {
        let err = std::io::Error::last_os_error();
        if err.kind() == std::io::ErrorKind::WouldBlock {
            Ok(0)
        } else {
            Err(err).context("recv failed")
        }
    } else {
        Ok(n as usize)
    }
}

fn send_frame(fd: RawFd, buf: &[u8]) -> Result<usize> {
    let n = unsafe { libc::send(fd, buf.as_ptr() as *const _, buf.len(), 0) };
    if n < 0 {
        let err = std::io::Error::last_os_error();
        if err.kind() == std::io::ErrorKind::WouldBlock {
            Ok(0)
        } else {
            Err(err).context("send failed")
        }
    } else {
        Ok(n as usize)
    }
}

/// Very simple Ethernet/IPv4/UDP filter:
/// - allow ARP
/// - allow IPv4 UDP dst port 53
/// - drop everything else
fn allow_frame(frame: &[u8]) -> bool {
    if frame.len() < 14 {
        return false;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    match ethertype {
        0x0806 => true, // ARP
        0x0800 => {
            if frame.len() < 14 + 20 {
                return false;
            }
            let ip = &frame[14..];
            let version = ip[0] >> 4;
            if version != 4 {
                return false;
            }
            let ihl = (ip[0] & 0x0f) as usize * 4;
            if ihl < 20 || ip.len() < ihl + 8 {
                return false;
            }
            let proto = ip[9];
            if proto != 17 {
                return false; // UDP only
            }
            let udp = &ip[ihl..];
            let dst_port = u16::from_be_bytes([udp[2], udp[3]]);
            dst_port == 53
        }
        _ => false,
    }
}

fn pump(src_fd: RawFd, dst_fd: RawFd, label: &str) -> Result<()> {
    let mut buf = [0u8; 2048];

    loop {
        let n = recv_frame(src_fd, &mut buf)?;
        if n == 0 {
            break;
        }

        let frame = &buf[..n];
        if allow_frame(frame) {
            let sent = send_frame(dst_fd, frame)?;
            if sent == 0 {
                eprintln!("[{}] drop due to backpressure", label);
            }
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        return Err(anyhow!("usage: {} <iface-a> <iface-b>", args[0]));
    }

    let iface_a = &args[1];
    let iface_b = &args[2];

    let fd_a = make_raw_socket(iface_a)?;
    let fd_b = make_raw_socket(iface_b)?;

    let mut poll = Poll::new()?;
    let mut events = Events::with_capacity(1024);

    let mut src_a = SourceFd(&fd_a);
    let mut src_b = SourceFd(&fd_b);

    poll.registry()
        .register(&mut src_a, TOKEN_A, Interest::READABLE)?;
    poll.registry()
        .register(&mut src_b, TOKEN_B, Interest::READABLE)?;

    eprintln!("forwarding between {} <-> {}", iface_a, iface_b);

    loop {
        poll.poll(&mut events, None)?;

        for event in events.iter() {
            match event.token() {
                TOKEN_A => {
                    pump(fd_a, fd_b, "A->B")?;
                }
                TOKEN_B => {
                    pump(fd_b, fd_a, "B->A")?;
                }
                _ => {}
            }
        }
    }
}
