use anyhow::{Context, Result};
use socket2::{Domain, Protocol, Socket, Type};
use std::collections::HashSet;
use std::net::{IpAddr, Ipv4Addr, SocketAddr};
use std::sync::Arc;
use tokio::net::UdpSocket;

#[derive(Clone)]
struct FilterConfig {
    allowed_sources: Arc<HashSet<IpAddr>>,
    allowed_dest_ports: Arc<HashSet<u16>>,
    max_packet_size: usize,
}

impl FilterConfig {
    fn allow_packet(&self, src: SocketAddr, local_dst_port: u16, len: usize) -> bool {
        if len == 0 || len > self.max_packet_size {
            return false;
        }

        if !self.allowed_sources.is_empty() && !self.allowed_sources.contains(&src.ip()) {
            return false;
        }

        if !self.allowed_dest_ports.is_empty() && !self.allowed_dest_ports.contains(&local_dst_port) {
            return false;
        }

        true
    }
}

fn make_udp_socket(bind_addr: SocketAddr) -> Result<std::net::UdpSocket> {
    let domain = match bind_addr {
        SocketAddr::V4(_) => Domain::IPV4,
        SocketAddr::V6(_) => Domain::IPV6,
    };

    let socket = Socket::new(domain, Type::DGRAM, Some(Protocol::UDP))
        .context("failed to create UDP socket")?;

    socket.set_reuse_address(true).ok();

    #[cfg(target_os = "linux")]
    {
        let _ = socket.set_recv_buffer_size(4 * 1024 * 1024);
        let _ = socket.set_send_buffer_size(4 * 1024 * 1024);
    }

    socket
        .bind(&bind_addr.into())
        .context("failed to bind UDP socket")?;

    socket
        .set_nonblocking(true)
        .context("failed to set nonblocking")?;

    Ok(socket.into())
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    let listen_addr: SocketAddr = "0.0.0.0:9000".parse()?;
    let upstream_addr: SocketAddr = "127.0.0.1:10000".parse()?;

    let mut allowed_sources = HashSet::new();
    allowed_sources.insert(IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)));

    let mut allowed_ports = HashSet::new();
    allowed_ports.insert(9000);

    let filter = FilterConfig {
        allowed_sources: Arc::new(allowed_sources),
        allowed_dest_ports: Arc::new(allowed_ports),
        max_packet_size: 2048,
    };

    let std_sock = make_udp_socket(listen_addr)?;
    let recv_sock = UdpSocket::from_std(std_sock).context("failed to convert socket")?;

    let send_std = make_udp_socket("0.0.0.0:0".parse()?)?;
    let send_sock = UdpSocket::from_std(send_std).context("failed to convert send socket")?;

    let local_port = listen_addr.port();
    let mut buf = vec![0u8; 65535];

    loop {
        let (len, src) = recv_sock
            .recv_from(&mut buf)
            .await
            .context("recv_from failed")?;

        if !filter.allow_packet(src, local_port, len) {
            continue;
        }

        let packet = &buf[..len];

        match send_sock.send_to(packet, upstream_addr).await {
            Ok(_) => {}
            Err(e) => {
                eprintln!("forward error: {e}");
            }
        }
    }
}
