# 1) XDP/eBPF filter program

This XDP program:

- parses Ethernet / IPv4 / TCP / UDP
- drops malformed packets
- optionally drops packets to blocked destination ports
- passes allowed packets to user space via **XSKMAP** (AF_XDP socket redirect)

## `xdp_filter_kern.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct {
    __uint(type, BPF_MAP_TYPE_XSKMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} xsks_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u16);   // blocked destination port
    __type(value, __u8);  // 1 = blocked
} blocked_ports SEC(".maps");

static __always_inline int parse_ipv4_l4(void *data, void *data_end, __u16 *proto, __u16 *dport)
{
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return -1;

    if (iph->ihl < 5)
        return -1;

    void *l4 = (void *)iph + iph->ihl * 4;
    if (l4 > data_end)
        return -1;

    *proto = iph->protocol;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end)
            return -1;
        *dport = bpf_ntohs(tcp->dest);
        return 0;
    }

    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end)
            return -1;
        *dport = bpf_ntohs(udp->dest);
        return 0;
    }

    return -1;
}

SEC("xdp")
int xdp_filter_redirect(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    __u16 proto = 0, dport = 0;

    if (parse_ipv4_l4(data, data_end, &proto, &dport) == 0) {
        __u8 *blocked = bpf_map_lookup_elem(&blocked_ports, &dport);
        if (blocked && *blocked == 1)
            return XDP_DROP;
    }

    __u32 rxq = ctx->rx_queue_index;
    if (bpf_map_lookup_elem(&xsks_map, &rxq))
        return bpf_redirect_map(&xsks_map, rxq, 0);

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```

