## `xdp_forwarder.c`

```c
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <linux/if_link.h>
#include <linux/if_packet.h>
#include <linux/if_xdp.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <poll.h>
#include <sched.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>
#include <arpa/inet.h>

#include <bpf/bpf.h>
#include <bpf/libbpf.h>
#include <xdp/xsk.h>

#define NUM_FRAMES      4096
#define FRAME_SIZE      XSK_UMEM__DEFAULT_FRAME_SIZE
#define UMEM_SIZE       (NUM_FRAMES * FRAME_SIZE)
#define RX_BATCH_SIZE   64

static volatile bool running = true;

struct xsk_umem_info {
    struct xsk_umem *umem;
    void *buffer;
    struct xsk_ring_prod fq;
    struct xsk_ring_cons cq;
};

struct xsk_socket_info {
    struct xsk_socket *xsk;
    struct xsk_ring_cons rx;
    struct xsk_ring_prod tx;
    struct xsk_umem_info *umem;
    uint32_t outstanding_tx;
    uint64_t umem_frame_addr[NUM_FRAMES];
    uint32_t umem_frame_free;
};

static void int_exit(int sig) {
    (void)sig;
    running = false;
}

static int set_rlimit(void) {
    struct rlimit r = {RLIM_INFINITY, RLIM_INFINITY};
    return setrlimit(RLIMIT_MEMLOCK, &r);
}

static int create_raw_tx_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex(ifname);

    if (sll.sll_ifindex == 0) {
        perror("if_nametoindex");
        close(fd);
        return -1;
    }

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind(AF_PACKET)");
        close(fd);
        return -1;
    }

    return fd;
}

static uint64_t alloc_umem_frame(struct xsk_socket_info *xsk) {
    if (xsk->umem_frame_free == 0)
        return UINT64_MAX;
    return xsk->umem_frame_addr[--xsk->umem_frame_free];
}

static void free_umem_frame(struct xsk_socket_info *xsk, uint64_t addr) {
    if (xsk->umem_frame_free < NUM_FRAMES)
        xsk->umem_frame_addr[xsk->umem_frame_free++] = addr;
}

static int xsk_configure_umem(struct xsk_umem_info *umem) {
    umem->buffer = mmap(NULL, UMEM_SIZE, PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS | MAP_POPULATE, -1, 0);
    if (umem->buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    struct xsk_umem_config cfg = {
        .fill_size = NUM_FRAMES,
        .comp_size = NUM_FRAMES,
        .frame_size = FRAME_SIZE,
        .frame_headroom = 0,
        .flags = 0,
    };

    int ret = xsk_umem__create(&umem->umem, umem->buffer, UMEM_SIZE,
                               &umem->fq, &umem->cq, &cfg);
    if (ret) {
        fprintf(stderr, "xsk_umem__create: %d\n", ret);
        return -1;
    }

    return 0;
}

static int xsk_configure_socket(struct xsk_socket_info *xsk, struct xsk_umem_info *umem,
                                const char *ifname, uint32_t queue_id) {
    xsk->umem = umem;

    for (uint32_t i = 0; i < NUM_FRAMES; i++)
        xsk->umem_frame_addr[i] = i * FRAME_SIZE;
    xsk->umem_frame_free = NUM_FRAMES;

    struct xsk_socket_config cfg = {
        .rx_size = 2048,
        .tx_size = 2048,
        .libbpf_flags = 0,
        .xdp_flags = XDP_FLAGS_UPDATE_IF_NOEXIST,
        .bind_flags = XDP_COPY,
    };

    int ret = xsk_socket__create(&xsk->xsk, ifname, queue_id, umem->umem,
                                 &xsk->rx, &xsk->tx, &cfg);
    if (ret) {
        fprintf(stderr, "xsk_socket__create: %d\n", ret);
        return -1;
    }

    uint32_t idx;
    ret = xsk_ring_prod__reserve(&umem->fq, NUM_FRAMES, &idx);
    if (ret != NUM_FRAMES) {
        fprintf(stderr, "fq reserve failed\n");
        return -1;
    }

    for (uint32_t i = 0; i < NUM_FRAMES; i++)
        *xsk_ring_prod__fill_addr(&umem->fq, idx + i) = xsk->umem_frame_addr[--xsk->umem_frame_free];

    xsk_ring_prod__submit(&umem->fq, NUM_FRAMES);
    return 0;
}

static int forward_packet(int tx_fd, const uint8_t *pkt, size_t len) {
    ssize_t n = send(tx_fd, pkt, len, MSG_DONTWAIT);
    if (n < 0) {
        if (errno != EAGAIN && errno != EWOULDBLOCK)
            perror("send");
        return -1;
    }
    return 0;
}

static bool userspace_policy_allow(const uint8_t *pkt, size_t len) {
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return false;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return true;

    const struct iphdr *iph = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
    if ((const uint8_t *)(iph + 1) > pkt + len)
        return false;

    if (iph->protocol == IPPROTO_ICMP)
        return false; // example policy: drop ICMP in user space

    return true;
}

static void complete_tx(struct xsk_socket_info *xsk) {
    uint32_t idx_cq;
    unsigned int rcvd = xsk_ring_cons__peek(&xsk->umem->cq, RX_BATCH_SIZE, &idx_cq);
    if (!rcvd)
        return;

    for (unsigned int i = 0; i < rcvd; i++) {
        uint64_t addr = *xsk_ring_cons__comp_addr(&xsk->umem->cq, idx_cq + i);
        free_umem_frame(xsk, addr);
    }

    xsk_ring_cons__release(&xsk->umem->cq, rcvd);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <in-iface> <queue-id> <out-iface>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    uint32_t queue_id = (uint32_t)atoi(argv[2]);
    const char *out_if = argv[3];

    signal(SIGINT, int_exit);
    signal(SIGTERM, int_exit);

    if (set_rlimit()) {
        perror("setrlimit");
        return 1;
    }

    struct xsk_umem_info umem = {0};
    struct xsk_socket_info xsk = {0};

    if (xsk_configure_umem(&umem))
        return 1;

    if (xsk_configure_socket(&xsk, &umem, in_if, queue_id))
        return 1;

    int tx_fd = create_raw_tx_socket(out_if);
    if (tx_fd < 0)
        return 1;

    struct pollfd fds[] = {
        {
            .fd = xsk_socket__fd(xsk.xsk),
            .events = POLLIN,
        },
    };

    while (running) {
        int ret = poll(fds, 1, 1000);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("poll");
            break;
        }

        uint32_t idx_rx = 0;
        unsigned int rcvd = xsk_ring_cons__peek(&xsk.rx, RX_BATCH_SIZE, &idx_rx);
        if (!rcvd)
            continue;

        for (unsigned int i = 0; i < rcvd; i++) {
            struct xdp_desc *desc = xsk_ring_cons__rx_desc(&xsk.rx, idx_rx + i);
            uint64_t addr = desc->addr;
            uint32_t len = desc->len;

            uint8_t *pkt = xsk_umem__get_data(umem.buffer, addr);

            if (userspace_policy_allow(pkt, len)) {
                forward_packet(tx_fd, pkt, len);
            }

            uint32_t idx_fq;
            while (xsk_ring_prod__reserve(&umem.fq, 1, &idx_fq) != 1) {
                complete_tx(&xsk);
            }
            *xsk_ring_prod__fill_addr(&umem.fq, idx_fq) = addr;
            xsk_ring_prod__submit(&umem.fq, 1);
        }

        xsk_ring_cons__release(&xsk.rx, rcvd);
        complete_tx(&xsk);
    }

    close(tx_fd);
    xsk_socket__delete(xsk.xsk);
    xsk_umem__delete(umem.umem);
    munmap(umem.buffer, UMEM_SIZE);
    return 0;
}
