```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use tokio::{net::UdpSocket, sync::Mutex, time};
use tracing::{debug, error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    listen_addr: String,
    forward_addr: String,
    max_packet_size: usize,
    rate_limit_per_sec: u64,
    filters: Filters,
}

#[derive(Debug, Deserialize, Clone)]
struct Filters {
    drop_empty: bool,
    drop_if_starts_with: Vec<String>,
    allow_only_prefixes: Vec<String>,
}

#[derive(Default)]
struct Stats {
    received: AtomicU64,
    forwarded: AtomicU64,
    dropped_filter: AtomicU64,
    dropped_rate_limit: AtomicU64,
    recv_errors: AtomicU64,
    send_errors: AtomicU64,
}

struct RateLimiter {
    inner: Mutex<HashMap<SocketAddr, TokenBucket>>,
    capacity: u64,
    refill_per_sec: u64,
}

#[derive(Debug)]
struct TokenBucket {
    tokens: f64,
    last_refill: Instant,
}

impl TokenBucket {
    fn new(capacity: u64) -> Self {
        Self {
            tokens: capacity as f64,
            last_refill: Instant::now(),
        }
    }

    fn allow(&mut self, capacity: u64, refill_per_sec: u64) -> bool {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.last_refill = now;

        self.tokens += elapsed * refill_per_sec as f64;
        if self.tokens > capacity as f64 {
            self.tokens = capacity as f64;
        }

        if self.tokens >= 1.0 {
            self.tokens -= 1.0;
            true
        } else {
            false
        }
    }
}

impl RateLimiter {
    fn new(rate_limit_per_sec: u64) -> Self {
        Self {
            inner: Mutex::new(HashMap::new()),
            capacity: rate_limit_per_sec,
            refill_per_sec: rate_limit_per_sec,
        }
    }

    async fn allow(&self, addr: SocketAddr) -> bool {
        let mut guard = self.inner.lock().await;
        let bucket = guard
            .entry(addr)
            .or_insert_with(|| TokenBucket::new(self.capacity));
        bucket.allow(self.capacity, self.refill_per_sec)
    }

    async fn cleanup_idle(&self, max_idle: Duration) {
        let mut guard = self.inner.lock().await;
        let now = Instant::now();
        guard.retain(|_, bucket| now.duration_since(bucket.last_refill) <= max_idle);
    }
}

fn passes_filter(packet: &[u8], filters: &Filters) -> bool {
    if filters.drop_empty && packet.is_empty() {
        return false;
    }

    if !filters.allow_only_prefixes.is_empty() {
        let allowed = filters
            .allow_only_prefixes
            .iter()
            .any(|prefix| packet.starts_with(prefix.as_bytes()));
        if !allowed {
            return false;
        }
    }

    for prefix in &filters.drop_if_starts_with {
        if packet.starts_with(prefix.as_bytes()) {
            return false;
        }
    }

    true
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config_text = std::fs::read_to_string("config.json")
        .context("failed to read config.json")?;
    let config: Config =
        serde_json::from_str(&config_text).context("failed to parse config.json")?;

    let listen_addr: SocketAddr = config.listen_addr.parse()?;
    let forward_addr: SocketAddr = config.forward_addr.parse()?;

    let socket = Arc::new(
        UdpSocket::bind(listen_addr)
            .await
            .with_context(|| format!("failed to bind {}", listen_addr))?,
    );

    let forward_socket = Arc::new(
        UdpSocket::bind("0.0.0.0:0")
            .await
            .context("failed to bind forwarding socket")?,
    );

    let stats = Arc::new(Stats::default());
    let limiter = Arc::new(RateLimiter::new(config.rate_limit_per_sec));
    let cfg = Arc::new(config);

    info!("listening on {}", listen_addr);
    info!("forwarding to {}", forward_addr);

    {
        let stats = Arc::clone(&stats);
        tokio::spawn(async move {
            let mut interval = time::interval(Duration::from_secs(5));
            loop {
                interval.tick().await;
                info!(
                    received = stats.received.load(Ordering::Relaxed),
                    forwarded = stats.forwarded.load(Ordering::Relaxed),
                    dropped_filter = stats.dropped_filter.load(Ordering::Relaxed),
                    dropped_rate_limit = stats.dropped_rate_limit.load(Ordering::Relaxed),
                    recv_errors = stats.recv_errors.load(Ordering::Relaxed),
                    send_errors = stats.send_errors.load(Ordering::Relaxed),
                    "stats"
                );
            }
        });
    }

    {
        let limiter = Arc::clone(&limiter);
        tokio::spawn(async move {
            let mut interval = time::interval(Duration::from_secs(60));
            loop {
                interval.tick().await;
                limiter.cleanup_idle(Duration::from_secs(300)).await;
            }
        });
    }

    let mut buf = vec![0u8; cfg.max_packet_size];

    loop {
        let (len, src) = match socket.recv_from(&mut buf).await {
            Ok(v) => v,
            Err(e) => {
                stats.recv_errors.fetch_add(1, Ordering::Relaxed);
                error!("recv error: {}", e);
                continue;
            }
        };

        stats.received.fetch_add(1, Ordering::Relaxed);
        let packet = &buf[..len];

        if !passes_filter(packet, &cfg.filters) {
            stats.dropped_filter.fetch_add(1, Ordering::Relaxed);
            debug!("dropped by filter from {}", src);
            continue;
        }

        if !limiter.allow(src).await {
            stats.dropped_rate_limit.fetch_add(1, Ordering::Relaxed);
            warn!("rate-limited source {}", src);
            continue;
        }

        match forward_socket.send_to(packet, forward_addr).await {
            Ok(_) => {
                stats.forwarded.fetch_add(1, Ordering::Relaxed);
            }
            Err(e) => {
                stats.send_errors.fetch_add(1, Ordering::Relaxed);
                error!("send error to {}: {}", forward_addr, e);
            }
        }
    }
}
