use anyhow::{anyhow, Result};
use clap::Parser;
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::str::FromStr;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Input interface name
    #[arg(long)]
    in_if: String,

    /// Output interface name
    #[arg(long)]
    out_if: String,

    /// Allow only packets with this destination IPv4 address
    #[arg(long)]
    dst_ip: Option<String>,

    /// Allow only packets with this destination port
    #[arg(long)]
    dst_port: Option<u16>,

    /// Allow only protocol: tcp, udp, or any
    #[arg(long, default_value = "any")]
    proto: String,

    /// Receive buffer read timeout in ms
    #[arg(long, default_value_t = 1)]
    read_timeout_ms: u64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ProtoFilter {
    Any,
    Tcp,
    Udp,
}

impl FromStr for ProtoFilter {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<Self> {
        match s.to_ascii_lowercase().as_str() {
            "any" => Ok(Self::Any),
            "tcp" => Ok(Self::Tcp),
            "udp" => Ok(Self::Udp),
            _ => Err(anyhow!("invalid proto: {}", s)),
        }
    }
}

#[derive(Clone, Debug)]
struct Filter {
    dst_ip: Option<Ipv4Addr>,
    dst_port: Option<u16>,
    proto: ProtoFilter,
}

impl Filter {
    fn matches(&self, frame: &[u8]) -> bool {
        let eth = match EthernetPacket::new(frame) {
            Some(p) => p,
            None => return false,
        };

        if eth.get_ethertype() != EtherTypes::Ipv4 {
            return false;
        }

        let ip = match Ipv4Packet::new(eth.payload()) {
            Some(p) => p,
            None => return false,
        };

        if let Some(expected_ip) = self.dst_ip {
            if ip.get_destination() != expected_ip {
                return false;
            }
        }

        match ip.get_next_level_protocol() {
            IpNextHeaderProtocols::Tcp => {
                if self.proto != ProtoFilter::Any && self.proto != ProtoFilter::Tcp {
                    return false;
                }

                if let Some(expected_port) = self.dst_port {
                    let tcp = match TcpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return false,
                    };
                    if tcp.get_destination() != expected_port {
                        return false;
                    }
                }

                true
            }
            IpNextHeaderProtocols::Udp => {
                if self.proto != ProtoFilter::Any && self.proto != ProtoFilter::Udp {
                    return false;
                }

                if let Some(expected_port) = self.dst_port {
                    let udp = match UdpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return false,
                    };
                    if udp.get_destination() != expected_port {
                        return false;
                    }
                }

                true
            }
            _ => self.proto == ProtoFilter::Any && self.dst_port.is_none(),
        }
    }
}

#[derive(Default)]
struct Stats {
    rx_packets: AtomicU64,
    forwarded_packets: AtomicU64,
    dropped_packets: AtomicU64,
    tx_errors: AtomicU64,
}

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .ok_or_else(|| anyhow!("interface not found: {}", name))
}

fn open_channels(
    iface_in: &NetworkInterface,
    iface_out: &NetworkInterface,
    read_timeout_ms: u64,
) -> Result<(Box<dyn DataLinkReceiver>, Box<dyn DataLinkSender>)> {
    let cfg = Config {
        read_timeout: Some(Duration::from_millis(read_timeout_ms)),
        write_buffer_size: 1 << 20,
        read_buffer_size: 1 << 20,
        promiscuous: true,
        ..Default::default()
    };

    let rx = match datalink::channel(iface_in, cfg.clone())? {
        Channel::Ethernet(_tx, rx) => rx,
        _ => return Err(anyhow!("unsupported input channel type")),
    };

    let tx = match datalink::channel(iface_out, cfg)? {
        Channel::Ethernet(tx, _rx) => tx,
        _ => return Err(anyhow!("unsupported output channel type")),
    };

    Ok((rx, tx))
}

fn main() -> Result<()> {
    let args = Args::parse();

    let filter = Filter {
        dst_ip: match args.dst_ip {
            Some(ip) => Some(ip.parse()?),
            None => None,
        },
        dst_port: args.dst_port,
        proto: ProtoFilter::from_str(&args.proto)?,
    };

    let iface_in = find_interface(&args.in_if)?;
    let iface_out = find_interface(&args.out_if)?;
    let (mut rx, mut tx) = open_channels(&iface_in, &iface_out, args.read_timeout_ms)?;

    let running = Arc::new(AtomicBool::new(true));
    let stats = Arc::new(Stats::default());

    let stats_thread = {
        let running = running.clone();
        let stats = stats.clone();
        thread::spawn(move || {
            let start = Instant::now();
            while running.load(Ordering::Relaxed) {
                thread::sleep(Duration::from_secs(1));
                let elapsed = start.elapsed().as_secs_f64().max(1.0);
                let rx = stats.rx_packets.load(Ordering::Relaxed);
                let fwd = stats.forwarded_packets.load(Ordering::Relaxed);
                let dropc = stats.dropped_packets.load(Ordering::Relaxed);
                let txe = stats.tx_errors.load(Ordering::Relaxed);

                eprintln!(
                    "rx={} fwd={} drop={} tx_err={} rx_pps={:.0} fwd_pps={:.0}",
                    rx,
                    fwd,
                    dropc,
                    txe,
                    rx as f64 / elapsed,
                    fwd as f64 / elapsed
                );
            }
        })
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                stats.rx_packets.fetch_add(1, Ordering::Relaxed);

                if !filter.matches(packet) {
                    stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    continue;
                }

                match tx.send_to(packet, None) {
                    Some(Ok(())) => {
                        stats.forwarded_packets.fetch_add(1, Ordering::Relaxed);
                    }
                    Some(Err(_)) | None => {
                        stats.tx_errors.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Err(_) => {
                // timeout or transient read error
                continue;
            }
        }
    }

    #[allow(unreachable_code)]
    {
        running.store(false, Ordering::Relaxed);
        let _ = stats_thread.join();
        Ok(())
    }
}
