// udp_filter_forwarder.c
// Build: gcc -O3 -march=native -Wall -Wextra -o udp_filter_forwarder udp_filter_forwarder.c
//
// Usage:
//   ./udp_filter_forwarder <listen_ip> <listen_port> <forward_ip> <forward_port>
//
// Example:
//   ./udp_filter_forwarder 0.0.0.0 9000 127.0.0.1 10000

#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

#define MAX_EVENTS 64
#define BUF_SIZE 2048

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    if (fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0) return -1;
    return 0;
}

static int set_socket_opts(int fd) {
    int one = 1;
    int rcvbuf = 4 * 1024 * 1024;
    int sndbuf = 4 * 1024 * 1024;

    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one)) < 0) {
        perror("setsockopt SO_REUSEADDR");
        return -1;
    }
#ifdef SO_REUSEPORT
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &one, sizeof(one)) < 0) {
        perror("setsockopt SO_REUSEPORT");
        return -1;
    }
#endif
    if (setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)) < 0) {
        perror("setsockopt SO_RCVBUF");
        return -1;
    }
    if (setsockopt(fd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf)) < 0) {
        perror("setsockopt SO_SNDBUF");
        return -1;
    }
    return 0;
}

// Example filter:
// - drop empty packets
// - drop packets larger than 1400 bytes
// - drop packets whose first byte is 0x00
static inline bool packet_allowed(const uint8_t *buf, ssize_t len) {
    if (len <= 0) return false;
    if (len > 1400) return false;
    if (buf[0] == 0x00) return false;
    return true;
}

static int make_udp_listener(const char *ip, uint16_t port) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket listener");
        return -1;
    }

    if (set_socket_opts(fd) < 0) {
        close(fd);
        return -1;
    }

    if (set_nonblocking(fd) < 0) {
        perror("set_nonblocking listener");
        close(fd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip, &addr.sin_addr) != 1) {
        fprintf(stderr, "invalid listen ip: %s\n", ip);
        close(fd);
        return -1;
    }

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    return fd;
}

static int make_udp_sender(void) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket sender");
        return -1;
    }

    if (set_socket_opts(fd) < 0) {
        close(fd);
        return -1;
    }

    if (set_nonblocking(fd) < 0) {
        perror("set_nonblocking sender");
        close(fd);
        return -1;
    }

    return fd;
}

int main(int argc, char **argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <listen_ip> <listen_port> <forward_ip> <forward_port>\n", argv[0]);
        return 1;
    }

    const char *listen_ip = argv[1];
    uint16_t listen_port = (uint16_t)strtoul(argv[2], NULL, 10);
    const char *forward_ip = argv[3];
    uint16_t forward_port = (uint16_t)strtoul(argv[4], NULL, 10);

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    int rx_fd = make_udp_listener(listen_ip, listen_port);
    if (rx_fd < 0) return 1;

    int tx_fd = make_udp_sender();
    if (tx_fd < 0) {
        close(rx_fd);
        return 1;
    }

    struct sockaddr_in forward_addr;
    memset(&forward_addr, 0, sizeof(forward_addr));
    forward_addr.sin_family = AF_INET;
    forward_addr.sin_port = htons(forward_port);
    if (inet_pton(AF_INET, forward_ip, &forward_addr.sin_addr) != 1) {
        fprintf(stderr, "invalid forward ip: %s\n", forward_ip);
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    int epfd = epoll_create1(0);
    if (epfd < 0) {
        perror("epoll_create1");
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    struct epoll_event ev;
    memset(&ev, 0, sizeof(ev));
    ev.events = EPOLLIN | EPOLLET;
    ev.data.fd = rx_fd;

    if (epoll_ctl(epfd, EPOLL_CTL_ADD, rx_fd, &ev) < 0) {
        perror("epoll_ctl ADD");
        close(epfd);
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    struct epoll_event events[MAX_EVENTS];
    uint8_t buf[BUF_SIZE];

    uint64_t received = 0, forwarded = 0, dropped = 0, send_wouldblock = 0;

    while (g_running) {
        int n = epoll_wait(epfd, events, MAX_EVENTS, 1000);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < n; i++) {
            if (events[i].data.fd != rx_fd) continue;

            for (;;) {
                struct sockaddr_in src_addr;
                socklen_t src_len = sizeof(src_addr);

                ssize_t r = recvfrom(
                    rx_fd,
                    buf,
                    sizeof(buf),
                    0,
                    (struct sockaddr *)&src_addr,
                    &src_len
                );

                if (r < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) {
                        break;
                    }
                    perror("recvfrom");
                    break;
                }

                received++;

                if (!packet_allowed(buf, r)) {
                    dropped++;
                    continue;
                }

                ssize_t s = sendto(
                    tx_fd,
                    buf,
                    (size_t)r,
                    0,
                    (struct sockaddr *)&forward_addr,
                    sizeof(forward_addr)
                );

                if (s < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) {
                        send_wouldblock++;
                        // In a production system, queue and retry on EPOLLOUT.
                        continue;
                    }
                    perror("sendto");
                    dropped++;
                    continue;
                }

                forwarded++;
            }
        }
    }

    fprintf(stderr,
            "stats: received=%llu forwarded=%llu dropped=%llu send_wouldblock=%llu\n",
            (unsigned long long)received,
            (unsigned long long)forwarded,
            (unsigned long long)dropped,
            (unsigned long long)send_wouldblock);

    close(epfd);
    close(rx_fd);
    close(tx_fd);
    return 0;
}
```

