## Code: `ultra_forwarder.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <poll.h>
#include <sched.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef TPACKET_V3
#define TPACKET_V3 2
#endif

#define BLOCK_SIZE      (1 << 22)   // 4 MiB
#define FRAME_SIZE      2048
#define BLOCK_NR        64
#define RX_RING_FRAMES  ((BLOCK_SIZE * BLOCK_NR) / FRAME_SIZE)

static volatile sig_atomic_t keep_running = 1;

static void on_signal(int signo) {
    (void)signo;
    keep_running = 0;
}

struct ring {
    void *map;
    size_t map_len;
    struct tpacket_req3 req;
};

static int set_promisc(int fd, const char *ifname, int enable) {
    struct packet_mreq mr = {0};
    mr.mr_ifindex = if_nametoindex(ifname);
    if (!mr.mr_ifindex) {
        perror("if_nametoindex");
        return -1;
    }
    mr.mr_type = PACKET_MR_PROMISC;
    int opt = enable ? PACKET_ADD_MEMBERSHIP : PACKET_DROP_MEMBERSHIP;
    if (setsockopt(fd, SOL_PACKET, opt, &mr, sizeof(mr)) < 0) {
        perror("setsockopt PROMISC");
        return -1;
    }
    return 0;
}

static int bind_socket_to_if(int fd, const char *ifname) {
    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex(ifname);
    if (!sll.sll_ifindex) {
        perror("if_nametoindex");
        return -1;
    }
    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return -1;
    }
    return 0;
}

static int setup_rx_ring(int fd, struct ring *r) {
    memset(r, 0, sizeof(*r));
    r->req.tp_block_size = BLOCK_SIZE;
    r->req.tp_frame_size = FRAME_SIZE;
    r->req.tp_block_nr   = BLOCK_NR;
    r->req.tp_frame_nr   = RX_RING_FRAMES;
    r->req.tp_retire_blk_tov = 60;
    r->req.tp_feature_req_word = TP_FT_REQ_FILL_RXHASH;

    int version = TPACKET_V3;
    if (setsockopt(fd, SOL_PACKET, PACKET_VERSION, &version, sizeof(version)) < 0) {
        perror("setsockopt PACKET_VERSION");
        return -1;
    }

    if (setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &r->req, sizeof(r->req)) < 0) {
        perror("setsockopt PACKET_RX_RING");
        return -1;
    }

    r->map_len = r->req.tp_block_size * r->req.tp_block_nr;
    r->map = mmap(NULL, r->map_len, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd, 0);
    if (r->map == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    return 0;
}

static void teardown_rx_ring(int fd, struct ring *r) {
    if (r->map && r->map != MAP_FAILED) {
        munmap(r->map, r->map_len);
    }
    struct tpacket_req3 zero = {0};
    setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &zero, sizeof(zero));
}

static int set_cpu_affinity(int cpu) {
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu, &set);
    if (sched_setaffinity(0, sizeof(set), &set) != 0) {
        perror("sched_setaffinity");
        return -1;
    }
    return 0;
}

static inline int packet_filter(const uint8_t *pkt, size_t len) {
    if (len < sizeof(struct ethhdr))
        return 0;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return 0;

    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return 0;

    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
    if (ip->protocol != IPPROTO_UDP)
        return 0;

    size_t ip_hdr_len = ip->ihl * 4;
    if (len < sizeof(struct ethhdr) + ip_hdr_len + sizeof(struct udphdr))
        return 0;

    const struct udphdr *udp = (const struct udphdr *)(pkt + sizeof(struct ethhdr) + ip_hdr_len);

    // Example filter: forward only destination UDP port 9000
    if (ntohs(udp->dest) != 9000)
        return 0;

    return 1;
}

static inline int forward_packet(int tx_fd, int out_ifindex, const uint8_t *pkt, size_t len) {
    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = out_ifindex;
    sll.sll_halen = ETH_ALEN;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    memcpy(sll.sll_addr, eth->h_dest, ETH_ALEN);

    ssize_t rc = sendto(tx_fd, pkt, len, MSG_DONTWAIT, (struct sockaddr *)&sll, sizeof(sll));
    return (rc == (ssize_t)len) ? 0 : -1;
}

static void process_ring(int rx_fd, int tx_fd, struct ring *r, int out_ifindex) {
    (void)rx_fd;
    unsigned int block_num = 0;

    while (keep_running) {
        struct tpacket_block_desc *block =
            (struct tpacket_block_desc *)((uint8_t *)r->map + (block_num * r->req.tp_block_size));

        if (!(block->hdr.bh1.block_status & TP_STATUS_USER)) {
            struct pollfd pfd = {
                .fd = rx_fd,
                .events = POLLIN,
                .revents = 0
            };
            poll(&pfd, 1, 100);
            continue;
        }

        uint32_t num_pkts = block->hdr.bh1.num_pkts;
        uint32_t offset = block->hdr.bh1.offset_to_first_pkt;

        for (uint32_t i = 0; i < num_pkts; i++) {
            struct tpacket3_hdr *ppd = (struct tpacket3_hdr *)((uint8_t *)block + offset);
            uint8_t *pkt = (uint8_t *)ppd + ppd->tp_mac;
            size_t len = ppd->tp_snaplen;

            if (packet_filter(pkt, len)) {
                forward_packet(tx_fd, out_ifindex, pkt, len);
            }

            offset += ppd->tp_next_offset;
        }

        __sync_synchronize();
        block->hdr.bh1.block_status = TP_STATUS_KERNEL;
        block_num = (block_num + 1) % r->req.tp_block_nr;
    }
}

static int raise_rlimit_memlock(void) {
    // Optional: omitted for portability in this minimal example.
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if> [cpu]\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];
    int cpu = (argc > 3) ? atoi(argv[3]) : -1;

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (cpu >= 0) {
        set_cpu_affinity(cpu);
    }

    raise_rlimit_memlock();

    int rx_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (rx_fd < 0) {
        perror("socket rx");
        return 1;
    }

    int tx_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx_fd < 0) {
        perror("socket tx");
        close(rx_fd);
        return 1;
    }

    int one = 1;
    setsockopt(rx_fd, SOL_PACKET, PACKET_QDISC_BYPASS, &one, sizeof(one));
    setsockopt(tx_fd, SOL_PACKET, PACKET_QDISC_BYPASS, &one, sizeof(one));

    if (bind_socket_to_if(rx_fd, in_if) < 0) {
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    if (bind_socket_to_if(tx_fd, out_if) < 0) {
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    if (set_promisc(rx_fd, in_if, 1) < 0) {
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    struct ring rx_ring;
    if (setup_rx_ring(rx_fd, &rx_ring) < 0) {
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    int out_ifindex = if_nametoindex(out_if);
    if (!out_ifindex) {
        perror("if_nametoindex out_if");
        teardown_rx_ring(rx_fd, &rx_ring);
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    process_ring(rx_fd, tx_fd, &rx_ring, out_ifindex);

    teardown_rx_ring(rx_fd, &rx_ring);
    set_promisc(rx_fd, in_if, 0);
    close(rx_fd);
    close(tx_fd);
    return 0;
}
