#include <atomic>
#include <array>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <memory>
#include <optional>
#include <thread>
#include <vector>
#include <chrono>
#include <functional>
#include <bit>
#include <arpa/inet.h>

constexpr size_t MAX_PACKET_SIZE = 2048;
constexpr size_t PACKET_POOL_SIZE = 1 << 16;
constexpr size_t RING_SIZE = 1 << 14;
constexpr size_t BATCH_SIZE = 32;

struct alignas(64) Packet {
    uint16_t len = 0;
    std::array<uint8_t, MAX_PACKET_SIZE> data{};
};

template <typename T, size_t Size>
class SpscRing {
    static_assert((Size & (Size - 1)) == 0, "Size must be power of two");

public:
    bool push(const T& item) {
        auto head = head_.load(std::memory_order_relaxed);
        auto next = (head + 1) & mask_;
        if (next == tail_.load(std::memory_order_acquire)) {
            return false;
        }
        buffer_[head] = item;
        head_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        auto tail = tail_.load(std::memory_order_relaxed);
        if (tail == head_.load(std::memory_order_acquire)) {
            return false;
        }
        item = buffer_[tail];
        tail_.store((tail + 1) & mask_, std::memory_order_release);
        return true;
    }

    size_t pop_batch(T* out, size_t max_items) {
        size_t count = 0;
        while (count < max_items && pop(out[count])) {
            ++count;
        }
        return count;
    }

private:
    static constexpr size_t mask_ = Size - 1;
    alignas(64) std::array<T, Size> buffer_{};
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
};

class PacketPool {
public:
    PacketPool() {
        for (size_t i = 0; i < PACKET_POOL_SIZE; ++i) {
            free_list_.push_back(std::make_unique<Packet>());
        }
    }

    Packet* acquire() {
        size_t idx = index_.fetch_add(1, std::memory_order_relaxed);
        if (idx >= free_list_.size()) return nullptr;
        return free_list_[idx].get();
    }

private:
    std::vector<std::unique_ptr<Packet>> free_list_;
    std::atomic<size_t> index_{0};
};

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t version_ihl;
    uint8_t dscp_ecn;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t hdr_checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct UdpHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t length;
    uint16_t checksum;
};
#pragma pack(pop)

struct FilterRule {
    std::optional<uint32_t> src_ip;
    std::optional<uint32_t> dst_ip;
    std::optional<uint16_t> src_port;
    std::optional<uint16_t> dst_port;
    std::optional<uint8_t> protocol;

    bool matches(const Packet& pkt) const {
        if (pkt.len < sizeof(EthernetHeader) + sizeof(IPv4Header)) {
            return false;
        }

        const auto* eth = reinterpret_cast<const EthernetHeader*>(pkt.data.data());
        if (ntohs(eth->ethertype) != 0x0800) {
            return false;
        }

        const auto* ip = reinterpret_cast<const IPv4Header*>(pkt.data.data() + sizeof(EthernetHeader));
        const uint8_t ihl = (ip->version_ihl & 0x0F) * 4;
        if (pkt.len < sizeof(EthernetHeader) + ihl) {
            return false;
        }

        if (protocol && *protocol != ip->protocol) return false;
        if (src_ip && *src_ip != ip->src_ip) return false;
        if (dst_ip && *dst_ip != ip->dst_ip) return false;

        if ((src_port || dst_port) && ip->protocol == 17) {
            if (pkt.len < sizeof(EthernetHeader) + ihl + sizeof(UdpHeader)) {
                return false;
            }
            const auto* udp = reinterpret_cast<const UdpHeader*>(
                pkt.data.data() + sizeof(EthernetHeader) + ihl
            );
            if (src_port && *src_port != udp->src_port) return false;
            if (dst_port && *dst_port != udp->dst_port) return false;
        } else if (src_port || dst_port) {
            return false;
        }

        return true;
    }
};

class Forwarder {
public:
    void forward(Packet* pkt) {
        while (!out_ring_.push(pkt)) {
            // busy-spin for low latency
        }
    }

    bool receive_forwarded(Packet*& pkt) {
        return out_ring_.pop(pkt);
    }

private:
    SpscRing<Packet*, RING_SIZE> out_ring_;
};

class PacketProcessor {
public:
    PacketProcessor(SpscRing<Packet*, RING_SIZE>& in, Forwarder& fwd, FilterRule rule)
        : in_ring_(in), forwarder_(fwd), rule_(rule) {}

    void run(std::atomic<bool>& stop_flag) {
        std::array<Packet*, BATCH_SIZE> batch{};
        while (!stop_flag.load(std::memory_order_relaxed)) {
            size_t n = in_ring_.pop_batch(batch.data(), BATCH_SIZE);
            if (n == 0) {
                std::this_thread::yield();
                continue;
            }

            for (size_t i = 0; i < n; ++i) {
                Packet* pkt = batch[i];
                if (pkt && rule_.matches(*pkt)) {
                    forwarder_.forward(pkt);
                }
            }
        }
    }

private:
    SpscRing<Packet*, RING_SIZE>& in_ring_;
    Forwarder& forwarder_;
    FilterRule rule_;
};

static uint32_t ip_from_string(const char* s) {
    in_addr addr{};
    inet_aton(s, &addr);
    return addr.s_addr;
}

void generate_test_packets(SpscRing<Packet*, RING_SIZE>& ring,
                           PacketPool& pool,
                           std::atomic<bool>& stop_flag) {
    while (!stop_flag.load(std::memory_order_relaxed)) {
        Packet* pkt = pool.acquire();
        if (!pkt) break;

        pkt->len = sizeof(EthernetHeader) + sizeof(IPv4Header) + sizeof(UdpHeader) + 16;
        std::memset(pkt->data.data(), 0, pkt->len);

        auto* eth = reinterpret_cast<EthernetHeader*>(pkt->data.data());
        eth->ethertype = htons(0x0800);

        auto* ip = reinterpret_cast<IPv4Header*>(pkt->data.data() + sizeof(EthernetHeader));
        ip->version_ihl = 0x45;
        ip->protocol = 17;
        ip->src_ip = ip_from_string("10.0.0.1");
        ip->dst_ip = ip_from_string("10.0.0.2");

        auto* udp = reinterpret_cast<UdpHeader*>(
            pkt->data.data() + sizeof(EthernetHeader) + sizeof(IPv4Header)
        );
        udp->src_port = htons(12345);
        udp->dst_port = htons(9000);

        while (!ring.push(pkt)) {
            // busy-spin
        }
    }
}

int main() {
    SpscRing<Packet*, RING_SIZE> input_ring;
    Forwarder forwarder;
    PacketPool pool;

    FilterRule rule;
    rule.protocol = 17; // UDP
    rule.dst_ip = ip_from_string("10.0.0.2");
    rule.dst_port = htons(9000);

    std::atomic<bool> stop_flag{false};

    PacketProcessor processor(input_ring, forwarder, rule);

    std::thread producer(generate_test_packets, std::ref(input_ring), std::ref(pool), std::ref(stop_flag));
    std::thread consumer([&] {
        processor.run(stop_flag);
    });

    auto start = std::chrono::steady_clock::now();
    size_t forwarded = 0;

    while (std::chrono::steady_clock::now() - start < std::chrono::seconds(2)) {
        Packet* pkt = nullptr;
        while (forwarder.receive_forwarded(pkt)) {
            ++forwarded;
        }
    }

    stop_flag.store(true, std::memory_order_relaxed);
    producer.join();
    consumer.join();

    std::cout << "Forwarded packets: " << forwarded << "\n";
    return 0;
}
