## Rust example: low-latency defensive packet processor

```rust
use std::collections::HashMap;
use std::net::{Ipv4Addr, UdpSocket, SocketAddrV4};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const MAX_PACKET_SIZE: usize = 2048;
const RATE_LIMIT_PER_SEC: u64 = 10000;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug)]
struct TokenBucket {
    tokens: u64,
    last_refill: Instant,
}

impl TokenBucket {
    fn new() -> Self {
        Self {
            tokens: RATE_LIMIT_PER_SEC,
            last_refill: Instant::now(),
        }
    }

    fn allow(&mut self) -> bool {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill);
        let refill = elapsed.as_secs();

        if refill > 0 {
            self.tokens = (self.tokens + refill * RATE_LIMIT_PER_SEC).min(RATE_LIMIT_PER_SEC);
            self.last_refill = now;
        }

        if self.tokens > 0 {
            self.tokens -= 1;
            true
        } else {
            false
        }
    }
}

#[derive(Default)]
struct Metrics {
    received: u64,
    forwarded: u64,
    dropped: u64,
    parse_errors: u64,
    rate_limited: u64,
}

#[derive(Clone)]
struct Policy {
    allowed_dst_ports: Vec<u16>,
    blocked_src_ips: Vec<Ipv4Addr>,
}

impl Policy {
    fn allow_packet(&self, flow: &FlowKey) -> bool {
        if self.blocked_src_ips.contains(&flow.src_ip) {
            return false;
        }
        self.allowed_dst_ports.contains(&flow.dst_port)
    }
}

fn parse_ipv4_udp(packet: &[u8]) -> Option<FlowKey> {
    if packet.len() < 20 {
        return None;
    }

    let version_ihl = packet[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = (version_ihl & 0x0f) as usize * 4;
    if packet.len() < ihl + 8 {
        return None;
    }

    let proto = packet[9];
    if proto != 17 {
        return None;
    }

    let src_ip = Ipv4Addr::new(packet[12], packet[13], packet[14], packet[15]);
    let dst_ip = Ipv4Addr::new(packet[16], packet[17], packet[18], packet[19]);

    let udp = &packet[ihl..];
    let src_port = u16::from_be_bytes([udp[0], udp[1]]);
    let dst_port = u16::from_be_bytes([udp[2], udp[3]]);

    Some(FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

fn process_packet(
    packet: &[u8],
    policy: &Policy,
    buckets: &Arc<Mutex<HashMap<FlowKey, TokenBucket>>>,
    metrics: &Arc<Mutex<Metrics>>,
) -> bool {
    {
        let mut m = metrics.lock().unwrap();
        m.received += 1;
    }

    let flow = match parse_ipv4_udp(packet) {
        Some(f) => f,
        None => {
            let mut m = metrics.lock().unwrap();
            m.parse_errors += 1;
            m.dropped += 1;
            return false;
        }
    };

    if !policy.allow_packet(&flow) {
        let mut m = metrics.lock().unwrap();
        m.dropped += 1;
        return false;
    }

    let allowed = {
        let mut map = buckets.lock().unwrap();
        let bucket = map.entry(flow).or_insert_with(TokenBucket::new);
        bucket.allow()
    };

    if !allowed {
        let mut m = metrics.lock().unwrap();
        m.rate_limited += 1;
        m.dropped += 1;
        return false;
    }

    let mut m = metrics.lock().unwrap();
    m.forwarded += 1;
    true
}

fn main() -> std::io::Result<()> {
    let ingress = UdpSocket::bind("0.0.0.0:9000")?;
    let egress = UdpSocket::bind("0.0.0.0:0")?;
    egress.connect("127.0.0.1:9001")?;

    ingress.set_nonblocking(false)?;
    ingress.set_read_timeout(Some(Duration::from_millis(100)))?;

    let policy = Policy {
        allowed_dst_ports: vec![53, 123, 443],
        blocked_src_ips: vec![Ipv4Addr::new(10, 0, 0, 66)],
    };

    let buckets = Arc::new(Mutex::new(HashMap::new()));
    let metrics = Arc::new(Mutex::new(Metrics::default()));

    let mut buf = [0u8; MAX_PACKET_SIZE];

    loop {
        match ingress.recv_from(&mut buf) {
            Ok((len, _src)) => {
                let packet = &buf[..len];
                if process_packet(packet, &policy, &buckets, &metrics) {
                    let _ = egress.send(packet);
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {}
            Err(e) if e.kind() == std::io::ErrorKind::TimedOut => {}
            Err(e) => {
                eprintln!("recv error: {e}");
            }
        }

        // Lightweight periodic metrics reporting could go here.
    }
}
```

