## Rust example: low-latency UDP filter/forwarder

```rust
use std::collections::HashSet;
use std::net::{IpAddr, SocketAddr};
use std::sync::Arc;

use tokio::net::UdpSocket;
use tokio::sync::RwLock;

#[derive(Clone)]
struct FilterPolicy {
    blocked_ips: Arc<RwLock<HashSet<IpAddr>>>,
    allowed_ports: Arc<RwLock<HashSet<u16>>>,
    forward_target: SocketAddr,
}

impl FilterPolicy {
    async fn allow(&self, src: SocketAddr, _payload: &[u8], local_port: u16) -> bool {
        let blocked = self.blocked_ips.read().await;
        if blocked.contains(&src.ip()) {
            return false;
        }

        let allowed_ports = self.allowed_ports.read().await;
        allowed_ports.contains(&local_port)
    }
}

async fn run_forwarder(bind_addr: SocketAddr, policy: FilterPolicy) -> tokio::io::Result<()> {
    let socket = UdpSocket::bind(bind_addr).await?;
    let mut buf = vec![0u8; 2048];

    loop {
        let (len, src) = socket.recv_from(&mut buf).await?;
        let packet = &buf[..len];

        if policy.allow(src, packet, bind_addr.port()).await {
            let _ = socket.send_to(packet, policy.forward_target).await?;
        }
    }
}

#[tokio::main]
async fn main() -> tokio::io::Result<()> {
    let mut blocked = HashSet::new();
    blocked.insert("192.168.1.10".parse().unwrap());

    let mut allowed_ports = HashSet::new();
    allowed_ports.insert(9000);

    let policy = FilterPolicy {
        blocked_ips: Arc::new(RwLock::new(blocked)),
        allowed_ports: Arc::new(RwLock::new(allowed_ports)),
        forward_target: "127.0.0.1:10000".parse().unwrap(),
    };

    let bind_addr: SocketAddr = "0.0.0.0:9000".parse().unwrap();
    run_forwarder(bind_addr, policy).await
}
```

