## 1. XDP eBPF program

`xdp_forward_kern.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

struct filter_key {
    __u8 proto;
    __u16 dport;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, struct filter_key);
    __type(value, __u8);
} allow_rules SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct iphdr **iph)
{
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return -1;

    *iph = (void *)(eth + 1);
    if ((void *)(*iph + 1) > data_end)
        return -1;

    return 0;
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct iphdr *iph;
    if (parse_ipv4(data, data_end, &iph) < 0)
        return XDP_PASS;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcph = (void *)iph + iph->ihl * 4;
        if ((void *)(tcph + 1) > data_end)
            return XDP_PASS;

        struct filter_key key = {
            .proto = IPPROTO_TCP,
            .dport = bpf_ntohs(tcph->dest),
        };

        __u8 *allowed = bpf_map_lookup_elem(&allow_rules, &key);
        if (allowed && *allowed) {
            __u32 out_if = 0;
            return bpf_redirect_map(&tx_port, out_if, 0);
        }
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udph = (void *)iph + iph->ihl * 4;
        if ((void *)(udph + 1) > data_end)
            return XDP_PASS;

        struct filter_key key = {
            .proto = IPPROTO_UDP,
            .dport = bpf_ntohs(udph->dest),
        };

        __u8 *allowed = bpf_map_lookup_elem(&allow_rules, &key);
        if (allowed && *allowed) {
            __u32 out_if = 0;
            return bpf_redirect_map(&tx_port, out_if, 0);
        }
    }

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```

