## 2. Userspace loader and rule manager in Go

This uses `cilium/ebpf`.

`main.go`

```go
package main

import (
	"encoding/binary"
	"flag"
	"fmt"
	"log"
	"net"
	"os"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
)

type FilterKey struct {
	Proto uint8
	Pad   uint8
	DPort uint16
}

func mustInterfaceIndex(name string) int {
	iface, err := net.InterfaceByName(name)
	if err != nil {
		log.Fatalf("lookup iface %s: %v", name, err)
	}
	return iface.Index
}

func loadSpec(path string) *ebpf.CollectionSpec {
	spec, err := ebpf.LoadCollectionSpec(path)
	if err != nil {
		log.Fatalf("load spec: %v", err)
	}
	return spec
}

func main() {
	var inIf string
	var outIf string
	var obj string
	var tcpPort int
	var udpPort int

	flag.StringVar(&inIf, "in", "", "input interface")
	flag.StringVar(&outIf, "out", "", "output interface")
	flag.StringVar(&obj, "obj", "xdp_forward_kern.o", "compiled eBPF object")
	flag.IntVar(&tcpPort, "tcp-port", 0, "allow+forward TCP destination port")
	flag.IntVar(&udpPort, "udp-port", 0, "allow+forward UDP destination port")
	flag.Parse()

	if inIf == "" || outIf == "" {
		fmt.Println("usage: app -in eth0 -out eth1 [-tcp-port 443] [-udp-port 53]")
		os.Exit(1)
	}

	spec := loadSpec(obj)

	coll, err := ebpf.NewCollection(spec)
	if err != nil {
		log.Fatalf("new collection: %v", err)
	}
	defer coll.Close()

	prog := coll.Programs["xdp_filter_forward"]
	if prog == nil {
		log.Fatal("program xdp_filter_forward not found")
	}

	txPort := coll.Maps["tx_port"]
	if txPort == nil {
		log.Fatal("map tx_port not found")
	}

	allowRules := coll.Maps["allow_rules"]
	if allowRules == nil {
		log.Fatal("map allow_rules not found")
	}

	outIdx := uint32(mustInterfaceIndex(outIf))
	key0 := uint32(0)
	if err := txPort.Put(key0, outIdx); err != nil {
		log.Fatalf("set devmap: %v", err)
	}

	if tcpPort > 0 {
		k := FilterKey{Proto: 6, DPort: uint16(tcpPort)}
		v := uint8(1)
		if err := allowRules.Put(k, v); err != nil {
			log.Fatalf("insert tcp rule: %v", err)
		}
	}

	if udpPort > 0 {
		k := FilterKey{Proto: 17, DPort: uint16(udpPort)}
		v := uint8(1)
		if err := allowRules.Put(k, v); err != nil {
			log.Fatalf("insert udp rule: %v", err)
		}
	}

	inIdx := mustInterfaceIndex(inIf)
	l, err := link.AttachXDP(link.XDPOptions{
		Program:   prog,
		Interface: inIdx,
	})
	if err != nil {
		log.Fatalf("attach xdp: %v", err)
	}
	defer l.Close()

	log.Printf("XDP attached on %s, forwarding to %s", inIf, outIf)
	select {}
}

func htons(v uint16) uint16 {
	var b [2]byte
	binary.BigEndian.PutUint16(b[:], v)
	return binary.BigEndian.Uint16(b[:])
}
