use bytes::BytesMut;
use std::time::Instant;

#[derive(Debug)]
pub struct Packet {
    pub buf: BytesMut,
    pub ingress_ts: Instant,
}

impl Packet {
    pub fn new(buf: BytesMut) -> Self {
        Self {
            buf,
            ingress_ts: Instant::now(),
        }
    }

    pub fn len(&self) -> usize {
        self.buf.len()
    }

    pub fn ethertype(&self) -> Option<u16> {
        if self.buf.len() < 14 {
            return None;
        }
        let hi = self.buf[12] as u16;
        let lo = self.buf[13] as u16;
        Some((hi << 8) | lo)
    }
}
