use crate::packet::Packet;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Allow,
    Drop,
}

#[derive(Debug, Clone)]
pub enum Match {
    EtherType(u16),
    Any,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub matcher: Match,
    pub action: Action,
}

impl Rule {
    pub fn allow_ethertype(ethertype: u16) -> Self {
        Self {
            matcher: Match::EtherType(ethertype),
            action: Action::Allow,
        }
    }

    pub fn drop_ethertype(ethertype: u16) -> Self {
        Self {
            matcher: Match::EtherType(ethertype),
            action: Action::Drop,
        }
    }

    pub fn allow_any() -> Self {
        Self {
            matcher: Match::Any,
            action: Action::Allow,
        }
    }
}

#[derive(Debug)]
pub struct RuleSet {
    rules: Vec<Rule>,
    default_action: Action,
}

impl RuleSet {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules,
            default_action: Action::Drop,
        }
    }

    pub fn classify(&self, pkt: &Packet) -> Action {
        for rule in &self.rules {
            match rule.matcher {
                Match::Any => return rule.action,
                Match::EtherType(v) => {
                    if pkt.ethertype() == Some(v) {
                        return rule.action;
                    }
                }
            }
        }
        self.default_action
    }
}
