## src/worker.rs

```rust
use crate::io::{PacketRx, PacketTx};
use crate::metrics::Metrics;
use crate::packet::Packet;
use crate::policy::{Action, RuleSet};
use crossbeam::channel::{bounded, Receiver, Sender};
use std::io;
use std::sync::Arc;
use std::thread;
use std::time::Instant;

#[derive(Debug, Clone, Copy)]
pub struct PipelineConfig {
    pub batch_size: usize,
    pub queue_depth: usize,
    pub worker_threads: usize,
}

pub fn run_pipeline(
    rx: Arc<dyn PacketRx>,
    tx: Arc<dyn PacketTx>,
    rules: Arc<RuleSet>,
    config: PipelineConfig,
) -> io::Result<()> {
    let metrics = Arc::new(Metrics::default());
    let (s, r): (Sender<Vec<Packet>>, Receiver<Vec<Packet>>) = bounded(config.queue_depth);

    {
        let rx = Arc::clone(&rx);
        let metrics = Arc::clone(&metrics);
        let s = s.clone();
        thread::spawn(move || {
            let mut batch = Vec::with_capacity(config.batch_size);
            loop {
                batch.clear();
                match rx.recv_batch(&mut batch, config.batch_size) {
                    Ok(0) => thread::yield_now(),
                    Ok(_) => {
                        for pkt in &batch {
                            metrics.on_rx(pkt.len());
                        }
                        let mut next = Vec::with_capacity(config.batch_size);
                        std::mem::swap(&mut batch, &mut next);
                        if s.send(next).is_err() {
                            break;
                        }
                    }
                    Err(_) => break,
                }
            }
        });
    }

    let mut handles = Vec::new();

    for _ in 0..config.worker_threads {
        let r = r.clone();
        let tx = Arc::clone(&tx);
        let rules = Arc::clone(&rules);
        let metrics = Arc::clone(&metrics);

        handles.push(thread::spawn(move || {
            let mut out = Vec::with_capacity(config.batch_size);

            while let Ok(mut batch) = r.recv() {
                out.clear();

                for pkt in batch.drain(..) {
                    match rules.classify(&pkt) {
                        Action::Allow => out.push(pkt),
                        Action::Drop => metrics.on_drop(),
                    }
                }

                let now = Instant::now();
                if tx.send_batch(&mut out).is_ok() {
                    for pkt in &out {
                        let latency = now.saturating_duration_since(pkt.ingress_ts);
                        metrics.on_tx(pkt.len(), latency);
                    }
                }
            }
        }));
    }

    for h in handles {
        let _ = h.join();
    }

    Ok(())
}
```

