struct Engine {
    rules: Vec<CompiledRule>,
    default_action: Action,
}

#[derive(Clone)]
struct CompiledRule {
    action: Action,
    protocol: Option<Proto>,
    src_ip: Option<IpAddr>,
    dst_ip: Option<IpAddr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

impl Engine {
    fn new(cfg: &Config) -> Result<Self> {
        let mut rules = Vec::with_capacity(cfg.rules.len());
        for r in &cfg.rules {
            rules.push(CompiledRule {
                action: r.action,
                protocol: r.protocol,
                src_ip: match &r.src_ip {
                    Some(ip) => Some(IpAddr::from_str(ip).context("invalid src_ip")?),
                    None => None,
                },
                dst_ip: match &r.dst_ip {
                    Some(ip) => Some(IpAddr::from_str(ip).context("invalid dst_ip")?),
                    None => None,
                },
                src_port: r.src_port,
                dst_port: r.dst_port,
            });
        }

        Ok(Self {
            rules,
            default_action: cfg.default_action,
        })
    }

    fn decide(&self, pkt: &ParsedPacket) -> Action {
        for rule in &self.rules {
            if let Some(p) = rule.protocol {
                if pkt.protocol != p {
                    continue;
                }
            }
            if let Some(ip) = rule.src_ip {
                if pkt.src_ip != Some(ip) {
                    continue;
                }
            }
            if let Some(ip) = rule.dst_ip {
                if pkt.dst_ip != Some(ip) {
                    continue;
                }
            }
            if let Some(port) = rule.src_port {
                if pkt.src_port != Some(port) {
                    continue;
                }
            }
            if let Some(port) = rule.dst_port {
                if pkt.dst_port != Some(port) {
                    continue;
                }
            }
            return rule.action;
        }
        self.default_action
    }
}

