fn parse_packet(buf: &[u8]) -> Result<ParsedPacket> {
    let sliced = SlicedPacket::from_ethernet(buf)?;

    let (src_ip, dst_ip, protocol) = match sliced.net {
        Some(etherparse::NetSlice::Ipv4(ipv4)) => {
            let hdr = ipv4.header();
            let src = IpAddr::V4(hdr.source_addr());
            let dst = IpAddr::V4(hdr.destination_addr());
            let proto = match sliced.transport {
                Some(TransportSlice::Tcp(_)) => Proto::Tcp,
                Some(TransportSlice::Udp(_)) => Proto::Udp,
                _ => Proto::Other,
            };
            (Some(src), Some(dst), proto)
        }
        Some(etherparse::NetSlice::Ipv6(ipv6)) => {
            let hdr = ipv6.header();
            let src = IpAddr::V6(hdr.source_addr());
            let dst = IpAddr::V6(hdr.destination_addr());
            let proto = match sliced.transport {
                Some(TransportSlice::Tcp(_)) => Proto::Tcp,
                Some(TransportSlice::Udp(_)) => Proto::Udp,
                _ => Proto::Other,
            };
            (Some(src), Some(dst), proto)
        }
        _ => (None, None, Proto::Other),
    };

    let (src_port, dst_port) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (Some(tcp.source_port()), Some(tcp.destination_port())),
        Some(TransportSlice::Udp(udp)) => (Some(udp.source_port()), Some(udp.destination_port())),
        _ => (None, None),
    };

    Ok(ParsedPacket {
        protocol,
        src_ip,
        dst_ip,
        src_port,
        dst_port,
    })
}

fn worker_loop(
    id: usize,
    rxq: Receiver<PacketBuf>,
    mut tx: Box<dyn Tx>,
    engine: Arc<Engine>,
    metrics: Arc<Metrics>,
) {
    while let Ok(pkt) = rxq.recv() {
        metrics.rx_packets.fetch_add(1, Ordering::Relaxed);

        let parsed = match parse_packet(&pkt.data) {
            Ok(p) => p,
            Err(_) => {
                metrics.parse_errors.fetch_add(1, Ordering::Relaxed);
                metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
                continue;
            }
        };

        match engine.decide(&parsed) {
            Action::Allow => {
                metrics.allowed_packets.fetch_add(1, Ordering::Relaxed);
                if tx.send(pkt).is_ok() {
                    metrics.tx_packets.fetch_add(1, Ordering::Relaxed);
                } else {
                    metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
                }
            }
            Action::Deny => {
                metrics.denied_packets.fetch_add(1, Ordering::Relaxed);
                metrics.dropped_packets.fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    eprintln!("worker {} exiting", id);
}

fn feeder_loop(mut rx: Box<dyn Rx>, txqs: Vec<Sender<PacketBuf>>) {
    let mut rr = 0usize;
    while let Some(pkt) = rx.recv() {
        let idx = rr % txqs.len();
        rr += 1;
        if txqs[idx].send(pkt).is_err() {
            break;
        }
    }
}

fn metrics_loop(metrics: Arc<Metrics>) {
    let mut last = Instant::now();
    let mut prev = metrics.snapshot();

    loop {
        thread::sleep(Duration::from_secs(1));
        let now = Instant::now();
        let cur = metrics.snapshot();
        let elapsed = now.duration_since(last).as_secs_f64().max(1e-9);

        let rx_pps = (cur.rx_packets - prev.rx_packets) as f64 / elapsed;
        let tx_pps = (cur.tx_packets - prev.tx_packets) as f64 / elapsed;
        let drop_pps = (cur.dropped_packets - prev.dropped_packets) as f64 / elapsed;

        println!(
            "rx={} tx={} drop={} allow={} deny={} parse_err={} | rx_pps={:.0} tx_pps={:.0} drop_pps={:.0}",
            cur.rx_packets,
            cur.tx_packets,
            cur.dropped_packets,
            cur.allowed_packets,
            cur.denied_packets,
            cur.parse_errors,
            rx_pps,
            tx_pps,
            drop_pps,
        );

        prev = cur;
        last = now;
    }
}

fn load_config(path: &str) -> Result<Config> {
    let text = fs::read_to_string(path)?;
    let cfg: Config = serde_yaml::from_str(&text)?;
    Ok(cfg)
}

fn main() -> Result<()> {
    let cfg = load_config("config.yaml")?;
    let engine = Arc::new(Engine::new(&cfg)?);
    let metrics = Arc::new(Metrics::default());

    let mut txqs = Vec::new();
    let mut handles = Vec::new();

    for worker_id in 0..cfg.workers {
        let (txq, rxq) = bounded::<PacketBuf>(4096);
        txqs.push(txq);

        let engine_cloned = Arc::clone(&engine);
        let metrics_cloned = Arc::clone(&metrics);

        let handle = thread::spawn(move || {
            let tx: Box<dyn Tx> = Box::new(DummyTx);
            worker_loop(worker_id, rxq, tx, engine_cloned, metrics_cloned);
        });

        handles.push(handle);
    }

    {
        let metrics_cloned = Arc::clone(&metrics);
        thread::spawn(move || metrics_loop(metrics_cloned));
    }

    let feeder = thread::spawn(move || {
        let rx: Box<dyn Rx> = Box::new(DummyRx { packets: 100_000 });
        feeder_loop(rx, txqs);
    });

    feeder.join().unwrap();
    for h in handles {
        h.join().unwrap();
    }

    Ok(())
}
