```rust
#![no_std]
#![no_main]

use aya_ebpf::{
    bindings::xdp_action,
    macros::{map, xdp},
    maps::{Array, HashMap, XskMap},
    programs::XdpContext,
};

use core::mem;

#[repr(C)]
#[derive(Copy, Clone)]
pub struct EthHdr {
    pub dst: [u8; 6],
    pub src: [u8; 6],
    pub eth_proto: u16,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct Ipv4Hdr {
    pub version_ihl: u8,
    pub tos: u8,
    pub tot_len: u16,
    pub id: u16,
    pub frag_off: u16,
    pub ttl: u8,
    pub protocol: u8,
    pub check: u16,
    pub saddr: u32,
    pub daddr: u32,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct UdpHdr {
    pub source: u16,
    pub dest: u16,
    pub len: u16,
    pub check: u16,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct TcpHdr {
    pub source: u16,
    pub dest: u16,
    pub seq: u32,
    pub ack_seq: u32,
    pub doff_res_flags: u16,
    pub window: u16,
    pub check: u16,
    pub urg_ptr: u16,
}

const ETH_P_IP: u16 = 0x0800;
const IPPROTO_TCP: u8 = 6;
const IPPROTO_UDP: u8 = 17;

#[map]
static BLOCKED_SRC_IPS: HashMap<u32, u8> = HashMap::with_max_entries(1024, 0);

#[map]
static ALLOWED_DST_PORTS: HashMap<u16, u8> = HashMap::with_max_entries(1024, 0);

#[map]
static REDIRECT_IFINDEX: Array<u32> = Array::with_max_entries(1, 0);

#[inline(always)]
fn ptr_at<T>(ctx: &XdpContext, offset: usize) -> Result<*const T, ()> {
    let start = ctx.data();
    let end = ctx.data_end();
    let len = mem::size_of::<T>();

    if start + offset + len > end {
        return Err(());
    }

    Ok((start + offset) as *const T)
}

#[xdp]
pub fn xdp_filter_forward(ctx: XdpContext) -> u32 {
    match try_xdp_filter_forward(ctx) {
        Ok(ret) => ret,
        Err(_) => xdp_action::XDP_PASS,
    }
}

fn try_xdp_filter_forward(ctx: XdpContext) -> Result<u32, ()> {
    let eth: *const EthHdr = ptr_at(&ctx, 0)?;
    let eth_proto = unsafe { u16::from_be((*eth).eth_proto) };

    if eth_proto != ETH_P_IP {
        return Ok(xdp_action::XDP_PASS);
    }

    let ip_off = mem::size_of::<EthHdr>();
    let iph: *const Ipv4Hdr = ptr_at(&ctx, ip_off)?;
    let src_ip = unsafe { u32::from_be((*iph).saddr) };
    let proto = unsafe { (*iph).protocol };

    if BLOCKED_SRC_IPS.get(&src_ip).is_some() {
        return Ok(xdp_action::XDP_DROP);
    }

    let ihl = unsafe { ((*iph).version_ihl & 0x0f) as usize * 4 };

    match proto {
        IPPROTO_UDP => {
            let udp_off = ip_off + ihl;
            let udp: *const UdpHdr = ptr_at(&ctx, udp_off)?;
            let dst_port = unsafe { u16::from_be((*udp).dest) };

            if ALLOWED_DST_PORTS.get(&dst_port).is_none() {
                return Ok(xdp_action::XDP_DROP);
            }
        }
        IPPROTO_TCP => {
            let tcp_off = ip_off + ihl;
            let tcp: *const TcpHdr = ptr_at(&ctx, tcp_off)?;
            let dst_port = unsafe { u16::from_be((*tcp).dest) };

            if ALLOWED_DST_PORTS.get(&dst_port).is_none() {
                return Ok(xdp_action::XDP_DROP);
            }
        }
        _ => {
            return Ok(xdp_action::XDP_DROP);
        }
    }

    let key = 0u32;
    if let Some(ifindex) = REDIRECT_IFINDEX.get(&key) {
        return Ok(ctx.redirect(*ifindex, 0));
    }

    Ok(xdp_action::XDP_PASS)
}

#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! {
    loop {}
}
