```rust
use anyhow::{Context, Result};
use aya::{
    include_bytes_aligned,
    maps::{Array, HashMap},
    programs::{Xdp, XdpFlags},
    Ebpf,
};
use clap::Parser;
use std::net::Ipv4Addr;

#[derive(Parser, Debug)]
struct Opt {
    #[arg(long)]
    iface: String,

    #[arg(long)]
    redirect_ifindex: Option<u32>,

    #[arg(long)]
    allow_port: Vec<u16>,

    #[arg(long)]
    block_src: Vec<Ipv4Addr>,
}

#[tokio::main]
async fn main() -> Result<()> {
    let opt = Opt::parse();

    let mut bpf = Ebpf::load(include_bytes_aligned!(
        "../../target/bpfel-unknown-none/release/xdp-fw-ebpf"
    ))?;

    {
        let program: &mut Xdp = bpf
            .program_mut("xdp_filter_forward")
            .context("program not found")?
            .try_into()?;

        program.load()?;
        program.attach(&opt.iface, XdpFlags::default())
            .context("failed to attach XDP program")?;
    }

    {
        let mut blocked: HashMap<_, u32, u8> =
            HashMap::try_from(bpf.take_map("BLOCKED_SRC_IPS").context("BLOCKED_SRC_IPS missing")?)?;

        for ip in &opt.block_src {
            let key = u32::from_be_bytes(ip.octets());
            blocked.insert(key, 1, 0)?;
        }
    }

    {
        let mut allowed: HashMap<_, u16, u8> =
            HashMap::try_from(bpf.take_map("ALLOWED_DST_PORTS").context("ALLOWED_DST_PORTS missing")?)?;

        for port in &opt.allow_port {
            allowed.insert(*port, 1, 0)?;
        }
    }

    if let Some(ifindex) = opt.redirect_ifindex {
        let mut redirect: Array<_, u32> =
            Array::try_from(bpf.take_map("REDIRECT_IFINDEX").context("REDIRECT_IFINDEX missing")?)?;
        redirect.set(0, ifindex, 0)?;
    }

    println!("XDP filter/forwarder attached to {}", opt.iface);
    println!("Press Ctrl-C to exit");

    tokio::signal::ctrl_c().await?;
    Ok(())
}
