# XDP program in C

File: `xdp_fw_kern.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <linux/in.h>

char LICENSE[] SEC("license") = "GPL";

struct rule_key {
    __u32 src_ip;     // network byte order
    __u32 dst_ip;     // network byte order
    __u16 src_port;   // host byte order in map key
    __u16 dst_port;   // host byte order in map key
    __u8  proto;      // IPPROTO_TCP/UDP
    __u8  pad1;
    __u16 pad2;
};

struct rule_val {
    __u8 action; // 0=drop, 1=allow
    __u8 pad[3];
};

struct stats_key {
    __u32 action; // XDP_DROP, XDP_PASS, redirect bucket, parse errors, etc.
};

struct stats_val {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, struct rule_key);
    __type(value, struct rule_val);
} rules SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 16);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 64);
    __type(key, struct stats_key);
    __type(value, struct stats_val);
} stats SEC(".maps");

static __always_inline void count_stat(__u32 action, __u64 bytes)
{
    struct stats_key key = { .action = action };
    struct stats_val *v = bpf_map_lookup_elem(&stats, &key);
    if (v) {
        v->packets++;
        v->bytes += bytes;
    } else {
        struct stats_val init = {
            .packets = 1,
            .bytes = bytes,
        };
        bpf_map_update_elem(&stats, &key, &init, BPF_ANY);
    }
}

static __always_inline int parse_eth(void **data, void *data_end, __u16 *eth_proto)
{
    struct ethhdr *eth = *data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    *eth_proto = bpf_ntohs(eth->h_proto);
    *data = eth + 1;

    // Minimal VLAN handling could be added here if needed.
    return 0;
}

static __always_inline int parse_ipv4(void **data, void *data_end, struct iphdr **iph)
{
    struct iphdr *ip = *data;
    if ((void *)(ip + 1) > data_end)
        return -1;
    if (ip->ihl < 5)
        return -1;
    if ((void *)ip + ip->ihl * 4 > data_end)
        return -1;

    *iph = ip;
    *data = (void *)ip + ip->ihl * 4;
    return 0;
}

SEC("xdp")
int xdp_fw(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    void *cursor = data;
    __u64 pkt_len = (__u64)(data_end - data);

    __u16 eth_proto;
    if (parse_eth(&cursor, data_end, &eth_proto) < 0) {
        count_stat(100, pkt_len); // parse error
        return XDP_DROP;
    }

    if (eth_proto != ETH_P_IP) {
        count_stat(XDP_PASS, pkt_len);
        return XDP_PASS;
    }

    struct iphdr *iph;
    if (parse_ipv4(&cursor, data_end, &iph) < 0) {
        count_stat(101, pkt_len); // ip parse error
        return XDP_DROP;
    }

    struct rule_key key = {};
    key.src_ip = iph->saddr;
    key.dst_ip = iph->daddr;
    key.proto = iph->protocol;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = cursor;
        if ((void *)(tcp + 1) > data_end) {
            count_stat(102, pkt_len);
            return XDP_DROP;
        }
        key.src_port = bpf_ntohs(tcp->source);
        key.dst_port = bpf_ntohs(tcp->dest);
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = cursor;
        if ((void *)(udp + 1) > data_end) {
            count_stat(103, pkt_len);
            return XDP_DROP;
        }
        key.src_port = bpf_ntohs(udp->source);
        key.dst_port = bpf_ntohs(udp->dest);
    } else {
        // Default deny non-TCP/UDP in this initial implementation
        count_stat(XDP_DROP, pkt_len);
        return XDP_DROP;
    }

    struct rule_val *rule = bpf_map_lookup_elem(&rules, &key);
    if (!rule || rule->action == 0) {
        count_stat(XDP_DROP, pkt_len);
        return XDP_DROP;
    }

    count_stat(200, pkt_len); // accepted before redirect

    // Redirect to devmap slot 0
    int rc = bpf_redirect_map(&tx_port, 0, XDP_DROP);
    count_stat(201, pkt_len); // redirect attempted
    return rc;
}
