		log.Fatalf("invalid IPv4: %s", ipStr)
	}
	return binary.BigEndian.Uint32(ip)
}

func ifIndex(name string) int {
	iface, err := net.InterfaceByName(name)
	if err != nil {
		log.Fatalf("lookup iface %s: %v", name, err)
	}
	return iface.Index
}

func loadObjects(path string) (*Objects, error) {
	spec, err := ebpf.LoadCollectionSpec(path)
	if err != nil {
		return nil, err
	}

	objs := &Objects{}
	if err := spec.LoadAndAssign(objs, nil); err != nil {
		return nil, err
	}
	return objs, nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Fprintf(os.Stderr, "usage: %s <ingress-iface> <egress-iface>\n", os.Args[0])
		os.Exit(1)
	}
	ingress := os.Args[1]
	egress := os.Args[2]

	if err := rlimit.RemoveMemlock(); err != nil {
		log.Fatalf("remove memlock: %v", err)
	}

	objs, err := loadObjects("xdp_fw_kern.o")
	if err != nil {
		log.Fatalf("load objects: %v", err)
	}
	defer objs.XdpFw.Close()
	defer objs.Rules.Close()
	defer objs.TxPort.Close()
	defer objs.Stats.Close()

	egressIdx := uint32(ifIndex(egress))
	slot := uint32(0)
	if err := objs.TxPort.Put(slot, egressIdx); err != nil {
		log.Fatalf("populate devmap: %v", err)
	}

	// Example allow rule: TCP 10.0.0.1:12345 -> 10.0.0.2:80
	rk := RuleKey{
		SrcIP:   ipToU32("10.0.0.1"),
		DstIP:   ipToU32("10.0.0.2"),
		SrcPort: 12345,
		DstPort: 80,
		Proto:   6, // TCP
	}
	rv := RuleVal{Action: 1}
	if err := objs.Rules.Put(rk, rv); err != nil {
		log.Fatalf("insert rule: %v", err)
	}

	lnk, err := link.AttachXDP(link.XDPOptions{
		Program:   objs.XdpFw,
		Interface: ifIndex(ingress),
		Flags:     link.XDPGenericMode, // replace with native/driver mode where supported
	})
	if err != nil {
		log.Fatalf("attach xdp: %v", err)
	}
	defer lnk.Close()

	log.Printf("attached XDP to %s, forwarding allowed traffic to %s", ingress, egress)

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, syscall.SIGINT, syscall.SIGTERM)

	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			printStats(objs.Stats)
		case s := <-sigc:
			log.Printf("signal: %v", s)
			return
		}
	}
}

func printStats(m *ebpf.Map) {
	iter := m.Iterate()
	var k StatsKey
	var v StatsVal

	log.Printf("stats:")
	for iter.Next(&k, &v) {
		log.Printf("  action=%d packets=%d bytes=%d", k.Action, v.Packets, v.Bytes)
	}
	if err := iter.Err(); err != nil && !errors.Is(err, ebpf.ErrKeyNotExist) {
		log.Printf("stats iterate error: %v", err)
	}
}
