# 2) XDP program: `xdp_fw_kern.c`

```c
#include "common.h"

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <linux/in.h>
#include <linux/icmp.h>

char LICENSE[] SEC("license") = "GPL";

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, MAX_RULES);
    __type(key, __u32);
    __type(value, struct rule);
} rules_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, MAX_RULES);
    __type(key, __u32);
    __type(value, struct rule_stats);
} stats_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct config);
} config_map SEC(".maps");

static __always_inline int ip_match(__u32 pkt_ip, __u32 rule_ip, __u32 mask)
{
    if (mask == 0)
        return 1;
    return (pkt_ip & mask) == (rule_ip & mask);
}

static __always_inline int port_match(__u16 port, __u16 start, __u16 end)
{
    if (start == 0 && end == 0)
        return 1;
    return port >= start && port <= end;
}

static __always_inline void count_rule(__u32 idx, __u64 bytes)
{
    struct rule_stats *st = bpf_map_lookup_elem(&stats_map, &idx);
    if (!st)
        return;

    __sync_fetch_and_add(&st->packets, 1);
    __sync_fetch_and_add(&st->bytes, bytes);
}

SEC("xdp")
int xdp_fw_prog(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_ABORTED;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_ABORTED;

    if (iph->ihl < 5)
        return XDP_DROP;

    void *l4 = (void *)iph + iph->ihl * 4;
    if (l4 > data_end)
        return XDP_ABORTED;

    __u8 proto = iph->protocol;
    __u16 src_port = 0;
    __u16 dst_port = 0;

    if (proto == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end)
            return XDP_ABORTED;
        src_port = bpf_ntohs(tcp->source);
        dst_port = bpf_ntohs(tcp->dest);
    } else if (proto == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end)
            return XDP_ABORTED;
        src_port = bpf_ntohs(udp->source);
        dst_port = bpf_ntohs(udp->dest);
    } else if (proto == IPPROTO_ICMP) {
        struct icmphdr *icmp = l4;
        if ((void *)(icmp + 1) > data_end)
            return XDP_ABORTED;
    }

    __u64 pkt_len = (__u64)((char *)data_end - (char *)data);

    #pragma unroll
    for (__u32 i = 0; i < MAX_RULES; i++) {
        struct rule *r = bpf_map_lookup_elem(&rules_map, &i);
        if (!r)
            break;
        if (!r->enabled)
            continue;

        if (r->proto != PROTO_ANY && r->proto != proto)
            continue;

        if (!ip_match(iph->saddr, r->src_ip, r->src_mask))
            continue;
        if (!ip_match(iph->daddr, r->dst_ip, r->dst_mask))
            continue;

        if (proto == IPPROTO_TCP || proto == IPPROTO_UDP) {
            if (!port_match(src_port, r->src_port_start, r->src_port_end))
                continue;
            if (!port_match(dst_port, r->dst_port_start, r->dst_port_end))
                continue;
        }

        count_rule(i, pkt_len);

        if (r->action == ACTION_DROP)
            return XDP_DROP;

        if (r->action == ACTION_REDIRECT) {
            __u32 key = 0;
            struct config *cfg = bpf_map_lookup_elem(&config_map, &key);
            if (!cfg)
                return XDP_DROP;
            return bpf_redirect(cfg->redirect_ifindex, 0);
        }

        return XDP_PASS;
    }

    __u32 key = 0;
    struct config *cfg = bpf_map_lookup_elem(&config_map, &key);
    if (!cfg)
        return XDP_PASS;

    if (cfg->default_action == ACTION_DROP)
        return XDP_DROP;

    return XDP_PASS;
}
