# 3) Userspace loader/control plane: `xdp_fw_user.c`

This is a minimal implementation using libbpf.

```c
#include "common.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <signal.h>

#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static volatile int running = 1;

static void on_sigint(int sig)
{
    (void)sig;
    running = 0;
}

static int parse_cidr(const char *cidr, __u32 *ip, __u32 *mask)
{
    if (!cidr || strcmp(cidr, "any") == 0) {
        *ip = 0;
        *mask = 0;
        return 0;
    }

    char buf[64];
    strncpy(buf, cidr, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    char *slash = strchr(buf, '/');
    int prefix = 32;
    if (slash) {
        *slash = '\0';
        prefix = atoi(slash + 1);
        if (prefix < 0 || prefix > 32)
            return -1;
    }

    struct in_addr addr;
    if (inet_pton(AF_INET, buf, &addr) != 1)
        return -1;

    *ip = addr.s_addr;
    if (prefix == 0) {
        *mask = 0;
    } else {
        __u32 m = 0xffffffffu << (32 - prefix);
        *mask = htonl(m);
    }

    return 0;
}

static int set_rule(int map_fd, __u32 idx, struct rule *r)
{
    return bpf_map_update_elem(map_fd, &idx, r, BPF_ANY);
}

static void print_stats(int stats_fd)
{
    for (__u32 i = 0; i < MAX_RULES; i++) {
        struct rule_stats st = {};
        if (bpf_map_lookup_elem(stats_fd, &i, &st) == 0) {
            if (st.packets || st.bytes) {
                printf("rule[%u]: packets=%llu bytes=%llu\n",
                       i,
                       (unsigned long long)st.packets,
                       (unsigned long long)st.bytes);
            }
        }
    }
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: %s <ingress-iface> <redirect-iface>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    const char *redir_ifname = argv[2];

    int ifindex = if_nametoindex(ifname);
    int redir_ifindex = if_nametoindex(redir_ifname);
    if (!ifindex || !redir_ifindex) {
        fprintf(stderr, "invalid interface name(s)\n");
        return 1;
    }

    struct bpf_object *obj = NULL;
    int prog_fd = -1;

    struct bpf_prog_load_attr prog_load_attr = {
        .prog_type = BPF_PROG_TYPE_XDP,
        .file = "xdp_fw_kern.o",
    };

    if (bpf_prog_load_xattr(&prog_load_attr, &obj, &prog_fd)) {
        fprintf(stderr, "failed to load BPF object: %s\n", strerror(errno));
        return 1;
    }

    int rules_fd = bpf_object__find_map_fd_by_name(obj, "rules_map");
    int stats_fd = bpf_object__find_map_fd_by_name(obj, "stats_map");
    int config_fd = bpf_object__find_map_fd_by_name(obj, "config_map");

    if (rules_fd < 0 || stats_fd < 0 || config_fd < 0) {
        fprintf(stderr, "failed to find BPF maps\n");
        bpf_object__close(obj);
        return 1;
    }

    __u32 cfg_key = 0;
    struct config cfg = {
        .default_action = ACTION_PASS,
        .redirect_ifindex = (__u32)redir_ifindex,
    };

    if (bpf_map_update_elem(config_fd, &cfg_key, &cfg, BPF_ANY) != 0) {
        fprintf(stderr, "failed to set config\n");
        bpf_object__close(obj);
        return 1;
    }

    // Example rules:
    // 0: Drop TCP dst port 23 (telnet)
    struct rule r0 = {
        .enabled = 1,
        .action = ACTION_DROP,
        .proto = PROTO_TCP,
        .src_ip = 0,
        .src_mask = 0,
        .dst_ip = 0,
        .dst_mask = 0,
        .src_port_start = 0,
        .src_port_end = 0,
        .dst_port_start = 23,
        .dst_port_end = 23,
    };
    set_rule(rules_fd, 0, &r0);

    // 1: Redirect UDP dst port 5000
    struct rule r1 = {
        .enabled = 1,
        .action = ACTION_REDIRECT,
        .proto = PROTO_UDP,
        .src_ip = 0,
        .src_mask = 0,
        .dst_ip = 0,
        .dst_mask = 0,
        .src_port_start = 0,
        .src_port_end = 0,
        .dst_port_start = 5000,
        .dst_port_end = 5000,
    };
    set_rule(rules_fd, 1, &r1);

    // 2: Allow TCP to 10.0.0.0/24 dst port 443
    struct rule r2 = {
        .enabled = 1,
        .action = ACTION_PASS,
        .proto = PROTO_TCP,
        .src_port_start = 0,
        .src_port_end = 0,
        .dst_port_start = 443,
        .dst_port_end = 443,
    };
    parse_cidr("10.0.0.0/24", &r2.dst_ip, &r2.dst_mask);
    set_rule(rules_fd, 2, &r2);

    if (bpf_set_link_xdp_fd(ifindex, prog_fd, 0) < 0) {
        fprintf(stderr, "failed to attach XDP program to %s\n", ifname);
        bpf_object__close(obj);
        return 1;
    }

    printf("XDP firewall/forwarder attached to %s, redirect=%s\n", ifname, redir_ifname);
    signal(SIGINT, on_sigint);

    while (running) {
        sleep(2);
        print_stats(stats_fd);
    }

    bpf_set_link_xdp_fd(ifindex, -1, 0);
    bpf_object__close(obj);
    return 0;
}
