## `xdp-ebpf/src/main.rs`

```rust
#![no_std]
#![no_main]

use aya_ebpf::{
    bindings::xdp_action,
    macros::{map, xdp},
    maps::{HashMap, XskMap},
    programs::XdpContext,
};

const ETH_P_IP: u16 = 0x0800;
const IPPROTO_TCP: u8 = 6;
const IPPROTO_UDP: u8 = 17;

#[repr(C)]
#[derive(Copy, Clone)]
pub struct RuleKey {
    pub proto: u8,
    pub dst_port: u16,
    pub _pad: u8,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct RuleAction {
    pub action: u32, // 0=PASS, 1=DROP, 2=REDIRECT_XSK
}

#[repr(C)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    eth_proto: u16,
}

#[repr(C)]
struct Ipv4Hdr {
    version_ihl: u8,
    tos: u8,
    tot_len: u16,
    id: u16,
    frag_off: u16,
    ttl: u8,
    protocol: u8,
    check: u16,
    saddr: u32,
    daddr: u32,
}

#[repr(C)]
struct TcpHdr {
    src: u16,
    dst: u16,
    seq: u32,
    ack_seq: u32,
    doff_res_flags: u16,
    window: u16,
    check: u16,
    urg_ptr: u16,
}

#[repr(C)]
struct UdpHdr {
    src: u16,
    dst: u16,
    len: u16,
    check: u16,
}

#[map(name = "RULES")]
static mut RULES: HashMap<RuleKey, RuleAction> =
    HashMap::<RuleKey, RuleAction>::with_max_entries(4096, 0);

#[map(name = "XSKS")]
static mut XSKS: XskMap = XskMap::with_max_entries(64, 0);

#[inline(always)]
fn ntohs(v: u16) -> u16 {
    u16::from_be(v)
}

#[inline(always)]
fn ptr_at<T>(ctx: &XdpContext, offset: usize) -> Option<*const T> {
    let start = ctx.data();
    let end = ctx.data_end();
    let len = core::mem::size_of::<T>();

    if start + offset + len > end {
        return None;
    }

    Some((start + offset) as *const T)
}

#[xdp(name = "ultra_filter")]
pub fn ultra_filter(ctx: XdpContext) -> u32 {
    match try_ultra_filter(ctx) {
        Ok(ret) => ret,
        Err(_) => xdp_action::XDP_PASS,
    }
}

fn try_ultra_filter(ctx: XdpContext) -> Result<u32, ()> {
    let eth: *const EthHdr = ptr_at(&ctx, 0).ok_or(())?;
    let eth_proto = unsafe { ntohs((*eth).eth_proto) };

    if eth_proto != ETH_P_IP {
        return Ok(xdp_action::XDP_PASS);
    }

    let ip_off = core::mem::size_of::<EthHdr>();
    let ip: *const Ipv4Hdr = ptr_at(&ctx, ip_off).ok_or(())?;
    let ihl = unsafe { ((*ip).version_ihl & 0x0f) as usize * 4 };
    if ihl < 20 {
        return Ok(xdp_action::XDP_PASS);
    }

    let proto = unsafe { (*ip).protocol };
    let l4_off = ip_off + ihl;

    let dst_port = match proto {
        IPPROTO_TCP => {
            let tcp: *const TcpHdr = ptr_at(&ctx, l4_off).ok_or(())?;
            unsafe { ntohs((*tcp).dst) }
        }
        IPPROTO_UDP => {
            let udp: *const UdpHdr = ptr_at(&ctx, l4_off).ok_or(())?;
            unsafe { ntohs((*udp).dst) }
        }
        _ => return Ok(xdp_action::XDP_PASS),
    };

    let key = RuleKey {
        proto,
        dst_port,
        _pad: 0,
    };

    let action = unsafe { RULES.get(&key) };

    match action {
        Some(a) => match a.action {
            1 => Ok(xdp_action::XDP_DROP),
            2 => {
                let qid = ctx.rx_queue_index();
                unsafe { XSKS.redirect(qid, 0).map_err(|_| ()) }
            }
            _ => Ok(xdp_action::XDP_PASS),
        },
        None => Ok(xdp_action::XDP_PASS),
    }
}

#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! {
    loop {}
}
```

