    pub action: u32, // 0=PASS, 1=DROP, 2=REDIRECT_XSK
}

#[derive(Parser, Debug)]
struct Opt {
    #[arg(long)]
    iface: String,

    #[arg(long, default_value = "./xdp-ebpf.o")]
    ebpf: PathBuf,
}

struct PacketService {
    iface: String,
}

impl PacketService {
    async fn run(&mut self) -> Result<()> {
        loop {
            // Placeholder for AF_XDP receive/forward loop.
            // In a real implementation:
            // 1. poll RX ring
            // 2. parse packet metadata
            // 3. optionally mirror counters/logging
            // 4. forward out TX ring or another interface
            // 5. recycle UMEM frames

            sleep(Duration::from_millis(10)).await;
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let opt = Opt::parse();

    let data = fs::read(&opt.ebpf)
        .with_context(|| format!("failed to read eBPF object {}", opt.ebpf.display()))?;

    let mut bpf = Ebpf::load(&data)?;
    let program: &mut Xdp = bpf
        .program_mut("ultra_filter")
        .context("program ultra_filter not found")?
        .try_into()?;

    program.load()?;
    program.attach(&opt.iface, XdpFlags::DRV_MODE)
        .or_else(|_| program.attach(&opt.iface, XdpFlags::SKB_MODE))?;

    let mut rules: HashMap<_, RuleKey, RuleAction> =
        HashMap::try_from(bpf.take_map("RULES").context("RULES map missing")?)?;

    // Example policies:
    // Drop TCP/23
    rules.insert(
        RuleKey {
            proto: 6,
            dst_port: 23,
            _pad: 0,
        },
        RuleAction { action: 1 },
        0,
    )?;

    // Redirect UDP/9000 to AF_XDP userspace
    rules.insert(
        RuleKey {
            proto: 17,
            dst_port: 9000,
            _pad: 0,
        },
        RuleAction { action: 2 },
        0,
    )?;

    // Pass TCP/443
    rules.insert(
        RuleKey {
            proto: 6,
            dst_port: 443,
            _pad: 0,
        },
        RuleAction { action: 0 },
        0,
    )?;

    let mut svc = PacketService {
        iface: opt.iface.clone(),
    };

    tokio::select! {
        r = svc.run() => r?,
        _ = signal::ctrl_c() => {
            eprintln!("shutting down");
        }
    }

    Ok(())
}
