# 4. Example forwarding classifier

If you want userspace to do additional filtering before forwarding:

```rust
#[derive(Debug, Clone, Copy)]
enum Decision {
    Forward,
    Drop,
    PassUp,
}

fn classify(pkt: &[u8]) -> Decision {
    if pkt.len() < 14 {
        return Decision::Drop;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    if ethertype != 0x0800 {
        return Decision::PassUp;
    }

    if pkt.len() < 34 {
        return Decision::Drop;
    }

    let ihl = (pkt[14] & 0x0f) as usize * 4;
    if pkt.len() < 14 + ihl {
        return Decision::Drop;
    }

    let proto = pkt[23];
    let l4 = 14 + ihl;

    match proto {
        6 if pkt.len() >= l4 + 4 => {
            let dst = u16::from_be_bytes([pkt[l4 + 2], pkt[l4 + 3]]);
            if dst == 9001 {
                Decision::Forward
            } else {
                Decision::PassUp
            }
        }
        17 if pkt.len() >= l4 + 4 => {
            let dst = u16::from_be_bytes([pkt[l4 + 2], pkt[l4 + 3]]);
            if dst == 9000 {
                Decision::Forward
            } else {
                Decision::PassUp
            }
        }
        _ => Decision::PassUp,
    }
}
```

