# 1. XDP program

## `xdp_filter_forward.bpf.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

char LICENSE[] SEC("license") = "GPL";

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 source address in network byte order
    __type(value, __u8);  // 1 = blocked
} blocklist SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 16);
    __type(key, __u32);   // logical port/index
    __type(value, __u32); // ifindex
} tx_ports SEC(".maps");

struct stats_rec {
    __u64 passed;
    __u64 dropped;
    __u64 redirected;
};

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct stats_rec);
} stats SEC(".maps");

static __always_inline void count_pass(void)
{
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s)
        __sync_fetch_and_add(&s->passed, 1);
}

static __always_inline void count_drop(void)
{
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s)
        __sync_fetch_and_add(&s->dropped, 1);
}

static __always_inline void count_redirect(void)
{
    __u32 key = 0;
    struct stats_rec *s = bpf_map_lookup_elem(&stats, &key);
    if (s)
        __sync_fetch_and_add(&s->redirected, 1);
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx)
{
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_ABORTED;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP) {
        count_pass();
        return XDP_PASS;
    }

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_ABORTED;

    // Only handle standard IPv4 header lengths safely
    if (iph->ihl < 5)
        return XDP_DROP;

    if ((void *)iph + (iph->ihl * 4) > data_end)
        return XDP_ABORTED;

    __u32 src = iph->saddr;
    __u8 *blocked = bpf_map_lookup_elem(&blocklist, &src);
    if (blocked && *blocked) {
        count_drop();
        return XDP_DROP;
    }

    // Redirect to tx_ports[0] if configured
    __u32 port = 0;
    __u32 *ifindex = bpf_map_lookup_elem(&tx_ports, &port);
    if (ifindex) {
        count_redirect();
        return bpf_redirect_map(&tx_ports, port, 0);
    }

    count_pass();
    return XDP_PASS;
}
```

