# 2. User-space loader

## `loader.c`

```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s <ingress-iface> <egress-iface> [blocked-ip ...]\n",
        prog);
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    const char *ingress = argv[1];
    const char *egress = argv[2];

    int ifindex_in = if_nametoindex(ingress);
    int ifindex_out = if_nametoindex(egress);

    if (!ifindex_in || !ifindex_out) {
        fprintf(stderr, "Invalid interface(s)\n");
        return 1;
    }

    struct bpf_object *obj = NULL;
    int prog_fd = -1;
    int err;

    obj = bpf_object__open_file("xdp_filter_forward.bpf.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_filter_forward");
    if (!prog) {
        fprintf(stderr, "Failed to find BPF program\n");
        bpf_object__close(obj);
        return 1;
    }

    prog_fd = bpf_program__fd(prog);

    err = bpf_xdp_attach(ifindex_in, prog_fd, XDP_FLAGS_DRV_MODE, NULL);
    if (err) {
        fprintf(stderr, "Failed to attach XDP program in driver mode: %d\n", err);
        fprintf(stderr, "Try native/generic fallback if your NIC does not support DRV mode.\n");
        bpf_object__close(obj);
        return 1;
    }

    int tx_ports_fd = bpf_object__find_map_fd_by_name(obj, "tx_ports");
    int blocklist_fd = bpf_object__find_map_fd_by_name(obj, "blocklist");

    if (tx_ports_fd < 0 || blocklist_fd < 0) {
        fprintf(stderr, "Failed to find BPF maps\n");
        bpf_xdp_detach(ifindex_in, XDP_FLAGS_DRV_MODE, NULL);
        bpf_object__close(obj);
        return 1;
    }

    __u32 key = 0;
    __u32 out_ifindex = ifindex_out;
    err = bpf_map_update_elem(tx_ports_fd, &key, &out_ifindex, BPF_ANY);
    if (err) {
        fprintf(stderr, "Failed to configure tx_ports map: %s\n", strerror(errno));
        bpf_xdp_detach(ifindex_in, XDP_FLAGS_DRV_MODE, NULL);
        bpf_object__close(obj);
        return 1;
    }

    for (int i = 3; i < argc; i++) {
        struct in_addr addr;
        if (inet_pton(AF_INET, argv[i], &addr) != 1) {
            fprintf(stderr, "Invalid IPv4 address: %s\n", argv[i]);
            continue;
        }

        __u32 ip = addr.s_addr; // network byte order
        __u8 blocked = 1;
        err = bpf_map_update_elem(blocklist_fd, &ip, &blocked, BPF_ANY);
        if (err) {
            fprintf(stderr, "Failed to add blocklist entry %s: %s\n",
                    argv[i], strerror(errno));
        }
    }

    printf("XDP filter/forward attached on %s (ifindex=%d), forwarding to %s (ifindex=%d)\n",
           ingress, ifindex_in, egress, ifindex_out);
    printf("Press Ctrl+C to exit.\n");

    while (1) {
        pause();
    }

    bpf_xdp_detach(ifindex_in, XDP_FLAGS_DRV_MODE, NULL);
    bpf_object__close(obj);
    return 0;
}
```

