# 1. XDP program

## `xdp/xdp_prog.c`

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/in.h>

char LICENSE[] SEC("license") = "GPL";

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 source address
    __type(value, __u8);  // 1 = allow, 2 = drop, 3 = redirect
} policy_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 source address
    __type(value, __u32); // ifindex for redirect
} redirect_map SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct iphdr **iphdr) {
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return -1;

    *iphdr = ip;
    return 0;
}

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct iphdr *ip;
    if (parse_ipv4(data, data_end, &ip) < 0)
        return XDP_PASS;

    __u32 src = ip->saddr;

    __u8 *policy = bpf_map_lookup_elem(&policy_map, &src);
    if (!policy)
        return XDP_PASS;

    switch (*policy) {
        case 1: // allow
            return XDP_PASS;
        case 2: // drop
            return XDP_DROP;
        case 3: { // redirect
            __u32 *ifindex = bpf_map_lookup_elem(&redirect_map, &src);
            if (!ifindex)
                return XDP_DROP;
            return bpf_redirect(*ifindex, 0);
        }
        default:
            return XDP_PASS;
    }
}
```

