```rust
use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use std::net::Ipv4Addr;
use std::process::Command;

#[derive(Parser)]
#[command(name = "ultra-net")]
#[command(about = "Low-latency XDP packet filter/forwarder control plane")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    Attach {
        #[arg(long)]
        iface: String,
        #[arg(long, default_value = "xdp/xdp_prog.o")]
        prog: String,
    },
    Detach {
        #[arg(long)]
        iface: String,
    },
    Allow {
        #[arg(long)]
        src: Ipv4Addr,
    },
    Drop {
        #[arg(long)]
        src: Ipv4Addr,
    },
    Redirect {
        #[arg(long)]
        src: Ipv4Addr,
        #[arg(long)]
        ifindex: u32,
    },
}

fn run(cmd: &mut Command) -> Result<()> {
    let status = cmd.status().context("failed to spawn command")?;
    if !status.success() {
        bail!("command failed with status: {status}");
    }
    Ok(())
}

fn ipv4_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from_ne_bytes(ip.octets())
}

fn update_policy(src: Ipv4Addr, policy: u8) -> Result<()> {
    let key = ipv4_to_u32(src);
    run(Command::new("bpftool")
        .args([
            "map", "update", "pinned", "/sys/fs/bpf/policy_map",
            "key",
            "hex",
            &format!("{:02x}", key as u8),
            &format!("{:02x}", (key >> 8) as u8),
            &format!("{:02x}", (key >> 16) as u8),
            &format!("{:02x}", (key >> 24) as u8),
            "value",
            "hex",
            &format!("{:02x}", policy),
        ]))
}

fn update_redirect(src: Ipv4Addr, ifindex: u32) -> Result<()> {
    let key = ipv4_to_u32(src);
    run(Command::new("bpftool")
        .args([
            "map", "update", "pinned", "/sys/fs/bpf/redirect_map",
            "key",
            "hex",
            &format!("{:02x}", key as u8),
            &format!("{:02x}", (key >> 8) as u8),
            &format!("{:02x}", (key >> 16) as u8),
            &format!("{:02x}", (key >> 24) as u8),
            "value",
            "hex",
            &format!("{:02x}", ifindex as u8),
            &format!("{:02x}", (ifindex >> 8) as u8),
            &format!("{:02x}", (ifindex >> 16) as u8),
            &format!("{:02x}", (ifindex >> 24) as u8),
        ]))
}

fn attach_xdp(iface: &str, prog: &str) -> Result<()> {
    run(Command::new("ip").args(["link", "set", "dev", iface, "xdp", "obj", prog, "sec", "xdp"]))?;

    // Pin maps by discovering program ID and pinning manually if needed.
    // Minimal implementation expects pre-pinned maps or a loader enhancement later.
    Ok(())
}

fn detach_xdp(iface: &str) -> Result<()> {
    run(Command::new("ip").args(["link", "set", "dev", iface, "xdp", "off"]))
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Attach { iface, prog } => attach_xdp(&iface, &prog)?,
        Commands::Detach { iface } => detach_xdp(&iface)?,
        Commands::Allow { src } => update_policy(src, 1)?,
        Commands::Drop { src } => update_policy(src, 2)?,
        Commands::Redirect { src, ifindex } => {
            update_policy(src, 3)?;
            update_redirect(src, ifindex)?;
        }
    }

    Ok(())
}
```

