```rust
use crate::config::FilterConfig;
use crate::packet::{L4Proto, ParsedPacket};
use std::collections::HashSet;
use std::net::IpAddr;

#[derive(Clone)]
pub struct PacketFilter {
    allow_src_ips: Option<HashSet<IpAddr>>,
    allow_dst_ips: Option<HashSet<IpAddr>>,
    allow_src_ports: Option<HashSet<u16>>,
    allow_dst_ports: Option<HashSet<u16>>,
    allow_protocols: Option<HashSet<L4Proto>>,
}

impl PacketFilter {
    pub fn new(cfg: &FilterConfig) -> Self {
        let allow_protocols = cfg.allow_protocols.as_ref().map(|v| {
            v.iter()
                .filter_map(|p| match p.to_ascii_lowercase().as_str() {
                    "tcp" => Some(L4Proto::Tcp),
                    "udp" => Some(L4Proto::Udp),
                    _ => None,
                })
                .collect()
        });

        Self {
            allow_src_ips: cfg
                .allow_src_ips
                .as_ref()
                .map(|v| v.iter().copied().collect()),
            allow_dst_ips: cfg
                .allow_dst_ips
                .as_ref()
                .map(|v| v.iter().copied().collect()),
            allow_src_ports: cfg
                .allow_src_ports
                .as_ref()
                .map(|v| v.iter().copied().collect()),
            allow_dst_ports: cfg
                .allow_dst_ports
                .as_ref()
                .map(|v| v.iter().copied().collect()),
            allow_protocols,
        }
    }

    pub fn permits(&self, pkt: &ParsedPacket) -> bool {
        if let Some(set) = &self.allow_src_ips {
            if !set.contains(&pkt.src_ip) {
                return false;
            }
        }
        if let Some(set) = &self.allow_dst_ips {
            if !set.contains(&pkt.dst_ip) {
                return false;
            }
        }
        if let Some(set) = &self.allow_protocols {
            if !set.contains(&pkt.proto) {
                return false;
            }
        }
        if let Some(port) = pkt.src_port {
            if let Some(set) = &self.allow_src_ports {
                if !set.contains(&port) {
                    return false;
                }
            }
        } else if self.allow_src_ports.is_some() {
            return false;
        }

        if let Some(port) = pkt.dst_port {
            if let Some(set) = &self.allow_dst_ports {
                if !set.contains(&port) {
                    return false;
                }
            }
        } else if self.allow_dst_ports.is_some() {
            return false;
        }

        true
    }
}
