# src/packet.rs

```rust
use anyhow::{anyhow, Result};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum L4Proto {
    Tcp,
    Udp,
}

#[derive(Debug, Clone)]
pub struct ParsedPacket {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: L4Proto,
}

pub fn parse_packet(buf: &[u8]) -> Result<ParsedPacket> {
    let sliced = SlicedPacket::from_ethernet(buf)
        .map_err(|e| anyhow!("packet parse error: {e}"))?;

    let (src_ip, dst_ip) = match sliced.net {
        Some(InternetSlice::Ipv4(h, _)) => (
            IpAddr::V4(Ipv4Addr::from(h.header().source())),
            IpAddr::V4(Ipv4Addr::from(h.header().destination())),
        ),
        Some(InternetSlice::Ipv6(h, _)) => (
            IpAddr::V6(Ipv6Addr::from(h.header().source())),
            IpAddr::V6(Ipv6Addr::from(h.header().destination())),
        ),
        _ => return Err(anyhow!("unsupported network layer")),
    };

    let (proto, src_port, dst_port) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (
            L4Proto::Tcp,
            Some(tcp.source_port()),
            Some(tcp.destination_port()),
        ),
        Some(TransportSlice::Udp(udp)) => (
            L4Proto::Udp,
            Some(udp.source_port()),
            Some(udp.destination_port()),
        ),
        _ => return Err(anyhow!("unsupported transport layer")),
    };

    Ok(ParsedPacket {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}
