```rust
use crate::config::{ForwardConfig, ForwardMode};
use anyhow::{anyhow, Result};
use socket2::{Domain, Protocol, SockAddr, Socket, Type};
use std::net::{IpAddr, SocketAddr};

pub struct Forwarder {
    mode: ForwardMode,
    target: Option<SocketAddr>,
    tx_socket: Option<Socket>,
}

impl Forwarder {
    pub fn new(cfg: &ForwardConfig) -> Result<Self> {
        match cfg.mode {
            ForwardMode::Drop => Ok(Self {
                mode: ForwardMode::Drop,
                target: None,
                tx_socket: None,
            }),
            ForwardMode::Ip => {
                let ip = cfg.target_ip.ok_or_else(|| anyhow!("missing target_ip"))?;
                let port = cfg.target_port.ok_or_else(|| anyhow!("missing target_port"))?;
                let addr = SocketAddr::new(ip, port);

                let domain = match ip {
                    IpAddr::V4(_) => Domain::IPV4,
                    IpAddr::V6(_) => Domain::IPV6,
                };

                let sock = Socket::new(domain, Type::DGRAM, Some(Protocol::UDP))?;
                sock.set_nonblocking(true)?;

                Ok(Self {
                    mode: ForwardMode::Ip,
                    target: Some(addr),
                    tx_socket: Some(sock),
                })
            }
        }
    }

    pub fn forward(&self, packet: &[u8]) -> Result<()> {
        match self.mode {
            ForwardMode::Drop => Ok(()),
            ForwardMode::Ip => {
                let sock = self.tx_socket.as_ref().ok_or_else(|| anyhow!("missing tx socket"))?;
                let target = self.target.ok_or_else(|| anyhow!("missing target"))?;
                let _ = sock.send_to(packet, &SockAddr::from(target))?;
                Ok(())
            }
        }
    }
}
