use std::fs;
use std::sync::atomic::Ordering;
use std::time::Duration;

#[derive(Parser, Debug)]
struct Cli {
    #[arg(short, long)]
    config: String,
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let raw = fs::read_to_string(&cli.config)
        .with_context(|| format!("failed reading config {}", cli.config))?;
    let cfg: Config = toml::from_str(&raw).context("failed parsing config")?;

    let workers = cfg.workers.unwrap_or_else(num_cpus::get);
    let stats = Stats::new();
    let filter = PacketFilter::new(&cfg.filter);

    println!(
        "starting service: iface={}, workers={}",
        cfg.interface, workers
    );

    thread::scope(|s| {
        for worker_id in 0..workers {
            let stats = stats.clone();
            let filter = filter.clone();
            let fwd_cfg = cfg.forward.clone();
            let iface = cfg.interface.clone();

            s.spawn(move |_| {
                if let Err(e) = worker_loop(worker_id, &iface, filter, fwd_cfg, stats) {
                    eprintln!("worker {} failed: {:?}", worker_id, e);
                }
            });
        }

        let stats_ref = stats.clone();
        s.spawn(move |_| loop {
            std::thread::sleep(Duration::from_secs(1));
            let snap = stats_ref.snapshot();
            println!(
                "rx_pkts={} rx_bytes={} passed={} dropped={} fwd={} parse_err={} tx_err={}",
                snap.rx_packets,
                snap.rx_bytes,
                snap.passed,
                snap.dropped,
                snap.forwarded,
                snap.parse_errors,
                snap.tx_errors
            );
        });
    })
    .unwrap();

    Ok(())
}

fn worker_loop(
    worker_id: usize,
    _iface: &str,
    filter: PacketFilter,
    fwd_cfg: config::ForwardConfig,
    stats: stats::SharedStats,
) -> Result<()> {
    let forwarder = Forwarder::new(&fwd_cfg)?;

    let mut fake_rx_ring = vec![vec![0u8; 2048]; 64];

    loop {
        for buf in &mut fake_rx_ring {
            let packet_len = synthetic_receive(buf, worker_id);
            if packet_len == 0 {
                continue;
            }

            let pkt = &buf[..packet_len];
            stats.rx_packets.fetch_add(1, Ordering::Relaxed);
            stats
                .rx_bytes
                .fetch_add(packet_len as u64, Ordering::Relaxed);

            match parse_packet(pkt) {
                Ok(parsed) => {
                    if filter.permits(&parsed) {
                        stats.passed.fetch_add(1, Ordering::Relaxed);
                        if let Err(_e) = forwarder.forward(pkt) {
                            stats.tx_errors.fetch_add(1, Ordering::Relaxed);
                        } else {
                            stats.forwarded.fetch_add(1, Ordering::Relaxed);
                        }
                    } else {
                        stats.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
                Err(_) => {
                    stats.parse_errors.fetch_add(1, Ordering::Relaxed);
                    stats.dropped.fetch_add(1, Ordering::Relaxed);
                }
            }
        }

        std::hint::spin_loop();
    }
}

fn synthetic_receive(_buf: &mut [u8], _worker_id: usize) -> usize {
    0
}
