# 1. XDP program

`xdp_fw_kern.c`
```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/in.h>
#include <linux/tcp.h>
#include <linux/udp.h>

char LICENSE[] SEC("license") = "GPL";

struct flow_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct rule_val {
    __u32 action;     // 0=drop, 1=pass, 2=redirect
    __u32 ifindex;    // target if redirect
};

struct stats_val {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key);
    __type(value, struct rule_val);
} rules SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key);
    __type(value, struct stats_val);
} stats SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct flow_key *key, __u64 *pkt_len)
{
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_ABORTED;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_ABORTED;

    if (iph->ihl < 5)
        return XDP_ABORTED;

    void *l4 = (void *)iph + iph->ihl * 4;
    if (l4 > data_end)
        return XDP_ABORTED;

    key->src_ip = iph->saddr;
    key->dst_ip = iph->daddr;
    key->proto = iph->protocol;
    key->src_port = 0;
    key->dst_port = 0;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end)
            return XDP_ABORTED;
        key->src_port = tcp->source;
        key->dst_port = tcp->dest;
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end)
            return XDP_ABORTED;
        key->src_port = udp->source;
        key->dst_port = udp->dest;
    }

    *pkt_len = (__u64)((char *)data_end - (char *)data);
    return 0;
}

static __always_inline void update_stats(struct flow_key *key, __u64 pkt_len)
{
    struct stats_val *s = bpf_map_lookup_elem(&stats, key);
    if (s) {
        __sync_fetch_and_add(&s->packets, 1);
        __sync_fetch_and_add(&s->bytes, pkt_len);
    } else {
        struct stats_val init = {
            .packets = 1,
            .bytes = pkt_len,
        };
        bpf_map_update_elem(&stats, key, &init, BPF_ANY);
    }
}

SEC("xdp")
int xdp_fw_prog(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct flow_key key = {};
    __u64 pkt_len = 0;

    int rc = parse_ipv4(data, data_end, &key, &pkt_len);
    if (rc == XDP_PASS || rc == XDP_ABORTED)
        return rc;

    update_stats(&key, pkt_len);

    struct rule_val *rule = bpf_map_lookup_elem(&rules, &key);
    if (!rule) {
        return XDP_PASS;
    }

    if (rule->action == 0)
        return XDP_DROP;
    if (rule->action == 1)
        return XDP_PASS;
    if (rule->action == 2)
        return bpf_redirect_map(&tx_port, rule->ifindex, 0);

    return XDP_PASS;
}
