// SPDX-License-Identifier: GPL-2.0
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

struct flow_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct rule_val {
    __u32 action;
    __u32 ifindex;
};

static int add_redirect_port(int devmap_fd, int ifindex)
{
    return bpf_map_update_elem(devmap_fd, &ifindex, &ifindex, BPF_ANY);
}

static int add_rule(int rules_fd,
                    const char *src_ip,
                    const char *dst_ip,
                    int src_port,
                    int dst_port,
                    int proto,
                    int action,
                    int ifindex)
{
    struct flow_key key = {};
    struct rule_val val = {
        .action = action,
        .ifindex = ifindex,
    };

    if (inet_pton(AF_INET, src_ip, &key.src_ip) != 1) return -1;
    if (inet_pton(AF_INET, dst_ip, &key.dst_ip) != 1) return -1;
    key.src_port = htons(src_port);
    key.dst_port = htons(dst_port);
    key.proto = proto;

    return bpf_map_update_elem(rules_fd, &key, &val, BPF_ANY);
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: %s <ifname> <xdp_fw_kern.o>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    const char *objfile = argv[2];
    int ifindex = if_nametoindex(ifname);
    if (!ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    struct bpf_object *obj = NULL;
    int prog_fd;
    int err;

    struct bpf_object_open_opts opts = {};
    obj = bpf_object__open_file(objfile, &opts);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "open failed\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "load failed: %d\n", err);
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_fw_prog");
    if (!prog) {
        fprintf(stderr, "program not found\n");
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    err = bpf_xdp_attach(ifindex, prog_fd, XDP_FLAGS_DRV_MODE, NULL);
    if (err) {
        fprintf(stderr, "attach failed: %d\n", err);
        return 1;
    }

    int rules_fd = bpf_object__find_map_fd_by_name(obj, "rules");
    int tx_port_fd = bpf_object__find_map_fd_by_name(obj, "tx_port");
    if (rules_fd < 0 || tx_port_fd < 0) {
        fprintf(stderr, "map lookup failed\n");
        return 1;
    }

    // Example: redirect TCP 10.0.0.1:12345 -> 10.0.0.2:80 out another NIC
    // Replace "eth1" with your authorized egress interface.
    int out_ifindex = if_nametoindex("eth1");
    if (out_ifindex > 0) {
        if (add_redirect_port(tx_port_fd, out_ifindex) == 0) {
            add_rule(rules_fd, "10.0.0.1", "10.0.0.2", 12345, 80, IPPROTO_TCP, 2, out_ifindex);
        }
    }

    printf("XDP forwarding service attached to %s (ifindex=%d)\n", ifname, ifindex);
    printf("Press Ctrl+C to exit\n");
    while (1) pause();

    return 0;
}
