## `xdp_filter_kern.c`
```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct {
    __uint(type, BPF_MAP_TYPE_XSKMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} xsks_map SEC(".maps");

struct filter_stats {
    __u64 passed;
    __u64 dropped;
};

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct filter_stats);
} stats_map SEC(".maps");

static __always_inline void count_pass(void) {
    __u32 key = 0;
    struct filter_stats *s = bpf_map_lookup_elem(&stats_map, &key);
    if (s) s->passed++;
}

static __always_inline void count_drop(void) {
    __u32 key = 0;
    struct filter_stats *s = bpf_map_lookup_elem(&stats_map, &key);
    if (s) s->dropped++;
}

SEC("xdp")
int xdp_filter_prog(struct xdp_md *ctx)
{
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        count_drop();
        return XDP_DROP;
    }

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP) {
        count_drop();
        return XDP_DROP;
    }

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        count_drop();
        return XDP_DROP;
    }

    if (iph->ihl < 5) {
        count_drop();
        return XDP_DROP;
    }

    void *l4 = (void *)iph + iph->ihl * 4;
    if (l4 > data_end) {
        count_drop();
        return XDP_DROP;
    }

    // Example fast-path policy:
    // Drop fragments for simplicity in initial implementation.
    if (iph->frag_off & bpf_htons(0x1FFF)) {
        count_drop();
        return XDP_DROP;
    }

    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end) {
            count_drop();
            return XDP_DROP;
        }

        // Example: drop UDP dst port 1900 (SSDP) as a simple policy
        if (bpf_ntohs(udp->dest) == 1900) {
            count_drop();
            return XDP_DROP;
        }
    } else if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end) {
            count_drop();
            return XDP_DROP;
        }
    } else {
        // Only allow TCP/UDP in this initial version
        count_drop();
        return XDP_DROP;
    }

    count_pass();

    // Redirect to AF_XDP socket bound to this RX queue
    return bpf_redirect_map(&xsks_map, ctx->rx_queue_index, XDP_PASS);
}

