## `rules.h`
```cpp
#pragma once
#include <cstdint>
#include <vector>

enum class Action : uint8_t {
    DROP = 0,
    FORWARD = 1,
};

struct Rule {
    uint32_t src_ip = 0;      // network byte order, 0 = wildcard
    uint32_t dst_ip = 0;      // network byte order, 0 = wildcard
    uint16_t src_port = 0;    // host byte order, 0 = wildcard
    uint16_t dst_port = 0;    // host byte order, 0 = wildcard
    uint8_t  proto = 0;       // IPPROTO_TCP/IPPROTO_UDP, 0 = wildcard
    Action action = Action::DROP;
};

struct PacketMeta {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
};

inline bool rule_matches(const Rule& r, const PacketMeta& p) {
    if (r.src_ip && r.src_ip != p.src_ip) return false;
    if (r.dst_ip && r.dst_ip != p.dst_ip) return false;
    if (r.src_port && r.src_port != p.src_port) return false;
    if (r.dst_port && r.dst_port != p.dst_port) return false;
    if (r.proto && r.proto != p.proto) return false;
    return true;
}

inline Action evaluate_rules(const std::vector<Rule>& rules, const PacketMeta& p) {
    for (const auto& r : rules) {
        if (rule_matches(r, p)) return r.action;
    }
    return Action::DROP;
}
