static bool parse_packet(const uint8_t* buf, size_t len, PacketMeta& out) {
    if (len < sizeof(ethhdr) + sizeof(iphdr)) return false;

    auto eth = reinterpret_cast<const ethhdr*>(buf);
    if (ntohs(eth->h_proto) != ETH_P_IP) return false;

    auto iph = reinterpret_cast<const iphdr*>(buf + sizeof(ethhdr));
    if (len < sizeof(ethhdr) + sizeof(iphdr)) return false;
    if (iph->ihl < 5) return false;

    size_t ip_header_len = iph->ihl * 4;
    if (len < sizeof(ethhdr) + ip_header_len) return false;

    out.src_ip = iph->saddr;
    out.dst_ip = iph->daddr;
    out.proto = iph->protocol;
    out.src_port = 0;
    out.dst_port = 0;

    const uint8_t* l4 = buf + sizeof(ethhdr) + ip_header_len;
    size_t l4_len = len - sizeof(ethhdr) - ip_header_len;

    if (iph->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(tcphdr)) return false;
        auto tcp = reinterpret_cast<const tcphdr*>(l4);
        out.src_port = ntohs(tcp->source);
        out.dst_port = ntohs(tcp->dest);
    } else if (iph->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(udphdr)) return false;
        auto udp = reinterpret_cast<const udphdr*>(l4);
        out.src_port = ntohs(udp->source);
        out.dst_port = ntohs(udp->dest);
