        if (len == 0) {
            continue;
        }

        counters.rx_packets++;

        PacketMeta meta{};
        if (!parse_packet(buf, len, meta)) {
            counters.parse_errors++;
            counters.dropped++;
            continue;
        }

        Action action = evaluate_rules(rules, meta);
        if (action == Action::DROP) {
            counters.dropped++;
            continue;
        }

        if (forward_packet(buf, len)) {
            counters.tx_packets++;
        } else {
            counters.dropped++;
        }
    }

    std::cout << "rx=" << counters.rx_packets
              << " tx=" << counters.tx_packets
              << " dropped=" << counters.dropped
              << " parse_errors=" << counters.parse_errors
              << "\n";

    return 0;
}
