# 1. XDP program: `xdp_policy.c`

```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct flow_key_v4 {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 src_port;
    __u16 dst_port;
    __u8  proto;
    __u8  pad1;
    __u16 pad2;
};

struct rule_action {
    __u32 action;       // 0=pass, 1=drop, 2=redirect
    __u32 ifindex;      // used when action=redirect
};

struct counter {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key_v4);
    __type(value, struct rule_action);
} rules_v4 SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key_v4);
    __type(value, struct counter);
} counters_v4 SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

static __always_inline int parse_eth(void **data, void *data_end, __u16 *eth_proto) {
    struct ethhdr *eth = *data;
    if ((void *)(eth + 1) > data_end)
        return -1;
    *eth_proto = bpf_ntohs(eth->h_proto);
    *data = eth + 1;
    return 0;
}

static __always_inline int parse_ipv4(void **data, void *data_end, struct iphdr **iph) {
    *iph = *data;
    if ((void *)(*iph + 1) > data_end)
        return -1;
    if ((*iph)->ihl < 5)
        return -1;
    if ((void *)(*iph) + ((*iph)->ihl * 4) > data_end)
        return -1;
    *data = (void *)(*iph) + ((*iph)->ihl * 4);
    return 0;
}

static __always_inline int parse_tcp(void **data, void *data_end, struct tcphdr **tcph) {
    *tcph = *data;
    if ((void *)(*tcph + 1) > data_end)
        return -1;
    return 0;
}

static __always_inline int parse_udp(void **data, void *data_end, struct udphdr **udph) {
    *udph = *data;
    if ((void *)(*udph + 1) > data_end)
        return -1;
    return 0;
}

static __always_inline void count_v4(struct flow_key_v4 *key, __u64 bytes) {
    struct counter *c = bpf_map_lookup_elem(&counters_v4, key);
    if (!c) {
        struct counter init = { .packets = 1, .bytes = bytes };
        bpf_map_update_elem(&counters_v4, key, &init, BPF_ANY);
        return;
    }
    __sync_fetch_and_add(&c->packets, 1);
    __sync_fetch_and_add(&c->bytes, bytes);
}

SEC("xdp")
int xdp_policy(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    void *cursor = data;
    __u16 eth_proto;

    if (parse_eth(&cursor, data_end, &eth_proto) < 0)
        return XDP_PASS;

    if (eth_proto != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *iph;
    if (parse_ipv4(&cursor, data_end, &iph) < 0)
        return XDP_PASS;

    struct flow_key_v4 key = {};
    key.src_ip = iph->saddr;
    key.dst_ip = iph->daddr;
    key.proto = iph->protocol;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcph;
        if (parse_tcp(&cursor, data_end, &tcph) < 0)
            return XDP_PASS;
        key.src_port = tcph->source;
        key.dst_port = tcph->dest;
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udph;
        if (parse_udp(&cursor, data_end, &udph) < 0)
            return XDP_PASS;
        key.src_port = udph->source;
        key.dst_port = udph->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    count_v4(&key, (__u64)(data_end - data));

    struct rule_action *ra = bpf_map_lookup_elem(&rules_v4, &key);
    if (!ra)
        return XDP_PASS;

    if (ra->action == 1)
        return XDP_DROP;

    if (ra->action == 2) {
        __u32 port_key = ra->ifindex;
        return bpf_redirect_map(&tx_port, port_key, XDP_PASS);
    }

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

