# 2. Go control plane: `main.go`

```go
package main

import (
	"encoding/binary"
	"errors"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
)

type FlowKeyV4 struct {
	SrcIP   uint32
	DstIP   uint32
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	Pad1    uint8
	Pad2    uint16
}

type RuleAction struct {
	Action  uint32
	Ifindex uint32
}

func ipToU32(ip string) (uint32, error) {
	parsed := net.ParseIP(ip).To4()
	if parsed == nil {
		return 0, errors.New("invalid IPv4")
	}
	return binary.BigEndian.Uint32(parsed), nil
}

func htons(v uint16) uint16 {
	return (v<<8)&0xff00 | v>>8
}

func mustMap(coll *ebpf.Collection, name string) *ebpf.Map {
	m := coll.Maps[name]
	if m == nil {
		log.Fatalf("map %s not found", name)
	}
	return m
}

func mustProg(coll *ebpf.Collection, name string) *ebpf.Program {
	p := coll.Programs[name]
	if p == nil {
		log.Fatalf("program %s not found", name)
	}
	return p
}

func main() {
	spec, err := ebpf.LoadCollectionSpec("xdp_policy.o")
	if err != nil {
		log.Fatalf("load spec: %v", err)
	}

	coll, err := ebpf.NewCollection(spec)
	if err != nil {
		log.Fatalf("new collection: %v", err)
	}
	defer coll.Close()

	ifaceName := os.Getenv("IFACE")
	if ifaceName == "" {
		log.Fatal("set IFACE")
	}

	iface, err := net.InterfaceByName(ifaceName)
	if err != nil {
		log.Fatalf("lookup iface: %v", err)
	}

	prog := mustProg(coll, "xdp_policy")
	l, err := link.AttachXDP(link.XDPOptions{
		Program:   prog,
		Interface: iface.Index,
	})
	if err != nil {
		log.Fatalf("attach xdp: %v", err)
	}
	defer l.Close()

	rules := mustMap(coll, "rules_v4")
	txPort := mustMap(coll, "tx_port")
	counters := mustMap(coll, "counters_v4")

	redirIfaceName := os.Getenv("REDIRECT_IFACE")
	if redirIfaceName != "" {
		redirIface, err := net.InterfaceByName(redirIfaceName)
		if err != nil {
			log.Fatalf("lookup redirect iface: %v", err)
		}
		key := uint32(redirIface.Index)
		val := uint32(redirIface.Index)
		if err := txPort.Put(key, val); err != nil {
			log.Fatalf("populate devmap: %v", err)
		}
	}

	srcIP, _ := ipToU32("10.0.0.10")
	dstIP, _ := ipToU32("10.0.0.20")

	key := FlowKeyV4{
		SrcIP:   srcIP,
		DstIP:   dstIP,
		SrcPort: htons(12345),
		DstPort: htons(443),
		Proto:   syscall.IPPROTO_TCP,
	}
	action := RuleAction{Action: 1, Ifindex: 0} // drop
	if err := rules.Put(key, action); err != nil {
		log.Fatalf("insert rule: %v", err)
	}

	log.Printf("XDP policy attached to %s (ifindex=%d)", iface.Name, iface.Index)

	go func() {
		t := time.NewTicker(5 * time.Second)
		defer t.Stop()
		for range t.C {
			var nextKey FlowKeyV4
			var val struct {
				Packets uint64
				Bytes   uint64
			}
			iter := counters.Iterate()
			fmt.Println("---- counters ----")
			for iter.Next(&nextKey, &val) {
				fmt.Printf("src=%08x dst=%08x sport=%d dport=%d proto=%d packets=%d bytes=%d\n",
					nextKey.SrcIP, nextKey.DstIP, ntohs(nextKey.SrcPort), ntohs(nextKey.DstPort),
					nextKey.Proto, val.Packets, val.Bytes)
			}
			if err := iter.Err(); err != nil {
				log.Printf("iterate counters: %v", err)
			}
		}
	}()

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, os.Interrupt, syscall.SIGTERM)
	<-sigc
	log.Println("shutting down")
}

func ntohs(v uint16) uint16 {
	return htons(v)
}
