mod packet;
mod rules;
mod pipeline;
mod metrics;
mod io;

use std::sync::Arc;
use std::thread;

use anyhow::Result;
use arc_swap::ArcSwap;

use crate::io::{MockRx, MockTx};
use crate::metrics::Metrics;
use crate::pipeline::process_batch;
use crate::rules::{RuleSet, ForwardAction};

const BATCH_SIZE: usize = 64;
const WORKERS: usize = 4;

fn main() -> Result<()> {
    let initial_rules = RuleSet::default_allow_with(vec![
        ForwardAction::DropTcpDstPort(23),
        ForwardAction::DropUdpDstPort(1900),
        ForwardAction::ForwardIpv4 {
            dst_subnet: [10, 0, 0, 0],
            prefix_len: 24,
            out_port: 1,
        },
        ForwardAction::ForwardIpv4 {
            dst_subnet: [0, 0, 0, 0],
            prefix_len: 0,
            out_port: 0,
        },
    ]);

    let rules = Arc::new(ArcSwap::from_pointee(initial_rules));
    let metrics = Arc::new(Metrics::default());

    let mut handles = Vec::new();

    for worker_id in 0..WORKERS {
        let rules = rules.clone();
        let metrics = metrics.clone();

        let handle = thread::Builder::new()
            .name(format!("worker-{worker_id}"))
            .spawn(move || {
                let mut rx = MockRx::new(worker_id);
                let mut tx = MockTx::new(worker_id);

                let mut batch = Vec::with_capacity(BATCH_SIZE);

                loop {
                    batch.clear();
                    rx.recv_batch(&mut batch, BATCH_SIZE);

                    if batch.is_empty() {
                        std::thread::yield_now();
                        continue;
                    }

                    let snapshot = rules.load();
                    process_batch(&batch, &snapshot, &mut tx, &metrics);
                }
            })?;

        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    Ok(())
}
