## `src/packet.rs`

```rust
#[derive(Clone, Debug)]
pub struct Packet {
    pub data: Vec<u8>,
    pub ingress_port: u16,
    pub timestamp_ns: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EtherType {
    Ipv4,
    Ipv6,
    Arp,
    Other(u16),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpProto {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct ParsedPacket<'a> {
    pub ethertype: EtherType,
    pub src_ip: Option<[u8; 4]>,
    pub dst_ip: Option<[u8; 4]>,
    pub ip_proto: Option<IpProto>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub payload: &'a [u8],
}

impl Packet {
    pub fn parse(&self) -> Option<ParsedPacket<'_>> {
        if self.data.len() < 14 {
            return None;
        }

        let ethertype_raw = u16::from_be_bytes([self.data[12], self.data[13]]);
        let ethertype = match ethertype_raw {
            0x0800 => EtherType::Ipv4,
            0x86DD => EtherType::Ipv6,
            0x0806 => EtherType::Arp,
            x => EtherType::Other(x),
        };

        match ethertype {
            EtherType::Ipv4 => self.parse_ipv4(),
            _ => Some(ParsedPacket {
                ethertype,
                src_ip: None,
                dst_ip: None,
                ip_proto: None,
                src_port: None,
                dst_port: None,
                payload: &self.data[14..],
            }),
        }
    }

    fn parse_ipv4(&self) -> Option<ParsedPacket<'_>> {
        if self.data.len() < 34 {
            return None;
        }

        let ip_start = 14;
        let version_ihl = self.data[ip_start];
        let version = version_ihl >> 4;
        let ihl = (version_ihl & 0x0f) as usize * 4;

        if version != 4 || self.data.len() < ip_start + ihl {
            return None;
        }

        let proto = match self.data[ip_start + 9] {
            6 => IpProto::Tcp,
            17 => IpProto::Udp,
            1 => IpProto::Icmp,
            x => IpProto::Other(x),
        };

        let src_ip = [
            self.data[ip_start + 12],
            self.data[ip_start + 13],
            self.data[ip_start + 14],
            self.data[ip_start + 15],
        ];

        let dst_ip = [
            self.data[ip_start + 16],
            self.data[ip_start + 17],
            self.data[ip_start + 18],
            self.data[ip_start + 19],
        ];

        let l4_start = ip_start + ihl;

        let (src_port, dst_port) = match proto {
            IpProto::Tcp | IpProto::Udp => {
                if self.data.len() < l4_start + 4 {
                    (None, None)
                } else {
                    let sp = u16::from_be_bytes([self.data[l4_start], self.data[l4_start + 1]]);
                    let dp = u16::from_be_bytes([self.data[l4_start + 2], self.data[l4_start + 3]]);
                    (Some(sp), Some(dp))
                }
            }
            _ => (None, None),
        };

        Some(ParsedPacket {
            ethertype: EtherType::Ipv4,
            src_ip: Some(src_ip),
            dst_ip: Some(dst_ip),
            ip_proto: Some(proto),
            src_port,
            dst_port,
            payload: if self.data.len() > l4_start {
                &self.data[l4_start..]
            } else {
                &[]
            },
        })
    }
}
