    DropTcpDstPort(u16),
    DropUdpDstPort(u16),
    ForwardIpv4 {
        dst_subnet: [u8; 4],
        prefix_len: u8,
        out_port: u16,
    },
}

#[derive(Debug, Clone)]
pub struct RuleSet {
    pub rules: Vec<ForwardAction>,
    pub default: Decision,
}

impl RuleSet {
    pub fn default_allow_with(rules: Vec<ForwardAction>) -> Self {
        Self {
            rules,
            default: Decision::Forward { out_port: 0 },
        }
    }

    pub fn evaluate(&self, pkt: &ParsedPacket<'_>) -> Decision {
        for rule in &self.rules {
            match *rule {
                ForwardAction::DropTcpDstPort(port) => {
                    if pkt.ethertype == EtherType::Ipv4
                        && pkt.ip_proto == Some(IpProto::Tcp)
                        && pkt.dst_port == Some(port)
                    {
                        return Decision::Drop;
                    }
                }
                ForwardAction::DropUdpDstPort(port) => {
                    if pkt.ethertype == EtherType::Ipv4
                        && pkt.ip_proto == Some(IpProto::Udp)
                        && pkt.dst_port == Some(port)
                    {
                        return Decision::Drop;
                    }
                }
                ForwardAction::ForwardIpv4 {
                    dst_subnet,
                    prefix_len,
                    out_port,
                } => {
                    if let Some(dst) = pkt.dst_ip {
                        if ipv4_prefix_match(dst, dst_subnet, prefix_len) {
                            return Decision::Forward { out_port };
                        }
                    }
                }
            }
        }

        self.default.clone()
    }
}

fn ipv4_prefix_match(ip: [u8; 4], subnet: [u8; 4], prefix_len: u8) -> bool {
    let ip = u32::from_be_bytes(ip);
    let subnet = u32::from_be_bytes(subnet);

    let mask = if prefix_len == 0 {
        0
    } else {
        u32::MAX << (32 - prefix_len)
    };

    (ip & mask) == (subnet & mask)
}
