## `src/pipeline.rs`

```rust
use crate::io::Tx;
use crate::metrics::Metrics;
use crate::packet::Packet;
use crate::rules::{Decision, RuleSet};

pub fn process_batch<T: Tx>(
    batch: &[Packet],
    rules: &RuleSet,
    tx: &mut T,
    metrics: &Metrics,
) {
    for pkt in batch {
        metrics.rx_packets.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

        let parsed = match pkt.parse() {
            Some(p) => p,
            None => {
                metrics.parse_errors.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                continue;
            }
        };

        match rules.evaluate(&parsed) {
            Decision::Drop => {
                metrics.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            }
            Decision::Forward { out_port } => {
                if tx.send(out_port, pkt).is_ok() {
                    metrics.tx_packets.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                } else {
                    metrics.tx_errors.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
            }
        }
    }
}
