## Minimal safe initial implementation

Below is a starter XDP filter that:
- parses Ethernet/IPv4/TCP/UDP
- drops malformed packets
- allows only configured destination ports
- counts passes/drops
- does not do covert forwarding or arbitrary interception

### `xdp_filter.c`
```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u16);   // destination port in host order
    __type(value, __u8);  // 1 = allowed
} allowed_ports SEC(".maps");

struct stats_key {
    __u32 action;
};

struct stats_val {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 16);
    __type(key, struct stats_key);
    __type(value, struct stats_val);
} stats SEC(".maps");

static __always_inline void count_stat(__u32 action, __u64 bytes) {
    struct stats_key key = { .action = action };
    struct stats_val *val = bpf_map_lookup_elem(&stats, &key);
    if (!val) return;
    __sync_fetch_and_add(&val->packets, 1);
    __sync_fetch_and_add(&val->bytes, bytes);
}

static __always_inline int parse_ipv4_l4(void *data, void *data_end, struct iphdr **iph_out, void **l4h_out) {
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return -1;

    if (iph->ihl < 5)
        return -1;

    void *l4h = (void *)iph + iph->ihl * 4;
    if (l4h > data_end)
        return -1;

    *iph_out = iph;
    *l4h_out = l4h;
    return 0;
}

SEC("xdp")
int xdp_port_allowlist(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    __u64 pkt_len = (__u64)(data_end - data);

    struct iphdr *iph;
    void *l4h;

    if (parse_ipv4_l4(data, data_end, &iph, &l4h) < 0) {
        count_stat(XDP_DROP, pkt_len);
        return XDP_DROP;
    }

    __u16 dport = 0;

    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4h;
        if ((void *)(tcp + 1) > data_end) {
            count_stat(XDP_DROP, pkt_len);
            return XDP_DROP;
        }
        dport = bpf_ntohs(tcp->dest);
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4h;
        if ((void *)(udp + 1) > data_end) {
            count_stat(XDP_DROP, pkt_len);
            return XDP_DROP;
        }
        dport = bpf_ntohs(udp->dest);
    } else {
        count_stat(XDP_DROP, pkt_len);
        return XDP_DROP;
    }

    __u8 *allowed = bpf_map_lookup_elem(&allowed_ports, &dport);
    if (!allowed || *allowed != 1) {
        count_stat(XDP_DROP, pkt_len);
        return XDP_DROP;
    }

    count_stat(XDP_PASS, pkt_len);
    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

