### `src/main.rs`
```rust
use anyhow::Context;
use aya::maps::HashMap;
use aya::programs::{Xdp, XdpFlags};
use aya::Bpf;
use clap::Parser;

#[derive(Parser, Debug)]
struct Args {
    #[arg(long)]
    iface: String,

    #[arg(long, value_delimiter = ',')]
    allow_port: Vec<u16>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    let mut bpf = Bpf::load_file("xdp_filter.o")
        .context("loading BPF object file")?;

    let program: &mut Xdp = bpf
        .program_mut("xdp_port_allowlist")
        .context("finding XDP program")?
        .try_into()
        .context("casting to XDP")?;

    program.load().context("loading XDP program")?;
    program
        .attach(&args.iface, XdpFlags::default())
        .context("attaching XDP program")?;

    let mut allowed_ports: HashMap<_, u16, u8> =
        HashMap::try_from(bpf.map_mut("allowed_ports").context("allowed_ports map")?)?;

    for port in args.allow_port {
        allowed_ports.insert(port, 1, 0).context("inserting allowed port")?;
    }

    println!("XDP filter attached to {}", args.iface);
    println!("Allowed ports configured. Press Ctrl-C to exit.");

    tokio::signal::ctrl_c().await?;
    println!("Detaching and exiting.");
    Ok(())
}
```

