#include <unistd.h>

#ifndef likely
#define likely(x)   __builtin_expect((x),1)
#endif
#ifndef unlikely
#define unlikely(x) __builtin_expect((x),0)
#endif

#define RX_BUF_SIZE 2048
#define BATCH_SIZE  64

static volatile sig_atomic_t g_running = 1;

struct stats {
    uint64_t rx_packets;
    uint64_t rx_bytes;
    uint64_t dropped_packets;
    uint64_t passed_packets;
    uint64_t forwarded_packets;
    uint64_t parse_errors;
};

struct config {
    char ifname[IFNAMSIZ];
    int ifindex;
    int rx_sock;
    int tx_sock;
    bool forward_enabled;
    struct sockaddr_in forward_addr;

    // Simple filtering policy:
    // allow only IPv4, optionally only UDP/TCP, and optional dst port match.
    bool allow_udp;
    bool allow_tcp;
    uint16_t allow_dst_port; // 0 means any
};

static struct stats g_stats;

static void on_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static uint16_t ip_checksum(const void *buf, size_t hdr_len) {
    unsigned long sum = 0;
    const uint16_t *ip1 = buf;

    while (hdr_len > 1) {
        sum += *ip1++;
        if (sum & 0x80000000)
            sum = (sum & 0xFFFF) + (sum >> 16);
        hdr_len -= 2;
    }

    if (hdr_len)
        sum += *((uint8_t *)ip1);

    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);

    return (uint16_t)(~sum);
}

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

static int open_rx_socket(const char *ifname, int *ifindex_out) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_IP));
    if (fd < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl(SIOCGIFINDEX)");
        close(fd);
        return -1;
    }

    int ifindex = ifr.ifr_ifindex;

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family   = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_IP);
    sll.sll_ifindex  = ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind(AF_PACKET)");
        close(fd);
        return -1;
    }

    if (set_nonblocking(fd) < 0) {
        perror("fcntl(O_NONBLOCK)");
        close(fd);
        return -1;
    }

    *ifindex_out = ifindex;
    return fd;
}

static int open_tx_socket(void) {
    int fd = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (fd < 0) {
        perror("socket(AF_INET, SOCK_RAW)");
        return -1;
    }

    int one = 1;
    if (setsockopt(fd, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one)) < 0) {
        perror("setsockopt(IP_HDRINCL)");
        close(fd);
        return -1;
    }

    return fd;
}

static bool parse_ipv4_l4(
    const uint8_t *buf,
    ssize_t len,
    const struct iphdr **iph_out,
    const struct udphdr **udph_out,
    const struct tcphdr **tcph_out
) {
    *iph_out = NULL;
    *udph_out = NULL;
    *tcph_out = NULL;

    if ((size_t)len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return false;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return false;

    const struct iphdr *iph = (const struct iphdr *)(buf + sizeof(struct ethhdr));
    if (iph->version != 4)
        return false;

    size_t iphdr_len = iph->ihl * 4;
    if (iphdr_len < sizeof(struct iphdr))
        return false;

    if ((size_t)len < sizeof(struct ethhdr) + iphdr_len)
        return false;

    const uint8_t *l4 = buf + sizeof(struct ethhdr) + iphdr_len;
    size_t l4_len = len - sizeof(struct ethhdr) - iphdr_len;

    if (iph->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr))
            return false;
        *udph_out = (const struct udphdr *)l4;
    } else if (iph->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr))
            return false;
        *tcph_out = (const struct tcphdr *)l4;
    }

    *iph_out = iph;
    return true;
}

static bool packet_allowed(const struct config *cfg,
                           const struct iphdr *iph,
                           const struct udphdr *udph,
                           const struct tcphdr *tcph) {
    if (!iph)
        return false;

    if (iph->protocol == IPPROTO_UDP) {
        if (!cfg->allow_udp || !udph)
            return false;
        if (cfg->allow_dst_port != 0 &&
            ntohs(udph->dest) != cfg->allow_dst_port)
            return false;
        return true;
    }

    if (iph->protocol == IPPROTO_TCP) {
        if (!cfg->allow_tcp || !tcph)
            return false;
        if (cfg->allow_dst_port != 0 &&
            ntohs(tcph->dest) != cfg->allow_dst_port)
            return false;
        return true;
    }

    return false;
}

static int forward_ipv4_packet(const struct config *cfg,
                               const uint8_t *frame,
                               ssize_t frame_len) {
    if (!cfg->forward_enabled)
        return 0;

    if ((size_t)frame_len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return -1;

    const uint8_t *ip_packet = frame + sizeof(struct ethhdr);
    ssize_t ip_len = frame_len - sizeof(struct ethhdr);

    struct iphdr *ip_copy = malloc(ip_len);
    if (!ip_copy)
        return -1;

    memcpy(ip_copy, ip_packet, ip_len);

    // Example administrative forwarding behavior:
    // refresh IPv4 checksum before transmit.
    ip_copy->check = 0;
    ip_copy->check = ip_checksum(ip_copy, ip_copy->ihl * 4);

    ssize_t sent = sendto(cfg->tx_sock,
                          ip_copy,
                          ip_len,
                          0,
                          (const struct sockaddr *)&cfg->forward_addr,
                          sizeof(cfg->forward_addr));
    free(ip_copy);

    if (sent < 0) {
        return -1;
    }

    return 0;
}

static void print_stats_periodic(void) {
    static time_t last = 0;
    time_t now = time(NULL);
    if (now == last)
        return;
    last = now;

    fprintf(stderr,
            "rx=%llu bytes=%llu passed=%llu dropped=%llu fwd=%llu parse_err=%llu\n",
            (unsigned long long)g_stats.rx_packets,
            (unsigned long long)g_stats.rx_bytes,
            (unsigned long long)g_stats.passed_packets,
            (unsigned long long)g_stats.dropped_packets,
            (unsigned long long)g_stats.forwarded_packets,
            (unsigned long long)g_stats.parse_errors);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -i <ifname> [--udp] [--tcp] [--port N] [--forward IP]\n"
        "Examples:\n"
        "  %s -i eth0 --udp --port 53\n"
        "  %s -i eth0 --tcp --forward 192.0.2.10\n",
        prog, prog, prog);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->allow_udp = false;
    cfg->allow_tcp = false;
    cfg->allow_dst_port = 0;
    cfg->forward_enabled = false;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-i") && i + 1 < argc) {
            strncpy(cfg->ifname, argv[++i], IFNAMSIZ - 1);
        } else if (!strcmp(argv[i], "--udp")) {
            cfg->allow_udp = true;
        } else if (!strcmp(argv[i], "--tcp")) {
            cfg->allow_tcp = true;
        } else if (!strcmp(argv[i], "--port") && i + 1 < argc) {
            cfg->allow_dst_port = (uint16_t)atoi(argv[++i]);
        } else if (!strcmp(argv[i], "--forward") && i + 1 < argc) {
            memset(&cfg->forward_addr, 0, sizeof(cfg->forward_addr));
            cfg->forward_addr.sin_family = AF_INET;
            if (inet_pton(AF_INET, argv[++i], &cfg->forward_addr.sin_addr) != 1) {
                fprintf(stderr, "invalid forward IP\n");
                return -1;
            }
            cfg->forward_enabled = true;
        } else {
            usage(argv[0]);
            return -1;
        }
    }

    if (cfg->ifname[0] == '\0') {
        usage(argv[0]);
        return -1;
    }

    if (!cfg->allow_udp && !cfg->allow_tcp) {
        // default: allow both
        cfg->allow_udp = true;
        cfg->allow_tcp = true;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    if (parse_args(argc, argv, &cfg) < 0)
        return 1;

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    cfg.rx_sock = open_rx_socket(cfg.ifname, &cfg.ifindex);
    if (cfg.rx_sock < 0)
        return 1;

    if (cfg.forward_enabled) {
        cfg.tx_sock = open_tx_socket();
        if (cfg.tx_sock < 0) {
            close(cfg.rx_sock);
            return 1;
        }
    }

    uint8_t *buffers[BATCH_SIZE];
    for (int i = 0; i < BATCH_SIZE; i++) {
        buffers[i] = aligned_alloc(64, RX_BUF_SIZE);
        if (!buffers[i]) {
            perror("aligned_alloc");
            return 1;
        }
    }

    while (g_running) {
        for (int i = 0; i < BATCH_SIZE; i++) {
            ssize_t n = recvfrom(cfg.rx_sock, buffers[i], RX_BUF_SIZE, 0, NULL, NULL);
            if (n < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK)
                    break;
                if (errno == EINTR)
                    continue;
                perror("recvfrom");
                g_running = 0;
                break;
            }

            g_stats.rx_packets++;
            g_stats.rx_bytes += (uint64_t)n;

            const struct iphdr *iph = NULL;
            const struct udphdr *udph = NULL;
            const struct tcphdr *tcph = NULL;

            if (!parse_ipv4_l4(buffers[i], n, &iph, &udph, &tcph)) {
                g_stats.parse_errors++;
                g_stats.dropped_packets++;
                continue;
            }

            if (!packet_allowed(&cfg, iph, udph, tcph)) {
                g_stats.dropped_packets++;
                continue;
            }

            g_stats.passed_packets++;

            if (cfg.forward_enabled) {
                if (forward_ipv4_packet(&cfg, buffers[i], n) == 0) {
                    g_stats.forwarded_packets++;
                } else {
                    g_stats.dropped_packets++;
                }
            }
        }

        print_stats_periodic();
    }

    for (int i = 0; i < BATCH_SIZE; i++)
        free(buffers[i]);

    if (cfg.forward_enabled)
        close(cfg.tx_sock);
    close(cfg.rx_sock);

    return 0;
}
