use anyhow::{Context, Result};
use ipnet::IpNet;
use serde::Deserialize;
use std::{
    net::{IpAddr, SocketAddr},
    sync::Arc,
    time::Instant,
};
use tokio::{
    net::UdpSocket,
    sync::mpsc,
};
use tracing::{debug, error, info, warn};

const MAX_PACKET_SIZE: usize = 2048;
const CHANNEL_CAPACITY: usize = 4096;

#[derive(Debug, Clone, Deserialize)]
struct Config {
    listeners: Vec<ListenerConfig>,
    rules: Vec<RuleConfig>,
    backends: Vec<BackendConfig>,
}

#[derive(Debug, Clone, Deserialize)]
struct ListenerConfig {
    bind: SocketAddr,
}

#[derive(Debug, Clone, Deserialize)]
struct BackendConfig {
    name: String,
    addr: SocketAddr,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Protocol {
    Udp,
    Tcp,
    Any,
}

#[derive(Debug, Clone, Deserialize)]
struct RuleConfig {
    name: String,
    src_cidr: Option<IpNet>,
    dst_port: Option<u16>,
    protocol: Option<Protocol>,
    min_len: Option<usize>,
    max_len: Option<usize>,
    action: ActionConfig,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
enum ActionConfig {
    Drop,
    Forward { backend: String },
}

#[derive(Debug, Clone)]
struct PacketMeta {
    src: SocketAddr,
    local_dst: SocketAddr,
    len: usize,
    protocol: Protocol,
    received_at: Instant,
}

#[derive(Debug)]
struct Packet {
    meta: PacketMeta,
    buf: Vec<u8>,
}

#[derive(Debug, Clone)]
enum Decision {
    Drop(&'static str),
    Forward(SocketAddr),
}

#[derive(Debug)]
struct CompiledRule {
    name: String,
    src_cidr: Option<IpNet>,
    dst_port: Option<u16>,
    protocol: Option<Protocol>,
    min_len: Option<usize>,
    max_len: Option<usize>,
    action: CompiledAction,
}

#[derive(Debug)]
enum CompiledAction {
    Drop,
    Forward(SocketAddr),
}

#[derive(Debug)]
struct Engine {
    rules: Arc<Vec<CompiledRule>>,
}

impl Engine {
    fn from_config(cfg: &Config) -> Result<Self> {
        let mut compiled = Vec::with_capacity(cfg.rules.len());

        for rule in &cfg.rules {
            let action = match &rule.action {
                ActionConfig::Drop => CompiledAction::Drop,
                ActionConfig::Forward { backend } => {
                    let be = cfg
                        .backends
                        .iter()
                        .find(|b| &b.name == backend)
                        .with_context(|| format!("backend not found: {}", backend))?;
                    CompiledAction::Forward(be.addr)
                }
            };

            compiled.push(CompiledRule {
                name: rule.name.clone(),
                src_cidr: rule.src_cidr,
                dst_port: rule.dst_port,
                protocol: rule.protocol.clone(),
                min_len: rule.min_len,
                max_len: rule.max_len,
                action,
            });
        }

        Ok(Self {
            rules: Arc::new(compiled),
        })
    }

    fn classify(&self, meta: &PacketMeta) -> Decision {
        for rule in self.rules.iter() {
            if let Some(cidr) = rule.src_cidr {
                if !cidr.contains(&meta.src.ip()) {
                    continue;
                }
            }

            if let Some(port) = rule.dst_port {
                if meta.local_dst.port() != port {
                    continue;
                }
            }

            if let Some(proto) = &rule.protocol {
                if !protocol_matches(proto, &meta.protocol) {
                    continue;
                }
            }

            if let Some(min_len) = rule.min_len {
                if meta.len < min_len {
                    continue;
                }
            }

            if let Some(max_len) = rule.max_len {
                if meta.len > max_len {
                    continue;
                }
            }

            return match rule.action {
                CompiledAction::Drop => Decision::Drop("rule_drop"),
                CompiledAction::Forward(addr) => Decision::Forward(addr),
            };
        }

        Decision::Drop("default_deny")
    }
}

fn protocol_matches(rule: &Protocol, pkt: &Protocol) -> bool {
    matches!(rule, Protocol::Any) || std::mem::discriminant(rule) == std::mem::discriminant(pkt)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg_text = std::fs::read_to_string("config.yaml")
        .context("failed to read config.yaml")?;
    let cfg: Config = serde_yaml::from_str(&cfg_text)
        .context("failed to parse config.yaml")?;

    let engine = Arc::new(Engine::from_config(&cfg)?);

    let (tx, rx) = mpsc::channel::<Packet>(CHANNEL_CAPACITY);

    for listener in cfg.listeners.clone() {
        let tx = tx.clone();
        tokio::spawn(async move {
            if let Err(e) = run_listener(listener, tx).await {
                error!("listener exited with error: {e:#}");
            }
        });
    }

    drop(tx);

    run_forwarder(rx, engine).await
}

async fn run_listener(listener: ListenerConfig, tx: mpsc::Sender<Packet>) -> Result<()> {
    let socket = UdpSocket::bind(listener.bind)
        .await
        .with_context(|| format!("bind failed on {}", listener.bind))?;

    info!("listening on {}", listener.bind);

    loop {
        let mut buf = vec![0u8; MAX_PACKET_SIZE];
        let (len, src) = socket.recv_from(&mut buf).await?;
        buf.truncate(len);

        let pkt = Packet {
            meta: PacketMeta {
                src,
                local_dst: listener.bind,
                len,
                protocol: Protocol::Udp,
                received_at: Instant::now(),
            },
            buf,
        };

        if let Err(_e) = tx.try_send(pkt) {
            warn!("packet dropped: ingress queue full");
        }
    }
}

async fn run_forwarder(mut rx: mpsc::Receiver<Packet>, engine: Arc<Engine>) -> Result<()> {
    use std::collections::HashMap;
    let mut sockets: HashMap<SocketAddr, UdpSocket> = HashMap::new();

    while let Some(pkt) = rx.recv().await {
        match engine.classify(&pkt.meta) {
            Decision::Drop(reason) => {
                debug!(
                    src = %pkt.meta.src,
                    dst = %pkt.meta.local_dst,
                    len = pkt.meta.len,
                    reason = reason,
                    "packet dropped"
                );
            }
            Decision::Forward(target) => {
                let sock = if let Some(sock) = sockets.get(&target) {
                    sock
                } else {
                    let bind_addr: SocketAddr = if target.is_ipv4() {
                        "0.0.0.0:0".parse().unwrap()
                    } else {
                        "[::]:0".parse().unwrap()
                    };
                    let sock = UdpSocket::bind(bind_addr).await?;
                    sockets.insert(target, sock);
                    sockets.get(&target).unwrap()
                };

                let start = Instant::now();
                if let Err(e) = sock.send_to(&pkt.buf, target).await {
                    warn!(target = %target, error = %e, "forward failed");
                    continue;
                }

                let elapsed = start.elapsed();
                debug!(
                    src = %pkt.meta.src,
                    target = %target,
                    len = pkt.meta.len,
                    queue_to_send_us = pkt.meta.received_at.elapsed().as_micros(),
                    send_us = elapsed.as_micros(),
                    "packet forwarded"
                );
            }
        }
    }

    Ok(())
}
