use std::net::{IpAddr, Ipv4Addr};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Protocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketMeta {
    pub src_ip: Option<IpAddr>,
    pub dst_ip: Option<IpAddr>,
    pub protocol: Option<L4Protocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub frame_len: usize,
}

impl PacketMeta {
    pub fn empty(frame_len: usize) -> Self {
        Self {
            src_ip: None,
            dst_ip: None,
            protocol: None,
            src_port: None,
            dst_port: None,
            frame_len,
        }
    }
}

pub fn parse_packet(frame: &[u8]) -> PacketMeta {
    let mut meta = PacketMeta::empty(frame.len());

    if frame.len() < 14 {
        return meta;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return meta;
    }

    if frame.len() < 34 {
        return meta;
    }

    let ip_start = 14;
    let version_ihl = frame[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || frame.len() < ip_start + ihl {
        return meta;
    }

    let proto = frame[ip_start + 9];
    let src = Ipv4Addr::new(
        frame[ip_start + 12],
        frame[ip_start + 13],
        frame[ip_start + 14],
        frame[ip_start + 15],
    );
    let dst = Ipv4Addr::new(
        frame[ip_start + 16],
        frame[ip_start + 17],
        frame[ip_start + 18],
        frame[ip_start + 19],
    );

    meta.src_ip = Some(IpAddr::V4(src));
    meta.dst_ip = Some(IpAddr::V4(dst));
    meta.protocol = Some(match proto {
        6 => L4Protocol::Tcp,
        17 => L4Protocol::Udp,
        1 => L4Protocol::Icmp,
        x => L4Protocol::Other(x),
    });

    let l4_start = ip_start + ihl;
    if frame.len() >= l4_start + 4 {
        match meta.protocol {
            Some(L4Protocol::Tcp) | Some(L4Protocol::Udp) => {
                meta.src_port = Some(u16::from_be_bytes([frame[l4_start], frame[l4_start + 1]]));
                meta.dst_port = Some(u16::from_be_bytes([frame[l4_start + 2], frame[l4_start + 3]]));
            }
            _ => {}
        }
    }

    meta
}
