use crate::config::{Action, RuleConfig};
use crate::packet::{L4Protocol, PacketMeta};
use std::net::IpAddr;

#[derive(Debug, Clone)]
pub struct Rule {
    pub action: Action,
    pub src_cidr: Option<ipnet::IpNet>,
    pub dst_cidr: Option<ipnet::IpNet>,
    pub protocol: Option<L4Protocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

impl From<RuleConfig> for Rule {
    fn from(r: RuleConfig) -> Self {
        let protocol = r.protocol.as_deref().map(|p| match p {
            "tcp" => L4Protocol::Tcp,
            "udp" => L4Protocol::Udp,
            "icmp" => L4Protocol::Icmp,
            _ => L4Protocol::Other(255),
        });

        Self {
            action: r.action,
            src_cidr: r.src_cidr,
            dst_cidr: r.dst_cidr,
            protocol,
            src_port: r.src_port,
            dst_port: r.dst_port,
        }
    }
}

#[derive(Debug, Clone)]
pub struct FilterEngine {
    rules: Vec<Rule>,
}

impl FilterEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    pub fn decide(&self, meta: &PacketMeta) -> Action {
        for rule in &self.rules {
            if matches_rule(rule, meta) {
                return rule.action;
            }
        }
        Action::Deny
    }
}

fn matches_rule(rule: &Rule, meta: &PacketMeta) -> bool {
    if let Some(net) = &rule.src_cidr {
        match meta.src_ip {
            Some(ip) if net.contains(&ip) => {}
            _ => return false,
        }
    }

    if let Some(net) = &rule.dst_cidr {
        match meta.dst_ip {
            Some(ip) if net.contains(&ip) => {}
            _ => return false,
        }
    }

    if let Some(proto) = rule.protocol {
        match meta.protocol {
            Some(p) if p == proto => {}
            _ => return false,
        }
    }

    if let Some(port) = rule.src_port {
        if meta.src_port != Some(port) {
            return false;
        }
    }

    if let Some(port) = rule.dst_port {
        if meta.dst_port != Some(port) {
            return false;
        }
    }

    true
}
