# src/main.rs

```rust
mod config;
mod filter;
mod packet;
mod stats;
mod xdp;

use anyhow::Context;
use clap::Parser;
use config::{Action, Config};
use filter::{FilterEngine, Rule};
use packet::parse_packet;
use stats::Stats;
use std::sync::Arc;
use std::sync::atomic::Ordering;
use std::thread;
use std::time::Duration;
use xdp::XdpSocket;

#[derive(Parser, Debug)]
struct Args {
    #[arg(short, long)]
    config: String,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();
    let cfg = Config::load(&args.config)?;

    let rules = cfg.rules.into_iter().map(Rule::from).collect::<Vec<_>>();
    let filter = FilterEngine::new(rules);
    let stats = Arc::new(Stats::default());

    let stats_thread = Arc::clone(&stats);
    thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(1));
        let s = stats_thread.snapshot();
        eprintln!(
            "rx_pkts={} rx_bytes={} tx_pkts={} tx_bytes={} denied={} dropped={}",
            s.rx_packets, s.rx_bytes, s.tx_packets, s.tx_bytes, s.denied_packets, s.dropped_packets
        );
    });

    let mut sock = XdpSocket::open(cfg.ingress_ifindex, cfg.egress_ifindex, cfg.queue_id)
        .context("failed to open XDP socket")?;

    loop {
        let batch = sock.recv_batch(64).context("recv_batch failed")?;
        if batch.is_empty() {
            std::hint::spin_loop();
            continue;
        }

        for pkt in batch {
            stats.rx_packets.fetch_add(1, Ordering::Relaxed);
            stats.rx_bytes.fetch_add(pkt.data.len() as u64, Ordering::Relaxed);

            let meta = parse_packet(&pkt.data);
            match filter.decide(&meta) {
                Action::Allow => {
                    if sock.send(&pkt.data).is_ok() {
                        stats.tx_packets.fetch_add(1, Ordering::Relaxed);
                        stats.tx_bytes.fetch_add(pkt.data.len() as u64, Ordering::Relaxed);
                    } else {
                        stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    }
                }
                Action::Deny => {
                    stats.denied_packets.fetch_add(1, Ordering::Relaxed);
                }
            }
        }
    }
}
```

