## 1. eBPF/XDP program

This example:
- parses Ethernet + IPv4
- checks destination IPv4 against a policy map
- drops or passes
- counts packets

```c
// xdp_filter.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 dst addr in network byte order
    __type(value, __u8);  // 1 = allow, 0 = drop
} policy_map SEC(".maps");

struct stats {
    __u64 passed;
    __u64 dropped;
};

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct stats);
} stats_map SEC(".maps");

static __always_inline void incr_passed() {
    __u32 key = 0;
    struct stats *s = bpf_map_lookup_elem(&stats_map, &key);
    if (s) {
        __sync_fetch_and_add(&s->passed, 1);
    }
}

static __always_inline void incr_dropped() {
    __u32 key = 0;
    struct stats *s = bpf_map_lookup_elem(&stats_map, &key);
    if (s) {
        __sync_fetch_and_add(&s->dropped, 1);
    }
}

SEC("xdp")
int xdp_packet_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    __u32 dst = ip->daddr;
    __u8 *decision = bpf_map_lookup_elem(&policy_map, &dst);

    if (decision && *decision == 0) {
        incr_dropped();
        return XDP_DROP;
    }

    incr_passed();
    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
```

