```rust
use anyhow::{Context, Result};
use aya::maps::{HashMap as AyaHashMap, PerCpuArray};
use aya::programs::{Xdp, XdpFlags};
use aya::Ebpf;
use axum::{extract::State, routing::{get, post}, Json, Router};
use serde::{Deserialize, Serialize};
use std::{net::Ipv4Addr, sync::Arc};
use tokio::sync::Mutex;

#[derive(Clone)]
struct AppState {
    bpf: Arc<Mutex<Ebpf>>,
}

#[derive(Deserialize)]
struct PolicyRequest {
    ip: String,
    allow: bool,
}

#[derive(Serialize)]
struct StatsResponse {
    passed: u64,
    dropped: u64,
}

#[tokio::main]
async fn main() -> Result<()> {
    let iface = std::env::args().nth(1).unwrap_or_else(|| "eth0".to_string());

    let mut bpf = Ebpf::load_file("xdp_filter.o").context("loading eBPF object")?;

    let program: &mut Xdp = bpf
        .program_mut("xdp_packet_filter")
        .context("finding XDP program")?
        .try_into()?;

    program.load()?;
    program.attach(&iface, XdpFlags::default())
        .context("attaching XDP program")?;

    let state = AppState {
        bpf: Arc::new(Mutex::new(bpf)),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/policy", post(set_policy))
        .route("/stats", get(get_stats))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").await?;
    axum::serve(listener, app).await?;

    Ok(())
}

async fn health() -> &'static str {
    "ok"
}

async fn set_policy(
    State(state): State<AppState>,
    Json(req): Json<PolicyRequest>,
) -> Result<Json<&'static str>, axum::http::StatusCode> {
    let ip: Ipv4Addr = req.ip.parse().map_err(|_| axum::http::StatusCode::BAD_REQUEST)?;
    let key = u32::from(ip).to_be();
    let value: u8 = if req.allow { 1 } else { 0 };

    let mut bpf = state.bpf.lock().await;
    let mut policy: AyaHashMap<_, u32, u8> =
        AyaHashMap::try_from(bpf.map_mut("policy_map").map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?)
            .map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?;

    policy.insert(key, value, 0)
        .map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json("ok"))
}

async fn get_stats(
    State(state): State<AppState>,
) -> Result<Json<StatsResponse>, axum::http::StatusCode> {
    #[repr(C)]
    #[derive(Clone, Copy)]
    struct Stats {
        passed: u64,
        dropped: u64,
    }

    let mut bpf = state.bpf.lock().await;
    let stats_map: PerCpuArray<_, Stats> =
        PerCpuArray::try_from(bpf.map_mut("stats_map").map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?)
            .map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?;

    let values = stats_map.get(&0, 0)
        .map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?;

    let mut passed = 0u64;
    let mut dropped = 0u64;

    for s in values.iter() {
        passed += s.passed;
        dropped += s.dropped;
    }

    Ok(Json(StatsResponse { passed, dropped }))
}
```

