```c
// bpf/xdp_filter.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#define ETH_P_IP 0x0800
#define IPPROTO_TCP 6
#define IPPROTO_UDP 17
#define ACTION_PASS 0
#define ACTION_DROP 1

struct ethhdr {
    unsigned char h_dest[6];
    unsigned char h_source[6];
    __be16 h_proto;
};

struct iphdr {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    __u8 ihl:4,
         version:4;
#else
    __u8 version:4,
         ihl:4;
#endif
    __u8 tos;
    __be16 tot_len;
    __be16 id;
    __be16 frag_off;
    __u8 ttl;
    __u8 protocol;
    __be16 check;
    __be32 saddr;
    __be32 daddr;
};

struct tcphdr {
    __be16 source;
    __be16 dest;
    __be32 seq;
    __be32 ack_seq;
    __u16 res1doff;
    __u16 window;
    __be16 check;
    __be16 urg_ptr;
};

struct udphdr {
    __be16 source;
    __be16 dest;
    __be16 len;
    __be16 check;
};

struct rule_key {
    __u32 src_ip;    // network byte order
    __u16 dst_port;  // host byte order
    __u8 proto;      // TCP/UDP
    __u8 pad;
};

struct rule_val {
    __u32 action;    // ACTION_PASS / ACTION_DROP
};

struct stats_key {
    __u32 action;
};

struct stats_val {
    __u64 packets;
    __u64 bytes;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, struct rule_key);
    __type(value, struct rule_val);
} rules SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 16);
    __type(key, struct stats_key);
    __type(value, struct stats_val);
} stats SEC(".maps");

static __always_inline void update_stats(__u32 action, __u64 bytes) {
    struct stats_key key = { .action = action };
    struct stats_val *val = bpf_map_lookup_elem(&stats, &key);
    if (!val) {
        struct stats_val init = { .packets = 1, .bytes = bytes };
        bpf_map_update_elem(&stats, &key, &init, BPF_ANY);
        return;
    }
    __sync_fetch_and_add(&val->packets, 1);
    __sync_fetch_and_add(&val->bytes, bytes);
}

SEC("xdp")
int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->ihl < 5)
        return XDP_PASS;

    void *l4 = (void *)ip + ip->ihl * 4;
    if (l4 > data_end)
        return XDP_PASS;

    __u16 dst_port = 0;

    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = l4;
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;
        dst_port = bpf_ntohs(tcp->dest);
    } else if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = l4;
        if ((void *)(udp + 1) > data_end)
            return XDP_PASS;
        dst_port = bpf_ntohs(udp->dest);
    } else {
        update_stats(ACTION_PASS, (__u64)((char *)data_end - (char *)data));
        return XDP_PASS;
    }

    struct rule_key key = {
        .src_ip = ip->saddr,
        .dst_port = dst_port,
        .proto = ip->protocol,
        .pad = 0,
    };

    struct rule_val *rule = bpf_map_lookup_elem(&rules, &key);
    if (rule && rule->action == ACTION_DROP) {
        update_stats(ACTION_DROP, (__u64)((char *)data_end - (char *)data));
        return XDP_DROP;
    }

    update_stats(ACTION_PASS, (__u64)((char *)data_end - (char *)data));
    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
