# 2) Go rule model: `internal/rules/rules.go`

```go
package rules

import (
	"encoding/binary"
	"fmt"
	"net"
)

const (
	ProtoTCP = 6
	ProtoUDP = 17

	ActionPass = 0
	ActionDrop = 1
)

type RuleKey struct {
	SrcIP   uint32
	DstPort uint16
	Proto   uint8
	Pad     uint8
}

type RuleVal struct {
	Action uint32
}

func IPv4ToU32(ipStr string) (uint32, error) {
	ip := net.ParseIP(ipStr)
	if ip == nil {
		return 0, fmt.Errorf("invalid ip: %s", ipStr)
	}
	ip = ip.To4()
	if ip == nil {
		return 0, fmt.Errorf("not an ipv4 address: %s", ipStr)
	}
	return binary.BigEndian.Uint32(ip), nil
}
