# 3) Go daemon: `cmd/ultranetd/main.go`

This:

- loads the XDP program
- attaches it to an interface
- inserts sample rules
- exposes `/metrics` and `/healthz`

This example uses the popular `cilium/ebpf` library.

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
	"github.com/cilium/ebpf/rlimit"

	"ultranet/internal/rules"
)

type StatsKey struct {
	Action uint32
}

type StatsVal struct {
	Packets uint64
	Bytes   uint64
}

func mustEnv(key, fallback string) string {
	v := os.Getenv(key)
	if v == "" {
		return fallback
	}
	return v
}

func main() {
	if err := rlimit.RemoveMemlock(); err != nil {
		log.Fatalf("remove memlock: %v", err)
	}

	iface := mustEnv("ULTRANET_IFACE", "eth0")
	objPath := mustEnv("ULTRANET_BPF_OBJ", "./xdp_filter.o")

	spec, err := ebpf.LoadCollectionSpec(objPath)
	if err != nil {
		log.Fatalf("load spec: %v", err)
	}

	coll, err := ebpf.NewCollection(spec)
	if err != nil {
		log.Fatalf("new collection: %v", err)
	}
	defer coll.Close()

	prog := coll.Programs["xdp_filter"]
	if prog == nil {
		log.Fatal("xdp_filter program not found")
	}

	netIf, err := netInterfaceByName(iface)
	if err != nil {
		log.Fatalf("interface lookup: %v", err)
	}

	lnk, err := link.AttachXDP(link.XDPOptions{
		Program:   prog,
		Interface: netIf.Index,
	})
	if err != nil {
		log.Fatalf("attach xdp: %v", err)
	}
	defer lnk.Close()

	rulesMap := coll.Maps["rules"]
	statsMap := coll.Maps["stats"]
	if rulesMap == nil || statsMap == nil {
		log.Fatal("required maps not found")
	}

	// Sample defensive rule:
	// drop TCP traffic from 192.0.2.10 to dst port 443
	src, err := rules.IPv4ToU32("192.0.2.10")
	if err != nil {
		log.Fatalf("ip parse: %v", err)
	}

	key := rules.RuleKey{
		SrcIP:   src,
		DstPort: 443,
		Proto:   rules.ProtoTCP,
		Pad:     0,
	}
	val := rules.RuleVal{Action: rules.ActionDrop}

	if err := rulesMap.Put(key, val); err != nil {
		log.Fatalf("insert rule: %v", err)
	}

	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok\n"))
	})

	http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
		resp := map[string]StatsVal{}

		for _, action := range []uint32{rules.ActionPass, rules.ActionDrop} {
			k := StatsKey{Action: action}
			var v StatsVal
			if err := statsMap.Lookup(&k, &v); err == nil {
				switch action {
				case rules.ActionPass:
					resp["pass"] = v
				case rules.ActionDrop:
					resp["drop"] = v
				}
			}
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	})

	go func() {
		addr := ":8080"
		log.Printf("control plane listening on %s", addr)
		if err := http.ListenAndServe(addr, nil); err != nil {
			log.Printf("http server exited: %v", err)
		}
	}()

	log.Printf("XDP attached to %s", iface)
	log.Printf("sample rule installed")

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, syscall.SIGINT, syscall.SIGTERM)
	<-sigc

	fmt.Println("shutting down")
}
```

