## `src/main.rs`

```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Packet {
    src: u32,
    dst: u32,
    proto: u8,
    len: usize,
}

#[derive(Clone)]
struct FilterRule {
    drop_src: Option<u32>,
    allow_proto: Option<u8>,
    min_len: usize,
}

impl FilterRule {
    #[inline(always)]
    fn allows(&self, p: &Packet) -> bool {
        if let Some(src) = self.drop_src {
            if p.src == src {
                return false;
            }
        }
        if let Some(proto) = self.allow_proto {
            if p.proto != proto {
                return false;
            }
        }
        p.len >= self.min_len
    }
}

struct Stats {
    received: AtomicU64,
    dropped: AtomicU64,
    forwarded: AtomicU64,
}

impl Stats {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            forwarded: AtomicU64::new(0),
        }
    }
}

#[inline(always)]
fn classify_and_forward(
    pkt: Packet,
    rule: &FilterRule,
    out_a: &Sender<Packet>,
    out_b: &Sender<Packet>,
    stats: &Stats,
) {
    stats.received.fetch_add(1, Ordering::Relaxed);

    if !rule.allows(&pkt) {
        stats.dropped.fetch_add(1, Ordering::Relaxed);
        return;
    }

    let target = if pkt.dst & 1 == 0 { out_a } else { out_b };

    if target.send(pkt).is_ok() {
        stats.forwarded.fetch_add(1, Ordering::Relaxed);
    } else {
        stats.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

fn worker_loop(
    input: Receiver<Packet>,
    out_a: Sender<Packet>,
    out_b: Sender<Packet>,
    rule: FilterRule,
    stats: Arc<Stats>,
) {
    while let Ok(pkt) = input.recv() {
        classify_and_forward(pkt, &rule, &out_a, &out_b, &stats);
    }
}

fn sink_loop(name: &'static str, rx: Receiver<Packet>) {
    let mut count = 0u64;
    while let Ok(_pkt) = rx.recv() {
        count += 1;
        if count % 100_000 == 0 {
            println!("{name}: processed {count}");
        }
    }
}

fn main() {
    let (ingress_tx, ingress_rx) = bounded::<Packet>(65_536);
    let (out_a_tx, out_a_rx) = bounded::<Packet>(65_536);
    let (out_b_tx, out_b_rx) = bounded::<Packet>(65_536);

    let stats = Arc::new(Stats::new());

    let rule = FilterRule {
        drop_src: Some(10),
        allow_proto: Some(17), // e.g. UDP-like
        min_len: 64,
    };

    {
        let stats = Arc::clone(&stats);
        let out_a_tx = out_a_tx.clone();
        let out_b_tx = out_b_tx.clone();
        thread::spawn(move || worker_loop(ingress_rx, out_a_tx, out_b_tx, rule, stats));
    }

    thread::spawn(move || sink_loop("out_a", out_a_rx));
    thread::spawn(move || sink_loop("out_b", out_b_rx));

    let start = Instant::now();

    for i in 0..1_000_000u32 {
        let pkt = Packet {
            src: i % 32,
            dst: i,
            proto: if i % 4 == 0 { 17 } else { 6 },
            len: 60 + (i as usize % 32),
        };

        if ingress_tx.send(pkt).is_err() {
            break;
        }
    }

    drop(ingress_tx);

    thread::sleep(Duration::from_secs(2));

    let elapsed = start.elapsed().as_secs_f64();
    let received = stats.received.load(Ordering::Relaxed);
    let dropped = stats.dropped.load(Ordering::Relaxed);
    let forwarded = stats.forwarded.load(Ordering::Relaxed);

    println!("received  = {}", received);
    println!("forwarded = {}", forwarded);
    println!("dropped   = {}", dropped);
    println!("elapsed   = {:.3}s", elapsed);
    println!("rate      = {:.0} pkt/s", received as f64 / elapsed);
}
```

