## Minimal example in C (Linux, AF_PACKET, inspect + drop/allow decision)

```c
// pkt_filter.c
// Build: gcc -O2 -Wall -o pkt_filter pkt_filter.c
// Run: sudo ./pkt_filter eth0
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <net/if.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

static int ifindex_from_name(int fd, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);
    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <iface>\n", argv[0]);
        return 1;
    }

    const char *iface = argv[1];
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    int ifindex = ifindex_from_name(fd, iface);
    if (ifindex < 0) {
        perror("ifindex");
        close(fd);
        return 1;
    }

    struct sockaddr_ll sll = {0};
    sll.sll_family   = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex  = ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return 1;
    }

    unsigned char buf[2048];
    for (;;) {
        ssize_t n = recvfrom(fd, buf, sizeof(buf), 0, NULL, NULL);
        if (n < (ssize_t)sizeof(struct ethhdr)) continue;

        struct ethhdr *eth = (struct ethhdr *)buf;
        if (ntohs(eth->h_proto) != ETH_P_IP) continue;
        if (n < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) continue;

        struct iphdr *ip = (struct iphdr *)(buf + sizeof(struct ethhdr));
        struct in_addr saddr = { .s_addr = ip->saddr };
        struct in_addr daddr = { .s_addr = ip->daddr };

        // Example rule: "drop" packets destined to 10.0.0.1, allow others.
        // This example only logs the decision; it does not reinject or block in-kernel.
        int drop = (ntohl(ip->daddr) == 0x0A000001u);

        printf("%s src=%s dst=%s proto=%u len=%zd\n",
               drop ? "DROP" : "ALLOW",
               inet_ntoa(saddr),
               inet_ntoa(daddr),
               ip->protocol,
               n);
        fflush(stdout);
    }

    close(fd);
    return 0;
}
```

