package main

import (
	"log"
	"net"
	"os"
	"os/signal"
	"syscall"
	"time"
)

type Config struct {
	ListenAddr  string
	ForwardAddr string
	AllowIPs    map[string]struct{}
}

func main() {
	cfg := Config{
		ListenAddr:  ":9000",
		ForwardAddr: "127.0.0.1:9001",
		AllowIPs: map[string]struct{}{
			"127.0.0.1": {},
		},
	}

	listenAddr, err := net.ResolveUDPAddr("udp", cfg.ListenAddr)
	if err != nil {
		log.Fatalf("resolve listen addr: %v", err)
	}

	forwardAddr, err := net.ResolveUDPAddr("udp", cfg.ForwardAddr)
	if err != nil {
		log.Fatalf("resolve forward addr: %v", err)
	}

	inConn, err := net.ListenUDP("udp", listenAddr)
	if err != nil {
		log.Fatalf("listen udp: %v", err)
	}
	defer inConn.Close()

	outConn, err := net.DialUDP("udp", nil, forwardAddr)
	if err != nil {
		log.Fatalf("dial forward udp: %v", err)
	}
	defer outConn.Close()

	log.Printf("listening on %s, forwarding to %s", cfg.ListenAddr, cfg.ForwardAddr)

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-stop
		log.Println("shutting down")
		inConn.Close()
		outConn.Close()
		os.Exit(0)
	}()

	buf := make([]byte, 2048)

	for {
		_ = inConn.SetReadDeadline(time.Now().Add(2 * time.Second))
		n, src, err := inConn.ReadFromUDP(buf)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				continue
			}
			log.Printf("read error: %v", err)
			continue
		}

		if !allowed(src, cfg.AllowIPs) {
			log.Printf("drop packet from %s", src.IP.String())
			continue
		}

		payload := buf[:n]

		// Example packet-level filter:
		// drop empty packets
		if len(payload) == 0 {
			continue
		}

		_, err = outConn.Write(payload)
		if err != nil {
			log.Printf("forward error: %v", err)
			continue
		}

		log.Printf("forwarded %d bytes from %s to %s", n, src.String(), cfg.ForwardAddr)
	}
}

func allowed(src *net.UDPAddr, allow map[string]struct{}) bool {
	_, ok := allow[src.IP.String()]
	return ok
}
