```rust
use std::io;
use std::net::{SocketAddr, UdpSocket};
use std::time::Duration;

fn allowed_packet(buf: &[u8], src: SocketAddr) -> bool {
    // Minimal example policy:
    // - drop empty packets
    // - drop packets from odd source ports
    // - allow everything else
    !buf.is_empty() && src.port() % 2 == 0
}

fn main() -> io::Result<()> {
    let listen_addr = "0.0.0.0:9000";
    let forward_addr: SocketAddr = "127.0.0.1:9001".parse().unwrap();

    let rx = UdpSocket::bind(listen_addr)?;
    let tx = UdpSocket::bind("0.0.0.0:0")?;

    rx.set_nonblocking(false)?;
    rx.set_read_timeout(Some(Duration::from_millis(100)))?;

    let mut buf = [0u8; 2048];

    println!("listening on {listen_addr}, forwarding to {forward_addr}");

    loop {
        match rx.recv_from(&mut buf) {
            Ok((n, src)) => {
                let pkt = &buf[..n];
                if allowed_packet(pkt, src) {
                    let _ = tx.send_to(pkt, forward_addr)?;
                }
            }
            Err(e) if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut => {
                continue;
            }
            Err(e) => return Err(e),
        }
    }
}
