## Code

```c
// toy_forwarder.c
// Build: gcc -O2 -Wall -o toy_forwarder toy_forwarder.c
// Run as root in a lab only:
//   sudo ./toy_forwarder eth0 eth1

#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

static volatile sig_atomic_t keep_running = 1;

static void on_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

static int ifindex_from_name(int fd, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, IFNAMSIZ, "%s", ifname);
    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

static int bind_raw_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int ifindex = ifindex_from_name(fd, ifname);
    if (ifindex < 0) {
        perror("SIOCGIFINDEX");
        close(fd);
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family   = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex  = ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    return fd;
}

static bool should_drop(const uint8_t *buf, ssize_t len) {
    if (len < (ssize_t)sizeof(struct ethhdr)) return true;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    uint16_t ethertype = ntohs(eth->h_proto);

    // Example rule: drop ARP, forward everything else.
    if (ethertype == ETH_P_ARP) return true;

    return false;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in-iface> <out-iface>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    int rx_fd = bind_raw_socket(in_if);
    if (rx_fd < 0) return 1;

    int tx_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx_fd < 0) {
        perror("socket tx");
        close(rx_fd);
        return 1;
    }

    int out_ifindex = ifindex_from_name(tx_fd, out_if);
    if (out_ifindex < 0) {
        perror("SIOCGIFINDEX out");
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    uint8_t buf[65536];
    unsigned long long forwarded = 0, dropped = 0;

    while (keep_running) {
        ssize_t n = recvfrom(rx_fd, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        if (should_drop(buf, n)) {
            dropped++;
            continue;
        }

        struct sockaddr_ll dst;
        memset(&dst, 0, sizeof(dst));
        dst.sll_family   = AF_PACKET;
        dst.sll_ifindex  = out_ifindex;
        dst.sll_protocol = htons(ETH_P_ALL);

        ssize_t sent = sendto(tx_fd, buf, n, 0,
                              (struct sockaddr *)&dst, sizeof(dst));
        if (sent < 0) {
            perror("sendto");
            continue;
        }

        forwarded++;
    }

    fprintf(stderr, "forwarded=%llu dropped=%llu\n", forwarded, dropped);
    close(rx_fd);
    close(tx_fd);
    return 0;
}
