## Minimal working example: UDP filter + forwarder in Go

```go
// udp_filter_forwarder.go
package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"sync/atomic"
	"syscall"
	"time"
)

type Config struct {
	ListenAddr  string
	ForwardAddr string
	AllowPrefix string
}

var (
	received uint64
	forwarded uint64
	dropped uint64
)

func allowed(payload []byte, prefix string) bool {
	if prefix == "" {
		return true
	}
	if len(payload) < len(prefix) {
		return false
	}
	return string(payload[:len(prefix)]) == prefix
}

func run(ctx context.Context, cfg Config) error {
	laddr, err := net.ResolveUDPAddr("udp", cfg.ListenAddr)
	if err != nil {
		return fmt.Errorf("resolve listen addr: %w", err)
	}
	raddr, err := net.ResolveUDPAddr("udp", cfg.ForwardAddr)
	if err != nil {
		return fmt.Errorf("resolve forward addr: %w", err)
	}

	inConn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		return fmt.Errorf("listen udp: %w", err)
	}
	defer inConn.Close()

	outConn, err := net.DialUDP("udp", nil, raddr)
	if err != nil {
		return fmt.Errorf("dial udp forward: %w", err)
	}
	defer outConn.Close()

	log.Printf("listening on %s, forwarding to %s, allow-prefix=%q",
		cfg.ListenAddr, cfg.ForwardAddr, cfg.AllowPrefix)

	buf := make([]byte, 64*1024)

	for {
		_ = inConn.SetReadDeadline(time.Now().Add(500 * time.Millisecond))
		n, src, err := inConn.ReadFromUDP(buf)
		select {
		case <-ctx.Done():
			return nil
		default:
		}
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				continue
			}
			return fmt.Errorf("read udp: %w", err)
		}

		atomic.AddUint64(&received, 1)
		payload := buf[:n]

		if !allowed(payload, cfg.AllowPrefix) {
			atomic.AddUint64(&dropped, 1)
			log.Printf("drop from %s len=%d", src, n)
			continue
		}

		_, err = outConn.Write(payload)
		if err != nil {
			log.Printf("forward error from %s: %v", src, err)
			continue
		}
		atomic.AddUint64(&forwarded, 1)
	}
}

func main() {
	cfg := Config{}
	flag.StringVar(&cfg.ListenAddr, "listen", ":9000", "local UDP listen address")
	flag.StringVar(&cfg.ForwardAddr, "forward", "127.0.0.1:9001", "destination UDP address")
	flag.StringVar(&cfg.AllowPrefix, "allow-prefix", "", "only forward packets whose payload starts with this prefix")
	flag.Parse()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sigc
		cancel()
	}()

	go func() {
		t := time.NewTicker(5 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				log.Printf("stats recv=%d fwd=%d drop=%d",
					atomic.LoadUint64(&received),
					atomic.LoadUint64(&forwarded),
					atomic.LoadUint64(&dropped))
			}
		}
	}()

	if err := run(ctx, cfg); err != nil {
		log.Fatal(err)
	}
}
