    uint64_t ipv4;
    uint64_t dropped_udp;
    uint64_t allowed;
} stats_t;

static bool should_drop_ipv4_udp(const uint8_t *buf, ssize_t len) {
    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return false;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP) return false;

    const struct iphdr *ip = (const struct iphdr *)(buf + sizeof(struct ethhdr));
    if (ip->version != 4) return false;

    // Example policy: mark UDP as "dropped" for accounting only
    return ip->protocol == IPPROTO_UDP;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <iface>\n", argv[0]);
        return 1;
    }

    const char *iface = argv[1];
    signal(SIGINT, on_sigint);

    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", iface);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        close(fd);
        return 1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifr.ifr_ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return 1;
    }

    uint8_t buf[2048];
    stats_t st = {0};

    while (keep_running) {
        ssize_t n = recvfrom(fd, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        st.total++;

        if (n >= (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) {
            const struct ethhdr *eth = (const struct ethhdr *)buf;
            if (ntohs(eth->h_proto) == ETH_P_IP) {
                st.ipv4++;
                const struct iphdr *ip = (const struct iphdr *)(buf + sizeof(struct ethhdr));

                char src[INET_ADDRSTRLEN] = {0};
                char dst[INET_ADDRSTRLEN] = {0};
                inet_ntop(AF_INET, &ip->saddr, src, sizeof(src));
                inet_ntop(AF_INET, &ip->daddr, dst, sizeof(dst));

                bool drop = should_drop_ipv4_udp(buf, n);
                if (drop) {
                    st.dropped_udp++;
                    printf("DROP-MARK ipv4 proto=%u %s -> %s len=%zd\n",
                           ip->protocol, src, dst, n);
                } else {
                    st.allowed++;
                    printf("ALLOW ipv4 proto=%u %s -> %s len=%zd\n",
                           ip->protocol, src, dst, n);
                }
            }
        }
    }

    printf("\n--- stats ---\n");
    printf("total=%llu\n", (unsigned long long)st.total);
    printf("ipv4=%llu\n", (unsigned long long)st.ipv4);
    printf("dropped_udp=%llu\n", (unsigned long long)st.dropped_udp);
    printf("allowed=%llu\n", (unsigned long long)st.allowed);

    close(fd);
    return 0;
}
