## A chunk-based parser for maximum throughput

Here is a more advanced version that processes large chunks and only allocates when a line spans chunk boundaries.

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};

#[derive(Debug)]
struct Record<'a> {
    timestamp: u64,
    user_id: u64,
    event_type: &'a str,
    value: i64,
}

fn parse_u64(bytes: &[u8]) -> Option<u64> {
    let mut n = 0u64;
    if bytes.is_empty() {
        return None;
    }
    for &b in bytes {
        if b < b'0' || b > b'9' {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn parse_i64(bytes: &[u8]) -> Option<i64> {
    if bytes.is_empty() {
        return None;
    }
    let (neg, digits) = if bytes[0] == b'-' {
        (true, &bytes[1..])
    } else {
        (false, bytes)
    };
    if digits.is_empty() {
        return None;
    }

    let mut n = 0i64;
    for &b in digits {
        if b < b'0' || b > b'9' {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as i64)?;
    }

    Some(if neg { -n } else { n })
}

fn split4<'a>(line: &'a [u8]) -> Option<(&'a [u8], &'a [u8], &'a [u8], &'a [u8])> {
    let mut idx = [0usize; 3];
    let mut n = 0usize;

    for (i, &b) in line.iter().enumerate() {
        if b == b'|' {
            if n == 3 {
                return None;
            }
            idx[n] = i;
            n += 1;
        }
    }

    if n != 3 {
        return None;
    }

    Some((
        &line[..idx[0]],
        &line[idx[0] + 1..idx[1]],
        &line[idx[1] + 1..idx[2]],
        &line[idx[2] + 1..],
    ))
}

fn parse_line(line: &[u8]) -> Option<Record<'_>> {
    let mut end = line.len();
    if end > 0 && line[end - 1] == b'\n' {
        end -= 1;
    }
    if end > 0 && line[end - 1] == b'\r' {
        end -= 1;
    }

    let line = &line[..end];
    let (a, b, c, d) = split4(line)?;

    Some(Record {
        timestamp: parse_u64(a)?,
        user_id: parse_u64(b)?,
        event_type: std::str::from_utf8(c).ok()?,
        value: parse_i64(d)?,
    })
}

fn parse_stream<R: BufRead, F: FnMut(Record<'_>)>(
    reader: &mut R,
    mut on_record: F,
) -> io::Result<()> {
    let mut carry = Vec::with_capacity(4096);

    loop {
        let buf = reader.fill_buf()?;
        if buf.is_empty() {
            if !carry.is_empty() {
                if let Some(record) = parse_line(&carry) {
                    on_record(record);
                }
            }
            break;
        }

        let mut start = 0usize;

        for i in 0..buf.len() {
            if buf[i] == b'\n' {
                if carry.is_empty() {
                    if let Some(record) = parse_line(&buf[start..=i]) {
                        on_record(record);
                    }
                } else {
                    carry.extend_from_slice(&buf[start..=i]);
                    if let Some(record) = parse_line(&carry) {
                        on_record(record);
                    }
                    carry.clear();
                }
                start = i + 1;
            }
        }

        if start < buf.len() {
            carry.extend_from_slice(&buf[start..]);
        }

        let consumed = buf.len();
        reader.consume(consumed);
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let file = File::open("events.log")?;
    let mut reader = BufReader::with_capacity(4 * 1024 * 1024, file);

    let mut count = 0u64;
    let mut sum = 0i64;

    parse_stream(&mut reader, |rec| {
        count += 1;
        sum += rec.value;
    })?;

    println!("count={}, sum={}", count, sum);
    Ok(())
}
```

