## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// High-throughput streaming line parser.
///
/// Features:
/// - Reads input in large chunks
/// - Reuses a fixed buffer
/// - Avoids per-line allocation when line is fully contained in a chunk
/// - Uses a small carry buffer only for lines spanning chunk boundaries
///
/// This parser emits each record as a byte slice to a callback.
/// The callback can decode UTF-8 only if needed, avoiding unnecessary work.
pub struct StreamingLineParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    carry: Vec<u8>,
    chunk_size: usize,
}

impl<R: Read> StreamingLineParser<R> {
    /// Create a new parser with a configurable chunk size.
    ///
    /// For high throughput, 64 KiB to 1 MiB is often a good range.
    pub fn new(reader: R, chunk_size: usize) -> Self {
        assert!(chunk_size > 0);
        Self {
            reader,
            buf: vec![0; chunk_size],
            carry: Vec::with_capacity(1024),
            chunk_size,
        }
    }

    /// Parse newline-delimited records.
    ///
    /// The callback receives each record *without* the trailing `\n`.
    /// If lines may end with `\r\n`, this strips the trailing `\r`.
    ///
    /// Returns the number of records processed.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<u64>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut total_records = 0u64;

        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0usize;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    let line = &chunk[start..i];

                    if self.carry.is_empty() {
                        let record = trim_cr(line);
                        on_record(record)?;
                    } else {
                        self.carry.extend_from_slice(line);
                        let record = trim_cr(&self.carry);
                        on_record(record)?;
                        self.carry.clear();
                    }

                    total_records += 1;
                    start = i + 1;
                }
            }

            // Remaining partial record at end of chunk
            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }

        // Emit final record if file doesn't end with newline
        if !self.carry.is_empty() {
            let record = trim_cr(&self.carry);
            on_record(record)?;
            total_records += 1;
            self.carry.clear();
        }

        Ok(total_records)
    }

    #[allow(dead_code)]
    pub fn chunk_size(&self) -> usize {
        self.chunk_size
    }
}

#[inline]
fn trim_cr(mut s: &[u8]) -> &[u8] {
    if let Some(&b'\r') = s.last() {
        s = &s[..s.len() - 1];
    }
    s
}

/// Example record processor:
/// parse lines of the form:
///   key,value,timestamp
///
/// This avoids allocating Strings unless needed.
fn process_csv_like_record(record: &[u8]) -> io::Result<()> {
    let mut fields = record.split(|&b| b == b',');

    let key = fields.next().unwrap_or(b"");
    let value = fields.next().unwrap_or(b"");
    let ts = fields.next().unwrap_or(b"");

    // Example: lightweight validation / processing
    // Convert only what you need.
    let _key_str = std::str::from_utf8(key).unwrap_or("<invalid-utf8>");
    let _value_num = parse_u64_ascii(value).unwrap_or(0);
    let _timestamp = parse_u64_ascii(ts).unwrap_or(0);

    // Do something useful here:
    // e.g. aggregate, write to DB batch, route, etc.

    Ok(())
}

/// Fast ASCII u64 parser without allocation.
#[inline]
fn parse_u64_ascii(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }

    let mut n = 0u64;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?;
        n = n.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;

    // BufReader helps reduce syscall overhead.
    // Internal buffering + parser chunking works well for large files.
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamingLineParser::new(reader, 1024 * 1024);

    let count = parser.parse(|record| {
        process_csv_like_record(record)
    })?;

    eprintln!("Processed {} records", count);
    Ok(())
}
