## Example: length-prefixed binary frame parser

If your stream is binary and each message starts with a 4-byte little-endian length:

```rust
use std::io::{self, Read};

pub fn parse_length_prefixed<R: Read, F>(
    mut reader: R,
    chunk_size: usize,
    mut on_frame: F,
) -> io::Result<u64>
where
    F: FnMut(&[u8]) -> io::Result<()>,
{
    let mut read_buf = vec![0u8; chunk_size];
    let mut buffer = Vec::<u8>::with_capacity(chunk_size * 2);
    let mut total = 0u64;

    loop {
        let n = reader.read(&mut read_buf)?;
        if n == 0 {
            break;
        }

        buffer.extend_from_slice(&read_buf[..n]);

        let mut offset = 0usize;

        loop {
            if buffer.len() - offset < 4 {
                break;
            }

            let len_bytes = &buffer[offset..offset + 4];
            let frame_len = u32::from_le_bytes([
                len_bytes[0],
                len_bytes[1],
                len_bytes[2],
                len_bytes[3],
            ]) as usize;

            if buffer.len() - offset < 4 + frame_len {
                break;
            }

            let frame = &buffer[offset + 4..offset + 4 + frame_len];
            on_frame(frame)?;
            total += 1;

            offset += 4 + frame_len;
        }

        if offset > 0 {
            buffer.drain(..offset);
        }
    }

    if !buffer.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "truncated frame at end of stream",
        ));
    }

    Ok(total)
}
```

For even lower overhead in binary protocols, I can rewrite this to avoid `drain(..offset)` by using a ring buffer or sliding window.

