# C++ Implementation

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string_view>
#include <functional>
#include <stdexcept>
#include <cstring>
#include <cstdio>

class StreamingLineParser {
public:
    using RecordHandler = std::function<void(std::string_view)>;

    explicit StreamingLineParser(
        size_t buffer_size = 1 << 20  // 1 MB default
    )
        : buffer_(buffer_size),
          data_start_(0),
          data_end_(0) {}

    void parse(std::istream& input, const RecordHandler& handler) {
        while (true) {
            compact_if_needed();

            // Read more data into the free space at the end of the buffer
            input.read(buffer_.data() + data_end_, buffer_.size() - data_end_);
            std::streamsize bytes_read = input.gcount();

            if (bytes_read < 0) {
                throw std::runtime_error("Read error");
            }

            data_end_ += static_cast<size_t>(bytes_read);

            // Process complete lines in the buffer
            process_buffer(handler);

            if (input.eof()) {
                // Emit any trailing partial line as a final record
                if (data_start_ < data_end_) {
                    handler(std::string_view(buffer_.data() + data_start_,
                                             data_end_ - data_start_));
                    data_start_ = data_end_;
                }
                break;
            }

            if (bytes_read == 0 && !input.eof()) {
                throw std::runtime_error("Input stalled without EOF");
            }

            // If buffer is full and no newline was found, record too large
            if (data_end_ == buffer_.size() && data_start_ == 0) {
                throw std::runtime_error(
                    "Record exceeds buffer capacity; increase buffer size");
            }
        }
    }

private:
    std::vector<char> buffer_;
    size_t data_start_;
    size_t data_end_;

    void compact_if_needed() {
        if (data_start_ == 0) {
            return;
        }

        if (data_start_ == data_end_) {
            data_start_ = 0;
            data_end_ = 0;
            return;
        }

        size_t remaining = data_end_ - data_start_;
        std::memmove(buffer_.data(),
                     buffer_.data() + data_start_,
                     remaining);
        data_start_ = 0;
        data_end_ = remaining;
    }

    void process_buffer(const RecordHandler& handler) {
        size_t scan = data_start_;

        while (scan < data_end_) {
            void* nl_ptr = std::memchr(buffer_.data() + scan, '\n', data_end_ - scan);
            if (!nl_ptr) {
                break;
            }

            size_t nl_index = static_cast<char*>(nl_ptr) - buffer_.data();
            size_t line_len = nl_index - data_start_;

            // Trim optional '\r' for CRLF input
            if (line_len > 0 && buffer_[data_start_ + line_len - 1] == '\r') {
                --line_len;
            }

            handler(std::string_view(buffer_.data() + data_start_, line_len));

            data_start_ = nl_index + 1;
            scan = data_start_;
        }
    }
};
```

