# Higher-throughput variant using POSIX `read()`

If you want lower overhead than `std::istream`, use file descriptors directly.

```cpp
#include <unistd.h>
#include <vector>
#include <string_view>
#include <functional>
#include <stdexcept>
#include <cstring>
#include <cerrno>

class FDStreamingLineParser {
public:
    using RecordHandler = std::function<void(std::string_view)>;

    explicit FDStreamingLineParser(size_t buffer_size = 1 << 20)
        : buffer_(buffer_size), data_start_(0), data_end_(0) {}

    void parse(int fd, const RecordHandler& handler) {
        while (true) {
            compact_if_needed();

            ssize_t n = ::read(fd, buffer_.data() + data_end_, buffer_.size() - data_end_);
            if (n < 0) {
                if (errno == EINTR) continue;
                throw std::runtime_error(std::string("read failed: ") + std::strerror(errno));
            }

            if (n == 0) {
                if (data_start_ < data_end_) {
                    handler(std::string_view(buffer_.data() + data_start_,
                                             data_end_ - data_start_));
                }
                break;
            }

            data_end_ += static_cast<size_t>(n);
            process_buffer(handler);

            if (data_end_ == buffer_.size() && data_start_ == 0) {
                throw std::runtime_error("Record exceeds buffer capacity");
            }
        }
    }

private:
    std::vector<char> buffer_;
    size_t data_start_;
    size_t data_end_;

    void compact_if_needed() {
        if (data_start_ == 0) return;
        if (data_start_ == data_end_) {
            data_start_ = data_end_ = 0;
            return;
        }

        size_t remaining = data_end_ - data_start_;
        std::memmove(buffer_.data(), buffer_.data() + data_start_, remaining);
        data_start_ = 0;
        data_end_ = remaining;
    }

    void process_buffer(const RecordHandler& handler) {
        size_t scan = data_start_;
        while (scan < data_end_) {
            void* p = std::memchr(buffer_.data() + scan, '\n', data_end_ - scan);
            if (!p) break;

            size_t nl = static_cast<char*>(p) - buffer_.data();
            size_t len = nl - data_start_;
            if (len > 0 && buffer_[data_start_ + len - 1] == '\r') {
                --len;
            }

            handler(std::string_view(buffer_.data() + data_start_, len));
            data_start_ = nl + 1;
            scan = data_start_;
        }
    }
};
```

