## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Parsed record borrowing from the input line buffer.
/// This avoids allocating new Strings for each field.
#[derive(Debug)]
struct Record<'a> {
    timestamp: u64,
    user_id: u64,
    event_type: &'a str,
    value: i64,
}

/// Parse a single line in-place.
/// Expected format:
/// timestamp|user_id|event_type|value
#[inline]
fn parse_line(line: &str) -> Option<Record<'_>> {
    let mut parts = line.trim_end_matches('\n').split('|');

    let timestamp = parts.next()?.parse().ok()?;
    let user_id = parts.next()?.parse().ok()?;
    let event_type = parts.next()?;
    let value = parts.next()?.parse().ok()?;

    // Reject malformed lines with extra fields
    if parts.next().is_some() {
        return None;
    }

    Some(Record {
        timestamp,
        user_id,
        event_type,
        value,
    })
}

/// High-throughput streaming parser.
/// Processes records one line at a time with a reusable buffer.
fn parse_stream<P, F>(path: P, mut on_record: F) -> io::Result<()>
where
    P: AsRef<Path>,
    F: FnMut(Record<'_>),
{
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(1024 * 1024, file); // 1 MB buffer
    let mut line = String::with_capacity(1024);

    loop {
        line.clear();
        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 {
            break; // EOF
        }

        if let Some(record) = parse_line(&line) {
            on_record(record);
        } else {
            // In production, consider logging malformed lines or counting errors
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let path = "events.log";

    let mut count: u64 = 0;
    let mut sum: i64 = 0;

    parse_stream(path, |record| {
        count += 1;
        sum += record.value;

        // Example lightweight processing
        // Avoid storing records unless necessary
        if count % 1_000_000 == 0 {
            println!(
                "Processed {} records; latest event_type={}, running_sum={}",
                count, record.event_type, sum
            );
        }
    })?;

    println!("Done. total_records={}, total_value={}", count, sum);
    Ok(())
}
```

---

## Why this is memory-efficient

- `BufReader` reads chunks from disk instead of the whole file.
- `line` is a **single reusable `String` buffer**.
- `Record<'a>` borrows `&str` slices from the line buffer instead of allocating new strings.
- Records are processed immediately via callback, so memory stays nearly constant regardless of file size.

