## Higher-throughput version using raw byte buffers

If you want even lower overhead, avoid `read_line` and `split('|')`, and parse directly from bytes. This reduces UTF-8/string handling overhead.

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};

#[derive(Debug)]
struct ByteRecord<'a> {
    timestamp: u64,
    user_id: u64,
    event_type: &'a [u8],
    value: i64,
}

#[inline]
fn parse_u64(bytes: &[u8]) -> Option<u64> {
    let mut n = 0u64;
    if bytes.is_empty() {
        return None;
    }
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

#[inline]
fn parse_i64(bytes: &[u8]) -> Option<i64> {
    if bytes.is_empty() {
        return None;
    }

    let (neg, digits) = if bytes[0] == b'-' {
        (true, &bytes[1..])
    } else {
        (false, bytes)
    };

    let val = parse_u64(digits)? as i64;
    Some(if neg { -val } else { val })
}

#[inline]
fn parse_line_bytes(line: &[u8]) -> Option<ByteRecord<'_>> {
    let line = if line.last() == Some(&b'\n') {
        &line[..line.len() - 1]
    } else {
        line
    };

    let mut fields = [0usize; 3];
    let mut found = 0;

    for (i, &b) in line.iter().enumerate() {
        if b == b'|' {
            if found < 3 {
                fields[found] = i;
            }
            found += 1;
        }
    }

    if found != 3 {
        return None;
    }

    let f0 = &line[..fields[0]];
    let f1 = &line[fields[0] + 1..fields[1]];
    let f2 = &line[fields[1] + 1..fields[2]];
    let f3 = &line[fields[2] + 1..];

    Some(ByteRecord {
        timestamp: parse_u64(f0)?,
        user_id: parse_u64(f1)?,
        event_type: f2,
        value: parse_i64(f3)?,
    })
}

fn parse_stream_bytes<F>(path: &str, mut on_record: F) -> io::Result<()>
where
    F: FnMut(ByteRecord<'_>),
{
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(1024 * 1024, file);

    loop {
        let buffer = reader.fill_buf()?;
        if buffer.is_empty() {
            break;
        }

        let mut start = 0usize;
        let mut consumed = 0usize;

        for (i, &b) in buffer.iter().enumerate() {
            if b == b'\n' {
                let line = &buffer[start..=i];
                if let Some(record) = parse_line_bytes(line) {
                    on_record(record);
                }
                start = i + 1;
                consumed = start;
            }
        }

        // If no newline found, handle very long lines safely
        if consumed == 0 {
            let mut long_line = Vec::with_capacity(buffer.len() * 2);
            long_line.extend_from_slice(buffer);
            reader.consume(buffer.len());

            loop {
                let next = reader.fill_buf()?;
                if next.is_empty() {
                    if let Some(record) = parse_line_bytes(&long_line) {
                        on_record(record);
                    }
                    return Ok(());
                }

                if let Some(pos) = next.iter().position(|&b| b == b'\n') {
                    long_line.extend_from_slice(&next[..=pos]);
                    if let Some(record) = parse_line_bytes(&long_line) {
                        on_record(record);
                    }
                    reader.consume(pos + 1);
                    break;
                } else {
                    long_line.extend_from_slice(next);
                    let len = next.len();
                    reader.consume(len);
                }
            }
        } else {
            reader.consume(consumed);
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let mut count = 0u64;
    let mut sum = 0i64;

    parse_stream_bytes("events.log", |rec| {
        count += 1;
        sum += rec.value;

        if count % 1_000_000 == 0 {
            println!(
                "Processed {} records; event_type={}; sum={}",
                count,
                String::from_utf8_lossy(rec.event_type),
                sum
            );
        }
    })?;

    println!("Done. total_records={}, total_value={}", count, sum);
    Ok(())
}
```

