### Optimized parser loop
Replace `parse_lines` with:

```rust
pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
where
    F: FnMut(&[u8]) -> io::Result<()>,
{
    loop {
        while self.start < self.end {
            let haystack = &self.buf[self.start..self.end];
            if let Some(pos) = memchr::memchr(b'\n', haystack) {
                let absolute = self.start + pos;
                let mut line = &self.buf[self.start..absolute];
                if let Some(b'\r') = line.last().copied() {
                    line = &line[..line.len() - 1];
                }

                on_record(line)?;
                self.start = absolute + 1;
            } else {
                break;
            }
        }

        if self.eof {
            if self.start < self.end {
                let mut line = &self.buf[self.start..self.end];
                if let Some(b'\r') = line.last().copied() {
                    line = &line[..line.len() - 1];
                }
                on_record(line)?;
                self.start = self.end;
            }
            return Ok(());
        }

        self.refill()?;
    }
}
```

This is usually noticeably faster on large inputs.

