## Example: length-prefixed binary parser

```rust
use std::io::{self, Read};

pub struct FrameParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
}

impl<R: Read> FrameParser<R> {
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        let mut buf = Vec::with_capacity(capacity);
        buf.resize(capacity, 0);
        Self {
            reader,
            buf,
            start: 0,
            end: 0,
            eof: false,
        }
    }

    fn refill(&mut self) -> io::Result<()> {
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        if self.end == self.buf.len() {
            self.buf.resize(self.buf.len().max(1) * 2, 0);
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }
        Ok(())
    }

    pub fn parse_frames<F>(&mut self, mut on_frame: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            let available = self.end - self.start;

            if available >= 4 {
                let header = &self.buf[self.start..self.start + 4];
                let len = u32::from_le_bytes([header[0], header[1], header[2], header[3]]) as usize;

                let total = 4 + len;
                if available >= total {
                    let payload = &self.buf[self.start + 4..self.start + total];
                    on_frame(payload)?;
                    self.start += total;
                    continue;
                }
            }

            if self.eof {
                if self.start != self.end {
                    return Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "truncated frame at end of stream",
                    ));
                }
                return Ok(());
            }

            self.refill()?;
        }
    }
}
```

