```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for gigabyte-scale input.
///
/// Design goals:
/// - Minimal memory overhead
/// - Avoid storing the whole file
/// - Reuse buffers
/// - Process records incrementally
///
/// This example treats input as newline-delimited records.
/// It handles records split across chunk boundaries.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    chunk_size: usize,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable chunk size.
    ///
    /// Typical values:
    /// - 64 KiB
    /// - 256 KiB
    /// - 1 MiB
    ///
    /// Larger chunks may improve throughput but increase transient memory usage.
    pub fn new(reader: R, chunk_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(chunk_size, reader),
            buf: vec![0u8; chunk_size],
            carry: Vec::with_capacity(1024),
            chunk_size,
        }
    }

    /// Parse newline-delimited records and invoke `on_record` for each record.
    ///
    /// `on_record` receives a byte slice for each record without the trailing newline.
    /// The slice is only valid during the callback.
    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            self.process_chunk(chunk, &mut on_record);
        }

        // Flush final partial record if present
        if !self.carry.is_empty() {
            on_record(&self.carry);
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F)
    where
        F: FnMut(&[u8]),
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record is fully inside current chunk
                    let mut record = &chunk[start..i];
                    if record.last() == Some(&b'\r') {
                        record = &record[..record.len() - 1];
                    }
                    on_record(record);
                } else {
                    // Record spans previous chunk(s)
                    self.carry.extend_from_slice(&chunk[start..i]);
                    if self.carry.last() == Some(&b'\r') {
                        self.carry.pop();
                    }
                    on_record(&self.carry);
                    self.carry.clear();
                }
                start = i + 1;
            }
        }

        // Save remainder for next chunk
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }
    }

    #[allow(dead_code)]
    pub fn chunk_size(&self) -> usize {
        self.chunk_size
    }
}

/// Example record processor:
/// Counts lines and bytes without retaining records.
#[derive(Default, Debug)]
struct Stats {
    records: u64,
    bytes: u64,
}

impl Stats {
    fn process(&mut self, record: &[u8]) {
        self.records += 1;
        self.bytes += record.len() as u64;
    }
}

/// Parse a file using the streaming parser.
pub fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<Stats> {
    let file = File::open(path)?;
    let mut parser = StreamingParser::new(file, 1024 * 1024); // 1 MiB chunk
    let mut stats = Stats::default();

    parser.parse_lines(|record| {
        stats.process(record);
    })?;

    Ok(stats)
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let stats = parse_file(path)?;
    println!("records={}, bytes={}", stats.records, stats.bytes);
    Ok(())
}
```

