use std::io::{self, BufReader, Read};

pub struct DelimitedParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    delimiter: u8,
}

impl<R: Read> DelimitedParser<R> {
    pub fn new(reader: R, chunk_size: usize, delimiter: u8) -> Self {
        Self {
            reader: BufReader::with_capacity(chunk_size, reader),
            buf: vec![0; chunk_size],
            carry: Vec::with_capacity(1024),
            delimiter,
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0;

            for i in 0..chunk.len() {
                if chunk[i] == self.delimiter {
                    if self.carry.is_empty() {
                        on_record(&chunk[start..i]);
                    } else {
                        self.carry.extend_from_slice(&chunk[start..i]);
                        on_record(&self.carry);
                        self.carry.clear();
                    }
                    start = i + 1;
                }
            }

            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }

        if !self.carry.is_empty() {
            on_record(&self.carry);
            self.carry.clear();
        }

        Ok(())
    }
}
