## Even lower-overhead version using `fill_buf`

This version can reduce some read-layer overhead by borrowing directly from the internal buffer.

```rust
use std::io::{self, BufRead, BufReader, Read};

pub struct FillBufParser<R: Read> {
    reader: BufReader<R>,
    carry: Vec<u8>,
}

impl<R: Read> FillBufParser<R> {
    pub fn new(reader: R, capacity: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(capacity, reader),
            carry: Vec::with_capacity(1024),
        }
    }

    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            let available = self.reader.fill_buf()?;
            if available.is_empty() {
                break;
            }

            let mut consumed = 0;
            let mut start = 0;

            for i in 0..available.len() {
                if available[i] == b'\n' {
                    if self.carry.is_empty() {
                        let mut record = &available[start..i];
                        if record.last() == Some(&b'\r') {
                            record = &record[..record.len() - 1];
                        }
                        on_record(record);
                    } else {
                        self.carry.extend_from_slice(&available[start..i]);
                        if self.carry.last() == Some(&b'\r') {
                            self.carry.pop();
                        }
                        on_record(&self.carry);
                        self.carry.clear();
                    }
                    consumed = i + 1;
                    start = i + 1;
                }
            }

            if start < available.len() {
                self.carry.extend_from_slice(&available[start..]);
                consumed = available.len();
            }

            self.reader.consume(consumed);
        }

        if !self.carry.is_empty() {
            on_record(&self.carry);
            self.carry.clear();
        }

        Ok(())
    }
}
```

