```rust
use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Parsed record borrowed from the input buffer.
/// No field allocations: fields are slices into the current line buffer.
#[derive(Debug)]
struct Record<'a> {
    timestamp: &'a str,
    user_id: &'a str,
    event_type: &'a str,
    value: i64,
}

/// Fast parser for a comma-delimited line:
/// timestamp,user_id,event_type,value
///
/// Returns None if malformed.
fn parse_line(line: &str) -> Option<Record<'_>> {
    let line = line.trim_end_matches(&['\n', '\r'][..]);

    let mut parts = line.splitn(4, ',');

    let timestamp = parts.next()?;
    let user_id = parts.next()?;
    let event_type = parts.next()?;
    let value_str = parts.next()?;

    let value = value_str.parse::<i64>().ok()?;

    Some(Record {
        timestamp,
        user_id,
        event_type,
        value,
    })
}

/// Example high-throughput processing:
/// - count records
/// - sum values
/// - count malformed lines
fn process_stream<R: BufRead>(reader: R) -> io::Result<()> {
    let mut line = String::with_capacity(1024);
    let mut reader = reader;

    let mut total_records: u64 = 0;
    let mut malformed_records: u64 = 0;
    let mut value_sum: i128 = 0;

    loop {
        line.clear();

        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 {
            break;
        }

        match parse_line(&line) {
            Some(record) => {
                total_records += 1;
                value_sum += record.value as i128;

                // Example: do something with the parsed fields.
                // Avoid printing in hot path for throughput.
                let _ = (record.timestamp, record.user_id, record.event_type);
            }
            None => {
                malformed_records += 1;
            }
        }
    }

    println!("total_records={}", total_records);
    println!("malformed_records={}", malformed_records);
    println!("value_sum={}", value_sum);

    Ok(())
}

fn open_reader<P: AsRef<Path>>(path: P) -> io::Result<BufReader<File>> {
    let file = File::open(path)?;
    // Large buffer reduces syscalls for high-throughput workloads.
    Ok(BufReader::with_capacity(1024 * 1024, file))
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 {
        let reader = open_reader(&args[1])?;
        process_stream(reader)
    } else {
        let stdin = io::stdin();
        let reader = stdin.lock();
        process_stream(reader)
    }
}
```

