## Faster Byte-Oriented Version

This version avoids `String` and parses raw bytes.

```rust
use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

#[derive(Debug)]
struct Record<'a> {
    timestamp: &'a [u8],
    user_id: &'a [u8],
    event_type: &'a [u8],
    value: i64,
}

fn parse_i64(bytes: &[u8]) -> Option<i64> {
    if bytes.is_empty() {
        return None;
    }

    let mut i = 0;
    let mut negative = false;

    if bytes[0] == b'-' {
        negative = true;
        i = 1;
        if i == bytes.len() {
            return None;
        }
    }

    let mut value: i64 = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        value = value.checked_mul(10)?;
        value = value.checked_add((b - b'0') as i64)?;
        i += 1;
    }

    Some(if negative { -value } else { value })
}

fn parse_line_bytes(line: &[u8]) -> Option<Record<'_>> {
    let line = if line.ends_with(b"\n") {
        &line[..line.len() - 1]
    } else {
        line
    };
    let line = if line.ends_with(b"\r") {
        &line[..line.len() - 1]
    } else {
        line
    };

    let mut commas = [usize::MAX; 3];
    let mut found = 0;

    for (i, &b) in line.iter().enumerate() {
        if b == b',' {
            if found < 3 {
                commas[found] = i;
                found += 1;
            } else {
                break;
            }
        }
    }

    if found != 3 {
        return None;
    }

    let c0 = commas[0];
    let c1 = commas[1];
    let c2 = commas[2];

    let timestamp = &line[..c0];
    let user_id = &line[c0 + 1..c1];
    let event_type = &line[c1 + 1..c2];
    let value_bytes = &line[c2 + 1..];

    let value = parse_i64(value_bytes)?;

    Some(Record {
        timestamp,
        user_id,
        event_type,
        value,
    })
}

fn process_stream<R: BufRead>(mut reader: R) -> io::Result<()> {
    let mut buf = Vec::with_capacity(1024);
    let mut total_records: u64 = 0;
    let mut malformed_records: u64 = 0;
    let mut value_sum: i128 = 0;

    loop {
        buf.clear();
        let bytes_read = reader.read_until(b'\n', &mut buf)?;
        if bytes_read == 0 {
            break;
        }

        match parse_line_bytes(&buf) {
            Some(record) => {
                total_records += 1;
                value_sum += record.value as i128;
                let _ = (record.timestamp, record.user_id, record.event_type);
            }
            None => malformed_records += 1,
        }
    }

    println!("total_records={}", total_records);
    println!("malformed_records={}", malformed_records);
    println!("value_sum={}", value_sum);

    Ok(())
}

fn open_reader<P: AsRef<Path>>(path: P) -> io::Result<BufReader<File>> {
    let file = File::open(path)?;
    Ok(BufReader::with_capacity(1024 * 1024, file))
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 {
        let reader = open_reader(&args[1])?;
        process_stream(reader)
    } else {
        let stdin = io::stdin();
        let reader = stdin.lock();
        process_stream(reader)
    }
}
