```rust
use std::fs::File;
use std::io::{self, BufReader, Read};

/// High-throughput streaming line parser.
///
/// Features:
/// - Reuses a fixed-size buffer
/// - Avoids loading the full file into memory
/// - Handles lines spanning multiple buffer fills
/// - Calls a user-provided handler for each parsed record
///
/// This parser emits records without the trailing '\n'.
pub struct StreamingLineParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    partial: Vec<u8>,
}

impl<R: Read> StreamingLineParser<R> {
    /// Create a new parser with a specified buffer size.
    ///
    /// For high throughput, 64 KiB to a few MiB is often reasonable.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader,
            buf: vec![0; buffer_size],
            start: 0,
            end: 0,
            partial: Vec::new(),
        }
    }

    /// Parse the stream and invoke `on_record` for each complete line.
    ///
    /// The callback receives a byte slice for each record.
    /// If you need UTF-8 text, convert in the callback.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            if self.start == self.end {
                let n = self.reader.read(&mut self.buf)?;
                if n == 0 {
                    break;
                }
                self.start = 0;
                self.end = n;
            }

            let chunk = &self.buf[self.start..self.end];
            let mut line_start = 0;

            for i in 0..chunk.len() {
                if chunk[i] == b'\n' {
                    let line = &chunk[line_start..i];

                    if self.partial.is_empty() {
                        on_record(trim_cr(line));
                    } else {
                        self.partial.extend_from_slice(line);
                        on_record(trim_cr(&self.partial));
                        self.partial.clear();
                    }

                    line_start = i + 1;
                }
            }

            if line_start < chunk.len() {
                self.partial.extend_from_slice(&chunk[line_start..]);
            }

            self.start = self.end;
        }

        // Emit final partial line if present and non-empty
        if !self.partial.is_empty() {
            on_record(trim_cr(&self.partial));
            self.partial.clear();
        }

        Ok(())
    }
}

/// Trim a trailing '\r' for CRLF inputs.
fn trim_cr(line: &[u8]) -> &[u8] {
    if let Some(&b'\r') = line.last() {
        &line[..line.len() - 1]
    } else {
        line
    }
}

