## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::str;

const DEFAULT_CHUNK_SIZE: usize = 1024 * 1024; // 1 MiB

#[derive(Debug)]
pub struct Record<'a> {
    pub id: u64,
    pub name: &'a str,
    pub value: f64,
}

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    Utf8(str::Utf8Error),
    InvalidFormat(&'static str),
    InvalidInt(std::num::ParseIntError),
    InvalidFloat(std::num::ParseFloatError),
    RecordTooLarge,
}

impl From<io::Error> for ParseError {
    fn from(e: io::Error) -> Self {
        ParseError::Io(e)
    }
}

impl From<str::Utf8Error> for ParseError {
    fn from(e: str::Utf8Error) -> Self {
        ParseError::Utf8(e)
    }
}

impl From<std::num::ParseIntError> for ParseError {
    fn from(e: std::num::ParseIntError) -> Self {
        ParseError::InvalidInt(e)
    }
}

impl From<std::num::ParseFloatError> for ParseError {
    fn from(e: std::num::ParseFloatError) -> Self {
        ParseError::InvalidFloat(e)
    }
}

pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
    max_record_size: usize,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, chunk_size: usize, max_record_size: usize) -> Self {
        Self {
            reader,
            buf: vec![0; chunk_size],
            start: 0,
            end: 0,
            eof: false,
            max_record_size,
        }
    }

    fn refill(&mut self) -> Result<(), ParseError> {
        if self.eof {
            return Ok(());
        }

        // Move unprocessed bytes to the front
        if self.start > 0 {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        }

        // If buffer is full and no newline found, record too large
        if self.end == self.buf.len() {
            return Err(ParseError::RecordTooLarge);
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    fn next_line(&mut self) -> Result<Option<&[u8]>, ParseError> {
        loop {
            if let Some(pos) = self.buf[self.start..self.end]
                .iter()
                .position(|&b| b == b'\n')
            {
                let line_start = self.start;
                let line_end = self.start + pos;
                self.start = line_end + 1;

                let line = if line_end > line_start && self.buf[line_end - 1] == b'\r' {
                    &self.buf[line_start..line_end - 1]
                } else {
                    &self.buf[line_start..line_end]
                };

                return Ok(Some(line));
            }

            if self.eof {
                if self.start < self.end {
                    let line = &self.buf[self.start..self.end];
                    self.start = self.end;
                    return Ok(Some(line));
                } else {
                    return Ok(None);
                }
            }

            self.refill()?;
        }
    }

    fn parse_record<'a>(&self, line: &'a [u8]) -> Result<Record<'a>, ParseError> {
        let mut fields = line.splitn(3, |&b| b == b',');

        let id_bytes = fields.next().ok_or(ParseError::InvalidFormat("missing id"))?;
        let name_bytes = fields.next().ok_or(ParseError::InvalidFormat("missing name"))?;
        let value_bytes = fields.next().ok_or(ParseError::InvalidFormat("missing value"))?;

        let id = str::from_utf8(id_bytes)?.parse::<u64>()?;
        let name = str::from_utf8(name_bytes)?;
        let value = str::from_utf8(value_bytes)?.parse::<f64>()?;

        Ok(Record { id, name, value })
    }

    pub fn process<F>(&mut self, mut handler: F) -> Result<(), ParseError>
    where
        F: FnMut(Record<'_>) -> Result<(), ParseError>,
    {
        while let Some(line) = self.next_line()? {
            if line.is_empty() {
                continue;
            }
            let record = self.parse_record(line)?;
            handler(record)?;
        }
        Ok(())
    }
}

fn main() -> Result<(), ParseError> {
    let file = File::open("data.txt")?;
    let reader = BufReader::with_capacity(DEFAULT_CHUNK_SIZE, file);

    let mut parser = StreamingParser::new(reader, DEFAULT_CHUNK_SIZE, 8 * 1024 * 1024);

    let mut count: u64 = 0;
    let mut sum: f64 = 0.0;

    parser.process(|record| {
        count += 1;
        sum += record.value;

        // Example processing:
        // println!("{:?}", record);

        Ok(())
    })?;

    println!("Processed {} records, sum={}", count, sum);
    Ok(())
}
```

