fn parse_u64(bytes: &[u8]) -> Result<u64, ParseError> {
    if bytes.is_empty() {
        return Err(ParseError::InvalidFormat("empty integer"));
    }

    let mut n: u64 = 0;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return Err(ParseError::InvalidFormat("invalid integer"));
