use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reads input in fixed-size chunks
/// - Avoids loading the whole file into memory
/// - Reuses internal buffers
/// - Handles records split across chunk boundaries
/// - Calls a user-provided callback for each parsed record
///
/// This parser assumes records are separated by '\n'.
/// It strips an optional trailing '\r' for CRLF compatibility.
pub struct StreamingParser<const CHUNK_SIZE: usize = 1024 * 1024> {
    /// Stores partial record data that spans chunk boundaries.
    carry: Vec<u8>,
}

impl<const CHUNK_SIZE: usize> StreamingParser<CHUNK_SIZE> {
    pub fn new() -> Self {
        Self {
            carry: Vec::with_capacity(1024),
        }
    }

    /// Parse from any Read source.
    ///
    /// `on_record` is called once per record with the record bytes.
    /// The slice passed to `on_record` is only valid during the callback.
    pub fn parse<R, F>(&mut self, mut reader: R, mut on_record: F) -> io::Result<()>
    where
        R: Read,
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut buf = vec![0u8; CHUNK_SIZE];

        loop {
            let n = reader.read(&mut buf)?;
            if n == 0 {
                break;
            }

            self.process_chunk(&buf[..n], &mut on_record)?;
        }

        // Emit final carry if non-empty
        if !self.carry.is_empty() {
            let record = trim_cr(&self.carry);
            on_record(record)?;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record entirely within this chunk
                    let record = trim_cr(&chunk[start..i]);
                    on_record(record)?;
                } else {
                    // Slow path: record spans previous chunk(s)
                    self.carry.extend_from_slice(&chunk[start..i]);
                    let record = trim_cr(&self.carry);
                    on_record(record)?;
                    self.carry.clear();
                }
                start = i + 1;
            }
        }

        // Save trailing partial record
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }
}

fn trim_cr(line: &[u8]) -> &[u8] {
    if let Some(&b'\r') = line.last() {
        &line[..line.len() - 1]
    } else {
        line
    }
}

/// Example record processor:
/// Parse newline-delimited "key:value" records and count them.
pub fn parse_key_value_record(record: &[u8]) -> Option<(&[u8], &[u8])> {
    let pos = record.iter().position(|&b| b == b':')?;
    Some((&record[..pos], &record[pos + 1..]))
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(4 * 1024 * 1024, file);

    let mut parser = StreamingParser::<1024 * 1024>::new();

    let mut total_records: u64 = 0;
    let mut matched_records: u64 = 0;

    parser.parse(reader, |record| {
        total_records += 1;

        if let Some((key, value)) = parse_key_value_record(record) {
            if key == b"user_id" && !value.is_empty() {
                matched_records += 1;
            }
        }

        Ok(())
    })?;

    println!("Total records: {}", total_records);
    println!("Matched records: {}", matched_records);

    Ok(())
}
