## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record view.
/// Fields borrow from the parser's internal line buffer,
/// so they must be consumed before the next `next_record()` call.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a [u8]>,
}

/// High-throughput streaming parser for newline-delimited records.
/// Each record is split by commas.
///
/// Characteristics:
/// - Reads input in large chunks
/// - Reuses buffers
/// - Avoids loading the whole file into memory
/// - Handles lines spanning multiple chunks
pub struct StreamingParser<R: Read> {
    reader: R,
    read_buf: Box<[u8]>,
    buf_start: usize,
    buf_end: usize,

    // Stores the current line if it spans chunks or after extraction.
    line_buf: Vec<u8>,

    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create parser with a configurable chunk size.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            read_buf: vec![0u8; capacity].into_boxed_slice(),
            buf_start: 0,
            buf_end: 0,
            line_buf: Vec::with_capacity(1024),
            eof: false,
        }
    }

    /// Refill internal read buffer.
    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        self.buf_start = 0;
        let n = self.reader.read(&mut self.read_buf)?;
        self.buf_end = n;

        if n == 0 {
            self.eof = true;
        }

        Ok(())
    }

    /// Returns the next full line without trailing '\n' or '\r\n'.
    fn next_line(&mut self) -> io::Result<Option<&[u8]>> {
        self.line_buf.clear();

        loop {
            if self.buf_start == self.buf_end {
                self.refill()?;
                if self.buf_start == self.buf_end {
                    // EOF
                    if self.line_buf.is_empty() {
                        return Ok(None);
                    } else {
                        // Final unterminated line
                        trim_cr(&mut self.line_buf);
                        return Ok(Some(&self.line_buf));
                    }
                }
            }

            let buf = &self.read_buf[self.buf_start..self.buf_end];

            if let Some(pos) = memchr::memchr(b'\n', buf) {
                let line_part = &buf[..pos];
                self.line_buf.extend_from_slice(line_part);
                self.buf_start += pos + 1;
                trim_cr(&mut self.line_buf);
                return Ok(Some(&self.line_buf));
            } else {
                self.line_buf.extend_from_slice(buf);
                self.buf_start = self.buf_end;
            }
        }
    }

    /// Parse next record as comma-separated fields.
    pub fn next_record<'a>(&'a mut self) -> io::Result<Option<Record<'a>>> {
        let line = match self.next_line()? {
            Some(line) => line,
            None => return Ok(None),
        };

        let mut fields = Vec::with_capacity(8);
        let mut start = 0;

        for i in 0..line.len() {
            if line[i] == b',' {
                fields.push(&line[start..i]);
                start = i + 1;
            }
        }
        fields.push(&line[start..]);

        Ok(Some(Record { fields }))
    }
}

fn trim_cr(buf: &mut Vec<u8>) {
    if matches!(buf.last(), Some(b'\r')) {
        buf.pop();
    }
}

/// Example processing function.
/// Replace this with your actual business logic.
fn process_record(record: &Record) {
    // Example: print first 3 fields if present
    let f0 = record.fields.get(0).copied().unwrap_or(b"");
    let f1 = record.fields.get(1).copied().unwrap_or(b"");
    let f2 = record.fields.get(2).copied().unwrap_or(b"");

    println!(
        "field0={}, field1={}, field2={}",
        String::from_utf8_lossy(f0),
        String::from_utf8_lossy(f1),
        String::from_utf8_lossy(f2),
    );
}

fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;

    // BufReader reduces syscall overhead; parser still streams internally.
    let reader = BufReader::with_capacity(1024 * 1024, file);

    // Large parser chunk for throughput; tune based on workload.
    let mut parser = StreamingParser::with_capacity(reader, 1024 * 1024);

    while let Some(record) = parser.next_record()? {
        process_record(&record);
    }

    Ok(())
}
```

