use std::io::{self, Read};

pub struct ReuseRecordParser<R: Read> {
    reader: R,
    read_buf: Box<[u8]>,
    buf_start: usize,
    buf_end: usize,
    line_buf: Vec<u8>,
    field_ranges: Vec<(usize, usize)>,
    eof: bool,
}

impl<R: Read> ReuseRecordParser<R> {
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader,
            read_buf: vec![0; capacity].into_boxed_slice(),
            buf_start: 0,
            buf_end: 0,
            line_buf: Vec::with_capacity(1024),
            field_ranges: Vec::with_capacity(16),
            eof: false,
        }
    }

    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }
        self.buf_start = 0;
        let n = self.reader.read(&mut self.read_buf)?;
        self.buf_end = n;
        if n == 0 {
            self.eof = true;
        }
        Ok(())
    }

    fn next_line(&mut self) -> io::Result<Option<()>> {
        self.line_buf.clear();

        loop {
            if self.buf_start == self.buf_end {
                self.refill()?;
                if self.buf_start == self.buf_end {
                    if self.line_buf.is_empty() {
                        return Ok(None);
                    } else {
                        trim_cr(&mut self.line_buf);
                        return Ok(Some(()));
                    }
                }
            }

            let buf = &self.read_buf[self.buf_start..self.buf_end];
            if let Some(pos) = memchr::memchr(b'\n', buf) {
                self.line_buf.extend_from_slice(&buf[..pos]);
                self.buf_start += pos + 1;
                trim_cr(&mut self.line_buf);
                return Ok(Some(()));
            } else {
                self.line_buf.extend_from_slice(buf);
                self.buf_start = self.buf_end;
            }
        }
    }

    pub fn next_record(&mut self) -> io::Result<Option<()>> {
        if self.next_line()?.is_none() {
            return Ok(None);
        }

        self.field_ranges.clear();
        let mut start = 0;
        for i in 0..self.line_buf.len() {
            if self.line_buf[i] == b',' {
                self.field_ranges.push((start, i));
                start = i + 1;
            }
        }
        self.field_ranges.push((start, self.line_buf.len()));
        Ok(Some(()))
    }

    pub fn field(&self, idx: usize) -> Option<&[u8]> {
        let (s, e) = *self.field_ranges.get(idx)?;
        Some(&self.line_buf[s..e])
    }

    pub fn field_count(&self) -> usize {
        self.field_ranges.len()
    }
}
