## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record represented as slices into an owned scratch buffer.
///
/// For maximum throughput and minimum allocation, this parser reuses internal
/// buffers and only materializes field boundaries. The caller should process
/// records immediately inside the callback.
#[derive(Debug)]
pub struct Record {
    pub fields: Vec<FieldRange>,
    pub raw_len: usize,
}

#[derive(Debug, Clone, Copy)]
pub struct FieldRange {
    pub start: usize,
    pub end: usize,
}

impl Record {
    pub fn field<'a>(&self, raw: &'a [u8], idx: usize) -> &'a [u8] {
        let r = self.fields[idx];
        &raw[r.start..r.end]
    }

    pub fn num_fields(&self) -> usize {
        self.fields.len()
    }
}

/// Streaming parser configuration.
#[derive(Debug, Clone)]
pub struct ParserConfig {
    /// Size of the read buffer used for streaming input.
    pub read_buffer_size: usize,
    /// Maximum allowed record size before failing.
    pub max_record_size: usize,
    /// Field delimiter.
    pub field_delim: u8,
    /// Record delimiter.
    pub record_delim: u8,
}

impl Default for ParserConfig {
    fn default() -> Self {
        Self {
            read_buffer_size: 1024 * 1024, // 1 MiB
            max_record_size: 64 * 1024 * 1024, // 64 MiB
            field_delim: b',',
            record_delim: b'\n',
        }
    }
}

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    RecordTooLarge(usize),
    UnterminatedFinalRecord,
}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::Io(err)
    }
}

/// High-throughput streaming parser.
///
/// Strategy:
/// - Read chunks into a fixed-size buffer.
/// - Scan for record delimiters.
/// - If a full record is found entirely in the current buffer, parse it directly.
/// - If a record spans buffers, append only the needed bytes into a scratch buffer.
/// - Reuse allocations across records.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    config: ParserConfig,

    /// Scratch space for records that span multiple read buffers.
    carry: Vec<u8>,

    /// Reused field range storage.
    field_ranges: Vec<FieldRange>,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, config: ParserConfig) -> Self {
        Self {
            reader: BufReader::with_capacity(config.read_buffer_size, reader),
            config,
            carry: Vec::with_capacity(4096),
            field_ranges: Vec::with_capacity(32),
        }
    }

    /// Parse all records, invoking `on_record` for each.
    ///
    /// The callback receives:
    /// - raw record bytes (without trailing record delimiter)
    /// - parsed field boundaries
    ///
    /// The slices are only valid during the callback.
    pub fn parse_all<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: FnMut(&[u8], &Record) -> Result<(), ParseError>,
    {
        let mut buf = vec![0u8; self.config.read_buffer_size];

        loop {
            let n = self.reader.read(&mut buf)?;
            if n == 0 {
                break;
            }

            let chunk = &buf[..n];
            self.process_chunk(chunk, &mut on_record)?;
        }

        if !self.carry.is_empty() {
            // Optionally treat final unterminated line as a record instead.
            return Err(ParseError::UnterminatedFinalRecord);
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> Result<(), ParseError>
    where
        F: FnMut(&[u8], &Record) -> Result<(), ParseError>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == self.config.record_delim {
                if self.carry.is_empty() {
                    let raw = &chunk[start..i];
                    let record = self.parse_record(raw);
                    on_record(raw, &record)?;
                } else {
                    self.carry.extend_from_slice(&chunk[start..i]);
                    let record = self.parse_record(&self.carry);
                    on_record(&self.carry, &record)?;
                    self.carry.clear();
                }
                start = i + 1;
            }
        }

        if start < chunk.len() {
            let remaining = &chunk[start..];
            if self.carry.len() + remaining.len() > self.config.max_record_size {
                return Err(ParseError::RecordTooLarge(self.carry.len() + remaining.len()));
            }
            self.carry.extend_from_slice(remaining);
        }

        Ok(())
    }

    fn parse_record<'a>(&'a mut self, raw: &[u8]) -> Record {
        self.field_ranges.clear();

        let mut field_start = 0;
        for i in 0..raw.len() {
            if raw[i] == self.config.field_delim {
                self.field_ranges.push(FieldRange {
                    start: field_start,
                    end: i,
                });
                field_start = i + 1;
            }
        }

        self.field_ranges.push(FieldRange {
            start: field_start,
            end: raw.len(),
        });

        Record {
            fields: self.field_ranges.clone(),
            raw_len: raw.len(),
        }
    }
}

/// Convenience function for parsing a file.
pub fn parse_file<P, F>(path: P, config: ParserConfig, on_record: F) -> Result<(), ParseError>
where
    P: AsRef<Path>,
    F: FnMut(&[u8], &Record) -> Result<(), ParseError>,
{
    let file = File::open(path)?;
    let mut parser = StreamingParser::new(file, config);
    parser.parse_all(on_record)
}

fn main() -> Result<(), ParseError> {
    let config = ParserConfig {
        read_buffer_size: 1024 * 1024,
        max_record_size: 16 * 1024 * 1024,
        field_delim: b',',
        record_delim: b'\n',
    };

    parse_file("large_input.csv", config, |raw, record| {
        // Example processing:
        // Avoid allocations by working directly with byte slices.
        if record.num_fields() >= 2 {
            let f0 = record.field(raw, 0);
            let f1 = record.field(raw, 1);

            // Example lightweight processing
            println!(
                "field0={}, field1={}",
                String::from_utf8_lossy(f0),
                String::from_utf8_lossy(f1)
            );
        }
        Ok(())
    })?;

    Ok(())
}
```

