## Lower-overhead callback variant

Here is the more efficient callback signature version:

```rust
pub fn parse_all<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
where
    F: FnMut(&[u8], &[FieldRange]) -> Result<(), ParseError>,
{
    let mut buf = vec![0u8; self.config.read_buffer_size];

    loop {
        let n = self.reader.read(&mut buf)?;
        if n == 0 {
            break;
        }

        let chunk = &buf[..n];
        self.process_chunk_no_clone(chunk, &mut on_record)?;
    }

    if !self.carry.is_empty() {
        return Err(ParseError::UnterminatedFinalRecord);
    }

    Ok(())
}

fn process_chunk_no_clone<F>(&mut self, chunk: &[u8], on_record: &mut F) -> Result<(), ParseError>
where
    F: FnMut(&[u8], &[FieldRange]) -> Result<(), ParseError>,
{
    let mut start = 0;

    for i in 0..chunk.len() {
        if chunk[i] == self.config.record_delim {
            if self.carry.is_empty() {
                let raw = &chunk[start..i];
                self.parse_fields(raw);
                on_record(raw, &self.field_ranges)?;
            } else {
                self.carry.extend_from_slice(&chunk[start..i]);
                let raw = &self.carry;
                self.parse_fields(raw);
                on_record(raw, &self.field_ranges)?;
                self.carry.clear();
            }
            start = i + 1;
        }
    }

    if start < chunk.len() {
        let remaining = &chunk[start..];
        if self.carry.len() + remaining.len() > self.config.max_record_size {
            return Err(ParseError::RecordTooLarge(self.carry.len() + remaining.len()));
        }
        self.carry.extend_from_slice(remaining);
    }

    Ok(())
}

fn parse_fields(&mut self, raw: &[u8]) {
    self.field_ranges.clear();

    let mut field_start = 0;
    for i in 0..raw.len() {
        if raw[i] == self.config.field_delim {
            self.field_ranges.push(FieldRange {
                start: field_start,
                end: i,
            });
            field_start = i + 1;
        }
    }

    self.field_ranges.push(FieldRange {
        start: field_start,
        end: raw.len(),
    });
}
