## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reuse a fixed-size buffer
/// - Avoid loading the whole file into memory
/// - Minimize allocations
/// - Handle records spanning multiple buffer fills
///
/// The parser emits each complete line as a byte slice to a user callback.
/// If a line spans multiple chunks, it is assembled in `carry`.
pub struct StreamParser<R: Read> {
    reader: R,
    buf: Box<[u8]>,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamParser<R> {
    /// Create a parser with a configurable buffer size.
    ///
    /// For high throughput, 64 KiB to several MiB often works well depending
    /// on storage and workload characteristics.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 0);
        Self {
            reader,
            buf: vec![0u8; buffer_size].into_boxed_slice(),
            carry: Vec::with_capacity(1024),
            eof: false,
        }
    }

    /// Parse the input stream and invoke `on_record` for every newline-delimited record.
    ///
    /// The callback receives the record bytes without the trailing '\n'.
    ///
    /// This function avoids allocations for records fully contained within a single chunk.
    /// Only records crossing chunk boundaries are copied into `carry`.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        while !self.eof {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                self.eof = true;
                break;
            }

            let chunk = &self.buf[..n];
            self.process_chunk(chunk, &mut on_record)?;
        }

        // Flush final partial record if present.
        if !self.carry.is_empty() {
            on_record(&self.carry)?;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record is entirely inside current chunk.
                    let mut record = &chunk[start..i];
                    if record.last() == Some(&b'\r') {
                        record = &record[..record.len() - 1];
                    }
                    on_record(record)?;
                } else {
                    // Slow path: record spans multiple chunks.
                    self.carry.extend_from_slice(&chunk[start..i]);
                    if self.carry.last() == Some(&b'\r') {
                        self.carry.pop();
                    }
                    on_record(&self.carry)?;
                    self.carry.clear();
                }
                start = i + 1;
            }
        }

        // Remaining bytes after the last newline belong to the next record.
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }
}

/// Example record processor that counts records and bytes.
#[derive(Default, Debug)]
pub struct Stats {
    pub records: u64,
    pub bytes: u64,
}

impl Stats {
    pub fn process(&mut self, record: &[u8]) {
        self.records += 1;
        self.bytes += record.len() as u64;
    }
}

/// Parse a file using a buffered reader and the streaming parser.
pub fn parse_file<P: AsRef<Path>>(path: P, buffer_size: usize) -> io::Result<Stats> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(buffer_size, file);

    let mut parser = StreamParser::new(reader, buffer_size);
    let mut stats = Stats::default();

    parser.parse(|record| {
        stats.process(record);
        Ok(())
    })?;

    Ok(stats)
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let stats = parse_file(path, 1024 * 1024)?; // 1 MiB buffer
    println!("records: {}", stats.records);
    println!("bytes: {}", stats.bytes);
    Ok(())
}
```

