use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record. For the initial implementation, we treat each line as a record.
/// We store offsets into an owned buffer where possible to reduce allocations,
/// but for simplicity in this initial version we emit owned bytes.
#[derive(Debug, Clone)]
pub struct Record {
    pub data: Vec<u8>,
}

/// Streaming parser configuration.
#[derive(Debug, Clone)]
pub struct ParserConfig {
    /// Size of the read buffer used for streaming from the input.
    pub read_buffer_size: usize,

    /// Maximum allowed size for a single record before returning an error.
    /// Prevents unbounded memory growth for malformed input with missing delimiters.
    pub max_record_size: usize,

    /// Record delimiter. Default is b'\n'.
    pub delimiter: u8,
}

impl Default for ParserConfig {
    fn default() -> Self {
        Self {
            read_buffer_size: 1024 * 1024, // 1 MiB
            max_record_size: 16 * 1024 * 1024, // 16 MiB
            delimiter: b'\n',
        }
    }
}

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    RecordTooLarge { size: usize, max: usize },
}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::Io(err)
    }
}

/// High-throughput streaming parser.
///
/// Internals:
/// - `reader`: source of bytes
/// - `read_buf`: temporary chunk buffer filled from reader
/// - `carry`: partial record spanning chunk boundaries
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    config: ParserConfig,
    read_buf: Vec<u8>,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, config: ParserConfig) -> Self {
        let capacity = config.read_buffer_size;
        Self {
            reader: BufReader::with_capacity(capacity, reader),
            config,
            read_buf: vec![0u8; capacity],
            carry: Vec::with_capacity(1024),
            eof: false,
        }
    }

    /// Push-style API:
    /// Reads and parses records, invoking `on_record` for each one.
    ///
    /// This avoids storing many parsed records in memory at once.
    pub fn parse_all<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: FnMut(Record) -> Result<(), ParseError>,
    {
        while let Some(record) = self.next_record()? {
            on_record(record)?;
        }
        Ok(())
    }

    /// Pull-style API:
    /// Returns the next parsed record, or None on EOF.
    pub fn next_record(&mut self) -> Result<Option<Record>, ParseError> {
        loop {
            // First check whether carry already contains a full record.
            if let Some(pos) = self.carry.iter().position(|&b| b == self.config.delimiter) {
                let mut record = self.carry.drain(..=pos).collect::<Vec<u8>>();
                if let Some(last) = record.last() {
                    if *last == self.config.delimiter {
                        record.pop();
                    }
                }
                return Ok(Some(Record { data: record }));
            }

            if self.eof {
                if self.carry.is_empty() {
                    return Ok(None);
                } else {
                    let tail = std::mem::take(&mut self.carry);
                    return Ok(Some(Record { data: tail }));
                }
            }

            let n = self.reader.read(&mut self.read_buf)?;
            if n == 0 {
                self.eof = true;
                continue;
            }

            self.append_and_check(&self.read_buf[..n])?;
        }
    }

    fn append_and_check(&mut self, bytes: &[u8]) -> Result<(), ParseError> {
        if self.carry.len() + bytes.len() > self.config.max_record_size {
            return Err(ParseError::RecordTooLarge {
                size: self.carry.len() + bytes.len(),
                max: self.config.max_record_size,
            });
        }
        self.carry.extend_from_slice(bytes);
        Ok(())
    }
}

/// A more efficient batch-oriented parser that reduces per-record scanning overhead.
///
/// This parser scans each chunk for delimiters and emits complete records immediately,
/// only using `carry` for records split across boundaries.
pub struct BatchStreamingParser<R: Read> {
    reader: BufReader<R>,
    config: ParserConfig,
    read_buf: Vec<u8>,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> BatchStreamingParser<R> {
    pub fn new(reader: R, config: ParserConfig) -> Self {
        let capacity = config.read_buffer_size;
        Self {
            reader: BufReader::with_capacity(capacity, reader),
            config,
            read_buf: vec![0u8; capacity],
            carry: Vec::with_capacity(1024),
            eof: false,
        }
    }

    /// Preferred high-throughput API.
    /// Processes records in batches from each chunk.
    pub fn parse_all<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: FnMut(Record) -> Result<(), ParseError>,
    {
        while !self.eof {
            let n = self.reader.read(&mut self.read_buf)?;
            if n == 0 {
                self.eof = true;
                break;
            }

            self.process_chunk(&self.read_buf[..n], &mut on_record)?;
        }

        if !self.carry.is_empty() {
            let tail = std::mem::take(&mut self.carry);
            on_record(Record { data: tail })?;
        }

        Ok(())
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> Result<(), ParseError>
    where
        F: FnMut(Record) -> Result<(), ParseError>,
    {
        let delim = self.config.delimiter;
        let mut start = 0usize;

        for i in 0..chunk.len() {
            if chunk[i] == delim {
                if self.carry.is_empty() {
                    // Fast path: record fully inside this chunk.
                    let record = chunk[start..i].to_vec();
                    on_record(Record { data: record })?;
                } else {
                    // Slow path: record spans previous chunk(s).
                    let needed = i - start;
                    if self.carry.len() + needed > self.config.max_record_size {
                        return Err(ParseError::RecordTooLarge {
                            size: self.carry.len() + needed,
                            max: self.config.max_record_size,
                        });
                    }
                    self.carry.extend_from_slice(&chunk[start..i]);
                    let record = std::mem::take(&mut self.carry);
                    on_record(Record { data: record })?;
                }
                start = i + 1;
            }
        }

        // Remaining partial record after last delimiter.
        if start < chunk.len() {
            let rem = &chunk[start..];
            if self.carry.len() + rem.len() > self.config.max_record_size {
                return Err(ParseError::RecordTooLarge {
                    size: self.carry.len() + rem.len(),
                    max: self.config.max_record_size,
                });
            }
            self.carry.extend_from_slice(rem);
        }

        Ok(())
    }
}

/// Example consumer that parses a file and counts records/bytes.
pub fn parse_file<P: AsRef<Path>>(path: P) -> Result<(u64, u64), ParseError> {
    let file = File::open(path)?;
    let config = ParserConfig::default();
    let mut parser = BatchStreamingParser::new(file, config);

    let mut record_count = 0u64;
    let mut byte_count = 0u64;

    parser.parse_all(|record| {
        record_count += 1;
        byte_count += record.data.len() as u64;

        // Example: do lightweight processing here.
        // Avoid converting to String unless required.
        // let s = std::str::from_utf8(&record.data).ok();

        Ok(())
    })?;

    Ok((record_count, byte_count))
}

fn main() -> Result<(), ParseError> {
    let path = "large_input.txt";
    let (records, bytes) = parse_file(path)?;
    println!("Parsed {} records, {} payload bytes", records, bytes);
    Ok(())
}
