## More optimized variant with borrowed records

Here is a better foundation if you want lower allocation overhead:

```rust
use std::io::{self, BufReader, Read};

pub enum RecordView<'a> {
    Borrowed(&'a [u8]),
    Owned(Vec<u8>),
}

pub struct ZeroCopyParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    carry: Vec<u8>,
    config: ParserConfig,
}

impl<R: Read> ZeroCopyParser<R> {
    pub fn new(reader: R, config: ParserConfig) -> Self {
        let cap = config.read_buffer_size;
        Self {
            reader: BufReader::with_capacity(cap, reader),
            buf: vec![0; cap],
            carry: Vec::new(),
            config,
        }
    }

    pub fn parse_all<F>(&mut self, mut on_record: F) -> Result<(), ParseError>
    where
        F: for<'a> FnMut(RecordView<'a>) -> Result<(), ParseError>,
    {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            let chunk = &self.buf[..n];
            let mut start = 0;
            for i in 0..chunk.len() {
                if chunk[i] == self.config.delimiter {
                    if self.carry.is_empty() {
                        on_record(RecordView::Borrowed(&chunk[start..i]))?;
                    } else {
                        self.carry.extend_from_slice(&chunk[start..i]);
                        let owned = std::mem::take(&mut self.carry);
                        on_record(RecordView::Owned(owned))?;
                    }
                    start = i + 1;
                }
            }

            if start < chunk.len() {
                let rem = &chunk[start..];
                if self.carry.len() + rem.len() > self.config.max_record_size {
                    return Err(ParseError::RecordTooLarge {
                        size: self.carry.len() + rem.len(),
                        max: self.config.max_record_size,
                    });
                }
                self.carry.extend_from_slice(rem);
            }
        }

        if !self.carry.is_empty() {
            let tail = std::mem::take(&mut self.carry);
            on_record(RecordView::Owned(tail))?;
        }

        Ok(())
    }
}
```

