## Rust implementation

```rust
use std::fmt;
use std::io::{self, BufReader, Read};

/// A parsed record.
/// Fields borrow from the parser's internal buffer/scratch,
/// so they are only valid until the next parser call.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a [u8]>,
}

#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    RecordTooLarge(usize),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Io(e) => write!(f, "I/O error: {}", e),
            ParseError::RecordTooLarge(sz) => write!(f, "record too large: {} bytes", sz),
        }
    }
}

impl std::error::Error for ParseError {}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::Io(err)
    }
}

/// High-throughput streaming parser.
///
/// Design goals:
/// - process arbitrarily large streams incrementally
/// - avoid loading the full input into memory
/// - reuse allocations across records
/// - handle records split across buffer boundaries
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,

    /// Reusable read buffer.
    buf: Vec<u8>,

    /// Current valid bytes in buf: [start, end)
    start: usize,
    end: usize,

    /// Scratch buffer for records spanning chunks.
    scratch: Vec<u8>,

    /// Reusable field index storage.
    field_ranges: Vec<(usize, usize)>,

    /// Hard cap to avoid unbounded memory growth on malformed input.
    max_record_size: usize,

    /// EOF reached?
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R, capacity: usize, max_record_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(capacity, reader),
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            scratch: Vec::with_capacity(1024),
            field_ranges: Vec::with_capacity(16),
            max_record_size,
            eof: false,
        }
    }

    /// Returns the next record, or None at EOF.
    ///
    /// The returned record borrows memory owned by the parser and is valid
    /// only until the next call to `next_record`.
    pub fn next_record<'a>(&'a mut self) -> Result<Option<Record<'a>>, ParseError> {
        loop {
            // Try parsing from existing buffer first.
            if let Some(rec) = self.try_parse_from_buffer()? {
                return Ok(Some(rec));
            }

            // If EOF and nothing left to parse, we're done.
            if self.eof {
                if !self.scratch.is_empty() {
                    // Final unterminated record.
                    let rec = self.parse_record_from_scratch()?;
                    return Ok(Some(rec));
                }
                return Ok(None);
            }

            self.refill_buffer()?;
        }
    }

    fn try_parse_from_buffer<'a>(&'a mut self) -> Result<Option<Record<'a>>, ParseError> {
        let available = &self.buf[self.start..self.end];

        if available.is_empty() {
            return Ok(None);
        }

        if let Some(pos) = memchr::memchr(b'\n', available) {
            let line_start = self.start;
            let line_end = self.start + pos;

            if self.scratch.is_empty() {
                // Fast path: entire record is in current buffer.
                let rec_bytes = &self.buf[line_start..line_end];
                self.start = line_end + 1;
                let rec = self.parse_record_bytes(rec_bytes)?;
                return Ok(Some(rec));
            } else {
                // Slow path: record spans multiple chunks.
                self.scratch.extend_from_slice(&self.buf[line_start..line_end]);
                self.start = line_end + 1;
                let rec = self.parse_record_from_scratch()?;
                return Ok(Some(rec));
            }
        } else {
            // No newline found; append to scratch and consume current buffer.
            let chunk = &self.buf[self.start..self.end];
            if self.scratch.len() + chunk.len() > self.max_record_size {
                return Err(ParseError::RecordTooLarge(self.scratch.len() + chunk.len()));
            }
            self.scratch.extend_from_slice(chunk);
            self.start = self.end;
            Ok(None)
        }
    }

    fn refill_buffer(&mut self) -> Result<(), ParseError> {
        // Compact unread data if needed.
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        // If buffer is full and no newline was found, data has already been
        // moved to scratch, so we can safely refill from start.
        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }
        Ok(())
    }

    fn parse_record_from_scratch<'a>(&'a mut self) -> Result<Record<'a>, ParseError> {
        if self.scratch.len() > self.max_record_size {
            return Err(ParseError::RecordTooLarge(self.scratch.len()));
        }

        self.field_ranges.clear();
        split_fields(&self.scratch, &mut self.field_ranges);

        let fields = self
            .field_ranges
            .iter()
            .map(|&(s, e)| &self.scratch[s..e])
            .collect();

        self.scratch.clear();
        Ok(Record { fields })
    }

    fn parse_record_bytes<'a>(&'a mut self, bytes: &'a [u8]) -> Result<Record<'a>, ParseError> {
        self.field_ranges.clear();
        split_fields(bytes, &mut self.field_ranges);

        let fields = self
            .field_ranges
            .iter()
            .map(|&(s, e)| &bytes[s..e])
            .collect();

        Ok(Record { fields })
    }
}

/// Split fields on `|`, recording byte ranges.
/// Avoids allocating intermediate strings.
fn split_fields(bytes: &[u8], out: &mut Vec<(usize, usize)>) {
    let mut start = 0;
    for (i, &b) in bytes.iter().enumerate() {
        if b == b'|' {
            out.push((start, i));
            start = i + 1;
        }
    }
    out.push((start, bytes.len()));
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdin = io::stdin();
    let lock = stdin.lock();

    let mut parser = StreamingParser::new(lock, 64 * 1024, 16 * 1024 * 1024);

    while let Some(record) = parser.next_record()? {
        // Example processing with minimal overhead.
        // Avoid converting unless needed.
        println!("record with {} fields", record.fields.len());

        // Example: print first field as lossy UTF-8
        if let Some(first) = record.fields.get(0) {
            println!("  first field: {}", String::from_utf8_lossy(first));
        }
    }

    Ok(())
}
