use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A borrowed-or-owned record view.
/// Borrowed records point into the parser's internal buffer and are only valid
/// during the callback invocation.
/// Owned records are used when a record spans multiple chunks.
pub enum Record<'a> {
    Borrowed(&'a [u8]),
    Owned(Vec<u8>),
}

impl<'a> Record<'a> {
    pub fn as_bytes(&self) -> &[u8] {
        match self {
            Record::Borrowed(b) => b,
            Record::Owned(v) => v.as_slice(),
        }
    }
}

/// High-throughput streaming parser for delimiter-separated records.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    delimiter: u8,
    spill: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a fixed-capacity buffer.
    ///
    /// `buffer_size` should typically be something like 64 KiB, 256 KiB, or 1 MiB
    /// depending on workload and IO characteristics.
    pub fn new(reader: R, buffer_size: usize, delimiter: u8) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            buf: vec![0u8; buffer_size],
            start: 0,
            end: 0,
            delimiter,
            spill: Vec::new(),
            eof: false,
        }
    }

    /// Parse the stream record-by-record.
    ///
    /// The callback is invoked once per record. Returning an error from the callback
    /// stops parsing immediately.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        while !self.eof || self.start < self.end {
            if self.start == self.end && !self.eof {
                self.refill()?;
            }

            while self.start < self.end {
                let slice = &self.buf[self.start..self.end];

                if let Some(pos) = memchr(self.delimiter, slice) {
                    let record_end = self.start + pos;
                    let record = &self.buf[self.start..record_end];

                    if self.spill.is_empty() {
                        on_record(Record::Borrowed(record))?;
                    } else {
                        self.spill.extend_from_slice(record);
                        let owned = std::mem::take(&mut self.spill);
                        on_record(Record::Owned(owned))?;
                    }

                    self.start = record_end + 1;
                } else {
                    // No delimiter in remaining buffer; spill remainder and refill.
                    self.spill.extend_from_slice(slice);
                    self.start = self.end;
                    break;
                }
            }

            if self.start == self.end && !self.eof {
                self.refill()?;
            }
        }

        // Emit final record if EOF reached and there's remaining data without trailing delimiter.
        if !self.spill.is_empty() {
            let owned = std::mem::take(&mut self.spill);
            on_record(Record::Owned(owned))?;
        }

        Ok(())
    }

    fn refill(&mut self) -> io::Result<()> {
        self.start = 0;
        self.end = 0;

        let n = self.reader.read(&mut self.buf)?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end = n;
        }

        Ok(())
    }
}

/// Simple byte search helper.
/// For best performance, add `memchr = "2"` to Cargo.toml and use memchr::memchr.
/// This fallback keeps the example self-contained.
fn memchr(byte: u8, haystack: &[u8]) -> Option<usize> {
    haystack.iter().position(|&b| b == byte)
}

/// Example usage: count records and total bytes.
fn main() -> io::Result<()> {
    let path = Path::new("large_input.txt");
    let file = File::open(path)?;

    let mut parser = StreamingParser::new(file, 256 * 1024, b'\n');

    let mut count: u64 = 0;
    let mut total_bytes: u64 = 0;

    parser.parse(|record| {
        let bytes = record.as_bytes();
        count += 1;
        total_bytes += bytes.len() as u64;

        // Example processing:
        // - decode UTF-8 if needed
        // - parse fields
        // - aggregate stats
        // Avoid storing records unless necessary.

        Ok(())
    })?;

    println!("records: {}", count);
    println!("payload bytes: {}", total_bytes);

    Ok(())
}
