use memchr::memchr_iter;
use std::io::{self, Read};

/// A borrowed or owned parsed record.
///
/// Most records are returned as borrowed slices directly into the internal
/// buffer for zero-copy processing. If a record spans buffer boundaries,
/// it is assembled into `Owned`.
pub enum Record<'a> {
    Borrowed(&'a [u8]),
    Owned(Vec<u8>),
}

impl<'a> Record<'a> {
    pub fn as_bytes(&self) -> &[u8] {
        match self {
            Record::Borrowed(b) => b,
            Record::Owned(v) => v.as_slice(),
        }
    }
}

pub struct StreamParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    carry: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamParser<R> {
    /// Create a parser with a reusable fixed-size buffer.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            carry: Vec::new(),
            eof: false,
        }
    }

    /// Parse newline-delimited records and invoke `on_record` for each one.
    ///
    /// This keeps memory overhead low:
    /// - complete records within the current buffer are borrowed
    /// - only split records across buffer boundaries are copied into `carry`
    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            if self.start == self.end && !self.eof {
                self.fill_buf()?;
            }

            if self.start == self.end && self.eof {
                if !self.carry.is_empty() {
                    on_record(Record::Owned(std::mem::take(&mut self.carry)))?;
                }
                return Ok(());
            }

            let available = &self.buf[self.start..self.end];
            let mut last_consumed = 0usize;

            for nl_pos in memchr_iter(b'\n', available) {
                let record_end = nl_pos;
                let chunk = &available[last_consumed..record_end];

                if self.carry.is_empty() {
                    on_record(Record::Borrowed(chunk))?;
                } else {
                    self.carry.extend_from_slice(chunk);
                    on_record(Record::Owned(std::mem::take(&mut self.carry)))?;
                }

                last_consumed = nl_pos + 1;
            }

            if last_consumed < available.len() {
                self.carry.extend_from_slice(&available[last_consumed..]);
            }

            self.start += available.len();

            if self.start == self.end && !self.eof {
                self.fill_buf()?;
            }
        }
    }

    fn fill_buf(&mut self) -> io::Result<()> {
        self.start = 0;
        self.end = 0;

        let n = self.reader.read(&mut self.buf)?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end = n;
        }

        Ok(())
    }
}
```

