use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// Represents a parsed record.
/// Borrowed records point into the parser's internal buffer.
/// Owned records are used only when a record spans multiple chunks.
#[derive(Debug)]
pub enum Record<'a> {
    Borrowed(&'a [u8]),
    Owned(Vec<u8>),
}

impl<'a> Record<'a> {
    pub fn as_bytes(&self) -> &[u8] {
        match self {
            Record::Borrowed(b) => b,
            Record::Owned(v) => v,
        }
    }
}

/// High-throughput streaming parser for newline-delimited input.
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    scratch: Vec<u8>,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable buffer size.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        assert!(capacity > 0, "buffer capacity must be > 0");
        Self {
            reader,
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            scratch: Vec::new(),
            eof: false,
        }
    }

    /// Refill the internal buffer while preserving unread bytes.
    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        // Move unread bytes to the front.
        if self.start > 0 && self.start < self.end {
            let unread = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = unread;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        // If buffer is full and no delimiter found, caller should have already
        // moved data into scratch. We still try to read only if space exists.
        if self.end == self.buf.len() {
            return Ok(());
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    /// Parse records and invoke `on_record` for each one.
    ///
    /// Records are delimited by `\n`. The trailing newline is not included.
    /// A final unterminated record at EOF is also emitted.
    pub fn parse_all<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            // Search for complete records in current buffer.
            while self.start < self.end {
                if let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                    let newline_idx = self.start + pos;

                    if self.scratch.is_empty() {
                        // Fast path: record is fully in the current buffer.
                        let record = &self.buf[self.start..newline_idx];
                        on_record(Record::Borrowed(record))?;
                    } else {
                        // Slow path: record spans multiple chunks.
                        self.scratch
                            .extend_from_slice(&self.buf[self.start..newline_idx]);
                        let owned = std::mem::take(&mut self.scratch);
                        on_record(Record::Owned(owned))?;
                    }

                    self.start = newline_idx + 1;
                } else {
                    // No newline in remaining buffer.
                    break;
                }
            }

            // If EOF, emit trailing partial record if present.
            if self.eof {
                if self.start < self.end || !self.scratch.is_empty() {
                    if self.start < self.end {
                        self.scratch
                            .extend_from_slice(&self.buf[self.start..self.end]);
                        self.start = self.end;
                    }

                    let owned = std::mem::take(&mut self.scratch);
                    on_record(Record::Owned(owned))?;
                }
                return Ok(());
            }

            // If remaining bytes exist but no delimiter was found, accumulate them.
            if self.start < self.end {
                self.scratch
                    .extend_from_slice(&self.buf[self.start..self.end]);
                self.start = self.end;
            }

            self.refill()?;
        }
    }
}

/// Convenience function to parse a file.
pub fn parse_file<P, F>(path: P, buffer_size: usize, on_record: F) -> io::Result<()>
where
    P: AsRef<Path>,
    F: FnMut(Record<'_>) -> io::Result<()>,
{
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(buffer_size, file);
    let mut parser = StreamingParser::with_capacity(reader, buffer_size);
    parser.parse_all(on_record)
}

fn main() -> io::Result<()> {
