            records_parsed: 0,
        }
    }

    /// Create a parser with a reasonable default capacity.
    pub fn new(reader: R) -> Self {
        Self::with_capacity(reader, 1024 * 1024) // 1 MiB
    }

    /// Parse the input stream and send each record to the consumer.
    pub fn parse<C: RecordConsumer>(&mut self, consumer: &mut C) -> io::Result<()> {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            self.bytes_read += n as u64;
            self.process_chunk(&self.buf[..n], consumer)?;
        }

        // Flush any remaining partial record at EOF
        if !self.carry.is_empty() {
            consumer.on_record(&self.carry)?;
            self.records_parsed += 1;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<C: RecordConsumer>(
        &mut self,
        chunk: &[u8],
        consumer: &mut C,
    ) -> io::Result<()> {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record fully contained in current chunk
                    let mut record = &chunk[start..i];

                    // Trim optional CR for CRLF support
                    if let Some(b'\r') = record.last().copied() {
                        record = &record[..record.len() - 1];
                    }

                    consumer.on_record(record)?;
                } else {
                    // Slow path: record spans previous chunk(s)
                    self.carry.extend_from_slice(&chunk[start..i]);

                    if self.carry.last() == Some(&b'\r') {
                        self.carry.pop();
                    }

                    consumer.on_record(&self.carry)?;
                    self.carry.clear();
                }

                self.records_parsed += 1;
                start = i + 1;
            }
        }

        // Save trailing partial record
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }

    pub fn bytes_read(&self) -> u64 {
        self.bytes_read
    }

    pub fn records_parsed(&self) -> u64 {
        self.records_parsed
    }
}

/// Example consumer that counts records and bytes.
