# Features

- **Streaming**: processes data chunk-by-chunk
- **Low memory**: fixed buffer plus small carry-over for incomplete record
- **Boundary-safe**: handles lines split across chunk boundaries
- **Zero-copy where possible**: passes slices into callback when record is fully inside current buffer
- **Extensible**: easy to adapt to other delimiters or binary framing
- **High throughput**: uses `BufReader` and chunk scanning

---

# Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for delimiter-separated records.
///
/// This implementation is optimized for:
/// - large inputs
/// - low memory overhead
/// - incremental processing
///
/// It parses records separated by a single-byte delimiter, typically `b'\n'`.
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    delimiter: u8,
    buffer: Vec<u8>,
    carry: Vec<u8>,
    bytes_read: u64,
    records_parsed: u64,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable internal buffer size.
    ///
    /// `buffer_size` should generally be large enough to amortize I/O overhead
    /// but not so large that it hurts cache locality. Common values:
    /// - 64 KiB
    /// - 256 KiB
    /// - 1 MiB
    pub fn new(reader: R, delimiter: u8, buffer_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            delimiter,
            buffer: vec![0u8; buffer_size],
            carry: Vec::new(),
            bytes_read: 0,
            records_parsed: 0,
        }
    }

    /// Parse the stream and invoke `on_record` for each record.
    ///
    /// The callback receives a byte slice for each record, excluding the delimiter.
    ///
    /// Notes:
    /// - If a record spans buffers, it is assembled in `carry`.
    /// - If a record is fully contained in the current chunk and `carry` is empty,
    ///   the callback gets a direct slice into the internal buffer.
    /// - The callback must not retain the slice after returning.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            let n = self.reader.read(&mut self.buffer)?;
            if n == 0 {
                break;
            }

            self.bytes_read += n as u64;
            let chunk = &self.buffer[..n];

            let mut start = 0usize;

            for i in 0..chunk.len() {
                if chunk[i] == self.delimiter {
                    if self.carry.is_empty() {
                        // Fast path: record is entirely inside current chunk.
                        on_record(&chunk[start..i])?;
                    } else {
                        // Slow path: record spans previous chunk(s).
                        self.carry.extend_from_slice(&chunk[start..i]);
                        on_record(&self.carry)?;
                        self.carry.clear();
                    }

                    self.records_parsed += 1;
                    start = i + 1;
                }
            }

            // Save any trailing partial record.
            if start < chunk.len() {
                self.carry.extend_from_slice(&chunk[start..]);
            }
        }

        // Emit final record if input does not end with delimiter.
        if !self.carry.is_empty() {
            on_record(&self.carry)?;
            self.records_parsed += 1;
            self.carry.clear();
        }

        Ok(())
    }

    pub fn bytes_read(&self) -> u64 {
        self.bytes_read
    }

    pub fn records_parsed(&self) -> u64 {
        self.records_parsed
    }
}

/// Convenience constructor for files.
pub fn parser_from_file<P: AsRef<Path>>(
    path: P,
    delimiter: u8,
    buffer_size: usize,
) -> io::Result<StreamingParser<File>> {
    let file = File::open(path)?;
    Ok(StreamingParser::new(file, delimiter, buffer_size))
}

