        // if !record.is_empty() { ... }

        Ok(())
    })?;

    println!("bytes_read={}", parser.bytes_read());
    println!("records_parsed={}", parser.records_parsed());
    println!("processed_records={}", total_records);
    println!("processed_payload_bytes={}", total_bytes);

    Ok(())
}
