## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A high-throughput streaming parser for newline-delimited records.
///
/// It reads input in chunks, scans for '\n', and invokes a callback for each record.
/// Incomplete records at the end of a chunk are retained and completed by the next read.
///
/// Memory behavior:
/// - A single reusable buffer
/// - No per-record allocation unless the callback chooses to allocate
/// - Handles arbitrarily large inputs incrementally
pub struct StreamingParser<R: Read> {
    reader: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a parser with a fixed-capacity buffer.
    ///
    /// `buffer_size` should typically be tuned based on workload:
    /// - 64 KiB to 1 MiB is often a good starting point
    pub fn new(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 1, "buffer_size must be > 1");
        Self {
            reader,
            buf: vec![0; buffer_size],
            start: 0,
            end: 0,
            eof: false,
        }
    }

    /// Fill the buffer while preserving any unconsumed bytes.
    ///
    /// Layout:
    /// [ consumed | unconsumed........ | free space........ ]
    ///           ^start                ^end
    ///
    /// After compaction:
    /// [ unconsumed........ | free space..................... ]
    /// ^0                   ^end
    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        // Compact unconsumed bytes to the front.
        if self.start > 0 {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        }

        // If buffer is full and we still have no delimiter, the record is too large
        // for the current fixed buffer strategy.
        if self.end == self.buf.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "record exceeds buffer capacity; increase buffer size or implement spill/grow strategy",
            ));
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    /// Process all newline-delimited records.
    ///
    /// The callback receives each record *without* the trailing newline.
    /// If lines may end in CRLF, '\r' is stripped.
    pub fn parse_lines<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        loop {
            // Scan existing buffer for complete lines.
            while let Some(pos) = memchr::memchr(b'\n', &self.buf[self.start..self.end]) {
                let line_end = self.start + pos;
                let mut record = &self.buf[self.start..line_end];

                // Trim trailing '\r' for CRLF support.
                if let Some(b'\r') = record.last().copied() {
                    record = &record[..record.len() - 1];
                }

                on_record(record)?;
                self.start = line_end + 1;
            }

            if self.eof {
                // Emit trailing partial record if present.
                if self.start < self.end {
                    let mut record = &self.buf[self.start..self.end];
                    if let Some(b'\r') = record.last().copied() {
                        record = &record[..record.len() - 1];
                    }
                    on_record(record)?;
                    self.start = self.end;
                }
                break;
            }

            self.refill()?;
        }

        Ok(())
    }
}

/// Example consumer: count lines and bytes without allocating.
pub fn count_records_in_file<P: AsRef<Path>>(path: P) -> io::Result<(u64, u64)> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(1024 * 1024, file);
    let mut parser = StreamingParser::new(reader, 1024 * 1024);

    let mut records = 0u64;
    let mut bytes = 0u64;

    parser.parse_lines(|record| {
        records += 1;
        bytes += record.len() as u64;
        Ok(())
    })?;

    Ok((records, bytes))
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let (records, bytes) = count_records_in_file(path)?;
    println!("records={}, payload_bytes={}", records, bytes);
    Ok(())
}
