## Rust Implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// Callback trait for handling parsed records without storing them all in memory.
pub trait RecordHandler {
    fn on_record(&mut self, record: &[u8]) -> io::Result<()>;
}

/// High-throughput streaming parser for newline-delimited records.
///
/// Design goals:
/// - Reads input in fixed-size chunks
/// - Avoids loading the whole file into memory
/// - Minimizes allocations by reusing buffers
/// - Handles records spanning chunk boundaries
pub struct StreamingParser<R> {
    reader: R,
    buf: Vec<u8>,
    carry: Vec<u8>,
    bytes_read: u64,
    records_parsed: u64,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable buffer size.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        assert!(buffer_size > 0, "buffer_size must be > 0");
        Self {
            reader,
            buf: vec![0; buffer_size],
            carry: Vec::with_capacity(buffer_size / 4),
            bytes_read: 0,
            records_parsed: 0,
        }
    }

    /// Parse the stream, invoking `handler` for each complete record.
    pub fn parse<H: RecordHandler>(&mut self, handler: &mut H) -> io::Result<()> {
        loop {
            let n = self.reader.read(&mut self.buf)?;
            if n == 0 {
                break;
            }

            self.bytes_read += n as u64;
            let chunk = &self.buf[..n];
            self.process_chunk(chunk, handler)?;
        }

        // Flush trailing data as final record if non-empty.
        if !self.carry.is_empty() {
            handler.on_record(&self.carry)?;
            self.records_parsed += 1;
            self.carry.clear();
        }

        Ok(())
    }

    fn process_chunk<H: RecordHandler>(
        &mut self,
        chunk: &[u8],
        handler: &mut H,
    ) -> io::Result<()> {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record fully contained in current chunk.
                    let record = &chunk[start..i];
                    handler.on_record(record)?;
                } else {
                    // Slow path: record spans previous chunk(s).
                    self.carry.extend_from_slice(&chunk[start..i]);
                    handler.on_record(&self.carry)?;
                    self.carry.clear();
                }

                self.records_parsed += 1;
                start = i + 1;
            }
        }

        // Save incomplete tail for next chunk.
        if start < chunk.len() {
            self.carry.extend_from_slice(&chunk[start..]);
        }

        Ok(())
    }

    pub fn bytes_read(&self) -> u64 {
        self.bytes_read
    }

    pub fn records_parsed(&self) -> u64 {
        self.records_parsed
    }
}

/// Example handler that counts records and bytes without storing them.
pub struct StatsHandler {
    pub record_count: u64,
    pub total_record_bytes: u64,
}

impl StatsHandler {
    pub fn new() -> Self {
        Self {
            record_count: 0,
            total_record_bytes: 0,
        }
    }
}

impl RecordHandler for StatsHandler {
    fn on_record(&mut self, record: &[u8]) -> io::Result<()> {
        self.record_count += 1;
        self.total_record_bytes += record.len() as u64;
        Ok(())
    }
}

/// Convenience function for parsing a file.
pub fn parse_file<P: AsRef<Path>, H: RecordHandler>(
    path: P,
    buffer_size: usize,
    handler: &mut H,
) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(buffer_size, file);
    let mut parser = StreamingParser::new(reader, buffer_size);
    parser.parse(handler)?;

    eprintln!(
        "Done: {} bytes read, {} records parsed",
        parser.bytes_read(),
        parser.records_parsed()
    );

    Ok(())
}

fn main() -> io::Result<()> {
    let path = "large_input.txt";
    let buffer_size = 1024 * 1024; // 1 MiB

    let mut handler = StatsHandler::new();
    parse_file(path, buffer_size, &mut handler)?;

    println!("Records: {}", handler.record_count);
    println!("Total record bytes: {}", handler.total_record_bytes);

    Ok(())
}
```

