## Rust implementation

```rust
use std::io::{self, BufReader, Read};

/// A parsed record referencing internal parser storage.
///
/// Lifetime is tied to the parser's internal line buffer, so callers
/// must consume the record before requesting the next one.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a str>,
}

/// High-throughput streaming parser for delimiter-separated, newline-terminated records.
///
/// Characteristics:
/// - Reads from any `Read`
/// - Processes incrementally
/// - Maintains bounded memory
/// - Handles lines crossing chunk boundaries
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    delimiter: u8,

    /// Raw read buffer
    read_buf: Vec<u8>,

    /// Pending bytes that have not yet formed a complete line
    pending: Vec<u8>,

    /// Reused field index storage to reduce allocations
    field_ranges: Vec<(usize, usize)>,

    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser with a configurable buffer size.
    pub fn new(reader: R, delimiter: u8, buffer_size: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(buffer_size, reader),
            delimiter,
            read_buf: vec![0; buffer_size],
            pending: Vec::with_capacity(buffer_size),
            field_ranges: Vec::with_capacity(16),
            eof: false,
        }
    }

    /// Read and parse the next record.
    ///
    /// Returns:
    /// - Ok(Some(record)) when a record is available
    /// - Ok(None) on EOF
    /// - Err(...) on I/O or UTF-8 errors
    pub fn next_record(&mut self) -> io::Result<Option<Record<'_>>> {
        loop {
            if let Some(line_end) = self.pending.iter().position(|&b| b == b'\n') {
                let mut line_len = line_end;
                if line_len > 0 && self.pending[line_len - 1] == b'\r' {
                    line_len -= 1;
                }

                self.field_ranges.clear();
                self.split_fields(line_len);

                let record = self.build_record()?;

                // Remove consumed line plus '\n'
                self.pending.drain(..line_end + 1);

                return Ok(Some(record));
            }

            if self.eof {
                if self.pending.is_empty() {
                    return Ok(None);
                }

                let mut line_len = self.pending.len();
                if line_len > 0 && self.pending[line_len - 1] == b'\r' {
                    line_len -= 1;
                }

                self.field_ranges.clear();
                self.split_fields(line_len);

                let record = self.build_record()?;
                self.pending.clear();

                return Ok(Some(record));
            }

            let n = self.reader.read(&mut self.read_buf)?;
            if n == 0 {
                self.eof = true;
            } else {
                self.pending.extend_from_slice(&self.read_buf[..n]);
            }
        }
    }

    fn split_fields(&mut self, line_len: usize) {
        let mut start = 0;
        for i in 0..line_len {
            if self.pending[i] == self.delimiter {
                self.field_ranges.push((start, i));
                start = i + 1;
            }
        }
        self.field_ranges.push((start, line_len));
    }

    fn build_record(&self) -> io::Result<Record<'_>> {
        let mut fields = Vec::with_capacity(self.field_ranges.len());
        for &(start, end) in &self.field_ranges {
            let s = std::str::from_utf8(&self.pending[start..end]).map_err(|e| {
                io::Error::new(io::ErrorKind::InvalidData, format!("invalid UTF-8: {}", e))
            })?;
            fields.push(s);
        }
        Ok(Record { fields })
    }
}

fn main() -> io::Result<()> {
    let data = b"name,age,city\nAlice,30,London\nBob,25,Paris\n";
    let cursor = std::io::Cursor::new(data);

    let mut parser = StreamingParser::new(cursor, b',', 64 * 1024);

    while let Some(record) = parser.next_record()? {
        println!("{:?}", record.fields);
    }

    Ok(())
}
```

