# Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// A parsed record represented as ranges into an internal buffer.
/// This avoids allocating Strings per field.
#[derive(Debug)]
pub struct Record {
    /// Byte ranges of fields within `data`
    pub fields: Vec<std::ops::Range<usize>>,
    /// Backing storage for the record contents
    pub data: Vec<u8>,
}

impl Record {
    pub fn field(&self, idx: usize) -> Option<&str> {
        let range = self.fields.get(idx)?;
        std::str::from_utf8(&self.data[range.clone()]).ok()
    }

    pub fn field_bytes(&self, idx: usize) -> Option<&[u8]> {
        let range = self.fields.get(idx)?;
        Some(&self.data[range.clone()])
    }

    pub fn len(&self) -> usize {
        self.fields.len()
    }

    pub fn is_empty(&self) -> bool {
        self.fields.is_empty()
    }
}

/// A high-throughput streaming parser for newline-delimited, comma-separated records.
///
/// Example input:
///   alpha,beta,gamma\n
///   one,two,three\n
///
/// Notes:
/// - Handles records split across chunk boundaries
/// - Uses a reusable internal buffer
/// - Copies only the bytes needed for the current record
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
}

impl<R: Read> StreamingParser<R> {
    /// Create parser with a configurable internal buffer size.
    ///
    /// For high-throughput workloads, 64 KiB to 1 MiB is often a good starting range.
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader: BufReader::with_capacity(capacity, reader),
            buf: vec![0; capacity],
            start: 0,
            end: 0,
            eof: false,
        }
    }

    pub fn new(reader: R) -> Self {
        Self::with_capacity(reader, 64 * 1024)
    }

    /// Reads more data into the internal buffer, compacting first if needed.
    fn refill(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }

        // If there is unconsumed data, move it to the front.
        if self.start > 0 && self.start < self.end {
            let remaining = self.end - self.start;
            self.buf.copy_within(self.start..self.end, 0);
            self.start = 0;
            self.end = remaining;
        } else if self.start == self.end {
            self.start = 0;
            self.end = 0;
        }

        // If buffer is full and no delimiter found yet, grow it.
        if self.end == self.buf.len() {
            let new_len = self.buf.len().max(1) * 2;
            self.buf.resize(new_len, 0);
        }

        let n = self.reader.read(&mut self.buf[self.end..])?;
        if n == 0 {
            self.eof = true;
        } else {
            self.end += n;
        }

        Ok(())
    }

    /// Returns the next parsed record, or None on EOF.
    pub fn next_record(&mut self) -> io::Result<Option<Record>> {
        loop {
            // Search for newline in available data
            if let Some(pos) = self.buf[self.start..self.end]
                .iter()
                .position(|&b| b == b'\n')
            {
                let line_end = self.start + pos;
                let mut line = &self.buf[self.start..line_end];

                // Trim trailing '\r' for CRLF compatibility
                if let Some(&b'\r') = line.last() {
                    line = &line[..line.len() - 1];
                }

                let record = parse_record(line);

                // Consume line + '\n'
                self.start = line_end + 1;
                return Ok(Some(record));
            }

            // If EOF and remaining data exists, parse final unterminated line
            if self.eof {
                if self.start < self.end {
                    let mut line = &self.buf[self.start..self.end];
                    if let Some(&b'\r') = line.last() {
                        line = &line[..line.len() - 1];
                    }
                    let record = parse_record(line);
                    self.start = self.end;
                    return Ok(Some(record));
                } else {
                    return Ok(None);
                }
            }

            self.refill()?;
        }
    }
}

/// Parse a single comma-separated line into a Record.
/// This implementation does not yet handle quoted CSV escaping.
/// It is intended as a high-throughput baseline parser.
fn parse_record(line: &[u8]) -> Record {
    let mut data = Vec::with_capacity(line.len());
    data.extend_from_slice(line);

    let mut fields = Vec::with_capacity(8);
    let mut field_start = 0;

    for (i, &b) in data.iter().enumerate() {
        if b == b',' {
            fields.push(field_start..i);
            field_start = i + 1;
        }
    }

    // Final field
    fields.push(field_start..data.len());

    Record { fields, data }
}

/// Example processing loop.
/// This keeps memory usage bounded while processing arbitrarily large files.
pub fn process_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let mut parser = StreamingParser::with_capacity(file, 256 * 1024);

    let mut record_count: u64 = 0;

    while let Some(record) = parser.next_record()? {
        // Example: access fields without allocating new strings
        if let Some(first) = record.field(0) {
            // Do work here
            let _ = first;
        }

        record_count += 1;

        if record_count % 1_000_000 == 0 {
            eprintln!("Processed {} records", record_count);
        }
    }

    eprintln!("Finished. Total records: {}", record_count);
    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");
    process_file(path)
}
```

