Below is a compact, memory-conscious log rotation daemon in **C** for Linux. It:

- Monitors one or more log files
- Rotates when size exceeds a limit
- Keeps a fixed number of backups
- Uses low, predictable memory
- Avoids dynamic allocation in the hot path
- Can run as a daemon
- Uses polling instead of inotify to keep implementation simple and bounded

It is designed for **strict memory environments**, not for feature richness.

---

## Features

- Fixed upper bounds:
  - max number of files
  - max path length
- No heap allocation after startup
- Small stack usage
- Simple polling loop
- Rotation pattern:
  - `app.log` -> `app.log.1`
  - `app.log.1` -> `app.log.2`
  - ...
- Optional copy-truncate mode is omitted to keep memory and complexity low
- Reopens by renaming the active file and creating a new one

---

## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef MAX_FILES
#define MAX_FILES 32
#endif

#ifndef MAX_PATH_LEN
#define MAX_PATH_LEN 256
#endif

#ifndef DEFAULT_POLL_SEC
#define DEFAULT_POLL_SEC 5
#endif

#ifndef DEFAULT_ROTATIONS
#define DEFAULT_ROTATIONS 5
#endif

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int rotations;
    mode_t create_mode;
    uid_t uid;
    gid_t gid;
} log_cfg_t;

static volatile sig_atomic_t g_stop = 0;
static volatile sig_atomic_t g_reload = 0;

static log_cfg_t g_logs[MAX_FILES];
static size_t g_log_count = 0;
static int g_poll_sec = DEFAULT_POLL_SEC;
static int g_foreground = 0;
static const char *g_config_path = NULL;

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_stop = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_msg(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    if (g_foreground) {
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
    }
    va_end(ap);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > 2) close(fd);

    if (chdir("/") < 0) return -1;
    umask(022);
    return 0;
}

static void trim(char *s) {
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r' ||
                       s[len - 1] == ' ' || s[len - 1] == '\t')) {
        s[--len] = '\0';
    }
    size_t i = 0;
    while (s[i] == ' ' || s[i] == '\t') i++;
    if (i > 0) memmove(s, s + i, strlen(s + i) + 1);
}

static int parse_line(char *line, log_cfg_t *cfg) {
    // Format:
    // /path/to/file.log max_size_bytes rotations [mode_octal] [uid] [gid]
    // Example:
    // /var/log/app.log 10485760 5 0644 0 0

    char *save = NULL;
    char *tok = strtok_r(line, " \t", &save);
    if (!tok) return -1;
    if (strlen(tok) >= MAX_PATH_LEN) return -1;
    strncpy(cfg->path, tok, sizeof(cfg->path) - 1);
    cfg->path[sizeof(cfg->path) - 1] = '\0';

    tok = strtok_r(NULL, " \t", &save);
    if (!tok) return -1;
    errno = 0;
    long long max_size = strtoll(tok, NULL, 10);
    if (errno || max_size < 0) return -1;
    cfg->max_size = (off_t)max_size;

    tok = strtok_r(NULL, " \t", &save);
    if (!tok) return -1;
    errno = 0;
    long rotations = strtol(tok, NULL, 10);
    if (errno || rotations < 1 || rotations > 999) return -1;
    cfg->rotations = (int)rotations;

    cfg->create_mode = 0644;
    cfg->uid = (uid_t)-1;
    cfg->gid = (gid_t)-1;

    tok = strtok_r(NULL, " \t", &save);
    if (tok) {
        errno = 0;
        long mode = strtol(tok, NULL, 8);
        if (errno || mode < 0 || mode > 0777) return -1;
        cfg->create_mode = (mode_t)mode;
    }

    tok = strtok_r(NULL, " \t", &save);
    if (tok) {
        errno = 0;
        long uid = strtol(tok, NULL, 10);
        if (errno || uid < 0) return -1;
        cfg->uid = (uid_t)uid;
    }

    tok = strtok_r(NULL, " \t", &save);
    if (tok) {
        errno = 0;
        long gid = strtol(tok, NULL, 10);
        if (errno || gid < 0) return -1;
        cfg->gid = (gid_t)gid;
    }

    return 0;
}

static int load_config(const char *path) {
    FILE *f = fopen(path, "r");
    if (!f) {
        log_msg("failed to open config %s: %s", path, strerror(errno));
        return -1;
    }

    char line[512];
    log_cfg_t new_logs[MAX_FILES];
    size_t count = 0;

    while (fgets(line, sizeof(line), f)) {
        trim(line);
        if (line[0] == '\0' || line[0] == '#') continue;
        if (count >= MAX_FILES) {
            log_msg("too many log entries, max=%d", MAX_FILES);
            fclose(f);
            return -1;
        }
        if (parse_line(line, &new_logs[count]) != 0) {
            log_msg("invalid config line: %s", line);
            fclose(f);
            return -1;
        }
        count++;
    }

    fclose(f);

    memcpy(g_logs, new_logs, sizeof(log_cfg_t) * count);
    g_log_count = count;
    log_msg("loaded %zu log entries", g_log_count);
    return 0;
}

static int ensure_new_active_file(const log_cfg_t *cfg) {
    int fd = open(cfg->path, O_WRONLY | O_CREAT | O_APPEND, cfg->create_mode);
    if (fd < 0) {
        log_msg("open create failed for %s: %s", cfg->path, strerror(errno));
        return -1;
    }

    if (cfg->uid != (uid_t)-1 || cfg->gid != (gid_t)-1) {
        uid_t uid = (cfg->uid == (uid_t)-1) ? (uid_t)-1 : cfg->uid;
        gid_t gid = (cfg->gid == (gid_t)-1) ? (gid_t)-1 : cfg->gid;
        if (fchown(fd, uid, gid) < 0) {
            log_msg("fchown failed for %s: %s", cfg->path, strerror(errno));
        }
    }

    if (fchmod(fd, cfg->create_mode) < 0) {
        log_msg("fchmod failed for %s: %s", cfg->path, strerror(errno));
    }

    close(fd);
    return 0;
}

static int rotate_one(const log_cfg_t *cfg) {
    char oldp[MAX_PATH_LEN + 16];
    char newp[MAX_PATH_LEN + 16];

    for (int i = cfg->rotations; i >= 1; --i) {
        if (i == cfg->rotations) {
            if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, i) != 0)
                return -1;
            unlink(oldp);
        } else {
            if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, i) != 0)
                return -1;
            if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->path, i + 1) != 0)
                return -1;
            if (rename(oldp, newp) < 0 && errno != ENOENT) {
                log_msg("rename %s -> %s failed: %s", oldp, newp, strerror(errno));
                return -1;
            }
        }
    }

    if (safe_snprintf(newp, sizeof(newp), "%s.1", cfg->path) != 0)
        return -1;

    if (rename(cfg->path, newp) < 0) {
        if (errno == ENOENT) {
            return ensure_new_active_file(cfg);
        }
        log_msg("rename %s -> %s failed: %s", cfg->path, newp, strerror(errno));
        return -1;
    }

    if (ensure_new_active_file(cfg) != 0) {
        return -1;
    }

    log_msg("rotated %s", cfg->path);
    return 0;
}

static int check_and_rotate(const log_cfg_t *cfg) {
    struct stat st;
    if (stat(cfg->path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_new_active_file(cfg);
        }
        log_msg("stat failed for %s: %s", cfg->path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg("not a regular file: %s", cfg->path);
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_one(cfg);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -c <config> [-f] [-p poll_seconds]\n"
        "  -c <config>   Config file path\n"
        "  -f            Foreground mode\n"
        "  -p <seconds>  Poll interval (default %d)\n",
        prog, DEFAULT_POLL_SEC);
}

int main(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "c:fp:")) != -1) {
        switch (opt) {
            case 'c':
                g_config_path = optarg;
                break;
            case 'f':
                g_foreground = 1;
                break;
            case 'p': {
                long v = strtol(optarg, NULL, 10);
                if (v <= 0 || v > 3600) {
                    fprintf(stderr, "invalid poll interval\n");
                    return 1;
                }
                g_poll_sec = (int)v;
                break;
            }
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (!g_config_path) {
        usage(argv[0]);
        return 1;
    }

    if (load_config(g_config_path) != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);

    if (!g_foreground) {
        if (daemonize_self() != 0) {
            fprintf(stderr, "daemonize failed: %s\n", strerror(errno));
            return 1;
        }
    }

    while (!g_stop) {
        if (g_reload) {
            g_reload = 0;
            if (load_config(g_config_path) != 0) {
                log_msg("config reload failed, keeping old config");
            }
        }

        for (size_t i = 0; i < g_log_count; ++i) {
            check_and_rotate(&g_logs[i]);
        }

        for (int i = 0; i < g_poll_sec && !g_stop && !g_reload; ++i) {
            sleep(1);
        }
    }

    return 0;
}
```

