Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits. It:

- uses fixed-size buffers
- avoids dynamic allocation
- rotates based on file size
- keeps a fixed number of rotated files
- can optionally truncate instead of rename-chain if desired
- sleeps between checks to avoid CPU churn

This is a practical minimal implementation, not a full `logrotate` replacement.

## Features

- Monitors one log file
- Rotates when file exceeds a configured size
- Keeps `N` backups:
  - `log`
  - `log.1`
  - `log.2`
  - ...
- Uses `stat`, `rename`, `open`, `ftruncate`
- No heap allocations
- Small stack footprint

---

## Code

```c
/*
 * memlogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogd memlogd.c
 *
 * Run:
 *   ./memlogd /var/log/myapp.log 1048576 5 5
 *
 * Args:
 *   <log_path> <max_size_bytes> <max_rotations> <check_interval_seconds>
 *
 * Example:
 *   ./memlogd /tmp/app.log 1048576 3 2
 *
 * Notes:
 * - No dynamic memory allocation.
 * - Uses fixed-size path buffers.
 * - Rotates by rename chain:
 *     log.(N-1) -> log.N
 *     ...
 *     log.1 -> log.2
 *     log -> log.1
 *   then recreates the main log file.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int safe_snprintf_path(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int recreate_log_file(const char *path, mode_t mode, uid_t uid, gid_t gid) {
    int fd = open(path, O_CREAT | O_TRUNC | O_WRONLY, mode);
    if (fd < 0) return -1;

    /* Best effort ownership restore */
    (void)fchown(fd, uid, gid);

    if (close(fd) < 0) return -1;
    return 0;
}

static int rotate_logs(const char *log_path, int max_rotations) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    struct stat st;

    if (stat(log_path, &st) < 0) {
        return -1;
    }

    /* Remove the oldest if it exists by renaming chain over it */
    for (int i = max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), log_path, i) < 0)
            return -1;
        if (safe_snprintf_path(new_path, sizeof(new_path), log_path, i + 1) < 0)
            return -1;

        /*
         * Ignore missing files; rename only if source exists.
         * rename() will overwrite destination atomically on POSIX filesystems.
         */
        if (access(old_path, F_OK) == 0) {
            if (rename(old_path, new_path) < 0) {
                return -1;
            }
        }
    }

    /* Rename current log to .1 */
    if (safe_snprintf_path(new_path, sizeof(new_path), log_path, 1) < 0)
        return -1;

    if (rename(log_path, new_path) < 0) {
        return -1;
    }

    /* Recreate original log file with original mode/owner if possible */
    if (recreate_log_file(log_path, st.st_mode & 0777, st.st_uid, st.st_gid) < 0) {
        return -1;
    }

    return 0;
}

static int check_and_rotate(const char *log_path, off_t max_size, int max_rotations) {
    struct stat st;

    if (stat(log_path, &st) < 0) {
        if (errno == ENOENT) {
            /* Create if missing */
            if (ensure_log_exists(log_path, 0644) < 0)
                return -1;
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= max_size) {
        if (rotate_logs(log_path, max_rotations) < 0) {
            return -1;
        }
    }

    return 0;
}

static void daemonize_if_needed(void) {
    pid_t pid = fork();
    if (pid < 0) {
        _exit(1);
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        _exit(1);
    }

    pid = fork();
    if (pid < 0) {
        _exit(1);
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") < 0) {
        _exit(1);
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }
}

static int parse_int(const char *s, long *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = v;
    return 0;
}

int main(int argc, char **argv) {
    long max_size_l;
    long max_rot_l;
    long interval_l;

    if (argc != 5) {
        fprintf(stderr,
                "Usage: %s <log_path> <max_size_bytes> <max_rotations> <check_interval_seconds>\n",
                argv[0]);
        return 1;
    }

    const char *log_path = argv[1];

    if (strlen(log_path) >= PATH_MAX) {
        fprintf(stderr, "Error: log path too long\n");
        return 1;
    }

    if (parse_int(argv[2], &max_size_l) < 0 || max_size_l <= 0) {
        fprintf(stderr, "Error: invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &max_rot_l) < 0 || max_rot_l < 1 || max_rot_l > 9999) {
        fprintf(stderr, "Error: invalid max_rotations\n");
        return 1;
    }

    if (parse_int(argv[4], &interval_l) < 0 || interval_l < 1 || interval_l > 86400) {
        fprintf(stderr, "Error: invalid check_interval_seconds\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    daemonize_if_needed();

    while (g_running) {
        if (check_and_rotate(log_path, (off_t)max_size_l, (int)max_rot_l) < 0) {
            /*
             * In daemon mode stderr goes to /dev/null.
             * For ultra-low memory, avoid complex logging here.
             */
        }

        struct timespec ts;
        ts.tv_sec = interval_l;
        ts.tv_nsec = 0;

        while (g_running && nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            /* resume sleeping */
        }
    }

    return 0;
}
```

---

## Why this is memory-constrained

This implementation keeps memory usage low by:

- no `malloc`, `calloc`, `realloc`, or free lists
- only a few fixed-size buffers:
  - two `PATH_MAX` arrays
  - a few structs like `stat`, `sigaction`, `timespec`
- no parsing of config files
- no linked lists, maps, or queues
- no in-memory log buffering

Typical runtime memory footprint will be very small aside from libc/process overhead.

---

## Important limitations

### 1. Writer process behavior
If another process keeps the log file open, rename-based rotation may not behave as expected unless that process reopens the file after rotation.

Common solutions:

- send `SIGHUP` to the writer after rotation
- use copy-truncate instead of rename
- ensure the application supports log reopening

### 2. No config file
This version only handles one file from command-line arguments.

### 3. No compression
Compression usually increases memory and CPU usage.

### 4. No locking
If multiple instances run on the same file, behavior is undefined.

---

## Optional improvement: copytruncate-free truncation mode

If your writer cannot reopen logs, you may prefer truncating the file in place after copying it. But copying increases complexity and may use more memory unless done with a tiny fixed buffer.

Here is a low-memory copy routine using a 4 KB buffer:

```c
static int copy_file_fixedbuf(const char *src, const char *dst, mode_t mode) {
    int in_fd = -1, out_fd = -1;
    char buf[4096];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_CREAT | O_TRUNC | O_WRONLY, mode);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    if (close(out_fd) < 0) return -1;
    return 0;
}
```

Then after copying `log -> log.1`, you could truncate the original:

```c
static int truncate_in_place(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int rc = ftruncate(fd, 0);
    close(fd);
    return rc;
}
```

This avoids requiring the writer to reopen the file, but it is less atomic.

