Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits. It avoids dynamic allocation in the hot path, uses fixed-size buffers, and rotates based on file size.

It:
- Monitors one log file
- Rotates when size exceeds a threshold
- Keeps a fixed number of rotated files
- Uses `rename()` for efficient rotation
- Sleeps between checks
- Uses no heap allocation after startup

## Features
- Low memory footprint
- No threads
- No large buffers
- Predictable behavior
- Suitable for embedded/Linux systems

---

## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_BACKUPS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    unsigned long long max_size;
    int max_backups;
    int check_interval_sec;
    int verbose;
} config_t;

static void handle_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static void log_msg(int verbose, const char *fmt, ...) {
    if (!verbose) return;
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int parse_ull(const char *s, unsigned long long *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_size_bytes] [-n backups] [-i interval_sec] [-v]\n"
        "  -f <logfile>         Path to log file\n"
        "  -s <bytes>           Rotate when file exceeds this size (default: %llu)\n"
        "  -n <count>           Number of backups to keep (default: %d)\n"
        "  -i <sec>             Check interval in seconds (default: %d)\n"
        "  -v                   Verbose logging\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_BACKUPS,
        DEFAULT_CHECK_INTERVAL_SEC);
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_backups > 0) {
        if (build_rotated_path(cfg->log_path, cfg->max_backups, old_path, sizeof(old_path)) != 0) {
            fprintf(stderr, "Path too long during rotation\n");
            return -1;
        }
        if (unlink(old_path) != 0 && errno != ENOENT) {
            perror("unlink oldest backup");
            return -1;
        }

        for (int i = cfg->max_backups - 1; i >= 1; --i) {
            if (build_rotated_path(cfg->log_path, i, old_path, sizeof(old_path)) != 0 ||
                build_rotated_path(cfg->log_path, i + 1, new_path, sizeof(new_path)) != 0) {
                fprintf(stderr, "Path too long during rotation\n");
                return -1;
            }

            if (rename(old_path, new_path) != 0) {
                if (errno != ENOENT) {
                    perror("rename backup");
                    return -1;
                }
            }
        }

        if (build_rotated_path(cfg->log_path, 1, new_path, sizeof(new_path)) != 0) {
            fprintf(stderr, "Path too long during rotation\n");
            return -1;
        }

        if (rename(cfg->log_path, new_path) != 0) {
            if (errno != ENOENT) {
                perror("rename active log");
                return -1;
            }
        }
    } else {
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            perror("unlink active log");
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("recreate log file");
        return -1;
    }
    close(fd);

    log_msg(cfg->verbose, "Rotated log: %s", cfg->log_path);
    return 0;
}

static int check_and_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        perror("stat");
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Target is not a regular file: %s\n", cfg->log_path);
        return -1;
    }

    if ((unsigned long long)st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_backups = DEFAULT_MAX_BACKUPS;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.verbose = 0;

    int daemon_mode = 0;
    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:vd")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg.log_path)) {
                    fprintf(stderr, "Log path too long\n");
                    return 1;
                }
                strncpy(cfg.log_path, optarg, sizeof(cfg.log_path) - 1);
                cfg.log_path[sizeof(cfg.log_path) - 1] = '\0';
                break;
            case 's':
                if (parse_ull(optarg, &cfg.max_size) != 0 || cfg.max_size == 0) {
                    fprintf(stderr, "Invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_backups) != 0) {
                    fprintf(stderr, "Invalid backup count\n");
                    return 1;
                }
                break;
            case 'i':
                if (parse_int(optarg, &cfg.check_interval_sec) != 0 || cfg.check_interval_sec <= 0) {
                    fprintf(stderr, "Invalid interval\n");
                    return 1;
                }
                break;
            case 'v':
                cfg.verbose = 1;
                break;
            case 'd':
                daemon_mode = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (daemon_mode) {
        if (daemonize_self() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        if (check_and_rotate(&cfg) != 0) {
            sleep(1);
        } else {
            sleep((unsigned int)cfg.check_interval_sec);
        }
    }

    return 0;
}
```

