## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE_BYTES (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    uint64_t max_size;
    int max_rotations;
    unsigned check_interval_sec;
    int daemonize;
    mode_t create_mode;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int get_file_size(const char *path, uint64_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, int index) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_rotations <= 0) {
        if (truncate(cfg->log_path, 0) < 0) return -1;
        return 0;
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, i) < 0)
            return -1;
        if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0)
            return -1;

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0)
        return -1;

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(cfg->log_path, O_CREAT | O_TRUNC | O_WRONLY, cfg->create_mode);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void sleep_interruptible(unsigned sec) {
    struct timespec req, rem;
    req.tv_sec = sec;
    req.tv_nsec = 0;

    while (g_running && nanosleep(&req, &rem) < 0) {
        if (errno == EINTR) {
            req = rem;
        } else {
            break;
        }
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

static void print_usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval_sec] [-d]\n"
        "  -f <logfile>      Path to log file\n"
        "  -s <max_bytes>    Rotate when file exceeds this size (default: %llu)\n"
        "  -n <rotations>    Number of rotated files to keep (default: %d)\n"
        "  -i <interval>     Check interval in seconds (default: %d)\n"
        "  -d                Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE_BYTES,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE_BYTES;
    cfg->max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg->check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg->daemonize = 0;
    cfg->create_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                    errno = ENAMETOOLONG;
                    return -1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg->max_size) < 0) return -1;
                break;
            case 'n':
                if (parse_int(optarg, &cfg->max_rotations) < 0) return -1;
                break;
            case 'i': {
                int tmp;
                if (parse_int(optarg, &tmp) < 0) return -1;
                cfg->check_interval_sec = (unsigned)tmp;
                break;
            }
            case 'd':
                cfg->daemonize = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    if (cfg->check_interval_sec == 0) cfg->check_interval_sec = 1;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    if (parse_args(argc, argv, &cfg) < 0) {
        print_usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(cfg.log_path, cfg.create_mode) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        uint64_t sz = 0;
        if (get_file_size(cfg.log_path, &sz) == 0) {
            if (sz >= cfg.max_size) {
                if (rotate_logs(&cfg) < 0) {
                    /* In a strict memory daemon, avoid verbose logging loops.
                       Best effort: continue after sleep. */
                }
            }
        } else {
            /* Recreate missing file if needed */
            (void)ensure_log_exists(cfg.log_path, cfg.create_mode);
        }

        sleep_interruptible(cfg.check_interval_sec);
    }

    return 0;
}
