## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_INTERVAL_SEC 1
#define DEFAULT_MAX_FILES 5
#define DEFAULT_LOG_MODE 0644

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    off_t rotate_size;
    int max_files;
    int poll_interval_sec;
    mode_t create_mode;
    int daemonize;
    int verbose;
};

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(int verbose, const char *fmt, ...) {
    if (!verbose) return;

    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    write(STDERR_FILENO, buf, strnlen(buf, sizeof(buf)));
    write(STDERR_FILENO, "\n", 1);
}

static int parse_size(const char *s, off_t *out) {
    if (!s || !*s || !out) return -1;

    char *end = NULL;
    errno = 0;
    unsigned long long val = strtoull(s, &end, 10);
    if (errno != 0 || end == s) return -1;

    unsigned long long mult = 1;
    if (*end != '\0') {
        if (end[1] != '\0') return -1;
        switch (*end) {
            case 'k': case 'K': mult = 1024ULL; break;
            case 'm': case 'M': mult = 1024ULL * 1024ULL; break;
            case 'g': case 'G': mult = 1024ULL * 1024ULL * 1024ULL; break;
            default: return -1;
        }
    }

    unsigned long long total = val * mult;
    if (total > (unsigned long long)INT64_MAX) return -1;

    *out = (off_t)total;
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dstsz, const char *base, int suffix) {
    int n;
    if (suffix <= 0) {
        n = snprintf(dst, dstsz, "%s", base);
    } else {
        n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    }

    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_CREAT | O_WRONLY, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_files < 1) {
        return 0;
    }

    /* Delete oldest */
    if (safe_snprintf_path(oldp, sizeof(oldp), cfg->log_path, cfg->max_files) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    unlink(oldp);

    /* Shift N-1 down to 1 upward */
    for (int i = cfg->max_files - 1; i >= 1; --i) {
        if (safe_snprintf_path(oldp, sizeof(oldp), cfg->log_path, i) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (safe_snprintf_path(newp, sizeof(newp), cfg->log_path, i + 1) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Move active log to .1 */
    if (safe_snprintf_path(newp, sizeof(newp), cfg->log_path, 1) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(cfg->log_path, newp) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate active log */
    int fd = open(cfg->log_path, O_CREAT | O_WRONLY | O_TRUNC, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int should_rotate(const struct config *cfg, int *result) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            *result = 0;
            return 0;
        }
        return -1;
    }

    *result = (st.st_size >= cfg->rotate_size) ? 1 : 0;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f <logfile> -s <size> [-n max_files] [-p poll_sec] [-m mode] [-d] [-v]\n"
        "  -f <logfile>   Path to log file\n"
        "  -s <size>      Rotate at size, e.g. 1048576, 10M, 512K\n"
        "  -n <files>     Number of rotated files to keep (default: 5)\n"
        "  -p <sec>       Poll interval seconds (default: 1)\n"
        "  -m <octal>     File mode for created log (default: 0644)\n"
        "  -d             Daemonize\n"
        "  -v             Verbose logging to stderr\n",
        prog
    );
}

static int parse_octal_mode(const char *s, mode_t *out) {
    if (!s || !*s || !out) return -1;
    char *end = NULL;
    errno = 0;
    unsigned long val = strtoul(s, &end, 8);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (val > 0777) return -1;
    *out = (mode_t)val;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_files = DEFAULT_MAX_FILES;
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg->create_mode = DEFAULT_LOG_MODE;
    cfg->daemonize = 0;
    cfg->verbose = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:m:dv")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                    return -1;
                }
                break;
            case 's':
                if (parse_size(optarg, &cfg->rotate_size) != 0) {
                    return -1;
                }
                break;
            case 'n': {
                char *end = NULL;
                errno = 0;
                long v = strtol(optarg, &end, 10);
                if (errno != 0 || end == optarg || *end != '\0' || v < 1 || v > 1000) {
                    return -1;
                }
                cfg->max_files = (int)v;
                break;
            }
            case 'p': {
                char *end = NULL;
                errno = 0;
                long v = strtol(optarg, &end, 10);
                if (errno != 0 || end == optarg || *end != '\0' || v < 1 || v > 3600) {
                    return -1;
                }
                cfg->poll_interval_sec = (int)v;
                break;
            }
            case 'm':
                if (parse_octal_mode(optarg, &cfg->create_mode) != 0) {
                    return -1;
                }
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'v':
                cfg->verbose = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0' || cfg->rotate_size <= 0) {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            return 1;
        }
    }

    if (ensure_log_exists(&cfg) != 0) {
        log_msg(cfg.verbose, "failed to create log file '%s': %s", cfg.log_path, strerror(errno));
        return 1;
    }

    log_msg(cfg.verbose, "started monitoring %s", cfg.log_path);

    while (g_running) {
        int rotate = 0;
        if (should_rotate(&cfg, &rotate) != 0) {
            log_msg(cfg.verbose, "stat failed for '%s': %s", cfg.log_path, strerror(errno));
        } else if (rotate) {
            log_msg(cfg.verbose, "rotating %s", cfg.log_path);
            if (rotate_logs(&cfg) != 0) {
                log_msg(cfg.verbose, "rotation failed for '%s': %s", cfg.log_path, strerror(errno));
            }
        }

        sleep((unsigned int)cfg.poll_interval_sec);
    }

    log_msg(cfg.verbose, "shutting down");
    return 0;
}
