Below is a compact, memory-conscious log rotation daemon in C for Linux. It:

- Watches a single log file path
- Rotates when file size exceeds a threshold
- Keeps `N` rotated files
- Uses fixed-size buffers only
- Avoids dynamic allocation
- Can daemonize
- Tries to stay within strict memory constraints

It is intentionally simple and conservative.

## Features

- No heap allocation in normal operation
- Small fixed buffers
- Periodic polling instead of inotify to reduce complexity
- Rotation scheme:
  - `app.log` → `app.log.1`
  - `app.log.1` → `app.log.2`
  - ...
  - oldest removed if exceeding retention count

## Code

```c
/*
 * memlogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Usage:
 *   ./memlogrotate /var/log/app.log 10485760 5 5
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = polling interval in seconds
 *
 * Notes:
 * - Uses polling, not inotify.
 * - Avoids malloc().
 * - Assumes path length fits in PATH_MAX.
 * - Reopens/creates the log file after rotation.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, unsigned index) {
    int n = snprintf(dst, dst_sz, "%s.%u", base, index);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const char *path, unsigned keep_count, mode_t create_mode) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (keep_count == 0) {
        if (unlink(path) < 0 && errno != ENOENT) return -1;
        return ensure_log_exists(path, create_mode);
    }

    /* Remove oldest: path.keep_count */
    if (safe_snprintf_path(old_path, sizeof(old_path), path, keep_count) < 0) return -1;
    if (unlink(old_path) < 0 && errno != ENOENT) {
        return -1;
    }

    /* Shift: path.(n-1) -> path.n */
    for (unsigned i = keep_count; i > 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), path, i - 1) < 0) return -1;
        if (safe_snprintf_path(new_path, sizeof(new_path), path, i) < 0) return -1;

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    /* path -> path.1 */
    if (safe_snprintf_path(new_path, sizeof(new_path), path, 1) < 0) return -1;
    if (rename(path, new_path) < 0) {
        if (errno != ENOENT) return -1;
    }

    return ensure_log_exists(path, create_mode);
}

static int get_file_size_and_mode(const char *path, off_t *size_out, mode_t *mode_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    *mode_out = st.st_mode & 0777;
    return 0;
}

static void sleep_interval(unsigned seconds) {
    struct timespec req, rem;
    req.tv_sec = (time_t)seconds;
    req.tv_nsec = 0;

    while (g_running && nanosleep(&req, &rem) < 0) {
        if (errno == EINTR) {
            req = rem;
            continue;
        }
        break;
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned *out) {
    uint64_t v;
    if (parse_u64(s, &v) < 0) return -1;
    if (v > 0xFFFFFFFFu) return -1;
    *out = (unsigned)v;
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path;
    uint64_t max_size;
    unsigned keep_count;
    unsigned poll_seconds;
    off_t current_size;
    mode_t current_mode;

    if (argc != 5) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <keep_count> <poll_seconds>\n", argv[0]);
        return 1;
    }

    log_path = argv[1];

    if (strlen(log_path) >= PATH_MAX) {
        fprintf(stderr, "Error: log path too long\n");
        return 1;
    }

    if (parse_u64(argv[2], &max_size) < 0 || max_size == 0) {
        fprintf(stderr, "Error: invalid max_size_bytes\n");
        return 1;
    }

    if (parse_u32(argv[3], &keep_count) < 0) {
        fprintf(stderr, "Error: invalid keep_count\n");
        return 1;
    }

    if (parse_u32(argv[4], &poll_seconds) < 0 || poll_seconds == 0) {
        fprintf(stderr, "Error: invalid poll_seconds\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(log_path, 0644) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (daemonize_process() < 0) {
        perror("daemonize");
        return 1;
    }

    while (g_running) {
        if (get_file_size_and_mode(log_path, &current_size, &current_mode) == 0) {
            if ((uint64_t)current_size >= max_size) {
                if (rotate_logs(log_path, keep_count, current_mode ? current_mode : 0644) < 0) {
                    /* Silent in daemon mode; optionally write to syslog in a fuller version */
                }
            }
        } else {
            /* Recreate if missing */
            ensure_log_exists(log_path, 0644);
        }

        sleep_interval(poll_seconds);
    }

    return 0;
}
```

---

## Why this is memory-conscious

- No `malloc`, `calloc`, `realloc`, or large temporary structures
- Only a few stack buffers:
  - two `PATH_MAX` buffers during rotation
- Polling loop has constant memory usage
- No threads
- No directory scans
- No parsing of config files

---

## Important limitations

This is minimal. In production, you may want:

- `syslog()` error reporting
- PID file support
- privilege dropping
- `copytruncate` mode for apps that keep the file open
- compression of old logs
- multiple log targets
- config reload
- file locking to prevent multiple daemons rotating the same file

A key issue:

### Rename-based rotation may not work with all applications
If the writer keeps the old file descriptor open, after `rename()` it may continue writing to the renamed file instead of the newly created `app.log`.

For such applications, you may need `copytruncate`:
1. Copy current log to rotated file
2. Truncate original file in place

That is slower but preserves the inode.

---

## Optional: copytruncate variant

Here is a small helper you can use instead of renaming the active file:

```c
static int copy_file_then_truncate(const char *src, const char *dst, mode_t mode) {
    int in_fd = -1, out_fd = -1;
    char buf[4096];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (ftruncate(in_fd, 0) < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    close(out_fd);
    return 0;
}
```

You would integrate that into rotation logic for `path -> path.1`.

