## If you want stricter memory limits

You can add `setrlimit()`:

```c
#include <sys/resource.h>

static int apply_memory_limit_bytes(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}
```

For example, call before daemonizing:

```c
if (apply_memory_limit_bytes(8 * 1024 * 1024) < 0) {
    perror("setrlimit RLIMIT_AS");
    return 1;
}
```

You may also set:

- `RLIMIT_DATA`
- `RLIMIT_STACK`
- `RLIMIT_NOFILE`

Example:

```c
static int apply_resource_limits(void) {
    struct rlimit rl;

    rl.rlim_cur = rl.rlim_max = 8 * 1024 * 1024; /* 8 MB address space */
    if (setrlimit(RLIMIT_AS, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = 1 * 1024 * 1024; /* 1 MB stack */
    if (setrlimit(RLIMIT_STACK, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = 32; /* few file descriptors */
    if (setrlimit(RLIMIT_NOFILE, &rl) < 0) return -1;

    return 0;
}
```

