# Code: `memlogrotate.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_INTERVAL_SEC 5
#define DEFAULT_MODE 0644
#define MAX_ROTATIONS 100
#define LOG_MSG_BUF 256

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int rotations;
    unsigned poll_interval_sec;
    mode_t create_mode;
    int foreground;
};

static void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_msg(int priority, const char *fmt, ...) {
    char buf[LOG_MSG_BUF];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    syslog(priority, "%s", buf);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->rotations < 1 || cfg->rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->rotations) < 0) {
        return -1;
    }
    (void)unlink(oldp);

    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            if (ensure_log_exists(cfg) < 0) {
                log_msg(LOG_ERR, "failed to create missing log file '%s': %s",
                        cfg->log_path, strerror(errno));
                return -1;
            }
            return 0;
        }
        log_msg(LOG_ERR, "stat failed on '%s': %s", cfg->log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg(LOG_WARNING, "'%s' is not a regular file", cfg->log_path);
        return 0;
    }

    if (st.st_size >= cfg->max_size) {
        log_msg(LOG_INFO, "rotating '%s' at size %lld",
                cfg->log_path, (long long)st.st_size);
        if (rotate_logs(cfg) < 0) {
            log_msg(LOG_ERR, "rotation failed for '%s': %s",
                    cfg->log_path, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -p <log_path> -s <max_size_bytes> [-n rotations] [-i poll_sec] [-m octal_mode] [-f]\n"
        "  -p <path>       Log file path\n"
        "  -s <bytes>      Rotate when file size >= bytes\n"
        "  -n <count>      Number of rotated files to keep (default: 5, max: %d)\n"
        "  -i <sec>        Poll interval in seconds (default: %d)\n"
        "  -m <mode>       Create mode in octal (default: 0644)\n"
        "  -f              Run in foreground\n",
        prog, MAX_ROTATIONS, DEFAULT_POLL_INTERVAL_SEC);
}

static int parse_long_long(const char *s, long long *out) {
    char *end = NULL;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

static int parse_uint(const char *s, unsigned *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v > UINT32_MAX) return -1;
    *out = (unsigned)v;
    return 0;
}

static int parse_octal_mode(const char *s, mode_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 8);
    if (errno != 0 || end == s || *end != '\0' || v > 07777) return -1;
    *out = (mode_t)v;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->rotations = 5;
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg->create_mode = DEFAULT_MODE;
    cfg->foreground = 0;

    int opt;
    while ((opt = getopt(argc, argv, "p:s:n:i:m:f")) != -1) {
        switch (opt) {
            case 'p':
                if (strlen(optarg) >= sizeof(cfg->log_path)) {
                    fprintf(stderr, "path too long\n");
                    return -1;
                }
                strncpy(cfg->log_path, optarg, sizeof(cfg->log_path) - 1);
                cfg->log_path[sizeof(cfg->log_path) - 1] = '\0';
                break;
            case 's': {
                long long v;
                if (parse_long_long(optarg, &v) < 0 || v <= 0) {
                    fprintf(stderr, "invalid max size\n");
                    return -1;
                }
                cfg->max_size = (off_t)v;
                break;
            }
            case 'n': {
                long long v;
                if (parse_long_long(optarg, &v) < 0 || v < 1 || v > MAX_ROTATIONS) {
                    fprintf(stderr, "invalid rotations count\n");
                    return -1;
                }
                cfg->rotations = (int)v;
                break;
            }
            case 'i': {
                unsigned v;
                if (parse_uint(optarg, &v) < 0 || v == 0) {
                    fprintf(stderr, "invalid poll interval\n");
                    return -1;
                }
                cfg->poll_interval_sec = v;
                break;
            }
            case 'm':
                if (parse_octal_mode(optarg, &cfg->create_mode) < 0) {
                    fprintf(stderr, "invalid mode\n");
                    return -1;
                }
                break;
            case 'f':
                cfg->foreground = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0' || cfg->max_size <= 0) {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    openlog("memlogrotate", LOG_PID | LOG_NDELAY, LOG_DAEMON);

    if (install_signal_handlers() < 0) {
        fprintf(stderr, "failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (!cfg.foreground) {
        if (daemonize_process() < 0) {
            fprintf(stderr, "failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    log_msg(LOG_INFO, "started for '%s', max_size=%lld, rotations=%d, poll=%u",
            cfg.log_path, (long long)cfg.max_size, cfg.rotations, cfg.poll_interval_sec);

    while (!g_terminate) {
        if (g_reload) {
            g_reload = 0;
            log_msg(LOG_INFO, "received SIGHUP");
        }

        (void)check_and_rotate(&cfg);

        for (unsigned i = 0; i < cfg.poll_interval_sec; ++i) {
            if (g_terminate || g_reload) break;
            sleep(1);
        }
    }

    log_msg(LOG_INFO, "shutting down");
    closelog();
    return 0;
}
