## Code: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define COPY_BUF_SIZE 4096
#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#define DEFAULT_MEM_LIMIT_MB 16

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    off_t max_size;
    int rotations;
    int interval_sec;
    rlim_t mem_limit_bytes;
    int truncate_in_place;
    int foreground;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int in_fd = -1, out_fd = -1;
    char buf[COPY_BUF_SIZE];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (fsync(out_fd) != 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    close(out_fd);
    return 0;
}

static int truncate_file(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int rc = ftruncate(fd, 0);
    close(fd);
    return rc;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    struct stat st;

    if (stat(cfg->log_path, &st) != 0) {
        return -1;
    }

    if (cfg->rotations > 0) {
        if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, cfg->rotations) != 0)
            return -1;
        unlink(old_path);

        for (int i = cfg->rotations - 1; i >= 1; --i) {
            if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, i) != 0)
                return -1;
            if (safe_snprintf(new_path, sizeof(new_path), "%s.%d", cfg->log_path, i + 1) != 0)
                return -1;
            if (file_exists(old_path)) {
                if (rename(old_path, new_path) != 0) {
                    return -1;
                }
            }
        }

        if (safe_snprintf(new_path, sizeof(new_path), "%s.1", cfg->log_path) != 0)
            return -1;

        /*
         * Safer for processes that keep the original file descriptor open:
         * copy current log to .1, then truncate original file.
         */
        if (copy_file(cfg->log_path, new_path, st.st_mode & 0777) != 0) {
            return -1;
        }

        if (truncate_file(cfg->log_path) != 0) {
            return -1;
        }
    } else {
        if (cfg->truncate_in_place) {
            if (truncate_file(cfg->log_path) != 0) {
                return -1;
            }
        }
    }

    return 0;
}

static int check_and_rotate(const config_t *cfg) {
    off_t size = 0;
    if (get_file_size(cfg->log_path, &size) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    if (size >= cfg->max_size) {
        return rotate_logs(cfg);
    }
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_off_t(const char *s, off_t *out) {
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

static int parse_mem_mb(const char *s, rlim_t *out) {
    char *end = NULL;
    unsigned long long mb = strtoull(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    *out = (rlim_t)(mb * 1024ULL * 1024ULL);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval_sec]\n"
        "          [-m mem_limit_mb] [-t] [-F]\n"
        "\n"
        "  -f logfile       Path to log file\n"
        "  -s max_bytes     Rotate when file size >= max_bytes (default: %d)\n"
        "  -n rotations     Number of rotated files to keep (default: %d)\n"
        "  -i interval_sec  Poll interval in seconds (default: %d)\n"
        "  -m mem_limit_mb  RLIMIT_AS in MB (default: %d)\n"
        "  -t               Truncate in place if rotations=0\n"
        "  -F               Run in foreground\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS,
        DEFAULT_INTERVAL_SEC, DEFAULT_MEM_LIMIT_MB);
}

static void init_default_config(config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->mem_limit_bytes = (rlim_t)DEFAULT_MEM_LIMIT_MB * 1024 * 1024;
    cfg->truncate_in_place = 0;
    cfg->foreground = 0;
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:tF")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) return -1;
                strncpy(cfg->log_path, optarg, sizeof(cfg->log_path) - 1);
                cfg->log_path[sizeof(cfg->log_path) - 1] = '\0';
                break;
            case 's':
                if (parse_off_t(optarg, &cfg->max_size) != 0) return -1;
                break;
            case 'n':
                if (parse_int(optarg, &cfg->rotations) != 0) return -1;
                if (cfg->rotations < 0) return -1;
                break;
            case 'i':
                if (parse_int(optarg, &cfg->interval_sec) != 0) return -1;
                if (cfg->interval_sec <= 0) return -1;
                break;
            case 'm':
                if (parse_mem_mb(optarg, &cfg->mem_limit_bytes) != 0) return -1;
                break;
            case 't':
                cfg->truncate_in_place = 1;
                break;
            case 'F':
                cfg->foreground = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    init_default_config(&cfg);

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    if (set_memory_limit(cfg.mem_limit_bytes) != 0) {
        log_stderr("failed to set memory limit: %s", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!cfg.foreground) {
        if (daemonize_process() != 0) {
            log_stderr("failed to daemonize: %s", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        if (check_and_rotate(&cfg) != 0) {
            /* In daemon mode stderr goes to /dev/null unless redirected externally. */
            if (cfg.foreground) {
                log_stderr("rotation check failed: %s", strerror(errno));
            }
        }
        sleep((unsigned int)cfg.interval_sec);
    }

    return 0;
}
