/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 2 -d
 *
 * Notes:
 * - Polls file size every interval seconds.
 * - Rotates when size >= max_size.
 * - Keeps N rotated files: log.1 ... log.N
 * - Designed for low/constant memory use.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_SEC 2
#define DEFAULT_ROTATIONS    5
#define DEFAULT_MAX_SIZE     (10 * 1024 * 1024ULL)
#define DEFAULT_MEM_LIMIT    (8 * 1024 * 1024ULL)

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void write_stderr(const char *msg) {
    if (msg) {
        (void)write(STDERR_FILENO, msg, strlen(msg));
    }
}

static void die(const char *fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    write_stderr(buf);
    _exit(1);
}

struct config {
    char log_path[PATH_MAX];
    uint64_t max_size;
    int max_rotations;
    int interval_sec;
    int daemonize;
    rlim_t mem_limit_bytes;
};

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval] [-m mem_bytes] [-d]\n"
        "  -f <logfile>     Path to the log file\n"
        "  -s <max_bytes>   Rotate when file size >= this value (default: %llu)\n"
        "  -n <rotations>   Number of rotated files to keep (default: %d)\n"
        "  -i <interval>    Poll interval in seconds (default: %d)\n"
        "  -m <mem_bytes>   Memory limit in bytes (default: %llu)\n"
        "  -d               Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_ROTATIONS,
        DEFAULT_INTERVAL_SEC,
        (unsigned long long)DEFAULT_MEM_LIMIT
    );
}

static unsigned long long parse_ull(const char *s, const char *name) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        die("Invalid %s: %s\n", name, s);
    }
    return v;
}

static int parse_int(const char *s, const char *name) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < 0 || v > INT_MAX) {
        die("Invalid %s: %s\n", name, s);
    }
    return (int)v;
}

static void parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->max_rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->daemonize = 0;
    cfg->mem_limit_bytes = (rlim_t)DEFAULT_MEM_LIMIT;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) {
                    die("Log path too long\n");
                }
                strncpy(cfg->log_path, optarg, sizeof(cfg->log_path) - 1);
                cfg->log_path[sizeof(cfg->log_path) - 1] = '\0';
                break;
            case 's':
                cfg->max_size = parse_ull(optarg, "max_bytes");
                break;
            case 'n':
                cfg->max_rotations = parse_int(optarg, "rotations");
                break;
            case 'i':
                cfg->interval_sec = parse_int(optarg, "interval");
                break;
            case 'm':
                cfg->mem_limit_bytes = (rlim_t)parse_ull(optarg, "mem_bytes");
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                _exit(opt == 'h' ? 0 : 1);
        }
    }

    if (cfg->log_path[0] == '\0') {
        usage(argv[0]);
        die("Missing required -f <logfile>\n");
    }

    if (cfg->max_size == 0) {
        die("max_bytes must be > 0\n");
    }
    if (cfg->max_rotations < 1) {
        die("rotations must be >= 1\n");
    }
    if (cfg->interval_sec < 1) {
        die("interval must be >= 1\n");
    }
}

static void apply_memory_limits(rlim_t bytes) {
    struct rlimit rl;

    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        /* Not fatal on all systems, continue */
    }

    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        /* Not fatal */
    }

    /* Keep stack modest but not too tiny */
    rl.rlim_cur = (bytes < (rlim_t)(512 * 1024)) ? bytes : (rlim_t)(512 * 1024);
    rl.rlim_max = rl.rlim_cur;
    if (setrlimit(RLIMIT_STACK, &rl) != 0) {
        /* Not fatal */
    }
}

static void daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        die("fork failed: %s\n", strerror(errno));
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        die("setsid failed: %s\n", strerror(errno));
    }

    pid = fork();
    if (pid < 0) {
        die("fork failed: %s\n", strerror(errno));
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        die("chdir failed: %s\n", strerror(errno));
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) {
            close(fd);
        }
    }
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd < 0) {
        return -1;
    }
    return fd;
}

static int rotate_logs(const char *base, int max_rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    /* Remove the oldest */
    if (snprintf(oldp, sizeof(oldp), "%s.%d", base, max_rotations) >= (int)sizeof(oldp)) {
        errno = ENAMETOOLONG;
        return -1;
    }
    (void)unlink(oldp);

    /* Shift: .(n-1) -> .n */
    for (int i = max_rotations - 1; i >= 1; --i) {
        if (snprintf(oldp, sizeof(oldp), "%s.%d", base, i) >= (int)sizeof(oldp) ||
            snprintf(newp, sizeof(newp), "%s.%d", base, i + 1) >= (int)sizeof(newp)) {
            errno = ENAMETOOLONG;
            return -1;
        }
        (void)rename(oldp, newp);
    }

    /* Base -> .1 */
    if (snprintf(newp, sizeof(newp), "%s.1", base) >= (int)sizeof(newp)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(base, newp) != 0) {
        return -1;
    }

    return 0;
}

static int check_and_rotate(const struct config *cfg, int *log_fd) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            int fd = ensure_log_exists(cfg->log_path);
            if (fd < 0) {
                return -1;
            }
            if (*log_fd >= 0) close(*log_fd);
            *log_fd = fd;
            return 0;
        }
        return -1;
    }

    if ((uint64_t)st.st_size < cfg->max_size) {
        return 0;
    }

    if (*log_fd >= 0) {
        close(*log_fd);
        *log_fd = -1;
    }

    if (rotate_logs(cfg->log_path, cfg->max_rotations) != 0) {
        return -1;
    }

    int fd = ensure_log_exists(cfg->log_path);
    if (fd < 0) {
        return -1;
    }
    *log_fd = fd;
    return 1;
}

int main(int argc, char **argv) {
    struct config cfg;
    parse_args(argc, argv, &cfg);

    apply_memory_limits(cfg.mem_limit_bytes);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    (void)sigaction(SIGINT, &sa, NULL);
    (void)sigaction(SIGTERM, &sa, NULL);

    if (cfg.daemonize) {
        daemonize_process();
    }

    int log_fd = ensure_log_exists(cfg.log_path);
    if (log_fd < 0) {
        die("Cannot open log file %s: %s\n", cfg.log_path, strerror(errno));
    }

    while (!g_stop) {
        (void)check_and_rotate(&cfg, &log_fd);

        struct timespec ts;
        ts.tv_sec = cfg.interval_sec;
        ts.tv_nsec = 0;

        while (!g_stop && nanosleep(&ts, &ts) != 0 && errno == EINTR) {
            /* resume sleeping */
        }
    }

    if (log_fd >= 0) {
        close(log_fd);
    }

    return 0;
}
