Below is a small, memory-conscious log rotation daemon in C designed for Linux/Unix-like systems.

Features:
- Watches a single log file path
- Rotates when file exceeds a size threshold
- Keeps a fixed number of rotated files
- Uses constant/small memory
- Avoids dynamic allocation in the hot path
- Can run as a daemon
- Has strict-ish memory limiting via `setrlimit()`

This is intentionally simple and conservative.

---

## `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE_BYTES (10 * 1024 * 1024)
#define DEFAULT_MEMORY_LIMIT_BYTES (8 * 1024 * 1024)

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[PATH_MAX];
    size_t max_size;
    int max_rotations;
    int check_interval_sec;
    int daemonize;
    rlim_t memory_limit_bytes;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int set_memory_limit(rlim_t limit_bytes) {
    struct rlimit rl;
    rl.rlim_cur = limit_bytes;
    rl.rlim_max = limit_bytes;
    if (setrlimit(RLIMIT_AS, &rl) < 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_rotations < 1) {
        int fd = open(cfg->log_path, O_WRONLY | O_TRUNC);
        if (fd >= 0) {
            close(fd);
            return 0;
        }
        return -1;
    }

    if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) == 0) {
        unlink(old_path);
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0) {
            return -1;
        }
        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int check_and_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) {
                close(fd);
                return 0;
            }
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if ((size_t)st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_size_bytes] [-n rotations] [-i interval_sec] [-m mem_limit_bytes] [-d]\n"
        "  -f logfile           Path to log file\n"
        "  -s max_size_bytes    Rotate when file reaches this size (default: %d)\n"
        "  -n rotations         Number of rotated files to keep (default: %d)\n"
        "  -i interval_sec      Poll interval in seconds (default: %d)\n"
        "  -m mem_limit_bytes   RLIMIT_AS memory limit (default: %d)\n"
        "  -d                   Daemonize\n",
        prog,
        DEFAULT_MAX_SIZE_BYTES,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC,
        DEFAULT_MEMORY_LIMIT_BYTES
    );
}

static int parse_positive_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0' || v <= 0 || v > INT_MAX) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

static int parse_size_t_val(const char *s, size_t *out) {
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') {
        return -1;
    }
    if (v == 0 || v > SIZE_MAX) {
        return -1;
    }
    *out = (size_t)v;
    return 0;
}

static int parse_rlim_t_val(const char *s, rlim_t *out) {
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') {
        return -1;
    }
    *out = (rlim_t)v;
    return 0;
}

static void init_config(config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE_BYTES;
    cfg->max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg->check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg->daemonize = 0;
    cfg->memory_limit_bytes = DEFAULT_MEMORY_LIMIT_BYTES;
}

int main(int argc, char **argv) {
    config_t cfg;
    init_config(&cfg);

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg.log_path)) {
                    log_stderr("log path too long");
                    return 1;
                }
                strncpy(cfg.log_path, optarg, sizeof(cfg.log_path) - 1);
                cfg.log_path[sizeof(cfg.log_path) - 1] = '\0';
                break;
            case 's':
                if (parse_size_t_val(optarg, &cfg.max_size) < 0) {
                    log_stderr("invalid max size");
                    return 1;
                }
                break;
            case 'n':
                if (parse_positive_int(optarg, &cfg.max_rotations) < 0) {
                    log_stderr("invalid rotation count");
                    return 1;
                }
                break;
            case 'i':
                if (parse_positive_int(optarg, &cfg.check_interval_sec) < 0) {
                    log_stderr("invalid interval");
                    return 1;
                }
                break;
            case 'm':
                if (parse_rlim_t_val(optarg, &cfg.memory_limit_bytes) < 0) {
                    log_stderr("invalid memory limit");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        log_stderr("failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    if (set_memory_limit(cfg.memory_limit_bytes) < 0) {
        log_stderr("failed to set memory limit: %s", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            log_stderr("failed to daemonize: %s", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        if (check_and_rotate(&cfg) < 0) {
            /* In daemon mode stderr goes to /dev/null; in foreground user sees it. */
            log_stderr("check/rotate failed for %s: %s", cfg.log_path, strerror(errno));
        }

        struct timespec ts;
        ts.tv_sec = cfg.check_interval_sec;
        ts.tv_nsec = 0;

        while (g_running && nanosleep(&ts, &ts) < 0) {
            if (errno != EINTR) {
                break;
            }
        }
    }

    return 0;
}
