## Code

```c
/*
 * memlogrotate.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogrotate memlogrotate.c
 *
 * Usage:
 *   ./memlogrotate -f /var/log/myapp.log -s 10485760 -n 5 -i 5 -d
 *
 * Options:
 *   -f <file>       Log file to monitor
 *   -s <bytes>      Rotate when file size exceeds this value
 *   -n <count>      Number of rotated files to keep
 *   -i <seconds>    Poll interval
 *   -d              Run as daemon
 *   -t              copytruncate mode (truncate active file after copy)
 *
 * Notes:
 *   Default mode uses rename():
 *     app.log -> app.log.1, app.log.1 -> app.log.2, ...
 *   This is best if the writer reopens logs or handles renamed files.
 *
 *   copytruncate mode copies content to .1 and truncates the original.
 *   This is safer for programs that keep the file descriptor open, but
 *   introduces a small race and some I/O cost.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define COPY_BUF_SIZE 4096

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int backups;
    unsigned int interval_sec;
    bool daemonize;
    bool copytruncate;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <file> -s <bytes> [-n backups] [-i seconds] [-d] [-t]\n"
        "  -f <file>    Log file path\n"
        "  -s <bytes>   Rotate size threshold\n"
        "  -n <count>   Number of backups to keep (default: 5)\n"
        "  -i <sec>     Poll interval seconds (default: 5)\n"
        "  -d           Run as daemon\n"
        "  -t           copytruncate mode\n",
        prog);
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno || end == s || *end != '\0' || v < 0 || v > INT_MAX) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno || end == s || *end != '\0' || v < 0) {
        return -1;
    }
    *out = (off_t)v;
    return 0;
}

static int make_rotated_path(const char *base, int index, char *out, size_t outsz) {
    int n = snprintf(out, outsz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= outsz) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") < 0) {
        return -1;
    }

    umask(022);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    if (open("/dev/null", O_RDONLY) < 0) return -1;
    if (open("/dev/null", O_WRONLY) < 0) return -1;
    if (open("/dev/null", O_WRONLY) < 0) return -1;

    return 0;
}

static int copy_file_contents(const char *src, const char *dst, mode_t mode) {
    int srcfd = -1, dstfd = -1;
    char buf[COPY_BUF_SIZE];
    ssize_t r;

    srcfd = open(src, O_RDONLY);
    if (srcfd < 0) return -1;

    dstfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (dstfd < 0) {
        close(srcfd);
        return -1;
    }

    for (;;) {
        r = read(srcfd, buf, sizeof(buf));
        if (r == 0) break;
        if (r < 0) {
            if (errno == EINTR) continue;
            close(srcfd);
            close(dstfd);
            return -1;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dstfd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                close(srcfd);
                close(dstfd);
                return -1;
            }
            off += w;
        }
    }

    if (close(srcfd) < 0) {
        close(dstfd);
        return -1;
    }
    if (close(dstfd) < 0) {
        return -1;
    }

    return 0;
}

static int truncate_file(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int rc = ftruncate(fd, 0);
    close(fd);
    return rc;
}

static int rotate_by_rename(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->backups > 0) {
        if (make_rotated_path(cfg->log_path, cfg->backups, oldp, sizeof(oldp)) == 0) {
            unlink(oldp);
        }

        for (int i = cfg->backups - 1; i >= 1; --i) {
            if (make_rotated_path(cfg->log_path, i, oldp, sizeof(oldp)) < 0) return -1;
            if (make_rotated_path(cfg->log_path, i + 1, newp, sizeof(newp)) < 0) return -1;
            rename(oldp, newp);
        }

        if (make_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) < 0) return -1;
        if (rename(cfg->log_path, newp) < 0) {
            return -1;
        }
    } else {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    return 0;
}

static int rotate_by_copytruncate(const struct config *cfg) {
    struct stat st;
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (stat(cfg->log_path, &st) < 0) {
        return -1;
    }

    if (cfg->backups > 0) {
        if (make_rotated_path(cfg->log_path, cfg->backups, oldp, sizeof(oldp)) == 0) {
            unlink(oldp);
        }

        for (int i = cfg->backups - 1; i >= 1; --i) {
            if (make_rotated_path(cfg->log_path, i, oldp, sizeof(oldp)) < 0) return -1;
            if (make_rotated_path(cfg->log_path, i + 1, newp, sizeof(newp)) < 0) return -1;
            rename(oldp, newp);
        }

        if (make_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) < 0) return -1;

        if (copy_file_contents(cfg->log_path, newp, st.st_mode & 0777) < 0) {
            return -1;
        }

        if (truncate_file(cfg->log_path) < 0) {
            return -1;
        }
    } else {
        if (truncate_file(cfg->log_path) < 0) {
            return -1;
        }
    }

    return 0;
}

static int maybe_rotate(const struct config *cfg) {
    struct stat st;

    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        return 0;
    }

    if (st.st_size < cfg->max_size) {
        return 0;
    }

    if (cfg->copytruncate) {
        return rotate_by_copytruncate(cfg);
    } else {
        return rotate_by_rename(cfg);
    }
}

int main(int argc, char **argv) {
    struct config cfg;
    int opt;

    memset(&cfg, 0, sizeof(cfg));
    cfg.backups = 5;
    cfg.interval_sec = 5;
    cfg.max_size = 0;
    cfg.daemonize = false;
    cfg.copytruncate = false;

    while ((opt = getopt(argc, argv, "f:s:n:i:dt")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "Path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_offt(optarg, &cfg.max_size) < 0 || cfg.max_size <= 0) {
                    fprintf(stderr, "Invalid size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.backups) < 0) {
                    fprintf(stderr, "Invalid backup count\n");
                    return 1;
                }
                break;
            case 'i':
                {
                    int tmp;
                    if (parse_int(optarg, &tmp) < 0 || tmp <= 0) {
                        fprintf(stderr, "Invalid interval\n");
                        return 1;
                    }
                    cfg.interval_sec = (unsigned int)tmp;
                }
                break;
            case 'd':
                cfg.daemonize = true;
                break;
            case 't':
                cfg.copytruncate = true;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0' || cfg.max_size <= 0) {
        usage(argv[0]);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    signal(SIGHUP, handle_signal);

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            return 1;
        }
    }

    while (g_running) {
        (void)maybe_rotate(&cfg);

        unsigned int remaining = cfg.interval_sec;
        while (g_running && remaining > 0) {
            remaining = sleep(remaining);
            if (remaining == 0) break;
        }
    }

    return 0;
}
```

