## Code

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogd memlogd.c
 *
 * Usage:
 *   ./memlogd /path/to/logfile max_size_bytes rotations interval_seconds [--daemon]
 *
 * Example:
 *   ./memlogd /var/log/myapp.log 1048576 5 2 --daemon
 *
 * Notes:
 * - Uses polling to avoid inotify complexity and memory overhead.
 * - Keeps memory use constant and very small.
 * - Avoids dynamic allocation entirely.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 1000

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, int suffix) {
    int n;
    if (suffix <= 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    }

    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const char *path, int rotations, mode_t mode, uid_t uid, gid_t gid) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (rotations < 1) return 0;
    if (rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    /* Remove oldest if present */
    if (safe_snprintf_path(oldp, sizeof(oldp), path, rotations) < 0) return -1;
    (void)unlink(oldp);

    /* Shift N-1 down to 1 upward */
    for (int i = rotations - 1; i >= 1; --i) {
        if (safe_snprintf_path(oldp, sizeof(oldp), path, i) < 0) return -1;
        if (safe_snprintf_path(newp, sizeof(newp), path, i + 1) < 0) return -1;

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Rotate current log to .1 */
    if (safe_snprintf_path(newp, sizeof(newp), path, 1) < 0) return -1;
    if (rename(path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate active log */
    int fd = open(path, O_CREAT | O_WRONLY | O_APPEND, mode);
    if (fd < 0) return -1;

    (void)fchown(fd, uid, gid); /* Ignore failure if not privileged */
    close(fd);
    return 0;
}

static int get_file_info(const char *path, off_t *size_out, mode_t *mode_out, uid_t *uid_out, gid_t *gid_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;

    if (size_out) *size_out = st.st_size;
    if (mode_out) *mode_out = st.st_mode & 0777;
    if (uid_out) *uid_out = st.st_uid;
    if (gid_out) *gid_out = st.st_gid;
    return 0;
}

static void sleep_interval(unsigned interval_seconds) {
    struct timespec req, rem;
    req.tv_sec = interval_seconds;
    req.tv_nsec = 0;

    while (g_running && nanosleep(&req, &rem) < 0) {
        if (errno == EINTR) {
            req = rem;
        } else {
            break;
        }
    }
}

static int parse_int(const char *s, long *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 6) {
        fprintf(stderr,
                "Usage: %s /path/to/logfile max_size_bytes rotations interval_seconds [--daemon]\n",
                argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    long max_size_l = 0;
    long rotations_l = 0;
    long interval_l = 0;
    int run_as_daemon = 0;

    if (parse_int(argv[2], &max_size_l) < 0 || max_size_l <= 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &rotations_l) < 0 || rotations_l < 1 || rotations_l > MAX_ROTATIONS) {
        fprintf(stderr, "Invalid rotations (1-%d)\n", MAX_ROTATIONS);
        return 1;
    }

    if (parse_int(argv[4], &interval_l) < 0 || interval_l < 1) {
        fprintf(stderr, "Invalid interval_seconds\n");
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "--daemon") != 0) {
            fprintf(stderr, "Unknown option: %s\n", argv[5]);
            return 1;
        }
        run_as_daemon = 1;
    }

    if (strlen(log_path) >= PATH_MAX - 16) {
        fprintf(stderr, "Log path too long\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(log_path, 0644) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (run_as_daemon) {
        if (daemonize_process() < 0) {
            return 1;
        }
    }

    const off_t max_size = (off_t)max_size_l;
    const int rotations = (int)rotations_l;
    const unsigned interval_seconds = (unsigned)interval_l;

    while (g_running) {
        off_t size = 0;
        mode_t mode = 0644;
        uid_t uid = getuid();
        gid_t gid = getgid();

        if (get_file_info(log_path, &size, &mode, &uid, &gid) == 0) {
            if (size >= max_size) {
                if (rotate_logs(log_path, rotations, mode, uid, gid) < 0) {
                    /* In daemon mode stderr may be /dev/null; fail softly */
                }
            }
        } else {
            /* If the file disappeared, recreate it */
            (void)ensure_log_exists(log_path, 0644);
        }

        sleep_interval(interval_seconds);
    }

    return 0;
}
```

