## Code

```c
/*
 * memlogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Example:
 *   ./memlogrotate /var/log/myapp.log 10485760 5 2
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = polling interval in seconds
 *
 * Notes:
 * - Rotation pattern:
 *     logfile     -> logfile.1
 *     logfile.1   -> logfile.2
 *     ...
 *     logfile.N-1 -> logfile.N
 * - The active file is recreated empty after rotation.
 * - Uses polling instead of inotify to keep implementation simple/predictable.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 1000

static volatile sig_atomic_t g_stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) != 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, unsigned index) {
    int n = snprintf(dst, dst_sz, "%s.%u", base, index);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_file_exists_with_mode(const char *path, mode_t mode, uid_t uid, gid_t gid) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) {
        return -1;
    }

    (void)fchown(fd, uid, gid);
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *log_path, unsigned keep_count) {
    if (keep_count == 0) {
        int fd = open(log_path, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        return close(fd);
    }

    struct stat st;
    mode_t mode = 0644;
    uid_t uid = (uid_t)-1;
    gid_t gid = (gid_t)-1;

    if (stat(log_path, &st) == 0) {
        mode = st.st_mode & 0777;
        uid = st.st_uid;
        gid = st.st_gid;
    }

    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (safe_snprintf_path(old_path, sizeof(old_path), log_path, keep_count) != 0) {
        return -1;
    }

    (void)unlink(old_path);

    for (unsigned i = keep_count; i > 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), log_path, i - 1) != 0) {
            return -1;
        }
        if (safe_snprintf_path(new_path, sizeof(new_path), log_path, i) != 0) {
            return -1;
        }

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (safe_snprintf_path(new_path, sizeof(new_path), log_path, 1) != 0) {
        return -1;
    }

    if (rename(log_path, new_path) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    if (ensure_file_exists_with_mode(log_path, mode, uid, gid) != 0) {
        return -1;
    }

    return 0;
}

static int file_size_exceeds(const char *path, off_t max_size, bool *exceeds) {
    struct stat st;
    if (stat(path, &st) != 0) {
        if (errno == ENOENT) {
            *exceeds = false;
            return 0;
        }
        return -1;
    }

    *exceeds = (st.st_size >= max_size);
    return 0;
}

static void usage(const char *prog) {
    const char *name = prog ? prog : "memlogrotate";
    dprintf(STDERR_FILENO,
            "Usage: %s <log_path> <max_size_bytes> <keep_count> <poll_seconds> [--daemon]\n",
            name);
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned *out) {
    uint64_t v;
    if (parse_u64(s, &v) != 0 || v > UINT_MAX) return -1;
    *out = (unsigned)v;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 6) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    uint64_t max_size_u64 = 0;
    unsigned keep_count = 0;
    unsigned poll_seconds = 0;
    bool run_as_daemon = false;

    if (parse_u64(argv[2], &max_size_u64) != 0 || max_size_u64 == 0) {
        dprintf(STDERR_FILENO, "Invalid max_size_bytes\n");
        return 1;
    }

    if (parse_u32(argv[3], &keep_count) != 0 || keep_count > MAX_ROTATIONS) {
        dprintf(STDERR_FILENO, "Invalid keep_count (max %d)\n", MAX_ROTATIONS);
        return 1;
    }

    if (parse_u32(argv[4], &poll_seconds) != 0 || poll_seconds == 0) {
        dprintf(STDERR_FILENO, "Invalid poll_seconds\n");
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "--daemon") != 0) {
            dprintf(STDERR_FILENO, "Unknown option: %s\n", argv[5]);
            return 1;
        }
        run_as_daemon = true;
    }

    if (strlen(log_path) >= PATH_MAX - 16) {
        dprintf(STDERR_FILENO, "log_path too long\n");
        return 1;
    }

    if (install_signal_handlers() != 0) {
        dprintf(STDERR_FILENO, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (run_as_daemon) {
        if (daemonize_process() != 0) {
            dprintf(STDERR_FILENO, "Failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    const off_t max_size = (off_t)max_size_u64;

    while (!g_stop) {
        bool exceeds = false;

        if (file_size_exceeds(log_path, max_size, &exceeds) != 0) {
            sleep(poll_seconds);
            continue;
        }

        if (exceeds) {
            (void)rotate_logs(log_path, keep_count);
        }

        sleep(poll_seconds);
    }

    return 0;
}
