## Code: `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 1
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_log_stderr(const char *fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n > 0) {
        size_t len = (size_t)n;
        if (len > sizeof(buf)) len = sizeof(buf);
        (void)write(STDERR_FILENO, buf, len);
    }
}

typedef struct {
    char log_path[PATH_MAX];
    uint64_t max_size;
    int max_rotations;
    int check_interval_sec;
    int daemonize;
} config_t;

static int parse_u64(const char *s, uint64_t *out) {
    if (!s || !*s) return -1;
    errno = 0;
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    if (!s || !*s) return -1;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval_sec] [-d]\n"
        "  -f <logfile>      Path to log file\n"
        "  -s <max_bytes>    Rotate when file size >= max_bytes (default: %llu)\n"
        "  -n <rotations>    Number of rotated files to keep (default: %d)\n"
        "  -i <seconds>      Poll interval seconds (default: %d)\n"
        "  -d                Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_ROTATIONS,
        DEFAULT_CHECK_INTERVAL_SEC
    );
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations <= 0) {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
        return ensure_log_exists(cfg->log_path);
    }

    if (build_rotated_path(cfg->log_path, cfg->max_rotations, oldp, sizeof(oldp)) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    if (unlink(oldp) < 0 && errno != ENOENT) {
        return -1;
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(cfg->log_path, i, oldp, sizeof(oldp)) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (build_rotated_path(cfg->log_path, i + 1, newp, sizeof(newp)) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    if (build_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    return ensure_log_exists(cfg->log_path);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int should_rotate(const config_t *cfg, bool *rotate) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            if (ensure_log_exists(cfg->log_path) < 0) return -1;
            *rotate = false;
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    *rotate = ((uint64_t)st.st_size >= cfg->max_size);
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.daemonize = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "Log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg.max_size) < 0 || cfg.max_size == 0) {
                    fprintf(stderr, "Invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) < 0) {
                    fprintf(stderr, "Invalid rotation count\n");
                    return 1;
                }
                break;
            case 'i':
                if (parse_int(optarg, &cfg.check_interval_sec) < 0 || cfg.check_interval_sec <= 0) {
                    fprintf(stderr, "Invalid interval\n");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return (opt == 'h') ? 0 : 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (!g_stop) {
        bool rotate = false;
        if (should_rotate(&cfg, &rotate) < 0) {
            safe_log_stderr("Error checking log file '%s': %s\n",
                            cfg.log_path, strerror(errno));
        } else if (rotate) {
            if (rotate_logs(&cfg) < 0) {
                safe_log_stderr("Error rotating log file '%s': %s\n",
                                cfg.log_path, strerror(errno));
            }
        }

        struct timespec ts;
        ts.tv_sec = cfg.check_interval_sec;
        ts.tv_nsec = 0;

        while (!g_stop && nanosleep(&ts, &ts) < 0) {
            if (errno != EINTR) break;
        }
    }

    return 0;
}
