Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits. It avoids dynamic allocation in the hot path, uses fixed-size buffers, and rotates based on file size.

## Features
- Monitors one log file
- Rotates when size exceeds a threshold
- Keeps a fixed number of old logs
- Uses `rename()` for rotation
- Sleeps between checks
- Minimal heap usage

## Code

```c
/*
 * tinylogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o tinylogrotate tinylogrotate.c
 *
 * Run:
 *   ./tinylogrotate /var/log/myapp.log 1048576 5 2
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = polling interval in seconds
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <limits.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    unsigned long long v;

    if (!s || !*s) return -1;
    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;

    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    if (!s || !*s) return -1;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > INT_MAX) return -1;

    *out = (int)v;
    return 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) return -1;
    return 0;
}

static int rotate_logs(const char *path, int keep_count) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    int i;

    if (keep_count < 1) {
        /* No backups: just truncate by renaming to .1 then removing */
        if (build_rotated_path(new_path, sizeof(new_path), path, 1) != 0) return -1;
        (void)unlink(new_path);
        if (rename(path, new_path) != 0) {
            if (errno != ENOENT) return -1;
        }
        (void)unlink(new_path);
        return 0;
    }

    /* Remove oldest */
    if (build_rotated_path(old_path, sizeof(old_path), path, keep_count) != 0) return -1;
    (void)unlink(old_path);

    /* Shift N-1 ... 1 upward */
    for (i = keep_count - 1; i >= 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), path, i) != 0) return -1;
        if (build_rotated_path(new_path, sizeof(new_path), path, i + 1) != 0) return -1;

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) return -1;
        }
    }

    /* Move current log to .1 */
    if (build_rotated_path(new_path, sizeof(new_path), path, 1) != 0) return -1;
    if (rename(path, new_path) != 0) {
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static int recreate_empty_log(const char *path) {
    FILE *f = fopen(path, "ab");
    if (!f) return -1;
    if (fclose(f) != 0) return -1;
    return 0;
}

static void daemon_loop(const char *path, uint64_t max_size, int keep_count, int interval_sec) {
    while (g_running) {
        off_t size = 0;

        if (get_file_size(path, &size) == 0) {
            if ((uint64_t)size >= max_size) {
                if (rotate_logs(path, keep_count) == 0) {
                    (void)recreate_empty_log(path);
                }
            }
        } else {
            /* If file does not exist, create it */
            if (errno == ENOENT) {
                (void)recreate_empty_log(path);
            }
        }

        for (int slept = 0; g_running && slept < interval_sec; ++slept) {
            sleep(1);
        }
    }
}

int main(int argc, char **argv) {
    uint64_t max_size;
    int keep_count;
    int interval_sec;

    if (argc != 5) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <keep_count> <interval_sec>\n", argv[0]);
        return 1;
    }

    if (strlen(argv[1]) >= PATH_MAX) {
        fprintf(stderr, "Error: log path too long\n");
        return 1;
    }

    if (parse_u64(argv[2], &max_size) != 0 || max_size == 0) {
        fprintf(stderr, "Error: invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &keep_count) != 0) {
        fprintf(stderr, "Error: invalid keep_count\n");
        return 1;
    }

    if (parse_int(argv[4], &interval_sec) != 0 || interval_sec < 1) {
        fprintf(stderr, "Error: invalid interval_sec\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    daemon_loop(argv[1], max_size, keep_count, interval_sec);
    return 0;
}
```

