```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_MS 1000
#define DEFAULT_MAX_FILES 5
#define DEFAULT_MAX_SIZE (10ULL * 1024ULL * 1024ULL)
#define DEFAULT_MEM_LIMIT_MB 16

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int set_memory_limit_mb(unsigned long mb) {
    struct rlimit rl;
    rl.rlim_cur = (rlim_t)mb * 1024UL * 1024UL;
    rl.rlim_max = (rlim_t)mb * 1024UL * 1024UL;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > 2) close(fd);

    return 0;
}

static int ensure_file_exists(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, unsigned index) {
    int n = snprintf(dst, dst_sz, "%s.%u", base, index);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, unsigned max_files) {
    if (max_files == 0) {
        if (unlink(path) != 0 && errno != ENOENT) return -1;
        return 0;
    }

    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (build_rotated_path(oldp, sizeof(oldp), path, max_files) != 0) return -1;
    if (unlink(oldp) != 0 && errno != ENOENT) return -1;

    for (unsigned i = max_files; i > 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i - 1) != 0) return -1;
        if (build_rotated_path(newp, sizeof(newp), path, i) != 0) return -1;

        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) return -1;
        }
    }

    if (build_rotated_path(newp, sizeof(newp), path, 1) != 0) return -1;
    if (rename(path, newp) != 0) {
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static int recreate_log_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int check_and_rotate(const char *path, off_t max_size, unsigned max_files, mode_t mode) {
    struct stat st;
    if (stat(path, &st) != 0) {
        if (errno == ENOENT) {
            return ensure_file_exists(path, mode);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size < max_size) {
        return 0;
    }

    if (rotate_logs(path, max_files) != 0) {
        return -1;
    }

    if (recreate_log_file(path, mode) != 0) {
        return -1;
    }

    return 0;
}

static unsigned long parse_ulong(const char *s, const char *name) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        fprintf(stderr, "invalid %s: %s\n", name, s);
        exit(2);
    }
    return v;
}

static unsigned long long parse_ull(const char *s, const char *name) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        fprintf(stderr, "invalid %s: %s\n", name, s);
        exit(2);
    }
    return v;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n max_files] [-p poll_ms] [-m mem_mb] [-d]\n"
        "  -f logfile    Path to log file\n"
        "  -s max_bytes  Rotate when file reaches this size (default: %llu)\n"
        "  -n max_files  Number of rotated files to keep (default: %u)\n"
        "  -p poll_ms    Poll interval in milliseconds (default: %u)\n"
        "  -m mem_mb     Address-space limit in MB (default: %u)\n"
        "  -d            Daemonize\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_MAX_FILES,
        DEFAULT_POLL_MS,
        DEFAULT_MEM_LIMIT_MB
    );
}

int main(int argc, char **argv) {
    const char *logfile = NULL;
    unsigned long long max_size = DEFAULT_MAX_SIZE;
    unsigned long max_files = DEFAULT_MAX_FILES;
    unsigned long poll_ms = DEFAULT_POLL_MS;
    unsigned long mem_mb = DEFAULT_MEM_LIMIT_MB;
    bool daemon_mode = false;
    mode_t create_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:m:d")) != -1) {
        switch (opt) {
            case 'f':
                logfile = optarg;
                break;
            case 's':
                max_size = parse_ull(optarg, "max_bytes");
                break;
            case 'n':
                max_files = parse_ulong(optarg, "max_files");
                break;
            case 'p':
                poll_ms = parse_ulong(optarg, "poll_ms");
                break;
            case 'm':
                mem_mb = parse_ulong(optarg, "mem_mb");
                break;
            case 'd':
                daemon_mode = true;
                break;
            default:
                usage(argv[0]);
                return 2;
        }
    }

    if (!logfile) {
        usage(argv[0]);
        return 2;
    }

    if (strlen(logfile) >= PATH_MAX - 32) {
        log_stderr("log path too long");
        return 2;
    }

    if (set_memory_limit_mb(mem_mb) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (daemon_mode) {
        if (daemonize_process() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (ensure_file_exists(logfile, create_mode) != 0) {
        perror("ensure_file_exists");
        return 1;
    }

    struct timespec ts;
    ts.tv_sec = poll_ms / 1000;
    ts.tv_nsec = (long)(poll_ms % 1000) * 1000000L;

    while (!g_stop) {
        if (check_and_rotate(logfile, (off_t)max_size, (unsigned)max_files, create_mode) != 0) {
            /* Keep running on transient errors */
        }

        while (!g_stop && nanosleep(&ts, &ts) != 0) {
            if (errno != EINTR) break;
        }

        ts.tv_sec = poll_ms / 1000;
        ts.tv_nsec = (long)(poll_ms % 1000) * 1000000L;
    }

    return 0;
}
