## Code

```c
/*
 * memlogrotate.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c99 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Usage:
 *   ./memlogrotate /var/log/myapp.log 10485760 5 2
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *
 * Notes:
 * - Uses polling, not inotify, for simplicity and low memory predictability.
 * - No dynamic allocation.
 * - Path length is limited by PATH_MAX.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 1000

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    unsigned long long v;

    if (s == NULL || *s == '\0' || out == NULL) {
        return -1;
    }

    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }

    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    if (s == NULL || *s == '\0' || out == NULL) {
        return -1;
    }

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    if (v < 0 || v > 2147483647L) {
        return -1;
    }

    *out = (int)v;
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dstsz, const char *base, int suffix) {
    int n;
    if (suffix <= 0) {
        n = snprintf(dst, dstsz, "%s", base);
    } else {
        n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    }
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const char *path, int keep, mode_t mode, uid_t uid, gid_t gid) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int i;

    if (keep < 1 || keep > MAX_ROTATIONS) {
        return -1;
    }

    /* Remove the oldest */
    if (safe_snprintf_path(oldp, sizeof(oldp), path, keep) != 0) {
        return -1;
    }
    (void)unlink(oldp);

    /* Shift: N-1 -> N, ..., 1 -> 2 */
    for (i = keep - 1; i >= 1; --i) {
        if (safe_snprintf_path(oldp, sizeof(oldp), path, i) != 0) {
            return -1;
        }
        if (safe_snprintf_path(newp, sizeof(newp), path, i + 1) != 0) {
            return -1;
        }
        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Current -> .1 */
    if (safe_snprintf_path(newp, sizeof(newp), path, 1) != 0) {
        return -1;
    }
    if (rename(path, newp) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate current log */
    {
        int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
        if (fd < 0) {
            return -1;
        }

        /* Best effort ownership restore */
        (void)fchown(fd, uid, gid);
        close(fd);
    }

    return 0;
}

static int daemonize(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    {
        int fd = open("/dev/null", O_RDWR);
        if (fd >= 0) {
            (void)dup2(fd, STDIN_FILENO);
            (void)dup2(fd, STDOUT_FILENO);
            (void)dup2(fd, STDERR_FILENO);
            if (fd > STDERR_FILENO) {
                close(fd);
            }
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    const char *path;
    uint64_t max_size;
    int keep;
    int interval_sec;
    struct stat st;
    mode_t mode = 0644;
    uid_t uid = 0;
    gid_t gid = 0;
    struct sigaction sa;

    if (argc != 5) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <keep_count> <poll_interval_sec>\n", argv[0]);
        return 1;
    }

    path = argv[1];

    if (strlen(path) >= PATH_MAX) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }

    if (parse_u64(argv[2], &max_size) != 0 || max_size == 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &keep) != 0 || keep < 1 || keep > MAX_ROTATIONS) {
        fprintf(stderr, "Invalid keep_count\n");
        return 1;
    }

    if (parse_int(argv[4], &interval_sec) != 0 || interval_sec < 1) {
        fprintf(stderr, "Invalid poll_interval_sec\n");
        return 1;
    }

    if (stat(path, &st) == 0) {
        mode = st.st_mode & 0777;
        uid = st.st_uid;
        gid = st.st_gid;
    }

    if (ensure_log_exists(path, mode) != 0) {
        perror("ensure_log_exists");
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    (void)sigaction(SIGINT, &sa, NULL);
    (void)sigaction(SIGTERM, &sa, NULL);
    (void)sigaction(SIGHUP, &sa, NULL);

    if (daemonize() != 0) {
        perror("daemonize");
        return 1;
    }

    while (g_running) {
        if (stat(path, &st) == 0) {
            if ((uint64_t)st.st_size >= max_size) {
                mode_t cur_mode = st.st_mode & 0777;
                uid_t cur_uid = st.st_uid;
                gid_t cur_gid = st.st_gid;

                if (rotate_logs(path, keep, cur_mode, cur_uid, cur_gid) != 0) {
                    /* Sleep briefly on error to avoid tight loop */
                    sleep((unsigned int)interval_sec);
                }
            }
        } else {
            /* Recreate if missing */
            (void)ensure_log_exists(path, mode);
        }

        sleep((unsigned int)interval_sec);
    }

    return 0;
}
