/*
 * memlogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogrotate memlogrotate.c
 *
 * Example:
 *   ./memlogrotate /var/log/myapp.log 10485760 5 5
 *   Arguments:
 *     argv[1] = log file path
 *     argv[2] = max size in bytes before rotation
 *     argv[3] = number of rotated files to keep
 *     argv[4] = check interval in seconds
 *
 * Notes:
 * - Uses fixed-size path buffers.
 * - Avoids heap allocation.
 * - Rotation scheme:
 *     logfile.(keep-1) deleted
 *     logfile.(keep-2) -> logfile.(keep-1)
 *     ...
 *     logfile.1 -> logfile.2
 *     logfile -> logfile.1
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_KEEP 1000
#define PIDFILE_MODE 0644

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_force_rotate = 0;

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_force_rotate = 1;
    }
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int make_rotated_path(char *buf, size_t bufsz, const char *base, unsigned idx) {
    int n = snprintf(buf, bufsz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= bufsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *logpath, unsigned keep) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (keep == 0) {
        return 0;
    }

    if (make_rotated_path(oldp, sizeof(oldp), logpath, keep) == 0) {
        (void)unlink(oldp);
    }

    for (unsigned i = keep; i > 1; --i) {
        if (make_rotated_path(oldp, sizeof(oldp), logpath, i - 1) < 0) {
            return -1;
        }
        if (make_rotated_path(newp, sizeof(newp), logpath, i) < 0) {
            return -1;
        }
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (make_rotated_path(newp, sizeof(newp), logpath, 1) < 0) {
        return -1;
    }

    if (rename(logpath, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return 0;
}

static int ensure_log_exists(const char *logpath) {
    int fd = open(logpath, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int should_rotate(const char *logpath, off_t max_size, bool force) {
    struct stat st;

    if (force) return 1;

    if (stat(logpath, &st) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    return (st.st_size >= max_size) ? 1 : 0;
}

static void sleep_interruptible(unsigned seconds) {
    struct timespec req, rem;
    req.tv_sec = seconds;
    req.tv_nsec = 0;

    while (!g_terminate) {
        if (nanosleep(&req, &rem) == 0) {
            break;
        }
        if (errno == EINTR) {
            if (g_force_rotate) {
                break;
            }
            req = rem;
            continue;
        }
        break;
    }
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned *out) {
    uint64_t v;
    if (parse_u64(s, &v) < 0) return -1;
    if (v > UINT_MAX) return -1;
    *out = (unsigned)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <logpath> <max_bytes> <keep_count> <interval_sec>\n", prog);
}

int main(int argc, char **argv) {
    char logpath[PATH_MAX];
    uint64_t max_bytes_u64;
    unsigned keep;
    unsigned interval_sec;
    off_t max_size;

    if (argc != 5) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(argv[1]) >= sizeof(logpath)) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }
    memcpy(logpath, argv[1], strlen(argv[1]) + 1);

    if (parse_u64(argv[2], &max_bytes_u64) < 0 || max_bytes_u64 == 0) {
        fprintf(stderr, "invalid max_bytes\n");
        return 1;
    }

    if (parse_u32(argv[3], &keep) < 0 || keep > MAX_KEEP) {
        fprintf(stderr, "invalid keep_count\n");
        return 1;
    }

    if (parse_u32(argv[4], &interval_sec) < 0 || interval_sec == 0) {
        fprintf(stderr, "invalid interval_sec\n");
        return 1;
    }

    if (max_bytes_u64 > (uint64_t)LLONG_MAX) {
        fprintf(stderr, "max_bytes too large\n");
        return 1;
    }
    max_size = (off_t)max_bytes_u64;

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (daemonize_self() < 0) {
        perror("daemonize");
        return 1;
    }

    for (;;) {
        if (g_terminate) {
            break;
        }

        if (ensure_log_exists(logpath) < 0) {
            sleep_interruptible(interval_sec);
            continue;
        }

        int sr = should_rotate(logpath, max_size, g_force_rotate ? true : false);
        if (sr < 0) {
            g_force_rotate = 0;
            sleep_interruptible(interval_sec);
            continue;
        }

        if (sr > 0) {
            (void)rotate_logs(logpath, keep);
            (void)ensure_log_exists(logpath);
        }

        g_force_rotate = 0;
        sleep_interruptible(interval_sec);
    }

    return 0;
}
```

