Below is a compact, memory-conscious log rotation daemon in C designed for strict memory limits. It avoids dynamic allocation in the hot path, uses fixed-size buffers, and rotates logs based on file size.

## Features
- Monitors one log file
- Rotates when file exceeds a size threshold
- Keeps a fixed number of rotated files
- Uses `rename()`-based rotation
- Minimal heap usage
- Simple polling loop
- Optional daemonization

## Code

```c
/*
 * memlogrotate.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogrotate memlogrotate.c
 *
 * Usage:
 *   ./memlogrotate <logfile> <max_bytes> <max_rotations> <poll_seconds> [--daemon]
 *
 * Example:
 *   ./memlogrotate /var/log/myapp.log 1048576 5 2 --daemon
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>

#define PATH_BUF 512

static volatile sig_atomic_t g_stop = 0;

static void handle_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int setup_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int safe_snprintf_path(char *buf, size_t buflen, const char *base, int suffix) {
    int n;
    if (suffix <= 0) {
        n = snprintf(buf, buflen, "%s", base);
    } else {
        n = snprintf(buf, buflen, "%s.%d", base, suffix);
    }
    if (n < 0 || (size_t)n >= buflen) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *logfile, int max_rotations) {
    char oldpath[PATH_BUF];
    char newpath[PATH_BUF];

    if (max_rotations < 1) return 0;

    /* Delete oldest if it exists: logfile.N */
    if (safe_snprintf_path(oldpath, sizeof(oldpath), logfile, max_rotations) < 0)
        return -1;
    (void)unlink(oldpath);

    /* Shift logfile.(N-1) -> logfile.N ... logfile.1 -> logfile.2 */
    for (int i = max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf_path(oldpath, sizeof(oldpath), logfile, i) < 0)
            return -1;
        if (safe_snprintf_path(newpath, sizeof(newpath), logfile, i + 1) < 0)
            return -1;

        if (rename(oldpath, newpath) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* logfile -> logfile.1 */
    if (safe_snprintf_path(newpath, sizeof(newpath), logfile, 1) < 0)
        return -1;

    if (rename(logfile, newpath) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty logfile */
    int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 5 || argc > 6) {
        fprintf(stderr,
                "Usage: %s <logfile> <max_bytes> <max_rotations> <poll_seconds> [--daemon]\n",
                argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    uint64_t max_bytes = 0;
    int max_rotations = 0;
    int poll_seconds = 0;
    int run_as_daemon = 0;

    if (strlen(logfile) >= PATH_BUF - 16) {
        fprintf(stderr, "Log path too long\n");
        return 1;
    }

    if (parse_u64(argv[2], &max_bytes) < 0 || max_bytes == 0) {
        fprintf(stderr, "Invalid max_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &max_rotations) < 0 || max_rotations < 1) {
        fprintf(stderr, "Invalid max_rotations\n");
        return 1;
    }

    if (parse_int(argv[4], &poll_seconds) < 0 || poll_seconds < 1) {
        fprintf(stderr, "Invalid poll_seconds\n");
        return 1;
    }

    if (argc == 6) {
        if (strcmp(argv[5], "--daemon") != 0) {
            fprintf(stderr, "Unknown option: %s\n", argv[5]);
            return 1;
        }
        run_as_daemon = 1;
    }

    if (setup_signals() < 0) {
        perror("setup_signals");
        return 1;
    }

    if (run_as_daemon) {
        if (daemonize_self() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    /* Ensure log file exists */
    {
        int fd = open(logfile, O_WRONLY | O_CREAT, 0644);
        if (fd < 0) {
            perror("open logfile");
            return 1;
        }
        close(fd);
    }

    while (!g_stop) {
        off_t size = 0;
        if (get_file_size(logfile, &size) == 0) {
            if ((uint64_t)size >= max_bytes) {
                if (rotate_logs(logfile, max_rotations) < 0) {
                    /* In daemon mode this goes to /dev/null unless redirected */
                    perror("rotate_logs");
                }
            }
        } else {
            perror("stat");
        }

        for (int i = 0; i < poll_seconds && !g_stop; ++i) {
            sleep(1);
        }
    }

    return 0;
}
```

