# Source: `memlogd.c`

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Features:
 * - Fixed maximum number of files
 * - Fixed maximum path length
 * - No heap allocation in steady-state
 * - Poll-based size checking
 * - Rotate when file exceeds configured size
 * - Keep N rotated copies: logfile, logfile.1, logfile.2, ...
 * - Optional daemonization
 *
 * Limitations:
 * - No compression
 * - No config reload
 * - No recursive discovery
 * - No inotify/kqueue; simple polling only
 * - Assumes single-process ownership of rotation policy
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -i 5 -r 5 -s 10485760 /var/log/app.log /var/log/worker.log
 *
 * Daemon mode:
 *   ./memlogd -d -p /var/run/memlogd.pid -i 5 -r 5 -s 10485760 /var/log/app.log
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/file.h>
#include <time.h>
#include <unistd.h>

/* ---------------- Strict memory limits ---------------- */

#define MAX_LOG_FILES   32
#define MAX_PATH_LEN    512
#define MAX_PIDFILE_LEN 512
#define MAX_ROTATIONS   32

/* ---------------- Defaults ---------------- */

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS    5
#define DEFAULT_MAX_SIZE     (10 * 1024 * 1024ULL)

/* ---------------- Globals ---------------- */

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

/* ---------------- Logging ---------------- */

static void log_msg(const char *level, const char *fmt, ...)
{
    va_list ap;
    char buf[512];
    int n;
    time_t now;
    struct tm tmv;

    now = time(NULL);
    localtime_r(&now, &tmv);

    n = snprintf(buf, sizeof(buf),
                 "%04d-%02d-%02d %02d:%02d:%02d [%s] ",
                 tmv.tm_year + 1900,
                 tmv.tm_mon + 1,
                 tmv.tm_mday,
                 tmv.tm_hour,
                 tmv.tm_min,
                 tmv.tm_sec,
                 level);
    if (n < 0 || (size_t)n >= sizeof(buf)) {
        return;
    }

    va_start(ap, fmt);
    vsnprintf(buf + (size_t)n, sizeof(buf) - (size_t)n, fmt, ap);
    va_end(ap);

    dprintf(STDERR_FILENO, "%s\n", buf);
}

/* ---------------- Config ---------------- */

struct log_target {
    char path[MAX_PATH_LEN];
};

struct config {
    unsigned interval_sec;
    unsigned rotations;
    uint64_t max_size;
    bool daemonize;
    char pidfile[MAX_PIDFILE_LEN];
    bool use_pidfile;
    struct log_target targets[MAX_LOG_FILES];
    size_t target_count;
};

/* ---------------- Signal handling ---------------- */

static void handle_signal(int signo)
{
    if (signo == SIGTERM || signo == SIGINT) {
        g_terminate = 1;
    } else if (signo == SIGHUP) {
        g_reload = 1;
    }
}

static int setup_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;

    return 0;
}

/* ---------------- Utility ---------------- */

static int safe_strcpy(char *dst, size_t dstsz, const char *src)
{
    size_t len;
    if (!dst || !src || dstsz == 0) return -1;
    len = strnlen(src, dstsz);
    if (len >= dstsz) return -1;
    memcpy(dst, src, len + 1);
    return 0;
}

static int build_rotated_path(char *out, size_t outsz, const char *base, unsigned idx)
{
    int n = snprintf(out, outsz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= outsz) return -1;
    return 0;
}

/* ---------------- PID file ---------------- */

static int write_pidfile(const char *path)
{
    int fd;
    char buf[64];
    int n;

    fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        log_msg("ERROR", "open pidfile '%s' failed: %s", path, strerror(errno));
        return -1;
    }

    if (flock(fd, LOCK_EX | LOCK_NB) < 0) {
        log_msg("ERROR", "lock pidfile '%s' failed: %s", path, strerror(errno));
        close(fd);
        return -1;
    }

    if (ftruncate(fd, 0) < 0) {
        log_msg("ERROR", "truncate pidfile '%s' failed: %s", path, strerror(errno));
        close(fd);
        return -1;
    }

    n = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (n < 0 || (size_t)n >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)n) != n) {
        log_msg("ERROR", "write pidfile '%s' failed: %s", path, strerror(errno));
        close(fd);
        return -1;
    }

    /* Intentionally leak fd for lock lifetime in daemon process. */
    return 0;
}

/* ---------------- Rotation ---------------- */

static int rotate_one(const char *path, unsigned rotations)
{
    char oldp[MAX_PATH_LEN + 16];
    char newp[MAX_PATH_LEN + 16];
    unsigned i;

    if (rotations == 0) {
        /* Truncate in place if no backups requested */
        int fd = open(path, O_WRONLY | O_TRUNC);
        if (fd < 0) {
            log_msg("ERROR", "truncate '%s' failed: %s", path, strerror(errno));
            return -1;
        }
        close(fd);
        return 0;
    }

    /* Remove oldest */
    if (build_rotated_path(oldp, sizeof(oldp), path, rotations) == 0) {
        unlink(oldp);
    }

    /* Shift logfile.(n-1) -> logfile.n */
    for (i = rotations; i > 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i - 1) < 0 ||
            build_rotated_path(newp, sizeof(newp), path, i) < 0) {
            log_msg("ERROR", "path too long during rotation for '%s'", path);
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                log_msg("ERROR", "rename '%s' -> '%s' failed: %s",
                        oldp, newp, strerror(errno));
                return -1;
            }
        }
    }

    /* logfile -> logfile.1 */
    if (build_rotated_path(newp, sizeof(newp), path, 1) < 0) {
        log_msg("ERROR", "path too long during rotation for '%s'", path);
        return -1;
    }

    if (rename(path, newp) < 0) {
        if (errno == ENOENT) {
            return 0;
        }
        log_msg("ERROR", "rename '%s' -> '%s' failed: %s",
                path, newp, strerror(errno));
        return -1;
    }

    /*
     * Recreate empty log file so writers that reopen by pathname can continue.
     * Writers holding old fd will continue writing to rotated file until reopen.
     */
    {
        int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) {
            log_msg("ERROR", "recreate '%s' failed: %s", path, strerror(errno));
            return -1;
        }
        close(fd);
    }

    log_msg("INFO", "rotated '%s'", path);
    return 0;
}

static int check_and_rotate(const struct config *cfg, const struct log_target *t)
{
    struct stat st;

    if (stat(t->path, &st) < 0) {
        if (errno != ENOENT) {
            log_msg("ERROR", "stat '%s' failed: %s", t->path, strerror(errno));
        }
        return 0;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg("ERROR", "'%s' is not a regular file", t->path);
        return -1;
    }

    if ((uint64_t)st.st_size >= cfg->max_size) {
        return rotate_one(t->path, cfg->rotations);
    }

    return 0;
}

/* ---------------- Daemonization ---------------- */

static int daemonize_process(void)
{
    pid_t pid;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    /* Keep stderr for minimal diagnostics; redirect if desired. */

    return 0;
}

/* ---------------- Config parsing ---------------- */

static void usage(const char *prog)
{
    dprintf(STDERR_FILENO,
        "Usage: %s [-d] [-p pidfile] [-i interval_sec] [-r rotations] [-s max_bytes] log1 [log2 ...]\n",
        prog);
}

static int parse_u64(const char *s, uint64_t *out)
{
    char *end = NULL;
    unsigned long long v;

    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = (uint64_t)v;
    return 0;
}

static int parse_uint(const char *s, unsigned *out)
{
    uint64_t v;
    if (parse_u64(s, &v) < 0 || v > 0xffffffffULL) return -1;
    *out = (unsigned)v;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg)
{
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->max_size = DEFAULT_MAX_SIZE;

    while ((opt = getopt(argc, argv, "dp:i:r:s:")) != -1) {
        switch (opt) {
        case 'd':
            cfg->daemonize = true;
            break;
        case 'p':
            if (safe_strcpy(cfg->pidfile, sizeof(cfg->pidfile), optarg) < 0) {
                log_msg("ERROR", "pidfile path too long");
                return -1;
            }
            cfg->use_pidfile = true;
            break;
        case 'i':
            if (parse_uint(optarg, &cfg->interval_sec) < 0 || cfg->interval_sec == 0) {
                log_msg("ERROR", "invalid interval: %s", optarg);
                return -1;
            }
            break;
        case 'r':
            if (parse_uint(optarg, &cfg->rotations) < 0 || cfg->rotations > MAX_ROTATIONS) {
                log_msg("ERROR", "invalid rotations: %s (max %u)", optarg, MAX_ROTATIONS);
                return -1;
            }
            break;
        case 's':
            if (parse_u64(optarg, &cfg->max_size) < 0 || cfg->max_size == 0) {
                log_msg("ERROR", "invalid max size: %s", optarg);
                return -1;
            }
            break;
        default:
            usage(argv[0]);
            return -1;
        }
    }

    for (; optind < argc; ++optind) {
        if (cfg->target_count >= MAX_LOG_FILES) {
            log_msg("ERROR", "too many log files (max %u)", MAX_LOG_FILES);
            return -1;
        }
        if (safe_strcpy(cfg->targets[cfg->target_count].path,
                        sizeof(cfg->targets[cfg->target_count].path),
                        argv[optind]) < 0) {
            log_msg("ERROR", "log path too long: %s", argv[optind]);
            return -1;
        }
        cfg->target_count++;
    }

    if (cfg->target_count == 0) {
        usage(argv[0]);
        return -1;
    }

    return 0;
}

/* ---------------- Main loop ---------------- */

static void main_loop(const struct config *cfg)
{
    while (!g_terminate) {
        size_t i;

        for (i = 0; i < cfg->target_count; ++i) {
            check_and_rotate(cfg, &cfg->targets[i]);
        }

        if (g_reload) {
            /* Placeholder: config reload intentionally omitted in initial version */
            log_msg("INFO", "received SIGHUP (reload not implemented)");
            g_reload = 0;
        }

        for (unsigned slept = 0; slept < cfg->interval_sec && !g_terminate; ++slept) {
            sleep(1);
        }
    }
}

/* ---------------- Entry ---------------- */

int main(int argc, char **argv)
{
    struct config cfg;

    if (parse_args(argc, argv, &cfg) < 0) {
        return 1;
    }

    if (setup_signals() < 0) {
        log_msg("ERROR", "setup_signals failed: %s", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            log_msg("ERROR", "daemonize failed: %s", strerror(errno));
            return 1;
        }
    }

    if (cfg.use_pidfile) {
        if (write_pidfile(cfg.pidfile) < 0) {
            return 1;
        }
    }

    log_msg("INFO", "memlogd started: files=%zu interval=%u rotations=%u max_size=%llu",
            cfg.target_count,
            cfg.interval_sec,
            cfg.rotations,
            (unsigned long long)cfg.max_size);

    main_loop(&cfg);

    log_msg("INFO", "memlogd exiting");
    return 0;
}
