Below is a compact initial implementation of a **memory-constrained log rotation daemon** in **C** for Linux/Unix-like systems.

It is designed with these goals:

- **Strict memory behavior**
  - no unbounded allocations
  - fixed-size buffers
  - no dynamic data structures in steady state
- **Daemon-like loop**
  - periodically checks a log file
  - rotates when size threshold is exceeded
- **Simple rotation policy**
  - `log -> log.1`, `log.1 -> log.2`, etc.
- **Low runtime footprint**
- **Defensive error handling**

---

## Features

- Monitors a single log file
- Rotates when file size exceeds configured max size
- Keeps a fixed number of rotated files
- Uses only stack/fixed buffers
- Optional foreground mode for testing
- Handles `SIGTERM` / `SIGINT` cleanly

---

## Initial implementation

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -pedantic -std=c11 -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 5
 *
 * Notes:
 * - Rotates when file size >= max_size
 * - Keeps N rotated files:
 *     logfile.1 ... logfile.N
 * - Avoids heap allocation in steady state
 * - Uses fixed-size path buffers
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS    5
#define DEFAULT_MAX_SIZE     (10 * 1024 * 1024ULL)
#define LOG_PREFIX           "memlogd: "

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    uint64_t max_size;
    unsigned int rotations;
    unsigned int interval_sec;
    int foreground;
};

/* Minimal stderr logger to avoid extra memory use */
static void log_msg(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    fputs(LOG_PREFIX, stderr);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static void handle_signal(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void)
{
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    umask(022);

    /* Redirect stdio to /dev/null */
    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0 ||
        dup2(fd, STDOUT_FILENO) < 0 ||
        dup2(fd, STDERR_FILENO) < 0) {
        close(fd);
        return -1;
    }

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static int safe_snprintf_path(char *dst, size_t dstsz, const char *base, unsigned int idx)
{
    int n = snprintf(dst, dstsz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int file_size_bytes(const char *path, uint64_t *size_out)
{
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size < 0) {
        errno = EOVERFLOW;
        return -1;
    }

    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int create_empty_logfile(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        return -1;
    }
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const struct config *cfg)
{
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->rotations == 0) {
        /* No history kept: truncate by replacing file */
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            return -1;
        }
        return create_empty_logfile(cfg->log_path);
    }

    /* Remove the oldest rotation if present */
    if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, cfg->rotations) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    if (unlink(old_path) != 0 && errno != ENOENT) {
        return -1;
    }

    /* Shift rotations upward: .N-1 -> .N, ..., .1 -> .2 */
    for (unsigned int i = cfg->rotations; i > 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, i - 1) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, i) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Current log -> .1 */
    if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, 1) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return create_empty_logfile(cfg->log_path);
}

static int check_and_rotate(const struct config *cfg)
{
    uint64_t sz = 0;

    if (file_size_bytes(cfg->log_path, &sz) != 0) {
        if (errno == ENOENT) {
            return create_empty_logfile(cfg->log_path);
        }
        return -1;
    }

    if (sz >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval_sec] [-F]\n"
        "  -f <logfile>      Path to log file\n"
        "  -s <max_bytes>    Rotate at size threshold (default: %llu)\n"
        "  -n <rotations>    Number of rotated files to keep (default: %u)\n"
        "  -i <interval>     Poll interval in seconds (default: %u)\n"
        "  -F                Run in foreground\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_ROTATIONS,
        DEFAULT_INTERVAL_SEC
    );
}

static int parse_u64(const char *s, uint64_t *out)
{
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out)
{
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    if (v > UINT_MAX) {
        errno = ERANGE;
        return -1;
    }
    *out = (unsigned int)v;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg)
{
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->foreground = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:F")) != -1) {
        switch (opt) {
        case 'f':
            if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                errno = ENAMETOOLONG;
                return -1;
            }
            break;
        case 's':
            if (parse_u64(optarg, &cfg->max_size) != 0 || cfg->max_size == 0) {
                return -1;
            }
            break;
        case 'n':
            if (parse_u32(optarg, &cfg->rotations) != 0) {
                return -1;
            }
            break;
        case 'i':
            if (parse_u32(optarg, &cfg->interval_sec) != 0 || cfg->interval_sec == 0) {
                return -1;
            }
            break;
        case 'F':
            cfg->foreground = 1;
            break;
        default:
            return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int main(int argc, char **argv)
{
    struct config cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signal_handlers() != 0) {
        log_msg("failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    if (!cfg.foreground) {
        if (daemonize_process() != 0) {
            log_msg("failed to daemonize: %s", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        if (check_and_rotate(&cfg) != 0) {
            /* In daemon mode stderr goes to /dev/null; in foreground this is visible */
            log_msg("check/rotate failed for '%s': %s", cfg.log_path, strerror(errno));
        }

        struct timespec ts;
        ts.tv_sec = cfg.interval_sec;
        ts.tv_nsec = 0;

        while (g_running && nanosleep(&ts, &ts) != 0) {
            if (errno != EINTR) {
                break;
            }
        }
    }

    return 0;
}
