static int apply_memory_limits(rlim_t address_space_bytes, rlim_t data_bytes)
{
    struct rlimit rl;

    rl.rlim_cur = rl.rlim_max = address_space_bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
