# `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOG_PATH PATH_MAX
#define MAX_ROTATIONS 32
#define DEFAULT_POLL_INTERVAL_SEC 2
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)

static volatile sig_atomic_t g_running = 1;
static int g_foreground = 1;

typedef struct {
    char log_path[MAX_LOG_PATH];
    uint64_t max_size;
    int rotations;
    unsigned poll_interval_sec;
    int foreground;
    int create_missing;
    mode_t create_mode;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);

    if (g_foreground) {
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
    } else {
        /* Minimal daemon logging: stderr may be closed. */
        /* Intentionally no syslog to keep implementation small. */
    }

    va_end(ap);
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = (uint64_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    if (v < 0 || v > 2147483647L) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

static int ensure_parent_exists_or_file(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return 0;
    }
    return -1;
}

static int create_empty_file_if_missing(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[MAX_LOG_PATH];
    char new_path[MAX_LOG_PATH];

    if (cfg->rotations <= 0 || cfg->rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    /* Remove the oldest file if it exists: log.N */
    if (build_rotated_path(cfg->log_path, cfg->rotations, old_path, sizeof(old_path)) != 0) {
        return -1;
    }
    (void)unlink(old_path);

    /* Shift log.(N-1) -> log.N, ..., log.1 -> log.2 */
    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (build_rotated_path(cfg->log_path, i, old_path, sizeof(old_path)) != 0) {
            return -1;
        }
        if (build_rotated_path(cfg->log_path, i + 1, new_path, sizeof(new_path)) != 0) {
            return -1;
        }

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                log_msg("rename('%s','%s') failed: %s", old_path, new_path, strerror(errno));
                return -1;
            }
        }
    }

    /* Rename current log -> log.1 */
    if (build_rotated_path(cfg->log_path, 1, new_path, sizeof(new_path)) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno != ENOENT) {
            log_msg("rename('%s','%s') failed: %s", cfg->log_path, new_path, strerror(errno));
            return -1;
        }
    }

    /* Recreate empty active log file */
    if (create_empty_file_if_missing(cfg->log_path, cfg->create_mode) != 0) {
        log_msg("failed to recreate log file '%s': %s", cfg->log_path, strerror(errno));
        return -1;
    }

    return 0;
}

static int check_and_rotate(const config_t *cfg) {
    struct stat st;

    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT && cfg->create_missing) {
            if (create_empty_file_if_missing(cfg->log_path, cfg->create_mode) != 0) {
                log_msg("failed to create missing log file '%s': %s",
                        cfg->log_path, strerror(errno));
                return -1;
            }
            return 0;
        }

        log_msg("stat('%s') failed: %s", cfg->log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg("'%s' is not a regular file", cfg->log_path);
        return -1;
    }

    if ((uint64_t)st.st_size >= cfg->max_size) {
        log_msg("rotating '%s' size=%lld max=%llu",
                cfg->log_path,
                (long long)st.st_size,
                (unsigned long long)cfg->max_size);
        return rotate_logs(cfg);
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) {
            close(fd);
        }
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <log_path> [-s max_bytes] [-n rotations] [-p poll_sec] [-d]\n"
        "  -f <log_path>   Path to log file\n"
        "  -s <max_bytes>  Rotate when size >= max_bytes (default: %llu)\n"
        "  -n <rotations>  Number of rotated files to keep, 1..%d (default: 5)\n"
        "  -p <poll_sec>   Poll interval in seconds (default: %d)\n"
        "  -d              Run as daemon\n"
        "  -h              Show this help\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        MAX_ROTATIONS,
        DEFAULT_POLL_INTERVAL_SEC);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        return -1;
    }
    if (sigaction(SIGHUP, &sa, NULL) != 0) {
        return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.rotations = 5;
    cfg.poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg.foreground = 1;
    cfg.create_missing = 1;
    cfg.create_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:dh")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg.max_size) != 0 || cfg.max_size == 0) {
                    fprintf(stderr, "invalid max size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.rotations) != 0 ||
                    cfg.rotations < 1 || cfg.rotations > MAX_ROTATIONS) {
                    fprintf(stderr, "invalid rotations\n");
                    return 1;
                }
                break;
            case 'p': {
                int v;
                if (parse_int(optarg, &v) != 0 || v < 1) {
                    fprintf(stderr, "invalid poll interval\n");
                    return 1;
                }
                cfg.poll_interval_sec = (unsigned)v;
                break;
            }
            case 'd':
                cfg.foreground = 0;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (ensure_parent_exists_or_file(cfg.log_path) != 0) {
        if (!cfg.create_missing) {
            fprintf(stderr, "log file does not exist: %s\n", cfg.log_path);
            return 1;
        }
    }

    g_foreground = cfg.foreground;

    if (!cfg.foreground) {
        if (daemonize_process() != 0) {
            fprintf(stderr, "failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    if (install_signal_handlers() != 0) {
        log_msg("failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    log_msg("started: file='%s' max_size=%llu rotations=%d poll=%u foreground=%d",
            cfg.log_path,
            (unsigned long long)cfg.max_size,
            cfg.rotations,
            cfg.poll_interval_sec,
            cfg.foreground);

    while (g_running) {
        (void)check_and_rotate(&cfg);

        struct timespec ts;
        ts.tv_sec = (time_t)cfg.poll_interval_sec;
        ts.tv_nsec = 0;

        while (g_running && nanosleep(&ts, &ts) != 0) {
            if (errno != EINTR) {
                break;
            }
        }
    }

    log_msg("stopped");
    return 0;
}
