## Initial implementation

```c
/*
 * memlogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogd memlogd.c
 *
 * Run:
 *   ./memlogd /var/log/app.log:10485760 /var/log/other.log:5242880
 *
 * Each argument is:
 *   path:max_bytes
 *
 * Notes:
 * - Fixed limits for number of logs and path lengths.
 * - Polling-based rotation.
 * - No config reload.
 * - No compression.
 * - No post-rotate hooks.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS        32
#define MAX_ROTATIONS   8
#define POLL_INTERVAL   5
#define PIDFILE_PATH    "/tmp/memlogd.pid"

/* Strict fixed-size logging to stderr only */
static volatile sig_atomic_t g_running = 1;

typedef struct {
    char path[PATH_MAX];
    off_t max_bytes;
    int rotations;
} log_target_t;

typedef struct {
    log_target_t logs[MAX_LOGS];
    int log_count;
    unsigned poll_interval;
} config_t;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void safe_log(const char *fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len > 0) {
        (void)write(STDERR_FILENO, buf, len);
    }
}

static int set_memory_limits(void) {
    struct rlimit rl;

    /* Limit virtual memory to 32 MB */
    rl.rlim_cur = 32 * 1024 * 1024;
    rl.rlim_max = 32 * 1024 * 1024;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        safe_log("warn: setrlimit(RLIMIT_AS) failed: %s\n", strerror(errno));
    }

    /* Limit data segment to 8 MB */
    rl.rlim_cur = 8 * 1024 * 1024;
    rl.rlim_max = 8 * 1024 * 1024;
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        safe_log("warn: setrlimit(RLIMIT_DATA) failed: %s\n", strerror(errno));
    }

#ifdef RLIMIT_RSS
    /* Advisory/ignored on many Linux systems, but harmless to try */
    rl.rlim_cur = 16 * 1024 * 1024;
    rl.rlim_max = 16 * 1024 * 1024;
    if (setrlimit(RLIMIT_RSS, &rl) != 0) {
        safe_log("warn: setrlimit(RLIMIT_RSS) failed: %s\n", strerror(errno));
    }
#endif

    return 0;
}

static int write_pidfile(const char *pidfile) {
    char buf[64];
    int fd = open(pidfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        safe_log("error: open pidfile %s failed: %s\n", pidfile, strerror(errno));
        return -1;
    }

    int n = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (n < 0 || (size_t)n >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)n) != n) {
        safe_log("error: write pidfile failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        safe_log("error: first fork failed: %s\n", strerror(errno));
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        safe_log("error: setsid failed: %s\n", strerror(errno));
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        safe_log("error: second fork failed: %s\n", strerror(errno));
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        safe_log("warn: chdir(/) failed: %s\n", strerror(errno));
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    /* Keep stderr for diagnostics, or redirect if desired */

    int nullfd = open("/dev/null", O_RDONLY);
    if (nullfd >= 0 && nullfd != STDIN_FILENO) {
        dup2(nullfd, STDIN_FILENO);
        close(nullfd);
    }

    return 0;
}

static int parse_target(const char *arg, log_target_t *out) {
    const char *colon = strrchr(arg, ':');
    long long maxb;
    char *endp = NULL;
    size_t path_len;

    if (!colon || colon == arg || colon[1] == '\0') {
        return -1;
    }

    path_len = (size_t)(colon - arg);
    if (path_len >= sizeof(out->path)) {
        return -1;
    }

    memcpy(out->path, arg, path_len);
    out->path[path_len] = '\0';

    errno = 0;
    maxb = strtoll(colon + 1, &endp, 10);
    if (errno != 0 || !endp || *endp != '\0' || maxb <= 0) {
        return -1;
    }

    out->max_bytes = (off_t)maxb;
    out->rotations = MAX_ROTATIONS;
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int rotate_one(const log_target_t *t) {
    char oldp[PATH_MAX + 16];
    char newp[PATH_MAX + 16];
    int i;

    /* Remove oldest */
    if (snprintf(oldp, sizeof(oldp), "%s.%d", t->path, t->rotations) >= (int)sizeof(oldp)) {
        safe_log("error: path too long during rotation: %s\n", t->path);
        return -1;
    }
    (void)unlink(oldp);

    /* Shift N-1 down to 1 */
    for (i = t->rotations - 1; i >= 1; --i) {
        if (snprintf(oldp, sizeof(oldp), "%s.%d", t->path, i) >= (int)sizeof(oldp) ||
            snprintf(newp, sizeof(newp), "%s.%d", t->path, i + 1) >= (int)sizeof(newp)) {
            safe_log("error: path too long during rotation shift: %s\n", t->path);
            return -1;
        }

        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                safe_log("warn: rename %s -> %s failed: %s\n", oldp, newp, strerror(errno));
            }
        }
    }

    /* Current log to .1 */
    if (snprintf(newp, sizeof(newp), "%s.1", t->path) >= (int)sizeof(newp)) {
        safe_log("error: path too long for current rotation: %s\n", t->path);
        return -1;
    }

    if (rename(t->path, newp) != 0) {
        safe_log("warn: rename %s -> %s failed: %s\n", t->path, newp, strerror(errno));
        return -1;
    }

    /* Recreate empty log file */
    int fd = open(t->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        safe_log("error: recreate log %s failed: %s\n", t->path, strerror(errno));
        return -1;
    }
    close(fd);

    safe_log("info: rotated %s\n", t->path);
    return 0;
}

static void check_and_rotate(const config_t *cfg) {
    for (int i = 0; i < cfg->log_count; ++i) {
        off_t sz;
        const log_target_t *t = &cfg->logs[i];

        if (file_size(t->path, &sz) != 0) {
            if (errno != ENOENT) {
                safe_log("warn: stat %s failed: %s\n", t->path, strerror(errno));
            }
            continue;
        }

        if (sz >= t->max_bytes) {
            (void)rotate_one(t);
        }
    }
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) != 0) return -1;

    signal(SIGPIPE, SIG_IGN);
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s [--foreground] path:max_bytes [path:max_bytes ...]\n",
        prog);
}

int main(int argc, char **argv) {
    config_t cfg;
    int argi = 1;
    bool foreground = false;

    memset(&cfg, 0, sizeof(cfg));
    cfg.poll_interval = POLL_INTERVAL;

    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    if (strcmp(argv[argi], "--foreground") == 0) {
        foreground = true;
        argi++;
    }

    if (argi >= argc) {
        usage(argv[0]);
        return 1;
    }

    for (; argi < argc; ++argi) {
        if (cfg.log_count >= MAX_LOGS) {
            safe_log("error: too many log targets (max %d)\n", MAX_LOGS);
            return 1;
        }
        if (parse_target(argv[argi], &cfg.logs[cfg.log_count]) != 0) {
            safe_log("error: invalid target: %s\n", argv[argi]);
            return 1;
        }
        cfg.log_count++;
    }

    if (install_signals() != 0) {
        safe_log("error: install_signals failed: %s\n", strerror(errno));
        return 1;
    }

    set_memory_limits();

    if (!foreground) {
        if (daemonize_process() != 0) {
            return 1;
        }
        if (write_pidfile(PIDFILE_PATH) != 0) {
            return 1;
        }
    }

    safe_log("info: memlogd started with %d targets\n", cfg.log_count);

    while (g_running) {
        check_and_rotate(&cfg);

        for (unsigned i = 0; i < cfg.poll_interval && g_running; ++i) {
            sleep(1);
        }
    }

    safe_log("info: memlogd stopping\n");
    if (!foreground) {
        unlink(PIDFILE_PATH);
    }
    return 0;
}
