## Initial implementation

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Characteristics:
 * - Fixed-size buffers
 * - No dynamic allocation in steady state
 * - Polling-based rotation
 * - Size-based rotation only
 * - Keeps a fixed number of rotated logs
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogd memlogd.c
 *
 * Usage:
 *   ./memlogd /var/log/myapp.log 1048576 5 1000
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = polling interval in milliseconds
 *
 * Example:
 *   ./memlogd /tmp/app.log 1048576 3 500
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 32
#define MAX_PATH_LEN  PATH_MAX

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_path[MAX_PATH_LEN];
    off_t max_size;
    unsigned int rotate_count;
    unsigned int poll_interval_ms;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        return -1;
    }
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, unsigned int suffix) {
    int n;
    if (suffix == 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%u", base, suffix);
    }

    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

/*
 * Rotation strategy:
 *   log.(N-1) -> log.N
 *   ...
 *   log.1 -> log.2
 *   log -> log.1
 *   create fresh log
 */
static int rotate_logs(const config_t *cfg) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    if (cfg->rotate_count == 0) {
        /* No backups requested: truncate the file in place. */
        int fd = open(cfg->log_path, O_WRONLY | O_TRUNC);
        if (fd < 0) {
            return -1;
        }
        close(fd);
        return 0;
    }

    if (cfg->rotate_count > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    /* Remove the oldest file if present */
    if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, cfg->rotate_count) < 0) {
        return -1;
    }
    if (unlink(old_path) < 0 && errno != ENOENT) {
        return -1;
    }

    /* Shift existing rotations upward */
    for (unsigned int i = cfg->rotate_count; i > 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, i - 1) < 0) {
            return -1;
        }
        if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, i) < 0) {
            return -1;
        }

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Rotate current log to .1 */
    if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty active log */
    if (ensure_log_exists(cfg->log_path) < 0) {
        return -1;
    }

    return 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000U;
    ts.tv_nsec = (long)(ms % 1000U) * 1000000L;

    while (nanosleep(&ts, &ts) < 0) {
        if (errno != EINTR) {
            break;
        }
        if (!g_running) {
            break;
        }
    }
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    unsigned long v;

    errno = 0;
    v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v > UINT32_MAX) {
        return -1;
    }

    *out = (unsigned int)v;
    return 0;
}

static int parse_off_t_val(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < 0) {
        return -1;
    }

    *out = (off_t)v;
    return 0;
}

static int load_config_from_argv(int argc, char **argv, config_t *cfg) {
    unsigned int rotate_count;
    unsigned int poll_ms;
    off_t max_size;
    size_t len;

    if (argc != 5) {
        return -1;
    }

    len = strnlen(argv[1], sizeof(cfg->log_path));
    if (len == 0 || len >= sizeof(cfg->log_path)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    memcpy(cfg->log_path, argv[1], len);
    cfg->log_path[len] = '\0';

    if (parse_off_t_val(argv[2], &max_size) < 0) {
        return -1;
    }
    if (parse_u32(argv[3], &rotate_count) < 0) {
        return -1;
    }
    if (parse_u32(argv[4], &poll_ms) < 0) {
        return -1;
    }

    if (rotate_count > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    cfg->max_size = max_size;
    cfg->rotate_count = rotate_count;
    cfg->poll_interval_ms = poll_ms;

    return 0;
}

static void print_usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s <log_path> <max_size_bytes> <rotate_count> <poll_interval_ms>\n"
            "Example: %s /tmp/app.log 1048576 5 1000\n",
            prog, prog);
}

static void log_error(const char *msg, const char *path) {
    if (path) {
        fprintf(stderr, "memlogd: %s: %s: %s\n", msg, path, strerror(errno));
    } else {
        fprintf(stderr, "memlogd: %s: %s\n", msg, strerror(errno));
    }
}

int main(int argc, char **argv) {
    config_t cfg;
    off_t size;

    if (load_config_from_argv(argc, argv, &cfg) < 0) {
        print_usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        log_error("failed to install signal handlers", NULL);
        return 1;
    }

    if (ensure_log_exists(cfg.log_path) < 0) {
        log_error("failed to create or open log file", cfg.log_path);
        return 1;
    }

    while (g_running) {
        if (get_file_size(cfg.log_path, &size) < 0) {
            if (errno != ENOENT) {
                log_error("failed to stat log file", cfg.log_path);
            } else {
                if (ensure_log_exists(cfg.log_path) < 0) {
                    log_error("failed to recreate missing log file", cfg.log_path);
                }
            }
            sleep_ms(cfg.poll_interval_ms);
            continue;
        }

        if (size >= cfg.max_size) {
            if (rotate_logs(&cfg) < 0) {
                log_error("rotation failed", cfg.log_path);
            }
        }

        sleep_ms(cfg.poll_interval_ms);
    }

    return 0;
}
```

