Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed to run with **strict memory limits** in mind.

It aims to be:

- **Small and predictable**
- **Heap-free during steady-state operation**
- **Single-threaded**
- **Polling-based**
- **Configurable at compile time**
- **Suitable as a starting point**, not a production-complete replacement for `logrotate`

It supports:

- Monitoring a fixed set of log files
- Rotating when size exceeds a threshold
- Keeping a fixed number of archives
- Optional periodic scan
- Reopening/creating the active log file after rotation
- Running as a daemon

---

# Design goals

This implementation intentionally avoids:

- Dynamic allocation in the main loop
- Complex parsing
- Recursive directory walking
- Compression
- Signal-heavy complexity
- Large buffers

Memory usage is bounded primarily by:

- Static arrays for configured log targets
- A small I/O buffer
- Stack-local temporary path buffers

---

# Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

/*
 * Memory-constrained log rotation daemon
 *
 * Features:
 * - fixed compile-time configuration
 * - no heap allocation in steady-state
 * - rotates files when they exceed max_size
 * - keeps rotate_count archives: file.1 ... file.N
 * - polling loop with fixed sleep interval
 * - simple daemonization
 *
 * Limitations:
 * - no config file parsing
 * - no compression
 * - no postrotate hooks
 * - no inode tracking for external rotations
 * - no locking across multiple daemon instances
 * - path lengths must fit PATH_MAX
 */

#ifndef MAX_LOGS
#define MAX_LOGS 16
#endif

#ifndef DEFAULT_SCAN_INTERVAL_SEC
#define DEFAULT_SCAN_INTERVAL_SEC 5
#endif

#ifndef IO_BUF_SIZE
#define IO_BUF_SIZE 256
#endif

#ifndef DEFAULT_ROTATE_COUNT
#define DEFAULT_ROTATE_COUNT 4
#endif

#ifndef DEFAULT_MAX_SIZE
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#endif

#ifndef PIDFILE_PATH
#define PIDFILE_PATH "/tmp/memlogd.pid"
#endif

#ifndef LOG_STDERR
#define LOG_STDERR 1
#endif

typedef struct {
    const char *path;
    off_t max_size;
    unsigned rotate_count;
    mode_t create_mode;
    uid_t create_uid;
    gid_t create_gid;
    bool enabled;
} log_target_t;

typedef struct {
    log_target_t targets[MAX_LOGS];
    size_t count;
    unsigned scan_interval_sec;
    bool daemonize;
} daemon_config_t;

static volatile sig_atomic_t g_stop = 0;
static volatile sig_atomic_t g_reload = 0;

static void on_signal(int signo) {
    if (signo == SIGTERM || signo == SIGINT) {
        g_stop = 1;
    } else if (signo == SIGHUP) {
        g_reload = 1;
    }
}

static void log_msg(const char *fmt, ...) {
#if LOG_STDERR
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
#else
    (void)fmt;
#endif
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int write_pidfile(const char *pidfile) {
    char buf[32];
    int fd = open(pidfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }

    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)len) != len) {
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int safe_stat(const char *path, struct stat *st) {
    if (stat(path, st) < 0) {
        if (errno == ENOENT) return 1;
        return -1;
    }
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, unsigned index) {
    int n = snprintf(out, out_sz, "%s.%u", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_parentless_create(const char *path, mode_t mode, uid_t uid, gid_t gid) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, mode);
    if (fd < 0) return -1;

    if (fchown(fd, uid, gid) < 0) {
        if (errno != EPERM) {
            close(fd);
            return -1;
        }
    }

    close(fd);
    return 0;
}

static int rotate_one(const log_target_t *t) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (!t || !t->enabled || !t->path) {
        errno = EINVAL;
        return -1;
    }

    if (t->rotate_count == 0) {
        /* Truncate in place if no archives requested */
        int fd = open(t->path, O_WRONLY | O_TRUNC | O_CREAT, t->create_mode);
        if (fd < 0) return -1;
        if (fchown(fd, t->create_uid, t->create_gid) < 0 && errno != EPERM) {
            close(fd);
            return -1;
        }
        close(fd);
        return 0;
    }

    /* Remove oldest archive */
    if (build_rotated_path(old_path, sizeof(old_path), t->path, t->rotate_count) < 0) {
        return -1;
    }
    (void)unlink(old_path);

    /* Shift N-1 down to N */
    for (unsigned i = t->rotate_count; i > 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), t->path, i - 1) < 0) {
            return -1;
        }
        if (build_rotated_path(new_path, sizeof(new_path), t->path, i) < 0) {
            return -1;
        }
        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Move current file to .1 */
    if (build_rotated_path(new_path, sizeof(new_path), t->path, 1) < 0) {
        return -1;
    }

    if (rename(t->path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate active file */
    if (ensure_parentless_create(t->path, t->create_mode, t->create_uid, t->create_gid) < 0) {
        return -1;
    }

    return 0;
}

static int maybe_rotate(const log_target_t *t) {
    struct stat st;
    int rc = safe_stat(t->path, &st);
    if (rc == 1) {
        /* Missing file: create it */
        return ensure_parentless_create(t->path, t->create_mode, t->create_uid, t->create_gid);
    }
    if (rc < 0) return -1;

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= t->max_size) {
        return rotate_one(t);
    }

    return 0;
}

static void handle_reload(daemon_config_t *cfg) {
    /*
     * Placeholder for future config reload support.
     * In this initial implementation, configuration is static.
     */
    (void)cfg;
    log_msg("SIGHUP received: reload requested, but static config is in use");
}

static void sleep_interval(unsigned sec) {
    struct timespec req, rem;
    req.tv_sec = (time_t)sec;
    req.tv_nsec = 0;

    while (nanosleep(&req, &rem) < 0) {
        if (errno == EINTR) {
            if (g_stop || g_reload) break;
            req = rem;
            continue;
        }
        break;
    }
}

static int run_loop(daemon_config_t *cfg) {
    while (!g_stop) {
        for (size_t i = 0; i < cfg->count; ++i) {
            const log_target_t *t = &cfg->targets[i];
            if (!t->enabled) continue;

            if (maybe_rotate(t) < 0) {
                log_msg("rotate check failed for %s: %s", t->path, strerror(errno));
            }
        }

        if (g_reload) {
            g_reload = 0;
            handle_reload(cfg);
        }

        if (!g_stop) {
            sleep_interval(cfg->scan_interval_sec);
        }
    }
    return 0;
}

static void init_default_config(daemon_config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->scan_interval_sec = DEFAULT_SCAN_INTERVAL_SEC;
    cfg->daemonize = false;

    /*
     * Example static configuration.
     * Replace these with your actual log files.
     */
    cfg->targets[0] = (log_target_t) {
        .path = "/tmp/app.log",
        .max_size = DEFAULT_MAX_SIZE,
        .rotate_count = DEFAULT_ROTATE_COUNT,
        .create_mode = 0644,
        .create_uid = 0,
        .create_gid = 0,
        .enabled = true
    };

    cfg->targets[1] = (log_target_t) {
        .path = "/tmp/worker.log",
        .max_size = 1024 * 1024,
        .rotate_count = 3,
        .create_mode = 0640,
        .create_uid = 0,
        .create_gid = 0,
        .enabled = true
    };

    cfg->count = 2;
}

static int parse_args(daemon_config_t *cfg, int argc, char **argv) {
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--daemon") == 0) {
            cfg->daemonize = true;
        } else if (strcmp(argv[i], "--interval") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "--interval requires a value\n");
                return -1;
            }
            char *end = NULL;
            unsigned long v = strtoul(argv[++i], &end, 10);
            if (!end || *end != '\0' || v == 0 || v > 86400UL) {
                fprintf(stderr, "invalid interval: %s\n", argv[i]);
                return -1;
            }
            cfg->scan_interval_sec = (unsigned)v;
        } else if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [--daemon] [--interval SEC]\n", argv[0]);
            return 1;
        } else {
            fprintf(stderr, "unknown argument: %s\n", argv[i]);
            return -1;
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    daemon_config_t cfg;

    init_default_config(&cfg);

    int prc = parse_args(&cfg, argc, argv);
    if (prc != 0) {
        return (prc > 0) ? 0 : 1;
    }

    if (install_signal_handlers() < 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize_process");
            return 1;
        }
    }

    if (write_pidfile(PIDFILE_PATH) < 0) {
        log_msg("warning: failed to write pidfile %s: %s", PIDFILE_PATH, strerror(errno));
    }

    log_msg("memlogd starting: logs=%zu interval=%u daemon=%d",
            cfg.count, cfg.scan_interval_sec, cfg.daemonize ? 1 : 0);

    int rc = run_loop(&cfg);

    unlink(PIDFILE_PATH);
    log_msg("memlogd stopping");
    return rc == 0 ? 0 : 1;
}
