# Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

/*
 * Memory-constrained log rotation daemon
 *
 * Design goals:
 * - Avoid dynamic allocation after startup
 * - Fixed-size tables and buffers
 * - Simple polling loop
 * - Rotate by size only
 * - Minimal dependencies
 */

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS            64
#define MAX_LINE            1024
#define MAX_PATH_LEN        PATH_MAX
#define DEFAULT_INTERVAL    5
#define DEFAULT_UMASK       022
#define DEFAULT_PIDFILE     "/tmp/memlogd.pid"

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_bytes;
    int keep_count;
    ino_t last_ino;
    dev_t last_dev;
} log_entry_t;

typedef struct {
    log_entry_t logs[MAX_LOGS];
    size_t log_count;
    unsigned interval_sec;
    int daemonize;
    int verbose;
    char pidfile[MAX_PATH_LEN];
    rlim_t rlimit_as;
    rlim_t rlimit_data;
    rlim_t rlimit_nofile;
} config_t;

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_msg(int verbose, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    if (verbose) {
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
    }
    va_end(ap);
}

static int set_limits(const config_t *cfg) {
    struct rlimit rl;

    if (cfg->rlimit_as > 0) {
        rl.rlim_cur = cfg->rlimit_as;
        rl.rlim_max = cfg->rlimit_as;
        if (setrlimit(RLIMIT_AS, &rl) != 0) {
            perror("setrlimit(RLIMIT_AS)");
            return -1;
        }
    }

#ifdef RLIMIT_DATA
    if (cfg->rlimit_data > 0) {
        rl.rlim_cur = cfg->rlimit_data;
        rl.rlim_max = cfg->rlimit_data;
        if (setrlimit(RLIMIT_DATA, &rl) != 0) {
            perror("setrlimit(RLIMIT_DATA)");
            return -1;
        }
    }
#endif

    if (cfg->rlimit_nofile > 0) {
        rl.rlim_cur = cfg->rlimit_nofile;
        rl.rlim_max = cfg->rlimit_nofile;
        if (setrlimit(RLIMIT_NOFILE, &rl) != 0) {
            perror("setrlimit(RLIMIT_NOFILE)");
            return -1;
        }
    }

    return 0;
}

static int write_pidfile(const char *pidfile) {
    int fd = open(pidfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open(pidfile)");
        return -1;
    }

    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)len) != len) {
        perror("write(pidfile)");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static void remove_pidfile(const char *pidfile) {
    unlink(pidfile);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        perror("setsid");
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        perror("chdir");
        return -1;
    }

    umask(DEFAULT_UMASK);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        perror("open(/dev/null)");
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0 ||
        dup2(fd, STDOUT_FILENO) < 0 ||
        dup2(fd, STDERR_FILENO) < 0) {
        perror("dup2");
        close(fd);
        return -1;
    }

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static void trim(char *s) {
    size_t len;
    char *p;

    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') {
        memmove(s, s + 1, strlen(s));
    }

    len = strlen(s);
    while (len > 0) {
        p = &s[len - 1];
        if (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') {
            *p = '\0';
            len--;
        } else {
            break;
        }
    }
}

static int parse_config_line(const char *line, log_entry_t *entry) {
    char path[MAX_PATH_LEN];
    long long max_bytes;
    int keep_count;

    if (sscanf(line, "%4095s %lld %d", path, &max_bytes, &keep_count) != 3) {
        return -1;
    }

    if (max_bytes <= 0 || keep_count < 1) {
        return -1;
    }

    strncpy(entry->path, path, sizeof(entry->path) - 1);
    entry->path[sizeof(entry->path) - 1] = '\0';
    entry->max_bytes = (off_t)max_bytes;
    entry->keep_count = keep_count;
    entry->last_ino = 0;
    entry->last_dev = 0;

    return 0;
}

static int load_config_file(const char *config_path, config_t *cfg) {
    FILE *fp;
    char line[MAX_LINE];
    size_t count = 0;

    fp = fopen(config_path, "r");
    if (!fp) {
        perror("fopen(config)");
        return -1;
    }

    cfg->log_count = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        trim(line);

        if (line[0] == '\0' || line[0] == '#') {
            continue;
        }

        if (count >= MAX_LOGS) {
            fprintf(stderr, "Too many log entries; max=%d\n", MAX_LOGS);
            fclose(fp);
            return -1;
        }

        if (parse_config_line(line, &cfg->logs[count]) != 0) {
            fprintf(stderr, "Invalid config line: %s\n", line);
            fclose(fp);
            return -1;
        }

        count++;
    }

    fclose(fp);
    cfg->log_count = count;
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int rename_with_suffix(const char *base, int suffix, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        return -1;
    }
    return 0;
}

static int rotate_log(const log_entry_t *entry, int verbose) {
    char oldpath[MAX_PATH_LEN];
    char newpath[MAX_PATH_LEN];
    int i;

    for (i = entry->keep_count; i >= 1; --i) {
        if (rename_with_suffix(entry->path, i, oldpath, sizeof(oldpath)) != 0) {
            return -1;
        }

        if (i == entry->keep_count) {
            if (file_exists(oldpath)) {
                if (unlink(oldpath) != 0) {
                    perror("unlink(old rotated)");
                    return -1;
                }
            }
        } else {
            if (rename_with_suffix(entry->path, i + 1, newpath, sizeof(newpath)) != 0) {
                return -1;
            }
            if (file_exists(oldpath)) {
                if (rename(oldpath, newpath) != 0) {
                    perror("rename(rotated chain)");
                    return -1;
                }
            }
        }
    }

    if (rename_with_suffix(entry->path, 1, newpath, sizeof(newpath)) != 0) {
        return -1;
    }

    if (file_exists(entry->path)) {
        if (rename(entry->path, newpath) != 0) {
            perror("rename(active log)");
            return -1;
        }
    }

    int fd = open(entry->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open(new active log)");
        return -1;
    }
    close(fd);

    log_msg(verbose, "rotated: %s", entry->path);
    return 0;
}

static int check_one_log(log_entry_t *entry, int verbose) {
    struct stat st;

    if (stat(entry->path, &st) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        perror("stat(log)");
        return -1;
    }

    entry->last_ino = st.st_ino;
    entry->last_dev = st.st_dev;

    if (!S_ISREG(st.st_mode)) {
        return 0;
    }

    if (st.st_size >= entry->max_bytes) {
        return rotate_log(entry, verbose);
    }

    return 0;
}

static void init_defaults(config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->interval_sec = DEFAULT_INTERVAL;
    cfg->daemonize = 0;
    cfg->verbose = 1;
    cfg->rlimit_as = 0;
    cfg->rlimit_data = 0;
    cfg->rlimit_nofile = 32;
    strncpy(cfg->pidfile, DEFAULT_PIDFILE, sizeof(cfg->pidfile) - 1);
    cfg->pidfile[sizeof(cfg->pidfile) - 1] = '\0';
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -c <config> [options]\n"
        "Options:\n"
        "  -c <file>   Config file path\n"
        "  -i <sec>    Poll interval seconds (default: %d)\n"
        "  -d          Daemonize\n"
        "  -q          Quiet\n"
        "  -p <file>   PID file path\n"
        "  -A <bytes>  RLIMIT_AS\n"
        "  -D <bytes>  RLIMIT_DATA\n"
        "  -N <count>  RLIMIT_NOFILE\n",
        prog, DEFAULT_INTERVAL);
}

int main(int argc, char **argv) {
    config_t cfg;
    char config_path[MAX_PATH_LEN];
    int opt;
    int rc = 1;

    init_defaults(&cfg);
    config_path[0] = '\0';

    while ((opt = getopt(argc, argv, "c:i:dqp:A:D:N:")) != -1) {
        switch (opt) {
            case 'c':
                strncpy(config_path, optarg, sizeof(config_path) - 1);
                config_path[sizeof(config_path) - 1] = '\0';
                break;
            case 'i':
                cfg.interval_sec = (unsigned)strtoul(optarg, NULL, 10);
                if (cfg.interval_sec == 0) {
                    cfg.interval_sec = DEFAULT_INTERVAL;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'q':
                cfg.verbose = 0;
                break;
            case 'p':
                strncpy(cfg.pidfile, optarg, sizeof(cfg.pidfile) - 1);
                cfg.pidfile[sizeof(cfg.pidfile) - 1] = '\0';
                break;
            case 'A':
                cfg.rlimit_as = (rlim_t)strtoull(optarg, NULL, 10);
                break;
            case 'D':
                cfg.rlimit_data = (rlim_t)strtoull(optarg, NULL, 10);
                break;
            case 'N':
                cfg.rlimit_nofile = (rlim_t)strtoull(optarg, NULL, 10);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (config_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (load_config_file(config_path, &cfg) != 0) {
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            return 1;
        }
    }

    if (set_limits(&cfg) != 0) {
        return 1;
    }

    if (write_pidfile(cfg.pidfile) != 0) {
        return 1;
    }

    signal(SIGTERM, on_signal);
    signal(SIGINT, on_signal);
    signal(SIGHUP, on_signal);

    log_msg(cfg.verbose, "memlogd started with %zu logs", cfg.log_count);

    while (!g_terminate) {
        if (g_reload) {
            g_reload = 0;
            if (load_config_file(config_path, &cfg) == 0) {
                log_msg(cfg.verbose, "configuration reloaded");
            } else {
                log_msg(cfg.verbose, "configuration reload failed; keeping prior state");
            }
        }

        for (size_t i = 0; i < cfg.log_count; i++) {
            if (check_one_log(&cfg.logs[i], cfg.verbose) != 0) {
                log_msg(cfg.verbose, "error checking log: %s", cfg.logs[i].path);
            }
        }

        for (unsigned slept = 0; slept < cfg.interval_sec && !g_terminate && !g_reload; slept++) {
            sleep(1);
        }
    }

    remove_pidfile(cfg.pidfile);
    log_msg(cfg.verbose, "memlogd exiting");
    rc = 0;
    return rc;
}
