Below is a compact initial implementation of a **memory-constrained log rotation daemon** in **C** designed with **strict memory limits** in mind.

It:
- avoids dynamic allocation in steady state
- uses fixed-size buffers
- scans a configured directory for `.log` files
- rotates files when they exceed a size threshold
- keeps a fixed number of rotated generations
- can run as a simple daemon loop
- tries to keep memory usage predictable

---

# Features

- **Strict memory discipline**
  - no heap allocation required for normal operation
  - fixed path buffers
  - bounded directory/file handling
- **Rotation policy**
  - `app.log` → `app.log.1`
  - `app.log.1` → `app.log.2`
  - ...
  - oldest removed when exceeding retention count
- **Daemon loop**
  - scans periodically
- **Safe-ish initial implementation**
  - uses `snprintf`
  - checks bounds/errors
  - avoids loading file contents into memory

---

# Initial implementation: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <signal.h>
#include <limits.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_NAME_LEN       256
#define DEFAULT_INTERVAL_S 5
#define DEFAULT_MAX_SIZE   (10 * 1024 * 1024) /* 10 MiB */
#define DEFAULT_KEEP       5

static volatile sig_atomic_t g_running = 1;

typedef struct {
    char log_dir[PATH_MAX];
    off_t max_size;
    int keep_count;
    unsigned interval_s;
    int daemonize;
    int verbose;
} config_t;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int is_log_file(const char *name) {
    size_t len;
    if (!name) return 0;
    if (name[0] == '.') return 0;

    len = strlen(name);
    if (len < 4) return 0;
    return strcmp(name + len - 4, ".log") == 0;
}

static int build_path(char *out, size_t out_sz, const char *dir, const char *name) {
    int n;
    if (!out || !dir || !name) return -1;
    n = snprintf(out, out_sz, "%s/%s", dir, name);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *dir, const char *name, int gen) {
    int n;
    if (!out || !dir || !name || gen < 1) return -1;
    n = snprintf(out, out_sz, "%s/%s.%d", dir, name, gen);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (!path || !size_out) return -1;
    if (stat(path, &st) < 0) return -1;
    if (!S_ISREG(st.st_mode)) return -1;
    *size_out = st.st_size;
    return 0;
}

static int remove_if_exists(const char *path) {
    if (unlink(path) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }
    return 0;
}

static int rotate_one(const config_t *cfg, const char *name) {
    char src[PATH_MAX];
    char dst[PATH_MAX];
    int i;

    if (!cfg || !name) return -1;

    if (cfg->keep_count < 1) {
        if (build_path(src, sizeof(src), cfg->log_dir, name) < 0) return -1;

        /* Truncate in place if no history is kept */
        int fd = open(src, O_WRONLY);
        if (fd < 0) return -1;
        if (ftruncate(fd, 0) < 0) {
            close(fd);
            return -1;
        }
        close(fd);
        return 0;
    }

    /* Remove oldest generation */
    if (build_rotated_path(dst, sizeof(dst), cfg->log_dir, name, cfg->keep_count) < 0) return -1;
    if (remove_if_exists(dst) < 0) return -1;

    /* Shift N-1 -> N, ..., 1 -> 2 */
    for (i = cfg->keep_count - 1; i >= 1; --i) {
        if (build_rotated_path(src, sizeof(src), cfg->log_dir, name, i) < 0) return -1;
        if (build_rotated_path(dst, sizeof(dst), cfg->log_dir, name, i + 1) < 0) return -1;

        if (rename(src, dst) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    /* Current log -> .1 */
    if (build_path(src, sizeof(src), cfg->log_dir, name) < 0) return -1;
    if (build_rotated_path(dst, sizeof(dst), cfg->log_dir, name, 1) < 0) return -1;

    if (rename(src, dst) < 0) return -1;

    /* Recreate empty current log */
    {
        int fd = open(src, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
    }

    return 0;
}

static int process_directory(const config_t *cfg) {
    DIR *dir;
    struct dirent *ent;
    char path[PATH_MAX];
    off_t sz;

    if (!cfg) return -1;

    dir = opendir(cfg->log_dir);
    if (!dir) return -1;

    errno = 0;
    while ((ent = readdir(dir)) != NULL) {
        if (!is_log_file(ent->d_name)) {
            continue;
        }

        if (build_path(path, sizeof(path), cfg->log_dir, ent->d_name) < 0) {
            if (cfg->verbose) {
                fprintf(stderr, "path too long: %s\n", ent->d_name);
            }
            continue;
        }

        if (file_size(path, &sz) < 0) {
            continue;
        }

        if (sz >= cfg->max_size) {
            if (cfg->verbose) {
                fprintf(stderr, "rotating %s (size=%lld)\n",
                        path, (long long)sz);
            }
            if (rotate_one(cfg, ent->d_name) < 0) {
                if (cfg->verbose) {
                    fprintf(stderr, "failed to rotate %s: %s\n",
                            path, strerror(errno));
                }
            }
        }
        errno = 0;
    }

    if (errno != 0) {
        closedir(dir);
        return -1;
    }

    closedir(dir);
    return 0;
}

static int daemonize_process(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -d <log_dir> [-s max_size_bytes] [-k keep_count] [-i interval_s] [-D] [-v]\n"
        "  -d log directory\n"
        "  -s rotate when file size >= max_size_bytes (default: %d)\n"
        "  -k number of rotated files to keep (default: %d)\n"
        "  -i scan interval seconds (default: %d)\n"
        "  -D daemonize\n"
        "  -v verbose\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_KEEP, DEFAULT_INTERVAL_S);
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    int opt;
    long long tmp;

    if (!cfg) return -1;

    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->keep_count = DEFAULT_KEEP;
    cfg->interval_s = DEFAULT_INTERVAL_S;
    cfg->daemonize = 0;
    cfg->verbose = 0;

    while ((opt = getopt(argc, argv, "d:s:k:i:Dv")) != -1) {
        switch (opt) {
            case 'd':
                if (snprintf(cfg->log_dir, sizeof(cfg->log_dir), "%s", optarg) >= (int)sizeof(cfg->log_dir)) {
                    return -1;
                }
                break;
            case 's':
                tmp = atoll(optarg);
                if (tmp <= 0) return -1;
                cfg->max_size = (off_t)tmp;
                break;
            case 'k':
                tmp = atoll(optarg);
                if (tmp < 0 || tmp > 1000) return -1;
                cfg->keep_count = (int)tmp;
                break;
            case 'i':
                tmp = atoll(optarg);
                if (tmp <= 0 || tmp > 86400) return -1;
                cfg->interval_s = (unsigned)tmp;
                break;
            case 'D':
                cfg->daemonize = 1;
                break;
            case 'v':
                cfg->verbose = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_dir[0] == '\0') return -1;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    struct stat st;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    if (stat(cfg.log_dir, &st) < 0 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "invalid log directory: %s\n", cfg.log_dir);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        fprintf(stderr, "failed to install signal handlers\n");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            fprintf(stderr, "failed to daemonize\n");
            return 1;
        }
    }

    while (g_running) {
        if (process_directory(&cfg) < 0) {
            if (cfg.verbose) {
                fprintf(stderr, "directory scan failed: %s\n", strerror(errno));
            }
        }

        {
            struct timespec ts;
            ts.tv_sec = cfg.interval_s;
            ts.tv_nsec = 0;
            while (g_running && nanosleep(&ts, &ts) < 0 && errno == EINTR) {
                /* retry remaining sleep */
            }
        }
    }

    return 0;
}
```

