# Source: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS            32
#define MAX_ROTATIONS       16
#define MAX_PATH_LEN        512
#define LOG_MSG_LEN         256
#define DEFAULT_POLL_SEC    5
#define DEFAULT_CREATE_MODE 0640

typedef struct {
    char path[MAX_PATH_LEN];
    off_t rotate_size;
    int keep_count;
    mode_t create_mode;
    bool enabled;
} log_target_t;

typedef struct {
    log_target_t targets[MAX_LOGS];
    size_t count;
    unsigned poll_interval_sec;
    bool foreground;
    bool recreate;
} daemon_config_t;

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

static void on_signal(int signo) {
    if (signo == SIGTERM || signo == SIGINT) {
        g_terminate = 1;
    } else if (signo == SIGHUP) {
        g_reload = 1;
    }
}

static void safe_log(FILE *stream, const char *fmt, ...) {
    char buf[LOG_MSG_LEN];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len + 1 < sizeof(buf)) {
        buf[len++] = '\n';
        buf[len] = '\0';
    }

    (void)fwrite(buf, 1, len, stream);
    (void)fflush(stream);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int set_memory_limit_bytes(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static int path_has_room(const char *base, const char *suffix) {
    size_t a = strnlen(base, MAX_PATH_LEN);
    size_t b = strnlen(suffix, MAX_PATH_LEN);
    return (a < MAX_PATH_LEN && b < MAX_PATH_LEN && (a + b + 1) < MAX_PATH_LEN);
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int index) {
    if (!out || !base || out_sz == 0) return -1;
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int ensure_parent_exists_simple(const char *path) {
    /* Minimal version: assumes parent exists. */
    (void)path;
    return 0;
}

static int recreate_log_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_one(const log_target_t *t, FILE *log_stream) {
    if (!t || !t->enabled) return -1;
    if (t->keep_count < 1 || t->keep_count > MAX_ROTATIONS) return -1;

    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    for (int i = t->keep_count - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), t->path, i) < 0) {
            safe_log(log_stream, "path too long during rotation: %s.%d", t->path, i);
            return -1;
        }
        if (build_rotated_path(newp, sizeof(newp), t->path, i + 1) < 0) {
            safe_log(log_stream, "path too long during rotation: %s.%d", t->path, i + 1);
            return -1;
        }

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                safe_log(log_stream, "rename failed %s -> %s: errno=%d", oldp, newp, errno);
                return -1;
            }
        }
    }

    if (build_rotated_path(newp, sizeof(newp), t->path, 1) < 0) {
        safe_log(log_stream, "path too long during base rotation: %s.1", t->path);
        return -1;
    }

    if (rename(t->path, newp) < 0) {
        safe_log(log_stream, "rename failed %s -> %s: errno=%d", t->path, newp, errno);
        return -1;
    }

    if (recreate_log_file(t->path, t->create_mode) < 0) {
        safe_log(log_stream, "recreate failed for %s: errno=%d", t->path, errno);
        return -1;
    }

    safe_log(log_stream, "rotated %s", t->path);
    return 0;
}

static int check_and_rotate(const log_target_t *t, bool recreate, FILE *log_stream) {
    struct stat st;
    if (!t || !t->enabled) return 0;

    if (stat(t->path, &st) < 0) {
        if (errno != ENOENT) {
            safe_log(log_stream, "stat failed for %s: errno=%d", t->path, errno);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        safe_log(log_stream, "not a regular file: %s", t->path);
        return -1;
    }

    if (st.st_size < t->rotate_size) {
        return 0;
    }

    if (!recreate) {
        int fd = open(t->path, O_WRONLY | O_TRUNC);
        if (fd < 0) {
            safe_log(log_stream, "truncate failed for %s: errno=%d", t->path, errno);
            return -1;
        }
        close(fd);
        safe_log(log_stream, "truncated %s", t->path);
        return 0;
    }

    return rotate_one(t, log_stream);
}

static void sleep_interruptible(unsigned sec) {
    while (sec > 0 && !g_terminate && !g_reload) {
        sec = sleep(sec);
    }
}

static void run_loop(daemon_config_t *cfg, FILE *log_stream) {
    while (!g_terminate) {
        if (g_reload) {
            safe_log(log_stream, "reload requested (not implemented)");
            g_reload = 0;
        }

        for (size_t i = 0; i < cfg->count; ++i) {
            (void)check_and_rotate(&cfg->targets[i], cfg->recreate, log_stream);
            if (g_terminate) break;
        }

        sleep_interruptible(cfg->poll_interval_sec);
    }

    safe_log(log_stream, "terminating");
}

static int add_target(daemon_config_t *cfg, const char *path, off_t rotate_size,
                      int keep_count, mode_t create_mode) {
    if (!cfg || !path) return -1;
    if (cfg->count >= MAX_LOGS) return -1;
    if (rotate_size <= 0) return -1;
    if (keep_count < 1 || keep_count > MAX_ROTATIONS) return -1;

    size_t len = strnlen(path, MAX_PATH_LEN);
    if (len == 0 || len >= MAX_PATH_LEN) return -1;

    log_target_t *t = &cfg->targets[cfg->count];
    memset(t, 0, sizeof(*t));
    memcpy(t->path, path, len);
    t->path[len] = '\0';
    t->rotate_size = rotate_size;
    t->keep_count = keep_count;
    t->create_mode = create_mode;
    t->enabled = true;

    cfg->count++;
    return 0;
}

static void init_default_config(daemon_config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->poll_interval_sec = DEFAULT_POLL_SEC;
    cfg->foreground = true;
    cfg->recreate = true;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [options] <logpath:size:keep> [<logpath:size:keep> ...]\n"
        "Options:\n"
        "  -f              Run in foreground\n"
        "  -d              Daemonize\n"
        "  -p <sec>        Poll interval seconds\n"
        "  -m <bytes>      Memory limit in bytes\n"
        "  -t              Truncate instead of rename rotation\n"
        "\n"
        "Example:\n"
        "  %s -f -p 2 -m 16777216 /var/log/app.log:10485760:5\n",
        prog, prog);
}

static int parse_target_spec(daemon_config_t *cfg, const char *spec) {
    char buf[MAX_PATH_LEN];
    char *p1, *p2;
    long long size_ll;
    long keep_l;

    size_t len = strnlen(spec, sizeof(buf));
    if (len == 0 || len >= sizeof(buf)) return -1;

    memcpy(buf, spec, len);
    buf[len] = '\0';

    p1 = strrchr(buf, ':');
    if (!p1) return -1;
    *p1++ = '\0';

    p2 = strrchr(buf, ':');
    if (!p2) return -1;
    *p2++ = '\0';

    errno = 0;
    size_ll = strtoll(p2, NULL, 10);
    if (errno != 0 || size_ll <= 0) return -1;

    errno = 0;
    keep_l = strtol(p1, NULL, 10);
    if (errno != 0 || keep_l <= 0 || keep_l > MAX_ROTATIONS) return -1;

    return add_target(cfg, buf, (off_t)size_ll, (int)keep_l, DEFAULT_CREATE_MODE);
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    rlim_t mem_limit = 0;
    int opt;

    init_default_config(&cfg);

    while ((opt = getopt(argc, argv, "fdp:m:t")) != -1) {
        switch (opt) {
            case 'f':
                cfg.foreground = true;
                break;
            case 'd':
                cfg.foreground = false;
                break;
            case 'p': {
                long v = strtol(optarg, NULL, 10);
                if (v <= 0 || v > 86400) {
                    usage(argv[0]);
                    return 1;
                }
                cfg.poll_interval_sec = (unsigned)v;
                break;
            }
            case 'm': {
                unsigned long long v = strtoull(optarg, NULL, 10);
                if (v == 0) {
                    usage(argv[0]);
                    return 1;
                }
                mem_limit = (rlim_t)v;
                break;
            }
            case 't':
                cfg.recreate = false;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    for (int i = optind; i < argc; ++i) {
        if (parse_target_spec(&cfg, argv[i]) < 0) {
            fprintf(stderr, "invalid target spec: %s\n", argv[i]);
            return 1;
        }
    }

    if (cfg.count == 0) {
        usage(argv[0]);
        return 1;
    }

    if (mem_limit > 0) {
        if (set_memory_limit_bytes(mem_limit) < 0) {
            perror("setrlimit");
            return 1;
        }
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    FILE *log_stream = stderr;

    if (!cfg.foreground) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
        log_stream = fopen("/dev/null", "w");
        if (!log_stream) {
            return 1;
        }
    }

    safe_log(log_stream, "started: targets=%zu poll=%u recreate=%d",
             cfg.count, cfg.poll_interval_sec, cfg.recreate ? 1 : 0);

    run_loop(&cfg, log_stream);

    if (!cfg.foreground && log_stream) {
        fclose(log_stream);
    }

    return 0;
}
