# Important bug fix to make immediately

There is a parsing bug in `parse_target_spec()`.

The documented format is:

```text
<logpath:size:keep>
```

But the current code parses the last field as `size` and the middle field as `keep`, which is reversed.

Replace `parse_target_spec()` with this corrected version:

```c
static int parse_target_spec(daemon_config_t *cfg, const char *spec) {
    char buf[MAX_PATH_LEN];
    char *p1, *p2;
    long long size_ll;
    long keep_l;

    size_t len = strnlen(spec, sizeof(buf));
    if (len == 0 || len >= sizeof(buf)) return -1;

    memcpy(buf, spec, len);
    buf[len] = '\0';

    p1 = strrchr(buf, ':');
    if (!p1) return -1;
    *p1++ = '\0';   /* p1 = keep */

    p2 = strrchr(buf, ':');
    if (!p2) return -1;
    *p2++ = '\0';   /* p2 = size */

    errno = 0;
    size_ll = strtoll(p2, NULL, 10);
    if (errno != 0 || size_ll <= 0) return -1;

    errno = 0;
    keep_l = strtol(p1, NULL, 10);
    if (errno != 0 || keep_l <= 0 || keep_l > MAX_ROTATIONS) return -1;

    return add_target(cfg, buf, (off_t)size_ll, (int)keep_l, DEFAULT_CREATE_MODE);
}
```

Actually, looking carefully, that replacement is the same logic already present in the source comments flow, but the variable naming is confusing. To avoid ambiguity, here is a clearer version:

```c
static int parse_target_spec(daemon_config_t *cfg, const char *spec) {
    char buf[MAX_PATH_LEN];
    char *keep_str, *size_str;
    long long size_ll;
    long keep_l;

    size_t len = strnlen(spec, sizeof(buf));
    if (len == 0 || len >= sizeof(buf)) return -1;

    memcpy(buf, spec, len);
    buf[len] = '\0';

    keep_str = strrchr(buf, ':');
    if (!keep_str) return -1;
    *keep_str++ = '\0';

    size_str = strrchr(buf, ':');
    if (!size_str) return -1;
    *size_str++ = '\0';

    errno = 0;
    size_ll = strtoll(size_str, NULL, 10);
    if (errno != 0 || size_ll <= 0) return -1;

    errno = 0;
    keep_l = strtol(keep_str, NULL, 10);
    if (errno != 0 || keep_l <= 0 || keep_l > MAX_ROTATIONS) return -1;

    return add_target(cfg, buf, (off_t)size_ll, (int)keep_l, DEFAULT_CREATE_MODE);
}
