# More robust rotation function

Here is a safer replacement for `rotate_one()`:

```c
static int rotate_one(const log_target_t *t, FILE *log_stream) {
    if (!t || !t->enabled) return -1;
    if (t->keep_count < 1 || t->keep_count > MAX_ROTATIONS) return -1;

    char src[MAX_PATH_LEN];
    char dst[MAX_PATH_LEN];

    if (build_rotated_path(dst, sizeof(dst), t->path, t->keep_count) < 0) {
        safe_log(log_stream, "path too long for oldest rotation");
        return -1;
    }
    if (unlink(dst) < 0 && errno != ENOENT) {
        safe_log(log_stream, "unlink failed %s: errno=%d", dst, errno);
        return -1;
    }

    for (int i = t->keep_count - 1; i >= 1; --i) {
        if (build_rotated_path(src, sizeof(src), t->path, i) < 0) {
            safe_log(log_stream, "path too long during rotation");
            return -1;
        }
        if (build_rotated_path(dst, sizeof(dst), t->path, i + 1) < 0) {
            safe_log(log_stream, "path too long during rotation");
            return -1;
        }

        if (rename(src, dst) < 0 && errno != ENOENT) {
            safe_log(log_stream, "rename failed %s -> %s: errno=%d", src, dst, errno);
            return -1;
        }
    }

    if (build_rotated_path(dst, sizeof(dst), t->path, 1) < 0) {
        safe_log(log_stream, "path too long for first rotation");
        return -1;
    }

    if (rename(t->path, dst) < 0) {
        safe_log(log_stream, "rename failed %s -> %s: errno=%d", t->path, dst, errno);
        return -1;
    }

    if (recreate_log_file(t->path, t->create_mode) < 0) {
        safe_log(log_stream, "recreate failed for %s: errno=%d", t->path, errno);
        return -1;
    }

    safe_log(log_stream, "rotated %s", t->path);
    return 0;
}
```

