# Source: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/file.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_MS 1000
#define DEFAULT_ROTATE_COUNT 5
#define DEFAULT_MAX_BYTES (10 * 1024 * 1024ULL)
#define DEFAULT_MAX_LINES 0ULL
#define LOCKFILE_SUFFIX ".lock"

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char log_path[PATH_MAX];
    char lock_path[PATH_MAX];
    unsigned int rotate_count;
    unsigned int poll_ms;
    unsigned long long max_bytes;
    unsigned long long max_lines;
    int daemonize;
};

struct state {
    unsigned long long last_counted_size;
    unsigned long long line_count;
    ino_t inode;
    dev_t dev;
    off_t last_scan_offset;
};

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int sleep_ms(unsigned int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) < 0) {
        if (errno == EINTR) {
            if (g_terminate || g_reload) return 0;
            continue;
        }
        return -1;
    }
    return 0;
}

static int make_lock_path(const char *log_path, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s%s", log_path, LOCKFILE_SUFFIX);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int acquire_lock(const char *lock_path) {
    int fd = open(lock_path, O_RDWR | O_CREAT, 0644);
    if (fd < 0) return -1;
    if (flock(fd, LOCK_EX | LOCK_NB) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    unsigned long v;
    errno = 0;
    v = strtoul(s, &end, 10);
    if (errno || !end || *end != '\0' || v > UINT_MAX) return -1;
    *out = (unsigned int)v;
    return 0;
}

static int parse_u64(const char *s, unsigned long long *out) {
    char *end = NULL;
    unsigned long long v;
    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno || !end || *end != '\0') return -1;
    *out = v;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) return -1;

    if (dup2(nullfd, STDIN_FILENO) < 0) return -1;
    if (dup2(nullfd, STDOUT_FILENO) < 0) return -1;
    if (dup2(nullfd, STDERR_FILENO) < 0) return -1;

    if (nullfd > STDERR_FILENO) close(nullfd);
    return 0;
}

static int path_with_index(const char *base, unsigned int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->rotate_count > 0) {
        if (path_with_index(cfg->log_path, cfg->rotate_count, oldp, sizeof(oldp)) < 0)
            return -1;
        unlink(oldp);

        for (unsigned int i = cfg->rotate_count; i > 1; --i) {
            if (path_with_index(cfg->log_path, i - 1, oldp, sizeof(oldp)) < 0)
                return -1;
            if (path_with_index(cfg->log_path, i, newp, sizeof(newp)) < 0)
                return -1;
            if (rename(oldp, newp) < 0 && errno != ENOENT)
                return -1;
        }

        if (path_with_index(cfg->log_path, 1, newp, sizeof(newp)) < 0)
            return -1;
        if (rename(cfg->log_path, newp) < 0) {
            if (errno != ENOENT) return -1;
        }
    } else {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT)
            return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int stat_log(const char *path, struct stat *st) {
    if (stat(path, st) < 0) return -1;
    return 0;
}

static int recount_lines_from_start(const char *path, unsigned long long *lines_out) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;

    char buf[4096];
    unsigned long long lines = 0;

    for (;;) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n < 0) {
            if (errno == EINTR) continue;
            close(fd);
            return -1;
        }
        if (n == 0) break;
        for (ssize_t i = 0; i < n; ++i) {
            if (buf[i] == '\n') lines++;
        }
    }

    close(fd);
    *lines_out = lines;
    return 0;
}

static int update_line_count_incremental(const char *path, struct state *st) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;

    if (lseek(fd, st->last_scan_offset, SEEK_SET) < 0) {
        close(fd);
        return -1;
    }

    char buf[4096];
    for (;;) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n < 0) {
            if (errno == EINTR) continue;
            close(fd);
            return -1;
        }
        if (n == 0) break;
        for (ssize_t i = 0; i < n; ++i) {
            if (buf[i] == '\n') st->line_count++;
        }
        st->last_scan_offset += (off_t)n;
    }

    close(fd);
    return 0;
}

static int refresh_state(const struct config *cfg, struct state *st) {
    struct stat sb;
    if (stat_log(cfg->log_path, &sb) < 0) {
        if (errno == ENOENT) {
            st->inode = 0;
            st->dev = 0;
            st->last_scan_offset = 0;
            st->last_counted_size = 0;
            st->line_count = 0;
            return 0;
        }
        return -1;
    }

    bool replaced = (st->inode != sb.st_ino || st->dev != sb.st_dev);
    bool shrunk = ((unsigned long long)sb.st_size < (unsigned long long)st->last_scan_offset);

    if (replaced || shrunk) {
        st->inode = sb.st_ino;
        st->dev = sb.st_dev;
        st->last_scan_offset = 0;
        st->last_counted_size = 0;
        st->line_count = 0;

        if (cfg->max_lines > 0) {
            if (recount_lines_from_start(cfg->log_path, &st->line_count) < 0)
                return -1;
            st->last_scan_offset = sb.st_size;
        } else {
            st->last_scan_offset = sb.st_size;
        }
    } else {
        st->inode = sb.st_ino;
        st->dev = sb.st_dev;
        if (cfg->max_lines > 0 && (unsigned long long)sb.st_size > (unsigned long long)st->last_scan_offset) {
            if (update_line_count_incremental(cfg->log_path, st) < 0)
                return -1;
        }
    }

    st->last_counted_size = (unsigned long long)sb.st_size;
    return 0;
}

static int should_rotate(const struct config *cfg, const struct state *st) {
    if (cfg->max_bytes > 0 && st->last_counted_size >= cfg->max_bytes) return 1;
    if (cfg->max_lines > 0 && st->line_count >= cfg->max_lines) return 1;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s --log PATH [options]\n"
        "Options:\n"
        "  --max-bytes N      Rotate when file size >= N bytes (default: %llu)\n"
        "  --max-lines N      Rotate when line count >= N (default: disabled)\n"
        "  --rotate-count N   Number of archives to keep (default: %u)\n"
        "  --poll-ms N        Poll interval in milliseconds (default: %u)\n"
        "  --daemonize        Run in background\n",
        prog,
        (unsigned long long)DEFAULT_MAX_BYTES,
        DEFAULT_ROTATE_COUNT,
        DEFAULT_POLL_MS
    );
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->rotate_count = DEFAULT_ROTATE_COUNT;
    cfg->poll_ms = DEFAULT_POLL_MS;
    cfg->max_bytes = DEFAULT_MAX_BYTES;
    cfg->max_lines = DEFAULT_MAX_LINES;
    cfg->daemonize = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--log") == 0) {
            if (++i >= argc) return -1;
            if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", argv[i]) >= (int)sizeof(cfg->log_path))
                return -1;
        } else if (strcmp(argv[i], "--max-bytes") == 0) {
            if (++i >= argc || parse_u64(argv[i], &cfg->max_bytes) < 0) return -1;
        } else if (strcmp(argv[i], "--max-lines") == 0) {
            if (++i >= argc || parse_u64(argv[i], &cfg->max_lines) < 0) return -1;
        } else if (strcmp(argv[i], "--rotate-count") == 0) {
            if (++i >= argc || parse_u32(argv[i], &cfg->rotate_count) < 0) return -1;
        } else if (strcmp(argv[i], "--poll-ms") == 0) {
            if (++i >= argc || parse_u32(argv[i], &cfg->poll_ms) < 0) return -1;
        } else if (strcmp(argv[i], "--daemonize") == 0) {
            cfg->daemonize = 1;
        } else {
            return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    if (make_lock_path(cfg->log_path, cfg->lock_path, sizeof(cfg->lock_path)) < 0) return -1;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    struct state st;
    memset(&st, 0, sizeof(st));

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signals() < 0) {
        log_stderr("failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    int lock_fd = acquire_lock(cfg.lock_path);
    if (lock_fd < 0) {
        log_stderr("failed to acquire lock on %s", cfg.lock_path);
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            log_stderr("failed to daemonize: %s", strerror(errno));
            close(lock_fd);
            return 1;
        }
    }

    for (;;) {
        if (g_terminate) break;

        if (g_reload) {
            g_reload = 0;
            memset(&st, 0, sizeof(st));
        }

        if (refresh_state(&cfg, &st) < 0) {
            log_stderr("refresh_state failed for %s: %s", cfg.log_path, strerror(errno));
        } else if (should_rotate(&cfg, &st)) {
            if (rotate_logs(&cfg) < 0) {
                log_stderr("rotate failed for %s: %s", cfg.log_path, strerror(errno));
            } else {
                memset(&st, 0, sizeof(st));
            }
        }

        if (sleep_ms(cfg.poll_ms) < 0) {
            log_stderr("sleep failed: %s", strerror(errno));
            break;
        }
    }

    close(lock_fd);
    return 0;
}
