## Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 32
#define LOGMSG_MAX    256

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_reload = 0;

typedef struct {
    char log_path[PATH_MAX];
    off_t rotate_size;
    unsigned int keep_count;
    unsigned int poll_interval_sec;
    int daemonize;
    int use_copytruncate;
    int verbose;
} config_t;

static void on_signal_term(int signo) {
    (void)signo;
    g_running = 0;
}

static void on_signal_hup(int signo) {
    (void)signo;
    g_reload = 1;
}

static void log_stderr(const char *fmt, ...) {
    char buf[LOGMSG_MAX];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    size_t len = strnlen(buf, sizeof(buf));
    if (len > 0) {
        (void)write(STDERR_FILENO, buf, len);
    }
    (void)write(STDERR_FILENO, "\n", 1);
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v > UINT32_MAX) {
        return -1;
    }
    *out = (unsigned int)v;
    return 0;
}

static int parse_size(const char *s, off_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s) {
        return -1;
    }

    unsigned long long mult = 1;
    if (*end != '\0') {
        if (end[1] != '\0') {
            return -1;
        }
        switch (*end) {
            case 'k': case 'K': mult = 1024ULL; break;
            case 'm': case 'M': mult = 1024ULL * 1024ULL; break;
            case 'g': case 'G': mult = 1024ULL * 1024ULL * 1024ULL; break;
            default: return -1;
        }
    }

    unsigned long long total = v * mult;
    if (mult != 0 && total / mult != v) {
        return -1;
    }

    *out = (off_t)total;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> -s <size> [options]\n"
        "Options:\n"
        "  -f <path>     Log file path\n"
        "  -s <size>     Rotate size, e.g. 1048576, 10M, 512K\n"
        "  -k <count>    Number of rotated files to keep (1-%d, default 5)\n"
        "  -p <sec>      Poll interval seconds (default 2)\n"
        "  -c            Use copytruncate instead of rename rotation\n"
        "  -d            Daemonize\n"
        "  -v            Verbose logging\n",
        prog, MAX_ROTATIONS);
}

static int build_rotated_path(const char *base, unsigned int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= out_sz) {
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int copy_file_truncate(const char *src, const char *dst) {
    int in_fd = -1, out_fd = -1;
    char buf[4096];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    if (r < 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    if (ftruncate(in_fd, 0) != 0) {
        close(in_fd);
        close(out_fd);
        return -1;
    }

    close(in_fd);
    close(out_fd);
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->keep_count == 0 || cfg->keep_count > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    if (cfg->use_copytruncate) {
        if (build_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        for (unsigned int i = cfg->keep_count; i > 1; --i) {
            if (build_rotated_path(cfg->log_path, i - 1, oldp, sizeof(oldp)) != 0 ||
                build_rotated_path(cfg->log_path, i, newp, sizeof(newp)) != 0) {
                errno = ENAMETOOLONG;
                return -1;
            }
            (void)rename(oldp, newp);
        }

        if (build_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        unlink(newp);
        return copy_file_truncate(cfg->log_path, newp);
    }

    for (unsigned int i = cfg->keep_count; i > 1; --i) {
        if (build_rotated_path(cfg->log_path, i - 1, oldp, sizeof(oldp)) != 0 ||
            build_rotated_path(cfg->log_path, i, newp, sizeof(newp)) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        (void)rename(oldp, newp);
    }

    if (build_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    unlink(newp);

    if (rename(cfg->log_path, newp) != 0) {
        return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int validate_config(const config_t *cfg) {
    if (cfg->log_path[0] == '\0') return -1;
    if (cfg->rotate_size <= 0) return -1;
    if (cfg->keep_count == 0 || cfg->keep_count > MAX_ROTATIONS) return -1;
    if (cfg->poll_interval_sec == 0) return -1;
    return 0;
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->keep_count = 5;
    cfg->poll_interval_sec = 2;

    while ((opt = getopt(argc, argv, "f:s:k:p:cdv")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                    return -1;
                }
                break;
            case 's':
                if (parse_size(optarg, &cfg->rotate_size) != 0) return -1;
                break;
            case 'k':
                if (parse_u32(optarg, &cfg->keep_count) != 0) return -1;
                break;
            case 'p':
                if (parse_u32(optarg, &cfg->poll_interval_sec) != 0) return -1;
                break;
            case 'c':
                cfg->use_copytruncate = 1;
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'v':
                cfg->verbose = 1;
                break;
            default:
                return -1;
        }
    }

    return validate_config(cfg);
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal_term;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;

    sa.sa_handler = on_signal_hup;
    if (sigaction(SIGHUP, &sa, NULL) != 0) return -1;

    signal(SIGPIPE, SIG_IGN);
    return 0;
}

static int check_and_rotate(const config_t *cfg) {
    struct stat st;

    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size < cfg->rotate_size) {
        return 0;
    }

    if (cfg->verbose) {
        log_stderr("rotating %s size=%lld threshold=%lld",
                   cfg->log_path,
                   (long long)st.st_size,
                   (long long)cfg->rotate_size);
    }

    return rotate_logs(cfg);
}

int main(int argc, char **argv) {
    config_t cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signal_handlers() != 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_self() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (cfg.verbose) {
        log_stderr("memlogd starting: file=%s size=%lld keep=%u poll=%u copytruncate=%d",
                   cfg.log_path,
                   (long long)cfg.rotate_size,
                   cfg.keep_count,
                   cfg.poll_interval_sec,
                   cfg.use_copytruncate);
    }

    while (g_running) {
        if (g_reload) {
            g_reload = 0;
            if (cfg.verbose) {
                log_stderr("received SIGHUP");
            }
        }

        if (check_and_rotate(&cfg) != 0) {
            if (cfg.verbose) {
                log_stderr("check_and_rotate error: %s", strerror(errno));
            }
        }

        for (unsigned int i = 0; i < cfg.poll_interval_sec && g_running; ++i) {
            sleep(1);
        }
    }

    if (cfg.verbose) {
        log_stderr("memlogd exiting");
    }

    return 0;
}
