# Initial implementation: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define LR_MAX_PATH         512
#define LR_MAX_ROTATIONS    16
#define LR_POLL_INTERVAL_S  1
#define LR_PIDFILE_PATH     "/tmp/logrotated.pid"

typedef struct {
    char log_path[LR_MAX_PATH];
    size_t max_size_bytes;
    unsigned int rotate_interval_sec;
    unsigned int max_rotations;
    unsigned int poll_interval_sec;
    bool daemonize;
} lr_config_t;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_force_rotate = 0;

static void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_running = 0;
    } else if (sig == SIGHUP) {
        g_force_rotate = 1;
    }
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int write_pidfile(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;

    char buf[32];
    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    ssize_t wr = write(fd, buf, (size_t)len);
    close(fd);
    return (wr == len) ? 0 : -1;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) return -1;

    if (dup2(nullfd, STDIN_FILENO) < 0) return -1;
    if (dup2(nullfd, STDOUT_FILENO) < 0) return -1;
    if (dup2(nullfd, STDERR_FILENO) < 0) return -1;

    if (nullfd > STDERR_FILENO) close(nullfd);
    return 0;
}

static int get_file_size(const char *path, off_t *size_out, time_t *mtime_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    if (size_out) *size_out = st.st_size;
    if (mtime_out) *mtime_out = st.st_mtime;
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, unsigned int idx) {
    int n = snprintf(dst, dst_sz, "%s.%u", base, idx);
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int rotate_files(const lr_config_t *cfg) {
    if (cfg->max_rotations == 0 || cfg->max_rotations > LR_MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    char old_path[LR_MAX_PATH];
    char new_path[LR_MAX_PATH];

    /* Remove oldest */
    if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) < 0) {
        return -1;
    }
    (void)unlink(old_path);

    /* Shift N-1 ... 1 upward */
    for (int i = (int)cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, (unsigned int)i) < 0) {
            return -1;
        }
        if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, (unsigned int)(i + 1)) < 0) {
            return -1;
        }

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Rotate current log to .1 */
    if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty log file */
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int validate_config(const lr_config_t *cfg) {
    if (!cfg) return -1;
    if (cfg->log_path[0] == '\0') return -1;
    if (strnlen(cfg->log_path, LR_MAX_PATH) >= LR_MAX_PATH) return -1;
    if (cfg->max_rotations == 0 || cfg->max_rotations > LR_MAX_ROTATIONS) return -1;
    if (cfg->poll_interval_sec == 0) return -1;
    return 0;
}

static int should_rotate(const lr_config_t *cfg, time_t start_time, off_t size_now) {
    if (g_force_rotate) return 1;

    if (cfg->max_size_bytes > 0 && (size_t)size_now >= cfg->max_size_bytes) {
        return 1;
    }

    if (cfg->rotate_interval_sec > 0) {
        time_t now = time(NULL);
        if (now == (time_t)-1) return 0;
        if ((unsigned int)(now - start_time) >= cfg->rotate_interval_sec) {
            return 1;
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    (void)argc;
    (void)argv;

    lr_config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    /* Initial hardcoded config for first implementation */
    {
        const char *default_path = "/tmp/app.log";
        size_t len = strnlen(default_path, sizeof(cfg.log_path) - 1);
        memcpy(cfg.log_path, default_path, len);
        cfg.log_path[len] = '\0';

        cfg.max_size_bytes = 1024 * 1024;   /* 1 MiB */
        cfg.rotate_interval_sec = 3600;     /* 1 hour */
        cfg.max_rotations = 5;
        cfg.poll_interval_sec = LR_POLL_INTERVAL_S;
        cfg.daemonize = false;
    }

    if (validate_config(&cfg) < 0) {
        fprintf(stderr, "invalid config\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            return 1;
        }
        if (write_pidfile(LR_PIDFILE_PATH) < 0) {
            return 1;
        }
    }

    time_t last_rotation_time = time(NULL);
    if (last_rotation_time == (time_t)-1) {
        perror("time");
        return 1;
    }

    while (g_running) {
        off_t size_now = 0;
        time_t mtime_now = 0;

        if (get_file_size(cfg.log_path, &size_now, &mtime_now) < 0) {
            if (errno == ENOENT) {
                int fd = open(cfg.log_path, O_WRONLY | O_CREAT, 0644);
                if (fd >= 0) close(fd);
            }
        } else {
            if (should_rotate(&cfg, last_rotation_time, size_now)) {
                if (rotate_files(&cfg) == 0) {
                    last_rotation_time = time(NULL);
                    g_force_rotate = 0;
                }
            }
        }

        sleep(cfg.poll_interval_sec);
    }

    if (cfg.daemonize) {
        unlink(LR_PIDFILE_PATH);
    }

    return 0;
}
```

