## Source: `memlogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS            32
#define MAX_ROTATIONS       16
#define MAX_PATH_LEN        512
#define DEFAULT_INTERVAL_S  5
#define DEFAULT_MAX_SIZE    (10 * 1024 * 1024)
#define DEFAULT_ROTATIONS   5
#define PIDFILE_PATH        "/tmp/memlogd.pid"

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int rotations;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    int log_count;
    unsigned interval_s;
    int daemonize;
    rlim_t memory_limit_bytes;
} daemon_config_t;

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static int safe_str_copy(char *dst, size_t dst_sz, const char *src) {
    size_t len;
    if (!dst || !src || dst_sz == 0) return -1;
    len = strnlen(src, dst_sz);
    if (len >= dst_sz) return -1;
    memcpy(dst, src, len + 1);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n;
    if (!out || !base || out_sz == 0) return -1;
    n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    if (bytes == 0) return 0;

    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;

#ifdef RLIMIT_AS
    if (setrlimit(RLIMIT_AS, &rl) < 0) {
        perror("setrlimit(RLIMIT_AS)");
        return -1;
    }
#endif

#ifdef RLIMIT_DATA
    if (setrlimit(RLIMIT_DATA, &rl) < 0) {
        perror("setrlimit(RLIMIT_DATA)");
        return -1;
    }
#endif

    return 0;
}

static int write_pidfile(const char *path) {
    int fd;
    char buf[64];
    int len;

    fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open pidfile");
        return -1;
    }

    len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)len) != len) {
        perror("write pidfile");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int daemonize_process(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (!path || !size_out) return -1;
    if (stat(path, &st) < 0) return -1;
    if (!S_ISREG(st.st_mode)) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_one(const log_config_t *log) {
    int i;
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    if (!log) return -1;
    if (log->rotations < 1 || log->rotations > MAX_ROTATIONS) return -1;

    /* Remove the oldest rotation */
    if (path_with_suffix(oldp, sizeof(oldp), log->path, log->rotations) == 0) {
        (void)unlink(oldp);
    }

    /* Shift N-1 down to 1 */
    for (i = log->rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), log->path, i) < 0) return -1;
        if (path_with_suffix(newp, sizeof(newp), log->path, i + 1) < 0) return -1;

        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Move active log to .1 */
    if (path_with_suffix(newp, sizeof(newp), log->path, 1) < 0) return -1;
    if (rename(log->path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    /* Recreate empty active log */
    {
        int fd = open(log->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
    }

    return 0;
}

static void check_and_rotate(const daemon_config_t *cfg) {
    int i;
    for (i = 0; i < cfg->log_count; ++i) {
        off_t sz = 0;
        if (file_size(cfg->logs[i].path, &sz) == 0) {
            if (sz >= cfg->logs[i].max_size) {
                if (rotate_one(&cfg->logs[i]) < 0) {
                    /* Best effort only in initial implementation */
                }
            }
        }
    }
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] [-i interval] [-m mem_bytes] "
        "[-s max_size] [-r rotations] log1 [log2 ...]\n",
        prog);
}

static int parse_off_t(const char *s, off_t *out) {
    long long v;
    char *end = NULL;
    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno || !end || *end != '\0' || v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

static int parse_uint(const char *s, unsigned *out) {
    unsigned long v;
    char *end = NULL;
    errno = 0;
    v = strtoul(s, &end, 10);
    if (errno || !end || *end != '\0') return -1;
    *out = (unsigned)v;
    return 0;
}

static int parse_rlim(const char *s, rlim_t *out) {
    unsigned long long v;
    char *end = NULL;
    errno = 0;
    v = strtoull(s, &end, 10);
    if (errno || !end || *end != '\0') return -1;
    *out = (rlim_t)v;
    return 0;
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    int opt;
    int i;
    off_t default_max_size = DEFAULT_MAX_SIZE;
    int default_rotations = DEFAULT_ROTATIONS;

    memset(&cfg, 0, sizeof(cfg));
    cfg.interval_s = DEFAULT_INTERVAL_S;
    cfg.memory_limit_bytes = 0;
    cfg.daemonize = 0;

    while ((opt = getopt(argc, argv, "di:m:s:r:")) != -1) {
        switch (opt) {
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'i':
                if (parse_uint(optarg, &cfg.interval_s) < 0 || cfg.interval_s == 0) {
                    fprintf(stderr, "Invalid interval\n");
                    return 1;
                }
                break;
            case 'm':
                if (parse_rlim(optarg, &cfg.memory_limit_bytes) < 0) {
                    fprintf(stderr, "Invalid memory limit\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_off_t(optarg, &default_max_size) < 0 || default_max_size <= 0) {
                    fprintf(stderr, "Invalid max size\n");
                    return 1;
                }
                break;
            case 'r':
                default_rotations = atoi(optarg);
                if (default_rotations < 1 || default_rotations > MAX_ROTATIONS) {
                    fprintf(stderr, "Invalid rotations\n");
                    return 1;
                }
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return 1;
    }

    for (i = optind; i < argc; ++i) {
        if (cfg.log_count >= MAX_LOGS) {
            fprintf(stderr, "Too many log files (max %d)\n", MAX_LOGS);
            return 1;
        }

        if (safe_str_copy(cfg.logs[cfg.log_count].path,
                          sizeof(cfg.logs[cfg.log_count].path),
                          argv[i]) < 0) {
            fprintf(stderr, "Path too long: %s\n", argv[i]);
            return 1;
        }

        cfg.logs[cfg.log_count].max_size = default_max_size;
        cfg.logs[cfg.log_count].rotations = default_rotations;
        cfg.log_count++;
    }

    if (install_signal_handlers() < 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (write_pidfile(PIDFILE_PATH) < 0) {
        return 1;
    }

    if (set_memory_limit(cfg.memory_limit_bytes) < 0) {
        return 1;
    }

    while (g_running) {
        check_and_rotate(&cfg);
        sleep(cfg.interval_s);
    }

    unlink(PIDFILE_PATH);
    return 0;
}
