# Initial implementation: `memlogd.c`

```c
/*
 * memlogd.c
 *
 * A small memory-constrained log rotation daemon.
 *
 * Characteristics:
 * - fixed-size configuration
 * - no heap allocation in steady-state
 * - polling-based file size checks
 * - simple rename-based rotation
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f
 *
 * Notes:
 * - This is an initial implementation, not a hardened production daemon.
 * - Rotation is based on file size only.
 * - Paths are fixed-size and must fit within PATH_MAX_LEN.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX_LEN
#define PATH_MAX_LEN 256
#endif

#ifndef MAX_LOGS
#define MAX_LOGS 16
#endif

#ifndef MAX_ROTATIONS
#define MAX_ROTATIONS 16
#endif

#ifndef DEFAULT_POLL_INTERVAL_SEC
#define DEFAULT_POLL_INTERVAL_SEC 5
#endif

#ifndef DEFAULT_MAX_SIZE
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#endif

typedef struct {
    char path[PATH_MAX_LEN];
    off_t max_size;
    int rotations;
    mode_t create_mode;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    int log_count;
    unsigned poll_interval_sec;
    bool foreground;
} daemon_config_t;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_reload_requested = 0;

/* Minimal stderr logger to avoid extra dependencies */
static void log_msg(const char *level, const char *fmt, ...)
{
    char buf[512];
    int off = 0;

    off = snprintf(buf, sizeof(buf), "[%s] ", level);
    if (off < 0 || (size_t)off >= sizeof(buf)) {
        return;
    }

    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf + off, sizeof(buf) - (size_t)off, fmt, ap);
    va_end(ap);

    if (n < 0) {
        return;
    }

    size_t len = strnlen(buf, sizeof(buf));
    if (len + 1 < sizeof(buf)) {
        buf[len] = '\n';
        buf[len + 1] = '\0';
        len++;
    }

    (void)write(STDERR_FILENO, buf, len);
}

static void handle_signal(int signo)
{
    if (signo == SIGTERM || signo == SIGINT) {
        g_running = 0;
    } else if (signo == SIGHUP) {
        g_reload_requested = 1;
    }
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;

    return 0;
}

static int daemonize_process(void)
{
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") < 0) {
        return -1;
    }

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    (void)dup2(fd, STDIN_FILENO);
    (void)dup2(fd, STDOUT_FILENO);
    (void)dup2(fd, STDERR_FILENO);

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, int suffix)
{
    int n;
    if (suffix <= 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%d", base, suffix);
    }

    if (n < 0 || (size_t)n >= dst_sz) {
        return -1;
    }
    return 0;
}

static int ensure_file_exists(const log_config_t *cfg)
{
    struct stat st;
    if (stat(cfg->path, &st) == 0) {
        return 0;
    }

    if (errno != ENOENT) {
        return -1;
    }

    int fd = open(cfg->path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }

    close(fd);
    return 0;
}

static int rotate_log(const log_config_t *cfg)
{
    if (cfg->rotations < 1 || cfg->rotations > MAX_ROTATIONS) {
        errno = EINVAL;
        return -1;
    }

    char old_path[PATH_MAX_LEN];
    char new_path[PATH_MAX_LEN];

    /* Delete oldest: file.N */
    if (safe_snprintf_path(old_path, sizeof(old_path), cfg->path, cfg->rotations) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    (void)unlink(old_path);

    /* Shift file.(N-1) -> file.N ... file.1 -> file.2 */
    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), cfg->path, i) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (safe_snprintf_path(new_path, sizeof(new_path), cfg->path, i + 1) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* file -> file.1 */
    if (safe_snprintf_path(new_path, sizeof(new_path), cfg->path, 1) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(cfg->path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty log file */
    int fd = open(cfg->path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int check_and_rotate(const log_config_t *cfg)
{
    struct stat st;
    if (stat(cfg->path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_file_exists(cfg);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_log(cfg);
    }

    return 0;
}

static void sleep_interruptible(unsigned sec)
{
    struct timespec req, rem;
    req.tv_sec = sec;
    req.tv_nsec = 0;

    while (g_running) {
        if (nanosleep(&req, &rem) == 0) {
            break;
        }
        if (errno == EINTR) {
            if (g_reload_requested) {
                break;
            }
            req = rem;
            continue;
        }
        break;
    }
}

static void init_default_config(daemon_config_t *cfg)
{
    memset(cfg, 0, sizeof(*cfg));
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL_SEC;
    cfg->foreground = false;

    /* Example fixed configuration */
    cfg->log_count = 2;

    snprintf(cfg->logs[0].path, sizeof(cfg->logs[0].path), "/tmp/app.log");
    cfg->logs[0].max_size = DEFAULT_MAX_SIZE;
    cfg->logs[0].rotations = 5;
    cfg->logs[0].create_mode = 0644;

    snprintf(cfg->logs[1].path, sizeof(cfg->logs[1].path), "/tmp/worker.log");
    cfg->logs[1].max_size = DEFAULT_MAX_SIZE;
    cfg->logs[1].rotations = 3;
    cfg->logs[1].create_mode = 0644;
}

static int parse_args(daemon_config_t *cfg, int argc, char **argv)
{
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-f") == 0 || strcmp(argv[i], "--foreground") == 0) {
            cfg->foreground = true;
        } else if ((strcmp(argv[i], "-i") == 0 || strcmp(argv[i], "--interval") == 0) && i + 1 < argc) {
            unsigned long v = 0;
            const char *s = argv[++i];
            for (const char *p = s; *p; ++p) {
                if (*p < '0' || *p > '9') {
                    return -1;
                }
                v = v * 10 + (unsigned long)(*p - '0');
                if (v > 86400UL) {
                    return -1;
                }
            }
            if (v == 0) {
                return -1;
            }
            cfg->poll_interval_sec = (unsigned)v;
        } else {
            return -1;
        }
    }
    return 0;
}

static void usage(const char *prog)
{
    dprintf(STDERR_FILENO,
            "Usage: %s [-f|--foreground] [-i|--interval SEC]\n",
            prog);
}

int main(int argc, char **argv)
{
    daemon_config_t cfg;
    init_default_config(&cfg);

    if (parse_args(&cfg, argc, argv) < 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signal_handlers() < 0) {
        log_msg("ERROR", "failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    if (!cfg.foreground) {
        if (daemonize_process() < 0) {
            log_msg("ERROR", "failed to daemonize: %s", strerror(errno));
            return 1;
        }
    }

    for (int i = 0; i < cfg.log_count; ++i) {
        if (ensure_file_exists(&cfg.logs[i]) < 0) {
            log_msg("WARN", "failed to ensure log exists '%s': %s",
                    cfg.logs[i].path, strerror(errno));
        }
    }

    while (g_running) {
        for (int i = 0; i < cfg.log_count; ++i) {
            if (check_and_rotate(&cfg.logs[i]) < 0) {
                log_msg("WARN", "check/rotate failed for '%s': %s",
                        cfg.logs[i].path, strerror(errno));
            }
        }

        if (g_reload_requested) {
            /*
             * Placeholder for future config reload support.
             * In this initial version we simply clear the flag and continue.
             */
            g_reload_requested = 0;
            log_msg("INFO", "received SIGHUP");
        }

        sleep_interruptible(cfg.poll_interval_sec);
    }

    log_msg("INFO", "shutting down");
    return 0;
}
```

