# `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX_FIXED
#define PATH_MAX_FIXED 512
#endif

#ifndef LOG_MSG_MAX
#define LOG_MSG_MAX 256
#endif

#ifndef DEFAULT_POLL_MS
#define DEFAULT_POLL_MS 1000
#endif

#ifndef DEFAULT_ROTATIONS
#define DEFAULT_ROTATIONS 5
#endif

#ifndef DEFAULT_MAX_SIZE
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024ULL)
#endif

static volatile sig_atomic_t g_stop = 0;

struct config {
    char log_path[PATH_MAX_FIXED];
    uint64_t max_size;
    unsigned int rotations;
    unsigned int poll_ms;
    int verbose;
};

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_log(int verbose, const char *fmt, ...) {
    if (!verbose) {
        return;
    }

    char buf[LOG_MSG_MAX];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n < 0) {
        return;
    }

    size_t len = (size_t)n;
    if (len >= sizeof(buf)) {
        len = sizeof(buf) - 1;
    }

    buf[len++] = '\n';
    (void)write(STDERR_FILENO, buf, len);
}

static int parse_u64(const char *s, uint64_t *out) {
    if (!s || !*s || !out) {
        return -1;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }

    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out) {
    uint64_t tmp;
    if (parse_u64(s, &tmp) != 0 || tmp > 0xffffffffULL) {
        return -1;
    }
    *out = (unsigned int)tmp;
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s --log PATH [--size BYTES] [--rotations N] [--poll-ms MS] [--verbose]\n",
        prog);
}

static int path_with_suffix(char *dst, size_t dst_sz, const char *base, unsigned int suffix) {
    int n = snprintf(dst, dst_sz, "%s.%u", base, suffix);
    if (n < 0 || (size_t)n >= dst_sz) {
        return -1;
    }
    return 0;
}

static int ensure_base_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[PATH_MAX_FIXED];
    char new_path[PATH_MAX_FIXED];

    if (cfg->rotations == 0) {
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            return -1;
        }
        return ensure_base_exists(cfg);
    }

    if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, cfg->rotations) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (unlink(old_path) != 0 && errno != ENOENT) {
        return -1;
    }

    for (unsigned int i = cfg->rotations; i > 1; --i) {
        if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, i - 1) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, i) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (rename(old_path, new_path) != 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, 1) != 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return ensure_base_exists(cfg);
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            return ensure_base_exists(cfg);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if ((uint64_t)st.st_size < cfg->max_size) {
        return 0;
    }

    safe_log(cfg->verbose, "rotating log: %s size=%" PRIu64, cfg->log_path, (uint64_t)st.st_size);
    return rotate_logs(cfg);
}

static void sleep_poll(unsigned int poll_ms) {
    struct timespec ts;
    ts.tv_sec = poll_ms / 1000U;
    ts.tv_nsec = (long)(poll_ms % 1000U) * 1000000L;

    while (!g_stop) {
        if (nanosleep(&ts, &ts) == 0) {
            break;
        }
        if (errno != EINTR) {
            break;
        }
    }
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        return -1;
    }
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->poll_ms = DEFAULT_POLL_MS;
    cfg->verbose = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--log") == 0) {
            if (++i >= argc) return -1;
            size_t len = strnlen(argv[i], sizeof(cfg->log_path));
            if (len == 0 || len >= sizeof(cfg->log_path)) {
                return -1;
            }
            memcpy(cfg->log_path, argv[i], len);
            cfg->log_path[len] = '\0';
        } else if (strcmp(argv[i], "--size") == 0) {
            if (++i >= argc) return -1;
            if (parse_u64(argv[i], &cfg->max_size) != 0 || cfg->max_size == 0) {
                return -1;
            }
        } else if (strcmp(argv[i], "--rotations") == 0) {
            if (++i >= argc) return -1;
            if (parse_u32(argv[i], &cfg->rotations) != 0) {
                return -1;
            }
        } else if (strcmp(argv[i], "--poll-ms") == 0) {
            if (++i >= argc) return -1;
            if (parse_u32(argv[i], &cfg->poll_ms) != 0 || cfg->poll_ms == 0) {
                return -1;
            }
        } else if (strcmp(argv[i], "--verbose") == 0) {
            cfg->verbose = 1;
        } else {
            return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signals() != 0) {
        perror("install_signals");
        return 1;
    }

    if (ensure_base_exists(&cfg) != 0) {
        perror("ensure_base_exists");
        return 1;
    }

    safe_log(cfg.verbose,
             "started: log=%s size=%" PRIu64 " rotations=%u poll_ms=%u",
             cfg.log_path, cfg.max_size, cfg.rotations, cfg.poll_ms);

    while (!g_stop) {
        if (check_and_rotate(&cfg) != 0) {
            safe_log(cfg.verbose, "error: %s", strerror(errno));
        }
        sleep_poll(cfg.poll_ms);
    }

    safe_log(cfg.verbose, "stopped");
    return 0;
}
