Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed with **strict memory limits** in mind.

It aims to:
- avoid dynamic allocation where practical
- use fixed-size buffers
- monitor a configured log file
- rotate when size exceeds a threshold
- keep a fixed number of rotated files
- run as a daemon
- maintain a small memory footprint

---

## Features

- Fixed memory usage
- No heap allocation in normal operation
- Simple polling loop
- Size-based rotation
- Configurable:
  - log path
  - max size
  - number of backups
  - poll interval
- Basic signal handling for clean shutdown

---

## Initial implementation

```c
/*
 * memlogd.c
 *
 * A memory-constrained log rotation daemon.
 *
 * Features:
 *  - Fixed-size configuration and path buffers
 *  - No dynamic allocation in steady-state operation
 *  - Size-based log rotation
 *  - Keeps N rotated files: logfile.1 ... logfile.N
 *  - Polling-based monitoring
 *  - Daemonizes itself
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd /var/log/myapp.log 1048576 5 2
 *   -> rotate when file exceeds 1 MiB, keep 5 backups, poll every 2 sec
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_BACKUPS 16
#define MIN_POLL_INTERVAL 1
#define DEFAULT_UMASK 022

typedef struct {
    char log_path[PATH_MAX];
    off_t max_size;
    int backup_count;
    unsigned int poll_interval_sec;
    int foreground;
} config_t;

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int parse_positive_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    if (s == NULL || *s == '\0' || out == NULL) return -1;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v <= 0 || v > 2147483647L) {
        return -1;
    }

    *out = (int)v;
    return 0;
}

static int parse_positive_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    if (s == NULL || *s == '\0' || out == NULL) return -1;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v <= 0) {
        return -1;
    }

    *out = (off_t)v;
    return 0;
}

static int safe_snprintf_path(char *dst, size_t dstsz, const char *base, int suffix) {
    int n;
    if (dst == NULL || dstsz == 0 || base == NULL) return -1;

    n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dstsz) return -1;

    return 0;
}

static int daemonize_process(void) {
    pid_t pid;
    int fd;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    umask(DEFAULT_UMASK);

    if (chdir("/") < 0) return -1;

    fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) {
        close(fd);
        return -1;
    }
    if (dup2(fd, STDOUT_FILENO) < 0) {
        close(fd);
        return -1;
    }
    if (dup2(fd, STDERR_FILENO) < 0) {
        close(fd);
        return -1;
    }

    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int file_size_exceeds(const char *path, off_t max_size) {
    struct stat st;

    if (stat(path, &st) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        return -1;
    }

    return (st.st_size >= max_size) ? 1 : 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    int i;

    if (cfg == NULL) return -1;

    /* Remove oldest backup */
    if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, cfg->backup_count) < 0) {
        return -1;
    }
    (void)unlink(old_path);

    /* Shift backups upward: log.(n-1) -> log.n */
    for (i = cfg->backup_count - 1; i >= 1; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, i) < 0) {
            return -1;
        }
        if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0) {
            return -1;
        }

        if (rename(old_path, new_path) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Current log -> log.1 */
    if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /*
     * Recreate the log file so writers expecting it to exist can continue.
     * Note: applications holding the old file descriptor will continue writing
     * to the renamed file unless they reopen the log.
     */
    {
        int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
    }

    return 0;
}

static int validate_config(config_t *cfg) {
    size_t len;
    if (cfg == NULL) return -1;

    len = strnlen(cfg->log_path, sizeof(cfg->log_path));
    if (len == 0 || len >= sizeof(cfg->log_path)) return -1;
    if (cfg->max_size <= 0) return -1;
    if (cfg->backup_count <= 0 || cfg->backup_count > MAX_BACKUPS) return -1;
    if (cfg->poll_interval_sec < MIN_POLL_INTERVAL) return -1;

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s [-f] <log_path> <max_size_bytes> <backup_count> <poll_interval_sec>\n"
            "  -f    run in foreground\n"
            "Constraints:\n"
            "  backup_count: 1..%d\n"
            "  poll_interval_sec: >= %d\n",
            prog, MAX_BACKUPS, MIN_POLL_INTERVAL);
}

int main(int argc, char **argv) {
    config_t cfg;
    int argi = 1;
    int tmp;

    memset(&cfg, 0, sizeof(cfg));
    cfg.foreground = 0;

    if (argc > 1 && strcmp(argv[1], "-f") == 0) {
        cfg.foreground = 1;
        argi++;
    }

    if (argc - argi != 4) {
        usage(argv[0]);
        return 1;
    }

    if (strnlen(argv[argi], sizeof(cfg.log_path)) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }
    strncpy(cfg.log_path, argv[argi], sizeof(cfg.log_path) - 1);
    cfg.log_path[sizeof(cfg.log_path) - 1] = '\0';
    argi++;

    if (parse_positive_offt(argv[argi], &cfg.max_size) < 0) {
        fprintf(stderr, "invalid max_size_bytes\n");
        return 1;
    }
    argi++;

    if (parse_positive_int(argv[argi], &cfg.backup_count) < 0) {
        fprintf(stderr, "invalid backup_count\n");
        return 1;
    }
    argi++;

    if (parse_positive_int(argv[argi], &tmp) < 0) {
        fprintf(stderr, "invalid poll_interval_sec\n");
        return 1;
    }
    cfg.poll_interval_sec = (unsigned int)tmp;

    if (validate_config(&cfg) < 0) {
        fprintf(stderr, "invalid configuration\n");
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (!cfg.foreground) {
        if (daemonize_process() < 0) {
            perror("daemonize_process");
            return 1;
        }
    }

    while (g_running) {
        int rc = file_size_exceeds(cfg.log_path, cfg.max_size);
        if (rc < 0) {
            /* In a strict-memory daemon, keep error handling simple and cheap. */
        } else if (rc > 0) {
            (void)rotate_logs(&cfg);
        }

        sleep(cfg.poll_interval_sec);
    }

    return 0;
}
