## Source: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS            16
#define MAX_RETENTION       16
#define IO_BUFFER_SIZE      4096
#define DEFAULT_INTERVAL_S  5
#define DEFAULT_RETENTION   5
#define DEFAULT_MAX_BYTES   (10 * 1024 * 1024)

typedef struct {
    char path[PATH_MAX];
    off_t max_bytes;
    int retention;
    ino_t last_inode;
    dev_t last_dev;
    off_t last_size;
    int initialized;
} log_target_t;

typedef struct {
    int interval_s;
    int daemonize;
    int verbose;
    int log_count;
    log_target_t logs[MAX_LOGS];
} config_t;

static volatile sig_atomic_t g_running = 1;
static char g_io_buffer[IO_BUFFER_SIZE];

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(int verbose, const char *fmt, ...) {
    if (!verbose) return;

    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    dprintf(STDERR_FILENO, "%s\n", buf);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int copy_file_contents(const char *src, const char *dst) {
    int sfd = -1, dfd = -1;
    int rc = -1;

    sfd = open(src, O_RDONLY);
    if (sfd < 0) goto out;

    dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dfd < 0) goto out;

    for (;;) {
        ssize_t r = read(sfd, g_io_buffer, sizeof(g_io_buffer));
        if (r == 0) break;
        if (r < 0) {
            if (errno == EINTR) continue;
            goto out;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dfd, g_io_buffer + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                goto out;
            }
            off += w;
        }
    }

    if (fsync(dfd) < 0) goto out;
    rc = 0;

out:
    if (sfd >= 0) close(sfd);
    if (dfd >= 0) close(dfd);
    return rc;
}

static int truncate_file(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int rc = ftruncate(fd, 0);
    close(fd);
    return rc;
}

static int rotate_one(log_target_t *t, int verbose) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    log_msg(verbose, "rotating: %s", t->path);

    if (t->retention < 1) {
        return truncate_file(t->path);
    }

    if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", t->path, t->retention) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }
    unlink(oldp);

    for (int i = t->retention - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", t->path, i) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", t->path, i + 1) < 0) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (safe_snprintf(newp, sizeof(newp), "%s.1", t->path) < 0) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(t->path, newp) == 0) {
        int fd = open(t->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    if (errno == EXDEV) {
        if (copy_file_contents(t->path, newp) < 0) return -1;
        if (truncate_file(t->path) < 0) return -1;
        return 0;
    }

    return -1;
}

static int stat_target(log_target_t *t, struct stat *st) {
    if (stat(t->path, st) < 0) {
        return -1;
    }
    return 0;
}

static int maybe_rotate(log_target_t *t, int verbose) {
    struct stat st;
    if (stat_target(t, &st) < 0) {
        if (errno != ENOENT) {
            log_msg(verbose, "stat failed for %s: %s", t->path, strerror(errno));
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg(verbose, "not a regular file: %s", t->path);
        return -1;
    }

    if (!t->initialized) {
        t->last_inode = st.st_ino;
        t->last_dev = st.st_dev;
        t->last_size = st.st_size;
        t->initialized = 1;
    } else {
        if (t->last_inode != st.st_ino || t->last_dev != st.st_dev) {
            log_msg(verbose, "file replaced externally: %s", t->path);
            t->last_inode = st.st_ino;
            t->last_dev = st.st_dev;
            t->last_size = st.st_size;
        } else {
            t->last_size = st.st_size;
        }
    }

    if (st.st_size >= t->max_bytes) {
        if (rotate_one(t, verbose) < 0) {
            log_msg(verbose, "rotation failed for %s: %s", t->path, strerror(errno));
            return -1;
        }

        if (stat_target(t, &st) == 0) {
            t->last_inode = st.st_ino;
            t->last_dev = st.st_dev;
            t->last_size = st.st_size;
            t->initialized = 1;
        } else {
            t->initialized = 0;
        }
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s [-d] [-v] [-i interval] "
        "-l path:max_bytes[:retention] [-l ...]\n"
        "\n"
        "Options:\n"
        "  -d                 Daemonize\n"
        "  -v                 Verbose logging to stderr\n"
        "  -i interval        Poll interval in seconds (default %d)\n"
        "  -l spec            Log spec: /path/to/log:bytes[:retention]\n"
        "\n"
        "Defaults:\n"
        "  retention          %d\n"
        "  max_bytes          %d\n",
        prog, DEFAULT_INTERVAL_S, DEFAULT_RETENTION, DEFAULT_MAX_BYTES);
}

static int parse_log_spec(config_t *cfg, const char *spec) {
    if (cfg->log_count >= MAX_LOGS) {
        return -1;
    }

    char tmp[PATH_MAX + 64];
    if (strlen(spec) >= sizeof(tmp)) {
        errno = ENAMETOOLONG;
        return -1;
    }
    strcpy(tmp, spec);

    char *p1 = strchr(tmp, ':');
    if (!p1) return -1;
    *p1++ = '\0';

    char *p2 = strchr(p1, ':');
    if (p2) *p2++ = '\0';

    log_target_t *t = &cfg->logs[cfg->log_count];
    memset(t, 0, sizeof(*t));

    if (strlen(tmp) >= sizeof(t->path)) {
        errno = ENAMETOOLONG;
        return -1;
    }
    strcpy(t->path, tmp);

    char *end = NULL;
    long long maxb = strtoll(p1, &end, 10);
    if (!end || *end != '\0' || maxb <= 0) {
        return -1;
    }
    t->max_bytes = (off_t)maxb;

    if (p2) {
        long ret = strtol(p2, &end, 10);
        if (!end || *end != '\0' || ret < 0 || ret > MAX_RETENTION) {
            return -1;
        }
        t->retention = (int)ret;
    } else {
        t->retention = DEFAULT_RETENTION;
    }

    cfg->log_count++;
    return 0;
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->interval_s = DEFAULT_INTERVAL_S;

    int opt;
    while ((opt = getopt(argc, argv, "dvi:l:")) != -1) {
        switch (opt) {
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'v':
                cfg->verbose = 1;
                break;
            case 'i': {
                char *end = NULL;
                long v = strtol(optarg, &end, 10);
                if (!end || *end != '\0' || v <= 0 || v > 86400) return -1;
                cfg->interval_s = (int)v;
                break;
            }
            case 'l':
                if (parse_log_spec(cfg, optarg) < 0) return -1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_count == 0) {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            dprintf(STDERR_FILENO, "daemonize failed: %s\n", strerror(errno));
            return 1;
        }
    }

    log_msg(cfg.verbose, "started with %d log target(s)", cfg.log_count);

    while (g_running) {
        for (int i = 0; i < cfg.log_count; ++i) {
            maybe_rotate(&cfg.logs[i], cfg.verbose);
        }

        for (int s = 0; s < cfg.interval_s && g_running; ++s) {
            sleep(1);
        }
    }

    log_msg(cfg.verbose, "stopped");
    return 0;
}
