```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define MAX_LOGS 64
#define MAX_PATH_LEN 256
#define MAX_LINE_LEN 512
#define MAX_PIDFILE_LEN 256

#define DEFAULT_POLL_INTERVAL 5
#define DEFAULT_DAEMONIZE 0

typedef struct {
    char path[MAX_PATH_LEN];
    off_t max_size;
    int keep_count;
} log_config_t;

typedef struct {
    int poll_interval_sec;
    int daemonize;
    char pidfile[MAX_PIDFILE_LEN];
    log_config_t logs[MAX_LOGS];
    size_t log_count;
} daemon_config_t;

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

static void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static int safe_strcpy(char *dst, size_t dst_sz, const char *src) {
    size_t n;
    if (!dst || !src || dst_sz == 0) return -1;
    n = strlen(src);
    if (n >= dst_sz) return -1;
    memcpy(dst, src, n + 1);
    return 0;
}

static void trim_whitespace(char *s) {
    char *end;
    char *start = s;

    while (*start == ' ' || *start == '\t' || *start == '\r' || *start == '\n') {
        start++;
    }

    if (start != s) {
        memmove(s, start, strlen(start) + 1);
    }

    if (*s == '\0') return;

    end = s + strlen(s) - 1;
    while (end >= s && (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')) {
        *end = '\0';
        end--;
    }
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0 || v > 1000000) return -1;
    *out = (int)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;
    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    if (v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

static void init_default_config(daemon_config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->poll_interval_sec = DEFAULT_POLL_INTERVAL;
    cfg->daemonize = DEFAULT_DAEMONIZE;
    cfg->pidfile[0] = '\0';
}

static int parse_log_line(const char *value, log_config_t *logcfg) {
    char buf[MAX_LINE_LEN];
    char *p1, *p2;
    off_t max_size;
    int keep_count;

    if (safe_strcpy(buf, sizeof(buf), value) != 0) return -1;

    p1 = strchr(buf, ',');
    if (!p1) return -1;
    *p1++ = '\0';

    p2 = strchr(p1, ',');
    if (!p2) return -1;
    *p2++ = '\0';

    trim_whitespace(buf);
    trim_whitespace(p1);
    trim_whitespace(p2);

    if (buf[0] == '\0') return -1;
    if (parse_offt(p1, &max_size) != 0) return -1;
    if (parse_int(p2, &keep_count) != 0) return -1;
    if (keep_count < 1 || keep_count > 1000) return -1;

    memset(logcfg, 0, sizeof(*logcfg));
    if (safe_strcpy(logcfg->path, sizeof(logcfg->path), buf) != 0) return -1;
    logcfg->max_size = max_size;
    logcfg->keep_count = keep_count;
    return 0;
}

static int load_config_file(const char *path, daemon_config_t *cfg) {
    FILE *fp;
    char line[MAX_LINE_LEN];
    daemon_config_t tmp;
    int lineno = 0;

    init_default_config(&tmp);

    fp = fopen(path, "r");
    if (!fp) {
        log_stderr("failed to open config '%s': %s", path, strerror(errno));
        return -1;
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        char *eq;
        char *key;
        char *value;

        lineno++;

        if (strchr(line, '\n') == NULL && !feof(fp)) {
            log_stderr("config line too long at %d", lineno);
            fclose(fp);
            return -1;
        }

        trim_whitespace(line);
        if (line[0] == '\0' || line[0] == '#') continue;

        eq = strchr(line, '=');
        if (!eq) {
            log_stderr("invalid config line %d", lineno);
            fclose(fp);
            return -1;
        }

        *eq++ = '\0';
        key = line;
        value = eq;
        trim_whitespace(key);
        trim_whitespace(value);

        if (strcmp(key, "poll_interval") == 0) {
            if (parse_int(value, &tmp.poll_interval_sec) != 0 || tmp.poll_interval_sec < 1) {
                log_stderr("invalid poll_interval at line %d", lineno);
                fclose(fp);
                return -1;
            }
        } else if (strcmp(key, "daemonize") == 0) {
            if (parse_int(value, &tmp.daemonize) != 0 || (tmp.daemonize != 0 && tmp.daemonize != 1)) {
                log_stderr("invalid daemonize at line %d", lineno);
                fclose(fp);
                return -1;
            }
        } else if (strcmp(key, "pidfile") == 0) {
            if (safe_strcpy(tmp.pidfile, sizeof(tmp.pidfile), value) != 0) {
                log_stderr("pidfile too long at line %d", lineno);
                fclose(fp);
                return -1;
            }
        } else if (strcmp(key, "log") == 0) {
            if (tmp.log_count >= MAX_LOGS) {
                log_stderr("too many log entries (max %d)", MAX_LOGS);
                fclose(fp);
                return -1;
            }
            if (parse_log_line(value, &tmp.logs[tmp.log_count]) != 0) {
                log_stderr("invalid log entry at line %d", lineno);
                fclose(fp);
                return -1;
            }
            tmp.log_count++;
        } else {
            log_stderr("unknown config key '%s' at line %d", key, lineno);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);

    if (tmp.log_count == 0) {
        log_stderr("no log entries configured");
        return -1;
    }

    *cfg = tmp;
    return 0;
}

static int write_pidfile(const char *path) {
    int fd;
    char buf[32];
    int len;

    if (!path || path[0] == '\0') return 0;

    fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        log_stderr("failed to open pidfile '%s': %s", path, strerror(errno));
        return -1;
    }

    len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        close(fd);
        return -1;
    }

    if (write(fd, buf, (size_t)len) != len) {
        log_stderr("failed to write pidfile '%s': %s", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static void remove_pidfile(const char *path) {
    if (path && path[0] != '\0') {
        unlink(path);
    }
}

static int daemonize_process(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) != 0) return -1;
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, int index) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int rotate_one_log(const log_config_t *logcfg) {
    int i;
    char oldp[MAX_PATH_LEN + 16];
    char newp[MAX_PATH_LEN + 16];

    for (i = logcfg->keep_count; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), logcfg->path, i) != 0) {
            log_stderr("rotated path too long for '%s'", logcfg->path);
            return -1;
        }

        if (i == logcfg->keep_count) {
            unlink(oldp);
            continue;
        }

        if (build_rotated_path(newp, sizeof(newp), logcfg->path, i + 1) != 0) {
            log_stderr("rotated path too long for '%s'", logcfg->path);
            return -1;
        }

        rename(oldp, newp);
    }

    if (build_rotated_path(newp, sizeof(newp), logcfg->path, 1) != 0) {
        log_stderr("rotated path too long for '%s'", logcfg->path);
        return -1;
    }

    if (rename(logcfg->path, newp) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        log_stderr("failed to rotate '%s' -> '%s': %s",
                   logcfg->path, newp, strerror(errno));
        return -1;
    }

    return 0;
}

static void check_and_rotate_logs(const daemon_config_t *cfg) {
    size_t i;
    for (i = 0; i < cfg->log_count; i++) {
        off_t sz;
        const log_config_t *logcfg = &cfg->logs[i];

        if (file_size(logcfg->path, &sz) != 0) {
            continue;
        }

        if (sz >= logcfg->max_size) {
            rotate_one_log(logcfg);
        }
    }
}

static void sleep_interruptible(int sec) {
    while (sec > 0 && !g_terminate && !g_reload) {
        sec = sleep((unsigned int)sec);
    }
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s -c <config-file>\n", prog);
}

int main(int argc, char **argv) {
    daemon_config_t cfg;
    const char *config_path = NULL;
    int opt;

    while ((opt = getopt(argc, argv, "c:h")) != -1) {
        switch (opt) {
            case 'c':
                config_path = optarg;
                break;
            case 'h':
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (!config_path) {
        usage(argv[0]);
        return 1;
    }

    init_default_config(&cfg);

    if (load_config_file(config_path, &cfg) != 0) {
        return 1;
    }

    if (install_signal_handlers() != 0) {
        log_stderr("failed to install signal handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            log_stderr("failed to daemonize");
            return 1;
        }
    }

    if (write_pidfile(cfg.pidfile) != 0) {
        return 1;
    }

    while (!g_terminate) {
        if (g_reload) {
            daemon_config_t newcfg;
            g_reload = 0;
            if (load_config_file(config_path, &newcfg) == 0) {
                cfg = newcfg;
                if (write_pidfile(cfg.pidfile) != 0) {
                    log_stderr("warning: failed to rewrite pidfile after reload");
                }
            } else {
                log_stderr("config reload failed; keeping previous config");
            }
        }

        check_and_rotate_logs(&cfg);
        sleep_interruptible(cfg.poll_interval_sec);
    }

    remove_pidfile(cfg.pidfile);
    return 0;
}
