Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed to run with **strict memory limits** in mind.

It aims to be:

- **Small and predictable**
- **Heap-free during steady state**
- **Single-threaded**
- **Polling-based**
- **Suitable for embedded or constrained Linux systems**

It supports:

- Monitoring a fixed list of log files
- Rotating when file size exceeds a threshold
- Keeping a fixed number of rotated files
- Truncating the active log after rotation
- Optional periodic polling loop as a daemon

---

## Design goals

This implementation intentionally avoids:

- dynamic allocation in the main path
- recursive directory walking
- regex/config parsers
- large buffers
- complex signal handling

Instead it uses:

- fixed-size arrays
- fixed-size path buffers
- `stat`, `rename`, `open`, `read`, `write`, `ftruncate`
- a simple sleep loop

---

## Initial implementation

```c
/*
 * memlogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Features:
 * - Monitors a fixed list of files
 * - Rotates when size exceeds max_size
 * - Keeps rotate_count historical files:
 *     logfile      -> active
 *     logfile.1    -> newest rotated
 *     logfile.N    -> oldest rotated
 * - Uses fixed buffers and avoids heap allocation
 * - Optional daemon mode
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd
 *
 * Notes:
 * - This is an initial implementation for Linux/POSIX systems.
 * - Rotation is best-effort and not atomic across all steps.
 * - Writers that keep the old file descriptor open may continue writing
 *   to the renamed file until they reopen the log.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS 8
#define MAX_ROTATE_COUNT 16
#define COPY_BUF_SIZE 4096

typedef struct {
    char path[PATH_MAX];
    off_t max_size;
    int rotate_count;
    mode_t create_mode;
} log_config_t;

typedef struct {
    log_config_t logs[MAX_LOGS];
    size_t log_count;
    unsigned int poll_interval_sec;
    int daemonize;
} daemon_config_t;

static volatile sig_atomic_t g_stop = 0;

static void handle_signal(int signo) {
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }

    return 0;
}

static int safe_snprintf(char *dst, size_t dst_sz, const char *fmt, const char *base, int idx) {
    int n = snprintf(dst, dst_sz, fmt, base, idx);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int ensure_file_exists(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int copy_fd(int src_fd, int dst_fd) {
    char buf[COPY_BUF_SIZE];
    for (;;) {
        ssize_t r = read(src_fd, buf, sizeof(buf));
        if (r == 0) return 0;
        if (r < 0) {
            if (errno == EINTR) continue;
            return -1;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dst_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                return -1;
            }
            off += w;
        }
    }
}

/*
 * Rotation strategy:
 *   log.(N-1) -> log.N
 *   ...
 *   log.1 -> log.2
 *   log -> log.1
 *   recreate/truncate log
 *
 * If rename(log, log.1) fails with EXDEV or similar edge cases,
 * fallback to copy+truncate.
 */
static int rotate_log(const log_config_t *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->rotate_count < 1 || cfg->rotate_count > MAX_ROTATE_COUNT) {
        errno = EINVAL;
        return -1;
    }

    for (int i = cfg->rotate_count; i >= 1; --i) {
        if (safe_snprintf(new_path, sizeof(new_path), "%s.%d", cfg->path, i) < 0) {
            return -1;
        }

        if (i == 1) {
            if (safe_snprintf(old_path, sizeof(old_path), "%s", cfg->path, 0) < 0) {
                return -1;
            }
        } else {
            if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", cfg->path, i - 1) < 0) {
                return -1;
            }
        }

        if (i == cfg->rotate_count) {
            (void)unlink(new_path);
        }

        if (!file_exists(old_path)) {
            continue;
        }

        if (rename(old_path, new_path) == 0) {
            continue;
        }

        if (i != 1) {
            return -1;
        }

        /* Fallback for active log only: copy to .1 then truncate original */
        int src_fd = open(cfg->path, O_RDONLY);
        if (src_fd < 0) return -1;

        int dst_fd = open(new_path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
        if (dst_fd < 0) {
            close(src_fd);
            return -1;
        }

        int rc = copy_fd(src_fd, dst_fd);
        int saved_errno = errno;

        close(src_fd);
        close(dst_fd);

        if (rc < 0) {
            errno = saved_errno;
            return -1;
        }

        int trunc_fd = open(cfg->path, O_WRONLY);
        if (trunc_fd < 0) return -1;
        rc = ftruncate(trunc_fd, 0);
        saved_errno = errno;
        close(trunc_fd);

        if (rc < 0) {
            errno = saved_errno;
            return -1;
        }
    }

    if (ensure_file_exists(cfg->path, cfg->create_mode) < 0) {
        return -1;
    }

    return 0;
}

static int check_and_rotate(const log_config_t *cfg) {
    struct stat st;
    if (stat(cfg->path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_file_exists(cfg->path, cfg->create_mode);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_log(cfg);
    }

    return 0;
}

static void sleep_interruptible(unsigned int sec) {
    struct timespec req, rem;
    req.tv_sec = sec;
    req.tv_nsec = 0;

    while (!g_stop && nanosleep(&req, &rem) < 0) {
        if (errno != EINTR) break;
        req = rem;
    }
}

static int run_daemon(const daemon_config_t *cfg) {
    while (!g_stop) {
        for (size_t i = 0; i < cfg->log_count; ++i) {
            (void)check_and_rotate(&cfg->logs[i]);
            /* Best-effort: ignore per-file errors in initial version */
        }

        sleep_interruptible(cfg->poll_interval_sec);
    }

    return 0;
}

int main(void) {
    daemon_config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    cfg.poll_interval_sec = 5;
    cfg.daemonize = 0;

    cfg.log_count = 2;

    strncpy(cfg.logs[0].path, "/tmp/app.log", sizeof(cfg.logs[0].path) - 1);
    cfg.logs[0].max_size = 1024 * 1024; /* 1 MiB */
    cfg.logs[0].rotate_count = 4;
    cfg.logs[0].create_mode = 0644;

    strncpy(cfg.logs[1].path, "/tmp/worker.log", sizeof(cfg.logs[1].path) - 1);
    cfg.logs[1].max_size = 512 * 1024; /* 512 KiB */
    cfg.logs[1].rotate_count = 3;
    cfg.logs[1].create_mode = 0644;

    if (install_signal_handlers() < 0) {
        perror("install_signal_handlers");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            perror("daemonize_process");
            return 1;
        }
    }

    if (run_daemon(&cfg) < 0) {
        perror("run_daemon");
        return 1;
    }

    return 0;
}
```

---

## Memory-constrained characteristics

This implementation is memory-conscious in several ways:

- **No malloc/free in steady state**
- Fixed arrays:
  - `MAX_LOGS`
  - `MAX_ROTATE_COUNT`
  - `PATH_MAX`
  - `COPY_BUF_SIZE`
- Stack usage is bounded and modest
- No large in-memory indexing or buffering
- No parsing of external config files

Approximate memory use is mainly:

- config struct
- a few `PATH_MAX` buffers during rotation
- one 4 KiB copy buffer in fallback path

---

## Important limitations

This is an **initial implementation**, so there are tradeoffs:

### 1. Writer coordination
If another process keeps the log file open:

- after `rename(log, log.1)`, it may continue writing to `log.1`
- the newly created `log` may remain unused until the writer reopens it

This is standard log rotation behavior unless the writer supports reopen signals.

### 2. No compression
Compressed rotations are intentionally omitted to avoid extra memory/CPU cost.

### 3. No config file parser
The log list is compiled into the binary. This avoids parser complexity and heap usage.

### 4. Best-effort error handling
The daemon currently ignores per-log failures in the main loop.

### 5. Polling only
No `inotify` is used. Polling is simpler and more predictable in memory use.

