You asked for strict memory limits, so here is a small helper you can add:

```c
#include <sys/resource.h>

static int apply_resource_limits(void) {
    struct rlimit rl;

    rl.rlim_cur = rl.rlim_max = 16 * 1024 * 1024; /* 16 MiB address space */
    if (setrlimit(RLIMIT_AS, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = 16 * 1024 * 1024; /* 16 MiB data segment */
    if (setrlimit(RLIMIT_DATA, &rl) < 0) return -1;

    rl.rlim_cur = rl.rlim_max = 32; /* max open files */
    if (setrlimit(RLIMIT_NOFILE, &rl) < 0) return -1;

    return 0;
}
