Below is an initial implementation of a **memory-constrained log rotation daemon** in **C** designed to run under **strict memory limits**.

It is intentionally:
- **single-process**
- **single-threaded**
- **allocation-light**
- based on **fixed-size buffers**
- avoids loading whole files into memory
- rotates by **size threshold**
- keeps a fixed number of rotated files
- optionally truncates the active file after rotation by renaming and recreating

It is a practical starting point, not a production-complete daemon.

---

# Features

- Watches one log file path
- Checks file size periodically
- Rotates when size exceeds a threshold
- Keeps `N` rotated files:
  - `log`
  - `log.1`
  - `log.2`
  - ...
- Uses:
  - no dynamic allocation in the hot path
  - fixed-size path buffers
  - low memory footprint
- Can daemonize
- Handles `SIGTERM` / `SIGINT`
- Uses `rename()`-based rotation

---

# Important design notes

This implementation assumes:

1. The writer reopens the log file if needed, or continues writing to the recreated file path after rotation.
2. Rotation is done by:
   - shifting `log.(n-1)` to `log.n`
   - renaming `log` to `log.1`
   - creating a fresh `log`
3. It does **not** compress logs.
4. It does **not** parse log lines.
5. It does **not** use inotify; it polls periodically to keep memory and complexity low.

If the application writing the log keeps the old file descriptor open, it may continue writing to the renamed file. That is normal for rename-based rotation and may require cooperation from the writer process.

---

# Source code

```c
/*
 * memlogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -std=c11 -O2 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 5 -d
 *
 * Notes:
 * - Rotates when file size >= max_size bytes.
 * - Keeps N rotated logs: .1 through .N
 * - Uses fixed buffers and avoids heap allocation.
 * - Polling-based, no inotify.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_ROTATIONS    5
#define DEFAULT_MAX_SIZE     (10ULL * 1024ULL * 1024ULL)
#define PIDFILE_MODE         0644
#define LOGFILE_MODE         0644

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    uint64_t max_size;
    unsigned int rotations;
    unsigned int interval_sec;
    bool daemonize;
    bool verbose;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static int setup_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static int safe_snprintf_path(char *dst, size_t dst_sz, const char *base, unsigned int suffix) {
    int n;
    if (suffix == 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%u", base, suffix);
    }

    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, LOGFILE_MODE);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int get_file_size(const char *path, uint64_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    *size_out = (uint64_t)st.st_size;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->rotations == 0) {
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            return -1;
        }
        return ensure_log_exists(cfg->log_path);
    }

    for (unsigned int i = cfg->rotations; i > 0; --i) {
        if (safe_snprintf_path(old_path, sizeof(old_path), cfg->log_path, i) != 0) {
            return -1;
        }

        if (i == cfg->rotations) {
            if (unlink(old_path) != 0 && errno != ENOENT) {
                return -1;
            }
        }

        if (i > 1) {
            if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, i - 1) != 0) {
                return -1;
            }

            if (rename(new_path, old_path) != 0) {
                if (errno != ENOENT) {
                    return -1;
                }
            }
        }
    }

    if (safe_snprintf_path(new_path, sizeof(new_path), cfg->log_path, 1) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return ensure_log_exists(cfg->log_path);
}

static int check_and_rotate(const struct config *cfg) {
    uint64_t size;

    if (ensure_log_exists(cfg->log_path) != 0) {
        return -1;
    }

    if (get_file_size(cfg->log_path, &size) != 0) {
        return -1;
    }

    if (size >= cfg->max_size) {
        if (cfg->verbose) {
            log_stderr("rotating %s (size=%llu)\n",
                       cfg->log_path,
                       (unsigned long long)size);
        }
        if (rotate_logs(cfg) != 0) {
            return -1;
        }
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [options]\n"
        "Options:\n"
        "  -f <path>   Log file path to monitor\n"
        "  -s <bytes>  Max size before rotation (default: %llu)\n"
        "  -n <count>  Number of rotated files to keep (default: %u)\n"
        "  -i <sec>    Poll interval in seconds (default: %u)\n"
        "  -d          Daemonize\n"
        "  -v          Verbose\n"
        "  -h          Help\n",
        prog,
        (unsigned long long)DEFAULT_MAX_SIZE,
        DEFAULT_ROTATIONS,
        DEFAULT_INTERVAL_SEC);
}

static int parse_u64(const char *s, uint64_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = (uint64_t)v;
    return 0;
}

static int parse_u32(const char *s, unsigned int *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    if (v > UINT_MAX) {
        errno = ERANGE;
        return -1;
    }
    *out = (unsigned int)v;
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->rotations = DEFAULT_ROTATIONS;
    cfg->interval_sec = DEFAULT_INTERVAL_SEC;
    cfg->daemonize = false;
    cfg->verbose = false;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:dvh")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", optarg) >= (int)sizeof(cfg->log_path)) {
                    errno = ENAMETOOLONG;
                    return -1;
                }
                break;
            case 's':
                if (parse_u64(optarg, &cfg->max_size) != 0 || cfg->max_size == 0) {
                    return -1;
                }
                break;
            case 'n':
                if (parse_u32(optarg, &cfg->rotations) != 0) {
                    return -1;
                }
                break;
            case 'i':
                if (parse_u32(optarg, &cfg->interval_sec) != 0 || cfg->interval_sec == 0) {
                    return -1;
                }
                break;
            case 'd':
                cfg->daemonize = true;
                break;
            case 'v':
                cfg->verbose = true;
                break;
            case 'h':
                usage(argv[0]);
                exit(0);
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    if (setup_signals() != 0) {
        perror("setup_signals");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        if (check_and_rotate(&cfg) != 0) {
            if (cfg.verbose) {
                log_stderr("error: %s\n", strerror(errno));
            }
        }

        for (unsigned int slept = 0; slept < cfg.interval_sec && g_running; ++slept) {
            sleep(1);
        }
    }

    return 0;
}
```

