## Source: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define MAX_PATH_LEN 512
#define DEFAULT_INTERVAL_SEC 2
#define DEFAULT_ROTATE_SIZE (1024 * 1024) /* 1 MiB */
#define DEFAULT_BACKUPS 5
#define DEFAULT_MEM_LIMIT_MB 8

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void die(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
    exit(1);
}

static void set_memory_limit_mb(rlim_t mb) {
    struct rlimit rl;
    rl.rlim_cur = mb * 1024 * 1024;
    rl.rlim_max = mb * 1024 * 1024;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        exit(1);
    }
}

static void daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) die("fork failed");
    if (pid > 0) exit(0);

    if (setsid() < 0) die("setsid failed");

    pid = fork();
    if (pid < 0) die("fork failed");
    if (pid > 0) exit(0);

    if (chdir("/") != 0) die("chdir failed");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > 2) close(fd);
    }
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const char *path, int backups, mode_t mode) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    if (backups < 1) return 0;

    for (int i = backups - 1; i >= 1; --i) {
        int n1 = snprintf(oldp, sizeof(oldp), "%s.%d", path, i);
        int n2 = snprintf(newp, sizeof(newp), "%s.%d", path, i + 1);
        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(oldp) || n2 >= (int)sizeof(newp)) {
            errno = ENAMETOOLONG;
            return -1;
        }
        if (file_exists(oldp)) {
            if (rename(oldp, newp) != 0) return -1;
        }
    }

    int n = snprintf(newp, sizeof(newp), "%s.1", path);
    if (n < 0 || n >= (int)sizeof(newp)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (file_exists(path)) {
        if (rename(path, newp) != 0) return -1;
    }

    if (ensure_log_exists(path, mode) != 0) return -1;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s bytes] [-b backups] [-i sec] [-m mem_mb] [-d]\n"
        "  -f <logfile>   Log file to monitor\n"
        "  -s <bytes>     Rotate when size exceeds bytes (default: %d)\n"
        "  -b <backups>   Number of rotated backups to keep (default: %d)\n"
        "  -i <sec>       Poll interval in seconds (default: %d)\n"
        "  -m <mem_mb>    Address space limit in MiB (default: %d)\n"
        "  -d             Run as daemon\n",
        prog, DEFAULT_ROTATE_SIZE, DEFAULT_BACKUPS,
        DEFAULT_INTERVAL_SEC, DEFAULT_MEM_LIMIT_MB);
}

int main(int argc, char **argv) {
    char logfile[MAX_PATH_LEN] = {0};
    off_t rotate_size = DEFAULT_ROTATE_SIZE;
    int backups = DEFAULT_BACKUPS;
    int interval_sec = DEFAULT_INTERVAL_SEC;
    int daemon_mode = 0;
    int mem_limit_mb = DEFAULT_MEM_LIMIT_MB;
    mode_t log_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:b:i:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(logfile, sizeof(logfile), "%s", optarg) >= (int)sizeof(logfile)) {
                    die("logfile path too long");
                }
                break;
            case 's':
                rotate_size = (off_t)atoll(optarg);
                break;
            case 'b':
                backups = atoi(optarg);
                break;
            case 'i':
                interval_sec = atoi(optarg);
                break;
            case 'm':
                mem_limit_mb = atoi(optarg);
                break;
            case 'd':
                daemon_mode = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (logfile[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (rotate_size <= 0 || backups < 1 || interval_sec < 1 || mem_limit_mb < 1) {
        die("invalid argument");
    }

    set_memory_limit_mb((rlim_t)mem_limit_mb);

    if (ensure_log_exists(logfile, log_mode) != 0) {
        perror("ensure_log_exists");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (daemon_mode) {
        daemonize();
    }

    while (!g_stop) {
        off_t sz = file_size(logfile);
        if (sz < 0) {
            /* If the file disappears, try to recreate it */
            ensure_log_exists(logfile, log_mode);
        } else if (sz >= rotate_size) {
            if (rotate_logs(logfile, backups, log_mode) != 0) {
                /* Keep running on transient errors */
                sleep(interval_sec);
                continue;
            }
        }

        sleep(interval_sec);
    }

    return 0;
}
