#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 9
#define DEFAULT_INTERVAL_SEC 5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }

    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode) {
    int fd = open(path, O_CREAT | O_APPEND, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int make_rotated_name(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const char *path, int keep, mode_t mode) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int i;

    if (keep < 1 || keep > MAX_ROTATIONS) return -1;

    for (i = keep - 1; i >= 1; --i) {
        if (make_rotated_name(oldp, sizeof(oldp), path, i) < 0) return -1;
        if (make_rotated_name(newp, sizeof(newp), path, i + 1) < 0) return -1;

        if (file_exists(oldp)) {
            if (rename(oldp, newp) < 0) {
                if (errno != ENOENT) return -1;
            }
        }
    }

    if (make_rotated_name(newp, sizeof(newp), path, 1) < 0) return -1;

    if (file_exists(path)) {
        if (rename(path, newp) < 0) return -1;
    }

    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, mode);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] <log_path> <max_size_bytes> <keep_count> [interval_sec]\n"
        "  -f              Run in foreground\n"
        "  log_path        Path to log file\n"
        "  max_size_bytes  Rotate when size >= this value\n"
        "  keep_count      Number of rotated files to keep (1-%d)\n"
        "  interval_sec    Poll interval in seconds (default %d)\n",
        prog, MAX_ROTATIONS, DEFAULT_INTERVAL_SEC);
}

static int parse_int(const char *s, long *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

int main(int argc, char **argv) {
    int foreground = 0;
    const char *log_path;
    long max_size_l, keep_l, interval_l = DEFAULT_INTERVAL_SEC;
    off_t max_size;
    int keep;
    unsigned int interval_sec;
    mode_t mode = 0644;
    int argi = 1;

    if (argc > 1 && strcmp(argv[1], "-f") == 0) {
        foreground = 1;
        argi++;
    }

    if (argc - argi < 3 || argc - argi > 4) {
        usage(argv[0]);
        return 1;
    }

    log_path = argv[argi++];

    if (parse_int(argv[argi++], &max_size_l) < 0 || max_size_l <= 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[argi++], &keep_l) < 0 || keep_l < 1 || keep_l > MAX_ROTATIONS) {
        fprintf(stderr, "Invalid keep_count\n");
        return 1;
    }

    if (argc - argi == 1) {
        if (parse_int(argv[argi++], &interval_l) < 0 || interval_l <= 0) {
            fprintf(stderr, "Invalid interval_sec\n");
            return 1;
        }
    }

    max_size = (off_t)max_size_l;
    keep = (int)keep_l;
    interval_sec = (unsigned int)interval_l;

    if (strlen(log_path) >= PATH_MAX - 16) {
        fprintf(stderr, "log_path too long\n");
        return 1;
    }

    if (install_signals() < 0) {
        perror("sigaction");
        return 1;
    }

    if (ensure_log_exists(log_path, mode) < 0) {
        perror("ensure_log_exists");
        return 1;
    }

    if (!foreground) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (!g_stop) {
        off_t size = 0;

        if (get_file_size(log_path, &size) == 0) {
            if (size >= max_size) {
                if (rotate_logs(log_path, keep, mode) < 0) {
                    /* Minimal daemon: ignore transient errors and retry later */
                }
            }
        } else {
            /* Recreate missing log file */
            (void)ensure_log_exists(log_path, mode);
        }

        sleep(interval_sec);
    }

    return 0;
}
