## Source: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE (1024 * 1024)   /* 1 MiB */
#define DEFAULT_ROTATIONS 5
#define DEFAULT_INTERVAL 5               /* seconds */
#define DEFAULT_MEM_LIMIT (8 * 1024 * 1024) /* 8 MiB */

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int rotations;
    int interval_sec;
    int daemonize;
    rlim_t mem_limit;
};

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void die(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
    exit(1);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval] [-m mem_bytes] [-d]\n"
        "  -f logfile     Path to log file\n"
        "  -s max_bytes   Rotate when file exceeds this size (default: %d)\n"
        "  -n rotations   Number of rotated files to keep (default: %d)\n"
        "  -i interval    Poll interval in seconds (default: %d)\n"
        "  -m mem_bytes   Memory limit in bytes (default: %d)\n"
        "  -d             Daemonize\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, DEFAULT_INTERVAL, DEFAULT_MEM_LIMIT);
}

static int parse_int(const char *s, long long *out) {
    char *end = NULL;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

static void set_memory_limits(rlim_t limit) {
    struct rlimit rl;
    rl.rlim_cur = limit;
    rl.rlim_max = limit;

    /* Best effort: some systems may reject some of these. */
    (void)setrlimit(RLIMIT_AS, &rl);
    (void)setrlimit(RLIMIT_DATA, &rl);
    (void)setrlimit(RLIMIT_STACK, &rl);
}

static void daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) die("fork failed");
    if (pid > 0) exit(0);

    if (setsid() < 0) die("setsid failed");

    pid = fork();
    if (pid < 0) die("fork failed");
    if (pid > 0) exit(0);

    if (chdir("/") != 0) die("chdir failed");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        (void)dup2(fd, STDIN_FILENO);
        (void)dup2(fd, STDOUT_FILENO);
        (void)dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->rotations < 1) return 0;

    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) != 0) return -1;
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) != 0) return -1;
        (void)rename(oldp, newp);
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) != 0) return -1;
    (void)rename(cfg->log_path, newp);

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.rotations = DEFAULT_ROTATIONS;
    cfg.interval_sec = DEFAULT_INTERVAL;
    cfg.daemonize = 0;
    cfg.mem_limit = DEFAULT_MEM_LIMIT;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:d")) != -1) {
        long long v;
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path))
                    die("log path too long");
                break;
            case 's':
                if (parse_int(optarg, &v) != 0 || v <= 0) die("invalid max size");
                cfg.max_size = (off_t)v;
                break;
            case 'n':
                if (parse_int(optarg, &v) != 0 || v < 1 || v > 1000) die("invalid rotations");
                cfg.rotations = (int)v;
                break;
            case 'i':
                if (parse_int(optarg, &v) != 0 || v < 1 || v > 3600) die("invalid interval");
                cfg.interval_sec = (int)v;
                break;
            case 'm':
                if (parse_int(optarg, &v) != 0 || v < (1024 * 1024)) die("invalid memory limit");
                cfg.mem_limit = (rlim_t)v;
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    set_memory_limits(cfg.mem_limit);

    if (cfg.daemonize) {
        daemonize_self();
    }

    while (g_running) {
        (void)check_and_rotate(&cfg);
        sleep((unsigned int)cfg.interval_sec);
    }

    return 0;
}
