    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *path, int keep) {
    char oldp[PATHBUF];
    char newp[PATHBUF];

    for (int i = keep - 1; i >= 1; --i) {
        int n1 = snprintf(oldp, sizeof(oldp), "%s.%d", path, i);
        int n2 = snprintf(newp, sizeof(newp), "%s.%d", path, i + 1);
        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(oldp) || n2 >= (int)sizeof(newp)) {
            errno = ENAMETOOLONG;
            return -1;
        }
        (void)rename(oldp, newp);
    }

    int n = snprintf(newp, sizeof(newp), "%s.1", path);
    if (n < 0 || n >= (int)sizeof(newp)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (rename(path, newp) != 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] <logfile> <max_bytes> <keep_count> <poll_ms> <mem_limit_bytes>\n"
        "  -f               Run in foreground\n"
        "  logfile          Path to log file\n"
        "  max_bytes        Rotate when file exceeds this size\n"
        "  keep_count       Number of rotated files to keep (>=1)\n"
        "  poll_ms          Poll interval in milliseconds\n"
        "  mem_limit_bytes  Address-space/data memory limit\n",
        prog);
}

int main(int argc, char **argv) {
    int foreground = 0;
    int argi = 1;

    if (argc > 1 && strcmp(argv[1], "-f") == 0) {
        foreground = 1;
        argi++;
    }

    if (argc - argi != 5) {
        usage(argv[0]);
        return 1;
    }

    const char *logfile = argv[argi++];
    char *end = NULL;

    errno = 0;
    unsigned long long max_bytes = strtoull(argv[argi++], &end, 10);
    if (errno || !end || *end != '\0' || max_bytes == 0) {
        fprintf(stderr, "invalid max_bytes\n");
        return 1;
    }

    errno = 0;
    long keep = strtol(argv[argi++], &end, 10);
    if (errno || !end || *end != '\0' || keep < 1 || keep > 9999) {
        fprintf(stderr, "invalid keep_count\n");
        return 1;
    }

    errno = 0;
    long poll_ms = strtol(argv[argi++], &end, 10);
    if (errno || !end || *end != '\0' || poll_ms < 10 || poll_ms > 3600000) {
        fprintf(stderr, "invalid poll_ms\n");
        return 1;
    }

    errno = 0;
    unsigned long long mem_limit = strtoull(argv[argi++], &end, 10);
    if (errno || !end || *end != '\0' || mem_limit < (1024ULL * 1024ULL)) {
        fprintf(stderr, "invalid mem_limit_bytes\n");
        return 1;
    }

    if (set_memory_limits((rlim_t)mem_limit) != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!foreground) {
        if (daemonize_self() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    struct timespec ts;
    ts.tv_sec = poll_ms / 1000;
    ts.tv_nsec = (poll_ms % 1000) * 1000000L;

    while (!g_stop) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0) {
            if ((unsigned long long)sz > max_bytes) {
                if (rotate_logs(logfile, (int)keep) != 0) {
                    /* In daemon mode stderr goes to /dev/null; keep running */
                }
            }
        } else {
            if (errno == ENOENT) {
                int fd = open(logfile, O_WRONLY | O_CREAT, 0644);
                if (fd >= 0) close(fd);
            }
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}
