## Code: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <stdlib.h>
#include <signal.h>

#define MAX_PATH_LEN 256
#define DEFAULT_CHECK_INTERVAL 5
#define DEFAULT_MAX_ROTATIONS 5

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_size_exceeds(const char *path, off_t limit) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return 0;
    }
    return st.st_size >= limit;
}

static int safe_snprintf(char *buf, size_t buflen, const char *fmt, const char *path, int n) {
    int ret = snprintf(buf, buflen, fmt, path, n);
    if (ret < 0 || (size_t)ret >= buflen) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int max_rotations) {
    char oldname[MAX_PATH_LEN];
    char newname[MAX_PATH_LEN];
    int i;

    if (max_rotations < 1) {
        return -1;
    }

    /* Remove oldest */
    if (safe_snprintf(oldname, sizeof(oldname), "%s.%d", path, max_rotations) != 0) {
        return -1;
    }
    unlink(oldname);

    /* Shift: path.(n-1) -> path.n */
    for (i = max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf(oldname, sizeof(oldname), "%s.%d", path, i) != 0) {
            return -1;
        }
        if (safe_snprintf(newname, sizeof(newname), "%s.%d", path, i + 1) != 0) {
            return -1;
        }
        rename(oldname, newname);
    }

    /* path -> path.1 */
    if (safe_snprintf(newname, sizeof(newname), "%s.%d", path, 1) != 0) {
        return -1;
    }
    if (rename(path, newname) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate active log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static void daemonize_if_requested(int do_daemonize) {
    pid_t pid;

    if (!do_daemonize) {
        return;
    }

    pid = fork();
    if (pid < 0) {
        exit(1);
    }
    if (pid > 0) {
        exit(0);
    }

    if (setsid() < 0) {
        exit(1);
    }

    pid = fork();
    if (pid < 0) {
        exit(1);
    }
    if (pid > 0) {
        exit(0);
    }

    chdir("/");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] <log_path> <max_size_bytes> [check_interval_sec] [max_rotations]\n"
        "  -d                  Run as daemon\n"
        "  log_path            Path to log file\n"
        "  max_size_bytes      Rotate when file reaches this size\n"
        "  check_interval_sec  Default: %d\n"
        "  max_rotations       Default: %d\n",
        prog, DEFAULT_CHECK_INTERVAL, DEFAULT_MAX_ROTATIONS);
}

int main(int argc, char *argv[]) {
    const char *log_path;
    off_t max_size;
    int check_interval = DEFAULT_CHECK_INTERVAL;
    int max_rotations = DEFAULT_MAX_ROTATIONS;
    int daemon_mode = 0;
    int argi = 1;

    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    if (strcmp(argv[argi], "-d") == 0) {
        daemon_mode = 1;
        argi++;
    }

    if ((argc - argi) < 2) {
        usage(argv[0]);
        return 1;
    }

    log_path = argv[argi++];
    max_size = (off_t)atoll(argv[argi++]);

    if ((argc - argi) >= 1) {
        check_interval = atoi(argv[argi++]);
    }
    if ((argc - argi) >= 1) {
        max_rotations = atoi(argv[argi++]);
    }

    if (strlen(log_path) >= MAX_PATH_LEN - 16) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }
    if (max_size <= 0 || check_interval <= 0 || max_rotations <= 0) {
        fprintf(stderr, "Invalid numeric argument\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    daemonize_if_requested(daemon_mode);

    while (g_running) {
        if (file_size_exceeds(log_path, max_size)) {
            rotate_logs(log_path, max_rotations);
        }
        sleep((unsigned int)check_interval);
    }

    return 0;
}
