## Code: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <dirent.h>
#include <errno.h>
#include <limits.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define SCAN_INTERVAL_SEC 5
#define MAX_BACKUPS 5
#define ROTATE_SIZE_BYTES (1024 * 1024) /* 1 MiB */
#define LOG_SUFFIX ".log"

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int has_log_suffix(const char *name) {
    size_t len = strlen(name);
    size_t sfx = sizeof(LOG_SUFFIX) - 1;
    if (len < sfx) return 0;
    return strcmp(name + len - sfx, LOG_SUFFIX) == 0;
}

static int build_path(char *out, size_t out_sz, const char *dir, const char *name) {
    int n = snprintf(out, out_sz, "%s/%s", dir, name);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *path, int index) {
    int n = snprintf(out, out_sz, "%s.%d", path, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_file(const char *path) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    int i;

    /* Remove oldest backup */
    if (build_rotated_path(oldp, sizeof(oldp), path, MAX_BACKUPS) != 0) {
        fprintf(stderr, "path too long: %s.%d\n", path, MAX_BACKUPS);
        return -1;
    }
    unlink(oldp);

    /* Shift backups upward */
    for (i = MAX_BACKUPS - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), path, i) != 0 ||
            build_rotated_path(newp, sizeof(newp), path, i + 1) != 0) {
            fprintf(stderr, "path too long during rotation: %s\n", path);
            return -1;
        }
        if (rename(oldp, newp) != 0 && errno != ENOENT) {
            fprintf(stderr, "rename(%s -> %s) failed: %s\n", oldp, newp, strerror(errno));
            return -1;
        }
    }

    /* Rotate current log to .1 */
    if (build_rotated_path(newp, sizeof(newp), path, 1) != 0) {
        fprintf(stderr, "path too long: %s.1\n", path);
        return -1;
    }

    if (rename(path, newp) != 0) {
        fprintf(stderr, "rename(%s -> %s) failed: %s\n", path, newp, strerror(errno));
        return -1;
    }

    /* Recreate empty log file */
    FILE *f = fopen(path, "a");
    if (!f) {
        fprintf(stderr, "fopen(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    fclose(f);

    return 0;
}

static void process_directory(const char *dir) {
    DIR *dp;
    struct dirent *ent;
    char path[PATH_MAX];
    struct stat st;

    dp = opendir(dir);
    if (!dp) {
        fprintf(stderr, "opendir(%s) failed: %s\n", dir, strerror(errno));
        return;
    }

    while (g_running && (ent = readdir(dp)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        if (!has_log_suffix(ent->d_name))
            continue;

        if (build_path(path, sizeof(path), dir, ent->d_name) != 0) {
            fprintf(stderr, "path too long: %s/%s\n", dir, ent->d_name);
            continue;
        }

        if (stat(path, &st) != 0) {
            fprintf(stderr, "stat(%s) failed: %s\n", path, strerror(errno));
            continue;
        }

        if (!S_ISREG(st.st_mode))
            continue;

        if (st.st_size >= ROTATE_SIZE_BYTES) {
            if (rotate_file(path) == 0) {
                fprintf(stderr, "rotated: %s\n", path);
            }
        }
    }

    closedir(dp);
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <log-directory>\n", prog);
}

int main(int argc, char **argv) {
    const char *dir;

    if (argc != 2) {
        usage(argv[0]);
        return 1;
    }

    dir = argv[1];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (g_running) {
        process_directory(dir);

        for (int i = 0; i < SCAN_INTERVAL_SEC && g_running; ++i) {
            sleep(1);
        }
    }

    return 0;
}
```

