```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>

#define MAX_PATH_LEN 256
#define DEFAULT_SLEEP_SEC 5
#define DEFAULT_ROTATIONS 3

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    return st.st_size;
}

static int create_empty_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const char *base_path, int rotations, mode_t mode) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];
    int i;

    if (rotations < 1) {
        return -1;
    }

    /* Remove the oldest if it exists */
    snprintf(old_path, sizeof(old_path), "%s.%d", base_path, rotations);
    unlink(old_path);

    /* Shift rotated logs upward */
    for (i = rotations - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", base_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", base_path, i + 1);
        if (file_exists(old_path)) {
            if (rename(old_path, new_path) != 0) {
                return -1;
            }
        }
    }

    /* Rotate current log to .1 */
    snprintf(new_path, sizeof(new_path), "%s.1", base_path);
    if (file_exists(base_path)) {
        if (rename(base_path, new_path) != 0) {
            return -1;
        }
    }

    /* Create fresh log file */
    if (create_empty_file(base_path, mode) != 0) {
        return -1;
    }

    return 0;
}

static int daemonize(void) {
    pid_t pid;

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    umask(0);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> <max_bytes> [sleep_sec] [rotations] [foreground]\n"
        "  log_path    Path to log file\n"
        "  max_bytes   Rotate when size exceeds this value\n"
        "  sleep_sec   Poll interval in seconds (default: %d)\n"
        "  rotations   Number of rotated files to keep (default: %d)\n"
        "  foreground  1 = stay in foreground, 0 = daemonize (default: 0)\n",
        prog, DEFAULT_SLEEP_SEC, DEFAULT_ROTATIONS);
}

int main(int argc, char **argv) {
    const char *log_path;
    off_t max_bytes;
    int sleep_sec = DEFAULT_SLEEP_SEC;
    int rotations = DEFAULT_ROTATIONS;
    int foreground = 0;
    mode_t mode = 0644;
    char *endptr;
    long tmp;

    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    log_path = argv[1];

    errno = 0;
    max_bytes = strtoll(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0' || max_bytes <= 0) {
        fprintf(stderr, "Invalid max_bytes\n");
        return 1;
    }

    if (argc >= 4) {
        errno = 0;
        tmp = strtol(argv[3], &endptr, 10);
        if (errno != 0 || *endptr != '\0' || tmp <= 0) {
            fprintf(stderr, "Invalid sleep_sec\n");
            return 1;
        }
        sleep_sec = (int)tmp;
    }

    if (argc >= 5) {
        errno = 0;
        tmp = strtol(argv[4], &endptr, 10);
        if (errno != 0 || *endptr != '\0' || tmp <= 0) {
            fprintf(stderr, "Invalid rotations\n");
            return 1;
        }
        rotations = (int)tmp;
    }

    if (argc >= 6) {
        errno = 0;
        tmp = strtol(argv[5], &endptr, 10);
        if (errno != 0 || *endptr != '\0' || (tmp != 0 && tmp != 1)) {
            fprintf(stderr, "Invalid foreground\n");
            return 1;
        }
        foreground = (int)tmp;
    }

    if (strlen(log_path) >= MAX_PATH_LEN - 16) {
        fprintf(stderr, "log_path too long\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!foreground) {
        if (daemonize() != 0) {
            return 1;
        }
    }

    /* Ensure log file exists */
    if (!file_exists(log_path)) {
        if (create_empty_file(log_path, mode) != 0) {
            return 1;
        }
    }

    while (g_running) {
        off_t sz = file_size(log_path);
        if (sz >= 0 && sz >= max_bytes) {
            if (rotate_logs(log_path, rotations, mode) != 0) {
                /* In minimal daemon, ignore and retry later */
            }
        }
        sleep((unsigned int)sleep_sec);
    }

    return 0;
}
