## Code: `mini_logrotate.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <errno.h>

#define LINE_BUF_SIZE 1024
#define PATH_BUF_SIZE 256

typedef struct {
    const char *base_path;
    size_t max_bytes;
    int max_files;
    FILE *fp;
    size_t current_size;
} logger_t;

static int set_memory_limit_mb(size_t mb) {
    struct rlimit rl;
    rl.rlim_cur = mb * 1024 * 1024;
    rl.rlim_max = mb * 1024 * 1024;
    return setrlimit(RLIMIT_AS, &rl);
}

static size_t file_size_or_zero(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return (size_t)st.st_size;
    }
    return 0;
}

static int make_rotated_name(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(logger_t *lg) {
    if (lg->fp) {
        fclose(lg->fp);
        lg->fp = NULL;
    }

    char oldp[PATH_BUF_SIZE];
    char newp[PATH_BUF_SIZE];

    if (lg->max_files > 0) {
        if (make_rotated_name(oldp, sizeof(oldp), lg->base_path, lg->max_files) != 0) {
            return -1;
        }
        unlink(oldp);

        for (int i = lg->max_files - 1; i >= 1; --i) {
            if (make_rotated_name(oldp, sizeof(oldp), lg->base_path, i) != 0) return -1;
            if (make_rotated_name(newp, sizeof(newp), lg->base_path, i + 1) != 0) return -1;
            rename(oldp, newp);
        }

        if (make_rotated_name(newp, sizeof(newp), lg->base_path, 1) != 0) {
            return -1;
        }
        rename(lg->base_path, newp);
    } else {
        unlink(lg->base_path);
    }

    lg->fp = fopen(lg->base_path, "a");
    if (!lg->fp) {
        return -1;
    }
    lg->current_size = 0;
    return 0;
}

static int logger_open(logger_t *lg, const char *path, size_t max_bytes, int max_files) {
    lg->base_path = path;
    lg->max_bytes = max_bytes;
    lg->max_files = max_files;
    lg->fp = fopen(path, "a");
    if (!lg->fp) {
        return -1;
    }
    lg->current_size = file_size_or_zero(path);
    return 0;
}

static int logger_write_line(logger_t *lg, const char *line) {
    size_t len = strlen(line);

    if (lg->current_size + len > lg->max_bytes) {
        if (rotate_logs(lg) != 0) {
            return -1;
        }
    }

    if (fwrite(line, 1, len, lg->fp) != len) {
        return -1;
    }

    fflush(lg->fp);
    lg->current_size += len;
    return 0;
}

static void logger_close(logger_t *lg) {
    if (lg->fp) {
        fclose(lg->fp);
        lg->fp = NULL;
    }
}

static void usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s <logfile> <max_bytes> <max_files> [mem_limit_mb]\n"
            "Reads lines from stdin and writes to logfile with size rotation.\n",
            prog);
}

int main(int argc, char **argv) {
    if (argc < 4 || argc > 5) {
        usage(argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    size_t max_bytes = (size_t)strtoull(argv[2], NULL, 10);
    int max_files = atoi(argv[3]);

    if (argc == 5) {
        size_t mem_limit_mb = (size_t)strtoull(argv[4], NULL, 10);
        if (mem_limit_mb > 0) {
            if (set_memory_limit_mb(mem_limit_mb) != 0) {
                perror("setrlimit");
                return 1;
            }
        }
    }

    logger_t lg;
    if (logger_open(&lg, logfile, max_bytes, max_files) != 0) {
        perror("logger_open");
        return 1;
    }

    char line[LINE_BUF_SIZE];

    while (fgets(line, sizeof(line), stdin)) {
        if (logger_write_line(&lg, line) != 0) {
            perror("logger_write_line");
            logger_close(&lg);
            return 1;
        }
    }

    if (ferror(stdin)) {
        perror("stdin");
        logger_close(&lg);
        return 1;
    }

    logger_close(&lg);
    return 0;
}
```

