## `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdlib.h>

#define PATH_MAX_LEN 256
#define ROTATE_NAME_LEN 300

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX_LEN];
    off_t max_size;
    int max_files;
    unsigned int interval_sec;
    int daemonize;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int create_empty_file(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int build_rotated_name(char *out, size_t out_sz, const char *base, int index) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_name[ROTATE_NAME_LEN];
    char new_name[ROTATE_NAME_LEN];
    int i;

    if (cfg->max_files < 1) {
        return 0;
    }

    if (cfg->max_files >= 2) {
        for (i = cfg->max_files - 1; i >= 1; --i) {
            if (build_rotated_name(old_name, sizeof(old_name), cfg->log_path, i) != 0) {
                return -1;
            }
            if (build_rotated_name(new_name, sizeof(new_name), cfg->log_path, i + 1) != 0) {
                return -1;
            }

            if (file_exists(new_name)) {
                unlink(new_name);
            }
            if (file_exists(old_name)) {
                if (rename(old_name, new_name) != 0) {
                    return -1;
                }
            }
        }
    }

    if (build_rotated_name(new_name, sizeof(new_name), cfg->log_path, 1) != 0) {
        return -1;
    }

    if (file_exists(new_name)) {
        unlink(new_name);
    }

    if (file_exists(cfg->log_path)) {
        if (rename(cfg->log_path, new_name) != 0) {
            return -1;
        }
    }

    if (create_empty_file(cfg->log_path) != 0) {
        return -1;
    }

    return 0;
}

static int maybe_rotate(const struct config *cfg) {
    off_t size;

    if (get_file_size(cfg->log_path, &size) != 0) {
        if (errno == ENOENT) {
            return create_empty_file(cfg->log_path);
        }
        return -1;
    }

    if (size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> <max_size_bytes> <max_files> <interval_sec> [-d]\n",
        prog);
}

int main(int argc, char **argv) {
    struct config cfg;
    struct sigaction sa;

    if (argc < 5 || argc > 6) {
        usage(argv[0]);
        return 1;
    }

    memset(&cfg, 0, sizeof(cfg));

    if (strlen(argv[1]) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }
    strcpy(cfg.log_path, argv[1]);

    cfg.max_size = (off_t)atoll(argv[2]);
    cfg.max_files = atoi(argv[3]);
    cfg.interval_sec = (unsigned int)atoi(argv[4]);
    cfg.daemonize = (argc == 6 && strcmp(argv[5], "-d") == 0) ? 1 : 0;

    if (cfg.max_size <= 0 || cfg.max_files < 1 || cfg.interval_sec < 1) {
        fprintf(stderr, "invalid arguments\n");
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            return 1;
        }
    }

    while (g_running) {
        if (maybe_rotate(&cfg) != 0) {
            /* In a stricter implementation, write to syslog or a fixed fd. */
        }
        sleep(cfg.interval_sec);
    }

    return 0;
}
