## Code: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <stdlib.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>

#define PATH_MAX_LEN 256
#define DEFAULT_MAX_SIZE (1024 * 1024)   /* 1 MB */
#define DEFAULT_ROTATIONS 4
#define DEFAULT_INTERVAL 5               /* seconds */

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_size_exceeds(const char *path, off_t max_size) {
    struct stat st;
    if (stat(path, &st) != 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }
    return st.st_size >= max_size;
}

static int rotate_logs(const char *path, int rotations) {
    char oldname[PATH_MAX_LEN];
    char newname[PATH_MAX_LEN];
    int i;

    if (rotations < 1) return 0;

    /* Remove oldest */
    if (snprintf(oldname, sizeof(oldname), "%s.%d", path, rotations) >= (int)sizeof(oldname)) {
        return -1;
    }
    unlink(oldname);

    /* Shift: logfile.(n-1) -> logfile.n */
    for (i = rotations - 1; i >= 1; --i) {
        if (snprintf(oldname, sizeof(oldname), "%s.%d", path, i) >= (int)sizeof(oldname)) {
            return -1;
        }
        if (snprintf(newname, sizeof(newname), "%s.%d", path, i + 1) >= (int)sizeof(newname)) {
            return -1;
        }
        rename(oldname, newname);
    }

    /* Current -> .1 */
    if (snprintf(newname, sizeof(newname), "%s.1", path) >= (int)sizeof(newname)) {
        return -1;
    }

    if (rename(path, newname) != 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    /* Recreate empty log file */
    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void daemonize_minimal(void) {
    pid_t pid = fork();
    if (pid < 0) exit(1);
    if (pid > 0) exit(0);

    if (setsid() < 0) exit(1);

    pid = fork();
    if (pid < 0) exit(1);
    if (pid > 0) exit(0);

    chdir("/");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] -p <logfile> [-s max_bytes] [-n rotations] [-i interval_sec]\n"
        "  -f              foreground mode\n"
        "  -p <logfile>    path to log file\n"
        "  -s <max_bytes>  rotate when size >= max_bytes (default: %d)\n"
        "  -n <rotations>  number of rotated files to keep (default: %d)\n"
        "  -i <seconds>    polling interval (default: %d)\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, DEFAULT_INTERVAL);
}

int main(int argc, char **argv) {
    char path[PATH_MAX_LEN] = {0};
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_INTERVAL;
    int foreground = 0;
    int opt;

    while ((opt = getopt(argc, argv, "fp:s:n:i:")) != -1) {
        switch (opt) {
            case 'f':
                foreground = 1;
                break;
            case 'p':
                if (snprintf(path, sizeof(path), "%s", optarg) >= (int)sizeof(path)) {
                    fprintf(stderr, "Path too long\n");
                    return 1;
                }
                break;
            case 's':
                max_size = (off_t)atoll(optarg);
                break;
            case 'n':
                rotations = atoi(optarg);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (path[0] == '\0' || max_size <= 0 || rotations < 1 || interval < 1) {
        usage(argv[0]);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!foreground) {
        daemonize_minimal();
    }

    while (g_running) {
        int rc = file_size_exceeds(path, max_size);
        if (rc < 0) {
            /* Ignore transient stat errors in minimal implementation */
        } else if (rc > 0) {
            rotate_logs(path, rotations);
        }
        sleep((unsigned int)interval);
    }

    return 0;
}
