## Source: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_BACKUPS 16
#define MIN_SLEEP_SEC 1
#define DEFAULT_SLEEP_SEC 5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void write_stderr(const char *fmt, ...) {
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n < 0) return;
    if ((size_t)n >= sizeof(buf)) n = (int)(sizeof(buf) - 1);
    (void)write(STDERR_FILENO, buf, (size_t)n);
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n;
    if (suffix <= 0) {
        n = snprintf(out, out_sz, "%s", base);
    } else {
        n = snprintf(out, out_sz, "%s.%d", base, suffix);
    }
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const char *path, int backups) {
    if (backups < 1 || backups > MAX_BACKUPS) return -1;

    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    /* Remove oldest */
    if (path_with_suffix(oldp, sizeof(oldp), path, backups) < 0) return -1;
    (void)unlink(oldp);

    /* Shift: N-1 -> N, ..., 1 -> 2 */
    for (int i = backups - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), path, i) < 0) return -1;
        if (path_with_suffix(newp, sizeof(newp), path, i + 1) < 0) return -1;
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                write_stderr("rename(%s -> %s) failed: %s\n", oldp, newp, strerror(errno));
                return -1;
            }
        }
    }

    /* Current -> .1 */
    if (path_with_suffix(newp, sizeof(newp), path, 1) < 0) return -1;
    if (rename(path, newp) < 0) {
        if (errno != ENOENT) {
            write_stderr("rename(%s -> %s) failed: %s\n", path, newp, strerror(errno));
            return -1;
        }
    }

    /* Recreate empty log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        write_stderr("open(%s) failed after rotation: %s\n", path, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

static int check_and_rotate(const char *path, off_t max_size, int backups) {
    struct stat st;
    if (stat(path, &st) < 0) {
        if (errno == ENOENT) {
            int fd = open(path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        write_stderr("stat(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        write_stderr("%s is not a regular file\n", path);
        return -1;
    }

    if (st.st_size >= max_size) {
        return rotate_logs(path, backups);
    }

    return 0;
}

static void usage(const char *prog) {
    write_stderr(
        "Usage: %s [-f] -p <log_path> -s <max_size_bytes> [-n backups] [-t sleep_sec]\n"
        "  -f              run in foreground\n"
        "  -p <log_path>   path to log file\n"
        "  -s <bytes>      rotate when size >= bytes\n"
        "  -n <backups>    number of backups to keep (1-%d, default 3)\n"
        "  -t <sec>        polling interval in seconds (default %d)\n",
        prog, MAX_BACKUPS, DEFAULT_SLEEP_SEC
    );
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_off(const char *s, off_t *out) {
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v <= 0) return -1;
    *out = (off_t)v;
    return 0;
}

int main(int argc, char **argv) {
    const char *path = NULL;
    off_t max_size = 0;
    int backups = 3;
    int sleep_sec = DEFAULT_SLEEP_SEC;
    int foreground = 0;

    int opt;
    while ((opt = getopt(argc, argv, "fp:s:n:t:")) != -1) {
        switch (opt) {
            case 'f':
                foreground = 1;
                break;
            case 'p':
                path = optarg;
                break;
            case 's':
                if (parse_off(optarg, &max_size) < 0) {
                    usage(argv[0]);
                    return 2;
                }
                break;
            case 'n':
                if (parse_int(optarg, &backups) < 0 || backups < 1 || backups > MAX_BACKUPS) {
                    usage(argv[0]);
                    return 2;
                }
                break;
            case 't':
                if (parse_int(optarg, &sleep_sec) < 0 || sleep_sec < MIN_SLEEP_SEC) {
                    usage(argv[0]);
                    return 2;
                }
                break;
            default:
                usage(argv[0]);
                return 2;
        }
    }

    if (!path || max_size <= 0) {
        usage(argv[0]);
        return 2;
    }

    if (install_signals() < 0) {
        write_stderr("failed to install signal handlers\n");
        return 1;
    }

    if (!foreground) {
        if (daemonize_self() < 0) {
            write_stderr("failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    while (!g_stop) {
        (void)check_and_rotate(path, max_size, backups);

        for (int i = 0; i < sleep_sec && !g_stop; ++i) {
            sleep(1);
        }
    }

    return 0;
}
