## Code: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL 5
#define DEFAULT_MAX_SIZE (1024 * 1024)   /* 1 MiB */
#define DEFAULT_ROTATIONS 3

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_memory_limit_bytes(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int touch_empty_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) {
        return -1;
    }
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int build_rotated_name(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldname[PATH_MAX];
    char newname[PATH_MAX];
    struct stat st;

    if (rotations < 1) {
        return 0;
    }

    /* Remove the oldest rotation if it exists */
    if (build_rotated_name(oldname, sizeof(oldname), path, rotations) != 0) {
        return -1;
    }
    unlink(oldname);

    /* Shift .N-1 -> .N down to .1 -> .2 */
    for (int i = rotations - 1; i >= 1; --i) {
        if (build_rotated_name(oldname, sizeof(oldname), path, i) != 0) {
            return -1;
        }
        if (build_rotated_name(newname, sizeof(newname), path, i + 1) != 0) {
            return -1;
        }
        if (rename(oldname, newname) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Preserve mode if original exists */
    mode_t mode = 0644;
    if (stat(path, &st) == 0) {
        mode = st.st_mode & 0777;
    }

    /* Move current log to .1 */
    if (build_rotated_name(newname, sizeof(newname), path, 1) != 0) {
        return -1;
    }
    if (rename(path, newname) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Recreate empty current log */
    if (touch_empty_file(path, mode) != 0) {
        return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> [max_size_bytes] [rotations] [check_interval_sec] [mem_limit_bytes]\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_CHECK_INTERVAL;

    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];

    if (argc >= 3) {
        max_size = (off_t)atoll(argv[2]);
        if (max_size <= 0) {
            fprintf(stderr, "invalid max_size_bytes\n");
            return 1;
        }
    }

    if (argc >= 4) {
        rotations = atoi(argv[3]);
        if (rotations < 1 || rotations > 1000) {
            fprintf(stderr, "invalid rotations\n");
            return 1;
        }
    }

    if (argc >= 5) {
        interval = atoi(argv[4]);
        if (interval < 1) {
            fprintf(stderr, "invalid check_interval_sec\n");
            return 1;
        }
    }

    if (argc >= 6) {
        rlim_t mem_limit = (rlim_t)atoll(argv[5]);
        if (mem_limit > 0) {
            if (set_memory_limit_bytes(mem_limit) != 0) {
                perror("setrlimit");
                return 1;
            }
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Ensure the file exists */
    if (touch_empty_file(logfile, 0644) != 0) {
        perror("create logfile");
        return 1;
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0) {
            if (sz >= max_size) {
                if (rotate_logs(logfile, rotations) != 0) {
                    perror("rotate_logs");
                }
            }
        } else {
            if (errno == ENOENT) {
                if (touch_empty_file(logfile, 0644) != 0) {
                    perror("recreate logfile");
                }
            } else {
                perror("stat");
            }
        }

        sleep((unsigned int)interval);
    }

    return 0;
}
