#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdlib.h>

#define PATH_MAX_LEN 256

typedef struct {
    char log_path[PATH_MAX_LEN];
    off_t max_size;
    int max_files;
    unsigned int interval_sec;
} config_t;

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int create_empty_file(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX_LEN];
    char newp[PATH_MAX_LEN];
    int i, n;

    if (cfg->max_files < 1) {
        return 0;
    }

    for (i = cfg->max_files - 1; i >= 1; --i) {
        n = snprintf(oldp, sizeof(oldp), "%s.%d", cfg->log_path, i);
        if (n < 0 || n >= (int)sizeof(oldp)) return -1;

        n = snprintf(newp, sizeof(newp), "%s.%d", cfg->log_path, i + 1);
        if (n < 0 || n >= (int)sizeof(newp)) return -1;

        (void)unlink(newp);
        (void)rename(oldp, newp);
    }

    n = snprintf(newp, sizeof(newp), "%s.1", cfg->log_path);
    if (n < 0 || n >= (int)sizeof(newp)) return -1;

    (void)unlink(newp);
    if (rename(cfg->log_path, newp) != 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    if (create_empty_file(cfg->log_path) != 0) {
        return -1;
    }

    return 0;
}

static void daemon_loop(const config_t *cfg) {
    off_t sz;

    for (;;) {
        if (file_size(cfg->log_path, &sz) == 0) {
            if (sz >= cfg->max_size) {
                if (rotate_logs(cfg) != 0) {
                    fprintf(stderr, "rotate failed: %s\n", strerror(errno));
                }
            }
        } else {
            if (errno == ENOENT) {
                if (create_empty_file(cfg->log_path) != 0) {
                    fprintf(stderr, "create failed: %s\n", strerror(errno));
                }
            } else {
                fprintf(stderr, "stat failed: %s\n", strerror(errno));
            }
        }

        sleep(cfg->interval_sec);
    }
}

static int parse_off_t(const char *s, off_t *out) {
    char *end;
    long long v;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < 0) {
        return -1;
    }

    *out = (off_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end;
    long v;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }

    *out = (int)v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> <max_size_bytes> <max_files> <interval_sec>\n",
        prog);
}

int main(int argc, char **argv) {
    config_t cfg;

    if (argc != 5) {
        usage(argv[0]);
        return 1;
    }

    memset(&cfg, 0, sizeof(cfg));

    if (strlen(argv[1]) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }
    strcpy(cfg.log_path, argv[1]);

    if (parse_off_t(argv[2], &cfg.max_size) != 0 || cfg.max_size <= 0) {
        fprintf(stderr, "invalid max_size_bytes\n");
        return 1;
    }

    if (parse_int(argv[3], &cfg.max_files) != 0 || cfg.max_files < 1 || cfg.max_files > 99) {
        fprintf(stderr, "invalid max_files\n");
        return 1;
    }

    if (parse_int(argv[4], (int *)&cfg.interval_sec) != 0 || cfg.interval_sec == 0) {
        fprintf(stderr, "invalid interval_sec\n");
        return 1;
    }

    daemon_loop(&cfg);
    return 0;
}
