## Code

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_memory_limits(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;

    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        return -1;
    }
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        perror("setrlimit(RLIMIT_DATA)");
        return -1;
    }
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int make_rotated_name(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) return -1;
    return 0;
}

static int rotate_logs(const char *log_path, int max_files) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (max_files < 1) return 0;

    if (make_rotated_name(oldp, sizeof(oldp), log_path, max_files) != 0)
        return -1;
    unlink(oldp);

    for (int i = max_files - 1; i >= 1; --i) {
        if (make_rotated_name(oldp, sizeof(oldp), log_path, i) != 0)
            return -1;
        if (make_rotated_name(newp, sizeof(newp), log_path, i + 1) != 0)
            return -1;
        rename(oldp, newp);
    }

    if (make_rotated_name(newp, sizeof(newp), log_path, 1) != 0)
        return -1;

    if (rename(log_path, newp) != 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    int fd = open(log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> <max_size_bytes> <max_rotated_files> <check_interval_sec> <mem_limit_bytes> [--no-daemon]\n",
        prog);
}

int main(int argc, char **argv) {
    if (argc < 6 || argc > 7) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    off_t max_size = (off_t)strtoll(argv[2], NULL, 10);
    int max_files = atoi(argv[3]);
    int interval_sec = atoi(argv[4]);
    rlim_t mem_limit = (rlim_t)strtoull(argv[5], NULL, 10);
    bool no_daemon = false;

    if (argc == 7 && strcmp(argv[6], "--no-daemon") == 0) {
        no_daemon = true;
    }

    if (max_size <= 0 || max_files < 1 || interval_sec < 1 || mem_limit < (rlim_t)(1024 * 1024)) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    if (set_memory_limits(mem_limit) != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!no_daemon) {
        if (daemonize() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size(log_path, &sz) == 0) {
            if (sz >= max_size) {
                if (rotate_logs(log_path, max_files) != 0) {
                    /* Minimal daemon: ignore errors and continue */
                }
            }
        }
        sleep((unsigned int)interval_sec);
    }

    return 0;
}
