## Source: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_SIZE (1024 * 1024)   /* 1 MiB */
#define DEFAULT_ROTATIONS 5
#define DEFAULT_INTERVAL 5               /* seconds */
#define DEFAULT_MEM_LIMIT (8 * 1024 * 1024) /* 8 MiB */

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int make_rotated_name(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (rotations < 1) {
        return 0;
    }

    if (make_rotated_name(oldp, sizeof(oldp), path, rotations) != 0) {
        return -1;
    }
    unlink(oldp);

    for (int i = rotations - 1; i >= 1; --i) {
        if (make_rotated_name(oldp, sizeof(oldp), path, i) != 0) {
            return -1;
        }
        if (make_rotated_name(newp, sizeof(newp), path, i + 1) != 0) {
            return -1;
        }
        if (file_exists(oldp)) {
            if (rename(oldp, newp) != 0) {
                return -1;
            }
        }
    }

    if (make_rotated_name(newp, sizeof(newp), path, 1) != 0) {
        return -1;
    }

    if (file_exists(path)) {
        if (rename(path, newp) != 0) {
            return -1;
        }
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int check_and_rotate(const char *path, off_t max_size, int rotations) {
    struct stat st;
    if (stat(path, &st) != 0) {
        if (errno == ENOENT) {
            int fd = open(path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= max_size) {
        return rotate_logs(path, rotations);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_size_bytes] [-n rotations] [-i interval_sec] [-m mem_limit_bytes]\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logfile = NULL;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_INTERVAL;
    rlim_t mem_limit = DEFAULT_MEM_LIMIT;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:")) != -1) {
        switch (opt) {
            case 'f':
                logfile = optarg;
                break;
            case 's':
                max_size = (off_t)atoll(optarg);
                break;
            case 'n':
                rotations = atoi(optarg);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'm':
                mem_limit = (rlim_t)atoll(optarg);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (!logfile || max_size <= 0 || rotations < 1 || interval < 1 || mem_limit < (1024 * 1024)) {
        usage(argv[0]);
        return 1;
    }

    if (set_memory_limit(mem_limit) != 0) {
        perror("setrlimit");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_stderr("minilogd: watching %s, max_size=%lld, rotations=%d, interval=%d, mem_limit=%lld",
               logfile,
               (long long)max_size,
               rotations,
               interval,
               (long long)mem_limit);

    while (g_running) {
        if (check_and_rotate(logfile, max_size, rotations) != 0) {
            log_stderr("minilogd: error: %s", strerror(errno));
        }
        sleep((unsigned int)interval);
    }

    log_stderr("minilogd: exiting");
    return 0;
}
