static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int set_memory_limit_bytes(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static int file_size(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *sz = st.st_size;
    return 0;
}

static int path_with_suffix(char *dst, size_t dstsz, const char *base, int suffix) {
    int n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int recreate_empty_file_like(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) {
        return -1;
    }
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *log_path, int keep) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    struct stat st;

    if (keep < 1) {
        errno = EINVAL;
        return -1;
    }

    if (stat(log_path, &st) != 0) {
        return -1;
    }

    for (int i = keep; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), log_path, i) != 0) {
            return -1;
        }

        if (i == keep) {
            if (unlink(oldp) != 0 && errno != ENOENT) {
                return -1;
            }
        } else {
            if (path_with_suffix(newp, sizeof(newp), log_path, i + 1) != 0) {
                return -1;
            }
            if (rename(oldp, newp) != 0 && errno != ENOENT) {
                return -1;
            }
        }
    }

    if (path_with_suffix(newp, sizeof(newp), log_path, 1) != 0) {
        return -1;
    }

    if (rename(log_path, newp) != 0) {
        return -1;
    }

    if (recreate_empty_file_like(log_path, st.st_mode & 0777) != 0) {
        return -1;
    }

    return 0;
}

static int daemonize_minimal(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) {
        return -1;
    }

    if (dup2(nullfd, STDIN_FILENO) < 0) return -1;
    if (dup2(nullfd, STDOUT_FILENO) < 0) return -1;
    if (dup2(nullfd, STDERR_FILENO) < 0) return -1;

    if (nullfd > STDERR_FILENO) {
        close(nullfd);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] <log_path> <max_bytes> <keep_count> <interval_sec> <mem_limit_bytes>\n"
        "  -f  foreground mode (do not daemonize)\n",
        prog);
}

int main(int argc, char **argv) {
    int argi = 1;
    int foreground = 0;

    if (argc > 1 && strcmp(argv[1], "-f") == 0) {
        foreground = 1;
        argi++;
    }

    if (argc - argi != 5) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[argi++];
    unsigned long long max_bytes = strtoull(argv[argi++], NULL, 10);
    int keep = atoi(argv[argi++]);
    int interval_sec = atoi(argv[argi++]);
    unsigned long long mem_limit = strtoull(argv[argi++], NULL, 10);

    if (max_bytes == 0 || keep < 1 || interval_sec < 1 || mem_limit < (1024 * 1024)) {
        usage(argv[0]);
        return 1;
    }

    if (set_memory_limit_bytes((rlim_t)mem_limit) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!foreground) {
        if (daemonize_minimal() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (!g_stop) {
        off_t sz = 0;
        if (file_size(log_path, &sz) == 0) {
            if ((unsigned long long)sz >= max_bytes) {
                if (rotate_logs(log_path, keep) != 0) {
                    if (foreground) {
                        log_stderr("rotate failed for %s: %s\n", log_path, strerror(errno));
                    }
                }
            }
        } else {
            if (errno != ENOENT && foreground) {
                log_stderr("stat failed for %s: %s\n", log_path, strerror(errno));
            }
        }

        sleep((unsigned int)interval_sec);
    }

    return 0;
}
