## `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MAX_PATH_LEN 256
#define DEFAULT_CHECK_INTERVAL 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (1024 * 1024) /* 1 MiB */

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[MAX_PATH_LEN];
    off_t max_size;
    int max_rotations;
    unsigned int check_interval;
    int daemonize;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int do_daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(char *out, size_t out_sz, const char *base, int idx) {
    int n = snprintf(out, out_sz, "%s.%d", base, idx);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];
    int i;

    /* Remove oldest */
    if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, cfg->max_rotations) < 0)
        return -1;
    unlink(oldp);

    /* Shift N-1..1 upward */
    for (i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(oldp, sizeof(oldp), cfg->log_path, i) < 0)
            return -1;
        if (build_rotated_path(newp, sizeof(newp), cfg->log_path, i + 1) < 0)
            return -1;
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    /* Current log -> .1 */
    if (build_rotated_path(newp, sizeof(newp), cfg->log_path, 1) < 0)
        return -1;

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    /* Create fresh empty log file */
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-i interval] [-d]\n"
        "  -f logfile     Path to log file\n"
        "  -s max_bytes   Rotate when file exceeds this size (default: %d)\n"
        "  -n rotations   Number of rotated files to keep (default: %d)\n"
        "  -i interval    Check interval in seconds (default: %d)\n"
        "  -d             Daemonize\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_MAX_ROTATIONS, DEFAULT_CHECK_INTERVAL);
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg->check_interval = DEFAULT_CHECK_INTERVAL;
    cfg->daemonize = 0;

    while ((opt = getopt(argc, argv, "f:s:n:i:d")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) return -1;
                strcpy(cfg->log_path, optarg);
                break;
            case 's':
                cfg->max_size = (off_t)atoll(optarg);
                if (cfg->max_size <= 0) return -1;
                break;
            case 'n':
                cfg->max_rotations = atoi(optarg);
                if (cfg->max_rotations <= 0 || cfg->max_rotations > 999) return -1;
                break;
            case 'i':
                cfg->check_interval = (unsigned int)atoi(optarg);
                if (cfg->check_interval == 0) return -1;
                break;
            case 'd':
                cfg->daemonize = 1;
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0') return -1;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    off_t sz;

    if (parse_args(argc, argv, &cfg) < 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signals() < 0) {
        perror("install_signals");
        return 1;
    }

    if (cfg.daemonize) {
        if (do_daemonize() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    /* Ensure file exists */
    int fd = open(cfg.log_path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        perror("open log");
        return 1;
    }
    close(fd);

    while (g_running) {
        if (file_size(cfg.log_path, &sz) == 0) {
            if (sz >= cfg.max_size) {
                if (rotate_logs(&cfg) < 0) {
                    /* In minimal daemon, ignore and retry later */
                }
            }
        }
        sleep(cfg.check_interval);
    }

    return 0;
}
