## Minimal implementation: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define MAX_PATH_LEN 512
#define LOG_BUF_LEN 256

static volatile sig_atomic_t g_terminate = 0;
static volatile sig_atomic_t g_reload = 0;

struct config {
    char logfile[MAX_PATH_LEN];
    off_t max_size;
    int max_files;
    unsigned interval_sec;
    int daemonize;
};

static void on_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_terminate = 1;
    } else if (sig == SIGHUP) {
        g_reload = 1;
    }
}

static void write_stderr(const char *fmt, ...) {
    char buf[LOG_BUF_LEN];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n < 0) return;
    size_t len = (size_t)n;
    if (len >= sizeof(buf)) len = sizeof(buf) - 1;
    (void)write(STDERR_FILENO, buf, len);
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int set_memory_limit_bytes(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > 2) close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int rotate_logs(const char *base, int max_files) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    if (max_files < 1) return 0;

    if (path_with_suffix(oldp, sizeof(oldp), base, max_files) < 0)
        return -1;
    (void)unlink(oldp);

    for (int i = max_files - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), base, i) < 0)
            return -1;
        if (path_with_suffix(newp, sizeof(newp), base, i + 1) < 0)
            return -1;
        if (rename(oldp, newp) < 0) {
            if (errno != ENOENT) return -1;
        }
    }

    if (path_with_suffix(newp, sizeof(newp), base, 1) < 0)
        return -1;

    if (rename(base, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static int ensure_logfile_exists(const char *path) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static void usage(const char *prog) {
    write_stderr(
        "Usage: %s -f <logfile> -s <max_bytes> [-n max_files] [-i interval] [-d] [-m mem_bytes]\n",
        prog
    );
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_files = 5;
    cfg.interval_sec = 5;
    cfg.daemonize = 0;

    rlim_t mem_limit = 0;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:dm:")) != -1) {
        switch (opt) {
            case 'f':
                strncpy(cfg.logfile, optarg, sizeof(cfg.logfile) - 1);
                cfg.logfile[sizeof(cfg.logfile) - 1] = '\0';
                break;
            case 's':
                cfg.max_size = (off_t)atoll(optarg);
                break;
            case 'n':
                cfg.max_files = atoi(optarg);
                break;
            case 'i':
                cfg.interval_sec = (unsigned)atoi(optarg);
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'm':
                mem_limit = (rlim_t)atoll(optarg);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.logfile[0] == '\0' || cfg.max_size <= 0 || cfg.max_files < 1 || cfg.interval_sec == 0) {
        usage(argv[0]);
        return 1;
    }

    if (mem_limit > 0) {
        if (set_memory_limit_bytes(mem_limit) < 0) {
            write_stderr("failed to set memory limit: %s\n", strerror(errno));
            return 1;
        }
    }

    if (install_signals() < 0) {
        write_stderr("failed to install signals: %s\n", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            write_stderr("failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    if (ensure_logfile_exists(cfg.logfile) < 0) {
        write_stderr("failed to create logfile: %s\n", strerror(errno));
        return 1;
    }

    while (!g_terminate) {
        off_t sz = 0;

        if (file_size(cfg.logfile, &sz) == 0) {
            if (sz >= cfg.max_size) {
                if (rotate_logs(cfg.logfile, cfg.max_files) < 0) {
                    write_stderr("rotation failed for %s: %s\n", cfg.logfile, strerror(errno));
                } else {
                    if (ensure_logfile_exists(cfg.logfile) < 0) {
                        write_stderr("failed to recreate logfile: %s\n", strerror(errno));
                    }
                }
            }
        } else {
            if (errno != ENOENT) {
                write_stderr("stat failed for %s: %s\n", cfg.logfile, strerror(errno));
            }
            if (ensure_logfile_exists(cfg.logfile) < 0) {
                write_stderr("failed to ensure logfile exists: %s\n", strerror(errno));
            }
        }

        if (g_reload) {
            g_reload = 0;
            /* Minimal version: no config reload from file.
               SIGHUP simply forces existence check next loop. */
        }

        unsigned slept = 0;
        while (slept < cfg.interval_sec && !g_terminate) {
            sleep(1);
            ++slept;
        }
    }

    return 0;
}
