## Minimal C implementation

```c
// mlogrotate.c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>

#define MAX_PATH 512
#define DEFAULT_CHECK_INTERVAL 5
#define DEFAULT_ROTATIONS 3
#define DEFAULT_MAX_SIZE (1024 * 1024)   // 1 MiB
#define DEFAULT_MEM_LIMIT (8 * 1024 * 1024) // 8 MiB

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;

    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    umask(027);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int touch_empty_file(const char *path, mode_t mode) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const char *path, int rotations) {
    char oldp[MAX_PATH];
    char newp[MAX_PATH];
    int i;

    for (i = rotations - 1; i >= 1; --i) {
        int n1 = snprintf(oldp, sizeof(oldp), "%s.%d", path, i);
        int n2 = snprintf(newp, sizeof(newp), "%s.%d", path, i + 1);
        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(oldp) || n2 >= (int)sizeof(newp)) {
            return -1;
        }
        rename(oldp, newp);
    }

    int n = snprintf(newp, sizeof(newp), "%s.1", path);
    if (n < 0 || n >= (int)sizeof(newp)) {
        return -1;
    }

    if (rename(path, newp) != 0) {
        if (errno != ENOENT) return -1;
    }

    if (touch_empty_file(path, 0640) != 0) {
        return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s <logfile> [max_size_bytes] [rotations] [check_interval_sec] [mem_limit_bytes]\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int interval = DEFAULT_CHECK_INTERVAL;
    rlim_t mem_limit = DEFAULT_MEM_LIMIT;

    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];

    if (argc > 2) max_size = (off_t)atoll(argv[2]);
    if (argc > 3) rotations = atoi(argv[3]);
    if (argc > 4) interval = atoi(argv[4]);
    if (argc > 5) mem_limit = (rlim_t)atoll(argv[5]);

    if (rotations < 1 || rotations > 100) {
        return 1;
    }
    if (interval < 1 || interval > 3600) {
        return 1;
    }
    if (max_size < 1) {
        return 1;
    }

    if (set_memory_limit(mem_limit) != 0) {
        perror("set_memory_limit");
        return 1;
    }

    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);
    signal(SIGHUP, handle_signal);

    if (daemonize() != 0) {
        perror("daemonize");
        return 1;
    }

    while (g_running) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0) {
            if (sz >= max_size) {
                rotate_logs(logfile, rotations);
            }
        } else {
            touch_empty_file(logfile, 0640);
        }

        sleep((unsigned int)interval);
    }

    return 0;
}
```

