## File: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_MS 1000
#define DEFAULT_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#define DEFAULT_MEM_LIMIT_MB 16

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    size_t max_size;
    int rotations;
    int poll_ms;
    int daemonize;
    int mem_limit_mb;
};

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f <logfile> [-s max_bytes] [-n rotations] [-p poll_ms] [-d] [-m mem_mb]\n"
        "  -f logfile     Path to log file to monitor\n"
        "  -s max_bytes   Rotate when file exceeds this size (default: %d)\n"
        "  -n rotations   Number of rotated files to keep (default: %d)\n"
        "  -p poll_ms     Poll interval in ms (default: %d)\n"
        "  -d             Daemonize\n"
        "  -m mem_mb      Address-space memory limit in MB (default: %d)\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_ROTATIONS, DEFAULT_POLL_MS, DEFAULT_MEM_LIMIT_MB);
}

static int set_memory_limit_mb(int mb) {
    if (mb <= 0) return 0;
    struct rlimit rl;
    rl.rlim_cur = (rlim_t)mb * 1024 * 1024;
    rl.rlim_max = (rlim_t)mb * 1024 * 1024;
    return setrlimit(RLIMIT_AS, &rl);
}

static int make_daemon(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
        if (!g_running) break;
    }
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->rotations <= 0) {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            return -1;
        }
        return 0;
    }

    if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->rotations) < 0) {
        return -1;
    }
    if (unlink(oldp) < 0 && errno != ENOENT) {
        return -1;
    }

    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) < 0) return -1;
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) < 0) return -1;

        if (rename(oldp, newp) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            int fd = open(cfg->log_path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
            return 0;
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if ((uintmax_t)st.st_size >= (uintmax_t)cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s[0] || (end && *end)) return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_size(const char *s, size_t *out) {
    char *end = NULL;
    unsigned long long v = strtoull(s, &end, 10);
    if (!s[0] || (end && *end)) return -1;
    *out = (size_t)v;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.max_size = DEFAULT_MAX_SIZE;
    cfg.rotations = DEFAULT_ROTATIONS;
    cfg.poll_ms = DEFAULT_POLL_MS;
    cfg.mem_limit_mb = DEFAULT_MEM_LIMIT_MB;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:dm:")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    dprintf(STDERR_FILENO, "Path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_size(optarg, &cfg.max_size) < 0) {
                    dprintf(STDERR_FILENO, "Invalid size\n");
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.rotations) < 0 || cfg.rotations < 0) {
                    dprintf(STDERR_FILENO, "Invalid rotations\n");
                    return 1;
                }
                break;
            case 'p':
                if (parse_int(optarg, &cfg.poll_ms) < 0 || cfg.poll_ms <= 0) {
                    dprintf(STDERR_FILENO, "Invalid poll interval\n");
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'm':
                if (parse_int(optarg, &cfg.mem_limit_mb) < 0 || cfg.mem_limit_mb <= 0) {
                    dprintf(STDERR_FILENO, "Invalid memory limit\n");
                    return 1;
                }
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (set_memory_limit_mb(cfg.mem_limit_mb) < 0) {
        dprintf(STDERR_FILENO, "Failed to set memory limit: %s\n", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (make_daemon() < 0) {
            dprintf(STDERR_FILENO, "Failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    while (g_running) {
        if (check_and_rotate(&cfg) < 0) {
            /* Minimal daemon: ignore transient errors and retry later */
        }
        sleep_ms(cfg.poll_ms);
    }

    return 0;
}
