use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};

use anyhow::Result;
use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use sysinfo::{Disks, System};
use tokio::time;
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    available_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks: Vec<DiskSnapshot>,
    sampled_at_unix_ms: u128,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
    used_space_bytes: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    http_bind: String,
    cpu_warn_percent: f32,
    memory_warn_percent: f64,
    disk_warn_percent: f64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            http_bind: "127.0.0.1:8080".to_string(),
            cpu_warn_percent: 90.0,
            memory_warn_percent: 90.0,
            disk_warn_percent: 90.0,
        }
    }
}

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<MetricsSnapshot>>,
    config: Arc<Config>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let config = Arc::new(Config::default());

    let initial_metrics = MetricsSnapshot {
        cpu_usage_percent: 0.0,
        total_memory_bytes: 0,
        used_memory_bytes: 0,
        available_memory_bytes: 0,
        total_swap_bytes: 0,
        used_swap_bytes: 0,
        load_avg_one: 0.0,
        load_avg_five: 0.0,
        load_avg_fifteen: 0.0,
        disks: Vec::new(),
        sampled_at_unix_ms: now_unix_ms(),
    };

    let state = AppState {
        metrics: Arc::new(RwLock::new(initial_metrics)),
        config: config.clone(),
    };

    let sampler_state = state.clone();
    tokio::spawn(async move {
        if let Err(e) = sampler_loop(sampler_state).await {
            error!("sampler loop exited: {e:?}");
        }
    });

    let app = Router::new()
        .route("/healthz", get(healthz))
        .route("/metrics", get(get_metrics))
        .with_state(state.clone());

    let addr: SocketAddr = config.http_bind.parse()?;
    info!("starting HTTP server on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,resourced=debug".to_string()),
        )
        .init();
}

async fn healthz() -> impl IntoResponse {
    "ok"
}

async fn get_metrics(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.metrics.read().clone();
    Json(snapshot)
}

async fn sampler_loop(state: AppState) -> Result<()> {
    let mut system = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    let interval = Duration::from_millis(state.config.sample_interval_ms);
    let mut ticker = time::interval(interval);
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    // Prime CPU measurement
    system.refresh_cpu_usage();
    time::sleep(Duration::from_millis(250)).await;

    loop {
        ticker.tick().await;

        system.refresh_cpu_usage();
        system.refresh_memory();
        disks.refresh();

        let cpu = system.global_cpu_usage();

        let total_mem = system.total_memory();
        let used_mem = system.used_memory();
        let available_mem = total_mem.saturating_sub(used_mem);

        let total_swap = system.total_swap();
        let used_swap = system.used_swap();

        let load = System::load_average();

        let disk_snapshots: Vec<DiskSnapshot> = disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                let used = total.saturating_sub(avail);
                let used_percent = if total == 0 {
                    0.0
                } else {
                    (used as f64 / total as f64) * 100.0
                };

                DiskSnapshot {
                    name: d.name().to_string_lossy().to_string(),
                    mount_point: d.mount_point().to_string_lossy().to_string(),
                    total_space_bytes: total,
                    available_space_bytes: avail,
                    used_space_bytes: used,
                    used_percent,
                }
            })
            .collect();

        let snapshot = MetricsSnapshot {
            cpu_usage_percent: cpu,
            total_memory_bytes: total_mem,
            used_memory_bytes: used_mem,
            available_memory_bytes: available_mem,
            total_swap_bytes: total_swap,
            used_swap_bytes: used_swap,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            disks: disk_snapshots,
            sampled_at_unix_ms: now_unix_ms(),
        };

        evaluate_policies(&snapshot, &state.config);

        {
            let mut guard = state.metrics.write();
            *guard = snapshot;
        }
    }
}

fn evaluate_policies(snapshot: &MetricsSnapshot, config: &Config) {
    if snapshot.cpu_usage_percent >= config.cpu_warn_percent {
        warn!(
            cpu = snapshot.cpu_usage_percent,
            threshold = config.cpu_warn_percent,
            "high CPU usage detected"
        );
    }

    if snapshot.total_memory_bytes > 0 {
        let mem_used_percent =
            (snapshot.used_memory_bytes as f64 / snapshot.total_memory_bytes as f64) * 100.0;

        if mem_used_percent >= config.memory_warn_percent {
            warn!(
                mem_used_percent = mem_used_percent,
                threshold = config.memory_warn_percent,
                "high memory usage detected"
            );
        }
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= config.disk_warn_percent {
            warn!(
                disk = %disk.mount_point,
                used_percent = disk.used_percent,
                threshold = config.disk_warn_percent,
                "high disk usage detected"
            );
        }
    }
}

fn now_unix_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0)
}
