# Example extension: action worker skeleton

```rust
use tokio::sync::mpsc;

#[derive(Debug, Clone)]
enum Event {
    HighCpu(f32),
    HighMemory(f64),
    HighDisk { mount: String, used_percent: f64 },
}

async fn action_worker(mut rx: mpsc::Receiver<Event>) {
    while let Some(event) = rx.recv().await {
        match event {
            Event::HighCpu(v) => {
                tracing::warn!("action worker received high CPU event: {}", v);
            }
            Event::HighMemory(v) => {
                tracing::warn!("action worker received high memory event: {}", v);
            }
            Event::HighDisk { mount, used_percent } => {
                tracing::warn!("action worker received high disk event: {} {}", mount, used_percent);
            }
        }
    }
}
```

Then the sampler emits events into a bounded queue.

