# `src/main.rs`

```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, Instant};
use sysinfo::{Disks, Pid as SysPid, ProcessRefreshKind, RefreshKind, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::{broadcast, RwLock};
use tokio::time;
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const HISTORY_LIMIT: usize = 120;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    cpu_alert_percent: f32,
    mem_alert_percent: f32,
    disk_alert_percent: f32,
    process_cpu_limit: f32,
    process_mem_limit_kb: u64,
    auto_kill: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            cpu_alert_percent: 90.0,
            mem_alert_percent: 90.0,
            disk_alert_percent: 95.0,
            process_cpu_limit: 300.0,
            process_mem_limit_kb: 1024 * 1024,
            auto_kill: false,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    mem_kb: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp_ms: u128,
    cpu_percent: f32,
    used_memory_kb: u64,
    total_memory_kb: u64,
    memory_percent: f32,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct State {
    latest: Option<SystemSnapshot>,
    history: Vec<SystemSnapshot>,
    config: Config,
    alerts: Vec<String>,
    last_action: HashMap<i32, Instant>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    GetStatus,
    GetHistory,
    GetConfig,
    SetConfig { config: Config },
    ListAlerts,
    SignalProcess { pid: i32, signal: String },
    KillProcess { pid: i32 },
    TerminateProcess { pid: i32 },
    ReloadProcess { pid: i32 },
}

#[derive(Debug, Serialize)]
struct Response<T: Serialize> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

impl<T: Serialize> Response<T> {
    fn ok(data: T) -> Self {
        Self {
            ok: true,
            data: Some(data),
            error: None,
        }
    }

    fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            data: None,
            error: Some(msg.into()),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).ok();
    }

    let state = Arc::new(RwLock::new(State {
        config: Config::default(),
        ..Default::default()
    }));

    let (shutdown_tx, _) = broadcast::channel::<()>(8);

    let monitor_state = Arc::clone(&state);
    let monitor_shutdown = shutdown_tx.subscribe();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_shutdown).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_state = Arc::clone(&state);
    let server_shutdown = shutdown_tx.subscribe();
    let server_task = tokio::spawn(async move {
        if let Err(e) = api_server(server_state, server_shutdown).await {
            error!("api server failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    let _ = shutdown_tx.send(());
    let _ = monitor_task.await;
    let _ = server_task.await;

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).ok();
    }

    info!("daemon exited");
    Ok(())
}

async fn monitor_loop(
    state: Arc<RwLock<State>>,
    mut shutdown: broadcast::Receiver<()>,
) -> Result<()> {
    let mut ticker = time::interval(SAMPLE_INTERVAL);

    let refresh = RefreshKind::new()
        .with_memory()
        .with_cpu()
        .with_processes(ProcessRefreshKind::everything());

    let mut sys = System::new_with_specifics(refresh);
    let mut disks = Disks::new_with_refreshed_list();

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("monitor loop shutting down");
                break;
            }
            _ = ticker.tick() => {
                sys.refresh_memory();
                sys.refresh_cpu();
                sys.refresh_processes();
                disks.refresh();

                let total_memory_kb = sys.total_memory();
                let used_memory_kb = sys.used_memory();
                let memory_percent = if total_memory_kb > 0 {
                    (used_memory_kb as f32 / total_memory_kb as f32) * 100.0
                } else {
                    0.0
                };

                let cpu_percent = sys.global_cpu_info().cpu_usage();

                let disk_infos = disks.iter().map(|d| {
                    let total = d.total_space();
                    let avail = d.available_space();
                    let used_percent = if total > 0 {
                        ((total - avail) as f32 / total as f32) * 100.0
                    } else {
                        0.0
                    };
                    DiskInfo {
                        name: d.name().to_string_lossy().to_string(),
                        mount_point: d.mount_point().to_string_lossy().to_string(),
                        total_space: total,
                        available_space: avail,
                        used_percent,
                    }
                }).collect::<Vec<_>>();

                let mut processes = sys.processes()
                    .iter()
                    .map(|(pid, p)| ProcessInfo {
                        pid: pid.as_u32() as i32,
                        name: p.name().to_string_lossy().to_string(),
                        cpu_percent: p.cpu_usage(),
                        mem_kb: p.memory(),
                        status: format!("{:?}", p.status()),
                    })
                    .collect::<Vec<_>>();

                processes.sort_by(|a, b| {
                    b.cpu_percent
                        .partial_cmp(&a.cpu_percent)
                        .unwrap_or(std::cmp::Ordering::Equal)
                        .then_with(|| b.mem_kb.cmp(&a.mem_kb))
                });

                let top_processes = processes.iter().take(20).cloned().collect::<Vec<_>>();

                let snapshot = SystemSnapshot {
                    timestamp_ms: std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis(),
                    cpu_percent,
                    used_memory_kb,
                    total_memory_kb,
                    memory_percent,
                    disks: disk_infos.clone(),
                    top_processes: top_processes.clone(),
                };

                let mut st = state.write().await;
                st.latest = Some(snapshot.clone());
                st.history.push(snapshot.clone());
                if st.history.len() > HISTORY_LIMIT {
                    let drain = st.history.len() - HISTORY_LIMIT;
                    st.history.drain(0..drain);
                }

                evaluate_rules(&mut st, &snapshot, &top_processes);
            }
        }
    }

    Ok(())
}

fn evaluate_rules(state: &mut State, snapshot: &SystemSnapshot, processes: &[ProcessInfo]) {
    let cfg = state.config.clone();

    if snapshot.cpu_percent >= cfg.cpu_alert_percent {
        let msg = format!("high cpu usage: {:.2}%", snapshot.cpu_percent);
        warn!("{msg}");
        state.alerts.push(msg);
    }

    if snapshot.memory_percent >= cfg.mem_alert_percent {
        let msg = format!("high memory usage: {:.2}%", snapshot.memory_percent);
        warn!("{msg}");
        state.alerts.push(msg);
    }

    for d in &snapshot.disks {
        if d.used_percent >= cfg.disk_alert_percent {
            let msg = format!(
                "disk usage alert: mount={} used={:.2}%",
                d.mount_point, d.used_percent
            );
            warn!("{msg}");
            state.alerts.push(msg);
        }
    }

    for p in processes {
        let over_cpu = p.cpu_percent >= cfg.process_cpu_limit;
        let over_mem = p.mem_kb >= cfg.process_mem_limit_kb;

        if over_cpu || over_mem {
            let msg = format!(
                "process limit exceeded pid={} name={} cpu={:.2}% mem={}KB",
                p.pid, p.name, p.cpu_percent, p.mem_kb
            );
            warn!("{msg}");
            state.alerts.push(msg);

            if cfg.auto_kill {
                let cooldown = Duration::from_secs(30);
                let now = Instant::now();
                let should_act = match state.last_action.get(&p.pid) {
                    Some(last) => now.duration_since(*last) > cooldown,
                    None => true,
                };

                if should_act {
                    match kill(Pid::from_raw(p.pid), Signal::SIGTERM) {
                        Ok(_) => {
                            let act = format!("sent SIGTERM to pid={}", p.pid);
                            warn!("{act}");
                            state.alerts.push(act);
                            state.last_action.insert(p.pid, now);
                        }
                        Err(e) => {
                            let act = format!("failed to signal pid={} err={}", p.pid, e);
                            error!("{act}");
                            state.alerts.push(act);
                        }
                    }
                }
            }
        }
    }

    if state.alerts.len() > 1000 {
        let drain = state.alerts.len() - 1000;
        state.alerts.drain(0..drain);
    }
}

async fn api_server(
    state: Arc<RwLock<State>>,
    mut shutdown: broadcast::Receiver<()>,
) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind socket {}", SOCKET_PATH))?;

    info!("api server listening on {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("api server shutting down");
                break;
            }
            res = listener.accept() => {
                let (stream, _) = res?;
                let state = Arc::clone(&state);
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state).await {
                        error!("client error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<State>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Command = match serde_json::from_str(&line) {
            Ok(c) => c,
            Err(e) => {
                let resp = Response::<serde_json::Value>::err(format!("invalid command: {e}"));
                writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
                writer.write_all(b"\n").await?;
                continue;
            }
        };

        let response = execute_command(cmd, &state).await;
        writer.write_all(serde_json::to_string(&response)?.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn execute_command(
    cmd: Command,
    state: &Arc<RwLock<State>>,
) -> Response<serde_json::Value> {
    match cmd {
        Command::GetStatus => {
            let st = state.read().await;
            match &st.latest {
                Some(s) => match serde_json::to_value(s) {
                    Ok(v) => Response::ok(v),
                    Err(e) => Response::err(e.to_string()),
                },
                None => Response::err("no snapshot available yet"),
            }
        }
        Command::GetHistory => {
            let st = state.read().await;
            match serde_json::to_value(&st.history) {
                Ok(v) => Response::ok(v),
                Err(e) => Response::err(e.to_string()),
            }
        }
        Command::GetConfig => {
            let st = state.read().await;
            match serde_json::to_value(&st.config) {
                Ok(v) => Response::ok(v),
                Err(e) => Response::err(e.to_string()),
            }
        }
        Command::SetConfig { config } => {
            let mut st = state.write().await;
            st.config = config;
            Response::ok(serde_json::json!({"message": "config updated"}))
        }
        Command::ListAlerts => {
            let st = state.read().await;
            match serde_json::to_value(&st.alerts) {
                Ok(v) => Response::ok(v),
                Err(e) => Response::err(e.to_string()),
            }
        }
        Command::SignalProcess { pid, signal } => {
            match parse_signal(&signal).and_then(|sig| send_signal(pid, sig)) {
                Ok(_) => Response::ok(serde_json::json!({"message": format!("signal sent to {}", pid)})),
                Err(e) => Response::err(e.to_string()),
            }
        }
        Command::KillProcess { pid } => {
            match send_signal(pid, Signal::SIGKILL) {
                Ok(_) => Response::ok(serde_json::json!({"message": format!("SIGKILL sent to {}", pid)})),
                Err(e) => Response::err(e.to_string()),
            }
        }
        Command::TerminateProcess { pid } => {
            match send_signal(pid, Signal::SIGTERM) {
                Ok(_) => Response::ok(serde_json::json!({"message": format!("SIGTERM sent to {}", pid)})),
                Err(e) => Response::err(e.to_string()),
            }
        }
        Command::ReloadProcess { pid } => {
            match send_signal(pid, Signal::SIGHUP) {
                Ok(_) => Response::ok(serde_json::json!({"message": format!("SIGHUP sent to {}", pid)})),
                Err(e) => Response::err(e.to_string()),
            }
        }
    }
}

fn parse_signal(s: &str) -> Result<Signal> {
    match s.to_uppercase().as_str() {
        "TERM" | "SIGTERM" => Ok(Signal::SIGTERM),
        "KILL" | "SIGKILL" => Ok(Signal::SIGKILL),
        "HUP" | "SIGHUP" => Ok(Signal::SIGHUP),
        "INT" | "SIGINT" => Ok(Signal::SIGINT),
        _ => anyhow::bail!("unsupported signal: {}", s),
    }
}

fn send_signal(pid: i32, sig: Signal) -> Result<()> {
    kill(Pid::from_raw(pid), sig).with_context(|| format!("failed to send {:?} to pid {}", sig, pid))?;
    Ok(())
}
