use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{
    CpuRefreshKind, DiskRefreshKind, MemoryRefreshKind, Pid as SysPid, ProcessRefreshKind,
    ProcessesToUpdate, RefreshKind, System,
};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize)]
struct ProcInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct Snapshot {
    timestamp_unix: u64,
    uptime_seconds: u64,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    cpu_usage_percent: f32,
    disks: Vec<DiskInfo>,
    top_cpu: Vec<ProcInfo>,
    top_mem: Vec<ProcInfo>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
    file_system: String,
    removable: bool,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<Snapshot>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Status,
    Top {
        by: Option<String>,
        limit: Option<usize>,
    },
    Kill {
        pid: i32,
        signal: Option<i32>,
    },
    Renice {
        pid: i32,
        nice: i32,
    },
}

#[derive(Debug, Serialize)]
struct Response<T> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

impl<T> Response<T> {
    fn ok(data: T) -> Self {
        Self {
            ok: true,
            data: Some(data),
            error: None,
        }
    }

    fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            data: None,
            error: Some(msg.into()),
        }
    }
}

#[derive(Debug, Serialize)]
struct TopResponse {
    by: String,
    items: Vec<ProcInfo>,
}

#[derive(Debug, Serialize)]
struct ActionResponse {
    message: String,
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn process_to_info(p: &sysinfo::Process) -> ProcInfo {
    ProcInfo {
        pid: p.pid().as_u32() as i32,
        name: p.name().to_string(),
        cpu_percent: p.cpu_usage(),
        memory_bytes: p.memory(),
        virtual_memory_bytes: p.virtual_memory(),
        status: format!("{:?}", p.status()),
    }
}

fn sort_desc_f32(a: f32, b: f32) -> Ordering {
    b.partial_cmp(&a).unwrap_or(Ordering::Equal)
}

fn collect_snapshot(sys: &System, top_n: usize) -> Snapshot {
    let load = System::load_average();

    let mut procs: Vec<ProcInfo> = sys.processes().values().map(process_to_info).collect();

    let mut top_cpu = procs.clone();
    top_cpu.sort_by(|a, b| sort_desc_f32(a.cpu_percent, b.cpu_percent));
    top_cpu.truncate(top_n);

    procs.sort_by(|a, b| b.memory_bytes.cmp(&a.memory_bytes));
    let mut top_mem = procs;
    top_mem.truncate(top_n);

    let disks = sys
        .disks()
        .iter()
        .map(|d| DiskInfo {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space_bytes: d.total_space(),
            available_space_bytes: d.available_space(),
            file_system: String::from_utf8_lossy(d.file_system()).to_string(),
            removable: d.is_removable(),
        })
        .collect();

    Snapshot {
        timestamp_unix: now_unix(),
        uptime_seconds: System::uptime(),
        loadavg_one: load.one,
        loadavg_five: load.five,
        loadavg_fifteen: load.fifteen,
        total_memory_bytes: sys.total_memory(),
        used_memory_bytes: sys.used_memory(),
        total_swap_bytes: sys.total_swap(),
        used_swap_bytes: sys.used_swap(),
        cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
        disks,
        top_cpu,
        top_mem,
    }
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>, period: Duration) {
    let mut ticker = interval(period);

    let refresh = RefreshKind::new()
        .with_cpu(CpuRefreshKind::everything())
        .with_memory(MemoryRefreshKind::everything())
        .with_processes(ProcessRefreshKind::everything())
        .with_disks(DiskRefreshKind::everything());

    let mut sys = System::new_with_specifics(refresh);

    // Prime CPU stats
    sys.refresh_cpu();
    tokio::time::sleep(Duration::from_millis(200)).await;

    loop {
        ticker.tick().await;

        sys.refresh_memory();
        sys.refresh_cpu();
        sys.refresh_processes_specifics(
            ProcessesToUpdate::All,
            true,
            ProcessRefreshKind::everything(),
        );
        sys.refresh_disks();

        let snap = collect_snapshot(&sys, 10);
        let mut guard = state.write().await;
        guard.latest = Some(snap);
    }
}

async fn write_json_line<T: Serialize>(stream: &mut UnixStream, value: &T) -> Result<()> {
    let mut buf = serde_json::to_vec(value)?;
    buf.push(b'\n');
    stream.write_all(&buf).await?;
    Ok(())
}

fn map_signal(sig: Option<i32>) -> Result<Signal> {
    let raw = sig.unwrap_or(15);
    Signal::try_from(raw).context("invalid signal")
}

fn renice_process(pid: i32, nice: i32) -> Result<()> {
    use nix::sys::resource::{setpriority, Which};

    if !(-20..=19).contains(&nice) {
        anyhow::bail!("nice value must be between -20 and 19");
    }

    setpriority(Which::PRIO_PROCESS, pid as u32, nice).context("setpriority failed")?;
    Ok(())
}

async fn handle_request(req: Request, state: Arc<RwLock<SharedState>>) -> serde_json::Value {
    match req {
        Request::Status => {
            let guard = state.read().await;
            match &guard.latest {
                Some(s) => serde_json::to_value(Response::ok(s)).unwrap(),
                None => serde_json::to_value(Response::<Snapshot>::err("no snapshot available")).unwrap(),
            }
        }
        Request::Top { by, limit } => {
            let by = by.unwrap_or_else(|| "cpu".to_string());
            let limit = limit.unwrap_or(10).min(100);

            let guard = state.read().await;
            match &guard.latest {
                Some(s) => {
                    let items = match by.as_str() {
                        "cpu" => s.top_cpu.iter().take(limit).cloned().collect(),
                        "mem" | "memory" => s.top_mem.iter().take(limit).cloned().collect(),
                        _ => {
                            return serde_json::to_value(Response::<TopResponse>::err(
                                "invalid 'by', expected 'cpu' or 'memory'",
                            ))
                            .unwrap()
                        }
                    };

                    serde_json::to_value(Response::ok(TopResponse { by, items })).unwrap()
                }
                None => serde_json::to_value(Response::<TopResponse>::err("no snapshot available")).unwrap(),
            }
        }
        Request::Kill { pid, signal } => {
            let result = (|| -> Result<String> {
                let sig = map_signal(signal)?;
                kill(Pid::from_raw(pid), sig).context("kill failed")?;
                Ok(format!("signal {:?} sent to pid {}", sig, pid))
            })();

            match result {
                Ok(msg) => serde_json::to_value(Response::ok(ActionResponse { message: msg })).unwrap(),
                Err(e) => serde_json::to_value(Response::<ActionResponse>::err(e.to_string())).unwrap(),
            }
        }
        Request::Renice { pid, nice } => {
            let result = renice_process(pid, nice)
                .map(|_| format!("set nice={} for pid {}", nice, pid));

            match result {
                Ok(msg) => serde_json::to_value(Response::ok(ActionResponse { message: msg })).unwrap(),
                Err(e) => serde_json::to_value(Response::<ActionResponse>::err(e.to_string())).unwrap(),
            }
        }
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let resp = match serde_json::from_str::<Request>(trimmed) {
            Ok(req) => handle_request(req, state.clone()).await,
            Err(e) => serde_json::to_value(Response::<HashMap<String, String>>::err(format!(
                "invalid request: {}",
                e
            )))
            .unwrap(),
        };

        let mut buf = serde_json::to_vec(&resp)?;
        buf.push(b'\n');
        writer.write_all(&buf).await?;
    }

    Ok(())
}

async fn server_loop(socket_path: &str, state: Arc<RwLock<SharedState>>) -> Result<()> {
    if Path::new(socket_path).exists() {
        std::fs::remove_file(socket_path).context("failed to remove stale socket")?;
    }

    let listener = UnixListener::bind(socket_path).context("failed to bind unix socket")?;
    info!("listening on {}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client error: {}", e);
            }
        });
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "osd=info,warn".to_string()),
        )
        .init();

    let socket_path = std::env::var("OSD_SOCKET")
        .unwrap_or_else(|_| "/tmp/osd.sock".to_string());
    let period_ms: u64 = std::env::var("OSD_PERIOD_MS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(1000);

    let state = Arc::new(RwLock::new(SharedState::default()));

    let monitor = tokio::spawn(monitor_loop(
        state.clone(),
        Duration::from_millis(period_ms),
    ));

    let server = tokio::spawn(server_loop(&socket_path, state.clone()));

    tokio::select! {
        r = monitor => {
            match r {
                Ok(_) => error!("monitor loop exited unexpectedly"),
                Err(e) => error!("monitor task join error: {}", e),
            }
        }
        r = server => {
            match r {
                Ok(Ok(_)) => error!("server loop exited unexpectedly"),
                Ok(Err(e)) => error!("server loop error: {}", e),
                Err(e) => error!("server task join error: {}", e),
            }
        }
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown requested");
        }
    }

    if Path::new(&socket_path).exists() {
        let _ = std::fs::remove_file(&socket_path);
    }

    Ok(())
}
