```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    path::Path,
    sync::Arc,
    time::{Duration, Instant},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    process::Command,
    signal,
    sync::{watch, RwLock},
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_alert_percent: f64,
    mem_alert_percent: f64,
    disk_alert_percent: f64,
    actions: Vec<ActionConfig>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_alert_percent: 90.0,
            mem_alert_percent: 90.0,
            disk_alert_percent: 95.0,
            actions: vec![],
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type")]
enum ActionConfig {
    Log,
    Exec { command: String, args: Vec<String> },
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct Metrics {
    timestamp_ms: u128,
    cpu_percent: f64,
    mem_used_percent: f64,
    disk_used_percent: f64,
    loadavg_1m: f64,
    loadavg_5m: f64,
    loadavg_15m: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Alert {
    kind: String,
    message: String,
    metrics: Metrics,
}

#[derive(Debug, Clone)]
struct CpuSample {
    total: u64,
    idle: u64,
}

#[derive(Debug, Default)]
struct SharedState {
    metrics: Metrics,
    alerts: Vec<Alert>,
    config: Config,
    last_cpu_sample: Option<CpuSample>,
}

type State = Arc<RwLock<SharedState>>;

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetMetrics,
    GetAlerts,
    GetConfig,
    SetConfig { config: Config },
    Ping,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok { data: serde_json::Value },
    Error { message: String },
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let state = Arc::new(RwLock::new(SharedState {
        config: Config::default(),
        ..Default::default()
    }));

    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let monitor_task = tokio::spawn(run_monitor(state.clone(), shutdown_rx.clone()));
    let server_task = tokio::spawn(run_server(state.clone(), shutdown_rx.clone()));

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    let _ = shutdown_tx.send(true);

    let _ = monitor_task.await;
    let _ = server_task.await;

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

async fn run_monitor(state: State, mut shutdown: watch::Receiver<bool>) -> Result<()> {
    loop {
        let interval_ms = {
            let s = state.read().await;
            s.config.sample_interval_ms
        };

        tokio::select! {
            _ = shutdown.changed() => {
                if *shutdown.borrow() {
                    info!("monitor shutting down");
                    break;
                }
            }
            _ = time::sleep(Duration::from_millis(interval_ms)) => {
                if let Err(e) = sample_and_check(state.clone()).await {
                    error!("monitor error: {e:#}");
                }
            }
        }
    }
    Ok(())
}

async fn sample_and_check(state: State) -> Result<()> {
    let now = Instant::now();
    let timestamp_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)?
        .as_millis();

    let cpu = read_cpu_percent(&state).await?;
    let mem = read_mem_percent()?;
    let disk = read_disk_percent("/")?;
    let (l1, l5, l15) = read_loadavg()?;

    let metrics = Metrics {
        timestamp_ms,
        cpu_percent: cpu,
        mem_used_percent: mem,
        disk_used_percent: disk,
        loadavg_1m: l1,
        loadavg_5m: l5,
        loadavg_15m: l15,
    };

    let (config, actions) = {
        let mut s = state.write().await;
        s.metrics = metrics.clone();
        (s.config.clone(), s.config.actions.clone())
    };

    let mut generated_alerts = Vec::new();

    if metrics.cpu_percent >= config.cpu_alert_percent {
        generated_alerts.push(Alert {
            kind: "cpu".into(),
            message: format!(
                "CPU usage {:.2}% exceeded threshold {:.2}%",
                metrics.cpu_percent, config.cpu_alert_percent
            ),
            metrics: metrics.clone(),
        });
    }

    if metrics.mem_used_percent >= config.mem_alert_percent {
        generated_alerts.push(Alert {
            kind: "memory".into(),
            message: format!(
                "Memory usage {:.2}% exceeded threshold {:.2}%",
                metrics.mem_used_percent, config.mem_alert_percent
            ),
            metrics: metrics.clone(),
        });
    }

    if metrics.disk_used_percent >= config.disk_alert_percent {
        generated_alerts.push(Alert {
            kind: "disk".into(),
            message: format!(
                "Disk usage {:.2}% exceeded threshold {:.2}%",
                metrics.disk_used_percent, config.disk_alert_percent
            ),
            metrics: metrics.clone(),
        });
    }

    if !generated_alerts.is_empty() {
        {
            let mut s = state.write().await;
            s.alerts.extend(generated_alerts.clone());
            if s.alerts.len() > 1000 {
                let excess = s.alerts.len() - 1000;
                s.alerts.drain(0..excess);
            }
        }

        for alert in generated_alerts {
            execute_actions(&actions, &alert).await;
        }
    }

    info!(
        "sampled in {:?}: cpu={:.2}% mem={:.2}% disk={:.2}% load={:.2},{:.2},{:.2}",
        now.elapsed(),
        metrics.cpu_percent,
        metrics.mem_used_percent,
        metrics.disk_used_percent,
        metrics.loadavg_1m,
        metrics.loadavg_5m,
        metrics.loadavg_15m
    );

    Ok(())
}

async fn execute_actions(actions: &[ActionConfig], alert: &Alert) {
    for action in actions {
        match action {
            ActionConfig::Log => {
                warn!("ALERT [{}] {}", alert.kind, alert.message);
            }
            ActionConfig::Exec { command, args } => {
                let mut cmd = Command::new(command);
                cmd.args(args);
                cmd.env("SYSMOND_ALERT_KIND", &alert.kind);
                cmd.env("SYSMOND_ALERT_MESSAGE", &alert.message);
                cmd.env(
                    "SYSMOND_ALERT_METRICS",
                    serde_json::to_string(&alert.metrics).unwrap_or_default(),
                );

                match cmd.spawn() {
                    Ok(mut child) => {
                        tokio::spawn(async move {
                            match child.wait().await {
                                Ok(status) => info!("action exited with status: {status}"),
                                Err(e) => error!("action wait failed: {e}"),
                            }
                        });
                    }
                    Err(e) => error!("failed to spawn action: {e}"),
                }
            }
        }
    }
}

async fn run_server(state: State, mut shutdown: watch::Receiver<bool>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    info!("listening on {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = shutdown.changed() => {
                if *shutdown.borrow() {
                    info!("server shutting down");
                    break;
                }
            }
            accept_result = listener.accept() => {
                match accept_result {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, state).await {
                                error!("client error: {e:#}");
                            }
                        });
                    }
                    Err(e) => error!("accept error: {e}"),
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: State) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: Request = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response::Error {
                    message: format!("invalid request: {e}"),
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
                continue;
            }
        };

        let resp = process_request(req, state.clone()).await;
        writer
            .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
            .await?;
    }

    Ok(())
}

async fn process_request(req: Request, state: State) -> Response {
    match req {
        Request::Ping => Response::Ok {
            data: serde_json::json!({"pong": true}),
        },
        Request::GetMetrics => {
            let s = state.read().await;
            Response::Ok {
                data: serde_json::to_value(&s.metrics).unwrap_or_default(),
            }
        }
        Request::GetAlerts => {
            let s = state.read().await;
            Response::Ok {
                data: serde_json::to_value(&s.alerts).unwrap_or_default(),
            }
        }
        Request::GetConfig => {
            let s = state.read().await;
            Response::Ok {
                data: serde_json::to_value(&s.config).unwrap_or_default(),
            }
        }
        Request::SetConfig { config } => {
            let mut s = state.write().await;
            s.config = config;
            Response::Ok {
                data: serde_json::json!({"updated": true}),
            }
        }
    }
}

async fn read_cpu_percent(state: &State) -> Result<f64> {
    let stat = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
    let first = stat
        .lines()
        .next()
        .context("missing cpu line in /proc/stat")?;
    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        anyhow::bail!("unexpected /proc/stat cpu format");
    }

    let nums: Vec<u64> = parts[1..]
        .iter()
        .map(|s| s.parse::<u64>())
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("parsing cpu counters")?;

    let idle = nums.get(3).copied().unwrap_or(0) + nums.get(4).copied().unwrap_or(0);
    let total: u64 = nums.iter().sum();

    let current = CpuSample { total, idle };

    let mut s = state.write().await;
    let percent = if let Some(prev) = &s.last_cpu_sample {
        let total_delta = current.total.saturating_sub(prev.total);
        let idle_delta = current.idle.saturating_sub(prev.idle);
        if total_delta == 0 {
            0.0
        } else {
            100.0 * (total_delta - idle_delta) as f64 / total_delta as f64
        }
    } else {
        0.0
    };
    s.last_cpu_sample = Some(current);
    Ok(percent)
}

fn read_mem_percent() -> Result<f64> {
    let meminfo = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
    let mut map = HashMap::new();

    for line in meminfo.lines() {
        let mut parts = line.split(':');
        if let (Some(k), Some(v)) = (parts.next(), parts.next()) {
            let value = v
                .trim()
                .split_whitespace()
                .next()
                .unwrap_or("0")
                .parse::<u64>()
                .unwrap_or(0);
            map.insert(k.to_string(), value);
        }
    }

    let total = *map.get("MemTotal").context("MemTotal missing")? as f64;
    let available = *map.get("MemAvailable").context("MemAvailable missing")? as f64;
    let used = total - available;

    Ok((used / total) * 100.0)
}

fn read_disk_percent(path: &str) -> Result<f64> {
    use std::process::Command as StdCommand;

    let output = StdCommand::new("df")
        .arg("-P")
        .arg(path)
        .output()
        .context("running df")?;

    if !output.status.success() {
        anyhow::bail!("df failed with status {}", output.status);
    }

    let stdout = String::from_utf8(output.stdout).context("df output not utf8")?;
    let line = stdout.lines().nth(1).context("df output missing data line")?;
    let cols: Vec<&str> = line.split_whitespace().collect();
    if cols.len() < 5 {
        anyhow::bail!("unexpected df output format");
    }

    let pct = cols[4].trim_end_matches('%').parse::<f64>()?;
    Ok(pct)
}

fn read_loadavg() -> Result<(f64, f64, f64)> {
    let s = fs::read_to_string("/proc/loadavg").context("reading /proc/loadavg")?;
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }
    Ok((
        parts[0].parse()?,
        parts[1].parse()?,
        parts[2].parse()?,
    ))
}
