```rust
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    io,
    path::Path,
    sync::Arc,
    time::Duration,
};
use thiserror::Error;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::{broadcast, RwLock},
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Error)]
enum DaemonError {
    #[error("io error: {0}")]
    Io(#[from] io::Error),

    #[error("parse error: {0}")]
    Parse(String),

    #[error("serialization error: {0}")]
    Serde(#[from] serde_json::Error),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Metrics {
    cpu_usage_percent: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_percent: f64,
    load1: f64,
    load5: f64,
    load15: f64,
    disk_free_bytes: u64,
    disk_total_bytes: u64,
    disk_used_percent: f64,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            cpu_usage_percent: 0.0,
            mem_total_kb: 0,
            mem_available_kb: 0,
            mem_used_percent: 0.0,
            load1: 0.0,
            load5: 0.0,
            load15: 0.0,
            disk_free_bytes: 0,
            disk_total_bytes: 0,
            disk_used_percent: 0.0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Thresholds {
    cpu_usage_percent: f64,
    mem_used_percent: f64,
    disk_used_percent: f64,
    load1: f64,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_usage_percent: 90.0,
            mem_used_percent: 90.0,
            disk_used_percent: 95.0,
            load1: 8.0,
        }
    }
}

#[derive(Debug, Default)]
struct CpuSnapshot {
    total: u64,
    idle: u64,
}

#[derive(Debug)]
struct AppState {
    metrics: RwLock<Metrics>,
    thresholds: RwLock<Thresholds>,
}

impl AppState {
    fn new() -> Self {
        Self {
            metrics: RwLock::new(Metrics::default()),
            thresholds: RwLock::new(Thresholds::default()),
        }
    }
}

#[derive(Debug, Serialize)]
struct StatusResponse {
    ok: bool,
    message: String,
}

#[tokio::main]
async fn main() -> Result<(), DaemonError> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH)?;
    }

    let state = Arc::new(AppState::new());
    let (shutdown_tx, _) = broadcast::channel::<()>(8);

    let monitor_state = state.clone();
    let monitor_shutdown = shutdown_tx.subscribe();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_shutdown).await {
            error!("monitor loop failed: {e}");
        }
    });

    let server_state = state.clone();
    let server_shutdown = shutdown_tx.subscribe();
    let server_task = tokio::spawn(async move {
        if let Err(e) = control_server(server_state, server_shutdown).await {
            error!("control server failed: {e}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c, shutting down");
        }
    }

    let _ = shutdown_tx.send(());
    let _ = monitor_task.await;
    let _ = server_task.await;

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    info!("shutdown complete");
    Ok(())
}

async fn monitor_loop(
    state: Arc<AppState>,
    mut shutdown: broadcast::Receiver<()>,
) -> Result<(), DaemonError> {
    let mut interval = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));
    let mut prev_cpu = read_cpu_snapshot()?;

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("monitor loop stopping");
                break;
            }
            _ = interval.tick() => {
                match collect_metrics(&prev_cpu) {
                    Ok((metrics, next_cpu)) => {
                        prev_cpu = next_cpu;

                        {
                            let mut guard = state.metrics.write().await;
                            *guard = metrics.clone();
                        }

                        evaluate_thresholds(&state, &metrics).await;
                    }
                    Err(e) => {
                        warn!("failed to collect metrics: {e}");
                    }
                }
            }
        }
    }

    Ok(())
}

async fn evaluate_thresholds(state: &Arc<AppState>, metrics: &Metrics) {
    let thresholds = state.thresholds.read().await.clone();

    if metrics.cpu_usage_percent >= thresholds.cpu_usage_percent {
        warn!(
            "cpu threshold exceeded: {:.2}% >= {:.2}%",
            metrics.cpu_usage_percent, thresholds.cpu_usage_percent
        );
    }

    if metrics.mem_used_percent >= thresholds.mem_used_percent {
        warn!(
            "memory threshold exceeded: {:.2}% >= {:.2}%",
            metrics.mem_used_percent, thresholds.mem_used_percent
        );
    }

    if metrics.disk_used_percent >= thresholds.disk_used_percent {
        warn!(
            "disk threshold exceeded: {:.2}% >= {:.2}%",
            metrics.disk_used_percent, thresholds.disk_used_percent
        );
    }

    if metrics.load1 >= thresholds.load1 {
        warn!(
            "load threshold exceeded: {:.2} >= {:.2}",
            metrics.load1, thresholds.load1
        );
    }
}

fn collect_metrics(prev_cpu: &CpuSnapshot) -> Result<(Metrics, CpuSnapshot), DaemonError> {
    let next_cpu = read_cpu_snapshot()?;
    let cpu_usage = compute_cpu_usage(prev_cpu, &next_cpu);

    let (mem_total_kb, mem_available_kb) = read_meminfo()?;
    let mem_used_percent = if mem_total_kb > 0 {
        100.0 * (mem_total_kb - mem_available_kb) as f64 / mem_total_kb as f64
    } else {
        0.0
    };

    let (load1, load5, load15) = read_loadavg()?;
    let (disk_total_bytes, disk_free_bytes) = read_disk_stats("/")?;
    let disk_used_percent = if disk_total_bytes > 0 {
        100.0 * (disk_total_bytes - disk_free_bytes) as f64 / disk_total_bytes as f64
    } else {
        0.0
    };

    Ok((
        Metrics {
            cpu_usage_percent: cpu_usage,
            mem_total_kb,
            mem_available_kb,
            mem_used_percent,
            load1,
            load5,
            load15,
            disk_free_bytes,
            disk_total_bytes,
            disk_used_percent,
        },
        next_cpu,
    ))
}

fn read_cpu_snapshot() -> Result<CpuSnapshot, DaemonError> {
    let stat = fs::read_to_string("/proc/stat")?;
    let line = stat
        .lines()
        .next()
        .ok_or_else(|| DaemonError::Parse("missing /proc/stat cpu line".into()))?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(DaemonError::Parse("invalid /proc/stat format".into()));
    }

    let values: Vec<u64> = parts[1..]
        .iter()
        .map(|s| s.parse::<u64>().map_err(|e| DaemonError::Parse(e.to_string())))
        .collect::<Result<_, _>>()?;

    let idle = values.get(3).copied().unwrap_or(0) + values.get(4).copied().unwrap_or(0);
    let total = values.iter().sum();

    Ok(CpuSnapshot { total, idle })
}

fn compute_cpu_usage(prev: &CpuSnapshot, next: &CpuSnapshot) -> f64 {
    let total_delta = next.total.saturating_sub(prev.total);
    let idle_delta = next.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        0.0
    } else {
        100.0 * (total_delta - idle_delta) as f64 / total_delta as f64
    }
}

fn read_meminfo() -> Result<(u64, u64), DaemonError> {
    let meminfo = fs::read_to_string("/proc/meminfo")?;
    let mut map = HashMap::new();

    for line in meminfo.lines() {
        let mut parts = line.split_whitespace();
        if let (Some(key), Some(value)) = (parts.next(), parts.next()) {
            map.insert(key.trim_end_matches(':'), value.parse::<u64>().unwrap_or(0));
        }
    }

    let total = *map
        .get("MemTotal")
        .ok_or_else(|| DaemonError::Parse("MemTotal not found".into()))?;
    let available = *map
        .get("MemAvailable")
        .ok_or_else(|| DaemonError::Parse("MemAvailable not found".into()))?;

    Ok((total, available))
}

fn read_loadavg() -> Result<(f64, f64, f64), DaemonError> {
    let loadavg = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = loadavg.split_whitespace().collect();
    if parts.len() < 3 {
        return Err(DaemonError::Parse("invalid /proc/loadavg format".into()));
    }

    Ok((
        parts[0].parse().map_err(|e: std::num::ParseFloatError| DaemonError::Parse(e.to_string()))?,
        parts[1].parse().map_err(|e: std::num::ParseFloatError| DaemonError::Parse(e.to_string()))?,
        parts[2].parse().map_err(|e: std::num::ParseFloatError| DaemonError::Parse(e.to_string()))?,
    ))
}

fn read_disk_stats(path: &str) -> Result<(u64, u64), DaemonError> {
    let c_path = std::ffi::CString::new(path).map_err(|e| DaemonError::Parse(e.to_string()))?;
    let mut stat: libc::statvfs = unsafe { std::mem::zeroed() };

    let rc = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
    if rc != 0 {
        return Err(DaemonError::Io(io::Error::last_os_error()));
    }

    let total = stat.f_blocks as u64 * stat.f_frsize as u64;
    let free = stat.f_bavail as u64 * stat.f_frsize as u64;

    Ok((total, free))
}

async fn control_server(
    state: Arc<AppState>,
    mut shutdown: broadcast::Receiver<()>,
) -> Result<(), DaemonError> {
    let listener = UnixListener::bind(SOCKET_PATH)?;
    info!("control socket listening at {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("control server stopping");
                break;
            }
            res = listener.accept() => {
                match res {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, state).await {
                                warn!("client error: {e}");
                            }
                        });
                    }
                    Err(e) => {
                        warn!("accept failed: {e}");
                    }
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<AppState>) -> Result<(), DaemonError> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"sysmond ready\n")
        .await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let response = process_command(line.trim(), &state).await?;
        writer.write_all(response.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn process_command(cmd: &str, state: &Arc<AppState>) -> Result<String, DaemonError> {
    let parts: Vec<&str> = cmd.split_whitespace().collect();
    if parts.is_empty() {
        return Ok(serde_json::to_string(&StatusResponse {
            ok: false,
            message: "empty command".into(),
        })?);
    }

    match parts[0] {
        "status" => Ok(serde_json::to_string(&StatusResponse {
            ok: true,
            message: "running".into(),
        })?),

        "metrics" => {
            let metrics = state.metrics.read().await.clone();
            Ok(serde_json::to_string(&metrics)?)
        }

        "get-thresholds" => {
            let thresholds = state.thresholds.read().await.clone();
            Ok(serde_json::to_string(&thresholds)?)
        }

        "set-threshold" => {
            if parts.len() != 3 {
                return Ok(serde_json::to_string(&StatusResponse {
                    ok: false,
                    message: "usage: set-threshold <resource> <value>".into(),
                })?);
            }

            let resource = parts[1];
            let value: f64 = match parts[2].parse() {
                Ok(v) => v,
                Err(_) => {
                    return Ok(serde_json::to_string(&StatusResponse {
                        ok: false,
                        message: "invalid numeric value".into(),
                    })?)
                }
            };

            let mut thresholds = state.thresholds.write().await;
            match resource {
                "cpu" => thresholds.cpu_usage_percent = value,
                "mem" => thresholds.mem_used_percent = value,
                "disk" => thresholds.disk_used_percent = value,
                "load1" => thresholds.load1 = value,
                _ => {
                    return Ok(serde_json::to_string(&StatusResponse {
                        ok: false,
                        message: "unknown resource; use cpu|mem|disk|load1".into(),
                    })?)
                }
            }

            Ok(serde_json::to_string(&StatusResponse {
                ok: true,
                message: format!("threshold updated: {}={}", resource, value),
            })?)
        }

        "shutdown" => Ok(serde_json::to_string(&StatusResponse {
            ok: true,
            message: "shutdown requested from client; send SIGINT/CTRL-C to stop in this sample".into(),
        })?),

        _ => Ok(serde_json::to_string(&StatusResponse {
            ok: false,
            message: "unknown command".into(),
        })?),
    }
}
