use anyhow::{Context, Result};
use serde::Deserialize;
use std::{fs, path::Path, time::Duration};
use sysinfo::{Disks, LoadAvg, Pid, Signal, System};
use tokio::signal;
use tokio::time;
use tracing::{debug, error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    interval_secs: u64,
    thresholds: Thresholds,
    actions: Actions,
}

#[derive(Debug, Deserialize, Clone)]
struct Thresholds {
    cpu_percent_warn: f32,
    memory_percent_warn: f32,
    memory_percent_kill: Option<f32>,
    disk_percent_warn: f32,
    loadavg_one_warn: f64,
}

#[derive(Debug, Deserialize, Clone)]
struct Actions {
    kill_pid_on_memory_critical: Option<u32>,
    log_top_processes: bool,
    top_process_count: usize,
}

#[derive(Debug)]
struct Metrics {
    cpu_percent: f32,
    memory_percent: f32,
    used_memory_bytes: u64,
    total_memory_bytes: u64,
    max_disk_percent: f32,
    loadavg_one: f64,
}

fn load_config<P: AsRef<Path>>(path: P) -> Result<Config> {
    let raw = fs::read_to_string(&path)
        .with_context(|| format!("failed to read config {}", path.as_ref().display()))?;
    let cfg = serde_json::from_str::<Config>(&raw)
        .with_context(|| format!("failed to parse config {}", path.as_ref().display()))?;
    Ok(cfg)
}

fn collect_metrics(sys: &mut System, disks: &Disks) -> Metrics {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_processes();
    let load = System::load_average();

    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();

    let memory_percent = if total_memory == 0 {
        0.0
    } else {
        (used_memory as f32 / total_memory as f32) * 100.0
    };

    let cpu_percent = sys.global_cpu_usage();

    let mut max_disk_percent = 0.0f32;
    for disk in disks.list() {
        let total = disk.total_space();
        let avail = disk.available_space();
        let used = total.saturating_sub(avail);
        let pct = if total == 0 {
            0.0
        } else {
            (used as f32 / total as f32) * 100.0
        };
        if pct > max_disk_percent {
            max_disk_percent = pct;
        }
    }

    Metrics {
        cpu_percent,
        memory_percent,
        used_memory_bytes: used_memory * 1024,
        total_memory_bytes: total_memory * 1024,
        max_disk_percent,
        loadavg_one: load.one,
    }
}

fn maybe_log_top_processes(sys: &System, count: usize) {
    let mut procs: Vec<_> = sys.processes().values().collect();
    procs.sort_by(|a, b| {
        b.memory()
            .cmp(&a.memory())
            .then_with(|| b.cpu_usage().partial_cmp(&a.cpu_usage()).unwrap_or(std::cmp::Ordering::Equal))
    });

    for proc_ in procs.into_iter().take(count) {
        info!(
            pid = proc_.pid().as_u32(),
            name = proc_.name().to_string_lossy().to_string(),
            mem_kib = proc_.memory(),
            cpu_percent = proc_.cpu_usage(),
            "top process"
        );
    }
}

fn enforce_policies(sys: &System, cfg: &Config, metrics: &Metrics) {
    if metrics.cpu_percent >= cfg.thresholds.cpu_percent_warn {
        warn!(
            cpu_percent = metrics.cpu_percent,
            threshold = cfg.thresholds.cpu_percent_warn,
            "cpu usage exceeded warning threshold"
        );
    }

    if metrics.memory_percent >= cfg.thresholds.memory_percent_warn {
        warn!(
            memory_percent = metrics.memory_percent,
            threshold = cfg.thresholds.memory_percent_warn,
            used_bytes = metrics.used_memory_bytes,
            total_bytes = metrics.total_memory_bytes,
            "memory usage exceeded warning threshold"
        );

        if cfg.actions.log_top_processes {
            maybe_log_top_processes(sys, cfg.actions.top_process_count);
        }
    }

    if metrics.max_disk_percent >= cfg.thresholds.disk_percent_warn {
        warn!(
            disk_percent = metrics.max_disk_percent,
            threshold = cfg.thresholds.disk_percent_warn,
            "disk usage exceeded warning threshold"
        );
    }

    if metrics.loadavg_one >= cfg.thresholds.loadavg_one_warn {
        warn!(
            loadavg_one = metrics.loadavg_one,
            threshold = cfg.thresholds.loadavg_one_warn,
            "load average exceeded warning threshold"
        );
    }

    if let Some(kill_threshold) = cfg.thresholds.memory_percent_kill {
        if metrics.memory_percent >= kill_threshold {
            if let Some(pid_u32) = cfg.actions.kill_pid_on_memory_critical {
                let pid = Pid::from_u32(pid_u32);
                if let Some(process) = sys.process(pid) {
                    warn!(
                        pid = pid_u32,
                        process = process.name().to_string_lossy().to_string(),
                        memory_percent = metrics.memory_percent,
                        threshold = kill_threshold,
                        "critical memory threshold reached; attempting to terminate configured process"
                    );

                    let ok = process.kill_with(Signal::Term).unwrap_or(false);
                    if ok {
                        warn!(pid = pid_u32, "sent SIGTERM to configured process");
                    } else {
                        error!(pid = pid_u32, "failed to send SIGTERM to configured process");
                    }
                } else {
                    error!(pid = pid_u32, "configured process pid not found");
                }
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "resource_daemon=info".to_string()),
        )
        .init();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "config.json".to_string());

    let cfg = load_config(&config_path)?;
    info!(config = %config_path, ?cfg, "loaded configuration");

    let mut sys = System::new_all();
    let disks = Disks::new_with_refreshed_list();

    sys.refresh_all();

    let mut ticker = time::interval(Duration::from_secs(cfg.interval_secs));
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    info!("resource daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let metrics = collect_metrics(&mut sys, &disks);

                debug!(
                    cpu_percent = metrics.cpu_percent,
                    memory_percent = metrics.memory_percent,
                    used_memory_bytes = metrics.used_memory_bytes,
                    total_memory_bytes = metrics.total_memory_bytes,
                    max_disk_percent = metrics.max_disk_percent,
                    loadavg_one = metrics.loadavg_one,
                    "collected metrics"
                );

                enforce_policies(&sys, &cfg, &metrics);
            }
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}
```

