fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,resourced=debug".to_string()),
        )
        .init();
}

async fn collector_loop(
    config: Arc<RwLock<Config>>,
    state: Arc<RwLock<SharedState>>,
    shutdown_rx: &mut broadcast::Receiver<()>,
) -> Result<()> {
    let mut system = System::new_all();

    loop {
        let interval = {
            let cfg = config.read();
            Duration::from_millis(cfg.sample_interval_ms)
        };

        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("collector loop stopping");
                break;
            }
            _ = time::sleep(interval) => {
                system.refresh_all();

                let metrics = gather_metrics(&system);
                evaluate_policy(&config, &state, &metrics)?;
                {
                    let mut st = state.write();
                    st.latest_metrics = Some(metrics);
                }
            }
        }
    }

    Ok(())
}

fn gather_metrics(system: &System) -> Metrics {
    let cpu_percent = system.global_cpu_info().cpu_usage();
    let memory_total = system.total_memory() * 1024;
    let memory_used = system.used_memory() * 1024;
    let swap_total = system.total_swap() * 1024;
    let swap_used = system.used_swap() * 1024;
    let memory_percent = if memory_total > 0 {
        (memory_used as f32 / memory_total as f32) * 100.0
    } else {
        0.0
    };

    let load = System::load_average();

    let disks = sysinfo::Disks::new_with_refreshed_list()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total > 0 {
                (used as f32 / total as f32) * 100.0
            } else {
                0.0
            };

            DiskMetrics {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            }
        })
        .collect();

    Metrics {
        timestamp_unix_ms: now_ms(),
        cpu_percent,
        memory_used_bytes: memory_used,
        memory_total_bytes: memory_total,
        memory_percent,
        swap_used_bytes: swap_used,
        swap_total_bytes: swap_total,
        load1: load.one,
        load5: load.five,
        load15: load.fifteen,
        disks,
    }
}

fn evaluate_policy(
    config: &Arc<RwLock<Config>>,
    state: &Arc<RwLock<SharedState>>,
    metrics: &Metrics,
) -> Result<()> {
    let cfg = config.read().clone();

    if metrics.cpu_percent >= cfg.thresholds.cpu_percent_alert {
        record_alert(
            state,
            "cpu_high",
            format!("CPU usage high: {:.2}%", metrics.cpu_percent),
        );
    }

    if metrics.memory_percent >= cfg.thresholds.memory_percent_alert {
        record_alert(
            state,
            "memory_high",
            format!("Memory usage high: {:.2}%", metrics.memory_percent),
        );

        if cfg.actions.enable_signal_process {
            signal_configured_process(&cfg)?;
        }
    }

    if metrics.load1 >= cfg.thresholds.load1_alert {
        record_alert(
            state,
            "load_high",
            format!("Load average high: {:.2}", metrics.load1),
        );
    }

    for disk in &metrics.disks {
        if disk.used_percent >= cfg.thresholds.disk_percent_alert {
            record_alert(
                state,
                "disk_high",
                format!(
                    "Disk usage high on {} ({}): {:.2}%",
                    disk.name, disk.mount_point, disk.used_percent
                ),
            );
        }
    }

    Ok(())
}

fn record_alert(state: &Arc<RwLock<SharedState>>, kind: &str, message: String) {
    warn!("{kind}: {message}");
    let mut st = state.write();
    st.recent_alerts.push(Alert {
        kind: kind.to_string(),
        message,
        timestamp_unix_ms: now_ms(),
    });

    if st.recent_alerts.len() > 1000 {
        let excess = st.recent_alerts.len() - 1000;
        st.recent_alerts.drain(0..excess);
    }

    *st.counters.entry(kind.to_string()).or_insert(0) += 1;
}

fn signal_configured_process(cfg: &Config) -> Result<()> {
    use nix::sys::signal::{kill, Signal};
    use nix::unistd::Pid;

    let pid = match cfg.actions.signal_pid {
        Some(p) => p,
        None => return Ok(()),
    };

    let sig = match cfg.actions.signal_name.as_deref() {
        Some("SIGTERM") => Signal::SIGTERM,
        Some("SIGUSR1") => Signal::SIGUSR1,
        Some("SIGUSR2") => Signal::SIGUSR2,
        Some("SIGHUP") => Signal::SIGHUP,
        _ => Signal::SIGUSR1,
    };

    kill(Pid::from_raw(pid), sig).context("failed to signal configured process")?;
    info!("sent {:?} to pid {}", sig, pid);
    Ok(())
}

async fn control_server_loop(
    config: Arc<RwLock<Config>>,
    state: Arc<RwLock<SharedState>>,
    shutdown_rx: &mut broadcast::Receiver<()>,
) -> Result<()> {
    let socket_path = config.read().control_socket.clone();

    if Path::new(&socket_path).exists() {
        fs::remove_file(&socket_path).context("failed to remove stale socket")?;
    }

    let listener = UnixListener::bind(&socket_path).context("failed to bind unix socket")?;
    info!("control socket listening at {}", socket_path);

    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("control server stopping");
                break;
            }
            accept_res = listener.accept() => {
                let (stream, _) = accept_res?;
                let config = Arc::clone(&config);
                let state = Arc::clone(&state);
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, config, state).await {
                        error!("client handler failed: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    config: Arc<RwLock<Config>>,
    state: Arc<RwLock<SharedState>>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: ControlRequest = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(e) => {
                let resp = ControlResponse {
                    ok: false,
                    message: format!("invalid request: {}", e),
                    data: None,
                };
                writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
                writer.write_all(b"\n").await?;
                continue;
            }
        };

        let resp = handle_request(req, &config, &state).await;
        writer.write_all(serde_json::to_string(&resp)?.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn handle_request(
    req: ControlRequest,
    config: &Arc<RwLock<Config>>,
    state: &Arc<RwLock<SharedState>>,
) -> ControlResponse {
    match req {
        ControlRequest::Ping => ControlResponse {
            ok: true,
            message: "pong".to_string(),
            data: None,
        },
        ControlRequest::GetMetrics => {
            let data = state.read().latest_metrics.clone();
            ControlResponse {
                ok: true,
                message: "ok".to_string(),
                data: serde_json::to_value(data).ok(),
            }
        }
        ControlRequest::GetAlerts => {
            let data = state.read().recent_alerts.clone();
            ControlResponse {
                ok: true,
                message: "ok".to_string(),
                data: serde_json::to_value(data).ok(),
            }
        }
        ControlRequest::GetConfig => {
            let data = config.read().clone();
            ControlResponse {
                ok: true,
                message: "ok".to_string(),
                data: serde_json::to_value(data).ok(),
            }
        }
        ControlRequest::SetConfig { config: new_cfg } => {
            *config.write() = new_cfg;
            ControlResponse {
                ok: true,
                message: "config updated".to_string(),
                data: None,
            }
        }
        ControlRequest::TriggerAction { action } => {
            let cfg = config.read().clone();
            match action.as_str() {
                "signal_process" => match signal_configured_process(&cfg) {
                    Ok(_) => ControlResponse {
                        ok: true,
                        message: "signal sent".to_string(),
                        data: None,
                    },
                    Err(e) => ControlResponse {
                        ok: false,
                        message: e.to_string(),
                        data: None,
                    },
                },
                "drop_caches" => {
                    if !cfg.actions.enable_drop_caches {
                        return ControlResponse {
                            ok: false,
                            message: "drop_caches not enabled".to_string(),
                            data: None,
                        };
                    }

                    match drop_caches() {
                        Ok(_) => ControlResponse {
                            ok: true,
                            message: "drop_caches executed".to_string(),
                            data: None,
                        },
                        Err(e) => ControlResponse {
                            ok: false,
                            message: e.to_string(),
                            data: None,
                        },
                    }
                }
                _ => ControlResponse {
                    ok: false,
                    message: "unknown action".to_string(),
                    data: None,
                },
            }
        }
    }
}

fn drop_caches() -> Result<()> {
    fs::write("/proc/sys/vm/drop_caches", "3\n")
        .context("failed to write to /proc/sys/vm/drop_caches")?;
    info!("requested kernel drop_caches");
    Ok(())
}

fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}
