# `src/main.rs`

```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{Disks, LoadAvg, Pid, ProcessesToUpdate, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    process::Command,
    signal,
    sync::{Mutex, RwLock},
    task,
    time,
};
use tracing::{debug, error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysdaemon.sock";
const POLL_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_one: f64,
    load_five: f64,
    load_fifteen: f64,
    disks: Vec<DiskSnapshot>,
    watched_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    alive: bool,
    cpu_usage_percent: f32,
    memory: u64,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<ResourceSnapshot>,
    watched: HashMap<String, WatchedProcess>,
    shutting_down: bool,
}

#[derive(Debug, Clone)]
struct WatchedProcess {
    name: String,
    pid: Option<i32>,
    restart_cmd: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    Status,
    Health,
    RestartProcess { name: String },
    Stop,
}

#[derive(Debug, Serialize)]
struct ControlResponse<T: Serialize> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

#[derive(Debug, Serialize)]
struct HealthResponse {
    healthy: bool,
    issues: Vec<String>,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    init_logging();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    info!("sysdaemon listening on {}", SOCKET_PATH);

    let state = Arc::new(RwLock::new(initial_state()));

    let monitor_state = Arc::clone(&state);
    let monitor_task = task::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let control_state = Arc::clone(&state);
    let control_task = task::spawn(async move {
        if let Err(e) = control_loop(listener, control_state).await {
            error!("control loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received shutdown signal");
        }
        _ = wait_for_stop(Arc::clone(&state)) => {
            info!("received stop command");
        }
    }

    {
        let mut guard = state.write().await;
        guard.shutting_down = true;
    }

    monitor_task.abort();
    control_task.abort();

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    info!("sysdaemon stopped");
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "sysdaemon=info".to_string()),
        )
        .init();
}

fn initial_state() -> SharedState {
    let mut watched = HashMap::new();

    watched.insert(
        "example_service".to_string(),
        WatchedProcess {
            name: "example_service".to_string(),
            pid: None,
            restart_cmd: vec![
                "/usr/bin/env".to_string(),
                "sh".to_string(),
                "-c".to_string(),
                "sleep 99999".to_string(),
            ],
        },
    );

    SharedState {
        latest: None,
        watched,
        shutting_down: false,
    }
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>) -> Result<()> {
    let mut ticker = time::interval(Duration::from_secs(POLL_INTERVAL_SECS));
    let mut sys = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    loop {
        ticker.tick().await;

        {
            let guard = state.read().await;
            if guard.shutting_down {
                break;
            }
        }

        sys.refresh_memory();
        sys.refresh_cpu();
        sys.refresh_processes(ProcessesToUpdate::All, true);
        disks.refresh();

        let load = System::load_average();
        let snapshot = build_snapshot(&sys, &disks, load, &state).await;

        {
            let mut guard = state.write().await;
            guard.latest = Some(snapshot);
        }
    }

    Ok(())
}

async fn build_snapshot(
    sys: &System,
    disks: &Disks,
    load: LoadAvg,
    state: &Arc<RwLock<SharedState>>,
) -> ResourceSnapshot {
    let watched = {
        let guard = state.read().await;
        guard.watched.values().cloned().collect::<Vec<_>>()
    };

    let watched_processes = watched
        .into_iter()
        .map(|wp| {
            let mut found = None;

            for (pid, proc_) in sys.processes() {
                if proc_.name() == wp.name {
                    found = Some((*pid, proc_));
                    break;
                }
            }

            match found {
                Some((pid, proc_)) => ProcessSnapshot {
                    pid: pid.as_u32() as i32,
                    name: wp.name,
                    alive: true,
                    cpu_usage_percent: proc_.cpu_usage(),
                    memory: proc_.memory(),
                },
                None => ProcessSnapshot {
                    pid: wp.pid.unwrap_or(-1),
                    name: wp.name,
                    alive: false,
                    cpu_usage_percent: 0.0,
                    memory: 0,
                },
            }
        })
        .collect::<Vec<_>>();

    let disk_snaps = disks
        .iter()
        .map(|d| DiskSnapshot {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
        })
        .collect::<Vec<_>>();

    ResourceSnapshot {
        timestamp: now_unix(),
        cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
        total_memory: sys.total_memory(),
        used_memory: sys.used_memory(),
        total_swap: sys.total_swap(),
        used_swap: sys.used_swap(),
        load_one: load.one,
        load_five: load.five,
        load_fifteen: load.fifteen,
        disks: disk_snaps,
        watched_processes,
    }
}

async fn control_loop(listener: UnixListener, state: Arc<RwLock<SharedState>>) -> Result<()> {
    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        task::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: ControlCommand = match serde_json::from_str(&line) {
            Ok(c) => c,
            Err(e) => {
                let resp = ControlResponse::<serde_json::Value> {
                    ok: false,
                    data: None,
                    error: Some(format!("invalid command: {e}")),
                };
                writer.write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes()).await?;
                continue;
            }
        };

        let response = dispatch_command(cmd, &state).await;
        writer
            .write_all(format!("{}\n", serde_json::to_string(&response)?).as_bytes())
            .await?;
    }

    Ok(())
}

async fn dispatch_command(
    cmd: ControlCommand,
    state: &Arc<RwLock<SharedState>>,
) -> ControlResponse<serde_json::Value> {
    match cmd {
        ControlCommand::Status => {
            let guard = state.read().await;
            match &guard.latest {
                Some(snapshot) => ControlResponse {
                    ok: true,
                    data: Some(serde_json::to_value(snapshot).unwrap_or_default()),
                    error: None,
                },
                None => ControlResponse {
                    ok: false,
                    data: None,
                    error: Some("no snapshot available yet".to_string()),
                },
            }
        }
        ControlCommand::Health => {
            let guard = state.read().await;
            let mut issues = Vec::new();

            if let Some(snapshot) = &guard.latest {
                if snapshot.cpu_usage_percent > 95.0 {
                    issues.push("cpu usage above 95%".to_string());
                }
                if snapshot.total_memory > 0
                    && (snapshot.used_memory as f64 / snapshot.total_memory as f64) > 0.95
                {
                    issues.push("memory usage above 95%".to_string());
                }
                for p in &snapshot.watched_processes {
                    if !p.alive {
                        issues.push(format!("watched process not running: {}", p.name));
                    }
                }
            } else {
                issues.push("no snapshot available".to_string());
            }

            let health = HealthResponse {
                healthy: issues.is_empty(),
                issues,
            };

            ControlResponse {
                ok: true,
                data: Some(serde_json::to_value(health).unwrap_or_default()),
                error: None,
            }
        }
        ControlCommand::RestartProcess { name } => {
            match restart_process(&name, state).await {
                Ok(msg) => ControlResponse {
                    ok: true,
                    data: Some(serde_json::json!({ "message": msg })),
                    error: None,
                },
                Err(e) => ControlResponse::<serde_json::Value> {
                    ok: false,
                    data: None,
                    error: Some(e.to_string()),
                },
            }
        }
        ControlCommand::Stop => {
            let mut guard = state.write().await;
            guard.shutting_down = true;

            ControlResponse {
                ok: true,
                data: Some(serde_json::json!({ "message": "daemon stopping" })),
                error: None,
            }
        }
    }
}

async fn restart_process(name: &str, state: &Arc<RwLock<SharedState>>) -> Result<String> {
    let watched = {
        let guard = state.read().await;
        guard
            .watched
            .get(name)
            .cloned()
            .with_context(|| format!("unknown watched process: {name}"))?
    };

    for (pid, proc_) in System::new_all().processes() {
        if proc_.name() == watched.name {
            let pid_i32 = pid.as_u32() as i32;
            info!("killing process {} pid={}", watched.name, pid_i32);
            let _ = nix::sys::signal::kill(
                nix::unistd::Pid::from_raw(pid_i32),
                nix::sys::signal::Signal::SIGTERM,
            );
        }
    }

    if watched.restart_cmd.is_empty() {
        anyhow::bail!("restart command is empty");
    }

    let mut cmd = Command::new(&watched.restart_cmd[0]);
    if watched.restart_cmd.len() > 1 {
        cmd.args(&watched.restart_cmd[1..]);
    }

    let child = cmd.spawn().context("spawning restarted process")?;
    let pid = child.id().unwrap_or(0) as i32;

    {
        let mut guard = state.write().await;
        if let Some(w) = guard.watched.get_mut(name) {
            w.pid = Some(pid);
        }
    }

    Ok(format!("restarted {name} with pid {pid}"))
}

async fn wait_for_stop(state: Arc<RwLock<SharedState>>) {
    loop {
        {
            let guard = state.read().await;
            if guard.shutting_down {
                break;
            }
        }
        time::sleep(Duration::from_millis(200)).await;
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
