## Minimal Rust daemon skeleton
Here is a safe starting point for a Linux resource-monitoring daemon:

```rust
use std::{
    fs,
    io,
    time::Duration,
};

use tokio::{signal, time};
use serde::Deserialize;

#[derive(Debug, Deserialize, Clone)]
struct Config {
    sample_interval_ms: u64,
    cpu_alert_percent: f32,
    mem_alert_percent: f32,
}

#[derive(Debug, Clone, Copy)]
struct CpuSample {
    total: u64,
    idle: u64,
}

#[derive(Debug)]
struct MemInfo {
    total_kb: u64,
    available_kb: u64,
}

fn read_to_string(path: &str) -> io::Result<String> {
    fs::read_to_string(path)
}

fn read_cpu_sample() -> io::Result<CpuSample> {
    let contents = read_to_string("/proc/stat")?;
    let first = contents
        .lines()
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing /proc/stat cpu line"))?;

    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "invalid cpu line"));
    }

    let user: u64 = parts[1].parse().unwrap_or(0);
    let nice: u64 = parts[2].parse().unwrap_or(0);
    let system: u64 = parts[3].parse().unwrap_or(0);
    let idle: u64 = parts[4].parse().unwrap_or(0);
    let iowait: u64 = parts.get(5).and_then(|v| v.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|v| v.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|v| v.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;

    Ok(CpuSample {
        total,
        idle: idle_all,
    })
}

fn cpu_usage_percent(prev: CpuSample, curr: CpuSample) -> f32 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    100.0 * (total_delta.saturating_sub(idle_delta)) as f32 / total_delta as f32
}

fn read_mem_info() -> io::Result<MemInfo> {
    let contents = read_to_string("/proc/meminfo")?;
    let mut total_kb = 0;
    let mut available_kb = 0;

    for line in contents.lines() {
        if let Some(rest) = line.strip_prefix("MemTotal:") {
            total_kb = rest.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
            available_kb = rest.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        }
    }

    Ok(MemInfo {
        total_kb,
        available_kb,
    })
}

fn mem_usage_percent(mem: &MemInfo) -> f32 {
    if mem.total_kb == 0 {
        return 0.0;
    }
    100.0 * (mem.total_kb.saturating_sub(mem.available_kb)) as f32 / mem.total_kb as f32
}

async fn run_daemon(cfg: Config) -> io::Result<()> {
    let mut ticker = time::interval(Duration::from_millis(cfg.sample_interval_ms));
    let mut prev_cpu = read_cpu_sample()?;

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let curr_cpu = match read_cpu_sample() {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("cpu read error: {e}");
                        continue;
                    }
                };

                let cpu = cpu_usage_percent(prev_cpu, curr_cpu);
                prev_cpu = curr_cpu;

                let mem = match read_mem_info() {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("mem read error: {e}");
                        continue;
                    }
                };

                let mem_pct = mem_usage_percent(&mem);

                println!(
                    "cpu={:.2}% mem={:.2}% mem_total_kb={} mem_avail_kb={}",
                    cpu, mem_pct, mem.total_kb, mem.available_kb
                );

                if cpu >= cfg.cpu_alert_percent {
                    eprintln!("ALERT: CPU usage high: {:.2}%", cpu);
                }

                if mem_pct >= cfg.mem_alert_percent {
                    eprintln!("ALERT: Memory usage high: {:.2}%", mem_pct);
                }
            }
            _ = signal::ctrl_c() => {
                eprintln!("shutdown signal received");
                break;
            }
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> io::Result<()> {
    let cfg = Config {
        sample_interval_ms: 1000,
        cpu_alert_percent: 90.0,
        mem_alert_percent: 90.0,
    };

    run_daemon(cfg).await
}
```

