use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::{broadcast, RwLock},
    time,
};
use tracing::{debug, error, info, warn};

use sysinfo::{
    CpuRefreshKind, DiskRefreshKind, Pid, ProcessRefreshKind, ProcessesToUpdate, RefreshKind,
    System,
};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    socket_path: String,
    cpu_alert_percent: f32,
    memory_alert_percent: f32,
    disk_alert_percent: f32,
    top_process_limit: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            socket_path: "/tmp/sysguardian.sock".to_string(),
            cpu_alert_percent: 90.0,
            memory_alert_percent: 90.0,
            disk_alert_percent: 95.0,
            top_process_limit: 10,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    memory_usage_percent: f32,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
    alerts: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonState {
    latest: Option<ResourceSnapshot>,
    config: Config,
    action_log: Vec<ActionRecord>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ActionRecord {
    timestamp_unix_ms: u128,
    action: String,
    result: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    GetStatus,
    GetConfig,
    SetConfig {
        sample_interval_ms: Option<u64>,
        cpu_alert_percent: Option<f32>,
        memory_alert_percent: Option<f32>,
        disk_alert_percent: Option<f32>,
        top_process_limit: Option<usize>,
    },
    ListActions,
    Ping,
    // Safe placeholder for future controlled management operations:
    // KillProcess { pid: u32, signal: i32 },
}

#[derive(Debug, Serialize, Deserialize)]
struct Response<T> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

impl<T> Response<T> {
    fn ok(data: T) -> Self {
        Self {
            ok: true,
            data: Some(data),
            error: None,
        }
    }

    fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            data: None,
            error: Some(msg.into()),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = Config::default();

    if Path::new(&config.socket_path).exists() {
        std::fs::remove_file(&config.socket_path)
            .with_context(|| format!("failed to remove stale socket {}", config.socket_path))?;
    }

    let state = Arc::new(RwLock::new(DaemonState {
        latest: None,
        config: config.clone(),
        action_log: Vec::new(),
    }));

    let (shutdown_tx, _) = broadcast::channel::<()>(8);

    let monitor_state = Arc::clone(&state);
    let mut monitor_shutdown = shutdown_tx.subscribe();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, &mut monitor_shutdown).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_state = Arc::clone(&state);
    let mut server_shutdown = shutdown_tx.subscribe();
    let socket_path = config.socket_path.clone();
    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(&socket_path, server_state, &mut server_shutdown).await {
            error!("server loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    let _ = shutdown_tx.send(());

    let _ = monitor_task.await;
    let _ = server_task.await;

    if Path::new(&config.socket_path).exists() {
        let _ = std::fs::remove_file(&config.socket_path);
    }

    info!("daemon exited cleanly");
    Ok(())
}

async fn monitor_loop(
    state: Arc<RwLock<DaemonState>>,
    shutdown: &mut broadcast::Receiver<()>,
) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    // First refresh to initialize CPU usage deltas correctly.
    system.refresh_all();
    time::sleep(Duration::from_millis(250)).await;

    loop {
        let interval_ms = {
            let s = state.read().await;
            s.config.sample_interval_ms
        };

        tokio::select! {
            _ = shutdown.recv() => {
                info!("monitor loop shutting down");
                break;
            }
            _ = time::sleep(Duration::from_millis(interval_ms)) => {
                let snapshot = collect_snapshot(&mut system, &state).await?;
                evaluate_policies(&state, &snapshot).await;
                let mut s = state.write().await;
                s.latest = Some(snapshot);
            }
        }
    }

    Ok(())
}

async fn collect_snapshot(
    system: &mut System,
    state: &Arc<RwLock<DaemonState>>,
) -> Result<ResourceSnapshot> {
    system.refresh_cpu();
    system.refresh_memory();
    system.refresh_processes_specifics(
        ProcessesToUpdate::All,
        true,
        ProcessRefreshKind::everything(),
    );
    system.refresh_disks_list();
    system.refresh_disks();

    let cpu_usage = system.global_cpu_info().cpu_usage();

    let total_memory = system.total_memory();
    let used_memory = system.used_memory();
    let memory_usage = if total_memory == 0 {
        0.0
    } else {
        (used_memory as f32 / total_memory as f32) * 100.0
    };

    let mut disks = Vec::new();
    for disk in system.disks() {
        let total = disk.total_space();
        let available = disk.available_space();
        let used_percent = if total == 0 {
            0.0
        } else {
            ((total - available) as f32 / total as f32) * 100.0
        };

        disks.push(DiskInfo {
            name: disk.name().to_string_lossy().to_string(),
            mount_point: disk.mount_point().to_string_lossy().to_string(),
            total_space_bytes: total,
            available_space_bytes: available,
            used_percent,
        });
    }

    let top_limit = {
        let s = state.read().await;
        s.config.top_process_limit
    };

    let mut processes: Vec<ProcessInfo> = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessInfo {
            pid: pid.as_u32(),
            name: proc_.name().to_string_lossy().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory(),
            status: format!("{:?}", proc_.status()),
        })
        .collect();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
    });
    processes.truncate(top_limit);

    let cfg = {
        let s = state.read().await;
        s.config.clone()
    };

    let mut alerts = Vec::new();
    if cpu_usage >= cfg.cpu_alert_percent {
        alerts.push(format!("high_cpu:{cpu_usage:.2}%"));
    }
    if memory_usage >= cfg.memory_alert_percent {
        alerts.push(format!("high_memory:{memory_usage:.2}%"));
    }
    for d in &disks {
        if d.used_percent >= cfg.disk_alert_percent {
            alerts.push(format!(
                "high_disk:{}:{:.2}%",
                d.mount_point, d.used_percent
            ));
        }
    }

    Ok(ResourceSnapshot {
        timestamp_unix_ms: now_unix_ms(),
        cpu_usage_percent: cpu_usage,
        total_memory_bytes: total_memory,
        used_memory_bytes: used_memory,
        memory_usage_percent: memory_usage,
        disks,
        top_processes: processes,
        alerts,
    })
}

async fn evaluate_policies(state: &Arc<RwLock<DaemonState>>, snapshot: &ResourceSnapshot) {
    if snapshot.alerts.is_empty() {
        debug!("no alerts");
        return;
    }

    for alert in &snapshot.alerts {
        warn!("alert triggered: {alert}");
        let mut s = state.write().await;
        s.action_log.push(ActionRecord {
            timestamp_unix_ms: now_unix_ms(),
            action: format!("alert:{alert}"),
            result: "recorded".to_string(),
        });

        if s.action_log.len() > 1000 {
            let excess = s.action_log.len() - 1000;
            s.action_log.drain(0..excess);
        }
    }
}

async fn server_loop(
    socket_path: &str,
    state: Arc<RwLock<DaemonState>>,
    shutdown: &mut broadcast::Receiver<()>,
) -> Result<()> {
    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("failed to bind unix socket at {socket_path}"))?;

    info!("control socket listening at {socket_path}");

    loop {
        tokio::select! {
            _ = shutdown.recv() => {
                info!("server loop shutting down");
                break;
            }
            accept_res = listener.accept() => {
                let (stream, _) = accept_res?;
                let state = Arc::clone(&state);
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state).await {
                        error!("client handler error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<DaemonState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let response = match serde_json::from_str::<Command>(line) {
            Ok(cmd) => handle_command(cmd, &state).await,
            Err(e) => serde_json::to_string(&Response::<serde_json::Value>::err(format!(
                "invalid command: {e}"
            )))?,
        };

        writer.write_all(response.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn handle_command(cmd: Command, state: &Arc<RwLock<DaemonState>>) -> String {
    match cmd {
        Command::GetStatus => {
            let s = state.read().await;
            serde_json::to_string(&Response::ok(s.latest.clone())).unwrap_or_else(|e| {
                serde_json::to_string(&Response::<()>::err(format!("serialization error: {e}")))
                    .unwrap()
            })
        }
        Command::GetConfig => {
            let s = state.read().await;
            serde_json::to_string(&Response::ok(s.config.clone())).unwrap_or_else(|e| {
                serde_json::to_string(&Response::<()>::err(format!("serialization error: {e}")))
                    .unwrap()
            })
        }
        Command::SetConfig {
            sample_interval_ms,
            cpu_alert_percent,
            memory_alert_percent,
            disk_alert_percent,
            top_process_limit,
        } => {
            let mut s = state.write().await;

            if let Some(v) = sample_interval_ms {
                s.config.sample_interval_ms = v.max(100);
            }
            if let Some(v) = cpu_alert_percent {
                s.config.cpu_alert_percent = v.clamp(0.0, 100.0);
            }
            if let Some(v) = memory_alert_percent {
                s.config.memory_alert_percent = v.clamp(0.0, 100.0);
            }
            if let Some(v) = disk_alert_percent {
                s.config.disk_alert_percent = v.clamp(0.0, 100.0);
            }
            if let Some(v) = top_process_limit {
                s.config.top_process_limit = v.clamp(1, 1000);
            }

            s.action_log.push(ActionRecord {
                timestamp_unix_ms: now_unix_ms(),
                action: "config_updated".to_string(),
                result: "ok".to_string(),
            });

            serde_json::to_string(&Response::ok(s.config.clone())).unwrap_or_else(|e| {
                serde_json::to_string(&Response::<()>::err(format!("serialization error: {e}")))
                    .unwrap()
            })
        }
        Command::ListActions => {
            let s = state.read().await;
            serde_json::to_string(&Response::ok(s.action_log.clone())).unwrap_or_else(|e| {
                serde_json::to_string(&Response::<()>::err(format!("serialization error: {e}")))
                    .unwrap()
            })
        }
        Command::Ping => serde_json::to_string(&Response::ok("pong")).unwrap_or_else(|e| {
            serde_json::to_string(&Response::<()>::err(format!("serialization error: {e}")))
                .unwrap()
        }),
    }
}

fn now_unix_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}
