async fn maybe_take_action(state: &Arc<RwLock<DaemonState>>, pid: u32) -> Result<()> {
    use nix::sys::signal::{kill, Signal};
    use nix::unistd::Pid as UnixPid;

    // Example: only allow action on pre-approved PIDs or process names.
    let allowed = false;
    if !allowed {
        let mut s = state.write().await;
        s.action_log.push(ActionRecord {
            timestamp_unix_ms: now_unix_ms(),
            action: format!("kill_attempt:{pid}"),
            result: "denied".to_string(),
        });
        return Ok(());
    }

    kill(UnixPid::from_raw(pid as i32), Signal::SIGTERM)?;
    let mut s = state.write().await;
    s.action_log.push(ActionRecord {
        timestamp_unix_ms: now_unix_ms(),
        action: format!("sigterm:{pid}"),
        result: "ok".to_string(),
    });
    Ok(())
}
