```rust
use anyhow::{Context, Result};
use nix::sys::signal::{self, SigSet, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::{remove_file, OpenOptions};
use std::io::Write;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::sync::{Arc, RwLock};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuRefreshKind, Pid as SysPid, ProcessRefreshKind, RefreshKind, System};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal::unix::{signal as tokio_signal, SignalKind};
use tokio::time;
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Metrics {
    timestamp: u64,
    cpu_usage_percent: f32,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    process_count: usize,
    disks: Vec<DiskMetrics>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskMetrics {
    name: String,
    total_space: u64,
    available_space: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    memory_kb: u64,
    cpu_usage_percent: f32,
}

#[derive(Debug, Default)]
struct SharedState {
    latest_metrics: Option<Metrics>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    GetMetrics,
    TopProcesses { limit: Option<usize> },
    Renice { pid: i32, priority: i32 },
    DropCaches,
    Ping,
}

#[derive(Debug, Serialize)]
struct Response<T: Serialize> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn collect_metrics(sys: &mut System) -> Metrics {
    sys.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything()),
    );

    let load = System::load_average();

    let disks = sysinfo::Disks::new_with_refreshed_list()
        .iter()
        .map(|d| DiskMetrics {
            name: d.name().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
        })
        .collect::<Vec<_>>();

    Metrics {
        timestamp: now_ts(),
        cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
        loadavg_one: load.one,
        loadavg_five: load.five,
        loadavg_fifteen: load.fifteen,
        total_memory_kb: sys.total_memory(),
        used_memory_kb: sys.used_memory(),
        total_swap_kb: sys.total_swap(),
        used_swap_kb: sys.used_swap(),
        process_count: sys.processes().len(),
        disks,
    }
}

fn top_processes(sys: &mut System, limit: usize) -> Vec<ProcessInfo> {
    sys.refresh_processes_specifics(ProcessRefreshKind::everything());

    let mut procs = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessInfo {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            memory_kb: p.memory(),
            cpu_usage_percent: p.cpu_usage(),
        })
        .collect::<Vec<_>>();

    procs.sort_by(|a, b| b.memory_kb.cmp(&a.memory_kb));
    procs.truncate(limit);
    procs
}

fn renice_process(pid: i32, priority: i32) -> Result<()> {
    let who = Pid::from_raw(pid);
    let prio = priority.clamp(-20, 19);

    let rc = unsafe { libc::setpriority(libc::PRIO_PROCESS, who.as_raw() as u32, prio) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error()).context("setpriority failed");
    }
    Ok(())
}

fn drop_caches() -> Result<()> {
    let mut file = OpenOptions::new()
        .write(true)
        .open("/proc/sys/vm/drop_caches")
        .context("opening /proc/sys/vm/drop_caches failed")?;

    file.write_all(b"3")
        .context("writing drop_caches failed")?;
    Ok(())
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Command = match serde_json::from_str(&line) {
            Ok(c) => c,
            Err(e) => {
                let resp = Response::<serde_json::Value> {
                    ok: false,
                    data: None,
                    error: Some(format!("invalid command: {e}")),
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
                continue;
            }
        };

        match cmd {
            Command::GetMetrics => {
                let metrics = state.read().unwrap().latest_metrics.clone();
                let resp = Response {
                    ok: true,
                    data: metrics,
                    error: None::<String>,
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
            }
            Command::TopProcesses { limit } => {
                let mut sys = System::new();
                let data = top_processes(&mut sys, limit.unwrap_or(10).min(100));
                let resp = Response {
                    ok: true,
                    data: Some(data),
                    error: None::<String>,
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
            }
            Command::Renice { pid, priority } => {
                let resp = match renice_process(pid, priority) {
                    Ok(_) => Response::<serde_json::Value> {
                        ok: true,
                        data: None,
                        error: None,
                    },
                    Err(e) => Response::<serde_json::Value> {
                        ok: false,
                        data: None,
                        error: Some(e.to_string()),
                    },
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
            }
            Command::DropCaches => {
                let resp = match drop_caches() {
                    Ok(_) => Response::<serde_json::Value> {
                        ok: true,
                        data: None,
                        error: None,
                    },
                    Err(e) => Response::<serde_json::Value> {
                        ok: false,
                        data: None,
                        error: Some(e.to_string()),
                    },
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
            }
            Command::Ping => {
                let resp = Response {
                    ok: true,
                    data: Some(HashMap::from([("pong", true)])),
                    error: None::<String>,
                };
                writer
                    .write_all(format!("{}\n", serde_json::to_string(&resp)?).as_bytes())
                    .await?;
            }
        }
    }

    Ok(())
}

async fn monitoring_loop(state: Arc<RwLock<SharedState>>) {
    let mut sys = System::new();
    let mut interval = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));

    loop {
        interval.tick().await;
        let metrics = collect_metrics(&mut sys);
        {
            let mut guard = state.write().unwrap();
            guard.latest_metrics = Some(metrics);
        }
    }
}

async fn socket_server(state: Arc<RwLock<SharedState>>) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        remove_file(SOCKET_PATH).ok();
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket failed")?;
    std::fs::set_permissions(SOCKET_PATH, std::fs::Permissions::from_mode(0o660))
        .context("setting socket permissions failed")?;

    info!("listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handler error: {e:#}");
            }
        });
    }
}

async fn shutdown_signal() -> Result<()> {
    let mut sigterm = tokio_signal(SignalKind::terminate())?;
    let mut sigint = tokio_signal(SignalKind::interrupt())?;

    tokio::select! {
        _ = sigterm.recv() => {}
        _ = sigint.recv() => {}
    }

    Ok(())
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .with_target(false)
        .init();

    let state = Arc::new(RwLock::new(SharedState::default()));

    let monitor_state = Arc::clone(&state);
    let server_state = Arc::clone(&state);

    let monitor_task = tokio::spawn(async move {
        monitoring_loop(monitor_state).await;
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = socket_server(server_state).await {
            error!("socket server failed: {e:#}");
        }
    });

    info!("sysmond started");

    shutdown_signal().await?;
    info!("shutdown signal received");

    monitor_task.abort();
    server_task.abort();

    if Path::new(SOCKET_PATH).exists() {
        remove_file(SOCKET_PATH).ok();
    }

    info!("sysmond stopped");
    Ok(())
}
