        .unwrap_or_default()
        .as_millis()
}

async fn load_config(path: &Path) -> Result<Config> {
    match tokio::fs::read_to_string(path).await {
        Ok(s) => {
            let cfg = serde_json::from_str::<Config>(&s)
                .with_context(|| format!("failed parsing config {}", path.display()))?;
            Ok(cfg)
        }
        Err(_) => {
            warn!("config not found at {}, using defaults", path.display());
            Ok(Config::default())
        }
    }
}

async fn execute_action(name: &str, cmdline: &str) {
    let name = name.to_string();
    let cmdline = cmdline.to_string();

    task::spawn(async move {
        warn!(action = %name, command = %cmdline, "executing action");

        let shell = "/bin/sh";
        let result = Command::new(shell).arg("-c").arg(&cmdline).output().await;

        match result {
            Ok(output) => {
                if !output.status.success() {
                    error!(
                        action = %name,
                        status = ?output.status.code(),
                        stderr = %String::from_utf8_lossy(&output.stderr),
                        "action failed"
                    );
                } else {
                    debug!(
                        action = %name,
                        stdout = %String::from_utf8_lossy(&output.stdout),
                        "action succeeded"
                    );
                }
            }
            Err(e) => {
                error!(action = %name, error = %e, "failed to spawn action");
            }
        }
    });
}

async fn maybe_trigger_action(state: &Arc<AppState>, action_name: &str) {
    let cfg = state.config.read().await.clone();

    let cmdline = match cfg.commands.get(action_name) {
        Some(c) => c.clone(),
        None => return,
    };

    let cooldown = Duration::from_secs(cfg.action_cooldown_secs);
    let mut last = state.last_action.write().await;

    let should_run = match last.get(action_name) {
        Some(t) => t.elapsed() >= cooldown,
        None => true,
    };

    if should_run {
        last.insert(action_name.to_string(), Instant::now());
        execute_action(action_name, &cmdline).await;
    } else {
        debug!(action = %action_name, "cooldown active, skipping action");
    }
}

fn collect_disk_metrics(disks: &Disks, mounts: &[String]) -> Vec<DiskMetric> {
    let mut out = Vec::new();

    for disk in disks.list() {
        let mount = disk.mount_point().to_string_lossy().to_string();
        if !mounts.is_empty() && !mounts.iter().any(|m| m == &mount) {
            continue;
        }

        let total = disk.total_space();
        let avail = disk.available_space();
        let used = total.saturating_sub(avail);
        let used_percent = if total > 0 {
            (used as f64 / total as f64 * 100.0) as f32
        } else {
            0.0
        };

        out.push(DiskMetric {
            mount,
            used_percent,
            total_bytes: total,
            available_bytes: avail,
        });
    }

    out
}

async fn monitor_loop(state: Arc<AppState>, interval: Duration, mut shutdown_rx: broadcast::Receiver<()>) {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_memory(MemoryRefreshKind::everything())
            .with_cpu(sysinfo::CpuRefreshKind::everything()),
    );
    let mut disks = Disks::new_with_refreshed_list();

    let mut ticker = time::interval(interval);
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                system.refresh_cpu();
                system.refresh_memory();
                disks.refresh();

                let cpu = system.global_cpu_info().cpu_usage();
                let total_mem = system.total_memory();
                let used_mem = system.used_memory();
                let mem_percent = if total_mem > 0 {
                    (used_mem as f64 / total_mem as f64 * 100.0) as f32
                } else {
                    0.0
                };

                let LoadAvg { one, five, fifteen } = System::load_average();
                let cfg = state.config.read().await.clone();
                let disk_metrics = collect_disk_metrics(&disks, &cfg.disk_mounts);

                let metrics = Metrics {
                    timestamp_unix_ms: now_unix_ms(),
                    cpu_percent: cpu,
                    mem_percent,
                    load1: one,
                    load5: five,
                    load15: fifteen,
                    disks: disk_metrics.clone(),
                };

                {
                    let mut m = state.metrics.write().await;
                    *m = metrics.clone();
                }

                if metrics.cpu_percent >= cfg.cpu_warn_percent {
                    warn!(cpu = metrics.cpu_percent, threshold = cfg.cpu_warn_percent, "cpu threshold exceeded");
                    maybe_trigger_action(&state, "cpu_warn").await;
                }

                if metrics.mem_percent >= cfg.mem_warn_percent {
                    warn!(mem = metrics.mem_percent, threshold = cfg.mem_warn_percent, "memory threshold exceeded");
                    maybe_trigger_action(&state, "mem_warn").await;
                }

                if metrics.load1 >= cfg.load1_warn {
                    warn!(load1 = metrics.load1, threshold = cfg.load1_warn, "load threshold exceeded");
                    maybe_trigger_action(&state, "load_warn").await;
                }

                for d in &disk_metrics {
                    if d.used_percent >= cfg.disk_warn_percent {
                        warn!(mount = %d.mount, used = d.used_percent, threshold = cfg.disk_warn_percent, "disk threshold exceeded");
                        maybe_trigger_action(&state, "disk_warn").await;
                    }
                }
            }
            _ = shutdown_rx.recv() => {
                info!("monitor loop shutting down");
                break;
            }
        }
    }
}

async fn handle_client(stream: UnixStream, state: Arc<AppState>, config_path: PathBuf, shutdown_tx: broadcast::Sender<()>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd = line.trim();

    match cmd {
        "status" => {
            let metrics = state.metrics.read().await.clone();
            let config = state.config.read().await.clone();
            let status = DaemonStatus {
                started_unix_ms: state.started_unix_ms,
                uptime_secs: state.started.elapsed().as_secs(),
                metrics,
                config,
            };
            let body = serde_json::to_vec(&status)?;
            writer.write_all(&body).await?;
            writer.write_all(b"\n").await?;
        }
        "reload" => {
            let new_cfg = load_config(&config_path).await?;
            {
                let mut cfg = state.config.write().await;
                *cfg = new_cfg;
            }
            writer.write_all(b"{\"ok\":true,\"message\":\"reloaded\"}\n").await?;
        }
        "shutdown" => {
            let _ = shutdown_tx.send(());
            writer.write_all(b"{\"ok\":true,\"message\":\"shutting down\"}\n").await?;
        }
        _ => {
            writer
                .write_all(b"{\"ok\":false,\"error\":\"unknown command\"}\n")
                .await?;
        }
    }

    Ok(())
}

async fn socket_server(
    socket_path: PathBuf,
    state: Arc<AppState>,
    config_path: PathBuf,
    shutdown_tx: broadcast::Sender<()>,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    if socket_path.exists() {
        fs::remove_file(&socket_path)
            .with_context(|| format!("failed removing stale socket {}", socket_path.display()))?;
    }

    if let Some(parent) = socket_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed creating socket dir {}", parent.display()))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed binding socket {}", socket_path.display()))?;

    info!("listening on {}", socket_path.display());

    loop {
        tokio::select! {
            accept_res = listener.accept() => {
                match accept_res {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        let config_path = config_path.clone();
                        let shutdown_tx = shutdown_tx.clone();
                        task::spawn(async move {
                            if let Err(e) = handle_client(stream, state, config_path, shutdown_tx).await {
                                error!(error = %e, "client handling failed");
                            }
                        });
                    }
                    Err(e) => {
                        error!(error = %e, "socket accept failed");
                    }
                }
            }
            _ = shutdown_rx.recv() => {
                info!("socket server shutting down");
                break;
            }
        }
    }

    let _ = fs::remove_file(&socket_path);
    Ok(())
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,resourced=debug".to_string()),
        )
        .init();

    let args = Args::parse();
    let config = load_config(&args.config).await?;
    let state = Arc::new(AppState::new(config));

    let (shutdown_tx, _) = broadcast::channel::<()>(16);

    let monitor_handle = {
        let state = state.clone();
        let rx = shutdown_tx.subscribe();
        tokio::spawn(monitor_loop(
            state,
            Duration::from_millis(args.interval_ms),
            rx,
        ))
    };

    let socket_handle = {
        let state = state.clone();
        let rx = shutdown_tx.subscribe();
        tokio::spawn(socket_server(
            args.socket.clone(),
            state,
            args.config.clone(),
            shutdown_tx.clone(),
            rx,
        ))
    };

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c");
            let _ = shutdown_tx.send(());
        }
        res = monitor_handle => {
            match res {
                Ok(_) => info!("monitor task exited"),
                Err(e) => error!(error = %e, "monitor task join error"),
            }
            let _ = shutdown_tx.send(());
        }
        res = socket_handle => {
            match res {
                Ok(Ok(())) => info!("socket task exited"),
                Ok(Err(e)) => error!(error = %e, "socket task error"),
                Err(e) => error!(error = %e, "socket task join error"),
            }
            let _ = shutdown_tx.send(());
        }
    }

    time::sleep(Duration::from_millis(200)).await;
    info!("daemon exiting");
    Ok(())
}
