# Main daemon code: `src/main.rs`

```rust
use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::process::Stdio;
use std::sync::Arc;
use sysinfo::{DiskExt, ProcessExt, System, SystemExt};
use thiserror::Error;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::process::Command;
use tokio::signal::unix::{signal, SignalKind};
use tokio::sync::{watch, RwLock};
use tokio::time::{self, Duration};
use tracing::{error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    poll_interval_ms: u64,
    socket_path: String,
    cpu: CpuConfig,
    memory: MemoryConfig,
    disk: DiskConfig,
    processes: Vec<ProcessRule>,
}

#[derive(Debug, Deserialize, Clone)]
struct CpuConfig {
    alert_percent: f32,
}

#[derive(Debug, Deserialize, Clone)]
struct MemoryConfig {
    alert_percent: f32,
}

#[derive(Debug, Deserialize, Clone)]
struct DiskConfig {
    mount_path: String,
    alert_percent: f32,
}

#[derive(Debug, Deserialize, Clone)]
struct ProcessRule {
    name: String,
    match_substring: String,
    required: bool,
    restart_command: String,
    sigterm_on_high_memory: bool,
    memory_limit_mb: u64,
}

#[derive(Debug, Serialize, Clone, Default)]
struct ProcessSnapshot {
    name: String,
    pid: i32,
    memory_mb: u64,
    cpu_percent: f32,
    status: String,
}

#[derive(Debug, Serialize, Clone)]
struct MetricsSnapshot {
    timestamp: DateTime<Utc>,
    cpu_percent: f32,
    memory_percent: f32,
    disk_percent: f32,
    processes: Vec<ProcessSnapshot>,
    alerts: Vec<String>,
}

impl Default for MetricsSnapshot {
    fn default() -> Self {
        Self {
            timestamp: Utc::now(),
            cpu_percent: 0.0,
            memory_percent: 0.0,
            disk_percent: 0.0,
            processes: Vec::new(),
            alerts: Vec::new(),
        }
    }
}

#[derive(Debug, Error)]
enum DaemonError {
    #[error("config error: {0}")]
    Config(String),
}

#[derive(Clone)]
struct SharedState {
    metrics: Arc<RwLock<MetricsSnapshot>>,
    config: Arc<RwLock<Config>>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "config/daemon.toml".to_string());

    let cfg = load_config(&config_path)?;
    let state = SharedState {
        metrics: Arc::new(RwLock::new(MetricsSnapshot::default())),
        config: Arc::new(RwLock::new(cfg.clone())),
    };

    if Path::new(&cfg.socket_path).exists() {
        fs::remove_file(&cfg.socket_path)
            .with_context(|| format!("failed to remove stale socket {}", cfg.socket_path))?;
    }

    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let monitor_state = state.clone();
    let monitor_config_path = config_path.clone();
    let monitor_shutdown = shutdown_rx.clone();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_config_path, monitor_shutdown).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let socket_state = state.clone();
    let socket_shutdown = shutdown_rx.clone();
    let socket_path = cfg.socket_path.clone();
    let socket_task = tokio::spawn(async move {
        if let Err(e) = socket_server(socket_state, socket_path, socket_shutdown).await {
            error!("socket server failed: {e:#}");
        }
    });

    let signal_task = tokio::spawn(handle_signals(shutdown_tx.clone()));

    tokio::select! {
        _ = monitor_task => {
            warn!("monitor task exited");
        }
        _ = socket_task => {
            warn!("socket task exited");
        }
        _ = signal_task => {
            info!("signal handler exited");
        }
    }

    let _ = shutdown_tx.send(true);
    time::sleep(Duration::from_millis(300)).await;

    let final_cfg = state.config.read().await.clone();
    if Path::new(&final_cfg.socket_path).exists() {
        let _ = fs::remove_file(&final_cfg.socket_path);
    }

    info!("daemon shutdown complete");
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

fn load_config(path: &str) -> Result<Config> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {path}"))?;
    let cfg: Config = toml::from_str(&raw)
        .with_context(|| format!("failed to parse config file: {path}"))?;
    validate_config(&cfg)?;
    Ok(cfg)
}

fn validate_config(cfg: &Config) -> Result<()> {
    if cfg.poll_interval_ms == 0 {
        return Err(DaemonError::Config("poll_interval_ms must be > 0".into()).into());
    }
    if cfg.socket_path.is_empty() {
        return Err(DaemonError::Config("socket_path cannot be empty".into()).into());
    }
    Ok(())
}

async fn handle_signals(shutdown_tx: watch::Sender<bool>) {
    let mut sigterm = signal(SignalKind::terminate()).expect("sigterm handler");
    let mut sigint = signal(SignalKind::interrupt()).expect("sigint handler");
    let mut sighup = signal(SignalKind::hangup()).expect("sighup handler");

    loop {
        tokio::select! {
            _ = sigterm.recv() => {
                info!("received SIGTERM");
                let _ = shutdown_tx.send(true);
                break;
            }
            _ = sigint.recv() => {
                info!("received SIGINT");
                let _ = shutdown_tx.send(true);
                break;
            }
            _ = sighup.recv() => {
                info!("received SIGHUP (ignored globally; use reload command)");
            }
        }
    }
}

async fn monitor_loop(
    state: SharedState,
    config_path: String,
    mut shutdown_rx: watch::Receiver<bool>,
) -> Result<()> {
    let mut sys = System::new_all();

    {
        sys.refresh_all();
        time::sleep(Duration::from_millis(200)).await;
        sys.refresh_cpu();
    }

    loop {
        if *shutdown_rx.borrow() {
            info!("monitor loop shutting down");
            break;
        }

        let cfg = state.config.read().await.clone();

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();
        sys.refresh_processes();

        let mut alerts = Vec::new();

        let cpu_percent = sys.global_cpu_info().cpu_usage();

        let total_mem = sys.total_memory() as f32;
        let used_mem = sys.used_memory() as f32;
        let memory_percent = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let disk_percent = disk_usage_percent(&sys, &cfg.disk.mount_path).unwrap_or(0.0);

        if cpu_percent >= cfg.cpu.alert_percent {
            alerts.push(format!(
                "high CPU usage: {:.2}% >= {:.2}%",
                cpu_percent, cfg.cpu.alert_percent
            ));
        }

        if memory_percent >= cfg.memory.alert_percent {
            alerts.push(format!(
                "high memory usage: {:.2}% >= {:.2}%",
                memory_percent, cfg.memory.alert_percent
            ));
        }

        if disk_percent >= cfg.disk.alert_percent {
            alerts.push(format!(
                "high disk usage on {}: {:.2}% >= {:.2}%",
                cfg.disk.mount_path, disk_percent, cfg.disk.alert_percent
            ));
        }

        let process_snapshots = evaluate_processes(&cfg, &sys, &mut alerts).await;

        let snapshot = MetricsSnapshot {
            timestamp: Utc::now(),
            cpu_percent,
            memory_percent,
            disk_percent,
            processes: process_snapshots,
            alerts,
        };

        {
            let mut guard = state.metrics.write().await;
            *guard = snapshot.clone();
        }

        for alert in &snapshot.alerts {
            warn!("{alert}");
        }

        tokio::select! {
            _ = time::sleep(Duration::from_millis(cfg.poll_interval_ms)) => {}
            changed = shutdown_rx.changed() => {
                if changed.is_ok() && *shutdown_rx.borrow() {
                    info!("monitor loop received shutdown");
                    break;
                }
            }
        }

        if let Ok(new_cfg) = load_config(&config_path) {
            let mut guard = state.config.write().await;
            *guard = new_cfg;
        }
    }

    Ok(())
}

fn disk_usage_percent(sys: &System, mount_path: &str) -> Option<f32> {
    for disk in sys.disks() {
        if disk.mount_point().to_string_lossy() == mount_path {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                let used = total - avail;
                return Some((used / total) * 100.0);
            }
        }
    }
    None
}

async fn evaluate_processes(
    cfg: &Config,
    sys: &System,
    alerts: &mut Vec<String>,
) -> Vec<ProcessSnapshot> {
    let mut result = Vec::new();
    let mut matched: HashMap<String, Vec<ProcessSnapshot>> = HashMap::new();

    for (pid, proc_) in sys.processes() {
        let name = proc_.name().to_string();
        let cmdline = proc_.cmd().join(" ");
        let mem_mb = proc_.memory() / 1024;
        let cpu = proc_.cpu_usage();
        let status = format!("{:?}", proc_.status());

        for rule in &cfg.processes {
            if name.contains(&rule.match_substring) || cmdline.contains(&rule.match_substring) {
                let snap = ProcessSnapshot {
                    name: rule.name.clone(),
                    pid: pid.as_u32() as i32,
                    memory_mb: mem_mb,
                    cpu_percent: cpu,
                    status: status.clone(),
                };
                matched.entry(rule.name.clone()).or_default().push(snap.clone());

                if rule.memory_limit_mb > 0 && mem_mb > rule.memory_limit_mb {
                    let msg = format!(
                        "process {} pid={} memory={}MB exceeds limit={}MB",
                        rule.name,
                        pid.as_u32(),
                        mem_mb,
                        rule.memory_limit_mb
                    );
                    alerts.push(msg.clone());
                    warn!("{msg}");

                    if rule.sigterm_on_high_memory {
                        if let Err(e) = kill(Pid::from_raw(pid.as_u32() as i32), Signal::SIGTERM) {
                            error!("failed to SIGTERM pid {}: {}", pid.as_u32(), e);
                        } else {
                            warn!("sent SIGTERM to {} pid={}", rule.name, pid.as_u32());
                        }
                    }
                }
            }
        }
    }

    for rule in &cfg.processes {
        match matched.get(&rule.name) {
            Some(snaps) if !snaps.is_empty() => {
                result.extend_from_slice(snaps);
            }
            _ => {
                if rule.required {
                    let msg = format!("required process '{}' is not running", rule.name);
                    alerts.push(msg.clone());
                    error!("{msg}");

                    if !rule.restart_command.trim().is_empty() {
                        if let Err(e) = spawn_restart(&rule.restart_command).await {
                            error!(
                                "failed to execute restart command for {}: {e:#}",
                                rule.name
                            );
                        } else {
                            warn!("restart command executed for {}", rule.name);
                        }
                    }
                }
            }
        }
    }

    result
}

async fn spawn_restart(cmd: &str) -> Result<()> {
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .with_context(|| format!("failed to spawn restart command: {cmd}"))?;

    tokio::spawn(async move {
        let _ = child.wait().await;
    });

    Ok(())
}

async fn socket_server(
    state: SharedState,
    socket_path: String,
    mut shutdown_rx: watch::Receiver<bool>,
) -> Result<()> {
    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket: {socket_path}"))?;
    info!("control socket listening on {}", socket_path);

    loop {
        tokio::select! {
            accept_res = listener.accept() => {
                let (stream, _) = accept_res?;
                let state = state.clone();
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state).await {
                        error!("client handling error: {e:#}");
                    }
                });
            }
            changed = shutdown_rx.changed() => {
                if changed.is_ok() && *shutdown_rx.borrow() {
                    info!("socket server shutting down");
                    break;
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer.write_all(b"os-daemon ready\n").await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        match cmd {
            "status" => {
                let metrics = state.metrics.read().await.clone();
                let summary = format!(
                    "timestamp={} cpu={:.2}% mem={:.2}% disk={:.2}% alerts={}\n",
                    metrics.timestamp,
                    metrics.cpu_percent,
                    metrics.memory_percent,
                    metrics.disk_percent,
                    metrics.alerts.len()
                );
                writer.write_all(summary.as_bytes()).await?;
            }
            "metrics" => {
                let metrics = state.metrics.read().await.clone();
                let json = metrics_to_json(&metrics);
                writer.write_all(json.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "reload" => {
                writer.write_all(b"reload requested\n").await?;
            }
            "shutdown" => {
                writer.write_all(b"shutdown must be sent via signal\n").await?;
            }
            "help" => {
                writer
                    .write_all(b"commands: status, metrics, reload, shutdown, help\n")
                    .await?;
            }
            _ => {
                writer.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}

fn metrics_to_json(metrics: &MetricsSnapshot) -> String {
    let mut s = String::new();
    s.push('{');
    s.push_str(&format!(
        "\"timestamp\":\"{}\",\"cpu_percent\":{:.2},\"memory_percent\":{:.2},\"disk_percent\":{:.2},\"alerts\":[",
        metrics.timestamp.to_rfc3339(),
        metrics.cpu_percent,
        metrics.memory_percent,
        metrics.disk_percent
    ));

    for (i, a) in metrics.alerts.iter().enumerate() {
        if i > 0 {
            s.push(',');
        }
        s.push('"');
        s.push_str(&escape_json(a));
        s.push('"');
    }

    s.push_str("],\"processes\":[");
    for (i, p) in metrics.processes.iter().enumerate() {
        if i > 0 {
            s.push(',');
        }
        s.push_str(&format!(
            "{{\"name\":\"{}\",\"pid\":{},\"memory_mb\":{},\"cpu_percent\":{:.2},\"status\":\"{}\"}}",
            escape_json(&p.name),
            p.pid,
            p.memory_mb,
            p.cpu_percent,
            escape_json(&p.status)
        ));
    }
    s.push_str("]}");
    s
}

fn escape_json(input: &str) -> String {
    input
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}
