## src/main.rs

```rust
use anyhow::{Context, Result};
use log::{error, info, warn};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{Disks, LoadAvg, PidExt, ProcessExt, System, SystemExt};

const SOCKET_PATH: &str = "/tmp/sysguardd.sock";
const POLL_INTERVAL_SECS: u64 = 2;
const MAX_CLIENT_LINE: usize = 16 * 1024;

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp: u64,
    cpu_usage_percent: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_one: f64,
    load_five: f64,
    load_fifteen: f64,
    disks: Vec<DiskSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
}

#[derive(Debug, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_usage_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetMetrics,
    ListProcesses { limit: Option<usize> },
    TerminateProcess { pid: i32 },
    SetPriority { pid: i32, nice: i32 },
    Ping,
}

#[derive(Debug, Serialize)]
struct Response<T> {
    ok: bool,
    result: Option<T>,
    error: Option<String>,
}

#[derive(Debug, Serialize)]
struct Pong {
    message: &'static str,
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn collect_metrics(sys: &mut System, disks: &mut Disks) -> MetricsSnapshot {
    sys.refresh_cpu_usage();
    sys.refresh_memory();
    disks.refresh();

    let load: LoadAvg = System::load_average();

    let disk_snaps = disks
        .list()
        .iter()
        .map(|d| DiskSnapshot {
            name: d.name().to_string_lossy().to_string(),
            mount_point: d.mount_point().to_string_lossy().to_string(),
            total_space: d.total_space(),
            available_space: d.available_space(),
        })
        .collect();

    MetricsSnapshot {
        timestamp: now_ts(),
        cpu_usage_percent: sys.global_cpu_usage(),
        total_memory: sys.total_memory(),
        used_memory: sys.used_memory(),
        total_swap: sys.total_swap(),
        used_swap: sys.used_swap(),
        load_one: load.one,
        load_five: load.five,
        load_fifteen: load.fifteen,
        disks: disk_snaps,
    }
}

fn list_processes(sys: &mut System, limit: usize) -> Vec<ProcessInfo> {
    sys.refresh_processes();

    let mut procs: Vec<ProcessInfo> = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessInfo {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage_percent: p.cpu_usage(),
            memory_bytes: p.memory(),
            status: format!("{:?}", p.status()),
        })
        .collect();

    procs.sort_by(|a, b| {
        b.cpu_usage_percent
            .partial_cmp(&a.cpu_usage_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    procs.truncate(limit);
    procs
}

fn terminate_process(pid: i32) -> Result<()> {
    kill(Pid::from_raw(pid), Signal::SIGTERM).context("failed to send SIGTERM")?;
    Ok(())
}

fn set_priority(pid: i32, nice: i32) -> Result<()> {
    if !(-20..=19).contains(&nice) {
        anyhow::bail!("nice value out of range (-20..19)");
    }

    // Safer policy: only allow lowering priority for non-privileged usage.
    if nice < 0 {
        anyhow::bail!("negative nice values are not allowed by policy");
    }

    let who = pid as u32;
    nix::sys::resource::setpriority(nix::sys::resource::Which::PRIO_PROCESS, who, nice)
        .context("failed to set priority")?;
    Ok(())
}

fn write_json_line<T: Serialize>(stream: &mut UnixStream, value: &T) -> Result<()> {
    let mut buf = serde_json::to_vec(value)?;
    buf.push(b'\n');
    stream.write_all(&buf)?;
    stream.flush()?;
    Ok(())
}

fn handle_client(
    mut stream: UnixStream,
    metrics: Arc<Mutex<MetricsSnapshot>>,
    sys: Arc<Mutex<System>>,
) -> Result<()> {
    let reader_stream = stream.try_clone()?;
    let mut reader = BufReader::new(reader_stream);
    let mut line = String::new();

    let n = reader.read_line(&mut line)?;
    if n == 0 {
        return Ok(());
    }
    if line.len() > MAX_CLIENT_LINE {
        let resp: Response<()> = Response {
            ok: false,
            result: None,
            error: Some("request too large".into()),
        };
        write_json_line(&mut stream, &resp)?;
        return Ok(());
    }

    let req: Request = match serde_json::from_str(line.trim()) {
        Ok(r) => r,
        Err(e) => {
            let resp: Response<()> = Response {
                ok: false,
                result: None,
                error: Some(format!("invalid request: {e}")),
            };
            write_json_line(&mut stream, &resp)?;
            return Ok(());
        }
    };

    match req {
        Request::Ping => {
            let resp = Response {
                ok: true,
                result: Some(Pong { message: "pong" }),
                error: None::<String>,
            };
            write_json_line(&mut stream, &resp)?;
        }
        Request::GetMetrics => {
            let snap = metrics.lock().unwrap().clone();
            let resp = Response {
                ok: true,
                result: Some(snap),
                error: None::<String>,
            };
            write_json_line(&mut stream, &resp)?;
        }
        Request::ListProcesses { limit } => {
            let limit = limit.unwrap_or(20).min(500);
            let mut sys = sys.lock().unwrap();
            let procs = list_processes(&mut sys, limit);
            let resp = Response {
                ok: true,
                result: Some(procs),
                error: None::<String>,
            };
            write_json_line(&mut stream, &resp)?;
        }
        Request::TerminateProcess { pid } => {
            info!("terminate request pid={pid}");
            match terminate_process(pid) {
                Ok(_) => {
                    let resp = Response {
                        ok: true,
                        result: Some(serde_json::json!({ "pid": pid, "signal": "SIGTERM" })),
                        error: None::<String>,
                    };
                    write_json_line(&mut stream, &resp)?;
                }
                Err(e) => {
                    warn!("terminate failed pid={pid}: {e}");
                    let resp: Response<serde_json::Value> = Response {
                        ok: false,
                        result: None,
                        error: Some(e.to_string()),
                    };
                    write_json_line(&mut stream, &resp)?;
                }
            }
        }
        Request::SetPriority { pid, nice } => {
            info!("set_priority request pid={pid} nice={nice}");
            match set_priority(pid, nice) {
                Ok(_) => {
                    let resp = Response {
                        ok: true,
                        result: Some(serde_json::json!({ "pid": pid, "nice": nice })),
                        error: None::<String>,
                    };
                    write_json_line(&mut stream, &resp)?;
                }
                Err(e) => {
                    warn!("set_priority failed pid={pid} nice={nice}: {e}");
                    let resp: Response<serde_json::Value> = Response {
                        ok: false,
                        result: None,
                        error: Some(e.to_string()),
                    };
                    write_json_line(&mut stream, &resp)?;
                }
            }
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    env_logger::init();

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("failed to remove stale socket")?;
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("failed to bind unix socket")?;
    fs::set_permissions(SOCKET_PATH, std::os::unix::fs::PermissionsExt::from_mode(0o600))
        .context("failed to set socket permissions")?;

    let mut init_sys = System::new_all();
    init_sys.refresh_all();
    let mut init_disks = Disks::new_with_refreshed_list();
    let initial_metrics = collect_metrics(&mut init_sys, &mut init_disks);

    let metrics = Arc::new(Mutex::new(initial_metrics));
    let sys = Arc::new(Mutex::new(init_sys));

    {
        let metrics_bg = Arc::clone(&metrics);
        let sys_bg = Arc::clone(&sys);

        thread::spawn(move || {
            let mut disks = Disks::new_with_refreshed_list();

            loop {
                {
                    let mut sys = sys_bg.lock().unwrap();
                    let snap = collect_metrics(&mut sys, &mut disks);
                    let mut m = metrics_bg.lock().unwrap();
                    *m = snap;
                }
                thread::sleep(Duration::from_secs(POLL_INTERVAL_SECS));
            }
        });
    }

    info!("sysguardd listening on {}", SOCKET_PATH);

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let metrics = Arc::clone(&metrics);
                let sys = Arc::clone(&sys);
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, metrics, sys) {
                        error!("client error: {e}");
                    }
                });
            }
            Err(e) => {
                error!("accept error: {e}");
            }
        }
    }

    Ok(())
}
