use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    path::Path,
    process::Stdio,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Pid, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    process::Command,
    signal,
    sync::{Mutex, RwLock},
    task,
    time,
};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    poll_interval_ms: u64,
    socket_path: String,
    cpu_warn_percent: f32,
    mem_warn_percent: f32,
    disk_warn_percent: f32,
    load_warn_per_cpu: f64,
    top_process_count: usize,
    kill_process_cpu_percent: Option<f32>,
    kill_process_mem_mb: Option<u64>,
    exec_on_alert: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            socket_path: "/tmp/osd.sock".to_string(),
            cpu_warn_percent: 90.0,
            mem_warn_percent: 90.0,
            disk_warn_percent: 95.0,
            load_warn_per_cpu: 2.0,
            top_process_count: 10,
            kill_process_cpu_percent: Some(400.0),
            kill_process_mem_mb: Some(4096),
            exec_on_alert: None,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix_ms: u128,
    uptime_seconds: u64,
    cpu_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    memory_used_percent: f32,
    loadavg_one: f64,
    loadavg_five: f64,
    loadavg_fifteen: f64,
    disks: Vec<DiskInfo>,
    top_cpu_processes: Vec<ProcessInfo>,
    top_mem_processes: Vec<ProcessInfo>,
    alerts: Vec<String>,
}

#[derive(Debug, Serialize)]
struct StatusResponse {
    ok: bool,
    metrics: MetricsSnapshot,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ClientCommand {
    Status,
    KillPid { pid: u32 },
    Exec { command: String },
    ReloadConfig,
}

struct SharedState {
    latest: RwLock<Option<MetricsSnapshot>>,
    config: RwLock<Config>,
    last_action: Mutex<HashMap<String, Instant>>,
}

impl SharedState {
    fn new(config: Config) -> Self {
        Self {
            latest: RwLock::new(None),
            config: RwLock::new(config),
            last_action: Mutex::new(HashMap::new()),
        }
    }
}

fn read_config(path: &str) -> Result<Config> {
    if !Path::new(path).exists() {
        return Ok(Config::default());
    }
    let content = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {}", path))?;
    let cfg: Config = toml::from_str(&content)
        .with_context(|| format!("failed to parse config file: {}", path))?;
    Ok(cfg)
}

async fn execute_shell(command: &str) -> Result<()> {
    let status = Command::new("sh")
        .arg("-c")
        .arg(command)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .await
        .with_context(|| format!("failed to execute shell command: {}", command))?;

    if !status.success() {
        anyhow::bail!("command failed: {}", command);
    }
    Ok(())
}

fn process_info(p: &sysinfo::Process) -> ProcessInfo {
    ProcessInfo {
        pid: p.pid().as_u32(),
        name: p.name().to_string(),
        cpu_percent: p.cpu_usage(),
        memory_bytes: p.memory(),
        status: format!("{:?}", p.status()),
    }
}

async fn maybe_rate_limit_action(
    state: &Arc<SharedState>,
    key: &str,
    cooldown: Duration,
) -> bool {
    let mut map = state.last_action.lock().await;
    let now = Instant::now();
    match map.get(key) {
        Some(last) if now.duration_since(*last) < cooldown => false,
        _ => {
            map.insert(key.to_string(), now);
            true
        }
    }
}

async fn monitor_loop(state: Arc<SharedState>) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    // Prime CPU measurement
    system.refresh_cpu();
    time::sleep(Duration::from_millis(200)).await;

    loop {
        let cfg = state.config.read().await.clone();

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_processes();
        system.refresh_disks();

        let cpu_percent = system.global_cpu_info().cpu_usage();
        let memory_total = system.total_memory();
        let memory_used = system.used_memory();
        let memory_used_percent = if memory_total > 0 {
            (memory_used as f32 / memory_total as f32) * 100.0
        } else {
            0.0
        };

        let load = System::load_average();
        let cpu_count = system.cpus().len().max(1) as f64;

        let mut disks = Vec::new();
        let mut disk_alert = false;
        for d in system.disks() {
            let total = d.total_space();
            let avail = d.available_space();
            let used_percent = if total > 0 {
                ((total - avail) as f32 / total as f32) * 100.0
            } else {
                0.0
            };
            if used_percent >= cfg.disk_warn_percent {
                disk_alert = true;
            }
            disks.push(DiskInfo {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_percent,
            });
        }

        let mut processes: Vec<_> = system.processes().values().collect();
        processes.sort_by(|a, b| {
            b.cpu_usage()
                .partial_cmp(&a.cpu_usage())
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let top_cpu_processes = processes
            .iter()
            .take(cfg.top_process_count)
            .map(|p| process_info(p))
            .collect::<Vec<_>>();

        processes.sort_by_key(|p| std::cmp::Reverse(p.memory()));
        let top_mem_processes = processes
            .iter()
            .take(cfg.top_process_count)
            .map(|p| process_info(p))
            .collect::<Vec<_>>();

        let mut alerts = Vec::new();

        if cpu_percent >= cfg.cpu_warn_percent {
            alerts.push(format!("high_cpu:{:.2}%", cpu_percent));
        }
        if memory_used_percent >= cfg.mem_warn_percent {
            alerts.push(format!("high_memory:{:.2}%", memory_used_percent));
        }
        if disk_alert {
            alerts.push("high_disk_usage".to_string());
        }
        if load.one >= cfg.load_warn_per_cpu * cpu_count {
            alerts.push(format!(
                "high_load:{:.2} on {} cpus",
                load.one, cpu_count
            ));
        }

        for p in system.processes().values() {
            if let Some(limit) = cfg.kill_process_cpu_percent {
                if p.cpu_usage() >= limit {
                    let key = format!("kill-cpu-{}", p.pid().as_u32());
                    if maybe_rate_limit_action(&state, &key, Duration::from_secs(60)).await {
                        warn!(
                            pid = p.pid().as_u32(),
                            name = %p.name(),
                            cpu = p.cpu_usage(),
                            "killing process due to CPU threshold"
                        );
                        let _ = nix::sys::signal::kill(
                            nix::unistd::Pid::from_raw(p.pid().as_u32() as i32),
                            nix::sys::signal::Signal::SIGKILL,
                        );
                        alerts.push(format!("killed_pid_cpu:{}", p.pid().as_u32()));
                    }
                }
            }

            if let Some(limit_mb) = cfg.kill_process_mem_mb {
                let mem_mb = p.memory() / 1024 / 1024;
                if mem_mb >= limit_mb {
                    let key = format!("kill-mem-{}", p.pid().as_u32());
                    if maybe_rate_limit_action(&state, &key, Duration::from_secs(60)).await {
                        warn!(
                            pid = p.pid().as_u32(),
                            name = %p.name(),
                            mem_mb = mem_mb,
                            "killing process due to memory threshold"
                        );
                        let _ = nix::sys::signal::kill(
                            nix::unistd::Pid::from_raw(p.pid().as_u32() as i32),
                            nix::sys::signal::Signal::SIGKILL,
                        );
                        alerts.push(format!("killed_pid_mem:{}", p.pid().as_u32()));
                    }
                }
            }
        }

        if !alerts.is_empty() {
            warn!(alerts = ?alerts, "resource alerts triggered");
            if let Some(cmd) = &cfg.exec_on_alert {
                if maybe_rate_limit_action(&state, "exec_on_alert", Duration::from_secs(30)).await {
                    let cmd = cmd.clone();
                    task::spawn(async move {
                        if let Err(e) = execute_shell(&cmd).await {
                            error!(error = %e, "failed exec_on_alert");
                        }
                    });
                }
            }
        }

        let snapshot = MetricsSnapshot {
            timestamp_unix_ms: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis(),
            uptime_seconds: System::uptime(),
            cpu_percent,
            memory_used_bytes: memory_used,
            memory_total_bytes: memory_total,
            memory_used_percent,
            loadavg_one: load.one,
            loadavg_five: load.five,
            loadavg_fifteen: load.fifteen,
            disks,
            top_cpu_processes,
            top_mem_processes,
            alerts,
        };

        {
            let mut latest = state.latest.write().await;
            *latest = Some(snapshot);
        }

        debug!("metrics snapshot updated");
        time::sleep(Duration::from_millis(cfg.poll_interval_ms)).await;
    }
}

async fn handle_client(stream: UnixStream, state: Arc<SharedState>, config_path: Arc<String>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: ClientCommand = serde_json::from_str(line.trim())
        .with_context(|| "invalid client command JSON")?;

    match cmd {
        ClientCommand::Status => {
            let latest = state.latest.read().await;
            if let Some(metrics) = latest.clone() {
                let resp = StatusResponse { ok: true, metrics };
                writer
                    .write_all(serde_json::to_string(&resp)?.as_bytes())
                    .await?;
                writer.write_all(b"\n").await?;
            } else {
                writer
                    .write_all(b"{\"ok\":false,\"error\":\"no metrics yet\"}\n")
                    .await?;
            }
        }
        ClientCommand::KillPid { pid } => {
            let res = nix::sys::signal::kill(
                nix::unistd::Pid::from_raw(pid as i32),
                nix::sys::signal::Signal::SIGKILL,
            );
            match res {
                Ok(_) => writer
                    .write_all(format!("{{\"ok\":true,\"killed\":{}}}\n", pid).as_bytes())
                    .await?,
                Err(e) => writer
                    .write_all(
                        format!("{{\"ok\":false,\"error\":\"{}\"}}\n", e).as_bytes(),
                    )
                    .await?,
            }
        }
        ClientCommand::Exec { command } => {
            let result = execute_shell(&command).await;
            match result {
                Ok(_) => writer.write_all(b"{\"ok\":true}\n").await?,
                Err(e) => {
                    writer
                        .write_all(
                            format!("{{\"ok\":false,\"error\":\"{}\"}}\n", e).as_bytes(),
                        )
                        .await?
                }
            }
        }
        ClientCommand::ReloadConfig => {
            let cfg = read_config(&config_path)?;
            {
                let mut current = state.config.write().await;
                *current = cfg;
            }
            writer.write_all(b"{\"ok\":true,\"reloaded\":true}\n").await?;
        }
    }

    Ok(())
}

async fn socket_server(state: Arc<SharedState>, config_path: Arc<String>) -> Result<()> {
    let socket_path = {
        let cfg = state.config.read().await;
        cfg.socket_path.clone()
    };

    if Path::new(&socket_path).exists() {
        fs::remove_file(&socket_path)
            .with_context(|| format!("failed to remove existing socket {}", socket_path))?;
    }

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket {}", socket_path))?;

    info!(socket = %socket_path, "control socket listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        let config_path = config_path.clone();
        task::spawn(async move {
            if let Err(e) = handle_client(stream, state, config_path).await {
                error!(error = %e, "client handling failed");
            }
        });
    }
}

async fn shutdown_signal() {
    let ctrl_c = async {
        let _ = signal::ctrl_c().await;
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm = signal(SignalKind::terminate()).expect("sigterm handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config_path = Arc::new(
        std::env::args()
            .nth(1)
            .unwrap_or_else(|| "osd.toml".to_string()),
    );

    let config = read_config(&config_path)?;
    let state = Arc::new(SharedState::new(config));

    let monitor = {
        let state = state.clone();
        task::spawn(async move {
            if let Err(e) = monitor_loop(state).await {
                error!(error = %e, "monitor loop failed");
            }
        })
    };

    let server = {
        let state = state.clone();
        let config_path = config_path.clone();
        task::spawn(async move {
            if let Err(e) = socket_server(state, config_path).await {
                error!(error = %e, "socket server failed");
            }
        })
    };

    shutdown_signal().await;
    info!("shutdown signal received");

    monitor.abort();
    server.abort();

    let socket_path = {
        let cfg = state.config.read().await;
        cfg.socket_path.clone()
    };
    if Path::new(&socket_path).exists() {
        let _ = fs::remove_file(&socket_path);
    }

    Ok(())
}
