use std::sync::Arc;

#[derive(Clone)]
pub struct SharedState {
    inner: Arc<RwLock<Option<SystemSnapshot>>>,
}

impl SharedState {
    pub fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(None)),
        }
    }

    pub fn set_snapshot(&self, snapshot: SystemSnapshot) {
        *self.inner.write() = Some(snapshot);
    }

    pub fn get_snapshot(&self) -> Option<SystemSnapshot> {
        self.inner.read().clone()
    }
}
