```rust
use crate::{
    config::Config,
    metrics::{ProcessSnapshot, SystemSnapshot},
};
use tracing::{info, warn};

pub fn evaluate(snapshot: &SystemSnapshot, config: &Config) {
    if snapshot.cpu_percent >= config.thresholds.cpu_percent {
        warn!(
            cpu = snapshot.cpu_percent,
            threshold = config.thresholds.cpu_percent,
            "system cpu threshold exceeded"
        );
    }

    if snapshot.memory_percent >= config.thresholds.memory_percent {
        warn!(
            memory_percent = snapshot.memory_percent,
            threshold = config.thresholds.memory_percent,
            "system memory threshold exceeded"
        );
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= config.thresholds.disk_percent {
            warn!(
                disk = %disk.name,
                mount = %disk.mount_point,
                used_percent = disk.used_percent,
                threshold = config.thresholds.disk_percent,
                "disk threshold exceeded"
            );
        }
    }

    for process in snapshot.processes.values() {
        evaluate_process(process, config);
    }
}

fn evaluate_process(process: &ProcessSnapshot, config: &Config) {
    let cpu_hot = process.cpu_percent >= config.thresholds.process_cpu_percent;
    let mem_hot = process.memory_bytes >= config.thresholds.process_memory_bytes;

    if cpu_hot || mem_hot {
        warn!(
            pid = process.pid,
            name = %process.name,
            cpu_percent = process.cpu_percent,
            memory_bytes = process.memory_bytes,
            "process threshold exceeded"
        );

        if config.actions.kill_process_on_limit && !config.actions.log_only {
            info!(
                pid = process.pid,
                "kill_process_on_limit enabled, but kill not implemented in initial version"
            );
        }
    }
}
