## `src/monitor.rs`

```rust
use crate::{
    metrics::{DiskSnapshot, ProcessSnapshot, SystemSnapshot},
    state::SharedState,
};
use std::{collections::HashMap, time::{SystemTime, UNIX_EPOCH}};
use sysinfo::{Disks, System};
use tracing::debug;

pub struct Monitor {
    system: System,
    disks: Disks,
    state: SharedState,
}

impl Monitor {
    pub fn new(state: SharedState) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let disks = Disks::new_with_refreshed_list();

        Self { system, disks, state }
    }

    pub fn poll(&mut self) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.disks.refresh();

        let cpu_percent = self.system.global_cpu_info().cpu_usage();

        let memory_total = self.system.total_memory();
        let memory_used = self.system.used_memory();
        let memory_percent = if memory_total == 0 {
            0.0
        } else {
            (memory_used as f32 / memory_total as f32) * 100.0
        };

        let disks = self.disks.iter().map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total == 0 {
                0.0
            } else {
                (used as f32 / total as f32) * 100.0
            };

            DiskSnapshot {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space: total,
                available_space: avail,
                used_percent,
            }
        }).collect();

        let processes: HashMap<u32, ProcessSnapshot> = self.system.processes()
            .iter()
            .map(|(pid, p)| {
                ((*pid).as_u32(), ProcessSnapshot {
                    pid: (*pid).as_u32(),
                    name: p.name().to_string(),
                    cpu_percent: p.cpu_usage(),
                    memory_bytes: p.memory(),
                })
            })
            .collect();

        let timestamp_unix_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();

        let snapshot = SystemSnapshot {
            cpu_percent,
            memory_used,
            memory_total,
            memory_percent,
            disks,
            processes,
            timestamp_unix_ms,
        };

        debug!("system snapshot updated");
        self.state.set_snapshot(snapshot);
    }
}
```

