## `src/control.rs`

```rust
use crate::state::SharedState;
use anyhow::Result;
use serde::{Deserialize, Serialize};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
};
use tracing::{error, info};

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
pub enum ControlRequest {
    GetSnapshot,
    Ping,
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum ControlResponse {
    Ok { data: serde_json::Value },
    Error { message: String },
}

pub async fn run_server(socket_path: String, state: SharedState) -> Result<()> {
    let _ = std::fs::remove_file(&socket_path);
    let listener = UnixListener::bind(&socket_path)?;
    info!(socket = %socket_path, "control socket listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!(error = %e, "control client error");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: Result<ControlRequest, _> = serde_json::from_str(&line);
        let resp = match req {
            Ok(ControlRequest::Ping) => ControlResponse::Ok {
                data: serde_json::json!({ "message": "pong" }),
            },
            Ok(ControlRequest::GetSnapshot) => {
                match state.get_snapshot() {
                    Some(snapshot) => ControlResponse::Ok {
                        data: serde_json::to_value(snapshot)?,
                    },
                    None => ControlResponse::Error {
                        message: "no snapshot available yet".into(),
                    },
                }
            }
            Err(e) => ControlResponse::Error {
                message: format!("invalid request: {e}"),
            },
        };

        let encoded = serde_json::to_vec(&resp)?;
        writer.write_all(&encoded).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}
```

