## `src/daemon.rs`

```rust
use crate::{actions, config::Config, control, monitor::Monitor, state::SharedState};
use anyhow::Result;
use tokio::{signal, time::{self, Duration}};
use tracing::info;

pub async fn run(config: Config) -> Result<()> {
    let state = SharedState::new();

    let control_state = state.clone();
    let socket_path = config.daemon.socket_path.clone();
    tokio::spawn(async move {
        if let Err(e) = control::run_server(socket_path, control_state).await {
            tracing::error!(error = %e, "control server stopped");
        }
    });

    let mut monitor = Monitor::new(state.clone());
    let mut interval = time::interval(Duration::from_millis(config.daemon.poll_interval_ms));

    info!("daemon started");

    loop {
        tokio::select! {
            _ = interval.tick() => {
                monitor.poll();
                if let Some(snapshot) = state.get_snapshot() {
                    actions::evaluate(&snapshot, &config);
                }
            }
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    Ok(())
}
