## src/metrics.rs

```rust
use anyhow::Result;
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, MemoryRefreshKind, RefreshKind, System};

#[derive(Debug, Clone)]
pub struct ResourceSnapshot {
    pub cpu_percent: f32,
    pub memory_percent: f32,
    pub disk_percent: f32,
    pub total_memory: u64,
    pub used_memory: u64,
    pub total_disk: u64,
    pub used_disk: u64,
}

pub struct MetricsCollector {
    sys: System,
    disks: Disks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything());

        let mut sys = System::new_with_specifics(refresh);
        sys.refresh_cpu();
        sys.refresh_memory();

        let disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());

        Self { sys, disks }
    }

    pub fn collect(&mut self) -> Result<ResourceSnapshot> {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.disks.refresh(true);

        let cpu_percent = self.sys.global_cpu_info().cpu_usage();

        let total_memory = self.sys.total_memory();
        let used_memory = self.sys.used_memory();
        let memory_percent = if total_memory == 0 {
            0.0
        } else {
            (used_memory as f32 / total_memory as f32) * 100.0
        };

        let mut total_disk = 0u64;
        let mut avail_disk = 0u64;

        for disk in self.disks.list() {
            total_disk += disk.total_space();
            avail_disk += disk.available_space();
        }

        let used_disk = total_disk.saturating_sub(avail_disk);
        let disk_percent = if total_disk == 0 {
            0.0
        } else {
            (used_disk as f32 / total_disk as f32) * 100.0
        };

        Ok(ResourceSnapshot {
            cpu_percent,
            memory_percent,
            disk_percent,
            total_memory,
            used_memory,
            total_disk,
            used_disk,
        })
    }
}
