use crate::config::Config;
use crate::metrics::ResourceSnapshot;

#[derive(Debug, Clone)]
pub enum PolicyEvent {
    CpuHigh(f32),
    MemoryHigh(f32),
    DiskHigh(f32),
}

pub fn evaluate(snapshot: &ResourceSnapshot, config: &Config) -> Vec<PolicyEvent> {
    let mut events = Vec::new();

    if snapshot.cpu_percent >= config.thresholds.cpu_percent {
        events.push(PolicyEvent::CpuHigh(snapshot.cpu_percent));
    }

    if snapshot.memory_percent >= config.thresholds.memory_percent {
        events.push(PolicyEvent::MemoryHigh(snapshot.memory_percent));
    }

    if snapshot.disk_percent >= config.thresholds.disk_percent {
        events.push(PolicyEvent::DiskHigh(snapshot.disk_percent));
    }

    events
}
