## src/actions.rs

```rust
use crate::config::Config;
use crate::policy::PolicyEvent;
use anyhow::{Context, Result};
use std::fs::OpenOptions;
use std::io::Write;
use tracing::{info, warn};

pub async fn execute(event: &PolicyEvent, config: &Config) -> Result<()> {
    match event {
        PolicyEvent::CpuHigh(value) => {
            warn!("CPU threshold exceeded: {:.2}%", value);
        }
        PolicyEvent::MemoryHigh(value) => {
            warn!("Memory threshold exceeded: {:.2}%", value);

            if !config.actions.log_only && config.actions.drop_caches_on_memory_pressure {
                drop_caches().context("failed to drop caches")?;
                info!("Requested kernel cache drop");
            }
        }
        PolicyEvent::DiskHigh(value) => {
            warn!("Disk threshold exceeded: {:.2}%", value);
        }
    }

    Ok(())
}

fn drop_caches() -> Result<()> {
    let mut file = OpenOptions::new()
        .write(true)
        .open("/proc/sys/vm/drop_caches")?;

    file.write_all(b"3\n")?;
    file.flush()?;
    Ok(())
}
```

