## src/daemon.rs

```rust
use crate::actions;
use crate::config::Config;
use crate::metrics::MetricsCollector;
use crate::policy;
use anyhow::Result;
use tokio::signal::unix::{signal, SignalKind};
use tokio::time::{self, Duration};
use tracing::{error, info};

pub struct Daemon {
    config: Config,
    collector: MetricsCollector,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            config,
            collector: MetricsCollector::new(),
        }
    }

    pub async fn run(&mut self) -> Result<()> {
        let mut interval = time::interval(Duration::from_millis(self.config.polling.interval_ms));
        let mut sigterm = signal(SignalKind::terminate())?;
        let mut sigint = signal(SignalKind::interrupt())?;

        info!("daemon started");

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    match self.collector.collect() {
                        Ok(snapshot) => {
                            info!(
                                cpu_percent = snapshot.cpu_percent,
                                memory_percent = snapshot.memory_percent,
                                disk_percent = snapshot.disk_percent,
                                used_memory = snapshot.used_memory,
                                total_memory = snapshot.total_memory,
                                used_disk = snapshot.used_disk,
                                total_disk = snapshot.total_disk,
                                "resource snapshot"
                            );

                            let events = policy::evaluate(&snapshot, &self.config);
                            for event in events {
                                if let Err(err) = actions::execute(&event, &self.config).await {
                                    error!(error = %err, "action execution failed");
                                }
                            }
                        }
                        Err(err) => {
                            error!(error = %err, "metrics collection failed");
                        }
                    }
                }
                _ = sigterm.recv() => {
                    info!("received SIGTERM, shutting down");
                    break;
                }
                _ = sigint.recv() => {
                    info!("received SIGINT, shutting down");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }
}
```

