    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct Snapshot {
    timestamp_unix: u64,
    cpu: CpuStats,
    memory: MemoryStats,
    load_avg: LoadAvgStats,
    disks: Vec<DiskStats>,
    process_count: usize,
}

#[derive(Debug, Clone, Serialize)]
struct LoadAvgStats {
    one: f64,
    five: f64,
    fifteen: f64,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonState {
    latest_snapshot: Snapshot,
    processes: Vec<ProcessInfo>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Ping,
    Stats,
    Processes,
    Kill { pid: i32, signal: i32 },
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok { data: serde_json::Value },
    Error { message: String },
}

#[derive(Debug, Error)]
enum DaemonError {
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),

    #[error("json error: {0}")]
    Json(#[from] serde_json::Error),

    #[error("invalid signal: {0}")]
    InvalidSignal(i32),

    #[error("signal error: {0}")]
    Signal(#[from] nix::Error),
}

type SharedState = Arc<RwLock<DaemonState>>;

#[tokio::main]
async fn main() -> Result<(), DaemonError> {
    init_logging();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)?;
    }

    let initial_state = DaemonState {
        latest_snapshot: empty_snapshot(),
        processes: Vec::new(),
    };

    let state: SharedState = Arc::new(RwLock::new(initial_state));

    let monitor_handle = tokio::spawn(monitor_loop(state.clone()));
    let server_handle = tokio::spawn(server_loop(state.clone()));

    info!("osd started");
    info!("control socket: {}", SOCKET_PATH);

    tokio::select! {
        _ = shutdown_signal() => {
            info!("shutdown signal received");
        }
        res = monitor_handle => {
            match res {
                Ok(Ok(())) => warn!("monitor loop exited unexpectedly"),
                Ok(Err(e)) => error!("monitor loop error: {}", e),
                Err(e) => error!("monitor task join error: {}", e),
            }
        }
        res = server_handle => {
            match res {
                Ok(Ok(())) => warn!("server loop exited unexpectedly"),
                Ok(Err(e)) => error!("server loop error: {}", e),
                Err(e) => error!("server task join error: {}", e),
            }
        }
    }

    info!("shutting down");
    let _ = std::fs::remove_file(SOCKET_PATH);
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG").unwrap_or_else(|_| "info,osd=debug".to_string()),
        )
        .init();
}

fn empty_snapshot() -> Snapshot {
    Snapshot {
        timestamp_unix: 0,
        cpu: CpuStats {
            usage_percent: 0.0,
            core_count: 0,
        },
        memory: MemoryStats {
            total_bytes: 0,
            used_bytes: 0,
            free_bytes: 0,
            available_bytes: 0,
            used_percent: 0.0,
        },
        load_avg: LoadAvgStats {
            one: 0.0,
            five: 0.0,
            fifteen: 0.0,
        },
        disks: Vec::new(),
        process_count: 0,
    }
}

async fn monitor_loop(state: SharedState) -> Result<(), DaemonError> {
    let mut ticker = interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));
    let mut system = System::new_all();

    loop {
        ticker.tick().await;

        system.refresh_cpu_usage();
        system.refresh_memory();
        system.refresh_processes();
        let disks = Disks::new_with_refreshed_list();

        let cpu = CpuStats {
            usage_percent: system.global_cpu_info().cpu_usage(),
            core_count: system.cpus().len(),
        };

        let total_memory = system.total_memory();
        let available_memory = system.available_memory();
        let used_memory = total_memory.saturating_sub(available_memory);
        let free_memory = system.free_memory();

        let memory = MemoryStats {
            total_bytes: total_memory * 1024,
            used_bytes: used_memory * 1024,
            free_bytes: free_memory * 1024,
            available_bytes: available_memory * 1024,
            used_percent: if total_memory == 0 {
                0.0
            } else {
                (used_memory as f32 / total_memory as f32) * 100.0
            },
        };

        let load = System::load_average();
        let load_avg = LoadAvgStats {
            one: load.one,
            five: load.five,
            fifteen: load.fifteen,
        };

        let disk_stats = disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                let used = total.saturating_sub(avail);
                DiskStats {
                    name: d.name().to_string_lossy().to_string(),
                    mount_point: d.mount_point().to_string_lossy().to_string(),
                    total_bytes: total,
                    available_bytes: avail,
                    used_bytes: used,
                    used_percent: if total == 0 {
                        0.0
                    } else {
                        (used as f32 / total as f32) * 100.0
                    },
                }
            })
            .collect::<Vec<_>>();

        let processes = system
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessInfo {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu_percent: proc_.cpu_usage(),
                memory_bytes: proc_.memory() * 1024,
                virtual_memory_bytes: proc_.virtual_memory() * 1024,
                status: format!("{:?}", proc_.status()),
            })
            .collect::<Vec<_>>();

        let snapshot = Snapshot {
            timestamp_unix: now_unix(),
            cpu,
            memory,
            load_avg,
            disks: disk_stats,
            process_count: processes.len(),
        };

        {
            let mut guard = state.write().await;
            guard.latest_snapshot = snapshot;
            guard.processes = processes;
        }
    }
}

async fn server_loop(state: SharedState) -> Result<(), DaemonError> {
    let listener = UnixListener::bind(SOCKET_PATH)?;

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client error: {}", e);
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<(), DaemonError> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Result<Command, _> = serde_json::from_str(&line);

        let response = match cmd {
            Ok(command) => process_command(command, &state).await,
            Err(e) => Response::Error {
                message: format!("invalid command: {}", e),
            },
        };

        let encoded = serde_json::to_string(&response)?;
        writer.write_all(encoded.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn process_command(command: Command, state: &SharedState) -> Response {
    match command {
        Command::Ping => Response::Ok {
            data: serde_json::json!({ "message": "pong" }),
        },
        Command::Stats => {
            let guard = state.read().await;
            Response::Ok {
                data: serde_json::to_value(&guard.latest_snapshot)
                    .unwrap_or_else(|e| serde_json::json!({ "error": e.to_string() })),
            }
        }
        Command::Processes => {
            let guard = state.read().await;
            Response::Ok {
                data: serde_json::to_value(&guard.processes)
                    .unwrap_or_else(|e| serde_json::json!({ "error": e.to_string() })),
            }
        }
        Command::Kill { pid, signal } => match signal_from_i32(signal) {
            Ok(sig) => match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response::Ok {
                    data: serde_json::json!({
                        "pid": pid,
                        "signal": signal,
                        "result": "sent"
                    }),
                },
                Err(e) => Response::Error {
                    message: format!("failed to send signal: {}", e),
                },
            },
            Err(e) => Response::Error {
                message: e.to_string(),
            },
        },
    }
}

fn signal_from_i32(sig: i32) -> Result<Signal, DaemonError> {
    Signal::try_from(sig).map_err(|_| DaemonError::InvalidSignal(sig))
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

async fn shutdown_signal() {
    let mut sigint = signal(SignalKind::interrupt()).expect("failed to install SIGINT handler");
    let mut sigterm = signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");

    tokio::select! {
        _ = sigint.recv() => {}
        _ = sigterm.recv() => {}
    }
}
