```rust
use tokio::process::Command;
use tracing::{info, warn};

use crate::{
    config::Config,
    state::{DaemonState, ResourceSnapshot},
};

pub struct ResourceManager;

impl ResourceManager {
    pub fn new() -> Self {
        Self
    }

    pub async fn evaluate(&self, cfg: &Config, state: &mut DaemonState, snap: &ResourceSnapshot) {
        if snap.cpu_percent >= cfg.thresholds.cpu_percent {
            state.high_cpu_events += 1;
            warn!("high cpu detected: {:.2}%", snap.cpu_percent);
            if let Some(cmd) = &cfg.actions.on_high_cpu {
                self.run_action(cmd).await;
            }
        }

        if snap.memory_percent >= cfg.thresholds.memory_percent {
            state.high_memory_events += 1;
            warn!("high memory detected: {:.2}%", snap.memory_percent);
            if let Some(cmd) = &cfg.actions.on_high_memory {
                self.run_action(cmd).await;
            }
        }

        if snap.load1 >= cfg.thresholds.load1 {
            state.high_load_events += 1;
            warn!("high load detected: {:.2}", snap.load1);
            if let Some(cmd) = &cfg.actions.on_high_load {
                self.run_action(cmd).await;
            }
        }
    }

    async fn run_action(&self, cmd: &str) {
        info!("executing action: {}", cmd);

        let result = Command::new("sh")
            .arg("-c")
            .arg(cmd)
            .output()
            .await;

        match result {
            Ok(output) => {
                if !output.status.success() {
                    warn!(
                        "action failed with status {:?}, stderr={}",
                        output.status.code(),
                        String::from_utf8_lossy(&output.stderr)
                    );
                }
            }
            Err(e) => {
                warn!("failed to execute action: {}", e);
            }
        }
    }
}
