# src/ipc.rs

```rust
use parking_lot::RwLock;
use serde_json::json;
use std::{path::Path, sync::Arc};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
};
use tracing::{error, info};

use crate::{
    config::Config,
    error::{ResourceDError, Result},
    state::DaemonState,
};

pub async fn run_ipc_server(
    socket_path: String,
    state: Arc<RwLock<DaemonState>>,
    config_path: String,
    config: Arc<RwLock<Config>>,
) -> Result<()> {
    if Path::new(&socket_path).exists() {
        let _ = std::fs::remove_file(&socket_path);
    }

    let listener = UnixListener::bind(&socket_path)?;
    info!("ipc server listening on {}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        let config = config.clone();
        let config_path = config_path.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state, config_path, config).await {
                error!("ipc client error: {}", e);
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<RwLock<DaemonState>>,
    config_path: String,
    config: Arc<RwLock<Config>>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    reader.read_line(&mut line).await?;
    let cmd = line.trim();

    match cmd {
        "ping" => {
            writer.write_all(b"{\"status\":\"ok\",\"reply\":\"pong\"}\n").await?;
        }
        "status" => {
            let snapshot = state.read().clone();
            let payload = serde_json::to_vec(&snapshot)?;
            writer.write_all(&payload).await?;
            writer.write_all(b"\n").await?;
        }
        "reload" => {
            let new_cfg = Config::load_from_file(&config_path)?;
            *config.write() = new_cfg;
            let payload = json!({"status":"ok","reply":"reloaded"});
            writer.write_all(payload.to_string().as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        other => {
            return Err(ResourceDError::InvalidCommand(other.to_string()));
        }
    }

    Ok(())
}
