# src/daemon.rs

```rust
use parking_lot::RwLock;
use std::sync::Arc;
use tokio::{
    signal::unix::{signal, SignalKind},
    time::{self, Duration},
};
use tracing::{error, info};

use crate::{
    config::Config,
    error::Result,
    ipc::run_ipc_server,
    manager::ResourceManager,
    monitor::ResourceMonitor,
    state::DaemonState,
};

pub struct Daemon {
    config_path: String,
    config: Arc<RwLock<Config>>,
    state: Arc<RwLock<DaemonState>>,
}

impl Daemon {
    pub fn new(config_path: String, config: Config) -> Self {
        Self {
            config_path,
            config: Arc::new(RwLock::new(config)),
            state: Arc::new(RwLock::new(DaemonState::default())),
        }
    }

    pub async fn run(self) -> Result<()> {
        let ipc_socket_path = self.config.read().daemon.ipc_socket_path.clone();
        let ipc_state = self.state.clone();
        let ipc_config = self.config.clone();
        let ipc_config_path = self.config_path.clone();

        tokio::spawn(async move {
            if let Err(e) =
                run_ipc_server(ipc_socket_path, ipc_state, ipc_config_path, ipc_config).await
            {
                error!("ipc server failed: {}", e);
            }
        });

        let mut monitor = ResourceMonitor::new();
        let manager = ResourceManager::new();

        let poll_ms = self.config.read().daemon.poll_interval_ms;
        let mut interval = time::interval(Duration::from_millis(poll_ms));

        let mut sigterm = signal(SignalKind::terminate())?;
        let mut sigint = signal(SignalKind::interrupt())?;

        info!("daemon started");

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    let snap = monitor.sample();
                    {
                        let mut state = self.state.write();
                        state.last_snapshot = Some(snap.clone());
                    }

                    let cfg = self.config.read().clone();
                    let mut state = self.state.write();
                    manager.evaluate(&cfg, &mut state, &snap).await;
                }
                _ = sigterm.recv() => {
                    info!("received SIGTERM, shutting down");
                    break;
                }
                _ = sigint.recv() => {
                    info!("received SIGINT, shutting down");
                    break;
                }
            }
        }

        Ok(())
    }
}
