use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::signal;
use tokio::sync::broadcast;
use tokio::time;
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    socket_path: String,
    disk_mounts: Vec<String>,
    thresholds: Thresholds,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            socket_path: "/tmp/osd.sock".to_string(),
            disk_mounts: vec!["/".to_string()],
            thresholds: Thresholds {
                cpu_percent: 90.0,
                memory_percent: 90.0,
                load_per_cpu: 2.0,
                disk_percent: 95.0,
            },
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Thresholds {
    cpu_percent: f32,
    memory_percent: f32,
    load_per_cpu: f32,
    disk_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuTimes {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn idle_total(&self) -> u64 {
        self.idle + self.iowait
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct DiskStat {
    mount: String,
    total_bytes: u64,
    free_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct SystemSnapshot {
    timestamp_unix_ms: u128,
    cpu_percent: f32,
    memory_total_kb: u64,
    memory_available_kb: u64,
    memory_used_percent: f32,
    load1: f32,
    load5: f32,
    load15: f32,
    cpu_count: usize,
    disks: Vec<DiskStat>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    GetStatus,
    ReloadConfig,
    KillProcess { pid: i32, signal: Option<i32> },
    RunHook { name: String },
    Ping,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok { message: String },
    Pong,
    Status { snapshot: SystemSnapshot },
    Error { message: String },
}

#[derive(Clone)]
struct SharedState {
    snapshot: Arc<RwLock<SystemSnapshot>>,
    config: Arc<RwLock<Config>>,
}

struct CpuSampler {
    previous: Option<CpuTimes>,
}

impl CpuSampler {
    fn new() -> Self {
        Self { previous: None }
    }

    fn sample(&mut self) -> Result<f32> {
        let current = read_cpu_times()?;
        let cpu = if let Some(prev) = &self.previous {
            let total_delta = current.total().saturating_sub(prev.total());
            let idle_delta = current.idle_total().saturating_sub(prev.idle_total());
            if total_delta == 0 {
                0.0
            } else {
                100.0 * (total_delta - idle_delta) as f32 / total_delta as f32
            }
        } else {
            0.0
        };
        self.previous = Some(current);
        Ok(cpu)
    }
}

fn read_cpu_times() -> Result<CpuTimes> {
    let content = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
    let line = content
        .lines()
        .find(|l| l.starts_with("cpu "))
        .context("missing aggregate cpu line")?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 8 {
        anyhow::bail!("unexpected /proc/stat cpu format");
    }

    Ok(CpuTimes {
        user: parts[1].parse()?,
        nice: parts[2].parse()?,
        system: parts[3].parse()?,
        idle: parts[4].parse()?,
        iowait: parts[5].parse()?,
        irq: parts[6].parse()?,
        softirq: parts[7].parse()?,
        steal: parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0),
    })
}

fn read_meminfo() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
    let mut total_kb = None;
    let mut available_kb = None;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line.split_whitespace().nth(1).and_then(|v| v.parse().ok());
        } else if line.starts_with("MemAvailable:") {
            available_kb = line.split_whitespace().nth(1).and_then(|v| v.parse().ok());
        }
    }

    let total = total_kb.context("MemTotal missing")?;
    let available = available_kb.context("MemAvailable missing")?;
    Ok((total, available))
}

fn read_loadavg() -> Result<(f32, f32, f32)> {
    let content = fs::read_to_string("/proc/loadavg").context("reading /proc/loadavg")?;
    let parts: Vec<&str> = content.split_whitespace().collect();
    if parts.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }
    Ok((parts[0].parse()?, parts[1].parse()?, parts[2].parse()?))
}

fn cpu_count() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
}

fn disk_usage_for_mount(mount: &str) -> Result<DiskStat> {
    let c_path = std::ffi::CString::new(mount)?;
    let mut stat: libc::statvfs = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
    if rc != 0 {
        return Err(io::Error::last_os_error()).context("statvfs failed");
    }

    let total = stat.f_blocks.saturating_mul(stat.f_frsize as u64);
    let free = stat.f_bavail.saturating_mul(stat.f_frsize as u64);
    let used = total.saturating_sub(free);
    let used_percent = if total == 0 {
        0.0
    } else {
        100.0 * used as f32 / total as f32
    };

    Ok(DiskStat {
        mount: mount.to_string(),
        total_bytes: total,
        free_bytes: free,
        used_percent,
    })
}

fn now_unix_ms() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

async fn monitor_loop(state: SharedState, mut shutdown: broadcast::Receiver<()>) {
    let mut cpu_sampler = CpuSampler::new();
    let mut ticker = {
        let cfg = state.config.read().unwrap().clone();
        time::interval(Duration::from_millis(cfg.sample_interval_ms))
    };

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let cfg = state.config.read().unwrap().clone();
                let start = Instant::now();

                let cpu = match cpu_sampler.sample() {
                    Ok(v) => v,
                    Err(e) => {
                        error!("cpu sample error: {e:#}");
                        0.0
                    }
                };

                let (mem_total, mem_avail) = match read_meminfo() {
                    Ok(v) => v,
                    Err(e) => {
                        error!("mem sample error: {e:#}");
                        (0, 0)
                    }
                };

                let mem_used_percent = if mem_total == 0 {
                    0.0
                } else {
                    100.0 * (mem_total.saturating_sub(mem_avail)) as f32 / mem_total as f32
                };

                let (load1, load5, load15) = match read_loadavg() {
                    Ok(v) => v,
                    Err(e) => {
                        error!("load sample error: {e:#}");
                        (0.0, 0.0, 0.0)
                    }
                };

                let mut disks = Vec::with_capacity(cfg.disk_mounts.len());
                for mount in &cfg.disk_mounts {
                    match disk_usage_for_mount(mount) {
                        Ok(d) => disks.push(d),
                        Err(e) => error!("disk sample error for {}: {e:#}", mount),
                    }
                }

                let snapshot = SystemSnapshot {
                    timestamp_unix_ms: now_unix_ms(),
                    cpu_percent: cpu,
                    memory_total_kb: mem_total,
                    memory_available_kb: mem_avail,
                    memory_used_percent: mem_used_percent,
                    load1,
                    load5,
                    load15,
                    cpu_count: cpu_count(),
                    disks,
                };

                {
                    let mut guard = state.snapshot.write().unwrap();
                    *guard = snapshot.clone();
                }

                evaluate_thresholds(&cfg, &snapshot);

                debug!("sampled in {:?}", start.elapsed());
            }
            _ = shutdown.recv() => {
                info!("monitor loop shutting down");
                break;
            }
        }
    }
}

fn evaluate_thresholds(cfg: &Config, snapshot: &SystemSnapshot) {
    if snapshot.cpu_percent >= cfg.thresholds.cpu_percent {
        warn!(
            "cpu threshold exceeded: {:.2}% >= {:.2}%",
            snapshot.cpu_percent, cfg.thresholds.cpu_percent
        );
    }

    if snapshot.memory_used_percent >= cfg.thresholds.memory_percent {
        warn!(
            "memory threshold exceeded: {:.2}% >= {:.2}%",
            snapshot.memory_used_percent, cfg.thresholds.memory_percent
        );
    }

    let per_cpu_load = if snapshot.cpu_count == 0 {
        snapshot.load1
    } else {
        snapshot.load1 / snapshot.cpu_count as f32
    };

    if per_cpu_load >= cfg.thresholds.load_per_cpu {
        warn!(
            "load threshold exceeded: {:.2} per cpu >= {:.2}",
            per_cpu_load, cfg.thresholds.load_per_cpu
        );
    }

    for d in &snapshot.disks {
        if d.used_percent >= cfg.thresholds.disk_percent {
            warn!(
                "disk threshold exceeded on {}: {:.2}% >= {:.2}%",
                d.mount, d.used_percent, cfg.thresholds.disk_percent
            );
        }
    }
}

async fn handle_client(stream: UnixStream, state: SharedState) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let req: Request = serde_json::from_str(line.trim())
        .context("invalid request json")?;

    let resp = process_request(req, &state).await;
    let encoded = serde_json::to_string(&resp)?;
    writer.write_all(encoded.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

async fn process_request(req: Request, state: &SharedState) -> Response {
    match req {
        Request::GetStatus => {
            let snapshot = state.snapshot.read().unwrap().clone();
            Response::Status { snapshot }
        }
        Request::ReloadConfig => {
            let mut cfg = state.config.write().unwrap();
            *cfg = Config::default();
            Response::Ok {
                message: "config reloaded to defaults".to_string(),
            }
        }
        Request::KillProcess { pid, signal } => {
            let sig = Signal::try_from(signal.unwrap_or(libc::SIGTERM)).unwrap_or(Signal::SIGTERM);
            match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response::Ok {
                    message: format!("signal {:?} sent to pid {}", sig, pid),
                },
                Err(e) => Response::Error {
                    message: format!("failed to signal pid {}: {}", pid, e),
                },
            }
        }
        Request::RunHook { name } => {
            info!("hook requested: {}", name);
            Response::Ok {
                message: format!("hook '{}' acknowledged", name),
            }
        }
        Request::Ping => Response::Pong,
    }
}

async fn server_loop(state: SharedState, mut shutdown: broadcast::Receiver<()>) -> Result<()> {
    let socket_path = {
        let cfg = state.config.read().unwrap();
        cfg.socket_path.clone()
    };

    let socket = PathBuf::from(&socket_path);
    if socket.exists() {
        fs::remove_file(&socket).with_context(|| format!("removing stale socket {}", socket_path))?;
    }

    let listener = UnixListener::bind(&socket)
        .with_context(|| format!("binding socket {}", socket_path))?;

    fs::set_permissions(&socket, fs::Permissions::from_mode(0o660))
        .with_context(|| format!("setting permissions on socket {}", socket_path))?;

    info!("control socket listening on {}", socket_path);

    loop {
        tokio::select! {
            accept = listener.accept() => {
                match accept {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, state).await {
                                error!("client handling error: {e:#}");
                            }
                        });
                    }
                    Err(e) => {
                        error!("socket accept error: {}", e);
                    }
                }
            }
            _ = shutdown.recv() => {
                info!("server loop shutting down");
                break;
            }
        }
    }

    if socket.exists() {
        let _ = fs::remove_file(&socket);
    }

    Ok(())
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,osd=debug".to_string()),
        )
        .init();

    let config = Config::default();
    let snapshot = SystemSnapshot::default();

    let state = SharedState {
        snapshot: Arc::new(RwLock::new(snapshot)),
        config: Arc::new(RwLock::new(config)),
    };

    let (shutdown_tx, _) = broadcast::channel(4);

    let monitor_state = state.clone();
    let monitor_shutdown = shutdown_tx.subscribe();
    let monitor_task = tokio::spawn(async move {
        monitor_loop(monitor_state, monitor_shutdown).await;
    });

    let server_state = state.clone();
    let server_shutdown = shutdown_tx.subscribe();
    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state, server_shutdown).await {
            error!("server loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c");
        }
    }

    let _ = shutdown_tx.send(());

    let _ = monitor_task.await;
    let _ = server_task.await;

    info!("daemon exited");
    Ok(())
}
