use anyhow::{Context, Result};
use nix::sys::signal::{kill as nix_kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuRefreshKind, ProcessRefreshKind, RefreshKind, Signal as SysSignal, System};
use thiserror::Error;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::{broadcast, RwLock},
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const MAX_PROCESSES_RETURNED: usize = 256;

#[derive(Debug, Clone, Serialize)]
struct CpuStats {
    usage_percent: f32,
    logical_cores: usize,
}

#[derive(Debug, Clone, Serialize)]
struct MemoryStats {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct DiskStats {
    total_read_bytes: u64,
    total_written_bytes: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp_unix_secs: u64,
    cpu: CpuStats,
    memory: MemoryStats,
    disk: DiskStats,
    process_count: usize,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Default)]
struct DaemonState {
    latest: Option<SystemSnapshot>,
    process_index: HashMap<i32, ProcessInfo>,
}

type SharedState = Arc<RwLock<DaemonState>>;

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Ping,
    Stats,
    Processes {
        limit: Option<usize>,
    },
    Kill {
        pid: i32,
        signal: Option<i32>,
    },
    Shutdown,
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok {
        message: String,
    },
    Pong {
        ts: u64,
    },
    Stats {
        snapshot: Option<SystemSnapshot>,
    },
    Processes {
        processes: Vec<ProcessInfo>,
    },
    Error {
        error: String,
    },
}

#[derive(Debug, Error)]
enum DaemonError {
    #[error("invalid signal: {0}")]
    InvalidSignal(i32),
}

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket at {}", SOCKET_PATH))?;
    }

    let state: SharedState = Arc::new(RwLock::new(DaemonState::default()));
    let (shutdown_tx, _) = broadcast::channel::<()>(16);

    let monitor_handle = {
        let state = Arc::clone(&state);
        let shutdown_rx = shutdown_tx.subscribe();
        tokio::spawn(async move {
            if let Err(e) = monitor_loop(state, shutdown_rx).await {
                error!("monitor loop failed: {e:#}");
            }
        })
    };

    let server_handle = {
        let state = Arc::clone(&state);
        let shutdown_rx = shutdown_tx.subscribe();
        tokio::spawn(async move {
            if let Err(e) = server_loop(state, shutdown_tx.clone(), shutdown_rx).await {
                error!("server loop failed: {e:#}");
            }
        })
    };

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received ctrl-c");
        }
        _ = monitor_handle => {
            warn!("monitor task exited");
        }
        _ = server_handle => {
            warn!("server task exited");
        }
    }

    let _ = shutdown_tx.send(());
    time::sleep(Duration::from_millis(200)).await;

    if Path::new(SOCKET_PATH).exists() {
        if let Err(e) = std::fs::remove_file(SOCKET_PATH) {
            warn!("failed to remove socket file: {e}");
        }
    }

    info!("daemon stopped");
    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,osd=debug".to_string()),
        )
        .init();
}

async fn monitor_loop(
    state: SharedState,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything()),
    );

    let mut prev_disk_read = 0u64;
    let mut prev_disk_written = 0u64;
    let mut interval = time::interval(SAMPLE_INTERVAL);

    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("monitor loop shutting down");
                break;
            }
            _ = interval.tick() => {
                sys.refresh_cpu();
                sys.refresh_memory();
                sys.refresh_processes();

                let cpu_usage = sys.global_cpu_info().cpu_usage();
                let logical_cores = sys.cpus().len();

                let total_mem = sys.total_memory() * 1024;
                let used_mem = sys.used_memory() * 1024;
                let free_mem = sys.free_memory() * 1024;
                let avail_mem = sys.available_memory() * 1024;
                let used_percent = if total_mem > 0 {
                    (used_mem as f32 / total_mem as f32) * 100.0
                } else {
                    0.0
                };

                let mut processes: Vec<ProcessInfo> = sys
                    .processes()
                    .iter()
                    .map(|(pid, p)| ProcessInfo {
                        pid: pid.as_u32() as i32,
                        name: p.name().to_string(),
                        cpu_percent: p.cpu_usage(),
                        memory_bytes: p.memory() * 1024,
                        virtual_memory_bytes: p.virtual_memory() * 1024,
                        status: format!("{:?}", p.status()),
                    })
                    .collect();

                processes.sort_by(|a, b| {
                    b.cpu_percent
                        .partial_cmp(&a.cpu_percent)
                        .unwrap_or(std::cmp::Ordering::Equal)
                });

                let process_index = processes
                    .iter()
                    .cloned()
                    .map(|p| (p.pid, p))
                    .collect::<HashMap<_, _>>();

                let total_read_bytes = prev_disk_read;
                let total_written_bytes = prev_disk_written;

                let snapshot = SystemSnapshot {
                    timestamp_unix_secs: now_unix_secs(),
                    cpu: CpuStats {
                        usage_percent: cpu_usage,
                        logical_cores,
                    },
                    memory: MemoryStats {
                        total_bytes: total_mem,
                        used_bytes: used_mem,
                        free_bytes: free_mem,
                        available_bytes: avail_mem,
                        used_percent,
                    },
                    disk: DiskStats {
                        total_read_bytes,
                        total_written_bytes,
                    },
                    process_count: processes.len(),
                    top_processes: processes.into_iter().take(16).collect(),
                };

                let mut guard = state.write().await;
                guard.latest = Some(snapshot);
                guard.process_index = process_index;
            }
        }
    }

    Ok(())
}

async fn server_loop(
    state: SharedState,
    shutdown_tx: broadcast::Sender<()>,
    mut shutdown_rx: broadcast::Receiver<()>,
) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;
    info!("listening on {}", SOCKET_PATH);

    loop {
        tokio::select! {
            _ = shutdown_rx.recv() => {
                info!("server loop shutting down");
                break;
            }
            accept_result = listener.accept() => {
                let (stream, _) = accept_result?;
                let state = Arc::clone(&state);
                let shutdown_tx = shutdown_tx.clone();

                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, state, shutdown_tx).await {
                        warn!("client handler error: {e:#}");
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    state: SharedState,
    shutdown_tx: broadcast::Sender<()>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::with_capacity(1024);

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let req: Request = match serde_json::from_str(line.trim()) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response::Error {
                    error: format!("invalid request: {e}"),
                };
                write_response(&mut writer, &resp).await?;
                continue;
            }
        };

        let resp = process_request(req, &state, &shutdown_tx).await;
        write_response(&mut writer, &resp).await?;
    }

    Ok(())
}

async fn process_request(
    req: Request,
    state: &SharedState,
    shutdown_tx: &broadcast::Sender<()>,
) -> Response {
    match req {
        Request::Ping => Response::Pong {
            ts: now_unix_secs(),
        },
        Request::Stats => {
            let guard = state.read().await;
            Response::Stats {
                snapshot: guard.latest.clone(),
            }
        }
        Request::Processes { limit } => {
            let guard = state.read().await;
            let mut processes: Vec<_> = guard.process_index.values().cloned().collect();
            processes.sort_by(|a, b| {
                b.cpu_percent
                    .partial_cmp(&a.cpu_percent)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
            processes.truncate(limit.unwrap_or(MAX_PROCESSES_RETURNED).min(MAX_PROCESSES_RETURNED));
            Response::Processes { processes }
        }
        Request::Kill { pid, signal } => {
            match kill_process(pid, signal.unwrap_or(15)) {
                Ok(()) => Response::Ok {
                    message: format!("signal sent to pid {}", pid),
                },
                Err(e) => Response::Error {
                    error: e.to_string(),
                },
            }
        }
        Request::Shutdown => {
            let _ = shutdown_tx.send(());
            Response::Ok {
                message: "shutdown initiated".to_string(),
            }
        }
    }
}

fn kill_process(pid: i32, signal_num: i32) -> Result<()> {
    let sig = signal_from_i32(signal_num)?;
    nix_kill(Pid::from_raw(pid), sig).with_context(|| format!("failed to signal pid {}", pid))?;
    Ok(())
}

fn signal_from_i32(sig: i32) -> Result<Signal> {
    Signal::try_from(sig).map_err(|_| DaemonError::InvalidSignal(sig).into())
}

async fn write_response<W: AsyncWriteExt + Unpin>(writer: &mut W, resp: &Response) -> Result<()> {
    let s = serde_json::to_string(resp)?;
    writer.write_all(s.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

fn now_unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
