use serde::{Deserialize, Serialize};
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, RwLock,
};
use std::thread;
use std::time::{Duration, Instant};

const SOCKET_PATH: &str = "/tmp/os-resource-daemon.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct CpuUsage {
    total_percent: f64,
    user_percent: f64,
    system_percent: f64,
    idle_percent: f64,
    iowait_percent: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct MemoryStats {
    total_kb: u64,
    free_kb: u64,
    available_kb: u64,
    buffers_kb: u64,
    cached_kb: u64,
    used_kb: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct LoadAvg {
    one: f64,
    five: f64,
    fifteen: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct DiskStats {
    path: String,
    total_bytes: u64,
    free_bytes: u64,
    avail_bytes: u64,
    used_bytes: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct MetricsSnapshot {
    timestamp_unix_secs: u64,
    uptime_secs: u64,
    cpu: CpuUsage,
    memory: MemoryStats,
    load: LoadAvg,
    disk: DiskStats,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    GetMetrics,
    Cleanup,
    Shutdown,
    Ping,
}

#[derive(Debug, Serialize, Deserialize)]
struct ControlResponse {
    ok: bool,
    message: String,
    metrics: Option<MetricsSnapshot>,
}

struct DaemonState {
    metrics: RwLock<MetricsSnapshot>,
    running: AtomicBool,
    started_at: Instant,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    install_signal_handlers();

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let state = Arc::new(DaemonState {
        metrics: RwLock::new(MetricsSnapshot::default()),
        running: AtomicBool::new(true),
        started_at: Instant::now(),
    });

    let monitor_state = Arc::clone(&state);
    let monitor_thread = thread::spawn(move || monitor_loop(monitor_state, "/"));

    let control_state = Arc::clone(&state);
    let control_thread = thread::spawn(move || control_loop(control_state));

    while state.running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_millis(250));
    }

    let _ = monitor_thread.join();
    let _ = control_thread.join();

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn monitor_loop(state: Arc<DaemonState>, disk_path: &str) {
    let mut prev_cpu = read_cpu_times().unwrap_or_default();

    while state.running.load(Ordering::Relaxed) {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        let cpu_now = read_cpu_times().unwrap_or_default();
        let cpu_usage = compute_cpu_usage(&prev_cpu, &cpu_now);
        prev_cpu = cpu_now;

        let memory = read_memory_stats().unwrap_or_default();
        let load = read_loadavg().unwrap_or_default();
        let disk = read_disk_stats(disk_path).unwrap_or_else(|_| DiskStats {
            path: disk_path.to_string(),
            ..Default::default()
        });

        let snapshot = MetricsSnapshot {
            timestamp_unix_secs: now,
            uptime_secs: state.started_at.elapsed().as_secs(),
            cpu: cpu_usage,
            memory,
            load,
            disk,
        };

        if let Ok(mut guard) = state.metrics.write() {
            *guard = snapshot;
        }

        thread::sleep(SAMPLE_INTERVAL);
    }
}

fn control_loop(state: Arc<DaemonState>) {
    let listener = match UnixListener::bind(SOCKET_PATH) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("failed to bind control socket {}: {}", SOCKET_PATH, e);
            state.running.store(false, Ordering::Relaxed);
            return;
        }
    };

    let _ = fs::set_permissions(SOCKET_PATH, std::os::unix::fs::PermissionsExt::from_mode(0o660));

    for stream in listener.incoming() {
        if !state.running.load(Ordering::Relaxed) {
            break;
        }

        match stream {
            Ok(stream) => {
                let state = Arc::clone(&state);
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, state) {
                        eprintln!("client handling error: {}", e);
                    }
                });
            }
            Err(e) => {
                eprintln!("socket accept error: {}", e);
                thread::sleep(Duration::from_millis(100));
            }
        }
    }
}

fn handle_client(
    mut stream: UnixStream,
    state: Arc<DaemonState>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut input = String::new();
    reader.read_line(&mut input)?;

    let cmd: ControlCommand = serde_json::from_str(input.trim())?;

    let response = match cmd {
        ControlCommand::GetMetrics => {
            let metrics = state.metrics.read().ok().map(|g| g.clone());
            ControlResponse {
                ok: true,
                message: "metrics retrieved".to_string(),
                metrics,
            }
        }
        ControlCommand::Cleanup => {
            perform_cleanup();
            ControlResponse {
                ok: true,
                message: "cleanup completed".to_string(),
                metrics: None,
            }
        }
        ControlCommand::Shutdown => {
            state.running.store(false, Ordering::Relaxed);
            ControlResponse {
                ok: true,
                message: "shutdown initiated".to_string(),
                metrics: None,
            }
        }
        ControlCommand::Ping => ControlResponse {
            ok: true,
            message: "pong".to_string(),
            metrics: None,
        },
    };

    let encoded = serde_json::to_string(&response)?;
    stream.write_all(encoded.as_bytes())?;
    stream.write_all(b"\n")?;
    stream.flush()?;

    Ok(())
}

fn perform_cleanup() {
    // Placeholder for cleanup hooks:
    // - rotate internal buffers
    // - compact caches
    // - release temporary resources
    // - trigger subordinate subsystem maintenance
}

fn read_cpu_times() -> Result<CpuTimes, Box<dyn std::error::Error>> {
    let content = fs::read_to_string("/proc/stat")?;
    let line = content
        .lines()
        .find(|l| l.starts_with("cpu "))
        .ok_or("missing cpu line in /proc/stat")?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 8 {
        return Err("invalid cpu line".into());
    }

    Ok(CpuTimes {
        user: parts[1].parse()?,
        nice: parts[2].parse()?,
        system: parts[3].parse()?,
        idle: parts[4].parse()?,
        iowait: parts.get(5).unwrap_or(&"0").parse()?,
        irq: parts.get(6).unwrap_or(&"0").parse()?,
        softirq: parts.get(7).unwrap_or(&"0").parse()?,
        steal: parts.get(8).unwrap_or(&"0").parse()?,
    })
}

fn compute_cpu_usage(prev: &CpuTimes, curr: &CpuTimes) -> CpuUsage {
    let prev_idle = prev.idle + prev.iowait;
    let curr_idle = curr.idle + curr.iowait;

    let prev_non_idle =
        prev.user + prev.nice + prev.system + prev.irq + prev.softirq + prev.steal;
    let curr_non_idle =
        curr.user + curr.nice + curr.system + curr.irq + curr.softirq + curr.steal;

    let prev_total = prev_idle + prev_non_idle;
    let curr_total = curr_idle + curr_non_idle;

    let totald = curr_total.saturating_sub(prev_total) as f64;
    let idled = curr_idle.saturating_sub(prev_idle) as f64;

    if totald <= 0.0 {
        return CpuUsage::default();
    }

    let userd = curr.user.saturating_sub(prev.user) as f64;
    let systemd = curr.system.saturating_sub(prev.system) as f64;
    let iowaitd = curr.iowait.saturating_sub(prev.iowait) as f64;

    CpuUsage {
        total_percent: ((totald - idled) / totald) * 100.0,
        user_percent: (userd / totald) * 100.0,
        system_percent: (systemd / totald) * 100.0,
        idle_percent: (idled / totald) * 100.0,
        iowait_percent: (iowaitd / totald) * 100.0,
    }
}

fn read_memory_stats() -> Result<MemoryStats, Box<dyn std::error::Error>> {
    let content = fs::read_to_string("/proc/meminfo")?;

    let mut total = 0;
    let mut free = 0;
    let mut available = 0;
    let mut buffers = 0;
    let mut cached = 0;

    for line in content.lines() {
        let mut parts = line.split_whitespace();
        match parts.next() {
            Some("MemTotal:") => total = parts.next().unwrap_or("0").parse()?,
            Some("MemFree:") => free = parts.next().unwrap_or("0").parse()?,
            Some("MemAvailable:") => available = parts.next().unwrap_or("0").parse()?,
            Some("Buffers:") => buffers = parts.next().unwrap_or("0").parse()?,
            Some("Cached:") => cached = parts.next().unwrap_or("0").parse()?,
            _ => {}
        }
    }

    let used = total.saturating_sub(available);
    let used_percent = if total > 0 {
        (used as f64 / total as f64) * 100.0
    } else {
        0.0
    };

    Ok(MemoryStats {
        total_kb: total,
        free_kb: free,
        available_kb: available,
        buffers_kb: buffers,
        cached_kb: cached,
        used_kb: used,
        used_percent,
    })
}

fn read_loadavg() -> Result<LoadAvg, Box<dyn std::error::Error>> {
    let content = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = content.split_whitespace().collect();
    if parts.len() < 3 {
        return Err("invalid /proc/loadavg".into());
    }

    Ok(LoadAvg {
        one: parts[0].parse()?,
        five: parts[1].parse()?,
        fifteen: parts[2].parse()?,
    })
}

fn read_disk_stats(path: &str) -> Result<DiskStats, Box<dyn std::error::Error>> {
    let c_path = std::ffi::CString::new(path)?;
    let mut stat: libc::statvfs = unsafe { std::mem::zeroed() };

    let rc = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error().into());
    }

    let total = stat.f_blocks as u64 * stat.f_frsize as u64;
    let free = stat.f_bfree as u64 * stat.f_frsize as u64;
    let avail = stat.f_bavail as u64 * stat.f_frsize as u64;
    let used = total.saturating_sub(free);
    let used_percent = if total > 0 {
        (used as f64 / total as f64) * 100.0
    } else {
        0.0
    };

    Ok(DiskStats {
        path: path.to_string(),
        total_bytes: total,
        free_bytes: free,
        avail_bytes: avail,
        used_bytes: used,
        used_percent,
    })
}

fn install_signal_handlers() {
    unsafe {
        libc::signal(libc::SIGPIPE, libc::SIG_IGN);
    }
}
