use anyhow::{anyhow, Result};

pub fn kill_process(pid: i32) -> Result<()> {
    #[cfg(unix)]
    {
        let rc = unsafe { libc::kill(pid, libc::SIGTERM) };
        if rc != 0 {
            return Err(anyhow!(std::io::Error::last_os_error()));
        }
        Ok(())
    }

    #[cfg(not(unix))]
    {
        let _ = pid;
        Err(anyhow!("kill_process is only supported on Unix"))
    }
}

pub fn renice_process(pid: i32, priority: i32) -> Result<()> {
    #[cfg(unix)]
    {
        let rc = unsafe { libc::setpriority(libc::PRIO_PROCESS, pid as u32, priority) };
        if rc != 0 {
            return Err(anyhow!(std::io::Error::last_os_error()));
        }
        Ok(())
    }

    #[cfg(not(unix))]
    {
        let _ = (pid, priority);
        Err(anyhow!("renice_process is only supported on Unix"))
    }
}
