# src/monitor.rs

```rust
use std::{
    cmp::Ordering,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use tokio::sync::RwLock;
use tokio::time::interval;

use sysinfo::{Disks, System};

use crate::models::{CpuInfo, DiskInfo, MemoryInfo, ProcessInfo, SystemSnapshot};

pub type SharedSnapshot = Arc<RwLock<SystemSnapshot>>;

pub struct MonitorConfig {
    pub sample_interval: Duration,
    pub top_n_processes: usize,
}

pub struct ResourceMonitor {
    config: MonitorConfig,
    state: SharedSnapshot,
}

impl ResourceMonitor {
    pub fn new(config: MonitorConfig, state: SharedSnapshot) -> Self {
        Self { config, state }
    }

    pub async fn run(self) {
        let mut sys = System::new_all();
        let mut disks = Disks::new_with_refreshed_list();
        let mut ticker = interval(self.config.sample_interval);

        loop {
            ticker.tick().await;

            sys.refresh_cpu_usage();
            sys.refresh_memory();
            sys.refresh_processes();
            disks.refresh();

            let cpu = CpuInfo {
                usage_percent: sys.global_cpu_info().cpu_usage(),
                core_count: sys.cpus().len(),
            };

            let total_mem = sys.total_memory();
            let used_mem = sys.used_memory();
            let free_mem = sys.free_memory();
            let avail_mem = sys.available_memory();

            let memory = MemoryInfo {
                total_bytes: total_mem * 1024,
                used_bytes: used_mem * 1024,
                free_bytes: free_mem * 1024,
                available_bytes: avail_mem * 1024,
                used_percent: if total_mem > 0 {
                    (used_mem as f32 / total_mem as f32) * 100.0
                } else {
                    0.0
                },
            };

            let disk_infos = disks
                .list()
                .iter()
                .map(|d| {
                    let total = d.total_space();
                    let avail = d.available_space();
                    let used = total.saturating_sub(avail);
                    DiskInfo {
                        name: d.name().to_string_lossy().to_string(),
                        mount_point: d.mount_point().to_string_lossy().to_string(),
                        total_bytes: total,
                        available_bytes: avail,
                        used_bytes: used,
                        used_percent: if total > 0 {
                            (used as f32 / total as f32) * 100.0
                        } else {
                            0.0
                        },
                    }
                })
                .collect::<Vec<_>>();

            let mut processes = sys
                .processes()
                .iter()
                .map(|(pid, p)| ProcessInfo {
                    pid: pid.as_u32() as i32,
                    name: p.name().to_string(),
                    cpu_percent: p.cpu_usage(),
                    memory_bytes: p.memory() * 1024,
                    virtual_memory_bytes: p.virtual_memory() * 1024,
                    status: format!("{:?}", p.status()),
                })
                .collect::<Vec<_>>();

            processes.sort_by(|a, b| {
                b.cpu_percent
                    .partial_cmp(&a.cpu_percent)
                    .unwrap_or(Ordering::Equal)
                    .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
            });

            processes.truncate(self.config.top_n_processes);

            let snapshot = SystemSnapshot {
                timestamp_unix_secs: SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs(),
                cpu,
                memory,
                disks: disk_infos,
                top_processes: processes,
            };

            let mut guard = self.state.write().await;
            *guard = snapshot;
        }
    }
}

pub fn initial_snapshot() -> SystemSnapshot {
    SystemSnapshot {
        timestamp_unix_secs: 0,
        cpu: CpuInfo {
            usage_percent: 0.0,
            core_count: 0,
        },
        memory: MemoryInfo {
            total_bytes: 0,
            used_bytes: 0,
            free_bytes: 0,
            available_bytes: 0,
            used_percent: 0.0,
        },
        disks: Vec::new(),
        top_processes: Vec::new(),
    }
}
