# src/control.rs

```rust
use std::path::Path;
use std::sync::Arc;

use anyhow::Result;
use serde_json::json;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tracing::{error, info};

use crate::actions::{kill_process, renice_process};
use crate::models::{ControlCommand, ControlResponse, SystemSnapshot};

pub type SharedSnapshot = Arc<RwLock<SystemSnapshot>>;

pub struct ControlServer {
    socket_path: String,
    state: SharedSnapshot,
}

impl ControlServer {
    pub fn new(socket_path: impl Into<String>, state: SharedSnapshot) -> Self {
        Self {
            socket_path: socket_path.into(),
            state,
        }
    }

    pub async fn run(self) -> Result<()> {
        if Path::new(&self.socket_path).exists() {
            let _ = std::fs::remove_file(&self.socket_path);
        }

        let listener = UnixListener::bind(&self.socket_path)?;
        info!("control socket listening on {}", self.socket_path);

        loop {
            let (stream, _) = listener.accept().await?;
            let state = self.state.clone();
            tokio::spawn(async move {
                if let Err(e) = handle_client(stream, state).await {
                    error!("client handling error: {e:#}");
                }
            });
        }
    }
}

async fn handle_client(stream: UnixStream, state: SharedSnapshot) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let bytes = reader.read_line(&mut line).await?;
    if bytes == 0 {
        return Ok(());
    }

    let response = match serde_json::from_str::<ControlCommand>(&line) {
        Ok(ControlCommand::GetStatus) => {
            let snapshot = state.read().await.clone();
            ControlResponse::Ok {
                data: serde_json::to_value(snapshot)?,
            }
        }
        Ok(ControlCommand::KillProcess { pid }) => match kill_process(pid) {
            Ok(_) => ControlResponse::Ok {
                data: json!({ "message": "process terminated", "pid": pid }),
            },
            Err(e) => ControlResponse::Error {
                message: format!("kill failed: {e}"),
            },
        },
        Ok(ControlCommand::ReniceProcess { pid, priority }) => match renice_process(pid, priority)
        {
            Ok(_) => ControlResponse::Ok {
                data: json!({
                    "message": "priority changed",
                    "pid": pid,
                    "priority": priority
                }),
            },
            Err(e) => ControlResponse::Error {
                message: format!("renice failed: {e}"),
            },
        },
        Err(e) => ControlResponse::Error {
            message: format!("invalid command: {e}"),
        },
    };

    let encoded = serde_json::to_vec(&response)?;
    writer.write_all(&encoded).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}
```

