# src/daemon.rs

```rust
use std::sync::Arc;
use std::time::Duration;

use anyhow::Result;
use tokio::sync::RwLock;
use tracing::info;

use crate::control::ControlServer;
use crate::monitor::{initial_snapshot, MonitorConfig, ResourceMonitor};

pub struct DaemonConfig {
    pub socket_path: String,
    pub sample_interval: Duration,
    pub top_n_processes: usize,
}

pub async fn run_daemon(config: DaemonConfig) -> Result<()> {
    let shared_state = Arc::new(RwLock::new(initial_snapshot()));

    let monitor = ResourceMonitor::new(
        MonitorConfig {
            sample_interval: config.sample_interval,
            top_n_processes: config.top_n_processes,
        },
        shared_state.clone(),
    );

    let control = ControlServer::new(config.socket_path.clone(), shared_state);

    let monitor_task = tokio::spawn(async move {
        monitor.run().await;
    });

    let control_task = tokio::spawn(async move { control.run().await });

    info!("daemon started");

    tokio::select! {
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = control_task => {
            match res {
                Ok(Ok(())) => info!("control server exited"),
                Ok(Err(e)) => return Err(e),
                Err(e) => return Err(e.into()),
            }
        }
    }

    monitor_task.abort();
    Ok(())
}
