        cpu_usage_percent: f32,
        memory_used_bytes: u64,
        memory_total_bytes: u64,
        swap_used_bytes: u64,
        swap_total_bytes: u64,
        load_avg_one: f64,
        load_avg_five: f64,
        load_avg_fifteen: f64,
        disk_total_bytes: u64,
        disk_available_bytes: u64,
        process_count: usize,
    ) -> Self {
        let timestamp_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();

        let memory_usage_percent = if memory_total_bytes > 0 {
            (memory_used_bytes as f32 / memory_total_bytes as f32) * 100.0
        } else {
            0.0
        };

        let disk_used_percent = if disk_total_bytes > 0 {
            ((disk_total_bytes - disk_available_bytes) as f32 / disk_total_bytes as f32) * 100.0
        } else {
            0.0
        };

        Self {
            timestamp_ms,
            cpu_usage_percent,
            memory_used_bytes,
            memory_total_bytes,
            memory_usage_percent,
            swap_used_bytes,
            swap_total_bytes,
            load_avg_one,
            load_avg_five,
            load_avg_fifteen,
            disk_total_bytes,
            disk_available_bytes,
            disk_used_percent,
            process_count,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct DaemonStatus {
    pub running: bool,
    pub last_snapshot: Option<ResourceSnapshot>,
    pub last_action: Option<String>,
    pub iteration: u64,
}
