# src/collector.rs

```rust
use crate::types::ResourceSnapshot;
use anyhow::{anyhow, Result};
use sysinfo::{Disks, LoadAvg, System};

pub struct Collector {
    sys: System,
    disks: Disks,
    managed_mount_path: String,
}

impl Collector {
    pub fn new(managed_mount_path: String) -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();

        let disks = Disks::new_with_refreshed_list();

        Self {
            sys,
            disks,
            managed_mount_path,
        }
    }

    pub fn collect(&mut self) -> Result<ResourceSnapshot> {
        self.sys.refresh_cpu_usage();
        self.sys.refresh_memory();
        self.sys.refresh_processes();
        self.disks.refresh();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();

        let total_mem = self.sys.total_memory();
        let used_mem = self.sys.used_memory();

        let total_swap = self.sys.total_swap();
        let used_swap = self.sys.used_swap();

        let LoadAvg { one, five, fifteen } = System::load_average();

        let mut disk_total = 0u64;
        let mut disk_available = 0u64;
        let target = std::path::Path::new(&self.managed_mount_path);

        for disk in self.disks.list() {
            if disk.mount_point() == target {
                disk_total = disk.total_space();
                disk_available = disk.available_space();
                break;
            }
        }

        if disk_total == 0 && self.managed_mount_path == "/" {
            if let Some(disk) = self.disks.list().first() {
                disk_total = disk.total_space();
                disk_available = disk.available_space();
            }
        }

        if disk_total == 0 {
            return Err(anyhow!(
                "no disk found for managed mount path: {}",
                self.managed_mount_path
            ));
        }

        let process_count = self.sys.processes().len();

        Ok(ResourceSnapshot::now(
            cpu_usage,
            used_mem,
            total_mem,
            used_swap,
            total_swap,
            one,
            five,
            fifteen,
            disk_total,
            disk_available,
            process_count,
        ))
    }
}
