use crate::config::Thresholds;
use crate::types::ResourceSnapshot;

#[derive(Debug, Clone)]
pub enum Action {
    None,
    LogHighCpu,
    LogHighMemory,
    LogHighDisk,
    LogHighLoad,
}

pub struct PolicyEngine {
    thresholds: Thresholds,
}

impl PolicyEngine {
    pub fn new(thresholds: Thresholds) -> Self {
        Self { thresholds }
    }

    pub fn evaluate(&self, snapshot: &ResourceSnapshot) -> Action {
        if snapshot.disk_used_percent >= self.thresholds.disk_percent {
            return Action::LogHighDisk;
        }

        if snapshot.memory_usage_percent >= self.thresholds.memory_percent {
            return Action::LogHighMemory;
        }

        if snapshot.cpu_usage_percent >= self.thresholds.cpu_percent {
            return Action::LogHighCpu;
        }

        if snapshot.load_avg_one >= self.thresholds.load_one {
            return Action::LogHighLoad;
        }

        Action::None
    }
}
