# src/daemon.rs

```rust
use crate::collector::Collector;
use crate::config::Config;
use crate::manager::ResourceManager;
use crate::policy::PolicyEngine;
use crate::server::SharedStatus;
use crate::types::DaemonStatus;
use anyhow::Result;
use tokio::time;
use tracing::{error, info};

pub struct Daemon {
    config: Config,
    collector: Collector,
    policy: PolicyEngine,
    manager: ResourceManager,
    status: SharedStatus,
}

impl Daemon {
    pub fn new(config: Config, status: SharedStatus) -> Self {
        let collector = Collector::new(config.managed_mount_path.clone());
        let policy = PolicyEngine::new(config.thresholds.clone());
        let manager = ResourceManager::new();

        Self {
            config,
            collector,
            policy,
            manager,
            status,
        }
    }

    pub async fn run(mut self) -> Result<()> {
        self.manager.startup().await?;

        {
            let mut s = self.status.write();
            s.running = true;
        }

        let mut ticker = time::interval(self.config.sample_interval);

        loop {
            tokio::select! {
                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
                _ = ticker.tick() => {
                    if let Err(err) = self.tick().await {
                        error!("daemon tick failed: {err:#}");
                    }
                }
            }
        }

        self.manager.shutdown().await?;

        {
            let mut s = self.status.write();
            s.running = false;
        }

        Ok(())
    }

    async fn tick(&mut self) -> Result<()> {
        let snapshot = self.collector.collect()?;
        let action = self.policy.evaluate(&snapshot);
        let action_result = self.manager.apply(&action, &snapshot).await?;

        {
            let mut s = self.status.write();
            s.iteration += 1;
            s.last_snapshot = Some(snapshot);
            s.last_action = action_result;
        }

        Ok(())
    }
}
