use libc::statvfs;
use nix::sys::signal::{self, SigSet, Signal};
use serde::Serialize;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, RwLock,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Debug, Clone, Serialize, Default)]
struct CpuStats {
    usage_percent: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct MemStats {
    total_kb: u64,
    available_kb: u64,
    used_kb: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct DiskStats {
    path: String,
    total_bytes: u64,
    free_bytes: u64,
    used_bytes: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct LoadStats {
    one: f64,
    five: f64,
    fifteen: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct ResourceSnapshot {
    timestamp: u64,
    cpu: CpuStats,
    memory: MemStats,
    disk: DiskStats,
    load: LoadStats,
    process_count: usize,
}

#[derive(Debug, Clone, Default)]
struct CpuTimes {
    total: u64,
    idle: u64,
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn read_to_string(path: &str) -> std::io::Result<String> {
    let mut s = String::new();
    File::open(path)?.read_to_string(&mut s)?;
    Ok(s)
}

fn read_cpu_times() -> std::io::Result<CpuTimes> {
    let content = read_to_string("/proc/stat")?;
    let first = content
        .lines()
        .next()
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::Other, "missing /proc/stat line"))?;

    let mut parts = first.split_whitespace();
    let label = parts.next().unwrap_or("");
    if label != "cpu" {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "invalid cpu line in /proc/stat",
        ));
    }

    let values: Vec<u64> = parts.filter_map(|p| p.parse::<u64>().ok()).collect();
    if values.len() < 4 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "not enough cpu fields",
        ));
    }

    let idle = values[3] + values.get(4).copied().unwrap_or(0);
    let total = values.iter().sum();

    Ok(CpuTimes { total, idle })
}

fn compute_cpu_usage(prev: &CpuTimes, curr: &CpuTimes) -> f64 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    let busy = total_delta.saturating_sub(idle_delta);
    (busy as f64 / total_delta as f64) * 100.0
}

fn read_mem_stats() -> std::io::Result<MemStats> {
    let content = read_to_string("/proc/meminfo")?;
    let mut total_kb = 0_u64;
    let mut available_kb = 0_u64;

    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("MemTotal:") {
            total_kb = rest
                .split_whitespace()
                .next()
                .and_then(|v| v.parse().ok())
                .unwrap_or(0);
        } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
            available_kb = rest
                .split_whitespace()
                .next()
                .and_then(|v| v.parse().ok())
                .unwrap_or(0);
        }
    }

    let used_kb = total_kb.saturating_sub(available_kb);
    let used_percent = if total_kb == 0 {
        0.0
    } else {
        (used_kb as f64 / total_kb as f64) * 100.0
    };

    Ok(MemStats {
        total_kb,
        available_kb,
        used_kb,
        used_percent,
    })
}

fn read_load_stats() -> std::io::Result<LoadStats> {
    let content = read_to_string("/proc/loadavg")?;
    let mut parts = content.split_whitespace();

    let one = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0.0);
    let five = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0.0);
    let fifteen = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0.0);

    Ok(LoadStats { one, five, fifteen })
}

fn read_disk_stats(path: &str) -> std::io::Result<DiskStats> {
    use std::ffi::CString;
    use std::mem::MaybeUninit;

    let c_path = CString::new(path).map_err(|_| {
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "invalid path for statvfs")
    })?;

    let mut stat = MaybeUninit::<libc::statvfs>::uninit();
    let rc = unsafe { statvfs(c_path.as_ptr(), stat.as_mut_ptr()) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error());
    }

    let stat = unsafe { stat.assume_init() };

    let total_bytes = stat.f_blocks.saturating_mul(stat.f_frsize as u64);
    let free_bytes = stat.f_bavail.saturating_mul(stat.f_frsize as u64);
    let used_bytes = total_bytes.saturating_sub(free_bytes);
    let used_percent = if total_bytes == 0 {
        0.0
    } else {
        (used_bytes as f64 / total_bytes as f64) * 100.0
    };

    Ok(DiskStats {
        path: path.to_string(),
        total_bytes,
        free_bytes,
        used_bytes,
        used_percent,
    })
}

fn read_process_count() -> std::io::Result<usize> {
    let mut count = 0usize;
    for entry in fs::read_dir("/proc")? {
        let entry = entry?;
        let name = entry.file_name();
        if name.to_string_lossy().chars().all(|c| c.is_ascii_digit()) {
            count += 1;
        }
    }
    Ok(count)
}

fn collect_snapshot(prev_cpu: &mut Option<CpuTimes>) -> ResourceSnapshot {
    let cpu = match read_cpu_times() {
        Ok(curr) => {
            let usage = if let Some(prev) = prev_cpu {
                compute_cpu_usage(prev, &curr)
            } else {
                0.0
            };
            *prev_cpu = Some(curr);
            CpuStats {
                usage_percent: usage,
            }
        }
        Err(_) => CpuStats::default(),
    };

    let memory = read_mem_stats().unwrap_or_default();
    let load = read_load_stats().unwrap_or_default();
    let disk = read_disk_stats("/").unwrap_or_else(|_| DiskStats {
        path: "/".to_string(),
        ..Default::default()
    });
    let process_count = read_process_count().unwrap_or(0);

    ResourceSnapshot {
        timestamp: now_unix(),
        cpu,
        memory,
        disk,
        load,
        process_count,
    }
}

fn monitor_loop(state: Arc<RwLock<ResourceSnapshot>>, running: Arc<AtomicBool>) {
    let mut prev_cpu: Option<CpuTimes> = None;

    while running.load(Ordering::Relaxed) {
        let snapshot = collect_snapshot(&mut prev_cpu);
        if let Ok(mut guard) = state.write() {
            *guard = snapshot;
        }
        thread::sleep(SAMPLE_INTERVAL);
    }
}

fn handle_client(mut stream: UnixStream, state: Arc<RwLock<ResourceSnapshot>>) -> std::io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut line = String::new();
    reader.read_line(&mut line)?;

    let cmd = line.trim();

    let response = match cmd {
        "ping" => serde_json::json!({
            "ok": true,
            "message": "pong"
        }),
        "status" => {
            let snapshot = state.read().map(|g| g.clone()).unwrap_or_default();
            serde_json::json!({
                "ok": true,
                "data": snapshot
            })
        }
        "drop_caches" => {
            let result = File::create("/proc/sys/vm/drop_caches")
                .and_then(|mut f| f.write_all(b"3\n"));

            match result {
                Ok(_) => serde_json::json!({
                    "ok": true,
                    "message": "drop_caches requested"
                }),
                Err(e) => serde_json::json!({
                    "ok": false,
                    "error": format!("drop_caches failed: {}", e)
                }),
            }
        }
        _ => serde_json::json!({
            "ok": false,
            "error": "unknown command"
        }),
    };

    let body = serde_json::to_vec(&response)?;
    stream.write_all(&body)?;
    stream.write_all(b"\n")?;
    stream.flush()?;
    Ok(())
}

fn server_loop(state: Arc<RwLock<ResourceSnapshot>>, running: Arc<AtomicBool>) -> std::io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;
    listener.set_nonblocking(true)?;

    while running.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let state = Arc::clone(&state);
                thread::spawn(move || {
                    let _ = handle_client(stream, state);
                });
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                eprintln!("socket accept error: {}", e);
                thread::sleep(Duration::from_millis(250));
            }
        }
    }

    let _ = fs::remove_file(SOCKET_PATH);
    Ok(())
}

fn signal_loop(running: Arc<AtomicBool>) {
    let mut sigset = SigSet::empty();
    sigset.add(Signal::SIGINT);
    sigset.add(Signal::SIGTERM);

    let _ = signal::pthread_sigmask(signal::SigmaskHow::SIG_BLOCK, Some(&sigset), None);

    let _ = sigset.wait();
    running.store(false, Ordering::Relaxed);
}

fn main() -> std::io::Result<()> {
    let state = Arc::new(RwLock::new(ResourceSnapshot::default()));
    let running = Arc::new(AtomicBool::new(true));

    let signal_running = Arc::clone(&running);
    let signal_thread = thread::spawn(move || signal_loop(signal_running));

    let monitor_state = Arc::clone(&state);
    let monitor_running = Arc::clone(&running);
    let monitor_thread = thread::spawn(move || monitor_loop(monitor_state, monitor_running));

    let server_state = Arc::clone(&state);
    let server_running = Arc::clone(&running);
    let server_thread = thread::spawn(move || server_loop(server_state, server_running));

    let _ = monitor_thread.join();
    let _ = signal_thread.join();

    match server_thread.join() {
        Ok(res) => res?,
        Err(_) => eprintln!("server thread panicked"),
    }

    Ok(())
}
