```rust
use serde::Serialize;
use sysinfo::{Disks, Networks, System};

#[derive(Debug, Clone, Serialize)]
pub struct SystemSnapshot {
    pub cpu_usage: f32,
    pub memory_usage: f64,
    pub used_memory: u64,
    pub total_memory: u64,
    pub used_swap: u64,
    pub total_swap: u64,
    pub load_avg_one: f64,
    pub load_avg_five: f64,
    pub load_avg_fifteen: f64,
    pub total_disk_space: u64,
    pub available_disk_space: u64,
    pub total_network_received: u64,
    pub total_network_transmitted: u64,
}

pub struct MetricsCollector {
    sys: System,
    disks: Disks,
    networks: Networks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();

        let mut disks = Disks::new_with_refreshed_list();
        disks.refresh();

        let mut networks = Networks::new_with_refreshed_list();
        networks.refresh();

        Self {
            sys,
            disks,
            networks,
        }
    }

    pub fn collect(&mut self) -> SystemSnapshot {
        self.sys.refresh_cpu_usage();
        self.sys.refresh_memory();
        self.disks.refresh();
        self.networks.refresh();

        let cpu_usage = self.sys.global_cpu_usage();

        let total_memory = self.sys.total_memory();
        let used_memory = self.sys.used_memory();
        let total_swap = self.sys.total_swap();
        let used_swap = self.sys.used_swap();

        let memory_usage = if total_memory == 0 {
            0.0
        } else {
            (used_memory as f64 / total_memory as f64) * 100.0
        };

        let load = System::load_average();

        let mut total_disk_space = 0u64;
        let mut available_disk_space = 0u64;
        for disk in self.disks.list() {
            total_disk_space += disk.total_space();
            available_disk_space += disk.available_space();
        }

        let mut total_network_received = 0u64;
        let mut total_network_transmitted = 0u64;
        for (_, data) in &self.networks {
            total_network_received += data.total_received();
            total_network_transmitted += data.total_transmitted();
        }

        SystemSnapshot {
            cpu_usage,
            memory_usage,
            used_memory,
            total_memory,
            used_swap,
            total_swap,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            total_disk_space,
            available_disk_space,
            total_network_received,
            total_network_transmitted,
        }
    }
}
