use crate::{
    actions::ActionExecutor,
    config::RuleConfig,
    metrics::SystemSnapshot,
};
use tracing::debug;

#[derive(Debug, Clone, Copy)]
pub enum Operator {
    Gt,
    Lt,
    Ge,
    Le,
    Eq,
}

impl Operator {
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "gt" => Some(Self::Gt),
            "lt" => Some(Self::Lt),
            "ge" => Some(Self::Ge),
            "le" => Some(Self::Le),
            "eq" => Some(Self::Eq),
            _ => None,
        }
    }

    pub fn eval(&self, lhs: f64, rhs: f64) -> bool {
        match self {
            Self::Gt => lhs > rhs,
            Self::Lt => lhs < rhs,
            Self::Ge => lhs >= rhs,
            Self::Le => lhs <= rhs,
            Self::Eq => (lhs - rhs).abs() < f64::EPSILON,
        }
    }
}

#[derive(Debug, Clone)]
pub enum ActionKind {
    Log,
    Command(String),
}

#[derive(Debug, Clone)]
pub struct CompiledRule {
    pub name: String,
    pub metric: String,
    pub operator: Operator,
    pub threshold: f64,
    pub action: ActionKind,
    pub message: String,
}

impl CompiledRule {
    pub fn from_config(cfg: RuleConfig) -> anyhow::Result<Self> {
        let operator = Operator::parse(&cfg.operator)
            .ok_or_else(|| anyhow::anyhow!("invalid operator: {}", cfg.operator))?;

        let action = match cfg.action.as_str() {
            "log" => ActionKind::Log,
            "command" => ActionKind::Command(
                cfg.command
                    .ok_or_else(|| anyhow::anyhow!("missing command for rule {}", cfg.name))?,
            ),
            other => return Err(anyhow::anyhow!("invalid action: {}", other)),
        };

        Ok(Self {
            name: cfg.name,
            metric: cfg.metric,
            operator,
            threshold: cfg.threshold,
            action,
            message: cfg.message.unwrap_or_else(|| "rule triggered".to_string()),
        })
    }

    fn metric_value(&self, snap: &SystemSnapshot) -> Option<f64> {
        match self.metric.as_str() {
            "cpu_usage" => Some(snap.cpu_usage as f64),
            "memory_usage" => Some(snap.memory_usage),
            "load_avg_one" => Some(snap.load_avg_one),
            "load_avg_five" => Some(snap.load_avg_five),
            "load_avg_fifteen" => Some(snap.load_avg_fifteen),
            "used_memory" => Some(snap.used_memory as f64),
            "total_memory" => Some(snap.total_memory as f64),
            "used_swap" => Some(snap.used_swap as f64),
            "total_swap" => Some(snap.total_swap as f64),
            "total_disk_space" => Some(snap.total_disk_space as f64),
            "available_disk_space" => Some(snap.available_disk_space as f64),
            "total_network_received" => Some(snap.total_network_received as f64),
            "total_network_transmitted" => Some(snap.total_network_transmitted as f64),
            _ => None,
        }
    }

    pub async fn evaluate(&self, snap: &SystemSnapshot, executor: &ActionExecutor) {
        let Some(value) = self.metric_value(snap) else {
            debug!(rule = %self.name, metric = %self.metric, "unknown metric");
            return;
        };

        if self.operator.eval(value, self.threshold) {
            match &self.action {
                ActionKind::Log => {
                    executor.log(&self.message).await;
                }
                ActionKind::Command(cmd) => {
                    let _ = executor.log(&self.message).await;
                    let _ = executor.run_command(cmd).await;
                }
            }
        }
    }
}
