# src/daemon.rs

```rust
use crate::{
    actions::ActionExecutor,
    config::Config,
    metrics::MetricsCollector,
    rules::CompiledRule,
};
use anyhow::Context;
use tokio::{
    signal,
    time::{self, Duration, MissedTickBehavior},
};
use tracing::{error, info};

pub struct Daemon {
    collector: MetricsCollector,
    rules: Vec<CompiledRule>,
    executor: ActionExecutor,
    poll_interval: Duration,
}

impl Daemon {
    pub fn new(config: Config) -> anyhow::Result<Self> {
        let rules = config
            .rules
            .into_iter()
            .map(CompiledRule::from_config)
            .collect::<anyhow::Result<Vec<_>>>()
            .context("failed to compile rules")?;

        Ok(Self {
            collector: MetricsCollector::new(),
            rules,
            executor: ActionExecutor::new(config.actions),
            poll_interval: Duration::from_millis(config.poll_interval_ms),
        })
    }

    pub async fn run(mut self) -> anyhow::Result<()> {
        let mut ticker = time::interval(self.poll_interval);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);

        info!("sysmond daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.collector.collect();

                    for rule in &self.rules {
                        rule.evaluate(&snapshot, &self.executor).await;
                    }
                }
                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("sysmond daemon stopped");
        Ok(())
    }
}
```

