use std::{net::SocketAddr, sync::Arc, time::Duration};

use anyhow::Result;
use tokio::{signal, sync::RwLock, task::JoinSet, time};
use tracing::{error, info};

use crate::{
    config::Config,
    monitor::collect_metrics,
    policy::evaluate_policies,
    state::DaemonState,
    web::serve_http,
};

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,resourced=debug,tower_http=info".to_string()),
        )
        .init();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "/etc/resourced/config.toml".to_string());

    let config = Arc::new(Config::load(&config_path)?);
    info!("loaded config from {}", config_path);

    let state = Arc::new(RwLock::new(DaemonState::new()));
    let bind_addr: SocketAddr = config.server.bind.parse()?;

    let mut tasks = JoinSet::new();

    {
        let state = Arc::clone(&state);
        let config = Arc::clone(&config);
        tasks.spawn(async move {
            let mut interval = time::interval(Duration::from_secs(config.monitor.interval_secs));
            interval.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

            loop {
                interval.tick().await;

                match collect_metrics(&config).await {
                    Ok(metrics) => {
                        {
                            let mut s = state.write().await;
                            s.last_metrics = Some(metrics.clone());
                            s.last_updated = Some(std::time::SystemTime::now());
                        }

                        if let Err(e) = evaluate_policies(&config, &state, &metrics).await {
                            error!("policy evaluation failed: {e:#}");
                        }
                    }
                    Err(e) => {
                        error!("metric collection failed: {e:#}");
                    }
                }
            }
        });
    }

    {
        let state = Arc::clone(&state);
        let config = Arc::clone(&config);
        tasks.spawn(async move {
            if let Err(e) = serve_http(bind_addr, state, config).await {
                error!("http server failed: {e:#}");
            }
        });
    }

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = tasks.join_next() => {
            if let Some(res) = res {
                match res {
                    Ok(_) => info!("task exited"),
                    Err(e) => error!("task join error: {e:#}"),
                }
            }
        }
    }

    info!("resourced shutting down");
    Ok(())
}
