pub struct DaemonState {
    pub last_metrics: Option<Metrics>,
    pub last_updated: Option<SystemTime>,
    pub recent_events: Vec<EventRecord>,
    pub last_action_epoch_ms: Option<u128>,
}

impl DaemonState {
    pub fn new() -> Self {
        Self {
            last_metrics: None,
            last_updated: None,
            recent_events: Vec::with_capacity(256),
            last_action_epoch_ms: None,
        }
    }

    pub fn push_event(&mut self, severity: impl Into<String>, message: impl Into<String>) {
        if self.recent_events.len() >= 256 {
            self.recent_events.remove(0);
        }

        self.recent_events.push(EventRecord {
            timestamp_epoch_ms: SystemTime::now()
                .duration_since(SystemTime::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0),
            severity: severity.into(),
            message: message.into(),
        });
    }
}
