## `src/monitor.rs`

```rust
use anyhow::{Context, Result};
use nix::sys::statvfs::statvfs;
use serde::Serialize;
use tokio::fs;

use crate::config::Config;

#[derive(Debug, Clone, Serialize)]
pub struct Metrics {
    pub cpu_percent: f32,
    pub mem_percent: f32,
    pub load1: f32,
    pub load5: f32,
    pub load15: f32,
    pub process_count: usize,
    pub disks: Vec<DiskMetric>,
}

#[derive(Debug, Clone, Serialize)]
pub struct DiskMetric {
    pub mount: String,
    pub total_bytes: u64,
    pub used_bytes: u64,
    pub used_percent: f32,
}

#[derive(Debug, Clone, Copy)]
struct CpuTimes {
    idle: u64,
    total: u64,
}

static mut PREV_CPU: Option<CpuTimes> = None;

pub async fn collect_metrics(config: &Config) -> Result<Metrics> {
    let cpu_percent = read_cpu_percent().await?;
    let mem_percent = read_mem_percent().await?;
    let (load1, load5, load15) = read_loadavg().await?;
    let process_count = count_processes().await?;
    let disks = read_disks(&config.monitor.disk_mounts)?;

    Ok(Metrics {
        cpu_percent,
        mem_percent,
        load1,
        load5,
        load15,
        process_count,
        disks,
    })
}

async fn read_cpu_percent() -> Result<f32> {
    let stat = fs::read_to_string("/proc/stat").await?;
    let line = stat
        .lines()
        .next()
        .context("missing cpu line in /proc/stat")?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 5 {
        anyhow::bail!("unexpected /proc/stat cpu format");
    }

    let user: u64 = parts[1].parse()?;
    let nice: u64 = parts[2].parse()?;
    let system: u64 = parts[3].parse()?;
    let idle: u64 = parts[4].parse()?;
    let iowait: u64 = parts.get(5).and_then(|s| s.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|s| s.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|s| s.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|s| s.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;

    let current = CpuTimes {
        idle: idle_all,
        total,
    };

    let percent = unsafe {
        let pct = if let Some(prev) = PREV_CPU {
            let totald = current.total.saturating_sub(prev.total);
            let idled = current.idle.saturating_sub(prev.idle);
            if totald == 0 {
                0.0
            } else {
                ((totald - idled) as f32 / totald as f32) * 100.0
            }
        } else {
            0.0
        };
        PREV_CPU = Some(current);
        pct
    };

    Ok(percent)
}

async fn read_mem_percent() -> Result<f32> {
    let meminfo = fs::read_to_string("/proc/meminfo").await?;
    let mut mem_total_kb = 0u64;
    let mut mem_available_kb = 0u64;

    for line in meminfo.lines() {
        if let Some(v) = line.strip_prefix("MemTotal:") {
            mem_total_kb = v.split_whitespace().next().unwrap_or("0").parse()?;
        } else if let Some(v) = line.strip_prefix("MemAvailable:") {
            mem_available_kb = v.split_whitespace().next().unwrap_or("0").parse()?;
        }
    }

    if mem_total_kb == 0 {
        anyhow::bail!("MemTotal was zero");
    }

    let used = mem_total_kb.saturating_sub(mem_available_kb);
    Ok((used as f32 / mem_total_kb as f32) * 100.0)
}

async fn read_loadavg() -> Result<(f32, f32, f32)> {
    let load = fs::read_to_string("/proc/loadavg").await?;
    let parts: Vec<&str> = load.split_whitespace().collect();
    if parts.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }

    Ok((parts[0].parse()?, parts[1].parse()?, parts[2].parse()?))
}

async fn count_processes() -> Result<usize> {
    let mut rd = fs::read_dir("/proc").await?;
    let mut count = 0usize;

    while let Some(entry) = rd.next_entry().await? {
        let name = entry.file_name();
        let s = name.to_string_lossy();
        if s.chars().all(|c| c.is_ascii_digit()) {
            count += 1;
        }
    }

    Ok(count)
}

fn read_disks(mounts: &[String]) -> Result<Vec<DiskMetric>> {
    let mut out = Vec::with_capacity(mounts.len());

    for mount in mounts {
        let vfs = statvfs(mount)?;
        let total = vfs.blocks().saturating_mul(vfs.fragment_size());
        let avail = vfs.blocks_available().saturating_mul(vfs.fragment_size());
        let used = total.saturating_sub(avail);
        let used_percent = if total == 0 {
            0.0
        } else {
            (used as f32 / total as f32) * 100.0
        };

        out.push(DiskMetric {
            mount: mount.clone(),
            total_bytes: total,
            used_bytes: used,
            used_percent,
        });
    }

    Ok(out)
}
