## `src/policy.rs`

```rust
use std::{
    sync::Arc,
    time::{SystemTime, UNIX_EPOCH},
};

use anyhow::Result;
use tokio::sync::RwLock;
use tracing::{info, warn};

use crate::{
    actions::{drop_caches, kill_named_processes},
    config::Config,
    monitor::Metrics,
    state::DaemonState,
};

pub async fn evaluate_policies(
    config: &Config,
    state: &Arc<RwLock<DaemonState>>,
    metrics: &Metrics,
) -> Result<()> {
    let p = &config.policy;

    if metrics.cpu_percent >= p.cpu_crit_percent {
        emit(state, "critical", format!("cpu critical: {:.2}%", metrics.cpu_percent)).await;
    } else if metrics.cpu_percent >= p.cpu_warn_percent {
        emit(state, "warning", format!("cpu warning: {:.2}%", metrics.cpu_percent)).await;
    }

    if metrics.mem_percent >= p.mem_crit_percent {
        emit(state, "critical", format!("memory critical: {:.2}%", metrics.mem_percent)).await;

        if config.actions.enable_drop_caches && action_allowed(config, state).await {
            warn!("dropping caches due to critical memory pressure");
            drop_caches().await?;
            mark_action(state).await;
            emit(state, "action", "drop_caches executed").await;
        }
    } else if metrics.mem_percent >= p.mem_warn_percent {
        emit(state, "warning", format!("memory warning: {:.2}%", metrics.mem_percent)).await;
    }

    if metrics.load1 >= p.load_crit {
        emit(state, "critical", format!("load critical: {:.2}", metrics.load1)).await;
    } else if metrics.load1 >= p.load_warn {
        emit(state, "warning", format!("load warning: {:.2}", metrics.load1)).await;
    }

    for disk in &metrics.disks {
        if disk.used_percent >= p.disk_crit_percent {
            emit(
                state,
                "critical",
                format!("disk critical on {}: {:.2}%", disk.mount, disk.used_percent),
            )
            .await;
        } else if disk.used_percent >= p.disk_warn_percent {
            emit(
                state,
                "warning",
                format!("disk warning on {}: {:.2}%", disk.mount, disk.used_percent),
            )
            .await;
        }
    }

    if config.actions.enable_kill_processes
        && metrics.mem_percent >= p.mem_crit_percent
        && action_allowed(config, state).await
    {
        let killed = kill_named_processes(&config.actions.kill_process_names).await?;
        if killed > 0 {
            mark_action(state).await;
            emit(
                state,
                "action",
                format!("killed {} configured processes", killed),
            )
            .await;
            info!("killed {} configured processes", killed);
        }
    }

    Ok(())
}

async fn emit(state: &Arc<RwLock<DaemonState>>, severity: &str, message: String) {
    {
        let mut s = state.write().await;
        s.push_event(severity, message.clone());
    }

    match severity {
        "critical" => warn!("{message}"),
        "warning" => warn!("{message}"),
        _ => info!("{message}"),
    }
}

async fn action_allowed(config: &Config, state: &Arc<RwLock<DaemonState>>) -> bool {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);

    let s = state.read().await;
    match s.last_action_epoch_ms {
        Some(last_ms) => {
            let last_secs = (last_ms / 1000) as u64;
            now.saturating_sub(last_secs) >= config.actions.cooldown_secs
        }
        None => true,
    }
}

async fn mark_action(state: &Arc<RwLock<DaemonState>>) {
    let now_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);

    let mut s = state.write().await;
    s.last_action_epoch_ms = Some(now_ms);
}
