## `src/actions.rs`

```rust
use anyhow::Result;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use tokio::{fs, process::Command};
use tracing::{info, warn};

pub async fn drop_caches() -> Result<()> {
    Command::new("sync").status().await?;
    fs::write("/proc/sys/vm/drop_caches", "1\n").await?;
    info!("requested kernel drop_caches");
    Ok(())
}

pub async fn kill_named_processes(names: &[String]) -> Result<usize> {
    let mut rd = fs::read_dir("/proc").await?;
    let mut pids = Vec::new();

    while let Some(entry) = rd.next_entry().await? {
        let file_name = entry.file_name();
        let pid_str = file_name.to_string_lossy();
        if !pid_str.chars().all(|c| c.is_ascii_digit()) {
            continue;
        }

        let comm_path = format!("/proc/{}/comm", pid_str);
        let Ok(comm) = fs::read_to_string(&comm_path).await else {
            continue;
        };

        let proc_name = comm.trim();
        if names.iter().any(|n| n == proc_name) {
            if let Ok(pid_raw) = pid_str.parse::<i32>() {
                pids.push(pid_raw);
            }
        }
    }

    let mut killed = 0usize;

    for pid in &pids {
        let _ = kill(Pid::from_raw(*pid), Signal::SIGTERM);
    }

    tokio::time::sleep(std::time::Duration::from_secs(2)).await;

    for pid in &pids {
        let proc_path = format!("/proc/{}", pid);
        if fs::metadata(&proc_path).await.is_ok() {
            warn!("process {} survived SIGTERM, sending SIGKILL", pid);
            let _ = kill(Pid::from_raw(*pid), Signal::SIGKILL);
        }
        killed += 1;
    }

    Ok(killed)
}
```

