use std::{net::SocketAddr, sync::Arc};

use anyhow::Result;
use axum::{
    extract::State,
    response::Json,
    routing::get,
    Router,
};
use serde_json::{json, Value};
use tokio::{net::TcpListener, sync::RwLock};

use crate::{config::Config, state::DaemonState};

#[derive(Clone)]
struct AppState {
    daemon_state: Arc<RwLock<DaemonState>>,
    config: Arc<Config>,
}

pub async fn serve_http(
    addr: SocketAddr,
    daemon_state: Arc<RwLock<DaemonState>>,
    config: Arc<Config>,
) -> Result<()> {
    let app_state = AppState { daemon_state, config };

    let app = Router::new()
        .route("/health", get(health))
        .route("/metrics", get(metrics))
        .route("/state", get(state))
        .with_state(app_state);

    let listener = TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;
    Ok(())
}

async fn health() -> Json<Value> {
    Json(json!({ "status": "ok" }))
}

async fn metrics(State(state): State<AppState>) -> Json<Value> {
    let s = state.daemon_state.read().await;
    Json(json!({
        "metrics": s.last_metrics,
        "updated": s.last_updated.map(|t| t.duration_since(std::time::UNIX_EPOCH).ok().map(|d| d.as_secs())).flatten()
    }))
}

async fn state(State(state): State<AppState>) -> Json<Value> {
    let s = state.daemon_state.read().await;
    Json(json!({
        "config": state.config,
        "last_metrics": s.last_metrics,
        "last_updated": s.last_updated.map(|t| t.duration_since(std::time::UNIX_EPOCH).ok().map(|d| d.as_secs())).flatten(),
        "recent_events": s.recent_events,
        "last_action_epoch_ms": s.last_action_epoch_ms
    }))
}
