use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, RwLock,
};
use std::thread;
use std::time::{Duration, Instant};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    uptime_secs: u64,
    loadavg_1: f64,
    loadavg_5: f64,
    loadavg_15: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
    proc_count: u64,
    cpu_usage_percent: f64,
    timestamp_unix_secs: u64,
}

#[derive(Debug)]
struct CpuSnapshot {
    total: u64,
    idle: u64,
}

#[derive(Debug)]
struct SharedState {
    started_at: Instant,
    metrics: RwLock<Metrics>,
    running: AtomicBool,
}

impl SharedState {
    fn new() -> Self {
        Self {
            started_at: Instant::now(),
            metrics: RwLock::new(Metrics::default()),
            running: AtomicBool::new(true),
        }
    }
}

fn main() -> Result<()> {
    let state = Arc::new(SharedState::new());

    install_signal_handlers(state.clone())?;

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let sampler_state = state.clone();
    let sampler = thread::spawn(move || sampler_loop(sampler_state));

    let server_state = state.clone();
    let server = thread::spawn(move || socket_server_loop(server_state));

    sampler.join().expect("sampler thread panicked")?;
    server.join().expect("server thread panicked")?;

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn install_signal_handlers(state: Arc<SharedState>) -> Result<()> {
    use nix::sys::signal::{self, SigHandler, Signal};

    extern "C" fn handle_sigint(_: i32) {
        // no-op; process will be interrupted unless masked
    }

    unsafe {
        signal::signal(Signal::SIGINT, SigHandler::Handler(handle_sigint))?;
        signal::signal(Signal::SIGTERM, SigHandler::Handler(handle_sigint))?;
    }

    let signal_state = state.clone();
    thread::spawn(move || {
        use nix::sys::signal::{sigwait, SigSet};

        let mut set = SigSet::empty();
        set.add(Signal::SIGINT);
        set.add(Signal::SIGTERM);

        let _ = signal::pthread_sigmask(signal::SigmaskHow::SIG_BLOCK, Some(&set), None);

        while signal_state.running.load(Ordering::Relaxed) {
            if let Ok(sig) = sigwait(&set) {
                match sig {
                    Signal::SIGINT | Signal::SIGTERM => {
                        signal_state.running.store(false, Ordering::Relaxed);
                        break;
                    }
                    _ => {}
                }
            }
        }
    });

    Ok(())
}

fn sampler_loop(state: Arc<SharedState>) -> Result<()> {
    let mut prev_cpu = read_cpu_snapshot().context("initial cpu snapshot")?;

    while state.running.load(Ordering::Relaxed) {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        let load = read_loadavg().context("read loadavg")?;
        let mem = read_meminfo().context("read meminfo")?;
        let proc_count = count_processes().context("count processes")?;
        let uptime_secs = state.started_at.elapsed().as_secs();

        let curr_cpu = read_cpu_snapshot().context("read cpu snapshot")?;
        let cpu_usage_percent = compute_cpu_usage(&prev_cpu, &curr_cpu);
        prev_cpu = curr_cpu;

        let metrics = Metrics {
            uptime_secs,
            loadavg_1: load.0,
            loadavg_5: load.1,
            loadavg_15: load.2,
            mem_total_kb: mem.0,
            mem_available_kb: mem.1,
            mem_used_kb: mem.0.saturating_sub(mem.1),
            proc_count,
            cpu_usage_percent,
            timestamp_unix_secs: now,
        };

        {
            let mut guard = state.metrics.write().unwrap();
            *guard = metrics;
        }

        thread::sleep(SAMPLE_INTERVAL);
    }

    Ok(())
}

fn socket_server_loop(state: Arc<SharedState>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH).context("bind unix socket")?;
    listener
        .set_nonblocking(true)
        .context("set nonblocking")?;

    while state.running.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let client_state = state.clone();
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, client_state) {
                        eprintln!("client error: {e:#}");
                    }
                });
            }
            Err(err) if err.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(50));
            }
            Err(err) => {
                return Err(err).context("accept failed");
            }
        }
    }

    Ok(())
}

fn handle_client(mut stream: UnixStream, state: Arc<SharedState>) -> Result<()> {
    let reader_stream = stream.try_clone().context("clone stream")?;
    let mut reader = BufReader::new(reader_stream);

    loop {
        let mut line = String::new();
        let n = reader.read_line(&mut line).context("read command")?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        match cmd {
            "ping" => {
                writeln!(stream, "pong").context("write pong")?;
            }
            "status" => {
                writeln!(stream, "ok running={}", state.running.load(Ordering::Relaxed))
                    .context("write status")?;
            }
            "metrics" => {
                let snapshot = {
                    let guard = state.metrics.read().unwrap();
                    guard.clone()
                };
                let json = serde_json::to_string(&snapshot).context("serialize metrics")?;
                writeln!(stream, "{json}").context("write metrics")?;
            }
            "quit" => {
                state.running.store(false, Ordering::Relaxed);
                writeln!(stream, "shutting down").context("write quit ack")?;
                break;
            }
            _ => {
                writeln!(stream, "error unknown-command").context("write error")?;
            }
        }
    }

    Ok(())
}

fn read_loadavg() -> Result<(f64, f64, f64)> {
    let content = fs::read_to_string("/proc/loadavg").context("read /proc/loadavg")?;
    let mut parts = content.split_whitespace();

    let one = parts
        .next()
        .context("missing loadavg 1")?
        .parse::<f64>()
        .context("parse loadavg 1")?;
    let five = parts
        .next()
        .context("missing loadavg 5")?
        .parse::<f64>()
        .context("parse loadavg 5")?;
    let fifteen = parts
        .next()
        .context("missing loadavg 15")?
        .parse::<f64>()
        .context("parse loadavg 15")?;

    Ok((one, five, fifteen))
}

fn read_meminfo() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo").context("read /proc/meminfo")?;
    let mut total = 0_u64;
    let mut available = 0_u64;

    for line in content.lines() {
        if let Some(value) = line.strip_prefix("MemTotal:") {
            total = parse_mem_kb(value)?;
        } else if let Some(value) = line.strip_prefix("MemAvailable:") {
            available = parse_mem_kb(value)?;
        }
    }

    Ok((total, available))
}

fn parse_mem_kb(s: &str) -> Result<u64> {
    let value = s
        .split_whitespace()
        .next()
        .context("missing meminfo value")?
        .parse::<u64>()
        .context("parse meminfo value")?;
    Ok(value)
}

fn count_processes() -> Result<u64> {
    let mut count = 0_u64;
    for entry in fs::read_dir("/proc").context("read /proc dir")? {
        let entry = entry?;
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name.as_bytes().iter().all(|b| b.is_ascii_digit()) {
            count += 1;
        }
    }
    Ok(count)
}

fn read_cpu_snapshot() -> Result<CpuSnapshot> {
    let content = fs::read_to_string("/proc/stat").context("read /proc/stat")?;
    let first = content.lines().next().context("missing cpu line")?;
    let mut parts = first.split_whitespace();

    let label = parts.next().context("missing cpu label")?;
    if label != "cpu" {
        anyhow::bail!("unexpected cpu label: {label}");
    }

    let values: Vec<u64> = parts
        .map(|p| p.parse::<u64>())
        .collect::<std::result::Result<Vec<_>, _>>()
        .context("parse cpu fields")?;

    let idle = values.get(3).copied().unwrap_or(0) + values.get(4).copied().unwrap_or(0);
    let total = values.iter().copied().sum();

    Ok(CpuSnapshot { total, idle })
}

fn compute_cpu_usage(prev: &CpuSnapshot, curr: &CpuSnapshot) -> f64 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    let busy = total_delta.saturating_sub(idle_delta);
    (busy as f64 / total_delta as f64) * 100.0
}
