```rust
use anyhow::{Context, Result};
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{LoadAvg, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    task,
    time,
};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    memory_usage_percent: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    process_count: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Thresholds {
    cpu_percent: f32,
    memory_percent: f32,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_percent: 90.0,
            memory_percent: 90.0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct HealthStatus {
    healthy: bool,
    reasons: Vec<String>,
}

#[derive(Debug)]
struct SharedState {
    latest: RwLock<Option<ResourceSnapshot>>,
    thresholds: RwLock<Thresholds>,
    started_at: Instant,
    counters: RwLock<HashMap<String, u64>>,
}

impl SharedState {
    fn new() -> Self {
        Self {
            latest: RwLock::new(None),
            thresholds: RwLock::new(Thresholds::default()),
            started_at: Instant::now(),
            counters: RwLock::new(HashMap::new()),
        }
    }

    fn incr(&self, key: &str) {
        let mut counters = self.counters.write();
        *counters.entry(key.to_string()).or_insert(0) += 1;
    }

    fn uptime_secs(&self) -> u64 {
        self.started_at.elapsed().as_secs()
    }

    fn health(&self) -> HealthStatus {
        let latest = self.latest.read().clone();
        let thresholds = self.thresholds.read().clone();

        let mut reasons = Vec::new();
        let mut healthy = true;

        match latest {
            Some(snapshot) => {
                if snapshot.cpu_usage_percent > thresholds.cpu_percent {
                    healthy = false;
                    reasons.push(format!(
                        "cpu usage {:.2}% exceeds threshold {:.2}%",
                        snapshot.cpu_usage_percent, thresholds.cpu_percent
                    ));
                }

                if snapshot.memory_usage_percent > thresholds.memory_percent {
                    healthy = false;
                    reasons.push(format!(
                        "memory usage {:.2}% exceeds threshold {:.2}%",
                        snapshot.memory_usage_percent, thresholds.memory_percent
                    ));
                }
            }
            None => {
                healthy = false;
                reasons.push("no resource snapshot available yet".to_string());
            }
        }

        HealthStatus { healthy, reasons }
    }
}

#[derive(Debug, Serialize)]
struct StatusResponse {
    uptime_secs: u64,
    latest: Option<ResourceSnapshot>,
    thresholds: Thresholds,
    counters: HashMap<String, u64>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Request {
    Status,
    Health,
    SetThreshold { resource: String, value: f32 },
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum Response {
    Status(StatusResponse),
    Health(HealthStatus),
    Ok { message: String },
    Error { message: String },
}

fn now_unix_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

async fn monitor_loop(state: Arc<SharedState>, interval: Duration) {
    let mut ticker = time::interval(interval);
    let mut sys = System::new_all();

    loop {
        ticker.tick().await;

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes();

        let cpu_usage = sys.global_cpu_info().cpu_usage();
        let memory_total = sys.total_memory() * 1024;
        let memory_used = sys.used_memory() * 1024;
        let memory_usage_percent = if memory_total > 0 {
            (memory_used as f32 / memory_total as f32) * 100.0
        } else {
            0.0
        };

        let LoadAvg { one, five, fifteen } = System::load_average();
        let process_count = sys.processes().len();

        let snapshot = ResourceSnapshot {
            timestamp_unix_ms: now_unix_ms(),
            cpu_usage_percent: cpu_usage,
            memory_used_bytes: memory_used,
            memory_total_bytes: memory_total,
            memory_usage_percent,
            load_avg_one: one,
            load_avg_five: five,
            load_avg_fifteen: fifteen,
            process_count,
        };

        {
            let mut latest = state.latest.write();
            *latest = Some(snapshot.clone());
        }

        state.incr("monitor_ticks");

        let thresholds = state.thresholds.read().clone();
        if snapshot.cpu_usage_percent > thresholds.cpu_percent {
            warn!(
                cpu_usage_percent = snapshot.cpu_usage_percent,
                threshold = thresholds.cpu_percent,
                "cpu threshold exceeded"
            );
            state.incr("cpu_threshold_exceeded");
        }

        if snapshot.memory_usage_percent > thresholds.memory_percent {
            warn!(
                memory_usage_percent = snapshot.memory_usage_percent,
                threshold = thresholds.memory_percent,
                "memory threshold exceeded"
            );
            state.incr("memory_threshold_exceeded");
        }
    }
}

async fn handle_client(stream: UnixStream, state: Arc<SharedState>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        state.incr("commands_total");

        let request: Request = match serde_json::from_str(&line) {
            Ok(req) => req,
            Err(err) => {
                let resp = Response::Error {
                    message: format!("invalid request: {}", err),
                };
                let out = serde_json::to_string(&resp)? + "\n";
                writer.write_all(out.as_bytes()).await?;
                state.incr("commands_invalid");
                continue;
            }
        };

        let response = match request {
            Request::Status => {
                let latest = state.latest.read().clone();
                let thresholds = state.thresholds.read().clone();
                let counters = state.counters.read().clone();

                Response::Status(StatusResponse {
                    uptime_secs: state.uptime_secs(),
                    latest,
                    thresholds,
                    counters,
                })
            }
            Request::Health => Response::Health(state.health()),
            Request::SetThreshold { resource, value } => {
                if value <= 0.0 || value > 100.0 {
                    Response::Error {
                        message: "threshold value must be in range (0, 100]".to_string(),
                    }
                } else {
                    let mut thresholds = state.thresholds.write();
                    match resource.as_str() {
                        "cpu" => {
                            thresholds.cpu_percent = value;
                            state.incr("threshold_updates");
                            Response::Ok {
                                message: format!("cpu threshold set to {}", value),
                            }
                        }
                        "mem" | "memory" => {
                            thresholds.memory_percent = value;
                            state.incr("threshold_updates");
                            Response::Ok {
                                message: format!("memory threshold set to {}", value),
                            }
                        }
                        _ => Response::Error {
                            message: "resource must be one of: cpu, mem, memory".to_string(),
                        },
                    }
                }
            }
        };

        let out = serde_json::to_string(&response)? + "\n";
        writer.write_all(out.as_bytes()).await?;
    }

    Ok(())
}

async fn command_server(state: Arc<SharedState>, socket_path: &str) -> Result<()> {
    if Path::new(socket_path).exists() {
        std::fs::remove_file(socket_path)
            .with_context(|| format!("failed to remove existing socket {}", socket_path))?;
    }

    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("failed to bind unix socket {}", socket_path))?;

    info!(socket_path = socket_path, "command server listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        task::spawn(async move {
            if let Err(err) = handle_client(stream, state).await {
                error!(error = %err, "client handler failed");
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,resourced=debug".to_string()),
        )
        .init();

    let socket_path =
        std::env::var("RESOURCED_SOCKET").unwrap_or_else(|_| "/tmp/resourced.sock".to_string());
    let monitor_interval_ms = std::env::var("RESOURCED_INTERVAL_MS")
        .ok()
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(1000);

    let state = Arc::new(SharedState::new());

    let monitor_task = {
        let state = state.clone();
        task::spawn(async move {
            monitor_loop(state, Duration::from_millis(monitor_interval_ms)).await;
        })
    };

    let server_task = {
        let state = state.clone();
        let socket_path = socket_path.clone();
        task::spawn(async move {
            if let Err(err) = command_server(state, &socket_path).await {
                error!(error = %err, "command server failed");
            }
        })
    };

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        _ = monitor_task => {
            error!("monitor task exited unexpectedly");
        }
        _ = server_task => {
            error!("server task exited unexpectedly");
        }
    }

    if Path::new(&socket_path).exists() {
        if let Err(err) = std::fs::remove_file(&socket_path) {
            warn!(error = %err, "failed to remove socket file during shutdown");
        }
    }

    Ok(())
}
