use anyhow::{Context, Result};
use log::{error, info, warn};
use serde::Serialize;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, RwLock,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, ProcessRefreshKind, RefreshKind, System};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const TOP_N_PROCESSES: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct CpuSnapshot {
    usage_percent: f32,
    logical_cores: usize,
}

#[derive(Debug, Clone, Serialize)]
struct MemorySnapshot {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix_secs: u64,
    cpu: CpuSnapshot,
    memory: MemorySnapshot,
    disks: Vec<DiskSnapshot>,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Debug, Default)]
struct SharedState {
    latest: Option<MetricsSnapshot>,
}

fn now_unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn build_snapshot(sys: &System) -> MetricsSnapshot {
    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let logical_cores = sys.cpus().len();

    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let free_mem = total_mem.saturating_sub(used_mem);
    let used_percent = if total_mem > 0 {
        (used_mem as f32 / total_mem as f32) * 100.0
    } else {
        0.0
    };

    let cpu = CpuSnapshot {
        usage_percent: cpu_usage,
        logical_cores,
    };

    let memory = MemorySnapshot {
        total_bytes: total_mem * 1024,
        used_bytes: used_mem * 1024,
        free_bytes: free_mem * 1024,
        used_percent,
    };

    let disks = sys
        .disks()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total > 0 {
                (used as f32 / total as f32) * 100.0
            } else {
                0.0
            };

            DiskSnapshot {
                name: d.name().to_string_lossy().into_owned(),
                mount_point: d.mount_point().to_string_lossy().into_owned(),
                total_bytes: total,
                available_bytes: avail,
                used_bytes: used,
                used_percent,
            }
        })
        .collect::<Vec<_>>();

    let mut processes = sys
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessSnapshot {
            pid: pid.as_u32(),
            name: proc_.name().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory() * 1024,
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    processes.truncate(TOP_N_PROCESSES);

    MetricsSnapshot {
        timestamp_unix_secs: now_unix_secs(),
        cpu,
        memory,
        disks,
        top_processes: processes,
    }
}

fn sampler_loop(shared: Arc<RwLock<SharedState>>, shutdown: Arc<AtomicBool>) {
    let refresh = RefreshKind::new()
        .with_cpu(CpuRefreshKind::everything())
        .with_memory()
        .with_processes(ProcessRefreshKind::everything())
        .with_disks(DiskRefreshKind::everything());

    let mut sys = System::new_with_specifics(refresh);

    // Prime CPU/process counters.
    sys.refresh_cpu();
    sys.refresh_processes();
    thread::sleep(Duration::from_millis(250));

    while !shutdown.load(Ordering::Relaxed) {
        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_processes();
        sys.refresh_disks();

        let snapshot = build_snapshot(&sys);

        match shared.write() {
            Ok(mut guard) => {
                guard.latest = Some(snapshot);
            }
            Err(e) => {
                error!("shared state poisoned in sampler: {}", e);
                break;
            }
        }

        thread::sleep(SAMPLE_INTERVAL);
    }

    info!("sampler loop exiting");
}

fn handle_client(mut stream: UnixStream, shared: &Arc<RwLock<SharedState>>) -> Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut line = String::new();
    reader.read_line(&mut line)?;

    let cmd = line.trim();

    let response = match cmd {
        "ping" => serde_json::json!({
            "status": "ok",
            "reply": "pong"
        }),
        "metrics" => {
            let snapshot = shared
                .read()
                .ok()
                .and_then(|g| g.latest.clone());

            match snapshot {
                Some(s) => serde_json::json!({
                    "status": "ok",
                    "metrics": s
                }),
                None => serde_json::json!({
                    "status": "error",
                    "error": "metrics unavailable"
                }),
            }
        }
        "shutdown" => serde_json::json!({
            "status": "error",
            "error": "remote shutdown disabled in initial implementation"
        }),
        other => serde_json::json!({
            "status": "error",
            "error": format!("unknown command: {}", other)
        }),
    };

    let encoded = serde_json::to_vec(&response)?;
    stream.write_all(&encoded)?;
    stream.write_all(b"\n")?;
    stream.flush()?;
    Ok(())
}

fn control_loop(shared: Arc<RwLock<SharedState>>, shutdown: Arc<AtomicBool>) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket {}", SOCKET_PATH))?;
    }

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind socket {}", SOCKET_PATH))?;

    info!("control socket listening on {}", SOCKET_PATH);

    listener
        .set_nonblocking(true)
        .context("failed to set nonblocking listener")?;

    while !shutdown.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                if let Err(e) = handle_client(stream, &shared) {
                    warn!("client handling error: {:?}", e);
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                warn!("accept error: {}", e);
                thread::sleep(Duration::from_millis(200));
            }
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        if let Err(e) = fs::remove_file(SOCKET_PATH) {
            warn!("failed to remove socket on shutdown: {}", e);
        }
    }

    info!("control loop exiting");
    Ok(())
}

fn main() -> Result<()> {
    env_logger::init();

    let shared = Arc::new(RwLock::new(SharedState::default()));
    let shutdown = Arc::new(AtomicBool::new(false));

    {
        let shutdown = shutdown.clone();
        ctrlc::set_handler(move || {
            shutdown.store(true, Ordering::Relaxed);
        })
        .context("failed to install ctrl-c handler")?;
    }

    let sampler_shared = shared.clone();
    let sampler_shutdown = shutdown.clone();
    let sampler = thread::Builder::new()
        .name("sampler".into())
        .spawn(move || sampler_loop(sampler_shared, sampler_shutdown))
        .context("failed to spawn sampler thread")?;

    let control_shared = shared.clone();
    let control_shutdown = shutdown.clone();
    let control = thread::Builder::new()
        .name("control".into())
        .spawn(move || {
            if let Err(e) = control_loop(control_shared, control_shutdown) {
                error!("control loop failed: {:?}", e);
            }
        })
        .context("failed to spawn control thread")?;

    info!("osd started");

    while !shutdown.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_millis(250));
    }

    info!("shutdown requested");

    if let Err(e) = sampler.join() {
        error!("sampler thread join error: {:?}", e);
    }

    if let Err(e) = control.join() {
        error!("control thread join error: {:?}", e);
    }

    info!("osd exited");
    Ok(())
}
