# src/policy.rs

```rust
use crate::config::Config;
use crate::metrics::ResourceMetrics;
use serde::Serialize;

#[derive(Debug, Clone, Serialize)]
pub enum Action {
    None,
    LogHighCpu,
    LogHighMemory,
    LogHighDisk,
    PressureRelief,
}

#[derive(Debug, Clone, Serialize)]
pub struct PolicyDecision {
    pub actions: Vec<Action>,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, metrics: &ResourceMetrics) -> PolicyDecision {
        let mut actions = Vec::with_capacity(4);

        if metrics.cpu_usage_percent >= self.config.cpu_threshold_percent {
            actions.push(Action::LogHighCpu);
        }

        if metrics.memory_usage_percent >= self.config.memory_threshold_percent {
            actions.push(Action::LogHighMemory);
        }

        if metrics.disk_usage_percent >= self.config.disk_threshold_percent {
            actions.push(Action::LogHighDisk);
        }

        if actions.len() >= 2 {
            actions.push(Action::PressureRelief);
        }

        if actions.is_empty() {
            actions.push(Action::None);
        }

        PolicyDecision { actions }
    }
}
