# src/main.rs

```rust
mod config;
mod manager;
mod metrics;
mod policy;
mod web;

use std::{net::SocketAddr, sync::Arc, time::Duration};

use anyhow::Result;
use config::Config;
use manager::ResourceManager;
use metrics::MetricsCollector;
use parking_lot::RwLock;
use policy::PolicyEngine;
use tokio::time::interval;
use tracing::{error, info};
use web::{DaemonStateSnapshot, SharedState};

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    let config = Config::default();
    info!(?config, "starting resource daemon");

    let shared_state: SharedState = Arc::new(RwLock::new(DaemonStateSnapshot::default()));

    let web_state = shared_state.clone();
    let web_bind = config.http_bind.clone();
    tokio::spawn(async move {
        if let Err(e) = run_web_server(web_bind, web_state).await {
            error!(error = %e, "web server failed");
        }
    });

    let mut collector = MetricsCollector::new();
    let policy = PolicyEngine::new(config.clone());
    let manager = ResourceManager::new();

    let mut ticker = interval(Duration::from_millis(config.sample_interval_ms));

    loop {
        ticker.tick().await;

        let metrics = collector.collect();
        let decision = policy.evaluate(&metrics);

        {
            let mut state = shared_state.write();
            state.metrics = Some(metrics.clone());
            state.decision = Some(decision.clone());
        }

        manager.apply(&decision).await?;
    }
}

async fn run_web_server(bind: String, state: SharedState) -> Result<()> {
    let app = web::router(state);
    let addr: SocketAddr = bind.parse()?;
    let listener = tokio::net::TcpListener::bind(addr).await?;
    info!(address = %addr, "HTTP server listening");
    axum::serve(listener, app).await?;
    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "resource_daemon=info,tower_http=info,axum=info".into()),
        )
        .init();
}
