```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::Path,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/osd.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);
const TOP_N: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct CpuStats {
    usage_percent: f32,
    logical_cores: usize,
}

#[derive(Debug, Clone, Serialize)]
struct MemoryStats {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct DiskStats {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp_unix_ms: u128,
    uptime_seconds: u64,
    cpu: CpuStats,
    memory: MemoryStats,
    disks: Vec<DiskStats>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug)]
struct SharedState {
    latest: RwLock<Option<SystemSnapshot>>,
    started_at: Instant,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Request {
    Ping,
    Stats,
    Top { limit: Option<usize> },
    Signal { pid: i32, signal: String },
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok { data: serde_json::Value },
    Error { message: String },
}

#[tokio::main]
async fn main() -> Result<()> {
    init_tracing();

    if Path::new(SOCKET_PATH).exists() {
        std::fs::remove_file(SOCKET_PATH)
            .with_context(|| format!("failed to remove stale socket {}", SOCKET_PATH))?;
    }

    let state = Arc::new(SharedState {
        latest: RwLock::new(None),
        started_at: Instant::now(),
    });

    let monitor_state = Arc::clone(&state);
    let server_state = Arc::clone(&state);

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = server_loop(server_state).await {
            error!("server loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received shutdown signal");
        }
        _ = monitor_task => {
            warn!("monitor task exited");
        }
        _ = server_task => {
            warn!("server task exited");
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        let _ = std::fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();
}

async fn monitor_loop(state: Arc<SharedState>) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything()),
    );

    // First refresh primes CPU usage calculations.
    system.refresh_all();
    time::sleep(Duration::from_millis(250)).await;

    let mut ticker = time::interval(SAMPLE_INTERVAL);

    loop {
        ticker.tick().await;

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_disks();
        system.refresh_processes();

        let snapshot = build_snapshot(&system, state.started_at.elapsed().as_secs());

        {
            let mut guard = state.latest.write().await;
            *guard = Some(snapshot);
        }
    }
}

fn build_snapshot(system: &System, uptime_seconds: u64) -> SystemSnapshot {
    let cpu = CpuStats {
        usage_percent: system.global_cpu_info().cpu_usage(),
        logical_cores: system.cpus().len(),
    };

    let total_memory = system.total_memory() * 1024;
    let used_memory = system.used_memory() * 1024;
    let free_memory = total_memory.saturating_sub(used_memory);

    let memory = MemoryStats {
        total_bytes: total_memory,
        used_bytes: used_memory,
        free_bytes: free_memory,
        used_percent: if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        },
    };

    let disks = system
        .disks()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            DiskStats {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_bytes: used,
                used_percent: if total > 0 {
                    (used as f32 / total as f32) * 100.0
                } else {
                    0.0
                },
            }
        })
        .collect::<Vec<_>>();

    let mut processes = system
        .processes()
        .iter()
        .map(|(pid, p)| ProcessInfo {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_percent: p.cpu_usage(),
            memory_bytes: p.memory() * 1024,
            virtual_memory_bytes: p.virtual_memory() * 1024,
            status: format!("{:?}", p.status()),
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
    });

    processes.truncate(TOP_N);

    SystemSnapshot {
        timestamp_unix_ms: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis(),
        uptime_seconds,
        cpu,
        memory,
        disks,
        top_processes: processes,
    }
}

async fn server_loop(state: Arc<SharedState>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket {}", SOCKET_PATH))?;

    info!("listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                warn!("client handler error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<SharedState>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let req: Request = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(e) => {
                let resp = Response::Error {
                    message: format!("invalid request: {e}"),
                };
                writer
                    .write_all((serde_json::to_string(&resp)? + "\n").as_bytes())
                    .await?;
                continue;
            }
        };

        let resp = process_request(req, &state).await;
        writer
            .write_all((serde_json::to_string(&resp)? + "\n").as_bytes())
            .await?;
    }

    Ok(())
}

async fn process_request(req: Request, state: &Arc<SharedState>) -> Response {
    match req {
        Request::Ping => Response::Ok {
            data: serde_json::json!({ "message": "pong" }),
        },
        Request::Stats => {
            let guard = state.latest.read().await;
            match guard.as_ref() {
                Some(snapshot) => Response::Ok {
                    data: serde_json::to_value(snapshot).unwrap_or_else(|_| {
                        serde_json::json!({ "error": "serialization failure" })
                    }),
                },
                None => Response::Error {
                    message: "stats not ready yet".to_string(),
                },
            }
        }
        Request::Top { limit } => {
            let guard = state.latest.read().await;
            match guard.as_ref() {
                Some(snapshot) => {
                    let limit = limit.unwrap_or(TOP_N).min(100);
                    Response::Ok {
                        data: serde_json::json!({
                            "top_processes": snapshot.top_processes.iter().take(limit).collect::<Vec<_>>()
                        }),
                    }
                }
                None => Response::Error {
                    message: "stats not ready yet".to_string(),
                },
            }
        }
        Request::Signal { pid, signal } => {
            let sig = match parse_signal(&signal) {
                Some(s) => s,
                None => {
                    return Response::Error {
                        message: format!("unsupported signal: {signal}"),
                    }
                }
            };

            match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response::Ok {
                    data: serde_json::json!({
                        "pid": pid,
                        "signal": signal,
                        "result": "sent"
                    }),
                },
                Err(e) => Response::Error {
                    message: format!("failed to signal pid {pid}: {e}"),
                },
            }
        }
    }
}

fn parse_signal(s: &str) -> Option<Signal> {
    let normalized = s.trim().to_uppercase();
    let normalized = normalized.strip_prefix("SIG").unwrap_or(&normalized);

    let mut map = HashMap::new();
    map.insert("TERM", Signal::SIGTERM);
    map.insert("KILL", Signal::SIGKILL);
    map.insert("INT", Signal::SIGINT);
    map.insert("HUP", Signal::SIGHUP);
    map.insert("STOP", Signal::SIGSTOP);
    map.insert("CONT", Signal::SIGCONT);

    map.get(normalized).copied()
}
