```rust
use crate::config::ThresholdConfig;
use crate::metrics::{
    CpuMetrics, DiskMetrics, MemoryMetrics, NetworkMetrics, SystemSnapshot,
};
use std::time::{SystemTime, UNIX_EPOCH};
use sysinfo::{Disks, Networks, System};

pub struct ResourceMonitor {
    system: System,
    disks: Disks,
    networks: Networks,
    thresholds: ThresholdConfig,
}

impl ResourceMonitor {
    pub fn new(thresholds: ThresholdConfig) -> Self {
        let mut system = System::new();
        system.refresh_cpu();
        system.refresh_memory();

        let disks = Disks::new_with_refreshed_list();
        let networks = Networks::new_with_refreshed_list();

        Self {
            system,
            disks,
            networks,
            thresholds,
        }
    }

    pub fn sample(&mut self) -> SystemSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.disks.refresh();
        self.networks.refresh();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let total_mem = self.system.total_memory();
        let used_mem = self.system.used_memory();
        let mem_usage = if total_mem == 0 {
            0.0
        } else {
            (used_mem as f32 / total_mem as f32) * 100.0
        };

        let disks = self
            .disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                let used = total.saturating_sub(avail);
                let usage = if total == 0 {
                    0.0
                } else {
                    (used as f32 / total as f32) * 100.0
                };

                DiskMetrics {
                    name: d.name().to_string_lossy().to_string(),
                    total_bytes: total,
                    available_bytes: avail,
                    usage_percent: usage,
                }
            })
            .collect::<Vec<_>>();

        let networks = self
            .networks
            .iter()
            .map(|(name, data)| NetworkMetrics {
                interface: name.to_string(),
                received_bytes: data.received(),
                transmitted_bytes: data.transmitted(),
            })
            .collect::<Vec<_>>();

        SystemSnapshot {
            timestamp_unix_secs: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            cpu: CpuMetrics {
                usage_percent: cpu_usage,
            },
            memory: MemoryMetrics {
                total_bytes: total_mem,
                used_bytes: used_mem,
                usage_percent: mem_usage,
            },
            disks,
            networks,
        }
    }

    pub fn check_thresholds(&self, snapshot: &SystemSnapshot) -> Vec<String> {
        let mut reasons = Vec::new();

        if snapshot.cpu.usage_percent >= self.thresholds.cpu_percent {
            reasons.push(format!(
                "cpu usage {:.2}% >= {:.2}%",
                snapshot.cpu.usage_percent, self.thresholds.cpu_percent
            ));
        }

        if snapshot.memory.usage_percent >= self.thresholds.memory_percent {
            reasons.push(format!(
                "memory usage {:.2}% >= {:.2}%",
                snapshot.memory.usage_percent, self.thresholds.memory_percent
            ));
        }

        for disk in &snapshot.disks {
            if disk.usage_percent >= self.thresholds.disk_percent {
                reasons.push(format!(
                    "disk {} usage {:.2}% >= {:.2}%",
                    disk.name, disk.usage_percent, self.thresholds.disk_percent
                ));
            }
        }

        reasons
    }
}
