# `src/control.rs`

```rust
use crate::metrics::SystemSnapshot;
use anyhow::Result;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
};
use tracing::{error, info};

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
pub enum ControlCommand {
    GetSnapshot,
    Ping,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ControlResponse {
    Pong,
    Snapshot { snapshot: SystemSnapshot },
    Error { message: String },
}

pub async fn serve_control_socket(
    socket_path: &std::path::Path,
    snapshot: Arc<RwLock<Option<SystemSnapshot>>>,
) -> Result<()> {
    if socket_path.exists() {
        std::fs::remove_file(socket_path)?;
    }

    let listener = UnixListener::bind(socket_path)?;
    info!(path = %socket_path.display(), "control socket listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let snapshot = Arc::clone(&snapshot);

        tokio::spawn(async move {
            if let Err(err) = handle_client(stream, snapshot).await {
                error!(error = %err, "control client error");
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    snapshot: Arc<RwLock<Option<SystemSnapshot>>>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Result<ControlCommand, _> = serde_json::from_str(&line);

        let response = match cmd {
            Ok(ControlCommand::Ping) => ControlResponse::Pong,
            Ok(ControlCommand::GetSnapshot) => {
                let guard = snapshot.read();
                match &*guard {
                    Some(s) => ControlResponse::Snapshot {
                        snapshot: s.clone(),
                    },
                    None => ControlResponse::Error {
                        message: "no snapshot available yet".into(),
                    },
                }
            }
            Err(err) => ControlResponse::Error {
                message: format!("invalid command: {err}"),
            },
        };

        let json = serde_json::to_string(&response)?;
        writer.write_all(json.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}
```

