use anyhow::Result;
use parking_lot::RwLock;
use std::sync::Arc;
use tokio::signal;
use tokio::time::{interval, MissedTickBehavior};
use tracing::{error, info};

pub struct SystemDaemon {
    config: DaemonConfig,
    snapshot: Arc<RwLock<Option<SystemSnapshot>>>,
    action_handler: Arc<dyn ActionHandler>,
}

impl SystemDaemon {
    pub fn new(config: DaemonConfig) -> Result<Self> {
        Ok(Self {
            config,
            snapshot: Arc::new(RwLock::new(None)),
            action_handler: Arc::new(LoggingActionHandler),
        })
    }

    pub async fn run(self) -> Result<()> {
        let snapshot_store = Arc::clone(&self.snapshot);
        let socket_path = self.config.socket_path.clone();

        let control_task = tokio::spawn(async move {
            if let Err(err) = serve_control_socket(&socket_path, snapshot_store).await {
                error!(error = %err, "control socket terminated");
            }
        });

        let mut monitor = ResourceMonitor::new(self.config.thresholds.clone());
        let mut ticker = interval(self.config.poll_interval);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);

        info!("system daemon started");

        tokio::select! {
            _ = async {
                loop {
                    ticker.tick().await;
                    let snapshot = monitor.sample();

                    {
                        let mut guard = self.snapshot.write();
                        *guard = Some(snapshot.clone());
                    }

                    for reason in monitor.check_thresholds(&snapshot) {
                        self.action_handler.on_threshold_exceeded(&snapshot, &reason);
                    }
                }
            } => {}
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
            }
        }

        control_task.abort();
        info!("system daemon stopped");
        Ok(())
    }
}
```

