```rust
use crate::types::*;
use std::time::SystemTime;
use sysinfo::{Disks, System};

pub struct MetricsCollector {
    sys: System,
    disks: Disks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();

        let disks = Disks::new_with_refreshed_list();

        Self { sys, disks }
    }

    pub fn collect(&mut self) -> SystemSnapshot {
        self.sys.refresh_cpu_usage();
        self.sys.refresh_memory();
        self.sys.refresh_processes();
        self.disks.refresh();

        let cpu = CpuMetrics {
            usage_percent: self.sys.global_cpu_usage(),
            core_count: self.sys.cpus().len(),
        };

        let total_memory = self.sys.total_memory();
        let used_memory = self.sys.used_memory();

        let memory = MemoryMetrics {
            total_bytes: total_memory * 1024,
            used_bytes: used_memory * 1024,
            used_percent: if total_memory > 0 {
                (used_memory as f32 / total_memory as f32) * 100.0
            } else {
                0.0
            },
        };

        let disks = self
            .disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                let used = total.saturating_sub(avail);
                let used_percent = if total > 0 {
                    (used as f32 / total as f32) * 100.0
                } else {
                    0.0
                };

                DiskMetrics {
                    name: d.name().to_string_lossy().to_string(),
                    total_bytes: total,
                    available_bytes: avail,
                    used_percent,
                }
            })
            .collect();

        let mut processes: Vec<ProcessMetrics> = self
            .sys
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessMetrics {
                pid: pid.as_u32(),
                name: proc_.name().to_string(),
                cpu_percent: proc_.cpu_usage(),
                memory_bytes: proc_.memory() * 1024,
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_percent
                .partial_cmp(&a.cpu_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(10);

        SystemSnapshot {
            timestamp: SystemTime::now(),
            cpu,
            memory,
            disks,
            top_processes: processes,
        }
    }
}
