# src/rules.rs

```rust
use crate::types::*;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use std::collections::HashMap;
use std::time::{Duration, Instant};
use tracing::{info, warn};

pub struct RuleEngine {
    rules: Vec<Rule>,
    last_triggered: HashMap<String, Instant>,
}

impl RuleEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules,
            last_triggered: HashMap::new(),
        }
    }

    pub fn evaluate(&mut self, snapshot: &SystemSnapshot) {
        for rule in &self.rules {
            if !self.cooldown_expired(rule) {
                continue;
            }

            if self.matches(rule, snapshot) {
                self.execute(&rule.action);
                self.last_triggered
                    .insert(rule.name.clone(), Instant::now());
            }
        }
    }

    fn cooldown_expired(&self, rule: &Rule) -> bool {
        match self.last_triggered.get(&rule.name) {
            Some(last) => last.elapsed() >= Duration::from_secs(rule.cooldown_secs),
            None => true,
        }
    }

    fn matches(&self, rule: &Rule, snapshot: &SystemSnapshot) -> bool {
        match &rule.condition {
            RuleCondition::CpuAbove(threshold) => snapshot.cpu.usage_percent > *threshold,
            RuleCondition::MemoryAbove(threshold) => snapshot.memory.used_percent > *threshold,
            RuleCondition::ProcessCpuAbove { pid, percent } => snapshot
                .top_processes
                .iter()
                .any(|p| p.pid == *pid && p.cpu_percent > *percent),
        }
    }

    fn execute(&self, action: &Action) {
        match action {
            Action::Log(msg) => {
                warn!("rule triggered: {}", msg);
            }
            Action::KillProcessByPid(pid) => {
                match kill(Pid::from_raw(*pid as i32), Signal::SIGTERM) {
                    Ok(_) => info!("sent SIGTERM to pid {}", pid),
                    Err(e) => warn!("failed to kill pid {}: {}", pid, e),
                }
            }
        }
    }
}
