# src/control.rs

```rust
use crate::types::SystemSnapshot;
use serde_json::json;
use std::path::Path;
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tracing::{error, info};

pub async fn run_control_socket(
    socket_path: &str,
    state: Arc<RwLock<Option<SystemSnapshot>>>,
) -> std::io::Result<()> {
    if Path::new(socket_path).exists() {
        std::fs::remove_file(socket_path)?;
    }

    let listener = UnixListener::bind(socket_path)?;
    info!("control socket listening on {}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("control client error: {}", e);
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<RwLock<Option<SystemSnapshot>>>,
) -> std::io::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd = line.trim();

    match cmd {
        "ping" => {
            writer.write_all(b"{\"status\":\"ok\"}\n").await?;
        }
        "snapshot" => {
            let guard = state.read().await;
            let payload = match &*guard {
                Some(snapshot) => serde_json::to_vec(snapshot).unwrap_or_else(|_| {
                    serde_json::to_vec(&json!({"error":"serialization failure"})).unwrap()
                }),
                None => serde_json::to_vec(&json!({"error":"no snapshot yet"})).unwrap(),
            };
            writer.write_all(&payload).await?;
            writer.write_all(b"\n").await?;
        }
        _ => {
            writer
                .write_all(b"{\"error\":\"unknown command\"}\n")
                .await?;
        }
    }

    Ok(())
}
