# src/daemon.rs

```rust
use crate::metrics::MetricsCollector;
use crate::rules::RuleEngine;
use crate::types::{Rule, SystemSnapshot};
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::{broadcast, RwLock};
use tracing::{error, info};

pub struct DaemonConfig {
    pub sample_interval: Duration,
    pub control_socket_path: String,
    pub rules: Vec<Rule>,
}

pub struct Daemon {
    config: DaemonConfig,
    latest_snapshot: Arc<RwLock<Option<SystemSnapshot>>>,
}

impl Daemon {
    pub fn new(config: DaemonConfig) -> Self {
        Self {
            config,
            latest_snapshot: Arc::new(RwLock::new(None)),
        }
    }

    pub async fn run(self) -> Result<(), Box<dyn std::error::Error>> {
        let (shutdown_tx, _) = broadcast::channel::<()>(8);

        let snapshot_state = self.latest_snapshot.clone();
        let control_state = self.latest_snapshot.clone();

        let mut shutdown_rx_metrics = shutdown_tx.subscribe();
        let mut shutdown_rx_control = shutdown_tx.subscribe();

        let sample_interval = self.config.sample_interval;
        let rules = self.config.rules.clone();
        let socket_path = self.config.control_socket_path.clone();

        let metrics_task = tokio::spawn(async move {
            let mut collector = MetricsCollector::new();
            let mut engine = RuleEngine::new(rules);
            let mut ticker = tokio::time::interval(sample_interval);

            loop {
                tokio::select! {
                    _ = ticker.tick() => {
                        let snapshot = collector.collect();
                        engine.evaluate(&snapshot);

                        let mut guard = snapshot_state.write().await;
                        *guard = Some(snapshot);
                    }
                    _ = shutdown_rx_metrics.recv() => {
                        info!("metrics task shutting down");
                        break;
                    }
                }
            }
        });

        let control_task = tokio::spawn(async move {
            tokio::select! {
                result = crate::control::run_control_socket(&socket_path, control_state) => {
                    if let Err(e) = result {
                        error!("control socket failed: {}", e);
                    }
                }
                _ = shutdown_rx_control.recv() => {
                    info!("control task shutting down");
                }
            }
        });

        tokio::signal::ctrl_c().await?;
        info!("shutdown signal received");

        let _ = shutdown_tx.send(());

        let _ = metrics_task.await;
        let _ = control_task.await;

        Ok(())
    }
}
