use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::fs;
use std::path::Path;
use std::sync::Arc;
use sysinfo::{
    CpuRefreshKind, DiskRefreshKind, Disks, MemoryRefreshKind, ProcessRefreshKind, ProcessesToUpdate,
    RefreshKind, System,
};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time::{sleep, Duration};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    poll_interval_secs: u64,
    socket_path: String,
    thresholds: Thresholds,
}

#[derive(Debug, Clone, Deserialize)]
struct Thresholds {
    cpu_percent: f32,
    memory_percent: f32,
    disk_percent: f32,
    top_process_count: usize,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    cpu_percent: f32,
    memory_total: u64,
    memory_used: u64,
    memory_percent: f32,
    disk_total: u64,
    disk_used: u64,
    disk_percent: f32,
    top_cpu_processes: Vec<ProcessInfo>,
    top_memory_processes: Vec<ProcessInfo>,
    timestamp_unix_secs: u64,
}

#[derive(Debug, Clone)]
struct SharedState {
    config: Config,
    metrics: Option<MetricsSnapshot>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let config = load_config("config.toml")?;
    let state = Arc::new(RwLock::new(SharedState {
        config: config.clone(),
        metrics: None,
    }));

    let monitor_state = Arc::clone(&state);
    let socket_state = Arc::clone(&state);

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let socket_task = tokio::spawn(async move {
        if let Err(e) = socket_server(socket_state).await {
            error!("socket server failed: {e:#}");
        }
    });

    tokio::select! {
        _ = monitor_task => {},
        _ = socket_task => {},
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    cleanup_socket(&config.socket_path)?;
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG")
                .unwrap_or_else(|_| "info,os_resource_daemon=debug".to_string()),
        )
        .init();
}

fn load_config(path: &str) -> Result<Config> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {path}"))?;
    let config: Config = toml::from_str(&raw)
        .with_context(|| format!("failed to parse config file: {path}"))?;
    Ok(config)
}

fn cleanup_socket(path: &str) -> Result<()> {
    if Path::new(path).exists() {
        fs::remove_file(path).with_context(|| format!("failed to remove socket: {path}"))?;
    }
    Ok(())
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything()),
    );

    let mut disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());

    loop {
        let config = {
            let guard = state.read().await;
            guard.config.clone()
        };

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_processes(ProcessesToUpdate::All, true);
        disks.refresh(true);

        let metrics = collect_metrics(&system, &disks, config.thresholds.top_process_count);

        evaluate_thresholds(&metrics, &config.thresholds);

        {
            let mut guard = state.write().await;
            guard.metrics = Some(metrics);
        }

        sleep(Duration::from_secs(config.poll_interval_secs)).await;
    }
}

fn collect_metrics(system: &System, disks: &Disks, top_n: usize) -> MetricsSnapshot {
    let cpu_percent = system.global_cpu_info().cpu_usage();

    let memory_total = system.total_memory();
    let memory_used = system.used_memory();
    let memory_percent = if memory_total == 0 {
        0.0
    } else {
        (memory_used as f32 / memory_total as f32) * 100.0
    };

    let mut disk_total = 0u64;
    let mut disk_used = 0u64;
    for disk in disks.list() {
        let total = disk.total_space();
        let available = disk.available_space();
        disk_total += total;
        disk_used += total.saturating_sub(available);
    }

    let disk_percent = if disk_total == 0 {
        0.0
    } else {
        (disk_used as f32 / disk_total as f32) * 100.0
    };

    let mut processes: Vec<ProcessInfo> = system
        .processes()
        .iter()
        .map(|(pid, process)| ProcessInfo {
            pid: pid.as_u32() as i32,
            name: process.name().to_string(),
            cpu_percent: process.cpu_usage(),
            memory_bytes: process.memory(),
        })
        .collect();

    let mut top_cpu_processes = processes.clone();
    top_cpu_processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(Ordering::Equal)
    });
    top_cpu_processes.truncate(top_n);

    processes.sort_by(|a, b| b.memory_bytes.cmp(&a.memory_bytes));
    processes.truncate(top_n);
    let top_memory_processes = processes;

    let timestamp_unix_secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    MetricsSnapshot {
        cpu_percent,
        memory_total,
        memory_used,
        memory_percent,
        disk_total,
        disk_used,
        disk_percent,
        top_cpu_processes,
        top_memory_processes,
        timestamp_unix_secs,
    }
}

fn evaluate_thresholds(metrics: &MetricsSnapshot, thresholds: &Thresholds) {
    if metrics.cpu_percent >= thresholds.cpu_percent {
        warn!(
            "cpu threshold exceeded: current={:.2}% threshold={:.2}%",
            metrics.cpu_percent, thresholds.cpu_percent
        );
    }

    if metrics.memory_percent >= thresholds.memory_percent {
        warn!(
            "memory threshold exceeded: current={:.2}% threshold={:.2}%",
            metrics.memory_percent, thresholds.memory_percent
        );
    }

    if metrics.disk_percent >= thresholds.disk_percent {
        warn!(
            "disk threshold exceeded: current={:.2}% threshold={:.2}%",
            metrics.disk_percent, thresholds.disk_percent
        );
    }
}

async fn socket_server(state: Arc<RwLock<SharedState>>) -> Result<()> {
    let socket_path = {
        let guard = state.read().await;
        guard.config.socket_path.clone()
    };

    cleanup_socket(&socket_path)?;
    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket: {socket_path}"))?;

    info!("control socket listening at {}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("client handling failed: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"os-resource-daemon ready\n")
        .await
        .context("failed to write greeting")?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let command = line.trim();
        let response = process_command(command, &state).await;
        writer.write_all(response.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn process_command(command: &str, state: &Arc<RwLock<SharedState>>) -> String {
    let parts: Vec<&str> = command.split_whitespace().collect();
    if parts.is_empty() {
        return "error: empty command".to_string();
    }

    match parts[0] {
        "status" => {
            let guard = state.read().await;
            match &guard.metrics {
                Some(metrics) => format!(
                    "cpu={:.2}% mem={:.2}% disk={:.2}% ts={}",
                    metrics.cpu_percent,
                    metrics.memory_percent,
                    metrics.disk_percent,
                    metrics.timestamp_unix_secs
                ),
                None => "no metrics yet".to_string(),
            }
        }
        "top" => {
            let guard = state.read().await;
            match &guard.metrics {
                Some(metrics) => {
                    let mut out = String::new();
                    out.push_str("top_cpu:\n");
                    for p in &metrics.top_cpu_processes {
                        out.push_str(&format!(
                            "  pid={} name={} cpu={:.2}% mem={}\n",
                            p.pid, p.name, p.cpu_percent, p.memory_bytes
                        ));
                    }
                    out.push_str("top_memory:\n");
                    for p in &metrics.top_memory_processes {
                        out.push_str(&format!(
                            "  pid={} name={} cpu={:.2}% mem={}\n",
                            p.pid, p.name, p.cpu_percent, p.memory_bytes
                        ));
                    }
                    out
                }
                None => "no metrics yet".to_string(),
            }
        }
        "reload" => {
            match load_config("config.toml") {
                Ok(new_config) => {
                    let mut guard = state.write().await;
                    guard.config = new_config;
                    "config reloaded".to_string()
                }
                Err(e) => format!("error: failed to reload config: {e:#}"),
            }
        }
        "kill" => {
            if parts.len() != 2 {
                return "usage: kill <pid>".to_string();
            }

            match parts[1].parse::<i32>() {
                Ok(pid) => match kill(Pid::from_raw(pid), Signal::SIGTERM) {
                    Ok(_) => format!("sent SIGTERM to pid {}", pid),
                    Err(e) => format!("error: failed to kill pid {}: {}", pid, e),
                },
                Err(_) => "error: invalid pid".to_string(),
            }
        }
        "help" => "commands: status, top, reload, kill <pid>, help".to_string(),
        _ => "error: unknown command".to_string(),
    }
}
