use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};

use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use serde::Serialize;
use sysinfo::{Disks, System};
use tokio::sync::RwLock;
use tracing::{error, info};

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    total_disk_bytes: u64,
    available_disk_bytes: u64,
    timestamp_unix_secs: u64,
}

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<Metrics>>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = AppState {
        metrics: Arc::new(RwLock::new(Metrics::default())),
    };

    spawn_sampler(state.clone());

    let app = Router::new()
        .route("/health", get(health))
        .route("/metrics", get(get_metrics))
        .route("/manage/drop_caches", post(drop_caches))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    info!("starting daemon on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    info!("daemon stopped");
    Ok(())
}

fn spawn_sampler(state: AppState) {
    tokio::spawn(async move {
        let mut sys = System::new_all();
        let mut disks = Disks::new_with_refreshed_list();
        let interval = Duration::from_secs(2);

        loop {
            sys.refresh_cpu_usage();
            sys.refresh_memory();
            disks.refresh();

            let cpu = sys.global_cpu_usage();
            let total_mem = sys.total_memory();
            let used_mem = sys.used_memory();
            let total_swap = sys.total_swap();
            let used_swap = sys.used_swap();

            let mut total_disk = 0u64;
            let mut available_disk = 0u64;
            for d in disks.list() {
                total_disk += d.total_space();
                available_disk += d.available_space();
            }

            let timestamp_unix_secs = match std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
            {
                Ok(d) => d.as_secs(),
                Err(_) => 0,
            };

            let next = Metrics {
                cpu_usage_percent: cpu,
                total_memory_bytes: total_mem * 1024,
                used_memory_bytes: used_mem * 1024,
                total_swap_bytes: total_swap * 1024,
                used_swap_bytes: used_swap * 1024,
                total_disk_bytes: total_disk,
                available_disk_bytes: available_disk,
                timestamp_unix_secs,
            };

            {
                let mut guard = state.metrics.write().await;
                *guard = next;
            }

            tokio::time::sleep(interval).await;
        }
    });
}

async fn health() -> impl IntoResponse {
    (StatusCode::OK, "ok")
}

async fn get_metrics(State(state): State<AppState>) -> impl IntoResponse {
    let metrics = state.metrics.read().await.clone();
    Json(metrics)
}

async fn drop_caches() -> impl IntoResponse {
    #[cfg(target_os = "linux")]
    {
        use tokio::process::Command;

        let result = Command::new("sh")
            .arg("-c")
            .arg("sync && echo 3 > /proc/sys/vm/drop_caches")
            .output()
            .await;

        match result {
            Ok(output) if output.status.success() => {
                (StatusCode::OK, "caches dropped").into_response()
            }
            Ok(output) => {
                let msg = format!(
                    "command failed: status={:?}, stderr={}",
                    output.status.code(),
                    String::from_utf8_lossy(&output.stderr)
                );
                (StatusCode::INTERNAL_SERVER_ERROR, msg).into_response()
            }
            Err(e) => {
                error!("drop_caches error: {}", e);
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    format!("execution error: {}", e),
                )
                    .into_response()
            }
        }
    }

    #[cfg(not(target_os = "linux"))]
    {
        (
            StatusCode::NOT_IMPLEMENTED,
            "drop_caches is only implemented on Linux",
        )
            .into_response()
    }
}

async fn shutdown_signal() {
    let ctrl_c = async {
        let _ = tokio::signal::ctrl_c().await;
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        if let Ok(mut sigterm) = signal(SignalKind::terminate()) {
            sigterm.recv().await;
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}
