use anyhow::{Context, Result};
use serde::Serialize;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const SOCKET_PATH: &str = "/tmp/sysdaemon.sock";

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp_ms: u128,
    mem_total_kb: u64,
    mem_available_kb: u64,
    loadavg_1m: f32,
    loadavg_5m: f32,
    loadavg_15m: f32,
    cpu_usage_pct: f32,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            timestamp_ms: 0,
            mem_total_kb: 0,
            mem_available_kb: 0,
            loadavg_1m: 0.0,
            loadavg_5m: 0.0,
            loadavg_15m: 0.0,
            cpu_usage_pct: 0.0,
        }
    }
}

#[derive(Debug)]
struct DaemonState {
    interval: Duration,
    throttle_enabled: bool,
    latest: Metrics,
}

impl Default for DaemonState {
    fn default() -> Self {
        Self {
            interval: Duration::from_millis(1000),
            throttle_enabled: false,
            latest: Metrics::default(),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct CpuSample {
    idle: u64,
    total: u64,
}

fn read_meminfo() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
    let mut total = 0;
    let mut available = 0;

    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("MemTotal:") {
            total = rest.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
            available = rest.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        }
    }

    Ok((total, available))
}

fn read_loadavg() -> Result<(f32, f32, f32)> {
    let content = fs::read_to_string("/proc/loadavg").context("reading /proc/loadavg")?;
    let mut parts = content.split_whitespace();
    let l1 = parts.next().unwrap_or("0").parse().unwrap_or(0.0);
    let l5 = parts.next().unwrap_or("0").parse().unwrap_or(0.0);
    let l15 = parts.next().unwrap_or("0").parse().unwrap_or(0.0);
    Ok((l1, l5, l15))
}

fn read_cpu_sample() -> Result<CpuSample> {
    let content = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
    let first = content.lines().next().unwrap_or("");
    let mut parts = first.split_whitespace();

    let tag = parts.next().unwrap_or("");
    if tag != "cpu" {
        anyhow::bail!("unexpected /proc/stat format");
    }

    let values: Vec<u64> = parts.map(|p| p.parse().unwrap_or(0)).collect();
    let idle = values.get(3).copied().unwrap_or(0) + values.get(4).copied().unwrap_or(0);
    let total: u64 = values.iter().sum();

    Ok(CpuSample { idle, total })
}

fn cpu_usage_pct(prev: CpuSample, curr: CpuSample) -> f32 {
    let idle_delta = curr.idle.saturating_sub(prev.idle);
    let total_delta = curr.total.saturating_sub(prev.total);

    if total_delta == 0 {
        0.0
    } else {
        100.0 * (1.0 - (idle_delta as f32 / total_delta as f32))
    }
}

fn collect_metrics(prev_cpu: &mut Option<CpuSample>, start: Instant) -> Result<Metrics> {
    let (mem_total_kb, mem_available_kb) = read_meminfo()?;
    let (loadavg_1m, loadavg_5m, loadavg_15m) = read_loadavg()?;
    let curr_cpu = read_cpu_sample()?;

    let cpu_usage_pct = if let Some(prev) = prev_cpu {
        cpu_usage_pct(*prev, curr_cpu)
    } else {
        0.0
    };

    *prev_cpu = Some(curr_cpu);

    Ok(Metrics {
        timestamp_ms: start.elapsed().as_millis(),
        mem_total_kb,
        mem_available_kb,
        loadavg_1m,
        loadavg_5m,
        loadavg_15m,
        cpu_usage_pct,
    })
}

fn handle_client(
    mut stream: UnixStream,
    state: Arc<Mutex<DaemonState>>,
    running: Arc<AtomicBool>,
) -> Result<()> {
    let reader_stream = stream.try_clone().context("cloning stream")?;
    let mut reader = BufReader::new(reader_stream);

    let mut line = String::new();
    reader.read_line(&mut line).context("reading command")?;
    let cmd = line.trim();

    let response = match cmd {
        "status" => {
            let state = state.lock().unwrap();
            serde_json::to_string(&state.latest)?
        }
        "throttle on" => {
            let mut state = state.lock().unwrap();
            state.throttle_enabled = true;
            "{\"ok\":true,\"throttle_enabled\":true}".to_string()
        }
        "throttle off" => {
            let mut state = state.lock().unwrap();
            state.throttle_enabled = false;
            "{\"ok\":true,\"throttle_enabled\":false}".to_string()
        }
        "quit" => {
            running.store(false, Ordering::SeqCst);
            "{\"ok\":true,\"shutting_down\":true}".to_string()
        }
        _ if cmd.starts_with("set interval ") => {
            let value = cmd.trim_start_matches("set interval ").trim();
            match value.parse::<u64>() {
                Ok(ms) if ms >= 100 => {
                    let mut state = state.lock().unwrap();
                    state.interval = Duration::from_millis(ms);
                    format!("{{\"ok\":true,\"interval_ms\":{}}}", ms)
                }
                _ => "{\"ok\":false,\"error\":\"interval must be integer >= 100 ms\"}".to_string(),
            }
        }
        _ => "{\"ok\":false,\"error\":\"unknown command\"}".to_string(),
    };

    writeln!(stream, "{response}").context("writing response")?;
    Ok(())
}

fn command_server(state: Arc<Mutex<DaemonState>>, running: Arc<AtomicBool>) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("removing stale socket")?;
    }

    let listener = UnixListener::bind(SOCKET_PATH).context("binding unix socket")?;
    listener
        .set_nonblocking(true)
        .context("setting nonblocking")?;

    while running.load(Ordering::SeqCst) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let state = Arc::clone(&state);
                let running = Arc::clone(&running);
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, state, running) {
                        eprintln!("client error: {e:#}");
                    }
                });
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                eprintln!("accept error: {e}");
                thread::sleep(Duration::from_millis(200));
            }
        }
    }

    fs::remove_file(SOCKET_PATH).ok();
    Ok(())
}

fn monitor_loop(state: Arc<Mutex<DaemonState>>, running: Arc<AtomicBool>) {
    let start = Instant::now();
    let mut prev_cpu = None;

    while running.load(Ordering::SeqCst) {
        let interval = {
            let state = state.lock().unwrap();
            state.interval
        };

        match collect_metrics(&mut prev_cpu, start) {
            Ok(metrics) => {
                let mut state = state.lock().unwrap();
                state.latest = metrics;

                if state.throttle_enabled {
                    // Placeholder for real management action.
                    // In a production daemon, this might adjust cgroups,
                    // process priorities, or scheduler settings.
                }
            }
            Err(e) => eprintln!("metrics collection error: {e:#}"),
        }

        thread::sleep(interval);
    }
}

fn main() -> Result<()> {
    let state = Arc::new(Mutex::new(DaemonState::default()));
    let running = Arc::new(AtomicBool::new(true));

    let monitor_state = Arc::clone(&state);
    let monitor_running = Arc::clone(&running);
    let monitor_thread = thread::spawn(move || {
        monitor_loop(monitor_state, monitor_running);
    });

    let server_result = command_server(Arc::clone(&state), Arc::clone(&running));

    running.store(false, Ordering::SeqCst);
    let _ = monitor_thread.join();

    server_result
}
