```rust
use serde::Serialize;
use std::{
    fs,
    io,
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::RwLock,
    time::sleep,
};

const SOCKET_PATH: &str = "/tmp/resourced.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    timestamp: u64,
    cpu_usage_percent: f32,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_percent: f32,
    disk_total_bytes: u64,
    disk_available_bytes: u64,
    disk_used_percent: f32,
}

#[derive(Default)]
struct CpuSnapshot {
    total: u64,
    idle: u64,
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn read_cpu_snapshot() -> io::Result<CpuSnapshot> {
    let stat = fs::read_to_string("/proc/stat")?;
    let first = stat
        .lines()
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "missing /proc/stat line"))?;

    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(io::Error::new(io::ErrorKind::Other, "invalid /proc/stat format"));
    }

    let nums: Vec<u64> = parts[1..]
        .iter()
        .map(|s| s.parse::<u64>().unwrap_or(0))
        .collect();

    let idle = nums.get(3).copied().unwrap_or(0) + nums.get(4).copied().unwrap_or(0);
    let total = nums.iter().sum();

    Ok(CpuSnapshot { total, idle })
}

fn cpu_usage(prev: &CpuSnapshot, curr: &CpuSnapshot) -> f32 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    let used = total_delta.saturating_sub(idle_delta);
    (used as f32) * 100.0 / (total_delta as f32)
}

fn read_meminfo() -> io::Result<(u64, u64)> {
    let meminfo = fs::read_to_string("/proc/meminfo")?;
    let mut total = 0;
    let mut available = 0;

    for line in meminfo.lines() {
        if let Some(v) = line.strip_prefix("MemTotal:") {
            total = v.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        } else if let Some(v) = line.strip_prefix("MemAvailable:") {
            available = v.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        }
    }

    Ok((total, available))
}

fn read_disk_usage(path: &str) -> io::Result<(u64, u64)> {
    let c_path = std::ffi::CString::new(path).unwrap();
    let mut stat: libc::statvfs = unsafe { std::mem::zeroed() };

    let rc = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
    if rc != 0 {
        return Err(io::Error::last_os_error());
    }

    let total = stat.f_blocks as u64 * stat.f_frsize as u64;
    let avail = stat.f_bavail as u64 * stat.f_frsize as u64;
    Ok((total, avail))
}

async fn sampler_loop(shared: Arc<RwLock<Metrics>>, running: Arc<AtomicBool>) {
    let mut prev_cpu = match read_cpu_snapshot() {
        Ok(s) => s,
        Err(_) => CpuSnapshot::default(),
    };

    while running.load(Ordering::Relaxed) {
        sleep(SAMPLE_INTERVAL).await;

        let curr_cpu = read_cpu_snapshot().unwrap_or_default();
        let cpu = cpu_usage(&prev_cpu, &curr_cpu);
        prev_cpu = curr_cpu;

        let (mem_total, mem_avail) = read_meminfo().unwrap_or((0, 0));
        let mem_used_pct = if mem_total == 0 {
            0.0
        } else {
            ((mem_total.saturating_sub(mem_avail)) as f32) * 100.0 / (mem_total as f32)
        };

        let (disk_total, disk_avail) = read_disk_usage("/").unwrap_or((0, 0));
        let disk_used_pct = if disk_total == 0 {
            0.0
        } else {
            ((disk_total.saturating_sub(disk_avail)) as f32) * 100.0 / (disk_total as f32)
        };

        let metrics = Metrics {
            timestamp: now_ts(),
            cpu_usage_percent: cpu,
            mem_total_kb: mem_total,
            mem_available_kb: mem_avail,
            mem_used_percent: mem_used_pct,
            disk_total_bytes: disk_total,
            disk_available_bytes: disk_avail,
            disk_used_percent: disk_used_pct,
        };

        let mut guard = shared.write().await;
        *guard = metrics;
    }
}

async fn handle_client(
    stream: UnixStream,
    shared: Arc<RwLock<Metrics>>,
    running: Arc<AtomicBool>,
) -> io::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        match line.trim() {
            "status" => {
                let metrics = shared.read().await.clone();
                let json = serde_json::to_string(&metrics).unwrap();
                writer.write_all(json.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "quit" => {
                running.store(false, Ordering::Relaxed);
                writer.write_all(b"shutting down\n").await?;
                break;
            }
            _ => {
                writer.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}

async fn server_loop(shared: Arc<RwLock<Metrics>>, running: Arc<AtomicBool>) -> io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;

    while running.load(Ordering::Relaxed) {
        let accept = listener.accept().await;
        let (stream, _) = match accept {
            Ok(v) => v,
            Err(e) => {
                if running.load(Ordering::Relaxed) {
                    eprintln!("accept error: {e}");
                }
                continue;
            }
        };

        let shared = Arc::clone(&shared);
        let running = Arc::clone(&running);

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, shared, running).await {
                eprintln!("client error: {e}");
            }
        });
    }

    let _ = fs::remove_file(SOCKET_PATH);
    Ok(())
}

#[tokio::main]
async fn main() -> io::Result<()> {
    let shared = Arc::new(RwLock::new(Metrics::default()));
    let running = Arc::new(AtomicBool::new(true));

    let sampler = tokio::spawn(sampler_loop(
        Arc::clone(&shared),
        Arc::clone(&running),
    ));

    let server = server_loop(Arc::clone(&shared), Arc::clone(&running)).await;

    running.store(false, Ordering::Relaxed);
    let _ = sampler.await;

    server
}
