## `main.go`

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"
)

type Metrics struct {
	Timestamp   time.Time `json:"timestamp"`
	CPUPercent  float64   `json:"cpu_percent"`
	MemTotalKB  uint64    `json:"mem_total_kb"`
	MemFreeKB   uint64    `json:"mem_free_kb"`
	MemAvailKB  uint64    `json:"mem_available_kb"`
	UptimeSec   float64   `json:"uptime_sec"`
}

var latest Metrics

func readUptime() float64 {
	data, err := os.ReadFile("/proc/uptime")
	if err != nil {
		return 0
	}
	var up float64
	_, err = fmtSscanf(string(data), &up)
	if err != nil {
		return 0
	}
	return up
}

func fmtSscanf(s string, out *float64) (int, error) {
	var field string
	for i := 0; i < len(s); i++ {
		if s[i] == ' ' || s[i] == '\t' || s[i] == '\n' {
			field = s[:i]
			break
		}
	}
	if field == "" {
		field = s
	}
	v, err := strconv.ParseFloat(field, 64)
	if err != nil {
		return 0, err
	}
	*out = v
	return 1, nil
}

func readMeminfo() (total, free, avail uint64) {
	data, err := os.ReadFile("/proc/meminfo")
	if err != nil {
		return
	}
	lines := splitLines(string(data))
	for _, line := range lines {
		if hasPrefix(line, "MemTotal:") {
			total = parseKB(line)
		} else if hasPrefix(line, "MemFree:") {
			free = parseKB(line)
		} else if hasPrefix(line, "MemAvailable:") {
			avail = parseKB(line)
		}
	}
	return
}

func readCPUStat() (idle, total uint64) {
	data, err := os.ReadFile("/proc/stat")
	if err != nil {
		return
	}
	lines := splitLines(string(data))
	if len(lines) == 0 || !hasPrefix(lines[0], "cpu ") {
		return
	}
	fields := splitFields(lines[0])
	if len(fields) < 8 {
		return
	}
	for i := 1; i < len(fields); i++ {
		v, err := strconv.ParseUint(fields[i], 10, 64)
		if err != nil {
			continue
		}
		total += v
		if i == 4 || i == 5 {
			idle += v
		}
	}
	return
}

func sampleCPUPercent(interval time.Duration) float64 {
	idle1, total1 := readCPUStat()
	time.Sleep(interval)
	idle2, total2 := readCPUStat()

	idleTicks := idle2 - idle1
	totalTicks := total2 - total1
	if totalTicks == 0 {
		return 0
	}
	used := float64(totalTicks-idleTicks) / float64(totalTicks) * 100.0
	return used
}

func collector(stop <-chan struct{}) {
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()

	for {
		cpu := sampleCPUPercent(500 * time.Millisecond)
		total, free, avail := readMeminfo()
		latest = Metrics{
			Timestamp:  time.Now().UTC(),
			CPUPercent: cpu,
			MemTotalKB: total,
			MemFreeKB:  free,
			MemAvailKB: avail,
			UptimeSec:  readUptime(),
		}

		log.Printf("cpu=%.2f%% mem_total=%dKB mem_free=%dKB mem_avail=%dKB uptime=%.0fs",
			latest.CPUPercent, latest.MemTotalKB, latest.MemFreeKB, latest.MemAvailKB, latest.UptimeSec)

		select {
		case <-stop:
			return
		case <-ticker.C:
		}
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status": "ok",
	})
}

func metricsHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(latest)
}

func main() {
	stop := make(chan struct{})
	go collector(stop)

	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", healthHandler)
	mux.HandleFunc("/metrics", metricsHandler)

	srv := &http.Server{
		Addr:    "127.0.0.1:8080",
		Handler: mux,
	}

	go func() {
		log.Println("daemon listening on http://127.0.0.1:8080")
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("http server error: %v", err)
		}
	}()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	close(stop)
	log.Println("shutting down")
}
