```rust
use std::{
    fs,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    thread,
    time::Duration,
};

#[derive(Debug, Clone, Copy)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuTimes {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn idle_total(&self) -> u64 {
        self.idle + self.iowait
    }
}

fn read_cpu_times() -> Option<CpuTimes> {
    let content = fs::read_to_string("/proc/stat").ok()?;
    let first = content.lines().next()?;
    let mut parts = first.split_whitespace();

    if parts.next()? != "cpu" {
        return None;
    }

    Some(CpuTimes {
        user: parts.next()?.parse().ok()?,
        nice: parts.next()?.parse().ok()?,
        system: parts.next()?.parse().ok()?,
        idle: parts.next()?.parse().ok()?,
        iowait: parts.next()?.parse().ok()?,
        irq: parts.next()?.parse().ok()?,
        softirq: parts.next()?.parse().ok()?,
        steal: parts.next().unwrap_or("0").parse().ok()?,
    })
}

fn cpu_usage_percent(prev: CpuTimes, curr: CpuTimes) -> f64 {
    let total_delta = curr.total().saturating_sub(prev.total());
    let idle_delta = curr.idle_total().saturating_sub(prev.idle_total());

    if total_delta == 0 {
        0.0
    } else {
        100.0 * (total_delta - idle_delta) as f64 / total_delta as f64
    }
}

fn read_mem_usage() -> Option<(u64, u64, f64)> {
    let content = fs::read_to_string("/proc/meminfo").ok()?;

    let mut total_kb = None;
    let mut available_kb = None;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line.split_whitespace().nth(1)?.parse::<u64>().ok();
        } else if line.starts_with("MemAvailable:") {
            available_kb = line.split_whitespace().nth(1)?.parse::<u64>().ok();
        }

        if total_kb.is_some() && available_kb.is_some() {
            break;
        }
    }

    let total = total_kb?;
    let available = available_kb?;
    let used = total.saturating_sub(available);
    let percent = if total == 0 {
        0.0
    } else {
        100.0 * used as f64 / total as f64
    };

    Some((used, total, percent))
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    })
    .expect("failed to set signal handler");

    println!("resource_daemon starting");

    let mut prev_cpu = match read_cpu_times() {
        Some(v) => v,
        None => {
            eprintln!("failed to read /proc/stat");
            return;
        }
    };

    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_secs(2));

        let curr_cpu = match read_cpu_times() {
            Some(v) => v,
            None => {
                eprintln!("failed to read /proc/stat");
                continue;
            }
        };

        let cpu = cpu_usage_percent(prev_cpu, curr_cpu);
        prev_cpu = curr_cpu;

        match read_mem_usage() {
            Some((used_kb, total_kb, mem_pct)) => {
                println!(
                    "cpu={:.2}% mem={:.2}% used={}MB total={}MB",
                    cpu,
                    mem_pct,
                    used_kb / 1024,
                    total_kb / 1024
                );
            }
            None => {
                println!("cpu={:.2}% mem=unavailable", cpu);
            }
        }
    }

    println!("resource_daemon shutting down");
}
