## `src/main.rs`

```rust
use serde::Serialize;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const SOCK_PATH: &str = "/tmp/safe_monitor_daemon.sock";

#[derive(Serialize, Clone, Default)]
struct CpuSample {
    usage_percent: f64,
}

#[derive(Serialize, Clone, Default)]
struct MemSample {
    total_kb: u64,
    available_kb: u64,
    used_kb: u64,
}

#[derive(Serialize, Clone, Default)]
struct DiskSample {
    path: String,
    total_bytes: u64,
    free_bytes: u64,
    used_bytes: u64,
}

#[derive(Serialize, Clone, Default)]
struct Status {
    timestamp: u64,
    loadavg_1m: f64,
    loadavg_5m: f64,
    loadavg_15m: f64,
    cpu: CpuSample,
    memory: MemSample,
    disk: DiskSample,
}

#[derive(Clone, Copy, Default)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuTimes {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn idle_all(&self) -> u64 {
        self.idle + self.iowait
    }
}

fn read_loadavg() -> std::io::Result<(f64, f64, f64)> {
    let s = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = s.split_whitespace().collect();
    let a = parts.get(0).and_then(|x| x.parse().ok()).unwrap_or(0.0);
    let b = parts.get(1).and_then(|x| x.parse().ok()).unwrap_or(0.0);
    let c = parts.get(2).and_then(|x| x.parse().ok()).unwrap_or(0.0);
    Ok((a, b, c))
}

fn read_meminfo() -> std::io::Result<MemSample> {
    let s = fs::read_to_string("/proc/meminfo")?;
    let mut total = 0u64;
    let mut available = 0u64;

    for line in s.lines() {
        if let Some(v) = line.strip_prefix("MemTotal:") {
            total = v.split_whitespace().next().and_then(|x| x.parse().ok()).unwrap_or(0);
        } else if let Some(v) = line.strip_prefix("MemAvailable:") {
            available = v.split_whitespace().next().and_then(|x| x.parse().ok()).unwrap_or(0);
        }
    }

    Ok(MemSample {
        total_kb: total,
        available_kb: available,
        used_kb: total.saturating_sub(available),
    })
}

fn read_cpu_times() -> std::io::Result<CpuTimes> {
    let s = fs::read_to_string("/proc/stat")?;
    let line = s.lines().next().unwrap_or("");
    let parts: Vec<&str> = line.split_whitespace().collect();

    if parts.len() < 8 || parts[0] != "cpu" {
        return Ok(CpuTimes::default());
    }

    Ok(CpuTimes {
        user: parts.get(1).and_then(|x| x.parse().ok()).unwrap_or(0),
        nice: parts.get(2).and_then(|x| x.parse().ok()).unwrap_or(0),
        system: parts.get(3).and_then(|x| x.parse().ok()).unwrap_or(0),
        idle: parts.get(4).and_then(|x| x.parse().ok()).unwrap_or(0),
        iowait: parts.get(5).and_then(|x| x.parse().ok()).unwrap_or(0),
        irq: parts.get(6).and_then(|x| x.parse().ok()).unwrap_or(0),
        softirq: parts.get(7).and_then(|x| x.parse().ok()).unwrap_or(0),
        steal: parts.get(8).and_then(|x| x.parse().ok()).unwrap_or(0),
    })
}

fn cpu_usage(prev: CpuTimes, curr: CpuTimes) -> f64 {
    let totald = curr.total().saturating_sub(prev.total()) as f64;
    let idled = curr.idle_all().saturating_sub(prev.idle_all()) as f64;
    if totald <= 0.0 {
        0.0
    } else {
        ((totald - idled) / totald) * 100.0
    }
}

fn disk_usage(path: &str) -> std::io::Result<DiskSample> {
    use std::ffi::CString;
    let c_path = CString::new(path).unwrap();

    let mut stat: libc::statvfs = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error());
    }

    let total = stat.f_blocks as u64 * stat.f_frsize as u64;
    let free = stat.f_bavail as u64 * stat.f_frsize as u64;
    let used = total.saturating_sub(free);

    Ok(DiskSample {
        path: path.to_string(),
        total_bytes: total,
        free_bytes: free,
        used_bytes: used,
    })
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs()
}

fn collect_status(prev_cpu: CpuTimes, curr_cpu: CpuTimes) -> Status {
    let (l1, l5, l15) = read_loadavg().unwrap_or((0.0, 0.0, 0.0));
    let mem = read_meminfo().unwrap_or_default();
    let disk = disk_usage("/").unwrap_or_default();

    Status {
        timestamp: now_ts(),
        loadavg_1m: l1,
        loadavg_5m: l5,
        loadavg_15m: l15,
        cpu: CpuSample {
            usage_percent: cpu_usage(prev_cpu, curr_cpu),
        },
        memory: mem,
        disk,
    }
}

fn handle_client(mut stream: UnixStream, latest: &Status, running: &Arc<AtomicBool>) -> std::io::Result<()> {
    let mut line = String::new();
    {
        let mut reader = BufReader::new(&stream);
        reader.read_line(&mut line)?;
    }

    match line.trim() {
        "status" => {
            let body = serde_json::to_string_pretty(latest).unwrap();
            stream.write_all(body.as_bytes())?;
            stream.write_all(b"\n")?;
        }
        "quit" => {
            running.store(false, Ordering::SeqCst);
            stream.write_all(b"{\"ok\":true}\n")?;
        }
        _ => {
            stream.write_all(b"{\"error\":\"unknown command\"}\n")?;
        }
    }
    Ok(())
}

fn main() -> std::io::Result<()> {
    if Path::new(SOCK_PATH).exists() {
        let _ = fs::remove_file(SOCK_PATH);
    }

    let listener = UnixListener::bind(SOCK_PATH)?;
    listener.set_nonblocking(true)?;

    let running = Arc::new(AtomicBool::new(true));
    let mut prev_cpu = read_cpu_times().unwrap_or_default();
    let mut latest = Status::default();

    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_secs(1));
        let curr_cpu = read_cpu_times().unwrap_or_default();
        latest = collect_status(prev_cpu, curr_cpu);
        prev_cpu = curr_cpu;

        loop {
            match listener.accept() {
                Ok((stream, _addr)) => {
                    let _ = handle_client(stream, &latest, &running);
                }
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
                Err(_) => break,
            }
        }
    }

    let _ = fs::remove_file(SOCK_PATH);
    Ok(())
}
```

