### `src/main.rs`

```rust
use serde::Serialize;
use signal_hook::consts::{SIGINT, SIGTERM};
use signal_hook::flag;
use std::fs;
use std::io;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Debug, Serialize)]
struct Sample {
    ts: u64,
    cpu_usage_pct: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_pct: f64,
    load1: f64,
    load5: f64,
    load15: f64,
    disk_reads_completed: u64,
    disk_writes_completed: u64,
}

#[derive(Debug, Default, Clone, Copy)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuTimes {
    fn total(&self) -> u64 {
        self.user
            + self.nice
            + self.system
            + self.idle
            + self.iowait
            + self.irq
            + self.softirq
            + self.steal
    }

    fn idle_all(&self) -> u64 {
        self.idle + self.iowait
    }
}

fn read_cpu_times() -> io::Result<CpuTimes> {
    let stat = fs::read_to_string("/proc/stat")?;
    let line = stat
        .lines()
        .find(|l| l.starts_with("cpu "))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing cpu line"))?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 9 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "invalid cpu line",
        ));
    }

    Ok(CpuTimes {
        user: parts[1].parse().unwrap_or(0),
        nice: parts[2].parse().unwrap_or(0),
        system: parts[3].parse().unwrap_or(0),
        idle: parts[4].parse().unwrap_or(0),
        iowait: parts[5].parse().unwrap_or(0),
        irq: parts[6].parse().unwrap_or(0),
        softirq: parts[7].parse().unwrap_or(0),
        steal: parts[8].parse().unwrap_or(0),
    })
}

fn cpu_usage_pct(prev: CpuTimes, curr: CpuTimes) -> f64 {
    let totald = curr.total().saturating_sub(prev.total()) as f64;
    let idled = curr.idle_all().saturating_sub(prev.idle_all()) as f64;
    if totald <= 0.0 {
        0.0
    } else {
        ((totald - idled) / totald) * 100.0
    }
}

fn read_meminfo() -> io::Result<(u64, u64)> {
    let meminfo = fs::read_to_string("/proc/meminfo")?;
    let mut total = 0_u64;
    let mut available = 0_u64;

    for line in meminfo.lines() {
        if let Some(v) = line.strip_prefix("MemTotal:") {
            total = v.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        } else if let Some(v) = line.strip_prefix("MemAvailable:") {
            available = v.split_whitespace().next().unwrap_or("0").parse().unwrap_or(0);
        }
    }

    Ok((total, available))
}

fn read_loadavg() -> io::Result<(f64, f64, f64)> {
    let s = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() < 3 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "invalid loadavg",
        ));
    }

    Ok((
        parts[0].parse().unwrap_or(0.0),
        parts[1].parse().unwrap_or(0.0),
        parts[2].parse().unwrap_or(0.0),
    ))
}

fn read_diskstats() -> io::Result<(u64, u64)> {
    let s = fs::read_to_string("/proc/diskstats")?;
    let mut reads = 0_u64;
    let mut writes = 0_u64;

    for line in s.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 14 {
            continue;
        }

        let name = parts[2];
        if name.starts_with("loop") || name.starts_with("ram") {
            continue;
        }

        reads += parts[3].parse::<u64>().unwrap_or(0);
        writes += parts[7].parse::<u64>().unwrap_or(0);
    }

    Ok((reads, writes))
}

fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn main() -> io::Result<()> {
    let term = Arc::new(AtomicBool::new(false));
    flag::register(SIGTERM, Arc::clone(&term))?;
    flag::register(SIGINT, Arc::clone(&term))?;

    let mut prev_cpu = read_cpu_times()?;

    while !term.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let curr_cpu = read_cpu_times()?;
        let cpu = cpu_usage_pct(prev_cpu, curr_cpu);
        prev_cpu = curr_cpu;

        let (mem_total, mem_avail) = read_meminfo()?;
        let mem_used_pct = if mem_total == 0 {
            0.0
        } else {
            ((mem_total - mem_avail) as f64 / mem_total as f64) * 100.0
        };

        let (load1, load5, load15) = read_loadavg()?;
        let (disk_reads, disk_writes) = read_diskstats()?;

        let sample = Sample {
            ts: now_ts(),
            cpu_usage_pct: cpu,
            mem_total_kb: mem_total,
            mem_available_kb: mem_avail,
            mem_used_pct,
            load1,
            load5,
            load15,
            disk_reads_completed: disk_reads,
            disk_writes_completed: disk_writes,
        };

        println!("{}", serde_json::to_string(&sample).unwrap());
    }

    eprintln!("resourced: shutting down");
    Ok(())
}
```

