use libc;
use std::fs::{remove_file, File};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::process;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::Duration;

const SOCKET_PATH: &str = "/tmp/resd.sock";

#[derive(Clone, Debug, Default)]
struct Metrics {
    cpu_percent: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    load1: f64,
    load5: f64,
    load15: f64,
}

#[derive(Debug)]
struct SharedState {
    metrics: Mutex<Metrics>,
    interval_secs: AtomicU64,
    running: AtomicBool,
}

impl SharedState {
    fn new() -> Self {
        Self {
            metrics: Mutex::new(Metrics::default()),
            interval_secs: AtomicU64::new(2),
            running: AtomicBool::new(true),
        }
    }
}

fn daemonize() -> std::io::Result<()> {
    unsafe {
        let pid = libc::fork();
        if pid < 0 {
            return Err(std::io::Error::last_os_error());
        }
        if pid > 0 {
            process::exit(0);
        }

        if libc::setsid() < 0 {
            return Err(std::io::Error::last_os_error());
        }

        let pid2 = libc::fork();
        if pid2 < 0 {
            return Err(std::io::Error::last_os_error());
        }
        if pid2 > 0 {
            process::exit(0);
        }

        libc::umask(0);

        let devnull = std::ffi::CString::new("/dev/null").unwrap();
        let fd = libc::open(devnull.as_ptr(), libc::O_RDWR);
        if fd < 0 {
            return Err(std::io::Error::last_os_error());
        }

        libc::dup2(fd, 0);
        libc::dup2(fd, 1);
        libc::dup2(fd, 2);

        if fd > 2 {
            libc::close(fd);
        }
    }
    Ok(())
}

fn read_cpu_times() -> std::io::Result<(u64, u64)> {
    let mut s = String::new();
    File::open("/proc/stat")?.read_to_string(&mut s)?;
    let line = s.lines().next().unwrap_or("");
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "invalid /proc/stat format",
        ));
    }

    let user: u64 = parts[1].parse().unwrap_or(0);
    let nice: u64 = parts[2].parse().unwrap_or(0);
    let system: u64 = parts[3].parse().unwrap_or(0);
    let idle: u64 = parts[4].parse().unwrap_or(0);
    let iowait: u64 = parts.get(5).and_then(|v| v.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|v| v.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|v| v.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let non_idle = user + nice + system + irq + softirq + steal;
    let total = idle_all + non_idle;

    Ok((total, idle_all))
}

fn read_meminfo() -> std::io::Result<(u64, u64)> {
    let file = File::open("/proc/meminfo")?;
    let reader = BufReader::new(file);

    let mut total = 0;
    let mut available = 0;

    for line in reader.lines() {
        let line = line?;
        if line.starts_with("MemTotal:") {
            total = line.split_whitespace().nth(1).and_then(|v| v.parse().ok()).unwrap_or(0);
        } else if line.starts_with("MemAvailable:") {
            available = line.split_whitespace().nth(1).and_then(|v| v.parse().ok()).unwrap_or(0);
        }
    }

    Ok((total, available))
}

fn read_loadavg() -> std::io::Result<(f64, f64, f64)> {
    let mut s = String::new();
    File::open("/proc/loadavg")?.read_to_string(&mut s)?;
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() < 3 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "invalid /proc/loadavg format",
        ));
    }

    let l1 = parts[0].parse().unwrap_or(0.0);
    let l5 = parts[1].parse().unwrap_or(0.0);
    let l15 = parts[2].parse().unwrap_or(0.0);
    Ok((l1, l5, l15))
}

fn monitor_loop(state: Arc<SharedState>) {
    let mut prev = read_cpu_times().ok();

    while state.running.load(Ordering::Relaxed) {
        let current = read_cpu_times().ok();
        let cpu_percent = match (prev, current) {
            (Some((prev_total, prev_idle)), Some((curr_total, curr_idle))) => {
                let totald = curr_total.saturating_sub(prev_total);
                let idled = curr_idle.saturating_sub(prev_idle);
                if totald == 0 {
                    0.0
                } else {
                    100.0 * (totald.saturating_sub(idled)) as f64 / totald as f64
                }
            }
            _ => 0.0,
        };
        prev = current;

        let (mem_total_kb, mem_available_kb) = read_meminfo().unwrap_or((0, 0));
        let (load1, load5, load15) = read_loadavg().unwrap_or((0.0, 0.0, 0.0));

        {
            let mut m = state.metrics.lock().unwrap();
            m.cpu_percent = cpu_percent;
            m.mem_total_kb = mem_total_kb;
            m.mem_available_kb = mem_available_kb;
            m.load1 = load1;
            m.load5 = load5;
            m.load15 = load15;
        }

        let sleep_secs = state.interval_secs.load(Ordering::Relaxed).max(1);
        thread::sleep(Duration::from_secs(sleep_secs));
    }
}

fn handle_client(mut stream: UnixStream, state: Arc<SharedState>) -> std::io::Result<()> {
    let mut buf = String::new();
    stream.read_to_string(&mut buf)?;
    let cmd = buf.trim();

    if cmd == "status" {
        let m = state.metrics.lock().unwrap().clone();
        let used_kb = m.mem_total_kb.saturating_sub(m.mem_available_kb);
        let response = format!(
            "cpu={:.2}% mem_used_kb={} mem_total_kb={} load={:.2},{:.2},{:.2}\n",
            m.cpu_percent, used_kb, m.mem_total_kb, m.load1, m.load5, m.load15
        );
        stream.write_all(response.as_bytes())?;
    } else if let Some(rest) = cmd.strip_prefix("set interval ") {
        match rest.parse::<u64>() {
            Ok(secs) if secs > 0 => {
                state.interval_secs.store(secs, Ordering::Relaxed);
                stream.write_all(b"ok\n")?;
            }
            _ => {
                stream.write_all(b"error: invalid interval\n")?;
            }
        }
    } else if cmd == "quit" {
        state.running.store(false, Ordering::Relaxed);
        stream.write_all(b"shutting down\n")?;
    } else {
        stream.write_all(b"error: unknown command\n")?;
    }

    Ok(())
}

fn control_loop(state: Arc<SharedState>) -> std::io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = remove_file(SOCKET_PATH);
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;

    for stream in listener.incoming() {
        if !state.running.load(Ordering::Relaxed) {
            break;
        }

        match stream {
            Ok(stream) => {
                let state = Arc::clone(&state);
                thread::spawn(move || {
                    let _ = handle_client(stream, state);
                });
            }
            Err(_) => {}
        }
    }

    let _ = remove_file(SOCKET_PATH);
    Ok(())
}

fn main() -> std::io::Result<()> {
    daemonize()?;

    let state = Arc::new(SharedState::new());

    let monitor_state = Arc::clone(&state);
    let monitor_thread = thread::spawn(move || {
        monitor_loop(monitor_state);
    });

    let control_result = control_loop(Arc::clone(&state));

    state.running.store(false, Ordering::Relaxed);
    let _ = monitor_thread.join();

    control_result
}
