use std::fs;
use std::io;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::Duration;

#[derive(Debug, Clone, Copy)]
struct CpuTimes {
    idle: u64,
    total: u64,
}

fn read_cpu_times() -> io::Result<CpuTimes> {
    let contents = fs::read_to_string("/proc/stat")?;
    let first = contents
        .lines()
        .find(|l| l.starts_with("cpu "))
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "missing cpu line"))?;

    let parts: Vec<u64> = first
        .split_whitespace()
        .skip(1)
        .map(|s| s.parse::<u64>())
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    if parts.len() < 4 {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "unexpected /proc/stat format",
        ));
    }

    let idle = parts[3] + parts.get(4).copied().unwrap_or(0); // idle + iowait
    let total: u64 = parts.iter().sum();

    Ok(CpuTimes { idle, total })
}

fn cpu_usage_percent(prev: CpuTimes, curr: CpuTimes) -> f64 {
    let idle_delta = curr.idle.saturating_sub(prev.idle);
    let total_delta = curr.total.saturating_sub(prev.total);

    if total_delta == 0 {
        0.0
    } else {
        100.0 * (1.0 - (idle_delta as f64 / total_delta as f64))
    }
}

fn read_mem_usage_percent() -> io::Result<f64> {
    let contents = fs::read_to_string("/proc/meminfo")?;

    let mut mem_total_kb = None;
    let mut mem_available_kb = None;

    for line in contents.lines() {
        if line.starts_with("MemTotal:") {
            mem_total_kb = line
                .split_whitespace()
                .nth(1)
                .and_then(|v| v.parse::<u64>().ok());
        } else if line.starts_with("MemAvailable:") {
            mem_available_kb = line
                .split_whitespace()
                .nth(1)
                .and_then(|v| v.parse::<u64>().ok());
        }
    }

    let total = mem_total_kb.ok_or_else(|| io::Error::new(io::ErrorKind::Other, "MemTotal missing"))?;
    let avail = mem_available_kb
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "MemAvailable missing"))?;

    if total == 0 {
        return Ok(0.0);
    }

    let used = total.saturating_sub(avail);
    Ok((used as f64 / total as f64) * 100.0)
}

fn main() -> io::Result<()> {
    let running = Arc::new(AtomicBool::new(true));
    let r = Arc::clone(&running);

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    })
    .expect("failed to set signal handler");

    eprintln!("resourced starting");

    let mut prev = read_cpu_times()?;

    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_secs(2));

        let curr = match read_cpu_times() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("cpu read error: {e}");
                continue;
            }
        };

        let cpu = cpu_usage_percent(prev, curr);
        prev = curr;

        let mem = match read_mem_usage_percent() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("mem read error: {e}");
                continue;
            }
        };

        println!("cpu={:.2}% mem={:.2}%", cpu, mem);

        if cpu > 90.0 || mem > 90.0 {
            eprintln!("warning: high resource usage cpu={:.2}% mem={:.2}%", cpu, mem);
        }
    }

    eprintln!("resourced shutting down");
    Ok(())
}
