```rust
use anyhow::{Context, Result};
use serde::Serialize;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const SOCKET_PATH: &str = "/tmp/sysmond.sock";

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp: u64,
    load1: f32,
    load5: f32,
    load15: f32,
    mem_total_kb: u64,
    mem_available_kb: u64,
}

#[derive(Debug)]
struct Config {
    interval_secs: u64,
}

#[derive(Debug)]
struct SharedState {
    metrics: Mutex<Metrics>,
    config: Mutex<Config>,
    running: AtomicBool,
}

fn main() -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).context("failed to remove stale socket")?;
    }

    let state = Arc::new(SharedState {
        metrics: Mutex::new(Metrics {
            timestamp: now_secs(),
            load1: 0.0,
            load5: 0.0,
            load15: 0.0,
            mem_total_kb: 0,
            mem_available_kb: 0,
        }),
        config: Mutex::new(Config { interval_secs: 2 }),
        running: AtomicBool::new(true),
    });

    let monitor_state = Arc::clone(&state);
    let monitor_thread = thread::spawn(move || monitor_loop(monitor_state));

    let server_state = Arc::clone(&state);
    let server_thread = thread::spawn(move || server_loop(server_state));

    monitor_thread.join().expect("monitor thread panicked")?;
    server_thread.join().expect("server thread panicked")?;

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn monitor_loop(state: Arc<SharedState>) -> Result<()> {
    while state.running.load(Ordering::Relaxed) {
        let metrics = collect_metrics().context("collect_metrics failed")?;
        {
            let mut guard = state.metrics.lock().unwrap();
            *guard = metrics;
        }

        let interval = {
            let guard = state.config.lock().unwrap();
            guard.interval_secs
        };

        thread::sleep(Duration::from_secs(interval.max(1)));
    }
    Ok(())
}

fn server_loop(state: Arc<SharedState>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH).context("bind unix socket failed")?;
    listener
        .set_nonblocking(false)
        .context("failed to configure listener")?;

    while state.running.load(Ordering::Relaxed) {
        let (stream, _) = listener.accept().context("accept failed")?;
        handle_client(stream, &state)?;
    }

    Ok(())
}

fn handle_client(mut stream: UnixStream, state: &Arc<SharedState>) -> Result<()> {
    let mut line = String::new();
    {
        let mut reader = BufReader::new(&stream);
        reader.read_line(&mut line).context("read command failed")?;
    }

    let cmd = line.trim();

    if cmd == "status" {
        let metrics = {
            let guard = state.metrics.lock().unwrap();
            guard.clone()
        };
        let json = serde_json::to_string(&metrics)?;
        writeln!(stream, "{json}")?;
    } else if let Some(rest) = cmd.strip_prefix("set interval ") {
        let secs: u64 = rest.parse().context("invalid interval")?;
        {
            let mut guard = state.config.lock().unwrap();
            guard.interval_secs = secs.max(1);
        }
        writeln!(stream, "ok")?;
    } else if cmd == "stop" {
        state.running.store(false, Ordering::Relaxed);
        writeln!(stream, "stopping")?;
    } else {
        writeln!(stream, "error: unknown command")?;
    }

    Ok(())
}

fn collect_metrics() -> Result<Metrics> {
    let (load1, load5, load15) = read_loadavg()?;
    let (mem_total_kb, mem_available_kb) = read_meminfo()?;

    Ok(Metrics {
        timestamp: now_secs(),
        load1,
        load5,
        load15,
        mem_total_kb,
        mem_available_kb,
    })
}

fn read_loadavg() -> Result<(f32, f32, f32)> {
    let s = fs::read_to_string("/proc/loadavg").context("read /proc/loadavg failed")?;
    let mut parts = s.split_whitespace();
    let l1: f32 = parts.next().context("missing load1")?.parse()?;
    let l5: f32 = parts.next().context("missing load5")?.parse()?;
    let l15: f32 = parts.next().context("missing load15")?.parse()?;
    Ok((l1, l5, l15))
}

fn read_meminfo() -> Result<(u64, u64)> {
    let s = fs::read_to_string("/proc/meminfo").context("read /proc/meminfo failed")?;
    let mut total = 0;
    let mut avail = 0;

    for line in s.lines() {
        if let Some(v) = line.strip_prefix("MemTotal:") {
            total = parse_mem_kb(v)?;
        } else if let Some(v) = line.strip_prefix("MemAvailable:") {
            avail = parse_mem_kb(v)?;
        }
    }

    Ok((total, avail))
}

fn parse_mem_kb(s: &str) -> Result<u64> {
    let value = s
        .split_whitespace()
        .next()
        .context("missing mem value")?
        .parse()?;
    Ok(value)
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}
