## Minimal working example in Rust (Linux)

```rust
use std::{
    fs,
    io,
    sync::atomic::{AtomicBool, Ordering},
    sync::Arc,
    thread,
    time::Duration,
};

fn read_proc_stat() -> io::Result<(u64, u64)> {
    let data = fs::read_to_string("/proc/stat")?;
    let first = data.lines().next().unwrap_or("");
    let parts: Vec<&str> = first.split_whitespace().collect();

    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(io::Error::new(io::ErrorKind::Other, "unexpected /proc/stat format"));
    }

    let user: u64 = parts[1].parse().unwrap_or(0);
    let nice: u64 = parts[2].parse().unwrap_or(0);
    let system: u64 = parts[3].parse().unwrap_or(0);
    let idle: u64 = parts[4].parse().unwrap_or(0);
    let iowait: u64 = parts.get(5).and_then(|s| s.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|s| s.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|s| s.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|s| s.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;

    Ok((total, idle_all))
}

fn read_meminfo() -> io::Result<(u64, u64)> {
    let data = fs::read_to_string("/proc/meminfo")?;
    let mut total_kb = 0;
    let mut avail_kb = 0;

    for line in data.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line.split_whitespace().nth(1).and_then(|v| v.parse().ok()).unwrap_or(0);
        } else if line.starts_with("MemAvailable:") {
            avail_kb = line.split_whitespace().nth(1).and_then(|v| v.parse().ok()).unwrap_or(0);
        }
    }

    if total_kb == 0 {
        return Err(io::Error::new(io::ErrorKind::Other, "MemTotal missing"));
    }

    Ok((total_kb, avail_kb))
}

fn main() -> io::Result<()> {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    }).expect("failed to set Ctrl-C handler");

    let mut prev = read_proc_stat()?;

    println!("resource monitor starting");

    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_secs(1));

        let curr = read_proc_stat()?;
        let (prev_total, prev_idle) = prev;
        let (curr_total, curr_idle) = curr;

        let totald = curr_total.saturating_sub(prev_total);
        let idled = curr_idle.saturating_sub(prev_idle);

        let cpu_usage = if totald == 0 {
            0.0
        } else {
            100.0 * (totald.saturating_sub(idled)) as f64 / totald as f64
        };

        let (mem_total, mem_avail) = read_meminfo()?;
        let mem_used = mem_total.saturating_sub(mem_avail);
        let mem_usage = 100.0 * mem_used as f64 / mem_total as f64;

        println!(
            "cpu={:.2}% mem={:.2}% used={}MB total={}MB",
            cpu_usage,
            mem_usage,
            mem_used / 1024,
            mem_total / 1024
        );

        prev = curr;
    }

    println!("resource monitor stopping");
    Ok(())
}
```

