```rust
use axum::{extract::State, response::IntoResponse, routing::get, Json, Router};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{Arc, Mutex},
    time::Duration,
};
use sysinfo::System;
use tokio::{signal, task, time};
use tracing::{error, info};

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    cpu_usage_percent: f32,
    used_memory_bytes: u64,
    total_memory_bytes: u64,
    used_swap_bytes: u64,
    total_swap_bytes: u64,
    process_count: usize,
}

#[derive(Clone, Default)]
struct AppState {
    metrics: Arc<Mutex<Metrics>>,
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = AppState::default();

    let monitor_state = state.clone();
    let monitor = task::spawn(async move {
        let mut sys = System::new_all();

        loop {
            sys.refresh_all();

            let metrics = Metrics {
                cpu_usage_percent: sys.global_cpu_info().cpu_usage(),
                used_memory_bytes: sys.used_memory() * 1024,
                total_memory_bytes: sys.total_memory() * 1024,
                used_swap_bytes: sys.used_swap() * 1024,
                total_swap_bytes: sys.total_swap() * 1024,
                process_count: sys.processes().len(),
            };

            {
                let mut guard = monitor_state.metrics.lock().unwrap();
                *guard = metrics.clone();
            }

            info!(
                cpu = metrics.cpu_usage_percent,
                mem_used = metrics.used_memory_bytes,
                mem_total = metrics.total_memory_bytes,
                procs = metrics.process_count,
                "sampled system metrics"
            );

            time::sleep(Duration::from_secs(5)).await;
        }
    });

    let app = Router::new()
        .route("/healthz", get(healthz))
        .route("/metrics.json", get(metrics_json))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    info!("http server listening on {}", addr);

    let server = tokio::spawn(async move {
        let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
        axum::serve(listener, app).await.unwrap();
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = monitor => {
            error!("monitor task exited unexpectedly: {:?}", res);
        }
        res = server => {
            error!("server task exited unexpectedly: {:?}", res);
        }
    }

    info!("daemon exiting");
}

async fn healthz() -> impl IntoResponse {
    "ok"
}

async fn metrics_json(State(state): State<AppState>) -> impl IntoResponse {
    let metrics = state.metrics.lock().unwrap().clone();
    Json(metrics)
}
```

