```cpp
#include <cstdint>
#include <cstring>
#include <vector>
#include <iostream>
#include <chrono>
#include <arpa/inet.h>

#if defined(__GNUC__) || defined(__clang__)
#define LIKELY(x)   __builtin_expect(!!(x), 1)
#define UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
#define LIKELY(x)   (x)
#define UNLIKELY(x) (x)
#endif

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t version_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
    uint8_t pad[3];

    bool operator==(const FlowKey& o) const {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowValue {
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
};

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(
        steady_clock::now().time_since_epoch()).count();
}

// Fast 64-bit mix hash
static inline uint64_t hash_flowkey(const FlowKey& k) {
    uint64_t x = 0x9e3779b97f4a7c15ULL;
    x ^= (uint64_t)k.src_ip + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
    x ^= (uint64_t)k.dst_ip + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
    x ^= ((uint64_t)k.src_port << 16) | k.dst_port;
    x ^= (uint64_t)k.proto << 48;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

class FlowTable {
public:
    struct Entry {
        FlowKey key{};
        FlowValue value{};
        uint8_t occupied = 0;
    };

    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), entries_(capacity_pow2) {}

    inline void update(const FlowKey& key, uint32_t pkt_len, uint64_t ts_ns) {
        uint64_t h = hash_flowkey(key);
        size_t idx = h & mask_;

        for (size_t probe = 0; probe < 16; ++probe) {
            Entry& e = entries_[(idx + probe) & mask_];
            if (LIKELY(e.occupied)) {
                if (LIKELY(e.key == key)) {
                    e.value.packets++;
                    e.value.bytes += pkt_len;
                    e.value.last_seen_ns = ts_ns;
                    return;
                }
            } else {
                e.occupied = 1;
                e.key = key;
                e.value.packets = 1;
                e.value.bytes = pkt_len;
                e.value.first_seen_ns = ts_ns;
                e.value.last_seen_ns = ts_ns;
                return;
            }
        }

        // Fallback: simple overwrite of initial slot if probe budget exceeded.
        // In production, use resizing, cuckoo hashing, or eviction policy.
        Entry& e = entries_[idx];
        e.occupied = 1;
        e.key = key;
        e.value.packets = 1;
        e.value.bytes = pkt_len;
        e.value.first_seen_ns = ts_ns;
        e.value.last_seen_ns = ts_ns;
    }

    void dump_top(size_t max_print = 20) const {
        size_t printed = 0;
        for (const auto& e : entries_) {
            if (!e.occupied) continue;
            char src[INET_ADDRSTRLEN];
            char dst[INET_ADDRSTRLEN];
            in_addr saddr{e.key.src_ip};
            in_addr daddr{e.key.dst_ip};
            inet_ntop(AF_INET, &saddr, src, sizeof(src));
            inet_ntop(AF_INET, &daddr, dst, sizeof(dst));

            std::cout << src << ":" << ntohs(e.key.src_port)
                      << " -> " << dst << ":" << ntohs(e.key.dst_port)
                      << " proto=" << (int)e.key.proto
                      << " pkts=" << e.value.packets
                      << " bytes=" << e.value.bytes
                      << "\n";
            if (++printed >= max_print) break;
        }
    }

private:
    size_t mask_;
    std::vector<Entry> entries_;
};

static inline bool parse_ipv4_5tuple(const uint8_t* pkt, size_t len, FlowKey& key) {
    if (UNLIKELY(len < sizeof(EthHdr) + sizeof(Ipv4Hdr))) return false;

    const EthHdr* eth = reinterpret_cast<const EthHdr*>(pkt);
    if (UNLIKELY(ntohs(eth->ethertype) != 0x0800)) return false; // IPv4

    const uint8_t* ip_ptr = pkt + sizeof(EthHdr);
    size_t ip_len = len - sizeof(EthHdr);

    const Ipv4Hdr* ip = reinterpret_cast<const Ipv4Hdr*>(ip_ptr);
    uint8_t version = ip->version_ihl >> 4;
    uint8_t ihl = (ip->version_ihl & 0x0F) * 4;

    if (UNLIKELY(version != 4 || ihl < 20 || ip_len < ihl)) return false;

    // Skip fragmented non-first packets
    uint16_t frag = ntohs(ip->frag_off);
    if (UNLIKELY((frag & 0x1FFF) != 0)) return false;

    key.src_ip = ip->src;
    key.dst_ip = ip->dst;
    key.proto = ip->protocol;
    key.src_port = 0;
    key.dst_port = 0;

    const uint8_t* l4_ptr = ip_ptr + ihl;
    size_t l4_len = ip_len - ihl;

    if (key.proto == 6) { // TCP
        if (UNLIKELY(l4_len < sizeof(TcpHdr))) return false;
        const TcpHdr* tcp = reinterpret_cast<const TcpHdr*>(l4_ptr);
        key.src_port = tcp->src_port;
        key.dst_port = tcp->dst_port;
        return true;
    } else if (key.proto == 17) { // UDP
        if (UNLIKELY(l4_len < sizeof(UdpHdr))) return false;
        const UdpHdr* udp = reinterpret_cast<const UdpHdr*>(l4_ptr);
        key.src_port = udp->src_port;
        key.dst_port = udp->dst_port;
        return true;
    } else {
        return true; // keep non-TCP/UDP flows with zero ports
    }
}

// Example packet processing API
void process_packet(FlowTable& table, const uint8_t* pkt, size_t len) {
    FlowKey key;
    if (LIKELY(parse_ipv4_5tuple(pkt, len, key))) {
        table.update(key, static_cast<uint32_t>(len), now_ns());
    }
}

int main() {
    // Power-of-two capacity for fast masking
    FlowTable table(1 << 20);

    // In production, replace this with a high-speed capture loop.
    // Example:
    // while (capture_next_packet(&pkt, &len)) process_packet(table, pkt, len);

    table.dump_top();
    return 0;
}
```

## Why this is fast
- no per-packet heap allocation
- compact fixed-size flow entries
- open addressing avoids pointer chasing
- branch prediction hints on hot path
- power-of-two table size for cheap indexing
- minimal parsing work

## Important production improvements
For real gigabit-scale live monitoring, I would strongly recommend adding:

1. **Per-core sharded flow tables**
   - one table per RX queue/thread
   - avoid locks on packet hot path

2. **Batch packet processing**
   - process bursts instead of one packet at a time

3. **Flow expiration**
   - idle timeout and active timeout
   - periodic scavenger thread

4. **Bidirectional canonicalization**
   - normalize client/server direction if desired

5. **IPv6 support**
   - current sample is IPv4 only

6. **Capture backend**
   - `AF_PACKET` with `TPACKET_V3` for Linux
   - or DPDK/XDP for higher rates

7. **Cache-line alignment**
   - align entries and counters carefully
   - avoid false sharing

8. **Probe strategy**
   - robin hood hashing or cuckoo hashing
   - resize or overflow handling instead of overwrite

9. **Timestamp source**
   - use packet timestamps from NIC/kernel ring if available
   - avoid calling `now()` per packet if too expensive

10. **Prefetching**
   - software prefetch next packet / table slot in tight loops

