```rust
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Eq, PartialEq, Debug)]
enum IpAddrKey {
    V4([u8; 4]),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Eq, PartialEq, Debug)]
struct FlowKey {
    src: IpAddrKey,
    dst: IpAddrKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self.src {
            IpAddrKey::V4(v) => v.hash(state),
            IpAddrKey::V6(v) => v.hash(state),
        }
        match self.dst {
            IpAddrKey::V4(v) => v.hash(state),
            IpAddrKey::V6(v) => v.hash(state),
        }
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct Analyzer {
    flows: HashMap<FlowKey, FlowStats>,
    timeout: Duration,
}

impl Analyzer {
    fn new(timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity(1 << 20),
            timeout,
        }
    }

    fn process_packet(&mut self, pkt: &[u8], now: Instant) {
        if let Some((key, tcp_flags)) = parse_packet(pkt) {
            let stats = self.flows.entry(key).or_insert_with(|| FlowStats::new(now, pkt.len()));
            if stats.packets > 1 || stats.bytes > pkt.len() as u64 {
                stats.update(now, pkt.len());
            }

            if let Some(flags) = tcp_flags {
                if flags & 0x02 != 0 { stats.tcp_syn += 1; } // SYN
                if flags & 0x01 != 0 { stats.tcp_fin += 1; } // FIN
                if flags & 0x04 != 0 { stats.tcp_rst += 1; } // RST
            }
        }
    }

    fn expire_flows(&mut self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let timeout = self.timeout;
        let mut expired = Vec::new();

        self.flows.retain(|k, v| {
            if now.duration_since(v.last_seen) > timeout {
                expired.push((*k, v.clone()));
                false
            } else {
                true
            }
        });

        expired
    }
}

fn parse_packet(pkt: &[u8]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    match ethertype {
        0x0800 => parse_ipv4(&pkt[14..]),
        0x86DD => parse_ipv6(&pkt[14..]),
        _ => None,
    }
}

fn parse_ipv4(pkt: &[u8]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < 20 {
        return None;
    }

    let version_ihl = pkt[0];
    if version_ihl >> 4 != 4 {
        return None;
    }
    let ihl = ((version_ihl & 0x0F) as usize) * 4;
    if ihl < 20 || pkt.len() < ihl {
        return None;
    }

    let proto = pkt[9];
    let src = [pkt[12], pkt[13], pkt[14], pkt[15]];
    let dst = [pkt[16], pkt[17], pkt[18], pkt[19]];

    match proto {
        6 => parse_tcp_v4(pkt, ihl, src, dst),
        17 => parse_udp_v4(pkt, ihl, src, dst),
        _ => None,
    }
}

fn parse_ipv6(pkt: &[u8]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < 40 || (pkt[0] >> 4) != 6 {
        return None;
    }

    let next_header = pkt[6];
    let src: [u8; 16] = pkt[8..24].try_into().ok()?;
    let dst: [u8; 16] = pkt[24..40].try_into().ok()?;

    match next_header {
        6 => parse_tcp_v6(pkt, 40, src, dst),
        17 => parse_udp_v6(pkt, 40, src, dst),
        _ => None,
    }
}

fn parse_tcp_v4(pkt: &[u8], l4_off: usize, src: [u8; 4], dst: [u8; 4]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < l4_off + 20 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt[l4_off], pkt[l4_off + 1]]);
    let dst_port = u16::from_be_bytes([pkt[l4_off + 2], pkt[l4_off + 3]]);
    let flags = pkt[l4_off + 13];

    Some((
        FlowKey {
            src: IpAddrKey::V4(src),
            dst: IpAddrKey::V4(dst),
            src_port,
            dst_port,
            proto: 6,
        },
        Some(flags),
    ))
}

fn parse_udp_v4(pkt: &[u8], l4_off: usize, src: [u8; 4], dst: [u8; 4]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < l4_off + 8 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt[l4_off], pkt[l4_off + 1]]);
    let dst_port = u16::from_be_bytes([pkt[l4_off + 2], pkt[l4_off + 3]]);

    Some((
        FlowKey {
            src: IpAddrKey::V4(src),
            dst: IpAddrKey::V4(dst),
            src_port,
            dst_port,
            proto: 17,
        },
        None,
    ))
}

fn parse_tcp_v6(pkt: &[u8], l4_off: usize, src: [u8; 16], dst: [u8; 16]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < l4_off + 20 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt[l4_off], pkt[l4_off + 1]]);
    let dst_port = u16::from_be_bytes([pkt[l4_off + 2], pkt[l4_off + 3]]);
    let flags = pkt[l4_off + 13];

    Some((
        FlowKey {
            src: IpAddrKey::V6(src),
            dst: IpAddrKey::V6(dst),
            src_port,
            dst_port,
            proto: 6,
        },
        Some(flags),
    ))
}

fn parse_udp_v6(pkt: &[u8], l4_off: usize, src: [u8; 16], dst: [u8; 16]) -> Option<(FlowKey, Option<u8>)> {
    if pkt.len() < l4_off + 8 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt[l4_off], pkt[l4_off + 1]]);
    let dst_port = u16::from_be_bytes([pkt[l4_off + 2], pkt[l4_off + 3]]);

    Some((
        FlowKey {
            src: IpAddrKey::V6(src),
            dst: IpAddrKey::V6(dst),
            src_port,
            dst_port,
            proto: 17,
        },
        None,
    ))
}

fn main() {
    let mut analyzer = Analyzer::new(Duration::from_secs(60));

    // Example: feed raw Ethernet frames here
    let packets: Vec<Vec<u8>> = vec![];

    for pkt in &packets {
        analyzer.process_packet(pkt, Instant::now());
    }

    for (k, v) in analyzer.expire_flows(Instant::now() + Duration::from_secs(120)) {
        println!("{:?} => {:?}", k, v);
    }
}
```

