# Rust implementation

```rust
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

use crossbeam_channel::{bounded, Receiver, Sender};

const NUM_SHARDS: usize = 64;
const NUM_WORKERS: usize = 4;
const CHANNEL_CAPACITY: usize = 262_144;
const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const EXPIRY_SCAN_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub enum TransportProtocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub enum IpAddress {
    V4([u8; 4]),
    V6([u8; 16]),
}

impl From<IpAddr> for IpAddress {
    fn from(ip: IpAddr) -> Self {
        match ip {
            IpAddr::V4(v4) => IpAddress::V4(v4.octets()),
            IpAddr::V6(v6) => IpAddress::V6(v6.octets()),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddress,
    pub dst_ip: IpAddress,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
}

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub timestamp: Instant,
    pub src_ip: IpAddress,
    pub dst_ip: IpAddress,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
    pub bytes: u32,
}

impl PacketMeta {
    #[inline]
    pub fn flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            proto: self.proto,
        }
    }
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowStats {
    #[inline]
    fn new(ts: Instant, bytes: u32) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: ts,
            last_seen: ts,
        }
    }

    #[inline]
    fn update(&mut self, ts: Instant, bytes: u32) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = ts;
    }
}

// Simple fast hasher for internal sharding/hashmap usage.
// For production, benchmark alternatives like ahash or fxhash.
#[derive(Default)]
struct Fnv64Hasher(u64);

impl Hasher for Fnv64Hasher {
    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        const FNV_OFFSET: u64 = 0xcbf29ce484222325;
        const FNV_PRIME: u64 = 0x100000001b3;
        let mut hash = if self.0 == 0 { FNV_OFFSET } else { self.0 };
        for b in bytes {
            hash ^= *b as u64;
            hash = hash.wrapping_mul(FNV_PRIME);
        }
        self.0 = hash;
    }

    #[inline]
    fn finish(&self) -> u64 {
        self.0
    }
}

type FastBuildHasher = BuildHasherDefault<Fnv64Hasher>;

#[derive(Debug)]
pub struct FlowRecord {
    pub key: FlowKey,
    pub stats: FlowStats,
}

type FlowMap = HashMap<FlowKey, FlowStats, FastBuildHasher>;

pub struct FlowShard {
    inner: Mutex<FlowMap>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            inner: Mutex::new(HashMap::default()),
        }
    }
}

pub struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    pub fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(FlowShard::new());
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = Fnv64Hasher::default();
        hash_flow_key(&mut hasher, key);
        (hasher.finish() as usize) % self.shards.len()
    }

    #[inline]
    pub fn update_flow(&self, packet: &PacketMeta) {
        let key = packet.flow_key();
        let idx = self.shard_index(&key);
        let shard = &self.shards[idx];
        let mut guard = shard.inner.lock().unwrap();

        match guard.get_mut(&key) {
            Some(stats) => stats.update(packet.timestamp, packet.bytes),
            None => {
                guard.insert(key, FlowStats::new(packet.timestamp, packet.bytes));
            }
        }
    }

    pub fn expire_inactive(&self, now: Instant, timeout: Duration) -> Vec<FlowRecord> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut guard = shard.inner.lock().unwrap();
            let mut to_remove = Vec::new();

            for (key, stats) in guard.iter() {
                if now.duration_since(stats.last_seen) >= timeout {
                    to_remove.push(*key);
                }
            }

            for key in to_remove {
                if let Some(stats) = guard.remove(&key) {
                    expired.push(FlowRecord { key, stats });
                }
            }
        }

        expired
    }

    pub fn snapshot(&self) -> Vec<FlowRecord> {
        let mut out = Vec::new();
        for shard in &self.shards {
            let guard = shard.inner.lock().unwrap();
            out.reserve(guard.len());
            for (key, stats) in guard.iter() {
                out.push(FlowRecord {
                    key: *key,
                    stats: stats.clone(),
                });
            }
        }
        out
    }
}

#[inline]
fn hash_flow_key(hasher: &mut impl Hasher, key: &FlowKey) {
    match key.src_ip {
        IpAddress::V4(o) => hasher.write(&o),
        IpAddress::V6(o) => hasher.write(&o),
    }
    match key.dst_ip {
        IpAddress::V4(o) => hasher.write(&o),
        IpAddress::V6(o) => hasher.write(&o),
    }
    hasher.write(&key.src_port.to_ne_bytes());
    hasher.write(&key.dst_port.to_ne_bytes());
    match key.proto {
        TransportProtocol::Tcp => hasher.write(&[6]),
        TransportProtocol::Udp => hasher.write(&[17]),
        TransportProtocol::Icmp => hasher.write(&[1]),
        TransportProtocol::Other(v) => hasher.write(&[v]),
    }
}

pub struct Analyzer {
    flow_table: Arc<FlowTable>,
    worker_senders: Vec<Sender<PacketMeta>>,
    shutdown: Arc<AtomicBool>,
    worker_handles: Vec<thread::JoinHandle<()>>,
    expiry_handle: Option<thread::JoinHandle<()>>,
}

impl Analyzer {
    pub fn new(num_workers: usize, num_shards: usize) -> Self {
        let flow_table = Arc::new(FlowTable::new(num_shards));
        let shutdown = Arc::new(AtomicBool::new(false));

        let mut worker_senders = Vec::with_capacity(num_workers);
        let mut worker_handles = Vec::with_capacity(num_workers);

        for _ in 0..num_workers {
            let (tx, rx): (Sender<PacketMeta>, Receiver<PacketMeta>) = bounded(CHANNEL_CAPACITY);
            worker_senders.push(tx);

            let ft = Arc::clone(&flow_table);
            let sd = Arc::clone(&shutdown);

            let handle = thread::spawn(move || worker_loop(ft, rx, sd));
            worker_handles.push(handle);
        }

        let ft = Arc::clone(&flow_table);
        let sd = Arc::clone(&shutdown);
        let expiry_handle = Some(thread::spawn(move || expiry_loop(ft, sd)));

        Self {
            flow_table,
            worker_senders,
            shutdown,
            worker_handles,
            expiry_handle,
        }
    }

    #[inline]
    pub fn submit(&self, packet: PacketMeta) -> Result<(), crossbeam_channel::SendError<PacketMeta>> {
        let idx = self.worker_index(&packet);
        self.worker_senders[idx].send(packet)
    }

    #[inline]
    fn worker_index(&self, packet: &PacketMeta) -> usize {
        let key = packet.flow_key();
        let mut hasher = Fnv64Hasher::default();
        hash_flow_key(&mut hasher, &key);
        (hasher.finish() as usize) % self.worker_senders.len()
    }

    pub fn snapshot(&self) -> Vec<FlowRecord> {
        self.flow_table.snapshot()
    }

    pub fn shutdown(mut self) {
        self.shutdown.store(true, Ordering::Relaxed);
        drop(self.worker_senders);

        for handle in self.worker_handles.drain(..) {
            let _ = handle.join();
        }

        if let Some(handle) = self.expiry_handle.take() {
            let _ = handle.join();
        }
    }
}

fn worker_loop(flow_table: Arc<FlowTable>, rx: Receiver<PacketMeta>, shutdown: Arc<AtomicBool>) {
    while !shutdown.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(packet) => flow_table.update_flow(&packet),
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }

    while let Ok(packet) = rx.try_recv() {
        flow_table.update_flow(&packet);
    }
}

fn expiry_loop(flow_table: Arc<FlowTable>, shutdown: Arc<AtomicBool>) {
    while !shutdown.load(Ordering::Relaxed) {
        thread::sleep(EXPIRY_SCAN_INTERVAL);
        let now = Instant::now();
        let expired = flow_table.expire_inactive(now, FLOW_TIMEOUT);

        if !expired.is_empty() {
            // Replace with real export/logging pipeline.
            println!("expired {} flows", expired.len());
        }
    }
}

// Example synthetic packet generator for testing.
fn main() {
    let analyzer = Analyzer::new(NUM_WORKERS, NUM_SHARDS);

    let start = Instant::now();

    for i in 0..1_000_000u32 {
        let packet = PacketMeta {
            timestamp: Instant::now(),
            src_ip: IpAddress::V4(Ipv4Addr::new(10, 0, ((i >> 8) & 0xff) as u8, (i & 0xff) as u8).octets()),
            dst_ip: IpAddress::V4(Ipv4Addr::new(192, 168, 1, ((i * 31) & 0xff) as u8).octets()),
            src_port: 1000 + (i % 1024) as u16,
            dst_port: 2000 + (i % 2048) as u16,
            proto: if i % 2 == 0 {
                TransportProtocol::Tcp
            } else {
                TransportProtocol::Udp
            },
            bytes: 128 + (i % 1400),
        };

        analyzer.submit(packet).unwrap();
    }

    thread::sleep(Duration::from_secs(2));

    let snapshot = analyzer.snapshot();
    println!(
        "processed flows: {}, elapsed: {:?}",
        snapshot.len(),
        start.elapsed()
    );

    analyzer.shutdown();
}
