# Main implementation

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Active, Capture, Device};
use std::fmt;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const PACKET_CHANNEL_SIZE: usize = 8192;
const REPORT_INTERVAL: Duration = Duration::from_secs(5);
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{}:{} -> {}:{} proto={}",
            self.src_ip, self.src_port, self.dst_ip, self.dst_port, self.proto
        )
    }
}

#[derive(Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_syn: u64,
    tcp_fin: u64,
    tcp_rst: u64,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

#[derive(Clone)]
struct PacketRecord {
    timestamp: Instant,
    data: Vec<u8>,
}

type FlowTable = DashMap<FlowKey, FlowStats>;

fn main() {
    let device = Device::lookup()
        .expect("failed to lookup default device")
        .expect("no default device found");

    println!("Capturing on device: {}", device.name);

    let running = Arc::new(AtomicBool::new(true));
    let flows = Arc::new(FlowTable::new());
    let (tx, rx) = bounded::<PacketRecord>(PACKET_CHANNEL_SIZE);

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })
        .expect("failed to install Ctrl-C handler");
    }

    let capture_handle = {
        let tx = tx.clone();
        let running = running.clone();
        let device_name = device.name.clone();
        thread::spawn(move || capture_loop(&device_name, tx, running))
    };

    let worker_handle = {
        let flows = flows.clone();
        let running = running.clone();
        thread::spawn(move || worker_loop(rx, flows, running))
    };

    let reporter_handle = {
        let flows = flows.clone();
        let running = running.clone();
        thread::spawn(move || reporter_loop(flows, running))
    };

    capture_handle.join().unwrap();
    worker_handle.join().unwrap();
    reporter_handle.join().unwrap();
}

fn capture_loop(device_name: &str, tx: Sender<PacketRecord>, running: Arc<AtomicBool>) {
    let mut cap = Capture::<Active>::from_device(device_name)
        .expect("failed to create capture from device")
        .promisc(true)
        .immediate_mode(true)
        .snaplen(2048)
        .open()
        .expect("failed to open capture");

    cap.filter("ip or ip6", true)
        .expect("failed to set BPF filter");

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let record = PacketRecord {
                    timestamp: Instant::now(),
                    data: packet.data.to_vec(),
                };

                if tx.try_send(record).is_err() {
                    // Drop packet under backpressure to preserve system responsiveness.
                }
            }
            Err(_) => {
                // In a more robust implementation, classify timeout vs fatal errors.
            }
        }
    }
}

fn worker_loop(rx: Receiver<PacketRecord>, flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(record) => process_packet(&record, &flows),
            Err(_) => {}
        }
    }
}

fn process_packet(record: &PacketRecord, flows: &FlowTable) {
    let sliced = match SlicedPacket::from_ethernet(&record.data) {
        Ok(pkt) => pkt,
        Err(_) => return,
    };

    let (src_ip, dst_ip, proto) = match sliced.net {
        Some(InternetSlice::Ipv4(header, _)) => (
            IpAddr::V4(Ipv4Addr::from(header.source())),
            IpAddr::V4(Ipv4Addr::from(header.destination())),
            header.protocol().0,
        ),
        Some(InternetSlice::Ipv6(header, _)) => (
            IpAddr::V6(Ipv6Addr::from(header.source())),
            IpAddr::V6(Ipv6Addr::from(header.destination())),
            header.next_header().0,
        ),
        _ => return,
    };

    let (src_port, dst_port, syn, fin, rst) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (
            tcp.source_port(),
            tcp.destination_port(),
            tcp.syn(),
            tcp.fin(),
            tcp.rst(),
        ),
        Some(TransportSlice::Udp(udp)) => (
            udp.source_port(),
            udp.destination_port(),
            false,
            false,
            false,
        ),
        Some(TransportSlice::Icmpv4(_)) | Some(TransportSlice::Icmpv6(_)) => (0, 0, false, false, false),
        _ => (0, 0, false, false, false),
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    let now = record.timestamp;
    let bytes = record.data.len();

    flows
        .entry(key)
        .and_modify(|stats| {
            stats.update(now, bytes);
            if syn {
                stats.tcp_syn += 1;
            }
            if fin {
                stats.tcp_fin += 1;
            }
            if rst {
                stats.tcp_rst += 1;
            }
        })
        .or_insert_with(|| {
            let mut stats = FlowStats::new(now, bytes);
            if syn {
                stats.tcp_syn = 1;
            }
            if fin {
                stats.tcp_fin = 1;
            }
            if rst {
                stats.tcp_rst = 1;
            }
            stats
        });
}

fn reporter_loop(flows: Arc<FlowTable>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) {
        thread::sleep(REPORT_INTERVAL);
        expire_idle_flows(&flows);
        print_top_flows(&flows, 20);
    }

    expire_idle_flows(&flows);
    print_top_flows(&flows, 50);
}

fn expire_idle_flows(flows: &FlowTable) {
    let now = Instant::now();
    let mut expired = Vec::new();

    for entry in flows.iter() {
        if now.duration_since(entry.value().last_seen) > FLOW_IDLE_TIMEOUT {
            expired.push(*entry.key());
        }
    }

    for key in expired {
        flows.remove(&key);
    }
}

fn print_top_flows(flows: &FlowTable, limit: usize) {
    let mut snapshot = Vec::with_capacity(flows.len());

    for entry in flows.iter() {
        snapshot.push((entry.key().to_owned(), entry.value().clone()));
    }

    snapshot.sort_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

    println!("==== top {} flows ====", limit);
    for (idx, (key, stats)) in snapshot.into_iter().take(limit).enumerate() {
        let age = stats.last_seen.duration_since(stats.first_seen).as_secs_f64();
        let bps = if age > 0.0 {
            (stats.bytes as f64 * 8.0) / age
        } else {
            0.0
        };

        println!(
            "#{:02} {} packets={} bytes={} rate={:.2}bps syn={} fin={} rst={}",
            idx + 1,
            key,
            stats.packets,
            stats.bytes,
            bps,
            stats.tcp_syn,
            stats.tcp_fin,
            stats.tcp_rst
        );
    }

    println!("total active flows={}", flows.len());
}
```

