# `src/main.rs`

```rust
use ahash::AHashMap;
use clap::Parser;
use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use parking_lot::Mutex;
use std::fmt::{Display, Formatter};
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Input pcap file
    #[arg(short, long)]
    pcap: String,

    /// Number of worker shards
    #[arg(short, long, default_value_t = num_cpus::get())]
    workers: usize,

    /// Idle timeout in seconds
    #[arg(long, default_value_t = 30)]
    idle_timeout: u64,

    /// Active timeout in seconds
    #[arg(long, default_value_t = 300)]
    active_timeout: u64,

    /// Channel capacity
    #[arg(long, default_value_t = 65536)]
    queue_size: usize,

    /// Print expired flows
    #[arg(long, default_value_t = false)]
    print_flows: bool,
}

#[derive(Clone, Copy, Eq, PartialEq, Debug, Hash)]
enum IpKey {
    V4([u8; 4]),
    V6([u8; 16]),
}

impl Display for IpKey {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            IpKey::V4(a) => write!(f, "{}", Ipv4Addr::from(*a)),
            IpKey::V6(a) => write!(f, "{}", Ipv6Addr::from(*a)),
        }
    }
}

#[derive(Clone, Copy, Eq, PartialEq, Debug, Hash)]
struct FlowKey {
    src: IpKey,
    dst: IpKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl FlowKey {
    fn canonical(self) -> Self {
        let a = (&self.src, self.src_port, &self.dst, self.dst_port, self.proto);
        let b = (&self.dst, self.dst_port, &self.src, self.src_port, self.proto);
        if tuple_le(&a, &b) {
            self
        } else {
            FlowKey {
                src: self.dst,
                dst: self.src,
                src_port: self.dst_port,
                dst_port: self.src_port,
                proto: self.proto,
            }
        }
    }
}

fn tuple_le(
    a: &(&IpKey, u16, &IpKey, u16, u8),
    b: &(&IpKey, u16, &IpKey, u16, u8),
) -> bool {
    use std::cmp::Ordering::*;
    match cmp_ip(a.0, b.0) {
        Less => true,
        Greater => false,
        Equal => match a.1.cmp(&b.1) {
            Less => true,
            Greater => false,
            Equal => match cmp_ip(a.2, b.2) {
                Less => true,
                Greater => false,
                Equal => match a.3.cmp(&b.3) {
                    Less | Equal => true,
                    Greater => false,
                },
            },
        },
    }
}

fn cmp_ip(a: &IpKey, b: &IpKey) -> std::cmp::Ordering {
    match (a, b) {
        (IpKey::V4(x), IpKey::V4(y)) => x.cmp(y),
        (IpKey::V6(x), IpKey::V6(y)) => x.cmp(y),
        (IpKey::V4(_), IpKey::V6(_)) => std::cmp::Ordering::Less,
        (IpKey::V6(_), IpKey::V4(_)) => std::cmp::Ordering::Greater,
    }
}

#[derive(Clone, Copy, Debug)]
struct PacketMeta {
    ts_sec: u64,
    ts_usec: u32,
    len: u32,
    key: FlowKey,
    tcp_flags: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_sec: u64,
    last_seen_sec: u64,
    tcp_flags_or: u8,
}

impl FlowStats {
    fn new(pkt: &PacketMeta) -> Self {
        Self {
            packets: 1,
            bytes: pkt.len as u64,
            first_seen_sec: pkt.ts_sec,
            last_seen_sec: pkt.ts_sec,
            tcp_flags_or: pkt.tcp_flags,
        }
    }

    fn update(&mut self, pkt: &PacketMeta) {
        self.packets += 1;
        self.bytes += pkt.len as u64;
        self.last_seen_sec = pkt.ts_sec;
        self.tcp_flags_or |= pkt.tcp_flags;
    }
}

struct FlowShard {
    map: Mutex<AHashMap<FlowKey, FlowStats>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            map: Mutex::new(AHashMap::with_capacity(1 << 16)),
        }
    }
}

fn flow_shard_index(key: &FlowKey, n: usize) -> usize {
    let mut h = ahash::AHasher::default();
    key.hash(&mut h);
    (h.finish() as usize) % n
}

fn parse_packet(ts_sec: u64, ts_usec: u32, data: &[u8]) -> Option<PacketMeta> {
    let sliced = SlicedPacket::from_ethernet(data).ok()?;

    let (src, dst, proto) = match sliced.net? {
        InternetSlice::Ipv4(h, _) => (
            IpKey::V4(h.source()),
            IpKey::V4(h.destination()),
            h.protocol().0,
        ),
        InternetSlice::Ipv6(h, _) => (
            IpKey::V6(h.source()),
            IpKey::V6(h.destination()),
            h.next_header().0,
        ),
    };

    let (src_port, dst_port, tcp_flags) = match sliced.transport? {
        TransportSlice::Tcp(tcp) => {
            let mut flags = 0u8;
            if tcp.fin() { flags |= 0x01; }
            if tcp.syn() { flags |= 0x02; }
            if tcp.rst() { flags |= 0x04; }
            if tcp.psh() { flags |= 0x08; }
            if tcp.ack() { flags |= 0x10; }
            if tcp.urg() { flags |= 0x20; }
            (tcp.source_port(), tcp.destination_port(), flags)
        }
        TransportSlice::Udp(udp) => (udp.source_port(), udp.destination_port(), 0),
        _ => return None,
    };

    let key = FlowKey {
        src,
        dst,
        src_port,
        dst_port,
        proto,
    }
    .canonical();

    Some(PacketMeta {
        ts_sec,
        ts_usec,
        len: data.len() as u32,
        key,
        tcp_flags,
    })
}

fn worker_loop(
    id: usize,
    rx: Receiver<PacketMeta>,
    shard: Arc<FlowShard>,
    idle_timeout: u64,
    active_timeout: u64,
    print_flows: bool,
) {
    let mut processed: u64 = 0;
    let mut last_expire_check: u64 = 0;

    while let Ok(pkt) = rx.recv() {
        {
            let mut map = shard.map.lock();
            match map.get_mut(&pkt.key) {
                Some(stats) => stats.update(&pkt),
                None => {
                    map.insert(pkt.key, FlowStats::new(&pkt));
                }
            }
        }

        processed += 1;

        if pkt.ts_sec.saturating_sub(last_expire_check) >= 1 {
            expire_flows(
                id,
                &shard,
                pkt.ts_sec,
                idle_timeout,
                active_timeout,
                print_flows,
            );
            last_expire_check = pkt.ts_sec;
        }

        if processed % 1_000_000 == 0 {
            eprintln!("worker={id} processed={processed}");
        }
    }

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs();

    expire_all_flows(id, &shard, now, print_flows);
}

fn expire_flows(
    id: usize,
    shard: &Arc<FlowShard>,
    now_sec: u64,
    idle_timeout: u64,
    active_timeout: u64,
    print_flows: bool,
) {
    let mut expired = Vec::new();

    {
        let mut map = shard.map.lock();
        map.retain(|k, v| {
            let idle = now_sec.saturating_sub(v.last_seen_sec);
            let active = now_sec.saturating_sub(v.first_seen_sec);
            let keep = idle < idle_timeout && active < active_timeout;
            if !keep {
                expired.push((*k, v.clone()));
            }
            keep
        });
    }

    if print_flows {
        for (k, v) in expired {
            println!(
                "worker={} flow={}:{} <-> {}:{} proto={} packets={} bytes={} first={} last={} flags=0x{:02x}",
                id,
                k.src,
                k.src_port,
                k.dst,
                k.dst_port,
                k.proto,
                v.packets,
                v.bytes,
                v.first_seen_sec,
                v.last_seen_sec,
                v.tcp_flags_or
            );
        }
    }
}

fn expire_all_flows(id: usize, shard: &Arc<FlowShard>, _now_sec: u64, print_flows: bool) {
    let expired: Vec<(FlowKey, FlowStats)> = {
        let mut map = shard.map.lock();
        map.drain().collect()
    };

    if print_flows {
        for (k, v) in expired {
            println!(
                "worker={} flow={}:{} <-> {}:{} proto={} packets={} bytes={} first={} last={} flags=0x{:02x}",
                id,
                k.src,
                k.src_port,
                k.dst,
                k.dst_port,
                k.proto,
                v.packets,
                v.bytes,
                v.first_seen_sec,
                v.last_seen_sec,
                v.tcp_flags_or
            );
        }
    }
}

fn reader_loop(args: &Args, txs: &[Sender<PacketMeta>]) -> Result<(), Box<dyn std::error::Error>> {
    let mut cap = pcap::Capture::from_file(&args.pcap)?;

    while let Ok(packet) = cap.next_packet() {
        let ts_sec = packet.header.ts.tv_sec as u64;
        let ts_usec = packet.header.ts.tv_usec as u32;

        if let Some(meta) = parse_packet(ts_sec, ts_usec, packet.data) {
            let idx = flow_shard_index(&meta.key, txs.len());
            if txs[idx].send(meta).is_err() {
                break;
            }
        }
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    if args.workers == 0 {
        return Err("workers must be > 0".into());
    }

    let mut txs = Vec::with_capacity(args.workers);
    let mut handles = Vec::with_capacity(args.workers);

    for i in 0..args.workers {
        let (tx, rx) = bounded::<PacketMeta>(args.queue_size);
        txs.push(tx);

        let shard = Arc::new(FlowShard::new());
        let idle_timeout = args.idle_timeout;
        let active_timeout = args.active_timeout;
        let print_flows = args.print_flows;

        let handle = thread::spawn(move || {
            worker_loop(i, rx, shard, idle_timeout, active_timeout, print_flows)
        });

        handles.push(handle);
    }

    reader_loop(&args, &txs)?;

    drop(txs);

    for h in handles {
        let _ = h.join();
    }

    Ok(())
}
```

