# Initial implementation

```cpp
#include <arpa/inet.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/if_ether.h>
#include <linux/icmp.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#include <atomic>
#include <chrono>
#include <cinttypes>
#include <csignal>
#include <cstring>
#include <iostream>
#include <string>
#include <vector>

static volatile std::sig_atomic_t g_running = 1;

static void handle_signal(int) {
    g_running = 0;
}

static inline uint64_t now_ns() {
    timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    return uint64_t(ts.tv_sec) * 1000000000ull + uint64_t(ts.tv_nsec);
}

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint8_t pad[3];

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowStats {
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    uint8_t tcp_flags_or;
    uint8_t active;
    uint16_t pad;
};

struct FlowEntry {
    FlowKey key;
    FlowStats stats;
};

static inline uint64_t hash_flow_key(const FlowKey& k) {
    uint64_t x = 0x9e3779b97f4a7c15ull;
    x ^= k.src_ip + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);
    x ^= k.dst_ip + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);
    x ^= k.src_port + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);
    x ^= k.dst_port + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);
    x ^= k.protocol + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);

    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ull;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebull;
    x ^= x >> 31;
    return x;
}

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2),
          mask_(capacity_pow2 - 1),
          entries_(capacity_pow2) {
    }

    bool update(const FlowKey& key, uint32_t pkt_bytes, uint8_t tcp_flags, uint64_t ts_ns) {
        uint64_t h = hash_flow_key(key);
        size_t idx = h & mask_;

        for (size_t probe = 0; probe < max_probe_; ++probe) {
            FlowEntry& e = entries_[(idx + probe) & mask_];
            if (!e.stats.active) {
                e.key = key;
                e.stats.packets = 1;
                e.stats.bytes = pkt_bytes;
                e.stats.first_seen_ns = ts_ns;
                e.stats.last_seen_ns = ts_ns;
                e.stats.tcp_flags_or = tcp_flags;
                e.stats.active = 1;
                return true;
            }
            if (e.key == key) {
                e.stats.packets++;
                e.stats.bytes += pkt_bytes;
                e.stats.last_seen_ns = ts_ns;
                e.stats.tcp_flags_or |= tcp_flags;
                return true;
            }
        }

        dropped_updates_++;
        return false;
    }

    void expire_and_export(uint64_t now,
                           uint64_t inactive_timeout_ns,
                           uint64_t active_timeout_ns) {
        for (size_t i = expire_cursor_; i < expire_cursor_ + expire_batch_; ++i) {
            FlowEntry& e = entries_[i & mask_];
            if (!e.stats.active) continue;

            bool inactive = (now - e.stats.last_seen_ns) >= inactive_timeout_ns;
            bool active = (now - e.stats.first_seen_ns) >= active_timeout_ns;

            if (inactive || active) {
                export_flow(e);
                std::memset(&e, 0, sizeof(e));
            }
        }
        expire_cursor_ = (expire_cursor_ + expire_batch_) & mask_;
    }

    void export_all() {
        for (auto& e : entries_) {
            if (e.stats.active) {
                export_flow(e);
                std::memset(&e, 0, sizeof(e));
            }
        }
    }

    uint64_t dropped_updates() const {
        return dropped_updates_;
    }

private:
    void export_flow(const FlowEntry& e) {
        char src[INET_ADDRSTRLEN];
        char dst[INET_ADDRSTRLEN];
        in_addr saddr{e.key.src_ip};
        in_addr daddr{e.key.dst_ip};
        inet_ntop(AF_INET, &saddr, src, sizeof(src));
        inet_ntop(AF_INET, &daddr, dst, sizeof(dst));

        std::cout
            << src << ":" << ntohs(e.key.src_port)
            << " -> "
            << dst << ":" << ntohs(e.key.dst_port)
            << " proto=" << unsigned(e.key.protocol)
            << " packets=" << e.stats.packets
            << " bytes=" << e.stats.bytes
            << " tcp_flags=0x" << std::hex << unsigned(e.stats.tcp_flags_or) << std::dec
            << " duration_ms=" << ((e.stats.last_seen_ns - e.stats.first_seen_ns) / 1000000ull)
            << "\n";
    }

    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
    size_t expire_cursor_ = 0;
    static constexpr size_t max_probe_ = 16;
    static constexpr size_t expire_batch_ = 4096;
    uint64_t dropped_updates_ = 0;
};

struct ParsedPacket {
    FlowKey key{};
    uint32_t wire_bytes = 0;
    uint8_t tcp_flags = 0;
    bool valid = false;
};

static ParsedPacket parse_packet(const uint8_t* buf, ssize_t len) {
    ParsedPacket out{};
    if (len < (ssize_t)sizeof(ethhdr)) return out;

    const ethhdr* eth = reinterpret_cast<const ethhdr*>(buf);
    if (ntohs(eth->h_proto) != ETH_P_IP) return out;

    const uint8_t* ip_ptr = buf + sizeof(ethhdr);
    ssize_t ip_len = len - sizeof(ethhdr);
    if (ip_len < (ssize_t)sizeof(iphdr)) return out;

    const iphdr* ip = reinterpret_cast<const iphdr*>(ip_ptr);
    if (ip->version != 4) return out;

    uint32_t ihl = ip->ihl * 4;
    if (ihl < sizeof(iphdr) || ip_len < (ssize_t)ihl) return out;

    out.key.src_ip = ip->saddr;
    out.key.dst_ip = ip->daddr;
    out.key.protocol = ip->protocol;
    out.wire_bytes = static_cast<uint32_t>(len);

    const uint8_t* l4 = ip_ptr + ihl;
    ssize_t l4_len = ip_len - ihl;

    switch (ip->protocol) {
        case IPPROTO_TCP: {
            if (l4_len < (ssize_t)sizeof(tcphdr)) return out;
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4);
            out.key.src_port = tcp->source;
            out.key.dst_port = tcp->dest;
            out.tcp_flags =
                (tcp->fin ? TH_FIN : 0) |
                (tcp->syn ? TH_SYN : 0) |
                (tcp->rst ? TH_RST : 0) |
                (tcp->psh ? TH_PUSH : 0) |
                (tcp->ack ? TH_ACK : 0) |
                (tcp->urg ? TH_URG : 0);
            out.valid = true;
            return out;
        }
        case IPPROTO_UDP: {
            if (l4_len < (ssize_t)sizeof(udphdr)) return out;
            const udphdr* udp = reinterpret_cast<const udphdr*>(l4);
            out.key.src_port = udp->source;
            out.key.dst_port = udp->dest;
            out.valid = true;
            return out;
        }
        case IPPROTO_ICMP: {
            out.key.src_port = 0;
            out.key.dst_port = 0;
            out.valid = true;
            return out;
        }
        default:
            return out;
    }
}

static int bind_raw_socket(const std::string& ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int ifindex = if_nametoindex(ifname.c_str());
    if (ifindex == 0) {
        perror("if_nametoindex");
        close(fd);
        return -1;
    }

    sockaddr_ll sll{};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex;

    if (bind(fd, reinterpret_cast<sockaddr*>(&sll), sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    int rcvbuf = 64 * 1024 * 1024;
    if (setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)) < 0) {
        perror("setsockopt SO_RCVBUF");
    }

    return fd;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    std::signal(SIGINT, handle_signal);
    std::signal(SIGTERM, handle_signal);

    const std::string ifname = argv[1];
    int fd = bind_raw_socket(ifname);
    if (fd < 0) return 1;

    constexpr size_t flow_capacity = 1 << 20;
    FlowTable table(flow_capacity);

    constexpr size_t buf_size = 2048;
    alignas(64) uint8_t buf[buf_size];

    const uint64_t inactive_timeout_ns = 30ull * 1000000000ull;
    const uint64_t active_timeout_ns = 300ull * 1000000000ull;
    const uint64_t expire_interval_ns = 1000000000ull;

    uint64_t last_expire = now_ns();
    uint64_t packet_count = 0;
    uint64_t byte_count = 0;
    uint64_t last_stats = last_expire;

    while (g_running) {
        ssize_t n = recvfrom(fd, buf, sizeof(buf), 0, nullptr, nullptr);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        uint64_t ts = now_ns();
        ParsedPacket pkt = parse_packet(buf, n);
        if (pkt.valid) {
            table.update(pkt.key, pkt.wire_bytes, pkt.tcp_flags, ts);
            packet_count++;
            byte_count += pkt.wire_bytes;
        }

        if ((ts - last_expire) >= expire_interval_ns) {
            table.expire_and_export(ts, inactive_timeout_ns, active_timeout_ns);
            last_expire = ts;
        }

        if ((ts - last_stats) >= 5000000000ull) {
            double secs = double(ts - last_stats) / 1e9;
            std::cerr
                << "[stats] pps=" << (packet_count / secs)
                << " Bps=" << (byte_count / secs)
                << " dropped_flow_updates=" << table.dropped_updates()
                << "\n";
            packet_count = 0;
            byte_count = 0;
            last_stats = ts;
        }
    }

    table.export_all();
    close(fd);
    return 0;
}
