```rust
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Default)]
struct Fnv64Hasher(u64);

impl Hasher for Fnv64Hasher {
    fn write(&mut self, bytes: &[u8]) {
        const FNV_OFFSET: u64 = 0xcbf29ce484222325;
        const FNV_PRIME: u64 = 0x100000001b3;

        if self.0 == 0 {
            self.0 = FNV_OFFSET;
        }
        for b in bytes {
            self.0 ^= *b as u64;
            self.0 = self.0.wrapping_mul(FNV_PRIME);
        }
    }

    fn finish(&self) -> u64 {
        self.0
    }
}

type FastHashBuilder = BuildHasherDefault<Fnv64Hasher>;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize, tcp_flags: Option<u8>) -> Self {
        let mut s = Self {
            packets: 1,
            bytes: bytes as u64,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
            first_seen: now,
            last_seen: now,
        };
        if let Some(flags) = tcp_flags {
            s.update_tcp_flags(flags);
        }
        s
    }

    #[inline(always)]
    fn update(&mut self, now: Instant, bytes: usize, tcp_flags: Option<u8>) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
        if let Some(flags) = tcp_flags {
            self.update_tcp_flags(flags);
        }
    }

    #[inline(always)]
    fn update_tcp_flags(&mut self, flags: u8) {
        if flags & 0x02 != 0 {
            self.tcp_syn += 1;
        }
        if flags & 0x01 != 0 {
            self.tcp_fin += 1;
        }
        if flags & 0x04 != 0 {
            self.tcp_rst += 1;
        }
    }
}

struct FlowShard {
    map: Mutex<HashMap<FlowKey, FlowStats, FastHashBuilder>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            map: Mutex::new(HashMap::with_hasher(FastHashBuilder::default())),
        }
    }
}

struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    fn new() -> Self {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(FlowShard::new());
        }
        Self { shards }
    }

    #[inline(always)]
    fn shard_index(key: &FlowKey) -> usize {
        let mut h = Fnv64Hasher::default();
        h.write_u32(key.src_ip);
        h.write_u32(key.dst_ip);
        h.write_u16(key.src_port);
        h.write_u16(key.dst_port);
        h.write_u8(key.proto);
        (h.finish() as usize) & (NUM_SHARDS - 1)
    }

    #[inline(always)]
    fn update_flow(&self, key: FlowKey, now: Instant, bytes: usize, tcp_flags: Option<u8>) {
        let idx = Self::shard_index(&key);
        let shard = &self.shards[idx];
        let mut map = shard.map.lock().unwrap();
        match map.get_mut(&key) {
            Some(stats) => stats.update(now, bytes, tcp_flags),
            None => {
                map.insert(key, FlowStats::new(now, bytes, tcp_flags));
            }
        }
    }

    fn expire_idle(&self, now: Instant, idle_timeout: Duration) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.map.lock().unwrap();
            map.retain(|k, v| {
                if now.duration_since(v.last_seen) >= idle_timeout {
                    expired.push((*k, v.clone()));
                    false
                } else {
                    true
                }
            });
        }

        expired
    }

    fn snapshot_counts(&self) -> (usize, u64, u64) {
        let mut flows = 0usize;
        let mut packets = 0u64;
        let mut bytes = 0u64;

        for shard in &self.shards {
            let map = shard.map.lock().unwrap();
            flows += map.len();
            for stats in map.values() {
                packets += stats.packets;
                bytes += stats.bytes;
            }
        }

        (flows, packets, bytes)
    }
}

#[derive(Debug, Clone, Copy)]
struct ParsedPacket {
    flow_key: FlowKey,
    packet_len: usize,
    tcp_flags: Option<u8>,
}

#[inline(always)]
fn parse_packet(pkt: &[u8]) -> Option<ParsedPacket> {
    if pkt.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &pkt[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..];
    match proto {
        6 => {
            if l4.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            let flags = l4[13];

            Some(ParsedPacket {
                flow_key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                    _pad: 0,
                },
                packet_len: pkt.len(),
                tcp_flags: Some(flags),
            })
        }
        17 => {
            if l4.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);

            Some(ParsedPacket {
                flow_key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                    _pad: 0,
                },
                packet_len: pkt.len(),
                tcp_flags: None,
            })
        }
        _ => None,
    }
}

fn export_flow(key: FlowKey, stats: FlowStats) {
    println!(
        "{}:{} -> {}:{} proto={} packets={} bytes={} syn={} fin={} rst={} duration_ms={}",
        Ipv4Addr::from(key.src_ip),
        key.src_port,
        Ipv4Addr::from(key.dst_ip),
        key.dst_port,
        key.proto,
        stats.packets,
        stats.bytes,
        stats.tcp_syn,
        stats.tcp_fin,
        stats.tcp_rst,
        stats.last_seen.duration_since(stats.first_seen).as_millis()
    );
}

fn start_expirer(table: Arc<FlowTable>, running: Arc<AtomicBool>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last_export = Instant::now();

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_millis(500));
            let now = Instant::now();

            let expired = table.expire_idle(now, FLOW_IDLE_TIMEOUT);
            for (key, stats) in expired {
                export_flow(key, stats);
            }

            if now.duration_since(last_export) >= EXPORT_INTERVAL {
                let (flows, packets, bytes) = table.snapshot_counts();
                eprintln!(
                    "[stats] active_flows={} total_packets={} total_bytes={}",
                    flows, packets, bytes
                );
                last_export = now;
            }
        }

        let expired = table.expire_idle(Instant::now(), Duration::from_secs(0));
        for (key, stats) in expired {
            export_flow(key, stats);
        }
    })
}

fn process_packet(table: &FlowTable, pkt: &[u8]) {
    if let Some(parsed) = parse_packet(pkt) {
        table.update_flow(
            parsed.flow_key,
            Instant::now(),
            parsed.packet_len,
            parsed.tcp_flags,
        );
    }
}

fn synthetic_ipv4_tcp_packet(
    src_ip: [u8; 4],
    dst_ip: [u8; 4],
    src_port: u16,
    dst_port: u16,
    flags: u8,
    payload_len: usize,
) -> Vec<u8> {
    let total_len = 14 + 20 + 20 + payload_len;
    let mut pkt = vec![0u8; total_len];

    pkt[12] = 0x08;
    pkt[13] = 0x00;

    let ip = &mut pkt[14..];
    ip[0] = 0x45;
    let ip_total = (20 + 20 + payload_len) as u16;
    ip[2..4].copy_from_slice(&ip_total.to_be_bytes());
    ip[8] = 64;
    ip[9] = 6;
    ip[12..16].copy_from_slice(&src_ip);
    ip[16..20].copy_from_slice(&dst_ip);

    let tcp = &mut ip[20..];
    tcp[0..2].copy_from_slice(&src_port.to_be_bytes());
    tcp[2..4].copy_from_slice(&dst_port.to_be_bytes());
    tcp[12] = 5 << 4;
    tcp[13] = flags;

    pkt
}

fn main() {
    let table = Arc::new(FlowTable::new());
    let running = Arc::new(AtomicBool::new(true));

    let expirer = start_expirer(table.clone(), running.clone());

    for i in 0..1_000_000u32 {
        let pkt = synthetic_ipv4_tcp_packet(
            [10, 0, ((i >> 8) & 0xff) as u8, (i & 0xff) as u8],
            [192, 168, 1, 10],
            10000 + (i % 1024) as u16,
            443,
            if i % 1000 == 0 { 0x02 } else { 0x10 },
            100,
        );
        process_packet(&table, &pkt);
    }

    thread::sleep(Duration::from_secs(2));
    running.store(false, Ordering::Relaxed);
    expirer.join().unwrap();
}
```

