## `src/main.rs`

```rust
use anyhow::{Context, Result};
use dashmap::DashMap;
use pcap::{Active, Capture, Device};
use serde::Serialize;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tokio::signal;
use tokio::time;

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug, Serialize)]
struct FlowStats {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    packets: u64,
    bytes: u64,
    first_seen_unix: u64,
    last_seen_unix: u64,
}

#[derive(Clone, Debug)]
struct FlowCounters {
    packets: u64,
    bytes: u64,
    first_seen_unix: u64,
    last_seen_unix: u64,
}

type FlowTable = DashMap<FlowKey, FlowCounters>;

fn now_unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn ipv4_to_string(ip: u32) -> String {
    Ipv4Addr::from(ip).to_string()
}

fn parse_ethernet_ipv4_packet(packet: &[u8]) -> Option<(FlowKey, usize)> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip_start = 14;
    if packet.len() < ip_start + 20 {
        return None;
    }

    let version_ihl = packet[ip_start];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || packet.len() < ip_start + ihl {
        return None;
    }

    let proto = packet[ip_start + 9];
    let src_ip = u32::from_be_bytes([
        packet[ip_start + 12],
        packet[ip_start + 13],
        packet[ip_start + 14],
        packet[ip_start + 15],
    ]);
    let dst_ip = u32::from_be_bytes([
        packet[ip_start + 16],
        packet[ip_start + 17],
        packet[ip_start + 18],
        packet[ip_start + 19],
    ]);

    let l4_start = ip_start + ihl;

    match proto {
        6 | 17 => {
            if packet.len() < l4_start + 4 {
                return None;
            }
            let src_port = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
            let dst_port = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);

            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                packet.len(),
            ))
        }
        _ => None,
    }
}

fn update_flow(table: &FlowTable, key: FlowKey, bytes: usize, ts: u64) {
    if let Some(mut entry) = table.get_mut(&key) {
        entry.packets += 1;
        entry.bytes += bytes as u64;
        entry.last_seen_unix = ts;
    } else {
        table.insert(
            key,
            FlowCounters {
                packets: 1,
                bytes: bytes as u64,
                first_seen_unix: ts,
                last_seen_unix: ts,
            },
        );
    }
}

fn export_flows(table: &FlowTable, idle_timeout_secs: u64) -> Vec<FlowStats> {
    let now = now_unix_secs();
    let mut expired = Vec::new();
    let mut remove_keys = Vec::new();

    for entry in table.iter() {
        if now.saturating_sub(entry.last_seen_unix) >= idle_timeout_secs {
            let key = *entry.key();
            let counters = entry.value().clone();

            expired.push(FlowStats {
                src_ip: ipv4_to_string(key.src_ip),
                dst_ip: ipv4_to_string(key.dst_ip),
                src_port: key.src_port,
                dst_port: key.dst_port,
                proto: key.proto,
                packets: counters.packets,
                bytes: counters.bytes,
                first_seen_unix: counters.first_seen_unix,
                last_seen_unix: counters.last_seen_unix,
            });

            remove_keys.push(key);
        }
    }

    for key in remove_keys {
        table.remove(&key);
    }

    expired
}

async fn exporter_task(table: Arc<FlowTable>, idle_timeout_secs: u64, interval_secs: u64) {
    let mut ticker = time::interval(Duration::from_secs(interval_secs));

    loop {
        ticker.tick().await;
        let flows = export_flows(&table, idle_timeout_secs);
        for flow in flows {
            match serde_json::to_string(&flow) {
                Ok(line) => println!("{line}"),
                Err(e) => eprintln!("failed to serialize flow: {e}"),
            }
        }
    }
}

fn capture_loop(mut cap: Capture<Active>, table: Arc<FlowTable>) -> Result<()> {
    loop {
        match cap.next_packet() {
            Ok(packet) => {
                if let Some((key, bytes)) = parse_ethernet_ipv4_packet(packet.data) {
                    let ts = now_unix_secs();
                    update_flow(&table, key, bytes, ts);
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => return Err(e).context("packet capture failed"),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let interface = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == interface)
        .with_context(|| format!("interface not found: {interface}"))?;

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .timeout(1000)
        .open()
        .context("failed to open capture")?;

    cap.filter("ip and (tcp or udp)", true)
        .context("failed to install BPF filter")?;

    let table = Arc::new(DashMap::with_capacity(1_000_000));

    let exporter_table = Arc::clone(&table);
    let exporter = tokio::spawn(async move {
        exporter_task(exporter_table, 30, 5).await;
    });

    let capture_table = Arc::clone(&table);
    let capture_handle = tokio::task::spawn_blocking(move || capture_loop(cap, capture_table));

    tokio::select! {
        _ = signal::ctrl_c() => {
            eprintln!("received Ctrl-C, shutting down");
        }
        res = exporter => {
            eprintln!("exporter task ended: {:?}", res);
        }
        res = capture_handle => {
            eprintln!("capture task ended: {:?}", res);
        }
    }

    Ok(())
}
```

