```rust
use anyhow::{Context, Result};
use crossbeam_channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use pcap::{Capture, Device};
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const CHANNEL_SIZE: usize = 8192;
const IDLE_TIMEOUT_SECS: u64 = 30;
const EXPORT_INTERVAL_SECS: u64 = 5;

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    tcp_flags: u8,
}

#[derive(Debug)]
struct PacketMeta {
    ts_sec: u64,
    len: u32,
    key: FlowKey,
    tcp_flags: u8,
}

struct FlowTable {
    shards: Vec<Mutex<HashMap<FlowKey, FlowStats>>>,
}

impl FlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(Mutex::new(HashMap::with_capacity(65536)));
        }
        Self { shards }
    }

    #[inline]
    fn shard_for(&self, key: &FlowKey) -> usize {
        let mut h = std::collections::hash_map::DefaultHasher::new();
        key.hash(&mut h);
        (h.finish() as usize) % self.shards.len()
    }

    fn update(&self, pkt: PacketMeta) {
        let shard_idx = self.shard_for(&pkt.key);
        let mut shard = self.shards[shard_idx].lock();

        let entry = shard.entry(pkt.key).or_insert(FlowStats {
            packets: 0,
            bytes: 0,
            first_seen: pkt.ts_sec,
            last_seen: pkt.ts_sec,
            tcp_flags: 0,
        });

        entry.packets += 1;
        entry.bytes += pkt.len as u64;
        entry.last_seen = pkt.ts_sec;
        entry.tcp_flags |= pkt.tcp_flags;
    }

    fn expire_idle(&self, now_sec: u64, idle_timeout: u64) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.lock();
            let mut to_remove = Vec::new();

            for (k, v) in map.iter() {
                if now_sec.saturating_sub(v.last_seen) >= idle_timeout {
                    to_remove.push(*k);
                }
            }

            for k in to_remove {
                if let Some(v) = map.remove(&k) {
                    expired.push((k, v));
                }
            }
        }

        expired
    }
}

fn now_unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0))
        .as_secs()
}

fn parse_packet(data: &[u8], ts_sec: u64) -> Option<PacketMeta> {
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip_start = 14;
    if data.len() < ip_start + 20 {
        return None;
    }

    let version_ihl = data[ip_start];
    let version = version_ihl >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || data.len() < ip_start + ihl {
        return None;
    }

    let proto = data[ip_start + 9];
    let src_ip = u32::from_be_bytes([
        data[ip_start + 12],
        data[ip_start + 13],
        data[ip_start + 14],
        data[ip_start + 15],
    ]);
    let dst_ip = u32::from_be_bytes([
        data[ip_start + 16],
        data[ip_start + 17],
        data[ip_start + 18],
        data[ip_start + 19],
    ]);

    let l4_start = ip_start + ihl;

    match proto {
        6 => {
            if data.len() < l4_start + 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([data[l4_start], data[l4_start + 1]]);
            let dst_port = u16::from_be_bytes([data[l4_start + 2], data[l4_start + 3]]);
            let flags = data[l4_start + 13];

            Some(PacketMeta {
                ts_sec,
                len: data.len() as u32,
                key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                tcp_flags: flags,
            })
        }
        17 => {
            if data.len() < l4_start + 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([data[l4_start], data[l4_start + 1]]);
            let dst_port = u16::from_be_bytes([data[l4_start + 2], data[l4_start + 3]]);

            Some(PacketMeta {
                ts_sec,
                len: data.len() as u32,
                key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                tcp_flags: 0,
            })
        }
        _ => None,
    }
}

fn capture_thread(iface: String, tx: Sender<PacketMeta>) -> Result<()> {
    let mut cap = Capture::from_device(iface.as_str())
        .context("failed to create capture from device")?
        .promisc(true)
        .immediate_mode(true)
        .open()
        .context("failed to open capture")?;

    cap.filter("ip and (tcp or udp)", true)
        .context("failed to install BPF filter")?;

    while let Ok(packet) = cap.next_packet() {
        let ts_sec = packet.header.ts.tv_sec as u64;
        if let Some(meta) = parse_packet(packet.data, ts_sec) {
            if tx.send(meta).is_err() {
                break;
            }
        }
    }

    Ok(())
}

fn worker_thread(rx: Receiver<PacketMeta>, table: Arc<FlowTable>) {
    while let Ok(pkt) = rx.recv() {
        table.update(pkt);
    }
}

fn exporter_thread(table: Arc<FlowTable>) {
    loop {
        thread::sleep(Duration::from_secs(EXPORT_INTERVAL_SECS));
        let now = now_unix_secs();
        let expired = table.expire_idle(now, IDLE_TIMEOUT_SECS);

        for (k, v) in expired {
            println!(
                "{{\"src_ip\":\"{}\",\"dst_ip\":\"{}\",\"src_port\":{},\"dst_port\":{},\"proto\":{},\"packets\":{},\"bytes\":{},\"first_seen\":{},\"last_seen\":{},\"tcp_flags\":{}}}",
                Ipv4Addr::from(k.src_ip),
                Ipv4Addr::from(k.dst_ip),
                k.src_port,
                k.dst_port,
                k.proto,
                v.packets,
                v.bytes,
                v.first_seen,
                v.last_seen,
                v.tcp_flags
            );
        }
    }
}

fn main() -> Result<()> {
    let iface = std::env::args()
        .nth(1)
        .or_else(|| Device::lookup().ok().flatten().map(|d| d.name))
        .context("no interface provided and no default device found")?;

    let (tx, rx) = bounded::<PacketMeta>(CHANNEL_SIZE);
    let table = Arc::new(FlowTable::new(NUM_SHARDS));

    let capture_iface = iface.clone();
    let tx_capture = tx.clone();
    let capture_handle = thread::spawn(move || {
        if let Err(e) = capture_thread(capture_iface, tx_capture) {
            eprintln!("capture thread error: {e:#}");
        }
    });

    let workers = std::cmp::max(1, num_cpus::get() - 1);
    let mut worker_handles = Vec::new();

    for _ in 0..workers {
        let rx_clone = rx.clone();
        let table_clone = Arc::clone(&table);
        worker_handles.push(thread::spawn(move || {
            worker_thread(rx_clone, table_clone);
        }));
    }

    let exporter_table = Arc::clone(&table);
    let exporter_handle = thread::spawn(move || {
        exporter_thread(exporter_table);
    });

    let _ = capture_handle.join();
    drop(tx);

    for h in worker_handles {
        let _ = h.join();
    }

    let _ = exporter_handle.join();
    Ok(())
}
```

