use ahash::RandomState;
use hashbrown::HashMap;
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

const ACTIVE_TIMEOUT: Duration = Duration::from_secs(300);
const INACTIVE_TIMEOUT: Duration = Duration::from_secs(30);
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);
const MAX_FLOWS_HINT: usize = 1 << 20;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

#[derive(Debug, Clone, Copy)]
#[repr(C)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_flags_or: u8,
}

impl FlowStats {
    #[inline]
    fn new(now: Instant, bytes: usize, tcp_flags: u8) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_flags_or: tcp_flags,
        }
    }

    #[inline]
    fn update(&mut self, now: Instant, bytes: usize, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
        self.tcp_flags_or |= tcp_flags;
    }
}

#[derive(Debug, Clone, Copy)]
struct ParsedFlow {
    key: FlowKey,
    tcp_flags: u8,
}

#[inline]
fn ipv4_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from_be_bytes(ip.octets())
}

#[inline]
fn parse_flow(packet: &[u8]) -> Option<ParsedFlow> {
    let eth = EthernetPacket::new(packet)?;
    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return None;
    }

    let ipv4 = Ipv4Packet::new(eth.payload())?;
    let src_ip = ipv4_to_u32(ipv4.get_source());
    let dst_ip = ipv4_to_u32(ipv4.get_destination());
    let proto = ipv4.get_next_level_protocol();

    match proto {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ipv4.payload())?;
            Some(ParsedFlow {
                key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: 6,
                    _pad: 0,
                },
                tcp_flags: tcp.get_flags(),
            })
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ipv4.payload())?;
            Some(ParsedFlow {
                key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: 17,
                    _pad: 0,
                },
                tcp_flags: 0,
            })
        }
        _ => None,
    }
}

#[inline]
fn export_flow(key: &FlowKey, stats: &FlowStats) {
    let src = Ipv4Addr::from(key.src_ip.to_be_bytes());
    let dst = Ipv4Addr::from(key.dst_ip.to_be_bytes());

    println!(
        concat!(
            "{{",
            "\"src\":\"{}\",",
            "\"dst\":\"{}\",",
            "\"sport\":{},",
            "\"dport\":{},",
            "\"proto\":{},",
            "\"packets\":{},",
            "\"bytes\":{},",
            "\"tcp_flags_or\":{}",
            "}}"
        ),
        src,
        dst,
        key.src_port,
        key.dst_port,
        key.proto,
        stats.packets,
        stats.bytes,
        stats.tcp_flags_or
    );
}

fn expire_and_export(flows: &mut HashMap<FlowKey, FlowStats, RandomState>, now: Instant) {
    let mut expired = Vec::with_capacity(1024);

    for (k, v) in flows.iter() {
        let inactive = now.duration_since(v.last_seen) >= INACTIVE_TIMEOUT;
        let active = now.duration_since(v.first_seen) >= ACTIVE_TIMEOUT;
        if inactive || active {
            expired.push((*k, *v));
        }
    }

    for (k, v) in expired {
        flows.remove(&k);
        export_flow(&k, &v);
    }
}

fn pick_interface(name: Option<&str>) -> Option<NetworkInterface> {
    let interfaces = datalink::interfaces();
    if let Some(name) = name {
        interfaces.into_iter().find(|i| i.name == name)
    } else {
        interfaces
            .into_iter()
            .find(|i| i.is_up() && !i.is_loopback() && !i.ips.is_empty())
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })
        .expect("failed to install Ctrl-C handler");
    }

    let iface_name = std::env::args().nth(1);
    let interface = pick_interface(iface_name.as_deref()).expect("no suitable interface found");

    eprintln!("capturing on interface: {}", interface.name);

    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(10));
    config.promiscuous = true;

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("unsupported channel type"),
        Err(e) => panic!("failed to create datalink channel: {e}"),
    };

    let hasher = RandomState::new();
    let mut flows: HashMap<FlowKey, FlowStats, RandomState> =
        HashMap::with_capacity_and_hasher(MAX_FLOWS_HINT, hasher);

    let mut last_export = Instant::now();

    while running.load(Ordering::Relaxed) {
        match rx.next() {
            Ok(packet) => {
                let now = Instant::now();
                if let Some(parsed) = parse_flow(packet) {
                    match flows.get_mut(&parsed.key) {
                        Some(stats) => stats.update(now, packet.len(), parsed.tcp_flags),
                        None => {
                            flows.insert(parsed.key, FlowStats::new(now, packet.len(), parsed.tcp_flags));
                        }
                    }
                }

                if now.duration_since(last_export) >= EXPORT_INTERVAL {
                    expire_and_export(&mut flows, now);
                    last_export = now;
                }
            }
            Err(_) => {
                let now = Instant::now();
                if now.duration_since(last_export) >= EXPORT_INTERVAL {
                    expire_and_export(&mut flows, now);
                    last_export = now;
                }
            }
        }
    }

    eprintln!("shutting down, exporting remaining flows...");
    for (k, v) in flows.drain() {
        export_flow(&k, &v);
    }
}
```

