# Optional improved parser sketch

Here’s an example of a lower-overhead parser style you could move toward:

```rust
#[inline(always)]
fn read_u16_be(buf: &[u8], off: usize) -> Option<u16> {
    let bytes = buf.get(off..off + 2)?;
    Some(u16::from_be_bytes([bytes[0], bytes[1]]))
}

#[inline(always)]
fn read_u32_be(buf: &[u8], off: usize) -> Option<u32> {
    let bytes = buf.get(off..off + 4)?;
    Some(u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
}

#[inline(always)]
fn parse_flow_fast(packet: &[u8]) -> Option<ParsedFlow> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = read_u16_be(packet, 12)?;
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    if version_ihl >> 4 != 4 {
        return None;
    }

    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    let src_ip = read_u32_be(ip, 12)?;
    let dst_ip = read_u32_be(ip, 16)?;

    let l4 = &ip[ihl..];
    if l4.len() < 4 {
        return None;
    }

    let src_port = read_u16_be(l4, 0)?;
    let dst_port = read_u16_be(l4, 2)?;

    match proto {
        6 => {
            if l4.len() < 14 {
                return None;
            }
            let tcp_flags = l4[13];
            Some(ParsedFlow {
                key: FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                    _pad: 0,
                },
                tcp_flags,
            })
        }
        17 => Some(ParsedFlow {
            key: FlowKey {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
                _pad: 0,
            },
            tcp_flags: 0,
        }),
        _ => None,
    }
}
```

This avoids object wrapper overhead and is closer to what you’d want in a hot path.

