```rust
use ahash::AHasher;
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Active, Capture, Device};
use std::fmt::{Display, Formatter};
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const FLOW_ACTIVE_TIMEOUT: Duration = Duration::from_secs(300);
const PACKET_CHANNEL_SIZE: usize = 8192;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum TransportProto {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: TransportProto,
}

impl FlowKey {
    fn canonical(self) -> Self {
        let a = (
            self.src_ip,
            self.src_port,
        );
        let b = (
            self.dst_ip,
            self.dst_port,
        );
        if a < b {
            self
        } else if a > b {
            Self {
                src_ip: self.dst_ip,
                dst_ip: self.src_ip,
                src_port: self.dst_port,
                dst_port: self.src_port,
                proto: self.proto,
            }
        } else {
            // Tie-break on protocol only if needed; usually src/dst pair is enough.
            self
        }
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct TcpFlagsSummary {
    syn: bool,
    ack: bool,
    fin: bool,
    rst: bool,
    psh: bool,
    urg: bool,
}

impl TcpFlagsSummary {
    fn update_from_bits(&mut self, bits: u8) {
        self.fin |= bits & 0x01 != 0;
        self.syn |= bits & 0x02 != 0;
        self.rst |= bits & 0x04 != 0;
        self.psh |= bits & 0x08 != 0;
        self.ack |= bits & 0x10 != 0;
        self.urg |= bits & 0x20 != 0;
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets_ab: u64,
    bytes_ab: u64,
    packets_ba: u64,
    bytes_ba: u64,
    first_seen_ms: u128,
    last_seen_ms: u128,
    tcp_flags: TcpFlagsSummary,
}

impl FlowStats {
    fn new(ts_ms: u128) -> Self {
        Self {
            packets_ab: 0,
            bytes_ab: 0,
            packets_ba: 0,
            bytes_ba: 0,
            first_seen_ms: ts_ms,
            last_seen_ms: ts_ms,
            tcp_flags: TcpFlagsSummary::default(),
        }
    }
}

#[derive(Clone, Debug)]
struct PacketMeta {
    ts_ms: u128,
    len: usize,
    key: FlowKey,
    forward: bool,
    tcp_flags: Option<u8>,
}

type FlowTable = DashMap<FlowKey, FlowStats>;

struct ShardedFlowTable {
    shards: Vec<FlowTable>,
}

impl ShardedFlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(DashMap::with_capacity(1 << 16));
        }
        Self { shards }
    }

    fn shard_for(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shards.len()
    }

    fn update(&self, pkt: PacketMeta) {
        let shard_idx = self.shard_for(&pkt.key);
        let shard = &self.shards[shard_idx];

        if let Some(mut entry) = shard.get_mut(&pkt.key) {
            if pkt.forward {
                entry.packets_ab += 1;
                entry.bytes_ab += pkt.len as u64;
            } else {
                entry.packets_ba += 1;
                entry.bytes_ba += pkt.len as u64;
            }
            entry.last_seen_ms = pkt.ts_ms;
            if let Some(flags) = pkt.tcp_flags {
                entry.tcp_flags.update_from_bits(flags);
            }
        } else {
            let mut stats = FlowStats::new(pkt.ts_ms);
            if pkt.forward {
                stats.packets_ab = 1;
                stats.bytes_ab = pkt.len as u64;
            } else {
                stats.packets_ba = 1;
                stats.bytes_ba = pkt.len as u64;
            }
            if let Some(flags) = pkt.tcp_flags {
                stats.tcp_flags.update_from_bits(flags);
            }
            shard.insert(pkt.key, stats);
        }
    }

    fn expire_and_export(&self, now_ms: u128) {
        let idle_ms = FLOW_IDLE_TIMEOUT.as_millis();
        let active_ms = FLOW_ACTIVE_TIMEOUT.as_millis();

        for shard in &self.shards {
            let mut expired = Vec::new();

            for entry in shard.iter() {
                let age = now_ms.saturating_sub(entry.first_seen_ms);
                let idle = now_ms.saturating_sub(entry.last_seen_ms);

                if idle >= idle_ms || age >= active_ms {
                    expired.push((*entry.key(), entry.value().clone()));
                }
            }

            for (key, stats) in expired {
                shard.remove(&key);
                export_flow(&key, &stats);
            }
        }
    }
}

fn export_flow(key: &FlowKey, stats: &FlowStats) {
    println!(
        "{}:{} <-> {}:{} proto={:?} pkts_ab={} bytes_ab={} pkts_ba={} bytes_ba={} first={} last={} flags=[SYN:{} ACK:{} FIN:{} RST:{} PSH:{} URG:{}]",
        Ipv4Addr::from(key.src_ip),
        key.src_port,
        Ipv4Addr::from(key.dst_ip),
        key.dst_port,
        key.proto,
        stats.packets_ab,
        stats.bytes_ab,
        stats.packets_ba,
        stats.bytes_ba,
        stats.first_seen_ms,
        stats.last_seen_ms,
        stats.tcp_flags.syn,
        stats.tcp_flags.ack,
        stats.tcp_flags.fin,
        stats.tcp_flags.rst,
        stats.tcp_flags.psh,
        stats.tcp_flags.urg
    );
}

#[derive(Debug)]
enum ParseError {
    NotIpv4,
    NotTcpUdp,
    Malformed,
}

impl Display for ParseError {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        write!(f, "{self:?}")
    }
}

fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis()
}

fn parse_packet(data: &[u8], ts_ms: u128) -> Result<PacketMeta, ParseError> {
    let sliced = SlicedPacket::from_ethernet(data).map_err(|_| ParseError::Malformed)?;

    let (src_ip, dst_ip, proto) = match sliced.ip {
        Some(InternetSlice::Ipv4(header, _)) => {
            let src = u32::from_be_bytes(header.source());
            let dst = u32::from_be_bytes(header.destination());
            let proto = header.protocol();
            (src, dst, proto)
        }
        _ => return Err(ParseError::NotIpv4),
    };

    match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => {
            let raw_key = FlowKey {
                src_ip,
                dst_ip,
                src_port: tcp.source_port(),
                dst_port: tcp.destination_port(),
                proto: TransportProto::Tcp,
            };
            let key = raw_key.canonical();
            let forward = raw_key == key;

            Ok(PacketMeta {
                ts_ms,
                len: data.len(),
                key,
                forward,
                tcp_flags: Some(tcp.flags()),
            })
        }
        Some(TransportSlice::Udp(udp)) => {
            let raw_key = FlowKey {
                src_ip,
                dst_ip,
                src_port: udp.source_port(),
                dst_port: udp.destination_port(),
                proto: TransportProto::Udp,
            };
            let key = raw_key.canonical();
            let forward = raw_key == key;

            Ok(PacketMeta {
                ts_ms,
                len: data.len(),
                key,
                forward,
                tcp_flags: None,
            })
        }
        _ => Err(ParseError::NotTcpUdp),
    }
}

fn capture_loop(mut cap: Capture<Active>, tx: Sender<PacketMeta>) {
    while let Ok(packet) = cap.next_packet() {
        let ts_ms =
            (packet.header.ts.tv_sec as u128 * 1000) + (packet.header.ts.tv_usec as u128 / 1000);

        if let Ok(meta) = parse_packet(packet.data, ts_ms) {
            if tx.try_send(meta).is_err() {
                // Channel full: drop packet metadata rather than blocking hot path.
            }
        }
    }
}

fn worker_loop(rx: Receiver<PacketMeta>, table: Arc<ShardedFlowTable>) {
    while let Ok(pkt) = rx.recv() {
        table.update(pkt);
    }
}

fn exporter_loop(table: Arc<ShardedFlowTable>) {
    loop {
        thread::sleep(EXPORT_INTERVAL);
        table.expire_and_export(now_ms());
    }
}

fn open_capture(dev: &str) -> Capture<Active> {
    Capture::from_device(dev)
        .unwrap()
        .promisc(true)
        .immediate_mode(true)
        .snaplen(256)
        .buffer_size(8 * 1024 * 1024)
        .open()
        .unwrap()
}

fn main() {
    let dev = std::env::args()
        .nth(1)
        .unwrap_or_else(|| Device::lookup().unwrap().unwrap().name);

    let cap = open_capture(&dev);
    let (tx, rx) = bounded::<PacketMeta>(PACKET_CHANNEL_SIZE);

    let table = Arc::new(ShardedFlowTable::new(NUM_SHARDS));

    let worker_count = num_cpus::get().max(2) - 1;
    let mut workers = Vec::new();

    {
        let tx_capture = tx.clone();
        workers.push(thread::spawn(move || {
            capture_loop(cap, tx_capture);
        }));
    }

    for _ in 0..worker_count {
        let rx_worker = rx.clone();
        let table_worker = Arc::clone(&table);
        workers.push(thread::spawn(move || {
            worker_loop(rx_worker, table_worker);
        }));
    }

    {
        let table_export = Arc::clone(&table);
        workers.push(thread::spawn(move || {
            exporter_loop(table_export);
        }));
    }

    for handle in workers {
        let _ = handle.join();
    }
}
