use ahash::AHashMap;
use crossbeam_channel::{bounded, Receiver, Sender};
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::icmp::IcmpPacket;
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const EXPORT_INTERVAL: Duration = Duration::from_secs(5);
const CHANNEL_CAPACITY: usize = 65536;

#[derive(Clone, Copy, Debug, Eq)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u32(self.src_ip);
        state.write_u32(self.dst_ip);
        state.write_u16(self.src_port);
        state.write_u16(self.dst_port);
        state.write_u8(self.proto);
    }
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_flags_or: u8,
}

#[derive(Debug)]
struct ExportRecord {
    key: FlowKey,
    stats: FlowStats,
}

fn ipv4_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from_be_bytes(ip.octets())
}

fn parse_flow(packet: &[u8], now: Instant) -> Option<(FlowKey, usize, u8)> {
    let eth = EthernetPacket::new(packet)?;
    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return None;
    }

    let ip = Ipv4Packet::new(eth.payload())?;
    let src_ip = ipv4_to_u32(ip.get_source());
    let dst_ip = ipv4_to_u32(ip.get_destination());
    let proto = ip.get_next_level_protocol();

    match proto {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ip.payload())?;
            let key = FlowKey {
                src_ip,
                dst_ip,
                src_port: tcp.get_source(),
                dst_port: tcp.get_destination(),
                proto: 6,
                _pad: 0,
            };
            Some((key, packet.len(), tcp.get_flags()))
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ip.payload())?;
            let key = FlowKey {
                src_ip,
                dst_ip,
                src_port: udp.get_source(),
                dst_port: udp.get_destination(),
                proto: 17,
                _pad: 0,
            };
            Some((key, packet.len(), 0))
        }
        IpNextHeaderProtocols::Icmp => {
            let _icmp = IcmpPacket::new(ip.payload())?;
            let key = FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto: 1,
                _pad: 0,
            };
            Some((key, packet.len(), 0))
        }
        _ => None,
    }
}

fn update_flow(
    table: &mut AHashMap<FlowKey, FlowStats>,
    key: FlowKey,
    bytes: usize,
    tcp_flags: u8,
    now: Instant,
) {
    if let Some(stats) = table.get_mut(&key) {
        stats.packets += 1;
        stats.bytes += bytes as u64;
        stats.last_seen = now;
        stats.tcp_flags_or |= tcp_flags;
    } else {
        table.insert(
            key,
            FlowStats {
                packets: 1,
                bytes: bytes as u64,
                first_seen: now,
                last_seen: now,
                tcp_flags_or: tcp_flags,
            },
        );
    }
}

fn expire_flows(
    table: &mut AHashMap<FlowKey, FlowStats>,
    now: Instant,
    export_tx: &Sender<ExportRecord>,
) {
    let mut expired = Vec::new();

    for (key, stats) in table.iter() {
        if now.duration_since(stats.last_seen) >= FLOW_IDLE_TIMEOUT {
            expired.push(*key);
        }
    }

    for key in expired {
        if let Some(stats) = table.remove(&key) {
            let _ = export_tx.send(ExportRecord { key, stats });
        }
    }
}

fn exporter_thread(rx: Receiver<ExportRecord>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(500)) {
            Ok(record) => {
                println!(
                    "FLOW src={}:{} dst={}:{} proto={} packets={} bytes={} duration_ms={} tcp_flags_or=0x{:02x}",
                    Ipv4Addr::from(record.key.src_ip),
                    record.key.src_port,
                    Ipv4Addr::from(record.key.dst_ip),
                    record.key.dst_port,
                    record.key.proto,
                    record.stats.packets,
                    record.stats.bytes,
                    record
                        .stats
                        .last_seen
                        .duration_since(record.stats.first_seen)
                        .as_millis(),
                    record.stats.tcp_flags_or
                );
            }
            Err(_) => {}
        }
    }
}

fn capture_thread(
    interface: NetworkInterface,
    export_tx: Sender<ExportRecord>,
    running: Arc<AtomicBool>,
) {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(10));
    config.promiscuous = true;

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => {
            eprintln!("Unhandled channel type");
            return;
        }
        Err(e) => {
            eprintln!("Failed to create datalink channel: {}", e);
            return;
        }
    };

    let mut table: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(1 << 20);
    let mut last_export = Instant::now();

    while running.load(Ordering::Relaxed) {
        match rx.next() {
            Ok(packet) => {
                let now = Instant::now();
                if let Some((key, bytes, tcp_flags)) = parse_flow(packet, now) {
                    update_flow(&mut table, key, bytes, tcp_flags, now);
                }

                if now.duration_since(last_export) >= EXPORT_INTERVAL {
                    expire_flows(&mut table, now, &export_tx);
                    last_export = now;
                }
            }
            Err(_) => {
                let now = Instant::now();
                if now.duration_since(last_export) >= EXPORT_INTERVAL {
                    expire_flows(&mut table, now, &export_tx);
                    last_export = now;
                }
            }
        }
    }

    let now = Instant::now();
    let keys: Vec<_> = table.keys().copied().collect();
    for key in keys {
        if let Some(stats) = table.remove(&key) {
            let _ = export_tx.send(ExportRecord { key, stats });
        }
    }
}

fn main() {
    let interface_name = std::env::args()
        .nth(1)
        .expect("usage: flow_analyzer <interface>");

    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == interface_name)
        .expect("interface not found");

    let running = Arc::new(AtomicBool::new(true));
    let (export_tx, export_rx) = bounded::<ExportRecord>(CHANNEL_CAPACITY);

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })
        .expect("failed to install Ctrl-C handler");
    }

    let exporter_running = running.clone();
    let exporter = thread::spawn(move || exporter_thread(export_rx, exporter_running));

    let capture_running = running.clone();
    let capture = thread::spawn(move || capture_thread(interface, export_tx, capture_running));

    capture.join().unwrap();
    exporter.join().unwrap();
}
