# src/flow.rs

```rust
use ahash::RandomState;
use parking_lot::Mutex;
use serde::Serialize;
use std::collections::HashMap;
use std::hash::{BuildHasher, Hash, Hasher};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

#[derive(Clone, Debug, Serialize)]
pub struct FlowRecord {
    pub src_ip: String,
    pub dst_ip: String,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub packets: u64,
    pub bytes: u64,
    pub first_seen_ms: u128,
    pub last_seen_ms: u128,
    pub tcp_flags: u8,
}

#[derive(Clone, Copy, Debug)]
pub struct FlowValue {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen_ms: u128,
    pub last_seen_ms: u128,
    pub tcp_flags: u8,
}

pub struct Shard {
    map: Mutex<HashMap<FlowKey, FlowValue, RandomState>>,
}

pub struct FlowTable {
    shards: Vec<Shard>,
    hasher: RandomState,
}

impl FlowTable {
    pub fn new(shard_count: usize) -> Self {
        let mut shards = Vec::with_capacity(shard_count);
        for _ in 0..shard_count {
            shards.push(Shard {
                map: Mutex::new(HashMap::with_hasher(RandomState::new())),
            });
        }
        Self {
            shards,
            hasher: RandomState::new(),
        }
    }

    #[inline]
    fn now_ms() -> u128 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or(Duration::ZERO)
            .as_millis()
    }

    #[inline]
    fn shard_idx(&self, key: &FlowKey) -> usize {
        let mut h = self.hasher.build_hasher();
        key.hash(&mut h);
        (h.finish() as usize) % self.shards.len()
    }

    #[inline]
    pub fn update_flow(&self, key: FlowKey, pkt_len: usize, tcp_flags: u8) {
        let now = Self::now_ms();
        let idx = self.shard_idx(&key);
        let mut map = self.shards[idx].map.lock();

        match map.get_mut(&key) {
            Some(v) => {
                v.packets += 1;
                v.bytes += pkt_len as u64;
                v.last_seen_ms = now;
                v.tcp_flags |= tcp_flags;
            }
            None => {
                map.insert(
                    key,
                    FlowValue {
                        packets: 1,
                        bytes: pkt_len as u64,
                        first_seen_ms: now,
                        last_seen_ms: now,
                        tcp_flags,
                    },
                );
            }
        }
    }

    pub fn expire_inactive(&self, inactive_for: Duration) -> Vec<FlowRecord> {
        let now = Self::now_ms();
        let cutoff = now.saturating_sub(inactive_for.as_millis());

        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.map.lock();
            let keys_to_remove: Vec<FlowKey> = map
                .iter()
                .filter_map(|(k, v)| {
                    if v.last_seen_ms <= cutoff {
                        Some(*k)
                    } else {
                        None
                    }
                })
                .collect();

            for key in keys_to_remove {
                if let Some(value) = map.remove(&key) {
                    expired.push(to_record(key, value));
                }
            }
        }

        expired
    }

    pub fn export_all(&self) -> Vec<FlowRecord> {
        let mut out = Vec::new();

        for shard in &self.shards {
            let mut map = shard.map.lock();
            for (k, v) in map.drain() {
                out.push(to_record(k, v));
            }
        }

        out
    }
}

fn to_record(key: FlowKey, value: FlowValue) -> FlowRecord {
    FlowRecord {
        src_ip: ipv4_to_string(key.src_ip),
        dst_ip: ipv4_to_string(key.dst_ip),
        src_port: key.src_port,
        dst_port: key.dst_port,
        proto: key.proto,
        packets: value.packets,
        bytes: value.bytes,
        first_seen_ms: value.first_seen_ms,
        last_seen_ms: value.last_seen_ms,
        tcp_flags: value.tcp_flags,
    }
}

fn ipv4_to_string(ip: u32) -> String {
    format!(
        "{}.{}.{}.{}",
        (ip >> 24) & 0xff,
        (ip >> 16) & 0xff,
        (ip >> 8) & 0xff,
        ip & 0xff
    )
}
