```rust
use crate::flow::FlowKey;

pub struct ParsedPacket {
    pub key: FlowKey,
    pub tcp_flags: u8,
    pub payload_len: usize,
}

#[inline]
pub fn parse_packet(frame: &[u8]) -> Option<ParsedPacket> {
    if frame.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &frame[14..];
    if ip.len() < 20 {
        return None;
    }

    let version = ip[0] >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((ip[0] & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let total_len = u16::from_be_bytes([ip[2], ip[3]]) as usize;
    if total_len < ihl || ip.len() < total_len {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..total_len];
    match proto {
        6 => parse_tcp(src_ip, dst_ip, proto, l4, total_len - ihl),
        17 => parse_udp(src_ip, dst_ip, proto, l4, total_len - ihl),
        _ => None,
    }
}

#[inline]
fn parse_tcp(
    src_ip: u32,
    dst_ip: u32,
    proto: u8,
    l4: &[u8],
    ip_payload_len: usize,
) -> Option<ParsedPacket> {
    if l4.len() < 20 {
        return None;
    }

    let src_port = u16::from_be_bytes([l4[0], l4[1]]);
    let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
    let data_offset = ((l4[12] >> 4) as usize) * 4;
    if data_offset < 20 || l4.len() < data_offset {
        return None;
    }

    let tcp_flags = l4[13];
    let payload_len = ip_payload_len.saturating_sub(data_offset);

    Some(ParsedPacket {
        key: FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        tcp_flags,
        payload_len,
    })
}

#[inline]
fn parse_udp(
    src_ip: u32,
    dst_ip: u32,
    proto: u8,
    l4: &[u8],
    ip_payload_len: usize,
) -> Option<ParsedPacket> {
    if l4.len() < 8 {
        return None;
    }

    let src_port = u16::from_be_bytes([l4[0], l4[1]]);
    let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
    let payload_len = ip_payload_len.saturating_sub(8);

    Some(ParsedPacket {
        key: FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        tcp_flags: 0,
        payload_len,
    })
}
