use crate::flow::FlowTable;
use crate::packet::parse_packet;
use pcap::Capture;
use std::error::Error;
use std::sync::Arc;

pub fn run_pcap_file(path: &str, flow_table: Arc<FlowTable>) -> Result<(), Box<dyn Error>> {
    let mut cap = Capture::from_file(path)?;

    while let Ok(packet) = cap.next_packet() {
        if let Some(parsed) = parse_packet(packet.data) {
            flow_table.update_flow(parsed.key, packet.header.len as usize, parsed.tcp_flags);
        }
    }

    let remaining = flow_table.export_all();
    for record in remaining {
        println!("{}", serde_json::to_string(&record)?);
    }

    Ok(())
}
