use ahash::AHashMap;
use crossbeam_channel::{bounded, Receiver, Sender};
use pcap::{Active, Capture, Device};
use pnet_packet::ethernet::{EtherTypes, EthernetPacket};
use pnet_packet::icmp::IcmpPacket;
use pnet_packet::ip::IpNextHeaderProtocols;
use pnet_packet::ipv4::Ipv4Packet;
use pnet_packet::ipv6::Ipv6Packet;
use pnet_packet::tcp::TcpPacket;
use pnet_packet::udp::UdpPacket;
use pnet_packet::Packet;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const REPORT_INTERVAL: Duration = Duration::from_secs(5);
const SNAPLEN: i32 = 256;
const CHANNEL_CAPACITY: usize = 1024;

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src: IpKey,
    dst: IpKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src == other.src
            && self.dst == other.dst
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src.hash(state);
        self.dst.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Copy, Eq, PartialEq, Hash)]
enum IpKey {
    V4([u8; 4]),
    V6([u8; 16]),
}

impl fmt::Display for IpKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IpKey::V4(bytes) => write!(f, "{}", Ipv4Addr::from(*bytes)),
            IpKey::V6(bytes) => write!(f, "{}", Ipv6Addr::from(*bytes)),
        }
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_flags_or: u8,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize, tcp_flags: u8) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
            tcp_flags_or: tcp_flags,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
        self.tcp_flags_or |= tcp_flags;
    }
}

#[derive(Clone)]
struct FlowRecord {
    key: FlowKey,
    stats: FlowStats,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let interface = std::env::args().nth(1).unwrap_or_else(|| {
        Device::lookup()
            .ok()
            .flatten()
            .map(|d| d.name)
            .unwrap_or_else(|| "eth0".to_string())
    });

    let running = Arc::new(AtomicBool::new(true));
    let (tx, rx) = bounded::<Vec<FlowRecord>>(CHANNEL_CAPACITY);

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::Relaxed);
        })?;
    }

    let reporter_running = running.clone();
    let reporter_handle = thread::spawn(move || reporter_loop(rx, reporter_running));

    capture_loop(&interface, tx, running.clone())?;

    drop(running);
    reporter_handle.join().ok();

    Ok(())
}

fn capture_loop(
    interface: &str,
    tx: Sender<Vec<FlowRecord>>,
    running: Arc<AtomicBool>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut cap = Capture::from_device(interface)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(SNAPLEN)
        .timeout(1000)
        .open()?;

    cap.direction(pcap::Direction::In)?;

    let mut flows: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(1 << 20);
    let mut last_report = Instant::now();
    let mut last_expire = Instant::now();

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                process_packet(packet.data, packet.header.len as usize, now, &mut flows);

                if now.duration_since(last_expire) >= Duration::from_secs(1) {
                    expire_flows(&mut flows, now, &tx);
                    last_expire = now;
                }

                if now.duration_since(last_report) >= REPORT_INTERVAL {
                    flush_snapshot(&flows, &tx);
                    last_report = now;
                }
            }
            Err(pcap::Error::TimeoutExpired) => {
                let now = Instant::now();

                if now.duration_since(last_expire) >= Duration::from_secs(1) {
                    expire_flows(&mut flows, now, &tx);
                    last_expire = now;
                }

                if now.duration_since(last_report) >= REPORT_INTERVAL {
                    flush_snapshot(&flows, &tx);
                    last_report = now;
                }
            }
            Err(e) => {
                eprintln!("capture error: {e}");
            }
        }
    }

    let now = Instant::now();
    expire_all_flows(&mut flows, now, &tx);
    Ok(())
}

fn process_packet(
    data: &[u8],
    wire_len: usize,
    now: Instant,
    flows: &mut AHashMap<FlowKey, FlowStats>,
) {
    let eth = match EthernetPacket::new(data) {
        Some(pkt) => pkt,
        None => return,
    };

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                process_ipv4(&ipv4, wire_len, now, flows);
            }
        }
        EtherTypes::Ipv6 => {
            if let Some(ipv6) = Ipv6Packet::new(eth.payload()) {
                process_ipv6(&ipv6, wire_len, now, flows);
            }
        }
        _ => {}
    }
}

fn process_ipv4(
    ipv4: &Ipv4Packet,
    wire_len: usize,
    now: Instant,
    flows: &mut AHashMap<FlowKey, FlowStats>,
) {
    let src = IpKey::V4(ipv4.get_source().octets());
    let dst = IpKey::V4(ipv4.get_destination().octets());
    let proto = ipv4.get_next_level_protocol().0;
    let payload = ipv4.payload();

    match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(payload) {
                let key = FlowKey {
                    src,
                    dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto,
                };
                upsert_flow(flows, key, now, wire_len, tcp.get_flags());
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(payload) {
                let key = FlowKey {
                    src,
                    dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto,
                };
                upsert_flow(flows, key, now, wire_len, 0);
            }
        }
        IpNextHeaderProtocols::Icmp => {
            if let Some(_icmp) = IcmpPacket::new(payload) {
                let key = FlowKey {
                    src,
                    dst,
                    src_port: 0,
                    dst_port: 0,
                    proto,
                };
                upsert_flow(flows, key, now, wire_len, 0);
            }
        }
        _ => {}
    }
}

fn process_ipv6(
    ipv6: &Ipv6Packet,
    wire_len: usize,
    now: Instant,
    flows: &mut AHashMap<FlowKey, FlowStats>,
) {
    let src = IpKey::V6(ipv6.get_source().octets());
    let dst = IpKey::V6(ipv6.get_destination().octets());
    let proto = ipv6.get_next_header().0;
    let payload = ipv6.payload();

    match ipv6.get_next_header() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(payload) {
                let key = FlowKey {
                    src,
                    dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto,
                };
                upsert_flow(flows, key, now, wire_len, tcp.get_flags());
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(payload) {
                let key = FlowKey {
                    src,
                    dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto,
                };
                upsert_flow(flows, key, now, wire_len, 0);
            }
        }
        IpNextHeaderProtocols::Icmpv6 => {
            let key = FlowKey {
                src,
                dst,
                src_port: 0,
                dst_port: 0,
                proto,
            };
            upsert_flow(flows, key, now, wire_len, 0);
        }
        _ => {}
    }
}

fn upsert_flow(
    flows: &mut AHashMap<FlowKey, FlowStats>,
    key: FlowKey,
    now: Instant,
    wire_len: usize,
    tcp_flags: u8,
) {
    match flows.get_mut(&key) {
        Some(stats) => stats.update(now, wire_len, tcp_flags),
        None => {
            flows.insert(key, FlowStats::new(now, wire_len, tcp_flags));
        }
    }
}

fn expire_flows(
    flows: &mut AHashMap<FlowKey, FlowStats>,
    now: Instant,
    tx: &Sender<Vec<FlowRecord>>,
) {
    let mut expired = Vec::with_capacity(1024);

    flows.retain(|key, stats| {
        if now.duration_since(stats.last_seen) >= FLOW_IDLE_TIMEOUT {
            expired.push(FlowRecord {
                key: *key,
                stats: stats.clone(),
            });
            false
        } else {
            true
        }
    });

    if !expired.is_empty() {
        let _ = tx.try_send(expired);
    }
}

fn expire_all_flows(
    flows: &mut AHashMap<FlowKey, FlowStats>,
    _now: Instant,
    tx: &Sender<Vec<FlowRecord>>,
) {
    if flows.is_empty() {
        return;
    }

    let mut all = Vec::with_capacity(flows.len());
    for (key, stats) in flows.drain() {
        all.push(FlowRecord { key, stats });
    }

    let _ = tx.try_send(all);
}

fn flush_snapshot(flows: &AHashMap<FlowKey, FlowStats>, tx: &Sender<Vec<FlowRecord>>) {
    let mut snapshot = Vec::with_capacity(flows.len().min(10_000));
    for (key, stats) in flows.iter() {
        snapshot.push(FlowRecord {
            key: *key,
            stats: stats.clone(),
        });
    }

    let _ = tx.try_send(snapshot);
}

fn reporter_loop(rx: Receiver<Vec<FlowRecord>>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(500)) {
            Ok(batch) => {
                for rec in batch {
                    print_flow(&rec);
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

fn print_flow(rec: &FlowRecord) {
    let duration_ms = rec
        .stats
        .last_seen
        .duration_since(rec.stats.first_seen)
        .as_millis();

    println!(
        "{}:{} -> {}:{} proto={} packets={} bytes={} duration_ms={} tcp_flags=0x{:02x}",
        rec.key.src,
        rec.key.src_port,
        rec.key.dst,
        rec.key.dst_port,
        rec.key.proto,
        rec.stats.packets,
        rec.stats.bytes,
        duration_ms,
        rec.stats.tcp_flags_or
    );
}
