use ahash::AHashMap;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

const INACTIVE_TIMEOUT: Duration = Duration::from_secs(30);
const ACTIVE_TIMEOUT: Duration = Duration::from_secs(300);

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TransportProtocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

impl TransportProtocol {
    #[inline]
    pub fn from_u8(v: u8) -> Self {
        match v {
            6 => Self::Tcp,
            17 => Self::Udp,
            1 => Self::Icmp,
            x => Self::Other(x),
        }
    }

    #[inline]
    pub fn as_u8(self) -> u8 {
        match self {
            Self::Tcp => 6,
            Self::Udp => 17,
            Self::Icmp => 1,
            Self::Other(x) => x,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FlowIp {
    V4([u8; 4]),
    V6([u8; 16]),
}

impl Hash for FlowIp {
    #[inline]
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            FlowIp::V4(v) => {
                4u8.hash(state);
                v.hash(state);
            }
            FlowIp::V6(v) => {
                6u8.hash(state);
                v.hash(state);
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct FlowKey {
    pub src_ip: FlowIp,
    pub dst_ip: FlowIp,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
}

#[derive(Debug, Clone)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub tcp_syn: u32,
    pub tcp_fin: u32,
    pub tcp_rst: u32,
}

impl FlowStats {
    #[inline]
    pub fn new(ts: Instant, bytes: usize, tcp_flags: Option<u8>) -> Self {
        let mut s = Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: ts,
            last_seen: ts,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        };
        s.update_tcp_flags(tcp_flags);
        s
    }

    #[inline]
    pub fn update(&mut self, ts: Instant, bytes: usize, tcp_flags: Option<u8>) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = ts;
        self.update_tcp_flags(tcp_flags);
    }

    #[inline]
    fn update_tcp_flags(&mut self, tcp_flags: Option<u8>) {
        if let Some(flags) = tcp_flags {
            if flags & 0x02 != 0 {
                self.tcp_syn += 1;
            }
            if flags & 0x01 != 0 {
                self.tcp_fin += 1;
            }
            if flags & 0x04 != 0 {
                self.tcp_rst += 1;
            }
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct PacketMeta {
    pub timestamp: Instant,
    pub length_bytes: usize,
    pub src_ip: FlowIp,
    pub dst_ip: FlowIp,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: TransportProtocol,
    pub tcp_flags: Option<u8>,
}

impl PacketMeta {
    #[inline]
    pub fn flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            proto: self.proto,
        }
    }
}

#[derive(Debug, Clone)]
pub struct ExpiredFlow {
    pub key: FlowKey,
    pub stats: FlowStats,
    pub reason: ExpireReason,
}

#[derive(Debug, Clone, Copy)]
pub enum ExpireReason {
    InactiveTimeout,
    ActiveTimeout,
    Manual,
}

pub struct FlowTable {
    flows: AHashMap<FlowKey, FlowStats>,
    inactive_timeout: Duration,
    active_timeout: Duration,
}

impl FlowTable {
    pub fn with_capacity(capacity: usize) -> Self {
        Self {
            flows: AHashMap::with_capacity(capacity),
            inactive_timeout: INACTIVE_TIMEOUT,
            active_timeout: ACTIVE_TIMEOUT,
        }
    }

    pub fn with_timeouts(
        capacity: usize,
        inactive_timeout: Duration,
        active_timeout: Duration,
    ) -> Self {
        Self {
            flows: AHashMap::with_capacity(capacity),
            inactive_timeout,
            active_timeout,
        }
    }

    #[inline]
    pub fn process_packet(&mut self, packet: PacketMeta) {
        let key = packet.flow_key();
        match self.flows.get_mut(&key) {
            Some(stats) => {
                stats.update(packet.timestamp, packet.length_bytes, packet.tcp_flags);
            }
            None => {
                self.flows.insert(
                    key,
                    FlowStats::new(packet.timestamp, packet.length_bytes, packet.tcp_flags),
                );
            }
        }
    }

    pub fn expire_flows(&mut self, now: Instant) -> Vec<ExpiredFlow> {
        let mut expired = Vec::new();

        self.flows.retain(|key, stats| {
            let inactive = now.duration_since(stats.last_seen) >= self.inactive_timeout;
            let active = now.duration_since(stats.first_seen) >= self.active_timeout;

            if inactive || active {
                expired.push(ExpiredFlow {
                    key: *key,
                    stats: stats.clone(),
                    reason: if inactive {
                        ExpireReason::InactiveTimeout
                    } else {
                        ExpireReason::ActiveTimeout
                    },
                });
                false
            } else {
                true
            }
        });

        expired
    }

    pub fn expire_all(&mut self) -> Vec<ExpiredFlow> {
        let mut expired = Vec::with_capacity(self.flows.len());
        for (key, stats) in self.flows.drain() {
            expired.push(ExpiredFlow {
                key,
                stats,
                reason: ExpireReason::Manual,
            });
        }
        expired
    }

    #[inline]
    pub fn len(&self) -> usize {
        self.flows.len()
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.flows.is_empty()
    }
}

fn format_ip(ip: FlowIp) -> IpAddr {
    match ip {
        FlowIp::V4(v) => IpAddr::V4(Ipv4Addr::from(v)),
        FlowIp::V6(v) => IpAddr::V6(Ipv6Addr::from(v)),
    }
}

fn main() {
    let mut table = FlowTable::with_capacity(1 << 20);
    let start = Instant::now();

    let packets = vec![
        PacketMeta {
            timestamp: start,
            length_bytes: 1500,
            src_ip: FlowIp::V4([10, 0, 0, 1]),
            dst_ip: FlowIp::V4([10, 0, 0, 2]),
            src_port: 12345,
            dst_port: 443,
            proto: TransportProtocol::Tcp,
            tcp_flags: Some(0x02),
        },
        PacketMeta {
            timestamp: start + Duration::from_millis(10),
            length_bytes: 900,
            src_ip: FlowIp::V4([10, 0, 0, 1]),
            dst_ip: FlowIp::V4([10, 0, 0, 2]),
            src_port: 12345,
            dst_port: 443,
            proto: TransportProtocol::Tcp,
            tcp_flags: Some(0x10),
        },
        PacketMeta {
            timestamp: start + Duration::from_secs(40),
            length_bytes: 100,
            src_ip: FlowIp::V4([192, 168, 1, 10]),
            dst_ip: FlowIp::V4([8, 8, 8, 8]),
            src_port: 53000,
            dst_port: 53,
            proto: TransportProtocol::Udp,
            tcp_flags: None,
        },
    ];

    for p in packets {
        table.process_packet(p);
    }

    let expired = table.expire_flows(start + Duration::from_secs(45));
    for flow in expired {
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={} syn={} fin={} rst={} reason={:?}",
            format_ip(flow.key.src_ip),
            flow.key.src_port,
            format_ip(flow.key.dst_ip),
            flow.key.dst_port,
            flow.key.proto.as_u8(),
            flow.stats.packets,
            flow.stats.bytes,
            flow.stats.tcp_syn,
            flow.stats.tcp_fin,
            flow.stats.tcp_rst,
            flow.reason
        );
    }

    let remaining = table.expire_all();
    for flow in remaining {
        println!(
            "remaining {}:{} -> {}:{} proto={} packets={} bytes={}",
            format_ip(flow.key.src_ip),
            flow.key.src_port,
            format_ip(flow.key.dst_ip),
            flow.key.dst_port,
            flow.key.proto.as_u8(),
            flow.stats.packets,
            flow.stats.bytes
        );
    }
}
