use ahash::RandomState;
use parking_lot::Mutex;
use std::collections::HashMap;
use std::fmt::{Display, Formatter};
use std::hash::{BuildHasher, Hash, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

#[derive(Clone, Debug)]
pub struct ExportedFlow {
    pub key: FlowKey,
    pub stats: FlowStats,
}

impl Display for ExportedFlow {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "{}:{} -> {}:{} proto={} packets={} bytes={}",
            self.key.src_ip,
            self.key.src_port,
            self.key.dst_ip,
            self.key.dst_port,
            self.key.proto,
            self.stats.packets,
            self.stats.bytes
        )
    }
}

#[derive(Clone, Copy, Debug)]
pub struct ParsedPacket {
    pub key: FlowKey,
    pub bytes: u32,
    pub ts: Instant,
}

pub struct FlowTableConfig {
    pub shards: usize,
    pub idle_timeout: Duration,
    pub active_timeout: Duration,
}

struct Shard {
    map: Mutex<HashMap<FlowKey, FlowStats, RandomState>>,
}

pub struct FlowTable {
    config: FlowTableConfig,
    shards: Vec<Shard>,
    hasher: RandomState,
}

impl FlowTable {
    pub fn new(config: FlowTableConfig) -> Self {
        assert!(config.shards > 0);
        let hasher = RandomState::default();
        let mut shards = Vec::with_capacity(config.shards);
        for _ in 0..config.shards {
            shards.push(Shard {
                map: Mutex::new(HashMap::with_hasher(RandomState::default())),
            });
        }
        Self {
            config,
            shards,
            hasher,
        }
    }

    #[inline]
    fn shard_for(&self, key: &FlowKey) -> usize {
        let mut h = self.hasher.build_hasher();
        key.hash(&mut h);
        (h.finish() as usize) % self.shards.len()
    }

    #[inline]
    pub fn update(&self, packet: ParsedPacket) {
        let idx = self.shard_for(&packet.key);
        let mut guard = self.shards[idx].map.lock();
        match guard.get_mut(&packet.key) {
            Some(stats) => {
                stats.packets += 1;
                stats.bytes += packet.bytes as u64;
                stats.last_seen = packet.ts;
            }
            None => {
                guard.insert(
                    packet.key,
                    FlowStats {
                        packets: 1,
                        bytes: packet.bytes as u64,
                        first_seen: packet.ts,
                        last_seen: packet.ts,
                    },
                );
            }
        }
    }

    pub fn expire_and_collect(&self) -> Vec<ExportedFlow> {
        let now = Instant::now();
        let mut out = Vec::new();

        for shard in &self.shards {
            let mut guard = shard.map.lock();
            guard.retain(|key, stats| {
                let idle = now.duration_since(stats.last_seen) >= self.config.idle_timeout;
                let active = now.duration_since(stats.first_seen) >= self.config.active_timeout;
                let keep = !(idle || active);
                if !keep {
                    out.push(ExportedFlow {
                        key: *key,
                        stats: stats.clone(),
                    });
                }
                keep
            });
        }

        out
    }

    pub fn expire_all(&self) -> Vec<ExportedFlow> {
        let mut out = Vec::new();
        for shard in &self.shards {
            let mut guard = shard.map.lock();
            for (key, stats) in guard.drain() {
                out.push(ExportedFlow { key, stats });
            }
        }
        out
    }
}
