## src/parser.rs

```rust
use crate::flow::{FlowKey, ParsedPacket};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use std::net::Ipv4Addr;
use std::time::Instant;

#[inline]
pub fn parse_packet(packet: &[u8]) -> Option<ParsedPacket> {
    let sliced = SlicedPacket::from_ethernet(packet).ok()?;

    let (src_ip, dst_ip, proto) = match sliced.net? {
        InternetSlice::Ipv4(header, _) => (
            Ipv4Addr::from(header.source()),
            Ipv4Addr::from(header.destination()),
            header.protocol().0,
        ),
        _ => return None,
    };

    let (src_port, dst_port) = match sliced.transport? {
        TransportSlice::Tcp(tcp) => (tcp.source_port(), tcp.destination_port()),
        TransportSlice::Udp(udp) => (udp.source_port(), udp.destination_port()),
        _ => return None,
    };

    Some(ParsedPacket {
        key: FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        bytes: packet.len() as u32,
        ts: Instant::now(),
    })
}
