```rust
use rand::rngs::SmallRng;
use rand::{Rng, SeedableRng};
use std::net::Ipv4Addr;

pub trait PacketSource: Iterator<Item = Vec<u8>> + Send {}

impl<T> PacketSource for T where T: Iterator<Item = Vec<u8>> + Send {}

pub struct SyntheticPacketSource {
    remaining: usize,
    rng: SmallRng,
}

impl SyntheticPacketSource {
    pub fn new(count: usize) -> Self {
        Self {
            remaining: count,
            rng: SmallRng::seed_from_u64(0x12345678),
        }
    }
}

impl Iterator for SyntheticPacketSource {
    type Item = Vec<u8>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.remaining == 0 {
            return None;
        }
        self.remaining -= 1;

        let src_ip = Ipv4Addr::new(10, 0, self.rng.gen(), self.rng.gen());
        let dst_ip = Ipv4Addr::new(192, 168, self.rng.gen(), self.rng.gen());
        let src_port: u16 = self.rng.gen_range(1024..65535);
        let dst_port: u16 = if self.rng.gen_bool(0.5) { 80 } else { 443 };
        let proto = if self.rng.gen_bool(0.7) { 6u8 } else { 17u8 };

        Some(build_ipv4_packet(src_ip, dst_ip, src_port, dst_port, proto))
    }
}

fn build_ipv4_packet(
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
) -> Vec<u8> {
    let payload_len = 32usize;
    let l4_len = if proto == 6 { 20 } else { 8 };
    let ip_total_len = 20 + l4_len + payload_len;
    let frame_len = 14 + ip_total_len;

    let mut pkt = vec![0u8; frame_len];

    pkt[0..6].copy_from_slice(&[0, 1, 2, 3, 4, 5]);
    pkt[6..12].copy_from_slice(&[6, 7, 8, 9, 10, 11]);
    pkt[12..14].copy_from_slice(&0x0800u16.to_be_bytes());

    let ip = 14;
    pkt[ip] = 0x45;
    pkt[ip + 1] = 0;
    pkt[ip + 2..ip + 4].copy_from_slice(&(ip_total_len as u16).to_be_bytes());
    pkt[ip + 4..ip + 6].copy_from_slice(&0u16.to_be_bytes());
    pkt[ip + 6..ip + 8].copy_from_slice(&0u16.to_be_bytes());
    pkt[ip + 8] = 64;
    pkt[ip + 9] = proto;
    pkt[ip + 10..ip + 12].copy_from_slice(&0u16.to_be_bytes());
    pkt[ip + 12..ip + 16].copy_from_slice(&src_ip.octets());
    pkt[ip + 16..ip + 20].copy_from_slice(&dst_ip.octets());

    let l4 = ip + 20;
    pkt[l4..l4 + 2].copy_from_slice(&src_port.to_be_bytes());
    pkt[l4 + 2..l4 + 4].copy_from_slice(&dst_port.to_be_bytes());

    if proto == 6 {
        pkt[l4 + 12] = 5u8 << 4;
        pkt[l4 + 13] = 0x10;
        pkt[l4 + 14..l4 + 16].copy_from_slice(&1024u16.to_be_bytes());
    } else {
        let udp_len = (8 + payload_len) as u16;
        pkt[l4 + 4..l4 + 6].copy_from_slice(&udp_len.to_be_bytes());
    }

    SomeIpv4Checksum::fill(&mut pkt[14..34]);
    pkt
}

struct SomeIpv4Checksum;

impl SomeIpv4Checksum {
    fn fill(hdr: &mut [u8]) {
        hdr[10] = 0;
        hdr[11] = 0;
        let mut sum = 0u32;
        for i in (0..hdr.len()).step_by(2) {
            let word = u16::from_be_bytes([hdr[i], hdr[i + 1]]) as u32;
            sum += word;
        }
        while (sum >> 16) != 0 {
            sum = (sum & 0xffff) + (sum >> 16);
        }
        let csum = !(sum as u16);
        hdr[10..12].copy_from_slice(&csum.to_be_bytes());
    }
}
