mod flow;
mod parser;
mod source;

use crate::flow::{FlowTable, FlowTableConfig};
use crate::source::SyntheticPacketSource;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

fn main() {
    let config = FlowTableConfig {
        shards: 64,
        idle_timeout: Duration::from_secs(30),
        active_timeout: Duration::from_secs(300),
    };

    let table = Arc::new(FlowTable::new(config));
    let running = Arc::new(AtomicBool::new(true));

    let exporter_table = Arc::clone(&table);
    let exporter_running = Arc::clone(&running);
    let exporter = thread::spawn(move || {
        while exporter_running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(5));
            let expired = exporter_table.expire_and_collect();
            if !expired.is_empty() {
                println!("expired_flows={}", expired.len());
            }
        }
    });

    let source = SyntheticPacketSource::new(5_000_000);
    let start = Instant::now();
    let mut packet_count = 0u64;
