        packet_count += 1;
        byte_count += packet.len() as u64;
        if let Some(parsed) = parser::parse_packet(&packet) {
            table.update(parsed);
        }
    }

    running.store(false, Ordering::Relaxed);
    let _ = exporter.join();

    let elapsed = start.elapsed().as_secs_f64();
    println!("processed_packets={}", packet_count);
    println!("processed_bytes={}", byte_count);
