```rust
use ahash::AHasher;
use crossbeam::channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use serde::Serialize;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const WORKER_THREADS: usize = 4;
const PACKET_BATCH_SIZE: usize = 1024;
const FLOW_IDLE_TIMEOUT_SECS: u64 = 30;
const EXPIRY_INTERVAL_SECS: u64 = 5;

#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq)]
enum TransportProto {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq)]
enum IpAddrExt {
    V4([u8; 4]),
    V6([u8; 16]),
}

#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq)]
struct FlowKey {
    src_ip: IpAddrExt,
    dst_ip: IpAddrExt,
    src_port: u16,
    dst_port: u16,
    proto: TransportProto,
}

#[derive(Debug, Clone, Copy)]
struct PacketMeta {
    timestamp_secs: u64,
    len: u32,
    flow_key: FlowKey,
    tcp_flags: u8,
}

#[derive(Debug, Clone, Serialize)]
struct FlowStats {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    proto: String,
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

#[derive(Debug, Clone)]
struct FlowValue {
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowValue {
    fn new(pkt: &PacketMeta) -> Self {
        let mut v = Self {
            packets: 1,
            bytes: pkt.len as u64,
            first_seen: pkt.timestamp_secs,
            last_seen: pkt.timestamp_secs,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        };
        v.update_flags(pkt.tcp_flags);
        v
    }

    fn update(&mut self, pkt: &PacketMeta) {
        self.packets += 1;
        self.bytes += pkt.len as u64;
        self.last_seen = pkt.timestamp_secs;
        self.update_flags(pkt.tcp_flags);
    }

    fn update_flags(&mut self, flags: u8) {
        // TCP flags bit positions:
        // FIN=0x01, SYN=0x02, RST=0x04
        if flags & 0x02 != 0 {
            self.tcp_syn += 1;
        }
        if flags & 0x01 != 0 {
            self.tcp_fin += 1;
        }
        if flags & 0x04 != 0 {
            self.tcp_rst += 1;
        }
    }
}

struct FlowShard {
    map: Mutex<HashMap<FlowKey, FlowValue, ahash::RandomState>>,
}

impl FlowShard {
    fn new() -> Self {
        Self {
            map: Mutex::new(HashMap::with_hasher(ahash::RandomState::new())),
        }
    }
}

struct FlowTable {
    shards: Vec<FlowShard>,
}

impl FlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(FlowShard::new());
        }
        Self { shards }
    }

    fn shard_for(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shards.len()
    }

    fn update_batch(&self, batch: &[PacketMeta]) {
        let mut grouped: Vec<Vec<&PacketMeta>> = vec![Vec::new(); self.shards.len()];

        for pkt in batch {
            let shard_idx = self.shard_for(&pkt.flow_key);
            grouped[shard_idx].push(pkt);
        }

        for (shard_idx, pkts) in grouped.into_iter().enumerate() {
            if pkts.is_empty() {
                continue;
            }

            let mut guard = self.shards[shard_idx].map.lock();
            for pkt in pkts {
                match guard.get_mut(&pkt.flow_key) {
                    Some(flow) => flow.update(pkt),
                    None => {
                        guard.insert(pkt.flow_key, FlowValue::new(pkt));
                    }
                }
            }
        }
    }

    fn expire_idle(&self, now_secs: u64, idle_timeout_secs: u64) -> Vec<(FlowKey, FlowValue)> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut guard = shard.map.lock();
            let mut to_remove = Vec::new();

            for (k, v) in guard.iter() {
                if now_secs.saturating_sub(v.last_seen) >= idle_timeout_secs {
                    to_remove.push(*k);
                }
            }

            for key in to_remove {
                if let Some(val) = guard.remove(&key) {
                    expired.push((key, val));
                }
            }
        }

        expired
    }

    fn snapshot_top_n(&self, n: usize) -> Vec<(FlowKey, FlowValue)> {
        let mut all = Vec::new();
        for shard in &self.shards {
            let guard = shard.map.lock();
            for (k, v) in guard.iter() {
                all.push((*k, v.clone()));
            }
        }

        all.sort_by(|a, b| b.1.bytes.cmp(&a.1.bytes));
        all.truncate(n);
        all
    }
}

fn ip_to_string(ip: IpAddrExt) -> String {
    match ip {
        IpAddrExt::V4(o) => IpAddr::V4(Ipv4Addr::from(o)).to_string(),
        IpAddrExt::V6(o) => IpAddr::V6(Ipv6Addr::from(o)).to_string(),
    }
}

fn proto_to_string(proto: TransportProto) -> String {
    match proto {
        TransportProto::Tcp => "TCP".to_string(),
        TransportProto::Udp => "UDP".to_string(),
        TransportProto::Other(v) => format!("OTHER({})", v),
    }
}

fn to_flow_stats(key: FlowKey, val: FlowValue) -> FlowStats {
    FlowStats {
        src_ip: ip_to_string(key.src_ip),
        dst_ip: ip_to_string(key.dst_ip),
        src_port: key.src_port,
        dst_port: key.dst_port,
        proto: proto_to_string(key.proto),
        packets: val.packets,
        bytes: val.bytes,
        first_seen: val.first_seen,
        last_seen: val.last_seen,
        tcp_syn: val.tcp_syn,
        tcp_fin: val.tcp_fin,
        tcp_rst: val.tcp_rst,
    }
}

fn unix_now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn worker_loop(rx: Receiver<PacketMeta>, table: Arc<FlowTable>) {
    let mut batch = Vec::with_capacity(PACKET_BATCH_SIZE);

    while let Ok(pkt) = rx.recv() {
        batch.push(pkt);

        while batch.len() < PACKET_BATCH_SIZE {
            match rx.try_recv() {
                Ok(pkt) => batch.push(pkt),
                Err(_) => break,
            }
        }

        table.update_batch(&batch);
        batch.clear();
    }
}

// Simulated packet source for initial implementation.
// Replace with real packet capture backend.
fn packet_generator(tx_workers: Vec<Sender<PacketMeta>>) {
    let mut counter = 0u64;

    loop {
        let now = unix_now_secs();
        let src = [10, 0, ((counter / 256) % 256) as u8, (counter % 256) as u8];
        let dst = [192, 168, 1, ((counter * 7) % 256) as u8];

        let proto = if counter % 2 == 0 {
            TransportProto::Tcp
        } else {
            TransportProto::Udp
        };

        let pkt = PacketMeta {
            timestamp_secs: now,
            len: 64 + (counter % 1400) as u32,
            flow_key: FlowKey {
                src_ip: IpAddrExt::V4(src),
                dst_ip: IpAddrExt::V4(dst),
                src_port: 10000 + (counter % 1000) as u16,
                dst_port: if matches!(proto, TransportProto::Tcp) { 443 } else { 53 },
                proto,
            },
            tcp_flags: if matches!(proto, TransportProto::Tcp) && counter % 10 == 0 {
                0x02
            } else {
                0
            },
        };

        let worker_idx = {
            let mut hasher = AHasher::default();
            pkt.flow_key.hash(&mut hasher);
            (hasher.finish() as usize) % tx_workers.len()
        };

        if tx_workers[worker_idx].send(pkt).is_err() {
            break;
        }

        counter = counter.wrapping_add(1);
    }
}

fn expiry_loop(table: Arc<FlowTable>) {
    loop {
        thread::sleep(Duration::from_secs(EXPIRY_INTERVAL_SECS));
        let now = unix_now_secs();
        let expired = table.expire_idle(now, FLOW_IDLE_TIMEOUT_SECS);

        for (key, val) in expired {
            let stats = to_flow_stats(key, val);
            println!("{}", serde_json::to_string(&stats).unwrap());
        }
    }
}

fn reporter_loop(table: Arc<FlowTable>) {
    loop {
        thread::sleep(Duration::from_secs(10));
        let top = table.snapshot_top_n(10);

        eprintln!("=== top flows ===");
        for (key, val) in top {
            let stats = to_flow_stats(key, val);
            eprintln!(
                "{}:{} -> {}:{} {} pkts={} bytes={}",
                stats.src_ip,
                stats.src_port,
                stats.dst_ip,
                stats.dst_port,
                stats.proto,
                stats.packets,
                stats.bytes
            );
        }
    }
}

fn main() {
    let table = Arc::new(FlowTable::new(NUM_SHARDS));
    let mut tx_workers = Vec::new();
    let mut worker_handles = Vec::new();

    for _ in 0..WORKER_THREADS {
        let (tx, rx) = bounded::<PacketMeta>(1 << 16);
        tx_workers.push(tx);
        let table_clone = Arc::clone(&table);
        worker_handles.push(thread::spawn(move || worker_loop(rx, table_clone)));
    }

    {
        let txs = tx_workers.clone();
        thread::spawn(move || packet_generator(txs));
    }

    {
        let table_clone = Arc::clone(&table);
        thread::spawn(move || expiry_loop(table_clone));
    }

    {
        let table_clone = Arc::clone(&table);
        thread::spawn(move || reporter_loop(table_clone));
    }

    for handle in worker_handles {
        let _ = handle.join();
    }
}
