# `src/main.rs`

```rust
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::icmp::IcmpPacket;
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;

use std::collections::HashMap;
use std::env;
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const NUM_SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT_SECS: u64 = 30;
const REPORT_INTERVAL_SECS: u64 = 5;

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self.src_ip {
            IpAddr::V4(ip) => ip.octets().hash(state),
            IpAddr::V6(ip) => ip.octets().hash(state),
        }
        match self.dst_ip {
            IpAddr::V4(ip) => ip.octets().hash(state),
            IpAddr::V6(ip) => ip.octets().hash(state),
        }
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    tcp_syn: u32,
    tcp_fin: u32,
    tcp_rst: u32,
}

impl FlowStats {
    fn new(ts: u64, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: ts,
            last_seen: ts,
            tcp_syn: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    fn update(&mut self, ts: u64, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = ts;
    }
}

type FlowMap = HashMap<FlowKey, FlowStats>;

struct ShardedFlowTable {
    shards: Vec<Mutex<FlowMap>>,
}

impl ShardedFlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(Mutex::new(HashMap::with_capacity(16_384)));
        }
        Self { shards }
    }

    fn shard_idx(&self, key: &FlowKey) -> usize {
        use std::collections::hash_map::DefaultHasher;
        let mut h = DefaultHasher::new();
        key.hash(&mut h);
        (h.finish() as usize) % self.shards.len()
    }

    fn update_flow(&self, key: FlowKey, pkt_len: usize, ts: u64, tcp_flags: Option<u8>) {
        let idx = self.shard_idx(&key);
        let mut shard = self.shards[idx].lock().unwrap();

        let entry = shard.entry(key).or_insert_with(|| FlowStats::new(ts, pkt_len));
        if entry.packets > 1 || entry.bytes != pkt_len as u64 {
            entry.update(ts, pkt_len);
        }

        if let Some(flags) = tcp_flags {
            const SYN: u8 = 0x02;
            const FIN: u8 = 0x01;
            const RST: u8 = 0x04;
            if flags & SYN != 0 {
                entry.tcp_syn += 1;
            }
            if flags & FIN != 0 {
                entry.tcp_fin += 1;
            }
            if flags & RST != 0 {
                entry.tcp_rst += 1;
            }
        }
    }

    fn expire_and_report(&self, now: u64, idle_timeout: u64) {
        for shard_mutex in &self.shards {
            let mut shard = shard_mutex.lock().unwrap();
            let mut expired = Vec::new();

            for (k, v) in shard.iter() {
                if now.saturating_sub(v.last_seen) >= idle_timeout {
                    expired.push((*k, v.clone()));
                }
            }

            for (k, v) in expired {
                shard.remove(&k);
                println!(
                    "FLOW src={:?}:{} dst={:?}:{} proto={} packets={} bytes={} first={} last={} syn={} fin={} rst={}",
                    k.src_ip,
                    k.src_port,
                    k.dst_ip,
                    k.dst_port,
                    k.proto,
                    v.packets,
                    v.bytes,
                    v.first_seen,
                    v.last_seen,
                    v.tcp_syn,
                    v.tcp_fin,
                    v.tcp_rst
                );
            }
        }
    }

    fn report_active_summary(&self) {
        let mut total_flows = 0usize;
        let mut total_packets = 0u64;
        let mut total_bytes = 0u64;

        for shard_mutex in &self.shards {
            let shard = shard_mutex.lock().unwrap();
            total_flows += shard.len();
            for stats in shard.values() {
                total_packets += stats.packets;
                total_bytes += stats.bytes;
            }
        }

        println!(
            "SUMMARY active_flows={} packets={} bytes={}",
            total_flows, total_packets, total_bytes
        );
    }
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn find_interface(name: &str) -> Option<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
}

fn process_ipv4(table: &ShardedFlowTable, ipv4: &Ipv4Packet, frame_len: usize, ts: u64) {
    let src = IpAddr::V4(ipv4.get_source());
    let dst = IpAddr::V4(ipv4.get_destination());

    match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: 6,
                };
                table.update_flow(key, frame_len, ts, Some(tcp.get_flags()));
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: 17,
                };
                table.update_flow(key, frame_len, ts, None);
            }
        }
        IpNextHeaderProtocols::Icmp => {
            if IcmpPacket::new(ipv4.payload()).is_some() {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: 0,
                    dst_port: 0,
                    proto: 1,
                };
                table.update_flow(key, frame_len, ts, None);
            }
        }
        _ => {}
    }
}

fn process_ipv6(table: &ShardedFlowTable, ipv6: &Ipv6Packet, frame_len: usize, ts: u64) {
    let src = IpAddr::V6(ipv6.get_source());
    let dst = IpAddr::V6(ipv6.get_destination());

    match ipv6.get_next_header() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(ipv6.payload()) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: tcp.get_source(),
                    dst_port: tcp.get_destination(),
                    proto: 6,
                };
                table.update_flow(key, frame_len, ts, Some(tcp.get_flags()));
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(ipv6.payload()) {
                let key = FlowKey {
                    src_ip: src,
                    dst_ip: dst,
                    src_port: udp.get_source(),
                    dst_port: udp.get_destination(),
                    proto: 17,
                };
                table.update_flow(key, frame_len, ts, None);
            }
        }
        IpNextHeaderProtocols::Icmpv6 => {
            let key = FlowKey {
                src_ip: src,
                dst_ip: dst,
                src_port: 0,
                dst_port: 0,
                proto: 58,
            };
            table.update_flow(key, frame_len, ts, None);
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <interface>", args[0]);
        std::process::exit(1);
    }

    let iface_name = &args[1];
    let interface = find_interface(iface_name).expect("interface not found");

    let config = Config {
        read_timeout: Some(Duration::from_millis(10)),
        promiscuous: true,
        ..Default::default()
    };

    let table = Arc::new(ShardedFlowTable::new(NUM_SHARDS));
    let running = Arc::new(AtomicBool::new(true));

    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::SeqCst);
        })
        .expect("failed to set ctrl-c handler");
    }

    let reporter_table = table.clone();
    let reporter_running = running.clone();
    let reporter = thread::spawn(move || {
        while reporter_running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(REPORT_INTERVAL_SECS));
            let now = now_secs();
            reporter_table.report_active_summary();
            reporter_table.expire_and_report(now, FLOW_IDLE_TIMEOUT_SECS);
        }

        let now = now_secs();
        reporter_table.expire_and_report(now, 0);
    });

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(_, rx)) => ((), rx),
        Ok(_) => panic!("unsupported channel type"),
        Err(e) => panic!("failed to create datalink channel: {}", e),
    };

    while running.load(Ordering::Relaxed) {
        match rx.next() {
            Ok(frame) => {
                let ts = now_secs();
                if let Some(eth) = EthernetPacket::new(frame) {
                    match eth.get_ethertype() {
                        EtherTypes::Ipv4 => {
                            if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                                process_ipv4(&table, &ipv4, frame.len(), ts);
                            }
                        }
                        EtherTypes::Ipv6 => {
                            if let Some(ipv6) = Ipv6Packet::new(eth.payload()) {
                                process_ipv6(&table, &ipv6, frame.len(), ts);
                            }
                        }
                        _ => {}
                    }
                }
            }
            Err(_) => {}
        }
    }

    reporter.join().unwrap();
}
