#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <inttypes.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <pthread.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/poll.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef likely
#define likely(x)   __builtin_expect(!!(x), 1)
#endif
#ifndef unlikely
#define unlikely(x) __builtin_expect(!!(x), 0)
#endif

#define MAX_THREADS 16
#define FLOW_TABLE_SIZE (1u << 20)   // 1M buckets per thread
#define FLOW_TABLE_MASK (FLOW_TABLE_SIZE - 1)

#define BLOCK_SIZE (1 << 22)         // 4 MiB
#define BLOCK_NR   64
#define FRAME_SIZE 2048
#define RETIRE_TOV 60

#define REPORT_INTERVAL_SEC 2

static volatile sig_atomic_t g_stop = 0;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  pad[3];
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t last_seen_ns;
    struct flow_entry *next;
} flow_entry_t;

typedef struct {
    flow_entry_t **buckets;
    flow_entry_t *pool;
    uint32_t pool_size;
    uint32_t pool_used;
} flow_table_t;

typedef struct {
    int thread_id;
    int sockfd;
    void *ring;
    size_t ring_size;
    struct tpacket_req3 req;
    flow_table_t table;
    uint64_t packets_processed;
    uint64_t bytes_processed;
} worker_ctx_t;

static worker_ctx_t g_workers[MAX_THREADS];
static int g_num_threads = 1;

static uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + ts.tv_nsec;
}

static void on_signal(int signo) {
    (void)signo;
    g_stop = 1;
}

static inline uint64_t hash_flow(const flow_key_t *k) {
    uint64_t x = 0x9e3779b97f4a7c15ull;
    x ^= k->src_ip + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);
    x ^= k->dst_ip + 0x9e3779b97f4a7c15ull + (x << 6) + (x >> 2);
    x ^= ((uint64_t)k->src_port << 16) | k->dst_port;
    x ^= k->proto;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdull;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ull;
    x ^= x >> 33;
    return x;
}

static inline bool flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static int flow_table_init(flow_table_t *ft, uint32_t max_entries) {
    ft->buckets = calloc(FLOW_TABLE_SIZE, sizeof(flow_entry_t *));
    if (!ft->buckets) return -1;

    ft->pool = calloc(max_entries, sizeof(flow_entry_t));
    if (!ft->pool) {
        free(ft->buckets);
        return -1;
    }

    ft->pool_size = max_entries;
    ft->pool_used = 0;
    return 0;
}

static inline void flow_table_update(flow_table_t *ft, const flow_key_t *key, uint32_t pkt_len, uint64_t ts_ns) {
    uint64_t h = hash_flow(key);
    uint32_t idx = h & FLOW_TABLE_MASK;

    flow_entry_t *e = ft->buckets[idx];
    while (e) {
        if (likely(flow_key_equal(&e->key, key))) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen_ns = ts_ns;
            return;
        }
        e = e->next;
    }

    if (unlikely(ft->pool_used >= ft->pool_size)) {
        return;
    }

    e = &ft->pool[ft->pool_used++];
    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->last_seen_ns = ts_ns;
    e->next = ft->buckets[idx];
    ft->buckets[idx] = e;
}

static int bind_socket_to_interface(int sockfd, const char *ifname) {
    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex(ifname);
    if (sll.sll_ifindex == 0) {
        perror("if_nametoindex");
        return -1;
    }

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return -1;
    }
    return 0;
}

static int setup_ring(worker_ctx_t *ctx, const char *ifname) {
    int ver = TPACKET_V3;
    if (setsockopt(ctx->sockfd, SOL_PACKET, PACKET_VERSION, &ver, sizeof(ver)) < 0) {
        perror("setsockopt PACKET_VERSION");
        return -1;
    }

    int fanout_arg = (0x1234 | (PACKET_FANOUT_HASH << 16));
    if (setsockopt(ctx->sockfd, SOL_PACKET, PACKET_FANOUT, &fanout_arg, sizeof(fanout_arg)) < 0) {
        perror("setsockopt PACKET_FANOUT");
        return -1;
    }

    memset(&ctx->req, 0, sizeof(ctx->req));
    ctx->req.tp_block_size = BLOCK_SIZE;
    ctx->req.tp_frame_size = FRAME_SIZE;
    ctx->req.tp_block_nr = BLOCK_NR;
    ctx->req.tp_frame_nr = (BLOCK_SIZE * BLOCK_NR) / FRAME_SIZE;
    ctx->req.tp_retire_blk_tov = RETIRE_TOV;

    if (setsockopt(ctx->sockfd, SOL_PACKET, PACKET_RX_RING, &ctx->req, sizeof(ctx->req)) < 0) {
        perror("setsockopt PACKET_RX_RING");
        return -1;
    }

    ctx->ring_size = ctx->req.tp_block_size * ctx->req.tp_block_nr;
    ctx->ring = mmap(NULL, ctx->ring_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, ctx->sockfd, 0);
    if (ctx->ring == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    if (bind_socket_to_interface(ctx->sockfd, ifname) < 0) {
        return -1;
    }

    return 0;
}

static inline void process_packet(worker_ctx_t *ctx, const uint8_t *pkt, uint32_t caplen, uint64_t ts_ns) {
    if (unlikely(caplen < sizeof(struct ethhdr))) return;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (unlikely(ntohs(eth->h_proto) != ETH_P_IP)) return;

    const uint8_t *l3 = pkt + sizeof(struct ethhdr);
    uint32_t l3_len = caplen - sizeof(struct ethhdr);
    if (unlikely(l3_len < sizeof(struct iphdr))) return;

    const struct iphdr *ip = (const struct iphdr *)l3;
    if (unlikely(ip->version != 4)) return;
    uint32_t ihl = ip->ihl * 4;
    if (unlikely(ihl < sizeof(struct iphdr) || l3_len < ihl)) return;

    flow_key_t key;
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto = ip->protocol;
    key.src_port = 0;
    key.dst_port = 0;
    key.pad[0] = key.pad[1] = key.pad[2] = 0;

    const uint8_t *l4 = l3 + ihl;
    uint32_t l4_len = l3_len - ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (unlikely(l4_len < sizeof(struct tcphdr))) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (unlikely(l4_len < sizeof(struct udphdr))) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        return;
    }

    flow_table_update(&ctx->table, &key, caplen, ts_ns);
    ctx->packets_processed++;
    ctx->bytes_processed += caplen;
}

static void *worker_main(void *arg) {
    worker_ctx_t *ctx = (worker_ctx_t *)arg;
    struct pollfd pfd = {
        .fd = ctx->sockfd,
        .events = POLLIN
    };

    uint32_t block_idx = 0;

    while (!g_stop) {
        struct tpacket_block_desc *block =
            (struct tpacket_block_desc *)((uint8_t *)ctx->ring + (block_idx * ctx->req.tp_block_size));

        if (!(block->hdr.bh1.block_status & TP_STATUS_USER)) {
            int ret = poll(&pfd, 1, 100);
            if (ret < 0 && errno != EINTR) {
                perror("poll");
                break;
            }
            continue;
        }

        uint32_t num_pkts = block->hdr.bh1.num_pkts;
        uint32_t offset = block->hdr.bh1.offset_to_first_pkt;

        for (uint32_t i = 0; i < num_pkts; i++) {
            struct tpacket3_hdr *ppd = (struct tpacket3_hdr *)((uint8_t *)block + offset);
            const uint8_t *pkt = (const uint8_t *)ppd + ppd->tp_mac;
            uint32_t caplen = ppd->tp_snaplen;
            uint64_t ts_ns = (uint64_t)ppd->tp_sec * 1000000000ull + ppd->tp_nsec;

            process_packet(ctx, pkt, caplen, ts_ns);

            offset += ppd->tp_next_offset;
        }

        __atomic_store_n(&block->hdr.bh1.block_status, TP_STATUS_KERNEL, __ATOMIC_RELEASE);
        block_idx = (block_idx + 1) % ctx->req.tp_block_nr;
    }

    return NULL;
}

static void print_ip(uint32_t ip_be, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip_be;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void report_worker(worker_ctx_t *ctx) {
    printf("=== worker %d ===\n", ctx->thread_id);
    printf("packets=%" PRIu64 " bytes=%" PRIu64 " flows=%u\n",
           ctx->packets_processed,
           ctx->bytes_processed,
           ctx->table.pool_used);

    uint32_t shown = 0;
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE && shown < 20; i++) {
        flow_entry_t *e = ctx->table.buckets[i];
        while (e && shown < 20) {
            char src[INET_ADDRSTRLEN];
            char dst[INET_ADDRSTRLEN];
            print_ip(e->key.src_ip, src, sizeof(src));
            print_ip(e->key.dst_ip, dst, sizeof(dst));

            printf("%s:%u -> %s:%u proto=%u pkts=%" PRIu64 " bytes=%" PRIu64 "\n",
                   src, ntohs(e->key.src_port),
                   dst, ntohs(e->key.dst_port),
                   e->key.proto,
                   e->packets, e->bytes);
            shown++;
            e = e->next;
        }
    }
}

static void *reporter_main(void *arg) {
    (void)arg;
    while (!g_stop) {
        sleep(REPORT_INTERVAL_SEC);
        printf("\n===== report =====\n");
        for (int i = 0; i < g_num_threads; i++) {
            report_worker(&g_workers[i]);
        }
        fflush(stdout);
    }
    return NULL;
}

static int pin_thread_to_cpu(int cpu) {
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(cpu, &cpuset);
    return pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
}

static int create_worker(worker_ctx_t *ctx, int thread_id, const char *ifname, int cpu) {
    memset(ctx, 0, sizeof(*ctx));
    ctx->thread_id = thread_id;

    ctx->sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (ctx->sockfd < 0) {
        perror("socket");
        return -1;
    }

    int one = 1;
    if (setsockopt(ctx->sockfd, SOL_PACKET, PACKET_QDISC_BYPASS, &one, sizeof(one)) < 0) {
        perror("setsockopt PACKET_QDISC_BYPASS");
    }

    if (flow_table_init(&ctx->table, FLOW_TABLE_SIZE / 2) < 0) {
        fprintf(stderr, "flow_table_init failed\n");
        close(ctx->sockfd);
        return -1;
    }

    if (setup_ring(ctx, ifname) < 0) {
        close(ctx->sockfd);
        return -1;
    }

    (void)cpu;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s <ifname> <threads>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    g_num_threads = atoi(argv[2]);
    if (g_num_threads <= 0 || g_num_threads > MAX_THREADS) {
        fprintf(stderr, "invalid thread count\n");
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    pthread_t workers[MAX_THREADS];
    pthread_t reporter;

    for (int i = 0; i < g_num_threads; i++) {
        if (create_worker(&g_workers[i], i, ifname, i) < 0) {
            fprintf(stderr, "failed to create worker %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < g_num_threads; i++) {
        if (pthread_create(&workers[i], NULL, worker_main, &g_workers[i]) != 0) {
            perror("pthread_create worker");
            return 1;
        }
    }

    if (pthread_create(&reporter, NULL, reporter_main, NULL) != 0) {
        perror("pthread_create reporter");
        return 1;
    }

    for (int i = 0; i < g_num_threads; i++) {
        pthread_join(workers[i], NULL);
    }

    pthread_join(reporter, NULL);

    for (int i = 0; i < g_num_threads; i++) {
        if (g_workers[i].ring && g_workers[i].ring != MAP_FAILED) {
            munmap(g_workers[i].ring, g_workers[i].ring_size);
        }
        if (g_workers[i].sockfd >= 0) {
            close(g_workers[i].sockfd);
        }
        free(g_workers[i].table.pool);
        free(g_workers[i].table.buckets);
    }

    return 0;
}
