#include <atomic>
#include <chrono>
#include <cinttypes>
#include <csignal>
#include <cstring>
#include <iostream>
#include <string>
#include <vector>

static volatile std::sig_atomic_t g_running = 1;

void signal_handler(int) {
    g_running = 0;
}

static inline uint64_t now_ns() {
    timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    return uint64_t(ts.tv_sec) * 1000000000ull + uint64_t(ts.tv_nsec);
}

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
    uint8_t pad[3];

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowValue {
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    uint8_t tcp_flags_or;
    uint8_t pad[7];
};

struct FlowEntry {
    FlowKey key;
    FlowValue value;
    bool occupied;
};

static inline uint64_t hash_flow_key(const FlowKey& k) {
    // Simple 64-bit mix; replace with xxhash/cityhash for production.
    uint64_t x = 0xcbf29ce484222325ULL;
    auto mix = [&](uint64_t v) {
        x ^= v;
        x *= 0x100000001b3ULL;
    };
    mix(k.src_ip);
    mix(k.dst_ip);
    mix(k.src_port);
    mix(k.dst_port);
    mix(k.proto);
    return x;
}

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2),
          mask_(capacity_pow2 - 1),
          entries_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of 2");
        }
        for (auto& e : entries_) {
            e.occupied = false;
        }
    }

    FlowValue* upsert(const FlowKey& key, uint64_t ts_ns) {
        uint64_t h = hash_flow_key(key);
        size_t idx = h & mask_;

        for (size_t probe = 0; probe < max_probe_; ++probe) {
            FlowEntry& e = entries_[(idx + probe) & mask_];
            if (!e.occupied) {
                e.occupied = true;
                e.key = key;
                e.value.packets = 0;
                e.value.bytes = 0;
                e.value.first_seen_ns = ts_ns;
                e.value.last_seen_ns = ts_ns;
                e.value.tcp_flags_or = 0;
                return &e.value;
            }
            if (e.key == key) {
                return &e.value;
            }
        }
        return nullptr; // table/probe overflow
    }

    template <typename Fn>
    void expire_idle(uint64_t now, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& e : entries_) {
            if (!e.occupied) continue;
            if (now - e.value.last_seen_ns > idle_timeout_ns) {
                fn(e.key, e.value);
                e.occupied = false;
            }
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) const {
        for (const auto& e : entries_) {
            if (e.occupied) {
                fn(e.key, e.value);
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
    static constexpr size_t max_probe_ = 16;
};

struct PacketStats {
    uint64_t total_packets = 0;
    uint64_t total_bytes = 0;
    uint64_t ipv4_packets = 0;
    uint64_t tcp_packets = 0;
    uint64_t udp_packets = 0;
    uint64_t icmp_packets = 0;
    uint64_t parse_errors = 0;
    uint64_t dropped_flows = 0;
};

class PacketParser {
public:
    static bool parse_ipv4_flow(const uint8_t* data, size_t len, FlowKey& key, uint8_t& tcp_flags) {
        tcp_flags = 0;

        if (len < sizeof(ethhdr)) return false;
        const ethhdr* eth = reinterpret_cast<const ethhdr*>(data);
        if (ntohs(eth->h_proto) != ETH_P_IP) return false;

        data += sizeof(ethhdr);
        len -= sizeof(ethhdr);

        if (len < sizeof(iphdr)) return false;
        const iphdr* ip = reinterpret_cast<const iphdr*>(data);
        if (ip->version != 4) return false;

        size_t ip_header_len = ip->ihl * 4;
        if (len < ip_header_len) return false;

        key.src_ip = ip->saddr;
        key.dst_ip = ip->daddr;
        key.proto = ip->protocol;
        key.src_port = 0;
        key.dst_port = 0;

        const uint8_t* l4 = data + ip_header_len;
        size_t l4_len = len - ip_header_len;

        switch (ip->protocol) {
            case IPPROTO_TCP: {
                if (l4_len < sizeof(tcphdr)) return false;
                const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4);
                key.src_port = tcp->source;
                key.dst_port = tcp->dest;
                tcp_flags = *((const uint8_t*)tcp + 13);
                return true;
            }
            case IPPROTO_UDP: {
                if (l4_len < sizeof(udphdr)) return false;
                const udphdr* udp = reinterpret_cast<const udphdr*>(l4);
                key.src_port = udp->source;
                key.dst_port = udp->dest;
                return true;
            }
            case IPPROTO_ICMP: {
                return true;
            }
            default:
                return true;
        }
    }
};

class Reporter {
public:
    static void print_flow(const FlowKey& k, const FlowValue& v) {
        char src[INET_ADDRSTRLEN];
        char dst[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &k.src_ip, src, sizeof(src));
        inet_ntop(AF_INET, &k.dst_ip, dst, sizeof(dst));

        std::cout
            << src << ":" << ntohs(k.src_port)
            << " -> "
            << dst << ":" << ntohs(k.dst_port)
            << " proto=" << unsigned(k.proto)
            << " packets=" << v.packets
            << " bytes=" << v.bytes
            << " duration_ms=" << ((v.last_seen_ns - v.first_seen_ns) / 1000000.0)
            << "\n";
    }

    static void print_stats(const PacketStats& s) {
        std::cout
            << "pkts=" << s.total_packets
            << " bytes=" << s.total_bytes
            << " ipv4=" << s.ipv4_packets
            << " tcp=" << s.tcp_packets
            << " udp=" << s.udp_packets
            << " icmp=" << s.icmp_packets
            << " parse_errors=" << s.parse_errors
            << " dropped_flows=" << s.dropped_flows
            << "\n";
    }
};

class RawSocketCapture {
public:
    explicit RawSocketCapture(const std::string& ifname) : fd_(-1) {
        fd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (fd_ < 0) {
            throw std::runtime_error("socket(AF_PACKET) failed");
        }

        ifreq ifr{};
        std::snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname.c_str());
        if (ioctl(fd_, SIOCGIFINDEX, &ifr) < 0) {
            close(fd_);
            throw std::runtime_error("SIOCGIFINDEX failed");
        }

        sockaddr_ll sll{};
        sll.sll_family = AF_PACKET;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifr.ifr_ifindex;

        if (bind(fd_, reinterpret_cast<sockaddr*>(&sll), sizeof(sll)) < 0) {
            close(fd_);
            throw std::runtime_error("bind(AF_PACKET) failed");
        }
    }

    ~RawSocketCapture() {
        if (fd_ >= 0) close(fd_);
    }

    ssize_t recv_packet(uint8_t* buf, size_t len) {
        return recvfrom(fd_, buf, len, 0, nullptr, nullptr);
    }

private:
    int fd_;
};

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    std::signal(SIGINT, signal_handler);
    std::signal(SIGTERM, signal_handler);

    const std::string ifname = argv[1];
    const size_t flow_capacity = 1 << 20; // ~1M slots
    const uint64_t idle_timeout_ns = 30ull * 1000000000ull;
    const uint64_t stats_interval_ns = 1ull * 1000000000ull;
    const uint64_t expire_interval_ns = 5ull * 1000000000ull;

    FlowTable flow_table(flow_capacity);
    PacketStats stats;
    RawSocketCapture cap(ifname);

    std::vector<uint8_t> buf(65536);

    uint64_t last_stats = now_ns();
    uint64_t last_expire = last_stats;

    while (g_running) {
        ssize_t n = cap.recv_packet(buf.data(), buf.size());
        if (n < 0) {
            if (errno == EINTR) continue;
            std::perror("recvfrom");
            break;
        }

        uint64_t ts = now_ns();
        stats.total_packets++;
        stats.total_bytes += static_cast<uint64_t>(n);

        FlowKey key{};
        uint8_t tcp_flags = 0;
        if (!PacketParser::parse_ipv4_flow(buf.data(), static_cast<size_t>(n), key, tcp_flags)) {
            stats.parse_errors++;
            continue;
        }

        stats.ipv4_packets++;
        if (key.proto == IPPROTO_TCP) stats.tcp_packets++;
        else if (key.proto == IPPROTO_UDP) stats.udp_packets++;
        else if (key.proto == IPPROTO_ICMP) stats.icmp_packets++;

        FlowValue* fv = flow_table.upsert(key, ts);
        if (!fv) {
            stats.dropped_flows++;
            continue;
        }

        fv->packets++;
        fv->bytes += static_cast<uint64_t>(n);
        fv->last_seen_ns = ts;
        fv->tcp_flags_or |= tcp_flags;

        if (ts - last_expire >= expire_interval_ns) {
            flow_table.expire_idle(ts, idle_timeout_ns, [](const FlowKey& k, const FlowValue& v) {
                Reporter::print_flow(k, v);
            });
            last_expire = ts;
        }

        if (ts - last_stats >= stats_interval_ns) {
            Reporter::print_stats(stats);
            last_stats = ts;
        }
    }

    uint64_t end_ts = now_ns();
    flow_table.for_each([](const FlowKey& k, const FlowValue& v) {
        Reporter::print_flow(k, v);
    });
    Reporter::print_stats(stats);

    (void)end_ts;
    return 0;
}
