```rust
use ahash::AHashMap;
use clap::Parser;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Active, Capture, Device};
use std::fmt;
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Parser, Debug)]
#[command(author, version, about = "High-performance network flow analyzer")]
struct Args {
    /// Network interface to capture from
    #[arg(short, long)]
    interface: Option<String>,

    /// BPF filter, e.g. "ip and (tcp or udp)"
    #[arg(short, long, default_value = "ip and (tcp or udp)")]
    filter: String,

    /// Flow idle timeout in seconds
    #[arg(long, default_value_t = 30)]
    idle_timeout: u64,

    /// Maximum number of active flows before forced expiration sweep
    #[arg(long, default_value_t = 1_000_000)]
    max_flows: usize,

    /// Snapshot length
    #[arg(long, default_value_t = 128)]
    snaplen: i32,

    /// Promiscuous mode
    #[arg(long, default_value_t = true)]
    promiscuous: bool,
}

#[derive(Clone, Copy, Hash, Eq, PartialEq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let src = Ipv4Addr::from(self.src_ip);
        let dst = Ipv4Addr::from(self.dst_ip);
        write!(
            f,
            "{}:{} -> {}:{} proto={}",
            src, self.src_port, dst, self.dst_port, self.proto
        )
    }
}

#[derive(Clone, Copy)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_sec: u64,
    last_seen_sec: u64,
}

impl FlowStats {
    fn new(ts_sec: u64, bytes: u64) -> Self {
        Self {
            packets: 1,
            bytes,
            first_seen_sec: ts_sec,
            last_seen_sec: ts_sec,
        }
    }

    fn update(&mut self, ts_sec: u64, bytes: u64) {
        self.packets += 1;
        self.bytes += bytes;
        self.last_seen_sec = ts_sec;
    }
}

fn packet_ts_sec(header: &pcap::PacketHeader) -> u64 {
    if header.ts.tv_sec >= 0 {
        header.ts.tv_sec as u64
    } else {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or(Duration::from_secs(0))
            .as_secs()
    }
}

fn extract_flow(packet_data: &[u8]) -> Option<FlowKey> {
    let sliced = SlicedPacket::from_ethernet(packet_data).ok()?;

    let (src_ip, dst_ip, proto) = match sliced.net? {
        InternetSlice::Ipv4(ipv4, _) => {
            let src = u32::from_be_bytes(ipv4.header().source());
            let dst = u32::from_be_bytes(ipv4.header().destination());
            let proto = ipv4.header().protocol().0;
            (src, dst, proto)
        }
        _ => return None,
    };

    match sliced.transport? {
        TransportSlice::Tcp(tcp) => Some(FlowKey {
            src_ip,
            dst_ip,
            src_port: tcp.source_port(),
            dst_port: tcp.destination_port(),
            proto,
        }),
        TransportSlice::Udp(udp) => Some(FlowKey {
            src_ip,
            dst_ip,
            src_port: udp.source_port(),
            dst_port: udp.destination_port(),
            proto,
        }),
        _ => None,
    }
}

fn expire_flows(
    flows: &mut AHashMap<FlowKey, FlowStats>,
    now_sec: u64,
    idle_timeout: u64,
) -> usize {
    let before = flows.len();
    flows.retain(|key, stats| {
        let expired = now_sec.saturating_sub(stats.last_seen_sec) > idle_timeout;
        if expired {
            println!(
                "FLOW {} packets={} bytes={} first={} last={}",
                key, stats.packets, stats.bytes, stats.first_seen_sec, stats.last_seen_sec
            );
        }
        !expired
    });
    before - flows.len()
}

fn open_capture(args: &Args) -> Result<Capture<Active>, Box<dyn std::error::Error>> {
    let device = if let Some(ref iface) = args.interface {
        let devices = Device::list()?;
        devices
            .into_iter()
            .find(|d| d.name == *iface)
            .ok_or_else(|| format!("Interface '{}' not found", iface))?
    } else {
        Device::lookup()?.ok_or("No default capture device found")?
    };

    let mut cap = Capture::from_device(device)?
        .promisc(args.promiscuous)
        .snaplen(args.snaplen)
        .immediate_mode(true)
        .open()?;

    cap.filter(&args.filter, true)?;
    Ok(cap)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    let running = Arc::new(AtomicBool::new(true));
    let running_flag = running.clone();

    ctrlc::set_handler(move || {
        running_flag.store(false, Ordering::SeqCst);
    })?;

    let mut cap = open_capture(&args)?;
    let mut flows: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(262_144);

    let mut packets_seen: u64 = 0;
    let mut bytes_seen: u64 = 0;
    let mut last_sweep_sec: u64 = 0;

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let ts_sec = packet_ts_sec(packet.header);
                let wire_len = packet.header.len as u64;

                packets_seen += 1;
                bytes_seen += wire_len;

                if let Some(key) = extract_flow(packet.data) {
                    match flows.get_mut(&key) {
                        Some(stats) => stats.update(ts_sec, wire_len),
                        None => {
                            flows.insert(key, FlowStats::new(ts_sec, wire_len));
                        }
                    }
                }

                if ts_sec != last_sweep_sec {
                    last_sweep_sec = ts_sec;
                    let expired = expire_flows(&mut flows, ts_sec, args.idle_timeout);
                    if expired > 0 || packets_seen % 100_000 == 0 {
                        eprintln!(
                            "status packets={} bytes={} active_flows={} expired={}",
                            packets_seen,
                            bytes_seen,
                            flows.len(),
                            expired
                        );
                    }
                }

                if flows.len() > args.max_flows {
                    let cutoff = ts_sec.saturating_sub(args.idle_timeout / 2);
                    let before = flows.len();
                    flows.retain(|key, stats| {
                        let expired = stats.last_seen_sec < cutoff;
                        if expired {
                            println!(
                                "FLOW {} packets={} bytes={} first={} last={}",
                                key, stats.packets, stats.bytes, stats.first_seen_sec, stats.last_seen_sec
                            );
                        }
                        !expired
                    });
                    eprintln!(
                        "forced_sweep active_flows_before={} active_flows_after={}",
                        before,
                        flows.len()
                    );
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("capture error: {}", e);
                break;
            }
        }
    }

    let now_sec = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs();

    for (key, stats) in flows.drain() {
        println!(
            "FLOW {} packets={} bytes={} first={} last={}",
            key, stats.packets, stats.bytes, stats.first_seen_sec, stats.last_seen_sec
        );
    }

    eprintln!(
        "shutdown packets={} bytes={} final_flush_ts={}",
        packets_seen, bytes_seen, now_sec
    );

    Ok(())
}
