## Safe alternative: high-throughput local event-stream analyzer

This version:
- reads newline-delimited synthetic “flow events” from stdin or a local file
- parses them efficiently
- aggregates per 5-tuple–like key
- expires old entries
- prints periodic stats

It demonstrates:
- lock-free-ish channel pipeline
- worker sharding by hash
- low-allocation parsing
- periodic aggregation/expiration

### `main.go`
```go
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"hash/fnv"
	"io"
	"os"
	"runtime"
	"strconv"
	"strings"
	"sync"
	"time"
)

type Event struct {
	Ts    int64
	Src   string
	Dst   string
	SPort uint16
	DPort uint16
	Proto uint8
	Bytes uint32
}

type FlowKey struct {
	Src   string
	Dst   string
	SPort uint16
	DPort uint16
	Proto uint8
}

type FlowStats struct {
	Packets    uint64
	Bytes      uint64
	LastSeenTs int64
}

type shard struct {
	mu    sync.Mutex
	table map[FlowKey]FlowStats
}

const (
	numShards      = 64
	expireAfterSec = 30
	reportEverySec = 5
)

// Input format per line:
// ts,src,dst,sport,dport,proto,bytes
// Example:
// 1710000000,10.0.0.1,10.0.0.2,12345,443,6,1500

func parseLine(b []byte) (Event, bool) {
	var e Event
	b = bytes.TrimSpace(b)
	if len(b) == 0 {
		return e, false
	}
	parts := bytes.Split(b, []byte{','})
	if len(parts) != 7 {
		return e, false
	}

	ts, err := strconv.ParseInt(string(parts[0]), 10, 64)
	if err != nil {
		return e, false
	}
	sport, err := strconv.ParseUint(string(parts[3]), 10, 16)
	if err != nil {
		return e, false
	}
	dport, err := strconv.ParseUint(string(parts[4]), 10, 16)
	if err != nil {
		return e, false
	}
	proto, err := strconv.ParseUint(string(parts[5]), 10, 8)
	if err != nil {
		return e, false
	}
	nbytes, err := strconv.ParseUint(string(parts[6]), 10, 32)
	if err != nil {
		return e, false
	}

	e = Event{
		Ts:    ts,
		Src:   string(parts[1]),
		Dst:   string(parts[2]),
		SPort: uint16(sport),
		DPort: uint16(dport),
		Proto: uint8(proto),
		Bytes: uint32(nbytes),
	}
	return e, true
}

func hashKey(k FlowKey) uint64 {
	h := fnv.New64a()
	h.Write([]byte(k.Src))
	h.Write([]byte{0})
	h.Write([]byte(k.Dst))
	h.Write([]byte{0})
	h.Write([]byte(strconv.Itoa(int(k.SPort))))
	h.Write([]byte{0})
	h.Write([]byte(strconv.Itoa(int(k.DPort))))
	h.Write([]byte{0})
	h.Write([]byte(strconv.Itoa(int(k.Proto))))
	return h.Sum64()
}

func worker(s *shard, ch <-chan Event) {
	for e := range ch {
		k := FlowKey{
			Src:   e.Src,
			Dst:   e.Dst,
			SPort: e.SPort,
			DPort: e.DPort,
			Proto: e.Proto,
		}
		s.mu.Lock()
		fs := s.table[k]
		fs.Packets++
		fs.Bytes += uint64(e.Bytes)
		fs.LastSeenTs = e.Ts
		s.table[k] = fs
		s.mu.Unlock()
	}
}

func expireAndReport(shards []shard) {
	ticker := time.NewTicker(reportEverySec * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		now := time.Now().Unix()
		var flows, packets, bytes uint64

		for i := range shards {
			shards[i].mu.Lock()
			for k, v := range shards[i].table {
				if now-v.LastSeenTs > expireAfterSec {
					delete(shards[i].table, k)
					continue
				}
				flows++
				packets += v.Packets
				bytes += v.Bytes
			}
			shards[i].mu.Unlock()
		}

		fmt.Printf("active_flows=%d packets=%d bytes=%d\n", flows, packets, bytes)
	}
}

func openInput() (io.Reader, error) {
	if len(os.Args) > 1 {
		return os.Open(os.Args[1])
	}
	return os.Stdin, nil
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	var shards [numShards]shard
	chans := make([]chan Event, numShards)
	for i := 0; i < numShards; i++ {
		shards[i] = shard{table: make(map[FlowKey]FlowStats, 4096)}
		chans[i] = make(chan Event, 8192)
		go worker(&shards[i], chans[i])
	}

	go expireAndReport(shards[:])

	in, err := openInput()
	if err != nil {
		fmt.Fprintln(os.Stderr, "open input:", err)
		os.Exit(1)
	}

	br := bufio.NewReaderSize(in, 1<<20)
	for {
		line, err := br.ReadBytes('\n')
		if len(line) > 0 {
			if e, ok := parseLine(line); ok {
				k := FlowKey{
					Src:   e.Src,
					Dst:   e.Dst,
					SPort: e.SPort,
					DPort: e.DPort,
					Proto: e.Proto,
				}
				idx := hashKey(k) % numShards
				chans[idx] <- e
			}
		}
		if err != nil {
			if err != io.EOF {
				fmt.Fprintln(os.Stderr, "read error:", err)
			}
			break
		}
	}

	for _, ch := range chans {
		close(ch)
	}

	time.Sleep(1 * time.Second)
}
