```rust
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Capture, Device};
use std::collections::HashMap;
use std::env;
use std::net::IpAddr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src: [u8; 4],
    dst: [u8; 4],
    sport: u16,
    dport: u16,
    proto: u8,
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

fn format_ipv4(ip: [u8; 4]) -> String {
    format!("{}.{}.{}.{}", ip[0], ip[1], ip[2], ip[3])
}

fn print_top(flows: &HashMap<FlowKey, FlowStats>, limit: usize) {
    let mut items: Vec<_> = flows.iter().collect();
    items.sort_by_key(|(_, st)| std::cmp::Reverse(st.bytes));

    println!("--- active flows: {} ---", flows.len());
    for (k, st) in items.into_iter().take(limit) {
        println!(
            "{}:{} -> {}:{} proto={} pkts={} bytes={} age={:?} idle={:?}",
            format_ipv4(k.src),
            k.sport,
            format_ipv4(k.dst),
            k.dport,
            k.proto,
            st.packets,
            st.bytes,
            st.first_seen.elapsed(),
            st.last_seen.elapsed()
        );
    }
}

fn expire_idle(flows: &mut HashMap<FlowKey, FlowStats>, idle_timeout: Duration) {
    let now = Instant::now();
    flows.retain(|_, st| now.duration_since(st.last_seen) < idle_timeout);
}

fn handle_packet(data: &[u8], ts: Instant, flows: &mut HashMap<FlowKey, FlowStats>) {
    let sliced = match SlicedPacket::from_ethernet(data) {
        Ok(s) => s,
        Err(_) => return,
    };

    let (src, dst, proto) = match sliced.ip {
        Some(InternetSlice::Ipv4(header, _)) => {
            let src = header.source();
            let dst = header.destination();
            let proto = header.protocol().0;
            (src, dst, proto)
        }
        _ => return,
    };

    let (sport, dport) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
        _ => return,
    };

    let key = FlowKey {
        src,
        dst,
        sport,
        dport,
        proto,
    };

    let entry = flows.entry(key).or_insert(FlowStats {
        packets: 0,
        bytes: 0,
        first_seen: ts,
        last_seen: ts,
    });

    entry.packets += 1;
    entry.bytes += data.len() as u64;
    entry.last_seen = ts;
}

fn open_capture(arg: Option<String>) -> Result<Capture<pcap::Active>, Box<dyn std::error::Error>> {
    let dev = if let Some(name) = arg {
        Device::list()?
            .into_iter()
            .find(|d| d.name == name)
            .ok_or("device not found")?
    } else {
        Device::lookup()?.ok_or("no default device found")?
    };

    let cap = Capture::from_device(dev)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .timeout(1000)
        .open()?;

    Ok(cap)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let iface = env::args().nth(1);

    let running = Arc::new(AtomicBool::new(true));
    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::SeqCst);
        })?;
    }

    let mut cap = open_capture(iface)?;
    cap.filter("ip and (tcp or udp)", true)?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(65_536);

    let idle_timeout = Duration::from_secs(30);
    let report_every = Duration::from_secs(5);
    let mut last_report = Instant::now();

    while running.load(Ordering::SeqCst) {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                handle_packet(packet.data, now, &mut flows);

                if last_report.elapsed() >= report_every {
                    expire_idle(&mut flows, idle_timeout);
                    print_top(&flows, 20);
                    last_report = Instant::now();
                }
            }
            Err(pcap::Error::TimeoutExpired) => {
                if last_report.elapsed() >= report_every {
                    expire_idle(&mut flows, idle_timeout);
                    print_top(&flows, 20);
                    last_report = Instant::now();
                }
            }
            Err(e) => {
                eprintln!("capture error: {e}");
                break;
            }
        }
    }

    expire_idle(&mut flows, idle_timeout);
    print_top(&flows, 50);
    Ok(())
}
