# Source: `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>

#define HASH_SIZE 262144
#define FLOW_IDLE_TIMEOUT 30
#define SNAPLEN 128

static volatile sig_atomic_t stop_capture = 0;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t first_seen;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];

static inline uint32_t flow_hash(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h ^= k->src_ip;   h *= 16777619u;
    h ^= k->dst_ip;   h *= 16777619u;
    h ^= k->src_port; h *= 16777619u;
    h ^= k->dst_port; h *= 16777619u;
    h ^= k->proto;    h *= 16777619u;
    return h & (HASH_SIZE - 1);
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip   == b->src_ip &&
           a->dst_ip   == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto    == b->proto;
}

static void print_flow(const flow_entry_t *f) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];
    struct in_addr saddr = { .s_addr = f->key.src_ip };
    struct in_addr daddr = { .s_addr = f->key.dst_ip };

    inet_ntop(AF_INET, &saddr, src, sizeof(src));
    inet_ntop(AF_INET, &daddr, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%lu bytes=%lu duration=%lds\n",
           src, ntohs(f->key.src_port),
           dst, ntohs(f->key.dst_port),
           f->key.proto,
           (unsigned long)f->packets,
           (unsigned long)f->bytes,
           (long)(f->last_seen - f->first_seen));
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, time_t now) {
    uint32_t idx = flow_hash(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            return e;
        }
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) {
        perror("calloc");
        return NULL;
    }

    e->key = *key;
    e->first_seen = now;
    e->last_seen = now;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void expire_flows(time_t now) {
    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if ((now - e->last_seen) >= FLOW_IDLE_TIMEOUT) {
                print_flow(e);
                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void flush_all_flows(void) {
    for (uint32_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            flow_entry_t *next = e->next;
            print_flow(e);
            free(e);
            e = next;
        }
        flow_table[i] = NULL;
    }
}

static void handle_signal(int sig) {
    (void)sig;
    stop_capture = 1;
}

static void process_packet(const struct pcap_pkthdr *hdr, const uint8_t *packet) {
    if (hdr->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const uint8_t *ip_ptr = packet + sizeof(struct ether_header);
    uint32_t ip_len_avail = hdr->caplen - sizeof(struct ether_header);
    if (ip_len_avail < sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)ip_ptr;
    if (iph->ip_v != 4) return;

    uint32_t ip_hdr_len = iph->ip_hl * 4;
    if (ip_hdr_len < sizeof(struct ip) || ip_hdr_len > ip_len_avail) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const uint8_t *l4_ptr = ip_ptr + ip_hdr_len;
    uint32_t l4_len = ip_len_avail - ip_hdr_len;

    if (key.proto == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcph = (const struct tcphdr *)l4_ptr;
        key.src_port = tcph->source;
        key.dst_port = tcph->dest;
    } else if (key.proto == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udph = (const struct udphdr *)l4_ptr;
        key.src_port = udph->source;
        key.dst_port = udph->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    time_t now = hdr->ts.tv_sec;
    flow_entry_t *flow = flow_lookup_or_create(&key, now);
    if (!flow) return;

    flow->packets++;
    flow->bytes += hdr->len;
    flow->last_seen = now;
}

static void packet_handler(uint8_t *user, const struct pcap_pkthdr *hdr, const uint8_t *packet) {
    (void)user;
    process_packet(hdr, packet);
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    char *dev = NULL;
    pcap_t *handle;
    struct bpf_program fp;
    const char *filter_exp = "ip";
    bpf_u_int32 net = 0, mask = 0;
    time_t last_expire = 0;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface> [bpf-filter]\n", argv[0]);
        return 1;
    }

    dev = argv[1];
    if (argc >= 3) {
        filter_exp = argv[2];
    }

    if (pcap_lookupnet(dev, &net, &mask, errbuf) == -1) {
        net = 0;
        mask = 0;
    }

    handle = pcap_open_live(dev, SNAPLEN, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live(%s) failed: %s\n", dev, errbuf);
        return 1;
    }

    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Only Ethernet is supported in this minimal version.\n");
        pcap_close(handle);
        return 1;
    }

    if (pcap_compile(handle, &fp, filter_exp, 1, mask) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }
    pcap_freecode(&fp);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Capturing on %s with filter: %s\n", dev, filter_exp);

    while (!stop_capture) {
        int rc = pcap_dispatch(handle, 1024, packet_handler, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch failed: %s\n", pcap_geterr(handle));
            break;
        }

        time_t now = time(NULL);
        if (now != last_expire) {
            expire_flows(now);
            last_expire = now;
        }
    }

    flush_all_flows();
    pcap_close(handle);
    return 0;
}
