## `src/main.rs`

```rust
use hashbrown::HashMap;
use pcap::{Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

fn be_u16(b: &[u8]) -> u16 {
    u16::from_be_bytes([b[0], b[1]])
}

fn be_u32(b: &[u8]) -> u32 {
    u32::from_be_bytes([b[0], b[1], b[2], b[3]])
}

fn format_ipv4(ip: u32) -> Ipv4Addr {
    Ipv4Addr::from(ip)
}

fn parse_ipv4_flow(packet: &[u8]) -> Option<(FlowKey, usize)> {
    // Ethernet II minimum
    if packet.len() < 14 {
        return None;
    }

    let ethertype = be_u16(&packet[12..14]);
    if ethertype != 0x0800 {
        return None; // only IPv4
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return None;
    }

    let version = ip[0] >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((ip[0] & 0x0f) as usize) * 4;
    if ihl < 20 || ip.len() < ihl {
        return None;
    }

    let total_len = be_u16(&ip[2..4]) as usize;
    if total_len < ihl || ip.len() < total_len {
        return None;
    }

    let proto = ip[9];
    let src_ip = be_u32(&ip[12..16]);
    let dst_ip = be_u32(&ip[16..20]);

    match proto {
        6 | 17 => {
            // TCP or UDP
            if total_len < ihl + 4 {
                return None;
            }
            let l4 = &ip[ihl..total_len];
            if l4.len() < 4 {
                return None;
            }

            let src_port = be_u16(&l4[0..2]);
            let dst_port = be_u16(&l4[2..4]);

            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                },
                total_len,
            ))
        }
        _ => None,
    }
}

fn expire_and_report(flows: &mut HashMap<FlowKey, FlowStats>, idle_timeout: Duration) {
    let now = Instant::now();
    let mut expired = Vec::new();

    for (k, v) in flows.iter() {
        if now.duration_since(v.last_seen) >= idle_timeout {
            expired.push((*k, v.clone()));
        }
    }

    for (k, v) in expired {
        flows.remove(&k);
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={} duration_ms={}",
            format_ipv4(k.src_ip),
            k.src_port,
            format_ipv4(k.dst_ip),
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes,
            v.last_seen.duration_since(v.first_seen).as_millis()
        );
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    })?;

    let device = Device::lookup()?
        .ok_or("no capture device found")?;

    eprintln!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(128)
        .timeout(1000)
        .open()?;

    // Keep only IPv4 TCP/UDP traffic
    cap.filter("ip and (tcp or udp)", true)?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let idle_timeout = Duration::from_secs(30);
    let mut last_expire = Instant::now();

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                if let Some((key, bytes)) = parse_ipv4_flow(packet.data) {
                    let now = Instant::now();
                    let entry = flows.entry(key).or_insert(FlowStats {
                        packets: 0,
                        bytes: 0,
                        first_seen: now,
                        last_seen: now,
                    });
                    entry.packets += 1;
                    entry.bytes += bytes as u64;
                    entry.last_seen = now;
                }
            }
            Err(pcap::Error::TimeoutExpired) => {}
            Err(e) => {
                eprintln!("capture error: {e}");
                break;
            }
        }

        if last_expire.elapsed() >= Duration::from_secs(5) {
            expire_and_report(&mut flows, idle_timeout);
            last_expire = Instant::now();
        }
    }

    eprintln!("Shutting down, flushing remaining flows...");
    for (k, v) in flows.drain() {
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={} duration_ms={}",
            format_ipv4(k.src_ip),
            k.src_port,
            format_ipv4(k.dst_ip),
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes,
            v.last_seen.duration_since(v.first_seen).as_millis()
        );
    }

    Ok(())
}
```

