## Code: `flow_analyzer.c`
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <sys/time.h>
#include <signal.h>
#include <unistd.h>

#define HASH_SIZE 65536
#define FLOW_TIMEOUT_SEC 30

static volatile int running = 1;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timeval first_seen;
    struct timeval last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h % HASH_SIZE;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void print_flow(const flow_entry_t *f) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];
    struct in_addr saddr = { .s_addr = f->key.src_ip };
    struct in_addr daddr = { .s_addr = f->key.dst_ip };

    inet_ntop(AF_INET, &saddr, src, sizeof(src));
    inet_ntop(AF_INET, &daddr, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu duration=%.3f sec\n",
           src, ntohs(f->key.src_port),
           dst, ntohs(f->key.dst_port),
           f->key.proto,
           (unsigned long long)f->packets,
           (unsigned long long)f->bytes,
           (f->last_seen.tv_sec - f->first_seen.tv_sec) +
           (f->last_seen.tv_usec - f->first_seen.tv_usec) / 1000000.0);
}

static void expire_flows(struct timeval now) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *f = *pp;
            time_t age = now.tv_sec - f->last_seen.tv_sec;
            if (age >= FLOW_TIMEOUT_SEC) {
                print_flow(f);
                *pp = f->next;
                free(f);
            } else {
                pp = &f->next;
            }
        }
    }
}

static void flush_all_flows(void) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *f = flow_table[i];
        while (f) {
            flow_entry_t *next = f->next;
            print_flow(f);
            free(f);
            f = next;
        }
        flow_table[i] = NULL;
    }
}

static void process_packet(const struct pcap_pkthdr *hdr, const uint8_t *packet) {
    if (hdr->caplen < 14) return; // Ethernet header

    const uint16_t ethertype = ((uint16_t)packet[12] << 8) | packet[13];
    if (ethertype != 0x0800) return; // IPv4 only

    const uint8_t *ip_ptr = packet + 14;
    if (hdr->caplen < 14 + sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)ip_ptr;
    const uint8_t ip_hl = iph->ip_hl * 4;
    if (ip_hl < 20) return;
    if (hdr->caplen < 14 + ip_hl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const uint8_t *l4 = ip_ptr + ip_hl;

    if (key.proto == IPPROTO_TCP) {
        if (hdr->caplen < (size_t)(l4 - packet) + sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (key.proto == IPPROTO_UDP) {
        if (hdr->caplen < (size_t)(l4 - packet) + sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    uint32_t idx = hash_flow(&key);
    flow_entry_t *f = flow_table[idx];

    while (f) {
        if (flow_equal(&f->key, &key)) {
            f->packets++;
            f->bytes += hdr->len;
            f->last_seen = hdr->ts;
            return;
        }
        f = f->next;
    }

    f = calloc(1, sizeof(*f));
    if (!f) return;

    f->key = key;
    f->packets = 1;
    f->bytes = hdr->len;
    f->first_seen = hdr->ts;
    f->last_seen = hdr->ts;
    f->next = flow_table[idx];
    flow_table[idx] = f;
}

static void packet_handler(uint8_t *user, const struct pcap_pkthdr *hdr, const uint8_t *packet) {
    (void)user;
    process_packet(hdr, packet);

    static time_t last_expire = 0;
    if (hdr->ts.tv_sec != last_expire) {
        last_expire = hdr->ts.tv_sec;
        expire_flows(hdr->ts);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface|pcap_file>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *pcap = NULL;

    if (access(argv[1], F_OK) == 0) {
        pcap = pcap_open_offline(argv[1], errbuf);
    } else {
        pcap = pcap_open_live(argv[1], 65535, 1, 1000, errbuf);
    }

    if (!pcap) {
        fprintf(stderr, "pcap open failed: %s\n", errbuf);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(pcap, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(pcap, &fp);
        pcap_freecode(&fp);
    }

    while (running) {
        int rc = pcap_dispatch(pcap, 1024, packet_handler, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(pcap));
            break;
        }
        if (rc == 0 && pcap_file(pcap)) {
            break;
        }
    }

    flush_all_flows();
    pcap_close(pcap);
    return 0;
}
