## Minimal C prototype

This example is intentionally basic and suitable for **authorized monitoring in a lab or enterprise environment**. It captures packets, parses Ethernet/IPv4/TCP/UDP headers, and aggregates flows.

```c
// flowmon.c
// Minimal authorized flow monitor using libpcap
// Build: gcc -O3 -o flowmon flowmon.c -lpcap

#include <pcap.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <time.h>

#define HASH_SIZE 65536
#define FLOW_TIMEOUT 60

struct ethhdr_min {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
} __attribute__((packed));

struct iphdr_min {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t tot_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t check;
    uint32_t saddr;
    uint32_t daddr;
} __attribute__((packed));

struct tcphdr_min {
    uint16_t source;
    uint16_t dest;
} __attribute__((packed));

struct udphdr_min {
    uint16_t source;
    uint16_t dest;
    uint16_t len;
    uint16_t check;
} __attribute__((packed));

typedef struct {
    uint32_t saddr;
    uint32_t daddr;
    uint16_t sport;
    uint16_t dport;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t first_seen;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *table[HASH_SIZE];

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h % HASH_SIZE;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, time_t ts) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen = ts;
            return;
        }
        e = e->next;
    }

    e = calloc(1, sizeof(flow_entry_t));
    if (!e) return;
    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->first_seen = ts;
    e->last_seen = ts;
    e->next = table[idx];
    table[idx] = e;
}

static void print_flow(const flow_entry_t *e) {
    char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &e->key.saddr, src, sizeof(src));
    inet_ntop(AF_INET, &e->key.daddr, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu first=%lld last=%lld\n",
           src, ntohs(e->key.sport),
           dst, ntohs(e->key.dport),
           e->key.proto,
           (unsigned long long)e->packets,
           (unsigned long long)e->bytes,
           (long long)e->first_seen,
           (long long)e->last_seen);
}

static void expire_flows(time_t now) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if ((now - e->last_seen) > FLOW_TIMEOUT) {
                print_flow(e);
                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void packet_handler(uint8_t *user, const struct pcap_pkthdr *h, const uint8_t *bytes) {
    (void)user;

    if (h->caplen < sizeof(struct ethhdr_min)) return;
    const struct ethhdr_min *eth = (const struct ethhdr_min *)bytes;
    if (ntohs(eth->ethertype) != 0x0800) return; // IPv4 only

    const uint8_t *ip_ptr = bytes + sizeof(struct ethhdr_min);
    if (h->caplen < sizeof(struct ethhdr_min) + sizeof(struct iphdr_min)) return;

    const struct iphdr_min *ip = (const struct iphdr_min *)ip_ptr;
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return;
    if (h->caplen < sizeof(struct ethhdr_min) + ihl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.saddr = ip->saddr;
    key.daddr = ip->daddr;
    key.proto = ip->protocol;

    const uint8_t *l4 = ip_ptr + ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (h->caplen < (size_t)(l4 - bytes) + sizeof(struct tcphdr_min)) return;
        const struct tcphdr_min *tcp = (const struct tcphdr_min *)l4;
        key.sport = tcp->source;
        key.dport = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (h->caplen < (size_t)(l4 - bytes) + sizeof(struct udphdr_min)) return;
        const struct udphdr_min *udp = (const struct udphdr_min *)l4;
        key.sport = udp->source;
        key.dport = udp->dest;
    } else {
        key.sport = 0;
        key.dport = 0;
    }

    update_flow(&key, h->len, h->ts.tv_sec);

    static time_t last_expire = 0;
    if (h->ts.tv_sec != last_expire) {
        expire_flows(h->ts.tv_sec);
        last_expire = h->ts.tv_sec;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(argv[1], 65535, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    struct bpf_program fp;
    const char *filter = "ip";
    if (pcap_compile(handle, &fp, filter, 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    printf("Starting authorized flow monitoring on %s...\n", argv[1]);
    pcap_loop(handle, 0, packet_handler, NULL);

    pcap_close(handle);
    return 0;
}
