# Code: `flowmon.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define HASH_SIZE 262144
#define FLOW_TIMEOUT 30
#define EXPIRE_INTERVAL 5
#define SNAPLEN 2048

static volatile sig_atomic_t stop = 0;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t first_seen;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];

static void on_sigint(int sig) {
    (void)sig;
    stop = 1;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h & (HASH_SIZE - 1);
}

static inline bool flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, time_t now) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            return e;
        }
        e = e->next;
    }

    e = calloc(1, sizeof(*e));
    if (!e) {
        perror("calloc");
        return NULL;
    }

    e->key = *key;
    e->first_seen = now;
    e->last_seen = now;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void print_flow(const flow_entry_t *e) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];
    struct in_addr s = { .s_addr = e->key.src_ip };
    struct in_addr d = { .s_addr = e->key.dst_ip };

    inet_ntop(AF_INET, &s, src, sizeof(src));
    inet_ntop(AF_INET, &d, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%lu bytes=%lu first=%ld last=%ld\n",
           src, ntohs(e->key.src_port),
           dst, ntohs(e->key.dst_port),
           e->key.proto,
           (unsigned long)e->packets,
           (unsigned long)e->bytes,
           (long)e->first_seen,
           (long)e->last_seen);
}

static void expire_flows(time_t now) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if ((now - e->last_seen) >= FLOW_TIMEOUT) {
                print_flow(e);
                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void flush_all_flows(void) {
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            flow_entry_t *next = e->next;
            print_flow(e);
            free(e);
            e = next;
        }
        flow_table[i] = NULL;
    }
}

static int set_promiscuous(int fd, const char *ifname, int enable) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (ioctl(fd, SIOCGIFFLAGS, &ifr) < 0) {
        perror("SIOCGIFFLAGS");
        return -1;
    }

    if (enable)
        ifr.ifr_flags |= IFF_PROMISC;
    else
        ifr.ifr_flags &= ~IFF_PROMISC;

    if (ioctl(fd, SIOCSIFFLAGS, &ifr) < 0) {
        perror("SIOCSIFFLAGS");
        return -1;
    }

    return 0;
}

static int bind_interface(int fd, const char *ifname) {
    struct sockaddr_ll sll;
    struct ifreq ifr;

    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        return -1;
    }

    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifr.ifr_ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return -1;
    }

    return 0;
}

static void process_packet(const uint8_t *buf, ssize_t len, time_t now) {
    if (len < (ssize_t)sizeof(struct ethhdr))
        return;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return;

    const uint8_t *ipbuf = buf + sizeof(struct ethhdr);
    ssize_t iplen = len - sizeof(struct ethhdr);

    if (iplen < (ssize_t)sizeof(struct iphdr))
        return;

    const struct iphdr *iph = (const struct iphdr *)ipbuf;
    if (iph->version != 4)
        return;

    size_t ihl = iph->ihl * 4;
    if (ihl < sizeof(struct iphdr) || iplen < (ssize_t)ihl)
        return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->saddr;
    key.dst_ip = iph->daddr;
    key.proto = iph->protocol;

    const uint8_t *l4 = ipbuf + ihl;
    ssize_t l4len = iplen - ihl;

    if (iph->protocol == IPPROTO_TCP) {
        if (l4len < (ssize_t)sizeof(struct tcphdr))
            return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (iph->protocol == IPPROTO_UDP) {
        if (l4len < (ssize_t)sizeof(struct udphdr))
            return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    flow_entry_t *e = flow_lookup_or_create(&key, now);
    if (!e)
        return;

    e->packets++;
    e->bytes += (uint64_t)len;
    e->last_seen = now;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    int rcvbuf = 64 * 1024 * 1024;
    if (setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)) < 0) {
        perror("setsockopt SO_RCVBUF");
    }

    if (bind_interface(fd, ifname) < 0) {
        close(fd);
        return 1;
    }

    if (set_promiscuous(fd, ifname, 1) < 0) {
        close(fd);
        return 1;
    }

    uint8_t *buf = malloc(SNAPLEN);
    if (!buf) {
        perror("malloc");
        set_promiscuous(fd, ifname, 0);
        close(fd);
        return 1;
    }

    time_t last_expire = time(NULL);

    while (!stop) {
        ssize_t n = recvfrom(fd, buf, SNAPLEN, 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("recvfrom");
            break;
        }

        time_t now = time(NULL);
        process_packet(buf, n, now);

        if ((now - last_expire) >= EXPIRE_INTERVAL) {
            expire_flows(now);
            last_expire = now;
        }
    }

    flush_all_flows();
    free(buf);
    set_promiscuous(fd, ifname, 0);
    close(fd);
    return 0;
}
