# 1. C implementation

Save as `flow_analyzer.c`:

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define HASH_SIZE (1 << 20)      // ~1M buckets
#define FLOW_TIMEOUT 30          // seconds
#define REPORT_INTERVAL 5        // seconds
#define MAX_CHAIN 8              // bounded linear probing

static volatile int running = 1;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ms;
    uint64_t last_seen_ms;
    uint8_t  used;
} flow_entry_t;

static flow_entry_t *flow_table;

static uint64_t now_ms(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (uint64_t)tv.tv_sec * 1000ULL + tv.tv_usec / 1000ULL;
}

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h & (HASH_SIZE - 1);
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void print_ip(uint32_t ip, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void report_flows(uint64_t now) {
    printf("---- flow report ----\n");
    for (size_t i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = &flow_table[i];
        if (!e->used) continue;

        if ((now - e->last_seen_ms) > FLOW_TIMEOUT * 1000ULL) {
            e->used = 0;
            continue;
        }

        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        print_ip(e->key.src_ip, src, sizeof(src));
        print_ip(e->key.dst_ip, dst, sizeof(dst));

        printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu age=%llums idle=%llums\n",
               src, ntohs(e->key.src_port),
               dst, ntohs(e->key.dst_port),
               e->key.proto,
               (unsigned long long)e->packets,
               (unsigned long long)e->bytes,
               (unsigned long long)(now - e->first_seen_ms),
               (unsigned long long)(now - e->last_seen_ms));
    }
    fflush(stdout);
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, uint64_t ts_ms) {
    uint32_t idx = hash_flow(key);

    for (int i = 0; i < MAX_CHAIN; i++) {
        flow_entry_t *e = &flow_table[(idx + i) & (HASH_SIZE - 1)];

        if (e->used) {
            if (flow_equal(&e->key, key)) {
                e->packets++;
                e->bytes += pkt_len;
                e->last_seen_ms = ts_ms;
                return;
            }

            if ((ts_ms - e->last_seen_ms) > FLOW_TIMEOUT * 1000ULL) {
                e->used = 0;
            }
        }

        if (!e->used) {
            e->used = 1;
            e->key = *key;
            e->packets = 1;
            e->bytes = pkt_len;
            e->first_seen_ms = ts_ms;
            e->last_seen_ms = ts_ms;
            return;
        }
    }

    // Drop if probe window full
}

static void process_packet(const uint8_t *buf, ssize_t len) {
    if ((size_t)len < sizeof(struct ethhdr)) return;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP) return;

    const uint8_t *ip_ptr = buf + sizeof(struct ethhdr);
    ssize_t ip_len = len - sizeof(struct ethhdr);
    if (ip_len < (ssize_t)sizeof(struct iphdr)) return;

    const struct iphdr *ip = (const struct iphdr *)ip_ptr;
    if (ip->version != 4) return;

    uint32_t ihl = ip->ihl * 4;
    if (ihl < sizeof(struct iphdr) || ip_len < (ssize_t)ihl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto = ip->protocol;

    const uint8_t *l4 = ip_ptr + ihl;
    ssize_t l4_len = ip_len - ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < (ssize_t)sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < (ssize_t)sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    update_flow(&key, (uint32_t)len, now_ms());
}

static int bind_interface(int sock, const char *ifname) {
    struct sockaddr_ll sll;
    struct ifreq ifr;

    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        return -1;
    }

    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifr.ifr_ifindex;

    if (bind(sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    flow_table = calloc(HASH_SIZE, sizeof(flow_entry_t));
    if (!flow_table) {
        perror("calloc");
        return 1;
    }

    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket");
        free(flow_table);
        return 1;
    }

    int rcvbuf = 64 * 1024 * 1024;
    if (setsockopt(sock, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)) < 0) {
        perror("setsockopt(SO_RCVBUF)");
    }

    if (bind_interface(sock, argv[1]) < 0) {
        close(sock);
        free(flow_table);
        return 1;
    }

    uint8_t buf[2048];
    uint64_t last_report = now_ms();

    while (running) {
        ssize_t n = recvfrom(sock, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        process_packet(buf, n);

        uint64_t now = now_ms();
        if ((now - last_report) >= REPORT_INTERVAL * 1000ULL) {
            report_flows(now);
            last_report = now;
        }
    }

    report_flows(now_ms());

    close(sock);
    free(flow_table);
    return 0;
}
```

