Below is a practical embedded C firmware example for a microcontroller that:

- reads sensor data from an ADC
- filters/processes the data
- computes engineering units
- raises simple alarms
- runs in a periodic loop

I’ll keep it generic so it can be adapted to STM32, AVR, PIC, MSP430, or similar MCUs.

---

## Example firmware in C

```c
#include <stdint.h>
#include <stdbool.h>

/*
 * Generic firmware example:
 * - Reads an analog sensor through ADC
 * - Applies moving average filtering
 * - Converts ADC counts to voltage
 * - Converts voltage to temperature
 * - Detects alarm conditions
 *
 * Replace hardware-specific stubs with your MCU SDK/HAL functions.
 */

#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLES          16
#define TEMP_HIGH_THRESHOLD_C   60.0f
#define TEMP_LOW_THRESHOLD_C    0.0f

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float temperature_c;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

static SensorData_t g_sensor_data;

/* Moving average filter state */
static uint16_t sample_buffer[SENSOR_SAMPLES];
static uint32_t sample_sum = 0;
static uint8_t sample_index = 0;
static bool buffer_filled = false;

/* Function prototypes */
void System_Init(void);
void ADC_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void GPIO_Init(void);
void Alarm_High_On(void);
void Alarm_High_Off(void);
void Alarm_Low_On(void);
void Alarm_Low_Off(void);
void Delay_ms(uint32_t ms);

static uint16_t Filter_MovingAverage(uint16_t new_sample);
static float Convert_ADC_To_Voltage(uint16_t adc_counts);
static float Convert_Voltage_To_Temperature(float voltage);
static void Process_Sensor(void);

/* ---------------- Hardware abstraction stubs ---------------- */

void System_Init(void)
{
    GPIO_Init();
    ADC_Init();
}

void ADC_Init(void)
{
    /* Replace with MCU-specific ADC setup */
}

void GPIO_Init(void)
{
    /* Replace with MCU-specific GPIO setup */
}

uint16_t ADC_ReadChannel(uint8_t channel)
{
    (void)channel;

    /*
     * Replace with actual ADC read.
     * For demonstration, return a simulated mid-scale value.
     */
    static uint16_t fake_adc = 2000;
    fake_adc += 5;
    if (fake_adc > 3000)
        fake_adc = 1800;

    return fake_adc;
}

void Alarm_High_On(void)
{
    /* e.g. set GPIO pin */
}

void Alarm_High_Off(void)
{
    /* e.g. clear GPIO pin */
}

void Alarm_Low_On(void)
{
    /* e.g. set GPIO pin */
}

void Alarm_Low_Off(void)
{
    /* e.g. clear GPIO pin */
}

void Delay_ms(uint32_t ms)
{
    /* Replace with MCU-specific delay or timer wait */
    volatile uint32_t count;
    while (ms--)
    {
        for (count = 0; count < 8000; count++)
        {
            __asm__ volatile ("nop");
        }
    }
}

/* ---------------- Signal processing ---------------- */

static uint16_t Filter_MovingAverage(uint16_t new_sample)
{
    if (buffer_filled)
    {
        sample_sum -= sample_buffer[sample_index];
    }

    sample_buffer[sample_index] = new_sample;
    sample_sum += new_sample;

    sample_index++;
    if (sample_index >= SENSOR_SAMPLES)
    {
        sample_index = 0;
        buffer_filled = true;
    }

    if (buffer_filled)
    {
        return (uint16_t)(sample_sum / SENSOR_SAMPLES);
    }
    else
    {
        return (uint16_t)(sample_sum / sample_index);
    }
}

static float Convert_ADC_To_Voltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

/*
 * Example conversion for a linear temperature sensor:
 * - 0.5 V = 0°C
 * - 10 mV/°C
 *
 * Temp(°C) = (V - 0.5) / 0.01
 *
 * Adjust this for your actual sensor.
 */
static float Convert_Voltage_To_Temperature(float voltage)
{
    return (voltage - 0.5f) / 0.01f;
}

static void Process_Sensor(void)
{
    uint16_t raw = ADC_ReadChannel(0);
    uint16_t filtered = Filter_MovingAverage(raw);
    float voltage = Convert_ADC_To_Voltage(filtered);
    float temperature = Convert_Voltage_To_Temperature(voltage);

    g_sensor_data.raw_adc = filtered;
    g_sensor_data.voltage = voltage;
    g_sensor_data.temperature_c = temperature;

    g_sensor_data.alarm_high = (temperature > TEMP_HIGH_THRESHOLD_C);
    g_sensor_data.alarm_low  = (temperature < TEMP_LOW_THRESHOLD_C);

    if (g_sensor_data.alarm_high)
        Alarm_High_On();
    else
        Alarm_High_Off();

    if (g_sensor_data.alarm_low)
        Alarm_Low_On();
    else
        Alarm_Low_Off();
}

/* ---------------- Main application ---------------- */

int main(void)
{
    System_Init();

    /* Initialize filter buffer */
    for (uint8_t i = 0; i < SENSOR_SAMPLES; i++)
    {
        sample_buffer[i] = 0;
    }

    while (1)
    {
        Process_Sensor();

        /*
         * Sample every 100 ms.
         * In production firmware, prefer timer interrupts or RTOS tasks.
         */
        Delay_ms(100);
    }

    return 0;
}
```

