Below is a compact but realistic example of embedded firmware in C for a microcontroller that:

- reads sensor data from an ADC,
- filters it,
- converts it to engineering units,
- checks alarm thresholds,
- exposes processed values in a main loop.

This is written in a generic style so it can be adapted to STM32, AVR, PIC, MSP430, etc.

---

## Example firmware in C

```c
#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f      // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_OFFSET_VOLTAGE   0.5f         // Example sensor offset
#define SENSOR_SCALE            100.0f       // Example: 100 units per volt

#define FILTER_ALPHA            0.1f         // Low-pass filter coefficient
#define SENSOR_HIGH_THRESHOLD   80.0f
#define SENSOR_LOW_THRESHOLD    10.0f

#define SAMPLE_PERIOD_MS        10

/*=========================================================
 * Types
 *=========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float value;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

/*=========================================================
 * Global sensor state
 *=========================================================*/
static SensorData_t g_sensor = {0};

/*=========================================================
 * Hardware abstraction prototypes
 * Replace these with MCU-specific implementations
 *=========================================================*/
void System_Init(void);
void ADC_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void GPIO_Init(void);
void Alarm_High_On(void);
void Alarm_High_Off(void);
void Alarm_Low_On(void);
void Alarm_Low_Off(void);
void Delay_ms(uint32_t ms);

/*=========================================================
 * Sensor processing functions
 *=========================================================*/
static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float low_pass_filter(float input, float previous_output, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * previous_output);
}

static float voltage_to_sensor_units(float voltage)
{
    /* Example linear conversion:
       sensor_value = (voltage - offset) * scale
    */
    return (voltage - SENSOR_OFFSET_VOLTAGE) * SENSOR_SCALE;
}

static void process_sensor(SensorData_t *sensor, uint8_t adc_channel)
{
    sensor->raw_adc = ADC_ReadChannel(adc_channel);

    sensor->voltage = adc_to_voltage(sensor->raw_adc);

    sensor->filtered_voltage = low_pass_filter(
        sensor->voltage,
        sensor->filtered_voltage,
        FILTER_ALPHA
    );

    sensor->value = voltage_to_sensor_units(sensor->filtered_voltage);

    sensor->alarm_high = (sensor->value > SENSOR_HIGH_THRESHOLD);
    sensor->alarm_low  = (sensor->value < SENSOR_LOW_THRESHOLD);

    if (sensor->alarm_high)
        Alarm_High_On();
    else
        Alarm_High_Off();

    if (sensor->alarm_low)
        Alarm_Low_On();
    else
        Alarm_Low_Off();
}

/*=========================================================
 * Main application
 *=========================================================*/
int main(void)
{
    System_Init();
    GPIO_Init();
    ADC_Init();

    /* Initialize filter with first sample to avoid startup jump */
    g_sensor.raw_adc = ADC_ReadChannel(0);
    g_sensor.voltage = adc_to_voltage(g_sensor.raw_adc);
    g_sensor.filtered_voltage = g_sensor.voltage;
    g_sensor.value = voltage_to_sensor_units(g_sensor.filtered_voltage);

    while (1)
    {
        process_sensor(&g_sensor, 0);

        /* At this point, g_sensor contains:
           - raw ADC reading
           - measured voltage
           - filtered voltage
           - converted sensor value
           - alarm states
        */

        Delay_ms(SAMPLE_PERIOD_MS);
    }

    return 0;
}

/*=========================================================
 * Stub hardware implementations
 * Replace with real MCU code
 *=========================================================*/
