# Example Firmware in C

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*=============================
  Configuration
=============================*/
#define ADC_MAX_COUNTS       4095.0f      // 12-bit ADC
#define ADC_REF_VOLTAGE      3.3f
#define SENSOR_SAMPLES       16
#define MOVING_AVG_SIZE      8
#define UART_TX_BUFFER_SIZE  128

/* Example temperature sensor:
   LM35-like: 10 mV / °C
*/
#define TEMP_SENSOR_MV_PER_C 0.010f

/*=============================
  Hardware Abstraction Layer
  Replace these with MCU-specific code
=============================*/
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(uint32_t baudrate);
uint16_t ADC_ReadChannel(uint8_t channel);
void UART_SendString(const char *str);
void Delay_ms(uint32_t ms);

/*=============================
  Globals
=============================*/
static float movingAvgBuffer[MOVING_AVG_SIZE] = {0};
static uint8_t movingAvgIndex = 0;
static bool movingAvgFilled = false;

/*=============================
  Utility Functions
=============================*/
float adc_to_voltage(uint16_t adcValue)
{
    return ((float)adcValue / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

float voltage_to_temperature(float voltage)
{
    return voltage / TEMP_SENSOR_MV_PER_C;
}

uint16_t read_sensor_average(uint8_t channel, uint8_t samples)
{
    uint32_t sum = 0;

    for (uint8_t i = 0; i < samples; i++)
    {
        sum += ADC_ReadChannel(channel);
    }

    return (uint16_t)(sum / samples);
}

float moving_average_filter(float newValue)
{
    movingAvgBuffer[movingAvgIndex] = newValue;
    movingAvgIndex++;

    if (movingAvgIndex >= MOVING_AVG_SIZE)
    {
        movingAvgIndex = 0;
        movingAvgFilled = true;
    }

    uint8_t count = movingAvgFilled ? MOVING_AVG_SIZE : movingAvgIndex;
    float sum = 0.0f;

    for (uint8_t i = 0; i < count; i++)
    {
        sum += movingAvgBuffer[i];
    }

    if (count == 0)
        return newValue;

    return sum / count;
}

/*=============================
  Sensor Processing
=============================*/
typedef struct
{
    uint16_t rawAdc;
    float voltage;
    float filteredVoltage;
    float temperatureC;
} SensorData;

void process_sensor_data(SensorData *data, uint8_t adcChannel)
{
    data->rawAdc = read_sensor_average(adcChannel, SENSOR_SAMPLES);
    data->voltage = adc_to_voltage(data->rawAdc);
    data->filteredVoltage = moving_average_filter(data->voltage);
    data->temperatureC = voltage_to_temperature(data->filteredVoltage);
}

/*=============================
  Main Application
=============================*/
int main(void)
{
    char txBuffer[UART_TX_BUFFER_SIZE];
    SensorData sensor;

    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    UART_Init(115200);

    UART_SendString("Sensor firmware started\r\n");

    while (1)
