# Example: STM32 HAL version

If you want something closer to production, here is a simplified STM32-style example:

```c
#include "main.h"

extern ADC_HandleTypeDef hadc1;

#define ADC_MAX_COUNTS      4095.0f
#define ADC_REF_VOLTAGE     3.3f
#define FILTER_WINDOW_SIZE  8

static uint16_t filter_buffer[FILTER_WINDOW_SIZE];
static uint32_t filter_sum = 0;
static uint8_t filter_index = 0;
static uint8_t filter_full = 0;

float moving_average(uint16_t sample)
{
    if (!filter_full && filter_index < FILTER_WINDOW_SIZE)
    {
        filter_buffer[filter_index++] = sample;
        filter_sum += sample;

        if (filter_index == FILTER_WINDOW_SIZE)
        {
            filter_index = 0;
            filter_full = 1;
        }

        return (float)filter_sum / (filter_full ? FILTER_WINDOW_SIZE : filter_index);
    }

    filter_sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = sample;
    filter_sum += sample;

    filter_index = (filter_index + 1) % FILTER_WINDOW_SIZE;

    return (float)filter_sum / FILTER_WINDOW_SIZE;
}

float read_sensor_voltage(void)
{
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);

    uint16_t raw = HAL_ADC_GetValue(&hadc1);
    float filtered = moving_average(raw);

    return (filtered / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_ADC1_Init();

    while (1)
    {
        float voltage = read_sensor_voltage();

        if (voltage > 2.5f)
        {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);
        }
        else
        {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET);
        }

        HAL_Delay(100);
    }
}
```

