#include <stdint.h>
#include <stdbool.h>

/*=========================
  Configuration
=========================*/
#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f

#define SAMPLE_BUFFER_SIZE      16
#define SENSOR_HIGH_THRESHOLD   2.50f
#define SENSOR_LOW_THRESHOLD    0.50f

#define SYSTEM_TICK_MS          10
#define SENSOR_SAMPLE_PERIOD_MS 100

/*=========================
  Hardware Abstraction
  Replace these with MCU-specific code
=========================*/
void MCU_Init(void);
void ADC_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void GPIO_Init(void);
void LED_Set(bool on);
void UART_Init(void);
void UART_SendString(const char *str);
void Timer_Init(void);

/*=========================
  Sensor Data Structure
=========================*/
typedef struct
{
    uint16_t raw;
    float voltage;
    float filteredVoltage;
    float engineeredValue;
    bool alarmHigh;
    bool alarmLow;
} SensorData_t;

/*=========================
  Globals
=========================*/
static volatile uint32_t g_systemTickMs = 0;
static SensorData_t g_sensorData = {0};

static float g_sampleBuffer[SAMPLE_BUFFER_SIZE] = {0};
static uint8_t g_sampleIndex = 0;
static bool g_bufferFilled = false;

/*=========================
  Utility Functions
=========================*/
float ConvertRawToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

float ApplyMovingAverage(float newSample)
{
    g_sampleBuffer[g_sampleIndex] = newSample;
    g_sampleIndex++;

    if (g_sampleIndex >= SAMPLE_BUFFER_SIZE)
    {
        g_sampleIndex = 0;
        g_bufferFilled = true;
    }

    uint8_t count = g_bufferFilled ? SAMPLE_BUFFER_SIZE : g_sampleIndex;
    if (count == 0)
    {
        return newSample;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_sampleBuffer[i];
    }

    return sum / count;
}

/* Example conversion:
   Assume sensor voltage maps 0.5V to 0 units
   and 2.5V to 100 units.
*/
float ConvertVoltageToEngineeringUnits(float voltage)
{
    const float vMin = 0.5f;
    const float vMax = 2.5f;
    const float outMin = 0.0f;
    const float outMax = 100.0f;

    if (voltage <= vMin)
        return outMin;
    if (voltage >= vMax)
        return outMax;

    return ((voltage - vMin) * (outMax - outMin) / (vMax - vMin)) + outMin;
}

void ProcessSensorData(SensorData_t *data)
{
    data->voltage = ConvertRawToVoltage(data->raw);
    data->filteredVoltage = ApplyMovingAverage(data->voltage);
    data->engineeredValue = ConvertVoltageToEngineeringUnits(data->filteredVoltage);

    data->alarmHigh = (data->filteredVoltage > SENSOR_HIGH_THRESHOLD);
    data->alarmLow  = (data->filteredVoltage < SENSOR_LOW_THRESHOLD);

    if (data->alarmHigh || data->alarmLow)
    {
        LED_Set(true);
    }
    else
    {
        LED_Set(false);
    }
}

/*=========================
  Periodic Task
=========================*/
void SensorTask(void)
{
    g_sensorData.raw = ADC_ReadChannel(0);
    ProcessSensorData(&g_sensorData);
}

/*=========================
  Simple Delay/Timing
=========================*/
uint32_t GetSystemTick(void)
{
    return g_systemTickMs;
}

bool TimeElapsed(uint32_t start, uint32_t period)
{
    return ((GetSystemTick() - start) >= period);
}

/*=========================
