  Filter functions
=========================================================*/
void Filter_Init(MovingAverageFilter_t *filter)
{
    uint8_t i;
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (i = 0; i < MOVING_AVG_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < MOVING_AVG_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= MOVING_AVG_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / filter->count;
}

/*=========================================================
  Conversion functions
=========================================================*/
float ADC_CountsToVoltage(uint16_t counts)
{
    return ((float)counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

float VoltageToTemperatureC(float voltage)
{
    return (voltage - SENSOR_OFFSET_VOLTAGE) / SENSOR_SCALE_V_PER_C;
}

/*=========================================================
  Sensor processing
=========================================================*/
void Sensor_ReadAndProcess(SensorData_t *data, MovingAverageFilter_t *filter)
{
    data->raw = ADC_ReadRaw();
    data->voltage = ADC_CountsToVoltage(data->raw);
    data->temperatureC = VoltageToTemperatureC(data->voltage);
    data->filteredTemperatureC = Filter_Update(filter, data->temperatureC);
}

void Sensor_CheckAlarms(SensorData_t *data)
{
    data->alarmHigh = (data->filteredTemperatureC > TEMP_HIGH_THRESHOLD_C);
    data->alarmLow  = (data->filteredTemperatureC < TEMP_LOW_THRESHOLD_C);
}

/*=========================================================
  Reporting
=========================================================*/
void ReportSensorData(const SensorData_t *data)
{
