## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* =========================
   Configuration
   ========================= */
#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLE_COUNT     16
#define LPF_ALPHA               0.2f

/* Example conversion:
   Suppose sensor outputs:
   0.5V = 0 units
   2.5V = 100 units
*/
#define SENSOR_VOLTAGE_OFFSET   0.5f
#define SENSOR_VOLTAGE_SPAN     2.0f
#define SENSOR_UNIT_SPAN        100.0f

/* =========================
   Mock hardware interface
   Replace these with MCU HAL functions
   ========================= */
void SystemClock_Config(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(void);
uint16_t ADC_ReadRaw(void);
void Delay_ms(uint32_t ms);
void UART_SendString(const char *str);

/* =========================
   Sensor data structure
   ========================= */
typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    float value_units;
    bool valid;
} SensorData_t;

/* =========================
   Global sensor state
   ========================= */
static SensorData_t g_sensor;

/* =========================
   Utility functions
   ========================= */

/* Average multiple ADC samples to reduce noise */
static uint16_t Sensor_ReadAveragedRaw(void)
{
    uint32_t sum = 0;

    for (uint32_t i = 0; i < SENSOR_SAMPLE_COUNT; i++)
    {
        sum += ADC_ReadRaw();
    }

    return (uint16_t)(sum / SENSOR_SAMPLE_COUNT);
}

/* Convert raw ADC counts to voltage */
static float Sensor_RawToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

/* Simple first-order low-pass filter */
static float LowPassFilter(float input, float prev_output, float alpha)
{
    return prev_output + alpha * (input - prev_output);
}

/* Convert voltage to engineering units */
static float Sensor_VoltageToUnits(float voltage)
{
    float adjusted = voltage - SENSOR_VOLTAGE_OFFSET;

    if (adjusted < 0.0f)
        adjusted = 0.0f;

    if (adjusted > SENSOR_VOLTAGE_SPAN)
        adjusted = SENSOR_VOLTAGE_SPAN;

    return (adjusted / SENSOR_VOLTAGE_SPAN) * SENSOR_UNIT_SPAN;
}

/* Validate sensor reading */
static bool Sensor_Validate(float voltage)
{
    if (voltage < 0.0f || voltage > ADC_REF_VOLTAGE)
        return false;

    return true;
}

/* Main sensor processing function */
static void Sensor_Update(SensorData_t *sensor)
{
    uint16_t raw = Sensor_ReadAveragedRaw();
    float voltage = Sensor_RawToVoltage(raw);

    sensor->raw = raw;
    sensor->voltage = voltage;
    sensor->valid = Sensor_Validate(voltage);

    if (!sensor->valid)
    {
        sensor->value_units = 0.0f;
        return;
    }

    /* Initialize filter on first valid sample */
    static bool filter_initialized = false;
    if (!filter_initialized)
    {
        sensor->filtered_voltage = voltage;
        filter_initialized = true;
    }
    else
    {
        sensor->filtered_voltage = LowPassFilter(
            voltage,
            sensor->filtered_voltage,
            LPF_ALPHA
        );
    }

    sensor->value_units = Sensor_VoltageToUnits(sensor->filtered_voltage);
}

/* Optional: format sensor data for debug output */
static void Sensor_FormatString(const SensorData_t *sensor, char *buffer, uint32_t len)
{
    if (!sensor->valid)
    {
        snprintf(buffer, len, "Sensor invalid\r\n");
        return;
    }

    snprintf(buffer, len,
             "RAW=%u, V=%.3f, FV=%.3f, UNITS=%.2f\r\n",
             sensor->raw,
             sensor->voltage,
             sensor->filtered_voltage,
             sensor->value_units);
}

/* =========================
   Main
   ========================= */
int main(void)
{
    char msg[128];

    SystemClock_Config();
    GPIO_Init();
    ADC_Init();
    UART_Init();

    memset(&g_sensor, 0, sizeof(g_sensor));

    while (1)
    {
        Sensor_Update(&g_sensor);

        Sensor_FormatString(&g_sensor, msg, sizeof(msg));
        UART_SendString(msg);

        Delay_ms(100);
    }
}
