bool I2C_ReadTempRegister(uint8_t dev_addr, uint8_t reg, uint8_t *data, uint8_t len);

static bool TempSensor_ReadCelsius(float *temp_c)
{
    uint8_t data[2];

    if (!I2C_ReadTempRegister(0x48, 0x00, data, 2))
        return false;

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);

    *temp_c = raw * 0.0078f; /* Example scale factor */
    return true;
}
