{
    uint16_t raw_adc[SENSOR_CH_COUNT];
    float voltage[SENSOR_CH_COUNT];
    float filtered_voltage[SENSOR_CH_COUNT];

    float temperature_c;
    float pressure_kpa;
    float light_percent;

    bool temp_alarm_high;
    bool temp_alarm_low;
    bool pressure_alarm_high;
    bool pressure_alarm_low;
} sensor_data_t;

