uint16_t ADC_ReadChannel(sensor_channel_t ch)
{
    /* Replace with actual ADC conversion code */
    static uint16_t fake_values[SENSOR_CH_COUNT] = {2000, 2500, 1500};

    switch (ch)
    {
        case SENSOR_CH_TEMP:
            fake_values[ch] += 3;
            break;
        case SENSOR_CH_PRESSURE:
            fake_values[ch] += 2;
            break;
        case SENSOR_CH_LIGHT:
            fake_values[ch] += 1;
            break;
        default:
            break;
    }

    return fake_values[ch] % 4096;
}

/* Optional debug output stub */
