{
    (void)str;
    /* Replace with UART transmit function */
}

/* =========================
   Utility functions
   ========================= */

static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float low_pass_filter(float input, float prev_output, float alpha)
{
    return alpha * input + (1.0f - alpha) * prev_output;
}

/* Example conversion functions
   Adjust based on your real sensor transfer functions.
*/

/* Example: TMP36-like temperature sensor
   Voltage = 0.5V + 10mV/°C
   Temp(°C) = (V - 0.5) * 100
*/
static float voltage_to_temperature_c(float voltage)
{
    return (voltage - 0.5f) * 100.0f;
}

/* Example: pressure sensor 0.5V to 4.5V = 0 to 100 kPa,
   but constrained to 3.3V ADC, so this is just illustrative.
*/
static float voltage_to_pressure_kpa(float voltage)
{
    float pressure = ((voltage - 0.5f) / 4.0f) * 100.0f;

    if (pressure < 0.0f) pressure = 0.0f;
    if (pressure > 100.0f) pressure = 100.0f;

    return pressure;
}

/* Example: light sensor mapped 0V to 3.3V => 0 to 100% */
static float voltage_to_light_percent(float voltage)
{
    float percent = (voltage / ADC_REF_VOLTAGE) * 100.0f;

    if (percent < 0.0f) percent = 0.0f;
    if (percent > 100.0f) percent = 100.0f;

    return percent;
}

/* =========================
   Sensor processing
   ========================= */

static uint16_t sensor_read_averaged(sensor_channel_t ch)
{
    uint32_t sum = 0;

    for (uint8_t i = 0; i < NUM_SAMPLES_AVG; i++)
    {
        sum += ADC_ReadChannel(ch);
    }

    return (uint16_t)(sum / NUM_SAMPLES_AVG);
}

static void sensor_update_raw_and_voltage(void)
{
    for (int ch = 0; ch < SENSOR_CH_COUNT; ch++)
    {
        g_sensor_data.raw_adc[ch] = sensor_read_averaged((sensor_channel_t)ch);
        g_sensor_data.voltage[ch] = adc_to_voltage(g_sensor_data.raw_adc[ch]);

        g_sensor_data.filtered_voltage[ch] = low_pass_filter(
            g_sensor_data.voltage[ch],
            g_sensor_data.filtered_voltage[ch],
            SENSOR_FILTER_ALPHA
        );
    }
}

static void sensor_compute_engineering_units(void)
{
    g_sensor_data.temperature_c = voltage_to_temperature_c(
        g_sensor_data.filtered_voltage[SENSOR_CH_TEMP]);

    g_sensor_data.pressure_kpa = voltage_to_pressure_kpa(
        g_sensor_data.filtered_voltage[SENSOR_CH_PRESSURE]);

    g_sensor_data.light_percent = voltage_to_light_percent(
        g_sensor_data.filtered_voltage[SENSOR_CH_LIGHT]);
