    g_sensor_data.temp_alarm_low =
        (g_sensor_data.temperature_c < TEMP_LOW_THRESHOLD_C);

    g_sensor_data.pressure_alarm_high =
        (g_sensor_data.pressure_kpa > PRESSURE_HIGH_THRESHOLD);

    g_sensor_data.pressure_alarm_low =
        (g_sensor_data.pressure_kpa < PRESSURE_LOW_THRESHOLD);
}

void Sensors_Init(void)
{
