#define TEMP_HIGH_ON   60.0f
#define TEMP_HIGH_OFF  58.0f

static void sensor_check_temp_alarm_hysteresis(void)
{
    if (!g_sensor_data.temp_alarm_high && g_sensor_data.temperature_c >= TEMP_HIGH_ON)
