- applies a moving average
- converts to engineering units
- detects threshold alarms

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

#define ADC_MAX             4095.0f
#define VREF                3.3f
#define FILTER_WINDOW       16
#define SENSOR_SCALE        100.0f   // example: volts -> units
#define ALARM_THRESHOLD     180.0f

static uint16_t sample_buffer[FILTER_WINDOW];
static uint32_t sample_sum = 0;
static uint8_t sample_index = 0;
static bool buffer_full = false;

static void adc_init(void);
static uint16_t adc_read_raw(void);
static void uart_init(void);
static void uart_print(const char *msg);
static void delay_ms(uint32_t ms);

static float raw_to_voltage(uint16_t raw) {
    return (raw / ADC_MAX) * VREF;
}

static float voltage_to_units(float voltage) {
    return voltage * SENSOR_SCALE;
}

static float moving_average_update(uint16_t new_sample) {
    sample_sum -= sample_buffer[sample_index];
    sample_buffer[sample_index] = new_sample;
    sample_sum += new_sample;

    sample_index++;
    if (sample_index >= FILTER_WINDOW) {
        sample_index = 0;
        buffer_full = true;
    }

    uint8_t count = buffer_full ? FILTER_WINDOW : sample_index;
    if (count == 0) count = 1;

    return (float)sample_sum / count;
}

int main(void) {
    adc_init();
    uart_init();

    char msg[128];

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        sample_buffer[i] = 0;
    }

    while (1) {
        uint16_t raw = adc_read_raw();
        float filtered_raw = moving_average_update(raw);
        float voltage = raw_to_voltage((uint16_t)filtered_raw);
        float units = voltage_to_units(voltage);

        bool alarm = (units > ALARM_THRESHOLD);

        snprintf(msg, sizeof(msg),
                 "raw=%u filtered=%.2f voltage=%.3f units=%.2f alarm=%s\r\n",
                 raw, filtered_raw, voltage, units, alarm ? "ON" : "OFF");
        uart_print(msg);

        delay_ms(100);
    }

    return 0;
}

