## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

/* =========================
   Hardware abstraction layer
   Replace these with MCU SDK functions
   ========================= */

bool HAL_I2C_Write(uint8_t devAddr, uint8_t regAddr, const uint8_t *data, uint16_t len);
bool HAL_I2C_Read(uint8_t devAddr, uint8_t regAddr, uint8_t *data, uint16_t len);
void HAL_UART_Print(const char *msg);
uint32_t HAL_GetTickMs(void);
void HAL_DelayMs(uint32_t ms);

/* =========================
   Sensor definitions
   Example register map
   ========================= */

#define SENSOR_I2C_ADDR         0x1D

#define REG_WHO_AM_I            0x00
#define REG_CTRL1               0x10
#define REG_CTRL2               0x11
#define REG_TEMP_MSB            0x20
#define REG_TEMP_LSB            0x21
#define REG_ACCEL_X_MSB         0x22
#define REG_ACCEL_X_LSB         0x23
#define REG_ACCEL_Y_MSB         0x24
#define REG_ACCEL_Y_LSB         0x25
#define REG_ACCEL_Z_MSB         0x26
#define REG_ACCEL_Z_LSB         0x27

#define WHO_AM_I_EXPECTED       0x42

/* =========================
   Configuration
   ========================= */

#define SAMPLE_PERIOD_MS        20      // 50 Hz
#define FILTER_WINDOW_SIZE      8
#define CALIBRATION_SAMPLES     100

/* =========================
   Data structures
   ========================= */

typedef struct
{
    int16_t raw_x;
    int16_t raw_y;
    int16_t raw_z;
    int16_t raw_temp;

    float accel_x_g;
    float accel_y_g;
    float accel_z_g;
    float temp_c;

    float accel_mag_g;
} SensorData;

typedef struct
{
    float x_offset;
    float y_offset;
    float z_offset;
    float temp_offset;
    bool calibrated;
} SensorCalibration;

typedef struct
{
    float x_buffer[FILTER_WINDOW_SIZE];
    float y_buffer[FILTER_WINDOW_SIZE];
    float z_buffer[FILTER_WINDOW_SIZE];
    float t_buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

/* =========================
   Globals
   ========================= */

static SensorCalibration g_cal = {0};
static MovingAverageFilter g_filter = {0};

/* =========================
   Utility functions
   ========================= */

static int16_t combine_bytes(uint8_t msb, uint8_t lsb)
{
    return (int16_t)((msb << 8) | lsb);
}

static float moving_average_update(float *buffer, uint8_t *index, uint8_t *count, float sample)
{
    buffer[*index] = sample;
    *index = (uint8_t)((*index + 1) % FILTER_WINDOW_SIZE);

    if (*count < FILTER_WINDOW_SIZE)
    {
        (*count)++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < *count; i++)
    {
        sum += buffer[i];
    }

    return sum / (float)(*count);
}

static void filter_reset(MovingAverageFilter *f)
{
    memset(f, 0, sizeof(MovingAverageFilter));
}

/* =========================
   Sensor low-level functions
   ========================= */

static bool sensor_write_reg(uint8_t reg, uint8_t value)
{
    return HAL_I2C_Write(SENSOR_I2C_ADDR, reg, &value, 1);
}

static bool sensor_read_reg(uint8_t reg, uint8_t *value)
{
    return HAL_I2C_Read(SENSOR_I2C_ADDR, reg, value, 1);
}

static bool sensor_read_multi(uint8_t start_reg, uint8_t *buf, uint16_t len)
{
    return HAL_I2C_Read(SENSOR_I2C_ADDR, start_reg, buf, len);
}

/* =========================
   Sensor driver
   ========================= */

static bool sensor_init(void)
{
    uint8_t whoami = 0;

    if (!sensor_read_reg(REG_WHO_AM_I, &whoami))
    {
        HAL_UART_Print("Sensor WHO_AM_I read failed\r\n");
        return false;
    }

    if (whoami != WHO_AM_I_EXPECTED)
    {
        HAL_UART_Print("Sensor WHO_AM_I mismatch\r\n");
        return false;
    }

    // Example configuration:
    // CTRL1: enable accel, 100 Hz
    // CTRL2: ±2g full scale, normal mode
    if (!sensor_write_reg(REG_CTRL1, 0x57))
    {
        HAL_UART_Print("Sensor CTRL1 write failed\r\n");
        return false;
    }

    if (!sensor_write_reg(REG_CTRL2, 0x00))
    {
        HAL_UART_Print("Sensor CTRL2 write failed\r\n");
        return false;
    }

    HAL_UART_Print("Sensor initialized\r\n");
    return true;
}

static bool sensor_read_raw(SensorData *data)
{
    uint8_t buf[8];

    if (!sensor_read_multi(REG_TEMP_MSB, buf, sizeof(buf)))
    {
        return false;
    }

    data->raw_temp = combine_bytes(buf[0], buf[1]);
    data->raw_x    = combine_bytes(buf[2], buf[3]);
    data->raw_y    = combine_bytes(buf[4], buf[5]);
    data->raw_z    = combine_bytes(buf[6], buf[7]);

    return true;
}

/* =========================
   Conversion and processing
   Adjust scale factors to your sensor datasheet
   ========================= */

static void sensor_convert(SensorData *data)
{
    // Example conversion factors
    // Assume accel raw LSB = 16384 counts/g
    // Assume temp raw LSB = 100 counts/°C, offset = 25°C at raw = 0

    data->accel_x_g = ((float)data->raw_x / 16384.0f) - g_cal.x_offset;
    data->accel_y_g = ((float)data->raw_y / 16384.0f) - g_cal.y_offset;
    data->accel_z_g = ((float)data->raw_z / 16384.0f) - g_cal.z_offset;
    data->temp_c    = (25.0f + ((float)data->raw_temp / 100.0f)) - g_cal.temp_offset;
}

static void sensor_filter(SensorData *data)
{
    static uint8_t idx_x = 0, cnt_x = 0;
    static uint8_t idx_y = 0, cnt_y = 0;
    static uint8_t idx_z = 0, cnt_z = 0;
    static uint8_t idx_t = 0, cnt_t = 0;

    data->accel_x_g = moving_average_update(g_filter.x_buffer, &idx_x, &cnt_x, data->accel_x_g);
    data->accel_y_g = moving_average_update(g_filter.y_buffer, &idx_y, &cnt_y, data->accel_y_g);
    data->accel_z_g = moving_average_update(g_filter.z_buffer, &idx_z, &cnt_z, data->accel_z_g);
    data->temp_c    = moving_average_update(g_filter.t_buffer, &idx_t, &cnt_t, data->temp_c);
}

static void sensor_compute_metrics(SensorData *data)
{
    data->accel_mag_g = sqrtf(
        data->accel_x_g * data->accel_x_g +
        data->accel_y_g * data->accel_y_g +
        data->accel_z_g * data->accel_z_g
    );
}

static bool sensor_calibrate(void)
{
    HAL_UART_Print("Calibration started...\r\n");

    float sum_x = 0.0f;
    float sum_y = 0.0f;
    float sum_z = 0.0f;
    float sum_t = 0.0f;

    SensorData sample;

    for (uint32_t i = 0; i < CALIBRATION_SAMPLES; i++)
    {
        if (!sensor_read_raw(&sample))
        {
            HAL_UART_Print("Calibration read failed\r\n");
            return false;
        }

        sum_x += (float)sample.raw_x / 16384.0f;
        sum_y += (float)sample.raw_y / 16384.0f;
        sum_z += (float)sample.raw_z / 16384.0f;
        sum_t += 25.0f + ((float)sample.raw_temp / 100.0f);

        HAL_DelayMs(10);
    }

    g_cal.x_offset = sum_x / CALIBRATION_SAMPLES;
    g_cal.y_offset = sum_y / CALIBRATION_SAMPLES;
    g_cal.z_offset = (sum_z / CALIBRATION_SAMPLES) - 1.0f; // assume Z sees +1g at rest
    g_cal.temp_offset = (sum_t / CALIBRATION_SAMPLES) - 25.0f;
    g_cal.calibrated = true;

    HAL_UART_Print("Calibration complete\r\n");
    return true;
}

/* =========================
   Application logic
   ========================= */

static void print_sensor_data(const SensorData *data)
{
    char msg[160];
    snprintf(msg, sizeof(msg),
             "AX=%.3f g AY=%.3f g AZ=%.3f g | MAG=%.3f g | T=%.2f C\r\n",
             data->accel_x_g,
             data->accel_y_g,
             data->accel_z_g,
             data->accel_mag_g,
             data->temp_c);
    HAL_UART_Print(msg);
}

int main(void)
{
    HAL_UART_Print("System boot\r\n");

    filter_reset(&g_filter);

    if (!sensor_init())
    {
        HAL_UART_Print("Fatal: sensor init failed\r\n");
        while (1)
        {
            HAL_DelayMs(1000);
        }
    }

    if (!sensor_calibrate())
    {
        HAL_UART_Print("Fatal: calibration failed\r\n");
        while (1)
        {
            HAL_DelayMs(1000);
        }
    }

    uint32_t last_sample_time = 0;
    SensorData data;

    while (1)
    {
        uint32_t now = HAL_GetTickMs();

        if ((now - last_sample_time) >= SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;

            if (sensor_read_raw(&data))
            {
                sensor_convert(&data);
                sensor_filter(&data);
                sensor_compute_metrics(&data);
                print_sensor_data(&data);
            }
            else
            {
                HAL_UART_Print("Sensor read error\r\n");
            }
        }

        // Other tasks can run here:
        // - communication
        // - watchdog refresh
        // - control outputs
        // - low-power handling
    }

    return 0;
}
