# Example firmware in C

```c
/*
 * Generic Sensor Firmware Example
 *
 * Features:
 * - Periodic ADC sampling
 * - Moving average filtering
 * - Conversion to voltage / temperature
 * - Threshold alarm detection
 * - Simple modular structure
 *
 * Replace hardware-specific functions with your MCU SDK/HAL calls.
 */

#include <stdint.h>
#include <stdbool.h>

/*==========================================================
 * Configuration
 *==========================================================*/
#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SAMPLE_PERIOD_MS        10
#define FILTER_WINDOW_SIZE      16

#define TEMP_SENSOR_SCALE       100.0f      // Example: 10 mV/°C => 100 °C/V
#define TEMP_SENSOR_OFFSET      0.5f        // Example offset voltage

#define TEMP_HIGH_THRESHOLD_C   60.0f
#define TEMP_LOW_THRESHOLD_C    0.0f

/*==========================================================
 * Type Definitions
 *==========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float temperature_c;
    float filtered_temperature_c;
    bool alarm_high;
    bool alarm_low;
} sensor_data_t;

typedef struct
{
    float buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} moving_average_filter_t;

/*==========================================================
 * Global Variables
 *==========================================================*/
static volatile uint32_t g_system_tick_ms = 0;
static sensor_data_t g_sensor_data;
static moving_average_filter_t g_temp_filter;

/*==========================================================
 * Hardware Abstraction Prototypes
 *==========================================================*/
void system_init(void);
void gpio_init(void);
void adc_init(void);
void timer_init(void);
uint16_t adc_read_channel(uint8_t channel);
void alarm_output_set(bool state);
void debug_uart_send(const char *msg);

/*==========================================================
 * Utility Functions
 *==========================================================*/
static void filter_init(moving_average_filter_t *filter)
{
    uint8_t i;
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float filter_update(moving_average_filter_t *filter, float sample)
{
    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= FILTER_WINDOW_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float voltage_to_temperature(float voltage)
{
    /* Example linear temperature sensor conversion:
     * temperature = (voltage - offset) * scale
     * For LM35/TMP36-like sensors, adjust constants as needed.
     */
    return (voltage - TEMP_SENSOR_OFFSET) * TEMP_SENSOR_SCALE;
}

/*==========================================================
 * Sensor Processing
 *==========================================================*/
static void sensor_read_and_process(void)
{
    uint16_t raw;
    float voltage;
    float temperature;
    float filtered_temperature;

    raw = adc_read_channel(0);
    voltage = adc_to_voltage(raw);
    temperature = voltage_to_temperature(voltage);
    filtered_temperature = filter_update(&g_temp_filter, temperature);

    g_sensor_data.raw_adc = raw;
    g_sensor_data.voltage = voltage;
    g_sensor_data.temperature_c = temperature;
    g_sensor_data.filtered_temperature_c = filtered_temperature;

    g_sensor_data.alarm_high = (filtered_temperature > TEMP_HIGH_THRESHOLD_C);
    g_sensor_data.alarm_low  = (filtered_temperature < TEMP_LOW_THRESHOLD_C);

    if (g_sensor_data.alarm_high || g_sensor_data.alarm_low)
    {
        alarm_output_set(true);
    }
    else
    {
        alarm_output_set(false);
    }
}

/*==========================================================
 * Application Logic
 *==========================================================*/
static void app_init(void)
{
    system_init();
    gpio_init();
    adc_init();
    timer_init();
    filter_init(&g_temp_filter);
}

static void app_task_10ms(void)
{
    sensor_read_and_process();
}

