#include <stdint.h>
#include <stdbool.h>

/* =========================
   Configuration
   ========================= */
#define ADC_MAX_COUNTS       4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE      3.3f
#define SENSOR_CHANNEL       0

#define SAMPLE_INTERVAL_MS   10
#define FILTER_SIZE          16

#define TEMP_SCALE_MV_PER_C  10.0f       // Example: LM35 = 10mV/°C
#define OVER_TEMP_THRESHOLD  50.0f       // °C

/* =========================
   Mock hardware interface
   Replace these with MCU-specific drivers
   ========================= */
void System_Init(void);
void ADC_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void GPIO_Init(void);
void LED_Set(bool on);
void Delay_ms(uint32_t ms);
void UART_Init(void);
void UART_SendString(const char *str);

/* =========================
   Sensor processing types
   ========================= */
typedef struct
{
    uint16_t buffer[FILTER_SIZE];
    uint32_t sum;
    uint8_t index;
    bool filled;
} MovingAverageFilter;

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float temperature_c;
    bool over_temp;
} SensorData;

/* =========================
   Filter functions
   ========================= */
void Filter_Init(MovingAverageFilter *filter)
{
    filter->sum = 0;
    filter->index = 0;
    filter->filled = false;

    for (uint8_t i = 0; i < FILTER_SIZE; i++)
    {
        filter->buffer[i] = 0;
    }
}

uint16_t Filter_Update(MovingAverageFilter *filter, uint16_t new_sample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = new_sample;
    filter->sum += new_sample;

    filter->index++;
    if (filter->index >= FILTER_SIZE)
    {
        filter->index = 0;
        filter->filled = true;
    }

    if (filter->filled)
    {
        return (uint16_t)(filter->sum / FILTER_SIZE);
    }
    else
    {
        uint8_t count = filter->index;
        if (count == 0) count = 1;
        return (uint16_t)(filter->sum / count);
    }
}

/* =========================
   Conversion functions
   ========================= */
float ADC_ToVoltage(uint16_t adc_value)
{
    return ((float)adc_value * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

float Voltage_ToTemperatureC(float voltage)
{
    // Example for LM35:
    // 10mV per °C => temperature = mV / 10
    float millivolts = voltage * 1000.0f;
    return millivolts / TEMP_SCALE_MV_PER_C;
}

/* =========================
   Sensor task
   ========================= */
void Sensor_ReadAndProcess(MovingAverageFilter *filter, SensorData *data)
{
    uint16_t raw = ADC_ReadChannel(SENSOR_CHANNEL);
    uint16_t filtered = Filter_Update(filter, raw);

    data->raw_adc = filtered;
    data->voltage = ADC_ToVoltage(filtered);
    data->temperature_c = Voltage_ToTemperatureC(data->voltage);
    data->over_temp = (data->temperature_c > OVER_TEMP_THRESHOLD);
}

/* =========================
   Simple integer/string helpers
   ========================= */
void float_to_string(char *buf, float value)
{
    int whole = (int)value;
    int frac = (int)((value - whole) * 100.0f);
    if (frac < 0) frac = -frac;

    // Very simple formatter for embedded use
    char temp[32];
    int i = 0, j = 0;

    if (whole == 0)
    {
        temp[i++] = '0';
    }
    else
    {
        int n = whole;
        if (n < 0)
        {
            *buf++ = '-';
            n = -n;
        }

        char rev[16];
        int k = 0;
        while (n > 0)
        {
            rev[k++] = '0' + (n % 10);
            n /= 10;
        }
        while (k > 0)
        {
            temp[i++] = rev[--k];
        }
    }

    temp[i++] = '.';
    temp[i++] = '0' + ((frac / 10) % 10);
    temp[i++] = '0' + (frac % 10);
    temp[i] = '\0';

    while (temp[j] != '\0')
    {
        *buf++ = temp[j++];
    }
    *buf = '\0';
}

void SendSensorReport(const SensorData *data)
{
    char msg[128];
    char temp_str[16];
    char volt_str[16];

    float_to_string(temp_str, data->temperature_c);
    float_to_string(volt_str, data->voltage);

    // Minimal embedded-safe formatting by manual assembly
    char *p = msg;

    const char *prefix1 = "ADC=";
    while (*prefix1) *p++ = *prefix1++;

    // raw adc
    {
        uint16_t v = data->raw_adc;
        char rev[8];
        int k = 0;
        if (v == 0)
        {
            *p++ = '0';
        }
        else
        {
            while (v > 0)
            {
                rev[k++] = '0' + (v % 10);
                v /= 10;
            }
            while (k > 0)
            {
                *p++ = rev[--k];
            }
        }
    }

    const char *prefix2 = ", V=";
    while (*prefix2) *p++ = *prefix2++;

    const char *s = volt_str;
    while (*s) *p++ = *s++;

    const char *prefix3 = ", T=";
    while (*prefix3) *p++ = *prefix3++;

    s = temp_str;
    while (*s) *p++ = *s++;

    const char *suffix = " C, Alarm=";
    while (*suffix) *p++ = *suffix++;

    if (data->over_temp)
    {
        *p++ = '1';
    }
    else
    {
        *p++ = '0';
    }

    *p++ = '\r';
    *p++ = '\n';
    *p = '\0';

    UART_SendString(msg);
}

/* =========================
   Main
   ========================= */
int main(void)
{
    System_Init();
    GPIO_Init();
    ADC_Init();
    UART_Init();

    MovingAverageFilter filter;
    SensorData sensor;

    Filter_Init(&filter);

    while (1)
    {
        Sensor_ReadAndProcess(&filter, &sensor);

        if (sensor.over_temp)
        {
            LED_Set(true);
        }
        else
        {
            LED_Set(false);
        }

        SendSensorReport(&sensor);

        Delay_ms(SAMPLE_INTERVAL_MS);
    }

    return 0;
}
