static float ProcessSensorSample(uint16_t newSample)
{
    if (bufferFilled) {
        sampleSum -= sampleBuffer[sampleIndex];
    }

    sampleBuffer[sampleIndex] = newSample;
    sampleSum += newSample;

    sampleIndex++;
    if (sampleIndex >= MOVING_AVG_SIZE) {
