            float voltage = ADC_ToVoltage(latest_adc);
            filtered_voltage = LowPassFilter(voltage, filtered_voltage, FILTER_ALPHA);

            if (filtered_voltage > SENSOR_THRESHOLD_V)
                LED_On();
