#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLE_PERIOD_MS 100
#define FILTER_WINDOW_SIZE      8

#define SENSOR_MIN_VALID_V      0.1f
#define SENSOR_MAX_VALID_V      3.2f

// Example scaling: convert voltage to temperature
// tempC = (voltage - 0.5) * 100
#define SENSOR_OFFSET_V         0.5f
#define SENSOR_SCALE_FACTOR     100.0f

/*=========================================================
 * Mock hardware abstraction layer
 * Replace these with MCU-specific implementations
 *=========================================================*/
void System_Init(void);
void ADC_Init(void);
void UART_Init(void);
void Timer_Init(void);

uint16_t ADC_ReadChannel(uint8_t channel);
uint32_t GetTickMs(void);
void UART_SendString(const char *str);

/*=========================================================
 * Sensor data structure
 *=========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float processed_value;
    bool valid;
    bool alarm_low;
    bool alarm_high;
} SensorData_t;

/*=========================================================
 * Globals
 *=========================================================*/
static SensorData_t g_sensor;

static float g_filter_buffer[FILTER_WINDOW_SIZE] = {0};
static uint8_t g_filter_index = 0;
static bool g_filter_filled = false;

/*=========================================================
 * Utility: Moving average filter
 *=========================================================*/
static float MovingAverageFilter(float new_sample)
{
    g_filter_buffer[g_filter_index] = new_sample;
    g_filter_index++;

    if (g_filter_index >= FILTER_WINDOW_SIZE)
    {
        g_filter_index = 0;
        g_filter_filled = true;
    }

    uint8_t count = g_filter_filled ? FILTER_WINDOW_SIZE : g_filter_index;
    if (count == 0)
        return new_sample;

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_filter_buffer[i];
    }

    return sum / count;
}

/*=========================================================
 * Conversion functions
 *=========================================================*/
static float ADC_ToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float Voltage_ToProcessedValue(float voltage)
{
    // Example: temperature sensor
    return (voltage - SENSOR_OFFSET_V) * SENSOR_SCALE_FACTOR;
}

/*=========================================================
 * Sensor processing
 *=========================================================*/
static void Sensor_ReadAndProcess(void)
{
    g_sensor.raw_adc = ADC_ReadChannel(0);

    g_sensor.voltage = ADC_ToVoltage(g_sensor.raw_adc);
    g_sensor.filtered_voltage = MovingAverageFilter(g_sensor.voltage);

    g_sensor.valid = (g_sensor.filtered_voltage >= SENSOR_MIN_VALID_V) &&
                     (g_sensor.filtered_voltage <= SENSOR_MAX_VALID_V);

    if (g_sensor.valid)
    {
        g_sensor.processed_value = Voltage_ToProcessedValue(g_sensor.filtered_voltage);
    }
    else
    {
        g_sensor.processed_value = 0.0f;
    }

    // Example alarm thresholds for processed value
    g_sensor.alarm_low  = (g_sensor.valid && g_sensor.processed_value < 10.0f);
    g_sensor.alarm_high = (g_sensor.valid && g_sensor.processed_value > 80.0f);
}

