static float low_pass_filter(float input, float previous, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * previous);
}

static uint16_t read_adc_averaged(uint8_t channel, uint8_t sample_count)
{
    uint32_t sum = 0;

    for (uint8_t i = 0; i < sample_count; i++)
    {
        sum += adc_read_channel(channel);
    }

    return (uint16_t)(sum / sample_count);
}

/* Example conversion:
   Assume sensor outputs:
   0.5V = 0°C
   1.5V = 100°C
*/
static float voltage_to_temperature(float voltage)
{
    float temperature = (voltage - 0.5f) * (100.0f / 1.0f);

    if (temperature < -40.0f)
        temperature = -40.0f;
    if (temperature > 125.0f)
        temperature = 125.0f;

    return temperature;
}

static void process_sensor_data(sensor_data_t *data)
{
    data->raw_adc = read_adc_averaged(0, SENSOR_SAMPLE_COUNT);

    data->voltage = ((float)data->raw_adc / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;

    data->filtered_voltage = low_pass_filter(
        data->voltage,
        data->filtered_voltage,
        FILTER_ALPHA
    );

    data->temperature_c = voltage_to_temperature(data->filtered_voltage);

    data->alarm_high = (data->temperature_c > TEMP_THRESHOLD_HIGH);
    data->alarm_low  = (data->temperature_c < TEMP_THRESHOLD_LOW);
}

static void handle_alarms(const sensor_data_t *data)
{
