    int temp_int = (int)(data->temperature_c * 10.0f); // tenths of degree
    int temp_whole = temp_int / 10;
    int temp_frac = temp_int >= 0 ? (temp_int % 10) : -(temp_int % 10);

    int volt_mV = (int)(data->filtered_voltage * 1000.0f);

