    len += int_to_str(data->raw_adc, &msg[len]);

    len += simple_strcpy(&msg[len], " V=");
    len += int_to_str(volt_mV, &msg[len]);
    len += simple_strcpy(&msg[len], "mV T=");
    len += int_to_str(temp_whole, &msg[len]);
    len += simple_strcpy(&msg[len], ".");
    len += int_to_str(temp_frac, &msg[len]);
    len += simple_strcpy(&msg[len], "C AH=");
    len += int_to_str(data->alarm_high ? 1 : 0, &msg[len]);
    len += simple_strcpy(&msg[len], " AL=");
    len += int_to_str(data->alarm_low ? 1 : 0, &msg[len]);
    len += simple_strcpy(&msg[len], "\r\n");

    msg[len] = '\0';

