static int simple_strcpy(char *dst, const char *src)
{
    int i = 0;
    while (src[i] != '\0')
    {
        dst[i] = src[i];
        i++;
    }
    return i;
}

static int int_to_str(int value, char *buf)
{
    char temp[16];
    int i = 0;
    int j = 0;
    int len = 0;
    bool negative = false;

    if (value == 0)
    {
        buf[0] = '0';
        return 1;
    }

    if (value < 0)
    {
        negative = true;
        value = -value;
    }

    while (value > 0)
    {
        temp[i++] = (char)('0' + (value % 10));
        value /= 10;
    }

    if (negative)
    {
        buf[len++] = '-';
    }

    for (j = i - 1; j >= 0; j--)
    {
        buf[len++] = temp[j];
    }

    return len;
}

