```c
#include <stdint.h>
#include <stdbool.h>

#define ADC_MAX             4095.0f
#define VREF                3.3f
#define FILTER_WINDOW       16
#define ALERT_THRESHOLD     2.0f   // engineering units
#define SENSOR_SCALE        100.0f // units per volt
#define SENSOR_OFFSET       0.0f

static uint16_t adc_buffer[FILTER_WINDOW];
static uint32_t adc_sum = 0;
static uint8_t adc_index = 0;
static bool buffer_full = false;

static float filtered_voltage = 0.0f;
static float sensor_value = 0.0f;
static bool alert_flag = false;

// Hardware-specific stubs
void adc_init(void);
uint16_t adc_read(void);
void uart_init(void);
void uart_send_string(const char *s);
void gpio_alert_set(bool on);
void delay_ms(uint32_t ms);

// Initialize filter state
static void sensor_init(void) {
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        adc_buffer[i] = 0;
    }
    adc_sum = 0;
    adc_index = 0;
    buffer_full = false;
}

// Update moving average filter
static float filter_update(uint16_t sample) {
    adc_sum -= adc_buffer[adc_index];
    adc_buffer[adc_index] = sample;
    adc_sum += sample;

    adc_index++;
    if (adc_index >= FILTER_WINDOW) {
        adc_index = 0;
        buffer_full = true;
    }

    uint8_t count = buffer_full ? FILTER_WINDOW : adc_index;
    if (count == 0) count = 1;

    return (float)adc_sum / (float)count;
}

// Convert raw ADC average to voltage
static float adc_to_voltage(float adc_avg) {
    return (adc_avg / ADC_MAX) * VREF;
}

// Convert voltage to sensor engineering units
static float voltage_to_units(float voltage) {
    return (voltage * SENSOR_SCALE) + SENSOR_OFFSET;
}

// Process one sensor sample
static void sensor_process(void) {
    uint16_t raw = adc_read();
    float adc_avg = filter_update(raw);
    filtered_voltage = adc_to_voltage(adc_avg);
    sensor_value = voltage_to_units(filtered_voltage);

    alert_flag = (sensor_value > ALERT_THRESHOLD);
    gpio_alert_set(alert_flag);
}

// Optional simple telemetry formatter
static void send_status(void) {
    char msg[128];
    // Replace with snprintf if available in your toolchain
    // Example placeholder:
    // snprintf(msg, sizeof(msg), "V=%.3f, Value=%.2f, Alert=%d\r\n",
    //          filtered_voltage, sensor_value, alert_flag);
    uart_send_string("Sensor processed\r\n");
}

int main(void) {
    adc_init();
    uart_init();
    sensor_init();

    while (1) {
        sensor_process();
        send_status();
        delay_ms(100);
    }

    return 0;
}
