   Sensor processing
   ========================= */

typedef struct
{
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    bool filled;
} MovingAverageFilter;

static void Filter_Init(MovingAverageFilter *filter)
{
    filter->sum = 0;
    filter->index = 0;
    filter->filled = false;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0;
    }
}

static uint16_t Filter_Update(MovingAverageFilter *filter, uint16_t newSample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = newSample;
    filter->sum += newSample;

    filter->index++;
    if (filter->index >= FILTER_WINDOW_SIZE)
    {
        filter->index = 0;
        filter->filled = true;
    }

    uint8_t divisor = filter->filled ? FILTER_WINDOW_SIZE : filter->index;
    if (divisor == 0)
    {
        return newSample;
    }

    return (uint16_t)(filter->sum / divisor);
}

static float ADC_ToVoltage(uint16_t adcValue)
{
    return ((float)adcValue * ADC_REF_VOLTAGE) / ADC_MAX_COUNT;
}

