   Utility
   ========================= */

static void FloatToString(char *buffer, float value, int decimals)
{
    int whole = (int)value;
    int frac = (int)((value - whole) * 1);
    if (decimals == 2)
        frac = (int)((value - whole) * 100);
    else if (decimals == 3)
        frac = (int)((value - whole) * 1000);

    if (frac < 0)
        frac = -frac;

    if (decimals == 1)
        sprintf(buffer, "%d.%01d", whole, frac);
    else if (decimals == 2)
        sprintf(buffer, "%d.%02d", whole, frac);
    else if (decimals == 3)
        sprintf(buffer, "%d.%03d", whole, frac);
    else
        sprintf(buffer, "%d", whole);
}

/* =========================
   Main application
   ========================= */

