# 2. Example firmware implementation

```c
/*
 * Initial sensor firmware implementation
 *
 * Description:
 * - Reads analog sensor data from ADC
 * - Applies moving average filtering
 * - Converts ADC counts to voltage and engineering units
 * - Detects simple fault conditions
 * - Reports results over UART (stub)
 *
 * Target:
 * - Generic microcontroller
 * - Replace HAL stubs with MCU-specific drivers
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS           4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE          3.3f

#define SENSOR_SAMPLE_PERIOD_MS  100U
#define SENSOR_FILTER_SIZE       8U

/* Example sensor scaling:
 * Suppose the sensor outputs:
 *   0.5V = 0 units
 *   2.5V = 100 units
 */
#define SENSOR_VOLTAGE_MIN       0.5f
#define SENSOR_VOLTAGE_MAX       2.5f
#define SENSOR_UNITS_MIN         0.0f
#define SENSOR_UNITS_MAX         100.0f

/* Fault thresholds */
#define SENSOR_RAW_MIN_VALID     10U
#define SENSOR_RAW_MAX_VALID     4085U

/*=========================================================
 * Type definitions
 *=========================================================*/
typedef enum
{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_OUT_OF_RANGE,
    SENSOR_STATUS_DISCONNECTED,
    SENSOR_STATUS_NOT_INITIALIZED
} sensor_status_t;

typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    float value_units;
    sensor_status_t status;
} sensor_data_t;

typedef struct
{
    bool initialized;
    uint16_t raw_buffer[SENSOR_FILTER_SIZE];
    uint32_t raw_sum;
    uint8_t index;
    uint8_t count;
    sensor_data_t latest;
} sensor_context_t;

/*=========================================================
 * Global state
 *=========================================================*/
static sensor_context_t g_sensor;

/*=========================================================
 * HAL stubs - replace with MCU-specific implementation
 *=========================================================*/
static void hal_init(void);
static uint32_t hal_get_tick_ms(void);
static uint16_t hal_adc_read(uint8_t channel);
static void hal_uart_write(const char *msg);
static void hal_delay_ms(uint32_t ms);

/*=========================================================
 * Utility
 *=========================================================*/
static float clampf(float x, float min, float max)
{
    if (x < min) return min;
    if (x > max) return max;
    return x;
}

/*=========================================================
 * Sensor processing functions
 *=========================================================*/
static void sensor_init(sensor_context_t *ctx)
{
    if (ctx == NULL)
        return;

    ctx->initialized = true;
    ctx->raw_sum = 0;
    ctx->index = 0;
    ctx->count = 0;

    for (uint8_t i = 0; i < SENSOR_FILTER_SIZE; i++)
    {
        ctx->raw_buffer[i] = 0;
    }

    ctx->latest.raw = 0;
    ctx->latest.voltage = 0.0f;
    ctx->latest.filtered_voltage = 0.0f;
    ctx->latest.value_units = 0.0f;
    ctx->latest.status = SENSOR_STATUS_OK;
}

static float sensor_raw_to_voltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float sensor_voltage_to_units(float voltage)
{
    float span_v = SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN;
    float span_units = SENSOR_UNITS_MAX - SENSOR_UNITS_MIN;

    if (span_v <= 0.0f)
        return 0.0f;

    float units = ((voltage - SENSOR_VOLTAGE_MIN) / span_v) * span_units + SENSOR_UNITS_MIN;
    return clampf(units, SENSOR_UNITS_MIN, SENSOR_UNITS_MAX);
}

static sensor_status_t sensor_check_fault(uint16_t raw, float voltage)
{
    (void)voltage;

    if (raw <= SENSOR_RAW_MIN_VALID || raw >= SENSOR_RAW_MAX_VALID)
    {
        return SENSOR_STATUS_DISCONNECTED;
    }

    if (voltage < SENSOR_VOLTAGE_MIN || voltage > SENSOR_VOLTAGE_MAX)
    {
        return SENSOR_STATUS_OUT_OF_RANGE;
    }

    return SENSOR_STATUS_OK;
}

static float sensor_update_filter(sensor_context_t *ctx, uint16_t raw)
{
    if (ctx->count < SENSOR_FILTER_SIZE)
    {
        ctx->raw_buffer[ctx->index] = raw;
        ctx->raw_sum += raw;
        ctx->count++;
    }
    else
    {
        ctx->raw_sum -= ctx->raw_buffer[ctx->index];
        ctx->raw_buffer[ctx->index] = raw;
        ctx->raw_sum += raw;
    }

    ctx->index++;
    if (ctx->index >= SENSOR_FILTER_SIZE)
    {
        ctx->index = 0;
    }

    return (float)ctx->raw_sum / (float)ctx->count;
}

static bool sensor_sample(sensor_context_t *ctx, uint8_t adc_channel)
{
    if ((ctx == NULL) || (!ctx->initialized))
    {
        if (ctx != NULL)
        {
            ctx->latest.status = SENSOR_STATUS_NOT_INITIALIZED;
        }
        return false;
    }

    uint16_t raw = hal_adc_read(adc_channel);
    float voltage = sensor_raw_to_voltage(raw);
    float filtered_raw = sensor_update_filter(ctx, raw);
    float filtered_voltage = sensor_raw_to_voltage((uint16_t)filtered_raw);
    float value_units = sensor_voltage_to_units(filtered_voltage);
    sensor_status_t status = sensor_check_fault(raw, voltage);

    ctx->latest.raw = raw;
    ctx->latest.voltage = voltage;
    ctx->latest.filtered_voltage = filtered_voltage;
    ctx->latest.value_units = value_units;
    ctx->latest.status = status;

    return true;
}

static const char* sensor_status_to_string(sensor_status_t status)
{
    switch (status)
    {
        case SENSOR_STATUS_OK: return "OK";
        case SENSOR_STATUS_OUT_OF_RANGE: return "OUT_OF_RANGE";
        case SENSOR_STATUS_DISCONNECTED: return "DISCONNECTED";
        case SENSOR_STATUS_NOT_INITIALIZED: return "NOT_INITIALIZED";
        default: return "UNKNOWN";
    }
}

/*=========================================================
 * Application
 *=========================================================*/
static void app_init(void)
{
    hal_init();
    sensor_init(&g_sensor);
}

static void app_task(void)
{
    static uint32_t last_sample_time = 0;
    uint32_t now = hal_get_tick_ms();

    if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
    {
        last_sample_time = now;

        if (sensor_sample(&g_sensor, 0))
        {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "raw=%u, V=%.3f, Vf=%.3f, units=%.2f, status=%s\r\n",
                     g_sensor.latest.raw,
                     g_sensor.latest.voltage,
                     g_sensor.latest.filtered_voltage,
                     g_sensor.latest.value_units,
                     sensor_status_to_string(g_sensor.latest.status));
            hal_uart_write(msg);
        }
    }
}

int main(void)
{
    app_init();

    while (1)
    {
        app_task();

        /* Optional low-power wait or short delay */
        hal_delay_ms(1);
    }

    return 0;
}

/*=========================================================
 * HAL stub implementations
 * Replace these with actual MCU SDK/HAL calls
 *=========================================================*/

static void hal_init(void)
{
    /* Initialize clocks, GPIO, ADC, UART, SysTick, etc. */
}

static uint32_t hal_get_tick_ms(void)
{
    /* Replace with system tick counter */
    static uint32_t fake_tick = 0;
    fake_tick += 1;
    return fake_tick;
}

static uint16_t hal_adc_read(uint8_t channel)
{
    (void)channel;

    /* Replace with actual ADC conversion result
     * This stub simulates a changing signal
     */
    static uint16_t simulated = 1800;
    simulated += 17;
    if (simulated > 3000)
    {
        simulated = 1500;
    }
    return simulated;
}

static void hal_uart_write(const char *msg)
{
    /* Replace with UART transmit function */
    printf("%s", msg);
}

static void hal_delay_ms(uint32_t ms)
{
    /* Replace with real delay or low-power wait */
    (void)ms;
}
```

