#define ADC_MAX_VALUE           4095U
#define ADC_REF_MV              3300U
#define SENSOR_SAMPLE_PERIOD_MS 100U
#define FILTER_WINDOW_SIZE      8U

typedef struct
{
    uint16_t raw_adc;
    uint32_t sensor_mv;
    uint32_t filtered_mv;
    bool new_data;
} sensor_data_t;

static sensor_data_t g_sensor_data = {0};

static uint32_t g_filter_buffer[FILTER_WINDOW_SIZE] = {0};
static uint32_t g_filter_sum = 0;
static uint8_t g_filter_index = 0;
static bool g_filter_initialized = false;

static volatile uint32_t g_system_tick_ms = 0;

/* ---- MCU-specific function stubs ---- */
static void clock_init(void);
static void gpio_init(void);
static void adc_init(void);
static void timer_init(void);
