static void sensor_task(void);
static uint32_t adc_to_millivolts(uint16_t adc_value);
static uint32_t moving_average_filter(uint32_t sample);

/* Example SysTick or timer ISR hook */
void systick_handler(void)
{
    g_system_tick_ms++;
}

int main(void)
{
    system_init();

    uint32_t last_sample_time = 0;

    while (1)
    {
        if ((g_system_tick_ms - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = g_system_tick_ms;
            sensor_task();
        }

        /* Optional: low-power wait, communications, control logic, etc. */
    }

    return 0;
}

static void system_init(void)
{
    clock_init();
    gpio_init();
    adc_init();
    timer_init();
}

static void sensor_task(void)
{
    const uint8_t sensor_adc_channel = 0;
    uint16_t raw = adc_read_channel(sensor_adc_channel);
    uint32_t mv = adc_to_millivolts(raw);
    uint32_t filtered = moving_average_filter(mv);

    g_sensor_data.raw_adc = raw;
    g_sensor_data.sensor_mv = mv;
    g_sensor_data.filtered_mv = filtered;
    g_sensor_data.new_data = true;
}

static uint32_t adc_to_millivolts(uint16_t adc_value)
{
    return ((uint32_t)adc_value * ADC_REF_MV) / ADC_MAX_VALUE;
}

static uint32_t moving_average_filter(uint32_t sample)
{
    if (!g_filter_initialized)
    {
        for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
        {
            g_filter_buffer[i] = sample;
            g_filter_sum += sample;
        }
        g_filter_initialized = true;
        return sample;
    }

    g_filter_sum -= g_filter_buffer[g_filter_index];
    g_filter_buffer[g_filter_index] = sample;
    g_filter_sum += sample;

    g_filter_index++;
    if (g_filter_index >= FILTER_WINDOW_SIZE)
    {
        g_filter_index = 0;
    }

    return g_filter_sum / FILTER_WINDOW_SIZE;
}

