#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define SENSOR_SAMPLE_PERIOD_MS     100U
#define FILTER_ALPHA_NUM            1U
#define FILTER_ALPHA_DEN            4U   // alpha = 1/4

#define TEMP_ALERT_THRESHOLD_C      50.0f
#define PRESSURE_ALERT_THRESHOLD_KPA 120.0f

/*=========================================================
 * Hardware abstraction placeholders
 * Replace these with MCU-specific implementations
 *=========================================================*/
static void system_clock_init(void);
static void gpio_init(void);
static void adc_init(void);
static void timer_init(void);
static void uart_init(void);

static uint16_t adc_read_channel(uint8_t channel);
static uint32_t get_millis(void);
static void uart_send_string(const char *str);

/*=========================================================
 * Sensor channels
 *=========================================================*/
typedef enum
{
    ADC_CH_TEMP = 0,
    ADC_CH_PRESSURE = 1
} adc_channel_t;

/*=========================================================
 * Data structures
 *=========================================================*/
typedef struct
{
    uint16_t raw_temp;
    uint16_t raw_pressure;
} sensor_raw_data_t;

typedef struct
{
    float temperature_c;
    float pressure_kpa;
} sensor_processed_data_t;

typedef struct
{
    float temperature_filtered_c;
    float pressure_filtered_kpa;
} sensor_filtered_data_t;

typedef struct
{
    bool temp_alert;
    bool pressure_alert;
} sensor_status_t;

/*=========================================================
 * Global state
 *=========================================================*/
static sensor_raw_data_t g_raw_data;
static sensor_processed_data_t g_processed_data;
static sensor_filtered_data_t g_filtered_data;
static sensor_status_t g_status;

/*=========================================================
 * Utility functions
 *=========================================================*/
static float convert_adc_to_temperature_c(uint16_t adc_value)
{
    // Example conversion:
    // 12-bit ADC (0..4095) maps to 0..100 C
    return ((float)adc_value * 100.0f) / 4095.0f;
}

static float convert_adc_to_pressure_kpa(uint16_t adc_value)
{
    // Example conversion:
    // 12-bit ADC (0..4095) maps to 0..200 kPa
    return ((float)adc_value * 200.0f) / 4095.0f;
}

static float low_pass_filter(float previous, float current)
{
    // filtered = previous + alpha * (current - previous)
    // alpha = FILTER_ALPHA_NUM / FILTER_ALPHA_DEN
    float alpha = (float)FILTER_ALPHA_NUM / (float)FILTER_ALPHA_DEN;
    return previous + alpha * (current - previous);
}

/*=========================================================
 * Sensor processing
 *=========================================================*/
static void sensor_read(sensor_raw_data_t *raw)
{
    if (raw == NULL)
        return;

    raw->raw_temp = adc_read_channel(ADC_CH_TEMP);
    raw->raw_pressure = adc_read_channel(ADC_CH_PRESSURE);
}

static void sensor_process(const sensor_raw_data_t *raw,
                           sensor_processed_data_t *processed)
{
    if ((raw == NULL) || (processed == NULL))
        return;

    processed->temperature_c = convert_adc_to_temperature_c(raw->raw_temp);
    processed->pressure_kpa = convert_adc_to_pressure_kpa(raw->raw_pressure);
}

static void sensor_filter(const sensor_processed_data_t *processed,
                          sensor_filtered_data_t *filtered)
{
    static bool initialized = false;

    if ((processed == NULL) || (filtered == NULL))
        return;

    if (!initialized)
    {
        filtered->temperature_filtered_c = processed->temperature_c;
        filtered->pressure_filtered_kpa = processed->pressure_kpa;
        initialized = true;
    }
    else
    {
        filtered->temperature_filtered_c =
            low_pass_filter(filtered->temperature_filtered_c,
                            processed->temperature_c);

        filtered->pressure_filtered_kpa =
            low_pass_filter(filtered->pressure_filtered_kpa,
                            processed->pressure_kpa);
    }
}

static void sensor_check_alerts(const sensor_filtered_data_t *filtered,
                                sensor_status_t *status)
{
    if ((filtered == NULL) || (status == NULL))
        return;

    status->temp_alert =
        (filtered->temperature_filtered_c > TEMP_ALERT_THRESHOLD_C);

    status->pressure_alert =
        (filtered->pressure_filtered_kpa > PRESSURE_ALERT_THRESHOLD_KPA);
}

/*=========================================================
 * Reporting
 *=========================================================*/
static void report_sensor_data(const sensor_filtered_data_t *filtered,
                               const sensor_status_t *status)
{
    if ((filtered == NULL) || (status == NULL))
        return;

    char buffer[128];

    // Minimal embedded-safe formatting may require snprintf support.
    // Replace if your toolchain lacks float printf support.
    int len = snprintf(buffer, sizeof(buffer),
                       "Temp: %.2f C, Pressure: %.2f kPa, Alerts[T:%d P:%d]\r\n",
                       filtered->temperature_filtered_c,
                       filtered->pressure_filtered_kpa,
                       status->temp_alert,
                       status->pressure_alert);

    if (len > 0)
    {
        uart_send_string(buffer);
    }
}

/*=========================================================
 * Main application task
 *=========================================================*/
static void sensor_task(void)
{
    sensor_read(&g_raw_data);
    sensor_process(&g_raw_data, &g_processed_data);
    sensor_filter(&g_processed_data, &g_filtered_data);
    sensor_check_alerts(&g_filtered_data, &g_status);
    report_sensor_data(&g_filtered_data, &g_status);
}

/*=========================================================
 * Main
 *=========================================================*/
int main(void)
{
    system_clock_init();
    gpio_init();
    adc_init();
    timer_init();
    uart_init();

    memset(&g_raw_data, 0, sizeof(g_raw_data));
    memset(&g_processed_data, 0, sizeof(g_processed_data));
    memset(&g_filtered_data, 0, sizeof(g_filtered_data));
    memset(&g_status, 0, sizeof(g_status));

    uint32_t last_sample_time = 0;

    while (1)
    {
        uint32_t now = get_millis();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;
            sensor_task();
        }

        // Optional: sleep, low-power mode, background tasks, watchdog service
    }

    return 0;
}

