# 2. Example firmware implementation

```c
#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f      // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f

#define SENSOR_SAMPLE_PERIOD_MS 10U
#define SENSOR_FILTER_SIZE      16U

#define SENSOR_MIN_VALID_V      0.1f
#define SENSOR_MAX_VALID_V      3.2f

#define SENSOR_SCALE            100.0f       // Example: volts to engineering units
#define SENSOR_OFFSET           0.0f

/*=========================================================
 * Mock hardware abstraction layer (replace with MCU-specific code)
 *=========================================================*/
static volatile uint32_t g_systemTickMs = 0;

void HAL_Init(void);
void HAL_Clock_Init(void);
void HAL_GPIO_Init(void);
void HAL_ADC_Init(void);
void HAL_Timer_Init(void);
uint16_t HAL_ADC_ReadChannel(uint8_t channel);
void HAL_UART_Init(void);
void HAL_UART_SendString(const char *str);

/*=========================================================
 * Sensor data structure
 *=========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float engineering_value;
    bool fault_open_circuit;
    bool fault_out_of_range;
    bool data_valid;
} SensorData_t;

/*=========================================================
 * Globals
 *=========================================================*/
static SensorData_t g_sensorData;

static float g_filterBuffer[SENSOR_FILTER_SIZE];
static uint8_t g_filterIndex = 0;
static bool g_filterFilled = false;

/*=========================================================
 * Utility functions
 *=========================================================*/
static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float apply_moving_average(float new_sample)
{
    g_filterBuffer[g_filterIndex] = new_sample;
    g_filterIndex++;

    if (g_filterIndex >= SENSOR_FILTER_SIZE)
    {
        g_filterIndex = 0;
        g_filterFilled = true;
    }

    uint8_t count = g_filterFilled ? SENSOR_FILTER_SIZE : g_filterIndex;
    if (count == 0)
    {
        return new_sample;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_filterBuffer[i];
    }

    return sum / (float)count;
}

static float convert_to_engineering_units(float voltage)
{
    return (voltage * SENSOR_SCALE) + SENSOR_OFFSET;
}

/*=========================================================
 * Sensor processing
 *=========================================================*/
static void Sensor_Init(void)
{
    g_sensorData.raw_adc = 0;
    g_sensorData.voltage = 0.0f;
    g_sensorData.filtered_voltage = 0.0f;
    g_sensorData.engineering_value = 0.0f;
    g_sensorData.fault_open_circuit = false;
    g_sensorData.fault_out_of_range = false;
    g_sensorData.data_valid = false;

    for (uint8_t i = 0; i < SENSOR_FILTER_SIZE; i++)
    {
        g_filterBuffer[i] = 0.0f;
    }

    g_filterIndex = 0;
    g_filterFilled = false;
}

static void Sensor_ReadAndProcess(void)
{
    uint16_t raw = HAL_ADC_ReadChannel(0);
    float voltage = adc_to_voltage(raw);
    float filtered = apply_moving_average(voltage);
    float eng = convert_to_engineering_units(filtered);

    g_sensorData.raw_adc = raw;
    g_sensorData.voltage = voltage;
    g_sensorData.filtered_voltage = filtered;
    g_sensorData.engineering_value = eng;

    /* Fault detection */
    g_sensorData.fault_open_circuit = (voltage < SENSOR_MIN_VALID_V);
    g_sensorData.fault_out_of_range = (voltage < SENSOR_MIN_VALID_V) || (voltage > SENSOR_MAX_VALID_V);

    g_sensorData.data_valid = !(g_sensorData.fault_open_circuit || g_sensorData.fault_out_of_range);
}

/*=========================================================
 * Optional reporting
 *=========================================================*/
static void Sensor_Report(void)
{
    char msg[128];

    /* Minimal lightweight formatting alternative recommended for embedded systems.
       Replace snprintf if standard library support is limited. */
    extern int snprintf(char *str, unsigned int size, const char *format, ...);

    snprintf(msg, sizeof(msg),
             "RAW=%u V=%.3f FV=%.3f ENG=%.2f VALID=%d\r\n",
             g_sensorData.raw_adc,
             g_sensorData.voltage,
             g_sensorData.filtered_voltage,
             g_sensorData.engineering_value,
             g_sensorData.data_valid ? 1 : 0);

    HAL_UART_SendString(msg);
}

/*=========================================================
 * Timing
 *=========================================================*/
void SysTick_Handler(void)
{
    g_systemTickMs++;
}

static uint32_t millis(void)
{
    return g_systemTickMs;
}

/*=========================================================
 * Main
 *=========================================================*/
int main(void)
{
    HAL_Init();
    HAL_Clock_Init();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_UART_Init();
    HAL_Timer_Init();

    Sensor_Init();

    uint32_t lastSampleTime = 0;
    uint32_t lastReportTime = 0;

    while (1)
    {
        uint32_t now = millis();

        if ((now - lastSampleTime) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            lastSampleTime = now;
            Sensor_ReadAndProcess();
        }

        if ((now - lastReportTime) >= 500U)
        {
            lastReportTime = now;
            Sensor_Report();
        }

        /* Idle, sleep, or handle other tasks here */
    }

    return 0;
}

/*=========================================================
 * Stub HAL implementations
 * Replace with real MCU-specific drivers
 *=========================================================*/
void HAL_Init(void) {}
void HAL_Clock_Init(void) {}
void HAL_GPIO_Init(void) {}
void HAL_ADC_Init(void) {}
void HAL_Timer_Init(void) {}
void HAL_UART_Init(void) {}

uint16_t HAL_ADC_ReadChannel(uint8_t channel)
{
    (void)channel;

    /* Replace this with actual ADC conversion/read logic */
    static uint16_t dummy = 2000;
    dummy += 10;
    if (dummy > 3000)
    {
        dummy = 1500;
    }
    return dummy;
}

void HAL_UART_SendString(const char *str)
{
    (void)str;
    /* Replace with UART transmit function */
}
