{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float calibrated_value;
    bool fault;
} SensorData_t;

typedef struct
{
    float offset;
    float scale;
} SensorCalibration_t;

/*=========================================================
 * Globals
 *=========================================================*/
static volatile bool g_sample_flag = false;

static SensorData_t g_sensor_data = {0};
static SensorCalibration_t g_sensor_cal = {
    .offset = 0.0f,
    .scale = 1.0f
};

/*=========================================================
 * Function Prototypes
 *=========================================================*/
static void App_Init(void);
static void Sensor_Init(void);
static void Sensor_SampleAndProcess(void);
static float ADC_ToVoltage(uint16_t adc_value);
static float ApplyLowPassFilter(float input, float prev_output, float alpha);
static bool Sensor_CheckFault(float voltage);

/*=========================================================
 * Timer ISR Hook
 * Call this from your actual timer interrupt handler
 *=========================================================*/
void Timer_PeriodElapsedCallback(void)
{
    g_sample_flag = true;
}

/*=========================================================
 * Main
 *=========================================================*/
int main(void)
{
    App_Init();

    while (1)
    {
        if (g_sample_flag)
        {
            g_sample_flag = false;
            Sensor_SampleAndProcess();
        }

        /* Optional: low-power wait or background tasks */
        HAL_DelayMs(1);
    }

    return 0;
}

/*=========================================================
 * Application Initialization
 *=========================================================*/
static void App_Init(void)
{
    HAL_SystemInit();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_Timer_Init();

    Sensor_Init();

    HAL_EnableInterrupts();
}

/*=========================================================
 * Sensor Initialization
 *=========================================================*/
static void Sensor_Init(void)
{
    g_sensor_data.raw_adc = 0;
    g_sensor_data.voltage = 0.0f;
    g_sensor_data.filtered_voltage = 0.0f;
    g_sensor_data.calibrated_value = 0.0f;
    g_sensor_data.fault = false;

    /* Example calibration values */
    g_sensor_cal.offset = 0.05f;
    g_sensor_cal.scale = 100.0f; 
    /* Example:
       calibrated_value = (filtered_voltage - offset) * scale
    */
}

/*=========================================================
 * Sensor Sampling and Processing
 *=========================================================*/
static void Sensor_SampleAndProcess(void)
{
    uint16_t adc_raw;
    float voltage;
    float filtered;
    float calibrated;

    adc_raw = HAL_ADC_ReadChannel(0);
    voltage = ADC_ToVoltage(adc_raw);

    filtered = ApplyLowPassFilter(
        voltage,
        g_sensor_data.filtered_voltage,
        SENSOR_FILTER_ALPHA
    );

    calibrated = (filtered - g_sensor_cal.offset) * g_sensor_cal.scale;

    g_sensor_data.raw_adc = adc_raw;
    g_sensor_data.voltage = voltage;
    g_sensor_data.filtered_voltage = filtered;
    g_sensor_data.calibrated_value = calibrated;
    g_sensor_data.fault = Sensor_CheckFault(voltage);
}

/*=========================================================
 * Utility Functions
 *=========================================================*/
static float ADC_ToVoltage(uint16_t adc_value)
{
    return ((float)adc_value / ADC_MAX_VALUE) * ADC_REF_VOLTAGE;
}

static float ApplyLowPassFilter(float input, float prev_output, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * prev_output);
}

static bool Sensor_CheckFault(float voltage)
{
    if ((voltage < SENSOR_MIN_VALID_V) || (voltage > SENSOR_MAX_VALID_V))
    {
        return true;
    }

    return false;
}
