/*=========================================================
 * Utility Functions
 *=========================================================*/
static float convert_adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float moving_average_filter(float new_sample)
{
    g_analogFilterBuffer[g_analogFilterIndex] = new_sample;
    g_analogFilterIndex++;

    if (g_analogFilterIndex >= ANALOG_FILTER_SIZE)
    {
        g_analogFilterIndex = 0;
        g_analogFilterFilled = true;
    }

    uint8_t count = g_analogFilterFilled ? ANALOG_FILTER_SIZE : g_analogFilterIndex;
    if (count == 0)
    {
        return new_sample;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_analogFilterBuffer[i];
    }

    return sum / (float)count;
}

/* Example scaling:
 * Convert filtered voltage to an engineering unit, e.g. pressure
 * 0.5V -> 0 units
 * 2.5V -> 100 units
 */
static float scale_analog_to_engineering(float voltage)
{
    const float v_min = 0.5f;
    const float v_max = 2.5f;
    const float out_min = 0.0f;
    const float out_max = 100.0f;

    if (voltage <= v_min) return out_min;
    if (voltage >= v_max) return out_max;

    return ((voltage - v_min) * (out_max - out_min) / (v_max - v_min)) + out_min;
}

static bool check_analog_fault(float voltage)
{
    return (voltage < ANALOG_SENSOR_MIN_V) || (voltage > ANALOG_SENSOR_MAX_V);
}

static bool check_temp_fault(float temp_c)
{
    return (temp_c < TEMP_SENSOR_MIN_C) || (temp_c > TEMP_SENSOR_MAX_C);
}

/*=========================================================
 * Sensor Drivers
 *=========================================================*/
static void AnalogSensor_Read(AnalogSensor_t *sensor)
{
    if (sensor == NULL) return;

    sensor->raw_adc = HAL_ADC_ReadChannel(0);
    sensor->voltage = convert_adc_to_voltage(sensor->raw_adc);
    sensor->filtered_voltage = moving_average_filter(sensor->voltage);
    sensor->fault = check_analog_fault(sensor->voltage);
}

/* Example assumes a 2-byte temperature register.
 * Adapt conversion based on your actual sensor datasheet.
 */
static void TempSensor_Read(TempSensor_t *sensor)
{
    if (sensor == NULL) return;

    uint8_t rx[2] = {0};

    if (HAL_I2C_Read(TEMP_SENSOR_I2C_ADDR, TEMP_SENSOR_REG, rx, 2))
    {
        sensor->raw_temp = (int16_t)((rx[0] << 8) | rx[1]);

        /* Example conversion: raw value in 0.01 deg C units */
        sensor->temperature_c = (float)sensor->raw_temp / 100.0f;
        sensor->fault = check_temp_fault(sensor->temperature_c);
    }
    else
    {
        sensor->raw_temp = 0;
        sensor->temperature_c = 0.0f;
        sensor->fault = true;
    }
}

/*=========================================================
 * Processing
 *=========================================================*/
static void ProcessSensorData(const SensorData_t *in, ProcessedData_t *out)
{
    if ((in == NULL) || (out == NULL)) return;

    out->analog_engineering_value = scale_analog_to_engineering(in->analog.filtered_voltage);
    out->temperature_c = in->temp.temperature_c;
    out->system_fault = in->analog.fault || in->temp.fault;
}

/*=========================================================
 * Reporting
 *=========================================================*/
static void ReportData(const ProcessedData_t *data)
{
    if (data == NULL) return;

    char msg[128];

    /* Minimal snprintf replacement may be needed on small MCUs */
    /* If snprintf is available, include stdio.h and use it */
    memset(msg, 0, sizeof(msg));

    /* Simple placeholder formatting */
    HAL_UART_SendString("Processed Data:\r\n");
    HAL_UART_SendString("  Analog Eng Value updated\r\n");
    HAL_UART_SendString("  Temperature updated\r\n");
    HAL_UART_SendString(data->system_fault ? "  Fault: YES\r\n" : "  Fault: NO\r\n");
}

/*=========================================================
 * Scheduler Helpers
 *=========================================================*/
static bool IsTimeElapsed(uint32_t *lastTick, uint32_t periodMs)
{
    uint32_t now = g_sysTickMs;
    if ((now - *lastTick) >= periodMs)
    {
        *lastTick = now;
        return true;
    }
    return false;
}

/*=========================================================
 * Interrupt Callback
 * Call this from the MCU SysTick ISR
 *=========================================================*/
void SysTick_Handler(void)
{
    g_sysTickMs++;
}

/*=========================================================
 * Initialization
 *=========================================================*/
static void System_Init(void)
{
    HAL_SystemClock_Init();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_I2C_Init();
    HAL_UART_Init();
    HAL_SysTick_Init(SYS_TICK_MS);

    memset(&g_sensorData, 0, sizeof(g_sensorData));
    memset(&g_processedData, 0, sizeof(g_processedData));
    memset(g_analogFilterBuffer, 0, sizeof(g_analogFilterBuffer));
}

/*=========================================================
 * Main
 *=========================================================*/
int main(void)
{
    System_Init();

    uint32_t lastSampleTick = 0;
    uint32_t lastProcessTick = 0;

    while (1)
    {
        if (IsTimeElapsed(&lastSampleTick, SENSOR_SAMPLE_PERIOD_MS))
        {
            AnalogSensor_Read(&g_sensorData.analog);
            TempSensor_Read(&g_sensorData.temp);
        }

        if (IsTimeElapsed(&lastProcessTick, PROCESS_PERIOD_MS))
        {
            ProcessSensorData(&g_sensorData, &g_processedData);
            ReportData(&g_processedData);
        }

        /* Optional:
         * Enter low-power mode until next interrupt
         */
    }

    return 0;
}
