## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

/* =========================================================
 * Configuration
 * ========================================================= */
#define SENSOR_SAMPLE_PERIOD_MS      100U
#define STATUS_PRINT_PERIOD_MS       1000U
#define ADC_MAX_COUNTS               4095.0f
#define ADC_REF_VOLTAGE              3.3f
#define ANALOG_FILTER_ALPHA          0.2f
#define TEMP_FILTER_ALPHA            0.1f

#define ANALOG_ALERT_THRESHOLD_V     2.80f
#define TEMP_ALERT_THRESHOLD_C       60.0f

/* =========================================================
 * Platform / HAL Interface
 * Replace these with MCU-specific implementations
 * ========================================================= */
uint32_t hal_millis(void);
bool hal_adc_read(uint16_t *out_raw);
bool hal_i2c_temp_read(float *out_temp_c);
void hal_uart_write(const char *msg);
void hal_delay_ms(uint32_t ms);

/* =========================================================
 * Utility
 * ========================================================= */
static float low_pass_filter(float input, float prev, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * prev);
}

/* =========================================================
 * Sensor Data Structures
 * ========================================================= */
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    bool alert;
    bool valid;
} analog_sensor_t;

typedef struct
{
    float raw_temp_c;
    float filtered_temp_c;
    bool alert;
    bool valid;
} temp_sensor_t;

typedef struct
{
    analog_sensor_t analog;
    temp_sensor_t temp;
    uint32_t sample_count;
} system_data_t;

static system_data_t g_data;

/* =========================================================
 * Sensor Processing
 * ========================================================= */
static void analog_sensor_init(analog_sensor_t *s)
{
    memset(s, 0, sizeof(*s));
}

static void temp_sensor_init(temp_sensor_t *s)
{
    memset(s, 0, sizeof(*s));
}

static void analog_sensor_update(analog_sensor_t *s)
{
    uint16_t raw = 0;
    if (!hal_adc_read(&raw))
    {
        s->valid = false;
        return;
    }

    s->raw_adc = raw;
    s->voltage = ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;

    if (!s->valid)
    {
        s->filtered_voltage = s->voltage;
    }
    else
    {
        s->filtered_voltage = low_pass_filter(
            s->voltage,
            s->filtered_voltage,
            ANALOG_FILTER_ALPHA
        );
    }

    s->alert = (s->filtered_voltage > ANALOG_ALERT_THRESHOLD_V);
    s->valid = true;
}

static void temp_sensor_update(temp_sensor_t *s)
{
    float temp_c = 0.0f;
    if (!hal_i2c_temp_read(&temp_c))
    {
        s->valid = false;
        return;
    }

    s->raw_temp_c = temp_c;

    if (!s->valid)
    {
        s->filtered_temp_c = s->raw_temp_c;
    }
    else
    {
        s->filtered_temp_c = low_pass_filter(
            s->raw_temp_c,
            s->filtered_temp_c,
            TEMP_FILTER_ALPHA
        );
    }

    s->alert = (s->filtered_temp_c > TEMP_ALERT_THRESHOLD_C);
    s->valid = true;
}

static void process_all_sensors(system_data_t *data)
{
    analog_sensor_update(&data->analog);
    temp_sensor_update(&data->temp);
    data->sample_count++;
}

/* =========================================================
 * Reporting
 * ========================================================= */
static void report_status(const system_data_t *data)
{
    char buf[256];

    snprintf(
        buf,
        sizeof(buf),
        "samples=%lu | ADC raw=%u, V=%.3f, Vf=%.3f, alert=%d, valid=%d | "
        "Temp=%.2fC, Tf=%.2fC, alert=%d, valid=%d\r\n",
        (unsigned long)data->sample_count,
        data->analog.raw_adc,
        data->analog.voltage,
        data->analog.filtered_voltage,
        data->analog.alert ? 1 : 0,
        data->analog.valid ? 1 : 0,
        data->temp.raw_temp_c,
        data->temp.filtered_temp_c,
        data->temp.alert ? 1 : 0,
        data->temp.valid ? 1 : 0
    );

    hal_uart_write(buf);
}

/* =========================================================
 * Application Init
 * ========================================================= */
static void app_init(system_data_t *data)
{
    memset(data, 0, sizeof(*data));
    analog_sensor_init(&data->analog);
    temp_sensor_init(&data->temp);

    hal_uart_write("Sensor firmware starting...\r\n");
}

/* =========================================================
 * Main
 * ========================================================= */
int main(void)
{
    app_init(&g_data);

    uint32_t last_sample_ms = 0;
    uint32_t last_report_ms = 0;

    while (1)
    {
        uint32_t now = hal_millis();

        if ((now - last_sample_ms) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_ms = now;
            process_all_sensors(&g_data);
        }

        if ((now - last_report_ms) >= STATUS_PRINT_PERIOD_MS)
        {
            last_report_ms = now;
            report_status(&g_data);
        }

        /* Optional low-power wait or short delay */
        hal_delay_ms(1);
    }

    return 0;
}
```

