# 2. Example initial firmware in C

## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */
#define SENSOR_SAMPLE_PERIOD_MS   100U
#define FILTER_ALPHA              0.2f
#define ADC_MAX_COUNTS            4095.0f
#define ADC_REF_VOLTAGE           3.3f

#define TEMP_SENSOR_CHANNEL       0U
#define PRESSURE_SENSOR_CHANNEL   1U

#define TEMP_MIN_C                -40.0f
#define TEMP_MAX_C                125.0f
#define PRESSURE_MIN_KPA          0.0f
#define PRESSURE_MAX_KPA          500.0f

/* =========================
 * Data Types
 * ========================= */
typedef enum
{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_OUT_OF_RANGE,
    SENSOR_STATUS_HW_ERROR
} sensor_status_t;

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float value;
    float filtered_value;
    sensor_status_t status;
} sensor_data_t;

typedef struct
{
    sensor_data_t temperature;
    sensor_data_t pressure;
    uint32_t sample_count;
} system_sensor_state_t;

/* =========================
 * Global State
 * ========================= */
static system_sensor_state_t g_sensor_state = {0};

/* =========================
 * HAL Prototypes
 * Replace these with MCU-specific implementations
 * ========================= */
void hal_init(void);
uint32_t hal_get_tick_ms(void);
bool hal_adc_read(uint8_t channel, uint16_t *out_value);
void hal_uart_send(const char *msg);
void hal_delay_ms(uint32_t delay_ms);

/* =========================
 * Utility Functions
 * ========================= */
static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

/* Example conversion:
 * Assume temperature sensor outputs:
 * 0.5V = 0C
 * 10mV per degree C
 */
static float voltage_to_temperature_c(float voltage)
{
    return (voltage - 0.5f) / 0.01f;
}

/* Example conversion:
 * Assume pressure sensor outputs:
 * 0.5V = 0 kPa
 * 4.0V = 500 kPa
 */
static float voltage_to_pressure_kpa(float voltage)
{
    float pressure = ((voltage - 0.5f) * 500.0f) / 4.0f;

    if (pressure < 0.0f)
    {
        pressure = 0.0f;
    }

    return pressure;
}

static float low_pass_filter(float previous, float current, float alpha)
{
    return (alpha * current) + ((1.0f - alpha) * previous);
}

/* =========================
 * Sensor Processing
 * ========================= */
static void process_temperature_sensor(sensor_data_t *sensor)
{
    sensor->voltage = adc_to_voltage(sensor->raw_adc);
    sensor->value = voltage_to_temperature_c(sensor->voltage);

    if (sensor->status == SENSOR_STATUS_OK)
    {
        if (g_sensor_state.sample_count == 0U)
        {
            sensor->filtered_value = sensor->value;
        }
        else
        {
            sensor->filtered_value = low_pass_filter(sensor->filtered_value,
                                                     sensor->value,
                                                     FILTER_ALPHA);
        }

        if ((sensor->filtered_value < TEMP_MIN_C) ||
            (sensor->filtered_value > TEMP_MAX_C))
        {
            sensor->status = SENSOR_STATUS_OUT_OF_RANGE;
        }
    }
}

static void process_pressure_sensor(sensor_data_t *sensor)
{
    sensor->voltage = adc_to_voltage(sensor->raw_adc);
    sensor->value = voltage_to_pressure_kpa(sensor->voltage);

    if (sensor->status == SENSOR_STATUS_OK)
    {
        if (g_sensor_state.sample_count == 0U)
        {
            sensor->filtered_value = sensor->value;
        }
        else
        {
            sensor->filtered_value = low_pass_filter(sensor->filtered_value,
                                                     sensor->value,
                                                     FILTER_ALPHA);
        }

        if ((sensor->filtered_value < PRESSURE_MIN_KPA) ||
            (sensor->filtered_value > PRESSURE_MAX_KPA))
        {
            sensor->status = SENSOR_STATUS_OUT_OF_RANGE;
        }
    }
}

static void sample_sensor(uint8_t channel,
                          sensor_data_t *sensor,
                          void (*process_fn)(sensor_data_t *))
{
    uint16_t adc_value = 0;

    sensor->status = SENSOR_STATUS_OK;

    if (!hal_adc_read(channel, &adc_value))
    {
        sensor->status = SENSOR_STATUS_HW_ERROR;
        return;
    }

    sensor->raw_adc = adc_value;
    process_fn(sensor);
}

static void sensors_update(void)
{
    sample_sensor(TEMP_SENSOR_CHANNEL,
                  &g_sensor_state.temperature,
                  process_temperature_sensor);

    sample_sensor(PRESSURE_SENSOR_CHANNEL,
                  &g_sensor_state.pressure,
                  process_pressure_sensor);

    g_sensor_state.sample_count++;
}

static void report_sensor_state(void)
{
    char buffer[160];

    snprintf(buffer, sizeof(buffer),
             "Samples=%lu | Temp: raw=%u V=%.3f val=%.2f filt=%.2f status=%d | "
             "Pressure: raw=%u V=%.3f val=%.2f filt=%.2f status=%d\r\n",
             (unsigned long)g_sensor_state.sample_count,
             g_sensor_state.temperature.raw_adc,
             g_sensor_state.temperature.voltage,
             g_sensor_state.temperature.value,
             g_sensor_state.temperature.filtered_value,
             g_sensor_state.temperature.status,
             g_sensor_state.pressure.raw_adc,
             g_sensor_state.pressure.voltage,
             g_sensor_state.pressure.value,
             g_sensor_state.pressure.filtered_value,
             g_sensor_state.pressure.status);

    hal_uart_send(buffer);
}

/* =========================
 * Main Application
 * ========================= */
int main(void)
{
    uint32_t last_sample_time = 0U;

    hal_init();
    hal_uart_send("Sensor firmware starting...\r\n");

    while (1)
    {
        uint32_t now = hal_get_tick_ms();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;

            sensors_update();
            report_sensor_state();
        }

        /* Idle / background tasks here */
        hal_delay_ms(1);
    }

    return 0;
}
