// Assume 0.5V = 0 units, 2.5V = 100 units
#define SENSOR_VOLTAGE_MIN       0.5f
#define SENSOR_VOLTAGE_MAX       2.5f
#define SENSOR_UNITS_MIN         0.0f
#define SENSOR_UNITS_MAX         100.0f

// Fault thresholds in engineering units
#define SENSOR_FAULT_LOW         (-5.0f)
#define SENSOR_FAULT_HIGH        105.0f

/* =========================================================
 * Types
 * ========================================================= */
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float value_units;
    bool fault_low;
    bool fault_high;
    bool data_valid;
} sensor_data_t;

