{
    system_init();
    sensor_init();

    uint32_t last_sensor_sample = 0;
    uint32_t last_diag_print = 0;

    while (1)
    {
        uint32_t now = g_system_tick_ms;

        if ((now - last_sensor_sample) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sensor_sample = now;
            sensor_task();
        }

        if ((now - last_diag_print) >= 1000U)
        {
            last_diag_print = now;
            diagnostics_task();
        }

        // Idle / low-power opportunity here
    }

    return 0;
}

/* =========================================================
 * System Initialization
 * ========================================================= */
static void system_init(void)
{
    memset(&g_sensor_data, 0, sizeof(g_sensor_data));
    moving_average_init(&g_sensor_filter);

    hal_clock_init();
    hal_gpio_init();
    hal_adc_init();
    hal_uart_init();
    hal_timer_init();
}

static void sensor_init(void)
{
    g_sensor_data.data_valid = false;
    g_sensor_data.fault_low = false;
    g_sensor_data.fault_high = false;
}

/* =========================================================
 * Sensor Task
 * ========================================================= */
static void sensor_task(void)
{
    // Example: sensor connected to ADC channel 0
    uint16_t adc_raw = hal_adc_read_channel(0);
    process_sensor_reading(adc_raw);
}

static void process_sensor_reading(uint16_t adc_raw)
{
    g_sensor_data.raw_adc = adc_raw;
    g_sensor_data.voltage = adc_to_voltage(adc_raw);
    g_sensor_data.filtered_voltage = moving_average_update(&g_sensor_filter, g_sensor_data.voltage);
    g_sensor_data.value_units = voltage_to_sensor_units(g_sensor_data.filtered_voltage);

    g_sensor_data.fault_low = (g_sensor_data.value_units < SENSOR_FAULT_LOW);
    g_sensor_data.fault_high = (g_sensor_data.value_units > SENSOR_FAULT_HIGH);
    g_sensor_data.data_valid = true;
}

/* =========================================================
 * Conversion Functions
 * ========================================================= */
static float adc_to_voltage(uint16_t adc_raw)
{
    return ((float)adc_raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float voltage_to_sensor_units(float voltage)
{
    float span_voltage = SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN;
    float span_units = SENSOR_UNITS_MAX - SENSOR_UNITS_MIN;

    if (span_voltage <= 0.0f)
    {
        return 0.0f;
    }

    float normalized = (voltage - SENSOR_VOLTAGE_MIN) / span_voltage;
    float units = SENSOR_UNITS_MIN + (normalized * span_units);

    return units;
}

/* =========================================================
 * Moving Average Filter
 * ========================================================= */
static void moving_average_init(moving_average_filter_t *filter)
{
    memset(filter->buffer, 0, sizeof(filter->buffer));
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;
}

static float moving_average_update(moving_average_filter_t *filter, float sample)
{
    if (filter->count < SENSOR_FILTER_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= SENSOR_FILTER_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

/* =========================================================
