#include <stdint.h>
#include <stdbool.h>

/*
 * Generic firmware template for reading and processing sensor data.
 *
 * Replace the stubbed HAL functions with your microcontroller-specific code.
 * Example targets:
 * - STM32 HAL/LL
 * - AVR register-level code
 * - ESP-IDF
 * - PIC MCC-generated drivers
 */

/* =========================
 * Configuration
 * ========================= */
#define ADC_MAX_COUNTS          4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLE_PERIOD_MS 100
#define FILTER_WINDOW_SIZE      8

#define SENSOR_HIGH_THRESHOLD_V 2.80f
#define SENSOR_LOW_THRESHOLD_V  0.50f

/* =========================
 * Types
 * ========================= */
typedef struct
{
    uint16_t raw;
    float voltage;
    float filtered_voltage;
    bool alarm_high;
    bool alarm_low;
} SensorData_t;

typedef struct
{
    float buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

/* =========================
 * Global State
 * ========================= */
static SensorData_t g_sensorData;
static MovingAverageFilter_t g_filter;

/* =========================
 * HAL Prototypes
 * Replace these with MCU-specific implementations
 * ========================= */
static void HAL_SystemInit(void);
static void HAL_GPIO_Init(void);
static void HAL_ADC_Init(void);
static void HAL_UART_Init(void);
static uint16_t HAL_ADC_ReadChannel(uint8_t channel);
static void HAL_DelayMs(uint32_t ms);
static uint32_t HAL_GetTickMs(void);
static void HAL_LED_Set(bool on);
static void HAL_UART_SendString(const char *str);

/* =========================
 * Utility Prototypes
 * ========================= */
static void Filter_Init(MovingAverageFilter_t *filter);
static float Filter_Update(MovingAverageFilter_t *filter, float sample);
static float ConvertRawToVoltage(uint16_t raw);
static void Sensor_ReadAndProcess(void);
static void App_HandleSensorState(const SensorData_t *data);
static void App_ReportSensorData(const SensorData_t *data);

/* =========================
 * Main
 * ========================= */
int main(void)
{
    HAL_SystemInit();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    HAL_UART_Init();

    Filter_Init(&g_filter);

    uint32_t lastSampleTime = 0;

    while (1)
    {
        uint32_t now = HAL_GetTickMs();

        if ((now - lastSampleTime) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            lastSampleTime = now;

            Sensor_ReadAndProcess();
            App_HandleSensorState(&g_sensorData);
            App_ReportSensorData(&g_sensorData);
        }

        /* Optional:
         * Enter low-power mode here until next interrupt/tick
         */
    }

    return 0;
}

/* =========================
 * Sensor Processing
 * ========================= */
static void Sensor_ReadAndProcess(void)
{
    const uint8_t sensorChannel = 0;

    g_sensorData.raw = HAL_ADC_ReadChannel(sensorChannel);
    g_sensorData.voltage = ConvertRawToVoltage(g_sensorData.raw);
    g_sensorData.filtered_voltage = Filter_Update(&g_filter, g_sensorData.voltage);

    g_sensorData.alarm_high = (g_sensorData.filtered_voltage > SENSOR_HIGH_THRESHOLD_V);
    g_sensorData.alarm_low  = (g_sensorData.filtered_voltage < SENSOR_LOW_THRESHOLD_V);
}

static float ConvertRawToVoltage(uint16_t raw)
{
    return ((float)raw * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static void App_HandleSensorState(const SensorData_t *data)
{
    if (data->alarm_high || data->alarm_low)
    {
        HAL_LED_Set(true);
    }
    else
    {
        HAL_LED_Set(false);
    }
}

static void App_ReportSensorData(const SensorData_t *data)
{
    /* Minimal integer-only formatting alternative is recommended on small MCUs.
     * This simple example uses a lightweight manual formatter approach.
     */
    char msg[128];

    int raw = data->raw;
    int mv = (int)(data->voltage * 1000.0f);
    int filtered_mv = (int)(data->filtered_voltage * 1000.0f);

    const char *state = "OK";
    if (data->alarm_high) state = "HIGH";
    else if (data->alarm_low) state = "LOW";

    /* Simple manual formatting to avoid full printf dependency */
    /* Replace with snprintf if your platform supports it comfortably */
    int len = 0;

    len += simple_strcpy(&msg[len], "RAW=");
    len += simple_itoa(raw, &msg[len]);
    len += simple_strcpy(&msg[len], " V=");
    len += simple_itoa(mv, &msg[len]);
    len += simple_strcpy(&msg[len], "mV FILT=");
    len += simple_itoa(filtered_mv, &msg[len]);
    len += simple_strcpy(&msg[len], "mV STATE=");
    len += simple_strcpy(&msg[len], state);
    len += simple_strcpy(&msg[len], "\r\n");

    msg[len] = '\0';

    HAL_UART_SendString(msg);
}

/* =========================
 * Filter
 * ========================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    uint8_t i;
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= FILTER_WINDOW_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / filter->count;
}

/* =========================
 * Lightweight String Helpers
 * ========================= */
static int simple_strcpy(char *dst, const char *src)
{
    int i = 0;
    while (src[i] != '\0')
    {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';
    return i;
}

static int simple_itoa(int value, char *str)
{
    char temp[16];
    int i = 0;
    int j = 0;
    int isNegative = 0;

    if (value == 0)
    {
        str[0] = '0';
        str[1] = '\0';
        return 1;
    }

    if (value < 0)
    {
        isNegative = 1;
        value = -value;
    }

    while (value > 0)
    {
        temp[i++] = (char)('0' + (value % 10));
        value /= 10;
    }

    if (isNegative)
    {
        str[j++] = '-';
