## Example firmware: sensor read and process

```c
#include <stdint.h>
#include <stdbool.h>

/*========================
  Configuration
========================*/
#define ADC_MAX_COUNTS         4095.0f
#define ADC_REF_VOLTAGE        3.3f
#define SENSOR_SCALE_FACTOR    100.0f   // Example: 100 units per volt
#define FILTER_WINDOW_SIZE     8

#define SENSOR_SAMPLE_PERIOD_MS 100

/*========================
  Mock HAL / Platform API
  Replace with MCU-specific code
========================*/
void SystemClock_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void UART_Init(void);
void Timer_Init(void);
uint16_t ADC_ReadChannel(uint8_t channel);
void Delay_ms(uint32_t ms);
void UART_SendString(const char *str);
uint32_t GetTick_ms(void);

/*========================
  Sensor Data Structure
========================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float physical_value;
} SensorData_t;

/*========================
  Moving Average Filter
========================*/
typedef struct
{
    float buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

static void Filter_Init(MovingAverageFilter_t *filter)
{
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = sample;
    filter->sum += sample;

    filter->index = (filter->index + 1) % FILTER_WINDOW_SIZE;

    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->count++;
    }

    return filter->sum / filter->count;
}

/*========================
  Sensor Functions
========================*/
static float ADC_ToVoltage(uint16_t adc_value)
{
    return ((float)adc_value / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float Voltage_ToPhysicalUnits(float voltage)
{
    return voltage * SENSOR_SCALE_FACTOR;
}

static void Sensor_ReadAndProcess(SensorData_t *sensor, MovingAverageFilter_t *filter)
{
    sensor->raw_adc = ADC_ReadChannel(0);
    sensor->voltage = ADC_ToVoltage(sensor->raw_adc);
    sensor->filtered_voltage = Filter_Update(filter, sensor->voltage);
    sensor->physical_value = Voltage_ToPhysicalUnits(sensor->filtered_voltage);
}

/*========================
  Debug / Reporting
========================*/
static void Sensor_Report(const SensorData_t *sensor)
{
    char msg[128];

    // Simple lightweight formatting alternative may be preferred on embedded targets
    // Replace snprintf if standard library support is limited
    extern int snprintf(char *str, unsigned long size, const char *format, ...);

    snprintf(msg, sizeof(msg),
             "ADC=%u, V=%.3f, Vf=%.3f, Value=%.2f\r\n",
             sensor->raw_adc,
             sensor->voltage,
             sensor->filtered_voltage,
             sensor->physical_value);

    UART_SendString(msg);
}

/*========================
  Main Application
========================*/
int main(void)
{
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    UART_Init();
    Timer_Init();

    SensorData_t sensor = {0};
    MovingAverageFilter_t filter;
    Filter_Init(&filter);

    uint32_t last_sample_time = 0;

    while (1)
    {
        uint32_t now = GetTick_ms();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;

            Sensor_ReadAndProcess(&sensor, &filter);
            Sensor_Report(&sensor);
        }

        // Optional: enter low-power mode here until next interrupt
    }

    return 0;
}
