#define ADC_REF_VOLTAGE         3.3f
#define SENSOR_SAMPLE_PERIOD_MS 100U
#define FILTER_WINDOW_SIZE      8U

#define SENSOR_MIN_VALID_V      0.1f
#define SENSOR_MAX_VALID_V      3.2f

/* Example conversion:
 * Suppose sensor outputs:
 * 0.5V = 0 units
 * 2.5V = 100 units
 */
#define SENSOR_VOLTAGE_OFFSET   0.5f
#define SENSOR_SCALE            50.0f       // (100 units / 2.0V)

/* =========================================================
 * Hardware abstraction layer prototypes
 * Replace these with MCU-specific implementations
 * ========================================================= */
