{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float engineering_value;
    bool valid;
    bool fault_low;
    bool fault_high;
} SensorData_t;

typedef struct
{
    float samples[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

/* =========================================================
 * Globals
 * ========================================================= */
static SensorData_t g_sensorData;
static MovingAverageFilter_t g_filter;

/* =========================================================
 * Utility functions
 * ========================================================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    memset(filter, 0, sizeof(MovingAverageFilter_t));
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->samples[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->samples[filter->index];
        filter->samples[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= FILTER_WINDOW_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

static float ADC_CountsToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float VoltageToEngineeringUnits(float voltage)
{
    float value = (voltage - SENSOR_VOLTAGE_OFFSET) * SENSOR_SCALE;

    if (value < 0.0f)
    {
        value = 0.0f;
    }

    return value;
}

/* =========================================================
 * Sensor processing
 * ========================================================= */
static void Sensor_Init(void)
{
    memset(&g_sensorData, 0, sizeof(g_sensorData));
    Filter_Init(&g_filter);
}

static void Sensor_ReadAndProcess(void)
{
    const uint8_t sensor_adc_channel = 0;

    g_sensorData.raw_adc = HAL_ADC_ReadRaw(sensor_adc_channel);
    g_sensorData.voltage = ADC_CountsToVoltage(g_sensorData.raw_adc);
    g_sensorData.filtered_voltage = Filter_Update(&g_filter, g_sensorData.voltage);

    g_sensorData.fault_low = (g_sensorData.filtered_voltage < SENSOR_MIN_VALID_V);
    g_sensorData.fault_high = (g_sensorData.filtered_voltage > SENSOR_MAX_VALID_V);
    g_sensorData.valid = !(g_sensorData.fault_low || g_sensorData.fault_high);

    if (g_sensorData.valid)
    {
        g_sensorData.engineering_value =
            VoltageToEngineeringUnits(g_sensorData.filtered_voltage);
    }
    else
    {
        g_sensorData.engineering_value = 0.0f;
    }
}

/* =========================================================
 * Optional reporting
 * ========================================================= */
