```c
#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define ADC_MAX_COUNTS          4095.0f
#define ADC_REF_VOLTAGE         3.3f

#define SENSOR_SAMPLE_PERIOD_MS 100U
#define FILTER_WINDOW_SIZE      8U

/* Example sensor scaling:
 * Suppose sensor outputs:
 *   0.5V = 0 units
 *   2.5V = 100 units
 */
#define SENSOR_VOLTAGE_MIN      0.5f
#define SENSOR_VOLTAGE_MAX      2.5f
#define SENSOR_UNITS_MIN        0.0f
#define SENSOR_UNITS_MAX        100.0f

/* Fault thresholds */
#define SENSOR_DISCONNECT_VOLTAGE_LOW   0.1f
#define SENSOR_DISCONNECT_VOLTAGE_HIGH  3.2f
#define SENSOR_VALID_MIN_UNITS         -5.0f
#define SENSOR_VALID_MAX_UNITS         105.0f

/*=========================================================
 * Types
 *=========================================================*/
typedef enum
{
    SENSOR_STATUS_OK = 0,
    SENSOR_STATUS_DISCONNECTED,
    SENSOR_STATUS_OUT_OF_RANGE
} sensor_status_t;

typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    float value_units;
    sensor_status_t status;
} sensor_data_t;

/*=========================================================
 * Globals
 *=========================================================*/
static volatile uint32_t g_system_tick_ms = 0;
static sensor_data_t g_sensor_data = {0};

static float g_filter_buffer[FILTER_WINDOW_SIZE] = {0};
static uint8_t g_filter_index = 0;
static bool g_filter_initialized = false;

/*=========================================================
 * Hardware abstraction stubs
 * Replace these with MCU-specific implementations
 *=========================================================*/
static void SystemClock_Init(void);
static void GPIO_Init(void);
static void ADC_Init(void);
static void Timer_Init(void);
static uint16_t ADC_ReadChannel(uint8_t channel);
static void UART_Log(const char *msg);

/*=========================================================
 * Utility functions
 *=========================================================*/
static float adc_to_voltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float voltage_to_sensor_units(float voltage)
{
    float slope = (SENSOR_UNITS_MAX - SENSOR_UNITS_MIN) /
                  (SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN);

    float units = SENSOR_UNITS_MIN + ((voltage - SENSOR_VOLTAGE_MIN) * slope);
    return units;
}

static float moving_average_filter(float new_sample)
{
    float sum = 0.0f;

    if (!g_filter_initialized)
    {
        for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
        {
            g_filter_buffer[i] = new_sample;
        }
        g_filter_initialized = true;
    }

    g_filter_buffer[g_filter_index] = new_sample;
    g_filter_index = (g_filter_index + 1U) % FILTER_WINDOW_SIZE;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        sum += g_filter_buffer[i];
    }

    return sum / FILTER_WINDOW_SIZE;
}

static sensor_status_t evaluate_sensor_status(float voltage, float units)
{
    if ((voltage <= SENSOR_DISCONNECT_VOLTAGE_LOW) ||
        (voltage >= SENSOR_DISCONNECT_VOLTAGE_HIGH))
    {
        return SENSOR_STATUS_DISCONNECTED;
    }

    if ((units < SENSOR_VALID_MIN_UNITS) ||
        (units > SENSOR_VALID_MAX_UNITS))
    {
        return SENSOR_STATUS_OUT_OF_RANGE;
    }

    return SENSOR_STATUS_OK;
}

/*=========================================================
 * Sensor task
 *=========================================================*/
static void Sensor_ReadAndProcess(void)
{
    uint16_t raw = ADC_ReadChannel(0);
    float voltage = adc_to_voltage(raw);
    float filtered_voltage = moving_average_filter(voltage);
    float units = voltage_to_sensor_units(filtered_voltage);
    sensor_status_t status = evaluate_sensor_status(filtered_voltage, units);

    g_sensor_data.raw_adc = raw;
    g_sensor_data.voltage = voltage;
    g_sensor_data.filtered_voltage = filtered_voltage;
    g_sensor_data.value_units = units;
    g_sensor_data.status = status;
}

