{
    SystemClock_Init();
    GPIO_Init();
    ADC_Init();
    Timer_Init();

    UART_Log("Sensor firmware starting...\n");

    uint32_t last_sample_time = 0;

    while (1)
    {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;
            Sensor_ReadAndProcess();

            /* Optional: place breakpoint here or transmit data */
            switch (g_sensor_data.status)
            {
