                    break;

                case SENSOR_STATUS_OUT_OF_RANGE:
                    UART_Log("Sensor out of range\n");
                    break;

                default:
                    UART_Log("Unknown sensor status\n");
                    break;
            }
        }

        /* Idle / low-power / background tasks here */
    }
}

