void UART_Init(void);
void UART_SendString(const char *str);
void DelayMs(uint32_t ms);

/* =========================
 * Utility functions
 * ========================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        filter->buffer[i] = 0.0f;
    }
}

static float Filter_Update(MovingAverageFilter_t *filter, float new_sample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = new_sample;
    filter->sum += new_sample;

    filter->index = (filter->index + 1) % FILTER_WINDOW_SIZE;

    if (filter->count < FILTER_WINDOW_SIZE) {
        filter->count++;
    }

    return filter->sum / filter->count;
}

static float ADC_CountsToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

/* =========================
