# Initial Firmware Implementation

```c
/*
 * initial_sensor_firmware.c
 *
 * Generic microcontroller firmware example:
 * - Periodic sensor sampling
 * - ADC-based sensor reading
 * - Moving average filtering
 * - Threshold/fault detection
 * - Main loop processing
 *
 * Replace HAL_* functions with your MCU-specific drivers.
 */

#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*=========================================================
 * Configuration
 *=========================================================*/
#define SENSOR_SAMPLE_PERIOD_MS     100U
#define SENSOR_FILTER_SIZE          8U

#define ADC_MAX_COUNTS              4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE             3.3f

/* Example sensor scaling:
 * Suppose sensor outputs 0.5V to 2.5V corresponding to 0 to 100 units
 */
#define SENSOR_VOLTAGE_MIN          0.5f
#define SENSOR_VOLTAGE_MAX          2.5f
#define SENSOR_PHYSICAL_MIN         0.0f
#define SENSOR_PHYSICAL_MAX         100.0f

#define SENSOR_FAULT_LOW_VOLTAGE    0.1f
#define SENSOR_FAULT_HIGH_VOLTAGE   3.2f

/*=========================================================
 * Type Definitions
 *=========================================================*/
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float physical_value;
    float filtered_value;
    bool fault;
} sensor_data_t;

typedef struct
{
    float buffer[SENSOR_FILTER_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} moving_average_filter_t;

/*=========================================================
 * Global State
 *=========================================================*/
static volatile uint32_t g_system_tick_ms = 0;
static volatile bool g_sample_flag = false;

static sensor_data_t g_sensor_data;
static moving_average_filter_t g_filter;

/*=========================================================
 * Hardware Abstraction Layer Prototypes
 * Replace these with real MCU-specific implementations.
 *=========================================================*/
static void HAL_SystemInit(void);
static void HAL_GPIO_Init(void);
static void HAL_ADC_Init(void);
static void HAL_Timer_Init(void);
static uint16_t HAL_ADC_ReadChannel(uint8_t channel);
static void HAL_DelayMs(uint32_t ms);
static void HAL_HeartbeatToggle(void);

/*=========================================================
 * Application Function Prototypes
 *=========================================================*/
static void Filter_Init(moving_average_filter_t *filter);
static float Filter_Update(moving_average_filter_t *filter, float sample);

static void Sensor_Init(void);
static void Sensor_SampleAndProcess(void);
static float ADC_CountsToVoltage(uint16_t adc_counts);
static float SensorVoltageToPhysical(float voltage);
static bool Sensor_CheckFault(float voltage);

static void App_Init(void);
static void App_Task(void);

/*=========================================================
 * Interrupt / Tick Hook
 * Call this from a 1 ms timer ISR in real firmware.
 *=========================================================*/
void SysTick_Handler(void)
{
    g_system_tick_ms++;

    if ((g_system_tick_ms % SENSOR_SAMPLE_PERIOD_MS) == 0U)
    {
        g_sample_flag = true;
    }
}

/*=========================================================
 * Filter Implementation
 *=========================================================*/
static void Filter_Init(moving_average_filter_t *filter)
{
    memset(filter, 0, sizeof(*filter));
}

static float Filter_Update(moving_average_filter_t *filter, float sample)
{
    if (filter->count < SENSOR_FILTER_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= SENSOR_FILTER_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

/*=========================================================
 * Sensor Processing
 *=========================================================*/
static void Sensor_Init(void)
{
    memset(&g_sensor_data, 0, sizeof(g_sensor_data));
    Filter_Init(&g_filter);
}

static void Sensor_SampleAndProcess(void)
{
    const uint8_t sensor_adc_channel = 0U;

    g_sensor_data.raw_adc = HAL_ADC_ReadChannel(sensor_adc_channel);
    g_sensor_data.voltage = ADC_CountsToVoltage(g_sensor_data.raw_adc);
    g_sensor_data.fault = Sensor_CheckFault(g_sensor_data.voltage);

    if (!g_sensor_data.fault)
    {
        g_sensor_data.physical_value = SensorVoltageToPhysical(g_sensor_data.voltage);
        g_sensor_data.filtered_value = Filter_Update(&g_filter, g_sensor_data.physical_value);
    }
    else
    {
        /* On fault, keep previous filtered value or set safe default */
        g_sensor_data.physical_value = 0.0f;
    }
}

static float ADC_CountsToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float SensorVoltageToPhysical(float voltage)
{
    if (voltage <= SENSOR_VOLTAGE_MIN)
    {
        return SENSOR_PHYSICAL_MIN;
    }

    if (voltage >= SENSOR_VOLTAGE_MAX)
    {
        return SENSOR_PHYSICAL_MAX;
    }

    float normalized = (voltage - SENSOR_VOLTAGE_MIN) /
                       (SENSOR_VOLTAGE_MAX - SENSOR_VOLTAGE_MIN);

    return SENSOR_PHYSICAL_MIN +
           normalized * (SENSOR_PHYSICAL_MAX - SENSOR_PHYSICAL_MIN);
}

static bool Sensor_CheckFault(float voltage)
{
    if (voltage < SENSOR_FAULT_LOW_VOLTAGE)
    {
        return true;
    }

    if (voltage > SENSOR_FAULT_HIGH_VOLTAGE)
    {
        return true;
    }

    return false;
}

