 *=============================*/
static void Filter_Init(MovingAverageFilter_t *filter)
{
    memset(filter, 0, sizeof(MovingAverageFilter_t));
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    if (filter->count < MOVING_AVG_WINDOW_SIZE)
    {
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->buffer[filter->index];
        filter->buffer[filter->index] = sample;
        filter->sum += sample;
    }

    filter->index++;
    if (filter->index >= MOVING_AVG_WINDOW_SIZE)
    {
        filter->index = 0;
    }

    return filter->sum / (float)filter->count;
}

static float Sensor_ApplyCalibration(uint16_t raw, const SensorCalibration_t *cal)
{
    return ((float)raw * cal->scale) + cal->offset;
}

static bool Sensor_CheckFault(uint16_t raw)
{
    static uint8_t lowCount = 0;
    static uint8_t highCount = 0;

    if (raw <= SENSOR_RAW_MIN)
    {
        lowCount++;
    }
    else
    {
        lowCount = 0;
    }

    if (raw >= SENSOR_RAW_MAX)
    {
        highCount++;
    }
    else
    {
        highCount = 0;
    }

    if (lowCount >= SENSOR_FAULT_THRESHOLD || highCount >= SENSOR_FAULT_THRESHOLD)
    {
        return true;
    }

    return false;
}

