{
    SystemClock_Init();
    GPIO_Init();
    UART_Init();
    ADC_Init();
    Timer_Init();
    Sensor_Init();

    UART_SendString("Sensor firmware started\r\n");

    while (1)
    {
        if (g_sampleFlag)
        {
            g_sampleFlag = false;

            Sensor_SampleAndProcess();
            App_ReportData();
        }

        /* Optional: enter low-power mode here until next interrupt */
    }

    return 0;
}

/*=========================================================
 * Sensor Initialization
 *=========================================================*/
static void Sensor_Init(void)
{
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        g_filterBuffer[i] = 0.0f;
    }

    g_filterIndex = 0;
    g_filterFilled = false;

    g_sensorData.raw_adc = 0;
    g_sensorData.voltage = 0.0f;
    g_sensorData.filtered_voltage = 0.0f;
    g_sensorData.engineering_value = 0.0f;
    g_sensorData.fault_low = false;
    g_sensorData.fault_high = false;
}

/*=========================================================
 * Sample and Process Sensor Data
 *=========================================================*/
static void Sensor_SampleAndProcess(void)
{
    /* Step 1: Read raw ADC */
    g_sensorData.raw_adc = ADC_ReadChannel(0);

    /* Step 2: Convert raw ADC to voltage */
    g_sensorData.voltage = Sensor_ConvertRawToVoltage(g_sensorData.raw_adc);

    /* Step 3: Filter voltage */
    g_sensorData.filtered_voltage = Sensor_FilterVoltage(g_sensorData.voltage);

    /* Step 4: Convert to engineering units */
    g_sensorData.engineering_value =
        Sensor_ConvertToEngineeringUnits(g_sensorData.filtered_voltage);

    /* Step 5: Check thresholds/faults */
    Sensor_CheckFaults(g_sensorData.engineering_value);
}

/*=========================================================
 * ADC Counts -> Voltage
 *=========================================================*/
static float Sensor_ConvertRawToVoltage(uint16_t raw)
{
    return ((float)raw / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

/*=========================================================
 * Simple Moving Average Filter
 *=========================================================*/
static float Sensor_FilterVoltage(float input)
{
    g_filterBuffer[g_filterIndex] = input;
    g_filterIndex++;

    if (g_filterIndex >= FILTER_WINDOW_SIZE)
    {
        g_filterIndex = 0;
        g_filterFilled = true;
    }

    uint8_t count = g_filterFilled ? FILTER_WINDOW_SIZE : g_filterIndex;
    if (count == 0)
    {
        return input;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++)
    {
        sum += g_filterBuffer[i];
    }

    return sum / (float)count;
}

/*=========================================================
 * Voltage -> Engineering Units
 * Example linear scaling
 *=========================================================*/
static float Sensor_ConvertToEngineeringUnits(float voltage)
{
    return voltage * SENSOR_SCALE;
}

/*=========================================================
