#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <atomic>
#include <algorithm>

using Clock = std::chrono::steady_clock;

// -----------------------------
// Utility
// -----------------------------
template <typename T>
T clamp(T value, T min_val, T max_val) {
    return std::max(min_val, std::min(value, max_val));
}

// -----------------------------
// Sensor data structures
// -----------------------------
struct IMUData {
    double accel_x;
    double accel_y;
    double accel_z;
    double gyro_x;
    double gyro_y;
    double gyro_z;
};

struct EncoderData {
    double left_velocity;
    double right_velocity;
};

struct RobotState {
    double pitch;          // estimated pitch angle (rad)
    double pitch_rate;     // estimated pitch rate (rad/s)
    double velocity;       // forward velocity (m/s)
};

// -----------------------------
// Mock hardware interfaces
// Replace these with real drivers
// -----------------------------
class IMUSensor {
public:
    IMUData read() {
        // Simulated sensor values
        return {
            0.0, 0.0, 9.81,   // accel
            0.0, 0.01, 0.0    // gyro
        };
    }
};

class Encoder {
public:
    EncoderData read() {
        return {0.5, 0.5};
    }
};

class MotorDriver {
public:
    void setMotorCommands(double left_cmd, double right_cmd) {
        left_cmd = clamp(left_cmd, -1.0, 1.0);
        right_cmd = clamp(right_cmd, -1.0, 1.0);

        // Replace with PWM / CAN / serial motor command output
        std::cout << "Motor L: " << left_cmd
                  << " R: " << right_cmd << std::endl;
    }
};

// -----------------------------
// Complementary filter for pitch
// -----------------------------
class ComplementaryFilter {
public:
    ComplementaryFilter(double alpha = 0.98)
        : alpha_(alpha), pitch_estimate_(0.0) {}

    double update(const IMUData& imu, double dt) {
        // Compute pitch from accelerometer
        double accel_pitch = std::atan2(-imu.accel_x,
                                        std::sqrt(imu.accel_y * imu.accel_y +
                                                  imu.accel_z * imu.accel_z));

        // Integrate gyro y-axis for pitch rate
        double gyro_pitch_rate = imu.gyro_y;

        // Complementary filter
        pitch_estimate_ = alpha_ * (pitch_estimate_ + gyro_pitch_rate * dt)
                        + (1.0 - alpha_) * accel_pitch;

        return pitch_estimate_;
    }

private:
    double alpha_;
    double pitch_estimate_;
};

// -----------------------------
// PID controller
// -----------------------------
class PIDController {
public:
    PIDController(double kp, double ki, double kd,
                  double min_output, double max_output)
        : kp_(kp), ki_(ki), kd_(kd),
          min_output_(min_output), max_output_(max_output),
          integral_(0.0), prev_error_(0.0), first_update_(true) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        integral_ += error * dt;

        double derivative = 0.0;
        if (!first_update_ && dt > 1e-6) {
            derivative = (error - prev_error_) / dt;
        }

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = clamp(output, min_output_, max_output_);

        prev_error_ = error;
        first_update_ = false;

        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
        first_update_ = true;
    }

private:
    double kp_, ki_, kd_;
    double min_output_, max_output_;
    double integral_;
    double prev_error_;
    bool first_update_;
};

// -----------------------------
// Main robot controller
// Example: balancing robot / pitch stabilization
// -----------------------------
class RobotController {
public:
    RobotController()
        : pitch_filter_(0.98),
          balance_pid_(25.0, 1.0, 2.0, -1.0, 1.0),
          running_(true) {}

    void run(double loop_hz) {
        const std::chrono::duration<double> period(1.0 / loop_hz);
        auto next_time = Clock::now();
        auto last_time = Clock::now();

        while (running_) {
            next_time += std::chrono::duration_cast<Clock::duration>(period);
            auto now = Clock::now();
            std::chrono::duration<double> elapsed = now - last_time;
            double dt = elapsed.count();
            last_time = now;

            // 1. Read sensors
            IMUData imu = imu_.read();
            EncoderData enc = encoder_.read();

            // 2. Sensor fusion / state estimation
            state_.pitch = pitch_filter_.update(imu, dt);
            state_.pitch_rate = imu.gyro_y;
            state_.velocity = 0.5 * (enc.left_velocity + enc.right_velocity);

            // 3. Control law
            double desired_pitch = 0.0; // upright
            double control_effort = balance_pid_.update(desired_pitch, state_.pitch, dt);

            // 4. Motor mixing
            double left_motor_cmd = control_effort;
            double right_motor_cmd = control_effort;

            // 5. Send actuator commands
            motor_driver_.setMotorCommands(left_motor_cmd, right_motor_cmd);

            // 6. Sleep until next cycle
            std::this_thread::sleep_until(next_time);
        }
    }

    void stop() {
        running_ = false;
    }

private:
    IMUSensor imu_;
    Encoder encoder_;
    MotorDriver motor_driver_;
    ComplementaryFilter pitch_filter_;
    PIDController balance_pid_;
    RobotState state_;
    std::atomic<bool> running_;
};

// -----------------------------
// Entry point
// -----------------------------
int main() {
    RobotController controller;

    // Run at 200 Hz
    controller.run(200.0);

    return 0;
}
