# Python version

If you want a quick prototype, here is a Python version:

```python
import time
import math

def clamp(value, min_val, max_val):
    return max(min_val, min(value, max_val))

class ComplementaryFilter:
    def __init__(self, alpha=0.98):
        self.alpha = alpha
        self.pitch = 0.0

    def update(self, accel_x, accel_y, accel_z, gyro_y, dt):
        accel_pitch = math.atan2(-accel_x, math.sqrt(accel_y**2 + accel_z**2))
        self.pitch = self.alpha * (self.pitch + gyro_y * dt) + (1 - self.alpha) * accel_pitch
        return self.pitch

class PID:
    def __init__(self, kp, ki, kd, out_min=-1.0, out_max=1.0):
        self.kp = kp
        self.ki = ki
        self.kd = kd
        self.out_min = out_min
        self.out_max = out_max
        self.integral = 0.0
        self.prev_error = 0.0
        self.first = True

    def update(self, setpoint, measurement, dt):
        error = setpoint - measurement
        self.integral += error * dt
        derivative = 0.0 if self.first else (error - self.prev_error) / dt
        self.first = False
        self.prev_error = error

        output = self.kp * error + self.ki * self.integral + self.kd * derivative
        return clamp(output, self.out_min, self.out_max)

def read_imu():
    return {
        "accel_x": 0.0,
        "accel_y": 0.0,
        "accel_z": 9.81,
        "gyro_y": 0.01
    }

def read_encoders():
    return {"left_velocity": 0.5, "right_velocity": 0.5}

def set_motors(left, right):
    print(f"Left={left:.3f}, Right={right:.3f}")

def main():
    loop_hz = 200.0
    dt_target = 1.0 / loop_hz

    filt = ComplementaryFilter(alpha=0.98)
    pid = PID(25.0, 1.0, 2.0)

    last = time.perf_counter()

    while True:
        now = time.perf_counter()
        dt = now - last
        last = now

        imu = read_imu()
        enc = read_encoders()

        pitch = filt.update(
            imu["accel_x"],
            imu["accel_y"],
            imu["accel_z"],
            imu["gyro_y"],
            dt
        )

        velocity = 0.5 * (enc["left_velocity"] + enc["right_velocity"])
        control = pid.update(0.0, pitch, dt)

        left_cmd = control
        right_cmd = control

        set_motors(left_cmd, right_cmd)

        elapsed = time.perf_counter() - now
        sleep_time = max(0.0, dt_target - elapsed)
        time.sleep(sleep_time)

if __name__ == "__main__":
    main()
```

