Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for MCUs.

It includes:

- 3-axis accelerometer sample input
- DC removal / simple low-pass baseline
- Magnitude estimation
- Moving average + variance estimate
- Z-score style anomaly detection
- Optional spike debounce / persistence
- No dynamic allocation
- Fixed-size buffers

---

## C Code

```c
/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - 3-axis sample ingestion
 * - Baseline removal with IIR low-pass
 * - Magnitude calculation
 * - Sliding window mean/variance
 * - Z-score anomaly detection
 * - Persistence counter to reduce false positives
 *
 * Suitable for microcontrollers with no malloc.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE             32
#define ANOMALY_Z_THRESHOLD     3.5f
#define MIN_STDDEV              0.02f
#define PERSISTENCE_LIMIT       3

/* Baseline LPF coefficient:
 * baseline = baseline + alpha * (x - baseline)
 * Smaller alpha => slower baseline tracking
 */
#define BASELINE_ALPHA          0.01f

/* =========================
 * Data structures
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    /* Baseline estimate for gravity / slow drift */
    float bx;
    float by;
    float bz;

    /* Sliding window for magnitude */
    float mag_buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    /* Running sums for mean/stddev */
    float sum;
    float sumsq;

    /* Detection state */
    uint8_t persistence;
    bool anomaly_active;
} AnomalyDetector;

/* =========================
 * Utility functions
 * ========================= */

/* Fast magnitude approximation for lower-cost MCUs.
 * Replace with sqrtf(x*x+y*y+z*z) if accuracy is more important.
 */
static float approx_magnitude(float x, float y, float z)
{
    x = fabsf(x);
    y = fabsf(y);
    z = fabsf(z);

    float max = x;
    float mid = y;
    float min = z;

    /* Sort descending: max >= mid >= min */
    if (max < mid) { float t = max; max = mid; mid = t; }
    if (mid < min) { float t = mid; mid = min; min = t; }
    if (max < mid) { float t = max; max = mid; mid = t; }

    /* Weighted approximation */
    return max + 0.5f * mid + 0.25f * min;
}

static float compute_mean(const AnomalyDetector *det)
{
    if (det->count == 0) return 0.0f;
    return det->sum / (float)det->count;
}

static float compute_stddev(const AnomalyDetector *det)
{
    if (det->count < 2) return MIN_STDDEV;

    float n = (float)det->count;
    float mean = det->sum / n;
    float variance = (det->sumsq / n) - (mean * mean);

    if (variance < 0.0f) variance = 0.0f;

    float stddev = sqrtf(variance);
    if (stddev < MIN_STDDEV) stddev = MIN_STDDEV;
    return stddev;
}

/* =========================
 * API
 * ========================= */

void anomaly_detector_init(AnomalyDetector *det)
{
    det->bx = 0.0f;
    det->by = 0.0f;
    det->bz = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        det->mag_buffer[i] = 0.0f;
    }

    det->index = 0;
    det->count = 0;
    det->sum = 0.0f;
    det->sumsq = 0.0f;
    det->persistence = 0;
    det->anomaly_active = false;
}

/*
 * Process one accelerometer sample.
 *
 * Returns true when anomaly condition is active.
 * Optionally outputs:
 *   - filtered magnitude
 *   - z-score
 */
bool anomaly_detector_process(
    AnomalyDetector *det,
    AccelSample s,
    float *out_mag,
    float *out_zscore)
{
    /* 1) Update slow baseline (gravity / orientation / drift) */
    det->bx += BASELINE_ALPHA * (s.x - det->bx);
    det->by += BASELINE_ALPHA * (s.y - det->by);
    det->bz += BASELINE_ALPHA * (s.z - det->bz);

    /* 2) Remove baseline */
    float fx = s.x - det->bx;
    float fy = s.y - det->by;
    float fz = s.z - det->bz;

    /* 3) Compute motion magnitude */
    float mag = approx_magnitude(fx, fy, fz);
    /* If you prefer exact:
     * float mag = sqrtf(fx*fx + fy*fy + fz*fz);
     */

    /* 4) Remove oldest sample from running stats if buffer full */
    if (det->count == WINDOW_SIZE) {
        float old = det->mag_buffer[det->index];
        det->sum   -= old;
        det->sumsq -= old * old;
    } else {
        det->count++;
    }

    /* 5) Insert new sample */
    det->mag_buffer[det->index] = mag;
    det->sum   += mag;
    det->sumsq += mag * mag;

    det->index++;
    if (det->index >= WINDOW_SIZE) {
        det->index = 0;
    }

    /* 6) Compute statistics */
    float mean = compute_mean(det);
    float stddev = compute_stddev(det);
    float z = (mag - mean) / stddev;

    /* 7) Detect anomaly */
    bool instant_anomaly = (fabsf(z) >= ANOMALY_Z_THRESHOLD);

    if (instant_anomaly) {
        if (det->persistence < 255) {
            det->persistence++;
        }
    } else {
        if (det->persistence > 0) {
            det->persistence--;
        }
    }

    det->anomaly_active = (det->persistence >= PERSISTENCE_LIMIT);

    if (out_mag) {
        *out_mag = mag;
    }
    if (out_zscore) {
        *out_zscore = z;
    }

    return det->anomaly_active;
}
```

