Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline suitable for MCUs.

What it does:
- Accepts raw 3-axis accelerometer samples
- Applies simple low-pass filtering
- Computes acceleration magnitude
- Maintains a rolling baseline mean/variance
- Produces anomaly events using a z-score threshold
- Includes a cooldown to avoid repeated triggers

This is designed to be:
- No dynamic allocation
- O(1) per sample
- Easy to port to bare metal, RTOS, or Arduino-style loops

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *   raw xyz
 *    -> low-pass filter
 *    -> magnitude
 *    -> online baseline mean/variance
 *    -> z-score anomaly detection
 *
 * Notes:
 * - Uses float for simplicity. For very small MCUs, this can be converted
 *   to fixed-point.
 * - Baseline update is frozen during anomaly events to avoid contaminating
 *   the normal model.
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Low-pass filtered axes
    float fx;
    float fy;
    float fz;

    // Baseline stats for magnitude
    float mean;
    float var;

    // Configuration
    float lpf_alpha;          // 0..1, higher = more responsive
    float stats_alpha;        // 0..1, higher = faster adaptation
    float z_threshold;        // anomaly threshold
    float min_stddev;         // floor to avoid divide-by-zero
    uint32_t warmup_samples;  // number of samples before detection is active
    uint32_t cooldown_samples;// suppress repeated alerts after anomaly

    // State
    uint32_t sample_count;
    uint32_t cooldown_remaining;
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float zscore;
    float mean;
    float stddev;
} DetectionResult;

/* Initialize detector with reasonable defaults */
void anomaly_detector_init(AnomalyDetector *d)
{
    d->fx = 0.0f;
    d->fy = 0.0f;
    d->fz = 0.0f;

    d->mean = 0.0f;
    d->var = 1e-4f;

    d->lpf_alpha = 0.2f;
    d->stats_alpha = 0.01f;
    d->z_threshold = 4.0f;
    d->min_stddev = 0.02f;
    d->warmup_samples = 100;
    d->cooldown_samples = 25;

    d->sample_count = 0;
    d->cooldown_remaining = 0;
    d->initialized = false;
}

/* Optional config helper */
void anomaly_detector_configure(
    AnomalyDetector *d,
    float lpf_alpha,
    float stats_alpha,
    float z_threshold,
    float min_stddev,
    uint32_t warmup_samples,
    uint32_t cooldown_samples)
{
    d->lpf_alpha = lpf_alpha;
    d->stats_alpha = stats_alpha;
    d->z_threshold = z_threshold;
    d->min_stddev = min_stddev;
    d->warmup_samples = warmup_samples;
    d->cooldown_samples = cooldown_samples;
}

/* Fast magnitude approximation option:
 * uncomment to use approximation instead of sqrtf for lower CPU cost.
 */
// static float fast_magnitude(float x, float y, float z)
// {
//     x = fabsf(x); y = fabsf(y); z = fabsf(z);
//     float maxv = x;
//     if (y > maxv) maxv = y;
//     if (z > maxv) maxv = z;
//     return maxv + 0.25f * (x + y + z - maxv);
// }

static float exact_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* Process one accelerometer sample */
DetectionResult anomaly_detector_process(AnomalyDetector *d, AccelSample s)
{
    DetectionResult result = {0};

    if (!d->initialized) {
        d->fx = s.x;
        d->fy = s.y;
        d->fz = s.z;

        float mag0 = exact_magnitude(d->fx, d->fy, d->fz);
        d->mean = mag0;
        d->var = 1e-4f;
        d->initialized = true;
    } else {
        // Low-pass filter each axis
        d->fx += d->lpf_alpha * (s.x - d->fx);
        d->fy += d->lpf_alpha * (s.y - d->fy);
        d->fz += d->lpf_alpha * (s.z - d->fz);
    }

    float mag = exact_magnitude(d->fx, d->fy, d->fz);
    float stddev = sqrtf(d->var);
    if (stddev < d->min_stddev) {
        stddev = d->min_stddev;
    }

    float z = (mag - d->mean) / stddev;
    if (z < 0.0f) {
        z = -z;
    }

    bool anomaly = false;

    // Detection only after warmup and if not in cooldown
    if (d->sample_count >= d->warmup_samples && d->cooldown_remaining == 0) {
        if (z >= d->z_threshold) {
            anomaly = true;
            d->cooldown_remaining = d->cooldown_samples;
        }
    }

    // Update baseline only when not anomalous
    if (!anomaly) {
        float a = d->stats_alpha;
        float delta = mag - d->mean;
        d->mean += a * delta;

        // Exponential moving variance estimate
        float delta2 = mag - d->mean;
        d->var = (1.0f - a) * d->var + a * delta * delta2;

        if (d->var < 1e-8f) {
            d->var = 1e-8f;
        }
    }

    if (d->cooldown_remaining > 0) {
        d->cooldown_remaining--;
    }

    d->sample_count++;

    result.anomaly = anomaly;
    result.magnitude = mag;
    result.zscore = z;
    result.mean = d->mean;
    result.stddev = stddev;

    return result;
}
```

