## Design

Pipeline:

1. Read accelerometer sample `(ax, ay, az)`
2. Compute signal magnitude
3. Smooth magnitude to estimate baseline
4. Compute deviation from baseline
5. Track recent average deviation
6. Trigger anomaly if deviation is much larger than normal background

This works for shocks, impacts, unusual vibration spikes, or sudden motion changes.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
} AccelSample;

// Output of anomaly detector
typedef struct {
    bool anomaly;
    uint32_t score;      // larger means more abnormal
    uint32_t magnitude;  // current accel magnitude estimate
    uint32_t deviation;  // deviation from baseline
} AnomalyResult;

typedef struct {
    // Exponential moving average baseline of magnitude
    uint32_t baseline;

    // Exponential moving average of absolute deviation
    uint32_t noise_floor;

    // Cooldown to avoid repeated triggers
    uint16_t cooldown;

    // Configuration
    uint8_t baseline_shift;   // larger = slower baseline update
    uint8_t noise_shift;      // larger = slower noise estimate
    uint16_t threshold_mult;  // threshold = noise_floor * threshold_mult / 16
    uint32_t min_threshold;   // absolute minimum threshold
    uint16_t cooldown_period; // samples to suppress after trigger

    bool initialized;
} AnomalyDetector;

static inline uint32_t abs32(int32_t x) {
    return (x < 0) ? (uint32_t)(-x) : (uint32_t)x;
}

/*
 * Fast magnitude approximation:
 * Instead of sqrt(ax^2 + ay^2 + az^2), use:
 * max + 1/2 mid + 1/4 min
 * This is cheap and works well for embedded anomaly detection.
 */
static uint32_t accel_magnitude_approx(int16_t ax, int16_t ay, int16_t az) {
    uint32_t x = abs32(ax);
    uint32_t y = abs32(ay);
    uint32_t z = abs32(az);

    uint32_t max = x, mid = y, min = z;

    // Sort x,y,z into max >= mid >= min
    if (max < mid) { uint32_t t = max; max = mid; mid = t; }
    if (mid < min) { uint32_t t = mid; mid = min; min = t; }
    if (max < mid) { uint32_t t = max; max = mid; mid = t; }

    return max + (mid >> 1) + (min >> 2);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0;
    det->noise_floor = 0;
    det->cooldown = 0;

    // Tunable parameters
    det->baseline_shift = 5;    // EMA alpha = 1/32
    det->noise_shift = 4;       // EMA alpha = 1/16
    det->threshold_mult = 48;   // 48/16 = 3.0x noise floor
    det->min_threshold = 200;   // minimum trigger threshold
    det->cooldown_period = 20;  // suppress for 20 samples after anomaly

    det->initialized = false;
}

AnomalyResult anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    AnomalyResult result = {0};

    uint32_t mag = accel_magnitude_approx(s.ax, s.ay, s.az);
    result.magnitude = mag;

    if (!det->initialized) {
        det->baseline = mag;
        det->noise_floor = 1;
        det->initialized = true;
        result.anomaly = false;
        result.score = 0;
        result.deviation = 0;
        return result;
    }

    // Update baseline (slow-changing estimate of nominal acceleration magnitude)
    // baseline += (mag - baseline) / 2^baseline_shift
    det->baseline += ((int32_t)mag - (int32_t)det->baseline) >> det->baseline_shift;

    uint32_t deviation = abs32((int32_t)mag - (int32_t)det->baseline);
    result.deviation = deviation;

    // Update noise floor from deviation
    det->noise_floor += ((int32_t)deviation - (int32_t)det->noise_floor) >> det->noise_shift;

    uint32_t dynamic_threshold = (det->noise_floor * det->threshold_mult) >> 4;
    if (dynamic_threshold < det->min_threshold) {
        dynamic_threshold = det->min_threshold;
    }

    // Score is normalized by threshold
    result.score = (dynamic_threshold > 0) ? (deviation * 100U / dynamic_threshold) : 0;

    if (det->cooldown > 0) {
        det->cooldown--;
    }

    if (deviation > dynamic_threshold && det->cooldown == 0) {
        result.anomaly = true;
        det->cooldown = det->cooldown_period;
    } else {
        result.anomaly = false;
    }

    return result;
}
```

