    det->noise_floor = 0;
    det->cooldown = 0;

    det->baseline_shift = 5;
    det->noise_shift = 4;
    det->threshold_mult = 48;
    det->min_threshold = 200;
    det->cooldown_period = 20;

    det->exceed_count = 0;
    det->exceed_required = 2;

    det->initialized = false;
}

AnomalyResult anomaly_detector2_process(AnomalyDetector2 *det, AccelSample s) {
    AnomalyResult result = {0};

    uint32_t mag = accel_magnitude_approx(s.ax, s.ay, s.az);
    result.magnitude = mag;

    if (!det->initialized) {
        det->baseline = mag;
        det->noise_floor = 1;
        det->initialized = true;
        return result;
    }

    det->baseline += ((int32_t)mag - (int32_t)det->baseline) >> det->baseline_shift;
    uint32_t deviation = abs32((int32_t)mag - (int32_t)det->baseline);
    result.deviation = deviation;

    det->noise_floor += ((int32_t)deviation - (int32_t)det->noise_floor) >> det->noise_shift;

    uint32_t dynamic_threshold = (det->noise_floor * det->threshold_mult) >> 4;
    if (dynamic_threshold < det->min_threshold) {
        dynamic_threshold = det->min_threshold;
    }

    result.score = (deviation * 100U) / dynamic_threshold;

    if (deviation > dynamic_threshold) {
        if (det->exceed_count < 255) det->exceed_count++;
    } else {
        det->exceed_count = 0;
    }

    if (det->cooldown > 0) {
        det->cooldown--;
    }

    if (det->exceed_count >= det->exceed_required && det->cooldown == 0) {
        result.anomaly = true;
        det->cooldown = det->cooldown_period;
        det->exceed_count = 0;
    }

    return result;
