Below is a compact, embedded-friendly C implementation of an accelerometer anomaly-detection pipeline suitable for MCUs.

It includes:

- 3-axis accelerometer sample input
- DC removal / smoothing with IIR low-pass
- Magnitude approximation
- Rolling mean and variance
- Anomaly score via z-score
- Threshold + cooldown logic
- Optional spike and motion anomaly detection

You can adapt it for Arduino, STM32, ESP32, or bare-metal systems.

---

## Design goals

For embedded use, the pipeline should be:

- lightweight
- streaming, one sample at a time
- no dynamic allocation
- numerically stable
- easy to tune

This example assumes fixed-rate accelerometer samples, e.g. 100 Hz.

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - IIR low-pass filtering per axis
 * - Magnitude computation
 * - Rolling mean/variance over magnitude
 * - Z-score anomaly detection
 * - Cooldown to avoid repeated triggers
 *
 * Assumptions:
 * - Sampling at fixed rate
 * - Input units in g or m/s^2, but must be consistent
 * - Floating point available; can be converted to fixed-point if needed
 */

#ifndef ABSF
#define ABSF(x) (((x) < 0.0f) ? -(x) : (x))
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Low-pass filtered axes
    float fx;
    float fy;
    float fz;

    // Rolling statistics
    float mean;
    float m2;          // variance accumulator
    uint32_t count;

    // Exponential stats alternative for embedded stability
    float ema_mean;
    float ema_var;

    // Config
    float lpf_alpha;           // 0..1, higher = more responsive
    float stats_alpha;         // EMA alpha for mean/variance
    float z_threshold;         // anomaly threshold
    float spike_threshold;     // instantaneous change threshold
    uint32_t warmup_samples;   // ignore anomalies before enough data
    uint32_t cooldown_samples; // refractory period after anomaly

    // State
    float prev_mag;
    uint32_t cooldown;
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    bool spike_anomaly;
    bool motion_anomaly;
    float magnitude;
    float filtered_x;
    float filtered_y;
    float filtered_z;
    float mean;
    float stddev;
    float z_score;
} AnomalyResult;

/* Initialize detector with recommended defaults for ~100 Hz sampling */
void anomaly_detector_init(AnomalyDetector *det)
{
    if (!det) return;

    det->fx = 0.0f;
    det->fy = 0.0f;
    det->fz = 0.0f;

    det->mean = 0.0f;
    det->m2 = 0.0f;
    det->count = 0;

    det->ema_mean = 0.0f;
    det->ema_var = 1e-6f;

    det->lpf_alpha = 0.2f;         // tune based on noise and dynamics
    det->stats_alpha = 0.02f;      // slower adaptation for baseline
    det->z_threshold = 4.0f;       // common anomaly threshold
    det->spike_threshold = 0.8f;   // tune to sensor scale
    det->warmup_samples = 50;
    det->cooldown_samples = 20;

    det->prev_mag = 0.0f;
    det->cooldown = 0;
    det->initialized = false;
}

/* Simple low-pass filter */
static float iir_lpf(float prev, float input, float alpha)
{
    return prev + alpha * (input - prev);
}

/* Fast magnitude approximation to reduce sqrt cost if desired */
static float accel_magnitude_approx(float x, float y, float z)
{
    // Accurate version:
    return sqrtf(x * x + y * y + z * z);

    /*
    // Faster approximation option:
    float ax = ABSF(x), ay = ABSF(y), az = ABSF(z);
    float max1 = ax;
    if (ay > max1) max1 = ay;
    if (az > max1) max1 = az;

    float sum = ax + ay + az;
    return max1 + 0.25f * (sum - max1);
    */
}

/* Process one sample */
AnomalyResult anomaly_detector_process(AnomalyDetector *det, AccelSample s)
{
    AnomalyResult out = {0};

    if (!det) return out;

    if (!det->initialized) {
        det->fx = s.x;
        det->fy = s.y;
        det->fz = s.z;
        det->initialized = true;
    }

    // 1. Low-pass filter each axis
    det->fx = iir_lpf(det->fx, s.x, det->lpf_alpha);
    det->fy = iir_lpf(det->fy, s.y, det->lpf_alpha);
    det->fz = iir_lpf(det->fz, s.z, det->lpf_alpha);

    // 2. Compute filtered magnitude
    float mag = accel_magnitude_approx(det->fx, det->fy, det->fz);

    // 3. Update EMA mean and variance
    // Mean
    float delta = mag - det->ema_mean;
    det->ema_mean += det->stats_alpha * delta;

    // Variance (EMA of squared residual)
    float residual = mag - det->ema_mean;
    det->ema_var = (1.0f - det->stats_alpha) * det->ema_var
                 + det->stats_alpha * residual * residual;

    // Prevent degenerate stddev
    if (det->ema_var < 1e-8f) {
        det->ema_var = 1e-8f;
    }

    float stddev = sqrtf(det->ema_var);
    float z = (mag - det->ema_mean) / stddev;

    // 4. Instantaneous spike detection
    float dmag = mag - det->prev_mag;
    if (dmag < 0.0f) dmag = -dmag;
    bool spike = (dmag > det->spike_threshold);

    // 5. Sustained motion anomaly
    bool motion = (ABSF(z) > det->z_threshold);

    // 6. Warmup + cooldown logic
    if (det->count < det->warmup_samples) {
        motion = false;
        spike = false;
    }

    if (det->cooldown > 0) {
        det->cooldown--;
        motion = false;
        spike = false;
    }

    bool anomaly = spike || motion;
    if (anomaly) {
        det->cooldown = det->cooldown_samples;
    }

    det->prev_mag = mag;
    det->count++;

    out.anomaly = anomaly;
    out.spike_anomaly = spike;
    out.motion_anomaly = motion;
    out.magnitude = mag;
    out.filtered_x = det->fx;
    out.filtered_y = det->fy;
    out.filtered_z = det->fz;
    out.mean = det->ema_mean;
    out.stddev = stddev;
    out.z_score = z;

    return out;
}
```

