Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- streaming sample input `(ax, ay, az)`
- magnitude estimation
- simple low-pass baseline tracking
- high-pass residual extraction
- rolling noise estimate
- anomaly score with thresholding
- debounce / persistence logic to reduce false positives

You can adapt it for bare metal, RTOS, or Arduino-style environments.

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *  1. Read raw accelerometer sample (x, y, z)
 *  2. Compute magnitude
 *  3. Low-pass filter magnitude to estimate baseline
 *  4. Compute residual = |magnitude - baseline|
 *  5. Estimate noise floor using EWMA
 *  6. Flag anomaly if residual exceeds adaptive threshold
 *  7. Require persistence for N samples before declaring anomaly
 *
 * Notes:
 *  - Uses floats for clarity. For small MCUs, can be converted to fixed-point.
 *  - Assumes constant sample rate.
 */

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    // Filter state
    float baseline_mag;     // low-pass estimate of acceleration magnitude
    float noise_est;        // EWMA estimate of residual/noise
    float last_residual;

    // Parameters
    float alpha_baseline;   // low-pass coefficient for baseline
    float alpha_noise;      // low-pass coefficient for noise estimate
    float threshold_k;      // adaptive threshold multiplier
    float min_threshold;    // minimum threshold floor
    uint16_t persist_count_required;

    // Detection state
    uint16_t persist_count;
    bool anomaly_active;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float baseline;
    float residual;
    float threshold;
    float noise_est;
} DetectionResult;

/* Fast magnitude helper
 * If sqrtf is too expensive, replace with approximation or squared magnitude logic.
 */
static inline float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

void anomaly_detector_init(AnomalyDetector *det,
                           float alpha_baseline,
                           float alpha_noise,
                           float threshold_k,
                           float min_threshold,
                           uint16_t persist_count_required,
                           float initial_baseline,
                           float initial_noise)
{
    det->baseline_mag = initial_baseline;
    det->noise_est = initial_noise;
    det->last_residual = 0.0f;

    det->alpha_baseline = alpha_baseline;
    det->alpha_noise = alpha_noise;
    det->threshold_k = threshold_k;
    det->min_threshold = min_threshold;
    det->persist_count_required = persist_count_required;

    det->persist_count = 0;
    det->anomaly_active = false;
}

DetectionResult anomaly_detector_process(AnomalyDetector *det, const AccelSample *sample) {
    DetectionResult result = {0};

    // 1. Compute magnitude
    float mag = accel_magnitude(sample);

    // 2. Update low-pass baseline estimate
    // baseline <- baseline + alpha * (mag - baseline)
    det->baseline_mag += det->alpha_baseline * (mag - det->baseline_mag);

    // 3. Residual from baseline
    float residual = fabsf(mag - det->baseline_mag);

    // 4. Update noise estimate from residual
    det->noise_est += det->alpha_noise * (residual - det->noise_est);

    // 5. Adaptive threshold
    float threshold = det->threshold_k * det->noise_est;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    // 6. Persistence logic
    if (residual > threshold) {
        if (det->persist_count < det->persist_count_required) {
            det->persist_count++;
        }
    } else {
        det->persist_count = 0;
        det->anomaly_active = false;
    }

    if (det->persist_count >= det->persist_count_required) {
        det->anomaly_active = true;
    }

    det->last_residual = residual;

    result.anomaly = det->anomaly_active;
    result.magnitude = mag;
    result.baseline = det->baseline_mag;
    result.residual = residual;
    result.threshold = threshold;
    result.noise_est = det->noise_est;

    return result;
}
```

