        DetectionResult r = anomaly_detector_process(&detector, &samples[i]);

        printf("i=%u mag=%.3f base=%.3f resid=%.3f thr=%.3f noise=%.3f anomaly=%d\n",
               (unsigned)i,
               r.magnitude,
               r.baseline,
               r.residual,
               r.threshold,
               r.noise_est,
               r.anomaly ? 1 : 0);
    }

    return 0;
}
```

