## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *   1. Read raw accel sample (x, y, z)
 *   2. Low-pass filter each axis
 *   3. Compute magnitude
 *   4. Maintain rolling baseline statistics
 *   5. Detect anomaly using z-score and threshold logic
 *
 * Notes:
 *   - Replace sqrtf if too expensive with approximation or squared magnitude.
 *   - Tune constants for your sensor/sample rate/use case.
 */

#define WINDOW_SIZE             64
#define MIN_STDDEV              0.02f
#define DEFAULT_Z_THRESHOLD     3.5f
#define DEFAULT_SPIKE_THRESHOLD 2.0f
#define LPF_ALPHA               0.2f
#define REQUIRED_CONSECUTIVE    3

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float values[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sum_sq;
} RollingStats;

typedef struct {
    float alpha;
    float state;
    bool initialized;
} LowPassFilter1D;

typedef struct {
    LowPassFilter1D fx;
    LowPassFilter1D fy;
    LowPassFilter1D fz;

    RollingStats mag_stats;

    float z_threshold;
    float spike_threshold;
    uint8_t consecutive_anomaly_count;
    uint8_t required_consecutive;

    bool anomaly_active;
} AnomalyDetector;

/* ---------------- Low-pass filter ---------------- */

static void lpf_init(LowPassFilter1D *f, float alpha) {
    f->alpha = alpha;
    f->state = 0.0f;
    f->initialized = false;
}

static float lpf_update(LowPassFilter1D *f, float input) {
    if (!f->initialized) {
        f->state = input;
        f->initialized = true;
    } else {
        f->state = f->alpha * input + (1.0f - f->alpha) * f->state;
    }
    return f->state;
}

/* ---------------- Rolling statistics ---------------- */

static void rolling_stats_init(RollingStats *rs) {
    memset(rs->values, 0, sizeof(rs->values));
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    rs->sum_sq = 0.0f;
}

static void rolling_stats_update(RollingStats *rs, float x) {
    if (rs->count < WINDOW_SIZE) {
        rs->values[rs->index] = x;
        rs->sum += x;
        rs->sum_sq += x * x;
        rs->count++;
    } else {
        float old = rs->values[rs->index];
        rs->sum -= old;
        rs->sum_sq -= old * old;

        rs->values[rs->index] = x;
        rs->sum += x;
        rs->sum_sq += x * x;
    }

    rs->index = (rs->index + 1) % WINDOW_SIZE;
}

static float rolling_stats_mean(const RollingStats *rs) {
    if (rs->count == 0) return 0.0f;
    return rs->sum / (float)rs->count;
}

static float rolling_stats_variance(const RollingStats *rs) {
    if (rs->count < 2) return 0.0f;

    float mean = rolling_stats_mean(rs);
    float var = (rs->sum_sq / (float)rs->count) - (mean * mean);
    return (var > 0.0f) ? var : 0.0f;
}

static float rolling_stats_stddev(const RollingStats *rs) {
    float var = rolling_stats_variance(rs);
    float stddev = sqrtf(var);
    return (stddev < MIN_STDDEV) ? MIN_STDDEV : stddev;
}

/* ---------------- Detector ---------------- */

void anomaly_detector_init(AnomalyDetector *det) {
    lpf_init(&det->fx, LPF_ALPHA);
    lpf_init(&det->fy, LPF_ALPHA);
    lpf_init(&det->fz, LPF_ALPHA);

    rolling_stats_init(&det->mag_stats);

    det->z_threshold = DEFAULT_Z_THRESHOLD;
    det->spike_threshold = DEFAULT_SPIKE_THRESHOLD;
    det->consecutive_anomaly_count = 0;
    det->required_consecutive = REQUIRED_CONSECUTIVE;
    det->anomaly_active = false;
}

/*
 * Returns true when anomaly detected on this sample.
 *
 * raw sample units can be g, m/s^2, or sensor counts if consistent.
 */
bool anomaly_detector_update(AnomalyDetector *det,
                             const AccelSample *raw,
                             float *out_magnitude,
                             float *out_zscore)
{
    /* 1. Filter axes */
    float fx = lpf_update(&det->fx, raw->x);
    float fy = lpf_update(&det->fy, raw->y);
    float fz = lpf_update(&det->fz, raw->z);

    /* 2. Magnitude */
    float mag = sqrtf(fx * fx + fy * fy + fz * fz);

    if (out_magnitude) {
        *out_magnitude = mag;
    }

    /* Need some baseline before meaningful detection */
    float mean = rolling_stats_mean(&det->mag_stats);
    float stddev = rolling_stats_stddev(&det->mag_stats);

    float z = 0.0f;
    if (det->mag_stats.count >= 8) {
        z = (mag - mean) / stddev;
    }

    if (out_zscore) {
        *out_zscore = z;
    }

    /* 3. Detection logic */
    bool spike = false;
    bool anomaly = false;

    if (det->mag_stats.count >= 8) {
        if (fabsf(mag - mean) > det->spike_threshold) {
            spike = true;
        }

        if (fabsf(z) > det->z_threshold || spike) {
            det->consecutive_anomaly_count++;
        } else {
            det->consecutive_anomaly_count = 0;
        }

        if (det->consecutive_anomaly_count >= det->required_consecutive) {
            anomaly = true;
            det->anomaly_active = true;
        } else {
            det->anomaly_active = false;
        }
    }

    /* 4. Update baseline after detection
     *
     * In some systems you may want to avoid learning anomalous samples.
     * For now, only update stats when not in active anomaly.
     */
    if (!anomaly) {
        rolling_stats_update(&det->mag_stats, mag);
    }

    return anomaly;
}
