```c
typedef struct {
    float alpha;
    float prev_input;
    float prev_output;
    bool initialized;
} HighPassFilter1D;

static void hpf_init(HighPassFilter1D *f, float alpha) {
    f->alpha = alpha;
    f->prev_input = 0.0f;
    f->prev_output = 0.0f;
    f->initialized = false;
}

static float hpf_update(HighPassFilter1D *f, float input) {
    if (!f->initialized) {
        f->prev_input = input;
        f->prev_output = 0.0f;
        f->initialized = true;
        return 0.0f;
    }

    float output = f->alpha * (f->prev_output + input - f->prev_input);
    f->prev_input = input;
    f->prev_output = output;
    return output;
}
```

Then compute anomaly score from the high-pass filtered axes.

