## C code

```c
/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Streaming processing
 * - Low-pass baseline estimation
 * - Residual (high-pass) extraction
 * - Energy smoothing
 * - Adaptive noise floor tracking
 * - Threshold-based anomaly detection with debounce/cooldown
 *
 * Suitable for:
 * - vibration anomaly detection
 * - impact detection
 * - unusual motion detection
 *
 * Notes:
 * - Uses float for clarity. Can be converted to fixed-point for smaller MCUs.
 * - Assumes samples arrive at a fixed rate.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*========================
  Configuration
========================*/

#ifndef ABSF
#define ABSF(x) ((x) < 0.0f ? -(x) : (x))
#endif

typedef struct {
    float alpha_baseline;     // LPF coefficient for baseline magnitude
    float alpha_energy;       // LPF coefficient for residual energy
    float alpha_noise;        // LPF coefficient for noise floor
    float threshold_k;        // threshold = noise_floor * k + offset
    float threshold_offset;   // minimum threshold offset
    uint16_t anomaly_hold;    // number of samples to hold anomaly active
    uint16_t cooldown;        // samples to suppress retrigger after anomaly
    float clip_limit;         // optional clipping limit for magnitude
} AnomalyConfig;

/*========================
  State
========================*/

typedef struct {
    bool initialized;

    float baseline_mag;       // low-pass estimate of |a|
    float residual;           // current high-pass residual
    float energy;             // smoothed abs residual
    float noise_floor;        // adaptive noise estimate

    uint16_t hold_counter;    // anomaly active hold
    uint16_t cooldown_counter;
    bool anomaly_active;
} AnomalyState;

typedef struct {
    bool anomaly;
    float magnitude;
    float baseline;
    float residual;
    float energy;
    float threshold;
    float noise_floor;
} AnomalyOutput;

/*========================
  Utility
========================*/

static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float accel_magnitude(float ax, float ay, float az) {
    return fast_sqrtf(ax * ax + ay * ay + az * az);
}

static inline float lpf_update(float prev, float x, float alpha) {
    return prev + alpha * (x - prev);
}

/*========================
  Initialization
========================*/

void anomaly_init(AnomalyState *st, const AnomalyConfig *cfg) {
    (void)cfg;
    st->initialized = false;
    st->baseline_mag = 0.0f;
    st->residual = 0.0f;
    st->energy = 0.0f;
    st->noise_floor = 0.0f;
    st->hold_counter = 0;
    st->cooldown_counter = 0;
    st->anomaly_active = false;
}

/*========================
  Processing
========================*/

AnomalyOutput anomaly_process_sample(
    AnomalyState *st,
    const AnomalyConfig *cfg,
    float ax,
    float ay,
    float az
) {
    AnomalyOutput out = {0};

    /* 1) Compute acceleration magnitude */
    float mag = accel_magnitude(ax, ay, az);

    /* Optional clipping against outliers / sensor glitches */
    if (cfg->clip_limit > 0.0f && mag > cfg->clip_limit) {
        mag = cfg->clip_limit;
    }

    /* 2) Initialize filters on first sample */
    if (!st->initialized) {
        st->baseline_mag = mag;
        st->residual = 0.0f;
        st->energy = 0.0f;
        st->noise_floor = 0.0f;
        st->initialized = true;
    }

    /* 3) Low-pass baseline tracks normal gravity + slow movement */
    st->baseline_mag = lpf_update(st->baseline_mag, mag, cfg->alpha_baseline);

    /* 4) High-pass residual captures sudden changes */
    st->residual = mag - st->baseline_mag;

    /* 5) Smoothed residual energy */
    float abs_res = ABSF(st->residual);
    st->energy = lpf_update(st->energy, abs_res, cfg->alpha_energy);

    /*
     * 6) Adaptive noise floor update
     * Update more conservatively during active anomaly to avoid threshold inflation.
     */
    if (!st->anomaly_active) {
        st->noise_floor = lpf_update(st->noise_floor, st->energy, cfg->alpha_noise);
    } else {
        /* very slow adaptation while anomaly is active */
        st->noise_floor = lpf_update(st->noise_floor, st->energy, cfg->alpha_noise * 0.1f);
    }

    /* 7) Dynamic threshold */
    float threshold = st->noise_floor * cfg->threshold_k + cfg->threshold_offset;

    /* 8) Cooldown management */
    if (st->cooldown_counter > 0) {
        st->cooldown_counter--;
    }

    /* 9) Detection logic */
    bool trigger = false;
    if (st->cooldown_counter == 0 && st->energy > threshold) {
        trigger = true;
        st->anomaly_active = true;
        st->hold_counter = cfg->anomaly_hold;
        st->cooldown_counter = cfg->cooldown;
    }

    /* 10) Hold anomaly active for a few samples */
    if (st->hold_counter > 0) {
        st->hold_counter--;
        st->anomaly_active = true;
    } else if (!trigger) {
        st->anomaly_active = false;
    }

    out.anomaly = st->anomaly_active;
    out.magnitude = mag;
    out.baseline = st->baseline_mag;
    out.residual = st->residual;
    out.energy = st->energy;
    out.threshold = threshold;
    out.noise_floor = st->noise_floor;

    return out;
}
```

