## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *  1. Read raw accel x,y,z
 *  2. Remove slow baseline via high-pass approximation
 *  3. Compute signal magnitude
 *  4. Smooth magnitude
 *  5. Track running mean/variance
 *  6. Raise anomaly if z-score exceeds threshold for N samples
 *
 * Notes:
 *  - Uses float for clarity. Can be converted to fixed-point if needed.
 *  - Assumes regular sampling interval.
 */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Baseline tracking for each axis
    float base_x;
    float base_y;
    float base_z;

    // Smoothed magnitude
    float smooth_mag;

    // Running statistics
    float mean;
    float var;

    // Config
    float baseline_alpha;   // e.g. 0.01
    float smooth_alpha;     // e.g. 0.2
    float stats_alpha;      // e.g. 0.01
    float z_thresh;         // e.g. 4.0
    uint16_t debounce_count;// e.g. 3

    // State
    uint16_t anomaly_counter;
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float smoothed;
    float mean;
    float stddev;
    float zscore;
} DetectionResult;

static void anomaly_detector_init(
    AnomalyDetector *det,
    float baseline_alpha,
    float smooth_alpha,
    float stats_alpha,
    float z_thresh,
    uint16_t debounce_count
) {
    det->base_x = 0.0f;
    det->base_y = 0.0f;
    det->base_z = 0.0f;
    det->smooth_mag = 0.0f;
    det->mean = 0.0f;
    det->var = 1e-6f;

    det->baseline_alpha = baseline_alpha;
    det->smooth_alpha = smooth_alpha;
    det->stats_alpha = stats_alpha;
    det->z_thresh = z_thresh;
    det->debounce_count = debounce_count;

    det->anomaly_counter = 0;
    det->initialized = false;
}

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static DetectionResult anomaly_detector_process(
    AnomalyDetector *det,
    AccelSample s
) {
    DetectionResult out = {0};

    if (!det->initialized) {
        det->base_x = s.x;
        det->base_y = s.y;
        det->base_z = s.z;

        det->smooth_mag = 0.0f;
        det->mean = 0.0f;
        det->var = 1e-3f;
        det->initialized = true;
    }

    // 1. Track slow baseline (gravity / mounting offset / drift)
    det->base_x += det->baseline_alpha * (s.x - det->base_x);
    det->base_y += det->baseline_alpha * (s.y - det->base_y);
    det->base_z += det->baseline_alpha * (s.z - det->base_z);

    // 2. High-pass output
    float hx = s.x - det->base_x;
    float hy = s.y - det->base_y;
    float hz = s.z - det->base_z;

    // 3. Magnitude
    float mag = fast_sqrtf(hx * hx + hy * hy + hz * hz);

    // 4. Smooth magnitude
    det->smooth_mag += det->smooth_alpha * (mag - det->smooth_mag);

    // 5. Running mean and variance (EMA-based)
    float delta = det->smooth_mag - det->mean;
    det->mean += det->stats_alpha * delta;

    float delta2 = det->smooth_mag - det->mean;
    det->var = (1.0f - det->stats_alpha) * det->var + det->stats_alpha * delta * delta2;

    if (det->var < 1e-8f) {
        det->var = 1e-8f;
    }

    float stddev = fast_sqrtf(det->var);
    float z = (det->smooth_mag - det->mean) / stddev;

    // 6. Debounced anomaly detection
    if (z > det->z_thresh) {
        if (det->anomaly_counter < 0xFFFF) {
            det->anomaly_counter++;
        }
    } else {
        det->anomaly_counter = 0;
    }

    out.anomaly = (det->anomaly_counter >= det->debounce_count);
    out.magnitude = mag;
    out.smoothed = det->smooth_mag;
    out.mean = det->mean;
    out.stddev = stddev;
    out.zscore = z;

    return out;
}
```

