## C code

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Running mean for crude gravity/DC removal
    float mean_x;
    float mean_y;
    float mean_z;

    // Smoothed signal energy
    float ema_signal;

    // Baseline noise estimate
    float ema_baseline;
    float ema_deviation;

    // Detection state
    uint16_t anomaly_count;
    uint16_t clear_count;
    bool anomaly_active;

    // Config
    float mean_alpha;         // e.g. 0.01
    float signal_alpha;       // e.g. 0.2
    float baseline_alpha;     // e.g. 0.01
    float deviation_alpha;    // e.g. 0.01
    float threshold_k;        // e.g. 4.0
    float min_threshold;      // e.g. 0.05
    uint16_t trigger_samples; // e.g. 3
    uint16_t clear_samples;   // e.g. 10
} AnomalyDetector;

static float fast_absf(float v) {
    return (v < 0.0f) ? -v : v;
}

// Embedded-friendly magnitude approximation.
// Avoids sqrtf() to reduce cost.
// Approx ~= max + 0.5*mid + 0.25*min
static float approx_magnitude(float ax, float ay, float az) {
    float x = fast_absf(ax);
    float y = fast_absf(ay);
    float z = fast_absf(az);

    float max = x, mid = y, min = z;

    if (max < mid) { float t = max; max = mid; mid = t; }
    if (mid < min) { float t = mid; mid = min; min = t; }
    if (max < mid) { float t = max; max = mid; mid = t; }

    return max + 0.5f * mid + 0.25f * min;
}

void anomaly_init(AnomalyDetector *det) {
    det->mean_x = 0.0f;
    det->mean_y = 0.0f;
    det->mean_z = 0.0f;

    det->ema_signal = 0.0f;
    det->ema_baseline = 0.0f;
    det->ema_deviation = 0.0f;

    det->anomaly_count = 0;
    det->clear_count = 0;
    det->anomaly_active = false;

    det->mean_alpha = 0.01f;
    det->signal_alpha = 0.2f;
    det->baseline_alpha = 0.01f;
    det->deviation_alpha = 0.01f;
    det->threshold_k = 4.0f;
    det->min_threshold = 0.05f;
    det->trigger_samples = 3;
    det->clear_samples = 10;
}

// Returns true only when anomaly state is currently active.
// If you want edge-triggered events only, see anomaly_process_event().
bool anomaly_process(AnomalyDetector *det, AccelSample s) {
    // Update running mean (tracks gravity / slow drift)
    det->mean_x += det->mean_alpha * (s.x - det->mean_x);
    det->mean_y += det->mean_alpha * (s.y - det->mean_y);
    det->mean_z += det->mean_alpha * (s.z - det->mean_z);

    // High-pass-ish residual
    float hx = s.x - det->mean_x;
    float hy = s.y - det->mean_y;
    float hz = s.z - det->mean_z;

    // Motion intensity
    float mag = approx_magnitude(hx, hy, hz);

    // Smooth signal
    det->ema_signal += det->signal_alpha * (mag - det->ema_signal);

    // Track baseline and deviation
    det->ema_baseline += det->baseline_alpha * (det->ema_signal - det->ema_baseline);

    float err = fast_absf(det->ema_signal - det->ema_baseline);
    det->ema_deviation += det->deviation_alpha * (err - det->ema_deviation);

    float threshold = det->ema_baseline + det->threshold_k * det->ema_deviation;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    bool over = det->ema_signal > threshold;

    if (over) {
        if (det->anomaly_count < 65535) det->anomaly_count++;
        det->clear_count = 0;

        if (!det->anomaly_active && det->anomaly_count >= det->trigger_samples) {
            det->anomaly_active = true;
        }
    } else {
        det->anomaly_count = 0;
        if (det->anomaly_active) {
            if (det->clear_count < 65535) det->clear_count++;
            if (det->clear_count >= det->clear_samples) {
                det->anomaly_active = false;
                det->clear_count = 0;
            }
        }
    }

    return det->anomaly_active;
}

// Edge-triggered version: returns true only when a new anomaly starts.
bool anomaly_process_event(AnomalyDetector *det, AccelSample s) {
    bool was_active = det->anomaly_active;
    bool is_active = anomaly_process(det, s);
    return (!was_active && is_active);
}
