## Design

Pipeline:

1. Read accelerometer sample `(ax, ay, az)`
2. Compute signal magnitude
3. Track slow baseline with EMA
4. Compute residual = `|magnitude - baseline|`
5. Track residual noise floor
6. Trigger anomaly if residual exceeds adaptive threshold for N samples

This is lightweight and practical for embedded systems.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
} AccelSample;

typedef struct {
    // Baseline tracking
    float baseline;
    float baseline_alpha;   // e.g. 0.01

    // Noise estimation
    float noise_est;
    float noise_alpha;      // e.g. 0.02

    // Detection
    float threshold_k;      // multiplier for adaptive threshold
    float min_threshold;    // absolute minimum threshold
    uint8_t trigger_count;  // consecutive samples above threshold
    uint8_t trigger_limit;  // required consecutive hits
    uint8_t cooldown;       // optional refractory period
    uint8_t cooldown_count;

    // State
    bool initialized;
    bool anomaly;
} AnomalyDetector;

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

// Cheap magnitude approximation for embedded use.
// Avoids sqrt(ax^2 + ay^2 + az^2).
// Good enough for anomaly detection.
static float approx_magnitude(int16_t ax, int16_t ay, int16_t az) {
    float x = (float)abs(ax);
    float y = (float)abs(ay);
    float z = (float)abs(az);

    // Sort so x >= y >= z
    float t;
    if (x < y) { t = x; x = y; y = t; }
    if (y < z) { t = y; y = z; z = t; }
    if (x < y) { t = x; x = y; y = t; }

    // Approximation to Euclidean norm
    return x + 0.5f * y + 0.25f * z;
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0.0f;
    det->baseline_alpha = 0.01f;

    det->noise_est = 0.0f;
    det->noise_alpha = 0.02f;

    det->threshold_k = 4.0f;
    det->min_threshold = 100.0f;

    det->trigger_count = 0;
    det->trigger_limit = 3;

    det->cooldown = 10;
    det->cooldown_count = 0;

    det->initialized = false;
    det->anomaly = false;
}

// Returns true when anomaly detected on this sample
bool anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    float mag = approx_magnitude(s.ax, s.ay, s.az);

    if (!det->initialized) {
        det->baseline = mag;
        det->noise_est = 0.0f;
        det->initialized = true;
        det->anomaly = false;
        return false;
    }

    // Slow baseline update
    det->baseline += det->baseline_alpha * (mag - det->baseline);

    // Residual from baseline
    float residual = fast_absf(mag - det->baseline);

    // Track noise floor using EMA of residual
    det->noise_est += det->noise_alpha * (residual - det->noise_est);

    float threshold = det->threshold_k * det->noise_est;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    det->anomaly = false;

    if (det->cooldown_count > 0) {
        det->cooldown_count--;
        det->trigger_count = 0;
        return false;
    }

    if (residual > threshold) {
        if (det->trigger_count < 255) {
            det->trigger_count++;
        }

        if (det->trigger_count >= det->trigger_limit) {
            det->anomaly = true;
            det->trigger_count = 0;
            det->cooldown_count = det->cooldown;
            return true;
        }
    } else {
        det->trigger_count = 0;
    }

    return false;
}
```

