bool anomaly_detector_process_freeze(AnomalyDetector *det, AccelSample s) {
    float mag = approx_magnitude(s.ax, s.ay, s.az);

    if (!det->initialized) {
        det->baseline = mag;
        det->noise_est = 0.0f;
