## Approach

A practical embedded anomaly detector often works like this:

1. Read accelerometer samples.
2. Convert 3-axis data into a scalar activity measure.
3. Track the normal baseline slowly.
4. Measure deviation from that baseline.
5. Compare deviation to an adaptive threshold based on recent noise.
6. Trigger anomaly if deviation stays large enough.

This avoids expensive ML and works well for:
- impacts
- sudden vibration bursts
- motion spikes
- mechanical faults

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int32_t baseline;          // Slow baseline of magnitude
    int32_t noise_est;         // Estimated normal residual level
    uint16_t anomaly_count;    // Debounce counter
    uint16_t cooldown;         // Holdoff after detection
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    int32_t magnitude;
    int32_t residual;
    int32_t threshold;
} DetectorOutput;

/*
Configuration notes:
- All values are integer-based for embedded efficiency.
- Input accelerometer units can be raw ADC counts or mg.
- Tune these constants for your sensor/sample rate.
*/
enum {
    BASELINE_SHIFT = 6,        // baseline LPF alpha = 1/64
    NOISE_SHIFT    = 5,        // noise LPF alpha = 1/32
    THRESHOLD_MULT = 6,        // threshold = noise_est * 6 + offset
    THRESHOLD_MIN  = 50,       // minimum threshold
    ANOMALY_HITS   = 3,        // consecutive hits required
    COOLDOWN_SAMPLES = 20      // suppress repeated triggers
};

/*
Fast approximate magnitude:
|x| + |y| + |z|
Cheaper than sqrt(x^2 + y^2 + z^2), often good enough for anomaly detection.
*/
static inline int32_t approx_magnitude(int16_t x, int16_t y, int16_t z) {
    return abs(x) + abs(y) + abs(z);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0;
    det->noise_est = THRESHOLD_MIN;
    det->anomaly_count = 0;
    det->cooldown = 0;
    det->initialized = false;
}

DetectorOutput anomaly_detector_process(
    AnomalyDetector *det,
    int16_t ax,
    int16_t ay,
    int16_t az
) {
    DetectorOutput out = {0};

    int32_t mag = approx_magnitude(ax, ay, az);
    out.magnitude = mag;

    if (!det->initialized) {
        det->baseline = mag;
        det->noise_est = THRESHOLD_MIN;
        det->initialized = true;
    }

    // Slow baseline tracking
    det->baseline += (mag - det->baseline) >> BASELINE_SHIFT;

    // High-pass residual: deviation from baseline
    int32_t residual = mag - det->baseline;
    if (residual < 0) residual = -residual;
    out.residual = residual;

    // Track normal residual/noise floor
    det->noise_est += (residual - det->noise_est) >> NOISE_SHIFT;

    // Adaptive threshold
    int32_t threshold = det->noise_est * THRESHOLD_MULT + THRESHOLD_MIN;
    if (threshold < THRESHOLD_MIN) {
        threshold = THRESHOLD_MIN;
    }
    out.threshold = threshold;

    // Cooldown logic
    if (det->cooldown > 0) {
        det->cooldown--;
    }

    // Debounced anomaly detection
    if (residual > threshold && det->cooldown == 0) {
        if (det->anomaly_count < 0xFFFF) {
            det->anomaly_count++;
        }
        if (det->anomaly_count >= ANOMALY_HITS) {
            out.anomaly = true;
            det->anomaly_count = 0;
            det->cooldown = COOLDOWN_SAMPLES;
        }
    } else {
        det->anomaly_count = 0;
        out.anomaly = false;
    }

    return out;
}
```

