## Simple Windowed RMS Variant

If you want, here is a small ring-buffer RMS detector too:

```c
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 16

typedef struct {
    int32_t buf[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    int64_t sum_sq;
} RmsWindow;

void rms_window_init(RmsWindow *w) {
    w->idx = 0;
    w->count = 0;
    w->sum_sq = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->buf[i] = 0;
    }
}

static inline int32_t mag_sq(int16_t x, int16_t y, int16_t z) {
    return (int32_t)x*x + (int32_t)y*y + (int32_t)z*z;
}

int32_t rms_window_update(RmsWindow *w, int16_t x, int16_t y, int16_t z) {
    int32_t v = mag_sq(x, y, z);

    if (w->count < WINDOW_SIZE) {
        w->buf[w->idx] = v;
        w->sum_sq += (int64_t)v * v;
        w->count++;
    } else {
        int32_t old = w->buf[w->idx];
        w->sum_sq -= (int64_t)old * old;
        w->buf[w->idx] = v;
        w->sum_sq += (int64_t)v * v;
    }

    w->idx = (w->idx + 1) % WINDOW_SIZE;

    if (w->count == 0) return 0;
    return (int32_t)(w->sum_sq / w->count);
}
```

That said, the first detector is usually better as a starting point for embedded anomaly detection.

