## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Bias/gravity removal via low-pass filter
 * - Magnitude computation
 * - Exponential moving average for baseline
 * - Exponential moving variance estimate
 * - Threshold-based anomaly detection
 *
 * Assumptions:
 * - Input accelerometer units are in g or m/s^2 consistently
 * - Called at a fixed sample rate
 * - No dynamic memory allocation
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Gravity/bias estimate
    float gx;
    float gy;
    float gz;

    // Smoothed signal
    float mag_lp;

    // Baseline stats
    float mean;
    float var;

    // Detection state
    uint16_t anomaly_count;
    bool anomaly;

    // Config
    float gravity_alpha;     // e.g. 0.01
    float signal_alpha;      // e.g. 0.2
    float stats_alpha;       // e.g. 0.01
    float z_thresh;          // e.g. 4.0
    float min_sigma;         // e.g. 0.02
    uint16_t sustain_count;  // e.g. 3
} AnomalyDetector;

typedef struct {
    float dynamic_x;
    float dynamic_y;
    float dynamic_z;
    float magnitude;
    float smoothed_magnitude;
    float mean;
    float sigma;
    float score;
    bool anomaly;
} AnomalyResult;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

void anomaly_detector_init(AnomalyDetector *det)
{
    det->gx = 0.0f;
    det->gy = 0.0f;
    det->gz = 0.0f;

    det->mag_lp = 0.0f;
    det->mean = 0.0f;
    det->var = 0.0f;

    det->anomaly_count = 0;
    det->anomaly = false;

    det->gravity_alpha = 0.01f;
    det->signal_alpha = 0.2f;
    det->stats_alpha = 0.01f;
    det->z_thresh = 4.0f;
    det->min_sigma = 0.02f;
    det->sustain_count = 3;
}

/*
 * Process one accelerometer sample.
 *
 * Returns:
 *   AnomalyResult containing intermediate values and final anomaly flag.
 */
AnomalyResult anomaly_detector_process(AnomalyDetector *det, AccelSample s)
{
    AnomalyResult out;

    // 1. Estimate gravity/bias using low-pass filter
    det->gx += det->gravity_alpha * (s.x - det->gx);
    det->gy += det->gravity_alpha * (s.y - det->gy);
    det->gz += det->gravity_alpha * (s.z - det->gz);

    // 2. Remove gravity/bias
    out.dynamic_x = s.x - det->gx;
    out.dynamic_y = s.y - det->gy;
    out.dynamic_z = s.z - det->gz;

    // 3. Compute magnitude of dynamic acceleration
    out.magnitude = fast_sqrtf(
        out.dynamic_x * out.dynamic_x +
        out.dynamic_y * out.dynamic_y +
        out.dynamic_z * out.dynamic_z
    );

    // 4. Smooth magnitude
    det->mag_lp += det->signal_alpha * (out.magnitude - det->mag_lp);
    out.smoothed_magnitude = det->mag_lp;

    // 5. Update running mean
    float prev_mean = det->mean;
    det->mean += det->stats_alpha * (out.smoothed_magnitude - det->mean);

    // 6. Update running variance (EMA of squared residual)
    float residual = out.smoothed_magnitude - prev_mean;
    det->var += det->stats_alpha * ((residual * residual) - det->var);

    if (det->var < 0.0f) {
        det->var = 0.0f;
    }

    out.mean = det->mean;
    out.sigma = fast_sqrtf(det->var);
    if (out.sigma < det->min_sigma) {
        out.sigma = det->min_sigma;
    }

    // 7. Compute anomaly score
    out.score = fabsf(out.smoothed_magnitude - out.mean) / out.sigma;

    // 8. Threshold with sustain logic
    if (out.score > det->z_thresh) {
        if (det->anomaly_count < 0xFFFF) {
            det->anomaly_count++;
        }
    } else {
        det->anomaly_count = 0;
    }

    det->anomaly = (det->anomaly_count >= det->sustain_count);
    out.anomaly = det->anomaly;

    return out;
}
```

