## More Embedded-Friendly Fixed-Point Version

If you want to avoid floating point on MCUs without an FPU, here is a simple fixed-point sketch using Q15/Q16-style integers.

This is less precise but often good enough.

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int32_t gx, gy, gz;
    int32_t mag_lp;
    int32_t mean;
    int32_t var;
    uint16_t anomaly_count;
    bool anomaly;
} AnomalyDetectorFixed;

/*
 * Scale convention:
 * - sensor values scaled by 1000 (e.g. 1g = 1000)
 * - filter alphas represented in Q15
 */
#define Q15_ONE 32768

static int32_t iabs32(int32_t x) {
    return (x < 0) ? -x : x;
}

static int32_t isqrt32(uint32_t x) {
    uint32_t op = x;
    uint32_t res = 0;
    uint32_t one = 1uL << 30;

    while (one > op) one >>= 2;
    while (one != 0) {
        if (op >= res + one) {
            op -= res + one;
            res = res + 2 * one;
        }
        res >>= 1;
        one >>= 2;
    }
    return (int32_t)res;
}

void anomaly_detector_fixed_init(AnomalyDetectorFixed *d)
{
    d->gx = d->gy = d->gz = 0;
    d->mag_lp = 0;
    d->mean = 0;
    d->var = 0;
    d->anomaly_count = 0;
    d->anomaly = false;
}

/*
 * Inputs:
 *   x,y,z in milli-g
 * Config constants:
 *   gravity_alpha_q15 = 328   (~0.01)
 *   signal_alpha_q15  = 6554  (~0.2)
 *   stats_alpha_q15   = 328   (~0.01)
 */
bool anomaly_detector_fixed_process(
    AnomalyDetectorFixed *d,
    int32_t x, int32_t y, int32_t z,
    int32_t gravity_alpha_q15,
    int32_t signal_alpha_q15,
    int32_t stats_alpha_q15,
    int32_t z_thresh_x100,
    int32_t min_sigma,
    uint16_t sustain_count)
{
    d->gx += ((gravity_alpha_q15 * (x - d->gx)) >> 15);
    d->gy += ((gravity_alpha_q15 * (y - d->gy)) >> 15);
    d->gz += ((gravity_alpha_q15 * (z - d->gz)) >> 15);

    int32_t dx = x - d->gx;
    int32_t dy = y - d->gy;
    int32_t dz = z - d->gz;

    uint32_t mag_sq = (uint32_t)(dx * dx + dy * dy + dz * dz);
    int32_t mag = isqrt32(mag_sq);

    d->mag_lp += ((signal_alpha_q15 * (mag - d->mag_lp)) >> 15);

    int32_t prev_mean = d->mean;
    d->mean += ((stats_alpha_q15 * (d->mag_lp - d->mean)) >> 15);

    int32_t residual = d->mag_lp - prev_mean;
    int32_t residual_sq = (residual * residual) / 1000; // crude scaling
    d->var += ((stats_alpha_q15 * (residual_sq - d->var)) >> 15);
    if (d->var < 0) d->var = 0;

    int32_t sigma = isqrt32((uint32_t)(d->var * 1000));
    if (sigma < min_sigma) sigma = min_sigma;

    int32_t score_x100 = (iabs32(d->mag_lp - d->mean) * 100) / sigma;

    if (score_x100 > z_thresh_x100) {
        if (d->anomaly_count < 0xFFFF) d->anomaly_count++;
    } else {
        d->anomaly_count = 0;
    }

    d->anomaly = (d->anomaly_count >= sustain_count);
    return d->anomaly;
}
```

