## Example With Warm-Up and Cooldown

Here is a slightly more production-ready version:

```c
typedef struct {
    float gx, gy, gz;
    float mag_lp;
    float mean, var;

    uint32_t sample_count;
    uint32_t warmup_samples;

    uint16_t anomaly_count;
    uint16_t sustain_count;

    uint32_t cooldown_samples;
    uint32_t cooldown_remaining;

    bool anomaly;

    float gravity_alpha;
    float signal_alpha;
    float stats_alpha;
    float z_thresh_on;
    float z_thresh_off;
    float min_sigma;
} AnomalyDetector2;

void anomaly_detector2_init(AnomalyDetector2 *det)
{
    det->gx = det->gy = det->gz = 0.0f;
    det->mag_lp = 0.0f;
    det->mean = 0.0f;
    det->var = 0.0f;

    det->sample_count = 0;
    det->warmup_samples = 100;

    det->anomaly_count = 0;
    det->sustain_count = 3;

    det->cooldown_samples = 50;
    det->cooldown_remaining = 0;

    det->anomaly = false;

    det->gravity_alpha = 0.01f;
    det->signal_alpha = 0.2f;
    det->stats_alpha = 0.01f;
    det->z_thresh_on = 4.0f;
    det->z_thresh_off = 2.0f;
    det->min_sigma = 0.02f;
}

bool anomaly_detector2_process(AnomalyDetector2 *det, AccelSample s, float *score_out)
{
    det->sample_count++;

    det->gx += det->gravity_alpha * (s.x - det->gx);
    det->gy += det->gravity_alpha * (s.y - det->gy);
    det->gz += det->gravity_alpha * (s.z - det->gz);

    float dx = s.x - det->gx;
    float dy = s.y - det->gy;
    float dz = s.z - det->gz;

    float mag = sqrtf(dx*dx + dy*dy + dz*dz);
    det->mag_lp += det->signal_alpha * (mag - det->mag_lp);

    float prev_mean = det->mean;
    det->mean += det->stats_alpha * (det->mag_lp - det->mean);

    float residual = det->mag_lp - prev_mean;
    det->var += det->stats_alpha * ((residual * residual) - det->var);
    if (det->var < 0.0f) det->var = 0.0f;

    float sigma = sqrtf(det->var);
    if (sigma < det->min_sigma) sigma = det->min_sigma;

    float score = fabsf(det->mag_lp - det->mean) / sigma;
    if (score_out) *score_out = score;

    if (det->sample_count <= det->warmup_samples) {
        det->anomaly = false;
        det->anomaly_count = 0;
        return false;
    }

    if (det->cooldown_remaining > 0) {
        det->cooldown_remaining--;
        det->anomaly = false;
        return false;
    }

    if (!det->anomaly) {
        if (score > det->z_thresh_on) {
            if (det->anomaly_count < 0xFFFF) det->anomaly_count++;
        } else {
            det->anomaly_count = 0;
        }

        if (det->anomaly_count >= det->sustain_count) {
            det->anomaly = true;
            det->cooldown_remaining = det->cooldown_samples;
            det->anomaly_count = 0;
        }
    } else {
        if (score < det->z_thresh_off) {
            det->anomaly = false;
        }
    }

    return det->anomaly;
}
```

