## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Assumptions:
 * - Samples arrive at a fixed rate (e.g. 100 Hz)
 * - Accelerometer values are already converted to g or m/s^2
 * - Floating point is available; if not, this can be converted to fixed-point
 */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

/* Output of the detector */
typedef struct {
    bool anomaly;
    float raw_magnitude;
    float filtered_magnitude;
    float baseline_mean;
    float baseline_stddev;
    float zscore;
} AnomalyResult;

/* Detector state */
typedef struct {
    /* Gravity / bias estimate */
    float grav_x;
    float grav_y;
    float grav_z;

    /* Smoothed activity magnitude */
    float mag_lp;

    /* Rolling baseline stats using exponential moving estimates */
    float mean;
    float var;

    /* Initialization and debounce */
    uint32_t sample_count;
    uint32_t cooldown_counter;
    bool initialized;
} AnomalyDetector;

/* Tunable parameters */
typedef struct {
    /* Gravity tracking factor: smaller = slower gravity update */
    float gravity_alpha;      // e.g. 0.01

    /* Magnitude smoothing factor */
    float mag_alpha;          // e.g. 0.2

    /* Baseline adaptation factor */
    float stats_alpha;        // e.g. 0.01

    /* Z-score threshold for anomaly */
    float z_threshold;        // e.g. 4.0

    /* Minimum stddev floor to avoid divide-by-zero */
    float min_stddev;         // e.g. 0.02

    /* Ignore anomaly decisions until enough samples seen */
    uint32_t warmup_samples;  // e.g. 100

    /* Cooldown after anomaly trigger */
    uint32_t cooldown_samples; // e.g. 20

    /* If true, do not adapt baseline while anomaly is active */
    bool freeze_stats_on_anomaly;
} AnomalyConfig;

/* Initialize detector state */
void anomaly_detector_init(AnomalyDetector *det)
{
    det->grav_x = 0.0f;
    det->grav_y = 0.0f;
    det->grav_z = 0.0f;
    det->mag_lp = 0.0f;
    det->mean = 0.0f;
    det->var = 0.0f;
    det->sample_count = 0;
    det->cooldown_counter = 0;
    det->initialized = false;
}

/* Default config helper */
AnomalyConfig anomaly_default_config(void)
{
    AnomalyConfig cfg;
    cfg.gravity_alpha = 0.01f;
    cfg.mag_alpha = 0.20f;
    cfg.stats_alpha = 0.01f;
    cfg.z_threshold = 4.0f;
    cfg.min_stddev = 0.02f;
    cfg.warmup_samples = 100;
    cfg.cooldown_samples = 20;
    cfg.freeze_stats_on_anomaly = true;
    return cfg;
}

/* Fast helper */
static float clamp_min(float x, float min_val)
{
    return (x < min_val) ? min_val : x;
}

/*
 * Process one accelerometer sample.
 * Returns anomaly decision and intermediate metrics.
 */
AnomalyResult anomaly_detector_process(
    AnomalyDetector *det,
    const AnomalyConfig *cfg,
    AccelSample s)
{
    AnomalyResult out = {0};

    det->sample_count++;

    /* First sample initializes gravity estimate */
    if (!det->initialized) {
        det->grav_x = s.x;
        det->grav_y = s.y;
        det->grav_z = s.z;
        det->initialized = true;
    }

    /* 1) Estimate gravity / bias with low-pass filter */
    det->grav_x += cfg->gravity_alpha * (s.x - det->grav_x);
    det->grav_y += cfg->gravity_alpha * (s.y - det->grav_y);
    det->grav_z += cfg->gravity_alpha * (s.z - det->grav_z);

    /* 2) Remove gravity */
    float dx = s.x - det->grav_x;
    float dy = s.y - det->grav_y;
    float dz = s.z - det->grav_z;

    /* 3) Magnitude of dynamic acceleration */
    float mag = sqrtf(dx * dx + dy * dy + dz * dz);
    out.raw_magnitude = mag;

    /* 4) Smooth magnitude */
    det->mag_lp += cfg->mag_alpha * (mag - det->mag_lp);
    out.filtered_magnitude = det->mag_lp;

    /* Initialize stats from first filtered sample */
    if (det->sample_count == 1) {
        det->mean = det->mag_lp;
        det->var = 0.0f;
    }

    /* Current stddev before update */
    float stddev = sqrtf(clamp_min(det->var, cfg->min_stddev * cfg->min_stddev));
    float z = (det->mag_lp - det->mean) / stddev;

    out.baseline_mean = det->mean;
    out.baseline_stddev = stddev;
    out.zscore = z;

    bool anomaly = false;

    if (det->sample_count > cfg->warmup_samples) {
        if (det->cooldown_counter == 0) {
            if (fabsf(z) >= cfg->z_threshold) {
                anomaly = true;
                det->cooldown_counter = cfg->cooldown_samples;
            }
        } else {
            det->cooldown_counter--;
        }
    }

    /* Update baseline stats unless frozen during anomaly */
    if (!(cfg->freeze_stats_on_anomaly && anomaly)) {
        float err = det->mag_lp - det->mean;
        det->mean += cfg->stats_alpha * err;

        /* Exponential moving variance estimate */
        float err2 = det->mag_lp - det->mean;
        det->var = (1.0f - cfg->stats_alpha) * det->var + cfg->stats_alpha * (err2 * err2);
    }

    out.anomaly = anomaly;
    return out;
}
```

