Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for MCUs.

It includes:
- DC removal / high-pass behavior via running mean
- Magnitude estimation
- Low-pass smoothing
- Rolling baseline and deviation
- Threshold-based anomaly detection with cooldown
- Fixed-size buffers, no dynamic allocation

You can adapt it to raw `x,y,z` accelerometer samples from an ISR or polling loop.

---

## C code

```c
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *  1. Read raw accel x,y,z
 *  2. Remove slow bias using EMA mean
 *  3. Compute motion magnitude
 *  4. Smooth magnitude
 *  5. Track baseline + deviation
 *  6. Trigger anomaly if deviation exceeds threshold
 *
 * Notes:
 *  - Uses integer math where convenient
 *  - No malloc
 *  - Tunable parameters for sampling rate and sensitivity
 */

#define ABS(x) ((x) < 0 ? -(x) : (x))

/* ---------- Configuration ---------- */

typedef struct {
    /* EMA shifts: larger shift => slower adaptation */
    uint8_t mean_shift;        // bias estimator speed, e.g. 6 => 1/64
    uint8_t smooth_shift;      // smoothing speed, e.g. 3 => 1/8
    uint8_t base_shift;        // baseline speed, e.g. 5 => 1/32
    uint8_t dev_shift;         // deviation estimator speed, e.g. 5 => 1/32

    /* Detection tuning */
    uint16_t threshold_mult;   // anomaly if signal > baseline + threshold_mult * deviation
    uint16_t min_threshold;    // minimum absolute threshold
    uint16_t cooldown_samples; // refractory period after detection
} AnomalyConfig;

/* ---------- State ---------- */

typedef struct {
    /* Running mean for x,y,z to remove gravity / DC drift */
    int32_t mean_x;
    int32_t mean_y;
    int32_t mean_z;

    /* Smoothed motion magnitude */
    uint32_t smooth_mag;

    /* Baseline and average absolute deviation */
    uint32_t baseline;
    uint32_t deviation;

    /* Cooldown counter */
    uint16_t cooldown;

    /* Optional stats */
    uint32_t sample_count;
    uint32_t last_score;
    bool initialized;
} AnomalyState;

/* ---------- Output ---------- */

typedef struct {
    bool anomaly;
    uint32_t motion_mag;   // current smoothed motion magnitude
    uint32_t baseline;
    uint32_t deviation;
    uint32_t score;        // amount above threshold, 0 if below
} AnomalyResult;

/* ---------- Utility ---------- */

/* Fast approximate vector magnitude:
 * |x| + |y| + |z|
 * Cheaper than sqrt(x^2+y^2+z^2), often good enough for anomaly detection.
 */
static inline uint32_t approx_magnitude(int32_t x, int32_t y, int32_t z) {
    return (uint32_t)(ABS(x) + ABS(y) + ABS(z));
}

/* Integer EMA update:
 * state += (input - state) / 2^shift
 */
static inline int32_t ema_i32(int32_t state, int32_t input, uint8_t shift) {
    return state + ((input - state) >> shift);
}

static inline uint32_t ema_u32(uint32_t state, uint32_t input, uint8_t shift) {
    return state + ((input - state) >> shift);
}

/* ---------- API ---------- */

void anomaly_init(AnomalyState *st) {
    memset(st, 0, sizeof(*st));
}

AnomalyConfig anomaly_default_config(void) {
    AnomalyConfig cfg;
    cfg.mean_shift = 6;         // slow bias tracking
    cfg.smooth_shift = 3;       // moderate smoothing
    cfg.base_shift = 5;         // baseline adapts slowly
    cfg.dev_shift = 5;          // deviation adapts slowly
    cfg.threshold_mult = 6;     // sensitivity
    cfg.min_threshold = 50;     // raw floor
    cfg.cooldown_samples = 20;  // depends on sample rate
    return cfg;
}

/*
 * Process one accelerometer sample.
 *
 * Inputs:
 *   ax, ay, az: raw accelerometer readings (e.g. mg or ADC counts)
 *
 * Returns:
 *   AnomalyResult with detection state and diagnostics
 */
AnomalyResult anomaly_process_sample(
    AnomalyState *st,
    const AnomalyConfig *cfg,
    int16_t ax,
    int16_t ay,
    int16_t az
) {
    AnomalyResult out = {0};

    st->sample_count++;

    /* Initialize means on first sample to avoid startup spike */
    if (!st->initialized) {
        st->mean_x = ax;
        st->mean_y = ay;
        st->mean_z = az;
        st->smooth_mag = 0;
        st->baseline = 0;
        st->deviation = 0;
        st->cooldown = 0;
        st->initialized = true;
    }

    /* 1) Update running mean (tracks gravity / slow drift) */
    st->mean_x = ema_i32(st->mean_x, ax, cfg->mean_shift);
    st->mean_y = ema_i32(st->mean_y, ay, cfg->mean_shift);
    st->mean_z = ema_i32(st->mean_z, az, cfg->mean_shift);

    /* 2) High-pass effect: subtract mean */
    int32_t hx = (int32_t)ax - st->mean_x;
    int32_t hy = (int32_t)ay - st->mean_y;
    int32_t hz = (int32_t)az - st->mean_z;

    /* 3) Motion magnitude */
    uint32_t mag = approx_magnitude(hx, hy, hz);

    /* 4) Smooth magnitude */
    st->smooth_mag = ema_u32(st->smooth_mag, mag, cfg->smooth_shift);

    /* 5) Update baseline */
    st->baseline = ema_u32(st->baseline, st->smooth_mag, cfg->base_shift);

    /* 6) Update deviation estimate using absolute residual */
    uint32_t resid = (st->smooth_mag > st->baseline)
        ? (st->smooth_mag - st->baseline)
        : (st->baseline - st->smooth_mag);

    st->deviation = ema_u32(st->deviation, resid, cfg->dev_shift);

    /* 7) Compute dynamic threshold */
    uint32_t dyn_threshold = st->baseline + (uint32_t)cfg->threshold_mult * st->deviation;
    if (dyn_threshold < st->baseline + cfg->min_threshold) {
        dyn_threshold = st->baseline + cfg->min_threshold;
    }

    /* 8) Cooldown handling */
    if (st->cooldown > 0) {
        st->cooldown--;
    }

    /* 9) Detect anomaly */
    if (st->smooth_mag > dyn_threshold && st->cooldown == 0) {
        out.anomaly = true;
        out.score = st->smooth_mag - dyn_threshold;
        st->last_score = out.score;
        st->cooldown = cfg->cooldown_samples;
    } else {
        out.anomaly = false;
        out.score = 0;
    }

    out.motion_mag = st->smooth_mag;
    out.baseline = st->baseline;
    out.deviation = st->deviation;

    return out;
}
```

