Below is a compact, embedded-friendly C implementation of an accelerometer anomaly-detection pipeline suitable for MCUs.

It includes:

- 3-axis accelerometer sample input
- DC removal / smoothing via IIR low-pass
- Magnitude calculation
- Rolling mean and variance
- Z-score based anomaly detection
- Optional cooldown to avoid repeated triggers
- No dynamic allocation
- Fixed-size state

---

## Design

Pipeline per sample:

1. Read raw accelerometer `(ax, ay, az)`
2. Low-pass filter each axis
3. Compute magnitude
4. Update rolling statistics on magnitude
5. Compute anomaly score
6. Trigger anomaly if score exceeds threshold

This is simple, efficient, and practical for embedded systems.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - 3-axis low-pass filtering
 * - Magnitude computation
 * - Rolling mean / variance via ring buffer
 * - Z-score anomaly detection
 * - Cooldown to suppress repeated alarms
 *
 * Notes:
 * - Assumes floating point is available. If not, this can be adapted to fixed-point.
 * - Sampling should be uniform.
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define AD_WINDOW_SIZE       64U
#define AD_MIN_STDDEV        0.02f
#define AD_DEFAULT_THRESHOLD 4.0f
#define AD_DEFAULT_ALPHA     0.2f
#define AD_DEFAULT_COOLDOWN  10U

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float buf[AD_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sumsq;
} RollingStats;

typedef struct {
    /* Low-pass filtered axes */
    float fx;
    float fy;
    float fz;

    /* Filter coefficient */
    float alpha;

    /* Rolling stats on magnitude */
    RollingStats stats;

    /* Detection parameters */
    float threshold_z;
    float min_stddev;

    /* Trigger cooldown */
    uint16_t cooldown_samples;
    uint16_t cooldown_counter;

    /* State flags */
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float mean;
    float stddev;
    float zscore;
} AnomalyResult;

/* ---------- Rolling statistics ---------- */

static void rolling_stats_init(RollingStats *rs)
{
    memset(rs, 0, sizeof(*rs));
}

static void rolling_stats_push(RollingStats *rs, float x)
{
    if (rs->count < AD_WINDOW_SIZE) {
        rs->buf[rs->index] = x;
        rs->sum += x;
        rs->sumsq += x * x;
        rs->count++;
        rs->index = (uint16_t)((rs->index + 1U) % AD_WINDOW_SIZE);
    } else {
        float old = rs->buf[rs->index];
        rs->sum -= old;
        rs->sumsq -= old * old;

        rs->buf[rs->index] = x;
        rs->sum += x;
        rs->sumsq += x * x;

        rs->index = (uint16_t)((rs->index + 1U) % AD_WINDOW_SIZE);
    }
}

static float rolling_stats_mean(const RollingStats *rs)
{
    if (rs->count == 0U) {
        return 0.0f;
    }
    return rs->sum / (float)rs->count;
}

static float rolling_stats_variance(const RollingStats *rs)
{
    if (rs->count < 2U) {
        return 0.0f;
    }

    float n = (float)rs->count;
    float mean = rs->sum / n;
    float var = (rs->sumsq / n) - (mean * mean);

    if (var < 0.0f) {
        var = 0.0f;
    }
    return var;
}

static float rolling_stats_stddev(const RollingStats *rs)
{
    return sqrtf(rolling_stats_variance(rs));
}

/* ---------- Detector ---------- */

void anomaly_detector_init(AnomalyDetector *ad,
                           float alpha,
                           float threshold_z,
                           float min_stddev,
                           uint16_t cooldown_samples)
{
    memset(ad, 0, sizeof(*ad));

    ad->alpha = alpha;
    ad->threshold_z = threshold_z;
    ad->min_stddev = min_stddev;
    ad->cooldown_samples = cooldown_samples;
    ad->cooldown_counter = 0U;
    ad->initialized = false;

    rolling_stats_init(&ad->stats);
}

static float lowpass_update(float prev, float input, float alpha)
{
    return prev + alpha * (input - prev);
}

static float accel_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

AnomalyResult anomaly_detector_process(AnomalyDetector *ad, AccelSample s)
{
    AnomalyResult result = {0};

    /* Initialize filter state on first sample */
    if (!ad->initialized) {
        ad->fx = s.x;
        ad->fy = s.y;
        ad->fz = s.z;
        ad->initialized = true;
    } else {
        ad->fx = lowpass_update(ad->fx, s.x, ad->alpha);
        ad->fy = lowpass_update(ad->fy, s.y, ad->alpha);
        ad->fz = lowpass_update(ad->fz, s.z, ad->alpha);
    }

    /* Compute filtered magnitude */
    result.magnitude = accel_magnitude(ad->fx, ad->fy, ad->fz);

    /* Compute stats BEFORE inserting current sample, to compare against history */
    result.mean = rolling_stats_mean(&ad->stats);
    result.stddev = rolling_stats_stddev(&ad->stats);

    if (result.stddev < ad->min_stddev) {
        result.stddev = ad->min_stddev;
    }

    if (ad->stats.count >= 8U) {
        result.zscore = fabsf((result.magnitude - result.mean) / result.stddev);

        if (ad->cooldown_counter > 0U) {
            ad->cooldown_counter--;
        }

        if ((result.zscore >= ad->threshold_z) &&
            (ad->cooldown_counter == 0U)) {
            result.anomaly = true;
            ad->cooldown_counter = ad->cooldown_samples;
        }
    } else {
        result.zscore = 0.0f;
        result.anomaly = false;
    }

    /* Update rolling baseline after scoring */
    rolling_stats_push(&ad->stats, result.magnitude);

    return result;
}
