If you want to suppress gravity and orientation changes, use a high-pass filter:

```c
typedef struct {
    float prev_x, prev_y, prev_z;
    float prev_yx, prev_yy, prev_yz;
    float alpha;
} HighPass3;

static void highpass3_init(HighPass3 *hp, float alpha)
{
    memset(hp, 0, sizeof(*hp));
    hp->alpha = alpha;
}

static void highpass3_update(HighPass3 *hp, float x, float y, float z,
                             float *ox, float *oy, float *oz)
{
    float yx = hp->alpha * (hp->prev_yx + x - hp->prev_x);
    float yy = hp->alpha * (hp->prev_yy + y - hp->prev_y);
    float yz = hp->alpha * (hp->prev_yz + z - hp->prev_z);

    hp->prev_x = x;
    hp->prev_y = y;
    hp->prev_z = z;

    hp->prev_yx = yx;
    hp->prev_yy = yy;
    hp->prev_yz = yz;

    *ox = yx;
    *oy = yy;
    *oz = yz;
}
```

