## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Input:
 *   raw accelerometer samples in g or mg units
 *
 * Pipeline:
 *   1. High-pass filter each axis to remove gravity / DC drift
 *   2. Compute signal magnitude
 *   3. Smooth magnitude with EMA
 *   4. Track baseline mean and variance
 *   5. Detect anomalies using z-score and absolute thresholds
 *
 * Notes:
 *   - Uses only fixed state
 *   - No malloc
 *   - Suitable for periodic sampling
 */

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // High-pass filter state
    float hp_alpha;
    float prev_raw_x;
    float prev_raw_y;
    float prev_raw_z;
    float prev_hp_x;
    float prev_hp_y;
    float prev_hp_z;

    // Smoothed magnitude
    float mag_ema;
    float mag_alpha;

    // Running baseline statistics
    float mean;
    float var;
    float stats_alpha;

    // Detection thresholds
    float z_threshold;
    float abs_threshold;
    uint16_t sustain_count_threshold;

    // Runtime counters
    uint16_t sustain_counter;
    bool initialized;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    bool spike;
    bool sustained;
    float hp_x;
    float hp_y;
    float hp_z;
    float magnitude;
    float smoothed_magnitude;
    float mean;
    float stddev;
    float zscore;
} DetectionResult;

/*
 * Initialize detector
 *
 * sample_rate_hz: sensor sample rate
 * hp_cutoff_hz: high-pass cutoff, e.g. 0.5 to 2.0 Hz
 */
static void anomaly_detector_init(
    AnomalyDetector *det,
    float sample_rate_hz,
    float hp_cutoff_hz,
    float mag_alpha,
    float stats_alpha,
    float z_threshold,
    float abs_threshold,
    uint16_t sustain_count_threshold)
{
    float dt = 1.0f / sample_rate_hz;
    float rc = 1.0f / (2.0f * (float)M_PI * hp_cutoff_hz);
    float hp_alpha = rc / (rc + dt);

    det->hp_alpha = hp_alpha;
    det->prev_raw_x = 0.0f;
    det->prev_raw_y = 0.0f;
    det->prev_raw_z = 0.0f;
    det->prev_hp_x = 0.0f;
    det->prev_hp_y = 0.0f;
    det->prev_hp_z = 0.0f;

    det->mag_ema = 0.0f;
    det->mag_alpha = mag_alpha;

    det->mean = 0.0f;
    det->var = 1e-6f;
    det->stats_alpha = stats_alpha;

    det->z_threshold = z_threshold;
    det->abs_threshold = abs_threshold;
    det->sustain_count_threshold = sustain_count_threshold;

    det->sustain_counter = 0;
    det->initialized = false;
}

/*
 * Fast magnitude approximation if sqrtf is too expensive:
 * Uncomment and use instead of exact sqrtf if needed.
 */
// static float fast_magnitude(float x, float y, float z)
// {
//     x = fabsf(x);
//     y = fabsf(y);
//     z = fabsf(z);
//     float max = x;
//     if (y > max) max = y;
//     if (z > max) max = z;
//     return max + 0.25f * (x + y + z - max);
// }

static DetectionResult anomaly_detector_process(
    AnomalyDetector *det,
    AccelSample raw)
{
    DetectionResult out = {0};

    // 1. High-pass filter per axis:
    // y[n] = alpha * (y[n-1] + x[n] - x[n-1])
    float hp_x = det->hp_alpha * (det->prev_hp_x + raw.x - det->prev_raw_x);
    float hp_y = det->hp_alpha * (det->prev_hp_y + raw.y - det->prev_raw_y);
    float hp_z = det->hp_alpha * (det->prev_hp_z + raw.z - det->prev_raw_z);

    det->prev_raw_x = raw.x;
    det->prev_raw_y = raw.y;
    det->prev_raw_z = raw.z;
    det->prev_hp_x = hp_x;
    det->prev_hp_y = hp_y;
    det->prev_hp_z = hp_z;

    // 2. Magnitude
    float mag = sqrtf(hp_x * hp_x + hp_y * hp_y + hp_z * hp_z);

    // 3. Smooth magnitude
    if (!det->initialized) {
        det->mag_ema = mag;
        det->mean = mag;
        det->var = 1e-6f;
        det->initialized = true;
    } else {
        det->mag_ema = det->mag_alpha * mag + (1.0f - det->mag_alpha) * det->mag_ema;
    }

    // 4. Update running mean and variance using EMA
    float delta = det->mag_ema - det->mean;
    det->mean = det->mean + det->stats_alpha * delta;

    float delta2 = det->mag_ema - det->mean;
    det->var = (1.0f - det->stats_alpha) * det->var + det->stats_alpha * delta * delta2;

    if (det->var < 1e-6f) {
        det->var = 1e-6f;
    }

    float stddev = sqrtf(det->var);
    float zscore = (det->mag_ema - det->mean) / stddev;

    // 5. Detection logic
    bool spike = (zscore > det->z_threshold) || (det->mag_ema > det->abs_threshold);

    if (spike) {
        if (det->sustain_counter < 65535) {
            det->sustain_counter++;
        }
    } else {
        det->sustain_counter = 0;
    }

    bool sustained = (det->sustain_counter >= det->sustain_count_threshold);
    bool anomaly = spike || sustained;

    out.anomaly = anomaly;
    out.spike = spike;
    out.sustained = sustained;
    out.hp_x = hp_x;
    out.hp_y = hp_y;
    out.hp_z = hp_z;
    out.magnitude = mag;
    out.smoothed_magnitude = det->mag_ema;
    out.mean = det->mean;
    out.stddev = stddev;
    out.zscore = zscore;

    return out;
}
