## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Bias/gravity removal via low-pass filter
 * - Magnitude extraction
 * - Exponential smoothing
 * - Rolling mean and variance over fixed window
 * - Anomaly detection using normalized deviation
 *
 * Notes:
 * - Replace sqrtf() if too expensive on your MCU
 * - Can be converted to fixed-point if needed
 */

#ifndef ABS
#define ABS(x) (((x) < 0) ? -(x) : (x))
#endif

#define ANOMALY_WINDOW_SIZE      32
#define MIN_STDDEV               0.01f
#define DEFAULT_Z_THRESHOLD      3.5f
#define DEFAULT_SMOOTH_ALPHA     0.2f
#define DEFAULT_GRAVITY_ALPHA    0.01f
#define SUSTAINED_COUNT_LIMIT    3

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    bool anomaly;
    bool sustained_anomaly;
    float raw_magnitude;
    float filtered_magnitude;
    float mean;
    float stddev;
    float score;
} AnomalyResult;

typedef struct {
    // Gravity / bias estimate
    float gx;
    float gy;
    float gz;

    // Smoothed magnitude
    float smoothed_mag;

    // Rolling stats buffer
    float window[ANOMALY_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    // Running sums for mean/stddev
    float sum;
    float sum_sq;

    // Config
    float gravity_alpha;
    float smooth_alpha;
    float z_threshold;

    // State
    uint16_t sustained_count;
    bool initialized;
} AnomalyDetector;

/* Initialize detector */
void anomaly_detector_init(AnomalyDetector *det)
{
    memset(det, 0, sizeof(*det));
    det->gravity_alpha = DEFAULT_GRAVITY_ALPHA;
    det->smooth_alpha = DEFAULT_SMOOTH_ALPHA;
    det->z_threshold = DEFAULT_Z_THRESHOLD;
}

/* Optional configuration */
void anomaly_detector_configure(AnomalyDetector *det,
                                float gravity_alpha,
                                float smooth_alpha,
                                float z_threshold)
{
    det->gravity_alpha = gravity_alpha;
    det->smooth_alpha = smooth_alpha;
    det->z_threshold = z_threshold;
}

/* Update rolling window statistics */
static void update_rolling_stats(AnomalyDetector *det, float value)
{
    if (det->count < ANOMALY_WINDOW_SIZE) {
        det->window[det->index] = value;
        det->sum += value;
        det->sum_sq += value * value;
        det->count++;
    } else {
        float old = det->window[det->index];
        det->sum -= old;
        det->sum_sq -= old * old;

        det->window[det->index] = value;
        det->sum += value;
        det->sum_sq += value * value;
    }

    det->index = (det->index + 1) % ANOMALY_WINDOW_SIZE;
}

static float compute_mean(const AnomalyDetector *det)
{
    if (det->count == 0) return 0.0f;
    return det->sum / (float)det->count;
}

static float compute_stddev(const AnomalyDetector *det, float mean)
{
    if (det->count < 2) return MIN_STDDEV;

    float variance = (det->sum_sq / (float)det->count) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;

    float stddev = sqrtf(variance);
    if (stddev < MIN_STDDEV) stddev = MIN_STDDEV;
    return stddev;
}

/*
 * Process one accelerometer sample
 *
 * Returns anomaly decision and intermediate metrics.
 */
AnomalyResult anomaly_detector_process(AnomalyDetector *det, AccelSample s)
{
    AnomalyResult result = {0};

    if (!det->initialized) {
        det->gx = s.x;
        det->gy = s.y;
        det->gz = s.z;
        det->smoothed_mag = 0.0f;
        det->initialized = true;
    }

    // 1. Update gravity/bias estimate (low-pass)
    det->gx = (1.0f - det->gravity_alpha) * det->gx + det->gravity_alpha * s.x;
    det->gy = (1.0f - det->gravity_alpha) * det->gy + det->gravity_alpha * s.y;
    det->gz = (1.0f - det->gravity_alpha) * det->gz + det->gravity_alpha * s.z;

    // 2. Remove gravity/bias (high-pass result)
    float dx = s.x - det->gx;
    float dy = s.y - det->gy;
    float dz = s.z - det->gz;

    // 3. Compute magnitude of dynamic acceleration
    float mag = sqrtf(dx * dx + dy * dy + dz * dz);
    result.raw_magnitude = mag;

    // 4. Smooth magnitude
    det->smoothed_mag =
        (1.0f - det->smooth_alpha) * det->smoothed_mag +
        det->smooth_alpha * mag;

    result.filtered_magnitude = det->smoothed_mag;

    // 5. Compute current baseline from previous window
    float mean = compute_mean(det);
    float stddev = compute_stddev(det, mean);

    result.mean = mean;
    result.stddev = stddev;

    // 6. Score deviation
    float score = 0.0f;
    if (det->count >= 8) {
        score = (det->smoothed_mag - mean) / stddev;
    }
    result.score = score;

    // 7. Detect anomaly before inserting current sample into baseline
    bool anomaly = (det->count >= 8) && (score > det->z_threshold);
    result.anomaly = anomaly;

    if (anomaly) {
        if (det->sustained_count < 65535) {
            det->sustained_count++;
        }
    } else {
        det->sustained_count = 0;
    }

    result.sustained_anomaly = (det->sustained_count >= SUSTAINED_COUNT_LIMIT);

    // 8. Update baseline window after decision
    update_rolling_stats(det, det->smoothed_mag);

    return result;
}
