## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Bias removal using exponential moving average
 * - Magnitude extraction
 * - Signal smoothing
 * - Online baseline mean/variance estimation
 * - Threshold-based anomaly detection with debounce
 *
 * Assumptions:
 * - Called at fixed sample rate
 * - Floating point available; can be converted to fixed-point if needed
 */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Bias estimate for each axis
    float mean_x;
    float mean_y;
    float mean_z;

    // Smoothed signal magnitude
    float smooth_mag;

    // Baseline stats for anomaly scoring
    float baseline_mean;
    float baseline_var;

    // Detection state
    uint16_t anomaly_count;
    bool anomaly_active;
} AnomalyDetector;

typedef struct {
    // Bias tracking coefficient (small = slower adaptation)
    float bias_alpha;

    // Magnitude smoothing coefficient
    float smooth_alpha;

    // Baseline stats tracking coefficient
    float stats_alpha;

    // Detection threshold in standard deviations
    float z_threshold;

    // Number of consecutive samples required
    uint16_t persistence;

    // Minimum variance floor to avoid divide-by-zero
    float min_var;
} DetectorConfig;

static void detector_init(AnomalyDetector *det)
{
    det->mean_x = 0.0f;
    det->mean_y = 0.0f;
    det->mean_z = 0.0f;
    det->smooth_mag = 0.0f;
    det->baseline_mean = 0.0f;
    det->baseline_var = 1.0f;
    det->anomaly_count = 0;
    det->anomaly_active = false;
}

static float fast_sqrtf_approx(float x)
{
    // Replace with hardware sqrtf if available
    return sqrtf(x);
}

static bool detector_process(
    AnomalyDetector *det,
    const DetectorConfig *cfg,
    AccelSample s,
    float *out_score,
    float *out_feature)
{
    // 1. Track slow bias / gravity trend
    det->mean_x += cfg->bias_alpha * (s.x - det->mean_x);
    det->mean_y += cfg->bias_alpha * (s.y - det->mean_y);
    det->mean_z += cfg->bias_alpha * (s.z - det->mean_z);

    // 2. High-pass-like residual
    float rx = s.x - det->mean_x;
    float ry = s.y - det->mean_y;
    float rz = s.z - det->mean_z;

    // 3. Magnitude of dynamic acceleration
    float mag = fast_sqrtf_approx(rx * rx + ry * ry + rz * rz);

    // 4. Smooth feature
    det->smooth_mag += cfg->smooth_alpha * (mag - det->smooth_mag);

    float feature = det->smooth_mag;
    if (out_feature) {
        *out_feature = feature;
    }

    // 5. Update baseline statistics
    // EMA mean
    float prev_mean = det->baseline_mean;
    det->baseline_mean += cfg->stats_alpha * (feature - det->baseline_mean);

    // EMA variance estimate
    float diff = feature - prev_mean;
    float diff2 = feature - det->baseline_mean;
    det->baseline_var =
        (1.0f - cfg->stats_alpha) * det->baseline_var +
        cfg->stats_alpha * (diff * diff2);

    if (det->baseline_var < cfg->min_var) {
        det->baseline_var = cfg->min_var;
    }

    // 6. Score
    float stddev = fast_sqrtf_approx(det->baseline_var);
    float score = fabsf(feature - det->baseline_mean) / stddev;

    if (out_score) {
        *out_score = score;
    }

    // 7. Persistence-based anomaly decision
    if (score > cfg->z_threshold) {
        if (det->anomaly_count < 0xFFFF) {
            det->anomaly_count++;
        }
    } else {
        det->anomaly_count = 0;
        det->anomaly_active = false;
    }

    if (det->anomaly_count >= cfg->persistence) {
        det->anomaly_active = true;
    }

    return det->anomaly_active;
}
```

