        .smooth_alpha = 0.2f,
        .stats_alpha = 0.01f,
        .z_threshold = 4.0f,
        .persistence = 3,
        .min_var = 1e-4f
    };

    // Example stream
    AccelSample samples[] = {
        {0.01f, 0.00f, 1.00f},
        {0.02f, 0.01f, 0.99f},
        {0.00f, 0.02f, 1.01f},
        {1.50f, 1.20f, 2.00f}, // anomaly-like spike
        {1.40f, 1.10f, 1.90f},
        {1.60f, 1.30f, 2.10f},
        {0.01f, 0.00f, 1.00f},
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float score, feature;
        bool anomaly = detector_process(&detector, &cfg, samples[i], &score, &feature);

        printf("i=%d feature=%.4f score=%.4f anomaly=%d\n",
               i, feature, score, anomaly ? 1 : 0);
    }

    return 0;
}
