Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:

- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass residual extraction
- Noise-floor estimation
- Adaptive threshold anomaly detection
- Debounce / persistence logic
- Optional fixed-point friendly structure

You can adapt it to raw ADC units, mg, or m/s².

---

## Design

Pipeline per sample:

1. Read `ax, ay, az`
2. Compute signal magnitude
3. Smooth magnitude to estimate normal baseline
4. Compute residual = deviation from baseline
5. Track residual noise level
6. Flag anomaly if residual exceeds adaptive threshold for N samples

This works well for:
- shocks
- impacts
- unusual vibration bursts
- sudden motion changes

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    // Baseline magnitude estimate
    float baseline;

    // Estimated residual noise level
    float noise;

    // Last residual
    float residual;

    // Detection state
    uint16_t consecutive_anomaly_count;
    uint16_t consecutive_normal_count;
    bool anomaly_active;

    // Tunable parameters
    float baseline_alpha;      // low-pass smoothing for baseline
    float noise_alpha;         // smoothing for noise estimate
    float threshold_scale;     // threshold = noise * threshold_scale + threshold_offset
    float threshold_offset;    // minimum threshold floor
    uint16_t trigger_count;    // samples above threshold to trigger
    uint16_t clear_count;      // samples below threshold to clear
} AnomalyDetector;

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

// Lightweight magnitude approximation for embedded use.
// Replaces sqrt(ax^2 + ay^2 + az^2) with a cheaper approximation.
static float approx_magnitude(float x, float y, float z) {
    float ax = fast_absf(x);
    float ay = fast_absf(y);
    float az = fast_absf(z);

    // Sort so ax >= ay >= az
    if (ax < ay) { float t = ax; ax = ay; ay = t; }
    if (ax < az) { float t = ax; ax = az; az = t; }
    if (ay < az) { float t = ay; ay = az; az = t; }

    // Good low-cost approximation
    return ax + 0.5f * ay + 0.25f * az;
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->baseline = 0.0f;
    det->noise = 0.0f;
    det->residual = 0.0f;
    det->consecutive_anomaly_count = 0;
    det->consecutive_normal_count = 0;
    det->anomaly_active = false;

    // Example tuning for 100 Hz sampling
    det->baseline_alpha = 0.01f;    // slow baseline adaptation
    det->noise_alpha = 0.05f;       // moderate noise adaptation
    det->threshold_scale = 4.0f;    // sensitivity
    det->threshold_offset = 0.05f;  // absolute minimum threshold
    det->trigger_count = 3;         // require 3 consecutive anomalous samples
    det->clear_count = 10;          // require 10 consecutive normal samples to clear
}

// Returns true if anomaly state is active after processing this sample.
bool anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    // 1. Compute magnitude
    float mag = approx_magnitude(s.ax, s.ay, s.az);

    // Initialize baseline on first valid sample
    if (det->baseline == 0.0f) {
        det->baseline = mag;
        det->noise = 0.01f;
    }

    // 2. Update baseline (low-pass)
    det->baseline += det->baseline_alpha * (mag - det->baseline);

    // 3. Residual from baseline
    float residual = mag - det->baseline;
    float abs_residual = fast_absf(residual);
    det->residual = residual;

    // 4. Update noise estimate using absolute residual
    det->noise += det->noise_alpha * (abs_residual - det->noise);

    // 5. Adaptive threshold
    float threshold = det->noise * det->threshold_scale + det->threshold_offset;

    // 6. Detection with persistence
    if (abs_residual > threshold) {
        if (det->consecutive_anomaly_count < 65535) {
            det->consecutive_anomaly_count++;
        }
        det->consecutive_normal_count = 0;

        if (!det->anomaly_active &&
            det->consecutive_anomaly_count >= det->trigger_count) {
            det->anomaly_active = true;
        }
    } else {
        det->consecutive_anomaly_count = 0;

        if (det->consecutive_normal_count < 65535) {
            det->consecutive_normal_count++;
        }

        if (det->anomaly_active &&
            det->consecutive_normal_count >= det->clear_count) {
            det->anomaly_active = false;
        }
    }

    return det->anomaly_active;
}
```

