## More Embedded-Friendly Integer Version

If you want to avoid floating point, use fixed-point integers. Example using milli-g units:

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int16_t ax_mg;
    int16_t ay_mg;
    int16_t az_mg;
} AccelSampleMg;

typedef struct {
    int32_t baseline;
    int32_t noise;
    int32_t residual;

    uint16_t consecutive_anomaly_count;
    uint16_t consecutive_normal_count;
    bool anomaly_active;

    // alpha represented as /256
    uint8_t baseline_alpha_q8;
    uint8_t noise_alpha_q8;
    uint8_t threshold_scale;
    int32_t threshold_offset;
    uint16_t trigger_count;
    uint16_t clear_count;
} AnomalyDetectorFixed;

static int32_t iabs32(int32_t x) {
    return (x < 0) ? -x : x;
}

static int32_t approx_magnitude_mg(int16_t x, int16_t y, int16_t z) {
    int32_t ax = iabs32(x);
    int32_t ay = iabs32(y);
    int32_t az = iabs32(z);

    if (ax < ay) { int32_t t = ax; ax = ay; ay = t; }
    if (ax < az) { int32_t t = ax; ax = az; az = t; }
    if (ay < az) { int32_t t = ay; ay = az; az = t; }

    return ax + (ay >> 1) + (az >> 2);
}

void anomaly_detector_fixed_init(AnomalyDetectorFixed *det) {
    det->baseline = 0;
    det->noise = 10;
    det->residual = 0;
    det->consecutive_anomaly_count = 0;
    det->consecutive_normal_count = 0;
    det->anomaly_active = false;

    det->baseline_alpha_q8 = 3;   // ~0.012
    det->noise_alpha_q8 = 13;     // ~0.051
    det->threshold_scale = 4;
    det->threshold_offset = 50;   // 50 mg
    det->trigger_count = 3;
    det->clear_count = 10;
}

bool anomaly_detector_fixed_process(AnomalyDetectorFixed *det, AccelSampleMg s) {
    int32_t mag = approx_magnitude_mg(s.ax_mg, s.ay_mg, s.az_mg);

    if (det->baseline == 0) {
        det->baseline = mag;
    }

    // baseline += alpha * (mag - baseline)
    det->baseline += ((int32_t)det->baseline_alpha_q8 * (mag - det->baseline)) >> 8;

    int32_t residual = mag - det->baseline;
    int32_t abs_residual = iabs32(residual);
    det->residual = residual;

    det->noise += ((int32_t)det->noise_alpha_q8 * (abs_residual - det->noise)) >> 8;

    int32_t threshold = det->noise * det->threshold_scale + det->threshold_offset;

    if (abs_residual > threshold) {
        if (det->consecutive_anomaly_count < 65535) det->consecutive_anomaly_count++;
        det->consecutive_normal_count = 0;

        if (!det->anomaly_active &&
            det->consecutive_anomaly_count >= det->trigger_count) {
            det->anomaly_active = true;
        }
    } else {
        det->consecutive_anomaly_count = 0;

        if (det->consecutive_normal_count < 65535) det->consecutive_normal_count++;

        if (det->anomaly_active &&
            det->consecutive_normal_count >= det->clear_count) {
            det->anomaly_active = false;
        }
    }

    return det->anomaly_active;
}
