## Example Windowed RMS Detector

If your anomalies are burst vibrations rather than single shocks, this alternative may be better:

```c
#define WINDOW_SIZE 32

typedef struct {
    float buf[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;
    float sum;
    float sumsq;
    float baseline_rms;
    bool anomaly;
} WindowRmsDetector;

void window_rms_init(WindowRmsDetector *d) {
    for (int i = 0; i < WINDOW_SIZE; i++) d->buf[i] = 0.0f;
    d->idx = 0;
    d->count = 0;
    d->sum = 0.0f;
    d->sumsq = 0.0f;
    d->baseline_rms = 0.0f;
    d->anomaly = false;
}

static float simple_sqrt(float x) {
    if (x <= 0.0f) return 0.0f;
    float g = x;
    for (int i = 0; i < 6; i++) {
        g = 0.5f * (g + x / g);
    }
    return g;
}

bool window_rms_process(WindowRmsDetector *d, AccelSample s) {
    float mag = approx_magnitude(s.ax, s.ay, s.az);

    float old = d->buf[d->idx];
    d->buf[d->idx] = mag;
    d->idx = (d->idx + 1) % WINDOW_SIZE;

    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    d->sum += mag - old;
    d->sumsq += mag * mag - old * old;

    if (d->count < WINDOW_SIZE) {
        return false;
    }

    float mean = d->sum / WINDOW_SIZE;
    float variance = (d->sumsq / WINDOW_SIZE) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;

    float rms_dev = simple_sqrt(variance);

    if (d->baseline_rms == 0.0f) {
        d->baseline_rms = rms_dev;
    } else {
        d->baseline_rms += 0.01f * (rms_dev - d->baseline_rms);
    }

    d->anomaly = (rms_dev > (3.0f * d->baseline_rms + 0.05f));
    return d->anomaly;
}
```

