Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline suitable for a microcontroller.

It includes:
- 3-axis accelerometer sample input
- Magnitude approximation
- Low-pass baseline tracking
- High-pass “activity” extraction
- Running mean/variance estimation
- Z-score style anomaly detection
- Debounce / persistence logic
- Fixed-point integer math only

You can adapt it for Cortex-M, AVR, ESP32, etc.

---

## Design

Pipeline per sample:

1. Read raw accelerometer `(x, y, z)`
2. Compute approximate magnitude
3. Low-pass filter magnitude to estimate gravity/baseline
4. Subtract baseline to get dynamic motion signal
5. Smooth absolute dynamic motion
6. Track running mean and variance of activity
7. Flag anomaly if activity exceeds adaptive threshold for N samples

This avoids floating point and is efficient for embedded targets.

---

## C Code

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    // Baseline tracking
    int32_t mag_lp;          // low-pass filtered magnitude
    int32_t activity_lp;     // smoothed activity

    // Running statistics
    int32_t mean;
    int32_t var;             // variance estimate

    // Detection state
    uint8_t anomaly_count;
    bool anomaly;

    // Config
    uint8_t lp_shift_mag;        // baseline LPF strength
    uint8_t lp_shift_activity;   // activity smoothing
    uint8_t stat_shift;          // stats adaptation rate
    uint16_t threshold_k;        // threshold multiplier in fixed-point
    uint8_t persist_samples;     // consecutive samples required
    int32_t min_threshold;       // absolute floor threshold
} AnomalyDetector;

static inline int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

/*
 Approximate vector magnitude cheaply:
 max + 1/2 mid + 1/4 min
 Good enough for anomaly detection without sqrt.
*/
static int32_t approx_magnitude(int16_t x, int16_t y, int16_t z) {
    int32_t ax = iabs32(x);
    int32_t ay = iabs32(y);
    int32_t az = iabs32(z);

    int32_t max = ax, mid = ay, min = az;

    if (max < mid) { int32_t t = max; max = mid; mid = t; }
    if (mid < min) { int32_t t = mid; mid = min; min = t; }
    if (max < mid) { int32_t t = max; max = mid; mid = t; }

    return max + (mid >> 1) + (min >> 2);
}

void anomaly_detector_init(AnomalyDetector *d) {
    d->mag_lp = 0;
    d->activity_lp = 0;
    d->mean = 0;
    d->var = 0;
    d->anomaly_count = 0;
    d->anomaly = false;

    // Tunable parameters
    d->lp_shift_mag = 4;         // 1/16 update
    d->lp_shift_activity = 3;    // 1/8 update
    d->stat_shift = 5;           // 1/32 update
    d->threshold_k = 3;          // ~3 sigma-ish
    d->persist_samples = 3;      // require 3 consecutive hits
    d->min_threshold = 200;      // raw-unit floor
}

/*
 Integer square root for variance -> stddev approximation.
 Optional but useful for thresholding.
*/
static uint32_t isqrt32(uint32_t x) {
    uint32_t op = x;
    uint32_t res = 0;
    uint32_t one = 1uL << 30;

    while (one > op) one >>= 2;

    while (one != 0) {
        if (op >= res + one) {
            op -= res + one;
            res += 2 * one;
        }
        res >>= 1;
        one >>= 2;
    }
    return res;
}

/*
 Process one accelerometer sample.
 Returns true when anomaly is currently asserted.
*/
bool anomaly_detector_update(AnomalyDetector *d, AccelSample s) {
    // 1. Magnitude
    int32_t mag = approx_magnitude(s.x, s.y, s.z);

    // Initialize LP on first sample
    if (d->mag_lp == 0) {
        d->mag_lp = mag;
        d->activity_lp = 0;
        d->mean = 0;
        d->var = 0;
        d->anomaly = false;
        d->anomaly_count = 0;
        return false;
    }

    // 2. Low-pass baseline estimate
    d->mag_lp += (mag - d->mag_lp) >> d->lp_shift_mag;

    // 3. High-pass / dynamic component
    int32_t dyn = mag - d->mag_lp;
    int32_t activity = iabs32(dyn);

    // 4. Smooth activity
    d->activity_lp += (activity - d->activity_lp) >> d->lp_shift_activity;
    int32_t feat = d->activity_lp;

    // 5. Running mean
    int32_t delta = feat - d->mean;
    d->mean += delta >> d->stat_shift;

    // 6. Running variance estimate: E[(x-mean)^2]
    int32_t err = feat - d->mean;
    int32_t err2 = (err * err);
    d->var += (err2 - d->var) >> d->stat_shift;

    // 7. Adaptive threshold
    uint32_t stddev = isqrt32((d->var < 0) ? 0 : (uint32_t)d->var);
    int32_t threshold = d->mean + (int32_t)(d->threshold_k * (int32_t)stddev);

    if (threshold < d->min_threshold) {
        threshold = d->min_threshold;
    }

    // 8. Persistence / debounce
    if (feat > threshold) {
        if (d->anomaly_count < 255) {
            d->anomaly_count++;
        }
    } else {
        if (d->anomaly_count > 0) {
            d->anomaly_count--;
        }
    }

    d->anomaly = (d->anomaly_count >= d->persist_samples);
    return d->anomaly;
}
```

