typedef struct {
    int32_t mag_lp;
    int32_t activity_lp;
    int32_t mean;
    int32_t var;
    uint8_t anomaly_count;
    bool anomaly;

    uint8_t lp_shift_mag;
    uint8_t lp_shift_activity;
    uint8_t stat_shift;
    uint16_t threshold_k;
    uint8_t persist_samples;
    int32_t min_threshold;

    uint16_t warmup_samples;
    uint16_t sample_count;
} AnomalyDetector2;

void anomaly_detector2_init(AnomalyDetector2 *d) {
    d->mag_lp = 0;
    d->activity_lp = 0;
    d->mean = 0;
    d->var = 0;
    d->anomaly_count = 0;
    d->anomaly = false;

    d->lp_shift_mag = 4;
    d->lp_shift_activity = 3;
    d->stat_shift = 5;
    d->threshold_k = 3;
    d->persist_samples = 3;
    d->min_threshold = 200;

    d->warmup_samples = 100; // e.g. 1 sec at 100 Hz
    d->sample_count = 0;
}

bool anomaly_detector2_update(AnomalyDetector2 *d, AccelSample s) {
    d->sample_count++;

    int32_t mag = approx_magnitude(s.x, s.y, s.z);

    if (d->mag_lp == 0) {
        d->mag_lp = mag;
        return false;
    }

    d->mag_lp += (mag - d->mag_lp) >> d->lp_shift_mag;
    int32_t dyn = mag - d->mag_lp;
    int32_t activity = iabs32(dyn);

    d->activity_lp += (activity - d->activity_lp) >> d->lp_shift_activity;
    int32_t feat = d->activity_lp;

    int32_t delta = feat - d->mean;
    d->mean += delta >> d->stat_shift;

    int32_t err = feat - d->mean;
    int64_t err64 = (int64_t)err;
    int32_t err2 = (err64 * err64 > INT32_MAX) ? INT32_MAX : (int32_t)(err64 * err64);
    d->var += (err2 - d->var) >> d->stat_shift;

    if (d->sample_count < d->warmup_samples) {
        d->anomaly = false;
        d->anomaly_count = 0;
        return false;
    }

    uint32_t stddev = isqrt32((d->var < 0) ? 0 : (uint32_t)d->var);
    int32_t threshold = d->mean + (int32_t)(d->threshold_k * (int32_t)stddev);
    if (threshold < d->min_threshold) threshold = d->min_threshold;

    if (feat > threshold) {
        if (d->anomaly_count < 255) d->anomaly_count++;
    } else {
        if (d->anomaly_count > 0) d->anomaly_count--;
    }

    d->anomaly = (d->anomaly_count >= d->persist_samples);
    return d->anomaly;
}
