## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <stddef.h>

static float fast_sqrtf_approx(float x)
{
    /* For initial implementation, use sqrtf.
       Can be replaced later with approximation if needed. */
    return sqrtf(x);
}

static float compute_magnitude(accel_sample_t v)
{
    return fast_sqrtf_approx(v.x * v.x + v.y * v.y + v.z * v.z);
}

static accel_sample_t vec_sub(accel_sample_t a, accel_sample_t b)
{
    accel_sample_t r;
    r.x = a.x - b.x;
    r.y = a.y - b.y;
    r.z = a.z - b.z;
    return r;
}

static accel_sample_t vec_lerp(accel_sample_t a, accel_sample_t b, float alpha)
{
    accel_sample_t r;
    r.x = a.x + alpha * (b.x - a.x);
    r.y = a.y + alpha * (b.y - a.y);
    r.z = a.z + alpha * (b.z - a.z);
    return r;
}

void anomaly_detector_init(anomaly_detector_t *det,
                           float baseline_alpha,
                           float stats_alpha,
                           float spike_threshold,
                           float z_threshold,
                           uint16_t sustained_count_thr)
{
    if (det == NULL) {
        return;
    }

    det->baseline_alpha = baseline_alpha;
    det->stats_alpha = stats_alpha;
    det->spike_threshold = spike_threshold;
    det->z_threshold = z_threshold;
    det->sustained_count_thr = sustained_count_thr;
    det->epsilon = 1e-6f;

    det->baseline.x = 0.0f;
    det->baseline.y = 0.0f;
    det->baseline.z = 0.0f;

    det->mean_residual = 0.0f;
    det->var_residual = 0.0f;
    det->sustained_count = 0;
    det->initialized = false;
}

anomaly_result_t anomaly_detector_update(anomaly_detector_t *det,
                                         accel_sample_t sample)
{
    anomaly_result_t result;
    result.type = ANOMALY_NONE;
    result.score = 0.0f;
    result.residual_mag = 0.0f;
    result.detected = false;

    if (det == NULL) {
        return result;
    }

    if (!det->initialized) {
        det->baseline = sample;
        det->mean_residual = 0.0f;
        det->var_residual = 0.0f;
        det->sustained_count = 0;
        det->initialized = true;
        return result;
    }

    /* Update low-pass baseline */
    det->baseline = vec_lerp(det->baseline, sample, det->baseline_alpha);

    /* High-pass residual */
    accel_sample_t residual = vec_sub(sample, det->baseline);

    /* Feature: residual magnitude */
    float residual_mag = compute_magnitude(residual);
    result.residual_mag = residual_mag;

    /* Update EWMA mean */
    float delta = residual_mag - det->mean_residual;
    det->mean_residual += det->stats_alpha * delta;

    /* Update EW variance (simple exponentially weighted form) */
    float diff = residual_mag - det->mean_residual;
    det->var_residual = (1.0f - det->stats_alpha) * det->var_residual
                      + det->stats_alpha * diff * diff;

    float stddev = fast_sqrtf_approx(det->var_residual + det->epsilon);
    float z_score = (residual_mag - det->mean_residual) / stddev;
    result.score = z_score;

    /* Detector 1: spike */
    if (residual_mag >= det->spike_threshold) {
        result.type = ANOMALY_SPIKE;
        result.detected = true;
        det->sustained_count = 0;
        return result;
    }

    /* Detector 2: sustained abnormality */
    if (z_score >= det->z_threshold) {
        if (det->sustained_count < 0xFFFF) {
            det->sustained_count++;
        }
    } else {
        det->sustained_count = 0;
    }

    if (det->sustained_count >= det->sustained_count_thr) {
        result.type = ANOMALY_SUSTAINED;
        result.detected = true;
    }

    return result;
}
```

