Below is a compact initial implementation of an embedded sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple processing pipeline
- Basic filtering
- Magnitude computation
- Rolling baseline statistics
- Z-score-based anomaly detection
- A C implementation suitable as a starting point for embedded use

---

## Design overview

Pipeline:

1. Read raw accelerometer samples `(x, y, z)`
2. Remove some noise with a simple low-pass filter
3. Compute acceleration magnitude
4. Maintain rolling mean and variance of magnitude
5. Flag anomaly when current sample deviates too much from baseline

This is a practical first version because it is:

- Lightweight
- Streaming-friendly
- No dynamic allocation required
- Easy to tune on-device

---

## Assumptions

- Accelerometer samples arrive at a fixed rate
- Raw values are already converted to `g` or consistent units
- We want online detection, one sample at a time
- Small MCU target

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;      // low-pass filter coefficient
    float fx;
    float fy;
    float fz;
    bool initialized;
} LowPassFilter3D;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} RunningStats;

typedef struct {
    LowPassFilter3D lpf;
    RunningStats stats;
    float z_threshold;
    uint32_t warmup_samples;
    float last_magnitude;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float magnitude;
    float mean;
    float stddev;
    float zscore;
} DetectionResult;

/* ---------------- Low-pass filter ---------------- */

static void lpf3d_init(LowPassFilter3D *f, float alpha) {
    f->alpha = alpha;
    f->fx = 0.0f;
    f->fy = 0.0f;
    f->fz = 0.0f;
    f->initialized = false;
}

static AccelSample lpf3d_update(LowPassFilter3D *f, AccelSample in) {
    if (!f->initialized) {
        f->fx = in.x;
        f->fy = in.y;
        f->fz = in.z;
        f->initialized = true;
    } else {
        f->fx = f->alpha * in.x + (1.0f - f->alpha) * f->fx;
        f->fy = f->alpha * in.y + (1.0f - f->alpha) * f->fy;
        f->fz = f->alpha * in.z + (1.0f - f->alpha) * f->fz;
    }

    AccelSample out = { f->fx, f->fy, f->fz };
    return out;
}

/* ---------------- Running statistics ---------------- */
/* Welford's online algorithm */

static void running_stats_init(RunningStats *s) {
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->count = 0;
}

static void running_stats_update(RunningStats *s, float x) {
    s->count++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->count;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float running_stats_variance(const RunningStats *s) {
    if (s->count < 2) {
        return 0.0f;
    }
    return s->m2 / (float)(s->count - 1);
}

static float running_stats_stddev(const RunningStats *s) {
    float var = running_stats_variance(s);
    return (var > 0.0f) ? sqrtf(var) : 0.0f;
}

/* ---------------- Utility ---------------- */

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* ---------------- Detector ---------------- */

static void anomaly_detector_init(
    AnomalyDetector *det,
    float lpf_alpha,
    float z_threshold,
    uint32_t warmup_samples
) {
    lpf3d_init(&det->lpf, lpf_alpha);
    running_stats_init(&det->stats);
    det->z_threshold = z_threshold;
    det->warmup_samples = warmup_samples;
    det->last_magnitude = 0.0f;
}

static DetectionResult anomaly_detector_update(
    AnomalyDetector *det,
    AccelSample raw
) {
    DetectionResult result = {0};

    AccelSample filtered = lpf3d_update(&det->lpf, raw);
    float mag = accel_magnitude(filtered);

    float mean = det->stats.mean;
    float stddev = running_stats_stddev(&det->stats);
    float z = 0.0f;

    if (det->stats.count >= det->warmup_samples && stddev > 1e-6f) {
        z = fabsf((mag - mean) / stddev);
        result.anomaly = (z > det->z_threshold);
    } else {
        result.anomaly = false;
    }

    running_stats_update(&det->stats, mag);

    result.magnitude = mag;
    result.mean = det->stats.mean;
    result.stddev = running_stats_stddev(&det->stats);
    result.zscore = z;

    det->last_magnitude = mag;
    return result;
}
```

