    det->ax_bias = ax_bias;
    det->ay_bias = ay_bias;
    det->az_bias = az_bias;

    det->filt_mag = 0.0f;
    det->mean = 0.0f;
    det->var = 1e-3f;

    det->lpf_alpha = lpf_alpha;
    det->stats_beta = stats_beta;
    det->anomaly_threshold = anomaly_threshold;
    det->consecutive_limit = consecutive_limit;

    det->consecutive_count = 0;
    det->initialized = false;
}

DetectorOutput anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    DetectorOutput out = {0};

    // 1. Bias correction
    float ax = s.ax - det->ax_bias;
    float ay = s.ay - det->ay_bias;
    float az = s.az - det->az_bias;

    // 2. Magnitude
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    // 3. Low-pass filter
    if (!det->initialized) {
        det->filt_mag = mag;
        det->mean = mag;
        det->var = 1e-3f;
        det->initialized = true;
    } else {
        det->filt_mag += det->lpf_alpha * (mag - det->filt_mag);
    }

    float x = det->filt_mag;

    // 4. Compute current score against previous baseline
    float stddev = sqrtf(clamp_min(det->var, 1e-6f));
    float z = fabsf(x - det->mean) / (stddev + 1e-6f);

    bool suspicious = (z > det->anomaly_threshold);

    // 5. Debounce anomaly decision
    if (suspicious) {
        if (det->consecutive_count < 0xFFFF) {
            det->consecutive_count++;
        }
    } else {
        det->consecutive_count = 0;
    }

    bool anomaly = (det->consecutive_count >= det->consecutive_limit);

    // 6. Update baseline only when not anomalous
    // This prevents anomalies from immediately contaminating the baseline.
    if (!anomaly) {
        float delta = x - det->mean;
        det->mean += det->stats_beta * delta;

        float delta2 = x - det->mean;
        det->var = (1.0f - det->stats_beta) * det->var + det->stats_beta * (delta2 * delta2);
        det->var = clamp_min(det->var, 1e-6f);
    }

    out.magnitude = mag;
    out.filtered_magnitude = x;
    out.mean = det->mean;
    out.stddev = sqrtf(det->var);
    out.zscore = z;
    out.anomaly = anomaly;

    return out;
}
```

