## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <string.h>

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

void anomaly_detector_init(AnomalyDetector *detector) {
    memset(detector, 0, sizeof(*detector));

    detector->alpha_baseline = 0.01f;
    detector->alpha_var = 0.01f;
    detector->alpha_score = 0.10f;

    detector->threshold_sigma = 4.0f;
    detector->min_threshold = 0.15f;

    detector->trigger_count = 5;
    detector->clear_count = 10;

    detector->baseline_mag = 1.0f;   // assume ~1g at startup
    detector->baseline_var = 0.01f;
    detector->score_ema = 0.0f;
}

void anomaly_detector_reset(AnomalyDetector *detector) {
    float alpha_baseline = detector->alpha_baseline;
    float alpha_var = detector->alpha_var;
    float alpha_score = detector->alpha_score;
    float threshold_sigma = detector->threshold_sigma;
    float min_threshold = detector->min_threshold;
    uint16_t trigger_count = detector->trigger_count;
    uint16_t clear_count = detector->clear_count;

    anomaly_detector_init(detector);

    detector->alpha_baseline = alpha_baseline;
    detector->alpha_var = alpha_var;
    detector->alpha_score = alpha_score;
    detector->threshold_sigma = threshold_sigma;
    detector->min_threshold = min_threshold;
    detector->trigger_count = trigger_count;
    detector->clear_count = clear_count;
}

AnomalyResult anomaly_detector_process(AnomalyDetector *detector, const AccelSample *sample) {
    AnomalyResult result = {0};

    // 1. Magnitude
    float mag = fast_sqrtf(
        sample->ax * sample->ax +
        sample->ay * sample->ay +
        sample->az * sample->az
    );

    // 2. Baseline estimate
    detector->baseline_mag =
        (1.0f - detector->alpha_baseline) * detector->baseline_mag +
        detector->alpha_baseline * mag;

    // 3. Residual
    float residual = fabsf(mag - detector->baseline_mag);

    // 4. Residual variance estimate
    float residual_sq = residual * residual;
    detector->baseline_var =
        (1.0f - detector->alpha_var) * detector->baseline_var +
        detector->alpha_var * residual_sq;

    float sigma = fast_sqrtf(detector->baseline_var);
    float dynamic_threshold = detector->threshold_sigma * sigma;
    float threshold = (dynamic_threshold > detector->min_threshold)
                        ? dynamic_threshold
                        : detector->min_threshold;

    // 5. Smooth score
    detector->score_ema =
        (1.0f - detector->alpha_score) * detector->score_ema +
        detector->alpha_score * residual;

    float score = detector->score_ema;

    // 6. Trigger logic
    bool above = (score > threshold);

    if (above) {
        detector->consecutive_count++;
        detector->below_count = 0;
    } else {
        detector->below_count++;
        detector->consecutive_count = 0;
    }

    if (!detector->anomaly_active &&
        detector->consecutive_count >= detector->trigger_count) {
        detector->anomaly_active = true;
        result.anomaly_started = true;
    }

    if (detector->anomaly_active &&
        detector->below_count >= detector->clear_count) {
        detector->anomaly_active = false;
        result.anomaly_cleared = true;
    }

    result.anomaly_active = detector->anomaly_active;
    result.magnitude = mag;
    result.residual = residual;
    result.score = score;
    result.threshold = threshold;

    return result;
}
