# Header: `anomaly_pipeline.h`

```c
#ifndef ANOMALY_PIPELINE_H
#define ANOMALY_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // Calibration bias
    float bias_x;
    float bias_y;
    float bias_z;

    // Low-pass filtered axes
    float filt_x;
    float filt_y;
    float filt_z;

    // Rolling baseline for magnitude
    float mean_mag;
    float var_mag;

    // Configuration
    float lpf_alpha;          // 0..1, higher = faster response
    float baseline_alpha;     // 0..1, higher = faster adaptation
    float anomaly_threshold;  // z-score-like threshold
    uint16_t min_consecutive; // debounce anomaly detection

    // Runtime
    uint16_t consecutive_count;
    bool initialized;
} anomaly_pipeline_t;

typedef struct {
    bool anomaly;
    float magnitude;
    float mean_magnitude;
    float std_magnitude;
    float score;
} anomaly_result_t;

/**
 * Initialize pipeline with default parameters.
 */
void anomaly_pipeline_init(anomaly_pipeline_t *p);

/**
 * Set calibration bias values.
 */
void anomaly_pipeline_set_bias(anomaly_pipeline_t *p, float bx, float by, float bz);

/**
 * Process one accelerometer sample.
 */
anomaly_result_t anomaly_pipeline_process(anomaly_pipeline_t *p, accel_sample_t raw);

#ifdef __cplusplus
}
#endif

#endif // ANOMALY_PIPELINE_H
