# Source: `anomaly_pipeline.c`

```c
#include "anomaly_pipeline.h"
#include <math.h>
#include <stddef.h>

#ifndef ANOMALY_EPSILON
#define ANOMALY_EPSILON 1e-6f
#endif

static float fast_sqrtf_safe(float x) {
    if (x <= 0.0f) {
        return 0.0f;
    }
    return sqrtf(x);
}

void anomaly_pipeline_init(anomaly_pipeline_t *p) {
    if (p == NULL) {
        return;
    }

    p->bias_x = 0.0f;
    p->bias_y = 0.0f;
    p->bias_z = 0.0f;

    p->filt_x = 0.0f;
    p->filt_y = 0.0f;
    p->filt_z = 0.0f;

    p->mean_mag = 0.0f;
    p->var_mag = 1.0f;

    p->lpf_alpha = 0.2f;
    p->baseline_alpha = 0.01f;
    p->anomaly_threshold = 3.0f;
    p->min_consecutive = 3;

    p->consecutive_count = 0;
    p->initialized = false;
}

void anomaly_pipeline_set_bias(anomaly_pipeline_t *p, float bx, float by, float bz) {
    if (p == NULL) {
        return;
    }

    p->bias_x = bx;
    p->bias_y = by;
    p->bias_z = bz;
}

anomaly_result_t anomaly_pipeline_process(anomaly_pipeline_t *p, accel_sample_t raw) {
    anomaly_result_t result = {0};

    if (p == NULL) {
        return result;
    }

    // 1. Bias removal
    float x = raw.x - p->bias_x;
    float y = raw.y - p->bias_y;
    float z = raw.z - p->bias_z;

    // 2. Initialize filter on first sample
    if (!p->initialized) {
        p->filt_x = x;
        p->filt_y = y;
        p->filt_z = z;

        float mag0 = fast_sqrtf_safe(x*x + y*y + z*z);
        p->mean_mag = mag0;
        p->var_mag = 1e-3f;
        p->initialized = true;
    } else {
        // 3. Low-pass filter
        p->filt_x += p->lpf_alpha * (x - p->filt_x);
        p->filt_y += p->lpf_alpha * (y - p->filt_y);
        p->filt_z += p->lpf_alpha * (z - p->filt_z);
    }

    // 4. Magnitude
    float mag = fast_sqrtf_safe(
        p->filt_x * p->filt_x +
        p->filt_y * p->filt_y +
        p->filt_z * p->filt_z
    );

    // 5. Compute score against current baseline
    float stddev = fast_sqrtf_safe(p->var_mag + ANOMALY_EPSILON);
    float score = fabsf(mag - p->mean_mag) / stddev;

    // 6. Threshold with debounce
    if (score > p->anomaly_threshold) {
        if (p->consecutive_count < 0xFFFF) {
            p->consecutive_count++;
        }
    } else {
        p->consecutive_count = 0;
    }

    result.anomaly = (p->consecutive_count >= p->min_consecutive);
    result.magnitude = mag;
    result.mean_magnitude = p->mean_mag;
    result.std_magnitude = stddev;
    result.score = score;

    // 7. Update baseline only when not anomalous
    if (!result.anomaly) {
        float a = p->baseline_alpha;
        float delta = mag - p->mean_mag;
        p->mean_mag += a * delta;

        float delta2 = mag - p->mean_mag;
        p->var_mag = (1.0f - a) * p->var_mag + a * delta * delta2;

        if (p->var_mag < ANOMALY_EPSILON) {
            p->var_mag = ANOMALY_EPSILON;
        }
    }

    return result;
}
