    if (idx > 100 && idx < 105) {
        s.x = 2.5f;
        s.y = 1.7f;
        s.z = 0.3f;
    }

    return s;
}

int main(void) {
    anomaly_pipeline_t pipeline;
    anomaly_pipeline_init(&pipeline);

    // Example calibration bias
    anomaly_pipeline_set_bias(&pipeline, 0.0f, 0.0f, 0.0f);

    for (int i = 0; i < 200; i++) {
        accel_sample_t sample = read_accel_sample();
        anomaly_result_t r = anomaly_pipeline_process(&pipeline, sample);

        printf("i=%d mag=%.3f mean=%.3f std=%.3f score=%.3f anomaly=%d\n",
               i,
               r.magnitude,
               r.mean_magnitude,
               r.std_magnitude,
               r.score,
               r.anomaly ? 1 : 0);
    }

    return 0;
}
```

