# 4. Embedded C implementation

## Header: `anomaly_detector.h`

```c
#ifndef ANOMALY_DETECTOR_H
#define ANOMALY_DETECTOR_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

#define AD_WINDOW_SIZE 32

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mean;
    float variance;
    float min;
    float max;
    float peak_to_peak;
    float latest;
} ad_features_t;

typedef struct {
    // Filter state
    float lp_alpha;
    float lp_value;
    bool lp_initialized;

    // Rolling window
    float window[AD_WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    bool window_full;

    // Thresholds
    float spike_threshold;
    float variance_threshold;
    float p2p_threshold;
    float low_motion_variance_threshold;

    // Debounce / hysteresis
    uint8_t consecutive_anomaly_count;
    uint8_t consecutive_anomaly_required;

    // Last computed features
    ad_features_t features;

    // Output state
    bool anomaly;
    float anomaly_score;
} anomaly_detector_t;

void ad_init(anomaly_detector_t *ad);

bool ad_process_sample(anomaly_detector_t *ad,
                       const accel_sample_t *sample,
                       bool *window_ready);

bool ad_detected(const anomaly_detector_t *ad);
float ad_score(const anomaly_detector_t *ad);
const ad_features_t* ad_get_features(const anomaly_detector_t *ad);

#ifdef __cplusplus
}
#endif

#endif
