## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <stddef.h>

static float compute_magnitude(const accel_sample_t *s) {
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static float low_pass_filter(anomaly_detector_t *ad, float input) {
    if (!ad->lp_initialized) {
        ad->lp_value = input;
        ad->lp_initialized = true;
        return input;
    }

    ad->lp_value = ad->lp_alpha * input + (1.0f - ad->lp_alpha) * ad->lp_value;
    return ad->lp_value;
}

static void update_window(anomaly_detector_t *ad, float value) {
    ad->window[ad->index] = value;
    ad->index = (ad->index + 1) % AD_WINDOW_SIZE;

    if (ad->count < AD_WINDOW_SIZE) {
        ad->count++;
    }

    if (ad->count == AD_WINDOW_SIZE) {
        ad->window_full = true;
    }
}

static void compute_features(anomaly_detector_t *ad) {
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = ad->window[0];
    float max_v = ad->window[0];

    for (uint16_t i = 0; i < ad->count; i++) {
        float v = ad->window[i];
        sum += v;
        sum_sq += v * v;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }

    float mean = sum / (float)ad->count;
    float variance = (sum_sq / (float)ad->count) - (mean * mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }

    ad->features.mean = mean;
    ad->features.variance = variance;
    ad->features.min = min_v;
    ad->features.max = max_v;
    ad->features.peak_to_peak = max_v - min_v;
    ad->features.latest = ad->window[(ad->index + AD_WINDOW_SIZE - 1) % AD_WINDOW_SIZE];
}

static void evaluate_anomaly(anomaly_detector_t *ad) {
    bool spike = fabsf(ad->features.latest - ad->features.mean) > ad->spike_threshold;
    bool high_variance = ad->features.variance > ad->variance_threshold;
    bool high_p2p = ad->features.peak_to_peak > ad->p2p_threshold;
    bool suspicious_low_motion = ad->features.variance < ad->low_motion_variance_threshold;

    bool raw_anomaly = spike || high_variance || high_p2p || suspicious_low_motion;

    // Simple anomaly score
    float score = 0.0f;
    if (ad->spike_threshold > 0.0f) {
        float spike_score = fabsf(ad->features.latest - ad->features.mean) / ad->spike_threshold;
        if (spike_score > score) score = spike_score;
    }
    if (ad->variance_threshold > 0.0f) {
        float var_score = ad->features.variance / ad->variance_threshold;
        if (var_score > score) score = var_score;
    }
    if (ad->p2p_threshold > 0.0f) {
        float p2p_score = ad->features.peak_to_peak / ad->p2p_threshold;
        if (p2p_score > score) score = p2p_score;
    }

    ad->anomaly_score = score;

    if (raw_anomaly) {
        if (ad->consecutive_anomaly_count < 255) {
            ad->consecutive_anomaly_count++;
        }
    } else {
        ad->consecutive_anomaly_count = 0;
    }

    ad->anomaly = (ad->consecutive_anomaly_count >= ad->consecutive_anomaly_required);
}

void ad_init(anomaly_detector_t *ad) {
    if (ad == NULL) return;

    ad->lp_alpha = 0.2f;
    ad->lp_value = 0.0f;
    ad->lp_initialized = false;

    for (uint16_t i = 0; i < AD_WINDOW_SIZE; i++) {
        ad->window[i] = 0.0f;
    }

    ad->index = 0;
    ad->count = 0;
    ad->window_full = false;

    // Example defaults; tune for your sensor/range/application
    ad->spike_threshold = 0.8f;
    ad->variance_threshold = 0.15f;
    ad->p2p_threshold = 1.5f;
    ad->low_motion_variance_threshold = 0.0005f;

    ad->consecutive_anomaly_count = 0;
    ad->consecutive_anomaly_required = 3;

    ad->features.mean = 0.0f;
    ad->features.variance = 0.0f;
    ad->features.min = 0.0f;
    ad->features.max = 0.0f;
    ad->features.peak_to_peak = 0.0f;
    ad->features.latest = 0.0f;

    ad->anomaly = false;
    ad->anomaly_score = 0.0f;
}

bool ad_process_sample(anomaly_detector_t *ad,
                       const accel_sample_t *sample,
                       bool *window_ready) {
    if ((ad == NULL) || (sample == NULL)) {
        if (window_ready) *window_ready = false;
        return false;
    }

    float mag = compute_magnitude(sample);

    // Optional gravity removal could be added here if needed.
    float filtered = low_pass_filter(ad, mag);

    update_window(ad, filtered);

    if (window_ready) {
        *window_ready = ad->window_full;
    }

    if (!ad->window_full) {
        return false;
    }

    compute_features(ad);
    evaluate_anomaly(ad);
    return true;
}

bool ad_detected(const anomaly_detector_t *ad) {
    if (ad == NULL) return false;
    return ad->anomaly;
}

float ad_score(const anomaly_detector_t *ad) {
    if (ad == NULL) return 0.0f;
    return ad->anomaly_score;
}

const ad_features_t* ad_get_features(const anomaly_detector_t *ad) {
    if (ad == NULL) return NULL;
    return &ad->features;
}
```

