Below is a compact initial implementation for an embedded sensor-processing pipeline that ingests accelerometer samples, filters them, extracts a simple feature, and flags anomalies.

I’ll provide:

1. A small C implementation suitable for microcontrollers
2. A simple pipeline design
3. Notes on tuning and integration

---

## 1. Pipeline design

A practical first-pass anomaly detector for accelerometer data:

1. **Read raw accelerometer sample** `(ax, ay, az)`
2. **Compute magnitude**  
   `m = sqrt(ax² + ay² + az²)`  
   or use an approximation if avoiding floating point
3. **Low-pass filter** magnitude to reduce noise
4. **Maintain rolling statistics** over a window:
   - mean
   - variance
5. **Compute anomaly score**:
   - z-score-like metric: `abs(x - mean) / stddev`
6. **Trigger anomaly** if:
   - score exceeds threshold
   - optionally for N consecutive samples

This is simple, explainable, and lightweight.

---

## 2. C implementation

### `sensor_pipeline.h`

```c
#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float alpha;              // Low-pass filter coefficient [0..1]
    float threshold_z;        // Z-score threshold
    uint16_t window_size;     // Rolling stats window size
    uint16_t consecutive_limit;
} PipelineConfig;

typedef struct {
    PipelineConfig cfg;

    // Filter state
    float filtered_mag;
    bool filter_initialized;

    // Ring buffer for rolling stats
    float *window;
    uint16_t index;
    uint16_t count;

    // Running sums for mean/stddev
    float sum;
    float sum_sq;

    // Anomaly persistence
    uint16_t consecutive_anomalies;
} SensorPipeline;

typedef struct {
    float raw_magnitude;
    float filtered_magnitude;
    float mean;
    float stddev;
    float z_score;
    bool anomaly;
} PipelineOutput;

bool sensor_pipeline_init(SensorPipeline *p, float *window_buffer, PipelineConfig cfg);
void sensor_pipeline_reset(SensorPipeline *p);
bool sensor_pipeline_process(SensorPipeline *p, const AccelSample *sample, PipelineOutput *out);

#ifdef __cplusplus
}
#endif

#endif
```

---

### `sensor_pipeline.c`

```c
#include "sensor_pipeline.h"
#include <math.h>
#include <stddef.h>

static float compute_magnitude(const AccelSample *s) {
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

static float low_pass_filter(float prev, float input, float alpha) {
    // y[n] = alpha*x[n] + (1-alpha)*y[n-1]
    return (alpha * input) + ((1.0f - alpha) * prev);
}

bool sensor_pipeline_init(SensorPipeline *p, float *window_buffer, PipelineConfig cfg) {
    if (p == NULL || window_buffer == NULL || cfg.window_size == 0) {
        return false;
    }

    if (cfg.alpha < 0.0f || cfg.alpha > 1.0f) {
        return false;
    }

    p->cfg = cfg;
    p->window = window_buffer;
    sensor_pipeline_reset(p);
    return true;
}

void sensor_pipeline_reset(SensorPipeline *p) {
    if (p == NULL) {
        return;
    }

    p->filtered_mag = 0.0f;
    p->filter_initialized = false;

    p->index = 0;
    p->count = 0;
    p->sum = 0.0f;
    p->sum_sq = 0.0f;
    p->consecutive_anomalies = 0;

    if (p->window != NULL) {
        for (uint16_t i = 0; i < p->cfg.window_size; i++) {
            p->window[i] = 0.0f;
        }
    }
}

bool sensor_pipeline_process(SensorPipeline *p, const AccelSample *sample, PipelineOutput *out) {
    if (p == NULL || sample == NULL || out == NULL) {
        return false;
    }

    float mag = compute_magnitude(sample);

    if (!p->filter_initialized) {
        p->filtered_mag = mag;
        p->filter_initialized = true;
    } else {
        p->filtered_mag = low_pass_filter(p->filtered_mag, mag, p->cfg.alpha);
    }

    float x = p->filtered_mag;

    // Remove oldest sample if buffer full
    if (p->count == p->cfg.window_size) {
        float old = p->window[p->index];
        p->sum -= old;
        p->sum_sq -= old * old;
    } else {
        p->count++;
    }

    // Add new sample
    p->window[p->index] = x;
    p->sum += x;
    p->sum_sq += x * x;

    p->index = (uint16_t)((p->index + 1) % p->cfg.window_size);

    float mean = p->sum / (float)p->count;
    float variance = (p->sum_sq / (float)p->count) - (mean * mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }

    float stddev = sqrtf(variance);

    float z = 0.0f;
    bool anomaly = false;

    // Avoid unstable detection with too little history
    if (p->count >= 5 && stddev > 1e-6f) {
        z = fabsf(x - mean) / stddev;
        if (z > p->cfg.threshold_z) {
            p->consecutive_anomalies++;
        } else {
            p->consecutive_anomalies = 0;
        }

        if (p->consecutive_anomalies >= p->cfg.consecutive_limit) {
            anomaly = true;
        }
    } else {
        p->consecutive_anomalies = 0;
    }

    out->raw_magnitude = mag;
    out->filtered_magnitude = x;
    out->mean = mean;
    out->stddev = stddev;
    out->z_score = z;
    out->anomaly = anomaly;

    return true;
}
```

