- uses fixed-point arithmetic
- includes jerk-based anomaly detection
- is structured for ISR + main-loop embedded integration

Below is an initial embedded-friendly implementation of a sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple pipeline structure
- Accelerometer preprocessing
- Magnitude calculation
- Moving statistics
- A basic anomaly detector using z-score-like thresholding
- C code suitable as a starting point for microcontrollers

---

## Design goals

This initial version is:

- lightweight
- deterministic
- no dynamic allocation
- easy to port to embedded C
- easy to extend later with filtering, calibration, or ML inference

Pipeline:

1. Read raw accelerometer sample `(x, y, z)`
2. Remove static bias / gravity estimate with a low-pass baseline
3. Compute motion magnitude
4. Smooth with moving average
5. Track running variance
6. Flag anomaly if deviation exceeds threshold for enough samples

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef ABS
#define ABS(x) ((x) < 0 ? -(x) : (x))
#endif

#define ACC_WINDOW_SIZE         16
#define ANOMALY_CONFIRM_COUNT   3

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float baseline_x;
    float baseline_y;
    float baseline_z;

    float mag_window[ACC_WINDOW_SIZE];
    uint8_t window_index;
    uint8_t window_count;

    float mag_sum;
    float mag_sq_sum;

    uint8_t anomaly_count;
    bool anomaly_active;
} SensorPipeline;

typedef struct {
    float dynamic_x;
    float dynamic_y;
    float dynamic_z;
    float magnitude;
    float mean;
    float stddev;
    float score;
    bool anomaly;
} PipelineOutput;

/* Tunable parameters */
typedef struct {
    float baseline_alpha;      // low-pass factor for gravity/bias estimate
    float anomaly_threshold;   // threshold on normalized deviation
    float min_stddev;          // floor to avoid division by zero
} PipelineConfig;

static void pipeline_init(SensorPipeline *p)
{
    p->baseline_x = 0.0f;
    p->baseline_y = 0.0f;
    p->baseline_z = 0.0f;

    for (uint8_t i = 0; i < ACC_WINDOW_SIZE; i++) {
        p->mag_window[i] = 0.0f;
    }

    p->window_index = 0;
    p->window_count = 0;
    p->mag_sum = 0.0f;
    p->mag_sq_sum = 0.0f;
    p->anomaly_count = 0;
    p->anomaly_active = false;
}

static float compute_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void update_baseline(SensorPipeline *p, const AccelSample *in, float alpha)
{
    p->baseline_x = alpha * in->x + (1.0f - alpha) * p->baseline_x;
    p->baseline_y = alpha * in->y + (1.0f - alpha) * p->baseline_y;
    p->baseline_z = alpha * in->z + (1.0f - alpha) * p->baseline_z;
}

static void update_window_stats(SensorPipeline *p, float value)
{
    if (p->window_count < ACC_WINDOW_SIZE) {
        p->mag_window[p->window_index] = value;
        p->mag_sum += value;
        p->mag_sq_sum += value * value;
        p->window_count++;
    } else {
        float old = p->mag_window[p->window_index];
        p->mag_sum -= old;
        p->mag_sq_sum -= old * old;

        p->mag_window[p->window_index] = value;
        p->mag_sum += value;
        p->mag_sq_sum += value * value;
    }

    p->window_index = (p->window_index + 1) % ACC_WINDOW_SIZE;
}

static void compute_stats(const SensorPipeline *p, float *mean, float *stddev, float min_stddev)
{
    if (p->window_count == 0) {
        *mean = 0.0f;
        *stddev = min_stddev;
        return;
    }

    float n = (float)p->window_count;
    *mean = p->mag_sum / n;

    float variance = (p->mag_sq_sum / n) - (*mean * *mean);
    if (variance < 0.0f) {
        variance = 0.0f;
    }

    *stddev = sqrtf(variance);
    if (*stddev < min_stddev) {
        *stddev = min_stddev;
    }
}

static bool detect_anomaly(SensorPipeline *p, float value, float mean, float stddev, float threshold, float *score)
{
    *score = ABS(value - mean) / stddev;

    if (*score > threshold) {
        if (p->anomaly_count < 255) {
            p->anomaly_count++;
        }
    } else {
        p->anomaly_count = 0;
        p->anomaly_active = false;
    }

    if (p->anomaly_count >= ANOMALY_CONFIRM_COUNT) {
        p->anomaly_active = true;
    }

    return p->anomaly_active;
}

static void pipeline_process(
    SensorPipeline *p,
    const PipelineConfig *cfg,
    const AccelSample *in,
    PipelineOutput *out)
{
    update_baseline(p, in, cfg->baseline_alpha);

    out->dynamic_x = in->x - p->baseline_x;
    out->dynamic_y = in->y - p->baseline_y;
    out->dynamic_z = in->z - p->baseline_z;

    out->magnitude = compute_magnitude(out->dynamic_x, out->dynamic_y, out->dynamic_z);

    update_window_stats(p, out->magnitude);
    compute_stats(p, &out->mean, &out->stddev, cfg->min_stddev);

    out->anomaly = detect_anomaly(
        p,
        out->magnitude,
        out->mean,
        out->stddev,
        cfg->anomaly_threshold,
        &out->score
    );
}
```

