## Source: `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>
#include <stddef.h>

#define EPSILON 1e-6f

static float low_pass(float prev, float input, float alpha)
{
    return prev + alpha * (input - prev);
}

void anomaly_detector_init(anomaly_detector_t *det,
                           float alpha_lp,
                           float alpha_stats,
                           float z_threshold,
                           uint16_t persist_count)
{
    if (det == NULL) {
        return;
    }

    det->fax = 0.0f;
    det->fay = 0.0f;
    det->faz = 0.0f;

    det->mean = 0.0f;
    det->var = 1.0f;

    det->alpha_lp = alpha_lp;
    det->alpha_stats = alpha_stats;
    det->z_threshold = z_threshold;
    det->persist_count = persist_count;
    det->anomaly_streak = 0;

    det->initialized = false;
    det->anomaly = false;
}

bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              float *out_score,
                              float *out_magnitude)
{
    if (det == NULL || sample == NULL) {
        return false;
    }

    // Initialize filter state with first sample
    if (!det->initialized) {
        det->fax = sample->ax;
        det->fay = sample->ay;
        det->faz = sample->az;

        float mag0 = sqrtf(det->fax * det->fax +
                           det->fay * det->fay +
                           det->faz * det->faz);

        det->mean = mag0;
        det->var = 1.0f;
        det->initialized = true;

        if (out_score) {
            *out_score = 0.0f;
        }
        if (out_magnitude) {
            *out_magnitude = mag0;
        }

        det->anomaly = false;
        return false;
    }

    // 1. Low-pass filter
    det->fax = low_pass(det->fax, sample->ax, det->alpha_lp);
    det->fay = low_pass(det->fay, sample->ay, det->alpha_lp);
    det->faz = low_pass(det->faz, sample->az, det->alpha_lp);

    // 2. Magnitude
    float mag = sqrtf(det->fax * det->fax +
                      det->fay * det->fay +
                      det->faz * det->faz);

    // 3. Compute deviation against current baseline
    float diff = mag - det->mean;
    float stddev = sqrtf(det->var + EPSILON);
    float score = diff / stddev;
    if (score < 0.0f) {
        score = -score;
    }

    // 4. Update anomaly streak
    if (score > det->z_threshold) {
        if (det->anomaly_streak < 0xFFFF) {
            det->anomaly_streak++;
        }
    } else {
        det->anomaly_streak = 0;
    }

    det->anomaly = (det->anomaly_streak >= det->persist_count);

    // 5. Update baseline after scoring
    // EWMA mean and variance update
    float alpha = det->alpha_stats;
    float new_mean = det->mean + alpha * (mag - det->mean);
    float delta2 = mag - new_mean;
    float new_var = (1.0f - alpha) * det->var + alpha * diff * delta2;

    if (new_var < EPSILON) {
        new_var = EPSILON;
    }

    det->mean = new_mean;
    det->var = new_var;

    if (out_score) {
        *out_score = score;
    }
    if (out_magnitude) {
        *out_magnitude = mag;
    }

    return det->anomaly;
}
```

