## 3. Source file

```c
#include "sensor_pipeline.h"
#include <math.h>

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

void sensor_pipeline_init(
    SensorPipeline *p,
    float lpf_alpha,
    float baseline_alpha,
    float dev_alpha,
    float anomaly_threshold)
{
    if (!p) return;

    p->fx = 0.0f;
    p->fy = 0.0f;
    p->fz = 0.0f;

    p->mean = 0.0f;
    p->dev = 0.0f;

    p->lpf_alpha = lpf_alpha;
    p->baseline_alpha = baseline_alpha;
    p->dev_alpha = dev_alpha;
    p->anomaly_threshold = anomaly_threshold;

    p->initialized = false;
}

AnomalyResult sensor_pipeline_process(
    SensorPipeline *p,
    const AccelSample *sample)
{
    AnomalyResult result = {0};

    if (!p || !sample) {
        return result;
    }

    if (!p->initialized) {
        p->fx = sample->x;
        p->fy = sample->y;
        p->fz = sample->z;

        float mag0 = sqrtf(sample->x * sample->x +
                           sample->y * sample->y +
                           sample->z * sample->z);

        p->mean = mag0;
        p->dev = 0.01f; /* avoid divide-by-zero */
        p->initialized = true;

        result.anomaly = false;
        result.score = 0.0f;
        result.magnitude = mag0;
        result.baseline_mean = p->mean;
        result.baseline_dev = p->dev;
        return result;
    }

    /* 1. Low-pass filter */
    p->fx += p->lpf_alpha * (sample->x - p->fx);
    p->fy += p->lpf_alpha * (sample->y - p->fy);
    p->fz += p->lpf_alpha * (sample->z - p->fz);

    /* 2. Magnitude feature */
    float mag = sqrtf(p->fx * p->fx +
                      p->fy * p->fy +
                      p->fz * p->fz);

    /* 3. Deviation from baseline mean */
    float err = mag - p->mean;
    float abs_err = fast_absf(err);

    /* 4. Update rolling deviation estimate */
    p->dev += p->dev_alpha * (abs_err - p->dev);

    /* 5. Compute anomaly score */
    float denom = (p->dev < 0.001f) ? 0.001f : p->dev;
    float score = abs_err / denom;

    /* 6. Detect anomaly */
    bool anomaly = (score > p->anomaly_threshold);

    /* 7. Update baseline mean
       Optional strategy: update slower during anomaly */
    float mean_alpha = anomaly ? (p->baseline_alpha * 0.1f) : p->baseline_alpha;
    p->mean += mean_alpha * (mag - p->mean);

    result.anomaly = anomaly;
    result.score = score;
    result.magnitude = mag;
    result.baseline_mean = p->mean;
    result.baseline_dev = p->dev;

    return result;
}
```

