        {2.50f, 1.80f, 0.20f, 40}, /* anomaly */
        {0.01f, 0.02f, 1.00f, 50},
    };

    int n = sizeof(samples) / sizeof(samples[0]);
    for (int i = 0; i < n; i++) {
        AnomalyResult r = sensor_pipeline_process(&pipeline, &samples[i]);
        printf("t=%lu mag=%.3f score=%.3f anomaly=%d\n",
               (unsigned long)samples[i].timestamp_ms,
               r.magnitude,
               r.score,
               r.anomaly ? 1 : 0);
    }

    return 0;
}
```

