### Updated source

```c
#include "sensor_pipeline.h"
#include <math.h>

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

void sensor_pipeline_init(
    SensorPipeline *p,
    float lpf_alpha,
    float baseline_alpha,
    float dev_alpha,
    float anomaly_threshold,
    uint16_t warmup_samples,
    uint8_t trigger_count_required,
    uint16_t cooldown_samples)
{
    if (!p) return;

    p->fx = p->fy = p->fz = 0.0f;
    p->mean = 0.0f;
    p->dev = 0.01f;

    p->lpf_alpha = lpf_alpha;
    p->baseline_alpha = baseline_alpha;
    p->dev_alpha = dev_alpha;
    p->anomaly_threshold = anomaly_threshold;

    p->warmup_samples = warmup_samples;
    p->sample_count = 0;
    p->trigger_count = 0;
    p->trigger_count_required = trigger_count_required;
    p->cooldown_samples = cooldown_samples;
    p->cooldown_remaining = 0;

    p->initialized = false;
}

AnomalyResult sensor_pipeline_process(
    SensorPipeline *p,
    const AccelSample *sample)
{
    AnomalyResult result = {0};
    if (!p || !sample) return result;

    p->sample_count++;

    if (!p->initialized) {
        p->fx = sample->x;
        p->fy = sample->y;
        p->fz = sample->z;

        float mag0 = sqrtf(sample->x * sample->x +
                           sample->y * sample->y +
                           sample->z * sample->z);

        p->mean = mag0;
        p->dev = 0.01f;
        p->initialized = true;

        result.magnitude = mag0;
        result.baseline_mean = p->mean;
        result.baseline_dev = p->dev;
        return result;
    }

    p->fx += p->lpf_alpha * (sample->x - p->fx);
    p->fy += p->lpf_alpha * (sample->y - p->fy);
    p->fz += p->lpf_alpha * (sample->z - p->fz);

    float mag = sqrtf(p->fx * p->fx + p->fy * p->fy + p->fz * p->fz);

    float err = mag - p->mean;
    float abs_err = fast_absf(err);

    p->dev += p->dev_alpha * (abs_err - p->dev);

    float denom = (p->dev < 0.001f) ? 0.001f : p->dev;
    float score = abs_err / denom;

    bool over = (score > p->anomaly_threshold);

    if (p->sample_count <= p->warmup_samples) {
        over = false;
    }

    if (p->cooldown_remaining > 0) {
        p->cooldown_remaining--;
        over = false;
    }

    if (over) {
        if (p->trigger_count < 255) {
            p->trigger_count++;
        }
    } else {
        p->trigger_count = 0;
    }

    bool anomaly = false;
    if (p->trigger_count >= p->trigger_count_required) {
        anomaly = true;
        p->trigger_count = 0;
        p->cooldown_remaining = p->cooldown_samples;
    }

    float mean_alpha = over ? (p->baseline_alpha * 0.1f) : p->baseline_alpha;
    p->mean += mean_alpha * (mag - p->mean);

    result.anomaly = anomaly;
    result.score = score;
    result.magnitude = mag;
    result.baseline_mean = p->mean;
    result.baseline_dev = p->dev;

    return result;
}
```

