Below is a compact, practical **initial implementation** of an **embedded sensor-processing pipeline** for **accelerometer anomaly detection**.

It includes:

- A simple pipeline architecture
- Preprocessing of 3-axis accelerometer samples
- Feature extraction
- A lightweight anomaly detector
- C code suitable as a starting point for microcontrollers
- Notes for embedded deployment

---

# 1. Design goals

For an embedded first version, we want:

- **Low memory**
- **Deterministic runtime**
- **No dynamic allocation**
- **Simple math**
- **Streaming / real-time operation**

A good initial approach is:

1. Read accelerometer sample `(ax, ay, az)`
2. Remove offset / smooth noise
3. Compute magnitude or other simple features
4. Maintain a sliding window
5. Compare current behavior to expected baseline
6. Raise anomaly flag if score exceeds threshold

---

# 2. Suggested pipeline

## Input
- 3-axis accelerometer samples in `g` or raw ADC units
- Fixed sample rate, e.g. `100 Hz`

## Processing stages

### Stage A: Calibration / normalization
- Apply scale and offset correction if available

### Stage B: Filtering
- Low-pass filter to reduce sensor noise
- Optional high-pass component to remove gravity / drift

### Stage C: Feature extraction
For each sample or window:
- Magnitude: `sqrt(ax² + ay² + az²)` or approximation
- Mean
- Variance
- Peak-to-peak
- Jerk (difference between successive samples)

### Stage D: Anomaly scoring
Initial lightweight choices:
- **Z-score against running baseline**
- **Threshold on variance / jerk / magnitude deviation**
- **EWMA-based residual detector**

### Stage E: Decision logic
- Require anomaly score above threshold for `N` consecutive windows
- Add hysteresis to avoid chatter

---

# 3. Initial algorithm choice

A strong initial embedded baseline is:

## Windowed statistical detector
For each window of `W` samples:

- Compute magnitude `m[i]`
- Compute:
  - mean magnitude
  - variance
  - max absolute jerk
- Compare each feature against a running baseline:
  - `score_mean = |mean - baseline_mean| / baseline_std`
  - `score_var = |var - baseline_var| / baseline_var_std`
  - `score_jerk = |jerk - baseline_jerk| / baseline_jerk_std`
- Combine scores
- Trigger anomaly if combined score exceeds threshold

This is easy to implement and tune.

---

# 4. Example embedded C implementation

This is a **single-file initial implementation**.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE              32
#define CONSECUTIVE_ANOMALIES    3
#define EPSILON                  1e-6f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float max_jerk;
} FeatureVector;

typedef struct {
    float mean;
    float alpha;
    bool initialized;
} LowPassFilter;

typedef struct {
    float baseline_mean;
    float baseline_mean_std;

    float baseline_var;
    float baseline_var_std;

    float baseline_jerk;
    float baseline_jerk_std;

    float adapt_alpha;     // slow adaptation for baseline
    bool initialized;
} BaselineModel;

typedef struct {
    AccelSample raw_window[WINDOW_SIZE];
    float mag_window[WINDOW_SIZE];
    uint16_t index;
    bool full;

    LowPassFilter lpf_x;
    LowPassFilter lpf_y;
    LowPassFilter lpf_z;

    float prev_mag;
    bool prev_mag_valid;

    BaselineModel baseline;

    uint8_t anomaly_count;
    bool anomaly_flag;
} SensorPipeline;
```

---

## Utility functions

```c
static float absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static float maxf(float a, float b) {
    return (a > b) ? a : b;
}

static float magnitude3(float x, float y, float z) {
    return sqrtf(x*x + y*y + z*z);
}
```

---

## Low-pass filter

```c
static void lpf_init(LowPassFilter *f, float alpha) {
    f->mean = 0.0f;
    f->alpha = alpha;
    f->initialized = false;
}

static float lpf_apply(LowPassFilter *f, float input) {
    if (!f->initialized) {
        f->mean = input;
        f->initialized = true;
    } else {
        f->mean = f->alpha * input + (1.0f - f->alpha) * f->mean;
    }
    return f->mean;
}
```

---

## Baseline model

This baseline is updated only when the current window is considered normal.

```c
static void baseline_init(BaselineModel *b, float adapt_alpha) {
    memset(b, 0, sizeof(*b));
    b->adapt_alpha = adapt_alpha;
    b->initialized = false;
}

static void baseline_seed(BaselineModel *b, const FeatureVector *fv) {
    b->baseline_mean = fv->mean;
    b->baseline_mean_std = 0.05f;

    b->baseline_var = fv->variance;
    b->baseline_var_std = 0.05f;

    b->baseline_jerk = fv->max_jerk;
    b->baseline_jerk_std = 0.05f;

    b->initialized = true;
}

static void baseline_update_stat(float *mean, float *std, float x, float alpha) {
    float delta = x - *mean;
    *mean += alpha * delta;

    float dev = absf(delta);
    *std += alpha * (dev - *std);

    if (*std < 0.001f) {
        *std = 0.001f;
    }
}

static void baseline_update(BaselineModel *b, const FeatureVector *fv) {
    baseline_update_stat(&b->baseline_mean, &b->baseline_mean_std, fv->mean, b->adapt_alpha);
    baseline_update_stat(&b->baseline_var, &b->baseline_var_std, fv->variance, b->adapt_alpha);
    baseline_update_stat(&b->baseline_jerk, &b->baseline_jerk_std, fv->max_jerk, b->adapt_alpha);
}
```

---

## Feature extraction

```c
static FeatureVector extract_features(const float *mag, uint16_t len) {
    FeatureVector fv = {0};

    float sum = 0.0f;
    for (uint16_t i = 0; i < len; i++) {
        sum += mag[i];
    }
    fv.mean = sum / (float)len;

    float var_sum = 0.0f;
    float max_jerk = 0.0f;
    for (uint16_t i = 0; i < len; i++) {
        float d = mag[i] - fv.mean;
        var_sum += d * d;

        if (i > 0) {
            float jerk = absf(mag[i] - mag[i - 1]);
            max_jerk = maxf(max_jerk, jerk);
        }
    }

    fv.variance = var_sum / (float)len;
    fv.max_jerk = max_jerk;

    return fv;
}
```

---

## Anomaly scoring

```c
static float zscore(float x, float mean, float std) {
    return absf(x - mean) / (std + EPSILON);
}

static float compute_anomaly_score(const BaselineModel *b, const FeatureVector *fv) {
    float s_mean = zscore(fv->mean, b->baseline_mean, b->baseline_mean_std);
    float s_var  = zscore(fv->variance, b->baseline_var, b->baseline_var_std);
    float s_jerk = zscore(fv->max_jerk, b->baseline_jerk, b->baseline_jerk_std);

    // Weighted sum; tune weights per application
    return 0.4f * s_mean + 0.3f * s_var + 0.3f * s_jerk;
}
```

---

## Pipeline initialization

```c
void sensor_pipeline_init(SensorPipeline *p) {
    memset(p, 0, sizeof(*p));

    lpf_init(&p->lpf_x, 0.2f);
    lpf_init(&p->lpf_y, 0.2f);
    lpf_init(&p->lpf_z, 0.2f);

    baseline_init(&p->baseline, 0.02f);

    p->index = 0;
    p->full = false;
    p->prev_mag_valid = false;
    p->anomaly_count = 0;
    p->anomaly_flag = false;
}
```

---

## Processing one sample

This function should be called for every accelerometer sample.

```c
typedef struct {
    bool window_ready;
    FeatureVector features;
    float anomaly_score;
    bool anomaly;
} PipelineResult;

PipelineResult sensor_pipeline_process(SensorPipeline *p, AccelSample sample) {
    PipelineResult result;
    memset(&result, 0, sizeof(result));

    // 1. Low-pass filter each axis
    float fx = lpf_apply(&p->lpf_x, sample.x);
    float fy = lpf_apply(&p->lpf_y, sample.y);
    float fz = lpf_apply(&p->lpf_z, sample.z);

    // 2. Compute magnitude
    float mag = magnitude3(fx, fy, fz);

    // 3. Store in window
    p->raw_window[p->index] = sample;
    p->mag_window[p->index] = mag;

    p->index++;
    if (p->index >= WINDOW_SIZE) {
        p->index = 0;
        p->full = true;
    }

    if (!p->full) {
        return result;
    }

    // 4. Extract features from full window
    FeatureVector fv = extract_features(p->mag_window, WINDOW_SIZE);
    result.window_ready = true;
    result.features = fv;

    // 5. Initialize baseline from first full window
    if (!p->baseline.initialized) {
        baseline_seed(&p->baseline, &fv);
        result.anomaly_score = 0.0f;
        result.anomaly = false;
        return result;
    }

    // 6. Compute anomaly score
    float score = compute_anomaly_score(&p->baseline, &fv);
    result.anomaly_score = score;

    // 7. Decision logic
    const float ANOMALY_THRESHOLD = 3.0f;

    bool is_anomaly = (score > ANOMALY_THRESHOLD);

    if (is_anomaly) {
        if (p->anomaly_count < 255) {
            p->anomaly_count++;
        }
    } else {
        p->anomaly_count = 0;
        baseline_update(&p->baseline, &fv);
    }

    p->anomaly_flag = (p->anomaly_count >= CONSECUTIVE_ANOMALIES);
    result.anomaly = p->anomaly_flag;

    return result;
}
```

