Below is a compact initial implementation of an embedded-friendly sensor-processing pipeline for accelerometer anomaly detection.

It includes:

- A simple pipeline architecture
- Basic preprocessing
- Magnitude-based feature extraction
- Rolling statistics
- Threshold-based anomaly detection
- C code suitable as a starting point for MCU firmware

---

## Design overview

Pipeline stages:

1. **Input acquisition**
   - Read raw accelerometer samples: `ax, ay, az`

2. **Preprocessing**
   - Optional offset correction
   - Magnitude approximation or exact magnitude
   - Low-pass baseline estimate
   - High-pass residual extraction

3. **Feature extraction**
   - Absolute residual
   - Short-term moving average energy
   - Peak tracking

4. **Anomaly detection**
   - Adaptive threshold using rolling mean + sensitivity × rolling deviation
   - Debounce / consecutive-hit logic

5. **Output**
   - Boolean anomaly flag
   - Optional score

This is intentionally lightweight for embedded use.

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Configuration
    float alpha_baseline;      // Low-pass coefficient for baseline
    float alpha_dev;           // Low-pass coefficient for deviation estimate
    float alpha_energy;        // Low-pass coefficient for short-term energy
    float sensitivity;         // Threshold multiplier
    uint16_t trigger_count;    // Consecutive detections required
    float min_threshold;       // Floor threshold to avoid over-sensitivity

    // Calibration / offsets
    float offset_x;
    float offset_y;
    float offset_z;

    // State
    float baseline_mag;
    float dev_est;
    float energy_est;
    uint16_t consecutive_hits;
    bool initialized;
} AnomalyDetector;

typedef struct {
    float magnitude;
    float residual;
    float energy;
    float threshold;
    bool anomaly;
} DetectorOutput;

static float absf_approx(float v) {
    return (v < 0.0f) ? -v : v;
}

// Embedded-friendly magnitude approximation.
// Replace with sqrtf(x*x + y*y + z*z) if FPU cost is acceptable.
static float magnitude_approx(float x, float y, float z) {
    float ax = absf_approx(x);
    float ay = absf_approx(y);
    float az = absf_approx(z);

    // Simple approximation: max + 0.5*(mid + min)
    float max = ax;
    float mid = ay;
    float min = az;

    if (max < mid) { float t = max; max = mid; mid = t; }
    if (mid < min) { float t = mid; mid = min; min = t; }
    if (max < mid) { float t = max; max = mid; mid = t; }

    return max + 0.5f * (mid + min);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->alpha_baseline = 0.01f;
    det->alpha_dev = 0.02f;
    det->alpha_energy = 0.05f;
    det->sensitivity = 4.0f;
    det->trigger_count = 3;
    det->min_threshold = 0.05f;

    det->offset_x = 0.0f;
    det->offset_y = 0.0f;
    det->offset_z = 0.0f;

    det->baseline_mag = 0.0f;
    det->dev_est = 0.0f;
    det->energy_est = 0.0f;
    det->consecutive_hits = 0;
    det->initialized = false;
}

void anomaly_detector_set_offsets(AnomalyDetector *det, float ox, float oy, float oz) {
    det->offset_x = ox;
    det->offset_y = oy;
    det->offset_z = oz;
}

DetectorOutput anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    DetectorOutput out = {0};

    // 1. Offset correction
    float x = s.x - det->offset_x;
    float y = s.y - det->offset_y;
    float z = s.z - det->offset_z;

    // 2. Magnitude extraction
    float mag = magnitude_approx(x, y, z);

    // 3. Initialize baseline on first sample
    if (!det->initialized) {
        det->baseline_mag = mag;
        det->dev_est = 0.0f;
        det->energy_est = 0.0f;
        det->initialized = true;
    }

    // 4. Baseline tracking (slow LPF)
    det->baseline_mag += det->alpha_baseline * (mag - det->baseline_mag);

    // 5. Residual / high-pass component
    float residual = mag - det->baseline_mag;
    float abs_residual = absf_approx(residual);

    // 6. Deviation estimate (adaptive noise floor)
    det->dev_est += det->alpha_dev * (abs_residual - det->dev_est);

    // 7. Short-term energy
    det->energy_est += det->alpha_energy * (abs_residual - det->energy_est);

    // 8. Adaptive threshold
    float threshold = det->sensitivity * det->dev_est;
    if (threshold < det->min_threshold) {
        threshold = det->min_threshold;
    }

    // 9. Detection with debounce
    bool hit = (det->energy_est > threshold);

    if (hit) {
        if (det->consecutive_hits < 65535) {
            det->consecutive_hits++;
        }
    } else {
        det->consecutive_hits = 0;
    }

    bool anomaly = (det->consecutive_hits >= det->trigger_count);

    out.magnitude = mag;
    out.residual = residual;
    out.energy = det->energy_est;
    out.threshold = threshold;
    out.anomaly = anomaly;

    return out;
}
```

