# 4. Source file

```c
#include "sensor_pipeline.h"
#include <string.h>
#include <math.h>

static float compute_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static float low_pass_filter(float prev, float input, float alpha)
{
    return alpha * input + (1.0f - alpha) * prev;
}

static void compute_window_stats(const float *buf,
                                 uint16_t count,
                                 float *mean,
                                 float *variance,
                                 float *max_dev)
{
    float sum = 0.0f;
    float var_sum = 0.0f;
    float local_max_dev = 0.0f;

    if (count == 0) {
        *mean = 0.0f;
        *variance = 0.0f;
        *max_dev = 0.0f;
        return;
    }

    for (uint16_t i = 0; i < count; i++) {
        sum += buf[i];
    }

    *mean = sum / (float)count;

    for (uint16_t i = 0; i < count; i++) {
        float d = buf[i] - *mean;
        float ad = fabsf(d);
        var_sum += d * d;
        if (ad > local_max_dev) {
            local_max_dev = ad;
        }
    }

    *variance = var_sum / (float)count;
    *max_dev = local_max_dev;
}

void sensor_pipeline_init(sensor_pipeline_t *sp,
                          const sensor_pipeline_config_t *cfg)
{
    memset(sp, 0, sizeof(*sp));

    sp->bias_x = cfg->bias_x;
    sp->bias_y = cfg->bias_y;
    sp->bias_z = cfg->bias_z;
    sp->alpha = cfg->alpha;
    sp->threshold_score = cfg->threshold_score;
    sp->persistence_count_required = cfg->persistence_count_required;
}

void sensor_pipeline_reset(sensor_pipeline_t *sp)
{
    float bx = sp->bias_x;
    float by = sp->bias_y;
    float bz = sp->bias_z;
    float alpha = sp->alpha;
    float threshold = sp->threshold_score;
    uint8_t persist = sp->persistence_count_required;

    memset(sp, 0, sizeof(*sp));

    sp->bias_x = bx;
    sp->bias_y = by;
    sp->bias_z = bz;
    sp->alpha = alpha;
    sp->threshold_score = threshold;
    sp->persistence_count_required = persist;
}

void sensor_pipeline_process(sensor_pipeline_t *sp,
                             const accel_sample_t *sample)
{
    // 1. Bias correction
    float x = sample->x - sp->bias_x;
    float y = sample->y - sp->bias_y;
    float z = sample->z - sp->bias_z;

    // 2. Magnitude
    float mag = compute_magnitude(x, y, z);

    // 3. Low-pass filter
    if (sp->count == 0) {
        sp->filtered_mag = mag;
    } else {
        sp->filtered_mag = low_pass_filter(sp->filtered_mag, mag, sp->alpha);
    }

    // 4. Insert into circular window
    sp->window[sp->index] = sp->filtered_mag;
    sp->index = (sp->index + 1) % SP_WINDOW_SIZE;
    if (sp->count < SP_WINDOW_SIZE) {
        sp->count++;
    }

    // 5. Compute features
    float mean = 0.0f;
    float variance = 0.0f;
    float max_dev = 0.0f;
    compute_window_stats(sp->window, sp->count, &mean, &variance, &max_dev);

    // 6. Simple anomaly score
    // Weighted combination of variance and peak deviation
    sp->last_score = variance + 0.5f * max_dev;

    // 7. Threshold + persistence
    if (sp->last_score > sp->threshold_score) {
        if (sp->persistence_counter < 255) {
            sp->persistence_counter++;
        }
    } else {
        sp->persistence_counter = 0;
    }

    sp->anomaly = (sp->persistence_counter >= sp->persistence_count_required);
}

float sensor_pipeline_get_score(const sensor_pipeline_t *sp)
{
    return sp->last_score;
}

bool sensor_pipeline_is_anomaly(const sensor_pipeline_t *sp)
{
    return sp->anomaly;
}
