Below is a compact, practical **initial implementation** of an embedded accelerometer anomaly-detection pipeline in **C** suitable for a microcontroller. It includes:

- sample ingestion
- simple preprocessing
- magnitude estimation
- moving baseline/noise tracking
- anomaly scoring
- threshold + cooldown logic

This is intentionally lightweight and easy to extend.

---

## Design

### Input
Assume incoming accelerometer samples:

```c
typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;
```

### Pipeline
1. **Low-pass filter** raw axes to reduce noise.
2. Compute **signal magnitude**.
3. Track a **slow-moving baseline** and **deviation estimate**.
4. Compute an **anomaly score** from deviation vs expected noise.
5. Trigger anomaly if score exceeds threshold for enough samples.

This approach works well as a first pass for:
- shocks
- vibration changes
- sudden movement spikes
- sensor mounting issues

---

## Example Implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef EPSILON
#define EPSILON 1e-6f
#endif

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    // Filtered acceleration
    float fx;
    float fy;
    float fz;

    // Magnitude tracking
    float mag;
    float baseline_mag;     // slow moving average of magnitude
    float noise_est;        // moving estimate of absolute deviation

    // Detection state
    float anomaly_score;
    uint32_t consecutive_hits;
    uint32_t cooldown_until_ms;
    bool anomaly_detected;

    // Config
    float lpf_alpha;            // 0..1, higher = less smoothing
    float baseline_alpha;       // slow baseline adaptation
    float noise_alpha;          // noise adaptation
    float score_threshold;      // anomaly score threshold
    uint32_t min_consecutive;   // require N consecutive hits
    uint32_t cooldown_ms;       // suppress repeated triggers
} anomaly_detector_t;

static void anomaly_detector_init(anomaly_detector_t *det)
{
    det->fx = 0.0f;
    det->fy = 0.0f;
    det->fz = 0.0f;

    det->mag = 0.0f;
    det->baseline_mag = 1.0f;   // assume near 1g initial magnitude if stationary
    det->noise_est = 0.05f;     // small initial noise estimate

    det->anomaly_score = 0.0f;
    det->consecutive_hits = 0;
    det->cooldown_until_ms = 0;
    det->anomaly_detected = false;

    // Conservative defaults
    det->lpf_alpha = 0.2f;
    det->baseline_alpha = 0.01f;
    det->noise_alpha = 0.01f;
    det->score_threshold = 6.0f;
    det->min_consecutive = 3;
    det->cooldown_ms = 1000;
}

static float fast_abs(float x)
{
    return (x < 0.0f) ? -x : x;
}

static float vector_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/**
 * Process one sample.
 * Returns true only on the sample where a new anomaly is triggered.
 */
static bool anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *s)
{
    // Clear one-shot output
    det->anomaly_detected = false;

    // 1. Low-pass filter each axis
    det->fx += det->lpf_alpha * (s->x - det->fx);
    det->fy += det->lpf_alpha * (s->y - det->fy);
    det->fz += det->lpf_alpha * (s->z - det->fz);

    // 2. Magnitude of filtered signal
    det->mag = vector_magnitude(det->fx, det->fy, det->fz);

    // 3. Deviation from baseline
    float residual = det->mag - det->baseline_mag;
    float abs_residual = fast_abs(residual);

    // 4. Update baseline and noise estimate
    // Baseline follows slowly so sudden changes stand out
    det->baseline_mag += det->baseline_alpha * (det->mag - det->baseline_mag);

    // Noise estimate tracks expected absolute deviation
    det->noise_est += det->noise_alpha * (abs_residual - det->noise_est);
    if (det->noise_est < 0.001f) {
        det->noise_est = 0.001f;
    }

    // 5. Compute anomaly score
    det->anomaly_score = abs_residual / (det->noise_est + EPSILON);

    // 6. Thresholding with consecutive hit logic
    bool over_threshold = (det->anomaly_score >= det->score_threshold);

    if (s->timestamp_ms < det->cooldown_until_ms) {
        det->consecutive_hits = 0;
        return false;
    }

    if (over_threshold) {
        det->consecutive_hits++;
    } else {
        det->consecutive_hits = 0;
    }

    if (det->consecutive_hits >= det->min_consecutive) {
        det->anomaly_detected = true;
        det->cooldown_until_ms = s->timestamp_ms + det->cooldown_ms;
        det->consecutive_hits = 0;
        return true;
    }

    return false;
}
```

