Below is a compact initial implementation of an embedded-friendly sensor-processing pipeline for anomaly detection on accelerometer data.

It includes:

- A simple processing pipeline
- Low-pass gravity estimation
- High-pass “dynamic acceleration”
- Magnitude computation
- Sliding-window feature extraction
- Threshold-based anomaly detection
- Plain C implementation suitable as a starting point for MCU firmware

---

## Design overview

Pipeline:

1. Read raw accelerometer sample `(ax, ay, az)`
2. Estimate gravity with a low-pass filter
3. Subtract gravity to get dynamic motion
4. Compute dynamic magnitude
5. Push magnitude into a fixed-size window
6. Compute simple features:
   - mean
   - variance
   - peak
7. Detect anomaly if features exceed thresholds
8. Return anomaly score / flag

This is intentionally simple, deterministic, and inexpensive.

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define WINDOW_SIZE 32

typedef struct {
    float x;
    float y;
    float z;
} Vec3;

typedef struct {
    float mean;
    float variance;
    float peak;
} Features;

typedef struct {
    // Low-pass gravity estimate
    Vec3 gravity;

    // Circular buffer for dynamic magnitude
    float mag_window[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    // Running state
    bool initialized;

    // Tunable parameters
    float gravity_alpha;     // e.g. 0.9 to 0.98
    float mean_threshold;    // anomaly threshold
    float var_threshold;
    float peak_threshold;
} SensorPipeline;

typedef struct {
    bool anomaly;
    float score;
    Features features;
    float dynamic_magnitude;
} PipelineResult;

static float clampf(float x, float lo, float hi) {
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}

static float vec3_magnitude(Vec3 v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
}

static Vec3 vec3_sub(Vec3 a, Vec3 b) {
    Vec3 out = {a.x - b.x, a.y - b.y, a.z - b.z};
    return out;
}

void sensor_pipeline_init(SensorPipeline *p,
                          float gravity_alpha,
                          float mean_threshold,
                          float var_threshold,
                          float peak_threshold) {
    memset(p, 0, sizeof(*p));
    p->gravity_alpha = gravity_alpha;
    p->mean_threshold = mean_threshold;
    p->var_threshold = var_threshold;
    p->peak_threshold = peak_threshold;
}

static Vec3 estimate_gravity(SensorPipeline *p, Vec3 accel) {
    if (!p->initialized) {
        p->gravity = accel;
        p->initialized = true;
        return p->gravity;
    }

    float a = clampf(p->gravity_alpha, 0.0f, 0.9999f);

    p->gravity.x = a * p->gravity.x + (1.0f - a) * accel.x;
    p->gravity.y = a * p->gravity.y + (1.0f - a) * accel.y;
    p->gravity.z = a * p->gravity.z + (1.0f - a) * accel.z;

    return p->gravity;
}

static void push_magnitude(SensorPipeline *p, float mag) {
    p->mag_window[p->index] = mag;
    p->index = (p->index + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) {
        p->count++;
    }
}

static Features compute_features(const SensorPipeline *p) {
    Features f = {0};

    if (p->count == 0) {
        return f;
    }

    float sum = 0.0f;
    float peak = 0.0f;

    for (uint16_t i = 0; i < p->count; i++) {
        float v = p->mag_window[i];
        sum += v;
        if (v > peak) peak = v;
    }

    float mean = sum / (float)p->count;

    float var_sum = 0.0f;
    for (uint16_t i = 0; i < p->count; i++) {
        float d = p->mag_window[i] - mean;
        var_sum += d * d;
    }

    f.mean = mean;
    f.variance = var_sum / (float)p->count;
    f.peak = peak;

    return f;
}

static float compute_anomaly_score(const SensorPipeline *p, Features f) {
    float score = 0.0f;

    if (p->mean_threshold > 0.0f) {
        score += f.mean / p->mean_threshold;
    }
    if (p->var_threshold > 0.0f) {
        score += f.variance / p->var_threshold;
    }
    if (p->peak_threshold > 0.0f) {
        score += f.peak / p->peak_threshold;
    }

    // Average normalized score
    score /= 3.0f;
    return score;
}

PipelineResult sensor_pipeline_process(SensorPipeline *p, float ax, float ay, float az) {
    PipelineResult result;
    memset(&result, 0, sizeof(result));

    Vec3 accel = {ax, ay, az};

    // 1. Estimate gravity
    Vec3 gravity = estimate_gravity(p, accel);

    // 2. Remove gravity to isolate dynamic acceleration
    Vec3 dynamic = vec3_sub(accel, gravity);

    // 3. Compute magnitude
    float dynamic_mag = vec3_magnitude(dynamic);

    // 4. Update window
    push_magnitude(p, dynamic_mag);

    // 5. Compute features
    Features f = compute_features(p);

    // 6. Threshold-based anomaly logic
    bool anomaly = false;
    if (f.mean > p->mean_threshold) anomaly = true;
    if (f.variance > p->var_threshold) anomaly = true;
    if (f.peak > p->peak_threshold) anomaly = true;

    result.anomaly = anomaly;
    result.score = compute_anomaly_score(p, f);
    result.features = f;
    result.dynamic_magnitude = dynamic_mag;

    return result;
}
```

