## Source: `sensor_pipeline.c`

```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float clampf(float v, float lo, float hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

void sensor_pipeline_init(sensor_pipeline_t *ctx,
                          float alpha,
                          float z_threshold,
                          uint32_t min_samples,
                          uint32_t cooldown_samples)
{
    if (!ctx) return;

    memset(ctx, 0, sizeof(*ctx));
    ctx->alpha = clampf(alpha, 0.0f, 1.0f);
    ctx->z_threshold = z_threshold;
    ctx->min_samples = min_samples;
    ctx->cooldown_samples = cooldown_samples;
}

static void lowpass_filter(sensor_pipeline_t *ctx, const accel_sample_t *s,
                           float *fx, float *fy, float *fz)
{
    if (!ctx->filter_initialized) {
        ctx->fx = s->x;
        ctx->fy = s->y;
        ctx->fz = s->z;
        ctx->filter_initialized = true;
    } else {
        ctx->fx = ctx->alpha * s->x + (1.0f - ctx->alpha) * ctx->fx;
        ctx->fy = ctx->alpha * s->y + (1.0f - ctx->alpha) * ctx->fy;
        ctx->fz = ctx->alpha * s->z + (1.0f - ctx->alpha) * ctx->fz;
    }

    *fx = ctx->fx;
    *fy = ctx->fy;
    *fz = ctx->fz;
}

static void update_online_stats(sensor_pipeline_t *ctx, float x)
{
    ctx->count++;
    float delta = x - ctx->mean;
    ctx->mean += delta / (float)ctx->count;
    float delta2 = x - ctx->mean;
    ctx->m2 += delta * delta2;
}

static float compute_stddev(const sensor_pipeline_t *ctx)
{
    if (ctx->count < 2) {
        return 0.0f;
    }
    float variance = ctx->m2 / (float)(ctx->count - 1);
    if (variance < 0.0f) variance = 0.0f;
    return sqrtf(variance);
}

anomaly_result_t sensor_pipeline_process(sensor_pipeline_t *ctx,
                                         const accel_sample_t *sample)
{
    anomaly_result_t result;
    memset(&result, 0, sizeof(result));

    if (!ctx || !sample) {
        return result;
    }

    float fx, fy, fz;
    lowpass_filter(ctx, sample, &fx, &fy, &fz);

    float magnitude = sqrtf(fx * fx + fy * fy + fz * fz);

    // Use current baseline before updating with this sample
    float mean = ctx->mean;
    float stddev = compute_stddev(ctx);

    bool anomaly = false;
    float zscore = 0.0f;

    if (ctx->count >= ctx->min_samples && stddev > 1e-6f) {
        zscore = fabsf((magnitude - mean) / stddev);

        if (ctx->cooldown_remaining > 0) {
            ctx->cooldown_remaining--;
        } else if (zscore > ctx->z_threshold) {
            anomaly = true;
            ctx->cooldown_remaining = ctx->cooldown_samples;
        }
    }

    update_online_stats(ctx, magnitude);

    result.magnitude = magnitude;
    result.filtered_x = fx;
    result.filtered_y = fy;
    result.filtered_z = fz;
    result.mean = mean;
    result.stddev = stddev;
    result.zscore = zscore;
    result.anomaly = anomaly;
    result.timestamp_ms = sample->timestamp_ms;

    return result;
}
