Below is a compact but practical **initial implementation** of an **embedded sensor-processing pipeline** for **accelerometer anomaly detection**.

It includes:

- A simple pipeline architecture
- Simulated accelerometer input
- Filtering
- Feature extraction
- Baseline/adaptive statistics
- Anomaly scoring
- Threshold-based detection
- C-style embedded-friendly implementation notes
- A Python reference implementation for prototyping

---

# 1. Design goals

For an embedded anomaly detector, a good initial version should be:

- **Lightweight**
- **Streaming/incremental**
- **Low memory**
- **Deterministic**
- **Easy to port to C/C++**

We’ll assume a 3-axis accelerometer:

- `ax`, `ay`, `az`
- sampled at a fixed rate, e.g. **100 Hz**

We want to detect events like:

- excessive vibration
- sudden shocks
- sustained unusual motion
- sensor behavior deviating from normal baseline

---

# 2. Pipeline overview

A simple embedded pipeline:

1. **Acquire sample**
2. **Preprocess**
   - remove bias / smooth noise
   - compute acceleration magnitude
3. **Windowing**
   - collect N samples
4. **Extract features**
   - mean magnitude
   - variance / RMS
   - peak
   - jerk estimate
5. **Compute anomaly score**
   - compare features to running baseline
6. **Decision logic**
   - threshold + debounce / persistence
7. **Emit event**

---

# 3. Recommended initial anomaly strategy

For a first implementation, use a **statistical baseline detector**:

- Maintain running mean and variance for each feature
- Convert current feature to a **z-score**
- Combine z-scores into a single anomaly score
- Trigger if score exceeds threshold for `k` consecutive windows

Why this is good initially:

- no training dataset required
- easy to tune
- cheap to compute
- interpretable

---

# 4. Reference Python implementation

This is useful for validation before porting to firmware.

```python
from dataclasses import dataclass
from collections import deque
import math
import random


@dataclass
class AccelSample:
    ax: float
    ay: float
    az: float
    ts: float


class IIRLowPass:
    def __init__(self, alpha: float):
        self.alpha = alpha
        self.y = None

    def update(self, x: float) -> float:
        if self.y is None:
            self.y = x
        else:
            self.y = self.alpha * x + (1.0 - self.alpha) * self.y
        return self.y


class RunningStats:
    """
    Welford running mean/variance.
    Suitable for baseline estimation.
    """
    def __init__(self):
        self.n = 0
        self.mean = 0.0
        self.m2 = 0.0

    def update(self, x: float):
        self.n += 1
        delta = x - self.mean
        self.mean += delta / self.n
        delta2 = x - self.mean
        self.m2 += delta * delta2

    @property
    def variance(self) -> float:
        if self.n < 2:
            return 1e-6
        return self.m2 / (self.n - 1)

    @property
    def std(self) -> float:
        return math.sqrt(max(self.variance, 1e-6))


class FeatureBaseline:
    def __init__(self):
        self.mean_stats = RunningStats()
        self.std_stats = RunningStats()
        self.rms_stats = RunningStats()
        self.peak_stats = RunningStats()
        self.jerk_stats = RunningStats()

    def update(self, features: dict):
        self.mean_stats.update(features["mean"])
        self.std_stats.update(features["std"])
        self.rms_stats.update(features["rms"])
        self.peak_stats.update(features["peak"])
        self.jerk_stats.update(features["jerk"])

    def zscore(self, x: float, stats: RunningStats) -> float:
        return abs(x - stats.mean) / stats.std

    def score(self, features: dict) -> float:
        z_mean = self.zscore(features["mean"], self.mean_stats)
        z_std = self.zscore(features["std"], self.std_stats)
        z_rms = self.zscore(features["rms"], self.rms_stats)
        z_peak = self.zscore(features["peak"], self.peak_stats)
        z_jerk = self.zscore(features["jerk"], self.jerk_stats)

        # Weighted sum; tune weights as needed
        return (
            0.15 * z_mean +
            0.25 * z_std +
            0.20 * z_rms +
            0.25 * z_peak +
            0.15 * z_jerk
        )


class AccelAnomalyDetector:
    def __init__(
        self,
        sample_rate_hz=100,
        window_size=32,
        lp_alpha=0.2,
        anomaly_threshold=4.0,
        persistence_windows=3,
        warmup_windows=20,
    ):
        self.sample_rate_hz = sample_rate_hz
        self.window_size = window_size
        self.mag_filter = IIRLowPass(lp_alpha)
        self.window = deque(maxlen=window_size)
        self.prev_mag = None

        self.baseline = FeatureBaseline()
        self.anomaly_threshold = anomaly_threshold
        self.persistence_windows = persistence_windows
        self.warmup_windows = warmup_windows

        self.window_count = 0
        self.consecutive_anomalies = 0

    def process_sample(self, sample: AccelSample):
        # Magnitude of acceleration vector
        mag = math.sqrt(sample.ax**2 + sample.ay**2 + sample.az**2)

        # Low-pass filter to reduce noise
        mag_f = self.mag_filter.update(mag)

        # Jerk approximation
        if self.prev_mag is None:
            jerk = 0.0
        else:
            jerk = abs(mag_f - self.prev_mag) * self.sample_rate_hz
        self.prev_mag = mag_f

        self.window.append((mag_f, jerk))

        if len(self.window) < self.window_size:
            return None

        features = self.extract_features()

        self.window_count += 1

        if self.window_count <= self.warmup_windows:
            self.baseline.update(features)
            return {
                "status": "warmup",
                "features": features,
                "score": 0.0,
                "anomaly": False,
            }

        score = self.baseline.score(features)
        is_anomaly = score > self.anomaly_threshold

        if is_anomaly:
            self.consecutive_anomalies += 1
        else:
            self.consecutive_anomalies = 0

        event = self.consecutive_anomalies >= self.persistence_windows

        # Update baseline only when not anomalous
        if not is_anomaly:
            self.baseline.update(features)

        return {
            "status": "active",
            "features": features,
            "score": score,
            "anomaly": event,
            "raw_anomaly": is_anomaly,
        }

    def extract_features(self):
        mags = [x[0] for x in self.window]
        jerks = [x[1] for x in self.window]

        n = len(mags)
        mean_val = sum(mags) / n
        var_val = sum((x - mean_val) ** 2 for x in mags) / max(n - 1, 1)
        std_val = math.sqrt(var_val)
        rms_val = math.sqrt(sum(x * x for x in mags) / n)
        peak_val = max(mags)
        jerk_mean = sum(jerks) / n

        return {
            "mean": mean_val,
            "std": std_val,
            "rms": rms_val,
            "peak": peak_val,
            "jerk": jerk_mean,
        }


def simulate_stream():
    """
    Example signal:
    - Mostly stable gravity-dominated readings around 1g
    - Occasional anomaly burst
    """
    detector = AccelAnomalyDetector()

    ts = 0.0
    dt = 1.0 / 100.0

    for i in range(1000):
        # Normal operating data
        ax = 0.02 * random.gauss(0, 1)
        ay = 0.02 * random.gauss(0, 1)
        az = 1.0 + 0.02 * random.gauss(0, 1)

        # Inject anomaly
        if 500 <= i < 540:
            ax += 0.8 * random.gauss(0, 1)
            ay += 0.8 * random.gauss(0, 1)
            az += 0.5 * random.gauss(0, 1)

        sample = AccelSample(ax=ax, ay=ay, az=az, ts=ts)
        result = detector.process_sample(sample)

        if result and result["anomaly"]:
            print(f"Anomaly detected at sample {i}, score={result['score']:.2f}")

        ts += dt


if __name__ == "__main__":
    simulate_stream()
```

