## Source implementation

```c
#include "accel_anomaly.h"
#include <math.h>
#include <string.h>

static void running_stats_update(running_stats_t *s, float x) {
    s->n++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->n;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float running_stats_variance(const running_stats_t *s) {
    if (s->n < 2) return 1e-6f;
    float v = s->m2 / (float)(s->n - 1);
    return (v < 1e-6f) ? 1e-6f : v;
}

static float running_stats_std(const running_stats_t *s) {
    return sqrtf(running_stats_variance(s));
}

static float zscore(float x, const running_stats_t *s) {
    return fabsf(x - s->mean) / running_stats_std(s);
}

static void baseline_update(feature_baseline_t *b, const accel_features_t *f) {
    running_stats_update(&b->mean_stats, f->mean);
    running_stats_update(&b->std_stats, f->std);
    running_stats_update(&b->rms_stats, f->rms);
    running_stats_update(&b->peak_stats, f->peak);
    running_stats_update(&b->jerk_stats, f->jerk);
}

static float baseline_score(const feature_baseline_t *b, const accel_features_t *f) {
    float z_mean = zscore(f->mean, &b->mean_stats);
    float z_std  = zscore(f->std,  &b->std_stats);
    float z_rms  = zscore(f->rms,  &b->rms_stats);
    float z_peak = zscore(f->peak, &b->peak_stats);
    float z_jerk = zscore(f->jerk, &b->jerk_stats);

    return 0.15f * z_mean +
           0.25f * z_std +
           0.20f * z_rms +
           0.25f * z_peak +
           0.15f * z_jerk;
}

static float lowpass_update(accel_detector_t *det, float x) {
    if (!det->lp_initialized) {
        det->lp_state = x;
        det->lp_initialized = true;
    } else {
        det->lp_state = det->lp_alpha * x + (1.0f - det->lp_alpha) * det->lp_state;
    }
    return det->lp_state;
}

static void extract_features(const accel_detector_t *det, accel_features_t *f) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    float peak = det->mags[0];
    float jerk_sum = 0.0f;

    for (uint16_t i = 0; i < det->count; i++) {
        float m = det->mags[i];
        float j = det->jerks[i];
        sum += m;
        sumsq += m * m;
        if (m > peak) peak = m;
        jerk_sum += j;
    }

    float mean = sum / (float)det->count;

    float var = 0.0f;
    for (uint16_t i = 0; i < det->count; i++) {
        float d = det->mags[i] - mean;
        var += d * d;
    }
    if (det->count > 1) {
        var /= (float)(det->count - 1);
    }

    f->mean = mean;
    f->std = sqrtf(var);
    f->rms = sqrtf(sumsq / (float)det->count);
    f->peak = peak;
    f->jerk = jerk_sum / (float)det->count;
}

void accel_detector_init(accel_detector_t *det) {
    memset(det, 0, sizeof(*det));
    det->lp_alpha = 0.2f;
    det->anomaly_threshold = 4.0f;
    det->persistence_windows = 3;
    det->warmup_windows = 20;
    det->sample_rate_hz = 100.0f;
}

accel_result_t accel_detector_process(accel_detector_t *det, const accel_sample_t *sample) {
    accel_result_t result;
    memset(&result, 0, sizeof(result));

    float mag = sqrtf(sample->ax * sample->ax +
                      sample->ay * sample->ay +
                      sample->az * sample->az);

    float mag_f = lowpass_update(det, mag);

    float jerk = 0.0f;
    if (det->prev_mag_valid) {
        jerk = fabsf(mag_f - det->prev_mag) * det->sample_rate_hz;
    }
    det->prev_mag = mag_f;
    det->prev_mag_valid = true;

    det->mags[det->index] = mag_f;
    det->jerks[det->index] = jerk;
    det->index = (det->index + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) {
        det->count++;
    }

    if (det->count < WINDOW_SIZE) {
        result.ready = false;
        return result;
    }

    // Note:
    // This simple implementation assumes features are extracted from the full arrays.
    // Since ring-buffer order is ignored for mean/std/rms/peak/avg jerk, that's okay.
    extract_features(det, &result.features);

    result.ready = true;
    det->window_count++;

    if (det->window_count <= det->warmup_windows) {
        baseline_update(&det->baseline, &result.features);
        result.warmup = true;
        result.score = 0.0f;
        return result;
    }

    result.score = baseline_score(&det->baseline, &result.features);
    result.raw_anomaly = (result.score > det->anomaly_threshold);

    if (result.raw_anomaly) {
        det->consecutive_anomalies++;
    } else {
        det->consecutive_anomalies = 0;
        baseline_update(&det->baseline, &result.features);
    }

    result.anomaly_event = (det->consecutive_anomalies >= det->persistence_windows);
    return result;
}
