## Example usage

```c
#include <stdio.h>

int main(void)
{
    SensorPipeline pipeline;
    sensor_pipeline_init(&pipeline);

    // Example stream of samples
    AccelSample samples[] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 1.01f},
        {0.02f, 0.03f, 0.99f},
        // ...
    };

    size_t n = sizeof(samples) / sizeof(samples[0]);

    for (size_t i = 0; i < n; i++) {
        PipelineResult r = sensor_pipeline_process(&pipeline, &samples[i]);

        if (r.window_ready) {
            printf("mean=%.3f var=%.3f peak=%.3f jerk=%.3f score=%.3f anomaly=%d\n",
                   r.features.mean,
                   r.features.variance,
                   r.features.peak,
                   r.features.mean_jerk,
                   r.anomaly_score,
                   r.anomaly_detected ? 1 : 0);
        }
    }

    return 0;
}
