} sensor_pipeline_output_t;

void sensor_pipeline_init(sensor_pipeline_state_t *state);

sensor_pipeline_output_t sensor_pipeline_process(
    vec3f_t raw_sample,
    sensor_pipeline_state_t *state,
    const sensor_pipeline_config_t *cfg);

#endif
