Below is an initial embedded-oriented implementation for an accelerometer anomaly-detection pipeline.

It is designed to be:
- simple,
- streaming,
- low-memory,
- easy to port to microcontrollers.

It includes:
1. preprocessing,
2. feature extraction,
3. online baseline estimation,
4. anomaly scoring,
5. thresholding with cooldown.

I’ll provide:
- a short design overview,
- a C implementation,
- notes for embedded deployment.

---

# 1. Design overview

## Input
Assume 3-axis accelerometer samples:

- `ax`
- `ay`
- `az`

sampled at a fixed rate.

## Pipeline
For each sample:
1. Remove DC / slow drift using a simple high-pass style update.
2. Compute acceleration magnitude.
3. Smooth the magnitude.
4. Estimate a rolling baseline mean and variance.
5. Compute a z-score-like anomaly score.
6. Trigger anomaly if score exceeds threshold for enough consecutive samples.

## Why this approach
This is a good initial implementation because it:
- avoids FFTs and large buffers,
- uses constant memory,
- works online,
- is robust enough for vibration/spike detection,
- can be tuned later.

---

# 2. C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - 3-axis input
 * - simple DC tracking / high-pass behavior
 * - magnitude feature
 * - exponential smoothing
 * - online baseline mean/variance
 * - z-score anomaly detection
 * - debounce / consecutive-hit logic
 *
 * Notes:
 * - Replace sqrtf() if needed for performance.
 * - For very small MCUs, consider fixed-point arithmetic.
 */

#ifndef EPSILON
#define EPSILON 1e-6f
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    // DC estimate for each axis
    float dc_ax;
    float dc_ay;
    float dc_az;

    // Smoothed feature
    float smoothed_mag;

    // Baseline statistics
    float mean;
    float var;

    // Detection state
    uint16_t consecutive_hits;
    uint16_t cooldown_counter;
    bool initialized;
} AnomalyDetectorState;

typedef struct {
    // DC tracking factor: smaller = slower DC adaptation
    float dc_alpha;

    // Feature smoothing factor
    float smooth_alpha;

    // Baseline adaptation factor
    float stats_alpha;

    // Detection threshold in z-score units
    float z_threshold;

    // Number of consecutive threshold crossings to trigger anomaly
    uint16_t required_consecutive_hits;

    // Cooldown period after anomaly trigger
    uint16_t cooldown_samples;

    // Whether to freeze baseline updates during strong anomalies
    bool freeze_stats_on_anomaly;
} AnomalyDetectorConfig;

typedef struct {
    float filtered_ax;
    float filtered_ay;
    float filtered_az;
    float magnitude;
    float smoothed_magnitude;
    float mean;
    float stddev;
    float zscore;
    bool anomaly;
} AnomalyDetectorOutput;

static void anomaly_detector_init(
    AnomalyDetectorState *state,
    const AccelSample *initial_sample
) {
    state->dc_ax = initial_sample->ax;
    state->dc_ay = initial_sample->ay;
    state->dc_az = initial_sample->az;

    state->smoothed_mag = 0.0f;
    state->mean = 0.0f;
    state->var = 1.0f;
    state->consecutive_hits = 0;
    state->cooldown_counter = 0;
    state->initialized = true;
}

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static void anomaly_detector_process(
    AnomalyDetectorState *state,
    const AnomalyDetectorConfig *cfg,
    const AccelSample *sample,
    AnomalyDetectorOutput *out
) {
    if (!state->initialized) {
        anomaly_detector_init(state, sample);
    }

    // 1. Track DC / gravity estimate using EMA
    state->dc_ax += cfg->dc_alpha * (sample->ax - state->dc_ax);
    state->dc_ay += cfg->dc_alpha * (sample->ay - state->dc_ay);
    state->dc_az += cfg->dc_alpha * (sample->az - state->dc_az);

    // High-pass style signal
    float fax = sample->ax - state->dc_ax;
    float fay = sample->ay - state->dc_ay;
    float faz = sample->az - state->dc_az;

    // 2. Magnitude feature
    float mag = sqrtf(fax * fax + fay * fay + faz * faz);

    // 3. Smooth feature
    state->smoothed_mag += cfg->smooth_alpha * (mag - state->smoothed_mag);
    float feat = state->smoothed_mag;

    // 4. Compute current score using previous baseline
    float stddev = sqrtf(state->var + EPSILON);
    float z = (feat - state->mean) / stddev;
    float abs_z = fast_absf(z);

    bool over_threshold = (abs_z >= cfg->z_threshold);
    bool in_cooldown = (state->cooldown_counter > 0);

    // 5. Update baseline stats
    // Optionally freeze adaptation during strong anomalies
    bool freeze_stats = cfg->freeze_stats_on_anomaly && over_threshold;

    if (!freeze_stats) {
        float delta = feat - state->mean;
        state->mean += cfg->stats_alpha * delta;

        float delta2 = feat - state->mean;
        state->var = (1.0f - cfg->stats_alpha) * state->var
                   + cfg->stats_alpha * delta * delta2;

        if (state->var < EPSILON) {
            state->var = EPSILON;
        }
    }

    // Recompute stddev for output clarity
    stddev = sqrtf(state->var + EPSILON);

    // 6. Debounce / trigger logic
    bool anomaly = false;

    if (!in_cooldown) {
        if (over_threshold) {
            if (state->consecutive_hits < 0xFFFF) {
                state->consecutive_hits++;
            }
        } else {
            state->consecutive_hits = 0;
        }

        if (state->consecutive_hits >= cfg->required_consecutive_hits) {
            anomaly = true;
            state->consecutive_hits = 0;
            state->cooldown_counter = cfg->cooldown_samples;
        }
    } else {
        state->cooldown_counter--;
        state->consecutive_hits = 0;
    }

    // Fill output
    out->filtered_ax = fax;
    out->filtered_ay = fay;
    out->filtered_az = faz;
    out->magnitude = mag;
    out->smoothed_magnitude = feat;
    out->mean = state->mean;
    out->stddev = stddev;
    out->zscore = z;
    out->anomaly = anomaly;
}

static AnomalyDetectorConfig anomaly_detector_default_config(void) {
    AnomalyDetectorConfig cfg;

    cfg.dc_alpha = 0.01f;
    cfg.smooth_alpha = 0.10f;
    cfg.stats_alpha = 0.01f;
    cfg.z_threshold = 4.0f;
    cfg.required_consecutive_hits = 3;
    cfg.cooldown_samples = 25;
    cfg.freeze_stats_on_anomaly = true;

    return cfg;
}
```

