Below is a **minimal working embedded sensor-processing pipeline** in **C** that:

- simulates **accelerometer samples**
- applies a simple **low-pass filter**
- computes a basic **magnitude-based feature**
- detects **anomalies** using a threshold
- prints results

It is written to be easy to port to a microcontroller.

---

## What it does

Pipeline:

1. **Read accelerometer sample** `(x, y, z)`
2. **Filter** each axis with a simple IIR low-pass filter
3. Compute **signal magnitude**
4. Compare against a **baseline threshold**
5. Flag anomaly if deviation is too large

This is intentionally minimal, but functional.

---

## Minimal C example

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;   // low-pass filter coefficient
    float fx, fy, fz;
    int initialized;
} LowPassFilter;

typedef struct {
    float baseline;     // expected magnitude
    float threshold;    // allowed deviation
} AnomalyDetector;

// --- Low-pass filter ---
void lpf_init(LowPassFilter *f, float alpha) {
    f->alpha = alpha;
    f->fx = f->fy = f->fz = 0.0f;
    f->initialized = 0;
}

AccelSample lpf_apply(LowPassFilter *f, AccelSample in) {
    if (!f->initialized) {
        f->fx = in.x;
        f->fy = in.y;
        f->fz = in.z;
        f->initialized = 1;
    } else {
        f->fx = f->alpha * in.x + (1.0f - f->alpha) * f->fx;
        f->fy = f->alpha * in.y + (1.0f - f->alpha) * f->fy;
        f->fz = f->alpha * in.z + (1.0f - f->alpha) * f->fz;
    }

    AccelSample out = { f->fx, f->fy, f->fz };
    return out;
}

// --- Feature extraction ---
float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// --- Anomaly detector ---
void detector_init(AnomalyDetector *d, float baseline, float threshold) {
    d->baseline = baseline;
    d->threshold = threshold;
}

int detector_is_anomaly(AnomalyDetector *d, float magnitude) {
    float deviation = fabsf(magnitude - d->baseline);
    return deviation > d->threshold;
}

// --- Simulated sensor input ---
AccelSample get_sample(int t) {
    // Normal data around 1g on Z axis
    AccelSample s = {0.02f, -0.01f, 1.00f};

    // Inject anomaly
    if (t == 20 || t == 21 || t == 22) {
        s.x = 1.5f;
        s.y = 1.2f;
        s.z = 0.3f;
    }

    return s;
}

int main(void) {
    LowPassFilter filter;
    AnomalyDetector detector;

    lpf_init(&filter, 0.2f);
    detector_init(&detector, 1.0f, 0.35f);

    for (int t = 0; t < 50; t++) {
        AccelSample raw = get_sample(t);
        AccelSample filtered = lpf_apply(&filter, raw);
        float mag = accel_magnitude(filtered);
        int anomaly = detector_is_anomaly(&detector, mag);

        printf("t=%02d raw=(%.2f, %.2f, %.2f) filt=(%.2f, %.2f, %.2f) mag=%.2f %s\n",
               t,
               raw.x, raw.y, raw.z,
               filtered.x, filtered.y, filtered.z,
               mag,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

