Below is a **minimal working embedded-style sensor-processing pipeline** in **C** that:

- simulates accelerometer samples,
- computes a simple magnitude feature,
- smooths it with a moving average,
- detects anomalies using a threshold,
- prints alerts.

This is intentionally small and easy to port to a microcontroller.

---

## Features

Pipeline stages:

1. **Read accelerometer sample** `(x, y, z)`
2. **Compute magnitude approximation**  
   - uses `abs(x) + abs(y) + abs(z)` to avoid floating point and `sqrt`
3. **Smooth signal**
   - moving average over a small window
4. **Detect anomaly**
   - if smoothed magnitude exceeds threshold, flag anomaly

---

## Minimal C Example

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#define WINDOW_SIZE 8
#define THRESHOLD   4200
#define NUM_SAMPLES 40

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverage;

// Initialize moving average state
void ma_init(MovingAverage *ma) {
    ma->sum = 0;
    ma->index = 0;
    ma->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0;
    }
}

// Update moving average with new value
int32_t ma_update(MovingAverage *ma, int32_t value) {
    ma->sum -= ma->buffer[ma->index];
    ma->buffer[ma->index] = value;
    ma->sum += value;

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    if (ma->count < WINDOW_SIZE) {
        ma->count++;
    }

    return ma->sum / ma->count;
}

// Lightweight magnitude approximation
int32_t accel_magnitude(AccelSample s) {
    return abs(s.x) + abs(s.y) + abs(s.z);
}

// Simple anomaly detector
int detect_anomaly(int32_t filtered_mag) {
    return filtered_mag > THRESHOLD;
}

// Simulated accelerometer input
AccelSample get_sample(int i) {
    AccelSample s;

    // Normal baseline around gravity on Z axis
    s.x = (rand() % 100) - 50;
    s.y = (rand() % 100) - 50;
    s.z = 1000 + (rand() % 100 - 50);

    // Inject anomaly
    if (i == 15 || i == 30) {
        s.x = 2000;
        s.y = 1800;
        s.z = 2200;
    }

    return s;
}

int main(void) {
    MovingAverage ma;
    ma_init(&ma);

    for (int i = 0; i < NUM_SAMPLES; i++) {
        AccelSample s = get_sample(i);

        int32_t mag = accel_magnitude(s);
        int32_t filtered = ma_update(&ma, mag);
        int anomaly = detect_anomaly(filtered);

        printf("sample=%2d x=%6d y=%6d z=%6d mag=%6ld avg=%6ld %s\n",
               i, s.x, s.y, s.z,
               (long)mag, (long)filtered,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

