Below is a **minimal working example** of an embedded-style sensor-processing pipeline for **accelerometer anomaly detection**.

It includes:

- simulated accelerometer input
- simple preprocessing
- magnitude feature extraction
- moving baseline
- threshold-based anomaly detection
- C code suitable as a starting point for microcontrollers

---

## 1. Design

Pipeline:

1. **Read accelerometer sample**: `ax, ay, az`
2. **Compute magnitude squared**: `mag2 = ax*ax + ay*ay + az*az`
3. **Low-pass baseline update**: track normal motion level
4. **Compute deviation**: `abs(mag2 - baseline)`
5. **Flag anomaly** if deviation exceeds threshold

This avoids expensive `sqrt()` and keeps computation lightweight.

---

## 2. Minimal C implementation

```c
#include <stdio.h>
#include <stdint.h>

typedef struct {
    float baseline;
    float alpha;       // smoothing factor for baseline
    float threshold;   // anomaly threshold
    uint8_t initialized;
} AnomalyDetector;

void detector_init(AnomalyDetector *det, float alpha, float threshold) {
    det->baseline = 0.0f;
    det->alpha = alpha;
    det->threshold = threshold;
    det->initialized = 0;
}

int detector_process(AnomalyDetector *det, float ax, float ay, float az, float *score) {
    float mag2 = ax * ax + ay * ay + az * az;

    if (!det->initialized) {
        det->baseline = mag2;
        det->initialized = 1;
    }

    // Exponential moving average baseline
    det->baseline = det->alpha * mag2 + (1.0f - det->alpha) * det->baseline;

    // Deviation from baseline
    float deviation = mag2 - det->baseline;
    if (deviation < 0) deviation = -deviation;

    *score = deviation;

    return (deviation > det->threshold) ? 1 : 0;
}

int main(void) {
    AnomalyDetector det;
    detector_init(&det, 0.05f, 20.0f);

    // Simulated accelerometer stream
    float samples[][3] = {
        {0.0f, 0.1f, 1.0f},
        {0.1f, 0.0f, 0.98f},
        {0.05f, -0.02f, 1.01f},
        {0.0f, 0.0f, 1.0f},
        {3.0f, 2.5f, 0.5f},   // anomaly
        {0.02f, 0.03f, 0.99f},
        {0.0f, 0.1f, 1.02f}
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        float score = 0.0f;
        int anomaly = detector_process(&det,
                                       samples[i][0],
                                       samples[i][1],
                                       samples[i][2],
                                       &score);

        printf("Sample %d: ax=%.2f ay=%.2f az=%.2f score=%.3f %s\n",
               i,
               samples[i][0], samples[i][1], samples[i][2],
               score,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

