# 2. Minimal anomaly logic

A very small and practical detector:

- Compute acceleration magnitude:

\[
m = \sqrt{ax^2 + ay^2 + az^2}
\]

- Over a window of samples:
  - mean
  - variance
  - max

- Flag anomaly if:
  - `max > PEAK_THRESHOLD`, or
  - `variance > VAR_THRESHOLD`

This works for basic shock/vibration anomaly detection.

---

# 3. Minimal embedded C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define PEAK_THRESHOLD 1.8f
#define VAR_THRESHOLD  0.05f

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float peak;
} Features;

static float magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static Features extract_features(const AccelSample *window, int size) {
    Features f = {0};
    float mags[WINDOW_SIZE];
    float sum = 0.0f;

    for (int i = 0; i < size; i++) {
        mags[i] = magnitude(window[i]);
        sum += mags[i];
        if (i == 0 || mags[i] > f.peak) {
            f.peak = mags[i];
        }
    }

    f.mean = sum / size;

    float var_sum = 0.0f;
    for (int i = 0; i < size; i++) {
        float d = mags[i] - f.mean;
        var_sum += d * d;
    }
    f.variance = var_sum / size;

    return f;
}

static int detect_anomaly(Features f) {
    if (f.peak > PEAK_THRESHOLD) {
        return 1;
    }
    if (f.variance > VAR_THRESHOLD) {
        return 1;
    }
    return 0;
}

int main(void) {
    // Simulated accelerometer stream
    AccelSample samples[WINDOW_SIZE] = {
        {0.01f, 0.02f, 0.98f}, {0.00f, 0.01f, 1.01f},
        {0.02f, 0.00f, 0.99f}, {0.01f, 0.01f, 1.00f},
        {0.00f, 0.03f, 0.97f}, {0.02f, 0.02f, 1.00f},
        {0.01f, 0.01f, 0.99f}, {0.00f, 0.00f, 1.02f},
        {0.01f, 0.02f, 0.98f}, {0.00f, 0.01f, 1.00f},
        {0.02f, 0.01f, 1.01f}, {0.01f, 0.00f, 0.99f},
        {0.00f, 0.02f, 1.00f}, {0.01f, 0.01f, 0.98f},
        {0.02f, 0.00f, 1.00f}, {0.01f, 0.01f, 1.01f},
        {0.00f, 0.02f, 0.99f}, {0.01f, 0.01f, 1.00f},
        {0.02f, 0.01f, 0.98f}, {0.00f, 0.00f, 1.00f},
        {0.01f, 0.02f, 1.01f}, {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.00f}, {0.01f, 0.01f, 0.98f},
        {0.00f, 0.02f, 1.00f}, {0.01f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f}, {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.98f}, {0.02f, 0.00f, 1.00f},
        {0.01f, 0.01f, 0.99f}, {0.80f, 0.90f, 1.60f} // anomaly spike
    };

    Features f = extract_features(samples, WINDOW_SIZE);
    int anomaly = detect_anomaly(f);

    printf("Mean: %.3f\n", f.mean);
    printf("Variance: %.3f\n", f.variance);
    printf("Peak: %.3f\n", f.peak);
    printf("Anomaly: %s\n", anomaly ? "YES" : "NO");

    return 0;
}
```

