# 5. Microcontroller-style streaming version

For a real embedded system, you usually process samples continuously rather than all at once.

Here is a minimal ring-buffer version:

```c
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define PEAK_THRESHOLD 1.8f
#define VAR_THRESHOLD  0.05f

typedef struct {
    float ax, ay, az;
} AccelSample;

typedef struct {
    AccelSample buffer[WINDOW_SIZE];
    uint16_t index;
    uint8_t full;
} AccelWindow;

typedef struct {
    float mean;
    float variance;
    float peak;
} Features;

static float magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void window_add(AccelWindow *w, AccelSample s) {
    w->buffer[w->index] = s;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->index == 0) {
        w->full = 1;
    }
}

static Features compute_features(const AccelWindow *w) {
    Features f = {0};
    float mags[WINDOW_SIZE];
    float sum = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        mags[i] = magnitude(w->buffer[i]);
        sum += mags[i];
        if (i == 0 || mags[i] > f.peak) {
            f.peak = mags[i];
        }
    }

    f.mean = sum / WINDOW_SIZE;

    float var_sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float d = mags[i] - f.mean;
        var_sum += d * d;
    }
    f.variance = var_sum / WINDOW_SIZE;

    return f;
}

static int is_anomaly(const Features *f) {
    return (f->peak > PEAK_THRESHOLD) || (f->variance > VAR_THRESHOLD);
}
```

Typical usage in firmware loop:

```c
AccelWindow win = {0};

while (1) {
    AccelSample s = read_accelerometer(); // platform-specific
    window_add(&win, s);

    if (win.full) {
        Features f = compute_features(&win);
        if (is_anomaly(&f)) {
            trigger_alert();
        }
    }
}
```

