   Convert 3-axis data into one scalar:
   \[
   mag = |ax| + |ay| + |az|
   \]
   This is cheaper than square root.

2. **Low-pass baseline filter**  
   Track normal motion/background:
   \[
   baseline = baseline + \alpha (mag - baseline)
   \]

3. **Deviation**
   \[
   dev = |mag - baseline|
   \]

4. **Anomaly decision**
   If `dev > threshold`, flag anomaly.

This is simple, fast, and realistic for embedded systems.

---

## Minimal C code

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    float baseline;
    float alpha;
    float threshold;
    uint8_t initialized;
} AnomalyDetector;

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
} AccelSample;

static float absf(float x) {
    return (x < 0) ? -x : x;
}

static int16_t absi16(int16_t x) {
    return (x < 0) ? -x : x;
}

void detector_init(AnomalyDetector *det, float alpha, float threshold) {
    det->baseline = 0.0f;
    det->alpha = alpha;
    det->threshold = threshold;
    det->initialized = 0;
}

uint8_t detector_process(AnomalyDetector *det, AccelSample s, float *dev_out) {
    float mag = (float)(absi16(s.ax) + absi16(s.ay) + absi16(s.az));

    if (!det->initialized) {
        det->baseline = mag;
        det->initialized = 1;
    }

    det->baseline = det->baseline + det->alpha * (mag - det->baseline);

    float dev = absf(mag - det->baseline);
    if (dev_out) {
        *dev_out = dev;
    }

    return (dev > det->threshold) ? 1 : 0;
}

int main(void) {
    AnomalyDetector det;
    detector_init(&det, 0.05f, 500.0f);

    AccelSample samples[] = {
        {100, 105, 980},
        {102, 98,  978},
        {101, 103, 982},
        {99,  101, 979},
        {100, 100, 981},
        {800, -700, 1500},   // anomaly
        {103, 99,  977},
        {101, 102, 980},
        {-900, 850, -1200},  // anomaly
        {100, 100, 980}
    };

    size_t count = sizeof(samples) / sizeof(samples[0]);

    for (size_t i = 0; i < count; i++) {
        float dev = 0.0f;
        uint8_t anomaly = detector_process(&det, samples[i], &dev);

        printf("sample %zu: ax=%d ay=%d az=%d dev=%.2f %s\n",
               i,
               samples[i].ax,
               samples[i].ay,
               samples[i].az,
               dev,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

