## Minimal C Example

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float filtered_mag;
    float alpha;       // low-pass filter coefficient
    float baseline;    // expected normal magnitude
    float threshold;   // anomaly threshold
} PipelineState;

// Compute vector magnitude
static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// One-pole low-pass filter
static float lowpass(float input, float prev, float alpha) {
    return alpha * input + (1.0f - alpha) * prev;
}

// Process one sample, return 1 if anomaly detected
static int process_sample(PipelineState *state, AccelSample sample) {
    float mag = magnitude(sample);
    state->filtered_mag = lowpass(mag, state->filtered_mag, state->alpha);

    float deviation = fabsf(state->filtered_mag - state->baseline);

    if (deviation > state->threshold) {
        return 1;
    }
    return 0;
}

int main(void) {
    PipelineState state = {
        .filtered_mag = 1.0f,
        .alpha = 0.2f,
        .baseline = 1.0f,   // assume ~1g normalized
        .threshold = 0.35f
    };

    // Simulated accelerometer stream
    AccelSample samples[] = {
        {0.02f, 0.01f, 0.99f},
        {0.03f, 0.00f, 1.01f},
        {0.01f, 0.02f, 0.98f},
        {0.04f, 0.02f, 1.00f},
        {1.20f, 0.80f, 1.50f}, // anomaly
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.03f, 0.97f}
    };

    int count = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < count; i++) {
        int anomaly = process_sample(&state, samples[i]);

        printf("sample=%d filtered_mag=%.3f", i, state.filtered_mag);
        if (anomaly) {
            printf("  <-- ANOMALY");
        }
        printf("\n");
    }

    return 0;
}
```

