## Minimal C Example

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#define WINDOW_SIZE 8
#define THRESHOLD   4000

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static int32_t abs16(int16_t v) {
    return (v < 0) ? -v : v;
}

static int32_t accel_magnitude_l1(AccelSample s) {
    return abs16(s.x) + abs16(s.y) + abs16(s.z);
}

static int32_t filter_update(MovingAverageFilter *f, int32_t value) {
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = value;
    f->sum += value;

    f->index = (f->index + 1) % WINDOW_SIZE;
    if (f->count < WINDOW_SIZE) {
        f->count++;
    }

    return f->sum / f->count;
}

static int detect_anomaly(int32_t smoothed_magnitude, int32_t baseline) {
    int32_t delta = smoothed_magnitude - baseline;
    return (delta > THRESHOLD) ? 1 : 0;
}

/* Simulated sensor input */
static AccelSample get_next_sample(int t) {
    AccelSample s;

    /* Normal motion around ~1g on Z axis */
    s.x = (rand() % 200) - 100;
    s.y = (rand() % 200) - 100;
    s.z = 1000 + ((rand() % 200) - 100);

    /* Inject anomaly */
    if (t == 30 || t == 31 || t == 32) {
        s.x += 3000;
        s.y += 2500;
        s.z += 2000;
    }

    return s;
}

int main(void) {
    MovingAverageFilter filter;
    filter_init(&filter);

    /* Baseline for stationary/normal condition:
       approximately |0| + |0| + |1000| = 1000 */
    const int32_t baseline = 1000;

    for (int t = 0; t < 60; t++) {
        AccelSample sample = get_next_sample(t);

        int32_t mag = accel_magnitude_l1(sample);
        int32_t smoothed = filter_update(&filter, mag);
        int anomaly = detect_anomaly(smoothed, baseline);

        printf("t=%02d x=%6d y=%6d z=%6d mag=%6ld smooth=%6ld anomaly=%d\n",
               t, sample.x, sample.y, sample.z,
               (long)mag, (long)smoothed, anomaly);
    }

    return 0;
}
```

