        f->buffer[i] = 0;
    }
}

int32_t filter_update(MovingAverageFilter *f, int32_t value) {
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = value;
    f->sum += value;

    f->index = (f->index + 1) % WINDOW_SIZE;
    if (f->count < WINDOW_SIZE) {
        f->count++;
    }

    return f->sum / f->count;
}

// Cheap magnitude approximation for embedded use
int32_t accel_magnitude(const AccelSample *s) {
    int32_t ax = abs(s->x);
    int32_t ay = abs(s->y);
    int32_t az = abs(s->z);
    return ax + ay + az;
}

int detect_anomaly(int32_t raw_mag, int32_t avg_mag) {
    int32_t diff = raw_mag - avg_mag;
    if (diff < 0) diff = -diff;
    return diff > THRESHOLD;
}

// Simulated sensor input
AccelSample get_sample(int i) {
    AccelSample s;

    // baseline motion around gravity on Z
    s.x = (rand() % 21) - 10;
    s.y = (rand() % 21) - 10;
    s.z = 1000 + ((rand() % 21) - 10);

    // inject anomaly
    if (i == 15 || i == 30) {
        s.x += 500;
        s.y += 400;
    }

    return s;
}

int main(void) {
    MovingAverageFilter filter;
    filter_init(&filter);

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        AccelSample s = get_sample(i);

        int32_t mag = accel_magnitude(&s);
        int32_t avg = filter_update(&filter, mag);
        int anomaly = detect_anomaly(mag, avg);

        printf("sample=%2d ax=%5d ay=%5d az=%5d mag=%5ld avg=%5ld %s\n",
               i, s.x, s.y, s.z, (long)mag, (long)avg,
               anomaly ? "<-- ANOMALY" : "");

