## 2. Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float baseline;
    float alpha;      // low-pass filter coefficient
    float threshold;  // anomaly threshold
    uint8_t initialized;
} AnomalyDetector;

// Compute acceleration magnitude
static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

// Initialize detector
void detector_init(AnomalyDetector *det, float alpha, float threshold) {
    det->baseline = 0.0f;
    det->alpha = alpha;
    det->threshold = threshold;
    det->initialized = 0;
}

// Process one sample, return 1 if anomaly detected
int detector_process(AnomalyDetector *det, AccelSample s, float *deviation_out) {
    float mag = accel_magnitude(s);

    if (!det->initialized) {
        det->baseline = mag;
        det->initialized = 1;
    }

    // Update baseline using low-pass filter
    det->baseline = det->alpha * mag + (1.0f - det->alpha) * det->baseline;

    // Compute deviation from baseline
    float deviation = fabsf(mag - det->baseline);

    if (deviation_out) {
        *deviation_out = deviation;
    }

    return (deviation > det->threshold) ? 1 : 0;
}

int main(void) {
    AnomalyDetector detector;
    detector_init(&detector, 0.1f, 2.0f);

    // Simulated accelerometer stream
    AccelSample samples[] = {
        {0.0f, 0.0f, 9.8f},
        {0.1f, 0.1f, 9.7f},
        {0.2f, 0.0f, 9.9f},
        {0.1f, -0.1f, 9.8f},
        {3.0f, 4.0f, 15.0f},   // anomaly
        {0.0f, 0.0f, 9.8f},
        {0.1f, 0.2f, 9.7f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float deviation;
        int anomaly = detector_process(&detector, samples[i], &deviation);

        printf("Sample %d: mag=%.2f baseline=%.2f deviation=%.2f %s\n",
               i,
               accel_magnitude(samples[i]),
               detector.baseline,
               deviation,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
