#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#define WINDOW_SIZE 8
#define THRESHOLD 3000   // tune for your sensor scale
#define NUM_SAMPLES 40

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelSample;

typedef struct {
    int32_t buffer[WINDOW_SIZE];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

// Simple absolute value for int32
static int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

// Approximate acceleration magnitude without sqrt:
// |x| + |y| + |z|
static int32_t compute_feature(AccelSample s) {
    return iabs32(s.x) + iabs32(s.y) + iabs32(s.z);
}

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static int32_t filter_update(MovingAverageFilter *f, int32_t input) {
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = input;
    f->sum += input;

    f->index = (f->index + 1) % WINDOW_SIZE;
    if (f->count < WINDOW_SIZE) {
        f->count++;
    }

    return f->sum / f->count;
}

// Anomaly if current feature deviates strongly from smoothed baseline
static uint8_t detect_anomaly(int32_t feature, int32_t baseline) {
    int32_t delta = iabs32(feature - baseline);
    return (delta > THRESHOLD) ? 1 : 0;
}

// Simulated accelerometer stream
static AccelSample get_sample(int i) {
    AccelSample s;

    // Normal motion
    s.x = 100 + (rand() % 40 - 20);
    s.y = 200 + (rand() % 40 - 20);
    s.z = 1000 + (rand() % 40 - 20);

    // Inject anomalies
    if (i == 12 || i == 28) {
        s.x += 1500;
        s.y -= 1200;
        s.z += 1000;
    }

    return s;
}

int main(void) {
