    filter_init(&filter);

    for (int i = 0; i < NUM_SAMPLES; i++) {
        AccelSample sample = get_sample(i);

        int32_t feature = compute_feature(sample);
        int32_t baseline = filter_update(&filter, feature);
        uint8_t anomaly = detect_anomaly(feature, baseline);

        printf("sample=%2d x=%6d y=%6d z=%6d feature=%6ld baseline=%6ld anomaly=%d\n",
               i, sample.x, sample.y, sample.z,
               (long)feature, (long)baseline, anomaly);
    }

    return 0;
}
