## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define ANOMALY_THRESHOLD 0.8f
#define ALPHA_SIGNAL 0.2f     // low-pass for incoming signal
#define ALPHA_BASELINE 0.01f  // slower baseline adaptation

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float filtered_mag;
    float baseline;
    uint8_t initialized;
} PipelineState;

// Compute magnitude of acceleration vector
static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

// Simple exponential low-pass filter
static float low_pass(float prev, float input, float alpha) {
    return alpha * input + (1.0f - alpha) * prev;
}

// Process one sample and return 1 if anomaly detected, else 0
int process_sample(PipelineState *state, AccelSample sample) {
    float mag = accel_magnitude(sample);

    if (!state->initialized) {
        state->filtered_mag = mag;
        state->baseline = mag;
        state->initialized = 1;
        return 0;
    }

    state->filtered_mag = low_pass(state->filtered_mag, mag, ALPHA_SIGNAL);
    state->baseline = low_pass(state->baseline, state->filtered_mag, ALPHA_BASELINE);

    float deviation = fabsf(state->filtered_mag - state->baseline);

    if (deviation > ANOMALY_THRESHOLD) {
        return 1;
    }

    return 0;
}

// Simulated accelerometer stream
int main(void) {
    PipelineState state = {0};

    AccelSample samples[] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 1.00f},
        {0.02f, 0.00f, 0.99f},
        {0.01f, 0.03f, 1.01f},
        {0.00f, 0.02f, 0.97f},
        {1.20f, 0.50f, 1.80f}, // anomaly
        {0.01f, 0.01f, 0.99f},
        {0.02f, 0.02f, 1.00f},
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        int anomaly = process_sample(&state, samples[i]);
        printf("Sample %d: mag=%.3f filtered=%.3f baseline=%.3f anomaly=%d\n",
               i,
               accel_magnitude(samples[i]),
               state.filtered_mag,
               state.baseline,
               anomaly);
    }

    return 0;
}
```

