## Minimal C Example

```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdint.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float x;
    float y;
    float z;
} FilterState;

static FilterState lp_state = {0};

// Simple low-pass filter
static float low_pass(float input, float prev, float alpha) {
    return alpha * input + (1.0f - alpha) * prev;
}

// Simulated accelerometer read
static AccelSample read_accelerometer(int t) {
    AccelSample s;

    // Normal motion around ~1g on Z axis
    s.x = 0.02f * sinf(0.1f * t);
    s.y = 0.03f * cosf(0.1f * t);
    s.z = 1.0f + 0.02f * sinf(0.05f * t);

    // Inject anomaly
    if (t == 50 || t == 51) {
        s.x += 2.5f;
        s.y += 2.0f;
        s.z += 1.5f;
    }

    return s;
}

// Filter sample
static AccelSample filter_sample(AccelSample in, float alpha) {
    lp_state.x = low_pass(in.x, lp_state.x, alpha);
    lp_state.y = low_pass(in.y, lp_state.y, alpha);
    lp_state.z = low_pass(in.z, lp_state.z, alpha);

    AccelSample out = {lp_state.x, lp_state.y, lp_state.z};
    return out;
}

// Compute magnitude
static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// Detect anomaly based on deviation from expected gravity magnitude
static int detect_anomaly(AccelSample s, float threshold) {
    float mag = magnitude(s);
    float deviation = fabsf(mag - 1.0f); // assume resting magnitude near 1g
    return deviation > threshold;
}

int main(void) {
    const float alpha = 0.2f;      // low-pass factor
    const float threshold = 0.5f;  // anomaly threshold in g

    for (int t = 0; t < 100; t++) {
        AccelSample raw = read_accelerometer(t);
        AccelSample filtered = filter_sample(raw, alpha);
        int anomaly = detect_anomaly(filtered, threshold);

        printf("t=%02d raw=(%.2f, %.2f, %.2f) filt=(%.2f, %.2f, %.2f) anomaly=%d\n",
               t,
               raw.x, raw.y, raw.z,
               filtered.x, filtered.y, filtered.z,
               anomaly);
    }

    return 0;
}
```

---

## How it works

### 1. Sensor input
`read_accelerometer()` simulates 3-axis accelerometer data.

### 2. Filtering
A first-order low-pass filter reduces noise:

```c
y[n] = alpha * x[n] + (1 - alpha) * y[n-1]
```

### 3. Feature extraction
We compute total acceleration magnitude:

```c
sqrt(x*x + y*y + z*z)
```

### 4. Anomaly detection
If magnitude differs too much from `1g`, we flag an anomaly.

