## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha;          // low-pass filter coefficient
    float filtered_mag;   // filtered magnitude
    float baseline;       // expected normal magnitude
    float threshold;      // anomaly threshold
    uint8_t initialized;
} SensorPipeline;

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

void pipeline_init(SensorPipeline *p, float alpha, float baseline, float threshold) {
    p->alpha = alpha;
    p->filtered_mag = 0.0f;
    p->baseline = baseline;
    p->threshold = threshold;
    p->initialized = 0;
}

int pipeline_process(SensorPipeline *p, AccelSample sample, float *feature_out) {
    float mag = accel_magnitude(sample);

    if (!p->initialized) {
        p->filtered_mag = mag;
        p->initialized = 1;
    } else {
        p->filtered_mag = p->alpha * mag + (1.0f - p->alpha) * p->filtered_mag;
    }

    *feature_out = p->filtered_mag;

    float deviation = fabsf(p->filtered_mag - p->baseline);
    return (deviation > p->threshold) ? 1 : 0;
}

int main(void) {
    SensorPipeline pipeline;
    pipeline_init(&pipeline, 0.2f, 1.0f, 0.25f);

    AccelSample samples[] = {
        {0.02f, 0.01f, 0.98f},
        {0.03f, 0.00f, 1.01f},
        {0.01f, 0.02f, 0.99f},
        {0.04f, 0.03f, 1.02f},
        {0.80f, 0.75f, 1.60f}, // anomaly
        {0.02f, 0.01f, 0.97f},
        {0.01f, 0.00f, 1.00f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float feature = 0.0f;
        int anomaly = pipeline_process(&pipeline, samples[i], &feature);

        printf("sample %d: filtered_mag=%.3f anomaly=%d\n", i, feature, anomaly);
    }

    return 0;
}
```

