static void actuator_set(bool on, Controller *ctl) {
    if (on) {
        hw_actuator_on();
        ctl->actuator_on = true;
    } else {
        hw_actuator_off();
        ctl->actuator_on = false;
    }
}

static void controller_init(Controller *ctl) {
    uint16_t initial = hw_read_sensor();

    if (!sensor_is_valid(initial)) {
        initial = SENSOR_MIN_VALID;
    }

    filter_init(&ctl->filter, initial);
    ctl->actuator_on = false;
    ctl->sensor_fault_count = 0;
    ctl->fault_active = false;

    actuator_set(false, ctl);
}

static void controller_step(Controller *ctl) {
    uint16_t raw = hw_read_sensor();

    if (!sensor_is_valid(raw)) {
        if (ctl->sensor_fault_count < 255U) {
            ctl->sensor_fault_count++;
        }

        if (ctl->sensor_fault_count >= SENSOR_FAULT_LIMIT) {
            ctl->fault_active = true;
            actuator_set(false, ctl);
            hw_signal_fault();
        }
        return;
    }

    // Valid sample resets fault counter
    ctl->sensor_fault_count = 0;
    ctl->fault_active = false;

    uint16_t filtered = filter_update(&ctl->filter, raw);

    // Hysteresis control
    if (!ctl->actuator_on && filtered >= ACTUATOR_ON_THRESHOLD) {
        actuator_set(true, ctl);
    } else if (ctl->actuator_on && filtered <= ACTUATOR_OFF_THRESHOLD) {
        actuator_set(false, ctl);
    }
}

/* =========================
   Main loop
   ========================= */

int main(void) {
    Controller ctl;
    controller_init(&ctl);

    while (1) {
        controller_step(&ctl);

        // Replace with low-power wait, RTOS delay, or timer scheduling
        // e.g. sleep_ms(10);
    }

    return 0;
}
