#define NUM_SAMPLES         8

#define TEMP_MIN_VALID      (-400)   // e.g. -40.0 C scaled by 10
#define TEMP_MAX_VALID      (1250)   // e.g. 125.0 C scaled by 10

#define PRESS_MIN_VALID     (0)      // e.g. 0.0 kPa scaled by 10
#define PRESS_MAX_VALID     (5000)   // e.g. 500.0 kPa scaled by 10

#define TEMP_FAN_ON         (700)    // 70.0 C
#define TEMP_FAN_OFF        (650)    // 65.0 C

#define PRESS_VALVE_ON      (3000)   // 300.0 kPa
#define PRESS_VALVE_OFF     (2800)   // 280.0 kPa

#define INVALID_LIMIT       3        // consecutive invalid samples before fail-safe

typedef struct {
    int16_t buffer[NUM_SAMPLES];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool fan_on;
    bool valve_open;
} ActuatorState;

typedef struct {
    uint8_t temp_invalid_count;
    uint8_t press_invalid_count;
    bool temp_fault;
    bool press_fault;
} FaultState;

/* ---------- Filter functions ---------- */

static void filter_init(MovingAverageFilter *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (i = 0; i < NUM_SAMPLES; i++) {
        f->buffer[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    if (f->count < NUM_SAMPLES) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index++;
    if (f->index >= NUM_SAMPLES) {
        f->index = 0;
    }

    return (int16_t)(f->sum / f->count);
}

/* ---------- Validation ---------- */

static bool valid_temperature(int16_t value) {
    return (value >= TEMP_MIN_VALID && value <= TEMP_MAX_VALID);
}

static bool valid_pressure(int16_t value) {
    return (value >= PRESS_MIN_VALID && value <= PRESS_MAX_VALID);
}

/* ---------- Hardware abstraction stubs ----------
 * Replace these with MCU-specific drivers.
 */

static int16_t read_temperature_sensor(void) {
    /* Example stub */
    static int16_t mock = 680;
    mock += 5;
    return mock;
}

static int16_t read_pressure_sensor(void) {
    /* Example stub */
    static int16_t mock = 2900;
    mock += 20;
    return mock;
}

static void set_fan(bool on) {
    /* Replace with GPIO write */
    printf("FAN: %s\n", on ? "ON" : "OFF");
}

static void set_valve(bool open) {
    /* Replace with GPIO write */
    printf("VALVE: %s\n", open ? "OPEN" : "CLOSED");
}

/* ---------- Fault handling ---------- */

static void update_fault_counter(bool valid, uint8_t *counter, bool *fault) {
    if (valid) {
        *counter = 0;
        *fault = false;
    } else {
        if (*counter < 255) {
            (*counter)++;
        }
        if (*counter >= INVALID_LIMIT) {
            *fault = true;
        }
    }
}

/* ---------- Control logic ---------- */

static void control_temperature(int16_t filtered_temp,
                                bool temp_fault,
                                ActuatorState *act) {
    if (temp_fault) {
        /* Fail-safe policy: turn fan ON on temperature sensor fault */
        if (!act->fan_on) {
            act->fan_on = true;
            set_fan(true);
        }
        return;
    }

    if (!act->fan_on && filtered_temp >= TEMP_FAN_ON) {
        act->fan_on = true;
        set_fan(true);
    } else if (act->fan_on && filtered_temp <= TEMP_FAN_OFF) {
        act->fan_on = false;
        set_fan(false);
    }
}

static void control_pressure(int16_t filtered_press,
                             bool press_fault,
                             ActuatorState *act) {
    if (press_fault) {
        /* Fail-safe policy: open valve on pressure sensor fault */
        if (!act->valve_open) {
            act->valve_open = true;
            set_valve(true);
        }
        return;
    }

    if (!act->valve_open && filtered_press >= PRESS_VALVE_ON) {
        act->valve_open = true;
        set_valve(true);
    } else if (act->valve_open && filtered_press <= PRESS_VALVE_OFF) {
        act->valve_open = false;
        set_valve(false);
    }
}

/* ---------- Main processing step ---------- */

static void process_step(MovingAverageFilter *temp_filter,
                         MovingAverageFilter *press_filter,
                         FaultState *faults,
                         ActuatorState *act) {
    int16_t raw_temp = read_temperature_sensor();
    int16_t raw_press = read_pressure_sensor();

    bool temp_ok = valid_temperature(raw_temp);
    bool press_ok = valid_pressure(raw_press);

    update_fault_counter(temp_ok, &faults->temp_invalid_count, &faults->temp_fault);
    update_fault_counter(press_ok, &faults->press_invalid_count, &faults->press_fault);

    /* Only update filter with valid values */
    int16_t filtered_temp = 0;
    int16_t filtered_press = 0;

    if (temp_ok) {
        filtered_temp = filter_update(temp_filter, raw_temp);
    }

    if (press_ok) {
        filtered_press = filter_update(press_filter, raw_press);
    }

    control_temperature(filtered_temp, faults->temp_fault, act);
    control_pressure(filtered_press, faults->press_fault, act);

    printf("raw_temp=%d filtered_temp=%d temp_fault=%d | raw_press=%d filtered_press=%d press_fault=%d\n",
           raw_temp, filtered_temp, faults->temp_fault,
           raw_press, filtered_press, faults->press_fault);
}

/* ---------- Main loop ---------- */

int main(void) {
    MovingAverageFilter temp_filter;
    MovingAverageFilter press_filter;
    FaultState faults = {0};
    ActuatorState actuators = {0};

    filter_init(&temp_filter);
    filter_init(&press_filter);

    /*
