static uint16_t ema_update(FilterState *fs, uint8_t idx, uint16_t raw) {
    if (!fs->initialized[idx]) {
        fs->filtered[idx] = raw;
        fs->initialized[idx] = true;
    } else {
        fs->filtered[idx] = fs->filtered[idx] +
                           ((int16_t)(raw - fs->filtered[idx]) >> EMA_SHIFT);
    }
    return fs->filtered[idx];
}
