        sensors[i].raw = clamp_sensor(read_adc(i));
        sensors[i].filtered = filter_update(&sensors[i].filter, sensors[i].raw);
    }
}

/* Actuator logic with hysteresis */
static void actuator_set(Actuator *act, uint8_t actuator_id, uint8_t state) {
    if (act->state != state) {
        act->state = state;
        write_gpio(actuator_id, state);
    }
}

static void control_update(void) {
    uint16_t temp = sensors[0].filtered;
    uint16_t pressure = sensors[1].filtered;

    /* Fan control */
    if (fan_actuator.state == ACTUATOR_OFF && temp >= TEMP_ON_THRESHOLD) {
        actuator_set(&fan_actuator, 0, ACTUATOR_ON);
    } else if (fan_actuator.state == ACTUATOR_ON && temp <= TEMP_OFF_THRESHOLD) {
        actuator_set(&fan_actuator, 0, ACTUATOR_OFF);
    }

    /* Valve control */
    if (valve_actuator.state == ACTUATOR_OFF && pressure >= PRESS_ON_THRESHOLD) {
        actuator_set(&valve_actuator, 1, ACTUATOR_ON);
    } else if (valve_actuator.state == ACTUATOR_ON && pressure <= PRESS_OFF_THRESHOLD) {
        actuator_set(&valve_actuator, 1, ACTUATOR_OFF);
    }
}

/* System init */
static void system_init(void) {
    sensor_init();
    fan_actuator.state = ACTUATOR_OFF;
    valve_actuator.state = ACTUATOR_OFF;
    write_gpio(0, ACTUATOR_OFF);
    write_gpio(1, ACTUATOR_OFF);
}

/* Main loop */
int main(void) {
    system_init();

    while (1) {
        sensor_update();
        control_update();

        /* Replace with low-power wait or RTOS delay */
    }

    return 0;
}
