## File: `edge_system.c`

```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Resource-constrained edge system:
 * - Collects sensor samples
 * - Filters samples using moving average
 * - Controls actuators based on thresholds with hysteresis
 *
 * Design goals:
 * - No dynamic memory
 * - Low CPU overhead
 * - Predictable timing
 * - Easy portability to embedded systems
 */

#define SENSOR_COUNT            3
#define ACTUATOR_COUNT          2
#define FILTER_WINDOW_SIZE      8
#define SENSOR_SAMPLE_MIN       0
#define SENSOR_SAMPLE_MAX       1023

/* Thresholds for actuator control */
#define TEMP_ON_THRESHOLD       700
#define TEMP_OFF_THRESHOLD      650

#define PRESSURE_ON_THRESHOLD   800
#define PRESSURE_OFF_THRESHOLD  750

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
    uint16_t filtered;
} MovingAverageFilter;

typedef struct {
    uint16_t raw_value;
    uint16_t filtered_value;
    MovingAverageFilter filter;
} Sensor;

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} ActuatorState;

typedef struct {
    ActuatorState state;
} Actuator;

typedef struct {
    Sensor sensors[SENSOR_COUNT];
    Actuator actuators[ACTUATOR_COUNT];
    uint32_t tick;
} EdgeSystem;

/* Sensor indices */
enum {
    SENSOR_TEMP = 0,
    SENSOR_PRESSURE = 1,
    SENSOR_HUMIDITY = 2
};

/* Actuator indices */
enum {
    ACTUATOR_COOLING_FAN = 0,
    ACTUATOR_PRESSURE_RELEASE = 1
};

static void filter_init(MovingAverageFilter *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    f->filtered = 0;
    for (i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index++;
    if (f->index >= FILTER_WINDOW_SIZE) {
        f->index = 0;
    }

    f->filtered = (uint16_t)(f->sum / f->count);
    return f->filtered;
}

static void sensor_init(Sensor *s) {
    s->raw_value = 0;
    s->filtered_value = 0;
    filter_init(&s->filter);
}

static void actuator_init(Actuator *a) {
    a->state = ACTUATOR_OFF;
}

/*
 * Replace this with hardware-specific ADC or sensor driver code.
 * Here we simulate changing sensor values.
 */
static uint16_t read_sensor_hw(uint8_t sensor_id, uint32_t tick) {
    switch (sensor_id) {
        case SENSOR_TEMP:
            return (uint16_t)(600 + ((tick * 13) % 180));   /* 600..779 */
        case SENSOR_PRESSURE:
            return (uint16_t)(720 + ((tick * 17) % 140));   /* 720..859 */
        case SENSOR_HUMIDITY:
            return (uint16_t)(400 + ((tick * 7) % 120));    /* 400..519 */
        default:
            return 0;
    }
}

static void actuator_write_hw(uint8_t actuator_id, ActuatorState state) {
    /* Replace with GPIO/relay driver code */
    const char *name = "UNKNOWN";
    if (actuator_id == ACTUATOR_COOLING_FAN) {
        name = "COOLING_FAN";
    } else if (actuator_id == ACTUATOR_PRESSURE_RELEASE) {
        name = "PRESSURE_RELEASE";
    }

    printf("Actuator %s -> %s\n", name, state == ACTUATOR_ON ? "ON" : "OFF");
}

static void actuator_set(EdgeSystem *sys, uint8_t actuator_id, ActuatorState new_state) {
    if (sys->actuators[actuator_id].state != new_state) {
        sys->actuators[actuator_id].state = new_state;
        actuator_write_hw(actuator_id, new_state);
    }
}

static void edge_system_init(EdgeSystem *sys) {
    uint8_t i;
    sys->tick = 0;

    for (i = 0; i < SENSOR_COUNT; i++) {
        sensor_init(&sys->sensors[i]);
    }

    for (i = 0; i < ACTUATOR_COUNT; i++) {
        actuator_init(&sys->actuators[i]);
    }
}

static void edge_system_sample_sensors(EdgeSystem *sys) {
    uint8_t i;
    uint16_t sample;

    for (i = 0; i < SENSOR_COUNT; i++) {
        sample = read_sensor_hw(i, sys->tick);

        if (sample < SENSOR_SAMPLE_MIN) {
            sample = SENSOR_SAMPLE_MIN;
        } else if (sample > SENSOR_SAMPLE_MAX) {
            sample = SENSOR_SAMPLE_MAX;
        }

        sys->sensors[i].raw_value = sample;
        sys->sensors[i].filtered_value = filter_update(&sys->sensors[i].filter, sample);
    }
}

static void edge_system_control(EdgeSystem *sys) {
    uint16_t temp = sys->sensors[SENSOR_TEMP].filtered_value;
    uint16_t pressure = sys->sensors[SENSOR_PRESSURE].filtered_value;

    /* Cooling fan control with hysteresis */
    if (sys->actuators[ACTUATOR_COOLING_FAN].state == ACTUATOR_OFF) {
        if (temp >= TEMP_ON_THRESHOLD) {
            actuator_set(sys, ACTUATOR_COOLING_FAN, ACTUATOR_ON);
        }
    } else {
        if (temp <= TEMP_OFF_THRESHOLD) {
            actuator_set(sys, ACTUATOR_COOLING_FAN, ACTUATOR_OFF);
        }
    }

    /* Pressure release control with hysteresis */
    if (sys->actuators[ACTUATOR_PRESSURE_RELEASE].state == ACTUATOR_OFF) {
        if (pressure >= PRESSURE_ON_THRESHOLD) {
            actuator_set(sys, ACTUATOR_PRESSURE_RELEASE, ACTUATOR_ON);
        }
    } else {
        if (pressure <= PRESSURE_OFF_THRESHOLD) {
            actuator_set(sys, ACTUATOR_PRESSURE_RELEASE, ACTUATOR_OFF);
        }
    }
}

static void edge_system_report(const EdgeSystem *sys) {
    printf("Tick=%lu | Temp raw=%u filt=%u | Pressure raw=%u filt=%u | Humidity raw=%u filt=%u | Fan=%s | Release=%s\n",
           (unsigned long)sys->tick,
           sys->sensors[SENSOR_TEMP].raw_value,
           sys->sensors[SENSOR_TEMP].filtered_value,
           sys->sensors[SENSOR_PRESSURE].raw_value,
           sys->sensors[SENSOR_PRESSURE].filtered_value,
           sys->sensors[SENSOR_HUMIDITY].raw_value,
           sys->sensors[SENSOR_HUMIDITY].filtered_value,
           sys->actuators[ACTUATOR_COOLING_FAN].state == ACTUATOR_ON ? "ON" : "OFF",
           sys->actuators[ACTUATOR_PRESSURE_RELEASE].state == ACTUATOR_ON ? "ON" : "OFF");
}

static void edge_system_step(EdgeSystem *sys) {
    edge_system_sample_sensors(sys);
    edge_system_control(sys);
    edge_system_report(sys);
    sys->tick++;
}

int main(void) {
    EdgeSystem sys;
    uint32_t i;

    edge_system_init(&sys);

    for (i = 0; i < 50; i++) {
        edge_system_step(&sys);
    }

    return 0;
}
```

