## 1. Example C implementation

This is a single-file prototype intended for embedded adaptation.

```c
/*
 * edge_system.c
 *
 * Initial implementation of a resource-constrained edge system:
 * - Reads sensor samples
 * - Applies lightweight filtering
 * - Detects conditions
 * - Manages actuators
 *
 * Designed for:
 * - low memory
 * - predictable execution
 * - no heap allocation in runtime path
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */

#define NUM_SENSORS            3
#define NUM_ACTUATORS          2
#define SENSOR_HISTORY_SIZE    4

/* Example thresholds */
#define TEMP_HIGH_THRESHOLD    75.0f
#define HUMID_LOW_THRESHOLD    25.0f
#define PRESS_HIGH_THRESHOLD   1020.0f

/* Safety timing / debounce */
#define EVENT_DEBOUNCE_COUNT   3

/* =========================
 * Types
 * ========================= */

typedef enum {
    SENSOR_TEMP = 0,
    SENSOR_HUMIDITY = 1,
    SENSOR_PRESSURE = 2
} sensor_id_t;

typedef enum {
    ACTUATOR_FAN = 0,
    ACTUATOR_VALVE = 1
} actuator_id_t;

typedef struct {
    float raw;
    float filtered;
    float history[SENSOR_HISTORY_SIZE];
    uint8_t history_index;
    bool initialized;
} sensor_state_t;

typedef struct {
    bool enabled;
    uint32_t last_change_tick;
} actuator_state_t;

typedef struct {
    uint8_t temp_high_count;
    uint8_t humid_low_count;
    uint8_t press_high_count;
} event_state_t;

typedef struct {
    sensor_state_t sensors[NUM_SENSORS];
    actuator_state_t actuators[NUM_ACTUATORS];
    event_state_t events;
    uint32_t tick;
} edge_system_t;

/* =========================
 * Hardware abstraction
 * Replace with platform-specific implementations
 * ========================= */

static float hal_read_sensor(sensor_id_t id) {
    /* Stubbed example values; replace with ADC/I2C/SPI/etc. */
    switch (id) {
        case SENSOR_TEMP:     return 70.0f + (float)(id);
        case SENSOR_HUMIDITY: return 22.0f;
        case SENSOR_PRESSURE: return 1018.0f;
        default:              return 0.0f;
    }
}

static void hal_set_actuator(actuator_id_t id, bool on) {
    /* Replace with GPIO/PWM/fieldbus write */
    const char *name = (id == ACTUATOR_FAN) ? "FAN" : "VALVE";
    printf("[HAL] %s -> %s\n", name, on ? "ON" : "OFF");
}

/* =========================
 * Filtering
 * ========================= */

/*
 * Simple moving average:
 * - low CPU cost
 * - small memory footprint
 * - decent noise suppression
 */
static float compute_moving_average(sensor_state_t *s, float sample) {
    s->history[s->history_index] = sample;
    s->history_index = (s->history_index + 1) % SENSOR_HISTORY_SIZE;

    float sum = 0.0f;
    uint8_t count = s->initialized ? SENSOR_HISTORY_SIZE : s->history_index;

    if (count == 0) {
        count = 1;
    }

    for (uint8_t i = 0; i < count; i++) {
        sum += s->history[i];
    }

    if (s->history_index == 0) {
        s->initialized = true;
        count = SENSOR_HISTORY_SIZE;
        sum = 0.0f;
        for (uint8_t i = 0; i < count; i++) {
            sum += s->history[i];
        }
    }

    return sum / (float)count;
}

/* =========================
 * Actuator control
 * ========================= */

static void set_actuator_state(edge_system_t *sys, actuator_id_t id, bool enable) {
    actuator_state_t *a = &sys->actuators[id];
    if (a->enabled != enable) {
        a->enabled = enable;
        a->last_change_tick = sys->tick;
        hal_set_actuator(id, enable);
    }
}

/* =========================
 * Event logic
 * ========================= */

static bool debounce_high(float value, float threshold, uint8_t *counter) {
    if (value > threshold) {
        if (*counter < 255) {
            (*counter)++;
        }
    } else {
        *counter = 0;
    }
    return (*counter >= EVENT_DEBOUNCE_COUNT);
}

static bool debounce_low(float value, float threshold, uint8_t *counter) {
    if (value < threshold) {
        if (*counter < 255) {
            (*counter)++;
        }
    } else {
        *counter = 0;
    }
    return (*counter >= EVENT_DEBOUNCE_COUNT);
}

/* =========================
 * Core system functions
 * ========================= */

static void edge_system_init(edge_system_t *sys) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        sys->sensors[i].raw = 0.0f;
        sys->sensors[i].filtered = 0.0f;
        sys->sensors[i].history_index = 0;
        sys->sensors[i].initialized = false;
        for (uint8_t j = 0; j < SENSOR_HISTORY_SIZE; j++) {
            sys->sensors[i].history[j] = 0.0f;
        }
    }

    for (uint8_t i = 0; i < NUM_ACTUATORS; i++) {
        sys->actuators[i].enabled = false;
        sys->actuators[i].last_change_tick = 0;
    }

    sys->events.temp_high_count = 0;
    sys->events.humid_low_count = 0;
    sys->events.press_high_count = 0;
    sys->tick = 0;
}

static void edge_system_sample_sensors(edge_system_t *sys) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        float sample = hal_read_sensor((sensor_id_t)i);
        sys->sensors[i].raw = sample;
        sys->sensors[i].filtered = compute_moving_average(&sys->sensors[i], sample);
    }
}

static void edge_system_process(edge_system_t *sys) {
    float temp = sys->sensors[SENSOR_TEMP].filtered;
    float humid = sys->sensors[SENSOR_HUMIDITY].filtered;
    float press = sys->sensors[SENSOR_PRESSURE].filtered;

    bool temp_high = debounce_high(temp, TEMP_HIGH_THRESHOLD, &sys->events.temp_high_count);
    bool humid_low = debounce_low(humid, HUMID_LOW_THRESHOLD, &sys->events.humid_low_count);
    bool press_high = debounce_high(press, PRESS_HIGH_THRESHOLD, &sys->events.press_high_count);

    /*
     * Example policy:
     * - Turn fan on if temperature is high
     * - Turn valve on if humidity is low
     * - If pressure is high, force valve off as a safety override
     */

    set_actuator_state(sys, ACTUATOR_FAN, temp_high);

    if (press_high) {
        set_actuator_state(sys, ACTUATOR_VALVE, false);
    } else {
        set_actuator_state(sys, ACTUATOR_VALVE, humid_low);
    }
}

static void edge_system_log(const edge_system_t *sys) {
    printf("[Tick %lu] T(raw=%.2f filt=%.2f) H(raw=%.2f filt=%.2f) P(raw=%.2f filt=%.2f) | FAN=%d VALVE=%d\n",
           (unsigned long)sys->tick,
           sys->sensors[SENSOR_TEMP].raw,
           sys->sensors[SENSOR_TEMP].filtered,
           sys->sensors[SENSOR_HUMIDITY].raw,
           sys->sensors[SENSOR_HUMIDITY].filtered,
           sys->sensors[SENSOR_PRESSURE].raw,
           sys->sensors[SENSOR_PRESSURE].filtered,
           sys->actuators[ACTUATOR_FAN].enabled ? 1 : 0,
           sys->actuators[ACTUATOR_VALVE].enabled ? 1 : 0);
}

static void edge_system_step(edge_system_t *sys) {
    sys->tick++;
    edge_system_sample_sensors(sys);
    edge_system_process(sys);
    edge_system_log(sys);
}

/* =========================
 * Main
 * ========================= */

int main(void) {
    edge_system_t sys;
    edge_system_init(&sys);

    /* Simulated loop */
    for (int i = 0; i < 10; i++) {
        edge_system_step(&sys);
    }

    return 0;
}
