 * Configuration
 * ========================= */

#define SENSOR_MIN_VALID       0
#define SENSOR_MAX_VALID       1023

#define ACTUATOR_ON_THRESHOLD  700
#define ACTUATOR_OFF_THRESHOLD 650

/* EMA filter coefficient:
 * filtered = filtered + (raw - filtered) / FILTER_ALPHA_DIV
 * Larger divisor = smoother but slower response
 */
#define FILTER_ALPHA_DIV       8

#define SENSOR_FAULT_LIMIT     5

/* =========================
 * Types
 * ========================= */

typedef struct {
    int32_t filtered_value;
    bool initialized;
} FilterState;

typedef struct {
    bool actuator_on;
    uint8_t consecutive_faults;
    bool sensor_fault;
} SystemState;

/* =========================
 * Hardware abstraction layer
 * Replace these with platform-specific implementations
 * ========================= */

static int read_sensor_raw(void) {
    /* Stub implementation:
     * Replace with ADC read / I2C / SPI / GPIO sensor fetch
     */
    static int mock_data[] = {
        620, 640, 680, 710, 720, 705, 690, 660, 640,
        1100, 1200, 650, 630, 720, 740, 600
    };
    static size_t idx = 0;
    int value = mock_data[idx];
    idx = (idx + 1) % (sizeof(mock_data) / sizeof(mock_data[0]));
    return value;
}

static void actuator_set(bool on) {
    /* Replace with GPIO/PWM/relay control */
    printf("ACTUATOR: %s\n", on ? "ON" : "OFF");
}

static void log_status(int raw, int filtered, const SystemState *sys) {
    printf("raw=%d filtered=%d actuator=%s fault=%s faults=%u\n",
           raw,
           filtered,
           sys->actuator_on ? "ON" : "OFF",
           sys->sensor_fault ? "YES" : "NO",
           sys->consecutive_faults);
}

/* =========================
 * Filtering
 * ========================= */

static int32_t filter_update(FilterState *state, int32_t raw) {
    if (!state->initialized) {
        state->filtered_value = raw;
        state->initialized = true;
    } else {
        state->filtered_value += (raw - state->filtered_value) / FILTER_ALPHA_DIV;
    }
    return state->filtered_value;
}

/* =========================
 * Validation
 * ========================= */

static bool sensor_value_valid(int raw) {
    return (raw >= SENSOR_MIN_VALID && raw <= SENSOR_MAX_VALID);
}

/* =========================
 * Control logic
 * ========================= */

static void update_actuator(SystemState *sys, int32_t filtered_value) {
    if (sys->sensor_fault) {
        if (sys->actuator_on) {
            sys->actuator_on = false;
            actuator_set(false);
        }
        return;
    }

    if (!sys->actuator_on && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        sys->actuator_on = true;
        actuator_set(true);
    } else if (sys->actuator_on && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        sys->actuator_on = false;
        actuator_set(false);
    }
}

/* =========================
 * Main processing step
 * ========================= */

static void process_step(FilterState *filter, SystemState *sys) {
    int raw = read_sensor_raw();

    if (!sensor_value_valid(raw)) {
        if (sys->consecutive_faults < 255) {
            sys->consecutive_faults++;
        }
        if (sys->consecutive_faults >= SENSOR_FAULT_LIMIT) {
            sys->sensor_fault = true;
        }

        log_status(raw, filter->initialized ? filter->filtered_value : -1, sys);
        update_actuator(sys, filter->initialized ? filter->filtered_value : 0);
        return;
    }

    sys->consecutive_faults = 0;
    sys->sensor_fault = false;

    int32_t filtered = filter_update(filter, raw);
    update_actuator(sys, filtered);
    log_status(raw, filtered, sys);
}

/* =========================
 * Initialization
 * ========================= */

static void system_init(FilterState *filter, SystemState *sys) {
    filter->filtered_value = 0;
    filter->initialized = false;

    sys->actuator_on = false;
    sys->consecutive_faults = 0;
    sys->sensor_fault = false;

    actuator_set(false);
}

/* =========================
 * Main
 * ========================= */

int main(void) {
    FilterState filter;
    SystemState sys;

    system_init(&filter, &sys);

    /* In a real edge system, this would run periodically from:
     * - RTOS task
     * - timer interrupt trigger
     * - superloop with delay
     */
    for (int i = 0; i < 30; i++) {
        process_step(&filter, &sys);
    }

    return 0;
}
