#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */

#define MAX_SENSORS         4
#define MAX_ACTUATORS       4
#define FILTER_WINDOW       8

#define SENSOR_MIN_VALID    0
#define SENSOR_MAX_VALID    4095

/* Example thresholds for filtered sensor values */
#define ACTUATOR_ON_THRESH  2500
#define ACTUATOR_OFF_THRESH 2200

/* =========================
 * Types
 * ========================= */

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} actuator_state_t;

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool valid;
} sensor_output_t;

typedef struct {
    uint16_t buffer[FILTER_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} moving_avg_filter_t;

typedef struct {
    uint8_t id;
    moving_avg_filter_t filter;
    sensor_output_t output;
} sensor_t;

typedef struct {
    uint8_t id;
    actuator_state_t state;
} actuator_t;

typedef struct {
    sensor_t sensors[MAX_SENSORS];
    actuator_t actuators[MAX_ACTUATORS];
    uint8_t sensor_count;
    uint8_t actuator_count;
} edge_system_t;

/* =========================
 * Filter functions
 * ========================= */

static void filter_init(moving_avg_filter_t *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(moving_avg_filter_t *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
    }

    return (uint16_t)(f->sum / f->count);
}

/* =========================
 * Hardware abstraction stubs
 * Replace with platform-specific code
 * ========================= */

static uint16_t hal_read_sensor(uint8_t sensor_id) {
    /* Stubbed sensor values for demonstration */
    static uint16_t demo_values[MAX_SENSORS] = {2100, 2300, 2600, 2800};

    demo_values[sensor_id] += (sensor_id * 3 + 1);
    if (demo_values[sensor_id] > 3000) {
        demo_values[sensor_id] = 2000 + sensor_id * 100;
    }

    return demo_values[sensor_id];
}

static void hal_write_actuator(uint8_t actuator_id, actuator_state_t state) {
    /* Replace with GPIO/PWM/relay control */
    printf("Actuator %u -> %s\n",
           actuator_id,
           (state == ACTUATOR_ON) ? "ON" : "OFF");
}

/* =========================
 * Sensor processing
 * ========================= */

static bool sensor_validate(uint16_t raw) {
    return (raw >= SENSOR_MIN_VALID && raw <= SENSOR_MAX_VALID);
}

static void sensor_init(sensor_t *sensor, uint8_t id) {
    sensor->id = id;
    filter_init(&sensor->filter);
    sensor->output.raw = 0;
    sensor->output.filtered = 0;
    sensor->output.valid = false;
}

static void sensor_process(sensor_t *sensor) {
    uint16_t raw = hal_read_sensor(sensor->id);

    sensor->output.raw = raw;
    sensor->output.valid = sensor_validate(raw);

    if (sensor->output.valid) {
        sensor->output.filtered = filter_update(&sensor->filter, raw);
    }
}

/* =========================
 * Actuator logic
 * ========================= */

static void actuator_init(actuator_t *actuator, uint8_t id) {
    actuator->id = id;
    actuator->state = ACTUATOR_OFF;
    hal_write_actuator(id, actuator->state);
}

static void actuator_set(actuator_t *actuator, actuator_state_t new_state) {
    if (actuator->state != new_state) {
        actuator->state = new_state;
        hal_write_actuator(actuator->id, actuator->state);
    }
}

static void control_update(edge_system_t *sys) {
    uint8_t i;
    uint8_t count = (sys->sensor_count < sys->actuator_count)
                    ? sys->sensor_count
                    : sys->actuator_count;

    for (i = 0; i < count; i++) {
        sensor_output_t *s = &sys->sensors[i].output;
        actuator_t *a = &sys->actuators[i];

        if (!s->valid) {
            actuator_set(a, ACTUATOR_OFF);
            continue;
        }

        if (a->state == ACTUATOR_OFF && s->filtered >= ACTUATOR_ON_THRESH) {
            actuator_set(a, ACTUATOR_ON);
        } else if (a->state == ACTUATOR_ON && s->filtered <= ACTUATOR_OFF_THRESH) {
            actuator_set(a, ACTUATOR_OFF);
        }
    }
}

/* =========================
 * System initialization
 * ========================= */

static void edge_system_init(edge_system_t *sys,
                             uint8_t sensor_count,
                             uint8_t actuator_count) {
    uint8_t i;

    if (sensor_count > MAX_SENSORS) sensor_count = MAX_SENSORS;
    if (actuator_count > MAX_ACTUATORS) actuator_count = MAX_ACTUATORS;

    sys->sensor_count = sensor_count;
    sys->actuator_count = actuator_count;

    for (i = 0; i < sensor_count; i++) {
        sensor_init(&sys->sensors[i], i);
    }

    for (i = 0; i < actuator_count; i++) {
        actuator_init(&sys->actuators[i], i);
    }
}

/* =========================
 * Main processing tick
 * ========================= */

static void edge_system_tick(edge_system_t *sys) {
    uint8_t i;

    for (i = 0; i < sys->sensor_count; i++) {
        sensor_process(&sys->sensors[i]);
    }

    control_update(sys);
}

/* =========================
 * Debug/telemetry
 * ========================= */

static void edge_system_print(const edge_system_t *sys) {
    uint8_t i;
    for (i = 0; i < sys->sensor_count; i++) {
        const sensor_output_t *o = &sys->sensors[i].output;
        printf("Sensor %u: raw=%u filtered=%u valid=%u\n",
               i, o->raw, o->filtered, o->valid ? 1 : 0);
    }
}

/* =========================
 * Demo main
 * ========================= */

int main(void) {
    edge_system_t sys;
    uint8_t tick;

    edge_system_init(&sys, 4, 4);

    for (tick = 0; tick < 20; tick++) {
        printf("---- Tick %u ----\n", tick);
        edge_system_tick(&sys);
        edge_system_print(&sys);
    }

    return 0;
}
