```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */
#define FILTER_WINDOW_SIZE   8
#define SENSOR_MIN_VALID     0
#define SENSOR_MAX_VALID     4095
#define ACTUATOR_ON_THRESHOLD  2500
#define ACTUATOR_OFF_THRESHOLD 2200
#define FAULT_LIMIT          5

/* =========================
 * Types
 * ========================= */
typedef struct {
    int32_t buffer[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int32_t sum;
} MovingAverageFilter;

typedef struct {
    bool enabled;
    uint32_t on_count;
    uint32_t off_count;
} ActuatorState;

typedef struct {
    uint32_t invalid_sensor_count;
    bool sensor_fault;
} SystemFaults;

typedef struct {
    MovingAverageFilter filter;
    ActuatorState actuator;
    SystemFaults faults;
} EdgeSystem;

/* =========================
 * Filter functions
 * ========================= */
static void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static int32_t filter_update(MovingAverageFilter *f, int32_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;

    if (f->count == 0) {
        return 0;
    }

    return f->sum / f->count;
}

/* =========================
 * Sensor validation
 * ========================= */
static bool sensor_is_valid(int32_t raw_value) {
    return (raw_value >= SENSOR_MIN_VALID && raw_value <= SENSOR_MAX_VALID);
}

/* =========================
 * Actuator control
 * Hysteresis prevents chatter
 * ========================= */
static void actuator_set(ActuatorState *actuator, bool enable) {
    if (actuator->enabled != enable) {
        actuator->enabled = enable;
        if (enable) {
            actuator->on_count++;
            printf("ACTUATOR: ON\n");
        } else {
            actuator->off_count++;
            printf("ACTUATOR: OFF\n");
        }
    }
}

static void actuator_update(ActuatorState *actuator, int32_t filtered_value) {
    if (!actuator->enabled && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        actuator_set(actuator, true);
    } else if (actuator->enabled && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        actuator_set(actuator, false);
    }
}

/* =========================
 * Fault handling
 * ========================= */
static void faults_init(SystemFaults *faults) {
    faults->invalid_sensor_count = 0;
    faults->sensor_fault = false;
}

static void faults_update(SystemFaults *faults, bool valid_sample) {
    if (!valid_sample) {
        faults->invalid_sensor_count++;
        if (faults->invalid_sensor_count >= FAULT_LIMIT) {
            faults->sensor_fault = true;
        }
    } else {
        faults->invalid_sensor_count = 0;
        faults->sensor_fault = false;
    }
}

/* =========================
 * System functions
 * ========================= */
static void edge_system_init(EdgeSystem *sys) {
    filter_init(&sys->filter);

    sys->actuator.enabled = false;
    sys->actuator.on_count = 0;
    sys->actuator.off_count = 0;

    faults_init(&sys->faults);
}

static void edge_system_process_sample(EdgeSystem *sys, int32_t raw_sample) {
    bool valid = sensor_is_valid(raw_sample);
    faults_update(&sys->faults, valid);

    if (!valid) {
        printf("WARN: Invalid sensor sample: %ld\n", (long)raw_sample);

        if (sys->faults.sensor_fault) {
            actuator_set(&sys->actuator, false);
            printf("FAULT: Sensor fault detected, actuator forced OFF\n");
        }
        return;
    }

    int32_t filtered = filter_update(&sys->filter, raw_sample);
    printf("RAW=%ld FILTERED=%ld\n", (long)raw_sample, (long)filtered);

    if (!sys->faults.sensor_fault) {
        actuator_update(&sys->actuator, filtered);
    } else {
        actuator_set(&sys->actuator, false);
    }
}

/* =========================
 * Example sensor input
 * Replace with ADC read in real system
 * ========================= */
static int32_t mock_sensor_read(uint32_t tick) {
    static const int32_t samples[] = {
        1800, 1900, 2100, 2400, 2550, 2650, 2700, 2600,
        2300, 2100, 2050, 5000, -10, 2000, 2600, 2800
    };
    return samples[tick % (sizeof(samples) / sizeof(samples[0]))];
}

/* =========================
 * Main loop
 * ========================= */
int main(void) {
    EdgeSystem system;
    edge_system_init(&system);

    for (uint32_t tick = 0; tick < 32; tick++) {
        int32_t raw = mock_sensor_read(tick);
        edge_system_process_sample(&system, raw);
    }

    printf("\nSummary:\n");
    printf("Actuator enabled: %s\n", system.actuator.enabled ? "true" : "false");
    printf("Actuator ON transitions: %lu\n", (unsigned long)system.actuator.on_count);
    printf("Actuator OFF transitions: %lu\n", (unsigned long)system.actuator.off_count);
    printf("Sensor fault: %s\n", system.faults.sensor_fault ? "true" : "false");

    return 0;
}
