#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/*
 * Resource-constrained edge system:
 * - Filters sensor data using a fixed-size moving average
 * - Controls actuator with hysteresis
 * - No dynamic memory
 * - Constant-time updates
 */

/* =========================
 * Configuration
 * ========================= */
#define SENSOR_COUNT        2
#define FILTER_WINDOW       8
#define ACTUATOR_COUNT      2

/* Thresholds for each sensor */
static const int16_t sensor_on_threshold[SENSOR_COUNT]  = { 700, 500 };
static const int16_t sensor_off_threshold[SENSOR_COUNT] = { 650, 450 };

/* =========================
 * Data Structures
 * ========================= */

typedef struct {
    int16_t buffer[FILTER_WINDOW];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    int16_t raw_value;
    int16_t filtered_value;
    MovingAverageFilter filter;
} SensorChannel;

typedef struct {
    bool state;
} Actuator;

/* =========================
 * Global System State
 * ========================= */

static SensorChannel sensors[SENSOR_COUNT];
static Actuator actuators[ACTUATOR_COUNT];

/* =========================
 * Filter Functions
 * ========================= */

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    /* Remove oldest sample from sum */
    f->sum -= f->buffer[f->index];

    /* Store new sample */
    f->buffer[f->index] = sample;
    f->sum += sample;

    /* Advance circular buffer index */
    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
    }

    /* Track valid sample count during startup */
    if (f->count < FILTER_WINDOW) {
        f->count++;
    }

    return (int16_t)(f->sum / f->count);
}

/* =========================
 * Sensor Interface
 * Replace with ADC/I2C/SPI reads on target hardware
 * ========================= */

static int16_t read_sensor_hw(uint8_t sensor_id) {
    /* Stubbed sample data */
    static int16_t test_data[SENSOR_COUNT] = { 600, 400 };

    /* Simulate changing sensor values */
    test_data[sensor_id] += (sensor_id == 0) ? 15 : 8;

    return test_data[sensor_id];
}

/* =========================
 * Actuator Interface
 * Replace with GPIO/PWM/relay control on target hardware
 * ========================= */

static void write_actuator_hw(uint8_t actuator_id, bool state) {
    /* Stubbed output */
    printf("Actuator %u -> %s\n", actuator_id, state ? "ON" : "OFF");
}

/* =========================
 * Control Logic
 * ========================= */

static void update_actuator_from_sensor(uint8_t sensor_id, uint8_t actuator_id) {
    int16_t value = sensors[sensor_id].filtered_value;
    bool current_state = actuators[actuator_id].state;
    bool new_state = current_state;

    /* Hysteresis control */
    if (!current_state && value >= sensor_on_threshold[sensor_id]) {
        new_state = true;
    } else if (current_state && value <= sensor_off_threshold[sensor_id]) {
        new_state = false;
    }

    if (new_state != current_state) {
        actuators[actuator_id].state = new_state;
        write_actuator_hw(actuator_id, new_state);
    }
}

/* =========================
 * System Lifecycle
 * ========================= */

static void system_init(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensors[i].raw_value = 0;
        sensors[i].filtered_value = 0;
        filter_init(&sensors[i].filter);
    }

    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        actuators[i].state = false;
        write_actuator_hw(i, false);
    }
}

static void system_step(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensors[i].raw_value = read_sensor_hw(i);
        sensors[i].filtered_value = filter_update(&sensors[i].filter, sensors[i].raw_value);
    }

    /* Simple sensor-to-actuator mapping */
    update_actuator_from_sensor(0, 0);
    update_actuator_from_sensor(1, 1);
}

/* =========================
 * Main Loop
 * ========================= */

int main(void) {
    system_init();

    for (uint16_t tick = 0; tick < 20; tick++) {
        system_step();

        for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
            printf("Sensor %u raw=%d filtered=%d\n",
                   i,
                   sensors[i].raw_value,
                   sensors[i].filtered_value);
        }

        printf("---\n");
    }

    return 0;
}
