#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*
 * Resource-constrained edge system:
 * - Reads a small number of sensors
 * - Filters values using integer EMA
 * - Controls actuators with hysteresis
 * - Avoids dynamic memory allocation
 */

#define MAX_SENSORS    4
#define MAX_ACTUATORS  4

#define SENSOR_SCALE   100   // fixed-point scale: 25.34 => 2534
#define EMA_ALPHA_NUM  1     // alpha = 1/4
#define EMA_ALPHA_DEN  4

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} actuator_state_t;

typedef struct {
    uint8_t id;
    int32_t raw_value;       // scaled integer
    int32_t filtered_value;  // scaled integer
    bool initialized;
} sensor_t;

typedef struct {
    uint8_t id;
    actuator_state_t state;
    int32_t on_threshold;    // turn on if >= this
    int32_t off_threshold;   // turn off if <= this
} actuator_t;

typedef struct {
    sensor_t sensors[MAX_SENSORS];
    actuator_t actuators[MAX_ACTUATORS];
    uint8_t sensor_count;
    uint8_t actuator_count;
} edge_system_t;

/* ---------- Platform hooks (replace with hardware-specific code) ---------- */

static int32_t platform_read_sensor(uint8_t sensor_id) {
    /* Stub sensor values for demo */
    static int32_t demo_values[MAX_SENSORS] = {2200, 2450, 2600, 1800};

    /* Simulate slight variation */
    demo_values[sensor_id] += ((sensor_id % 2 == 0) ? 15 : -10);
    return demo_values[sensor_id];
}

static void platform_write_actuator(uint8_t actuator_id, actuator_state_t state) {
    /* Replace with GPIO/PWM/relay write */
    printf("Actuator %u -> %s\n", actuator_id, state == ACTUATOR_ON ? "ON" : "OFF");
}

static void platform_log_sensor(uint8_t sensor_id, int32_t raw, int32_t filtered) {
    printf("Sensor %u: raw=%ld filtered=%ld\n",
           sensor_id, (long)raw, (long)filtered);
}

/* ---------- Filter ---------- */

static int32_t ema_filter(int32_t previous, int32_t sample) {
    /* Integer EMA:
       y[n] = y[n-1] + alpha * (x[n] - y[n-1])
       alpha = 1/4
    */
    return previous + ((EMA_ALPHA_NUM * (sample - previous)) / EMA_ALPHA_DEN);
}

/* ---------- Initialization ---------- */

static void edge_system_init(edge_system_t *sys) {
    memset(sys, 0, sizeof(*sys));

    sys->sensor_count = 2;
    sys->actuator_count = 2;

    for (uint8_t i = 0; i < sys->sensor_count; i++) {
        sys->sensors[i].id = i;
        sys->sensors[i].raw_value = 0;
        sys->sensors[i].filtered_value = 0;
        sys->sensors[i].initialized = false;
    }

    /* Example:
       actuator 0 controlled by sensor 0
       actuator 1 controlled by sensor 1
       thresholds use hysteresis
    */
    sys->actuators[0].id = 0;
    sys->actuators[0].state = ACTUATOR_OFF;
    sys->actuators[0].on_threshold = 2500;   // 25.00
    sys->actuators[0].off_threshold = 2300;  // 23.00

    sys->actuators[1].id = 1;
    sys->actuators[1].state = ACTUATOR_OFF;
    sys->actuators[1].on_threshold = 2000;   // 20.00
    sys->actuators[1].off_threshold = 1800;  // 18.00
}

/* ---------- Sensor processing ---------- */

static void edge_system_update_sensors(edge_system_t *sys) {
    for (uint8_t i = 0; i < sys->sensor_count; i++) {
        sensor_t *s = &sys->sensors[i];
        s->raw_value = platform_read_sensor(s->id);

        if (!s->initialized) {
            s->filtered_value = s->raw_value;
            s->initialized = true;
        } else {
            s->filtered_value = ema_filter(s->filtered_value, s->raw_value);
        }

        platform_log_sensor(s->id, s->raw_value, s->filtered_value);
    }
}

/* ---------- Control logic ---------- */

static void edge_system_update_actuator_for_sensor(actuator_t *a, const sensor_t *s) {
    actuator_state_t new_state = a->state;

    if (a->state == ACTUATOR_OFF && s->filtered_value >= a->on_threshold) {
        new_state = ACTUATOR_ON;
    } else if (a->state == ACTUATOR_ON && s->filtered_value <= a->off_threshold) {
        new_state = ACTUATOR_OFF;
    }

    if (new_state != a->state) {
        a->state = new_state;
        platform_write_actuator(a->id, a->state);
    }
}

static void edge_system_control(edge_system_t *sys) {
    /* Simple 1:1 mapping actuator[i] <- sensor[i] */
    uint8_t count = (sys->sensor_count < sys->actuator_count)
                        ? sys->sensor_count
                        : sys->actuator_count;

    for (uint8_t i = 0; i < count; i++) {
        edge_system_update_actuator_for_sensor(&sys->actuators[i], &sys->sensors[i]);
    }
}

/* ---------- Main loop step ---------- */

static void edge_system_step(edge_system_t *sys) {
    edge_system_update_sensors(sys);
    edge_system_control(sys);
}

/* ---------- Demo main ---------- */

int main(void) {
    edge_system_t sys;
    edge_system_init(&sys);

    for (int i = 0; i < 10; i++) {
        printf("---- cycle %d ----\n", i);
        edge_system_step(&sys);
    }

    return 0;
}
