/*
 * edge_system.c
 *
 * Initial implementation of a resource-constrained edge system
 * that filters sensor data and manages actuators.
 *
 * Designed for small embedded targets:
 * - no dynamic memory
 * - lightweight filtering
 * - simple actuator control
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */

#define SENSOR_COUNT        3
#define ACTUATOR_COUNT      2

#define FILTER_ALPHA_NUM    1   /* EMA alpha = 1/4 */
#define FILTER_ALPHA_DEN    4

#define SENSOR_MIN_VALID    0
#define SENSOR_MAX_VALID    1023

#define TEMP_SENSOR_INDEX   0
#define HUM_SENSOR_INDEX    1
#define PRESS_SENSOR_INDEX  2

#define FAN_ACTUATOR_INDEX  0
#define PUMP_ACTUATOR_INDEX 1

/* Thresholds with hysteresis */
#define FAN_ON_THRESHOLD        700
#define FAN_OFF_THRESHOLD       650

#define PUMP_ON_THRESHOLD       300
#define PUMP_OFF_THRESHOLD      350

/* =========================
 * Types
 * ========================= */

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool valid;
} SensorData;

typedef struct {
    bool state;
} ActuatorState;

typedef struct {
    SensorData sensors[SENSOR_COUNT];
    ActuatorState actuators[ACTUATOR_COUNT];
} EdgeSystem;

/* =========================
 * Hardware abstraction layer
 * Replace these with platform-specific implementations
 * ========================= */

static uint16_t hal_read_sensor(uint8_t sensor_id) {
    /* Stub implementation for testing */
    static uint16_t fake_values[SENSOR_COUNT] = {680, 420, 900};

    /* Simulate slight variation */
    fake_values[sensor_id] += (sensor_id + 1);

    if (fake_values[sensor_id] > 1023) {
        fake_values[sensor_id] = 100;
    }

    return fake_values[sensor_id];
}

static void hal_set_actuator(uint8_t actuator_id, bool on) {
    /* Stub implementation for testing */
    printf("Actuator %u -> %s\n", actuator_id, on ? "ON" : "OFF");
}

/* =========================
 * Utility functions
 * ========================= */

static bool sensor_value_valid(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

/* Lightweight integer EMA:
 * filtered = filtered + alpha * (raw - filtered)
 * alpha = FILTER_ALPHA_NUM / FILTER_ALPHA_DEN
 */
static uint16_t apply_ema_filter(uint16_t previous, uint16_t current) {
    int32_t delta = (int32_t)current - (int32_t)previous;
    int32_t adjustment = (delta * FILTER_ALPHA_NUM) / FILTER_ALPHA_DEN;
    int32_t result = (int32_t)previous + adjustment;

    if (result < 0) {
        result = 0;
    } else if (result > 65535) {
        result = 65535;
    }

    return (uint16_t)result;
}

/* =========================
 * Core system functions
 * ========================= */

static void edge_system_init(EdgeSystem *sys) {
    uint8_t i;

    for (i = 0; i < SENSOR_COUNT; i++) {
        sys->sensors[i].raw = 0;
        sys->sensors[i].filtered = 0;
        sys->sensors[i].valid = false;
    }

    for (i = 0; i < ACTUATOR_COUNT; i++) {
        sys->actuators[i].state = false;
        hal_set_actuator(i, false);
    }
}

static void edge_system_read_sensors(EdgeSystem *sys) {
    uint8_t i;

    for (i = 0; i < SENSOR_COUNT; i++) {
        uint16_t raw = hal_read_sensor(i);

        sys->sensors[i].raw = raw;
        sys->sensors[i].valid = sensor_value_valid(raw);

        if (sys->sensors[i].valid) {
            if (sys->sensors[i].filtered == 0) {
                /* Initialize filter on first valid sample */
                sys->sensors[i].filtered = raw;
            } else {
                sys->sensors[i].filtered =
                    apply_ema_filter(sys->sensors[i].filtered, raw);
            }
        }
    }
}

static void edge_system_control_actuators(EdgeSystem *sys) {
    uint16_t temp_value = sys->sensors[TEMP_SENSOR_INDEX].filtered;
    uint16_t hum_value  = sys->sensors[HUM_SENSOR_INDEX].filtered;

    /* Fan control with hysteresis */
    if (sys->sensors[TEMP_SENSOR_INDEX].valid) {
        if (!sys->actuators[FAN_ACTUATOR_INDEX].state &&
            temp_value >= FAN_ON_THRESHOLD) {
            sys->actuators[FAN_ACTUATOR_INDEX].state = true;
            hal_set_actuator(FAN_ACTUATOR_INDEX, true);
        } else if (sys->actuators[FAN_ACTUATOR_INDEX].state &&
                   temp_value <= FAN_OFF_THRESHOLD) {
            sys->actuators[FAN_ACTUATOR_INDEX].state = false;
            hal_set_actuator(FAN_ACTUATOR_INDEX, false);
        }
    }

    /* Pump control with hysteresis */
    if (sys->sensors[HUM_SENSOR_INDEX].valid) {
        if (!sys->actuators[PUMP_ACTUATOR_INDEX].state &&
            hum_value <= PUMP_ON_THRESHOLD) {
            sys->actuators[PUMP_ACTUATOR_INDEX].state = true;
            hal_set_actuator(PUMP_ACTUATOR_INDEX, true);
        } else if (sys->actuators[PUMP_ACTUATOR_INDEX].state &&
                   hum_value >= PUMP_OFF_THRESHOLD) {
            sys->actuators[PUMP_ACTUATOR_INDEX].state = false;
            hal_set_actuator(PUMP_ACTUATOR_INDEX, false);
        }
    }
}

static void edge_system_log(const EdgeSystem *sys) {
    uint8_t i;

    printf("Sensors:\n");
    for (i = 0; i < SENSOR_COUNT; i++) {
        printf("  S%u raw=%u filtered=%u valid=%u\n",
               i,
               sys->sensors[i].raw,
               sys->sensors[i].filtered,
               sys->sensors[i].valid ? 1 : 0);
    }

    printf("Actuators:\n");
    for (i = 0; i < ACTUATOR_COUNT; i++) {
        printf("  A%u state=%s\n", i, sys->actuators[i].state ? "ON" : "OFF");
    }
}

static void edge_system_step(EdgeSystem *sys) {
    edge_system_read_sensors(sys);
    edge_system_control_actuators(sys);
    edge_system_log(sys);
}

/* =========================
 * Example main loop
 * ========================= */

