#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* =========================
 * Configuration
 * ========================= */
#define SENSOR_COUNT            3
#define FILTER_WINDOW           4
#define ACTUATOR_COUNT          2

#define TEMP_SENSOR_ID          0
#define HUM_SENSOR_ID           1
#define PRESS_SENSOR_ID         2

#define FAN_ACTUATOR_ID         0
#define VALVE_ACTUATOR_ID       1

#define TEMP_HIGH_THRESHOLD     30.0f
#define TEMP_LOW_THRESHOLD      28.0f

#define HUM_HIGH_THRESHOLD      70.0f
#define HUM_LOW_THRESHOLD       65.0f

#define SENSOR_INVALID_MIN     -1000.0f
#define SENSOR_INVALID_MAX      1000.0f

/* =========================
 * Types
 * ========================= */
typedef struct {
    float samples[FILTER_WINDOW];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter;

typedef struct {
    uint8_t id;
    float raw_value;
    float filtered_value;
    bool valid;
    MovingAverageFilter filter;
} Sensor;

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} ActuatorState;

typedef struct {
    uint8_t id;
    ActuatorState state;
} Actuator;

/* =========================
 * Global state
 * ========================= */
static Sensor sensors[SENSOR_COUNT];
static Actuator actuators[ACTUATOR_COUNT];

/* =========================
 * Filter functions
 * ========================= */
static void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0.0f;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0.0f;
    }
}

static float filter_update(MovingAverageFilter *f, float new_sample) {
    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return f->sum / (float)f->count;
}

/* =========================
 * Hardware abstraction stubs
 * Replace these with platform-specific code
 * ========================= */
static float read_sensor_hw(uint8_t sensor_id) {
    /* Stub values for demonstration */
    static float demo_values[SENSOR_COUNT] = {25.0f, 60.0f, 101.3f};

    /* Simulate changing temperature */
    if (sensor_id == TEMP_SENSOR_ID) {
        demo_values[sensor_id] += 0.8f;
        if (demo_values[sensor_id] > 35.0f) {
            demo_values[sensor_id] = 25.0f;
        }
    }

    /* Simulate changing humidity */
    if (sensor_id == HUM_SENSOR_ID) {
        demo_values[sensor_id] += 1.5f;
        if (demo_values[sensor_id] > 75.0f) {
            demo_values[sensor_id] = 60.0f;
        }
    }

    return demo_values[sensor_id];
}

static void write_actuator_hw(uint8_t actuator_id, ActuatorState state) {
    const char *state_str = (state == ACTUATOR_ON) ? "ON" : "OFF";
    printf("Actuator %u -> %s\n", actuator_id, state_str);
}

/* =========================
 * Sensor management
 * ========================= */
static bool validate_sensor_value(float value) {
    return (value > SENSOR_INVALID_MIN && value < SENSOR_INVALID_MAX);
}

static void sensor_init(Sensor *s, uint8_t id) {
    s->id = id;
    s->raw_value = 0.0f;
    s->filtered_value = 0.0f;
    s->valid = false;
    filter_init(&s->filter);
}

static void sensor_update(Sensor *s) {
    float raw = read_sensor_hw(s->id);
    s->raw_value = raw;
    s->valid = validate_sensor_value(raw);

    if (s->valid) {
        s->filtered_value = filter_update(&s->filter, raw);
    }
}

/* =========================
 * Actuator management
 * ========================= */
static void actuator_init(Actuator *a, uint8_t id) {
    a->id = id;
    a->state = ACTUATOR_OFF;
    write_actuator_hw(a->id, a->state);
}

static void actuator_set(Actuator *a, ActuatorState new_state) {
    if (a->state != new_state) {
        a->state = new_state;
        write_actuator_hw(a->id, a->state);
    }
}

/* =========================
 * Control logic
 * ========================= */
static void control_temperature(void) {
    Sensor *temp = &sensors[TEMP_SENSOR_ID];
    Actuator *fan = &actuators[FAN_ACTUATOR_ID];

    if (!temp->valid) {
        actuator_set(fan, ACTUATOR_OFF);
        return;
    }

    if (fan->state == ACTUATOR_OFF && temp->filtered_value >= TEMP_HIGH_THRESHOLD) {
        actuator_set(fan, ACTUATOR_ON);
    } else if (fan->state == ACTUATOR_ON && temp->filtered_value <= TEMP_LOW_THRESHOLD) {
        actuator_set(fan, ACTUATOR_OFF);
    }
}

static void control_humidity(void) {
    Sensor *hum = &sensors[HUM_SENSOR_ID];
    Actuator *valve = &actuators[VALVE_ACTUATOR_ID];

    if (!hum->valid) {
        actuator_set(valve, ACTUATOR_OFF);
        return;
    }

    if (valve->state == ACTUATOR_OFF && hum->filtered_value >= HUM_HIGH_THRESHOLD) {
        actuator_set(valve, ACTUATOR_ON);
    } else if (valve->state == ACTUATOR_ON && hum->filtered_value <= HUM_LOW_THRESHOLD) {
        actuator_set(valve, ACTUATOR_OFF);
    }
}

/* =========================
 * Diagnostics
 * ========================= */
static void print_status(void) {
    printf("Sensors:\n");
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        printf("  Sensor %u raw=%.2f filtered=%.2f valid=%d\n",
               sensors[i].id,
               sensors[i].raw_value,
               sensors[i].filtered_value,
               sensors[i].valid ? 1 : 0);
    }

    printf("Actuators:\n");
    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        printf("  Actuator %u state=%s\n",
               actuators[i].id,
               actuators[i].state == ACTUATOR_ON ? "ON" : "OFF");
    }
    printf("\n");
}

/* =========================
 * System init and loop
 * ========================= */
static void system_init(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensor_init(&sensors[i], i);
    }

    actuator_init(&actuators[FAN_ACTUATOR_ID], FAN_ACTUATOR_ID);
    actuator_init(&actuators[VALVE_ACTUATOR_ID], VALVE_ACTUATOR_ID);
}

static void system_step(void) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sensor_update(&sensors[i]);
    }

    control_temperature();
    control_humidity();
    print_status();
}

int main(void) {
    system_init();

    /* Simulated periodic loop */
    for (int i = 0; i < 20; i++) {
        system_step();
    }

    return 0;
}
