            f->samples[i] = new_sample;
            f->sum += new_sample;
        }
        f->initialized = true;
        return new_sample;
    }

    f->sum -= f->samples[f->index];
    f->samples[f->index] = new_sample;
    f->sum += new_sample;
    f->index = (f->index + 1) % FILTER_WINDOW;

    return (int16_t)(f->sum / FILTER_WINDOW);
}

