```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

/* =========================
 * Configuration
 * ========================= */

#define SENSOR_COUNT        3
#define ACTUATOR_COUNT      2
#define FILTER_WINDOW       4

#define SENSOR_MIN_VALID    0
#define SENSOR_MAX_VALID    1000

/* Example thresholds */
#define TEMP_ON_THRESHOLD   700
#define TEMP_OFF_THRESHOLD  650

#define HUM_ON_THRESHOLD    300
#define HUM_OFF_THRESHOLD   350

/* Sensor indices */
typedef enum {
    SENSOR_TEMP = 0,
    SENSOR_HUM  = 1,
    SENSOR_VIB  = 2
} SensorId;

/* Actuator indices */
typedef enum {
    ACTUATOR_FAN = 0,
    ACTUATOR_VALVE = 1
} ActuatorId;

/* =========================
 * Data Structures
 * ========================= */

typedef struct {
    int16_t samples[FILTER_WINDOW];
    int32_t sum;
    uint8_t index;
    uint8_t count;
    int16_t filtered;
    bool valid;
} FilterState;

typedef struct {
    int16_t raw;
    int16_t filtered;
    bool valid;
} SensorData;

typedef struct {
    bool state;
    bool fault;
} ActuatorState;

typedef struct {
    FilterState filters[SENSOR_COUNT];
    SensorData sensors[SENSOR_COUNT];
    ActuatorState actuators[ACTUATOR_COUNT];
} EdgeSystem;

/* =========================
 * Hardware Abstraction Layer
 * Replace these with platform-specific code
 * ========================= */

static int16_t hal_read_sensor(SensorId id) {
    /* Stubbed test values */
    static int tick = 0;
    tick++;

    switch (id) {
        case SENSOR_TEMP: return 600 + (tick % 200);
        case SENSOR_HUM:  return 400 - (tick % 150);
        case SENSOR_VIB:  return 100 + (tick % 50);
        default:          return -1;
    }
}

static void hal_write_actuator(ActuatorId id, bool on) {
    /* Replace with GPIO/PWM/fieldbus write */
    const char *name = (id == ACTUATOR_FAN) ? "FAN" : "VALVE";
    printf("Actuator %s -> %s\n", name, on ? "ON" : "OFF");
}

/* =========================
 * Filter Logic
 * ========================= */

static void filter_init(FilterState *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    f->filtered = 0;
    f->valid = false;

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static bool sensor_value_valid(int16_t value) {
    return (value >= SENSOR_MIN_VALID) && (value <= SENSOR_MAX_VALID);
}

static void filter_update(FilterState *f, int16_t sample, bool valid) {
    if (!valid) {
        f->valid = false;
        return;
    }

    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    f->filtered = (int16_t)(f->sum / f->count);
    f->valid = true;
}

/* =========================
 * System Logic
 * ========================= */

static void edge_system_init(EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        filter_init(&sys->filters[i]);
        sys->sensors[i].raw = 0;
        sys->sensors[i].filtered = 0;
        sys->sensors[i].valid = false;
    }

    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        sys->actuators[i].state = false;
        sys->actuators[i].fault = false;
    }
}

static void edge_system_read_sensors(EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        int16_t raw = hal_read_sensor((SensorId)i);
        bool valid = sensor_value_valid(raw);

        sys->sensors[i].raw = raw;
        sys->sensors[i].valid = valid;

        filter_update(&sys->filters[i], raw, valid);

        sys->sensors[i].filtered = sys->filters[i].filtered;
        sys->sensors[i].valid = sys->filters[i].valid;
    }
}

static void edge_system_control(EdgeSystem *sys) {
    /* FAN control based on temperature with hysteresis */
    if (sys->sensors[SENSOR_TEMP].valid) {
        int16_t t = sys->sensors[SENSOR_TEMP].filtered;

        if (!sys->actuators[ACTUATOR_FAN].state && t >= TEMP_ON_THRESHOLD) {
            sys->actuators[ACTUATOR_FAN].state = true;
        } else if (sys->actuators[ACTUATOR_FAN].state && t <= TEMP_OFF_THRESHOLD) {
            sys->actuators[ACTUATOR_FAN].state = false;
        }
    } else {
        /* Fail-safe */
        sys->actuators[ACTUATOR_FAN].state = false;
        sys->actuators[ACTUATOR_FAN].fault = true;
    }

    /* VALVE control based on humidity with inverse hysteresis */
    if (sys->sensors[SENSOR_HUM].valid) {
        int16_t h = sys->sensors[SENSOR_HUM].filtered;

        if (!sys->actuators[ACTUATOR_VALVE].state && h <= HUM_ON_THRESHOLD) {
            sys->actuators[ACTUATOR_VALVE].state = true;
        } else if (sys->actuators[ACTUATOR_VALVE].state && h >= HUM_OFF_THRESHOLD) {
            sys->actuators[ACTUATOR_VALVE].state = false;
        }
    } else {
        /* Fail-safe */
        sys->actuators[ACTUATOR_VALVE].state = false;
        sys->actuators[ACTUATOR_VALVE].fault = true;
    }
}

static void edge_system_apply_actuators(EdgeSystem *sys) {
    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        hal_write_actuator((ActuatorId)i, sys->actuators[i].state);
    }
}

static void edge_system_log(const EdgeSystem *sys) {
    printf("Sensors: ");
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        printf("[id=%u raw=%d filt=%d valid=%d] ",
               i,
               sys->sensors[i].raw,
               sys->sensors[i].filtered,
               sys->sensors[i].valid ? 1 : 0);
    }

    printf(" Actuators: ");
    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        printf("[id=%u state=%d fault=%d] ",
               i,
               sys->actuators[i].state ? 1 : 0,
               sys->actuators[i].fault ? 1 : 0);
    }
    printf("\n");
}

static void edge_system_step(EdgeSystem *sys) {
    edge_system_read_sensors(sys);
    edge_system_control(sys);
    edge_system_apply_actuators(sys);
    edge_system_log(sys);
}

/* =========================
 * Main
 * ========================= */

int main(void) {
    EdgeSystem sys;
    edge_system_init(&sys);

    for (int i = 0; i < 20; i++) {
        edge_system_step(&sys);
    }

    return 0;
}
