## 2. Initial implementation in C

```c
/*
 * edge_system.c
 *
 * Initial resource-constrained edge system:
 * - Filters sensor data using moving average
 * - Evaluates simple rules
 * - Manages actuators
 *
 * Intended as a portable starting point for:
 * - embedded Linux
 * - RTOS task loop
 * - bare-metal adaptation
 */

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* =========================
 * Configuration
 * ========================= */

#define MAX_SENSORS            8
#define MAX_ACTUATORS          8
#define FILTER_WINDOW_SIZE     4
#define SENSOR_STALE_TICKS     10

/* Simulated system tick period:
 * one loop iteration == one tick
 */

typedef enum {
    SENSOR_OK = 0,
    SENSOR_INVALID,
    SENSOR_STALE
} SensorStatus;

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} ActuatorState;

typedef enum {
    RULE_NONE = 0,
    RULE_ON_ABOVE_MAX,
    RULE_ON_BELOW_MIN,
    RULE_ON_OUTSIDE_RANGE
} RuleType;

/* =========================
 * Sensor structures
 * ========================= */

typedef struct {
    float samples[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter;

typedef struct {
    uint8_t id;
    const char *name;

    float raw_value;
    float filtered_value;

    float min_valid;
    float max_valid;

    float threshold_min;
    float threshold_max;

    uint32_t last_update_tick;
    SensorStatus status;

    MovingAverageFilter filter;
} Sensor;

typedef struct {
    uint8_t id;
    const char *name;

    ActuatorState state;

    uint8_t sensor_id;
    RuleType rule;
} Actuator;

/* =========================
 * Global system state
 * ========================= */

typedef struct {
    Sensor sensors[MAX_SENSORS];
    Actuator actuators[MAX_ACTUATORS];
    uint8_t sensor_count;
    uint8_t actuator_count;
    uint32_t tick;
} EdgeSystem;

/* =========================
 * Filter functions
 * ========================= */

static void filter_init(MovingAverageFilter *f) {
    memset(f->samples, 0, sizeof(f->samples));
    f->index = 0;
    f->count = 0;
    f->sum = 0.0f;
}

static float filter_update(MovingAverageFilter *f, float sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index = (uint8_t)((f->index + 1) % FILTER_WINDOW_SIZE);
    return f->sum / (float)f->count;
}

/* =========================
 * Utility functions
 * ========================= */

static Sensor* get_sensor_by_id(EdgeSystem *sys, uint8_t id) {
    for (uint8_t i = 0; i < sys->sensor_count; i++) {
        if (sys->sensors[i].id == id) {
            return &sys->sensors[i];
        }
    }
    return NULL;
}

static const char* sensor_status_str(SensorStatus s) {
    switch (s) {
        case SENSOR_OK: return "OK";
        case SENSOR_INVALID: return "INVALID";
        case SENSOR_STALE: return "STALE";
        default: return "UNKNOWN";
    }
}

static const char* actuator_state_str(ActuatorState s) {
    return (s == ACTUATOR_ON) ? "ON" : "OFF";
}

/* =========================
 * System initialization
 * ========================= */

static void edge_system_init(EdgeSystem *sys) {
    memset(sys, 0, sizeof(*sys));
}

static bool edge_add_sensor(
    EdgeSystem *sys,
    uint8_t id,
    const char *name,
    float min_valid,
    float max_valid,
    float threshold_min,
    float threshold_max
) {
    if (sys->sensor_count >= MAX_SENSORS) {
        return false;
    }

    Sensor *s = &sys->sensors[sys->sensor_count++];
    s->id = id;
    s->name = name;
    s->raw_value = 0.0f;
    s->filtered_value = 0.0f;
    s->min_valid = min_valid;
    s->max_valid = max_valid;
    s->threshold_min = threshold_min;
    s->threshold_max = threshold_max;
    s->last_update_tick = 0;
    s->status = SENSOR_STALE;
    filter_init(&s->filter);

    return true;
}

static bool edge_add_actuator(
    EdgeSystem *sys,
    uint8_t id,
    const char *name,
    uint8_t sensor_id,
    RuleType rule
) {
    if (sys->actuator_count >= MAX_ACTUATORS) {
        return false;
    }

    Actuator *a = &sys->actuators[sys->actuator_count++];
    a->id = id;
    a->name = name;
    a->state = ACTUATOR_OFF;
    a->sensor_id = sensor_id;
    a->rule = rule;

    return true;
}

/* =========================
 * Sensor ingestion
 * ========================= */

static bool edge_update_sensor(EdgeSystem *sys, uint8_t sensor_id, float value) {
    Sensor *s = get_sensor_by_id(sys, sensor_id);
    if (s == NULL) {
        return false;
    }

    s->raw_value = value;
    s->last_update_tick = sys->tick;

    if (value < s->min_valid || value > s->max_valid) {
        s->status = SENSOR_INVALID;
        return true;
    }

    s->filtered_value = filter_update(&s->filter, value);
    s->status = SENSOR_OK;
    return true;
}

/* =========================
 * Health monitoring
 * ========================= */

static void edge_check_sensor_health(EdgeSystem *sys) {
    for (uint8_t i = 0; i < sys->sensor_count; i++) {
        Sensor *s = &sys->sensors[i];

        if ((sys->tick - s->last_update_tick) > SENSOR_STALE_TICKS) {
            s->status = SENSOR_STALE;
        }
    }
}

/* =========================
 * Rule evaluation
 * ========================= */

static bool edge_rule_triggered(const Sensor *s, RuleType rule) {
    if (s->status != SENSOR_OK) {
        return false;
    }

    switch (rule) {
        case RULE_ON_ABOVE_MAX:
            return s->filtered_value > s->threshold_max;

        case RULE_ON_BELOW_MIN:
            return s->filtered_value < s->threshold_min;

        case RULE_ON_OUTSIDE_RANGE:
            return (s->filtered_value < s->threshold_min ||
                    s->filtered_value > s->threshold_max);

        case RULE_NONE:
        default:
            return false;
    }
}

/* =========================
 * Actuator output hook
 * ========================= */

static void hardware_set_actuator(uint8_t actuator_id, ActuatorState state) {
    /* Replace this with GPIO, PWM, relay, fieldbus, etc. */
    printf("[HW] Actuator %u -> %s\n", actuator_id, actuator_state_str(state));
}

/* =========================
 * Actuator management
 * ========================= */

static void edge_update_actuators(EdgeSystem *sys) {
    for (uint8_t i = 0; i < sys->actuator_count; i++) {
        Actuator *a = &sys->actuators[i];
        Sensor *s = get_sensor_by_id(sys, a->sensor_id);

        ActuatorState desired = ACTUATOR_OFF;

        if (s != NULL && edge_rule_triggered(s, a->rule)) {
            desired = ACTUATOR_ON;
        }

        if (desired != a->state) {
            a->state = desired;
            hardware_set_actuator(a->id, a->state);
        }
    }
}

/* =========================
 * Debug/status reporting
 * ========================= */

static void edge_print_status(const EdgeSystem *sys) {
    printf("\n[TICK %u]\n", sys->tick);

    printf("Sensors:\n");
    for (uint8_t i = 0; i < sys->sensor_count; i++) {
        const Sensor *s = &sys->sensors[i];
        printf("  [%u] %s raw=%.2f filt=%.2f status=%s\n",
               s->id, s->name, s->raw_value, s->filtered_value,
               sensor_status_str(s->status));
    }

    printf("Actuators:\n");
    for (uint8_t i = 0; i < sys->actuator_count; i++) {
        const Actuator *a = &sys->actuators[i];
        printf("  [%u] %s state=%s (sensor=%u)\n",
               a->id, a->name, actuator_state_str(a->state), a->sensor_id);
    }
}

/* =========================
 * Main processing step
 * ========================= */

static void edge_process(EdgeSystem *sys) {
    edge_check_sensor_health(sys);
    edge_update_actuators(sys);
}

/* =========================
 * Demo main
 * ========================= */

int main(void) {
    EdgeSystem sys;
    edge_system_init(&sys);

    /* Sensors:
     * id, name, min_valid, max_valid, threshold_min, threshold_max
     */
    edge_add_sensor(&sys, 1, "temperature", -40.0f, 125.0f, 0.0f, 30.0f);
    edge_add_sensor(&sys, 2, "light",        0.0f, 1000.0f, 200.0f, 800.0f);
    edge_add_sensor(&sys, 3, "pressure",     0.0f, 10.0f,   2.0f,  8.0f);

    /* Actuators:
     * id, name, sensor_id, rule
     */
    edge_add_actuator(&sys, 1, "fan",   1, RULE_ON_ABOVE_MAX);
    edge_add_actuator(&sys, 2, "lamp",  2, RULE_ON_BELOW_MIN);
    edge_add_actuator(&sys, 3, "alarm", 3, RULE_ON_OUTSIDE_RANGE);

    /* Simulated loop */
    for (sys.tick = 1; sys.tick <= 20; sys.tick++) {
        /* Simulated sensor updates */
        switch (sys.tick) {
            case 1:
                edge_update_sensor(&sys, 1, 25.0f);
                edge_update_sensor(&sys, 2, 150.0f);
                edge_update_sensor(&sys, 3, 5.0f);
                break;
            case 2:
                edge_update_sensor(&sys, 1, 28.0f);
                edge_update_sensor(&sys, 2, 180.0f);
                edge_update_sensor(&sys, 3, 5.5f);
                break;
            case 3:
                edge_update_sensor(&sys, 1, 31.0f);
                edge_update_sensor(&sys, 2, 220.0f);
                edge_update_sensor(&sys, 3, 8.5f);
                break;
            case 4:
                edge_update_sensor(&sys, 1, 35.0f);
                edge_update_sensor(&sys, 2, 250.0f);
                edge_update_sensor(&sys, 3, 9.0f);
                break;
            case 5:
                edge_update_sensor(&sys, 1, 36.0f);
                edge_update_sensor(&sys, 2, 300.0f);
                edge_update_sensor(&sys, 3, 11.0f); /* invalid */
                break;
            case 12:
                edge_update_sensor(&sys, 1, 26.0f);
                edge_update_sensor(&sys, 2, 100.0f);
                edge_update_sensor(&sys, 3, 4.0f);
                break;
            default:
                break;
        }

        edge_process(&sys);
        edge_print_status(&sys);
    }

    return 0;
}
