```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/*
 * Resource-constrained edge system:
 * - fixed-size buffers
 * - no malloc
 * - simple moving average filter
 * - hysteresis-based actuator control
 * - mock sensor/actuator interfaces for initial implementation
 */

#define MAX_SENSORS 4
#define FILTER_WINDOW 4

typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON  = 1
} actuator_state_t;

typedef struct {
    const char *name;
    int32_t raw_value;
    int32_t filtered_value;

    int32_t filter_buffer[FILTER_WINDOW];
    uint8_t filter_index;
    uint8_t filter_count;
    int32_t filter_sum;
} sensor_t;

typedef struct {
    const char *name;
    actuator_state_t state;
} actuator_t;

typedef struct {
    int32_t on_threshold;
    int32_t off_threshold;
} control_rule_t;

typedef struct {
    sensor_t sensors[MAX_SENSORS];
    uint8_t sensor_count;

    actuator_t fan;
    control_rule_t temp_rule;

    uint32_t tick;
} edge_system_t;

/* ---------------- Sensor Interface ---------------- */

/* Mock sensor read: replace with ADC/I2C/SPI/GPIO read */
static int32_t read_sensor_mock(uint32_t tick, const char *name) {
    (void)name;

    /* Synthetic temperature-like waveform */
    static const int32_t samples[] = {
        28, 29, 30, 31, 35, 38, 40, 42, 39, 36, 33, 30, 29, 28
    };
    return samples[tick % (sizeof(samples) / sizeof(samples[0]))];
}

/* ---------------- Filter ---------------- */

static void sensor_filter_init(sensor_t *s, const char *name) {
    memset(s, 0, sizeof(*s));
    s->name = name;
}

static int32_t sensor_filter_update(sensor_t *s, int32_t new_value) {
    s->raw_value = new_value;

    if (s->filter_count < FILTER_WINDOW) {
        s->filter_buffer[s->filter_index] = new_value;
        s->filter_sum += new_value;
        s->filter_count++;
    } else {
        s->filter_sum -= s->filter_buffer[s->filter_index];
        s->filter_buffer[s->filter_index] = new_value;
        s->filter_sum += new_value;
    }

    s->filter_index = (s->filter_index + 1) % FILTER_WINDOW;
    s->filtered_value = s->filter_sum / s->filter_count;

    return s->filtered_value;
}

/* ---------------- Actuator Interface ---------------- */

/* Mock actuator write: replace with GPIO/PWM/relay write */
static void actuator_apply(actuator_t *a, actuator_state_t new_state) {
    if (a->state != new_state) {
        a->state = new_state;
        printf("[ACTUATOR] %s -> %s\n",
               a->name,
               (new_state == ACTUATOR_ON) ? "ON" : "OFF");
    }
}

/* ---------------- Control Logic ---------------- */

static void control_temperature(sensor_t *temp_sensor,
                                actuator_t *fan,
                                const control_rule_t *rule) {
    int32_t temp = temp_sensor->filtered_value;

    if (fan->state == ACTUATOR_OFF && temp >= rule->on_threshold) {
        actuator_apply(fan, ACTUATOR_ON);
    } else if (fan->state == ACTUATOR_ON && temp <= rule->off_threshold) {
        actuator_apply(fan, ACTUATOR_OFF);
    }
}

/* ---------------- System ---------------- */

static void edge_system_init(edge_system_t *sys) {
    memset(sys, 0, sizeof(*sys));

    sys->sensor_count = 1;
    sensor_filter_init(&sys->sensors[0], "temperature");

    sys->fan.name = "cooling_fan";
    sys->fan.state = ACTUATOR_OFF;

    sys->temp_rule.on_threshold = 37;
    sys->temp_rule.off_threshold = 34;
}

static void edge_system_step(edge_system_t *sys) {
    sensor_t *temp = &sys->sensors[0];

    int32_t raw = read_sensor_mock(sys->tick, temp->name);
    int32_t filtered = sensor_filter_update(temp, raw);

    printf("[TICK %u] sensor=%s raw=%ld filtered=%ld fan=%s\n",
           sys->tick,
           temp->name,
           (long)raw,
           (long)filtered,
           (sys->fan.state == ACTUATOR_ON) ? "ON" : "OFF");

    control_temperature(temp, &sys->fan, &sys->temp_rule);

    sys->tick++;
}

int main(void) {
    edge_system_t sys;
    edge_system_init(&sys);

    for (int i = 0; i < 20; i++) {
        edge_system_step(&sys);
    }

    return 0;
}
