    demo_values[sensor_id] += (sensor_id == 0) ? 15 : -10;

    if (demo_values[sensor_id] > 900) demo_values[sensor_id] = 900;
    if (demo_values[sensor_id] < 100) demo_values[sensor_id] = 100;

    return demo_values[sensor_id];
}

