}

static void platform_log(const char *msg) {
    printf("%s\n", msg);
}

/* =========================
 * Filter Functions
 * ========================= */

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;

    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->samples[i] = 0;
    }
}

static int32_t filter_update(MovingAverageFilter *f, int32_t sample) {
    if (f->count < FILTER_WINDOW_SIZE) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index = (uint8_t)((f->index + 1) % FILTER_WINDOW_SIZE);

    return f->sum / f->count;
}

/* =========================
 * Validation
 * ========================= */

static bool sensor_value_valid(int32_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

/* =========================
 * System Initialization
 * ========================= */

static void edge_system_init(EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        sys->sensors[i].valid = false;
        sys->sensors[i].raw_value = 0;
        sys->sensors[i].filtered_value = 0;
        filter_init(&sys->sensors[i].filter);
    }

    for (uint8_t i = 0; i < ACTUATOR_COUNT; i++) {
        sys->actuators[i].state = ACTUATOR_OFF;
        platform_set_actuator(i, ACTUATOR_OFF);
    }

    /* Example threshold configuration */
    sys->thresholds[0].on_threshold = 600;
    sys->thresholds[0].off_threshold = 500;

    sys->thresholds[1].on_threshold = 650;
    sys->thresholds[1].off_threshold = 550;
}

/* =========================
 * Sensor Processing
 * ========================= */

static void edge_system_read_and_filter(EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        int32_t raw = platform_read_sensor(i);
        sys->sensors[i].raw_value = raw;

        if (!sensor_value_valid(raw)) {
            sys->sensors[i].valid = false;
            platform_log("Invalid sensor reading");
            continue;
        }

        sys->sensors[i].valid = true;
        sys->sensors[i].filtered_value = filter_update(&sys->sensors[i].filter, raw);
    }
}

/* =========================
 * Actuator Control
 * One actuator per sensor in this simple version
 * ========================= */

static void edge_system_update_actuators(EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT && i < ACTUATOR_COUNT; i++) {
        if (!sys->sensors[i].valid) {
            /* Fail-safe behavior: turn actuator off on invalid input */
            if (sys->actuators[i].state != ACTUATOR_OFF) {
                sys->actuators[i].state = ACTUATOR_OFF;
                platform_set_actuator(i, ACTUATOR_OFF);
            }
            continue;
        }

        int32_t value = sys->sensors[i].filtered_value;
        ThresholdConfig *cfg = &sys->thresholds[i];
        ActuatorState current = sys->actuators[i].state;
        ActuatorState next = current;

        if (current == ACTUATOR_OFF && value >= cfg->on_threshold) {
            next = ACTUATOR_ON;
        } else if (current == ACTUATOR_ON && value <= cfg->off_threshold) {
            next = ACTUATOR_OFF;
        }

        if (next != current) {
            sys->actuators[i].state = next;
            platform_set_actuator(i, next);
        }
    }
}

/* =========================
 * Diagnostics
 * ========================= */

static void edge_system_print_status(const EdgeSystem *sys) {
    for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
        printf("Sensor %u: valid=%d raw=%ld filtered=%ld | Actuator=%s\n",
               i,
               sys->sensors[i].valid ? 1 : 0,
               (long)sys->sensors[i].raw_value,
               (long)sys->sensors[i].filtered_value,
               sys->actuators[i].state == ACTUATOR_ON ? "ON" : "OFF");
    }
}

/* =========================
 * Main Loop
 * ========================= */

int main(void) {
    EdgeSystem system;
    edge_system_init(&system);

    while (1) {
        edge_system_read_and_filter(&system);
        edge_system_update_actuators(&system);
        edge_system_print_status(&system);
        platform_delay_ms(LOOP_DELAY_MS);
    }

    return 0;
}
