#include <stdint.h>
#include <stdbool.h>

#define SENSOR_COUNT 3
#define FILTER_WINDOW 4

typedef struct {
    int16_t raw_history[FILTER_WINDOW];
    uint8_t index;
    int32_t sum;
    int16_t filtered;
} SensorFilter;

typedef struct {
    int16_t on_threshold;
    int16_t off_threshold;
    bool actuator_state;
} ControlRule;

typedef struct {
    SensorFilter filter;
    ControlRule rule;
    int16_t latest_raw;
} SensorChannel;

/* ---------- Mock hardware layer ---------- */

static int16_t mock_read_sensor(uint8_t sensor_id) {
    static int16_t test_data[SENSOR_COUNT][8] = {
        {20, 22, 25, 30, 35, 40, 38, 32},
        {50, 49, 48, 52, 55, 60, 58, 54},
        {10, 12, 11, 15, 18, 21, 19, 16}
    };
    static uint8_t sample_index[SENSOR_COUNT] = {0};

    int16_t value = test_data[sensor_id][sample_index[sensor_id]];
    sample_index[sensor_id] = (sample_index[sensor_id] + 1) % 8;
    return value;
}

static void mock_set_actuator(uint8_t actuator_id, bool state) {
    printf("Actuator %u -> %s\n", actuator_id, state ? "ON" : "OFF");
}

/* ---------- Filter logic ---------- */

static void filter_init(SensorFilter *f) {
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->raw_history[i] = 0;
    }
    f->index = 0;
    f->sum = 0;
    f->filtered = 0;
}

static int16_t filter_update(SensorFilter *f, int16_t sample) {
    f->sum -= f->raw_history[f->index];
    f->raw_history[f->index] = sample;
    f->sum += sample;

    f->index = (f->index + 1) % FILTER_WINDOW;
    f->filtered = (int16_t)(f->sum / FILTER_WINDOW);

    return f->filtered;
}

/* ---------- Control logic ---------- */

static bool control_update(ControlRule *rule, int16_t filtered_value) {
    bool previous = rule->actuator_state;

    if (!rule->actuator_state && filtered_value >= rule->on_threshold) {
        rule->actuator_state = true;
    } else if (rule->actuator_state && filtered_value <= rule->off_threshold) {
        rule->actuator_state = false;
    }

    return previous != rule->actuator_state;
}

/* ---------- System setup ---------- */

static void sensor_channel_init(SensorChannel *ch, int16_t on_th, int16_t off_th) {
    filter_init(&ch->filter);
    ch->rule.on_threshold = on_th;
    ch->rule.off_threshold = off_th;
    ch->rule.actuator_state = false;
    ch->latest_raw = 0;
}

/* ---------- Main processing ---------- */

static void process_channel(SensorChannel *ch, uint8_t id) {
    ch->latest_raw = mock_read_sensor(id);
    int16_t filtered = filter_update(&ch->filter, ch->latest_raw);

    bool changed = control_update(&ch->rule, filtered);
    if (changed) {
        mock_set_actuator(id, ch->rule.actuator_state);
    }

    printf("Sensor %u: raw=%d filtered=%d actuator=%s\n",
           id,
           ch->latest_raw,
           filtered,
           ch->rule.actuator_state ? "ON" : "OFF");
}

int main(void) {
    SensorChannel channels[SENSOR_COUNT];

    sensor_channel_init(&channels[0], 30, 25);
    sensor_channel_init(&channels[1], 55, 50);
    sensor_channel_init(&channels[2], 18, 14);

    for (uint8_t cycle = 0; cycle < 8; cycle++) {
        printf("Cycle %u\n", cycle);
        for (uint8_t i = 0; i < SENSOR_COUNT; i++) {
            process_channel(&channels[i], i);
        }
        printf("\n");
    }

    return 0;
}
