    fake_values[sensor_id] += (sensor_id + 1) * 7;
    if (fake_values[sensor_id] > SENSOR_MAX) {
        fake_values[sensor_id] = SENSOR_MIN + (sensor_id * 100);
    }

    return fake_values[sensor_id];
}

