/* =========================
 * Filter functions
 * ========================= */
static void filter_init(MovingAverageFilter *filter) {
    filter->sum = 0;
    filter->index = 0;
    filter->initialized = false;

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        filter->samples[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *filter, uint16_t new_sample) {
    if (!filter->initialized) {
        for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
            filter->samples[i] = new_sample;
            filter->sum += new_sample;
        }
        filter->initialized = true;
        return new_sample;
    }

    filter->sum -= filter->samples[filter->index];
    filter->samples[filter->index] = new_sample;
    filter->sum += new_sample;

    filter->index++;
    if (filter->index >= FILTER_WINDOW) {
        filter->index = 0;
    }

    return (uint16_t)(filter->sum / FILTER_WINDOW);
}

