    uint16_t temp = state->sensors[TEMP_SENSOR_IDX].filtered;
    uint16_t pressure = state->sensors[PRESS_SENSOR_IDX].filtered;
    uint16_t motion = state->sensors[MOTION_SENSOR_IDX].filtered;

    /* Cooling fan control */
    if (!state->actuators.cooling_fan_on && temp >= TEMP_HIGH_THRESHOLD) {
        state->actuators.cooling_fan_on = true;
    } else if (state->actuators.cooling_fan_on && temp <= TEMP_LOW_THRESHOLD) {
        state->actuators.cooling_fan_on = false;
    }

    /* Pressure valve control */
    if (!state->actuators.pressure_valve_open && pressure >= PRESS_HIGH_THRESHOLD) {
        state->actuators.pressure_valve_open = true;
    } else if (state->actuators.pressure_valve_open && pressure <= PRESS_LOW_THRESHOLD) {
        state->actuators.pressure_valve_open = false;
    }

    /* Alarm based on motion + high temperature */
    if (motion >= MOTION_ON_THRESHOLD && temp >= TEMP_HIGH_THRESHOLD) {
        state->actuators.alarm_on = true;
    } else if (motion <= MOTION_OFF_THRESHOLD || temp <= TEMP_LOW_THRESHOLD) {
        state->actuators.alarm_on = false;
    }
}

/* =========================
 * Actuator output
 * ========================= */
static void apply_actuators(const EdgeSystemState *state) {
    static ActuatorState last_state = {false, false, false};

    if (state->actuators.cooling_fan_on != last_state.cooling_fan_on) {
        hal_set_cooling_fan(state->actuators.cooling_fan_on);
        last_state.cooling_fan_on = state->actuators.cooling_fan_on;
    }

    if (state->actuators.pressure_valve_open != last_state.pressure_valve_open) {
        hal_set_pressure_valve(state->actuators.pressure_valve_open);
        last_state.pressure_valve_open = state->actuators.pressure_valve_open;
    }

    if (state->actuators.alarm_on != last_state.alarm_on) {
        hal_set_alarm(state->actuators.alarm_on);
        last_state.alarm_on = state->actuators.alarm_on;
    }
}

/* =========================
 * Diagnostics
 * ========================= */
static void print_status(const EdgeSystemState *state) {
    printf("Sensors: "
           "Temp raw=%u filt=%u, "
           "Pressure raw=%u filt=%u, "
           "Motion raw=%u filt=%u\n",
           state->sensors[TEMP_SENSOR_IDX].raw,
           state->sensors[TEMP_SENSOR_IDX].filtered,
           state->sensors[PRESS_SENSOR_IDX].raw,
           state->sensors[PRESS_SENSOR_IDX].filtered,
           state->sensors[MOTION_SENSOR_IDX].raw,
           state->sensors[MOTION_SENSOR_IDX].filtered);

    printf("Actuators: fan=%d valve=%d alarm=%d\n",
           state->actuators.cooling_fan_on,
           state->actuators.pressure_valve_open,
           state->actuators.alarm_on);
}

/* =========================
 * System init
 * ========================= */
static void edge_system_init(EdgeSystemState *state) {
    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        state->sensors[i].raw = 0;
        state->sensors[i].filtered = 0;
        filter_init(&state->filters[i]);
    }

    state->actuators.cooling_fan_on = false;
    state->actuators.pressure_valve_open = false;
    state->actuators.alarm_on = false;
}

/* =========================
 * Main loop
 * ========================= */
int main(void) {
    EdgeSystemState system_state;
    edge_system_init(&system_state);

    /* Simulated periodic loop */
    for (uint32_t tick = 0; tick < 20; tick++) {
        read_and_filter_sensors(&system_state);
        update_control_logic(&system_state);
        apply_actuators(&system_state);
        print_status(&system_state);

        /* On real hardware:
         * - sleep until timer interrupt
         * - or delay_ms(loop_period)
         */
        printf("----\n");
    }

    return 0;
}
```

