## 2. Minimal working C example

```c
#include <stdio.h>
#include <stdint.h>

#define FILTER_WINDOW 4
#define TEMP_THRESHOLD 30.0f
#define VIB_THRESHOLD  70.0f

typedef struct {
    float buffer[FILTER_WINDOW];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter;

typedef struct {
    uint8_t fan_on;
    uint8_t alarm_on;
} ActuatorState;

/* ---------- Filter ---------- */

void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0.0f;
    for (int i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0.0f;
    }
}

float filter_update(MovingAverageFilter *f, float sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return f->sum / f->count;
}

/* ---------- Simulated sensors ---------- */

float read_temperature_sensor(int tick) {
    /* Simulated temperature profile */
    float samples[] = {25.0f, 26.5f, 28.0f, 31.0f, 33.0f, 29.0f, 27.0f, 26.0f};
    return samples[tick % 8];
}

float read_vibration_sensor(int tick) {
    /* Simulated vibration profile */
    float samples[] = {40.0f, 45.0f, 50.0f, 80.0f, 75.0f, 60.0f, 55.0f, 50.0f};
    return samples[tick % 8];
}

/* ---------- Actuator control ---------- */

void set_fan(uint8_t on, ActuatorState *state) {
    if (state->fan_on != on) {
        state->fan_on = on;
        printf("ACTUATOR: Fan %s\n", on ? "ON" : "OFF");
    }
}

void set_alarm(uint8_t on, ActuatorState *state) {
    if (state->alarm_on != on) {
        state->alarm_on = on;
        printf("ACTUATOR: Alarm %s\n", on ? "ON" : "OFF");
    }
}

/* ---------- Decision logic ---------- */

void process_control(float temp_filtered, float vib_filtered, ActuatorState *state) {
    if (temp_filtered > TEMP_THRESHOLD) {
        set_fan(1, state);
    } else {
        set_fan(0, state);
    }

    if (vib_filtered > VIB_THRESHOLD) {
        set_alarm(1, state);
    } else {
        set_alarm(0, state);
    }
}

/* ---------- Main loop ---------- */

int main(void) {
    MovingAverageFilter temp_filter;
    MovingAverageFilter vib_filter;
    ActuatorState actuators = {0, 0};

    filter_init(&temp_filter);
    filter_init(&vib_filter);

    for (int tick = 0; tick < 16; tick++) {
        float temp_raw = read_temperature_sensor(tick);
        float vib_raw = read_vibration_sensor(tick);

        float temp_filtered = filter_update(&temp_filter, temp_raw);
        float vib_filtered = filter_update(&vib_filter, vib_raw);

        printf("Tick %2d | Temp raw: %5.1f, filtered: %5.2f | Vib raw: %5.1f, filtered: %5.2f\n",
               tick, temp_raw, temp_filtered, vib_raw, vib_filtered);

        process_control(temp_filtered, vib_filtered, &actuators);
    }

    return 0;
}
