#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/*
 * Minimal resource-constrained edge system
 * - Simulated sensors
 * - Lightweight filtering
 * - Threshold-based actuator control
 * - No dynamic memory
 */

/* ---------------- Configuration ---------------- */

#define TEMP_THRESHOLD_ON     30.0f
#define TEMP_THRESHOLD_OFF    28.0f

#define VIB_THRESHOLD_ON      5.0f
#define VIB_THRESHOLD_OFF     4.0f

/* EMA alpha in fixed-point-ish float form for simplicity */
#define TEMP_ALPHA            0.2f
#define VIB_ALPHA             0.3f

#define LOOP_ITERATIONS       20

/* ---------------- Data Types ---------------- */

typedef struct {
    float temperature;
    float vibration;
} SensorData;

typedef struct {
    float temperature_filtered;
    float vibration_filtered;
    bool initialized;
} FilterState;

typedef struct {
    bool fan_on;
    bool alarm_on;
} ActuatorState;

/* ---------------- Sensor Layer ---------------- */

/* Simulated sensor reads */
static SensorData read_sensors(uint32_t tick)
{
    SensorData data;

    /* Simple deterministic test patterns */
    data.temperature = 25.0f + (tick % 10);               /* 25..34 */
    data.vibration   = (tick % 7 == 0) ? 6.5f : 2.0f;     /* occasional spike */

    return data;
}

/* ---------------- Filter Layer ---------------- */

static float ema_filter(float input, float prev, float alpha)
{
    return alpha * input + (1.0f - alpha) * prev;
}

static void filter_update(FilterState *state, const SensorData *raw)
{
    if (!state->initialized) {
        state->temperature_filtered = raw->temperature;
        state->vibration_filtered = raw->vibration;
        state->initialized = true;
        return;
    }

    state->temperature_filtered =
        ema_filter(raw->temperature, state->temperature_filtered, TEMP_ALPHA);

    state->vibration_filtered =
        ema_filter(raw->vibration, state->vibration_filtered, VIB_ALPHA);
}

/* ---------------- Actuator Layer ---------------- */

static void set_fan(bool on)
{
    /* Replace with GPIO write on real hardware */
    printf("ACTUATOR fan=%s\n", on ? "ON" : "OFF");
}

static void set_alarm(bool on)
{
    /* Replace with GPIO write on real hardware */
    printf("ACTUATOR alarm=%s\n", on ? "ON" : "OFF");
}

static void update_actuators(const FilterState *filter, ActuatorState *act)
{
    /* Hysteresis for fan */
    if (!act->fan_on && filter->temperature_filtered >= TEMP_THRESHOLD_ON) {
        act->fan_on = true;
        set_fan(true);
    } else if (act->fan_on && filter->temperature_filtered <= TEMP_THRESHOLD_OFF) {
        act->fan_on = false;
        set_fan(false);
    }

    /* Hysteresis for alarm */
    if (!act->alarm_on && filter->vibration_filtered >= VIB_THRESHOLD_ON) {
        act->alarm_on = true;
        set_alarm(true);
    } else if (act->alarm_on && filter->vibration_filtered <= VIB_THRESHOLD_OFF) {
        act->alarm_on = false;
        set_alarm(false);
    }
}

/* ---------------- Main Control Loop ---------------- */

int main(void)
{
    FilterState filter = {0};
    ActuatorState actuators = {0};

    for (uint32_t tick = 0; tick < LOOP_ITERATIONS; ++tick) {
        SensorData raw = read_sensors(tick);

        filter_update(&filter, &raw);
        update_actuators(&filter, &actuators);

        printf(
            "tick=%u raw_temp=%.2f raw_vib=%.2f filt_temp=%.2f filt_vib=%.2f fan=%d alarm=%d\n",
            tick,
            raw.temperature,
            raw.vibration,
            filter.temperature_filtered,
            filter.vibration_filtered,
            actuators.fan_on,
            actuators.alarm_on
        );
    }

    return 0;
}
