# 2. Minimal working C program

```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define FILTER_WINDOW 4
#define SENSOR_SAMPLES 20

#define THRESHOLD_ON   60
#define THRESHOLD_OFF  55   // hysteresis

typedef struct {
    int16_t buffer[FILTER_WINDOW];
    uint8_t index;
    int32_t sum;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool state;
} Actuator;

static void filter_init(MovingAverageFilter *f) {
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
    f->index = 0;
    f->sum = 0;
    f->count = 0;
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (int16_t)(f->sum / f->count);
}

static void actuator_init(Actuator *a) {
    a->state = false;
}

static void actuator_set(Actuator *a, bool on) {
    if (a->state != on) {
        a->state = on;
        printf("ACTUATOR -> %s\n", on ? "ON" : "OFF");
    }
}

static int16_t read_sensor_simulated(uint8_t t) {
    // Simulated noisy signal
    static const int16_t samples[SENSOR_SAMPLES] = {
        50, 52, 49, 55, 58,
        61, 63, 65, 62, 59,
        57, 54, 53, 56, 60,
        64, 66, 58, 52, 50
    };

    if (t < SENSOR_SAMPLES) {
        return samples[t];
    }
    return 50;
}

static void control_step(MovingAverageFilter *filter, Actuator *actuator, int16_t raw) {
    int16_t filtered = filter_update(filter, raw);

    if (!actuator->state && filtered >= THRESHOLD_ON) {
        actuator_set(actuator, true);
    } else if (actuator->state && filtered <= THRESHOLD_OFF) {
        actuator_set(actuator, false);
    }

    printf("raw=%d filtered=%d actuator=%s\n",
           raw,
           filtered,
           actuator->state ? "ON" : "OFF");
}

int main(void) {
    MovingAverageFilter filter;
    Actuator actuator;

    filter_init(&filter);
    actuator_init(&actuator);

    for (uint8_t t = 0; t < SENSOR_SAMPLES; t++) {
        int16_t raw = read_sensor_simulated(t);
        control_step(&filter, &actuator, raw);
    }

    return 0;
}
```

