## File: `edge_system.c`

```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* =========================
   Configuration
   ========================= */

#define NUM_SENSORS     2
#define FILTER_WINDOW   4

#define TEMP_SENSOR_ID  0
#define PRESS_SENSOR_ID 1

#define TEMP_THRESHOLD_HIGH   70
#define TEMP_THRESHOLD_LOW    65

#define PRESS_THRESHOLD_HIGH  80
#define PRESS_THRESHOLD_LOW   75

/* =========================
   Types
   ========================= */

typedef struct {
    int16_t buffer[FILTER_WINDOW];
    int32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool fan_on;
    bool valve_open;
} ActuatorState;

/* =========================
   Global State
   ========================= */

static MovingAverageFilter filters[NUM_SENSORS];
static ActuatorState actuators = { false, false };

/* =========================
   Filter Functions
   ========================= */

static void filter_init(MovingAverageFilter *f) {
    uint8_t i;
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static int16_t filter_update(MovingAverageFilter *f, int16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (int16_t)(f->sum / f->count);
}

/* =========================
   Hardware Abstraction
   Replace these with real drivers
   ========================= */

static int16_t read_sensor(uint8_t sensor_id) {
    static int16_t temp_samples[]  = {60, 62, 68, 71, 73, 69, 64, 66};
    static int16_t press_samples[] = {72, 74, 77, 81, 83, 79, 74, 73};
    static uint8_t idx = 0;

    int16_t value = 0;

    if (sensor_id == TEMP_SENSOR_ID) {
        value = temp_samples[idx];
    } else if (sensor_id == PRESS_SENSOR_ID) {
        value = press_samples[idx];
    }

    if (sensor_id == PRESS_SENSOR_ID) {
        idx = (idx + 1) % 8;
    }

    return value;
}

static void set_fan(bool on) {
    if (actuators.fan_on != on) {
        actuators.fan_on = on;
        printf("ACTUATOR: Fan %s\n", on ? "ON" : "OFF");
    }
}

static void set_valve(bool open) {
    if (actuators.valve_open != open) {
        actuators.valve_open = open;
        printf("ACTUATOR: Valve %s\n", open ? "OPEN" : "CLOSED");
    }
}

/* =========================
   Control Logic
   ========================= */

static void process_control(int16_t filtered_temp, int16_t filtered_press) {
    /* Temperature hysteresis control for fan */
    if (!actuators.fan_on && filtered_temp >= TEMP_THRESHOLD_HIGH) {
        set_fan(true);
    } else if (actuators.fan_on && filtered_temp <= TEMP_THRESHOLD_LOW) {
        set_fan(false);
    }

    /* Pressure hysteresis control for valve */
    if (!actuators.valve_open && filtered_press >= PRESS_THRESHOLD_HIGH) {
        set_valve(true);
    } else if (actuators.valve_open && filtered_press <= PRESS_THRESHOLD_LOW) {
        set_valve(false);
    }
}

/* =========================
   Main Loop
   ========================= */

int main(void) {
    uint8_t i;
    int16_t raw_temp, raw_press;
    int16_t filtered_temp, filtered_press;

    for (i = 0; i < NUM_SENSORS; i++) {
        filter_init(&filters[i]);
    }

    printf("Starting edge system...\n");

    for (i = 0; i < 16; i++) {
        raw_temp = read_sensor(TEMP_SENSOR_ID);
        raw_press = read_sensor(PRESS_SENSOR_ID);

        filtered_temp = filter_update(&filters[TEMP_SENSOR_ID], raw_temp);
        filtered_press = filter_update(&filters[PRESS_SENSOR_ID], raw_press);

        printf("RAW: temp=%d press=%d | FILTERED: temp=%d press=%d\n",
               raw_temp, raw_press, filtered_temp, filtered_press);

        process_control(filtered_temp, filtered_press);
    }

    return 0;
}
