```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
  </style>
</head>
<body>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.code] = true);
    window.addEventListener("keyup", e => keys[e.code] = false);

    const GRAVITY = 0.7;
    const FRICTION = 0.8;
    const MOVE_SPEED = 0.8;
    const MAX_SPEED = 6;
    const JUMP_FORCE = -14;

    class Platform {
      constructor(x, y, w, h, color = "#654321") {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.color = color;
      }

      draw(cameraX, cameraY) {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.w = 40;
        this.h = 60;
        this.vx = 0;
        this.vy = 0;
        this.onGround = false;
        this.facing = 1;

        // Animation
        this.animTimer = 0;
        this.animFrame = 0;
        this.state = "idle";
      }

      update(platforms) {
        // Horizontal input
        if (keys["ArrowLeft"] || keys["KeyA"]) {
          this.vx -= MOVE_SPEED;
          this.facing = -1;
        }
        if (keys["ArrowRight"] || keys["KeyD"]) {
          this.vx += MOVE_SPEED;
          this.facing = 1;
        }

        // Clamp horizontal speed
        this.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, this.vx));

        // Jump
        if ((keys["ArrowUp"] || keys["KeyW"] || keys["Space"]) && this.onGround) {
          this.vy = JUMP_FORCE;
          this.onGround = false;
        }

        // Apply gravity
        this.vy += GRAVITY;

        // Horizontal movement
        this.x += this.vx;
        this.resolveCollisions(platforms, "x");

        // Vertical movement
        this.y += this.vy;
        this.onGround = false;
        this.resolveCollisions(platforms, "y");

        // Friction
        this.vx *= FRICTION;
        if (Math.abs(this.vx) < 0.05) this.vx = 0;

        // Animation state
        if (!this.onGround) {
          this.state = "jump";
        } else if (Math.abs(this.vx) > 0.5) {
          this.state = "run";
        } else {
          this.state = "idle";
        }

        this.animate();
      }

      resolveCollisions(platforms, axis) {
        for (const p of platforms) {
          if (
            this.x < p.x + p.w &&
            this.x + this.w > p.x &&
            this.y < p.y + p.h &&
            this.y + this.h > p.y
          ) {
            if (axis === "x") {
              if (this.vx > 0) {
                this.x = p.x - this.w;
              } else if (this.vx < 0) {
                this.x = p.x + p.w;
              }
              this.vx = 0;
            } else if (axis === "y") {
              if (this.vy > 0) {
                this.y = p.y - this.h;
                this.vy = 0;
                this.onGround = true;
              } else if (this.vy < 0) {
                this.y = p.y + p.h;
                this.vy = 0;
              }
            }
          }
        }
      }

      animate() {
        this.animTimer++;
        if (this.animTimer > 8) {
          this.animTimer = 0;
          this.animFrame++;
        }
      }

      draw(cameraX, cameraY) {
        const drawX = this.x - cameraX;
        const drawY = this.y - cameraY;

        ctx.save();
        ctx.translate(drawX + this.w / 2, drawY + this.h / 2);
        ctx.scale(this.facing, 1);

        // Simple sprite animation using shapes/colors
        if (this.state === "idle") {
          ctx.fillStyle = "#ffcc00";
          ctx.fillRect(-this.w / 2, -this.h / 2, this.w, this.h);
        } else if (this.state === "run") {
          ctx.fillStyle = this.animFrame % 2 === 0 ? "#ff8800" : "#ffaa00";
          ctx.fillRect(-this.w / 2, -this.h / 2, this.w, this.h);

          // Legs
          ctx.strokeStyle = "#222";
          ctx.lineWidth = 4;
          ctx.beginPath();
          if (this.animFrame % 2 === 0) {
            ctx.moveTo(-10, this.h / 2);
            ctx.lineTo(-5, this.h / 2 + 10);
            ctx.moveTo(10, this.h / 2);
            ctx.lineTo(15, this.h / 2 + 10);
          } else {
            ctx.moveTo(-10, this.h / 2);
            ctx.lineTo(-15, this.h / 2 + 10);
            ctx.moveTo(10, this.h / 2);
            ctx.lineTo(5, this.h / 2 + 10);
          }
          ctx.stroke();
        } else if (this.state === "jump") {
          ctx.fillStyle = "#00ccff";
          ctx.fillRect(-this.w / 2, -this.h / 2, this.w, this.h);
        }

        // Eye
        ctx.fillStyle = "#000";
        ctx.beginPath();
        ctx.arc(8, -10, 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }
    }

    const platforms = [
      new Platform(-200, 500, 1400, 100, "#3c8d2f"),
      new Platform(200, 400, 160, 20),
      new Platform(450, 320, 160, 20),
      new Platform(700, 250, 160, 20),
      new Platform(950, 180, 160, 20),
      new Platform(1250, 350, 200, 20),
      new Platform(1550, 450, 220, 20),
    ];

    const player = new Player(100, 200);

    function drawBackground(cameraX) {
      // Parallax hills
      ctx.fillStyle = "#b7e4c7";
      ctx.beginPath();
      ctx.arc(200 - cameraX * 0.2, canvas.height, 250, Math.PI, Math.PI * 2);
      ctx.arc(700 - cameraX * 0.2, canvas.height, 300, Math.PI, Math.PI * 2);
      ctx.arc(1200 - cameraX * 0.2, canvas.height, 280, Math.PI, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "#95d5b2";
      ctx.beginPath();
      ctx.arc(100 - cameraX * 0.4, canvas.height, 180, Math.PI, Math.PI * 2);
      ctx.arc(500 - cameraX * 0.4, canvas.height, 220, Math.PI, Math.PI * 2);
      ctx.arc(1000 - cameraX * 0.4, canvas.height, 200, Math.PI, Math.PI * 2);
      ctx.fill();
    }

    function gameLoop() {
      player.update(platforms);

      const cameraX = player.x - canvas.width / 2 + player.w / 2;
      const cameraY = Math.max(0, player.y - canvas.height / 2);

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground(cameraX);

      for (const platform of platforms) {
        platform.draw(cameraX, cameraY);
      }

      player.draw(cameraX, cameraY);

      // UI
      ctx.fillStyle = "#000";
      ctx.font = "20px sans-serif";
      ctx.fillText("Controls: A/D or ←/→ to move, W/↑/Space to jump", 20, 30);

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
