  <title>2D Platformer</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background: #1e1e2f;
      overflow: hidden;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      border: 2px solid #222;
    }

    .info {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.4);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="info">
    Controls: A/D or ←/→ to move, W/Space/↑ to jump
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    // -----------------------------
    // Utility
    // -----------------------------
    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.width &&
        a.x + a.width > b.x &&
        a.y < b.y + b.height &&
        a.y + a.height > b.y
      );
    }

    // -----------------------------
    // Level
    // -----------------------------
    const world = {
      width: 2600,
      height: 1200,
      gravity: 0.6,
      platforms: [
        { x: 0, y: 500, width: 600, height: 40 },
        { x: 650, y: 440, width: 180, height: 30 },
        { x: 900, y: 380, width: 180, height: 30 },
        { x: 1150, y: 320, width: 180, height: 30 },
        { x: 1450, y: 420, width: 250, height: 30 },
        { x: 1780, y: 350, width: 220, height: 30 },
        { x: 2050, y: 280, width: 180, height: 30 },
        { x: 2280, y: 500, width: 320, height: 40 },
        { x: 400, y: 300, width: 120, height: 20 },
        { x: 250, y: 220, width: 100, height: 20 },
        { x: 1000, y: 180, width: 120, height: 20 },
        { x: 1600, y: 220, width: 140, height: 20 },
        { x: 0, y: 580, width: 2600, height: 80 } // ground
      ]
    };

    // -----------------------------
    // Camera
    // -----------------------------
    const camera = {
      x: 0,
      y: 0,
      width: canvas.width,
      height: canvas.height,
      follow(target) {
        this.x = target.x + target.width / 2 - this.width / 2;
        this.y = target.y + target.height / 2 - this.height / 2;

        this.x = clamp(this.x, 0, world.width - this.width);
        this.y = clamp(this.y, 0, world.height - this.height);
      }
    };

    // -----------------------------
    // Sprite Animation
    // -----------------------------
    class Animation {
      constructor(frames, frameDuration, loop = true) {
        this.frames = frames;
        this.frameDuration = frameDuration;
        this.loop = loop;
        this.timer = 0;
        this.index = 0;
      }

      reset() {
        this.timer = 0;
        this.index = 0;
      }

      update(dt) {
        this.timer += dt;
        if (this.timer >= this.frameDuration) {
          this.timer = 0;
          this.index++;
          if (this.index >= this.frames.length) {
            this.index = this.loop ? 0 : this.frames.length - 1;
          }
        }
      }

      getFrame() {
        return this.frames[this.index];
      }
    }

    // -----------------------------
    // Player
    // -----------------------------
    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 42;
        this.height = 58;

        this.vx = 0;
        this.vy = 0;

        this.speed = 0.7;
        this.maxSpeed = 6;
        this.jumpForce = -13;
        this.friction = 0.82;
        this.airFriction = 0.96;

        this.onGround = false;
        this.facing = 1;

        this.color = "#ffcc66";

        // Simple generated "sprite frames"
        this.animations = {
          idle: new Animation([
            { body: "#ffcc66", legOffset: 0, eye: 0 },
            { body: "#ffd27a", legOffset: 1, eye: 0 }
          ], 350),
          run: new Animation([
            { body: "#ffcc66", legOffset: -5, eye: 0 },
            { body: "#ffb84d", legOffset: 0, eye: 0 },
            { body: "#ffcc66", legOffset: 5, eye: 0 },
            { body: "#ffb84d", legOffset: 0, eye: 0 }
          ], 100),
          jump: new Animation([
            { body: "#ffe08a", legOffset: 0, eye: 1 }
          ], 1000)
        };

        this.currentAnimation = "idle";
      }

      setAnimation(name) {
        if (this.currentAnimation !== name) {
          this.currentAnimation = name;
          this.animations[name].reset();
        }
      }

      update(dt) {
        // Horizontal input
        if (keys.left) {
          this.vx -= this.speed;
          this.facing = -1;
        }
        if (keys.right) {
          this.vx += this.speed;
          this.facing = 1;
        }

        this.vx = clamp(this.vx, -this.maxSpeed, this.maxSpeed);

        // Jump
        if (keys.jump && this.onGround) {
          this.vy = this.jumpForce;
          this.onGround = false;
        }

        // Gravity
        this.vy += world.gravity;
        this.vy = clamp(this.vy, -50, 20);

        // Friction
        if (this.onGround) {
          this.vx *= this.friction;
        } else {
          this.vx *= this.airFriction;
        }

        // Move X and resolve collisions
        this.x += this.vx;
        for (const p of world.platforms) {
          if (rectsIntersect(this, p)) {
            if (this.vx > 0) {
              this.x = p.x - this.width;
            } else if (this.vx < 0) {
              this.x = p.x + p.width;
            }
            this.vx = 0;
          }
        }

        // Move Y and resolve collisions
        this.y += this.vy;
        this.onGround = false;
        for (const p of world.platforms) {
          if (rectsIntersect(this, p)) {
            if (this.vy > 0) {
              this.y = p.y - this.height;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              this.y = p.y + p.height;
              this.vy = 0;
            }
          }
        }

        // World bounds
        this.x = clamp(this.x, 0, world.width - this.width);

        if (this.y > world.height + 200) {
          this.respawn();
        }

        // Animation state
        if (!this.onGround) {
          this.setAnimation("jump");
        } else if (Math.abs(this.vx) > 0.5) {
          this.setAnimation("run");
        } else {
          this.setAnimation("idle");
        }

        this.animations[this.currentAnimation].update(dt);
      }

      respawn() {
        this.x = 100;
        this.y = 100;
        this.vx = 0;
        this.vy = 0;
      }

      draw(ctx, camera) {
        const frame = this.animations[this.currentAnimation].getFrame();
        const drawX = this.x - camera.x;
        const drawY = this.y - camera.y;

        ctx.save();
        ctx.translate(drawX + this.width / 2, drawY + this.height / 2);
        ctx.scale(this.facing, 1);

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.15)";
        ctx.beginPath();
        ctx.ellipse(0, this.height / 2 + 6, 16, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Legs
        ctx.fillStyle = "#5b3a29";
        ctx.fillRect(-12, 14 + frame.legOffset, 8, 20);
        ctx.fillRect(4, 14 - frame.legOffset, 8, 20);

        // Body
        ctx.fillStyle = frame.body;
        ctx.fillRect(-16, -20, 32, 36);

        // Head
        ctx.fillStyle = "#f5d7b2";
        ctx.fillRect(-14, -34, 28, 18);

        // Eye
        ctx.fillStyle = "#222";
        ctx.fillRect(4, -27 + frame.eye, 3, 3);

        // Arm
        ctx.fillStyle = "#d99b66";
        ctx.fillRect(14, -10, 6, 20);

        ctx.restore();
      }
    }

    const player = new Player(100, 100);

    // -----------------------------
    // Background
    // -----------------------------
    function drawBackground() {
      // Distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const hillX = i * 400 - (camera.x * 0.2 % 400);
        ctx.beginPath();
        ctx.arc(hillX, 500, 220, Math.PI, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = "#79b96d";
      for (let i = 0; i < 10; i++) {
        const hillX = i * 320 - (camera.x * 0.35 % 320);
        ctx.beginPath();
        ctx.arc(hillX, 540, 180, Math.PI, Math.PI * 2);
        ctx.fill();
      }
    }

    // -----------------------------
    // Draw Level
    // -----------------------------
    function drawPlatforms() {
      for (const p of world.platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(x, y, p.width, p.height);

        ctx.fillStyle = "#7ecb63";
        ctx.fillRect(x, y, p.width, 10);

        // Decorative pattern
        ctx.strokeStyle = "rgba(0,0,0,0.15)";
        for (let i = 0; i < p.width; i += 24) {
          ctx.beginPath();
          ctx.moveTo(x + i, y + 10);
          ctx.lineTo(x + i, y + p.height);
          ctx.stroke();
        }
      }
    }

    // -----------------------------
    // HUD
    // -----------------------------
    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(12, 12, 220, 70);

      ctx.fillStyle = "#fff";
      ctx.font = "16px sans-serif";
      ctx.fillText(`Position: ${Math.floor(player.x)}, ${Math.floor(player.y)}`, 24, 38);
      ctx.fillText(`Velocity: ${player.vx.toFixed(2)}, ${player.vy.toFixed(2)}`, 24, 60);
    }

    // -----------------------------
    // Game Loop
    // -----------------------------
    let lastTime = 0;

    function update(timestamp) {
      const dt = timestamp - lastTime;
      lastTime = timestamp;

      player.update(dt);
      camera.follow(player);

      render();
      requestAnimationFrame(update);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawPlatforms();
      player.draw(ctx, camera);
      drawHUD();
    }

    requestAnimationFrame(update);
  </script>
</body>
</html>
