<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      overflow: hidden;
      background: #111;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }

    .ui {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.4);
      padding: 10px 14px;
      border-radius: 8px;
      font-size: 14px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="ui">
    <div><strong>Controls</strong></div>
    <div>A / Left Arrow: Move left</div>
    <div>D / Right Arrow: Move right</div>
    <div>W / Space / Up Arrow: Jump</div>
  </div>

  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resizeCanvas() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    // -----------------------------
    // Utility
    // -----------------------------
    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function rectIntersect(a, b) {
      return (
        a.x < b.x + b.width &&
        a.x + a.width > b.x &&
        a.y < b.y + b.height &&
        a.y + a.height > b.y
      );
    }

    // -----------------------------
    // Camera
    // -----------------------------
    const camera = {
      x: 0,
      y: 0,
      smoothness: 0.12
    };

    // -----------------------------
    // Level
    // -----------------------------
    const world = {
      width: 3000,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 700, width: 600, height: 80 },
      { x: 700, y: 620, width: 220, height: 30 },
      { x: 1000, y: 540, width: 220, height: 30 },
      { x: 1300, y: 470, width: 180, height: 30 },
      { x: 1550, y: 620, width: 260, height: 30 },
      { x: 1900, y: 560, width: 220, height: 30 },
      { x: 2200, y: 500, width: 180, height: 30 },
      { x: 2450, y: 430, width: 220, height: 30 },
      { x: 2700, y: 700, width: 300, height: 80 },

      // lower platforms
      { x: 500, y: 850, width: 300, height: 30 },
      { x: 950, y: 920, width: 250, height: 30 },
      { x: 1400, y: 860, width: 250, height: 30 },
      { x: 1800, y: 940, width: 300, height: 30 },
      { x: 2300, y: 880, width: 240, height: 30 },
    ];

    // -----------------------------
    // Simple procedural sprite sheet
    // We'll generate a sprite sheet dynamically so no external assets are needed.
    // Each frame is 32x48.
    // Rows:
    // 0 = idle
    // 1 = run
    // 2 = jump
    // -----------------------------
    function createSpriteSheet() {
      const frameW = 32;
      const frameH = 48;
      const cols = 4;
      const rows = 3;

      const sheet = document.createElement("canvas");
      sheet.width = frameW * cols;
      sheet.height = frameH * rows;
      const sctx = sheet.getContext("2d");

      function drawCharacterFrame(x, y, pose) {
        sctx.clearRect(x, y, frameW, frameH);

        // transparent background
        // head
        sctx.fillStyle = "#ffd6a5";
        sctx.fillRect(x + 10, y + 4, 12, 12);

        // hair
        sctx.fillStyle = "#4b2e2e";
        sctx.fillRect(x + 10, y + 4, 12, 4);

        // body
        sctx.fillStyle = "#3a86ff";
        sctx.fillRect(x + 9, y + 16, 14, 14);

        // arms
        sctx.fillStyle = "#ffd6a5";
        if (pose === "idle1") {
          sctx.fillRect(x + 5, y + 18, 4, 10);
          sctx.fillRect(x + 23, y + 18, 4, 10);
        } else if (pose === "idle2") {
          sctx.fillRect(x + 6, y + 19, 4, 9);
          sctx.fillRect(x + 22, y + 19, 4, 9);
        } else if (pose === "run1") {
          sctx.fillRect(x + 4, y + 17, 4, 10);
          sctx.fillRect(x + 24, y + 20, 4, 8);
        } else if (pose === "run2") {
          sctx.fillRect(x + 6, y + 20, 4, 8);
          sctx.fillRect(x + 22, y + 17, 4, 10);
        } else if (pose === "run3") {
          sctx.fillRect(x + 4, y + 19, 4, 9);
          sctx.fillRect(x + 24, y + 18, 4, 9);
        } else if (pose === "run4") {
          sctx.fillRect(x + 6, y + 17, 4, 10);
          sctx.fillRect(x + 22, y + 20, 4, 8);
        } else if (pose === "jump") {
          sctx.fillRect(x + 5, y + 16, 4, 8);
          sctx.fillRect(x + 23, y + 16, 4, 8);
        }

        // legs
        sctx.fillStyle = "#222";
        if (pose === "idle1") {
          sctx.fillRect(x + 10, y + 30, 4, 14);
          sctx.fillRect(x + 18, y + 30, 4, 14);
        } else if (pose === "idle2") {
          sctx.fillRect(x + 11, y + 30, 4, 14);
          sctx.fillRect(x + 17, y + 30, 4, 14);
        } else if (pose === "run1") {
          sctx.fillRect(x + 8, y + 30, 4, 14);
          sctx.fillRect(x + 20, y + 32, 4, 12);
        } else if (pose === "run2") {
          sctx.fillRect(x + 11, y + 32, 4, 12);
          sctx.fillRect(x + 18, y + 30, 4, 14);
        } else if (pose === "run3") {
          sctx.fillRect(x + 9, y + 31, 4, 13);
          sctx.fillRect(x + 19, y + 31, 4, 13);
        } else if (pose === "run4") {
          sctx.fillRect(x + 11, y + 30, 4, 14);
          sctx.fillRect(x + 18, y + 32, 4, 12);
        } else if (pose === "jump") {
          sctx.fillRect(x + 9, y + 30, 4, 10);
          sctx.fillRect(x + 19, y + 30, 4, 10);
        }

        // shoes
        sctx.fillStyle = "#ff006e";
        if (pose === "jump") {
          sctx.fillRect(x + 8, y + 40, 6, 3);
          sctx.fillRect(x + 18, y + 40, 6, 3);
        } else {
          sctx.fillRect(x + 8, y + 42, 7, 3);
          sctx.fillRect(x + 17, y + 42, 7, 3);
        }
      }

      // Row 0: idle
      drawCharacterFrame(0 * frameW, 0 * frameH, "idle1");
      drawCharacterFrame(1 * frameW, 0 * frameH, "idle2");
      drawCharacterFrame(2 * frameW, 0 * frameH, "idle1");
      drawCharacterFrame(3 * frameW, 0 * frameH, "idle2");

      // Row 1: run
      drawCharacterFrame(0 * frameW, 1 * frameH, "run1");
      drawCharacterFrame(1 * frameW, 1 * frameH, "run2");
      drawCharacterFrame(2 * frameW, 1 * frameH, "run3");
      drawCharacterFrame(3 * frameW, 1 * frameH, "run4");

      // Row 2: jump
      drawCharacterFrame(0 * frameW, 2 * frameH, "jump");
      drawCharacterFrame(1 * frameW, 2 * frameH, "jump");
      drawCharacterFrame(2 * frameW, 2 * frameH, "jump");
      drawCharacterFrame(3 * frameW, 2 * frameH, "jump");

      return sheet;
    }

    const spriteSheet = createSpriteSheet();

    // -----------------------------
    // Player
    // -----------------------------
    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 32;
        this.height = 48;

        this.vx = 0;
        this.vy = 0;

        this.speed = 0.8;
        this.maxSpeed = 6;
        this.friction = 0.82;
        this.airFriction = 0.95;
        this.gravity = 0.65;
        this.jumpForce = -13;

        this.onGround = false;
        this.facing = 1;

        this.animations = {
          idle: { row: 0, frames: 4, speed: 0.12 },
          run:  { row: 1, frames: 4, speed: 0.18 },
          jump: { row: 2, frames: 4, speed: 0.08 }
        };

        this.currentAnimation = "idle";
        this.frameIndex = 0;
        this.frameTimer = 0;

        this.spawnX = x;
        this.spawnY = y;
      }

      update() {
        // Horizontal input
        if (keys.left) {
          this.vx -= this.speed;
          this.facing = -1;
        }
        if (keys.right) {
          this.vx += this.speed;
          this.facing = 1;
        }

        // Clamp horizontal speed
        this.vx = clamp(this.vx, -this.maxSpeed, this.maxSpeed);

        // Jump
        if (keys.jump && this.onGround) {
          this.vy = this.jumpForce;
          this.onGround = false;
        }

        // Gravity
        this.vy += this.gravity;
        this.vy = Math.min(this.vy, 18);

        // Friction
        if (this.onGround) {
          this.vx *= this.friction;
        } else {
          this.vx *= this.airFriction;
        }

        // Deadzone
        if (Math.abs(this.vx) < 0.05) this.vx = 0;

        // Horizontal movement and collision
        this.x += this.vx;
        for (const p of platforms) {
          if (rectIntersect(this, p)) {
            if (this.vx > 0) {
              this.x = p.x - this.width;
            } else if (this.vx < 0) {
              this.x = p.x + p.width;
            }
            this.vx = 0;
          }
        }

        // Vertical movement and collision
        this.y += this.vy;
        this.onGround = false;
        for (const p of platforms) {
          if (rectIntersect(this, p)) {
            if (this.vy > 0) {
              // falling onto platform
              this.y = p.y - this.height;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              // hitting underside
              this.y = p.y + p.height;
              this.vy = 0;
            }
          }
        }

        // World bounds
        this.x = clamp(this.x, 0, world.width - this.width);

        // Respawn if fallen
        if (this.y > world.height + 300) {
          this.respawn();
        }

        this.updateAnimation();
      }

      respawn() {
        this.x = this.spawnX;
        this.y = this.spawnY;
        this.vx = 0;
        this.vy = 0;
      }

      updateAnimation() {
        if (!this.onGround) {
          this.currentAnimation = "jump";
        } else if (Math.abs(this.vx) > 0.4) {
          this.currentAnimation = "run";
        } else {
          this.currentAnimation = "idle";
        }

        const anim = this.animations[this.currentAnimation];
        this.frameTimer += anim.speed;
        if (this.frameTimer >= 1) {
          this.frameTimer = 0;
          this.frameIndex = (this.frameIndex + 1) % anim.frames;
        }

        if (this.currentAnimation === "jump") {
          this.frameIndex = 0;
        }
      }

      draw(ctx) {
        const anim = this.animations[this.currentAnimation];
        const frameW = 32;
        const frameH = 48;
        const sx = this.frameIndex * frameW;
        const sy = anim.row * frameH;

        ctx.save();

        if (this.facing === -1) {
          ctx.translate(this.x + this.width / 2, this.y + this.height / 2);
          ctx.scale(-1, 1);
          ctx.drawImage(
            spriteSheet,
            sx, sy, frameW, frameH,
            -this.width / 2, -this.height / 2,
            this.width, this.height
          );
        } else {
          ctx.drawImage(
            spriteSheet,
            sx, sy, frameW, frameH,
            this.x, this.y,
            this.width, this.height
          );
        }

        ctx.restore();
      }
    }

    const player = new Player(100, 500);

    // -----------------------------
    // Background decorations
    // -----------------------------
    const hills = [
      { x: 100, y: 650, r: 180, color: "#8ecf7a" },
      { x: 500, y: 680, r: 220, color: "#7fc86b" },
      { x: 1000, y: 660, r: 200, color: "#8ecf7a" },
      { x: 1500, y: 700, r: 250, color: "#7fc86b" },
      { x: 2100, y: 670, r: 210, color: "#8ecf7a" },
      { x: 2700, y: 690, r: 240, color: "#7fc86b" }
    ];

    function drawBackground() {
      // sky already via canvas bg, but let's add clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      const cloudData = [
        { x: 200, y: 120 },
        { x: 700, y: 180 },
        { x: 1200, y: 110 },
        { x: 1800, y: 150 },
        { x: 2400, y: 100 }
      ];

      for (const c of cloudData) {
        drawCloud(c.x, c.y);
      }

      // hills
      for (const h of hills) {
        ctx.fillStyle = h.color;
        ctx.beginPath();
        ctx.arc(h.x, h.y, h.r, Math.PI, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawCloud(x, y) {
      ctx.beginPath();
      ctx.arc(x, y, 25, 0, Math.PI * 2);
      ctx.arc(x + 25, y - 10, 30, 0, Math.PI * 2);
      ctx.arc(x + 55, y, 25, 0, Math.PI * 2);
      ctx.arc(x + 30, y + 10, 28, 0, Math.PI * 2);
      ctx.fill();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        // dirt
        ctx.fillStyle = "#7f5539";
        ctx.fillRect(p.x, p.y, p.width, p.height);

        // grass top
        ctx.fillStyle = "#55a630";
        ctx.fillRect(p.x, p.y, p.width, 10);

        // little texture lines
        ctx.strokeStyle = "rgba(0,0,0,0.15)";
        for (let i = 0; i < p.width; i += 30) {
          ctx.beginPath();
          ctx.moveTo(p.x + i, p.y + 14);
          ctx.lineTo(p.x + i + 10, p.y + p.height - 8);
          ctx.stroke();
        }
      }
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(0,0,0,0.08)";
      ctx.strokeRect(0, 0, world.width, world.height);
    }

    // -----------------------------
    // Game loop
    // -----------------------------
    function updateCamera() {
      const targetX = player.x + player.width / 2 - canvas.width / 2;
      const targetY = player.y + player.height / 2 - canvas.height / 2;

      camera.x += (targetX - camera.x) * camera.smoothness;
      camera.y += (targetY - camera.y) * camera.smoothness;

      camera.x = clamp(camera.x, 0, Math.max(0, world.width - canvas.width));
      camera.y = clamp(camera.y, 0, Math.max(0, world.height - canvas.height));
    }

    function update() {
      player.update();
      updateCamera();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      drawBackground();
      drawPlatforms();
      drawWorldBounds();
      player.draw(ctx);

      ctx.restore();

      // HUD
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 40, 240, 30);
      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText(
        `Pos: (${Math.round(player.x)}, ${Math.round(player.y)})  Vel: (${player.vx.toFixed(2)}, ${player.vy.toFixed(2)})`,
        20,
        canvas.height - 20
      );
    }

    function gameLoop() {
      update();
      render();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
```

