      box-sizing: border-box;
    }

    body {
      margin: 0;
      overflow: hidden;
      background: #87ceeb;
      font-family: Arial, sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
    }

    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: #fff;
      font-size: 20px;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.6);
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="hud" id="hud">Score: 0 | Lives: 3</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const hud = document.getElementById("hud");

    function resizeCanvas() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.code] = true);
    window.addEventListener("keyup", e => keys[e.code] = false);

    const GRAVITY = 0.6;
    const FRICTION = 0.8;
    const AIR_FRICTION = 0.95;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_FORCE = -13;
    const WORLD_WIDTH = 3000;
    const GROUND_Y = 900;

    let score = 0;
    let lives = 3;

    class Animation {
      constructor(frames, frameDuration) {
        this.frames = frames;
        this.frameDuration = frameDuration;
        this.timer = 0;
        this.index = 0;
      }

      update(dt) {
        this.timer += dt;
        if (this.timer >= this.frameDuration) {
          this.timer = 0;
          this.index = (this.index + 1) % this.frames.length;
        }
      }

      getFrame() {
        return this.frames[this.index];
      }

      reset() {
        this.timer = 0;
        this.index = 0;
      }
    }

    class Entity {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.vx = 0;
        this.vy = 0;
        this.remove = false;
      }

      get left() { return this.x; }
      get right() { return this.x + this.w; }
      get top() { return this.y; }
      get bottom() { return this.y + this.h; }

      intersects(other) {
        return (
          this.right > other.left &&
          this.left < other.right &&
          this.bottom > other.top &&
          this.top < other.bottom
        );
      }
    }

    class Player extends Entity {
      constructor(x, y) {
        super(x, y, 42, 58);
        this.onGround = false;
        this.facing = 1;
        this.spawnX = x;
        this.spawnY = y;

        this.animations = {
          idle: new Animation([
            { body: "#ffcc66", eyeOffset: 0 },
            { body: "#ffd27a", eyeOffset: 1 }
          ], 400),
          run: new Animation([
            { body: "#ff9966", leg: 0 },
            { body: "#ff884d", leg: 1 },
            { body: "#ff9966", leg: 2 },
            { body: "#ff884d", leg: 1 }
          ], 100),
          jump: new Animation([
            { body: "#66ff99" }
          ], 1000),
          fall: new Animation([
            { body: "#66ccff" }
          ], 1000)
        };

        this.currentAnim = "idle";
      }

      respawn() {
        this.x = this.spawnX;
        this.y = this.spawnY;
        this.vx = 0;
        this.vy = 0;
      }

      update(dt, platforms) {
        if (keys["ArrowLeft"] || keys["KeyA"]) {
          this.vx -= MOVE_ACCEL;
          this.facing = -1;
        }
        if (keys["ArrowRight"] || keys["KeyD"]) {
          this.vx += MOVE_ACCEL;
          this.facing = 1;
        }

        this.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, this.vx));

        if ((keys["ArrowUp"] || keys["Space"] || keys["KeyW"]) && this.onGround) {
          this.vy = JUMP_FORCE;
          this.onGround = false;
        }

        this.vy += GRAVITY;

        if (this.onGround) {
          this.vx *= FRICTION;
        } else {
          this.vx *= AIR_FRICTION;
        }

        this.x += this.vx;
        this.resolveCollisions(platforms, "x");

        this.y += this.vy;
        this.onGround = false;
        this.resolveCollisions(platforms, "y");

        if (this.y > canvas.height + 1000) {
          lives--;
          this.respawn();
        }

        let nextAnim = "idle";
        if (!this.onGround) {
          nextAnim = this.vy < 0 ? "jump" : "fall";
        } else if (Math.abs(this.vx) > 0.5) {
          nextAnim = "run";
        }

        if (nextAnim !== this.currentAnim) {
          this.currentAnim = nextAnim;
          this.animations[this.currentAnim].reset();
        }

        this.animations[this.currentAnim].update(dt);
      }

      resolveCollisions(platforms, axis) {
        for (const p of platforms) {
          if (!this.intersects(p)) continue;

          if (axis === "x") {
            if (this.vx > 0) {
              this.x = p.x - this.w;
            } else if (this.vx < 0) {
              this.x = p.x + p.w;
            }
            this.vx = 0;
          } else if (axis === "y") {
            if (this.vy > 0) {
              this.y = p.y - this.h;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              this.y = p.y + p.h;
              this.vy = 0;
            }
          }
        }
      }

      draw(ctx, cameraX, cameraY) {
        const frame = this.animations[this.currentAnim].getFrame();
        const px = this.x - cameraX;
        const py = this.y - cameraY;

        ctx.save();
        ctx.translate(px + this.w / 2, py + this.h / 2);
        ctx.scale(this.facing, 1);

        ctx.fillStyle = frame.body || "#ffcc66";
        ctx.fillRect(-this.w / 2, -this.h / 2, this.w, this.h);

        ctx.fillStyle = "#663300";
        ctx.fillRect(-this.w / 2 + 8, this.h / 2 - 10, 10, 10);
        ctx.fillRect(this.w / 2 - 18, this.h / 2 - 10, 10, 10);

        if (this.currentAnim === "run") {
          const legOffset = frame.leg === 0 ? -3 : frame.leg === 2 ? 3 : 0;
          ctx.fillRect(-this.w / 2 + 8, this.h / 2 - 10 + legOffset, 10, 10);
          ctx.fillRect(this.w / 2 - 18, this.h / 2 - 10 - legOffset, 10, 10);
        }

        ctx.fillStyle = "#222";
        ctx.fillRect(4, -10 + (frame.eyeOffset || 0), 6, 6);

        ctx.restore();
      }
    }

    class Platform extends Entity {
      constructor(x, y, w, h, color = "#654321") {
        super(x, y, w, h);
        this.color = color;
      }

      draw(ctx, cameraX, cameraY) {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);

        ctx.fillStyle = "#7a5230";
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, 8);
      }
    }

    class Coin extends Entity {
      constructor(x, y) {
        super(x, y, 20, 20);
        this.anim = new Animation([
          { scale: 1.0, color: "#ffd700" },
          { scale: 0.8, color: "#ffea70" },
          { scale: 1.0, color: "#ffd700" },
          { scale: 1.2, color: "#fff099" }
        ], 120);
      }

      update(dt) {
        this.anim.update(dt);
      }

      draw(ctx, cameraX, cameraY) {
        const frame = this.anim.getFrame();
        const cx = this.x - cameraX + this.w / 2;
        const cy = this.y - cameraY + this.h / 2;
        const r = (this.w / 2) * frame.scale;

        ctx.fillStyle = frame.color;
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#ccaa00";
        ctx.stroke();
      }
    }

    class Enemy extends Entity {
      constructor(x, y, minX, maxX) {
        super(x, y, 40, 40);
        this.minX = minX;
        this.maxX = maxX;
        this.vx = 2;
      }

      update() {
        this.x += this.vx;
        if (this.x <= this.minX || this.x + this.w >= this.maxX) {
          this.vx *= -1;
        }
      }

      draw(ctx, cameraX, cameraY) {
        const x = this.x - cameraX;
        const y = this.y - cameraY;

        ctx.fillStyle = "#cc3333";
        ctx.fillRect(x, y, this.w, this.h);

        ctx.fillStyle = "#fff";
        ctx.fillRect(x + 8, y + 10, 8, 8);
        ctx.fillRect(x + 24, y + 10, 8, 8);

        ctx.fillStyle = "#000";
        ctx.fillRect(x + 10, y + 12, 4, 4);
        ctx.fillRect(x + 26, y + 12, 4, 4);
      }
    }

    const player = new Player(100, 400);

    const platforms = [
      new Platform(0, 650, 800, 80, "#4c8a2b"),
      new Platform(850, 580, 220, 30, "#4c8a2b"),
      new Platform(1150, 500, 220, 30, "#4c8a2b"),
      new Platform(1450, 430, 220, 30, "#4c8a2b"),
      new Platform(1750, 550, 260, 30, "#4c8a2b"),
      new Platform(2100, 470, 220, 30, "#4c8a2b"),
      new Platform(2400, 390, 250, 30, "#4c8a2b"),
      new Platform(2700, 650, 500, 80, "#4c8a2b")
    ];

    const coins = [
      new Coin(900, 530),
      new Coin(980, 530),
      new Coin(1200, 450),
      new Coin(1280, 450),
      new Coin(1500, 380),
      new Coin(1800, 500),
      new Coin(1880, 500),
      new Coin(2150, 420),
      new Coin(2450, 340)
    ];

    const enemies = [
      new Enemy(900, 540, 850, 1070),
      new Enemy(1760, 510, 1750, 2010),
      new Enemy(2720, 610, 2700, 3150)
    ];

    let cameraX = 0;
    let cameraY = 0;
    let lastTime = 0;

    function update(dt) {
      player.update(dt, platforms);

      for (const coin of coins) {
        coin.update(dt);
        if (!coin.remove && player.intersects(coin)) {
          coin.remove = true;
          score += 10;
        }
      }

      for (const enemy of enemies) {
        enemy.update();

        if (player.intersects(enemy)) {
          const playerBottomPrev = player.y + player.h - player.vy;
          const stomped = player.vy > 0 && playerBottomPrev <= enemy.y + 10;

          if (stomped) {
            enemy.remove = true;
            player.vy = -8;
            score += 25;
          } else {
            lives--;
            player.respawn();
            break;
          }
        }
      }

      for (let i = coins.length - 1; i >= 0; i--) {
        if (coins[i].remove) coins.splice(i, 1);
      }

      for (let i = enemies.length - 1; i >= 0; i--) {
        if (enemies[i].remove) enemies.splice(i, 1);
      }

      cameraX = player.x - canvas.width / 2 + player.w / 2;
      cameraY = player.y - canvas.height / 2 + player.h / 2;

      cameraX = Math.max(0, Math.min(cameraX, WORLD_WIDTH - canvas.width));
      cameraY = Math.max(0, Math.min(cameraY, 400));

      if (lives <= 0) {
        alert("Game Over! Final Score: " + score);
        document.location.reload();
      }

      hud.textContent = `Score: ${score} | Lives: ${lives}`;
    }

    function drawBackground() {
      const hills = [
        { x: 200, y: 550, w: 300, h: 150, color: "#7dbb6f" },
        { x: 700, y: 520, w: 400, h: 180, color: "#6eae60" },
        { x: 1400, y: 560, w: 350, h: 140, color: "#7dbb6f" },
        { x: 2200, y: 530, w: 420, h: 170, color: "#6eae60" }
      ];

      for (const hill of hills) {
        ctx.fillStyle = hill.color;
        ctx.beginPath();
        ctx.ellipse(
          hill.x - cameraX * 0.5,
          hill.y - cameraY * 0.2,
          hill.w / 2,
          hill.h / 2,
          0,
          0,
          Math.PI * 2
        );
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      for (const platform of platforms) {
        platform.draw(ctx, cameraX, cameraY);
      }

      for (const coin of coins) {
        coin.draw(ctx, cameraX, cameraY);
      }

      for (const enemy of enemies) {
        enemy.draw(ctx, cameraX, cameraY);
      }

      player.draw(ctx, cameraX, cameraY);
    }

    function gameLoop(timestamp) {
      const dt = timestamp - lastTime;
      lastTime = timestamp;

      update(dt);
      render();

      requestAnimationFrame(gameLoop);
    }

    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
```

