```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }

    .info {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="info">
    Controls: A/D or ←/→ to move, W/Space/↑ to jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", e => {
      keys[e.key.toLowerCase()] = false;
    });

    const GRAVITY = 0.7;
    const FRICTION = 0.8;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_FORCE = -14;

    const world = {
      width: 3000,
      height: 1200
    };

    const camera = {
      x: 0,
      y: 0,
      smooth: 0.12
    };

    class Platform {
      constructor(x, y, w, h, color = "#4c8c4a") {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.color = color;
      }

      draw(ctx, cam) {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x - cam.x, this.y - cam.y, this.w, this.h);

        ctx.fillStyle = "rgba(255,255,255,0.15)";
        ctx.fillRect(this.x - cam.x, this.y - cam.y, this.w, 6);
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.w = 40;
        this.h = 56;

        this.vx = 0;
        this.vy = 0;

        this.onGround = false;
        this.facing = 1;

        this.animations = {
          idle: [
            { body: "#ffcc66", legOffset: 0, armOffset: 0 },
            { body: "#ffd27a", legOffset: 1, armOffset: 1 }
          ],
          run: [
            { body: "#ffcc66", legOffset: -6, armOffset: 6 },
            { body: "#ffb84d", legOffset: 0, armOffset: 0 },
            { body: "#ffcc66", legOffset: 6, armOffset: -6 },
            { body: "#ffb84d", legOffset: 0, armOffset: 0 }
          ],
          jump: [
            { body: "#ff9966", legOffset: 2, armOffset: -8 }
          ]
        };

        this.currentAnimation = "idle";
        this.frameIndex = 0;
        this.frameTimer = 0;
        this.frameSpeed = 0.15;
      }

      update(platforms) {
        // Input
        let moving = false;

        if (keys["a"] || keys["arrowleft"]) {
          this.vx -= MOVE_ACCEL;
          this.facing = -1;
          moving = true;
        }
        if (keys["d"] || keys["arrowright"]) {
          this.vx += MOVE_ACCEL;
          this.facing = 1;
          moving = true;
        }

        if ((keys["w"] || keys[" "] || keys["arrowup"]) && this.onGround) {
          this.vy = JUMP_FORCE;
          this.onGround = false;
        }

        // Clamp horizontal speed
        if (this.vx > MAX_SPEED_X) this.vx = MAX_SPEED_X;
        if (this.vx < -MAX_SPEED_X) this.vx = -MAX_SPEED_X;

        // Apply gravity
        this.vy += GRAVITY;

        // Horizontal movement
        this.x += this.vx;
        this.handleCollisions(platforms, "x");

        // Vertical movement
        this.y += this.vy;
        this.onGround = false;
        this.handleCollisions(platforms, "y");

        // Friction
        this.vx *= FRICTION;
        if (Math.abs(this.vx) < 0.05) this.vx = 0;

        // World bounds
        if (this.x < 0) {
          this.x = 0;
          this.vx = 0;
        }
        if (this.x + this.w > world.width) {
          this.x = world.width - this.w;
          this.vx = 0;
        }
        if (this.y > world.height + 500) {
          this.respawn();
        }

        // Animation state
        if (!this.onGround) {
          this.currentAnimation = "jump";
          this.frameSpeed = 0.1;
        } else if (moving && Math.abs(this.vx) > 0.3) {
          this.currentAnimation = "run";
          this.frameSpeed = 0.25;
        } else {
          this.currentAnimation = "idle";
          this.frameSpeed = 0.08;
        }

        this.animate();
      }

      handleCollisions(platforms, axis) {
        for (const p of platforms) {
          if (
            this.x < p.x + p.w &&
            this.x + this.w > p.x &&
            this.y < p.y + p.h &&
            this.y + this.h > p.y
          ) {
            if (axis === "x") {
              if (this.vx > 0) {
                this.x = p.x - this.w;
              } else if (this.vx < 0) {
                this.x = p.x + p.w;
              }
              this.vx = 0;
            } else if (axis === "y") {
              if (this.vy > 0) {
                this.y = p.y - this.h;
                this.vy = 0;
                this.onGround = true;
              } else if (this.vy < 0) {
                this.y = p.y + p.h;
                this.vy = 0;
              }
            }
          }
        }
      }

      animate() {
        const frames = this.animations[this.currentAnimation];
        this.frameTimer += this.frameSpeed;
        if (this.frameTimer >= 1) {
          this.frameTimer = 0;
          this.frameIndex = (this.frameIndex + 1) % frames.length;
        }
      }

      getFrame() {
        const frames = this.animations[this.currentAnimation];
        return frames[this.frameIndex % frames.length];
      }

      respawn() {
        this.x = 100;
        this.y = 100;
        this.vx = 0;
        this.vy = 0;
      }

      draw(ctx, cam) {
        const px = this.x - cam.x;
        const py = this.y - cam.y;
        const frame = this.getFrame();

        ctx.save();
        ctx.translate(px + this.w / 2, py + this.h / 2);
        ctx.scale(this.facing, 1);

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath();
        ctx.ellipse(0, this.h / 2 + 4, 16, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Legs
        ctx.strokeStyle = "#3b2f2f";
        ctx.lineWidth = 5;
        ctx.beginPath();
        ctx.moveTo(-8, 16);
        ctx.lineTo(-8 + frame.legOffset, 28);
        ctx.moveTo(8, 16);
        ctx.lineTo(8 - frame.legOffset, 28);
        ctx.stroke();

        // Body
        ctx.fillStyle = frame.body;
        ctx.fillRect(-12, -8, 24, 24);

        // Arms
        ctx.strokeStyle = "#d18b47";
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(-12, 0);
        ctx.lineTo(-20, 8 + frame.armOffset);
        ctx.moveTo(12, 0);
        ctx.lineTo(20, 8 - frame.armOffset);
        ctx.stroke();

        // Head
        ctx.fillStyle = "#f1c27d";
        ctx.beginPath();
        ctx.arc(0, -18, 12, 0, Math.PI * 2);
        ctx.fill();

        // Eye
        ctx.fillStyle = "#222";
        ctx.beginPath();
        ctx.arc(4, -20, 2, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }
    }

    const platforms = [
      new Platform(0, 1100, 3000, 100, "#3f7c3c"),
      new Platform(150, 980, 180, 25),
      new Platform(420, 900, 180, 25),
      new Platform(700, 820, 180, 25),
      new Platform(980, 740, 180, 25),
      new Platform(1280, 860, 220, 25),
      new Platform(1600, 780, 160, 25),
      new Platform(1850, 680, 200, 25),
      new Platform(2150, 820, 220, 25),
      new Platform(2450, 720, 180, 25)
    ];

    const player = new Player(100, 100);

    function drawBackground() {
      // Far hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = i * 500 - (camera.x * 0.2 % 500);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 80, 220, Math.PI, Math.PI * 2);
        ctx.fill();
      }

      // Mid hills
      ctx.fillStyle = "#7fbd6d";
      for (let i = 0; i < 10; i++) {
        const x = i * 350 - (camera.x * 0.4 % 350);
        ctx.beginPath();
        ctx.arc(x, canvas.height - 30, 160, Math.PI, Math.PI * 2);
        ctx.fill();
      }
    }

    function updateCamera() {
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;

      camera.x += (targetX - camera.x) * camera.smooth;
      camera.y += (targetY - camera.y) * camera.smooth;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(0,0,0,0.15)";
      ctx.lineWidth = 2;
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function gameLoop() {
      requestAnimationFrame(gameLoop);

      player.update(platforms);
      updateCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawWorldBounds();

      for (const platform of platforms) {
        platform.draw(ctx, camera);
      }

      player.draw(ctx, camera);

      // HUD
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 40, 220, 30);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(
        `x:${player.x.toFixed(1)} y:${player.y.toFixed(1)} vx:${player.vx.toFixed(2)} vy:${player.vy.toFixed(2)}`,
        20,
        canvas.height - 20
      );
    }

    gameLoop();
  </script>
</body>
</html>
