You can save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      overflow: hidden;
      background: #111;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }

    .info {
      position: fixed;
      top: 8px;
      left: 8px;
      color: white;
      background: rgba(0, 0, 0, 0.4);
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 14px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div class="info">Move: A/D or ←/→ | Jump: W / Space / ↑</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resizeCanvas() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.code] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.code] = false;
    });

    class SpriteAnimator {
      constructor(image, animations) {
        this.image = image;
        this.animations = animations;
        this.current = "idle";
        this.frameIndex = 0;
        this.frameTimer = 0;
      }

      setAnimation(name) {
        if (this.current !== name) {
          this.current = name;
          this.frameIndex = 0;
          this.frameTimer = 0;
        }
      }

      update(dt) {
        const anim = this.animations[this.current];
        if (!anim) return;

        this.frameTimer += dt;
        if (this.frameTimer >= anim.frameDuration) {
          this.frameTimer = 0;
          this.frameIndex = (this.frameIndex + 1) % anim.frames.length;
        }
      }

      draw(ctx, x, y, width, height, flipX = false) {
        const anim = this.animations[this.current];
        if (!anim || !this.image || !this.image.complete || this.image.naturalWidth === 0) {
          // Fallback if image isn't loaded
          ctx.save();
          ctx.fillStyle = "#ffcc66";
          ctx.fillRect(x, y, width, height);
          ctx.restore();
          return;
        }

        const frame = anim.frames[this.frameIndex];
        const { sx, sy, sw, sh } = frame;

        ctx.save();
        if (flipX) {
          ctx.translate(x + width, y);
          ctx.scale(-1, 1);
          ctx.drawImage(this.image, sx, sy, sw, sh, 0, 0, width, height);
        } else {
          ctx.drawImage(this.image, sx, sy, sw, sh, x, y, width, height);
        }
        ctx.restore();
      }
    }

    class Platform {
      constructor(x, y, width, height, color = "#4c8c4a") {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.color = color;
      }

      draw(ctx, camera) {
        ctx.fillStyle = this.color;
        ctx.fillRect(
          this.x - camera.x,
          this.y - camera.y,
          this.width,
          this.height
        );

        // top highlight
        ctx.fillStyle = "#7fc97f";
        ctx.fillRect(
          this.x - camera.x,
          this.y - camera.y,
          this.width,
          6
        );
      }
    }

    class Player {
      constructor(x, y, animator) {
        this.x = x;
        this.y = y;
        this.width = 48;
        this.height = 64;

        this.vx = 0;
        this.vy = 0;

        this.speed = 900;
        this.maxSpeedX = 280;
        this.jumpStrength = 560;
        this.gravity = 1500;
        this.friction = 0.82;
        this.airControl = 0.55;

        this.onGround = false;
        this.facingLeft = false;

        this.animator = animator;
      }

      update(dt, platforms) {
        const left = keys["KeyA"] || keys["ArrowLeft"];
        const right = keys["KeyD"] || keys["ArrowRight"];
        const jump = keys["KeyW"] || keys["ArrowUp"] || keys["Space"];

        let move = 0;
        if (left) move -= 1;
        if (right) move += 1;

        const control = this.onGround ? 1 : this.airControl;
        this.vx += move * this.speed * control * dt;

        if (move === 0 && this.onGround) {
          this.vx *= this.friction;
          if (Math.abs(this.vx) < 1) this.vx = 0;
        }

        this.vx = Math.max(-this.maxSpeedX, Math.min(this.maxSpeedX, this.vx));

        if (jump && this.onGround) {
          this.vy = -this.jumpStrength;
          this.onGround = false;
        }

        this.vy += this.gravity * dt;

        // Horizontal movement
        this.x += this.vx * dt;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vx > 0) {
              this.x = p.x - this.width;
            } else if (this.vx < 0) {
              this.x = p.x + p.width;
            }
            this.vx = 0;
          }
        }

        // Vertical movement
        this.y += this.vy * dt;
        this.onGround = false;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vy > 0) {
              this.y = p.y - this.height;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              this.y = p.y + p.height;
              this.vy = 0;
            }
          }
        }

        if (this.vx < -1) this.facingLeft = true;
        if (this.vx > 1) this.facingLeft = false;

        this.updateAnimation(dt);
      }

      updateAnimation(dt) {
        if (!this.onGround) {
          this.animator.setAnimation("jump");
        } else if (Math.abs(this.vx) > 20) {
          this.animator.setAnimation("run");
        } else {
          this.animator.setAnimation("idle");
        }
        this.animator.update(dt);
      }

      intersects(rect) {
        return (
          this.x < rect.x + rect.width &&
          this.x + this.width > rect.x &&
          this.y < rect.y + rect.height &&
          this.y + this.height > rect.y
        );
      }

      draw(ctx, camera) {
        this.animator.draw(
          ctx,
          this.x - camera.x,
          this.y - camera.y,
          this.width,
          this.height,
          this.facingLeft
        );
      }
    }

    class Camera {
      constructor() {
        this.x = 0;
        this.y = 0;
        this.smoothing = 0.1;
      }

      follow(target) {
        const targetX = target.x + target.width / 2 - canvas.width / 2;
        const targetY = target.y + target.height / 2 - canvas.height / 2;

        this.x += (targetX - this.x) * this.smoothing;
        this.y += (targetY - this.y) * this.smoothing;

        if (this.y < 0) this.y = 0;
      }
    }

    // Optional sprite sheet image
    // Replace this path with your own sprite sheet.
    const playerImage = new Image();
    playerImage.src = "player_spritesheet.png";

    // Example sprite-sheet layout:
    // row 0 = idle frames
    // row 1 = run frames
    // row 2 = jump frame(s)
    // each frame = 32x32
    const FRAME_W = 32;
    const FRAME_H = 32;

    function frame(col, row) {
      return {
        sx: col * FRAME_W,
        sy: row * FRAME_H,
        sw: FRAME_W,
        sh: FRAME_H
      };
    }

    const playerAnimator = new SpriteAnimator(playerImage, {
      idle: {
        frames: [frame(0, 0), frame(1, 0), frame(2, 0), frame(3, 0)],
        frameDuration: 0.18
      },
      run: {
        frames: [frame(0, 1), frame(1, 1), frame(2, 1), frame(3, 1), frame(4, 1), frame(5, 1)],
        frameDuration: 0.09
      },
      jump: {
        frames: [frame(0, 2)],
        frameDuration: 0.2
      }
    });

    const level = [
      new Platform(-200, 650, 2200, 80, "#5b8c5a"),
      new Platform(220, 540, 180, 24),
      new Platform(500, 470, 180, 24),
      new Platform(770, 390, 160, 24),
      new Platform(1040, 500, 220, 24),
      new Platform(1360, 420, 180, 24),
      new Platform(1650, 340, 220, 24),
      new Platform(1950, 560, 260, 24)
    ];

    const player = new Player(100, 300, playerAnimator);
    const camera = new Camera();

    let lastTime = 0;

    function drawBackground(camera) {
      // parallax hills
      ctx.fillStyle = "#b7e4c7";
      for (let i = 0; i < 8; i++) {
        const hillX = i * 400 - (camera.x * 0.2 % 400);
        ctx.beginPath();
        ctx.arc(hillX, canvas.height - 50, 220, Math.PI, 2 * Math.PI);
        ctx.fill();
      }

      ctx.fillStyle = "#95d5b2";
      for (let i = 0; i < 8; i++) {
        const hillX = i * 350 - (camera.x * 0.35 % 350);
        ctx.beginPath();
        ctx.arc(hillX, canvas.height - 10, 180, Math.PI, 2 * Math.PI);
        ctx.fill();
      }
    }

    function drawWorld() {
      for (const p of level) {
        p.draw(ctx, camera);
      }
      player.draw(ctx, camera);
    }

    function drawDebug() {
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, 40, 200, 70);
      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)}`, 20, 62);
      ctx.fillText(`y: ${player.y.toFixed(1)}`, 20, 82);
      ctx.fillText(`onGround: ${player.onGround}`, 20, 102);
    }

    function update(dt) {
      player.update(dt, level);
      camera.follow(player);

      // Respawn if fallen off map
      if (player.y > 1200) {
        player.x = 100;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground(camera);
      drawWorld();
      drawDebug();
    }

    function gameLoop(timestamp) {
      const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
      lastTime = timestamp;

      update(dt);
      render();

      requestAnimationFrame(gameLoop);
    }

    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
```

## Notes

### 1. Sprite sheet
The code expects a file named:

```text
player_spritesheet.png
```

If you don’t provide one, the player will still render as a colored rectangle.

Expected frame layout:
- frame size: `32x32`
- row 0: idle
- row 1: run
- row 2: jump

You can adjust this here:

```js
const FRAME_W = 32;
const FRAME_H = 32;
```

and in the animation definitions.

### 2. Current physics behavior
This is an initial implementation, so the physics are intentionally simple:
- rectangle collisions only
- no slopes
- no one-way platforms
- no coyote time / jump buffering
- no acceleration curves beyond basic movement and friction

### 3. Good next improvements
If you want, I can also extend this with any of the following:

- tilemap-based level loading
- enemies and patrol AI
- collectibles and score
- double jump / wall jump
- attack system
- animated tiles
- sound effects and music
- gamepad support
- TypeScript + modular file structure
- Phaser or Matter.js version
- React/Canvas version

If you want, I can next turn this into a more structured multi-file project with:
- `Game`
- `Player`
- `Physics`
- `Animation`
- `Level`
- `Input`

for easier expansion.

Below is a single-file, minimal working 2D platformer in HTML/JS using the Canvas API.

Features:
- Gravity + simple physics
- AABB collision with platforms
- Left/right movement + jump
- Basic sprite animation using a generated sprite sheet
- Camera follow
- Collectible coins
- Goal flag

Controls:
- Arrow keys or A/D to move
- Space / W / Up to jump

Save as `index.html` and open in a browser.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      background: #87ceeb;
      overflow: hidden;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: #111;
      background: rgba(255,255,255,0.7);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hud" id="hud">Coins: 0</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const hud = document.getElementById('hud');

    const keys = {};
    addEventListener('keydown', e => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "arrowdown", "arrowleft", "arrowright"].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });
    addEventListener('keyup', e => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- Utility ---
    function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    // --- Sprite sheet generation (simple procedural animation) ---
    function createPlayerSpriteSheet() {
      const frameW = 24;
      const frameH = 32;
      const frames = 4;
      const c = document.createElement('canvas');
      c.width = frameW * frames;
      c.height = frameH;
      const g = c.getContext('2d');

      for (let i = 0; i < frames; i++) {
        const x = i * frameW;

        // body
        g.fillStyle = '#2d5bff';
        g.fillRect(x + 7, 8, 10, 12);

        // head
        g.fillStyle = '#ffd6a5';
        g.fillRect(x + 7, 2, 10, 8);

        // eyes
        g.fillStyle = '#222';
        g.fillRect(x + 9, 5, 1, 1);
        g.fillRect(x + 13, 5, 1, 1);

        // arms
        g.fillStyle = '#ffd6a5';
        g.fillRect(x + 4, 10 + (i % 2), 3, 8);
        g.fillRect(x + 17, 10 + ((i + 1) % 2), 3, 8);

        // legs animate
        g.fillStyle = '#1f2d3d';
        if (i % 2 === 0) {
          g.fillRect(x + 8, 20, 3, 10);
          g.fillRect(x + 13, 22, 3, 8);
        } else {
          g.fillRect(x + 8, 22, 3, 8);
          g.fillRect(x + 13, 20, 3, 10);
        }
      }
      return { image: c, frameW, frameH, frames };
    }

    const playerSheet = createPlayerSpriteSheet();

    // --- World ---
    const world = {
      width: 2600,
      height: 1200,
      gravity: 0.55,
      friction: 0.82,
      airFriction: 0.98,
      platforms: [
        { x: 0, y: 500, w: 500, h: 40 },
        { x: 560, y: 450, w: 180, h: 30 },
        { x: 820, y: 390, w: 160, h: 30 },
        { x: 1050, y: 330, w: 160, h: 30 },
        { x: 1300, y: 430, w: 240, h: 30 },
        { x: 1620, y: 360, w: 180, h: 30 },
        { x: 1880, y: 300, w: 180, h: 30 },
        { x: 2140, y: 420, w: 240, h: 30 },
        { x: 2420, y: 500, w: 180, h: 40 },

        // lower floor chunks
        { x: 300, y: 650, w: 220, h: 30 },
        { x: 650, y: 760, w: 260, h: 30 },
        { x: 1040, y: 860, w: 300, h: 30 },
      ],
      coins: [
        { x: 610, y: 410, r: 10, collected: false },
        { x: 880, y: 350, r: 10, collected: false },
        { x: 1110, y: 290, r: 10, collected: false },
        { x: 1390, y: 390, r: 10, collected: false },
        { x: 1700, y: 320, r: 10, collected: false },
        { x: 1960, y: 260, r: 10, collected: false },
        { x: 2230, y: 380, r: 10, collected: false },
      ],
      goal: { x: 2520, y: 440, w: 20, h: 60 }
    };

    const player = {
      x: 60,
      y: 300,
      w: 24,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 0.7,
      maxSpeed: 6,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      coins: 0,
      won: false
    };

    const camera = { x: 0, y: 0 };

    function respawn() {
      player.x = 60;
      player.y = 300;
      player.vx = 0;
      player.vy = 0;
    }

    function update() {
      if (player.won) return;

      // Input
      const left = keys['arrowleft'] || keys['a'];
      const right = keys['arrowright'] || keys['d'];
      const jump = keys[' '] || keys['w'] || keys['arrowup'];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      player.vx = clamp(player.vx, -player.maxSpeed, player.maxSpeed);

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.vx *= player.onGround ? world.friction : world.airFriction;

      // Horizontal move
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Fall off world
      if (player.y > world.height) {
        respawn();
      }

      // Coins
      for (const coin of world.coins) {
        if (coin.collected) continue;
        const nearestX = clamp(coin.x, player.x, player.x + player.w);
        const nearestY = clamp(coin.y, player.y, player.y + player.h);
        const dx = coin.x - nearestX;
        const dy = coin.y - nearestY;
        if (dx * dx + dy * dy < coin.r * coin.r) {
          coin.collected = true;
          player.coins++;
        }
      }

      // Goal
      if (rectsOverlap(player, world.goal)) {
        player.won = true;
      }

      // Animation
      if (!player.onGround) {
        player.frame = 1;
      } else if (Math.abs(player.vx) > 0.3) {
        player.animTime += 0.18;
        player.frame = Math.floor(player.animTime) % playerSheet.frames;
      } else {
        player.frame = 0;
        player.animTime = 0;
      }

      // Camera follow
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;
      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);

      hud.textContent = player.won
        ? `You win! Coins: ${player.coins}/${world.coins.length}`
        : `Coins: ${player.coins}/${world.coins.length}`;
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = '#9bd18b';
      for (let i = 0; i < 8; i++) {
        const x = i * 380 - (camera.x * 0.2 % 380);
        ctx.beginPath();
        ctx.arc(x, 520, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = '#7fbd6d';
      for (let i = 0; i < 10; i++) {
        const x = i * 280 - (camera.x * 0.35 % 280);
        ctx.beginPath();
        ctx.arc(x, 540, 120, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawWorld() {
      // Ground/platforms
      for (const p of world.platforms) {
        ctx.fillStyle = '#6b4f2a';
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
        ctx.fillStyle = '#4caf50';
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }

      // Coins
      for (const coin of world.coins) {
        if (coin.collected) continue;
        const t = performance.now() * 0.005;
        const bob = Math.sin(t + coin.x * 0.01) * 3;
        ctx.fillStyle = '#ffd700';
        ctx.beginPath();
        ctx.arc(coin.x - camera.x, coin.y - camera.y + bob, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#c99700';
        ctx.stroke();
      }

      // Goal flag
      const g = world.goal;
      ctx.fillStyle = '#555';
      ctx.fillRect(g.x - camera.x, g.y - camera.y, 4, g.h);
      ctx.fillStyle = '#ff3b30';
      ctx.fillRect(g.x - camera.x + 4, g.y - camera.y, 18, 12);
    }

    function drawPlayer() {
      const px = Math.round(player.x - camera.x);
      const py = Math.round(player.y - camera.y);

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(px + player.w, py);
        ctx.scale(-1, 1);
        drawPlayerFrame(0, 0);
      } else {
        ctx.translate(px, py);
        drawPlayerFrame(0, 0);
      }
      ctx.restore();

      function drawPlayerFrame(x, y) {
        ctx.drawImage(
          playerSheet.image,
          player.frame * playerSheet.frameW, 0, playerSheet.frameW, playerSheet.frameH,
          x, y, player.w, player.h
        );
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawWorld();
      drawPlayer();

      if (player.won) {
        ctx.fillStyle = 'rgba(0,0,0,0.45)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 42px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('You Win!', canvas.width / 2, canvas.height / 2 - 10);
        ctx.font = '20px sans-serif';
        ctx.fillText('Refresh to play again', canvas.width / 2, canvas.height / 2 + 30);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

