<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #87ceeb;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: #111;
      background: rgba(255,255,255,0.7);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <canvas id="game"></canvas>
  <div class="hud">Move: ← → or A D | Jump: Space / W / ↑</div>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const GRAVITY = 0.7;
    const FRICTION = 0.8;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_VELOCITY = -14;

    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 550, w: 2400, h: 100 },   // ground
        { x: 250, y: 450, w: 180, h: 20 },
        { x: 520, y: 380, w: 180, h: 20 },
        { x: 780, y: 320, w: 180, h: 20 },
        { x: 1100, y: 420, w: 220, h: 20 },
        { x: 1450, y: 340, w: 160, h: 20 },
        { x: 1720, y: 270, w: 180, h: 20 },
      ]
    };

    const player = {
      x: 80,
      y: 100,
      w: 36,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (!left && !right) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY;
      if (player.vy > 20) player.vy = 20;

      // Horizontal movement
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      if (player.y > world.height) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation timer
      if (Math.abs(player.vx) > 0.2 && player.onGround) {
        player.animTime += 0.2;
      } else {
        player.animTime = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawPlayer(x, y) {
      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      const walk = Math.sin(player.animTime * 8) * 5;
      const armSwing = Math.sin(player.animTime * 8) * 6;

      // legs
      ctx.fillStyle = "#2244aa";
      ctx.fillRect(-10, 8, 8, 18 + walk);
      ctx.fillRect(2, 8, 8, 18 - walk);

      // body
      ctx.fillStyle = "#e63946";
      ctx.fillRect(-12, -10, 24, 22);

      // arms
      ctx.fillStyle = "#f4a261";
      ctx.fillRect(-16, -8 + armSwing * 0.2, 4, 16);
      ctx.fillRect(12, -8 - armSwing * 0.2, 4, 16);

      // head
      ctx.fillStyle = "#f1c27d";
      ctx.fillRect(-10, -26, 20, 16);

      // eye
      ctx.fillStyle = "#111";
      ctx.fillRect(3, -20, 3, 3);

      ctx.restore();
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < world.width; i += 300) {
        const sx = i - camera.x * 0.3;
        ctx.beginPath();
        ctx.arc(sx, 600 - camera.y * 0.1, 180, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawWorld() {
      // platforms
      for (const p of world.platforms) {
        ctx.fillStyle = p.y > 500 ? "#5a8f3d" : "#6b4f2a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = "#7ec850";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawWorld();
      drawPlayer(player.x - camera.x, player.y - camera.y);

      // simple debug text
      ctx.fillStyle = "rgba(0,0,0,0.7)";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 12, canvas.height - 16);
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
