```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      background: #111;
      overflow: hidden;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .info {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.4);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="info">
    Move: ← → or A D | Jump: Space / W / ↑<br>
    Collect all coins and reach the green goal.
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const GRAVITY = 0.6;
    const FRICTION = 0.8;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 5;
    const JUMP_FORCE = -12;

    const world = {
      width: 2200,
      height: 900
    };

    const camera = {
      x: 0,
      y: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 500, h: 40 },
      { x: 580, y: 450, w: 180, h: 30 },
      { x: 840, y: 390, w: 180, h: 30 },
      { x: 1100, y: 330, w: 180, h: 30 },
      { x: 1380, y: 420, w: 220, h: 30 },
      { x: 1700, y: 500, w: 400, h: 40 },
      { x: 300, y: 380, w: 120, h: 20 },
      { x: 1450, y: 280, w: 100, h: 20 }
    ];

    const spawn = { x: 80, y: 300 };

    function makeCoins() {
      return [
        { x: 350, y: 340, r: 10, collected: false },
        { x: 640, y: 410, r: 10, collected: false },
        { x: 900, y: 350, r: 10, collected: false },
        { x: 1160, y: 290, r: 10, collected: false },
        { x: 1490, y: 240, r: 10, collected: false }
      ];
    }

    function makeEnemies() {
      return [
        { x: 1750, y: 470, w: 30, h: 30, minX: 1730, maxX: 2050, vx: 1.5 }
      ];
    }

    const goal = { x: 2020, y: 440, w: 40, h: 60 };

    const player = {
      x: spawn.x,
      y: spawn.y,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle",
      color: "#ff4d6d"
    };

    let coins = makeCoins();
    let enemies = makeEnemies();
    let message = "";

    function reset(full = false) {
      player.x = spawn.x;
      player.y = spawn.y;
      player.vx = 0;
      player.vy = 0;
      player.onGround = false;
      player.state = "idle";
      player.animTime = 0;
      if (full) {
        coins = makeCoins();
        enemies = makeEnemies();
        message = "";
      }
    }

    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function updatePlayer() {
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      player.vx *= FRICTION;
      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (jump && player.onGround) {
        player.vy = JUMP_FORCE;
        player.onGround = false;
      }

      player.vy += GRAVITY;

      // Horizontal move
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      if (player.y > world.height + 200) {
        message = "You fell! Resetting...";
        setTimeout(() => message = "", 800);
        reset(false);
      }

      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += 0.15;
    }

    function updateEnemies() {
      for (const e of enemies) {
        e.x += e.vx;
        if (e.x < e.minX || e.x + e.w > e.maxX) {
          e.vx *= -1;
        }

        if (rectsOverlap(player, e)) {
          message = "Ouch! Resetting...";
          setTimeout(() => message = "", 800);
          reset(false);
        }
      }
    }

    function updateCoinsAndGoal() {
      for (const c of coins) {
        if (c.collected) continue;
        const dx = (player.x + player.w / 2) - c.x;
        const dy = (player.y + player.h / 2) - c.y;
        if (dx * dx + dy * dy < (player.w * 0.35 + c.r) ** 2) {
          c.collected = true;
        }
      }

      const allCollected = coins.every(c => c.collected);
      if (allCollected && rectsOverlap(player, goal)) {
        message = "You win! Restarting...";
        setTimeout(() => {
          reset(true);
        }, 1200);
      }
    }

    function updateCamera() {
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;
      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawBackground() {
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = (i * 320 - camera.x * 0.3) % 2600;
        ctx.beginPath();
        ctx.arc(x, 520, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = "#7dbb6f";
      for (let i = 0; i < 10; i++) {
        const x = (i * 260 - camera.x * 0.5) % 2600;
        ctx.beginPath();
        ctx.arc(x, 540, 120, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
        ctx.fillStyle = "#4caf50";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawCoins() {
      for (const c of coins) {
        if (c.collected) continue;
        const bob = Math.sin(performance.now() * 0.01 + c.x) * 3;
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(c.x - camera.x, c.y - camera.y + bob, c.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c79a00";
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    }

    function drawGoal() {
      const allCollected = coins.every(c => c.collected);
      ctx.fillStyle = allCollected ? "#00e676" : "#888";
      ctx.fillRect(goal.x - camera.x, goal.y - camera.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x - camera.x, goal.y - camera.y, 4, goal.h);
    }

    function drawEnemies() {
      for (const e of enemies) {
        ctx.fillStyle = "#6a1b9a";
        ctx.fillRect(e.x - camera.x, e.y - camera.y, e.w, e.h);
        ctx.fillStyle = "#fff";
        ctx.fillRect(e.x - camera.x + 5, e.y - camera.y + 8, 6, 6);
        ctx.fillRect(e.x - camera.x + 19, e.y - camera.y + 8, 6, 6);
      }
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // body color changes slightly by animation state
      let body = player.color;
      if (player.state === "jump") body = "#ff758f";
      if (player.state === "run") body = "#ff335c";

      // body
      ctx.fillStyle = body;
      ctx.fillRect(-player.w / 2, -player.h / 2, player.w, player.h);

      // headband
      ctx.fillStyle = "#fff";
      ctx.fillRect(-player.w / 2, -player.h / 2 + 8, player.w, 5);

      // eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(4, -8, 4, 4);

      // simple sprite animation
      const t = player.animTime;
      let legOffset = 0;
      let armOffset = 0;

      if (player.state === "run") {
        legOffset = Math.sin(t * 10) * 6;
        armOffset = Math.cos(t * 10) * 5;
      } else if (player.state === "jump") {
        legOffset = 2;
        armOffset = -6;
      }

      ctx.fillStyle = "#222";

      // left leg
      ctx.fillRect(-10, player.h / 2 - 10, 6, 14 + legOffset);
      // right leg
      ctx.fillRect(4, player.h / 2 - 10, 6, 14 - legOffset);

      // left arm
      ctx.fillRect(-player.w / 2 - 4, -6, 6, 16 + armOffset);
      // right arm
      ctx.fillRect(player.w / 2 - 2, -6, 6, 16 - armOffset);

      ctx.restore();
    }

    function drawHUD() {
      const collected = coins.filter(c => c.collected).length;
      ctx.fillStyle = "rgba(0,0,0,0.45)";
      ctx.fillRect(12, 12, 220, 70);
      ctx.fillStyle = "#fff";
      ctx.font = "18px sans-serif";
      ctx.fillText(`Coins: ${collected}/${coins.length}`, 24, 40);
      ctx.fillText(`State: ${player.state}`, 24, 66);

      if (message) {
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        ctx.fillRect(canvas.width / 2 - 140, 20, 280, 44);
        ctx.fillStyle = "#fff";
        ctx.textAlign = "center";
        ctx.fillText(message, canvas.width / 2, 48);
        ctx.textAlign = "left";
      }
    }

    function update() {
      updatePlayer();
      updateEnemies();
      updateCoinsAndGoal();
      updateCamera();
    }

    function draw() {
      drawBackground();
      drawPlatforms();
      drawCoins();
      drawGoal();
      drawEnemies();
      drawPlayer();
      drawHUD();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    reset(true);
    loop();
  </script>
</body>
</html>
