      for (const p of world.platforms) {
        if (intersects(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      player.x = clamp(player.x, 0, world.width - player.w);
      if (player.y > world.height) {
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      if (!player.onGround) player.state = "jump";
      else if (Math.abs(player.vx) > 20) player.state = "walk";
      else player.state = "idle";

      player.animTime += dt;

      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5b3f1f";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#7ccf5b";
      ctx.fillRect(p.x, p.y, p.w, 8);
    }

    function drawPlayer() {
      const x = player.x;
      const y = player.y;

      ctx.save();

      if (player.facing < 0) {
        ctx.translate(x + player.w / 2, 0);
        ctx.scale(-1, 1);
        ctx.translate(-(x + player.w / 2), 0);
      }

      let bob = 0;
      let legOffset = 0;
      let armOffset = 0;
      let bodyColor = "#ffcc66";

      if (player.state === "walk") {
        const t = player.animTime * 12;
        bob = Math.sin(t) * 2;
        legOffset = Math.sin(t) * 6;
        armOffset = Math.sin(t + Math.PI) * 5;
        bodyColor = "#ffd166";
      } else if (player.state === "jump") {
        bob = -2;
        legOffset = 2;
        armOffset = -8;
        bodyColor = "#f4a261";
      }

      const px = x;
      const py = y + bob;

      ctx.fillStyle = bodyColor;
      ctx.fillRect(px + 10, py + 12, 22, 26);

      ctx.fillStyle = "#f1c27d";
      ctx.fillRect(px + 12, py, 18, 16);

      ctx.fillStyle = "#2d2d2d";
      ctx.fillRect(px + 14, py + 4, 3, 3);
      ctx.fillRect(px + 23, py + 4, 3, 3);

      ctx.strokeStyle = "#8b5a2b";
      ctx.lineWidth = 4;

      ctx.beginPath();
      ctx.moveTo(px + 12, py + 18);
      ctx.lineTo(px + 6, py + 30 + armOffset);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(px + 30, py + 18);
      ctx.lineTo(px + 36, py + 30 - armOffset);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(px + 16, py + 38);
      ctx.lineTo(px + 14, py + 54 + legOffset);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(px + 26, py + 38);
      ctx.lineTo(px + 28, py + 54 - legOffset);
      ctx.stroke();

      ctx.restore();
    }

    function drawBackground() {
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 6; i++) {
        const cx = (i * 350 - camera.x * 0.3) % (canvas.width + 400) - 100;
        const cy = 60 + (i % 3) * 50;
        ctx.beginPath();
        ctx.arc(cx, cy, 28, 0, Math.PI * 2);
        ctx.arc(cx + 25, cy - 10, 22, 0, Math.PI * 2);
        ctx.arc(cx + 50, cy, 26, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = "#9bd18b";
      ctx.fillRect(0, canvas.height - 80, canvas.width, 80);
    }

    function render() {
      drawBackground();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      for (const p of world.platforms) drawPlatform(p);
      drawPlayer();

      ctx.restore();

      ctx.fillStyle = "rgba(0,0,0,0.6)";
      ctx.fillRect(10, 10, 250, 70);
      ctx.fillStyle = "white";
      ctx.font = "16px sans-serif";
      ctx.fillText("Move: A/D or ←/→", 20, 35);
      ctx.fillText("Jump: W / ↑ / Space", 20, 58);
      ctx.fillText("State: " + player.state, 20, 81);
    }

    let last = performance.now();
    function loop(now) {
      const dt = (now - last) / 1000;
      last = now;
      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

