Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #87ceeb;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }
    #ui {
      position: fixed;
      top: 10px;
      left: 10px;
      color: #111;
      background: rgba(255,255,255,0.7);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div id="ui">
    Arrow keys / A,D to move, Space / W / Up to jump
    <br />
    Collect coins and reach the green goal.
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const WORLD_WIDTH = 2200;
    const WORLD_HEIGHT = 900;
    const GRAVITY = 0.6;
    const FRICTION = 0.8;
    const MOVE_ACCEL = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_VELOCITY = -13;

    const camera = {
      x: 0,
      y: 0
    };

    const player = {
      x: 100,
      y: 100,
      w: 36,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      state: "idle",
      color: "#ffcc66"
    };

    const platforms = [
      { x: 0, y: 500, w: 500, h: 60 },
      { x: 560, y: 440, w: 180, h: 30 },
      { x: 820, y: 380, w: 180, h: 30 },
      { x: 1080, y: 320, w: 180, h: 30 },
      { x: 1360, y: 420, w: 240, h: 30 },
      { x: 1680, y: 500, w: 420, h: 60 },
      { x: 300, y: 350, w: 120, h: 20 },
      { x: 1450, y: 260, w: 100, h: 20 },
      { x: 1900, y: 360, w: 120, h: 20 }
    ];

    const coins = [
      { x: 620, y: 390, r: 10, collected: false },
      { x: 880, y: 330, r: 10, collected: false },
      { x: 1140, y: 270, r: 10, collected: false },
      { x: 1490, y: 210, r: 10, collected: false },
      { x: 1940, y: 310, r: 10, collected: false }
    ];

    const goal = { x: 2030, y: 440, w: 40, h: 60 };

    let score = 0;
    let won = false;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectOverlap(circle, rect) {
      const closestX = clamp(circle.x, rect.x, rect.x + rect.w);
      const closestY = clamp(circle.y, rect.y, rect.y + rect.h);
      const dx = circle.x - closestX;
      const dy = circle.y - closestY;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function resetGame() {
      player.x = 100;
      player.y = 100;
      player.vx = 0;
      player.vy = 0;
      score = 0;
      won = false;
      for (const coin of coins) coin.collected = false;
    }

    function handleInput() {
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_ACCEL;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL;
        player.facing = 1;
      }

      if (!left && !right && player.onGround) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }
    }

    function updatePhysics() {
      player.vy += GRAVITY;

      // Horizontal move
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      player.x = clamp(player.x, 0, WORLD_WIDTH - player.w);
      if (player.y > WORLD_HEIGHT + 200) {
        resetGame();
      }

      // Collect coins
      for (const coin of coins) {
        if (!coin.collected && circleRectOverlap(coin, player)) {
          coin.collected = true;
          score++;
        }
      }

      // Goal
      if (rectsOverlap(player, goal) && score === coins.length) {
        won = true;
      }
    }

    function updateAnimation(dt) {
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;

      if (player.state === "idle") {
        player.frame = Math.floor(player.animTime / 400) % 2;
      } else if (player.state === "run") {
        player.frame = Math.floor(player.animTime / 100) % 4;
      } else {
        player.frame = 0;
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = clamp(camera.x, 0, WORLD_WIDTH - canvas.width);
      camera.y = clamp(camera.y, 0, WORLD_HEIGHT - canvas.height);
    }

    function drawBackground() {
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // parallax hills
      ctx.save();
      ctx.translate(-camera.x * 0.3, -camera.y * 0.1);
      ctx.fillStyle = "#7dbb6f";
      for (let i = 0; i < 8; i++) {
        ctx.beginPath();
        ctx.arc(200 + i * 320, 520, 180, Math.PI, 0);
        ctx.fill();
      }
      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
        ctx.fillStyle = "#3fa34d";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawCoins() {
      for (const coin of coins) {
        if (coin.collected) continue;
        const x = coin.x - camera.x;
        const y = coin.y - camera.y;
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(x, y, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#cc9a00";
        ctx.lineWidth = 3;
        ctx.stroke();
      }
    }

    function drawGoal() {
      ctx.fillStyle = "#2ecc71";
      ctx.fillRect(goal.x - camera.x, goal.y - camera.y, goal.w, goal.h);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(goal.x - camera.x + 8, goal.y - camera.y + 8, 6, 44);
      ctx.beginPath();
      ctx.moveTo(goal.x - camera.x + 14, goal.y - camera.y + 8);
      ctx.lineTo(goal.x - camera.x + 34, goal.y - camera.y + 18);
      ctx.lineTo(goal.x - camera.x + 14, goal.y - camera.y + 28);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // body color changes slightly by state/frame to simulate animation
      let bodyColor = "#ffcc66";
      let legOffset = 0;
      let armOffset = 0;

      if (player.state === "run") {
        legOffset = (player.frame % 2 === 0) ? 5 : -5;
        armOffset = -legOffset;
        bodyColor = "#ffd27a";
      } else if (player.state === "jump") {
        legOffset = 2;
        armOffset = -8;
        bodyColor = "#ffb84d";
      } else {
        legOffset = (player.frame % 2 === 0) ? 1 : -1;
      }

      // head
      ctx.fillStyle = "#f4b183";
      ctx.fillRect(10, 0, 16, 16);

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(8, 16, 20, 18);

      // arms
      ctx.fillStyle = "#e09a5f";
      ctx.fillRect(2, 18 + armOffset * 0.2, 6, 16);
      ctx.fillRect(28, 18 - armOffset * 0.2, 6, 16);

      // legs
      ctx.fillStyle = "#334";
      ctx.fillRect(10, 34, 6, 14 + legOffset * 0.2);
      ctx.fillRect(20, 34, 6, 14 - legOffset * 0.2);

      // eye
      ctx.fillStyle = "#222";
      ctx.fillRect(18, 5, 2, 2);

      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, 10, 170, 60);
      ctx.fillStyle = "#fff";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Coins: ${score}/${coins.length}`, 20, 35);
      ctx.fillText(won ? "You Win! R to reset" : "", 20, 60);
    }

    function draw() {
      drawBackground();
      drawPlatforms();
      drawCoins();
      drawGoal();
      drawPlayer();
      drawHUD();
    }

    let lastTime = 0;
    function loop(timestamp) {
      const dt = timestamp - lastTime;
      lastTime = timestamp;

      if (keys["r"]) resetGame();

      if (!won) {
        handleInput();
        updatePhysics();
        updateAnimation(dt);
        updateCamera();
      }

      draw();
      requestAnimationFrame(loop);
    }

    resetGame();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
