            player.vy = 0;
          }
        }
      }

      for (const coin of level.coins) {
        if (!coin.collected && circleRectOverlap(coin, player)) {
          coin.collected = true;
          player.coins++;
        }
      }

      if (rectsOverlap(player, level.goal)) {
        alert("You win! Coins: " + player.coins + "/" + level.coins.length);
        resetGame();
      }

      if (player.y > WORLD.height + 200) {
        alert("You fell! Restarting...");
        resetGame();
      }

      if (Math.abs(player.vx) > 20 && player.onGround) {
        player.animTime += dt * 10;
        player.frame = Math.floor(player.animTime) % 3;
      } else {
        player.frame = 0;
        player.animTime = 0;
      }

      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = Math.max(0, Math.min(camera.x, WORLD.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, WORLD.height - canvas.height));

      hud.textContent = `Coins: ${player.coins}/${level.coins.length}`;
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#6b4f2a";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#7acb5a";
      ctx.fillRect(p.x, p.y, p.w, 8);
    }

    function drawCoin(c) {
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
      ctx.fillStyle = "#ffd54a";
      ctx.fill();
      ctx.strokeStyle = "#c89b00";
      ctx.lineWidth = 3;
      ctx.stroke();
    }

    function drawGoal(g) {
      ctx.fillStyle = "#e8e8e8";
      ctx.fillRect(g.x, g.y, 4, g.h);
      ctx.fillStyle = "#ff4d6d";
      ctx.fillRect(g.x + 4, g.y, g.w - 4, 20);
    }

    function drawPlayer() {
      const sx = player.frame * 32;
      const sy = 0;

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w / 2, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(
          playerSheet,
          sx, sy, 32, 32,
          -player.w / 2, 0, player.w, player.h
        );
      } else {
        ctx.drawImage(
          playerSheet,
          sx, sy, 32, 32,
          player.x, player.y, player.w, player.h
        );
      }
      ctx.restore();
    }

    function drawBackground() {
      ctx.fillStyle = "rgba(255,255,255,0.35)";
      for (let i = 0; i < 8; i++) {
        const x = (i * 300 - camera.x * 0.2) % (WORLD.width + 300);
        const y = 80 + (i % 3) * 60;
        ctx.beginPath();
        ctx.arc(x, y, 30, Math.PI * 0.5, Math.PI * 1.5);
        ctx.arc(x + 35, y - 20, 35, Math.PI, 0);
        ctx.arc(x + 70, y, 30, Math.PI * 1.5, Math.PI * 0.5);
        ctx.closePath();
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      for (const p of level.platforms) drawPlatform(p);
      for (const c of level.coins) if (!c.collected) drawCoin(c);
      drawGoal(level.goal);
      drawPlayer();

      ctx.restore();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;
      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    resetGame();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
