Save as `index.html` and open in a browser.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      background: #1e1e2f;
      overflow: hidden;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#7ec0ee, #dff6ff);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
      border: 2px solid #111;
    }
    .hud {
      position: fixed;
      top: 8px;
      left: 8px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 6px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hud">Arrows / A,D to move · Space / W / Up to jump</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');

    const keys = {};
    addEventListener('keydown', e => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "arrowdown", "arrowleft", "arrowright"].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });
    addEventListener('keyup', e => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- Utility ---
    function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    // --- Generate a tiny sprite sheet in code ---
    function createPlayerSpriteSheet() {
      const sheet = document.createElement('canvas');
      sheet.width = 96;   // 3 frames * 32
      sheet.height = 32;
      const sctx = sheet.getContext('2d');

      function drawFrame(offsetX, legOffset, armOffset, bodyColor) {
        // transparent bg
        // head
        sctx.fillStyle = '#ffd6a5';
        sctx.fillRect(offsetX + 10, 2, 12, 10);

        // body
        sctx.fillStyle = bodyColor;
        sctx.fillRect(offsetX + 10, 12, 12, 10);

        // eyes
        sctx.fillStyle = '#222';
        sctx.fillRect(offsetX + 13, 5, 1, 1);
        sctx.fillRect(offsetX + 18, 5, 1, 1);

        // arms
        sctx.fillStyle = '#ffd6a5';
        sctx.fillRect(offsetX + 6, 13 + armOffset, 4, 3);
        sctx.fillRect(offsetX + 22, 13 - armOffset, 4, 3);

        // legs
        sctx.fillStyle = '#2d6cdf';
        sctx.fillRect(offsetX + 11, 22, 4, 8 + legOffset);
        sctx.fillRect(offsetX + 17, 22, 4, 8 - legOffset);
      }

      drawFrame(0, 0, 0, '#ff5d73');   // idle
      drawFrame(32, 2, 1, '#ff5d73');  // walk 1
      drawFrame(64, -2, -1, '#ff5d73');// walk 2

      return sheet;
    }

    const playerSheet = createPlayerSpriteSheet();

    // --- World ---
    const world = {
      width: 2400,
      height: 1200,
      platforms: [
        { x: 0, y: 500, w: 500, h: 40 },
        { x: 560, y: 440, w: 180, h: 30 },
        { x: 820, y: 380, w: 180, h: 30 },
        { x: 1080, y: 320, w: 180, h: 30 },
        { x: 1350, y: 420, w: 220, h: 30 },
        { x: 1650, y: 350, w: 220, h: 30 },
        { x: 1950, y: 280, w: 250, h: 30 },
        { x: 2200, y: 500, w: 200, h: 40 },

        // lower path
        { x: 450, y: 560, w: 220, h: 30 },
        { x: 760, y: 620, w: 300, h: 30 },
        { x: 1140, y: 690, w: 240, h: 30 },
        { x: 1480, y: 760, w: 350, h: 30 },

        // floor
        { x: -200, y: 900, w: 3000, h: 200 }
      ]
    };

    // --- Player ---
    const player = {
      x: 80,
      y: 300,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 0.7,
      maxSpeed: 5,
      jumpPower: 12,
      gravity: 0.6,
      friction: 0.82,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      spawnX: 80,
      spawnY: 300
    };

    const camera = { x: 0, y: 0 };

    function input() {
      const left = keys['arrowleft'] || keys['a'];
      const right = keys['arrowright'] || keys['d'];
      const jump = keys[' '] || keys['w'] || keys['arrowup'];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      player.vx = clamp(player.vx, -player.maxSpeed, player.maxSpeed);

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
    }

    function physics() {
      player.vy += player.gravity;
      player.vx *= player.friction;

      // Horizontal move
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Respawn if fallen
      if (player.y > world.height) {
        player.x = player.spawnX;
        player.y = player.spawnY;
        player.vx = 0;
        player.vy = 0;
      }

      // World bounds
      player.x = clamp(player.x, 0, world.width - player.w);
    }

    function animate(dt) {
      const moving = Math.abs(player.vx) > 0.4;
      if (!player.onGround) {
        player.frame = 1; // airborne uses a walk frame
        return;
      }

      if (!moving) {
        player.frame = 0;
      } else {
        player.animTime += dt;
        if (player.animTime > 120) {
          player.animTime = 0;
          player.frame = player.frame === 1 ? 2 : 1;
        }
      }
    }

    function updateCamera() {
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      camera.x = clamp(camera.x, 0, world.width - canvas.width);
      camera.y = clamp(camera.y, 0, world.height - canvas.height);
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = '#9bd18b';
      for (let i = 0; i < 8; i++) {
        const x = i * 320 - (camera.x * 0.2 % 320);
        ctx.beginPath();
        ctx.arc(x, 500, 180, Math.PI, 2 * Math.PI);
        ctx.fill();
      }

      ctx.fillStyle = '#7bb661';
      for (let i = 0; i < 10; i++) {
        const x = i * 260 - (camera.x * 0.35 % 260);
        ctx.beginPath();
        ctx.arc(x, 540, 140, Math.PI, 2 * Math.PI);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = '#5c4033';
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = '#6fcf6a';
        ctx.fillRect(sx, sy, p.w, 8);

        // simple tile lines
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        for (let x = 0; x < p.w; x += 32) {
          ctx.beginPath();
          ctx.moveTo(sx + x, sy + 8);
          ctx.lineTo(sx + x, sy + p.h);
          ctx.stroke();
        }
      }
    }

    function drawPlayer() {
      const sx = player.x - camera.x;
      const sy = player.y - camera.y;

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(sx + player.w, sy);
        ctx.scale(-1, 1);
        ctx.drawImage(playerSheet, player.frame * 32, 0, 32, 32, 0, 0, 32, 32);
      } else {
        ctx.drawImage(playerSheet, player.frame * 32, 0, 32, 32, sx, sy, 32, 32);
      }
      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawPlayer();

      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.fillRect(10, canvas.height - 34, 220, 24);
      ctx.fillStyle = '#fff';
      ctx.font = '14px sans-serif';
      ctx.fillText(
        `x:${player.x.toFixed(0)} y:${player.y.toFixed(0)} vx:${player.vx.toFixed(1)} vy:${player.vy.toFixed(1)}`,
        18,
        canvas.height - 17
      );
    }

    let last = performance.now();
    function loop(now) {
      const dt = now - last;
      last = now;

      input();
      physics();
      animate(dt);
      updateCamera();
      draw();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
