      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const hx = i * 350 - (camera.x * 0.2 % 350);
        ctx.beginPath();
        ctx.arc(hx, canvas.height - 40, 180, Math.PI, Math.PI * 2);
        ctx.fill();
