      // body color by state
      let bodyColor = "#ffcc66";
      if (player.state === "run") bodyColor = "#ffd166";
      if (player.state === "jump") bodyColor = "#f4a261";

      // bobbing animation
      let bob = 0;
      let legSwing = 0;
      if (player.state === "run") {
        bob = Math.sin(player.animTime * 10) * 2;
        legSwing = Math.sin(player.animTime * 12) * 6;
      } else if (player.state === "idle") {
        bob = Math.sin(player.animTime * 3) * 1;
      }

      // torso
      ctx.fillStyle = bodyColor;
      ctx.fillRect(-player.w / 2, -player.h / 2 + bob, player.w, player.h);

      // eye
      ctx.fillStyle = "#222";
      ctx.fillRect(6, -10 + bob, 5, 5);

