      ctx.strokeStyle = "#5b3a29";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-10, player.h / 2 - 8 + bob);
      ctx.lineTo(-10, player.h / 2 + 8 + bob + legSwing);
      ctx.moveTo(10, player.h / 2 - 8 + bob);
      ctx.lineTo(10, player.h / 2 + 8 + bob - legSwing);
      ctx.stroke();

      // jump arms
      if (player.state === "jump") {
        ctx.beginPath();
        ctx.moveTo(-player.w / 2, -10);
        ctx.lineTo(-player.w / 2 - 10, -20);
        ctx.moveTo(player.w / 2, -10);
        ctx.lineTo(player.w / 2 + 10, -20);
        ctx.stroke();
      }

      ctx.restore();
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(0,0,0,0.15)";
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorldBounds();
      drawPlatforms();
      drawPlayer();

      ctx.fillStyle = "rgba(0,0,0,0.5)";
