- Physics simulation:
  - gravity
  - horizontal movement
  - jumping
  - collision with platforms
- Simple sprite animation:
  - idle
  - run
  - jump
- Camera follow
- Collectibles and a goal

Save as `index.html` and open in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    #ui {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="ui">
    Arrow keys / A,D to move<br>
    Space / W / Up to jump
    <div id="score">Coins: 0</div>
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const scoreEl = document.getElementById("score");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const GRAVITY = 0.7;
    const FRICTION = 0.8;
    const MOVE_SPEED = 0.8;
    const MAX_SPEED_X = 6;
    const JUMP_FORCE = -14;

    const world = {
      width: 2400,
      height: 1200
    };

    const camera = {
      x: 0,
      y: 0
    };

    const platforms = [
      { x: 0, y: 550, w: 500, h: 50 },
      { x: 560, y: 480, w: 180, h: 24 },
      { x: 820, y: 420, w: 180, h: 24 },
      { x: 1080, y: 360, w: 180, h: 24 },
      { x: 1360, y: 440, w: 220, h: 24 },
      { x: 1660, y: 520, w: 260, h: 24 },
      { x: 2000, y: 460, w: 300, h: 24 },
      { x: 300, y: 300, w: 140, h: 20 },
      { x: 520, y: 240, w: 140, h: 20 },
      { x: 0, y: 700, w: 2400, h: 80 }
    ];

    const coins = [
      { x: 620, y: 440, r: 10, collected: false },
      { x: 880, y: 380, r: 10, collected: false },
      { x: 1140, y: 320, r: 10, collected: false },
      { x: 1450, y: 400, r: 10, collected: false },
      { x: 1750, y: 480, r: 10, collected: false },
      { x: 2140, y: 420, r: 10, collected: false }
    ];

    const goal = { x: 2250, y: 380, w: 30, h: 80 };

    const player = {
      x: 80,
      y: 450,
      w: 36,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      score: 0,
      state: "idle",
      animTime: 0
    };

    function rectIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectIntersect(circle, rect) {
      const closestX = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const closestY = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - closestX;
      const dy = circle.y - closestY;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function updatePlayer() {
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_SPEED;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_SPEED;
        player.facing = 1;
      }

      player.vx *= FRICTION;
      player.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, player.vx));

      if (jump && player.onGround) {
        player.vy = JUMP_FORCE;
        player.onGround = false;
      }

      player.vy += GRAVITY;

      // Horizontal move
      player.x += player.vx;
      for (const p of platforms) {
        if (rectIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical move
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }
      if (player.y > world.height) {
        // respawn
        player.x = 80;
        player.y = 450;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }
      player.animTime += 0.15;

      // Coins
      for (const coin of coins) {
        if (!coin.collected && circleRectIntersect(coin, player)) {
          coin.collected = true;
          player.score++;
          scoreEl.textContent = "Coins: " + player.score;
        }
      }

      // Goal
      if (rectIntersect(player, goal)) {
        alert("You win! Collected " + player.score + " coins.");
        window.location.reload();
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawBackground() {
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // parallax hills
      ctx.save();
      ctx.translate(-camera.x * 0.3, -camera.y * 0.1);
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        ctx.beginPath();
        ctx.arc(i * 350 + 100, 650, 180, Math.PI, 0);
        ctx.fill();
      }
      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
        ctx.fillStyle = "#4caf50";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
      }
    }

    function drawCoins() {
      for (const coin of coins) {
        if (coin.collected) continue;
        const bob = Math.sin(performance.now() * 0.01 + coin.x) * 3;
        ctx.beginPath();
        ctx.fillStyle = "gold";
        ctx.arc(coin.x - camera.x, coin.y - camera.y + bob, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c99700";
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    }

    function drawGoal() {
      const x = goal.x - camera.x;
      const y = goal.y - camera.y;
      ctx.fillStyle = "#444";
      ctx.fillRect(x, y, 6, goal.h);
      ctx.fillStyle = "#ff4d6d";
      ctx.beginPath();
      ctx.moveTo(x + 6, y);
      ctx.lineTo(x + 40, y + 15);
      ctx.lineTo(x + 6, y + 30);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // simple sprite animation using body part offsets/colors
      let legOffset = 0;
      let armOffset = 0;
      let bodyColor = "#ffcc66";

      if (player.state === "run") {
        legOffset = Math.sin(player.animTime * 10) * 6;
        armOffset = Math.cos(player.animTime * 10) * 6;
        bodyColor = "#ffd166";
      } else if (player.state === "jump") {
        legOffset = -4;
        armOffset = 8;
        bodyColor = "#f4a261";
      } else {
        legOffset = Math.sin(player.animTime * 2) * 1.5;
        armOffset = 0;
        bodyColor = "#ffcc66";
      }

      // head
      ctx.fillStyle = "#f2d3b1";
      ctx.beginPath();
      ctx.arc(0, -12, 10, 0, Math.PI * 2);
      ctx.fill();

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(-10, -2, 20, 22);

      // arms
      ctx.strokeStyle = "#f2d3b1";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-8, 4);
      ctx.lineTo(-16, 10 + armOffset);
      ctx.moveTo(8, 4);
      ctx.lineTo(16, 10 - armOffset);
      ctx.stroke();

      // legs
      ctx.beginPath();
      ctx.moveTo(-5, 20);
      ctx.lineTo(-8, 32 + legOffset);
      ctx.moveTo(5, 20);
      ctx.lineTo(8, 32 - legOffset);
      ctx.stroke();

      // eye
      ctx.fillStyle = "#222";
      ctx.beginPath();
      ctx.arc(4, -14, 1.5, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    function drawWorld() {
      drawBackground();
      drawPlatforms();
      drawCoins();
      drawGoal();
      drawPlayer();
    }

    function loop() {
      updatePlayer();
      updateCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawWorld();

      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
