<body>
  <div id="ui">
    Arrow keys / A,D to move, Space / W / Up to jump
    <div id="status">Coins: 0 | Goal: not reached</div>
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const GRAVITY = 1800;
    const FRICTION = 0.82;
    const MOVE_ACCEL = 1800;
    const MAX_SPEED_X = 260;
    const JUMP_VELOCITY = -620;
    const TILE = 48;

    const world = {
      width: 2800,
      height: 1200,
      platforms: [
        { x: 0, y: 500, w: 600, h: 80 },
        { x: 650, y: 430, w: 180, h: 30 },
        { x: 900, y: 360, w: 180, h: 30 },
        { x: 1180, y: 300, w: 180, h: 30 },
        { x: 1450, y: 420, w: 240, h: 30 },
        { x: 1760, y: 520, w: 500, h: 60 },
        { x: 2300, y: 450, w: 220, h: 30 },
        { x: 2550, y: 380, w: 180, h: 30 },

        // ground segments
        { x: 0, y: 580, w: 900, h: 200 },
        { x: 1050, y: 580, w: 650, h: 200 },
        { x: 1850, y: 580, w: 950, h: 200 }
      ],
      coins: [
        { x: 730, y: 380, r: 12, collected: false },
        { x: 980, y: 310, r: 12, collected: false },
        { x: 1260, y: 250, r: 12, collected: false },
        { x: 1530, y: 370, r: 12, collected: false },
        { x: 2380, y: 400, r: 12, collected: false }
      ],
      goal: { x: 2680, y: 300, w: 24, h: 80 }
    };

    const player = {
      x: 80,
      y: 300,
      w: 34,
      h: 46,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      coins: 0,
      reachedGoal: false,
      animTime: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function circleRectOverlap(circle, rect) {
      const closestX = clamp(circle.x, rect.x, rect.x + rect.w);
      const closestY = clamp(circle.y, rect.y, rect.y + rect.h);
      const dx = circle.x - closestX;
      const dy = circle.y - closestY;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function update(dt) {
      // Input
      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }
      if (!left && !right && player.onGround) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 4) player.vx = 0;
      }

      player.vx = clamp(player.vx, -MAX_SPEED_X, MAX_SPEED_X);

      if (jump && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;

      // Horizontal move + collision
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical move + collision
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Fall reset
      if (player.y > world.height) {
        player.x = 80;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Coins
      for (const coin of world.coins) {
        if (!coin.collected && circleRectOverlap(coin, player)) {
          coin.collected = true;
          player.coins++;
        }
      }

      // Goal
      if (rectsOverlap(player, world.goal)) {
        player.reachedGoal = true;
      }

      // Animation timer
      player.animTime += dt;

      // Camera follows player
      camera.x = clamp(player.x - canvas.width / 2 + player.w / 2, 0, world.width - canvas.width);
      camera.y = clamp(player.y - canvas.height / 2 + player.h / 2, 0, world.height - canvas.height);

      statusEl.textContent = `Coins: ${player.coins} | Goal: ${player.reachedGoal ? "reached" : "not reached"}`;
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#9bd18b";
      for (let i = 0; i < 8; i++) {
        const x = i * 420 - (camera.x * 0.2 % 420);
        ctx.beginPath();
        ctx.arc(x, 520, 180, Math.PI, 0);
        ctx.fill();
      }

      ctx.fillStyle = "#79b96b";
      for (let i = 0; i < 10; i++) {
        const x = i * 320 - (camera.x * 0.35 % 320);
        ctx.beginPath();
        ctx.arc(x, 560, 140, Math.PI, 0);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of world.platforms) {
        ctx.fillStyle = "#6b4f3a";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 10);

        // simple tile lines
        ctx.strokeStyle = "rgba(0,0,0,0.15)";
        for (let x = 0; x < p.w; x += TILE) {
          ctx.beginPath();
          ctx.moveTo(p.x - camera.x + x, p.y - camera.y);
          ctx.lineTo(p.x - camera.x + x, p.y - camera.y + p.h);
          ctx.stroke();
        }
      }
    }

    function drawCoins() {
      for (const coin of world.coins) {
        if (coin.collected) continue;
        const bob = Math.sin(performance.now() * 0.005 + coin.x * 0.01) * 4;
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(coin.x - camera.x, coin.y - camera.y + bob, coin.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#e0a800";
        ctx.lineWidth = 3;
        ctx.stroke();
      }
    }

    function drawGoal() {
      const g = world.goal;
      // pole
      ctx.fillStyle = "#d8d8d8";
      ctx.fillRect(g.x - camera.x, g.y - camera.y, 4, g.h);
      // flag
      ctx.fillStyle = player.reachedGoal ? "#00e676" : "#ff5252";
      ctx.fillRect(g.x - camera.x + 4, g.y - camera.y, g.w, 20);
    }

    function drawPlayer() {
      const px = player.x - camera.x;
      const py = player.y - camera.y;

      // minimal sprite animation by frame switching
      let frame = 0;
      if (!player.onGround) {
        frame = 2; // jump frame
      } else if (Math.abs(player.vx) > 20) {
        frame = Math.floor(player.animTime * 10) % 2; // run frames 0/1
      } else {
        frame = 0; // idle
      }

      ctx.save();
      ctx.translate(px + player.w / 2, py + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // body
      ctx.fillStyle = frame === 2 ? "#ff8a65" : "#ff7043";
      ctx.fillRect(6, 8, 22, 24);

      // head
      ctx.fillStyle = "#ffcc80";
      ctx.fillRect(8, 0, 18, 14);

      // eye
      ctx.fillStyle = "#222";
      ctx.fillRect(18, 4, 3, 3);

      // legs animated
      ctx.fillStyle = "#3949ab";
      if (frame === 0) {
        ctx.fillRect(8, 32, 7, 14);
        ctx.fillRect(19, 32, 7, 14);
      } else if (frame === 1) {
        ctx.fillRect(7, 31, 7, 15);
        ctx.fillRect(20, 33, 7, 13);
      } else {
        ctx.fillRect(9, 32, 7, 12);
        ctx.fillRect(18, 32, 7, 12);
      }

      // arm
      ctx.fillStyle = "#ffcc80";
      if (frame === 1) {
        ctx.fillRect(2, 14, 6, 12);
      } else {
        ctx.fillRect(1, 16, 6, 10);
      }

      ctx.restore();
    }

    function drawWorldBounds() {
      // optional subtle border
      ctx.strokeStyle = "rgba(0,0,0,0.08)";
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorldBounds();
      drawPlatforms();
      drawCoins();
      drawGoal();
      drawPlayer();

      if (player.reachedGoal) {
        ctx.fillStyle = "rgba(0,0,0,0.45)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 42px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You reached the goal!", canvas.width / 2, canvas.height / 2);
        ctx.font = "24px sans-serif";
        ctx.fillText(`Coins collected: ${player.coins}/${world.coins.length}`, canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;
      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
