      top: 10px;
      left: 10px;
      background: rgba(255,255,255,0.85);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hint">Move: ← → or A D | Jump: Space / W / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "arrowdown", "arrowleft", "arrowright"].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });
    addEventListener("keyup", e => {
      keys[e.key.toLowerCase()] = false;
    });

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function rectsIntersect(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    // Generate a tiny sprite sheet dynamically:
    // 4 frames: idle1, idle2, run1, run2
    function createPlayerSpriteSheet() {
      const frameW = 24;
      const frameH = 32;
      const frames = 4;
      const sheet = document.createElement("canvas");
      sheet.width = frameW * frames;
      sheet.height = frameH;
      const sctx = sheet.getContext("2d");

      function drawFrame(offsetX, legOffset, armOffset, eyeShift) {
        // transparent bg
        // body
        sctx.fillStyle = "#2d5bff";
        sctx.fillRect(offsetX + 7, 8, 10, 12);

        // head
        sctx.fillStyle = "#ffd6a5";
        sctx.fillRect(offsetX + 6, 0, 12, 10);

        // eyes
        sctx.fillStyle = "#111";
        sctx.fillRect(offsetX + 9 + eyeShift, 3, 1, 1);
        sctx.fillRect(offsetX + 13 + eyeShift, 3, 1, 1);

        // arms
        sctx.fillStyle = "#ffd6a5";
        sctx.fillRect(offsetX + 4, 10 + armOffset, 3, 8);
        sctx.fillRect(offsetX + 17, 10 - armOffset, 3, 8);

        // legs
        sctx.fillStyle = "#333";
        sctx.fillRect(offsetX + 8, 20, 3, 10 + legOffset);
        sctx.fillRect(offsetX + 13, 20, 3, 10 - legOffset);
      }

      drawFrame(0, 0, 0, 0);   // idle 1
      drawFrame(24, 1, 0, 0);  // idle 2
      drawFrame(48, 3, 2, 1);  // run 1
      drawFrame(72, -3, -2, 1);// run 2

      return { image: sheet, frameW, frameH, frames };
    }

    const playerSheet = createPlayerSpriteSheet();

    const world = {
      width: 2400,
      height: 1200,
      gravity: 1800,
      platforms: [
        { x: 0, y: 500, w: 600, h: 40 },
        { x: 650, y: 430, w: 180, h: 30 },
        { x: 900, y: 360, w: 180, h: 30 },
        { x: 1150, y: 300, w: 180, h: 30 },
        { x: 1450, y: 420, w: 220, h: 30 },
        { x: 1750, y: 500, w: 500, h: 40 },
        { x: 300, y: 380, w: 120, h: 24 },
        { x: 450, y: 320, w: 120, h: 24 },
      ],
      goal: { x: 2140, y: 440, w: 24, h: 60 }
    };

    const player = {
      x: 80,
      y: 200,
      w: 24,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 320,
      jump: 700,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    let last = performance.now();
    let won = false;

    function update(dt) {
      if (won) return;

      // Horizontal input
      let move = 0;
      if (keys["arrowleft"] || keys["a"]) move -= 1;
      if (keys["arrowright"] || keys["d"]) move += 1;

      player.vx = move * player.speed;
      if (move !== 0) player.facing = move;

      // Jump
      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jump;
        player.onGround = false;
      }

      // Gravity
      player.vy += world.gravity * dt;

      // Horizontal move
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
        }
      }

      // Vertical move
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Respawn if fallen
      if (player.y > world.height) {
        player.x = 80;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Goal
      if (rectsIntersect(player, world.goal)) {
        won = true;
      }

      // Animation
      player.animTime += dt;
      if (!player.onGround) {
        player.frame = 2;
      } else if (Math.abs(player.vx) > 1) {
        player.frame = (Math.floor(player.animTime * 10) % 2) + 2; // run frames 2,3
      } else {
        player.frame = Math.floor(player.animTime * 2) % 2; // idle frames 0,1
      }

      // Camera follow
      camera.x = clamp(player.x + player.w / 2 - canvas.width / 2, 0, world.width - canvas.width);
      camera.y = clamp(player.y + player.h / 2 - canvas.height / 2, 0, world.height - canvas.height);
    }

    function drawPlayer() {
      const sx = player.frame * playerSheet.frameW;
      const sy = 0;
      const dx = Math.floor(player.x - camera.x);
      const dy = Math.floor(player.y - camera.y);

      ctx.save();
      if (player.facing < 0) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(
          playerSheet.image,
          sx, sy, playerSheet.frameW, playerSheet.frameH,
          0, 0, player.w, player.h
        );
      } else {
        ctx.drawImage(
          playerSheet.image,
          sx, sy, playerSheet.frameW, playerSheet.frameH,
          dx, dy, player.w, player.h
        );
      }
      ctx.restore();
    }

    function draw() {
      // Sky
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Parallax hills
      ctx.fillStyle = "#9bd18b";
      ctx.fillRect(0, 420, canvas.width, 120);

      ctx.save();
      ctx.translate(-camera.x * 0.3, 0);
      ctx.fillStyle = "#7fbe6a";
      for (let i = 0; i < 10; i++) {
        ctx.beginPath();
        ctx.arc(i * 260 + 100, 460, 120, Math.PI, 0);
        ctx.fill();
      }
      ctx.restore();

      // World platforms
      for (const p of world.platforms) {
        const x = Math.floor(p.x - camera.x);
        const y = Math.floor(p.y - camera.y);

        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(x, y, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(x, y, p.w, 8);
      }

      // Goal flag
      const g = world.goal;
      const gx = Math.floor(g.x - camera.x);
      const gy = Math.floor(g.y - camera.y);

      ctx.fillStyle = "#555";
      ctx.fillRect(gx, gy, 4, g.h);
      ctx.fillStyle = "#ff3b3b";
      ctx.fillRect(gx + 4, gy, 20, 14);

      drawPlayer();

      // UI
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 36, 220, 26);
      ctx.fillStyle = "#fff";
      ctx.font = "16px sans-serif";
      ctx.fillText("Reach the red flag", 20, canvas.height - 18);

      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 42px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 36);
        ctx.textAlign = "left";
      }
    }

    function loop(now) {
      const dt = Math.min((now - last) / 1000, 1 / 30);
      last = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

