## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
      font-family: Arial, sans-serif;
    }

    #app {
      width: 100%;
      height: 100%;
    }

    .info {
      position: absolute;
      top: 12px;
      left: 12px;
      color: white;
      background: rgba(0, 0, 0, 0.45);
      padding: 10px 14px;
      border-radius: 8px;
      z-index: 10;
      font-size: 14px;
      line-height: 1.4;
    }
  </style>
</head>
<body>
  <div class="info">
    <strong>3D Scene Viewer</strong><br />
    Drag to orbit, scroll to zoom
  </div>
  <div id="app"></div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    const container = document.getElementById("app");

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 20, 60);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(0, 4, 10);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    container.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1.5, 0);

    // Ambient Light
    const ambientLight = new THREE.AmbientLight(0x404060, 1.2);
    scene.add(ambientLight);

    // Dynamic Point Light
    const pointLight = new THREE.PointLight(0x66ccff, 2.5, 100);
    pointLight.position.set(5, 6, 5);
    pointLight.castShadow = true;
    pointLight.shadow.mapSize.width = 1024;
    pointLight.shadow.mapSize.height = 1024;
    scene.add(pointLight);

    // Secondary colored light
    const pointLight2 = new THREE.PointLight(0xff6699, 1.8, 100);
    pointLight2.position.set(-5, 4, -5);
    scene.add(pointLight2);

    // Directional light
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(4, 10, 2);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.set(1024, 1024);
    scene.add(dirLight);

    // Floor
    const floorGeometry = new THREE.PlaneGeometry(50, 50);
    const floorMaterial = new THREE.MeshStandardMaterial({
      color: 0x111827,
      roughness: 0.85,
      metalness: 0.15
    });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // Grid helper
    const grid = new THREE.GridHelper(50, 50, 0x334155, 0x1e293b);
    grid.position.y = 0.01;
    scene.add(grid);

    // Custom shader material
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff00aa) },
        uLightPos: { value: pointLight.position.clone() }
      },
      vertexShader: `
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPosition;
        uniform float uTime;

        void main() {
          vUv = uv;
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position;

          // Animated vertex displacement
          pos += normal * sin(uTime * 2.0 + position.y * 4.0 + position.x * 3.0) * 0.12;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        uniform vec3 uLightPos;

        void main() {
          // Gradient blend
          float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0 + vUv.x * 6.0);
          vec3 baseColor = mix(uColorA, uColorB, wave);

          // Simple diffuse lighting
          vec3 lightDir = normalize(uLightPos - vWorldPosition);
          float diff = max(dot(normalize(vNormal), lightDir), 0.0);

          // Fresnel-like edge glow
          vec3 viewDir = normalize(cameraPosition - vWorldPosition);
          float fresnel = pow(1.0 - max(dot(normalize(vNormal), viewDir), 0.0), 3.0);

          vec3 color = baseColor * (0.25 + diff * 1.2);
          color += fresnel * vec3(0.8, 0.9, 1.0);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Main object
    const sphereGeometry = new THREE.SphereGeometry(1.5, 128, 128);
    const sphere = new THREE.Mesh(sphereGeometry, shaderMaterial);
    sphere.position.set(0, 2, 0);
    sphere.castShadow = true;
    scene.add(sphere);

    // Additional standard objects
    const boxMaterial = new THREE.MeshStandardMaterial({
      color: 0x22c55e,
      roughness: 0.4,
      metalness: 0.5
    });

    const box = new THREE.Mesh(new THREE.BoxGeometry(1.5, 1.5, 1.5), boxMaterial);
    box.position.set(-3, 1, 1);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    const torusMaterial = new THREE.MeshStandardMaterial({
      color: 0xf59e0b,
      roughness: 0.25,
      metalness: 0.8
    });

    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.3, 128, 24),
      torusMaterial
    );
    torus.position.set(3, 2, -1);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);

    // Light indicators
    const lightMarker1 = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x66ccff })
    );
    scene.add(lightMarker1);

    const lightMarker2 = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0xff6699 })
    );
    scene.add(lightMarker2);

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate lights
      pointLight.position.x = Math.cos(elapsed) * 6.0;
      pointLight.position.z = Math.sin(elapsed) * 6.0;
      pointLight.position.y = 4.0 + Math.sin(elapsed * 2.0) * 2.0;

      pointLight2.position.x = Math.cos(-elapsed * 0.7) * 5.0;
      pointLight2.position.z = Math.sin(-elapsed * 0.7) * 5.0;
      pointLight2.position.y = 3.0 + Math.cos(elapsed * 1.5) * 1.5;

      lightMarker1.position.copy(pointLight.position);
      lightMarker2.position.copy(pointLight2.position);

      // Update shader uniforms
      shaderMaterial.uniforms.uTime.value = elapsed;
      shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

      // Animate objects
      sphere.rotation.y += 0.003;
      box.rotation.x += 0.01;
      box.rotation.y += 0.015;
      torus.rotation.x += 0.008;
      torus.rotation.y += 0.012;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
