        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;
        varying vec3 vNormalW;

        void main() {
          float mixValue = 0.5 + 0.5 * sin(uTime + vUv.y * 8.0 + vWave * 10.0);
          vec3 baseColor = mix(uColorA, uColorB, mixValue);

          vec3 lightDir = normalize(vec3(0.5, 1.0, 0.3));
          float diffuse = max(dot(normalize(vNormalW), lightDir), 0.0);

          float glow = 0.35 + 0.65 * abs(vWave) * 3.0;
          vec3 color = baseColor * (0.3 + diffuse * 0.9) + baseColor * glow * 0.25;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const centralMesh = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.5, 0.45, 256, 32),
      shaderMaterial
    );
    centralMesh.position.set(0, 2.5, 0);
    centralMesh.castShadow = true;
    centralMesh.receiveShadow = true;
    scene.add(centralMesh);

    // Surrounding objects
    const objects = [];
    const standardGeometries = [
      new THREE.BoxGeometry(1.2, 1.2, 1.2),
      new THREE.SphereGeometry(0.7, 32, 32),
      new THREE.ConeGeometry(0.7, 1.5, 32),
      new THREE.TorusGeometry(0.7, 0.25, 16, 64)
    ];

    for (let i = 0; i < 20; i++) {
      const geometry = standardGeometries[i % standardGeometries.length];
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(i / 20, 0.7, 0.55),
        roughness: 0.35,
        metalness: 0.7
      });

      const mesh = new THREE.Mesh(geometry, material);
      const angle = (i / 20) * Math.PI * 2;
      const radius = 6 + (i % 3) * 2;

      mesh.position.set(
        Math.cos(angle) * radius,
        0.8 + (i % 4) * 0.4,
        Math.sin(angle) * radius
      );

      mesh.rotation.set(
        Math.random() * Math.PI,
        Math.random() * Math.PI,
        0
      );

      mesh.castShadow = true;
      mesh.receiveShadow = true;
      scene.add(mesh);
      objects.push(mesh);
    }

    // Animated emissive sphere
    const energySphereMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0x2266ff,
      emissiveIntensity: 2.5,
      roughness: 0.2,
      metalness: 0.1
    });

    const energySphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 32, 32),
      energySphereMaterial
    );
    energySphere.castShadow = true;
    scene.add(energySphere);

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Animate central mesh
      centralMesh.rotation.x = elapsed * 0.3;
      centralMesh.rotation.y = elapsed * 0.6;

      // Orbiting point light
      pointLight.position.x = Math.cos(elapsed * 1.2) * 8;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 8;
      pointLight.position.y = 4 + Math.sin(elapsed * 2.0) * 2.0;
      pointLightHelperMesh.position.copy(pointLight.position);

      // Animate energy sphere
      energySphere.position.set(
        Math.cos(elapsed * 0.8) * 3,
        1.5 + Math.sin(elapsed * 3.0) * 0.8,
        Math.sin(elapsed * 0.8) * 3
      );

      // Animate surrounding objects
      objects.forEach((obj, i) => {
        obj.rotation.x += 0.005 + i * 0.0002;
        obj.rotation.y += 0.01 + i * 0.0003;
        obj.position.y = 1 + Math.sin(elapsed * 1.5 + i) * 0.5;
      });

      // Pulse directional light intensity
      dirLight.intensity = 1.6 + Math.sin(elapsed * 0.7) * 0.5;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
