    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
      font-family: Arial, sans-serif;
    }

    #info {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      z-index: 10;
      background: rgba(0,0,0,0.4);
      padding: 10px 14px;
      border-radius: 8px;
      font-size: 14px;
    }

    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <div id="info">
    Real-Time 3D Scene Viewer<br />
    Mouse: Rotate / Zoom / Pan
  </div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050510);
    scene.fog = new THREE.Fog(0x050510, 15, 60);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(0, 5, 14);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404060, 1.2);
    scene.add(ambientLight);

    // Directional light
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Moving point light
    const pointLight = new THREE.PointLight(0x44aaff, 40, 100, 2);
    pointLight.position.set(0, 4, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    const pointLightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(pointLightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(100, 100),
      new THREE.MeshStandardMaterial({
        color: 0x1a1a22,
        metalness: 0.2,
        roughness: 0.8
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Standard objects
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        metalness: 0.6,
        roughness: 0.2
      })
    );
    sphere.position.set(-3, 0, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(2, 2, 2),
      new THREE.MeshStandardMaterial({
        color: 0x44ff88,
        metalness: 0.3,
        roughness: 0.4
      })
    );
    box.position.set(3, 0, 0);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    // Custom shader object
    const shaderUniforms = {
      uTime: { value: 0.0 },
      uColorA: { value: new THREE.Color(0x6a5cff) },
      uColorB: { value: new THREE.Color(0x00d4ff) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          vUv = uv;

          vec3 pos = position;
          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                     + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;

          pos += normal * wave;
          vWave = wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          float mixVal = vUv.y + vWave * 1.5 + pulse * 0.2;

          vec3 color = mix(uColorA, uColorB, smoothstep(0.0, 1.0, mixVal));
          float glow = 0.7 + 0.3 * sin(uTime * 3.0 + vUv.x * 12.0);

          gl_FragColor = vec4(color * glow, 1.0);
        }
      `
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.2, 0.35, 200, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 1.5, -4);
    shaderMesh.castShadow = true;
    shaderMesh.receiveShadow = true;
    scene.add(shaderMesh);

    // Extra decorative objects
    const smallObjects = [];
    const geo = new THREE.IcosahedronGeometry(0.35, 0);
    for (let i = 0; i < 30; i++) {
      const mat = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(i / 30, 0.7, 0.5),
        metalness: 0.5,
        roughness: 0.4
      });

      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(
        (Math.random() - 0.5) * 20,
        Math.random() * 6 - 1,
        (Math.random() - 0.5) * 20
      );
      mesh.rotation.set(
        Math.random() * Math.PI,
        Math.random() * Math.PI,
        Math.random() * Math.PI
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      scene.add(mesh);
      smallObjects.push(mesh);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate main objects
      sphere.rotation.y += 0.01;
      sphere.position.y = Math.sin(elapsed * 1.5) * 0.5;

      box.rotation.x += 0.01;
      box.rotation.y += 0.015;
      box.position.y = Math.cos(elapsed * 1.2) * 0.4;

      shaderMesh.rotation.x = elapsed * 0.3;
      shaderMesh.rotation.y = elapsed * 0.7;
      shaderUniforms.uTime.value = elapsed;

      // Animate point light in a circle
      pointLight.position.x = Math.cos(elapsed) * 6;
      pointLight.position.z = Math.sin(elapsed) * 6;
      pointLight.position.y = 3 + Math.sin(elapsed * 2.0) * 1.5;
      pointLightSphere.position.copy(pointLight.position);

      // Animate decorative objects
      smallObjects.forEach((obj, i) => {
        obj.rotation.x += 0.005 + i * 0.0001;
        obj.rotation.y += 0.007 + i * 0.0001;
        obj.position.y += Math.sin(elapsed + i) * 0.002;
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
