          vUv = uv;
          vec3 pos = position;

          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.2
                     + cos(pos.y * 4.0 + uTime * 1.5) * 0.2;

          pos += normal * wave;
          vWave = wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vUv.y * 10.0);
          float mixVal = 0.5 + vWave * 1.5 + pulse * 0.2;
          vec3 color = mix(uColorA, uColorB, clamp(mixVal, 0.0, 1.0));

          float glow = 0.8 + abs(vWave) * 2.0;
          gl_FragColor = vec4(color * glow, 1.0);
        }
      `
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.8, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 5, -5);
    scene.add(shaderMesh);

    // Extra emissive pillars
    const pillarGeometry = new THREE.CylinderGeometry(0.4, 0.4, 4, 32);
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const x = Math.cos(angle) * 10;
      const z = Math.sin(angle) * 10;

      const pillar = new THREE.Mesh(
        pillarGeometry,
        new THREE.MeshStandardMaterial({
          color: new THREE.Color().setHSL(i / 6, 0.8, 0.5),
          emissive: new THREE.Color().setHSL(i / 6, 0.8, 0.2),
          roughness: 0.5,
          metalness: 0.4
        })
      );
      pillar.position.set(x, 2, z);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    }

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate standard objects
      box.rotation.x = elapsed * 0.7;
      box.rotation.y = elapsed * 1.1;

      sphere.position.y = 1.5 + Math.sin(elapsed * 2.0) * 0.5;
      sphere.rotation.y = elapsed * 0.8;

      torus.rotation.x = elapsed * 0.9;
      torus.rotation.y = elapsed * 1.3;

      // Animate shader
      shaderUniforms.uTime.value = elapsed;
      shaderMesh.rotation.y += 0.01;
      shaderMesh.rotation.x += 0.005;

      // Dynamic moving light
      pointLight.position.x = Math.cos(elapsed) * 6;
      pointLight.position.z = Math.sin(elapsed) * 6;
      pointLight.position.y = 4 + Math.sin(elapsed * 2.0) * 2.0;

      lightSphere.position.copy(pointLight.position);

      // Slight directional light movement
      dirLight.position.x = Math.sin(elapsed * 0.3) * 10;
      dirLight.position.z = Math.cos(elapsed * 0.3) * 10;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
