</head>
<body>
  <div class="overlay">
    Real-Time 3D Scene Viewer<br />
    Mouse: rotate / zoom / pan
  </div>
  <canvas id="app"></canvas>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    const canvas = document.getElementById("app");

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0b1020);
    scene.fog = new THREE.Fog(0x0b1020, 10, 45);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(6, 5, 10);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1.5, 0);

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404060, 1.2);
    scene.add(ambientLight);

    // Directional light with shadows
    const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Moving point light
    const pointLight = new THREE.PointLight(0x44aaff, 60, 30, 2);
    pointLight.position.set(0, 4, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Light helper sphere
    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2b,
        roughness: 0.9,
        metalness: 0.1
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Standard objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 180, 32),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.25,
        metalness: 0.8
      })
    );
    torus.position.set(-2.8, 2.0, 0);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0x88ffcc,
        roughness: 0.35,
        metalness: 0.2
      })
    );
    sphere.position.set(2.8, 1.4, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Shader-driven object
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x7a5cff) },
      uColorB: { value: new THREE.Color(0x00d4ff) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vElevation;
        varying vec3 vNormalW;
        varying vec3 vPositionW;

        void main() {
          vUv = uv;

          vec3 pos = position;
          float wave1 = sin(pos.x * 4.0 + uTime * 1.8) * 0.15;
          float wave2 = cos(pos.y * 5.0 + uTime * 1.4) * 0.12;
          float wave3 = sin((pos.x + pos.y) * 3.0 + uTime * 2.2) * 0.08;

          pos += normal * (wave1 + wave2 + wave3);
          vElevation = wave1 + wave2 + wave3;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vPositionW = worldPos.xyz;
          vNormalW = normalize(mat3(modelMatrix) * normal);

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vElevation;
        varying vec3 vNormalW;
        varying vec3 vPositionW;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 10.0);
          float mixVal = smoothstep(-0.2, 0.25, vElevation + pulse * 0.15);

          vec3 baseColor = mix(uColorA, uColorB, mixVal);

          vec3 lightDir = normalize(vec3(0.5, 1.0, 0.3));
          float diffuse = max(dot(normalize(vNormalW), lightDir), 0.0);

          float fresnel = pow(1.0 - max(dot(normalize(vNormalW), normalize(-vPositionW)), 0.0), 2.0);
          vec3 color = baseColor * (0.35 + diffuse * 0.9) + fresnel * vec3(0.8, 0.9, 1.0) * 0.5;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.4, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 2.2, -3.5);
    shaderMesh.castShadow = true;
    shaderMesh.receiveShadow = true;
    scene.add(shaderMesh);

    // Decorative pillars
    const pillarGeometry = new THREE.BoxGeometry(0.8, 3, 0.8);
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x8899aa,
      roughness: 0.7,
      metalness: 0.15
    });

    for (let i = 0; i < 8; i++) {
      const pillar = new THREE.Mesh(pillarGeometry, pillarMaterial);
      const angle = (i / 8) * Math.PI * 2;
      const radius = 8;
      pillar.position.set(Math.cos(angle) * radius, 1.5, Math.sin(angle) * radius);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      const elapsed = clock.getElapsedTime();

      // Animate objects
      torus.rotation.x = elapsed * 0.5;
      torus.rotation.y = elapsed * 0.8;

      sphere.position.y = 1.4 + Math.sin(elapsed * 1.5) * 0.35;
      sphere.rotation.y = elapsed * 0.6;

      shaderMesh.rotation.y = elapsed * 0.45;
      shaderMesh.rotation.x = Math.sin(elapsed * 0.3) * 0.2;
      shaderUniforms.uTime.value = elapsed;

      // Animate point light in a circular path
      const lightRadius = 5;
      pointLight.position.x = Math.cos(elapsed * 1.2) * lightRadius;
      pointLight.position.z = Math.sin(elapsed * 1.2) * lightRadius;
      pointLight.position.y = 3.5 + Math.sin(elapsed * 2.0) * 1.0;
      lightSphere.position.copy(pointLight.position);

      // Animate directional light slightly
      dirLight.position.x = 5 + Math.sin(elapsed * 0.4) * 3;
      dirLight.position.z = 7 + Math.cos(elapsed * 0.4) * 3;

      controls.update();
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
