      font-size: 14px;
    }

    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <div id="info">
    Real-Time 3D Scene Viewer<br />
    Mouse: rotate / zoom / pan
  </div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';
    import { EffectComposer } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js';
    import { RenderPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js';
    import { UnrealBloomPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js';

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.1;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 15, 60);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      200
    );
    camera.position.set(8, 6, 12);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 2, 0);

    // Postprocessing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.8,
      0.4,
      0.85
    );
    composer.addPass(bloomPass);

    // Lights
    const ambientLight = new THREE.AmbientLight(0x406080, 0.5);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.8);
    directionalLight.position.set(8, 12, 6);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.set(2048, 2048);
    directionalLight.shadow.camera.left = -20;
    directionalLight.shadow.camera.right = 20;
    directionalLight.shadow.camera.top = 20;
    directionalLight.shadow.camera.bottom = -20;
    directionalLight.shadow.camera.near = 1;
    directionalLight.shadow.camera.far = 50;
    scene.add(directionalLight);

    const pointLight = new THREE.PointLight(0x44aaff, 30, 50, 2);
    pointLight.position.set(0, 4, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(100, 100),
      new THREE.MeshStandardMaterial({
        color: 0x111827,
        roughness: 0.85,
        metalness: 0.15
      })
    );
    ground.rotation.x = -Math.PI * 0.5;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid helper
    const grid = new THREE.GridHelper(100, 100, 0x335577, 0x223344);
    grid.position.y = 0.01;
    scene.add(grid);

    // Custom shader material
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vElevation;

        void main() {
          vUv = uv;
          vec3 pos = position;

          float wave1 = sin(pos.x * 3.0 + uTime * 2.0) * 0.2;
          float wave2 = cos(pos.y * 4.0 + uTime * 1.5) * 0.2;
          pos.z += wave1 + wave2;

          vElevation = pos.z;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec2 vUv;
        varying float vElevation;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 10.0);
          float mixStrength = smoothstep(-0.3, 0.3, vElevation + pulse * 0.2);
          vec3 color = mix(uColorA, uColorB, mixStrength);

          float glow = 0.7 + 0.3 * sin(uTime * 3.0 + vUv.y * 20.0);
          gl_FragColor = vec4(color * glow, 1.0);
        }
      `,
      side: THREE.DoubleSide
    });

    const shaderPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(6, 6, 128, 128),
      shaderMaterial
    );
    shaderPlane.rotation.x = -Math.PI * 0.5;
    shaderPlane.position.set(0, 2.5, 0);
    scene.add(shaderPlane);

    // Central reflective object
    const centerSphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.5, 64, 64),
      new THREE.MeshPhysicalMaterial({
        color: 0xffffff,
        metalness: 0.8,
        roughness: 0.15,
        clearcoat: 1.0,
        clearcoatRoughness: 0.1,
        emissive: 0x112244,
        emissiveIntensity: 0.4
      })
    );
    centerSphere.position.set(0, 2, 0);
    centerSphere.castShadow = true;
    centerSphere.receiveShadow = true;
    scene.add(centerSphere);

    // Animated torus knots
    const objects = [];
    const knotGeometry = new THREE.TorusKnotGeometry(0.6, 0.2, 128, 16);

    for (let i = 0; i < 8; i++) {
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(i / 8, 0.8, 0.55),
        emissive: new THREE.Color().setHSL(i / 8, 0.8, 0.2),
        emissiveIntensity: 0.5,
        metalness: 0.5,
        roughness: 0.25
      });

      const mesh = new THREE.Mesh(knotGeometry, material);
      const angle = (i / 8) * Math.PI * 2;
      mesh.position.set(
        Math.cos(angle) * 5,
        1.5 + Math.sin(i) * 0.5,
        Math.sin(angle) * 5
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      scene.add(mesh);
      objects.push({ mesh, angleOffset: angle });
    }

    // Particle field
    const particleCount = 1500;
    const particlePositions = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 40;
      particlePositions[i * 3 + 1] = Math.random() * 20 + 2;
      particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 40;
    }

    const particleGeometry = new THREE.BufferGeometry();
    particleGeometry.setAttribute(
      'position',
      new THREE.BufferAttribute(particlePositions, 3)
    );

    const particleMaterial = new THREE.PointsMaterial({
      color: 0x88ccff,
      size: 0.06,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    });

    const particles = new THREE.Points(particleGeometry, particleMaterial);
    scene.add(particles);

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Update shader time
      shaderUniforms.uTime.value = elapsed;

      // Dynamic point light motion
      pointLight.position.x = Math.cos(elapsed * 1.2) * 4;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 4;
      pointLight.position.y = 3 + Math.sin(elapsed * 2.0) * 1.5;
      pointLight.intensity = 20 + Math.sin(elapsed * 3.0) * 8;

      // Animate center sphere
      centerSphere.rotation.y += 0.01;
      centerSphere.position.y = 2 + Math.sin(elapsed * 1.5) * 0.25;

      // Animate orbiting objects
      objects.forEach((obj, i) => {
        const t = elapsed * 0.5 + obj.angleOffset;
        obj.mesh.position.x = Math.cos(t) * (5 + Math.sin(elapsed + i) * 0.3);
        obj.mesh.position.z = Math.sin(t) * (5 + Math.cos(elapsed + i) * 0.3);
        obj.mesh.position.y = 1.5 + Math.sin(elapsed * 2 + i) * 0.8;
        obj.mesh.rotation.x += 0.01 + i * 0.001;
        obj.mesh.rotation.y += 0.02 + i * 0.001;
      });

      // Slowly rotate particle field
      particles.rotation.y = elapsed * 0.03;

      controls.update();
      composer.render();
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
