      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(6, 5, 10);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    container.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1, 0);

    // Ambient Light
    const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
    scene.add(ambientLight);

    // Directional Light
    const dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Moving Point Light
    const pointLight = new THREE.PointLight(0x44aaff, 40, 100, 2);
    pointLight.position.set(0, 3, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    const pointLightHelper = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(pointLightHelper);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      new THREE.MeshStandardMaterial({
        color: 0x111827,
        roughness: 0.85,
        metalness: 0.15
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Standard objects
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.25,
        metalness: 0.6
      })
    );
    sphere.position.set(-2.5, 1.2, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.8, 1.8, 1.8),
      new THREE.MeshStandardMaterial({
        color: 0x44ddaa,
        roughness: 0.4,
        metalness: 0.3
      })
    );
    box.position.set(2.5, 0.9, -1);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);

    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.9, 0.28, 150, 20),
      new THREE.MeshStandardMaterial({
        color: 0x8888ff,
        roughness: 0.35,
        metalness: 0.75
      })
    );
    torus.position.set(0, 2.2, 2.5);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);

    // Custom shader object
    const shaderUniforms = {
      uTime: { value: 0.0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          vUv = uv;
          vec3 pos = position;

          float wave = sin(pos.y * 8.0 + uTime * 2.5) * 0.12;
          wave += cos(pos.x * 6.0 + uTime * 1.8) * 0.08;

          pos += normal * wave;
          vWave = wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          float mixVal = smoothstep(-0.15, 0.15, vWave) * 0.7 + pulse * 0.3;

          vec3 color = mix(uColorA, uColorB, mixVal);

          float glow = 0.75 + abs(vWave) * 2.5;
          gl_FragColor = vec4(color * glow, 1.0);
        }
      `
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.2, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 1.5, -3.5);
    shaderMesh.castShadow = true;
    shaderMesh.receiveShadow = true;
    scene.add(shaderMesh);

    // Decorative pillars
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x9ca3af,
      roughness: 0.7,
      metalness: 0.2
    });

    for (let i = 0; i < 8; i++) {
      const pillar = new THREE.Mesh(
        new THREE.CylinderGeometry(0.25, 0.35, 3, 24),
        pillarMaterial
      );
      const angle = (i / 8) * Math.PI * 2;
      const radius = 8;
      pillar.position.set(Math.cos(angle) * radius, 1.5, Math.sin(angle) * radius);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      controls.update();

      // Animate objects
      sphere.rotation.y += 0.01;
      box.rotation.x += 0.008;
      box.rotation.y += 0.012;
      torus.rotation.x += 0.01;
      torus.rotation.y += 0.01;

      shaderUniforms.uTime.value = elapsed;
      shaderMesh.rotation.y += 0.006;
      shaderMesh.rotation.x = Math.sin(elapsed * 0.8) * 0.2;

      // Move point light in orbit
      pointLight.position.x = Math.cos(elapsed * 1.2) * 4.0;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 4.0;
      pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
      pointLightHelper.position.copy(pointLight.position);

      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
