      const geometry = geometries[i % geometries.length];
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color().setHSL(i / 12, 0.7, 0.55),
        metalness: 0.5,
        roughness: 0.3
      });

      const mesh = new THREE.Mesh(geometry, material);
      const angle = (i / 12) * Math.PI * 2;
      const radius = 5 + (i % 3) * 1.2;

      mesh.position.set(
        Math.cos(angle) * radius,
        0.8 + (i % 2) * 0.5,
        Math.sin(angle) * radius
      );

      mesh.castShadow = true;
      mesh.receiveShadow = true;
      scene.add(mesh);
      objects.push(mesh);
    }

    // Decorative emissive pillars
    for (let i = 0; i < 6; i++) {
      const pillar = new THREE.Mesh(
        new THREE.CylinderGeometry(0.2, 0.2, 3, 24),
        new THREE.MeshStandardMaterial({
          color: 0x222a44,
          emissive: new THREE.Color().setHSL(i / 6, 1.0, 0.5),
          emissiveIntensity: 0.6,
          metalness: 0.7,
          roughness: 0.2
        })
      );
      const angle = (i / 6) * Math.PI * 2;
      pillar.position.set(Math.cos(angle) * 8, 1.5, Math.sin(angle) * 8);
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      scene.add(pillar);
    }

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();
      shaderUniforms.uTime.value = elapsed;

      // Animate center object
      centerMesh.rotation.x = elapsed * 0.35;
      centerMesh.rotation.y = elapsed * 0.6;

      // Animate orbiting point light
      pointLight.position.x = Math.cos(elapsed * 1.2) * 4.5;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 4.5;
      pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.2;

      // Animate surrounding objects
      objects.forEach((obj, i) => {
        obj.rotation.x += 0.01 + i * 0.0005;
        obj.rotation.y += 0.015 + i * 0.0007;
        obj.position.y = 0.8 + Math.sin(elapsed * 1.5 + i) * 0.25;
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
