          vec3 lightDir = normalize(vec3(1.0, 1.5, 0.5));
          float diffuse = max(dot(normalize(vNormal), lightDir), 0.0);

          float fresnel = pow(1.0 - max(dot(normalize(vNormal), normalize(-vPosition)), 0.0), 2.0);

          vec3 color = baseColor * (0.3 + diffuse * 0.7);
          color += fresnel * 0.35;

          gl_FragColor = vec4(color, 1.0);
        }
