      // Animate center object
      centerMesh.rotation.x = elapsed * 0.35;
      centerMesh.rotation.y = elapsed * 0.6;

      // Animate other objects
      sphere1.position.y = 1 + Math.sin(elapsed * 1.8) * 0.35;
      sphere2.position.y = 1 + Math.cos(elapsed * 1.5) * 0.35;
