    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const canvas = document.getElementById('app');

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0b1020);
    scene.fog = new THREE.Fog(0x0b1020, 15, 45);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(6, 5, 10);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1, 0);

    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404060, 1.2);
    scene.add(ambientLight);

    // Directional light with shadows
    const dirLight = new THREE.DirectionalLight(0xffffff, 2.2);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // Dynamic point light
    const pointLight = new THREE.PointLight(0x44aaff, 40, 30, 2);
    pointLight.position.set(0, 3, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Light helper sphere
    const lightSphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightSphere);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x1a1f2f,
        metalness: 0.2,
        roughness: 0.85
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Standard material objects
    const torusKnot = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 128, 16),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        metalness: 0.7,
        roughness: 0.2
      })
    );
    torusKnot.position.set(-2.8, 1.8, 0);
    torusKnot.castShadow = true;
    torusKnot.receiveShadow = true;
    scene.add(torusKnot);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0x66ffcc,
        metalness: 0.3,
        roughness: 0.15
      })
    );
    sphere.position.set(2.8, 1.2, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Custom shader object
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x7c3aed) },
      uColorB: { value: new THREE.Color(0x06b6d4) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;
        varying vec3 vNormalW;
        varying vec3 vPositionW;

        void main() {
          vUv = uv;

          vec3 pos = position;
          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                     + cos(pos.y * 5.0 + uTime * 1.5) * 0.1;
          pos += normal * wave;

          vWave = wave;
          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vPositionW = worldPos.xyz;
          vNormalW = normalize(mat3(modelMatrix) * normal);

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;
        varying vec3 vNormalW;
        varying vec3 vPositionW;

        void main() {
          float mixValue = 0.5 + 0.5 * sin(vUv.y * 10.0 + uTime * 2.0 + vWave * 8.0);
          vec3 baseColor = mix(uColorA, uColorB, mixValue);

          vec3 lightDir = normalize(vec3(1.0, 1.5, 0.8));
          float diffuse = max(dot(normalize(vNormalW), lightDir), 0.0);

          float fresnel = pow(1.0 - max(dot(normalize(vNormalW), normalize(-vPositionW)), 0.0), 2.5);

          vec3 color = baseColor * (0.35 + diffuse * 0.9) + fresnel * vec3(1.0, 1.0, 1.0) * 0.6;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const shaderMesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.4, 32),
      shaderMaterial
    );
    shaderMesh.position.set(0, 2.2, -3.5);
    shaderMesh.castShadow = true;
    shaderMesh.receiveShadow = true;
    scene.add(shaderMesh);

    // Extra scene elements
    const boxes = [];
    for (let i = 0; i < 20; i++) {
      const box = new THREE.Mesh(
        new THREE.BoxGeometry(0.6, 0.6, 0.6),
        new THREE.MeshStandardMaterial({
          color: new THREE.Color().setHSL(i / 20, 0.7, 0.5),
          metalness: 0.4,
          roughness: 0.4
        })
      );

      const angle = (i / 20) * Math.PI * 2;
      const radius = 6 + (i % 3) * 1.2;
      box.position.set(
        Math.cos(angle) * radius,
        0.4,
        Math.sin(angle) * radius
      );
      box.castShadow = true;
      box.receiveShadow = true;
      scene.add(box);
      boxes.push(box);
    }

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate lights
      pointLight.position.x = Math.cos(elapsed * 1.2) * 4.0;
      pointLight.position.z = Math.sin(elapsed * 1.2) * 4.0;
      pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
      lightSphere.position.copy(pointLight.position);

      dirLight.position.x = Math.sin(elapsed * 0.4) * 8.0;
      dirLight.position.z = Math.cos(elapsed * 0.4) * 8.0;

      // Animate objects
      torusKnot.rotation.x += 0.01;
      torusKnot.rotation.y += 0.015;

      sphere.position.y = 1.2 + Math.sin(elapsed * 2.5) * 0.35;
      sphere.rotation.y += 0.01;

      shaderMesh.rotation.y += 0.008;
      shaderMesh.rotation.x += 0.004;
      shaderUniforms.uTime.value = elapsed;

      boxes.forEach((box, i) => {
        box.rotation.x = elapsed * 0.5 + i * 0.1;
        box.rotation.y = elapsed * 0.8 + i * 0.15;
        box.position.y = 0.4 + Math.sin(elapsed * 2.0 + i) * 0.15;
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
