          uniform vec3 uColorB;

          varying vec3 vNormal;
          varying vec3 vPosition;
          varying vec2 vUv;

          void main() {
            vec3 normal = normalize(vNormal);
            vec3 lightDir = normalize(uLightPos - vPosition);

            float diff = max(dot(normal, lightDir), 0.0);

            float wave = 0.5 + 0.5 * sin(vUv.x * 10.0 + uTime * 3.0);
            vec3 baseColor = mix(uColorA, uColorB, wave);

            vec3 finalColor = baseColor * (0.25 + diff * 1.2);

            gl_FragColor = vec4(finalColor, 1.0);
          }
        `
      });

      const geometry = new THREE.TorusKnotGeometry(1.2, 0.4, 256, 32);
      shaderMesh = new THREE.Mesh(geometry, shaderMaterial);
      shaderMesh.position.y = 1.0;
      shaderMesh.castShadow = true;
      shaderMesh.receiveShadow = true;
      scene.add(shaderMesh);

      // Extra scene objects
      const sphere = new THREE.Mesh(
        new THREE.SphereGeometry(0.8, 32, 32),
        new THREE.MeshStandardMaterial({
          color: 0xff8844,
          roughness: 0.3,
          metalness: 0.5
        })
      );
      sphere.position.set(-3, 0, 1);
      sphere.castShadow = true;
      sphere.receiveShadow = true;
      scene.add(sphere);

      const box = new THREE.Mesh(
        new THREE.BoxGeometry(1.5, 1.5, 1.5),
        new THREE.MeshStandardMaterial({
          color: 0x66ff99,
          roughness: 0.5,
          metalness: 0.1
        })
      );
      box.position.set(3, -0.2, -1);
      box.castShadow = true;
      box.receiveShadow = true;
      scene.add(box);

      window.addEventListener('resize', onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Animate shader
      shaderMesh.material.uniforms.uTime.value = elapsed;

      // Rotate object
      shaderMesh.rotation.x += 0.003;
      shaderMesh.rotation.y += 0.006;

      // Move point light in circle
      pointLight.position.x = Math.cos(elapsed) * 4.0;
      pointLight.position.z = Math.sin(elapsed) * 4.0;
      pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;

      controls.update();
      renderer.render(scene, camera);
    }
  </script>
</body>
