    scene.add(pointLight);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(50, 50),
      new THREE.MeshStandardMaterial({
        color: 0x1b1f2a,
        roughness: 0.85,
        metalness: 0.15
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Shader material
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          vUv = uv;
          vec3 pos = position;

          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                     + cos(pos.y * 4.0 + uTime * 1.5) * 0.15;

          pos += normal * wave;
          vWave = wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying float vWave;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          vec3 color = mix(uColorA, uColorB, vUv.x + vWave + pulse * 0.25);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Central object
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1.5, 128, 128),
      shaderMaterial
    );
    sphere.position.set(0, 2, 0);
    sphere.castShadow = true;
    scene.add(sphere);

    // Additional objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.8, 0.25, 128, 32),
      new THREE.MeshStandardMaterial({
        color: 0xffaa00,
        roughness: 0.35,
        metalness: 0.8,
        emissive: 0x331100
      })
    );
    torus.position.set(-3, 1.5, -1);
    torus.castShadow = true;
    scene.add(torus);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.5, 1.5, 1.5),
      new THREE.MeshStandardMaterial({
        color: 0x66ff99,
        roughness: 0.4,
        metalness: 0.2
      })
    );
    box.position.set(3, 1, 1);
    box.castShadow = true;
    scene.add(box);

    // Small emissive marker for point light
    const lightOrb = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 24, 24),
      new THREE.MeshBasicMaterial({ color: 0x44aaff })
    );
    scene.add(lightOrb);

    // Clock
    const clock = new THREE.Clock();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();
      shaderUniforms.uTime.value = elapsed;

      // Animate objects
      sphere.rotation.y += 0.003;
      torus.rotation.x += 0.01;
      torus.rotation.y += 0.013;
      box.rotation.x += 0.008;
      box.rotation.y += 0.01;

      // Dynamic light motion
      pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
      pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;
      pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;

      lightOrb.position.copy(pointLight.position);

      // Slight directional light drift
      directionalLight.position.x = 5 + Math.sin(elapsed * 0.5) * 2.0;
      directionalLight.position.z = 5 + Math.cos(elapsed * 0.5) * 2.0;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
