  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Clock
const clock = new THREE.Clock();

// Ambient light
const ambientLight = new THREE.AmbientLight(0x405060, 1.2);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
dirLight.position.set(5, 10, 5);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(2048, 2048);
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
dirLight.shadow.camera.left = -15;
dirLight.shadow.camera.right = 15;
dirLight.shadow.camera.top = 15;
dirLight.shadow.camera.bottom = -15;
scene.add(dirLight);

// Point light with animation
const pointLight = new THREE.PointLight(0x44aaff, 30, 50, 2);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Light helper sphere
const lightSphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
pointLight.add(lightSphere);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(50, 50),
  new THREE.MeshStandardMaterial({
    color: 0x1c2333,
    roughness: 0.9,
    metalness: 0.1,
  })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Grid helper
const grid = new THREE.GridHelper(50, 50, 0x334466, 0x223344);
grid.position.y = 0.001;
scene.add(grid);

// Standard object
const torusKnot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 180, 32),
  new THREE.MeshStandardMaterial({
    color: 0x88ccff,
    roughness: 0.25,
    metalness: 0.8,
  })
);
torusKnot.position.set(-2.4, 1.5, 0);
torusKnot.castShadow = true;
torusKnot.receiveShadow = true;
scene.add(torusKnot);

// Custom shader object
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x7c3aed) },
  uColorB: { value: new THREE.Color(0x06b6d4) },
};

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.15;
      wave += cos(pos.x * 3.0 + uTime * 1.5) * 0.1;
      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      float mixValue = vUv.y + vWave * 1.5;
      vec3 color = mix(uColorA, uColorB, smoothstep(0.0, 1.0, mixValue));
      float glow = 0.5 + abs(vWave) * 2.0;
      gl_FragColor = vec4(color * glow, 1.0);
    }
  `,
});

const shaderSphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 128, 128),
  shaderMaterial
);
shaderSphere.position.set(2.4, 1.5, 0);
shaderSphere.castShadow = true;
shaderSphere.receiveShadow = true;
scene.add(shaderSphere);

// Extra objects for scene depth
for (let i = 0; i < 20; i++) {
  const box = new THREE.Mesh(
    new THREE.BoxGeometry(0.6, 0.6, 0.6),
    new THREE.MeshStandardMaterial({
      color: new THREE.Color().setHSL(0.55 + Math.random() * 0.15, 0.6, 0.5),
      roughness: 0.6,
      metalness: 0.2,
    })
  );

  box.position.set(
    (Math.random() - 0.5) * 18,
    0.3,
    (Math.random() - 0.5) * 18
  );
  box.castShadow = true;
  box.receiveShadow = true;
  scene.add(box);
}

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  controls.update();

  // Animate objects
  torusKnot.rotation.x = elapsed * 0.35;
  torusKnot.rotation.y = elapsed * 0.6;

  shaderSphere.rotation.y = elapsed * 0.4;
  shaderUniforms.uTime.value = elapsed;

  // Animate point light in a circular path
  pointLight.position.x = Math.cos(elapsed) * 4.0;
  pointLight.position.z = Math.sin(elapsed * 1.2) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.2;

  renderer.render(scene, camera);
}

animate();
