scene.fog = new THREE.Fog(0x0b0f17, 10, 45);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  1000
);
camera.position.set(8, 6, 12);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
container.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1.5, 0);

// Ambient light
const ambientLight = new THREE.AmbientLight(0x404040, 1.2);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(6, 10, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
dirLight.shadow.camera.left = -15;
dirLight.shadow.camera.right = 15;
dirLight.shadow.camera.top = 15;
dirLight.shadow.camera.bottom = -15;
scene.add(dirLight);

// Point light with animation
const pointLight = new THREE.PointLight(0x44aaff, 30, 50, 2);
pointLight.position.set(0, 4, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x1a1f2b,
  roughness: 0.85,
  metalness: 0.15,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Standard object
const boxGeo = new THREE.BoxGeometry(2, 2, 2);
const boxMat = new THREE.MeshStandardMaterial({
  color: 0xff8844,
  roughness: 0.35,
  metalness: 0.4,
});
const box = new THREE.Mesh(boxGeo, boxMat);
box.position.set(-3, 1, 0);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

// Shader object
const sphereGeo = new THREE.SphereGeometry(1.5, 64, 64);

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0.0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff00aa) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;
      vec3 pos = position;

      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.15;
      wave += cos(pos.x * 3.0 + uTime * 1.5) * 0.1;

      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      float mixValue = vUv.y + vWave * 2.0;
      vec3 color = mix(uColorA, uColorB, smoothstep(0.0, 1.0, mixValue));
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

const sphere = new THREE.Mesh(sphereGeo, shaderMaterial);
sphere.position.set(3, 2, 0);
sphere.castShadow = true;
sphere.receiveShadow = true;
scene.add(sphere);

// Decorative torus
const torusGeo = new THREE.TorusKnotGeometry(1, 0.3, 128, 16);
const torusMat = new THREE.MeshStandardMaterial({
  color: 0x88ffcc,
  roughness: 0.25,
  metalness: 0.8,
});
const torus = new THREE.Mesh(torusGeo, torusMat);
torus.position.set(0, 3, -4);
torus.castShadow = true;
torus.receiveShadow = true;
scene.add(torus);

// Small emissive marker for point light
const lightMarker = new THREE.Mesh(
  new THREE.SphereGeometry(0.15, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(lightMarker);

// Grid helper
const gridHelper = new THREE.GridHelper(50, 50, 0x334155, 0x1e293b);
scene.add(gridHelper);

// Clock
const clock = new THREE.Clock();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Animate objects
  box.rotation.x = elapsed * 0.6;
  box.rotation.y = elapsed * 0.9;

  torus.rotation.x = elapsed * 0.4;
  torus.rotation.y = elapsed * 0.7;

  sphere.rotation.y = elapsed * 0.5;
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Animate point light in a circular path
  pointLight.position.x = Math.cos(elapsed) * 5.0;
  pointLight.position.z = Math.sin(elapsed) * 5.0;
  pointLight.position.y = 3.0 + Math.sin(elapsed * 2.0) * 1.5;

  lightMarker.position.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
}

animate();
