```javascript
import * as THREE from 'https://unpkg.com/three@0.166.1/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.166.1/examples/jsm/controls/OrbitControls.js';

const canvas = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 3, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Clock
const clock = new THREE.Clock();

// Ambient light
const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
dirLight.position.set(5, 10, 7);
scene.add(dirLight);

// Point light with animated motion
const pointLight = new THREE.PointLight(0x44aaff, 30, 50, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Optional light helper
const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.2);
scene.add(pointLightHelper);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(30, 30),
  new THREE.MeshStandardMaterial({
    color: 0x1a1f2f,
    metalness: 0.1,
    roughness: 0.9,
  })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.5;
scene.add(ground);

// Background objects
const boxGroup = new THREE.Group();
scene.add(boxGroup);

for (let i = 0; i < 40; i++) {
  const box = new THREE.Mesh(
    new THREE.BoxGeometry(
      0.4 + Math.random() * 0.8,
      0.4 + Math.random() * 2.0,
      0.4 + Math.random() * 0.8
    ),
    new THREE.MeshStandardMaterial({
      color: new THREE.Color().setHSL(Math.random(), 0.4, 0.5),
      metalness: 0.2,
      roughness: 0.7,
    })
  );

  box.position.set(
    (Math.random() - 0.5) * 20,
    -1 + Math.random() * 3,
    (Math.random() - 0.5) * 20
  );

  box.rotation.set(
    Math.random() * Math.PI,
    Math.random() * Math.PI,
    0
  );

  boxGroup.add(box);
}

// Shader-driven sphere
const sphereGeometry = new THREE.SphereGeometry(1.5, 128, 128);

const sphereMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff4fd8) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave =
        sin(pos.y * 6.0 + uTime * 2.0) * 0.08 +
        sin(pos.x * 8.0 + uTime * 1.5) * 0.05;

      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
      float mixValue = vUv.y + vWave * 2.0 + pulse * 0.2;

      vec3 color = mix(uColorA, uColorB, smoothstep(0.0, 1.0, mixValue));
      float glow = 0.75 + vWave * 4.0 + pulse * 0.25;

      gl_FragColor = vec4(color * glow, 1.0);
    }
  `,
});

const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
sphere.position.y = 1.0;
scene.add(sphere);

// Torus ring
const torus = new THREE.Mesh(
  new THREE.TorusGeometry(2.4, 0.08, 32, 200),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    emissive: 0x2244ff,
    emissiveIntensity: 1.5,
    metalness: 0.8,
    roughness: 0.2,
  })
);
torus.rotation.x = Math.PI / 2;
torus.position.copy(sphere.position);
scene.add(torus);

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Update controls
  controls.update();

  // Animate shader
  sphereMaterial.uniforms.uTime.value = elapsed;

  // Animate central objects
  sphere.rotation.y = elapsed * 0.4;
  torus.rotation.z = elapsed * 0.8;

  // Animate point light
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;
  pointLight.position.y = 2.0 + Math.sin(elapsed * 2.0) * 1.0;

  // Subtle motion in background objects
  boxGroup.children.forEach((box, i) => {
    box.rotation.y += 0.002 + i * 0.00002;
  });

  renderer.render(scene, camera);
}

animate();
