## `main.js`

```javascript
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b0f1a);
scene.fog = new THREE.Fog(0x0b0f1a, 10, 50);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  1000
);
camera.position.set(6, 4, 10);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById('app').appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 2048;
directionalLight.shadow.mapSize.height = 2048;
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x44aaff, 2, 30);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

const pointLightHelper = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(pointLightHelper);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(50, 50),
  new THREE.MeshStandardMaterial({
    color: 0x1a1f2b,
    roughness: 0.9,
    metalness: 0.1
  })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.5;
ground.receiveShadow = true;
scene.add(ground);

// Grid
const grid = new THREE.GridHelper(50, 50, 0x334155, 0x1f2937);
grid.position.y = -1.49;
scene.add(grid);

// Shader uniforms
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x7c3aed) },
  uColorB: { value: new THREE.Color(0x06b6d4) }
};

// Shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;
      vec3 pos = position;

      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.15;
      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform float uTime;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float mixValue = 0.5 + 0.5 * sin(uTime + vUv.y * 8.0 + vWave * 10.0);
      vec3 color = mix(uColorA, uColorB, mixValue);
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 128, 128),
  shaderMaterial
);
sphere.position.set(-2.5, 0.2, 0);
sphere.castShadow = true;
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.8, 1.8, 1.8),
  new THREE.MeshStandardMaterial({
    color: 0xf59e0b,
    roughness: 0.4,
    metalness: 0.6
  })
);
box.position.set(2.5, 0, 0);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 128, 24),
  new THREE.MeshStandardMaterial({
    color: 0x22c55e,
    roughness: 0.3,
    metalness: 0.8
  })
);
torus.position.set(0, 1.2, -3);
torus.castShadow = true;
torus.receiveShadow = true;
scene.add(torus);

// Clock
const clock = new THREE.Clock();

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderUniforms.uTime.value = elapsed;

  // Animate objects
  sphere.rotation.y += 0.005;
  box.rotation.x += 0.01;
  box.rotation.y += 0.008;
  torus.rotation.x += 0.01;
  torus.rotation.y += 0.012;

  // Animate point light in circular path
  pointLight.position.x = Math.cos(elapsed) * 4.0;
  pointLight.position.z = Math.sin(elapsed) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
  pointLightHelper.position.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

