```javascript
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

const container = document.getElementById('app');

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 50);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  1000
);
camera.position.set(0, 3, 8);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
container.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Ambient Light
const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
scene.add(ambientLight);

// Directional Light
const directionalLight = new THREE.DirectionalLight(0xffffff, 2.0);
directionalLight.position.set(5, 10, 7);
scene.add(directionalLight);

// Moving Point Light
const pointLight = new THREE.PointLight(0x44aaff, 30, 100, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Optional helper for light visualization
const pointLightHelper = new THREE.Mesh(
  new THREE.SphereGeometry(0.1, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(pointLightHelper);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(50, 50),
  new THREE.MeshStandardMaterial({
    color: 0x1a1f2f,
    metalness: 0.2,
    roughness: 0.8
  })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1.5;
scene.add(ground);

// Shader Material
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x6a5cff) },
  uColorB: { value: new THREE.Color(0x00d4ff) }
};

const vertexShader = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vWave;

  void main() {
    vUv = uv;

    vec3 pos = position;
    float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.2
               + cos(pos.y * 4.0 + uTime * 1.5) * 0.2;
    pos.z += wave;
    vWave = wave;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
  }
`;

const fragmentShader = `
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  varying vec2 vUv;
  varying float vWave;

  void main() {
    float mixStrength = vUv.y + vWave * 0.5;
    vec3 color = mix(uColorA, uColorB, mixStrength);
    gl_FragColor = vec4(color, 1.0);
  }
`;

const shaderMesh = new THREE.Mesh(
  new THREE.SphereGeometry(1.5, 128, 128),
  new THREE.ShaderMaterial({
    uniforms: shaderUniforms,
    vertexShader,
    fragmentShader
  })
);
shaderMesh.position.set(0, 1, 0);
scene.add(shaderMesh);

// Additional objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.25, 128, 32),
  new THREE.MeshStandardMaterial({
    color: 0xff8844,
    metalness: 0.7,
    roughness: 0.2
  })
);
torus.position.set(-3, 1, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0x44ff88,
    metalness: 0.3,
    roughness: 0.5
  })
);
box.position.set(3, 0.5, 0);
scene.add(box);

// Clock
const clock = new THREE.Clock();

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsedTime = clock.getElapsedTime();

  // Update shader time
  shaderUniforms.uTime.value = elapsedTime;

  // Animate objects
  shaderMesh.rotation.y += 0.005;
  torus.rotation.x += 0.01;
  torus.rotation.y += 0.015;
  box.rotation.x += 0.01;
  box.rotation.y += 0.01;

  // Move point light in a circular path
  pointLight.position.x = Math.cos(elapsedTime) * 4;
  pointLight.position.z = Math.sin(elapsedTime) * 4;
  pointLight.position.y = 2 + Math.sin(elapsedTime * 2.0);

  pointLightHelper.position.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

