## `main.js`

```javascript
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

const app = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0d1117);
scene.fog = new THREE.Fog(0x0d1117, 12, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 10);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Clock
const clock = new THREE.Clock();

// Ambient light
const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
dirLight.shadow.camera.left = -15;
dirLight.shadow.camera.right = 15;
dirLight.shadow.camera.top = 15;
dirLight.shadow.camera.bottom = -15;
scene.add(dirLight);

// Point light with animation
const pointLight = new THREE.PointLight(0x44aaff, 40, 30, 2);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x1f2937,
  roughness: 0.85,
  metalness: 0.15
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI * 0.5;
ground.receiveShadow = true;
scene.add(ground);

// Standard objects
const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0xf59e0b,
    roughness: 0.4,
    metalness: 0.3
  })
);
box.position.set(-2.5, 0.75, 0);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0x10b981,
    roughness: 0.2,
    metalness: 0.7
  })
);
sphere.position.set(2.5, 1, 0);
sphere.castShadow = true;
sphere.receiveShadow = true;
scene.add(sphere);

// Custom shader object
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x7c3aed) },
  uColorB: { value: new THREE.Color(0x22d3ee) }
};

const shaderMat = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.15;
      wave += cos(pos.x * 3.0 + uTime * 1.5) * 0.1;
      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
      vec3 color = mix(uColorA, uColorB, vUv.y + vWave * 2.0 + pulse * 0.2);
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

const shaderMesh = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.9, 0.3, 256, 32),
  shaderMat
);
shaderMesh.position.set(0, 2, -3);
shaderMesh.castShadow = true;
shaderMesh.receiveShadow = true;
scene.add(shaderMesh);

// Small glowing markers
const markerMaterial = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  emissive: 0x66ccff,
  emissiveIntensity: 2
});

for (let i = 0; i < 12; i++) {
  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.08, 16, 16),
    markerMaterial
  );

  const angle = (i / 12) * Math.PI * 2;
  marker.position.set(Math.cos(angle) * 4, 0.5, Math.sin(angle) * 4);
  marker.castShadow = true;
  scene.add(marker);
}

// Optional axes helper
const axesHelper = new THREE.AxesHelper(3);
scene.add(axesHelper);

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  controls.update();

  // Animate standard objects
  box.rotation.x += 0.01;
  box.rotation.y += 0.015;

  sphere.position.y = 1 + Math.sin(elapsed * 2.0) * 0.25;

  // Animate shader
  shaderUniforms.uTime.value = elapsed;
  shaderMesh.rotation.x = elapsed * 0.3;
  shaderMesh.rotation.y = elapsed * 0.6;

  // Animate point light in a circular path
  pointLight.position.x = Math.cos(elapsed) * 4;
  pointLight.position.z = Math.sin(elapsed) * 4;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;

  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

