import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

const container = document.getElementById('app');

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 12, 45);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  200
);
camera.position.set(7, 5, 10);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
container.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1.5, 0);

// Clock
const clock = new THREE.Clock();

// Ambient Light
const ambientLight = new THREE.AmbientLight(0x88aaff, 0.35);
scene.add(ambientLight);

// Directional Light
const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
dirLight.shadow.camera.left = -15;
dirLight.shadow.camera.right = 15;
dirLight.shadow.camera.top = 15;
dirLight.shadow.camera.bottom = -15;
scene.add(dirLight);

// Point Light with dynamic motion
const pointLight = new THREE.PointLight(0x44ccff, 2.5, 30, 2);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
pointLight.shadow.mapSize.width = 1024;
pointLight.shadow.mapSize.height = 1024;
scene.add(pointLight);

// Optional point light helper sphere
const pointLightMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44ccff })
);
scene.add(pointLightMesh);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(50, 50),
  new THREE.MeshStandardMaterial({
    color: 0x1b2238,
    roughness: 0.9,
    metalness: 0.05
  })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Standard objects
const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0xff8844,
    roughness: 0.35,
    metalness: 0.25
  })
);
box.position.set(-3, 0.75, 0);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0x66ffcc,
    roughness: 0.2,
    metalness: 0.6
  })
);
sphere.position.set(3, 1, 0);
sphere.castShadow = true;
sphere.receiveShadow = true;
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.9, 0.3, 128, 32),
  new THREE.MeshStandardMaterial({
    color: 0xa066ff,
    roughness: 0.4,
    metalness: 0.7
  })
);
torus.position.set(0, 2, -3);
torus.castShadow = true;
torus.receiveShadow = true;
scene.add(torus);

// Custom shader object
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x00d0ff) },
  uColorB: { value: new THREE.Color(0xff00aa) }
};

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.15
                 + cos(pos.y * 5.0 + uTime * 1.5) * 0.15;

      pos += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
      float mixFactor = smoothstep(-0.2, 0.2, vWave) * 0.7 + pulse * 0.3;

      vec3 color = mix(uColorA, uColorB, mixFactor);

      float glow = 0.15 / (abs(vWave) + 0.08);
      color += glow * 0.08;

      gl_FragColor = vec4(color, 1.0);
    }
  `
});

const shaderMesh = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 32),
  shaderMaterial
);
shaderMesh.position.set(0, 2, 3);
shaderMesh.castShadow = true;
shaderMesh.receiveShadow = true;
scene.add(shaderMesh);

// Decorative pillars
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const pillar = new THREE.Mesh(
    new THREE.CylinderGeometry(0.3, 0.3, 3, 24),
    new THREE.MeshStandardMaterial({
      color: 0x7f8fb3,
      roughness: 0.8,
      metalness: 0.1
    })
  );

  pillar.position.set(Math.cos(angle) * 8, 1.5, Math.sin(angle) * 8);
  pillar.castShadow = true;
  pillar.receiveShadow = true;
  scene.add(pillar);
}

// Resize
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Dynamic light movement
  pointLight.position.x = Math.cos(elapsed * 1.2) * 4;
  pointLight.position.z = Math.sin(elapsed * 1.2) * 4;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
  pointLightMesh.position.copy(pointLight.position);

  // Object animation
  box.rotation.x += 0.01;
  box.rotation.y += 0.015;

  sphere.position.y = 1 + Math.sin(elapsed * 1.5) * 0.25;
  torus.rotation.x = elapsed * 0.6;
  torus.rotation.y = elapsed * 0.9;

  shaderUniforms.uTime.value = elapsed;
  shaderMesh.rotation.y = elapsed * 0.5;
  shaderMesh.rotation.x = Math.sin(elapsed * 0.3) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}

animate();
