import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js';

const canvas = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0d1117);
scene.fog = new THREE.Fog(0x0d1117, 15, 50);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 10);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Clock
const clock = new THREE.Clock();

// Ambient Light
const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambientLight);

// Directional Light
const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
dirLight.position.set(5, 10, 5);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(2048, 2048);
dirLight.shadow.camera.near = 1;
dirLight.shadow.camera.far = 30;
dirLight.shadow.camera.left = -10;
dirLight.shadow.camera.right = 10;
dirLight.shadow.camera.top = 10;
dirLight.shadow.camera.bottom = -10;
scene.add(dirLight);

// Moving Point Light
const pointLight = new THREE.PointLight(0x44aaff, 30, 20, 2);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Light helper sphere
const lightSphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
scene.add(lightSphere);

// Ground shader
const groundMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x101820) },
    uColorB: { value: new THREE.Color(0x1f4068) }
  },
  vertexShader: `
    varying vec2 vUv;
    varying float vWave;

    uniform float uTime;

    void main() {
      vUv = uv;
      vec3 pos = position;

      float wave = sin(pos.x * 2.0 + uTime) * 0.08
                 + cos(pos.z * 2.5 + uTime * 1.2) * 0.08;

      pos.y += wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    varying vec2 vUv;
    varying float vWave;

    uniform vec3 uColorA;
    uniform vec3 uColorB;

    void main() {
      float mixValue = vUv.y + vWave * 1.5;
      vec3 color = mix(uColorA, uColorB, smoothstep(0.0, 1.0, mixValue));
      gl_FragColor = vec4(color, 1.0);
    }
  `,
  side: THREE.DoubleSide
});

const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(30, 30, 200, 200),
  groundMaterial
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Central object
const torusKnot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 128, 32),
  new THREE.MeshStandardMaterial({
    color: 0xff8844,
    metalness: 0.7,
    roughness: 0.2,
    emissive: 0x221100
  })
);
torusKnot.position.set(0, 2, 0);
torusKnot.castShadow = true;
torusKnot.receiveShadow = true;
scene.add(torusKnot);

// Secondary objects
const objects = [];

for (let i = 0; i < 20; i++) {
  const geo = i % 2 === 0
    ? new THREE.BoxGeometry(0.6, 0.6, 0.6)
    : new THREE.SphereGeometry(0.35, 24, 24);

  const mat = new THREE.MeshStandardMaterial({
    color: new THREE.Color().setHSL(i / 20, 0.7, 0.5),
    metalness: 0.3,
    roughness: 0.4
  });

  const mesh = new THREE.Mesh(geo, mat);
  const angle = (i / 20) * Math.PI * 2;
  const radius = 4 + (i % 3) * 1.2;

  mesh.position.set(
    Math.cos(angle) * radius,
    0.5 + Math.random() * 2,
    Math.sin(angle) * radius
  );

  mesh.castShadow = true;
  mesh.receiveShadow = true;

  scene.add(mesh);
  objects.push(mesh);
}

// Postprocessing
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.8, // strength
  0.4, // radius
  0.85 // threshold
);
composer.addPass(bloomPass);

// Resize
window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;

  camera.aspect = w / h;
  camera.updateProjectionMatrix();

  renderer.setSize(w, h);
  composer.setSize(w, h);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  controls.update();

  // Animate shader
  groundMaterial.uniforms.uTime.value = elapsed;

  // Animate central object
  torusKnot.rotation.x = elapsed * 0.4;
  torusKnot.rotation.y = elapsed * 0.7;

  // Orbiting point light
  pointLight.position.x = Math.cos(elapsed * 1.5) * 4;
  pointLight.position.z = Math.sin(elapsed * 1.5) * 4;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;
  lightSphere.position.copy(pointLight.position);

  // Animate surrounding objects
  objects.forEach((obj, i) => {
    obj.rotation.x += 0.01 + i * 0.0005;
    obj.rotation.y += 0.015 + i * 0.0005;
    obj.position.y += Math.sin(elapsed * 2 + i) * 0.003;
  });

  composer.render();
}

animate();
