import * as THREE from 'https://unpkg.com/three@0.167.1/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.167.1/examples/jsm/controls/OrbitControls.js';

const canvas = document.getElementById('app');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 15, 50);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(6, 4, 10);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Clock
const clock = new THREE.Clock();

// Ambient light
const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambientLight);

// Directional light
const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
dirLight.position.set(5, 10, 5);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 50;
dirLight.shadow.camera.left = -15;
dirLight.shadow.camera.right = 15;
dirLight.shadow.camera.top = 15;
dirLight.shadow.camera.bottom = -15;
scene.add(dirLight);

// Animated point light
const pointLight = new THREE.PointLight(0x44aaff, 2.5, 30, 2);
pointLight.position.set(0, 3, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Visible light marker
const pointLightMarker = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x44aaff })
);
pointLight.add(pointLightMarker);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 40),
  new THREE.MeshStandardMaterial({
    color: 0x1f2937,
    roughness: 0.9,
    metalness: 0.1
  })
);
ground.rotation.x = -Math.PI * 0.5;
ground.receiveShadow = true;
scene.add(ground);

// Standard box
const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0xf59e0b,
    roughness: 0.4,
    metalness: 0.3
  })
);
box.position.set(-2.5, 0.75, 0);
box.castShadow = true;
box.receiveShadow = true;
scene.add(box);

// Standard torus knot
const knot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 128, 24),
  new THREE.MeshStandardMaterial({
    color: 0x10b981,
    roughness: 0.35,
    metalness: 0.7
  })
);
knot.position.set(2.5, 1.2, -1.5);
knot.castShadow = true;
knot.receiveShadow = true;
scene.add(knot);

// Custom shader sphere
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x7c3aed) },
  uColorB: { value: new THREE.Color(0x06b6d4) }
};

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;

      vec3 pos = position;
      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.12;
      wave += sin(pos.x * 5.0 + uTime * 1.5) * 0.08;
      pos += normal * wave;

      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
      float mixValue = smoothstep(-0.15, 0.15, vWave) * 0.7 + pulse * 0.3;

      vec3 color = mix(uColorA, uColorB, mixValue);

      float glow = 0.85 + abs(vWave) * 2.0;
      gl_FragColor = vec4(color * glow, 1.0);
    }
  `
});

const shaderSphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 128, 128),
  shaderMaterial
);
shaderSphere.position.set(0, 1.5, 0);
shaderSphere.castShadow = true;
shaderSphere.receiveShadow = true;
scene.add(shaderSphere);

// Optional helpers
const gridHelper = new THREE.GridHelper(40, 40, 0x334155, 0x1e293b);
scene.add(gridHelper);

// Resize handling
window.addEventListener('resize', onWindowResize);

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderUniforms.uTime.value = elapsed;

  // Animate objects
  box.rotation.x = elapsed * 0.4;
  box.rotation.y = elapsed * 0.8;

  knot.rotation.x = elapsed * 0.3;
  knot.rotation.y = elapsed * 0.6;

  shaderSphere.rotation.y = elapsed * 0.25;

  // Animate point light in a circular path
  pointLight.position.x = Math.cos(elapsed) * 4.0;
  pointLight.position.z = Math.sin(elapsed) * 4.0;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 1.0;

  controls.update();
  renderer.render(scene, camera);
}

animate();
