          float diffuse = max(dot(normal, lightDir), 0.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 10.0);
          vec3 baseColor = mix(vec3(0.2, 0.3, 0.9), vec3(0.9, 0.2, 0.8), pulse);

          vec3 color = baseColor * (0.2 + diffuse * 1.2);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const object = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 128, 24),
      shaderMaterial
    );
    scene.add(object);

    // Extra standard object for comparison
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.6, 32, 32),
      new THREE.MeshStandardMaterial({ color: 0xffaa33, roughness: 0.3, metalness: 0.7 })
    );
    sphere.position.set(-2, 0, 0);
    scene.add(sphere);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Animate object
      object.rotation.x = t * 0.4;
      object.rotation.y = t * 0.8;

      sphere.rotation.y = t * 0.6;

      // Animate light in a circle
      pointLight.position.x = Math.cos(t) * 4.0;
      pointLight.position.z = Math.sin(t) * 4.0;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0);

      pointLightHelper.position.copy(pointLight.position);

      shaderMaterial.uniforms.uTime.value = t;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
