    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(1, 0.35, 128, 32);

    // Uniforms for shader animation and lighting
    const uniforms = {
      uTime: { value: 0 },
      uLightPos: { value: new THREE.Vector3(2, 2, 2) },
      uColorA: { value: new THREE.Color(0x00d0ff) },
      uColorB: { value: new THREE.Color(0xff00aa) }
    };

    // Vertex shader
    const vertexShader = `
      varying vec3 vNormal;
      varying vec3 vWorldPosition;
      varying vec2 vUv;
      uniform float uTime;

      void main() {
        vUv = uv;

        vec3 pos = position + normal * 0.08 * sin(uTime * 2.0 + position.y * 6.0);

        vec4 worldPos = modelMatrix * vec4(pos, 1.0);
        vWorldPosition = worldPos.xyz;
        vNormal = normalize(mat3(modelMatrix) * normal);

        gl_Position = projectionMatrix * viewMatrix * worldPos;
