      display: block;
    }
  </style>
</head>
<body>
  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x101522);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2, 6);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Ambient + dynamic point light
    const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0x66ccff, 2, 20);
    pointLight.position.set(2, 3, 2);
    scene.add(pointLight);

    // Light helper sphere
    const lightMarker = new THREE.Mesh(
      new THREE.SphereGeometry(0.08, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x66ccff })
    );
    scene.add(lightMarker);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    scene.add(ground);

    // Shader-driven object
    const uniforms = {
      uTime: { value: 0.0 },
      uLightPos: { value: new THREE.Vector3() }
    };

    const material = new THREE.ShaderMaterial({
      uniforms,
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        void main() {
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position + normal * 0.15 * sin(uTime * 2.0 + position.y * 8.0);
          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uLightPos;

        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        void main() {
          vec3 normal = normalize(vNormal);
          vec3 lightDir = normalize(uLightPos - vWorldPosition);

          float diffuse = max(dot(normal, lightDir), 0.0);
          float pulse = 0.5 + 0.5 * sin(uTime * 3.0);

          vec3 baseColor = mix(
            vec3(0.2, 0.3, 0.8),
            vec3(0.8, 0.2, 1.0),
            pulse
          );

          vec3 color = baseColor * (0.2 + diffuse * 1.2);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 128, 24),
      material
    );
    scene.add(mesh);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Animate mesh
      mesh.rotation.y += 0.01;
      mesh.rotation.x = Math.sin(t * 0.5) * 0.2;

      // Animate light in a circle
      pointLight.position.x = Math.cos(t) * 3.0;
      pointLight.position.z = Math.sin(t) * 3.0;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0);

      lightMarker.position.copy(pointLight.position);

      // Update shader uniforms
      uniforms.uTime.value = t;
      uniforms.uLightPos.value.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
