        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00ffff) },
        uColorB: { value: new THREE.Color(0xff00ff) }
      },
      vertexShader: `
        varying vec2 vUv;
        varying float vWave;

        uniform float uTime;

        void main() {
          vUv = uv;
          vec3 pos = position;
          float wave = sin(pos.y * 8.0 + uTime * 2.0) * 0.08;
          pos += normal * wave;
          vWave = wave;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        varying vec2 vUv;
        varying float vWave;

        uniform vec3 uColorA;
        uniform vec3 uColorB;
        uniform float uTime;

        void main() {
          float t = 0.5 + 0.5 * sin(uTime + vUv.y * 10.0 + vWave * 20.0);
          vec3 color = mix(uColorA, uColorB, t);
          gl_FragColor = vec4(color, 1.0);
