        metalness: 0.1
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    scene.add(ground);

    // Shader-driven object
    const geometry = new THREE.SphereGeometry(1, 128, 128);

    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uLightPos: { value: pointLight.position },
        uColorA: { value: new THREE.Color(0x7a5cff) },
        uColorB: { value: new THREE.Color(0x00d4ff) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        void main() {
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position + normal * 0.15 * sin(uTime * 2.0 + position.y * 6.0);
          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform vec3 uLightPos;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec3 vNormal;
        varying vec3 vWorldPosition;

        void main() {
          vec3 normal = normalize(vNormal);
          vec3 lightDir = normalize(uLightPos - vWorldPosition);

          float diffuse = max(dot(normal, lightDir), 0.0);
          float fresnel = pow(1.0 - max(dot(normal, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

          vec3 baseColor = mix(uColorA, uColorB, diffuse);
          vec3 color = baseColor * (0.25 + diffuse) + fresnel * 0.35;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const sphere = new THREE.Mesh(geometry, material);
    scene.add(sphere);

    // Extra object for scene depth
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.2, 1.2, 1.2),
      new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.4,
        metalness: 0.5
      })
    );
    box.position.set(-2.2, -0.3, 0);
    scene.add(box);

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Animate light
      pointLight.position.x = Math.cos(t) * 3.0;
      pointLight.position.z = Math.sin(t) * 3.0;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.75;

      // Animate objects
      sphere.rotation.y += 0.005;
      box.rotation.x += 0.01;
      box.rotation.y += 0.015;

      // Update shader time
      material.uniforms.uTime.value = t;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
