## `SimplePhysicsWorld.cpp`

```cpp
#include "SimplePhysicsWorld.h"
#include <stdexcept>

namespace PhysicsPlugin
{
    SimplePhysicsWorld::SimplePhysicsWorld() = default;

    BodyHandle SimplePhysicsWorld::CreateRigidBody(const RigidBodyDesc& desc)
    {
        BodyHandle handle = m_nextHandle++;

        RigidBody body;
        body.handle = handle;
        body.transform = desc.transform;
        body.shape = desc.shape;
        body.mass = desc.isStatic ? 0.0f : desc.mass;
        body.invMass = (desc.isStatic || desc.mass <= 0.0f) ? 0.0f : 1.0f / desc.mass;
        body.isStatic = desc.isStatic;
        body.useGravity = desc.useGravity;
        body.velocity = {0.0f, 0.0f, 0.0f};
        body.accumulatedForce = {0.0f, 0.0f, 0.0f};

        m_bodies.emplace(handle, body);
        return handle;
    }

    void SimplePhysicsWorld::DestroyRigidBody(BodyHandle handle)
    {
        m_bodies.erase(handle);
    }

    void SimplePhysicsWorld::ApplyForce(BodyHandle handle, const Vec3& force)
    {
        auto it = m_bodies.find(handle);
        if (it == m_bodies.end() || it->second.isStatic)
            return;

        it->second.accumulatedForce += force;
    }

    void SimplePhysicsWorld::ApplyImpulse(BodyHandle handle, const Vec3& impulse)
    {
        auto it = m_bodies.find(handle);
        if (it == m_bodies.end() || it->second.isStatic)
            return;

        it->second.velocity += impulse * it->second.invMass;
    }

    Transform SimplePhysicsWorld::GetTransform(BodyHandle handle) const
    {
        auto it = m_bodies.find(handle);
        if (it == m_bodies.end())
            throw std::runtime_error("Invalid body handle");

        return it->second.transform;
    }

    void SimplePhysicsWorld::SetTransform(BodyHandle handle, const Transform& transform)
    {
        auto it = m_bodies.find(handle);
        if (it == m_bodies.end())
            return;

        it->second.transform = transform;
    }

    void SimplePhysicsWorld::Integrate(RigidBody& body, float dt)
    {
        if (body.isStatic)
            return;

        Vec3 totalForce = body.accumulatedForce;
        if (body.useGravity)
            totalForce += m_gravity * body.mass;

        Vec3 acceleration = totalForce * body.invMass;
        body.velocity += acceleration * dt;
        body.transform.position += body.velocity * dt;

        body.accumulatedForce = {0.0f, 0.0f, 0.0f};
    }

    void SimplePhysicsWorld::ResolveGroundCollision(RigidBody& body)
    {
        float bottom = body.transform.position.y;

        if (body.shape.type == ShapeType::Sphere)
            bottom -= body.shape.radius;
        else if (body.shape.type == ShapeType::Box)
            bottom -= body.shape.halfExtents.y;

        if (bottom < 0.0f)
        {
            float penetration = -bottom;
            body.transform.position.y += penetration;

            if (body.velocity.y < 0.0f)
                body.velocity.y *= -0.4f;
        }
    }

    void SimplePhysicsWorld::Simulate(float deltaTime)
    {
        const float fixedStep = 1.0f / 60.0f;
        static float accumulator = 0.0f;
        accumulator += deltaTime;

        while (accumulator >= fixedStep)
        {
            for (auto& [handle, body] : m_bodies)
            {
                Integrate(body, fixedStep);
                ResolveGroundCollision(body);
            }

            accumulator -= fixedStep;
        }
    }
}
