```cpp
// SimplePhysicsPlugin.cpp
#include "IPhysicsPlugin.h"
#include <cmath>

static Vec3 Add(const Vec3& a, const Vec3& b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 Mul(const Vec3& v, float s) {
    return {v.x * s, v.y * s, v.z * s};
}

class SimpleRigidBody : public IRigidBody {
public:
    explicit SimpleRigidBody(const RigidBodyDesc& desc)
        : mass(desc.mass), isStatic(desc.isStatic) {
        transform.position = desc.initialPosition;
        velocity = desc.initialVelocity;
    }

    void ApplyForce(const Vec3& force) override {
        accumulatedForce = Add(accumulatedForce, force);
    }

    void ApplyImpulse(const Vec3& impulse) override {
        if (isStatic || mass <= 0.0f) return;
        velocity = Add(velocity, Mul(impulse, 1.0f / mass));
    }

    Transform GetTransform() const override {
        return transform;
    }

    void SetTransform(const Transform& t) override {
        transform = t;
    }

    void Integrate(float dt, const Vec3& gravity) {
        if (isStatic || mass <= 0.0f) return;

        Vec3 totalForce = Add(accumulatedForce, Mul(gravity, mass));
        Vec3 acceleration = Mul(totalForce, 1.0f / mass);

        velocity = Add(velocity, Mul(acceleration, dt));
        transform.position = Add(transform.position, Mul(velocity, dt));

        accumulatedForce = {0, 0, 0};
    }

private:
    float mass = 1.0f;
    bool isStatic = false;
    Transform transform{};
    Vec3 velocity{0,0,0};
    Vec3 accumulatedForce{0,0,0};
};

class SimplePhysicsWorld : public IPhysicsWorld {
public:
    IRigidBody* CreateRigidBody(const RigidBodyDesc& desc) override {
        bodies.push_back(std::make_unique<SimpleRigidBody>(desc));
        return bodies.back().get();
    }

    void StepSimulation(float deltaTime) override {
        for (auto& body : bodies) {
            body->Integrate(deltaTime, gravity);
        }
    }

    void SetGravity(const Vec3& g) override {
        gravity = g;
    }

private:
    std::vector<std::unique_ptr<SimpleRigidBody>> bodies;
    Vec3 gravity{0.0f, -9.81f, 0.0f};
};

class SimplePhysicsPlugin : public IPhysicsPlugin {
public:
    bool Initialize() override {
        return true;
    }

    void Shutdown() override {
        world.reset();
    }

    IPhysicsWorld* CreateWorld() override {
        world = std::make_unique<SimplePhysicsWorld>();
        return world.get();
    }

private:
    std::unique_ptr<SimplePhysicsWorld> world;
};
