```cpp
// High-level engine-agnostic physics plugin skeleton

struct Vec3 {
    float x, y, z;
};

struct Transform {
    Vec3 position;
    Vec3 rotationEuler;
};

struct RigidBodyDesc {
    float mass;
    Vec3 initialPosition;
    Vec3 initialVelocity;
    bool isStatic;
};

class PhysicsBody {
public:
    Transform transform;
    Vec3 linearVelocity;
    Vec3 accumulatedForce;
    float mass = 1.0f;
    bool isStatic = false;

    void AddForce(const Vec3& force) {
        if (!isStatic) {
            accumulatedForce.x += force.x;
            accumulatedForce.y += force.y;
            accumulatedForce.z += force.z;
        }
    }
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual bool Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual int CreateRigidBody(const RigidBodyDesc& desc) = 0;
    virtual void ApplyForce(int bodyId, const Vec3& force) = 0;
    virtual void StepSimulation(float deltaTime) = 0;
    virtual Transform GetBodyTransform(int bodyId) const = 0;
};

class SimplePhysicsPlugin : public IPhysicsPlugin {
private:
    std::vector<PhysicsBody> bodies;
    Vec3 gravity{0.0f, -9.81f, 0.0f};

public:
    bool Initialize() override {
        bodies.clear();
        return true;
    }

    void Shutdown() override {
        bodies.clear();
    }

    int CreateRigidBody(const RigidBodyDesc& desc) override {
        PhysicsBody body;
        body.transform.position = desc.initialPosition;
        body.linearVelocity = desc.initialVelocity;
        body.mass = desc.mass > 0.0f ? desc.mass : 1.0f;
        body.isStatic = desc.isStatic;
        bodies.push_back(body);
        return static_cast<int>(bodies.size() - 1);
    }

    void ApplyForce(int bodyId, const Vec3& force) override {
        if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size())) return;
        bodies[bodyId].AddForce(force);
    }

    void StepSimulation(float deltaTime) override {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            Vec3 totalForce = body.accumulatedForce;
            totalForce.x += gravity.x * body.mass;
            totalForce.y += gravity.y * body.mass;
            totalForce.z += gravity.z * body.mass;

            Vec3 acceleration{
                totalForce.x / body.mass,
                totalForce.y / body.mass,
                totalForce.z / body.mass
            };

            body.linearVelocity.x += acceleration.x * deltaTime;
            body.linearVelocity.y += acceleration.y * deltaTime;
            body.linearVelocity.z += acceleration.z * deltaTime;

            body.transform.position.x += body.linearVelocity.x * deltaTime;
            body.transform.position.y += body.linearVelocity.y * deltaTime;
            body.transform.position.z += body.linearVelocity.z * deltaTime;

            body.accumulatedForce = {0.0f, 0.0f, 0.0f};
        }
    }

    Transform GetBodyTransform(int bodyId) const override {
        if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size())) {
            return {};
        }
        return bodies[bodyId].transform;
    }
};
```

