## `Private/SimplePhysicsComponent.cpp`

```cpp
#include "SimplePhysicsComponent.h"
#include "SimplePhysicsSubsystem.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

USimplePhysicsComponent::USimplePhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void USimplePhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (UWorld* World = GetWorld())
    {
        USimplePhysicsSubsystem* Subsystem = World->GetSubsystem<USimplePhysicsSubsystem>();
        if (Subsystem)
        {
            Subsystem->RegisterComponent(this);
            CachedSubsystem = Subsystem;
        }
    }
}

void USimplePhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (CachedSubsystem.IsValid())
    {
        CachedSubsystem->UnregisterComponent(this);
    }

    Super::EndPlay(EndPlayReason);
}

void USimplePhysicsComponent::AddForce(FVector Force)
{
    PhysicsState.AccumulatedForce += Force;
}

void USimplePhysicsComponent::AddImpulse(FVector Impulse)
{
    if (PhysicsState.Mass > KINDA_SMALL_NUMBER)
    {
        PhysicsState.Velocity += Impulse / PhysicsState.Mass;
    }
}

void USimplePhysicsComponent::SetVelocity(FVector NewVelocity)
{
    PhysicsState.Velocity = NewVelocity;
}

FVector USimplePhysicsComponent::GetVelocity() const
{
    return PhysicsState.Velocity;
}

void USimplePhysicsComponent::Simulate(float DeltaTime)
{
    if (!PhysicsState.bSimulating || DeltaTime <= 0.0f)
    {
        PhysicsState.AccumulatedForce = FVector::ZeroVector;
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        PhysicsState.AccumulatedForce = FVector::ZeroVector;
        return;
    }

    const float SafeMass = FMath::Max(PhysicsState.Mass, 0.001f);

    FVector TotalForce = PhysicsState.AccumulatedForce;

    if (bEnableGravity)
    {
        TotalForce += FVector(0.0f, 0.0f, GetWorld()->GetGravityZ() * SafeMass * GravityScale);
    }

    const FVector Acceleration = TotalForce / SafeMass;
    PhysicsState.Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    PhysicsState.Velocity *= DampingFactor;

    FVector NewLocation = Owner->GetActorLocation() + PhysicsState.Velocity * DeltaTime;

    if (NewLocation.Z < GroundHeight)
    {
        NewLocation.Z = GroundHeight;

        if (PhysicsState.Velocity.Z < 0.0f)
        {
            PhysicsState.Velocity.Z = -PhysicsState.Velocity.Z * Restitution;
        }
    }

    Owner->SetActorLocation(NewLocation, false);

    PhysicsState.AccumulatedForce = FVector::ZeroVector;
}
