## `Private/SimplePhysicsSubsystem.cpp`

```cpp
#include "SimplePhysicsSubsystem.h"
#include "SimplePhysicsComponent.h"

void USimplePhysicsSubsystem::Tick(float DeltaTime)
{
    for (int32 Index = Components.Num() - 1; Index >= 0; --Index)
    {
        USimplePhysicsComponent* Component = Components[Index];
        if (!IsValid(Component))
        {
            Components.RemoveAtSwap(Index);
            continue;
        }

        Component->Simulate(DeltaTime);
    }
}

