## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody()
        : m_bodyType(BodyType::Dynamic)
        , m_mass(1.0f)
        , m_inverseMass(1.0f)
        , m_useGravity(true)
        , m_restitution(0.5f)
        , m_position()
        , m_velocity()
        , m_acceleration()
        , m_accumulatedForce()
    {
    }

    void RigidBody::SetBodyType(BodyType type)
    {
        m_bodyType = type;

        if (m_bodyType == BodyType::Static)
        {
            m_mass = 0.0f;
            m_inverseMass = 0.0f;
        }
    }

    BodyType RigidBody::GetBodyType() const
    {
        return m_bodyType;
    }

    void RigidBody::SetMass(float mass)
    {
        if (m_bodyType == BodyType::Static || mass <= 0.0f)
        {
            m_mass = 0.0f;
            m_inverseMass = 0.0f;
            return;
        }

        m_mass = mass;
        m_inverseMass = 1.0f / mass;
    }

    float RigidBody::GetMass() const
    {
        return m_mass;
    }

    float RigidBody::GetInverseMass() const
    {
        return m_inverseMass;
    }

    void RigidBody::SetPosition(const Vec3& position)
    {
        m_position = position;
    }

    const Vec3& RigidBody::GetPosition() const
    {
        return m_position;
    }

    void RigidBody::SetVelocity(const Vec3& velocity)
    {
        m_velocity = velocity;
    }

    const Vec3& RigidBody::GetVelocity() const
    {
        return m_velocity;
    }

    void RigidBody::SetAcceleration(const Vec3& acceleration)
    {
        m_acceleration = acceleration;
    }

    const Vec3& RigidBody::GetAcceleration() const
    {
        return m_acceleration;
    }

    void RigidBody::AddForce(const Vec3& force)
    {
        m_accumulatedForce += force;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = Vec3();
    }

    void RigidBody::SetUseGravity(bool enabled)
    {
        m_useGravity = enabled;
    }

    bool RigidBody::UsesGravity() const
    {
        return m_useGravity;
    }

    void RigidBody::SetRestitution(float restitution)
    {
        m_restitution = restitution;
    }

    float RigidBody::GetRestitution() const
    {
        return m_restitution;
    }

    void RigidBody::Integrate(float deltaTime, const Vec3& gravity)
    {
        if (m_bodyType != BodyType::Dynamic || m_inverseMass <= 0.0f)
            return;

        Vec3 totalAcceleration = m_acceleration;

        if (m_useGravity)
            totalAcceleration += gravity;

        totalAcceleration += m_accumulatedForce * m_inverseMass;

        m_velocity += totalAcceleration * deltaTime;
        m_position += m_velocity * deltaTime;

        ClearForces();
    }
}
