## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f)
    {
    }

    void PhysicsWorld::SetGravity(const Vec3& gravity)
    {
        m_gravity = gravity;
    }

    const Vec3& PhysicsWorld::GetGravity() const
    {
        return m_gravity;
    }

    RigidBody* PhysicsWorld::CreateRigidBody()
    {
        auto body = std::make_unique<RigidBody>();
        RigidBody* rawPtr = body.get();
        m_bodies.push_back(std::move(body));
        return rawPtr;
    }

    void PhysicsWorld::DestroyRigidBody(RigidBody* body)
    {
        m_bodies.erase(
            std::remove_if(
                m_bodies.begin(),
                m_bodies.end(),
                [body](const std::unique_ptr<RigidBody>& ptr)
                {
                    return ptr.get() == body;
                }),
            m_bodies.end());
    }

    void PhysicsWorld::StepSimulation(float deltaTime)
    {
        for (auto& body : m_bodies)
        {
            body->Integrate(deltaTime, m_gravity);
            SolveGroundPlaneCollision(*body);
        }
    }

    const std::vector<std::unique_ptr<RigidBody>>& PhysicsWorld::GetBodies() const
    {
        return m_bodies;
    }

    void PhysicsWorld::SolveGroundPlaneCollision(RigidBody& body)
    {
        if (body.GetBodyType() != BodyType::Dynamic)
            return;

        Vec3 position = body.GetPosition();
        Vec3 velocity = body.GetVelocity();

        // Simple plane at y = 0
        if (position.y < 0.0f)
        {
            position.y = 0.0f;

            if (velocity.y < 0.0f)
            {
                velocity.y = -velocity.y * body.GetRestitution();
            }

            // crude friction damping
            velocity.x *= 0.95f;
            velocity.z *= 0.95f;

            body.SetPosition(position);
            body.SetVelocity(velocity);
        }
    }
}
