# 5. Plugin implementation

## `CustomPhysicsPlugin.cpp`

```cpp
#include "ICustomPhysicsPlugin.h"
#include "PhysicsWorld.h"

#include <iostream>
#include <memory>

namespace CustomPhysics
{
    class CustomPhysicsPluginImpl : public ICustomPhysicsPlugin
    {
    public:
        CustomPhysicsPluginImpl()
            : m_initialized(false)
        {
        }

        virtual ~CustomPhysicsPluginImpl()
        {
            Shutdown();
        }

        bool Initialize() override
        {
            if (m_initialized)
                return true;

            m_world = std::make_unique<PhysicsWorld>();
            m_initialized = true;

            std::cout << "[CustomPhysics] Plugin initialized.\n";
            return true;
        }

        void Shutdown() override
        {
            if (!m_initialized)
                return;

            m_world.reset();
            m_initialized = false;

            std::cout << "[CustomPhysics] Plugin shutdown.\n";
        }

        void Tick(float deltaTime) override
        {
            if (!m_initialized || !m_world)
                return;

            m_world->StepSimulation(deltaTime);
        }

        PhysicsWorld* GetWorld() override
        {
            return m_world.get();
        }

    private:
        bool m_initialized;
        std::unique_ptr<PhysicsWorld> m_world;
    };

    extern "C" ICustomPhysicsPlugin* CreatePhysicsPlugin()
    {
        return new CustomPhysicsPluginImpl();
    }

    extern "C" void DestroyPhysicsPlugin(ICustomPhysicsPlugin* plugin)
    {
        delete plugin;
    }
}
