# 11. Optional: fixed timestep improvement

If you want a slightly better starter loop, replace direct `Tick(deltaTime)` stepping with an accumulator:

```cpp
class CustomPhysicsPluginImpl : public ICustomPhysicsPlugin
{
public:
    CustomPhysicsPluginImpl()
        : m_initialized(false)
        , m_accumulator(0.0f)
        , m_fixedTimeStep(1.0f / 60.0f)
    {
    }

    bool Initialize() override
    {
        if (m_initialized)
            return true;

        m_world = std::make_unique<PhysicsWorld>();
        m_initialized = true;
        return true;
    }

    void Shutdown() override
    {
        m_world.reset();
        m_initialized = false;
    }

    void Tick(float deltaTime) override
    {
        if (!m_world)
            return;

        m_accumulator += deltaTime;

        while (m_accumulator >= m_fixedTimeStep)
        {
            m_world->StepSimulation(m_fixedTimeStep);
            m_accumulator -= m_fixedTimeStep;
        }
    }

    PhysicsWorld* GetWorld() override
    {
        return m_world.get();
    }

private:
    bool m_initialized;
    float m_accumulator;
    float m_fixedTimeStep;
    std::unique_ptr<PhysicsWorld> m_world;
};
```

