# 7. Physics component source: `SimplePhysicsComponent.cpp`

```cpp
#include "SimplePhysicsComponent.h"
#include "GameFramework/Actor.h"

USimplePhysicsComponent::USimplePhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void USimplePhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (Mass <= KINDA_SMALL_NUMBER)
    {
        Mass = 1.0f;
    }
}

void USimplePhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bSimulate || !GetOwner())
    {
        return;
    }

    Integrate(DeltaTime);
}

void USimplePhysicsComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void USimplePhysicsComponent::AddImpulse(FVector Impulse)
{
    if (Mass > KINDA_SMALL_NUMBER)
    {
        Velocity += Impulse / Mass;
    }
}

void USimplePhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

FVector USimplePhysicsComponent::GetVelocity() const
{
    return Velocity;
}

void USimplePhysicsComponent::Integrate(float DeltaTime)
{
    if (DeltaTime <= 0.0f)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    FVector Position = Owner->GetActorLocation();

    // F = ma -> a = F / m
    FVector Acceleration = Gravity;
    if (Mass > KINDA_SMALL_NUMBER)
    {
        Acceleration += AccumulatedForce / Mass;
    }

    // Semi-implicit Euler integration
    Velocity += Acceleration * DeltaTime;

    // Simple linear damping
    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    Position += Velocity * DeltaTime;

    if (bEnableGroundPlaneCollision)
    {
        ResolveGroundPlaneCollision(Position);
    }

    Owner->SetActorLocation(Position);

    ClearForces();
}

void USimplePhysicsComponent::ResolveGroundPlaneCollision(FVector& Position)
{
    if (Position.Z < GroundPlaneZ)
    {
        Position.Z = GroundPlaneZ;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = -Velocity.Z * Restitution;
        }

        // Optional friction-ish effect on bounce contact
        Velocity.X *= 0.95f;
        Velocity.Y *= 0.95f;

        // Put very small bounce velocities to rest
        if (FMath::Abs(Velocity.Z) < 5.0f)
        {
            Velocity.Z = 0.0f;
        }
    }
}

void USimplePhysicsComponent::ClearForces()
{
    AccumulatedForce = FVector::ZeroVector;
}
```

