void UCustomPhysicsBodyComponent::BeginPlay()
{
    Super::BeginPlay();

    if (UWorld* World = GetWorld())
    {
        if (UCustomPhysicsWorldSubsystem* Subsystem = World->GetSubsystem<UCustomPhysicsWorldSubsystem>())
        {
            Subsystem->RegisterBody(this);
        }
    }
}

void UCustomPhysicsBodyComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (UWorld* World = GetWorld())
    {
        if (UCustomPhysicsWorldSubsystem* Subsystem = World->GetSubsystem<UCustomPhysicsWorldSubsystem>())
        {
            Subsystem->UnregisterBody(this);
        }
    }

    Super::EndPlay(EndPlayReason);
}

void UCustomPhysicsBodyComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsBodyComponent::ClearForces()
{
    AccumulatedForce = FVector::ZeroVector;
}

FVector UCustomPhysicsBodyComponent::GetPosition() const
{
    if (const AActor* Owner = GetOwner())
    {
        return Owner->GetActorLocation();
    }

    return FVector::ZeroVector;
}

void UCustomPhysicsBodyComponent::SetPosition(const FVector& NewPosition)
{
    if (AActor* Owner = GetOwner())
    {
        Owner->SetActorLocation(NewPosition);
    }
}

void UCustomPhysicsBodyComponent::Integrate(float DeltaTime)
{
    if (!bSimulate)
    {
        return;
    }

    if (Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    FVector TotalForce = AccumulatedForce;

    if (bUseGravity)
    {
        TotalForce += FVector(0.0f, 0.0f, -980.0f) * Mass;
    }

    const FVector Acceleration = TotalForce / Mass;

    Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    const FVector NewPosition = GetPosition() + Velocity * DeltaTime;
    SetPosition(NewPosition);

    ClearForces();
}
