# 3. Physics body

This is the minimal rigid body representation.

## `PhysicsBody.h`

```cpp
#pragma once

#include "CoreMinimal.h"

struct FPhysicsBody
{
    int32 Id = INDEX_NONE;

    FVector Position = FVector::ZeroVector;
    FVector Velocity = FVector::ZeroVector;
    FVector AccumulatedForce = FVector::ZeroVector;

    float Mass = 1.0f;
    float InverseMass = 1.0f;

    bool bSimulate = true;
    bool bIsStatic = false;

    float Restitution = 0.25f;
    float LinearDamping = 0.98f;
    float Radius = 50.0f; // simple sphere collision for initial implementation

    FPhysicsBody() = default;

    FPhysicsBody(int32 InId, const FVector& InPosition, float InMass, bool bInStatic = false)
        : Id(InId)
        , Position(InPosition)
        , Mass(InMass)
        , bIsStatic(bInStatic)
    {
        if (bIsStatic || FMath::IsNearlyZero(Mass))
        {
            InverseMass = 0.0f;
            bSimulate = false;
        }
        else
        {
            InverseMass = 1.0f / Mass;
        }
    }

    void AddForce(const FVector& Force)
    {
        if (!bIsStatic)
        {
            AccumulatedForce += Force;
        }
    }

    void ClearForces()
    {
        AccumulatedForce = FVector::ZeroVector;
    }
};
```

