# 4. Physics world

This owns bodies and performs simulation.

## `PhysicsWorld.h`

```cpp
#pragma once

#include "CoreMinimal.h"
#include "PhysicsBody.h"

class FPhysicsWorld
{
public:
    FPhysicsWorld();

    int32 CreateBody(const FVector& Position, float Mass, bool bStatic = false);
    void RemoveBody(int32 BodyId);

    FPhysicsBody* GetBody(int32 BodyId);
    const FPhysicsBody* GetBody(int32 BodyId) const;

    void StepSimulation(float DeltaTime);

    void SetGravity(const FVector& InGravity) { Gravity = InGravity; }
    FVector GetGravity() const { return Gravity; }

private:
    void Integrate(FPhysicsBody& Body, float DeltaTime);
    void SolveGroundCollision(FPhysicsBody& Body);

private:
    TMap<int32, FPhysicsBody> Bodies;
    int32 NextBodyId = 1;
    FVector Gravity = FVector(0.0f, 0.0f, -980.0f); // cm/s^2 style units
};
```

## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"

FPhysicsWorld::FPhysicsWorld()
{
}

int32 FPhysicsWorld::CreateBody(const FVector& Position, float Mass, bool bStatic)
{
    const int32 NewId = NextBodyId++;
    Bodies.Add(NewId, FPhysicsBody(NewId, Position, Mass, bStatic));
    return NewId;
}

void FPhysicsWorld::RemoveBody(int32 BodyId)
{
    Bodies.Remove(BodyId);
}

FPhysicsBody* FPhysicsWorld::GetBody(int32 BodyId)
{
    return Bodies.Find(BodyId);
}

const FPhysicsBody* FPhysicsWorld::GetBody(int32 BodyId) const
{
    return Bodies.Find(BodyId);
}

void FPhysicsWorld::StepSimulation(float DeltaTime)
{
    if (DeltaTime <= 0.0f)
    {
        return;
    }

    for (TPair<int32, FPhysicsBody>& Pair : Bodies)
    {
        FPhysicsBody& Body = Pair.Value;

        if (Body.bIsStatic)
        {
            continue;
        }

        Body.AddForce(Gravity * Body.Mass);

        Integrate(Body, DeltaTime);
        SolveGroundCollision(Body);
        Body.ClearForces();
    }
}

void FPhysicsWorld::Integrate(FPhysicsBody& Body, float DeltaTime)
{
    const FVector Acceleration = Body.AccumulatedForce * Body.InverseMass;
    Body.Velocity += Acceleration * DeltaTime;
    Body.Velocity *= Body.LinearDamping;
    Body.Position += Body.Velocity * DeltaTime;
}

void FPhysicsWorld::SolveGroundCollision(FPhysicsBody& Body)
{
    const float GroundZ = 0.0f;
    const float MinZ = GroundZ + Body.Radius;

    if (Body.Position.Z < MinZ)
    {
        Body.Position.Z = MinZ;

        if (Body.Velocity.Z < 0.0f)
        {
            Body.Velocity.Z = -Body.Velocity.Z * Body.Restitution;
        }
    }
}
```

