## `CustomPhysicsComponent.cpp`

```cpp
#include "CustomPhysicsComponent.h"
#include "PhysicsSubsystem.h"
#include "PhysicsWorld.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    UWorld* World = GetWorld();
    if (!World)
    {
        return;
    }

    UPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UPhysicsSubsystem>();
    if (!PhysicsSubsystem)
    {
        return;
    }

    BodyId = PhysicsSubsystem->CreateBody(GetOwner()->GetActorLocation(), Mass, bStaticBody);

    if (FPhysicsBody* Body = PhysicsSubsystem->GetPhysicsWorld().GetBody(BodyId))
    {
        Body->Radius = Radius;
    }
}

void UCustomPhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (UWorld* World = GetWorld())
    {
        if (UPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UPhysicsSubsystem>())
        {
            if (BodyId != INDEX_NONE)
            {
                PhysicsSubsystem->RemoveBody(BodyId);
            }
        }
    }

    Super::EndPlay(EndPlayReason);
}

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    UWorld* World = GetWorld();
    if (!World || BodyId == INDEX_NONE)
    {
        return;
    }

    UPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UPhysicsSubsystem>();
    if (!PhysicsSubsystem)
    {
        return;
    }

    const FPhysicsBody* Body = PhysicsSubsystem->GetPhysicsWorld().GetBody(BodyId);
    if (Body && GetOwner())
    {
        GetOwner()->SetActorLocation(Body->Position);
    }
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    UWorld* World = GetWorld();
    if (!World || BodyId == INDEX_NONE)
    {
        return;
    }

    UPhysicsSubsystem* PhysicsSubsystem = World->GetSubsystem<UPhysicsSubsystem>();
    if (!PhysicsSubsystem)
    {
        return;
    }

    if (FPhysicsBody* Body = PhysicsSubsystem->GetPhysicsWorld().GetBody(BodyId))
    {
        Body->AddForce(Force);
    }
}
