# 4. Source implementation

## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody(
        float mass,
        const Transform& transform,
        CollisionShapePtr shape,
        const PhysicsMaterial& material)
        : m_mass(mass)
        , m_transform(transform)
        , m_shape(std::move(shape))
        , m_material(material)
    {
        m_invMass = (m_mass > 0.0f) ? (1.0f / m_mass) : 0.0f;
    }

    void RigidBody::ApplyForce(const Vec3& force)
    {
        if (IsStatic()) return;
        m_accumulatedForce += force;
    }

    void RigidBody::ApplyImpulse(const Vec3& impulse)
    {
        if (IsStatic()) return;
        m_velocity += impulse * m_invMass;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = Vec3();
    }

    void RigidBody::Integrate(float deltaTime, const Vec3& gravity)
    {
        if (IsStatic()) return;

        Vec3 acceleration = gravity + (m_accumulatedForce * m_invMass);
        m_velocity += acceleration * deltaTime;
        m_transform.position += m_velocity * deltaTime;

        ClearForces();
    }
}
```

