## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f)
    {
    }

    RigidBody* PhysicsWorld::CreateRigidBody(
        float mass,
        const Transform& transform,
        CollisionShapePtr shape,
        const PhysicsMaterial& material)
    {
        auto body = std::make_unique<RigidBody>(mass, transform, std::move(shape), material);
        RigidBody* ptr = body.get();
        m_bodies.push_back(std::move(body));
        return ptr;
    }

    void PhysicsWorld::RemoveRigidBody(RigidBody* body)
    {
        m_bodies.erase(
            std::remove_if(m_bodies.begin(), m_bodies.end(),
                [body](const std::unique_ptr<RigidBody>& ptr)
                {
                    return ptr.get() == body;
                }),
            m_bodies.end());
    }

    void PhysicsWorld::StepSimulation(float deltaTime)
    {
        for (auto& body : m_bodies)
        {
            body->Integrate(deltaTime, m_gravity);
        }

        DetectCollisions();
        ResolveCollisions();
    }

    void PhysicsWorld::DetectCollisions()
    {
        m_contacts.clear();

        for (size_t i = 0; i < m_bodies.size(); ++i)
        {
            for (size_t j = i + 1; j < m_bodies.size(); ++j)
            {
                Contact contact;
                if (CheckSphereSphere(m_bodies[i].get(), m_bodies[j].get(), contact))
                {
                    m_contacts.push_back(contact);
                }
            }
        }
    }

    bool PhysicsWorld::CheckSphereSphere(RigidBody* a, RigidBody* b, Contact& contact)
    {
        if (!a || !b) return false;
        if (a->GetShape()->GetType() != ShapeType::Sphere ||
            b->GetShape()->GetType() != ShapeType::Sphere)
        {
            return false;
        }

        auto sphereA = static_cast<SphereShape*>(a->GetShape().get());
        auto sphereB = static_cast<SphereShape*>(b->GetShape().get());

        Vec3 delta = b->GetTransform().position - a->GetTransform().position;
        float distance = delta.Length();
        float radiusSum = sphereA->GetRadius() + sphereB->GetRadius();

        if (distance >= radiusSum)
            return false;

        contact.a = a;
        contact.b = b;
        contact.normal = (distance > 1e-6f) ? delta / distance : Vec3(0.0f, 1.0f, 0.0f);
        contact.penetration = radiusSum - distance;
        return true;
    }

    void PhysicsWorld::ResolveCollisions()
    {
        for (const Contact& contact : m_contacts)
        {
            ResolveContact(contact);
        }
    }

    void PhysicsWorld::ResolveContact(const Contact& contact)
    {
        RigidBody* a = contact.a;
        RigidBody* b = contact.b;
        if (!a || !b) return;

        float invMassA = a->GetInvMass();
        float invMassB = b->GetInvMass();
        float invMassSum = invMassA + invMassB;

        if (invMassSum <= 0.0f)
            return;

        Vec3 relativeVelocity = b->GetVelocity() - a->GetVelocity();
        float velAlongNormal = Vec3::Dot(relativeVelocity, contact.normal);

        if (velAlongNormal > 0.0f)
            return;

        float restitution = std::min(a->GetMaterial().restitution, b->GetMaterial().restitution);

        float j = -(1.0f + restitution) * velAlongNormal;
        j /= invMassSum;

        Vec3 impulse = contact.normal * j;

        a->ApplyImpulse(impulse * -1.0f);
        b->ApplyImpulse(impulse);

        const float percent = 0.8f;
        const float slop = 0.01f;
        float correctionMagnitude = std::max(contact.penetration - slop, 0.0f) / invMassSum * percent;
        Vec3 correction = contact.normal * correctionMagnitude;

        if (!a->IsStatic())
            a->GetTransform().position -= correction * invMassA;
        if (!b->IsStatic())
            b->GetTransform().position += correction * invMassB;
    }
}
```

