# 6. Example engine-side usage

A commercial engine would usually load this DLL/shared object and call exported functions.

Example:

```cpp
#include "IPhysicsPlugin.h"
#include <iostream>

int main()
{
    using namespace CustomPhysics;

    IPhysicsPlugin* plugin = CreatePhysicsPlugin();
    if (!plugin->Initialize())
    {
        std::cout << "Failed to initialize physics plugin\n";
        return 1;
    }

    PhysicsWorld* world = plugin->CreateWorld();

    auto sphere1 = std::make_shared<SphereShape>(1.0f);
    auto sphere2 = std::make_shared<SphereShape>(1.0f);

    RigidBody* bodyA = world->CreateRigidBody(1.0f, { Vec3(0, 5, 0) }, sphere1);
    RigidBody* bodyB = world->CreateRigidBody(1.0f, { Vec3(0, 2, 0) }, sphere2);

    for (int i = 0; i < 120; ++i)
    {
        world->StepSimulation(1.0f / 60.0f);

        const auto& posA = bodyA->GetTransform().position;
        const auto& posB = bodyB->GetTransform().position;

        std::cout << "A: (" << posA.x << ", " << posA.y << ", " << posA.z << ") "
                  << "B: (" << posB.x << ", " << posB.y << ", " << posB.z << ")\n";
    }

    plugin->DestroyWorld(world);
    plugin->Shutdown();
    DestroyPhysicsPlugin(plugin);

    return 0;
}
