struct FVector3
{
    float X = 0.0f;
    float Y = 0.0f;
    float Z = 0.0f;

    FVector3() = default;
    FVector3(float x, float y, float z) : X(x), Y(y), Z(z) {}

    FVector3 operator+(const FVector3& Other) const
    {
        return FVector3(X + Other.X, Y + Other.Y, Z + Other.Z);
    }

    FVector3 operator-(const FVector3& Other) const
    {
        return FVector3(X - Other.X, Y - Other.Y, Z - Other.Z);
    }

    FVector3 operator*(float Scalar) const
    {
        return FVector3(X * Scalar, Y * Scalar, Z * Scalar);
    }

    FVector3& operator+=(const FVector3& Other)
    {
        X += Other.X;
        Y += Other.Y;
        Z += Other.Z;
        return *this;
    }

    FVector3& operator*=(float Scalar)
    {
        X *= Scalar;
        Y *= Scalar;
        Z *= Scalar;
        return *this;
    }

    float Length() const
    {
        return std::sqrt(X * X + Y * Y + Z * Z);
    }

    static FVector3 Zero()
    {
        return FVector3(0.0f, 0.0f, 0.0f);
    }
};
