    void ClearForces();

    void Integrate(float DeltaTime, const FVector3& Gravity);

    bool IsStatic() const { return InverseMass == 0.0f; }

private:
    uint64_t Id = 0;

    FVector3 Position = FVector3::Zero();
    FVector3 Velocity = FVector3::Zero();
    FVector3 AccumulatedForce = FVector3::Zero();

    float Mass = 1.0f;
    float InverseMass = 1.0f;
};
