## `PhysicsBody.cpp`

```cpp
#include "PhysicsBody.h"
#include <algorithm>

FPhysicsBody::FPhysicsBody(uint64_t InId)
    : Id(InId)
{
}

void FPhysicsBody::SetMass(float InMass)
{
    Mass = std::max(InMass, 0.0f);

    if (Mass <= 0.0f)
    {
        InverseMass = 0.0f; // static/infinite mass
    }
    else
    {
        InverseMass = 1.0f / Mass;
    }
}

void FPhysicsBody::AddForce(const FVector3& Force)
{
    AccumulatedForce += Force;
}

void FPhysicsBody::ClearForces()
{
    AccumulatedForce = FVector3::Zero();
}

void FPhysicsBody::Integrate(float DeltaTime, const FVector3& Gravity)
{
    if (IsStatic() || DeltaTime <= 0.0f)
    {
        ClearForces();
        return;
    }

    FVector3 Acceleration = Gravity + (AccumulatedForce * InverseMass);

    Velocity += Acceleration * DeltaTime;
    Position += Velocity * DeltaTime;

    ClearForces();
}
