    uint64_t NextBodyId = 1;
    FVector3 Gravity = FVector3(0.0f, 0.0f, -980.0f); // cm/s^2 style gravity

    std::unordered_map<uint64_t, std::unique_ptr<FPhysicsBody>> Bodies;
};
