## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"

FPhysicsWorld::FPhysicsWorld()
{
}

uint64_t FPhysicsWorld::CreateBody(float Mass, const FVector3& InitialPosition)
{
    const uint64_t NewId = NextBodyId++;

    auto Body = std::make_unique<FPhysicsBody>(NewId);
    Body->SetMass(Mass);
    Body->SetPosition(InitialPosition);

    Bodies.emplace(NewId, std::move(Body));
    return NewId;
}

bool FPhysicsWorld::RemoveBody(uint64_t BodyId)
{
    return Bodies.erase(BodyId) > 0;
}

FPhysicsBody* FPhysicsWorld::GetBody(uint64_t BodyId)
{
    auto It = Bodies.find(BodyId);
    return (It != Bodies.end()) ? It->second.get() : nullptr;
}

const FPhysicsBody* FPhysicsWorld::GetBody(uint64_t BodyId) const
{
    auto It = Bodies.find(BodyId);
    return (It != Bodies.end()) ? It->second.get() : nullptr;
}

void FPhysicsWorld::AddForce(uint64_t BodyId, const FVector3& Force)
{
    if (FPhysicsBody* Body = GetBody(BodyId))
    {
        Body->AddForce(Force);
    }
}

void FPhysicsWorld::StepSimulation(float DeltaTime)
{
    for (auto& Pair : Bodies)
    {
        Pair.second->Integrate(DeltaTime, Gravity);
    }
}

std::vector<uint64_t> FPhysicsWorld::GetBodyIds() const
{
    std::vector<uint64_t> Ids;
    Ids.reserve(Bodies.size());

    for (const auto& Pair : Bodies)
    {
        Ids.push_back(Pair.first);
    }

    return Ids;
}
