## `Source/PhysicsBody.cpp`

```cpp
#include "PhysicsBody.h"

PhysicsBody::PhysicsBody(BodyId id, float mass, const Vec3& initialPosition)
    : m_id(id)
    , m_mass(mass)
    , m_inverseMass(mass > 0.0f ? 1.0f / mass : 0.0f)
    , m_position(initialPosition)
    , m_velocity(0.0f, 0.0f, 0.0f)
    , m_accumulatedForce(0.0f, 0.0f, 0.0f)
{
}

PhysicsBody::BodyId PhysicsBody::GetId() const
{
    return m_id;
}

void PhysicsBody::SetPosition(const Vec3& p)
{
    m_position = p;
}

const Vec3& PhysicsBody::GetPosition() const
{
    return m_position;
}

void PhysicsBody::SetVelocity(const Vec3& v)
{
    m_velocity = v;
}

const Vec3& PhysicsBody::GetVelocity() const
{
    return m_velocity;
}

void PhysicsBody::AddForce(const Vec3& force)
{
    if (!IsStatic())
    {
        m_accumulatedForce += force;
    }
}

void PhysicsBody::ClearForces()
{
    m_accumulatedForce = Vec3(0.0f, 0.0f, 0.0f);
}

float PhysicsBody::GetMass() const
{
    return m_mass;
}

float PhysicsBody::GetInverseMass() const
{
    return m_inverseMass;
}

bool PhysicsBody::IsStatic() const
{
    return m_inverseMass == 0.0f;
}

void PhysicsBody::Integrate(float deltaTime, const Vec3& gravity)
{
    if (IsStatic())
    {
        return;
    }

    Vec3 acceleration = gravity + (m_accumulatedForce * m_inverseMass);

    m_velocity += acceleration * deltaTime;
    m_position += m_velocity * deltaTime;

    ClearForces();
}
```

