# 5. Physics world

This manages all bodies and performs the simulation step.

## `Include/PhysicsWorld.h`

```cpp
#pragma once

#include "PhysicsBody.h"
#include <unordered_map>
#include <memory>

class PhysicsWorld
{
public:
    PhysicsWorld();

    PhysicsBody::BodyId CreateBody(float mass, const Vec3& position);
    void RemoveBody(PhysicsBody::BodyId id);

    PhysicsBody* GetBody(PhysicsBody::BodyId id);
    const PhysicsBody* GetBody(PhysicsBody::BodyId id) const;

    void StepSimulation(float deltaTime);

    void SetGravity(const Vec3& gravity);
    const Vec3& GetGravity() const;

private:
    void SolveGroundCollision(PhysicsBody& body);

private:
    std::unordered_map<PhysicsBody::BodyId, std::unique_ptr<PhysicsBody>> m_bodies;
    PhysicsBody::BodyId m_nextBodyId;
    Vec3 m_gravity;
