## `Source/PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"

PhysicsWorld::PhysicsWorld()
    : m_nextBodyId(1)
    , m_gravity(0.0f, -9.81f, 0.0f)
{
}

PhysicsBody::BodyId PhysicsWorld::CreateBody(float mass, const Vec3& position)
{
    PhysicsBody::BodyId newId = m_nextBodyId++;
    m_bodies[newId] = std::make_unique<PhysicsBody>(newId, mass, position);
    return newId;
}

void PhysicsWorld::RemoveBody(PhysicsBody::BodyId id)
{
    m_bodies.erase(id);
}

PhysicsBody* PhysicsWorld::GetBody(PhysicsBody::BodyId id)
{
    auto it = m_bodies.find(id);
    if (it != m_bodies.end())
    {
        return it->second.get();
    }
    return nullptr;
}

const PhysicsBody* PhysicsWorld::GetBody(PhysicsBody::BodyId id) const
{
    auto it = m_bodies.find(id);
    if (it != m_bodies.end())
    {
        return it->second.get();
    }
    return nullptr;
}

void PhysicsWorld::StepSimulation(float deltaTime)
{
    for (auto& pair : m_bodies)
    {
        PhysicsBody& body = *pair.second;
        body.Integrate(deltaTime, m_gravity);
        SolveGroundCollision(body);
    }
}

void PhysicsWorld::SetGravity(const Vec3& gravity)
{
    m_gravity = gravity;
}

const Vec3& PhysicsWorld::GetGravity() const
{
    return m_gravity;
}

void PhysicsWorld::SolveGroundCollision(PhysicsBody& body)
{
    if (body.IsStatic())
    {
        return;
    }

    Vec3 position = body.GetPosition();
    Vec3 velocity = body.GetVelocity();

    if (position.y < 0.0f)
    {
        position.y = 0.0f;

        if (velocity.y < 0.0f)
        {
            velocity.y *= -0.5f;
        }

        body.SetPosition(position);
        body.SetVelocity(velocity);
    }
}
```

