enum class EBodyType : uint8_t
{
    Static,
    Dynamic
};

struct PhysicsBodyDesc
{
    EBodyType Type = EBodyType::Dynamic;
    float Mass = 1.0f;
    Vec3 Position = Vec3(0, 0, 0);
    Vec3 Velocity = Vec3(0, 0, 0);
    bool EnableGravity = true;
};

class PhysicsBody
{
public:
    explicit PhysicsBody(const PhysicsBodyDesc& desc);

    void AddForce(const Vec3& force);
    void ClearForces();

    void Integrate(float dt, const Vec3& gravity);

    const Vec3& GetPosition() const { return Position; }
    const Vec3& GetVelocity() const { return Velocity; }

    void SetPosition(const Vec3& p) { Position = p; }
    void SetVelocity(const Vec3& v) { Velocity = v; }

    EBodyType GetType() const { return Type; }
    float GetMass() const { return Mass; }
    bool IsGravityEnabled() const { return bEnableGravity; }

private:
    EBodyType Type;
    float Mass;
    float InvMass;
    bool bEnableGravity;

    Vec3 Position;
    Vec3 Velocity;
    Vec3 ForceAccum;
};
```

## `PhysicsBody.cpp`

```cpp
#include "PhysicsBody.h"

PhysicsBody::PhysicsBody(const PhysicsBodyDesc& desc)
    : Type(desc.Type)
    , Mass(desc.Mass)
    , InvMass((desc.Type == EBodyType::Dynamic && desc.Mass > 0.0f) ? 1.0f / desc.Mass : 0.0f)
    , bEnableGravity(desc.EnableGravity)
    , Position(desc.Position)
    , Velocity(desc.Velocity)
    , ForceAccum(0, 0, 0)
{
}

void PhysicsBody::AddForce(const Vec3& force)
{
    if (Type == EBodyType::Dynamic)
    {
        ForceAccum += force;
    }
}

void PhysicsBody::ClearForces()
{
    ForceAccum = Vec3(0, 0, 0);
}

void PhysicsBody::Integrate(float dt, const Vec3& gravity)
{
    if (Type != EBodyType::Dynamic || dt <= 0.0f)
    {
        return;
    }

    Vec3 totalAcceleration = ForceAccum * InvMass;

    if (bEnableGravity)
    {
        totalAcceleration += gravity;
    }

    Velocity += totalAcceleration * dt;
    Position += Velocity * dt;

    ClearForces();
}
```

