## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

PhysicsWorld::PhysicsWorld()
    : Gravity(0.0f, 0.0f, -980.0f) // cm/s^2 style gravity
{
}

PhysicsWorld::~PhysicsWorld() = default;

PhysicsBody* PhysicsWorld::CreateBody(const PhysicsBodyDesc& desc)
{
    Bodies.push_back(std::make_unique<PhysicsBody>(desc));
    return Bodies.back().get();
}

void PhysicsWorld::DestroyBody(PhysicsBody* body)
{
    Bodies.erase(
        std::remove_if(Bodies.begin(), Bodies.end(),
            [body](const std::unique_ptr<PhysicsBody>& ptr)
            {
                return ptr.get() == body;
            }),
        Bodies.end());
}

void PhysicsWorld::StepSimulation(float dt)
{
    for (auto& bodyPtr : Bodies)
    {
        PhysicsBody& body = *bodyPtr;
        body.Integrate(dt, Gravity);
        SolveGroundPlaneCollision(body);
    }
}

void PhysicsWorld::SolveGroundPlaneCollision(PhysicsBody& body)
{
    if (body.GetType() != EBodyType::Dynamic)
    {
        return;
    }

    Vec3 pos = body.GetPosition();
    Vec3 vel = body.GetVelocity();

    // Simple ground plane at Z = 0
    if (pos.z < 0.0f)
    {
        pos.z = 0.0f;

        if (vel.z < 0.0f)
        {
            vel.z *= -0.25f; // crude restitution
        }

        // crude horizontal damping on contact
        vel.x *= 0.95f;
        vel.y *= 0.95f;

        body.SetPosition(pos);
        body.SetVelocity(vel);
    }
}
