## `PhysicsComponent.cpp`

```cpp
#include "PhysicsComponent.h"

PhysicsComponent::PhysicsComponent(PhysicsWorld* inWorld, EngineTransform* inTransform)
    : World(inWorld)
    , Transform(inTransform)
{
}

PhysicsComponent::~PhysicsComponent()
{
    Shutdown();
}

void PhysicsComponent::Initialize(const PhysicsBodyDesc& desc)
{
    if (!World || !Transform || Body)
    {
        return;
    }

    PhysicsBodyDesc bodyDesc = desc;
    bodyDesc.Position = Transform->GetWorldPosition();
    Body = World->CreateBody(bodyDesc);
}

void PhysicsComponent::Shutdown()
{
    if (World && Body)
    {
        World->DestroyBody(Body);
        Body = nullptr;
    }
}

void PhysicsComponent::AddForce(const Vec3& force)
{
    if (Body)
    {
        Body->AddForce(force);
    }
}

void PhysicsComponent::SyncToPhysics()
{
    if (Body && Transform)
    {
        Body->SetPosition(Transform->GetWorldPosition());
    }
}

void PhysicsComponent::SyncFromPhysics()
{
    if (Body && Transform)
    {
        Transform->SetWorldPosition(Body->GetPosition());
    }
}
