# 10. Better initial version: fixed timestep plugin tick

A more correct plugin tick loop would look like this:

```cpp
class CustomPhysicsPlugin final : public ICustomPhysicsPlugin
{
public:
    bool Startup() override
    {
        World = std::make_unique<PhysicsWorld>();
        Accumulator = 0.0f;
        FixedTimeStep = 1.0f / 60.0f;
        return true;
    }

    void Shutdown() override
    {
        World.reset();
    }

    void Tick(float DeltaTime) override
    {
        if (!World)
        {
            return;
        }

        Accumulator += DeltaTime;

        while (Accumulator >= FixedTimeStep)
        {
            World->StepSimulation(FixedTimeStep);
            Accumulator -= FixedTimeStep;
        }
    }

    PhysicsWorld* GetWorld() const { return World.get(); }

private:
    std::unique_ptr<PhysicsWorld> World;
    float Accumulator = 0.0f;
    float FixedTimeStep = 1.0f / 60.0f;
};
```

