## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody(BodyId id, const RigidBodyDesc& desc)
        : m_id(id)
        , m_type(desc.type)
        , m_position(desc.position)
        , m_velocity(desc.velocity)
        , m_mass(desc.mass)
        , m_restitution(desc.restitution)
        , m_friction(desc.friction)
        , m_shape(desc.shape)
    {
        if (m_type != BodyType::Dynamic || m_mass <= 0.0f)
        {
            m_mass = 0.0f;
            m_invMass = 0.0f;
        }
        else
        {
            m_invMass = 1.0f / m_mass;
        }
    }

    void RigidBody::AddForce(const Vec3& force)
    {
        if (m_type == BodyType::Dynamic)
        {
            m_accumulatedForce += force;
        }
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = Vec3(0, 0, 0);
    }

    void RigidBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic)
            return;

        Vec3 acceleration = gravity + (m_accumulatedForce * m_invMass);
        m_velocity += acceleration * dt;
        m_position += m_velocity * dt;

        ClearForces();
    }
}
