#include "PhysicsWorld.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld() = default;
    PhysicsWorld::~PhysicsWorld() = default;

    void PhysicsWorld::SetGravity(const Vec3& gravity)
    {
        m_gravity = gravity;
    }

    const Vec3& PhysicsWorld::GetGravity() const
    {
        return m_gravity;
    }

    BodyId PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
    {
        BodyId id = m_nextBodyId++;
        m_bodies[id] = std::make_unique<RigidBody>(id, desc);
        return id;
    }

    void PhysicsWorld::DestroyBody(BodyId id)
    {
        m_bodies.erase(id);
    }

    RigidBody* PhysicsWorld::GetBody(BodyId id)
    {
        auto it = m_bodies.find(id);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    const RigidBody* PhysicsWorld::GetBody(BodyId id) const
    {
        auto it = m_bodies.find(id);
        return (it != m_bodies.end()) ? it->second.get() : nullptr;
    }

    void PhysicsWorld::StepSimulation(float dt)
    {
        constexpr float maxStep = 1.0f / 30.0f;
        dt = std::min(dt, maxStep);

        for (auto& [id, body] : m_bodies)
        {
            body->Integrate(dt, m_gravity);
        }

        DetectCollisions();
        ResolveCollisions();
    }

    void PhysicsWorld::DetectCollisions()
    {
        m_contacts.clear();

        for (auto itA = m_bodies.begin(); itA != m_bodies.end(); ++itA)
        {
            auto itB = itA;
            ++itB;

            for (; itB != m_bodies.end(); ++itB)
            {
                RigidBody& a = *itA->second;
                RigidBody& b = *itB->second;

                Contact contact;
                if (CheckSphereSphere(a, b, contact))
                {
                    m_contacts.push_back(contact);
                }
            }
        }
    }

    bool PhysicsWorld::CheckSphereSphere(const RigidBody& a, const RigidBody& b, Contact& outContact)
    {
        if (a.GetShape().type != ShapeType::Sphere || b.GetShape().type != ShapeType::Sphere)
            return false;

        Vec3 delta = b.GetPosition() - a.GetPosition();
        float distSq = LengthSq(delta);
        float radiusSum = a.GetShape().sphere.radius + b.GetShape().sphere.radius;

        if (distSq > radiusSum * radiusSum)
            return false;

        float dist = std::sqrt(distSq);
        Vec3 normal = (dist > 1e-6f) ? (delta * (1.0f / dist)) : Vec3(0, 1, 0);

        outContact.a = a.GetId();
        outContact.b = b.GetId();
        outContact.normal = normal;
        outContact.penetration = radiusSum - dist;
        outContact.point = a.GetPosition() + normal * a.GetShape().sphere.radius;

        return true;
    }

    void PhysicsWorld::ResolveCollisions()
    {
        for (const Contact& contact : m_contacts)
        {
            ResolveContact(contact);
        }
    }

    void PhysicsWorld::ResolveContact(const Contact& contact)
    {
        RigidBody* a = GetBody(contact.a);
        RigidBody* b = GetBody(contact.b);

        if (!a || !b)
            return;

        float invMassA = a->GetInvMass();
        float invMassB = b->GetInvMass();
        float invMassSum = invMassA + invMassB;

        if (invMassSum <= 0.0f)
            return;

        Vec3 relativeVelocity = b->GetVelocity() - a->GetVelocity();
        float velAlongNormal = Dot(relativeVelocity, contact.normal);

        if (velAlongNormal > 0.0f)
            return;

        float restitution = std::min(a->GetRestitution(), b->GetRestitution());

        float impulseScalar = -(1.0f + restitution) * velAlongNormal;
        impulseScalar /= invMassSum;

        Vec3 impulse = contact.normal * impulseScalar;

        a->SetVelocity(a->GetVelocity() - impulse * invMassA);
        b->SetVelocity(b->GetVelocity() + impulse * invMassB);

        constexpr float percent = 0.8f;
        constexpr float slop = 0.01f;

        float correctionMagnitude = std::max(contact.penetration - slop, 0.0f) / invMassSum * percent;
        Vec3 correction = contact.normal * correctionMagnitude;

        a->SetPosition(a->GetPosition() - correction * invMassA);
        b->SetPosition(b->GetPosition() + correction * invMassB);
    }
}
