#pragma once
#include "PhysicsTypes.h"

namespace CustomPhysics
{
    class Collider
    {
    public:
        virtual ~Collider() = default;
        virtual ColliderType GetType() const = 0;
        virtual AABB ComputeAABB(const Transform& worldTransform) const = 0;
    };

    class SphereCollider : public Collider
    {
    public:
        float radius = 50.0f;

        explicit SphereCollider(float r) : radius(r) {}

        ColliderType GetType() const override
        {
            return ColliderType::Sphere;
        }

        AABB ComputeAABB(const Transform& t) const override
        {
            Vec3 ext(radius, radius, radius);
            return { t.position - ext, t.position + ext };
        }
    };

    class BoxCollider : public Collider
    {
    public:
        Vec3 halfExtents = Vec3(50, 50, 50);

        explicit BoxCollider(const Vec3& he) : halfExtents(he) {}

        ColliderType GetType() const override
        {
            return ColliderType::Box;
        }

        AABB ComputeAABB(const Transform& t) const override
        {
            return { t.position - halfExtents, t.position + halfExtents };
        }
    };
}
