#pragma once
#include "PhysicsTypes.h"
#include "Collider.h"

namespace CustomPhysics
{
    class RigidBody
    {
    public:
        BodyID id = 0;
        Transform transform;
        Vec3 linearVelocity;
        Vec3 accumulatedForce;

        float mass = 1.0f;
        float inverseMass = 1.0f;
        float restitution = 0.2f;
        bool isStatic = false;

        std::unique_ptr<Collider> collider;

        RigidBody() = default;

        void SetMass(float m)
        {
            mass = m;
            if (isStatic || m <= 1e-6f)
            {
                inverseMass = 0.0f;
            }
            else
            {
                inverseMass = 1.0f / m;
            }
        }

        void SetStatic(bool value)
        {
            isStatic = value;
            inverseMass = isStatic ? 0.0f : (mass > 1e-6f ? 1.0f / mass : 0.0f);
        }

        void AddForce(const Vec3& force)
        {
            if (!isStatic)
            {
                accumulatedForce += force;
            }
        }

        void ClearForces()
        {
            accumulatedForce = Vec3(0, 0, 0);
        }
    };
}
