## `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <cassert>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
    {
    }

    BodyID PhysicsWorld::CreateBody(std::unique_ptr<Collider> collider,
                                    const Transform& transform,
                                    float mass,
                                    bool isStatic)
    {
        RigidBody body;
        body.id = nextBodyID++;
        body.transform = transform;
        body.collider = std::move(collider);
        body.SetStatic(isStatic);
        body.SetMass(mass);

        if (isStatic)
        {
            body.inverseMass = 0.0f;
        }

        bodies.push_back(std::move(body));
        return bodies.back().id;
    }

    void PhysicsWorld::DestroyBody(BodyID id)
    {
        bodies.erase(
            std::remove_if(bodies.begin(), bodies.end(),
                [id](const RigidBody& b) { return b.id == id; }),
            bodies.end());
    }

    RigidBody* PhysicsWorld::GetBody(BodyID id)
    {
        for (auto& body : bodies)
        {
            if (body.id == id)
                return &body;
        }
        return nullptr;
    }

    const RigidBody* PhysicsWorld::GetBody(BodyID id) const
    {
        for (const auto& body : bodies)
        {
            if (body.id == id)
                return &body;
        }
        return nullptr;
    }

    void PhysicsWorld::SetGravity(const Vec3& g)
    {
        gravity = g;
    }

    void PhysicsWorld::Step(float deltaTime)
    {
        Integrate(deltaTime);

        std::vector<Contact> contacts;
        DetectCollisions(contacts);
        ResolveContacts(contacts);

        for (auto& body : bodies)
        {
            body.ClearForces();
        }
    }

    void PhysicsWorld::Integrate(float dt)
    {
        for (auto& body : bodies)
        {
            if (body.isStatic)
                continue;

            Vec3 acceleration = gravity + body.accumulatedForce * body.inverseMass;
            body.linearVelocity += acceleration * dt;
            body.transform.position += body.linearVelocity * dt;
        }
    }

    void PhysicsWorld::DetectCollisions(std::vector<Contact>& contacts)
    {
        const size_t count = bodies.size();
        for (size_t i = 0; i < count; ++i)
        {
            for (size_t j = i + 1; j < count; ++j)
            {
                if (bodies[i].isStatic && bodies[j].isStatic)
                    continue;

                Contact contact;
                if (Intersect(bodies[i], bodies[j], contact))
                {
                    contacts.push_back(contact);
                }
            }
        }
    }

    bool PhysicsWorld::Intersect(const RigidBody& a, const RigidBody& b, Contact& outContact) const
    {
        const ColliderType typeA = a.collider->GetType();
        const ColliderType typeB = b.collider->GetType();

        if (typeA == ColliderType::Sphere && typeB == ColliderType::Sphere)
        {
            return SphereSphere(a, b, outContact);
        }

        if (typeA == ColliderType::Box && typeB == ColliderType::Box)
        {
            return AABBAABB(a, b, outContact);
        }

        // Initial version: mixed shape pairs not yet supported.
        return false;
    }

    bool PhysicsWorld::SphereSphere(const RigidBody& a, const RigidBody& b, Contact& outContact) const
    {
        const SphereCollider* sphereA = static_cast<const SphereCollider*>(a.collider.get());
        const SphereCollider* sphereB = static_cast<const SphereCollider*>(b.collider.get());

        Vec3 delta = b.transform.position - a.transform.position;
        float distSq = delta.LengthSq();
        float radiusSum = sphereA->radius + sphereB->radius;

        if (distSq > radiusSum * radiusSum)
            return false;

        float dist = std::sqrt(distSq);
        Vec3 normal = (dist > 1e-6f) ? delta / dist : Vec3(1, 0, 0);
        float penetration = radiusSum - dist;

        outContact.a = a.id;
        outContact.b = b.id;
        outContact.normal = normal;
        outContact.penetration = penetration;
        return true;
    }

    bool PhysicsWorld::AABBAABB(const RigidBody& a, const RigidBody& b, Contact& outContact) const
    {
        AABB aabbA = a.collider->ComputeAABB(a.transform);
        AABB aabbB = b.collider->ComputeAABB(b.transform);

        if (aabbA.max.x < aabbB.min.x || aabbA.min.x > aabbB.max.x) return false;
        if (aabbA.max.y < aabbB.min.y || aabbA.min.y > aabbB.max.y) return false;
        if (aabbA.max.z < aabbB.min.z || aabbA.min.z > aabbB.max.z) return false;

        float overlapX = std::min(aabbA.max.x, aabbB.max.x) - std::max(aabbA.min.x, aabbB.min.x);
        float overlapY = std::min(aabbA.max.y, aabbB.max.y) - std::max(aabbA.min.y, aabbB.min.y);
        float overlapZ = std::min(aabbA.max.z, aabbB.max.z) - std::max(aabbA.min.z, aabbB.min.z);

        float penetration = overlapX;
        Vec3 normal((a.transform.position.x < b.transform.position.x) ? -1.0f : 1.0f, 0, 0);

        if (overlapY < penetration)
        {
            penetration = overlapY;
            normal = Vec3(0, (a.transform.position.y < b.transform.position.y) ? -1.0f : 1.0f, 0);
        }

        if (overlapZ < penetration)
        {
            penetration = overlapZ;
            normal = Vec3(0, 0, (a.transform.position.z < b.transform.position.z) ? -1.0f : 1.0f);
        }

        outContact.a = a.id;
        outContact.b = b.id;
        outContact.normal = normal * -1.0f;
        outContact.penetration = penetration;
        return true;
    }

    void PhysicsWorld::ResolveContacts(std::vector<Contact>& contacts)
    {
        const float percent = 0.8f;
        const float slop = 0.01f;

        for (const Contact& contact : contacts)
        {
            RigidBody* a = GetBody(contact.a);
            RigidBody* b = GetBody(contact.b);
            if (!a || !b) continue;

            Vec3 rv = b->linearVelocity - a->linearVelocity;
            float velAlongNormal = Vec3::Dot(rv, contact.normal);

            if (velAlongNormal > 0.0f)
                continue;

            float e = std::min(a->restitution, b->restitution);
            float invMassSum = a->inverseMass + b->inverseMass;
            if (invMassSum <= 1e-6f)
                continue;

            float j = -(1.0f + e) * velAlongNormal;
            j /= invMassSum;

            Vec3 impulse = contact.normal * j;

            if (!a->isStatic)
                a->linearVelocity -= impulse * a->inverseMass;
            if (!b->isStatic)
                b->linearVelocity += impulse * b->inverseMass;

            float correctionMagnitude = std::max(contact.penetration - slop, 0.0f) / invMassSum * percent;
            Vec3 correction = contact.normal * correctionMagnitude;

            if (!a->isStatic)
                a->transform.position -= correction * a->inverseMass;
            if (!b->isStatic)
                b->transform.position += correction * b->inverseMass;
        }
    }
}
```

