#include "PhysicsAPI.h"

namespace CustomPhysics
{
    PhysicsAPI& PhysicsAPI::Get()
    {
        static PhysicsAPI instance;
        return instance;
    }

    bool PhysicsAPI::Initialize()
    {
        initialized = true;
        return true;
    }

    void PhysicsAPI::Shutdown()
    {
        initialized = false;
    }

    void PhysicsAPI::Tick(float deltaTime)
    {
        if (!initialized) return;
        world.Step(deltaTime);
    }

    BodyID PhysicsAPI::CreateSphereBody(const Vec3& position, float radius, float mass, bool isStatic)
    {
