        t.position = position;
        return world.CreateBody(std::make_unique<SphereCollider>(radius), t, mass, isStatic);
    }

    BodyID PhysicsAPI::CreateBoxBody(const Vec3& position, const Vec3& halfExtents, float mass, bool isStatic)
    {
        Transform t;
        t.position = position;
        return world.CreateBody(std::make_unique<BoxCollider>(halfExtents), t, mass, isStatic);
    }

    void PhysicsAPI::DestroyBody(BodyID id)
    {
        world.DestroyBody(id);
    }

    void PhysicsAPI::AddForce(BodyID id, const Vec3& force)
    {
        if (RigidBody* body = world.GetBody(id))
        {
            body->AddForce(force);
