# 8. Physics component source: `CustomPhysicsComponent.cpp`

```cpp
#include "CustomPhysicsComponent.h"
#include "CustomPhysicsWorldSubsystem.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (UWorld* World = GetWorld())
    {
        if (UCustomPhysicsWorldSubsystem* Subsystem = World->GetSubsystem<UCustomPhysicsWorldSubsystem>())
        {
            Subsystem->RegisterComponent(this);
        }
    }
}

void UCustomPhysicsComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (UWorld* World = GetWorld())
    {
        if (UCustomPhysicsWorldSubsystem* Subsystem = World->GetSubsystem<UCustomPhysicsWorldSubsystem>())
        {
            Subsystem->UnregisterComponent(this);
        }
    }

    Super::EndPlay(EndPlayReason);
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsComponent::AddImpulse(FVector Impulse)
{
    if (Mass > KINDA_SMALL_NUMBER)
    {
        Velocity += Impulse / Mass;
    }
}

void UCustomPhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

void UCustomPhysicsComponent::SimulateCustomPhysics(float DeltaTime)
{
    if (!bSimulate || DeltaTime <= 0.0f)
    {
        AccumulatedForce = FVector::ZeroVector;
        return;
    }

    AActor* Owner = GetOwner();
    if (!IsValid(Owner))
    {
        AccumulatedForce = FVector::ZeroVector;
        return;
    }

    if (Mass <= KINDA_SMALL_NUMBER)
    {
        AccumulatedForce = FVector::ZeroVector;
        return;
    }

    FVector Acceleration = Gravity + (AccumulatedForce / Mass);

    Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;

    if (NewLocation.Z < GroundHeight)
    {
        NewLocation.Z = GroundHeight;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = -Velocity.Z * Restitution;
        }
    }

    Owner->SetActorLocation(NewLocation, false);

    AccumulatedForce = FVector::ZeroVector;
}
```

