# Optional improved version: fixed-step simulation in component

Here is a small upgrade for more stable simulation.

Add to component header:

```cpp
private:
    float TimeAccumulator = 0.0f;
    void SimulateStep(float StepTime);
```

Then update source:

```cpp
void UCustomPhysicsComponent::SimulateCustomPhysics(float DeltaTime)
{
    if (!bSimulate || DeltaTime <= 0.0f)
    {
        AccumulatedForce = FVector::ZeroVector;
        return;
    }

    TimeAccumulator += DeltaTime;
    constexpr float FixedStep = 1.0f / 60.0f;
    constexpr float MaxAccumulatedTime = 0.25f;

    TimeAccumulator = FMath::Min(TimeAccumulator, MaxAccumulatedTime);

    while (TimeAccumulator >= FixedStep)
    {
        SimulateStep(FixedStep);
        TimeAccumulator -= FixedStep;
    }

    AccumulatedForce = FVector::ZeroVector;
}

void UCustomPhysicsComponent::SimulateStep(float DeltaTime)
{
    AActor* Owner = GetOwner();
    if (!IsValid(Owner) || Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    FVector Acceleration = Gravity + (AccumulatedForce / Mass);
    Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;

    if (NewLocation.Z < GroundHeight)
    {
        NewLocation.Z = GroundHeight;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = -Velocity.Z * Restitution;
        }
    }

    Owner->SetActorLocation(NewLocation, false);
}
```

Note: in a more correct fixed-step system, force accumulation should be handled carefully across substeps.

