## `RigidBody.h`

```cpp
#pragma once

#include "MathTypes.h"
#include <cstdint>

enum class EBodyType : uint8_t
{
    Static,
    Dynamic,
    Kinematic
};

class RigidBody
{
public:
    RigidBody();
    ~RigidBody() = default;

    void SetBodyType(EBodyType InType);
    EBodyType GetBodyType() const;

    void SetMass(float InMass);
    float GetMass() const;

    void SetTransform(const Transform& InTransform);
    const Transform& GetTransform() const;

    void SetLinearVelocity(const Vec3& InVelocity);
    const Vec3& GetLinearVelocity() const;

    void AddForce(const Vec3& Force);
    void ClearForces();

    void SetGravityScale(float InScale);
    float GetGravityScale() const;

    void SetLinearDamping(float InDamping);
    float GetLinearDamping() const;

    void Integrate(float DeltaTime, const Vec3& Gravity);

private:
    EBodyType BodyType;
    float Mass;
    float InverseMass;
    float GravityScale;
    float LinearDamping;

    Transform WorldTransform;
    Vec3 LinearVelocity;
    Vec3 AccumulatedForce;
};
```

## `RigidBody.cpp`

```cpp
#include "RigidBody.h"
#include <algorithm>

RigidBody::RigidBody()
    : BodyType(EBodyType::Dynamic)
    , Mass(1.0f)
    , InverseMass(1.0f)
    , GravityScale(1.0f)
    , LinearDamping(0.01f)
{
}

void RigidBody::SetBodyType(EBodyType InType)
{
    BodyType = InType;

    if (BodyType == EBodyType::Static)
    {
        InverseMass = 0.0f;
    }
    else if (Mass > 0.0f)
    {
        InverseMass = 1.0f / Mass;
    }
}

EBodyType RigidBody::GetBodyType() const
{
    return BodyType;
}

void RigidBody::SetMass(float InMass)
{
    Mass = std::max(InMass, 0.0001f);

    if (BodyType == EBodyType::Static)
    {
        InverseMass = 0.0f;
    }
    else
    {
        InverseMass = 1.0f / Mass;
    }
}

float RigidBody::GetMass() const
{
    return Mass;
}

void RigidBody::SetTransform(const Transform& InTransform)
{
    WorldTransform = InTransform;
}

const Transform& RigidBody::GetTransform() const
{
    return WorldTransform;
}

void RigidBody::SetLinearVelocity(const Vec3& InVelocity)
{
    LinearVelocity = InVelocity;
}

const Vec3& RigidBody::GetLinearVelocity() const
{
    return LinearVelocity;
}

void RigidBody::AddForce(const Vec3& Force)
{
    if (BodyType == EBodyType::Dynamic)
    {
        AccumulatedForce += Force;
    }
}

void RigidBody::ClearForces()
{
    AccumulatedForce = Vec3();
}

void RigidBody::SetGravityScale(float InScale)
{
    GravityScale = InScale;
}

float RigidBody::GetGravityScale() const
{
    return GravityScale;
}

void RigidBody::SetLinearDamping(float InDamping)
{
    LinearDamping = std::max(0.0f, InDamping);
}

float RigidBody::GetLinearDamping() const
{
    return LinearDamping;
}

void RigidBody::Integrate(float DeltaTime, const Vec3& Gravity)
{
    if (BodyType != EBodyType::Dynamic || InverseMass <= 0.0f)
    {
        ClearForces();
        return;
    }

    Vec3 Acceleration = (AccumulatedForce * InverseMass) + (Gravity * GravityScale);
    LinearVelocity += Acceleration * DeltaTime;

    float DampingFactor = std::max(0.0f, 1.0f - LinearDamping * DeltaTime);
    LinearVelocity *= DampingFactor;

    WorldTransform.position += LinearVelocity * DeltaTime;

    ClearForces();
}
```

