#include "PhysicsWorld.h"
#include <algorithm>

PhysicsWorld::PhysicsWorld()
    : Gravity(0.0f, 0.0f, -980.0f) // cm/s^2 style gravity
{
}

RigidBody* PhysicsWorld::CreateRigidBody()
{
    auto NewBody = std::make_unique<RigidBody>();
    RigidBody* RawPtr = NewBody.get();
    Bodies.push_back(std::move(NewBody));
    return RawPtr;
}

void PhysicsWorld::DestroyRigidBody(RigidBody* Body)
{
    Bodies.erase(
        std::remove_if(Bodies.begin(), Bodies.end(),
            [Body](const std::unique_ptr<RigidBody>& Ptr)
            {
                return Ptr.get() == Body;
            }),
        Bodies.end());
}

