## `PhysicsSubsystem.cpp`

```cpp
#include "PhysicsSubsystem.h"

PhysicsSubsystem::PhysicsSubsystem()
    : bInitialized(false)
{
}

PhysicsSubsystem::~PhysicsSubsystem()
{
    Shutdown();
}

bool PhysicsSubsystem::Initialize()
{
    if (bInitialized)
    {
        return true;
    }

    MainWorld = std::make_unique<PhysicsWorld>();
    bInitialized = true;
    return true;
}

void PhysicsSubsystem::Shutdown()
{
    if (!bInitialized)
    {
        return;
    }

    MainWorld.reset();
    bInitialized = false;
}

void PhysicsSubsystem::Tick(float DeltaTime)
{
    if (!bInitialized || !MainWorld)
    {
        return;
    }

    MainWorld->StepSimulation(DeltaTime);
}

PhysicsWorld* PhysicsSubsystem::GetWorld()
{
    return MainWorld.get();
}
