## `PhysicsComponent.cpp`

```cpp
#include "PhysicsComponent.h"
#include "PhysicsWorld.h"

PhysicsComponent::PhysicsComponent()
    : World(nullptr)
    , Body(nullptr)
    , bSimulatePhysics(false)
{
}

PhysicsComponent::~PhysicsComponent()
{
    Shutdown();
}

bool PhysicsComponent::Initialize(PhysicsWorld* InWorld)
{
    if (!InWorld)
    {
        return false;
    }

    World = InWorld;
    Body = World->CreateRigidBody();
    return Body != nullptr;
}

void PhysicsComponent::Shutdown()
{
    if (World && Body)
    {
        World->DestroyRigidBody(Body);
        Body = nullptr;
    }

    World = nullptr;
}

void PhysicsComponent::SetSimulatePhysics(bool bEnable)
{
    bSimulatePhysics = bEnable;

    if (Body)
    {
        Body->SetBodyType(bEnable ? EBodyType::Dynamic : EBodyType::Kinematic);
    }
}

bool PhysicsComponent::IsSimulatingPhysics() const
{
    return bSimulatePhysics;
}

void PhysicsComponent::SetWorldTransform(const Transform& InTransform)
{
    if (Body)
    {
        Body->SetTransform(InTransform);
    }
}

Transform PhysicsComponent::GetWorldTransform() const
{
    if (Body)
    {
        return Body->GetTransform();
    }

    return Transform();
}

void PhysicsComponent::AddForce(const Vec3& Force)
{
    if (Body)
    {
        Body->AddForce(Force);
    }
}

void PhysicsComponent::SetMass(float InMass)
{
    if (Body)
    {
        Body->SetMass(InMass);
    }
}

void PhysicsComponent::SyncFromEngineTransform(const Transform& EngineTransform)
{
    if (!Body)
    {
        return;
    }

    if (!bSimulatePhysics)
    {
        Body->SetTransform(EngineTransform);
    }
}

void PhysicsComponent::SyncToEngineTransform(Transform& EngineTransform) const
{
    if (!Body)
    {
        return;
    }

    if (bSimulatePhysics)
    {
        EngineTransform = Body->GetTransform();
    }
}
