UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    enum ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bSimulate || !GetOwner())
    {
        return;
    }

    Simulate(DeltaTime);
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsComponent::AddImpulse(FVector Impulse)
{
    if (Mass > KINDA_SMALL_NUMBER)
    {
        Velocity += Impulse / Mass;
    }
}

void UCustomPhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

FVector UCustomPhysicsComponent::GetVelocity() const
{
    return Velocity;
}

void UCustomPhysicsComponent::ResetForces()
{
    AccumulatedForce = FVector::ZeroVector;
}

void UCustomPhysicsComponent::Simulate(float DeltaTime)
{
    if (DeltaTime <= SMALL_NUMBER || Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    FVector Position = Owner->GetActorLocation();

    // F = ma -> a = F / m
    FVector Acceleration = (AccumulatedForce / Mass) + Gravity;

    // Semi-implicit Euler integration
    Velocity += Acceleration * DeltaTime;

    // Linear damping
    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    Position += Velocity * DeltaTime;

    if (bEnableGroundPlane)
    {
        ResolveGroundCollision(Position, Velocity);
    }

    Owner->SetActorLocation(Position);

    // Clear per-frame forces
    AccumulatedForce = FVector::ZeroVector;
}

void UCustomPhysicsComponent::ResolveGroundCollision(FVector& Position, FVector& InOutVelocity)
{
    if (Position.Z < GroundHeight)
    {
        Position.Z = GroundHeight;

        if (InOutVelocity.Z < 0.0f)
        {
            InOutVelocity.Z = -InOutVelocity.Z * Restitution;
        }

        InOutVelocity.X *= FMath::Clamp(1.0f - GroundFriction, 0.0f, 1.0f);
        InOutVelocity.Y *= FMath::Clamp(1.0f - GroundFriction, 0.0f, 1.0f);

        if (FMath::Abs(InOutVelocity.Z) < 1.0f)
        {
            InOutVelocity.Z = 0.0f;
        }
    }
}
