# Optional Improved Version: Basic Collision Response

If you want a slightly better initial implementation, replace the movement part in `Simulate()` with this:

```cpp
void UCustomPhysicsComponent::Simulate(float DeltaTime)
{
    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    FVector TotalForce = AccumulatedForce;

    if (bApplyGravity)
    {
        TotalForce += Gravity * Mass;
    }

    const FVector SafeMass = FVector(FMath::Max(Mass, 0.001f));
    const FVector Acceleration = TotalForce / FMath::Max(Mass, 0.001f);

    Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    const FVector DeltaMove = Velocity * DeltaTime;

    FHitResult Hit;
    Owner->SetActorLocation(Owner->GetActorLocation() + DeltaMove, true, &Hit);

    if (Hit.IsValidBlockingHit())
    {
        Velocity = FVector::VectorPlaneProject(Velocity, Hit.Normal) * 0.5f;
    }

    AccumulatedForce = FVector::ZeroVector;
}
```

This gives a crude “slide and lose energy” behavior.

