# 7. Physics world

This is the core simulation container.

## `SimplePhysicsWorld.h`

```cpp
#pragma once

#include "CoreMinimal.h"

class USimplePhysicsBodyComponent;

class CUSTOMPHYSICSPLUGIN_API FSimplePhysicsWorld
{
public:
    FSimplePhysicsWorld();

    void AddBody(USimplePhysicsBodyComponent* Body);
    void RemoveBody(USimplePhysicsBodyComponent* Body);
    void StepSimulation(float DeltaTime);

    void SetGravity(const FVector& InGravity) { Gravity = InGravity; }
    const FVector& GetGravity() const { return Gravity; }

private:
    void IntegrateBody(USimplePhysicsBodyComponent* Body, float DeltaTime);
    void SolveGroundCollision(USimplePhysicsBodyComponent* Body);

private:
    TArray<TWeakObjectPtr<USimplePhysicsBodyComponent>> Bodies;
    FVector Gravity;
};
```

## `SimplePhysicsWorld.cpp`

```cpp
#include "SimplePhysicsWorld.h"
#include "SimplePhysicsBodyComponent.h"

FSimplePhysicsWorld::FSimplePhysicsWorld()
    : Gravity(0.0f, 0.0f, -980.0f)
{
}

void FSimplePhysicsWorld::AddBody(USimplePhysicsBodyComponent* Body)
{
    if (Body)
    {
        Bodies.AddUnique(Body);
    }
}

void FSimplePhysicsWorld::RemoveBody(USimplePhysicsBodyComponent* Body)
{
    Bodies.Remove(Body);
}

void FSimplePhysicsWorld::StepSimulation(float DeltaTime)
{
    for (int32 Index = Bodies.Num() - 1; Index >= 0; --Index)
    {
        USimplePhysicsBodyComponent* Body = Bodies[Index].Get();
        if (!Body)
        {
            Bodies.RemoveAtSwap(Index);
            continue;
        }

        if (!Body->bSimulatePhysics)
        {
            continue;
        }

        IntegrateBody(Body, DeltaTime);
        SolveGroundCollision(Body);
        Body->ClearForces();
    }
}

void FSimplePhysicsWorld::IntegrateBody(USimplePhysicsBodyComponent* Body, float DeltaTime)
{
    if (!Body || Body->Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    FVector TotalForce = Body->GetAccumulatedForce();

    if (Body->bUseGravity)
    {
        TotalForce += Gravity * Body->Mass;
    }

    const FVector Acceleration = TotalForce / Body->Mass;

    Body->Velocity += Acceleration * DeltaTime;

    const float DampingFactor = FMath::Clamp(1.0f - Body->LinearDamping * DeltaTime, 0.0f, 1.0f);
    Body->Velocity *= DampingFactor;

    FVector NewPosition = Body->GetPosition() + Body->Velocity * DeltaTime;
    Body->SetPosition(NewPosition);
}

void FSimplePhysicsWorld::SolveGroundCollision(USimplePhysicsBodyComponent* Body)
{
    if (!Body)
    {
        return;
    }

    FVector Position = Body->GetPosition();
    const float GroundZ = 0.0f;
    const float MinZ = GroundZ + Body->CollisionRadius;

    if (Position.Z < MinZ)
    {
        Position.Z = MinZ;
        Body->SetPosition(Position);

        if (Body->Velocity.Z < 0.0f)
        {
            Body->Velocity.Z = -Body->Velocity.Z * Body->Restitution;
        }
    }
}
```

