{
    GENERATED_BODY()

public:
    virtual bool ShouldCreateSubsystem(UObject* Outer) const override;
    virtual void Tick(float DeltaTime);
    virtual TStatId GetStatId() const;

    void RegisterBody(USimplePhysicsComponent* Body);
    void UnregisterBody(USimplePhysicsComponent* Body);

private:
    TArray<TWeakObjectPtr<USimplePhysicsComponent>> Bodies;
