```

## `Private/CustomPhysicsSubsystem.cpp`

```cpp
#include "CustomPhysicsSubsystem.h"
#include "SimplePhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

bool UCustomPhysicsSubsystem::ShouldCreateSubsystem(UObject* Outer) const
{
    return true;
}

void UCustomPhysicsSubsystem::RegisterBody(USimplePhysicsComponent* Body)
{
    if (Body)
    {
        Bodies.AddUnique(Body);
    }
}

void UCustomPhysicsSubsystem::UnregisterBody(USimplePhysicsComponent* Body)
{
    Bodies.Remove(Body);
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    if (DeltaTime <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    for (int32 i = Bodies.Num() - 1; i >= 0; --i)
    {
        USimplePhysicsComponent* Body = Bodies[i].Get();
        if (!Body)
        {
            Bodies.RemoveAt(i);
            continue;
        }

        if (!Body->bSimulate || Body->Mass <= 0.0f)
        {
            Body->ClearForces();
            continue;
        }

        FVector TotalForce = Body->AccumulatedForce;

        if (Body->bUseGravity)
        {
            TotalForce += Body->Gravity * Body->Mass;
        }

        const FVector Acceleration = TotalForce / Body->Mass;
        Body->Velocity += Acceleration * DeltaTime;

        if (AActor* Owner = Body->GetOwner())
        {
            FVector NewLocation = Owner->GetActorLocation() + Body->Velocity * DeltaTime;
            Owner->SetActorLocation(NewLocation);
        }

        Body->ClearForces();
    }
}

