void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    if (DeltaTime <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    for (int32 i = Bodies.Num() - 1; i >= 0; --i)
    {
        USimplePhysicsComponent* Body = Bodies[i].Get();
        if (!Body)
        {
            Bodies.RemoveAt(i);
            continue;
        }

        if (!Body->bSimulate || Body->Mass <= 0.0f)
        {
            Body->ClearForces();
            continue;
        }

        FVector TotalForce = Body->AccumulatedForce;

        if (Body->bUseGravity)
        {
            TotalForce += Body->Gravity * Body->Mass;
        }

        const FVector Acceleration = TotalForce / Body->Mass;
        Body->Velocity += Acceleration * DeltaTime;

        if (AActor* Owner = Body->GetOwner())
        {
            FVector NewLocation = Owner->GetActorLocation() + Body->Velocity * DeltaTime;
            Owner->SetActorLocation(NewLocation);
        }

        Body->ClearForces();
    }
}

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}
