## `SimplePhysicsWorld.cpp`

```cpp
#include "SimplePhysicsWorld.h"
#include "SimpleRigidBodyComponent.h"

FSimplePhysicsWorld::FSimplePhysicsWorld()
    : Gravity(0.0f, 0.0f, -980.0f)
{
}

void FSimplePhysicsWorld::AddBody(USimpleRigidBodyComponent* Body)
{
    if (Body)
    {
        Bodies.AddUnique(Body);
    }
}

void FSimplePhysicsWorld::RemoveBody(USimpleRigidBodyComponent* Body)
{
    Bodies.Remove(Body);
}

void FSimplePhysicsWorld::StepSimulation(float DeltaTime)
{
    for (int32 i = Bodies.Num() - 1; i >= 0; --i)
    {
        if (!Bodies[i].IsValid())
        {
            Bodies.RemoveAt(i);
            continue;
        }

        IntegrateBody(Bodies[i].Get(), DeltaTime);
    }

    SolveCollisions();
}

void FSimplePhysicsWorld::IntegrateBody(USimpleRigidBodyComponent* Body, float DeltaTime)
{
    if (!Body || !Body->IsSimulating())
    {
        return;
    }

    FVector Position = Body->GetSimulatedPosition();
    FVector Velocity = Body->GetLinearVelocity();

    Velocity += Gravity * DeltaTime;
    Position += Velocity * DeltaTime;

    Body->SetLinearVelocity(Velocity);
    Body->SetSimulatedPosition(Position);
}

void FSimplePhysicsWorld::SolveCollisions()
{
    // Very naive N^2 collision pass
    for (int32 i = 0; i < Bodies.Num(); ++i)
    {
        USimpleRigidBodyComponent* A = Bodies[i].Get();
        if (!A) continue;

        for (int32 j = i + 1; j < Bodies.Num(); ++j)
        {
            USimpleRigidBodyComponent* B = Bodies[j].Get();
            if (!B) continue;

            const FSimpleCollider& ColliderA = A->GetCollider();
            const FSimpleCollider& ColliderB = B->GetCollider();

            // Sphere vs Plane
            if (ColliderA.Type == ESimpleColliderType::Sphere &&
                ColliderB.Type == ESimpleColliderType::Plane)
            {
                FVector PosA = A->GetSimulatedPosition();
                FVector N = ColliderB.PlaneNormal.GetSafeNormal();
                float Distance = FVector::DotProduct(N, PosA) - ColliderB.PlaneOffset;

                if (Distance < ColliderA.Radius)
                {
                    float Penetration = ColliderA.Radius - Distance;
                    PosA += N * Penetration;

                    FVector VelA = A->GetLinearVelocity();
                    float VN = FVector::DotProduct(VelA, N);

                    if (VN < 0.0f)
                    {
                        float Restitution = A->GetRestitution();
                        VelA = VelA - (1.0f + Restitution) * VN * N;
                    }

                    A->SetSimulatedPosition(PosA);
                    A->SetLinearVelocity(VelA);
                }
            }

            // Plane vs Sphere
            if (ColliderA.Type == ESimpleColliderType::Plane &&
                ColliderB.Type == ESimpleColliderType::Sphere)
            {
                FVector PosB = B->GetSimulatedPosition();
                FVector N = ColliderA.PlaneNormal.GetSafeNormal();
                float Distance = FVector::DotProduct(N, PosB) - ColliderA.PlaneOffset;

                if (Distance < ColliderB.Radius)
                {
                    float Penetration = ColliderB.Radius - Distance;
                    PosB += N * Penetration;

                    FVector VelB = B->GetLinearVelocity();
                    float VN = FVector::DotProduct(VelB, N);

                    if (VN < 0.0f)
                    {
                        float Restitution = B->GetRestitution();
                        VelB = VelB - (1.0f + Restitution) * VN * N;
                    }

                    B->SetSimulatedPosition(PosB);
                    B->SetLinearVelocity(VelB);
                }
            }
        }
    }
}
```

