void USimpleRigidBodyComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!GetOwner())
    {
        return;
    }

    // Prototype approach:
    // Only first component effectively advances the world if multiple exist would be wrong.
    // This is intentionally simple for initial implementation.
    static bool bSteppedThisFrame = false;

    if (!bSteppedThisFrame && GSimplePhysicsWorld.IsValid())
    {
        GSimplePhysicsWorld->StepSimulation(DeltaTime);
        bSteppedThisFrame = true;
    }

    GetOwner()->SetActorLocation(SimulatedPosition);

    // Reset frame flag in a crude way
    if (GFrameCounter % 2 == 0)
    {
        bSteppedThisFrame = false;
    }
}
