# 12. Example: add sphere-sphere collision now

If you want a slightly better initial implementation, here is a sphere-sphere narrowphase you can drop into `SolveCollisions()`:

```cpp
if (ColliderA.Type == ESimpleColliderType::Sphere &&
    ColliderB.Type == ESimpleColliderType::Sphere)
{
    FVector PosA = A->GetSimulatedPosition();
    FVector PosB = B->GetSimulatedPosition();

    FVector Delta = PosB - PosA;
    float DistSq = Delta.SizeSquared();
    float RadiusSum = ColliderA.Radius + ColliderB.Radius;

    if (DistSq < RadiusSum * RadiusSum)
    {
        float Dist = FMath::Sqrt(FMath::Max(DistSq, KINDA_SMALL_NUMBER));
        FVector Normal = Delta / Dist;

        float Penetration = RadiusSum - Dist;

        bool bSimA = A->IsSimulating();
        bool bSimB = B->IsSimulating();

        if (bSimA && bSimB)
        {
            PosA -= Normal * (Penetration * 0.5f);
            PosB += Normal * (Penetration * 0.5f);
        }
        else if (bSimA)
        {
            PosA -= Normal * Penetration;
        }
        else if (bSimB)
        {
            PosB += Normal * Penetration;
        }

        FVector VelA = A->GetLinearVelocity();
        FVector VelB = B->GetLinearVelocity();

        FVector RelativeVelocity = VelB - VelA;
        float VelAlongNormal = FVector::DotProduct(RelativeVelocity, Normal);

        if (VelAlongNormal < 0.0f)
        {
            float Restitution = FMath::Min(A->GetRestitution(), B->GetRestitution());

            float InvMassA = bSimA ? 1.0f : 0.0f;
            float InvMassB = bSimB ? 1.0f : 0.0f;

            float Denom = InvMassA + InvMassB;
            if (Denom > KINDA_SMALL_NUMBER)
            {
                float J = -(1.0f + Restitution) * VelAlongNormal;
                J /= Denom;

                FVector Impulse = J * Normal;

                if (bSimA)
                {
                    VelA -= Impulse * InvMassA;
                }

                if (bSimB)
                {
                    VelB += Impulse * InvMassB;
                }
            }
        }

        A->SetSimulatedPosition(PosA);
        B->SetSimulatedPosition(PosB);
        A->SetLinearVelocity(VelA);
        B->SetLinearVelocity(VelB);
    }
}
```

