    bodies.push_back(body);
    return (int)bodies.size() - 1;
}

void SimplePhysicsPlugin::ApplyForce(int bodyId, const Vec3& force) {
    if (bodyId < 0 || bodyId >= (int)bodies.size()) return;
    bodies[bodyId].force = bodies[bodyId].force + force;
}

void SimplePhysicsPlugin::StepSimulation(float dt) {
    for (auto& body : bodies) {
        if (!body.dynamic || body.mass <= 0.0f) continue;

        Vec3 accel = gravity + (body.force * (1.0f / body.mass));
        body.velocity = body.velocity + accel * dt;
        body.position = body.position + body.velocity * dt;
        body.force = {0.0f, 0.0f, 0.0f};

        // simple ground plane collision at y = 0
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) body.velocity.y *= -0.5f;
        }
    }
