// Minimal engine-agnostic physics plugin skeleton

#include <vector>
#include <string>
#include <cmath>

struct Vec3 {
    float x{}, y{}, z{};
    Vec3 operator+(const Vec3& r) const { return {x + r.x, y + r.y, z + r.z}; }
    Vec3 operator-(const Vec3& r) const { return {x - r.x, y - r.y, z - r.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 accumulatedForce;
    float mass{1.0f};
    bool isStatic{false};
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual const char* GetName() const = 0;
    virtual bool Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void StepSimulation(float dt) = 0;
    virtual int CreateBody(const Vec3& position, float mass, bool isStatic) = 0;
    virtual void ApplyForce(int bodyId, const Vec3& force) = 0;
    virtual Vec3 GetBodyPosition(int bodyId) const = 0;
};

class MinimalPhysicsPlugin : public IPhysicsPlugin {
public:
    const char* GetName() const override {
        return "MinimalPhysicsPlugin";
    }

    bool Initialize() override {
        gravity = {0.0f, -9.81f, 0.0f};
        return true;
    }

    void Shutdown() override {
        bodies.clear();
    }

    int CreateBody(const Vec3& position, float mass, bool isStatic) override {
        RigidBody body;
        body.position = position;
        body.mass = (mass <= 0.0f) ? 1.0f : mass;
        body.isStatic = isStatic;
        bodies.push_back(body);
        return static_cast<int>(bodies.size() - 1);
    }

    void ApplyForce(int bodyId, const Vec3& force) override {
        if (!IsValid(bodyId) || bodies[bodyId].isStatic) return;
        bodies[bodyId].accumulatedForce += force;
    }

    Vec3 GetBodyPosition(int bodyId) const override {
        if (!IsValid(bodyId)) return {};
        return bodies[bodyId].position;
    }

    void StepSimulation(float dt) override {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            Vec3 totalForce = body.accumulatedForce + gravity * body.mass;
            Vec3 acceleration = totalForce * (1.0f / body.mass);

            body.velocity += acceleration * dt;
            body.position += body.velocity * dt;

            if (body.position.y < 0.0f) {
                body.position.y = 0.0f;
                if (body.velocity.y < 0.0f) {
                    body.velocity.y *= -0.5f;
                }
            }

            body.accumulatedForce = {};
        }
    }

private:
    bool IsValid(int id) const {
        return id >= 0 && id < static_cast<int>(bodies.size());
    }

    std::vector<RigidBody> bodies;
    Vec3 gravity;
};

