// MinimalPhysicsPlugin.h
#pragma once
#include <vector>
#include <unordered_map>
#include <cstdint>

struct Vec3 {
    float x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }
};

struct Transform {
    Vec3 position;
};

using BodyHandle = uint32_t;
using TransformCallback = void(*)(BodyHandle, const Transform&);

struct RigidBody {
    float mass = 1.0f;
    Vec3 velocity{0,0,0};
    Vec3 accumulatedForce{0,0,0};
    Transform transform{{0,0,0}};
    bool dynamic = true;
};

class PhysicsWorld {
public:
    explicit PhysicsWorld(TransformCallback cb) : callback(cb) {}

    BodyHandle CreateBody(float mass, const Transform& start, bool dynamic) {
        BodyHandle id = nextId++;
        bodies[id] = RigidBody{mass, {0,0,0}, {0,0,0}, start, dynamic};
        return id;
    }

    void DestroyBody(BodyHandle id) {
        bodies.erase(id);
    }

    void ApplyForce(BodyHandle id, Vec3 force) {
        auto it = bodies.find(id);
        if (it != bodies.end() && it->second.dynamic) {
            it->second.accumulatedForce += force;
        }
    }

    void Step(float dt) {
        for (auto& [id, body] : bodies) {
            if (!body.dynamic || body.mass <= 0.0f) continue;

            Vec3 gravity{0.0f, -9.81f * body.mass, 0.0f};
            body.accumulatedForce += gravity;

            Vec3 acceleration = body.accumulatedForce * (1.0f / body.mass);
            body.velocity += acceleration * dt;
            body.transform.position += body.velocity * dt;

            if (body.transform.position.y < 0.0f) {
                body.transform.position.y = 0.0f;
                if (body.velocity.y < 0.0f) body.velocity.y *= -0.3f;
            }

            body.accumulatedForce = {0,0,0};

            if (callback) callback(id, body.transform);
        }
    }

private:
    std::unordered_map<BodyHandle, RigidBody> bodies;
    BodyHandle nextId = 1;
    TransformCallback callback = nullptr;
};
