#include <memory>

struct Vec3 {
    float x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }
};

struct Body {
    Vec3 position{0,0,0};
    Vec3 velocity{0,0,0};
    float mass = 1.0f;
    bool dynamic = true;
};

class PhysicsWorld {
public:
    void AddBody(const Body& body) {
        bodies.push_back(body);
    }

    Body& GetBody(size_t i) {
        return bodies[i];
    }

    size_t GetBodyCount() const {
        return bodies.size();
    }

    void Step(float dt) {
        const Vec3 gravity{0.0f, -9.81f, 0.0f};

        for (auto& b : bodies) {
            if (!b.dynamic) continue;

            b.velocity += gravity * dt;
            b.position += b.velocity * dt;

            // Minimal collision with ground plane at y = 0
            if (b.position.y < 0.0f) {
                b.position.y = 0.0f;
                if (b.velocity.y < 0.0f) {
                    b.velocity.y *= -0.5f; // restitution
                }
            }
        }
    }

private:
    std::vector<Body> bodies;
};

// Plugin-style API surface
class MinimalPhysicsPlugin {
public:
    bool Initialize() {
        world = std::make_unique<PhysicsWorld>();
        return true;
    }

    void Shutdown() {
        world.reset();
    }

    PhysicsWorld* GetWorld() {
        return world.get();
    }

    void Tick(float deltaTime) {
        if (world) world->Step(deltaTime);
    }

private:
    std::unique_ptr<PhysicsWorld> world;
};
