#include <vector>

static Vec3 Add(Vec3 a, Vec3 b) { return {a.x+b.x, a.y+b.y, a.z+b.z}; }
static Vec3 Scale(Vec3 v, float s) { return {v.x*s, v.y*s, v.z*s}; }

struct InternalBody {
    BodyState state;
    Vec3 accumulatedForce;
};

class MinimalPhysicsPlugin : public IPhysicsPlugin {
public:
    bool Initialize() override {
        bodies.clear();
        return true;
    }

    void Shutdown() override {
        bodies.clear();
    }

    int CreateBody(const BodyState& initial) override {
        bodies.push_back({initial, {0,0,0}});
        return (int)bodies.size() - 1;
    }

    void ApplyForce(int bodyId, const Vec3& force) override {
        if (bodyId < 0 || bodyId >= (int)bodies.size()) return;
        bodies[bodyId].accumulatedForce = Add(bodies[bodyId].accumulatedForce, force);
    }

    void StepSimulation(float dt) override {
        for (auto& body : bodies) {
            if (!body.state.dynamic || body.state.mass <= 0.0f) continue;

            Vec3 accel = Scale(body.accumulatedForce, 1.0f / body.state.mass);
            body.state.velocity = Add(body.state.velocity, Scale(accel, dt));
            body.state.position = Add(body.state.position, Scale(body.state.velocity, dt));

            body.accumulatedForce = {0,0,0};
        }
    }

    BodyState GetBodyState(int bodyId) const override {
        if (bodyId < 0 || bodyId >= (int)bodies.size()) {
            return {{0,0,0},{0,0,0},1.0f,false};
        }
        return bodies[bodyId].state;
    }

private:
    std::vector<InternalBody> bodies;
};
