    Vec3(float ix, float iy, float iz) : x(ix), y(iy), z(iz) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }

    Vec3& operator+=(const Vec3& r)
    {
        x += r.x; y += r.y; z += r.z;
        return *this;
    }
};

struct RigidBody
{
    Vec3 position;
    Vec3 velocity;
    Vec3 accumulatedForce;
    float mass = 1.0f;
    bool isStatic = false;
};

class IPhysicsSystem
{
public:
    virtual ~IPhysicsSystem() = default;
    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void StepSimulation(float deltaTime) = 0;
    virtual RigidBody* CreateRigidBody(const Vec3& position, float mass, bool isStatic) = 0;
    virtual void AddForce(RigidBody* body, const Vec3& force) = 0;
};

class SimplePhysicsSystem : public IPhysicsSystem
{
public:
    void Initialize() override;
    void Shutdown() override;
    void StepSimulation(float deltaTime) override;
    RigidBody* CreateRigidBody(const Vec3& position, float mass, bool isStatic) override;
    void AddForce(RigidBody* body, const Vec3& force) override;

private:
    std::vector<std::unique_ptr<RigidBody>> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
};
```

### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"
#include <algorithm>

void SimplePhysicsSystem::Initialize()
{
    bodies.clear();
}

void SimplePhysicsSystem::Shutdown()
{
    bodies.clear();
}

RigidBody* SimplePhysicsSystem::CreateRigidBody(const Vec3& position, float mass, bool isStatic)
{
    auto body = std::make_unique<RigidBody>();
    body->position = position;
    body->velocity = Vec3(0, 0, 0);
    body->accumulatedForce = Vec3(0, 0, 0);
    body->mass = (mass <= 0.0f) ? 1.0f : mass;
    body->isStatic = isStatic;

    RigidBody* ptr = body.get();
    bodies.push_back(std::move(body));
    return ptr;
}

void SimplePhysicsSystem::AddForce(RigidBody* body, const Vec3& force)
{
    if (!body || body->isStatic) return;
    body->accumulatedForce += force;
}

void SimplePhysicsSystem::StepSimulation(float deltaTime)
{
    for (auto& bodyPtr : bodies)
    {
        RigidBody& body = *bodyPtr;
        if (body.isStatic) continue;

        Vec3 acceleration = gravity + (body.accumulatedForce * (1.0f / body.mass));
        body.velocity += acceleration * deltaTime;
        body.position += body.velocity * deltaTime;

        // Very simple collision with ground plane at y = 0
        if (body.position.y < 0.0f)
        {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f)
            {
                body.velocity.y *= -0.3f; // bounce damping
            }
        }

        body.accumulatedForce = Vec3(0, 0, 0);
    }
}
