// minimal_physics_plugin.cpp
#include <vector>
#include <cmath>
#include <iostream>

struct Vec3 {
    float x{}, y{}, z{};

    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }

    Vec3& operator+=(const Vec3& o) {
        x += o.x; y += o.y; z += o.z;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass{1.0f};
    bool isStatic{false};
};

class PhysicsPlugin {
public:
    bool initialize() {
        gravity = {0.0f, -9.81f, 0.0f};
        std::cout << "PhysicsPlugin initialized\n";
        return true;
    }

    void shutdown() {
        bodies.clear();
        std::cout << "PhysicsPlugin shutdown\n";
    }

    int createBody(const Vec3& pos, float mass, bool isStatic = false) {
        RigidBody body;
        body.position = pos;
        body.mass = mass;
        body.isStatic = isStatic;
        bodies.push_back(body);
        return static_cast<int>(bodies.size() - 1);
    }

    void applyForce(int id, const Vec3& force) {
        if (!isValid(id) || bodies[id].isStatic) return;
        bodies[id].forceAccum += force;
    }

    void update(float dt) {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            Vec3 acceleration = gravity + (body.forceAccum * (1.0f / body.mass));
            body.velocity += acceleration * dt;
            body.position += body.velocity * dt;

            // Simple ground-plane collision at y = 0
            if (body.position.y < 0.0f) {
                body.position.y = 0.0f;
                if (body.velocity.y < 0.0f) {
                    body.velocity.y *= -0.5f; // restitution
                }
            }

            body.forceAccum = {0.0f, 0.0f, 0.0f};
        }
    }

    Vec3 getPosition(int id) const {
        if (!isValid(id)) return {};
        return bodies[id].position;
    }

private:
    bool isValid(int id) const {
        return id >= 0 && id < static_cast<int>(bodies.size());
    }

    std::vector<RigidBody> bodies;
    Vec3 gravity;
};

// Example host usage
int main() {
    PhysicsPlugin physics;
    if (!physics.initialize()) return 1;

    int bodyId = physics.createBody({0.0f, 10.0f, 0.0f}, 1.0f);

    for (int i = 0; i < 120; ++i) {
        physics.update(1.0f / 60.0f);
        Vec3 p = physics.getPosition(bodyId);
        std::cout << "t=" << i / 60.0f
                  << " pos=(" << p.x << ", " << p.y << ", " << p.z << ")\n";
    }

    physics.shutdown();
    return 0;
}
