```cpp
// MinimalPhysicsPlugin.cpp
#include "MinimalPhysicsPlugin.h"

bool MinimalPhysicsPlugin::Initialize() {
    bodies.clear();
    return true;
}

void MinimalPhysicsPlugin::Shutdown() {
    bodies.clear();
}

int MinimalPhysicsPlugin::CreateBody(const RigidBody& body) {
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void MinimalPhysicsPlugin::StepSimulation(float dt) {
    for (auto& b : bodies) {
        if (!b.dynamic) continue;

        b.velocity.x += gravity.x * dt;
        b.velocity.y += gravity.y * dt;
        b.velocity.z += gravity.z * dt;

        b.position.x += b.velocity.x * dt;
        b.position.y += b.velocity.y * dt;
        b.position.z += b.velocity.z * dt;

        if (b.position.y < 0.0f) {
            b.position.y = 0.0f;
            if (b.velocity.y < 0.0f) b.velocity.y *= -0.5f;
        }
    }
}

RigidBody MinimalPhysicsPlugin::GetBody(int id) const {
    return bodies.at(id);
}
