  </div>
  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Vector utilities
    // -----------------------------
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      clone() {
        return new Vec2(this.x, this.y);
      }

      set(x, y) {
        this.x = x;
        this.y = y;
        return this;
      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      length() {
        return Math.hypot(this.x, this.y);
      }

      normalize() {
        const len = this.length();
        if (len > 1e-8) {
          this.x /= len;
          this.y /= len;
        }
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }

      static dot(a, b) {
        return a.x * b.x + a.y * b.y;
      }

      // 2D cross product helpers
      static cross(a, b) {
        return a.x * b.y - a.y * b.x;
      }

      // scalar x vector => vector
      static crossSV(s, v) {
        return new Vec2(-s * v.y, s * v.x);
      }

      // vector x scalar => vector
      static crossVS(v, s) {
        return new Vec2(s * v.y, -s * v.x);
      }
    }

    // -----------------------------
    // Rigid body: circle
    // -----------------------------
    class RigidBody {
      constructor(x, y, radius, mass = 1, restitution = 0.8) {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2(0, 0);
        this.force = new Vec2(0, 0);

        this.angle = 0;
        this.angularVelocity = 0;
        this.torque = 0;

        this.radius = radius;
        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        // Moment of inertia for solid disk: I = 1/2 * m * r^2
        this.inertia = mass > 0 ? 0.5 * mass * radius * radius : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

        this.restitution = restitution;
        this.color = `hsl(${Math.random() * 360}, 70%, 60%)`;
      }

      applyForce(force) {
        this.force.add(force);
      }

      applyImpulse(impulse, contactVector) {
        this.velocity.add(Vec2.scale(impulse, this.invMass));
        this.angularVelocity += this.invInertia * Vec2.cross(contactVector, impulse);
      }

      integrateForces(dt, gravity) {
        if (this.invMass === 0) return;

        // Semi-implicit Euler
        this.velocity.x += (gravity.x + this.force.x * this.invMass) * dt;
        this.velocity.y += (gravity.y + this.force.y * this.invMass) * dt;
        this.angularVelocity += this.torque * this.invInertia * dt;
      }

      integrateVelocity(dt) {
        if (this.invMass === 0) return;

        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;
      }

      clearForces() {
        this.force.set(0, 0);
        this.torque = 0;
      }

      draw(ctx) {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);

        ctx.beginPath();
        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = "#fff";
        ctx.lineWidth = 2;
        ctx.stroke();

        // Orientation marker
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(this.radius, 0);
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 3;
        ctx.stroke();

        ctx.restore();
      }
    }

    // -----------------------------
    // Collision handling
    // -----------------------------
    function resolveCircleCollision(a, b) {
      const normal = Vec2.sub(b.position, a.position);
      const dist = normal.length();
      const radiusSum = a.radius + b.radius;

      if (dist === 0 || dist >= radiusSum) return false;

      normal.scale(1 / dist);

      const contactPoint = Vec2.add(a.position, Vec2.scale(normal, a.radius));
      const ra = Vec2.sub(contactPoint, a.position);
      const rb = Vec2.sub(contactPoint, b.position);

      const rv = Vec2.sub(
        Vec2.add(b.velocity, Vec2.crossSV(b.angularVelocity, rb)),
        Vec2.add(a.velocity, Vec2.crossSV(a.angularVelocity, ra))
      );

      const velAlongNormal = Vec2.dot(rv, normal);

      // Objects separating
      if (velAlongNormal > 0) return false;

      const e = Math.min(a.restitution, b.restitution);

      const raCrossN = Vec2.cross(ra, normal);
      const rbCrossN = Vec2.cross(rb, normal);

      const invMassSum =
        a.invMass +
        b.invMass +
        (raCrossN * raCrossN) * a.invInertia +
        (rbCrossN * rbCrossN) * b.invInertia;

      const j = -(1 + e) * velAlongNormal / invMassSum;
      const impulse = Vec2.scale(normal, j);

      a.applyImpulse(Vec2.scale(impulse, -1), ra);
      b.applyImpulse(impulse, rb);

      // Positional correction to reduce sinking
      const percent = 0.8;
      const slop = 0.01;
      const penetration = radiusSum - dist;
      const correctionMag = Math.max(penetration - slop, 0) / (a.invMass + b.invMass) * percent;
      const correction = Vec2.scale(normal, correctionMag);

      if (a.invMass > 0) {
        a.position.sub(Vec2.scale(correction, a.invMass));
      }
      if (b.invMass > 0) {
        b.position.add(Vec2.scale(correction, b.invMass));
      }

      return true;
    }

    function resolveBoundaryCollision(body, width, height) {
      const r = body.radius;
      const e = body.restitution;

      // Left
      if (body.position.x - r < 0) {
        body.position.x = r;
        if (body.velocity.x < 0) body.velocity.x *= -e;
      }

      // Right
      if (body.position.x + r > width) {
        body.position.x = width - r;
        if (body.velocity.x > 0) body.velocity.x *= -e;
      }

      // Top
      if (body.position.y - r < 0) {
        body.position.y = r;
        if (body.velocity.y < 0) body.velocity.y *= -e;
      }

      // Bottom
      if (body.position.y + r > height) {
        body.position.y = height - r;
        if (body.velocity.y > 0) {
          body.velocity.y *= -e;
          // Add some angular effect when hitting floor
          body.angularVelocity += body.velocity.x * 0.01;
        }

        // Simple floor friction
        body.velocity.x *= 0.98;
      }
    }

    // -----------------------------
    // Physics world
    // -----------------------------
    class PhysicsWorld {
      constructor() {
        this.bodies = [];
        this.gravity = new Vec2(0, 600); // pixels/s^2
        this.iterations = 4;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        // Integrate forces
        for (const body of this.bodies) {
          body.integrateForces(dt, this.gravity);
        }

        // Integrate velocities
        for (const body of this.bodies) {
          body.integrateVelocity(dt);
          resolveBoundaryCollision(body, canvas.width, canvas.height);
        }

        // Solve collisions multiple times for stability
        for (let k = 0; k < this.iterations; k++) {
          for (let i = 0; i < this.bodies.length; i++) {
            for (let j = i + 1; j < this.bodies.length; j++) {
              resolveCircleCollision(this.bodies[i], this.bodies[j]);
            }
          }
        }

        // Clear forces
        for (const body of this.bodies) {
          body.clearForces();
        }
      }

      draw(ctx) {
        for (const body of this.bodies) {
          body.draw(ctx);
        }
      }
    }

    const world = new PhysicsWorld();

    // Static heavy body example (mass=0 => immovable)
    // Not used here, but supported by invMass=0 if needed.

    // Spawn initial bodies
    for (let i = 0; i < 12; i++) {
      const radius = 15 + Math.random() * 20;
      const mass = radius * 0.1;
      const body = new RigidBody(
        100 + Math.random() * (canvas.width - 200),
        50 + Math.random() * 200,
        radius,
        mass,
        0.7
      );
      body.velocity.x = (Math.random() - 0.5) * 200;
      body.velocity.y = Math.random() * 50;
      body.angularVelocity = (Math.random() - 0.5) * 5;
      world.addBody(body);
    }

    canvas.addEventListener("click", (e) => {
      const radius = 10 + Math.random() * 25;
      const mass = radius * 0.12;
      const body = new RigidBody(e.clientX, e.clientY, radius, mass, 0.8);
      body.velocity.x = (Math.random() - 0.5) * 300;
      body.velocity.y = -100 - Math.random() * 200;
      body.angularVelocity = (Math.random() - 0.5) * 10;
      world.addBody(body);
    });

    // -----------------------------
    // Real-time loop with fixed timestep
    // -----------------------------
    const FIXED_DT = 1 / 120;     // 120 Hz physics
    const MAX_FRAME_TIME = 0.25;  // avoid spiral of death
    const TARGET_FPS = 60;
    const FRAME_DURATION = 1000 / TARGET_FPS;

    let accumulator = 0;
    let lastTime = performance.now();
    let lastRenderTime = 0;

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Optional background grid
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1;
      for (let x = 0; x < canvas.width; x += 50) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      world.draw(ctx);

      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText(`Bodies: ${world.bodies.length}`, 10, canvas.height - 30);
      ctx.fillText(`Physics: ${(1 / FIXED_DT).toFixed(0)} Hz`, 10, canvas.height - 10);
    }

    function loop(now) {
      requestAnimationFrame(loop);

      // Frame-rate cap for rendering
      if (now - lastRenderTime < FRAME_DURATION) return;
      const renderDelta = now - lastRenderTime;
      lastRenderTime = now - (renderDelta % FRAME_DURATION);

      let frameTime = (now - lastTime) / 1000;
      lastTime = now;

      // Clamp to avoid huge catch-up after tab switch
      if (frameTime > MAX_FRAME_TIME) frameTime = MAX_FRAME_TIME;

      accumulator += frameTime;

      while (accumulator >= FIXED_DT) {
        world.step(FIXED_DT);
        accumulator -= FIXED_DT;
      }

      const alpha = accumulator / FIXED_DT;
      render(alpha);
    }

    requestAnimationFrame(loop);
  </script>
