```cpp
#include <SDL2/SDL.h>
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

static constexpr float PI = 3.14159265359f;

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(const Vec2& o) { x -= o.x; y -= o.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

inline float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

inline float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

inline Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return {0.0f, 0.0f};
    return v / len;
}

// 2D cross products:
// scalar x vector -> vector
inline Vec2 cross(float s, const Vec2& v) {
    return {-s * v.y, s * v.x};
}

// vector x vector -> scalar
inline float cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

inline Vec2 rotate(const Vec2& v, float angle) {
    float c = std::cos(angle);
    float s = std::sin(angle);
    return {c * v.x - s * v.y, s * v.x + c * v.y};
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float angle = 0.0f;
    float angularVelocity = 0.0f;
    float torque = 0.0f;

    float width = 50.0f;
    float height = 30.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float restitution = 0.3f;
    float friction = 0.8f;

    bool isStatic = false;

    void computeMassProperties() {
        if (isStatic || mass <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
            return;
        }

        invMass = 1.0f / mass;

        // Rectangle inertia about center in 2D
        inertia = (mass * (width * width + height * height)) / 12.0f;
        invInertia = (inertia > 0.0f) ? 1.0f / inertia : 0.0f;
    }

    void applyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void applyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += cross(contactVector, impulse) * invInertia;
    }

    void integrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void integrateVelocity(float dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;
    }

    void clearAccumulators() {
        force = {0.0f, 0.0f};
        torque = 0.0f;
    }

    std::vector<Vec2> getWorldVertices() const {
        std::vector<Vec2> verts(4);
        Vec2 half{width * 0.5f, height * 0.5f};

        std::vector<Vec2> local = {
            {-half.x, -half.y},
            { half.x, -half.y},
            { half.x,  half.y},
            {-half.x,  half.y}
        };

        for (int i = 0; i < 4; ++i) {
            verts[i] = position + rotate(local[i], angle);
        }

        return verts;
    }
};

struct Contact {
    RigidBody* body = nullptr;
    Vec2 point;
    Vec2 normal;
    float penetration = 0.0f;
};

bool detectGroundContact(RigidBody& body, float groundY, Contact& outContact) {
    auto verts = body.getWorldVertices();

    float deepest = -1e9f;
    Vec2 contactPoint;
    bool collided = false;

    for (const auto& v : verts) {
        float pen = groundY - v.y;
        if (pen > 0.0f) {
            collided = true;
            if (pen > deepest) {
                deepest = pen;
                contactPoint = v;
            }
        }
    }

    if (!collided) return false;

    outContact.body = &body;
    outContact.point = contactPoint;
    outContact.normal = {0.0f, -1.0f}; // ground pushes upward in screen coords? adjust below
    outContact.penetration = deepest;
    return true;
}

// Since SDL screen Y grows downward, gravity is positive Y.
// Ground normal should point upward against penetration:
static const Vec2 GROUND_NORMAL = {0.0f, -1.0f};

void resolveContact(Contact& c) {
    RigidBody& body = *c.body;
    if (body.isStatic) return;

    Vec2 r = c.point - body.position;

    // Velocity at contact point
    Vec2 contactVel = body.velocity + cross(body.angularVelocity, r);

    // Relative velocity along normal
    float velAlongNormal = dot(contactVel, c.normal);

    // Only resolve if moving into surface
    if (velAlongNormal >= 0.0f) return;

    float e = body.restitution;

    float rn = cross(r, c.normal);
    float invMassSum = body.invMass + (rn * rn) * body.invInertia;

    float j = -(1.0f + e) * velAlongNormal;
    j /= invMassSum;

    Vec2 impulse = c.normal * j;
    body.applyImpulse(impulse, r);

    // Friction
    contactVel = body.velocity + cross(body.angularVelocity, r);

    Vec2 tangent = contactVel - c.normal * dot(contactVel, c.normal);
    float tLen = length(tangent);
    if (tLen > 1e-6f) tangent = tangent / tLen;
    else tangent = {0.0f, 0.0f};

    float rt = cross(r, tangent);
    float denom = body.invMass + (rt * rt) * body.invInertia;

    float jt = -dot(contactVel, tangent);
    jt /= denom;

    float mu = body.friction;
    jt = std::clamp(jt, -j * mu, j * mu);

    Vec2 frictionImpulse = tangent * jt;
    body.applyImpulse(frictionImpulse, r);

    // Positional correction to reduce sinking
    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(c.penetration - slop, 0.0f) / body.invMass * percent;
    body.position -= c.normal * correctionMag * body.invMass;
}

void drawPolygon(SDL_Renderer* renderer, const std::vector<Vec2>& verts) {
    for (size_t i = 0; i < verts.size(); ++i) {
        const Vec2& a = verts[i];
        const Vec2& b = verts[(i + 1) % verts.size()];
        SDL_RenderDrawLine(renderer,
                           (int)a.x, (int)a.y,
                           (int)b.x, (int)b.y);
    }
}

int main(int argc, char** argv) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) != 0) {
        std::cerr << "SDL_Init failed: " << SDL_GetError() << "\n";
        return 1;
    }

    SDL_Window* window = SDL_CreateWindow(
        "Rigid Body Physics - Fixed Timestep",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        1000, 700,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        std::cerr << "SDL_CreateWindow failed: " << SDL_GetError() << "\n";
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "SDL_CreateRenderer failed: " << SDL_GetError() << "\n";
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    const float fixedDt = 1.0f / 120.0f;   // physics update rate
    const float maxFrameTime = 0.25f;      // clamp huge frame delays
    const Vec2 gravity = {0.0f, 980.0f};   // px/s^2
    const float groundY = 620.0f;

    RigidBody box;
    box.position = {300.0f, 120.0f};
    box.velocity = {120.0f, 0.0f};
    box.angle = 0.3f;
    box.angularVelocity = 1.5f;
    box.width = 100.0f;
    box.height = 50.0f;
    box.mass = 4.0f;
    box.restitution = 0.25f;
    box.friction = 0.7f;
    box.computeMassProperties();

    bool running = true;
    Uint64 prevCounter = SDL_GetPerformanceCounter();
    double accumulator = 0.0;

    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }

            if (event.type == SDL_KEYDOWN) {
                if (event.key.keysym.sym == SDLK_ESCAPE) {
                    running = false;
                }
                if (event.key.keysym.sym == SDLK_SPACE) {
                    // kick the box
                    box.applyImpulse({0.0f, -250.0f}, {0.0f, 0.0f});
                    box.angularVelocity += 1.0f;
                }
            }
        }

        Uint64 currentCounter = SDL_GetPerformanceCounter();
        double elapsed = (double)(currentCounter - prevCounter) /
                         (double)SDL_GetPerformanceFrequency();
        prevCounter = currentCounter;

        // Clamp frame time to avoid instability after stalls
        elapsed = std::min(elapsed, (double)maxFrameTime);
        accumulator += elapsed;

        while (accumulator >= fixedDt) {
            // External forces
            box.integrateForces(fixedDt, gravity);

            // Integrate motion
            box.integrateVelocity(fixedDt);

            // Collision detection/resolution
            Contact contact;
            if (detectGroundContact(box, groundY, contact)) {
                contact.normal = GROUND_NORMAL;
                resolveContact(contact);
            }

            // Mild damping for stability
            box.velocity *= 0.999f;
            box.angularVelocity *= 0.999f;

            box.clearAccumulators();
            accumulator -= fixedDt;
        }

        // Render
        SDL_SetRenderDrawColor(renderer, 18, 18, 22, 255);
        SDL_RenderClear(renderer);

        // Ground
        SDL_SetRenderDrawColor(renderer, 180, 180, 180, 255);
        SDL_RenderDrawLine(renderer, 0, (int)groundY, 1000, (int)groundY);

        // Box
        SDL_SetRenderDrawColor(renderer, 80, 220, 120, 255);
        drawPolygon(renderer, box.getWorldVertices());

        // Center marker
        SDL_SetRenderDrawColor(renderer, 255, 80, 80, 255);
        SDL_Rect centerRect{
            (int)(box.position.x - 3),
            (int)(box.position.y - 3),
            6, 6
        };
        SDL_RenderFillRect(renderer, &centerRect);

        SDL_RenderPresent(renderer);

        // Optional frame cap for rendering ~60 FPS
        SDL_Delay(1);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
