<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Rigid Body Physics Simulation</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1b1b1b;
    }
  </style>
</head>
<body>
<canvas id="canvas"></canvas>
<script>
class Vec2 {
  constructor(x = 0, y = 0) {
    this.x = x;
    this.y = y;
  }

  clone() {
    return new Vec2(this.x, this.y);
  }

  add(v) {
    return new Vec2(this.x + v.x, this.y + v.y);
  }

  sub(v) {
    return new Vec2(this.x - v.x, this.y - v.y);
  }

  scale(s) {
    return new Vec2(this.x * s, this.y * s);
  }

  dot(v) {
    return this.x * v.x + this.y * v.y;
  }

  length() {
    return Math.hypot(this.x, this.y);
  }

  normalize() {
    const len = this.length();
    if (len === 0) return new Vec2(0, 0);
    return this.scale(1 / len);
  }

  static cross(a, b) {
    return a.x * b.y - a.y * b.x;
  }

  // scalar x vector => vector
  static crossSV(s, v) {
    return new Vec2(-s * v.y, s * v.x);
  }

  // vector x scalar => vector
  static crossVS(v, s) {
    return new Vec2(s * v.y, -s * v.x);
  }
}

class RigidBody {
  constructor({
    x, y, width, height,
    mass = 1,
    angle = 0,
    restitution = 0.3,
    color = "#4fc3f7"
  }) {
    this.position = new Vec2(x, y);
    this.velocity = new Vec2(0, 0);
    this.force = new Vec2(0, 0);

    this.angle = angle;
    this.angularVelocity = 0;
    this.torque = 0;

    this.width = width;
    this.height = height;

    this.mass = mass;
    this.invMass = mass > 0 ? 1 / mass : 0;

    // Moment of inertia for rectangle about center
    this.inertia = mass > 0 ? (mass * (width * width + height * height)) / 12 : 0;
    this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

    this.restitution = restitution;
    this.color = color;
  }

  applyForce(force, point = null) {
    this.force = this.force.add(force);
    if (point) {
      const r = point.sub(this.position);
      this.torque += Vec2.cross(r, force);
    }
  }

  integrateForces(dt, gravity) {
    if (this.invMass === 0) return;

    // Semi-implicit Euler
    this.velocity = this.velocity.add(gravity.scale(dt));
    this.velocity = this.velocity.add(this.force.scale(this.invMass * dt));
    this.angularVelocity += this.torque * this.invInertia * dt;
  }

  integrateVelocity(dt) {
    if (this.invMass === 0) return;

    this.position = this.position.add(this.velocity.scale(dt));
    this.angle += this.angularVelocity * dt;
  }

  clearAccumulators() {
    this.force = new Vec2(0, 0);
    this.torque = 0;
  }

  getVertices() {
    const hw = this.width / 2;
    const hh = this.height / 2;
    const c = Math.cos(this.angle);
    const s = Math.sin(this.angle);

    const local = [
      new Vec2(-hw, -hh),
      new Vec2(hw, -hh),
      new Vec2(hw, hh),
      new Vec2(-hw, hh)
    ];

    return local.map(v => {
      const x = v.x * c - v.y * s + this.position.x;
      const y = v.x * s + v.y * c + this.position.y;
      return new Vec2(x, y);
    });
  }

  draw(ctx) {
    const verts = this.getVertices();

    ctx.beginPath();
    ctx.moveTo(verts[0].x, verts[0].y);
    for (let i = 1; i < verts.length; i++) {
      ctx.lineTo(verts[i].x, verts[i].y);
    }
    ctx.closePath();

    ctx.fillStyle = this.color;
    ctx.fill();

    ctx.strokeStyle = "#ffffff22";
    ctx.stroke();

    // Orientation line
    ctx.beginPath();
    ctx.moveTo(this.position.x, this.position.y);
    ctx.lineTo(
      this.position.x + Math.cos(this.angle) * this.width * 0.5,
      this.position.y + Math.sin(this.angle) * this.width * 0.5
    );
    ctx.strokeStyle = "#fff";
    ctx.stroke();
  }
}

class PhysicsWorld {
  constructor(gravity = new Vec2(0, 500)) {
    this.gravity = gravity;
    this.bodies = [];
    this.groundY = 600;
  }

  addBody(body) {
    this.bodies.push(body);
  }

  step(dt) {
    // Integrate forces
    for (const body of this.bodies) {
      body.integrateForces(dt, this.gravity);
    }

    // Integrate velocities
    for (const body of this.bodies) {
      body.integrateVelocity(dt);
    }

    // Handle collisions with ground
    for (const body of this.bodies) {
      this.resolveGroundCollision(body);
      body.clearAccumulators();
    }
  }

  resolveGroundCollision(body) {
    if (body.invMass === 0) return;

    const verts = body.getVertices();
    let deepest = null;
    let maxPenetration = 0;

    for (const v of verts) {
      if (v.y > this.groundY) {
        const penetration = v.y - this.groundY;
        if (penetration > maxPenetration) {
          maxPenetration = penetration;
          deepest = v;
        }
      }
    }

    if (!deepest) return;

    const normal = new Vec2(0, -1);

    // Positional correction
    body.position.y -= maxPenetration;

    const contactPoint = deepest;
    const r = contactPoint.sub(body.position);

    const velAtPoint = body.velocity.add(Vec2.crossSV(body.angularVelocity, r));
    const velAlongNormal = velAtPoint.dot(normal);

    if (velAlongNormal > 0) return;

    const e = body.restitution;

    const rCrossN = Vec2.cross(r, normal);
    const denom = body.invMass + (rCrossN * rCrossN) * body.invInertia;

    const j = -(1 + e) * velAlongNormal / denom;
    const impulse = normal.scale(j);

    body.velocity = body.velocity.add(impulse.scale(body.invMass));
    body.angularVelocity += body.invInertia * Vec2.cross(r, impulse);

    // Simple friction
    const tangentVel = velAtPoint.sub(normal.scale(velAtPoint.dot(normal)));
    const tangent = tangentVel.length() > 0 ? tangentVel.normalize().scale(-1) : new Vec2(0, 0);

    const rCrossT = Vec2.cross(r, tangent);
    const denomT = body.invMass + (rCrossT * rCrossT) * body.invInertia;

    let jt = 0;
    if (denomT > 0) {
      jt = tangentVel.length() / denomT;
    }

    const mu = 0.4;
    jt = Math.min(jt, j * mu);

    const frictionImpulse = tangent.scale(jt);
    body.velocity = body.velocity.add(frictionImpulse.scale(body.invMass));
    body.angularVelocity += body.invInertia * Vec2.cross(r, frictionImpulse);

    // Dampen tiny jitter
    if (Math.abs(body.velocity.y) < 5) body.velocity.y = 0;
    if (Math.abs(body.angularVelocity) < 0.05) body.angularVelocity = 0;
  }

  draw(ctx, canvas) {
    for (const body of this.bodies) {
      body.draw(ctx);
    }

    // Draw ground
    ctx.beginPath();
    ctx.moveTo(0, this.groundY);
    ctx.lineTo(canvas.width, this.groundY);
    ctx.strokeStyle = "#66bb6a";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.lineWidth = 1;
  }
}

// Setup canvas
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

// Create world
const world = new PhysicsWorld(new Vec2(0, 900));
world.groundY = canvas.height - 80;

// Static floor body not needed since we use analytic ground

// Add some dynamic boxes
for (let i = 0; i < 8; i++) {
  const body = new RigidBody({
    x: 200 + i * 70,
    y: 100 + i * 20,
    width: 50,
    height: 30,
    mass: 1 + Math.random() * 2,
    angle: Math.random() * 0.5,
    restitution: 0.2 + Math.random() * 0.4,
    color: `hsl(${180 + i * 20}, 80%, 60%)`
  });

  body.velocity = new Vec2((Math.random() - 0.5) * 100, Math.random() * 50);
  body.angularVelocity = (Math.random() - 0.5) * 4;
  world.addBody(body);
}

// Fixed timestep loop
const FIXED_DT = 1 / 120;
const MAX_FRAME_TIME = 0.25; // clamp huge frame jumps
let accumulator = 0;
let lastTime = performance.now();

function loop(now) {
  let frameTime = (now - lastTime) / 1000;
  lastTime = now;

  // Clamp to avoid spiral of death
  frameTime = Math.min(frameTime, MAX_FRAME_TIME);
  accumulator += frameTime;

  while (accumulator >= FIXED_DT) {
    world.step(FIXED_DT);
    accumulator -= FIXED_DT;
  }

  render();
  requestAnimationFrame(loop);
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  world.draw(ctx, canvas);

  ctx.fillStyle = "#fff";
  ctx.font = "14px monospace";
  ctx.fillText("Rigid Body Physics Demo", 20, 30);
  ctx.fillText("Fixed timestep: 1/120 s", 20, 50);
  ctx.fillText("Ground collision + angular response", 20, 70);
}

requestAnimationFrame(loop);

// Click to spawn new boxes
canvas.addEventListener("click", (e) => {
  const body = new RigidBody({
    x: e.clientX,
    y: e.clientY,
    width: 40 + Math.random() * 30,
    height: 20 + Math.random() * 30,
    mass: 1 + Math.random() * 3,
    angle: Math.random() * Math.PI,
    restitution: 0.2 + Math.random() * 0.5,
    color: `hsl(${Math.random() * 360}, 80%, 60%)`
  });

  body.velocity = new Vec2((Math.random() - 0.5) * 200, -100 - Math.random() * 200);
  body.angularVelocity = (Math.random() - 0.5) * 8;
  world.addBody(body);
});
</script>
