constexpr float PI = 3.14159265359f;

// -----------------------------
// Basic Math Types
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& b) const { return Vec3(x + b.x, y + b.y, z + b.z); }
    Vec3 operator-(const Vec3& b) const { return Vec3(x - b.x, y - b.y, z - b.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3& operator-=(const Vec3& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& b) const { return x*b.x + y*b.y + z*b.z; }

    Vec3 cross(const Vec3& b) const {
        return Vec3(
            y*b.z - z*b.y,
            z*b.x - x*b.z,
            x*b.y - y*b.x
        );
    }

    float length() const { return std::sqrt(x*x + y*y + z*z); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-8f) return Vec3(0,0,0);
        return *this / len;
    }
};

struct Mat3 {
    float m[3][3];

    Mat3() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                m[i][j] = 0.0f;
    }

    static Mat3 identity() {
        Mat3 r;
        r.m[0][0] = r.m[1][1] = r.m[2][2] = 1.0f;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }

    Mat3 operator*(const Mat3& b) const {
        Mat3 r;
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                for (int k = 0; k < 3; ++k) {
                    r.m[i][j] += m[i][k] * b.m[k][j];
                }
            }
        }
        return r;
    }

    Mat3 transpose() const {
        Mat3 r;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                r.m[i][j] = m[j][i];
        return r;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator+(const Quat& b) const {
        return Quat(w + b.w, x + b.x, y + b.y, z + b.z);
    }

    Quat operator*(float s) const {
        return Quat(w*s, x*s, y*s, z*s);
    }

    Quat operator*(const Quat& b) const {
        return Quat(
            w*b.w - x*b.x - y*b.y - z*b.z,
            w*b.x + x*b.w + y*b.z - z*b.y,
            w*b.y - x*b.z + y*b.w + z*b.x,
            w*b.z + x*b.y - y*b.x + z*b.w
        );
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-8f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    Mat3 toMat3() const {
        Mat3 r;
        float xx = x*x, yy = y*y, zz = z*z;
        float xy = x*y, xz = x*z, yz = y*z;
        float wx = w*x, wy = w*y, wz = w*z;

        r.m[0][0] = 1.0f - 2.0f*(yy + zz);
        r.m[0][1] = 2.0f*(xy - wz);
        r.m[0][2] = 2.0f*(xz + wy);

        r.m[1][0] = 2.0f*(xy + wz);
        r.m[1][1] = 1.0f - 2.0f*(xx + zz);
        r.m[1][2] = 2.0f*(yz - wx);

        r.m[2][0] = 2.0f*(xz - wy);
        r.m[2][1] = 2.0f*(yz + wx);
        r.m[2][2] = 1.0f - 2.0f*(xx + yy);

        return r;
    }
};

// -----------------------------
// Rigid Body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    Mat3 inertiaBody;
    Mat3 invInertiaBody;

    float radius; // simple sphere approximation for collision/rendering

    bool isStatic = false;

    RigidBody(float m, float r, const Vec3& pos)
        : position(pos), orientation(), linearVelocity(), angularVelocity(),
          forceAccum(), torqueAccum(), mass(m), radius(r)
    {
        if (m <= 0.0f) {
            isStatic = true;
            mass = 0.0f;
            invMass = 0.0f;
            inertiaBody = Mat3::identity();
            invInertiaBody = Mat3();
        } else {
            invMass = 1.0f / mass;

            // Sphere inertia tensor: I = 2/5 m r^2
            float I = 0.4f * mass * radius * radius;
            inertiaBody = Mat3();
            inertiaBody.m[0][0] = I;
            inertiaBody.m[1][1] = I;
            inertiaBody.m[2][2] = I;

            invInertiaBody = Mat3();
            invInertiaBody.m[0][0] = 1.0f / I;
            invInertiaBody.m[1][1] = 1.0f / I;
            invInertiaBody.m[2][2] = 1.0f / I;
        }
    }

    Mat3 getInvInertiaWorld() const {
        Mat3 R = orientation.toMat3();
        return R * invInertiaBody * R.transpose();
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& pointWorld) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = pointWorld - position;
        torqueAccum += r.cross(force);
    }

    void clearAccumulators() {
        forceAccum = Vec3(0,0,0);
        torqueAccum = Vec3(0,0,0);
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Linear
        Vec3 acceleration = forceAccum * invMass;
        linearVelocity += acceleration * dt;
        position += linearVelocity * dt;

        // Angular
        Mat3 invInertiaWorld = getInvInertiaWorld();
        Vec3 angularAcc = invInertiaWorld * torqueAccum;
        angularVelocity += angularAcc * dt;

        // Orientation update: q' = 0.5 * omegaQuat * q
        Quat omega(0, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat qDot = omega * orientation * 0.5f;
        orientation = orientation + qDot * dt;
        orientation.normalize();

        clearAccumulators();
    }
};

// -----------------------------
// Physics World
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);

    void step(float dt) {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        for (auto& body : bodies) {
            body.integrate(dt);
            solveGroundCollision(body);
        }
    }

private:
    void solveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        const float groundY = 0.0f;
        const float restitution = 0.5f;
        const float friction = 0.8f;

        float penetration = groundY - (body.position.y - body.radius);
        if (penetration > 0.0f) {
            // Positional correction
            body.position.y += penetration;

            Vec3 normal(0, 1, 0);

            // Contact point at bottom of sphere
            Vec3 contactPoint = body.position - Vec3(0, body.radius, 0);
            Vec3 r = contactPoint - body.position;

            Vec3 contactVel = body.linearVelocity + body.angularVelocity.cross(r);
            float velAlongNormal = contactVel.dot(normal);

            if (velAlongNormal < 0.0f) {
                Mat3 invInertiaWorld = body.getInvInertiaWorld();

                Vec3 rn = r.cross(normal);
                Vec3 angularTerm = (invInertiaWorld * rn).cross(r);

                float denom = body.invMass + normal.dot(angularTerm);
                float j = -(1.0f + restitution) * velAlongNormal / denom;

                Vec3 impulse = normal * j;
                body.linearVelocity += impulse * body.invMass;
                body.angularVelocity += invInertiaWorld * r.cross(impulse);

                // Friction impulse
                contactVel = body.linearVelocity + body.angularVelocity.cross(r);
                Vec3 tangent = contactVel - normal * contactVel.dot(normal);
                float tangentLen = tangent.length();

                if (tangentLen > 1e-6f) {
                    tangent = tangent / tangentLen;

                    Vec3 rt = r.cross(tangent);
                    Vec3 angularTermT = (invInertiaWorld * rt).cross(r);
                    float denomT = body.invMass + tangent.dot(angularTermT);

                    float jt = -contactVel.dot(tangent) / denomT;
                    float maxFriction = friction * j;
                    jt = std::clamp(jt, -maxFriction, maxFriction);

                    Vec3 frictionImpulse = tangent * jt;
                    body.linearVelocity += frictionImpulse * body.invMass;
                    body.angularVelocity += invInertiaWorld * r.cross(frictionImpulse);
                }
            }
        }
    }
};

// -----------------------------
// Simple Renderer Helper
// 2D projection for demonstration
// -----------------------------
void drawBody(SDL_Renderer* renderer, const RigidBody& body, int screenW, int screenH) {
    // Simple orthographic projection: x -> horizontal, y -> vertical
    float scale = 50.0f;
    int cx = static_cast<int>(screenW / 2 + body.position.x * scale);
    int cy = static_cast<int>(screenH - body.position.y * scale - 50);
    int r = static_cast<int>(body.radius * scale);

    for (int w = -r; w <= r; ++w) {
        for (int h = -r; h <= r; ++h) {
            if (w*w + h*h <= r*r) {
                SDL_RenderDrawPoint(renderer, cx + w, cy + h);
            }
        }
    }
}

int main(int argc, char** argv) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) != 0) {
        std::cerr << "SDL_Init failed: " << SDL_GetError() << "\n";
        return 1;
    }

    const int screenW = 800;
    const int screenH = 600;

    SDL_Window* window = SDL_CreateWindow(
        "Rigid Body Physics Simulation",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        screenW, screenH,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        std::cerr << "SDL_CreateWindow failed: " << SDL_GetError() << "\n";
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "SDL_CreateRenderer failed: " << SDL_GetError() << "\n";
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    PhysicsWorld world;
    world.bodies.emplace_back(2.0f, 0.5f, Vec3(-2.0f, 8.0f, 0.0f));
    world.bodies.emplace_back(1.0f, 0.4f, Vec3(0.0f, 12.0f, 0.0f));
    world.bodies.emplace_back(3.0f, 0.6f, Vec3(2.0f, 15.0f, 0.0f));

    // Give some initial spin/velocity
    world.bodies[0].linearVelocity = Vec3(2.0f, 0.0f, 0.0f);
    world.bodies[0].angularVelocity = Vec3(0.0f, 0.0f, 8.0f);

    world.bodies[1].linearVelocity = Vec3(-1.0f, 0.0f, 0.0f);
    world.bodies[1].angularVelocity = Vec3(0.0f, 0.0f, -5.0f);

    const float fixedDt = 1.0f / 120.0f;   // physics timestep
    const int targetFPS = 60;
    const float targetFrameTime = 1.0f / targetFPS;

    bool running = true;
    Uint64 prevCounter = SDL_GetPerformanceCounter();
    float accumulator = 0.0f;

    while (running) {
        Uint64 frameStart = SDL_GetPerformanceCounter();
        float deltaTime = static_cast<float>(frameStart - prevCounter) /
                          static_cast<float>(SDL_GetPerformanceFrequency());
        prevCounter = frameStart;

        // Avoid spiral of death after pause/hitch
        deltaTime = std::min(deltaTime, 0.25f);
        accumulator += deltaTime;

        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }
        }

        // Fixed-step physics
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render
        SDL_SetRenderDrawColor(renderer, 20, 20, 30, 255);
        SDL_RenderClear(renderer);

        // Draw ground
        SDL_SetRenderDrawColor(renderer, 100, 255, 100, 255);
        int groundScreenY = screenH - 50;
        SDL_RenderDrawLine(renderer, 0, groundScreenY, screenW, groundScreenY);

        SDL_SetRenderDrawColor(renderer, 200, 200, 255, 255);
        for (const auto& body : world.bodies) {
            drawBody(renderer, body, screenW, screenH);
        }

        SDL_RenderPresent(renderer);

        // Frame-rate cap
        Uint64 frameEnd = SDL_GetPerformanceCounter();
        float frameTime = static_cast<float>(frameEnd - frameStart) /
                          static_cast<float>(SDL_GetPerformanceFrequency());

        if (frameTime < targetFrameTime) {
            Uint32 delayMs = static_cast<Uint32>((targetFrameTime - frameTime) * 1000.0f);
            if (delayMs > 0) {
                SDL_Delay(delayMs);
            }
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
