</head>
<body>
  <div class="info">
    Real-time 2D rigid body simulation<br/>
    Click to spawn boxes
  </div>
  <canvas id="canvas"></canvas>

  <script>
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      clone() {
        return new Vec2(this.x, this.y);
      }

      set(x, y) {
        this.x = x;
        this.y = y;
        return this;
      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      dot(v) {
        return this.x * v.x + this.y * v.y;
      }

      length() {
        return Math.hypot(this.x, this.y);
      }

      normalize() {
        const len = this.length();
        if (len > 1e-8) {
          this.x /= len;
          this.y /= len;
        }
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }

      static dot(a, b) {
        return a.x * b.x + a.y * b.y;
      }

      static cross(a, b) {
        // 2D cross product returning scalar
        return a.x * b.y - a.y * b.x;
      }

      static crossScalarVec(s, v) {
        // scalar x vector => vector
        return new Vec2(-s * v.y, s * v.x);
      }
    }

    class RigidBody {
      constructor({
        x, y,
        width, height,
        mass = 1,
        angle = 0,
        vx = 0, vy = 0,
        angularVelocity = 0,
        restitution = 0.4,
        friction = 0.8,
        color = "#4fc3f7",
        isStatic = false
      }) {
        this.position = new Vec2(x, y);
        this.prevPosition = this.position.clone();

        this.velocity = new Vec2(vx, vy);
        this.force = new Vec2(0, 0);

        this.angle = angle;
        this.prevAngle = angle;
        this.angularVelocity = angularVelocity;
        this.torque = 0;

        this.width = width;
        this.height = height;

        this.restitution = restitution;
        this.friction = friction;
        this.color = color;
        this.isStatic = isStatic;

        if (isStatic) {
          this.mass = Infinity;
          this.invMass = 0;
          this.inertia = Infinity;
          this.invInertia = 0;
        } else {
          this.mass = mass;
          this.invMass = 1 / mass;
          this.inertia = (mass * (width * width + height * height)) / 12;
          this.invInertia = 1 / this.inertia;
        }
      }

      applyForce(force, point = null) {
        if (this.isStatic) return;
        this.force.add(force);

        if (point) {
          const r = Vec2.sub(point, this.position);
          this.torque += Vec2.cross(r, force);
        }
      }

      applyImpulse(impulse, contactVector) {
        if (this.isStatic) return;

        this.velocity.add(Vec2.scale(impulse, this.invMass));
        this.angularVelocity += this.invInertia * Vec2.cross(contactVector, impulse);
      }

      integrate(dt, gravity) {
        if (this.isStatic) return;

        this.prevPosition = this.position.clone();
        this.prevAngle = this.angle;

        // Linear integration
        const acceleration = Vec2.add(Vec2.scale(this.force, this.invMass), gravity);
        this.velocity.add(Vec2.scale(acceleration, dt));
        this.position.add(Vec2.scale(this.velocity, dt));

        // Angular integration
        const angularAcceleration = this.torque * this.invInertia;
        this.angularVelocity += angularAcceleration * dt;
        this.angle += this.angularVelocity * dt;

        // Damping
        this.velocity.scale(0.999);
        this.angularVelocity *= 0.999;

        // Clear accumulators
        this.force.set(0, 0);
        this.torque = 0;
      }

      getVertices(interpolated = false, alpha = 1) {
        const pos = interpolated
          ? new Vec2(
              this.prevPosition.x + (this.position.x - this.prevPosition.x) * alpha,
              this.prevPosition.y + (this.position.y - this.prevPosition.y) * alpha
            )
          : this.position;

        const ang = interpolated
          ? this.prevAngle + (this.angle - this.prevAngle) * alpha
          : this.angle;

        const hw = this.width / 2;
        const hh = this.height / 2;
        const c = Math.cos(ang);
        const s = Math.sin(ang);

        const local = [
          new Vec2(-hw, -hh),
          new Vec2(hw, -hh),
          new Vec2(hw, hh),
          new Vec2(-hw, hh)
        ];

        return local.map(v => {
          const x = v.x * c - v.y * s + pos.x;
          const y = v.x * s + v.y * c + pos.y;
          return new Vec2(x, y);
        });
      }
    }

    class PhysicsWorld {
      constructor() {
        this.bodies = [];
        this.gravity = new Vec2(0, 900); // pixels/s^2
        this.groundY = 650;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        for (const body of this.bodies) {
          body.integrate(dt, this.gravity);
          this.solveGroundCollision(body);
        }
      }

      solveGroundCollision(body) {
        if (body.isStatic) return;

        const verts = body.getVertices(false);
        let deepestPenetration = 0;
        let contactPoint = null;

        for (const v of verts) {
          const penetration = v.y - this.groundY;
          if (penetration > deepestPenetration) {
            deepestPenetration = penetration;
            contactPoint = v;
          }
        }

        if (deepestPenetration <= 0 || !contactPoint) return;

        const normal = new Vec2(0, -1);

        // Positional correction
        body.position.y -= deepestPenetration;

        const r = Vec2.sub(contactPoint, body.position);
        const tangentVel = Vec2.crossScalarVec(body.angularVelocity, r);
        const contactVelocity = Vec2.add(body.velocity, tangentVel);

        const velAlongNormal = Vec2.dot(contactVelocity, normal);

        if (velAlongNormal > 0) return;

        const e = body.restitution;

        const rCrossN = Vec2.cross(r, normal);
        const invMassSum = body.invMass + (rCrossN * rCrossN) * body.invInertia;

        let j = -(1 + e) * velAlongNormal;
        j /= invMassSum;

        const impulse = Vec2.scale(normal, j);
        body.applyImpulse(impulse, r);

        // Friction impulse
        const tangent = Vec2.sub(contactVelocity, Vec2.scale(normal, Vec2.dot(contactVelocity, normal)));
        if (tangent.length() > 1e-8) {
          tangent.normalize();

          const velAlongTangent = Vec2.dot(contactVelocity, tangent);
          const rCrossT = Vec2.cross(r, tangent);
          const denom = body.invMass + (rCrossT * rCrossT) * body.invInertia;

          let jt = -velAlongTangent / denom;

          const mu = body.friction;
          const maxFriction = j * mu;

          jt = Math.max(-maxFriction, Math.min(jt, maxFriction));

          const frictionImpulse = Vec2.scale(tangent, jt);
          body.applyImpulse(frictionImpulse, r);
        }

        // Kill tiny jitter near rest
        if (Math.abs(body.velocity.y) < 5) body.velocity.y = 0;
        if (Math.abs(body.angularVelocity) < 0.05) body.angularVelocity = 0;
      }
    }

    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      world.groundY = canvas.height - 80;
    }
    window.addEventListener("resize", resize);

    const world = new PhysicsWorld();

    function spawnBox(x, y) {
      const w = 30 + Math.random() * 50;
      const h = 30 + Math.random() * 50;
      const mass = (w * h) / 1500;

      const body = new RigidBody({
        x,
        y,
        width: w,
        height: h,
        mass,
        angle: Math.random() * Math.PI,
        vx: (Math.random() - 0.5) * 200,
        vy: Math.random() * 50,
        angularVelocity: (Math.random() - 0.5) * 4,
        restitution: 0.3 + Math.random() * 0.3,
        friction: 0.5 + Math.random() * 0.4,
        color: `hsl(${Math.random() * 360}, 80%, 65%)`
      });

      world.addBody(body);
    }

    for (let i = 0; i < 8; i++) {
      spawnBox(150 + i * 70, 100 + i * 20);
    }

    canvas.addEventListener("click", (e) => {
      spawnBox(e.clientX, e.clientY);
    });

    resize();

    // Fixed timestep loop
    const FIXED_DT = 1 / 120;
    const MAX_FRAME_TIME = 0.25;
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // Clamp to avoid spiral of death on tab switch / lag spike
      frameTime = Math.min(frameTime, MAX_FRAME_TIME);
      accumulator += frameTime;

      while (accumulator >= FIXED_DT) {
        world.step(FIXED_DT);
        accumulator -= FIXED_DT;
      }

      const alpha = accumulator / FIXED_DT;
      render(alpha);

      requestAnimationFrame(loop);
    }

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Ground
      ctx.strokeStyle = "#888";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, world.groundY);
      ctx.lineTo(canvas.width, world.groundY);
      ctx.stroke();

      // Bodies
      for (const body of world.bodies) {
        const verts = body.getVertices(true, alpha);

        ctx.beginPath();
        ctx.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < verts.length; i++) {
          ctx.lineTo(verts[i].x, verts[i].y);
        }
        ctx.closePath();

        ctx.fillStyle = body.color;
        ctx.fill();
        ctx.strokeStyle = "#000";
        ctx.stroke();

        // Orientation marker
        const center = new Vec2(
          body.prevPosition.x + (body.position.x - body.prevPosition.x) * alpha,
          body.prevPosition.y + (body.position.y - body.prevPosition.y) * alpha
        );
        const ang = body.prevAngle + (body.angle - body.prevAngle) * alpha;

        ctx.beginPath();
        ctx.moveTo(center.x, center.y);
        ctx.lineTo(
          center.x + Math.cos(ang) * body.width * 0.5,
          center.y + Math.sin(ang) * body.width * 0.5
        );
        ctx.strokeStyle = "#fff";
        ctx.stroke();
      }
    }

    loop();
  </script>
</body>
</html>
```

