## C++ Example

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr float FIXED_DT = 1.0f / 60.0f;
constexpr float MAX_FRAME_TIME = 0.25f; // clamp to avoid spiral of death
constexpr int MAX_SUBSTEPS = 8;

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
    Vec3& operator-=(const Vec3& r) { x -= r.x; y -= r.y; z -= r.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& r) const { return x * r.x + y * r.y + z * r.z; }

    Vec3 cross(const Vec3& r) const {
        return Vec3(
            y * r.z - z * r.y,
            z * r.x - x * r.z,
            x * r.y - y * r.x
        );
    }

    float length() const { return std::sqrt(x*x + y*y + z*z); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3();
        return *this / len;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator*(const Quat& q) const {
        return Quat(
            w*q.w - x*q.x - y*q.y - z*q.z,
            w*q.x + x*q.w + y*q.z - z*q.y,
            w*q.y - x*q.z + y*q.w + z*q.x,
            w*q.z + x*q.y - y*q.x + z*q.w
        );
    }

    Quat operator*(float s) const {
        return Quat(w*s, x*s, y*s, z*s);
    }

    Quat operator+(const Quat& q) const {
        return Quat(w+q.w, x+q.x, y+q.y, z+q.z);
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-6f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    static Quat fromAngularVelocity(const Vec3& omega) {
        return Quat(0.0f, omega.x, omega.y, omega.z);
    }
};

struct RigidBody {
    float mass;
    float invMass;

    // Simplified scalar inertia for demo purposes
    float inertia;
    float invInertia;

    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    Quat orientation;
    Vec3 angularVelocity;
    Vec3 torqueAccum;

    float restitution;
    float linearDamping;
    float angularDamping;
    float radius; // sphere collider for simple collision

    bool isStatic;

    RigidBody(float m, const Vec3& pos, float r, bool staticBody = false)
        : mass(m),
          invMass((m > 0.0f && !staticBody) ? 1.0f / m : 0.0f),
          position(pos),
          velocity(),
          forceAccum(),
          orientation(),
          angularVelocity(),
          torqueAccum(),
          restitution(0.5f),
          linearDamping(0.999f),
          angularDamping(0.995f),
          radius(r),
          isStatic(staticBody)
    {
        if (staticBody || m <= 0.0f) {
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            // Sphere inertia: I = 2/5 m r^2
            inertia = 0.4f * mass * radius * radius;
            invInertia = 1.0f / inertia;
        }
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyTorque(const Vec3& torque) {
        if (isStatic) return;
        torqueAccum += torque;
    }

    void clearAccumulators() {
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Semi-implicit Euler integration
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        velocity *= std::pow(linearDamping, dt * 60.0f);
        position += velocity * dt;

        Vec3 angularAcceleration = torqueAccum * invInertia;
        angularVelocity += angularAcceleration * dt;
        angularVelocity *= std::pow(angularDamping, dt * 60.0f);

        Quat omega = Quat::fromAngularVelocity(angularVelocity);
        Quat dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
    float groundY = 0.0f;

    void step(float dt) {
        applyGlobalForces();
        integrateBodies(dt);
        solveCollisions();
    }

    void applyGlobalForces() {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }
    }

    void integrateBodies(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

    void solveCollisions() {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // Sphere-ground collision
            float penetration = (groundY + body.radius) - body.position.y;
            if (penetration > 0.0f) {
                // Positional correction
                body.position.y += penetration;

                // Velocity response
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // crude friction
                    body.velocity.x *= 0.8f;
                    body.velocity.z *= 0.8f;
                }
            }
        }

        // Simple sphere-sphere collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];
                if (a.isStatic && b.isStatic) continue;

                Vec3 delta = b.position - a.position;
                float dist = delta.length();
                float minDist = a.radius + b.radius;

                if (dist < minDist && dist > 1e-6f) {
                    Vec3 normal = delta / dist;
                    float penetration = minDist - dist;

                    float totalInvMass = a.invMass + b.invMass;
                    if (totalInvMass <= 0.0f) continue;

                    // Positional correction
                    Vec3 correction = normal * (penetration / totalInvMass);
                    if (!a.isStatic) a.position -= correction * a.invMass;
                    if (!b.isStatic) b.position += correction * b.invMass;

                    // Relative velocity
                    Vec3 rv = b.velocity - a.velocity;
                    float velAlongNormal = rv.dot(normal);

                    if (velAlongNormal > 0.0f) continue;

                    float e = std::min(a.restitution, b.restitution);
                    float jImpulse = -(1.0f + e) * velAlongNormal;
                    jImpulse /= totalInvMass;

                    Vec3 impulse = normal * jImpulse;
                    if (!a.isStatic) a.velocity -= impulse * a.invMass;
                    if (!b.isStatic) b.velocity += impulse * b.invMass;
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    world.bodies.emplace_back(1.0f, Vec3(0, 10, 0), 0.5f);
    world.bodies.emplace_back(2.0f, Vec3(1, 15, 0), 0.7f);
    world.bodies.emplace_back(0.0f, Vec3(0, 0, 0), 0.0f, true); // optional static placeholder

    world.bodies[0].velocity = Vec3(1.0f, 0.0f, 0.0f);
    world.bodies[1].velocity = Vec3(-0.5f, 0.0f, 0.0f);
    world.bodies[1].applyTorque(Vec3(0.0f, 0.0f, 1.0f));

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();
    float accumulator = 0.0f;

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto currentTime = clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = std::min(elapsed.count(), MAX_FRAME_TIME);
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS) {
            world.step(FIXED_DT);
            accumulator -= FIXED_DT;
            substeps++;
        }

        // If we hit substep cap, discard excess to preserve real-time behavior
        if (substeps == MAX_SUBSTEPS && accumulator >= FIXED_DT) {
            accumulator = 0.0f;
        }

        // Render / debug output
        std::cout << "Frame " << frameCount++ << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            if (b.isStatic) continue;
            std::cout << "Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                      << "\n";
        }
        std::cout << "----\n";

        // Simulate rendering frame cap ~60 FPS
        std::this_thread::sleep_for(std::chrono::milliseconds(16));

        if (frameCount > 300) {
            running = false;
        }
    }

    return 0;
}
