## C++ Example: Real-Time Rigid Body Physics

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const {
        return Vec3(x + other.x, y + other.y, z + other.z);
    }

    Vec3 operator-(const Vec3& other) const {
        return Vec3(x - other.x, y - other.y, z - other.z);
    }

    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    Vec3 operator/(float s) const {
        return Vec3(x / s, y / s, z / s);
    }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }

    Vec3& operator-=(const Vec3& other) {
        x -= other.x; y -= other.y; z -= other.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float length() const {
        return std::sqrt(dot(*this));
    }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3();
        return *this / len;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    float mass;
    float invMass;
    float restitution;
    float linearDamping;
    float radius;

    RigidBody(const Vec3& pos, float m, float r)
        : position(pos),
          velocity(0, 0, 0),
          forceAccum(0, 0, 0),
          mass(m),
          invMass(m > 0.0f ? 1.0f / m : 0.0f),
          restitution(0.7f),
          linearDamping(0.999f),
          radius(r) {}

    void applyForce(const Vec3& force) {
        forceAccum += force;
    }

    void integrate(float dt) {
        if (invMass <= 0.0f) return;

        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        velocity *= std::pow(linearDamping, dt * 60.0f);
        position += velocity * dt;

        forceAccum = Vec3(0, 0, 0);
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;

    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void step(float dt) {
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.applyForce(gravity * body.mass);
            }
        }

        for (auto& body : bodies) {
            body.integrate(dt);
            solveGroundCollision(body);
        }
    }

private:
    void solveGroundCollision(RigidBody& body) {
        const float groundY = 0.0f;

        if (body.position.y - body.radius < groundY) {
            body.position.y = groundY + body.radius;

            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;
            }

            // Basic friction on contact
            body.velocity.x *= 0.98f;
            body.velocity.z *= 0.98f;

            // Stop tiny bouncing jitter
            if (std::fabs(body.velocity.y) < 0.05f) {
                body.velocity.y = 0.0f;
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(2.0f, 15.0f, 0.0f), 2.0f, 0.75f);

    using clock = std::chrono::high_resolution_clock;

    const double fixedTimeStep = 1.0 / 120.0;   // 120 Hz physics
    const double maxFrameTime = 0.25;           // avoid spiral of death
    const int targetFPS = 60;
    const auto targetFrameDuration = std::chrono::microseconds(1000000 / targetFPS);

    auto previousTime = clock::now();
    double accumulator = 0.0;

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto frameStart = clock::now();
        std::chrono::duration<double> elapsed = frameStart - previousTime;
        previousTime = frameStart;

        double frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedTimeStep) {
            world.step(static_cast<float>(fixedTimeStep));
            accumulator -= fixedTimeStep;
        }

        // Render / output state
        std::cout << "Frame " << frameCount++ << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ") "
                      << "Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }
        std::cout << "----------------------\n";

        if (frameCount > 600) {
            running = false;
        }

        auto frameEnd = clock::now();
        auto workTime = std::chrono::duration_cast<std::chrono::microseconds>(frameEnd - frameStart);

        if (workTime < targetFrameDuration) {
            std::this_thread::sleep_for(targetFrameDuration - workTime);
        }
    }

    return 0;
}
```

