## C++ Example: Real-Time Rigid Body Simulation Loop

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& rhs) {
        x += rhs.x; y += rhs.y; z += rhs.z;
        return *this;
    }

    Vec3& operator-=(const Vec3& rhs) {
        x -= rhs.x; y -= rhs.y; z -= rhs.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float length() const {
        return std::sqrt(x*x + y*y + z*z);
    }

    Vec3 normalized() const {
        float len = length();
        if (len <= 1e-6f) return Vec3();
        return *this / len;
    }

    static float dot(const Vec3& a, const Vec3& b) {
        return a.x*b.x + a.y*b.y + a.z*b.z;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 accumulatedForce;

    float mass;
    float invMass;
    float restitution;
    float linearDamping;
    float radius;

    RigidBody(const Vec3& pos, float m, float r)
        : position(pos),
          velocity(0, 0, 0),
          accumulatedForce(0, 0, 0),
          mass(m),
          invMass(m > 0.0f ? 1.0f / m : 0.0f),
          restitution(0.5f),
          linearDamping(0.99f),
          radius(r) {}

    bool isStatic() const {
        return invMass == 0.0f;
    }

    void applyForce(const Vec3& force) {
        accumulatedForce += force;
    }

    void clearForces() {
        accumulatedForce = Vec3(0, 0, 0);
    }

    void integrate(float dt) {
        if (isStatic()) return;

        Vec3 acceleration = accumulatedForce * invMass;
        velocity += acceleration * dt;
        velocity *= std::pow(linearDamping, dt * 60.0f);
        position += velocity * dt;

        clearForces();
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;

    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void step(float dt) {
        applyGlobalForces();
        integrateBodies(dt);
        solveCollisions();
    }

private:
    void applyGlobalForces() {
        for (auto& body : bodies) {
            if (!body.isStatic()) {
                body.applyForce(gravity * body.mass);
            }
        }
    }

    void integrateBodies(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

    void solveCollisions() {
        // Simple collision with ground plane at y = 0
        for (auto& body : bodies) {
            if (body.isStatic()) continue;

            float minY = body.radius;
            if (body.position.y < minY) {
                body.position.y = minY;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }

                // Simple friction approximation
                body.velocity.x *= 0.8f;
                body.velocity.z *= 0.8f;
            }
        }

        // Naive sphere-sphere collision
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveSphereCollision(bodies[i], bodies[j]);
            }
        }
    }

    void resolveSphereCollision(RigidBody& a, RigidBody& b) {
        Vec3 delta = b.position - a.position;
        float dist = delta.length();
        float minDist = a.radius + b.radius;

        if (dist <= 1e-6f || dist >= minDist) return;

        Vec3 normal = delta / dist;
        float penetration = minDist - dist;

        float totalInvMass = a.invMass + b.invMass;
        if (totalInvMass <= 0.0f) return;

        // Positional correction
        Vec3 correction = normal * (penetration / totalInvMass);
        if (!a.isStatic()) a.position -= correction * a.invMass;
        if (!b.isStatic()) b.position += correction * b.invMass;

        // Relative velocity
        Vec3 relativeVelocity = b.velocity - a.velocity;
        float velAlongNormal = Vec3::dot(relativeVelocity, normal);

        if (velAlongNormal > 0.0f) return;

        float restitution = std::min(a.restitution, b.restitution);

        float impulseScalar = -(1.0f + restitution) * velAlongNormal;
        impulseScalar /= totalInvMass;

        Vec3 impulse = normal * impulseScalar;

        if (!a.isStatic()) a.velocity -= impulse * a.invMass;
        if (!b.isStatic()) b.velocity += impulse * b.invMass;
    }
};

int main() {
    PhysicsWorld world;

    world.bodies.emplace_back(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(0.8f, 12.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(2.0f, 15.0f, 0.0f), 2.0f, 0.7f);

    const float fixedTimeStep = 1.0f / 120.0f; // 120 Hz physics
    const float maxFrameTime = 0.25f;          // Avoid spiral of death
    const int targetFPS = 60;
    const auto targetFrameDuration = std::chrono::duration<double>(1.0 / targetFPS);

    double accumulator = 0.0;
    auto previousTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> frameTime = currentTime - previousTime;
        previousTime = currentTime;

        double dt = std::min(frameTime.count(), static_cast<double>(maxFrameTime));
        accumulator += dt;

        while (accumulator >= fixedTimeStep) {
            world.step(fixedTimeStep);
            accumulator -= fixedTimeStep;
        }

        // Render / output state
        std::cout << "Bodies:\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }
        std::cout << "-------------------------\n";

        // Frame-rate limiting
        auto frameEndTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> workTime = frameEndTime - currentTime;

        if (workTime < targetFrameDuration) {
            auto sleepTime = targetFrameDuration - workTime;
            std::this_thread::sleep_for(
                std::chrono::duration_cast<std::chrono::milliseconds>(sleepTime)
            );
        }
    }

    return 0;
}
```

---

## Key Design Points

### 1. Fixed timestep
Using:

```cpp
const float fixedTimeStep = 1.0f / 120.0f;
```

keeps the physics stable and deterministic compared to using variable `dt` directly.

---

### 2. Accumulator pattern
This part:

```cpp
accumulator += dt;
while (accumulator >= fixedTimeStep) {
    world.step(fixedTimeStep);
    accumulator -= fixedTimeStep;
}
```

allows rendering at one frame rate and physics at another.

---

### 3. Frame-rate limiting
This section caps rendering/update frequency:

```cpp
if (workTime < targetFrameDuration) {
    std::this_thread::sleep_for(...);
}
```

so the loop doesn’t run unnecessarily fast.

---

### 4. Spiral-of-death protection
This line:

```cpp
double dt = std::min(frameTime.count(), static_cast<double>(maxFrameTime));
```

prevents giant time steps after a pause or hitch.

