<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Rigid Body Physics Simulation</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
      color: white;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: #1b1b1b;
    }
    .info {
      position: fixed;
      top: 10px;
      left: 10px;
      background: rgba(0,0,0,0.4);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>
  <div class="info">
    Click to spawn circles<br />
    Fixed timestep physics @ 120 Hz
  </div>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Vector utilities
    // -----------------------------
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      clone() {
        return new Vec2(this.x, this.y);
      }

      set(x, y) {
        this.x = x;
        this.y = y;
        return this;
      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      length() {
        return Math.hypot(this.x, this.y);
      }

      lengthSq() {
        return this.x * this.x + this.y * this.y;
      }

      normalize() {
        const len = this.length();
        if (len > 1e-8) {
          this.x /= len;
          this.y /= len;
        }
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }

      static dot(a, b) {
        return a.x * b.x + a.y * b.y;
      }

      // 2D scalar cross product of vectors
      static cross(a, b) {
        return a.x * b.y - a.y * b.x;
      }

      // vector from scalar x vector: s × v
      static crossSV(s, v) {
        return new Vec2(-s * v.y, s * v.x);
      }

      // vector from vector x scalar: v × s
      static crossVS(v, s) {
        return new Vec2(s * v.y, -s * v.x);
      }
    }

    // -----------------------------
    // Rigid body: circle
    // -----------------------------
    class RigidBody {
      constructor({
        position,
        velocity = new Vec2(),
        radius = 20,
        density = 1,
        restitution = 0.8,
        friction = 0.2,
        angle = 0,
        angularVelocity = 0,
        isStatic = false,
        color = "orange"
      }) {
        this.position = position.clone();
        this.velocity = velocity.clone();
        this.force = new Vec2();

        this.angle = angle;
        this.angularVelocity = angularVelocity;
        this.torque = 0;

        this.radius = radius;
        this.restitution = restitution;
        this.friction = friction;
        this.isStatic = isStatic;
        this.color = color;

        if (isStatic) {
          this.mass = Infinity;
          this.invMass = 0;
          this.inertia = Infinity;
          this.invInertia = 0;
        } else {
          // 2D circle mass and inertia
          this.mass = Math.PI * radius * radius * density;
          this.invMass = 1 / this.mass;
          this.inertia = 0.5 * this.mass * radius * radius;
          this.invInertia = 1 / this.inertia;
        }
      }

      applyForce(force) {
        if (this.isStatic) return;
        this.force.add(force);
      }

      applyImpulse(impulse, contactVector) {
        if (this.isStatic) return;
        this.velocity.add(Vec2.scale(impulse, this.invMass));
        this.angularVelocity += this.invInertia * Vec2.cross(contactVector, impulse);
      }

      integrateForces(dt, gravity) {
        if (this.isStatic) return;

        // Semi-implicit Euler
        this.velocity.x += (gravity.x + this.force.x * this.invMass) * dt;
        this.velocity.y += (gravity.y + this.force.y * this.invMass) * dt;
        this.angularVelocity += this.torque * this.invInertia * dt;

        // Mild damping
        this.velocity.scale(0.999);
        this.angularVelocity *= 0.999;
      }

      integrateVelocity(dt) {
        if (this.isStatic) return;

        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;
      }

      clearAccumulators() {
        this.force.set(0, 0);
        this.torque = 0;
      }

      draw(ctx) {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);

        ctx.beginPath();
        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = "#fff";
        ctx.lineWidth = 2;
        ctx.stroke();

        // orientation line
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(this.radius, 0);
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 3;
        ctx.stroke();

        ctx.restore();
      }
    }

    // -----------------------------
    // Collision manifold
    // -----------------------------
    class Manifold {
      constructor(a, b) {
        this.a = a;
        this.b = b;
        this.normal = new Vec2();
        this.penetration = 0;
        this.contactPoint = new Vec2();
      }
    }

    function circleCircleCollision(a, b) {
      const n = Vec2.sub(b.position, a.position);
      const r = a.radius + b.radius;
      const distSq = n.lengthSq();

      if (distSq > r * r) return null;

      const manifold = new Manifold(a, b);
      const dist = Math.sqrt(distSq);

      if (dist !== 0) {
        manifold.penetration = r - dist;
        manifold.normal = Vec2.scale(n, 1 / dist);
        manifold.contactPoint = Vec2.add(
          a.position,
          Vec2.scale(manifold.normal, a.radius - manifold.penetration * 0.5)
        );
      } else {
        // perfectly overlapping
        manifold.penetration = a.radius;
        manifold.normal = new Vec2(1, 0);
        manifold.contactPoint = a.position.clone();
      }

      return manifold;
    }

    function resolveCollision(m) {
      const a = m.a;
      const b = m.b;

      if (a.invMass + b.invMass === 0) return;

      const ra = Vec2.sub(m.contactPoint, a.position);
      const rb = Vec2.sub(m.contactPoint, b.position);

      const velA = Vec2.add(a.velocity, Vec2.crossSV(a.angularVelocity, ra));
      const velB = Vec2.add(b.velocity, Vec2.crossSV(b.angularVelocity, rb));
      const rv = Vec2.sub(velB, velA);

      const velAlongNormal = Vec2.dot(rv, m.normal);

      // Do not resolve if separating
      if (velAlongNormal > 0) return;

      const e = Math.min(a.restitution, b.restitution);

      const raCrossN = Vec2.cross(ra, m.normal);
      const rbCrossN = Vec2.cross(rb, m.normal);

      const invMassSum =
        a.invMass +
        b.invMass +
        (raCrossN * raCrossN) * a.invInertia +
        (rbCrossN * rbCrossN) * b.invInertia;

      let j = -(1 + e) * velAlongNormal;
      j /= invMassSum;

      const impulse = Vec2.scale(m.normal, j);
      a.applyImpulse(Vec2.scale(impulse, -1), ra);
      b.applyImpulse(impulse, rb);

      // Friction impulse
      const velA2 = Vec2.add(a.velocity, Vec2.crossSV(a.angularVelocity, ra));
      const velB2 = Vec2.add(b.velocity, Vec2.crossSV(b.angularVelocity, rb));
      const rv2 = Vec2.sub(velB2, velA2);

      const tangent = Vec2.sub(rv2, Vec2.scale(m.normal, Vec2.dot(rv2, m.normal)));
      if (tangent.lengthSq() > 1e-8) tangent.normalize();

      let jt = -Vec2.dot(rv2, tangent);
      jt /= invMassSum;

      const mu = Math.sqrt(a.friction * b.friction);

      let frictionImpulse;
      if (Math.abs(jt) < j * mu) {
        frictionImpulse = Vec2.scale(tangent, jt);
      } else {
        frictionImpulse = Vec2.scale(tangent, -j * mu);
      }

      a.applyImpulse(Vec2.scale(frictionImpulse, -1), ra);
      b.applyImpulse(frictionImpulse, rb);
    }

    function positionalCorrection(m) {
      const a = m.a;
      const b = m.b;

      const percent = 0.8; // correction strength
      const slop = 0.01;   // penetration allowance

      const correctionMag =
        Math.max(m.penetration - slop, 0) / (a.invMass + b.invMass) * percent;

      const correction = Vec2.scale(m.normal, correctionMag);

      if (!a.isStatic) {
        a.position.sub(Vec2.scale(correction, a.invMass));
      }
      if (!b.isStatic) {
        b.position.add(Vec2.scale(correction, b.invMass));
      }
    }

    // -----------------------------
    // World
    // -----------------------------
    class PhysicsWorld {
      constructor() {
        this.bodies = [];
        this.gravity = new Vec2(0, 500); // pixels/s^2
        this.iterations = 6;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        // Integrate forces
        for (const body of this.bodies) {
          body.integrateForces(dt, this.gravity);
        }

        // Detect collisions
        const contacts = [];
        for (let i = 0; i < this.bodies.length; i++) {
          for (let j = i + 1; j < this.bodies.length; j++) {
            const a = this.bodies[i];
            const b = this.bodies[j];
            const m = circleCircleCollision(a, b);
            if (m) contacts.push(m);
          }
        }

        // Solve collisions iteratively
        for (let k = 0; k < this.iterations; k++) {
          for (const contact of contacts) {
            resolveCollision(contact);
          }
        }

        // Integrate velocities
        for (const body of this.bodies) {
          body.integrateVelocity(dt);
          this.handleBoundaryCollision(body);
          body.clearAccumulators();
        }

        // Positional correction
        for (const contact of contacts) {
          positionalCorrection(contact);
        }
      }

      handleBoundaryCollision(body) {
        if (body.isStatic) return;

        const r = body.radius;
        const bounce = body.restitution;

        // Left
        if (body.position.x - r < 0) {
          body.position.x = r;
          if (body.velocity.x < 0) body.velocity.x *= -bounce;
        }

        // Right
        if (body.position.x + r > canvas.width) {
          body.position.x = canvas.width - r;
          if (body.velocity.x > 0) body.velocity.x *= -bounce;
        }

        // Top
        if (body.position.y - r < 0) {
          body.position.y = r;
          if (body.velocity.y < 0) body.velocity.y *= -bounce;
        }

        // Bottom
        if (body.position.y + r > canvas.height) {
          body.position.y = canvas.height - r;
          if (body.velocity.y > 0) body.velocity.y *= -bounce;

          // crude floor friction
          body.velocity.x *= 0.98;
          body.angularVelocity *= 0.98;
        }
      }

      draw(ctx) {
        for (const body of this.bodies) {
          body.draw(ctx);
        }
      }
    }

    // -----------------------------
    // Setup
    // -----------------------------
    const world = new PhysicsWorld();

    function randomColor() {
      const colors = ["#ff8a65", "#4fc3f7", "#81c784", "#ffd54f", "#ba68c8"];
      return colors[Math.floor(Math.random() * colors.length)];
    }

    // Initial bodies
    for (let i = 0; i < 8; i++) {
      const radius = 15 + Math.random() * 25;
      world.addBody(new RigidBody({
        position: new Vec2(
          100 + Math.random() * (canvas.width - 200),
          50 + Math.random() * 200
        ),
        velocity: new Vec2(
          (Math.random() - 0.5) * 200,
          Math.random() * 50
        ),
        radius,
        density: 0.002,
        restitution: 0.85,
        friction: 0.3,
        angularVelocity: (Math.random() - 0.5) * 5,
        color: randomColor()
      }));
    }

    canvas.addEventListener("click", (e) => {
      const radius = 10 + Math.random() * 25;
      world.addBody(new RigidBody({
        position: new Vec2(e.clientX, e.clientY),
        velocity: new Vec2(
          (Math.random() - 0.5) * 300,
          -100 - Math.random() * 200
        ),
        radius,
        density: 0.002,
        restitution: 0.8,
        friction: 0.3,
        angularVelocity: (Math.random() - 0.5) * 10,
        color: randomColor()
      }));
    });

    // -----------------------------
    // Real-time loop with frame-rate constraints
    // -----------------------------
    const FIXED_DT = 1 / 120;     // 120 Hz physics
    const MAX_FRAME_TIME = 0.25;  // clamp large frame gaps
    const MAX_STEPS = 8;          // prevent spiral of death

    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // background grid
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1;
      for (let x = 0; x < canvas.width; x += 50) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      world.draw(ctx);
    }

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // Clamp frame time to avoid instability after tab switch / lag spike
      if (frameTime > MAX_FRAME_TIME) {
        frameTime = MAX_FRAME_TIME;
      }

      accumulator += frameTime;

      let steps = 0;
      while (accumulator >= FIXED_DT && steps < MAX_STEPS) {
        world.step(FIXED_DT);
        accumulator -= FIXED_DT;
        steps++;
      }

      // If too far behind, drop remaining accumulated time
      if (steps === MAX_STEPS) {
        accumulator = 0;
      }

      const alpha = accumulator / FIXED_DT;
      render(alpha);

      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

---

## Why this satisfies frame-rate constraints

The important part is the **fixed timestep loop**:

```js
const FIXED_DT = 1 / 120;
const MAX_FRAME_TIME = 0.25;
const MAX_STEPS = 8;
```

### 1. Fixed timestep
Physics always updates with the same `dt`, which improves stability:

```js
while (accumulator >= FIXED_DT && steps < MAX_STEPS) {
  world.step(FIXED_DT);
  accumulator -= FIXED_DT;
  steps++;
}
```

### 2. Frame time clamping
If the browser stalls or the tab resumes after being inactive, `frameTime` can become huge. This is clamped:

```js
if (frameTime > MAX_FRAME_TIME) {
  frameTime = MAX_FRAME_TIME;
}
```

### 3. Max physics steps per frame
This prevents the “spiral of death” where the simulation tries to catch up forever:

```js
if (steps === MAX_STEPS) {
  accumulator = 0;
}
```

