```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Rigid Body Physics Simulation</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
      color: #fff;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: #1a1a1a;
    }
    .info {
      position: absolute;
      top: 10px;
      left: 10px;
      background: rgba(0,0,0,0.4);
      padding: 8px 12px;
      border-radius: 6px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="info">
    Real-time 2D rigid body simulation<br>
    Fixed timestep + frame-rate constraints<br>
    Refresh page to restart
  </div>
  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Vector utilities
    // -----------------------------
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      clone() {
        return new Vec2(this.x, this.y);
      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      dot(v) {
        return this.x * v.x + this.y * v.y;
      }

      length() {
        return Math.hypot(this.x, this.y);
      }

      normalize() {
        const len = this.length();
        if (len > 1e-8) {
          this.x /= len;
          this.y /= len;
        }
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }
    }

    function cross2D(a, b) {
      // scalar cross product of 2D vectors
      return a.x * b.y - a.y * b.x;
    }

    function crossScalarVec(s, v) {
      // scalar x vector => vector
      return new Vec2(-s * v.y, s * v.x);
    }

    // -----------------------------
    // Rigid body
    // -----------------------------
    class RigidBody {
      constructor({
        x, y,
        width, height,
        mass = 1,
        angle = 0,
        vx = 0, vy = 0,
        angularVelocity = 0,
        restitution = 0.3,
        friction = 0.8,
        color = "#4fc3f7"
      }) {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2(vx, vy);
        this.force = new Vec2(0, 0);

        this.angle = angle;
        this.angularVelocity = angularVelocity;
        this.torque = 0;

        this.width = width;
        this.height = height;

        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        // Rectangle moment of inertia about center:
        // I = (1/12) * m * (w^2 + h^2)
        this.inertia = mass > 0 ? (mass * (width * width + height * height)) / 12 : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

        this.restitution = restitution;
        this.friction = friction;
        this.color = color;
      }

      applyForce(force, point = null) {
        this.force.add(force);
        if (point) {
          const r = Vec2.sub(point, this.position);
          this.torque += cross2D(r, force);
        }
      }

      integrateForces(dt, gravity) {
        if (this.invMass === 0) return;

        // Semi-implicit Euler
        this.velocity.x += (gravity.x + this.force.x * this.invMass) * dt;
        this.velocity.y += (gravity.y + this.force.y * this.invMass) * dt;
        this.angularVelocity += this.torque * this.invInertia * dt;
      }

      integrateVelocity(dt) {
        if (this.invMass === 0) return;

        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;

        // light damping for stability
        this.velocity.scale(0.999);
        this.angularVelocity *= 0.999;

        // clear accumulated force/torque
        this.force.x = 0;
        this.force.y = 0;
        this.torque = 0;
      }

      getVertices() {
        const hw = this.width / 2;
        const hh = this.height / 2;
        const c = Math.cos(this.angle);
        const s = Math.sin(this.angle);

        const local = [
          new Vec2(-hw, -hh),
          new Vec2(hw, -hh),
          new Vec2(hw, hh),
          new Vec2(-hw, hh)
        ];

        return local.map(v => {
          return new Vec2(
            this.position.x + v.x * c - v.y * s,
            this.position.y + v.x * s + v.y * c
          );
        });
      }

      draw(ctx) {
        const verts = this.getVertices();

        ctx.beginPath();
        ctx.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < verts.length; i++) {
          ctx.lineTo(verts[i].x, verts[i].y);
        }
        ctx.closePath();

        ctx.fillStyle = this.color;
        ctx.fill();

        ctx.strokeStyle = "#ffffff22";
        ctx.stroke();

        // orientation line
        ctx.beginPath();
        ctx.moveTo(this.position.x, this.position.y);
        ctx.lineTo(
          this.position.x + Math.cos(this.angle) * this.width * 0.5,
          this.position.y + Math.sin(this.angle) * this.width * 0.5
        );
        ctx.strokeStyle = "#fff";
        ctx.stroke();
      }
    }

    // -----------------------------
    // World
    // -----------------------------
    class PhysicsWorld {
      constructor() {
        this.bodies = [];
        this.gravity = new Vec2(0, 900); // px/s^2
        this.groundY = () => canvas.height - 80;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        // Integrate forces
        for (const body of this.bodies) {
          body.integrateForces(dt, this.gravity);
        }

        // Integrate velocities
        for (const body of this.bodies) {
          body.integrateVelocity(dt);
        }

        // Collisions
        for (const body of this.bodies) {
          this.solveGroundCollision(body);
        }
      }

      solveGroundCollision(body) {
        const verts = body.getVertices();
        let deepestPenetration = 0;
        let contactPoint = null;

        const ground = this.groundY();

        for (const v of verts) {
          const penetration = v.y - ground;
          if (penetration > deepestPenetration) {
            deepestPenetration = penetration;
            contactPoint = v.clone();
          }
        }

        if (deepestPenetration <= 0 || !contactPoint) return;

        const normal = new Vec2(0, -1);

        // positional correction
        body.position.y -= deepestPenetration + 0.01;

        // recompute contact vector after correction
        const r = Vec2.sub(contactPoint, body.position);

        // velocity at contact point
        const tangentVel = crossScalarVec(body.angularVelocity, r);
        const contactVel = Vec2.add(body.velocity, tangentVel);

        const velAlongNormal = contactVel.dot(normal);

        // if moving away, skip bounce impulse
        if (velAlongNormal > 0) return;

        const e = body.restitution;

        const rCrossN = cross2D(r, normal);
        const invMassSum = body.invMass + (rCrossN * rCrossN) * body.invInertia;

        const j = -(1 + e) * velAlongNormal / invMassSum;
        const impulse = Vec2.scale(normal, j);

        body.velocity.add(Vec2.scale(impulse, body.invMass));
        body.angularVelocity += body.invInertia * cross2D(r, impulse);

        // friction impulse
        const newTangentVel = crossScalarVec(body.angularVelocity, r);
        const newContactVel = Vec2.add(body.velocity, newTangentVel);

        const tangent = new Vec2(newContactVel.x, newContactVel.y);
        tangent.sub(Vec2.scale(normal, newContactVel.dot(normal)));

        if (tangent.length() > 1e-8) {
          tangent.normalize();

          const velAlongTangent = newContactVel.dot(tangent);
          const rCrossT = cross2D(r, tangent);
          const denomT = body.invMass + (rCrossT * rCrossT) * body.invInertia;

          let jt = -velAlongTangent / denomT;
          const mu = body.friction;

          // Coulomb friction clamp
          jt = Math.max(-j * mu, Math.min(j * mu, jt));

          const frictionImpulse = Vec2.scale(tangent, jt);
          body.velocity.add(Vec2.scale(frictionImpulse, body.invMass));
          body.angularVelocity += body.invInertia * cross2D(r, frictionImpulse);
        }
      }

      draw(ctx) {
        const ground = this.groundY();

        // ground
        ctx.beginPath();
        ctx.moveTo(0, ground);
        ctx.lineTo(canvas.width, ground);
        ctx.strokeStyle = "#7fff7f";
        ctx.lineWidth = 2;
        ctx.stroke();

        for (const body of this.bodies) {
          body.draw(ctx);
        }
      }
    }

    // -----------------------------
    // Setup
    // -----------------------------
    const world = new PhysicsWorld();

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    for (let i = 0; i < 8; i++) {
      world.addBody(new RigidBody({
        x: 150 + i * 80,
        y: 100 + i * 20,
        width: rand(30, 70),
        height: rand(20, 60),
        mass: rand(1, 5),
        angle: rand(-0.5, 0.5),
        vx: rand(-50, 50),
        vy: rand(-20, 20),
        angularVelocity: rand(-2, 2),
        restitution: 0.2 + Math.random() * 0.4,
        friction: 0.4 + Math.random() * 0.5,
        color: `hsl(${Math.random() * 360}, 70%, 60%)`
      }));
    }

    // -----------------------------
    // Real-time loop with fixed timestep
    // -----------------------------
    const FIXED_DT = 1 / 120;      // 120 Hz physics
    const MAX_FRAME_TIME = 0.25;   // clamp huge pauses
    const MAX_STEPS = 5;           // frame-rate constraint safeguard

    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // background grid
      ctx.strokeStyle = "#ffffff08";
      ctx.lineWidth = 1;
      for (let x = 0; x < canvas.width; x += 50) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      world.draw(ctx);

      ctx.fillStyle = "#fff";
      ctx.fillText(`Bodies: ${world.bodies.length}`, 20, canvas.height - 40);
      ctx.fillText(`Physics dt: ${(FIXED_DT * 1000).toFixed(2)} ms`, 20, canvas.height - 22);
    }

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // clamp frame time to avoid instability after tab switching / lag spikes
      if (frameTime > MAX_FRAME_TIME) {
        frameTime = MAX_FRAME_TIME;
      }

      accumulator += frameTime;

      let steps = 0;
      while (accumulator >= FIXED_DT && steps < MAX_STEPS) {
        world.step(FIXED_DT);
        accumulator -= FIXED_DT;
        steps++;
      }

      // If we hit max steps, drop leftover time to preserve frame-rate responsiveness
      if (steps === MAX_STEPS) {
        accumulator = 0;
      }

      const alpha = accumulator / FIXED_DT;
      render(alpha);

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
