## Initial Implementation

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Rigid Body Physics Simulation</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1e1e1e;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>

  <script>
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      clone() {
        return new Vec2(this.x, this.y);
      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }
    }

    class RigidBody {
      constructor({
        position = new Vec2(),
        velocity = new Vec2(),
        mass = 1,
        radius = 20,
        restitution = 0.7,
        isStatic = false,
        color = "#4fc3f7"
      } = {}) {
        this.position = position;
        this.velocity = velocity;
        this.force = new Vec2();
        this.mass = isStatic ? Infinity : mass;
        this.invMass = isStatic ? 0 : 1 / mass;
        this.radius = radius;
        this.restitution = restitution;
        this.isStatic = isStatic;
        this.color = color;
      }

      applyForce(force) {
        if (this.isStatic) return;
        this.force.add(force);
      }

      integrate(dt) {
        if (this.isStatic) return;

        // a = F / m
        const acceleration = Vec2.scale(this.force, this.invMass);

        // Semi-implicit Euler integration
        this.velocity.add(Vec2.scale(acceleration, dt));
        this.position.add(Vec2.scale(this.velocity, dt));

        // Clear force accumulator
        this.force.x = 0;
        this.force.y = 0;
      }
    }

    class PhysicsWorld {
      constructor({ gravity = new Vec2(0, 500), width = 800, height = 600 } = {}) {
        this.gravity = gravity;
        this.bodies = [];
        this.width = width;
        this.height = height;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        // Apply gravity
        for (const body of this.bodies) {
          if (!body.isStatic) {
            body.applyForce(new Vec2(
              this.gravity.x * body.mass,
              this.gravity.y * body.mass
            ));
          }
        }

        // Integrate motion
        for (const body of this.bodies) {
          body.integrate(dt);
        }

        // Resolve collisions with bounds
        for (const body of this.bodies) {
          this.resolveBoundaryCollision(body);
        }

        // Resolve body-body collisions
        for (let i = 0; i < this.bodies.length; i++) {
          for (let j = i + 1; j < this.bodies.length; j++) {
            this.resolveCircleCollision(this.bodies[i], this.bodies[j]);
          }
        }
      }

      resolveBoundaryCollision(body) {
        if (body.isStatic) return;

        // Left
        if (body.position.x - body.radius < 0) {
          body.position.x = body.radius;
          body.velocity.x *= -body.restitution;
        }

        // Right
        if (body.position.x + body.radius > this.width) {
          body.position.x = this.width - body.radius;
          body.velocity.x *= -body.restitution;
        }

        // Top
        if (body.position.y - body.radius < 0) {
          body.position.y = body.radius;
          body.velocity.y *= -body.restitution;
        }

        // Bottom
        if (body.position.y + body.radius > this.height) {
          body.position.y = this.height - body.radius;
          body.velocity.y *= -body.restitution;

          // Simple friction on floor contact
          body.velocity.x *= 0.98;
        }
      }

      resolveCircleCollision(a, b) {
        if (a.isStatic && b.isStatic) return;

        const normal = Vec2.sub(b.position, a.position);
        const distSq = normal.x * normal.x + normal.y * normal.y;
        const radiusSum = a.radius + b.radius;

        if (distSq >= radiusSum * radiusSum) return;

        const dist = Math.sqrt(distSq) || 0.0001;
        normal.scale(1 / dist);

        // Positional correction
        const penetration = radiusSum - dist;
        const totalInvMass = a.invMass + b.invMass;
        if (totalInvMass === 0) return;

        const correction = penetration / totalInvMass;
        if (!a.isStatic) {
          a.position.add(Vec2.scale(normal, -correction * a.invMass));
        }
        if (!b.isStatic) {
          b.position.add(Vec2.scale(normal, correction * b.invMass));
        }

        // Relative velocity
        const rv = Vec2.sub(b.velocity, a.velocity);
        const velAlongNormal = rv.x * normal.x + rv.y * normal.y;

        // Do not resolve if separating
        if (velAlongNormal > 0) return;

        const restitution = Math.min(a.restitution, b.restitution);

        // Impulse scalar
        const j = -(1 + restitution) * velAlongNormal / totalInvMass;

        const impulse = Vec2.scale(normal, j);

        if (!a.isStatic) {
          a.velocity.add(Vec2.scale(impulse, -a.invMass));
        }
        if (!b.isStatic) {
          b.velocity.add(Vec2.scale(impulse, b.invMass));
        }
      }
    }

    class Renderer {
      constructor(canvas, world) {
        this.canvas = canvas;
        this.ctx = canvas.getContext("2d");
        this.world = world;
        this.resize();
        window.addEventListener("resize", () => this.resize());
      }

      resize() {
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
        this.world.width = this.canvas.width;
        this.world.height = this.canvas.height;
      }

      render() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        for (const body of this.world.bodies) {
          ctx.beginPath();
          ctx.arc(body.position.x, body.position.y, body.radius, 0, Math.PI * 2);
          ctx.fillStyle = body.color;
          ctx.fill();
        }
      }
    }

    class GameLoop {
      constructor(update, render, targetFPS = 60, maxSubSteps = 5) {
        this.update = update;
        this.render = render;
        this.targetFPS = targetFPS;
        this.fixedDt = 1 / targetFPS;
        this.maxSubSteps = maxSubSteps;
        this.accumulator = 0;
        this.lastTime = 0;
        this.running = false;
      }

      start() {
        this.running = true;
        requestAnimationFrame((t) => this.loop(t));
      }

      stop() {
        this.running = false;
      }

      loop(timestamp) {
        if (!this.running) return;

        if (!this.lastTime) this.lastTime = timestamp;
        let frameTime = (timestamp - this.lastTime) / 1000;
        this.lastTime = timestamp;

        // Prevent spiral of death on tab-switch / lag spike
        frameTime = Math.min(frameTime, 0.25);

        this.accumulator += frameTime;

        let subSteps = 0;
        while (this.accumulator >= this.fixedDt && subSteps < this.maxSubSteps) {
          this.update(this.fixedDt);
          this.accumulator -= this.fixedDt;
          subSteps++;
        }

        this.render();

        requestAnimationFrame((t) => this.loop(t));
      }
    }

    // Setup
    const canvas = document.getElementById("canvas");
    const world = new PhysicsWorld({
      gravity: new Vec2(0, 980)
    });

    const renderer = new Renderer(canvas, world);

    // Create some bodies
    for (let i = 0; i < 10; i++) {
      world.addBody(new RigidBody({
        position: new Vec2(100 + i * 50, 50 + i * 10),
        velocity: new Vec2((Math.random() - 0.5) * 100, 0),
        mass: 1 + Math.random() * 2,
        radius: 15 + Math.random() * 15,
        restitution: 0.6 + Math.random() * 0.3,
        color: `hsl(${Math.random() * 360}, 70%, 60%)`
      }));
    }

    // Optional: click to spawn new body
    canvas.addEventListener("click", (e) => {
      world.addBody(new RigidBody({
        position: new Vec2(e.clientX, e.clientY),
        velocity: new Vec2((Math.random() - 0.5) * 200, -200),
        mass: 1,
        radius: 10 + Math.random() * 20,
        restitution: 0.8,
        color: `hsl(${Math.random() * 360}, 70%, 60%)`
      }));
    });

    const loop = new GameLoop(
      (dt) => world.step(dt),
      () => renderer.render(),
      60,   // target physics FPS
      8     // max substeps per rendered frame
    );

    loop.start();
  </script>
</body>
</html>
```

---

## Key Design Notes

### 1. Fixed timestep for physics
Physics is updated using a fixed timestep:

```js
this.fixedDt = 1 / targetFPS;
```

This avoids instability caused by variable frame times.

### 2. Accumulator pattern
The loop accumulates elapsed time and runs multiple physics steps if needed:

```js
this.accumulator += frameTime;
while (this.accumulator >= this.fixedDt && subSteps < this.maxSubSteps) {
  this.update(this.fixedDt);
  this.accumulator -= this.fixedDt;
  subSteps++;
}
```

This keeps simulation timing consistent even if rendering fluctuates.

### 3. Frame-rate constraints
To prevent performance collapse:
- `frameTime` is clamped to `0.25`
- `maxSubSteps` limits how many physics updates happen per render frame

This helps avoid the “spiral of death”.

### 4. Semi-implicit Euler integration
This is more stable than explicit Euler for many real-time simulations:

```js
velocity += acceleration * dt
position += velocity * dt
```

### 5. Collision handling
This initial version supports:
- circle-boundary collisions
- circle-circle impulse collisions

It does not yet include:
- angular momentum
- rotational inertia
- contact manifolds
- continuous collision detection

