## Single-file example

Save as `index.html` and open in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Rigid Body Physics Simulation</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1a1a1a;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>

  <script>
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      clone() {
        return new Vec2(this.x, this.y);
      }

      set(x, y) {
        this.x = x;
        this.y = y;
        return this;
      }

      add(v) {
        this.x += v.x;
        this.y += v.y;
        return this;
      }

      sub(v) {
        this.x -= v.x;
        this.y -= v.y;
        return this;
      }

      scale(s) {
        this.x *= s;
        this.y *= s;
        return this;
      }

      length() {
        return Math.hypot(this.x, this.y);
      }

      normalize() {
        const len = this.length();
        if (len > 1e-8) {
          this.x /= len;
          this.y /= len;
        }
        return this;
      }

      static add(a, b) {
        return new Vec2(a.x + b.x, a.y + b.y);
      }

      static sub(a, b) {
        return new Vec2(a.x - b.x, a.y - b.y);
      }

      static scale(v, s) {
        return new Vec2(v.x * s, v.y * s);
      }

      static dot(a, b) {
        return a.x * b.x + a.y * b.y;
      }

      static cross(a, b) {
        return a.x * b.y - a.y * b.x;
      }

      // scalar x vector => vector
      static crossSV(s, v) {
        return new Vec2(-s * v.y, s * v.x);
      }

      // vector x scalar => vector
      static crossVS(v, s) {
        return new Vec2(s * v.y, -s * v.x);
      }
    }

    class RigidBody {
      constructor({
        position = new Vec2(),
        velocity = new Vec2(),
        angle = 0,
        angularVelocity = 0,
        radius = 20,
        mass = 1,
        restitution = 0.5,
        isStatic = false,
        color = "#4fc3f7"
      } = {}) {
        this.position = position;
        this.velocity = velocity;
        this.angle = angle;
        this.angularVelocity = angularVelocity;
        this.force = new Vec2();
        this.torque = 0;

        this.radius = radius;
        this.restitution = restitution;
        this.isStatic = isStatic;
        this.color = color;

        if (isStatic || mass <= 0) {
          this.mass = Infinity;
          this.invMass = 0;
          this.inertia = Infinity;
          this.invInertia = 0;
        } else {
          this.mass = mass;
          this.invMass = 1 / mass;
          // Solid disk inertia in 2D
          this.inertia = 0.5 * mass * radius * radius;
          this.invInertia = 1 / this.inertia;
        }
      }

      applyForce(force) {
        if (this.invMass === 0) return;
        this.force.add(force);
      }

      applyImpulse(impulse, contactVector) {
        if (this.invMass === 0) return;

        this.velocity.add(Vec2.scale(impulse, this.invMass));
        this.angularVelocity += Vec2.cross(contactVector, impulse) * this.invInertia;
      }

      integrateForces(dt, gravity) {
        if (this.invMass === 0) return;

        // Semi-implicit Euler
        this.velocity.x += (gravity.x + this.force.x * this.invMass) * dt;
        this.velocity.y += (gravity.y + this.force.y * this.invMass) * dt;
        this.angularVelocity += this.torque * this.invInertia * dt;
      }

      integrateVelocity(dt) {
        if (this.invMass === 0) return;

        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;
      }

      clearAccumulators() {
        this.force.set(0, 0);
        this.torque = 0;
      }
    }

    class Contact {
      constructor(a, b, normal, penetration, contactPoint) {
        this.a = a;
        this.b = b;
        this.normal = normal;
        this.penetration = penetration;
        this.contactPoint = contactPoint;
      }
    }

    class PhysicsWorld {
      constructor(gravity = new Vec2(0, 500)) {
        this.gravity = gravity;
        this.bodies = [];
        this.iterations = 8;
      }

      addBody(body) {
        this.bodies.push(body);
        return body;
      }

      step(dt) {
        // Integrate forces
        for (const body of this.bodies) {
          body.integrateForces(dt, this.gravity);
        }

        // Detect collisions
        const contacts = this.detectCollisions();

        // Resolve collisions iteratively
        for (let i = 0; i < this.iterations; i++) {
          for (const contact of contacts) {
            this.resolveCollision(contact);
          }
        }

        // Integrate velocities
        for (const body of this.bodies) {
          body.integrateVelocity(dt);
        }

        // Positional correction
        for (const contact of contacts) {
          this.positionalCorrection(contact);
        }

        // Clear forces
        for (const body of this.bodies) {
          body.clearAccumulators();
        }
      }

      detectCollisions() {
        const contacts = [];

        for (let i = 0; i < this.bodies.length; i++) {
          for (let j = i + 1; j < this.bodies.length; j++) {
            const a = this.bodies[i];
            const b = this.bodies[j];

            if (a.invMass === 0 && b.invMass === 0) continue;

            const contact = this.circleVsCircle(a, b);
            if (contact) contacts.push(contact);
          }
        }

        return contacts;
      }

      circleVsCircle(a, b) {
        const delta = Vec2.sub(b.position, a.position);
        const distSq = delta.x * delta.x + delta.y * delta.y;
        const radiusSum = a.radius + b.radius;

        if (distSq >= radiusSum * radiusSum) return null;

        const dist = Math.sqrt(distSq);

        let normal;
        if (dist > 1e-8) {
          normal = Vec2.scale(delta, 1 / dist);
        } else {
          normal = new Vec2(1, 0);
        }

        const penetration = radiusSum - dist;
        const contactPoint = Vec2.add(a.position, Vec2.scale(normal, a.radius - penetration * 0.5));

        return new Contact(a, b, normal, penetration, contactPoint);
      }

      resolveCollision(contact) {
        const { a, b, normal, contactPoint } = contact;

        const ra = Vec2.sub(contactPoint, a.position);
        const rb = Vec2.sub(contactPoint, b.position);

        const velA = Vec2.add(a.velocity, Vec2.crossSV(a.angularVelocity, ra));
        const velB = Vec2.add(b.velocity, Vec2.crossSV(b.angularVelocity, rb));
        const relativeVelocity = Vec2.sub(velB, velA);

        const velAlongNormal = Vec2.dot(relativeVelocity, normal);

        // Do not resolve if separating
        if (velAlongNormal > 0) return;

        const restitution = Math.min(a.restitution, b.restitution);

        const raCrossN = Vec2.cross(ra, normal);
        const rbCrossN = Vec2.cross(rb, normal);

        const invMassSum =
          a.invMass +
          b.invMass +
          (raCrossN * raCrossN) * a.invInertia +
          (rbCrossN * rbCrossN) * b.invInertia;

        if (invMassSum === 0) return;

        const j = -(1 + restitution) * velAlongNormal / invMassSum;
        const impulse = Vec2.scale(normal, j);

        a.applyImpulse(Vec2.scale(impulse, -1), ra);
        b.applyImpulse(impulse, rb);
      }

      positionalCorrection(contact) {
        const { a, b, normal, penetration } = contact;

        const percent = 0.8; // correction strength
        const slop = 0.01;   // penetration allowance

        const invMassSum = a.invMass + b.invMass;
        if (invMassSum === 0) return;

        const correctionMagnitude = Math.max(penetration - slop, 0) / invMassSum * percent;
        const correction = Vec2.scale(normal, correctionMagnitude);

        if (a.invMass > 0) {
          a.position.sub(Vec2.scale(correction, a.invMass));
        }
        if (b.invMass > 0) {
          b.position.add(Vec2.scale(correction, b.invMass));
        }
      }
    }

    class Renderer {
      constructor(canvas, world) {
        this.canvas = canvas;
        this.ctx = canvas.getContext("2d");
        this.world = world;
        this.resize();
        window.addEventListener("resize", () => this.resize());
      }

      resize() {
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
      }

      render() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        for (const body of this.world.bodies) {
          ctx.save();
          ctx.translate(body.position.x, body.position.y);
          ctx.rotate(body.angle);

          ctx.beginPath();
          ctx.arc(0, 0, body.radius, 0, Math.PI * 2);
          ctx.fillStyle = body.color;
          ctx.fill();
          ctx.strokeStyle = "#ffffff22";
          ctx.stroke();

          // Orientation line
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.lineTo(body.radius, 0);
          ctx.strokeStyle = "#fff";
          ctx.stroke();

          ctx.restore();
        }
      }
    }

    // Setup
    const canvas = document.getElementById("canvas");
    const world = new PhysicsWorld(new Vec2(0, 800));
    const renderer = new Renderer(canvas, world);

    // Walls as large static circles are awkward, so we'll do simple boundary constraints separately
    function createScene() {
      world.addBody(new RigidBody({
        position: new Vec2(300, 100),
        velocity: new Vec2(80, 20),
        angularVelocity: 1.5,
        radius: 30,
        mass: 2,
        restitution: 0.8,
        color: "#ff6b6b"
      }));

      world.addBody(new RigidBody({
        position: new Vec2(420, 120),
        velocity: new Vec2(-50, 10),
        angularVelocity: -1.2,
        radius: 25,
        mass: 1.5,
        restitution: 0.7,
        color: "#ffd166"
      }));

      world.addBody(new RigidBody({
        position: new Vec2(550, 80),
        velocity: new Vec2(-20, 0),
        angularVelocity: 0.8,
        radius: 40,
        mass: 3,
        restitution: 0.6,
        color: "#06d6a0"
      }));
    }

    function solveBoundaryCollisions() {
      const width = canvas.width;
      const height = canvas.height;

      for (const body of world.bodies) {
        if (body.invMass === 0) continue;

        const r = body.radius;
        const e = body.restitution;

        if (body.position.x - r < 0) {
          body.position.x = r;
          body.velocity.x *= -e;
        } else if (body.position.x + r > width) {
          body.position.x = width - r;
          body.velocity.x *= -e;
        }

        if (body.position.y - r < 0) {
          body.position.y = r;
          body.velocity.y *= -e;
        } else if (body.position.y + r > height) {
          body.position.y = height - r;
          body.velocity.y *= -e;

          // simple angular response from floor friction-ish effect
          body.angularVelocity += body.velocity.x * 0.01;
          body.velocity.x *= 0.98;
        }
      }
    }

    createScene();

    // Fixed timestep loop with frame-rate constraints
    const fixedDt = 1 / 60;
    const maxFrameTime = 0.25; // clamp large pauses
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      if (frameTime > maxFrameTime) {
        frameTime = maxFrameTime;
      }

      accumulator += frameTime;

      while (accumulator >= fixedDt) {
        world.step(fixedDt);
        solveBoundaryCollisions();
        accumulator -= fixedDt;
      }

      renderer.render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);

    // Click to spawn new bodies
    canvas.addEventListener("click", (e) => {
      const radius = 15 + Math.random() * 25;
      const mass = radius * 0.05;
      world.addBody(new RigidBody({
        position: new Vec2(e.clientX, e.clientY),
        velocity: new Vec2((Math.random() - 0.5) * 300, (Math.random() - 0.5) * 100),
        angularVelocity: (Math.random() - 0.5) * 8,
        radius,
        mass,
        restitution: 0.7,
        color: `hsl(${Math.random() * 360}, 80%, 60%)`
      }));
    });
  </script>
</body>
</html>
