```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}

    Vec3 operator+(const Vec3& other) const {
        return Vec3(x + other.x, y + other.y, z + other.z);
    }

    Vec3 operator-(const Vec3& other) const {
        return Vec3(x - other.x, y - other.y, z - other.z);
    }

    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    Vec3 operator/(float s) const {
        return Vec3(x / s, y / s, z / s);
    }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float length() const {
        return std::sqrt(dot(*this));
    }

    Vec3 normalized() const {
        float len = length();
        if (len == 0) return Vec3();
        return *this / len;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 acceleration;

    Vec3 rotation;         // Euler angles for simplicity
    Vec3 angularVelocity;
    Vec3 torque;

    float mass;
    float invMass;
    float restitution;
    bool isStatic;

    RigidBody(Vec3 pos, float m, bool isStatic = false)
        : position(pos), velocity(), acceleration(),
          rotation(), angularVelocity(), torque(),
          mass(m), restitution(0.5f), isStatic(isStatic)
    {
        invMass = (isStatic || m <= 0.0f) ? 0.0f : 1.0f / m;
    }

    void applyForce(const Vec3& force) {
        if (!isStatic) {
            acceleration += force * invMass;
        }
    }

    void applyTorque(const Vec3& t) {
        if (!isStatic) {
            torque += t;
        }
    }

    void integrate(float dt) {
        if (isStatic) return;

        velocity += acceleration * dt;
        position += velocity * dt;

        angularVelocity += torque * dt; // Simplified inertia handling
        rotation += angularVelocity * dt;

        acceleration = Vec3();
        torque = Vec3();
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;

    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void step(float dt) {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }

            body.integrate(dt);
            handleGroundCollision(body);
        }
    }

    void handleGroundCollision(RigidBody& body) {
        const float groundY = 0.0f;

        if (body.position.y < groundY) {
            body.position.y = groundY;
            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec3(0, 10, 0), 1.0f);
    world.bodies.emplace_back(Vec3(2, 15, 0), 2.0f);

    const float fixedTimeStep = 1.0f / 60.0f;
    const int targetFPS = 60;
    const auto frameDuration = std::chrono::milliseconds(1000 / targetFPS);

    auto previousTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    bool running = true;
    int frameCount = 0;

    while (running && frameCount < 600) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        accumulator += elapsed.count();

        while (accumulator >= fixedTimeStep) {
            world.step(fixedTimeStep);
            accumulator -= fixedTimeStep;
        }

        // Render/debug output
        std::cout << "Frame " << frameCount << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ") "
                      << "Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }
        std::cout << "----------------------\n";

        auto frameEnd = std::chrono::high_resolution_clock::now();
        auto workTime = std::chrono::duration_cast<std::chrono::milliseconds>(frameEnd - currentTime);

        if (workTime < frameDuration) {
            std::this_thread::sleep_for(frameDuration - workTime);
        }

        frameCount++;
    }

    return 0;
}
```

