```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>

constexpr float PI = 3.14159265359f;

// -----------------------------
// Basic Math Types
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& rhs) {
        x += rhs.x; y += rhs.y; z += rhs.z;
        return *this;
    }

    Vec3& operator-=(const Vec3& rhs) {
        x -= rhs.x; y -= rhs.y; z -= rhs.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float dot(const Vec3& rhs) const {
        return x * rhs.x + y * rhs.y + z * rhs.z;
    }

    Vec3 cross(const Vec3& rhs) const {
        return Vec3(
            y * rhs.z - z * rhs.y,
            z * rhs.x - x * rhs.z,
            x * rhs.y - y * rhs.x
        );
    }

    float length() const {
        return std::sqrt(x*x + y*y + z*z);
    }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3();
        return *this / len;
    }
};

struct Quaternion {
    float w, x, y, z;

    Quaternion() : w(1), x(0), y(0), z(0) {}
    Quaternion(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quaternion operator+(const Quaternion& rhs) const {
        return Quaternion(w + rhs.w, x + rhs.x, y + rhs.y, z + rhs.z);
    }

    Quaternion operator*(float s) const {
        return Quaternion(w * s, x * s, y * s, z * s);
    }

    Quaternion operator*(const Quaternion& rhs) const {
        return Quaternion(
            w*rhs.w - x*rhs.x - y*rhs.y - z*rhs.z,
            w*rhs.x + x*rhs.w + y*rhs.z - z*rhs.y,
            w*rhs.y - x*rhs.z + y*rhs.w + z*rhs.x,
            w*rhs.z + x*rhs.y - y*rhs.x + z*rhs.w
        );
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-6f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    static Quaternion fromAngularVelocity(const Vec3& omega) {
        return Quaternion(0.0f, omega.x, omega.y, omega.z);
    }
};

// -----------------------------
// Simple 3x3 Matrix
// -----------------------------
struct Mat3 {
    float m[3][3];

    Mat3() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                m[i][j] = 0.0f;
    }

    static Mat3 identity() {
        Mat3 r;
        r.m[0][0] = r.m[1][1] = r.m[2][2] = 1.0f;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }
};

// -----------------------------
// Rigid Body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    Quaternion orientation;
    Vec3 angularVelocity;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    Mat3 inertiaBody;
    Mat3 invInertiaBody;

    float restitution;
    float radius; // sphere collision approximation

    bool isStatic;

    RigidBody()
        : position(), velocity(), forceAccum(),
          orientation(), angularVelocity(), torqueAccum(),
          mass(1.0f), invMass(1.0f),
          inertiaBody(Mat3::identity()),
          invInertiaBody(Mat3::identity()),
          restitution(0.5f), radius(0.5f),
          isStatic(false)
    {}

    void setMass(float m) {
        mass = m;
        invMass = (m > 1e-6f) ? 1.0f / m : 0.0f;
    }

    void setSphereInertia(float r) {
        radius = r;
        if (isStatic || mass <= 1e-6f) {
            inertiaBody = Mat3();
            invInertiaBody = Mat3();
            return;
        }

        float i = 2.0f / 5.0f * mass * r * r;
        inertiaBody = Mat3();
        invInertiaBody = Mat3();

        inertiaBody.m[0][0] = inertiaBody.m[1][1] = inertiaBody.m[2][2] = i;
        invInertiaBody.m[0][0] = invInertiaBody.m[1][1] = invInertiaBody.m[2][2] = 1.0f / i;
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyTorque(const Vec3& torque) {
        if (isStatic) return;
        torqueAccum += torque;
    }

    void clearAccumulators() {
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }

    void integrate(float dt, const Vec3& gravity) {
        if (isStatic) return;

        // Linear
        Vec3 acceleration = gravity + forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        // Angular (simplified: body inertia treated as constant in world space)
        Vec3 angularAcceleration = invInertiaBody * torqueAccum;
        angularVelocity += angularAcceleration * dt;

        Quaternion omega = Quaternion::fromAngularVelocity(angularVelocity);
        Quaternion dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

// -----------------------------
// Physics World
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;

    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void step(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt, gravity);
            resolveGroundCollision(body);
        }
    }

private:
    void resolveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        float groundY = 0.0f;
        float minY = body.position.y - body.radius;

        if (minY < groundY) {
            body.position.y = groundY + body.radius;

            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;
            }

            // Simple damping to reduce endless jitter
            if (std::fabs(body.velocity.y) < 0.05f) {
                body.velocity.y = 0.0f;
            }
        }
    }
};

// -----------------------------
// Real-Time Simulation Loop
// -----------------------------
int main() {
    PhysicsWorld world;

    RigidBody body;
    body.position = Vec3(0.0f, 10.0f, 0.0f);
    body.velocity = Vec3(2.0f, 0.0f, 0.0f);
    body.setMass(2.0f);
    body.setSphereInertia(0.5f);
    body.restitution = 0.7f;

    world.bodies.push_back(body);

    const float fixedDt = 1.0f / 120.0f;   // physics at 120 Hz
    const float targetFrameTime = 1.0f / 60.0f; // render/update at 60 FPS

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();
    float accumulator = 0.0f;

    bool running = true;
    int frameCount = 0;
    const int maxFrames = 600; // run for ~10 seconds at 60 FPS

    while (running) {
        auto currentTime = clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = elapsed.count();

        // Prevent spiral of death after pauses
        if (frameTime > 0.25f) {
            frameTime = 0.25f;
        }

        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Output body state
        const RigidBody& b = world.bodies[0];
        std::cout << "Frame " << frameCount
                  << " | Pos: (" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                  << " | Vel: (" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                  << std::endl;

        // Frame-rate limiting
        auto frameEndTime = clock::now();
        std::chrono::duration<float> workTime = frameEndTime - currentTime;
        float sleepTime = targetFrameTime - workTime.count();

        if (sleepTime > 0.0f) {
            std::this_thread::sleep_for(std::chrono::duration<float>(sleepTime));
        }

        frameCount++;
        if (frameCount >= maxFrames) {
            running = false;
        }
    }

    return 0;
}
