  <script>
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }

      add(v) { return new Vec2(this.x + v.x, this.y + v.y); }
      sub(v) { return new Vec2(this.x - v.x, this.y - v.y); }
      scale(s) { return new Vec2(this.x * s, this.y * s); }
      dot(v) { return this.x * v.x + this.y * v.y; }
      length() { return Math.sqrt(this.x * this.x + this.y * this.y); }

      normalize() {
        const len = this.length();
        return len > 0 ? this.scale(1 / len) : new Vec2();
      }
    }

    class RigidBody {
      constructor({
        position = new Vec2(),
        velocity = new Vec2(),
        angle = 0,
        angularVelocity = 0,
        mass = 1,
        width = 40,
        height = 40,
        restitution = 0.4
      } = {}) {
        this.position = position;
        this.velocity = velocity;
        this.angle = angle;
        this.angularVelocity = angularVelocity;
        this.force = new Vec2();
        this.torque = 0;

        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        this.width = width;
        this.height = height;
        this.restitution = restitution;

        this.inertia = mass > 0
          ? (mass * (width * width + height * height)) / 12
          : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;
      }

      applyForce(force) {
        this.force = this.force.add(force);
      }

      applyTorque(torque) {
        this.torque += torque;
      }

      integrate(dt) {
        if (this.invMass === 0) return;

        const acceleration = this.force.scale(this.invMass);
        this.velocity = this.velocity.add(acceleration.scale(dt));
        this.position = this.position.add(this.velocity.scale(dt));

        const angularAcceleration = this.torque * this.invInertia;
        this.angularVelocity += angularAcceleration * dt;
        this.angle += this.angularVelocity * dt;

        this.force = new Vec2();
        this.torque = 0;
      }

      getAABB() {
        return {
          minX: this.position.x - this.width / 2,
          maxX: this.position.x + this.width / 2,
          minY: this.position.y - this.height / 2,
          maxY: this.position.y + this.height / 2
        };
      }
    }

    class PhysicsWorld {
      constructor(gravity = new Vec2(0, 500)) {
        this.gravity = gravity;
        this.bodies = [];
        this.groundY = 550;
      }

      addBody(body) {
        this.bodies.push(body);
      }

      step(dt) {
        for (const body of this.bodies) {
          if (body.invMass === 0) continue;

          body.applyForce(this.gravity.scale(body.mass));
          body.integrate(dt);
          this.solveGroundCollision(body);
        }
      }

      solveGroundCollision(body) {
        const halfH = body.height / 2;
        const bottom = body.position.y + halfH;

        if (bottom > this.groundY) {
          body.position.y = this.groundY - halfH;

          if (body.velocity.y > 0) {
            body.velocity.y *= -body.restitution;
            body.velocity.x *= 0.98;
            body.angularVelocity *= 0.98;
          }

          if (Math.abs(body.velocity.y) < 5) {
            body.velocity.y = 0;
          }
        }
      }
    }

    class Renderer {
      constructor(canvas, world) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.world = world;
        this.resize();
        window.addEventListener('resize', () => this.resize());
      }

      resize() {
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
      }

      render(alpha = 1) {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        ctx.strokeStyle = '#888';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, this.world.groundY);
        ctx.lineTo(this.canvas.width, this.world.groundY);
        ctx.stroke();

        for (const body of this.world.bodies) {
          ctx.save();
          ctx.translate(body.position.x, body.position.y);
          ctx.rotate(body.angle);

          ctx.fillStyle = '#4fc3f7';
          ctx.fillRect(
            -body.width / 2,
            -body.height / 2,
            body.width,
            body.height
          );

          ctx.strokeStyle = '#ffffff';
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.lineTo(body.width / 2, 0);
          ctx.stroke();

          ctx.restore();
        }
      }
    }

    class GameLoop {
      constructor(update, render, targetFPS = 60) {
        this.update = update;
        this.render = render;
        this.targetFPS = targetFPS;
        this.fixedDt = 1 / targetFPS;
        this.accumulator = 0;
        this.lastTime = 0;
        this.maxFrameTime = 0.25;
      }

      start() {
        requestAnimationFrame(this.loop.bind(this));
      }

      loop(timestamp) {
        const time = timestamp / 1000;
        let frameTime = time - this.lastTime;
        if (!this.lastTime) frameTime = this.fixedDt;
        this.lastTime = time;

        if (frameTime > this.maxFrameTime) {
          frameTime = this.maxFrameTime;
        }

        this.accumulator += frameTime;

        while (this.accumulator >= this.fixedDt) {
          this.update(this.fixedDt);
          this.accumulator -= this.fixedDt;
        }

        const alpha = this.accumulator / this.fixedDt;
        this.render(alpha);

        requestAnimationFrame(this.loop.bind(this));
      }
    }

    const canvas = document.getElementById('canvas');
    const world = new PhysicsWorld(new Vec2(0, 980));
    const renderer = new Renderer(canvas, world);

    world.addBody(new RigidBody({
