      angularVelocity: -2.0,
      mass: 1,
      width: 50,
      height: 50,
      restitution: 0.3
    }));

    const loop = new GameLoop(
      (dt) => world.step(dt),
      (alpha) => renderer.render(alpha),
      60
    );

    loop.start();
