```cpp
#include <cmath>
#include <vector>
#include <iostream>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr double EPSILON = 1e-8;

// -----------------------------
// Vec3
// -----------------------------
struct Vec3 {
    double x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(double s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(double s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    Vec3& operator-=(const Vec3& rhs) { x -= rhs.x; y -= rhs.y; z -= rhs.z; return *this; }
    Vec3& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }

    double dot(const Vec3& rhs) const {
        return x * rhs.x + y * rhs.y + z * rhs.z;
    }

    Vec3 cross(const Vec3& rhs) const {
        return Vec3(
            y * rhs.z - z * rhs.y,
            z * rhs.x - x * rhs.z,
            x * rhs.y - y * rhs.x
        );
    }

    double length() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    double lengthSquared() const {
        return x * x + y * y + z * z;
    }

    Vec3 normalized() const {
        double len = length();
        if (len < EPSILON) return Vec3();
        return *this / len;
    }
};

inline Vec3 operator*(double s, const Vec3& v) {
    return v * s;
}

// -----------------------------
// Quaternion
// -----------------------------
struct Quat {
    double w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(double w_, double x_, double y_, double z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator+(const Quat& rhs) const {
        return Quat(w + rhs.w, x + rhs.x, y + rhs.y, z + rhs.z);
    }

    Quat operator*(double s) const {
        return Quat(w * s, x * s, y * s, z * s);
    }

    Quat operator*(const Quat& rhs) const {
        return Quat(
            w * rhs.w - x * rhs.x - y * rhs.y - z * rhs.z,
            w * rhs.x + x * rhs.w + y * rhs.z - z * rhs.y,
            w * rhs.y - x * rhs.z + y * rhs.w + z * rhs.x,
            w * rhs.z + x * rhs.y - y * rhs.x + z * rhs.w
        );
    }

    void normalize() {
        double len = std::sqrt(w * w + x * x + y * y + z * z);
        if (len < EPSILON) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len;
        x /= len;
        y /= len;
        z /= len;
    }

    static Quat fromAngularVelocity(const Vec3& omega) {
        return Quat(0.0, omega.x, omega.y, omega.z);
    }
};

// -----------------------------
// 3x3 Matrix (minimal)
// -----------------------------
struct Mat3 {
    double m[3][3];

    Mat3() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                m[i][j] = 0.0;
    }

    static Mat3 identity() {
        Mat3 r;
        r.m[0][0] = r.m[1][1] = r.m[2][2] = 1.0;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0] * v.x + m[0][1] * v.y + m[0][2] * v.z,
            m[1][0] * v.x + m[1][1] * v.y + m[1][2] * v.z,
            m[2][0] * v.x + m[2][1] * v.y + m[2][2] * v.z
        );
    }

    Mat3 operator*(const Mat3& rhs) const {
        Mat3 r;
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                for (int k = 0; k < 3; ++k) {
                    r.m[i][j] += m[i][k] * rhs.m[k][j];
                }
            }
        }
        return r;
    }

    Mat3 transpose() const {
        Mat3 r;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                r.m[i][j] = m[j][i];
        return r;
    }
};

Mat3 quatToMat3(const Quat& q) {
    Mat3 r;
    double ww = q.w * q.w;
    double xx = q.x * q.x;
    double yy = q.y * q.y;
    double zz = q.z * q.z;

    double wx = q.w * q.x;
    double wy = q.w * q.y;
    double wz = q.w * q.z;
    double xy = q.x * q.y;
    double xz = q.x * q.z;
    double yz = q.y * q.z;

    r.m[0][0] = ww + xx - yy - zz;
    r.m[0][1] = 2.0 * (xy - wz);
    r.m[0][2] = 2.0 * (xz + wy);

    r.m[1][0] = 2.0 * (xy + wz);
    r.m[1][1] = ww - xx + yy - zz;
    r.m[1][2] = 2.0 * (yz - wx);

    r.m[2][0] = 2.0 * (xz - wy);
    r.m[2][1] = 2.0 * (yz + wx);
    r.m[2][2] = ww - xx - yy + zz;

    return r;
}

// -----------------------------
// RigidBody
// -----------------------------
struct RigidBody {
    Vec3 position;
    Quat orientation;

    Vec3 linearVelocity;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    double mass;
    double invMass;

    Mat3 localInertia;
    Mat3 localInvInertia;

    double restitution = 0.4;
    double linearDamping = 0.999;
    double angularDamping = 0.998;

    // Simple collision shape: sphere
    double radius = 0.5;

    bool isStatic = false;

    RigidBody(double m, double r, const Vec3& pos)
        : position(pos), mass(m), radius(r)
    {
        orientation = Quat();
        linearVelocity = Vec3();
        angularVelocity = Vec3();
        forceAccum = Vec3();
        torqueAccum = Vec3();

        if (m <= 0.0) {
            isStatic = true;
            mass = 0.0;
            invMass = 0.0;
            localInertia = Mat3::identity();
            localInvInertia = Mat3();
        } else {
            invMass = 1.0 / mass;

            // Solid sphere inertia tensor: I = 2/5 m r^2
            double I = 0.4 * mass * radius * radius;
            localInertia = Mat3();
            localInertia.m[0][0] = I;
            localInertia.m[1][1] = I;
            localInertia.m[2][2] = I;

            localInvInertia = Mat3();
            localInvInertia.m[0][0] = 1.0 / I;
            localInvInertia.m[1][1] = 1.0 / I;
            localInvInertia.m[2][2] = 1.0 / I;
        }
    }

    Mat3 worldInvInertia() const {
        Mat3 R = quatToMat3(orientation);
        return R * localInvInertia * R.transpose();
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& worldPoint) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = worldPoint - position;
        torqueAccum += r.cross(force);
    }

    void applyImpulse(const Vec3& impulse, const Vec3& contactVector) {
        if (isStatic) return;
        linearVelocity += impulse * invMass;
        angularVelocity += worldInvInertia() * contactVector.cross(impulse);
    }

    void clearAccumulators() {
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }

    void integrate(double dt, const Vec3& gravity) {
        if (isStatic) return;

        // Linear
        Vec3 acceleration = gravity + forceAccum * invMass;
        linearVelocity += acceleration * dt;
        linearVelocity *= std::pow(linearDamping, dt * 60.0);
        position += linearVelocity * dt;

        // Angular
        Vec3 angularAcceleration = worldInvInertia() * torqueAccum;
        angularVelocity += angularAcceleration * dt;
        angularVelocity *= std::pow(angularDamping, dt * 60.0);

        Quat omega = Quat::fromAngularVelocity(angularVelocity);
        Quat dq = omega * orientation;
        orientation = orientation + dq * (0.5 * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

// -----------------------------
// PhysicsWorld
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0, -9.81, 0.0);

    void step(double dt) {
        // Integrate forces and velocities
        for (auto& body : bodies) {
            body.integrate(dt, gravity);
        }

        // Resolve collisions after integration
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }
    }

private:
    void resolveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        // Ground plane y = 0
        double penetration = body.radius - body.position.y;
        if (penetration <= 0.0) return;

        Vec3 normal(0.0, 1.0, 0.0);

        // Positional correction
        body.position.y += penetration;

        // Contact point on sphere bottom
        Vec3 contactPoint = body.position - Vec3(0.0, body.radius, 0.0);
        Vec3 r = contactPoint - body.position;

        // Velocity at contact
        Vec3 contactVelocity = body.linearVelocity + body.angularVelocity.cross(r);
        double separatingVelocity = contactVelocity.dot(normal);

        if (separatingVelocity < 0.0) {
            double e = body.restitution;

            Vec3 rnCrossN = r.cross(normal);
            Vec3 angularTerm = body.worldInvInertia() * rnCrossN;
            double denom = body.invMass + normal.dot(angularTerm.cross(r));

            if (denom > EPSILON) {
                double j = -(1.0 + e) * separatingVelocity / denom;
                Vec3 impulse = normal * j;
                body.applyImpulse(impulse, r);
            }
        }

        // Simple friction approximation
        contactVelocity = body.linearVelocity + body.angularVelocity.cross(r);
        Vec3 tangent = contactVelocity - normal * contactVelocity.dot(normal);
        double tangentLen = tangent.length();

        if (tangentLen > EPSILON) {
            tangent = tangent / tangentLen;

            double jt = -contactVelocity.dot(tangent);
            Vec3 rtCrossT = r.cross(tangent);
            Vec3 angularTermT = body.worldInvInertia() * rtCrossT;
            double denomT = body.invMass + tangent.dot(angularTermT.cross(r));

            if (denomT > EPSILON) {
                jt /= denomT;

                double mu = 0.5; // friction coefficient
                double normalImpulseApprox = body.mass * 9.81;
                jt = std::clamp(jt, -mu * normalImpulseApprox, mu * normalImpulseApprox);

                Vec3 frictionImpulse = tangent * jt;
                body.applyImpulse(frictionImpulse, r);
            }
        }

        // Sleep threshold for tiny bounce jitter
        if (std::abs(body.linearVelocity.y) < 0.05 && body.position.y <= body.radius + 1e-4) {
            body.linearVelocity.y = 0.0;
        }
    }
};

// -----------------------------
// Example main loop with frame-rate constraint
// -----------------------------
int main() {
    PhysicsWorld world;

    // Add a dynamic sphere
    world.bodies.emplace_back(1.0, 0.5, Vec3(0.0, 5.0, 0.0));
    world.bodies.back().linearVelocity = Vec3(1.0, 0.0, 0.0);
    world.bodies.back().angularVelocity = Vec3(0.0, 0.0, 2.0);

    const double fixedDt = 1.0 / 60.0;
    const double maxFrameTime = 0.25; // prevent spiral of death
    double accumulator = 0.0;

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto currentTime = clock::now();
        std::chrono::duration<double> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        double frameTime = elapsed.count();
        if (frameTime > maxFrameTime) {
            frameTime = maxFrameTime;
        }

        accumulator += frameTime;

        // Fixed-step physics
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render / output (placeholder)
        const RigidBody& b = world.bodies[0];
        std::cout
            << "Frame " << frameCount
            << " | Pos: (" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
            << " | Vel: (" << b.linearVelocity.x << ", " << b.linearVelocity.y << ", " << b.linearVelocity.z << ")"
            << "\n";

        frameCount++;
        if (frameCount > 300) {
            running = false;
        }

        // Frame-rate constraint (~60 FPS render loop)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
```

