## Minimal Working Example

Save as `index.html` and open in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Rigid Body Physics</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1e1e1e;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>
  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }
      add(v) { return new Vec2(this.x + v.x, this.y + v.y); }
      sub(v) { return new Vec2(this.x - v.x, this.y - v.y); }
      scale(s) { return new Vec2(this.x * s, this.y * s); }
      dot(v) { return this.x * v.x + this.y * v.y; }
      length() { return Math.hypot(this.x, this.y); }
      normalize() {
        const len = this.length();
        return len > 0 ? this.scale(1 / len) : new Vec2();
      }
    }

    class RigidBody {
      constructor(x, y, radius, mass = 1) {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2((Math.random() - 0.5) * 100, (Math.random() - 0.5) * 100);
        this.angle = 0;
        this.angularVelocity = (Math.random() - 0.5) * 4;
        this.radius = radius;
        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;
        this.inertia = 0.5 * mass * radius * radius;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;
        this.restitution = 0.8;
        this.color = `hsl(${Math.random() * 360}, 70%, 60%)`;
      }

      integrate(dt, gravity) {
        this.velocity.y += gravity * dt;
        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;
      }

      draw(ctx) {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);

        ctx.beginPath();
        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.strokeStyle = "#fff";
        ctx.stroke();

        // orientation marker
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(this.radius, 0);
        ctx.strokeStyle = "#fff";
        ctx.stroke();

        ctx.restore();
      }
    }

    const bodies = [];
    const gravity = 500;
    const floorY = () => canvas.height - 50;

    for (let i = 0; i < 8; i++) {
      bodies.push(
        new RigidBody(
          100 + i * 70,
          100 + Math.random() * 100,
          20 + Math.random() * 10,
          1 + Math.random() * 2
        )
      );
    }

    function resolveFloorCollision(body) {
      const bottom = body.position.y + body.radius;
      if (bottom > floorY()) {
        body.position.y = floorY() - body.radius;
        if (body.velocity.y > 0) {
          body.velocity.y *= -body.restitution;
          body.velocity.x *= 0.98; // simple friction
          body.angularVelocity *= 0.98;
        }
      }
    }

    function resolveCircleCollision(a, b) {
      const delta = b.position.sub(a.position);
      const dist = delta.length();
      const minDist = a.radius + b.radius;

      if (dist === 0 || dist >= minDist) return;

      const normal = delta.scale(1 / dist);
      const penetration = minDist - dist;

      // positional correction
      const totalInvMass = a.invMass + b.invMass;
      if (totalInvMass === 0) return;

      const correction = normal.scale(penetration / totalInvMass * 0.8);
      a.position = a.position.sub(correction.scale(a.invMass));
      b.position = b.position.add(correction.scale(b.invMass));

      // relative velocity
      const rv = b.velocity.sub(a.velocity);
      const velAlongNormal = rv.dot(normal);

      if (velAlongNormal > 0) return;

      const e = Math.min(a.restitution, b.restitution);
      const j = -(1 + e) * velAlongNormal / totalInvMass;
      const impulse = normal.scale(j);

      a.velocity = a.velocity.sub(impulse.scale(a.invMass));
      b.velocity = b.velocity.add(impulse.scale(b.invMass));

      // crude angular response
      const tangent = new Vec2(-normal.y, normal.x);
      const tangentVel = rv.dot(tangent);
      const spinImpulse = tangentVel * 0.01;
      a.angularVelocity -= spinImpulse;
      b.angularVelocity += spinImpulse;
    }

    function step(dt) {
      for (const body of bodies) {
        body.integrate(dt, gravity);
      }

      for (let i = 0; i < bodies.length; i++) {
        resolveFloorCollision(bodies[i]);
        for (let j = i + 1; j < bodies.length; j++) {
          resolveCircleCollision(bodies[i], bodies[j]);
        }
      }
    }

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // floor
      ctx.beginPath();
      ctx.moveTo(0, floorY());
      ctx.lineTo(canvas.width, floorY());
      ctx.strokeStyle = "#888";
      ctx.lineWidth = 2;
      ctx.stroke();

      for (const body of bodies) {
        body.draw(ctx);
      }

      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText("Fixed timestep rigid body demo", 20, 30);
    }

    const fixedDt = 1 / 60;
    let accumulator = 0;
    let lastTime = performance.now();

    function loop(currentTime) {
      let frameTime = (currentTime - lastTime) / 1000;
      lastTime = currentTime;

      // frame-rate constraint: avoid spiral of death
      frameTime = Math.min(frameTime, 0.25);
      accumulator += frameTime;

      while (accumulator >= fixedDt) {
        step(fixedDt);
        accumulator -= fixedDt;
      }

      const alpha = accumulator / fixedDt;
      render(alpha);

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

---

## Why this satisfies the request

### Real-time simulation
It updates continuously using `requestAnimationFrame`.

### Rigid body dynamics
Each body has:
- linear position/velocity
- angular position/velocity
- mass and inertia

### Frame-rate constraints
It uses a **fixed timestep**:

```js
const fixedDt = 1 / 60;
```

and an accumulator:

```js
while (accumulator >= fixedDt) {
  step(fixedDt);
  accumulator -= fixedDt;
}
```

This keeps physics stable even if rendering frame time varies.

---

## Important limitation

This is a **minimal** implementation, not a production physics engine. It simplifies rigid body dynamics by:

- using only circles
- approximating angular collision response
- handling only one static boundary (the floor)
- not using full contact manifolds or constraint solvers

