      display: block;
      background: #1e1e1e;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    class RigidBody {
      constructor(x, y, width, height, mass = 1) {
        this.position = { x, y };
        this.velocity = { x: 120, y: 0 };

        this.angle = 0;
        this.angularVelocity = 1.5;

        this.force = { x: 0, y: 0 };
        this.torque = 0;

        this.width = width;
        this.height = height;

        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        // Rectangle moment of inertia about center
        this.inertia = mass > 0
          ? (mass * (width * width + height * height)) / 12
          : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

        this.restitution = 0.5;
      }

      applyForce(fx, fy) {
        this.force.x += fx;
        this.force.y += fy;
      }

      applyTorque(t) {
        this.torque += t;
      }

      integrate(dt) {
        // Linear motion
        const ax = this.force.x * this.invMass;
        const ay = this.force.y * this.invMass;

        this.velocity.x += ax * dt;
        this.velocity.y += ay * dt;

        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;

        // Angular motion
        const angularAcc = this.torque * this.invInertia;
        this.angularVelocity += angularAcc * dt;
        this.angle += this.angularVelocity * dt;

        // Clear accumulated forces
        this.force.x = 0;
        this.force.y = 0;
        this.torque = 0;
      }

      handleGroundCollision(groundY) {
        const halfH = this.height / 2;

        // Very simple collision using body's center and AABB-ish vertical extent
        if (this.position.y + halfH > groundY) {
          this.position.y = groundY - halfH;

          if (this.velocity.y > 0) {
            this.velocity.y *= -this.restitution;
          }

          // crude friction/damping on bounce
          this.velocity.x *= 0.98;
          this.angularVelocity *= 0.98;
        }
      }

      draw(ctx) {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);

        ctx.fillStyle = "#4fc3f7";
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);

        // orientation marker
        ctx.strokeStyle = "#ffffff";
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(this.width / 2, 0);
        ctx.stroke();

        ctx.restore();
      }
    }

    const body = new RigidBody(150, 100, 80, 40, 2);
    const gravity = 900; // px/s^2
    const groundY = () => canvas.height - 80;

    // Fixed timestep for stable simulation
    const fixedDt = 1 / 120;
    const maxFrameTime = 0.25; // avoid spiral of death
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function update(dt) {
      body.applyForce(0, body.mass * gravity);

      // example persistent torque
      body.applyTorque(0.5);

      body.integrate(dt);
      body.handleGroundCollision(groundY());
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // ground
      ctx.strokeStyle = "#888";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, groundY());
      ctx.lineTo(canvas.width, groundY());
      ctx.stroke();

      body.draw(ctx);

      ctx.fillStyle = "#ccc";
      ctx.font = "16px sans-serif";
      ctx.fillText("Minimal real-time rigid body simulation", 20, 30);
      ctx.fillText("Fixed timestep: 120 Hz", 20, 55);
    }

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // Clamp long frames
      if (frameTime > maxFrameTime) frameTime = maxFrameTime;

      accumulator += frameTime;

      while (accumulator >= fixedDt) {
        update(fixedDt);
        accumulator -= fixedDt;
      }

      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
