## Minimal Working Example

Save this as `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Rigid Body Physics</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1e1e1e;
    }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>
  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }
      add(v) { return new Vec2(this.x + v.x, this.y + v.y); }
      sub(v) { return new Vec2(this.x - v.x, this.y - v.y); }
      scale(s) { return new Vec2(this.x * s, this.y * s); }
      dot(v) { return this.x * v.x + this.y * v.y; }
      length() { return Math.hypot(this.x, this.y); }
      normalize() {
        const len = this.length() || 1;
        return new Vec2(this.x / len, this.y / len);
      }
    }

    function cross2D(a, b) {
      return a.x * b.y - a.y * b.x;
    }

    function rotate(v, angle) {
      const c = Math.cos(angle);
      const s = Math.sin(angle);
      return new Vec2(
        v.x * c - v.y * s,
        v.x * s + v.y * c
      );
    }

    class RigidBody {
      constructor(x, y, w, h, mass = 1) {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2(0, 0);
        this.angle = 0;
        this.angularVelocity = 0;

        this.width = w;
        this.height = h;

        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        // Rectangle moment of inertia about center
        this.inertia = mass > 0 ? (mass * (w * w + h * h)) / 12 : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

        this.restitution = 0.4;
        this.friction = 0.8;

        this.color = "#4fc3f7";
      }

      getVertices() {
        const hw = this.width / 2;
        const hh = this.height / 2;
        const local = [
          new Vec2(-hw, -hh),
          new Vec2(hw, -hh),
          new Vec2(hw, hh),
          new Vec2(-hw, hh)
        ];
        return local.map(v => rotate(v, this.angle).add(this.position));
      }

      integrate(dt, gravity) {
        if (this.invMass === 0) return;

        // Linear motion
        this.velocity = this.velocity.add(gravity.scale(dt));
        this.position = this.position.add(this.velocity.scale(dt));

        // Angular motion
        this.angle += this.angularVelocity * dt;
      }

      draw(ctx) {
        const verts = this.getVertices();
        ctx.beginPath();
        ctx.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < verts.length; i++) {
          ctx.lineTo(verts[i].x, verts[i].y);
        }
        ctx.closePath();
        ctx.fillStyle = this.color;
        ctx.fill();

        // Orientation line
        ctx.beginPath();
        ctx.moveTo(this.position.x, this.position.y);
        const dir = rotate(new Vec2(this.width / 2, 0), this.angle);
        ctx.lineTo(this.position.x + dir.x, this.position.y + dir.y);
        ctx.strokeStyle = "#fff";
        ctx.stroke();
      }
    }

    const gravity = new Vec2(0, 1000);
    const floorY = () => canvas.height - 60;

    const bodies = [
      new RigidBody(canvas.width * 0.5, 100, 80, 40, 2),
      new RigidBody(canvas.width * 0.35, 50, 60, 60, 1),
      new RigidBody(canvas.width * 0.65, 150, 120, 30, 3)
    ];

    bodies[0].angularVelocity = 1.5;
    bodies[1].angularVelocity = -2.0;
    bodies[2].angularVelocity = 0.8;

    function solveFloorCollision(body) {
      const verts = body.getVertices();

      let deepestPenetration = 0;
      let contactPoint = null;

      for (const v of verts) {
        const penetration = v.y - floorY();
        if (penetration > deepestPenetration) {
          deepestPenetration = penetration;
          contactPoint = v;
        }
      }

      if (deepestPenetration <= 0 || !contactPoint) return;

      // Positional correction
      body.position.y -= deepestPenetration;

      const normal = new Vec2(0, -1);
      const r = contactPoint.sub(body.position);

      // Velocity at contact point
      const tangentVelFromRotation = new Vec2(
        -body.angularVelocity * r.y,
         body.angularVelocity * r.x
      );
      const contactVelocity = body.velocity.add(tangentVelFromRotation);

      const velAlongNormal = contactVelocity.dot(normal);
      if (velAlongNormal > 0) return;

      const e = body.restitution;

      const rn = cross2D(r, normal);
      const denom = body.invMass + (rn * rn) * body.invInertia;

      const j = -(1 + e) * velAlongNormal / denom;
      const impulse = normal.scale(j);

      body.velocity = body.velocity.add(impulse.scale(body.invMass));
      body.angularVelocity += cross2D(r, impulse) * body.invInertia;

      // Friction
      const tangent = new Vec2(contactVelocity.x, contactVelocity.y)
        .sub(normal.scale(contactVelocity.dot(normal)))
        .normalize();

      const velAlongTangent = contactVelocity.dot(tangent);
      const rt = cross2D(r, tangent);
      const denomT = body.invMass + (rt * rt) * body.invInertia;

      let jt = -velAlongTangent / denomT;
      const mu = body.friction;
      jt = Math.max(-j * mu, Math.min(jt, j * mu));

      const frictionImpulse = tangent.scale(jt);
      body.velocity = body.velocity.add(frictionImpulse.scale(body.invMass));
      body.angularVelocity += cross2D(r, frictionImpulse) * body.invInertia;

      // Damp tiny motion to help resting stability
      if (Math.abs(body.velocity.y) < 5) body.velocity.y = 0;
      if (Math.abs(body.angularVelocity) < 0.05) body.angularVelocity = 0;
    }

    // Fixed timestep for stable simulation
    const fixedDt = 1 / 120;
    const maxFrameTime = 0.25;
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function update(dt) {
      for (const body of bodies) {
        body.integrate(dt, gravity);
        solveFloorCollision(body);
      }
    }

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Floor
      ctx.fillStyle = "#444";
      ctx.fillRect(0, floorY(), canvas.width, canvas.height - floorY());

      for (const body of bodies) {
        body.draw(ctx);
      }

      ctx.fillStyle = "#ccc";
      ctx.font = "14px monospace";
      ctx.fillText("Fixed timestep rigid body demo", 20, 30);
      ctx.fillText("Bodies: " + bodies.length, 20, 50);
    }

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      // Prevent spiral of death
      if (frameTime > maxFrameTime) frameTime = maxFrameTime;

      accumulator += frameTime;

      while (accumulator >= fixedDt) {
        update(fixedDt);
        accumulator -= fixedDt;
      }

      const alpha = accumulator / fixedDt;
      render(alpha);

      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

