        // orientation marker
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(this.radius, 0);
        ctx.strokeStyle = "#ffcc00";
        ctx.stroke();

        ctx.restore();
      }
    }

    const bodies = [];

    function createScene() {
      bodies.length = 0;
      for (let i = 0; i < 8; i++) {
        const radius = 20 + Math.random() * 20;
        const mass = radius;
        bodies.push(
          new RigidBody(
            100 + Math.random() * (canvas.width - 200),
            50 + Math.random() * 200,
            radius,
            mass
          )
        );
      }
    }

    function resolveWallCollision(body) {
      // Left
      if (body.x - body.radius < 0) {
        body.x = body.radius;
        body.vx *= -RESTITUTION;
      }
      // Right
      if (body.x + body.radius > canvas.width) {
        body.x = canvas.width - body.radius;
        body.vx *= -RESTITUTION;
      }
      // Top
      if (body.y - body.radius < 0) {
        body.y = body.radius;
        body.vy *= -RESTITUTION;
      }
      // Bottom
      if (body.y + body.radius > canvas.height) {
        body.y = canvas.height - body.radius;
        body.vy *= -RESTITUTION;
        body.angularVelocity *= 0.98;
      }
    }

    function resolveCircleCollision(a, b) {
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const distSq = dx * dx + dy * dy;
      const minDist = a.radius + b.radius;

      if (distSq >= minDist * minDist) return;

      const dist = Math.sqrt(distSq) || 0.0001;
      const nx = dx / dist;
      const ny = dy / dist;

      // Positional correction
      const penetration = minDist - dist;
      const totalInvMass = a.invMass + b.invMass;
      if (totalInvMass === 0) return;

      const correction = penetration / totalInvMass;
      a.x -= correction * a.invMass * nx;
      a.y -= correction * a.invMass * ny;
      b.x += correction * b.invMass * nx;
      b.y += correction * b.invMass * ny;

      // Relative velocity
      const rvx = b.vx - a.vx;
      const rvy = b.vy - a.vy;
      const velAlongNormal = rvx * nx + rvy * ny;

      if (velAlongNormal > 0) return;

      const e = RESTITUTION;
      const j = -(1 + e) * velAlongNormal / totalInvMass;

      const impulseX = j * nx;
      const impulseY = j * ny;

      a.vx -= impulseX * a.invMass;
      a.vy -= impulseY * a.invMass;
      b.vx += impulseX * b.invMass;
      b.vy += impulseY * b.invMass;

      // Minimal angular response from tangential motion
      const tx = -ny;
      const ty = nx;
      const tangentVel = rvx * tx + rvy * ty;
      const spinImpulse = tangentVel * 0.0005;

      a.angularVelocity -= spinImpulse / (a.invInertia || 1);
      b.angularVelocity += spinImpulse / (b.invInertia || 1);
    }

    function stepPhysics(dt) {
      for (const body of bodies) {
        body.integrate(dt);
        resolveWallCollision(body);
      }

      for (let i = 0; i < bodies.length; i++) {
        for (let j = i + 1; j < bodies.length; j++) {
          resolveCircleCollision(bodies[i], bodies[j]);
        }
      }
    }

    function render(alpha) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (const body of bodies) {
        body.draw(ctx);
      }

      ctx.fillStyle = "#ffffff";
      ctx.font = "16px sans-serif";
      ctx.fillText("Minimal Real-Time Rigid Body Physics", 20, 30);
      ctx.fillText("Bodies: " + bodies.length, 20, 55);
      ctx.fillText("Fixed dt: " + FIXED_DT.toFixed(4), 20, 80);
    }

    createScene();

    let accumulator = 0;
    let lastTime = performance.now();

    function loop(currentTime) {
      let frameTime = (currentTime - lastTime) / 1000;
      lastTime = currentTime;

      if (frameTime > MAX_FRAME_TIME) frameTime = MAX_FRAME_TIME;
      accumulator += frameTime;

      while (accumulator >= FIXED_DT) {
        stepPhysics(FIXED_DT);
        accumulator -= FIXED_DT;
      }

      const alpha = accumulator / FIXED_DT;
      render(alpha);

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);

    window.addEventListener("click", () => {
      createScene();
    });
  </script>
</body>
</html>
```

