    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Vector utilities
    // -----------------------------
    class Vec2 {
      constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
      }
      add(v) { return new Vec2(this.x + v.x, this.y + v.y); }
      sub(v) { return new Vec2(this.x - v.x, this.y - v.y); }
      scale(s) { return new Vec2(this.x * s, this.y * s); }
      dot(v) { return this.x * v.x + this.y * v.y; }
      length() { return Math.hypot(this.x, this.y); }
      normalize() {
        const len = this.length();
        return len > 0 ? this.scale(1 / len) : new Vec2();
      }
    }

    function cross2D(a, b) {
      return a.x * b.y - a.y * b.x;
    }

    function crossScalarVec(s, v) {
      return new Vec2(-s * v.y, s * v.x);
    }

    // -----------------------------
    // Rigid body
    // -----------------------------
    class RigidBody {
      constructor(x, y, w, h, mass = 1) {
        this.position = new Vec2(x, y);
        this.velocity = new Vec2(0, 0);
        this.angle = 0;
        this.angularVelocity = 0;

        this.width = w;
        this.height = h;

        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;

        // Rectangle inertia about center: (1/12) * m * (w^2 + h^2)
        this.inertia = mass > 0 ? (mass * (w * w + h * h)) / 12 : 0;
        this.invInertia = this.inertia > 0 ? 1 / this.inertia : 0;

        this.restitution = 0.4;
        this.color = `hsl(${Math.random() * 360}, 70%, 60%)`;
      }

      applyGravity(g, dt) {
        if (this.invMass === 0) return;
        this.velocity.y += g * dt;
      }

      integrate(dt) {
        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.angle += this.angularVelocity * dt;
      }

      getCorners() {
        const hw = this.width / 2;
        const hh = this.height / 2;
        const c = Math.cos(this.angle);
        const s = Math.sin(this.angle);

        const local = [
          new Vec2(-hw, -hh),
          new Vec2(hw, -hh),
          new Vec2(hw, hh),
          new Vec2(-hw, hh)
        ];

        return local.map(p => new Vec2(
          this.position.x + p.x * c - p.y * s,
          this.position.y + p.x * s + p.y * c
        ));
      }

      draw(ctx) {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);
        ctx.fillStyle = this.color;
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);

        // orientation marker
        ctx.strokeStyle = "#fff";
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(this.width / 2, 0);
        ctx.stroke();

        ctx.restore();
      }
    }

    // -----------------------------
    // World
    // -----------------------------
    const gravity = 900; // pixels/s^2
    const floorY = () => canvas.height - 60;

    const bodies = [
      new RigidBody(300, 100, 80, 40, 2),
      new RigidBody(500, 50, 60, 60, 1),
      new RigidBody(700, 150, 120, 30, 3)
    ];

    bodies[0].angularVelocity = 1.2;
    bodies[1].angularVelocity = -2.0;
    bodies[2].angularVelocity = 0.8;

    // -----------------------------
    // Collision with floor
    // -----------------------------
    function resolveFloorCollision(body) {
      const corners = body.getCorners();
      let deepestPenetration = 0;
      let contactPoint = null;

      for (const corner of corners) {
        const penetration = corner.y - floorY();
        if (penetration > deepestPenetration) {
          deepestPenetration = penetration;
          contactPoint = corner;
        }
      }

      if (!contactPoint) return;

      // Positional correction
      body.position.y -= deepestPenetration;

      const r = contactPoint.sub(body.position);
      const normal = new Vec2(0, -1);

      // Velocity at contact point: v + w x r
      const contactVel = body.velocity.add(crossScalarVec(body.angularVelocity, r));
      const velAlongNormal = contactVel.dot(normal);

      // Only resolve if moving into the floor
      if (velAlongNormal >= 0) return;

      const rn = cross2D(r, normal);
      const invMassSum = body.invMass + (rn * rn) * body.invInertia;

      const j = -(1 + body.restitution) * velAlongNormal / invMassSum;
      const impulse = normal.scale(j);

      body.velocity = body.velocity.add(impulse.scale(body.invMass));
      body.angularVelocity += cross2D(r, impulse) * body.invInertia;

      // Simple damping to reduce endless jitter
      body.velocity.x *= 0.98;
      body.angularVelocity *= 0.98;
    }

    // -----------------------------
    // Fixed timestep loop
    // -----------------------------
    const fixedDt = 1 / 60;
    const maxFrameTime = 0.25; // avoid spiral of death
    let accumulator = 0;
    let lastTime = performance.now() / 1000;

    function update(dt) {
      for (const body of bodies) {
        body.applyGravity(gravity, dt);
        body.integrate(dt);
        resolveFloorCollision(body);
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // floor
      ctx.strokeStyle = "#888";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, floorY());
      ctx.lineTo(canvas.width, floorY());
      ctx.stroke();

      for (const body of bodies) {
        body.draw(ctx);
      }

      ctx.fillStyle = "#ccc";
      ctx.font = "16px sans-serif";
      ctx.fillText("Minimal 2D Rigid Body Physics (fixed timestep)", 20, 30);
    }

    function loop() {
      const now = performance.now() / 1000;
      let frameTime = now - lastTime;
      lastTime = now;

      if (frameTime > maxFrameTime) frameTime = maxFrameTime;
      accumulator += frameTime;

      while (accumulator >= fixedDt) {
        update(fixedDt);
        accumulator -= fixedDt;
      }

      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
