### `service/PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.repo.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.NoSuchElementException;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentProcessorClient processorClient;
    private final PaymentEventPublisher eventPublisher;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentProcessorClient processorClient,
                          PaymentEventPublisher eventPublisher) {
        this.paymentRepository = paymentRepository;
        this.processorClient = processorClient;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public Payment createPayment(String idempotencyKey, CreatePaymentRequest request) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> {
                    Payment payment = new Payment();
                    payment.setIdempotencyKey(idempotencyKey);
                    payment.setDebtorAccount(request.getDebtorAccount());
                    payment.setCreditorAccount(request.getCreditorAccount());
                    payment.setAmount(request.getAmount());
                    payment.setCurrency(request.getCurrency());
                    payment.setStatus(PaymentStatus.PENDING);

                    Payment saved = paymentRepository.save(payment);
                    eventPublisher.publishCreated(saved);
                    return saved;
                });
    }

    @Transactional
    public Payment authorizePayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NoSuchElementException("Payment not found"));

        if (payment.getStatus() != PaymentStatus.PENDING) {
            return payment;
        }

        boolean authorized = processorClient.authorize(payment.getId());
        if (authorized) {
            payment.setStatus(PaymentStatus.AUTHORIZED);
            Payment saved = paymentRepository.save(payment);
            eventPublisher.publishAuthorized(saved);
            return saved;
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            Payment saved = paymentRepository.save(payment);
            eventPublisher.publishFailed(saved, "Authorization declined");
            return saved;
        }
    }

    @Transactional
    public Payment capturePayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NoSuchElementException("Payment not found"));

        if (payment.getStatus() != PaymentStatus.AUTHORIZED) {
            return payment;
        }

        boolean captured = processorClient.capture(payment.getId());
        if (captured) {
            payment.setStatus(PaymentStatus.CAPTURED);
            Payment saved = paymentRepository.save(payment);
            eventPublisher.publishCaptured(saved);
            return saved;
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            Payment saved = paymentRepository.save(payment);
            eventPublisher.publishFailed(saved, "Capture failed");
            return saved;
        }
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NoSuchElementException("Payment not found"));
    }
}
```

