## 8. Core payment service

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.PaymentResponse;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.persistence.entity.PaymentEntity;
import com.example.payments.persistence.repository.PaymentRepository;
import com.example.payments.service.port.LedgerService;
import com.example.payments.service.port.RiskService;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.Map;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final AuditService auditService;

    public PaymentProcessingService(PaymentRepository paymentRepository,
                                    RiskService riskService,
                                    LedgerService ledgerService,
                                    AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        var existing = paymentRepository.findByIdempotencyKey(request.getIdempotencyKey());
        if (existing.isPresent()) {
            return new PaymentResponse(existing.get().getId(), existing.get().getStatus());
        }

        validateBusinessRules(request);

        PaymentEntity payment = new PaymentEntity();
        payment.setDebtorAccountId(request.getDebtorAccountId());
        payment.setCreditorAccountId(request.getCreditorAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setClientReference(request.getClientReference());
        payment.setIdempotencyKey(request.getIdempotencyKey());
        payment.setPaymentPurpose(request.getPaymentPurpose());
        payment.setStatus(PaymentStatus.RECEIVED);

        payment = paymentRepository.save(payment);

        auditService.record("PAYMENT_RECEIVED", payment.getId(), Map.of(
            "debtorAccountId", payment.getDebtorAccountId(),
            "creditorAccountId", payment.getCreditorAccountId(),
            "amount", payment.getAmount(),
            "currency", payment.getCurrency()
        ));

        var riskDecision = riskService.assess(
            payment.getDebtorAccountId(),
            payment.getCreditorAccountId(),
            payment.getAmount(),
            payment.getCurrency(),
            payment.getPaymentPurpose()
        );

        if (!riskDecision.approved()) {
            if (riskDecision.manualReview()) {
                payment.setStatus(PaymentStatus.PENDING_REVIEW);
                paymentRepository.save(payment);
                auditService.record("PAYMENT_PENDING_REVIEW", payment.getId(),
                    Map.of("reason", riskDecision.reason()));
                return new PaymentResponse(payment.getId(), payment.getStatus());
            } else {
                payment.setStatus(PaymentStatus.REJECTED);
                paymentRepository.save(payment);
                auditService.record("PAYMENT_REJECTED", payment.getId(),
                    Map.of("reason", riskDecision.reason()));
                return new PaymentResponse(payment.getId(), payment.getStatus());
            }
        }

        payment.setStatus(PaymentStatus.APPROVED);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_APPROVED", payment.getId(), Map.of());

        try {
            payment.setStatus(PaymentStatus.PROCESSING);
            paymentRepository.save(payment);

            ledgerService.reserveFunds(
                payment.getId(),
                payment.getDebtorAccountId(),
                payment.getAmount(),
                payment.getCurrency()
            );

            ledgerService.postTransfer(
                payment.getId(),
                payment.getDebtorAccountId(),
                payment.getCreditorAccountId(),
                payment.getAmount(),
                payment.getCurrency()
            );

            payment.setStatus(PaymentStatus.SETTLED);
            paymentRepository.save(payment);

            auditService.record("PAYMENT_SETTLED", payment.getId(), Map.of());
            return new PaymentResponse(payment.getId(), payment.getStatus());

        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            paymentRepository.save(payment);

            try {
                ledgerService.releaseFunds(
                    payment.getId(),
                    payment.getDebtorAccountId(),
                    payment.getAmount(),
                    payment.getCurrency()
                );
            } catch (Exception ignored) {
                auditService.record("PAYMENT_COMPENSATION_FAILED", payment.getId(),
                    Map.of("message", ignored.getMessage()));
            }

            auditService.record("PAYMENT_FAILED", payment.getId(),
                Map.of("message", ex.getMessage()));
            return new PaymentResponse(payment.getId(), payment.getStatus());
        }
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccountId().equals(request.getCreditorAccountId())) {
            throw new IllegalArgumentException("Debtor and creditor accounts must differ");
        }

        if (!request.getAmount().stripTrailingZeros().scaleIsZero() && request.getAmount().scale() > 4) {
            throw new IllegalArgumentException("Amount exceeds supported decimal precision");
        }
    }
}
