```java
package com.example.payments.service;

import com.example.payments.exception.PaymentException;
import com.example.payments.gateway.PaymentGatewayClient;
import com.example.payments.model.PaymentEntity;
import com.example.payments.model.PaymentRequest;
import com.example.payments.model.PaymentResponse;
import com.example.payments.model.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentGatewayClient gatewayClient;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentGatewayClient gatewayClient,
                          IdempotencyService idempotencyService,
                          AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.gatewayClient = gatewayClient;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(PaymentRequest request, String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new PaymentException("Missing required Idempotency-Key header");
        }

        UUID existingPaymentId = idempotencyService.findPaymentIdByKey(idempotencyKey).orElse(null);
        if (existingPaymentId != null) {
            PaymentEntity existing = paymentRepository.findById(existingPaymentId)
                    .orElseThrow(() -> new PaymentException("Idempotency record exists but payment not found"));
            return toResponse(existing, "Duplicate request: returning existing payment");
        }

        PaymentEntity payment = new PaymentEntity();
        payment.setId(UUID.randomUUID());
        payment.setCustomerId(request.getCustomerId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setSourceAccountToken(request.getSourceAccountToken());
        payment.setDestinationAccountToken(request.getDestinationAccountToken());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.PENDING);
        payment.setCreatedAt(Instant.now());
        payment.setUpdatedAt(Instant.now());

        payment = paymentRepository.save(payment);
        auditService.recordPaymentCreated(payment);

        try {
            idempotencyService.save(idempotencyKey, payment.getId());
        } catch (DataIntegrityViolationException e) {
            UUID paymentId = idempotencyService.findPaymentIdByKey(idempotencyKey)
                    .orElseThrow(() -> new PaymentException("Unable to resolve idempotent request"));
            PaymentEntity existing = paymentRepository.findById(paymentId)
                    .orElseThrow(() -> new PaymentException("Existing payment not found"));
            return toResponse(existing, "Duplicate request: returning existing payment");
        }

        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.recordPaymentStatusChanged(payment);

        boolean success = gatewayClient.process(payment);

        payment.setStatus(success ? PaymentStatus.COMPLETED : PaymentStatus.FAILED);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.recordPaymentStatusChanged(payment);

        return toResponse(payment, success ? "Payment processed successfully" : "Payment failed");
    }

    public PaymentResponse getPayment(UUID paymentId) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentException("Payment not found"));
        return toResponse(payment, "Payment retrieved");
    }

    private PaymentResponse toResponse(PaymentEntity payment, String message) {
        return new PaymentResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getReference(),
                payment.getCreatedAt(),
                message
        );
    }
}
