## Payment entity

```java
package com.bank.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments", indexes = {
        @Index(name = "idx_payments_idempotency_key", columnList = "idempotencyKey", unique = true),
        @Index(name = "idx_payments_customer_id", columnList = "customerId")
})
public class Payment {

    @Id
    private UUID id;

    @Column(nullable = false, length = 64)
    private String customerId;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentStatus status;

    @Column(nullable = false, length = 128, unique = true)
    private String idempotencyKey;

    @Column(length = 128)
    private String externalReference;

    @Column(nullable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    protected Payment() {}

    public Payment(UUID id,
                   String customerId,
                   BigDecimal amount,
                   String currency,
                   String idempotencyKey) {
        this.id = id;
        this.customerId = customerId;
        this.amount = amount;
        this.currency = currency;
        this.idempotencyKey = idempotencyKey;
        this.status = PaymentStatus.PENDING;
        this.createdAt = Instant.now();
        this.updatedAt = Instant.now();
    }

    public void authorize(String externalReference) {
        if (status != PaymentStatus.PENDING) {
            throw new IllegalStateException("Only pending payments can be authorized");
        }
        this.status = PaymentStatus.AUTHORIZED;
        this.externalReference = externalReference;
        this.updatedAt = Instant.now();
    }

    public void capture() {
        if (status != PaymentStatus.AUTHORIZED) {
            throw new IllegalStateException("Only authorized payments can be captured");
        }
        this.status = PaymentStatus.CAPTURED;
        this.updatedAt = Instant.now();
    }

    public void fail() {
        if (status == PaymentStatus.CAPTURED || status == PaymentStatus.REFUNDED) {
            throw new IllegalStateException("Cannot fail a captured or refunded payment");
        }
        this.status = PaymentStatus.FAILED;
        this.updatedAt = Instant.now();
    }

    public void refundPartialOrFull(BigDecimal refundedAmount) {
        if (status != PaymentStatus.CAPTURED && status != PaymentStatus.PARTIALLY_REFUNDED) {
            throw new IllegalStateException("Only captured or partially refunded payments can be refunded");
        }

        if (refundedAmount.compareTo(amount) == 0) {
            this.status = PaymentStatus.REFUNDED;
        } else if (refundedAmount.compareTo(amount) < 0) {
            this.status = PaymentStatus.PARTIALLY_REFUNDED;
        } else {
            throw new IllegalArgumentException("Refund amount exceeds captured amount");
        }

        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getCustomerId() { return customerId; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public PaymentStatus getStatus() { return status; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public String getExternalReference() { return externalReference; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
```

