## Ledger service

```java
package com.bank.payments.service;

import com.bank.payments.domain.LedgerEntry;
import com.bank.payments.domain.Payment;
import com.bank.payments.repository.LedgerEntryRepository;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.List;
import java.util.UUID;

@Service
public class LedgerService {

    private final LedgerEntryRepository ledgerEntryRepository;

    public LedgerService(LedgerEntryRepository ledgerEntryRepository) {
        this.ledgerEntryRepository = ledgerEntryRepository;
    }

    public void postCaptureEntries(Payment payment) {
        BigDecimal amount = payment.getAmount();

        LedgerEntry receivableDebit = new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                "SETTLEMENT_RECEIVABLE",
                amount,
                BigDecimal.ZERO,
                payment.getCurrency()
        );

        LedgerEntry customerFundsCredit = new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                "CUSTOMER_FUNDS",
                BigDecimal.ZERO,
                amount,
                payment.getCurrency()
        );

        validateBalanced(List.of(receivableDebit, customerFundsCredit));
        ledgerEntryRepository.saveAll(List.of(receivableDebit, customerFundsCredit));
    }

    public void postRefundEntries(Payment payment, BigDecimal refundAmount) {
        LedgerEntry customerFundsDebit = new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                "CUSTOMER_FUNDS",
                refundAmount,
                BigDecimal.ZERO,
                payment.getCurrency()
        );

        LedgerEntry settlementPayableCredit = new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                "SETTLEMENT_PAYABLE",
                BigDecimal.ZERO,
                refundAmount,
                payment.getCurrency()
        );

        validateBalanced(List.of(customerFundsDebit, settlementPayableCredit));
        ledgerEntryRepository.saveAll(List.of(customerFundsDebit, settlementPayableCredit));
    }

    private void validateBalanced(List<LedgerEntry> entries) {
        BigDecimal totalDebits = entries.stream()
                .map(LedgerEntry::getDebit)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal totalCredits = entries.stream()
                .map(LedgerEntry::getCredit)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        if (totalDebits.compareTo(totalCredits) != 0) {
            throw new IllegalStateException("Ledger entries are not balanced");
        }
    }
}
```

