# 10. Payment service

```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.api.dto.PaymentResponse;
import com.bank.payments.domain.Payment;
import com.bank.payments.gateway.GatewayAuthorizationResult;
import com.bank.payments.gateway.PaymentGateway;
import com.bank.payments.outbox.OutboxEvent;
import com.bank.payments.outbox.OutboxEventRepository;
import com.bank.payments.repository.PaymentRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentGateway paymentGateway;
    private final LedgerService ledgerService;
    private final OutboxEventRepository outboxEventRepository;
    private final ObjectMapper objectMapper;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentGateway paymentGateway,
                          LedgerService ledgerService,
                          OutboxEventRepository outboxEventRepository,
                          ObjectMapper objectMapper) {
        this.paymentRepository = paymentRepository;
        this.paymentGateway = paymentGateway;
        this.ledgerService = ledgerService;
        this.outboxEventRepository = outboxEventRepository;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public PaymentResponse createAndCapture(CreatePaymentRequest request, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .map(this::toResponse)
                .orElseGet(() -> createNewPayment(request, idempotencyKey));
    }

    private PaymentResponse createNewPayment(CreatePaymentRequest request, String idempotencyKey) {
        Payment payment = new Payment(
                UUID.randomUUID(),
                request.customerId(),
                request.amount(),
                request.currency(),
                idempotencyKey
        );

        GatewayAuthorizationResult authResult = paymentGateway.authorize(
                request.customerId(),
                request.amount(),
                request.currency()
        );

        if (!authResult.approved()) {
            payment.fail();
            paymentRepository.save(payment);
            enqueueEvent("PaymentFailed", payment);
            return toResponse(payment);
        }

        payment.authorize(authResult.externalReference());
        payment.capture();

        paymentRepository.save(payment);
        ledgerService.postCaptureEntries(payment);
        enqueueEvent("PaymentCaptured", payment);

        return toResponse(payment);
    }

    @Transactional
    public PaymentResponse refund(UUID paymentId, java.math.BigDecimal refundAmount) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));

        payment.refundPartialOrFull(refundAmount);
        paymentRepository.save(payment);
        ledgerService.postRefundEntries(payment, refundAmount);
        enqueueEvent("PaymentRefunded", payment);

        return toResponse(payment);
    }

    private void enqueueEvent(String eventType, Payment payment) {
        try {
            String payload = objectMapper.writeValueAsString(toResponse(payment));
            outboxEventRepository.save(new OutboxEvent(
                    UUID.randomUUID(),
                    "Payment",
                    payment.getId().toString(),
                    eventType,
                    payload
            ));
        } catch (Exception e) {
            throw new RuntimeException("Failed to serialize outbox event", e);
        }
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getCustomerId(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getStatus(),
                payment.getExternalReference()
        );
    }
}
