```java
package com.example.payments.service.impl;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.entity.Account;
import com.example.payments.entity.IdempotencyRecord;
import com.example.payments.entity.Payment;
import com.example.payments.exception.ConflictException;
import com.example.payments.exception.InsufficientFundsException;
import com.example.payments.exception.NotFoundException;
import com.example.payments.repository.AccountRepository;
import com.example.payments.repository.IdempotencyRecordRepository;
import com.example.payments.repository.PaymentRepository;
import com.example.payments.service.AuditService;
import com.example.payments.service.LedgerService;
import com.example.payments.service.PaymentService;
import com.example.payments.service.RiskService;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Optional;

@Service
public class PaymentServiceImpl implements PaymentService {

    private final PaymentRepository paymentRepository;
    private final AccountRepository accountRepository;
    private final IdempotencyRecordRepository idempotencyRepository;
    private final LedgerService ledgerService;
    private final AuditService auditService;
    private final RiskService riskService;
    private final ObjectMapper objectMapper;

    public PaymentServiceImpl(
            PaymentRepository paymentRepository,
            AccountRepository accountRepository,
            IdempotencyRecordRepository idempotencyRepository,
            LedgerService ledgerService,
            AuditService auditService,
            RiskService riskService,
            ObjectMapper objectMapper
    ) {
        this.paymentRepository = paymentRepository;
        this.accountRepository = accountRepository;
        this.idempotencyRepository = idempotencyRepository;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
        this.riskService = riskService;
        this.objectMapper = objectMapper;
    }

    @Override
    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        String requestHash = hashRequest(request);

        Optional<IdempotencyRecord> existing = idempotencyRepository.findById(idempotencyKey);
        if (existing.isPresent()) {
            IdempotencyRecord record = existing.get();
            if (!record.getRequestHash().equals(requestHash)) {
                throw new ConflictException("Idempotency key reused with different request payload");
            }
            try {
                return objectMapper.readValue(record.getResponsePayload(), PaymentResponse.class);
            } catch (JsonProcessingException e) {
                throw new RuntimeException("Failed to deserialize stored idempotent response", e);
            }
        }

        validateBusinessRules(request);
        riskService.evaluate(request);

        Account source = accountRepository.findById(request.getSourceAccountId())
                .orElseThrow(() -> new NotFoundException("Source account not found"));

        Account destination = accountRepository.findById(request.getDestinationAccountId())
                .orElseThrow(() -> new NotFoundException("Destination account not found"));

        if (!source.getCurrency().equals(request.getCurrency()) ||
            !destination.getCurrency().equals(request.getCurrency())) {
            throw new ConflictException("Currency mismatch");
        }

        if (source.getAvailableBalance().compareTo(request.getAmount()) < 0) {
            throw new InsufficientFundsException("Insufficient funds");
        }

        source.setAvailableBalance(source.getAvailableBalance().subtract(request.getAmount()));
        destination.setAvailableBalance(destination.getAvailableBalance().add(request.getAmount()));

        accountRepository.save(source);
        accountRepository.save(destination);

        Payment payment = new Payment();
        payment.setSourceAccountId(request.getSourceAccountId());
        payment.setDestinationAccountId(request.getDestinationAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setStatus("COMPLETED");

        paymentRepository.save(payment);
        ledgerService.postEntries(payment);

        PaymentResponse response = new PaymentResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getSourceAccountId(),
                payment.getDestinationAccountId(),
                payment.getReference(),
                payment.getCreatedAt()
        );

        IdempotencyRecord record = new IdempotencyRecord();
        record.setIdempotencyKey(idempotencyKey);
        record.setRequestHash(requestHash);
        record.setPaymentId(payment.getId());
        record.setStatus(payment.getStatus());
        record.setResponsePayload(writeJson(response));
        idempotencyRepository.save(record);

        auditService.record("PAYMENT_CREATED", "paymentId=" + payment.getId());

        return response;
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getSourceAccountId().equals(request.getDestinationAccountId())) {
            throw new ConflictException("Source and destination accounts must differ");
        }
        if (request.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new ConflictException("Amount must be greater than zero");
        }
        if (request.getCurrency().length() != 3) {
            throw new ConflictException("Currency must be ISO-4217 alpha-3");
        }
    }

    private String hashRequest(CreatePaymentRequest request) {
        try {
            String canonical = request.getSourceAccountId() + "|" +
                    request.getDestinationAccountId() + "|" +
                    request.getAmount().toPlainString() + "|" +
                    request.getCurrency() + "|" +
                    request.getReference();

            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));

            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unable to hash request", e);
        }
    }

    private String writeJson(PaymentResponse response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to serialize payment response", e);
        }
    }
}
