# 8. Payment service

## PaymentService.java

```java
package com.bank.payments.application;

import com.bank.payments.api.CreatePaymentRequest;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.outbox.OutboxEvent;
import com.bank.payments.outbox.OutboxRepository;
import com.bank.payments.persistence.PaymentRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Map;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentProcessor paymentProcessor;
    private final AuditService auditService;
    private final OutboxRepository outboxRepository;
    private final ObjectMapper objectMapper;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentProcessor paymentProcessor,
                          AuditService auditService,
                          OutboxRepository outboxRepository,
                          ObjectMapper objectMapper) {
        this.paymentRepository = paymentRepository;
        this.paymentProcessor = paymentProcessor;
        this.auditService = auditService;
        this.outboxRepository = outboxRepository;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> createAndProcessPayment(request, idempotencyKey));
    }

    private Payment createAndProcessPayment(CreatePaymentRequest request, String idempotencyKey) {
        validateBusinessRules(request);

        Payment payment = new Payment();
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDebtorAccountId(request.getDebtorAccountId());
        payment.setCreditorAccountId(request.getCreditorAccountId());
        payment.setPaymentType(request.getPaymentType());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setStatus(PaymentStatus.RECEIVED);

        payment = paymentRepository.save(payment);
        auditService.record(payment.getId(), "PAYMENT_RECEIVED", Map.of("status", payment.getStatus().name()));

        payment.setStatus(PaymentStatus.VALIDATED);
        payment = paymentRepository.save(payment);
        auditService.record(payment.getId(), "PAYMENT_VALIDATED", Map.of("status", payment.getStatus().name()));

        payment.setStatus(PaymentStatus.PROCESSING);
        payment = paymentRepository.save(payment);

        ProcessingResult result = paymentProcessor.process(payment);
        if (result.success()) {
            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setExternalReference(result.externalReference());
            auditService.record(payment.getId(), "PAYMENT_COMPLETED",
                    Map.of("externalReference", result.externalReference()));
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(result.failureReason());
            auditService.record(payment.getId(), "PAYMENT_FAILED",
                    Map.of("reason", result.failureReason()));
        }

        payment = paymentRepository.save(payment);
        enqueueEvent(payment);
        return payment;
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccountId().equals(request.getCreditorAccountId())) {
            throw new IllegalArgumentException("Debtor and creditor accounts must differ");
        }
    }

    private void enqueueEvent(Payment payment) {
        try {
            String payload = objectMapper.writeValueAsString(Map.of(
                    "paymentId", payment.getId(),
                    "status", payment.getStatus(),
                    "amount", payment.getAmount(),
                    "currency", payment.getCurrency(),
                    "externalReference", payment.getExternalReference()
            ));

            OutboxEvent event = new OutboxEvent();
            event.setAggregateId(payment.getId());
            event.setEventType("PaymentStatusChanged");
            event.setPayload(payload);
            outboxRepository.save(event);
        } catch (Exception e) {
            throw new RuntimeException("Failed to serialize outbox event", e);
        }
    }
}
```

