# 8. Payment service

## `PaymentService.java`

```java
package com.bank.payments.service;

import com.bank.payments.api.CreatePaymentRequest;
import com.bank.payments.api.PaymentResponse;
import com.bank.payments.domain.*;
import com.bank.payments.repository.LedgerEntryRepository;
import com.bank.payments.repository.OutboxEventRepository;
import com.bank.payments.repository.PaymentRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerEntryRepository ledgerEntryRepository;
    private final OutboxEventRepository outboxEventRepository;
    private final RiskService riskService;
    private final AccountService accountService;
    private final ObjectMapper objectMapper;

    public PaymentService(PaymentRepository paymentRepository,
                          LedgerEntryRepository ledgerEntryRepository,
                          OutboxEventRepository outboxEventRepository,
                          RiskService riskService,
                          AccountService accountService,
                          ObjectMapper objectMapper) {
        this.paymentRepository = paymentRepository;
        this.ledgerEntryRepository = ledgerEntryRepository;
        this.outboxEventRepository = outboxEventRepository;
        this.riskService = riskService;
        this.accountService = accountService;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        var existing = paymentRepository.findByIdempotencyKey(request.idempotencyKey());
        if (existing.isPresent()) {
            return toResponse(existing.get());
        }

        validateBusinessRules(request);

        var now = Instant.now();
        var payment = new PaymentEntity(
                UUID.randomUUID(),
                request.idempotencyKey(),
                request.debtorAccountId(),
                request.creditorAccountId(),
                request.amount(),
                request.currency(),
                request.reference(),
                PaymentStatus.RECEIVED,
                now,
                now
        );

        var riskDecision = riskService.assess(request);
        if ("PENDING_REVIEW".equals(riskDecision.decision())) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
            paymentRepository.save(payment);
            saveOutbox(payment, "PaymentPendingReview");
            return toResponse(payment);
        }

        payment.setStatus(PaymentStatus.AUTHORIZED);
        paymentRepository.save(payment);

        ledgerEntryRepository.save(new LedgerEntryEntity(
                UUID.randomUUID(),
                payment.getId(),
                payment.getDebtorAccountId(),
                "DEBIT",
                payment.getAmount(),
                payment.getCurrency(),
                now
        ));

        ledgerEntryRepository.save(new LedgerEntryEntity(
                UUID.randomUUID(),
                payment.getId(),
                payment.getCreditorAccountId(),
                "CREDIT",
                payment.getAmount(),
                payment.getCurrency(),
                now
        ));

        payment.setStatus(PaymentStatus.POSTED);
        paymentRepository.save(payment);

        saveOutbox(payment, "PaymentPosted");
        return toResponse(payment);
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (!accountService.accountExists(request.debtorAccountId())) {
            throw new IllegalArgumentException("Debtor account not found");
        }
        if (!accountService.accountExists(request.creditorAccountId())) {
            throw new IllegalArgumentException("Creditor account not found");
        }
        if (request.debtorAccountId().equals(request.creditorAccountId())) {
            throw new IllegalArgumentException("Debtor and creditor accounts must differ");
        }
        if (!accountService.hasSufficientFunds(request.debtorAccountId(), request.amount())) {
            throw new IllegalArgumentException("Insufficient funds");
        }
        if (request.currency().length() != 3) {
            throw new IllegalArgumentException("Currency must be ISO-4217 alpha-3");
        }
    }

    private void saveOutbox(PaymentEntity payment, String eventType) {
        try {
            var payload = objectMapper.writeValueAsString(toResponse(payment));
            outboxEventRepository.save(new OutboxEventEntity(
                    UUID.randomUUID(),
                    "PAYMENT",
                    payment.getId(),
                    eventType,
                    payload,
                    Instant.now(),
                    false
            ));
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to serialize outbox payload", e);
        }
    }

    private PaymentResponse toResponse(PaymentEntity entity) {
        return new PaymentResponse(
                entity.getId(),
                entity.getStatus().name(),
                entity.getDebtorAccountId(),
                entity.getCreditorAccountId(),
                entity.getAmount(),
                entity.getCurrency(),
                entity.getReference(),
                entity.getCreatedAt()
        );
    }
}
```

