```java
package com.bank.payments.messaging;

import com.bank.payments.repository.OutboxEventRepository;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
public class OutboxPublisher {

    private final OutboxEventRepository outboxEventRepository;
    private final KafkaTemplate<String, String> kafkaTemplate;

    public OutboxPublisher(OutboxEventRepository outboxEventRepository,
                           KafkaTemplate<String, String> kafkaTemplate) {
        this.outboxEventRepository = outboxEventRepository;
        this.kafkaTemplate = kafkaTemplate;
    }

    @Scheduled(fixedDelay = 1000)
    @Transactional
    public void publishPendingEvents() {
        var events = outboxEventRepository.findTop100ByPublishedFalseOrderByCreatedAtAsc();
        for (var event : events) {
            kafkaTemplate.send("payments.events", event.getAggregateId().toString(), event.getPayload());
            event.setPublished(true);
            outboxEventRepository.save(event);
        }
    }
}
