package com.example.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments", indexes = {
        @Index(name = "idx_payment_client_ref", columnList = "clientReference", unique = true)
})
public class Payment {

    @Id
    private UUID id;

    @Column(nullable = false, updatable = false)
    private String clientReference;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentStatus status;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private long version;

    protected Payment() {}

    public Payment(UUID id, String clientReference, BigDecimal amount, String currency, PaymentStatus status) {
        this.id = id;
        this.clientReference = clientReference;
        this.amount = amount;
        this.currency = currency;
        this.status = status;
        this.createdAt = Instant.now();
        this.updatedAt = this.createdAt;
    }

    public void markApproved() {
        this.status = PaymentStatus.APPROVED;
        this.updatedAt = Instant.now();
    }

    public void markRejected() {
        this.status = PaymentStatus.REJECTED;
        this.updatedAt = Instant.now();
    }

    public void markPosted() {
        this.status = PaymentStatus.POSTED;
        this.updatedAt = Instant.now();
    }

    public void markFailed() {
        this.status = PaymentStatus.FAILED;
        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getClientReference() { return clientReference; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public PaymentStatus getStatus() { return status; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
```

