## `LedgerService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.AccountType;
import com.example.payments.domain.LedgerEntry;
import com.example.payments.domain.Payment;
import com.example.payments.repo.LedgerEntryRepository;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.List;
import java.util.UUID;

@Service
public class LedgerService {

    private final LedgerEntryRepository ledgerEntryRepository;

    public LedgerService(LedgerEntryRepository ledgerEntryRepository) {
        this.ledgerEntryRepository = ledgerEntryRepository;
    }

    public void postPayment(Payment payment) {
        BigDecimal amount = payment.getAmount();

        LedgerEntry debit = new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                AccountType.INTERNAL_SETTLEMENT,
                amount,
                BigDecimal.ZERO,
                payment.getCurrency()
        );

        LedgerEntry credit = new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                AccountType.CUSTOMER_CASH,
                BigDecimal.ZERO,
                amount,
                payment.getCurrency()
        );

        validateBalanced(List.of(debit, credit));

        ledgerEntryRepository.save(debit);
        ledgerEntryRepository.save(credit);
    }

    private void validateBalanced(List<LedgerEntry> entries) {
        BigDecimal totalDebits = entries.stream()
                .map(LedgerEntry::getDebit)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal totalCredits = entries.stream()
                .map(LedgerEntry::getCredit)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        if (totalDebits.compareTo(totalCredits) != 0) {
            throw new IllegalStateException("Ledger entries are not balanced");
        }
    }
}
```

