## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.repo.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final LedgerService ledgerService;
    private final AuditService auditService;
    private final EventOutboxService eventOutboxService;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     IdempotencyService idempotencyService,
                                     LedgerService ledgerService,
                                     AuditService auditService,
                                     EventOutboxService eventOutboxService) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
        this.eventOutboxService = eventOutboxService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        var existingPaymentId = idempotencyService.findPaymentId(idempotencyKey);
        if (existingPaymentId.isPresent()) {
            return paymentRepository.findById(existingPaymentId.get())
                    .orElseThrow(() -> new IllegalStateException("Idempotency record exists but payment not found"));
        }

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getClientReference(),
                request.getAmount(),
                request.getCurrency(),
                PaymentStatus.PENDING_APPROVAL
        );

        paymentRepository.save(payment);
        idempotencyService.save(idempotencyKey, payment.getId());
        auditService.record("PAYMENT_CREATED", "paymentId=" + payment.getId());
        eventOutboxService.publishPaymentCreated(payment.getId().toString());

        // Placeholder approval logic
        payment.markApproved();

        ledgerService.postPayment(payment);
        payment.markPosted();

        auditService.record("PAYMENT_POSTED", "paymentId=" + payment.getId());
        eventOutboxService.publishPaymentPosted(payment.getId().toString());

        return paymentRepository.save(payment);
    }
}
```

