package com.example.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments",
       indexes = {
           @Index(name = "idx_payment_client_payment_ref", columnList = "clientPaymentReference"),
           @Index(name = "idx_payment_status", columnList = "status")
       })
public class Payment {

    @Id
    @Column(nullable = false, updatable = false)
    private UUID id;

    @Column(nullable = false, length = 64)
    private String clientId;

    @Column(nullable = false, length = 128)
    private String clientPaymentReference;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentType type;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(nullable = false, length = 64)
    private String debtorAccount;

    @Column(nullable = false, length = 64)
    private String creditorAccount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentStatus status;

    @Column(length = 256)
    private String statusReason;

    @Column(nullable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private long version;

    public Payment() {
    }

    public static Payment create(
            String clientId,
            String clientPaymentReference,
            PaymentType type,
            BigDecimal amount,
            String currency,
            String debtorAccount,
            String creditorAccount
    ) {
        Payment p = new Payment();
        p.id = UUID.randomUUID();
        p.clientId = clientId;
        p.clientPaymentReference = clientPaymentReference;
        p.type = type;
        p.amount = amount;
        p.currency = currency;
        p.debtorAccount = debtorAccount;
        p.creditorAccount = creditorAccount;
        p.status = PaymentStatus.PENDING;
        p.createdAt = Instant.now();
        p.updatedAt = p.createdAt;
        return p;
    }

    public void approve() {
        this.status = PaymentStatus.APPROVED;
        this.statusReason = "Approved";
        this.updatedAt = Instant.now();
    }

    public void reject(String reason) {
        this.status = PaymentStatus.REJECTED;
        this.statusReason = reason;
        this.updatedAt = Instant.now();
    }

    public void fail(String reason) {
        this.status = PaymentStatus.FAILED;
        this.statusReason = reason;
        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getClientId() { return clientId; }
    public String getClientPaymentReference() { return clientPaymentReference; }
    public PaymentType getType() { return type; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public String getDebtorAccount() { return debtorAccount; }
    public String getCreditorAccount() { return creditorAccount; }
    public PaymentStatus getStatus() { return status; }
    public String getStatusReason() { return statusReason; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
```

