        if (payment.getAmount().doubleValue() > 1_000_000) {
            return RiskDecision.reject("Amount exceeds automatic approval threshold");
        }
        if (payment.getDebtorAccount().equals(payment.getCreditorAccount())) {
            return RiskDecision.reject("Debtor and creditor accounts must differ");
        }
        return RiskDecision.approve();
    }

    public record RiskDecision(boolean approved, String reason) {
