# Core application service

## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.IdempotencyRecord;
import com.example.payments.domain.Payment;
import com.example.payments.repo.IdempotencyRecordRepository;
import com.example.payments.repo.PaymentRepository;
import jakarta.persistence.EntityNotFoundException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRecordRepository idempotencyRecordRepository;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final AuditService auditService;
    private final EventPublisher eventPublisher;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            IdempotencyRecordRepository idempotencyRecordRepository,
            RiskService riskService,
            LedgerService ledgerService,
            AuditService auditService,
            EventPublisher eventPublisher
    ) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRecordRepository = idempotencyRecordRepository;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String clientId, String actor, String idempotencyKey) {
        var existing = idempotencyRecordRepository.findByClientIdAndIdempotencyKey(clientId, idempotencyKey);
        if (existing.isPresent()) {
            return paymentRepository.findById(existing.get().getPaymentId())
                    .orElseThrow(() -> new IllegalStateException("Idempotency record exists but payment not found"));
        }

        Payment payment = Payment.create(
                clientId,
                request.getClientPaymentReference(),
                request.getType(),
                request.getAmount(),
                request.getCurrency(),
                request.getDebtorAccount(),
                request.getCreditorAccount()
        );

        paymentRepository.save(payment);
        auditService.paymentCreated(payment, actor);

        var riskDecision = riskService.assess(payment);
        if (!riskDecision.approved()) {
            payment.reject(riskDecision.reason());
            paymentRepository.save(payment);
            auditService.paymentStatusChanged(payment, actor);
        } else {
            ledgerService.reserveFunds(payment);
            payment.approve();
            paymentRepository.save(payment);
            auditService.paymentStatusChanged(payment, actor);
        }

        try {
            idempotencyRecordRepository.save(IdempotencyRecord.of(clientId, idempotencyKey, payment.getId()));
        } catch (DataIntegrityViolationException e) {
            var concurrent = idempotencyRecordRepository.findByClientIdAndIdempotencyKey(clientId, idempotencyKey)
                    .orElseThrow(() -> e);
            return paymentRepository.findById(concurrent.getPaymentId())
                    .orElseThrow(() -> new IllegalStateException("Concurrent idempotent payment missing"));
        }

        eventPublisher.publishPaymentCreated(payment);
        return payment;
    }

    @Transactional(readOnly = true)
    public Payment getPayment(UUID paymentId, String clientId) {
        return paymentRepository.findByIdAndClientId(paymentId, clientId)
                .orElseThrow(() -> new EntityNotFoundException("Payment not found"));
    }
}
```

