```java
package com.example.payments.api;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.PaymentResponse;
import com.example.payments.security.RequestContext;
import com.example.payments.service.PaymentApplicationService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
@Validated
public class PaymentController {

    private final PaymentApplicationService paymentApplicationService;
    private final RequestContext requestContext;

    public PaymentController(PaymentApplicationService paymentApplicationService, RequestContext requestContext) {
        this.paymentApplicationService = paymentApplicationService;
        this.requestContext = requestContext;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PaymentResponse createPayment(
            @Valid @RequestBody CreatePaymentRequest request,
            @RequestHeader("Idempotency-Key") @NotBlank String idempotencyKey
    ) {
        String clientId = requestContext.getClientId();
        String actor = requestContext.getActor();

        return PaymentResponse.from(
                paymentApplicationService.createPayment(request, clientId, actor, idempotencyKey)
        );
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable UUID paymentId) {
        String clientId = requestContext.getClientId();
        return PaymentResponse.from(paymentApplicationService.getPayment(paymentId, clientId));
    }
}
