## 5. Service Implementation

```java
package com.bank.payments.service.impl;

import com.bank.payments.api.CreatePaymentRequest;
import com.bank.payments.api.PaymentResponse;
import com.bank.payments.domain.EntryType;
import com.bank.payments.domain.LedgerEntry;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.repo.LedgerEntryRepository;
import com.bank.payments.repo.PaymentRepository;
import com.bank.payments.service.AccountService;
import com.bank.payments.service.AuditService;
import com.bank.payments.service.PaymentService;
import com.bank.payments.service.RiskService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;

@Service
public class PaymentServiceImpl implements PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerEntryRepository ledgerEntryRepository;
    private final RiskService riskService;
    private final AccountService accountService;
    private final AuditService auditService;

    public PaymentServiceImpl(PaymentRepository paymentRepository,
                              LedgerEntryRepository ledgerEntryRepository,
                              RiskService riskService,
                              AccountService accountService,
                              AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.ledgerEntryRepository = ledgerEntryRepository;
        this.riskService = riskService;
        this.accountService = accountService;
        this.auditService = auditService;
    }

    @Override
    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey, String actorId) {
        var existing = paymentRepository.findByIdempotencyKey(idempotencyKey);
        if (existing.isPresent()) {
            Payment p = existing.get();
            return new PaymentResponse(p.getId(), p.getStatus(), p.getAmount(), p.getCurrency());
        }

        validateBusinessRules(request);

        riskService.assessOrThrow(
                request.getSourceAccountId(),
                request.getDestinationAccountId(),
                request.getCurrency()
        );

        Instant now = Instant.now();
        Payment payment = new Payment(
                UUID.randomUUID(),
                idempotencyKey,
                request.getSourceAccountId(),
                request.getDestinationAccountId(),
                request.getAmount(),
                request.getCurrency(),
                PaymentStatus.PENDING,
                now,
                now
        );

        paymentRepository.save(payment);

        accountService.debitOrThrow(
                request.getSourceAccountId(),
                request.getAmount(),
                request.getCurrency()
        );

        accountService.creditOrThrow(
                request.getDestinationAccountId(),
                request.getAmount(),
                request.getCurrency()
        );

        ledgerEntryRepository.save(new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                request.getSourceAccountId(),
                EntryType.DEBIT,
                request.getAmount(),
                request.getCurrency(),
                now
        ));

        ledgerEntryRepository.save(new LedgerEntry(
                UUID.randomUUID(),
                payment.getId(),
                request.getDestinationAccountId(),
                EntryType.CREDIT,
                request.getAmount(),
                request.getCurrency(),
                now
        ));

        payment.markCompleted();
        paymentRepository.save(payment);

        auditService.record("PAYMENT_CREATED", actorId, Map.of(
                "paymentId", payment.getId().toString(),
                "sourceAccountId", request.getSourceAccountId(),
                "destinationAccountId", request.getDestinationAccountId(),
                "amount", request.getAmount().toPlainString(),
                "currency", request.getCurrency(),
                "status", payment.getStatus().name()
        ));

        return new PaymentResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency()
        );
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getSourceAccountId().equals(request.getDestinationAccountId())) {
            throw new IllegalArgumentException("Source and destination accounts must differ");
        }
    }
}
```

