# 10. Payment service

## `PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.dto.PaymentStatusResponse;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final PaymentProcessor paymentProcessor;

    public PaymentService(
            PaymentRepository paymentRepository,
            IdempotencyService idempotencyService,
            PaymentProcessor paymentProcessor) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.paymentProcessor = paymentProcessor;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return idempotencyService.findExistingPayment(idempotencyKey)
                .map(existing -> new PaymentResponse(
                        existing.getId(),
                        existing.getStatus(),
                        existing.getCreatedAt()))
                .orElseGet(() -> {
                    Payment payment = new Payment();
                    payment.setIdempotencyKey(idempotencyKey);
                    payment.setDebtorAccount(request.getDebtorAccount());
                    payment.setCreditorAccount(request.getCreditorAccount());
                    payment.setAmount(request.getAmount());
                    payment.setCurrency(request.getCurrency());
                    payment.setPaymentType(request.getPaymentType());
                    payment.setClientReference(request.getClientReference());
                    payment.setStatus(PaymentStatus.RECEIVED);

                    Payment saved = paymentRepository.save(payment);

                    saved.setStatus(PaymentStatus.VALIDATED);
                    paymentRepository.save(saved);

                    paymentProcessor.process(saved);

                    return new PaymentResponse(saved.getId(), saved.getStatus(), saved.getCreatedAt());
                });
    }

    @Transactional(readOnly = true)
    public PaymentStatusResponse getPayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));

        return new PaymentStatusResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getDebtorAccount(),
                payment.getCreditorAccount(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getClientReference(),
                payment.getFailureReason(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }
}
```

