## `service/PaymentApplicationService.java`

```java
package com.bank.payments.service;

import com.bank.payments.domain.Payment;
import com.bank.payments.dto.CreatePaymentRequest;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentProcessor paymentProcessor;

    public PaymentApplicationService(PaymentRepository paymentRepository, PaymentProcessor paymentProcessor) {
        this.paymentRepository = paymentRepository;
        this.paymentProcessor = paymentProcessor;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request) {
        return paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
                .orElseGet(() -> createAndProcessPayment(request));
    }

    private Payment createAndProcessPayment(CreatePaymentRequest request) {
        try {
            Payment payment = new Payment(
                    UUID.randomUUID(),
                    request.getIdempotencyKey(),
                    request.getSourceAccountId(),
                    request.getDestinationAccountId(),
                    request.getAmount(),
                    request.getCurrency(),
                    request.getPaymentType(),
                    request.getReference()
            );

            payment = paymentRepository.save(payment);

            payment.markProcessing();
            paymentRepository.save(payment);

            try {
                paymentProcessor.process(payment);
                payment.markCompleted();
            } catch (Exception ex) {
                payment.markFailed("PROCESSING_ERROR", ex.getMessage());
            }

            return paymentRepository.save(payment);

        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
                    .orElseThrow(() -> ex);
        }
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));
    }
}
```

