package com.bank.payment.service;

import com.bank.payment.dto.CreatePaymentRequest;
import com.bank.payment.exception.PaymentValidationException;
import org.springframework.stereotype.Component;

import java.util.Set;

@Component
public class DefaultPaymentValidator implements PaymentValidator {

    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP");

    @Override
    public void validate(CreatePaymentRequest request) {
        if (!SUPPORTED_CURRENCIES.contains(request.getCurrency())) {
            throw new PaymentValidationException("Unsupported currency: " + request.getCurrency());
        }

        if (request.getSourceAccountId().equals(request.getDestinationAccountId())) {
            throw new PaymentValidationException("Source and destination accounts must differ");
        }
    }
}
