## Payment service

### PaymentService.java
```java
package com.bank.payment.service;

import com.bank.payment.domain.PaymentStatus;
import com.bank.payment.dto.CreatePaymentRequest;
import com.bank.payment.dto.PaymentResponse;
import com.bank.payment.entity.PaymentEntity;
import com.bank.payment.exception.PaymentNotFoundException;
import com.bank.payment.repository.PaymentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidator paymentValidator;
    private final FraudCheckService fraudCheckService;
    private final LedgerService ledgerService;
    private final PaymentAuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentValidator paymentValidator,
                          FraudCheckService fraudCheckService,
                          LedgerService ledgerService,
                          PaymentAuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.paymentValidator = paymentValidator;
        this.fraudCheckService = fraudCheckService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey, String correlationId) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .map(existing -> toResponse(existing))
                .orElseGet(() -> createNewPayment(request, idempotencyKey, correlationId));
    }

    @Transactional
    protected PaymentResponse createNewPayment(CreatePaymentRequest request, String idempotencyKey, String correlationId) {
        PaymentEntity payment = new PaymentEntity();
        payment.setPaymentId(UUID.randomUUID());
        payment.setClientRequestId(UUID.randomUUID().toString());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setSourceAccountId(request.getSourceAccountId());
        payment.setDestinationAccountId(request.getDestinationAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setPaymentType(request.getPaymentType());
        payment.setReference(request.getReference());
        payment.setCorrelationId(correlationId);
        payment.setCreatedAt(Instant.now());
        payment.setUpdatedAt(Instant.now());
        payment.setStatus(PaymentStatus.RECEIVED);

        paymentRepository.save(payment);
        auditService.record(payment, "PAYMENT_RECEIVED", null, PaymentStatus.RECEIVED.name(), "SYSTEM", "Payment request received");

        transition(payment, PaymentStatus.VALIDATING, "SYSTEM", "Starting validation");
        paymentValidator.validate(request);

        if (fraudCheckService.requiresManualReview(request)) {
            transition(payment, PaymentStatus.PENDING_REVIEW, "SYSTEM", "Payment requires manual review");
            return toResponse(paymentRepository.save(payment));
        }

        transition(payment, PaymentStatus.APPROVED, "SYSTEM", "Payment approved");
        ledgerService.reserveFunds(payment);
        transition(payment, PaymentStatus.RESERVED, "SYSTEM", "Funds reserved");

        transition(payment, PaymentStatus.PROCESSING, "SYSTEM", "Payment processing started");
        ledgerService.settle(payment);
        transition(payment, PaymentStatus.SETTLED, "SYSTEM", "Payment settled");

        paymentRepository.save(payment);
        return toResponse(payment);
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(UUID paymentId) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    @Transactional
    public PaymentResponse reversePayment(UUID paymentId) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));

        if (payment.getStatus() != PaymentStatus.SETTLED) {
            throw new IllegalStateException("Only settled payments may be reversed");
        }

        ledgerService.reverse(payment);
        transition(payment, PaymentStatus.REVERSED, "SYSTEM", "Payment reversed");
        paymentRepository.save(payment);

        return toResponse(payment);
    }

    private void transition(PaymentEntity payment, PaymentStatus newStatus, String actor, String details) {
        PaymentStatus previous = payment.getStatus();
        payment.setStatus(newStatus);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record(payment, "STATUS_CHANGED",
                previous != null ? previous.name() : null,
                newStatus.name(),
                actor,
                details);
    }

    private PaymentResponse toResponse(PaymentEntity entity) {
        return new PaymentResponse(
                entity.getPaymentId(),
                entity.getStatus(),
                entity.getCorrelationId(),
                entity.getCreatedAt()
        );
    }
}
```

