import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentService paymentService;

    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PaymentResponse createPayment(
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId,
            @Valid @RequestBody CreatePaymentRequest request) {

        String effectiveCorrelationId = correlationId != null ? correlationId : UUID.randomUUID().toString();
        return paymentService.createPayment(request, idempotencyKey, effectiveCorrelationId);
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable UUID paymentId) {
        return paymentService.getPayment(paymentId);
    }

    @PostMapping("/{paymentId}/reverse")
    public PaymentResponse reversePayment(@PathVariable UUID paymentId) {
        return paymentService.reversePayment(paymentId);
    }
}
