# 13. Application service

## `PaymentApplicationService.java`

```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.mapper.PaymentMapper;
import com.bank.payments.repository.IdempotencyRepository;
import com.bank.payments.repository.PaymentRepository;
import com.bank.payments.repository.entity.IdempotencyRecordEntity;
import com.bank.payments.repository.entity.PaymentEntity;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRepository idempotencyRepository;
    private final PaymentMapper paymentMapper;
    private final FraudScreeningService fraudScreeningService;
    private final ComplianceService complianceService;
    private final AuditService auditService;
    private final EventPublisher eventPublisher;

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = idempotencyRepository.findById(idempotencyKey);
            if (existing.isPresent()) {
                PaymentEntity existingPayment = paymentRepository.findById(existing.get().getPaymentId())
                        .orElseThrow(() -> new PaymentNotFoundException(existing.get().getPaymentId()));
                return paymentMapper.toDomain(existingPayment);
            }
        }

        Instant now = Instant.now();
        UUID paymentId = UUID.randomUUID();

        PaymentEntity entity = new PaymentEntity();
        entity.setId(paymentId);
        entity.setDebtorAccount(request.debtorAccount());
        entity.setCreditorAccount(request.creditorAccount());
        entity.setAmount(request.amount());
        entity.setCurrency(request.currency());
        entity.setPaymentType(request.paymentType());
        entity.setReference(request.reference());
        entity.setCreatedAt(now);
        entity.setUpdatedAt(now);
        entity.setStatus(PaymentStatus.PENDING);

        PaymentEntity saved = paymentRepository.save(entity);
        Payment payment = paymentMapper.toDomain(saved);

        boolean compliant = complianceService.isCompliant(payment);
        boolean fraudApproved = fraudScreeningService.isApproved(payment);

        if (!compliant || !fraudApproved) {
            saved.setStatus(PaymentStatus.REJECTED);
        } else {
            saved.setStatus(PaymentStatus.APPROVED);
        }
        saved.setUpdatedAt(Instant.now());

        saved = paymentRepository.save(saved);

        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            try {
                IdempotencyRecordEntity record = new IdempotencyRecordEntity();
                record.setIdempotencyKey(idempotencyKey);
                record.setPaymentId(saved.getId());
                record.setCreatedAt(Instant.now());
                idempotencyRepository.save(record);
            } catch (DataIntegrityViolationException e) {
                var existing = idempotencyRepository.findById(idempotencyKey)
                        .orElseThrow(() -> e);
                PaymentEntity existingPayment = paymentRepository.findById(existing.getPaymentId())
                        .orElseThrow(() -> new PaymentNotFoundException(existing.getPaymentId()));
                return paymentMapper.toDomain(existingPayment);
            }
        }

        Payment finalPayment = paymentMapper.toDomain(saved);
        auditService.record("PAYMENT_CREATED", "paymentId=" + finalPayment.id() + ", status=" + finalPayment.status());
        eventPublisher.publishPaymentCreated(finalPayment);

        return finalPayment;
    }

    public Payment getPayment(UUID id) {
        PaymentEntity entity = paymentRepository.findById(id)
                .orElseThrow(() -> new PaymentNotFoundException(id));
        return paymentMapper.toDomain(entity);
    }
}
```

