```java
package com.bank.payments.service;

import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.exception.InvalidPaymentStateException;
import org.springframework.stereotype.Service;

@Service
public class PaymentDomainService {

    public PaymentStatus evaluate(boolean compliant, boolean fraudApproved) {
        return (compliant && fraudApproved) ? PaymentStatus.APPROVED : PaymentStatus.REJECTED;
    }

    public PaymentStatus settle(PaymentStatus current) {
        if (current != PaymentStatus.APPROVED) {
            throw new InvalidPaymentStateException("Only APPROVED payments can be settled");
        }
        return PaymentStatus.SETTLED;
    }
}
