```java
package com.bank.payments.domain;

import jakarta.persistence.*;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments", indexes = {
        @Index(name = "idx_payment_client_ref", columnList = "clientPaymentReference", unique = true)
})
public class Payment {

    @Id
    private UUID id;

    @Column(nullable = false, unique = true, length = 64)
    private String clientPaymentReference;

    @Column(nullable = false, length = 34)
    private String debtorAccount;

    @Column(nullable = false, length = 34)
    private String creditorAccount;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(length = 140)
    private String remittanceInformation;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentStatus status;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    public Payment() {
    }

    public static Payment fromRequest(PaymentRequest request) {
        Payment payment = new Payment();
        payment.id = UUID.randomUUID();
        payment.clientPaymentReference = request.getClientPaymentReference();
        payment.debtorAccount = request.getDebtorAccount();
        payment.creditorAccount = request.getCreditorAccount();
        payment.amount = request.getAmount();
        payment.currency = request.getCurrency();
        payment.remittanceInformation = request.getRemittanceInformation();
