## `PaymentProcessingService.java`

```java
package com.bank.payments.service;

import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentRequest;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.exception.DuplicatePaymentException;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final ComplianceService complianceService;
    private final FraudService fraudService;
    private final LedgerService ledgerService;
    private final AuditService auditService;

    public PaymentProcessingService(
            PaymentRepository paymentRepository,
            ComplianceService complianceService,
            FraudService fraudService,
            LedgerService ledgerService,
            AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.complianceService = complianceService;
        this.fraudService = fraudService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
    }

    @Transactional
    public Payment submitPayment(PaymentRequest request) {
        paymentRepository.findByClientPaymentReference(request.getClientPaymentReference())
                .ifPresent(existing -> {
                    throw new DuplicatePaymentException(
                            "Payment already exists for reference: " + request.getClientPaymentReference());
                });

        Payment payment = Payment.fromRequest(request);
        auditService.record("PAYMENT_RECEIVED", payment, "Payment request accepted");

        try {
            payment = paymentRepository.save(payment);
        } catch (DataIntegrityViolationException ex) {
            throw new DuplicatePaymentException(
                    "Duplicate payment reference: " + request.getClientPaymentReference());
        }

        payment.setStatus(PaymentStatus.VALIDATED);
        auditService.record("PAYMENT_VALIDATED", payment, "Basic validation completed");

        payment.setStatus(PaymentStatus.PENDING_COMPLIANCE);
        auditService.record("PAYMENT_COMPLIANCE_STARTED", payment, "Compliance screening started");

        boolean compliancePassed = complianceService.screen(payment);
        boolean fraudPassed = fraudService.assess(payment);

        if (!compliancePassed || !fraudPassed) {
            payment.setStatus(PaymentStatus.REJECTED);
            paymentRepository.save(payment);
            auditService.record("PAYMENT_REJECTED", payment, "Compliance or fraud checks failed");
            return payment;
        }

        payment.setStatus(PaymentStatus.APPROVED);
        auditService.record("PAYMENT_APPROVED", payment, "Payment approved");

        payment.setStatus(PaymentStatus.PROCESSING);
        auditService.record("PAYMENT_PROCESSING", payment, "Ledger posting started");

        try {
            ledgerService.post(payment);
            payment.setStatus(PaymentStatus.SETTLED);
            auditService.record("PAYMENT_SETTLED", payment, "Payment settled successfully");
        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            auditService.record("PAYMENT_FAILED", payment, "Ledger posting failed: " + ex.getMessage());
        }

        return paymentRepository.save(payment);
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }
}
```

