package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.InvalidPaymentException;
import org.springframework.stereotype.Service;

import java.util.Set;

@Service
public class PaymentValidationService {

    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP");

    public void validate(CreatePaymentRequest request) {
        if (request.getDebtorAccountId().equals(request.getCreditorAccountId())) {
            throw new InvalidPaymentException("Debtor and creditor accounts must be different");
        }

        if (!SUPPORTED_CURRENCIES.contains(request.getCurrency())) {
            throw new InvalidPaymentException("Unsupported currency: " + request.getCurrency());
        }
    }
}
