## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidationService validationService;
    private final AuditService auditService;
    private final IdempotencyService idempotencyService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            PaymentValidationService validationService,
            AuditService auditService,
            IdempotencyService idempotencyService) {
        this.paymentRepository = paymentRepository;
        this.validationService = validationService;
        this.auditService = auditService;
        this.idempotencyService = idempotencyService;
    }

    @Transactional
    public PaymentResponse createPayment(String idempotencyKey, CreatePaymentRequest request) {
        return idempotencyService.findExisting(idempotencyKey)
                .map(this::toResponse)
                .orElseGet(() -> createNewPayment(idempotencyKey, request));
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(String paymentId) {
        Payment payment = paymentRepository.findByPaymentId(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse createNewPayment(String idempotencyKey, CreatePaymentRequest request) {
        validationService.validate(request);

        Payment payment = new Payment();
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDebtorAccountId(request.getDebtorAccountId());
        payment.setCreditorAccountId(request.getCreditorAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            Payment saved = paymentRepository.save(payment);
            auditService.record(saved.getPaymentId(), "PAYMENT_CREATED", "Payment created with status RECEIVED");
            return toResponse(saved);
        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByIdempotencyKey(idempotencyKey)
                    .map(this::toResponse)
                    .orElseThrow(() -> ex);
        }
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getPaymentId(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getReference(),
                payment.getCreatedAt()
        );
    }
}
```

