import org.springframework.stereotype.Component;

@Component
public class PaymentValidator {

    public void validate(CreatePaymentRequest request) {
        if (request.getDebtorAccount().equals(request.getCreditorAccount())) {
            throw new ValidationException("Debtor and creditor accounts must be different");
        }

        if (request.getClientPaymentReference().length() > 64) {
            throw new ValidationException("Client payment reference exceeds max length");
        }
    }
}
