```java
package com.bank.payments.service;

import com.bank.payments.domain.IdempotencyRecord;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.dto.CreatePaymentRequest;
import com.bank.payments.dto.PaymentResponse;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.repository.IdempotencyRecordRepository;
import com.bank.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRecordRepository idempotencyRecordRepository;
    private final PaymentValidator paymentValidator;
    private final AuditService auditService;
    private final PaymentEventPublisher eventPublisher;

    public PaymentService(PaymentRepository paymentRepository,
                          IdempotencyRecordRepository idempotencyRecordRepository,
                          PaymentValidator paymentValidator,
                          AuditService auditService,
                          PaymentEventPublisher eventPublisher) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRecordRepository = idempotencyRecordRepository;
        this.paymentValidator = paymentValidator;
        this.auditService = auditService;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        idempotencyRecordRepository.findByIdempotencyKey(idempotencyKey).ifPresent(record -> {
            throw new IllegalStateException(record.getPaymentId().toString());
        });

        paymentValidator.validate(request);

        Payment payment = new Payment();
        payment.setClientPaymentReference(request.getClientPaymentReference());
        payment.setDebtorAccount(request.getDebtorAccount());
        payment.setCreditorAccount(request.getCreditorAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setStatus(PaymentStatus.RECEIVED);

        try {
            payment = paymentRepository.save(payment);

            payment.setStatus(PaymentStatus.VALIDATED);
            payment = paymentRepository.save(payment);

            idempotencyRecordRepository.save(new IdempotencyRecord(idempotencyKey, payment.getId()));

            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);

            payment.setStatus(PaymentStatus.COMPLETED);
            payment = paymentRepository.save(payment);

            auditService.record("PAYMENT_CREATED", "paymentId=" + payment.getId());
            eventPublisher.publishPaymentCreated(payment);
            eventPublisher.publishPaymentCompleted(payment);

            return toResponse(payment);
        } catch (DataIntegrityViolationException ex) {
            throw new IllegalStateException("Duplicate request or client payment reference");
        }
    }

    public PaymentResponse getPayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getId());
        response.setClientPaymentReference(payment.getClientPaymentReference());
        response.setDebtorAccount(payment.getDebtorAccount());
        response.setCreditorAccount(payment.getCreditorAccount());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setStatus(payment.getStatus());
        response.setFailureReason(payment.getFailureReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
```

