## `DefaultPaymentProcessor.java`

```java
package com.bank.payments.service.impl;

import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentEvent;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.repository.PaymentEventRepository;
import com.bank.payments.repository.PaymentRepository;
import com.bank.payments.service.LedgerService;
import com.bank.payments.service.PaymentProcessor;
import com.bank.payments.service.ProviderGateway;
import com.bank.payments.service.RiskService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class DefaultPaymentProcessor implements PaymentProcessor {

    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final ProviderGateway providerGateway;
    private final PaymentRepository paymentRepository;
    private final PaymentEventRepository paymentEventRepository;

    public DefaultPaymentProcessor(RiskService riskService,
                                   LedgerService ledgerService,
                                   ProviderGateway providerGateway,
                                   PaymentRepository paymentRepository,
                                   PaymentEventRepository paymentEventRepository) {
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.providerGateway = providerGateway;
        this.paymentRepository = paymentRepository;
        this.paymentEventRepository = paymentEventRepository;
    }

    @Override
    @Transactional
    public Payment process(Payment payment) {
        payment.setStatus(PaymentStatus.VALIDATED);
        paymentRepository.save(payment);
        appendEvent(payment, "PAYMENT_VALIDATED", "{\"status\":\"VALIDATED\"}");

        RiskService.RiskDecision riskDecision = riskService.assess(payment);
        if (!riskDecision.approved()) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
            payment.setFailureCode(riskDecision.code());
            payment.setFailureReason(riskDecision.reason());
            paymentRepository.save(payment);
            appendEvent(payment, "PAYMENT_PENDING_REVIEW",
                    "{\"code\":\"" + riskDecision.code() + "\",\"reason\":\"" + riskDecision.reason() + "\"}");
            return payment;
        }

        payment.setStatus(PaymentStatus.APPROVED);
        paymentRepository.save(payment);
        appendEvent(payment, "PAYMENT_APPROVED", "{\"status\":\"APPROVED\"}");

        LedgerService.LedgerResult ledgerResult = ledgerService.reserveFunds(payment);
        if (!ledgerResult.success()) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureCode(ledgerResult.code());
            payment.setFailureReason(ledgerResult.reason());
            paymentRepository.save(payment);
            appendEvent(payment, "PAYMENT_FAILED",
                    "{\"code\":\"" + ledgerResult.code() + "\",\"reason\":\"" + ledgerResult.reason() + "\"}");
            return payment;
        }

        payment.setStatus(PaymentStatus.PROCESSING);
        paymentRepository.save(payment);
        appendEvent(payment, "PAYMENT_PROCESSING", "{\"status\":\"PROCESSING\"}");

        ProviderGateway.ProviderResult providerResult = providerGateway.submit(payment);
        if (!providerResult.success()) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureCode(providerResult.code());
            payment.setFailureReason(providerResult.reason());
            paymentRepository.save(payment);
            appendEvent(payment, "PAYMENT_FAILED",
                    "{\"code\":\"" + providerResult.code() + "\",\"reason\":\"" + providerResult.reason() + "\"}");
            return payment;
        }

        payment.setStatus(PaymentStatus.COMPLETED);
        paymentRepository.save(payment);
        appendEvent(payment, "PAYMENT_COMPLETED",
                "{\"providerReference\":\"" + providerResult.providerReference() + "\"}");

        return payment;
    }

    private void appendEvent(Payment payment, String eventType, String payload) {
        PaymentEvent event = new PaymentEvent();
        event.setEventId(UUID.randomUUID());
        event.setPaymentId(payment.getPaymentId());
        event.setEventType(eventType);
        event.setPayload(payload);
        paymentEventRepository.save(event);
    }
}
```

