## `PaymentApplicationService.java`

```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.domain.IdempotencyRecord;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentEvent;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.exception.IdempotencyConflictException;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.repository.IdempotencyRecordRepository;
import com.bank.payments.repository.PaymentEventRepository;
import com.bank.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.HexFormat;
import java.util.List;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentEventRepository paymentEventRepository;
    private final IdempotencyRecordRepository idempotencyRecordRepository;
    private final PaymentProcessor paymentProcessor;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     PaymentEventRepository paymentEventRepository,
                                     IdempotencyRecordRepository idempotencyRecordRepository,
                                     PaymentProcessor paymentProcessor) {
        this.paymentRepository = paymentRepository;
        this.paymentEventRepository = paymentEventRepository;
        this.idempotencyRecordRepository = idempotencyRecordRepository;
        this.paymentProcessor = paymentProcessor;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        String requestHash = hashRequest(request);

        return idempotencyRecordRepository.findById(idempotencyKey)
                .map(existing -> {
                    if (!existing.getRequestHash().equals(requestHash)) {
                        throw new IdempotencyConflictException("Idempotency key reused with different request payload");
                    }
                    return paymentRepository.findById(existing.getPaymentId())
                            .orElseThrow(() -> new IllegalStateException("Payment missing for idempotency record"));
                })
                .orElseGet(() -> {
                    Payment payment = new Payment();
                    payment.setPaymentId(UUID.randomUUID());
                    payment.setClientRequestId(request.getClientRequestId());
                    payment.setIdempotencyKey(idempotencyKey);
                    payment.setDebtorAccountId(request.getDebtorAccountId());
                    payment.setCreditorAccountId(request.getCreditorAccountId());
                    payment.setAmount(request.getAmount());
                    payment.setCurrency(request.getCurrency());
                    payment.setReference(request.getReference());
                    payment.setStatus(PaymentStatus.RECEIVED);
                    payment.setCreatedAt(Instant.now());
                    payment.setUpdatedAt(Instant.now());

                    paymentRepository.save(payment);

                    PaymentEvent receivedEvent = new PaymentEvent();
                    receivedEvent.setEventId(UUID.randomUUID());
                    receivedEvent.setPaymentId(payment.getPaymentId());
                    receivedEvent.setEventType("PAYMENT_RECEIVED");
                    receivedEvent.setPayload("{\"status\":\"RECEIVED\"}");
                    paymentEventRepository.save(receivedEvent);

                    IdempotencyRecord record = new IdempotencyRecord();
                    record.setIdempotencyKey(idempotencyKey);
                    record.setRequestHash(requestHash);
                    record.setPaymentId(payment.getPaymentId());
                    idempotencyRecordRepository.save(record);

                    return paymentProcessor.process(payment);
                });
    }

    @Transactional(readOnly = true)
    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    @Transactional(readOnly = true)
    public List<PaymentEvent> getPaymentEvents(UUID paymentId) {
        return paymentEventRepository.findByPaymentIdOrderByCreatedAtAsc(paymentId);
    }

    private String hashRequest(CreatePaymentRequest request) {
        try {
            String canonical = String.join("|",
                    request.getClientRequestId(),
                    request.getDebtorAccountId(),
                    request.getCreditorAccountId(),
                    request.getAmount().toPlainString(),
                    request.getCurrency(),
                    request.getReference());

            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (Exception e) {
            throw new IllegalStateException("Unable to hash request", e);
        }
    }
}
```

