```java
package com.bank.payments.api;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.api.dto.PaymentResponse;
import com.bank.payments.domain.Payment;
import com.bank.payments.service.PaymentApplicationService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentApplicationService paymentApplicationService;

    public PaymentController(PaymentApplicationService paymentApplicationService) {
        this.paymentApplicationService = paymentApplicationService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PaymentResponse createPayment(
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @Valid @RequestBody CreatePaymentRequest request) {

        Payment payment = paymentApplicationService.createPayment(request, idempotencyKey);
        return toResponse(payment);
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable UUID paymentId) {
        return toResponse(paymentApplicationService.getPayment(paymentId));
    }

    private PaymentResponse toResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setClientRequestId(payment.getClientRequestId());
        response.setDebtorAccountId(payment.getDebtorAccountId());
        response.setCreditorAccountId(payment.getCredorAccountId());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setReference(payment.getReference());
        response.setStatus(payment.getStatus());
        response.setFailureCode(payment.getFailureCode());
        response.setFailureReason(payment.getFailureReason());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
