package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import org.springframework.stereotype.Service;

@Service
public class PaymentValidator {

    public void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getDebtorAccount().equals(request.getCreditorAccount())) {
            throw new IllegalArgumentException("Debtor and creditor accounts must differ");
        }

        if (!isSupportedCurrency(request.getCurrency())) {
            throw new IllegalArgumentException("Unsupported currency: " + request.getCurrency());
        }
    }

    private boolean isSupportedCurrency(String currency) {
        return currency.equals("USD") || currency.equals("EUR") || currency.equals("GBP");
    }
}
