# 11. Payment service

```java
package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.entity.Payment;
import com.example.payments.entity.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidator paymentValidator;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final AuditService auditService;
    private final IdempotencyService idempotencyService;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentValidator paymentValidator,
                          RiskService riskService,
                          LedgerService ledgerService,
                          AuditService auditService,
                          IdempotencyService idempotencyService) {
        this.paymentRepository = paymentRepository;
        this.paymentValidator = paymentValidator;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
        this.idempotencyService = idempotencyService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return idempotencyService.findExistingPayment(idempotencyKey)
                .map(this::toResponse)
                .orElseGet(() -> processNewPayment(request, idempotencyKey));
    }

    private PaymentResponse processNewPayment(CreatePaymentRequest request, String idempotencyKey) {
        paymentValidator.validateBusinessRules(request);

        Payment payment = new Payment(
                idempotencyKey,
                request.getDebtorAccount(),
                request.getCreditorAccount(),
                request.getAmount(),
                request.getCurrency(),
                PaymentStatus.RECEIVED
        );

        payment = paymentRepository.save(payment);
        auditService.logEvent("PAYMENT_RECEIVED", payment, "Payment request accepted");

        if (riskService.requiresManualReview(request)) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
            payment = paymentRepository.save(payment);
            auditService.logEvent("PAYMENT_REVIEW_REQUIRED", payment, "Payment flagged for manual review");
            return toResponse(payment);
        }

        try {
            payment.setStatus(PaymentStatus.PROCESSING);
            payment = paymentRepository.save(payment);
            auditService.logEvent("PAYMENT_PROCESSING", payment, "Posting payment to ledger");

            ledgerService.postPayment(request);

            payment.setStatus(PaymentStatus.COMPLETED);
            payment = paymentRepository.save(payment);
            auditService.logEvent("PAYMENT_COMPLETED", payment, "Payment completed successfully");

        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(ex.getMessage());
            payment = paymentRepository.save(payment);
            auditService.logEvent("PAYMENT_FAILED", payment, ex.getMessage());
        }

        return toResponse(payment);
    }

    public PaymentResponse getPayment(java.util.UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getIdempotencyKey(),
                payment.getDebtorAccount(),
                payment.getCreditorAccount(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getStatus(),
                payment.getFailureReason(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }
}
```

