package com.bank.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments", indexes = {
        @Index(name = "idx_payment_status", columnList = "status"),
        @Index(name = "idx_payment_created_at", columnList = "createdAt")
})
public class Payment {

    @Id
    private UUID id;

    @Column(nullable = false, length = 64)
    private String debtorAccountId;

    @Column(nullable = false, length = 64)
    private String creditorAccountId;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(length = 140)
    private String reference;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentMethod paymentMethod;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentStatus status;

    @Column(nullable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private Long version;

    public Payment() {
    }

    public Payment(UUID id,
                   String debtorAccountId,
                   String creditorAccountId,
                   BigDecimal amount,
                   String currency,
                   String reference,
                   PaymentMethod paymentMethod,
                   PaymentStatus status,
                   Instant createdAt,
                   Instant updatedAt) {
        this.id = id;
        this.debtorAccountId = debtorAccountId;
        this.creditorAccountId = creditorAccountId;
        this.amount = amount;
        this.currency = currency;
        this.reference = reference;
        this.paymentMethod = paymentMethod;
        this.status = status;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    public void markProcessing() {
        if (this.status != PaymentStatus.PENDING) {
            throw new IllegalStateException("Payment cannot transition to PROCESSING from " + this.status);
        }
        this.status = PaymentStatus.PROCESSING;
        this.updatedAt = Instant.now();
    }

    public void markCompleted() {
        if (this.status != PaymentStatus.PROCESSING && this.status != PaymentStatus.PENDING) {
            throw new IllegalStateException("Payment cannot transition to COMPLETED from " + this.status);
        }
        this.status = PaymentStatus.COMPLETED;
        this.updatedAt = Instant.now();
    }

    public void markFailed() {
        if (this.status == PaymentStatus.COMPLETED || this.status == PaymentStatus.CANCELLED) {
            throw new IllegalStateException("Payment cannot transition to FAILED from " + this.status);
        }
        this.status = PaymentStatus.FAILED;
        this.updatedAt = Instant.now();
    }

    public void markCancelled() {
        if (this.status == PaymentStatus.COMPLETED) {
            throw new IllegalStateException("Completed payment cannot be cancelled");
        }
        this.status = PaymentStatus.CANCELLED;
        this.updatedAt = Instant.now();
    }

    public UUID getId() {
        return id;
    }

    public String getDebtorAccountId() {
        return debtorAccountId;
    }

    public String getCreditorAccountId() {
        return creditorAccountId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getCurrency() {
        return currency;
    }

    public String getReference() {
        return reference;
    }

    public PaymentMethod getPaymentMethod() {
        return paymentMethod;
    }

    public PaymentStatus getStatus() {
        return status;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }
}
```

