```java
package com.bank.payments.application;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.audit.AuditService;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.exception.InvalidPaymentStateException;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.persistence.IdempotencyRecord;
import com.bank.payments.persistence.IdempotencyRepository;
import com.bank.payments.persistence.PaymentRepository;
import com.bank.payments.security.SecurityContextFacade;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRepository idempotencyRepository;
    private final AuditService auditService;
    private final SecurityContextFacade securityContextFacade;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     IdempotencyRepository idempotencyRepository,
                                     AuditService auditService,
                                     SecurityContextFacade securityContextFacade) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRepository = idempotencyRepository;
        this.auditService = auditService;
        this.securityContextFacade = securityContextFacade;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        var existing = idempotencyRepository.findByIdempotencyKey(idempotencyKey);
        if (existing.isPresent()) {
            return paymentRepository.findById(existing.get().getPaymentId())
                    .orElseThrow(() -> new PaymentNotFoundException("Payment linked to idempotency key not found"));
        }

        Instant now = Instant.now();
        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference(),
                request.getPaymentMethod(),
                PaymentStatus.PENDING,
                now,
                now
        );

        payment = paymentRepository.save(payment);
        idempotencyRepository.save(new IdempotencyRecord(idempotencyKey, payment.getId(), now));

        auditService.log("CREATE_PAYMENT", payment.getId().toString(), securityContextFacade.currentActor());

        return payment;
    }

    @Transactional(readOnly = true)
    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    @Transactional
    public Payment cancelPayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));

        try {
            payment.markCancelled();
        } catch (IllegalStateException e) {
            throw new InvalidPaymentStateException(e.getMessage());
        }

        payment = paymentRepository.save(payment);
        auditService.log("CANCEL_PAYMENT", payment.getId().toString(), securityContextFacade.currentActor());

        return payment;
    }

    @Transactional
    public Payment processPayment(UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));

        try {
            payment.markProcessing();
            payment.markCompleted();
        } catch (IllegalStateException e) {
            payment.markFailed();
            throw new InvalidPaymentStateException(e.getMessage());
        }

        payment = paymentRepository.save(payment);
        auditService.log("PROCESS_PAYMENT", payment.getId().toString(), securityContextFacade.currentActor());

        return payment;
    }
}
```

