```java
package com.example.payments.repository;

import org.springframework.stereotype.Repository;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryIdempotencyRepository implements IdempotencyRepository {
    private final Map<String, UUID> store = new ConcurrentHashMap<>();

    @Override
    public Optional<UUID> findPaymentIdByKey(String clientId, String idempotencyKey) {
        return Optional.ofNullable(store.get(composeKey(clientId, idempotencyKey)));
    }

    @Override
    public void save(String clientId, String idempotencyKey, UUID paymentId) {
        store.put(composeKey(clientId, idempotencyKey), paymentId);
    }

    private String composeKey(String clientId, String idempotencyKey) {
        return clientId + ":" + idempotencyKey;
    }
}
