# 7. Core payment orchestration service

## PaymentProcessingService.java

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.InvalidPaymentException;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentProcessingService {
    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final ComplianceService complianceService;
    private final LedgerService ledgerService;
    private final RailRoutingService railRoutingService;
    private final AuditService auditService;

    public PaymentProcessingService(
            PaymentRepository paymentRepository,
            IdempotencyService idempotencyService,
            ComplianceService complianceService,
            LedgerService ledgerService,
            RailRoutingService railRoutingService,
            AuditService auditService
    ) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.complianceService = complianceService;
        this.ledgerService = ledgerService;
        this.railRoutingService = railRoutingService;
        this.auditService = auditService;
    }

    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        validateRequest(request);

        if (idempotencyKey != null && !idempotencyKey.isBlank() &&
                idempotencyService.exists(request.getClientId(), idempotencyKey)) {
            return idempotencyService.getExistingPayment(request.getClientId(), idempotencyKey);
        }

        Instant now = Instant.now();
        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getClientId(),
                request.getSourceAccount(),
                request.getDestinationAccount(),
                request.getAmount(),
                request.getCurrency(),
                request.getPaymentType(),
                PaymentStatus.RECEIVED,
                request.getReference(),
                now,
                now,
                null
        );

        paymentRepository.save(payment);
        auditService.record("PAYMENT_RECEIVED", payment);

        payment.setStatus(PaymentStatus.VALIDATED);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_VALIDATED", payment);

        payment.setStatus(PaymentStatus.COMPLIANCE_REVIEW);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_COMPLIANCE_REVIEW", payment);

        if (!complianceService.passes(payment)) {
            payment.setStatus(PaymentStatus.COMPLIANCE_REJECTED);
            payment.setFailureReason("Compliance screening failed");
            paymentRepository.save(payment);
            auditService.record("PAYMENT_COMPLIANCE_REJECTED", payment);

            if (idempotencyKey != null && !idempotencyKey.isBlank()) {
                idempotencyService.save(request.getClientId(), idempotencyKey, payment);
            }

            return payment;
        }

        if (!ledgerService.reserveFunds(payment)) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason("Unable to reserve funds");
            paymentRepository.save(payment);
            auditService.record("PAYMENT_FUNDS_RESERVATION_FAILED", payment);

            if (idempotencyKey != null && !idempotencyKey.isBlank()) {
                idempotencyService.save(request.getClientId(), idempotencyKey, payment);
            }

            return payment;
        }

        payment.setStatus(PaymentStatus.FUNDS_RESERVED);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_FUNDS_RESERVED", payment);

        if (!railRoutingService.submit(payment)) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason("Rail submission failed");
            paymentRepository.save(payment);
            auditService.record("PAYMENT_RAIL_SUBMISSION_FAILED", payment);

            if (idempotencyKey != null && !idempotencyKey.isBlank()) {
                idempotencyService.save(request.getClientId(), idempotencyKey, payment);
            }

            return payment;
        }

        payment.setStatus(PaymentStatus.SUBMITTED_TO_RAIL);
        paymentRepository.save(payment);
        auditService.record("PAYMENT_SUBMITTED_TO_RAIL", payment);

        if (payment.getPaymentType().name().equals("INTERNAL_TRANSFER")) {
            payment.setStatus(PaymentStatus.SETTLED);
            paymentRepository.save(payment);
            auditService.record("PAYMENT_SETTLED", payment);
        }

        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            idempotencyService.save(request.getClientId(), idempotencyKey, payment);
        }

        return payment;
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    private void validateRequest(CreatePaymentRequest request) {
        if (request.getClientId() == null || request.getClientId().isBlank()) {
            throw new InvalidPaymentException("clientId is required");
        }
        if (request.getSourceAccount() == null || request.getSourceAccount().isBlank()) {
            throw new InvalidPaymentException("sourceAccount is required");
        }
        if (request.getDestinationAccount() == null || request.getDestinationAccount().isBlank()) {
            throw new InvalidPaymentException("destinationAccount is required");
        }
        if (request.getAmount() == null || request.getAmount().signum() <= 0) {
            throw new InvalidPaymentException("amount must be greater than zero");
        }
        if (request.getCurrency() == null || request.getCurrency().isBlank()) {
            throw new InvalidPaymentException("currency is required");
        }
        if (request.getPaymentType() == null) {
            throw new InvalidPaymentException("paymentType is required");
        }
    }
}
```

