package com.bank.payments.service;

import com.bank.payments.persistence.entity.AuditEventEntity;
import com.bank.payments.persistence.repository.AuditEventRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class AuditService {

    private final AuditEventRepository auditEventRepository;
    private final ObjectMapper objectMapper;

    public AuditService(AuditEventRepository auditEventRepository, ObjectMapper objectMapper) {
        this.auditEventRepository = auditEventRepository;
        this.objectMapper = objectMapper;
    }

    public void record(String aggregateType, UUID aggregateId, String eventType, Object payload) {
        try {
            AuditEventEntity event = new AuditEventEntity();
            event.setId(UUID.randomUUID());
            event.setAggregateType(aggregateType);
            event.setAggregateId(aggregateId);
            event.setEventType(eventType);
            event.setPayload(objectMapper.writeValueAsString(payload));
            event.setCreatedAt(Instant.now());
            auditEventRepository.save(event);
        } catch (Exception e) {
            throw new RuntimeException("Failed to record audit event", e);
        }
    }
}
