    public void postDoubleEntry(UUID paymentId, UUID sourceAccountId, UUID destinationAccountId,
                                BigDecimal amount, String currency) {

        LedgerEntryEntity debit = new LedgerEntryEntity();
        debit.setId(UUID.randomUUID());
        debit.setPaymentId(paymentId);
        debit.setAccountId(sourceAccountId);
        debit.setEntryType(LedgerEntryType.DEBIT);
        debit.setAmount(amount);
        debit.setCurrency(currency);
        debit.setCreatedAt(Instant.now());

        LedgerEntryEntity credit = new LedgerEntryEntity();
        credit.setId(UUID.randomUUID());
        credit.setPaymentId(paymentId);
        credit.setAccountId(destinationAccountId);
        credit.setEntryType(LedgerEntryType.CREDIT);
        credit.setAmount(amount);
        credit.setCurrency(currency);
        credit.setCreatedAt(Instant.now());

        ledgerEntryRepository.save(debit);
        ledgerEntryRepository.save(credit);
    }
