## Payment service
```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.api.dto.PaymentResponse;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.persistence.entity.PaymentEntity;
import com.bank.payments.persistence.repository.PaymentRepository;
import com.bank.payments.service.exception.InvalidPaymentStateException;
import com.bank.payments.service.exception.PaymentNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final LedgerService ledgerService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          LedgerService ledgerService,
                          AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request) {
        return paymentRepository.findByIdempotencyKey(request.idempotencyKey())
                .map(this::toResponse)
                .orElseGet(() -> createNewPayment(request));
    }

    @Transactional
    public PaymentResponse authorizePayment(UUID paymentId, String approvedBy) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));

        if (payment.getStatus() != PaymentStatus.CREATED) {
            throw new InvalidPaymentStateException("Payment must be in CREATED state to authorize");
        }

        payment.setStatus(PaymentStatus.AUTHORIZED);
        payment.setUpdatedAt(Instant.now());

        PaymentEntity saved = paymentRepository.save(payment);
        auditService.record("PAYMENT", saved.getId(), "PAYMENT_AUTHORIZED",
                new AuditPayload("approvedBy", approvedBy, "status", saved.getStatus().name()));

        return toResponse(saved);
    }

    @Transactional
    public PaymentResponse capturePayment(UUID paymentId, String capturedBy) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));

        if (payment.getStatus() != PaymentStatus.AUTHORIZED) {
            throw new InvalidPaymentStateException("Payment must be in AUTHORIZED state to capture");
        }

        ledgerService.postDoubleEntry(
                payment.getId(),
                payment.getSourceAccountId(),
                payment.getDestinationAccountId(),
                payment.getAmount(),
                payment.getCurrency()
        );

        payment.setStatus(PaymentStatus.CAPTURED);
        payment.setUpdatedAt(Instant.now());

        PaymentEntity saved = paymentRepository.save(payment);
        auditService.record("PAYMENT", saved.getId(), "PAYMENT_CAPTURED",
                new AuditPayload("capturedBy", capturedBy, "status", saved.getStatus().name()));

        return toResponse(saved);
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(UUID paymentId) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse createNewPayment(CreatePaymentRequest request) {
        PaymentEntity payment = new PaymentEntity();
        payment.setId(UUID.randomUUID());
        payment.setIdempotencyKey(request.idempotencyKey());
        payment.setSourceAccountId(request.sourceAccountId());
        payment.setDestinationAccountId(request.destinationAccountId());
        payment.setType(request.type());
        payment.setStatus(PaymentStatus.CREATED);
        payment.setAmount(request.amount());
        payment.setCurrency(request.currency().toUpperCase());
        payment.setReference(request.reference());
        payment.setCreatedAt(Instant.now());
        payment.setUpdatedAt(Instant.now());

        PaymentEntity saved = paymentRepository.save(payment);
        auditService.record("PAYMENT", saved.getId(), "PAYMENT_CREATED", saved);

        return toResponse(saved);
    }

    private PaymentResponse toResponse(PaymentEntity payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getIdempotencyKey(),
                payment.getSourceAccountId(),
                payment.getDestinationAccountId(),
                payment.getType(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getReference(),
                payment.getFailureReason(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }

    public record AuditPayload(String key1, String value1, String key2, String value2) {}
}
```

