# 9. REST controller

```java
package com.bank.payments.api;

import com.bank.payments.api.dto.AuthorizePaymentRequest;
import com.bank.payments.api.dto.CapturePaymentRequest;
import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.api.dto.PaymentResponse;
import com.bank.payments.service.PaymentService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentService paymentService;

    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PaymentResponse createPayment(@Valid @RequestBody CreatePaymentRequest request) {
        return paymentService.createPayment(request);
    }

    @PostMapping("/{paymentId}/authorize")
    public PaymentResponse authorizePayment(@PathVariable UUID paymentId,
                                            @RequestBody(required = false) AuthorizePaymentRequest request) {
        String approvedBy = request != null ? request.approvedBy() : "system";
        return paymentService.authorizePayment(paymentId, approvedBy);
    }

    @PostMapping("/{paymentId}/capture")
    public PaymentResponse capturePayment(@PathVariable UUID paymentId,
                                          @RequestBody(required = false) CapturePaymentRequest request) {
        String capturedBy = request != null ? request.capturedBy() : "system";
        return paymentService.capturePayment(paymentId, capturedBy);
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable UUID paymentId) {
        return paymentService.getPayment(paymentId);
    }
}
