package com.bank.payments.api;

import com.bank.payments.service.exception.InvalidPaymentStateException;
import com.bank.payments.service.exception.PaymentNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.time.Instant;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(PaymentNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public Map<String, Object> handleNotFound(PaymentNotFoundException ex) {
        return Map.of(
                "timestamp", Instant.now().toString(),
                "error", "PAYMENT_NOT_FOUND",
                "message", ex.getMessage()
        );
    }

    @ExceptionHandler(InvalidPaymentStateException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, Object> handleInvalidState(InvalidPaymentStateException ex) {
        return Map.of(
                "timestamp", Instant.now().toString(),
                "error", "INVALID_PAYMENT_STATE",
                "message", ex.getMessage()
        );
    }

    @ExceptionHandler(Exception.class)
    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public Map<String, Object> handleGeneric(Exception ex) {
        return Map.of(
                "timestamp", Instant.now().toString(),
                "error", "INTERNAL_SERVER_ERROR",
                "message", ex.getMessage()
        );
    }
}
