@Entity
@Table(name = "payments", uniqueConstraints = {
        @UniqueConstraint(name = "uk_payments_idempotency_key", columnNames = "idempotency_key")
})
public class Payment {

    @Id
    @Column(name = "payment_id", nullable = false, updatable = false)
    private UUID paymentId;

    @Column(name = "idempotency_key", nullable = false, updatable = false, length = 128)
    private String idempotencyKey;

    @Column(name = "client_request_id", length = 128)
    private String clientRequestId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 32)
    private PaymentStatus status;

    @Enumerated(EnumType.STRING)
    @Column(name = "payment_type", nullable = false, length = 32)
    private PaymentType paymentType;

    @Column(name = "debtor_account_id", nullable = false, length = 64)
    private String debtorAccountId;

    @Column(name = "creditor_account_id", nullable = false, length = 64)
    private String creditorAccountId;

    @Column(name = "amount", nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(name = "currency", nullable = false, length = 3)
    private String currency;

    @Column(name = "reference", length = 256)
    private String reference;

    @Column(name = "failure_code", length = 64)
    private String failureCode;

    @Column(name = "failure_reason", length = 1024)
    private String failureReason;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    private Long version;

    public Payment() {
    }

    public static Payment create(
            String idempotencyKey,
            String clientRequestId,
            PaymentType paymentType,
            String debtorAccountId,
            String creditorAccountId,
            BigDecimal amount,
            String currency,
            String reference
    ) {
        Payment payment = new Payment();
        payment.paymentId = UUID.randomUUID();
        payment.idempotencyKey = idempotencyKey;
        payment.clientRequestId = clientRequestId;
        payment.paymentType = paymentType;
        payment.debtorAccountId = debtorAccountId;
        payment.creditorAccountId = creditorAccountId;
        payment.amount = amount;
        payment.currency = currency;
        payment.reference = reference;
        payment.status = PaymentStatus.RECEIVED;
        payment.createdAt = Instant.now();
        payment.updatedAt = payment.createdAt;
        return payment;
    }

    public void transitionTo(PaymentStatus newStatus) {
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }

    public void markFailed(String code, String reason) {
        this.status = PaymentStatus.FAILED;
        this.failureCode = code;
        this.failureReason = reason;
        this.updatedAt = Instant.now();
    }

    public void markRejected(String code, String reason) {
        this.status = PaymentStatus.REJECTED;
        this.failureCode = code;
        this.failureReason = reason;
        this.updatedAt = Instant.now();
    }

    public void cancel() {
        this.status = PaymentStatus.CANCELLED;
        this.updatedAt = Instant.now();
    }

    public UUID getPaymentId() { return paymentId; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public String getClientRequestId() { return clientRequestId; }
    public PaymentStatus getStatus() { return status; }
    public PaymentType getPaymentType() { return paymentType; }
    public String getDebtorAccountId() { return debtorAccountId; }
    public String getCreditorAccountId() { return creditorAccountId; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public String getReference() { return reference; }
    public String getFailureCode() { return failureCode; }
    public String getFailureReason() { return failureReason; }
    public Instant getCreatedAt() { return createdAt; }
