package com.bank.payments.service;

import com.bank.payments.domain.AuditEvent;
import com.bank.payments.domain.Payment;
import com.bank.payments.dto.CreatePaymentRequest;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.repository.AuditEventRepository;
import com.bank.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final AuditEventRepository auditEventRepository;
    private final PaymentWorkflowService paymentWorkflowService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            AuditEventRepository auditEventRepository,
            PaymentWorkflowService paymentWorkflowService
    ) {
        this.paymentRepository = paymentRepository;
        this.auditEventRepository = auditEventRepository;
        this.paymentWorkflowService = paymentWorkflowService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey, String actor) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> {
                    Payment payment = Payment.create(
                            idempotencyKey,
                            request.getClientRequestId(),
                            request.getPaymentType(),
                            request.getDebtorAccountId(),
                            request.getCreditorAccountId(),
                            request.getAmount(),
                            request.getCurrency(),
                            request.getReference()
                    );

                    paymentRepository.save(payment);
                    auditEventRepository.save(new AuditEvent(
                            payment.getPaymentId(),
                            "PAYMENT_CREATED",
                            actor,
                            "Payment created"
                    ));

                    paymentWorkflowService.process(payment, actor);
                    return payment;
                });
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));
    }
}
