## Workflow service

### `PaymentWorkflowService.java`

```java
package com.bank.payments.service;

import com.bank.payments.domain.AuditEvent;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.repository.AuditEventRepository;
import com.bank.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

@Service
public class PaymentWorkflowService {

    private final PaymentRepository paymentRepository;
    private final AuditEventRepository auditEventRepository;
    private final AccountService accountService;
    private final ComplianceService complianceService;
    private final FraudService fraudService;
    private final LedgerService ledgerService;

    public PaymentWorkflowService(
            PaymentRepository paymentRepository,
            AuditEventRepository auditEventRepository,
            AccountService accountService,
            ComplianceService complianceService,
            FraudService fraudService,
            LedgerService ledgerService
    ) {
        this.paymentRepository = paymentRepository;
        this.auditEventRepository = auditEventRepository;
        this.accountService = accountService;
        this.complianceService = complianceService;
        this.fraudService = fraudService;
        this.ledgerService = ledgerService;
    }

    @Transactional
    public void process(Payment payment, String actor) {
        payment.transitionTo(PaymentStatus.VALIDATING);
        audit(payment, "PAYMENT_VALIDATING", actor, "Validation started");

        if (!accountService.accountsExist(payment.getDebtorAccountId(), payment.getCreditorAccountId())) {
            payment.markRejected("INVALID_ACCOUNT", "One or more accounts do not exist");
            audit(payment, "PAYMENT_REJECTED", actor, "Invalid accounts");
            paymentRepository.save(payment);
            return;
        }

        if (!accountService.hasSufficientFunds(payment.getDebtorAccountId(), payment.getAmount())) {
            payment.markRejected("INSUFFICIENT_FUNDS", "Insufficient funds");
            audit(payment, "PAYMENT_REJECTED", actor, "Insufficient funds");
            paymentRepository.save(payment);
            return;
        }

        payment.transitionTo(PaymentStatus.PENDING_COMPLIANCE);
        audit(payment, "PAYMENT_PENDING_COMPLIANCE", actor, "Compliance screening started");

        if (!complianceService.screen(payment)) {
            payment.markRejected("COMPLIANCE_REJECTED", "Compliance screening failed");
            audit(payment, "PAYMENT_REJECTED", actor, "Compliance rejected");
            paymentRepository.save(payment);
            return;
        }

        payment.transitionTo(PaymentStatus.PENDING_FRAUD_REVIEW);
        audit(payment, "PAYMENT_PENDING_FRAUD_REVIEW", actor, "Fraud review started");

        if (!fraudService.approve(payment)) {
            payment.markRejected("FRAUD_REJECTED", "Fraud screening failed");
            audit(payment, "PAYMENT_REJECTED", actor, "Fraud rejected");
            paymentRepository.save(payment);
            return;
        }

        payment.transitionTo(PaymentStatus.AUTHORIZED);
        audit(payment, "PAYMENT_AUTHORIZED", actor, "Payment authorized");

        accountService.placeHold(payment.getDebtorAccountId(), payment.getAmount());

        payment.transitionTo(PaymentStatus.PROCESSING);
        audit(payment, "PAYMENT_PROCESSING", actor, "Ledger posting started");

        try {
            ledgerService.post(payment);
            payment.transitionTo(PaymentStatus.SETTLED);
            audit(payment, "PAYMENT_SETTLED", actor, "Payment settled");
        } catch (Exception ex) {
            accountService.releaseHold(payment.getDebtorAccountId(), payment.getAmount());
            payment.markFailed("LEDGER_POSTING_FAILED", ex.getMessage());
            audit(payment, "PAYMENT_FAILED", actor, "Ledger posting failed");
        }

        paymentRepository.save(payment);
    }

    private void audit(Payment payment, String eventType, String actor, String details) {
        auditEventRepository.save(new AuditEvent(payment.getPaymentId(), eventType, actor, details));
    }
}
```

