package com.bank.payments.repository;

import com.bank.payments.domain.Account;
import jakarta.annotation.PostConstruct;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryAccountRepository implements AccountRepository {

    private final Map<String, Account> accounts = new ConcurrentHashMap<>();

    @PostConstruct
    public void init() {
        accounts.put("ACC-1001", new Account("ACC-1001", "USD", new BigDecimal("10000.00")));
        accounts.put("ACC-2001", new Account("ACC-2001", "USD", new BigDecimal("5000.00")));
        accounts.put("ACC-3001", new Account("ACC-3001", "EUR", new BigDecimal("7000.00")));
    }

    @Override
    public Optional<Account> findByAccountId(String accountId) {
        return Optional.ofNullable(accounts.get(accountId));
    }

    @Override
    public Account save(Account account) {
        accounts.put(account.getAccountId(), account);
        return account;
    }
}
