# 10. Services

## `ValidationService.java`

```java
package com.bank.payments.service;

import com.bank.payments.domain.Account;
import com.bank.payments.domain.PaymentRequest;
import com.bank.payments.exception.PaymentException;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;

@Service
public class ValidationService {

    public void validatePaymentRequest(PaymentRequest request) {
        if (request.getSourceAccountId().equals(request.getDestinationAccountId())) {
            throw new PaymentException("Source and destination accounts must be different");
        }

        if (!isSupportedCurrency(request.getCurrency())) {
            throw new PaymentException("Unsupported currency: " + request.getCurrency());
        }

        if (request.getAmount().scale() > 2) {
            throw new PaymentException("Amount cannot have more than 2 decimal places");
        }
    }

    public void validateAccountForDebit(Account account, PaymentRequest request) {
        if (!account.getCurrency().equalsIgnoreCase(request.getCurrency())) {
            throw new PaymentException("Currency mismatch for source account");
        }

        if (account.getBalance().compareTo(request.getAmount()) < 0) {
            throw new PaymentException("Insufficient funds");
        }
    }

    public void validateAccountForCredit(Account account, PaymentRequest request) {
        if (!account.getCurrency().equalsIgnoreCase(request.getCurrency())) {
            throw new PaymentException("Currency mismatch for destination account");
        }
    }

    private boolean isSupportedCurrency(String currency) {
        return currency != null &&
                (currency.equalsIgnoreCase("USD")
                        || currency.equalsIgnoreCase("EUR")
                        || currency.equalsIgnoreCase("GBP"));
    }
}
```

