## `PaymentProcessingService.java`

```java
package com.bank.payments.service;

import com.bank.payments.domain.Account;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentRequest;
import com.bank.payments.domain.PaymentResponse;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.exception.PaymentException;
import com.bank.payments.repository.AccountRepository;
import com.bank.payments.repository.PaymentRepository;
import com.bank.payments.util.IdGenerator;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.time.Instant;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final AccountRepository accountRepository;
    private final ValidationService validationService;
    private final AuditService auditService;

    public PaymentProcessingService(PaymentRepository paymentRepository,
                                    AccountRepository accountRepository,
                                    ValidationService validationService,
                                    AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.accountRepository = accountRepository;
        this.validationService = validationService;
        this.auditService = auditService;
    }

    public PaymentResponse processPayment(PaymentRequest request) {
        return paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
                .map(this::toResponse)
                .orElseGet(() -> createAndProcessPayment(request));
    }

    public PaymentResponse getPayment(String paymentId) {
        Payment payment = paymentRepository.findByPaymentId(paymentId)
                .orElseThrow(() -> new PaymentException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse createAndProcessPayment(PaymentRequest request) {
        validationService.validatePaymentRequest(request);

        Instant now = Instant.now();
        Payment payment = new Payment(
                IdGenerator.newPaymentId(),
                request.getIdempotencyKey(),
                request.getSourceAccountId(),
                request.getDestinationAccountId(),
                request.getAmount(),
                request.getCurrency().toUpperCase(),
                PaymentStatus.RECEIVED,
                now,
                now,
                null
        );

        paymentRepository.save(payment);
        auditService.record(payment.getPaymentId(), "PAYMENT_RECEIVED", "Payment request received");

        try {
            payment.setStatus(PaymentStatus.VALIDATED);
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_VALIDATED", "Payment validated");

            Account source = accountRepository.findByAccountId(request.getSourceAccountId())
                    .orElseThrow(() -> new PaymentException("Source account not found"));
            Account destination = accountRepository.findByAccountId(request.getDestinationAccountId())
                    .orElseThrow(() -> new PaymentException("Destination account not found"));

            validationService.validateAccountForDebit(source, request);
            validationService.validateAccountForCredit(destination, request);

            payment.setStatus(PaymentStatus.PROCESSING);
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_PROCESSING", "Payment processing started");

            debit(source, request.getAmount());
            credit(destination, request.getAmount());

            accountRepository.save(source);
            accountRepository.save(destination);

            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_COMPLETED", "Payment completed successfully");

        } catch (Exception ex) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(ex.getMessage());
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_FAILED", ex.getMessage());
        }

        return toResponse(payment);
    }

    private void debit(Account account, BigDecimal amount) {
        account.setBalance(account.getBalance().subtract(amount));
    }

    private void credit(Account account, BigDecimal amount) {
        account.setBalance(account.getBalance().add(amount));
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getPaymentId(),
                payment.getStatus().name(),
                payment.getSourceAccountId(),
                payment.getDestinationAccountId(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getCreatedAt(),
                payment.getUpdatedAt(),
                payment.getFailureReason()
        );
    }
}
```

