## Payment entity

```java
package com.bank.payments.domain;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

public class Payment {
    private UUID id;
    private String clientPaymentId;
    private String idempotencyKey;
    private String debtorAccount;
    private String creditorAccount;
    private BigDecimal amount;
    private String currency;
    private PaymentStatus status;
    private String failureReason;
    private Instant createdAt;
    private Instant updatedAt;

    public Payment(
            UUID id,
            String clientPaymentId,
            String idempotencyKey,
            String debtorAccount,
            String creditorAccount,
            BigDecimal amount,
            String currency,
            PaymentStatus status,
            String failureReason,
            Instant createdAt,
            Instant updatedAt) {
        this.id = id;
        this.clientPaymentId = clientPaymentId;
        this.idempotencyKey = idempotencyKey;
        this.debtorAccount = debtorAccount;
        this.creditorAccount = creditorAccount;
        this.amount = amount;
        this.currency = currency;
        this.status = status;
        this.failureReason = failureReason;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    public static Payment createNew(
            String clientPaymentId,
            String idempotencyKey,
            String debtorAccount,
            String creditorAccount,
            BigDecimal amount,
            String currency) {
        Instant now = Instant.now();
        return new Payment(
                UUID.randomUUID(),
                clientPaymentId,
                idempotencyKey,
                debtorAccount,
                creditorAccount,
                amount,
                currency,
                PaymentStatus.RECEIVED,
                null,
                now,
                now
        );
    }

    public void markValidated() {
        transitionTo(PaymentStatus.VALIDATED);
    }

    public void markPendingReview() {
        transitionTo(PaymentStatus.PENDING_REVIEW);
    }

    public void markApproved() {
        transitionTo(PaymentStatus.APPROVED);
    }

    public void markRejected(String reason) {
        this.failureReason = reason;
        transitionTo(PaymentStatus.REJECTED);
    }

    public void markExecuting() {
        transitionTo(PaymentStatus.EXECUTING);
    }

    public void markSettled() {
        transitionTo(PaymentStatus.SETTLED);
    }

    public void markFailed(String reason) {
        this.failureReason = reason;
        transitionTo(PaymentStatus.FAILED);
    }

    public void markCancelled() {
        transitionTo(PaymentStatus.CANCELLED);
    }

    private void transitionTo(PaymentStatus newStatus) {
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getClientPaymentId() { return clientPaymentId; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public String getDebtorAccount() { return debtorAccount; }
    public String getCreditorAccount() { return creditorAccount; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public PaymentStatus getStatus() { return status; }
    public String getFailureReason() { return failureReason; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
