# 8. Payment service

```java
package com.bank.payments.application;

import com.bank.payments.api.CreatePaymentRequest;
import com.bank.payments.application.port.*;
import com.bank.payments.domain.Payment;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Map;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final RiskScreeningService riskScreeningService;
    private final PaymentExecutionGateway paymentExecutionGateway;
    private final AuditService auditService;

    public PaymentService(
            PaymentRepository paymentRepository,
            RiskScreeningService riskScreeningService,
            PaymentExecutionGateway paymentExecutionGateway,
            AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.riskScreeningService = riskScreeningService;
        this.paymentExecutionGateway = paymentExecutionGateway;
        this.auditService = auditService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> createAndProcessPayment(request, idempotencyKey));
    }

    private Payment createAndProcessPayment(CreatePaymentRequest request, String idempotencyKey) {
        Payment payment = Payment.createNew(
                request.getClientPaymentId(),
                idempotencyKey,
                request.getDebtorAccount(),
                request.getCreditorAccount(),
                request.getAmount(),
                request.getCurrency()
        );

        payment = paymentRepository.save(payment);
        auditService.record("PAYMENT_CREATED", payment.getId(), Map.of(
                "clientPaymentId", payment.getClientPaymentId(),
                "amount", payment.getAmount(),
                "currency", payment.getCurrency()
        ));

        payment.markValidated();
        payment = paymentRepository.save(payment);
        auditService.record("PAYMENT_VALIDATED", payment.getId(), Map.of());

        RiskDecision decision = riskScreeningService.screen(payment);

        switch (decision) {
            case REJECT -> {
                payment.markRejected("Rejected by risk screening");
                payment = paymentRepository.save(payment);
                auditService.record("PAYMENT_REJECTED", payment.getId(), Map.of(
                        "reason", "Rejected by risk screening"
                ));
                return payment;
            }
            case REVIEW -> {
                payment.markPendingReview();
                payment = paymentRepository.save(payment);
                auditService.record("PAYMENT_PENDING_REVIEW", payment.getId(), Map.of());
                return payment;
            }
            case APPROVE -> {
                payment.markApproved();
                payment = paymentRepository.save(payment);
                auditService.record("PAYMENT_APPROVED", payment.getId(), Map.of());
            }
        }

        payment.markExecuting();
        payment = paymentRepository.save(payment);
        auditService.record("PAYMENT_EXECUTING", payment.getId(), Map.of());

        ExecutionResult result = paymentExecutionGateway.execute(payment);
        if (result.isSuccess()) {
            payment.markSettled();
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_SETTLED", payment.getId(), Map.of());
        } else {
            payment.markFailed(result.getFailureReason());
            payment = paymentRepository.save(payment);
            auditService.record("PAYMENT_FAILED", payment.getId(), Map.of(
                    "reason", result.getFailureReason()
            ));
        }

        return payment;
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
    }
}
```

