package com.bank.payments.infrastructure.persistence;

import com.bank.payments.application.port.PaymentRepository;
import com.bank.payments.domain.Payment;
import org.springframework.stereotype.Repository;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository implements PaymentRepository {

    private final Map<UUID, Payment> store = new ConcurrentHashMap<>();
    private final Map<String, UUID> idempotencyIndex = new ConcurrentHashMap<>();

    @Override
    public Payment save(Payment payment) {
        store.put(payment.getId(), payment);
        idempotencyIndex.put(payment.getIdempotencyKey(), payment.getId());
        return payment;
    }

    @Override
    public Optional<Payment> findById(UUID id) {
        return Optional.ofNullable(store.get(id));
    }

    @Override
    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        UUID id = idempotencyIndex.get(idempotencyKey);
        return id == null ? Optional.empty() : findById(id);
    }
}
