# 6. Validation Service

## `PaymentValidator.java`

```java
package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.ValidationException;
import java.util.Currency;
import org.springframework.stereotype.Component;

@Component
public class PaymentValidator {

    public void validate(CreatePaymentRequest request) {
        if (request.debtorAccount().equals(request.creditorAccount())) {
            throw new ValidationException("Debtor and creditor accounts must be different");
        }

        try {
            Currency.getInstance(request.currency());
        } catch (IllegalArgumentException ex) {
            throw new ValidationException("Invalid currency: " + request.currency());
        }

        if (request.clientReference().length() > 64) {
            throw new ValidationException("clientReference exceeds max length");
        }

        if (request.debtorAccount().length() > 34 || request.creditorAccount().length() > 34) {
            throw new ValidationException("Account number exceeds max length");
        }
    }
}
