# 10. Application Service

## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Money;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.repository.PaymentRepository;
import java.util.Currency;
import java.util.UUID;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidator validator;
    private final PaymentProcessor processor;
    private final AuditService auditService;
    private final IdempotencyService idempotencyService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            PaymentValidator validator,
            PaymentProcessor processor,
            AuditService auditService,
            IdempotencyService idempotencyService) {
        this.paymentRepository = paymentRepository;
        this.validator = validator;
        this.processor = processor;
        this.auditService = auditService;
        this.idempotencyService = idempotencyService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            String existingReference = idempotencyService.findPaymentReference(idempotencyKey);
            if (existingReference != null) {
                Payment existing = paymentRepository.findByPaymentReference(existingReference)
                        .orElseThrow(() -> new PaymentNotFoundException("Payment not found for idempotency key"));
                return toResponse(existing);
            }
        }

        validator.validate(request);

        Payment payment = new Payment();
        payment.setPaymentReference(generatePaymentReference());
        payment.setClientReference(request.clientReference());
        payment.setPaymentType(request.paymentType());
        payment.setMoney(new Money(request.amount(), Currency.getInstance(request.currency())));
        payment.setDebtorAccount(request.debtorAccount());
        payment.setCreditorAccount(request.creditorAccount());
        payment.setStatus(PaymentStatus.RECEIVED);

        payment = paymentRepository.save(payment);
        auditService.record(payment.getPaymentReference(), "PAYMENT_RECEIVED", "Payment created");

        payment.setStatus(PaymentStatus.VALIDATED);
        payment = paymentRepository.save(payment);
        auditService.record(payment.getPaymentReference(), "PAYMENT_VALIDATED", "Payment validated");

        processor.process(payment);
        payment = paymentRepository.save(payment);
        auditService.record(payment.getPaymentReference(), "PAYMENT_PROCESSED", "Payment processed to status " + payment.getStatus());

        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            try {
                idempotencyService.save(idempotencyKey, payment.getPaymentReference());
            } catch (DataIntegrityViolationException ex) {
                String existingReference = idempotencyService.findPaymentReference(idempotencyKey);
                if (existingReference != null) {
                    Payment existing = paymentRepository.findByPaymentReference(existingReference)
                            .orElseThrow(() -> new PaymentNotFoundException("Payment not found for idempotency key"));
                    return toResponse(existing);
                }
                throw ex;
            }
        }

        return toResponse(payment);
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(UUID id) {
        Payment payment = paymentRepository.findById(id)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + id));
        return toResponse(payment);
    }

    private String generatePaymentReference() {
        return "PAY-" + UUID.randomUUID().toString().replace("-", "").substring(0, 20);
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getPaymentReference(),
                payment.getClientReference(),
                payment.getPaymentType(),
                payment.getMoney().getAmount(),
                payment.getMoney().getCurrency().getCurrencyCode(),
                payment.getDebtorAccount(),
                payment.getCreditorAccount(),
                payment.getStatus(),
                payment.getFailureReason(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }
}
```

