package com.bank.payments.service;

import com.bank.payments.entity.AuditEventEntity;
import com.bank.payments.repository.AuditEventRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;

@Service
public class AuditService {

    private final AuditEventRepository auditEventRepository;
    private final ObjectMapper objectMapper;

    public AuditService(AuditEventRepository auditEventRepository, ObjectMapper objectMapper) {
        this.auditEventRepository = auditEventRepository;
        this.objectMapper = objectMapper;
    }

    public void record(UUID paymentId, String eventType, Map<String, Object> data) {
        AuditEventEntity event = new AuditEventEntity();
        event.setPaymentId(paymentId);
        event.setEventType(eventType);
        event.setCreatedAt(Instant.now());
        try {
            event.setEventData(objectMapper.writeValueAsString(data));
        } catch (JsonProcessingException e) {
            event.setEventData("{\"serializationError\":\"true\"}");
        }
        auditEventRepository.save(event);
    }
}
