## `PaymentApplicationService.java`

```java
package com.bank.payments.service;

import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.dto.CreatePaymentRequest;
import com.bank.payments.dto.PaymentResponse;
import com.bank.payments.entity.IdempotencyEntity;
import com.bank.payments.entity.PaymentEntity;
import com.bank.payments.exception.PaymentNotFoundException;
import com.bank.payments.repository.IdempotencyRepository;
import com.bank.payments.repository.PaymentRepository;
import jakarta.transaction.Transactional;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRepository idempotencyRepository;
    private final RiskService riskService;
    private final AccountService accountService;
    private final SettlementService settlementService;
    private final AuditService auditService;

    public PaymentApplicationService(
            PaymentRepository paymentRepository,
            IdempotencyRepository idempotencyRepository,
            RiskService riskService,
            AccountService accountService,
            SettlementService settlementService,
            AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRepository = idempotencyRepository;
        this.riskService = riskService;
        this.accountService = accountService;
        this.settlementService = settlementService;
        this.auditService = auditService;
    }

    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        idempotencyRepository.findByIdempotencyKey(idempotencyKey).ifPresent(existing -> {
            throw new DataIntegrityViolationException("Duplicate idempotency key");
        });

        UUID paymentId = UUID.randomUUID();
        Instant now = Instant.now();

        PaymentEntity payment = new PaymentEntity();
        payment.setPaymentId(paymentId);
        payment.setClientRequestId(request.getClientRequestId());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDebtorAccountId(request.getDebtorAccountId());
        payment.setCreditorAccountId(request.getCreditorAccountId());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setPaymentType(request.getPaymentType());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);
        payment.setCreatedAt(now);
        payment.setUpdatedAt(now);

        paymentRepository.save(payment);

        IdempotencyEntity idem = new IdempotencyEntity();
        idem.setIdempotencyKey(idempotencyKey);
        idem.setPaymentId(paymentId);
        idem.setCreatedAt(now);
        idempotencyRepository.save(idem);

        auditService.record(paymentId, "PAYMENT_RECEIVED", Map.of(
                "clientRequestId", request.getClientRequestId(),
                "amount", request.getAmount(),
                "currency", request.getCurrency()
        ));

        validateAndProcess(payment);

        return toResponse(payment);
    }

    @Transactional
    protected void validateAndProcess(PaymentEntity payment) {
        if (!accountService.isAccountActive(payment.getDebtorAccountId()) ||
            !accountService.isAccountActive(payment.getCreditorAccountId())) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setFailureCode("ACCOUNT_INVALID");
            payment.setFailureReason("One or more accounts are inactive");
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_REJECTED", Map.of(
                    "reason", payment.getFailureReason()
            ));
            return;
        }

        if (!accountService.hasSufficientFunds(payment.getDebtorAccountId(), payment.getAmount())) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setFailureCode("INSUFFICIENT_FUNDS");
            payment.setFailureReason("Insufficient funds");
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_REJECTED", Map.of(
                    "reason", payment.getFailureReason()
            ));
            return;
        }

        payment.setStatus(PaymentStatus.VALIDATED);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record(payment.getPaymentId(), "PAYMENT_VALIDATED", Map.of());

        if (riskService.requiresManualReview(
                payment.getDebtorAccountId(),
                payment.getCreditorAccountId(),
                payment.getAmount())) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_PENDING_REVIEW", Map.of(
                    "thresholdReview", true
            ));
            return;
        }

        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record(payment.getPaymentId(), "PAYMENT_PROCESSING", Map.of());

        boolean success = settlementService.execute(payment.getPaymentId());
        if (success) {
            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_COMPLETED", Map.of());
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureCode("SETTLEMENT_FAILED");
            payment.setFailureReason("Settlement processor returned failure");
            payment.setUpdatedAt(Instant.now());
            paymentRepository.save(payment);
            auditService.record(payment.getPaymentId(), "PAYMENT_FAILED", Map.of(
                    "reason", payment.getFailureReason()
            ));
        }
    }

    public PaymentResponse getPayment(UUID paymentId) {
        PaymentEntity payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(PaymentEntity payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setClientRequestId(payment.getClientRequestId());
        response.setStatus(payment.getStatus());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setReference(payment.getReference());
        response.setCreatedAt(payment.getCreatedAt());
        response.setUpdatedAt(payment.getUpdatedAt());
        return response;
    }
}
```

