# 8. Validation service

## `ValidationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.exception.ValidationException;
import org.springframework.stereotype.Service;

@Service
public class ValidationService {

    public void validate(CreatePaymentRequest request) {
        if (request.getSourceAccount().equals(request.getDestinationAccount())) {
            throw new ValidationException("sourceAccount and destinationAccount must differ");
        }

        if (!isSupportedCurrency(request.getCurrency())) {
            throw new ValidationException("unsupported currency: " + request.getCurrency());
        }

        if (request.getAmount().scale() > 2) {
            throw new ValidationException("amount cannot have more than 2 decimal places");
        }
    }

    private boolean isSupportedCurrency(String currency) {
        return currency.equals("USD") || currency.equals("EUR") || currency.equals("GBP");
    }
}
