package com.example.payments.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

public class Payment {
    private final UUID paymentId;
    private final String sourceAccount;
    private final String destinationAccount;
    private final Money money;
    private final PaymentType paymentType;
    private final String reference;
    private final String idempotencyKey;
    private PaymentStatus status;
    private final Instant createdAt;
    private Instant updatedAt;
    private String failureReason;

    public Payment(
            UUID paymentId,
            String sourceAccount,
            String destinationAccount,
            Money money,
            PaymentType paymentType,
            String reference,
            String idempotencyKey
    ) {
        this.paymentId = Objects.requireNonNull(paymentId);
        this.sourceAccount = Objects.requireNonNull(sourceAccount);
        this.destinationAccount = Objects.requireNonNull(destinationAccount);
        this.money = Objects.requireNonNull(money);
        this.paymentType = Objects.requireNonNull(paymentType);
        this.reference = reference;
        this.idempotencyKey = Objects.requireNonNull(idempotencyKey);
        this.status = PaymentStatus.INITIATED;
        this.createdAt = Instant.now();
        this.updatedAt = this.createdAt;
    }

    public UUID getPaymentId() {
        return paymentId;
    }

    public String getSourceAccount() {
        return sourceAccount;
    }

    public String getDestinationAccount() {
        return destinationAccount;
    }

    public Money getMoney() {
        return money;
    }

    public PaymentType getPaymentType() {
        return paymentType;
    }

    public String getReference() {
        return reference;
    }

    public String getIdempotencyKey() {
        return idempotencyKey;
    }

    public PaymentStatus getStatus() {
        return status;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public String getFailureReason() {
        return failureReason;
    }

    public void markValidated() {
        transitionTo(PaymentStatus.VALIDATED);
    }

    public void markAuthorized() {
        transitionTo(PaymentStatus.AUTHORIZED);
    }

    public void markCaptured() {
        transitionTo(PaymentStatus.CAPTURED);
    }

    public void markSettled() {
        transitionTo(PaymentStatus.SETTLED);
    }

    public void markCancelled() {
        transitionTo(PaymentStatus.CANCELLED);
    }

    public void markReversed() {
        transitionTo(PaymentStatus.REVERSED);
    }

    public void markFailed(String reason) {
        this.failureReason = reason;
        transitionTo(PaymentStatus.FAILED);
    }

    private void transitionTo(PaymentStatus newStatus) {
        this.status = newStatus;
        this.updatedAt = Instant.now();
    }
}
