package com.example.payments.repository;

import com.example.payments.domain.Payment;
import org.springframework.stereotype.Repository;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository implements PaymentRepository {

    private final Map<UUID, Payment> paymentsById = new ConcurrentHashMap<>();
    private final Map<String, UUID> idempotencyIndex = new ConcurrentHashMap<>();

    @Override
    public Payment save(Payment payment) {
        paymentsById.put(payment.getPaymentId(), payment);
        idempotencyIndex.put(payment.getIdempotencyKey(), payment.getPaymentId());
        return payment;
    }

    @Override
    public Optional<Payment> findById(UUID paymentId) {
        return Optional.ofNullable(paymentsById.get(paymentId));
    }

    @Override
    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        UUID paymentId = idempotencyIndex.get(idempotencyKey);
        if (paymentId == null) {
            return Optional.empty();
        }
        return findById(paymentId);
    }
}
