```java
package com.example.payments.service;

import com.example.payments.domain.Money;
import com.example.payments.domain.Payment;
import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.PaymentNotFoundException;
import com.example.payments.exception.ValidationException;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.util.Currency;
import java.util.UUID;

@Service
public class PaymentProcessingService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    public PaymentProcessingService(
            PaymentRepository paymentRepository,
            IdempotencyService idempotencyService,
            AuditService auditService
    ) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
    }

    public Payment createPayment(CreatePaymentRequest request) {
        return idempotencyService.findExistingPayment(request.getIdempotencyKey())
                .orElseGet(() -> createNewPayment(request));
    }

    private Payment createNewPayment(CreatePaymentRequest request) {
        validateBusinessRules(request);

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getSourceAccount(),
                request.getDestinationAccount(),
                new Money(request.getAmount(), Currency.getInstance(request.getCurrency())),
                request.getPaymentType(),
                request.getReference(),
                request.getIdempotencyKey()
        );

        payment.markValidated();
        payment.markAuthorized();
        payment.markCaptured();

        paymentRepository.save(payment);
        auditService.record("PAYMENT_CREATED", payment);

        return payment;
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + paymentId));
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.getSourceAccount().equals(request.getDestinationAccount())) {
            throw new ValidationException("Source and destination accounts must differ");
        }
        if (request.getReference() != null && request.getReference().length() > 140) {
            throw new ValidationException("Reference cannot exceed 140 characters");
        }
    }
}
