### `server.js`
```javascript
const express = require('express');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const payments = new Map();

function isPositiveNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function validatePayment(body) {
  const { amount, currency, sourceAccount, destinationAccount } = body;

  if (!isPositiveNumber(amount)) {
    return 'amount must be a positive number';
  }

  if (typeof currency !== 'string' || currency.length !== 3) {
    return 'currency must be a 3-letter code';
  }

  if (typeof sourceAccount !== 'string' || sourceAccount.trim().length < 4) {
    return 'sourceAccount is required';
  }

  if (typeof destinationAccount !== 'string' || destinationAccount.trim().length < 4) {
    return 'destinationAccount is required';
  }

  if (sourceAccount === destinationAccount) {
    return 'source and destination accounts must differ';
  }

  return null;
}

app.post('/payments', (req, res) => {
  const error = validatePayment(req.body);
  if (error) {
    return res.status(400).json({ error });
  }

  const id = crypto.randomUUID();
  const payment = {
    id,
    amount: req.body.amount,
    currency: req.body.currency.toUpperCase(),
    sourceAccount: req.body.sourceAccount,
    destinationAccount: req.body.destinationAccount,
    reference: req.body.reference || null,
    status: 'PENDING',
    createdAt: new Date().toISOString()
  };

  payments.set(id, payment);

  setTimeout(() => {
    const existing = payments.get(id);
    if (existing && existing.status === 'PENDING') {
      existing.status = 'SETTLED';
      existing.settledAt = new Date().toISOString();
      payments.set(id, existing);
    }
  }, 2000);

  res.status(201).json(payment);
});

app.get('/payments/:id', (req, res) => {
  const payment = payments.get(req.params.id);

  if (!payment) {
    return res.status(404).json({ error: 'payment not found' });
  }

  res.json(payment);
});

app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Mock payment service listening on port ${port}`);
});
```

