import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../../../common/errors/domain.error';
import {
  asEmailAddress,
  asUserId,
  type EmailAddress,
  type UserId
} from '../../../common/types/branded-types';
import { CORPORATE_DIRECTORY_CLIENT, type CorporateDirectoryClient } from '../infra/corporate-directory.client';
import { USER_REPOSITORY, type UserRepository } from './user.repository';
import { type User } from './user.entity';

@Injectable()
export class UserService {
  public constructor(
    @Inject(USER_REPOSITORY)
    private readonly userRepository: UserRepository,
    @Inject(CORPORATE_DIRECTORY_CLIENT)
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  public async createUser(input: {
    email: string;
    firstName: string;
    lastName: string;
  }): Promise<User> {
    const email: EmailAddress = asEmailAddress(input.email.toLowerCase());
    const existing = await this.userRepository.findByEmail(email);

    if (existing !== null) {
      throw new DomainError('USER_ALREADY_EXISTS', 'A user with this email already exists', {
        email: input.email
      });
    }

    const corporateProfile = await this.corporateDirectoryClient.findByEmail(email);

    const userId: UserId = asUserId(randomUUID());

    return this.userRepository.create({
      id: userId,
      email,
      firstName: input.firstName,
      lastName: input.lastName,
      externalId: corporateProfile?.externalId ?? null
    });
  }

  public async getUserById(id: string): Promise<User | null> {
    return this.userRepository.findById(asUserId(id));
  }
}
```

