import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { type EmailAddress } from '../../../common/types/branded-types';

export const CORPORATE_DIRECTORY_CLIENT = Symbol('CORPORATE_DIRECTORY_CLIENT');

export interface CorporateDirectoryProfile {
  readonly externalId: string;
  readonly email: string;
  readonly displayName: string;
}

export interface CorporateDirectoryClient {
  findByEmail(email: EmailAddress): Promise<CorporateDirectoryProfile | null>;
}

type DirectoryResponse = {
  externalId: string;
  email: string;
  displayName: string;
};

@Injectable()
export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  public constructor(
    private readonly httpService: HttpService,
    private readonly configService: ConfigService
  ) {}

  public async findByEmail(email: EmailAddress): Promise<CorporateDirectoryProfile | null> {
    const baseUrl = this.configService.getOrThrow<string>('CORPORATE_DIRECTORY_URL');
    const timeout = this.configService.getOrThrow<number>('CORPORATE_DIRECTORY_TIMEOUT_MS');

    const response = await firstValueFrom(
      this.httpService.get<DirectoryResponse | null>(`${baseUrl}/directory/users/by-email`, {
        params: { email },
        timeout
      })
    );

    if (response.data === null) {
      return null;
    }

    return {
      externalId: response.data.externalId,
      email: response.data.email,
      displayName: response.data.displayName
    };
  }
}
```

