# 15. Users controller

## src/modules/users/api/users.controller.ts

```ts
import {
  Body,
  Controller,
  Get,
  NotFoundException,
  Param,
  Post
} from '@nestjs/common';
import { ZodValidationPipe } from 'nestjs-zod';
import { CreateUserRequestDto } from './dto/create-user.request';
import { type UserResponseDto } from './dto/user.response';
import { UserService } from '../domain/user.service';

@Controller({
  path: 'v1/users'
})
export class UsersController {
  public constructor(private readonly userService: UserService) {}

  @Post()
  public async createUser(
    @Body(new ZodValidationPipe()) body: CreateUserRequestDto
  ): Promise<UserResponseDto> {
    const user = await this.userService.createUser(body);

    return {
      id: user.id,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      externalId: user.externalId,
      createdAt: user.createdAt.toISOString(),
      updatedAt: user.updatedAt.toISOString()
    };
  }

  @Get(':id')
  public async getUser(@Param('id') id: string): Promise<UserResponseDto> {
    const user = await this.userService.getUserById(id);

    if (user === null) {
      throw new NotFoundException('User not found');
    }

    return {
      id: user.id,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      externalId: user.externalId,
      createdAt: user.createdAt.toISOString(),
      updatedAt: user.updatedAt.toISOString()
    };
  }
}
