# `src/infrastructure/integrations/corporate-crm-client.ts`

Typed integration client for an existing corporate system.

```ts
import type { CorporateCrmPort } from "../../domain/ports.js";
import { IntegrationError } from "../../domain/errors.js";

export interface CorporateCrmClientDependencies {
  readonly baseUrl: string;
  readonly apiKey: string;
  readonly fetchFn?: typeof fetch;
}

interface CrmCreateCustomerRequest {
  readonly email: string;
  readonly firstName: string;
  readonly lastName: string;
}

interface CrmCreateCustomerResponse {
  readonly id: string;
}

export class CorporateCrmClient implements CorporateCrmPort {
  private readonly baseUrl: string;
  private readonly apiKey: string;
  private readonly fetchFn: typeof fetch;

  constructor(deps: CorporateCrmClientDependencies) {
    this.baseUrl = deps.baseUrl;
    this.apiKey = deps.apiKey;
    this.fetchFn = deps.fetchFn ?? fetch;
  }

  public async createCustomerRecord(
    input: CrmCreateCustomerRequest
  ): Promise<{ readonly crmId: string }> {
    const response = await this.fetchFn(`${this.baseUrl}/customers`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.apiKey
      },
      body: JSON.stringify(input)
    });

    if (!response.ok) {
      throw new IntegrationError(`CRM request failed with status ${response.status}`);
    }

    const data = (await response.json()) as Partial<CrmCreateCustomerResponse>;

    if (typeof data.id !== "string" || data.id.length === 0) {
      throw new IntegrationError("CRM response did not contain a valid id");
    }

    return { crmId: data.id };
  }
}
```

