# `src/application/customer-service.ts`

Business logic layer.

```ts
import { randomUUID } from "node:crypto";
import type { Customer } from "../domain/customer.js";
import type { CustomerRepository, CorporateCrmPort } from "../domain/ports.js";
import { CustomerNotFoundError } from "../domain/errors.js";

export interface CreateCustomerCommand {
  readonly email: string;
  readonly firstName: string;
  readonly lastName: string;
}

export interface CustomerServiceDependencies {
  readonly customerRepository: CustomerRepository;
  readonly corporateCrm: CorporateCrmPort;
}

export class CustomerService {
  private readonly customerRepository: CustomerRepository;
  private readonly corporateCrm: CorporateCrmPort;

  constructor(deps: CustomerServiceDependencies) {
    this.customerRepository = deps.customerRepository;
    this.corporateCrm = deps.corporateCrm;
  }

  public async createCustomer(command: CreateCustomerCommand): Promise<Customer> {
    const crmRecord = await this.corporateCrm.createCustomerRecord({
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName
    });

    const created = await this.customerRepository.create({
      id: randomUUID(),
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName
    });

    return {
      ...created,
      externalCrmId: crmRecord.crmId
    };
  }

  public async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.customerRepository.getById(id);

    if (customer === null) {
      throw new CustomerNotFoundError(id);
    }

    return customer;
  }

  public async listCustomers(): Promise<readonly Customer[]> {
    return this.customerRepository.list();
  }
}
```

