import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { createCustomerBodySchema } from "../schemas.js";
import type { CustomerService } from "../../../application/customer-service.js";

interface CustomerIdParams {
  readonly id: string;
}

export async function registerCustomerRoutes(
  fastify: FastifyInstance,
  deps: { readonly customerService: CustomerService }
): Promise<void> {
  fastify.post(
    "/customers",
    async (
      request: FastifyRequest<{ Body: unknown }>,
      reply: FastifyReply
    ) => {
      const body = createCustomerBodySchema.parse(request.body);

      const customer = await deps.customerService.createCustomer(body);

      reply.status(201).send(customer);
    }
  );

  fastify.get(
    "/customers/:id",
    async (
      request: FastifyRequest<{ Params: CustomerIdParams }>
    ) => {
      return deps.customerService.getCustomerById(request.params.id);
    }
  );

  fastify.get("/customers", async () => {
    return deps.customerService.listCustomers();
  });
}
