# Example: stronger integration client with timeout

If you want stricter production behavior, here is a better CRM client pattern:

```ts
import { IntegrationError } from "../../domain/errors.js";
import type { CorporateCrmPort } from "../../domain/ports.js";

export class CorporateCrmClientWithTimeout implements CorporateCrmPort {
  constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string,
    private readonly timeoutMs = 5000,
    private readonly fetchFn: typeof fetch = fetch
  ) {}

  public async createCustomerRecord(input: {
    readonly email: string;
    readonly firstName: string;
    readonly lastName: string;
  }): Promise<{ readonly crmId: string }> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), this.timeoutMs);

    try {
      const response = await this.fetchFn(`${this.baseUrl}/customers`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-api-key": this.apiKey
        },
        body: JSON.stringify(input),
        signal: controller.signal
      });

      if (!response.ok) {
        throw new IntegrationError(`CRM request failed with status ${response.status}`);
      }

      const data = (await response.json()) as { id?: unknown };

      if (typeof data.id !== "string" || data.id.length === 0) {
        throw new IntegrationError("CRM response did not contain a valid id");
      }

      return { crmId: data.id };
    } catch (error: unknown) {
      if (error instanceof Error && error.name === "AbortError") {
        throw new IntegrationError("CRM request timed out");
      }

      if (error instanceof IntegrationError) {
        throw error;
      }

      throw new IntegrationError("Unexpected CRM integration failure");
    } finally {
      clearTimeout(timeout);
    }
  }
}
```

