# Controller

## `src/users/users.controller.ts`

```ts
import {
  Body,
  Controller,
  Get,
  Param,
  Post,
  Req,
  UnauthorizedException,
  UseGuards
} from '@nestjs/common';
import type { Request } from 'express';
import { AuthGuard } from '../common/auth/auth.guard';
import { createUserSchema, type CreateUserDto } from './dto/create-user.dto';
import type { UserResponseDto } from './dto/user-response.dto';
import { UsersService } from './users.service';
import type { AuthenticatedPrincipal } from '../common/auth/corporate-jwt.service';

type RequestWithPrincipal = Request & {
  principal?: AuthenticatedPrincipal;
};

@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Post()
  @UseGuards(AuthGuard)
  async createUser(
    @Body() body: unknown,
    @Req() req: RequestWithPrincipal
  ): Promise<UserResponseDto> {
    if (req.principal === undefined) {
      throw new UnauthorizedException('Principal missing');
    }

    const parsed: CreateUserDto = createUserSchema.parse(body);
    const user = await this.usersService.createUser(parsed);
    return this.toResponse(user);
  }

  @Get(':id')
  @UseGuards(AuthGuard)
  async getUserById(@Param('id') id: string): Promise<UserResponseDto> {
    const user = await this.usersService.getUserById(id);
    return this.toResponse(user);
  }

  private toResponse(user: {
    id: string;
    employeeId: string;
    email: string;
    firstName: string;
    lastName: string;
    department: string | null;
    createdAt: Date;
    updatedAt: Date;
  }): UserResponseDto {
    return {
      id: user.id,
      employeeId: user.employeeId,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      department: user.department,
      createdAt: user.createdAt.toISOString(),
      updatedAt: user.updatedAt.toISOString()
    };
  }
}
