# `src/middleware/auth.ts`

This is a placeholder for corporate auth integration. In a real environment, this would validate JWTs, mTLS identity, SSO headers, or API gateway claims.

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { UnauthorizedError } from "../core/errors.js";
import { AuthenticatedUser, UserId } from "../core/types.js";

declare module "fastify" {
  interface FastifyRequest {
    user?: AuthenticatedUser;
  }
}

export async function authMiddleware(
  request: FastifyRequest,
  _reply: FastifyReply
): Promise<void> {
  const userIdHeader = request.headers["x-user-id"];
  const rolesHeader = request.headers["x-roles"];
  const emailHeader = request.headers["x-user-email"];

  if (
    typeof userIdHeader !== "string" ||
    typeof rolesHeader !== "string" ||
    typeof emailHeader !== "string"
  ) {
    throw new UnauthorizedError("Missing required authentication headers");
  }

  request.user = {
    userId: userIdHeader as UserId,
    roles: rolesHeader.split(",").map((role) => role.trim()),
    email: emailHeader
  };
}
```

