import axios, { AxiosInstance } from "axios";
import { env } from "../config/env.js";
import { IntegrationError } from "../core/errors.js";

export interface HrEmployeeRecord {
  employeeNumber: string;
  firstName: string;
  lastName: string;
  department: string;
  active: boolean;
