export class HrSystemClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: env.HR_SYSTEM_BASE_URL,
      timeout: 5000,
      headers: {
        "x-api-key": env.HR_SYSTEM_API_KEY,
        "content-type": "application/json"
      }
    });
  }

  async fetchEmployeeByNumber(employeeNumber: string): Promise<HrEmployeeRecord | null> {
    try {
      const response = await this.http.get<HrEmployeeRecord | null>(
        `/employees/${encodeURIComponent(employeeNumber)}`
      );
      return response.data;
    } catch (error: unknown) {
      throw new IntegrationError("Failed to fetch employee from HR system", error);
    }
  }
}
