# `src/modules/employee/employee.repository.ts`

In a real system this would use PostgreSQL, SQL Server, Oracle, etc. Here it is an interface plus in-memory implementation for demonstration.

```ts
import { Employee } from "./employee.types.js";

export interface EmployeeRepository {
  findByEmployeeNumber(employeeNumber: string): Promise<Employee | null>;
  save(employee: Employee): Promise<void>;
}

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly store = new Map<string, Employee>();

  async findByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    return this.store.get(employeeNumber) ?? null;
  }

  async save(employee: Employee): Promise<void> {
    this.store.set(employee.employeeNumber, employee);
  }
}
```

