# `src/modules/employee/employee.service.ts`

```ts
import { v4 as uuidv4 } from "uuid";
import { NotFoundError } from "../../core/errors.js";
import { EmployeeId } from "../../core/types.js";
import { HrSystemClient } from "../../integrations/hr-system.client.js";
import { IdentityClient } from "../../integrations/identity.client.js";
import { EmployeeRepository } from "./employee.repository.js";
import { Employee } from "./employee.types.js";

export class EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly hrClient: HrSystemClient,
    private readonly identityClient: IdentityClient
  ) {}

  async getEmployeeByNumber(employeeNumber: string): Promise<Employee> {
    const existing = await this.repository.findByEmployeeNumber(employeeNumber);
    if (existing !== null) {
      return existing;
    }

    const hrRecord = await this.hrClient.fetchEmployeeByNumber(employeeNumber);
    if (hrRecord === null) {
      throw new NotFoundError(`Employee ${employeeNumber} not found`);
    }

    const identityProfile = await this.identityClient.fetchProfile(employeeNumber);

    const employee: Employee = {
      id: uuidv4() as EmployeeId,
      employeeNumber: hrRecord.employeeNumber,
      firstName: hrRecord.firstName,
      lastName: hrRecord.lastName,
      department: hrRecord.department,
      active: hrRecord.active,
      email: identityProfile?.email ?? null,
      managerEmail: identityProfile?.managerEmail ?? null
    };

    await this.repository.save(employee);
    return employee;
  }
}
```

