# `src/modules/employee/employee.controller.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { ValidationError } from "../../core/errors.js";
import {
  employeeNumberParamsSchema,
  employeeResponseSchema
} from "./employee.schemas.js";
import { EmployeeService } from "./employee.service.js";

export class EmployeeController {
  constructor(private readonly employeeService: EmployeeService) {}

  getEmployeeByNumber = async (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> => {
    const parsedParams = employeeNumberParamsSchema.safeParse(request.params);
    if (!parsedParams.success) {
      throw new ValidationError("Invalid employee number", parsedParams.error.format());
    }

    const employee = await this.employeeService.getEmployeeByNumber(
      parsedParams.data.employeeNumber
    );

    const responseBody = employeeResponseSchema.parse(employee);
    reply.status(200).send(responseBody);
  };
}
```

