# `src/app.ts`

```ts
import Fastify, { FastifyInstance } from "fastify";
import { logger } from "./core/logger.js";
import { AppError } from "./core/errors.js";
import { requestContextMiddleware } from "./middleware/request-context.js";
import { registerRoutes } from "./routes/index.js";
import { InMemoryEmployeeRepository } from "./modules/employee/employee.repository.js";
import { HrSystemClient } from "./integrations/hr-system.client.js";
import { IdentityClient } from "./integrations/identity.client.js";
import { EmployeeService } from "./modules/employee/employee.service.js";
import { EmployeeController } from "./modules/employee/employee.controller.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({
    logger
  });

  app.addHook("onRequest", requestContextMiddleware);

  app.addHook("onResponse", async (request, reply) => {
    request.log.info(
      {
        correlationId: request.correlationId,
        statusCode: reply.statusCode,
        method: request.method,
        url: request.url
      },
      "request completed"
    );
  });

  const employeeRepository = new InMemoryEmployeeRepository();
  const hrClient = new HrSystemClient();
  const identityClient = new IdentityClient();
  const employeeService = new EmployeeService(
    employeeRepository,
    hrClient,
    identityClient
  );
  const employeeController = new EmployeeController(employeeService);

  void registerRoutes(app, employeeController);

  app.setErrorHandler((error, request, reply) => {
    request.log.error(
      {
        err: error,
        correlationId: request.correlationId
      },
      "request failed"
    );

    if (error instanceof AppError) {
      reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message,
          details: error.details ?? null
        }
      });
      return;
    }

    reply.status(500).send({
      error: {
        code: "INTERNAL_SERVER_ERROR",
        message: "An unexpected error occurred"
      }
    });
  });

  return app;
}
```

