export interface CorporateClient {
  getCustomerProfile(corporateId: string, authToken: string): Promise<CorporateCustomerProfile | null>;
}

declare module "fastify" {
  interface FastifyInstance {
    corporateClient: CorporateClient;
  }
}

const corporateClientPlugin = fp(async (app: FastifyInstance) => {
  const httpClient: AxiosInstance = axios.create({
    baseURL: env.CORPORATE_API_BASE_URL,
    timeout: env.CORPORATE_API_TIMEOUT_MS,
    headers: {
      "Content-Type": "application/json"
    }
  });

  const corporateClient: CorporateClient = {
    async getCustomerProfile(corporateId: string, authToken: string): Promise<CorporateCustomerProfile | null> {
      try {
        const response = await httpClient.get<CorporateCustomerProfile>(`/customers/${encodeURIComponent(corporateId)}`, {
          headers: {
            Authorization: `Bearer ${authToken}`
          }
        });

        return response.data;
      } catch (error: unknown) {
        app.log.error({ error, corporateId }, "Failed to fetch corporate customer profile");
        return null;
      }
    }
  };

  app.decorate("corporateClient", corporateClient);
});

export default corporateClientPlugin;
