# 11. Service layer: `src/modules/customer/customer.service.ts`

Business logic belongs here.

```ts
import type { Customer } from "@prisma/client";
import type { CorporateClient } from "../../plugins/corporateClient.js";
import type { AuthenticatedUser } from "../../plugins/auth.js";
import { ConflictError, ForbiddenError, NotFoundError } from "../../shared/errors.js";
import type { CustomerRepository } from "./customer.repository.js";

export interface CustomerDetails {
  id: string;
  externalCorpId: string;
  email: string;
  firstName: string;
  lastName: string;
  createdAt: Date;
  updatedAt: Date;
  corporateStatus: "ACTIVE" | "INACTIVE" | "SUSPENDED" | null;
}

export class CustomerService {
  public constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateClient: CorporateClient
  ) {}

  public async getCustomerById(id: string, user: AuthenticatedUser): Promise<CustomerDetails> {
    if (!user.roles.includes("customer:read")) {
      throw new ForbiddenError("User does not have permission to read customers");
    }

    const customer = await this.repository.findById(id);

    if (customer === null) {
      throw new NotFoundError(`Customer not found: ${id}`);
    }

    const corporateProfile = await this.corporateClient.getCustomerProfile(customer.externalCorpId, user.token);

    return this.toDetails(customer, corporateProfile?.status ?? null);
  }

  public async createCustomer(
    input: {
      externalCorpId: string;
      email: string;
      firstName: string;
      lastName: string;
    },
    user: AuthenticatedUser
  ): Promise<CustomerDetails> {
    if (!user.roles.includes("customer:write")) {
      throw new ForbiddenError("User does not have permission to create customers");
    }

    const existing = await this.repository.findByEmail(input.email);

    if (existing !== null) {
      throw new ConflictError(`Customer with email already exists: ${input.email}`);
    }

    const created = await this.repository.create(input);

    return this.toDetails(created, null);
  }

  private toDetails(
    customer: Customer,
    corporateStatus: "ACTIVE" | "INACTIVE" | "SUSPENDED" | null
  ): CustomerDetails {
    return {
      id: customer.id,
      externalCorpId: customer.externalCorpId,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      createdAt: customer.createdAt,
      updatedAt: customer.updatedAt,
      corporateStatus
    };
  }
}
```

