# 12. Controller layer: `src/modules/customer/customer.controller.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import type {
  CreateCustomerBody,
  CustomerIdParams
} from "./customer.schemas.js";
import { CustomerService } from "./customer.service.js";

export class CustomerController {
  public constructor(private readonly service: CustomerService) {}

  public getById = async (
    request: FastifyRequest<{ Params: CustomerIdParams }>,
    reply: FastifyReply
  ): Promise<void> => {
    const user = request.user;
    if (!user) {
      reply.code(401).send({ error: "Unauthorized" });
      return;
    }

    const customer = await this.service.getCustomerById(request.params.id, user);

    reply.code(200).send({
      ...customer,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });
  };

  public create = async (
    request: FastifyRequest<{ Body: CreateCustomerBody }>,
    reply: FastifyReply
  ): Promise<void> => {
    const user = request.user;
    if (!user) {
      reply.code(401).send({ error: "Unauthorized" });
      return;
    }

    const customer = await this.service.createCustomer(request.body, user);

    reply.code(201).send({
      ...customer,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });
  };
}
