import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { PrismaCustomerRepository } from "./customer.repository.js";
import { CustomerService } from "./customer.service.js";
import { CustomerController } from "./customer.controller.js";
import {
  createCustomerBodySchema,
  customerIdParamsSchema,
  customerResponseSchema
} from "./customer.schemas.js";

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const repository = new PrismaCustomerRepository(app.prisma);
  const service = new CustomerService(repository, app.corporateClient);
  const controller = new CustomerController(service);

  app.get(
    "/customers/:id",
    {
      schema: {
        params: customerIdParamsSchema,
        response: {
          200: customerResponseSchema
        }
      }
    },
    controller.getById
  );

  app.post(
    "/customers",
    {
      schema: {
        body: createCustomerBodySchema,
        response: {
          201: customerResponseSchema
        }
      }
    },
    controller.create
  );
}
