# 15. App bootstrap: `src/app.ts`

Global error handling, plugin registration, routes.

```ts
import Fastify, { type FastifyInstance } from "fastify";
import sensible from "@fastify/sensible";
import prismaPlugin from "./plugins/prisma.js";
import corporateClientPlugin from "./plugins/corporateClient.js";
import authPlugin from "./plugins/auth.js";
import { customerRoutes } from "./modules/customer/customer.routes.js";
import { healthRoutes } from "./routes/health.js";
import { ConflictError, ForbiddenError, NotFoundError } from "./shared/errors.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({
    logger: {
      level: "info"
    }
  });

  app.register(sensible);
  app.register(prismaPlugin);
  app.register(corporateClientPlugin);
  app.register(authPlugin);

  app.setErrorHandler((error, request, reply) => {
    request.log.error({ err: error }, "Request failed");

    if (error instanceof NotFoundError) {
      reply.code(404).send({ error: error.code, message: error.message });
      return;
    }

    if (error instanceof ConflictError) {
      reply.code(409).send({ error: error.code, message: error.message });
      return;
    }

    if (error instanceof ForbiddenError) {
      reply.code(403).send({ error: error.code, message: error.message });
      return;
    }

    reply.code(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  app.register(healthRoutes, { prefix: "/api" });
  app.register(customerRoutes, { prefix: "/api" });

  return app;
}
```

