export interface AppConfig {
  port: number;
  corporateApiBaseUrl: string;
  corporateApiToken: string;
}

export const configuration = (): AppConfig => ({
  port: parseInt(process.env.PORT ?? '3000', 10),
  corporateApiBaseUrl: process.env.CORPORATE_API_BASE_URL ?? '',
  corporateApiToken: process.env.CORPORATE_API_TOKEN ?? ''
});

export function validateEnv(env: Record<string, unknown>): AppConfig {
  const port = Number(env.PORT ?? 3000);
  const corporateApiBaseUrl = String(env.CORPORATE_API_BASE_URL ?? '');
  const corporateApiToken = String(env.CORPORATE_API_TOKEN ?? '');

  if (!Number.isInteger(port) || port <= 0) {
    throw new Error('Invalid PORT');
  }

  if (corporateApiBaseUrl.length === 0) {
    throw new Error('CORPORATE_API_BASE_URL is required');
  }

  if (corporateApiToken.length === 0) {
    throw new Error('CORPORATE_API_TOKEN is required');
  }

  return {
    port,
    corporateApiBaseUrl,
    corporateApiToken
  };
}
