  isAllowed: boolean;
}

@Injectable()
export class CorporateDirectoryClient {
  constructor(
    private readonly httpService: HttpService,
    private readonly configService: ConfigService
  ) {}

  async validateCustomerEmail(email: string): Promise<boolean> {
    const baseUrl = this.configService.get<string>('corporateApiBaseUrl');
    const token = this.configService.get<string>('corporateApiToken');

    if (!baseUrl || !token) {
      throw new Error('Corporate API configuration missing');
    }

    const response = await firstValueFrom(
      this.httpService.get<CorporateDirectoryResponse>(
        `${baseUrl}/directory/validate-email`,
        {
          params: { email },
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      )
    );

    return response.data.isAllowed;
  }
}
