import {
  BadRequestException,
  Inject,
  Injectable,
  NotFoundException
} from '@nestjs/common';
import { randomUUID } from 'crypto';
import { Customer } from './domain/customer';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CorporateDirectoryClient } from './corporate-directory.client';
import { CustomerRepository } from './customer.repository';

@Injectable()
export class CustomerService {
  constructor(
    @Inject('CustomerRepository')
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async createCustomer(dto: CreateCustomerDto): Promise<Customer> {
    const isAllowed = await this.corporateDirectoryClient.validateCustomerEmail(dto.email);

    if (!isAllowed) {
      throw new BadRequestException('Email is not allowed by corporate directory');
    }

    const customer: Customer = {
      id: randomUUID(),
      email: dto.email,
      firstName: dto.firstName,
      lastName: dto.lastName,
      active: dto.active,
      createdAt: new Date().toISOString()
    };

    return this.customerRepository.create(customer);
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);

    if (!customer) {
      throw new NotFoundException(`Customer with id ${id} not found`);
    }

    return customer;
  }
}
