# 11. Auth plugin: `src/plugins/auth.ts`

In a real enterprise, this would validate JWTs against corporate IdP JWKS. Below is a typed stub pattern.

```ts
import fp from "fastify-plugin";
import type { FastifyRequest } from "fastify";
import { UnauthorizedError } from "../core/errors.js";
import type { AuthenticatedUser } from "../core/types.js";

declare module "fastify" {
  interface FastifyRequest {
    user: AuthenticatedUser;
  }

  interface FastifyInstance {
    authenticate(request: FastifyRequest): Promise<void>;
  }
}

function parseBearerToken(authHeader: string | undefined): string {
  if (!authHeader) {
    throw new UnauthorizedError("Missing Authorization header");
  }

  const [scheme, token] = authHeader.split(" ");

  if (scheme !== "Bearer" || !token) {
    throw new UnauthorizedError("Invalid Authorization header");
  }

  return token;
}

async function validateCorporateJwt(token: string): Promise<AuthenticatedUser> {
  // Replace with real OIDC/JWKS validation.
  // Example only: token format "userId|email|role1,role2"
  const parts = token.split("|");
  if (parts.length < 3) {
    throw new UnauthorizedError("Invalid token");
  }

  const [userId, email, rolesRaw] = parts;
  return {
    userId,
    email,
    roles: rolesRaw.split(",")
  };
}

export default fp(async (fastify) => {
  fastify.decorate("authenticate", async (request: FastifyRequest) => {
    const token = parseBearerToken(request.headers.authorization);
    const user = await validateCorporateJwt(token);
    request.user = user;
  });
});
```

