import axios, { AxiosError, type AxiosInstance } from "axios";
import { env } from "../config/env.js";
import { IntegrationError } from "../core/errors.js";

export interface ErpOrderSyncRequest {
  readonly orderId: string;
  readonly customerId: string;
  readonly amountCents: number;
  readonly currency: string;
}

export interface ErpOrderSyncResponse {
  readonly erpDocumentId: string;
  readonly syncedAt: string;
}

export class CorporateErpClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: env.ERP_BASE_URL,
      timeout: 5000,
      headers: {
        "x-api-key": env.ERP_API_KEY,
        "content-type": "application/json"
      }
    });
  }

  async syncOrder(payload: ErpOrderSyncRequest): Promise<ErpOrderSyncResponse> {
    try {
      const response = await this.http.post<ErpOrderSyncResponse>("/orders/sync", payload);
      return response.data;
    } catch (error: unknown) {
      const err = error as AxiosError;
      throw new IntegrationError("Failed to sync order to ERP", {
        status: err.response?.status,
        data: err.response?.data
      });
    }
  }
}
