# 17. Service layer: `src/modules/orders/order.service.ts`

```ts
import { ConflictError } from "../../core/errors.js";
import type { AuthenticatedUser } from "../../core/types.js";
import { CorporateErpClient } from "../../integrations/corporate-erp.client.js";
import { EventBusPublisher } from "../../integrations/event-bus.publisher.js";
import type { CreateOrderBody } from "./order.schemas.js";
import { OrderRepository } from "./order.repository.js";
import type { Order } from "@prisma/client";

export class OrderService {
  constructor(
    private readonly repository: OrderRepository,
    private readonly erpClient: CorporateErpClient,
    private readonly eventPublisher: EventBusPublisher
  ) {}

  async createOrder(input: CreateOrderBody, user: AuthenticatedUser): Promise<Order> {
    const existing = await this.repository.findByExternalRef(input.externalRef);
    if (existing) {
      throw new ConflictError("Order with this externalRef already exists", {
        externalRef: input.externalRef
      });
    }

    const order = await this.repository.create({
      externalRef: input.externalRef,
      customerId: input.customerId,
      description: input.description,
      amountCents: input.amountCents,
      currency: input.currency,
      createdBy: user.userId
    });

    await this.erpClient.syncOrder({
      orderId: order.id,
      customerId: order.customerId,
      amountCents: order.amountCents,
      currency: order.currency
    });

    const synced = await this.repository.updateStatus(order.id, "SYNCED");

    await this.eventPublisher.publishOrderCreated({
      type: "order.created",
      orderId: synced.id,
      customerId: synced.customerId,
      createdBy: synced.createdBy,
      occurredAt: new Date().toISOString()
    });

    return synced;
  }
}
```

