    .string()
    .optional()
    .transform((v) => v === "true"),
  AUTH_ENABLED: z
    .string()
    .optional()
    .transform((v) => v !== "false")
});

const parsed = envSchema.safeParse(process.env);

if (!parsed.success) {
  console.error("Invalid environment configuration:", parsed.error.format());
  process.exit(1);
}

export const env = parsed.data;
export type Env = typeof env;
