# 11. Corporate integration client

This simulates calling an internal enterprise system.

## `src/infrastructure/integrations/corporate-directory.client.ts`

```ts
export interface CorporateDirectoryRecord {
  employeeId: string;
  email: string;
  department: string;
  active: boolean;
}

export interface CorporateDirectoryClient {
  lookupByEmail(email: string): Promise<CorporateDirectoryRecord | null>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  constructor(private readonly baseUrl: string) {}

  async lookupByEmail(email: string): Promise<CorporateDirectoryRecord | null> {
    const response = await fetch(
      `${this.baseUrl}/directory/users?email=${encodeURIComponent(email)}`,
      {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          "X-Corporate-System": "enterprise-microservice"
        }
      }
    );

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate directory lookup failed with ${response.status}`);
    }

    const data = (await response.json()) as CorporateDirectoryRecord;
    return data;
  }
}
```

