# 13. Service layer

## `src/domain/customer/customer.service.ts`

```ts
import type { Customer, CreateCustomerInput } from "./customer.types.js";
import type { CustomerRepository } from "./customer.repository.js";
import type { CorporateDirectoryClient } from "../../infrastructure/integrations/corporate-directory.client.js";
import type { EventPublisher } from "../../infrastructure/messaging/event.publisher.js";
import { ValidationError, NotFoundError } from "../../shared/errors.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient,
    private readonly eventPublisher: EventPublisher
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new ValidationError("Customer with this email already exists", {
        email: input.email
      });
    }

    const directoryRecord = await this.corporateDirectoryClient.lookupByEmail(input.email);

    const customer = await this.repository.create({
      ...input,
      externalRef: input.externalRef ?? directoryRecord?.employeeId
    });

    await this.eventPublisher.publish({
      type: "customer.created",
      occurredAt: new Date().toISOString(),
      payload: {
        customerId: customer.id,
        email: customer.email
      }
    });

    return customer;
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError("Customer not found", { id });
    }
    return customer;
  }
}
```

