# 14. Auth middleware hook

In a real enterprise environment, this would validate JWTs, mTLS headers, API gateway headers, or call internal IAM.

## `src/infrastructure/auth/auth.middleware.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { env } from "../../config/env.js";
import { UnauthorizedError } from "../../shared/errors.js";

export interface AuthenticatedUser {
  userId: string;
  email: string;
  roles: string[];
}

declare module "fastify" {
  interface FastifyRequest {
    user?: AuthenticatedUser;
  }
}

export async function authMiddleware(
  request: FastifyRequest,
  _reply: FastifyReply
): Promise<void> {
  if (!env.AUTH_ENABLED) {
    request.user = {
      userId: "dev-user",
      email: "dev@example.com",
      roles: ["developer"]
    };
    return;
  }

  const authHeader = request.headers.authorization;
  if (!authHeader?.startsWith("Bearer ")) {
    throw new UnauthorizedError();
  }

  const token = authHeader.slice("Bearer ".length).trim();

  if (token.length === 0) {
    throw new UnauthorizedError();
  }

  request.user = {
    userId: "corporate-user-123",
    email: "user@corp.example",
    roles: ["customer:read", "customer:write"]
  };
}
```

