```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { createCustomerSchema } from "./customer.types.js";
import type { CustomerService } from "./customer.service.js";
import { authMiddleware } from "../../infrastructure/auth/auth.middleware.js";

const paramsSchema = z.object({
  id: z.string().uuid()
});

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.addHook("preHandler", authMiddleware);

  app.post("/customers", async (request, reply) => {
    const input = createCustomerSchema.parse(request.body);
    const customer = await customerService.createCustomer(input);
    return reply.status(201).send(customer);
  });

  app.get("/customers/:id", async (request, reply) => {
    const params = paramsSchema.parse(request.params);
    const customer = await customerService.getCustomerById(params.id);
    return reply.status(200).send(customer);
  });
}
