# 18. App assembly

## `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { logger } from "./config/logger.js";
import { env } from "./config/env.js";
import { prisma } from "./infrastructure/db/prisma.js";
import { PrismaCustomerRepository } from "./domain/customer/customer.repository.js";
import { CustomerService } from "./domain/customer/customer.service.js";
import { HttpCorporateDirectoryClient } from "./infrastructure/integrations/corporate-directory.client.js";
import {
  ConsoleEventPublisher,
  NoopEventPublisher
} from "./infrastructure/messaging/event.publisher.js";
import { registerCustomerRoutes } from "./domain/customer/customer.controller.js";
import { registerErrorHandler } from "./plugins/error-handler.js";
import { registerHealthRoutes } from "./plugins/health.js";

export async function buildApp() {
  const app = Fastify({
    logger
  });

  await app.register(sensible);

  const customerRepository = new PrismaCustomerRepository(prisma);
  const corporateDirectoryClient = new HttpCorporateDirectoryClient(
    env.CORPORATE_DIRECTORY_BASE_URL
  );
  const eventPublisher = env.EVENT_BUS_ENABLED
    ? new ConsoleEventPublisher()
    : new NoopEventPublisher();

  const customerService = new CustomerService(
    customerRepository,
    corporateDirectoryClient,
    eventPublisher
  );

  await registerErrorHandler(app);
  await registerHealthRoutes(app);
  await registerCustomerRoutes(app, customerService);

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
```

