## `src/infrastructure/http/request-context.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { v4 as uuidv4 } from "uuid";

export interface RequestContext {
  readonly correlationId: string;
}

declare module "fastify" {
  interface FastifyRequest {
    requestContext: RequestContext;
  }
}

export async function attachRequestContext(
  request: FastifyRequest,
  _reply: FastifyReply
): Promise<void> {
  const incomingCorrelationId = request.headers["x-correlation-id"];
  const correlationId =
    typeof incomingCorrelationId === "string" && incomingCorrelationId.length > 0
      ? incomingCorrelationId
      : uuidv4();

  request.requestContext = {
    correlationId
  };
}
```

