Initial implementation can be in-memory for bootstrapping and testing.

```ts
import {
  Customer,
  CustomerId,
  CustomerRepository
} from "../../domain/customer/customer.types.js";

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly customers = new Map<CustomerId, Customer>();

  public async create(input: Customer): Promise<Customer> {
    this.customers.set(input.id, input);
    return input;
  }

  public async findById(id: CustomerId): Promise<Customer | null> {
    return this.customers.get(id) ?? null;
  }

  public async findByEmployeeNumber(employeeNumber: string): Promise<Customer | null> {
    for (const customer of this.customers.values()) {
      if (customer.employeeNumber === employeeNumber) {
        return customer;
      }
    }
    return null;
  }

  public async list(): Promise<readonly Customer[]> {
    return [...this.customers.values()];
  }
}
```

