## `src/domain/customer/customer.controller.ts`

```ts
import { FastifyInstance } from "fastify";
import {
  createCustomerInputSchema,
  customerIdSchema
} from "./customer.types.js";
import { CustomerService } from "./customer.service.js";
import { ValidationError, NotFoundError } from "../../shared/errors.js";

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.post("/customers", async (request, reply) => {
    const parsedBody = createCustomerInputSchema.safeParse(request.body);

    if (!parsedBody.success) {
      throw new ValidationError(parsedBody.error.message);
    }

    const result = await customerService.createCustomer(parsedBody.data);

    if (!result.ok) {
      if (result.error.type === "DUPLICATE_EMPLOYEE_NUMBER") {
        reply.status(409).send({
          code: "DUPLICATE_EMPLOYEE_NUMBER",
          message: `Customer with employee number '${result.error.employeeNumber}' already exists`,
          correlationId: request.requestContext.correlationId
        });
        return;
      }
    }

    reply.status(201).send(result.value);
  });

  app.get("/customers/:id", async (request) => {
    const parsedId = customerIdSchema.safeParse((request.params as { id?: unknown }).id);

    if (!parsedId.success) {
      throw new ValidationError("Invalid customer id");
    }

    const customer = await customerService.getCustomerById(parsedId.data);

    if (customer === null) {
      throw new NotFoundError(`Customer '${parsedId.data}' not found`);
    }

    return customer;
  });

  app.get("/customers", async () => {
    return customerService.listCustomers();
  });
}
```

