# 11. Example enhancement: validate against corporate directory before create

In many enterprises, internal records must align with authoritative systems. Here’s how to evolve the service.

Update `CustomerService` to depend on `CorporateDirectoryClient`.

## Revised `customer.service.ts`

```ts
import { v4 as uuidv4 } from "uuid";
import {
  CreateCustomerInput,
  Customer,
  CustomerRepository
} from "./customer.types.js";
import { err, ok, Result } from "../../shared/result.js";
import { CorporateDirectoryClient } from "../../infrastructure/integrations/corporate-directory.client.js";

export type CreateCustomerError =
  | { readonly type: "DUPLICATE_EMPLOYEE_NUMBER"; readonly employeeNumber: string }
  | { readonly type: "EMPLOYEE_NOT_FOUND"; readonly employeeNumber: string }
  | { readonly type: "EMPLOYEE_INACTIVE"; readonly employeeNumber: string };

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  public async createCustomer(
    input: CreateCustomerInput
  ): Promise<Result<Customer, CreateCustomerError>> {
    const existing = await this.customerRepository.findByEmployeeNumber(
      input.employeeNumber
    );

    if (existing !== null) {
      return err({
        type: "DUPLICATE_EMPLOYEE_NUMBER",
        employeeNumber: input.employeeNumber
      });
    }

    const employee = await this.corporateDirectoryClient.getEmployeeByNumber(
      input.employeeNumber
    );

    if (employee === null) {
      return err({
        type: "EMPLOYEE_NOT_FOUND",
        employeeNumber: input.employeeNumber
      });
    }

    if (!employee.active) {
      return err({
        type: "EMPLOYEE_INACTIVE",
        employeeNumber: input.employeeNumber
      });
    }

    const now = new Date().toISOString();

    const customer: Customer = {
      id: uuidv4(),
      employeeNumber: employee.employeeNumber,
      email: employee.email,
      firstName: employee.firstName,
      lastName: employee.lastName,
      department: employee.department,
      createdAt: now,
      updatedAt: now
    };

    const created = await this.customerRepository.create(customer);
    return ok(created);
  }

  public async getCustomerById(id: string): Promise<Customer | null> {
    return this.customerRepository.findById(id);
  }

  public async listCustomers(): Promise<readonly Customer[]> {
    return this.customerRepository.list();
  }
}
```

