# 9. Service layer

## `src/domain/services/customer-service.ts`

```ts
import type { Customer, CreateCustomerInput } from "../models/customer.js";
import type { CustomerRepository } from "../ports/customer-repository.js";
import type { CorporateCrmClient } from "../ports/corporate-crm-client.js";
import { ValidationError } from "../../shared/errors.js";

export class CustomerService {
  public constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  public async getCustomerById(id: string): Promise<Customer | null> {
    return this.repository.findById(id);
  }

  public async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new ValidationError("Customer with this email already exists", {
        email: input.email
      });
    }

    const crmCustomer = await this.crmClient.createCustomer(input);
    return this.repository.create({
      email: crmCustomer.email,
      firstName: crmCustomer.firstName,
      lastName: crmCustomer.lastName
    });
  }
}
```

Note: in a real enterprise system, you may:
- persist the CRM external ID
- use distributed transactions or outbox patterns
- support idempotency keys
- emit domain events

