# 10. Repository implementation

## `src/infrastructure/persistence/in-memory-customer-repository.ts`

```ts
import type { Customer, CreateCustomerInput } from "../../domain/models/customer.js";
import type { CustomerRepository } from "../../domain/ports/customer-repository.js";

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly customers = new Map<string, Customer>();

  public async findById(id: string): Promise<Customer | null> {
    return this.customers.get(id) ?? null;
  }

  public async findByEmail(email: string): Promise<Customer | null> {
    for (const customer of this.customers.values()) {
      if (customer.email.toLowerCase() === email.toLowerCase()) {
        return customer;
      }
    }
    return null;
  }

  public async create(input: CreateCustomerInput): Promise<Customer> {
    const customer: Customer = {
      id: crypto.randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString(),
      sourceSystem: "LOCAL"
    };

    this.customers.set(customer.id, customer);
    return customer;
  }
}
```

For production, replace this with:
- PostgreSQL repository
- Oracle/SQL Server adapter
- internal enterprise persistence SDK

