# 11. Corporate integration client

## `src/infrastructure/integrations/corporate-crm-http-client.ts`

```ts
import type { CorporateCrmClient } from "../../domain/ports/corporate-crm-client.js";
import type { Customer, CreateCustomerInput } from "../../domain/models/customer.js";
import type { AppConfig } from "../../config/env.js";
import { IntegrationError } from "../../shared/errors.js";

interface CorporateCrmCreateCustomerResponse {
  customerId: string;
  email: string;
  givenName: string;
  familyName: string;
  createdTimestamp: string;
}

export class CorporateCrmHttpClient implements CorporateCrmClient {
  public constructor(private readonly config: AppConfig) {}

  public async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const response = await fetch(`${this.config.CRM_BASE_URL}/api/customers`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.config.CRM_API_KEY
      },
      body: JSON.stringify({
        email: input.email,
        givenName: input.firstName,
        familyName: input.lastName
      })
    });

    if (!response.ok) {
      throw new IntegrationError("Corporate CRM returned a non-success response", {
        status: response.status
      });
    }

    const data = (await response.json()) as CorporateCrmCreateCustomerResponse;

    return {
      id: data.customerId,
      email: data.email,
      firstName: data.givenName,
      lastName: data.familyName,
      createdAt: data.createdTimestamp,
      sourceSystem: "CORPORATE_CRM"
    };
  }
}
```

In a stricter enterprise implementation, validate the response with Zod before trusting it.

