## `src/infrastructure/http/routes/customer-routes.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import type { CustomerService } from "../../../domain/services/customer-service.js";
import { NotFoundError } from "../../../shared/errors.js";
import { createCustomerBodySchema } from "../../../schemas/customer-schemas.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

type GetCustomerRequest = FastifyRequest<{
  Params: {
    id: string;
  };
}>;

type CreateCustomerRequest = FastifyRequest<{
  Body: {
    email: string;
    firstName: string;
    lastName: string;
  };
}>;

export async function customerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get(
    "/customers/:id",
    async (request: GetCustomerRequest, reply: FastifyReply) => {
      const params = paramsSchema.parse(request.params);
      const customer = await customerService.getCustomerById(params.id);

      if (!customer) {
        throw new NotFoundError("Customer not found", { id: params.id });
      }

      await reply.status(200).send(customer);
    }
  );

  app.post(
    "/customers",
    async (request: CreateCustomerRequest, reply: FastifyReply) => {
      const body = createCustomerBodySchema.parse(request.body);
      const customer = await customerService.createCustomer(body);
      await reply.status(201).send(customer);
    }
  );
}
```

