# 16. App bootstrap

## `src/app.ts`

```ts
import Fastify from "fastify";
import type { AppConfig } from "./config/env.js";
import type { Dependencies } from "./container/dependencies.js";
import { errorHandler } from "./infrastructure/http/error-handler.js";
import { healthRoutes } from "./infrastructure/http/routes/health-routes.js";
import { customerRoutes } from "./infrastructure/http/routes/customer-routes.js";
import { createLogger } from "./infrastructure/logging/logger.js";

export function buildApp(config: AppConfig, dependencies: Dependencies) {
  const logger = createLogger(config);

  const app = Fastify({
    logger
  });

  app.setErrorHandler(errorHandler);

  app.register(healthRoutes);
  app.register(async (instance) => {
    await customerRoutes(instance, dependencies.customerService);
  });

  return app;
}
```

## `src/server.ts`

```ts
import { loadConfig } from "./config/env.js";
import { buildDependencies } from "./container/dependencies.js";
import { buildApp } from "./app.js";

async function main(): Promise<void> {
  const config = loadConfig(process.env);
  const dependencies = buildDependencies(config);
  const app = buildApp(config, dependencies);

  try {
    await app.listen({
      port: config.PORT,
      host: "0.0.0.0"
    });
    app.log.info({ port: config.PORT }, "Server started");
  } catch (error) {
    app.log.fatal({ err: error }, "Failed to start server");
    process.exit(1);
  }
}

void main();
```

