```ts
import { describe, expect, it } from "vitest";
import { CustomerService } from "./customer-service.js";
import { ValidationError } from "../../shared/errors.js";
import type { CustomerRepository } from "../ports/customer-repository.js";
import type { CorporateCrmClient } from "../ports/corporate-crm-client.js";
import type { Customer } from "../models/customer.js";

class FakeRepository implements CustomerRepository {
  private customer: Customer | null = null;

  async findById(id: string): Promise<Customer | null> {
    return this.customer?.id === id ? this.customer : null;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    return this.customer?.email === email ? this.customer : null;
  }

  async create(input: { email: string; firstName: string; lastName: string }): Promise<Customer> {
    this.customer = {
      id: "local-1",
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString(),
      sourceSystem: "LOCAL"
    };
    return this.customer;
  }
}

class FakeCrmClient implements CorporateCrmClient {
  async createCustomer(input: { email: string; firstName: string; lastName: string }): Promise<Customer> {
    return {
      id: "crm-1",
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString(),
      sourceSystem: "CORPORATE_CRM"
    };
  }
}

describe("CustomerService", () => {
  it("creates a customer when email does not exist", async () => {
    const service = new CustomerService(new FakeRepository(), new FakeCrmClient());

    const result = await service.createCustomer({
      email: "user@example.com",
      firstName: "Jane",
      lastName: "Doe"
    });

    expect(result.email).toBe("user@example.com");
    expect(result.sourceSystem).toBe("LOCAL");
  });

  it("throws when email already exists", async () => {
    const repository = new FakeRepository();
    await repository.create({
      email: "user@example.com",
      firstName: "Jane",
      lastName: "Doe"
    });

    const service = new CustomerService(repository, new FakeCrmClient());

    await expect(
      service.createCustomer({
        email: "user@example.com",
        firstName: "John",
        lastName: "Smith"
      })
    ).rejects.toBeInstanceOf(ValidationError);
  });
});
