# 9. Repository

For initial implementation, use an in-memory repository. In production, this would be replaced by PostgreSQL, Oracle, SQL Server, etc.

## `src/repositories/employee.repository.ts`

```ts
import type { CreateEmployeeInput, EmployeeId, EmployeeProfile } from "../domain/employee.js";
import { randomUUID } from "node:crypto";

export interface EmployeeRepository {
  findById(id: EmployeeId): Promise<EmployeeProfile | null>;
  findByEmail(email: string): Promise<EmployeeProfile | null>;
  create(input: CreateEmployeeInput): Promise<EmployeeProfile>;
}

export class InMemoryEmployeeRepository implements EmployeeRepository {
  private readonly store = new Map<EmployeeId, EmployeeProfile>();

  async findById(id: EmployeeId): Promise<EmployeeProfile | null> {
    return this.store.get(id) ?? null;
  }

  async findByEmail(email: string): Promise<EmployeeProfile | null> {
    for (const employee of this.store.values()) {
      if (employee.email.toLowerCase() === email.toLowerCase()) {
        return employee;
      }
    }
    return null;
  }

  async create(input: CreateEmployeeInput): Promise<EmployeeProfile> {
    const employee: EmployeeProfile = {
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      department: input.department,
      active: true
    };

    this.store.set(employee.id, employee);
    return employee;
  }
}
```

