# 10. Corporate integration clients

These are typed outbound clients for existing corporate systems.

## `src/integrations/corporate-identity.client.ts`

```ts
import axios, { type AxiosInstance } from "axios";
import { z } from "zod";
import { env } from "../config/env.js";
import { IntegrationError } from "../domain/errors.js";

const IdentityUserSchema = z.object({
  email: z.string().email(),
  exists: z.boolean()
});

export type IdentityUser = z.infer<typeof IdentityUserSchema>;

export interface CorporateIdentityClient {
  checkUserExists(email: string): Promise<boolean>;
}

export class HttpCorporateIdentityClient implements CorporateIdentityClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: env.CORPORATE_IDENTITY_BASE_URL,
      timeout: 5000,
      headers: {
        "x-api-key": env.CORPORATE_IDENTITY_API_KEY
      }
    });
  }

  async checkUserExists(email: string): Promise<boolean> {
    try {
      const response = await this.http.get("/users/exists", {
        params: { email }
      });

      const parsed = IdentityUserSchema.safeParse(response.data);
      if (!parsed.success) {
        throw new IntegrationError("Invalid response from Corporate Identity", parsed.error.format());
      }

      return parsed.data.exists;
    } catch (error: unknown) {
      if (error instanceof IntegrationError) {
        throw error;
      }

      throw new IntegrationError("Failed to query Corporate Identity", {
        cause: error
      });
    }
  }
}
```

## `src/integrations/corporate-hr.client.ts`

```ts
import axios, { type AxiosInstance } from "axios";
import { z } from "zod";
import { env } from "../config/env.js";
import { IntegrationError } from "../domain/errors.js";
import type { Department } from "../domain/employee.js";

const HrProvisionRequestSchema = z.object({
  email: z.string().email(),
  firstName: z.string(),
  lastName: z.string(),
  department: z.string()
});

const HrProvisionResponseSchema = z.object({
  success: z.boolean(),
  employeeNumber: z.string().min(1)
});

export type HrProvisionResponse = z.infer<typeof HrProvisionResponseSchema>;

export interface CorporateHrClient {
  provisionEmployee(input: {
    email: string;
    firstName: string;
    lastName: string;
    department: Department;
  }): Promise<HrProvisionResponse>;
}

export class HttpCorporateHrClient implements CorporateHrClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: env.CORPORATE_HR_BASE_URL,
      timeout: 5000,
      headers: {
        "x-api-key": env.CORPORATE_HR_API_KEY
      }
    });
  }

  async provisionEmployee(input: {
    email: string;
    firstName: string;
    lastName: string;
    department: Department;
  }): Promise<HrProvisionResponse> {
    const validated = HrProvisionRequestSchema.parse(input);

    try {
      const response = await this.http.post("/employees/provision", validated);
      const parsed = HrProvisionResponseSchema.safeParse(response.data);

      if (!parsed.success) {
        throw new IntegrationError("Invalid response from Corporate HR", parsed.error.format());
      }

      return parsed.data;
    } catch (error: unknown) {
      if (error instanceof IntegrationError) {
        throw error;
      }

      throw new IntegrationError("Failed to provision employee in Corporate HR", {
        cause: error
      });
    }
  }
}
