# 11. Service layer

## `src/services/employee.service.ts`

```ts
import type { CreateEmployeeInput, EmployeeId, EmployeeProfile } from "../domain/employee.js";
import { NotFoundError, DomainError } from "../domain/errors.js";
import type { EmployeeRepository } from "../repositories/employee.repository.js";
import type { CorporateIdentityClient } from "../integrations/corporate-identity.client.js";
import type { CorporateHrClient } from "../integrations/corporate-hr.client.js";

export interface EmployeeService {
  getById(id: EmployeeId): Promise<EmployeeProfile>;
  create(input: CreateEmployeeInput): Promise<EmployeeProfile>;
}

export class DefaultEmployeeService implements EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly identityClient: CorporateIdentityClient,
    private readonly hrClient: CorporateHrClient
  ) {}

  async getById(id: EmployeeId): Promise<EmployeeProfile> {
    const employee = await this.repository.findById(id);
    if (!employee) {
      throw new NotFoundError(`Employee not found: ${id}`);
    }
    return employee;
  }

  async create(input: CreateEmployeeInput): Promise<EmployeeProfile> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new DomainError("Employee already exists", "EMPLOYEE_ALREADY_EXISTS", 409, {
        email: input.email
      });
    }

    const identityExists = await this.identityClient.checkUserExists(input.email);
    if (!identityExists) {
      throw new DomainError(
        "Employee email does not exist in Corporate Identity",
        "IDENTITY_USER_NOT_FOUND",
        400,
        { email: input.email }
      );
    }

    const hrResult = await this.hrClient.provisionEmployee({
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      department: input.department
    });

    if (!hrResult.success) {
      throw new DomainError("HR provisioning failed", "HR_PROVISIONING_FAILED", 502, hrResult);
    }

    return this.repository.create(input);
  }
}
```

