import type { FastifyInstance, FastifyRequest } from "fastify";
import { z } from "zod";
import { CreateEmployeeRequestSchema } from "../schemas/employee.schemas.js";
import { EmployeeIdSchema } from "../../domain/employee.js";
import type { EmployeeService } from "../../services/employee.service.js";

type CreateEmployeeRequestBody = z.infer<typeof CreateEmployeeRequestSchema>;
type GetEmployeeParams = { id: string };

export async function employeeRoutes(
  app: FastifyInstance,
  dependencies: { employeeService: EmployeeService }
): Promise<void> {
  app.get(
    "/employees/:id",
    async (
      request: FastifyRequest<{ Params: GetEmployeeParams }>
    ) => {
      const id = EmployeeIdSchema.parse(request.params.id);
      const employee = await dependencies.employeeService.getById(id);
      return employee;
    }
  );

  app.post(
    "/employees",
    async (
      request: FastifyRequest<{ Body: CreateEmployeeRequestBody }>,
      reply
    ) => {
      const body = CreateEmployeeRequestSchema.parse(request.body);
      const employee = await dependencies.employeeService.create(body);
      reply.status(201);
      return employee;
    }
  );
}
```

