import { HttpCorporateHrClient } from "./integrations/corporate-hr.client.js";
import { DefaultEmployeeService } from "./services/employee.service.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({
    logger
  });

  const employeeRepository = new InMemoryEmployeeRepository();
  const identityClient = new HttpCorporateIdentityClient();
  const hrClient = new HttpCorporateHrClient();

  const employeeService = new DefaultEmployeeService(
    employeeRepository,
    identityClient,
    hrClient
  );

  void registerErrorHandler(app);
  void healthRoutes(app);
  void employeeRoutes(app, { employeeService });

  return app;
}
