# 9. Application service

## `src/application/services/customer-service.ts`

```ts
import crypto from "node:crypto";
import { customerSchema, type Customer } from "../../domain/models/customer.js";
import type { CustomerRepository } from "../../domain/ports/customer-repository.js";
import type {
  CorporateCrmClient,
  CorporateCrmCustomerRecord
} from "../../domain/ports/corporate-crm-client.js";

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateCrmClient: CorporateCrmClient
  ) {}

  public async syncCustomerFromCrm(crmId: string): Promise<Customer> {
    const crmRecord = await this.corporateCrmClient.fetchCustomerByCrmId(crmId);

    if (crmRecord === null) {
      throw new Error(`CRM customer not found for crmId=${crmId}`);
    }

    const customer = this.mapCrmRecordToCustomer(crmRecord);
    await this.customerRepository.save(customer);
    return customer;
  }

  private mapCrmRecordToCustomer(record: CorporateCrmCustomerRecord): Customer {
    return customerSchema.parse({
      id: crypto.randomUUID(),
      externalCrmId: record.crmId,
      email: record.emailAddress,
      firstName: record.givenName,
      lastName: record.familyName,
      active: record.isActive
    });
  }
}
```

