# 11. Infrastructure: corporate HTTP adapter

## `src/infrastructure/integrations/corporate-crm-http-client.ts`

```ts
import type { AppConfig } from "../../config/env.js";
import type {
  CorporateCrmClient,
  CorporateCrmCustomerRecord
} from "../../domain/ports/corporate-crm-client.js";

interface FetchLikeResponse {
  ok: boolean;
  status: number;
  json(): Promise<unknown>;
}

type FetchLike = (input: string, init?: Record<string, unknown>) => Promise<FetchLikeResponse>;

export class CorporateCrmHttpClient implements CorporateCrmClient {
  public constructor(
    private readonly config: AppConfig,
    private readonly fetchImpl: FetchLike = fetch as unknown as FetchLike
  ) {}

  public async fetchCustomerByCrmId(crmId: string): Promise<CorporateCrmCustomerRecord | null> {
    const url = `${this.config.CORPORATE_CRM_BASE_URL}/api/customers/${encodeURIComponent(crmId)}`;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), this.config.CORPORATE_CRM_TIMEOUT_MS);

    try {
      const response = await this.fetchImpl(url, {
        method: "GET",
        headers: {
          "x-api-key": this.config.CORPORATE_CRM_API_KEY,
          "content-type": "application/json"
        },
        signal: controller.signal
      });

      if (response.status === 404) {
        return null;
      }

      if (!response.ok) {
        throw new Error(`Corporate CRM request failed with status ${response.status}`);
      }

      const payload = await response.json();
      return this.validateCrmPayload(payload);
    } finally {
      clearTimeout(timeout);
    }
  }

  private validateCrmPayload(payload: unknown): CorporateCrmCustomerRecord {
    const value = payload as Partial<CorporateCrmCustomerRecord>;

    if (
      typeof value.crmId !== "string" ||
      typeof value.emailAddress !== "string" ||
      typeof value.givenName !== "string" ||
      typeof value.familyName !== "string" ||
      typeof value.isActive !== "boolean"
    ) {
      throw new Error("Invalid CRM payload shape");
    }

    return {
      crmId: value.crmId,
      emailAddress: value.emailAddress,
      givenName: value.givenName,
      familyName: value.familyName,
      isActive: value.isActive
    };
  }
}
```

For even stricter runtime safety, you could replace manual validation with `zod`.

