import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import type { CustomerService } from "../../application/services/customer-service.js";
import { syncCustomerParamsSchema } from "../schemas/customer-schemas.js";

type SyncCustomerRequest = FastifyRequest<{
  Params: {
    crmId: string;
  };
}>;

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.post(
    "/customers/sync/:crmId",
    async (request: SyncCustomerRequest, reply: FastifyReply) => {
      const params = syncCustomerParamsSchema.parse(request.params);
      const customer = await customerService.syncCustomerFromCrm(params.crmId);
      return reply.code(200).send(customer);
    }
  );

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof z.ZodError) {
      return reply.status(400).send({
        message: "Validation failed",
        issues: error.issues
      });
    }

    app.log.error({ err: error }, "Unhandled route error");
    return reply.status(500).send({
      message: "Internal server error"
    });
  });
}
