```ts
import Fastify from "fastify";
import { loadConfig } from "./config/env.js";
import { createLogger } from "./config/logger.js";
import { CustomerService } from "./application/services/customer-service.js";
import { InMemoryCustomerRepository } from "./infrastructure/persistence/in-memory-customer-repository.js";
import { CorporateCrmHttpClient } from "./infrastructure/integrations/corporate-crm-http-client.js";
import { registerHealthRoutes } from "./api/routes/health.js";
import { registerCustomerRoutes } from "./api/routes/customers.js";

export async function buildApp() {
  const config = loadConfig(process.env);
  const logger = createLogger(config);

  const app = Fastify({
    logger
  });

  const customerRepository = new InMemoryCustomerRepository();
  const corporateCrmClient = new CorporateCrmHttpClient(config);
  const customerService = new CustomerService(customerRepository, corporateCrmClient);

  await registerHealthRoutes(app);
  await registerCustomerRoutes(app, customerService);

  return app;
}
