```ts
import { DomainError } from '../../common/errors/domain.error';
import type { AccessRequestProps } from './access-request.types';
import { AccessRequestStatus } from './access-request.types';

export class AccessRequest {
  private constructor(private readonly props: AccessRequestProps) {}

  static create(props: AccessRequestProps): AccessRequest {
    if (props.systemName.trim().length < 3) {
      throw new DomainError('System name must be at least 3 characters.');
    }

    if (props.justification.trim().length < 10) {
      throw new DomainError('Justification must be at least 10 characters.');
    }

    return new AccessRequest(props);
  }

  get id() {
    return this.props.id;
  }

  get employeeId() {
    return this.props.employeeId;
  }

  get systemName() {
    return this.props.systemName;
  }

  get justification() {
    return this.props.justification;
  }

  get status() {
    return this.props.status;
  }

  get createdAt() {
    return this.props.createdAt;
  }

  approve(): AccessRequest {
    if (this.props.status !== AccessRequestStatus.Pending) {
      throw new DomainError('Only pending requests can be approved.');
    }

    return new AccessRequest({
      ...this.props,
      status: AccessRequestStatus.Approved
    });
  }
}
