# 11. Application service

## `src/application/access-request/access-request.service.ts`

```ts
import { Inject, Injectable, NotFoundException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { toAccessRequestId, toEmployeeId } from '../../common/types/branded';
import { AccessRequest } from '../../domain/access-request/access-request.entity';
import {
  ACCESS_REQUEST_REPOSITORY,
  type AccessRequestRepository
} from '../../domain/access-request/access-request.repository';
import { AccessRequestStatus } from '../../domain/access-request/access-request.types';
import type { CreateAccessRequestDto } from './dto/create-access-request.dto';
import type { AccessRequestResponse } from './dto/access-request.response';
import {
  EMPLOYEE_DIRECTORY_PORT,
  type EmployeeDirectoryPort
} from './ports/employee-directory.port';
import { EVENT_BUS_PORT, type EventBusPort } from './ports/event-bus.port';

@Injectable()
export class AccessRequestService {
  constructor(
    @Inject(ACCESS_REQUEST_REPOSITORY)
    private readonly repository: AccessRequestRepository,
    @Inject(EMPLOYEE_DIRECTORY_PORT)
    private readonly employeeDirectory: EmployeeDirectoryPort,
    @Inject(EVENT_BUS_PORT)
    private readonly eventBus: EventBusPort
  ) {}

  async create(dto: CreateAccessRequestDto): Promise<AccessRequestResponse> {
    const employeeId = toEmployeeId(dto.employeeId);
    const employee = await this.employeeDirectory.getEmployeeById(employeeId);

    if (!employee || !employee.active) {
      throw new NotFoundException('Active employee not found.');
    }

    const entity = AccessRequest.create({
      id: toAccessRequestId(randomUUID()),
      employeeId,
      systemName: dto.systemName,
      justification: dto.justification,
      status: AccessRequestStatus.Pending,
      createdAt: new Date()
    });

    const saved = await this.repository.save(entity);

    await this.eventBus.publish({
      eventName: 'access-request.created',
      occurredAt: new Date().toISOString(),
      payload: {
        id: saved.id,
        employeeId: saved.employeeId,
        systemName: saved.systemName,
        status: saved.status
      }
    });

    return {
      id: saved.id,
      employeeId: saved.employeeId,
      systemName: saved.systemName,
      justification: saved.justification,
      status: saved.status,
      createdAt: saved.createdAt.toISOString()
    };
  }

  async getById(id: string): Promise<AccessRequestResponse> {
    const entity = await this.repository.findById(toAccessRequestId(id));

    if (!entity) {
      throw new NotFoundException('Access request not found.');
    }

    return {
      id: entity.id,
      employeeId: entity.employeeId,
      systemName: entity.systemName,
      justification: entity.justification,
      status: entity.status,
      createdAt: entity.createdAt.toISOString()
    };
  }
}
```

