      where: { id: entity.id },
      update: {
        employeeId: entity.employeeId,
        systemName: entity.systemName,
        justification: entity.justification,
        status: entity.status,
        createdAt: entity.createdAt
      },
      create: {
        id: entity.id,
        employeeId: entity.employeeId,
        systemName: entity.systemName,
        justification: entity.justification,
        status: entity.status,
        createdAt: entity.createdAt
      }
    });

    return AccessRequest.create({
      id: toAccessRequestId(record.id),
      employeeId: toEmployeeId(record.employeeId),
      systemName: record.systemName,
      justification: record.justification,
      status: record.status as keyof typeof AccessRequestStatus extends never
        ? never
        : typeof record.status,
      createdAt: record.createdAt
    });
  }

  async findById(id: ReturnType<typeof toAccessRequestId>): Promise<AccessRequest | null> {
    const record = await this.prisma.accessRequest.findUnique({
      where: { id }
    });

    if (!record) {
      return null;
    }

    return AccessRequest.create({
      id: toAccessRequestId(record.id),
      employeeId: toEmployeeId(record.employeeId),
      systemName: record.systemName,
      justification: record.justification,
      status: record.status as 'PENDING' | 'APPROVED' | 'REJECTED',
      createdAt: record.createdAt
    });
  }
}
