import { Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ExternalSystemError } from '../../../common/errors/external-system.error';
import type { EmployeeId } from '../../../common/types/branded';
import type {
  EmployeeDirectoryPort,
  EmployeeRecord
} from '../../../application/access-request/ports/employee-directory.port';

interface HrEmployeeResponse {
  employeeId: string;
  email: string;
  department: string;
  active: boolean;
}

@Injectable()
export class CorporateHrClient implements EmployeeDirectoryPort {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.HR_API_BASE_URL,
      timeout: Number(process.env.HR_API_TIMEOUT_MS ?? 5000)
    });
  }

  async getEmployeeById(employeeId: EmployeeId): Promise<EmployeeRecord | null> {
    try {
      const response = await this.client.get<HrEmployeeResponse>(`/employees/${employeeId}`);
      const data = response.data;

      return {
        employeeId: data.employeeId as EmployeeId,
        email: data.email,
        department: data.department,
        active: data.active
      };
    } catch (error: unknown) {
      if (axios.isAxiosError(error) && error.response?.status === 404) {
        return null;
      }

      throw new ExternalSystemError('Failed to fetch employee from HR system.', 'CorporateHR', error);
    }
  }
}
```

