# 20. A more enterprise-safe repository implementation

Here is a cleaned-up repository version.

## `src/infrastructure/database/access-request.prisma.repository.ts`

```ts
import { Injectable } from '@nestjs/common';
import { toAccessRequestId, toEmployeeId, type AccessRequestId } from '../../common/types/branded';
import { AccessRequest } from '../../domain/access-request/access-request.entity';
import type { AccessRequestRepository } from '../../domain/access-request/access-request.repository';
import type { AccessRequestStatus } from '../../domain/access-request/access-request.types';
import { PrismaService } from './prisma/prisma.service';

const parseAccessRequestStatus = (value: string): AccessRequestStatus => {
  switch (value) {
    case 'PENDING':
    case 'APPROVED':
    case 'REJECTED':
      return value;
    default:
      throw new Error(`Invalid access request status from database: ${value}`);
  }
};

@Injectable()
export class PrismaAccessRequestRepository implements AccessRequestRepository {
  constructor(private readonly prisma: PrismaService) {}

  async save(entity: AccessRequest): Promise<AccessRequest> {
    const record = await this.prisma.accessRequest.upsert({
      where: { id: entity.id },
      update: {
        employeeId: entity.employeeId,
        systemName: entity.systemName,
        justification: entity.justification,
        status: entity.status,
        createdAt: entity.createdAt
      },
      create: {
        id: entity.id,
        employeeId: entity.employeeId,
        systemName: entity.systemName,
        justification: entity.justification,
        status: entity.status,
        createdAt: entity.createdAt
      }
    });

    return this.toDomain(record);
  }

  async findById(id: AccessRequestId): Promise<AccessRequest | null> {
    const record = await this.prisma.accessRequest.findUnique({
      where: { id }
    });

    return record ? this.toDomain(record) : null;
  }

  private toDomain(record: {
    id: string;
    employeeId: string;
    systemName: string;
    justification: string;
    status: string;
    createdAt: Date;
  }): AccessRequest {
    return AccessRequest.create({
      id: toAccessRequestId(record.id),
      employeeId: toEmployeeId(record.employeeId),
      systemName: record.systemName,
      justification: record.justification,
      status: parseAccessRequestStatus(record.status),
      createdAt: record.createdAt
    });
  }
}
```

