import type { CustomerRepository } from "./customer.repository.js";
import type { Customer, CreateCustomerInput } from "./customer.js";
import { CustomerAlreadyExistsError, CustomerNotFoundError } from "./customer.errors.js";
import type { CustomerId } from "../../shared/types.js";

export class CustomerService {
  public constructor(private readonly repository: CustomerRepository) {}

  public async getCustomerById(id: CustomerId): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new CustomerNotFoundError(id);
    }
    return customer;
  }

  public async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new CustomerAlreadyExistsError(input.email);
    }
    return this.repository.create(input);
  }

  public async listCustomers(): Promise<readonly Customer[]> {
    return this.repository.list();
  }
}
