# 9. Infrastructure: auth/corporate context propagation

This is where enterprise SSO/JWT/header propagation would be integrated.

## `src/infrastructure/http/auth-context.ts`

```ts
import type { FastifyRequest } from "fastify";
import { asCorrelationId, type CorrelationId } from "../../shared/types.js";

export interface RequestContext {
  readonly correlationId: CorrelationId;
  readonly principalId: string | null;
  readonly roles: readonly string[];
}

export function extractRequestContext(request: FastifyRequest): RequestContext {
  const correlationHeader = request.headers["x-correlation-id"];
  const principalHeader = request.headers["x-principal-id"];
  const rolesHeader = request.headers["x-roles"];

  const correlationId =
    typeof correlationHeader === "string" && correlationHeader.length > 0
      ? asCorrelationId(correlationHeader)
      : asCorrelationId(crypto.randomUUID());

  const principalId = typeof principalHeader === "string" ? principalHeader : null;

  const roles =
    typeof rolesHeader === "string"
      ? rolesHeader.split(",").map((role) => role.trim()).filter(Boolean)
      : [];

  return {
    correlationId,
    principalId,
    roles
  };
}
```

