# 10. Infrastructure: corporate API client

This client abstracts an existing corporate system.

## `src/infrastructure/http/corporate-api.client.ts`

```ts
import { IntegrationError } from "../../shared/errors.js";
import type { Logger } from "../logging/logger.js";
import type { RequestContext } from "./auth-context.js";

export interface CorporateCustomerRecord {
  readonly employeeSponsorId: string;
  readonly riskTier: "LOW" | "MEDIUM" | "HIGH";
}

export interface CorporateApiClient {
  fetchCustomerRecord(
    customerEmail: string,
    context: RequestContext
  ): Promise<CorporateCustomerRecord | null>;
}

export interface CorporateApiClientConfig {
  readonly baseUrl: string;
  readonly timeoutMs: number;
}

export class HttpCorporateApiClient implements CorporateApiClient {
  public constructor(
    private readonly config: CorporateApiClientConfig,
    private readonly logger: Logger
  ) {}

  public async fetchCustomerRecord(
    customerEmail: string,
    context: RequestContext
  ): Promise<CorporateCustomerRecord | null> {
    const url = new URL("/customers/lookup", this.config.baseUrl);
    url.searchParams.set("email", customerEmail);

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), this.config.timeoutMs);

    try {
      const response = await fetch(url, {
        method: "GET",
        signal: controller.signal,
        headers: {
          "x-correlation-id": context.correlationId,
          ...(context.principalId ? { "x-principal-id": context.principalId } : {})
        }
      });

      if (response.status === 404) {
        return null;
      }

      if (!response.ok) {
        throw new IntegrationError("Corporate API returned non-success status", {
          status: response.status
        });
      }

      const data: unknown = await response.json();

      if (
        typeof data !== "object" ||
        data === null ||
        typeof (data as Record<string, unknown>).employeeSponsorId !== "string" ||
        !["LOW", "MEDIUM", "HIGH"].includes(
          String((data as Record<string, unknown>).riskTier)
        )
      ) {
        throw new IntegrationError("Corporate API returned invalid payload");
      }

      return {
        employeeSponsorId: (data as Record<string, string>).employeeSponsorId,
        riskTier: (data as Record<string, "LOW" | "MEDIUM" | "HIGH">).riskTier
      };
    } catch (error: unknown) {
      if (error instanceof IntegrationError) {
        throw error;
      }

      this.logger.error("Corporate API request failed", {
        error: error instanceof Error ? error.message : "unknown_error"
      });

      throw new IntegrationError("Failed to call corporate API");
    } finally {
      clearTimeout(timeout);
    }
  }
}
```

