# 13. Fastify routes

## `src/app/routes.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import type { CustomerService } from "../domain/customer/customer.service.js";
import { createCustomerInputSchema } from "../domain/customer/customer.js";
import { getHealthStatus } from "../infrastructure/monitoring/health.js";
import { extractRequestContext } from "../infrastructure/http/auth-context.js";
import { ApplicationError } from "../shared/errors.js";
import { asCustomerId } from "../shared/types.js";
import type { Logger } from "../infrastructure/logging/logger.js";

export interface RouteDependencies {
  readonly customerService: CustomerService;
  readonly logger: Logger;
}

const customerIdParamsSchema = z.object({
  id: z.string().min(1)
});

export async function registerRoutes(
  app: FastifyInstance,
  dependencies: RouteDependencies
): Promise<void> {
  app.get("/health", async () => {
    return getHealthStatus();
  });

  app.get("/ready", async () => {
    return { ready: true };
  });

  app.get(
    "/customers",
    async (_request: FastifyRequest, reply: FastifyReply) => {
      const customers = await dependencies.customerService.listCustomers();
      return reply.status(200).send({ data: customers });
    }
  );

  app.get(
    "/customers/:id",
    async (request: FastifyRequest, reply: FastifyReply) => {
      try {
        const params = customerIdParamsSchema.parse(request.params);
        const customer = await dependencies.customerService.getCustomerById(
          asCustomerId(params.id)
        );
        return reply.status(200).send({ data: customer });
      } catch (error: unknown) {
        return handleRouteError(error, reply, dependencies.logger);
      }
    }
  );

  app.post(
    "/customers",
    async (request: FastifyRequest, reply: FastifyReply) => {
      try {
        const context = extractRequestContext(request);
        dependencies.logger.info("Create customer request received", {
          correlationId: context.correlationId,
          principalId: context.principalId
        });

        const input = createCustomerInputSchema.parse(request.body);
        const customer = await dependencies.customerService.createCustomer(input);

        return reply.status(201).send({ data: customer });
      } catch (error: unknown) {
        return handleRouteError(error, reply, dependencies.logger);
      }
    }
  );
}

function handleRouteError(
  error: unknown,
  reply: FastifyReply,
  logger: Logger
): FastifyReply {
  if (error instanceof ApplicationError) {
    logger.warn("Application error", {
      code: error.code,
      statusCode: error.statusCode,
      message: error.message,
      details: error.details
    });

    return reply.status(error.statusCode).send({
      error: {
        code: error.code,
        message: error.message,
        details: error.details
      }
    });
  }

  if (error instanceof z.ZodError) {
    return reply.status(400).send({
      error: {
        code: "INVALID_REQUEST",
        message: "Request validation failed",
        details: error.flatten()
      }
    });
  }

  logger.error("Unhandled route error", {
    error: error instanceof Error ? error.message : "unknown_error"
  });

  return reply.status(500).send({
    error: {
      code: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    }
  });
}
```

