import Fastify, { type FastifyInstance } from "fastify";
import { registerRoutes, type RouteDependencies } from "./routes.js";

export async function buildServer(
  dependencies: RouteDependencies
): Promise<FastifyInstance> {
  const app = Fastify({
    logger: false
  });

  await registerRoutes(app, dependencies);

  return app;
}
```

## `src/main.ts`

```ts
import { loadEnv } from "./config/env.js";
import { buildServer } from "./app/server.js";
import { ConsoleLogger } from "./infrastructure/logging/logger.js";
import { InMemoryCustomerRepository } from "./infrastructure/persistence/in-memory-customer.repository.js";
import { CustomerService } from "./domain/customer/customer.service.js";

async function main(): Promise<void> {
  const env = loadEnv();
  const logger = new ConsoleLogger();

  const customerRepository = new InMemoryCustomerRepository();
  const customerService = new CustomerService(customerRepository);

  const server = await buildServer({
    customerService,
    logger
  });

  await server.listen({
    port: env.PORT,
    host: "0.0.0.0"
  });

  logger.info("Service started", {
    service: env.SERVICE_NAME,
    port: env.PORT,
    environment: env.NODE_ENV
  });
}

main().catch((error: unknown) => {
  console.error("Fatal startup error", error);
  process.exit(1);
});
