# 7. Application service layer

## `src/application/customer-service.ts`

```ts
import type { AuditPort, CustomerRepository } from "../domain/ports.js";
import type { CreateCustomerCommand, Customer } from "../domain/customer.js";
import { NotFoundError, ValidationError } from "../domain/errors.js";

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly auditPort: AuditPort
  ) {}

  public async getCustomerById(customerId: string): Promise<Customer> {
    if (customerId.trim().length === 0) {
      throw new ValidationError("customerId must not be empty");
    }

    const customer = await this.customerRepository.getById(customerId);
    if (customer === null) {
      throw new NotFoundError(`Customer not found: ${customerId}`);
    }

    return customer;
  }

  public async createCustomer(
    command: CreateCustomerCommand,
    requestId: string
  ): Promise<Customer> {
    if (!command.email.includes("@")) {
      throw new ValidationError("Invalid email address");
    }

    const customer = await this.customerRepository.create(command);
    await this.auditPort.publishCustomerCreated(customer, requestId);

    return customer;
  }
}
