# 8. Corporate HTTP client abstraction

This is important in enterprise environments because:
- auth mechanisms often change
- proxy/TLS/retry requirements are centralized
- headers like correlation IDs must be propagated consistently

## `src/infrastructure/http/corporate-http-client.ts`

```ts
import { request } from "undici";
import { IntegrationError } from "../../domain/errors.js";

export interface HttpRequestOptions {
  readonly method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  readonly url: string;
  readonly headers?: Readonly<Record<string, string>>;
  readonly body?: unknown;
  readonly timeoutMs: number;
}

export interface HttpResponse<T> {
  readonly statusCode: number;
  readonly body: T;
}

export class CorporateHttpClient {
  public constructor(
    private readonly apiKey: string
  ) {}

  public async send<TResponse>(
    options: HttpRequestOptions
  ): Promise<HttpResponse<TResponse>> {
    const response = await request(options.url, {
      method: options.method,
      headers: {
        "content-type": "application/json",
        "x-api-key": this.apiKey,
        ...options.headers
      },
      body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
      headersTimeout: options.timeoutMs,
      bodyTimeout: options.timeoutMs
    });

    const text = await response.body.text();
    const parsedBody = text.length > 0 ? JSON.parse(text) as TResponse : ({} as TResponse);

    if (response.statusCode >= 400) {
      throw new IntegrationError(
        `HTTP ${response.statusCode} calling ${options.url}`
      );
    }

    return {
      statusCode: response.statusCode,
      body: parsedBody
    };
  }
}
```

