# 9. Integration clients

## `src/infrastructure/integrations/customer-master-client.ts`

```ts
import { z } from "zod";
import type { CreateCustomerCommand, Customer } from "../../domain/customer.js";
import { IntegrationError } from "../../domain/errors.js";
import { CorporateHttpClient } from "../http/corporate-http-client.js";

const externalCustomerSchema = z.object({
  id: z.string().min(1),
  firstName: z.string(),
  lastName: z.string(),
  email: z.string().email(),
  status: z.enum(["ACTIVE", "INACTIVE"]),
  createdAt: z.string()
});

type ExternalCustomer = z.infer<typeof externalCustomerSchema>;

export class CustomerMasterClient {
  public constructor(
    private readonly httpClient: CorporateHttpClient,
    private readonly baseUrl: string,
    private readonly timeoutMs: number
  ) {}

  public async getCustomerById(customerId: string, requestId: string): Promise<Customer | null> {
    try {
      const response = await this.httpClient.send<ExternalCustomer>({
        method: "GET",
        url: `${this.baseUrl}/customers/${encodeURIComponent(customerId)}`,
        headers: {
          "x-request-id": requestId
        },
        timeoutMs: this.timeoutMs
      });

      const parsed = externalCustomerSchema.parse(response.body);
      return mapExternalCustomer(parsed);
    } catch (error: unknown) {
      if (error instanceof Error && error.message.includes("HTTP 404")) {
        return null;
      }

      throw new IntegrationError("Failed to fetch customer from customer master");
    }
  }

  public async createCustomer(
    command: CreateCustomerCommand,
    requestId: string
  ): Promise<Customer> {
    const response = await this.httpClient.send<ExternalCustomer>({
      method: "POST",
      url: `${this.baseUrl}/customers`,
      headers: {
        "x-request-id": requestId
      },
      body: command,
      timeoutMs: this.timeoutMs
    });

    const parsed = externalCustomerSchema.parse(response.body);
    return mapExternalCustomer(parsed);
  }
}

function mapExternalCustomer(external: ExternalCustomer): Customer {
  return {
    id: { value: external.id },
    firstName: external.firstName,
    lastName: external.lastName,
    email: external.email,
    status: external.status,
    createdAt: external.createdAt
  };
}
```

