import type { Customer } from "../../domain/customer.js";
import type { AuditPort } from "../../domain/ports.js";
import { CorporateHttpClient } from "../http/corporate-http-client.js";

interface AuditEvent {
  readonly eventType: "CUSTOMER_CREATED";
  readonly requestId: string;
  readonly payload: {
    readonly customerId: string;
    readonly email: string;
    readonly createdAt: string;
  };
}

export class AuditClient implements AuditPort {
  public constructor(
    private readonly httpClient: CorporateHttpClient,
    private readonly baseUrl: string,
    private readonly timeoutMs: number
  ) {}

  public async publishCustomerCreated(
    customer: Customer,
    requestId: string
  ): Promise<void> {
    const event: AuditEvent = {
      eventType: "CUSTOMER_CREATED",
      requestId,
      payload: {
        customerId: customer.id.value,
        email: customer.email,
        createdAt: customer.createdAt
      }
    };

    await this.httpClient.send({
      method: "POST",
      url: `${this.baseUrl}/events`,
      body: event,
      headers: {
        "x-request-id": requestId
      },
      timeoutMs: this.timeoutMs
    });
  }
}
