```ts
import type { FastifyPluginAsync } from "fastify";
import { createCustomerBodySchema, customerIdParamsSchema } from "../schemas/customer-schemas.js";
import { CustomerService } from "../../application/customer-service.js";
import { CustomerRepositoryAdapter } from "../../infrastructure/repositories/customer-repository.js";
import { CustomerMasterClient } from "../../infrastructure/integrations/customer-master-client.js";
import { AuditClient } from "../../infrastructure/integrations/audit-client.js";
import { CorporateHttpClient } from "../../infrastructure/http/corporate-http-client.js";
import { loadConfig } from "../../config/env.js";

export const customerRoutes: FastifyPluginAsync = async (fastify) => {
  const config = loadConfig(process.env);

  const httpClient = new CorporateHttpClient(config.corporateApiKey);
  const customerMasterClient = new CustomerMasterClient(
    httpClient,
    config.customerMasterBaseUrl,
    config.requestTimeoutMs
  );
  const auditClient = new AuditClient(
    httpClient,
    config.auditBaseUrl,
    config.requestTimeoutMs
  );

  class RequestAwareCustomerRepository extends CustomerRepositoryAdapter {
    public async getById(customerId: string) {
      return customerMasterClient.getCustomerById(customerId, "placeholder");
    }

    public async create(command: Parameters<CustomerRepositoryAdapter["create"]>[0]) {
      return customerMasterClient.createCustomer(command, "placeholder");
    }
  }

  fastify.get("/v1/customers/:customerId", async (request, reply) => {
    const params = customerIdParamsSchema.parse(request.params);

    const service = new CustomerService(
      {
        getById: async (customerId) =>
          customerMasterClient.getCustomerById(customerId, request.requestId),
        create: async (command) =>
          customerMasterClient.createCustomer(command, request.requestId)
      },
      {
        publishCustomerCreated: async (customer, requestId) =>
          auditClient.publishCustomerCreated(customer, requestId)
      }
    );

    const customer = await service.getCustomerById(params.customerId);

    reply.send({
      id: customer.id.value,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      status: customer.status,
      createdAt: customer.createdAt
    });
  });

  fastify.post("/v1/customers", async (request, reply) => {
    const body = createCustomerBodySchema.parse(request.body);

    const service = new CustomerService(
      {
        getById: async (customerId) =>
          customerMasterClient.getCustomerById(customerId, request.requestId),
        create: async (command) =>
          customerMasterClient.createCustomer(command, request.requestId)
      },
      {
        publishCustomerCreated: async (customer, requestId) =>
          auditClient.publishCustomerCreated(customer, requestId)
      }
    );

    const customer = await service.createCustomer(body, request.requestId);

    reply.status(201).send({
      id: customer.id.value,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      status: customer.status,
      createdAt: customer.createdAt
    });
  });
};
```

