# 11. Service layer

Business logic belongs here.

## `src/domain/customer/customer.service.ts`

```ts
import { AppError } from "../../core/errors.js";
import type { CustomerRepository } from "./customer.repository.js";
import type { CreateCustomerInput, Customer } from "./customer.types.js";
import type { HrSystemClient } from "../../infrastructure/clients/hr-system.client.js";
import type { IdentityClient } from "../../infrastructure/clients/identity.client.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly hrSystemClient: HrSystemClient,
    private readonly identityClient: IdentityClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new AppError({
        message: "Customer with this email already exists",
        code: "CONFLICT",
        statusCode: 409
      });
    }

    const employee = await this.hrSystemClient.getEmployeeById(input.externalEmployeeId);
    if (!employee || !employee.active) {
      throw new AppError({
        message: "Employee not found or inactive in HR system",
        code: "VALIDATION_ERROR",
        statusCode: 400
      });
    }

    const identityUser = await this.identityClient.findUserByEmail(input.email);
    if (!identityUser || !identityUser.enabled) {
      throw new AppError({
        message: "User not found or disabled in identity system",
        code: "VALIDATION_ERROR",
        statusCode: 400
      });
    }

    return this.customerRepository.create(input);
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new AppError({
        message: "Customer not found",
        code: "NOT_FOUND",
        statusCode: 404
      });
    }
    return customer;
  }
}
```

