# 14. Prisma repository implementation

## `src/infrastructure/repositories/prisma-customer.repository.ts`

```ts
import type { CustomerRepository } from "../../domain/customer/customer.repository.js";
import type { CreateCustomerInput, Customer } from "../../domain/customer/customer.types.js";
import { prisma } from "../db/prisma.js";

function mapToDomain(record: {
  id: string;
  externalEmployeeId: string;
  email: string;
  firstName: string;
  lastName: string;
  isActive: boolean;
  createdAt: Date;
  updatedAt: Date;
}): Customer {
  return {
    id: record.id,
    externalEmployeeId: record.externalEmployeeId,
    email: record.email,
    firstName: record.firstName,
    lastName: record.lastName,
    isActive: record.isActive,
    createdAt: record.createdAt,
    updatedAt: record.updatedAt
  };
}

export class PrismaCustomerRepository implements CustomerRepository {
  async create(input: CreateCustomerInput): Promise<Customer> {
    const created = await prisma.customer.create({
      data: {
        externalEmployeeId: input.externalEmployeeId,
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName
      }
    });

    return mapToDomain(created);
  }

  async findById(id: string): Promise<Customer | null> {
    const found = await prisma.customer.findUnique({ where: { id } });
    return found ? mapToDomain(found) : null;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    const found = await prisma.customer.findUnique({ where: { email } });
    return found ? mapToDomain(found) : null;
  }
}
```

