# 22. Better enterprise-grade dependency wiring

A more scalable approach is to create a composition root.

## `src/app/container.ts`

```ts
import { CustomerService } from "../domain/customer/customer.service.js";
import { MockHrSystemClient } from "../infrastructure/clients/mock-hr-system.client.js";
import { MockIdentityClient } from "../infrastructure/clients/mock-identity.client.js";
import { PrismaCustomerRepository } from "../infrastructure/repositories/prisma-customer.repository.js";

export interface Container {
  customerService: CustomerService;
}

export function createContainer(): Container {
  const customerRepository = new PrismaCustomerRepository();
  const hrSystemClient = new MockHrSystemClient();
  const identityClient = new MockIdentityClient();

  const customerService = new CustomerService(
    customerRepository,
    hrSystemClient,
    identityClient
  );

  return {
    customerService
  };
}
```

Then routes use the container instead of constructing dependencies themselves.

