import { describe, expect, it } from "vitest";
import { CustomerService } from "./customer.service.js";
import type { CustomerRepository } from "./customer.repository.js";
import type { HrSystemClient } from "../../infrastructure/clients/hr-system.client.js";
import type { IdentityClient } from "../../infrastructure/clients/identity.client.js";
import type { Customer } from "./customer.types.js";

class InMemoryCustomerRepository implements CustomerRepository {
  private readonly items = new Map<string, Customer>();

  async create(input: {
    externalEmployeeId: string;
    email: string;
    firstName: string;
    lastName: string;
  }): Promise<Customer> {
    const customer: Customer = {
      id: crypto.randomUUID(),
      externalEmployeeId: input.externalEmployeeId,
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      isActive: true,
      createdAt: new Date(),
      updatedAt: new Date()
    };
    this.items.set(customer.id, customer);
    return customer;
  }

  async findById(id: string): Promise<Customer | null> {
    return this.items.get(id) ?? null;
  }

  async findByEmail(email: string): Promise<Customer | null> {
    for (const customer of this.items.values()) {
      if (customer.email === email) return customer;
    }
    return null;
  }
}

class FakeHrClient implements HrSystemClient {
  async getEmployeeById(employeeId: string) {
    return { employeeId, email: "test@corp.example.com", active: true };
  }
}

class FakeIdentityClient implements IdentityClient {
  async findUserByEmail(email: string) {
    return { id: "id-1", email, enabled: true };
  }
}

describe("CustomerService", () => {
  it("creates a customer when dependencies validate successfully", async () => {
    const service = new CustomerService(
      new InMemoryCustomerRepository(),
      new FakeHrClient(),
      new FakeIdentityClient()
    );

    const created = await service.createCustomer({
      externalEmployeeId: "EMP123",
      email: "test@corp.example.com",
      firstName: "Jane",
      lastName: "Doe"
    });

    expect(created.email).toBe("test@corp.example.com");
  });
});
