## src/integrations/corporate-directory/corporate-directory.client.ts

```ts
import { env } from "../../config/env.js";
import { IntegrationError } from "../../core/errors.js";
import type {
  CorporateDirectoryClient,
  CorporateDirectoryUser
} from "./corporate-directory.types.js";

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  async getUserByEmployeeId(employeeId: string): Promise<CorporateDirectoryUser | null> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), env.CORPORATE_DIRECTORY_TIMEOUT_MS);

    try {
      const response = await fetch(
        `${env.CORPORATE_DIRECTORY_BASE_URL}/users/${encodeURIComponent(employeeId)}`,
        {
          method: "GET",
          signal: controller.signal,
          headers: {
            "Content-Type": "application/json"
          }
        }
      );

      if (response.status === 404) {
        return null;
      }

      if (!response.ok) {
        throw new IntegrationError("Corporate directory request failed", {
          status: response.status
        });
      }

      const data = (await response.json()) as CorporateDirectoryUser;
      return data;
    } catch (error) {
      if (error instanceof IntegrationError) {
        throw error;
      }

      throw new IntegrationError("Corporate directory unavailable", {
        cause: error instanceof Error ? error.message : "unknown"
      });
    } finally {
      clearTimeout(timeout);
    }
  }
}
```

