## src/modules/customer/customer.repository.ts

```ts
import crypto from "node:crypto";
import type { Pool } from "pg";
import type {
  CreateCustomerInput,
  Customer,
  CustomerRepository
} from "./customer.types.js";

export class PostgresCustomerRepository implements CustomerRepository {
  constructor(private readonly pool: Pool) {}

  async create(input: CreateCustomerInput): Promise<Customer> {
    const id = crypto.randomUUID();
    const createdAt = new Date().toISOString();

    await this.pool.query(
      `
      INSERT INTO customers (id, external_ref, name, owner_employee_id, created_at)
      VALUES ($1, $2, $3, $4, $5)
      `,
      [id, input.externalRef, input.name, input.ownerEmployeeId, createdAt]
    );

    return {
      id,
      externalRef: input.externalRef,
      name: input.name,
      ownerEmployeeId: input.ownerEmployeeId,
      createdAt
    };
  }

  async findById(id: string): Promise<Customer | null> {
    const result = await this.pool.query<{
      id: string;
      external_ref: string;
      name: string;
      owner_employee_id: string;
      created_at: string;
    }>(
      `
      SELECT id, external_ref, name, owner_employee_id, created_at
      FROM customers
      WHERE id = $1
      `,
      [id]
    );

    const row = result.rows[0];
    if (!row) {
      return null;
    }

    return {
      id: row.id,
      externalRef: row.external_ref,
      name: row.name,
      ownerEmployeeId: row.owner_employee_id,
      createdAt: row.created_at
    };
  }

  async findByExternalRef(externalRef: string): Promise<Customer | null> {
    const result = await this.pool.query<{
      id: string;
      external_ref: string;
      name: string;
      owner_employee_id: string;
      created_at: string;
    }>(
      `
      SELECT id, external_ref, name, owner_employee_id, created_at
      FROM customers
      WHERE external_ref = $1
      `,
      [externalRef]
    );

    const row = result.rows[0];
    if (!row) {
      return null;
    }

    return {
      id: row.id,
      externalRef: row.external_ref,
      name: row.name,
      ownerEmployeeId: row.owner_employee_id,
      createdAt: row.created_at
    };
  }
}
```

## src/modules/customer/customer.service.ts

```ts
import { NotFoundError, ValidationError } from "../../core/errors.js";
import type { CorporateDirectoryClient } from "../../integrations/corporate-directory/corporate-directory.types.js";
import type {
  CreateCustomerInput,
  Customer,
  CustomerRepository
} from "./customer.types.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByExternalRef(input.externalRef);
    if (existing) {
      throw new ValidationError("Customer externalRef already exists", {
        externalRef: input.externalRef
      });
    }

    const owner = await this.corporateDirectoryClient.getUserByEmployeeId(input.ownerEmployeeId);
    if (!owner) {
      throw new ValidationError("Owner employee not found in corporate directory", {
        ownerEmployeeId: input.ownerEmployeeId
      });
    }

    return this.repository.create(input);
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError("Customer not found", { id });
    }

    return customer;
  }
}
```

