# 14. App composition

## src/app.ts

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { logger } from "./config/logger.js";
import { dbPool } from "./infrastructure/db.js";
import { HttpCorporateDirectoryClient } from "./integrations/corporate-directory/corporate-directory.client.js";
import authPlugin from "./plugins/auth.js";
import errorHandlerPlugin from "./plugins/error-handler.js";
import requestContextPlugin from "./plugins/request-context.js";
import { PostgresCustomerRepository } from "./modules/customer/customer.repository.js";
import { CustomerService } from "./modules/customer/customer.service.js";
import { registerCustomerRoutes } from "./modules/customer/customer.routes.js";

export async function buildApp() {
  const app = Fastify({
    logger
  });

  await app.register(sensible);
  await app.register(authPlugin);
  await app.register(requestContextPlugin);
  await app.register(errorHandlerPlugin);

  const customerRepository = new PostgresCustomerRepository(dbPool);
  const corporateDirectoryClient = new HttpCorporateDirectoryClient();
  const customerService = new CustomerService(customerRepository, corporateDirectoryClient);

  await registerCustomerRoutes(app, { customerService });

  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/ready", async (_request, reply) => {
    try {
      await dbPool.query("SELECT 1");
      reply.code(200).send({ status: "ready" });
    } catch {
      reply.code(503).send({ status: "not_ready" });
    }
  });

  return app;
}
```

