## `src/modules/customer/application/services/customer.service.ts`

```ts
import { Inject, Injectable, ConflictException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import {
  CUSTOMER_REPOSITORY,
  CustomerRepository
} from '../../domain/customer.repository';
import { Customer } from '../../domain/customer.entity';
import { CorporateMasterDataClient } from '../../infrastructure/corporate-master-data.client';
import { CreateCustomerCommand } from '../commands/create-customer.command';

@Injectable()
export class CustomerService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepository,
    private readonly corporateMasterDataClient: CorporateMasterDataClient
  ) {}

  async createCustomer(command: CreateCustomerCommand): Promise<Customer> {
    const existing = await this.customerRepository.findByExternalId(command.externalId);
    if (existing !== null) {
      throw new ConflictException(
        `Customer with externalId ${command.externalId} already exists`
      );
    }

    await this.corporateMasterDataClient.validateCustomerReference(command.externalId);

    const now = new Date();
    const customer = new Customer({
      id: randomUUID(),
      externalId: command.externalId,
      email: command.email,
      firstName: command.firstName,
      lastName: command.lastName,
      createdAt: now,
      updatedAt: now
    });

    return this.customerRepository.create(customer);
  }

  async getCustomerById(id: string): Promise<Customer | null> {
    return this.customerRepository.findById(id);
  }
}
```

