# 10. External corporate system adapter

This is where enterprise integration lives.

## `src/modules/customer/infrastructure/corporate-master-data.client.ts`

```ts
import { Injectable, ServiceUnavailableException } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';

interface CorporateCustomerLookupResponse {
  externalId: string;
  status: 'ACTIVE' | 'INACTIVE';
}

@Injectable()
export class CorporateMasterDataClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.CORPORATE_MASTER_DATA_URL,
      timeout: Number(process.env.CORPORATE_MASTER_DATA_TIMEOUT_MS ?? 3000)
    });
  }

  async validateCustomerReference(externalId: string): Promise<void> {
    try {
      const response = await this.client.get<CorporateCustomerLookupResponse>(
        `/customers/${encodeURIComponent(externalId)}`
      );

      if (response.data.status !== 'ACTIVE') {
        throw new ServiceUnavailableException(
          `Corporate customer reference ${externalId} is not active`
        );
      }
    } catch (error: unknown) {
      throw new ServiceUnavailableException(
        `Failed to validate customer reference ${externalId}`
      );
    }
  }
}
```

In a real enterprise environment, this client should also include:

- mTLS support
- OAuth2 client credentials
- retry/backoff
- circuit breaker
- structured logging
- correlation ID propagation

