# 12. Controller

## `src/modules/customer/api/customer.controller.ts`

```ts
import {
  Body,
  Controller,
  Get,
  NotFoundException,
  Param,
  Post
} from '@nestjs/common';
import { CustomerService } from '../application/services/customer.service';
import {
  createCustomerRequestSchema,
  CreateCustomerRequest
} from './dto/create-customer.request';
import { CustomerResponse } from './dto/customer.response';
import { Customer } from '../domain/customer.entity';

@Controller('customers')
export class CustomerController {
  constructor(private readonly customerService: CustomerService) {}

  @Post()
  async createCustomer(
    @Body() body: CreateCustomerRequest
  ): Promise<CustomerResponse> {
    const request = createCustomerRequestSchema.parse(body);
    const customer = await this.customerService.createCustomer(request);
    return this.toResponse(customer);
  }

  @Get(':id')
  async getCustomer(@Param('id') id: string): Promise<CustomerResponse> {
    const customer = await this.customerService.getCustomerById(id);
    if (customer === null) {
      throw new NotFoundException(`Customer ${id} not found`);
    }

    return this.toResponse(customer);
  }

  private toResponse(customer: Customer): CustomerResponse {
    return {
      id: customer.id,
      externalId: customer.externalId,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }
}
```

