# 7. Corporate integration client abstraction

This is important for enterprise systems because outbound dependencies should be isolated behind interfaces.

## `src/infra/integrations/corporate-directory.client.ts`

```ts
import { z } from "zod";
import { UpstreamDependencyError } from "../../core/errors.js";

const CorporateDirectoryEmployeeSchema = z.object({
  id: z.string().min(1),
  email: z.string().email(),
  department: z.string().min(1),
  active: z.boolean()
});

export type CorporateDirectoryEmployee = z.infer<typeof CorporateDirectoryEmployeeSchema>;

export interface CorporateDirectoryClient {
  getEmployeeProfile(employeeId: string): Promise<CorporateDirectoryEmployee | null>;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  public constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string
  ) {}

  public async getEmployeeProfile(employeeId: string): Promise<CorporateDirectoryEmployee | null> {
    const response = await fetch(`${this.baseUrl}/employees/${encodeURIComponent(employeeId)}`, {
      method: "GET",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.apiKey
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new UpstreamDependencyError(
        `Corporate directory request failed with status ${response.status}`
      );
    }

    const json: unknown = await response.json();
    return CorporateDirectoryEmployeeSchema.parse(json);
  }
}
```

