# 10. Application service

## `src/modules/employees/application/employee.service.ts`

```ts
import { NotFoundError } from "../../../core/errors.js";
import type { EmployeeRepository } from "../domain/employee.repository.js";
import type { Employee } from "../domain/employee.js";
import type { CorporateDirectoryClient } from "../../../infra/integrations/corporate-directory.client.js";
import type { EmployeeId, ISODateString } from "../../../core/types.js";

export interface CreateEmployeeInput {
  readonly id: EmployeeId;
  readonly firstName: string;
  readonly lastName: string;
}

export interface EmployeeDetails {
  readonly id: EmployeeId;
  readonly firstName: string;
  readonly lastName: string;
  readonly createdAt: ISODateString;
  readonly corporateProfile: {
    readonly email: string;
    readonly department: string;
    readonly active: boolean;
  } | null;
}

export class EmployeeService {
  public constructor(
    private readonly employeeRepository: EmployeeRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  public async getEmployeeDetails(id: string): Promise<EmployeeDetails> {
    const employee = await this.employeeRepository.getById(id);

    if (employee === null) {
      throw new NotFoundError(`Employee ${id} not found`);
    }

    const corporateProfile = await this.corporateDirectoryClient.getEmployeeProfile(id);

    return {
      id: employee.id,
      firstName: employee.firstName,
      lastName: employee.lastName,
      createdAt: employee.createdAt,
      corporateProfile: corporateProfile
        ? {
            email: corporateProfile.email,
            department: corporateProfile.department,
            active: corporateProfile.active
          }
        : null
    };
  }

  public async listEmployees(): Promise<readonly Employee[]> {
    return this.employeeRepository.list();
  }

  public async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    const employee: Employee = {
      id: input.id,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString() as ISODateString
    };

    return this.employeeRepository.create(employee);
  }
}
```

