```ts
import type { FastifyInstance } from "fastify";
import { EmployeeParamsSchema, CreateEmployeeBodySchema } from "./employee.schemas.js";
import type { EmployeeService } from "../application/employee.service.js";

export async function employeeRoutes(
  fastify: FastifyInstance,
  deps: { readonly employeeService: EmployeeService }
): Promise<void> {
  fastify.get("/employees", async (_request, reply) => {
    const employees = await deps.employeeService.listEmployees();
    return reply.code(200).send(employees);
  });

  fastify.get("/employees/:id", async (request, reply) => {
    const params = EmployeeParamsSchema.parse(request.params);
    const employee = await deps.employeeService.getEmployeeDetails(params.id);
    return reply.code(200).send(employee);
  });

  fastify.post("/employees", async (request, reply) => {
    const body = CreateEmployeeBodySchema.parse(request.body);
    const employee = await deps.employeeService.createEmployee({
      id: body.id as never,
      firstName: body.firstName,
      lastName: body.lastName
    });

    return reply.code(201).send(employee);
  });
}
