# 13. HTTP error handling

## `src/infra/http/error-handler.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import { AppError, InternalServerError } from "../../core/errors.js";

export function registerErrorHandler(fastify: FastifyInstance): void {
  fastify.setErrorHandler(
    (error: Error, request: FastifyRequest, reply: FastifyReply): void => {
      if (error instanceof ZodError) {
        request.log.warn({ err: error }, "Request validation failed");
        void reply.status(400).send({
          code: "VALIDATION_ERROR",
          message: "Request validation failed",
          details: error.issues
        });
        return;
      }

      if (error instanceof AppError) {
        request.log.warn({ err: error }, "Application error");
        void reply.status(error.statusCode).send({
          code: error.code,
          message: error.message
        });
        return;
      }

      const internalError = new InternalServerError("An unexpected error occurred");
      request.log.error({ err: error }, "Unhandled error");
      void reply.status(internalError.statusCode).send({
        code: internalError.code,
        message: internalError.message
      });
    }
  );
}
```

