```ts
import Fastify, { type FastifyInstance } from "fastify";
import sensible from "@fastify/sensible";
import { loadEnv, type Env } from "./config/env.js";
import { createLogger } from "./infra/logging/logger.js";
import { registerErrorHandler } from "./infra/http/error-handler.js";
import { registerRequestContext } from "./infra/http/request-context.js";
import { registerSecurity } from "./plugins/security.js";
import { HttpCorporateDirectoryClient } from "./infra/integrations/corporate-directory.client.js";
import { InMemoryEmployeeRepository } from "./modules/employees/infra/in-memory-employee.repository.js";
import { EmployeeService } from "./modules/employees/application/employee.service.js";
import { employeeRoutes } from "./modules/employees/api/employee.routes.js";

export interface AppDependencies {
  readonly env: Env;
}

export async function buildApp(
  dependencies?: Partial<AppDependencies>
): Promise<FastifyInstance> {
  const env = dependencies?.env ?? loadEnv();
  const logger = createLogger(env);

  const app = Fastify({
    logger
  });

  await app.register(sensible);
  await registerSecurity(app);
  await registerRequestContext(app);

  const employeeRepository = new InMemoryEmployeeRepository();
  const corporateDirectoryClient = new HttpCorporateDirectoryClient(
    env.CORPORATE_DIRECTORY_BASE_URL,
    env.CORPORATE_DIRECTORY_API_KEY
  );
  const employeeService = new EmployeeService(
    employeeRepository,
    corporateDirectoryClient
  );

  app.get("/health", async () => {
    return {
      status: "ok",
      service: env.SERVICE_NAME
    };
  });

  app.get("/ready", async () => {
    return {
      status: "ready"
    };
  });

  await employeeRoutes(app, { employeeService });

  registerErrorHandler(app);

  return app;
}
```

