# 8. Repository Abstraction

## `src/infrastructure/persistence/customer-repository.ts`

```ts
import { Customer, CreateCustomerCommand, UpdateCustomerCommand } from "../../domain/customer.js";
import { CustomerId, toCustomerId, toISODateString } from "../../shared/types.js";

export interface CustomerRepository {
  findById(id: CustomerId): Promise<Customer | null>;
  create(command: CreateCustomerCommand): Promise<Customer>;
  update(id: CustomerId, command: UpdateCustomerCommand): Promise<Customer | null>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly store = new Map<CustomerId, Customer>();

  async findById(id: CustomerId): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }

  async create(command: CreateCustomerCommand): Promise<Customer> {
    const now = new Date().toISOString();
    const customer: Customer = {
      id: toCustomerId(crypto.randomUUID()),
      firstName: command.firstName,
      lastName: command.lastName,
      email: command.email,
      department: command.department,
      createdAt: toISODateString(now),
      updatedAt: toISODateString(now)
    };

    this.store.set(customer.id, customer);
    return customer;
  }

  async update(id: CustomerId, command: UpdateCustomerCommand): Promise<Customer | null> {
    const existing = this.store.get(id);
    if (!existing) {
      return null;
    }

    const updated: Customer = {
      ...existing,
      ...command,
      updatedAt: toISODateString(new Date().toISOString())
    };

    this.store.set(id, updated);
    return updated;
  }
}
```

