# 10. Application Service Layer

## `src/application/customer-service.ts`

```ts
import { CreateCustomerCommand, Customer, UpdateCustomerCommand } from "../domain/customer.js";
import { NotFoundError, ValidationError } from "../domain/errors.js";
import { CustomerRepository } from "../infrastructure/persistence/customer-repository.js";
import { CorporateDirectoryClient } from "../infrastructure/integrations/corporate-directory-client.js";
import { CustomerId } from "../shared/types.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly directoryClient: CorporateDirectoryClient
  ) {}

  async getCustomerById(id: CustomerId): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer with id '${id}' was not found`);
    }
    return customer;
  }

  async createCustomer(command: CreateCustomerCommand): Promise<Customer> {
    const directoryRecord = await this.directoryClient.lookupByEmail(command.email);

    if (directoryRecord && !directoryRecord.isActive) {
      throw new ValidationError("Cannot create customer for inactive corporate directory user");
    }

    const enrichedCommand: CreateCustomerCommand = {
      ...command,
      department: command.department ?? directoryRecord?.department
    };

    return this.repository.create(enrichedCommand);
  }

  async updateCustomer(id: CustomerId, command: UpdateCustomerCommand): Promise<Customer> {
    const updated = await this.repository.update(id, command);
    if (!updated) {
      throw new NotFoundError(`Customer with id '${id}' was not found`);
    }
    return updated;
  }
}
```

