## `src/interfaces/http/routes/customer-routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { CustomerService } from "../../../application/customer-service.js";
import {
  createCustomerBodySchema,
  customerIdParamsSchema,
  updateCustomerBodySchema
} from "../schemas/customer-schemas.js";
import { toCustomerId } from "../../../shared/types.js";
import { authenticate } from "../middleware/auth.js";

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.addHook("preHandler", authenticate);

  app.get("/customers/:id", async (request) => {
    const params = customerIdParamsSchema.parse(request.params);
    return customerService.getCustomerById(toCustomerId(params.id));
  });

  app.post("/customers", async (request, reply) => {
    const body = createCustomerBodySchema.parse(request.body);
    const customer = await customerService.createCustomer(body);
    reply.status(201);
    return customer;
  });

  app.patch("/customers/:id", async (request) => {
    const params = customerIdParamsSchema.parse(request.params);
    const body = updateCustomerBodySchema.parse(request.body);
    return customerService.updateCustomer(toCustomerId(params.id), body);
  });
}
```

