# 16. App Composition

## `src/app.ts`

```ts
import Fastify, { FastifyInstance } from "fastify";
import sensible from "@fastify/sensible";
import { AppConfig } from "./config/env.js";
import { createLogger } from "./infrastructure/logging/logger.js";
import { InMemoryCustomerRepository } from "./infrastructure/persistence/customer-repository.js";
import { StubCorporateDirectoryClient } from "./infrastructure/integrations/corporate-directory-client.js";
import { CustomerService } from "./application/customer-service.js";
import { registerHealthRoutes } from "./interfaces/http/routes/health-routes.js";
import { registerCustomerRoutes } from "./interfaces/http/routes/customer-routes.js";
import { registerErrorHandler } from "./interfaces/http/middleware/error-handler.js";

export async function buildApp(config: AppConfig): Promise<FastifyInstance> {
  const logger = createLogger(config);

  const app = Fastify({
    logger
  });

  await app.register(sensible);

  const repository = new InMemoryCustomerRepository();
  const directoryClient = new StubCorporateDirectoryClient();
  const customerService = new CustomerService(repository, directoryClient);

  registerErrorHandler(app);

  await registerHealthRoutes(app);
  await registerCustomerRoutes(app, customerService);

  return app;
}
```

