# 7. Application service

## `src/application/services/customer.service.ts`

```ts
import type { CustomerRepository } from "../ports/customer.repository.js";
import type { CrmGateway } from "../ports/crm.gateway.js";
import type { CreateCustomerInput, Customer } from "../../domain/customer.js";
import { CustomerAlreadyExistsError, CustomerNotFoundError } from "../../domain/errors.js";

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly crmGateway: CrmGateway
  ) {}

  public async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);

    if (existing) {
      throw new CustomerAlreadyExistsError(input.email);
    }

    const customer = await this.customerRepository.create(input);

    await this.crmGateway.syncCustomer(customer);

    return customer;
  }

  public async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);

    if (!customer) {
      throw new CustomerNotFoundError(id);
    }

    return customer;
  }
}
```

This service is:
- strongly typed
- isolated from HTTP
- isolated from Prisma
- isolated from external CRM implementation

That is exactly what you want in enterprise code.

