# 9. HTTP handlers

## `src/api/handlers/customer.handlers.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import type { CustomerService } from "../../application/services/customer.service.js";
import { createCustomerBodySchema } from "../schemas/customer.schemas.js";
import { CustomerAlreadyExistsError, CustomerNotFoundError } from "../../domain/errors.js";

type CreateCustomerRequest = FastifyRequest<{
  Body: {
    email: string;
    firstName: string;
    lastName: string;
  };
}>;

type GetCustomerRequest = FastifyRequest<{
  Params: {
    id: string;
  };
}>;

export class CustomerHandlers {
  public constructor(private readonly customerService: CustomerService) {}

  public createCustomer = async (
    request: CreateCustomerRequest,
    reply: FastifyReply
  ): Promise<void> => {
    const body = createCustomerBodySchema.parse(request.body);

    try {
      const customer = await this.customerService.createCustomer(body);

      reply.status(201).send({
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        createdAt: customer.createdAt.toISOString(),
        updatedAt: customer.updatedAt.toISOString()
      });
    } catch (error: unknown) {
      if (error instanceof CustomerAlreadyExistsError) {
        reply.status(409).send({
          code: error.code,
          message: error.message
        });
        return;
      }

      throw error;
    }
  };

  public getCustomerById = async (
    request: GetCustomerRequest,
    reply: FastifyReply
  ): Promise<void> => {
    try {
      const customer = await this.customerService.getCustomerById(request.params.id);

      reply.status(200).send({
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        createdAt: customer.createdAt.toISOString(),
        updatedAt: customer.updatedAt.toISOString()
      });
    } catch (error: unknown) {
      if (error instanceof CustomerNotFoundError) {
        reply.status(404).send({
          code: error.code,
          message: error.message
        });
        return;
      }

      throw error;
    }
  };
}
```

