# 14. External corporate system integration

This simulates calling an enterprise CRM or master data platform.

## `src/infrastructure/gateways/crm.gateway.http.ts`

```ts
import type { CrmGateway } from "../../application/ports/crm.gateway.js";
import type { Customer } from "../../domain/customer.js";

interface CrmHttpClientConfig {
  baseUrl: string;
  apiKey: string;
}

export class HttpCrmGateway implements CrmGateway {
  public constructor(private readonly config: CrmHttpClientConfig) {}

  public async syncCustomer(customer: Customer): Promise<void> {
    const response = await fetch(`${this.config.baseUrl}/customers/sync`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.config.apiKey
      },
      body: JSON.stringify({
        id: customer.id,
        email: customer.email,
        firstName: customer.firstName,
        lastName: customer.lastName,
        createdAt: customer.createdAt.toISOString(),
        updatedAt: customer.updatedAt.toISOString()
      })
    });

    if (!response.ok) {
      throw new Error(`CRM sync failed with status ${response.status}`);
    }
  }
}
```

