# 15. Fastify app composition

## `src/app.ts`

```ts
import Fastify, { type FastifyInstance } from "fastify";
import { loadEnv } from "./infrastructure/config/env.js";
import { createLogger } from "./infrastructure/logging/logger.js";
import { createPrismaClient } from "./infrastructure/db/prisma.js";
import { PrismaCustomerRepository } from "./infrastructure/db/customer.repository.prisma.js";
import { HttpCrmGateway } from "./infrastructure/gateways/crm.gateway.http.js";
import { CustomerService } from "./application/services/customer.service.js";
import { CustomerHandlers } from "./api/handlers/customer.handlers.js";
import { registerCustomerRoutes } from "./api/routes/customer.routes.js";
import { registerHealthRoutes } from "./api/routes/health.routes.js";

export async function buildApp(): Promise<FastifyInstance> {
  const env = loadEnv();
  const logger = createLogger(env);
  const prisma = createPrismaClient();

  const customerRepository = new PrismaCustomerRepository(prisma);
  const crmGateway = new HttpCrmGateway({
    baseUrl: env.CRM_BASE_URL,
    apiKey: env.CRM_API_KEY
  });

  const customerService = new CustomerService(customerRepository, crmGateway);
  const customerHandlers = new CustomerHandlers(customerService);

  const app = Fastify({
    logger
  });

  app.get("/", async () => {
    return { service: "enterprise-microservice" };
  });

  await registerHealthRoutes(app);
  await registerCustomerRoutes(app, customerHandlers);

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
```

