```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { Customer } from './domain/customer';
import { CreateCustomerRecord, CustomersRepository } from './customers.repository';

@Injectable()
export class InMemoryCustomersRepository extends CustomersRepository {
  private readonly customers = new Map<string, Customer>();

  public async create(input: CreateCustomerRecord): Promise<Customer> {
    const customer: Customer = {
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      externalErpId: input.externalErpId,
      createdAt: new Date()
    };

    this.customers.set(customer.id, customer);
    return customer;
