```ts
import { HttpService } from '@nestjs/axios';
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { firstValueFrom } from 'rxjs';
import { ErpCustomerRequest, ErpCustomerResponse } from '../interfaces/erp.types';

interface AppConfig {
  ERP_BASE_URL: string;
  ERP_API_KEY: string;
}

@Injectable()
export class ErpClient {
  public constructor(
    private readonly httpService: HttpService,
    private readonly configService: ConfigService<AppConfig, true>
  ) {}

  public async createCustomer(input: ErpCustomerRequest): Promise<ErpCustomerResponse> {
    const baseUrl = this.configService.get('ERP_BASE_URL', { infer: true });
    const apiKey = this.configService.get('ERP_API_KEY', { infer: true });

    try {
      const response = await firstValueFrom(
        this.httpService.post<ErpCustomerResponse>(
          `${baseUrl}/customers`,
          input,
          {
            headers: {
              'x-api-key': apiKey
            },
            timeout: 5000
          }
        )
      );

      return response.data;
    } catch (error: unknown) {
      throw new InternalServerErrorException('Failed to create customer in ERP system');
    }
  }
}
```

