import { Injectable } from '@nestjs/common';
import { ErpClient } from '../corporate-integration/clients/erp.client';
import { Customer } from './domain/customer';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CreateCustomerRecord, CustomersRepository } from './customers.repository';

@Injectable()
export class CustomersService {
  public constructor(
    private readonly customersRepository: CustomersRepository,
    private readonly erpClient: ErpClient
  ) {}

  public async createCustomer(dto: CreateCustomerDto): Promise<Customer> {
    let externalErpId = dto.externalErpId;

    if (externalErpId === undefined) {
      const erpResponse = await this.erpClient.createCustomer({
        emailAddress: dto.email,
        givenName: dto.firstName,
        familyName: dto.lastName
      });

      externalErpId = erpResponse.customerId;
    }

    const record: CreateCustomerRecord = {
      email: dto.email,
      firstName: dto.firstName,
      lastName: dto.lastName,
      externalErpId
    };

    return this.customersRepository.create(record);
  }

  public async getCustomerById(id: string): Promise<Customer | null> {
    return this.customersRepository.findById(id);
  }
}
