## `src/domain/customer/customer.service.ts`

```ts
import { randomUUID } from "node:crypto";
import type { CustomerRepository } from "./customer.repository.js";
import type { CreateCustomerRequest, Customer } from "./customer.types.js";
import type { ERPClient } from "../../integrations/erp/erp.client.js";
import { err, ok, type Result } from "../../shared/result.js";
import { NotFoundError, UpstreamServiceError } from "../../shared/errors.js";
import type { CustomerId, ISODateString } from "../../shared/types.js";

export class CustomerService {
  public constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly erpClient: ERPClient
  ) {}

  public async getCustomerById(id: string): Promise<Result<Customer, NotFoundError>> {
    const customer = await this.customerRepository.findById(id);

    if (customer === null) {
      return err(new NotFoundError(`Customer with id '${id}' was not found`));
    }

    return ok(customer);
  }

  public async createCustomer(
    input: CreateCustomerRequest
  ): Promise<Result<Customer, UpstreamServiceError>> {
    const erpResult = await this.erpClient.createCustomerProfile({
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName
    });

    if (!erpResult.ok) {
      return err(new UpstreamServiceError(`Failed to create ERP customer profile: ${erpResult.error}`));
    }

    const now = new Date().toISOString() as ISODateString;
    const customer: Customer = {
      id: randomUUID() as CustomerId,
      externalErpId: erpResult.value.erpCustomerId,
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: now
    };

    const created = await this.customerRepository.create(customer);
    return ok(created);
  }
}
```

