## `src/domain/customer/customer.controller.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { createCustomerRequestSchema } from "./customer.types.js";
import { ValidationError } from "../../shared/errors.js";
import type { CustomerService } from "./customer.service.js";

type GetCustomerParams = {
  id: string;
};

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get(
    "/customers/:id",
    async (
      request: FastifyRequest<{ Params: GetCustomerParams }>,
      reply: FastifyReply
    ) => {
      const result = await customerService.getCustomerById(request.params.id);

      if (!result.ok) {
        throw result.error;
      }

      return reply.code(200).send(result.value);
    }
  );

  app.post(
    "/customers",
    async (
      request: FastifyRequest<{ Body: unknown }>,
      reply: FastifyReply
    ) => {
      const parsed = createCustomerRequestSchema.safeParse(request.body);

      if (!parsed.success) {
        throw new ValidationError(parsed.error.message);
      }

      const result = await customerService.createCustomer(parsed.data);

      if (!result.ok) {
        throw result.error;
      }

      return reply.code(201).send(result.value);
    }
  );
}
```

