# 8. Request Context / Correlation ID Plugin

This is important in enterprise systems for tracing requests across services.

## `src/plugins/requestContext.ts`

```ts
import { randomUUID } from 'node:crypto';
import fp from 'fastify-plugin';
import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';

declare module 'fastify' {
  interface FastifyRequest {
    correlationId: string;
  }
}

export default fp(async function requestContextPlugin(app: FastifyInstance) {
  app.addHook('onRequest', async (request: FastifyRequest, reply: FastifyReply) => {
    const incomingCorrelationId = request.headers['x-correlation-id'];
    const correlationId =
      typeof incomingCorrelationId === 'string' && incomingCorrelationId.length > 0
        ? incomingCorrelationId
        : randomUUID();

    request.correlationId = correlationId;
    reply.header('x-correlation-id', correlationId);
  });
});
```

You’ll need:

```bash
npm install fastify-plugin
```

