# 10. Corporate System Integration Client

This abstracts an existing corporate upstream API and validates its responses.

## `src/integrations/corporateCustomerClient.ts`

```ts
import axios, { AxiosInstance, AxiosError } from 'axios';
import { z } from 'zod';
import { env } from '../config/env.js';
import { CustomerSchema, type Customer, type CustomerId } from '../domain/customer.js';
import { NotFoundError, UpstreamServiceError } from '../domain/errors.js';

const upstreamCustomerSchema = z.object({
  customer_id: z.string(),
  given_name: z.string(),
  family_name: z.string(),
  email_address: z.string().email().nullable(),
  lifecycle_status: z.enum(['ACTIVE', 'INACTIVE', 'SUSPENDED'])
});

type UpstreamCustomer = z.infer<typeof upstreamCustomerSchema>;

export class CorporateCustomerClient {
  private readonly httpClient: AxiosInstance;

  constructor() {
    this.httpClient = axios.create({
      baseURL: env.CORPORATE_CUSTOMER_API_BASE_URL,
      timeout: env.CORPORATE_CUSTOMER_API_TIMEOUT_MS,
      headers: {
        'x-api-key': env.CORPORATE_API_KEY,
        'content-type': 'application/json'
      }
    });
  }

  async getCustomerById(customerId: CustomerId, correlationId: string): Promise<Customer> {
    try {
      const response = await this.httpClient.get(`/customers/${encodeURIComponent(customerId)}`, {
        headers: {
          'x-correlation-id': correlationId
        }
      });

      const parsed = upstreamCustomerSchema.safeParse(response.data);

      if (!parsed.success) {
        throw new UpstreamServiceError('Invalid response received from corporate customer API', {
          validationIssues: parsed.error.issues
        });
      }

      return this.mapToDomain(parsed.data);
    } catch (error: unknown) {
      if (error instanceof NotFoundError || error instanceof UpstreamServiceError) {
        throw error;
      }

      if (this.isAxiosError(error)) {
        if (error.response?.status === 404) {
          throw new NotFoundError(`Customer not found: ${customerId}`);
        }

        throw new UpstreamServiceError('Corporate customer API request failed', {
          status: error.response?.status,
          responseBody: error.response?.data,
          message: error.message
        });
      }

      throw new UpstreamServiceError('Unexpected error calling corporate customer API', error);
    }
  }

  private mapToDomain(upstream: UpstreamCustomer): Customer {
    return CustomerSchema.parse({
      id: upstream.customer_id,
      firstName: upstream.given_name,
      lastName: upstream.family_name,
      email: upstream.email_address,
      status: upstream.lifecycle_status
    });
  }

  private isAxiosError(error: unknown): error is AxiosError {
    return axios.isAxiosError(error);
  }
}
```

