```ts
import type { FastifyInstance, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { CustomerIdSchema } from '../domain/customer.js';
import { ValidationError } from '../domain/errors.js';
import type { CustomerService } from '../services/customerService.js';

const paramsSchema = z.object({
  customerId: CustomerIdSchema
});

type CustomerRouteDeps = {
  customerService: CustomerService;
};

export async function customerRoutes(app: FastifyInstance, deps: CustomerRouteDeps): Promise<void> {
  app.get(
    '/api/v1/customers/:customerId',
    async (request: FastifyRequest<{ Params: { customerId: string } }>) => {
      const parsedParams = paramsSchema.safeParse(request.params);

      if (!parsedParams.success) {
        throw new ValidationError('Invalid customerId', parsedParams.error.issues);
      }

      const customer = await deps.customerService.getCustomerById(
        parsedParams.data.customerId,
        request.correlationId
      );

      return {
        data: customer
      };
    }
  );
}
```

