# 13. Application Composition

## `src/app.ts`

```ts
import Fastify, { type FastifyInstance } from 'fastify';
import requestContextPlugin from './plugins/requestContext.js';
import errorHandlerPlugin from './plugins/errorHandler.js';
import { logger } from './utils/logger.js';
import { healthRoutes } from './routes/healthRoutes.js';
import { customerRoutes } from './routes/customerRoutes.js';
import { CorporateCustomerClient } from './integrations/corporateCustomerClient.js';
import { CustomerService } from './services/customerService.js';

export async function buildApp(): Promise<FastifyInstance> {
  const app = Fastify({
    logger
  });

  await app.register(requestContextPlugin);
  await app.register(errorHandlerPlugin);

  const corporateCustomerClient = new CorporateCustomerClient();
  const customerService = new CustomerService(corporateCustomerClient);

  await app.register(healthRoutes);
  await app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  return app;
}
```

