```ts
import { crmCustomerSchema, type CrmClient, type CrmCustomer } from "./crm.types.js";

export class HttpCrmClient implements CrmClient {
  constructor(
    private readonly config: {
      baseUrl: string;
      apiKey: string;
    }
  ) {}

  async createCustomer(input: {
    emailAddress: string;
    givenName: string;
    surname: string;
    correlationId: string;
  }): Promise<CrmCustomer> {
    const response = await fetch(`${this.config.baseUrl}/customers`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": this.config.apiKey,
        "x-correlation-id": input.correlationId
      },
      body: JSON.stringify({
        emailAddress: input.emailAddress,
        givenName: input.givenName,
        surname: input.surname
      })
    });

    if (!response.ok) {
      throw new Error(`CRM request failed with status ${response.status}`);
    }

    const json: unknown = await response.json();
    return crmCustomerSchema.parse(json);
  }
}
