## `src/modules/customer/customer.service.ts`

```ts
import { randomUUID } from "node:crypto";
import { AppError } from "../../common/errors/app-error.js";
import type { CrmAdapter } from "../../integrations/corporate-crm/crm.adapter.js";
import type { CreateCustomerRequest } from "./customer.schemas.js";
import type { Customer } from "./customer.types.js";
import type { CustomerRepository } from "./customer.repository.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmAdapter: CrmAdapter
  ) {}

  async createCustomer(
    input: CreateCustomerRequest,
    correlationId: string
  ): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new AppError({
        code: "CUSTOMER_ALREADY_EXISTS",
        message: "Customer with this email already exists",
        statusCode: 409
      });
    }

    const customer = await this.repository.create({
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName
    });

    await this.crmAdapter.syncCustomer(customer, correlationId);

    return customer;
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);

    if (!customer) {
      throw new AppError({
        code: "CUSTOMER_NOT_FOUND",
        message: "Customer not found",
        statusCode: 404
      });
    }

    return customer;
  }
}
```

