## `src/modules/customer/customer.controller.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import {
  createCustomerRequestSchema,
  customerIdSchema,
  customerResponseSchema
} from "./customer.schemas.js";
import type { CustomerService } from "./customer.service.js";

function mapCustomerResponse(customer: {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  createdAt: Date;
  updatedAt: Date;
}) {
  return customerResponseSchema.parse({
    id: customer.id,
    email: customer.email,
    firstName: customer.firstName,
    lastName: customer.lastName,
    createdAt: customer.createdAt.toISOString(),
    updatedAt: customer.updatedAt.toISOString()
  });
}

export class CustomerController {
  constructor(private readonly service: CustomerService) {}

  createCustomer = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const body = createCustomerRequestSchema.parse(request.body);
    const customer = await this.service.createCustomer(body, request.correlationId);
    reply.status(201).send(mapCustomerResponse(customer));
  };

  getCustomerById = async (
    request: FastifyRequest<{ Params: { id: string } }>,
    reply: FastifyReply
  ): Promise<void> => {
    const params = customerIdSchema.parse(request.params.id);
    const customer = await this.service.getCustomerById(params);
    reply.status(200).send(mapCustomerResponse(customer));
  };
}
```

