# 6. App composition

## `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { env } from "./config/env.js";
import { logger } from "./config/logger.js";
import { registerErrorHandler } from "./common/errors/error-handler.js";
import { registerRequestContext } from "./common/http/request-context.js";
import { prisma } from "./infrastructure/db/prisma.js";
import { CustomerRepository } from "./modules/customer/customer.repository.js";
import { CustomerService } from "./modules/customer/customer.service.js";
import { CustomerController } from "./modules/customer/customer.controller.js";
import { registerCustomerRoutes } from "./modules/customer/customer.routes.js";
import { HttpCrmClient } from "./integrations/corporate-crm/crm.client.js";
import { CrmAdapter } from "./integrations/corporate-crm/crm.adapter.js";

export async function buildApp() {
  const app = Fastify({
    logger
  });

  await app.register(sensible);

  registerRequestContext(app);
  registerErrorHandler(app);

  const crmClient = new HttpCrmClient({
    baseUrl: env.CRM_BASE_URL,
    apiKey: env.CRM_API_KEY
  });

  const crmAdapter = new CrmAdapter(crmClient);
  const customerRepository = new CustomerRepository(prisma);
  const customerService = new CustomerService(customerRepository, crmAdapter);
  const customerController = new CustomerController(customerService);

  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/ready", async (_request, reply) => {
    try {
      await prisma.$queryRaw`SELECT 1`;
      reply.status(200).send({ status: "ready" });
    } catch {
      reply.status(503).send({ status: "not_ready" });
    }
  });

  await registerCustomerRoutes(app, customerController);

  return app;
}
```

