## `src/infrastructure/integrations/corporateCrmClient.ts`

```ts
import { env } from "../../config/env.js";
import { IntegrationError } from "../../domain/errors.js";

export interface CorporateCrmRecord {
  externalId: string;
  lifecycleState: "PROSPECT" | "CUSTOMER" | "SUSPENDED";
}

export interface CorporateCrmClient {
  syncCustomer(customerId: string, email: string): Promise<CorporateCrmRecord>;
}

export class HttpCorporateCrmClient implements CorporateCrmClient {
  async syncCustomer(customerId: string, email: string): Promise<CorporateCrmRecord> {
    const response = await fetch(`${env.CORPORATE_CRM_BASE_URL}/api/customers/sync`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": env.CORPORATE_CRM_API_KEY
      },
      body: JSON.stringify({
        customerId,
        email
      })
    }).catch((error: unknown) => {
      throw new IntegrationError(
        `Failed to reach corporate CRM: ${error instanceof Error ? error.message : "unknown error"}`
      );
    });

    if (!response.ok) {
      throw new IntegrationError(`Corporate CRM returned status ${response.status}`);
    }

    const json: unknown = await response.json();

    if (
      typeof json !== "object" ||
      json === null ||
      !("externalId" in json) ||
      !("lifecycleState" in json)
    ) {
      throw new IntegrationError("Corporate CRM returned invalid payload");
    }

    const payload = json as CorporateCrmRecord;
    return payload;
  }
}
```

