# 9. Service Layer

## `src/services/customerService.ts`

```ts
import type { CreateCustomerInput, Customer } from "../domain/customer.js";
import { ConflictError, NotFoundError } from "../domain/errors.js";
import type { CorporateCrmClient } from "../infrastructure/integrations/corporateCrmClient.js";
import type { CustomerRepository } from "../infrastructure/persistence/customerRepository.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer with id '${id}' was not found`);
    }
    return customer;
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new ConflictError(`Customer with email '${input.email}' already exists`);
    }

    const customer = await this.repository.create(input);

    await this.crmClient.syncCustomer(customer.id, customer.email);

    return customer;
  }
}
