# 14. Request Context Plugin

A common enterprise requirement is correlation IDs for tracing across systems.

## `src/plugins/requestContext.ts`

```ts
import fp from "fastify-plugin";
import type { FastifyInstance, FastifyRequest } from "fastify";

function getOrCreateCorrelationId(request: FastifyRequest): string {
  const header = request.headers["x-correlation-id"];
  if (typeof header === "string" && header.length > 0) {
    return header;
  }
  return crypto.randomUUID();
}

async function requestContextPlugin(fastify: FastifyInstance): Promise<void> {
  fastify.addHook("onRequest", async (request) => {
    const correlationId = getOrCreateCorrelationId(request);
    request.correlationId = correlationId;
  });
}

export default fp(requestContextPlugin);
```

