import Fastify from "fastify";
import { env } from "./config/env.js";
import { healthRoutes } from "./api/routes/health.js";
import { customerRoutes } from "./api/routes/customers.js";
import { logger } from "./infrastructure/logging/logger.js";
import { InMemoryCustomerRepository } from "./infrastructure/persistence/customerRepository.js";
import { HttpCorporateCrmClient } from "./infrastructure/integrations/corporateCrmClient.js";
import { CustomerService } from "./services/customerService.js";
import { registerErrorHandler } from "./plugins/errorHandler.js";
import requestContextPlugin from "./plugins/requestContext.js";

export function buildApp() {
  const fastify = Fastify({
    logger
  });

  const customerRepository = new InMemoryCustomerRepository();
  const crmClient = new HttpCorporateCrmClient();
  const customerService = new CustomerService(customerRepository, crmClient);

  fastify.register(requestContextPlugin);

  fastify.addHook("onRequest", async (request) => {
    request.log = request.log.child({
      correlationId: request.correlationId,
      service: env.SERVICE_NAME
    });
  });

  fastify.register(async (instance) => {
    await healthRoutes(instance);
    await customerRoutes(instance, { customerService });
  });

  registerErrorHandler(fastify);

  return fastify;
}
