## `src/application/services/CustomerService.ts`

```ts
import { randomUUID } from "node:crypto";
import { CreateCustomerRequest } from "../dto/CreateCustomerRequest.js";
import { CustomerResponse } from "../dto/CustomerResponse.js";
import {
  Customer,
  toCorporateIdentityId,
  toCustomerId
} from "../../domain/entities/Customer.js";
import { CustomerRepository } from "../../domain/repositories/CustomerRepository.js";
import { CorporateIdentityClient } from "../../infrastructure/external/CorporateIdentityClient.js";
import { ValidationError } from "../../domain/errors/ValidationError.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateIdentityClient: CorporateIdentityClient
  ) {}

  public async createCustomer(request: CreateCustomerRequest): Promise<CustomerResponse> {
    const existing = await this.customerRepository.findByEmail(request.email);
    if (existing !== null) {
      throw new ValidationError("Customer with this email already exists");
    }

    const provisioned = await this.corporateIdentityClient.provisionIdentity(
      request.email,
      request.fullName
    );

    const customer: Customer = {
      id: toCustomerId(randomUUID()),
      email: request.email,
      fullName: request.fullName,
      corporateIdentityId: toCorporateIdentityId(provisioned.identityId),
      createdAt: new Date()
    };

    await this.customerRepository.save(customer);

    return {
      id: customer.id,
      email: customer.email,
      fullName: customer.fullName,
      corporateIdentityId: customer.corporateIdentityId,
      createdAt: customer.createdAt.toISOString()
    };
  }

  public async getCustomer(id: string): Promise<CustomerResponse | null> {
    const customer = await this.customerRepository.findById(toCustomerId(id));
    if (customer === null) {
      return null;
    }

    return {
      id: customer.id,
      email: customer.email,
      fullName: customer.fullName,
      corporateIdentityId: customer.corporateIdentityId,
      createdAt: customer.createdAt.toISOString()
    };
  }
}
```

