import { CustomerRepository } from "../../domain/repositories/CustomerRepository.js";
import { Customer, CustomerId } from "../../domain/entities/Customer.js";

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly customersById = new Map<string, Customer>();
  private readonly customersByEmail = new Map<string, Customer>();

  public async findById(id: CustomerId): Promise<Customer | null> {
    return this.customersById.get(id) ?? null;
  }

  public async findByEmail(email: string): Promise<Customer | null> {
    return this.customersByEmail.get(email.toLowerCase()) ?? null;
  }

  public async save(customer: Customer): Promise<void> {
    this.customersById.set(customer.id, customer);
    this.customersByEmail.set(customer.email.toLowerCase(), customer);
  }
}
