## `src/infrastructure/http/middleware/requestContext.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { randomUUID } from "node:crypto";

export const attachRequestContext = async (
  request: FastifyRequest,
  reply: FastifyReply
): Promise<void> => {
  const correlationIdHeader = request.headers["x-correlation-id"];
  const correlationId =
    typeof correlationIdHeader === "string" && correlationIdHeader.length > 0
      ? correlationIdHeader
      : randomUUID();

  request.log = request.log.child({ correlationId });
  reply.header("x-correlation-id", correlationId);
};
```

## `src/infrastructure/http/middleware/errorHandler.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import { DomainError } from "../../../domain/errors/DomainError.js";

export const errorHandler = (
  error: Error,
  request: FastifyRequest,
  reply: FastifyReply
): void => {
  request.log.error({ err: error }, "request failed");

  if (error instanceof ZodError) {
    reply.status(400).send({
      code: "INVALID_REQUEST",
      message: "Request validation failed",
      details: error.issues
    });
    return;
  }

  if (error instanceof DomainError) {
    const statusCode = error.code === "NOT_FOUND" ? 404 : 400;
    reply.status(statusCode).send({
      code: error.code,
      message: error.message
    });
    return;
  }

  reply.status(500).send({
    code: "INTERNAL_SERVER_ERROR",
    message: "An unexpected error occurred"
  });
};
```

