import { FastifyInstance } from "fastify";
import { CustomerService } from "../../../application/services/CustomerService.js";
import {
  createCustomerBodySchema,
  customerParamsSchema
} from "../schemas/customerSchemas.js";

export const registerCustomerRoutes = (
  app: FastifyInstance,
  customerService: CustomerService
): void => {
  app.post("/customers", async (request, reply) => {
    const body = createCustomerBodySchema.parse(request.body);
    const customer = await customerService.createCustomer(body);

    reply.status(201).send(customer);
  });

  app.get("/customers/:id", async (request, reply) => {
    const params = customerParamsSchema.parse(request.params);
    const customer = await customerService.getCustomer(params.id);

    if (customer === null) {
      reply.status(404).send({
        code: "NOT_FOUND",
        message: "Customer not found"
      });
      return;
    }

    reply.send(customer);
  });
};
```

