import Fastify, { FastifyInstance } from "fastify";
import sensible from "@fastify/sensible";
import { env } from "../config/index.js";
import { logger } from "../infrastructure/logging/logger.js";
import { attachRequestContext } from "../infrastructure/http/middleware/requestContext.js";
import { errorHandler } from "../infrastructure/http/middleware/errorHandler.js";
import { registerHealthRoutes } from "../infrastructure/http/routes/healthRoutes.js";
import { registerCustomerRoutes } from "../infrastructure/http/routes/customerRoutes.js";
import { InMemoryCustomerRepository } from "../infrastructure/db/InMemoryCustomerRepository.js";
import { HttpCorporateIdentityClient } from "../infrastructure/external/HttpCorporateIdentityClient.js";
import { CustomerService } from "../application/services/CustomerService.js";

export const buildApp = (): FastifyInstance => {
  const app = Fastify({
    logger: logger
  });

  void app.register(sensible);

  app.addHook("onRequest", attachRequestContext);
  app.setErrorHandler(errorHandler);

  const customerRepository = new InMemoryCustomerRepository();
  const corporateIdentityClient = new HttpCorporateIdentityClient();
  const customerService = new CustomerService(
    customerRepository,
    corporateIdentityClient
  );

  registerHealthRoutes(app);
  registerCustomerRoutes(app, customerService);

  return app;
};
```

