## `src/repositories/postgres-customer-repository.ts`

```ts
import type { Pool } from "pg";
import { randomUUID } from "node:crypto";
import type { Customer, CreateCustomerInput } from "../domain/customer.js";
import type { CustomerRepository } from "./customer-repository.js";

interface CustomerRow {
  id: string;
  external_id: string;
  email: string;
  full_name: string;
  is_active: boolean;
  created_at: Date;
  updated_at: Date;
}

export class PostgresCustomerRepository implements CustomerRepository {
  constructor(private readonly db: Pool) {}

  async create(input: CreateCustomerInput): Promise<Customer> {
    const id = randomUUID();

    const result = await this.db.query<CustomerRow>(
      `
      INSERT INTO customers (id, external_id, email, full_name, is_active, created_at, updated_at)
      VALUES ($1, $2, $3, $4, true, NOW(), NOW())
      RETURNING id, external_id, email, full_name, is_active, created_at, updated_at
      `,
      [id, input.externalId, input.email, input.fullName]
    );

    return this.mapRow(result.rows[0]);
  }

  async findById(id: string): Promise<Customer | null> {
    const result = await this.db.query<CustomerRow>(
      `
      SELECT id, external_id, email, full_name, is_active, created_at, updated_at
      FROM customers
      WHERE id = $1
      `,
      [id]
    );

    return result.rows[0] ? this.mapRow(result.rows[0]) : null;
  }

  async findByExternalId(externalId: string): Promise<Customer | null> {
    const result = await this.db.query<CustomerRow>(
      `
      SELECT id, external_id, email, full_name, is_active, created_at, updated_at
      FROM customers
      WHERE external_id = $1
      `,
      [externalId]
    );

    return result.rows[0] ? this.mapRow(result.rows[0]) : null;
  }

  private mapRow(row: CustomerRow | undefined): Customer {
    if (!row) {
      throw new Error("Expected database row but received none");
    }

    return {
      id: row.id,
      externalId: row.external_id,
      email: row.email,
      fullName: row.full_name,
      isActive: row.is_active,
      createdAt: new Date(row.created_at),
      updatedAt: new Date(row.updated_at)
    };
  }
}
```

