## `src/integrations/http-corporate-directory-client.ts`

```ts
import type { CorporateDirectoryClient, DirectoryUser } from "./corporate-directory-client.js";

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  constructor(
    private readonly baseUrl: string,
    private readonly fetchImpl: typeof fetch = fetch
  ) {}

  async getUserByExternalId(externalId: string): Promise<DirectoryUser | null> {
    const response = await this.fetchImpl(
      `${this.baseUrl}/directory/users/${encodeURIComponent(externalId)}`,
      {
        method: "GET",
        headers: {
          "content-type": "application/json"
        }
      }
    );

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate directory request failed with status ${response.status}`);
    }

    const data = (await response.json()) as DirectoryUser;

    return {
      externalId: data.externalId,
      email: data.email,
      fullName: data.fullName,
      active: data.active
    };
  }
}
```

