# 11. Service layer

## `src/services/customer-service.ts`

```ts
import type { Customer, CreateCustomerInput } from "../domain/customer.js";
import { ConflictError, NotFoundError } from "../domain/errors.js";
import type { CustomerRepository } from "../repositories/customer-repository.js";
import type { CorporateDirectoryClient } from "../integrations/corporate-directory-client.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly directoryClient: CorporateDirectoryClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByExternalId(input.externalId);
    if (existing) {
      throw new ConflictError(`Customer with externalId '${input.externalId}' already exists`);
    }

    const directoryUser = await this.directoryClient.getUserByExternalId(input.externalId);
    if (!directoryUser || !directoryUser.active) {
      throw new NotFoundError(`Active directory user not found for externalId '${input.externalId}'`);
    }

    return this.repository.create({
      externalId: input.externalId,
      email: input.email,
      fullName: input.fullName
    });
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer '${id}' not found`);
    }
    return customer;
  }
}
```

