# 15. Controller layer

## `src/api/controllers/customer-controller.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import type { CustomerService } from "../../services/customer-service.js";
import {
  createCustomerRequestSchema,
  customerResponseSchema
} from "../schemas/customer-schemas.js";
import { UnauthorizedError } from "../../domain/errors.js";

const paramsSchema = z.object({
  id: z.string().uuid()
});

export class CustomerController {
  constructor(private readonly customerService: CustomerService) {}

  createCustomer = async (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> => {
    if (!request.principal?.roles.includes("customer:write")) {
      throw new UnauthorizedError();
    }

    const body = createCustomerRequestSchema.parse(request.body);
    const customer = await this.customerService.createCustomer(body);

    const response = customerResponseSchema.parse({
      id: customer.id,
      externalId: customer.externalId,
      email: customer.email,
      fullName: customer.fullName,
      isActive: customer.isActive,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });

    await reply.status(201).send(response);
  };

  getCustomerById = async (
    request: FastifyRequest<{ Params: { id: string } }>,
    reply: FastifyReply
  ): Promise<void> => {
    if (!request.principal?.roles.includes("customer:read")) {
      throw new UnauthorizedError();
    }

    const params = paramsSchema.parse(request.params);
    const customer = await this.customerService.getCustomerById(params.id);

    const response = customerResponseSchema.parse({
      id: customer.id,
      externalId: customer.externalId,
      email: customer.email,
      fullName: customer.fullName,
      isActive: customer.isActive,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });

    await reply.status(200).send(response);
  };
}
```

