# 17. Server composition root

## `src/app/server.ts`

```ts
import Fastify from "fastify";
import cors from "@fastify/cors";
import helmet from "@fastify/helmet";
import sensible from "@fastify/sensible";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import { logger } from "../observability/logger.js";
import { pool } from "../db/pool.js";
import { env } from "../config/env.js";
import requestContextPlugin from "./plugins/request-context.js";
import authPlugin from "./plugins/auth.js";
import errorHandlerPlugin from "./plugins/error-handler.js";
import { PostgresCustomerRepository } from "../repositories/postgres-customer-repository.js";
import { HttpCorporateDirectoryClient } from "../integrations/http-corporate-directory-client.js";
import { CustomerService } from "../services/customer-service.js";
import { CustomerController } from "../api/controllers/customer-controller.js";
import { registerRoutes } from "./routes.js";

export async function buildServer() {
  const app = Fastify({
    logger
  });

  await app.register(cors);
  await app.register(helmet);
  await app.register(sensible);
  await app.register(swagger, {
    openapi: {
      info: {
        title: "Enterprise Microservice API",
        version: "1.0.0"
      }
    }
  });
  await app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  await app.register(requestContextPlugin);
  await app.register(authPlugin);
  await app.register(errorHandlerPlugin);

  const customerRepository = new PostgresCustomerRepository(pool);
  const directoryClient = new HttpCorporateDirectoryClient(
    env.CORPORATE_DIRECTORY_BASE_URL
  );
  const customerService = new CustomerService(customerRepository, directoryClient);
  const customerController = new CustomerController(customerService);

  await registerRoutes(app, {
    customerController
  });

  return app;
}
```

