```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../services/customer-service.js";
import { AppError } from "../errors/app-error.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function customerRoutes(
  app: FastifyInstance,
  dependencies: { customerService: CustomerService }
): Promise<void> {
  app.get("/customers/:id", async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);

    if (!parsed.success) {
      throw new AppError("Invalid request parameters", 400, "INVALID_PARAMS");
    }

    const result = await dependencies.customerService.getCustomer(parsed.data.id);

    if (result.customer === null) {
      reply.code(404);
      return {
        code: "CUSTOMER_NOT_FOUND",
        message: "Customer not found"
      };
    }

    return result;
  });
}
```

