# 11. `src/app.ts`

Application composition root.

```ts
import Fastify, { FastifyInstance } from "fastify";
import { AppConfig } from "./config.js";
import { createLogger } from "./logger.js";
import { AppError } from "./errors/app-error.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customer.js";
import { HttpCorporateCrmClient } from "./clients/corporate-crm-client.js";
import { CustomerService } from "./services/customer-service.js";

export function buildApp(config: AppConfig): FastifyInstance {
  const logger = createLogger(config.LOG_LEVEL);

  const app = Fastify();

  const crmClient = new HttpCorporateCrmClient({
    baseUrl: config.CRM_BASE_URL,
    apiKey: config.CRM_API_KEY
  });

  const customerService = new CustomerService(crmClient);

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      logger.warn("Application error", {
        code: error.code,
        message: error.message,
        statusCode: error.statusCode
      });

      reply.status(error.statusCode).send({
        code: error.code,
        message: error.message
      });
      return;
    }

    logger.error("Unhandled error", {
      error: error instanceof Error ? error.message : String(error)
    });

    reply.status(500).send({
      code: "INTERNAL_ERROR",
      message: "An unexpected error occurred"
    });
  });

  void app.register(healthRoutes);
  void app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  return app;
}
```

