# 11. src/routes/customers.ts

Strictly typed route params and responses.

```ts
import { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { getCustomerById } from "../services/customerService.js";
import { Customer, ErrorResponse } from "../types.js";

const customerParamsSchema = z.object({
  id: z.string().min(1)
});

type CustomerParams = z.infer<typeof customerParamsSchema>;

type GetCustomerRequest = FastifyRequest<{
  Params: CustomerParams;
}>;

type GetCustomerReply = FastifyReply;

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  app.get(
    "/v1/customers/:id",
    async (request: GetCustomerRequest, reply: GetCustomerReply) => {
      const params = customerParamsSchema.parse(request.params);

      const customer: Customer | null = await getCustomerById(app, params.id);

      if (!customer) {
        const response: ErrorResponse = {
          error: "NOT_FOUND",
          message: `Customer ${params.id} not found`
        };
        return reply.status(404).send(response);
      }

      return reply.status(200).send(customer);
    }
  );
}
```

