```ts
import { config } from "../config.js";
import type { Customer } from "../types.js";
import { UpstreamError } from "../utils/errors.js";

export class CorporateCrmClient {
  async notifyCustomerCreated(customer: Customer): Promise<void> {
    const response = await fetch(`${config.CRM_BASE_URL}/api/customers/sync`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": config.CRM_API_KEY
      },
      body: JSON.stringify(customer)
    });

    if (!response.ok) {
      throw new UpstreamError(`CRM sync failed with status ${response.status}`);
    }
  }

  async checkReadiness(): Promise<boolean> {
    try {
      const response = await fetch(`${config.CRM_BASE_URL}/health`, {
        method: "GET",
        headers: {
          "x-api-key": config.CRM_API_KEY
        }
      });

      return response.ok;
    } catch {
      return false;
    }
  }
}
```

