import { FastifyPluginAsync } from "fastify";
import { CorporateCrmClient } from "../clients/corporate-crm-client.js";

export const healthRoutes: FastifyPluginAsync = async (app) => {
  const crmClient = new CorporateCrmClient();

  app.get("/health", async () => {
    return {
      status: "ok",
      service: "enterprise-customer-service"
    };
  });

  app.get("/ready", async (_, reply) => {
    const crmReady = await crmClient.checkReadiness();

    if (!crmReady) {
      return reply.status(503).send({
        status: "not_ready",
        dependencies: {
          crm: "down"
        }
      });
    }

    return {
      status: "ready",
      dependencies: {
        crm: "up"
      }
    };
  });
};
