  app.post("/api/v1/customers", async (request, reply) => {
    const body = createCustomerBodySchema.parse(request.body);
    const customer = await service.createCustomer(body);
    return reply.status(201).send(customer);
  });

  app.get("/api/v1/customers/:id", async (request) => {
    const params = customerIdParamsSchema.parse(request.params);
    return service.getCustomerById(params.id);
  });
};
