import fp from "fastify-plugin";
import { FastifyPluginAsync } from "fastify";
import { AppConfig } from "../config.js";

export interface CorporateCustomerRecord {
  externalId: string;
  fullName: string;
  emailAddress: string;
}

export interface CorporateClient {
  ping(): Promise<boolean>;
  createCustomer(input: CorporateCustomerRecord): Promise<{ id: string }>;
}

class MockCorporateClient implements CorporateClient {
  constructor(private readonly config: AppConfig) {}

  async ping(): Promise<boolean> {
    return this.config.CORPORATE_API_KEY.length > 0;
  }

  async createCustomer(input: CorporateCustomerRecord): Promise<{ id: string }> {
    return {
      id: `corp-${input.externalId}`
    };
  }
}

const corporateClientPlugin: FastifyPluginAsync<{ config: AppConfig }> = async (fastify, opts) => {
  const client: CorporateClient = new MockCorporateClient(opts.config);

  fastify.decorate("corporateClient", client);
};

export default fp(corporateClientPlugin, {
  name: "corporateClient"
});
```

