# 14. Customer routes

## `src/routes/customers.ts`

```ts
import { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import { CustomerService } from "../services/customerService.js";
import {
  createCustomerBodySchema,
  createCustomerResponseSchema
} from "../schemas/customer.js";
import { AppError } from "../errors.js";

const customersRoutes: FastifyPluginAsync = async (fastify) => {
  const customerService = new CustomerService(fastify.corporateClient);

  fastify.post("/api/v1/customers", async (request, reply) => {
    const parsedBody = createCustomerBodySchema.safeParse(request.body);

    if (!parsedBody.success) {
      throw new AppError("Invalid request body", 400, "VALIDATION_ERROR", parsedBody.error.flatten());
    }

    const result = await customerService.createCustomer(parsedBody.data);

    const parsedResponse = createCustomerResponseSchema.safeParse(result);
    if (!parsedResponse.success) {
      throw new AppError("Invalid response contract", 500, "RESPONSE_VALIDATION_ERROR");
    }

    return reply.code(201).send(parsedResponse.data);
  });

  fastify.get("/api/v1/customers/schema", async () => {
    return {
      request: z.toJSONSchema(createCustomerBodySchema),
      response: z.toJSONSchema(createCustomerResponseSchema)
    };
  });
};

export default customersRoutes;
```

