import type { Customer, CustomerId } from "../domain/customer.js";
import type { CustomerGateway } from "./customerGateway.js";

export class InMemoryCustomerGateway implements CustomerGateway {
  private readonly customers: ReadonlyMap<CustomerId, Customer>;

