        id: "cust-002",
        externalRef: "ERP-1002",
        name: "Bob Smith",
        email: "bob.smith@example.com",
        active: false
      }
    ];

    this.customers = new Map(seed.map((customer) => [customer.id, customer]));
  }

  public async getCustomerById(id: CustomerId): Promise<Customer | null> {
    return this.customers.get(id) ?? null;
  }
}
