```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { NotFoundError } from "../errors/httpErrors.js";
import { CustomerSchema } from "../domain/customer.js";

const ParamsSchema = z.object({
  id: z.string().min(1)
});

type GetCustomerParams = z.infer<typeof ParamsSchema>;

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  app.get(
    "/api/v1/customers/:id",
    async (
      request: FastifyRequest<{ Params: GetCustomerParams }>,
      reply: FastifyReply
    ) => {
      const parsedParams = ParamsSchema.safeParse(request.params);

      if (!parsedParams.success) {
        return reply.status(400).send({
          error: "Bad Request",
          message: "Invalid customer id",
          details: parsedParams.error.flatten()
        });
      }

      const customer = await app.di.customerGateway.getCustomerById(parsedParams.data.id);

      if (customer === null) {
        throw new NotFoundError(`Customer not found: ${parsedParams.data.id}`);
      }

      const parsedCustomer = CustomerSchema.safeParse(customer);

      if (!parsedCustomer.success) {
        request.log.error(
          { validation: parsedCustomer.error.flatten() },
          "Corporate system returned invalid customer payload"
        );

        return reply.status(502).send({
          error: "Bad Gateway",
          message: "Upstream customer data invalid"
        });
      }

      return reply.status(200).send(parsedCustomer.data);
    }
  );
}
```

