You could add:

```ts
import type { Customer, CustomerId } from "../domain/customer.js";
import type { CustomerGateway } from "./customerGateway.js";
import { CustomerSchema } from "../domain/customer.js";

export class CorporateRestCustomerGateway implements CustomerGateway {
  public constructor(
    private readonly baseUrl: string,
    private readonly apiToken: string
  ) {}

  public async getCustomerById(id: CustomerId): Promise<Customer | null> {
    const response = await fetch(`${this.baseUrl}/customers/${encodeURIComponent(id)}`, {
      headers: {
        Authorization: `Bearer ${this.apiToken}`,
        Accept: "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate API error: ${response.status}`);
    }

    const json: unknown = await response.json();
    return CustomerSchema.parse(json);
  }
}
