# 10. `src/services/customerService.ts`

Business logic with dependency injection.

```ts
import crypto from "crypto";
import { CreateCustomerInput, Customer } from "../domain/customer";
import { CorporateDirectoryClient } from "../integrations/corporateDirectoryClient";
import { CustomerRepository } from "../repositories/customerRepository";
import { NotFoundError, ValidationError } from "../utils/errors";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError("Customer not found");
    }
    return customer;
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const corporateRecord = await this.corporateDirectoryClient.lookupByEmail(input.email);

    if (!corporateRecord || !corporateRecord.active) {
      throw new ValidationError("Customer email is not active in corporate directory");
    }

    const customer: Customer = {
      id: crypto.randomUUID(),
      name: input.name,
      email: input.email,
      department: input.department
    };

    return this.repository.create(customer);
  }
}
```

