# 11. `src/controllers/customerController.ts`

Typed controller methods.

```ts
import { Request, Response, NextFunction } from "express";
import { CreateCustomerSchema } from "../domain/customer";
import { CustomerService } from "../services/customerService";
import { ApiResponse } from "../types/api";
import { Customer } from "../domain/customer";
import { ValidationError } from "../utils/errors";

export class CustomerController {
  constructor(private readonly customerService: CustomerService) {}

  getById = async (
    req: Request<{ id: string }>,
    res: Response<ApiResponse<Customer>>,
    next: NextFunction
  ): Promise<void> => {
    try {
      const customer = await this.customerService.getCustomerById(req.params.id);
      res.json({ success: true, data: customer });
    } catch (error) {
      next(error);
    }
  };

  create = async (
    req: Request<unknown, unknown, unknown>,
    res: Response<ApiResponse<Customer>>,
    next: NextFunction
  ): Promise<void> => {
    try {
      const parsed = CreateCustomerSchema.safeParse(req.body);
      if (!parsed.success) {
        throw new ValidationError(parsed.error.message);
      }

      const customer = await this.customerService.createCustomer(parsed.data);
      res.status(201).json({ success: true, data: customer });
    } catch (error) {
      next(error);
    }
  };
}
```

