import express from "express";
import healthRoutes from "./routes/healthRoutes";
import { createCustomerRoutes } from "./routes/customerRoutes";
import { requestLogger } from "./middleware/requestLogger";
import { errorHandler } from "./middleware/errorHandler";
import { InMemoryCustomerRepository } from "./repositories/customerRepository";
import { MockCorporateDirectoryClient } from "./integrations/corporateDirectoryClient";
import { CustomerService } from "./services/customerService";
import { CustomerController } from "./controllers/customerController";

export function createApp() {
  const app = express();

  app.use(express.json());
  app.use(requestLogger);

  const customerRepository = new InMemoryCustomerRepository();
  const corporateDirectoryClient = new MockCorporateDirectoryClient();
  const customerService = new CustomerService(customerRepository, corporateDirectoryClient);
  const customerController = new CustomerController(customerService);

  app.use("/health", healthRoutes);
  app.use("/customers", createCustomerRoutes(customerController));

  app.use(errorHandler);

  return app;
}
