import { FastifyInstance } from "fastify";
import {
  CreateCustomerRequestSchema,
  CreateCustomerResponseSchema,
  GetCustomerParamsSchema
} from "../types.js";
import { CustomerService } from "../services/customerService.js";

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const service = new CustomerService(app);

  app.get(
    "/v1/customers/:id",
    async (request, reply) => {
      const params = GetCustomerParamsSchema.parse(request.params);
      const customer = await service.getCustomerById(params.id);
      return reply.send(customer);
    }
  );

  app.post(
    "/v1/customers",
    async (request, reply) => {
      const body = CreateCustomerRequestSchema.parse(request.body);
      const customer = await service.createCustomer(body);
      const response = CreateCustomerResponseSchema.parse(customer);
      return reply.code(201).send(response);
    }
  );
}
