import { Customer } from "../schemas/customer.js";

export interface CustomerRepository {
  create(customer: Customer): Promise<Customer>;
  findByExternalId(externalId: string): Promise<Customer | null>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly customers = new Map<string, Customer>();

  async create(customer: Customer): Promise<Customer> {
    this.customers.set(customer.externalId, customer);
    return customer;
  }

  async findByExternalId(externalId: string): Promise<Customer | null> {
    return this.customers.get(externalId) ?? null;
  }
}
