```ts
import {
  CreateCustomerRequest,
  Customer
} from "../schemas/customer.js";
import { CustomerRepository } from "../repositories/customerRepository.js";
import { CorporateCrmClient } from "../integrations/corporateCrmClient.js";

export class DuplicateCustomerError extends Error {
  constructor(externalId: string) {
    super(`Customer with externalId '${externalId}' already exists`);
    this.name = "DuplicateCustomerError";
  }
}

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const existing = await this.repository.findByExternalId(input.externalId);
    if (existing) {
      throw new DuplicateCustomerError(input.externalId);
    }

    await this.crmClient.createCustomer({
      externalId: input.externalId,
      name: input.name,
      email: input.email
    });

    const customer: Customer = {
      id: crypto.randomUUID(),
      externalId: input.externalId,
      name: input.name,
      email: input.email,
      createdAt: new Date().toISOString()
    };

    return this.repository.create(customer);
  }
}
```

