# 12. src/routes/health.ts

```ts
import { FastifyInstance } from "fastify";
import { config } from "../config.js";
import { CorporateCrmClient } from "../integrations/corporateCrmClient.js";

export async function healthRoutes(
  fastify: FastifyInstance,
  crmClient: CorporateCrmClient
): Promise<void> {
  fastify.get("/health", {
    schema: {
      tags: ["system"],
      response: {
        200: {
          type: "object",
          properties: {
            status: { type: "string", enum: ["ok"] },
            service: { type: "string" }
          },
          required: ["status", "service"]
        }
      }
    }
  }, async () => {
    return {
      status: "ok",
      service: config.SERVICE_NAME
    };
  });

  fastify.get("/ready", {
    schema: {
      tags: ["system"],
      response: {
        200: {
          type: "object",
          properties: {
            status: { type: "string", enum: ["ready"] },
            service: { type: "string" }
          },
          required: ["status", "service"]
        },
        503: {
          type: "object",
          properties: {
            status: { type: "string" },
            service: { type: "string" }
          },
          required: ["status", "service"]
        }
      }
    }
  }, async (_, reply) => {
    const crmOk = await crmClient.ping();

    if (!crmOk) {
      return reply.code(503).send({
        status: "not-ready",
        service: config.SERVICE_NAME
      });
    }

    return {
      status: "ready",
