# 13. src/routes/customers.ts

```ts
import { FastifyInstance } from "fastify";
import {
  createCustomerRequestSchema,
  createCustomerResponseSchema
} from "../schemas/customer.js";
import { CustomerService, DuplicateCustomerError } from "../services/customerService.js";

export async function customerRoutes(
  fastify: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  fastify.post("/customers", {
    schema: {
      tags: ["customers"],
      body: {
        type: "object",
        properties: {
          externalId: { type: "string" },
          name: { type: "string", minLength: 1, maxLength: 200 },
          email: { type: "string", format: "email" }
        },
        required: ["externalId", "name", "email"]
      },
      response: {
        201: {
          type: "object",
          properties: {
            customer: {
              type: "object",
              properties: {
                id: { type: "string" },
                externalId: { type: "string" },
                name: { type: "string" },
                email: { type: "string", format: "email" },
                createdAt: { type: "string", format: "date-time" }
              },
              required: ["id", "externalId", "name", "email", "createdAt"]
            }
          },
          required: ["customer"]
        },
        409: {
          type: "object",
          properties: {
            error: {
              type: "object",
              properties: {
                code: { type: "string" },
                message: { type: "string" }
              },
              required: ["code", "message"]
            }
          },
          required: ["error"]
        }
      }
    }
  }, async (request, reply) => {
    const parsedBody = createCustomerRequestSchema.parse(request.body);

    try {
      const customer = await customerService.createCustomer(parsedBody);
      const response = createCustomerResponseSchema.parse({ customer });

      return reply.code(201).send(response);
    } catch (error) {
      if (error instanceof DuplicateCustomerError) {
        return reply.code(409).send({
          error: {
            code: "DUPLICATE_CUSTOMER",
            message: error.message
          }
        });
      }

      throw error;
    }
  });
}
```

