# 14. src/app.ts

Wire dependencies together.

```ts
import Fastify, { FastifyInstance } from "fastify";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import { config } from "./config.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { InMemoryCustomerRepository } from "./repositories/customerRepository.js";
import { CorporateCrmClient } from "./integrations/corporateCrmClient.js";
import { CustomerService } from "./services/customerService.js";

export async function buildApp(): Promise<FastifyInstance> {
  const app = Fastify({
    logger: true
  });

  await app.register(swagger, {
    openapi: {
      info: {
        title: config.SERVICE_NAME,
        version: "1.0.0"
      }
    }
  });

  await app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  const repository = new InMemoryCustomerRepository();
  const crmClient = new CorporateCrmClient(config);
  const customerService = new CustomerService(repository, crmClient);

  app.setErrorHandler((error, _request, reply) => {
    app.log.error({ err: error }, "Unhandled error");

    return reply.code(500).send({
      error: {
        code: "INTERNAL_SERVER_ERROR",
        message: "An unexpected error occurred"
      }
    });
  });

  await healthRoutes(app, crmClient);
  await customerRoutes(app, customerService);

  return app;
}
```

