# 8) `src/clients/corporate-customer-client.ts`

A typed client for an existing corporate customer system.

```ts
import type { AppConfig } from "../config.js";
import type { Customer } from "../types.js";
import { NotFoundError, UpstreamError } from "../utils/errors.js";

export class CorporateCustomerClient {
  public constructor(private readonly config: AppConfig) {}

  public async getCustomerById(
    customerId: string,
    authToken: string
  ): Promise<Customer> {
    const url = `${this.config.CORP_CUSTOMER_BASE_URL}/customers/${encodeURIComponent(customerId)}`;

    const response = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: authToken,
        "X-API-Key": this.config.CORP_CUSTOMER_API_KEY,
        Accept: "application/json"
      }
    });

    if (response.status === 404) {
      throw new NotFoundError(`Customer ${customerId} not found`);
    }

    if (!response.ok) {
      throw new UpstreamError(`Corporate customer system returned ${response.status}`);
    }

    const data: unknown = await response.json();

    // Minimal runtime validation for external system data
    if (
      typeof data !== "object" ||
      data === null ||
      !("id" in data) ||
      !("email" in data) ||
      !("fullName" in data) ||
      !("active" in data)
    ) {
      throw new UpstreamError("Invalid response from corporate customer system");
    }

    const customer = data as Customer;
    return customer;
  }
}
```

