# 8. Corporate system integration plugin

This represents an existing internal system.

## src/plugins/corporateClient.ts

```ts
import axios, { AxiosInstance } from "axios";
import { FastifyInstance } from "fastify";
import fp from "fastify-plugin";
import { AppConfig } from "../config.js";
import { customerSchema, Customer, CreateCustomerRequest } from "../schemas/customer.js";

declare module "fastify" {
  interface FastifyInstance {
    corporateClient: {
      createCustomer(input: CreateCustomerRequest): Promise<Customer>;
    };
  }
}

function buildCorporateClient(config: AppConfig): FastifyInstance["corporateClient"] {
  const client: AxiosInstance = axios.create({
    baseURL: config.CORP_API_BASE_URL,
    timeout: 5000,
    headers: {
      Authorization: `Bearer ${config.CORP_API_TOKEN}`,
      "Content-Type": "application/json"
    }
  });

  return {
    async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
      const response = await client.post("/customers", input);
      return customerSchema.parse(response.data);
    }
  };
}

export default fp(async function corporateClientPlugin(app: FastifyInstance) {
  const config = app.config;
  app.decorate("corporateClient", buildCorporateClient(config));
});
```

