## `src/integrations/corporate-crm.ts`

```ts
import type { CreateCustomerInput, Customer } from "../types.js";

export interface CorporateCrmClient {
  getCustomerById(id: string): Promise<Customer | null>;
  createCustomer(input: CreateCustomerInput): Promise<Customer>;
}

export class InMemoryCorporateCrmClient implements CorporateCrmClient {
  private readonly store = new Map<string, Customer>();

  async getCustomerById(id: string): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const customer: Customer = {
      id: crypto.randomUUID(),
      email: input.email,
      fullName: input.fullName,
      createdAt: new Date().toISOString()
    };

    this.store.set(customer.id, customer);
    return customer;
  }
}
```

