# 11. Auth plugin for corporate headers

This simulates enterprise SSO / API gateway propagation.

Expected headers:

- `x-employee-id`
- `x-employee-email`
- `x-employee-roles`

## `src/plugins/auth.ts`

```ts
import fp from "fastify-plugin";
import { z } from "zod";
import type { FastifyPluginAsync } from "fastify";
import { corporateUserSchema } from "../types.js";

declare module "fastify" {
  interface FastifyRequest {
    corporateUser: z.infer<typeof corporateUserSchema>;
  }
}

const headerSchema = z.object({
  "x-employee-id": z.string().min(1),
  "x-employee-email": z.string().email(),
  "x-employee-roles": z.string().min(1)
});

const authPlugin: FastifyPluginAsync = async (app) => {
  app.decorateRequest("corporateUser", null);

  app.addHook("preHandler", async (request) => {
    const parsedHeaders = headerSchema.parse({
      "x-employee-id": request.headers["x-employee-id"],
      "x-employee-email": request.headers["x-employee-email"],
      "x-employee-roles": request.headers["x-employee-roles"]
    });

    request.corporateUser = {
      employeeId: parsedHeaders["x-employee-id"],
      email: parsedHeaders["x-employee-email"],
      roles: parsedHeaders["x-employee-roles"].split(",").map((role) => role.trim())
    };
  });
};

export default fp(authPlugin);
```

