```ts
import type { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import { AppError } from "../errors/app-error.js";
import { createCustomerSchema, customerIdSchema } from "../types.js";

const paramsSchema = z.object({
  id: customerIdSchema
});

export const customerRoutes: FastifyPluginAsync = async (app) => {
  app.get("/customers/:id", async (request, reply) => {
    const params = paramsSchema.parse(request.params);

    const customer = await app.customerService.getCustomerById(params.id);

    if (!customer) {
      throw new AppError("Customer not found", 404, "CUSTOMER_NOT_FOUND");
    }

    return reply.send(customer);
  });

  app.post("/customers", async (request, reply) => {
    const body = createCustomerSchema.parse(request.body);

    if (!request.corporateUser.roles.includes("customer:write")) {
      throw new AppError("Forbidden", 403, "FORBIDDEN");
    }

    const customer = await app.customerService.createCustomer(body);
    return reply.code(201).send(customer);
  });
};
```

