# 13. App composition

## `src/app.ts`

```ts
import Fastify from "fastify";
import authPlugin from "./plugins/auth.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { loadConfig } from "./config.js";
import { InMemoryCorporateCrmClient } from "./integrations/corporate-crm.js";
import { CustomerService } from "./services/customer-service.js";
import { AppError } from "./errors/app-error.js";

declare module "fastify" {
  interface FastifyInstance {
    config: ReturnType<typeof loadConfig>;
    customerService: CustomerService;
  }
}

export function buildApp() {
  const config = loadConfig(process.env);

  const app = Fastify({
    logger: true
  });

  const crmClient = new InMemoryCorporateCrmClient();
  const customerService = new CustomerService(crmClient);

  app.decorate("config", config);
  app.decorate("customerService", customerService);

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message,
          details: error.details ?? null
        }
      });
    }

    if ("issues" in error) {
      return reply.status(400).send({
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid request",
          details: error
        }
      });
    }

    app.log.error(error);

    return reply.status(500).send({
      error: {
        code: "INTERNAL_ERROR",
        message: "Internal server error"
      }
    });
  });

  app.register(authPlugin);
  app.register(healthRoutes);
  app.register(customerRoutes);

  return app;
}
```

