# 11. Request context plugin

Adds request ID support for tracing across corporate systems.

## `src/plugins/request-context.ts`

```ts
import fp from "fastify-plugin";
import type { FastifyPluginAsync } from "fastify";

declare module "fastify" {
  interface FastifyRequest {
    requestId: string;
  }
}

const requestContextPlugin: FastifyPluginAsync = async (app) => {
  app.addHook("onRequest", async (request) => {
    const incoming = request.headers["x-request-id"];
    request.requestId = typeof incoming === "string" && incoming.length > 0
      ? incoming
      : crypto.randomUUID();
  });
};

export default fp(requestContextPlugin);
```

