import type { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import {
  CreateCustomerRequestSchema,
  CustomerIdSchema
} from "../types.js";
import { ValidationError } from "../utils/errors.js";

const ParamsSchema = z.object({
  id: CustomerIdSchema
});

const customerRoutes: FastifyPluginAsync = async (app) => {
  app.post("/customers", async (request, reply) => {
    const parsed = CreateCustomerRequestSchema.safeParse(request.body);

    if (!parsed.success) {
      throw new ValidationError("Invalid create customer request", parsed.error.flatten());
    }

    const customer = await app.di.customerService.createCustomer(parsed.data);
    return reply.code(201).send(customer);
  });

  app.get("/customers/:id", async (request) => {
    const parsed = ParamsSchema.safeParse(request.params);

    if (!parsed.success) {
      throw new ValidationError("Invalid customer id", parsed.error.flatten());
    }

    return app.di.customerService.getCustomer(parsed.data.id);
  });
};

export default customerRoutes;
