# 13. App assembly

## `src/app.ts`

```ts
import Fastify from "fastify";
import type { FastifyInstance } from "fastify";
import requestContextPlugin from "./plugins/request-context.js";
import healthRoutes from "./routes/health.js";
import customerRoutes from "./routes/customers.js";
import type { AppConfig } from "./config.js";
import { MockCorporateCrmClient } from "./integrations/corporate-crm-client.js";
import { CorporateCustomerRepository } from "./repositories/customer-repository.js";
import { DefaultCustomerService } from "./services/customer-service.js";
import { AppError } from "./utils/errors.js";

export interface AppDependencies {
  config: AppConfig;
  customerService: DefaultCustomerService;
}

declare module "fastify" {
  interface FastifyInstance {
    di: AppDependencies;
  }
}

export function buildApp(config: AppConfig): FastifyInstance {
  const app = Fastify({
    logger: {
      level: config.NODE_ENV === "production" ? "info" : "debug"
    }
  });

  const crmClient = new MockCorporateCrmClient();
  const customerRepository = new CorporateCustomerRepository(crmClient);
  const customerService = new DefaultCustomerService(customerRepository);

  app.decorate("di", {
    config,
    customerService
  });

  app.register(requestContextPlugin);

  app.addHook("onResponse", async (request, reply) => {
    request.log.info(
      {
        requestId: request.requestId,
        method: request.method,
        url: request.url,
        statusCode: reply.statusCode
      },
      "request completed"
    );
  });

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      request.log.warn(
        {
          requestId: request.requestId,
          code: error.code,
          details: error.details
        },
        error.message
      );

      void reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message
        }
      });
      return;
    }

    request.log.error(
      {
        requestId: request.requestId,
        err: error
      },
      "unhandled error"
    );

    void reply.status(500).send({
      error: {
        code: "INTERNAL_ERROR",
        message: "Internal server error"
      }
    });
  });

  app.register(healthRoutes);
  app.register(customerRoutes, { prefix: "/api/v1" });

  return app;
}
```

