# 9. Fastify plugin for request context

In many enterprises, upstream gateways inject identity and tracing headers.

## `src/plugins/auth-context.ts`

```ts
import fp from "fastify-plugin";
import { FastifyReply, FastifyRequest } from "fastify";
import { UserContext } from "../types/common.js";

declare module "fastify" {
  interface FastifyRequest {
    userContext: UserContext;
  }
}

export default fp(async function authContextPlugin(fastify) {
  fastify.addHook("onRequest", async (request: FastifyRequest, _reply: FastifyReply) => {
    const userIdHeader = request.headers["x-user-id"];
    const rolesHeader = request.headers["x-roles"];
    const correlationIdHeader = request.headers["x-correlation-id"];

    const userId = typeof userIdHeader === "string" ? userIdHeader : "anonymous";
    const roles = typeof rolesHeader === "string" && rolesHeader.length > 0
      ? rolesHeader.split(",").map((r) => r.trim())
      : [];
    const correlationId =
      typeof correlationIdHeader === "string" && correlationIdHeader.length > 0
        ? correlationIdHeader
        : request.id;

    request.userContext = {
      userId,
      roles,
      correlationId
    };
  });
});
```

