import { randomUUID } from "node:crypto";
import { CreateCustomerInput, Customer } from "../domain/customer.js";
import { ErpClient } from "../clients/erp-client.js";
import { CustomerRepository } from "../repositories/customer-repository.js";

export class CustomerService {
  public constructor(
    private readonly repository: CustomerRepository,
    private readonly erpClient: ErpClient
  ) {}

  public async getCustomerById(id: string): Promise<Customer | null> {
    return this.repository.findById(id);
  }

  public async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const erpRecord = await this.erpClient.registerCustomer(input.email);

    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      status: erpRecord.lifecycleStatus
    };

    await this.repository.save(customer);
    return customer;
  }
}
