    const parsedBody = createCustomerInputSchema.safeParse(request.body);

    if (!parsedBody.success) {
      return reply.badRequest("Invalid request body");
    }

    const customer = await fastify.di.customerService.createCustomer(parsedBody.data);

    return reply.code(201).send(customer);
  });
};

