# 15. App assembly and dependency injection

We’ll use a simple DI pattern by decorating Fastify.

## `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { config } from "./config.js";
import authContextPlugin from "./plugins/auth-context.js";
import loggerPlugin from "./plugins/logger.js";
import healthRoutes from "./routes/health.js";
import customersRoutes from "./routes/customers.js";
import { MockErpClient } from "./clients/erp-client.js";
import { InMemoryCustomerRepository } from "./repositories/customer-repository.js";
import { CustomerService } from "./services/customer-service.js";

declare module "fastify" {
  interface FastifyInstance {
    di: {
      config: typeof config;
      customerService: CustomerService;
    };
  }
}

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  await app.register(sensible);
  await app.register(authContextPlugin);
  await app.register(loggerPlugin);

  const repository = new InMemoryCustomerRepository();
  const erpClient = new MockErpClient();
  const customerService = new CustomerService(repository, erpClient);

  app.decorate("di", {
    config,
    customerService
  });

  await app.register(healthRoutes);
  await app.register(customersRoutes);

  app.setErrorHandler((error, request, reply) => {
    request.log.error(
      {
        err: error,
        correlationId: request.userContext?.correlationId
      },
      "unhandled error"
    );

    return reply.status(500).send({
      error: "InternalServerError",
      message: "An unexpected error occurred",
      correlationId: request.userContext?.correlationId
    });
  });

  return app;
}
```

