# 11. Business service

## `src/services/customer-service.ts`

```ts
import { randomUUID } from "node:crypto";
import type { Customer, CreateCustomerRequest } from "../domain/customer.js";
import type { CustomerRepository } from "../repositories/customer-repository.js";
import type { CorporateDirectoryClient } from "../integrations/corporate-directory-client.js";
import { AppError } from "../errors/app-error.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new AppError(`Customer not found: ${id}`, 404, "CUSTOMER_NOT_FOUND");
    }
    return customer;
  }

  async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new AppError("Customer with this email already exists", 409, "CUSTOMER_ALREADY_EXISTS");
    }

    const corporateRecord = await this.corporateDirectoryClient.lookupByEmail(input.email);

    const customer: Customer = {
      id: randomUUID(),
      email: input.email,
      firstName: input.firstName,
      lastName: input.lastName,
      createdAt: new Date().toISOString(),
      corporateDirectoryId: corporateRecord?.directoryId
    };

    return this.repository.create(customer);
  }
}
```

