## `src/routes/customer-routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import {
  createCustomerRequestSchema,
  customerResponseSchema
} from "../domain/customer.js";
import type { CustomerService } from "../services/customer-service.js";

const customerIdParamsSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get("/v1/customers/:id", {
    schema: {
      tags: ["Customers"],
      params: {
        type: "object",
        properties: {
          id: { type: "string", format: "uuid" }
        },
        required: ["id"]
      },
      response: {
        200: {
          type: "object",
          properties: {
            id: { type: "string" },
            email: { type: "string" },
            firstName: { type: "string" },
            lastName: { type: "string" },
            createdAt: { type: "string" },
            corporateDirectoryId: { type: "string" }
          },
          required: ["id", "email", "firstName", "lastName", "createdAt"]
        }
      }
    }
  }, async (request) => {
    const params = customerIdParamsSchema.parse(request.params);
    const customer = await customerService.getCustomerById(params.id);
    return customerResponseSchema.parse(customer);
  });

  app.post("/v1/customers", {
    schema: {
      tags: ["Customers"],
      body: {
        type: "object",
        properties: {
          email: { type: "string", format: "email" },
          firstName: { type: "string", minLength: 1, maxLength: 100 },
          lastName: { type: "string", minLength: 1, maxLength: 100 }
        },
        required: ["email", "firstName", "lastName"]
      },
      response: {
        201: {
          type: "object",
          properties: {
            id: { type: "string" },
            email: { type: "string" },
            firstName: { type: "string" },
            lastName: { type: "string" },
            createdAt: { type: "string" },
            corporateDirectoryId: { type: "string" }
          },
          required: ["id", "email", "firstName", "lastName", "createdAt"]
        }
      }
    }
  }, async (request, reply) => {
    const body = createCustomerRequestSchema.parse(request.body);
    const customer = await customerService.createCustomer(body);
    void reply.status(201);
    return customerResponseSchema.parse(customer);
  });
}
```

