```ts
import Fastify, { type FastifyInstance } from "fastify";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import { config } from "./config.js";
import { errorHandler } from "./errors/error-handler.js";
import { InMemoryCustomerRepository } from "./repositories/in-memory-customer-repository.js";
import { StubCorporateDirectoryClient } from "./integrations/stub-corporate-directory-client.js";
import { CustomerService } from "./services/customer-service.js";
import { healthRoutes } from "./routes/health-routes.js";
import { customerRoutes } from "./routes/customer-routes.js";

export async function buildApp(): Promise<FastifyInstance> {
  const app = Fastify({
    logger: {
      level: config.LOG_LEVEL
    }
  });

  await app.register(swagger, {
    openapi: {
      info: {
        title: "Customer Service API",
        version: "1.0.0"
      }
    }
  });

  await app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  const repository = new InMemoryCustomerRepository();
  const corporateDirectoryClient = new StubCorporateDirectoryClient();
  const customerService = new CustomerService(repository, corporateDirectoryClient);

  app.setErrorHandler(errorHandler);

  await app.register(healthRoutes);
  await customerRoutes(app, customerService);

  return app;
}
