import { randomUUID } from "node:crypto";
import type { Customer, CreateCustomerInput } from "../types/customer.js";
import type { CustomerRepository } from "../repositories/customerRepository.js";
import type { CorporateCrmClient } from "../integrations/corporateCrmClient.js";

export interface CustomerService {
  getCustomer(id: string): Promise<Customer | null>;
  createCustomer(input: CreateCustomerInput): Promise<Customer>;
}

export class DefaultCustomerService implements CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async getCustomer(id: string): Promise<Customer | null> {
    return this.repository.findById(id);
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const crmResult = await this.crmClient.createContact({
      name: input.name,
      email: input.email
    });

    const customer: Customer = {
      id: randomUUID(),
      name: input.name,
      email: input.email,
      externalCrmId: crmResult.crmId
    };

    return this.repository.create(customer);
  }
}
