# 14. src/routes/customers.ts

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { createCustomerSchema } from "../types/customer.js";
import type { CustomerService } from "../domain/customerService.js";
import { AppError } from "../errors/appError.js";

const paramsSchema = z.object({
  id: z.string().uuid()
});

type GetCustomerRequest = FastifyRequest<{
  Params: {
    id: string;
  };
}>;

type CreateCustomerRequest = FastifyRequest<{
  Body: {
    name: string;
    email: string;
  };
}>;

export async function customerRoutes(
  app: FastifyInstance,
  dependencies: { customerService: CustomerService }
): Promise<void> {
  app.get(
    "/v1/customers/:id",
    async (request: GetCustomerRequest, reply: FastifyReply) => {
      const parsedParams = paramsSchema.safeParse(request.params);
      if (!parsedParams.success) {
        throw new AppError("Invalid customer id", 400, "VALIDATION_ERROR");
      }

      const customer = await dependencies.customerService.getCustomer(parsedParams.data.id);

      if (customer === null) {
        throw new AppError("Customer not found", 404, "NOT_FOUND");
      }

      return reply.send(customer);
    }
  );

  app.post(
    "/v1/customers",
    async (request: CreateCustomerRequest, reply: FastifyReply) => {
      const parsedBody = createCustomerSchema.safeParse(request.body);
      if (!parsedBody.success) {
        throw new AppError("Invalid request body", 400, "VALIDATION_ERROR");
      }

      const customer = await dependencies.customerService.createCustomer(parsedBody.data);
      return reply.status(201).send(customer);
    }
  );
}
```

