# 15. src/app.ts

Application composition and error handling.

```ts
import Fastify, { type FastifyInstance } from "fastify";
import { logger } from "./logger.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { InMemoryCustomerRepository } from "./repositories/customerRepository.js";
import { StubCorporateCrmClient } from "./integrations/corporateCrmClient.js";
import { DefaultCustomerService } from "./domain/customerService.js";
import { AppError } from "./errors/appError.js";

export function buildApp(): FastifyInstance {
  const app = Fastify({
    logger: false
  });

  const customerRepository = new InMemoryCustomerRepository();
  const crmClient = new StubCorporateCrmClient();
  const customerService = new DefaultCustomerService(customerRepository, crmClient);

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      logger.warn("Application error", {
        path: request.url,
        method: request.method,
        code: error.code,
        message: error.message
      });

      void reply.status(error.statusCode).send({
        error: {
          code: error.code,
          message: error.message
        }
      });
      return;
    }

    logger.error("Unhandled error", {
      path: request.url,
      method: request.method,
      error: error.message
    });

    void reply.status(500).send({
      error: {
        code: "INTERNAL_ERROR",
        message: "An unexpected error occurred"
      }
    });
  });

  void app.register(healthRoutes);
  void app.register(async (instance) => {
    await customerRoutes(instance, { customerService });
  });

  return app;
}
```

