# 11. src/integrations/corporateHrClient.ts

This is the enterprise integration point.

```ts
import axios, { AxiosInstance } from "axios";
import { z } from "zod";
import { config } from "../config.js";

const CorporateEmployeeSchema = z.object({
  id: z.string(),
  first_name: z.string(),
  last_name: z.string(),
  email_address: z.string().email(),
  department_name: z.string(),
  is_active: z.boolean()
});

type CorporateEmployee = z.infer<typeof CorporateEmployeeSchema>;

export interface CorporateHrClient {
  getEmployeeById(id: string): Promise<CorporateEmployee | null>;
}

export class AxiosCorporateHrClient implements CorporateHrClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: config.CORP_HR_BASE_URL,
      timeout: 5000,
      headers: {
        "x-api-key": config.CORP_HR_API_KEY
      }
    });
  }

  async getEmployeeById(id: string): Promise<CorporateEmployee | null> {
    try {
      const response = await this.http.get(`/corp/employees/${encodeURIComponent(id)}`);
      return CorporateEmployeeSchema.parse(response.data);
    } catch (error: unknown) {
      if (axios.isAxiosError(error) && error.response?.status === 404) {
        return null;
      }
      throw error;
    }
  }
}
