# 12. src/routes/employees.ts

The HTTP routes with strict validation.

```ts
import { FastifyInstance } from "fastify";
import { randomUUID } from "node:crypto";
import {
  CreateEmployeeRequestSchema,
  Employee,
  EmployeeSchema
} from "../domain/employee.js";
import type { EmployeeRepository } from "../repository/employeeRepository.js";
import type { CorporateHrClient } from "../integrations/corporateHrClient.js";

interface Dependencies {
  employeeRepository: EmployeeRepository;
  corporateHrClient: CorporateHrClient;
}

export async function employeeRoutes(
  fastify: FastifyInstance,
  dependencies: Dependencies
): Promise<void> {
  fastify.get("/health", async () => {
    return { status: "ok" };
  });

  fastify.get("/employees/:id", async (request, reply) => {
    const paramsSchema = EmployeeSchema.pick({ id: true });
    const paramsParse = paramsSchema.safeParse(request.params);

    if (!paramsParse.success) {
      return reply.status(400).send({
        code: "INVALID_REQUEST",
        message: "Invalid employee id"
      });
    }

    const { id } = paramsParse.data;

    const localEmployee = await dependencies.employeeRepository.getById(id);
    if (localEmployee) {
      return reply.send(localEmployee);
    }

    const corporateEmployee = await dependencies.corporateHrClient.getEmployeeById(id);
    if (!corporateEmployee) {
      return reply.status(404).send({
        code: "NOT_FOUND",
        message: `Employee ${id} not found`
      });
    }

    const mappedEmployee: Employee = {
      id: corporateEmployee.id,
      firstName: corporateEmployee.first_name,
      lastName: corporateEmployee.last_name,
      email: corporateEmployee.email_address,
      department: corporateEmployee.department_name,
      active: corporateEmployee.is_active
    };

    const validatedEmployee = EmployeeSchema.parse(mappedEmployee);
    return reply.send(validatedEmployee);
  });

  fastify.post("/employees", async (request, reply) => {
    const parseResult = CreateEmployeeRequestSchema.safeParse(request.body);

    if (!parseResult.success) {
      return reply.status(400).send({
        code: "INVALID_REQUEST",
        message: "Request body validation failed"
      });
    }

    const body = parseResult.data;

    const employee: Employee = {
      id: randomUUID(),
      firstName: body.firstName,
      lastName: body.lastName,
      email: body.email,
      department: body.department,
      active: true
    };

    const validatedEmployee = EmployeeSchema.parse(employee);
    const created = await dependencies.employeeRepository.create(validatedEmployee);

    return reply.status(201).send(created);
  });
}
```

