# 7) `src/plugins/crmClient.ts`

A typed integration client for an existing corporate CRM system.

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { AppConfig } from "../config.js";
import { CreateCustomerRequestSchema, CustomerSchema, type CreateCustomerRequest, type Customer } from "../types.js";
import { UpstreamError } from "../errors.js";

const CrmCustomerSchema = CustomerSchema;

type CrmCustomer = z.infer<typeof CrmCustomerSchema>;

export interface CrmClient {
  getCustomerById(id: string): Promise<Customer | null>;
  createCustomer(input: CreateCustomerRequest): Promise<Customer>;
}

export function buildCrmClient(config: AppConfig): CrmClient {
  const headers = {
    "content-type": "application/json",
    "x-api-key": config.CRM_API_KEY
  };

  return {
    async getCustomerById(id: string): Promise<Customer | null> {
      const response = await fetch(`${config.CRM_BASE_URL}/customers/${encodeURIComponent(id)}`, {
        method: "GET",
        headers
      });

      if (response.status === 404) {
        return null;
      }

      if (!response.ok) {
        throw new UpstreamError(`CRM getCustomerById failed with status ${response.status}`);
      }

      const json: unknown = await response.json();
      return CrmCustomerSchema.parse(json);
    },

    async createCustomer(input: CreateCustomerRequest): Promise<Customer> {
      const payload = CreateCustomerRequestSchema.parse(input);

      const response = await fetch(`${config.CRM_BASE_URL}/customers`, {
        method: "POST",
        headers,
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        throw new UpstreamError(`CRM createCustomer failed with status ${response.status}`);
      }

      const json: unknown = await response.json();
      return CrmCustomerSchema.parse(json);
    }
  };
}

declare module "fastify" {
  interface FastifyInstance {
    crmClient: CrmClient;
  }
}

export async function registerCrmClient(app: FastifyInstance, config: AppConfig): Promise<void> {
  app.decorate("crmClient", buildCrmClient(config));
}
```

