# 6. Corporate integration client: `src/integrations/corporateDirectoryClient.ts`

This simulates integration with an internal corporate system.

```ts
import { Customer } from "../domain/customer.js";

export interface CorporateDirectoryClient {
  getCustomerById(id: string): Promise<Customer | null>;
}

export interface CorporateDirectoryClientConfig {
  baseUrl: string;
  apiKey: string;
}

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  public constructor(private readonly config: CorporateDirectoryClientConfig) {}

  public async getCustomerById(id: string): Promise<Customer | null> {
    const response = await fetch(`${this.config.baseUrl}/customers/${encodeURIComponent(id)}`, {
      method: "GET",
      headers: {
        "Authorization": `Bearer ${this.config.apiKey}`,
        "Accept": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate directory request failed with status ${response.status}`);
    }

    const data: unknown = await response.json();

    if (!isCustomer(data)) {
      throw new Error("Corporate directory returned invalid customer payload");
    }

    return data;
  }
}

function isCustomer(value: unknown): value is Customer {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const record = value as Record<string, unknown>;

  return (
    typeof record["id"] === "string" &&
    typeof record["email"] === "string" &&
    typeof record["fullName"] === "string" &&
    (record["department"] === undefined || typeof record["department"] === "string")
  );
}
```

