# 9. Customer route: `src/routes/customer.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../services/customerService.js";
import { CustomerResponse, ErrorResponse } from "../types/api.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function registerCustomerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get<{
    Params: { id: string };
    Reply: CustomerResponse | ErrorResponse;
  }>("/customers/:id", async (request, reply) => {
    const paramsResult = paramsSchema.safeParse(request.params);

    if (!paramsResult.success) {
      reply.code(400);
      return {
        error: "BadRequest",
        message: "Invalid customer id"
      };
    }

    const customer = await customerService.getCustomerById(paramsResult.data.id);

    if (customer === null) {
      reply.code(404);
      return {
        error: "NotFound",
        message: "Customer not found"
      };
    }

    return {
      id: customer.id,
      email: customer.email,
      fullName: customer.fullName,
      department: customer.department
    };
  });
}
```

