# 10. App factory: `src/app.ts`

Use dependency injection style for enterprise maintainability.

```ts
import Fastify, { FastifyInstance } from "fastify";
import { Env } from "./config/env.js";
import { HttpCorporateDirectoryClient } from "./integrations/corporateDirectoryClient.js";
import { registerCustomerRoutes } from "./routes/customer.js";
import { registerHealthRoutes } from "./routes/health.js";
import { CustomerService } from "./services/customerService.js";

export function buildApp(env: Env): FastifyInstance {
  const app = Fastify({
    logger: {
      level: env.LOG_LEVEL
    }
  });

  const corporateDirectoryClient = new HttpCorporateDirectoryClient({
    baseUrl: env.CORPORATE_DIRECTORY_BASE_URL,
    apiKey: env.CORPORATE_DIRECTORY_API_KEY
  });

  const customerService = new CustomerService(corporateDirectoryClient);

  app.setErrorHandler((error, _request, reply) => {
    app.log.error({ err: error }, "Unhandled error");
    reply.status(500).send({
      error: "InternalServerError",
      message: "An unexpected error occurred"
    });
  });

  void registerHealthRoutes(app);
  void registerCustomerRoutes(app, customerService);

  return app;
}
