## 2.3 Infrastructure with Entity Framework Core

### `src/EnterpriseBackend.Infrastructure/Data/AppDbContext.cs`

```csharp
using EnterpriseBackend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Data;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options)
    {
    }

    public DbSet<Customer> Customers => Set<Customer>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Customer>(entity =>
        {
            entity.ToTable("Customers");
            entity.HasKey(x => x.Id);

            entity.Property(x => x.ExternalId)
                .HasMaxLength(100)
                .IsRequired();

            entity.Property(x => x.Name)
                .HasMaxLength(200)
                .IsRequired();

            entity.Property(x => x.Email)
                .HasMaxLength(200)
                .IsRequired();

            entity.Property(x => x.CreatedUtc)
                .IsRequired();

            entity.HasIndex(x => x.ExternalId).IsUnique();
            entity.HasIndex(x => x.Email);
        });
    }
}
```

### `src/EnterpriseBackend.Infrastructure/Repositories/CustomerRepository.cs`

```csharp
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Repositories;

public class CustomerRepository : ICustomerRepository
{
    private readonly AppDbContext _dbContext;

    public CustomerRepository(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<Customer?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task<IReadOnlyList<Customer>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .ToListAsync(cancellationToken);
    }

    public async Task<Customer> CreateAsync(Customer customer, CancellationToken cancellationToken = default)
    {
        _dbContext.Customers.Add(customer);
        await _dbContext.SaveChangesAsync(cancellationToken);
        return customer;
    }
}
```

