## 5.6 Background processing with Azure Service Bus

If your backend needs async enterprise workflows, add Service Bus.

Example publisher:

### `src/EnterpriseBackend.Infrastructure/Messaging/CustomerCreatedPublisher.cs`

```csharp
using System.Text.Json;
using Azure.Messaging.ServiceBus;
using EnterpriseBackend.Domain.Entities;

namespace EnterpriseBackend.Infrastructure.Messaging;

public class CustomerCreatedPublisher
{
    private readonly ServiceBusClient _client;
    private readonly IConfiguration _configuration;

    public CustomerCreatedPublisher(ServiceBusClient client, IConfiguration configuration)
    {
        _client = client;
        _configuration = configuration;
    }

    public async Task PublishAsync(Customer customer, CancellationToken cancellationToken = default)
    {
        var queueName = _configuration["ServiceBus:CustomerCreatedQueue"];
        var sender = _client.CreateSender(queueName);

        var payload = JsonSerializer.Serialize(new
        {
            customer.Id,
            customer.ExternalId,
            customer.Name,
            customer.Email,
            customer.CreatedUtc
        });

        var message = new ServiceBusMessage(payload)
        {
            ContentType = "application/json",
            Subject = "CustomerCreated"
        };

        await sender.SendMessageAsync(message, cancellationToken);
    }
}
```

