```csharp
using Enterprise.Backend.Data;
using Enterprise.Backend.Models;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<OrderService> _logger;

    public OrderService(AppDbContext dbContext, ILogger<OrderService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<IEnumerable<Order>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Orders
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedUtc)
            .ToListAsync(cancellationToken);
    }

    public async Task<Order?> GetByIdAsync(int id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Orders
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task<Order> CreateAsync(Order order, CancellationToken cancellationToken = default)
    {
        order.CreatedUtc = DateTime.UtcNow;
        order.Status = "New";

        _dbContext.Orders.Add(order);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Created order {OrderId} for customer {CustomerName}", order.Id, order.CustomerName);

        return order;
    }

    public async Task<bool> UpdateStatusAsync(int id, string status, CancellationToken cancellationToken = default)
    {
        var order = await _dbContext.Orders.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (order == null)
        {
            return false;
        }

        order.Status = status;
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Updated order {OrderId} status to {Status}", id, status);

        return true;
    }
}
```

