# 6. Service implementation

## `OrderService.cs`

```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Repositories;

namespace EnterpriseBackend.Application.Services;

public class OrderService : IOrderService
{
    private readonly OrderRepository _orderRepository;

    public OrderService(OrderRepository orderRepository)
    {
        _orderRepository = orderRepository;
    }

    public async Task<OrderResponse> CreateOrderAsync(CreateOrderRequest request, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerName))
            throw new ArgumentException("CustomerName is required.");

        if (request.Amount <= 0)
            throw new ArgumentException("Amount must be greater than zero.");

        var order = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName.Trim(),
            Amount = request.Amount,
            CreatedUtc = DateTime.UtcNow,
            Status = "Pending"
        };

        var created = await _orderRepository.CreateAsync(order, cancellationToken);

        return new OrderResponse
        {
            Id = created.Id,
            CustomerName = created.CustomerName,
            Amount = created.Amount,
            CreatedUtc = created.CreatedUtc,
            Status = created.Status
        };
    }

    public async Task<OrderResponse?> GetOrderAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var order = await _orderRepository.GetByIdAsync(id, cancellationToken);
        if (order == null) return null;

        return new OrderResponse
        {
            Id = order.Id,
            CustomerName = order.CustomerName,
            Amount = order.Amount,
            CreatedUtc = order.CreatedUtc,
            Status = order.Status
        };
    }

    public async Task<IReadOnlyList<OrderResponse>> GetOrdersAsync(CancellationToken cancellationToken = default)
    {
        var orders = await _orderRepository.GetAllAsync(cancellationToken);

        return orders.Select(order => new OrderResponse
        {
            Id = order.Id,
            CustomerName = order.CustomerName,
            Amount = order.Amount,
            CreatedUtc = order.CreatedUtc,
            Status = order.Status
        }).ToList();
    }
}
