## Services/EmployeeService.cs

```csharp
using EnterpriseBackend.Data;
using EnterpriseBackend.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Services
{
    public class EmployeeService : IEmployeeService
    {
        private readonly AppDbContext _dbContext;
        private readonly ILogger<EmployeeService> _logger;

        public EmployeeService(AppDbContext dbContext, ILogger<EmployeeService> logger)
        {
            _dbContext = dbContext;
            _logger = logger;
        }

        public async Task<IEnumerable<Employee>> GetAllAsync(CancellationToken cancellationToken = default)
        {
            return await _dbContext.Employees
                .AsNoTracking()
                .OrderBy(e => e.LastName)
                .ThenBy(e => e.FirstName)
                .ToListAsync(cancellationToken);
        }

        public async Task<Employee?> GetByIdAsync(int id, CancellationToken cancellationToken = default)
        {
            return await _dbContext.Employees
                .AsNoTracking()
                .FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
        }

        public async Task<Employee> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken = default)
        {
            var employee = new Employee
            {
                FirstName = request.FirstName,
                LastName = request.LastName,
                Email = request.Email,
                Department = request.Department,
                CreatedUtc = DateTime.UtcNow
            };

            _dbContext.Employees.Add(employee);
            await _dbContext.SaveChangesAsync(cancellationToken);

            _logger.LogInformation("Employee created with ID {EmployeeId}", employee.Id);

            return employee;
        }

        public async Task<Employee?> UpdateAsync(int id, UpdateEmployeeRequest request, CancellationToken cancellationToken = default)
        {
            var employee = await _dbContext.Employees
                .FirstOrDefaultAsync(e => e.Id == id, cancellationToken);

            if (employee == null)
                return null;

            employee.FirstName = request.FirstName;
            employee.LastName = request.LastName;
            employee.Email = request.Email;
            employee.Department = request.Department;

            await _dbContext.SaveChangesAsync(cancellationToken);

            _logger.LogInformation("Employee updated with ID {EmployeeId}", id);

            return employee;
        }

        public async Task<bool> DeleteAsync(int id, CancellationToken cancellationToken = default)
        {
            var employee = await _dbContext.Employees
                .FirstOrDefaultAsync(e => e.Id == id, cancellationToken);

            if (employee == null)
                return false;

            _dbContext.Employees.Remove(employee);
            await _dbContext.SaveChangesAsync(cancellationToken);

            _logger.LogInformation("Employee deleted with ID {EmployeeId}", id);

            return true;
        }
    }
}
```

