## Controllers/EmployeesController.cs

```csharp
using EnterpriseBackend.Models;
using EnterpriseBackend.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class EmployeesController : ControllerBase
    {
        private readonly IEmployeeService _employeeService;

        public EmployeesController(IEmployeeService employeeService)
        {
            _employeeService = employeeService;
        }

        [HttpGet]
        [Authorize(Policy = "RequireReaderRole")]
        public async Task<ActionResult<IEnumerable<Employee>>> GetAll(CancellationToken cancellationToken)
        {
            var employees = await _employeeService.GetAllAsync(cancellationToken);
            return Ok(employees);
        }

        [HttpGet("{id:int}")]
        [Authorize(Policy = "RequireReaderRole")]
        public async Task<ActionResult<Employee>> GetById(int id, CancellationToken cancellationToken)
        {
            var employee = await _employeeService.GetByIdAsync(id, cancellationToken);

            if (employee == null)
                return NotFound();

            return Ok(employee);
        }

        [HttpPost]
        [Authorize(Policy = "RequireAdminRole")]
        public async Task<ActionResult<Employee>> Create(
            [FromBody] CreateEmployeeRequest request,
            CancellationToken cancellationToken)
        {
            var employee = await _employeeService.CreateAsync(request, cancellationToken);
            return CreatedAtAction(nameof(GetById), new { id = employee.Id }, employee);
        }

        [HttpPut("{id:int}")]
        [Authorize(Policy = "RequireAdminRole")]
        public async Task<ActionResult<Employee>> Update(
            int id,
            [FromBody] UpdateEmployeeRequest request,
            CancellationToken cancellationToken)
        {
            var employee = await _employeeService.UpdateAsync(id, request, cancellationToken);

            if (employee == null)
                return NotFound();

            return Ok(employee);
        }

        [HttpDelete("{id:int}")]
        [Authorize(Policy = "RequireAdminRole")]
        public async Task<IActionResult> Delete(int id, CancellationToken cancellationToken)
        {
            var deleted = await _employeeService.DeleteAsync(id, cancellationToken);

            if (!deleted)
                return NotFound();

            return NoContent();
        }
    }
}
