# 7. Service implementation

## `Application/Services/OrderService.cs`

```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _dbContext;
    private readonly ILogger<OrderService> _logger;

    public OrderService(AppDbContext dbContext, ILogger<OrderService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<IReadOnlyCollection<OrderDto>> GetOrdersAsync(CancellationToken cancellationToken = default)
    {
        var orders = await _dbContext.Orders
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedUtc)
            .Select(x => new OrderDto
            {
                Id = x.Id,
                CustomerName = x.CustomerName,
                Amount = x.Amount,
                CreatedUtc = x.CreatedUtc
            })
            .ToListAsync(cancellationToken);

        return orders;
    }

    public async Task<OrderDto?> GetOrderByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Orders
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new OrderDto
            {
                Id = x.Id,
                CustomerName = x.CustomerName,
                Amount = x.Amount,
                CreatedUtc = x.CreatedUtc
            })
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<OrderDto> CreateOrderAsync(CreateOrderRequest request, CancellationToken cancellationToken = default)
    {
        var entity = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName,
            Amount = request.Amount,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Orders.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Order created with id {OrderId} for customer {CustomerName}", entity.Id, entity.CustomerName);

        return new OrderDto
        {
            Id = entity.Id,
            CustomerName = entity.CustomerName,
            Amount = entity.Amount,
            CreatedUtc = entity.CreatedUtc
        };
    }
}
```

