# 9. Service layer: `Services/CustomerService.cs`

```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Services;

public class CustomerService
{
    private readonly AppDbContext _db;
    private readonly ILogger<CustomerService> _logger;

    public CustomerService(AppDbContext db, ILogger<CustomerService> logger)
    {
        _db = db;
        _logger = logger;
    }

    public async Task<List<Customer>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Customers
            .AsNoTracking()
            .OrderBy(c => c.Name)
            .ToListAsync(cancellationToken);
    }

    public async Task<Customer?> GetByIdAsync(int id, CancellationToken cancellationToken = default)
    {
        return await _db.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
    }

    public async Task<Customer> CreateAsync(Customer customer, CancellationToken cancellationToken = default)
    {
        _db.Customers.Add(customer);
        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Customer created with ID {CustomerId}", customer.Id);

        return customer;
    }

    public async Task<bool> UpdateAsync(int id, Customer updatedCustomer, CancellationToken cancellationToken = default)
    {
        var existing = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
        if (existing is null)
            return false;

        existing.Name = updatedCustomer.Name;
        existing.Email = updatedCustomer.Email;
        existing.Status = updatedCustomer.Status;

        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Customer updated with ID {CustomerId}", id);

        return true;
    }

    public async Task<bool> DeleteAsync(int id, CancellationToken cancellationToken = default)
    {
        var existing = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
        if (existing is null)
            return false;

        _db.Customers.Remove(existing);
        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Customer deleted with ID {CustomerId}", id);

        return true;
    }
}
```

