using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Models.Requests;
using Enterprise.Backend.Models.Responses;
using Enterprise.Backend.Repositories.Interfaces;
using Enterprise.Backend.Services.Interfaces;

namespace Enterprise.Backend.Services;

public class OrderService : IOrderService
{
    private readonly IOrderRepository _repository;
    private readonly ILogger<OrderService> _logger;

    public OrderService(IOrderRepository repository, ILogger<OrderService> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    public async Task<OrderResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var order = await _repository.GetByIdAsync(id, cancellationToken);
        return order is null ? null : Map(order);
    }

    public async Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var orders = await _repository.GetAllAsync(cancellationToken);
        return orders.Select(Map).ToList();
    }

    public async Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerName))
            throw new ArgumentException("CustomerName is required.");

        if (request.Amount <= 0)
            throw new ArgumentException("Amount must be greater than zero.");

        var order = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName.Trim(),
            Amount = request.Amount,
            Status = "Pending",
            CreatedUtc = DateTime.UtcNow
        };

        var created = await _repository.AddAsync(order, cancellationToken);

        _logger.LogInformation("Order created: {OrderId} for customer {CustomerName}", created.Id, created.CustomerName);

        return Map(created);
    }

    private static OrderResponse Map(Order order) =>
        new()
        {
            Id = order.Id,
            CustomerName = order.CustomerName,
            Amount = order.Amount,
            Status = order.Status,
            CreatedUtc = order.CreatedUtc
        };
}
```

