namespace Enterprise.Backend.Workers;

public class OrderCleanupWorker : BackgroundService
{
    private readonly ILogger<OrderCleanupWorker> _logger;

    public OrderCleanupWorker(ILogger<OrderCleanupWorker> logger)
    {
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("OrderCleanupWorker started.");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                _logger.LogInformation("OrderCleanupWorker heartbeat at {TimeUtc}", DateTime.UtcNow);

                // Add cleanup / archival / sync logic here
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error in OrderCleanupWorker");
            }

            await Task.Delay(TimeSpan.FromMinutes(15), stoppingToken);
        }

        _logger.LogInformation("OrderCleanupWorker stopped.");
    }
}
