```

Example service:

```csharp
using System.Text.Json;
using Azure.Messaging.ServiceBus;

namespace Enterprise.Backend.Services;

public interface IMessagePublisher
{
    Task PublishAsync<T>(string queueName, T payload, CancellationToken cancellationToken = default);
}

public class ServiceBusMessagePublisher : IMessagePublisher
{
    private readonly ServiceBusClient _client;
    private readonly ILogger<ServiceBusMessagePublisher> _logger;

    public ServiceBusMessagePublisher(ServiceBusClient client, ILogger<ServiceBusMessagePublisher> logger)
    {
        _client = client;
        _logger = logger;
    }

    public async Task PublishAsync<T>(string queueName, T payload, CancellationToken cancellationToken = default)
    {
        var sender = _client.CreateSender(queueName);
        var body = JsonSerializer.Serialize(payload);

        await sender.SendMessageAsync(new ServiceBusMessage(body), cancellationToken);

        _logger.LogInformation("Published message to queue {QueueName}", queueName);
    }
}
```

Register in `Program.cs`:

```csharp
using Azure.Messaging.ServiceBus;

builder.Services.AddSingleton(_ =>
    new ServiceBusClient(builder.Configuration["ServiceBus:NamespaceConnectionString"]));

builder.Services.AddScoped<IMessagePublisher, ServiceBusMessagePublisher>();
```

