## `Services/OrderService.cs`

```csharp
using EnterpriseBackend.Data;
using EnterpriseBackend.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _db;
    private readonly ILogger<OrderService> _logger;

    public OrderService(AppDbContext db, ILogger<OrderService> logger)
    {
        _db = db;
        _logger = logger;
    }

    public async Task<IEnumerable<Order>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Orders
            .AsNoTracking()
            .OrderByDescending(o => o.CreatedUtc)
            .ToListAsync(cancellationToken);
    }

    public async Task<Order?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.Orders
            .AsNoTracking()
            .FirstOrDefaultAsync(o => o.Id == id, cancellationToken);
    }

    public async Task<Order> CreateAsync(Order order, CancellationToken cancellationToken = default)
    {
        order.Id = Guid.NewGuid();
        order.CreatedUtc = DateTime.UtcNow;

        _db.Orders.Add(order);
        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Created order {OrderId} for customer {CustomerName}", order.Id, order.CustomerName);

        return order;
    }

    public async Task<bool> UpdateAsync(Guid id, Order order, CancellationToken cancellationToken = default)
    {
        var existing = await _db.Orders.FirstOrDefaultAsync(o => o.Id == id, cancellationToken);
        if (existing == null)
            return false;

        existing.CustomerName = order.CustomerName;
        existing.ProductCode = order.ProductCode;
        existing.Quantity = order.Quantity;
        existing.UnitPrice = order.UnitPrice;

        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Updated order {OrderId}", id);

        return true;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var existing = await _db.Orders.FirstOrDefaultAsync(o => o.Id == id, cancellationToken);
        if (existing == null)
            return false;

        _db.Orders.Remove(existing);
        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Deleted order {OrderId}", id);

        return true;
    }
}
