Example publisher service:

```csharp
using Azure.Messaging.ServiceBus;

public class OrderEventPublisher
{
    private readonly ServiceBusClient _client;
    private readonly IConfiguration _configuration;

    public OrderEventPublisher(ServiceBusClient client, IConfiguration configuration)
    {
        _client = client;
        _configuration = configuration;
    }

    public async Task PublishOrderCreatedAsync(Guid orderId, CancellationToken cancellationToken = default)
    {
        var queueName = _configuration["ServiceBus:QueueName"];
        var sender = _client.CreateSender(queueName);

        var message = new ServiceBusMessage($"{{\"orderId\":\"{orderId}\"}}");
        message.Subject = "OrderCreated";

        await sender.SendMessageAsync(message, cancellationToken);
    }
}
```

Register it:

```csharp
builder.Services.AddSingleton(_ =>
{
    var fullyQualifiedNamespace = builder.Configuration["ServiceBus:Namespace"];
    return new Azure.Messaging.ServiceBus.ServiceBusClient(
        fullyQualifiedNamespace,
        new DefaultAzureCredential());
});
```

