```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Repositories;

public class WorkItemService : IWorkItemService
{
    private readonly AppDbContext _dbContext;

    public WorkItemService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<IReadOnlyList<WorkItemResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.WorkItems
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedUtc)
            .Select(x => new WorkItemResponse
            {
                Id = x.Id,
                Title = x.Title,
                Status = x.Status,
                CreatedUtc = x.CreatedUtc,
                CreatedBy = x.CreatedBy
            })
            .ToListAsync(cancellationToken);
    }

    public async Task<WorkItemResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.WorkItems
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new WorkItemResponse
            {
                Id = x.Id,
                Title = x.Title,
                Status = x.Status,
                CreatedUtc = x.CreatedUtc,
                CreatedBy = x.CreatedBy
            })
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<WorkItemResponse> CreateAsync(CreateWorkItemRequest request, string createdBy, CancellationToken cancellationToken = default)
    {
        var entity = new WorkItem
        {
            Id = Guid.NewGuid(),
            Title = request.Title,
            Status = "New",
            CreatedUtc = DateTime.UtcNow,
            CreatedBy = createdBy
        };

        _dbContext.WorkItems.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new WorkItemResponse
        {
            Id = entity.Id,
            Title = entity.Title,
            Status = entity.Status,
