using System.Security.Claims;
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class WorkItemsController : ControllerBase
{
    private readonly IWorkItemService _workItemService;

    public WorkItemsController(IWorkItemService workItemService)
    {
        _workItemService = workItemService;
    }

    [HttpGet]
    public async Task<ActionResult<IReadOnlyList<WorkItemResponse>>> GetAll(CancellationToken cancellationToken)
    {
        var items = await _workItemService.GetAllAsync(cancellationToken);
        return Ok(items);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WorkItemResponse>> GetById(Guid id, CancellationToken cancellationToken)
    {
        var item = await _workItemService.GetByIdAsync(id, cancellationToken);

        if (item is null)
            return NotFound();

        return Ok(item);
    }

    [HttpPost]
    public async Task<ActionResult<WorkItemResponse>> Create(
        [FromBody] CreateWorkItemRequest request,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.Title))
            return BadRequest("Title is required.");

        var createdBy =
            User.FindFirstValue(ClaimTypes.Upn) ??
            User.FindFirstValue("preferred_username") ??
            User.Identity?.Name ??
            "unknown";

        var created = await _workItemService.CreateAsync(request, createdBy, cancellationToken);

        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
}
