```csharp
using Enterprise.Backend.Application.DTOs;
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Domain.Entities;

namespace Enterprise.Backend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly IEmployeeRepository _repository;

    public EmployeeService(IEmployeeRepository repository)
    {
        _repository = repository;
    }

    public async Task<IReadOnlyList<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var employees = await _repository.GetAllAsync(cancellationToken);

        return employees
            .Select(MapToDto)
            .ToList();
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetByIdAsync(id, cancellationToken);
        return employee is null ? null : MapToDto(employee);
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken = default)
    {
        var existing = await _repository.GetByEmployeeNumberAsync(request.EmployeeNumber, cancellationToken);
        if (existing is not null)
        {
            throw new InvalidOperationException($"Employee number '{request.EmployeeNumber}' already exists.");
        }

        var employee = new Employee
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = request.EmployeeNumber,
            FirstName = request.FirstName,
            LastName = request.LastName,
            Email = request.Email,
            Department = request.Department,
            CreatedUtc = DateTime.UtcNow
        };

        await _repository.AddAsync(employee, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return MapToDto(employee);
    }

    private static EmployeeDto MapToDto(Employee employee) =>
        new()
        {
            Id = employee.Id,
            EmployeeNumber = employee.EmployeeNumber,
            FirstName = employee.FirstName,
            LastName = employee.LastName,
            Email = employee.Email,
            Department = employee.Department
        };
}
```

