## `src/EnterpriseBackend.Application/Services/CustomerService.cs`

```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;

namespace EnterpriseBackend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _dbContext;

    public CustomerService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<IReadOnlyCollection<CustomerDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await Task.FromResult(
            _dbContext.Customers
                .Select(c => new CustomerDto(c.Id, c.ExternalId, c.Name, c.Email, c.CreatedUtc))
                .ToList()
                .AsReadOnly());
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var customer = await _dbContext.Customers.FindAsync(new object[] { id }, cancellationToken);
        return customer is null
            ? null
            : new CustomerDto(customer.Id, customer.ExternalId, customer.Name, customer.Email, customer.CreatedUtc);
    }

    public async Task<CustomerDto> CreateAsync(string externalId, string name, string email, CancellationToken cancellationToken = default)
    {
        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            ExternalId = externalId,
            Name = name,
            Email = email,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Customers.Add(customer);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new CustomerDto(customer.Id, customer.ExternalId, customer.Name, customer.Email, customer.CreatedUtc);
    }
}
```

> Note: In a stricter clean architecture, `Application` should not depend on `Infrastructure`. For an **initial implementation**, this is acceptable, but I’d refactor to repositories/interfaces next.

