# 6. Infrastructure layer

## `src/EnterpriseBackend.Infrastructure/Data/AppDbContext.cs`

```csharp
using EnterpriseBackend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Data;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options)
    {
    }

    public DbSet<Customer> Customers => Set<Customer>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Customer>(entity =>
        {
            entity.ToTable("Customers");
            entity.HasKey(x => x.Id);

            entity.Property(x => x.ExternalId)
                .HasMaxLength(100)
                .IsRequired();

            entity.Property(x => x.Name)
                .HasMaxLength(200)
                .IsRequired();

            entity.Property(x => x.Email)
                .HasMaxLength(320)
                .IsRequired();

            entity.Property(x => x.CreatedUtc)
                .IsRequired();

            entity.HasIndex(x => x.ExternalId).IsUnique();
            entity.HasIndex(x => x.Email);
        });
    }
}
```

## `src/EnterpriseBackend.Infrastructure/DependencyInjection.cs`

```csharp
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Application.Services;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace EnterpriseBackend.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddInfrastructure(this IServiceCollection services, IConfiguration configuration)
    {
        var connectionString = configuration.GetConnectionString("SqlDatabase")
                               ?? throw new InvalidOperationException("Connection string 'SqlDatabase' not found.");

        services.AddDbContext<AppDbContext>(options =>
            options.UseSqlServer(connectionString));

        services.AddScoped<ICustomerService, CustomerService>();

        return services;
    }
}
```

