## 5.5 Application service implementation

**`src/EnterpriseBackend.Application/Services/CustomerService.cs`**
```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _dbContext;

    public CustomerService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<CustomerResponse> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken = default)
    {
        var existing = await _dbContext.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.ExternalId == request.ExternalId, cancellationToken);

        if (existing is not null)
        {
            throw new InvalidOperationException($"Customer with ExternalId '{request.ExternalId}' already exists.");
        }

        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            ExternalId = request.ExternalId,
            Name = request.Name,
            Email = request.Email,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Customers.Add(customer);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new CustomerResponse
        {
            Id = customer.Id,
            ExternalId = customer.ExternalId,
            Name = customer.Name,
            Email = customer.Email,
            CreatedUtc = customer.CreatedUtc
        };
    }

    public async Task<CustomerResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var customer = await _dbContext.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);

        if (customer is null)
        {
            return null;
        }

        return new CustomerResponse
        {
            Id = customer.Id,
            ExternalId = customer.ExternalId,
            Name = customer.Name,
            Email = customer.Email,
            CreatedUtc = customer.CreatedUtc
        };
    }

    public async Task<IReadOnlyList<CustomerResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .Select(customer => new CustomerResponse
            {
                Id = customer.Id,
                ExternalId = customer.ExternalId,
                Name = customer.Name,
                Email = customer.Email,
                CreatedUtc = customer.CreatedUtc
            })
            .ToListAsync(cancellationToken);
    }
}
```

