    {
        return await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .Select(x => new CustomerDto(x.Id, x.ExternalId, x.Name, x.Email, x.CreatedUtc))
            .ToListAsync(cancellationToken);
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new CustomerDto(x.Id, x.ExternalId, x.Name, x.Email, x.CreatedUtc))
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<CustomerDto> CreateAsync(string externalId, string name, string email, CancellationToken cancellationToken = default)
    {
        var entity = new Customer
        {
            Id = Guid.NewGuid(),
            ExternalId = externalId,
            Name = name,
            Email = email,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Customers.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new CustomerDto(entity.Id, entity.ExternalId, entity.Name, entity.Email, entity.CreatedUtc);
    }
