# Database migration setup

Add EF tools package to Infrastructure or a dedicated migrations project.

Example command:

```bash
dotnet ef migrations add InitialCreate \
  --project src/EnterpriseBackend.Infrastructure \
  --startup-project src/EnterpriseBackend.Api
```

Then:

```bash
dotnet ef database update \
  --project src/EnterpriseBackend.Infrastructure \
  --startup-project src/EnterpriseBackend.Api
```

You may also want a design-time factory.

### `src/EnterpriseBackend.Infrastructure/Data/AppDbContextFactory.cs`

```csharp
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Design;
using Microsoft.Extensions.Configuration;

namespace EnterpriseBackend.Infrastructure.Data;

public class AppDbContextFactory : IDesignTimeDbContextFactory<AppDbContext>
{
    public AppDbContext CreateDbContext(string[] args)
    {
        var configuration = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddJsonFile("appsettings.json", optional: true)
            .AddJsonFile("appsettings.Development.json", optional: true)
            .AddEnvironmentVariables()
            .Build();

        var optionsBuilder = new DbContextOptionsBuilder<AppDbContext>();
        var connectionString = configuration.GetConnectionString("SqlDatabase")
                              ?? "Server=(localdb)\\mssqllocaldb;Database=EnterpriseBackendDb;Trusted_Connection=True;";

        optionsBuilder.UseSqlServer(connectionString);

        return new AppDbContext(optionsBuilder.Options);
    }
}
```

