# 5. Infrastructure layer

## EF Core DbContext

**src/Enterprise.Backend.Infrastructure/Persistence/EnterpriseDbContext.cs**

```csharp
using Enterprise.Backend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Infrastructure.Persistence;

public class EnterpriseDbContext : DbContext
{
    public EnterpriseDbContext(DbContextOptions<EnterpriseDbContext> options)
        : base(options)
    {
    }

    public DbSet<Customer> Customers => Set<Customer>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<Customer>(entity =>
        {
            entity.ToTable("Customers");
            entity.HasKey(x => x.Id);

            entity.Property(x => x.ExternalId)
                .IsRequired()
                .HasMaxLength(100);

            entity.HasIndex(x => x.ExternalId)
                .IsUnique();

            entity.Property(x => x.Name)
                .IsRequired()
                .HasMaxLength(200);

            entity.Property(x => x.Email)
                .IsRequired()
                .HasMaxLength(320);

            entity.Property(x => x.CreatedUtc)
                .IsRequired();
        });
    }
}
```

## Service implementation

**src/Enterprise.Backend.Infrastructure/Services/CustomerService.cs**

```csharp
using Enterprise.Backend.Application.Customers;
using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Infrastructure.Services;

public class CustomerService : ICustomerService
{
    private readonly EnterpriseDbContext _dbContext;

    public CustomerService(EnterpriseDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<IReadOnlyCollection<CustomerDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .Select(x => new CustomerDto(
                x.Id,
                x.ExternalId,
                x.Name,
                x.Email,
                x.CreatedUtc))
            .ToListAsync(cancellationToken);
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new CustomerDto(
                x.Id,
                x.ExternalId,
                x.Name,
                x.Email,
                x.CreatedUtc))
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken = default)
    {
        var existing = await _dbContext.Customers
            .AnyAsync(x => x.ExternalId == request.ExternalId, cancellationToken);

        if (existing)
            throw new InvalidOperationException($"Customer with ExternalId '{request.ExternalId}' already exists.");

        var customer = new Customer(request.ExternalId, request.Name, request.Email);

        _dbContext.Customers.Add(customer);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new CustomerDto(
            customer.Id,
            customer.ExternalId,
            customer.Name,
            customer.Email,
            customer.CreatedUtc);
    }
}
```

