# 4. API project: Program.cs

This is the core initial implementation.

```csharp
using Azure.Identity;
using EnterpriseBackend.Application.Customers;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Identity.Web;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

var builder = WebApplication.CreateBuilder(args);

var configuration = builder.Configuration;
var services = builder.Services;
var environment = builder.Environment;

// Azure App Configuration / Key Vault
builder.Configuration.AddEnvironmentVariables();

if (!environment.IsDevelopment())
{
    var keyVaultName = configuration["KeyVault:Name"];
    if (!string.IsNullOrWhiteSpace(keyVaultName))
    {
        var keyVaultUri = new Uri($"https://{keyVaultName}.vault.azure.net/");
        builder.Configuration.AddAzureKeyVault(keyVaultUri, new DefaultAzureCredential());
    }
}

// Controllers + API behavior
services.AddControllers();
services.AddProblemDetails();

// API versioning could be added here if needed
services.AddEndpointsApiExplorer();
services.AddSwaggerGen();

// Authentication with Entra ID
services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddMicrosoftIdentityWebApi(configuration.GetSection("AzureAd"));

services.AddAuthorization(options =>
{
    options.AddPolicy("CustomerRead", policy =>
        policy.RequireClaim("roles", "Customer.Read", "Customer.Admin"));

    options.AddPolicy("CustomerWrite", policy =>
        policy.RequireClaim("roles", "Customer.Write", "Customer.Admin"));
});

// SQL Server / Azure SQL
services.AddDbContext<AppDbContext>(options =>
{
    options.UseSqlServer(configuration.GetConnectionString("DefaultConnection"));
});

// Application services
services.AddScoped<ICustomerService, CustomerService>();

// Health checks
services.AddHealthChecks()
    .AddDbContextCheck<AppDbContext>();

// OpenTelemetry
services.AddOpenTelemetry()
    .WithTracing(tracing =>
    {
        tracing
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("EnterpriseBackend.Api"))
            .AddAspNetCoreInstrumentation()
            .AddHttpClientInstrumentation()
            .AddEntityFrameworkCoreInstrumentation();
    });

var app = builder.Build();

// Global exception handling
app.UseExceptionHandler(exceptionApp =>
{
    exceptionApp.Run(async context =>
    {
        var feature = context.Features.Get<IExceptionHandlerFeature>();
        var exception = feature?.Error;

        var problem = new ProblemDetails
        {
            Title = "An unexpected error occurred.",
            Status = StatusCodes.Status500InternalServerError,
            Detail = environment.IsDevelopment() ? exception?.ToString() : null
        };

        context.Response.StatusCode = 500;
        await context.Response.WriteAsJsonAsync(problem);
    });
});

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();

app.UseAuthentication();
app.UseAuthorization();

app.MapHealthChecks("/health");
app.MapControllers();

app.Run();
```

