using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using EnterpriseBackend.Data;
using EnterpriseBackend.Models;

namespace EnterpriseBackend.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class CustomersController : ControllerBase
    {
        private readonly AppDbContext _db;
        private readonly ILogger<CustomersController> _logger;

        public CustomersController(AppDbContext db, ILogger<CustomersController> logger)
        {
            _db = db;
            _logger = logger;
        }

        [HttpGet]
        public async Task<ActionResult<IEnumerable<Customer>>> Get()
        {
            _logger.LogInformation("Fetching customers");
            var customers = await _db.Customers.AsNoTracking().ToListAsync();
            return Ok(customers);
        }

        [HttpPost]
        public async Task<ActionResult<Customer>> Post(Customer customer)
        {
            if (!ModelState.IsValid)
                return ValidationProblem(ModelState);

            _db.Customers.Add(customer);
            await _db.SaveChangesAsync();

            _logger.LogInformation("Created customer {CustomerId}", customer.Id);

            return CreatedAtAction(nameof(Get), new { id = customer.Id }, customer);
        }
    }
}
