# 9. Optional SQL connectivity test endpoint

If you want a minimal SQL Server connectivity check, add this controller.

## `Controllers/DatabaseController.cs`

```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;

namespace EnterpriseBackend.Controllers;

[ApiController]
[Route("api/[controller]")]
public class DatabaseController : ControllerBase
{
    private readonly IConfiguration _configuration;
    private readonly ILogger<DatabaseController> _logger;

    public DatabaseController(IConfiguration configuration, ILogger<DatabaseController> logger)
    {
        _configuration = configuration;
        _logger = logger;
    }

    [HttpGet("check")]
    [Authorize]
    public async Task<IActionResult> Check()
    {
        var connectionString = _configuration.GetConnectionString("DefaultConnection");

        if (string.IsNullOrWhiteSpace(connectionString))
        {
            return StatusCode(500, new { error = "Connection string not configured" });
        }

        try
        {
            await using var connection = new SqlConnection(connectionString);
            await connection.OpenAsync();

            await using var command = new SqlCommand("SELECT GETUTCDATE()", connection);
            var result = await command.ExecuteScalarAsync();

            return Ok(new
            {
                database = "connected",
                serverUtcTime = result
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Database connectivity check failed");
            return StatusCode(500, new
            {
                database = "failed",
                error = ex.Message
            });
        }
    }
}
```

