### `src/main.rs`

```rust
use axum::{
    extract::State,
    http::{HeaderValue, StatusCode},
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde_json::json;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Instant,
};
use tokio::net::TcpListener;
use tracing::{error, info};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
    start_time: Instant,
}

async fn health() -> impl IntoResponse {
    (StatusCode::OK, "OK")
}

async fn json_handler(State(state): State<AppState>) -> impl IntoResponse {
    let count = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;

    let body = Json(json!({
        "message": "hello",
        "request_count": count
    }));

    let mut response = body.into_response();
    response.headers_mut().insert(
        "content-type",
        HeaderValue::from_static("application/json"),
    );
    response
}

async fn metrics(State(state): State<AppState>) -> impl IntoResponse {
    let uptime = state.start_time.elapsed().as_secs();
    let requests = state.request_count.load(Ordering::Relaxed);

    Json(json!({
        "uptime_seconds": uptime,
        "total_requests": requests
    }))
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
        start_time: Instant::now(),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/json", get(json_handler))
        .route("/metrics", get(metrics))
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();

    info!("starting server on {}", addr);

    let listener = TcpListener::bind(addr).await.unwrap();

    if let Err(err) = axum::serve(listener, app).await {
        error!("server error: {}", err);
    }
}
```

