use std::{convert::Infallible, net::SocketAddr, sync::Arc};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

type RespBody = Full<Bytes>;

#[derive(Clone)]
struct AppState {
    message: Arc<String>,
}

async fn handle_request(
    req: Request<Incoming>,
    state: AppState,
) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => {
            Response::new(Full::new(Bytes::from(format!(
                "OK: {}\n",
                state.message
            ))))
        }
        (&Method::GET, "/health") => {
            Response::new(Full::new(Bytes::from("healthy\n")))
        }
        (&Method::GET, "/ping") => {
            Response::new(Full::new(Bytes::from("pong\n")))
        }
        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from("not found\n")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    Ok(response)
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;

    let state = AppState {
        message: Arc::new("high-performance server".to_string()),
    };

    println!("Listening on http://{}", addr);

    loop {
        let (stream, _) = listener.accept().await?;
        let io = TokioIo::new(stream);
        let state = state.clone();

        tokio::spawn(async move {
            let service = service_fn(move |req| {
                let state = state.clone();
                async move { handle_request(req, state).await }
            });

            if let Err(err) = http1::Builder::new()
                .keep_alive(true)
                .serve_connection(io, service)
                .await
            {
                eprintln!("connection error: {}", err);
            }
        });
    }
}
```

