```rust
use std::{convert::Infallible, net::SocketAddr};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::header::{CONTENT_TYPE, SERVER};
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::{TokioExecutor, TokioIo};
use serde_json::json;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

fn response_with_status(
    status: StatusCode,
    body: impl Into<Bytes>,
    content_type: &'static str,
) -> Response<RespBody> {
    Response::builder()
        .status(status)
        .header(CONTENT_TYPE, content_type)
        .header(SERVER, "high-perf-rust-server")
        .body(Full::new(body.into()))
        .unwrap()
}

async fn router(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => {
            response_with_status(
                StatusCode::OK,
                "Hello from a high-performance Rust server\n",
                "text/plain; charset=utf-8",
            )
        }

        (&Method::GET, "/health") => {
            response_with_status(
                StatusCode::OK,
                r#"{"status":"ok"}"#,
                "application/json",
            )
        }

        (&Method::GET, "/json") => {
            let payload = json!({
                "message": "fast response",
                "success": true
            });

            response_with_status(
                StatusCode::OK,
                payload.to_string(),
                "application/json",
            )
        }

        _ => {
            response_with_status(
                StatusCode::NOT_FOUND,
                "Not Found\n",
                "text/plain; charset=utf-8",
            )
        }
    };

    Ok(response)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    let shutdown = shutdown_signal();

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            biased;

            _ = &mut shutdown => {
                println!("Shutdown signal received");
                break;
            }

            accept_result = listener.accept() => {
                let (stream, _peer) = match accept_result {
                    Ok(v) => v,
                    Err(err) => {
                        eprintln!("accept error: {}", err);
                        continue;
                    }
                };

                tokio::spawn(async move {
                    let io = TokioIo::new(stream);

                    let conn = hyper::server::conn::http1::Builder::new()
                        .keep_alive(true)
                        .serve_connection(io, service_fn(router));

                    if let Err(err) = conn.await {
                        eprintln!("connection error: {}", err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};

        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

