use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{SystemTime, UNIX_EPOCH},
};
use tokio::signal;
use tracing::{info, Level};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
    started_at: u64,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    uptime_seconds: u64,
    total_requests: u64,
}

#[derive(Serialize)]
struct HelloResponse {
    message: &'static str,
    request_number: u64,
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    let now = now_unix();
    let uptime = now.saturating_sub(state.started_at);
    let total_requests = state.request_count.load(Ordering::Relaxed);

    let body = HealthResponse {
        status: "ok",
        uptime_seconds: uptime,
        total_requests,
    };

    (StatusCode::OK, Json(body))
}

async fn hello(State(state): State<AppState>) -> impl IntoResponse {
    let req_num = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;

    let body = HelloResponse {
        message: "Hello, world!",
        request_number: req_num,
    };

    (StatusCode::OK, Json(body))
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .with_env_filter("info")
        .init();

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
        started_at: now_unix(),
    };

    let app = Router::new()
        .route("/", get(hello))
        .route("/health", get(health))
        .with_state(state);

    let port = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse::<u16>().ok())
        .unwrap_or(8080);

    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    info!("starting server on {}", addr);
    info!("logical CPUs: {}", num_cpus::get());

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind address");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}
