## Important fix

The `#[tokio::main(worker_threads = 0)]` line should be changed, because `0` is not valid for Tokio worker threads.

Use this instead:

```rust
fn main() {
    let worker_threads = num_cpus::get().max(2);

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(worker_threads)
        .enable_all()
        .build()
        .expect("failed to build Tokio runtime");

    runtime.block_on(async_main(worker_threads));
}

async fn async_main(worker_threads: usize) {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    info!("starting server with {} worker threads", worker_threads);

    let state = AppState {
        start_time: Instant::now(),
        request_count: Arc::new(AtomicU64::new(0)),
    };

    let app = Router::new()
        .route("/", get(root))
        .route("/health", get(health))
        .route("/hello", get(hello))
        .with_state(state);

    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    info!("listening on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind address");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");
}
```

