use std::{convert::Infallible, net::SocketAddr, sync::Arc};

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[derive(Clone)]
struct AppState {
    hello_response: Arc<Bytes>,
    health_response: Arc<Bytes>,
}

async fn handler(
    req: Request<Incoming>,
    state: AppState,
) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => Response::new(Full::new((*state.hello_response).clone())),
        (&Method::GET, "/health") => Response::new(Full::new((*state.health_response).clone())),
        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from_static(b"Not Found")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    Ok(response)
}

#[tokio::main(worker_threads = 0)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let workers = num_cpus::get().max(1);

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(workers)
        .enable_all()
        .build()?;

    runtime.block_on(async move {
        let addr: SocketAddr = "0.0.0.0:8080".parse()?;

        let state = AppState {
            hello_response: Arc::new(Bytes::from_static(b"Hello, world!")),
            health_response: Arc::new(Bytes::from_static(b"OK")),
        };

        let listener = TcpListener::bind(addr).await?;
        println!("Listening on http://{}", addr);
        println!("Worker threads: {}", workers);

        loop {
            tokio::select! {
                accept_result = listener.accept() => {
                    let (stream, _) = match accept_result {
                        Ok(v) => v,
                        Err(e) => {
                            eprintln!("accept error: {}", e);
                            continue;
                        }
                    };

                    let io = TokioIo::new(stream);
                    let state_clone = state.clone();

                    tokio::spawn(async move {
                        let service = service_fn(move |req| {
                            handler(req, state_clone.clone())
                        });

                        if let Err(err) = hyper::server::conn::http1::Builder::new()
                            .keep_alive(true)
                            .serve_connection(io, service)
                            .await
                        {
                            eprintln!("connection error: {}", err);
                        }
                    });
                }

                _ = shutdown_signal() => {
                    println!("Shutdown signal received");
                    break;
                }
            }
        }

        Ok::<(), Box<dyn std::error::Error + Send + Sync>>(())
    })?;

    Ok(())
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
