use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::signal;
use tower::ServiceBuilder;
use tower_http::{timeout::TimeoutLayer, trace::TraceLayer};
use tracing::{error, info};

#[derive(Clone)]
struct AppState {
    request_counter: Arc<AtomicU64>,
    started_at_unix: u64,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    uptime_seconds: u64,
    total_requests_seen: u64,
}

#[derive(Serialize)]
struct MessageResponse {
    message: &'static str,
    request_number: u64,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    init_tracing();

    let started_at_unix = now_unix();
    let state = AppState {
        request_counter: Arc::new(AtomicU64::new(0)),
        started_at_unix,
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/hello", get(hello))
        .route("/", get(root))
        .with_state(state)
        .layer(
            ServiceBuilder::new()
                .layer(TraceLayer::new_for_http())
                .layer(TimeoutLayer::new(Duration::from_secs(10))),
        );

    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    info!("starting server on {}", addr);
    info!("logical CPUs available: {}", num_cpus::get());

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind TCP listener");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .unwrap_or_else(|err| {
            error!("server error: {}", err);
        });
}

async fn root() -> impl IntoResponse {
    (StatusCode::OK, "high-performance server is running")
}

async fn hello(State(state): State<AppState>) -> impl IntoResponse {
    let req_num = state.request_counter.fetch_add(1, Ordering::Relaxed) + 1;

    let body = MessageResponse {
        message: "hello, world",
        request_number: req_num,
    };

    (StatusCode::OK, Json(body))
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    let total = state.request_counter.load(Ordering::Relaxed);
    let uptime = now_unix().saturating_sub(state.started_at_unix);

    let body = HealthResponse {
        status: "ok",
        uptime_seconds: uptime,
        total_requests_seen: total,
    };

    (StatusCode::OK, Json(body))
}

fn init_tracing() {
    let filter = std::env::var("RUST_LOG")
        .unwrap_or_else(|_| "info,tower_http=info".to_string());

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};

        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("received Ctrl+C, shutting down");
        }
        _ = terminate => {
            info!("received SIGTERM, shutting down");
        }
    }
}
