```rust
use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::time::Instant;

use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
    start_time: Instant,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
        start_time: Instant::now(),
    };

    println!("Server listening on http://{}", addr);

    let shutdown = shutdown_signal();

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            biased;

            _ = &mut shutdown => {
                println!("Shutdown signal received");
                break;
            }

            accept_result = listener.accept() => {
                let (stream, remote_addr) = match accept_result {
                    Ok(v) => v,
                    Err(err) => {
                        eprintln!("Accept error: {}", err);
                        continue;
                    }
                };

                let io = TokioIo::new(stream);
                let state = state.clone();

                tokio::spawn(async move {
                    let service = service_fn(move |req: Request<Incoming>| {
                        let state = state.clone();
                        async move { handle_request(req, state, remote_addr).await }
                    });

                    if let Err(err) = hyper::server::conn::http1::Builder::new()
                        .keep_alive(true)
                        .serve_connection(io, service)
                        .await
                    {
                        eprintln!("Connection error ({}): {}", remote_addr, err);
                    }
                });
            }
        }
    }

    println!("Server shut down cleanly");
    Ok(())
}

async fn handle_request(
    req: Request<Incoming>,
    state: AppState,
    remote_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let request_id = state.request_count.fetch_add(1, Ordering::Relaxed) + 1;
    let method = req.method().clone();
    let path = req.uri().path().to_string();

    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => text_response(
            StatusCode::OK,
            "high-performance server is running\n",
        ),
        (&Method::GET, "/health") => text_response(StatusCode::OK, "OK\n"),
        (&Method::GET, "/metrics") => {
            let uptime_secs = state.start_time.elapsed().as_secs();
            let total_requests = state.request_count.load(Ordering::Relaxed);

            let body = format!(
                "uptime_seconds {}\nrequests_total {}\n",
                uptime_secs, total_requests
            );

            text_response(StatusCode::OK, &body)
        }
        _ => text_response(StatusCode::NOT_FOUND, "Not Found\n"),
    };

    println!(
        "[{}] {} {} {} -> {}",
        request_id,
        remote_addr,
        method,
        path,
        response.status()
    );

    Ok(response)
}

fn text_response(status: StatusCode, body: &str) -> Response<RespBody> {
    Response::builder()
        .status(status)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(body.to_owned())))
        .unwrap()
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};

        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
