use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Instant,
};
use tokio::signal;
use tower_http::{
    compression::CompressionLayer,
    trace::TraceLayer,
};
use tracing::{info, Level};
use tracing_subscriber::EnvFilter;

#[derive(Clone)]
struct AppState {
    started_at: Instant,
    request_count: Arc<AtomicU64>,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
    uptime_seconds: u64,
    total_requests: u64,
}

#[derive(Serialize)]
struct MessageResponse {
    message: &'static str,
    worker_threads: usize,
}

#[tokio::main(flavor = "multi_thread", worker_threads = 0)]
async fn main() {
    init_tracing();

    let worker_threads = num_cpus::get();
    info!("starting server with {} worker threads", worker_threads);

    let state = AppState {
        started_at: Instant::now(),
        request_count: Arc::new(AtomicU64::new(0)),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/", get(index))
        .route("/metrics", get(metrics))
        .with_state(state)
        .layer(CompressionLayer::new())
        .layer(TraceLayer::new_for_http());

    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    info!("listening on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("failed to bind TCP listener");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");
}

fn init_tracing() {
    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new("info"));

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

async fn index(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let response = MessageResponse {
        message: "high-performance server is running",
        worker_threads: num_cpus::get(),
    };

    (StatusCode::OK, Json(response))
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let response = HealthResponse {
        status: "ok",
        uptime_seconds: state.started_at.elapsed().as_secs(),
        total_requests: state.request_count.load(Ordering::Relaxed),
    };

    (StatusCode::OK, Json(response))
}

async fn metrics(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let body = format!(
        concat!(
            "# HELP app_requests_total Total number of handled requests\n",
            "# TYPE app_requests_total counter\n",
            "app_requests_total {}\n",
            "# HELP app_uptime_seconds Application uptime in seconds\n",
            "# TYPE app_uptime_seconds gauge\n",
            "app_uptime_seconds {}\n"
        ),
        state.request_count.load(Ordering::Relaxed),
        state.started_at.elapsed().as_secs()
    );

    (StatusCode::OK, body)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("failed to install signal handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}
```

